            ["RougeTalkActorType"] = 1,
            ["SpeakNpcName"] = "StoryNPC_Flynn",
            },
        [6201519] = {
            ["Content"] = "我……只是习惯了而已。",
            ["ContentJP"] = "私は......ただ慣れただけだ。",
            ["DialogueId"] = 6201519,
            ["GUID"] = "0F865CB6",
            ["NextDialogue"] = 6201527,
            ["RougeTalkActorType"] = 2,
            },
        [6201520] = {
            ["Content"] = "青年脸上的惊讶慢慢转变为钦佩。\
“那么……您是如何看待深渊的呢？您认为，人类会战胜它吗？”",
            ["ContentJP"] = "青年の驚いた顔に、感服した表情が浮かんだ。\
「では......あなたはどう思いますか？人類は深淵に勝てると思いますか？」",
            ["DialogueId"] = 6201520,
            ["GUID"] = "0F865CE0",
            ["NextOptions"] = {
                [1] = 6201521,
