        [6201603] = {
            ["Content"] = "“卡莉斯塔……？”",
            ["ContentJP"] = "「カリスタ......？」",
            ["DialogueId"] = 6201603,
            ["GUID"] = "0F866A7E",
            ["NextDialogue"] = 6201604,
