            },
        [6202023] = {
            ["Content"] = "你翻到了笔记的最后一页。",
            ["ContentJP"] = "日記の最後の一ページをめくる。",
            ["DialogueId"] = 6202023,
            ["GUID"] = "0F86AF66",
