        [10011702] = {
            ["Camera"] = "112.41748,326.53125,131.15976,0.001058,1.609964,-59.853107,35.0,100000.0,true,DoNotOverride,2.8",
            ["Content"] = "士兵们真的尽力了，岛上的秽兽群的确是预料外的状况。但是今天并不算一无所获。",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>の群れに出くわすとは想定外でして......ですが、成果もありますよ。",
            ["DialogueId"] = 10011702,
            ["DisableMouth"] = 1,
            ["Duration"] = 7.6,
            ["GUID"] = "191030DC",
            ["SpeakNpcId"] = 100006,
            ["VoiceName"] = "voice/$Locale$/story/1001/100117/191030DC",
            },
        [10011703] = {
            ["Content"] = "我们在这儿找到了她使用过的炼金设施，还有一艘有军团编号的飞艇……",
            ["ContentJP"] = "彼女が使っていた錬金施設と、軍団番号つきの飛行船を発見しました……",
            ["DialogueId"] = 10011703,
            ["DisableMouth"] = 1,
            ["Duration"] = 5.4,
            ["GUID"] = "19103106",
            ["SpeakNpcId"] = 100006,
            ["VoiceName"] = "voice/$Locale$/story/1001/100117/19103106",
            },
        [10011704] = {
            ["Camera"] = "126.422852,269.644531,140.342804,0.001063,-0.790492,125.942245,35.0,100000.0,true,DoNotOverride,2.8",
            ["Content"] = "你应该知道我们找的是“零号”，不是这堆破铜烂铁！",
            ["ContentJP"] = "私たちが探しているのは「No.0」よ？こんなガラクタじゃないわ！",
            ["DialogueId"] = 10011704,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "19103130",
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100117/19103130",
            },
        [10011705] = {
            ["Content"] = "十几年过去了，确实比较困难……不过，海上分队已经拦截了逃亡村民的船只，说不定能问出什——",
            ["ContentJP"] = "長期にわたる各地の捜査もそろそろ限界ですが……そうそう、村人の船を捕らえたので、何か聞きだせるかも――",
            ["DialogueId"] = 10011705,
            ["DisableMouth"] = 1,
            ["Duration"] = 9.5,
            ["GUID"] = "1910315A",
            ["SpeakNpcId"] = 100006,
            ["VoiceName"] = "voice/$Locale$/story/1001/100117/1910315A",
            },
        [10011706] = {
            ["Content"] = "枪声？",
            ["ContentJP"] = "銃声？",
            ["DialogueId"] = 10011706,
            ["DisableMouth"] = 1,
            ["Duration"] = 1,
            ["GUID"] = "191031AE",
            ["SpeakNpcId"] = 100006,
            ["VoiceName"] = "voice/$Locale$/story/1001/100117/191031AE",
            },
        [10011707] = {
            ["Camera"] = "18.672363,118.146484,149.783295,0.001118,-3.591033,6.145676,35.0,100000.0,true,DoNotOverride,2.8",
            ["Content"] = "……兰迪。",
            ["ContentJP"] = "ランディー。",
            ["DialogueId"] = 10011707,
            ["DisableMouth"] = 1,
            ["Duration"] = 1,
            ["GUID"] = "191031D8",
