                },
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100119/191052D2",
            },
        [10011911] = {
            ["Content"] = "想起来……{nickname}，你必须想起来……",
            ["ContentJP"] = "思い出すのだ……{nickname}、思い出さねばならない……",
            ["DialogueId"] = 10011911,
            ["Duration"] = 4.5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191052D3",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1001/100119/191052D3",
            },
        [10011912] = {
            ["Content"] = "你的力量……和鸣之力……",
            ["ContentJP"] = "お前の……レゾナンスを……",
            ["DialogueId"] = 10011912,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191052D4",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1001/100119/191052D4",
            },
        [10011913] = {
            ["Content"] = "如果你渴望拯救这一切……",
            ["ContentJP"] = "すべてを救いたいのならば……",
            ["DialogueId"] = 10011913,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191052D5",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1001/100119/191052D5",
            },
        [10012001] = {
            ["Content"] = "再坚持一下！马上就……",
            ["ContentJP"] = "頑張って！すぐに……",
            ["DefaultLookAt"] = "Self",
            ["DialogueId"] = 10012001,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["GUID"] = "191061EA",
            ["LookAt"] = {
                [1] = "100005:n(100003)",
                },
            ["RelatedWikiId"] = {
                [1] = 408001,
                [2] = 201001,
                [3] = 201002,
                },
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191061EA",
            },
        [10012002] = {
            ["Content"] = "贝蕾！",
            ["ContentJP"] = "ベレ！",
            ["DialogueId"] = 10012002,
            ["DisableMouth"] = 1,
            ["Duration"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191061EB",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191061EB",
            },
        [10012003] = {
            ["Content"] = "停手吧，零号。再坚硬的兵刃，也会有折断的一刻。",
            ["ContentJP"] = "諦めなさい。どんなに硬い刃も、いつかは折れるものよ。",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012003,
            ["DisableMouth"] = 1,
            ["Duration"] = 4.5,
            ["GUID"] = "19106214",
            ["LookAt"] = {
                [1] = "100005:n(100003)",
                },
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/19106214",
            },
        [10012004] = {
            ["Content"] = "跟我回去。你会活着——你在乎的那个{性别：少年|小姑娘}也一样。",
            ["ContentJP"] = "私と共に帰れば、お前もそのチビも命は助かるわ。",
            ["DialogueId"] = 10012004,
            ["DisableMouth"] = 1,
            ["Duration"] = 5.5,
            ["GUID"] = "19106218",
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/19106218",
            },
        [10012005] = {
            ["Content"] = "否则，{性别：他|她}的性命就——",
            ["ContentJP"] = "さもないと、そいつの命は――",
            ["DialogueId"] = 10012005,
            ["DisableMouth"] = 1,
            ["Duration"] = 3.5,
            ["GUID"] = "19106219",
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/19106219",
            },
        [10012006] = {
            ["Content"] = "……给我承诺。",
            ["ContentJP"] = "……約束して。",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012006,
            ["DisableMouth"] = 1,
            ["Duration"] = 1.7,
            ["GUID"] = "1910623E",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/1910623E",
            },
        [10012007] = {
            ["Content"] = "嗯？",
            ["ContentJP"] = "何を？",
            ["DialogueId"] = 10012007,
            ["DisableMouth"] = 1,
            ["Duration"] = 1,
            ["GUID"] = "1910623F",
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/1910623F",
            },
        [10012008] = {
            ["Content"] = "我跟你回去，你放{性别：他|她}走。",
            ["ContentJP"] = "私が行く代わりにこの子は見逃して。",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012008,
            ["DisableMouth"] = 1,
            ["Duration"] = 4,
            ["GUID"] = "19106268",
            ["LookAt"] = {
                [1] = "100007:n(100005)",
                },
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/19106268",
            },
        [10012009] = {
            ["Content"] = "说啊！否则你就带着我们两个的尸骸回去！",
            ["ContentJP"] = "約束しないなら私たちの死体を持ち帰るのね！",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012009,
            ["DisableMouth"] = 1,
            ["Duration"] = 3.5,
            ["GUID"] = "19106292",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/19106292",
            },
        [10012010] = {
            ["Content"] = "你误会了。这不是谈判，是命令。",
            ["ContentJP"] = "誤解しているみたいだけど、これは「交渉」じゃなくて、「命令」なのよ。",
            ["DefaultLookAt"] = "Self",
            ["DialogueId"] = 10012010,
            ["DisableMouth"] = 1,
            ["Duration"] = 5.5,
            ["GUID"] = "190F7C64",
            ["LookAt"] = {
                [1] = "100005:n(100005)",
                },
            ["SpeakNpcId"] = 100005,
            ["VoiceName"] = "voice/$Locale$/story/1001/100106/190F7C64",
            },
        [10012011] = {
            ["Content"] = "……贝蕾。",
            ["ContentJP"] = "……ベレ。",
            ["DefaultLookAt"] = "KeepState",
            ["DialogueId"] = 10012011,
            ["DisableMouth"] = 1,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191062E6",
            ["LookAt"] = {
                [1] = "100005:n(100003)",
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062E6",
            },
        [10012012] = {
            ["Content"] = "……？！你……！",
            ["ContentJP"] = "……？！ダメ……！",
            ["DialogueId"] = 10012012,
            ["DisableMouth"] = 1,
            ["Duration"] = 1,
            ["GUID"] = "191062E7",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062E7",
            },
        [10012013] = {
            ["Content"] = "要逃出去。",
            ["ContentJP"] = "逃げて。",
            ["DialogueId"] = 10012013,
            ["DisableMouth"] = 1,
            ["Duration"] = 1.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191062E8",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062E8",
            },
        [10012014] = {
            ["Content"] = "不——！！",
            ["ContentJP"] = "いやあぁぁ――――！！",
            ["DialogueId"] = 10012014,
            ["DisableMouth"] = 1,
            ["Duration"] = 1.5,
            ["GUID"] = "191062E9",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062E9",
            },
        [10012015] = {
            ["Content"] = "{nickname}，我来考考你。“眨眼三次”这个暗号——",
            ["ContentJP"] = "{nickname}、テストするよ。「まばたき3回」の合図は――",
            ["DialogueId"] = 10012015,
            ["Duration"] = 5,
            ["GUID"] = "191062F0",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062F0",
            },
        [10012016] = {
            ["Content"] = "用不着贝蕾提醒，我早记住啦！眨眼三次的意思是……",
            ["ContentJP"] = "心配性だねベレは。もう覚えたよ！まばたき3回の意味は……",
            ["DialogueId"] = 10012016,
            ["Duration"] = 6,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191062F1",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062F1",
            },
        [10012017] = {
            ["Content"] = "“即使只剩一个人，你也要坚强地活下去。”",
            ["ContentJP"] = "「たとえひとりになっても、強く生きる」",
            ["DialogueId"] = 10012017,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191062F2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062F2",
            },
        [10012018] = {
            ["Content"] = "“直到我们再次相逢。”",
            ["ContentJP"] = "{性别:「僕たちが、また会う日まで」|「私たちが、また会う日まで」}",
            ["DialogueId"] = 10012018,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191062F3",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100120/191062F3",
            },
        [10012101] = {
            ["Content"] = "那是……",
            ["ContentJP"] = "その力は……？",
            ["DialogueId"] = 10012101,
            ["Duration"] = 1.5,
            ["GUID"] = "19107252",
