        [10017801] = {
            ["Content"] = "......",
            ["DialogueId"] = 10017801,
            ["Duration"] = 1,
            ["GUID"] = "1914197A",
            ["RelatedWikiId"] = {
                [1] = 408001,
                [2] = 201001,
                [3] = 303001,
                [4] = 401001,
                [5] = 403001,
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/100178/1914197A",
            },
        [10017901] = {
            ["Content"] = "飞艇在山顶。稍微修整一下，就继续往上走吧。",
            ["ContentJP"] = "飛行船は山頂にあるはず。少し休んだら、また登ろうか。",
            ["DialogueId"] = 10017901,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["GUID"] = "191429E2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/191429E2",
            },
        [10017902] = {
            ["Content"] = "……这么快，就要和净界岛告别了。",
            ["ContentJP"] = "……こんなに早く、この島を出ることになるなんて。",
            ["DialogueId"] = 10017902,
            ["DisableMouth"] = 1,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19142A0C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/19142A0C",
            },
        [10017903] = {
            ["Content"] = "……真是片刻也不让人清净。",
            ["ContentJP"] = "……チッ、少しぐらい、休ませてよ。",
            ["DialogueId"] = 10017903,
            ["DisableMouth"] = 1,
            ["Duration"] = 5.5,
            ["GUID"] = "19142A0D",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100179/19142A0D",
            },
        [10018001] = {
            ["Content"] = "走。",
            ["DialogueId"] = 10018001,
            ["Duration"] = 2,
            ["GUID"] = "19143A4A",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100180/19143A4A",
            },
        [10018101] = {
            ["DialogueId"] = 10018101,
            ["Duration"] = 1,
            ["GUID"] = "19144AB2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100181/19144AB2",
            },
        [10018201] = {
            ["Content"] = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
            ["DialogueId"] = 10018201,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 13,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19145B1A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100182/19145B1A",
            },
        [10018202] = {
            ["Content"] = "第一次，我感受到了，我是如此真实地活着。",
            ["DialogueId"] = 10018202,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 7,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19145B44",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100182/19145B44",
            },
        [10018301] = {
            ["Content"] = "下坠。我本应朝着漆黑的深渊下坠。",
            ["DialogueId"] = 10018301,
            ["Duration"] = 2.5,
            ["GUID"] = "19146B82",
            ["NextDialogue"] = 10018302,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146B82",
            },
        [10018302] = {
            ["Content"] = "但，我却感觉自己在晨雾的怀抱里飘浮。",
            ["DialogueId"] = 10018302,
            ["Duration"] = 2.5,
            ["GUID"] = "19146BAC",
            ["NextDialogue"] = 10018303,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146BAC",
            },
        [10018303] = {
            ["Content"] = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
            ["DialogueId"] = 10018303,
            ["Duration"] = 4,
            ["GUID"] = "19146BD6",
            ["NextDialogue"] = 10018304,
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146BD6",
            },
        [10018304] = {
            ["Content"] = "而是一种，奇特的触感……亲切，甚至令人怀念。",
            ["DialogueId"] = 10018304,
            ["Duration"] = 3,
            ["GUID"] = "19146C00",
            ["VoiceName"] = "voice/$Locale$/story/1001/100183/19146C00",
            },
        [10018401] = {
            ["Content"] = "回答我的，只有不尽流泻的无垠白沙；以及……",
            ["ContentJP"] = "答えてくれたのは、無限に流れる白い砂と……そして……",
            ["DialogueId"] = 10018401,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19147BEA",
            ["NextDialogue"] = 10018402,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100184/19147BEA",
            },
        [10018402] = {
            ["Content"] = "{性别：她|他}。",
            ["ContentJP"] = "{性别:彼女|彼}。",
            ["DialogueId"] = 10018402,
            ["Duration"] = 1.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19147C14",
            ["SnapShot"] = "HEART",
