            ["DialogueId"] = 10018501,
            ["GUID"] = "19148C52",
            ["VoiceName"] = "voice/$Locale$/story/1001/100185/19148C52",
            },
        [10018601] = {
            ["Content"] = "不要……",
            ["ContentJP"] = "だめ……",
            ["DialogueId"] = 10018601,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19149CBA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100186/19149CBA",
            },
        [10018602] = {
            ["Content"] = "不要……把……她……",
            ["ContentJP"] = "だめ……ベレ……を――",
            ["DialogueId"] = 10018602,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19149CE4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100186/19149CE4",
            },
        [10018603] = {
            ["Content"] = "滚开。",
            ["DialogueId"] = 10018603,
            ["Duration"] = 2,
            ["GUID"] = "19144AB3",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100181/19144AB3",
            },
        [10018701] = {
            ["Content"] = "——“我是谁？”",
            ["ContentJP"] = "{性别:――“僕は誰？”|――“私は誰？”}",
            ["DialogueId"] = 10018701,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
