            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1001/100109/190FAD9E",
            },
        [10019001] = {
            ["Content"] = "村子里什么人声都没有，恐怕他们已经……",
            ["ContentJP"] = "村には誰もいないみたい。多分、みんなもう……",
            ["DialogueId"] = 10019001,
            ["Duration"] = 1.8,
            ["GUID"] = "1914DE5A",
            ["NextDialogue"] = 10019002,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DE5A",
            },
        [10019002] = {
            ["Content"] = "……！！",
            ["ContentJP"] = "……！！",
            ["DialogueId"] = 10019002,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DE84",
            ["NextDialogue"] = 10019003,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DE84",
            },
        [10019003] = {
            ["Content"] = "……我的意思是，他们大多应该乘船逃走了。",
            ["ContentJP"] = "……そんな顔しないで。みんなは船で逃げ出したんでしょうね、って意味。",
            ["DialogueId"] = 10019003,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEAE",
            ["NextDialogue"] = 10019004,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEAE",
            },
        [10019004] = {
            ["Content"] = "抓紧回家拿到武器，然后去码头吧。这里现在还很危险。",
            ["ContentJP"] = "ここは危険だから、急いで家に戻って武器を回収しないとね。そしたら桟橋まで行ってみよう。",
            ["DialogueId"] = 10019004,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEAF",
            ["NextDialogue"] = 10019005,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEAF",
            },
        [10019005] = {
            ["Content"] = "（……我们现在赤手空拳，得尽量避开秽兽。）",
            ["ContentJP"] = "（{性别:今の僕たちは武器を持っていないし……<Default note=\"text:エジュウ\">穢獣</>に見つからないようにしないと|今の私たちは武器を持っていないし……<Default note=\"text:エジュウ\">穢獣</>に見つからないようにしないと}）",
            ["DialogueId"] = 10019005,
            ["Duration"] = 2.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914DEB1",
            ["NextDialogue"] = 10019006,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB1",
            },
        [10019006] = {
            ["Content"] = "还差一点……家就在前面了。",
            ["ContentJP"] = "家はこの先……もう少しだよ。",
            ["DialogueId"] = 10019006,
            ["Duration"] = 2.5,
            ["GUID"] = "1914DEB2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100190/1914DEB2",
            },
        [10019007] = {
            ["Content"] = "（……我们现在赤手空拳，得尽量避开秽兽。）",
            ["ContentJP"] = "（{性别:今の僕たちは武器を持っていないし……<Default note=\"text:エジュウ\">穢獣</>に見つからないようにしないと|今の私たちは武器を持っていないし……<Default note=\"text:エジュウ\">穢獣</>に見つからないようにしないと}）",
