            },
        [10019101] = {
            ["Content"] = "想起▇▇……▇▇，你必须▇▇▇……",
            ["ContentJP"] = "思い▇▇▇▇……▇▇▇▇▇、▇▇出さねばならない……",
            ["DialogueId"] = 10019101,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1914EEC2",
            ["RelatedWikiId"] = {
                [1] = 304001,
