                },
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EEC2",
            },
        [10019102] = {
            ["Content"] = "你的▇▇……▇▇之力……",
            ["ContentJP"] = "お前の……▇▇▇▇▇を……",
            ["DialogueId"] = 10019102,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1914EEEC",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EEEC",
            },
        [10019103] = {
            ["Content"] = "▇▇▇渴望▇▇……这一切……",
            ["ContentJP"] = "すべてを▇▇▇▇ならば……",
            ["DialogueId"] = 10019103,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
