            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EF16",
            },
        [10019104] = {
            ["Content"] = "你在说什么……",
            ["ContentJP"] = "一体、何を言って……",
            ["DialogueId"] = 10019104,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914EF17",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100191/1914EF17",
            },
        [10019201] = {
            ["Content"] = "关于那柄剑……除了它从小就在身边之外，我一无所知。",
            ["DialogueId"] = 10019201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914FF2A",
            ["NextDialogue"] = 10019202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100192/1914FF2A",
            },
        [10019202] = {
            ["Content"] = "正如我不知道自己从何而来——我没有与贝蕾相遇之前的任何记忆。",
            ["DialogueId"] = 10019202,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914FF54",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100192/1914FF54",
            },
        [10019301] = {
            ["Content"] = "秽兽没完没了的……",
            ["ContentJP"] = "倒しても倒してもキリがない……",
            ["DialogueId"] = 10019301,
            ["Duration"] = 3.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19150F92",
            ["NextDialogue"] = 10019302,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100193/19150F92",
            },
        [10019302] = {
            ["Content"] = "向上跑。甩掉它们。",
            ["ContentJP"] = "走りながら、できるだけ振り切ろう。",
            ["DialogueId"] = 10019302,
            ["Duration"] = 4,
            ["GUID"] = "19150FBC",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100193/19150FBC",
            },
        [10019401] = {
            ["Content"] = "这是我第一次来科赛托斯省。看来，这里的待客之道颇为独特啊。",
            ["ContentJP"] = "コキュートスに来るのは初めてだが、当地のもてなしはかなり独特なのだな。",
            ["DialogueId"] = 10019401,
            ["Duration"] = 8,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19151FFA",
            ["RelatedWikiId"] = {
                [1] = 408002,
                },
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/19151FFA",
            },
        [10019402] = {
            ["Content"] = "我没有任何恶意，只是想同你做一笔……小小的交易。",
            ["ContentJP"] = "ああ、悪気はないんだ。ただ……少し取引をしたいだけだ。",
            ["DialogueId"] = 10019402,
            ["Duration"] = 5.3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19152024",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/19152024",
            },
        [10019403] = {
            ["Content"] = "我会付给你无法拒绝的报酬，而你要做的，非常简单。",
            ["ContentJP"] = "聞けば断れないぐらいの報酬は用意するつもりだ。非常にシンプルな頼みごとなのだが……引き受けてはくれないかね。",
            ["DialogueId"] = 10019403,
            ["Duration"] = 6.9,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915204E",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100194/1915204E",
            },
        [10019501] = {
            ["Content"] = "？？？：不杀了{性别：他|她}吗？",
            ["DialogueId"] = 10019501,
            ["Duration"] = 2.5,
            ["GUID"] = "19153057.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153057",
            },
        [10019502] = {
            ["Content"] = "？？？：{性别：他|她}和您一样，拥有决定历史轨迹的力量。不要忘记，您的使命。",
            ["DialogueId"] = 10019502,
            ["Duration"] = 9,
            ["GUID"] = "19153058.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153058",
            },
        [10019503] = {
            ["Content"] = "？？？：我会处理。但，现在还不是时候。",
            ["DialogueId"] = 10019503,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153059.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153059",
            },
        [10019504] = {
            ["Content"] = "？？？：收到。将如实提交您的答复。",
            ["DialogueId"] = 10019504,
            ["Duration"] = 5,
            ["GUID"] = "19153060.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153060",
            },
        [10019505] = {
            ["Content"] = "？？？：……听着，{NickName}。",
            ["DialogueId"] = 10019505,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153061.0",
            ["SpeakNpcId"] = 100012,
