            },
        [10019506] = {
            ["Content"] = "？？？：“生命是航行在无尽长夜里的孤船。”",
            ["DialogueId"] = 10019506,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "19153062.0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/19153062",
            },
        [10019507] = {
            ["Content"] = "？？？：“河流泪水满溢，夹岸荆棘丛生。”",
            ["DialogueId"] = 10019507,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915308C",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/1915308C",
            },
        [10019508] = {
            ["Content"] = "？？？：“我会一直注视着……”",
            ["DialogueId"] = 10019508,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191530B6",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/191530B6",
            },
        [10019509] = {
            ["Content"] = "？？？：“来自彼岸之人，你将驶向何方。”",
            ["DialogueId"] = 10019509,
            ["Duration"] = 5,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "191530E0",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/191530E0",
            },
        [10019510] = {
            ["Content"] = "（是谁……）",
            ["DialogueId"] = 10019510,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1915310A",
            ["SpeakNpcId"] = 100012,
            ["VoiceName"] = "voice/$Locale$/story/1001/100195/1915310A",
            },
        [10025701] = {
            ["Content"] = "这场逃亡，是从那场奇异的梦开始的；从小到大，我一直重复着相似的梦。",
            ["ContentJP"] = "この奇妙な夢が、逃避行の始まりの合図だった。\
幼い頃から、ずっと似たような夢を見てきたけれど……",
            ["DialogueId"] = 10025701,
            ["Duration"] = 3,
            ["GUID"] = "19192992",
            ["NextDialogue"] = 10025702,
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/19192992",
            },
        [10025702] = {
            ["Content"] = "但不容回想，我知道此刻有更急迫的事——",
            ["ContentJP"] = "今はそれどころじゃない。",
            ["DialogueId"] = 10025702,
            ["Duration"] = 3,
            ["GUID"] = "191929BC",
            ["NextDialogue"] = 10025703,
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/191929BC",
            },
        [10025703] = {
            ["Content"] = "必须和贝蕾妮卡一起逃离这座叫做“净界岛”的小岛，即使这是我们一起长大的地方。",
            ["ContentJP"] = "この「パーガトリー島」から、逃げ出さなければ。\
小さい頃からベレニカと一緒に育った島だけど――",
            ["DialogueId"] = 10025703,
            ["Duration"] = 4,
            ["GUID"] = "191929E6",
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/191929E6",
            },
        [10025704] = {
            ["Content"] = "因为我们平静的生活，早已被秽兽的利爪撕碎……",
            ["ContentJP"] = "平穏な日常は、<Default note=\"text:エジュウ\">穢獣</>の爪で引き裂かれてしまった……",
            ["DialogueId"] = 10025704,
            ["Duration"] = 3,
            ["GUID"] = "19192A10",
            ["VoiceName"] = "voice/$Locale$/story/1002/100257/19192A10",
            },
        [10025801] = {
            ["Content"] = "这些秽兽……死了？",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>が……死んでいる？",
            ["DialogueId"] = 10025801,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191939FA",
            ["NextDialogue"] = 10025802,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/191939FA",
            },
        [10025802] = {
            ["Content"] = "看来在我们之前，这里就有人和秽兽战斗过。而且，还没过去太久。",
            ["ContentJP"] = "私たちより先に誰かがここで<Default note=\"text:エジュウ\">穢獣</>と戦っていたみたいね。そんなに時間は経っていない。",
            ["DialogueId"] = 10025802,
            ["GUID"] = "19193A24",
            ["NextDialogue"] = 10025803,
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A24",
            },
        [10025803] = {
            ["Content"] = "难道有村民逃到了这里……不，那扇门是我们打开的才对。",
            ["ContentJP"] = "{性别:村の人がここに逃げ込んで来たのかな？でも、僕たちが来るまで扉は閉じていたはず……|村の人がここに逃げ込んで来たのかな？でも、私たちが来るまで扉は閉じていたはず……}",
            ["DialogueId"] = 10025803,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193A4E",
            ["NextDialogue"] = 10025804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A4E",
            },
        [10025804] = {
            ["Content"] = "不过好在有他帮忙清理，否则秽兽就更难对付了。",
            ["ContentJP"] = "なんにせよ<Default note=\"text:エジュウ\">穢獣</>を倒してくれたのは助かるね。立て続けに戦うのは厳しいし。",
            ["DialogueId"] = 10025804,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193A78",
            ["NextDialogue"] = 10025805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193A78",
            },
        [10025805] = {
            ["Content"] = "无论是谁，他的实力都不容小觑。我们也要留心。",
            ["ContentJP"] = "誰かはわからないけど、実力は申し分なさそう。私たちも用心しておかないと。",
            ["DialogueId"] = 10025805,
            ["GUID"] = "19193AA2",
            ["SpeakNpcId"] = 100003,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193AA2",
            },
        [10025806] = {
            ["Content"] = "这些秽兽……断气了？",
            ["ContentJP"] = "穢獣が……死んでいる？",
            ["DialogueId"] = 10025806,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19193AA3",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1001/100258/19193AA3",
            },
        [10027501] = {
            ["Content"] = "在不远处……",
            ["ContentJP"] = "付近にて",
            ["DialogueId"] = 10027501,
            ["Duration"] = 2,
            ["GUID"] = "191A50E2",
            ["VoiceName"] = "voice/$Locale$/story/1001/100275/191A50E2",
            },
        [10029301] = {
            ["Content"] = "无数次，螺旋般往复的梦中，我一遍又一遍地问着。",
            ["ContentJP"] = "螺旋のように巡り回る夢の中で、何度も問いかけた。",
            ["DialogueId"] = 10029301,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1914AD4C",
            ["NextDialogue"] = 10018401,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/100293/1914AD4C",
            },
        [10029309] = {
            ["Content"] = "恭喜你起名完成啦！！！！！",
            ["DialogueId"] = 10029309,
            ["Duration"] = 3,
            ["GUID"] = "1914AD4D",
            ["VoiceName"] = "voice/$Locale$/story/1002/100293/",
            },
        [10029401] = {
            ["Content"] = "要再休息一会儿吗？",
            ["ContentJP"] = "もう少し休むの？",
            ["DialogueId"] = 10029401,
            ["GUID"] = "1914AD4E",
            ["SpeakNpcId"] = 100003,
            },
        [10030101] = {
            ["Content"] = "呼…呼…",
            ["ContentJP"] = "はぁ……はぁ……",
            ["DialogueId"] = 10030101,
            ["Duration"] = 3,
            ["GUID"] = "191BFB72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100301/191BFB72",
            },
        [10030201] = {
            ["DialogueId"] = 10030201,
            ["Duration"] = 3,
            ["GUID"] = "191C0BDA",
            ["VoiceName"] = "voice/$Locale$/story/1003/100302/191C0BDA",
            },
        [10030202] = {
            ["Content"] = "打开推理小游戏",
            ["DialogueId"] = 10030202,
            ["GUID"] = "191C0BDB",
            },
        [10030301] = {
            ["Camera"] = "-229.695435,48.554688,189.588501,0.000025,-8.400114,39.796463,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……卡米拉？",
            ["ContentJP"] = "……カミラさん？",
            ["DialogueId"] = 10030301,
            ["GUID"] = "191C1C42",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100303/191C1C42",
            },
        [10030302] = {
            ["Content"] = "嘴里的药，先咽下去。",
            ["ContentJP"] = "先に薬を飲み込んでから話しなさい。",
            ["DialogueId"] = 10030302,
            ["GUID"] = "191C1C6C",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100303/191C1C6C",
            },
        [10030401] = {
            ["Camera"] = "67.060974,63.269043,215.128113,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
            ["Content"] = "你……我这是……",
            ["ContentJP"] = "カミラさん…ここは……",
            ["DialogueId"] = 10030401,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["FinalCamera"] = "58.562622,72.381348,205.739349,0.000134,-36.998093,133.003891,35.000015,115.415909,false,Manual,2.8",
            ["GUID"] = "191C2CAA",
            ["LookAt"] = {
                [1] = "100001:n(200003)",
                [2] = "200003:n(100001)",
                },
            ["NextDialogue"] = 10030402,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2CAA",
            },
        [10030402] = {
            ["Camera"] = "86.758911,282.283203,92.856476,0.000175,5.190773,-113.187576,35.000011,284.956726,false,Manual,2.8",
            ["Content"] = "睡了五天，运气不错。再多一天，这辈子可能都醒不过来了。",
            ["ContentJP"] = "5日間も寝てたのよ。運が良かったわね。明日までに目を覚まさなかったら、一生寝たきりだったかもしれないわ。",
            ["DialogueId"] = 10030402,
            ["FinalCamera"] = "86.758911,282.283203,92.856476,0.00018,11.790866,-114.790039,35.000011,284.956726,false,Manual,2.8",
            ["GUID"] = "191C2CD4",
            ["NextDialogue"] = 10030403,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2CD4",
            },
        [10030403] = {
            ["Camera"] = "86.758911,282.283203,92.856476,0.000164,14.190912,-114.991394,35.000008,284.956726,false,Manual,2.8",
            ["Content"] = "所以，这些天是你在……谢……",
            ["ContentJP"] = "ってことは、カミラさんがずっと世話を……ありがとう……",
            ["DialogueId"] = 10030403,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191C2CFE",
            ["NextDialogue"] = 10030404,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2CFE",
            },
        [10030404] = {
            ["Camera"] = "68.587265,188.526855,131.323135,0.000194,3.19883,-111.220688,35.000015,153.176254,false,Manual,2.8",
            ["Content"] = "不用谢我。你现在可今非昔比了，因为上次群星绮晶的事，现在可有不少委托指名让你去呢。",
            ["ContentJP"] = "礼なんて結構よ。群星のジェムの件で、あなたを指名した依頼が殺到してるわ。まったく見違えたものね。",
            ["DialogueId"] = 10030404,
            ["FinalCamera"] = "68.587265,188.526855,131.323135,0.000192,7.598797,-111.820282,35.000015,153.176254,false,Manual,2.8",
            ["GUID"] = "191C2D28",
            ["NextDialogue"] = 10030405,
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2D28",
            },
        [10030405] = {
            ["Camera"] = "98.511124,-16.412109,172.841675,0.000205,-11.603302,130.15361,35.000019,202.161392,false,Manual,2.8",
            ["Content"] = "可别活还没干完，人先没了。",
            ["ContentJP"] = "まだ仕事が残ってるんだから、簡単に死ぬんじゃないよ。",
            ["DialogueId"] = 10030405,
            ["GUID"] = "191C2D52",
            ["NextOptions"] = {
                [1] = 10030406,
                [2] = 10030408,
                },
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2D52",
            },
        [10030406] = {
            ["Content"] = "卡米拉女士真是嘴硬心软。",
            ["ContentJP"] = "口ではそう言ってるけど、本当は心配だったんでしょ。",
            ["DialogueId"] = 10030406,
            ["GUID"] = "191C2D7C",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10030407,
            },
        [10030407] = {
            ["Camera"] = "42.419052,245.519531,108.856918,0.000246,12.994878,-104.423546,35.000015,203.457535,false,Manual,2.8",
            ["Content"] = "油嘴滑舌。跟奥特赛德学的？",
            ["ContentJP"] = "随分口が達者になって……アウトサイダーに悪知恵でも吹き込まれたのかしら？",
            ["DialogueId"] = 10030407,
            ["GUID"] = "191C2DA6",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                },
            ["NextDialogue"] = 10030411,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2DA6",
            },
        [10030408] = {
            ["Content"] = "……要不，还是让我死一会儿？",
            ["ContentJP"] = "……ええと、もう少し寝込んでた方が良かったかも？",
            ["DialogueId"] = 10030408,
            ["GUID"] = "191C2DD0",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10030409,
            },
        [10030409] = {
            ["Camera"] = "42.419052,245.519531,108.856918,0.000246,12.994892,-104.423515,35.000015,243.87735,false,Manual,2.8",
            ["Content"] = "呵，现在后悔被我救下也来不及了。",
            ["ContentJP"] = "ふっ、今更後悔しても遅いわよ。",
            ["DialogueId"] = 10030409,
            ["GUID"] = "191C2DFA",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                },
            ["NextDialogue"] = 10030411,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2DFA",
            },
        [10030410] = {
            ["Camera"] = "236.477112,-183.054688,160.382812,0.000109,-10.003269,137.977005,25.0,142.250885,false,DoNotOverride,3.0",
            ["DialogueId"] = 10030410,
            ["DialoguePanelType"] = "None",
            ["GUID"] = "191C2E24",
            ["NextOptions"] = {
                [1] = 10030601,
                [2] = 10030602,
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2E24",
            },
        [10030411] = {
            ["Camera"] = "166.64328,-62.497559,178.52565,0.000175,-8.403386,136.948242,35.000011,142.834564,false,Manual,22.0",
            ["Content"] = "对了，有个人来看了你几次——黎瑟·费西尔，卫戍部队的军官。",
            ["ContentJP"] = "そうだ、何度か見舞いに来た子がいたわ――名は確かリズム・フィッシャー、警備部隊の士官よ。",
            ["DialogueId"] = 10030411,
            ["GUID"] = "191C2E4E",
            ["LookAt"] = {
                [1] = "200003:n(200003)",
                },
            ["NextDialogue"] = 10030412,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{1.7},TargetPosition{\"80.631256,-105.42334,178.525864,0.000194,-10.203278,115.354225,35.000015,142.834564,false,Manual,22.0\"},duration{1.3}},\
SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Think_End\"},Duration{1.5}},\
MoveTo{ActorId{200003},TargetPoint{\"kami_01_turnleft\"},MoveSpeed{90},Visibility{\"Show\"}}\
}\
}",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2E4E",
            },
        [10030412] = {
            ["Content"] = "我是第六军团下属，科赛托斯行省卫戍部队准尉，黎瑟·费西尔。",
            ["ContentJP"] = "私は第六軍団所属、コキュートス領警備部隊准尉、リズム・フィッシャーです。",
            ["DialogueId"] = 10030412,
            ["GUID"] = "191C2E78",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030412.T_Story_Recall_10030412'",
            ["NextDialogue"] = 10030413,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2E78",
            },
        [10030413] = {
            ["Content"] = "她托我带个话，说有事想找你聊聊。",
            ["ContentJP"] = "彼女から伝言を預かってるわ。あなたと話したいことがあるんだって。",
            ["DialogueId"] = 10030413,
            ["GUID"] = "191C2EA2",
            ["NextOptions"] = {
                [1] = 10030414,
                [2] = 10030415,
                },
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2EA2",
            },
        [10030414] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 10030414,
            ["GUID"] = "191C2ECC",
            ["NextDialogue"] = 10030416,
            },
        [10030415] = {
            ["Content"] = "我跟她没什么好谈的。",
            ["ContentJP"] = "特に話すことなんてないけど。",
            ["DialogueId"] = 10030415,
            ["GUID"] = "191C2EF6",
            ["NextDialogue"] = 10030416,
            },
        [10030416] = {
            ["Camera"] = "17.873657,-44.469727,169.63678,-0.00131,-21.59972,96.626923,35.000008,39.151329,false,DoNotOverride,22",
            ["Content"] = "那晚泪湖边上的事，我听说了，我知道你多半不想见她。",
            ["ContentJP"] = "あの晩のダクリ湖でのこと、聞いたわ。彼女に会いたくないのは分かる。",
            ["DialogueId"] = 10030416,
            ["GUID"] = "191C2F20",
            ["NextDialogue"] = 10030417,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2F20",
            },
        [10030417] = {
            ["Camera"] = "406.211243,-635.881592,325.041443,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
            ["Content"] = "但你是那夜<H>袭击事件</>中唯一活下来的，我想她不会轻易放弃。",
            ["ContentJP"] = "けど、あの<H>襲撃事件</>の生存者はあなただけよ。彼女がそう簡単に諦めるとは思えないわ。",
            ["DialogueId"] = 10030417,
            ["FinalCamera"] = "391.624817,-609.80957,316.13501,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
            ["GUID"] = "191C2F4A",
            ["NextDialogue"] = 10030418,
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2F4A",
            },
        [10030418] = {
            ["Camera"] = "13.79155,51.50293,147.848907,0.000202,-3.803739,102.358437,35.000019,112.939484,false,Manual,22.0",
            ["Content"] = "唯一活下来的？",
            ["ContentJP"] = "{性别:僕|私}だけ……？",
            ["DialogueId"] = 10030418,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "191C2F74",
            ["NextDialogue"] = 10030419,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2F74",
            },
        [10030419] = {
            ["Camera"] = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
            ["Content"] = "时间差不多了。",
            ["ContentJP"] = "そろそろ時間だわ。",
            ["DialogueId"] = 10030419,
            ["GUID"] = "191C2F9E",
            ["NextDialogue"] = 10030422,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2F9E",
            },
        [10030420] = {
            ["Camera"] = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
            ["DialogueId"] = 10030420,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "80.489944,-105.125,178.525864,0.000199,-12.403227,110.153175,35.000015,290.266602,false,Manual,22.0",
            ["GUID"] = "191C2FC9",
            ["Scripts"] = "MoveTo{ActorId{200003},TargetPoint{\"kami_01_leave\"},MoveSpeed{90},Visibility{\"Show\"}}",
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            },
        [10030421] = {
            ["Content"] = "慰问品七七八八地堆放着，似乎是这几天很多人陆续送来的。\
仔细一看，里面有不知名的野花，虽然冷掉但依旧闻起来美味的肉汤，带划痕但精美的八音盒，画着小鸟的一罐棉花糖……\
除了这些以外，还有一份没有署名，系着歪扭蝴蝶结的朴素礼盒，打开以后发现里面是一瓶帝国最顶尖的止痛剂。这份关怀的心虽是好的，但送给一名昏迷人士止痛剂，实在是没什么意义了。",
            ["ContentJP"] = "お見舞い品が所狭しと積まれている。ここ数日、見舞いの者が大勢来ていたようだ。\
名も知らぬ花や冷めてしまっても香ばしい肉スープ、傷だらけだが精巧なオルゴール、小鳥の絵が描かれた綿菓子の缶……\
中には、名の記されていない少し歪んだリボンが結ばれた質素な贈り物が混ざっていた。開けてみると、帝国で最高級の鎮痛剤が一本入っている。気持ちはありがたいが、気絶状態の者に鎮痛剤を贈るのは、どう考えても意味がない。",
            ["DialogueId"] = 10030421,
            ["GUID"] = "191C2FF2",
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2FF2",
            },
        [10030422] = {
            ["Camera"] = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
            ["Content"] = "还想知道什么，就去水仙平原问你的朋友吧。这几天他们也很挂念你。",
            ["ContentJP"] = "他の質問は、アスフォデロスにいる友人たちに聞きなさい。この数日間、あなたのことを随分心配していたわ。",
            ["DialogueId"] = 10030422,
            ["GUID"] = "191C2FC8",
            ["NextDialogue"] = 10030420,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1003/100304/191C2FC8",
            },
        [10030501] = {
            ["Content"] = "（咦，冰湖城多了好多气球……最近是什么节日吗？）",
            ["ContentJP"] = "（空に風船がたくさん浮いてる……何か祭りでもあるのかな？）",
            ["DialogueId"] = 10030501,
            ["DisableMouth"] = 1,
            ["GUID"] = "191C3D12",
            ["NextDialogue"] = 10030502,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3D12",
            },
        [10030502] = {
            ["Content"] = "（但这么热闹的装饰，也盖不住空气里的冷清……）",
            ["ContentJP"] = "（賑やかな装飾があっても、街に漂うわびしさは隠しきれない……）",
            ["DialogueId"] = 10030502,
            ["DisableMouth"] = 1,
            ["GUID"] = "191C3D3C",
            ["NextDialogue"] = 10030503,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3D3C",
            },
        [10030503] = {
            ["Content"] = "（去找奥特赛德和白了解下昏迷这几天的情况吧。）",
            ["ContentJP"] = "（まずはアウトサイダーとスノウを探して、ここ数日の状況を聞いてみよう。）",
            ["DialogueId"] = 10030503,
            ["DisableMouth"] = 1,
            ["GUID"] = "191C3D66",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3D66",
            },
        [10030504] = {
            ["Content"] = "13个人，13个人！一夜之间！",
            ["ContentJP"] = "13人！たった一晩で13人だぞ！",
            ["DialogueId"] = 10030504,
            ["Duration"] = 5,
            ["GUID"] = "191C3D90",
            ["SpeakNpcId"] = 700036,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3D90",
            },
        [10030505] = {
            ["Content"] = "躲在家里也不安全，我们到底该怎么办……",
            ["ContentJP"] = "家にいても安全は保証されないなんて……これからどうすればいいの……",
            ["DialogueId"] = 10030505,
            ["Duration"] = 7,
            ["GUID"] = "191C3DBA",
            ["SpeakNpcId"] = 700038,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3DBA",
            },
        [10030506] = {
            ["Content"] = "唉，一把老骨头了，总不能为这事搬家吧……",
            ["ContentJP"] = "はぁ……この老いぼれに引っ越しなどとても無理じゃ……",
            ["DialogueId"] = 10030506,
            ["Duration"] = 7,
            ["GUID"] = "191C3DE4",
            ["SpeakNpcId"] = 700246,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3DE4",
            },
        [10030507] = {
            ["Content"] = "演员在八音盒内旋转，我们在冰湖城中徘徊！转折将要发生，雾海欢迎来客！",
            ["ContentJP"] = "オルゴールで踊る俳優、アイスレイク城を彷徨う我ら……転機はもう目の前だ。ようこそ、ニヴルヘイムへ！",
            ["DialogueId"] = 10030507,
            ["Duration"] = 12,
            ["GUID"] = "191C3E0E",
            ["SpeakNpcId"] = 700015,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3E0E",
            },
        [10030508] = {
            ["Content"] = "别，别过来，不要杀我……卫戍部队，卫戍部队在哪里？！",
            ["ContentJP"] = "来…来るな！殺さないでくれ……警備隊！警備隊はどこだ？！",
            ["DialogueId"] = 10030508,
            ["Duration"] = 9,
            ["GUID"] = "191C3E38",
            ["SpeakNpcId"] = 700035,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3E38",
            },
        [10030509] = {
            ["Content"] = "怪物，绝对是怪物干的……",
            ["ContentJP"] = "化け物だ……化け物の仕業に違いない……",
            ["DialogueId"] = 10030509,
            ["Duration"] = 4,
            ["GUID"] = "191C3E62",
            ["SpeakNpcId"] = 700034,
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3E62",
            },
        [10030510] = {
            ["Content"] = "冰湖城外城近日发生多起恶性伤人事件，手段极其残忍，现场极为混乱，请广大市民减少深夜外出，锁好门窗。\
持有武器许可证的市民如果遭遇行凶者，不要试图反击（这很危险！！！），优先保全自身性命。\
如有凶手线索，请立即联系卫戍部队，黎瑟·费西尔。\
皇帝会庇护他忠诚的子民度过难关，荣耀尽归吾皇。",
            ["ContentJP"] = "近日、アイスレイク城の外城区で残忍な傷害事件が多発し、現場は混乱状態に陥っております。深夜の外出を控え、戸締まりを徹底してください。\
武器免許を所持する市民は、犯人と遭遇した際、決して反撃せず（非常にキケン！！！）、 身の安全を確保することを優先してください。\
犯人の手がかりがある方は、警備部隊のリズム・フィッシャーまでご連絡ください。\
忠実なる民は皇帝のご加護を得られるでしょう。皇帝に栄光あれ。",
            ["DialogueId"] = 10030510,
            ["GUID"] = "191C3E8C",
            ["VoiceName"] = "voice/$Locale$/story/1003/100305/191C3E8C",
            },
        [10030601] = {
            ["Content"] = "挥手打个招呼。",
            ["ContentJP"] = "手を振る。",
            ["DialogueId"] = 10030601,
            ["GUID"] = "191C4D7A",
            ["NextDialogue"] = 10030603,
            },
        [10030602] = {
            ["Content"] = "吹个口哨。",
            ["ContentJP"] = "口笛を吹く。",
            ["DialogueId"] = 10030602,
            ["GUID"] = "191C4DA4",
            ["NextDialogue"] = 10030603,
            },
        [10030603] = {
            ["Camera"] = "78.226898,5.710938,147.152344,0.000109,-17.401026,138.984924,35.000011,249.345123,false,Manual,3.0",
            ["Content"] = "呜呜呜……是你，{nickname}，真的是你！！",
            ["ContentJP"] = "うわああ……{nickname}！本当にお前か！！",
            ["DialogueId"] = 10030603,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["GUID"] = "191C4DCE",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "200021:n(100001)",
                [3] = "100001:n(200002)",
                },
            ["NextDialogue"] = 10030604,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4DCE",
            },
        [10030604] = {
            ["Camera"] = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862011,35.282173,313.231873,false,Manual,6.0",
            ["Content"] = "哦？该说不说，碰上<H>卡戎狩猎</>还能活着，你命真是比坚壳果还硬啊。我还以为我们这个“夜航者小队”还没起航就要搁浅了呢。",
            ["ContentJP"] = "お？まあなんだ、<H>カロン狩り</>から生き延びるなんて、案外しぶといのな。「<Default note=\"text:ノクトボイジャー\">夜航者</>」が出航するより先に座礁しちまうのかと思ったぜ。",
            ["DialogueId"] = 10030604,
            ["GUID"] = "191C4DF8",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030605,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_Start",
                [2] = "200002:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "100304:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4DF8",
            },
        [10030605] = {
            ["Camera"] = "0.396332,244.167969,21.378906,0.000094,25.396158,-121.224731,35.000011,411.428223,false,Manual,22.0",
            ["Content"] = "呸呸呸，明明这几天急得又是满城找医生，又是低三下四求卡米拉帮忙照顾{性别：他|她}的就是你，现在人家醒了，怎么又开始胡言乱语！",
            ["ContentJP"] = "なんて不吉なことを！ここ数日、カミラに頭を下げて{性别:こいつ|こいつ}の面倒見を頼んだのは誰なんだか！やっと本人が目を覚ましたってのに……ほんと素直じゃないのな。",
            ["DialogueId"] = 10030605,
            ["GUID"] = "191C4E22",
            ["LookAt"] = {
                [1] = "200002:n(200021)",
                [2] = "100001:n(200021)",
                [3] = "200021:n(200002)",
                },
            ["NextDialogue"] = 10030606,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                [2] = "200021:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4E22",
            },
        [10030606] = {
            ["Camera"] = "23.498505,-207.322266,260.337891,0.00005,-27.40271,113.967453,35.000011,411.428162,false,Manual,3.0",
            ["Content"] = "我没——小矮子我警告你少添油加醋啊，不然——",
            ["ContentJP"] = "なっ――何のことだか！デタラメもほどほどにしろよ！",
            ["DialogueId"] = 10030606,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "191C4E4C",
            ["NextDialogue"] = 10030607,
