                [2] = "200002:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4E4C",
            },
        [10030607] = {
            ["Camera"] = "-405.321106,133.943359,83.382812,0.000094,-6.002507,-9.651911,35.0,681.079041,false,Manual,3.0",
            ["Content"] = "（嗯……看起来这两个人都还挺精神的。）",
            ["ContentJP"] = "（うん……二人とも元気そうでよかった。）",
            ["DialogueId"] = 10030607,
            ["DisableMouth"] = 1,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["FinalCamera"] = "-405.321106,133.943359,83.382812,0.000094,-1.002378,-9.652462,35.000008,520.892517,false,Manual,6.0",
            ["GUID"] = "191C4E76",
            ["NextDialogue"] = 10030608,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4E76",
            },
        [10030608] = {
            ["Camera"] = "135.663208,-35.232422,147.521484,0.000062,-15.799928,131.261826,35.000023,295.694153,false,Manual,6.0",
            ["Content"] = "小仆从你感觉怎么样？嗯……胳膊腿都在，角的颜色很棒，脸色有点差。",
            ["ContentJP"] = "下僕よ、調子はどうだ？ふむふむ……手足もちゃんと揃ってるし、角の色も良好だな！顔色は少し悪いが……",
            ["DialogueId"] = 10030608,
            ["GUID"] = "191C4EA0",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "200021:n(100001)",
                [3] = "100001:n(200002)",
                },
            ["NextDialogue"] = 10030609,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Bai_Think2Confident",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4EA0",
            },
        [10030609] = {
            ["Content"] = "很好，我就知道“不死的白色骑士，重生的夜航之星，被赐福的恶魔伯爵”不会随便抛下魔王大人不管的！",
            ["ContentJP"] = "ふむふむ、「不死なる騎士」にして「<Default note=\"text:ノクトボイジャー\">夜航者</>の新星」、そして「祝福されし悪魔伯爵」が、この魔王様を置き去りにするわけないってわかってたんだから！",
            ["DialogueId"] = 10030609,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["GUID"] = "191C4ECA",
            ["NextDialogue"] = 10030610,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4ECA",
            },
        [10030610] = {
            ["Content"] = "你坐在这里不要动，我去给你拿点水果补补身子！",
            ["ContentJP"] = "ほら座りな。果物を取って来るよ。しっかり栄養補給しないとな！",
            ["DialogueId"] = 10030610,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "191C4EF4",
            ["NextDialogue"] = 10030631,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4EF4",
            },
        [10030611] = {
            ["Camera"] = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
            ["Content"] = "（怎么称呼变长以后，爵位反而更低了！等等……不能被白奇怪的称呼拐走话题。）",
            ["ContentJP"] = "（どんどん称号が長くなってるけど、爵位はむしろ下がってない！？って……スノウの変な称号につられて、目的を忘れるところだった。）",
            ["DialogueId"] = 10030611,
            ["DisableMouth"] = 1,
            ["GUID"] = "191C4F1E",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030612,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4F1E",
            },
        [10030612] = {
            ["Camera"] = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
            ["Content"] = "刚才你们在说什么……<H>卡戎狩猎</>？那是什么？",
            ["ContentJP"] = "さっき……<H>カロン狩り</>って聞こえたけど。いったい何のこと？",
            ["DialogueId"] = 10030612,
            ["GUID"] = "191C4F48",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030613,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4F48",
            },
        [10030613] = {
