            },
        [10030616] = {
            ["Camera"] = "1297.798462,-671.682617,65.072266,0.000065,-0.601719,155.368057,35.000008,116.489357,false,Manual,3.0",
            ["Content"] = "喏，来了来了。麻烦一蹬腿不动弹了——麻烦死喽。",
            ["ContentJP"] = "ほれ見ろ、厄介事が来たぞ……",
            ["DialogueId"] = 10030616,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["FinalCamera"] = "1297.798462,-671.682617,65.072266,0.000066,-0.601685,155.368103,35.000008,2653.720459,false,Manual,3.0",
            ["GUID"] = "191C4FF0",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10030617,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "100001:n(100304)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C4FF0",
            },
        [10030617] = {
            ["Camera"] = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
            ["Content"] = "……黎瑟·费西尔？",
            ["ContentJP"] = "……リズム・フィッシャー？",
            ["DialogueId"] = 10030617,
            ["GUID"] = "191C501A",
            ["NextDialogue"] = 10030618,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "200002:Shock_End",
                [3] = "200021:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C501A",
            },
        [10030618] = {
            ["Content"] = "对，又来了。她基本每天这个点都要来问一次。",
            ["ContentJP"] = "そう、もう何度目だか。毎日この時間になると必ずお前のことを尋ねに来るんだ。",
            ["DialogueId"] = 10030618,
            ["GUID"] = "191C5044",
            ["NextDialogue"] = 10030619,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5044",
            },
        [10030619] = {
            ["Content"] = "……既然你说了“又”，那就说明这几天已经应付过她很多次了。交给你了，奥特赛德，加油，你可以的。",
            ["ContentJP"] = "……つまり、ここ数日ずっとあなたが彼女の相手をしてたってことだよね。なら、今回も任せるね。ありがとう、アウトサイダー！",
            ["DialogueId"] = 10030619,
            ["GUID"] = "191C506E",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10030620,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200021)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C506E",
            },
        [10030620] = {
            ["Content"] = "等等，先别走。唉，我说过，这麻烦你逃不掉的。",
            ["ContentJP"] = "おい、待て。言っただろう、お前も避けられねぇ厄介事だって。",
            ["DialogueId"] = 10030620,
            ["GUID"] = "191C5098",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextDialogue"] = 10030621,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5098",
            },
        [10030621] = {
            ["Content"] = "<W>卡戎狩猎</>是近期发生在外城的<W>连环凶案</>，你作为唯一幸存者不可能不被军团问话，时间早晚而已。",
            ["ContentJP"] = "<W>カロン狩り</>ってのは、最近外城区で多発している<W>連続殺人事件</>のことだ。その唯一の生存者として、お前は遅かれ早かれ帝国軍の事情聴取を受けることになる。",
            ["DialogueId"] = 10030621,
            ["GUID"] = "191C50C2",
            ["NextDialogue"] = 10030622,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C50C2",
            },
        [10030622] = {
            ["Content"] = "我看这位黎瑟女士还挺好说话的，这在军团可不多见。要是换个凶神恶煞的来，还不如她呢。",
            ["ContentJP"] = "あのリズムって女は意外と話が通じるやつだ。少なくとも仏頂面の軍人に比べりゃマシだぜ。",
            ["DialogueId"] = 10030622,
            ["GUID"] = "191C50EC",
            ["NextOptions"] = {
                [1] = 10030623,
                [2] = 10030624,
                },
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C50EC",
            },
        [10030623] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 10030623,
            ["GUID"] = "191C5116",
            ["NextDialogue"] = 10030625,
            },
        [10030624] = {
            ["Content"] = "……我不太想见她。",
            ["ContentJP"] = "……いや、彼女にはあまり会いたくない。",
            ["DialogueId"] = 10030624,
            ["GUID"] = "191C5140",
            ["NextDialogue"] = 10030625,
            },
        [10030625] = {
            ["Content"] = "好吧，你的意思我懂了。既然你还没做好准备，那就还是先由我——",
            ["ContentJP"] = "そうか。まあ、気持ちはわかった。まだ心の準備が出来ていないってんなら、ひとまず俺が――",
            ["DialogueId"] = 10030625,
            ["GUID"] = "191C516A",
            ["NextDialogue"] = 10030626,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk01_End",
                },
            ["TurnTo"] = {
                [1] = "100304:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C516A",
            },
        [10030626] = {
            ["Camera"] = "3.56424,135.133789,143.957031,0.000086,-7.202332,-42.028748,35.000008,998.946716,false,Manual,3.0",
            ["Content"] = "{nickname}，你终于醒了。我有件重要的事，希望你配合——",
            ["ContentJP"] = "{nickname}どの、目が覚めたのですね。重要な件で、ご協力をお願いしたく――",
            ["DialogueId"] = 10030626,
            ["GUID"] = "191C5194",
            ["NextDialogue"] = 10030627,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5194",
            },
        [10030627] = {
            ["Camera"] = "3.56424,135.133789,143.957031,0.000086,-7.202332,-42.028748,35.000008,998.946716,false,Manual,3.0",
            ["Content"] = "……她看到了！",
            ["ContentJP"] = "……しまった！",
            ["DialogueId"] = 10030627,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "191C51BE",
            ["NextDialogue"] = 10030628,
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"100001:n(100304)\"}},   \
PlayAnimation{ActorId{100001},AnimationId{\"Shock_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C51BE",
            },
        [10030628] = {
            ["Camera"] = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
            ["Content"] = "那就没办法了，去吧{性别：兄弟|朋友}，该来的总会来的。",
            ["ContentJP"] = "こうなっちゃ仕方ないな。無駄な足掻きはよせ、{性别:相棒|相棒}。",
            ["DialogueId"] = 10030628,
            ["GUID"] = "191C51E8",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "100001:n(100304)",
