                [1] = "100001:Shock_End",
                [2] = "200021:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C51E8",
            },
        [10030629] = {
            ["Content"] = "唉，真是甩不掉的麻烦啊。",
            ["ContentJP"] = "はぁ……確かに避けられそうにないね。",
            ["DialogueId"] = 10030629,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191C5212",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 10030630,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100306/191C5212",
            },
        [10030630] = {
            ["Camera"] = "-285.275513,162.134766,109.957031,0.000065,2.195619,-25.839436,35.000008,1787541766275072.0,false,Manual,3.0",
            ["Content"] = "……先看看这家伙到底有什么事吧。",
            ["ContentJP"] = "……とりあえず、用件を聞いてみよう。",
            ["DialogueId"] = 10030630,
            ["FinalCamera"] = "-285.275513,162.134766,109.957031,0.000065,-1.404328,-26.238977,35.000008,1787541766275072.0,false,Manual,3.0",
