        [10030802] = {
            ["Camera"] = "40.330078,-14.789795,129.912109,-0.000122,3.401612,100.797935,35.000019,1.5,false,DoNotOverride,1.2",
            ["Content"] = "嗯，我平时累了的话，就会来这里散心。这里一般没什么人，适合聊正事。",
            ["ContentJP"] = "ええ、疲れを感じた時によく来る場所です。人通りも少ないので、重要な話し合いにはもってこいの場所かと。",
            ["DialogueId"] = 10030802,
            ["FacialId"] = {
