                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100310/191C9094",
            },
        [10031101] = {
            ["Camera"] = "844.44043,-1090.708984,244.199707,0.000182,-7.000854,132.199615,50.000008,100000.0,false,Manual,22.0",
            ["Content"] = "凌晨四点到五点间……嗯，和卡米拉·斯卡雷特的证词一致。看来你的记忆很准确，并没有受到昏迷的影响。",
            ["ContentJP"] = "午前4時から5時の間……ふむ、カミラ・スカーレットの証言とも一致しますし、月狩り人どのの記憶にブレはないようですね。",
            ["DialogueId"] = 10031101,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "792.896484,-1033.864258,234.775391,0.000182,-7.000854,132.199615,50.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191C9F82",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                [2] = "200021:n(100304)",
                [3] = "200002:n(100304)",
                [4] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10031102,
            ["RelatedWikiId"] = {
                [1] = 201011,
                [2] = 405005,
                },
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191C9F82",
            },
        [10031102] = {
            ["Camera"] = "164.110352,-295.21875,130.549805,0.000187,-2.201418,135.795242,35.0,324.824371,false,Manual,3.0",
            ["Content"] = "那么，关于凶手的特征，你还记得多少？我想知道线索，任何线索都可以。",
            ["ContentJP"] = "では、犯人の特徴などはどうですか？どんな些細なことでも構いません。何か覚えていることがあれば教えてください。",
            ["DialogueId"] = 10031102,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191C9FAC",
            ["NextDialogue"] = 10031103,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191C9FAC",
            },
        [10031103] = {
            ["Camera"] = "1.719727,-99.894531,130.34082,0.000209,1.398256,-61.207794,35.000011,324.828125,false,Manual,22.0",
            ["Content"] = "当时的袭击太突然，我没看太清楚凶手的长相。但有一点我可以确认，它……不是人。",
            ["ContentJP"] = "あまりにも突然のことだったから、犯人の顔までははっきり見えなかった。でも……犯人は「人間」じゃなかった。これだけは断言できる。",
            ["DialogueId"] = 10031103,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                [2] = "200021:Shock01",
                },
            ["GUID"] = "191C9FD6",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10031104,
            ["Scripts"] = "CameraMoveTo{_delay{7},TargetPosition{\"56.811523,-148.78833,135.421875,0.000207,4.598254,-77.806282,35.000011,324.828125,false,Manual,22.0\"},duration{0}},",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191C9FD6",
            },
        [10031104] = {
            ["Camera"] = "56.811523,-148.78833,135.421875,0.000208,4.59824,-76.605972,35.000015,324.828125,false,Manual,22.0",
            ["Content"] = "我昏倒前最后一刻看到的，是一张怪物的面孔。至于到底是秽兽还是其他什么，就不清楚了。",
            ["ContentJP"] = "気を失う前に見えたのは、おぞましい化け物の顔だった。それが「<Default note=\"text:エジュウ\">穢獣</>」なのか、それとも別の何かなのかまではわからないけど……",
            ["DialogueId"] = 10031104,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "191CA000",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                },
            ["NextDialogue"] = 10031105,
            ["Scripts"] = "PlayAnimation{_delay{6},ActorId{100001},AnimationId{\"Think_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA000",
            },
        [10031105] = {
            ["Camera"] = "149.513672,-169.366943,198.691895,0.000219,-21.601606,154.789032,35.0,324.824371,false,DoNotOverride,22",
            ["Content"] = "嗯……怪物，这个我已经知道了。没有其他信息了吗……",
            ["ContentJP"] = "……化け物、ですか。分かりました。他には何かございますか……？",
            ["DialogueId"] = 10031105,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191CA02A",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                },
            ["NextDialogue"] = 10031106,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA02A",
            },
        [10031106] = {
            ["Camera"] = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
            ["Content"] = "等等，还有一件事！",
            ["ContentJP"] = "あ、待って、もう一つ思い出した！",
            ["DialogueId"] = 10031106,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "191CA054",
            ["NextDialogue"] = 10031107,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA054",
            },
        [10031107] = {
            ["Content"] = "请说！",
            ["ContentJP"] = "なんでしょう！",
            ["DialogueId"] = 10031107,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "191CA07E",
            ["NextDialogue"] = 10031108,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA07E",
            },
        [10031108] = {
            ["Content"] = "歌声……",
            ["ContentJP"] = "歌声……",
            ["DialogueId"] = 10031108,
            ["GUID"] = "191CA0A8",
            ["NextDialogue"] = 10031109,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100304:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA0A8",
            },
        [10031109] = {
            ["Camera"] = "145.999023,-899.881348,124.759277,0.000267,33.387341,-12.212714,15.0,324.824371,false,Manual,3.0",
            ["Content"] = "我记得，在这条街，我被什么东西尾随……那时，我听到的，除了它的脚步声外，还有……歌声。",
            ["ContentJP"] = "この通りを歩いていた時、何者かに尾行されて……その時、足音以外に……歌声が聞こえた{性别:んだ|の}。",
            ["DialogueId"] = 10031109,
            ["FinalCamera"] = "116.962891,-893.183594,105.121094,0.000266,33.387348,-12.612405,15.0,324.824371,false,Manual,3.0",
            ["GUID"] = "191CA0D2",
            ["NextDialogue"] = 10031110,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA0D2",
            },
        [10031110] = {
            ["Camera"] = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
            ["Content"] = "我记得，在这条街，我被什么东西尾随……那时，我听到的，除了它的脚步声外，还有……歌声。",
            ["ContentJP"] = "間違いない……声はかすれていて、まるで壊れたふいごみたいだったけど――<H>あの化け物は歌を歌っていた</>。",
            ["DialogueId"] = 10031110,
            ["GUID"] = "191CA0FC",
            ["NextDialogue"] = 10031111,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA0FC",
            },
        [10031111] = {
            ["Camera"] = "105.765625,-455.361328,108.25,0.000137,4.600098,105.407356,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "歌声？这个还没有人说过——太好了，是全新的线索！我就知道你那一下不会白挨。",
            ["ContentJP"] = "歌声……ですか？なるほど、それは新しい手がかりです！事件の突破口となるかもしれません！月狩り人どのの苦しみは決して無駄にはしませんから。",
            ["DialogueId"] = 10031111,
            ["FacialId"] = {
                [1] = "100304:Happy01",
                },
            ["GUID"] = "191CA126",
            ["NextDialogue"] = 10031112,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Confident_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA126",
            },
        [10031112] = {
            ["Camera"] = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "喂，我说长官，人家经历挺痛苦的，这么激动不太好吧？",
            ["ContentJP"] = "おい、長官、人の辛い記憶を掘り起こしといて、そんな風に喜ぶのはどうなんだ？",
            ["DialogueId"] = 10031112,
            ["GUID"] = "191CA150",
            ["LookAt"] = {
                [1] = "100304:n(200021)",
                [2] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10031113,
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"200021:n(100304)\"}},PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100304:Confident_End",
                [2] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA150",
            },
        [10031113] = {
            ["Camera"] = "90.230469,-472.615723,119.978027,0.000191,-0.400393,102.219055,40.0,941.904541,false,DoNotOverride,1.2",
            ["Content"] = "……抱歉。刚刚我只是想，案子有了突破口，兴许就可以早点结束这场“狩猎”，还大家一个安宁了。我没有拿你的痛苦回忆取乐的意思，万分抱歉。",
            ["ContentJP"] = "……大変失礼しました。あくまで捜査の進展に対する感情であって、決して月狩り人どのの苦しみに興奮しているわけではありません。どうかお許しください。",
            ["DialogueId"] = 10031113,
            ["FacialId"] = {
                [1] = "100304:Shock01",
                },
            ["GUID"] = "191CA17A",
            ["NextOptions"] = {
                [1] = 10031114,
                [2] = 10031116,
                },
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "200021:Explain01_End",
                [2] = "100304:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA17A",
            },
        [10031114] = {
            ["Content"] = "我没有介意。",
            ["ContentJP"] = "大丈夫だよ。",
            ["DialogueId"] = 10031114,
            ["GUID"] = "191CA1A4",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10031115,
            },
        [10031115] = {
            ["Camera"] = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2",
            ["Content"] = "谢谢你的宽容。",
            ["ContentJP"] = "ありがとうございます。",
            ["DialogueId"] = 10031115,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["GUID"] = "191CA1CE",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10031123,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA1CE",
            },
        [10031116] = {
            ["Content"] = "我要精神损失费。",
            ["ContentJP"] = "お詫びに、損害賠償金を追加して。",
            ["DialogueId"] = 10031116,
            ["GUID"] = "191CA1F8",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10031117,
            },
        [10031117] = {
            ["Camera"] = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2",
            ["Content"] = "你需要多少？如果在我可以承受的范围内……",
            ["ContentJP"] = "わかりました。私に負担できる範囲内であれば――",
            ["DialogueId"] = 10031117,
            ["GUID"] = "191CA222",
            ["LookAt"] = {
                [1] = "100304:n(100001)",
                },
            ["NextDialogue"] = 10031118,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA222",
            },
        [10031118] = {
            ["Camera"] = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "这玩笑都当真？长官小姐，您是个没怎么和外城人打过交道的“桂冠卡戎”吧？",
            ["ContentJP"] = "こんなジョークを真に受けるやつがいたなんてな。長官様、まさかとは思うが、アイスレイク城の貴族「桂冠カロン族」か何かか？",
            ["DialogueId"] = 10031118,
            ["GUID"] = "191CA24C",
            ["NextDialogue"] = 10031119,
            ["RelatedWikiId"] = {
                [1] = 407003,
                },
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA24C",
            },
        [10031119] = {
            ["Content"] = "要是把军团这身行头脱下来，便装去贫民窟转一圈，我看恐怕不等太阳下山，您就得赔得连鞋子都不剩了。",
            ["ContentJP"] = "軍服を脱いで、普段着でスラム街を歩いてみな。日が沈む頃にゃ、身ぐるみを剥がされてるだろうよ。",
            ["DialogueId"] = 10031119,
            ["GUID"] = "191CA276",
            ["NextDialogue"] = 10031120,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                [2] = "200021:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA276",
            },
        [10031120] = {
            ["Camera"] = "149.513672,-169.366943,198.691895,0.000219,-21.601578,154.789032,35.0,324.824371,false,DoNotOverride,22",
            ["Content"] = "“桂冠卡戎”……很惭愧，现在的我还没有获得这份殊荣的资格。",
            ["ContentJP"] = "「桂冠カロン族」……恥ずかしい話、私はそんな称号を頂けるほどの器ではありません。",
            ["DialogueId"] = 10031120,
            ["FacialId"] = {
                [1] = "100304:Sad02",
                },
            ["GUID"] = "191CA2A0",
            ["NextDialogue"] = 10031121,
            ["Scripts"] = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"DisagreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA2A0",
            },
        [10031121] = {
            ["Camera"] = "114.541016,142.993408,51.0,0.000056,8.797734,-105.975571,35.0,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "相反，我自己就是雾区出身。我过过那种日子，知道外城卡戎人的生计有多难。所以，能帮上忙的我会尽量帮。",
            ["ContentJP"] = "私は霧の街の出身です。なので、スラムの暮らしがどういうものかは、身をもって体験しています。だからこそ、できる範囲でお力になれればと思っているのです。",
            ["DialogueId"] = 10031121,
            ["FacialId"] = {
                [1] = "100304:Sad02",
                },
            ["GUID"] = "191CA2CA",
            ["NextDialogue"] = 10031122,
            ["RelatedWikiId"] = {
                [1] = 408003,
                },
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA2CA",
            },
        [10031122] = {
            ["Content"] = "更何况刚刚是我说错话在先，所以……",
            ["ContentJP"] = "それに、先ほどの発言は確かに自分の落ち度ですから……",
            ["DialogueId"] = 10031122,
            ["GUID"] = "191CA2F4",
            ["NextDialogue"] = 10031123,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA2F4",
            },
        [10031123] = {
            ["Camera"] = "133.141602,-83.859375,106.349609,0.000045,10.39638,-116.369263,35.000011,941.904541,false,DoNotOverride,1.903106",
            ["Content"] = "行了，其他事都等“卡戎狩猎”的事完了再说吧。既然长官你费那么大力气把我叫来，那就先该调查调查，该问话问话吧。",
            ["ContentJP"] = "ひとまず、今は「カロン狩り」の解決を優先しよう。長官、わざわざ{性别:僕|私}を呼び出した以上、はやく調査を進めて{性别:くれ|ほしい}。",
            ["DialogueId"] = 10031123,
            ["GUID"] = "191CA31E",
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Explain01_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "100304:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100311/191CA31E",
            },
        [10031201] = {
            ["Camera"] = "-802.193359,-200.429199,291.232422,0.000171,-5.395378,13.011268,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "刚才提到的“怪物的歌声”……你还能试着哼一下那首歌的旋律吗？",
            ["ContentJP"] = "先ほどの「化け物の歌声」について……そのメロディを覚えていますか？",
            ["DetectiveQuestionId"] = 1003,
            ["DialogueId"] = 10031201,
            ["FinalCamera"] = "-802.193359,-200.429199,291.232422,0.000172,-13.395387,14.612322,35.000011,100000.0,false,Manual,22.0",
