        [10032302] = {
            ["Camera"] = "87.0,17.469238,161.0,-10.803343,-34.997726,-25.183821,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "抱歉，薇奥莱塔老师。我，我再试试……",
            ["ContentJP"] = "すみません、ヴィオレッタ先生。もう一度やってみます……",
            ["DialogueId"] = 10032302,
            ["FinalCamera"] = "86.523438,17.706665,161.0,-10.805331,-17.197323,-25.181259,35.000011,100000.0,false,DoNotOverride,22.0",
