        [10032311] = {
            ["Camera"] = "105.410156,-129.692505,108.539062,0.00026,12.795806,-78.157402,35.000023,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "那么，有没有什么人不好好排练，半夜偷偷溜出去？",
            ["ContentJP"] = "それじゃあ、リハーサルをサボって、夜中にこっそり抜け出した人とかいなかった？",
            ["DialogueId"] = 10032311,
            ["FacialId"] = {
