            ["FinalCamera"] = "110.507812,-128.654907,108.539062,0.000264,12.795792,-80.756798,35.000023,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191D6606",
            ["NextDialogue"] = 10032312,
