                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100325/191D88F8",
            },
        [10032526] = {
            ["Content"] = "渔夫。",
            ["ContentJP"] = "漁師か。",
            ["DialogueId"] = 10032526,
            ["GUID"] = "191D8922",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 10032527,
            },
        [10032527] = {
            ["Camera"] = "-52.859375,-596.512695,69.789795,0.000565,3.798207,76.587906,45.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "嗯，我也赞同。",
            ["ContentJP"] = "私もそう思います。",
            ["DialogueId"] = 10032527,
