        [10032720] = {
            ["Camera"] = "55.330933,1065.099609,369.362305,0.000144,7.601577,-134.201859,25.000006,91.688835,false,Manual,3.0",
            ["Content"] = "……情况我知道了，盗窃帝国公共财产，按照《海伯利亚刑事法典》第33条，应判处十年监禁。",
            ["ContentJP"] = "……分かりました。ただし、帝国の公有財産を盗んだ罪が確定した以上、『ヒュペリア刑法』第33条により、10年の刑が科せられる可能性があります。",
            ["DialogueId"] = 10032720,
            ["FacialId"] = {
                [1] = "100304:Close",
                },
            ["FinalCamera"] = "55.330933,1065.099609,369.362305,0.000144,7.601577,-134.201859,27.0,91.688835,false,Manual,3.0",
