        [10032721] = {
            ["Camera"] = "178.80014,1315.770508,449.867676,0.000145,-16.998201,-127.790787,25.000002,12186.542969,false,Manual,22.0",
            ["Content"] = "十，十年？？？长官，各位长官，你们帮帮忙，帮帮忙啊。",
            ["ContentJP"] = "じゅ、10年！？ちょっと待ってください、長官様！ど……どうか勘弁してください！",
            ["DialogueId"] = 10032721,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["FinalCamera"] = "178.80014,1315.770508,453.872559,0.000144,-17.398165,-127.590401,25.000002,12186.542969,false,Manual,22.0",
