            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DA99E",
            },
        [10032724] = {
            ["Content"] = "生活的艰苦构不成犯罪的借口，抱歉。",
            ["ContentJP"] = "貧しいからって、何をしてもいいってわけじゃないよ。",
            ["DialogueId"] = 10032724,
            ["GUID"] = "191DA9C8",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 10032725,
            },
        [10032725] = {
            ["Camera"] = "-1.381821,1059.145508,417.826172,0.00006,-9.197997,91.177856,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "啊，这，我……",
            ["ContentJP"] = "そ、それは……",
            ["DialogueId"] = 10032725,
            ["FinalCamera"] = "-1.447895,1062.360352,417.304688,0.00006,-9.197997,91.177856,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DA9F2",
            ["NextDialogue"] = 10032726,
            ["SpeakNpcId"] = 100314,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DA9F2",
            },
        [10032726] = {
            ["Camera"] = "276.917511,644.075195,504.31543,5.000523,-17.598658,129.559998,35.000015,100000.0,false,Manual,22.0",
            ["Content"] = "我、我、我……我还有重大线索要交代！和你们说的那个“卡戎狩猎”有关！",
            ["ContentJP"] = "お、俺、その「カロン狩り」に関する重要な手がかりを知ってるぜ！",
            ["DialogueId"] = 10032726,
            ["FacialId"] = {
                [1] = "100314:CM_Sad01",
                [2] = "\
100304:None",
                [3] = "\
100001:None",
                },
            ["FinalCamera"] = "272.368469,640.114258,503.812012,5.000535,-17.598658,128.959854,35.000015,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAA1C",
            ["LookAt"] = {
                [1] = "100304:n(100314)",
                },
            ["NextDialogue"] = 10032727,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100314},AnimationId{\"Talk01_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["ToFinalCameraBlendTime"] = 7.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA1C",
            },
        [10032727] = {
            ["Camera"] = "2.182457,1055.015625,378.21875,0.000225,6.601323,-88.042694,15.0,44.406654,false,Manual,2.0",
            ["Content"] = "快说！把你知道的全告诉我，一句也不要遗漏！",
            ["ContentJP"] = "言いなさい！洗いざらい全部！",
            ["DialogueId"] = 10032727,
            ["FacialId"] = {
                [1] = "100304:Unhappy01",
                },
            ["FinalCamera"] = "2.247303,1052.630859,378.50293,0.000228,6.801318,-88.44265,15.0,44.406654,false,Manual,2.0",
            ["GUID"] = "191DAA46",
            ["NextDialogue"] = 10032728,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Angry01_Start",
                [2] = "\
100314:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA46",
            },
        [10032728] = {
            ["Camera"] = "35.5327,1047.580078,426.085449,0.000162,-13.398644,112.155922,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "你们、你们得先答应……你们要保证我的安全！我怕万一说出来，那该死的怪物就会把我、把我……",
            ["ContentJP"] = "俺の安全が保証されない限り、絶対に話すもんか！万が一、あの化け物に知られたら、お……俺は……",
            ["DialogueId"] = 10032728,
            ["FinalCamera"] = "30.844559,1060.518555,427.949219,0.000161,-14.798738,110.955978,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAA70",
            ["NextDialogue"] = 10032729,
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{100314},AnimationId{\"Explain02_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100304:Angry01_End",
                [2] = "\
100314:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA70",
            },
        [10032729] = {
            ["Camera"] = "7.246655,1098.832031,376.648438,0.000195,5.001645,-96.442291,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "我保证，不会让那只怪物伤害到你。",
            ["ContentJP"] = "心配せずとも、あなたの安全を守ると約束するわ。",
            ["DialogueId"] = 10032729,
            ["FinalCamera"] = "6.774265,1094.647461,377.016602,0.000194,5.201646,-96.242355,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAA9A",
            ["NextDialogue"] = 10032730,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:AgreeHead",
                [2] = "\
100314:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAA9A",
            },
        [10032730] = {
            ["Camera"] = "-3.580261,1060.973633,409.661621,0.000202,-4.198271,88.156929,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "好，好。那晚我在机车厂里，捡了两罐月髓液就打算开溜……但就在我翻墙离开的时候，我看到了、看到了……",
            ["ContentJP"] = "分かった……話すよ。5日前の夜、イコル液を盗んで、こっそり外に出た時だ……下水道から何かが這い出てくるのを見たんだ！",
            ["DialogueId"] = 10032730,
            ["FinalCamera"] = "-2.966713,1078.547852,408.523438,0.000198,-3.198168,83.556847,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAAC4",
            ["NextDialogue"] = 10032731,
            ["Scripts"] = "PlayAnimation{_delay{6},ActorId{100314},AnimationId{\"Sigh_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Agree",
                },
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAAC4",
            },
        [10032731] = {
            ["Camera"] = "39.773964,990.78125,331.155762,0.000091,18.20233,103.582535,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "我看到了一只怪物，从我眼前的下水道钻了出来！它有两人那么高，秽兽一样的脑袋，像熊一样强壮……它的眼睛和嘴里都喷着火焰……",
            ["ContentJP"] = "2メートル以上もある化け物だった！頭は「<Default note=\"text:エジュウ\">穢獣</>」のそれで、体は熊のようにがっしりしていた。それに……目と口から火が噴き出してたんだ……！",
            ["DialogueId"] = 10032731,
            ["FinalCamera"] = "28.134758,1028.376953,382.807129,0.000107,5.802635,101.982338,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAAEE",
            ["NextDialogue"] = 10032732,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100314},AnimationId{\"Sigh_End\"},Duration{2}},\
PlayAnimation{_delay{3},ActorId{100314},AnimationId{\"Talk01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 100314,
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAAEE",
            },
        [10032732] = {
            ["Camera"] = "80.654564,1001.875,379.909668,0.000229,0.202536,-121.235329,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "这个描述，莫非是秽兽？",
            ["ContentJP"] = "……それって、もしかして<Default note=\"text:エジュウ\">穢獣</>なんじゃ？",
            ["DialogueId"] = 10032732,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["FinalCamera"] = "78.132179,1001.040039,379.916016,0.000229,0.202536,-121.235329,25.000006,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAB18",
            ["NextDialogue"] = 10032733,
            ["Scripts"] = "SetLocation{ActorId{200021},TargetPoint{\"cp2fixsimple17_aoteHide\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "\
100314:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB18",
            },
        [10032733] = {
            ["Camera"] = "2.76627,1049.458008,392.086426,0.000262,-9.596436,-92.63929,19.0,50.097149,false,Manual,3.0",
            ["Content"] = "不，秽兽没有理智，只会在街上横冲直撞。而这只怪物既然白天会藏起来，那就说明它具备反侦察意识。",
            ["ContentJP"] = "いいえ。「<Default note=\"text:エジュウ\">穢獣</>」に知性はなく、ただやみくもに目に付くものを破壊する生き物です。一方で、この化け物は昼間に身を隠すなどの行動をとっている……つまり、理性を持っている可能性が高いかと。",
            ["DialogueId"] = 10032733,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "2.76627,1049.458008,392.086426,0.000262,-9.596436,-92.63929,20.0,50.097149,false,Manual,3.0",
            ["GUID"] = "191DAB42",
            ["NextDialogue"] = 10032734,
            ["Scripts"] = "SetLocation{ActorId{200021},TargetPoint{\"cp2fixsimple17_aoteHide\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Think_Start",
                [2] = "\
100314:Talk01_End",
                [3] = "\
100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB42",
            },
        [10032734] = {
            ["Camera"] = "26.018082,1022.058594,419.480957,0.00025,-9.196863,101.955841,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "我当时吓破了胆，光顾着把手里的东西一股脑丢过去，防身的鱼叉啊，月髓液啊……唉，辛辛苦苦搞来的月髓液全都砸它身上了，一分钱也没捞到。",
            ["ContentJP"] = "あの時、俺は完全に腰を抜かしちまった。それで手に持ってた銛だのイコル液だの、全部投げつけて逃げたんだ……こうして、辛うじて命拾いしたってわけさ。",
            ["DialogueId"] = 10032734,
            ["FinalCamera"] = "24.513016,1021.863281,422.244141,0.000247,-9.196863,99.756096,27.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAB6C",
            ["NextDialogue"] = 10032735,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{10},ActorId{100314},AnimationId{\"Talk02_End\"},Duration{2}},\
PlayAnimation{ActorId{100314},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{_delay{4},ActorId{100314},AnimationId{\"Sigh_End\"},Duration{2}},\
}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Talk02_Start",
                [2] = "\
100304:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB6C",
            },
        [10032735] = {
            ["Camera"] = "90.650497,1262.787109,464.490234,0.000251,-20.997215,-118.24427,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "难怪它身上会沾着这么多月髓液。然后呢，它怎样了？",
            ["ContentJP"] = "なるほど……だから、化け物の体に大量のイコル液が付着していたのね。それで、その後は？",
            ["DialogueId"] = 10032735,
            ["FacialId"] = {
                [1] = "100304:Think01",
                },
            ["FinalCamera"] = "90.650497,1262.787109,456.999512,0.000264,-18.797083,-118.044243,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DAB96",
            ["NextDialogue"] = 10032736,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAB96",
            },
        [10032736] = {
            ["Camera"] = "384.150787,1358.378906,320.59082,0.000264,2.402717,-144.638229,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "我哪知道，我回过神来吓得连裤子都湿了，拔腿就跑，根本不敢回头看……",
            ["ContentJP"] = "し、知るか！俺はとにかく命が惜しくて、逃げるので精一杯だったんだからよぉ……",
            ["DialogueId"] = 10032736,
            ["FacialId"] = {
                [1] = "100304:None",
                },
            ["FinalCamera"] = "391.812073,1347.450195,320.59082,0.000264,2.402717,-145.238098,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DABC0",
            ["NextDialogue"] = 10032737,
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DABC0",
            },
        [10032737] = {
            ["Camera"] = "10.431229,1056.774414,422.860352,0.000264,-14.396945,91.352699,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "唉，我全都、全都告诉你们了！各位长官，你们要说话算话，你们要救救我！我和那怪物打过照面，一直躲在这里也是怕它找上门来……",
            ["ContentJP"] = "知ってることはすべて話した！だから、お前たちも約束を守ってもらうぞ！俺がずっとここに隠れていたのも、あいつに見つからないためだからな！",
            ["DialogueId"] = 10032737,
            ["FinalCamera"] = "10.431229,1056.774414,422.860352,0.000264,-14.396945,91.352699,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191DABEA",
            ["LookAt"] = {
                [1] = "100314:n(100314)",
                },
            ["NextDialogue"] = 10032738,
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DABEA",
            },
        [10032738] = {
            ["Camera"] = "118.877075,858.798828,345.73584,0.000268,5.002854,122.155495,25.000002,327.751526,false,Manual,8.0",
            ["Content"] = "长官你看这个情报，和我那月、月髓液的事……",
            ["ContentJP"] = "手柄も立てたことだし、その、減刑の件は……",
            ["DialogueId"] = 10032738,
            ["FinalCamera"] = "116.053726,857.193359,345.73584,0.000266,4.60285,125.156082,25.000002,327.751526,false,Manual,8.0",
            ["GUID"] = "191DAC14",
            ["NextDialogue"] = 10032739,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{100314},AnimationId{\"Explain01_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 100314,
            ["TalkActionId"] = {
                [1] = "100314:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1003/100327/191DAC14",
            },
        [10032739] = {
            ["Camera"] = "12.610016,1093.600586,371.847168,0.000261,4.202765,-97.048279,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "我会如实汇报。你盗窃的罪行确凿——不过，根据《海伯利亚刑事法典》，因为你提供了怪物藏身处这一关键线索，量刑上会酌情减免。",
            ["ContentJP"] = "……あなたの状況は逐一上に報告します。窃盗に関しては『ヒュペリア刑法』に基づき裁かれますが、今回の協力を考慮し、量刑は減免されるでしょう。",
            ["DialogueId"] = 10032739,
            ["FinalCamera"] = "12.383255,1091.765625,369.847656,0.000261,5.202746,-97.248253,25.000002,100000.0,false,Manual,22.0",
