            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DB95E",
            },
        [10032820] = {
            ["Camera"] = "72.367409,-120.216789,137.059326,0.007411,1.581291,-2.808713,35.0,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "抱歉我漏了，还有第三件事是……",
            ["ContentJP"] = "すみません、もうひとつだけ……",
            ["DialogueId"] = 10032820,
            ["FinalCamera"] = "72.092346,-125.821777,137.059326,0.007411,1.581291,-2.808713,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191DB988",
            ["NextDialogue"] = 10032821,
            ["SpeakNpcId"] = 100304,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100328/191DB988",
            },
        [10032821] = {
            ["Camera"] = "113.508186,-60.045151,119.098877,0.007421,5.980657,72.403885,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "行了，没有第三件了。不，前两件也没有。",
            ["ContentJP"] = "もういい、全部お断りだよ。",
            ["DialogueId"] = 10032821,
            ["FacialId"] = {
