            ["VoiceName"] = "voice/$Locale$/story/1003/100330/191DD73A",
            },
        [10033002] = {
            ["Camera"] = "-4.990234,-83.879883,129.222412,0.000075,-0.599486,141.201096,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "他和同伴被一只怪物逼进了下水道，他以为自己肯定活不成了，但那只怪物突然停止了追击。",
            ["ContentJP"] = "仲間とある化け物に追い詰められ、この下水道に逃げ込んだそうです。もうダメだと思っていた矢先に、その化け物はなぜか急に追撃を止めたとか。",
            ["DialogueId"] = 10033002,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "-3.224609,-81.675781,129.222412,0.000074,-0.599486,141.601227,35.000008,100000.0,false,Manual,22.0",
