            },
        [10033004] = {
            ["Camera"] = "-49.501953,-22.475586,161.653687,0.000193,-13.19893,165.996674,35.000019,113.917175,false,Manual,3.0",
            ["Content"] = "怪物……卡戎狩猎的凶手？",
            ["ContentJP"] = "化け物……もしかして、「カロン狩り」の犯人？",
            ["DialogueId"] = 10033004,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["FinalCamera"] = "-56.919922,-20.625977,159.860718,0.000193,-13.19893,165.996674,35.000019,113.917175,false,Manual,3.0",
            ["GUID"] = "191DD7B8",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 10033005,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100330/191DD7B8",
            },
        [10033005] = {
            ["Camera"] = "-139.492188,131.598633,126.062134,0.000172,2.202073,-108.178284,20.0,100000.0,false,Manual,22.0",
            ["Content"] = "很有可能。我已处理了他的伤口并呼叫了我的下属，在他们赶来前，先保障两名受困者的安全吧。",
            ["ContentJP"] = "その可能性は高いですね。傷の手当てを済ませた後、部下に連絡を取りました。彼らが到着するまで、遭難者たちの安全を確保しましょう。",
            ["DialogueId"] = 10033005,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["FinalCamera"] = "-139.492188,131.598633,132.132202,0.000173,0.202044,-107.978302,20.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191DD7E2",
            ["NextDialogue"] = 10033006,
            ["Scripts"] = "PARA{\
