                [2] = "\
100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1003/100332/191DF8B2",
            },
        [10033206] = {
            ["Content"] = "收到。",
            ["ContentJP"] = "了解しました。",
            ["DialogueId"] = 10033206,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "191DF8DC",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 100344,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100332/191DF8DC",
            },
        [10033301] = {
            ["Content"] = "——吼！！",
            ["ContentJP"] = "――ガオォォォ！！",
            ["DialogueId"] = 10033301,
            ["GUID"] = "191E0872",
            ["NextDialogue"] = 10033302,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0872",
            },
        [10033302] = {
            ["Content"] = "那怪物到底藏在哪儿……",
            ["ContentJP"] = "あの化け物、いったいどこに隠れて……？",
            ["DialogueId"] = 10033302,
            ["GUID"] = "191E089C",
            ["NextDialogue"] = 10033303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E089C",
            },
        [10033303] = {
            ["Content"] = "废水处理区与下水道其他区域相连，我们把这里的废水排出去，彻查整片区域吧。",
            ["ContentJP"] = "廃水処理区は下水道の他の区域とつながっています。調査のため、まずは廃水を排出しましょう。",
            ["DialogueId"] = 10033303,
            ["GUID"] = "191E08C6",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E08C6",
            },
        [10033304] = {
            ["Content"] = "长官，我们来支援了。",
            ["ContentJP"] = "長官、支援に参りました。",
            ["DialogueId"] = 10033304,
            ["GUID"] = "191E08F0",
            ["NextDialogue"] = 10033305,
            ["SpeakNpcId"] = 100344,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E08F0",
            },
        [10033305] = {
            ["Content"] = "两位市民呢？",
            ["ContentJP"] = "被害者の2人は？",
            ["DialogueId"] = 10033305,
            ["GUID"] = "191E091A",
            ["NextDialogue"] = 10033306,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E091A",
            },
        [10033306] = {
            ["Content"] = "送去医院了。我们还呼叫了上级，到这份上他们终于肯支援了。",
            ["ContentJP"] = "病院に搬送しました。上層部にも連絡を取ったところ、ようやく支援をよこしてくれるそうです。",
            ["DialogueId"] = 10033306,
            ["GUID"] = "191E0944",
            ["NextDialogue"] = 10033307,
            ["SpeakNpcId"] = 100345,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0944",
            },
        [10033307] = {
            ["Content"] = "这几个人就是您提到的帮手吗？",
            ["ContentJP"] = "彼らが、長官が言っていた協力者ですか？",
            ["DialogueId"] = 10033307,
            ["GUID"] = "191E096E",
            ["NextDialogue"] = 10033308,
            ["SpeakNpcId"] = 100345,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E096E",
            },
        [10033308] = {
            ["Content"] = "是的，若不是“夜航者”这样优秀的狩月人，我也找不到这里。",
            ["ContentJP"] = "ええ。彼らのような優れた月狩り人たちがいなければ、ここに到達することはできなかったでしょう。",
            ["DialogueId"] = 10033308,
            ["GUID"] = "191E0998",
            ["NextDialogue"] = 10033309,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0998",
            },
        [10033309] = {
            ["Content"] = "哇，好多人帮忙呀！哼哼，对付打伤{nickname}的坏家伙，必须出重拳！",
            ["ContentJP"] = "うわぁ、これ全員助っ人！？ふふん、まあ、{nickname}を傷つけた悪いやつには、徹底的にお仕置きしてやらないとね！",
            ["DialogueId"] = 10033309,
            ["GUID"] = "191E09C2",
            ["NextDialogue"] = 10033310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E09C2",
            },
        [10033310] = {
            ["Content"] = "要准备迎战了。",
            ["ContentJP"] = "準備はできてるよ。",
            ["DialogueId"] = 10033310,
            ["GUID"] = "191E09EC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E09EC",
            },
        [10033311] = {
            ["Content"] = "吼……！",
            ["ContentJP"] = "グオォォォ……！",
            ["DialogueId"] = 10033311,
            ["GUID"] = "191E0A16",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0A16",
            },
        [10033312] = {
            ["Content"] = "目标并非秽兽，采取牵制战术！",
            ["ContentJP"] = "あれは<Default note=\"text:エジュウ\">穢獣</>じゃない！牽制しながら戦うのよ！",
            ["DialogueId"] = 10033312,
            ["GUID"] = "191E0A40",
            ["NextDialogue"] = 10033313,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0A40",
            },
        [10033313] = {
            ["Content"] = "活捉目标，还受害者一个交代！",
            ["ContentJP"] = "被害者の無念を払うためにも、生け捕りにしなさい！",
            ["DialogueId"] = 10033313,
            ["GUID"] = "191E0A6A",
            ["NextDialogue"] = 10033314,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0A6A",
            },
        [10033314] = {
            ["Content"] = "收到！",
            ["ContentJP"] = "了解！",
            ["DialogueId"] = 10033314,
            ["GUID"] = "191E0A94",
            ["SpeakNpcId"] = 100344,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0A94",
            },
        [10033315] = {
            ["Content"] = "粉……碎……",
            ["ContentJP"] = "砕け……ろ……",
            ["DialogueId"] = 10033315,
            ["GUID"] = "191E0ABE",
            ["NextDialogue"] = 10033316,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0ABE",
            },
        [10033316] = {
            ["Content"] = "呃啊……好大的力气……",
            ["ContentJP"] = "うっ……なんて力だ……！",
            ["DialogueId"] = 10033316,
            ["GUID"] = "191E0AE8",
            ["NextDialogue"] = 10033317,
            ["SpeakNpcId"] = 100345,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0AE8",
            },
        [10033317] = {
            ["Content"] = "小心！",
            ["ContentJP"] = "危ない！",
            ["DialogueId"] = 10033317,
            ["GUID"] = "191E0B12",
            ["NextDialogue"] = 10033318,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0B12",
            },
        [10033318] = {
            ["Content"] = "可恶……腾不出手！",
            ["ContentJP"] = "くっ……これ以上は……！",
            ["DialogueId"] = 10033318,
            ["GUID"] = "191E0B3C",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0B3C",
            },
        [10033319] = {
            ["Content"] = "消……除……",
            ["ContentJP"] = "抹消……する……",
            ["DialogueId"] = 10033319,
            ["GUID"] = "191E0B66",
            ["NextDialogue"] = 10033320,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0B66",
            },
        [10033320] = {
            ["Content"] = "我来掩护伤员后撤，大家不要慌张。",
            ["ContentJP"] = "みんな、落ち着いて！負傷者の撤退を援護するよ！",
            ["DialogueId"] = 10033320,
            ["GUID"] = "191E0B90",
            ["NextDialogue"] = 10033321,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0B90",
            },
        [10033321] = {
            ["Content"] = "拜托了。",
            ["ContentJP"] = "お願いします。",
            ["DialogueId"] = 10033321,
            ["GUID"] = "191E0BBA",
            ["NextDialogue"] = 10033322,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0BBA",
            },
        [10033322] = {
            ["Content"] = "咳……谢谢。",
            ["ContentJP"] = "ぐっ……助かった、ありがとう。",
            ["DialogueId"] = 10033322,
            ["GUID"] = "191E0BE4",
            ["SpeakNpcId"] = 100344,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0BE4",
            },
        [10033323] = {
            ["Content"] = "奥特赛德，左边有破绽。",
            ["ContentJP"] = "アウトサイダー！やつの左側を狙{性别:え|って}！",
            ["DialogueId"] = 10033323,
            ["GUID"] = "191E0C0E",
            ["NextDialogue"] = 10033324,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0C0E",
            },
        [10033324] = {
            ["Content"] = "交给我。",
            ["ContentJP"] = "任せろ！",
            ["DialogueId"] = 10033324,
            ["GUID"] = "191E0C38",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0C38",
            },
        [10033325] = {
            ["Content"] = "牵制住了。黎瑟！",
            ["ContentJP"] = "動きを止めたぞ！長官様！",
            ["DialogueId"] = 10033325,
            ["GUID"] = "191E0C62",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100333/191E0C62",
            },
        [10033401] = {
            ["Content"] = "快……撤……",
            ["ContentJP"] = "……撤退……を……",
            ["DialogueId"] = 10033401,
            ["GUID"] = "191E18DA",
            ["SpeakNpcId"] = 100311,
            ["VoiceName"] = "voice/$Locale$/story/1003/100334/191E18DA",
            },
        [10033402] = {
            ["Content"] = "……怪物……不止一只……有同伙！",
            ["ContentJP"] = "……化け物は……一匹じゃない……仲間がいるぞ！",
            ["DialogueId"] = 10033402,
            ["GUID"] = "191E1904",
            ["SpeakNpcId"] = 100311,
            ["VoiceName"] = "voice/$Locale$/story/1003/100334/191E1904",
            },
        [10033403] = {
            ["Content"] = "拦住它们两个……",
            ["ContentJP"] = "やつらを止めろ……",
            ["DialogueId"] = 10033403,
            ["GUID"] = "191E192E",
            ["SpeakNpcId"] = 100311,
            ["VoiceName"] = "voice/$Locale$/story/1003/100334/191E192E",
            },
        [10033404] = {
            ["Content"] = "……不行……防线被突破了……",
            ["ContentJP"] = "ダメだ……防衛線が突破された……！",
            ["DialogueId"] = 10033404,
            ["GUID"] = "191E1958",
            ["SpeakNpcId"] = 100311,
            ["VoiceName"] = "voice/$Locale$/story/1003/100334/191E1958",
            },
        [10033405] = {
            ["Content"] = "营救伤员，快，先去营救伤员！",
            ["ContentJP"] = "急げ！負傷者を救助が最優先だ！",
            ["DialogueId"] = 10033405,
            ["GUID"] = "191E1982",
            ["SpeakNpcId"] = 100311,
            ["VoiceName"] = "voice/$Locale$/story/1003/100334/191E1982",
            },
