        [10033502] = {
            ["Camera"] = "259.068359,-18.712982,40.941162,-0.000244,7.196711,167.766693,35.000015,1.5,false,DoNotOverride,1.2",
            ["Content"] = "我没事，黎瑟长官她……",
            ["ContentJP"] = "{性别:僕|私}は大丈夫。でもリズム長官が……",
            ["DialogueId"] = 10033502,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                [2] = "100304:Sad02",
                },
            ["FinalCamera"] = "256.6875,-29.730164,40.941162,-0.000244,7.596707,164.966385,35.000015,1.5,false,DoNotOverride,1.2",
            ["GUID"] = "191E296C",
            ["LookAt"] = {
                [1] = "100001:n(100304)",
                },
            ["NextDialogue"] = 10033503,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200021:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E296C",
            },
        [10033503] = {
            ["Camera"] = "14.822266,-56.511841,90.980835,-0.000244,-13.203759,38.555153,35.000015,157.581314,false,Manual,3.299097",
            ["Content"] = "没关系的，保护市民是我的责任……你们没事……就好。",
            ["ContentJP"] = "……気にしないで。市民を守るのは私の責務よ……皆さんが無事なら……それでいいの。",
            ["DialogueId"] = 10033503,
            ["FinalCamera"] = "11.332031,-52.260254,90.980835,-0.000245,-13.203704,37.151642,35.000015,157.581314,false,Manual,3.299097",
            ["GUID"] = "191E2996",
            ["NextDialogue"] = 10033504,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-2076.6875,-1091.334961,1321.631348,-0.000245,-29.209351,25.139265,45.000011,2077.543213,false,Manual,1.713872\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-2080.646484,-1082.892334,1321.631348,-0.000245,-29.209316,25.738663,45.000011,2077.543213,false,Manual,1.713872\"},duration{10}}}",
