            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E2A92",
            },
        [10033510] = {
