            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E2D32",
            ["bForbidSkipOptions"] = true,
            },
        [10033526] = {
            ["Content"] = "嗯，走吧。先离开下水道。",
            ["ContentJP"] = "うん、行こう。まずは下水道から出よう。",
            ["DialogueId"] = 10033526,
            ["GUID"] = "191E2D33",
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [10033527] = {
            ["Content"] = "再等等吧。",
            ["ContentJP"] = "もう少し待とう。",
            ["DialogueId"] = 10033527,
            ["GUID"] = "191E2D34",
            ["NextDialogue"] = 10033528,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [10033528] = {
            ["Content"] = "行啊，那等你准备好了我们再出去。",
            ["ContentJP"] = "分かった、じゃあ、準備できたら教えてくれ。",
            ["DialogueId"] = 10033528,
            ["GUID"] = "191E2D35",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100335/191E2D35",
            },
        [10033601] = {
            ["Content"] = "咦？不是说有人在这儿接我们嘛，他们人呢？",
            ["ContentJP"] = "あれ？ここでお迎えが待ってるんじゃなかったの？誰もいないじゃん。",
            ["DialogueId"] = 10033601,
            ["GUID"] = "191E39AA",
            ["NextDialogue"] = 10033602,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E39AA",
            },
        [10033602] = {
            ["Content"] = "看这里，墙上有一大片密集的弹孔。",
            ["ContentJP"] = "見て、壁一面に弾丸の痕が残ってる……",
            ["DialogueId"] = 10033602,
            ["GUID"] = "191E39D4",
            ["NextDialogue"] = 10033603,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E39D4",
            },
        [10033603] = {
            ["Content"] = "啧……接我们的人跟凶手撞上了？这下麻烦了啊。",
            ["ContentJP"] = "くそ……まさか、迎えに来た隊員が犯人と遭遇したんじゃ？面倒なことになったぜ。",
            ["DialogueId"] = 10033603,
            ["GUID"] = "191E39FE",
            ["NextDialogue"] = 10033604,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E39FE",
            },
        [10033604] = {
            ["Content"] = "……从弹孔的分布来看，凶手应该是往这边去了。我们也顺路去看看吧。",
            ["ContentJP"] = "……弾痕から見て、恐らく犯人はこっちに逃げたはず。はやく行こう。",
            ["DialogueId"] = 10033604,
            ["GUID"] = "191E3A28",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3A28",
            },
        [10033605] = {
            ["Content"] = "真是这边吗？附近什么也没有呀……",
            ["ContentJP"] = "本当にこっちで合ってるの？なんにもないよ？",
            ["DialogueId"] = 10033605,
            ["GUID"] = "191E3A52",
            ["NextDialogue"] = 10033606,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3A52",
            },
        [10033606] = {
            ["Content"] = "你们有没有感觉，这里的风力比其他地方强？",
            ["ContentJP"] = "……ここの風、他の場所より強くない？",
            ["DialogueId"] = 10033606,
            ["GUID"] = "191E3A7C",
            ["NextDialogue"] = 10033607,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3A7C",
            },
        [10033607] = {
            ["Content"] = "我上去看看。",
            ["ContentJP"] = "ちょっと上の方を調べてくるわ。",
            ["DialogueId"] = 10033607,
            ["GUID"] = "191E3AA6",
            ["NextDialogue"] = 10033608,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3AA6",
            },
        [10033608] = {
            ["Content"] = "哈，你的感觉还挺敏锐，上面这个管道不久前才被人破坏过。",
            ["ContentJP"] = "さすが勘が鋭いな。この上の配管に真新しい破損があった。",
            ["DialogueId"] = 10033608,
            ["GUID"] = "191E3AD0",
            ["NextDialogue"] = 10033609,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3AD0",
            },
        [10033609] = {
            ["Content"] = "从管道延伸的方向来看，凶手会从前面的出口附近出来。",
            ["ContentJP"] = "配管の方向から見て、犯人は出口の近くにいる可能性が高い。",
            ["DialogueId"] = 10033609,
            ["GUID"] = "191E3AFA",
            ["NextDialogue"] = 10033610,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3AFA",
            },
        [10033610] = {
            ["Content"] = "好，大家小心些。",
            ["ContentJP"] = "分かった。慎重に進もう。",
            ["DialogueId"] = 10033610,
            ["GUID"] = "191E3B24",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100336/191E3B24",
            },
        [10033611] = {
