            },
        [10033802] = {
            ["Content"] = "小仆从小仆从，走这边。",
            ["ContentJP"] = "こっちこっち！",
            ["DialogueId"] = 10033802,
            ["GUID"] = "191E5AA4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100338/191E5AA4",
            },
        [10033803] = {
            ["Content"] = "前方是内城，卡戎之民没有特殊许可禁止通行！",
            ["ContentJP"] = "ここから先は内城区だ。カロン族は特別な許可がない限り立ち入り禁止だ！",
            ["DialogueId"] = 10033803,
            ["GUID"] = "191E5ACE",
            ["NextDialogue"] = 10033804,
            ["SpeakNpcId"] = 100325,
            ["VoiceName"] = "voice/$Locale$/story/1003/100338/191E5ACE",
            },
        [10033804] = {
            ["Content"] = "哦哦，是你们啊。别那么凶，{性别：他们|她们}刚刚给卫戍部队帮了大忙。",
            ["ContentJP"] = "あれ、君たち！そんな怖い顔するな。この子たちは警備部隊に貢献してくれたばかりなんだから。",
            ["DialogueId"] = 10033804,
            ["GUID"] = "191E5AF8",
            ["NextDialogue"] = 10033805,
            ["SpeakNpcId"] = 100325,
            ["VoiceName"] = "voice/$Locale$/story/1003/100338/191E5AF8",
            },
        [10033805] = {
            ["Content"] = "你们来内城做什么？",
            ["ContentJP"] = "ところで、なぜ内城区に？",
            ["DialogueId"] = 10033805,
            ["GUID"] = "191E5B22",
            ["NextDialogue"] = 10033806,
            ["SpeakNpcId"] = 100325,
            ["VoiceName"] = "voice/$Locale$/story/1003/100338/191E5B22",
            },
        [10033806] = {
            ["Content"] = "我们想看看黎瑟长官的状况。",
            ["ContentJP"] = "リズム長官の様子を見に来た。",
            ["DialogueId"] = 10033806,
            ["GUID"] = "191E5B4C",
            ["NextDialogue"] = 10033807,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100338/191E5B4C",
            },
        [10033807] = {
            ["Content"] = "听说救回来一条命，还昏迷着。真要看她的话，我带你们进去吧。低调点，跟着我。",
            ["ContentJP"] = "ああ、長官なら、一命は取り留めたもののまだ意識を取り戻してないらしい。案内してあげるよ。ただし、あまり目立たないようにね。",
            ["DialogueId"] = 10033807,
            ["GUID"] = "191E5B76",
            ["SpeakNpcId"] = 100325,
            ["VoiceName"] = "voice/$Locale$/story/1003/100338/191E5B76",
            },
        [10033901] = {
            ["Camera"] = "24.498535,102.712585,126.646484,0.000073,-6.999646,-158.394653,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "（空气中弥漫的消毒水让鼻腔感到些许的刺激，落针可闻的房间中回荡着黎瑟平缓的呼吸。）",
            ["ContentJP"] = "消毒液の匂いが鼻を刺激し、静まり返った部屋には、リズムの穏やかな呼吸音だけが響いていた。",
            ["DialogueId"] = 10033901,
            ["FacialId"] = {
                [1] = "100360:Close",
                },
            ["FinalCamera"] = "27.636719,94.549805,126.646484,0.000073,-6.799651,-160.394623,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191E6AE2",
            ["NextDialogue"] = 10033902,
            ["RelatedWikiId"] = {
