        [10033905] = {
            ["Camera"] = "33.217773,125.854919,134.521484,0.000093,2.393059,111.061989,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你来了，跟那群内城士兵说清楚情况了？",
            ["ContentJP"] = "アウトサイダー、状況説明はもう済んだの？",
            ["DialogueId"] = 10033905,
