        [10033948] = {
            ["Camera"] = "127.84375,-20.15332,112.732666,0.002085,15.912045,-140.45549,30.000013,108.648788,false,Manual,3.232587",
            ["Content"] = "对了，第六军团还是蛮辛苦的，长官说入伍前三年都是封闭式训练，回不了家……如果姐姐想我的话，就经常看看内城那盏灯吧。",
            ["ContentJP"] = "そういえば、第六軍団って案外大変なんだよ。長官がいうには入隊後の三年間は隔離訓練で家に帰れないんだって……もし寂しくなったら、内城区の灯りを僕だと思って見るといい。",
            ["DialogueId"] = 10033948,
            ["FinalCamera"] = "133.529297,-27.189453,112.732666,0.002083,15.91197,-145.655502,30.000013,108.648788,false,Manual,3.232587",
            ["GUID"] = "191E7298",
            ["NextDialogue"] = 10033949,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"369.674805,49.414307,111.657959,0.0021,0.711986,-165.443069,30.000013,385.789124,false,Manual,2.978149\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"366.126953,61.830811,111.657959,0.0021,0.711986,-164.043228,30.000013,385.789124,false,Manual,2.978149\"},duration{10}}}",
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100358:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7298",
            },
        [10033949] = {
            ["Camera"] = "867.347656,-2098.635498,629.636597,0.002082,-14.284138,117.329636,45.0,2254.919678,false,Manual,1.2",
            ["Content"] = "我会好好在内城等你的。我会把薪水好好攒起来，让你过上好日子。到时候我们想看戏就看戏，想吃好吃的就吃好吃的……再也不会有人欺负我们了。",
            ["ContentJP"] = "内城区で待ってるよ。お金をいっぱい貯めて、姉さんにいい暮らしをさせるんだ。好きな時に劇を見に行ったり、美味しいものを食べたり……もう誰にも僕たちをいじめさせたりしないから。",
            ["DialogueId"] = 10033949,
            ["FinalCamera"] = "881.833008,-2091.153564,629.636597,0.002081,-14.284138,117.72963,45.0,2254.919678,false,Manual,1.2",
            ["GUID"] = "191E72C2",
            ["NextDialogue"] = 10033950,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"211.825195,92.396362,98.62915,0.002103,7.115499,-142.670944,30.000013,241.237091,false,Manual,2.770165\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"211.825195,92.396362,105.62915,0.002103,7.115499,-142.670944,30.000013,241.237091,false,Manual,2.770165\"},duration{8}}},\
PlayAnimation{_delay{5},ActorId{100358},AnimationId{\"Explain02_End\"},Duration{2}}\
}",
