        [10033950] = {
            ["Camera"] = "66.576172,-38.906006,130.142578,0.002075,2.315359,65.741318,40.0,62.173073,false,Manual,7.254174",
            ["Content"] = "布鲁斯……",
            ["ContentJP"] = "ブルース……",
            ["DialogueId"] = 10033950,
            ["FacialId"] = {
                [1] = "100304:Sad01",
                },
            ["FinalCamera"] = "62.260742,-36.960693,130.142578,0.002075,2.315359,65.740913,40.0,62.173073,false,Manual,7.254174",
            ["GUID"] = "191E72EC",
            ["NextDialogue"] = 10033951,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                [2] = "100358:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E72EC",
            },
        [10033951] = {
            ["Camera"] = "159.118164,62.682617,116.599609,0.002062,5.112949,-136.657822,30.000013,174.769302,false,Manual,3.415042",
            ["Content"] = "姐、姐姐，你怎么哭了！不用担心，不用担心，等三年期满我们就能见面啦！而且，说不定……说不定你运气好，明年就成了桂冠卡戎呢！",
            ["ContentJP"] = "姉さん、なんで泣くんだ！し、心配しないで……三年後には必ず会えるから！運が良ければ、来年には桂冠カロン族になってるかもしれないし！",
            ["DialogueId"] = 10033951,
            ["FacialId"] = {
                [1] = "100358:None",
                },
            ["FinalCamera"] = "161.53418,60.29541,116.599609,0.002064,5.112949,-139.257599,30.000013,174.769302,false,Manual,3.415042",
            ["GUID"] = "191E7316",
            ["NextDialogue"] = 10033952,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"529.967773,73.81665,178.095947,0.002119,-9.087621,-168.846649,30.000019,487.339325,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"527.376953,86.979492,178.095947,0.002119,-9.087621,-167.046463,30.000019,487.339325,false,Manual,1.2\"},duration{8}}},PlayAnimation{_delay{5},ActorId{100358},AnimationId{\"ScratchHead_End\"},Duration{2}}}",
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100358:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7316",
            },
        [10033952] = {
            ["Camera"] = "1558.825195,1094.241333,364.312744,0.00206,-9.084534,-145.467102,35.000008,1941.741211,false,Manual,1.2",
            ["Content"] = "到时候我们一起爬到城墙的最上面，让冰湖城的所有人都看到，我们有多了不起！",
            ["ContentJP"] = "そして、一緒に城壁の一番上まで登って、アイスレイク城のみんなに見せてやるんだ。僕たちがどれだけすごいかってのをね！",
            ["DialogueId"] = 10033952,
            ["FinalCamera"] = "1574.841797,1070.966309,364.312744,0.002059,-9.084534,-146.866806,35.000008,1941.741211,false,Manual,1.2",
            ["GUID"] = "191E7340",
            ["SpeakNpcId"] = 100358,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E7340",
            },
        [10033953] = {
            ["Content"] = "嗯，布鲁斯……我会……加油。我们……一起到……城墙上……",
            ["ContentJP"] = "うん、ブルース……私……頑張るから。一緒に……城壁……登ろう……",
            ["DialogueId"] = 10033953,
            ["GUID"] = "191E736A",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E736A",
            },
        [10033954] = {
            ["Camera"] = "22.037598,80.328857,85.623047,0.000103,13.600046,166.199295,28.0,226.057693,false,DoNotOverride,3.159981",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "黎瑟长官！你醒啦！你、你怎么在哭？做噩梦了吗？",
            ["ContentJP"] = "リズム！目覚めたのか！な、なんで泣いてるんだ？悪い夢でも見たのか？",
            ["DialogueId"] = 10033954,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["FinalCamera"] = "73.599609,67.932922,75.339844,0.000102,9.600083,166.399826,28.0,226.057693,false,DoNotOverride,3.159981",
