        [10033969] = {
            ["Camera"] = "141.86377,306.253906,122.765625,0.000177,5.989379,-155.498428,35.0,216.320572,false,DoNotOverride,3.374357",
            ["Content"] = "这是我秘密基地的钥匙，地址就写在钥匙的背面。你们能去那帮我拿一下刻有我名字的银色印章吗？",
            ["ContentJP"] = "私の秘密基地の鍵です。在り処は鍵の裏に刻まれています。そこで、私の名前が刻まれた銀色の印鑑を取ってきていただけませんか？",
            ["DialogueId"] = 10033969,
            ["FinalCamera"] = "144.689941,300.053467,122.765625,0.000177,5.989379,-155.498428,35.0,216.320572,false,DoNotOverride,3.374357",
            ["GUID"] = "191E760A",
            ["NextDialogue"] = 10033970,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"652.945312,463.934875,412.007812,0.000188,-23.608671,-148.696426,35.000008,216.320572,false,DoNotOverride,3.374357\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"625.39502,505.701294,412.007812,0.000183,-23.408648,-144.695618,35.000008,216.320572,false,DoNotOverride,3.374357\"},duration{5}}}",
            ["SpeakNpcId"] = 100360,
            ["TalkActionId"] = {
                [1] = "200021:ConfidentLR_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1003/100339/191E760A",
            },
        [10033970] = {
            ["Camera"] = "291.686035,147.772278,166.871094,-10.000484,-20.003922,-142.886566,35.000015,364.535095,false,DoNotOverride,3.069153",
            ["Content"] = "虽然现在没法亲自帮你，但写几封信拜托别人还是能做到的。",
            ["ContentJP"] = "現状、私自ら手を貸すことは難しいですが、代わりの者に手紙を出すことくらいはできます。",
            ["DialogueId"] = 10033970,
            ["FinalCamera"] = "296.286621,140.633057,172.496094,-10.001247,-21.203911,-145.486053,35.000015,364.535095,false,DoNotOverride,3.069153",
