            },
        [10034220] = {
            ["Camera"] = "-140.234375,456.795898,68.025391,0.000896,10.808064,-67.380486,35.000011,247.296616,false,Manual,4.532753",
            ["Content"] = "时候不早了，我们抓紧些，继续找那枚印章吧。",
            ["ContentJP"] = "{性别:さて|さぁ}、急いであの印鑑を探そう。",
            ["DialogueId"] = 10034220,
            ["FinalCamera"] = "-137.816406,457.798828,68.025391,0.000897,10.808064,-67.980507,35.000011,247.296616,false,Manual,4.532753",
            ["GUID"] = "191E9F38",
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-48.074219,-177.825195,242.457031,0.000911,-16.990921,99.013062,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-48.074219,-177.825195,242.457031,0.000915,-15.190948,99.012909,35.000011,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100342/191E9F38",
            },
        [10034221] = {
            ["Content"] = "（内城城墙下姐弟的合照，照片的右上角写着“黎瑟·费西尔”与“布鲁斯·费西尔”两个名字，还有庆祝弟弟布鲁斯通过第六军团考核的祝语。）",
            ["ContentJP"] = "内城の城壁の下で撮られた、姉弟の記念写真。写真の右上には「リズム・フィッシャー」と「ブルース・フィッシャー」の名が記され、弟・ブルースが第六軍団の試験に合格したことを祝う言葉が添えられている。",
            ["DialogueId"] = 10034221,
            ["GUID"] = "191E9F62",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100342/191E9F62",
            },
        [10034222] = {
            ["Content"] = "（看起来很久没使用过的口琴，比起黎瑟的爱好，更像某种礼物。）",
            ["ContentJP"] = "長い間使われた形跡のないハーモニカ。リズムの趣味というより、誰かから贈られたもののようだ。",
            ["DialogueId"] = 10034222,
            ["GUID"] = "191E9F8C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100342/191E9F8C",
            },
        [10034223] = {
            ["Camera"] = "7.019531,28.510742,50.533203,0.0,11.598098,-12.817424,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "锵锵——白找到印章啦！关键时刻还得靠我嘛。",
            ["ContentJP"] = "じゃーん、これなーんだ！やっぱりスノウってば頼りになる～",
            ["DialogueId"] = 10034223,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["FinalCamera"] = "8.574219,28.148438,50.533203,0.000001,15.598,-13.21839,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191E9FB6",
            ["LookAt"] = {
                [1] = "200021:p(cp2fixsimple33Point01)",
                },
            ["NextDialogue"] = 10034224,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{1.5},TargetPosition{\"413.886719,34.080078,67.716797,0.0,5.998928,-176.011871,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"415.066406,13.404297,67.716797,0.0,5.998934,-179.211777,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Alright_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100342/191E9FB6",
            },
        [10034224] = {
            ["Camera"] = "236.867188,146.151367,25.097656,0.000059,17.597742,-134.200272,35.000019,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哦？居然被你找到了，不错不错，奖励你一顶紫露花花环。",
            ["ContentJP"] = "おっ？やるじゃねぇか、チビ助。ご褒美にムラサキツユクサの花冠でもプレゼントしてやろう。",
            ["DialogueId"] = 10034224,
            ["FacialId"] = {
                [1] = "200021:Ahaha01",
                },
            ["FinalCamera"] = "236.867188,146.151367,25.097656,0.000054,19.797834,-134.200699,35.000019,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "191E9FE0",
            ["NextDialogue"] = 10034225,
            ["SpeakNpcId"] = 200021,
