            ["TalkActionId"] = {
                [1] = "100361:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1003/100343/191EAEA4",
            },
        [10034315] = {
            ["Camera"] = "142.187012,14.526367,158.126953,0.000148,-1.3962,155.668839,35.000011,185.386246,false,Manual,22.0",
            ["Content"] = "“桂冠卡戎”？这可不容易。拿到桂冠资格的都是强者中的强者。",
            ["ContentJP"] = "「桂冠カロン族」だと？なら話は早いじゃねぇか。桂冠になれるのは、強者の中の強者だけだからな。",
            ["DialogueId"] = 10034315,
            ["FacialId"] = {
