        [10034316] = {
            ["Camera"] = "290.523926,52.623901,96.710938,0.000174,5.403185,-169.918121,25.000006,291.195435,false,Manual,15.0",
            ["Content"] = "嗯，布鲁斯他……和我不一样。虽然都幸运地成为了“骸”，但“骸”之间也天差地别。他从小就很聪明……即使不需要努力练习也能很好地掌控魔法。",
            ["ContentJP"] = "ええ、私たちは運良く「骸」になれましたが、ブルースは……私とは違います。骸の中でも能力差は大きいのです。彼は幼い頃から賢く……努力せずとも魔法の扱いが上手かったんです。",
            ["DialogueId"] = 10034316,
            ["FacialId"] = {
                [1] = "200021:Unhappy02",
                },
            ["FinalCamera"] = "291.792969,45.107056,96.710938,0.000173,5.603186,-174.717438,25.000006,291.195435,false,Manual,15.0",
            ["GUID"] = "191EAEF8",
            ["LookAt"] = {
                [1] = "100001:n(100361)",
                },
            ["NextDialogue"] = 10034317,
            ["Scripts"] = "TurnTo{_delay{1},TurnToDescription{\"200021:n(100361)\"}}",
            ["SpeakNpcId"] = 100361,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1003/100343/191EAEF8",
            },
        [10034317] = {
            ["Camera"] = "50.372559,77.353577,99.699219,0.000192,14.002181,-36.722607,35.000008,127.422424,false,Manual,3.0",
            ["Content"] = "但即使如此，他还是很刻苦。所以他才能通过第六军团万里挑一的选拔考试，进入内城服役。",
            ["ContentJP"] = "その上、努力を惜しまない子でした。そのかいあって、数万人に一人の倍率だとされる第六軍団の選抜試験に合格し、内城区に入る資格を得たのです。",
            ["DialogueId"] = 10034317,
            ["FinalCamera"] = "57.093262,72.341003,101.791016,0.000192,14.002181,-36.722607,35.000008,115.580086,false,Manual,3.0",
            ["GUID"] = "191EAF22",
            ["LookAt"] = {
                [1] = "200021:n(200021)",
                [2] = "\
100361:n(100361)",
                },
            ["NextDialogue"] = 10034318,
            ["SpeakNpcId"] = 100361,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1003/100343/191EAF22",
            },
        [10034318] = {
            ["Camera"] = "-117.456543,432.085693,206.490234,0.000006,-14.597705,-63.5117,25.000002,649.314514,false,Manual,22.0",
            ["Content"] = "恭喜恭喜！万里挑一，就为了贵族老爷牙齿缝里抠出来的那几块骨头。",
            ["ContentJP"] = "へぇ、そりゃあめでたい！狭い門をくぐり抜けた挙句、ようやくご貴族様の食べ残しが拾えるようになったってわけか。",
            ["DialogueId"] = 10034318,
            ["FacialId"] = {
                [1] = "200021:Ahaha01",
                },
            ["FinalCamera"] = "-122.652832,442.513,211.927734,0.000008,-14.997681,-63.511803,25.000002,649.314514,false,Manual,22.0",
