            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1003/100343/191EB26A",
            },
        [10034337] = {
            ["Camera"] = "122.662598,421.170105,153.037109,0.000287,-5.398568,-98.948692,35.000015,402.692322,false,Manual,5.0",
            ["Content"] = "想好了就来找我吧，报酬少不了你，一切都是为了冰湖城的安全。",
            ["ContentJP"] = "返事が決まったら、アタシのところへこい。報酬は弾むぜ。もっとも、アイスレイク城の安全のためでもあるからな。",
            ["DialogueId"] = 10034337,
            ["FinalCamera"] = "129.948242,420.022461,153.037109,0.000287,-5.398568,-98.948692,35.000019,402.692322,false,Manual,5.0",
