            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "200002:n(100304)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBD68",
            },
        [10034405] = {
            ["Content"] = "嚯，街上全是十三军团的人，好大阵仗。",
            ["ContentJP"] = "ほれ、見ろ。第十三軍団の兵士がうじゃうじゃいやがる。",
            ["DialogueId"] = 10034405,
            ["GUID"] = "191EBDBC",
            ["NextDialogue"] = 10034406,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBDBC",
            },
        [10034406] = {
            ["Content"] = "琳恩长官为什么独自向着<H>内城</>走了？",
            ["ContentJP"] = "リーン長官、一人で<H>内城区</>に向かったけど……何をしに行ったんだろ？",
            ["DialogueId"] = 10034406,
            ["GUID"] = "191EBDE6",
            ["NextDialogue"] = 10034407,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBDE6",
            },
        [10034407] = {
            ["Content"] = "炼金院、执政厅、第六军团驻扎地都在内城，过去无非就是调遣、应酬、问责、叙旧之类的吧。",
            ["ContentJP"] = "錬金院、行政庁、第六軍団の駐屯地――どれも内城区にあるからな。せいぜい、人員のやりくり、お偉ぇさんの接待、責任の追及、昔馴染みとの顔合わせ……そんなとこだろ。",
            ["DialogueId"] = 10034407,
            ["GUID"] = "191EBE10",
            ["NextDialogue"] = 10034408,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE10",
            },
        [10034408] = {
            ["Content"] = "反正与我们无关，我的人生准则之一就是，少问多做，才能活得更久。",
            ["ContentJP"] = "ま、オレたちには関係ねぇことだ。「詮索せずに働け」――それが長生きの秘訣だぜ。",
            ["DialogueId"] = 10034408,
            ["GUID"] = "191EBE3A",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE3A",
            },
        [10034410] = {
            ["Content"] = "就是在这里接货吧！哇啊——怎么有雪狼！",
            ["ContentJP"] = "ここだよね！わあっ――なんで白いオオカミがいるの！？",
            ["DialogueId"] = 10034410,
            ["GUID"] = "191EBE64",
            ["NextDialogue"] = 10034411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE64",
            },
        [10034411] = {
            ["Content"] = "你们就是琳恩长官说的本地人小队吧，货物还没来，跟我把这片区域清理出来。",
            ["ContentJP"] = "お前らがリーン長官の言ってた連中か。荷物はまだ届いてねぇから、先にこの辺りの<Default note=\"text:エジュウ\">穢獣</>を片付けるぞ。",
            ["DialogueId"] = 10034411,
            ["GUID"] = "191EBE8E",
            ["NextDialogue"] = 10034412,
            ["SpeakNpcId"] = 100310,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE8E",
            },
        [10034412] = {
            ["Content"] = "唉，又要多干一份活喽。",
            ["ContentJP"] = "はあ……また仕事がひとつ増えちまったか。",
            ["DialogueId"] = 10034412,
            ["GUID"] = "191EBEB8",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBEB8",
            },
        [10034413] = {
            ["Content"] = "警戒线都拉起来，动作快！",
            ["ContentJP"] = "警戒線を張れ、急げ！",
            ["DialogueId"] = 10034413,
            ["GUID"] = "191EBE3B",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE3B",
            },
        [10034414] = {
            ["Content"] = "冰湖城这几日宵禁，没有许可禁止随意走动。",
            ["ContentJP"] = "アイスレイク城はここ数日、夜間外出禁止だ。許可のない移動は一切禁止！",
            ["DialogueId"] = 10034414,
            ["GUID"] = "191EBE3C",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE3C",
            },
        [10034415] = {
            ["Content"] = "银烛狂欢之前肯定能结案，这些花花绿绿的装饰就放着吧。",
            ["ContentJP"] = "銀燭祭りが始まる前には、必ずこの事件を終わらせる。派手な飾り付けはそのままでいい。",
            ["DialogueId"] = 10034415,
            ["GUID"] = "191EBE3D",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE3D",
            },
        [10034416] = {
            ["Content"] = "通讯测试，一二三一二三，通讯测试，一二三，能听到吗？好，我这儿听着也没问题。",
            ["ContentJP"] = "通信テスト、いち・に・さん、いち・に・さん。……通信テスト、いち・に・さん、聞こえるか？よし、こっちも問題なし。",
            ["DialogueId"] = 10034416,
            ["GUID"] = "191EBE3E",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE3E",
            },
        [10034417] = {
            ["Content"] = "说是宵禁，怎么白天也不让出去啊？",
            ["ContentJP"] = "夜間外出禁止だって言うけど、なんで昼間も出られないんだよ？",
            ["DialogueId"] = 10034417,
            ["GUID"] = "191EBE40",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE40",
            },
        [10034418] = {
            ["Content"] = "该死，这批新鲜霜脊鱼卖不出去了。",
            ["ContentJP"] = "まずいな、この釣りたての霜降りトゲウオ、腐ってしまうんじゃないか。",
            ["DialogueId"] = 10034418,
            ["GUID"] = "191EBE41",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE41",
            },
        [10034419] = {
            ["Content"] = "噢，我心爱的女士，这个夜晚我孤枕难眠，明明我们只隔着两条街的距离却无法相见……",
            ["ContentJP"] = "ああ、わが愛するレディよ。今宵は一人でどうしても眠れないんだ。たった二つの街角しか離れてないのに、貴女に会えない......",
            ["DialogueId"] = 10034419,
            ["GUID"] = "191EBE42",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE42",
            },
        [10034420] = {
            ["Content"] = "长官行行好啊，我不过去干活，全家都要饿死了……",
            ["ContentJP"] = "兵士様、どうかご慈悲を！働きに行かなければ、家族全員が飢え死にします。",
            ["DialogueId"] = 10034420,
            ["GUID"] = "191EBE43",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE43",
            },
        [10034421] = {
            ["Content"] = "怎么老是你？当心长官送你全家吃牢饭！",
            ["ContentJP"] = "またお前か？長官様がお前の家族全員を牢屋入りにさせちまうぞ、さっさと消えろ！",
            ["DialogueId"] = 10034421,
            ["GUID"] = "191EBE44",
            ["VoiceName"] = "voice/$Locale$/story/1003/100344/191EBE44",
            },
        [10034501] = {
            ["Camera"] = "984.259766,-313.733643,236.012207,0.000085,-9.598621,162.389984,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "办事挺麻利啊，不错。一起在这等运货的人过来吧。",
            ["ContentJP"] = "なかなか手際がいいじゃないか。こっちに来て一緒に待とう。",
            ["DialogueId"] = 10034501,
            ["FinalCamera"] = "984.259766,-313.733643,243.88623,0.000086,-9.998625,162.389923,35.000011,100000.0,false,Manual,22.0",
