        [10034517] = {
            ["Camera"] = "288.396484,340.865479,272.666504,0.000028,-21.39267,-98.97049,20.0,100000.0,false,Manual,22.0",
            ["Content"] = "你们放跑的“卡戎狩猎”嫌疑人前段时间流窜到了内城，残害了陛下的子民，还把仇恨索拉之民的涂鸦画得到处都是——这难道不是你们的失职吗！",
            ["ContentJP"] = "お前らが取り逃がした「カロン狩り」の容疑者が、先日内城区に潜り込んで陛下の民を殺し、ソラへの暴言をあっちこっち落書きして回ってるらしい――これが失態じゃないと言えるのか！",
            ["DialogueId"] = 10034517,
            ["FinalCamera"] = "306.296875,337.759277,272.666504,0.000026,-20.792625,-100.170906,20.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "191ECFF2",
