            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ECFF2",
            },
        [10034518] = {
            ["Camera"] = "365.872009,5.727009,151.48291,5.003078,-8.593204,-140.975723,20.000011,100000.0,false,Manual,22.0",
            ["Content"] = "全面戒严既是为了抓捕嫌疑人，也是为了封锁消息。若是索拉被怪物杀死在内城的消息传出去，你们这些家伙全都得上军事法庭！",
            ["ContentJP"] = "城の封鎖は容疑者を捕まえるためでもあるが、情報を外に漏らさないためでもある。もし内城区でソラが化け物に殺されたなんて話が広まったら、お前らは全員罪人扱いだ！",
            ["DialogueId"] = 10034518,
            ["FinalCamera"] = "365.872009,5.727009,156.694824,5.00317,-9.193209,-141.574554,20.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191ED01C",
