            },
        [10034519] = {
            ["Camera"] = "301.061676,-90.123116,187.39209,0.000131,-17.79336,-7.569943,32.000004,95.417534,false,Manual,3.0",
            ["Content"] = "怪不得十三军团大老远跑过来，还说什么为了冰湖城的安全，闹半天原来是<H>内城的索拉老爷出事了</>……",
            ["ContentJP"] = "なるほどな、アイスレイク城の安全のためとかぬかしやがって……本当は<H>内城区のお偉いさんがやられた</>からってわけか。",
            ["DialogueId"] = 10034519,
            ["FinalCamera"] = "301.061676,-90.123116,187.39209,0.000132,-17.393343,-7.56995,36.0,95.417534,false,Manual,3.0",
            ["GUID"] = "191ED046",
