            },
        [10034530] = {
            ["Camera"] = "313.703003,-7.806791,124.205078,0.000106,14.197558,-47.393547,35.000015,116.556152,false,Manual,4.0",
            ["Content"] = "你是指搬弹药箱误触引爆，还是指堵管道时时撞坏水闸让大伙白忙活半天？",
            ["ContentJP"] = "確かに――弾薬箱を誤爆させたり、配管を塞ぐ時に水門ぶっ壊してみたり……ずいぶん無駄手間を増やしてくれてたな？",
            ["DialogueId"] = 10034530,
            ["FacialId"] = {
                [1] = "200021:Unhappy02",
                },
            ["GUID"] = "191ED214",
            ["LookAt"] = {
