            },
        [10034531] = {
            ["Camera"] = "426.979126,-187.174683,184.529053,0.000142,-24.601282,121.190933,35.000019,348.247833,false,Manual,2.8",
            ["Content"] = "呃……那些是意外，意外！",
            ["ContentJP"] = "うっ……そ、それはアクシデントだよ、アクシデント！",
            ["DialogueId"] = 10034531,
            ["FacialId"] = {
                [1] = "200002:Syouganai01",
