            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100345/191ED3B8",
            },
        [10034541] = {
            ["Content"] = "我也缺，能帮我搞点月石吗？",
            ["ContentJP"] = "そういえば、{性别:僕|私}も月ノ石が欲しいんだけど、ついでに取って来てくれない？",
            ["DialogueId"] = 10034541,
            ["GUID"] = "191ED3E2",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10034542,
            },
        [10034542] = {
