            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF044",
            },
        [10034715] = {
            ["Content"] = "各个区域都有士兵驻守，是已经完成了封锁吗？",
            ["ContentJP"] = "どのエリアにも兵士が配置されてる。どうやら、城の封鎖は済んだようだね。",
            ["DialogueId"] = 10034715,
            ["GUID"] = "191EF06E",
            ["NextDialogue"] = 10034716,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF06E",
            },
        [10034716] = {
            ["Content"] = "看来是。接下来随时可能遇敌。目标的身手我们是领教过的，务必当心。",
            ["ContentJP"] = "いつ敵と遭遇してもおかしくありませんから。やつの実力はもうご存じでしょう、警戒を怠らないでください。",
            ["DialogueId"] = 10034716,
            ["GUID"] = "191EF098",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF098",
            },
        [10034717] = {
            ["Content"] = "先去找克莱夫留下的标记吧。",
            ["ContentJP"] = "とりあえずクレフが残した印を探そうぜ。",
            ["DialogueId"] = 10034717,
            ["GUID"] = "191EF0C2",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100347/191EF0C2",
