            ["TalkActionId"] = {
                [1] = "200021:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1003/100348/191F012A",
            },
        [10034818] = {
            ["Camera"] = "-87.959473,-40.362305,149.193604,0.000196,-4.19418,55.214046,40.0,237.274918,false,Manual,3.0",
            ["Content"] = "我发现了，头顶这些布条的材质和袭击现场的帷幕是一样的。不过我们现在已经找到了这里，看来没什么意义了。",
            ["ContentJP"] = "気づいたんだけど、天井にぶら下がっている布切れの材質、事件現場で見た幕布と同じものだ。でも、ここを突き止めた以上、大した意味はないか。",
            ["DialogueId"] = 10034818,
            ["FinalCamera"] = "-89.506348,-39.294922,149.193604,0.000197,-3.594148,55.013935,40.0,237.274918,false,Manual,3.0",
            ["GUID"] = "191F0154",
