            },
        [10035008] = {
            ["Content"] = "嘁，二流货色。",
            ["ContentJP"] = "ちっ、二流のザコが。",
            ["DialogueId"] = 10035008,
            ["GUID"] = "191F2080",
            ["NextDialogue"] = 10035009,
