            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F2080",
            },
        [10035009] = {
            ["Content"] = "琳恩长官，我来协助您！",
            ["ContentJP"] = "リーン長官、お手伝いします！",
            ["DialogueId"] = 10035009,
            ["GUID"] = "191F20AA",
            ["NextDialogue"] = 10035010,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F20AA",
            },
        [10035010] = {
            ["Content"] = "我们也上吧。",
            ["ContentJP"] = "私たちも行こう！",
            ["DialogueId"] = 10035010,
            ["GUID"] = "191F20D4",
            ["NextDialogue"] = 10035011,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F20D4",
            },
        [10035011] = {
            ["Content"] = "像上次那样，奥特赛德灵活牵制，我来寻找机会。",
            ["ContentJP"] = "この前と同じように、アウトサイダーはやつ動きを牽制して。私はその隙を狙うから。",
            ["DialogueId"] = 10035011,
            ["GUID"] = "191F20FE",
            ["NextDialogue"] = 10035012,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F20FE",
            },
        [10035012] = {
            ["Content"] = "没问题。",
            ["ContentJP"] = "了解。",
            ["DialogueId"] = 10035012,
            ["GUID"] = "191F2128",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F2128",
            },
        [10035013] = {
            ["Content"] = "默契的配合。你们证明了自己的价值，值得嘉奖。",
            ["ContentJP"] = "なかなか息が合うな。お前らは見事にその価値を証明した。褒めてやろう。",
            ["DialogueId"] = 10035013,
            ["GUID"] = "191F2152",
            ["NextDialogue"] = 10035014,
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F2152",
            },
        [10035014] = {
            ["Content"] = "那我就再教你们一个新的道理吧。",
            ["ContentJP"] = "褒美に、新しい掟を教えてやる。",
            ["DialogueId"] = 10035014,
            ["GUID"] = "191F217C",
            ["NextDialogue"] = 10035015,
            ["SpeakNpcId"] = 200022,
            ["VoiceName"] = "voice/$Locale$/story/1003/100350/191F217C",
            },
