            ["NextDialogue"] = 10035210,
            },
        [10035210] = {
            ["Camera"] = "-75.948898,-23.243881,162.542236,0.000282,-10.804621,24.274958,40.0,119.498253,false,Manual,8.0",
            ["Content"] = "我明白你的意思，是我做出选择的时候了……",
            ["ContentJP"] = "言いたいことはわかるわ。決断をしないと……",
            ["DialogueId"] = 10035210,
            ["FacialId"] = {
                [1] = "100304:Close",
                },
            ["FinalCamera"] = "-77.361824,-20.11338,162.542236,0.000282,-10.404604,22.675148,40.0,119.498253,false,Manual,8.0",
            ["GUID"] = "191F41A4",
