            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F41A4",
            },
        [10035211] = {
            ["Content"] = "那就做回平时的你吧。",
            ["ContentJP"] = "自分の心に従いなよ。",
            ["DialogueId"] = 10035211,
