            ["Camera"] = "-151.905182,-13.076996,141.362305,0.000255,-2.60461,19.078295,35.0,193.682495,false,Manual,8.0",
            ["Content"] = "那个不会放弃，为了保护市民拼尽全力的你。",
            ["ContentJP"] = "いつもの{性别:君|あなた}だったら、絶対に諦めたりしない。",
            ["DialogueId"] = 10035212,
            ["FinalCamera"] = "-149.821655,-19.036041,141.362305,0.000255,-2.604604,19.478231,35.0,193.682495,false,Manual,8.0",
            ["GUID"] = "191F41F8",
            ["NextDialogue"] = 10035215,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{5}},\
PlayAnimation{ActorId{100001},AnimationId{\"Angry01_End\"},Duration{5}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F41F8",
            },
        [10035213] = {
            ["Content"] = "让我们来就来，让我们走就走。这个十三军团我是一点都忍不了了。",
            ["ContentJP"] = "利用するだけ利用して、用が済んだら突き放すなんて。 第十三軍団め、ただじゃ済まさないから{性别:な|ね}。",
            ["DialogueId"] = 10035213,
            ["GUID"] = "191F4222",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10035214,
            },
        [10035214] = {
