                },
            ["NextDialogue"] = 10035251,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:ScratchHead_Start",
                [2] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4834",
            },
        [10035251] = {
            ["Camera"] = "230.964554,123.720169,183.445557,0.000094,-14.6028,-143.350281,30.000008,100000.0,false,Manual,22.0",
            ["Content"] = "唔，我也不会……黎瑟长官呢？",
            ["ContentJP"] = "んー、スノウも無理……リズムは？",
            ["DialogueId"] = 10035251,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "191F485E",
            ["LookAt"] = {
                [1] = "200021:n(200002)",
                [2] = "100304:n(200002)",
                [3] = "100001:n(200002)",
                },
            ["NextDialogue"] = 10035252,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200002},AnimationId{\"ScratchHead_Start\"},Duration{2}},\
PlayAnimation{ActorId{200002},AnimationId{\"ScratchHead_End\"},Duration{1}},\
LookAt{LookAtDescription{\"200002:n(100304)\"}},\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200021:ScratchHead_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F485E",
            },
        [10035252] = {
            ["Camera"] = "-56.100571,-8.342358,115.075195,0.000082,8.198917,-0.569315,30.000013,100000.0,false,Manual,22.0",
            ["Content"] = "抱歉，我说过我五音不全……唉，如果当时布鲁斯缠着我听录音带的时候，我没有偷偷睡觉就好了。",
            ["ContentJP"] = "ええと、前にも言ったけど、私音痴なの……はぁ、ブルースに一緒に聞こうってねだられた時、居眠りなんてするんじゃなかった……",
            ["DialogueId"] = 10035252,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["GUID"] = "191F4888",
            ["LookAt"] = {
                [1] = "200021:n(100304)",
                [2] = "200002:n(100304)",
                [3] = "100001:n(100304)",
                [4] = "100304:n(100304)",
                },
            ["NextDialogue"] = 10035253,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4888",
            },
        [10035253] = {
            ["Content"] = "等等……布鲁斯……他就是个狂热歌剧迷，我记得他在秘密基地里留下了很多录音带！虽然只能用笨办法全听一遍，但，说不定能找到那首歌！",
            ["ContentJP"] = "……そうだ、ブルース……あの子オペラの大ファンなの。秘密基地にカセットテープがたくさん残っていたはずよ。一つずつ聞いて行けば、あなたが聞いた曲が見つかるかも！",
            ["DialogueId"] = 10035253,
            ["GUID"] = "191F48B2",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(100001)",
                [3] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10035254,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"100304:n(100304)\"}},\
PlayAnimation{ActorId{100304},AnimationId{\"Sigh_End\"},Duration{1}},\
PlayAnimation{ActorId{100304},AnimationId{\"Think_Start\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F48B2",
            },
        [10035254] = {
            ["Camera"] = "-314.120422,323.028412,138.915283,0.0001,-2.600881,-44.171185,30.000002,100000.0,false,Manual,22.0",
            ["Content"] = "好家伙！谢谢布鲁斯，哥们儿帮大忙了。队长，咱们再回一趟那个秘密基地吧。",
            ["ContentJP"] = "ナイス、ブルース！そんじゃ、さっそくあの秘密基地に戻ろうぜ。",
            ["DialogueId"] = 10035254,
            ["GUID"] = "191F48DC",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(200021)",
                [3] = "100304:n(200021)",
                [4] = "100001:n(200021)",
                },
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F48DC",
            },
        [10035255] = {
            ["Content"] = "由冰湖城开往迪斯玛尼亚的列车将在一小时后出发。祝第十三军团返程顺利，荣耀尽归吾皇！",
            ["ContentJP"] = "アイスレイク城発ディズマニア行きの列車は、1時間後に出発します。第十三軍団が無事に帰還することを願っています。皇帝に栄光あれ！",
            ["DialogueId"] = 10035255,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "191F4906",
            ["SpeakNpcName"] = "Cp2CharacterName30",
            ["VoiceName"] = "voice/$Locale$/story/1003/100352/191F4906",
            },
        [10035301] = {
            ["Content"] = "收集这么多录音带，你弟弟是不是很富有呀！",
            ["ContentJP"] = "すごい量だね……弟さん、すごいお金持ちなんじゃないの？",
            ["DialogueId"] = 10035301,
            ["GUID"] = "191F5092",
            ["NextDialogue"] = 10035302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5092",
            },
        [10035302] = {
            ["Content"] = "不是的，那些都是他从朋友那里翻录的。",
            ["ContentJP"] = "ううん、全部お友だちのをダビングしたものよ。",
            ["DialogueId"] = 10035302,
            ["GUID"] = "191F50BC",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F50BC",
            },
        [10035303] = {
            ["Content"] = "旋律很像，但不太一样，凶手的声音更悲伤一些。",
            ["ContentJP"] = "うーん、似てるけど少し違う。もっと悲しい雰囲気のだった。",
            ["DialogueId"] = 10035303,
            ["GUID"] = "191F50E6",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F50E6",
            },
        [10035304] = {
            ["Content"] = "耳朵，我的耳朵！这也能叫歌吗！布鲁斯暗算我！",
            ["ContentJP"] = "み、耳が……これ歌っていうより、ブルースのいたずらなんじゃ？！",
            ["DialogueId"] = 10035304,
            ["GUID"] = "191F5110",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5110",
            },
        [10035305] = {
            ["Content"] = "这个……感觉不太像。",
            ["ContentJP"] = "これも……違う。",
            ["DialogueId"] = 10035305,
            ["GUID"] = "191F513A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F513A",
            },
        [10035306] = {
            ["Camera"] = "375.742188,-433.851562,288.041016,0.00005,-17.800415,125.025429,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "这些就是全部了吗？",
            ["ContentJP"] = "他にはないの？",
            ["DialogueId"] = 10035306,
            ["FinalCamera"] = "317.1875,-472.192383,288.041016,0.000045,-19.000452,121.826225,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191F5164",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "200002:n(100001)",
                [3] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10035307,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100353/191F5164",
            },
        [10035307] = {
            ["Camera"] = "41.957031,83.793945,112.646484,0.000084,10.397767,-108.765564,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "没有？",
            ["ContentJP"] = "ええ？",
            ["DialogueId"] = 10035307,
            ["FacialId"] = {
                [1] = "200021:Shock02",
                },
            ["FinalCamera"] = "43.648438,88.827148,111.683594,0.000084,10.397767,-108.765564,25.000006,100000.0,false,Manual,22.0",
