        [10035401] = {
            ["Content"] = "……凶手果然还活着！",
            ["ContentJP"] = "……やっぱり生きて――！",
            ["DialogueId"] = 10035401,
            ["GUID"] = "191F60FA",
            ["NextDialogue"] = 10035402,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F60FA",
            },
        [10035402] = {
            ["Content"] = "好家伙，自己找上门来了……",
            ["ContentJP"] = "ほぅ、探す手間が省けたぜ……",
            ["DialogueId"] = 10035402,
            ["GUID"] = "191F6124",
            ["NextDialogue"] = 10035403,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F6124",
            },
        [10035403] = {
            ["Content"] = "“凶手”……",
            ["ContentJP"] = "「犯人」か……",
            ["DialogueId"] = 10035403,
            ["GUID"] = "191F614E",
            ["NextDialogue"] = 10035404,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F614E",
            },
        [10035404] = {
            ["Content"] = "看来，直到最后，他们也，没告诉你，真相。果然十三军团，也是，一丘之貉。",
            ["ContentJP"] = "どうやら……最後まで……真相を……知らされなかったようだな……第十三軍団も……所詮その程度の連中だ。",
            ["DialogueId"] = 10035404,
            ["GUID"] = "191F6178",
            ["NextDialogue"] = 10035405,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName01",
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F6178",
            },
        [10035405] = {
            ["Content"] = "真相？你在说什么……",
            ["ContentJP"] = "真相？何のこと……",
            ["DialogueId"] = 10035405,
            ["GUID"] = "191F61A2",
            ["NextDialogue"] = 10035406,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F61A2",
            },
        [10035406] = {
            ["Content"] = "这怪物在拖延时间，先制服它！",
            ["ContentJP"] = "時間稼ぎに決まってる！とっとと捕まえようぜ！",
            ["DialogueId"] = 10035406,
            ["GUID"] = "191F61CC",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100354/191F61CC",
            },
