                [1] = "100331:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100357/191F93AC",
            },
        [10035711] = {
            ["Camera"] = "-141.865234,31.176758,158.599976,-0.000031,13.99628,-38.820576,25.0,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "那种东西早就碎在了实验台上。",
            ["ContentJP"] = "そんなの、とっくの昔に砕け散ったよ。",
            ["DialogueId"] = 10035711,
            ["FinalCamera"] = "-132.458984,42.869141,158.599976,-0.000031,13.796285,-42.620617,25.0,335.406189,false,DoNotOverride,1.2",
            ["GUID"] = "191F93D6",
            ["NextDialogue"] = 10035712,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100357/191F93D6",
            },
        [10035712] = {
            ["Camera"] = "147.782227,-325.042969,147.337708,0.000036,5.995984,-31.222105,25.0,335.406189,false,DoNotOverride,1.2",
            ["Content"] = "那就让我们把它再次拼起来吧，然后一起以人的身份逃出去。",
            ["ContentJP"] = "なら、もう一度繋ぎ合わせればいい。そして「人」として、この地獄を抜け出すんだ。",
            ["DialogueId"] = 10035712,
            ["FinalCamera"] = "153.202148,-316.107422,147.337708,0.000036,5.995984,-31.222105,25.0,335.406189,false,DoNotOverride,1.2",
            ["GUID"] = "191F9400",
            ["NextDialogue"] = 10035713,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["TalkActionId"] = {
                [1] = "100331:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100357/191F9400",
            },
        [10035713] = {
            ["Camera"] = "255.836914,-351.580078,219.478699,0.000112,-5.004336,131.172974,25.0,374.165375,false,Manual,1.908222",
            ["Content"] = "……白日做梦。",
            ["ContentJP"] = "……寝言はよしてよ。",
            ["DialogueId"] = 10035713,
            ["FinalCamera"] = "273.556641,-371.847656,221.835327,0.000112,-5.004336,131.172974,25.0,374.165375,false,Manual,1.908222",
            ["GUID"] = "191F942A",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "100328:n(100331)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100357/191F942A",
            },
        [10035801] = {
            ["Content"] = "测试开始。这次的敌人比较罕见，做好数据记录。",
            ["ContentJP"] = "実験を再開する。今回は珍しい相手を用意した。記録を怠るな。",
            ["DialogueId"] = 10035801,
            ["GUID"] = "191FA29A",
            ["NextDialogue"] = 10035802,
            ["SpeakNpcName"] = "Cp2CharacterName04",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA29A",
            },
        [10035802] = {
            ["Content"] = "是，老师！",
            ["ContentJP"] = "了解です、先生！",
            ["DialogueId"] = 10035802,
            ["GUID"] = "191FA2C4",
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA2C4",
            },
        [10035803] = {
            ["Content"] = "虽然我们被抓了，但是敢给我们武器，那就让你们尝尝神的怒火！",
            ["ContentJP"] = "確かに投降はしたが、まさかノコノコ武器を渡して来るとはな……神の怒りを思い知るがいい！",
            ["DialogueId"] = 10035803,
            ["GUID"] = "191FA2EE",
            ["NextDialogue"] = 10035804,
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA2EE",
            },
        [10035804] = {
            ["Content"] = "海伯利亚人，堕落的亵渎者，竟然造出这样的怪物！杀了它！",
            ["ContentJP"] = "ヒュペリアめ、神を冒涜する堕落者が！こんな化け物を作るなど……万死に値する！",
            ["DialogueId"] = 10035804,
            ["GUID"] = "191FA318",
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA318",
            },
        [10035805] = {
            ["Content"] = "放，放过我们，我们明明已经投降了啊！",
            ["ContentJP"] = "ま、待て……見逃してくれ。とっくに俺たちは投降してるんだ！",
            ["DialogueId"] = 10035805,
            ["GUID"] = "191FA342",
            ["NextDialogue"] = 10035806,
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA342",
            },
        [10035806] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 10035806,
            ["GUID"] = "191FA36C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10035807,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName02",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA36C",
            },
        [10035807] = {
            ["Content"] = "九神啊……！请怜悯我，赐我智慧，赐我力量，赐我庇护……！",
            ["ContentJP"] = "神よ……！どうか……知恵とご加護を……！",
            ["DialogueId"] = 10035807,
            ["GUID"] = "191FA396",
            ["NextDialogue"] = 10035808,
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA396",
            },
        [10035808] = {
            ["Content"] = "抱歉。",
            ["ContentJP"] = "すまない……",
            ["DialogueId"] = 10035808,
            ["GUID"] = "191FA3C0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10035809,
            ["SpeakNpcId"] = 100331,
            ["SpeakNpcName"] = "Cp2CharacterName03",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA3C0",
            },
        [10035809] = {
            ["Content"] = "啊啊……宽恕我，宽恕我……",
            ["ContentJP"] = "ああ……お許しを……どうか……",
            ["DialogueId"] = 10035809,
            ["GUID"] = "191FA3EA",
            ["SpeakNpcName"] = "Cp2CharacterName31",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA3EA",
            },
        [10035810] = {
            ["Content"] = "上啊，让我看看你们到底谁才是真正的恶魔，哈哈哈。",
            ["ContentJP"] = "いいぞ、もっとやれ！どっちが本当の悪魔か見せてよ！あははは。",
            ["DialogueId"] = 10035810,
            ["GUID"] = "191FA414",
            ["NextDialogue"] = 10035811,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA414",
            },
        [10035811] = {
            ["Content"] = "真好用，配合这段时间注射的抑制剂，稳定性也高了不少。",
            ["ContentJP"] = "悪くない威力だね。最近の抑制剤との相性も悪くない。",
            ["DialogueId"] = 10035811,
            ["GUID"] = "191FA43E",
            ["NextDialogue"] = 10035812,
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA43E",
            },
        [10035812] = {
            ["Content"] = "这样下去把改造实验推广向其他军团也指日可待了。",
            ["ContentJP"] = "これなら戦力として使えるようになるのも時間の問題だな。",
            ["DialogueId"] = 10035812,
            ["GUID"] = "191FA468",
            ["SpeakNpcName"] = "Cp2CharacterName04",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA468",
            },
        [10035813] = {
            ["Content"] = "实验数据采集完成，你们自己回去吧，我要去给老师提交报告。",
            ["ContentJP"] = "採取も済んだことだし、自分たちで牢に戻りな。ボクは報告書を仕上げないと。",
            ["DialogueId"] = 10035813,
            ["GUID"] = "191FA492",
            ["SpeakNpcName"] = "Cp2CharacterName05",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191FA492",
            },
        [10035814] = {
            ["Content"] = "各项数据都在波动范围之内，这次很有希望！",
            ["ContentJP"] = "各データ、すべて許容範囲内だ。今回は期待できそうだぞ！",
            ["DialogueId"] = 10035814,
            ["GUID"] = "191F942B",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942B",
            },
        [10035815] = {
            ["Content"] = "怎么还是比不上36号和47号，到底哪里出了问题……",
            ["ContentJP"] = "でもなんでだ……No. 36やNo. 47には及ばない。いったい何が足りないんだ……",
            ["DialogueId"] = 10035815,
            ["GUID"] = "191F942C",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942C",
            },
        [10035816] = {
            ["Content"] = "可以考虑加大剂量了。",
            ["ContentJP"] = "もう少し投薬量を増やすって手もあるな。",
            ["DialogueId"] = 10035816,
            ["GUID"] = "191F942D",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942D",
            },
        [10035817] = {
            ["Content"] = "还是得强化近身作战能力。",
            ["ContentJP"] = "やっぱり近接戦闘の強化は外せないな。",
            ["DialogueId"] = 10035817,
            ["GUID"] = "191F942E",
            ["SpeakNpcName"] = "Cp2CharacterName22",
            ["VoiceName"] = "voice/$Locale$/story/1003/100358/191F942E",
            },
        [10035901] = {
