                },
            ["NextDialogue"] = 10036203,
            ["Scripts"] = "MoveTo{ActorId{100304},MoveSpeed{120},TargetPoint{\"lise_56_walk\"}}",
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "200021:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE464",
            },
        [10036203] = {
            ["Camera"] = "255.566406,-24.741699,131.422363,0.000058,0.598905,163.386917,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……还痛吗？",
            ["ContentJP"] = "……まだ痛む？",
            ["DialogueId"] = 10036203,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["FinalCamera"] = "223.371094,-15.542969,131.395508,0.000058,1.398898,162.986725,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191FE48E",
            ["LookAt"] = {
                [1] = "100304:n(100327)",
                },
            ["NextDialogue"] = 10036204,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE48E",
            },
        [10036204] = {
            ["Camera"] = "-10.363281,-8.108887,102.920898,0.000115,20.997046,15.209096,25.000006,495.125,false,Manual,2.799999",
            ["Content"] = "我……还好。",
            ["ContentJP"] = "僕は……大丈夫。",
            ["DialogueId"] = 10036204,
            ["GUID"] = "191FE4B8",
            ["NextDialogue"] = 10036205,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["TalkActionId"] = {
                [1] = "100327:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE4B8",
            },
        [10036205] = {
            ["Camera"] = "90.679688,-10.201172,155.186035,0.000029,19.198732,13.00046,25.000006,233.5448,false,Manual,2.8",
            ["Content"] = "只可惜，命运只是，短暂地，垂怜了我们一下。逃出炼金院，不是，新生活的开始，而是，结束……",
            ["ContentJP"] = "残念ながら……運命の女神の……微笑みは……ほんの一瞬に……終わった。錬金院からの脱出は……新しい生活の……始まり、ではなく……終わりだったんだ……",
            ["DialogueId"] = 10036205,
            ["GUID"] = "191FE4E2",
            ["NextDialogue"] = 10036206,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["TalkActionId"] = {
                [1] = "100327:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE4E2",
            },
        [10036206] = {
            ["Content"] = "……逃跑时，炼金术师，新型抑制剂……毁掉了，我的，喉咙，更摧毁了……心智……",
            ["ContentJP"] = "逃亡中に……錬金術師の……新型抑制剤をくらい……僕の……喉は潰され……心も……更に、蝕まれていった……",
            ["DialogueId"] = 10036206,
            ["GUID"] = "191FE50C",
            ["LookAt"] = {
                [1] = "100327:n(100001)",
                },
            ["NextDialogue"] = 10036207,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE50C",
            },
        [10036207] = {
            ["Content"] = "我们时常，发疯，失控……而我的朋友，<H>36号</>，已经先我一步……",
            ["ContentJP"] = "ときどき……正気を失って……暴走してしまうんだ。そうして……僕の友人、<H>No.36</>は……一足先に……",
            ["DialogueId"] = 10036207,
            ["GUID"] = "191FE536",
            ["LookAt"] = {
                [1] = "100327:n(100327)",
                },
            ["NextDialogue"] = 10036208,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE536",
            },
        [10036208] = {
            ["Camera"] = "-178.277344,-33.839355,138.938477,0.00009,5.597422,154.782913,50.0,239.778275,false,Manual,22.0",
            ["Content"] = "啧，早就知道炼金院那群炼金术师不是人，没想到这么不是人。居然和第六军团勾结，把魔法资质好的卡戎之民骗去做实验……",
            ["ContentJP"] = "ちっ、やっぱ錬金術師なんざロクでもねぇぜ。しかも第六軍団とグルになって、魔法の素質があるカロン族を呼び寄せて実験材料にしてたってことだろ……",
            ["DialogueId"] = 10036208,
            ["FacialId"] = {
                [1] = "200021:Angry01",
                },
            ["GUID"] = "191FE560",
            ["NextDialogue"] = 10036209,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE560",
            },
        [10036209] = {
            ["Camera"] = "201.75,1.508789,159.896973,-6.000039,-11.003229,172.177917,25.000006,100000.0,false,Manual,22.0",
            ["Content"] = "姐姐，你听好。",
            ["ContentJP"] = "姉さん、聞いて。",
            ["DialogueId"] = 10036209,
            ["FacialId"] = {
                [1] = "100304:Shock01",
                },
            ["GUID"] = "191FE58A",
            ["NextDialogue"] = 10036210,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["TalkActionId"] = {
                [1] = "100304:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE58A",
            },
        [10036210] = {
            ["Camera"] = "55.476562,-24.161621,154.890137,-6.00001,14.795302,12.594482,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "第六军团，用桂冠卡戎，欺骗我们。",
            ["ContentJP"] = "第六軍団は……「桂冠カロン族」の……肩書で……ぼ、僕たちを騙したんだ。",
            ["DialogueId"] = 10036210,
            ["FinalCamera"] = "55.476562,-24.161621,154.890137,-6.000008,17.595236,12.594818,25.000002,100000.0,false,Manual,22.0",
            ["GUID"] = "191FE5B4",
            ["NextDialogue"] = 10036211,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE5B4",
            },
        [10036211] = {
            ["Camera"] = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "离开，军团。",
            ["ContentJP"] = "帝国軍から……離れて……",
            ["DialogueId"] = 10036211,
            ["GUID"] = "191FE5DE",
            ["NextDialogue"] = 10036212,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["TalkActionId"] = {
                [1] = "100327:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE5DE",
            },
        [10036212] = {
            ["Camera"] = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
            ["Content"] = "找个，安稳的地方，好好——",
            ["ContentJP"] = "どこか……静かな場所を……見つけて……しっかり――",
            ["DialogueId"] = 10036212,
            ["GUID"] = "191FE608",
            ["NextDialogue"] = 10036213,
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["TalkActionId"] = {
                [1] = "100327:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE608",
            },
        [10036213] = {
            ["Camera"] = "227.824219,31.842285,181.181152,0.000023,-16.404352,178.979095,45.0,100000.0,false,DoNotOverride,22",
            ["Content"] = "那你呢，你要怎么办？！",
            ["ContentJP"] = "待って、あなたは……どうするつもりなの？！",
            ["DialogueId"] = 10036213,
            ["FacialId"] = {
                [1] = "100304:Shock01",
                },
            ["GUID"] = "191FE632",
            ["NextDialogue"] = 10036214,
            ["Scripts"] = "CameraMoveTo{_delay{2},TargetPosition{\"189.578125,-871.764404,19.383301,-0.0,6.995186,93.378288,25.0,100000.0,false,DoNotOverride,22\"},duration{0}}",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE632",
            },
        [10036214] = {
            ["Camera"] = "86.808594,-88.199707,320.100586,0.000018,-29.605869,33.985477,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "我……",
            ["ContentJP"] = "僕は……",
            ["DialogueId"] = 10036214,
            ["FinalCamera"] = "4.820312,-143.472656,376.284668,0.000023,-32.005917,34.185921,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "191FE65C",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE65C",
            },
        [10036215] = {
            ["Content"] = "五天前，下水道出口",
            ["ContentJP"] = "五日前――下水道の出口",
            ["DialogueId"] = 10036215,
            ["GUID"] = "191FE686",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE686",
            },
        [10036216] = {
            ["Content"] = "我还，以为，你会一直昏到，世界末日。",
            ["ContentJP"] = "ずいぶん長く…寝てた気がする。このまま……目覚められないのかと……思ったよ。",
            ["DialogueId"] = 10036216,
            ["GUID"] = "191FE6B0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["NextDialogue"] = 10036217,
            ["RelatedWikiId"] = {
                [1] = 407003,
                [2] = 403004,
                [3] = 201024,
                },
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE6B0",
            },
        [10036217] = {
            ["Content"] = "都怪我。如果我能早点赶来，你就不会被他们……",
            ["ContentJP"] = "僕のせいだ。もっとはやく目を覚ましていれば……",
            ["DialogueId"] = 10036217,
            ["GUID"] = "191FE6DA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["NextDialogue"] = 10036218,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE6DA",
            },
        [10036218] = {
            ["Content"] = "没机会，的。我能清醒的时间，在缩短。",
            ["ContentJP"] = "もう……無理だ。意識を保てる時間が……短くなってる。",
            ["DialogueId"] = 10036218,
            ["GUID"] = "191FE704",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["NextDialogue"] = 10036219,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE704",
            },
        [10036219] = {
            ["Content"] = "也可能是，如你所说，我的心，真的变成了……怪物。",
            ["ContentJP"] = "君の言う通り……僕の心は……本当の化け物に……な、なりかけてるのかな。",
            ["DialogueId"] = 10036219,
            ["GUID"] = "191FE72E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["NextDialogue"] = 10036220,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE72E",
            },
        [10036220] = {
            ["Content"] = "你是怪物的话，那我又是什么呢？",
            ["ContentJP"] = "お前が化け物なら、僕はどうなる！",
            ["DialogueId"] = 10036220,
            ["GUID"] = "191FE758",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["NextDialogue"] = 10036221,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE758",
            },
        [10036221] = {
            ["Content"] = "我们追逐的，那盏灯，原来这么耀眼，高不可及啊。",
            ["ContentJP"] = "僕たちが追い求めていた……あ、あの光は……こんなにも眩しくて……て、手に届かないものだったんだね。",
            ["DialogueId"] = 10036221,
            ["GUID"] = "191FE782",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
            ["NextDialogue"] = 10036222,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE782",
            },
        [10036222] = {
            ["Content"] = "高不可及的东西，让它坠落到地面来不就好了吗？",
            ["ContentJP"] = "手に届かぬのなら、引きずり下ろすまでだ。",
            ["DialogueId"] = 10036222,
            ["GUID"] = "191FE7AC",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036223,
            ["Scripts"] = "SEQ\
{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0080_story_the_abandoned_theme\"},RelatedRegionId{101103}}\
}",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE7AC",
            },
        [10036223] = {
            ["Content"] = "当心，<H>他身上有毒</>……你是谁！",
            ["ContentJP"] = "気をつけろ。<H>やつの体には毒が</>……！お前は誰だ？",
            ["DialogueId"] = 10036223,
            ["GUID"] = "191FE7D6",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036224,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE7D6",
            },
        [10036224] = {
            ["Content"] = "我有很多个名字，也有很多种身份，但这些说到底只是一个代号。而代号不管怎么变，我们这被神抛弃的本质都不会更改。",
            ["ContentJP"] = "私にはいくつもの名と顔がある。だが、それらは所詮ただの符号に過ぎない。いくら名を変えようが、神に見捨てられた身であることには変わりはない。",
            ["DialogueId"] = 10036224,
            ["GUID"] = "191FE800",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036225,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE800",
            },
        [10036225] = {
            ["Content"] = "说到这里，聪明的你们应该知道我是谁了吧。",
            ["ContentJP"] = "賢い君たちのことだ。私が誰か、わからぬとは言わせんぞ。",
            ["DialogueId"] = 10036225,
            ["GUID"] = "191FE82A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036226,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE82A",
            },
        [10036226] = {
            ["Content"] = "我是来向你们发出一个邀请，加入我们，将那高不可及的索拉之民拖到地上，感受卡戎的怒火。",
            ["ContentJP"] = "君たちを勧誘したい。頂点に居座るソラを引きずり下ろし、共にカロンの怒りを思い知らせようではないか。",
            ["DialogueId"] = 10036226,
            ["GUID"] = "191FE854",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036227,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE854",
            },
        [10036227] = {
            ["Content"] = "别急着拒绝。好好想想帝国对你们的所作所为吧！他们用美好的谎言欺骗你们，用残忍的刑罚折磨你们，用无尽的绝望笼罩你们。",
            ["ContentJP"] = "すぐに断る必要はない。帝国が君たちに何をしてきたのか、よく考えてみろ。甘い嘘で君たちを欺き、残酷な刑罰で苦しめ、果てしない絶望で覆い尽くした――",
            ["DialogueId"] = 10036227,
            ["GUID"] = "191FE87E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036228,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE87E",
            },
        [10036228] = {
            ["Content"] = "在这条路的尽头等你们的是什么？当上“桂冠卡戎”，过上更好的生活，实现更远的梦想？",
            ["ContentJP"] = "その末に待っているのはなんだ？「桂冠カロン族」としての裕福な暮らしか？夢の実現か？",
            ["DialogueId"] = 10036228,
            ["GUID"] = "191FE8A8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036229,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE8A8",
            },
        [10036229] = {
            ["Content"] = "不！是被索拉人敲骨吸髓，被同胞中的叛徒追捕，最后死在哪个不知名的角落。",
            ["ContentJP"] = "どれも違う！ソラどもに骨までしゃぶられ、同胞の裏切り者に追われ、最期は世の隅っこでドブネズミのようにひっそり死ぬだけだ。",
            ["DialogueId"] = 10036229,
            ["GUID"] = "191FE8D2",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036230,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE8D2",
            },
        [10036230] = {
            ["Content"] = "他们用一个简单的承诺，驱使如你，如我，如所有渴望出人头地的卡戎，一头扎进深渊。",
            ["ContentJP"] = "連中は言葉一つで私たちを騙し、希望を抱いたカロンを深淵へと追いやった。",
            ["DialogueId"] = 10036230,
            ["GUID"] = "191FE8FC",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036231,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE8FC",
            },
        [10036231] = {
            ["Content"] = "只要第六军团和炼金院的谎言不被戳破，就不断会有冰湖城的卡戎之民沿着军团这条路走下去，一个又一个，踏上和你们一样的悲剧。",
            ["ContentJP"] = "第六軍団と錬金院の嘘が暴かれない限り、アイスレイク城のカロン族は皆、君たちと同じ道を辿って、悲惨な終わりを迎えるだろう。",
            ["DialogueId"] = 10036231,
            ["GUID"] = "191FE926",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036232,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE926",
            },
        [10036232] = {
            ["Content"] = "…………！",
            ["ContentJP"] = "…………！",
            ["DialogueId"] = 10036232,
            ["GUID"] = "191FE950",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036233,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE950",
            },
        [10036233] = {
            ["Content"] = "我们被帝国夺走了过去，苟活在当下。未来我们也要这样毫无作为，让那群畜生碾碎我们所珍视的一切吗？",
            ["ContentJP"] = "私たちは帝国に過去を奪われ、地に汗滲む思いで生きている。だが、この先はどうだ？このまま指をくわえながら、連中に大切なものを踏みにじられる運命を受け入れるのか？",
            ["DialogueId"] = 10036233,
            ["GUID"] = "191FE97A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036234,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE97A",
            },
        [10036234] = {
            ["Content"] = "看啊，看看现在的你我。帝国贪求我们的力量，为我们套上镣铐，把我们变成野兽，沦为真正的恶魔。",
            ["ContentJP"] = "私たちの有様を見てみろ。帝国は私たちの力を貪り、獣のように首輪をつけ、私たちを本当の悪魔へと変えた。",
            ["DialogueId"] = 10036234,
            ["GUID"] = "191FE9A4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036235,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE9A4",
            },
        [10036235] = {
            ["Content"] = "如今我们好不容易挣脱了枷锁，那不正是用帝国给予我们的这副獠牙，狠狠咬向他们咽喉的时刻吗！",
            ["ContentJP"] = "枷が取れた今、その牙を連中の首に立てたいとは思わないか！？",
            ["DialogueId"] = 10036235,
            ["GUID"] = "191FE9CE",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036236,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE9CE",
            },
        [10036236] = {
            ["Content"] = "让他们记住我们的存在，感受我们的痛苦，再也不敢觊觎我们珍视的东西！让他们用鲜血去忏悔，去铭记我们的存在，让整个帝国呼唤我们的名字！",
            ["ContentJP"] = "その脳裏に私たちの存在を刻み、私たちの痛みを思い知らせろ！二度と踏みにじられないように！連中に血で償わせ、帝国に私たちの名を轟かせるのだ！",
            ["DialogueId"] = 10036236,
            ["GUID"] = "191FE9F8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036237,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FE9F8",
            },
        [10036237] = {
            ["Content"] = "<W>神弃者同盟</>……",
            ["ContentJP"] = "<W>フォーセイクン同盟</>……",
            ["DialogueId"] = 10036237,
            ["GUID"] = "191FEA22",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["NextDialogue"] = 10036238,
            ["RelatedWikiId"] = {
                [1] = 101004,
                },
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FEA22",
            },
        [10036238] = {
            ["Content"] = "你们可以把它理解成报复，但我更希望你们把它理解成保护，这是只有我们“恶魔”才能做到的责任——清理内城的“垃圾”，还你们的家人一个干净的未来。",
            ["ContentJP"] = "これは復讐であると同時に、「加護」でもある。私たち「悪魔」にしかできないことだ――内城区の「ゴミ」を掃除するとともに、君たちの家族も安らかな未来が得られる……一挙両得だ。",
            ["DialogueId"] = 10036238,
            ["GUID"] = "191FEA4C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100326,
            ["SpeakNpcName"] = "Cp2CharacterName08",
            ["VoiceName"] = "voice/$Locale$/story/1003/100362/191FEA4C",
            },
        [10036239] = {
            ["Camera"] = "145.113281,-134.397461,226.663574,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "（神弃者同盟……）",
            ["ContentJP"] = "（フォーセイクン同盟……）",
            ["DialogueId"] = 10036239,
            ["DisableMouth"] = 1,
            ["FinalCamera"] = "149.515625,-128.306641,226.455078,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "191FEA76",
