        [10036504] = {
            ["Camera"] = "352.181641,-1420.943481,295.125,10.817314,-10.006131,108.659332,25.0,100000.0,false,Manual,22.0",
            ["Content"] = "你们也和先前那群人一样，被愚蠢的狂欢冲烂了脑子？",
            ["ContentJP"] = "お前らまで馬鹿騒ぎに脳ミソをやられたんじゃないだろうな。",
            ["DialogueId"] = 10036504,
            ["FinalCamera"] = "315.181641,-1309.563599,274.621094,10.818109,-9.806095,108.059586,25.0,100000.0,false,Manual,22.0",
            ["GUID"] = "192015F0",
            ["NextDialogue"] = 10036505,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{1}}",
