            ["TalkActionId"] = {
                [1] = "100304:Lise_Story_Protect_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192015F0",
            },
        [10036505] = {
            ["Camera"] = "67.845703,-302.296021,112.21875,0.00005,11.194864,-117.729912,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……凶手的身份和动机还未确认，直接击毙无法向冰湖城的受害者交代！",
            ["ContentJP"] = "……犯人の身分と動機は未だ不明。このまま処刑するなど、アイスレイク城の被害者たちも納得されないでしょう！",
            ["DialogueId"] = 10036505,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["FinalCamera"] = "87.982422,-255.8255,86.699219,0.000067,11.194679,-117.325897,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "1920161A",
            ["LookAt"] = {
                [1] = "100304:n(100310)",
                [2] = "100001:n(100304)",
                [3] = "200021:n(100304)",
                [4] = "100327:n(100304)",
