        [10036507] = {
            ["Camera"] = "67.845703,-302.296021,112.21875,0.00005,11.194864,-117.729912,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 10036507,
            ["FacialId"] = {
                [1] = "100304:Disappoint01",
                },
            ["GUID"] = "1920166E",
            ["LookAt"] = {
                [1] = "100304:p(lise_ditou)",
                },
            ["NextDialogue"] = 10036508,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/1920166E",
            },
        [10036508] = {
            ["Camera"] = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "你还记得你加入军团那天，在三头狼旗下发过的誓言吗？“将此生奉献给皇帝陛下，成为海伯利亚的忠诚战士，至死方休。”",
            ["ContentJP"] = "帝国軍に入った日、あの旗の下で立てた誓いを忘れたのか？「命を陛下に捧げ、ヒュペリアの忠実な兵士とならん」――そう言ったのは他でもないお前だ。",
            ["DialogueId"] = 10036508,
            ["FinalCamera"] = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "19201698",
            ["LookAt"] = {
                [1] = "100304:n(100310)",
                },
            ["NextDialogue"] = 10036509,
            ["SpeakNpcId"] = 100310,
            ["TalkActionId"] = {
                [1] = "100310:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201698",
            },
        [10036509] = {
            ["Camera"] = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "琳恩长官说过，你虽是卡戎之民，却是难得的人才。她本打算在案子结束后提携你去皇都。",
            ["ContentJP"] = "リーン長官もその優秀さを見込んで、この事件が解決したら、カロン族のお前を皇都に推薦する気だったんだぞ。",
            ["DialogueId"] = 10036509,
            ["GUID"] = "192016C2",
            ["NextDialogue"] = 10036510,
            ["SpeakNpcId"] = 100310,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192016C2",
            },
        [10036510] = {
            ["Camera"] = "53.857422,378.744141,188.148438,0.000066,-9.20508,-99.947792,20.0,100000.0,false,Manual,22.0",
            ["Content"] = "十三军团一向惜才，我再给你最后一次证明自己是海伯利亚忠诚战士的机会。给我让开。",
            ["ContentJP"] = "第十三軍団は人材を尊ぶ。最後にもう一度だけ、ヒュペリアへの忠誠を証明する機会を与えよう。さっさとそこをどけ！",
            ["DialogueId"] = 10036510,
            ["FinalCamera"] = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
            ["GUID"] = "192016EC",
            ["NextDialogue"] = 10036511,
            ["SpeakNpcId"] = 100310,
            ["TalkActionId"] = {
                [1] = "100310:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192016EC",
            },
        [10036511] = {
            ["Camera"] = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
            ["Content"] = "……不。",
            ["ContentJP"] = "……いいえ。",
            ["DialogueId"] = 10036511,
            ["FacialId"] = {
                [1] = "100304:Doubt01",
                },
            ["GUID"] = "19201716",
            ["LookAt"] = {
                [1] = "100304:n(100304)",
                [2] = "100001:n(100304)",
                [3] = "200021:n(100304)",
                },
            ["NextDialogue"] = 10036512,
