        [10036516] = {
            ["Camera"] = "438.205078,-272.948975,145.40625,0.000054,0.193151,156.073257,50.0,100000.0,false,Manual,22.0",
            ["Content"] = "违抗军纪，阻碍其他军团执行任务，依照帝国军律，同样就地击毙。",
            ["ContentJP"] = "軍紀違反に軍団の任務妨害――帝国軍律に基づき、直ちに処刑とする！",
            ["DialogueId"] = 10036516,
