        [10036518] = {
            ["Content"] = "全部处理掉，一个都不能放出剧院！",
            ["ContentJP"] = "劇場から誰ひとり逃がすな！全員ブチ殺せ！",
            ["DialogueId"] = 10036518,
            ["GUID"] = "1920183C",
            ["NextDialogue"] = 10036519,
            ["SpeakNpcId"] = 100310,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/1920183C",
            },
        [10036519] = {
            ["Content"] = "抱歉了，长官……！",
            ["ContentJP"] = "ごめん、長官……！",
            ["DialogueId"] = 10036519,
            ["GUID"] = "19201866",
            ["NextDialogue"] = 10036520,
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201866",
            },
        [10036520] = {
            ["Content"] = "黎瑟撑住！我们也来帮你。",
            ["ContentJP"] = "リズム、しっかり！{性别:僕|私}たちも手を貸すよ！",
            ["DialogueId"] = 10036520,
            ["GUID"] = "19201890",
            ["NextDialogue"] = 10036521,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/19201890",
            },
        [10036521] = {
            ["Content"] = "好吧、好吧。既然都到了这份上，我也只能舍命相陪了！",
            ["ContentJP"] = "こうなったら、腹くくるしかねぇな。俺たちが命懸けで付き合ってやるよ！",
            ["DialogueId"] = 10036521,
            ["GUID"] = "192018BA",
            ["NextDialogue"] = 10036522,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1003/100365/192018BA",
            },
        [10036522] = {
            ["Content"] = "你们、怎么……",
            ["ContentJP"] = "君たち……どうして……",
            ["DialogueId"] = 10036522,
            ["GUID"] = "192018E4",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
