            },
        [10036525] = {
            ["Camera"] = "-318.023438,-765.236267,387.527344,0.000012,-27.004503,4.585194,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "你走的时候，白留意到了，你身上有些亮晶晶的细小粉末。",
            ["ContentJP"] = "あなたが出ていくのをスノウが気付いてね。身体にキラキラ光る粒が付着してたからそれを辿って来たんだ。",
            ["DialogueId"] = 10036525,
            ["GUID"] = "19201962",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100327:n(100001)",
                },
