            },
        [10036555] = {
            ["Camera"] = "258.386719,-506.575806,104.496094,0.000145,16.772669,-121.30761,35.000011,327.03125,false,Manual,2.799999",
            ["Content"] = "你刚才唱那首歌的时候……或者更早。",
            ["ContentJP"] = "さっきあなたがその歌を口ずさんだ時……いや、もっと前かもしれない。",
