        [10036602] = {
            ["Content"] = "这个秘密，由我……带进坟墓。",
            ["ContentJP"] = "この秘密は……僕が墓場まで……持って行くとしよう……",
            ["DialogueId"] = 10036602,
            ["GUID"] = "19202604",
            ["NextDialogue"] = 10036603,
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100366/19202604",
            },
        [10036603] = {
            ["Camera"] = "-508.236328,-141.803528,-26.71875,-0.001345,50.110828,41.260582,15.0,100000.0,false,Manual,22.0",
            ["Content"] = "布鲁斯，我完成约定了。",
            ["ContentJP"] = "ブルース……約束は果たしたぞ。",
            ["DialogueId"] = 10036603,
            ["FinalCamera"] = "-508.236328,-141.803528,-26.71875,-0.001344,55.910446,50.060265,15.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1920262E",
            ["LookAt"] = {
                [1] = "100327:p(tuosi02_62_lookat)",
                },
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "100327:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100366/1920262E",
            },
        [10036604] = {
            ["Content"] = "（士兵的手腕有一道细细的伤痕，稍加辨认便能看出是被利剑所伤。但<H>这个舞台最终留下的，应该只有军团与“怪物”战斗的痕迹才对。</>）",
            ["ContentJP"] = "兵士の手首に細い傷跡がある。よく見ると、それは剣によってつけられたものだとわかる。だが、<H>この舞台に残されるべきは、本来「化け物」と軍団の戦闘の痕跡のみのはず……</>",
            ["DialogueId"] = 10036604,
            ["GUID"] = "1920226A",
            ["NextOptions"] = {
                [1] = 10036605,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_Pangbai",
            },
        [10036605] = {
            ["Content"] = "（毁掉剑痕。）",
            ["ContentJP"] = "剣の傷跡を消す",
            ["DialogueId"] = 10036605,
            ["GUID"] = "1920226B",
            ["NextDialogue"] = 10036606,
            },
        [10036606] = {
            ["Content"] = "（那道剑伤足够细，所以伤口的形状可以轻易被破坏掉。朱红的露滴滚落，<H>就像从来没有一位使剑的狩月人来过这里一样。</>）",
            ["ContentJP"] = "その傷は細く、跡形なく壊すのは容易だった。朱に染まった露が滴り落ちる――<H>まるで、剣を振るった月狩り人など初めから存在しなかったかのように。</>",
            ["DialogueId"] = 10036606,
            ["GUID"] = "1920226C",
            ["SpeakNpcName"] = "UI_Npc_Name_Pangbai",
            },
        [10036607] = {
            ["Content"] = "（士兵的身上有大面积焦痂，稍加辨认便能看出遭受过电击。但<H>这个舞台最终留下的，应该只有军团与“怪物”战斗的痕迹才对。</>）",
            ["ContentJP"] = "兵士の身体には広範囲にわたる火傷があり、よく見ると電撃によるものだとわかる。だが、<H>この舞台に残されるべきは、本来「化け物」と軍団の戦闘の痕跡のみのはず……</>",
            ["DialogueId"] = 10036607,
            ["GUID"] = "1920226D",
            ["NextOptions"] = {
                [1] = 10036608,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_Pangbai",
            },
        [10036608] = {
            ["Content"] = "（扯过电缆。）",
            ["ContentJP"] = "ケーブルを引きちぎる",
            ["DialogueId"] = 10036608,
            ["GUID"] = "1920226E",
            ["NextDialogue"] = 10036609,
            },
        [10036609] = {
            ["Content"] = "（落地灯碎裂，垂落的电缆被拦腰扯断。电火花跳起快活的小步舞曲，<H>就像从来没有一位能操纵电流的军官来过这里一样。</>啊，可惜了，那真的是一盏很漂亮的落地灯。）",
            ["ContentJP"] = "フロアランプが砕け、垂れ下がったケーブルは真っ二つに引き裂かれた。火花がパチパチと軽やかに踊り、<H>まるで電流を操る軍官などここにいなかったかのようだ。</>……ああ、あのフロアランプ、いいデザインだったのにな。",
            ["DialogueId"] = 10036609,
            ["GUID"] = "1920226F",
            ["NextDialogue"] = 10036610,
            ["SpeakNpcName"] = "UI_Npc_Name_Pangbai",
            },
        [10036610] = {
            ["Content"] = "（现在，布景已经完成了：十三军团一路追查到盖雷亚剧院，<H>先头小队虽然疏散了群众，却不幸命丧“怪物”之手。</>随后赶来的大部队则成功击毙“怪物”，为卡戎狩猎一案画上了休止符——这才是卡戎狩猎最恰如其分的谢幕。）",
            ["ContentJP"] = "こうして、舞台は整った。第十三軍団はガレア劇場まで追撃し、<H>先頭部隊は市民の避難に成功するも、「化け物」の手により全滅。</>その後到着した本隊が「化け物」を討ち取り、カロン狩り事件は終幕を迎えた――それこそが、カロン狩りにふさわしい終わり方なのだ。",
            ["DialogueId"] = 10036610,
            ["GUID"] = "19202270",
            ["SpeakNpcName"] = "UI_Npc_Name_Pangbai",
            },
        [10036701] = {
            ["Content"] = "神弃者同盟的人走了，布鲁斯，你的伤怎么样……布鲁斯，布鲁斯！",
            ["ContentJP"] = "フォーセイクン同盟のやつ、もう行ったぞ！……ブルース、大丈夫か？ブルース、ブルース！",
            ["DialogueId"] = 10036701,
            ["GUID"] = "19203642",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036702,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203642",
            },
        [10036702] = {
            ["Content"] = "这具躯体，也不是，钢筋铁骨……这帝国炼金院，技术，也不怎么样。",
            ["ContentJP"] = "見た目の割りに……も、脆すぎる……錬金院の技術も……大したことないね。",
            ["DialogueId"] = 10036702,
            ["GUID"] = "1920366C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036703,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/1920366C",
            },
        [10036703] = {
            ["Content"] = "姐姐的……枪法还挺准，比以前厉害……多了。看来，她已经可以，保护好，自己……咳！",
            ["ContentJP"] = "姉さん……銃の腕が、また上がった……前よりずっと上手だ……あれなら、ちゃんと……自分を守れる……ゴホッ！",
            ["DialogueId"] = 10036703,
            ["GUID"] = "19203696",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036704,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203696",
            },
        [10036704] = {
            ["Content"] = "现在是说这种话的时候吗！",
            ["ContentJP"] = "そんなこと言ってる場合か！",
            ["DialogueId"] = 10036704,
            ["GUID"] = "192036C0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036705,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192036C0",
            },
        [10036705] = {
            ["Content"] = "哈，哈。",
            ["ContentJP"] = "ハ、ハ……",
            ["DialogueId"] = 10036705,
            ["GUID"] = "192036EA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036706,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192036EA",
            },
        [10036706] = {
            ["Content"] = "撑住，我带你去找医生！只要用武力逼迫他们，就算是我们这样的怪物……",
            ["ContentJP"] = "待ってろ。医者を捕まえてきてやる！脅してでも手当させるから――",
            ["DialogueId"] = 10036706,
            ["GUID"] = "19203714",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036707,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203714",
            },
        [10036707] = {
            ["Content"] = "……没必要，了。",
            ["ContentJP"] = "……もう……いいんだ……",
            ["DialogueId"] = 10036707,
            ["GUID"] = "1920373E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036708,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/1920373E",
            },
        [10036708] = {
            ["Content"] = "你一直，不肯告诉我……但我能猜到，身上，洗不掉的血……是……哪来的……",
            ["ContentJP"] = "君は……何も言わないけど……僕にはわかるんだ……身体にこびりついた血が……何を意味するのかをね……",
            ["DialogueId"] = 10036708,
            ["GUID"] = "19203768",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036709,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203768",
            },
        [10036709] = {
            ["Content"] = "这样，死掉，对大家，很好……",
            ["ContentJP"] = "こうして……死ねば……みんなも……助かる。",
            ["DialogueId"] = 10036709,
            ["GUID"] = "19203792",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036710,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203792",
            },
        [10036710] = {
            ["Content"] = "混蛋，别大家大家的，你自己呢？你忘了自己怎么说的？等逃出来，我们会搭起舞台，我会教你表演，让所有亲朋好友来看我们的演出！",
            ["ContentJP"] = "ふざけるな！他人のことばかり言って、自分はどうなんだ！？約束したことを忘れたのか？外へ出たら舞台を作るんだろ！僕が演技を教えてやる！みんなを招待して公演を開くって言ってたじゃないか！",
            ["DialogueId"] = 10036710,
            ["GUID"] = "192037BC",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
            ["NextDialogue"] = 10036711,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192037BC",
            },
        [10036711] = {
            ["Content"] = "抱歉……要食言了……",
            ["ContentJP"] = "……ごめんね……守れそうにないや……",
            ["DialogueId"] = 10036711,
            ["GUID"] = "192037E6",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036712,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192037E6",
            },
        [10036712] = {
            ["Content"] = "不……对了，姐姐、你的姐姐！你说过最想念的就是姐姐，你还没和她相认啊！",
            ["ContentJP"] = "なっ……そうだ、お前の姉さん！お前、姉さんに会いたがってたじゃないか！こんなところでくたばっちゃダメだ！",
            ["DialogueId"] = 10036712,
            ["GUID"] = "19203810",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036713,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203810",
            },
        [10036713] = {
            ["Content"] = "……我是个，懦夫……嘴上说着，想要与亲人团聚的，漂亮话。可，真的见到她，除了……落荒而逃……什么都，做不了……",
            ["ContentJP"] = "……僕は……臆病者なんだ……口では……家族に会うんだとか……偉そうに言っても……いざ目の前にすると……逃げることしか……できなかった……",
            ["DialogueId"] = 10036713,
            ["GUID"] = "1920383A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036714,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/1920383A",
            },
        [10036714] = {
            ["Content"] = "我、我有个……请求。",
            ["ContentJP"] = "お、お願いが……あるんだ。",
            ["DialogueId"] = 10036714,
            ["GUID"] = "19203864",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036715,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203864",
            },
        [10036715] = {
            ["Content"] = "这条链子是……信物。找到姐姐，告诉她……第六军团……真相……不要，她……也被骗……",
            ["ContentJP"] = "この編み紐は……僕の宝物だ。姉さんに……だ、第六軍団の……真相を……伝えてくれ……彼女を……同じ目に……合わせたくないんだ……",
            ["DialogueId"] = 10036715,
            ["GUID"] = "1920388E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036716,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/1920388E",
            },
        [10036716] = {
            ["Content"] = "还有，<H>绝对，别让她，知道……我死在，她手上。</>她会，受不住……",
            ["ContentJP"] = "それから……<H>僕を殺したのが……姉さんだってこと……絶対に……知られちゃダメだ……</>そんなの知ったら……姉さんは……",
            ["DialogueId"] = 10036716,
            ["GUID"] = "192038B8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036717,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192038B8",
            },
        [10036717] = {
            ["Content"] = "拜托……你了。",
            ["ContentJP"] = "たの……む……",
            ["DialogueId"] = 10036717,
            ["GUID"] = "192038E2",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
            ["NextDialogue"] = 10036718,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100327,
            ["SpeakNpcName"] = "Cp2CharacterName06",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192038E2",
            },
        [10036718] = {
            ["Content"] = "布鲁斯……！！",
            ["ContentJP"] = "ブルース……！！",
            ["DialogueId"] = 10036718,
            ["GUID"] = "1920390C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
            ["NextDialogue"] = 10036719,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/1920390C",
            },
        [10036719] = {
            ["Content"] = "我答应你。",
            ["ContentJP"] = "……わかったよ。",
            ["DialogueId"] = 10036719,
            ["GUID"] = "19203936",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
            ["NextDialogue"] = 10036720,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203936",
            },
        [10036720] = {
            ["Content"] = "但是……用什么办法才能隐瞒你的死因，又让她相信第六军团的真相……",
            ["ContentJP"] = "だが、彼女にお前の死を隠した上で、第六軍団の真相を伝えるとなると……",
            ["DialogueId"] = 10036720,
            ["GUID"] = "19203960",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
            ["NextDialogue"] = 10036721,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/19203960",
            },
        [10036721] = {
            ["Content"] = "……我知道了。",
            ["ContentJP"] = "……そうか。",
            ["DialogueId"] = 10036721,
            ["GUID"] = "1920398A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
            ["NextDialogue"] = 10036722,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/1920398A",
            },
        [10036722] = {
            ["Content"] = "<H>只要让她以为“布鲁斯”还活着，让“布鲁斯”告诉她一切</>……只要这样……",
            ["ContentJP"] = "<H>「ブルース」が自ら姉さんに事実を伝えればいい</>……そうすれば……",
            ["DialogueId"] = 10036722,
            ["GUID"] = "192039B4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100328,
            ["SpeakNpcName"] = "Cp2CharacterName07",
            ["VoiceName"] = "voice/$Locale$/story/1003/100367/192039B4",
            },
        [10036801] = {
            ["Camera"] = "-120.507812,969.508057,189.074219,0.000029,7.583572,-89.405365,40.000011,1878.839111,false,Manual,22.0",
            ["Content"] = "布鲁斯，我，做到了。谎言，揭穿了。",
            ["ContentJP"] = "ブルース……約束……守ったが……結局は……バレてしまった。",
            ["DialogueId"] = 10036801,
            ["FinalCamera"] = "-119.283203,850.649658,204.894531,0.000029,7.583572,-89.405365,40.000011,1878.839111,false,Manual,22.0",
