            },
        [10036804] = {
            ["Camera"] = "-707.240234,463.596924,56.441406,0.000062,10.230789,-5.153081,40.000027,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我们，头一次的，合作表演，还，不错吧。",
            ["ContentJP"] = "初めての……共演にしては……なかなか……悪くなかった……そうだろう？",
            ["DialogueId"] = 10036804,
            ["FinalCamera"] = "-707.240234,463.596924,56.441406,0.000061,10.030787,23.246756,40.000027,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "19204728",
            ["NextDialogue"] = 10036805,
            ["Scripts"] = "PARA{SEQ{CameraMoveTo{_delay{1},TargetPosition{\"-155.210938,420.388672,141.570312,0.000106,14.365984,-85.363564,35.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-199.027344,1123.37085,-9.492188,3.599992,13.965052,-86.362556,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0.7}}},PARA{MoveTo{ActorId{100356},TargetPoint{\"cp2fixsimple63Point01\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100340},TargetPoint{\"cp2fixsimple63Point02\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100341},TargetPoint{\"cp2fixsimple63Point03\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100342},TargetPoint{\"cp2fixsimple63Point04\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100346},TargetPoint{\"cp2fixsimple63Point06\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100347},TargetPoint{\"cp2fixsimple63Point07\"},MoveSpeed{250},Visibility{\"Show\"}},MoveTo{ActorId{100343},TargetPoint{\"cp2fixsimple63Point05\"},MoveSpeed{250},Visibility{\"Show\"}}}}",
            ["SpeakNpcId"] = 100328,
