            ["Scripts"] = "SetLocation{ActorId{200022},TargetPoint{\"Cp2Meetingstage01Point01\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 200022,
            ["TalkActionId"] = {
                [1] = "200022:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CD86",
            },
        [10037624] = {
            ["Camera"] = "-120.253906,83.223389,109.773438,0.000115,6.400085,-83.788696,35.000015,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈哈，可算等到你说“休息”了。生命在于休息，你终于听进去了上司的谆谆教诲，可喜可贺。",
            ["ContentJP"] = "おやおや、君が「休む」なんて珍しい。休憩は命の養分だって言葉……やっと聞き入れてくれたようで嬉しい限りだよ。",
            ["DialogueId"] = 10037624,
            ["FacialId"] = {
                [1] = "200022:Confident01",
                },
            ["FinalCamera"] = "-130.150879,82.145996,109.773438,0.000111,6.400085,-81.788612,35.000015,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1920CDB0",
            ["NextDialogue"] = 10037625,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-266.87085,324.740479,109.642578,0.000128,1.800076,-61.188812,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-258.637451,329.45874,109.642578,0.000129,1.800076,-63.189171,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
            ["SpeakNpcId"] = 100006,
            ["TalkActionId"] = {
                [1] = "100006:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1003/100376/1920CDB0",
            },
        [10037625] = {
            ["Camera"] = "-162.948242,-70.67041,200.082031,0.000205,-21.197163,70.186539,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……等等，还有件事。",
            ["ContentJP"] = "……あ、忘れてた――",
            ["DialogueId"] = 10037625,
