        [10038001] = {
            ["Content"] = "长官们……当心……",
            ["ContentJP"] = "どうか……お気を付けて……",
            ["DialogueId"] = 10038001,
            ["GUID"] = "191DEA43",
            ["NextDialogue"] = 10038002,
            ["SpeakNpcId"] = 100322,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA43",
            },
        [10038002] = {
            ["Content"] = "小宝贝们又来了，真是一会儿也不得闲。",
            ["ContentJP"] = "どんどん湧いてきやがる。少しは休ませてくれっての。",
            ["DialogueId"] = 10038002,
            ["GUID"] = "191DEA44",
