            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA44",
            },
        [10038004] = {
            ["Content"] = "好，下一个。",
            ["ContentJP"] = "さあ、次へ！",
            ["DialogueId"] = 10038004,
            ["GUID"] = "191DEA46",
            ["SpeakNpcId"] = 100304,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA46",
            },
        [10038006] = {
            ["Content"] = "好……好难转……我累啦，小仆从，接下来你加油……",
            ["ContentJP"] = "ぐぬぬ……か、かったーい！！はぁはぁ……我が下僕、後は任せたぞ……",
            ["DialogueId"] = 10038006,
            ["GUID"] = "191DEA48",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191DEA48",
            },
        [10038007] = {
