            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191EF0C3",
            },
        [10038013] = {
            ["Content"] = "嗯？是你们啊。",
            ["ContentJP"] = "ん？ああ、君たちか。",
            ["DialogueId"] = 10038013,
            ["GUID"] = "191EF0C4",
