            ["TurnTo"] = {
                [1] = "100341:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1003/100380/191EF0C4",
            },
        [10038014] = {
            ["Content"] = "你们的行动地点不是在前面吗？快去吧，这次行动决不允许有任何闪失。",
            ["ContentJP"] = "君たちの作戦区域は前方のはずだろ？さっさと行け。如何なる失敗も許されないからな！",
            ["DialogueId"] = 10038014,
            ["GUID"] = "191EF0C5",
            ["NextDialogue"] = 10038015,
            ["SpeakNpcId"] = 100340,
