            },
        [10100211] = {
            ["Camera"] = "321.105469,367.106934,155.726562,0.001201,-4.999698,-131.971817,50.0,560.205811,false,Manual,3.0",
            ["Content"] = "那你们知道一个叫西比尔的女人吗？其他人叫她“军团长”，她应该就在这个国家……我想去找她。",
            ["ContentJP"] = "「シビル」という名前の女性を知って……いますか？「軍団長」と呼ばれていて、この国にいるはずなんですが……どうしても彼女を見つけたくて。",
            ["DialogueId"] = 10100211,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1948E9B4",
            ["LookAt"] = {
                [1] = "100001:n(200003)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 10100212,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_End",
                [2] = "\
100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101002/1948E9B4",
            },
        [10100212] = {
            ["Camera"] = "109.613281,-278.998535,123.344238,0.001196,-0.900663,111.229919,35.0,350.570953,false,Manual,3.0",
            ["Content"] = "叫西比尔的人遍地都是，但是被称作“军团长”的只能是那一位。找她？卡戎之民无惧严寒，你是怎么把脑子冻坏的？",
            ["ContentJP"] = "「シビル」はよくある名前だけど、「軍団長」って呼ばれるシビルならひとりだけね。彼女を探しているだなんて本当に？カロン族は寒さに強いはずだけど、あなたの脳みそは凍っちゃったのかしら？",
            ["DialogueId"] = 10100212,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["GUID"] = "1948E9DE",
            ["NextDialogue"] = 10100213,
            ["RelatedWikiId"] = {
                [1] = 303003,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{4},ActorId{200003},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "200002:SpecialConfident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101002/1948E9DE",
            },
        [10100213] = {
            ["Camera"] = "94.464844,26.425293,178.743652,0.001218,-19.900541,-128.170197,36.276737,164.815262,false,Manual,2.909652",
            ["Content"] = "我没在开玩笑。我有一个重要的……东西，可能落在了她手上，所以我一定要搞清楚。",
            ["ContentJP"] = "冗談じゃなくて真剣な話で。{性别:僕|私}の大事な……モノがあって。彼女の手に落ちたかもしれないんです。なんとか居場所を見つけないと。",
            ["DialogueId"] = 10100213,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Angry01",
                [2] = "200003:None",
                [3] = "200002:None",
                },
            ["GUID"] = "1948EA08",
            ["NextDialogue"] = 10100214,
            ["Scripts"] = "PARA{\
