        [10100301] = {
            ["Content"] = "你看起来全身都是伤，不要紧吗？",
            ["ContentJP"] = "なんか全身傷だらけだけど、平気なの？",
            ["DialogueId"] = 10100301,
            ["GUID"] = "1948F8A2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8A2",
            },
        [10100302] = {
            ["Content"] = "没什么，已经不痛了。",
            ["ContentJP"] = "はい、特に痛みもないですし。",
            ["DialogueId"] = 10100302,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1948F8CC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8CC",
            },
        [10100303] = {
            ["Content"] = "你是不是遇到了很倒霉的事……不过不用怕！",
            ["ContentJP"] = "恐ろしい目にあったんだね……でも、もう心配はいらない！",
            ["DialogueId"] = 10100303,
            ["GUID"] = "1948F8F6",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10100304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F8F6",
            },
        [10100304] = {
            ["Content"] = "现在有我罩着你啦！毕竟白可是——",
            ["ContentJP"] = "今は私が守ってあげるからさ！だってスノウは――",
            ["DialogueId"] = 10100304,
            ["GUID"] = "1948F920",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101003/1948F920",
            },
        [10100305] = {
            ["Content"] = "呜哇——！！那边是是是是是什么？！",
            ["ContentJP"] = "ほぎゃぁ――！ああ、あそこにいるのは何！？",
