        [10100611] = {
            ["Camera"] = "-1080.685547,-5501.387695,2266.973145,0.0012,-9.499632,139.245468,80.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……{性别：他|她}是南方的维瓦尔酒庄派来送货的，可怜大桥上路滑翻了车，货和行李都被秽兽撕咬一空。",
            ["ContentJP"] = "……この子は南方のヴィヴァル酒造所から配達に来たのだけど、大橋でトラックが横転して、おまけに<Default note=\"text:エジュウ\">穢獣</>まで襲ってきて。荷物も全部やられちゃったみたいなのよ。",
            ["DefaultLookAt"] = "TalkNpc",
