        [10100613] = {
            ["Camera"] = "-184.384766,162.758789,125.498535,0.001232,0.301116,-34.69698,38.839439,410.389923,false,Manual,2.4",
            ["Content"] = "{性别：喂、喂……兄弟你也老大不小了，别哭啊！|喂喂，你怎么哭了？见鬼，长官没说过怎么对付掉眼泪的小姑娘啊！}",
            ["ContentJP"] = "{性别:おいおい兄弟、もう大きいんだから、泣かないでくれよ？|おいおい、泣かないでくれよ？女の子が泣いた場合の対処法なんて、上官から聞いてないんだぞ俺は！}",
