        [10100614] = {
            ["Camera"] = "-0.116211,61.776855,134.516113,0.001232,2.701039,-32.100098,35.0,203.17984,false,Manual,3.0",
            ["Content"] = "要是放在以前也不是不行。只是……唉，卡米拉女士，您知道的，最近全国上下都在通缉那什么，“神奇的同盟”，所以长官特别吩咐了，各城镇都得严查。",
            ["ContentJP"] = "今までだったら問題なかったんだが、参ったな……カミラさんも知ってるだろう？最近は国中が「フォースイクン」だったか？を探し出そうと躍起になっていて、すべての地域で厳しく検問しろって命令が出てるんだ。",
            ["DialogueId"] = 10100614,
            ["GUID"] = "19492BFC",
            ["LookAt"] = {
                [1] = "200071:n(200003)",
                },
            ["NextDialogue"] = 10100615,
            ["Scripts"] = "PARA{\
