            },
        [10100615] = {
            ["Camera"] = "71.237305,19.397461,134.438965,0.001202,0.399996,-170.399307,35.0,165.0,false,Manual,4.0",
            ["Content"] = "……是“神弃者同盟”。我以我本人，卡米拉·斯卡雷特的信誉担保，{性别：他|她}和神弃者同盟绝无关系。",
            ["ContentJP"] = "……「フォーセイクン同盟」かしら。そいつらとこの子は一切関係ないって誓えるけど……そうね、私ことカミラ・スカーレットの信用を担保にしてくださらない？",
            ["DialogueId"] = 10100615,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200002:Smile02",
                [2] = "100001:Smile01",
                },
            ["GUID"] = "19492C26",
            ["LookAt"] = {
