        [10100616] = {
            ["Camera"] = "-365.87207,335.160156,119.696777,0.001258,-1.199463,-44.99984,35.000008,640.0,false,Manual,10.0",
            ["Content"] = "行吧。您的人我放心。但千万记住，一定要看好{性别：他|她}，千万别在城里惹是生非，不然长官怪罪下来，咱俩就都有大麻烦了。",
            ["ContentJP"] = "……わかった。あんたがそこまで言う関係者ならば仕方ない。ただし絶対にそいつから目を離すなよ。街で騒ぎを起こすのなんざ厳禁だ。もし上官にバレでもしたら、俺もあんたも一大事になるからな。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10100616,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19492C50",
            ["NextDialogue"] = 10100617,
