            },
        [10100809] = {
            ["Camera"] = "-226.311523,-113.507812,192.955566,0.001224,-17.302214,34.000774,50.0,381.876587,false,Manual,6.0",
            ["Content"] = "好吧……有个穿白斗篷的家伙和卡米拉谈了一笔交易，要她找到你，带你进城。",
            ["ContentJP"] = "まあ簡単に言うと……白いマントを着たヘンチクリンが急に店に来てさ、カミラに取引を持ちかけたんだよ。{nickname}を見つけて街に連れ帰って欲しいってさ。",
            ["DialogueId"] = 10100809,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "19494BFA",
            ["LookAt"] = {
