        [10100810] = {
            ["Camera"] = "311.154297,29.604004,51.351074,0.001201,7.799625,177.456207,40.0,405.292908,false,Manual,5.0",
            ["Content"] = "你还记得那个人的长相吗？",
            ["ContentJP"] = "その人の容姿を、覚えていたりしますか？",
            ["DialogueId"] = 10100810,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "19494C24",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200003:n(100001)",
                [3] = "200002:n(100001)",
