        [10101701] = {
            ["Camera"] = "246.411194,114.218262,109.373657,0.001183,-13.29721,-168.309631,50.000011,93.339378,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "（太多事，发生了太多事......奇怪的梦、神秘的白斗篷、西比尔和“零号”……它们似乎有着某种关联，但我无法理清它们的头绪。）",
            ["ContentJP"] = "（本当、いろいろなことが起きた……奇妙な夢、謎の白いマント、シビルに「No.0」……すべてに何かのつながりがありそうだけど、まだ整理がつかない）",
            ["DialogueId"] = 10101701,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
