        [10102425] = {
            ["Camera"] = "-17.418396,194.422119,141.601807,0.000029,-2.999962,-85.199936,40.0,283.130951,false,Manual,5.0",
            ["Content"] = "好，我明白了。把拳头松开吧，赛琪。你的手都快掐破皮了。",
            ["ContentJP"] = "うん、わかったから拳の力を緩めて。赤くなってるよ。",
            ["DialogueId"] = 10102425,
            ["FacialId"] = {
                [1] = "200006:None",
                [2] = "100001:Ahaha02",
                },
            ["GUID"] = "194A53FA",
            ["NextDialogue"] = 10102426,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101024/194A53FA",
            },
        [10102426] = {
            ["Camera"] = "39.056404,-29.035645,137.217285,0.000045,0.599718,123.395554,40.0,133.348373,false,Manual,5.0",
            ["Content"] = "啊，我……",
            ["ContentJP"] = "あ、私……",
            ["DialogueId"] = 10102426,
            ["FacialId"] = {
                [1] = "200006:Shock01",
                },
            ["GUID"] = "194A53FB",
            ["NextDialogue"] = 10102427,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{200006},AnimationId{\"SpecialThink_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101024/194A53FB",
            },
        [10102427] = {
            ["Camera"] = "-8.967339,194.64624,141.601807,0.000016,-3.399843,-89.599655,40.000011,283.130951,false,Manual,5.0",
            ["Content"] = "放心，我不会乱来的。至少，我不能连累担保我进城的卡米拉女士，对吧？",
            ["ContentJP"] = "安心して。考えなしに首を突っ込んだりしないよ。カミラさんに迷惑をかけるわけにはいかないからね。",
            ["DialogueId"] = 10102427,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "194A53FC",
            ["NextDialogue"] = 10102428,
