            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A7278",
            },
        [10102605] = {
            ["Camera"] = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
            ["Content"] = "狩月人！那你们是找对地方了，正巧，现在这里就有一份委托——",
            ["ContentJP"] = "月狩り人ちゃんだって！？おおお、ナイスタイミングで来てくれたよ！今まさに依頼を出したところでさ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10102605,
            ["FacialId"] = {
                [1] = "200011:Happy01",
                },
            ["GUID"] = "194A72A2",
            ["LookAt"] = {
                [1] = "200003:n(200003)",
                },
            ["NextDialogue"] = 10102606,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200011},AnimationId{\"Shock_Start\"},Duration{1.3}},\
PlayAnimation{ActorId{200011},AnimationId{\"Shock_End\"},Duration{1.2}},\
PlayAnimation{ActorId{200011},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200011,
            ["SpeakNpcName"] = "UI_Npc_Name_NervouseMaer",
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A72A2",
            },
        [10102606] = {
            ["Camera"] = "-333.986206,-132.207031,145.634766,0.001253,-3.999936,19.037998,50.000008,264.189575,false,Manual,4.109556",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "先别插嘴，玛尔洁。",
            ["ContentJP"] = "口を挟まないでちょうだい、マギー。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10102606,
            ["Duration"] = 1,
            ["FinalCamera"] = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
            ["GUID"] = "194A72CC",
            ["LookAt"] = {
                [1] = "200003:n(200011)",
                [2] = "200011:n(200003)",
                },
            ["NextDialogue"] = 10102607,
            ["RelatedWikiId"] = {
                [1] = 201008,
                },
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200006:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A72CC",
            },
        [10102607] = {
            ["Camera"] = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
            ["Content"] = "……哦。",
            ["ContentJP"] = "……ぷぇ、わかってますって。",
            ["DialogueId"] = 10102607,
            ["Duration"] = 1.5,
            ["FacialId"] = {
                [1] = "200011:Syouganai01",
                },
            ["GUID"] = "194A72F6",
            ["NextDialogue"] = 10102608,
            ["Scripts"] = "TurnTo{_delay{1},TurnToDescription{\"200011:n(200003)\"}}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A72F6",
            },
        [10102608] = {
            ["Camera"] = "-109.342285,-78.164062,166.683594,0.00123,-3.99997,36.028351,50.0,253.714981,false,Manual,3.5",
            ["Content"] = "这么快就交上了朋友……你还挺受欢迎。至于狩月人——",
            ["ContentJP"] = "こんなに早くお友達を作っちゃうなんて、人に好かれる才能を持っているようね。加えて月狩り人に目をつけるとは――",
            ["DialogueId"] = 10102608,
            ["FacialId"] = {
                [1] = "100001:Confident01",
                },
            ["GUID"] = "194A7320",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                },
            ["NextDialogue"] = 10102609,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Think_End\"},Duration{1.5}},\
PlayAnimation{ActorId{200003},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A7320",
            },
        [10102609] = {
            ["Camera"] = "291.657104,98.844727,170.599609,0.001316,-5.498842,-164.352921,52.422081,496.264801,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "丑话说在前头，这不是小孩子玩闹，更不是什么轻松活计。这里是不问来历、不问出身，但你得到的每一枚回报，都伴随着相应的危险。",
            ["ContentJP"] = "先に言っておきましょう。子供のごっこ遊びじゃないし、簡単だって思わないでね？経歴や出自はここじゃ問わないけど、相応のリスクを背負ってもらう仕事ばかりだから。",
            ["DialogueId"] = 10102609,
            ["FacialId"] = {
                [1] = "200011:Unhappy01",
                },
            ["FinalCamera"] = "231.961548,82.132812,164.626953,0.001316,-5.498842,-164.352844,52.422081,430.432526,false,Manual,4.0",
            ["GUID"] = "194A734A",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                [2] = "200006:n(200003)",
                [3] = "200003:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 101026091,
                [2] = 101026092,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Confident_End\"},Duration{2}},\
PlayAnimation{ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{200003},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 14,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A734A",
            },
        [10102610] = {
            ["Camera"] = "-294.801819,-157.509766,135.695312,0.001227,1.1999,33.90601,60.000004,460.630157,false,Manual,12.0",
            ["Content"] = "模样不算硬朗，想法倒是坚决。",
            ["ContentJP"] = "見た目はヤワなのに、考え方は一丁前ね。",
            ["DialogueId"] = 10102610,
            ["FacialId"] = {
                [1] = "200006:None",
                [2] = "200011:None",
                },
            ["GUID"] = "194A7374",
            ["LookAt"] = {
                [1] = "200011:n(200003)",
                },
            ["NextDialogue"] = 10102611,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                [2] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A7374",
            },
        [10102611] = {
            ["Camera"] = "-43.718262,-1261.714844,610.828125,0.001481,-22.297657,82.031219,25.0,166.832703,false,DoNotOverride,22.0",
            ["Content"] = "你身手确实比一般的卡戎强些，我见过。但想要成为狩月人的话，只有蛮力是不够的——你还得证明自己能够应付突发事件与各种各样的雇主。",
            ["ContentJP"] = "腕前も並のカロンよりいいのは実際にこの目で見たわ。でも月狩り人として信頼するにはまだ――緊急事態の対処もそうだし、いろいろな雇い主の要望に応えられるのか証明してもらえないと。",
            ["DialogueId"] = 10102611,
            ["FinalCamera"] = "-98.231934,-1254.261719,610.828125,0.001477,-22.297657,82.031197,25.0,166.832703,false,DoNotOverride,22.0",
            ["GUID"] = "194A739E",
            ["NextDialogue"] = 10102612,
            ["Scripts"] = "SetLocation{ActorId{200011},TargetPoint{\"P10102601Maer\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A739E",
            },
        [10102612] = {
            ["Camera"] = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
            ["Content"] = "比如，这里就有一个证明的机会。",
            ["ContentJP"] = "たとえば今ここにある……証明のチャンスをものにすれば。",
            ["DialogueId"] = 10102612,
            ["GUID"] = "194A73C8",
            ["LookAt"] = {
                [1] = "200003:n(200011)",
                [2] = "100001:n(200003)",
                },
            ["NextDialogue"] = 10102613,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A73C8",
            },
        [10102613] = {
            ["Content"] = "啊……对、对！",
            ["ContentJP"] = "あぁ……そう、そうそう！",
            ["DialogueId"] = 10102613,
            ["FacialId"] = {
                [1] = "200011:Happy01",
                },
            ["GUID"] = "194A73F2",
