}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A73F2",
            },
        [10102614] = {
            ["Camera"] = "73.365112,16.138672,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
            ["Content"] = "诶，白刚才听着好像是，这位大姐姐的钱包被抢走了？",
            ["ContentJP"] = "ねえ、スノウも聞いてたけど。この人の財布が盗まれたんだよね？",
            ["DialogueId"] = 10102614,
            ["FacialId"] = {
                [1] = "200002:Think01",
                },
            ["FinalCamera"] = "72.002441,21.418945,155.199219,0.001344,-8.499999,-165.541534,35.0,266.048492,false,Manual,5.0",
            ["GUID"] = "194A741C",
            ["LookAt"] = {
                [1] = "200006:n(200011)",
                [2] = "200003:n(100001)",
                [3] = "100001:n(200011)",
                [4] = "200002:n(200011)",
                },
            ["Scripts"] = "SetLocation{ActorId{200002},TargetPoint{\"P10102601Bai3\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101026/194A741C",
            },
        [10102701] = {
            ["Content"] = "那位小姐这么着急，我也一起去帮忙吧。",
            ["ContentJP"] = "すごく困っているみたい。私も何か手伝ったほうがいいかな？",
            ["DialogueId"] = 10102701,
            ["GUID"] = "194A8262",
            ["NextDialogue"] = 10102702,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101027/194A8262",
            },
        [10102702] = {
            ["Content"] = "不要插手，这是对我们未来狩月人的简单考验。要是没有吃这碗饭的实力，做狩月人只会害了自己。",
            ["ContentJP"] = "余計なお世話はやめてちょうだい。これは月狩り人になれるかどうかのテストなのよ。自力がない人間に依頼を任せても死ぬだけだから。",
            ["DialogueId"] = 10102702,
            ["GUID"] = "194A828C",
            ["NextDialogue"] = 10102703,
            ["SpeakNpcId"] = 200003,
            ["TurnTo"] = {
                [1] = "2000061:n(200003)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101027/194A828C",
            },
        [10102703] = {
            ["Content"] = "好吧……",
            ["ContentJP"] = "わかりました……",
            ["DialogueId"] = 10102703,
            ["GUID"] = "194A82B6",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101027/194A82B6",
            },
        [10102801] = {
            ["Content"] = "你、你真的愿意帮我吗！呜……谢谢你，陌生人！",
            ["ContentJP"] = "ほ、本当に助けてくれちゃう感じ？たはぁ～マジで一生感謝します！",
            ["DialogueId"] = 10102801,
            ["GUID"] = "194A92CA",
            ["NextDialogue"] = 10102802,
            ["SpeakNpcId"] = 2000111,
            ["TurnTo"] = {
                [1] = "2000111:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101028/194A92CA",
            },
        [10102802] = {
            ["Content"] = "小贼刚才是往西边去了。但是冰湖城嘛，四通八达，谁知道他到底会窜到哪儿去。等下咱俩先找找线索！",
            ["ContentJP"] = "コソ泥は西の方に逃げていったんだけど、アイスレイク城は入り組んだ道が多いからさ。どこに行方をくらませたのか見当ついてなくてね。とりあえずは手がかりを探そっか。",
            ["DialogueId"] = 10102802,
            ["GUID"] = "194A92F4",
            ["SpeakNpcId"] = 2000111,
            ["VoiceName"] = "voice/$Locale$/story/1002/101028/194A92F4",
            },
        [10103001] = {
            ["Content"] = "原来井盖下面这么大、这么宽敞呀！还比上面暖和好多！就像一个秘密的小王国一样。",
            ["ContentJP"] = "マンホールの下にこんなおっきな空間があったんだね。外よりずっとあったかいし、小さな秘密の国って感じじゃない？",
            ["DialogueId"] = 10103001,
            ["GUID"] = "194A92F5",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103002,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194A92F5",
            },
        [10103002] = {
            ["Content"] = "把这些小动物请走，再把异味儿清理干净，搬个帐篷就能住人啦！",
            ["ContentJP"] = "住みついてる生き物を追い出して、臭いをなんとかしてさ。でもってテントとか持ち込めば十分暮らせるね。",
            ["DialogueId"] = 10103002,
            ["GUID"] = "194A92F6",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103003,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194A92F6",
            },
        [10103003] = {
            ["Content"] = "对啊对啊！而且，诶{nickname}你看，住在这儿还不用付房租！",
            ["ContentJP"] = "そうそう！それにほら、{nickname}、ここに住めば家賃もいらないよ！",
            ["DialogueId"] = 10103003,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194A92F7",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194A92F7",
            },
        [10103004] = {
            ["Content"] = "让我们一起来打跑这些家伙，抢走他们的国土，我做魔王，册封你为……",
            ["ContentJP"] = "よし、ヤツらを一網打尽にしてこの土地を奪おうではないか。スノウが魔王となって、{nickname}を……",
            ["DialogueId"] = 10103004,
            ["GUID"] = "194AB3EE",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194AB3EE",
            },
        [10103005] = {
            ["Content"] = "“骁勇的独目勇者，冷酷的冰湖之主，第一代下水道公爵”！",
            ["ContentJP"] = "「剛猛な片目の勇者かつ冷酷なアイスレイクの主である初代下水道公爵」に任命してあげるよ！",
            ["DialogueId"] = 10103005,
            ["GUID"] = "194AB418",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194AB418",
            },
        [10103006] = {
            ["Content"] = "（好像称呼有点太长了，缩短一些比较好……）",
            ["ContentJP"] = "（設定を詰め込みすぎ。もっと短い称号の方が好みかも……）",
            ["DialogueId"] = 10103006,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194AB419",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10103007,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194AB419",
            },
        [10103007] = {
            ["Content"] = "（等等，怎么我真的在一本正经思考了。）",
            ["ContentJP"] = "（って、何を真剣に考えている{性别:んだ。僕|の。私}は……）",
            ["DialogueId"] = 10103007,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194AB46C",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101030/194AB46C",
            },
