            ["VoiceName"] = "voice/$Locale$/story/1002/101032/194AD566",
            },
        [10103217] = {
            ["Camera"] = "-224.279297,-53.761719,138.360504,0.000002,-6.599731,-7.001203,20.000008,396.617218,false,DoNotOverride,5.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "嘁，我当是哪个人模狗样的，原来是开酒馆的大婶。你又能拿老子怎么样？叫士兵来抓？你不会真以为那些老爷会管卡戎的破事——",
            ["ContentJP"] = "はん、誰かと思えば酒場のババアじゃねぇかよ。……俺をどうする気だ？兵士でも呼ぶつもりか？あいつらがカロン族のもめごとに首を突っ込むとでも思って――",
            ["DialogueId"] = 10103217,
            ["FacialId"] = {
                [1] = "200011:Unhappy02",
                },
            ["FinalCamera"] = "-289.886719,-45.707031,146.008194,-0.0,-6.599731,-7.001234,20.000011,115.779877,false,DoNotOverride,5.0",
            ["GUID"] = "194AD567",
