        [10103401] = {
            ["Camera"] = "-217.132812,41.322266,158.146271,0.00012,-3.121273,6.666764,35.000008,100000.0,false,Disable,2.8",
            ["Content"] = "送他去治安署，直接找达米安署长。这情况我们处理不了。",
            ["ContentJP"] = "保安署に連れていって……ダミアン署長に引き渡しましょう。私たちの手に負える範疇を超えているわ。",
            ["DialogueId"] = 10103401,
            ["FacialId"] = {
