            },
        [10103403] = {
            ["Camera"] = "415.427734,94.491211,401.934753,8.000882,-38.599918,-167.192322,20.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "老……我、我知道了，知错了，这次是真的知错了！你们怎么惩罚我都行，千万别送我去那儿！",
            ["ContentJP"] = "お……俺が、お、わ、私が間違っていました！保安署には送らないで、お願いします、どんな罰も受けますから！",
            ["DialogueId"] = 10103403,
            ["FinalCamera"] = "395.310547,89.914062,385.454681,8.001169,-38.599918,-167.191513,20.0,100000.0,false,Disable,2.8",
            ["GUID"] = "194AE5A5",
            ["NextDialogue"] = 10103404,
            ["Scripts"] = "PARA{\
