            },
        [10103404] = {
            ["Camera"] = "1827.431641,564.506836,52.700241,8.011471,1.600771,-160.179901,25.0,171.285019,false,DoNotOverride,1.6",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "我、我可以离开冰湖城，再也不回来！放了我吧，求求你们！",
            ["ContentJP"] = "や、約束します！アイスレイク城から離れて、二度と戻りません。お願いします。見逃してください！",
            ["DialogueId"] = 10103404,
            ["FinalCamera"] = "1805.054688,588.825195,57.433624,8.012086,1.600771,-156.000839,25.0,533.129272,false,DoNotOverride,1.2",
