            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200065:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B3704",
            },
        [10103803] = {
            ["Camera"] = "-15.678711,45.273438,123.974609,0.001306,6.799911,-0.799835,30.000002,169.71138,false,Manual,2.5",
            ["Content"] = "抓了一个？这听起来倒跟真的似的，我得见识见识。",
            ["ContentJP"] = "ひとりだけ？珍しく嘘っぱちに聞こえないことを言うな。まあ実際この目で見ないことには信じられんが。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10103803,
            ["GUID"] = "194B372E",
            ["NextDialogue"] = 10103804,
            ["SpeakNpcId"] = 200065,
            ["TalkActionId"] = {
                [1] = "200065:Think_Start",
                [2] = "200002:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B372E",
            },
        [10103804] = {
            ["Camera"] = "174.522949,141.578125,137.132812,0.001337,-15.600308,-143.896393,35.0,212.370575,false,Manual,2.8",
            ["Content"] = "之前也没说过假话！快来快来，我的小仆从，这是威尔斯大叔，这里最勤快的狩月人啦。",
            ["ContentJP"] = "今までだって嘘もパチも言ってないし！さあ早く来い、我が下僕よ！彼はウェルズおじさん、ここで一番よく働いてる月狩り人なのさ。",
            ["DialogueId"] = 10103804,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "194B3758",
            ["NextDialogue"] = 10103805,
            ["Scripts"] = "PARA{\
