}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200065:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B3758",
            },
        [10103805] = {
