        [10103806] = {
            ["Camera"] = "-220.573608,96.777344,99.291016,0.001347,2.799155,-17.691002,30.000002,397.786072,false,Manual,2.5",
            ["Content"] = "就是你？长得白白净净，看不出来还真有点“本事”啊？",
            ["ContentJP"] = "お前がやったってのか？おとなしそうな顔して「なかなかなこと」をするじゃないか？",
            ["DialogueId"] = 10103806,
            ["GUID"] = "194B37AC",
            ["LookAt"] = {
                [1] = "200002:n(200065)",
                [2] = "100001:n(200065)",
                },
            ["NextDialogue"] = 10103807,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200065},AnimationId{\"Talk03_Start\"},Duration{3.4}},\
PlayAnimation{ActorId{200065},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200065,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B37AC",
            },
        [10103807] = {
            ["Camera"] = "284.5,160.327148,200.447266,0.001179,-15.600097,-147.194611,35.000011,345.690643,false,Manual,2.25",
            ["Content"] = "过奖了，小事而已。",
            ["ContentJP"] = "褒めてくれるのはうれしいですが、別にたいしたことでもなかったから。",
            ["DialogueId"] = 10103807,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "194B37D6",
            ["NextDialogue"] = 10103808,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Explain02_End\"},Duration{0.9}},\
PlayAnimation{ActorId{100001},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B37D6",
            },
        [10103808] = {
            ["Camera"] = "-88.652222,34.671875,132.285156,0.00134,1.999114,2.708378,30.0,289.613831,false,Manual,1.6",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "小事？我跟你说，就是你们这些干小事的人太多，冰湖城才是现在这副样子。要是干什么大事，那冰湖城还不得翻了天去。",
            ["ContentJP"] = "たいしたことじゃない？そりゃそうさ。だがな、そういう小さな仕事が積み重なって今のアイスレイクができあがってるんだ。お前さんみたいなヤツがみんなしてたいしたことをおっぱじめたら、この街は大変なことになるだろうよ。",
            ["DialogueId"] = 10103808,
            ["FinalCamera"] = "-37.667603,37.084961,137.621094,0.00134,1.999114,2.708446,30.0,210.36618,false,Manual,1.6",
            ["GUID"] = "194B3800",
            ["NextDialogue"] = 10103809,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{2.2}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain01_Start\"},Duration{5}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain01_End\"},Duration{2.1}},\
PlayAnimation{_delay{2.6},ActorId{200065},AnimationId{\"Talk01_Start\"},Duration{0.5}}\
}",
            ["SpeakNpcId"] = 200065,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B3800",
            },
        [10103809] = {
            ["Camera"] = "294.89917,204.099609,233.652344,0.001298,-17.702196,-144.748398,54.403389,386.499695,false,Manual,2.0",
            ["Content"] = "那我努努力，多向前辈学习——",
            ["ContentJP"] = "じゃあ、先輩方に習って、もっと勉強を――",
            ["DialogueId"] = 10103809,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "194B382A",
            ["NextDialogue"] = 10103810,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                [2] = "200065:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101038/194B382A",
            },
        [10103810] = {
            ["Camera"] = "-35.028076,37.188477,139.802734,0.00134,1.999114,2.708401,30.000002,206.157364,false,Manual,1.6",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "学习？先消停会儿吧！好好思考，想想清楚，自己为什么会走上这条路。",
            ["ContentJP"] = "勉強ってお前なぁ。胸に手を当てて考えてみろよ！自分のしてることに疑問を感じないのか？",
            ["DialogueId"] = 10103810,
            ["FacialId"] = {
                [1] = "200065:CM_Angry01",
                },
            ["FinalCamera"] = "26.359253,40.088867,147.71875,0.00134,1.999114,2.708373,30.000002,148.703949,false,Manual,1.6",
            ["GUID"] = "194B3854",
            ["NextDialogue"] = 10103811,
            ["Scripts"] = "SEQ{\
