        [10103815] = {
            ["Camera"] = "-247.799683,170.196289,195.980469,0.001317,-13.199579,-25.189466,29.355034,108.515091,false,DoNotOverride,3.527027",
            ["Content"] = "呃，搞了半天，原来你是捉小偷的那个？我还以为白管你叫仆从，一定是因为把你给抓住了，仔细想想，正常人怎么可能被白给抓住，我糊涂了。",
            ["ContentJP"] = "あれ、そうするとなんだ？コソ泥を捕まえたのはスノウじゃなくお前なのか？「下僕」と呼ばれていたから、てっきりお前がスノウに捕まったコソ泥なのかと……よくよく考えれば、スノウに捕まる人間とか普通いないよな。俺がバカだったわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10103815,
            ["FacialId"] = {
                [1] = "200065:CM_Idle",
                },
            ["FinalCamera"] = "-262.072144,135.240234,195.980469,0.001312,-13.199552,-17.988911,29.355034,108.515091,false,DoNotOverride,3.527027",
            ["GUID"] = "194B397A",
