        [10103816] = {
            ["Camera"] = "272.487305,158.962891,176.826172,0.001194,-13.800076,-148.534592,25.0,1000.0,false,DoNotOverride,2.0",
            ["Content"] = "我是让{性别：他|她}来给我作证的！谁叫大叔你整天想着说教别人，这下闹笑话了吧？",
            ["ContentJP"] = "スノウはこやつに説明してもらおうと思ってただけ！隙あらばガミガミお説教するおじさんも、今日は形なしお笑い草って感じだね？",
            ["DialogueId"] = 10103816,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200002:Confident01",
                [2] = "100001:Ahaha02",
                },
            ["FinalCamera"] = "272.487305,158.962891,165.708984,0.001196,-13.800069,-148.534744,25.0,1000.0,false,DoNotOverride,2.0",
            ["GUID"] = "194B39A4",
            ["LookAt"] = {
                [1] = "200002:n(200065)",
                },
            ["NextDialogue"] = 10103817,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{1.5}},\
PlayAnimation{ActorId{200002},AnimationId{\"Angry01_End\"},Duration{1}},\
