            ["SpeakNpcId"] = 200003,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B57AA",
            },
        [10104002] = {
            ["Camera"] = "264.06897,120.25293,140.035156,0.001216,-0.898272,38.841923,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来吧，喝口热饮。本来还想请你一杯，但既然威尔斯开了口，那就记他账上吧。",
            ["ContentJP"] = "さて、温かい飲み物でいいかしら？もともと私も一杯サービスするつもりだったのだけど、ウェルズに先を越されちゃったわね。まあウェルズに勘定つけたほうが、私の懐も痛まないからちょうどいいわ。",
            ["DialogueId"] = 10104002,
            ["GUID"] = "194B57D4",
            ["LookAt"] = {
                [1] = "200002:n(200065)",
                },
            ["NextDialogue"] = 10104003,
            ["Scripts"] = "PARA{\
SEQ{\
