            },
        [10104005] = {
            ["Camera"] = "1019.142822,-738.232422,198.009766,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "今天的委托我刚看过，净是吃力不讨好的小活。除了那个烫手山芋……",
            ["ContentJP"] = "今日貼り出してある依頼だって、時間をかけて達成しても報酬は子供の小遣い程度だけ。あの厄介事は別だが……",
            ["DialogueId"] = 10104005,
            ["FinalCamera"] = "1021.591187,-674.18457,195.511719,-0.0,0.200002,87.801537,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "194B5852",
            ["LookAt"] = {
                [1] = "100001:n(200065)",
                },
            ["NextOptions"] = {
                [1] = 101040051,
                },
            ["SpeakNpcId"] = 200065,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B5852",
            },
        [10104006] = {
            ["Camera"] = "206.755127,354.53418,169.501953,0.000076,-7.199996,-92.795441,30.000002,292.884125,false,Manual,2.0",
            ["Content"] = "一个麻烦委托，找一块见鬼的石头——唉，跟你说也没用，这活连我们这些老手都没人接，何况是你这样新来的。",
            ["ContentJP"] = "変な石ころ探せって依頼だがヤバい内容で――ってお前に説明しても仕方ないか。あれは俺もベテラン連中も避けてんだ。新米には言うまでもなく荷が重い。",
            ["DialogueId"] = 10104006,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "194B587C",
            ["LookAt"] = {
                [1] = "200003:n(100001)",
                [2] = "200002:n(200065)",
                },
            ["NextOptions"] = {
                [1] = 101040061,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200065},AnimationId{\"Sigh_End\"},Duration{2.2}},\
PlayAnimation{ActorId{200065},AnimationId{\"Talk01_Start\"},Duration{2}},\
PlayAnimation{ActorId{200065},AnimationId{\"Talk01_End\"},Duration{0.7}},\
PlayAnimation{ActorId{200065},AnimationId{\"Disagree\"},Duration{1.7}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200065,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B587C",
            },
        [10104007] = {
            ["Camera"] = "-60.295044,-143.261719,150.679688,0.001294,-1.100057,41.202648,65.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "去格雷姆废矿，找一种叫做<H>“群星绮晶”</>的罕见矿石。委托人是<H>恩里克·埃塞尔莱德</>——没错，就是你见过的那个恩里克。",
            ["ContentJP"] = "グルビューム廃鉱山へ行って<H>「群星のジェム」</>って珍しい鉱石を探してきて欲しいんだとか。依頼人は<H>ヘンリック・エセルレッド</>。そう、あなたも会ったことのある、あのヘンリックよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104007,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "194B58A6",
            ["NextDialogue"] = 10104008,
            ["RelatedWikiId"] = {
                [1] = 301004,
                },
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{ActorId{200003},AnimationId{\"Think_Start\"},Duration{4.9}},\
PlayAnimation{ActorId{200003},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{200003},AnimationId{\"Explain01_Start\"},Duration{3.5}},\
PlayAnimation{ActorId{200003},AnimationId{\"Explain01_End\"},Duration{1.4}},\
PlayAnimation{ActorId{200003},AnimationId{\"Agree\"},Duration{1}}\
},\
TurnTo{_delay{1},TurnToDescription{\"200065:n(200003)\"}}\
}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200065:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "100001:n(200003)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B58A6",
            },
        [10104008] = {
            ["Content"] = "格雷姆废矿现在已经是秽兽的巢穴了。曾有几个狩月人冒险去那儿，想去碰碰运气看还有没有月石剩下，他们都没能回来。",
            ["ContentJP"] = "廃鉱山になった今じゃあそこは<Default note=\"text:エジュウ\">穢獣</>の巣窟。掘り残された月ノ石が残ってるんじゃないかって月狩り人のグループが探しに向かったけど……誰一人として帰ってこなかったわ。",
            ["DialogueId"] = 10104008,
            ["GUID"] = "194B58D0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10104008.T_Story_Recall_10104008'",
            ["NextDialogue"] = 10104009,
            ["RelatedWikiId"] = {
                [1] = 406001,
                },
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B58D0",
            },
        [10104009] = {
            ["Camera"] = "124.620239,-443.34668,310.703125,0.001321,-20.100447,76.801399,25.0,680.331482,false,Manual,1.2",
            ["Content"] = "所以虽然恩里克悬赏了五千银币，不过一天下来还是没有狩月人接手。",
            ["ContentJP"] = "銀貨五千枚なんて破格の報酬をヘンリックは用意したけど、請け負う月狩り人は日をまたいでもまだ現れない始末でね。",
            ["DialogueId"] = 10104009,
            ["GUID"] = "194B58FA",
            ["NextDialogue"] = 10104010,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{3.3},ActorId{200003},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B58FA",
            },
        [10104010] = {
            ["Camera"] = "684.517334,308.858398,177.394531,0.00124,-5.298,-154.201248,54.56435,525.42511,false,Manual,3.0",
            ["Content"] = "狩月人是天生的冒险家，但不是来者不拒的莽夫！且不说废矿到底有没有他要的那石头，天知道恩里克到底能不能拿出来那笔钱？",
            ["ContentJP"] = "月狩り人は生来の冒険好きだが、なんでも引き受ける鉄砲玉と思われちゃ困る！お望みの石が廃鉱山に存在するのか真偽には目をつぶるとしても、ヘンリックが大金を出すって保証すら怪しいだろ？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104010,
            ["GUID"] = "194B5924",
            ["NextDialogue"] = 10104011,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2.5},ActorId{200065},AnimationId{\"Disagree\"},Duration{3.1}},\
PlayAnimation{ActorId{200065},AnimationId{\"Angry01_Start\"},Duration{1.9}},\
PlayAnimation{ActorId{200065},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{ActorId{200065},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayFacial{_delay{3},ActorId{200006},FacialId{\"Sad01\"}}\
}",
            ["SpeakNpcId"] = 200065,
            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B5924",
            },
        [10104011] = {
            ["Camera"] = "77.71582,492.297852,137.373047,0.001236,-2.698307,-72.790131,35.0,468.643616,false,Manual,2.0",
            ["Content"] = "你看他最近不是破产了，连家族房产都准备卖了吗？莫非他是准备靠倒卖群星绮晶赌一把？……不对啊，绮晶交易禁止这么多年了，他能找到门路卖出去？",
            ["ContentJP"] = "破産寸前で不動産まで投げ売っているらしいな。群星のジェムを転売して一発逆転でも狙うつもりか？ジェムの取引は数年前から禁止だってのに、売る手立てがあるようには見えんが。",
            ["DialogueId"] = 10104011,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "88.144165,495.515625,137.373047,0.001236,-2.698307,-72.790131,35.0,471.859924,false,Manual,6.0",
            ["GUID"] = "194B594E",
