        [10104013] = {
            ["Camera"] = "-875.020996,-905.817383,491.335938,0.001335,-14.498169,42.003368,30.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "卡米拉女士，您之前提到过的，到南方去要多少钱？",
            ["ContentJP"] = "カミラさん、この前、南へ行くにはいくらかかるって言ってました？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104013,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
