        [10104014] = {
            ["Camera"] = "261.244263,118.665039,141.974609,0.001213,-1.298371,39.241299,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "也是差不多的价格。怎么，你对这委托有兴趣？",
            ["ContentJP"] = "旅費も考えればちょうどこの依頼の報酬と同じぐらいかしらね……どうしたの？興味あるの？",
            ["DialogueId"] = 10104014,
            ["GUID"] = "194B59CC",
