            ["VoiceName"] = "voice/$Locale$/story/1002/101040/194B5A20",
            },
        [10104017] = {
            ["Content"] = "谢谢你，我明白的。但是，卡米拉女士……",
            ["ContentJP"] = "危険なことはわかっています。心配してくれてありがとう……でも、カミラさんの言った通り……",
            ["DialogueId"] = 10104017,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
