  { MinKey = 10104502, MaxKey = 10106214, Loader = function()
      return {
        [10104502] = {
            ["Content"] = "落满雪的针叶林，望不到边的冰湖……高个子山峰被天空按住了脑袋……很喜欢。",
            ["ContentJP"] = "雪の積もった針葉樹林、果てしない氷の湖……高い山脈に覆いかぶさる空……この風景が大好きなの。",
            ["DialogueId"] = 10104502,
            ["Duration"] = 3,
            ["GUID"] = "194BA9DC",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104503,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BA9DC",
            },
        [10104503] = {
            ["Content"] = "白还是更喜欢城里面！如果郊外没有那些到处巡逻的秽兽就好啦。",
            ["ContentJP"] = "スノウはやっぱり城内に一票！郊外はどうしても<Default note=\"text:エジュウ\">穢獣</>がうろついてるからさ。",
            ["DialogueId"] = 10104503,
            ["Duration"] = 3,
            ["GUID"] = "194BAA06",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA06",
            },
        [10104504] = {
            ["Content"] = "里面更安全些。但是，我喜欢这里的……空气。",
            ["ContentJP"] = "城内は安全だけど、私は外の空気が好き……匂いとかも。",
            ["DialogueId"] = 10104504,
            ["Duration"] = 3,
            ["GUID"] = "194BAA30",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104505,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA30",
            },
        [10104505] = {
            ["Content"] = "有区别吗？我闻起来都差不多耶……",
            ["ContentJP"] = "え？違うの？匂いとか……スノウには同じに思えるけど……",
            ["DialogueId"] = 10104505,
            ["Duration"] = 3,
            ["GUID"] = "194BAA5A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104506,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA5A",
            },
        [10104506] = {
            ["Content"] = "嗯……冰湖城的空气总是带着腥味，带着哭声。",
            ["ContentJP"] = "アイスレイク城の空気はいつも生臭い感じだよ。泣き声が聴こえてくるような匂いなの。",
            ["DialogueId"] = 10104506,
            ["Duration"] = 3,
            ["GUID"] = "194BAA84",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104507,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAA84",
            },
        [10104507] = {
            ["Content"] = "而这里是森林的味道，浮冰的味道，还有驶向远方的汽笛。这里偶尔能看到雪白的鹿从林间窜出——",
            ["ContentJP"] = "ここは森の匂い、流氷の匂い。遠くへ向かう汽笛の音が響いて、運がよければ林の間から真っ白な鹿さんが飛び出してきて――",
            ["DialogueId"] = 10104507,
            ["Duration"] = 3,
            ["GUID"] = "194BAAAE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104508,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAAAE",
            },
        [10104508] = {
            ["Content"] = "而冰湖城街道的角落窜出来的，是小偷、强盗……或者呜咽的乞丐。",
            ["ContentJP"] = "アイスレイクの外城区だと飛び出してくるのは泥棒や強盗……聞こえるのは物乞いさんのすすり泣きとかだから。",
            ["DialogueId"] = 10104508,
            ["Duration"] = 3,
            ["GUID"] = "194BAAD8",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104509,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAAD8",
            },
        [10104509] = {
            ["Content"] = "{nickname}，你呢？讲讲你的故乡吧！那座海岛是怎样的？",
            ["ContentJP"] = "{nickname}はどう？私、あなたの故郷のことが知りたい！海の小島ってどんな感じなの？",
            ["DialogueId"] = 10104509,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BAB02",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104510,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB02",
            },
        [10104510] = {
            ["Content"] = "那里的“空气”是金色的砂砾，海岸的迷迭香……",
            ["ContentJP"] = "あそこの「空気」は……金色の砂浜、海辺に咲くローズマリー……",
            ["DialogueId"] = 10104510,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BAB2C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104511,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB2C",
            },
        [10104511] = {
            ["Content"] = "是深夜朦胧的海雾，是我和贝……和家人每天眺望的巨大天之树。",
            ["ContentJP"] = "夜の海に漂うおぼろな霧……{性别:僕|私}とベ……家族で、巨大な天上樹を毎日眺めたり。",
            ["DialogueId"] = 10104511,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BAB56",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104512,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB56",
            },
        [10104512] = {
            ["Content"] = "嗯……那如果你什么时候回去故乡，请代我向它们问候~",
            ["ContentJP"] = "わぁ……いつか故郷に帰った時はさ？私の代わりにその景色に、よろしくって伝えて欲しいな。",
            ["DialogueId"] = 10104512,
            ["Duration"] = 3,
            ["GUID"] = "194BAB80",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104513,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BAB80",
            },
        [10104513] = {
            ["Content"] = "……唔唔，你们两个的话好难懂哦……",
            ["ContentJP"] = "ぬぐぐ、スノウにはふたりの話がチンプンカンプンだ……",
            ["DialogueId"] = 10104513,
            ["Duration"] = 3,
            ["GUID"] = "194BABAA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104514,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BABAA",
            },
        [10104514] = {
            ["Content"] = "等你再长大一些就明白啦。",
            ["ContentJP"] = "もう少し大きくなったらわかると思うよ。",
            ["DialogueId"] = 10104514,
            ["Duration"] = 3,
            ["GUID"] = "194BABD4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104515,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101045/194BABD4",
            },
        [10104515] = {
            ["Content"] = "……不过，皎皎之民似乎是长不大的？",
            ["ContentJP"] = "……でも、ルーナ族って大きくならないのかな？",
            ["DialogueId"] = 10104515,
