            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBB6A",
            },
        [10104610] = {
            ["Camera"] = "59.988281,-46.624023,150.626953,0.000005,-4.199733,-90.964828,40.000011,175.938858,false,Manual,8.987392",
            ["Content"] = "不，“没有经历过冒险，人生一定是不完整的”……我觉得，她说的没有错。",
            ["ContentJP"] = "違うの。「冒険とかの経験がない、どこか満たされない人生」……多分、何も間違っていないから。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104610,
            ["FacialId"] = {
                [1] = "200006:Satisfy01",
                },
            ["GUID"] = "194BBB94",
            ["LookAt"] = {
                [1] = "200006:n(100001)",
                },
            ["NextDialogue"] = 10104611,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{6.5}},\
PlayAnimation{ActorId{200006},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBB94",
            },
        [10104611] = {
            ["Camera"] = "-1093.402344,-90.92041,40.319336,0.000074,4.600064,-2.560578,40.000011,291.229248,false,DoNotOverride,8.987392",
            ["Content"] = "所以，可以带我一起去吗？",
            ["ContentJP"] = "お願い、私も一緒に行きたいの！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104611,
            ["FinalCamera"] = "-1163.527344,-87.78418,34.672363,0.000074,4.600064,-2.560578,40.000011,291.229248,false,DoNotOverride,8.987392",
            ["GUID"] = "194BBBBE",
            ["LookAt"] = {
                [1] = "200006:n(100001)",
                },
            ["NextDialogue"] = 10104612,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Talk02_End\"},Duration{1.8}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBBBE",
            },
        [10104612] = {
            ["Camera"] = "-54.855469,-231.366211,124.558594,0.000041,-12.799651,82.845856,35.000008,160.594696,false,Manual,7.37621",
            ["Content"] = "走吧走吧！冰湖城天黑得早，咱们得抓紧时间。",
            ["ContentJP"] = "オーケーゴーゴー！アイスレイク城の陽は落ちるのが早いんだし、急がなくっちゃ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104612,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["GUID"] = "194BBBE8",
            ["LookAt"] = {
                [1] = "200002:n(200006)",
                },
            ["NextDialogue"] = 10104613,
            ["Scripts"] = "SetRotation{SetRotationDescription{\"100001:n(200006)\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_Start",
                [2] = "200006:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBBE8",
            },
        [10104613] = {
            ["Camera"] = "47.644531,26.861328,156.047852,-0.0,-5.199734,-84.16452,40.000023,241.163803,false,Manual,8.987392",
            ["Content"] = "嗯！",
            ["ContentJP"] = "うん！",
            ["DialogueId"] = 10104613,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["GUID"] = "194BBC12",
            ["LookAt"] = {
                [1] = "200006:n(100001)",
                [2] = "100001:n(200006)",
                },
            ["NextDialogue"] = 10104614,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBC12",
            },
        [10104614] = {
            ["Camera"] = "-3371.945312,1771.284668,1105.757324,0.000082,-14.000022,-33.965176,56.0,2477.148193,false,DoNotOverride,8.987392",
            ["Content"] = "……好吧。你们当心些。",
            ["ContentJP"] = "……わかった。でも、気を{性别:つけよう|つけようね}。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10104614,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Satisfy01",
                },
            ["GUID"] = "194BBC3C",
            ["LookAt"] = {
                [1] = "100001:n(200006)",
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.9},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200006:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101046/194BBC3C",
            },
        [10104701] = {
            ["Content"] = "锁住了？看我给它敲开！",
            ["ContentJP"] = "もしかしてロックされちゃってる？なにおう！ブチ破ってやらぁ！",
            ["DialogueId"] = 10104701,
            ["Duration"] = 3,
            ["GUID"] = "194BCA82",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCA82",
            },
        [10104702] = {
            ["Content"] = "（头槌砸门声）",
            ["ContentJP"] = "（頭突きがドアに直撃する音）",
            ["DialogueId"] = 10104702,
            ["DisableMouth"] = 1,
            ["Duration"] = 2,
            ["GUID"] = "194BCA83",
            ["NextDialogue"] = 10104703,
            ["VoiceName"] = "sfx/common/story/01/tietougong",
            },
        [10104703] = {
            ["Content"] = "……哇！",
            ["ContentJP"] = "……にぎゃあ！？",
            ["DialogueId"] = 10104703,
            ["Duration"] = 2,
            ["GUID"] = "194BCAD6",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCAD6",
            },
        [10104704] = {
            ["Content"] = "这种厚度的门应该是无法用蛮力打开的。",
            ["ContentJP"] = "分厚い扉。無理やり開けるのは難しそうだ{性别:な|ね}。",
            ["DialogueId"] = 10104704,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BCB00",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB00",
            },
        [10104705] = {
            ["Content"] = "那我们在周围转转，看看有没有其它入口吧。",
            ["ContentJP"] = "ほかに出入り口はないか、探してみよっか。",
            ["DialogueId"] = 10104705,
            ["Duration"] = 3,
            ["GUID"] = "194BCB2A",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104706,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB2A",
            },
        [10104706] = {
            ["Content"] = "白，你的脑袋痛吗？我来帮你——",
            ["ContentJP"] = "スノウちゃん、痛かったの？こっちにおいで――",
            ["DialogueId"] = 10104706,
            ["Duration"] = 3,
            ["GUID"] = "194BCB54",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104707,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB54",
            },
        [10104707] = {
            ["Content"] = "……吹一下就不疼啦。",
            ["ContentJP"] = "……ふぅ～としたら、痛いの飛んでいくからね。",
            ["DialogueId"] = 10104707,
            ["Duration"] = 3,
            ["GUID"] = "194BCB7E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104708,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCB7E",
            },
        [10104708] = {
            ["Content"] = "呜呜……你真是个大好人。等本魔王大人彻底占领这里，就封你——",
            ["ContentJP"] = "うう……本当に優しいねサイキは。魔王様がここを掌握した暁にはサイキを――",
            ["DialogueId"] = 10104708,
            ["Duration"] = 3,
            ["GUID"] = "194BCBA8",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104709,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCBA8",
            },
        [10104709] = {
            ["Content"] = "“温柔的绿衣法师，睿智的月石主宰，第一代格雷姆矿场大公”！",
            ["ContentJP"] = "「温和なる緑の衣の魔術師かつ聡明な月ノ石の支配者である初代グルビューム鉱山大公」に任命してあげるよ！",
            ["DialogueId"] = 10104709,
            ["Duration"] = 3,
            ["GUID"] = "194BCBD2",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104710,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCBD2",
            },
        [10104710] = {
            ["Content"] = "（之前我是下水道公爵……大公是不是比公爵还要高级一点的爵位啊？）",
            ["ContentJP"] = "（{性别:僕|私}は下水道公爵だったけど……大公は公爵よりランクが高そう）",
            ["DialogueId"] = 10104710,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BCBFC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104711,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCBFC",
            },
        [10104711] = {
            ["Content"] = "（为什么赛琪的爵位比我高？等等，怎么我又在一本正经思考了。）",
            ["ContentJP"] = "（なぜサイキに爵位で負けたのかな――って、{性别:僕|私}はまた何を真剣に考えている{性别:んだ|の}）",
            ["DialogueId"] = 10104711,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BCC26",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101047/194BCC26",
            },
        [10104801] = {
            ["Content"] = "“在魔王大人白的指引下，刚刚从远方抵达冰湖城的小仆从，只一天功夫就成为了出色的‘狩月人’。”",
            ["ContentJP"] = "「魔王スノウに導かれ、遥か遠方よりアイスレイク城へとはせ参じた下僕は、ただの1日で『月狩り人』の称号を得たのだ！」",
            ["DialogueId"] = 10104801,
            ["GUID"] = "194BDAEA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDAEA",
            },
        [10104802] = {
            ["Content"] = "本魔王的传说又可以添上新的篇章啦。",
            ["ContentJP"] = "この魔王様の物語に、新たな伝説がまた1ページ……",
            ["DialogueId"] = 10104802,
            ["GUID"] = "194BDB14",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB14",
            },
        [10104803] = {
            ["Content"] = "“狩月人”这个名字还挺特别的……狩猎月亮？",
            ["ContentJP"] = "「月狩り人」って不思議な名前だけど……月を狩るのかな？",
            ["DialogueId"] = 10104803,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BDB3E",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB3E",
            },
        [10104804] = {
            ["Content"] = "错了错了！狩月人这个名字和月亮没什么关系，它最早的意思其实是——“月石猎人”！",
            ["ContentJP"] = "ぶっぶー不正解！月狩り人は月とあまり関係ないよ。もとの意味は「月ノ石の狩り人」だから！",
            ["DialogueId"] = 10104804,
            ["GUID"] = "194BDB68",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104805,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB68",
            },
        [10104805] = {
            ["Content"] = "嗯，我听说这个职业就是起源于冰湖城。",
            ["ContentJP"] = "うん、アイスレイク城で生まれた職業みたい。",
            ["DialogueId"] = 10104805,
            ["GUID"] = "194BDB92",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104806,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDB92",
            },
        [10104806] = {
            ["Content"] = "似乎是因为，维德弗尼尔山一带有丰富的天之树矿脉，上面的月石可以卖出好价钱……",
            ["ContentJP"] = "ヴィドフニル山脈には天上樹の鉱脈があって、山で見つかる月ノ石は高い値段で取引されていたんだって……",
            ["DialogueId"] = 10104806,
            ["GUID"] = "194BDBBC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104807,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDBBC",
            },
        [10104807] = {
            ["Content"] = "没错！所以很久很久以前，就有很多人冒险接受委托去采月石了。",
            ["ContentJP"] = "そうそう、危険を承知で採取の依頼を受けていたのが月狩り人ってわけ！",
            ["DialogueId"] = 10104807,
            ["GUID"] = "194BDBE6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104808,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDBE6",
            },
        [10104808] = {
            ["Content"] = "不过大商人和帝国先后接管了这附近的矿区，普通人就没什么机会碰到月石了……",
            ["ContentJP"] = "でも大商人と帝国が鉱区を管理するようになって、一般の人は月ノ石を採取できなくなって……",
            ["DialogueId"] = 10104808,
            ["GUID"] = "194BDC10",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104815,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC10",
            },
        [10104809] = {
            ["Content"] = "不过呢，靠接取委托为生的狩月人，还是作为一种特色职业保留了下来，只是委托的种类呢就五花八门啦。",
            ["ContentJP"] = "それから、月狩り人は月ノ石採取以外の依頼を受けるようになったんだけど、職業として名前が残ったのさ。最近はいろんな依頼がありすぎて、月はどこへ行ったのやらって感じだよ。",
            ["DialogueId"] = 10104809,
            ["GUID"] = "194BDC3A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104810,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC3A",
            },
        [10104810] = {
            ["Content"] = "大到从秽兽的魔爪下保护城市，小到从狗嘴里抢刚出炉的面包……",
            ["ContentJP"] = "「<Default note=\"text:エジュウ\">穢獣</>から街を守ってくれ！」なんて立派な依頼もあれば、「犬に盗まれた焼きたてパンを取り返して！」なんてショボいのも……",
            ["DialogueId"] = 10104810,
            ["GUID"] = "194BDC64",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104811,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC64",
            },
        [10104811] = {
            ["Content"] = "和狗抢面包？",
            ["ContentJP"] = "犬からパンを取り返す？だって？",
            ["DialogueId"] = 10104811,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BDC8E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104812,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC8E",
            },
        [10104812] = {
            ["Content"] = "还有一些更可怕的，比如让自己讨厌的家伙再也不会出现……",
            ["ContentJP"] = "物騒な依頼もあるんだぞ！例えば「憎き相手を二度と歩けないようにしろ」とか……",
            ["DialogueId"] = 10104812,
            ["GUID"] = "194BDCB8",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104813,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDCB8",
            },
        [10104813] = {
            ["Content"] = "可是，跑一趟水仙平原的功夫，面包不是早就被狗吃掉了吗？",
            ["ContentJP"] = "依頼を出しにアスフォデロスまで行くあいだに、パンはワンちゃんに食べられちゃうんじゃないかな？",
            ["DialogueId"] = 10104813,
            ["GUID"] = "194BDCE2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104814,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDCE2",
            },
        [10104814] = {
            ["Content"] = "你们两个能不能别再关心狗啦！",
            ["ContentJP"] = "ふたりとも犬の話題はもういいから。スノウの話も聞いて？",
            ["DialogueId"] = 10104814,
            ["GUID"] = "194BDD0C",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDD0C",
            },
        [10104815] = {
            ["Content"] = "再后来，这附近的矿脉也渐渐枯竭掉了，比如现在这座格雷姆废矿……",
            ["ContentJP"] = "最後は鉱脈が枯れちゃったの。今いるグルビューム廃鉱山も月ノ石の採取が盛んだった鉱山のひとつで……",
            ["DialogueId"] = 10104815,
            ["GUID"] = "194BDC11",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104816,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC11",
            },
        [10104816] = {
            ["Content"] = "对呀，好可惜哦！否则小仆从就能靠卖月石大赚一笔了。",
            ["ContentJP"] = "鉱脈が枯れてなければ下僕も月ノ石で大もうけできたのに、残念だね。",
            ["DialogueId"] = 10104816,
            ["GUID"] = "194BDC12",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104809,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101048/194BDC12",
            },
        [10104901] = {
            ["Content"] = "没事吧？",
            ["ContentJP"] = "大丈夫？",
            ["DialogueId"] = 10104901,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BEB52",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEB52",
            },
        [10104902] = {
            ["Content"] = "……！！",
            ["ContentJP"] = "……！！",
            ["DialogueId"] = 10104902,
            ["GUID"] = "194BEB7C",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104903,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEB7C",
            },
        [10104903] = {
            ["Content"] = "我刚刚突然看不清东西，没想到竟然惊动了它……抱歉！",
            ["ContentJP"] = "ごめんなさい……！急に目がかすんじゃって……あいつに気づかれた……",
            ["DialogueId"] = 10104903,
            ["GUID"] = "194BEBA6",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104904,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBA6",
            },
        [10104904] = {
            ["Content"] = "现在好些了吗？",
            ["ContentJP"] = "目の具合は？",
            ["DialogueId"] = 10104904,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BEBD0",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBD0",
            },
        [10104905] = {
            ["Content"] = "嗯，没问题了。",
            ["ContentJP"] = "うん、平気。",
            ["DialogueId"] = 10104905,
            ["GUID"] = "194BEBFA",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104906,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEBFA",
            },
        [10104906] = {
            ["Content"] = "好。可以战斗的话，一起来对付这个大块头。",
            ["ContentJP"] = "よし、戦えそうなら、一緒にこのデカブツをやっつけよう。",
            ["DialogueId"] = 10104906,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194BEC24",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10104907,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEC24",
            },
        [10104907] = {
            ["Content"] = "明白了！我会尽我所能支援你。",
            ["ContentJP"] = "わかった！全力でサポートするから！",
            ["DialogueId"] = 10104907,
            ["GUID"] = "194BEC4E",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101049/194BEC4E",
            },
        [10105001] = {
            ["Content"] = "我听说多凶猛的野兽，只要能找到<H>弱点</>，就能打败……",
            ["ContentJP"] = "<H>弱点</>さえ見つければ凶暴な野獣を倒せるって聞いたことがあるの。",
            ["DialogueId"] = 10105001,
            ["GUID"] = "194BFBB9",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105002,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101050/194BFBB9",
            },
        [10105002] = {
            ["Content"] = "秽兽一定也是这样！我们冷静下来……想办法找找它的弱点吧。",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>もきっと同じだと思うから。冷静に……あいつの弱点を探してみよう？",
            ["DialogueId"] = 10105002,
            ["GUID"] = "194BFBBA",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101050/194BFBBA",
            },
        [10105101] = {
            ["Content"] = "它变迟钝了。{nickname}，<H>看起来像肩膀的位置</>就是它的弱点！",
            ["ContentJP"] = "動きが鈍くなったよ！きっと<H>肩</>があいつの弱点なの！やっつけちゃえ、{nickname}！",
            ["DialogueId"] = 10105101,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C0C4C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101051/194C0C4C",
            },
        [10105201] = {
            ["Content"] = "它停下来了——趁这个机会！",
            ["ContentJP"] = "動きが止まったの――今だよ！",
            ["DialogueId"] = 10105201,
            ["GUID"] = "194C1C8A",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105202,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101052/194C1C8A",
            },
        [10105202] = {
            ["Content"] = "太好了……！",
            ["ContentJP"] = "私たち、やったんだね……！",
            ["DialogueId"] = 10105202,
            ["GUID"] = "194C1CB4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101052/194C1CB4",
            },
        [10105301] = {
            ["Content"] = "群星绮晶……真漂亮！难怪大家都喜欢。",
            ["ContentJP"] = "みんなが欲しがる群星のジェム……やっぱきれいだな。",
            ["DialogueId"] = 10105301,
            ["GUID"] = "194C2CF2",
            ["SpeakNpcId"] = 200021,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_17",
            ["VoiceName"] = "voice/$Locale$/story/1002/101053/194C2CF2",
            },
        [10105302] = {
            ["Content"] = "刚刚这边好大的动静——该不会是你们搞定了那个大家伙？有两下子嘛。",
            ["ContentJP"] = "なんか騒がしかったが――お前たちがあいつを倒したのか。やるじゃねえか。",
            ["DialogueId"] = 10105302,
            ["GUID"] = "194C2D1C",
            ["SpeakNpcId"] = 200021,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_17",
            ["VoiceName"] = "voice/$Locale$/story/1002/101053/194C2D1C",
            },
        [10105401] = {
            ["Camera"] = "-29.328125,-255.251953,164.21875,0.001081,-14.107393,94.226692,50.000008,544.145996,false,Manual,5.0",
            ["Content"] = "奥特赛德？！你装什么傻，绮晶怎么会在你手里？是我家小仆从先——",
            ["ContentJP"] = "アウトサイダー！？なにかっこつけてんのさ。って、うぎゃあジェムが……！それはスノウの下僕のモノだぞ――",
            ["DialogueId"] = 10105401,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                [2] = "200002:Angry01",
                },
            ["FinalCamera"] = "-3.181641,-258.998047,197.030273,0.001091,-23.507626,104.626007,50.000008,311.108795,false,Manual,5.0",
            ["GUID"] = "194C3D5A",
