        [10105404] = {
            ["Camera"] = "-82.755859,381.703125,133.121094,0.001257,1.800014,76.308632,50.000008,149.680878,false,Manual,12.0",
            ["Content"] = "请还给我们！这颗绮晶对{nickname}、对我们都很重要！",
            ["ContentJP"] = "返してください！そのジェムは大切なモノなの！{nickname}にとっても、私にとっても！",
            ["DialogueId"] = 10105404,
