            },
        [10105408] = {
            ["Camera"] = "-66.146484,-162.783203,62.850586,0.001408,5.398533,100.412529,50.0,176.147034,false,Manual,3.0",
            ["Content"] = "好，很有气势！{nickname}，打他！",
            ["ContentJP"] = "いいねぇ、バッチバチに怖くていいよ！さあ{nickname}、あいつをブン殴れ！スノウが許可する！",
            ["DialogueId"] = 10105408,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
