        [10105409] = {
            ["Camera"] = "-76.011719,43.419922,154.643555,0.000008,-0.200466,-68.806732,50.0,182.562775,false,Manual,8.0",
            ["Content"] = "喂喂喂，动口不动手，动口不动手。要不这样，一人一半，你看行不行？",
            ["ContentJP"] = "待て待て待て、暴力反対！お前らどんだけ血気盛んなんだ？ここは、なあ？半分ずつ山分けでどうだ？賢くいこうぜ？",
            ["DialogueId"] = 10105409,
