        [10105410] = {
            ["Camera"] = "-79.025391,636.621094,135.024414,0.000017,-1.799809,-84.781464,50.000008,855.271484,false,Manual,12.0",
            ["Content"] = "火气这么大？小姑娘，要不你帮我劝劝你的同伴。",
            ["ContentJP"] = "取りつく島もねえ！そこの嬢ちゃん、お仲間に「落ち着け」って言ってやってくれ！",
            ["DialogueId"] = 10105410,
