        [10105412] = {
            ["Camera"] = "-30.539062,-5.080078,158.119141,0.001307,-0.707266,-85.384132,50.0,127.462646,false,Manual,8.0",
            ["Content"] = "没关系，你很有礼貌，我可以原谅——",
            ["ContentJP"] = "いいって気にすんな。嬢ちゃんは礼儀正しいみたいだし、特別に許してやらんことも――",
            ["DialogueId"] = 10105412,
