        [10105413] = {
            ["Camera"] = "-53.419922,368.90625,141.725586,0.00131,-2.000234,-86.268929,50.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不懂规矩确实是我们的错……所以，为了表示歉意，奥特赛德先生，请你先动手吧。",
            ["ContentJP"] = "たしかにルールを理解していないのは私たちが悪いのかもしれません……だからお詫びとしてアウトサイダーさん、そちらから攻撃を仕掛けて大丈夫です。",
            ["DialogueId"] = 10105413,
            ["FinalCamera"] = "-48.773438,318.841797,110.551758,0.00131,4.599661,-86.668335,45.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "194C3F52",
            ["NextDialogue"] = 10105414,
            ["Scripts"] = "SEQ{\
