        [10105415] = {
            ["Camera"] = "-184.5,230.808594,85.188477,0.00131,8.499528,-62.082497,60.0,404.742706,false,Manual,2.8",
            ["Content"] = "等，等等！我跟你说，我很强的啊，整个冰湖城的狩月人没谁能打过我。听说过大军团长西比尔没？我啊，能跟她打个五五开。",
            ["ContentJP"] = "タ、タイム、タイム！言っとくが俺は強いぞ？アイスレイク城で俺に勝てる月狩り人なんざいない。帝国のシビル軍団長って聞いたことあるだろ？俺はそいつと五分五分の喧嘩ができるんだぜ？",
            ["DialogueId"] = 10105415,
            ["Duration"] = 2,
            ["FacialId"] = {
                [1] = "200021:Unhappy02",
                },
            ["FinalCamera"] = "-181.439453,232.429688,86.922852,0.00131,8.299533,-62.682556,60.0,404.742706,false,Manual,2.8",
