        [10105430] = {
            ["Camera"] = "-132.251953,201.019531,133.736328,0.001431,1.600122,-68.005325,50.000008,389.24408,false,Manual,8.0",
            ["Content"] = "今天算是幸运，贸然闯进来的是你这样的“骸”。要是换成普通人，肯定也和他们一个下场了。",
            ["ContentJP"] = "お前は運がよかったんだよ。無鉄砲にこんなとこまで来て無事だったのは、お前が「骸」だったからだ。普通のヤツなら間違いなくこいつらと同じ末路をたどってた。",
            ["DialogueId"] = 10105430,
            ["FinalCamera"] = "-137.875,198.705078,133.736328,0.001431,1.80011,-66.605614,50.000008,389.24408,false,Manual,8.0",
            ["GUID"] = "194C414A",
