            ["Content"] = "<H>“骸”</>？",
            ["ContentJP"] = "<H>むく…ろ</>？",
            ["DialogueId"] = 10105431,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C4174",
            ["NextDialogue"] = 10105432,
