            },
        [10105435] = {
            ["Camera"] = "-437.984375,565.548828,190.137695,0.001318,-9.399911,-52.879211,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哪里过分了，这叫“诚实”。我真诚的心和这颗绮晶一样晶莹剔透。",
            ["ContentJP"] = "何がおかしいんだよ？「正直」な評価そのものだろ。俺の心は、このジェムと同じぐらい透き通ってるのになぁ。",
            ["DialogueId"] = 10105435,
            ["FacialId"] = {
