            },
        [10105446] = {
            ["Camera"] = "227.804688,530.064453,114.802734,0.000015,-1.793635,-114.596718,35.0,803.517822,false,DoNotOverride,4.0",
            ["Content"] = "我会回去晚一些，到时候水仙平原可能已经打烊了。去我家找我吧，我家在城南的那堆破房子那儿，门上画着一只小鸟那个。",
            ["ContentJP"] = "帰りは少し遅くなるから、頃合いを見て俺の家まで来てくれ。街の南のボロ家だらけの場所で、扉に小鳥が描いてある家だ。",
            ["DialogueId"] = 10105446,
            ["FinalCamera"] = "227.804688,530.064453,104.378906,0.000015,-1.393611,-114.396393,35.0,803.517822,false,DoNotOverride,4.0",
            ["GUID"] = "194C43EA",
            ["NextDialogue"] = 10105447,
            ["Scripts"] = "SEQ{\
TurnTo{_delay{2},TurnToDescription{\"200021:n(200061)\"}},\
PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Think_Start\"},Duration{3}},\
}\
\
",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/101054/194C43EA",
            },
        [10105447] = {
            ["Camera"] = "-9.882812,4.484375,146.6875,0.000026,1.206198,-92.395676,50.0,241.293564,false,Manual,4.0",
            ["Content"] = "还有，一个人来——别带无关的家伙。",
            ["ContentJP"] = "それと来る時はひとりだけ、無関係なヤツは絶対に連れてくるな。",
            ["DialogueId"] = 10105447,
            ["FinalCamera"] = "-9.882812,4.484375,146.6875,0.000026,1.406199,-92.39563,52.0,241.293564,false,Manual,4.0",
            ["GUID"] = "194C4414",
            ["LookAt"] = {
                [1] = "200021:n(200006)",
                },
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Think_End\"},Duration{1}},\
",
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101054/194C4414",
            },
        [10105501] = {
            ["Content"] = "那边好像有条路！我们快上去，这里站久了老觉得阴森森的……",
            ["ContentJP"] = "あっちに道があるよ。早く行こう。こんな場所にずっといたら心が暗くなっちゃう……",
            ["DialogueId"] = 10105501,
            ["GUID"] = "194C4DC1",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101055/194C4DC1",
            },
        [10105502] = {
            ["Content"] = "……等等，刚才他那句“无关的家伙”，说的不会是我吧？",
            ["ContentJP"] = "……ん？ちょっと待って。アウトサイダーが言ってた「無関係なヤツ」って？私のことじゃないよね？",
            ["DialogueId"] = 10105502,
            ["GUID"] = "194C4DC2",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101055/194C4DC2",
            },
        [10105601] = {
            ["Content"] = "这条小路和之前的矿道好像不太一样，像是什么人自己挖出来的。",
            ["ContentJP"] = "この道、さっき通ってきた坑道と違う……誰かが掘ったのかな？",
            ["DialogueId"] = 10105601,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C5E2A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5E2A",
            },
        [10105602] = {
            ["Content"] = "还真是耶，这里还有好几把镐子……看来早有冒险家来过这儿了！",
            ["ContentJP"] = "ほんとだね。スコップが転がってるし......かなり昔にもここに来た冒険家がいたみたいだね。",
            ["DialogueId"] = 10105602,
            ["Duration"] = 3,
            ["GUID"] = "194C5E54",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5E54",
            },
        [10105603] = {
            ["Content"] = "诶，赛琪你怎么脸色那么差？从刚才开始就没见你说话了。",
            ["ContentJP"] = "というかサイキ、調子悪いの？さっきから何も話してないし、顔色もよくないみたいだけど。",
            ["DialogueId"] = 10105603,
            ["Duration"] = 3,
            ["GUID"] = "194C5E7E",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105604,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5E7E",
            },
        [10105604] = {
            ["Content"] = "啊，我、我有吗？",
            ["ContentJP"] = "えっ、そ、そうかな？",
            ["DialogueId"] = 10105604,
            ["Duration"] = 3,
            ["GUID"] = "194C5EA8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105605,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5EA8",
            },
        [10105605] = {
            ["Content"] = "可能是想到刚才那只怪物，还有些后怕吧。那只怪物会不会曾经也……",
            ["ContentJP"] = "多分……さっきの<Default note=\"text:エジュウ\">穢獣</>のせいだと思う。まだちょっと足が震えちゃっているから。",
            ["DialogueId"] = 10105605,
            ["Duration"] = 3,
            ["GUID"] = "194C5ED2",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105606,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5ED2",
            },
        [10105606] = {
            ["Content"] = "这有什么好怕的！不是有我们在吗？",
            ["ContentJP"] = "恐るるに足らず！この魔王様と下僕がいるのだぞ！",
            ["DialogueId"] = 10105606,
            ["Duration"] = 3,
            ["GUID"] = "194C5EFC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105607,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5EFC",
            },
        [10105607] = {
            ["Content"] = "刚才那家伙说过，小仆从是很厉害的“骸”吧？就算再来十只秽兽，肯定也不是{性别：他|她}的对手。",
            ["ContentJP"] = "さっきのアホチンサイダーも我が下僕は特別な「骸」だと語ってたじゃんか？たとえ10匹ぐらい<Default note=\"text:エジュウ\">穢獣</>が来たって、{nickname}の相手にはならないのさ！",
            ["DialogueId"] = 10105607,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C5F26",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105608,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5F26",
            },
        [10105608] = {
            ["Content"] = "少起哄，我已经快用光力气了，赛琪刚刚也是在虚张声势吧。",
            ["ContentJP"] = "適当なこと{性别:言うなって|言わないでよ}。こっちはもうヘトヘトだし、サイキだってさっきは無理に強がってたんだから。",
            ["DialogueId"] = 10105608,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C5F50",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105609,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5F50",
            },
        [10105609] = {
            ["Content"] = "还好你们都平安无事……也许我当时不该让你们一起涉险。",
            ["ContentJP"] = "みんな無事で本当によかった……やっぱりふたりを巻き込むべきじゃなかったかもしれない。",
            ["DialogueId"] = 10105609,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C5F7A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105610,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5F7A",
            },
        [10105610] = {
            ["Content"] = "不是的！这一次的“冒险”，我很满足。",
            ["ContentJP"] = "そんなことないよ！今日一緒に「冒険」できて、私はすっごく満足だったんだから！",
            ["DialogueId"] = 10105610,
            ["Duration"] = 3,
            ["GUID"] = "194C5FA4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105611,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5FA4",
            },
        [10105611] = {
            ["Content"] = "我从未想过能和伙伴们一起逃离熟悉的城市，去未曾去过的地方，一起闯祸，一起战胜险恶的敌人。",
            ["ContentJP"] = "仲間と一緒に、慣れ親しんだ街から一歩を踏み出して、行ったことのない場所に向かう。みんなでおしゃべりしたり、危険な敵に立ち向かったり……私にこんなことができるなんて、夢にも思わなかったの。",
            ["DialogueId"] = 10105611,
            ["Duration"] = 3,
            ["GUID"] = "194C5FCE",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105612,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5FCE",
            },
        [10105612] = {
            ["Content"] = "……现在想想，还有些晕乎乎的，就像是大白天做了一场梦一样。",
            ["ContentJP"] = "……そう考えると、まだ少しふわふわで、夢見心地で。",
            ["DialogueId"] = 10105612,
            ["Duration"] = 3,
            ["GUID"] = "194C5FF8",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105613,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C5FF8",
            },
        [10105613] = {
            ["Content"] = "你看，赛琪都这么说了吧！",
            ["ContentJP"] = "ね、サイキもこう言ってることだし！",
            ["DialogueId"] = 10105613,
            ["Duration"] = 3,
            ["GUID"] = "194C6022",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105614,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C6022",
            },
        [10105614] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 10105614,
            ["Duration"] = 3,
            ["GUID"] = "194C604C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101056/194C604C",
            },
        [10105701] = {
            ["Content"] = "那边那个不是……恩里克吗？他怎么跑这里来了？",
            ["ContentJP"] = "あそこにいるのって……ヘンリックじゃない？なんでここに？",
            ["DialogueId"] = 10105701,
            ["Duration"] = 3,
            ["GUID"] = "194C6E92",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101057/194C6E92",
            },
        [10105801] = {
