            },
        [10105805] = {
            ["Camera"] = "-15.444336,23.682617,166.880371,0.000075,-17.199617,-149.595322,45.0,83.977844,false,Manual,7.276294",
            ["Content"] = "格雷姆矿坑。我……想一起帮忙找群星绮晶。",
            ["ContentJP"] = "グルビューム鉱山。私……群星のジェムを探すのを手伝いたくて。",
            ["DialogueId"] = 10105805,
            ["FacialId"] = {
                [1] = "200059:Sad01",
                [2] = "200002:Unhappy02",
                [3] = "100001:Unhappy01",
                },
            ["GUID"] = "194C7FA2",
            ["NextDialogue"] = 10105806,
