CameraMoveTo{_delay{3.01},TargetPosition{\"208.405273,65.750488,166.410645,0.000057,-7.599855,-157.997894,30.0,405.834045,false,Manual,7.276294\"},duration{0}}\
}\
}",
            ["SpeakNpcId"] = 200059,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                [2] = "100001:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C7FA2",
            },
        [10105806] = {
            ["Camera"] = "-146.253906,8.684082,132.574219,0.000076,6.199974,-15.00077,35.0,195.174042,false,Manual,4.235867",
            ["Content"] = "先别管绮晶。进修普诺斯之家的第一天，我跟你说过什么，还记得吗？",
            ["ContentJP"] = "ジェムはどうでもいい。ヒュプノスの家に来た初日、俺が言ったことを覚えているか？",
            ["DialogueId"] = 10105806,
            ["GUID"] = "194C7FCC",
            ["NextDialogue"] = 10105807,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200005},AnimationId{\"Disagree\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C7FCC",
            },
        [10105807] = {
            ["Camera"] = "178.701172,37.807617,161.741211,0.000015,-4.800045,-164.274582,75.000015,266.881348,false,Manual,10.075966",
            ["Content"] = "“不要随便走动，如果一定要去什么地方，先和您说。”",
            ["ContentJP"] = "「むやみに出歩かない。どうしてもどこかに行きたい時は、必ず知らせる」",
            ["DialogueId"] = 10105807,
            ["FacialId"] = {
                [1] = "200059:Sad02",
                },
            ["GUID"] = "194C7FF6",
