        [10105813] = {
            ["Camera"] = "115.382812,-61.85791,174.962402,0.000078,-10.400042,155.7948,35.0,252.340637,false,Manual,4.235867",
            ["Content"] = "管好你自己的事，少和无关的人牵扯。这对谁都好。",
            ["ContentJP"] = "自分の面倒は自分でみろ。無関係な人間を巻き込むな。これは互いのための忠告だ。",
            ["DialogueId"] = 10105813,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "194C80C8",
            ["LookAt"] = {
                [1] = "200005:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 101058131,
                [2] = 101058132,
                },
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C80C8",
            },
        [10105814] = {
            ["Camera"] = "-248.442383,-210.168945,153.489746,0.000127,-3.200374,44.998043,35.000008,345.865082,false,Manual,5.41403",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "她不是你的女儿。就算是，你也不该连这点自由都不给她。你知道出一趟门她有多开心吗？",
            ["ContentJP"] = "サイキはあなたの娘じゃない。たとえそうだとしても、自由を奪う権利なんてない{性别:|よ}。たった1回出かけただけなのに、どれだけサイキが喜んでいたのか知りもしないで。",
            ["DialogueId"] = 10105814,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "-248.442383,-210.168945,153.489746,0.000127,-3.000386,39.998112,35.000008,345.865082,false,Manual,5.41403",
            ["GUID"] = "194C80F2",
            ["NextDialogue"] = 10105816,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100001},TargetPoint{\"P10105801Nvzhu\"},MoveSpeed{90},Visibility{\"Show\"}},\
PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{100001},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C80F2",
            },
        [10105815] = {
            ["Camera"] = "-248.442383,-210.168945,153.489746,0.000127,-3.200374,44.998043,35.000008,345.865082,false,Manual,5.41403",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "要不我们聊聊别的，比如，你对所有人都这么礼貌吗？难怪你那栋宅子会一直卖不出去。",
            ["ContentJP"] = "ヘンリックさん、あなたは身内とか関係なく誰に対してもそんな態度なんですね。どおりであの屋敷がずっと売れ残っているわけだ。",
            ["DialogueId"] = 10105815,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "-248.442383,-210.168945,153.489746,0.000127,-3.000386,39.998112,35.000008,345.865082,false,Manual,5.41403",
            ["GUID"] = "194C811C",
            ["NextDialogue"] = 10105816,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100001},TargetPoint{\"P10105801Nvzhu\"},MoveSpeed{90},Visibility{\"Show\"}},\
PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{100001},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200005:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C811C",
            },
        [10105816] = {
            ["Camera"] = "-129.060547,27.748535,125.864746,0.000099,7.798006,-6.398357,35.000011,185.640503,false,Manual,4.0",
            ["Content"] = "少自以为是。与其操别人的心，不如想想怎么过好你在屋檐下的最后一晚。",
            ["ContentJP"] = "図に乗るな。他人より自分の心配をしたらどうだ？屋根の下で過ごせる最後の夜だ。せいぜい身の振り方を考えておくんだな。",
            ["DialogueId"] = 10105816,
            ["GUID"] = "194C8146",
            ["NextDialogue"] = 10105817,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200005},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200005,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C8146",
            },
        [10105817] = {
            ["Camera"] = "-161.455078,-739.210938,56.689453,0.000176,4.600037,70.007301,40.000011,887.664001,false,Manual,1.912821",
            ["Content"] = "等天亮了，就给我搬出去。",
            ["ContentJP"] = "夜が明けたら、すぐに出ていけよ。",
            ["DialogueId"] = 10105817,
            ["GUID"] = "194C8170",
            ["NextDialogue"] = 10105818,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{200005},AnimationId{\"Angry01_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200005,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                [2] = "200005:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C8170",
            },
        [10105818] = {
            ["Camera"] = "-978.966797,-1154.05127,783.140869,0.000061,-23.880819,46.397503,30.000002,539.39325,false,DoNotOverride,1.2",
            ["Content"] = "赛琪，走，回去吧。",
            ["ContentJP"] = "さあ、サイキ、帰るぞ。",
            ["DialogueId"] = 10105818,
            ["FinalCamera"] = "-1003.191406,-1179.489258,798.692383,0.000061,-23.880819,46.397503,30.000002,539.39325,false,DoNotOverride,1.2",
            ["GUID"] = "194C819A",
