                [1] = "200005:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101058/194C819A",
            },
        [10105901] = {
            ["Content"] = "恩里克这家伙，一开口还是这么让人火大……",
            ["ContentJP"] = "ぐぎぎぎ、ヘンリックの野郎めがぁ……いちいち言い方がムカつくなぁ……！",
            ["DialogueId"] = 10105901,
            ["Duration"] = 3,
            ["GUID"] = "194C8F62",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8F62",
            },
        [10105902] = {
            ["Content"] = "但愿他不会责骂赛琪。",
            ["ContentJP"] = "サイキが叱られてしまわないか心配だけど……",
            ["DialogueId"] = 10105902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C8F8C",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8F8C",
            },
        [10105903] = {
            ["Content"] = "至于是不是住在宅子里的最后一晚，得要去找奥特赛德了。",
            ["ContentJP"] = "屋根の下で過ごせる最後の夜になるかどうかは……アウトサイダー次第だ{性别:な|ね}。",
            ["DialogueId"] = 10105903,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194C8FB6",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105904,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8FB6",
            },
        [10105904] = {
            ["Content"] = "要绕开我说悄悄话对吧？奥特赛德事儿真多。",
            ["ContentJP"] = "スノウを仲間外れにした内緒話だってねぇ？ウサンクサイダーめ、小賢しいったらありゃしない。",
            ["DialogueId"] = 10105904,
            ["Duration"] = 3,
            ["GUID"] = "194C8FE0",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10105905,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C8FE0",
            },
        [10105905] = {
            ["Content"] = "哼，我还不稀罕听呢！你走吧，我要去水仙平原玩了。",
            ["ContentJP"] = "ふん、そんなの興味ないもぉーんだ！行っちゃえばいいさ！私はアスフォデロスで遊んじゃうもんね！",
            ["DialogueId"] = 10105905,
            ["Duration"] = 3,
            ["GUID"] = "194C900A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101059/194C900A",
            },
