        [10106005] = {
            ["Camera"] = "331.934814,-24.207031,117.277344,0.000011,5.806794,40.010612,45.0,93.467445,false,Manual,8.517118",
            ["Content"] = "雪狼出没的密林，还是沼泽女巫的塔楼？",
            ["ContentJP"] = "白いオオカミの現れる森？それとも沼地の魔女の塔？",
            ["DialogueId"] = 10106005,
            ["GUID"] = "194CA072",
