        [10106008] = {
            ["Camera"] = "323.243591,24.703125,127.890625,0.000445,7.800567,-57.954342,40.0,290.985474,false,DoNotOverride,2.892337",
            ["Content"] = "哎呀，那都是之前的事了，这次是真的没有。看，我这次出门啊，是为了给菲娜带这个。",
            ["ContentJP"] = "今回に限っては本当に違うからさ。な、ほら、出かけてた理由はこれ。フィーナのために手に入れたんだぜ。",
