        [10106010] = {
            ["Camera"] = "-185.995667,-51.054688,175.679688,0.000535,-7.999517,1.439629,30.0,461.171814,false,DoNotOverride,1.2",
            ["Content"] = "我自有办法。要知道，我可是智慧超绝的魔法师啊。别管它了，我还有一个东西给你看。",
