            },
        [10106106] = {
            ["Content"] = "我叫{nickname}。你该不会就是那个……凶神恶煞的亲戚……？",
            ["ContentJP"] = "{性别:僕|私}は{nickname}{性别:だよ|よ}。アウトサイダーの恐ろしいファミリーって……あなたのことかな？",
            ["DialogueId"] = 10106106,
            ["GUID"] = "10106106",
            ["NextDialogue"] = 10106107,
            },
        [10106107] = {
            ["Camera"] = "386.396118,-50.326172,150.816406,0.000089,0.011434,-59.814888,45.0,100000.0,false,DoNotOverride,4.42362",
            ["Content"] = "……别听水仙平原的小矮子瞎说，那皎皎嘴里没句好话。",
            ["ContentJP"] = "……アスフォデロスのチビ助の言うことなんか真に受けるなよ。あのルーナ族はいつも口からでまかせばかりなんだぞ。",
            ["DialogueId"] = 10106107,
            ["GUID"] = "194CB0DC",
            ["LookAt"] = {
                [1] = "200021:n(100001)",
                [2] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10106108,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101061/194CB0DC",
            },
        [10106108] = {
            ["Camera"] = "392.718933,-45.626953,133.417969,0.000022,-8.587979,133.589279,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "凶神……恶煞？我不太明白……我是菲娜，奥特赛德的妹妹——咳、咳！",
            ["ContentJP"] = "恐ろしい……ファミリー？ごめんなさい、よくわからないけど……私はフィーナよ。アウトサイダーの妹で……ゴホ、ゴホ！",
