        [10106211] = {
            ["Camera"] = "247.410675,-57.9375,168.519531,0.000134,-20.200529,35.800228,50.000008,111.523781,false,Manual,7.19876",
            ["Content"] = "那位总是放许多糖的小姐一定有着强大的魔法。所以在{性别：大哥哥|大姐姐}眼里，和她有关的一切都是好的，哪怕是甜到无法下咽的饭菜。",
            ["ContentJP"] = "お砂糖をたくさん入れちゃう女の子は、実はすごい魔法が使えるの。だから{性别:お兄さん|お姉さん}にとっては、その女の子に関わるものはみーんな素敵なものなの。喉を通らないくらいあまーいお料理だって。",
            ["DialogueId"] = 10106211,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200020:Happy02",
                },
