            ["VoiceName"] = "voice/$Locale$/story/1002/101062/194CC23E",
            },
        [10106212] = {
            ["Camera"] = "90.803986,-143.320312,134.382812,0.000123,0.599335,20.609505,35.000008,213.622009,false,Manual,7.38829",
            ["Content"] = "好吧，菲娜说的都对。所以那个女孩儿现在在哪儿呢？要不你给她打包一份，让她品尝一下正常的甜食。",
            ["ContentJP"] = "なるほどたしかに、フィーナの言う通りだな……で、その女は今どこにいるんだ？よかったらこのケーキ少し持ち帰って、普通の甘さのお菓子を味わわせてやんな。",
            ["DialogueId"] = 10106212,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                },
