        [10107002] = {
            ["Camera"] = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
            ["Content"] = "你是为了住处的事情来的吧，别着急，先在这里躲一会儿吧。我再帮你求求恩里克叔叔，他一定会允许你多住上几天的。",
            ["ContentJP"] = "泊まる場所のことで来たんだよね？心配しないで、私がまたヘンリックおじさんに頼んでみる。だからしばらくここに隠れていて欲しいの。あと何日か泊まるくらいなら、きっと許してくれると思うし。",
            ["DialogueId"] = 10107002,
            ["FacialId"] = {
                [1] = "200006:Smile01",
                },
            ["FinalCamera"] = "-11.103516,535.533691,148.048828,0.0,-3.999328,-87.402275,35.0,549.519409,false,Manual,4.291738",
            ["GUID"] = "194D43DB",
            ["LookAt"] = {
