                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101071/194D553E",
            },
        [10107108] = {
            ["Camera"] = "-1277.564453,-593.944031,1182.701172,0.000064,-13.100098,20.401525,20.0,406.956116,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "就像我每天会把这里全部清理一遍，就像赛琪每天会给她的花浇水两次。习惯会让你空洞的内心变得充实。",
            ["ContentJP"] = "僕は1日1回ここを掃除する。サイキは1日2回花に水をあげる。そんな習慣が空っぽの心を満たしてくれるんだ。",
            ["DialogueId"] = 10107108,
            ["FinalCamera"] = "-1291.347656,-556.815186,1182.701172,0.000064,-13.100098,20.401525,20.0,406.956116,false,Manual,8.0",
