        [10107820] = {
            ["Camera"] = "-9.021729,-26.742188,128.609863,0.000102,5.600222,80.398033,35.0,95.583733,false,Manual,5.0",
            ["Content"] = "（……时候还早，或许我可以看看有没有什么能接的委托……）",
            ["ContentJP"] = "（休むにはまだ早い{性别:な|よね}。アスフォデロスに行って、{性别:僕|私}にできそうな依頼がないか確認してみようかな......）",
            ["DialogueId"] = 10107820,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194DD782",
            ["LookAt"] = {
