                [2] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101085/194E3A70",
            },
        [10108505] = {
            ["Camera"] = "38.050293,248.716797,38.96167,0.000147,18.199257,-84.5942,50.000008,342.942749,false,Manual,5.0",
            ["Content"] = "没有没有，怎么会，您最高大威猛了，冰湖城门就是专门为了您才修这么高——",
            ["ContentJP"] = "いやややや、滅相もございません。あなた様は山々と見紛うほどご立派であらせられる。アイスレイク城の城門はあなた様に合わせてあれほど巨大に建てられたとかなんたらかんたら――",
            ["DialogueId"] = 10108505,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                [2] = "\
200021:Smile02",
                [3] = "\
200064:None",
                },
            ["GUID"] = "194E3A9A",
