            },
        [10109007] = {
            ["Camera"] = "-54.203369,-87.207031,170.859375,0.000122,-15.201439,29.00316,50.0,139.404022,false,DoNotOverride,3.698512",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "不，救人早去总比晚去好。我不能再一次……看着……",
            ["ContentJP"] = "悠長すぎるよ。助けるって決めたならすぐに行動しなきゃ。もう二度と、あんなことは……",
