        [10109009] = {
            ["Camera"] = "46.280029,5.457031,149.058594,0.000183,0.999714,-140.175919,45.0,163.680023,false,Manual,8.0",
            ["Content"] = "“一个人离我而去，而我什么都做不到”。是吗？",
            ["ContentJP"] = "「誰かを失う時に、何もできない自分が許せない」……のか？",
