        [10109010] = {
            ["Camera"] = "-218.000488,-102.597656,160.563965,0.000186,-4.601375,10.503407,45.0,275.06012,false,Manual,8.0",
            ["Content"] = "……你怎么知道……",
            ["ContentJP"] = "……どうして……わかる{性别:んだ|の}……",
            ["DialogueId"] = 10109010,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Shock02",
                },
