        [10109403] = {
            ["Content"] = "是的。",
            ["ContentJP"] = "……そうだ{性别:な|よ}。",
            ["DialogueId"] = 10109403,
            ["GUID"] = "10109403.0",
            ["NextDialogue"] = 10109404,
            },
        [10109404] = {
            ["Camera"] = "19.714844,-41.03125,94.928711,0.00024,0.189367,126.75769,20.000008,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "真好啊。你看，旅客们是不是点起了灯？那些车窗是不是很漂亮，很温暖，像炉子里的小火苗一样？",
            ["ContentJP"] = "いいなぁ。乗客は明かりをつけているの？列車の窓から漏れる明かりはすごく、きれいで、暖かくて、ストーブで揺れる小さな炎みたいだよね？",
            ["DialogueId"] = 10109404,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "31.46875,-56.716797,94.905273,0.000241,-2.210632,127.157379,20.000008,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194ECDEE",
            ["LookAt"] = {
                [1] = "100001:n(200006)",
                [2] = "200006:n(100001)",
                },
            ["NextDialogue"] = 10109407,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{2.5}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain02_End\"},Duration{1}},\
PlayAnimation{ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{2}}\
}\
",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECDEE",
            },
        [10109405] = {
            ["Content"] = "只是风的声音。",
            ["ContentJP"] = "風の音だよ。",
            ["DialogueId"] = 10109405,
            ["GUID"] = "10109405",
            ["NextDialogue"] = 10109406,
            },
        [10109406] = {
            ["Camera"] = "28.210938,-52.099609,95.129883,0.000245,0.989387,124.358093,20.0,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……原来不是啊。",
            ["ContentJP"] = "……そっか。",
            ["DialogueId"] = 10109406,
            ["FacialId"] = {
                [1] = "200006:Happy02",
                },
            ["FinalCamera"] = "13.988281,-31.232422,98.763672,0.000245,0.989387,124.358093,20.0,100000.0,false,DoNotOverride,22.0",
