            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE18",
            },
        [10109407] = {
            ["Camera"] = "-281.054688,-237.414062,82.333008,0.0,-2.99999,39.999969,20.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你的眼睛……是什么时候看不清的？",
            ["ContentJP"] = "サイキは……いつから目が見えなくなったんだ？",
            ["DialogueId"] = 10109407,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
            ["FinalCamera"] = "-281.054688,-237.414062,47.505859,0.000001,4.000004,39.999969,20.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "194ECE42",
            ["NextDialogue"] = 10109408,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE42",
            },
        [10109408] = {
            ["Camera"] = "97.648438,-137.328125,117.448242,0.00021,-3.611073,122.97995,50.000008,336.90625,false,Manual,7.017789",
            ["Content"] = "什么时候……",
            ["ContentJP"] = "いつから……だったかな……",
            ["DialogueId"] = 10109408,
            ["GUID"] = "194ECE6C",
            ["NextDialogue"] = 10109409,
            ["SpeakNpcId"] = 200006,
            ["TalkActionId"] = {
                [1] = "200006:Sigh_Start",
                [2] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE6C",
            },
        [10109409] = {
            ["Camera"] = "-173.027344,119.447266,100.172852,0.000213,0.788593,-32.62458,50.000008,287.144684,false,Manual,4.056031",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "我也不知道。我以为和从前一样，模糊一阵子就会慢慢好起来。可现在……",
            ["ContentJP"] = "分かんない。てっきり今までみたいに、しばらくしたら治ると思ってたんだけど。今回は……",
            ["DialogueId"] = 10109409,
            ["FacialId"] = {
                [1] = "200006:Unhappy01",
                },
            ["FinalCamera"] = "-153.613281,107.021484,100.492188,0.000213,0.788593,-32.62458,50.000008,287.144684,false,Manual,4.056031",
            ["GUID"] = "194ECE6D",
            ["NextDialogue"] = 10109410,
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101094/194ECE6D",
            },
        [10109410] = {
            ["Camera"] = "60.910156,-67.048828,109.011719,0.000257,-3.799709,132.574326,35.0,339.966736,false,DoNotOverride,2.608581",
            ["Content"] = "不说这个了。我有一个想去的地方，你可以陪我一起吗？",
            ["ContentJP"] = "こんな話はやめておいてさ？私、行きたい場所があるの。一緒に行ってくれないかな？",
            ["DialogueId"] = 10109410,
            ["FacialId"] = {
                [1] = "200006:None",
                },
            ["GUID"] = "194ECE96",
            ["NextOptions"] = {
                [1] = 10109411,
                },
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{3.4},TargetPosition{\"-2489.960938,234.535156,332.305664,0.000228,6.999994,117.97747,20.0,339.966736,false,DoNotOverride,22\"},duration{0}},\
CameraMoveTo{_delay{3.5},TargetPosition{\"-2489.960938,234.535156,576.185547,0.000228,4.999999,117.977455,20.0,339.966736,false,DoNotOverride,22\"},duration{8}},\
SEQ{\
