        [10110210] = {
            ["Camera"] = "155.150391,89.697266,40.088867,0.000099,0.594261,-127.181572,25.0,379.426514,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "这家伙母亲去得早，打过的架不比吃过的饭少。虽然家人禁止我和卡戎来往，但我想着好歹也是一起玩到大的，所以偶尔会帮他点忙……",
            ["ContentJP"] = "母親が早くに亡くなっちまってから、こいつは三度の飯よりケンカ三昧な生活でな。家族からはカロン族なんざとつるむなって口酸っぱく言われたが、ガキの頃からの付き合いなんだ。できる範囲で助けてやっていた……",
            ["DialogueId"] = 10110210,
            ["FinalCamera"] = "155.150391,89.697266,40.088867,0.000105,18.793825,-127.379799,25.0,379.426514,false,Manual,22.0",
