            ["TalkActionId"] = {
                [1] = "200004:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F52D2",
            },
        [10110214] = {
            ["Content"] = "我是偏远村子来的，消息闭塞…… ",
            ["ContentJP"] = "辺鄙な村の出だから、そういう情報はなかなか入ってこなくて……",
            ["DialogueId"] = 10110214,
            ["GUID"] = "10110214",
