            },
        [10110216] = {
            ["Content"] = "再多问，小心我把今天的事…… ",
            ["ContentJP"] = "{性别:僕|私}のことは詮索{性别:するな|しないで}。さもなくばこのことを大声で……",
            ["DialogueId"] = 10110216,
            ["GUID"] = "10110216",
            ["ImprPlusId"] = 1010,
