            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F5476",
            },
        [10110226] = {
            ["Content"] = "送去治安署会发生什么？",
            ["ContentJP"] = "保安署に送られるとどうなる{性别:んだ|の}？",
            ["DialogueId"] = 10110226,
            ["GUID"] = "194F5477",
            ["NextDialogue"] = 10110227,
            },
        [10110227] = {
            ["Camera"] = "777.373047,-100.292969,25.057617,0.000009,4.599859,172.998215,40.000011,332.596619,false,Manual,22.0",
            ["Content"] = "都说了秽蚀者是无药可救的，还能发生什么？自然是移交给我们卫戍部队，然后……唉。",
            ["ContentJP"] = "穢蝕者は救いようがないと言ったろ？どうなるかって……俺たち警備部隊に移管されてだな……それから……はぁ。",
            ["DialogueId"] = 10110227,
            ["GUID"] = "194F54A0",
            ["NextDialogue"] = 10110228,
            ["SpeakNpcId"] = 200004,
            ["TalkActionId"] = {
                [1] = "200004:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101102/194F54A0",
            },
        [10110228] = {
            ["Camera"] = "-30.980469,-249.970703,249.849609,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
            ["Content"] = "虽然这家伙也算自作自受……但好歹也当过几年朋友，我不忍心让他躺在冰冷的殓房，就把他偷……带了出来，打算把他葬在泪湖边上，埋他母亲的地方。",
            ["ContentJP"] = "盗みを働いた自業自得だって言われりゃそれまでだが……長いこと友人だったヤツなんだ。冷たい死体安置所に寝かせておくのは心苦しくてな。だからこいつをこっそりと盗み……連れだした。ダクリ湖のほとりで、母親の近くに葬ってやりたかったんだよ。",
            ["DialogueId"] = 10110228,
            ["FinalCamera"] = "-23.003906,-235.451172,235.890625,0.000058,-40.098839,61.201523,20.000011,207.029022,false,Manual,3.5",
            ["GUID"] = "194F54CA",
