CameraMoveTo{_delay{1.6},TargetPosition{\"614.092041,-84.750488,127.766602,0.000123,-3.400054,86.35746,35.0,365.6586,false,Manual,2.5\"},duration{0}},\
CameraMoveTo{_delay{1.7},TargetPosition{\"614.092041,-84.750488,156.081787,0.000124,-6.0,86.35746,35.0,364.392914,false,Manual,3.227706\"},blend{\"easeOutQuad\"},duration{3}}\
}",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F8212",
            },
        [10110502] = {
            ["Camera"] = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
            ["Content"] = "我和内城的朋友通过气了，今夜他的马车会停在这附近。等赛琪出来，我们先送她到城外避避风头。给恩里克八个胆子，他也不敢去打劫贵族老爷的马车。",
            ["ContentJP"] = "内城区の知り合いに話を通した。今夜この近くにそいつの馬車が止まる手はずだ。サイキが来たら、まずは街の外まで連れ出して身を隠せ。いくらヘンリックが無鉄砲で強心臓だったとしても、貴族の旦那様の馬車を強奪するなんてまねはしないだろう。",
            ["DialogueId"] = 10110502,
            ["GUID"] = "194F823C",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10110503,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}},\
PlayAnimation{ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}},\
PlayAnimation{ActorId{200021},AnimationId{\"Talk02_End\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F823C",
            },
        [10110503] = {
            ["Content"] = "然后……再想办法看看接下来怎么办吧。",
            ["ContentJP"] = "今後どうするかは、救出後に考えよう。",
            ["DialogueId"] = 10110503,
            ["GUID"] = "194F8266",
            ["NextDialogue"] = 10110504,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F8266",
            },
        [10110504] = {
            ["Camera"] = "597.891357,-27.287598,177.053955,0.000212,-9.60052,80.358948,40.0,340.8461,false,Manual,5.0",
            ["Content"] = "你还挺神通广大。",
            ["ContentJP"] = "すさまじい根回しだ{性别:な|ね}。",
            ["DialogueId"] = 10110504,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "194F8290",
            ["NextDialogue"] = 10110505,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "200021:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F8290",
            },
        [10110505] = {
            ["Camera"] = "722.716003,214.500488,130.546387,0.000153,5.999351,-137.03714,30.0,171.684738,false,Manual,6.0",
            ["Content"] = "哈，总得对得起我这些年经历的**事。不过，你确定她会来？",
            ["ContentJP"] = "へへ、何年も**ッタレなことを経験してんだこっちは……しかし、あの子が本当に来るって確証はあるのか？",
            ["DialogueId"] = 10110505,
            ["FacialId"] = {
                [1] = "200021:Smile02",
                },
            ["GUID"] = "194F82BA",
            ["NextDialogue"] = 10110506,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{4}},\
PlayAnimation{ActorId{200021},AnimationId{\"Explain01_End\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F82BA",
            },
        [10110506] = {
            ["Camera"] = "636.023804,126.125488,194.547607,0.000064,-21.999287,69.385223,35.000008,165.235214,false,Manual,22.0",
            ["Content"] = "……我不知道。总之，她不来的话，就按照第二计划行事。",
            ["ContentJP"] = "……わからない。でもサイキが来なければ、2つ目の計画を実行するだけ。",
            ["DialogueId"] = 10110506,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200021:None",
                [2] = "100001:None",
                },
            ["GUID"] = "194F82E4",
            ["NextDialogue"] = 10110507,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{2}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F82E4",
            },
        [10110507] = {
            ["Camera"] = "752.663208,304.167969,134.771973,0.000159,0.799091,-134.831451,30.000008,255.753464,false,Manual,3.0",
            ["Content"] = "直接冲进修普诺斯之家，彻底揭露恩里克的罪行——哈，听起来像是流行小说里的侠盗。",
            ["ContentJP"] = "ヒュプノスの家に突入して、ヘンリックの罪を徹底的に暴きだす——へっ流行の小説に出てくる義賊かよ。",
            ["DialogueId"] = 10110507,
            ["FacialId"] = {
                [1] = "200021:Confident01",
                },
            ["GUID"] = "194F830E",
            ["NextDialogue"] = 10110508,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Angry01_Start",
                [2] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F830E",
            },
        [10110508] = {
            ["Content"] = "不过，你做好心理准备。即使我们今天救了赛琪，她也……支持不了太久了。我们在废矿里看到的那家伙，就是她最终的归宿。",
            ["ContentJP"] = "いいか、覚悟だけはしておけよ？たとえ今日サイキを助けられたとしても、長くはもたない。サイキの最後は、廃坑でみたアレのように……",
            ["DialogueId"] = 10110508,
            ["FacialId"] = {
                [1] = "200021:Doubt01",
                },
            ["GUID"] = "194F8338",
            ["NextDialogue"] = 10110509,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F8338",
            },
        [10110509] = {
            ["Camera"] = "597.891357,-27.287598,177.053955,0.000213,-9.60052,80.35907,40.0,340.8461,false,Manual,5.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "……先走一步算一步吧。",
            ["ContentJP"] = "その時は……その時になってから考えるよ。",
            ["DialogueId"] = 10110509,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Sad01",
                [2] = "200021:None",
                },
            ["FinalCamera"] = "595.481689,-41.476074,179.486816,0.000213,-9.60052,80.359016,40.0,340.8461,false,Manual,5.0",
            ["GUID"] = "194F8362",
            ["NextDialogue"] = 10110510,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{2}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F8362",
            },
        [10110510] = {
            ["Camera"] = "752.663208,304.167969,134.771973,0.000159,0.799091,-134.831451,30.000008,255.753464,false,Manual,3.0",
            ["Content"] = "……唉，说起来，就算是秽蚀者，不是一直有卫戍部队处置吗？恩里克到底经历过什么，才会做到这种地步……",
            ["ContentJP"] = "……ったく、穢蝕者の処理は警備部隊が担ってるはずだが。ヘンリックはなぜそこまでやるんだ？",
            ["DialogueId"] = 10110510,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "194F838C",
            ["NextDialogue"] = 10110511,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F838C",
            },
        [10110511] = {
            ["Camera"] = "594.983521,34.920898,147.270508,0.000067,-8.200632,79.375977,30.000008,567.112122,false,Manual,3.0",
            ["Content"] = "我大概……猜到了原因。",
            ["ContentJP"] = "だいたいの見当はついてるよ。",
            ["DialogueId"] = 10110511,
            ["ExStoryInfo"] = "Player",
            ["FinalCamera"] = "617.869507,29.944824,148.867676,0.000067,-6.800539,83.778389,30.000008,242.72731,false,Manual,3.0",
            ["GUID"] = "194F838D",
            ["NextOptions"] = {
                [1] = 10110512,
                },
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F838D",
            },
        [10110512] = {
            ["Content"] = "（说出在凯文处打听到的情报。）",
            ["ContentJP"] = "（ケビンから聞いた情報を話す）",
            ["DialogueId"] = 10110512,
            ["GUID"] = "10110512.0",
            ["NextDialogue"] = 10110513,
            },
        [10110513] = {
            ["Camera"] = "960.668701,-341.848633,606.558594,0.000024,-38.601192,121.190224,30.000002,362.012939,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……恩里克曾是一名医生，但出于某种原因关闭了医馆；恩里克有一个女儿，但她在丹流城下落不明；恩里克在丹流城谋害了一名秽蚀者……",
            ["ContentJP"] = "……ヘンリックは昔は医者だったが何らかの理由で病院を閉めた……娘がひとりいたがレッドバリー城で行方不明になった……レッドバリー城で穢蝕者を殺害した……",
            ["DialogueId"] = 10110513,
            ["FacialId"] = {
                [1] = "200021:Think01",
                },
            ["FinalCamera"] = "896.82605,-237.447266,505.624023,0.000011,-40.001194,121.590363,30.000002,362.012939,false,Manual,22.0",
            ["GUID"] = "194F83B6",
            ["NextDialogue"] = 10110514,
            ["SpeakNpcId"] = 200021,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F83B6",
            },
        [10110514] = {
            ["Camera"] = "673.087097,200.460449,158.318604,0.00003,-18.200924,80.989754,30.000013,71.430817,false,Manual,22.0",
            ["Content"] = "嗯。更重要的是，这三件事是在同一年发生的，所以它们不会没有关联。",
            ["ContentJP"] = "重要なのは3つの出来事がだいたい同じ年に起きていること。たまたま連続したなんて絶対にないと思う{性别:んだ|の}。",
            ["DialogueId"] = 10110514,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "200021:Doubt01",
                },
            ["GUID"] = "194F83E0",
            ["NextDialogue"] = 10110515,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F83E0",
            },
        [10110515] = {
            ["Camera"] = "801.704407,333.576172,133.333984,0.000171,-0.800471,-142.436356,30.000002,310.031403,false,Manual,3.5",
            ["Content"] = "……考虑到修普诺斯之家的住客很有可能都是秽蚀者……嗯，我懂你的意思了。",
            ["ContentJP"] = "ヒュプノスの家の宿泊客が全員穢蝕者だって可能性を考えれば……ああ、言いたいことはわかったぜ。",
            ["DialogueId"] = 10110515,
            ["FacialId"] = {
                [1] = "200021:Unhappy02",
                },
            ["GUID"] = "194F840A",
            ["NextDialogue"] = 10110516,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F840A",
            },
        [10110516] = {
            ["Camera"] = "684.15155,260.363281,147.201416,0.000142,-1.401261,-120.639412,30.000002,200.0,false,Manual,3.0",
            ["Content"] = "恩里克的女儿大概率在丹流城遭遇了不测，这件事很可能同秽蚀者有关，从而激起了恩里克对秽蚀者的仇恨，即使多年后仍然无法消解……",
            ["ContentJP"] = "ヘンリックの娘はレッドバリー城で、穢蝕者が関係するトラブルに巻き込まれたんだろう。それでヘンリックは穢蝕者を憎むようになった。年月が流れても憎悪は消えずに……",
            ["DialogueId"] = 10110516,
            ["GUID"] = "194F8434",
            ["NextDialogue"] = 10110517,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F8434",
            },
        [10110517] = {
            ["Content"] = "所以他不知道用了什么方式将一些秽蚀者控制起来，并动用私刑——你是这么想的吧？",
            ["ContentJP"] = "何らかの手段で穢蝕者を支配して、私刑に興じるようになったと……お前の推理はこんな感じか？",
            ["DialogueId"] = 10110517,
            ["GUID"] = "194F845E",
            ["NextDialogue"] = 10110518,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101105/194F845E",
            },
        [10110518] = {
            ["Camera"] = "649.498047,158.819336,162.394043,0.000159,-15.000577,73.956459,30.000002,106.04982,false,Manual,2.113648",
            ["Content"] = "……嗯。不过不管他出于什么理由，不管秽蚀者的最终命运是什么……我们都必须——",
            ["ContentJP"] = "うん。どんな理由があるとしても……穢蝕者の最後がどうであれ……{性别:僕|私}たちは絶対に――",
            ["DialogueId"] = 10110518,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
