        [10110603] = {
            ["Camera"] = "3.640381,-208.794922,183.625,0.000189,-20.999163,86.982307,50.000011,313.724945,false,DoNotOverride,3.0",
            ["Content"] = "我不是按你们说的一直在这里观察情况嘛……然后，真的像你们说的那样，赛琪出来了！我就上去拉住她，准备带她去找你们。",
            ["ContentJP"] = "スノウはね？言われた通りね？ちゃんとここで様子を見てたんだよ？そしたら、本当に、サイキが出てきたの！だから「{nickname}たちのところまで案内してあげる」って、声をかけたら……",
            ["DialogueId"] = 10110603,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "194F92CE",
            ["NextDialogue"] = 10110604,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{3.8}},PlayAnimation{ActorId{200002},AnimationId{\"Angry01_End\"},Duration{4.2}},PlayAnimation{ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101106/194F92CE",
            },
        [10110604] = {
            ["Camera"] = "5.263672,-60.99707,136.059082,0.000133,-20.999565,92.985939,35.000008,170.151947,false,Manual,22.0",
            ["Content"] = "可她突然扑了过来，狠狠地抓向我……还好本大人闪得快！但是……那真的是赛琪吗？那个人一点都不像平时的她，就像是……一头野兽！",
            ["ContentJP"] = "サイキが、飛びかかってきて……スノウに容赦なく襲いかかってきたの……なんとか運よく……あ、違う、魔王様は華麗に避けたのである！いや、あの……あの人って本当にサイキだった……？いつものサイキとは似ても似つかない……まるで別人……獣……獣みたいだった……！",
            ["DialogueId"] = 10110604,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["FinalCamera"] = "2.735596,-5.030273,114.464722,0.000139,-19.799591,92.585823,35.000008,170.151947,false,Manual,22.0",
