        [10110808] = {
            ["Content"] = "修普诺斯之家，收留的是……秽蚀者……命运的弃儿……",
            ["ContentJP"] = "ヒュプノスの家で引き取るのは穢蝕者……運命の捨て子だ……",
            ["DialogueId"] = 10110808,
            ["GUID"] = "194FB470",
            ["LookAt"] = {
                [1] = "200005:p(P10110802)",
                },
            ["NextDialogue"] = 10110809,
            ["RelatedWikiId"] = {
