            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101108/194FB836",
            },
        [10110832] = {
            ["Content"] = "走吧……我们必须尽快。",
            ["ContentJP"] = "行くぞ……急げ。",
            ["DialogueId"] = 10110832,
