        [10110902] = {
            ["Camera"] = "-231.873047,-73.172028,160.285156,0.000103,-6.596924,20.794041,40.000011,446.663574,false,Manual,5.5",
            ["Content"] = "请你们带上这个。",
            ["ContentJP"] = "これを持っていって。",
            ["DialogueId"] = 10110902,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_1.T_Guide_Chapter01_Flower_1'}",
            ["GUID"] = "194FC3DC",
