            },
        [10111001] = {
            ["Content"] = "呼……呼……呼……",
            ["ContentJP"] = "はぁ……はぁ……はぁ……",
            ["DialogueId"] = 10111001,
            ["Duration"] = 3,
            ["GUID"] = "194FD41A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD41A",
            },
        [10111002] = {
            ["Content"] = "啊……",
            ["ContentJP"] = "はぁっ……ああ……",
            ["DialogueId"] = 10111002,
            ["Duration"] = 1,
            ["GUID"] = "194FD444",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD444",
            },
        [10111003] = {
            ["Content"] = "对……不……",
            ["ContentJP"] = "ご……めん……",
            ["DialogueId"] = 10111003,
            ["Duration"] = 0.5,
            ["GUID"] = "194FD46E",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD46E",
            },
        [10111004] = {
            ["Content"] = "回来，危险！",
            ["ContentJP"] = "うぁぁっ——！！",
            ["DialogueId"] = 10111004,
            ["Duration"] = 0.5,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FD498",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD498",
            },
        [10111005] = {
            ["Content"] = "风太大了，我没法靠近……！",
            ["ContentJP"] = "っ！風が強すぎて……近づけない！",
            ["DialogueId"] = 10111005,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FD499",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD499",
            },
        [10111006] = {
            ["Content"] = "该死，这样下去我们都会送命的……",
            ["ContentJP"] = "くそっ、こいつはマジやべぇ！",
            ["DialogueId"] = 10111006,
            ["Duration"] = 4.5,
            ["GUID"] = "194FD500",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD500",
            },
        [10111007] = {
            ["Content"] = "她失去理智了，应战！",
            ["ContentJP"] = "サイキは理性を失ってる！",
            ["DialogueId"] = 10111007,
            ["Duration"] = 2.5,
            ["GUID"] = "194FD516",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101110/194FD516",
            },
        [10111101] = {
            ["Content"] = "赛琪，听得见我的声音吗？",
            ["ContentJP"] = "サイキ、{性别:僕|私}の声が聞こえる？",
            ["DialogueId"] = 10111101,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE482",
            ["NextDialogue"] = 10111102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE482",
            },
        [10111102] = {
            ["Content"] = "回答我……",
            ["ContentJP"] = "答えて……",
            ["DialogueId"] = 10111102,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE4AC",
            ["NextDialogue"] = 10111103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE4AC",
            },
        [10111103] = {
            ["Content"] = "你说过的，你明明还有那么多想做的事……",
            ["ContentJP"] = "言っていたじゃない{性别:か|の}……まだやりたいこと、たくさんある{性别:って|んでしょ}……？",
            ["DialogueId"] = 10111103,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE4D6",
            ["NextDialogue"] = 10111104,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE4D6",
            },
        [10111104] = {
            ["Content"] = "你会离开这里，去那些你前所未见的地方——",
            ["ContentJP"] = "ここを離れて、まだ見たことのない場所に行こうよ――",
            ["DialogueId"] = 10111104,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE500",
            ["NextDialogue"] = 10111105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE500",
            },
        [10111105] = {
            ["Content"] = "……你可以去一座小岛，在那里盖几间房子……",
            ["ContentJP"] = "小さな島で……小さな家を建てて……",
            ["DialogueId"] = 10111105,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE52A",
            ["NextDialogue"] = 10111106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE52A",
            },
        [10111106] = {
            ["Content"] = "……在房子边上种满白色的花……",
            ["ContentJP"] = "家の周りにたくさんの白い花を植えて……",
            ["DialogueId"] = 10111106,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE554",
            ["NextDialogue"] = 10111107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE554",
            },
        [10111107] = {
            ["Content"] = "……一边用大大的帽檐遮住太阳，一边和友人说起冰湖城的雪……",
            ["ContentJP"] = "太陽の下で日よけの帽子をかぶって……アイスレイク城の雪が恋しいなって、友達とおしゃべりする{性别:んだ|の}……",
            ["DialogueId"] = 10111107,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE57E",
            ["NextDialogue"] = 10111108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE57E",
            },
        [10111108] = {
            ["Content"] = "……回答我……",
            ["ContentJP"] = "ねえ……答えて{性别:くれ|}よ……",
            ["DialogueId"] = 10111108,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FE5A8",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101111/194FE5A8",
            },
        [10111201] = {
            ["Content"] = "赛琪，我来带你回家。",
            ["ContentJP"] = "サイキ、一緒に帰ろう。",
            ["DialogueId"] = 10111201,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194FF4EA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101127/1950EB02",
            },
        [10111301] = {
            ["Content"] = "这是……我家？",
            ["ContentJP"] = "ここは……私の家？",
            ["DialogueId"] = 10111301,
            ["GUID"] = "191B889A",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101113/191B889A",
            },
        [10111401] = {
            ["Content"] = "亲爱的，看，赛琪在对我们笑呢。",
            ["ContentJP"] = "あなた、見て。サイキが笑っているわ。",
            ["DialogueId"] = 10111401,
            ["GUID"] = "191B88C4",
            ["NextDialogue"] = 10111402,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B88C4",
            },
        [10111402] = {
            ["Content"] = "……不知道这孩子来到世上，究竟是幸运还是不幸。",
            ["ContentJP"] = "この子はこの世に生まれてきて……幸せなのか不幸なのか……",
            ["DialogueId"] = 10111402,
            ["GUID"] = "191B88EE",
            ["NextDialogue"] = 10111403,
            ["SpeakNpcId"] = 200038,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B88EE",
            },
        [10111403] = {
            ["Content"] = "……是的，我们并不是带着祝福降生的。",
            ["ContentJP"] = "……そうだね。私たちは祝福されて、生まれてきたわけじゃないから。",
            ["DialogueId"] = 10111403,
            ["GUID"] = "191B8918",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101114/191B8918",
            },
        [10111501] = {
            ["Content"] = "妈妈！我答应过赛琪，今天带她来家里堆积木……",
            ["ContentJP"] = "お母さん！今日うちで積み木で遊ぼうって、サイキと約束したんだけど……",
            ["DialogueId"] = 10111501,
            ["GUID"] = "191BB9D2",
            ["NextDialogue"] = 10111502,
            ["SpeakNpcId"] = 200040,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BB9D2",
            },
        [10111502] = {
            ["Content"] = "谁让你和她玩的？说过多少次，少碰那些不干不净的，你想被邪恶的魔法害死吗？",
            ["ContentJP"] = "誰があの子と遊んでいいって言ったの？お母さん何度も言ったでしょうに。あの汚い連中に近づいちゃダメって。邪悪な魔法で殺されたいの？",
            ["DialogueId"] = 10111502,
            ["GUID"] = "191BB9FC",
            ["NextDialogue"] = 10111503,
            ["SpeakNpcId"] = 200041,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BB9FC",
            },
        [10111503] = {
            ["Content"] = "哎呀，好好的积木都弄脏了，快扔掉！",
            ["ContentJP"] = "ちっ、上等な積み木だったのに穢れちゃったじゃないの！……もうそれ捨てておきなさいよ！",
            ["DialogueId"] = 10111503,
            ["GUID"] = "191BBA26",
            ["SpeakNpcId"] = 200041,
            ["VoiceName"] = "voice/$Locale$/story/1002/101115/191BBA26",
            },
        [10111601] = {
            ["Content"] = "那天，怀着委屈与不解，我花了一整晚时间洗澡，直到皮肤流出鲜血。",
            ["ContentJP"] = "あの日、とまどって、悔しくて、一晩中お風呂で血が出るまで体を洗ったんだっけ。",
            ["DialogueId"] = 10111601,
            ["GUID"] = "191BBA50",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101116/191BBA50",
            },
        [10111701] = {
            ["Content"] = "不是的长官，我的女儿一向懂事，她绝不会偷窃顾客的项链，更没有藏在花盆里！",
            ["ContentJP"] = "長官様、滅相もございません。うちの娘は本当にいい子で、人様のネックレスを盗むなんて絶対にありえません。まして植木鉢の中に隠すだなんて！",
            ["DialogueId"] = 10111701,
            ["GUID"] = "191BCA3A",
            ["NextDialogue"] = 10111702,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA3A",
            },
        [10111702] = {
            ["Content"] = "狡辩什么，卡戎崽子有几个手脚干净的？",
            ["ContentJP"] = "言い逃れはやめろ、手癖が悪くないカロンのガキがいるか？",
            ["DialogueId"] = 10111702,
            ["GUID"] = "191BCA64",
            ["NextDialogue"] = 10111703,
            ["SpeakNpcId"] = 200043,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA64",
            },
        [10111703] = {
            ["Content"] = "这样吧，不是说没偷没藏吗，那就让她自己把店里那些花一盆盆砸了，证明清白。",
            ["ContentJP"] = "こうしよう。盗んでも隠してもいないと言い張るなら、あのガキが自分で、この店の植木鉢をひとつずつ壊して、身の潔白を証明するんだ。",
            ["DialogueId"] = 10111703,
            ["GUID"] = "191BCA8E",
            ["NextDialogue"] = 10111704,
            ["SpeakNpcId"] = 200044,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BCA8E",
            },
        [10111704] = {
            ["Content"] = "……因为，我们生而是“恶魔的孩子”。",
            ["ContentJP"] = "……そう、私たちは生まれながらにして「悪魔の子」だから。こんな扱いを受けるの。",
            ["DialogueId"] = 10111704,
            ["GUID"] = "191BDAA2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101117/191BDAA2",
            },
        [10111801] = {
            ["Content"] = "啊啊……为什么……",
            ["ContentJP"] = "ああ……どうして……",
            ["DialogueId"] = 10111801,
            ["GUID"] = "191BDACC",
            ["NextDialogue"] = 10111802,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDACC",
            },
        [10111802] = {
            ["Content"] = "她那么善良，我们一家也本本分分，没做过任何坏事……为什么这种事会落在我们头上？",
            ["ContentJP"] = "本当に優しい子なのに。私たち真面目に暮らしていたのに。悪いことなんてなにひとつしていないのに………どうしてこんな目にあわないといけないの？",
            ["DialogueId"] = 10111802,
            ["GUID"] = "191BDAF6",
            ["NextDialogue"] = 10111803,
            ["SpeakNpcId"] = 200039,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDAF6",
            },
        [10111803] = {
            ["Content"] = "……事到如今，只能去请求恩里克·埃塞尔莱德医生了。这是我们最后能为她做的。",
            ["ContentJP"] = "……ヘンリック・エセルレッド先生にお願いするしかないだろう。それがこの子のために、私たちができる最後のことだ。",
            ["DialogueId"] = 10111803,
            ["GUID"] = "191BDB20",
            ["NextDialogue"] = 10111804,
            ["SpeakNpcId"] = 200038,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDB20",
            },
        [10111804] = {
            ["Content"] = "爸爸，妈妈，对不起……",
            ["ContentJP"] = "お父さん、お母さん、ごめんね……",
            ["DialogueId"] = 10111804,
            ["GUID"] = "191BDB4A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101118/191BDB4A",
            },
        [10111901] = {
            ["Content"] = "……没有任何意义。",
            ["ContentJP"] = "……こんなのに、何の意味があるっていうのよ。",
            ["DialogueId"] = 10111901,
            ["GUID"] = "191BEB0A",
            ["NextDialogue"] = 10111902,
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB0A",
            },
        [10111902] = {
            ["Content"] = "你每天送这种东西给我，又能改变什么呢。",
            ["ContentJP"] = "毎日こんなのもらったって、何かが変わるわけないでしょ。",
            ["DialogueId"] = 10111902,
            ["GUID"] = "191BEB34",
            ["NextDialogue"] = 10111903,
            ["SpeakNpcId"] = 200045,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB34",
            },
        [10111903] = {
            ["Content"] = "赛琪。你应该知道，来到“修普诺斯之家”意味着什么。",
            ["ContentJP"] = "サイキ。お前も知っているだろう。「ヒュプノスの家」に来るということが、何を意味しているか。",
            ["DialogueId"] = 10111903,
            ["GUID"] = "191BEB5E",
            ["NextDialogue"] = 10111904,
            ["SpeakNpcId"] = 200046,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB5E",
            },
        [10111904] = {
            ["Content"] = "嗯，我都明白。",
            ["ContentJP"] = "うん、全部わかっているの。",
            ["DialogueId"] = 10111904,
            ["GUID"] = "191BEB88",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10111905,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEB88",
            },
        [10111905] = {
            ["Content"] = "……但我们是为了什么“意义”才活着吗？",
            ["ContentJP"] = "……でも私たちって何か「意味」がないと生きてちゃいけないのかな？",
            ["DialogueId"] = 10111905,
            ["GUID"] = "191BEBB2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101119/191BEBB2",
            },
        [10112001] = {
            ["Content"] = "……赛琪……",
            ["ContentJP"] = "……サイ……キ……",
            ["DialogueId"] = 10112001,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B9902",
            ["NextDialogue"] = 10112002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9902",
            },
        [10112002] = {
            ["Content"] = "……能听见我的声音吗……",
            ["ContentJP"] = "……{性别:僕|私}の声が……聞こえる？",
            ["DialogueId"] = 10112002,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B992C",
            ["NextDialogue"] = 10112003,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B992C",
            },
        [10112003] = {
            ["Content"] = "……回答我……",
            ["ContentJP"] = "{性别:なあ|ねえ}……答えて{性别:|よ}……",
            ["DialogueId"] = 10112003,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "191B9956",
            ["NextDialogue"] = 10112004,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9956",
            },
        [10112004] = {
            ["Content"] = "有什么人在呼唤我吗……",
            ["ContentJP"] = "誰かが私を呼んでいるのかな……？",
            ["DialogueId"] = 10112004,
            ["GUID"] = "191B9980",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10112005,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B9980",
            },
        [10112005] = {
            ["Content"] = "是在告诉我，不要就这样睡着吗……",
            ["ContentJP"] = "眠らないでって……言っているの……？",
            ["DialogueId"] = 10112005,
            ["GUID"] = "191B99AA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101120/191B99AA",
            },
        [10112100] = {
            ["Content"] = "赛琪……醒醒……",
            ["ContentJP"] = "サイキ……目を覚まして……",
            ["DialogueId"] = 10112100,
            ["GUID"] = "19508891",
            ["VoiceName"] = "voice/$Locale$/story/1002/101121/19508891",
            },
        [10112101] = {
            ["Camera"] = "-1315.217285,639.65625,36.358154,-0.0,-14.999996,-34.000755,14.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你已经看到了自己的一生。怀抱诅咒的来，毫无意义的去。",
            ["ContentJP"] = "あんたはもう自分の人生のすべてを見たよ。呪われた生、意味のない死。",
            ["DialogueId"] = 10112101,
            ["FacialId"] = {
                [1] = "200052:Smile01",
                [2] = "200006:Shock01",
                },
            ["FinalCamera"] = "-1353.548462,665.503906,107.660645,-0.0,-8.800411,-34.000824,12.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "19508892",
            ["LookAt"] = {
                [1] = "200052:n(200006)",
                [2] = "200006:n(200052)",
                },
            ["NextDialogue"] = 10112102,
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}},\
CameraMoveTo{_delay{6.1},TargetPosition{\"-544.991699,42.441406,167.733154,0.00007,-27.399405,-23.990501,20.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}\
}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["TalkActionId"] = {
                [1] = "200052:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101121/19508892",
            },
        [10112102] = {
            ["Camera"] = "-1207.813599,500.523438,177.099365,0.000065,-6.399019,-1.789612,35.0,229.405197,false,Manual,6.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "毫无意义——你永远以虚伪的笑脸逢迎他人，你那么无私吗？不，你只是卑怯地乞求他们垂怜你，记住你——记住你还是个人时的模样！",
            ["ContentJP"] = "何もかも無意味なの――いつも嘘の笑顔を浮かべて、他人の顔色ばかり伺ってさ。健気で優しい子？いや違うね、あんたは卑屈に哀れみを求めているだけ。忘れないでほしいって……まだ人らしい姿をしてる自分を覚えていてほしいって！",
            ["DialogueId"] = 10112102,
            ["FinalCamera"] = "-1212.987305,506.90625,177.723389,0.000065,-6.399019,-3.700013,35.0,229.405197,false,Manual,6.0",
            ["GUID"] = "195088BC",
            ["NextDialogue"] = 10112103,
            ["Scripts"] = "SEQ{\
SetLocation{ActorId{200052},TargetPoint{\"101121Point9\"},Visibility{\"Show\"}},\
PlayAnimation{ActorId{200052},AnimationId{\"Explain01_End\"},Duration{2}},\
LookAt{LookAtDescription{\"200006:n(200006)\"}},\
PlayAnimation{ActorId{200052},AnimationId{\"Explain02_Start\"},Duration{4.5}},\
PlayAnimation{ActorId{200052},AnimationId{\"Explain02_End\"},Duration{3.5}}\
}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101121/195088BC",
            },
        [10112103] = {
            ["Camera"] = "-1059.955688,483.929688,169.242188,0.000069,-5.50003,148.198685,35.0,83.151031,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "毫无意义——他们的怜悯和记忆如此短暂，很快便会因时间侵蚀而枯萎、衰朽。你会在泥土中腐坏，而后被彻彻底底地遗忘。",
            ["ContentJP"] = "何もかも無意味なの――哀れみなんてほんの一瞬。時間が記憶を侵食して、あっという間に枯れ果てちゃうの。あんたは土の中で腐って、誰の記憶にも残らないの。",
            ["DialogueId"] = 10112103,
            ["FacialId"] = {
                [1] = "200006:Sad01",
                },
            ["FinalCamera"] = "-1072.286011,464.078125,169.407227,0.000071,-5.099966,147.198303,35.000008,517.215454,false,Manual,4.0",
            ["GUID"] = "195088E6",
            ["NextDialogue"] = 10112104,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{200052},TargetPoint{\"101121Point8\"},Visibility{\"Show\"}},\
LookAt{_delay{2},LookAtDescription{\"200006:n(200006)\"}},\
LookAt{_delay{0},LookAtDescription{\"200052:n(200052)\"}},\
PlayAnimation{_delay{2.0},ActorId{200006},AnimationId{\"Sigh_Start\"},Duration{1}},\
SetLocation{_delay{2.2},ActorId{200052},TargetPoint{\"101121Point10\"},Visibility{\"Show\"}},\
SetRotation{_delay{2.3},SetRotationDescription{\"200052:p(-90)\"}},\
PlayAnimation{_delay{2.3},ActorId{200052},AnimationId{\"Talk03_Start\"},Duration{1}},\
LookAt{_delay{2.3},LookAtDescription{\"200052:n(200052)\"}}\
}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101121/195088E6",
            },
        [10112104] = {
            ["Camera"] = "-749.858276,899.738281,124.033691,0.00006,3.599072,-132.19986,80.0,607.756409,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你在想什么？你在愤怒什么？——我知道了，你渴望战胜我，杀掉我。你以为只要我不在了，你的生活就能回到正轨，回到那些平静的时日……",
            ["ContentJP"] = "何を考えているの？何を怒っているの？――ああ、私を殺したいのね。私がいなくなれば、元の穏やかな生活に戻れると思ってる……",
            ["DialogueId"] = 10112104,
            ["FinalCamera"] = "-829.983887,811.878906,132.056641,0.000061,3.999062,-132.799957,80.0,450.437531,false,Manual,4.0",
            ["GUID"] = "195088E7",
            ["NextDialogue"] = 10112105,
            ["Scripts"] = "PARA{\
SetLocation{_delay{0.3},ActorId{200052},TargetPoint{\"101121Point11\"},Visibility{\"Show\"}},\
SetRotation{SetRotationDescription{\"200052:p(90)\"}},\
PlayAnimation{_delay{2},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{1}}\
}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 200052,
            ["TalkActionId"] = {
                [1] = "200052:Talk01_Start",
                [2] = "200006:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101121/195088E7",
            },
        [10112105] = {
            ["Camera"] = "-804.349976,160.710938,171.24585,0.000067,-3.400027,138.804932,40.0,569.174194,false,Manual,7.455382",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你错了。秽蚀不可逆转，<W>如果我死去，你也会一并消失！</>",
            ["ContentJP"] = "でもね、そんな甘い考えは通用しないの。穢蝕者は元には戻れない。<W>私が死ねば、あんたも死ぬのよ！</>",
            ["DialogueId"] = 10112105,
            ["FacialId"] = {
                [1] = "200006:Sad01",
