            ["VoiceName"] = "voice/$Locale$/story/1002/101128/1950FD38",
            },
        [10112815] = {
            ["Camera"] = "-103.455078,522.871094,134.970703,0.000312,-23.004848,-26.640802,25.000006,4089.927734,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "因为它们的种子，会乘着轻柔的风，去向远方……翻越城墙、高山……没有什么能阻挡它们。",
            ["ContentJP"] = "お花の種は……優しい風に乗って遠くまで行けるから……城壁や山も越えて……邪魔するものは……何もないの……",
            ["DialogueId"] = 10112815,
            ["FacialId"] = {
                [1] = "200058:None",
                },
            ["FinalCamera"] = "-1856.353516,1398.453125,977.069336,0.000313,-23.604845,-25.838488,25.000006,4089.927734,false,Manual,22.0",
            ["GUID"] = "1950FD62",
            ["SpeakNpcId"] = 200058,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/101128/1950FD62",
            },
        [10112901] = {
            ["Content"] = "最后，我有个愿望——",
            ["ContentJP"] = "……最後にお願いがあるの――",
            ["DialogueId"] = 10112901,
            ["Duration"] = 3,
            ["GUID"] = "1950FD63",
            ["SpeakNpcId"] = 200058,
            },
        [10112902] = {
            ["Content"] = "我在听。",
            ["ContentJP"] = "うん……",
            ["DialogueId"] = 10112902,
            ["Duration"] = 0.8,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1950FD64",
            ["SpeakNpcId"] = 100001,
            },
        [10112903] = {
            ["Content"] = "目标未击中，当前距离无法确认目标和人质状态。",
