            ["DialogueId"] = 10112903,
            ["Duration"] = 1,
            ["GUID"] = "1950FD65",
            ["SpeakNpcId"] = 700065,
            },
        [10112904] = {
            ["Content"] = "……准备正面迎敌！",
            ["ContentJP"] = "……敵に備えなさい！",
            ["DialogueId"] = 10112904,
            ["Duration"] = 1,
            ["GUID"] = "1950FD66",
            },
        [10113001] = {
            ["Camera"] = "-90.074219,755.777344,469.635742,0.000111,-25.499575,-93.596069,25.0,467.444916,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInQuad",
