        [10113002] = {
            ["Camera"] = "82.416016,128.960938,14.348633,-3.000001,-0.400782,-132.985641,30.000002,214.526855,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你好，我是第六军团下属，科赛托斯行省卫戍部队准尉，黎瑟·费西尔。",
            ["ContentJP"] = "お初にお目にかかります。本官は第六軍団所属、コキュートス領警備部隊准尉、リズム・フィッシャーです。",
