        [10113003] = {
            ["Camera"] = "-345.591797,-227.671875,150.0,0.000125,-11.999351,20.399422,18.0,718.595093,false,Manual,3.0",
            ["Content"] = "我接到紧急情报，外围北区出现“秽蚀”事件。秽蚀者异常凶险，我们不确定它是真的被击毙了，还是短暂休眠。你们即刻撤离此地，接下来由我们应付。",
            ["ContentJP"] = "外周東区にて、「穢蝕」事件が発生したとの緊急情報を受けました。穢蝕者は非常に危険です。現状では完全に射殺できたのか、一時的な休眠状態に入ったのか未確定です。皆様はすみやかに退避を、以降は当方にて対処します。",
            ["DialogueId"] = 10113003,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["FinalCamera"] = "-348.543945,-229.019531,150.953125,0.000126,-16.799225,24.99777,18.0,718.595093,false,Manual,3.0",
            ["GUID"] = "19511C8E",
