        [10113007] = {
            ["Camera"] = "-201.873047,-180.394531,124.880859,0.00054,2.802508,-144.973618,25.0,115.146286,false,Manual,22.0",
            ["Content"] = "的确没有生命体征了。难怪这次的目标比大多数秽兽都要稳定。",
            ["ContentJP"] = "たしかに生命徴候は認められません。今回の標的はほかの個体よりおとなしい様子でしたが、どうりで……",
            ["DialogueId"] = 10113007,
