        [10113010] = {
            ["Camera"] = "-197.794922,-170.070312,134.780273,0.000507,0.002964,-142.999863,35.000008,124.303391,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不对！长官，我看到了！虽然离得很远，但我先前探路的时候看到了，这几个卡戎……他们也会使用<W>魔法</>……",
            ["ContentJP"] = "違いますぜ！上官殿、俺は見ましたよ！遠くからですが、さきほど偵察した時に確かに見ました……このカロンたち……こいつらも<W>魔法</>を使います……",
            ["DialogueId"] = 10113010,
            ["FinalCamera"] = "-197.794922,-170.070312,134.780273,0.000507,-0.597013,-133.199646,35.000008,395.571716,false,Manual,4.0",
