        [10113015] = {
            ["Camera"] = "-339.033203,-227.824219,136.402344,0.000588,-7.200924,7.438437,25.0,501.611572,false,Manual,4.0",
            ["Content"] = "感谢几位对军团的鼎力协助。请随我们前往治安署，我们将给予几位应有的报偿。",
            ["ContentJP"] = "皆様のご協力に感謝申し上げます。保安署までご同行ください。しかるべき報酬を用意しますので。",
            ["DialogueId"] = 10113015,
