        [10113020] = {
            ["Camera"] = "-68.743164,-169.890625,196.316406,0.000058,-47.599606,80.197784,25.000002,235.984589,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……在最后一刻，她还在竭尽全力地……试图为人们做些什么……",
            ["ContentJP"] = "……最後の瞬間まで……命懸けで頑張って……みんなのためにできることを……",
