        [10113108] = {
            ["Camera"] = "166.950943,133.818985,133.208984,-1.5,-19.999264,-177.415726,30.0,246.856323,false,Manual,3.0",
            ["Content"] = "不过，还有另外一件重要的事。",
            ["ContentJP"] = "ところで、もう一つ重要なことがある。",
            ["DialogueId"] = 10113108,
            ["FacialId"] = {
                [1] = "200021:None",
                },
            ["GUID"] = "19512D9F",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["NextDialogue"] = 10113109,
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
