        [10113115] = {
            ["Camera"] = "-163.218521,132.791336,42.427734,-5.000002,15.199219,2.797176,35.000008,419.357452,false,Manual,3.5",
            ["Content"] = "好了，{性别：难过就哭一场吧，兄弟。|想哭的话就哭一场吧，不用硬撑着。}",
            ["ContentJP"] = "まあ、{性别:辛いときは泣いてもいいんだぞ。|泣きたい時は好きなだけ泣けばいいさ。意地を張るこたねぇよ}。",
            ["DialogueId"] = 10113115,
            ["ExStoryInfo"] = "Player",
