            ["Duration"] = 3.5,
            ["GUID"] = "19514D72",
            ["NextDialogue"] = 10113302,
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514D72",
            },
        [10113302] = {
            ["Content"] = "这一次，我终于可以听清。",
            ["ContentJP"] = "今度こそ、やっと聞き取ることができた。",
            ["DialogueId"] = 10113302,
            ["Duration"] = 3.5,
            ["GUID"] = "19514D9C",
            ["NextDialogue"] = 10113303,
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514D9C",
            },
        [10113303] = {
            ["Content"] = "像树木的根须汲取着每一滴水，我竭尽全力试图记住那个名字。",
            ["ContentJP"] = "木の根が乾いた土の水を一滴残らず吸い上げるように、全力で名前を頭に刻み込む。",
            ["DialogueId"] = 10113303,
            ["Duration"] = 4,
            ["GUID"] = "19514DC6",
            ["NextDialogue"] = 10113304,
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514DC6",
            },
        [10113304] = {
            ["Content"] = "……那个名字……",
            ["ContentJP"] = "……その名前は……",
            ["DialogueId"] = 10113304,
            ["Duration"] = 3,
            ["GUID"] = "19514DF0",
            ["VoiceName"] = "voice/$Locale$/story/1002/101133/19514DF0",
            },
