                },
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1002/101135/19516F14",
            },
        [10113503] = {
            ["Camera"] = "135.984375,-44.101318,130.969727,0.000225,3.999998,147.005432,35.0,200.0,false,Manual,5.0",
            ["Content"] = "想办法保护它，别让秽兽把它拆了。",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>に壊されないよう、守ってやれ。",
            ["DialogueId"] = 10113503,
            ["GUID"] = "19516F3E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["LookAt"] = {
