            ["TurnTo"] = {
                [1] = "200021:p(45)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101135/19516F92",
            },
        [10113701] = {
            ["Content"] = "呃，碎掉了。",
            ["ContentJP"] = "あーあ、壊れちゃった。",
            ["DialogueId"] = 10113701,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19518F12",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10113702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101137/19518F12",
            },
        [10113702] = {
            ["Content"] = "废品改装的嘛，能用已经很不错了！。",
            ["ContentJP"] = "廃品を組み立てた代物だからな。少し使えるだけで十分さ。",
            ["DialogueId"] = 10113702,
            ["Duration"] = 2.5,
            ["GUID"] = "19518F3C",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101137/19518F3C",
            },
        [10113801] = {
            ["Content"] = "任务完成",
            ["ContentJP"] = "クエスト達成",
            ["DialogueId"] = 10113801,
            ["Duration"] = 3.5,
            ["GUID"] = "19519F7A",
            ["VoiceName"] = "voice/$Locale$/story/1002/101138/19519F7A",
            },
        [10113901] = {
            ["Content"] = "本次技术性测试剧情流程已结束。",
            ["DialogueId"] = 10113901,
            ["Duration"] = 5,
            ["GUID"] = "1951AFE2",
            ["VoiceName"] = "voice/$Locale$/story/1002/101139/1951AFE2",
            },
        [10114001] = {
            ["Content"] = "这么快就回来了？不是去跟踪恩里克了吗？",
            ["ContentJP"] = "何しに戻ってきたんだ？ヘンリックを尾行するって段取りだったろ？",
            ["DialogueId"] = 10114001,
            ["GUID"] = "1951C04A",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101140/1951C04A",
            },
        [10114201] = {
            ["Content"] = "你们要早点休息哦。",
            ["ContentJP"] = "ふたりとも早く休んでね。",
            ["DialogueId"] = 10114201,
            ["GUID"] = "1951E11A",
            ["SpeakNpcId"] = 200020,
            ["VoiceName"] = "voice/$Locale$/story/1002/101142/1951E11A",
            },
        [10114301] = {
            ["Content"] = "如果恩里克叔叔同意的话，你可以再来找我玩吗？",
            ["ContentJP"] = "ヘンリックおじさんが許してくれるなら、また遊びに来てくれるかな？",
            ["DialogueId"] = 10114301,
            ["GUID"] = "1951F182",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101143/1951F182",
            },
        [10114401] = {
            ["Content"] = "放老实点，别管与你无关的事。",
            ["ContentJP"] = "余計なことに首を突っ込むな。おとなしくしておけ。",
            ["DialogueId"] = 10114401,
            ["GUID"] = "195201EA",
            ["SpeakNpcId"] = 200005,
            ["VoiceName"] = "voice/$Locale$/story/1002/101144/195201EA",
            },
        [10114501] = {
            ["Camera"] = "-36.346924,180.007812,144.75769,0.000186,-6.600435,-88.992912,25.0,418.354095,false,Manual,3.0",
