        [10117302] = {
            ["Camera"] = "-192.958298,199.304382,104.51123,0.000078,1.000431,-68.603432,43.300995,474.195221,false,Manual,2.6",
            ["Content"] = "哦哟，这不是咱们的垃圾桶小公主吗？今天带着{性别:小弟小妹|两个小妹}一起捡啊？",
            ["ContentJP"] = "おっ、ゴミ拾いの姫様じゃねぇか。今日は{性别:弟分と妹分|妹分ふたり}を引き連れてゴミ拾いかい。",
            ["DialogueId"] = 10117302,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1953DDB2",
            ["LookAt"] = {
                [1] = "200054:n(200011)",
                },
            ["NextDialogue"] = 10117303,
            ["Scripts"] = "PARA{\
LookAt{_delay{3},LookAtDescription{\"200054:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 200054,
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DDB2",
            },
        [10117303] = {
            ["Camera"] = "99.868393,-250.259125,175.274902,0.000025,-25.999838,135.993896,35.0,246.462189,false,Manual,2.6",
            ["Content"] = "我不是小妹！是魔王！",
            ["ContentJP"] = "だ～れが妹分だってー！スノウは魔王様なんだぞ！",
            ["DialogueId"] = 10117303,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "1953DDDC",
            ["LookAt"] = {
                [1] = "200011:n(200002)",
                [2] = "200054:n(200002)",
                },
            ["NextDialogue"] = 10117304,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                [2] = "200011:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DDDC",
            },
        [10117304] = {
            ["Camera"] = "-84.425522,47.435509,57.425781,0.000151,11.599348,-73.994087,35.000008,278.919617,false,Manual,3.0",
            ["Content"] = "哦……那就是垃圾桶小魔王？",
            ["ContentJP"] = "おお……するってぇとゴミ拾いの魔王ちゃん…かい？",
            ["DialogueId"] = 10117304,
            ["GUID"] = "1953DE06",
            ["LookAt"] = {
                [1] = "200011:n(200002)",
                },
            ["NextDialogue"] = 10117305,
            ["SpeakNpcId"] = 200054,
            ["TalkActionId"] = {
                [1] = "200011:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE06",
            },
        [10117305] = {
            ["Camera"] = "206.001495,-142.157104,81.942383,0.000148,2.199983,176.390671,35.000008,303.843719,false,DoNotOverride,1.715777",
            ["Content"] = "不是啦，是“光之魔王”！",
            ["ContentJP"] = "ちっがーう！「光の魔王様」！",
            ["DialogueId"] = 10117305,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "1953DE30",
            ["LookAt"] = {
                [1] = "100001:n(200011)",
                [2] = "200011:n(100001)",
                },
            ["NextDialogue"] = 10117306,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                [2] = "200011:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE30",
            },
        [10117306] = {
            ["Camera"] = "114.257248,-212.611359,148.254395,0.000174,-12.397339,160.570602,24.0,208.790619,false,Manual,2.5",
            ["Content"] = "啊哈哈哈……先别管这个了，爷爷啊，您看没看到一个黑头发、蓝衣服的卡戎男人从这里跑过去？",
            ["ContentJP"] = "あはは……そんなあだ名の話は置いといてさ。ねえ、じいちゃん、黒い髪で青い服のカロンの男を見かけなかったかな？",
            ["DialogueId"] = 10117306,
            ["FacialId"] = {
                [1] = "200011:Ahaha02",
                },
            ["GUID"] = "1953DE5A",
            ["LookAt"] = {
                [1] = "200054:n(200011)",
                [2] = "100001:n(200054)",
                },
            ["NextDialogue"] = 10117307,
            ["Scripts"] = "SEQ{\
LookAt{_delay{1},LookAtDescription{\"200011:n(200054)\"}},\
PlayAnimation{_delay{1},ActorId{200011},AnimationId{\"Explain01_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                [2] = "200011:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE5A",
            },
        [10117307] = {
            ["Content"] = "刚刚确实有个小伙子跑过去了。年轻人冒冒失失的，走路也不看路，直冲着<H>雾区</>堆垃圾那块儿去了！呀，他该不会是——要抢你生意？",
            ["ContentJP"] = "たしかにさっきそんな若ぇもんが走ってったな。なんか危なっかしい足取りで、<H>霧の街</>のゴミ箱の方に向かったぞ。するってぇと何かい……あの男がマギーの商売を横取りしようってのかい？",
            ["DialogueId"] = 10117307,
            ["GUID"] = "1953DE84",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10117307.T_Story_Recall_10117307'",
            ["NextDialogue"] = 10117308,
            ["SpeakNpcId"] = 200054,
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DE84",
            },
        [10117308] = {
            ["Content"] = "呃……算是吧！谢啦，我这就追他去。",
            ["ContentJP"] = "うん、まあそんなところ。ありがとね。よっし追っかけよう。",
            ["DialogueId"] = 10117308,
            ["FacialId"] = {
                [1] = "200011:Happy01",
                },
            ["GUID"] = "1953DEAE",
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{ActorId{200011},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101173/1953DEAE",
            },
        [10117401] = {
            ["Content"] = "雾区堆放垃圾的地方……",
            ["ContentJP"] = "霧の街のゴミ箱……",
            ["DialogueId"] = 10117401,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1953EE1A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117402,
            ["SpeakNpcId"] = 100001,
            },
        [10117402] = {
            ["Content"] = "他说的是3号大垃圾箱！跟我来！",
            ["ContentJP"] = "大型ゴミ箱3号のことだね。私についてきて！",
            ["DialogueId"] = 10117402,
            ["Duration"] = 3,
            ["GUID"] = "1953EE44",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101174/1953EE44",
            },
        [10117501] = {
            ["Content"] = "去吧去吧……老话怎么说的来着？“早起的鸟儿有垃圾捡！”",
            ["ContentJP"] = "俺の情報が役に立つといいけどな。なんとかも積もれば……そう、ゴミも積もれば山となるって言うしよ。",
            ["DialogueId"] = 10117501,
            ["GUID"] = "1953FE82",
            ["SpeakNpcId"] = 200054,
            ["VoiceName"] = "voice/$Locale$/story/1002/101175/1953FE82",
            },
        [10117601] = {
            ["Content"] = "这一带没有人。",
            ["ContentJP"] = "誰もいないみたいだけど。",
            ["DialogueId"] = 10117601,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "19540EEA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101176/19540EEA",
            },
        [10117602] = {
            ["Content"] = "……没关系！灵敏的“侦探”嗅觉告诉我，这附近一定能找到线索！",
            ["ContentJP"] = "……へーきへーき。「探偵」の鋭い嗅覚が教えてくれてるもん。近くに手がかりがあるって！",
            ["DialogueId"] = 10117602,
            ["Duration"] = 3,
            ["GUID"] = "19540F14",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101176/19540F14",
            },
        [10117701] = {
            ["Camera"] = "-410.567871,424.552368,74.604492,0.000115,4.799778,-44.802727,25.000002,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "涂鸦墙边的箱子叠了两层……底层箱子被斜过来了，表面还有凌乱的成年男性脚印——哼哼，被我看穿了！",
            ["ContentJP"] = "落書きの壁、その下には2段に積まれた木箱……一番下の箱は斜めに傾き、成人男性の足跡がついてる――ふむふむ……丸っと了解！",
            ["DialogueId"] = 10117701,
            ["FinalCamera"] = "-410.567871,424.552368,74.604492,0.000105,8.599781,-41.002731,25.000002,100000.0,false,Disable,2.8",
            ["GUID"] = "19541F52",
            ["NextDialogue"] = 10117702,
            ["Scripts"] = "PlayAnimation{_delay{1.5},ActorId{200011},AnimationId{\"Think_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 3.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541F52",
            },
        [10117702] = {
            ["Content"] = "咳，根据证人玛尔洁的证词，今天早上她来3号大垃圾箱“进货”的时候，才刚把这边的箱子横着摆好。",
            ["ContentJP"] = "うぉっほん！証人マギーの証言によると、今朝大型ゴミ箱3号で「商品を仕入れた」時、箱を横一列に並べた。",
            ["DialogueId"] = 10117702,
            ["GUID"] = "19541F7C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10117702.T_Story_Recall_10117702'",
            ["NextDialogue"] = 10117703,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541F7C",
            },
        [10117703] = {
            ["Camera"] = "83.220734,36.439808,97.523438,0.000132,10.199651,-171.604935,35.0,144.288223,false,Manual,2.5",
            ["Content"] = "所以，“缄默侦探”玛尔洁的推理显而易见——小贼情急之下把这些箱子叠了起来，踩着它们爬上了墙！他很可能藏在天台上！",
            ["ContentJP"] = "よって、「物言わぬ探偵」マギーの推理は――慌てふためいたコソ泥は箱を積み上げ、それを足がかりにして壁を登ったのであ～る！ヤツは屋上に潜んでいるに違いないぞ！",
            ["DialogueId"] = 10117703,
            ["FinalCamera"] = "48.795158,31.354404,106.438965,0.000132,10.199651,-171.604935,35.0,107.665878,false,Manual,2.5",
            ["GUID"] = "19541FA6",
            ["NextDialogue"] = 10117704,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{ActorId{200011},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayFacial{_delay{6},ActorId{200011},FacialId{\"Happy01\"}}\
}",
            ["SpeakNpcId"] = 200011,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541FA6",
            },
        [10117704] = {
            ["Camera"] = "-2114.584229,613.182617,98.33252,0.000144,1.892338,-19.423639,35.000008,732.249939,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哦！有道理耶！我们也爬上去看看吧。",
            ["ContentJP"] = "おお～なるほど！じゃあ私たちも登ってみよう。",
            ["DialogueId"] = 10117704,
            ["FinalCamera"] = "-2097.467041,661.715881,98.33252,0.000144,1.892338,-19.423639,35.000008,732.249939,false,DoNotOverride,1.2",
            ["GUID"] = "19541FD0",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200011:Talk03_End",
                [2] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101177/19541FD0",
            },
        [10117801] = {
            ["Content"] = "原来“缄默侦探”就是玛尔洁的称号啊，还挺威风的……只可惜有点短，气势上输了一截！",
            ["ContentJP"] = "「物言わぬ探偵」ってマギーのあだ名なんだね。かっこいいけど、ちょっと短くて迫力が足りないかも。",
            ["DialogueId"] = 10117801,
            ["Duration"] = 3,
            ["GUID"] = "19542FBA",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19542FBA",
            },
        [10117802] = {
            ["Content"] = "有道理！那魔王小妹你有什么主意吗？",
            ["ContentJP"] = "んーそう言われてみればたしかに。魔王ちゃん、なにかいいアイディアあるかな？",
            ["DialogueId"] = 10117802,
            ["Duration"] = 3,
            ["GUID"] = "19542FE4",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117803,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19542FE4",
            },
        [10117803] = {
            ["Content"] = "刚才那个老爷爷说的“垃圾桶公主”就挺不错的？",
            ["ContentJP"] = "さっきのおじいちゃんが言ってた「ゴミ拾いの姫様」がいい感じだったから……",
            ["DialogueId"] = 10117803,
            ["Duration"] = 3,
            ["GUID"] = "1954300E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117804,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/1954300E",
            },
        [10117804] = {
            ["Content"] = "“缄默侦探☆垃圾桶公主”，气势是不是突然就上去啦！",
            ["ContentJP"] = "「物言わぬ探偵☆ゴミ拾いのプリンセス」！ってどうどう？めっちゃかっこよくなったでしょ！",
            ["DialogueId"] = 10117804,
            ["Duration"] = 3,
            ["GUID"] = "19543038",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10117805,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19543038",
            },
        [10117805] = {
            ["Content"] = "啊——！不要不要，不要再提那几个字了，丢死人了！",
            ["ContentJP"] = "ノォーー！やめてーー。私は姫様なんかじゃないし！もお恥ずかしいったらありゃしないよ！",
            ["DialogueId"] = 10117805,
            ["Duration"] = 3,
            ["GUID"] = "19543062",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101178/19543062",
            },
        [10117901] = {
            ["Camera"] = "441.521088,-620.674683,187.3125,0.000037,-5.799861,111.19696,25.0,850.802856,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "怎么了，垃圾桶里有什么吗？",
            ["ContentJP"] = "どしたの？ゴミ箱に何かある？",
            ["DialogueId"] = 10117901,
            ["FinalCamera"] = "441.521088,-620.674683,164.277588,0.000037,-5.799861,111.19696,25.0,850.802856,false,Manual,1.2",
            ["GUID"] = "19544022",
            ["NextDialogue"] = 10117902,
            ["SpeakNpcId"] = 200011,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/19544022",
            },
        [10117902] = {
            ["Camera"] = "25.164871,87.383209,131.531006,0.000057,-2.19986,-60.40377,25.0,225.91423,false,Manual,1.6",
            ["Content"] = "我只是想确认一下他有没有藏在——",
            ["ContentJP"] = "泥棒がここに隠れてないかなって、ちょっと確認を――",
            ["DialogueId"] = 10117902,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1954404C",
            ["LookAt"] = {
                [1] = "200011:n(100001)",
                [2] = "100001:n(200011)",
                },
            ["NextDialogue"] = 10117903,
            ["Scripts"] = "SetLocation{ActorId{200002},TargetPoint{\"P101179Bai1\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/1954404C",
            },
        [10117903] = {
            ["Camera"] = "14.791107,54.489399,135.432129,0.000058,-2.399801,-63.204136,35.0,189.973221,false,Manual,4.0",
            ["Content"] = "啊——！那是……半瓶葡萄酒和一枚古董胸针？！天哪，难道你就是被垃圾桶之神眷顾的天选之人？！",
            ["ContentJP"] = "おおお！こ、これは……飲み残しのワインボトル、おまけにアンティークのブローチ！君ってゴミ箱の神様に選ばれし者だったの？！",
            ["DialogueId"] = 10117903,
            ["FacialId"] = {
                [1] = "200011:Shock01",
                },
            ["GUID"] = "19544076",
            ["LookAt"] = {
                [1] = "200011:n(200011)",
                },
            ["NextDialogue"] = 10117904,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/19544076",
            },
        [10117904] = {
            ["Camera"] = "282.696777,274.406219,171.463379,0.000081,-11.800018,-126.601822,20.0,385.634796,false,Manual,1.2",
            ["Content"] = "可恶，偏偏在这个节骨眼上……你等我一下！",
            ["ContentJP"] = "もう～こんな急いでるときに……ちょっと待っててね！",
            ["DialogueId"] = 10117904,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                [2] = "200002:Shock01",
                },
            ["GUID"] = "195440A0",
            ["LookAt"] = {
                [1] = "200002:n(200011)",
                },
            ["NextDialogue"] = 10117905,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{200011},TargetPoint{\"P101179Maer2\"},Visibility{\"Show\"}},\
MoveTo{_delay{4},ActorId{200011},TargetPoint{\"P101179Maer1\"},MoveSpeed{50},Visibility{\"Show\"}},\
CameraMoveTo{_delay{4},TargetPosition{\"277.728668,278.098145,171.463379,0.000081,-11.800018,-126.601822,20.0,385.634796,false,Manual,1.2\"},duration{3}},\
SetLocation{ActorId{200002},TargetPoint{\"P101179Bai1\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/195440A0",
            },
        [10117905] = {
            ["Content"] = "（玛尔洁从废品堆里扯出两张旧报纸，把刚找到的宝贝小心翼翼地包了起来，放在角落里。）",
            ["ContentJP"] = "（マギーはゴミの山から古新聞を2枚引っ張り出し、見つけ出した「宝物」を大切に包むと、道のすみに置いた）",
            ["DialogueId"] = 10117905,
            ["DisableMouth"] = 1,
            ["Duration"] = 4,
            ["GUID"] = "195440CA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 10117906,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{200002},TargetPoint{\"P101179Bai2\"},Visibility{\"Show\"}},\
PlayNormalSound{_delay{2},EventPath{\"event:/sfx/common/story/01/searchtrash\"},PlayAs2D{true}}\
}",
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/195440CA",
            },
        [10117906] = {
            ["Camera"] = "-97.681335,235.033142,214.595215,0.000114,-15.999267,-53.001629,35.0,124.611694,false,DoNotOverride,2.2",
            ["Content"] = "好嘞，这样就没问题了！等我抓完小贼再回来收货。见者有份，等小贼的事儿搞定，葡萄酒也分你一半！",
            ["ContentJP"] = "よし、これでオッケー！コソ泥を捕まえたら戻ってきて回収しよう。発見者には分け前をあげなきゃだね。この依頼が片付いたら、ワインを半分分けてあげる。",
            ["DialogueId"] = 10117906,
            ["FacialId"] = {
                [1] = "200011:Smile02",
                },
            ["GUID"] = "195440F4",
            ["LookAt"] = {
                [1] = "100001:n(200011)",
                [2] = "200002:n(200011)",
                },
            ["NextDialogue"] = 10117907,
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:SpecialHoldHelmet_Start",
                [2] = "200002:SpecialHappy_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/195440F4",
            },
        [10117907] = {
            ["Content"] = "呃……这个就不用了！",
            ["ContentJP"] = "えっと……{性别:僕|私}のことは気にしないでいいから。",
            ["DialogueId"] = 10117907,
            ["ExStoryInfo"] = "Player",
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "1954411E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101179/1954411E",
            },
        [10118001] = {
            ["Content"] = "才刚有个人爬上来，怎么又来三个？",
            ["ContentJP"] = "あらあら、さっきも誰かが1人で登ってきたけど。今度は3人一緒に登ってきたのね。",
            ["DialogueId"] = 10118001,
            ["Duration"] = 3,
            ["GUID"] = "1954508A",
            ["SpeakNpcId"] = 200055,
            ["VoiceName"] = "voice/$Locale$/story/1002/101180/1954508A",
            },
        [10118101] = {
            ["Content"] = "最近这是怎么了，总有人在城里飞檐走壁。冰湖城是有什么运动赛吗？爬得快有奖那种？",
            ["ContentJP"] = "最近なんだかあちこちで跳んだりはねたりしてる人を見かけるけど。アイスレイク城で何か競技大会でもやってるの？速く登ると賞品がもらえるとか？",
            ["DialogueId"] = 10118101,
            ["GUID"] = "195460F2",
            ["NextDialogue"] = 10118102,
            ["SpeakNpcId"] = 200055,
            ["VoiceName"] = "voice/$Locale$/story/1002/101181/195460F2",
            },
        [10118102] = {
            ["Content"] = "呃……这么说来，好像确实有个皎皎前辈设过类似的挑战？",
            ["ContentJP"] = "あー、そういえば。ルーナ族の先輩がそういう競技を開催したって聞いたことあるかも。",
            ["DialogueId"] = 10118102,
            ["GUID"] = "1954611C",
            ["NextDialogue"] = 10118103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101181/1954611C",
            },
        [10118103] = {
            ["Content"] = "那你们快追吧！刚才那位选手都跑过去半天啦。",
            ["ContentJP"] = "あらあら、だったら急いで追いかけないと。さっきの選手はもうずっと先に進んじゃったわよ。",
            ["DialogueId"] = 10118103,
            ["GUID"] = "19546146",
            ["SpeakNpcId"] = 200055,
            ["VoiceName"] = "voice/$Locale$/story/1002/101181/19546146",
            },
        [10118201] = {
            ["Content"] = "啊，快看，就是前面屋顶上那家伙！",
            ["ContentJP"] = "あ、見て見て、あそこ。屋根の上にいるヤツ！",
            ["DialogueId"] = 10118201,
            ["Duration"] = 3,
            ["GUID"] = "1954715A",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/1954715A",
            },
        [10118202] = {
            ["Camera"] = "-476.057983,-45.540398,533.046387,0.000058,-4.400117,156.809341,35.000008,241.278336,false,Manual,4.2",
            ["Content"] = "你、你……至于追到这种地方来吗？你说你那钱本来就是拿来分给别人的，那分老子一点怎么了？",
            ["ContentJP"] = "お前……普通こんなとこまで追いかけてくるか？あのカネは元々スラムの連中に分けてやるつもりだったんだろ。だったら俺が少しくらい分け前もらったってバチはあたらねぇさ。",
            ["DialogueId"] = 10118202,
            ["GUID"] = "19547184",
            ["LookAt"] = {
                [1] = "200002:n(200053)",
                [2] = "200053:n(100001)",
                [3] = "100001:n(200053)",
                [4] = "200011:n(200053)",
                },
            ["NextDialogue"] = 10118203,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{100001},TargetPoint{\"P101182Nvzhu1\"},MoveSpeed{220},Visibility{\"Show\"}},\
MoveTo{ActorId{200011},TargetPoint{\"P101182Maer1\"},MoveSpeed{240},Visibility{\"Show\"}},\
MoveTo{ActorId{200002},TargetPoint{\"P101182Bai1\"},MoveSpeed{210},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 200053,
            ["SpeakNpcName"] = "UI_Npc_Name_Man_12",
            ["TalkActionId"] = {
                [1] = "200053:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/19547184",
            },
        [10118203] = {
            ["Camera"] = "-845.377014,-25.232204,629.145264,0.000027,-33.600269,4.611965,28.874323,1077.120361,false,Manual,4.2",
            ["Content"] = "你有困难我可以帮你，但直接上手抢，那就吃我一铲！",
            ["ContentJP"] = "君が本当に困ってるなら助けてあげるけどさ。勝手に持っていっちゃう子にはお仕置きだよ！",
            ["DialogueId"] = 10118203,
            ["FacialId"] = {
                [1] = "200011:Angry01",
                },
            ["GUID"] = "195471AE",
            ["SpeakNpcId"] = 200011,
            ["TalkActionId"] = {
                [1] = "200011:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/195471AE",
            },
        [10118204] = {
            ["Content"] = "（青年似乎找不到反驳的话，气急败坏地跳下了墙。）",
            ["ContentJP"] = "（青年は言い返す言葉がみつからないようだ。苛ついた様子で屋根から飛び降りた）",
            ["DialogueId"] = 10118204,
            ["DisableMouth"] = 1,
            ["GUID"] = "195471D8",
            ["VoiceName"] = "voice/$Locale$/story/1002/101182/195471D8",
            },
        [10118301] = {
            ["Content"] = "又、又不见了？他是幽灵吗？",
            ["ContentJP"] = "またまた見失っちゃった？あいつはゴーストか？！",
            ["DialogueId"] = 10118301,
            ["Duration"] = 3,
            ["GUID"] = "195481C2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/195481C2",
            },
        [10118302] = {
            ["Content"] = "不……你们看，这面井盖有被挪动过的痕迹。",
            ["ContentJP"] = "ううん……ほら見て。このマンホール、動かした跡がある。",
            ["DialogueId"] = 10118302,
            ["Duration"] = 3,
            ["GUID"] = "195481EC",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118303,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/195481EC",
            },
        [10118303] = {
            ["Content"] = "以我的推测，他一定钻进了下水道！",
            ["ContentJP"] = "よって私の推理は……あいつは下水道に逃げ込んだんだ！",
            ["DialogueId"] = 10118303,
            ["Duration"] = 3,
            ["GUID"] = "19548216",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101183/19548216",
            },
        [10118401] = {
            ["Content"] = "这么深的水……根本就过不去吧！他怎么做到的？",
            ["ContentJP"] = "うわ……水が深すぎて渡れないよ。あいつはどうやって渡ったのかな？",
            ["DialogueId"] = 10118401,
            ["Duration"] = 3,
            ["GUID"] = "1954922A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101184/1954922A",
            },
        [10118402] = {
            ["Content"] = "别急，这种时候就该动用本“缄默侦探”的情报网了！",
            ["ContentJP"] = "慌てない慌てない。こういう時は「物言わぬ探偵」の情報網の出番だよ。",
            ["DialogueId"] = 10118402,
            ["Duration"] = 3,
            ["GUID"] = "19549254",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118403,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101184/19549254",
            },
        [10118403] = {
            ["Content"] = "根据8号小桶产出的《下水道维修手册》，这里的水位是可以人为控制的！机关一定就在附近。",
            ["ContentJP"] = "小型ゴミ箱8号で見つけた『下水道メンテナンスマニュアル』に書いてあったんだけど、ここの水位は調節できるんだって。水門がたしかこの辺にあったはず。",
            ["DialogueId"] = 10118403,
            ["Duration"] = 3,
            ["GUID"] = "1954927E",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101184/1954927E",
            },
        [10118501] = {
            ["Content"] = "哇——真的有排水机关。垃圾桶公主☆缄默侦探，你好有本领！",
            ["ContentJP"] = "わお！本当に排水の仕掛けがあったよ。ゴミ拾いの姫様☆物言わぬ探偵、やるじゃん！",
            ["DialogueId"] = 10118501,
            ["Duration"] = 3,
            ["GUID"] = "1954A292",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101185/1954A292",
            },
        [10118502] = {
            ["Content"] = "去掉前面那半，拜托了……呜呜。",
            ["ContentJP"] = "ぷえ……お願いだから、前半のあだ名は省略して……",
            ["DialogueId"] = 10118502,
            ["Duration"] = 3,
            ["GUID"] = "1954A2BC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118503,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101185/1954A2BC",
            },
        [10118503] = {
            ["Content"] = "水位下降了一部分，找找还有没有类似的开关吧。",
            ["ContentJP"] = "水位が少し下がったね。他にも似たような仕掛けがないか探してみよう。",
            ["DialogueId"] = 10118503,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "1954A2E6",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101185/1954A2E6",
            },
        [10118601] = {
            ["Content"] = "快看，下边真有路哎！",
            ["ContentJP"] = "見て、下の方に道があるよ！",
            ["DialogueId"] = 10118601,
            ["Duration"] = 3,
            ["GUID"] = "1954B2FA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B2FA",
            },
        [10118602] = {
            ["Content"] = "对了，《下水道维修手册》里写过，下水道偶尔会招来一些喜欢温暖湿润的秽兽栖身。",
            ["ContentJP"] = "あっそうだ。これも『下水道メンテナンスマニュアル』に書いてあったんだけど、下水道にはあったくて湿った環境を好む穢獣が住みつくことがあるって。",
            ["DialogueId"] = 10118602,
            ["Duration"] = 3,
            ["GUID"] = "1954B324",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B324",
            },
        [10118603] = {
            ["Content"] = "虽然这些秽兽是体格最弱小的那种，快跟猫猫狗狗差不多了，但如果成群结队行动，还是会有点危险……",
            ["ContentJP"] = "犬とか猫くらいの大きさしかない小型の<Default note=\"text:エジュウ\">穢獣</>だけど、群れで行動するとちょっと厄介なんだって。",
            ["DialogueId"] = 10118603,
            ["Duration"] = 3,
            ["GUID"] = "1954B34E",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118604,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B34E",
            },
        [10118604] = {
            ["Content"] = "我们准备好再前进吧！",
            ["ContentJP"] = "この先に進むならしっかり準備を整えないとね！",
            ["DialogueId"] = 10118604,
            ["Duration"] = 3,
            ["GUID"] = "1954B378",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101186/1954B378",
            },
        [10118701] = {
            ["Content"] = "乖乖站住！不许跑！",
            ["ContentJP"] = "そこの君！いい子だから止まりやがれーー！",
            ["DialogueId"] = 10118701,
            ["Duration"] = 3,
            ["GUID"] = "1954C362",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118702,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101187/1954C362",
            },
        [10118702] = {
            ["Content"] = "呼……呼……你们几个腿长的……等等我……",
            ["ContentJP"] = "はあ……はあ……足の長いみなさーん……ちょっと待って……",
            ["DialogueId"] = 10118702,
            ["Duration"] = 3,
            ["GUID"] = "1954C38C",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101187/1954C38C",
            },
        [10118801] = {
            ["Content"] = "咳、咳……呛死我了……好卑鄙……",
            ["ContentJP"] = "ゴホゴホ……く、苦しい……卑怯者めーｰ",
            ["DialogueId"] = 10118801,
            ["Duration"] = 3,
            ["GUID"] = "1954D3CA",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101188/1954D3CA",
            },
        [10118901] = {
            ["Content"] = "听到脚步声了，这边这边！",
