        [10120401] = {
            ["Content"] = "那边是泪湖诶，我们不是说好要进城吗？",
            ["ContentJP"] = "あっちはダクリ湖だよ。街へ行くんじゃなかったの？",
            ["DialogueId"] = 10120401,
            ["GUID"] = "1955DA4A",
            ["NextDialogue"] = 10120402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101204/1955DA4A",
            },
        [10120402] = {
            ["Content"] = "一个人乱转很危险的！快回来，白在这儿等你！",
            ["ContentJP"] = "勝手に歩き回ったら危ないよ！おーい、戻ってこーい！",
            ["DialogueId"] = 10120402,
            ["GUID"] = "1955DA74",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101204/1955DA74",
            },
        [10120501] = {
            ["Content"] = "你要去哪儿呀，我们不是说好要进城吗？",
            ["ContentJP"] = "ちょっと、そっちは違うよ。街へ行くんじゃなかったの？",
            ["DialogueId"] = 10120501,
            ["GUID"] = "1955EAB2",
            ["NextDialogue"] = 10120502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101205/1955EAB2",
            },
        [10120502] = {
            ["Content"] = "那边有好多好多秽兽，你会被吃掉的！快到白这边来！",
            ["ContentJP"] = "あっちに行ったら、<Default note=\"text:エジュウ\">穢獣</>に食べられちゃうぞ！ほら、戻っておいで！",
            ["DialogueId"] = 10120502,
            ["GUID"] = "1955EADC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101205/1955EADC",
            },
        [10120601] = {
            ["Content"] = "（这就是“城市”吗，还是第一次见到……）",
            ["ContentJP"] = "（これが、「街」？初めて見た……）",
            ["DialogueId"] = 10120601,
            ["DisableMouth"] = 1,
            ["GUID"] = "1955FB1A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101206/1955FB1A",
            },
        [10120602] = {
            ["Content"] = "（可接下来去哪儿，完全没有头绪……还是先找到白和那位卡米拉女士吧。）",
            ["ContentJP"] = "（どこへ行けばいいんだろう……やっぱりスノウとカミラさんの所へ戻ろう……）",
            ["DialogueId"] = 10120602,
            ["DisableMouth"] = 1,
            ["GUID"] = "1955FB44",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101206/1955FB44",
            },
        [10120701] = {
            ["Content"] = "呜哇哇，过不去了！怎么回事，连下水道也在和我们作对……",
            ["ContentJP"] = "わわ！これじゃあ通れない。下水道までスノウたちの邪魔をするつもり！？",
            ["DialogueId"] = 10120701,
            ["GUID"] = "19560B82",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120702,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101207/19560B82",
            },
        [10120702] = {
            ["Content"] = "让“缄默侦探”看看——这里有个水阀！他一定对水阀做了手脚！",
            ["ContentJP"] = "「物言わぬ探偵」に見せてごらん……ここにバルブが！きっとあいつがバルブに小細工をしたんだよ！",
            ["DialogueId"] = 10120702,
            ["GUID"] = "19560BAC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120703,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101207/19560BAC",
            },
        [10120703] = {
            ["Content"] = "也就是说，这里的水位是<H>水阀</>控制的……",
            ["ContentJP"] = "つまり、<H>バルブ</>で水位を調整してるんだね……",
            ["DialogueId"] = 10120703,
            ["GUID"] = "19560BD6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101207/19560BD6",
            },
        [10120801] = {
            ["Content"] = "前面还有个水阀！",
            ["ContentJP"] = "この先にもバルブがあるよ！",
            ["DialogueId"] = 10120801,
            ["GUID"] = "19561BEA",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101208/19561BEA",
            },
        [10120901] = {
            ["Content"] = "那个坏蛋刚刚就是钻到这个洞里去了，我们也跟上！",
            ["ContentJP"] = "あの悪党はこの穴の中に入ってたんだよ。スノウたちも行こう！",
            ["DialogueId"] = 10120901,
            ["GUID"] = "19562C52",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10120902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101209/19562C52",
            },
        [10120902] = {
            ["Content"] = "对了，8号小桶产出的《下水道维修手册》里写过，下水道偶尔会招来一些喜欢温暖潮湿的秽兽。",
            ["ContentJP"] = "そうだ、小型ゴミ箱8号で見つけた『下水道メンテナンスマニュアル』によれば、下水道にはジメジメした所が好きな<Default note=\"text:エジュウ\">穢獣</>が多いとか。",
            ["DialogueId"] = 10120902,
            ["GUID"] = "19562C7C",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10118603,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101209/19562C7C",
            },
