        [10124504] = {
            ["Camera"] = "-170.298828,286.62207,6.517578,0.000065,-0.600066,81.802094,30.000002,715.44751,false,Manual,2.5",
            ["Content"] = "我们一起到湖边走走，好吗？",
            ["ContentJP"] = "一緒に湖の周りを散歩しない？",
            ["DialogueId"] = 10124504,
            ["FinalCamera"] = "-167.683594,286.25,6.517578,0.000065,-0.600066,81.802094,30.000002,715.44751,false,Manual,2.5",
            ["GUID"] = "19587B70",
            ["SpeakNpcId"] = 200006,
            ["ToFinalCameraBlendTime"] = 3,
            ["TurnTo"] = {
                [1] = "100001:n(200006)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101245/19587B70",
            },
        [10124601] = {
            ["Content"] = "这边的积雪有些厚，小心。",
            ["ContentJP"] = "ここ、雪が積もってるから気を付けて。",
            ["DialogueId"] = 10124601,
            ["GUID"] = "19588B5A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10124602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588B5A",
            },
        [10124602] = {
            ["Content"] = "嗯……那你走在前，我在后面。",
            ["ContentJP"] = "分かった……それじゃ、あなたが前を歩いて。",
            ["DialogueId"] = 10124602,
            ["GUID"] = "19588B84",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10124603,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588B84",
            },
        [10124603] = {
            ["Content"] = "如果踩在你的脚印上就不会摔倒啦。",
            ["ContentJP"] = "あなたの足跡に沿って歩けば、転ぶ心配はないでしょ。",
            ["DialogueId"] = 10124603,
            ["GUID"] = "19588BAE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101246/19588BAE",
            },
