        [10124703] = {
            ["Camera"] = "3394.880859,-590.107422,3505.388672,0.000188,-4.999999,115.388802,10.0,615.599121,false,Manual,22",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不对……书上说大海的水是咸咸的，那么连着大海的河一定也是咸咸的吧？",
            ["ContentJP"] = "あ、でも、海の水はしょっぱいって本に書いてあったから。海と繋がってるなら同じくしょっぱいはずだよね？",
            ["DialogueId"] = 10124703,
            ["FacialId"] = {
