        [10125201] = {
            ["Content"] = "（那边那个人好像有点眼熟……是谁来着？）",
            ["ContentJP"] = "（あの人、何だか見覚えがあるような……誰だっけ？）",
            ["DialogueId"] = 10125201,
            ["DisableMouth"] = 1,
            ["GUID"] = "1958EDCA",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101252/1958EDCA",
            },
        [10125301] = {
            ["Content"] = "我真要开枪了！我是说真的！！",
            ["ContentJP"] = "本当に撃つぞ！これは脅しじゃないからな！",
            ["DialogueId"] = 10125301,
            ["GUID"] = "1958FE32",
            ["VoiceName"] = "voice/$Locale$/story/1002/101253/1958FE32",
            },
        [10125401] = {
            ["Content"] = "哇啊快跑，这块冰要碎了！",
            ["ContentJP"] = "わああ！走れっ！氷が割れるぞ！",
            ["DialogueId"] = 10125401,
            ["GUID"] = "19590E9A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101254/19590E9A",
            },
        [10125501] = {
            ["Content"] = "冰面易碎，或许我们应该先躲到更稳固的台子上。",
            ["ContentJP"] = "氷が割れやすくなってる。ひとまず頑丈な台の上に避難した方がいいかもな。",
            ["DialogueId"] = 10125501,
            ["GUID"] = "19591F02",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101255/19591F02",
            },
        [10125601] = {
            ["Content"] = "（这应该是最后一段路了吧……）",
            ["ContentJP"] = "（ここを過ぎれば……）",
            ["DialogueId"] = 10125601,
            ["DisableMouth"] = 1,
            ["GUID"] = "19592F6A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10125602,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101256/19592F6A",
            },
        [10125602] = {
            ["Content"] = "（赛琪，等我……我来带你回家。）",
            ["ContentJP"] = "（サイキ、待ってて……一緒に帰ろう）",
            ["DialogueId"] = 10125602,
            ["DisableMouth"] = 1,
            ["GUID"] = "19592F94",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101256/19592F94",
            },
        [10125701] = {
            ["Content"] = "{nickname}，你去了哪儿？",
            ["ContentJP"] = "{nickname}？どこにいるの？",
            ["DialogueId"] = 10125701,
            ["GUID"] = "19593FD2",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101257/19593FD2",
            },
        [10125702] = {
            ["Content"] = "你已经走远了吗？我在这儿等你……",
            ["ContentJP"] = "どこに行っちゃったの？私はここだよ……",
            ["DialogueId"] = 10125702,
            ["GUID"] = "19593FFC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101257/19593FFC",
            },
        [10125801] = {
            ["Content"] = "回去睡会儿吧。知道你肯定睡不着，但歇一会儿也是好的。",
            ["ContentJP"] = "ほれ、そろそろ帰って休め。もっとも、寝れねぇだろうがな。",
            ["DialogueId"] = 10125801,
            ["GUID"] = "1959503A",
            ["NextDialogue"] = 10125802,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101258/1959503A",
            },
        [10125802] = {
            ["Content"] = "不用了，我想一个人走走。",
            ["ContentJP"] = "いや、少し風にあたってくる。",
            ["DialogueId"] = 10125802,
            ["GUID"] = "19595064",
            ["NextDialogue"] = 10125803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101258/19595064",
            },
        [10125803] = {
            ["Content"] = "……好，冰湖城的夜很长，你多小心。",
            ["ContentJP"] = "……そうか。アイスレイク城の夜は長い。気を付けろよ。",
            ["DialogueId"] = 10125803,
            ["GUID"] = "1959508E",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/1002/101258/1959508E",
            },
        [10125901] = {
            ["Camera"] = "454.923828,1684.220703,-255.024414,8.000015,2.99999,-111.999702,35.0,320.217255,false,Manual,4.0",
            ["Content"] = "愿你的灵魂于雾海深处获得安宁……",
            ["ContentJP"] = "あなたの魂がニヴルヘイムの深淵で安らかに眠れますように…",
            ["DialogueId"] = 10125901,
            ["GUID"] = "195960A2",
            ["LookAt"] = {
                [1] = "200076:n(200076)",
                [2] = "100001:n(200076)",
                },
            ["NextOptions"] = {
