        [10125902] = {
            ["Camera"] = "143.350586,113.806641,100.092773,-15.001924,4.999999,-149.999969,35.0,181.272781,false,Manual,3.0",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "你来了，孩子……请稍等，待我完成最后的仪式。",
            ["ContentJP"] = "来ましたね、{性别:坊や|お嬢さん}…少し待っていて、最後の儀式を終わらせますから。",
            ["DialogueId"] = 10125902,
