            },
        [10125903] = {
            ["Camera"] = "381.145508,5108.46875,-188.0625,0.000089,13.799932,-105.801727,15.0,4893.01709,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……愿你于母神的怀抱中重获新生。",
            ["ContentJP"] = "…母なる神の腕の中で、新たな命を授かりますように。",
            ["DialogueId"] = 10125903,
            ["FinalCamera"] = "350.378906,5114.902344,-177.369141,0.00009,13.799932,-101.801758,15.0,4893.01709,false,DoNotOverride,1.2",
            ["GUID"] = "195960F6",
            ["NextDialogue"] = 10125904,
            ["SpeakNpcId"] = 200076,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/195960F6",
            },
        [10125904] = {
            ["Camera"] = "52.793945,123.166016,112.274414,0.000068,18.633036,-113.494453,60.0,171.088638,false,Manual,2.75",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "你好，孩子。我是一名漂泊的雾海引渡人——或者，如果你更喜欢以姓名相称，也可以称呼我为妮弗尔夫人。",
            ["ContentJP"] = "こんにちは、{性别:坊や|お嬢さん}。私は漂泊するニブルヘイムの導き手——名前で呼びたいなら、ニフル夫人と呼んでください。",
            ["DialogueId"] = 10125904,
            ["FinalCamera"] = "64.296875,149.507812,102.587891,0.000073,18.832949,-113.293243,60.0,171.088638,false,Manual,2.75",
            ["GUID"] = "19596120",
            ["NextDialogue"] = 10125905,
