            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/1959621C",
            },
        [10125911] = {
            ["Camera"] = "95.520508,198.755859,124.03125,5.001531,-13.799672,57.99501,20.000008,46.651825,false,Manual,4.0",
            ["Content"] = "……她是我的朋友。",
            ["ContentJP"] = "……彼女は……友人だった。",
            ["DialogueId"] = 10125911,
            ["FacialId"] = {
                [1] = "100001:Sad01",
                },
