SetLocation{ActorId{200076},TargetPoint{\"P_101259Nifu2\"},Visibility{\"Hide\"}}\
}",
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
