            },
        [10125930] = {
            ["Camera"] = "677.972656,898.259766,768.71582,0.000071,-39.198925,-126.606758,18.0,56.213341,false,Manual,22.0",
            ["Content"] = "一路顺风，亲爱的孩子。",
            ["ContentJP"] = "大切な{性别:坊や|お嬢さん}、良い旅を。",
            ["DialogueId"] = 10125930,
            ["FinalCamera"] = "765.867188,1016.578125,888.923828,0.000071,-39.198925,-126.606758,18.0,56.213341,false,Manual,22.0",
            ["GUID"] = "19596564",
            ["SpeakNpcId"] = 200076,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/19596564",
            },
        [10125931] = {
            ["Content"] = "（雾海……逝去的灵魂……）",
            ["ContentJP"] = "（ニブルヘイム……亡き者の魂……）",
            ["DialogueId"] = 10125931,
            ["DisableMouth"] = 1,
            ["GUID"] = "19596565",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 10125932,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/19596565",
            },
        [10125932] = {
            ["Content"] = "（世界的真相……构筑它的法则……）",
            ["ContentJP"] = "（世界の本当の姿と……その掟……）",
            ["DialogueId"] = 10125932,
            ["DisableMouth"] = 1,
            ["GUID"] = "19596566",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101259/19596566",
            },
        [10126001] = {
            ["Camera"] = "21.271936,1262.868164,169.894531,0.000235,-0.800724,-92.056824,30.0,1303.695801,false,DoNotOverride,1.2",
            ["DialogueId"] = 10126001,
            ["GUID"] = "1959710A",
            },
        [10127001] = {
            ["Camera"] = "-261.964844,-143.53418,117.835449,0.000286,-8.398476,29.395039,18.0,411.462158,false,DoNotOverride,2.0",
            ["Content"] = "怀抱着襁褓的小小摇篮，如今已经落满尘埃。",
            ["ContentJP"] = "かつて幼子を包んでいた小さなゆりかごも、今やすっかり埃に覆われてしまっている。",
            ["DialogueId"] = 10127001,
            ["GUID"] = "195A151A",
            ["VoiceName"] = "voice/$Locale$/story/1002/101270/195A151A",
            },
        [10127002] = {
            ["Camera"] = "-175.474609,0.638672,49.867432,0.0,0.0,0.0,15.0,142.471756,false,DoNotOverride,2.0",
            ["Content"] = "散碎一地的积木块，似乎被什么人粗暴地推倒了。",
            ["ContentJP"] = "何者かが乱暴に倒したのか、床一面に積み木が散らばっている。",
            ["DialogueId"] = 10127002,
            ["GUID"] = "195A1544",
            ["VoiceName"] = "voice/$Locale$/story/1002/101270/195A1544",
            },
        [10127003] = {
            ["Camera"] = "-92.993164,-100.354492,108.179443,0.000091,-34.999081,38.198757,20.0,138.826813,false,DoNotOverride,2.0",
            ["Content"] = "一张笔录，潦草地记下了你的“罪行”。",
            ["ContentJP"] = "乱雑な文字で、あなたの「罪」が記されている。",
            ["DialogueId"] = 10127003,
            ["GUID"] = "195A156E",
            ["VoiceName"] = "voice/$Locale$/story/1002/101270/195A156E",
            },
        [10127004] = {
            ["Content"] = "两痕泪静静地流淌在她苍老的双眼之下。",
            ["ContentJP"] = "老いた彼女の瞳から、二筋の涙が静かに流れた。",
            ["DialogueId"] = 10127004,
            ["GUID"] = "195A1598",
            ["VoiceName"] = "voice/$Locale$/story/1002/101270/195A1598",
            },
        [10127005] = {
            ["Camera"] = "101.757812,-139.77832,28.292236,0.000069,0.600367,129.191574,12.5,133.732285,false,DoNotOverride,2.0",
            ["Content"] = "还带着朝露的白花被打翻在地，花瓣凌乱不堪。",
            ["ContentJP"] = "朝露に濡れた白い花が床に倒れ、花弁が無残に散っている。",
            ["DialogueId"] = 10127005,
            ["GUID"] = "195A15C2",
            ["VoiceName"] = "voice/$Locale$/story/1002/101270/195A15C2",
            },
        [10127006] = {
            ["Content"] = "拂去灰尘",
            ["ContentJP"] = "ほこりを払う",
            ["DialogueId"] = 10127006,
            ["GUID"] = "195A15EC",
            },
        [10127007] = {
            ["Content"] = "堆起来",
            ["ContentJP"] = "積み上げる",
            ["DialogueId"] = 10127007,
            ["GUID"] = "195A1616",
            },
        [10127008] = {
            ["Content"] = "用笔划掉",
            ["ContentJP"] = "線を引いて消す",
            ["DialogueId"] = 10127008,
            ["GUID"] = "195A1640",
            },
        [10127009] = {
            ["Content"] = "帮她擦掉眼泪",
            ["ContentJP"] = "彼女の涙をそっと拭う",
            ["DialogueId"] = 10127009,
            ["GUID"] = "195A166A",
            },
        [10127010] = {
            ["Content"] = "修复花朵",
            ["ContentJP"] = "花を修復する",
            ["DialogueId"] = 10127010,
            ["GUID"] = "195A1694",
            },
        [10127011] = {
            ["Content"] = "就在这里歇息吧",
            ["ContentJP"] = "ここで少し休憩しよう",
            ["DialogueId"] = 10127011,
            ["GUID"] = "195A16BE",
            },
        [10128001] = {
            ["Camera"] = "2092.79834,-850.263184,574.188477,0.000034,-19.801502,119.803421,10.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["DialogueId"] = 10128001,
            ["FinalCamera"] = "2149.577148,-817.741333,574.188477,0.000037,-19.801476,122.803436,10.0,100000.0,false,Disable,2.8",
            ["GUID"] = "195AB92A",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101280/195AB92A",
            },
        [10128002] = {
            ["Camera"] = "964.108154,1014.200562,-209.061523,0.000064,-5.201202,-74.993759,15.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["DialogueId"] = 10128002,
            ["FinalCamera"] = "876.738525,985.802246,-209.061523,0.000063,-5.201202,-71.993752,15.0,100000.0,false,Disable,2.8",
            ["GUID"] = "195AB954",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1002/101280/195AB954",
            },
        [10128101] = {
            ["Content"] = "放我们进城吧，我们只是想进城卖点柴火，买点面包啊……",
            ["ContentJP"] = "どうか中に入れてくれませんか……城で薪を売って、パンを買いたいだけなんです……",
            ["DialogueId"] = 10128101,
            ["GUID"] = "195AC992",
            ["NextDialogue"] = 10128102,
            ["SpeakNpcId"] = 200089,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195AC992",
            },
        [10128102] = {
            ["Content"] = "之前进城也没听过过要什么通行证啊，行行好，长官，家里的吃的快见底了。",
            ["ContentJP"] = "以前は通行証などいらなかったのに……どうかお願いします。家の食料も既に底をついていて……",
            ["DialogueId"] = 10128102,
            ["GUID"] = "195AC9BC",
            ["NextDialogue"] = 10128103,
            ["SpeakNpcId"] = 200089,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195AC9BC",
            },
        [10128103] = {
            ["Content"] = "抱怨什么啊，你以为我想查什么通行证？还不是你们这些卡戎之民总是聚众闹事。",
            ["ContentJP"] = "こっちだって面倒な作業が増えてうんざりしてんだ。そもそもといえば、お前らカロンが騒ぎを起こさなければ、こんなことにはなってなかったんだぞ！",
            ["DialogueId"] = 10128103,
            ["GUID"] = "195AC9E6",
            ["NextDialogue"] = 10128104,
            ["SpeakNpcId"] = 200071,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195AC9E6",
            },
        [10128104] = {
            ["Content"] = "你也知道那个神弃者同盟吧，啊，专门和帝国对着干，通行证就是为了筛查这帮人的。你啊，要怪就怪你的那些不安分的同族们。",
            ["ContentJP"] = "お前も知ってるだろ、フォーセイクン同盟のこと。帝国と対立してる連中だ。取り締まりが厳しくなったのもそいつらのせいなんだ。責めるなら、お前の同胞たちを責めるんだな。",
            ["DialogueId"] = 10128104,
            ["GUID"] = "195ACA10",
            ["NextDialogue"] = 10128105,
            ["SpeakNpcId"] = 200071,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACA10",
            },
        [10128105] = {
            ["Content"] = "我不认识什么神弃者同盟……那长官你行行好，告诉我哪里可以办……办这个通行证。",
            ["ContentJP"] = "僕はフォーセイクン同盟なんて知りません……お願いします、せめて、どこで許可証が手に入るかだけでも教えてくれませんか……",
            ["DialogueId"] = 10128105,
            ["GUID"] = "195ACA3A",
            ["NextDialogue"] = 10128106,
            ["SpeakNpcId"] = 200089,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACA3A",
            },
        [10128106] = {
            ["Content"] = "自己到治安署门口，排队申请去！",
            ["ContentJP"] = "ああ、もううっとおしい！申請場所は保安署の前だ！",
            ["DialogueId"] = 10128106,
            ["GUID"] = "195ACA64",
            ["NextDialogue"] = 10128107,
            ["SpeakNpcId"] = 200071,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACA64",
            },
        [10128107] = {
            ["Content"] = "治安署……在城里啊……",
            ["ContentJP"] = "ですが……保安署は城内にしか……",
            ["DialogueId"] = 10128107,
            ["GUID"] = "195ACA8E",
            ["NextDialogue"] = 10128108,
            ["SpeakNpcId"] = 200089,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACA8E",
            },
        [10128108] = {
            ["Content"] = "那就不是我能管的了，自己回去想办法。别来烦我了。跟你说，我这都是脾气好的了，碰上脾气坏的家伙，一枪毙了你都没人敢为你收尸。",
            ["ContentJP"] = "俺の知ったことか！自分でなんとかしろ。ここにいるのが俺で良かったな。他だったら、今頃とっくにその頭をぶち抜かれてたぞ。",
            ["DialogueId"] = 10128108,
            ["GUID"] = "195ACAB8",
            ["NextDialogue"] = 10128109,
            ["SpeakNpcId"] = 200071,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACAB8",
            },
        [10128109] = {
            ["Content"] = "反正现在上头认定了，所有卡戎都是潜在的神弃者同盟分子。你啊，自己想办法吧。",
            ["ContentJP"] = "とにかく、これは上が決めたことなんだ。カロンはフォーセイクン同盟になるリスクがあるからな。さあ、いったいった！",
            ["DialogueId"] = 10128109,
            ["GUID"] = "195ACAE2",
            ["SpeakNpcId"] = 200071,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACAE2",
            },
        [10128110] = {
            ["Content"] = "前不久还不要通行证的啊……",
            ["ContentJP"] = "この前までは通行証なんていらなかったのに…",
            ["DialogueId"] = 10128110,
            ["GUID"] = "195ACAE3",
            ["NextDialogue"] = 10128111,
            ["SpeakNpcId"] = 200089,
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACAE3",
            },
        [10128111] = {
            ["Content"] = "抱怨什么啊，我还想抱怨呢！这都是上头的规定！",
            ["ContentJP"] = "グダグダうるせぇ！文句を言いたいのはこっちだぜ！上の命令なんだから仕方ねぇだろ！",
            ["DialogueId"] = 10128111,
            ["GUID"] = "195ACAE4",
            ["VoiceName"] = "voice/$Locale$/story/1002/101281/195ACAE4",
            },
        [10128201] = {
            ["Content"] = "今天我也忘了带通行证……",
            ["ContentJP"] = "俺も通行証を持って来るの忘れちまったんだ……",
            ["DialogueId"] = 10128201,
            ["GUID"] = "195AD9FA",
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195AD9FA",
            },
        [10128202] = {
            ["Content"] = "今天我也忘了带通行证出门，没被当场抓去坐牢算我运气好……",
            ["ContentJP"] = "俺も通行証を持って来るの忘れちまったんだ……牢屋にぶち込まれなくて良かったぜ……",
            ["DialogueId"] = 10128202,
            ["GUID"] = "195ADA24",
            ["NextOptions"] = {
                [1] = 101282021,
                [2] = 101282022,
                [3] = 101282023,
                },
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADA24",
            },
        [10128204] = {
            ["Content"] = "其实我觉得不重要，说是为了防止神弃者同盟混进城里，但人家想要来搞事情，难道会走正门？",
            ["ContentJP"] = "いやぁ、俺は正直なくてもいいと思ってるんだ。フォーセイクン対策だとは聞いてるが、そもそも企みを持つ連中がわざわざ正門から入ってくるか？",
            ["DialogueId"] = 10128204,
            ["GUID"] = "195ADA78",
            ["NextDialogue"] = 10128205,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADA78",
            },
        [10128205] = {
            ["Content"] = "到头来，只是给这些士兵欺压普通人多了一个借口：只要没带通行证，那就是可疑分子。",
            ["ContentJP"] = "結局は、平民を制圧するための口実だろ。通行証がないだけで、容疑者扱いなんてどうかしてる。",
            ["DialogueId"] = 10128205,
            ["GUID"] = "195ADAA2",
            ["NextDialogue"] = 10128206,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADAA2",
            },
        [10128206] = {
            ["Content"] = "大部分时候，只要把身上带的铜币都交出去，就没啥事了。但运气不好的话……就是你刚刚看到的样子了，哎，真造孽。",
            ["ContentJP"] = "ほとんどの場合、持ってる銅貨を全部差し出せば、通してくれる。だが、運が悪いと……さっきみたいなことになる。はぁ、ほんと酷い話だよな。",
            ["DialogueId"] = 10128206,
            ["GUID"] = "195ADACC",
            ["NextOptions"] = {
                [1] = 101282061,
                },
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADACC",
            },
        [10128208] = {
            ["Content"] = "也是有的，如果部队的长官是被帝国认可的桂冠卡戎，那手下的士兵一般都会收敛一些。",
            ["ContentJP"] = "まぁ、いるっちゃいるな。長官が桂冠カロン族とかの部隊だと、割と話が通じるやつも多いんだ。",
            ["DialogueId"] = 10128208,
            ["GUID"] = "195ADB20",
            ["NextDialogue"] = 10128209,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADB20",
            },
        [10128209] = {
            ["Content"] = "像是大家都知道的西比尔军团长啊，新来的黎瑟长官啊，都是会刻意约束手下的卡戎。",
            ["ContentJP"] = "シビル軍団長や、最近ではリズム長官とかかな。彼女たちは手下のもんをちゃんと抑えてるからな。",
            ["DialogueId"] = 10128209,
            ["GUID"] = "195ADB4A",
            ["NextDialogue"] = 10128210,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADB4A",
            },
        [10128210] = {
            ["Content"] = "不说了，我得回家拿通行证了。",
            ["ContentJP"] = "もういいか？通行許可証を取ってこないといけないから、そろそろ帰らせてもらうよ。",
            ["DialogueId"] = 10128210,
            ["GUID"] = "195ADB74",
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADB74",
            },
        [10128212] = {
            ["Content"] = "惩罚，当然有惩罚啦，关几天禁闭罚点钱就完事了。",
            ["ContentJP"] = "もちろん懲罰はあるぜ。だが、せいぜい数日の禁固とわずかな罰金ってとこだ。",
            ["DialogueId"] = 10128212,
            ["GUID"] = "195ADBC8",
            ["NextDialogue"] = 10128213,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADBC8",
            },
        [10128213] = {
            ["Content"] = "没办法，这是海伯利亚帝国，卡戎就是要低他们索拉之民一等。谁让我们卡戎没打得过他们呢。",
            ["ContentJP"] = "まあ、これがヒュペリア帝国だ。カロンはどうしてもソラの民より地位が低い。武力で勝てないんだから、どうしようもないんだよ。",
            ["DialogueId"] = 10128213,
            ["GUID"] = "195ADBF2",
            ["NextDialogue"] = 10128214,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADBF2",
            },
        [10128214] = {
            ["Content"] = "听说在大陆东方的尽头有一个叫做华胥的国家，那里好像就不太一样，卡戎过着好日子。",
            ["ContentJP"] = "聞いた話、大陸の東の果てに「<Default note=\"text:カショ\">華胥</>」という国があってな。そこではカロンもいい暮らしができるらしいんだ。",
            ["DialogueId"] = 10128214,
            ["GUID"] = "195ADC1C",
            ["NextOptions"] = {
                [1] = 101282141,
                },
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADC1C",
            },
        [10128216] = {
            ["Content"] = "唉，还不是因为卡戎干很多事都要被额外收一笔“卡戎监护金”，去华胥的路费贵的要死……",
            ["ContentJP"] = "はぁ……カロンは何をするにも「カロン税」ってもんがかかる。<Default note=\"text:カショ\">華胥</>につくより先に、貯金が底をついちまうぜ……",
            ["DialogueId"] = 10128216,
            ["GUID"] = "195ADC70",
            ["NextDialogue"] = 10128217,
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADC70",
            },
        [10128217] = {
            ["Content"] = "就算我攒够了我一个人的路费，但我还有老婆孩子呢……唉，我看你年纪轻轻，应该还有机会，努力攒攒钱吧。",
            ["ContentJP"] = "一人分ならまだしも、俺には妻子がいるんだ……はぁ、君はまだ若いし、チャンスがあるはずだ。頑張って金を貯めなさい。",
            ["DialogueId"] = 10128217,
            ["GUID"] = "195ADC9A",
            ["SpeakNpcId"] = 200090,
            ["VoiceName"] = "voice/$Locale$/story/1002/101282/195ADC9A",
            },
        [10128301] = {
            ["Content"] = "这个月第几个了……",
            ["ContentJP"] = "今月に入って何人目だ……",
            ["DialogueId"] = 10128301,
            ["GUID"] = "195AEA62",
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEA62",
            },
        [10128302] = {
            ["Content"] = "这个月第几个了……第三个了吧……这还做什么生意啊，我也投奔神弃者同盟算了。",
            ["ContentJP"] = "今月に入って何人目だ……三人はいるんじゃないか……？こんなんじゃ商売にならん。私もフォーセイクン同盟に加わりたい気分だよ。",
            ["DialogueId"] = 10128302,
            ["GUID"] = "195AEA8C",
            ["NextOptions"] = {
                [1] = 101283021,
                [2] = 101283022,
                [3] = 101283023,
                },
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEA8C",
            },
        [10128304] = {
            ["Content"] = "是啊，都是没带通行证，和这些士兵吵起来，然后就被当做神弃者同盟……",
            ["ContentJP"] = "ああ、通行許可証を持ってないせいで兵士と揉めて、フォーセイクン同盟の一味だと決めつけられた者の人数だよ……",
            ["DialogueId"] = 10128304,
            ["GUID"] = "195AEAE0",
            ["NextDialogue"] = 10128305,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEAE0",
            },
        [10128305] = {
            ["Content"] = "你说他们怎么能这样……难道就因为我们卡戎天生就低他们索拉之民一等吗？",
            ["ContentJP"] = "生まれつき、ソラの民より卑しい存在だからって、こんなのおかしいだろ……？",
            ["DialogueId"] = 10128305,
            ["GUID"] = "195AEB0A",
            ["NextDialogue"] = 10128306,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEB0A",
            },
        [10128306] = {
            ["Content"] = "哼，如果之前那场卡戎大反抗是我们卡戎赢了，他们还能这么耀武扬威？可惜啊可惜……",
            ["ContentJP"] = "ふん、大昔の大反乱で、勝っていたのが私たちカロンだったら……あいつらもあんな風に威張りちらすなんてできなかっただろうに。はぁ、残念だよ……",
            ["DialogueId"] = 10128306,
            ["GUID"] = "195AEB34",
            ["NextOptions"] = {
                [1] = 101283061,
                },
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEB34",
            },
        [10128308] = {
            ["Content"] = "你不知道啊？也是，看你年纪不大，大反抗的时候应该还没你呢，回去问问你爹妈吧，那时候帝国大部分卡戎都被卷进去了，他们应该也知道。",
            ["ContentJP"] = "知らないのか？まあ、その年じゃ無理もないな。ご両親に聞いてみなさい。あの事件には、帝国の大多数のカロンが関わったからね。彼らもきっと知ってるはずだよ。",
            ["DialogueId"] = 10128308,
            ["GUID"] = "195AEB88",
            ["NextDialogue"] = 10128309,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEB88",
            },
        [10128309] = {
            ["Content"] = "当时最前面的队伍都攻入了皇都，只是在最后一刻败了……所以现在帝国才对我们卡戎严防死守，拼了命的压制。",
            ["ContentJP"] = "当時、最前線の部隊は帝都にまで攻め込んだんだ。ただ、最後の最後で負けてしまった…だから、帝国は私たちカロンを警戒し、必死に抑え込もうとしてるんだ。",
            ["DialogueId"] = 10128309,
            ["GUID"] = "195AEBB2",
            ["NextDialogue"] = 10128310,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEBB2",
            },
        [10128310] = {
            ["Content"] = "不过嘛，现在这位陛下这么乱搞下去，我看距离下次战争也就是时间问题。",
            ["ContentJP"] = "まあ、皇帝がこのまま横行を続ければ、戦が起こるのも時間の問題だろうな。",
            ["DialogueId"] = 10128310,
            ["GUID"] = "195AEBDC",
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEBDC",
            },
        [10128312] = {
            ["Content"] = "怎么？想要同去？还是想要告密？",
            ["ContentJP"] = "なんだ？一緒に行くか？それとも、軍の連中に告発する気とか？",
            ["DialogueId"] = 10128312,
            ["GUID"] = "195AEC30",
            ["NextDialogue"] = 10128313,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEC30",
            },
        [10128313] = {
            ["Content"] = "唉，我也就是说说气话。虽说神弃者同盟是卡戎们组成的反抗组织，但真想要找到他们又是不可能的事情。",
            ["ContentJP"] = "はぁ、本気なわけないだろ。フォーセイクン同盟は確かにカロンによって作られた反乱組織だが、私たちのような凡人には、彼らを見つけることはできないよ。",
            ["DialogueId"] = 10128313,
            ["GUID"] = "195AEC5A",
            ["NextDialogue"] = 10128314,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEC5A",
            },
        [10128314] = {
            ["Content"] = "在上次卡戎大反抗失败后，他们的行动就变得极度隐秘，没人知道他们现在现在有多少人、有没有什么大本营、怎么找到他们。",
            ["ContentJP"] = "前回のカロン大反乱が失敗してから、あいつらは表舞台から引っ込んでしまってね。そのアジトを知る者すら、ほとんどいないのが現状だ。",
            ["DialogueId"] = 10128314,
            ["GUID"] = "195AEC84",
            ["NextDialogue"] = 10128315,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AEC84",
            },
        [10128315] = {
            ["Content"] = "甚至也有人说，神弃者同盟早就解散了，只是治安署的那些无能之辈遇到破不了的案子，就会和上头报告说是神弃者同盟糊弄事。",
            ["ContentJP"] = "フォーセイクン同盟はとっくに解散したと言ってるやつもいる。そのくせ、難解な事件に遭遇するたびに、保安署の無能どもは「フォーセイクン同盟の仕業」だと報告するんだ。皮肉な話だろ。",
            ["DialogueId"] = 10128315,
            ["GUID"] = "195AECAE",
            ["NextDialogue"] = 10128316,
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AECAE",
            },
        [10128316] = {
            ["Content"] = "但我还是相信他们一定在暗处积蓄着力量，直到哪一天，让这些索拉血债血偿。",
            ["ContentJP"] = "だが、連中はきっと裏で力を蓄えてるはずだと思うんだ。ソラの恨みを晴らす日がきっと来るって、私は信じてる。",
            ["DialogueId"] = 10128316,
            ["GUID"] = "195AECD8",
            ["SpeakNpcId"] = 200091,
            ["VoiceName"] = "voice/$Locale$/story/1002/101283/195AECD8",
            },
        [10128401] = {
            ["Content"] = "宅子挺大，但鬼气森森……",
            ["ContentJP"] = "この屋敷からは、どうも不気味な気配を……",
            ["DialogueId"] = 10128401,
            ["GUID"] = "195AFACA",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFACA",
            },
        [10128402] = {
            ["Content"] = "这宅子又高又大，鬼气森森。买得起的人不愿意住，想住的人买不起。",
            ["ContentJP"] = "この大きな屋敷からは、どうも不気味な気配を感じるわ。買えるほどの財力を持つ者には忌み嫌われ、一方でここに住みたがる者はきっと財力に欠けてる。",
            ["DialogueId"] = 10128402,
            ["GUID"] = "195AFAF4",
            ["NextOptions"] = {
                [1] = 101284021,
                [2] = 101284022,
                [3] = 101284023,
                [4] = 101284024,
                },
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFAF4",
            },
        [10128404] = {
            ["Content"] = "是啦，你不知道吗？这可是冰湖城两大知名鬼屋之一！据说在这里待过的住客不是被帝国找麻烦，就是和亲人离散。",
            ["ContentJP"] = "ええ、知らないの？ここはアイスレイク城の二大心霊スポットの一つと言われているのよ！なんでも、ここに住んでいた者は、ほとんど帝国に目をつけられるか、家族が散り散りになるか――",
            ["DialogueId"] = 10128404,
            ["GUID"] = "195AFB48",
            ["NextDialogue"] = 10128405,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFB48",
            },
        [10128405] = {
            ["Content"] = "至于城里的另一个鬼屋，那就是你们刚刚从那里出来的修普诺斯之家。据说每个夜晚，那里都会传出哭声。",
            ["ContentJP"] = "もう一つのスポットは、先程あなたたちがいた「ヒュプノスの家」よ。なんでも、毎晩不気味な泣き声が聞こえるとか……",
            ["DialogueId"] = 10128405,
            ["GUID"] = "195AFB72",
            ["NextDialogue"] = 10128406,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFB72",
            },
        [10128406] = {
            ["Content"] = "嗯……好像都和那个恩里克有关系哦。",
            ["ContentJP"] = "ふむ……どちらも、あのヘンリックと関係があるようね。",
            ["DialogueId"] = 10128406,
            ["GUID"] = "195AFB9C",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFB9C",
            },
        [10128408] = {
            ["Content"] = "哎，这怎么叫窥探呢，这么大的房子来了新住客能不好奇吗？",
            ["ContentJP"] = "覗き見だなんて人聞きが悪い！こんな大きな屋敷、初めて見た者なら誰だって気になると思うけど？",
            ["DialogueId"] = 10128408,
            ["GUID"] = "195AFBF0",
            ["NextDialogue"] = 10128409,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFBF0",
            },
        [10128409] = {
            ["Content"] = "冰湖城里大大小小这么多户人家我都知道的一清二楚，都是我挨家挨户打听出来的，其他人可没说过什么窥探隐私之类的话。",
            ["ContentJP"] = "それに、アイスレイク城の住民のことなら、私はなんだって知ってるわ。一軒一軒訪問して回ったんだもの。彼らにすら覗き見だなんて言われたことはないんだから。",
            ["DialogueId"] = 10128409,
            ["GUID"] = "195AFC1A",
            ["NextDialogue"] = 10128410,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFC1A",
            },
        [10128410] = {
            ["Content"] = "不过既然你都这么说了，那我就不在这里自讨没趣了，再见——我相信我们会再见的。",
            ["ContentJP"] = "とはいえ、今日のところは大人しく帰るとしましょう。どうせまた会えるでしょうし。",
            ["DialogueId"] = 10128410,
            ["GUID"] = "195AFC44",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFC44",
            },
        [10128412] = {
            ["Content"] = "我？哎呀我就是一个写点东西挣钱的，管我叫大记者安苏兹（Ansuz）就好。",
            ["ContentJP"] = "私？そうね……噂話を金に変える「記者」をやってるわ。アンスーズと呼んでちょうだい。",
            ["DialogueId"] = 10128412,
            ["GUID"] = "195AFC98",
            ["NextDialogue"] = 10128413,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFC98",
            },
        [10128413] = {
            ["Content"] = "我一直在冰湖城里搜罗消息，写成文章，印刷报纸，带来欢乐。",
            ["ContentJP"] = "アイスレイク城で記事になる情報を集め、新聞として民に喜びをもたらしているの。",
            ["DialogueId"] = 10128413,
            ["GUID"] = "195AFCC2",
            ["NextDialogue"] = 10128414,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFCC2",
            },
        [10128414] = {
            ["Content"] = "怎么一副不信的样子，来，拿着，今天的《冰湖城早报》。这份免费，喜欢再买。",
            ["ContentJP"] = "その顔……全然信じてないね。ほら、本日の「アイスレイク新聞」よ。これはタダであげるわ。気に入ったら次号からは自分で買ってね。",
            ["DialogueId"] = 10128414,
            ["GUID"] = "195AFCEC",
            ["NextDialogue"] = 10128415,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFCEC",
            },
        [10128415] = {
            ["Content"] = "当然，如果你有什么新闻线索的话，也可以来找我，免费给你换一份。",
            ["ContentJP"] = "もちろん、もし話題性のある噂を聞いたら、なんでも教えて。報酬として、無料で新聞をあげるから。",
            ["DialogueId"] = 10128415,
            ["GUID"] = "195AFD16",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101284/195AFD16",
            },
        [10128501] = {
            ["Content"] = "玛尔洁姐姐带来了生活费。",
            ["ContentJP"] = "マギーお姉さんが生活費を持ってきてくれたよ。",
            ["DialogueId"] = 10128501,
            ["GUID"] = "195B0B32",
            ["NextDialogue"] = 10128502,
            ["SpeakNpcId"] = 200093,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0B32",
            },
        [10128502] = {
            ["Content"] = "不能一直这样。",
            ["ContentJP"] = "でも、ずっとこのままじゃダメだよ。",
            ["DialogueId"] = 10128502,
            ["GUID"] = "195B0B5C",
            ["SpeakNpcId"] = 200094,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0B5C",
            },
        [10128503] = {
            ["Content"] = "玛尔洁姐姐带回了这个月的生活费哦，这样一来就不用担心月底饿肚子了。玛尔洁姐姐真好！",
            ["ContentJP"] = "マギーお姉さんが今月の生活費を持ってきてくれたよ！これで月末もお腹を空かせなくて済むね。マギーお姉さん、本当にいい人だなぁ……",
            ["DialogueId"] = 10128503,
            ["GUID"] = "195B0B86",
            ["NextDialogue"] = 10128504,
            ["SpeakNpcId"] = 200093,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0B86",
            },
        [10128504] = {
            ["Content"] = "我听说啊，这些生活费先前都被人偷走了，是玛尔洁姐姐和一个好心的狩月人好不容易追回来的。",
            ["ContentJP"] = "でも、これらはもともと盗まれたものなんだって。それをマギーお姉さんと心優しい月狩り人さんが取り返してくれたって聞いたよ。",
            ["DialogueId"] = 10128504,
            ["GUID"] = "195B0BB0",
            ["NextDialogue"] = 10128505,
            ["SpeakNpcId"] = 200094,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0BB0",
            },
        [10128505] = {
            ["Content"] = "不能这样，这样不行。我们不能总是这么依靠玛尔洁姐姐。我说难听一点，要是她有什么万一，难道我们就一直饿着肚子吗？",
            ["ContentJP"] = "このままじゃダメだよ。ずっとマギーお姉さんに頼りっきりじゃ……万が一彼女に何かあったら、生きていけないよ。それでいいの？",
            ["DialogueId"] = 10128505,
            ["GUID"] = "195B0BDA",
            ["NextDialogue"] = 10128506,
            ["SpeakNpcId"] = 200094,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0BDA",
            },
        [10128506] = {
            ["Content"] = "哎，要是我能吃饱，多长点力气，就也能去做狩月人，去帮玛尔洁姐姐了。",
            ["ContentJP"] = "はぁ、もし食料がたくさんあったらなぁ。そうすれば、力をつけて月狩り人になったり、マギーお姉さんのお手伝いができるかもしれないのに。",
            ["DialogueId"] = 10128506,
            ["GUID"] = "195B0C04",
            ["NextDialogue"] = 10128507,
            ["SpeakNpcId"] = 200093,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0C04",
            },
        [10128507] = {
            ["Content"] = "那你多吃一点，这块饼干我吃不完，掰一半给你。等你长得比玛尔洁姐姐的铲子高了，就代替她给贫民窟的各位攒生活费。",
            ["ContentJP"] = "じゃあいっぱいお食べ。クッキー食べきれないから半分あげるね。それで、マギーお姉さんのスコップより高くなったら、スラム街のみんなの生活費はあなたに任せるわ。",
            ["DialogueId"] = 10128507,
            ["GUID"] = "195B0C2E",
            ["NextDialogue"] = 10128508,
            ["SpeakNpcId"] = 200094,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0C2E",
            },
        [10128508] = {
            ["Content"] = "好呀好呀，不过我相信啊，到那时候啊，住在这里的各位应该都能吃饱，不会再要人攒钱救济了。",
            ["ContentJP"] = "もちろん！でも、その時にはきっと、スラム街も施しに頼らずお腹いっぱい食べれるようになってると思う！",
            ["DialogueId"] = 10128508,
            ["GUID"] = "195B0C58",
            ["NextDialogue"] = 10128509,
            ["SpeakNpcId"] = 200093,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0C58",
            },
        [10128509] = {
            ["Content"] = "要真有那么一天就好了，那时候玛尔洁姐姐，还有大家都不用这辛苦……哎，你吃饼干的样子真丑，狼吞虎咽的。",
            ["ContentJP"] = "本当にそんな日が来たらいいな。そうすれば、マギーお姉さんもみんなも、あんなに苦労せずに済む……はぁ、お行儀が悪いよ。ゆっくり食べなさい。",
            ["DialogueId"] = 10128509,
            ["GUID"] = "195B0C82",
            ["NextDialogue"] = 10128510,
            ["SpeakNpcId"] = 200094,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0C82",
            },
        [10128510] = {
            ["Content"] = "唔，唔唔……",
            ["ContentJP"] = "んぐ……んん……",
            ["DialogueId"] = 10128510,
            ["GUID"] = "195B0CAC",
            ["SpeakNpcId"] = 200093,
            ["VoiceName"] = "voice/$Locale$/story/1002/101285/195B0CAC",
            },
        [10128601] = {
            ["Content"] = "八点要到了吧……",
            ["ContentJP"] = "そろそろ8時か……",
            ["DialogueId"] = 10128601,
            ["GUID"] = "195B1B9A",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1B9A",
            },
        [10128602] = {
            ["Content"] = "我和朋友约好八点钟在水仙平原见面，但我又没带怀表。所以我来到了这里，只要恩里克一出现，我就知道，八点到了。",
            ["ContentJP"] = "8時に友人とアスフォデロスで待ち合わせしてるんだけど、懐中時計を忘れてしまってね。だからここに来たの。ヘンリックが来れば、ほぼ8時だと分かるわ。",
            ["DialogueId"] = 10128602,
            ["GUID"] = "195B1BC4",
            ["NextOptions"] = {
                [1] = 101286021,
                [2] = 101286022,
                [3] = 101286023,
                },
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1BC4",
            },
        [10128604] = {
            ["Content"] = "我就是知道，恩里克这个习惯维持了很久了。像是他这么死板的人会干出的事情，固定时间出门，固定时间吃饭之类。",
            ["ContentJP"] = "ヘンリックは毎日決まってこの時間にここに来るの。あの人、几帳面だから、こういう習慣は簡単に崩したりしないのよ。",
            ["DialogueId"] = 10128604,
            ["GUID"] = "195B1C18",
            ["NextDialogue"] = 10128605,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1C18",
            },
        [10128605] = {
            ["Content"] = "你说，他是不是连呼吸都是固定节奏，自己有意识在控制的？啊，有了，我要写一篇文章，标题就叫《规律生活，把握人生》，怎么样？",
            ["ContentJP"] = "もしかしてさ、呼吸のリズムまで自分でコントロールしてたりして？……あ、いいタイトルを思いついた。『規則正しい生活が、人生を変える』、どう？",
            ["DialogueId"] = 10128605,
            ["GUID"] = "195B1C42",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1C42",
            },
        [10128607] = {
            ["Content"] = "我？哎呀我就是一个写点东西挣钱的，管我叫大记者安苏兹（Ansuz）就好。",
            ["ContentJP"] = "私？そうね……噂話を金に変える「記者」をやってるわ。アンスーズと呼んでちょうだい。",
            ["DialogueId"] = 10128607,
            ["GUID"] = "195B1C96",
            ["NextDialogue"] = 10128608,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1C96",
            },
        [10128608] = {
            ["Content"] = "我一直在冰湖城里搜罗消息，写成文章，印刷报纸，带来欢乐。",
            ["ContentJP"] = "アイスレイク城で記事になる情報を集め、新聞として民に喜びをもたらしているの。",
            ["DialogueId"] = 10128608,
            ["GUID"] = "195B1CC0",
            ["NextDialogue"] = 10128609,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1CC0",
            },
        [10128609] = {
            ["Content"] = "怎么一副不信的样子，来，拿着，今天的《冰湖城早报》。这份免费，喜欢再买。",
            ["ContentJP"] = "その顔……全然信じてないね。ほら、本日の「アイスレイク新聞」よ。これはタダであげるわ。気に入ったら次号からは自分で買ってね。",
            ["DialogueId"] = 10128609,
            ["GUID"] = "195B1CEA",
            ["NextDialogue"] = 10128610,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1CEA",
            },
        [10128610] = {
            ["Content"] = "当然，如果你有什么新闻线索的话，也可以来找我，免费给你换一份。",
            ["ContentJP"] = "もちろん、もし話題性のある噂を聞いたら、なんでも教えて。報酬として、無料で新聞をあげるから。",
            ["DialogueId"] = 10128610,
            ["GUID"] = "195B1D14",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101286/195B1D14",
            },
        [10128701] = {
            ["Content"] = "唉……还是不写报道了。",
            ["ContentJP"] = "はぁ……やっぱり記事にするのはやめとこ。",
            ["DialogueId"] = 10128701,
            ["GUID"] = "195B2C02",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2C02",
            },
        [10128702] = {
            ["Content"] = "唉……还是不写报道了，整版整版都没什么好事，还是不给人添堵了。",
            ["ContentJP"] = "はぁ……やっぱり記事にするのはやめとこ。ページは埋まってもロクな話ないし、読む人の気分まで重くしちゃいそうだしね。",
            ["DialogueId"] = 10128702,
            ["GUID"] = "195B2C2C",
            ["NextOptions"] = {
                [1] = 101287021,
                [2] = 101287022,
                [3] = 101287023,
                [4] = 101287024,
                },
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2C2C",
            },
        [10128704] = {
            ["Content"] = "还能是什么报道……无非是那个小姑娘身上发生的那些事。恩里克不在了，没人拦着我，我进去问明白了个七七八八。",
            ["ContentJP"] = "あの少女のことに決まってるでしょ……ヘンリックがいなくなったから、屋敷に入って聞けるだけ聞いてきたの。だいたいの事情は掴めたわ。",
            ["DialogueId"] = 10128704,
            ["GUID"] = "195B2C80",
            ["NextDialogue"] = 10128705,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2C80",
            },
        [10128705] = {
            ["Content"] = "我做《冰湖城早报》是想给人带来快乐，鼓舞人心，但冰湖城里发生的坏事还是太多了。",
            ["ContentJP"] = "私が『アイスレイク新聞』を書いてるのは、人々に喜びを届けるため。でも、アイスレイク城は最近悪いこと続きで、ほんと参っちゃうわ……",
            ["DialogueId"] = 10128705,
            ["GUID"] = "195B2CAA",
            ["NextDialogue"] = 10128706,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2CAA",
            },
        [10128706] = {
            ["Content"] = "前一天的报道里提到的工匠父子，第二天就可能横死街头。原本预定采访的卡戎诗人，过一阵就可能彻底发疯。",
            ["ContentJP"] = "前日取り上げた職人の親子も、翌日には路上で無惨な最期を迎えるかもしれない。取材を予定していたカロンの詩人だって、しばらくしたら正気を失ってしまうかもしれないのよ。",
            ["DialogueId"] = 10128706,
            ["GUID"] = "195B2CD4",
            ["NextDialogue"] = 10128707,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2CD4",
            },
        [10128707] = {
            ["Content"] = "他们就像是泪湖上空落下的雪，落下后成为湖冰，无人在意。但我也相信，当这些坚冰融化之时，整个冰湖城都会倒塌。",
            ["ContentJP"] = "彼らはまるで、ダクリ湖に降り積もる雪みたい。やがて氷となって湖に閉じ込められ、誰にも気づかれない。でも私は信じてるわ。その氷がいつか溶けるとき、アイスレイク城そのものが崩れ落ちるって。",
            ["DialogueId"] = 10128707,
            ["GUID"] = "195B2CFE",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2CFE",
            },
        [10128709] = {
            ["Content"] = "有吧，虽然现在没有，但总会有的。",
            ["ContentJP"] = "あるよ、きっと。今はなくても、いつかきっと現れる。",
            ["DialogueId"] = 10128709,
            ["GUID"] = "195B2D52",
            ["NextDialogue"] = 10128710,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2D52",
            },
        [10128710] = {
            ["Content"] = "你也别太伤心，我向你保证，我们卡戎开始反抗的日子，不远了。",
            ["ContentJP"] = "あなたもあまり落ち込まないで。私、信じてるから――私たちカロンが立ち上がる日は、もうすぐそこよ。",
            ["DialogueId"] = 10128710,
            ["GUID"] = "195B2D7C",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2D7C",
            },
        [10128712] = {
            ["Content"] = "《冰湖城早报》的记者，安苏兹。你现在可以叫我这个。",
            ["ContentJP"] = "『アイスレイク新聞』の記者、アンスーズよ。今はこの名で呼んでちょうだい。",
            ["DialogueId"] = 10128712,
            ["GUID"] = "195B2DD0",
            ["NextDialogue"] = 10128713,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2DD0",
            },
        [10128713] = {
            ["Content"] = "不过实际上，其他城市的报纸多多少少和我也有点关联。我是想用文字让我们卡戎之民的处境变好一点。",
            ["ContentJP"] = "実はね、他の街の新聞にも、少しだけ関わってるの。……私は文字で、カロンが少しでも生きやすくなるようにしたい。",
            ["DialogueId"] = 10128713,
            ["GUID"] = "195B2DFA",
            ["NextDialogue"] = 10128714,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2DFA",
            },
        [10128714] = {
            ["Content"] = "当然了，我也非常明白，只有笔是不够的，我们要握起剑来，我们要让他们血债血偿。",
            ["ContentJP"] = "もちろん言葉だけじゃ足りないってことくらいわかってる。私たちは剣を手に取るべきなの。あいつらに――その罪を、血で償わせなきゃ。",
            ["DialogueId"] = 10128714,
            ["GUID"] = "195B2E24",
            ["NextDialogue"] = 10128715,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2E24",
            },
        [10128715] = {
            ["Content"] = "到那时候，我相信你也会成为我的同伴的。",
            ["ContentJP"] = "その時が来たら……きっとあなたも、仲間になってくれるって信じてるから。",
            ["DialogueId"] = 10128715,
            ["GUID"] = "195B2E4E",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101287/195B2E4E",
            },
        [10128801] = {
            ["Content"] = "一杯……六杯……十三杯……",
            ["ContentJP"] = "一杯目……六杯目……十三杯目……",
            ["DialogueId"] = 10128801,
            ["GUID"] = "195B3C6A",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3C6A",
            },
        [10128802] = {
            ["Content"] = "一杯酒下肚，卡戎索拉和睦睦，六杯酒下肚，第六军团一群猪，喝了十三杯……",
            ["ContentJP"] = "一杯飲めば、カロンとソラも仲良しこよし～。六杯目にゃ、第六軍団のくそくらえ！十三杯？へっ、十三杯も飲んだらよぉ……",
            ["DialogueId"] = 10128802,
            ["GUID"] = "195B3C94",
            ["NextOptions"] = {
                [1] = 101288021,
                [2] = 101288022,
                [3] = 101288023,
                },
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3C94",
            },
        [10128804] = {
            ["Content"] = "我好的很，不好的是冰湖城！所以来一杯酒吧朋友，麻醉思考，调和人生。酒精进入脑袋的那一刻，上司就会变成猪，如果你喜欢的话，狗也可以。",
            ["ContentJP"] = "俺は絶好調さ。ダメなのは、このアイスレイク城のほうだっての。だからさ、一杯くれよ、相棒。酔いで思考を溶かして、人生まろやかに味つけしようぜ。酒が脳ん中にしみ込んだ瞬間にはな、上司なんざブタ見えてくる。いや、犬か？まあ、好きに想像できちまうってんだ！",
            ["DialogueId"] = 10128804,
            ["GUID"] = "195B3CE8",
            ["NextDialogue"] = 10128805,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3CE8",
            },
        [10128805] = {
            ["Content"] = "不过我还是喜欢猪。狗崇拜人类。猫鄙视人类。猪对我们一视同仁。所以说那群贵族和军团啊连猪都不如，卡戎们都过成这样了，他们还在唱唱跳跳。",
            ["ContentJP"] = "でもな、俺はやっぱり豚が好きなんだよ。犬は人間にヘコヘコして、猫は人間をバカにしてる。けど豚はさ、こっちを見ても何とも思ってねぇ。みんな同じ、って顔してる。……だから言うけどさ、あの貴族どもも軍団の連中も、豚以下だ。カロンの連中がどんだけ苦しんでると思ってんだ。そん中であいつら、のうのうと歌って踊ってやがる。",
            ["DialogueId"] = 10128805,
            ["GUID"] = "195B3D12",
            ["NextDialogue"] = 10128806,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3D12",
            },
        [10128806] = {
            ["Content"] = "还好有酒，还好有酒，我的灵魂喜欢威士忌的泥土芳香。我可能不是索拉，实际上我的灵魂是七十三升的烈酒，我的身体是束缚的橡木桶！",
            ["ContentJP"] = "酒があってよかった、ほんとによ……ありがたいよな、酒ってやつは。俺の魂はな、ウイスキーの土の香りが大好きなんだ。……たぶん俺はソラなんかじゃない。俺の魂はな――七十三リットルのリキュールでできてんだよ！この体は、その魂を閉じ込めるオークの樽さ！",
            ["DialogueId"] = 10128806,
            ["GUID"] = "195B3D3C",
            ["NextDialogue"] = 10128807,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3D3C",
            },
        [10128807] = {
            ["Content"] = "对，对，要是卡戎和索拉都是烈酒就好了，大家可以彼此交融调和，世界啊就是一汪浩瀚无边的鸡尾酒或者三分糖橙子果汁！",
            ["ContentJP"] = "そうだよ、そうだ……カロンもソラも、みーんなリキュールだったらよかったのにな。そしたら混ざり合って、溶け合って、うまくやれたかもしれないのにさ。世界そのものが、でっかいカクテルみたいなもんでさ！いや、微糖のオレンジジュースでもいいぞ、甘くて、ちょっと酸っぱいやつ！",
            ["DialogueId"] = 10128807,
            ["GUID"] = "195B3D66",
            ["NextDialogue"] = 10128808,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3D66",
            },
        [10128808] = {
            ["Content"] = "你也喝吧，一醉解百忧，大家是朋友。",
            ["ContentJP"] = "お前も飲めよ。酔えば悩みなんて吹っ飛ぶさ。……な？俺たち、もう友だちだろ？",
            ["DialogueId"] = 10128808,
            ["GUID"] = "195B3D90",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3D90",
            },
        [10128810] = {
            ["Content"] = "哎呀你这新来的卡戎，这不是明摆着的吗，我在这里醉酒！",
            ["ContentJP"] = "おいおい、新入りのカロンさんよ～、見りゃわかるだろ？俺はいま、絶賛・酩酊中だっての！",
            ["DialogueId"] = 10128810,
            ["GUID"] = "195B3DE4",
            ["NextDialogue"] = 10128811,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3DE4",
            },
        [10128811] = {
            ["Content"] = "如果不醉酒，那就要好好工作，我要好好工作，你们就都不能活，所以我还是要选择醉酒。你们应该感激我，我在慢性自杀换你们活得长久。",
            ["ContentJP"] = "正気に戻りゃ、ちゃんと働くしかない。俺が本気で働きゃ、お前らなんか一人残らず消える。……だから俺は、酔うことにしてるんだよ。感謝してほしいくらいさ。俺はな、少しずつ死に近づいてんだ――おまえらが長生きできるようにな。",
            ["DialogueId"] = 10128811,
            ["GUID"] = "195B3E0E",
            ["NextDialogue"] = 10128812,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3E0E",
            },
        [10128812] = {
            ["Content"] = "敬我一杯酒吧，我是罪人，也是善人，我的初次见面的卡戎朋友。",
            ["ContentJP"] = "俺に乾杯！俺は罪人で、同時に善人だ。……はじめましての、カロンの友よ。",
            ["DialogueId"] = 10128812,
            ["GUID"] = "195B3E38",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101288/195B3E38",
            },
        [10128901] = {
            ["Content"] = "你又不真的是酒桶，别喝了……",
            ["ContentJP"] = "本物の樽じゃないんだからさ……それくらいにしとけって。",
            ["DialogueId"] = 10128901,
            ["GUID"] = "195B4CD2",
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4CD2",
            },
        [10128902] = {
            ["Content"] = "唉，他又喝了不少，这样下去迟早会死，要是换一个新的索拉人来监视那就不好办了。",
            ["ContentJP"] = "はぁ……またけっこう飲んでるな。こんな調子じゃ、そのうち倒れるぞ。そうなったら、次は別のソラ族が監視として……それだけは勘弁してほしいんだけど。",
            ["DialogueId"] = 10128902,
            ["GUID"] = "195B4CFC",
            ["NextOptions"] = {
                [1] = 101289021,
                [2] = 101289022,
                [3] = 101289023,
                },
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4CFC",
            },
        [10128904] = {
            ["Content"] = "是啊，唉你是新来的应该不知道，他是第六军团派来贫民窟的监视员，说是要找出这边的危险分子，以儆效尤。",
            ["ContentJP"] = "ああ……君は新入りだから知らないか。あいつ、第六軍団からこのスラムに派遣された監視役でさ。何か企んでるやつらを炙り出して、見せしめにするのが目的らしいんだ。",
            ["DialogueId"] = 10128904,
            ["GUID"] = "195B4D50",
            ["NextDialogue"] = 10128905,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4D50",
            },
        [10128905] = {
            ["Content"] = "他来这边第一天，记下了三个人有些可疑，第二天那三个人就都被吊死了。这件事给了他不小的刺激，可能一开始他以为就是关几天了事吧。",
            ["ContentJP"] = "こっちに来た初日に、あいつは「怪しい」三人をメモしたんだ。そしたら次の日には、三人全員が首を吊られてた。……かなりショックだったみたいだよ。最初は、せいぜい数日拘束されるくらいだと思ってたんだろうな。",
            ["DialogueId"] = 10128905,
            ["GUID"] = "195B4D7A",
            ["NextDialogue"] = 10128906,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4D7A",
            },
        [10128906] = {
            ["Content"] = "在那之后他就这样了，每天泡在酒里，仿佛真的想要醉死自己一样，整天说世界是一个大酒桶，自己是一个小酒桶，大家应该都成为一桶酒这样的话。",
            ["ContentJP"] = "それからずっとこんな調子さ。毎日酒に溺れて、まるで自分から酔い潰れたいみたいに飲んでる。「世界はでっかい酒樽で、自分はちっちゃな酒樽。みんなで一つの酒になればいい」……とか、そんなことばっかり言ってんの。",
            ["DialogueId"] = 10128906,
            ["GUID"] = "195B4DA4",
            ["NextDialogue"] = 10128907,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4DA4",
            },
        [10128907] = {
            ["Content"] = "对上司嘛，一直汇报说卡戎们因为他第一天的雷厉风行，都被吓得和鹌鹑一样老老实实，就这样应付过去。",
            ["ContentJP"] = "上にはな、こう報告してるらしいよ。「初日の厳しい対応が効いたようで、カロンどもはすっかりビビって、大人しくしてます」ってさ。そんな調子で、うまいことやり過ごしてんのさ。",
            ["DialogueId"] = 10128907,
            ["GUID"] = "195B4DCE",
            ["NextDialogue"] = 10128908,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4DCE",
            },
        [10128908] = {
            ["Content"] = "实际上又怎么会呢？真要按照他一开始的工作劲头，这里所有人都会被吊死十次不止，不过在那之前，恐怕他也会被其他人打死。",
            ["ContentJP"] = "実際のところ、そんなわけないだろ？最初の勢いのまま真面目に仕事してたら、この辺の連中なんて、十回は吊るされてるだろう。……もっとも、その前にこいつ自身が誰かに殺されてたかもしれないけどな。",
            ["DialogueId"] = 10128908,
            ["GUID"] = "195B4DF8",
            ["NextDialogue"] = 10128909,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4DF8",
            },
        [10128909] = {
            ["Content"] = "唉，所以说现在这样，借着醉酒逃避工作对他来说也是最好的做法了。现在这边的酒客大部分也不恨他了，军团里有良心的人不多，他算是一个。",
            ["ContentJP"] = "はぁ……だから今が、こいつにとってはいちばん楽なんだろうな。酔っ払って、仕事から目を背けることでさ。今じゃ、ここにいる酒好きたちも、もうこいつを憎んじゃいない。軍団に良心のあるやつなんて滅多にいないからな……こいつは、マシなほうだよ。",
            ["DialogueId"] = 10128909,
            ["GUID"] = "195B4E22",
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4E22",
            },
        [10128911] = {
            ["Content"] = "大部分情况下是的，卡戎从一出生就会被帝国教育说卡戎们是邪恶的，会带来许多灾难。",
            ["ContentJP"] = "まあ、ほとんどの場合そうだよ。カロンなんて、生まれたときから帝国に刷り込まれてるんだ。「カロンは邪悪で、災いをもたらす存在だ」ってな。",
            ["DialogueId"] = 10128911,
            ["GUID"] = "195B4E76",
            ["NextDialogue"] = 10128912,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4E76",
            },
        [10128912] = {
            ["Content"] = "成长途中也会目睹那些没有角的索拉人是如何手握着武器高高在上，用子弹和列车炮把所有的反抗者轰成碎块。",
            ["ContentJP"] = "成長の過程で嫌でも見ることになるんだよ。角のないソラどもが、武器を手にふんぞり返ってさ――反抗したカロンたちを、銃弾と列車砲でバラバラに吹き飛ばしていくのを。",
            ["DialogueId"] = 10128912,
            ["GUID"] = "195B4EA0",
            ["NextDialogue"] = 10128913,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4EA0",
            },
        [10128913] = {
            ["Content"] = "而卡戎们反抗起来对索拉们也并不客气就是了，只不过现在恰好是索拉们占据优势的时候。",
            ["ContentJP"] = "もちろんカロンだって、本気で反抗すればソラに容赦なんてしないさ。ただ……今はたまたま、ソラのほうが優勢ってだけの話だよ。",
            ["DialogueId"] = 10128913,
            ["GUID"] = "195B4ECA",
            ["NextDialogue"] = 10128914,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4ECA",
            },
        [10128914] = {
            ["Content"] = "矛盾啊就像是一个螺旋，一直在延续着累积着。有时候卡戎居上，有时候索拉居上，只不过索拉居上时候要长得多就是了。",
            ["ContentJP"] = "この対立はな、まるで螺旋みたいに続いてるんだよ。積み重なって、ぐるぐると。カロンが上に立つこともあれば、ソラが上に立つこともある。でも……ソラが上にいる時間のほうが、ずっと長いんだ。",
            ["DialogueId"] = 10128914,
            ["GUID"] = "195B4EF4",
            ["NextDialogue"] = 10128915,
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4EF4",
            },
        [10128915] = {
            ["Content"] = "看你一副初来乍到的样子，奉劝你一句，活着比什么都重要。留一条命在，说不定就能看到卡戎们的好日子。",
            ["ContentJP"] = "見たところ、新入りっぽいな。一つだけ言っておく――生き延びることが、何より大事だ。命さえあれば、いつかカロンにだって、春が来るかもしれないんだから。",
            ["DialogueId"] = 10128915,
            ["GUID"] = "195B4F1E",
            ["SpeakNpcId"] = 200096,
            ["VoiceName"] = "voice/$Locale$/story/1002/101289/195B4F1E",
            },
        [10129001] = {
            ["Content"] = "抓回来就好，也没人受伤，走运啊走运。",
            ["ContentJP"] = "連れ戻せたんなら上出来だ。ケガ人も出てねぇし、ツイてる、ツイてる。",
            ["DialogueId"] = 10129001,
            ["GUID"] = "195B5D3A",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5D3A",
            },
        [10129002] = {
            ["Content"] = "听说你抓到的那个小偷是被送去了治安署？太走运了，被提前阻止了就好，干得好啊年轻人。",
            ["ContentJP"] = "聞いたぜ、お前が捕まえたあの泥棒、保安署に送られたんだって？いや～運が良かったなぁ、早めに止められてさ。よくやったよ、若いの！",
            ["DialogueId"] = 10129002,
            ["GUID"] = "195B5D64",
            ["NextOptions"] = {
                [1] = 101290021,
                [2] = 101290022,
                [3] = 101290023,
                },
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5D64",
            },
        [10129004] = {
            ["Content"] = "是啊，像他这样的情况被送去治安署是最好的结局了，否则再由着他胡闹，搞出更大的乱子，那针对卡戎的各种谣言和恨意都变得更多。",
            ["ContentJP"] = "そうそう、ああいう手合いは保安署送りがいちばんマシな結末さ。あのまま好き勝手やらせてたら、もっと大きな騒ぎになってた。……そしたらまたさ、カロンに対するデマや憎しみが、さらに広がっちまうだろ？",
            ["DialogueId"] = 10129004,
            ["GUID"] = "195B5DB8",
            ["NextDialogue"] = 10129005,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5DB8",
            },
        [10129005] = {
            ["Content"] = "虽然对他个人来说非常悲惨，但，又能怎么样呢，死亡迟早会拥抱他，现在这样算是最不坏的结果了。",
            ["ContentJP"] = "あいつにとっては確かに悲劇だろうが……でも、どだしようもないだろ。死ぬのは時間の問題だし、最悪の結果を免れたわけだしな。",
            ["DialogueId"] = 10129005,
            ["GUID"] = "195B5DE2",
            ["NextDialogue"] = 10129006,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5DE2",
            },
        [10129006] = {
            ["Content"] = "别有压力，这也不是你的错，没有人有错。",
            ["ContentJP"] = "気にすんな、これはお前のせいじゃない。誰も悪くなんかないんだ。",
            ["DialogueId"] = 10129006,
            ["GUID"] = "195B5E0C",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5E0C",
            },
        [10129008] = {
            ["Content"] = "你这个问题就和喝了酒会怎么样似的，何必多问呢？我给你的答案只能是他会像是喝了一杯烈酒一样，剧痛之后安眠无忧。",
            ["ContentJP"] = "お前の質問、酒を飲んだらどうなるかって聞いてるのと同じだ。答えは簡単だ。あいつはな、リキュールを一杯飲んだ時のように、一瞬の痛みのあと、何も気にせずぐっすり眠るのさ。",
            ["DialogueId"] = 10129008,
            ["GUID"] = "195B5E60",
            ["NextDialogue"] = 10129009,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5E60",
            },
        [10129009] = {
            ["Content"] = "哈哈，每次喝了酒我都觉得自己说话像是艺术家而不是帝国的士兵，我喜欢这种能够面对坏事还自我夸赞的心情。但希望你永远不要懂这种感觉。",
            ["ContentJP"] = "はは、酒を飲むと、毎回自分の話っぷりが芸術家みたいだと感じることがあるんだ。帝国の兵士じゃなくてな。悪いことに直面していながら、自分を褒めたくなる心境、結構好きなんだ。でも、頼むから、お前にはこの気持ち、わかってほしくないな。",
            ["DialogueId"] = 10129009,
            ["GUID"] = "195B5E8A",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101290/195B5E8A",
            },
        [10129101] = {
            ["Content"] = "原来都是恩里克……",
            ["ContentJP"] = "まさか、ヘンリックだったとは……",
            ["DialogueId"] = 10129101,
            ["GUID"] = "195B6DA2",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6DA2",
            },
        [10129102] = {
            ["Content"] = "我还以为之前冰湖城的秽蚀者数量变少是奇迹，结果是恩里克……鉴于他已经死了，军团不会追究他，但以后怎么办呢……",
            ["ContentJP"] = "アイスレイク城の穢蝕者が減ったのは奇跡だと思ってたけど、ヘンリックの仕業だったんだな……あいつはもう死んだし、軍団も追及しないだろうけどさ。だが、これからどうすれば……",
            ["DialogueId"] = 10129102,
            ["GUID"] = "195B6DCC",
            ["NextOptions"] = {
                [1] = 101291021,
                [2] = 101291022,
                [3] = 101291023,
                },
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6DCC",
            },
        [10129104] = {
            ["Content"] = "是啊，又能追究什么呢，修普诺斯之家已经空了，并且也有合法的继承人，总不能真的把那个宅子一把火烧了。",
            ["ContentJP"] = "ああ、何を追及するってんだ？ヒュプノスの家はもう空っぽだし、合法的な後継者もいる。さすがに家を火で燃やすなんてこと、できるわけねぇだろ。",
            ["DialogueId"] = 10129104,
            ["GUID"] = "195B6E20",
            ["NextDialogue"] = 10129105,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6E20",
            },
        [10129105] = {
            ["Content"] = "但说实话，我是觉得军团要感谢他，应该给他发奖。否则那么多秽蚀者，每个都引发事故的话，我不敢想。",
            ["ContentJP"] = "正直言うと、軍団はあいつに感謝すべきだろうな。むしろ賞でもあげるべきだよ。だって、あんなにたくさんの穢蝕者が全員暴走したら……考えただけでゾッとする。",
            ["DialogueId"] = 10129105,
            ["GUID"] = "195B6E4A",
            ["NextDialogue"] = 10129106,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6E4A",
            },
        [10129106] = {
            ["Content"] = "听说他是想研究药物阻止秽蚀，唉，要是真的成功就好了，能够让什么卡戎生来背负着罪孽的说法少上一些。",
            ["ContentJP"] = "聞いた話だと、あいつは薬で穢蝕を防ごうとしてたらしいな。あぁ、成功してたらよかったのにな。そしたら、カロンみたいに生まれつき罪を背負った存在なんて話も、少しは減ったかもしれないのに。",
            ["DialogueId"] = 10129106,
            ["GUID"] = "195B6E74",
            ["NextDialogue"] = 10129107,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6E74",
            },
        [10129107] = {
            ["Content"] = "嗯……不少索拉之民之所以能对卡戎们的境遇视而不见，也是靠着这个说法自我催眠吧——生来有罪的种族，吃点苦也是活该的。",
            ["ContentJP"] = "うん……ソラの民がカロンたちの境遇を無視できるのも、そういう言い訳で自分を納得させてるからだろうな。「生まれつき罪を背負った種族だから、苦しいのは当然だ」ってな。",
            ["DialogueId"] = 10129107,
            ["GUID"] = "195B6E9E",
            ["NextDialogue"] = 10129108,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6E9E",
            },
        [10129108] = {
            ["Content"] = "唉，我也没有立场去说他们，比起同是索拉之民，又为了卡戎丧命的恩里克，我又做了什么呢……",
            ["ContentJP"] = "はぁ、俺もあいつらに文句言える立場じゃないよな。俺もソラの民だ。カロンのために命を落としたヘンリックと比べて、俺は一体何をしたって言うんだ……",
            ["DialogueId"] = 10129108,
            ["GUID"] = "195B6EC8",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6EC8",
            },
        [10129110] = {
            ["Content"] = "赛琪……？啊你是说之前和你在一起的那个孩子……军团没有太在意她，毕竟每天全国这样的秽蚀者相关的事件不少。",
            ["ContentJP"] = "サイキ……？あぁ、前にお前と一緒にいたあの子のことか。軍団はあんまり気にしてないみたいだな。何せ、穢蝕者関連の事件は毎日山ほど怒ってるんだから。",
            ["DialogueId"] = 10129110,
            ["GUID"] = "195B6F1C",
            ["NextDialogue"] = 10129111,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6F1C",
            },
        [10129111] = {
            ["Content"] = "第六军团的黎瑟长官也表示这起秽蚀虽然规模要更大，也牵扯了非法行医，但不需要深究。",
            ["ContentJP"] = "第六軍団のリズム長官も言ってたよ。今回の穢蝕者の件、規模は大きいし、違法な医療行為も関わってるけど、これ以上追及する必要はないってさ。",
            ["DialogueId"] = 10129111,
            ["GUID"] = "195B6F46",
            ["NextDialogue"] = 10129112,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6F46",
            },
        [10129112] = {
            ["Content"] = "否则，在现场的人……有你吧，免不了要被带去军团审问，那时候发生什么就未可知了。",
            ["ContentJP"] = "でなけりゃ、現場にいたお前は、今頃軍団に連れて行かれて、何されてたかわからなかっただろうな。",
            ["DialogueId"] = 10129112,
            ["GUID"] = "195B6F70",
            ["NextDialogue"] = 10129113,
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6F70",
            },
        [10129113] = {
            ["Content"] = "唉，你也节哀，很不好受吧。我这杯酒，敬她。",
            ["ContentJP"] = "はぁ、お前も気を落とすなよ、つらいだろうけど。この酒を、彼女に捧げるよ。",
            ["DialogueId"] = 10129113,
            ["GUID"] = "195B6F9A",
            ["SpeakNpcId"] = 200095,
            ["VoiceName"] = "voice/$Locale$/story/1002/101291/195B6F9A",
            },
        [10129201] = {
            ["Content"] = "是去了格雷姆废矿？身手不错啊。",
            ["ContentJP"] = "グルビューム廃坑に行ったの？案外お強いのね。",
            ["DialogueId"] = 10129201,
            ["GUID"] = "195B7001",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7001",
            },
        [10129202] = {
            ["Content"] = "怎么回事？去了格雷姆废矿？那能活下来算你们运气不错。话说回来，这恩里克也越来越神经质了。",
            ["ContentJP"] = "え？グルビューム廃坑に行ったの？生きて帰って来るなんて、運が良いのね。そういえば、最近ヘンリックの様子がおかしいんだよね……",
            ["DialogueId"] = 10129202,
            ["GUID"] = "195B7002",
            ["NextOptions"] = {
                [1] = 101292021,
                [2] = 101292022,
                [3] = 101292023,
                },
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7002",
            },
        [10129204] = {
            ["Content"] = "那里很危险呀，说是废矿，但里面还有很多秽兽的吧。我曾经委托人去查过，都被里面的一个大怪物给堵回来了。",
            ["ContentJP"] = "ありゃ危険な場所よ。廃坑とは言っても、<Default note=\"text:エジュウ\">穢獣</>がうじゃうじゃいるし……昔、調査を依頼したんだけど、中にいるデカブツに誰一人勝てなくて……",
            ["DialogueId"] = 10129204,
            ["GUID"] = "195B7004",
            ["NextDialogue"] = 10129205,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7004",
            },
        [10129205] = {
            ["Content"] = "啊？你说你们打败了它？这……该说是你们身手好还是命大呢？",
            ["ContentJP"] = "え？あれを……倒した？それはそれは……さすがだと言えばばいいのか、運がよかったと言えばいいのか……",
            ["DialogueId"] = 10129205,
            ["GUID"] = "195B7005",
            ["NextDialogue"] = 10129206,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7005",
            },
        [10129206] = {
            ["Content"] = "嗯……有空的话，要不要我为你写一篇专访？标题就叫《冉冉升起的新兴狩月人——{nickname}》，还能帮你提高知名度呢。",
            ["ContentJP"] = "ふむ……良かったら今度、あなたの特集記事を書かせてくれない？タイトルは……『期待の新星！月狩り人——{nickname}』なんてどう？知名度も上がるし、あなたにとって悪い話ではないでしょ？",
            ["DialogueId"] = 10129206,
            ["GUID"] = "195B7006",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7006",
            },
        [10129208] = {
            ["Content"] = "该怎么说呢，他之前也是这样一板一眼，不和人说笑。我想采访他写报道，被他拒绝，想和他的住客搭话，也被他赶走。",
            ["ContentJP"] = "無愛想なのも、インタビューを断られるのも、他の宿泊客を取材しようとして追い出されるのもいつも通りだけど……",
            ["DialogueId"] = 10129208,
            ["GUID"] = "195B7008",
            ["NextDialogue"] = 10129209,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7008",
            },
        [10129209] = {
            ["Content"] = "但他之前说话也不像是这种冷冰冰的，想要杀人一样。可能他最近也有什么心事吧，唉，这个年头，谁又没点烦心事呢。",
            ["ContentJP"] = "なんと言うか……最近、妙に殺気立ってる気がするのよね。何か悩み事でもあるんじゃないかしら？今時、誰だって何かしら抱えてるものよ。",
            ["DialogueId"] = 10129209,
            ["GUID"] = "195B7009",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B7009",
            },
        [10129211] = {
            ["Content"] = "我？哎呀我就是一个写点东西挣钱的，管我叫大记者安苏兹（Ansuz）就好。",
            ["ContentJP"] = "私？そうね……噂話を金に変える「記者」をやってるわ。アンスーズと呼んでちょうだい。",
            ["DialogueId"] = 10129211,
            ["GUID"] = "195B700B",
            ["NextDialogue"] = 10129212,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B700B",
            },
        [10129212] = {
            ["Content"] = "我一直在冰湖城里搜罗消息，写成文章，印刷报纸，带来欢乐。",
            ["ContentJP"] = "アイスレイク城で記事になる情報を集め、新聞として民に喜びをもたらしているの。",
            ["DialogueId"] = 10129212,
            ["GUID"] = "195B700C",
            ["NextDialogue"] = 10129213,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B700C",
            },
        [10129213] = {
            ["Content"] = "怎么一副不信的样子，来，拿着，今天的《冰湖城早报》。这份免费，喜欢再买。",
            ["ContentJP"] = "その顔……全然信じてないね。ほら、本日の「アイスレイク新聞」よ。これはタダであげるわ。気に入ったら次号からは自分で買ってね。",
            ["DialogueId"] = 10129213,
            ["GUID"] = "195B700D",
            ["NextDialogue"] = 10129214,
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B700D",
            },
        [10129214] = {
            ["Content"] = "当然，如果你有什么新闻线索的话，也可以来找我，免费给你换一份。",
            ["ContentJP"] = "もちろん、もし話題性のある噂を聞いたら、なんでも教えて。報酬として、無料で新聞をあげるから。",
            ["DialogueId"] = 10129214,
            ["GUID"] = "195B700E",
            ["SpeakNpcId"] = 200092,
            ["VoiceName"] = "voice/$Locale$/story/1002/101292/195B700E",
            },
        [10129301] = {
            ["Camera"] = "266.991333,-1202.721191,114.503418,0.000067,-0.398835,93.80304,30.0,560.390686,false,DoNotOverride,1.2",
            ["DialogueId"] = 10129301,
            ["FinalCamera"] = "246.92688,-1204.056152,114.503418,0.000067,-0.398835,93.80304,30.0,560.390686,false,DoNotOverride,1.2",
            ["GUID"] = "195B8E72",
            ["LookAt"] = {
                [1] = "100001:p(101293LookAt1)",
                [2] = "200002:p(101293LookAt1)",
                },
