        [10129701] = {
            ["Camera"] = "98.882812,336.099609,13.861816,0.00006,13.998199,-124.392242,15.0,100000.0,false,Disable,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["DialogueId"] = 10129701,
            ["FinalCamera"] = "176.5,102.359375,-7.201416,0.000064,19.197878,-143.98999,15.0,100000.0,false,Disable,2.8",
            ["GUID"] = "195BD012",
            ["ToFinalCameraBlendTime"] = 3,
            },
        [10129801] = {
            ["Content"] = "小贼在前面！糟了……他好像和秽兽打起来了！",
            ["ContentJP"] = "泥棒はっけーん！あっ……穢獣と戦ってるよ！！",
            ["DialogueId"] = 10129801,
            ["GUID"] = "195BD013",
            ["NextDialogue"] = 10129802,
            ["SpeakNpcId"] = 200011,
            ["VoiceName"] = "voice/$Locale$/story/1002/101298/195BD013",
            },
        [10129802] = {
            ["Content"] = "赶跑秽兽，然后制服他吧。",
            ["ContentJP"] = "穢獣を撃退して、彼を捕まえよう。",
            ["DialogueId"] = 10129802,
            ["GUID"] = "195BD014",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101298/195BD014",
            },
        [10129901] = {
            ["Content"] = "那栋宅子常常在深夜传来哭声，偶尔还会飘出奇怪的味道。",
            ["ContentJP"] = "あの屋敷、夜中によく泣き声が聞こえるんだ。たまに変な匂いまで漂ってくるんだぜ。",
            ["DialogueId"] = 10129901,
            ["GUID"] = "195BD015",
            ["VoiceName"] = "voice/$Locale$/story/1002/101299/195BD015",
            },
        [10130001] = {
            ["Content"] = "恩里克的事与我无关。但如果他真的有什么问题……我担心赛琪的安全。",
            ["ContentJP"] = "ヘンリックのことは、{性别:僕|私}には関係ない。でも……もし本当に何かあるんなら、サイキのことがちょっと心配{性别:だ|だよ}。",
            ["DialogueId"] = 10130001,
            ["GUID"] = "195BD016",
            ["NextDialogue"] = 10106325,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101300/195BD016",
            },
        [10130101] = {
            ["Camera"] = "17.943359,4617.524414,902.814453,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0",
            ["Content"] = "如果真的得到了{性别：他|她}——也就是和鸣之力的持有者，您打算如何处置？",
            ["ContentJP"] = "もし{性别:彼|彼女}を——レゾナンスの所有者を手中に収めたとして、如何なさるおつもりですか？",
            ["DialogueId"] = 10130101,
            ["Duration"] = 8,
            ["FinalCamera"] = "37.016602,4939.133301,642.138672,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0",
            ["GUID"] = "195BD017",
            ["NextDialogue"] = 10130102,
            ["SpeakNpcId"] = 100006,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/101301/195BD017",
            },
        [10130102] = {
            ["Content"] = "完全觉醒的和鸣之力可以对一切“骸”施加干预……但这种力量完全依赖于持有者本人的意志。",
            ["ContentJP"] = "「レゾナンス」の力が完全に覚醒すれば、あらゆる「骸」に対して干渉が可能となります……ですが、その力を振るえるかどうかは、持ち主の意志に懸かっているんですよ。",
            ["DialogueId"] = 10130102,
            ["Duration"] = 8,
            ["GUID"] = "195BD018",
            ["NextDialogue"] = 10130103,
            ["SpeakNpcId"] = 100006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101301/195BD018",
            },
        [10130103] = {
            ["Camera"] = "-1576.924561,1990.549316,316.099609,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2",
            ["Content"] = "也就是说，除非{性别：他|她}本人自愿协助，否则得到{性别：他|她}对帝国来说并无意义，甚至可能成为祸端。就像当年……",
            ["ContentJP"] = "言い換えれば、ご本人が自ら望まぬ限り——帝国にとってその力は、無用どころか……かえって災いを招く火種となるでしょう。あのときのように、ね。",
            ["DialogueId"] = 10130103,
            ["Duration"] = 8,
            ["FinalCamera"] = "-1587.533691,2001.532227,318.089844,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2",
            ["GUID"] = "195BD019",
            ["NextDialogue"] = 10130104,
            ["SpeakNpcId"] = 100006,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101301/195BD019",
            },
        [10130104] = {
            ["Camera"] = "-40.981445,48.569336,104.802734,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0",
            ["Content"] = "那就和当年一样抹除掉。无论如何，这份力量不能落入帝国之外，尤其是艾利西安。好了，另一个坏消息呢？",
            ["ContentJP"] = "ならば——あのときと同じように、始末すればいいだけのこと。どんな手段を使おうと、この力が帝国以外へ渡るのは許されないわ。特に……エリュシオンにはね。……それで、もう一つの報告は？",
            ["DialogueId"] = 10130104,
            ["Duration"] = 10,
            ["FinalCamera"] = "-42.826172,89.025879,102.189453,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0",
            ["GUID"] = "195BD020",
            ["NextDialogue"] = 10108013,
            ["SpeakNpcId"] = 100005,
            ["TalkActionId"] = {
                [1] = "100005:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101301/195BD020",
            },
        [10130201] = {
            ["Content"] = "“牵念之花”……是花店！诶？！难道他准备去约会？",
            ["ContentJP"] = "「フローリスト・リメンブランス」……って、花屋じゃん！！まさか、デートにでも行くの？",
            ["DialogueId"] = 10130201,
            ["GUID"] = "195BD021",
            ["NextDialogue"] = 10130202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101302/195BD021",
            },
        [10130202] = {
            ["Content"] = "我们坐对面等一会儿吧！",
            ["ContentJP"] = "向かいで少し様子を見よ！",
            ["DialogueId"] = 10130202,
            ["GUID"] = "195BD022",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101302/195BD022",
            },
        [10130301] = {
            ["Camera"] = "216.478516,-137.633301,117.546875,0.000164,-6.198915,127.211983,35.0,407.218628,false,DoNotOverride,4.0",
            ["Content"] = "他出来了！",
            ["ContentJP"] = "出てきたよ！",
            ["DialogueId"] = 10130301,
            ["GUID"] = "195BD023",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:p(LC_EnterFlow)",
                },
            ["NextDialogue"] = 10130302,
            ["Scripts"] = "MoveTo{ActorId{200002},MoveSpeed{220},TargetPoint{\"P1190930Bai1\"}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD023",
            },
        [10130302] = {
            ["Camera"] = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0",
            ["Content"] = "二位要喝点什么吗？",
            ["ContentJP"] = "おふたりさん、何か注文されます？",
            ["DialogueId"] = 10130302,
            ["GUID"] = "195BD024",
            ["NextDialogue"] = 10130303,
            ["Scripts"] = "MoveTo{ActorId{200097},MoveSpeed{80},TargetPoint{\"P1190930Boy1\"}}",
            ["SpeakNpcId"] = 200097,
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD024",
            },
        [10130303] = {
            ["Camera"] = "105.118164,-51.828613,93.718262,0.0,-2.999962,129.999985,30.0,118.813644,false,Manual,4.0",
            ["Content"] = "不喝不喝，我们就坐一会儿，看看风景！你看今晚太阳多好啊，嘿嘿……",
            ["ContentJP"] = "いらないいらない。ちょっと風景を眺めてるだけだから。ほら、今晩のお日様、すっごくピカピカでしょ！",
            ["DialogueId"] = 10130303,
            ["GUID"] = "195BD025",
            ["NextDialogue"] = 10130304,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD025",
            },
        [10130304] = {
            ["Camera"] = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0",
            ["Content"] = "看风景才要喝点什么！我们店有各式咖啡，还有冰湖城特产北风莓果汁！对了，最新的鲱鱼罐头味浓汤不来品尝一下吗！",
            ["ContentJP"] = "景色見るなら、やっぱり何か飲まなきゃ！うちにはいろんな種類のコーヒーに、アイスレイク城名物の「アイスベリージュース」もありますよ！あ、あと最新作の「ニシンの缶詰風スープ」、濃厚でオススメです！ちょっと試してみませんか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 10130304,
            ["GUID"] = "195BD026",
            ["NextDialogue"] = 10130305,
            ["SpeakNpcId"] = 200097,
            ["TalkActionId"] = {
                [1] = "200097:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD026",
            },
        [10130305] = {
            ["Camera"] = "126.273438,-640.34082,115.856201,0.000007,0.0,89.999985,20.0,118.813644,false,Manual,4.0",
            ["Content"] = "不了，我们还有事——等下，恩里克呢？",
            ["ContentJP"] = "いや、結構。今ちょっと忙しいから……あれ、ヘンリックさんは？",
            ["DialogueId"] = 10130305,
            ["GUID"] = "195BD027",
            ["NextDialogue"] = 10130306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD027",
            },
        [10130306] = {
            ["Camera"] = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,169.724716,false,Manual,4.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "呜呜，好像跟丢了……",
            ["ContentJP"] = "うっ、見失ってしまった……",
            ["DialogueId"] = 10130306,
            ["FinalCamera"] = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,680.897827,false,Manual,1.2",
            ["GUID"] = "195BD028",
            ["LookAt"] = {
                [1] = "200002:p(LC_EnterFlow)",
                [2] = "100001:p(LC_EnterFlow)",
                },
            ["NextDialogue"] = 10130307,
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD028",
            },
        [10130307] = {
            ["Camera"] = "-31.876953,-170.957031,169.342773,0.0,-14.000125,51.202343,30.0,155.608383,false,Manual,3.0",
            ["Content"] = "……和花店老板打听一下，碰碰运气吧。",
            ["ContentJP"] = "……花屋の店長に聞いてみよう。何か情報がつかめるかも。",
            ["DialogueId"] = 10130307,
            ["GUID"] = "195BD029",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101303/195BD029",
            },
        [10130401] = {
            ["Camera"] = "-137.371094,-123.811035,229.291016,0.000012,-12.600093,90.599869,16.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（火炉的炉体高大，火焰早已熄灭，但里面的炉灰似乎证明了它近期被使用过。）",
            ["ContentJP"] = "（大きな暖炉の火はかなり前に消えたようだ。しかし最近使用した形跡はあるな……）",
            ["DialogueId"] = 10130401,
            ["DisableMouth"] = 1,
            ["FinalCamera"] = "-132.40625,-283.590576,87.898438,0.000034,13.599972,91.399513,16.000004,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "195BD030",
            ["LookAt"] = {
                [1] = "200021:n(200021)",
                },
            ["NextDialogue"] = 10130402,
            ["Scripts"] = "TurnTo{_delay{1},TurnToDescription{\"200021:p(-180)\"}}",
