                [1] = "200021:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/101304/195BD030",
            },
        [10130402] = {
            ["Content"] = "这么大个的炉子，既不是拿来做饭的，也不是拿来取暖的。它……是拿来烧什么的？……该不会……",
            ["ContentJP"] = "こんなデカい暖炉、料理用でもなさそうだし、暖をとるにしては大げさすぎるよな？……何焼いてたんだろ？まさか……",
            ["DialogueId"] = 10130402,
            ["GUID"] = "195BD031",
            ["NextOptions"] = {
                [1] = 101089041,
                },
            ["SpeakNpcId"] = 200021,
