            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1002/101306/195BD037",
            },
        [10130604] = {
            ["Content"] = "秽兽异常凶险，虽然它现在停止了攻击，但很可能只是暂时休眠。你们尽快去城内避难，这里交给卫戍部队应付。",
            ["ContentJP"] = "穢獣は極めて危険です。今は動きを止めていますが、おそらく一時的に休眠しているだけですから。あなたたちは急いで市内へ避難してください。ここは警備部隊が引き受けます。",
            ["DialogueId"] = 10130604,
            ["GUID"] = "195BD038",
            ["NextDialogue"] = 10113038,
            ["SpeakNpcId"] = 100304,
            ["TalkActionId"] = {
                [1] = "100304:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101306/195BD038",
