        [10130802] = {
            ["Camera"] = "-137.248779,-3.609863,123.338379,0.000239,6.000567,-59.584656,35.0,167.968307,false,Manual,7.759425",
            ["Content"] = "嗯，这本笔记也提到了火药，似乎是用来<H>爆破那些黄色晶体</>的。",
            ["ContentJP"] = "うん、このノートにも火薬の話が…どうやら<H>黄色結晶を爆破する</>のに使うらしい。",
            ["DialogueId"] = 10130802,
            ["Duration"] = 10,
