        [10130803] = {
            ["Camera"] = "269.530029,368.111084,118.398438,0.000066,-2.199314,-128.599228,30.0,619.991211,false,Manual,1.2",
            ["Content"] = "那我们也带上吧！冒险就是要做足准备嘛！",
            ["ContentJP"] = "じゃあ私たちも持っていこう！冒険は準備が命だもの！",
            ["DialogueId"] = 10130803,
            ["Duration"] = 10,
            ["FinalCamera"] = "257.802246,377.4729,118.398438,0.000066,-2.199314,-128.599228,30.0,274.965851,false,Manual,1.2",
            ["GUID"] = "195BD044",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/101308/195BD044",
            },
        [10130901] = {
            ["Content"] = "啊，路被那些恶心的黄色晶刺堵住啦！",
            ["ContentJP"] = "うわ、気持ち悪い黄色結晶のトゲに道を塞がれてる！",
            ["DialogueId"] = 10130901,
            ["GUID"] = "195BD045",
            ["NextDialogue"] = 10130902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101309/195BD045",
            },
        [10130902] = {
            ["Content"] = "刚才那些火药桶应该能派上用场了。",
            ["ContentJP"] = "さっき見つけた火薬樽が役に立ちそう{性别:だね|ね}。",
            ["DialogueId"] = 10130902,
            ["GUID"] = "195BD046",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101309/195BD046",
            },
        [10130903] = {
            ["Content"] = "（离远一些，<H>用子弹射击</>引爆它吧。）",
            ["ContentJP"] = "（離れてから<H>銃で射撃して</>起爆しょう。）",
            ["DialogueId"] = 10130903,
            ["GUID"] = "195BD047",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101309/195BD047",
            },
        [10131001] = {
            ["Content"] = "成功了！……啊，你们要不要紧？魔王大人你怎么蹲在地上，受伤了吗？",
            ["ContentJP"] = "成功！…あれ？皆平気？魔王様はどうして地面にしゃがんでるの？ケガでもした？",
            ["DialogueId"] = 10131001,
            ["GUID"] = "195BD048",
            ["NextDialogue"] = 10131002,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD048",
            },
        [10131002] = {
            ["Content"] = "啊？！没、没事，区区区区爆炸而已！我、我是在勘探地形，嘿嘿……",
            ["ContentJP"] = "はっ？！ べ、別に！ここここんな爆発なんてへっちゃらさ！地形調査してただけだぞ、えへへ……",
            ["DialogueId"] = 10131002,
            ["GUID"] = "195BD049",
            ["NextDialogue"] = 10131003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD049",
            },
        [10131003] = {
            ["Content"] = "嘘！",
            ["ContentJP"] = "しーッ！",
            ["DialogueId"] = 10131003,
            ["GUID"] = "195BD050",
            ["NextDialogue"] = 10131004,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD050",
            },
        [10131004] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "ガオウーー",
            ["DialogueId"] = 10131004,
            ["GUID"] = "195BD051",
            ["NextDialogue"] = 10131005,
            ["SpeakNpcName"] = "MESSAGE_TITLE_LOADING_14_PC",
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD051",
            },
        [10131005] = {
            ["Content"] = "……矿坑深处好像有什么动静？",
            ["ContentJP"] = "…鉱山の奥で何か音が？",
            ["DialogueId"] = 10131005,
            ["GUID"] = "195BD052",
            ["NextDialogue"] = 10131006,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD052",
            },
        [10131006] = {
            ["Content"] = "这么说来，刚刚的笔记还写到，废矿里可能有一种特别的秽兽出没……大家留意些，不要落单。",
            ["ContentJP"] = "そういえばさっきのノートに、廃坑には特別な穢獣がいると書いてあった……皆、離れないで進もう。",
            ["DialogueId"] = 10131006,
            ["GUID"] = "195BD053",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101310/195BD053",
            },
        [10131101] = {
            ["Content"] = "快看，中间那块大晶石在发光诶！难道里面有我们要找的群星绮晶？",
            ["ContentJP"] = "見て！あの光ってるデッカイ結晶！まさか私たちが探してた群星のジェムがその中に？",
            ["DialogueId"] = 10131101,
            ["GUID"] = "195BD054",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101311/195BD054",
            },
        [10131201] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "ガオウーー",
            ["DialogueId"] = 10131201,
            ["GUID"] = "195BD055",
            ["NextDialogue"] = 10131202,
            ["SpeakNpcName"] = "MESSAGE_TITLE_LOADING_14_PC",
            ["VoiceName"] = "voice/$Locale$/story/1002/101312/195BD055",
            },
        [10131202] = {
            ["Content"] = "是刚才那个声音！",
            ["ContentJP"] = "さっきの声だ！",
            ["DialogueId"] = 10131202,
            ["GUID"] = "195BD056",
            ["NextDialogue"] = 10131203,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101312/195BD056",
            },
        [10131203] = {
            ["Content"] = "哇啊——怎么突然冲上来这么多秽兽！……呃……呃呃……",
            ["ContentJP"] = "ぎゃああっーー いきなり穢獣の群れが襲ってきた！…うっ…ううっ…",
            ["DialogueId"] = 10131203,
            ["GUID"] = "195BD057",
            ["NextDialogue"] = 10131204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101312/195BD057",
            },
        [10131204] = {
            ["Content"] = "也许是被爆炸声引过来的？",
            ["ContentJP"] = "爆破音に引き寄せられたの…？",
            ["DialogueId"] = 10131204,
            ["GUID"] = "195BD058",
            ["NextDialogue"] = 10120102,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101312/195BD058",
            },
        [10131301] = {
            ["Camera"] = "775.768799,-65.358398,179.694336,0.000056,-1.399676,-179.401596,20.0,100000.0,false,Disable,2.8",
            ["Content"] = "亮闪闪魔弹——纯白的救赎！轰！！",
            ["ContentJP"] = "煌きの魔弾――純白の救済！ドッカ――ン！！",
            ["DialogueId"] = 10131301,
            ["GUID"] = "195BD059",
            ["NextDialogue"] = 10131302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD059",
            },
        [10131302] = {
            ["Content"] = "不用“轰”了，秽兽已经被消灭啦。",
            ["ContentJP"] = "「ドッカ――ン」はもう要らないよ。穢獣はとっくに倒されたのよ。",
            ["DialogueId"] = 10131302,
            ["GUID"] = "195BD060",
            ["NextDialogue"] = 10131303,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD060",
            },
        [10131303] = {
            ["Content"] = "噢，是吗！快让我鉴赏一下本大人伟大的战利品——",
            ["ContentJP"] = "ほんとかい！ じゃあ早く魔王サマの偉大なる戦利品を鑑賞させ――",
            ["DialogueId"] = 10131303,
            ["GUID"] = "195BD061",
            ["NextDialogue"] = 10131304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD061",
            },
        [10131304] = {
            ["Content"] = "卡米拉说过，群星绮晶是“流转着星云的紫色晶体”……这个似乎只是常见的银辉石而已。",
            ["ContentJP"] = "カミラが言ってた「星雲が宿っている」群星のジェム…これはただの銀輝石みたいね。",
            ["DialogueId"] = 10131304,
            ["GUID"] = "195BD062",
            ["NextDialogue"] = 10131305,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD062",
            },
        [10131305] = {
            ["Content"] = "呜……没意思。",
            ["ContentJP"] = "ちぇっ… つまんない",
            ["DialogueId"] = 10131305,
            ["GUID"] = "195BD063",
            ["NextDialogue"] = 10131307,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD063",
            },
        [10131306] = {
            ["Content"] = "<H>银辉石</>吗……我小时候听隔壁的裁缝叔叔说过，这种矿物可以拿来做颜料或者<H>染料</>。",
            ["ContentJP"] = "<H>銀輝石</>か…子供の頃、隣の仕立て屋おじさんが、これを顔料や<H>染料</>に加工すると話してた。",
            ["DialogueId"] = 10131306,
            ["GUID"] = "195BD064",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD064",
            },
        [10131307] = {
            ["Content"] = "那小仆从有空拿给<H>铁匠皎皎前辈</>瞧瞧吧！至于现在，让我继续带领你们向矿坑深处进发！",
            ["ContentJP"] = "じゃあ下僕！暇な時に<H>鍛冶屋の先輩</>に見せておいで！今は魔王様についてこい、鉱坑の奥へ！",
            ["DialogueId"] = 10131307,
            ["GUID"] = "195BD065",
            ["NextDialogue"] = 10131308,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD065",
            },
        [10131308] = {
            ["Content"] = "呵呵……遵命，魔王大人。",
            ["ContentJP"] = "ふふ…かしこまりました、魔王様。",
            ["DialogueId"] = 10131308,
            ["GUID"] = "195BD066",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101313/195BD066",
            },
        [10131401] = {
            ["Content"] = "这些黄色晶刺里面，竟然还裹着这么多亮晶晶的石头呀！",
            ["ContentJP"] = "黄色結晶のトゲの中で、こんなキラキラした石が包まれていた！",
            ["DialogueId"] = 10131401,
            ["GUID"] = "195BD067",
            ["NextDialogue"] = 10131402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101314/195BD067",
            },
        [10131402] = {
            ["Content"] = "就像是被谁当成宝贝，小心翼翼地藏起来了一样……",
            ["ContentJP"] = "まるで誰かが宝物のように、大事に隠していたみたい......",
            ["DialogueId"] = 10131402,
            ["GUID"] = "195BD068",
            ["NextDialogue"] = 10131403,
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101314/195BD068",
            },
        [10131403] = {
            ["Content"] = "哼哼~赛琪该不会也偷藏了什么宝贝？",
            ["ContentJP"] = "ふふん～サイキも何か隠してるじゃない？",
            ["DialogueId"] = 10131403,
            ["GUID"] = "195BD069",
            ["NextDialogue"] = 10131404,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1002/101314/195BD069",
            },
        [10131404] = {
            ["Content"] = "嘿嘿……是秘密哦。",
            ["ContentJP"] = "えへへ......秘密よ。",
            ["DialogueId"] = 10131404,
            ["GUID"] = "195BD070",
            ["SpeakNpcId"] = 200006,
            ["VoiceName"] = "voice/$Locale$/story/1002/101314/195BD070",
            },
