        [11010103] = {
            ["Camera"] = "138.929688,18.707031,107.624329,0.000043,-26.202394,152.990067,28.0,179.473755,false,Manual,10.963819",
            ["Content"] = "<W>你的血肉之躯因窒息而悸动，疼痛叩击着你深处最隐秘的渴望。</>",
            ["ContentJP"] = "<W>血がざわつき、鋭い痛みが奥底に眠る渇望を呼び覚まそうとしている。</>",
            ["DialogueId"] = 11010103,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "138.929688,18.707031,131.753906,0.000043,-26.202394,152.990067,28.0,179.473755,false,Manual,10.963819",
            ["GUID"] = "1B900906",
            ["NextDialogue"] = 11010104,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900906",
            },
        [11010104] = {
            ["Camera"] = "80.007812,123.242188,115.345276,0.000047,-32.004726,-160.221619,28.0,121.418312,false,Manual,10.963819",
            ["Content"] = "（又是这个声音……）",
            ["ContentJP"] = "またこの声……",
            ["DialogueId"] = 11010104,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "65.46875,118.03125,105.693848,0.000047,-32.004726,-160.221619,28.0,121.418312,false,Manual,10.963819",
            ["GUID"] = "1B900930",
            ["NextOptions"] = {
                [1] = 11010105,
                },
            ["RelatedWikiId"] = {
                [1] = 204001,
                },
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900930",
            },
        [11010105] = {
            ["Content"] = "（够了。从我的脑子里滚出去。）",
            ["ContentJP"] = "もういい。私の頭の中から出て{性别2:いけ|って}。",
            ["DialogueId"] = 11010105,
            ["GUID"] = "1B90095A",
            ["NextDialogue"] = 11010106,
            },
        [11010106] = {
            ["Camera"] = "-162.023438,188.144531,-14.760071,0.000057,25.19714,-32.413078,28.0,179.473755,false,Manual,10.963819",
            ["Content"] = "<W>杀了它。聆听它的哀嚎，沐浴它的血。拥抱这甜蜜的死亡。</>",
            ["ContentJP"] = "<W>殺しなさい。その悲鳴と血を一身に浴びながら、甘美なる死を存分に楽しむといい……</>",
            ["DialogueId"] = 11010106,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-313.984375,284.59375,-99.471802,0.000057,25.19714,-32.413078,28.0,179.473755,false,Manual,10.963819",
            ["GUID"] = "1B900984",
            ["NextOptions"] = {
                [1] = 11010107,
                [2] = 11010108,
                },
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/evilvo\"},PlayAs2D{true}}",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900984",
            },
        [11010107] = {
            ["Content"] = "（捂住耳朵。拼尽全力隔绝这奇怪的声音。）",
            ["ContentJP"] = "（耳を塞いで、得体の知れない声を全力で遮断する）",
            ["DialogueId"] = 11010107,
            ["GUID"] = "1B9009AE",
            },
        [11010108] = {
            ["Content"] = "（寻找离开这里的路。）",
            ["ContentJP"] = "（ここから抜け出す道を探す）",
            ["DialogueId"] = 11010108,
            ["GUID"] = "1B9009D8",
            },
        [11010116] = {
            ["Content"] = "（……总之，我必须逃离这里，逃离这如同附骨之疽的可怕念头。）",
            ["ContentJP"] = "（とにかく、ここから離れないと。このまま聞き続けていたら、頭がおかしくなりそう。）",
            ["DialogueId"] = 11010116,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B900B28",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900B28",
            },
        [11010117] = {
            ["Content"] = ".....{nickname2}，醒醒！",
            ["ContentJP"] = "……{nickname2}さん……聞こえますか！",
            ["DialogueId"] = 11010117,
            ["Duration"] = 3,
            ["GUID"] = "1B900B52",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110101/1B900B52",
            },
        [11010203] = {
            ["Content"] = "队长，你终于醒了！",
            ["ContentJP"] = "やっと目覚められて……心配しましたよ！",
            ["DialogueId"] = 11010203,
            ["Duration"] = 3,
            ["GUID"] = "1B90196E",
            ["NextDialogue"] = 11010204,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B90196E",
            },
        [11010204] = {
            ["Content"] = "那秽兽要不行了！干掉它，快！！",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>はすでに虫の息です！さあ、トドメを！！",
            ["DialogueId"] = 11010204,
            ["Duration"] = 3,
            ["GUID"] = "1B901998",
            ["NextDialogue"] = 11010205,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B901998",
            },
        [11010205] = {
            ["Content"] = "尤里安，跟我撤到后方去！您的伤口要裂开了！",
            ["ContentJP"] = "ジュリアンさんは後ろに下がっててください！傷口がまた開いてしまいますよ！",
            ["DialogueId"] = 11010205,
            ["Duration"] = 3,
            ["GUID"] = "1B9019C2",
            ["NextDialogue"] = 11010206,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B9019C2",
            },
        [11010206] = {
            ["Content"] = "我们要……相信{nickname2}。",
            ["ContentJP"] = "{nickname2}さんを……{性别2:彼|彼女}を信じましょう。",
            ["DialogueId"] = 11010206,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9019EC",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110102/1B9019EC",
            },
        [11010207] = {
            ["Camera"] = "-541.03125,57.806641,257.779175,0.000056,-14.399083,-25.188799,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "处理干净了……唔！",
            ["ContentJP"] = "やっと終わった……っ！",
