            },
        [11010309] = {
            ["Camera"] = "-31.5,-4.214844,98.260132,0.000095,10.799259,-24.393532,35.0,155.397324,false,Manual,22.0",
            ["Content"] = "作战地图标记出我们现在的位置附近有几间仓库。运气好的话，里面说不定会有急救箱。",
            ["ContentJP"] = "まだ手当てが行き届いていない負傷者がたくさんいるのに、止血剤も鎮痛剤も底をついてしまって……これ以上、犠牲者を増やすわけにはいきません。",
            ["DialogueId"] = 11010309,
            ["GUID"] = "1B902AD2",
            ["NextDialogue"] = 11010310,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{3.5},TargetPosition{\"-4824.253906,-1793.578125,399.504517,0.000149,-14.800787,8.606606,35.0,100000.0,false,Manual,22.0\"},duration{0}}\
}",
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902AD2",
            },
        [11010310] = {
            ["Camera"] = "-19.5,-9.617188,101.238037,0.000106,10.999233,-24.590504,35.000008,169.901962,false,Manual,22.0",
            ["Content"] = "我已经用光了所有凝血剂和镇痛剂，但还有几位伤员没有得到救治……他们的伤情已经耽误不得了。",
            ["ContentJP"] = "マップによれば、この近くに倉庫がいくつかあるんです。運が良ければ、医療物資が見つかるかもしれません。",
            ["DialogueId"] = 11010310,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
            ["FinalCamera"] = "-8.886719,-14.484375,103.508179,0.000106,10.999233,-24.590261,35.000008,169.901962,false,Manual,22.0",
            ["GUID"] = "1B902AFC",
            ["NextDialogue"] = 11010311,
            ["SpeakNpcId"] = 110005,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902AFC",
            },
        [11010311] = {
            ["Camera"] = "87.443359,-59.851562,132.342285,0.000173,-0.600893,160.005676,35.000008,196.017685,false,Manual,22.0",
            ["Content"] = "你留下，我去。",
            ["ContentJP"] = "私がいくよ。{性别2:君|あなた}はここにいて。",
            ["DialogueId"] = 11010311,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B902B26",
            ["NextDialogue"] = 11010312,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{110022},AnimationId{\"DisagreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902B26",
            },
        [11010312] = {
            ["Camera"] = "-147.375,86.609375,133.640381,0.000178,-1.801148,-38.594769,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "可，这是医务员的职责——",
            ["ContentJP"] = "ですが、これは医務官である私の役目で——",
            ["DialogueId"] = 11010312,
            ["FacialId"] = {
                [1] = "110005:Unacceptable01",
                },
            ["GUID"] = "1B902B50",
            ["NextDialogue"] = 11010313,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902B50",
            },
        [11010313] = {
            ["Camera"] = "87.443359,-59.851562,132.342285,0.000173,-0.600893,160.005676,35.000008,196.017685,false,Manual,22.0",
            ["Content"] = "留下。你身手不算好，路上的秽兽未必应付得来。我们就剩你一个医务员了，别死在这儿。",
            ["ContentJP"] = "強がらないで。{性别2:君|あなた}の実力じゃ、もし<Default note=\"text:エジュウ\">穢獣</>に遭遇したら危険すぎる。それに、もう医務官は{性别2:君|あなた}だけなんだから、{性别2:君|あなた}がいなくなったら、助かるはずの命も助からなくなるよ。",
            ["DialogueId"] = 11010313,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B902B7A",
            ["NextDialogue"] = 11010314,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902B7A",
            },
        [11010314] = {
            ["Camera"] = "-114.242188,52.828125,134.584595,0.000186,-2.000849,-30.397076,35.000008,203.938095,false,Manual,22.0",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11010314,
            ["Duration"] = 2,
            ["FinalCamera"] = "-79.822266,32.675781,133.191162,0.000186,-2.000849,-30.397076,35.000008,203.938095,false,Manual,22.0",
            ["GUID"] = "1B902BA4",
            ["NextDialogue"] = 11010315,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_End",
                [2] = "110022:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902BA4",
            },
        [11010315] = {
            ["Content"] = "明白了……我听从您的安排。",
            ["ContentJP"] = "わかりました……あなたの決断に従います。",
            ["DialogueId"] = 11010315,
            ["FacialId"] = {
                [1] = "110005:None",
                },
            ["GUID"] = "1B902BCE",
            ["NextDialogue"] = 11010316,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902BCE",
            },
        [11010316] = {
            ["Content"] = "对了，您的通讯器还完好吗？",
            ["ContentJP"] = "ところで、通信機はまだ使えますか？",
            ["DialogueId"] = 11010316,
            ["GUID"] = "1B902BF8",
            ["NextDialogue"] = 11010317,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902BF8",
            },
        [11010317] = {
            ["Camera"] = "103.357422,-46.015625,131.054077,0.000209,-0.60077,165.802734,35.0,189.147873,false,Manual,22.0",
            ["Content"] = "嗯，能用。",
            ["ContentJP"] = "うん、問題ないよ。",
            ["DialogueId"] = 11010317,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B902C22",
            ["NextDialogue"] = 11010318,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902C22",
            },
        [11010318] = {
            ["Camera"] = "-200.285156,169.671875,157.805542,0.000194,-7.601222,-43.996536,35.0,203.938095,false,Manual,22.0",
            ["Content"] = "好，那请您保持通讯状态，我们随时联络。",
            ["ContentJP"] = "分かりました。いつでも通信できるようにしておいてください。何かあればすぐ連絡を。",
            ["DialogueId"] = 11010318,
            ["GUID"] = "1B902C4C",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110103/1B902C4C",
            },
        [11010401] = {
            ["Content"] = "*的……这帮畜生！",
            ["ContentJP"] = "ぐっ、あんの……畜生どもめ！",
            ["DialogueId"] = 11010401,
            ["Duration"] = 3,
            ["GUID"] = "1B9039EA",
            ["NextOptions"] = {
                [1] = 11010402,
                [2] = 11010404,
                [3] = 11010406,
                },
            ["RelatedWikiId"] = {
                [1] = 204001,
                [2] = 201012,
                },
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B9039EA",
            },
        [11010402] = {
            ["Content"] = "伤还好吗？",
            ["ContentJP"] = "傷の具合はどう？",
            ["DialogueId"] = 11010402,
            ["GUID"] = "1B903A14",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 11010403,
            },
        [11010403] = {
            ["Content"] = "队长！我没事，还能动弹……嘶——",
            ["ContentJP"] = "隊長！大丈夫です、まだ動けま……っ——",
            ["DialogueId"] = 11010403,
            ["Duration"] = 3,
            ["GUID"] = "1B903A3E",
            ["NextDialogue"] = 11010408,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903A3E",
            },
        [11010404] = {
            ["Content"] = "是我没保护好你们。",
            ["ContentJP"] = "ごめん、私がもっと強ければ……",
            ["DialogueId"] = 11010404,
            ["GUID"] = "1B903A68",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 11010405,
            },
        [11010405] = {
            ["Content"] = "别，队长，你可别这么说。",
            ["ContentJP"] = "そ、そんなこと言わないでください！隊長は精一杯やったんですから！",
            ["DialogueId"] = 11010405,
            ["Duration"] = 3,
            ["GUID"] = "1B903A92",
            ["NextDialogue"] = 11010408,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903A92",
            },
        [11010406] = {
            ["Content"] = "在这儿骂谁呢？",
            ["ContentJP"] = "それって私のこと？",
            ["DialogueId"] = 11010406,
            ["GUID"] = "1B903ABC",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 11010407,
            },
        [11010407] = {
            ["Content"] = "除了神弃者那帮畜生，还能有谁？",
            ["ContentJP"] = "フォーセイクン同盟のやつらに決まってるでしょう！？",
            ["DialogueId"] = 11010407,
            ["Duration"] = 3,
            ["GUID"] = "1B903AE6",
            ["NextDialogue"] = 11010408,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903AE6",
            },
        [11010408] = {
            ["Content"] = "那帮丧尽天良的东西，竟然把秽兽当兵器用……<W>神弃者同盟</>的人简直和秽兽一样，都是怪物！",
            ["ContentJP"] = "あの外道ども、まさか<Default note=\"text:エジュウ\">穢獣</>を兵器として使うなんて……<W>フォーセイクン同盟</>の連中も<Default note=\"text:エジュウ\">穢獣</>と同じだ！全員化け物だ！",
            ["DialogueId"] = 11010408,
            ["Duration"] = 3,
            ["GUID"] = "1B903B10",
            ["NextDialogue"] = 11010409,
            ["RelatedWikiId"] = {
                [1] = 101004,
                },
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903B10",
            },
        [11010409] = {
            ["Content"] = "还有上头那些混蛋也是，一点儿他*的脑子都没有，这么多秽兽，给我们先遣队的作战手册里硬是一个字都没提到！",
            ["ContentJP"] = "上層部の連中もクソったれだ！あれだけ<Default note=\"text:エジュウ\">穢獣</>がいたってのに、俺たちのマニュアルには忠告の一つもありやしねぇ！",
            ["DialogueId"] = 11010409,
            ["Duration"] = 3,
            ["GUID"] = "1B903B3A",
            ["NextDialogue"] = 11010410,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903B3A",
            },
        [11010410] = {
            ["Content"] = "……对不住啊，你不太爱出声，还按着你听了这么多牢骚。",
            ["ContentJP"] = "……すみません。口数の少ない隊長に愚痴ばかり聞かせてしまって。",
            ["DialogueId"] = 11010410,
            ["Duration"] = 3,
            ["GUID"] = "1B903B64",
            ["NextDialogue"] = 11010411,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903B64",
            },
        [11010411] = {
            ["Content"] = "没事。发这么多牢骚，总比说不出话好。",
            ["ContentJP"] = "大丈夫だよ。何も言えないよりはマシだからね。",
            ["DialogueId"] = 11010411,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B903B8E",
            ["NextDialogue"] = 11010412,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903B8E",
            },
        [11010412] = {
            ["Content"] = "哈哈，队长啊，你还是这么会安慰人。",
            ["ContentJP"] = "ハハハ、相変わらず、人を慰めるのがお上手ですな。",
            ["DialogueId"] = 11010412,
            ["Duration"] = 3,
            ["GUID"] = "1B903BB8",
            ["NextDialogue"] = 11010413,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903BB8",
            },
        [11010413] = {
            ["Content"] = "不过幸好有你在，否则我们剩下这几条命也得扔这儿。",
            ["ContentJP"] = "俺たちがこうして生きていられたのも、隊長のおかげです。",
            ["DialogueId"] = 11010413,
            ["Duration"] = 3,
            ["GUID"] = "1B903BE2",
            ["NextDialogue"] = 11010414,
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903BE2",
            },
        [11010414] = {
            ["Content"] = "只可惜咱们还是太年轻了，如果<H>阿瓦尔长官</>在……他是咱们中作战经验最丰富的，肯定能指条明路……",
            ["ContentJP"] = "とはいえ、俺らはまだまだ未熟すぎます。もしも、<H>アヴァール長官</>がいてくださったら……戦闘経験が豊富な長官なら、きっと道を指示してくださるはずなのに……",
            ["DialogueId"] = 11010414,
            ["Duration"] = 3,
            ["GUID"] = "1B903C0C",
            ["SpeakNpcId"] = 110044,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903C0C",
            },
        [11010415] = {
            ["Content"] = "（阿瓦尔老师……暂时还没有消息。）",
            ["ContentJP"] = "（アヴァール教官は……いまだ消息不明のまま……）",
            ["DialogueId"] = 11010415,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B903C36",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903C36",
            },
        [11010416] = {
            ["Content"] = "请您务必小心，我在这里等您回来。",
            ["ContentJP"] = "くれぐれもお気をつけてください。ここであなたを待っていますから。",
            ["DialogueId"] = 11010416,
            ["GUID"] = "1B903C37",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110104/1B903C37",
            },
        [11010501] = {
            ["Content"] = "医生……达芙涅医生……唉，咱们现在被困在这里，多半是完了。要是真死在这个鬼地方，能不能你来埋我啊……达芙涅医生……",
            ["ContentJP"] = "先生……！ダフネ先生……！ああ、こんな地獄のような場所に放り込まれて……！あたしもどうせ助からないんでしょ……！野垂れ死ぬくらいなら、せめて楽にさせてよ……ねえ先生……！",
            ["DialogueId"] = 11010501,
            ["Duration"] = 3,
            ["GUID"] = "1B904A52",
            ["NextOptions"] = {
                [1] = 11010502,
                [2] = 11010504,
                },
            ["RelatedWikiId"] = {
                [1] = 204001,
                [2] = 201012,
                },
            ["SpeakNpcId"] = 110045,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904A52",
            },
        [11010502] = {
            ["Content"] = "少说话，会加重伤势。",
            ["ContentJP"] = "しゃべらない方がいい。傷にさわるよ。",
            ["DialogueId"] = 11010502,
            ["GUID"] = "1B904A7C",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 11010503,
            },
        [11010503] = {
            ["Content"] = "又没有止疼药，只能哼哼两声让自己好受点儿了。",
            ["ContentJP"] = "鎮痛剤もないし、他にどうしろって言うんですか？くっちゃべって気を紛らわすくらいしか、方法がないじゃないですか。",
            ["DialogueId"] = 11010503,
            ["Duration"] = 3,
            ["FinalCamera"] = "19.119141,-1903.257812,170.347046,0.000149,-8.797147,-118.375465,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B904AA6",
            ["NextDialogue"] = 11010506,
            ["SpeakNpcId"] = 110045,
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904AA6",
            },
        [11010504] = {
            ["Content"] = "喊这么大声是要把秽兽引来吗？",
            ["ContentJP"] = "そんな大声を出して、穢獣を引き寄せるつもり？",
            ["DialogueId"] = 11010504,
            ["GUID"] = "1B904AD0",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 11010505,
            },
        [11010505] = {
            ["Content"] = "不说了，队长你别动气。没有止疼药，只能哼哼两声让自己好受点儿了。",
            ["ContentJP"] = "はいはいもう黙りますから、そんなカッカしなさんな隊長。鎮痛剤もないし、くっちゃべって気を紛らわすくらいしか、方法がないじゃないですか。",
            ["DialogueId"] = 11010505,
            ["Duration"] = 3,
            ["FinalCamera"] = "19.119141,-1903.257812,170.347046,0.000149,-8.797147,-118.375465,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B904AFA",
            ["NextDialogue"] = 11010506,
            ["SpeakNpcId"] = 110045,
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904AFA",
            },
        [11010506] = {
            ["Content"] = "刚才达芙涅医生和你一起断后的，她怎么样了？",
            ["ContentJP"] = "ダフネ先生、殿で隊長と一緒に後衛を務めてましたよね……彼女もご無事ですか？",
            ["DialogueId"] = 11010506,
            ["Duration"] = 3,
            ["GUID"] = "1B904B24",
            ["NextDialogue"] = 11010507,
            ["SpeakNpcId"] = 110045,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904B24",
            },
        [11010507] = {
            ["Content"] = "她没事，就是她让我来看望你们的。",
            ["ContentJP"] = "うん。彼女から{性别2:君|あなた}たちの看病を任されたんだよ。",
            ["DialogueId"] = 11010507,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B904B4E",
            ["NextDialogue"] = 11010508,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904B4E",
            },
        [11010508] = {
            ["Content"] = "那就好。唉，她也是，一个大小姐，原本在炼金院待着好好的，偏要自请调来十三军团遭这个罪，也不知道她到底在想什么。",
            ["ContentJP"] = "そりゃよかった。ああ……にしたって彼女、いいとこのお嬢様だし錬金院で平穏にやっていればよかったのに、わざわざ志願して第十三軍団に来て……で、結局この有様……まったくけったいな話ですよね。",
            ["DialogueId"] = 11010508,
            ["Duration"] = 3,
            ["GUID"] = "1B904B78",
            ["NextDialogue"] = 11010509,
            ["RelatedWikiId"] = {
                [1] = 101007,
                },
            ["SpeakNpcId"] = 110045,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904B78",
            },
        [11010509] = {
            ["Content"] = "……“为陛下献上荣耀与忠诚”？那群贵族嘴上总挂着这些，也不知道他们现在真的到了这鬼地方，会不会后悔当初不该头脑发热。",
            ["ContentJP"] = "……『陛下に栄光と忠誠を捧げる』ですって？あの貴族ども、口ではそう言ってたけど、実際にこの地獄みたいな場所に来たら、まっさきに後悔するんじゃないかね。",
            ["DialogueId"] = 11010509,
            ["Duration"] = 3,
            ["GUID"] = "1B904BA2",
            ["NextDialogue"] = 11010510,
            ["SpeakNpcId"] = 110045,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904BA2",
            },
        [11010510] = {
            ["Content"] = "不过她医术真不错，说话又好听。队长，你可得护着她点，别让她死在这儿了。",
            ["ContentJP"] = "とはいっても、あの子の医術は本当にすごいし、口も甘いし……隊長、しっかり守ってあげてくださいね。こんなところで死なせたらダメですよ。",
            ["DialogueId"] = 11010510,
            ["Duration"] = 3,
            ["GUID"] = "1B904BCC",
            ["SpeakNpcId"] = 110045,
            ["VoiceName"] = "voice/$Locale$/story/1002/110105/1B904BCC",
            },
        [11010618] = {
            ["Content"] = "仓库的确有一些军需箱。",
            ["ContentJP"] = "確かに軍需品の入った箱が数個あったよ。",
            ["DialogueId"] = 11010618,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B905D84",
            ["NextDialogue"] = 11010619,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905D84",
            },
        [11010619] = {
            ["Content"] = "好。翻找之前，请先确认箱子周围是否设有陷阱。",
            ["ContentJP"] = "よかった。周囲に罠が仕掛けられていないか、確認してから開けてください。",
            ["DialogueId"] = 11010619,
            ["Duration"] = 3,
            ["GUID"] = "1B905DAE",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905DAE",
            },
        [11010621] = {
            ["Content"] = "拿到了，药品没有异样。",
            ["ContentJP"] = "薬を見つけたよ。多分使えると思う。",
            ["DialogueId"] = 11010621,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B905E02",
            ["NextDialogue"] = 11010622,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905E02",
            },
        [11010622] = {
            ["Content"] = "谢谢！回来时小心些，这附近恐怕还会有秽兽出没。",
            ["ContentJP"] = "ありがとうございます！その付近はまだ<Default note=\"text:エジュウ\">穢獣</>がなおうろついているかもしれないので、気を付けてお戻りください。",
            ["DialogueId"] = 11010622,
            ["Duration"] = 3,
            ["GUID"] = "1B905E2C",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905E2C",
            },
        [11010623] = {
            ["Content"] = "也不知道其他人怎么样了……",
            ["ContentJP"] = "他のやつらは……どうなったんだ……",
            ["DialogueId"] = 11010623,
            ["Duration"] = 3,
            ["GUID"] = "1B905E56",
            ["SpeakNpcId"] = 110026,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905E56",
            },
        [11010624] = {
            ["Content"] = "要让那帮畜生血债血偿。",
            ["ContentJP"] = "あの畜生ども、絶対に報いを受けさせてやる……",
            ["DialogueId"] = 11010624,
            ["Duration"] = 3,
            ["GUID"] = "1B905E80",
            ["SpeakNpcId"] = 110057,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905E80",
            },
        [11010625] = {
            ["Content"] = "该死的秽兽……该死的同盟……",
            ["ContentJP"] = "クソ<Default note=\"text:エジュウ\">穢獣</>どもめ……アホセイクソ同盟め……",
            ["DialogueId"] = 11010625,
            ["Duration"] = 3,
            ["GUID"] = "1B905EAA",
            ["SpeakNpcId"] = 110024,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905EAA",
            },
        [11010626] = {
            ["Content"] = "不能睡……不能在这里倒下……",
            ["ContentJP"] = "寝るな……ここで意識を手放したら……",
            ["DialogueId"] = 11010626,
            ["Duration"] = 3,
            ["GUID"] = "1B905ED4",
            ["SpeakNpcId"] = 110025,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905ED4",
            },
        [11010627] = {
            ["Content"] = "嘶——我的胳膊好像不听使唤了……",
            ["ContentJP"] = "ッ——腕が、言うこと聞かねぇよぉ……",
            ["DialogueId"] = 11010627,
            ["Duration"] = 3,
            ["GUID"] = "1B905EFE",
            ["SpeakNpcId"] = 110027,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905EFE",
            },
        [11010628] = {
            ["Content"] = "还好队长平安无事，我们有希望了。",
            ["ContentJP"] = "隊長、ご無事で何よりです。これでまた希望が見えてきました。",
            ["DialogueId"] = 11010628,
            ["Duration"] = 3,
            ["GUID"] = "1B905F28",
            ["SpeakNpcId"] = 110027,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110106/1B905F28",
            },
        [11010701] = {
