            },
        [11010806] = {
            ["Content"] = "玩法教学预留",
            ["DialogueId"] = 11010806,
            ["Duration"] = 3,
            ["GUID"] = "1B907C5C",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110108/1B907C5C",
            },
        [11010901] = {
            ["Content"] = "是秽兽！",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>です！",
            ["DialogueId"] = 11010901,
            ["Duration"] = 3,
            ["GUID"] = "1B908BF2",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908BF2",
            },
        [11010902] = {
            ["Content"] = "达芙涅，保护伤员。",
            ["ContentJP"] = "ダフネ、負傷者をお願い。",
            ["DialogueId"] = 11010902,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B908C1C",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908C1C",
            },
        [11010903] = {
            ["Content"] = "……是！",
            ["ContentJP"] = "分かりました！",
            ["DialogueId"] = 11010903,
            ["Duration"] = 3,
            ["GUID"] = "1B908C46",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110109/1B908C46",
            },
        [11011001] = {
            ["Content"] = "坚持住，我再试试联系“雪狼”分队！",
            ["ContentJP"] = "しっかり！「<Default note=\"text:スノーウルフ\">雪狼</>」隊にもう一度連絡してみます！",
            ["DialogueId"] = 11011001,
            ["Duration"] = 3,
            ["GUID"] = "1B909C5A",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011002,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102101}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909C5A",
            },
        [11011002] = {
            ["Content"] = "还是……没反应……",
            ["ContentJP"] = "やっぱり……ダメ……",
            ["DialogueId"] = 11011002,
            ["Duration"] = 3,
            ["GUID"] = "1B909C84",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011003,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909C84",
            },
        [11011003] = {
            ["Content"] = "喂？喂？",
            ["ContentJP"] = "おい？聞こえるか？",
            ["DialogueId"] = 11011003,
            ["Duration"] = 3,
            ["GUID"] = "1B909CAE",
            ["NextDialogue"] = 11011004,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909CAE",
            },
        [11011004] = {
            ["Content"] = "接通了……！",
            ["ContentJP"] = "繋がった……！",
            ["DialogueId"] = 11011004,
            ["Duration"] = 3,
            ["GUID"] = "1B909CD8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011005,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909CD8",
            },
        [11011005] = {
            ["Content"] = "<H>海伯利亚今日天气怎么样？</>",
            ["ContentJP"] = "<H>本日のヒュペリアの空模様は？</>",
            ["DialogueId"] = 11011005,
            ["Duration"] = 3,
            ["GUID"] = "1B909D02",
            ["NextDialogue"] = 11011006,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D02",
            },
        [11011006] = {
            ["Content"] = "<H>迪斯玛尼亚今夜有雨。</>",
            ["ContentJP"] = "<H>今宵のディズマニアは雨模様。</>",
            ["DialogueId"] = 11011006,
            ["Duration"] = 3,
            ["GUID"] = "1B909D2C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011007,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D2C",
            },
        [11011007] = {
            ["Content"] = "我是阿瓦尔·赫德兰中校。对面的“狮鹫”小队队员，你们在哪里？",
            ["ContentJP"] = "こちらアヴァール·ハードランド。「<Default note=\"text:グリフィン\">鷲獅子</>」隊だよな？現在地は？",
            ["DialogueId"] = 11011007,
            ["Duration"] = 3,
            ["GUID"] = "1B909D56",
            ["NextDialogue"] = 11011008,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D56",
            },
        [11011008] = {
            ["Content"] = "医务员达芙涅·塞奥多尔请求支援。我们当前正位于……",
            ["ContentJP"] = "医務官ダフネ・セオドール、支援を要請します。こちらは現在……",
            ["DialogueId"] = 11011008,
            ["Duration"] = 3,
            ["GUID"] = "1B909D80",
            ["NextDialogue"] = 11011009,
            ["SnapShot"] = "OUTDOOR",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909D80",
            },
        [11011009] = {
            ["Content"] = "没完没了……",
            ["ContentJP"] = "キリがない……",
            ["DialogueId"] = 11011009,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909DAA",
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DAA",
            },
        [11011010] = {
            ["Content"] = "小鬼，撑住！",
            ["ContentJP"] = "おい小童！踏ん張らんか！",
            ["DialogueId"] = 11011010,
            ["Duration"] = 3,
            ["GUID"] = "1B909DD4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DD4",
            },
        [11011011] = {
            ["Content"] = "阿瓦尔老师！",
            ["ContentJP"] = "アヴァール教官！！",
            ["DialogueId"] = 11011011,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909DFE",
            ["NextDialogue"] = 11011012,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909DFE",
            },
        [11011012] = {
            ["Content"] = "嗯，有我呢。你专心应付眼前，背后交给我就是。",
            ["ContentJP"] = "おう、待たせたな。背中は俺に任せて、お前は目の前の敵に専念しろ。",
            ["DialogueId"] = 11011012,
            ["GUID"] = "1B909E28",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E28",
            },
        [11011013] = {
            ["Content"] = "我们暂时击退了来袭的秽兽，清理出一个临时休整点，不过这边也坚持不了太久。",
            ["ContentJP"] = "襲ってきた<Default note=\"text:エジュウ\">穢獣</>を撃退した後、ベースキャンプを作ったのですが、そう長くは持たないでしょう。",
            ["DialogueId"] = 11011013,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E52",
            ["NextDialogue"] = 11011014,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E52",
            },
        [11011014] = {
            ["Content"] = "达芙涅紧急救治了伤员，但据伤情判断，他们已经暂时丧失了作战能力。",
            ["ContentJP"] = "ダフネがすでにケガ人の応急手当を済ませましたが、これ以上作戦を遂行できる状態ではないかと。",
            ["DialogueId"] = 11011014,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B909E7C",
            ["NextDialogue"] = 11011015,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909E7C",
            },
        [11011015] = {
            ["Content"] = "……好。你们也辛苦了。",
            ["ContentJP"] = "……了解した。よくやったな。",
            ["DialogueId"] = 11011015,
            ["GUID"] = "1B909EA6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909EA6",
            },
        [11011016] = {
            ["Content"] = "阿瓦尔长官！哈、哈……你来了！你一定会带着大家……攻下这座要塞……",
            ["ContentJP"] = "アヴァール長官！ハ、ハハ……おいでなさったのですね！長官なら……きっと皆を率いて……要塞を攻め落としてくださる……！",
            ["DialogueId"] = 11011016,
            ["GUID"] = "1B909ED0",
            ["NextDialogue"] = 11011017,
            ["SpeakNpcId"] = 110019,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909ED0",
            },
        [11011017] = {
            ["Content"] = "你们都是好样的，你们的勇敢对得起胸口的徽章，帝国不会让你们在这里白白流血。",
            ["ContentJP"] = "大儀だったぞ。お前らの戦いぶりは胸の帝国徽章にも恥じんほどに勇猛果敢であった。ここで流した血は決して無駄にはせん。",
            ["DialogueId"] = 11011017,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909EFA",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909EFA",
            },
        [11011018] = {
            ["Content"] = "长官，“雪狼”那边怎么样了？",
            ["ContentJP"] = "長官、「<Default note=\"text:スノーウルフ\">雪狼</>」の方はどうなったんですか？",
            ["DialogueId"] = 11011018,
            ["GUID"] = "1B909F24",
            ["NextDialogue"] = 11011019,
            ["SpeakNpcId"] = 110013,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F24",
            },
        [11011019] = {
            ["Content"] = "雪狼分队一切正常。我已经联系上了总指挥官，你们尽管放心休息，接下来就交给我们。",
            ["ContentJP"] = "順当に任務を遂行中だ。総司令にも連絡を取ったから、安心して休んでいいぞ。ここからは俺たちに任せておけ。",
            ["DialogueId"] = 11011019,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909F4E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F4E",
            },
        [11011020] = {
            ["Content"] = "阿瓦尔长官？我……在做梦吗……",
            ["ContentJP"] = "アヴァール長官？自分は……夢でも見てるのか……？",
            ["DialogueId"] = 11011020,
            ["GUID"] = "1B909F78",
            ["NextDialogue"] = 11011021,
            ["SpeakNpcId"] = 110027,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909F78",
            },
        [11011021] = {
            ["Content"] = "这不是梦。坚持住，别睡着。",
            ["ContentJP"] = "現実だぞ寝ぼけてる場合か。しっかりしろ。",
            ["DialogueId"] = 11011021,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909FA2",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FA2",
            },
        [11011022] = {
            ["Content"] = "向您致意……长官……荣耀……尽归吾皇……",
            ["ContentJP"] = "ああ……長官……我らが皇帝に……栄光あれ……",
            ["DialogueId"] = 11011022,
            ["GUID"] = "1B909FCC",
            ["NextDialogue"] = 11011023,
            ["SpeakNpcId"] = 110028,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FCC",
            },
        [11011023] = {
            ["Content"] = "荣耀尽归吾皇。",
            ["ContentJP"] = "我らが皇帝に栄光あれ。",
            ["DialogueId"] = 11011023,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B909FF6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B909FF6",
            },
        [11011024] = {
            ["Content"] = "长官，以你们的判断，这次作战还有希望吗？",
            ["ContentJP"] = "隊長、長官、おふたりから見て、本作戦にまだ希望はありますでしょうか？",
            ["DialogueId"] = 11011024,
            ["GUID"] = "1B90A020",
            ["NextDialogue"] = 11011025,
            ["SpeakNpcId"] = 110026,
            ["SpeakNpcName"] = "UI_Npc_Hurtsoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A020",
            },
        [11011025] = {
            ["Content"] = "以当前的战况来看——",
            ["ContentJP"] = "現在の戦況から見るに——",
            ["DialogueId"] = 11011025,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90A04A",
            ["NextDialogue"] = 11011026,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A04A",
            },
        [11011026] = {
            ["Content"] = "以当前的战况来看，援军就在路上。我们很快会夺下要塞，把那群混蛋打得头破血流。",
            ["ContentJP"] = "援軍がこちらに向かっている。到着すれば要塞の奪還は確実だろう。そんでもって、野郎どもを血みどろにするのさ。",
            ["DialogueId"] = 11011026,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90A074",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110110/1B90A074",
            },
        [11011101] = {
            ["Camera"] = "320.033203,-633.472656,260.888916,0.000053,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "我看过大家的情况了。",
            ["ContentJP"] = "あいつらの様子を見てきた。",
            ["DialogueId"] = 11011101,
            ["FinalCamera"] = "350.376953,-614.980469,260.888916,0.000053,-14.19958,121.341087,35.0,100000.0,false,Manual,22.0",
