            ["NextDialogue"] = 11011136,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90B256",
            },
        [11011136] = {
            ["Content"] = "等回皇都，我会去看你。",
            ["ContentJP"] = "帝都に戻ったら、お見舞いに行くから。",
            ["DialogueId"] = 11011136,
            ["Duration"] = 3,
