            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90B280",
            },
        [11011137] = {
            ["Content"] = "嗯。长官都那么说了，我也没有别的选择。但是，我总担心……",
            ["ContentJP"] = "はい。長官に命じられた以上、逆らうわけにはいきませんが……どうしても心配で……",
            ["DialogueId"] = 11011137,
            ["Duration"] = 3,
            ["GUID"] = "1B90B2AA",
            ["NextDialogue"] = 11011138,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90B2AA",
            },
        [11011138] = {
            ["Content"] = "算了，没关系，有他在，应该不会有问题的。",
            ["ContentJP"] = "……いえ、なんでもないです……私は、隊長を信じます。",
            ["DialogueId"] = 11011138,
            ["Duration"] = 3,
            ["GUID"] = "1B90B2D4",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110111/1B90B2D4",
            },
        [11011201] = {
            ["Content"] = "他们改装了所有机关……同盟中也有了不得的工程师吗？",
            ["ContentJP"] = "ヤツらが設備の全てを改装しているとのことですが……同盟にも腕利きのエンジニアが？",
            ["DialogueId"] = 11011201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90BD2A",
            ["NextDialogue"] = 11011202,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BD2A",
            },
        [11011202] = {
            ["Content"] = "当然。早就和上头的老顽固说过，别把神弃者同盟当“野蛮人”。",
            ["ContentJP"] = "当然いるに決まっている。上の頑固ジジイどもに昔から言ってるんだがな。フォーセイクン同盟を「野蛮人」風情と舐めてかかるなって。",
            ["DialogueId"] = 11011202,
            ["Duration"] = 3,
            ["GUID"] = "1B90BD54",
            ["NextDialogue"] = 11011203,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BD54",
            },
        [11011203] = {
            ["Content"] = "要是同盟是野蛮人，那帝国让人家占了大半年要塞，岂不是还不如野蛮人？",
            ["ContentJP"] = "同盟の連中が野蛮人であるならば、帝国は野蛮人に手も足も出せず、半年も要塞の占領を許しているということになるのが分かっとらん。",
