            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011204,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BD7E",
            },
        [11011204] = {
            ["Content"] = "嗯……高层太轻敌了。",
            ["ContentJP"] = "……上層部は曇った眼鏡で敵を見ているのでしょうか。",
