            ["NextDialogue"] = 11011206,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BDD2",
            },
        [11011206] = {
            ["Content"] = "让大艺术家自己去军团长办公室解释吧！看他那副伶牙俐齿还能不能哄得西比尔赦免他。",
            ["ContentJP"] = "軍団長の執務室に大芸術家様を向かわせようじゃないか！自ら説明しろってもんだ！あいつの器用な口先がシビルに通じるのか、見ものだな！",
            ["DialogueId"] = 11011206,
            ["Duration"] = 3,
            ["GUID"] = "1B90BDFC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110112/1B90BDFC",
            },
        [11011301] = {
            ["Content"] = "先停下来整理一下现在的情况吧。",
