        [11011308] = {
            ["Content"] = "用要塞防御机关设伏也就算了，偏偏还引来一群秽兽……我们轻装突进，没携带针对大型秽兽的武器，大伙只能拿命硬搏。",
            ["ContentJP"] = "兵を伏せて要塞の防衛機能を余すことなく活用した挙句、意図的に<Default note=\"text:エジュウ\">穢獣</>の群れまでぶつけてきやがった……潜入目的で軽装備だった我々は大型<Default note=\"text:エジュウ\">穢獣</>に対抗可能な武器など備えておらず、逃走経路も確保できない状況下、\
命を賭して戦うしか選択肢は他なかった。",
            ["DialogueId"] = 11011308,
            ["FacialId"] = {
                [1] = "110010:None",
                },
            ["GUID"] = "1B90CEB8",
            ["NextDialogue"] = 11011309,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CEB8",
            },
        [11011309] = {
            ["Camera"] = "163.675781,75.453125,153.764725,0.00033,-4.399987,-121.180855,35.000011,217.265625,false,Manual,22.0",
            ["Content"] = "既然龙莎要塞是帝国工程师设计的，您应该可以破解那些机关吧？",
            ["ContentJP"] = "ロンザ要塞は帝国のエンジニアにより設計されたとの話です。ならば防衛機構の詳細把握や暗号通信も傍受可能だったのでは？",
            ["DialogueId"] = 11011309,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90CEE2",
            ["NextDialogue"] = 11011310,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CEE2",
            },
        [11011310] = {
            ["Camera"] = "137.261719,-144.210938,138.550858,0.000377,2.000023,104.411934,35.000011,460.11969,false,Manual,22.0",
            ["Content"] = "怎么，小鬼，军事学院那些日子，密码学没好好上？",
            ["ContentJP"] = "お前は暗号学の成績が悪かったよな？士官学校で学ぶ機会は如何程にもあったろうに。",
            ["DialogueId"] = 11011310,
            ["GUID"] = "1B90CF0C",
            ["NextDialogue"] = 11011311,
            ["RelatedWikiId"] = {
                [1] = 407001,
                },
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CF0C",
            },
        [11011311] = {
            ["Camera"] = "205.858398,232.40625,175.778214,0.000381,-9.199888,-117.389748,35.000011,460.11969,false,Manual,22.0",
            ["Content"] = "您还记着这事啊。",
            ["ContentJP"] = "耳新しくない問いかけですね。",
            ["DialogueId"] = 11011311,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Unhappy02",
                },
            ["GUID"] = "1B90CF36",
            ["NextDialogue"] = 11011312,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CF36",
            },
        [11011312] = {
            ["Camera"] = "149.15918,-96.898438,158.218338,0.00035,-2.399719,109.005692,35.000015,460.11969,false,Manual,22.0",
            ["Content"] = "算了算了，这次的情况就算你擅长解码也没用。全要塞的机关都被同盟改装过了，根本没时间挨个破解完。",
            ["ContentJP"] = "まあ今回は暗号解読が得意であろうと無駄だ。要塞の全設備は同盟の手により改装されている。それを個々に解読するなど、時間がまったく足りん。",
            ["DialogueId"] = 11011312,
            ["FacialId"] = {
                [1] = "110010:None",
                },
            ["GUID"] = "1B90CF60",
            ["NextDialogue"] = 11011313,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Confident_End",
                [2] = "110022:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CF60",
            },
        [11011313] = {
            ["Camera"] = "762.444336,-451.796875,86.761429,0.00037,1.745735,147.234253,35.000011,100000.0,false,Manual,22.0",
            ["Content"] = "不过，“先解决机关”的判断是正确的，我们接下来要去的就是<H>动力室</>。",
            ["ContentJP"] = "対して「防衛機構の詳細把握」が可能だったかは正答だ。俺たちは今<H>機関室</>に向かっている。",
            ["DialogueId"] = 11011313,
            ["FinalCamera"] = "728.643555,-504.324219,86.761093,0.00037,1.745735,147.234253,35.000011,100000.0,false,Manual,22.0",
            ["GUID"] = "1B90CF8A",
            ["NextDialogue"] = 11011314,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CF8A",
            },
        [11011314] = {
            ["Content"] = "强制切断动力、关停机关后，救援其他受困士兵——这就是接下来的作战目标。",
            ["ContentJP"] = "強制的に動力を切断し、要塞機能を停止へ追い込む。後に捕虜となった兵士を救助する——というのが次の作戦目標だ。",
            ["DialogueId"] = 11011314,
            ["Duration"] = 3,
            ["GUID"] = "1B90CF8B",
            ["NextDialogue"] = 11011315,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CF8B",
            },
        [11011315] = {
            ["Content"] = "那边的装置至少需要两个人协力，亏得我先把你捞出来了。",
            ["ContentJP"] = "それに際しては少なくとも人員が2名以上必要となる。先にお前を拾えたのは運が良かった。",
            ["DialogueId"] = 11011315,
            ["GUID"] = "1B90CFDE",
            ["NextDialogue"] = 11011316,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90CFDE",
            },
        [11011316] = {
            ["Camera"] = "112.263672,-51.882812,144.46846,0.000339,3.600268,98.398293,35.000015,183.304688,false,Manual,22.0",
            ["Content"] = "等等，有人联络……",
            ["ContentJP"] = "待て、通信だ……",
            ["DialogueId"] = 11011316,
            ["GUID"] = "1B90D008",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11011317,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Call_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D008",
            },
        [11011317] = {
            ["Camera"] = "140.575195,-95.742188,175.792465,0.00006,-8.19863,103.384193,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "喂？喂喂？听到了吗？<H>海伯利亚今日天气怎么样？</>",
            ["ContentJP"] = "応答を？どうか応答を、聞こえますか？<H>本日のヒュペリアの空模様は？</>",
            ["DialogueId"] = 11011317,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["FinalCamera"] = "-5.985352,-65.789062,175.738083,0.00007,-8.398653,55.582458,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "1B90D032",
            ["NextDialogue"] = 11011318,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Voice",
            ["TalkActionId"] = {
                [1] = "110022:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 50,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D032",
            },
        [11011318] = {
            ["Content"] = "<H>迪斯玛尼亚今夜有雨。</>",
            ["ContentJP"] = "<H>今夜はディズマニアに雨が降る。</>",
            ["DialogueId"] = 11011318,
            ["Duration"] = 1,
            ["GUID"] = "1B90D05C",
            ["NextDialogue"] = 11011319,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D05C",
            },
        [11011319] = {
            ["Content"] = "阿瓦尔长官？是您吗？我是维克！",
            ["ContentJP"] = "アヴァール長官？ですか？俺です！ヴィックです！",
            ["DialogueId"] = 11011319,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 1,
            ["GUID"] = "1B90D086",
            ["NextDialogue"] = 11011320,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Voice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D086",
            },
        [11011320] = {
            ["Content"] = "是我，报告现状。",
            ["ContentJP"] = "アヴァールだ。現状の報告を。",
            ["DialogueId"] = 11011320,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110010:Think01",
                },
            ["GUID"] = "1B90D0B0",
            ["NextDialogue"] = 11011321,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D0B0",
            },
        [11011321] = {
            ["Content"] = "与您分开后，我和莫妮卡选择了外环路线，现在已经抵达动力室附近。",
            ["ContentJP"] = "長官との連絡が途絶えてからは、モニカとともに外周ルートを侵攻、現在は機関室付近に到着しています。",
            ["DialogueId"] = 11011321,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90D0DA",
            ["NextDialogue"] = 11011322,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Weike",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D0DA",
            },
        [11011322] = {
            ["Content"] = "动力室？你们莫非也打算——",
            ["ContentJP"] = "機関室？もしやお前らも——",
            ["DialogueId"] = 11011322,
            ["Duration"] = 1,
            ["GUID"] = "1B90D104",
            ["NextDialogue"] = 11011323,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D104",
            },
        [11011323] = {
            ["Content"] = "我是来特地向您报告的，我们接下来会尝试关闭动力装置。",
            ["ContentJP"] = "これから動力装置を切断します。そのご報告を。",
            ["DialogueId"] = 11011323,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90D12E",
            ["NextDialogue"] = 11011324,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Weike",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D12E",
            },
        [11011324] = {
            ["Camera"] = "6.650391,45.976562,136.704086,0.000072,12.600298,22.184877,35.000008,112.428253,false,Manual,22.0",
            ["Content"] = "先别急，动力室很可能有陷阱。你们两个原地待命，我们再有十几分钟就能赶过去帮你们了。",
            ["ContentJP"] = "急くな、機関室には罠が仕掛けられている可能性が高い。お前らはその場で待機だ。後10分と少しで俺と{nickname2}が援護できる。",
            ["DialogueId"] = 11011324,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "5.854492,47.929688,136.704086,0.000072,12.600298,22.184877,35.000008,112.428253,false,Manual,22.0",
            ["GUID"] = "1B90D158",
            ["NextDialogue"] = 11011325,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D158",
            },
        [11011325] = {
            ["Content"] = "先让我们试试吧，长官！多耽误一分钟，其他人就多一分钟危险。",
            ["ContentJP"] = "まずは我々が試します長官！どうか、現状は1分でも長引けば、味方が危険に晒されます。",
            ["DialogueId"] = 11011325,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90D182",
            ["NextDialogue"] = 11011326,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Weike",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D182",
            },
        [11011326] = {
            ["Camera"] = "59.295898,61.582031,155.348526,0.000335,-4.601198,-74.576843,35.0,178.050125,false,Manual,22.0",
            ["Content"] = "你小子……",
            ["ContentJP"] = "お前……",
            ["DialogueId"] = 11011326,
            ["FacialId"] = {
                [1] = "110022:Doubt01",
                },
            ["GUID"] = "1B90D1AC",
            ["NextDialogue"] = 11011327,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D1AC",
            },
        [11011327] = {
            ["Camera"] = "-1.773438,-172.789062,140.002975,0.000304,-0.201839,60.417431,35.000008,178.050125,false,Manual,22.0",
            ["Content"] = "还有最后一件事……既然{nickname2}在您那的话，能不能告诉我“狮鹫”分队的情况怎么样？我弟弟西蒙他……",
            ["ContentJP"] = "最後に……私事ではありますが、「<Default note=\"text:グリフィン\">鷲獅子</>」隊の状況を教えていただけませんか？{nickname2}隊長が長官とご一緒なのであれば、弟のシーモンに関して……",
            ["DialogueId"] = 11011327,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:None",
                },
            ["GUID"] = "1B90D1D6",
            ["NextDialogue"] = 11011328,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Weike",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D1D6",
            },
        [11011328] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11011328,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90D200",
            ["NextDialogue"] = 11011329,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D200",
            },
        [11011329] = {
            ["Camera"] = "11.716797,206.703125,167.242294,0.000336,-6.80127,-68.977051,35.000011,178.050125,false,Manual,22.0",
            ["Content"] = "我目前没有发现他的尸体。",
            ["ContentJP"] = "今のところ死体は発見していない。",
            ["DialogueId"] = 11011329,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90D22A",
            ["NextDialogue"] = 11011330,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D22A",
            },
        [11011330] = {
            ["Content"] = "……啊……？",
            ["ContentJP"] = "……えっ……？",
            ["DialogueId"] = 11011330,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B90D254",
            ["NextDialogue"] = 11011331,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Weike",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D254",
            },
        [11011331] = {
            ["Camera"] = "6.71582,-172.675781,139.699112,0.000306,0.19813,66.419029,35.000015,178.050125,false,Manual,22.0",
            ["Content"] = "咳，没事，没事。他受了些伤，在休整点躺着。医务员看着呢，别担心。",
            ["ContentJP"] = "大丈夫だ、大丈夫。オッホン……少し怪我を負ったようだが無事なはずだ。今はベースキャンプで休んでいる。なに心配いらん！そこには医務官もいるからな！",
            ["DialogueId"] = 11011331,
            ["FacialId"] = {
                [1] = "110010:Unhappy01",
                },
            ["GUID"] = "1B90D27E",
            ["NextDialogue"] = 11011332,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D27E",
            },
        [11011332] = {
            ["Content"] = "……明白了，多谢。",
            ["ContentJP"] = "……わかりました、ありがとうございます。",
            ["DialogueId"] = 11011332,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 2,
            ["GUID"] = "1B90D2A8",
            ["NextDialogue"] = 11011333,
            ["Scripts"] = "PARA{\
PlayNormalSound{_delay{3.5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}},\
PlayAnimation{_delay{3.5},ActorId{110010},AnimationId{\"Call_End\"},Duration{1}}\
}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcName"] = "UI_Npc_Weike",
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D2A8",
            },
        [11011333] = {
            ["Content"] = "你那张嘴，以后还是别安慰人了，千万别。",
            ["ContentJP"] = "今後一切、その口で誰かを慰めようとするなよ。お前、絶対にだ。",
            ["DialogueId"] = 11011333,
            ["FacialId"] = {
                [1] = "110010:Syouganai01",
                },
            ["GUID"] = "1B90D2D2",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11011334,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D2D2",
            },
        [11011334] = {
            ["Camera"] = "-111.132812,292.960938,162.815781,0.000358,-5.199953,-55.60548,35.000011,183.307098,false,Manual,22.0",
            ["Content"] = "……知道了。",
            ["ContentJP"] = "……了解であります。",
            ["DialogueId"] = 11011334,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90D2FC",
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{110010},AnimationId{\"Sigh_End\"},Duration{1}}",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110113/1B90D2FC",
            },
        [11011401] = {
            ["Camera"] = "335.451782,-725.574219,186.097534,0.000954,-5.597319,112.385605,40.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你们来了！",
            ["ContentJP"] = "いらっしゃいましたか！",
            ["DialogueId"] = 11011401,
            ["Duration"] = 1,
            ["FinalCamera"] = "300.328125,-740.019531,186.097534,0.000954,-5.597319,112.385605,40.0,100000.0,false,DoNotOverride,22.0",
