        [11011411] = {
            ["Camera"] = "49.17527,197.511719,119.335083,0.000004,17.003107,-77.610802,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我来处理上锁的门。{nickname2}，你去下面协助我关停动力装置，营救维克。",
            ["ContentJP"] = "{nickname2}、お前は下で動力装置の停止に加勢せよ。ロックされたゲートはなんとかするから、ヴィックの救出を。",
            ["DialogueId"] = 11011411,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "28.606674,187.460938,128.160645,-2.0,1.602922,-90.009247,35.0,100000.0,false,DoNotOverride,22.0",
