                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90DF75",
            },
        [11011412] = {
            ["Camera"] = "-4.312927,-138.851562,142.460938,0.001032,1.402832,76.977753,30.000002,213.29274,false,Manual,11.73743",
            ["Content"] = "听我指示行动。我们的动作越快，战友活下来的几率就越高。明白吗？",
            ["ContentJP"] = "可及的速やかに行動しろ。今は戦友の生存確率が行動速度に直結する。分かったな？",
            ["DialogueId"] = 11011412,
            ["Duration"] = 3,
            ["GUID"] = "1B90DFC8",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
