}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90DFC8",
            },
        [11011413] = {
            ["Content"] = "我找到维克了……只有遗体。",
            ["ContentJP"] = "ヴィックが……見つかりました。死体で……ですが。",
            ["DialogueId"] = 11011413,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90DFF2",
            ["NextDialogue"] = 11011414,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90DFF2",
            },
        [11011414] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11011414,
            ["Duration"] = 3,
            ["GUID"] = "1B90E01C",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011415,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E01C",
            },
        [11011415] = {
            ["Content"] = "任务继续。",
            ["ContentJP"] = "任務を続行せよ。",
            ["DialogueId"] = 11011415,
            ["Duration"] = 3,
            ["GUID"] = "1B90E046",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011418,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E046",
            },
        [11011416] = {
            ["Content"] = "除了独立供能的中央控制室，整座要塞运转需要的月髓液都在这里。",
            ["ContentJP"] = "要塞全体を稼働するのに必要なイコル液は、独立したエネルギー供給源を持つ中央制御室を除けば、全てここにある。",
            ["DialogueId"] = 11011416,
            ["Duration"] = 3,
            ["GUID"] = "1B90E047",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011417,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E047",
            },
        [11011417] = {
            ["Content"] = "破坏这里的动力装置，要塞中的大部分机关就会停止运转。",
            ["ContentJP"] = "動力装置を破壊すれば、設備の大部分が停止するだろう。",
            ["DialogueId"] = 11011417,
            ["Duration"] = 3,
            ["GUID"] = "1B90E048",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E048",
            },
        [11011418] = {
            ["Content"] = "我们必须让那些机关瘫痪掉……维克不能白白牺牲。",
            ["ContentJP"] = "必ずやり遂げるぞ……ヴィックの犠牲を無駄にはせん。",
            ["DialogueId"] = 11011418,
            ["Duration"] = 3,
            ["GUID"] = "1B90E0C4",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E0C4",
            },
        [11011419] = {
            ["Content"] = "哦？已经处理好一个了吗，小心些，我好像听到秽兽靠过来的声音了。",
            ["DialogueId"] = 11011419,
            ["Duration"] = 3,
            ["GUID"] = "1B90E0EE",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E0EE",
            },
        [11011420] = {
            ["Content"] = "好，{nickname2}，动力链接已经断开了，我们得趁现在去把整个动力装置都毁了。",
            ["DialogueId"] = 11011420,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E118",
            ["NextDialogue"] = 11011421,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E118",
            },
        [11011421] = {
            ["Content"] = "核心的动力炉就在下面，小心些……",
            ["DialogueId"] = 11011421,
            ["Duration"] = 3,
            ["GUID"] = "1B90E142",
            ["NextDialogue"] = 11011422,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E142",
            },
        [11011422] = {
            ["Content"] = "有些脏东西围过来了……事办妥了再上来集合！",
            ["DialogueId"] = 11011422,
            ["Duration"] = 3,
            ["GUID"] = "1B90E16C",
            ["NextDialogue"] = 11011423,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E16C",
            },
        [11011423] = {
            ["Content"] = "好……",
            ["DialogueId"] = 11011423,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E196",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E196",
            },
        [11011424] = {
            ["Content"] = "我会逐个解锁防护屏障，等信号亮起，你就把月髓舱打碎！",
            ["ContentJP"] = "俺が防護バリアを順次解除する！信号が点灯したら、お前はイコルキャビンを破壊しろ！",
            ["DialogueId"] = 11011424,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C0",
            ["NextDialogue"] = 11011425,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C0",
            },
        [11011425] = {
            ["Content"] = "有些月髓舱可能会配备自毁装置，如果听到倒计时响起，就终止行动，马上离开。",
            ["ContentJP"] = "イコルキャビンには自爆装置が備えられている可能性もある。もしカウントダウンが聞こえてきたら、作戦を中止して即時退避せよ。",
            ["DialogueId"] = 11011425,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C1",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C1",
            },
        [11011426] = {
            ["Content"] = "就是现在，打碎它！",
            ["ContentJP"] = "今だ、ブッ壊せ！",
            ["DialogueId"] = 11011426,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C2",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C2",
            },
        [11011427] = {
            ["Content"] = "干得不错，我们还有两个要处理。",
            ["ContentJP"] = "よくやった。しかしキャビンはひとつだけじゃない。残りふたつ、2号と3号を処理する必要がある。",
            ["DialogueId"] = 11011427,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C3",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C3",
            },
        [11011428] = {
            ["Content"] = "2号月髓舱的屏障解锁了，上吧！",
            ["ContentJP"] = "イコルキャビンの2号をアンロックした！やれ！",
            ["DialogueId"] = 11011428,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C4",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C4",
            },
        [11011429] = {
            ["Content"] = "呼……还有最后一个，你那儿还行吗？",
            ["ContentJP"] = "ふぅ……残りは3号のひとつだけだ。そっちは大丈夫か？",
            ["DialogueId"] = 11011429,
            ["Duration"] = 3,
            ["GUID"] = "1B90E1C5",
            ["NextDialogue"] = 11011430,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C5",
            },
        [11011430] = {
            ["Content"] = "没问题。",
            ["ContentJP"] = "問題ありません。",
            ["DialogueId"] = 11011430,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E1C6",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E1C6",
            },
        [11011432] = {
            ["Content"] = "好了，3号，最后一个！",
            ["ContentJP"] = "よし、3号、こいつで最後だ！",
            ["DialogueId"] = 11011432,
            ["GUID"] = "1B90E2E7",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E7",
            },
        [11011433] = {
            ["Content"] = "……自毁倒计时？",
            ["ContentJP"] = "……自爆のカウントダウン？",
            ["DialogueId"] = 11011433,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90E2E8",
            ["NextDialogue"] = 11011434,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E8",
            },
        [11011434] = {
            ["Content"] = "动力室要爆炸了，快走！",
            ["ContentJP"] = "機関室が爆発する！急ぎ退避だ！",
            ["DialogueId"] = 11011434,
            ["GUID"] = "1B90E2E9",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110114/1B90E2E9",
            },
