                },
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F27C",
            },
        [11011527] = {
            ["Content"] = "（闭口不言。）",
            ["ContentJP"] = "（口を出さずに黙り込む）",
            ["DialogueId"] = 11011527,
            ["GUID"] = "1B90F2A6",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 11011528,
            },
        [11011528] = {
            ["Content"] = "继续任务可以，给我们支援。",
            ["ContentJP"] = "……任務続行は了解した。しかし必ず我々への支援を実行してもらいたい。",
            ["DialogueId"] = 11011528,
            ["Duration"] = 3,
            ["GUID"] = "1B90F2D0",
            ["NextDialogue"] = 11011535,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F2D0",
            },
        [11011529] = {
            ["Content"] = "给我们足够的支援，我们才有希望取胜，这也是属于您的胜利。",
            ["ContentJP"] = "必要とする支援を与えられてこそ、勝つ可能性は生まれるものではないでしょうか。ひいては総司令の勝利にも繋がります。",
            ["DialogueId"] = 11011529,
            ["GUID"] = "1B90F2FA",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 11011530,
            },
        [11011530] = {
            ["Camera"] = "-120.756348,-24.742188,128.990662,-2.0,-4.799799,-34.392021,28.0,62.163586,false,DoNotOverride,10.0",
            ["Content"] = "富尔维斯指挥官，如果我们全都死在这里，以你的战术素养，只怕是更拿不下这座要塞。到时候，你就要为战役的失利负责。",
            ["ContentJP"] = "もし私たちが全滅しようものなら、総司令の戦術的素養であっても要塞を手に入れることは不可能となるでしょう。であれば敗北の責任を負うのは総司令です。",
            ["DialogueId"] = 11011530,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-111.863281,-36.107422,127.6828,-2.0,-4.799799,-34.392021,28.0,62.163586,false,DoNotOverride,10.0",
            ["GUID"] = "1B90F324",
            ["NextDialogue"] = 11011531,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{7},TargetPosition{\"-49.350586,-85.533203,128.152405,-1.999999,-4.399707,-32.791218,28.000006,62.163586,false,DoNotOverride,10.0\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-43.35791,-89.382812,127.603882,-1.999999,-4.399707,-32.791218,28.000006,62.163586,false,DoNotOverride,10.0\"},duration{15}}\
}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F324",
            },
        [11011531] = {
            ["Content"] = "我们是你荣辱与共的下属，不是你的敌人。",
            ["ContentJP"] = "私たちは総司令の誉れも辱めもともにする部下であります。決して総司令の敵ではありません。",
            ["DialogueId"] = 11011531,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90F34E",
            ["NextDialogue"] = 11011532,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F34E",
            },
        [11011532] = {
            ["Camera"] = "-885.801758,-247.560547,331.117859,-2.0,-16.999998,14.005773,28.0,261.438629,false,DoNotOverride,3.0",
            ["Content"] = "这又是哪个？哦，阿瓦尔那个好学生，“狮鹫”分队的队长{nickname2}？",
            ["ContentJP"] = "今話しているのは誰だ？ああ、アヴァールが気に入っている優秀な学生とやらか？「鷲獅子」隊の隊長か。",
            ["DialogueId"] = 11011532,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-782.422363,-221.78125,310.503784,-2.0,-16.999992,14.006827,28.0,261.438629,false,DoNotOverride,3.0",
            ["GUID"] = "1B90F378",
            ["NextDialogue"] = 11011535,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110011,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F378",
            },
        [11011533] = {
            ["Content"] = "你那么勇敢，怎么不自己来前线？",
            ["ContentJP"] = "そこまで総司令が勇敢であられるならば、どうしてご自身で前線に出られないのです？",
            ["DialogueId"] = 11011533,
            ["GUID"] = "1B90F379",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 11011534,
            },
        [11011534] = {
            ["Camera"] = "-885.801758,-247.560547,331.117859,-2.0,-16.999998,14.005773,28.0,261.438629,false,DoNotOverride,3.0",
            ["Content"] = "这又是哪个？哦，阿瓦尔那个好学生，“狮鹫”分队的队长{nickname2}？",
            ["ContentJP"] = "今話しているのは誰だ？ああ、アヴァールが気に入っている優秀な学生とやらか？「<Default note=\"text:グリフィン\">鷲獅子</>」隊の隊長の{nickname2}。",
            ["DialogueId"] = 11011534,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-782.422363,-221.78125,310.503784,-2.0,-16.999992,14.006827,28.0,261.438629,false,DoNotOverride,3.0",
