            },
        [11011535] = {
            ["Camera"] = "-249.72168,-44.890625,102.124084,0.00013,9.399945,21.192924,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们先不用那么着急，作战会议已经开完了，“一角鲸”分队的支援就在路上，我也会和他们一起亲临前线。",
            ["ContentJP"] = "君たちに言われるまでもなく作戦会議には通してある。すでに「<Default note=\"text:ナーファル\">一角鯨</>」隊は支援へ急行中であり、私も彼らと前線へ出向くつもりだ。",
            ["DialogueId"] = 11011535,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110022:None",
                },
            ["FinalCamera"] = "-249.72168,-44.890625,106.481567,0.00013,9.399945,21.192924,28.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B90F3F6",
            ["NextDialogue"] = 11011536,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110011,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F3F6",
            },
        [11011536] = {
            ["Camera"] = "272.799316,2614.929688,815.410767,0.000108,-9.399993,-101.800346,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "继续按原计划前进，明白了吗？海伯利亚的军人，但凡一息尚存，就给我去战斗到最后一刻。",
            ["ContentJP"] = "当初の予定通りに作戦を遂行したまえ。いいな？ヒュペリアの軍人たるもの、命を尽くして戦うのだぞ。",
            ["DialogueId"] = 11011536,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["FinalCamera"] = "145.71582,2641.474609,815.410767,0.000108,-9.399993,-101.800346,28.000006,100000.0,false,DoNotOverride,2.8",
