        [11011553] = {
            ["Camera"] = "-116.939453,59.931641,129.807434,0.000084,-6.599089,-65.392105,28.000008,100000.0,false,Manual,8.0",
            ["Content"] = "去救你的战友，{nickname2}。富尔维斯事后问责起来，就说是我的命令。",
            ["ContentJP"] = "{nickname2}、命令だ。お前の戦友を救助せよ。フルヴィスに責任を問われたら俺が命令したと答えてやれ。",
            ["DialogueId"] = 11011553,
            ["Duration"] = 3,
            ["GUID"] = "1B90F6EA",
            ["NextDialogue"] = 11011554,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F6EA",
            },
        [11011554] = {
            ["Content"] = "是。",
            ["ContentJP"] = "了解です。",
            ["DialogueId"] = 11011554,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B90F714",
            ["NextDialogue"] = 11011555,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F714",
            },
        [11011555] = {
            ["Camera"] = "57.235352,-148.5625,119.510437,0.000097,-0.398992,145.808975,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我和莫妮卡也出发去救援另一群士兵，他们被困在了4号炮台附近。",
            ["ContentJP"] = "俺もモニカを連れて信号の兵士たちの救助へ向かう。4番砲台の近くで身動きできんようだ。",
            ["DialogueId"] = 11011555,
            ["Duration"] = 3,
            ["GUID"] = "1B90F73E",
            ["NextDialogue"] = 11011556,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F73E",
            },
        [11011556] = {
            ["Content"] = "……我们刚刚解除了动力，炮台的自动防御应该停止了……或许可以考虑先攻下炮台……",
            ["ContentJP"] = "動力は停止したから砲台の自動防御も解除されている……となると先に砲台を攻め落とすことも可能か……",
            ["DialogueId"] = 11011556,
            ["Duration"] = 3,
            ["GUID"] = "1B90F768",
            ["NextDialogue"] = 11011557,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F768",
            },
        [11011557] = {
            ["Content"] = "……这样一来，我们还能用月髓炮轰开中心区的防御设施。",
            ["ContentJP"] = "……イコルキャノンをぶんどれたら、中央エリアのバリアを撃ち破れるだろうからな。",
            ["DialogueId"] = 11011557,
            ["Duration"] = 3,
            ["GUID"] = "1B90F769",
            ["NextDialogue"] = 11011558,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110115/1B90F769",
            },
        [11011558] = {
            ["Camera"] = "-3.358398,-61.634766,129.081787,0.000143,-6.799255,-81.393669,28.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就这么办吧。如果你那边顺利，等下就到4号炮台来。",
            ["ContentJP"] = "よしやるか。そっちの次第が順当に運んだら、4番砲台で合流だ。",
            ["DialogueId"] = 11011558,
            ["GUID"] = "1B90F76A",
