            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B910FB0",
            },
        [11011705] = {
            ["Content"] = "……喂？",
            ["ContentJP"] = "……えていますか？",
            ["DialogueId"] = 11011705,
            ["Duration"] = 3,
            ["GUID"] = "1B910FDA",
            ["NextDialogue"] = 11011706,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B910FDA",
            },
        [11011706] = {
            ["Content"] = "喂？我是“狮鹫”分队医务员达芙涅·塞奥多尔。",
            ["ContentJP"] = "聞こえていますか？こちらは「<Default note=\"text:グリフィン\">鷲獅子</>」隊の医務官、ダフネ・セオドールです。",
            ["DialogueId"] = 11011706,
            ["Duration"] = 3,
            ["GUID"] = "1B911004",
            ["NextDialogue"] = 11011707,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911004",
            },
        [11011707] = {
            ["Content"] = "……{nickname2}？是你吗？为什么不说话？你受伤了？",
            ["ContentJP"] = "……{nickname2}さん？あなた……でしょうか？どうして何もお話しにならないのですか？お怪我をされたりは？",
            ["DialogueId"] = 11011707,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B91102E",
            ["NextDialogue"] = 11011708,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B91102E",
            },
        [11011708] = {
            ["Content"] = "你在哪儿？我马上申请赶过去……",
            ["ContentJP"] = "現在地はどちらですかね？急行できないか申請を……",
            ["DialogueId"] = 11011708,
            ["Duration"] = 3,
            ["GUID"] = "1B911058",
            ["NextDialogue"] = 11011709,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911058",
            },
        [11011709] = {
            ["Content"] = "我……只是想听听你们的声音。我没事，你们还好吗？",
            ["ContentJP"] = "{性别2:私は……状況を聞きたかっただけだ。そちらは大丈夫か？|私は……状況を聞きたかっただけ。そちらは大丈夫？}",
            ["DialogueId"] = 11011709,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B911082",
            ["NextDialogue"] = 11011710,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911082",
            },
        [11011710] = {
            ["Content"] = "“雪狼”的残兵和我们会合了，我们这里暂时还算安稳。你那边呢？",
            ["ContentJP"] = "残存する「<Default note=\"text:スノーウルフ\">雪狼</>」の隊員も私たちと合流を果たしました。なのでしばらくは波風もなく平穏かと。あなたの方こそ大丈夫ですか？",
            ["DialogueId"] = 11011710,
            ["Duration"] = 3,
            ["GUID"] = "1B9110AC",
            ["NextDialogue"] = 11011711,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B9110AC",
            },
        [11011711] = {
            ["Content"] = "……我……也很好。我继续执行任务了，再见。",
            ["ContentJP"] = "……こちらは……こちらも特に問題はない。任務に戻る……では、また。",
            ["DialogueId"] = 11011711,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9110D6",
            ["NextDialogue"] = 11011712,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B9110D6",
            },
        [11011712] = {
            ["Content"] = "请多保重……我们会在迪斯玛尼亚平安重逢。",
            ["ContentJP"] = "どうかご無事で……ディズマニアで無事に再会できるようお祈りしておきますね。",
            ["DialogueId"] = 11011712,
            ["Duration"] = 3,
            ["GUID"] = "1B911100",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110117/1B911100",
            },
        [11011801] = {
            ["Content"] = "队长！嗨——在这里！",
            ["ContentJP"] = "隊長！あ、あああ——こっち！こっちです！",
            ["DialogueId"] = 11011801,
            ["Duration"] = 3,
            ["GUID"] = "1B911F9A",
            ["SpeakNpcId"] = 110015,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110118/1B911F9A",
            },
        [11011802] = {
            ["Camera"] = "-485.80957,430.660156,148.512939,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，队长，我亲爱的队长！！终于找到你了！！我们的联络频段突然出现异常，这一路谁也联系不上，西蒙就跑出去求救了。",
            ["ContentJP"] = "やった、やったぞ、隊長、我が親愛なる隊長様ぁ！来てくださいましたかぁ！通信の周波数帯に異常が起きて誰とも連絡が取れなくなってたのです。なのでシモンが救援の要請に。",
            ["DialogueId"] = 11011802,
