  { MinKey = 11011842, MaxKey = 11012806, Loader = function()
      return {
        [11011842] = {
            ["Content"] = "可是，不动的话……就没法为您指路了……",
            ["ContentJP"] = "あの……動きはしないと……道の案内はできませんので……",
            ["DialogueId"] = 11011842,
            ["Duration"] = 3,
            ["GUID"] = "1B912654",
            ["NextDialogue"] = 11011843,
            ["SpeakNpcId"] = 110034,
            },
        [11011843] = {
            ["Content"] = "对哦，也是。",
            ["ContentJP"] = "それはそっか。",
            ["DialogueId"] = 11011843,
            ["Duration"] = 3,
            ["GUID"] = "1B91267E",
            ["NextDialogue"] = 11011844,
            ["SpeakNpcId"] = 110015,
            },
        [11011844] = {
            ["Content"] = "您无需这样戒备，普通的卡戎之民也是人，大家和您一样，都有妈妈，都想回去和她团聚。",
            ["ContentJP"] = "そんなに警戒をしなくても、カロン族も普通の人間でございますから。同じように母がいて、同じように母に再会したいと考えている、本当に普通なのです。",
            ["DialogueId"] = 11011844,
            ["Duration"] = 3,
            ["GUID"] = "1B9126A8",
            ["NextDialogue"] = 11011845,
            ["SpeakNpcId"] = 110034,
            },
        [11011845] = {
            ["Content"] = "……唉，卡嘉……",
            ["ContentJP"] = "……あぁ、カーチャ……",
            ["DialogueId"] = 11011845,
            ["GUID"] = "1B9126D2",
            ["NextDialogue"] = 11011846,
            ["SpeakNpcId"] = 110017,
            },
        [11011846] = {
            ["Content"] = "……队长，为什么要阻止我？！",
            ["ContentJP"] = "……隊長、どうして俺を止めた！？",
            ["DialogueId"] = 11011846,
            ["GUID"] = "1B9126FC",
            ["NextDialogue"] = 11011847,
            ["SpeakNpcId"] = 110016,
            },
        [11011847] = {
            ["Content"] = "不一定所有卡戎之民都是同盟那些反抗者——比如阿瓦尔长官也是卡戎之民。就算这几个人真的是同盟成员，活着的他们也比死了的他们更有价值。",
            ["ContentJP"] = "全てのカロン族が同盟に属する反逆者であるとは限らない——アヴァール長官もカロン族{性别2:だろう|でしょう}？仮に数人が本当の同盟のメンバーであろうとも同じだ。生きている彼らは死んだ彼らよりも価値がある。",
            ["DialogueId"] = 11011847,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B912726",
            ["NextDialogue"] = 11011848,
            ["SpeakNpcId"] = 110022,
            },
        [11011848] = {
            ["Content"] = "……无论心里有什么声音在回响，都不要屈从它们。马尔科，不要让冲动凌驾在理智之上。",
            ["ContentJP"] = "……穏やかでない声が心中に響いても、それに屈従してはダメだ。マルコ、衝動が理性を凌駕してはいけない。",
            ["DialogueId"] = 11011848,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B912750",
            ["SpeakNpcId"] = 110022,
            },
        [11011849] = {
            ["Camera"] = "-206.832031,-274.033203,151.986694,0.000304,-7.786074,84.022697,30.000002,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "谢谢您……",
            ["ContentJP"] = "ありがとうございました……",
            ["DialogueId"] = 11011849,
            ["Duration"] = 1,
            ["GUID"] = "1B91277A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
