        [11011909] = {
            ["Camera"] = "-13.794922,-59.895142,111.804016,0.000078,20.79701,-163.038177,22.0,100000.0,false,DoNotOverride,5.0",
            ["Content"] = "西蒙阵亡，其他几个救下来了。",
            ["ContentJP"] = "シモンは戦死、他の数名は救出できました。",
            ["DialogueId"] = 11011909,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B913152",
            ["NextDialogue"] = 11011910,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110010:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B913152",
            },
        [11011910] = {
            ["Camera"] = "-13.794922,-59.895142,111.804016,0.000078,20.79701,-163.038177,22.0,100000.0,false,DoNotOverride,5.0",
            ["Content"] = "我们还遇到了几个被同盟掳来的卡戎难民，是他们带我们来这儿的。",
            ["ContentJP"] = "同盟に連行されたと話すカロン難民の数名にも遭遇しました。彼女たちの手引きで私たちは到着できましたが。",
            ["DialogueId"] = 11011910,
            ["Duration"] = 8,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-4.126953,-57.571289,122.111938,0.000078,2.796942,-148.23848,22.000011,424.359375,false,DoNotOverride,5.0",
            ["GUID"] = "1B91317C",
            ["NextDialogue"] = 11011911,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91317C",
            },
        [11011911] = {
            ["Camera"] = "-161.328125,-202.881226,167.300476,0.000099,-11.803092,-148.037811,40.0,424.358032,false,DoNotOverride,5.0",
            ["Content"] = "难民？会不会是同盟的人假扮的？",
            ["ContentJP"] = "難民？同盟どもの偽装工作の疑いは？",
            ["DialogueId"] = 11011911,
            ["Duration"] = 3,
            ["FinalCamera"] = "-156.371094,-210.830078,167.300476,0.000099,-11.803092,-148.037811,40.0,424.358032,false,DoNotOverride,5.0",
            ["GUID"] = "1B9131A6",
            ["NextDialogue"] = 11011912,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9131A6",
            },
        [11011912] = {
            ["Camera"] = "1204.801758,464.393738,813.957642,0.000043,-27.002495,-153.843018,40.0,100000.0,false,Manual,5.0",
            ["Content"] = "所以我让士兵们看好他们了。如果他们是平民，那么跟着我们比乱转更安全；如果他们是同盟的人，就刚好一并带回皇都。",
            ["ContentJP"] = "無論警戒を。兵士たちには目を離すなと厳命しています。仮に一般人であれば我々と行動をともにしたほうが逃げ回るより安全ですし、仮に同盟の手合いであれば帝都へ連行できますので。",
            ["DialogueId"] = 11011912,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "1220.620117,432.180267,813.957642,0.000043,-27.002495,-153.843018,40.0,100000.0,false,Manual,5.0",
            ["GUID"] = "1B9131D0",
            ["NextDialogue"] = 11011913,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_End",
                [2] = "110010:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9131D0",
            },
        [11011913] = {
            ["Camera"] = "87.085938,-80.530945,111.064758,-2.000001,24.197323,-65.246292,25.000002,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如果他们是敌人，那带上他们，埋伏在暗的同盟成员也会适当顾虑同伴的性命。嗯，你很周全。",
            ["ContentJP"] = "確かにな。闇に潜む同盟の連中も仲間の命は考慮するだろうから、彼女たちが敵対勢力だとしても同行させる価値はある。ふむ、お前らしく考えているじゃないか。",
            ["DialogueId"] = 11011913,
            ["Duration"] = 3,
            ["FinalCamera"] = "91.947266,-92.697449,116.917236,-2.000001,24.197323,-65.246323,25.000002,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B9131FA",
            ["NextDialogue"] = 11011914,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9131FA",
            },
        [11011914] = {
            ["Camera"] = "-445.671875,693.834045,67.956787,-1.0,3.597447,-59.841167,35.0,100000.0,false,Manual,5.0",
            ["Content"] = "至于这边……支援在路上出了些状况，上头的命令是，“任务继续”。",
            ["ContentJP"] = "こっちについては……支援部隊がトラブルで進行を停止したが、上からの命令は「任務続行」となっている。",
            ["DialogueId"] = 11011914,
            ["Duration"] = 3,
            ["FinalCamera"] = "-368.775391,561.49176,77.580078,-1.0,3.597447,-59.841167,35.0,100000.0,false,Manual,5.0",
            ["GUID"] = "1B913224",
            ["NextDialogue"] = 11011915,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{110010},AnimationId{\"Confident_Start\"},Duration{0}}",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B913224",
            },
        [11011915] = {
            ["Content"] = "我听到了。",
            ["ContentJP"] = "了解しました。",
            ["DialogueId"] = 11011915,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B91324E",
            ["NextDialogue"] = 11011916,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91324E",
            },
        [11011916] = {
            ["Camera"] = "-4.320312,-54.229919,156.435608,2.0,-15.402834,-158.041519,40.0,60.997154,false,Manual,12.0",
            ["Content"] = "……往好处想，任务也到最后了。揍扁所有拦路的，想办法打开中央控制室的大门，把秘钥放进控制台，回收权限，一切就结束了。",
            ["ContentJP"] = "……任務が最終局面を迎えているのだけは救いと前向きに考えるか。妨害を仕掛けてくる者たちを殲滅後、用いる全ての手段で中央制御室のゲート開放を目指す。そして鍵を制御コンソールに挿入し、権限を掌握できれば終了だ。",
            ["DialogueId"] = 11011916,
            ["Duration"] = 3,
            ["FinalCamera"] = "-13.175781,-57.801208,153.804443,2.0,-15.402834,-158.041519,40.0,60.997154,false,Manual,12.0",
            ["GUID"] = "1B913278",
            ["NextDialogue"] = 11011936,
            ["Scripts"] = "SEQ{\
CameraMoveTo{_delay{6},TargetPosition{\"-46.275391,-86.162109,142.679993,-1.0,4.799451,-24.651934,45.0,129.592651,false,DoNotOverride,5.0\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-33.478516,-92.035095,143.405212,-1.0,4.799451,-24.651691,45.0,129.592651,false,DoNotOverride,5.0\"},duration{5}}\
}",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110022:Talk03_End",
                [2] = "110010:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B913278",
            },
        [11011917] = {
            ["Camera"] = "-22.394531,-48.055237,156.619995,0.00007,-7.800322,-164.04863,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……所以当务之急是解决前面的屏障吧。用这门炮轰开如何？",
            ["ContentJP"] = "……そのためには眼前のバリアをどうやって打ち破るのか、早急に考える必要がありますね。ここにあるイコルキャノンを使用するのは？",
            ["DialogueId"] = 11011917,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-14.953125,-45.923645,157.682129,0.00007,-7.800322,-164.04863,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9132A2",
            ["NextDialogue"] = 11011918,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A2",
            },
        [11011918] = {
            ["Camera"] = "-4.816406,-6.338318,179.877502,0.000095,-1.000575,-45.047215,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "这门炮作为底火的月髓刚好用光了，我正准备——",
            ["ContentJP"] = "ここのイコルキャノンはイコルをきっかり使い果たしていやがる。使用するには——",
            ["DialogueId"] = 11011918,
            ["Duration"] = 3,
            ["FinalCamera"] = "-21.675781,10.563416,180.294556,0.000095,-1.800533,-45.047245,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9132A3",
            ["NextDialogue"] = 11011919,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_End",
                [2] = "110010:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A3",
            },
        [11011919] = {
            ["Camera"] = "-54.783203,111.192444,135.942932,0.000055,-2.400723,-155.452408,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "小长官，小长官！",
            ["ContentJP"] = "お若い兵士様、お聞きくだされ。",
            ["DialogueId"] = 11011919,
            ["Duration"] = 3,
            ["FinalCamera"] = "-70.373047,102.649536,128.868347,0.000056,-0.40057,-152.8535,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9132A4",
            ["LookAt"] = {
                [1] = "110022:n(110017)，110017:n(110022",
                },
            ["NextDialogue"] = 11011920,
            ["SpeakNpcId"] = 110017,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "110022:n(110017)，110017:n(110022",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A4",
            },
        [11011920] = {
            ["Content"] = "听起来那位长官好像需要月髓，我知道最近放月髓的仓库在哪里。我可以带您去。",
            ["ContentJP"] = "わしはイコルの保管倉庫を把握しておりまする。イコルが必要であるならば……一番近い場所をご案内できますが……",
            ["DialogueId"] = 11011920,
            ["Duration"] = 3,
            ["GUID"] = "1B9132A5",
            ["NextDialogue"] = 11011921,
            ["SpeakNpcId"] = 110017,
            ["TalkActionId"] = {
                [1] = "110017:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A5",
            },
        [11011921] = {
            ["Camera"] = "-6.033203,-285.19043,132.766541,0.000062,-1.800199,143.14183,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……嗯……",
            ["ContentJP"] = "そうか……",
            ["DialogueId"] = 11011921,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-15.679688,-316.977051,130.002502,0.000064,-2.599884,137.739395,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9132A6",
            ["NextDialogue"] = 11011922,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110017:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A6",
            },
        [11011922] = {
            ["Content"] = "你跟我一起。",
            ["ContentJP"] = "どうか私と一緒に。",
            ["DialogueId"] = 11011922,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9132A7",
            ["LookAt"] = {
                [1] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11011923,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A7",
            },
        [11011923] = {
            ["Camera"] = "-209.833984,-22.960693,135.643921,0.000057,-2.800658,-139.652802,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……已经带您平安抵达了这里，您还是不肯信任我吗。",
            ["ContentJP"] = "……ここまで無事にお連れしました。まだ信用には足りえていませんか？",
            ["DialogueId"] = 11011923,
            ["Duration"] = 3,
            ["FinalCamera"] = "-164.667969,15.409241,138.542725,0.000057,-2.800658,-139.652802,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9132A8",
            ["LookAt"] = {
                [1] = "110034:n(110022)",
                },
            ["NextDialogue"] = 11011924,
            ["SpeakNpcId"] = 110034,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A8",
            },
        [11011924] = {
            ["Content"] = "抱歉，只是稍微有点……没事，我和您一起就是了。",
            ["ContentJP"] = "いえ、申し訳ございません。ただ少し心配で……大丈夫です、私も兵士様についていきます。",
            ["DialogueId"] = 11011924,
            ["Duration"] = 3,
            ["GUID"] = "1B9132A9",
            ["SpeakNpcId"] = 110034,
            ["TalkActionId"] = {
                [1] = "110034:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132A9",
            },
        [11011925] = {
            ["Content"] = "就是这儿了，长官。",
            ["ContentJP"] = "この場所でございまする、兵士様。",
            ["DialogueId"] = 11011925,
            ["Duration"] = 3,
            ["GUID"] = "1B9132AA",
            ["NextDialogue"] = 11011926,
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132AA",
            },
        [11011926] = {
            ["Content"] = "长官，我来帮您拿着吧。没关系，我什么重活都干过，力气很大的。",
            ["ContentJP"] = "兵士様、私が持ちます。ふふ、お任せください、もう色々と力仕事はこなして来ましたので。意外と力持ちなのですよ。",
            ["DialogueId"] = 11011926,
            ["Duration"] = 3,
            ["GUID"] = "1B9132AB",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011927,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132AB",
            },
        [11011927] = {
            ["Content"] = "……呃，不用吗……",
            ["ContentJP"] = "えっと……差し出がましかったでしょうか……",
            ["DialogueId"] = 11011927,
            ["Duration"] = 3,
            ["GUID"] = "1B9132AC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9132AC",
            },
        [11011928] = {
            ["Content"] = "这些月髓液真好看，透明的，亮晶晶的。",
            ["ContentJP"] = "イコル液って本当に綺麗ですよね……透明で、キラキラしていて……",
            ["DialogueId"] = 11011928,
            ["Duration"] = 3,
            ["GUID"] = "1B913470",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011929,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B913470",
            },
        [11011929] = {
            ["Content"] = "如果不是用来杀人的就好了。",
            ["ContentJP"] = "人を殺すために使われなければ……美しいだけなのに……",
            ["DialogueId"] = 11011929,
            ["Duration"] = 3,
            ["GUID"] = "1B91349A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011930,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91349A",
            },
        [11011930] = {
            ["Content"] = "……嗯。",
            ["ContentJP"] = "……ああ。",
            ["DialogueId"] = 11011930,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9134C4",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9134C4",
            },
        [11011931] = {
            ["Content"] = "好，找齐了。",
            ["ContentJP"] = "よし、これで揃った。",
            ["DialogueId"] = 11011931,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9134C5",
            ["NextDialogue"] = 11011932,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9134C5",
            },
        [11011932] = {
            ["Content"] = "长官，我们是不是很快就可以回家了？",
            ["ContentJP"] = "兵士様、これで私たちは家に帰ることをお許しいただけますか？",
            ["DialogueId"] = 11011932,
            ["Duration"] = 3,
            ["GUID"] = "1B9134C6",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011933,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9134C6",
            },
        [11011933] = {
            ["Content"] = "也许吧，但愿如此。",
            ["ContentJP"] = "恐らくは。そうであればいいと私も思っている。",
            ["DialogueId"] = 11011933,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9134C7",
            ["NextDialogue"] = 11011934,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9134C7",
            },
        [11011934] = {
            ["Content"] = "如果能活着回去，我想去服装店，买好多好多以前不舍得买的衣服。",
            ["ContentJP"] = "もし生きて帰ることができましたら……私は洋服屋さんに行こうと思っています。これまで我慢して買えなかった服を、いっぱい買ったりしてみたいのです。",
            ["DialogueId"] = 11011934,
            ["Duration"] = 3,
            ["GUID"] = "1B9134C8",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11011935,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9134C8",
            },
        [11011935] = {
            ["Content"] = "如果能有一双漂亮的袜子就更好了。",
            ["ContentJP"] = "素敵な靴下も揃えられるなら、もっと嬉しいのですが。",
            ["DialogueId"] = 11011935,
            ["Duration"] = 3,
            ["GUID"] = "1B9134C9",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B9134C9",
            },
        [11011936] = {
            ["Camera"] = "1265.860352,2012.351807,591.866943,-0.0,-10.39929,-120.446251,35.0,86.916473,false,DoNotOverride,2.2",
            ["Content"] = "不过麻烦的是，中央控制室的门没法从外侧打开……",
            ["ContentJP"] = "問題は中央制御室のゲート開閉を外から操作する手段がない点だが……",
            ["DialogueId"] = 11011936,
            ["Duration"] = 4,
            ["FinalCamera"] = "1315.114258,1983.400879,591.866943,-0.0,-10.39929,-120.446251,35.0,86.916473,false,DoNotOverride,2.2",
            ["GUID"] = "1B913279",
            ["NextDialogue"] = 11011937,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B913279",
            },
        [11011937] = {
            ["Camera"] = "262.451172,-426.251709,296.255249,0.000046,1.597902,-39.643715,35.0,100000.0,false,DoNotOverride,5.0",
            ["Content"] = "所以您在调试这门炮……",
            ["ContentJP"] = "それの打開策としてキャノンを使いたいわけですね……",
            ["DialogueId"] = 11011937,
            ["Duration"] = 7,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "289.830078,-393.212524,296.255249,0.000046,1.597902,-39.643715,35.0,100000.0,false,DoNotOverride,5.0",
            ["GUID"] = "1B91327A",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                },
            ["NextDialogue"] = 11018402,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91327A",
            },
        [11011939] = {
            ["Camera"] = "106.029297,82.120117,148.969055,0.000085,0.198506,-84.237144,35.000011,62.085716,false,DoNotOverride,10.0",
            ["Content"] = "长官，成功在附近仓库找到了罐装月髓液，已经按您的吩咐连接上剩下的髓动轮了。",
            ["ContentJP"] = "長官、近くの倉庫にてイコル液の保存タンクを発見しましたので、ご指示通りイコル駆動輪の供給に接続しました。",
            ["DialogueId"] = 11011939,
            ["FinalCamera"] = "108.123047,61.345215,149.04126,0.000085,0.198506,-84.237144,35.000011,62.085716,false,DoNotOverride,10.0",
            ["GUID"] = "1B91327C",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11011940,
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110020,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91327C",
            },
        [11011940] = {
            ["Camera"] = "37.863281,-121.802368,173.759277,0.000092,-6.001612,-26.831324,35.000011,62.085716,false,DoNotOverride,10.0",
            ["Content"] = "好……应该足够支持把这门炮运到中央控制室附近了。",
            ["ContentJP"] = "首尾は良好か……少なくともキャノンを中央制御室の付近まで運ぶのには足りるはずだ。",
            ["DialogueId"] = 11011940,
            ["FinalCamera"] = "43.78125,-124.801086,173.06073,0.000092,-6.001612,-26.831289,35.000011,62.085716,false,DoNotOverride,10.0",
            ["GUID"] = "1B91327D",
            ["Scripts"] = "SEQ{\
PlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}},\
PlayAnimation{ActorId{110010},AnimationId{\"Call_End\"},Duration{0}}\
}\
",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91327D",
            },
        [11012001] = {
            ["Content"] = "干得好，出发吧。把炮台开到轰击中央控制室的最佳位置。",
            ["ContentJP"] = "よくやった、急ぎ出発するか。キャノンを最適な位置まで運んで中央制御室のゲートをブッ飛ばすぞ。",
            ["DialogueId"] = 11012001,
            ["Duration"] = 3,
            ["GUID"] = "1B91406A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110120/1B91406A",
            },
        [11012002] = {
            ["Content"] = "嗯，多亏了这两位难民的帮助。",
            ["ContentJP"] = "ええ、難民のふたりのお陰で、首尾よく運べました。",
            ["DialogueId"] = 11012002,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B914094",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110120/1B914094",
            },
        [11012003] = {
            ["Content"] = "留意炮台，别让秽兽把它弄坏了。",
            ["ContentJP"] = "キャノンに気を配っておけよ。<Default note=\"text:エジュウ\">穢獣</>に壊されんようにな。",
            ["DialogueId"] = 11012003,
            ["Duration"] = 3,
            ["GUID"] = "1B9140BE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110120/1B9140BE",
            },
        [11012004] = {
            ["Content"] = "我们找个轰击中心区屏障的最佳位置。你盯着点，别让秽兽把炮台弄坏了。",
            ["ContentJP"] = "バリアへ向けてブッ放すのに最適な位置を確保しないとだな。穢獣にキャノンを壊されないよう見張る必要もある。",
            ["DialogueId"] = 11012004,
            ["Duration"] = 3,
            ["GUID"] = "1B9140E8",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110120/1B9140E8",
            },
        [11012005] = {
            ["Content"] = "当心秽兽！",
            ["ContentJP"] = "穢獣だ！気をつけろ！",
            ["DialogueId"] = 11012005,
            ["Duration"] = 3,
            ["GUID"] = "1B914112",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110120/1B914112",
            },
        [11012006] = {
            ["Content"] = "又来了，保护炮台！",
            ["ContentJP"] = "また来たか、キャノンを守れ！",
            ["DialogueId"] = 11012006,
            ["Duration"] = 3,
            ["GUID"] = "1B91413C",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110120/1B91413C",
            },
        [11012101] = {
            ["Content"] = "这里视野不错，停下吧。",
            ["ContentJP"] = "見晴らしのいい場所だな。よし、停止だ。",
            ["DialogueId"] = 11012101,
            ["Duration"] = 3,
            ["GUID"] = "1B9150D2",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11012102,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B9150D2",
            },
        [11012102] = {
            ["Content"] = "接下来，我们就用这门月髓炮轰击前面的屏障。",
            ["ContentJP"] = "これより我々は前進を阻むバリアに対し、イコルキャノンで砲撃を行う。",
            ["DialogueId"] = 11012102,
            ["Duration"] = 3,
            ["GUID"] = "1B9150FC",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B9150FC",
            },
        [11012103] = {
            ["Content"] = "有秽兽被吸引过来了，直接开炮吧。",
            ["ContentJP"] = "穢獣め、しつこいヤツらだな。直接砲撃してしまえ。",
            ["DialogueId"] = 11012103,
            ["Duration"] = 3,
            ["GUID"] = "1B915126",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B915126",
            },
        [11012104] = {
            ["Content"] = "好硬的屏障。",
            ["ContentJP"] = "優秀なバリアですね。",
            ["DialogueId"] = 11012104,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B915150",
            ["NextDialogue"] = 11012105,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B915150",
            },
        [11012105] = {
            ["Content"] = "连月髓炮都能抗住，工程炼金院那帮人的技术还真是有两下子……",
            ["ContentJP"] = "イコルキャノンさえ防ぎやがるとは、工学錬金院の技術はなかなかのものだな……",
            ["DialogueId"] = 11012105,
            ["Duration"] = 3,
            ["GUID"] = "1B91517A",
            ["NextDialogue"] = 11012106,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B91517A",
            },
        [11012106] = {
            ["Content"] = "不要停，继续轰击，记得换高爆弹。",
            ["ContentJP"] = "手を止めるなよ、砲撃を続けるんだ。それと次弾は榴弾に切り替えておけ。",
            ["DialogueId"] = 11012106,
            ["Duration"] = 3,
            ["GUID"] = "1B9151A4",
            ["NextDialogue"] = 11012107,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B9151A4",
            },
        [11012107] = {
            ["Content"] = "就算轰不破这面屏障，我们也能让里面的家伙自己把门打开。",
            ["ContentJP"] = "衝撃を与え続ければバリアを突破できずとも籠っている連中は炙り出せる。自らゲートを開けさせようじゃないか。",
            ["DialogueId"] = 11012107,
            ["Duration"] = 3,
            ["GUID"] = "1B9151CE",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B9151CE",
            },
        [11012108] = {
            ["Content"] = "有什么人从侧边跑出来了——是同盟的家伙！",
            ["ContentJP"] = "側方より何者かが出現——同盟のヤツらだ！",
            ["DialogueId"] = 11012108,
            ["Duration"] = 3,
            ["GUID"] = "1B9151F8",
            ["NextDialogue"] = 11012109,
            ["SpeakNpcId"] = 110015,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B9151F8",
            },
        [11012109] = {
            ["Content"] = "差不多了，过去看看吧。",
            ["ContentJP"] = "そろそろか。行くぞ。",
            ["DialogueId"] = 11012109,
            ["Duration"] = 3,
            ["GUID"] = "1B915222",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B915222",
            },
        [11012110] = {
            ["Content"] = "喂，别玩儿了，快来这边！",
            ["ContentJP"] = "おい、遊んでないで、早くこっちへ来んか！",
            ["DialogueId"] = 11012110,
            ["Duration"] = 3,
            ["GUID"] = "1B91524C",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110121/1B91524C",
            },
        [11012201] = {
            ["Camera"] = "-507.54541,-397.79126,-135.757874,0.000019,-8.799681,31.148724,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "他们真的自己打开了门……",
            ["ContentJP"] = "連中、本当に自らゲートを開けましたね……",
            ["DialogueId"] = 11012201,
            ["Duration"] = 3,
            ["FinalCamera"] = "-65.992188,-135.824219,-212.646179,0.000021,-7.799652,29.548767,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B91618C",
            ["NextDialogue"] = 11012202,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110122/1B91618C",
            },
        [11012202] = {
            ["Content"] = "留在里面受到的冲击更大，他们多半撑不住的。",
            ["ContentJP"] = "中で受ける衝撃は外から見た印象よりも遥かに大きい。大半のヤツは耐えられんさ。",
            ["DialogueId"] = 11012202,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B91618D",
            ["NextDialogue"] = 11012203,
            ["SpeakNpcId"] = 110022,
            ["TurnTo"] = {
                [1] = "110010:n(110022)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110122/1B91618D",
            },
        [11012203] = {
            ["Content"] = "我和{nickname2}走前面，其他人小心跟上！",
            ["ContentJP"] = "{nickname2}と俺、2名が先行する！他の者は周囲を警戒しつつ後に続け！",
            ["DialogueId"] = 11012203,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B91618E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110122/1B91618E",
            },
        [11012301] = {
            ["Content"] = "蹲下干什么？怎么不走了？",
            ["ContentJP"] = "しゃがんで何をしてる？どうして進まない？",
            ["DialogueId"] = 11012301,
            ["Duration"] = 3,
            ["GUID"] = "1B9171F4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11012302,
            ["SpeakNpcId"] = 110015,
            ["VoiceName"] = "voice/$Locale$/story/1002/110123/1B9171F4",
            },
        [11012302] = {
            ["Content"] = "卡嘉？",
            ["ContentJP"] = "カーチャ？",
            ["DialogueId"] = 11012302,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9171F5",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110123/1B9171F5",
            },
        [11012303] = {
            ["Content"] = "我亲爱的长官，别急，请让我稍微准备一下——",
            ["ContentJP"] = "親愛なる隊長様、どうか焦らず……もう少しだけ準備させてください——",
            ["DialogueId"] = 11012303,
            ["Duration"] = 3,
            ["GUID"] = "1B9171F6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11012304,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110123/1B9171F6",
            },
        [11012304] = {
            ["Content"] = "嗯，准备好啦！",
            ["ContentJP"] = "えぇ、もう準備は終わったわ！",
            ["DialogueId"] = 11012304,
            ["Duration"] = 3,
            ["GUID"] = "1B917220",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110123/1B917220",
            },
        [11012401] = {
            ["Camera"] = "34.176025,-39.523438,173.482391,0.000113,-24.600769,-88.793587,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你这疯女人！笑什么笑，你对队长恩将仇报，就一点都不忏悔吗？",
            ["ContentJP"] = "このイカレ女め、何を笑ってやがんだ！！恩を仇で返した挙句に少しの懺悔もできないってのか？",
            ["DialogueId"] = 11012401,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110009:Smile01",
                },
            ["FinalCamera"] = "45.875854,-39.736328,173.482391,0.000107,-24.800785,-95.193405,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B91820A",
            ["NextDialogue"] = 11012402,
            ["RelatedWikiId"] = {
                [1] = 204001,
                [2] = 201013,
                [3] = 201015,
                [4] = 408007,
                [5] = 101004,
                },
