            ["TalkActionId"] = {
                [1] = "110009:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B9182DC",
            },
        [11012407] = {
            ["Content"] = "找我干什么？向我展示海伯利亚军官老爷不计前嫌的大度？还是假惺惺地惋惜一下我这个“误入歧途”的可怜小姑娘，想要“拯救”我啊？",
            ["ContentJP"] = "私に何かご用？過去のことは水に流そうって寛大さを見せてくれるのかなぁ？それとも「道を外した」哀れな小娘に心を痛めながら「救おう」と決意していたりぃ？",
            ["DialogueId"] = 11012407,
            ["FacialId"] = {
                [1] = "110009:Happy01",
                },
            ["GUID"] = "1B918306",
            ["LookAt"] = {
                [1] = "110022:n(110009)",
                },
            ["NextDialogue"] = 11012408,
            ["Scripts"] = "PARA{\
SEQ{\
