        [11012423] = {
            ["Camera"] = "67.383972,-41.145508,109.074097,0.000133,16.40362,124.389236,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "被你摆了这么一遭，总得告诉我是为什么吧？这是针对海伯利亚士兵的袭击，还是针对我个人的刺杀？",
            ["ContentJP"] = "{性别2:お前が企てた計画の被害者である以上、理由を聞きたくなるのは道理だろう？ヒュペリア兵士を無差別に狙っての襲撃なのか？私個人を狙っての暗殺なのか？目的を教えてくれ。|お前が企てた計画の被害者である以上、理由を聞きたくなるのは道理でしょう？ヒュペリア兵士を無差別に狙っての襲撃なの？私個人を狙っての暗殺なの？目的を教えて。}",
            ["DialogueId"] = 11012423,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:None",
                },
            ["FinalCamera"] = "59.581787,-46.003906,109.074097,0.000143,15.403538,117.789177,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B9185A6",
            ["NextDialogue"] = 11012424,
            ["Scripts"] = "SEQ{	\
	PlayAnimation{_delay{2},ActorId{110022},AnimationId{\"Explain01_Start\"},Duration{6}}\
		}",
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B9185A6",
            },
        [11012424] = {
            ["Camera"] = "50.555542,84.171387,71.75116,5.000197,8.604228,-107.607498,15.610331,100000.0,false,Manual,22.0",
            ["Content"] = "这个啊……行，告诉你——看在你让我寻了个开心的份上，就当做额外奖励吧。",
            ["ContentJP"] = "あーそんなこと……ま、いっか、教えてあげるわ——あんたのマヌケ面が結構笑えたから、そのお礼としてねぇ。",
            ["DialogueId"] = 11012424,
            ["FacialId"] = {
                [1] = "110009:Smile01",
                },
            ["FinalCamera"] = "60.200439,80.97168,70.87262,5.000216,8.204218,-108.407532,15.610331,100000.0,false,Manual,22.0",
            ["GUID"] = "1B9185D0",
            ["NextDialogue"] = 11012425,
            ["Scripts"] = "SEQ{	\
	PlayAnimation{_delay{1},ActorId{110009},AnimationId{\"AgreeHead\"},Duration{4}},\
	PlayAnimation{ActorId{110009},AnimationId{\"Talk03_Start\"},Duration{6}}\
		}",
            ["SpeakNpcId"] = 110009,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B9185D0",
            },
        [11012425] = {
            ["Camera"] = "70.837952,-130.941895,139.360352,5.001442,-5.595973,131.590164,15.0,174.765015,false,Manual,8.726983",
            ["Content"] = "同盟就是想要海伯利亚的走狗们都死在这里，而且最好是死在自己造出来的杀人机器里——喜欢吗？我们准备的大礼？",
            ["ContentJP"] = "同盟としてはヒュペリアの手先全員をここで皆殺しにしたかったの。自分たちの用意した殺人要塞で死ぬことになるとか痛快愉快だしぃ——ねえどうだったかなぁ？私たちが用意したビッグサプライズは！",
            ["DialogueId"] = 11012425,
            ["Duration"] = 3,
            ["FinalCamera"] = "65.503906,-135.757812,138.734558,5.001442,-5.595973,131.590164,15.0,174.765015,false,Manual,8.726983",
            ["GUID"] = "1B9185FA",
            ["NextDialogue"] = 11012426,
            ["SpeakNpcId"] = 110009,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110124/1B9185FA",
            },
        [11012426] = {
            ["Camera"] = "58.501587,-26.595215,105.298645,0.000128,17.4041,-101.210243,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "至于我本人……我呀，当然是为了<H>你</>而来的！",
            ["ContentJP"] = "それから私自身はっていうとぉ……私はねぇ、当然<H>テメェ</>を狙ってぶっ殺そうとしたに決まってんじゃん！",
            ["DialogueId"] = 11012426,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110009:Happy02",
                },
            ["FinalCamera"] = "56.160217,-38.411133,109.074097,0.000128,17.4041,-101.210243,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B918624",
            ["NextDialogue"] = 11012427,
