        [11012456] = {
            ["Camera"] = "-14.494629,-247.046387,127.962891,0.000166,-0.200958,77.201035,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你还记得，在去炮台的路上，我对你说过的吗？“你会因为自己的善良得到报答”。",
            ["ContentJP"] = "砲台へ向かう道中で話した言葉、まだ覚えてる？「兵士様はきっと報われますー自分の優しさでー！」ってヤツ。",
            ["DialogueId"] = 11012456,
            ["Duration"] = 3,
            ["FinalCamera"] = "-30.220276,-242.865723,127.962891,0.000166,-0.000949,73.200394,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B918B10",
