            ["NextDialogue"] = 11013608,
            ["RelatedWikiId"] = {
                [1] = 201016,
                },
            ["Scripts"] = "PlayAnimation{_delay{4},ActorId{110011},AnimationId{\"Talk02_End\"},Duration{3}}",
            ["SpeakNpcId"] = 110011,
            ["TalkActionId"] = {
                [1] = "110011:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B9247E6",
            },
        [11013608] = {
            ["Camera"] = "45.629196,-553.193359,13.620331,0.000056,8.603962,74.588776,20.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是，我在门外随时待命。",
            ["ContentJP"] = "承知しました。ゲートの外に控えておきますのでいつでもお声がけを。",
            ["DialogueId"] = 11013608,
