            ["VoiceName"] = "voice/$Locale$/story/1002/110136/1B924A5C",
            },
        [11013624] = {
            ["Camera"] = "-62.074799,-566.730469,491.808014,-0.001556,-31.999592,75.647636,16.661533,100000.0,false,Manual,22.0",
            ["Content"] = "等一下！",
            ["ContentJP"] = "待て！",
            ["DialogueId"] = 11013624,
            ["Duration"] = 3,
            ["GUID"] = "1B924A86",
            ["LookAt"] = {
                [1] = "110011:n(110010)",
