        [11014005] = {
            ["Camera"] = "-501.787109,-1215.910156,49.703491,0.000052,38.595211,59.516899,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "龙莎要塞全体十三军团士兵听令。现通缉前“狮鹫”小队医务员、神弃者同盟间谍达芙涅·塞奥多尔。",
            ["ContentJP"] = "ロンザ要塞に残存している第十三軍団の兵士全員に命じます。フォーセイクン同盟のスパイであることが判明した元「<Default note=\"text:グリフィン\">鷲獅子</>」隊医務官ダフネ・セオドールは、現時刻より指名手配犯となりました。",
            ["DialogueId"] = 11014005,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["FinalCamera"] = "-580.382324,-1169.650391,49.703491,0.000052,38.595211,59.516899,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "1B928932",
            ["NextDialogue"] = 11014006,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_Broadcast",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110140/1B928932",
            },
        [11014006] = {
