        [11014304] = {
            ["Camera"] = "188.189941,22.199753,132.788391,0.000101,5.599874,20.424314,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我知道了。",
            ["ContentJP"] = "……ですね。",
            ["DialogueId"] = 11014304,
            ["Duration"] = 3,
            ["GUID"] = "1B92BA40",
            ["NextDialogue"] = 11014305,
            ["SpeakNpcId"] = 110005,
