            },
        [11014305] = {
            ["Camera"] = "188.189941,22.199753,132.788391,0.000101,5.599874,20.424314,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要小心这里的士兵。这里很可能已经没有“战友”，只有“敌人”了。",
            ["ContentJP"] = "兵士を発見した際にはご警戒を。まず「敵」であると考えるべきかと……すでに「戦友」ではなく。",
            ["DialogueId"] = 11014305,
            ["Duration"] = 3,
            ["GUID"] = "1B92BA6A",
            ["LookAt"] = {
                [1] = "110005:n(110022)",
                },
            ["Scripts"] = "PARA{\
SEQ{\
CameraMoveTo{_delay{2},TargetPosition{\"264.104858,4.391851,125.635437,0.000112,7.79972,139.222382,50.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"249.126114,17.308903,128.344788,0.000113,7.79972,139.222321,50.000008,100000.0,false,DoNotOverride,2.8\"},duration{8}}\
},PlayAnimation{_delay{5},ActorId{110022},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BA6A",
            },
        [11014306] = {
            ["Content"] = "警告，无通行权限，无通行权限。",
            ["ContentJP"] = "警告、あなたには通行の権限がありません、あなたには通行の権限がありません。",
            ["DialogueId"] = 11014306,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "ELECTRIC",
            ["GUID"] = "1B92BA94",
            ["NextDialogue"] = 11014307,
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BA94",
            },
        [11014307] = {
            ["Content"] = "……他们这么快就删除了我们的权限……",
            ["ContentJP"] = "こんなにも早く……私たちの権限が削除されるなんて……",
            ["DialogueId"] = 11014307,
            ["Duration"] = 3,
            ["GUID"] = "1B92BABE",
            ["NextDialogue"] = 11014308,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BABE",
            },
        [11014308] = {
            ["Content"] = "发现目标了！在这里！",
            ["ContentJP"] = "目標を発見！ここだ！",
            ["DialogueId"] = 11014308,
            ["Duration"] = 3,
            ["GUID"] = "1B92BAE8",
            ["NextDialogue"] = 11014309,
            ["SpeakNpcName"] = "UI_Npc_WhaleSoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BAE8",
            },
        [11014309] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11014309,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B92BB12",
            ["NextDialogue"] = 11014310,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110143/1B92BB12",
            },
        [11014310] = {
            ["Content"] = "打晕他们，用他们的秘钥开门。",
