        [11014402] = {
            ["Camera"] = "37.388428,234.120605,23.369995,-9.010153,3.999574,178.72345,13.358559,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "说实在的，我……我现在脑袋很乱，很乱。",
            ["ContentJP"] = "しょ、正直言うと、わ……私、今、ぐちゃぐちゃで、混乱していて。",
            ["DialogueId"] = 11014402,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
            ["FinalCamera"] = "27.15918,234.347656,24.085571,-9.010153,3.999574,178.72345,13.358559,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B92CA54",
            ["NextDialogue"] = 11014403,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{110005},AnimationId{\"Sigh_End\"},Duration{2}},PlayAnimation{ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1}}}",
            ["SpeakNpcId"] = 110005,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CA54",
            },
        [11014403] = {
            ["Camera"] = "3.711914,201.639648,77.724976,0.000011,-22.200401,-176.477524,38.709583,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "他死了，父……阿瓦尔长官。死了。外边的士兵，海伯利亚的士兵，要杀掉我。他们说，我是间谍。我不知道……我不知道……",
            ["ContentJP"] = "死んでしまったの、お父……アヴァール長官が。死んで、しまって……外の兵士は、ヒュペリアの兵士が私を殺そうとしているの。あの人たち、私のことスパイだって。どうしよう……どうしましょう……",
            ["DialogueId"] = 11014403,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110005:Sad01",
                },
            ["FinalCamera"] = "3.711914,201.639648,88.750854,0.000011,-22.200401,-176.477524,38.709583,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B92CA7E",
            ["NextDialogue"] = 11014404,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{110005},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{_delay{1},ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{110005},AnimationId{\"Sigh_End\"},Duration{2}},\
LookAt{LookAtDescription{\"110005:p(P11014403)\"}},\
PlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{2}},\
PlayAnimation{_delay{8},ActorId{110005},AnimationId{\"DisagreeHead\"},Duration{1}},\
LookAt{_delay{1},LookAtDescription{\"110005:n(110022)\"}}\
}",
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CA7E",
            },
        [11014404] = {
            ["Camera"] = "-88.27002,103.208984,34.547974,0.000074,-7.599576,87.918869,13.462664,136.822205,false,Manual,22.0",
            ["Content"] = "我请求您……请求您告诉我……我可以信任您……只要您这么说，我就会相信。",
            ["ContentJP"] = "どうか……教えて……あなたのことは信用していますから……あなたが話す言葉だけを……私は信じるから。",
            ["DialogueId"] = 11014404,
            ["GUID"] = "1B92CAA8",
            ["NextOptions"] = {
                [1] = 11014405,
                [2] = 11014406,
                },
            ["Scripts"] = "SEQ{PlayAnimation{_delay{1},ActorId{110005},AnimationId{\"Explain02_End\"},Duration{1}},CameraMoveTo{_delay{3},TargetPosition{\"5.080566,190.669922,1.12085,3.600006,16.199665,176.318161,35.000008,128.714386,false,Manual,22.0\"},duration{0}}}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CAA8",
            },
        [11014405] = {
            ["Content"] = "（轻轻拥抱她。告诉她可以信任你。）",
            ["ContentJP"] = "（そっと彼女を抱きしめて、自分を信頼するよう伝える）",
            ["DialogueId"] = 11014405,
            ["GUID"] = "1B92CAD2",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 110144071,
            },
        [11014406] = {
            ["Content"] = "（她太依赖自己了——让她靠自己的力量坚强起来。）",
            ["ContentJP"] = "（彼女は私頼りになってしまっている——自分の力で強く立ってもらわなければ）",
            ["DialogueId"] = 11014406,
            ["GUID"] = "1B92CAFC",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 11014407,
            },
        [11014407] = {
            ["Camera"] = "24.679199,230.498535,34.460815,0.000049,-0.400242,-167.066864,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11014407,
