                },
            ["NextDialogue"] = 11014408,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{110005},AnimationId{\"Explain02_Start\"},Duration{2}},\
SetLocation{ActorId{110022},TargetPoint{\"nanzhu_hugset2\"},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CB26",
            },
        [11014408] = {
            ["Camera"] = "366.595215,-356.056641,24.533936,0.00005,-2.200284,127.312248,35.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我、我冷静下来了。抱歉，明明是您受了这么重的伤……",
            ["ContentJP"] = "わ、私、何を言って。ごめんなさい、もう落ち着きました。あなたは大怪我をしているっていうのに……",
            ["DialogueId"] = 11014408,
            ["FacialId"] = {
                [1] = "110005:None",
                },
            ["GUID"] = "1B92CB50",
            ["LookAt"] = {
                [1] = "110005:n(110022)",
                },
            ["NextDialogue"] = 11014409,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{110005},AnimationId{\"AgreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CB50",
            },
        [11014409] = {
            ["Camera"] = "124.651611,286.081543,35.425293,0.000024,-1.799925,-163.283066,35.000011,498.109375,false,Manual,22.0",
            ["Content"] = "之前您帮我找的药剂还留有一些。我来为您紧急处理一下伤口。",
            ["ContentJP"] = "捜索して見つけてくださった薬剤がまだ少し残っています。傷口の応急処置を行ってもいいでしょうか。",
            ["DialogueId"] = 11014409,
            ["FacialId"] = {
                [1] = "110005:Smile01",
                },
            ["GUID"] = "1B92CB7A",
            ["NextDialogue"] = 11014410,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CB7A",
            },
        [11014410] = {
            ["Content"] = "先不要走，药剂生效还需要些时间……我先告诉您外面发生的事吧。",
            ["ContentJP"] = "まだ動かないでくださいね。薬が効能を発揮するまでには、もう少しだけ時間がかかりますから……その間に、外で何が起きていたのかをお話しさせてください。",
            ["DialogueId"] = 11014410,
            ["FacialId"] = {
                [1] = "110005:None",
                },
            ["GUID"] = "1B92CBA4",
            ["NextDialogue"] = 11014411,
            ["SpeakNpcId"] = 110005,
            ["TalkActionId"] = {
                [1] = "110005:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CBA4",
            },
        [11014411] = {
            ["Content"] = "没处理干净？漏了一个？",
            ["ContentJP"] = "完璧には処理できなかったと？ひとり取り逃したのですね？",
            ["DialogueId"] = 11014411,
            ["GUID"] = "1B92CBCE",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
            ["NextDialogue"] = 11014412,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110012,
            ["TalkActionId"] = {
                [1] = "110005:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CBCE",
            },
        [11014412] = {
            ["Content"] = "是，一名女性医务员，达芙涅·塞奥多尔。先遣小队的伤兵不要命地拖延时间，让她跑了。",
            ["ContentJP"] = "はい、女性医務官1名、ダフネ・セオドール。先遣隊所属の負傷兵らが彼女を逃がした模様です。",
            ["DialogueId"] = 11014412,
            ["GUID"] = "1B92CBF8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014413.T_Story_Recall_11014413'",
            ["NextDialogue"] = 11014413,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CBF8",
            },
        [11014413] = {
            ["Content"] = "现在“一角鲸”分队已经开始陆续进入要塞，但清理先遣小队的事不能让我们之外的人知道。一旦达芙涅向他们求助，事情就难办了。",
            ["ContentJP"] = "現在「<Default note=\"text:ナーファル\">一角鯨</>」隊が続々と要塞内に侵襲を開始。先遣隊の粛清は秘密裏に進めておりますので、ダフネ・セオドールが彼らに接触した場合は事態が複雑化します。",
            ["DialogueId"] = 11014413,
            ["GUID"] = "1B92CC22",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
            ["NextDialogue"] = 11014414,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CC22",
            },
        [11014414] = {
            ["Content"] = "而且，因为战局不顺，西比尔军团长也在赶来龙莎要塞的路上。情况现在有些棘手，不过好在最关键的阿瓦尔已经死了。",
            ["ContentJP"] = "更に戦局の悪化からシビル軍団長がロンザ要塞に急行中との情報も入っております。些か息苦しい状況ではありますが、肝心のアヴァールを始末できているのは幸いかと。",
            ["DialogueId"] = 11014414,
            ["GUID"] = "1B92CC4C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
            ["NextDialogue"] = 11014415,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CC4C",
            },
        [11014415] = {
            ["Content"] = "至于达芙涅这个人，您的意思是……",
            ["ContentJP"] = "それでダフネ・セオドールに関して、フォルス様のご意志を伺いたく……",
            ["DialogueId"] = 11014415,
            ["Duration"] = 1,
            ["GUID"] = "1B92CC76",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014411.T_Story_Recall_11014411'",
            ["NextDialogue"] = 11014416,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CC76",
            },
        [11014416] = {
            ["Content"] = "传富尔维斯指挥官的命令下去，要塞全面戒严，搜寻并处决达芙涅·塞奥多尔。理由……一样吧，“勾结神弃者同盟，以间谍身份潜入军团，扰乱要塞进攻计划”。",
            ["ContentJP"] = "フルヴィス総司令のご命令です。要塞に厳戒態勢を敷いてダフネ・セオドールを捜索してください。発見次第処刑を……理由は彼と同じにしましょう。「フォーセイクン同盟と結託、スパイとして帝国軍に潜入、要塞の攻撃計画を混乱させた」と。",
            ["DialogueId"] = 11014416,
            ["GUID"] = "1B92CCA0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014416.T_Story_Recall_11014416'",
            ["NextDialogue"] = 11014417,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110144/1B92CCA0",
            },
        [11014417] = {
            ["Content"] = "是。",
            ["ContentJP"] = "了解です。",
            ["DialogueId"] = 11014417,
            ["Duration"] = 1,
            ["GUID"] = "1B92CCCA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11014416.T_Story_Recall_11014416'",
            ["NextDialogue"] = 11014418,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_Npc_EnemySoldier",
