        [11014432] = {
            ["Camera"] = "825.23584,-925.32959,105.616943,0.000043,-7.198575,129.922852,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "走吧。只要我们活着，富尔维斯这笔债迟早会讨回来。",
            ["ContentJP"] = "{性别2:行くぞ|行こう}、私たちが生き残ったら必ず貸しを返させてやる。いつの日かフルヴィスに。",
            ["DialogueId"] = 11014432,
