            },
        [11014601] = {
            ["Content"] = "达芙涅·塞奥多尔和不知名同伙躲进了地下水道，现在在1号储水池附近。",
            ["ContentJP"] = "ダフネ・セオドールが氏名不詳の協力者とともに地下水路へ逃げ込みました。現在は1号貯水池の付近に潜伏している模様です。",
            ["DialogueId"] = 11014601,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["GUID"] = "1B92EAFA",
            ["NextDialogue"] = 11014602,
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110146/1B92EAFA",
            },
        [11014602] = {
            ["Content"] = "向1号储水池放水，逼他们出来！",
            ["ContentJP"] = "貯水池1号へ直ちに放水を！ヤツらを炙り出せ！",
            ["DialogueId"] = 11014602,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["Duration"] = 3,
            ["GUID"] = "1B92EB24",
            ["NextDialogue"] = 11014603,
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110146/1B92EB24",
            },
        [11014603] = {
            ["Content"] = "还是被发现了……我们得在这里被淹没之前离开！",
            ["ContentJP"] = "やはり尻尾は掴まれていますね……水没する前にここから離れないと！",
            ["DialogueId"] = 11014603,
            ["Duration"] = 3,
            ["GUID"] = "1B92EB4E",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110146/1B92EB4E",
            },
        [11014701] = {
            ["Content"] = "当前水位高于预定值，无法开启安全门，请调整水位后再试。",
            ["ContentJP"] = "水位が規定値を上回っているため、セキュリティゲートを開放できません。水位を調整してから再度お試しください。",
            ["DialogueId"] = 11014701,
            ["Duration"] = 3,
            ["GUID"] = "1B92FB62",
            ["NextDialogue"] = 11014702,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110147/1B92FB62",
            },
        [11014702] = {
            ["Content"] = "进水机关被他们控制了……但这里既然是储水池，肯定还有排水机关！",
            ["ContentJP"] = "水の流入機構は敵によって制御されています……ですが貯水池であるならば、どこかに必ず排水機構もあるはずです！",
            ["DialogueId"] = 11014702,
            ["Duration"] = 3,
            ["GUID"] = "1B92FB8C",
            ["NextDialogue"] = 11018915,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110147/1B92FB8C",
            },
        }
  end },
  { MinKey = 11014803, MaxKey = 11016825, Loader = function()
      return {
        [11014803] = {
            ["Content"] = "他们跑不了多远！把剩下的秽兽也赶到地下去！",
            ["ContentJP"] = "そう遠くまで逃れるのは不可能です！残っていた<Default note=\"text:エジュウ\">穢獣</>も地下へと追い立ててください！",
            ["DialogueId"] = 11014803,
