            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110148/1B930C1E",
            },
        [11014804] = {
            ["Content"] = "封锁所有地下出口，等叛徒出来，即刻处决。",
            ["ContentJP"] = "全ての地下出口を封鎖し、裏切り者は見つけ次第、即時処刑せよ！",
            ["DialogueId"] = 11014804,
