            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935DD2",
            },
        [11015307] = {
            ["Camera"] = "175.138626,16.254257,-15.015625,0.000019,25.795355,-21.761339,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……你清楚自己在说什么吗？",
            ["ContentJP"] = "……言葉の意味を、自分で理解はできているのか？",
            ["DialogueId"] = 11015307,
            ["Duration"] = 3,
            ["GUID"] = "1B935ECE",
            ["NextDialogue"] = 11015308,
            ["SpeakNpcId"] = 110039,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935ECE",
            },
        [11015308] = {
            ["Camera"] = "389.865051,85.663879,11.320312,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我清楚。我正式指控安东尼·富尔维斯，他是龙莎要塞一案真正的幕后黑手。",
            ["ContentJP"] = "もちろんそのつもり{性别2:だが|}。私はアンソニー・フルヴィスを正式に告訴する。彼こそがロンザ要塞事件の真の黒幕{性别2:だ|}。",
            ["DialogueId"] = 11015308,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Unhappy02",
                },
            ["FinalCamera"] = "378.377686,84.125763,12.214844,0.0,4.395124,-172.362595,25.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B935EF8",
            ["NextDialogue"] = 11015309,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_Start",
                [2] = "110039:Sit_Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935EF8",
            },
        [11015309] = {
            ["Camera"] = "138.132721,33.639923,-21.648438,0.000026,20.39575,-25.164968,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你知不知道，如果你对富尔维斯上校的指控不实，你将面临什么刑罚？",
            ["ContentJP"] = "フルヴィス大佐への告発が虚偽であった場合、いかほどの刑罰を受けることになるのかも承知の上で？",
            ["DialogueId"] = 11015309,
            ["Duration"] = 3,
            ["FinalCamera"] = "144.695236,30.554977,-26.570312,0.000028,20.395737,-25.163847,25.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B935F22",
            ["NextDialogue"] = 11015310,
            ["SpeakNpcId"] = 110039,
            ["TalkActionId"] = {
                [1] = "110022:Talk02_End",
                [2] = "110039:Sit_Talk03ToTalkR_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935F22",
            },
        [11015310] = {
            ["Camera"] = "149.444336,-10.450867,-8.71875,0.000056,9.995599,-179.96492,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……诬陷罪，十年监禁。",
            ["ContentJP"] = "……虚偽告訴罪により、10年の拘禁。",
            ["DialogueId"] = 11015310,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110039:None",
                [2] = "110022:None",
                },
            ["FinalCamera"] = "118.790039,-10.450943,-3.3125,0.000056,9.995599,-179.96492,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B935F4C",
            ["NextDialogue"] = 11015311,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk03ToTalkR_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935F4C",
            },
        [11015311] = {
            ["Camera"] = "-75.674171,170.735184,471.796875,0.000076,-53.397903,-27.591795,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "回答错误，是叛国罪、间谍罪和诬陷罪。",
            ["ContentJP"] = "違います。国家反逆罪、外患罪、虚偽告訴罪の併合罪となります。",
            ["DialogueId"] = 11015311,
            ["Duration"] = 3,
            ["FinalCamera"] = "-56.026688,160.466644,454.570312,0.00008,-53.397835,-27.591671,15.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B935F76",
            ["NextDialogue"] = 11015312,
            ["SpeakNpcId"] = 110021,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935F76",
            },
        [11015312] = {
            ["Camera"] = "135.673386,220.094009,-5.660156,-0.99997,17.801788,-36.789379,35.000008,1.5,false,DoNotOverride,1.2",
            ["Content"] = "你会被处以帝国的最高极刑——以荆棘藤条倒悬着钉在迪斯玛尼亚市中心的天之树上公开行刑，直至咽气。",
            ["ContentJP"] = "あなたは帝国における極刑に処されます——ディズマニアの中心部にて逆さ吊りの公開処刑。命の続く限りあなたは、茨のツルで天上樹に括りつけられるのですよ。",
            ["DialogueId"] = 11015312,
            ["Duration"] = 3,
            ["FinalCamera"] = "141.826721,215.4944,-3.203125,-0.99997,17.801788,-36.789379,35.000008,1.5,false,DoNotOverride,1.2",
            ["GUID"] = "1B935FA0",
            ["NextDialogue"] = 11015313,
            ["RelatedWikiId"] = {
                [1] = 407002,
                },
            ["SpeakNpcId"] = 110021,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935FA0",
            },
        [11015313] = {
            ["Camera"] = "-13.288574,747.44519,159.546875,-1.0,-6.197686,-87.991653,15.0,1.5,false,DoNotOverride,1.2",
            ["Content"] = "我说的全部都是事实。既然你们选择对我和达芙涅·塞奥多尔分开审讯，就应该知道，我们的证词完全可以互证。",
            ["ContentJP"] = "私は全て事実しか述べていない。ダフネ・セオドールも私と同じことしか言わない{性别2:ぞ|}。別々に尋問するのを選んだ以上は、私たちの証言が一致する事実の加味も忘れないで{性别2:くれ|}。",
            ["DialogueId"] = 11015313,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "24.04541,748.68158,160.195312,-1.0,-6.197686,-87.991653,15.0,1.5,false,DoNotOverride,1.2",
            ["GUID"] = "1B935FCA",
            ["NextDialogue"] = 11015314,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935FCA",
            },
        [11015314] = {
            ["Camera"] = "435.769226,121.471558,121.855469,0.000029,-17.19808,-165.965164,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你本来就受了不轻的伤，又挨了刑讯，还能硬撑着不改口，勇气可嘉。",
            ["ContentJP"] = "お前はもともと重傷を負っていた。その上で拷問を受けても頑なに言い分を変えない。大した気概の持ち主だ。",
            ["DialogueId"] = 11015314,
            ["Duration"] = 3,
            ["FinalCamera"] = "435.769226,121.471558,108.164062,0.000029,-17.19808,-165.96492,20.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B935FF4",
            ["NextDialogue"] = 11019005,
            ["SpeakNpcId"] = 110039,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B935FF4",
            },
        [11015315] = {
            ["Camera"] = "168.701141,10.085297,-15.542969,-0.999999,21.599749,-14.160914,20.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "审讯官，准备新的审讯——用“炼火之狱”。",
            ["ContentJP"] = "尋問官、新たな尋問に取りかかるぞ——「煉火の獄」だ！",
            ["DialogueId"] = 11015315,
            ["Duration"] = 3,
            ["FinalCamera"] = "166.064407,10.751297,-23.003906,-1.000001,21.599741,-14.16094,20.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B93601E",
            ["NextDialogue"] = 11015316,
            ["SpeakNpcId"] = 110039,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B93601E",
            },
        [11015316] = {
            ["Camera"] = "257.716278,247.216309,131.074219,0.000041,-29.99778,-90.566948,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是。催眠针剂已经准备完毕。",
            ["ContentJP"] = "了解です。催眠剤の準備は完了しております。",
            ["DialogueId"] = 11015316,
            ["Duration"] = 3,
            ["GUID"] = "1B936048",
            ["NextDialogue"] = 11015317,
            ["SpeakNpcId"] = 110021,
            ["TalkActionId"] = {
                [1] = "110021:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B936048",
            },
        [11015317] = {
            ["Camera"] = "-210.255844,7.862869,61.75,-0.999997,-10.599784,-0.559817,20.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果你还能挺过这次审问，我就考虑认可你证言的价值。",
            ["ContentJP"] = "もしお前が今回の尋問に耐え抜いたならば、お前の証言には幾分か価値があると認めてやってもいいぞ。",
            ["DialogueId"] = 11015317,
            ["Duration"] = 3,
            ["FinalCamera"] = "-204.461914,7.807205,60.671875,-0.999997,-10.599784,-0.559817,20.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B936072",
            ["LookAt"] = {
