                },
            ["NextDialogue"] = 11015318,
            ["SpeakNpcId"] = 110039,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1002/110153/1B936072",
            },
        [11015318] = {
            ["Camera"] = "-73.836884,-10.731598,18.917969,0.000025,20.598156,179.199265,45.000027,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……好。",
            ["ContentJP"] = "……わかった。",
