        [11015401] = {
            ["Camera"] = "471.230347,-142.271942,453.386719,0.00004,5.397912,-84.798851,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "……头好疼……",
            ["ContentJP"] = "……頭が痛むな……",
            ["DialogueId"] = 11015401,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "474.943176,-183.063965,457.253906,0.00004,5.397912,-84.798836,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B936E61",
