            },
        [11015402] = {
            ["Camera"] = "144.459961,146.939453,250.199219,0.000046,-31.401581,-139.605774,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "刚刚，应该是典狱长在说……“审讯”……",
            ["ContentJP"] = "先ほど「新たな尋問」だと……典獄が言っていたが……",
            ["DialogueId"] = 11015402,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "150.571289,139.705078,250.199219,0.000046,-31.401581,-139.805817,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B936E62",
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110154/1B936E62",
            },
        [11015403] = {
            ["Content"] = "等等，那两个人是——！莱昂和……马尔科？！",
            ["ContentJP"] = "待て！あのふたり——レオンと……マルコ！？",
            ["DialogueId"] = 11015403,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B936E63",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110154/1B936E63",
            },
        [11015404] = {
            ["Camera"] = "323.552734,2.655273,442.851562,0.000054,-47.001175,175.994278,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "帝国的背叛者……",
            ["ContentJP"] = "帝国の裏切り者め……",
            ["DialogueId"] = 11015404,
            ["Duration"] = 3,
            ["FinalCamera"] = "404.529297,32.693359,534.855469,0.000055,-48.400833,-178.20578,35.0,100000.0,false,Manual,22.0",
            ["GUID"] = "1B936E64",
            ["NextDialogue"] = 11015405,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1002/110154/1B936E64",
            },
        [11015405] = {
            ["Content"] = "若你坚称自己是无辜的，就向我证明你的正义吧。",
            ["ContentJP"] = "無実を主張するのであれば、お前の正義を私に証明してみせろ。",
            ["DialogueId"] = 11015405,
            ["Duration"] = 3,
            ["GUID"] = "1B936E8E",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1002/110154/1B936E8E",
            },
        [11015501] = {
            ["Camera"] = "320.628906,234.481445,65.152344,0.000067,13.598537,5.584634,25.522396,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "莱昂！你还活着？",
            ["ContentJP"] = "レオン！生きていたの{性别2:か|}？",
            ["DialogueId"] = 11015501,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FacialId"] = {
                [1] = "110022:Shock01",
                },
            ["FinalCamera"] = "284.21875,230.282227,59.746094,0.000067,8.398578,6.584378,25.522396,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1B937EA2",
            ["NextDialogue"] = 11015502,
