            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110157/1B939F72",
            },
        [11015702] = {
            ["Content"] = "这里……应该不是真实的世界。我想我现在在梦中。",
            ["ContentJP"] = "ここは……現実ではない。私は幻を見ているのだろうか。",
            ["DialogueId"] = 11015702,
