        [11016801] = {
            ["Camera"] = "459.99707,183.754883,152.386719,0.000152,-2.992859,-102.205826,35.0,150.488785,false,DoNotOverride,22.0",
            ["Content"] = "{nickname2}，海尔法典狱长吩咐了，带塞奥多尔小姐过来。",
            ["ContentJP"] = "{nickname2}、ヘルファイア典獄のご命令にて、セオドール医務官をお連れしました。",
            ["DialogueId"] = 11016801,
            ["ExStoryInfo"] = "EXPlayer",
