                },
            ["GUID"] = "1B94560C",
            ["NextDialogue"] = 11016820,
            ["Scripts"] = "PlayAnimation{_delay{6},ActorId{110040},AnimationId{\"Sit_Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 110040,
            ["VoiceName"] = "voice/$Locale$/story/1002/110168/1B94560C",
            },
        [11016815] = {
            ["Content"] = "典狱长相信了我的证词，她去调查法露茜了。",
            ["ContentJP"] = "典獄は私の証言をひとまず信じ、フォルスを調べに向かってくれた。",
            ["DialogueId"] = 11016815,
            ["GUID"] = "1B945636",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 11016816,
            },
        [11016816] = {
            ["Camera"] = "77.791992,275.038086,116.648438,0.000166,0.404306,-96.204185,35.0,298.040161,false,Manual,15.739686",
            ["Content"] = "太好了。",
            ["ContentJP"] = "よかった。",
            ["DialogueId"] = 11016816,
            ["FacialId"] = {
                [1] = "110041:Smile01",
                },
            ["GUID"] = "1B945660",
            ["NextDialogue"] = 11016817,
            ["SpeakNpcId"] = 110041,
            ["VoiceName"] = "voice/$Locale$/story/1002/110168/1B945660",
            },
        [11016817] = {
            ["Camera"] = "140.551758,369.635742,116.640625,0.000213,2.207462,117.81002,35.0,150.488785,false,DoNotOverride,22.0",
            ["Content"] = "……你身上又多了好多伤，很痛吧……我、我去求他们把医药箱还给我……",
            ["ContentJP"] = "……また傷がこんなにたくさん増えて……痛みますよね？わ、私、治療箱を返してもらえないか頼んで……",
            ["DialogueId"] = 11016817,
            ["GUID"] = "1B94568A",
            ["NextDialogue"] = 11016818,
            ["SpeakNpcId"] = 110041,
            ["VoiceName"] = "voice/$Locale$/story/1002/110168/1B94568A",
            },
        [11016818] = {
            ["Content"] = "我还好，你先给自己治疗一下吧……",
            ["ContentJP"] = "私は平気{性别2:だ|}。それより自らの手当てを優先して{性别2:|くれ}……",
