            ["VoiceName"] = "voice/$Locale$/story/1002/110168/1B9458AC",
            },
        [11016831] = {
            ["Content"] = "你在偷听？",
            ["ContentJP"] = "盗み聞きしていたの{性别2:か|}？",
            ["DialogueId"] = 11016831,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9458D6",
