            },
        [11017520] = {
            ["Camera"] = "699.135376,388.0625,157.425171,10.009494,-3.598785,-51.594585,40.0,100000.0,false,DoNotOverride,20.0",
            ["Content"] = "既然常规手段解决不了月髓舱，你就让它自己搞坏自己。",
            ["ContentJP"] = "通常の方法でイコルキャビンが停止できんのならば、自壊するよう仕向けるまでだ。",
            ["DialogueId"] = 11017520,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "110010:Angry01",
                },
            ["FinalCamera"] = "699.135376,388.0625,156.380249,10.010453,-3.598785,-51.595715,40.0,100000.0,false,DoNotOverride,20.0",
            ["GUID"] = "1B94C9E0",
            ["NextDialogue"] = 11017521,
            ["SpeakNpcId"] = 110010,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94C9E0",
            },
        [11017521] = {
            ["Camera"] = "992.544189,397.238281,178.074951,-0.0,-8.599126,-138.38974,40.000011,100000.0,false,DoNotOverride,20.0",
            ["Content"] = "您指的是……利用过载炸毁月髓舱？我知道了。",
            ["ContentJP"] = "過負荷でイコルキャビンを破裂させるのですね？了解です。",
            ["DialogueId"] = 11017521,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94CA0A",
            ["Scripts"] = "PlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
            ["SnapShot"] = "TELEPHONE",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110175/1B94CA0A",
            },
        [11017601] = {
            ["Content"] = "1号备用髓动轮可以操作了，启动吧。",
            ["ContentJP"] = "予備1号のイコル駆動輪が操作可能になったぞ。起動してみろ。",
            ["DialogueId"] = 11017601,
            ["GUID"] = "1B94D72A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D72A",
            },
        [11017602] = {
            ["Content"] = "干得好，我会把剩下三台的髓动轮的操作权限一一解锁。",
            ["ContentJP"] = "よくやった！残り3つの操作権限も解除していく一一ひとつずつ順にはなるが。",
            ["DialogueId"] = 11017602,
            ["GUID"] = "1B94D754",
            ["NextDialogue"] = 11017603,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D754",
            },
        [11017603] = {
            ["Content"] = "等黄色灯光亮起，你就启动它。",
            ["ContentJP"] = "黄色に点灯したら、起動するんだ。",
            ["DialogueId"] = 11017603,
            ["GUID"] = "1B94D77E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D77E",
            },
        [11017604] = {
            ["Content"] = "（髓动轮亮了，看来老师那边已经解决了。）",
            ["ContentJP"] = "（イコル駆動輪が点灯した。ということは教官が操作可能な状態にしてくれたのだろう）",
            ["DialogueId"] = 11017604,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94D7A8",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D7A8",
            },
        [11017605] = {
            ["Content"] = "<W>警告：月髓舱负荷过大，已过载50%。请立即停止髓动轮设备使用，不得擅自撤离。</>",
            ["ContentJP"] = "<W>警告。イコルキャビンに50%以上の過負荷が発生しております。ただちにイコル駆動輪に関する設備を停止してください。独断で離脱することは許されません。</>",
            ["DialogueId"] = 11017605,
            ["GUID"] = "1B94D7D2",
            ["NextDialogue"] = 11017606,
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D7D2",
            },
        [11017606] = {
            ["Content"] = "（……要尽快了。）",
            ["ContentJP"] = "（……ことは迅速に進めなければ）",
            ["DialogueId"] = 11017606,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94D7FC",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D7FC",
            },
        [11017607] = {
            ["Content"] = "3号也可以了，去吧！",
            ["ContentJP"] = "3号も弄れるようにしたぞ！向かってくれ！",
            ["DialogueId"] = 11017607,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D826",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D826",
            },
        [11017608] = {
            ["Content"] = "（呼……）",
            ["ContentJP"] = "（ふぅ……）",
            ["DialogueId"] = 11017608,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94D850",
            ["NextDialogue"] = 11017609,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D850",
            },
        [11017609] = {
            ["Content"] = "干净利落，做得漂亮。",
            ["ContentJP"] = "見事な手際だ、完璧じゃないか。",
            ["DialogueId"] = 11017609,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D87A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D87A",
            },
        [11017610] = {
            ["Content"] = "权限激活了，这是最后一台！",
            ["ContentJP"] = "権限有効！よし、こいつでしまいだ！",
            ["DialogueId"] = 11017610,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D8A4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D8A4",
            },
        [11017611] = {
            ["Content"] = "<W>警告：月髓舱即将损毁，请自首。</>",
            ["ContentJP"] = "<W>警告。イコルキャビンが自壊を始めました。対応者は速やかに出頭してください。</>",
            ["DialogueId"] = 11017611,
            ["GUID"] = "1B94D8CE",
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D8CE",
            },
        [11017612] = {
            ["Content"] = "快！撤到安全门后面去！",
            ["ContentJP"] = "急ぎ下がれ！セキュリティゲートの後ろまで！",
            ["DialogueId"] = 11017612,
            ["DialoguePanelType"] = "{type:Guide;style:Communicator}",
            ["GUID"] = "1B94D8F8",
            ["NextDialogue"] = 11017613,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D8F8",
            },
        [11017613] = {
            ["Content"] = "<W>警告：月髓舱即将损毁，请自首。</>",
            ["ContentJP"] = "<W>警告。イコルキャビンが自壊を始めました。対応者は速やかに出頭してください。</>",
            ["DialogueId"] = 11017613,
            ["GUID"] = "1B94D922",
            ["SnapShot"] = "BROADCAST",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110176/1B94D922",
            },
        [11017701] = {
            ["Content"] = "长官，请走这边……",
            ["ContentJP"] = "兵士様、こちらへどうぞ……",
            ["DialogueId"] = 11017701,
            ["GUID"] = "1B94E792",
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E792",
            },
        [11017702] = {
            ["Content"] = "长官，从这里下去，就是地下水道了。",
            ["ContentJP"] = "兵士様、ここを降りたところが地下水路でございまする。",
            ["DialogueId"] = 11017702,
            ["GUID"] = "1B94E7BC",
            ["NextDialogue"] = 11017703,
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E7BC",
            },
        [11017703] = {
            ["Content"] = "卡戎人，你走前面。",
            ["ContentJP"] = "前を歩け、カロン人。",
            ["DialogueId"] = 11017703,
            ["GUID"] = "1B94E7E6",
            ["NextDialogue"] = 11017704,
            ["SpeakNpcId"] = 110016,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E7E6",
            },
        [11017704] = {
            ["Content"] = "是、是……",
            ["ContentJP"] = "は、はい……",
            ["DialogueId"] = 11017704,
            ["GUID"] = "1B94E810",
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E810",
            },
        [11017705] = {
            ["Content"] = "这股热气是……",
            ["ContentJP"] = "この熱気は……",
            ["DialogueId"] = 11017705,
            ["GUID"] = "1B94E83A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017706,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E83A",
            },
        [11017706] = {
            ["Content"] = "当心！前面有一台冷凝机，靠太近的话会受伤的！",
            ["ContentJP"] = "お気をつけください！前方にございます冷却装置には、近づきすぎないように！",
            ["DialogueId"] = 11017706,
            ["GUID"] = "1B94E864",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E864",
            },
        [11017707] = {
            ["Content"] = "各位长官……冷凝机的蒸汽很危险，千万不要久留。",
            ["ContentJP"] = "兵士様……冷却装置は排熱機構ゆえに常に熱い蒸気を噴き出しておりまする。大変危険ですので、長居は避けるべきかと。",
            ["DialogueId"] = 11017707,
            ["GUID"] = "1B94E88E",
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E88E",
            },
        [11017708] = {
            ["Content"] = "呼、呼……好热……长官，您没事吧？",
            ["ContentJP"] = "はぁ、あぁ……熱い……兵士様、お怪我はございませんか？",
            ["DialogueId"] = 11017708,
            ["GUID"] = "1B94E8B8",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E8B8",
            },
        [11017709] = {
            ["Content"] = "长官，请走这边……",
            ["ContentJP"] = "兵士様、こちらへお進みを……",
            ["DialogueId"] = 11017709,
            ["GUID"] = "1B94E8E2",
            ["NextDialogue"] = 11017710,
            ["SpeakNpcId"] = 110017,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E8E2",
            },
        [11017710] = {
            ["Content"] = "秽、秽兽……！",
            ["ContentJP"] = "穢、<Default note=\"text:エジュウ\">穢獣</>……！",
            ["DialogueId"] = 11017710,
            ["GUID"] = "1B94E90C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017711,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E90C",
            },
        [11017711] = {
            ["Content"] = "平民都退到我身后去。",
            ["ContentJP"] = "難民の皆はひとり残らず後方に退避を。",
            ["DialogueId"] = 11017711,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94E936",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E936",
            },
        [11017712] = {
            ["Content"] = "谢谢您救了我们！原来也不是所有帝国士兵都……",
            ["ContentJP"] = "なんとお礼を言うべきか！私たちをお守りくださるなんて、帝国の兵士様の中にもお優しい方が……",
            ["DialogueId"] = 11017712,
            ["GUID"] = "1B94E960",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 11017713,
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E960",
            },
        [11017713] = {
            ["Content"] = "啊，抱歉！我是说，我曾经以为帝国士兵都和同盟的家伙一样蛮横粗暴，但现在我知道了，不是我想的那样！",
            ["ContentJP"] = "あ、も、申し訳ございません……正直にお話すると、帝国の兵士様に偏見を持っていました。横暴で乱暴なのは同盟のやつらと同じだと……でも今は違うって、考えを改めました！",
            ["DialogueId"] = 11017713,
            ["GUID"] = "1B94E98A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E98A",
            },
        [11017714] = {
            ["Content"] = "前面那个是……阿瓦尔长官！",
            ["ContentJP"] = "あそこにいるのは……アヴァール長官！",
            ["DialogueId"] = 11017714,
            ["GUID"] = "1B94E9B4",
            ["NextDialogue"] = 11017715,
            ["SpeakNpcId"] = 110015,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E9B4",
            },
        [11017715] = {
            ["Content"] = "（好，总算是平安会合了。）",
            ["ContentJP"] = "（ふぅ、なんとか無事に合流できた{性别2:な|}）",
            ["DialogueId"] = 11017715,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94E9DE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110177/1B94E9DE",
            },
        [11017801] = {
            ["Content"] = "停下吧。",
            ["ContentJP"] = "停止せよ。",
            ["DialogueId"] = 11017801,
            ["GUID"] = "1B94F7FA",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F7FA",
            },
        [11017802] = {
            ["Content"] = "视野不错，就在这儿轰击中央控制室吧。",
            ["ContentJP"] = "最高の見晴らしだ。ここから砲撃と洒落こむか。",
            ["DialogueId"] = 11017802,
            ["GUID"] = "1B94F824",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F824",
            },
        [11017803] = {
            ["Content"] = "该死……",
            ["ContentJP"] = "おのれ…",
            ["DialogueId"] = 11017803,
            ["GUID"] = "1B94F84E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F84E",
            },
        [11017804] = {
            ["Content"] = "先处理掉秽兽，别让它们干扰到你！",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>を先に片づけろ！邪魔者は蹴散らせ！",
            ["DialogueId"] = 11017804,
            ["GUID"] = "1B94F878",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F878",
            },
        [11017805] = {
            ["Content"] = "好，清理干净了。",
            ["ContentJP"] = "よしよし、綺麗さっぱり片づいたな。",
            ["DialogueId"] = 11017805,
            ["GUID"] = "1B94F8A2",
            ["NextDialogue"] = 11017806,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F8A2",
            },
        [11017806] = {
            ["Content"] = "接下来，就从相对薄弱的<H>侧门</>开始轰击吧。",
            ["ContentJP"] = "だったらゲートへの砲撃を再開だ。お次は比較的脆弱な<H>サイドゲート</>を狙って撃ってみろ。",
            ["DialogueId"] = 11017806,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B94F8CC",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F8CC",
            },
        [11017807] = {
            ["Content"] = "不要停，继续轰击！记得用高爆弹。",
            ["ContentJP"] = "手を止めずに砲撃し続けろ！それと使用するのは榴弾だ！",
            ["DialogueId"] = 11017807,
            ["GUID"] = "1B94F8F6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F8F6",
            },
        [11017808] = {
            ["Content"] = "差不多了！过去看看吧。",
            ["ContentJP"] = "だいたい片付いたな。見にいってみるか。",
            ["DialogueId"] = 11017808,
            ["GUID"] = "1B94F920",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110186/1B957C0C",
            },
        [11017809] = {
            ["Content"] = "别发愣啊，快轰！",
            ["ContentJP"] = "ボケーッとしている場合か！早く撃て！",
            ["DialogueId"] = 11017809,
            ["GUID"] = "1B94F94A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F94A",
            },
        [11017810] = {
            ["Content"] = "你还好吧？别是哪儿受伤了？",
            ["ContentJP"] = "おいどうした？まさかお前も負傷を隠しているんじゃないだろうな？",
            ["DialogueId"] = 11017810,
            ["GUID"] = "1B94F974",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F974",
            },
        [11017811] = {
            ["Content"] = "等你把这门敲破，我小女儿都变成老奶奶了！回去开炮。",
            ["ContentJP"] = "お前の攻撃で壊れるのを待っていたら俺の娘も婆さんだ！戻って素直に砲撃しろ！キャノン以外じゃゲートはどうにもならん！",
            ["DialogueId"] = 11017811,
            ["GUID"] = "1B94F99E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F99E",
            },
        [11017812] = {
            ["DialogueId"] = 11017812,
            ["GUID"] = "1B94F9C8",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1002/110178/1B94F9C8",
            },
        [11017901] = {
            ["Content"] = "去吧，保持联络，听我指示。",
            ["ContentJP"] = "さあ行け。俺の指示を聞けるよう、常に通信可能な状態は保っていてくれよ。",
            ["DialogueId"] = 11017901,
            ["GUID"] = "1B950862",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110179/1B950862",
            },
        [11017902] = {
            ["Content"] = "维克……",
            ["ContentJP"] = "ヴィック……",
            ["DialogueId"] = 11017902,
            ["GUID"] = "1B95088C",
            ["SpeakNpcId"] = 110020,
            ["VoiceName"] = "voice/$Locale$/story/1002/110179/1B95088C",
            },
        [11017903] = {
            ["Content"] = "准备好了，就激活髓动轮出发吧。",
            ["ContentJP"] = "準備できたら「イコル駆動輪」を起動して出発しよう。",
            ["DialogueId"] = 11017903,
            ["GUID"] = "1B9508B6",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110179/1B9508B6",
            },
        [11018001] = {
            ["Camera"] = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "等一下。",
            ["ContentJP"] = "待て。",
            ["DialogueId"] = 11018001,
            ["GUID"] = "1B9518CA",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                [2] = "110034:n(110010)",
                [3] = "110015:n(110010)",
                [4] = "110017:n(110010)",
                },
            ["NextDialogue"] = 11018002,
            ["RelatedWikiId"] = {
                [1] = 204001,
                [2] = 201013,
                [3] = 201015,
                [4] = 408007,
                [5] = 101004,
                },
            ["Scripts"] = "PARA{\
MoveTo{ActorId{110017},MoveSpeed{150},TargetPoint{\"fulankemoVe\"}},\
MoveTo{ActorId{110010},MoveSpeed{150},TargetPoint{\"fix30awa\"}},\
MoveTo{ActorId{110022},MoveSpeed{150},TargetPoint{\"qiannanzhumoVe\"}},\
MoveTo{ActorId{110034},MoveSpeed{150},TargetPoint{\"kajiamoVe\"}}\
}",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B9518CA",
            },
        [11018002] = {
            ["Camera"] = "436.131592,1.919922,136.800903,0.000139,-1.999415,173.000534,35.0,100000.0,false,Manual,22.0",
            ["Content"] = "接下来的任务容不得出任何错，我们还是得排除风险——小姑娘和老人家不能跟着了。",
            ["ContentJP"] = "ここから先は些細なミスも犯せん。極限までリスクを排除しなくては——若い娘、ならびにご老体よ。あなた方を連れ歩くのはここまでだ。",
            ["DialogueId"] = 11018002,
            ["GUID"] = "1B9518F4",
            ["LookAt"] = {
                [1] = "110010:n(110034)",
                },
            ["NextDialogue"] = 11018003,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B9518F4",
            },
        [11018003] = {
            ["Camera"] = "27.165649,69.382324,136.855469,0.000141,-0.199305,10.000502,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……为什么？刚才您也看到了，到处都是秽兽，如果在这里和你们分开，我和爷爷一定会没命的！",
            ["ContentJP"] = "そんな、先ほどもご覧になられたでしょう！？周辺は<Default note=\"text:エジュウ\">穢獣</>で溢れかえっておりますのに、捨て置かれてしまったら……！私とお爺様の命はないも同然です！",
            ["DialogueId"] = 11018003,
            ["FacialId"] = {
                [1] = "110034:Sad01",
                },
            ["GUID"] = "1B95191E",
            ["LookAt"] = {
                [1] = "110034:n(110010)",
                [2] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11018004,
            ["Scripts"] = "CameraMoveTo{_delay{8},TargetPosition{\"-263.419067,35.512207,120.94928,0.000142,0.800758,5.202505,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}}",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B95191E",
            },
        [11018004] = {
            ["Camera"] = "-143.649597,-86.15332,142.109314,0.000144,-2.799244,26.800621,35.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "长官，我帮过您的！您想，我刚刚给您带路，帮您顺利会合……求求您……求求您不要抛下我们！",
            ["ContentJP"] = "隊長様、私は微力ながらもお手伝いしました！つい先ほどまで道案内を、兵士の皆様方が無事に合流を果たせるようにと……どうか……お願いします。私たちを置き去りにしないで！",
            ["DialogueId"] = 11018004,
            ["GUID"] = "1B951948",
            ["LookAt"] = {
                [1] = "110034:n(110022)",
                [2] = "110017:n(110010)",
                },
            ["NextOptions"] = {
                [1] = 11018005,
                [2] = 11018008,
                },
            ["Scripts"] = "LookAt{_delay{1},LookAtDescription{\"110022:n(110034)\"}}",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951948",
            },
        [11018005] = {
            ["Content"] = "信任卡嘉",
            ["ContentJP"] = "カーチャを信用する",
            ["DialogueId"] = 11018005,
            ["GUID"] = "1B951972",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 11018006,
            },
        [11018006] = {
            ["Camera"] = "-372.804108,82.572754,153.340088,0.000149,-3.999233,-7.999348,50.000011,450.777496,false,DoNotOverride,7.0",
            ["Content"] = "老师也许多虑了。如果他们是敌人，那么在地下水道故意带错路会是更好的选择，但他们没有这么做。",
            ["ContentJP"] = "過剰な不安視ではありませんか？もし敵であれば地下水路で意図的に誤った道を案内するなど、如何様にも我々を効率的に貶める手段があったはずです。ですが彼女らはそうしませんでした。",
            ["DialogueId"] = 11018006,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95199C",
            ["LookAt"] = {
                [1] = "110022:n(110010)",
                [2] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11018007,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B95199C",
            },
        [11018007] = {
            ["Camera"] = "32.585205,14.534668,146.054871,0.00015,-1.399219,162.798279,50.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如果他们另有打算呢。你不觉得，刚才这一路，他们“过于了解”这座要塞了吗？",
            ["ContentJP"] = "もし俺たちが知り得ぬ企みを持っていたとしたらどうする？道中にて何も感じなかったのか？彼女らは要塞について「知りすぎている」とは。",
            ["DialogueId"] = 11018007,
            ["GUID"] = "1B9519C6",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                },
            ["NextDialogue"] = 11018011,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B9519C6",
            },
        [11018008] = {
            ["Content"] = "不信任卡嘉",
            ["ContentJP"] = "カーチャを信用しない",
            ["DialogueId"] = 11018008,
            ["GUID"] = "1B9519F0",
            ["ImprPlusId"] = 1008,
            ["NextDialogue"] = 11018009,
            },
        [11018009] = {
            ["Camera"] = "209.203857,228.964844,146.143616,0.000167,-4.599087,-120.406746,45.000011,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "……我赞同老师的判断。",
            ["ContentJP"] = "……教官の判断を支持する。",
            ["DialogueId"] = 11018009,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B951A1A",
            ["LookAt"] = {
                [1] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11018010,
            ["Scripts"] = "SetRotation{SetRotationDescription{\"110022:n(110034)\"}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A1A",
            },
        [11018010] = {
            ["Camera"] = "-127.301941,-114.787598,142.109314,0.000143,-1.599302,31.20196,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "如果是进中央控制室之前，我还可以勉强信任你；但是现在看来你似乎“过于了解”这座要塞了。",
            ["ContentJP"] = "まだ中央制御室に入る前までなら信用できた。今は要塞について「知りすぎている」ように見える。",
            ["DialogueId"] = 11018010,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B951A44",
            ["LookAt"] = {
                [1] = "110010:n(110022)",
                [2] = "110022:n(110034)",
                },
            ["NextDialogue"] = 11018011,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A44",
            },
        [11018011] = {
            ["Camera"] = "414.556763,7.735352,138.894348,0.000155,-2.599324,169.392776,50.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "中央控制室是龙莎要塞的中枢，就算是同盟，也不会允许路边随便抓来的苦力来这种核心区域闲逛。",
            ["ContentJP"] = "中央制御室はロンザ要塞の中枢だ。そんな場所を自由に歩く権利など、同盟の連中が適当に拉致してきた労働者に渡すものか。",
            ["DialogueId"] = 11018011,
            ["GUID"] = "1B951A6E",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11018012,
            ["SpeakNpcId"] = 110010,
            ["TurnTo"] = {
                [1] = "110022:n(110010)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A6E",
            },
        [11018012] = {
            ["Content"] = "你不该对里面的路线也如此轻车熟路。",
            ["ContentJP"] = "さも慣れ親しんだ道のように歩きやがって。",
            ["DialogueId"] = 11018012,
            ["GUID"] = "1B951A98",
            ["LookAt"] = {
                [1] = "110010:n(110034)",
                },
            ["NextDialogue"] = 11018013,
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951A98",
            },
        [11018013] = {
            ["Camera"] = "-38.761108,62.896484,133.47168,0.000157,0.600497,8.994007,50.000008,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "呃……那是因为——",
            ["ContentJP"] = "ええ……それは——",
            ["DialogueId"] = 11018013,
            ["GUID"] = "1B951AC2",
            ["LookAt"] = {
                [1] = "110034:n(110010)",
                },
            ["NextDialogue"] = 11018014,
            ["SpeakNpcId"] = 110034,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951AC2",
            },
        [11018014] = {
            ["Camera"] = "528.188843,-8.837402,130.242065,0.000159,-1.599541,172.787582,50.000008,824.380615,false,Manual,10.0",
            ["Content"] = "小姑娘，这么喜欢演戏，还是去皇都的大剧院演吧。",
            ["ContentJP"] = "おい小娘。そんなに芝居が好きなら、帝都の大劇場で働けばいいだろう？今よりもいい役がもらえるかもな。",
            ["DialogueId"] = 11018014,
            ["GUID"] = "1B951AEC",
            ["LookAt"] = {
                [1] = "110010:n(110010)",
                },
            ["NextDialogue"] = 11018015,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951AEC",
            },
        [11018015] = {
            ["Camera"] = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "时间不多了，我们走。莱昂，留下来看好他们。",
            ["ContentJP"] = "時間がない、急ぎ進むぞ。レオンは残っておけ。こいつらを見張っておくんだ。",
            ["DialogueId"] = 11018015,
            ["GUID"] = "1B951B16",
            ["SpeakNpcId"] = 110010,
            ["TalkActionId"] = {
                [1] = "110010:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110180/1B951B16",
            },
        [11018101] = {
            ["Content"] = "年轻的士兵半倚着冰冷的墙壁，已经没了气息。一道巨大的爪痕穿过他的胸口，将他贯穿。在刚刚的巨型秽兽面前，普通人类的力量太微弱了。",
            ["ContentJP"] = "若い兵士が冷たい壁に寄りかかっている。彼の胸には巨大な爪痕があり、すでに生命反応はない。先ほどのような巨大な<Default note=\"text:エジュウ\">穢獣</>の前では、人間の力などあまりに微弱だ。",
            ["DialogueId"] = 11018101,
            ["GUID"] = "1B952932",
            ["VoiceName"] = "voice/$Locale$/story/1002/110181/1B952932",
            },
        [11018102] = {
            ["Content"] = "（……安息。）",
            ["ContentJP"] = "（……どうか安らかに。）",
            ["DialogueId"] = 11018102,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95295C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110181/1B95295C",
            },
        [11018201] = {
            ["Content"] = "先解决那个神弃者！这群秽兽受他操弄！",
            ["ContentJP"] = "この<Default note=\"text:エジュウ\">穢獣</>ども、操られていやがる！あのフォーセイクンから片付けろ！",
            ["DialogueId"] = 11018201,
            ["GUID"] = "1B95399A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B95399A",
            },
        [11018202] = {
            ["Content"] = "维克，莫妮卡，撑住……我们很快就到。",
            ["ContentJP"] = "ヴィック、モニカ、もうすぐつくぞ……しっかりしろ。",
            ["DialogueId"] = 11018202,
            ["GUID"] = "1B9539C4",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B9539C4",
            },
        [11018203] = {
            ["Content"] = "（好，关停了。去找其他几台髓动轮吧。）",
            ["ContentJP"] = "（よし、停まった。他のイコル駆動輪を探そう。）",
            ["DialogueId"] = 11018203,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9539EE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B9539EE",
            },
        [11018204] = {
            ["Content"] = "男人崭新的军装被撕碎，透过褴褛的布条，无数爪迹和齿痕清晰可辨；显然，他是被相当数量的秽兽撕咬致死的。他指节青白的手仍紧紧握着断刃，似是最后一刻仍在与群兽角力。",
            ["ContentJP"] = "男の新しい軍服は無残に引き裂かれ、ぼろ布の隙間からは無数の爪痕や噛み跡がはっきりと見て取れた。相当な数の<Default note=\"text:エジュウ\">穢獣</>に食いちぎられた末の最期であることは明白だ。青白くなった指は、今もなお折れた剣を固く握りしめたまま——死の間際まで、群がる獣どもに抗っていたのだろう。",
            ["DialogueId"] = 11018204,
            ["GUID"] = "1B953A18",
            ["NextDialogue"] = 11018205,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A18",
            },
        [11018205] = {
            ["Content"] = "在他的身旁静静地躺着一枚铭牌，你认得出来，那是军团为每一位新兵颁发的铭牌。铭牌的正面是他的名字，维克·吉拉德。背面则用小刀刻着一行小字：“莫妮卡，下次射击比赛我一定会赢过你。”",
            ["ContentJP"] = "その傍らには、一枚の銘板が静かに転がっていた。軍団が新兵一人ひとりに与えるものだ。表には彼の名——「ヴィク・ジラルド」が刻まれている。裏返すと、ナイフで走り書きのように刻まれた文字が目に入った。「モニカ、次の射撃大会では、必ず君に勝つ」",
            ["DialogueId"] = 11018205,
            ["GUID"] = "1B953A42",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A42",
            },
        [11018206] = {
            ["Content"] = "（月髓舱炸毁后，这些机关都瘫痪了。）",
            ["ContentJP"] = "（イコルキャビンが爆発してから、これらのトラップは完全に停止している。）",
            ["DialogueId"] = 11018206,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953A6C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A6C",
            },
        [11018207] = {
            ["Content"] = "就是这些畜生……把大家……",
            ["ContentJP"] = "こいつらが……みんなを……",
            ["DialogueId"] = 11018207,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953A96",
            ["NextDialogue"] = 11018208,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953A96",
            },
        [11018208] = {
            ["Content"] = "<W>不错，正是如此。仇恨刺痛着你的心脏，你从未如此渴求着鲜血。</>",
            ["ContentJP"] = "<W>そうだ、間違いない……憎しみが胸を突き刺す。これほど血を渇望したのは初めてだ。</>",
            ["DialogueId"] = 11018208,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953AC0",
            ["NextDialogue"] = 11018209,
            ["SnapShot"] = "MONSTER",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953AC0",
            },
        [11018209] = {
            ["Content"] = "<W>你只恨这些怪物无血无泪，它们无法感受你的愤怒与悲辛。</>",
            ["ContentJP"] = "<W>憎いだろう……血も涙もない奴らが。お前のこの怒りも悲しみも、奴らには届かない。</>",
            ["DialogueId"] = 11018209,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953AEA",
            ["NextDialogue"] = 11018210,
            ["SnapShot"] = "MONSTER",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953AEA",
            },
        [11018210] = {
            ["Content"] = "<W>但是没有关系，你只需要挥剑、挥剑、挥剑——</>",
            ["ContentJP"] = "<W>……だが、それでいい。ただ、剣を振れ、振れ、振り続けろ——</>",
            ["DialogueId"] = 11018210,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953B14",
            ["NextDialogue"] = 11018211,
            ["SnapShot"] = "MONSTER",
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953B14",
            },
        [11018211] = {
            ["Content"] = "（……不行！）",
            ["ContentJP"] = "{性别2:……ダメだ！|……ダメ！}",
            ["DialogueId"] = 11018211,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953B3E",
            ["NextDialogue"] = 11018212,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953B3E",
            },
        [11018212] = {
            ["Content"] = "（还有人等待我救援……不能被这些秽兽拖在这儿！）",
            ["ContentJP"] = "（まだ助けを待っている人がいる……こんなところで<Default note=\"text:エジュウ\">穢獣</>に足止めされている場合じゃない！）",
            ["DialogueId"] = 11018212,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B953B68",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110182/1B953B68",
            },
        [11018301] = {
            ["Content"] = "坚持住，队长就快来了！",
            ["ContentJP"] = "ふんばれ！隊長もきっとすぐ来るはずだ！",
            ["DialogueId"] = 11018301,
            ["GUID"] = "1B954A02",
            ["SpeakNpcId"] = 110016,
            ["VoiceName"] = "voice/$Locale$/story/1002/110183/1B954A02",
            },
        [11018302] = {
            ["Content"] = "神弃者同盟的人改造要塞要苦力，就派人到我们镇子，把我们强行绑过来。他们甚至不要索拉之民，而是专挑我们卡戎之民……",
            ["ContentJP"] = "フォーセイクン同盟の人たちが要塞を改造する労働者を確保するために町へやってきました。彼らはソラ族でなく、私たちカロン族だけを強制的に連行して……",
            ["DialogueId"] = 11018302,
            ["FacialId"] = {
                [1] = "110034:Sad01",
                },
            ["GUID"] = "1B954A2C",
            ["NextDialogue"] = 11011824,
            ["RelatedWikiId"] = {
                [1] = 201015,
                },
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110183/1B954A2C",
            },
        [11018401] = {
            ["Camera"] = "-274.711914,194.082031,124.856079,0.00015,-1.800322,-91.197739,35.000008,229.080856,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "没错，仅仅因为我们比索拉之民力气更大，更不怕严寒暑热——也许在您的眼中我们是同类，但同盟从未把我们当过“同胞”。",
            ["ContentJP"] = "その通りでございます。ソラ族より力が強く、寒さや暑さにも耐性があるとの理由で——兵士様の目には同胞と映るかもしれませんが、同盟は私たちを「同胞」と扱ってはくれませんでした。",
            ["DialogueId"] = 11018401,
            ["FacialId"] = {
                [1] = "110034:None",
                },
            ["FinalCamera"] = "-275.310547,165.044922,123.943848,0.00015,-1.800322,-91.197739,35.000008,208.205566,false,Manual,2.8",
