            ["VoiceName"] = "voice/$Locale$/story/1002/110119/1B91327B",
            },
        [11018403] = {
            ["Content"] = "先启动髓动轮，恢复这一小片区域的供能吧。",
            ["ContentJP"] = "ひとまずイコル駆動輪を起動して、ここの供給を復旧させよう。",
