            ["NextDialogue"] = 11017417,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955ABE",
            },
        [11018404] = {
            ["Content"] = "这门炮调校得差不多，模拟战场区域的供能也恢复了。",
            ["ContentJP"] = "このキャノンはほぼ調整完了だ。シミュレーション戦場のエネルギー供給も回復した。",
