            ["GUID"] = "1B955AE8",
            ["NextDialogue"] = 11018405,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955AE8",
            },
        [11018405] = {
            ["Content"] = "走吧，去控制台开门。我也一起。",
            ["ContentJP"] = "さあ、制御装置で扉を開けよう。",
            ["DialogueId"] = 11018405,
            ["GUID"] = "1B955B12",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955B12",
            },
        [11018406] = {
            ["Content"] = "已成功覆写模拟战场区域，模拟战场重启中。",
            ["ContentJP"] = "シミュレーション戦場エリアの上書きが完了しました。シミュレーション戦場を再起動しています。",
            ["DialogueId"] = 11018406,
            ["GUID"] = "1B955B3C",
            ["NextDialogue"] = 11018407,
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955B3C",
            },
        [11018407] = {
            ["Content"] = "当前测试环境：科赛托斯行省，冰湖城。通道已开启，训练人员准备就位。",
            ["ContentJP"] = "現在のテスト環境：コキュートス領、アイスレイク城。通路が開放されました。参加者は位置についてください。",
            ["DialogueId"] = 11018407,
            ["GUID"] = "1B955B66",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955B66",
            },
        [11018408] = {
            ["Content"] = "门开了。走，回炮台。",
            ["ContentJP"] = "扉が開いた。行こう、砲台に戻ろう。",
            ["DialogueId"] = 11018408,
            ["GUID"] = "1B955B90",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955B90",
            },
        [11018409] = {
            ["Content"] = "（炮台可以启动了。）",
            ["ContentJP"] = "（砲台が起動できるようになった。）",
            ["DialogueId"] = 11018409,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B955BBA",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110184/1B955BBA",
            },
        [11018501] = {
            ["Content"] = "{nickname2}，还好，我们又平安会合了。",
            ["ContentJP"] = "{nickname2}、良かった。無事だったのね。",
            ["DialogueId"] = 11018501,
            ["GUID"] = "1B956AD2",
            ["SpeakNpcId"] = 110020,
            ["VoiceName"] = "voice/$Locale$/story/1002/110185/1B956AD2",
            },
        [11018502] = {
            ["Content"] = "对了，这个是维克留下来的。你……帮他收着吧。",
            ["ContentJP"] = "{性别2:そうだ。これ……ヴィックが残したものだ。君が保管してくれ。|そうだ。これ……ヴィックが残したものよ。あなたが代わりに保管してくれない？}",
            ["DialogueId"] = 11018502,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B956AFC",
            ["NextDialogue"] = 11018503,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110185/1B956AFC",
            },
        [11018503] = {
            ["Content"] = "是……他的铭牌……",
            ["ContentJP"] = "ヴィックの……銘板……",
            ["DialogueId"] = 11018503,
            ["GUID"] = "1B956B26",
            ["NextDialogue"] = 11018504,
            ["SpeakNpcId"] = 110020,
            ["VoiceName"] = "voice/$Locale$/story/1002/110185/1B956B26",
            },
        [11018504] = {
            ["Content"] = "“莫妮卡，下次射击比赛我一定会赢你”……哈，哈哈……混账，这算什么……",
            ["ContentJP"] = "「モニカ、次の射撃大会では、必ず君に勝つ」……ふ、ははは……ばっかじゃないの……こんなの……",
            ["DialogueId"] = 11018504,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B956B50",
            ["NextDialogue"] = 11018505,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110185/1B956B50",
            },
        [11018505] = {
            ["Content"] = "早知道这么记仇……上次就让着他了……",
            ["ContentJP"] = "こんな根に持つなんてね……あのとき、ちょっと譲っときゃよかったわ……",
            ["DialogueId"] = 11018505,
            ["GUID"] = "1B956B7A",
            ["NextDialogue"] = 11018506,
            ["SpeakNpcId"] = 110020,
            ["VoiceName"] = "voice/$Locale$/story/1002/110185/1B956B7A",
            },
        [11018506] = {
            ["Content"] = "……莫妮卡，接下来恐怕又是一场恶战，别分心。",
            ["ContentJP"] = "……モニカ、これからまた激しい戦いになる。今はまだ気を抜かないで。",
