            ["DialogueId"] = 11018601,
            ["GUID"] = "1B957B3A",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110186/1B957B3A",
            },
        [11018602] = {
