            ["GUID"] = "1B957B8E",
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110186/1B957B8E",
            },
        [11018604] = {
            ["Content"] = "是这群秽兽的首领，干掉它！",
            ["ContentJP"] = "こいつが<Default note=\"text:エジュウ\">穢獣</>のボスか！撃つぞっ！",
