        [11018910] = {
            ["Content"] = "秘钥不在他身上，继续找。",
            ["ContentJP"] = "鍵はなかった。捜索を続けよう。",
            ["DialogueId"] = 11018910,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95ADEC",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95ADEC",
            },
        [11018911] = {
            ["Content"] = "还是不对……",
            ["ContentJP"] = "こいつも違う……",
            ["DialogueId"] = 11018911,
            ["GUID"] = "1B95AE16",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE16",
            },
        [11018912] = {
            ["Content"] = "找到秘钥了，在这里！",
            ["ContentJP"] = "あ、鍵、ありました！",
            ["DialogueId"] = 11018912,
            ["Duration"] = 3,
            ["GUID"] = "1B95AE40",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE40",
            },
        [11018913] = {
            ["Content"] = "走！",
            ["ContentJP"] = "行こう！",
            ["DialogueId"] = 11018913,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95AE6A",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE6A",
            },
        [11018914] = {
            ["Content"] = "水位一直在上涨，必须赶在被淹没之前离开这儿！",
            ["ContentJP"] = "水位は上がり続けてます。急いで脱出しないと！",
            ["DialogueId"] = 11018914,
            ["GUID"] = "1B95AE94",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AE94",
            },
        [11018915] = {
            ["Content"] = "这里刻着使用说明：“同时开启储水池外围的三个辅助水阀可加速排水……”",
            ["ContentJP"] = "ここに使用説明が刻まれていますね。えっと、「貯水池外周の補助排水バルブ3つを同時に起動することで、排水速度を加速できる……」",
            ["DialogueId"] = 11018915,
            ["GUID"] = "1B95AEBE",
            ["NextDialogue"] = 11014803,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AEBE",
            },
        [11018916] = {
            ["Content"] = "好，可以出去了……",
            ["ContentJP"] = "やった、ようやく外に出られますね……",
            ["DialogueId"] = 11018916,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95AEE8",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AEE8",
            },
        [11018917] = {
            ["Content"] = "他们……要烧毁这里？",
            ["ContentJP"] = "{性别2:ここを……爆破するつもりなのか？|ここを……爆破するつもり？}",
            ["DialogueId"] = 11018917,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95AC72",
            ["NextDialogue"] = 11018902,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110189/1B95AC72",
            },
        [11019005] = {
            ["Camera"] = "14.98733,-14.154265,30.628906,0.000071,5.795005,178.84024,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "海尔法典狱长，我一直在等待你亲自审问。这些真相，我必须亲口讲给你听。",
            ["ContentJP"] = "ヘルファイア典獄殿、待ってたよ。どうしても……この口から伝える必要があったからね。",
            ["DialogueId"] = 11019005,
            ["Duration"] = 7,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "2.373075,-13.902337,31.914062,0.000071,5.795005,178.84024,45.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B95BD82",
            ["NextDialogue"] = 11015315,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110039:Sit_Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BD82",
            },
        [11019006] = {
            ["Content"] = "想起来了……刚刚是，典狱长在说……“审讯”……",
            ["ContentJP"] = "思い出した……さっき、典獄殿が言ってた「尋問」……",
            ["DialogueId"] = 11019006,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BDAC",
            ["NextDialogue"] = 11019007,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BDAC",
            },
        [11019007] = {
            ["Content"] = "那位审讯官提到了“催眠药剂”……",
            ["ContentJP"] = "あの尋問官は「催眠剤」と口にしていた……",
            ["DialogueId"] = 11019007,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BDD6",
            ["NextDialogue"] = 11019008,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BDD6",
            },
        [11019008] = {
            ["Content"] = "这里……应该不是真实的世界。我想我现在正在梦中。",
            ["ContentJP"] = "ここは……現実ではない。私は幻を見ているのだろう{性别2:か|}。",
            ["DialogueId"] = 11019008,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BE00",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE00",
            },
        [11019009] = {
            ["Content"] = "（“老师”和“达芙涅”都消失了……）",
            ["ContentJP"] = "（「教官」と「ダフネ」が消えた……）",
            ["DialogueId"] = 11019009,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BE2A",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE2A",
            },
        [11019010] = {
            ["Content"] = "（神弃者同盟……？）",
            ["ContentJP"] = "（フォーセイクン同盟……？）",
            ["DialogueId"] = 11019010,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BE54",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE54",
            },
        [11019011] = {
            ["Content"] = "先遣小队全军覆没。",
            ["ContentJP"] = "先遣隊は全滅した。",
            ["DialogueId"] = 11019011,
            ["GUID"] = "1B95BE7E",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BE7E",
            },
        [11019012] = {
            ["Content"] = "干得漂亮，朋友。",
            ["ContentJP"] = "よくやった、相棒。",
            ["DialogueId"] = 11019012,
            ["GUID"] = "1B95BEA8",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BEA8",
            },
        [11019013] = {
            ["Content"] = "这就是军团狗应得的下场。",
            ["ContentJP"] = "これが軍団の犬どもの末路ってやつさ。",
            ["DialogueId"] = 11019013,
            ["GUID"] = "1B95BED2",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BED2",
            },
        [11019014] = {
            ["Content"] = "为我们的合作干杯！",
            ["ContentJP"] = "俺たちに乾杯！",
            ["DialogueId"] = 11019014,
            ["GUID"] = "1B95BEFC",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BEFC",
            },
        [11019015] = {
            ["Content"] = "一起庆祝吧，亲爱的~",
            ["ContentJP"] = "ねぇ、一緒にお祝いしよ。",
            ["DialogueId"] = 11019015,
            ["GUID"] = "1B95BF26",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BF26",
            },
        [11019016] = {
            ["Content"] = "……从我的梦里滚出去。",
            ["ContentJP"] = "{性别2:……私の夢から出てけ。|……私の夢から出てって。}",
            ["DialogueId"] = 11019016,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BF50",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BF50",
            },
        [11019017] = {
            ["Camera"] = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "第一个问题，作为帝国的士兵，你是否背叛了帝国？",
            ["ContentJP"] = "第一の質問だ。帝国の兵士として──お前は帝国を裏切り、フォーセイクン同盟に機密を漏洩したのか？",
            ["DialogueId"] = 11019017,
            ["Duration"] = 3,
            ["GUID"] = "1B95BF7A",
            ["NextDialogue"] = 11019018,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BF7A",
            },
        [11019018] = {
            ["Content"] = "若你背叛了帝国的正义，就被秽兽的利爪撕碎！",
            ["ContentJP"] = "もしお前が帝国の正義を裏切ったのなら──その身、<Default note=\"text:エジュウ\">穢獣</>の爪で引き裂かれるがいい！",
            ["DialogueId"] = 11019018,
            ["Duration"] = 3,
            ["GUID"] = "1B95BFA4",
            ["NextDialogue"] = 11019019,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BFA4",
            },
        [11019019] = {
            ["Content"] = "（……这个问题很容易回答。）",
            ["ContentJP"] = "（……こんな質問、迷う必要もない。）",
            ["DialogueId"] = 11019019,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BFCE",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BFCE",
            },
        [11019020] = {
            ["Content"] = "（呃——！身体突然变得好沉重……我不该承认那些指控。）",
            ["ContentJP"] = "（うっ……！身体が急に重く……こんなことなら、認めるんじゃなかった……）",
            ["DialogueId"] = 11019020,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95BFF8",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95BFF8",
            },
        [11019021] = {
            ["Content"] = "（为什么这里也有秽兽……！）",
            ["ContentJP"] = "（なぜこんなところに<Default note=\"text:エジュウ\">穢獣</>が……！）",
            ["DialogueId"] = 11019021,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C022",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C022",
            },
        [11019022] = {
            ["Content"] = "（不……冷静下来。它们不过是虚影而已。）",
            ["ContentJP"] = "（いや……落ち着け。あれはただの幻……）",
            ["DialogueId"] = 11019022,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C04C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C04C",
            },
        [11019023] = {
            ["Content"] = "（没错。绝不能承认那些指控。）",
            ["ContentJP"] = "（そうだ……あんな告発、絶対に認めちゃダメだ。）",
            ["DialogueId"] = 11019023,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C076",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C076",
            },
        [11019024] = {
            ["Content"] = "（秽兽……）",
            ["ContentJP"] = "（<Default note=\"text:エジュウ\">穢獣</>……）",
            ["DialogueId"] = 11019024,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C0A0",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C0A0",
            },
        [11019025] = {
            ["Content"] = "（不，它们只是虚影而已……）",
            ["ContentJP"] = "（違う、あれはただの{性别2:幻だ|幻}。）",
            ["DialogueId"] = 11019025,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C0CA",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C0CA",
            },
        [11019026] = {
            ["Camera"] = "-13.981445,564.373535,123.75,0.00011,3.399125,89.793884,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "第二个问题，龙莎一役中，先遣队伍全军覆没，是否与你有关？",
            ["ContentJP"] = "第二の質問だ。ロンザ要塞での戦いにおいて、先遣隊が全滅した件──お前と関係はあるか？",
            ["DialogueId"] = 11019026,
            ["GUID"] = "1B95C0F4",
            ["NextDialogue"] = 11019027,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C0F4",
            },
        [11019027] = {
            ["Camera"] = "-4.504883,1095.012207,226.371094,-0.000824,-13.200255,-89.031578,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "若你背弃了同胞的正义，就溅血于自己的锋刃！",
            ["ContentJP"] = "同胞の正義を裏切ったのなら──その血、自らの刃で浴びることになるだろう！",
            ["DialogueId"] = 11019027,
            ["GUID"] = "1B95C11E",
            ["NextDialogue"] = 11019028,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C11E",
            },
        [11019028] = {
            ["Camera"] = "13.287109,114.423828,114.03125,-0.000825,14.198904,-86.82589,17.134987,100000.0,false,Manual,22.0",
            ["Content"] = "（无需迷惘，坚定地做出选择吧。）",
            ["ContentJP"] = "（迷うことはない。覚悟を決めて、選ぶんだ。）",
            ["DialogueId"] = 11019028,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C148",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C148",
            },
        [11019029] = {
            ["Content"] = "（呃——！身体突然变得好沉重……我不该承认那些指控。）",
            ["ContentJP"] = "（うっ……！身体が急に重く……こんなことなら、認めるんじゃなかった……）",
            ["DialogueId"] = 11019029,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C172",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C172",
            },
        [11019030] = {
            ["Content"] = "（你是……谁？！）",
            ["ContentJP"] = "（あなたは……？）",
            ["DialogueId"] = 11019030,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C19C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C19C",
            },
        [11019031] = {
            ["Content"] = "（不……{性别2：他|她}不是我。）",
            ["ContentJP"] = "（いや……この人は私じゃない。）",
            ["DialogueId"] = 11019031,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C1C6",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C1C6",
            },
        [11019032] = {
            ["Content"] = "（是的，我必须走出这里，把真相……）",
            ["ContentJP"] = "（そうだ、ここを抜け出さなきゃ……はやく真実を――）",
            ["DialogueId"] = 11019032,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C1F0",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C1F0",
            },
        [11019033] = {
            ["Content"] = "（你不是我。你只是一个愚蠢的赝品。）",
            ["ContentJP"] = "（お前は私じゃない。ただの出来損ないの模造品だ。）",
            ["DialogueId"] = 11019033,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C21A",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C21A",
            },
        [11019034] = {
            ["Content"] = "消失吧。",
            ["ContentJP"] = "{性别2:消えろ。|消えなさい。}",
            ["DialogueId"] = 11019034,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C244",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C244",
            },
        [11019035] = {
            ["Content"] = "（前面好像走不通了……要回头吗？）",
            ["ContentJP"] = "（これ以上は進めない……引き返す？）",
            ["DialogueId"] = 11019035,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C26E",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C26E",
            },
        [11019036] = {
            ["Content"] = "坚称无罪之人，你会因愤怒动摇吗？",
            ["ContentJP"] = "無実を訴える者よ、お前は怒りに心を乱すか？",
            ["DialogueId"] = 11019036,
            ["GUID"] = "1B95C298",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C298",
            },
        [11019037] = {
            ["Content"] = "善后得怎么样了？",
            ["ContentJP"] = "後処理はどうなった？",
            ["DialogueId"] = 11019037,
            ["GUID"] = "1B95C2C2",
            ["NextDialogue"] = 11019038,
            ["SpeakNpcId"] = 110011,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C2C2",
            },
        [11019038] = {
            ["Content"] = "干干净净，如您所见。",
            ["ContentJP"] = "ご覧のとおり、きれいさっぱり片付きましたよ。",
            ["DialogueId"] = 11019038,
            ["GUID"] = "1B95C2EC",
            ["SpeakNpcId"] = 110012,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C2EC",
            },
        [11019039] = {
            ["Content"] = "（是他们两个……！）",
            ["ContentJP"] = "（あいつら……！）",
            ["DialogueId"] = 11019039,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C316",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C316",
            },
        [11019040] = {
            ["Content"] = "坚称无罪之人，你会因悲哀动摇吗？",
            ["ContentJP"] = "無実を訴える者よ──お前は悲しみに心を乱すか？",
            ["DialogueId"] = 11019040,
            ["GUID"] = "1B95C340",
            ["SpeakNpcId"] = 110032,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C340",
            },
        [11019041] = {
            ["Content"] = "{nickname2}，我的学生……",
            ["ContentJP"] = "{nickname2}、我が生徒よ……",
            ["DialogueId"] = 11019041,
            ["GUID"] = "1B95C36A",
            ["NextDialogue"] = 11019042,
            ["SpeakNpcId"] = 110010,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C36A",
            },
        [11019042] = {
            ["Content"] = "阿瓦尔老师？！",
            ["ContentJP"] = "アヴァール教官！！",
            ["DialogueId"] = 11019042,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C394",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C394",
            },
        [11019043] = {
            ["Content"] = "唔——！",
            ["ContentJP"] = "っ——！",
            ["DialogueId"] = 11019043,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C3BE",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C3BE",
            },
        [11019044] = {
            ["Content"] = "（这是一张全然陌生的脸。）",
            ["ContentJP"] = "（まったく見覚えのない顔だ……）",
            ["DialogueId"] = 11019044,
            ["GUID"] = "1B95C3E8",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C3E8",
            },
        [11019045] = {
            ["Content"] = "坚称无罪之人，你会因迷惘动摇吗？",
            ["ContentJP"] = "無実を訴える者よ、お前は戸惑いに心を乱すか？",
            ["DialogueId"] = 11019045,
            ["GUID"] = "1B95C412",
            ["NextDialogue"] = 11019046,
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C412",
            },
        [11019046] = {
            ["Content"] = "亲爱的长官，我来为您指路……",
            ["ContentJP"] = "長官、お迎えに上がりました……",
            ["DialogueId"] = 11019046,
            ["GUID"] = "1B95C43C",
            ["NextDialogue"] = 11019047,
            ["SpeakNpcId"] = 110009,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C43C",
            },
        [11019047] = {
            ["Content"] = "是……通向地狱的路……",
            ["ContentJP"] = "どうぞ……地獄へ……",
            ["DialogueId"] = 11019047,
            ["GUID"] = "1B95C466",
            ["SpeakNpcId"] = 110009,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C466",
            },
        [11019048] = {
            ["Content"] = "典狱长大人，够了……！请停下吧！",
            ["ContentJP"] = "典獄殿、もうやめてください！",
            ["DialogueId"] = 11019048,
            ["GUID"] = "1B95C490",
            ["NextDialogue"] = 11019049,
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C490",
            },
        [11019049] = {
            ["Content"] = "{nickname2}，请跟我来，我带您离开这里！",
            ["ContentJP"] = "{nickname2}さん、こちらへ！一緒にここを離れましょう！",
            ["DialogueId"] = 11019049,
            ["GUID"] = "1B95C4BA",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C4BA",
            },
        [11019050] = {
            ["Content"] = "无论前方等待您的是什么……请记得……",
            ["ContentJP"] = "この先に何があろうと……どうか忘れないでください……",
            ["DialogueId"] = 11019050,
            ["GUID"] = "1B95C4E4",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C4E4",
            },
        [11019051] = {
            ["Content"] = "我会和您一起活下去！",
            ["ContentJP"] = "私はあなたと共に生きると！",
            ["DialogueId"] = 11019051,
            ["GUID"] = "1B95C50E",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C50E",
            },
        [11019052] = {
            ["Content"] = "（这就是她对我意志的最后试炼了。）",
            ["ContentJP"] = "（これが最後の試練のようだね。）",
            ["DialogueId"] = 11019052,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C538",
            ["NextDialogue"] = 11019053,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C538",
            },
        [11019053] = {
            ["Content"] = "（必须撑过这场审判的梦……必须把真相亲口告诉她！）",
            ["ContentJP"] = "（この裁きの夢を乗り越えて……この口で彼女に真実を伝えないと！）",
            ["DialogueId"] = 11019053,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95C562",
            ["NextDialogue"] = 11019054,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C562",
            },
        [11019054] = {
            ["Content"] = "坚称无罪之人，若你仍不曾动摇，就把胸中意志熔铸成锋刃——",
            ["ContentJP"] = "無実を訴える者よ──なお心に迷いがないというのなら、その胸の意志を刃へとして鍛え上げてみせよ――",
            ["DialogueId"] = 11019054,
            ["DisableMouth"] = 1,
            ["GUID"] = "1B95C58C",
            ["NextDialogue"] = 11019055,
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C58C",
            },
        [11019055] = {
            ["Content"] = "用你手中的剑回答我！",
            ["ContentJP"] = "その剣をもって──答えろ！",
            ["DialogueId"] = 11019055,
            ["DisableMouth"] = 1,
            ["GUID"] = "1B95C5B6",
            ["SnapShot"] = "MONSTER",
            ["SpeakNpcId"] = 110032,
            ["SpeakNpcName"] = "UI_Npc_Wardenry",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C5B6",
            },
        [11019056] = {
            ["Content"] = "是",
            ["ContentJP"] = "はい",
            ["DialogueId"] = 11019056,
            ["GUID"] = "1B95C5E0",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C5E0",
            },
        [11019057] = {
            ["Content"] = "否",
            ["ContentJP"] = "いいえ",
            ["DialogueId"] = 11019057,
            ["GUID"] = "1B95C60A",
            ["VoiceName"] = "voice/$Locale$/story/1002/110190/1B95C60A",
            },
        [11019101] = {
            ["Content"] = "决不能让士兵们冤屈的哭号，永远在龙莎要塞上空徘徊。",
            ["ContentJP"] = "兵たちの無念が、ロンザ要塞の空を彷徨い続けるような結末にはさせない。",
            ["DialogueId"] = 11019101,
            ["GUID"] = "1B95CD42",
            ["SpeakNpcId"] = 110005,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD42",
            },
        [11019102] = {
            ["Camera"] = "582.071289,-479.369141,593.910156,-0.000856,-38.992104,162.400696,15.284281,100000.0,false,Manual,22.0",
            ["Content"] = "所以，我们选择用这种方式来见你。",
            ["ContentJP"] = "だからこそ、この方法で……会いに来た。",
            ["DialogueId"] = 11019102,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "476.848633,-672.017578,593.910156,-0.000855,-39.992191,138.000839,15.284281,100000.0,false,Manual,22.0",
            ["GUID"] = "1B95CD6C",
            ["NextDialogue"] = 11019103,
            ["SpeakNpcId"] = 110022,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD6C",
            },
        [11019103] = {
            ["Content"] = "富尔维斯陷害阿瓦尔真正的目的，是排除帝国高层的卡戎之民。你明白，如果他的计划得逞，对帝国，以及对<H>你本人</>而言又意味着什么。",
            ["ContentJP"] = "フルヴィスがアヴァールを陥れた本当の目的は──帝国中枢にいるカロンを排除することだった。その計画が成功していたら、帝国にとって、そして……<H>あなた自身</>にとって、どれほどの意味を持っていたか……わかる{性别2:だろう|でしょう}？",
            ["DialogueId"] = 11019103,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95CD96",
            ["NextDialogue"] = 11016706,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CD96",
            },
        [11019104] = {
            ["Content"] = "幸运的话，你会得到一份决定性的证据。即使证据不幸被销毁，她的证言也有极大价值。请让我和她在你的主持下当面对质。",
            ["ContentJP"] = "運が良ければ、決定的な証拠が手に入るはず{性别2:だ|}。たとえ証拠が不幸にも破棄されていたとしても──彼女の証言には極めて大きな価値がある。どうか、あなたの立ち会いのもとで、彼女に会わせて。",
            ["DialogueId"] = 11019104,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95CDC0",
            ["NextDialogue"] = 11016707,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CDC0",
            },
        [11019105] = {
            ["Content"] = "嗯。等你休息好了，我再仔细说给你听。",
            ["ContentJP"] = "うん。君がちゃんと休めたら、改めてゆっくり話すよ。",
            ["DialogueId"] = 11019105,
            ["GUID"] = "1B95CDEA",
            ["NextDialogue"] = 11019106,
            ["SpeakNpcId"] = 110018,
            ["TalkActionId"] = {
                [1] = "110018:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CDEA",
            },
        [11019106] = {
            ["Camera"] = "-201.890625,-407.858398,414.960938,0.000216,-22.600248,41.391022,18.0,254.013382,false,DoNotOverride,7.801928",
            ["Content"] = "我讨厌这座监狱里的血腥味儿，准备好了我们就走吧。",
            ["ContentJP"] = "準備ができ次第すぐにでも出発しようか。この刑務所の血生臭さにはもううんざりだし。",
            ["DialogueId"] = 11019106,
            ["FinalCamera"] = "-251.734375,-451.791016,442.613281,0.000208,-22.000229,41.39093,18.0,254.013382,false,DoNotOverride,7.801928",
            ["GUID"] = "1B95CE14",
            ["SpeakNpcId"] = 110018,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CE14",
            },
        [11019107] = {
            ["Content"] = "五日后",
            ["ContentJP"] = "5日後",
            ["DialogueId"] = 11019107,
            ["GUID"] = "1B95CE3E",
            ["NextDialogue"] = 11019108,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CE3E",
            },
        [11019108] = {
            ["Content"] = "皇都·迪斯玛尼亚 皇家大剧院",
            ["ContentJP"] = "帝都ディズマニア 皇立劇場",
            ["DialogueId"] = 11019108,
            ["GUID"] = "1B95CE68",
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95CE68",
            },
        [11019109] = {
            ["Camera"] = "41.970703,146.506836,246.835938,0.000077,-0.000096,-100.601891,31.194523,100000.0,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "刚才这出《雪国的孩子》是作曲家卡瓦拉多西的手笔，故事改编自流传于他家乡冰湖城的精怪传说……{nickname2}，你在听吗？",
            ["ContentJP"] = "さっきの『雪国の幼子』って曲、作ったのは作曲家のカヴァラドッシでね。彼の故郷、アイスレイク城に伝わる精霊の伝説をもとにした物語なんだよ……って、{nickname2}、聞いてる？",
            ["DialogueId"] = 11019109,
            ["Duration"] = 1,
            ["FacialId"] = {
                [1] = "110022:Think01",
                },
