        [11019123] = {
            ["Content"] = "（弗莱格桑省……）",
            ["ContentJP"] = "（フレグサン……）",
            ["DialogueId"] = 11019123,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95D0DE",
            ["NextDialogue"] = 11019124,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95D0DE",
            },
        [11019124] = {
            ["Content"] = "（那里有我连典狱长都没有告诉的……<H>那个东西</>……）",
            ["ContentJP"] = "（あの典獄にも教えなかった……<H>アレ</>がある場所か……）",
            ["DialogueId"] = 11019124,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B9488BE",
            ["NextDialogue"] = 11019125,
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110171/1B9488BE",
            },
        [11019125] = {
            ["Content"] = "（<H>第二新枝计划的另一个关键……零号的触媒</>。）",
            ["ContentJP"] = "（<H>「第2イノバンス」計画のもう一つの鍵であり…</> No.0の<H>触媒</>。）",
            ["DialogueId"] = 11019125,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95D132",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110191/1B95D132",
            },
        [11019201] = {
            ["Content"] = "喂，怎么了？蹲下干吗？",
            ["ContentJP"] = "おい、どうした？しゃがんで何してる？",
            ["DialogueId"] = 11019201,
            ["GUID"] = "1B95DDAA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11019202,
            ["SpeakNpcId"] = 110015,
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDAA",
            },
        [11019202] = {
            ["Content"] = "我跟你说少在这装可怜啊，我可不吃这一套！跟我走！",
            ["ContentJP"] = "言っとくけど可哀想ぶったりしても無駄だかんな！ほら、ついてこい！",
            ["DialogueId"] = 11019202,
            ["GUID"] = "1B95DDD4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 11012303,
            ["SpeakNpcId"] = 110015,
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD4",
            },
        [11019203] = {
            ["Content"] = "请走这边！",
            ["ContentJP"] = "こちらです！",
            ["DialogueId"] = 11019203,
            ["GUID"] = "1B95DDD5",
            ["SpeakNpcId"] = 110034,
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD5",
            },
        [11019204] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11019204,
            ["GUID"] = "1B95DDD6",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD6",
            },
        [11019205] = {
            ["Content"] = "（是运输用升降机，兴许可以得到补给。不过，也要小心留意是否有埋伏的敌人。）",
            ["ContentJP"] = "（物資輸送用のエレベーターか……補給が手に入るかもしれない。でも、待ち伏せには警戒しておいた方がよさそう{性别2:だ|}。）",
            ["DialogueId"] = 11019205,
            ["DisableMouth"] = 1,
            ["GUID"] = "1B95DDD7",
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD7",
            },
        [11019206] = {
            ["Content"] = "这个房间暂时安全，可以操作控制台了。",
            ["ContentJP"] = "この部屋はひとまず安全だ。制御装置を操作しよう。",
            ["DialogueId"] = 11019206,
            ["GUID"] = "1B95DDD8",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD8",
            },
        [11019207] = {
            ["Content"] = "获取控制权限中，请稍等。",
            ["ContentJP"] = "制御権限取得中。少々お待ちください。",
            ["DialogueId"] = 11019207,
            ["GUID"] = "1B95DDD9",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDD9",
            },
        [11019208] = {
            ["Content"] = "（中央控制室是独立供能……这里的髓动轮并未受到动力室爆炸的影响。）",
            ["ContentJP"] = "（中央制御室は独立した電力供給だから……ここにあるイコル駆動輪は、動力室の爆発の影響を受けていないみたい。）",
            ["DialogueId"] = 11019208,
            ["GUID"] = "1B95DDDA",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDDA",
            },
        [11019209] = {
            ["Content"] = "线路错误，控制台处于保护状态。请关闭髓动轮以解除保护状态。",
            ["ContentJP"] = "回路エラー、制御装置は保護状態にあります。保護状態を解除するために、イコル駆動輪を停止してください。",
            ["DialogueId"] = 11019209,
            ["GUID"] = "1B95DDDB",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110192/1B95DDDB",
            },
        [11019301] = {
