            },
        [11019306] = {
            ["Camera"] = "-179.412964,-186.140625,-9.101074,0.000056,9.994964,89.912399,35.000011,76.53801,false,Manual,22.0",
            ["Content"] = "（没时间了……）",
            ["ContentJP"] = "（間に合わない……）",
            ["DialogueId"] = 11019306,
            ["DisableMouth"] = 1,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95EEE4",
            ["NextOptions"] = {
