            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95EEE4",
            },
        [11019307] = {
            ["Content"] = "给自己注射强心剂",
            ["ContentJP"] = "自分に興奮剤を打つ",
            ["DialogueId"] = 11019307,
            ["GUID"] = "1B95EF0E",
            ["NextDialogue"] = 11019308,
            },
        [11019308] = {
            ["Content"] = "（这样应该足够撑一会儿……我得先离开这里！）",
            ["ContentJP"] = "（これでしばらくはもつはず……今は、まずここを離れないと！）",
            ["DialogueId"] = 11019308,
            ["DisableMouth"] = 1,
