            ["TalkActionId"] = {
                [1] = "110022:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95EFE0",
            },
        [11019313] = {
            ["Camera"] = "-68.800133,168.857269,475.46875,-2.999996,-69.999832,-56.789295,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "阵亡士兵的尸检报告中多有要塞机关所伤的痕迹，而中央控制室的机密记录仪中，只留有阿瓦尔·赫德兰和你二人的操作记录。你怎么解释？",
            ["ContentJP"] = "亡くなった兵士を検死したところ、大多数の死因が要塞設備の攻撃によるものだと報告には記載されている。中央制御室の機密ログにはアヴァール·ハードランドとお前の操作記録しか残されていなかった。これについてはどう説明する？",
            ["DialogueId"] = 11019313,
            ["Duration"] = 2,
            ["FinalCamera"] = "-90.44854,156.158005,475.027344,-2.999996,-69.999832,-56.789295,15.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B95F00A",
            ["NextDialogue"] = 11019314,
            ["SpeakNpcId"] = 110039,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F00A",
            },
        [11019314] = {
            ["Camera"] = "0.64937,21.817383,42.609375,5.00035,-6.998867,-165.187607,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们接管要塞的操作权限，不是为了开启机关，而是为了关停机关。",
            ["ContentJP"] = "{性别2:要塞の操作権限を引き継いだのは防衛装置を起動するためではなく、停止するためだ。|要塞の操作権限を引き継いだのは防衛装置を起動するためではなく、停止するためよ。}",
            ["DialogueId"] = 11019314,
            ["Duration"] = 2,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-1.82135,30.754875,43.375,5.000283,-6.998867,-165.188583,15.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B95F034",
            ["NextDialogue"] = 11019315,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F034",
            },
        [11019315] = {
            ["Camera"] = "-87.908264,37.815254,47.214844,5.000778,2.401037,-147.587677,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "至于操作记录，如果现场有某位军官夺取了阿瓦尔的秘钥，那么他完全可以用阿瓦尔的权限删除“不需要”的操作记录。",
            ["ContentJP"] = "記録なんて、彼の鍵さえ手に入れていれば、後から「不要な操作」だけを消すなんて造作もないこと{性别2:だろう|でしょ}？",
            ["DialogueId"] = 11019315,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["FinalCamera"] = "-85.94146,34.681473,46.878906,5.000793,2.401037,-147.587509,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1B95F05E",
            ["NextDialogue"] = 11015307,
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "110022:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F05E",
            },
        [11019316] = {
            ["Content"] = "我这是在哪儿……",
            ["ContentJP"] = "ここは……",
            ["DialogueId"] = 11019316,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95F088",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F088",
            },
        [11019317] = {
            ["Content"] = "要塞被攻占的当日，在中央控制室执行操作的，只有阿瓦尔·赫德兰和{nickname2}。",
            ["ContentJP"] = "要塞が占拠された当日、中央制御室で操作を行ったのは、アヴァール·ハードランドおよび{nickname2}のみです。",
            ["DialogueId"] = 11019317,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95F0B2",
            ["NextDialogue"] = 11019318,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F0B2",
            },
        [11019318] = {
            ["Content"] = "最终，{nickname2}开启了自毁模式。",
            ["ContentJP"] = "そして最終的に、{nickname2}が自爆モードを起動しました。",
            ["DialogueId"] = 11019318,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95F0DC",
            ["NextDialogue"] = 11019320,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F0DC",
            },
        [11019320] = {
            ["Content"] = "但我搭载了工程炼金院全新材料制造的机密记录仪，即使控制台被烧坏，操作记录也不会消失，哈哈，哈哈。",
            ["ContentJP"] = "だが私は、工学錬金院の最新素材で作られた機密記録装置を搭載しています。たとえ制御台が焼き払われても、操作記録は消えません──ハハ、ハハ……",
            ["DialogueId"] = 11019320,
            ["Duration"] = 3,
            ["GUID"] = "1B95F130",
            ["NextDialogue"] = 11016005,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcName"] = "UI_Npc_MechVoice",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F130",
            },
        [11019321] = {
            ["Content"] = "（是……先遣小队的战友……）",
            ["ContentJP"] = "（この人、先行部隊にいた……）",
            ["DialogueId"] = 11019321,
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95F15A",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 110022,
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F15A",
            },
        [11019322] = {
            ["Content"] = "军团有叛徒……",
            ["ContentJP"] = "軍団に裏切り者がいる……",
            ["DialogueId"] = 11019322,
            ["GUID"] = "1B95F184",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F184",
            },
        [11019323] = {
            ["Content"] = "好痛……好痛……",
            ["ContentJP"] = "痛い……痛いよ……",
            ["DialogueId"] = 11019323,
            ["GUID"] = "1B95F1AE",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F1AE",
            },
        [11019324] = {
            ["Content"] = "我不想倒在这里……",
            ["ContentJP"] = "こんなところごめんだ……",
            ["DialogueId"] = 11019324,
            ["GUID"] = "1B95F1D8",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F1D8",
            },
        [11019325] = {
            ["Content"] = "秽兽在吃我的腿……妈妈……",
            ["ContentJP"] = "……穢獣に……脚を……食いちぎられた……母さん……",
            ["DialogueId"] = 11019325,
            ["GUID"] = "1B95F202",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F202",
            },
        [11019326] = {
            ["Content"] = "是谁出卖了我们？",
            ["ContentJP"] = "私たちを裏切ったのは誰なの？",
            ["DialogueId"] = 11019326,
            ["GUID"] = "1B95F22C",
            ["VoiceName"] = "voice/$Locale$/story/1002/110193/1B95F22C",
            },
        [11019401] = {
            ["Content"] = "……",
            ["DialogueId"] = 11019401,
            ["DialoguePanelType"] = "None",
            ["ExStoryInfo"] = "EXPlayer",
            ["GUID"] = "1B95FE7A",
            ["Scripts"] = "PlayAnimation{_click{false},_delay{3},ActorId{0},AnimationId{\"Sigh_End\"},Duration{3}}",
            ["SpeakNpcId"] = 110022,
            ["TalkActionId"] = {
                [1] = "0:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FE7A",
            },
        [11019402] = {
            ["Content"] = "们我了叛背人有见所人大长判审如阱陷了置设都上路条一每在盟同者弃神",
            ["ContentJP"] = "とかるあで物人い高も最が性能可すら漏を画計に盟同ンクイセーォフだ族ンロカは彼",
            ["DialogueId"] = 11019402,
            ["GUID"] = "1B95FEA4",
            ["SpeakNpcId"] = 110016,
            ["SpeakNpcName"] = "UI_Npc_DreamMaerke",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FEA4",
            },
        [11019403] = {
            ["Content"] = "人的划计露泄盟同者弃神向能可最是他的民之戎卡为身",
            ["ContentJP"] = "たしまりおてけ掛仕を罠にて全トール攻進は盟同ンクイセーォフ",
            ["DialogueId"] = 11019403,
            ["GUID"] = "1B95FECE",
            ["SpeakNpcId"] = 110017,
            ["SpeakNpcName"] = "UI_Npc_DreamLaiang",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FECE",
            },
        [11019404] = {
            ["Content"] = "队遣先支两狼雪鹫狮了卖出团军三十了叛背国帝亚利伯海了叛背我",
            ["ContentJP"] = "たっ売をフルウーノスンィフリグ隊遣先だ間人たっ切裏を団軍三十第、り切裏を国帝アリペュヒ",
            ["DialogueId"] = 11019404,
            ["GUID"] = "1B95FEF8",
            ["SpeakNpcId"] = 110010,
            ["SpeakNpcName"] = "UI_Npc_DreamAware",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FEF8",
            },
        [11019405] = {
            ["Content"] = "决判的正公予给人大长判审求恳前面人大长判审到带手凶将我",
            ["ContentJP"] = "ましたいい願おを決判な正公かうどすませさ廷出とへ前の様長判裁を人犯",
            ["DialogueId"] = 11019405,
            ["GUID"] = "1B95FF22",
            ["SpeakNpcId"] = 110005,
            ["SpeakNpcName"] = "UI_Npc_DreamDafu",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FF22",
            },
        [11019406] = {
            ["Content"] = "开门",
            ["ContentJP"] = "扉を開ける",
            ["DialogueId"] = 11019406,
            ["GUID"] = "1B95FF4C",
            ["NextDialogue"] = 11019407,
            },
        [11019407] = {
            ["Content"] = "（按下“开门”按钮，但大门纹丝不动——它被做了什么手脚吗？看来事情并非想象中那么简单。）",
            ["ContentJP"] = "「扉を開ける」のボタンを押しても扉はびくっとも動きはしなかったーーなにか小細工でも施されたのか？どうやら何もかもがまだ終わってない…",
            ["DialogueId"] = 11019407,
            ["GUID"] = "1B95FF76",
            ["NextOptions"] = {
                [1] = 11019408,
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FF76",
            },
        [11019408] = {
            ["Content"] = "查阅文件",
            ["ContentJP"] = "ファイルを確認",
            ["DialogueId"] = 11019408,
            ["GUID"] = "1B95FFA0",
            ["NextDialogue"] = 11018807,
            },
        [11019409] = {
            ["Content"] = "……",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 11019409,
            ["GUID"] = "1B95FFCA",
            ["NextOptions"] = {
                [1] = 11019406,
                },
            },
        [11019410] = {
            ["Content"] = "最后的审判",
            ["ContentJP"] = "最後の審判",
            ["DialogueId"] = 11019410,
            ["GUID"] = "1B95FFF4",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B95FFF4",
            },
        [11019411] = {
            ["Content"] = "背叛者？",
            ["ContentJP"] = "裏切り者？",
            ["DialogueId"] = 11019411,
            ["GUID"] = "1B96001E",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B96001E",
            },
        [11019412] = {
            ["Content"] = "无罪者？",
            ["ContentJP"] = "罪なき者？",
            ["DialogueId"] = 11019412,
            ["GUID"] = "1B960048",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B960048",
            },
        [11019413] = {
            ["Content"] = "活下去",
            ["ContentJP"] = "生きる",
            ["DialogueId"] = 11019413,
            ["GUID"] = "1B960072",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B960072",
            },
        [11019414] = {
            ["Content"] = "和达芙涅",
            ["ContentJP"] = "ダフネと",
            ["DialogueId"] = 11019414,
            ["GUID"] = "1B96009C",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B96009C",
            },
        [11019415] = {
            ["Content"] = "一起",
            ["ContentJP"] = "一緒に",
            ["DialogueId"] = 11019415,
            ["GUID"] = "1B9600C6",
            ["VoiceName"] = "voice/$Locale$/story/1002/110194/1B9600C6",
            },
        [11019416] = {
            ["Content"] = "（士兵们已经没有了气息。）",
            ["ContentJP"] = "兵士たちはすでに息絶えている。",
            ["DialogueId"] = 11019416,
            ["GUID"] = "1B9600C7",
            },
        [11019417] = {
            ["Content"] = "（秽兽的尸骸——正是这些怪物夺走了士兵们年轻的生命；而士兵们也在最后一刻，在它们身上留下了致命的弹孔。）",
            ["ContentJP"] = "穢獣の死骸――これらの怪物が若き兵士たちの命を奪った。だが、兵士たちも最後の瞬間に、獣たちに致命の一撃を刻んでいた。",
            ["DialogueId"] = 11019417,
            ["GUID"] = "1B9600C8",
            },
        [11019418] = {
            ["DialogueId"] = 11019418,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_JailInves02;content:READ_TEXT_JailInves02}",
            ["GUID"] = "1B9600C9",
            },
        [11019419] = {
            ["DialogueId"] = 11019419,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_JailInves01;content:READ_TEXT_JailInves01}",
            ["GUID"] = "1B9600CA",
            },
        [11019420] = {
            ["Content"] = "你向典狱长承认了罪行，等待你的将是更为严酷的裁决。",
            ["ContentJP"] = "あなたは典獄に罪を認めた。この先にはより苛酷な裁決が来るのであろう。",
            ["DialogueId"] = 11019420,
            ["Duration"] = 4,
            ["GUID"] = "1B9600CB",
            ["NextDialogue"] = 11019421,
            },
        [11019421] = {
            ["Content"] = "你听见她的嗤笑——她曾认为你坚强无匹，但如今看来，你和她审判过的其他囚犯也并无分别。",
            ["ContentJP"] = "彼女のせせら笑いが耳に刺さる.。かつて彼女は、あなたは決して折れぬ者だと信じていたけれど、今では、これまで裁いてきた囚人たちと何も変わらぬ存在にしか見えていない。",
            ["DialogueId"] = 11019421,
            ["Duration"] = 4,
            ["GUID"] = "1B9600CC",
            ["NextDialogue"] = 11019422,
            },
        [11019422] = {
            ["Content"] = "你意识到自己正在坠入漆黑的深渊——你开始思索，如果当时你的意志能够更坚定一些，结局会不会有所不同？",
            ["ContentJP"] = "奈落の闇へと沈んでいく時、あなたは考え始めた。もしあの頃は、覚悟がもう少し強かったなら、結末は違っていたのだろうか、と。",
            ["DialogueId"] = 11019422,
            ["Duration"] = 4,
            ["GUID"] = "1B9600CD",
            },
        [12000100] = {
            ["Content"] = "东国引入测试文本",
            ["DialogueId"] = 12000100,
            ["GUID"] = "1E0A7E68",
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1200/120001/1E0A7E68",
            },
        [12000401] = {
            ["Camera"] = "867.037842,-235.637695,67.861328,0.000032,17.998148,95.003975,25.0,137.990356,false,DoNotOverride,18.0",
            ["Content"] = "让我看看——帮人找走丢的猫，抓偷蜡烛的小贼，疏通堵塞的烟囱……怎么都是些让人提不起劲的小委托。",
            ["ContentJP"] = "ちょっと見せて……迷子の猫探し、ろうそくを盗んだ悪党の捕獲、煙突掃除……どれもやりがいのない依頼ばかりだな。",
            ["DialogueId"] = 12000401,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["FinalCamera"] = "851.23999,-237.014648,67.861328,0.000032,17.998148,95.003975,25.0,137.990356,false,DoNotOverride,18.0",
