            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB01E",
            },
        [12000404] = {
            ["Camera"] = "454.686768,177.710938,179.886719,0.000076,-13.001531,-36.781921,24.0,200.0,false,DoNotOverride,10.0",
            ["Content"] = "——呜呜不要！是{nickname}说，最近的委托都太小了，那一点点报酬都不够{性别：他|她}这个冉冉升起的冰湖之星·{性别：狩月之王|狩月女王}塞牙缝的！",
            ["ContentJP"] = "――ひぃえ！それだけはやめてー！そもそも、{nickname}が言い始めたんだよ。最近の依頼はどうも気が乗らないって。あの程度の報酬じゃ、『アイスレイクの新星』・{性别:月狩りの王|月狩りの女王}の足しにもならないって！",
            ["DialogueId"] = 12000404,
            ["FacialId"] = {
