            },
        [12000412] = {
            ["Camera"] = "210.601685,277.546875,150.097656,0.000214,2.402225,109.397453,35.0,312.341827,false,DoNotOverride,10.0",
            ["Content"] = "千万别。",
            ["ContentJP"] = "お断りするわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000412,
            ["GUID"] = "1E0AB198",
            ["NextDialogue"] = 12000413,
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB198",
            },
        [12000413] = {
            ["Content"] = "今天我有位难得的大客户要接待。你要是待在这儿，人家还以为我放着好好的酒馆生意不做，转头开幼儿园了呢。",
            ["ContentJP"] = "今日はちょっと特別なお客様が来るの。あなたがいると、酒場から幼稚園に転職するのかと思われちゃうじゃない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000413,
            ["FacialId"] = {
                [1] = "200003:Uninterested01",
                },
            ["GUID"] = "1E0AB1C2",
            ["NextDialogue"] = 12000414,
            ["SpeakNpcId"] = 200003,
            ["TalkActionId"] = {
                [1] = "200003:Talk03_End",
                [2] = "100001:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB1C2",
            },
        [12000414] = {
            ["Camera"] = "719.914917,-228.804688,96.634766,-2.0,-2.801607,32.384254,45.000023,171.47702,false,Manual,18.0",
            ["Content"] = "呜呜，不过是离开了几天，卡米拉就嫌弃起白了，呜呜。",
            ["ContentJP"] = "うぅ、数日いなかっただけで、スノウを追い出そうなんて、ひどいよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000414,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
