            ["GUID"] = "1E0AB1EC",
            ["NextDialogue"] = 12000415,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_Start",
                [2] = "200002:Talk03_End",
                [3] = "200003:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1200/120004/1E0AB1EC",
            },
        [12000415] = {
            ["Camera"] = "215.504517,220.833984,112.722656,0.000129,10.599026,104.21505,35.000011,150.0,false,Manual,10.0",
            ["Content"] = "别以为你那些小伎俩对我有用，眼泪在这酒馆里是最不值钱的东西。",
            ["ContentJP"] = "ふふっ、そんな小細工が私に通じると思ったら大間違いよ。涙なんて、この酒場じゃ一番価値のないものなんだから。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000415,
            ["FinalCamera"] = "215.504517,220.833984,94.533203,0.000106,17.199236,104.613319,35.000008,150.0,false,Manual,10.0",
