            ["GUID"] = "1E0AC0B1",
            ["ToFinalCameraBlendTime"] = 8,
            },
        }
  end },
  { MinKey = 12000506, MaxKey = 12001720, Loader = function()
      return {
        [12000506] = {
            ["Content"] = "开个车，提示去聊一下",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000506,
            ["GUID"] = "1E0AC0B2",
            ["NextDialogue"] = 12000507,
            },
        [12000507] = {
            ["Content"] = "开个车，提示去聊一下+1",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000507,
            ["GUID"] = "1E0AC0B3",
            },
        [12000601] = {
            ["Content"] = "以薇奥莱塔女士的美妙歌喉，那清澈饱满的高音，充满艺术性的花腔，一定能完美诠释妖精的角色，让这部经久不衰的歌剧达到新的高峰！",
            ["ContentJP"] = "ヴィオレッタさんのあの美しい歌声、澄んで豊かな高音に、芸術的なコロラトゥーラ！絶対に妖精の役を完璧に演じてくれるに違いないよ！この不朽のオペラが、新たな高みへと昇るのを見るのが楽しみだな！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000601,
            ["GUID"] = "1E0AD09A",
            ["NextDialogue"] = 12000602,
            ["SpeakNpcId"] = 220003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD09A",
            },
        [12000602] = {
            ["Content"] = "是吗……依我看，这里的歌剧班底是一年不如一年了，也就是勉强能入耳的水平。",
            ["ContentJP"] = "そうかね……ボクから見れば、このオペラ団のレベルは年々落ちてきてる気がするんだ。まあ、かろうじて聴けるってところだな。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000602,
            ["GUID"] = "1E0AD0C4",
            ["NextDialogue"] = 12000603,
            ["SpeakNpcId"] = 220004,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD0C4",
            },
        [12000603] = {
            ["Content"] = "那你还场场不落地买票？",
            ["ContentJP"] = "それでも毎回欠かさずチケット買ってるじゃないか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000603,
            ["GUID"] = "1E0AD0EE",
            ["NextDialogue"] = 12000604,
            ["SpeakNpcId"] = 220003,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD0EE",
            },
        [12000604] = {
            ["Content"] = "能不能听，总要实际到场后才好评价。毕竟也只能指着这些乐趣活了。",
            ["ContentJP"] = "聴けるかどうかは、やっぱり実際に来てみないとわからないでしょ？ 結局のところ、こういう楽しみで生きてるようなもんだからさ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000604,
            ["GUID"] = "1E0AD118",
            ["SpeakNpcId"] = 220004,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD118",
            },
        [12000605] = {
            ["Content"] = "爸爸，莉莉马上就能听到大姐姐们施展声音的魔法了！",
            ["ContentJP"] = "パパ、リリィもうすぐお姉さんたちの声の魔法が聴けるんだよね！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000605,
            ["GUID"] = "1E0AD142",
            ["NextDialogue"] = 12000606,
            ["SpeakNpcId"] = 220005,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD142",
            },
        [12000606] = {
            ["Content"] = "能和爸爸一起看歌剧，结束后还要去吃大餐，今天就是莉莉最幸福的一天！",
            ["ContentJP"] = "パパと一緒にオペラを観れて、そのあとごちそうも食べに行けるなんて、今日はリリィにとって一番幸せな日だよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000606,
            ["GUID"] = "1E0AD16C",
            ["SpeakNpcId"] = 220005,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD16C",
            },
        [12000607] = {
            ["Content"] = "喂，你听说了吗？前几天的银烛狂欢，有人在剧院当场行凶，直接惊动了军团老爷耶！",
            ["ContentJP"] = "おい、聞いたか？数日前の銀燭祭りで、劇場で誰かが騒動を起こしたらしい！帝国軍のお偉いさんまで出てきたんだってよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000607,
            ["GUID"] = "1E0AD196",
            ["NextDialogue"] = 12000608,
            ["SpeakNpcId"] = 220006,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD196",
            },
        [12000608] = {
            ["Content"] = "究竟是闹鬼、神弃者、还是“卡戎狩猎”的怪物复活了……想一探究竟的人，全被下封口令了！",
            ["ContentJP"] = "幽霊の仕業か、神に見捨てられた者の仕業か、それとも「カロン狩り」の犯人が蘇ったのか……真相を探ろうとした奴らはみんな口止めされちまったんだってよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000608,
            ["GUID"] = "1E0AD1C0",
            ["SpeakNpcId"] = 220006,
            ["VoiceName"] = "voice/$Locale$/story/1200/120006/1E0AD1C0",
            },
        [12000701] = {
            ["Camera"] = "-677.66748,25.194824,133.280273,0.000017,-4.400049,-14.604745,35.000008,576.302551,false,Manual,10.0",
            ["Content"] = "票，内部优惠，要不？",
            ["ContentJP"] = "チケット、特別割引あるよ？どうだい？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000701,
            ["FinalCamera"] = "-678.432617,22.252441,133.280273,0.000017,-4.400049,-14.604682,35.000008,576.302551,false,Manual,10.0",
