        [12000705] = {
            ["Camera"] = "-311.203369,-50.041016,41.681152,0.000108,8.198399,-25.589983,40.0,265.472382,false,DoNotOverride,10.0",
            ["Content"] = "这可是物超所值，在这个位置，薇奥莱塔女士裙子上的每一片亮片，到嘴唇最轻微的嚅动，都可以看得一清二楚！绝对是让人难以忘怀的体验！",
            ["ContentJP"] = "値段に目をくらませちゃいけないぜ。この席からなら、ヴィオレッタさんのドレスのラメから、唇のかすかな動きまで、すべてがはっきり見えるんだ。間違いなく忘れられない体験になるよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12000705,
            ["FinalCamera"] = "-314.26416,-56.431641,41.681152,0.000109,8.198385,-25.589556,40.0,265.472382,false,DoNotOverride,10.0",
