            },
        [12000710] = {
            ["Camera"] = "-89.339111,-5.74707,150.428711,0.00002,-10.800386,-53.803547,55.000008,267.196838,false,Manual,10.0",
            ["Content"] = "……不早说，浪费我时间。晦气。",
            ["ContentJP"] = "……最初からそう言えよ、時間の無駄だったじゃねぇか。ツイてねぇな。",
            ["DefaultLookAt"] = "TalkNpc",
