            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1200/120011/1E0B22CC",
            },
        [12001103] = {
            ["Camera"] = "219.5,-1363.567383,271.265625,0.000139,-9.198488,34.811485,30.0,240.0,false,Manual,10.0",
            ["Content"] = "以为用墨水描了日期就能用过期票混进去吗？成天把脑筋动在这种小偷小摸的事情上，逃不过我的眼睛！",
            ["ContentJP"] = "まさかインクで日付を書き足せば、期限切れのチケットでもバレないと思ったのか？一日中そんなセコい手ばかり考えていても、私の目はごまかせないぞ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001103,
            ["FacialId"] = {
                [1] = "220010:CM_Idle",
                [2] = "200002:Angry01",
                [3] = "100001:Unhappy01",
                },
            ["FinalCamera"] = "236.039062,-1352.068359,268.0,0.000141,-9.198488,34.811592,30.0,240.0,false,Manual,10.0",
            ["GUID"] = "1E0B22F6",
