            },
        [12001104] = {
            ["Content"] = "在确凿证据前，你们哑口无言。",
            ["ContentJP"] = "確たる証拠を突きつけられて、あなたたちは何も言えなくなる。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001104,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E0B2320",
            ["NextDialogue"] = 12001105,
            ["VoiceName"] = "voice/$Locale$/story/1200/120011/1E0B2320",
            },
        [12001105] = {
            ["Camera"] = "419.865234,-1179.731934,285.492188,0.000074,-32.19841,-16.777586,30.000002,240.0,false,DoNotOverride,10.0",
            ["Content"] = "不对啊，小仆从。这个票面上的图画，和白刚刚拿着的那张不一样！",
            ["ContentJP"] = "おかしいな、我が下僕よ。このチケットの絵柄、さっきスノウが持ってたやつとは違うぞ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001105,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["GUID"] = "1E0B234A",
            ["LookAt"] = {
                [1] = "100001:p(BP_12000201in_nvzhu)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12001106,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_Start",
                [2] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120011/1E0B234A",
            },
        [12001106] = {
            ["Camera"] = "427.664062,-1314.868652,193.546875,0.00007,14.599891,52.018433,38.0,240.0,false,DoNotOverride,10.0",
            ["Content"] = "难道是……刚刚那个男孩离开时，把我们的票偷换了？！",
            ["ContentJP"] = "まさか…さっきの男の子が、私たちのチケットをこっそりすり替えちゃったんじゃないの？！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001106,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "1E0B2374",
            ["NextDialogue"] = 12001107,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200002:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120011/1E0B2374",
            },
        [12001107] = {
            ["Camera"] = "293.919922,-1303.304199,263.761719,0.000144,-10.997807,22.19919,30.000002,240.0,false,Manual,10.0",
            ["Content"] = "他应该还没走远！我们找他说理去！",
            ["ContentJP"] = "あいつ、まだそんなに遠くへは行ってないはずだよ！さあ、直接文句を言いに行くよ！",
            ["DialogueId"] = 12001107,
            ["FacialId"] = {
