        [12001108] = {
            ["Camera"] = "432.458984,-1299.610352,214.050781,0.000149,15.399015,172.204926,30.000013,240.0,false,DoNotOverride,10.0",
            ["Content"] = "还想找借口逃跑？偷鸡摸狗的小鬼——不许走，我要把你们扭送进治安署去！",
            ["ContentJP"] = "まだ言い訳して逃げようってのか？こそこそ悪さばっかりするガキどもめ——逃がさんぞ！保安署に突き出してやるからな！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001108,
