        [12001116] = {
            ["Camera"] = "374.478516,-1404.547852,282.367188,-5.000006,-12.998567,-27.569317,45.0,391.082153,false,DoNotOverride,7.0",
            ["Content"] = "对、对不起，女士，我瞎说的，我头晕，说了胡话，我没有针对您的意思……",
            ["ContentJP"] = "す、すみません、奥様……なんでもございません。ちょっと頭がふらついてて、悪気はなかったんです……あなたに言ったわけじゃないんです、本当です……",
