        [12001118] = {
            ["Camera"] = "368.121094,-1520.700684,268.441406,0.000267,-12.199708,56.793133,30.0,391.082153,false,Manual,7.0",
            ["Content"] = "我们才没有想混进剧场，明明是我们的票被人调包了！白正要去找那个小偷理论呢！",
            ["ContentJP"] = "私たちは劇場にタダで潜り込もうなんて考えてないよ！私たちのチケットが誰かにすり替えられたんだ！スノウは、その泥棒を捕まえて文句を言いに行こうとしてたんだよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001118,
            ["FacialId"] = {
