        [12001120] = {
            ["Camera"] = "415.578125,-727.958984,124.617188,0.000169,6.399539,-87.782471,25.0,240.0,false,DoNotOverride,10.0",
            ["Content"] = "我想，这里可能有些误会。这两位小朋友应该是头等包厢的客人。",
            ["ContentJP"] = "そうね、どうやらちょっとした誤解があったみたい。このふたりは、たぶんロイヤルルームのお客さんなんじゃないかしら？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001120,
            ["FinalCamera"] = "414.039062,-688.067383,120.128906,0.000169,6.399539,-87.782471,25.0,240.0,false,DoNotOverride,10.0",
