        [12001307] = {
            ["Camera"] = "408.238281,-1356.822754,294.8125,0.000137,-17.000668,150.418488,35.000008,240.0,false,DoNotOverride,10.0",
            ["Content"] = "……遵命，女士。",
            ["ContentJP"] = "承知致しました、奥様。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001307,
            ["GUID"] = "1E0B446E",
