            },
        [12001308] = {
            ["Camera"] = "299.849609,-1221.519043,191.652344,0.000176,8.199498,-63.981323,35.0,240.0,false,Manual,10.0",
            ["Content"] = "顺便给你一个忠告。在我的家乡，有句箴言叫做祸从口出。",
            ["ContentJP"] = "ついでにひとつ忠告してあげるわ。わたしの国にはね、「口は災いの元」っていう言葉があるのよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001308,
            ["GUID"] = "1E0B4498",
            ["NextDialogue"] = 12001309,
            ["Scripts"] = "TurnTo{TurnToDescription{\"210004:p(160)\"}}",
            ["SpeakNpcId"] = 210004,
            ["TurnTo"] = {
                [1] = "210004:p(160)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120013/1E0B4498",
            },
        [12001309] = {
            ["Camera"] = "416.728516,-1396.350098,247.863281,28.798187,5.598638,-58.176476,35.000008,240.0,false,DoNotOverride,10.0",
            ["Content"] = "管好你的嘴，不然，保不准某天会有什么样的噩运降临到你头上。",
            ["ContentJP"] = "口の聞き方には気を付けなさい。さもないと、いつかとんでもない不幸が降りかかるかもしれないわよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001309,
            ["GUID"] = "1E0B44C2",
