            },
        [12001348] = {
            ["Camera"] = "-97.597656,490.723633,-6.394531,0.000057,9.200121,87.800667,30.0,300.0,false,Manual,10.0",
            ["Content"] = "对不住啊，止流老板。人多嘈杂的环境我不习惯。清净了，才好谈事。",
            ["ContentJP"] = "悪いな、シリュウさん。人混みの騒がしい場所は苦手でね。静かになったところで、ゆっくり話そうじゃないか。",
            ["DialogueId"] = 12001348,
            ["FacialId"] = {
