        [12001502] = {
            ["Camera"] = "127.935547,523.036133,-20.207031,0.000092,7.799284,-141.520447,15.726627,200.0,false,Manual,10.0",
            ["Content"] = "兄弟们只是出来讨点生计。您看……这月髓液就作为见面礼送给您了，以您的大度和慷慨，想必是不会和我们这些小人物计较吧！",
            ["ContentJP"] = "俺たちは、ただ生計を立てるために商売をしているだけなんです。どうでしょう……このイコル液、挨拶代わりに差し上げます。あなたほどのお方なら、俺たちみたいな小物のことは気にしないですよね？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001502,
