        [12001517] = {
            ["Camera"] = "-499.877808,-1184.16748,622.455811,0.000199,-23.19931,78.986671,23.147667,113.994598,false,DoNotOverride,10.0",
            ["Content"] = "哇……白完全搞错了！原来止流姐姐不是被心上人抛弃了，而是来和人接头交易。好险好险，还好刚刚没说出来。",
            ["ContentJP"] = "わあ……スノウ、完全に勘違いしてたよ！シリュウ、てっきり恋人に捨てられたのかと思ったら、ただ取引の相手と接触しに来ただけだったんだね。危ない危ない、さっき口に出さなくて本当に良かった！",
            ["DialogueId"] = 12001517,
            ["FacialId"] = {
                [1] = "200002:Smile02",
                },
            ["FinalCamera"] = "-569.940063,-1170.533203,622.455811,0.000199,-23.19931,78.986671,23.147667,113.994598,false,DoNotOverride,10.0",
