        [12001521] = {
            ["Camera"] = "-467.7724,102.231445,130.40918,0.000185,-2.401003,-1.618133,35.000008,200.303619,false,Manual,10.0",
            ["Content"] = "呵呵……那就后会有期了。",
            ["ContentJP"] = "ふふ、ではまたどこかでお会いしましょう。",
