            ["NextDialogue"] = 12001522,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B678A",
            },
        [12001522] = {
            ["Content"] = "……对了，我对这附近不太熟悉。你们知道，有一家叫做水仙平原的酒馆该怎么走吗？",
            ["ContentJP"] = "……そういえば、この辺りにはあまり詳しくないの。ねえ、あなたたち、アスフォデロスっていう名前の酒場がどこにあるか知ってるかしら？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001522,
            ["FacialId"] = {
