        [12001542] = {
            ["Camera"] = "-346.054382,570.72168,223.681641,0.000322,-18.375448,-156.66983,35.000008,449.203247,false,Manual,10.0",
            ["Content"] = "今天这是怎么了，气鼓鼓的一张脸。",
            ["ContentJP"] = "そんなにふてくされちゃって、どうしたの？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001542,
            ["FinalCamera"] = "-375.45282,558.045898,216.148438,0.000322,-18.375448,-156.66983,35.000008,449.203247,false,Manual,10.0",
            ["GUID"] = "1E0B6AFC",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "220019:n(100001)",
                },
            ["NextDialogue"] = 12001543,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6AFC",
            },
        [12001543] = {
            ["Camera"] = "-998.7005,558.96875,116.302734,0.00046,0.623241,-24.26104,35.000008,73.319519,false,DoNotOverride,10.0",
            ["Content"] = "哈哈，你来之前，咱们的小白和老约翰突然对当今陛下是谁争执了起来，被激得打起了赌，最后毫无意外地输了十个铜币。",
            ["ContentJP"] = "ははは、君が来る前にね、スノウとジョンがどちらがここの王かで言い争いを始めてさ。ついには賭けにまで発展したんだよ。案の定、スノウが負けて、銅貨を10枚取られたよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001543,
            ["FacialId"] = {
                [1] = "220019:CM_Ahaha01",
                },
            ["GUID"] = "1E0B6B26",
            ["NextDialogue"] = 12001544,
            ["SpeakNpcId"] = 220019,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6B26",
            },
        [12001544] = {
            ["Camera"] = "-488.200195,648.398438,247.289062,0.00045,-24.375666,-134.273666,32.414555,420.0,false,Manual,10.0",
            ["Content"] = "……呜，怎么能这样看不起本魔王！不信你看这张报纸——这里写得清清楚楚，是“克拉伏瓦皇帝陛下”！",
            ["ContentJP"] = "……う、この魔王を見くびるとはどういうこと！信じられないなら、この新聞を見てみなよ——ほら、ここにハッキリ書いてあるじゃない！「クラヴォワ皇帝陛下」ってさ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001544,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "1E0B6B50",
            ["NextDialogue"] = 12001545,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayAnimation{_delay{4},ActorId{200002},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6B50",
            },
        [12001545] = {
            ["Content"] = "（白不由分说，把手里的报纸塞到你的怀里。）",
            ["ContentJP"] = "スノウは手に持っていた新聞をあなたに押し付けた。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001545,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_NewsPaper.T_Guide_Chapter_NewsPaper'}",
            ["Duration"] = 4,
            ["GUID"] = "1E0B6B51",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12001546,
            ["Scripts"] = "PlayAnimation{_delay{0.5},ActorId{200002},AnimationId{\"Give\"},Duration{1}}",
            },
        [12001546] = {
            ["Content"] = "哈哈哈哈……小白，你仔细看看标题，那是人家的连载小说啊！",
            ["ContentJP"] = "ははは、スノウよ、よくタイトルを見てみな。それはただの連載小説だよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001546,
            ["GUID"] = "1E0B6B7A",
            ["NextDialogue"] = 12001547,
            ["SpeakNpcId"] = 220019,
            ["VoiceName"] = "voice/$Locale$/story/1200/120015/1E0B6B7A",
            },
        [12001547] = {
            ["Camera"] = "-648.699707,388.334961,113.205078,0.00046,8.223841,127.532356,35.000008,130.0,false,Manual,10.0",
            ["Content"] = "（你随手翻开了眼前的报纸。突然，角落里的一则寻物启事牢牢地吸引住了你的视线。）",
            ["ContentJP"] = "あなたは適当に新聞をめくった。その瞬間、隅に載っていた一つの捜し物広告が目に留まり、思わず目を見開いた。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001547,
            ["GUID"] = "1E0B6B7B",
            ["LookAt"] = {
                [1] = "100001:p(paper)",
                },
            ["NextDialogue"] = 12001548,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [12001548] = {
