                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8A7C",
            },
        [12001735] = {
            ["Content"] = "我在执行公务，别碍事！",
            ["ContentJP"] = "私は今、公務中なの。邪魔をしないでちょうだい。",
            ["DefaultLookAt"] = "TalkNpc",
