                [1] = "210004:Talk03ToTalkL_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8E42",
            },
        [12001758] = {
            ["Camera"] = "262.360352,20.961182,141.071045,0.000118,-4.199665,-113.39299,35.000011,152.94194,false,Manual,10.0",
            ["Content"] = "止流女士——不，止流掌柜，你怎么会在这里？",
            ["ContentJP"] = "シリュウ奥様——じゃなかった、シリュウ店主、どうしてここに？",
            ["DialogueId"] = 12001758,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                },
            ["GUID"] = "1E0B8E6C",
            ["LookAt"] = {
                [1] = "100001:n(210004)",
                [2] = "200002:n(210004)",
                },
            ["NextDialogue"] = 12001759,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                [2] = "200002:BaiTX_Story_Tired_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8E6C",
            },
        [12001759] = {
            ["Camera"] = "263.743164,-274.392456,127.796387,0.00015,-2.60013,101.20816,35.0,400.0,false,Manual,10.0",
            ["Content"] = "本来是特意找你道别的……现在看来，倒是没有这个必要了。",
            ["ContentJP"] = "本当は別れを言いに来たのだけど……まだその必要はなさそうね。",
            ["DialogueId"] = 12001759,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "200002:None",
                },
            ["GUID"] = "1E0B8E96",
            ["NextDialogue"] = 12001760,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8E96",
            },
        [12001760] = {
            ["Camera"] = "267.479004,9.616211,119.475098,0.000074,9.399432,110.6063,35.000011,124.361229,false,Manual,10.0",
            ["Content"] = "你是要和我继续在这里寒暄呢，还是要在他们抓到你之前，赶紧逃出这里呢？",
            ["ContentJP"] = "ところで、これ以上話を続けてる余裕はあるの？彼らに捕まる前に急いで逃げ出すべきでは？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001760,
            ["GUID"] = "1E0B8EC0",
            ["NextDialogue"] = 12001761,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8EC0",
            },
        [12001761] = {
            ["Camera"] = "217.206543,35.907349,156.063477,0.000065,-9.400607,-97.392738,35.000015,163.255356,false,Manual,15.0",
            ["Content"] = "……我明白了！",
            ["ContentJP"] = "……分かりました、ありがとうございます！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001761,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E0B8EEA",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8EEA",
            },
        [12001762] = {
            ["Camera"] = "55.601562,-74.976562,92.190918,0.000011,13.599883,168.789474,35.000019,257.48999,false,Manual,10.0",
            ["Content"] = "什么人？停车！",
            ["ContentJP"] = "何者だ、車を止めろ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001762,
            ["GUID"] = "1E0B8F14",
            ["NextDialogue"] = 12001763,
            ["SpeakNpcId"] = 220025,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8F14",
            },
        [12001763] = {
            ["Content"] = "上头下了命令，今晚一个可疑人士都不能放行，麻烦你们配合一下。",
            ["ContentJP"] = "上からの命令だ、今夜疑わしい者は誰も通せない、悪いがご協力願う。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001763,
            ["GUID"] = "1E0B8F3E",
            ["LookAt"] = {
                [1] = "220025:n(220014)",
                },
            ["NextDialogue"] = 120017641,
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220025:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8F3E",
            },
        [12001764] = {
            ["Camera"] = "-462.479492,486.855469,394.952148,0.000034,-20.000547,-54.008591,35.000008,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "哎呀……我过来的路上看见不少士兵在街上巡逻。请问出了什么事吗？",
            ["ContentJP"] = "あら……こちらに来る途中でたくさんの兵士が街を巡回しているのを見たわ。何かあったのかしら？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001764,
            ["FinalCamera"] = "-462.479492,486.855469,339.495117,0.000034,-20.000547,-54.008591,35.000008,100000.0,false,DoNotOverride,10.0",
            ["GUID"] = "1E0B8F68",
            ["LookAt"] = {
                [1] = "220014:n(220025)",
                [2] = "100001:n(220025)",
                [3] = "200002:n(220025)",
                },
            ["NextDialogue"] = 12001765,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{220014},MoveSpeed{80},TargetPoint{\"ZhiliuMove_309\"}},\
MoveTo{ActorId{200002},MoveSpeed{80},TargetPoint{\"BaiMove_309\"}},\
MoveTo{ActorId{100001},MoveSpeed{80},TargetPoint{\"ZhujueMove_309\"}},\
StopNormalSound{EventKey{\"carplay\"}}\
}",
            ["SpeakNpcId"] = 220014,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8F68",
            },
        [12001765] = {
            ["Camera"] = "194.37793,-166.161133,140.183105,0.000003,-1.799557,152.996048,37.747215,362.031006,false,Manual,10.0",
            ["Content"] = "瞎打听什么呢？！这是你该知道的吗——",
            ["ContentJP"] = "何を詮索している！これはお前が知るべきことでは——",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001765,
            ["GUID"] = "1E0B8F92",
            ["NextDialogue"] = 12001766,
            ["SpeakNpcId"] = 220025,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8F92",
            },
        [12001766] = {
            ["Camera"] = "-108.702148,25.432129,82.476562,0.000077,13.598018,-45.800716,51.545876,204.890732,false,Manual,3.882469",
            ["Content"] = "士兵的呵斥戛然而止。你用余光瞥到，止流将一个沉甸甸的小袋子递给了他。士兵掂了掂袋子的重量，不动声色地将其收入袖口中。",
            ["ContentJP"] = "兵士の叱責が突然止んだ。シリュウが重そうな小袋を彼に渡しているのが目に入った。兵士は袋の重さを量り、無表情でそれを袖口にしまい込んだ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001766,
            ["Duration"] = 5,
            ["GUID"] = "1E0B8FBC",
            ["NextDialogue"] = 12001767,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"100001:p(Nvzhu_Look_309)\"}}",
            ["TalkActionId"] = {
                [1] = "220014:Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8FBC",
            },
        [12001767] = {
            ["Camera"] = "355.125,200.536621,154.582031,0.000034,-5.1997,-148.204956,35.000011,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "倒也没什么不能讲的。今晚说是要抓捕一个重要逃犯，城里的所有守备力量都被调动了。",
            ["ContentJP"] = "まあいいでしょう。今夜、重要な逃亡犯を捕まえるために、街の全ての兵力が動員されたんです。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001767,
            ["GUID"] = "1E0B8FE6",
            ["LookAt"] = {
                [1] = "100001:n(220025)",
                },
            ["NextDialogue"] = 12001768,
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220014:Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B8FE6",
            },
        [12001768] = {
            ["Content"] = "但这逃犯在哪，长什么样，目前还没个影呢。",
            ["ContentJP"] = "でも、この逃亡犯がどこにいて、どんな姿をしているのか、まだ手がかりは掴んでおりません。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001768,
            ["GUID"] = "1E0B9010",
            ["NextDialogue"] = 12001769,
            ["SpeakNpcId"] = 220025,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9010",
            },
        [12001769] = {
            ["Camera"] = "-270.78418,255.63623,167.03418,0.000086,-8.000794,-55.608383,35.000011,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "嗯，这可有点苦恼了……我是华胥来的商人。我的私人飞艇现在就停在郊外。六小时后，我必须出席一场重要的商业洽谈。",
            ["ContentJP"] = "うーん、困ったわね……私は<Default note=\"text:カショ\">華胥</>から来た商人よ。プライベート飛行船を郊外に停めててね。六時間後には、重要な商談に出席しなければならないの。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001769,
            ["GUID"] = "1E0B903A",
            ["LookAt"] = {
                [1] = "100001:n(220025)",
                [2] = "200002:n(220025)",
                },
            ["NextDialogue"] = 12001770,
            ["SpeakNpcId"] = 220014,
            ["TalkActionId"] = {
                [1] = "220014:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B903A",
            },
        [12001770] = {
            ["Content"] = "我和车上的伙计都是身份清白的人士，办好了正规的出境手续文件。您看，能否通融一下呢？",
            ["ContentJP"] = "私と車に乗っている方は全員、身分が潔白なので、正式な出国手続きも済ませているの。どうか、少しだけご融通いただけないかしら？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001770,
            ["GUID"] = "1E0B9064",
            ["NextDialogue"] = 12001771,
            ["SpeakNpcId"] = 220014,
            ["TalkActionId"] = {
                [1] = "220014:Talk03ToTalkL_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9064",
            },
        [12001771] = {
            ["Camera"] = "-90.224609,27.822266,129.658691,0.000123,-0.199885,-48.183372,51.572987,182.084885,false,Manual,10.0",
            ["Content"] = "在止流出示的文件上，你赫然看见自己的照片被方方正正地贴在其中。照片上略显严肃的表情让你感到陌生。",
            ["ContentJP"] = "シリュウが提示した書類の中に、あなたは自分の写真がきちんと貼り付けられているのをはっきりと見た。ただその写真の表情はやや厳しく、見慣れないものだった。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001771,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
            ["Duration"] = 5,
            ["FinalCamera"] = "-83.21582,19.981934,129.623047,0.000123,-0.199885,-48.18306,51.572987,171.736893,false,Manual,10.0",
            ["GUID"] = "1E0B908E",
            ["NextDialogue"] = 12001772,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B908E",
            },
        [12001772] = {
            ["Content"] = "（止流她……什么时候准备好的文件？）",
            ["ContentJP"] = "シリュウ……いつの間に書類を準備したんだろう？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001772,
            ["DisableMouth"] = 1,
            ["Duration"] = 5,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E0B90B8",
            ["LookAt"] = {
                [1] = "220014:n(220025)",
                },
            ["NextDialogue"] = 12001773,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "220014:Talk03ToTalkL_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B90B8",
            },
        [12001773] = {
            ["Camera"] = "100.349609,-20.827148,139.20459,0.000054,-0.000246,-172.803757,35.000011,264.540283,false,Manual,6.124233",
            ["Content"] = "女士……不是我故意为难你，但我们长官严禁任何人从这里通行。",
            ["ContentJP"] = "奥様……決してご迷惑をおかけするつもりはありませんが、長官から通行を厳しく禁じられております。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001773,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "1E0B90E2",
            ["LookAt"] = {
                [1] = "220025:n(220014)",
                },
            ["NextDialogue"] = 12001774,
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220025:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B90E2",
            },
        [12001774] = {
            ["Camera"] = "-410.826172,260.788574,156.883301,0.000045,-3.800918,-40.007858,60.419567,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "这样吧。把你们的军队番号和长官姓名告诉我，我去想想办法。",
            ["ContentJP"] = "ではこうしましょう。あなたたちの軍隊番号と長官の名前を教え、私が何とかするわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001774,
            ["GUID"] = "1E0B910C",
            ["NextDialogue"] = 12001775,
            ["SpeakNpcId"] = 220014,
            ["TalkActionId"] = {
                [1] = "220014:Talk03ToThink_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B910C",
            },
        [12001775] = {
            ["Camera"] = "-60.169922,20.828613,119.424805,0.000075,12.599663,-45.606236,46.428596,118.094795,false,Manual,10.0",
            ["Content"] = "……呵呵，若是卢西亚娜·洛雷托知道我被一个小小士兵拖在这里，从而误了一场重要洽谈，这等趣事，倒是能成为茶余的谈资呢。",
            ["ContentJP"] = "ふふ、もしルシアナ・ロレートが私が小さな兵士に引き留められて、大事な商談を逃したことを知ったら、アフタヌーンティーの話題になるでしょうね。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001775,
            ["GUID"] = "1E0B9136",
            ["NextDialogue"] = 12001776,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9136",
            },
        [12001776] = {
            ["Camera"] = "24.524414,3.004395,148.750488,0.000044,-2.599973,-158.404205,35.000008,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "卢西亚娜·洛雷托……我好像听过……这是帝国财务大臣的名字！",
            ["ContentJP"] = "ルシアナ・ロレート……聞いたことがあるような……確か帝国財務大臣のお名前！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001776,
            ["GUID"] = "1E0B9160",
            ["LookAt"] = {
                [1] = "220026:n(220025)",
                [2] = "220025:n(220026)",
                },
            ["NextDialogue"] = 12001777,
            ["SpeakNpcId"] = 220026,
            ["TalkActionId"] = {
                [1] = "220025:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9160",
            },
        [12001777] = {
            ["Content"] = "喂，再一看，文件上好像就是她的亲笔签名！",
            ["ContentJP"] = "待て、もう一度見てみろ。書類に彼女の直筆署名が載っているぞ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001777,
            ["GUID"] = "1E0B918A",
            ["NextDialogue"] = 12001778,
            ["SpeakNpcId"] = 220026,
            ["TalkActionId"] = {
                [1] = "220014:Talk03ToThink_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B918A",
            },
        [12001778] = {
            ["Content"] = "这……",
            ["ContentJP"] = "困りましたな……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001778,
            ["GUID"] = "1E0B91B4",
            ["LookAt"] = {
                [1] = "220025:n(220014)",
                },
            ["NextDialogue"] = 12001779,
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220025:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B91B4",
            },
        [12001779] = {
            ["Camera"] = "-491.920898,478.322754,448.695801,0.000088,-10.999807,-47.399258,9.196175,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "全体注意！目标疑似出现于剧院附近，持有器械，正在试图逃离。附近小队，速至现场增援。重复一遍——附近小队，速至现场增援。",
            ["ContentJP"] = "全体注意！目標が劇場付近に出現した疑いがあり、武器を所持して逃走を試みている。近隣小隊、速やかに現場へ増援に向かえ。繰り返す——近隣小隊、速やかに現場へ増援に向かえ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001779,
            ["FinalCamera"] = "-491.920898,478.322754,448.695801,0.000088,-1.599603,-42.39946,9.196175,100000.0,false,DoNotOverride,10.0",
            ["GUID"] = "1E0B91DE",
            ["NextDialogue"] = 12001780,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/intro_crowdcombat\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "220025:Shock_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B91DE",
            },
        [12001780] = {
            ["Camera"] = "-245.133789,192.716309,132.871094,0.00009,-3.199267,-51.80265,30.0,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "嗯……看来嫌犯出现了。怎么说，您还要继续扣押我们吗？",
            ["ContentJP"] = "うーん……どうやら容疑者が現れたみたいね。さて、まだ私たちを引き止めるつもりかしら？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001780,
            ["FacialId"] = {
                [1] = "220014:Smile01",
                },
            ["GUID"] = "1E0B9208",
            ["LookAt"] = {
                [1] = "220014:n(220025)",
                [2] = "100001:n(220025)",
                [3] = "200002:n(220025)",
                },
            ["NextDialogue"] = 12001781,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9208",
            },
        [12001781] = {
            ["Camera"] = "259.166016,139.326172,124.026855,0.0001,-2.599324,-148.204941,30.000002,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "……这样吧，女士。我们就不耽误您的行程了，但是我们必须派人确保您顺利离境。",
            ["ContentJP"] = "……ではこうしましょう、奥様。今回は通行を許可しますが、確かに出国したことを確認できるように担当者を派遣いたします。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001781,
            ["GUID"] = "1E0B9232",
            ["NextDialogue"] = 12001782,
            ["SpeakNpcId"] = 220025,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9232",
            },
        [12001782] = {
            ["Content"] = "直到飞艇起飞前，您或您的手下都必须好端端地待在我们的视野里。如果有任何异动，会被视为对帝国的挑衅。您看，这个方案可以吗？",
            ["ContentJP"] = "飛行船が離陸するまで、あなたやあなたの部下の皆様には、私たちの視界内にお留まりいただく必要がございます。万が一、怪しい動きがございましたら、それは帝国への挑発と見なされます。このご提案はいかがでしょうか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001782,
            ["GUID"] = "1E0B925C",
            ["NextDialogue"] = 12001783,
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220014:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B925C",
            },
        [12001783] = {
            ["Camera"] = "-247.888672,60.718262,171.297363,0.000116,-9.999724,-29.603325,35.000011,298.698639,false,Manual,10.0",
            ["Content"] = "呵呵……没问题。与人方便，也是与己方便。务必配合长官们的工作。",
            ["ContentJP"] = "ふふ……問題ないわ。お互い納得がいくことに越したことはないからね。その提案を受け入れるわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001783,
            ["GUID"] = "1E0B9286",
            ["LookAt"] = {
                [1] = "100001:n(220025)",
                },
            ["NextDialogue"] = 12001784,
            ["SpeakNpcId"] = 220014,
            ["TalkActionId"] = {
                [1] = "220014:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B9286",
            },
        [12001784] = {
            ["Camera"] = "-459.007812,408.505859,307.084473,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
            ["Content"] = "感谢您的理解——放行吧！",
            ["ContentJP"] = "ご協力ありがとうございます——通せ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001784,
            ["FinalCamera"] = "-534.192383,507.5625,345.104492,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
            ["GUID"] = "1E0B92B0",
            ["SpeakNpcId"] = 220025,
            ["TalkActionId"] = {
                [1] = "220014:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1200/120017/1E0B92B0",
            },
        [12001785] = {
            ["Content"] = "皎皎气呼呼地跑走了。",
            ["ContentJP"] = "スノウはプンプンしながら走り去った。",
            ["DialogueId"] = 12001785,
            ["GUID"] = "1E0B8AD1",
            },
        [12001801] = {
            ["Camera"] = "26.581055,-95.871094,153.29248,0.000088,-8.170654,-51.38456,12.0,60.0,false,Manual,10.0",
            ["Content"] = "好啦，现在可以随意讨论了。不过，注意控制表情，那些士兵还在后头尽职尽责地跟着呢。",
            ["ContentJP"] = "さて、もう自由に話しても大丈夫よ。でも、表情には気をつけて。あの兵士たちが後ろについているから。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001801,
            ["FinalCamera"] = "1.03418,-98.566895,152.582031,0.000092,-8.970668,-40.585316,12.0,100.0,false,Manual,10.0",
            ["GUID"] = "1E0B957A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001830,
            ["Scripts"] = "PARA{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/1_0/0085_scene_icelake\"}},\
PlayNormalSound{EventKey{\"car2drive\"},EventPath{\"event:/sfx/common/story/yinru/car_drive\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 220014,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B957A",
            ["bNotRecall"] = 1,
            },
        [12001802] = {
            ["Content"] = "呵呵，那是我雇佣的狩月人。",
            ["ContentJP"] = "ふふ、あれは私が雇った月狩り人よ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001802,
            ["GUID"] = "1E0B95A4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001803,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B95A4",
            },
        [12001803] = {
            ["Content"] = "只要一份不算丰厚的报酬，就有人愿意为此铤而走险。而这些钱，甚至买不起财务大臣郊外庄园的一只猎犬。",
            ["ContentJP"] = "報酬がそれほど多くなくても、それを目当てにリスクを冒す人はいるわよね。でも、このお金じゃ、財務大臣の郊外の邸宅にいる猟犬すら買えないわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001803,
            ["GUID"] = "1E0B95CE",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001804,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B95CE",
            },
        [12001804] = {
            ["Content"] = "但也多亏于此，我们才能化解今晚的危机。",
            ["ContentJP"] = "でもおかげで、今夜の危機を解決できたわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001804,
            ["GUID"] = "1E0B95F8",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001830,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B95F8",
            },
        [12001805] = {
            ["Content"] = "想听一件有趣的事情吗？",
            ["ContentJP"] = "面白いことを聞きたい？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001805,
            ["GUID"] = "1E0B9622",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001806,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9622",
            },
        [12001806] = {
            ["Content"] = "《海伯利亚早报》是一份在帝国全境发售的报纸。而海伯利亚所有主要城市的中心广场上……又恰好都有一座红色电话亭。",
            ["ContentJP"] = "『ヒュペリア新聞』は帝国全土で発行されている新聞よ。そして、ヒュペリアのすべての主要都市の中心広場には……ちょうど赤い電話ボックスが一つずつ設置されている。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001806,
            ["GUID"] = "1E0B964C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001807,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B964C",
            },
        [12001807] = {
            ["Content"] = "早上卡米拉和我转述了报纸的前因后果。了解这件事后，我留了一份心，多打了几个电报。  ",
            ["ContentJP"] = "今朝、カミラからこの新聞について説明してもらったの。これを知ってから、念のため、いくつか電報を余分に送ったわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001807,
            ["GUID"] = "1E0B9676",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001808,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9676",
            },
        [12001808] = {
            ["Content"] = "可以告诉你一个好消息：今夜，所有城市的电话亭中都站着一位白发女子，等待着不会到来的“故人”。",
            ["ContentJP"] = "いいニュースを教えてあげる。今夜、すべての都市の電話ボックスには白髪の女性が立っていて、訪れることのない『故人』を待っているのよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001808,
            ["GUID"] = "1E0B96A0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001809,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B96A0",
            },
        [12001809] = {
            ["Content"] = "这为什么是好消息哇？白有点听不懂……",
            ["ContentJP"] = "なぜこれがいいニュースなの？スノウ、わかんない……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001809,
            ["GUID"] = "1E0B96CA",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001810,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B96CA",
            },
        [12001810] = {
            ["Content"] = "我想，止流掌柜的意思是，他们不确定我具体的位置，甚至不确信我是否还活着，所以大规模洒下诱饵，试图用这种方式诱我出来……",
            ["ContentJP"] = "シリュウ店主が言いたいのは、彼らには{性别:僕|私}の居場所も生死もわかっていないから、大規模に餌を撒き、この方法で{性别:僕|私}を誘い出そうとしているのだと思う……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001810,
            ["GUID"] = "1E0B96F4",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001811,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B96F4",
            },
        [12001811] = {
            ["Content"] = "答对了，真聪明。",
            ["ContentJP"] = "大当たり、賢いわね。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001811,
            ["GUID"] = "1E0B971E",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001812,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B971E",
            },
        [12001812] = {
            ["Content"] = "（知道我的存在，还处心积虑布下这场局的军团人士，究竟是谁……？）",
            ["ContentJP"] = "自分の存在を知っていて、この局を仕掛けている帝国軍の人物は、一体誰なんだろう……？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001812,
            ["GUID"] = "1E0B9748",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001830,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9748",
            },
        [12001813] = {
            ["Content"] = "按目前的形势，直到飞艇起飞之前，恐怕你都无法下车。抱歉，看来要连累你和我走一趟华胥了。",
            ["ContentJP"] = "今の状況だと、飛行船が離陸するまであなたは車を降りられないみたいね。ごめんなさい、どうやらあなたも一緒に<Default note=\"text:カショ\">華胥</>へ連れて行くことになりそうね。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001813,
            ["GUID"] = "1E0B9772",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001814,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 408010,
                },
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9772",
            },
        [12001814] = {
            ["Content"] = "止流掌柜，您几次为我解围，我简直不知要如何报答您。",
            ["ContentJP"] = "シリュウ店主、何回も助けていただいて本当に感謝しきれません。どうすればこのご恩を返せますでしょうか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001814,
            ["GUID"] = "1E0B979C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001815,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B979C",
            },
        [12001815] = {
            ["Content"] = "嗯……报答吗？",
            ["ContentJP"] = "ふむ……恩を返すか。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001815,
            ["GUID"] = "1E0B97C6",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001816,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B97C6",
            },
        [12001816] = {
            ["Content"] = "我恰好有样活计正缺人手。从华胥返回海伯利亚的飞艇会在七日后启程，这期间，你若是不介意，倒是可以助我一臂之力。",
            ["ContentJP"] = "実はちょうど手伝ってくれる人が必要だったの。<Default note=\"text:カショ\">華胥</>からヒュペリアへ戻る飛行船は七日後に出発するから、その間、もしよかったら力を貸してくれると助かるわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001816,
            ["GUID"] = "1E0B97F0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001817,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B97F0",
            },
        [12001817] = {
            ["Content"] = "怎么样？考虑一下吧，聪明的小朋友。报酬自然是不会少了你们的。",
            ["ContentJP"] = "どうかしら？ちょっと考えてみて、賢い子供たち。報酬ももちろんはずむわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001817,
            ["GUID"] = "1E0B981A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001818,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B981A",
            },
        [12001818] = {
            ["Content"] = "（果然……这一切并非巧合。）",
            ["ContentJP"] = "（やっぱり……偶然じゃなかったか。）",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001818,
            ["GUID"] = "1E0B9844",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextOptions"] = {
                [1] = 12001819,
                [2] = 12001820,
                },
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9844",
            },
        [12001819] = {
            ["Content"] = "上了这辆车，恐怕我也没有拒绝的机会了吧。",
            ["ContentJP"] = "この車に乗った時から、拒否権はもうないんじゃないかな。",
            ["DialogueId"] = 12001819,
            ["GUID"] = "1E0B986E",
            ["ImprPlusId"] = 1006,
            ["NextDialogue"] = 12001821,
            },
        [12001820] = {
            ["Content"] = "您帮了我好几次，我很乐意报答您。",
            ["ContentJP"] = "何度も助けてくれた身です、喜んでお手伝いします。",
            ["DialogueId"] = 12001820,
            ["GUID"] = "1E0B9898",
            ["ImprPlusId"] = 1007,
            ["NextDialogue"] = 12001821,
            },
        [12001821] = {
            ["Content"] = "能去到很远很远的国家，品尝没见过的好吃食物，还能赚到一大笔报酬……小仆从，听起来是一次很不错的大冒险耶！",
            ["ContentJP"] = "とっても遠い国に行って、見たこともない美味しい食べ物を味わって、しかも大金を稼げるだなんて……我が下僕よ、これはかなり素敵な大冒険になりそうだな！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001821,
            ["GUID"] = "1E0B98C2",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001822,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B98C2",
            },
        [12001822] = {
            ["Content"] = "对了，在出发之前……我可否再拜托您一件事？",
            ["ContentJP"] = "すみません、出発する前に……もう一つお願いしてもいいですか。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001822,
            ["GUID"] = "1E0B98EC",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001823,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B98EC",
            },
        [12001823] = {
            ["Content"] = "无须担心。在别的城市中，我也雇佣了些临时工。有了这些四处咬钩的鱼儿，海伯利亚士兵今晚的行动，大约是要无功而返了——他们不会知道你在冰湖城。",
            ["ContentJP"] = "心配いらないわ。他の街でも何人か雇ったからね。こうしてあちこちで釣られる魚たちがいるおかげで、ヒュペリアの兵士たちの今夜の行動は、多分無駄足に終わるでしょうね――彼らは、あなたがアイスレイク城にいることを知ることはないわ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001823,
            ["GUID"] = "1E0B9916",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001824,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9916",
            },
        [12001824] = {
            ["Content"] = "（连这个都预判到了吗……这位来自<H>华胥</>的女士，究竟想要委托我做什么……）",
            ["ContentJP"] = "（ここまで読むなんて……この<Default note=\"text:カショ\">華胥</>から来た女性、一体何を依頼するつもりなんだろう……）",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001824,
            ["GUID"] = "1E0B9940",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001825,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9940",
            },
        [12001825] = {
            ["Content"] = "（不过事已至此，也没有其他选择了。只是七天的话，时间还算充裕……）",
            ["ContentJP"] = "とはいえ、ここまで来てしまった以上、他に選択肢はない。7日間だけなら、時間的にはまだ余裕がある……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001825,
            ["GUID"] = "1E0B996A",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextDialogue"] = 12001826,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B996A",
            },
        [12001826] = {
            ["Content"] = "好！这个委托，我们就接下了！",
            ["ContentJP"] = "わかった！この依頼、引き受けるよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12001826,
            ["GUID"] = "1E0B9994",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["Scripts"] = "StopNormalSound{EventKey{\"car2drive\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1200/120018/1E0B9994",
            },
        [12001830] = {
            ["DialogueId"] = 12001830,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.1,
            ["FinalDialogueId"] = 12001813,
            ["GUID"] = "1E0B957B",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
            ["NextOptions"] = {
                [1] = 120018011,
                [2] = 120018041,
                },
            },
        [12001901] = {
            ["Content"] = "假装这里非常热闹、节日氛围",
            ["DialogueId"] = 12001901,
            ["GUID"] = "1E0BA5E2",
            },
        [12002001] = {
            ["Camera"] = "286.526367,-483.072693,114.938232,0.000091,-2.399923,133.799744,35.0,500.0,false,Manual,10.0",
