            },
        [12002003] = {
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12002003,
            ["FinalCamera"] = "-114.279785,-254.552246,92.543457,0.000091,2.400053,125.79911,35.0,100000.0,False,Manual,10.0",
            ["GUID"] = "1E0BB69E",
            },
        [12002100] = {
            ["Content"] = "假装潜行玩法",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12002100,
            ["GUID"] = "1E0BC688",
            },
        [12003001] = {
            ["Content"] = "假装这里坐下来了，后面k一个Sequence",
            ["DialogueId"] = 12003001,
            ["GUID"] = "1E0C5A5A",
            },
        [12003101] = {
            ["Content"] = "假装把止流带走",
            ["DialogueId"] = 12003101,
            ["GUID"] = "1E0C6AC2",
            },
        [12003201] = {
            ["Content"] = "假装2D图",
            ["DialogueId"] = 12003201,
            ["GUID"] = "1E0C7B2A",
            },
        [12003301] = {
            ["Content"] = "这里就把玩家传到东国了",
            ["DialogueId"] = 12003301,
            ["GUID"] = "1E0C8B92",
            },
        [12003401] = {
            ["Content"] = "假装开车出城的Sequence",
            ["DialogueId"] = 12003401,
            ["GUID"] = "1E0C9BFA",
            },
        [12004001] = {
            ["Camera"] = "127.357666,-54.3125,106.762451,0.000013,7.799898,-163.400085,35.0,100000.0,False,Manual,10.0",
            ["Content"] = "选A还是B",
            ["DialogueId"] = 12004001,
            ["GUID"] = "1E0CFE6A",
            ["SpeakNpcId"] = 100001,
            },
        [12004002] = {
            ["Content"] = "A",
            ["DialogueId"] = 12004002,
            ["GUID"] = "1E0CFE94",
            ["SpeakNpcId"] = 100001,
            },
        [12004003] = {
            ["Content"] = "B",
            ["DialogueId"] = 12004003,
            ["GUID"] = "1E0CFEBE",
            ["SpeakNpcId"] = 200002,
            },
        [12004101] = {
            ["Content"] = "……哇，好多人哦。大家都是来看剧的吗？",
            ["ContentJP"] = "……わぁ、すごい人だ！みんなオペラを観に来たのかな？",
            ["DialogueId"] = 12004101,
            ["GUID"] = "1E0AE102",
            ["NextDialogue"] = 12004102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120007/1E0AE102",
            },
        [12004102] = {
            ["Content"] = "他们好像在聊一些很有意思的事情，小仆从，我们去听听看吧。",
            ["ContentJP"] = "なんか面白いこと話してるみたい。我が下僕よ、早く行こう！",
            ["DialogueId"] = 12004102,
            ["GUID"] = "1E0D0EFC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120041/1E0D0EFC",
            },
        [12004201] = {
            ["Content"] = "止流姐姐，你去水仙平原，莫非是要见什么人？",
            ["ContentJP"] = "シリュウ、アスフォデロスに行くって言ってたけど、知り合いにでも会いに行くのか？",
            ["DialogueId"] = 12004201,
            ["GUID"] = "1E0D1F3A",
            ["NextDialogue"] = 12004202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F3A",
            },
        [12004202] = {
            ["Content"] = "让白猜猜……该不会是一位金色大波浪、说起话来凶巴巴的老板娘吧！",
            ["ContentJP"] = "まーさーか……金髪のくるくるパーマをした、おっかない女店長とかじゃないよね！？",
            ["DialogueId"] = 12004202,
            ["GUID"] = "1E0D1F64",
            ["NextDialogue"] = 12004203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F64",
            },
        [12004203] = {
            ["Content"] = "呵呵，这都被你猜中了。",
            ["ContentJP"] = "ふふ、よく分かったわね。",
            ["DialogueId"] = 12004203,
            ["GUID"] = "1E0D1F8E",
            ["NextDialogue"] = 12004204,
            ["SpeakNpcId"] = 220014,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1F8E",
            },
        [12004204] = {
            ["Content"] = "魔王大人当然是料事如神啦！",
            ["ContentJP"] = "へへん！この魔王様に分からないことなんてないよ！",
            ["DialogueId"] = 12004204,
            ["GUID"] = "1E0D1FB8",
            ["NextDialogue"] = 12004205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1FB8",
            },
        [12004205] = {
            ["Content"] = "啊，不过，刚刚的话，可千万别对卡米拉说哦……不然今天的零花钱又要被扣光了。",
            ["ContentJP"] = "あ、さっきのはカミラに言っちゃダメだぞ……今日のお小遣いがなくなっちゃうから。",
            ["DialogueId"] = 12004205,
            ["GUID"] = "1E0D1FE2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D1FE2",
            },
        [12004206] = {
            ["Content"] = "我们到啦——",
            ["ContentJP"] = "着いたぞ——",
            ["DialogueId"] = 12004206,
            ["GUID"] = "1E0D200C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120042/1E0D200C",
            },
        [12004301] = {
            ["Content"] = "皎皎气呼呼地跑走了。",
            ["ContentJP"] = "スノウはプンプンしながら走り去った。",
            ["DialogueId"] = 12004301,
            ["Duration"] = 2,
            ["GUID"] = "1E0D2FA2",
            ["VoiceName"] = "voice/$Locale$/story/1200/120043/1E0D2FA2",
            },
        [12004401] = {
            ["Content"] = "那边的机器奇奇怪怪的……唔，总觉得绕开它们比较好！",
            ["ContentJP"] = "あの機械、なんか変……避けた方がいい気がする！",
            ["DialogueId"] = 12004401,
            ["GUID"] = "1E0D400A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120044/1E0D400A",
            },
        [12004402] = {
            ["Content"] = "它转过去啦，就是现在——",
            ["ContentJP"] = "あっち行ったぞ！今のうちに——",
            ["DialogueId"] = 12004402,
            ["GUID"] = "1E0D4034",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120044/1E0D4034",
            },
        [12004501] = {
            ["Content"] = "<W>发现追捕目标，发现追捕目标。</>",
            ["ContentJP"] = "<W>ターゲット発見！ターゲット発見！</>",
            ["DialogueId"] = 12004501,
            ["GUID"] = "1E0D5072",
            ["NextDialogue"] = 12004502,
            ["SnapShot"] = "BROADCAST",
            ["VoiceName"] = "voice/$Locale$/story/1200/120045/1E0D5072",
            },
        [12004502] = {
            ["Content"] = "哇啊……我们的行踪好像暴露了！",
            ["ContentJP"] = "あわわ……見つかっちゃったぞ！",
            ["DialogueId"] = 12004502,
            ["GUID"] = "1E0D509C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1200/120045/1E0D509C",
            },
        [12004503] = {
            ["Content"] = "任务失败，请重新开始。",
            ["ContentJP"] = "クエスト失敗、再チャレンジしてください。",
            ["DialogueId"] = 12004503,
            ["GUID"] = "1E0D509D",
            ["SpeakNpcId"] = 200002,
            },
        [12004504] = {
            ["Content"] = "被动失败",
            ["DialogueId"] = 12004504,
            ["GUID"] = "1E0D509E",
            ["SpeakNpcId"] = 200002,
            },
        [12010000] = {
            ["Content"] = "收帆——归港咯——",
            ["ContentJP"] = "帆をたためー！港へ戻るぞー！",
            ["DialogueId"] = 12010000,
            ["Duration"] = 5,
            ["GUID"] = "1E10D6A0",
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6A0",
            },
        [12010001] = {
            ["Content"] = "一路上，从敞篷车换飞艇再坐船，白的屁股都坐痛了……",
            ["ContentJP"] = "車に飛行艇、そんでもって船……座ってばかりいたせいで、お尻イタイタだよ……",
            ["DialogueId"] = 12010001,
            ["GUID"] = "1E10D6CA",
            ["NextDialogue"] = 12010002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6CA",
            },
        [12010002] = {
            ["Content"] = "呵呵……毕竟从华胥到海伯利亚，隔了千百里之遥。能将广阔的距离缩减为一日之内的行程，已经是月石技术的伟力了。",
            ["ContentJP"] = "ふふ……<Default note=\"text:カショ\">華胥</>はヒュペリアから千里もの距離があるのよ。一日で戻ってこれるなんて驚異の速度よ。これもみんな。月ノ石のおかげだけどね。",
            ["DialogueId"] = 12010002,
            ["GUID"] = "1E10D6F4",
            ["NextDialogue"] = 12010003,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D6F4",
            },
        [12010003] = {
            ["Content"] = "说的也是。白还从没来过这么远的地方呢！",
            ["ContentJP"] = "たしかに……スノウ、こんな遠出するの初めてだぞ！",
            ["DialogueId"] = 12010003,
            ["GUID"] = "1E10D71E",
            ["NextDialogue"] = 12010004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D71E",
            },
        [12010004] = {
            ["Content"] = "能看到这么绿的山峰，这趟算是来对了！要是还待在冰湖城，就只能和雪地里的冰原狼大眼瞪小眼。",
            ["ContentJP"] = "こんな緑色の山に、赤や黄色の葉っぱまで見られるなんて、来てよかったな～！アイスレイク城なんて、白いオオカミとにらめっこするほか、やれることないし～",
            ["DialogueId"] = 12010004,
            ["GUID"] = "1E10D748",
            ["NextDialogue"] = 12010005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D748",
            },
        [12010005] = {
            ["Content"] = "小仆从，这就是你们经常说的南方吧。这里和你的家乡像吗？",
            ["ContentJP"] = "我が下僕、もしかしてここが俗に言う「南のほう」ってやつか？君の故郷もこんな感じか？",
            ["DialogueId"] = 12010005,
            ["GUID"] = "1E10D772",
            ["NextDialogue"] = 12010006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D772",
            },
        [12010006] = {
            ["Content"] = "有点相似，但又有很多不一样的地方。",
            ["ContentJP"] = "少し似てる気もするけど……よく見るとぜんぜん違うかも。",
            ["DialogueId"] = 12010006,
            ["GUID"] = "1E10D79C",
            ["NextDialogue"] = 12010007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D79C",
            },
        [12010007] = {
            ["Content"] = "净界岛是个袖珍的小岛，就算是最高点，对于小孩子来说铆足了劲就能一口气冲上去，然后就能看见碧蓝的大海……",
            ["ContentJP"] = "パーガトリー島はほんの小さな島でね。いちばん高い場所も、子どもが本気で駆け上がれば一気に登れちゃうくらい。登りきった先には、真っ青な海が広がっていて……",
            ["DialogueId"] = 12010007,
            ["GUID"] = "1E10D7C6",
            ["NextDialogue"] = 12010008,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D7C6",
            },
        [12010008] = {
            ["Content"] = "止流掌柜，华胥是个怎样的国家呢？",
            ["ContentJP"] = "シリュウさん、<Default note=\"text:カショ\">華胥</>はどんな国なんですか？",
            ["DialogueId"] = 12010008,
            ["GUID"] = "1E10D7F0",
            ["NextDialogue"] = 12010009,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D7F0",
            },
        [12010009] = {
            ["Content"] = "让我想想……你们所见的，只是华胥的一小部分区域。",
            ["ContentJP"] = "そうね……あなたたちが見ているのは、<Default note=\"text:カショ\">華胥</>のほんの一部に過ぎないわ。",
            ["DialogueId"] = 12010009,
            ["GUID"] = "1E10D81A",
            ["NextDialogue"] = 12010010,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D81A",
            },
        [12010010] = {
            ["Content"] = "昔日，华胥先人依靠团结一致的伟力，解决了肆虐于这片土地的秽兽危机。然后扎根下来，逐渐地繁衍生息、开疆拓土。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>の祖先は、かつて力を合わせてこの地を荒らしていた穢獣を討ち払ったの。そしてこの土地に根を下ろし、少しずつ人々が暮らしを築き、国を広げていったのよ。",
            ["DialogueId"] = 12010010,
            ["GUID"] = "1E10D844",
            ["NextDialogue"] = 12010011,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D844",
            },
        [12010011] = {
            ["Content"] = "如今，这处入海口已经成为了旧都。在华胥广袤的版图中，它只占了一小块，却拥有不容忽视的影响力。",
            ["ContentJP"] = "この河口は「旧都」と呼ばれているわ。広大な<Default note=\"text:カショ\">華胥</>の一角にすぎないけれど、その影響力は決して小さくないの。",
            ["DialogueId"] = 12010011,
            ["GUID"] = "1E10D86E",
            ["NextDialogue"] = 12010012,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D86E",
            },
        [12010012] = {
            ["Content"] = "就整个华胥而言，这里地产富足，风景秀美，四季常青，由织星客领衔的贸易发达……",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>全体で見ても、この地は特に豊かな土地よ。景色は美しく、四季を通じて緑が絶えない。それに、星織人が率いる貿易も盛んで……",
            ["DialogueId"] = 12010012,
            ["GUID"] = "1E10D898",
            ["NextDialogue"] = 12010013,
            ["RelatedWikiId"] = {
                [1] = 405007,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D898",
            },
        [12010013] = {
            ["Content"] = "呵呵，怎么一脸凝重，莫非是我的介绍太官方了？",
            ["ContentJP"] = "ふふ、そんなに真剣な顔して……もしかして、ちょっとお堅い紹介になっちゃってたかしら？",
            ["DialogueId"] = 12010013,
            ["GUID"] = "1E10D8C2",
            ["NextOptions"] = {
                [1] = 120100131,
                [2] = 120100132,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D8C2",
            },
        [12010014] = {
            ["Content"] = "这样吧，说点你们可能感兴趣的。华胥是<H>不动干戈，世无纷争</>的和睦之乡。",
            ["ContentJP"] = "じゃあ少し、興味が湧きそうな話をしてあげる。<Default note=\"text:カショ\">華胥</>はね、<H>武器要らずの</>、平和な国なの。",
            ["DialogueId"] = 12010014,
            ["GUID"] = "1E10D8EC",
            ["NextDialogue"] = 12010015,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D8EC",
            },
        [12010015] = {
            ["Content"] = "什么干什么戈……白好像没太听懂！",
            ["ContentJP"] = "へ？……ぶきいらず？……スノウ、ちんぷんかんぷんだぞ～！",
            ["DialogueId"] = 12010015,
            ["GUID"] = "1E10D916",
            ["NextDialogue"] = 12010016,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D916",
            },
        [12010016] = {
            ["Content"] = "唔，意思是，这里没有战争，人们也不会像冰湖城那样动不动打架？",
            ["ContentJP"] = "んー、つまりここでは戦争がなくて、アイスレイク城みたいにすぐケンカになったりしないってこと、かな？",
            ["DialogueId"] = 12010016,
            ["GUID"] = "1E10D940",
            ["NextDialogue"] = 12010017,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D940",
            },
        [12010017] = {
            ["Content"] = "嗯。就连鸡鸣狗盗之恶，华胥也早已杜绝。",
            ["ContentJP"] = "ええ、それどころか、ちょっとした盗みや悪さすら、<Default note=\"text:カショ\">華胥</>ではもう随分発生していないわ。",
            ["DialogueId"] = 12010017,
            ["GUID"] = "1E10D96A",
            ["NextDialogue"] = 12010018,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D96A",
            },
        [12010018] = {
            ["Content"] = "你该不会是说——华胥没人犯罪？我才不信咧，这种话就是哄小孩子的吧！",
            ["ContentJP"] = "それって……<Default note=\"text:カショ\">華胥</>には悪いヤツがいないってこと？嘘だ！そんな子供だましには乗らないよ！",
            ["DialogueId"] = 12010018,
            ["GUID"] = "1E10D994",
            ["NextDialogue"] = 12010019,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D994",
            },
        [12010019] = {
            ["Content"] = "呵呵……是吗？",
            ["ContentJP"] = "ふふ……あら、そう？",
            ["DialogueId"] = 12010019,
            ["GUID"] = "1E10D9BE",
            ["NextDialogue"] = 12010020,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D9BE",
            },
        [12010020] = {
            ["Content"] = "止流大当家——",
            ["ContentJP"] = "シリュウ当主――！",
            ["DialogueId"] = 12010020,
            ["GUID"] = "1E10D9E8",
            ["NextDialogue"] = 12010021,
            ["SpeakNpcName"] = "UI_Npc_Name_FarawayVoice",
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10D9E8",
            },
        [12010021] = {
            ["Content"] = "好像码头上有人在叫您。",
            ["ContentJP"] = "ふ頭で誰かが呼んでますよ。",
            ["DialogueId"] = 12010021,
            ["GUID"] = "1E10DA12",
            ["NextDialogue"] = 12010022,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10DA12",
            },
        [12010022] = {
            ["Content"] = "嗯，我听到了。我们先下船去看看吧。",
            ["ContentJP"] = "ええ、聞こえてるわ。船が港に着いたら、行ってみましょう。",
            ["DialogueId"] = 12010022,
            ["GUID"] = "1E10DA3C",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120100/1E10DA3C",
            },
        [12010101] = {
            ["Content"] = "止流大当家。今次的卸货名单，该找哪位清点核对呢？",
            ["ContentJP"] = "シリュウ当主、今回の荷下ろし分の確認はどなたが？",
            ["DialogueId"] = 12010101,
            ["GUID"] = "1E10E732",
            ["NextDialogue"] = 12010102,
            ["SpeakNpcId"] = 210030,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E732",
            },
        [12010102] = {
            ["Content"] = "杜立没来吗？我嘱咐过他提早前来接应的。",
            ["ContentJP"] = "ドゥリは？前もって迎えに来るよう伝えたはずなんだけれど……",
            ["DialogueId"] = 12010102,
            ["GUID"] = "1E10E75C",
            ["NextDialogue"] = 12010103,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E75C",
            },
        [12010103] = {
            ["Content"] = "这趟运回来了好些贵重货物，有些需要特殊的储运手法，有他盯着，我放心些。",
            ["ContentJP"] = "今回は貴重な荷もいくつか積んでるの。中には特別な保管や運搬が必要なものもあるから……彼に見ていてもらおうと思ってたのよ。",
            ["DialogueId"] = 12010103,
            ["GUID"] = "1E10E786",
            ["NextDialogue"] = 12010104,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E786",
            },
        [12010104] = {
            ["Content"] = "兄弟们打听了一圈，今天码头上没人见过杜管事。",
            ["ContentJP"] = "みんなで聞いて回ったんですが……今日は誰も、ドゥリさんを見てないそうで。",
            ["DialogueId"] = 12010104,
            ["GUID"] = "1E10E7B0",
            ["NextDialogue"] = 12010105,
            ["SpeakNpcId"] = 210030,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E7B0",
            },
        [12010105] = {
            ["Content"] = "嗯……我明白了。他或许是被什么事情拖住了，先在这里等候一下吧。",
            ["ContentJP"] = "そう……他のことで立て込んでいるのかもしれないわね。ここで少し待ってもらえるかしら。",
            ["DialogueId"] = 12010105,
            ["GUID"] = "1E10E7DA",
            ["NextDialogue"] = 12010106,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E7DA",
            },
        [12010106] = {
            ["Content"] = "新鲜出炉的烤鱼嘞——不好吃不要钱——",
            ["ContentJP"] = "焼きたての魚だよ〜！不味かったら、お代はいらないよ～！",
            ["DialogueId"] = 12010106,
            ["GUID"] = "1E10E804",
            ["NextDialogue"] = 12010107,
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E804",
            },
        [12010107] = {
            ["Content"] = "哇——好香啊！",
            ["ContentJP"] = "うひょー！いいにおい！",
            ["DialogueId"] = 12010107,
            ["GUID"] = "1E10E82E",
            ["NextDialogue"] = 12010108,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E82E",
            },
        [12010108] = {
            ["Content"] = "刚刚才在船上吃了小点心，现在又馋了吗？",
            ["ContentJP"] = "さっき船でおやつ食べたばかりだよね……",
            ["DialogueId"] = 12010108,
            ["GUID"] = "1E10E858",
            ["NextDialogue"] = 12010109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E858",
            },
        [12010109] = {
            ["Content"] = "烤鱼是很香没错啦！但感觉空气里还有一股说不上来的香味。",
            ["ContentJP"] = "焼き魚の匂いも食欲そそるけど～、なんかそれとは別に、もっとこう……うまそうな香りが漂ってない？",
            ["DialogueId"] = 12010109,
            ["GUID"] = "1E10E882",
            ["NextDialogue"] = 12010110,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E882",
            },
        [12010110] = {
            ["Content"] = "有点像花香，又有点像清晨的霜的味道……总之很好闻就是了！",
            ["ContentJP"] = "花の匂いのような、朝の霜のような……とにかく、すっごくいい匂いがしてるよ！",
            ["DialogueId"] = 12010110,
            ["GUID"] = "1E10E8AC",
            ["NextDialogue"] = 12010111,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E8AC",
            },
        [12010111] = {
            ["Content"] = "也是巧合，本该前来接应的人迟到了。{nickname}，你们初来乍到，我就陪你们逛逛吧。",
            ["ContentJP"] = "ちょうど、あなたたちを迎えに来るはずの人が遅刻してるみたいだし、私が少し街を案内してあげるわ。",
            ["DialogueId"] = 12010111,
            ["GUID"] = "1E10E8D6",
            ["NextDialogue"] = 12010112,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E8D6",
            },
        [12010112] = {
            ["Content"] = "好耶！那白想看看那边的小吃摊子，那个拨浪鼓看起来也好有意思……还有那里！",
            ["ContentJP"] = "やった～！スノウ、あっちの屋台見てみたい！あのガラガラ鳴るやつも気になるし……それからあれも面白そう！",
            ["DialogueId"] = 12010112,
            ["GUID"] = "1E10E900",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E900",
            },
        [12010113] = {
            ["Camera"] = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "针头线脑、香脂香囊，我这儿样样齐全。客官，要来一份吗？",
            ["ContentJP"] = "針に糸、香油に香り袋、なんでも揃ってるよ〜。お客さん、おひとついかが？",
            ["DialogueId"] = 12010113,
            ["FacialId"] = {
                [1] = "210031:Cin_Smile01",
                },
            ["FinalCamera"] = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E10E92A",
            ["LookAt"] = {
                [1] = "210031:n(100001)",
                },
            ["NextDialogue"] = 12010114,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210031:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E92A",
            },
        [12010114] = {
            ["Content"] = "看中了什么？直接拿吧，我来付账。",
            ["ContentJP"] = "欲しいのがあったら、遠慮しないで。買ってあげるわ。",
            ["DialogueId"] = 12010114,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["GUID"] = "1E10E954",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                },
            ["NextDialogue"] = 12010115,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210031:Talk01_End",
                [2] = "\
210004:ConfidentR_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E954",
            },
        [12010115] = {
            ["Camera"] = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["Content"] = "你们在华胥的所有开销都由我包揽了，尽管花，让他们记在百年春的账上就行。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>での滞在中、費用は全部私が受け持つわ。欲しい物があったら、「<Default note=\"text:ももとき\">百年春</>」にツケさせておきなさい。",
            ["DialogueId"] = 12010115,
            ["FinalCamera"] = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["GUID"] = "1E10E97E",
            ["LookAt"] = {
                [1] = "100001:n(210004)",
                },
            ["NextOptions"] = {
                [1] = 120101151,
                [2] = 120101152,
                },
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToTalk_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E97E",
            },
        [12010116] = {
            ["Camera"] = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "呵呵……放心。这些小钱，我供得起。",
            ["ContentJP"] = "ふふ……その程度の出費、大したことないわ。",
            ["DialogueId"] = 12010116,
            ["GUID"] = "1E10E9A8",
            ["NextDialogue"] = 12010117,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9A8",
            },
        [12010117] = {
            ["Camera"] = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "止流大当家！您办事归来了。原来这位<H>有龙氏</>是您邀请的客人。",
            ["ContentJP"] = "おお、当主！お戻りでしたか！なるほど、こちらの<H>「龍の民」</>はあなたのお客さんだったんですね！",
            ["DialogueId"] = 12010117,
            ["GUID"] = "1E10E9D2",
            ["LookAt"] = {
                [1] = "210031:n(210004)",
                [2] = "\
210004:n(210031)",
                [3] = "\
100001:n(210031)",
                },
            ["NextDialogue"] = 12010118,
            ["RelatedWikiId"] = {
                [1] = 405008,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentRToTalk_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9D2",
            },
        [12010118] = {
            ["Camera"] = "-148.47049,-63.694336,115.687988,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
            ["Content"] = "瞧{性别：他|她}的角，小巧、坚硬又有光泽，一看便有成龙之相。真是优秀的后生，让人看着就心生欢喜。",
            ["ContentJP"] = "見てくださいよ、{性别:彼|彼女}の角。小ぶりで硬くてつやもある――こりゃあ立派な龍の相ですな。いやぁ、こりゃ将来有望な若者だ、見てるだけで嬉しくなっちまうよ。",
            ["DialogueId"] = 12010118,
            ["FinalCamera"] = "-145.448669,-59.758316,115.963867,0.000015,3.201023,52.205986,50.000008,354.199371,false,DoNotOverride,8.0",
            ["GUID"] = "1E10E9FC",
            ["NextDialogue"] = 12010119,
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:ConfidentR_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10E9FC",
            },
        [12010119] = {
            ["Camera"] = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,50.0,147.841843,false,DoNotOverride,8.0",
            ["Content"] = "有龙氏……止流掌柜，你们是在说我吗？",
            ["ContentJP"] = "龍の民……って、{性别:僕|私}のこと？",
            ["DialogueId"] = 12010119,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["FinalCamera"] = "-23.817619,-70.792191,153.86084,0.00002,-4.399809,81.994202,53.0,147.841843,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EA26",
            ["NextDialogue"] = 12010120,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA26",
            },
        [12010120] = {
            ["Camera"] = "-166.510681,150.144012,125.549805,0.000042,2.600478,-8.198592,50.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "忘了告诉你，有龙氏是华胥文化中对于卡戎的称呼。不同于海伯利亚的歧视与打压，在这里，卡戎被视为护佑国家的祥瑞种族。",
            ["ContentJP"] = "言い忘れてたわね。<Default note=\"text:カショ\">華胥</>ではカロンを「龍の民」って呼ぶの。ヒュペリアみたいに差別されたり迫害されたりなんてことはなくて、ここでは国家を守る祥瑞のような存在として大切にされてるのよ。",
            ["DialogueId"] = 12010120,
            ["GUID"] = "1E10EA50",
            ["LookAt"] = {
                [1] = "210004:n(100001)",
                [2] = "100001:n(210004)",
                },
            ["NextDialogue"] = 12010121,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                [2] = "210004:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA50",
            },
        [12010121] = {
            ["Content"] = "当初我遇见你时，看见年幼的有龙氏被旁人刁难，忍不住照拂了一下。",
            ["ContentJP"] = "最初にあなたと出会ったとき、幼い龍の民が周りにいじめられてるのを見て……つい、放っておけなくて手を差し伸べたの。",
            ["DialogueId"] = 12010121,
            ["FacialId"] = {
                [1] = "210004:Smile02",
                },
            ["GUID"] = "1E10EA7A",
            ["NextDialogue"] = 12010122,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EA7A",
            },
        [12010122] = {
            ["Camera"] = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,35.0,176.801208,false,DoNotOverride,8.0",
            ["Content"] = "这样说来……止流掌柜也是卡戎——啊，有龙氏。我那时就好奇过您的身份，您看起来地位并不普通。",
            ["ContentJP"] = "そういえば……シリュウさんもカロン――あっ、「龍の民」なんですね。あのときから気になってました、ただ者じゃない雰囲気でしたから。",
            ["DialogueId"] = 12010122,
            ["FinalCamera"] = "-68.049751,89.252998,97.667969,0.000073,16.599312,8.000803,38.0,176.801208,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EAA4",
            ["NextDialogue"] = 12010123,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EAA4",
            },
        [12010123] = {
            ["Camera"] = "-258.889587,722.140747,375.999023,0.000044,-22.399721,-67.201347,35.0,257.556915,false,DoNotOverride,8.0",
            ["Content"] = "呵呵……{性别：小弟弟|小妹妹}，你觉得止流大当家是什么身份？",
            ["ContentJP"] = "ふふ……{性别:ぼうず|嬢ちゃん}、シリュウ当主が誰か、知らないのかい？",
            ["DialogueId"] = 12010123,
            ["GUID"] = "1E10EACE",
            ["LookAt"] = {
                [1] = "210031:n(100001)",
                [2] = "\
210004:n(210031)",
                [3] = "\
100001:n(210031)",
                },
            ["NextOptions"] = {
                [1] = 120101231,
                [2] = 120101232,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210031:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EACE",
            },
        [12010124] = {
            ["Camera"] = "-300.496887,-107.604889,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["Content"] = "她可是年纪尚轻时，就获得了天命青睐，当上了<H>龙渊上卿</>。如今她司掌天禄司，就是说呀，咱们华胥所有贸易、财政、收税都归她管。",
            ["ContentJP"] = "あの方はね、まだお若いころに天命に選ばれて、「龍淵の<Default note=\"text:しょうけい\">上卿</>」にまで上り詰めたお方だよ。<Default note=\"text:カショ\">華胥</>の中じゃ、交易も財政も税も、ぜ〜んぶあの方が握ってるのさ。",
            ["DialogueId"] = 12010124,
            ["FacialId"] = {
                [1] = "210004:Smile01",
                },
            ["FinalCamera"] = "-302.217896,-104.770386,166.557129,0.000039,-5.799308,31.399658,50.0,441.88739,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EAF8",
            ["NextDialogue"] = 12010125,
            ["RelatedWikiId"] = {
                [1] = 407005,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EAF8",
            },
        [12010125] = {
            ["Content"] = "只是，止流大当家为人平易近人，平日里不准我们称呼她的官职，只愿我们以大当家的头衔相称。在这里做生意的人，多多少少都承过她的人情。",
            ["ContentJP"] = "でもね、シリュウさんはとっても気さくな方でな。普段から偉そうな肩書きは使わせずに、「シリュウさん」って呼べって言うんだよ。ここで商売やってる者なら、誰だって一度はあの方の世話になってるんだ。",
            ["DialogueId"] = 12010125,
            ["GUID"] = "1E10EB22",
            ["NextDialogue"] = 12010126,
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB22",
            },
        [12010126] = {
            ["Content"] = "……只是没有刻意提起的必要罢了。毕竟，以势压人，不如以理服人来得妥当。",
            ["ContentJP"] = "……わざわざ言うほどのことでもなかっただけよ。力でねじ伏せるより、道理で納得させるほうが、ずっと穏やかでいいでしょ。",
            ["DialogueId"] = 12010126,
            ["GUID"] = "1E10EB4C",
            ["NextDialogue"] = 12010127,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:DisagreeHead",
                [2] = "210031:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB4C",
            },
        [12010127] = {
            ["Camera"] = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,35.0,165.19751,false,DoNotOverride,8.0",
            ["Content"] = "商人这个身份，进可织星揽月，退可通权达变。比起一官半职来，倒是更符合我的喜好。",
            ["ContentJP"] = "商人って立場はね、動けば大きなことを成し遂げられるし、引けば流れにうまく馴染める。お偉いさんの肩書きより、ずっと性に合うわ。",
            ["DialogueId"] = 12010127,
            ["FinalCamera"] = "-68.959076,68.54129,118.671875,0.000075,7.399253,11.199726,38.0,165.19751,false,DoNotOverride,8.0",
            ["GUID"] = "1E10EB76",
            ["NextDialogue"] = 12010128,
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EB76",
            },
        [12010128] = {
            ["Camera"] = "315.296692,492.476501,203.203613,0.000004,-9.399719,-124.991638,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来，{性别：小弟弟|小妹妹}。止流大当家难得带贵客来。这件香囊你就作为见面礼收下吧。",
            ["ContentJP"] = "シリュウさんが{性别:ぼうず|嬢ちゃん}のような客人を連れてくるのはめったにないんだ。ほれ、この香り袋をやろう。",
            ["DialogueId"] = 12010128,
            ["FinalCamera"] = "311.297241,486.82547,183.789551,0.000005,-7.199613,-125.391396,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E10EBA0",
            ["NextOptions"] = {
                [1] = 120101281,
                [2] = 120101282,
                },
            ["SpeakNpcId"] = 210031,
            ["TalkActionId"] = {
                [1] = "210004:Talk03ToTalkL_End",
                [2] = "210031:Give",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBA0",
            },
        [12010129] = {
            ["Content"] = "<H>香</>在华胥可是有着大作用。定气凝神，防身护体，个中妙用，你很快就能体悟到了。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>じゃあ、<H>香</>には大きな力があるんだよ。心を落ち着けたり、身を守ったり……その不思議な効き目、すぐに実感するはずさ。",
            ["DialogueId"] = 12010129,
            ["FacialId"] = {
                [1] = "210031:Cin_Happy01",
                },
            ["GUID"] = "1E10EBCA",
            ["RelatedWikiId"] = {
                [1] = 403005,
                },
            ["SpeakNpcId"] = 210031,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBCA",
            },
        [12010130] = {
            ["Content"] = "烤鱿鱼还是香喷喷的小银鱼干，唔，好难选哦……",
            ["ContentJP"] = "焼きイカにしよっかな～それとも香ばしいニボシに……う～ん、どっちもおいしそうで迷う～！",
            ["DialogueId"] = 12010130,
            ["Duration"] = 3,
            ["GUID"] = "1E10EBF4",
            ["NextDialogue"] = 12010131,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EBF4",
            },
        [12010131] = {
            ["Content"] = "老板，一样来一份好了！多来点酱汁！",
            ["ContentJP"] = "きーめた！店長、一つずつください！ソース多めでっ！",
            ["DialogueId"] = 12010131,
            ["GUID"] = "1E10EC1E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EC1E",
            },
        [12010132] = {
            ["Content"] = "咦，白跑到哪里去了……",
            ["ContentJP"] = "あれ……スノウは？",
            ["DialogueId"] = 12010132,
            ["GUID"] = "1E10EC48",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120101/1E10EC48",
            },
        [12010201] = {
            ["Camera"] = "26.601562,-263.371094,126.632324,0.0,-8.000487,77.603035,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以说，梦想是很重要的——比如白的梦想，就是成为世界第一的大魔王！",
            ["ContentJP"] = "だからね、夢ってすっごく大事なんだよ！たとえばスノウの夢はね――世界一の大魔王になることっ！",
            ["DialogueId"] = 12010201,
            ["GUID"] = "1E10F79A",
            ["NextDialogue"] = 12010202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F79A",
            },
        [12010202] = {
            ["Content"] = "哇，说的太好了！",
            ["ContentJP"] = "わぁ、すっごーい！",
            ["DialogueId"] = 12010202,
            ["GUID"] = "1E10F7C4",
            ["NextDialogue"] = 12010203,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F7C4",
            },
        [12010203] = {
            ["Content"] = "你看，华胥的这片码头有这么大对吧。今后本魔王大人的宫殿要比它大十倍！",
            ["ContentJP"] = "ほら、<Default note=\"text:カショ\">華胥</>のこの港ってけっこう広いでしょ？将来、この10倍もの大きさのお城を建てるんだ！",
            ["DialogueId"] = 12010203,
            ["GUID"] = "1E10F7EE",
            ["NextDialogue"] = 12010204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F7EE",
            },
        [12010204] = {
            ["Content"] = "等梦想实现后，白每天就能睡到下午三点，然后从长一百米的大床上醒来，享用搜罗了全世界所有小蛋糕的豪华下午茶！",
            ["ContentJP"] = "夢が叶ったら、スノウは毎日お昼すぎまでぐっすり寝て、長さ100メートルのベッドで毎日目を覚まして、世界中のカップケーキを集めた豪華なアフタヌーンティーを楽しむんだ～！",
            ["DialogueId"] = 12010204,
            ["GUID"] = "1E10F818",
            ["NextDialogue"] = 12010205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F818",
            },
        [12010205] = {
            ["Content"] = "那……我要成为青史留名的织星客，在人类的史书上，写下皎皎一族的名字！",
            ["ContentJP"] = "じゃあ……私は歴史に名を刻む星織人になる！人間の史書に、ルーナの名を刻みつけるんだ！",
            ["DialogueId"] = 12010205,
            ["GUID"] = "1E10F842",
            ["NextDialogue"] = 12010206,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F842",
            },
        [12010206] = {
            ["Content"] = "到时候，从现在这里到遥远的对岸，整个码头都要铺满我的货物。每个集装箱上都要画一个硕大的皎皎涂鸦！",
            ["ContentJP"] = "それで、ここから遥か彼方の対岸まで、港まるごと私の貨物で埋め尽くすんだ！コンテナ全部にでっかいルーナの落書きをしてやる！",
            ["DialogueId"] = 12010206,
            ["GUID"] = "1E10F86C",
            ["NextDialogue"] = 12010207,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F86C",
            },
        [12010207] = {
            ["Content"] = "很好，就要这个气势！大声喊出来，皎皎之民征服世界——",
            ["ContentJP"] = "よーし、その調子だ！もっと大きな声で！世界はルーナ族のモノなりーーっ！",
            ["DialogueId"] = 12010207,
            ["GUID"] = "1E10F896",
            ["NextDialogue"] = 12010208,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F896",
            },
        [12010208] = {
            ["Content"] = "呜呜……早上起床时，我向白龙神君祈愿，希望今天可以撞见好运。",
            ["ContentJP"] = "うぅ……朝起きた時、白龍様にお祈りしたんだ。「今日はいいことがありますように」って。",
            ["DialogueId"] = 12010208,
            ["GUID"] = "1E10F8C0",
            ["NextDialogue"] = 12010209,
            ["RelatedWikiId"] = {
                [1] = 303008,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F8C0",
            },
        [12010209] = {
            ["Content"] = "本来只是指望来码头进货时，可以从那些抠门织星客手中再抢下几个单子。没想到，有生之年，竟然能让我看到活的有角皎皎……",
            ["ContentJP"] = "ふ頭で仕入れるついでに、あのケチな星織人から、もう何件か仕事を横取りできたらいいなって思ってたら、まさか生きた角付きルーナに会えるなんて！！",
            ["DialogueId"] = 12010209,
            ["GUID"] = "1E10F8EA",
            ["NextDialogue"] = 12010210,
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F8EA",
            },
        [12010210] = {
            ["Camera"] = "345.640625,-174.457031,104.969238,0.000003,-0.600497,140.202652,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来白龙神君大人终于回应我的诚心了……那个，尊贵的魔王殿下，可以让我再摸一下你的角吗？",
            ["ContentJP"] = "きっと白龍様が私の願いを聞いてくれたんだろうなぁ……あの、魔王さま、その角……もう一度だけ触らせてくれない？",
            ["DialogueId"] = 12010210,
            ["GUID"] = "1E10F914",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextOptions"] = {
                [1] = 120102101,
                [2] = 120102102,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F914",
            },
        [12010211] = {
            ["Content"] = "小仆从，你怎么来了……你、你都听见了？",
            ["ContentJP"] = "我が下僕！なぜここに……い、いつから聞いてたの？",
            ["DialogueId"] = 12010211,
            ["GUID"] = "1E10F93E",
            ["NextOptions"] = {
                [1] = 120102111,
                [2] = 120102112,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F93E",
            },
        [12010212] = {
            ["Content"] = "咳咳……这就是本魔王麾下的得力大将，{nickname}。",
            ["ContentJP"] = "ゴホン……こいつは、この魔王様の頼れる右腕、{nickname}だ。",
            ["DialogueId"] = 12010212,
            ["GUID"] = "1E10F968",
            ["NextDialogue"] = 12010213,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F968",
            },
        [12010213] = {
            ["Content"] = "哇——不愧是魔王大人，竟然能吸引一位有龙氏前来效忠。幸会，我是即将成为华胥第一织星客的锦鲤皎皎！",
            ["ContentJP"] = "わぁ！さすが魔王さま！まさか龍の民を従えてるなんて！初めまして、私はまもなく<Default note=\"text:カショ\">華胥</>一の星織人になる予定の、ニシキだよ！",
            ["DialogueId"] = 12010213,
            ["GUID"] = "1E10F992",
            ["NextDialogue"] = 12010214,
            ["RelatedWikiId"] = {
                [1] = 203002,
                },
            ["SpeakNpcId"] = 210003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F992",
            },
        [12010214] = {
            ["Camera"] = "422.453125,1255.105469,437.982422,0.00003,-8.400634,-104.197899,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "白，止流掌柜还在等着我们呢。玩够了就赶紧回去吧。",
            ["ContentJP"] = "スノウ、お遊びはそれくらいにして。シリュウさんが待ってるんだから。",
            ["DialogueId"] = 12010214,
            ["GUID"] = "1E10F9BC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F9BC",
            },
        [12010215] = {
            ["Camera"] = "-387.542969,474.4375,151.621582,0.000187,-2.20303,-35.42408,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "止流掌柜——我把白找回来了。",
            ["ContentJP"] = "シリュウさん、スノウを見つけました。",
            ["DialogueId"] = 12010215,
            ["GUID"] = "1E10F9E6",
            ["NextDialogue"] = 12010216,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408011,
                [3] = 203001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10F9E6",
            },
        [12010216] = {
            ["Content"] = "……一群**养的！没完没了！",
            ["ContentJP"] = "……クソッたれが！いい加減にしろよ！",
            ["DialogueId"] = 12010216,
            ["GUID"] = "1E10FA10",
            ["NextDialogue"] = 12010217,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA10",
            },
        [12010217] = {
            ["Camera"] = "192.5,215.453125,162.744141,0.000181,-5.402953,-76.421349,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "……小心！！！",
            ["ContentJP"] = "危ない！",
            ["DialogueId"] = 12010217,
            ["GUID"] = "1E10FA3A",
            ["NextDialogue"] = 12010218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA3A",
            },
        [12010218] = {
            ["Camera"] = "999.449219,-469.097656,578.913574,0.000173,-25.402763,150.978256,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "喂，你就是这里的舵手吧？赶紧驾船带老子离开这个鬼地方，越快越好！",
            ["ContentJP"] = "おい、てめぇがここの船頭だな！？さっさと船を出せ！こんなクソみたいな場所、もう一秒たりともいたくねぇ！さっさとしろ！",
            ["DialogueId"] = 12010218,
            ["GUID"] = "1E10FA64",
            ["NextDialogue"] = 12010219,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA64",
            },
        [12010219] = {
            ["Content"] = "胆敢轻举妄动，或者做什么手脚，老子一刀嘎了你。",
            ["ContentJP"] = "下手な真似しやがったら、その場でブッた斬るぞ。わかったか？",
            ["DialogueId"] = 12010219,
            ["GUID"] = "1E10FA8E",
            ["NextDialogue"] = 12010220,
            ["SpeakNpcId"] = 210002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FA8E",
            },
        [12010220] = {
            ["Content"] = "放开他！",
            ["ContentJP"] = "その人を{性别:放せ|放して}！",
            ["DialogueId"] = 12010220,
            ["GUID"] = "1E10FAB8",
            ["NextDialogue"] = 12010221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FAB8",
            },
        [12010221] = {
            ["Camera"] = "-863.470703,299.425781,276.108887,0.000178,-7.60267,-14.021979,35.0,100000.0,false,Manual,12.0",
            ["Content"] = "冷静点，{nickname}，不用出手。",
            ["ContentJP"] = "その必要はないわ、{nickname}。",
            ["DialogueId"] = 12010221,
            ["GUID"] = "1E10FAE2",
            ["NextDialogue"] = 12010222,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FAE2",
            },
        [12010222] = {
            ["Content"] = "可是刀都架在船夫的脖子上了！明明是这么紧急的情况，你们怎么还能这么淡定！",
            ["ContentJP"] = "刀がもう船頭さんの首に当たってるんだよ！？こんなピンチなのに、なんでみんなそんなに落ち着いていられるの！？",
            ["DialogueId"] = 12010222,
            ["GUID"] = "1E10FB0C",
            ["NextDialogue"] = 12010223,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB0C",
            },
        [12010223] = {
            ["Content"] = "这位劫匪大约是外来者，尚未熟悉这里的规矩。",
            ["ContentJP"] = "この賊はよそ者のようね。この土地の「掟」をまるで知らないなんて。",
            ["DialogueId"] = 12010223,
            ["GUID"] = "1E10FB36",
            ["NextDialogue"] = 12010224,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB36",
            },
        [12010224] = {
            ["Content"] = "记得我先前所说吗？华胥是<H>止戈之乡</>。也好，让你们有机会亲眼见证——",
            ["ContentJP"] = "前に話したのを覚えてる？<Default note=\"text:カショ\">華胥</>は「武器要らずの」国。ちょうどいいわ、あなたたちにもその真意を見せてあげましょう－－",
            ["DialogueId"] = 12010224,
            ["GUID"] = "1E10FB60",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB60",
            },
        [12010225] = {
            ["Content"] = "嗷呜——",
            ["ContentJP"] = "グオオォォ――",
            ["DialogueId"] = 12010225,
            ["GUID"] = "1E10FB8A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FB8A",
            },
        }
  end },
  { MinKey = 12010226, MaxKey = 12010909, Loader = function()
      return {
        [12010226] = {
            ["Content"] = "又是这些东西，怎么阴魂不散的！",
            ["ContentJP"] = "くそ！こいつまた……どこまでしつこいんだよ！！",
            ["DialogueId"] = 12010226,
            ["GUID"] = "1E10FBB4",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FBB4",
            },
        [12010227] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那、那是什么……？",
            ["ContentJP"] = "い、今のは……？",
            ["DialogueId"] = 12010227,
            ["GUID"] = "1E10FBDE",
            ["NextDialogue"] = 12010228,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FBDE",
            },
        [12010228] = {
            ["Content"] = "小仆从，看到了吗！那个家伙只用了一招就让坏人消失了诶。",
            ["ContentJP"] = "わ、我が下僕……今の見た！？一発であの悪党を消しちゃったぞ！……",
            ["DialogueId"] = 12010228,
            ["GUID"] = "1E10FC08",
            ["NextDialogue"] = 12010229,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC08",
            },
        [12010229] = {
            ["Content"] = "<H>大风有隧，有空大谷。有兽狴犴，乘风而行。香尘扰扰，缘有罪因。</>这是华胥子民从牙牙学语时便能念诵的歌谣。",
            ["ContentJP"] = "<Default note=\"text:たいふう\">大風</>は<Default note=\"text:みち\">隧</>を開き、<Default note=\"text:おおたに\">大谷</>を越える。<Default note=\"text:ビーアン\">狴犴</>は風に乗り、<Default note=\"text:そら\">空</>にて<Default note=\"text:はごろも\">羽衣</>を舞う。<Default note=\"text:こうじん\">香塵</>の乱れも、罪が深いゆえ。</>これは<Default note=\"text:カショ\">華胥</>の子どもたちが言葉を覚えたときから、ずっと歌い継いできた歌よ。",
            ["DialogueId"] = 12010229,
            ["GUID"] = "1E10FC32",
            ["NextDialogue"] = 12010230,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC32",
            },
        [12010230] = {
            ["Content"] = "歌谣中的“狴犴”，便是你们所见之物——华胥的守护者。",
            ["ContentJP"] = "この歌詞の「<Default note=\"text:ビーアン\">狴犴</>」こそ、あなたたちが目にしたあの神獣――<Default note=\"text:カショ\">華胥</>の守り神の名よ。",
            ["DialogueId"] = 12010230,
            ["GUID"] = "1E10FC5C",
            ["NextDialogue"] = 12010231,
            ["RelatedWikiId"] = {
                [1] = 303009,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC5C",
            },
        [12010231] = {
            ["Content"] = "华胥全境被一种无声无形、但又恒常流转之法则，<H>大风九章</>所统御。任何人只要踏入了华胥的界域，就会进入大风九章的保护范围内。",
            ["ContentJP"] = "この土地は<H>「大風九章」</>という、形無くして絶えず巡る法則によって守られているの。足を踏み入れた者は、誰であれ「大風九章」の加護を受ける。",
            ["DialogueId"] = 12010231,
            ["GUID"] = "1E10FC86",
            ["NextDialogue"] = 12010232,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FC86",
            },
        [12010232] = {
            ["Content"] = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
            ["ContentJP"] = "一方で、掟を破れば、<Default note=\"text:ビーアン\">狴犴</>は冷たい風に乗って姿を現し、制裁を下すのよ。",
            ["DialogueId"] = 12010232,
            ["GUID"] = "1E10FCB0",
            ["NextDialogue"] = 12010233,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCB0",
            },
        [12010233] = {
            ["Content"] = "原来，这就是这里完全杜绝犯罪的理由……",
            ["ContentJP"] = "なるほど、だからここには悪いやつがいなかったのか……",
            ["DialogueId"] = 12010233,
            ["GUID"] = "1E10FCDA",
            ["NextDialogue"] = 12010234,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCDA",
            },
        [12010234] = {
            ["Content"] = "只是不知何故，出现了不懂规矩的外来者。看来，这一趟办事归来，倒是有些“惊喜”等着我呢。",
            ["ContentJP"] = "どうやら掟知らずのよそ者がいるようね。戻って早々、とんでもない「予期せぬこと」が待っている気がするわ。",
            ["DialogueId"] = 12010234,
            ["GUID"] = "1E10FD04",
            ["NextDialogue"] = 12010235,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FD04",
            },
        [12010235] = {
            ["Content"] = "大当家——不好意思，属下来迟了——",
            ["ContentJP"] = "すみません、シリュウさん！遅れました！",
            ["DialogueId"] = 12010235,
            ["GUID"] = "1E10FD2E",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FD2E",
            },
        [12010301] = {
            ["Camera"] = "-156.389893,790.13324,235.143555,0.00015,-10.001431,-71.777824,50.0,856.361206,false,DoNotOverride,2.8",
            ["Content"] = "幸好歹人已经被截获了……他竟然跑到这里来，惊扰到了您。",
            ["ContentJP"] = "賊は無事に捕まえたようですね！まさかここまで来るとは……ご迷惑をおかけしてすみません。",
            ["DialogueId"] = 12010301,
            ["FacialId"] = {
                [1] = "210032:Cin_Sad01",
                },
            ["FinalCamera"] = "-137.076416,731.468506,224.247559,0.00015,-10.001431,-71.777466,50.0,856.361206,false,DoNotOverride,2.8",
            ["GUID"] = "1E110802",
            ["LookAt"] = {
                [1] = "100001:n(210032)",
