                [1] = "210004:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120109/1E116BEC",
            },
        [12010911] = {
            ["Content"] = "想必不用我再叮嘱什么了……{nickname}，我等着你平安归来。",
            ["ContentJP"] = "何度も言うけど……{nickname}、必ず無事に戻ってきてね。",
            ["DialogueId"] = 12010911,
            ["GUID"] = "1E116C16",
            ["LookAt"] = {
                [1] = "210004:n(210004)",
                },
            ["Scripts"] = "LookAt{_delay{4},LookAtDescription{\"210004:n(100001)\"}}",
            ["SpeakNpcId"] = 210004,
            ["TalkActionId"] = {
                [1] = "210004:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120109/1E116C16",
            },
        [12011001] = {
            ["Content"] = "沿海洞窟……看来就是前面那里了。",
            ["ContentJP"] = "海沿いの洞窟……たぶん、あそこかな。",
            ["DialogueId"] = 12011001,
            ["Duration"] = 2,
            ["GUID"] = "1E117ADA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117ADA",
            },
        [12011002] = {
            ["Content"] = "白还记得和小仆从第一次探险，也是下洞窟，仿佛就像昨天刚刚发生一样！",
            ["ContentJP"] = "そういえば、スノウたちが初めて冒険したとこも洞窟だったよね！？まるで昨日のことみたいにはっきり覚えてるぞ！",
            ["DialogueId"] = 12011002,
            ["Duration"] = 4,
            ["GUID"] = "1E117B04",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B04",
            },
        [12011003] = {
            ["Content"] = "谁想到转眼间，我们就来到这么远的地方，肩负这么激动人心的大使命——",
            ["ContentJP"] = "まさかこんなに遠くまで来て、しかもこんなワクワクする大任務を任されるなんて思わなかったなぁ――！",
            ["DialogueId"] = 12011003,
            ["Duration"] = 4,
            ["GUID"] = "1E117B2E",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B2E",
            },
        [12011004] = {
            ["Content"] = "……嗯。那次遇到了奥特赛德，敲了他一顿竹杠。赛琪……也还在。",
            ["ContentJP"] = "……うん。そこでアウトサイダーに出くわして、ちょっとふっかけてやったっけ。サイキも、まだ一緒で……",
            ["DialogueId"] = 12011004,
            ["Duration"] = 3,
            ["GUID"] = "1E117B58",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011005,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B58",
            },
        [12011005] = {
            ["Content"] = "白、白说错话了……",
            ["ContentJP"] = "あ、ご、ごめ……",
            ["DialogueId"] = 12011005,
            ["Duration"] = 2,
            ["GUID"] = "1E117B82",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117B82",
            },
        [12011006] = {
            ["Content"] = "没关系。等我们回去，再到泪湖边去，把华胥的见闻说给她听吧。",
            ["ContentJP"] = "大丈夫。戻ったら、またダクリ湖に行って、<Default note=\"text:カショ\">華胥</>で見たことをサイキに話してあげよう。",
            ["DialogueId"] = 12011006,
            ["Duration"] = 5,
            ["GUID"] = "1E117BAC",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120110/1E117BAC",
            },
        [12011101] = {
            ["Content"] = "喂——喂——有人吗？",
            ["ContentJP"] = "やっほー！やっほー！だれかいるー？",
            ["DialogueId"] = 12011101,
            ["Duration"] = 2,
            ["GUID"] = "1E118B42",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E118B42",
            },
        [12011102] = {
            ["Content"] = "看，小仆从！这里黑布隆冬的，说话还会有回音耶。你会怕黑吗？",
            ["ContentJP"] = "見て見て、我が下僕！ここ、真っ暗で声が響くよ〜。君、暗いの怖かったりする？",
            ["DialogueId"] = 12011102,
            ["Duration"] = 3,
            ["GUID"] = "1E118B6C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E118B6C",
            },
        [12011103] = {
            ["Content"] = "不怕。但是我们说话声音最好压低些，当心引来什么奇怪的东西。",
            ["ContentJP"] = "怖くはないけど、声は抑えたほうがいい。変なモノを呼び寄せたら厄介だから。",
            ["DialogueId"] = 12011103,
            ["Duration"] = 3,
            ["GUID"] = "1E118B96",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E118B96",
            },
        [12011104] = {
            ["Content"] = "……哇啊！！",
            ["ContentJP"] = "……うわぁ！！",
            ["DialogueId"] = 12011104,
            ["Duration"] = 2,
            ["GUID"] = "1E118BC0",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E118BC0",
            },
        [12011201] = {
            ["Content"] = "呸、呸！好的不灵坏的灵，小仆从简直是乌鸦嘴——",
            ["ContentJP"] = "ふん！我が下僕が不吉なこと言うから――！！",
            ["DialogueId"] = 12011201,
            ["Duration"] = 2,
            ["GUID"] = "1E119BAA",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E119BAA",
            },
        [12011202] = {
            ["Content"] = "又是玄色狴犴，它们的数量怎么越来越多了！",
            ["ContentJP"] = "また<Default note=\"text:ゲンビー\">玄狴</>だ！しかもどんどん増えてる！",
            ["DialogueId"] = 12011202,
            ["Duration"] = 2,
            ["GUID"] = "1E119BD4",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E119BD4",
            },
        [12011301] = {
            ["Content"] = "留神——",
            ["ContentJP"] = "油断大敵。",
            ["DialogueId"] = 12011301,
            ["Duration"] = 3,
            ["GUID"] = "1E11AC12",
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E11AC12",
            },
