        [12011415] = {
            ["Camera"] = "-20.366999,-42.464127,13.334961,0.000288,25.588646,77.37146,35.000011,257.516388,false,Manual,14.0",
            ["Content"] = "怎、怎么办，小仆从？！我们好像被他误解了……",
            ["ContentJP"] = "ど、どうしよう。なんだか誤解されちゃったみたい……！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011415,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "1E11BEC6",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12011416,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                [2] = "100001:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BEC6",
            },
        [12011416] = {
            ["Content"] = "事情不是你想的那样。我们受止流掌柜雇佣，为了解决玄色狴犴肆虐的问题，需要去黑市取一样工具。",
            ["ContentJP"] = "{性别:誤解しないでほしい。僕たちはシリュウさんに頼まれて、<Default note=\"text:ゲンビー\">玄狴</>の暴走を止めるために動いてる。そのために、闇市で必要な道具を受け取りにきたんだ。|誤解しないで。私たちはシリュウさんに頼まれて、<Default note=\"text:ゲンビー\">玄狴</>の暴走を止めるために動いてる。そのために、闇市で必要な道具を受け取りにきたの。}",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011416,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
