            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BF6E",
            },
        [12011420] = {
            ["Camera"] = "189.114975,196.35614,114.457275,0.000178,-3.606934,-159.432861,25.000006,417.040405,false,Manual,22.0",
            ["Content"] = "此地不安全，让我护送你们过去吧。",
            ["ContentJP"] = "ここは危険だ。……俺が護衛してやろう。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12011420,
            ["GUID"] = "1E11BF98",
            ["Scripts"] = "PlayAnimation{_delay{0},ActorId{200002},AnimationId{\"Explain02_End\"},Duration{1}},",
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["TalkActionId"] = {
                [1] = "210007:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E11BF98",
            },
        [12011501] = {
            ["Content"] = "应天尉就是华胥的卫戍部队吧！你们有工资拿吗，待遇怎么样呀？",
            ["ContentJP"] = "<Default note=\"text:おうてんい\">応天尉</>って、<Default note=\"text:カショ\">華胥</>の守備隊でしょ？お給料とかちゃんともらえるの？待遇はいいのかな～なんて……",
            ["DialogueId"] = 12011501,
            ["Duration"] = 3,
            ["GUID"] = "1E11CCE2",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011502,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CCE2",
            },
        [12011502] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12011502,
            ["Duration"] = 1,
            ["GUID"] = "1E11CD0C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011503,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD0C",
            },
        [12011503] = {
            ["Content"] = "好啦好啦。白知道了，白不问这些了。",
            ["ContentJP"] = "はいはい、わかったよ。もう聞かないって～",
            ["DialogueId"] = 12011503,
            ["Duration"] = 2,
            ["GUID"] = "1E11CD36",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD36",
            },
        [12011504] = {
            ["Content"] = "我为应天尉，只愿济苍生，安黎元，并非为那些身外俗物。",
            ["ContentJP"] = "俺が<Default note=\"text:おうてんい\">応天尉</>として在るのは、ただ民を救い、世を安んずるためだ。報酬や名声に心を動かされることはない。",
            ["DialogueId"] = 12011504,
            ["Duration"] = 2,
            ["GUID"] = "1E11CD60",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011505,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD60",
            },
        [12011505] = {
            ["Content"] = "……小仆从你听，就是不发工资的意思咯？比帝国还抠门！",
            ["ContentJP"] = "……我が下僕、今の聞いた？つまりお給料ナシってことだよね？帝国よりケチじゃん！",
            ["DialogueId"] = 12011505,
            ["Duration"] = 2,
            ["GUID"] = "1E11CD8A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120115/1E11CD8A",
            },
        [12011601] = {
            ["Content"] = "前方恐有玄色狴犴蛰伏，由我开路。请两位紧随我身后。",
            ["ContentJP"] = "この先に<Default note=\"text:ゲンビー\">玄狴</>が潜んでいるかもしれない。俺が先導するから、二人ともついてきてくれ。",
            ["DialogueId"] = 12011601,
            ["Duration"] = 3,
            ["GUID"] = "1E11DD4A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
