            },
        [12011801] = {
            ["Content"] = "怎么……是你们？此处危险——",
            ["ContentJP"] = "君たち…なぜ？ここは危険だ、すぐに下がれ――！",
            ["DialogueId"] = 12011801,
            ["Duration"] = 3,
            ["GUID"] = "1E11FE1A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120118/1E11FE1A",
            },
        [12011802] = {
            ["Content"] = "我来帮你！",
            ["ContentJP"] = "手を貸すよ！",
            ["DialogueId"] = 12011802,
            ["Duration"] = 2,
            ["GUID"] = "1E11FE44",
            ["VoiceName"] = "voice/$Locale$/story/1201/120118/1E11FE44",
            },
        [12011901] = {
            ["Content"] = "你们是化外无关人士，不应卷入这场恶战。这里由我一人应对就好。",
            ["ContentJP"] = "……君たちは無関係の部外者だ。こんな戦いに巻き込まれるべきじゃない。ここは、俺ひとりで十分だ。",
            ["DialogueId"] = 12011901,
            ["Duration"] = 3,
            ["GUID"] = "1E120E82",
            ["GuideFacialId"] = "Afraid",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011902,
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120E82",
            },
        [12011902] = {
            ["Content"] = "敌人面前不能闲聊，你说过的。",
            ["ContentJP"] = "敵の前では油断大敵――そう言ったのは、あなたでしょ。",
            ["DialogueId"] = 12011902,
            ["Duration"] = 2,
            ["GUID"] = "1E120EAC",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011903,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120EAC",
            },
        [12011903] = {
            ["Content"] = "就是就是。都负伤了还嘴硬，你就乖乖接受我们的帮助吧！",
            ["ContentJP"] = "そうそう、もうケガしてるのに、まだ強がっちゃって～！ここは素直に、スノウたちに頼るんだね！",
            ["DialogueId"] = 12011903,
            ["Duration"] = 3,
            ["GUID"] = "1E120ED6",
            ["GuideFacialId"] = "Angry",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12011904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120ED6",
            },
        [12011904] = {
            ["Content"] = "……我明白了。",
            ["ContentJP"] = "……わかった。",
            ["DialogueId"] = 12011904,
            ["Duration"] = 2,
            ["GUID"] = "1E120F00",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120119/1E120F00",
            },
        [12012001] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这些孽畜，总算是尽数清缴了。多谢两位施以援手。",
            ["ContentJP"] = "……ようやく、この忌まわしき獣どもを一掃できたか。助力、感謝する。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012001,
            ["GUID"] = "1E121EEA",
            ["NextDialogue"] = 12012002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                },
            ["SpeakNpcId"] = 210007,
            ["SpeakNpcName"] = "UI_Npc_Name_Yingtianwei",
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121EEA",
            },
        [12012002] = {
            ["Content"] = "抱歉，先前失了礼数，尚未互通姓名。在下煜明，请问你们是？",
            ["ContentJP"] = "無礼を詫びよう。まだ名乗っていなかったな……俺はユーミンだ。君たちは？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012002,
            ["GUID"] = "1E121F14",
            ["NextDialogue"] = 12012003,
            ["RelatedWikiId"] = {
                [1] = 203004,
                },
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121F14",
            },
        [12012003] = {
            ["Content"] = "我是外乡来的狩月人{nickname}。这位是……",
            ["ContentJP"] = "{性别:僕|私}は{nickname}、こっちは…",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012003,
            ["GUID"] = "1E121F3E",
            ["NextOptions"] = {
                [1] = 120120031,
                [2] = 120120032,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121F3E",
            },
        [12012005] = {
            ["Content"] = "哼哼，没错！纯白的救赎☆光之魔王大人正是我！",
            ["ContentJP"] = "ふふん、我こそは純白の救い手☆そして光の魔王様だ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012005,
            ["GUID"] = "1E121F92",
            ["NextDialogue"] = 12012009,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121F92",
            },
        [12012007] = {
            ["Content"] = "异国文化，果真高深莫测……",
            ["ContentJP"] = "異国の風習は……まったく、奥が深いものだな。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012007,
            ["GUID"] = "1E121FE6",
            ["NextDialogue"] = 12012008,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E121FE6",
            },
        [12012008] = {
            ["Content"] = "从、从别人的嘴里说出来，怎么有一种莫名的羞耻感……叫我白就好了！",
            ["ContentJP"] = "た、他人の口から言われると、なんか……妙に恥ずかしい……普通にスノウでいい！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012008,
            ["GUID"] = "1E122010",
            ["NextDialogue"] = 12012009,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122010",
            },
        [12012009] = {
            ["Content"] = "刚刚还在说“无暇闲聊”，怎么这会儿就有空啦？",
            ["ContentJP"] = "さっきは「油断大敵」とか言ってたのに、ずいぶん余裕だな？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012009,
            ["GUID"] = "1E12203A",
            ["NextDialogue"] = 12012010,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12203A",
            },
        [12012010] = {
            ["Content"] = "先前我灭敌心切，待人接物有所轻慢，想来惭愧，还望阁下海涵。",
            ["ContentJP"] = "先ほどは討伐を急ぐあまり、応対が粗雑になった。失礼を詫びよう――どうか、水に流してほしい。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012010,
            ["GUID"] = "1E122064",
            ["NextDialogue"] = 12012011,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122064",
            },
        [12012011] = {
            ["Content"] = "好吧。白就大人有大量，原谅你啦！",
            ["ContentJP"] = "ま、いっか！スノウは心が広いから、今回は特別に許してあげるぞ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012011,
            ["GUID"] = "1E12208E",
            ["NextDialogue"] = 12012012,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12208E",
            },
        [12012012] = {
            ["Content"] = "你还好吗？",
            ["ContentJP"] = "大丈夫？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012012,
            ["GUID"] = "1E1220B8",
            ["NextDialogue"] = 12012013,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1220B8",
            },
        [12012013] = {
            ["Content"] = "……无妨。只是刚才应对的狴犴众多，难免左支右绌，受了些皮外伤。",
            ["ContentJP"] = "……心配は無用だ。先ほどの戦いで四方に気を配るうちに、多少のかすり傷を負っただけだ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012013,
            ["GUID"] = "1E1220E2",
            ["NextDialogue"] = 12012014,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1220E2",
            },
        [12012014] = {
            ["Content"] = "这看起来可不只是一点点皮外伤啊喂！",
            ["ContentJP"] = "これ、ちょっとやそっとのかすり傷じゃないってば、もうボロッボロじゃん！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012014,
            ["GUID"] = "1E12210C",
            ["NextDialogue"] = 12012015,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12210C",
            },
        [12012015] = {
            ["Content"] = "给你。这是我为了应对突发情况，从冰湖城带上的绷带和治疗药水。",
            ["ContentJP"] = "これを使って。緊急事態に備えて、アイスレイク城から持ってきた包帯と治療薬だよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012015,
            ["GUID"] = "1E122136",
            ["NextDialogue"] = 12012016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122136",
            },
        [12012016] = {
            ["Content"] = "多谢好意，给两位添忧了……这些伤势只需静坐休息，一晌之后就能痊愈。",
            ["ContentJP"] = "気遣ってくれてありがとう。心配かけて悪かったな……この傷は、少し休めばすぐに治るさ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012016,
            ["GUID"] = "1E122160",
            ["NextDialogue"] = 12012017,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122160",
            },
        [12012017] = {
            ["Content"] = "你确定吗？看起来已经伤到了筋骨，要不去找个医生看看？",
            ["ContentJP"] = "本当に大丈夫？筋とか骨にまで達してそうだし、医者に診てもらったほうがいいんじゃない？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012017,
            ["GUID"] = "1E12218A",
            ["NextDialogue"] = 12012018,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12218A",
            },
        [12012018] = {
            ["Content"] = "应天尉既与大风九章立了契，力量来源自与常人不同。",
            ["ContentJP"] = "<Default note=\"text:おうてんい\">応天尉</>は大風九章と契約を結んでいる。その力は普通の者とは違うものだ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012018,
            ["GUID"] = "1E1221B4",
            ["NextDialogue"] = 12012019,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1221B4",
            },
        [12012019] = {
            ["Content"] = "只要脊骨未损，再重的伤势，也能通过汲取大风九章传来的能量而缓慢修复，不过是多忍受些痛楚煎熬罢了。",
            ["ContentJP"] = "背骨さえ無事なら、どんな重傷も大風九章の力を取り込んで徐々に癒せる。耐え難い痛みや苦しみはあるがな。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012019,
            ["GUID"] = "1E1221DE",
            ["NextDialogue"] = 12012020,
            ["RelatedWikiId"] = {
                [1] = 405010,
                },
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1221DE",
            },
        [12012020] = {
            ["Content"] = "听起来很厉害的样子……这不就是小说里的“不败金身”嘛！白都有点心动了！",
            ["ContentJP"] = "すごい話だね……まるで小説の「不死身」みたい！スノウ、ちょっとうらやましいかも！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012020,
            ["GUID"] = "1E122208",
            ["NextDialogue"] = 12012021,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122208",
            },
        [12012021] = {
            ["Content"] = "那只是好的一面。",
            ["ContentJP"] = "それは、あくまで良い側面に過ぎない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012021,
            ["GUID"] = "1E122232",
            ["NextDialogue"] = 12012022,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122232",
            },
        [12012022] = {
            ["Content"] = "还有坏的一面？",
            ["ContentJP"] = "悪い面もあるのか？",
            ["DialogueId"] = 12012022,
            ["GUID"] = "1E12225C",
            ["NextDialogue"] = 12012023,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12225C",
            },
        [12012023] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12012023,
            ["GUID"] = "1E122286",
            ["NextDialogue"] = 12012024,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122286",
            },
        [12012024] = {
            ["Content"] = "无事，一时失言。",
            ["ContentJP"] = "すまん、少し話しが過ぎた。",
            ["DialogueId"] = 12012024,
            ["GUID"] = "1E1222B0",
            ["NextDialogue"] = 12012025,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1222B0",
            },
        [12012025] = {
            ["Content"] = "我曾是一介罪人，回首往去，纵是披坚执锐，却未能护下任何性命。为大风九章奔走，于我而言，是一件将功折罪的幸事。",
            ["ContentJP"] = "俺はかつて罪人だった。振り返れば、鎧をまとい武器を握っていても、誰ひとり守れなかった。大風九章のために走ることは、俺にとって罪を償う機会であり、幸運でもある。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012025,
            ["GUID"] = "1E1222DA",
            ["NextDialogue"] = 12012026,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1222DA",
            },
        [12012026] = {
            ["Content"] = "多谢二位关怀。我在此疗伤，恕无法远送。",
            ["ContentJP"] = "気遣ってくれてありがとう。ここで傷を癒すから、遠くまでは付き添えそうにない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012026,
            ["GUID"] = "1E122304",
            ["NextDialogue"] = 12012027,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122304",
            },
        [12012027] = {
            ["Content"] = "二位身手了得，但烛阴之祸凶险，还望多多留意。",
            ["ContentJP"] = "ふたりとも腕は確かだが、<Default note=\"text:しょくいん\">燭陰</>は凶暴だ。くれぐれも用心しろよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012027,
            ["GUID"] = "1E12232E",
            ["NextDialogue"] = 12012028,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12232E",
            },
        [12012028] = {
            ["Content"] = "放心，我们会的。",
            ["ContentJP"] = "もちろん。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012028,
            ["GUID"] = "1E122358",
            ["NextDialogue"] = 12012029,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122358",
            },
        [12012029] = {
            ["Content"] = "如此，便好……",
            ["ContentJP"] = "なら、いい……",
            ["DialogueId"] = 12012029,
            ["GUID"] = "1E122382",
            ["NextDialogue"] = 12012030,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122382",
            },
        [12012030] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12012030,
            ["GUID"] = "1E1223AC",
            ["NextDialogue"] = 12012031,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1223AC",
            },
        [12012031] = {
            ["Content"] = "……睡、睡着了？",
            ["ContentJP"] = "……ね、寝た？",
            ["DialogueId"] = 12012031,
            ["GUID"] = "1E1223D6",
            ["NextDialogue"] = 12012032,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E1223D6",
            },
        [12012032] = {
            ["Content"] = "大概是太累了吧。我刚才转了一圈，这里的玄色狴犴都被我们清理干净了，应该暂时安全。我们找点什么把他藏起来吧。",
            ["ContentJP"] = "たぶん疲れてるんだよ。さっき辺りをぐるっと回ったけど、ここの<Default note=\"text:ゲンビー\">玄狴</>は全部片付けたから、しばらくは大丈夫だと思う。何かで彼を隠しておこう。",
            ["DialogueId"] = 12012032,
            ["GUID"] = "1E122400",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E122400",
            },
        [12012033] = {
            ["Camera"] = "-211.635849,61.618118,96.055908,0.000228,-13.199524,1.187723,50.000008,78.880096,false,Manual,6.0",
            ["Content"] = "就这样，大功告成！",
            ["ContentJP"] = "これでよしっと！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012033,
            ["FacialId"] = {
                [1] = "200002:Happy02",
                },
            ["FinalCamera"] = "-209.995361,89.062073,96.055908,0.000229,-12.999502,-3.412318,50.000008,384.850891,false,Manual,6.0",
            ["GUID"] = "1E12242A",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:p(baitx_20_lookat)",
                },
            ["NextDialogue"] = 12012034,
            ["Scripts"] = "SetLocation{ActorId{210007},TargetPoint{\"baitx_20_lookat\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited02_Start",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120120/1E12242A",
            },
        [12012034] = {
            ["Camera"] = "-97.596481,177.937027,64.957031,0.0003,-8.801279,-14.827387,35.000011,109.451584,false,Manual,12.0",
