            ["SpeakNpcId"] = 210008,
            ["TalkActionId"] = {
                [1] = "210008:Confident_New_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E12314A",
            },
        [12012114] = {
            ["Camera"] = "-144.614258,249.075195,179.435547,0.000213,-26.201075,8.196909,40.000011,243.196228,false,Manual,3.746801",
            ["Content"] = "怎、怎么办，小仆从？感觉今天做什么都不顺利，这就是华胥俗称的“点背”嘛！",
            ["ContentJP"] = "ど、どうしよう？今日は何やってもうまくいかない気がする……これが<Default note=\"text:カショ\">華胥</>で言うところの「踏んだり蹴ったり」ってやつかな！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012114,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["FinalCamera"] = "-145.767578,257.100586,179.435547,0.000213,-26.201069,8.196872,40.000011,243.196228,false,Manual,3.746801",
            ["GUID"] = "1E123174",
            ["NextDialogue"] = 12012115,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{210008},TargetPoint{\"MeichantA_Move2\"},Visibility{\"Hide\"}},\
SetLocation{ActorId{210058},TargetPoint{\"Xiaodi1_Move\"},Visibility{\"Hide\"}},\
SetLocation{ActorId{210059},TargetPoint{\"Xiaodi2_Move\"},Visibility{\"Hide\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E123174",
            },
        [12012115] = {
            ["Camera"] = "622.662109,-1112.847656,421.122559,0.000177,-10.60076,113.988228,40.0,243.196228,false,DoNotOverride,3.746801",
            ["Content"] = "只能在这附近转转，看看有没有机会见到那位虬先生了。",
            ["ContentJP"] = "ここら辺をうろうろしながら、あのキョウンさんに会うチャンスを探すしかない{性别:な|ね}。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012115,
            ["FinalCamera"] = "841.544922,-1591.740234,696.769043,0.000171,-15.400682,114.189644,40.0,243.196228,false,DoNotOverride,3.746801",
            ["GUID"] = "1E12319E",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 18,
            ["VoiceName"] = "voice/$Locale$/story/1201/120121/1E12319E",
            },
        [12012201] = {
            ["Content"] = "你——简直欺人太甚！！",
            ["ContentJP"] = "なっ――こんなのあんまりだわ！",
            ["DialogueId"] = 12012201,
            ["Duration"] = 2,
            ["GUID"] = "1E123FBA",
            ["NextDialogue"] = 12012202,
            ["SpeakNpcId"] = 210011,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120122/1E123FBA",
            },
        [12012202] = {
            ["Content"] = "小仆从，对面好像起了什么争执！我们赶紧过去看看热闹！",
            ["ContentJP"] = "下僕、なんだか向こう岸で揉めてるみたい！早くいって、様子を見に行こう！",
            ["DialogueId"] = 12012202,
            ["Duration"] = 3,
            ["GUID"] = "1E123FE4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120122/1E123FE4",
            },
        [12012301] = {
            ["Camera"] = "353.783203,574.717773,227.101074,0.000003,-5.60001,-117.193687,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "今日在这里，我横竖也要讨个说法——",
            ["ContentJP"] = "今日こそはっきりさせてもらうわよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012301,
            ["GUID"] = "1E125022",
            ["NextDialogue"] = 12012302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 408012,
                },
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125022",
            },
        [12012302] = {
            ["Content"] = "你诓骗家父签下了假契书，害得佘家家财尽散。母亲受此打击也一病不起，郁郁而终。",
            ["ContentJP"] = "あんたが父を騙して偽の契約にサインさせ、うちの財産を根こそぎ奪ったせいで、母はそのショックで病に伏し、悲しみに沈んだまま死んでしまったのよ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012302,
            ["GUID"] = "1E12504C",
            ["NextDialogue"] = 12012303,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12504C",
            },
        [12012303] = {
            ["Content"] = "贪了人钱财性命，自己却脱身事外……这黑市还有没有王法存在？！",
            ["ContentJP"] = "人の金も命も奪っておいて、何事もなかったかのようにのうのうと……闇市に、法はないの！？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012303,
            ["GUID"] = "1E125076",
            ["NextDialogue"] = 12012304,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125076",
            },
        [12012304] = {
            ["Content"] = "您说笑呢——大风九章，不就是这华胥的王法？",
            ["ContentJP"] = "バカを言うな。<Default note=\"text:カショ\">華胥</>の掟は「大風九章」だ、違うか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012304,
            ["GUID"] = "1E1250A0",
            ["NextDialogue"] = 12012305,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1250A0",
            },
        [12012305] = {
            ["Content"] = "那狴犴，应天尉，都双目如炬地盯着咱呢。咱要是敢作奸犯科，早就被狴犴给逮了去了。还能站在这里说话？",
            ["ContentJP"] = "あの<Default note=\"text:ビーアン\">狴犴</>に、<Default note=\"text:おうてんい\">応天尉</>まで、みんな鋭い目つきで俺たちを見張ってる。もし俺たちが悪いことなどしたら、とっくに<Default note=\"text:ビーアン\">狴犴</>に捕まってるだろうよ。こんなところに立って話せると思うか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012305,
            ["GUID"] = "1E1250CA",
            ["NextDialogue"] = 12012306,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1250CA",
            },
        [12012306] = {
            ["Content"] = "诫条刻在那儿呢：毁约背盟，不可为也。咱只是照章办事，遵纪守法的小百姓一个呀。你血口喷人，咱心善，姑且不追究了。",
            ["ContentJP"] = "戒律にも刻まれてるだろうが、「誓いを破り、盟を背くこと、為すべからず」ってな。俺はそれに従っただけの、真面目な商人だ。まぁ、俺は優しいから、君のでっち上げも大目に見てやろう。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012306,
            ["GUID"] = "1E1250F4",
            ["NextDialogue"] = 12012307,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1250F4",
            },
        [12012307] = {
            ["Content"] = "你……你怎么恶人先告状！",
            ["ContentJP"] = "なっ！悪いことをしたのはそっちじゃない！！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012307,
            ["GUID"] = "1E12511E",
            ["NextDialogue"] = 12012308,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12511E",
            },
        [12012308] = {
            ["Content"] = "要是正常的生意盈亏，我们便也认下了。但你事后拿出的那份契书，分明是在诓骗、敲诈！",
            ["ContentJP"] = "商売の損得は認めるわ。でも、後から出して来たあの契約書は、明らかな騙しとゆすりじゃない！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012308,
            ["GUID"] = "1E125148",
            ["NextDialogue"] = 12012309,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125148",
            },
        [12012309] = {
            ["Content"] = "哎呀，令尊签字画押时……莫非不识字？",
            ["ContentJP"] = "サインをしたのはお父上だ……まさか、文字すら読めないのか？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012309,
            ["GUID"] = "1E125172",
            ["NextDialogue"] = 12012310,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125172",
            },
        [12012310] = {
            ["Content"] = "（群众哄笑声。）",
            ["ContentJP"] = "（群衆の笑い声）",
            ["DialogueId"] = 12012310,
            ["GUID"] = "1E12519C",
            ["NextDialogue"] = 12012311,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12519C",
            },
        [12012311] = {
            ["Content"] = "别强词夺理了！你看父亲年老眼花，故意把利息的“三倍”写成“三十倍”，还把“十”写得像芝麻一样小——",
            ["ContentJP"] = "そんなの屁理屈よ！お父さんは年で目が悪かった！それを利用して、利子「3倍」を「30倍」に書き換えたり、わざと「10」の字をゴマみたいに小さくしたんでしょ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012311,
            ["GUID"] = "1E1251C6",
            ["NextDialogue"] = 12012312,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1251C6",
            },
        [12012312] = {
            ["Content"] = "天地良心，你敢对白龙神君发誓，你不是故意诓骗家父吗？",
            ["ContentJP"] = "天地と白龍様の前で誓える？本当にお父さんを騙すつもりじゃなかったって！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012312,
            ["GUID"] = "1E1251F0",
            ["NextDialogue"] = 12012313,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1251F0",
            },
        [12012313] = {
            ["Content"] = "小姑娘，这我可就要给你上一课了。",
            ["ContentJP"] = "お嬢ちゃん、一つ教えてやろう。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012313,
            ["GUID"] = "1E12521A",
            ["NextDialogue"] = 12012314,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12521A",
            },
        [12012314] = {
            ["Content"] = "这普天之下，率土之滨，凡是可为的，皆属大风九章默许的。",
            ["ContentJP"] = "この世の中で、できることは全部、大風九章が黙認してることだ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012314,
            ["GUID"] = "1E125244",
            ["NextDialogue"] = 12012315,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125244",
            },
        [12012315] = {
            ["Content"] = "大风九章只管咱们是否守契，又不管这契文怎么写。莫说这“十”字是大是小，就算我给它上面画根麻花，我照样好端端地站在这儿。你又能拿我如何？",
            ["ContentJP"] = "大風九章が気にするのは、契約を守っているかのみ。契約書にどんな字を書こうが、たとえ「10」を小さくしようが、てっぺんに落書きしようが、俺はこうして堂々とここに立ってる。――さて、お嬢ちゃん、あんたに俺をどうこうできるかい？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012315,
            ["GUID"] = "1E12526E",
            ["NextDialogue"] = 12012316,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12526E",
            },
        [12012316] = {
            ["Content"] = "你……！",
            ["ContentJP"] = "なっ……！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012316,
            ["GUID"] = "1E125298",
            ["NextDialogue"] = 12012317,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125298",
            },
        [12012317] = {
            ["Content"] = "今天我就站在这里不走了。我要让每个路过的客人都知道你的所作所为！",
            ["ContentJP"] = "今日は絶対ここを動かないから！通りかかった人全員に、あんたが何をしたか教えてやるわ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012317,
            ["GUID"] = "1E1252C2",
            ["NextDialogue"] = 12012318,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1252C2",
            },
        [12012318] = {
            ["Content"] = "（议论纷纷的嘈杂音。）",
            ["ContentJP"] = "（ざわつき）",
            ["DialogueId"] = 12012318,
            ["GUID"] = "1E1252EC",
            ["NextDialogue"] = 12012319,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1252EC",
            },
        [12012319] = {
            ["Content"] = "好了好了。大伙儿都围在这里，照这样下去，这生意没法做啦。",
            ["ContentJP"] = "ほら、散った散った。こんなんじゃ商売になりやしない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012319,
            ["GUID"] = "1E125316",
            ["NextDialogue"] = 12012320,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125316",
            },
        [12012320] = {
            ["Content"] = "听好了，咱也不是什么恶贯满盈的主。",
            ["ContentJP"] = "いいか？俺たちは別に悪人じゃない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012320,
            ["GUID"] = "1E125340",
            ["NextDialogue"] = 12012321,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125340",
            },
        [12012321] = {
            ["Content"] = "本来这生意，就该买定离手，风险自负。今儿个我欣赏你这小姑娘的骨气，就破例给你一个翻盘的机会。",
            ["ContentJP"] = "本来、商売なんて自己責任だし、売ったら終いってもんだけどな。けど今日は、お嬢ちゃんの根性に免じて、特別にもう一回だけチャンスをやるよ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012321,
            ["GUID"] = "1E12536A",
            ["NextDialogue"] = 12012322,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12536A",
            },
        [12012322] = {
            ["Content"] = "……你说。",
            ["ContentJP"] = "……言ってみなさい。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012322,
            ["GUID"] = "1E125394",
            ["NextDialogue"] = 12012323,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125394",
            },
        [12012323] = {
            ["Content"] = "看到我手下这弱不禁风的小兄弟了吗？按照我们黑市的规矩，你若是能在单挑中赢了他，我便把令尊的欠款连本带息地如数奉还。",
            ["ContentJP"] = "ほら、俺のそばにいる、風だけでも飛んで行っちまいそうな小僧。闇市の掟に従い、こいつにタイマンで勝てたら、お父上の利子と借金は全部チャラにしてやろう。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012323,
            ["GUID"] = "1E1253BE",
            ["NextDialogue"] = 12012324,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1253BE",
            },
        [12012324] = {
            ["Content"] = "单挑？可是华胥禁武，又怎会允许私下械斗……？",
            ["ContentJP"] = "タイマン？でも、<Default note=\"text:カショ\">華胥</>の掟では、私闘は許されない行為で……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012324,
            ["GUID"] = "1E1253E8",
            ["NextDialogue"] = 12012325,
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E1253E8",
            },
        [12012325] = {
            ["Content"] = "瞧您说的。这只是点到为止的切磋，双方只用招式，不伤皮肉，怎会惊动狴犴和应天尉呢。有大风九章护着，您也不用怕自己的性命出什么差池。",
            ["ContentJP"] = "心配はいらんよ。あくまで軽い手合わせ。形だけの勝負といったところだ。どちらも技を交わすだけで、けがをするようなことはない。だから、<Default note=\"text:ビーアン\">狴犴</>や<Default note=\"text:おうてんい\">応天尉</>の世話になることもないし、大風九章の加護もあるから、命に関わることもない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012325,
            ["GUID"] = "1E125412",
            ["NextDialogue"] = 12012326,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125412",
            },
        [12012326] = {
            ["Content"] = "您若是担心咱使什么手段，可以当场起草一份契书，条款都由您亲自书写，总能放心了吧。要是这点胆量都没有，那还请您不要打扰此地生意了。",
            ["ContentJP"] = "もしどうしても不安なら、この場で誓約書を書けばいい。条件は好きなように決めてくれ。これで納得できるだろ？……もっとも、その勇気すらないのなら、ここで商売のじゃまをするのはやめてくれ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012326,
            ["GUID"] = "1E12543C",
            ["NextDialogue"] = 12012327,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E12543C",
            },
        [12012327] = {
            ["Content"] = "……好，我答应！",
            ["ContentJP"] = "……わかったわ！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 12012327,
            ["GUID"] = "1E125466",
            ["SpeakNpcId"] = 210011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120123/1E125466",
            },
        [12012401] = {
            ["Content"] = "他答应得这么爽快……怕是有诈。",
            ["ContentJP"] = "こんなにあっさり話に応じるなんて……何か裏がある気がする。",
            ["DialogueId"] = 12012401,
            ["Duration"] = 2,
            ["GUID"] = "1E12608A",
            ["NextDialogue"] = 12012402,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120124/1E12608A",
            },
        [12012402] = {
            ["Content"] = "呜哇，围观的人越来越多了……可恶，踮起脚都看不到。",
            ["ContentJP"] = "わっ、どんどん人が集まってきてる……もうっ、背伸びしても全然見えないよ！",
            ["DialogueId"] = 12012402,
            ["Duration"] = 3,
            ["GUID"] = "1E1260B4",
            ["NextDialogue"] = 12012403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120124/1E1260B4",
            },
        [12012403] = {
            ["Content"] = "小仆从，我们挤到前排去吧。",
            ["ContentJP"] = "ねぇねぇ下僕、もっと前のほうまで行こっ！",
            ["DialogueId"] = 12012403,
            ["Duration"] = 2,
            ["GUID"] = "1E1260DE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120124/1E1260DE",
            },
        [12012501] = {
            ["Camera"] = "353.783203,574.717773,227.101074,0.000003,-5.60001,-117.193687,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "随着双方揖礼，比试正式开始。",
            ["ContentJP"] = "両者が礼を交わし、いよいよ勝負が始まった。",
            ["DialogueId"] = 12012501,
            ["GUID"] = "1E1270F2",
            ["NextDialogue"] = 12012511,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 408012,
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E1270F2",
            },
        [12012502] = {
            ["Content"] = "小仆从，我看不太明白。但好像……那个姑娘占了上风？那她是不是有翻盘的机会了！",
            ["ContentJP"] = "ねぇ、よくわかんないけど……あの子、ちょっと優勢っぽい？このまま行けば、借金チャラじゃない！？",
            ["DialogueId"] = 12012502,
            ["GUID"] = "1E12711C",
            ["NextDialogue"] = 12012503,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E12711C",
            },
        [12012503] = {
            ["Content"] = "总感觉黑市的人在隐藏自己的实力……",
            ["ContentJP"] = "あの闇市の人、どうも本気を出してないように見える……",
            ["DialogueId"] = 12012503,
            ["GUID"] = "1E127146",
            ["NextDialogue"] = 12012504,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E127146",
            },
        [12012504] = {
            ["Content"] = "不好。那个人，在故意往她刀口上撞——！",
            ["ContentJP"] = "まずい、あいつ……わざと彼女の刃に向かって突っ込んでる――！",
            ["DialogueId"] = 12012504,
            ["GUID"] = "1E127170",
            ["NextDialogue"] = 12012512,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E127170",
            },
        [12012505] = {
            ["Content"] = "他、他为什么要干这种事情？！",
            ["ContentJP"] = "ど、どうしてそんなことを！？",
            ["DialogueId"] = 12012505,
            ["GUID"] = "1E12719A",
            ["NextDialogue"] = 12012510,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E12719A",
            },
        [12012506] = {
            ["Content"] = "原来如此……这样大风九章会判定那女孩伤了人，狴犴会惩罚她！",
            ["ContentJP"] = "そうか……これなら大風九章は、彼女が人を傷つけたと判断する。つまり、<Default note=\"text:ビーアン\">狴犴</>の罰則対象になるってこと！",
            ["DialogueId"] = 12012506,
            ["GUID"] = "1E1271C4",
            ["NextDialogue"] = 12012507,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E1271C4",
            },
        [12012507] = {
            ["Content"] = "糟糕，她控制不住自己的力道了。必须在事态发酵之前分开他们！",
            ["ContentJP"] = "やばい、彼女、うまく力加減ができてない。このままだと大変なことになる……早く止めなきゃ！",
            ["DialogueId"] = 12012507,
            ["GUID"] = "1E1271EE",
            ["NextDialogue"] = 12012508,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E1271EE",
            },
        [12012508] = {
            ["Content"] = "嗷呜——",
            ["ContentJP"] = "グオオォォ――",
            ["DialogueId"] = 12012508,
            ["GUID"] = "1E127218",
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E127218",
            },
        [12012509] = {
            ["Content"] = "由于你的及时救援，黑市商人只“蹭”到了肋下的一处伤口。\
狴犴击伤年轻姑娘以示惩戒，随后在凛风中隐去。",
            ["ContentJP"] = "あなたの素早い救出のおかげで、闇市の商人は肋のあたりにかすり傷を負っただけで済んだ。<Default note=\"text:ビーアン\">狴犴</>は若い娘に罰として傷を与え、冷たい風の中に姿を消した。",
            ["DialogueId"] = 12012509,
            ["Duration"] = 4,
            ["GUID"] = "1E127242",
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E127242",
            },
        [12012510] = {
            ["Content"] = "对于触犯诫律者，狴犴会从凛风中突现，施以惩戒。",
            ["ContentJP"] = "一方で、掟を破れば、<Default note=\"text:ビーアン\">狴犴</>は冷たい風に乗って姿を現し、制裁を下すのよ。",
            ["DialogueId"] = 12012510,
            ["GUID"] = "1E12726C",
            ["NextDialogue"] = 12012506,
            ["VoiceName"] = "voice/$Locale$/story/1201/120102/1E10FCB0",
            },
        [12012511] = {
            ["DialogueId"] = 12012511,
            ["GUID"] = "1E127172",
            ["NextDialogue"] = 12012502,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E127172",
            },
        [12012512] = {
            ["DialogueId"] = 12012512,
            ["GUID"] = "1E127171",
            ["NextDialogue"] = 12012505,
            ["VoiceName"] = "voice/$Locale$/story/1201/120125/1E127171",
            },
        [12012601] = {
            ["Camera"] = "-806.824219,-1533.11377,53.525879,0.000038,-4.799833,23.397711,35.0,385.121887,true,Manual,2.8",
            ["Content"] = "你怎么样了？",
            ["ContentJP"] = "大丈夫？",
            ["DialogueId"] = 12012601,
            ["FacialId"] = {
                [1] = "200002:Sad03",
                [2] = "210089:CM_Sad01",
                [3] = "100001:Sad01",
                },
            ["GUID"] = "1E12815A",
            ["LookAt"] = {
                [1] = "200002:n(210089)",
                [2] = "100001:n(210089)",
                },
            ["NextDialogue"] = 12012602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 408012,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:SquatTalk_Start",
                [2] = "200002:Please01_Start",
                },
            ["TurnTo"] = {
                [1] = "210009:n(210089)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E12815A",
            },
        [12012602] = {
            ["Content"] = "多亏了恩人出手相助……好歹，保全了性命……",
            ["ContentJP"] = "おかげさまで……命だけは助かったわ……",
            ["DialogueId"] = 12012602,
            ["GUID"] = "1E128184",
            ["NextDialogue"] = 12012603,
            ["SpeakNpcId"] = 210089,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E128184",
            },
        [12012603] = {
            ["Content"] = "大风九章……难道是只惩戒好人，却教有心人肆意妄为，逍遥法外的吗？",
            ["ContentJP"] = "善い人は罰せられ、悪人は好き放題に悪さをする……これが大風九章なの？",
            ["DialogueId"] = 12012603,
            ["GUID"] = "1E1281AE",
            ["NextDialogue"] = 12012604,
            ["SpeakNpcId"] = 210089,
            ["TalkActionId"] = {
                [1] = "100001:SquatTalk_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1281AE",
            },
        [12012604] = {
            ["Camera"] = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,60.0,685.305847,true,Manual,2.8",
            ["Content"] = "可惜可惜，差点解决一桩麻烦……你又是哪根葱，跳出来扰咱的好事——",
            ["ContentJP"] = "惜しかったなあ、もうちょいで面倒なやつを一人片付けられたのに……で、お前は何者だ？横から出てきて、俺の邪魔ばっかりしやがって――",
            ["DialogueId"] = 12012604,
            ["FacialId"] = {
                [1] = "210009:CM_Angry01",
                [2] = "100001:Angry01",
                },
            ["FinalCamera"] = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,65.0,685.305847,true,Manual,2.8",
            ["GUID"] = "1E1281D8",
            ["LookAt"] = {
                [1] = "210009:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 120126041,
                [2] = 120126042,
                },
            ["SpeakNpcId"] = 210009,
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "100001:n(210009)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1281D8",
            },
        [12012607] = {
            ["Camera"] = "-205.837891,-1341.109863,120.132812,0.000046,-2.399493,-174.205383,65.0,685.305847,true,Manual,2.8",
            ["Content"] = "带了帮手是吧。今天不管多少人来，我都叫他吃不了兜着走！",
            ["ContentJP"] = "仲間を連れてきたってか？何人来ようが、今日はただじゃ済まさねぇぞ！",
            ["DialogueId"] = 12012607,
            ["GUID"] = "1E128256",
            ["SpeakNpcId"] = 210009,
            ["TalkActionId"] = {
                [1] = "100001:Angry01_Start",
                [2] = "210009:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E128256",
            },
        [12012608] = {
            ["Content"] = "你控制力道，将对方制服，却没有留下伤口。",
            ["ContentJP"] = "あなたは加減して相手を抑え込み、傷を負わせることなく制圧した。",
            ["DialogueId"] = 12012608,
            ["GUID"] = "1E128280",
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E128280",
            },
        [12012609] = {
            ["Camera"] = "944.539062,-331.335449,256.336914,0.000019,-7.799679,166.403183,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "够了——不可怠慢贵客！",
            ["ContentJP"] = "そこまでだ！客人に無礼ではないか。",
            ["DialogueId"] = 12012609,
            ["GUID"] = "1E1282AA",
            ["NextDialogue"] = 12012610,
            ["SpeakNpcId"] = 210010,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1282AA",
            },
        [12012610] = {
            ["Content"] = "是我们没有及时察觉您的到来，让您看了这场闹剧……我家主人<H>虬先生</>有请您移步沉船内部的会客厅，进行商谈。",
            ["ContentJP"] = "こちらが不手際で、あなたのご来訪に気づかず、このような騒ぎをお見せしてしまった。我らが主、<H>キョウンさん</>が、沈没船の奥にある応接室でお待ちです。そちらでゆっくり話しましょう。",
            ["DialogueId"] = 12012610,
            ["GUID"] = "1E1282D4",
            ["NextDialogue"] = 12012611,
            ["RelatedWikiId"] = {
                [1] = 203005,
                },
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1282D4",
            },
        [12012611] = {
            ["Content"] = "我怎么知道，这不是为了调开我而使的伎俩？",
            ["ContentJP"] = "それが本当の話だという根拠は？",
            ["DialogueId"] = 12012611,
            ["GUID"] = "1E1282FE",
            ["NextDialogue"] = 12012612,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1282FE",
            },
        [12012612] = {
            ["Content"] = "您且安心。您的朋友就是我们的朋友。万一朋友在我们的地盘上出了事，我们也不好向止流掌柜交代。",
            ["ContentJP"] = "ご安心を。あなたの友人は、私たちにとっても大切なお客さまです。もしこの場所で何かあれば、私たちだってシリュウさんに顔向けできませんからね。",
            ["DialogueId"] = 12012612,
            ["GUID"] = "1E128328",
            ["NextDialogue"] = 12012613,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E128328",
            },
        [12012613] = {
            ["Content"] = "是，是，都是朋友！原来是误会一场啊！",
            ["ContentJP"] = "そうそう！――いやぁ、ただの誤解だったんだな！",
            ["DialogueId"] = 12012613,
            ["GUID"] = "1E128352",
            ["NextDialogue"] = 12012614,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E128352",
            },
        [12012614] = {
            ["Content"] = "咱今儿就把珍藏的药材都拿出来，给小友赔罪。一定给她的伤口包扎仔细了，让她宾至如归呀。",
            ["ContentJP"] = "お詫びに俺の秘蔵の薬草を全部出そう。彼女の手当もしっかりしとくから安心してくれ。",
            ["DialogueId"] = 12012614,
            ["GUID"] = "1E12837C",
            ["NextDialogue"] = 12012615,
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E12837C",
            },
        [12012615] = {
            ["Content"] = "这样处理，您满意吗？",
            ["ContentJP"] = "これで、誠意は伝わりましたか？",
            ["DialogueId"] = 12012615,
            ["GUID"] = "1E1283A6",
            ["NextDialogue"] = 12012616,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1283A6",
            },
        [12012616] = {
            ["Content"] = "这家伙变脸这么快，真是气人！",
            ["ContentJP"] = "なにそれ、手のひら返し早すぎでしょ！ムカつく～！",
            ["DialogueId"] = 12012616,
            ["GUID"] = "1E1283D0",
            ["NextDialogue"] = 12012617,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1283D0",
            },
        [12012617] = {
            ["Content"] = "你们……",
            ["ContentJP"] = "あなたたち……",
            ["DialogueId"] = 12012617,
            ["GUID"] = "1E1283FA",
            ["NextDialogue"] = 12012618,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E1283FA",
            },
        [12012618] = {
            ["Content"] = "算了。带路吧，我之后再来看她。",
            ["ContentJP"] = "まあいい。案内して。彼女はまたあとで様子を見に来る。",
            ["DialogueId"] = 12012618,
            ["GUID"] = "1E128424",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120126/1E128424",
            },
        [12012701] = {
            ["Camera"] = "69.70105,1077.539062,187.139709,0.0,-5.999931,-101.595413,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "有朋自远方来，幸甚至哉。",
            ["ContentJP"] = "はるばるお越しいただき、光栄だよ。",
            ["DialogueId"] = 12012701,
            ["GUID"] = "1E1291C2",
            ["NextDialogue"] = 12012702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 408012,
                [4] = 203005,
                },
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1291C2",
            },
        [12012702] = {
            ["Content"] = "你们黑市人，平时就是这样行事吗？",
            ["ContentJP"] = "あなたたち闇市の連中は、いつもあんなやり方をしている{性别:のか|の}？",
            ["DialogueId"] = 12012702,
            ["GUID"] = "1E1291EC",
            ["NextDialogue"] = 12012703,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1291EC",
            },
        [12012703] = {
            ["Content"] = "小友恰好撞见了比较极端的个例，但我并不打算否认这种生存之道。",
            ["ContentJP"] = "たまたま少々極端な一幕を見ただけさ――だが、そうした生き方を否定するつもりもない。",
            ["DialogueId"] = 12012703,
            ["GUID"] = "1E129216",
            ["NextDialogue"] = 12012704,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129216",
            },
        [12012704] = {
            ["Content"] = "竟然承认了……无耻！",
            ["ContentJP"] = "開き直るなんて……なんて奴だ！",
            ["DialogueId"] = 12012704,
            ["GUID"] = "1E129240",
            ["NextDialogue"] = 12012705,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129240",
            },
        [12012705] = {
            ["Content"] = "哈哈……要说到礼义廉耻，我倒是有一个问题想要请教。",
            ["ContentJP"] = "ははは……礼や恥を語るか。では、尋ねたいことがある。",
            ["DialogueId"] = 12012705,
            ["GUID"] = "1E12926A",
            ["NextDialogue"] = 12012706,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12926A",
            },
        [12012706] = {
            ["Content"] = "昔日华胥一隅，有群羊，又有一猛虎。猛虎捕食群羊，羔羊为虎所食，不得安生。",
            ["ContentJP"] = "かつて<Default note=\"text:カショ\">華胥</>の片隅に、羊の群れと一頭の猛虎がいた。虎は羊を狩り、幼い子羊まで喰らい、群れは常に怯え、安らぎもなかった。",
            ["DialogueId"] = 12012706,
            ["GUID"] = "1E129294",
            ["NextDialogue"] = 12012707,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129294",
            },
        [12012707] = {
            ["Content"] = "此时一侠义之士路过，羔羊便向那侠士哭求，请他垂怜庇护，令羊群免受求生之苦。",
            ["ContentJP"] = "そこへ、ひとりの義士が通りかかる。子羊たちは涙ながらに訴えた――どうか憐れみを、どうか守ってほしいと。生きるための苦しみから、救ってほしいと。",
            ["DialogueId"] = 12012707,
            ["GUID"] = "1E1292BE",
            ["NextDialogue"] = 12012708,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1292BE",
            },
        [12012708] = {
            ["Content"] = "侠士可怜羔羊羸弱，便回应羊群祈愿，尽逐当地猛兽。又去了羔羊顶角，使它们不至于误伤同类。侠义之士离去后，羊群睦然而居，繁衍壮大。",
            ["ContentJP"] = "義士はその弱き子羊たちを哀れみ、その願いに応えて猛獣を追い払った。そして、羊同士が傷つけ合わぬよう、その角を削いでやった。やがて義士は去り、残された羊たちは争いもなく、仲睦まじく数を増やしていった。",
            ["DialogueId"] = 12012708,
            ["GUID"] = "1E1292E8",
            ["NextDialogue"] = 12012709,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1292E8",
            },
        [12012709] = {
            ["Content"] = "然，多年后一日，羊群中再次闯入一只新的猛虎。羊群折了角，逃跑的功夫又日久生疏，最后全数夭于虎口。",
            ["ContentJP"] = "だが――それから幾年、羊の群れに再び一頭の虎が現れた。角を失った彼らは戦えず、逃げる術も忘れていた。そしてとうとう、すべてが虎の牙にかかって命を落としたのだ。",
            ["DialogueId"] = 12012709,
            ["GUID"] = "1E129312",
            ["NextDialogue"] = 12012710,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129312",
            },
        [12012710] = {
            ["Content"] = "这个故事里，你们认为何者犯了<H>最大的错误</>呢？",
            ["ContentJP"] = "さて、この話の中で――<H>いちばん大きな過ち</>を犯したのは誰だと思う？",
            ["DialogueId"] = 12012710,
            ["GUID"] = "1E12933C",
            ["NextOptions"] = {
                [1] = 120127101,
                [2] = 120127102,
                [3] = 120127103,
                [4] = 120127104,
                },
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12933C",
            },
        [12012711] = {
            ["Content"] = "虎以羊为食，此乃天性使然。",
            ["ContentJP"] = "虎が羊を喰らうのは、天が与えた本性にすぎん。",
            ["DialogueId"] = 12012711,
            ["GUID"] = "1E129366",
            ["NextDialogue"] = 12012713,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129366",
            },
        [12012712] = {
            ["Content"] = "哈哈……所见略同。",
            ["ContentJP"] = "ほぅ……どうやら私たちは似た者同士のようだ。",
            ["DialogueId"] = 12012712,
            ["GUID"] = "1E129390",
            ["NextDialogue"] = 12012713,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129390",
            },
        [12012713] = {
            ["Content"] = "故事里的羔羊就能全然置身事外吗？在天敌面前全无自保之力，只能垂首乞怜，寄希望于他人援手。",
            ["ContentJP"] = "あの物語の子羊たちは、本当に無垢な存在と言えるのか？天敵を前にして、身を守る術も持たず、ただ頭を垂れて他人の慈悲にすがる――それは本当に、責任を逃れられる在り方だろうか。",
            ["DialogueId"] = 12012713,
            ["GUID"] = "1E1293BA",
            ["NextDialogue"] = 12012716,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1293BA",
            },
        [12012714] = {
            ["Content"] = "你想说什么？",
            ["ContentJP"] = "何が言いたい{性别:|の}？",
            ["DialogueId"] = 12012714,
            ["GUID"] = "1E1293E4",
            ["NextDialogue"] = 12012715,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1293E4",
            },
        [12012715] = {
            ["Content"] = "既然小友心中尚无定数，那虬某就给一个答案吧：犯下最大错误的既非猛虎，也非侠士，而是看似最无辜的羊群。",
            ["ContentJP"] = "まだ君の中で答えが定まっていないのなら――私から一つ、答えを示そう。最大の過ちを犯したのは、虎でも義士でもない。一見もっとも無垢に見える、あの子羊たちさ。",
            ["DialogueId"] = 12012715,
            ["GUID"] = "1E12940E",
            ["NextDialogue"] = 12012716,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12940E",
            },
        [12012716] = {
            ["Content"] = "正是它们放弃自保，向侠士摇尾乞怜，才招致了最终的灭亡。",
            ["ContentJP"] = "自ら身を守ることを捨て、義士に尾を振って助けを乞った――その選択こそが、滅びへの道を開いたのだよ。",
            ["DialogueId"] = 12012716,
            ["GUID"] = "1E129438",
            ["NextDialogue"] = 12012717,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129438",
            },
        [12012717] = {
            ["Content"] = "物竞天择，适者生存，自然界本是如此。为什么人类却满口仁义道德，以弱者自居，以顺服为荣呢？",
            ["ContentJP"] = "弱肉強食、適者生存――それが本来の自然の理だ。なのに人は、やたらと仁義や道徳を唱え、弱者の立場に甘んじ、従順であることを美徳とする……一体、何のために？",
            ["DialogueId"] = 12012717,
            ["GUID"] = "1E129462",
            ["NextDialogue"] = 12012718,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129462",
            },
        [12012718] = {
            ["Content"] = "在我看来，道德不过是弱者的遮羞布。逐利才是人之本性。",
            ["ContentJP"] = "私からすれば、道徳など弱者が身を隠すための薄布にすぎん。人の本性とは――利を追い求めることだ。",
            ["DialogueId"] = 12012718,
            ["GUID"] = "1E12948C",
            ["NextDialogue"] = 12012719,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12948C",
            },
        [12012719] = {
            ["Content"] = "但凡有人类这种生物的地方，便伴随着支配与臣服。若有人自愿拔去爪牙，抛下剑盾，把力量交给虚无缥缈的“规则”，那也怪不得我们这样的人存在了。",
            ["ContentJP"] = "人という存在がいるかぎり、そこには必ず支配と服従が生まれる。もし自ら爪を抜き、剣も盾も捨てて、力を空虚な「規則」などに委ねる者がいるのだとしたら――そんな世に、我々のような者が現れるのも、当然のことだろう。",
            ["DialogueId"] = 12012719,
            ["GUID"] = "1E1294B6",
            ["NextDialogue"] = 12012720,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1294B6",
            },
        [12012720] = {
            ["Content"] = "……听你的意思，你追求的是一个人人都可以不受约束，肆意欺凌他人的世界。",
            ["ContentJP"] = "{性别:……つまりあなたの理想は、誰も縛られず、好き勝手に他人を踏みにじれる世界ってわけか。|……つまりあなたの理想は、誰も縛られず、好き勝手に他人を踏みにじれる世界ってわけ？}",
            ["DialogueId"] = 12012720,
            ["GUID"] = "1E1294E0",
            ["NextDialogue"] = 12012721,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1294E0",
            },
        [12012721] = {
            ["Content"] = "但我不喜欢。我不想被人拿剑指着，也对拿剑指着别人没兴趣。",
            ["ContentJP"] = "でも、そんな世界はごめん{性别:だ|よ}。剣を突きつけられるのもごめんだし、誰かに剣を向けるつもりもない。",
            ["DialogueId"] = 12012721,
            ["GUID"] = "1E12950A",
            ["NextDialogue"] = 12012722,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12950A",
            },
        [12012722] = {
            ["Content"] = "哈哈！小友心思纯粹，倒是衬得吾辈蝇营狗苟了。",
            ["ContentJP"] = "ははっ、君の思いはまっすぐで清らかだ――おかげで、我らの欲にまみれた在り様がますますみじめに映るな。",
            ["DialogueId"] = 12012722,
            ["GUID"] = "1E129534",
            ["NextDialogue"] = 12012723,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129534",
            },
        [12012723] = {
            ["Content"] = "闲聊到此为止吧。这就是止流掌柜托付我打造的工具，你拿好了。",
            ["ContentJP"] = "さて――雑談はこの辺にしておこう。これが、シリュウ嬢に頼まれて仕上げた道具だ。受け取ってくれ。",
            ["DialogueId"] = 12012723,
            ["GUID"] = "1E12955E",
            ["NextDialogue"] = 12012724,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12955E",
            },
        [12012724] = {
            ["Content"] = "让白看看，怪模怪样的……方盒子？",
            ["ContentJP"] = "スノウに見せて～。なにこれ……四角い箱？",
            ["DialogueId"] = 12012724,
            ["GUID"] = "1E129588",
            ["NextDialogue"] = 12012725,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129588",
            },
        [12012725] = {
            ["Content"] = "它以失传的机枢派技艺锻造而成，光是凑齐所需材料便费了不少功夫。",
            ["ContentJP"] = "これは、今や失われた機枢派の技法を用いて鍛えたものだ。必要な素材を揃えるだけでも、ずいぶん骨が折れたよ。",
            ["DialogueId"] = 12012725,
            ["GUID"] = "1E1295B2",
            ["NextDialogue"] = 12012726,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1295B2",
            },
        [12012726] = {
            ["Content"] = "至于其中妙用……去请教它的锻造者吧。公尚师傅想必已迫不及待地要显摆自己的手艺了，他就在尘漠石海的入口处等着你们。",
            ["ContentJP"] = "その真価については――直接、鍛えた本人に聞くといい。コウショウ師匠、自分の腕前を披露したくてうずうずしているはずだ。塵砂の荒海、その入口で君たちを待っているよ。",
            ["DialogueId"] = 12012726,
            ["GUID"] = "1E1295DC",
            ["NextDialogue"] = 12012727,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E1295DC",
            },
        [12012727] = {
            ["Content"] = "没什么别的事，我告辞了。",
            ["ContentJP"] = "他に用がないなら、これで失礼する。",
            ["DialogueId"] = 12012727,
            ["GUID"] = "1E129606",
            ["NextDialogue"] = 12012728,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129606",
            },
        [12012728] = {
            ["Content"] = "小友留步片刻。",
            ["ContentJP"] = "お待ちを。",
            ["DialogueId"] = 12012728,
            ["GUID"] = "1E129630",
            ["NextDialogue"] = 12012729,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129630",
            },
        [12012729] = {
            ["Content"] = "顺手带上这支竹笛吧。狴犴造成的伤口并非普通人能承受，这支竹笛或许能发挥意想不到的功用。",
            ["ContentJP"] = "これを――竹の笛だ。ついでに持っていくといい。<Default note=\"text:ビーアン\">狴犴</>による傷は、並の者には堪えられん。その笛が、思いがけない助けになるかもしれない。",
            ["DialogueId"] = 12012729,
            ["GUID"] = "1E12965A",
            ["NextDialogue"] = 12012730,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E12965A",
            },
        [12012730] = {
            ["Content"] = "就当做是……我对你的“投资”好了。",
            ["ContentJP"] = "これは、そうだな……君という者への「投資」ということにしておこう。",
            ["DialogueId"] = 12012730,
            ["GUID"] = "1E129684",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120127/1E129684",
            },
        [12012801] = {
            ["Content"] = "这个叫做虬先生的家伙总是皮笑肉不笑的，真不想和他打交道……",
            ["ContentJP"] = "あのキョウンって人、ずーっと作り笑いしてて、なんかヤダ……できればもう関わりたくないな～",
            ["DialogueId"] = 12012801,
            ["Duration"] = 2,
            ["GUID"] = "1E12A22A",
            ["NextDialogue"] = 12012802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120128/1E12A22A",
            },
        [12012802] = {
            ["Content"] = "这就怕了？",
            ["ContentJP"] = "怖いの？",
            ["DialogueId"] = 12012802,
            ["Duration"] = 2,
            ["GUID"] = "1E12A254",
            ["NextDialogue"] = 12012803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120128/1E12A254",
            },
        [12012803] = {
            ["Content"] = "你、你说什么呢！光之魔王大人顶天立地，怎么会有害怕的东西！",
            ["ContentJP"] = "な、なに言ってんの！光の魔王さまは天下無双なんだよ！？怖いものなんてあるわけないでしょっ！",
            ["DialogueId"] = 12012803,
            ["Duration"] = 3,
            ["GUID"] = "1E12A27E",
            ["NextDialogue"] = 12012804,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120128/1E12A27E",
            },
        }
  end },
  { MinKey = 12012804, MaxKey = 12014305, Loader = function()
      return {
        [12012804] = {
            ["Content"] = "好啦好啦，不拿你开玩笑了。",
            ["ContentJP"] = "はいはい、わかったよ。",
            ["DialogueId"] = 12012804,
            ["Duration"] = 2,
            ["GUID"] = "1E12A2A8",
            ["NextDialogue"] = 12012805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120128/1E12A2A8",
            },
        [12012805] = {
            ["Content"] = "他们在照顾那个女孩。还好，他们还算信守承诺。",
            ["ContentJP"] = "ちゃんとあの子の手当てをしたようだね。……まあ、約束は守ってるってことか。",
            ["DialogueId"] = 12012805,
            ["Duration"] = 2,
            ["GUID"] = "1E12A2D2",
            ["NextDialogue"] = 12012806,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120128/1E12A2D2",
            },
        [12012806] = {
            ["Content"] = "诶，但是她的状态看起来不太好……我们也去看看吧！",
            ["ContentJP"] = "えっ、でもなんか、あの子すっごく辛そう……！ちょっと様子を見てこようよ！",
            ["DialogueId"] = 12012806,
            ["Duration"] = 2,
            ["GUID"] = "1E12A2FC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120128/1E12A2FC",
            },
        [12012901] = {
            ["Content"] = "没想到她身子骨这么弱……挨了狴犴一下便长卧不起了。",
            ["ContentJP"] = "あんな貧弱だとは思わなかったぜ……<Default note=\"text:ビーアン\">狴犴</>に一撃くらっただけで寝たきりとはな。",
            ["DialogueId"] = 12012901,
            ["GUID"] = "1E12B292",
            ["NextDialogue"] = 12012902,
            ["SpeakNpcId"] = 210008,
            ["VoiceName"] = "voice/$Locale$/story/1201/120129/1E12B292",
            },
        [12012902] = {
            ["Content"] = "这下就算是神仙妙手来了，也无力回天了吧。",
            ["ContentJP"] = "こりゃもう、どんな手を使ってもお陀仏だろうな。",
            ["DialogueId"] = 12012902,
            ["GUID"] = "1E12B2BC",
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120129/1E12B2BC",
            },
        [12013001] = {
            ["Content"] = "什么人，走路不看路的吗？",
            ["ContentJP"] = "おい、どこの誰だ！目ついてないのか！",
            ["DialogueId"] = 12013001,
            ["Duration"] = 2,
            ["GUID"] = "1E12C2FA",
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 408012,
                },
            ["SpeakNpcId"] = 210008,
            ["VoiceName"] = "voice/$Locale$/story/1201/120130/1E12C2FA",
            },
        [12013002] = {
            ["Content"] = "我说，这里可是黑市的地盘……嘁，真是怪人。",
            ["ContentJP"] = "ここをだれの縄張りと心得る……ちっ、なんだアイツ、妙な奴だな。",
            ["DialogueId"] = 12013002,
            ["Duration"] = 2,
            ["GUID"] = "1E12C324",
            ["SpeakNpcId"] = 210009,
            ["VoiceName"] = "voice/$Locale$/story/1201/120130/1E12C324",
            },
        [12013003] = {
            ["Content"] = "……你受伤了。痛吗？",
            ["ContentJP"] = "痛みますか？",
            ["DialogueId"] = 12013003,
            ["Duration"] = 2,
            ["GUID"] = "1E12C34E",
            ["SpeakNpcName"] = "UI_Npc_Name_QiZhiShuLi",
            ["VoiceName"] = "voice/$Locale$/story/1201/120130/1E12C34E",
            },
        [12013004] = {
            ["Content"] = "不要紧，忍耐片刻就好。",
            ["ContentJP"] = "心配には及びません。少しだけ、耐えてくださいまし。",
            ["DialogueId"] = 12013004,
            ["Duration"] = 2,
            ["GUID"] = "1E12C378",
            ["SpeakNpcName"] = "UI_Npc_Name_QiZhiShuLi",
            ["VoiceName"] = "voice/$Locale$/story/1201/120130/1E12C378",
            },
        [12013005] = {
            ["Content"] = "你看似多有劳累。",
            ["ContentJP"] = "お疲れが溜まっているご様子ですね。",
            ["DialogueId"] = 12013005,
            ["Duration"] = 2,
            ["GUID"] = "1E12C3A2",
            ["SpeakNpcName"] = "UI_Npc_Name_QiZhiShuLi",
            ["VoiceName"] = "voice/$Locale$/story/1201/120130/1E12C3A2",
            },
        [12013006] = {
            ["Content"] = "我会为你调理，以免积劳成疾。",
            ["ContentJP"] = "このままでは体调を崩しかねません。少し整えて差し上げますね。",
            ["DialogueId"] = 12013006,
            ["Duration"] = 2,
            ["GUID"] = "1E12C3CC",
            ["SpeakNpcName"] = "UI_Npc_Name_QiZhiShuLi",
            ["VoiceName"] = "voice/$Locale$/story/1201/120130/1E12C3CC",
            },
        [12013101] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如此，你的疲累应该已无大碍。",
            ["ContentJP"] = "これで、疲れもだいぶ和らいだはずです。",
            ["DialogueId"] = 12013101,
            ["GUID"] = "1E12D362",
            ["NextDialogue"] = 12013102,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D362",
            },
        [12013102] = {
            ["Content"] = "这位受伤的姑娘，是你们的朋友吗？",
            ["ContentJP"] = "この怪我人は、あなたがたのお知り合いですか？",
            ["DialogueId"] = 12013102,
            ["GUID"] = "1E12D38C",
            ["NextDialogue"] = 12013103,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D38C",
            },
        [12013103] = {
            ["Content"] = "……抱歉，我还未介绍名姓。我是<H>祝由</>扶疏，以家族世代传承的<H>枯荣之法</>，为恶疾缠身之人祛痛排浊。",
            ["ContentJP"] = "……申し遅れました。私は、<H>祝由</>フーシュと申します。代々受け継がれてきた「<Default note=\"text:こえい\">枯栄</>の術」をもって、重き病に苦しむ方々の痛みと穢れを祓っております。",
            ["DialogueId"] = 12013103,
            ["GUID"] = "1E12D3B6",
            ["NextDialogue"] = 12013104,
            ["RelatedWikiId"] = {
                [1] = 405012,
                [2] = 203006,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D3B6",
            },
        [12013104] = {
            ["Content"] = "你的意思是……你是一位医生？",
            ["ContentJP"] = "つまり……あなたは、お医者さんってこと？",
            ["DialogueId"] = 12013104,
            ["GUID"] = "1E12D3E0",
            ["NextDialogue"] = 12013105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D3E0",
            },
        [12013105] = {
            ["Content"] = "在华胥，枯荣之法与医药之学并非同一原理。但如果医师这一称呼会让你觉得方便，倒也无妨——或者简单一点，唤我“扶疏”便可。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>において、「<Default note=\"text:こえい\">枯栄</>の術」と医術とは本来、異なる理に基づくものです。ですが、医師のほうがご理解いただきやすいのであれば、それでも構いません。――あるいは、「フーシュ」とお呼びください。",
            ["DialogueId"] = 12013105,
            ["GUID"] = "1E12D40A",
            ["NextDialogue"] = 12013106,
            ["RelatedWikiId"] = {
                [1] = 304005,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D40A",
            },
        [12013106] = {
            ["Content"] = "二位认识这位姑娘吗？",
            ["ContentJP"] = "この少女とは知り合いで？",
            ["DialogueId"] = 12013106,
            ["GUID"] = "1E12D434",
            ["NextOptions"] = {
                [1] = 120131061,
                [2] = 120131062,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D434",
            },
        [12013107] = {
            ["Content"] = "我无法根治她的病痛。可否了解她的伤因何而起？",
            ["ContentJP"] = "この方の病は、私の術では根治できません。差し支えなければ……彼女がこうなった原因を、お聞かせ願えますか？",
            ["DialogueId"] = 12013107,
            ["GUID"] = "1E12D45E",
            ["NextDialogue"] = 12013108,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D45E",
            },
        [12013108] = {
            ["Content"] = "她的伤口是狴犴造成的，但她不是什么坏人。",
            ["ContentJP"] = "あの傷は……<Default note=\"text:ビーアン\">狴犴</>にやられたもの{性别:だ|}。でも、彼女は決して悪い人間じゃない。",
            ["DialogueId"] = 12013108,
            ["GUID"] = "1E12D488",
            ["NextDialogue"] = 12013109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D488",
            },
        [12013109] = {
            ["Content"] = "她是被黑市的坏家伙陷害，才被大风九章惩罚的！你不要放弃她……",
            ["ContentJP"] = "その子ね、闇市のやつらに騙されたの！だから大風九章に罰せられただけで、悪い子じゃないんだ！……お願い、見捨てないであげて……！",
            ["DialogueId"] = 12013109,
            ["GUID"] = "1E12D4B2",
            ["NextDialogue"] = 12013110,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D4B2",
            },
        [12013110] = {
            ["Content"] = "我明白了。枯荣之术同样源于大风九章，因此我的力量无法治愈狴犴的伤。我会将她带回照料，寻找有无他法。",
            ["ContentJP"] = "承知しました。<Default note=\"text:こえい\">枯栄</>の術もまた、大風九章の理から生まれたもの――ゆえに、私の力では<Default note=\"text:ビーアン\">狴犴</>の傷を癒すことはできません。ですが、彼女は私がお預かりし、できる限りの手を尽くしてみましょう。別の道がないか、探ってみます。",
            ["DialogueId"] = 12013110,
            ["GUID"] = "1E12D4DC",
            ["NextDialogue"] = 12013111,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D4DC",
            },
        [12013111] = {
            ["Content"] = "你……",
            ["ContentJP"] = "あなた……",
            ["DialogueId"] = 12013111,
            ["GUID"] = "1E12D506",
            ["NextDialogue"] = 12013112,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D506",
            },
        [12013112] = {
            ["Content"] = "诶，扶疏姐姐为什么老盯着小仆从看呀，难道小仆从还有什么没治好的伤？",
            ["ContentJP"] = "えっ、フーシュ、なんでさっきから下僕のことじーっと見てるの？もしかして、まだ治ってないケガがあるとか！？",
            ["DialogueId"] = 12013112,
            ["GUID"] = "1E12D530",
            ["NextDialogue"] = 12013113,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D530",
            },
        [12013113] = {
            ["Content"] = "抱歉，我并非有意。你身体并无大碍。只是，你携带的那支竹笛似是故人之物，对我意义重大。",
            ["ContentJP"] = "失礼しました。あなたの身体に異常はありません。……ただ、その手にある竹笛が――かつての知人の持ち物によく似ていたもので。私にとっては……少々、特別なものなのです。",
            ["DialogueId"] = 12013113,
            ["GUID"] = "1E12D55A",
            ["NextDialogue"] = 12013114,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D55A",
            },
        [12013114] = {
            ["Content"] = "谅我冒昧，可否将这支竹笛转让与我？我会尽力给出相应的报酬。",
            ["ContentJP"] = "無礼を承知でお願いがあります――その竹笛を、私に譲ってはいただけませんか？できるかぎりの礼は尽くします。",
            ["DialogueId"] = 12013114,
            ["GUID"] = "1E12D584",
            ["NextOptions"] = {
                [1] = 120131141,
                [2] = 120131142,
                [3] = 120131143,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D584",
            },
        [12013115] = {
            ["Content"] = "枯荣之术不图回报。这是家训，扶疏不敢违背。",
            ["ContentJP"] = "<Default note=\"text:こえい\">枯栄</>の術は、報いを求めて行うものではありません。それが我が家の教え……決して背くわけにはいきません。",
            ["DialogueId"] = 12013115,
            ["GUID"] = "1E12D5AE",
            ["NextDialogue"] = 12013119,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D5AE",
            },
        [12013116] = {
            ["Content"] = "不能平白受人恩惠。这是家训，扶疏不敢违背。",
            ["ContentJP"] = "タダではもらえません。それが我が家の教え……決して背くわけにはいきません。",
            ["DialogueId"] = 12013116,
            ["GUID"] = "1E12D5D8",
            ["NextDialogue"] = 12013119,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D5D8",
            },
        [12013117] = {
            ["Content"] = "理应如此。",
            ["ContentJP"] = "おっしゃる通りです。",
            ["DialogueId"] = 12013117,
            ["GUID"] = "1E12D602",
            ["NextDialogue"] = 12013118,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D602",
            },
        [12013118] = {
            ["Content"] = "不能平白受人恩惠。这是家训，扶疏不敢违背。",
            ["ContentJP"] = "タダではもらえません。それが我が家の教え……決して背くわけにはいきません。",
            ["DialogueId"] = 12013118,
            ["GUID"] = "1E12D62C",
            ["NextDialogue"] = 12013119,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D62C",
            },
        [12013119] = {
            ["Content"] = "只是我现在身无长物，就当我赊了这笔账吧。作为回报，日后你若有需要我的事，凡力所能及，扶疏在所不辞。",
            ["ContentJP"] = "あいにく今の私には、差し出せる物がありません。ですので――この借り、いずれ必ず返します。あなたがいつか私を必要とする日が来たなら、その時は力の及ぶかぎり、お応えしましょう。",
            ["DialogueId"] = 12013119,
            ["GUID"] = "1E12D656",
            ["NextDialogue"] = 12013120,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D656",
            },
        [12013120] = {
            ["Content"] = "它对我们只是一支普通的竹笛，远不如对你而言的价值。来，给你。",
            ["ContentJP"] = "{性别:僕|私}たちにとってはただの笛だけど、あなたにとってはそれ以上の意味があるんでしょ。ほら、どうぞ。",
            ["DialogueId"] = 12013120,
            ["GUID"] = "1E12D680",
            ["NextDialogue"] = 12013121,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D680",
            },
        [12013121] = {
            ["Content"] = "多谢。还请二位告知名姓吧，扶疏定不相忘。",
            ["ContentJP"] = "ありがとうございます。よろしければ、おふたりのお名前を伺っても？",
            ["DialogueId"] = 12013121,
            ["GUID"] = "1E12D6AA",
            ["NextOptions"] = {
                [1] = 120131211,
                [2] = 120131212,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D6AA",
            },
        [12013122] = {
            ["Content"] = "嗯，我读过些风物志，“公爵”应是海伯利亚帝国的贵族。只是这“下水道”……",
            ["ContentJP"] = "風物志で少し読んだことがあります。「公爵」とは、たしかヒュペリア帝国の高位貴族でしたね。……ただ、その「下水道」というのは……",
            ["DialogueId"] = 12013122,
            ["GUID"] = "1E12D6D4",
            ["NextDialogue"] = 12013123,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D6D4",
            },
        [12013123] = {
            ["Content"] = "无事，兴许是我的认知已经跟不上如今的时代了。",
            ["ContentJP"] = "いえ、気にしないでください。きっと、今の時代に私の認識が追いついていないだけなのでしょう。",
            ["DialogueId"] = 12013123,
            ["GUID"] = "1E12D6FE",
            ["NextDialogue"] = 12013124,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D6FE",
            },
        [12013124] = {
            ["Content"] = "开个玩笑……我是{nickname}。这位皎皎叫白。",
            ["ContentJP"] = "……冗談だよ。{性别:僕|私}は{nickname}、こっちのルーナはスノウ。",
            ["DialogueId"] = 12013124,
            ["GUID"] = "1E12D728",
            ["NextDialogue"] = 12013125,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D728",
            },
        [12013125] = {
            ["Content"] = "好的，{nickname}，白。",
            ["ContentJP"] = "そうでしたか。では改めてよろしくお願いいたします、{nickname}さん、スノウさん。",
            ["DialogueId"] = 12013125,
            ["GUID"] = "1E12D752",
            ["NextDialogue"] = 12013126,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D752",
            },
        [12013126] = {
            ["Content"] = "那我便不耽误二位的行程了，回见。",
            ["ContentJP"] = "それでは――私はこの辺で。またお会いしましょう。",
            ["DialogueId"] = 12013126,
            ["GUID"] = "1E12D77C",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D77C",
            },
        [12013127] = {
            ["Content"] = "咳、咳……！",
            ["ContentJP"] = "ゴホッ、ゲホッ！",
            ["DialogueId"] = 12013127,
            ["Duration"] = 4,
            ["GUID"] = "1E12D7A6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120131/1E12D7A6",
            },
        [12013201] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……扶疏姐姐，你怎么了？！",
            ["ContentJP"] = "なっ……ど、どうしたんだ！？",
            ["DialogueId"] = 12013201,
            ["GUID"] = "1E12E3CA",
            ["NextDialogue"] = 12013202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 408012,
                [4] = 405012,
                [5] = 203006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E3CA",
            },
        [12013202] = {
            ["Content"] = "……无妨。",
            ["ContentJP"] = "……いえ、問題ありません。",
            ["DialogueId"] = 12013202,
            ["GUID"] = "1E12E3F4",
            ["NextDialogue"] = 12013203,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E3F4",
            },
        [12013203] = {
            ["Content"] = "以自身气血化如甘霖，引渡患者体内病秽伤痛凝成的浊气，则为<H>枯荣</>。",
            ["ContentJP"] = "己の気血を甘露となして巡らせ、患者の内に積もる病と痛みの穢れを引き取り、外へと流し去る――これが<Default note=\"text:こえい\">枯栄</>です。",
            ["DialogueId"] = 12013203,
            ["GUID"] = "1E12E41E",
            ["NextDialogue"] = 12013204,
            ["RelatedWikiId"] = {
                [1] = 304005,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E41E",
            },
        [12013204] = {
            ["Content"] = "自烛阴之灾以来，伤者众多，我连日使用枯荣之法，气血周转不济，从而失态了，请二位勿要介怀。",
            ["ContentJP"] = "<Default note=\"text:しょくいん\">燭陰</>の禍以来、負傷者が後を絶たず、私は連日<Default note=\"text:こえい\">枯栄</>の術を用いてまいりました。気血の巡りが乱れたまま無理を重ねたせいで、やや体調を崩してしまったようで……どうか、お気になさらないでください。",
            ["DialogueId"] = 12013204,
            ["GUID"] = "1E12E448",
            ["NextDialogue"] = 12013205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E448",
            },
        [12013205] = {
            ["Content"] = "自身气血……小仆从，这又是什么意思？",
            ["ContentJP"] = "おのれのきけつ……ぐぬぬ、難しい！！",
            ["DialogueId"] = 12013205,
            ["GUID"] = "1E12E472",
            ["NextDialogue"] = 12013206,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E472",
            },
        [12013206] = {
            ["Content"] = "扶疏，你的意思是……枯荣之法就是以命换命？",
            ["ContentJP"] = "つまり……その<Default note=\"text:こえい\">枯栄</>の術って、命を削って、命を救うってこと？",
            ["DialogueId"] = 12013206,
            ["GUID"] = "1E12E49C",
            ["NextDialogue"] = 12013207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E49C",
            },
        [12013207] = {
            ["Content"] = "你的家人……不会很担心吗？",
            ["ContentJP"] = "ご家族は……心配しないの？",
            ["DialogueId"] = 12013207,
            ["GUID"] = "1E12E4C6",
            ["NextDialogue"] = 12013208,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E4C6",
            },
        [12013208] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12013208,
            ["GUID"] = "1E12E4F0",
            ["NextDialogue"] = 12013209,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E4F0",
            },
        [12013209] = {
            ["Content"] = "家中传下了排浊化清的秘法，只要休憩片刻就好。",
            ["ContentJP"] = "我が家には、穢れを祓い清める秘法が代々伝わっております。少し休めば、すぐに元どおりになりますよ。",
            ["DialogueId"] = 12013209,
            ["GUID"] = "1E12E51A",
            ["NextDialogue"] = 12013210,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E51A",
            },
        [12013210] = {
            ["Content"] = "哎呀气死我了，那个叫煜明的家伙也是，华胥的卡戎怎么都不把自己的身体当一回事……简直是一个模子刻出来的！",
            ["ContentJP"] = "も～う、ほんっと腹立つ！あのユーミンってやつもそうだし、<Default note=\"text:カショ\">華胥</>のカロンって、なんで自分の身体を大事にしないの！？まるで同じ型で作ったみたい！",
            ["DialogueId"] = 12013210,
            ["GUID"] = "1E12E544",
            ["NextDialogue"] = 12013211,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E544",
            },
        [12013211] = {
            ["Content"] = "枯荣流转，月盈而亏。祛除病痛，自然也要付出等量的代价。",
            ["ContentJP"] = "枯れては栄え、満ちた月はやがて欠ける――それが巡りの理。病を祓えば、その分の代価を払うのもまた然り。",
            ["DialogueId"] = 12013211,
            ["GUID"] = "1E12E56E",
            ["NextDialogue"] = 12013212,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E56E",
            },
        [12013212] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12013212,
            ["GUID"] = "1E12E598",
            ["NextDialogue"] = 12013213,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E598",
            },
        [12013213] = {
            ["Content"] = "我要即刻出发寻找治愈这姑娘的法子，先失陪了。你们且去忙碌，若你们想看望她，可往北部杏林中的枯荣阁寻我。",
            ["ContentJP"] = "この方を癒す術を探すため、すぐに出発せねばなりません。さて、どうぞ、おふたりもご自身のなすべきことを。彼女の容態が気になりましたら、北の杏林にある「<Default note=\"text:こえい\">枯栄</>閣」までお越しください。私はそこにおりますから。",
            ["DialogueId"] = 12013213,
            ["GUID"] = "1E12E5C2",
            ["RelatedWikiId"] = {
                [1] = 405013,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120132/1E12E5C2",
            },
        [12013301] = {
            ["Content"] = "虽然她说休息一会儿就好，但刚才她都吐血了……真的不要紧吗？",
            ["ContentJP"] = "休めば平気って言ってたけど……さっき血まで吐いてたし、ほんとに大丈夫なのかな……",
            ["DialogueId"] = 12013301,
            ["GUID"] = "1E12F432",
            ["NextDialogue"] = 12013302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120133/1E12F432",
            },
        [12013302] = {
            ["Content"] = "如果说枯荣之术就是消耗自己的生命救人，那她这样也有一部分是因为我……",
            ["ContentJP"] = "もし<Default note=\"text:こえい\">枯栄</>の術が、自分の命を削って誰かを救うものなら……少なからず{性别:僕|私}にも責任がある……",
            ["DialogueId"] = 12013302,
            ["GUID"] = "1E12F45C",
            ["NextDialogue"] = 12013303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120133/1E12F45C",
            },
        [12013303] = {
            ["Content"] = "等我们完成止流的差事，就去看看扶疏和那个女孩的情况吧。",
            ["ContentJP"] = "シリュウさんの用件が済んだら、フーシュと、あの少女の様子を見に行こう。",
            ["DialogueId"] = 12013303,
            ["GUID"] = "1E12F486",
            ["NextDialogue"] = 12013304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120133/1E12F486",
            },
        [12013304] = {
            ["Content"] = "说起来，小仆从用一支笛子换取了顶级医生的诺言！这就是那个虬先生的意图吗？",
            ["ContentJP"] = "そういえばさ、あの笛一本で、あの超すご腕のお医者さんを後ろ盾にできちゃったんだよね！？もしかして、あのキョウンって人、ここまで読んでたとか！？",
            ["DialogueId"] = 12013304,
            ["GUID"] = "1E12F4B0",
            ["NextDialogue"] = 12013305,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120133/1E12F4B0",
            },
        [12013305] = {
            ["Content"] = "天上不会掉面包。他给我们的好处，以后肯定也会从我们这里讨回来。",
            ["ContentJP"] = "タダより高いものはない。あの人の「親切」は、いずれ返さないといけないものだよ。",
            ["DialogueId"] = 12013305,
            ["GUID"] = "1E12F4DA",
            ["NextDialogue"] = 12013306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120133/1E12F4DA",
            },
        [12013306] = {
            ["Content"] = "虬先生……我们还是对他警惕些吧。",
            ["ContentJP"] = "キョウンさんには警戒しといた方がいい。",
            ["DialogueId"] = 12013306,
            ["GUID"] = "1E12F504",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120133/1E12F504",
            },
        [12013401] = {
            ["Camera"] = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "你们两位脚程实在是太慢了——怎么才来？我一直搁这儿盯着，瞪得我眼睛都酸了。",
            ["ContentJP"] = "おいおい、遅いぞお前ら～！どれだけ待たせるんだ！ずーっとここで目ぇこらして待ってたんだぞ、目玉がカピカピになるかと思ったわ！",
            ["DialogueId"] = 12013401,
            ["FinalCamera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["GUID"] = "1E13049A",
            ["LookAt"] = {
                [1] = "100001:n(210014)",
                [2] = "200002:n(210014)",
                },
            ["NextDialogue"] = 12013402,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13049A",
            },
        [12013402] = {
            ["Camera"] = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
            ["Content"] = "不好意思，刚刚被一些事情耽搁了。您就是公尚先生吧？",
            ["ContentJP"] = "すみません、ちょっと用事で手間取っちゃって。コウショウさん、ですよね？",
            ["DialogueId"] = 12013402,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "1E1304C4",
            ["NextDialogue"] = 12013403,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1304C4",
            },
        [12013403] = {
            ["Camera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "哎呀，怎么这么见外呢，还叫什么先生？来，快叫声师父！",
            ["ContentJP"] = "なに他人行儀なこと言ってんだい？「さん」なんて水くさい！さあさあ、「師匠！」って呼んでみな！",
            ["DialogueId"] = 12013403,
            ["FacialId"] = {
                [1] = "210014:CM_Happy01",
                },
            ["GUID"] = "1E1304EE",
            ["NextDialogue"] = 12013404,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_Start",
                [2] = "100001:ScratchHead_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1304EE",
            },
        [12013404] = {
            ["Content"] = "咦——你们怎么两手空空，没带拜师礼吗？",
            ["ContentJP"] = "んん？おやおや～？なんだい、手ぶらじゃないか！弟子入りのご挨拶に、手土産もナシってのはちょいと寂しいねぇ～？",
            ["DialogueId"] = 12013404,
            ["FacialId"] = {
                [1] = "210014:CM_Idle",
                [2] = "100001:None",
                },
            ["GUID"] = "1E130518",
            ["NextDialogue"] = 12013405,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130518",
            },
        [12013405] = {
            ["Camera"] = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
            ["Content"] = "……小仆从，搞技术的人，都是这么热情好客的吗？",
            ["ContentJP"] = "……ねぇ、職人って、みんなこんなにノリがいいの？",
            ["DialogueId"] = 12013405,
            ["FacialId"] = {
                [1] = "200002:Guilty",
                },
            ["GUID"] = "1E130542",
            ["NextDialogue"] = 12013406,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130542",
            },
        [12013406] = {
            ["Content"] = "那个，您是不是搞错了什么……我们是来请教这柄武器怎么使用，但好像不是来拜师的……",
            ["ContentJP"] = "あの……ちょっと誤解されてる気がするんですけど……{性别:僕|私}たち、この武器の使い方を教わりに来ただけで、弟子入りしに来たわけじゃ……",
            ["DialogueId"] = 12013406,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "1E13056C",
            ["LookAt"] = {
                [1] = "100001:n(210014)",
                [2] = "200002:n(210014)",
                },
            ["NextDialogue"] = 12013407,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13056C",
            },
        [12013407] = {
            ["Camera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "竟然如此——",
            ["ContentJP"] = "そうだったのか……",
            ["DialogueId"] = 12013407,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "200002:None",
                [3] = "210014:CM_Sad01",
                },
            ["GUID"] = "1E130596",
            ["NextDialogue"] = 12013408,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                [2] = "210014:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130596",
            },
        [12013408] = {
            ["Camera"] = "-81.517975,-323.171509,152.899414,0.000041,-15.400177,85.60154,35.000008,557.472534,false,DoNotOverride,2.8",
            ["Content"] = "哇啊！他好像一下子蔫了——我们是不是说了什么很打击人的话？",
            ["ContentJP"] = "わわっ！なんかすごいしょげてるよ！もしかして、言わない方がよかった！？",
            ["DialogueId"] = 12013408,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "1E1305C0",
            ["NextDialogue"] = 12013409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1305C0",
            },
        [12013409] = {
            ["Content"] = "……您、您好？",
            ["ContentJP"] = "……あ、あのぉ……",
            ["DialogueId"] = 12013409,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E1305EA",
            ["NextDialogue"] = 12013410,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1305EA",
            },
        [12013410] = {
            ["Camera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "罢了。怪我病急乱投医，一听到有人愿意继承我机枢派的衣钵，便喜不自胜，情难自禁。",
            ["ContentJP"] = "まあ、ええさ。早とちりして悪かったな。誰かが機枢派の技を継いでくれるって聞いて、つい舞い上がっちまってさ……はは、ついはしゃぎすぎてしまった。",
            ["DialogueId"] = 12013410,
            ["GUID"] = "1E130614",
            ["NextDialogue"] = 12013411,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "200002:Shock03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130614",
            },
        [12013411] = {
            ["Content"] = "也怪我机枢派如今式微了，换以前风光的时候，弟子排着队来拜师，那是挑花了眼也挑不过来！",
            ["ContentJP"] = "まあ、うちの機枢派も今じゃすっかり見る影もなくなっちまってな。昔は弟子入り志願があとを絶たなくて、誰を選ぶか悩むほどだったんだぜ？……はは、今じゃいい笑い話だけどな。",
            ["DialogueId"] = 12013411,
            ["GUID"] = "1E13063E",
            ["NextDialogue"] = 12013412,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13063E",
            },
        [12013412] = {
            ["Camera"] = "-123.167976,-244.147675,155.87207,0.000059,-18.800013,73.197205,35.0,557.472534,false,DoNotOverride,2.8",
            ["Content"] = "再仔细看看两位，也是一副四体不勤、天资不足的模样。对于需要精密操作、聪慧头脑、过人毅力等等集大成于一体的机括术来说，还是远远不够啊。",
            ["ContentJP"] = "うーん、改めて見ると、お前たち……正直ちょっと、運動神経悪そうだし、頭の回転も遅そうだし、根気も微妙って感じだなあ。繊細な手先、鋭い頭脳、折れない根性――全部そろって初めて扱えるのが機括術ってもんだ。……うん、まだまだってとこだねぇ。",
            ["DialogueId"] = 12013412,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                [2] = "200002:Unhappy01",
                },
            ["FinalCamera"] = "-115.39222,-218.401855,146.717773,0.00006,-18.800013,73.197128,35.0,557.472534,false,DoNotOverride,2.8",
            ["GUID"] = "1E130668",
            ["LookAt"] = {
                [1] = "210014:n(100001)",
                },
            ["NextDialogue"] = 12013413,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130668",
            },
        [12013413] = {
            ["Camera"] = "-139.459106,-137.644135,66.660156,0.00006,-13.600217,47.404423,35.000011,237.675415,false,DoNotOverride,2.8",
            ["Content"] = "……你，你别把我们看扁了！我们今天偏要——",
            ["ContentJP"] = "……な、なんですって！？見下さないでよね！こうなったら――",
            ["DialogueId"] = 12013413,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "1E130692",
            ["NextDialogue"] = 12013414,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130692",
            },
        [12013414] = {
            ["Camera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "哦？你难道是想证明，自己其实很有悟性？",
            ["ContentJP"] = "ほう？ってことは、自分にはセンスがあるって証明するとでも？",
            ["DialogueId"] = 12013414,
            ["FacialId"] = {
                [1] = "210014：CM_Shock01",
                },
            ["GUID"] = "1E1306BC",
            ["LookAt"] = {
                [1] = "210014:n(200002)",
                },
            ["NextDialogue"] = 12013415,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1306BC",
            },
        [12013415] = {
            ["Content"] = "启动这牵机方枢吧。让我看看两位的资质，能否达到我们机枢派的标准。",
            ["ContentJP"] = "じゃあ――そこの「機巧制御盤」を起動してみな。お前たちの腕前、機枢派の基準に届くかどうか……見せてもらおうじゃないか。",
            ["DialogueId"] = 12013415,
            ["FacialId"] = {
                [1] = "210014：CM_Idle",
                },
            ["GUID"] = "1E1306E6",
            ["LookAt"] = {
                [1] = "210014:n(100001)",
                },
            ["SpeakNpcId"] = 210014,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1306E6",
            },
        [12013416] = {
            ["Camera"] = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "看见这些太虚符文了吗？",
            ["ContentJP"] = "この太虚符文が見えるかい？",
            ["DialogueId"] = 12013416,
            ["FinalCamera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["GUID"] = "1E130710",
            ["LookAt"] = {
                [1] = "100001:n(210014)",
                [2] = "210014:n(100001)",
                [3] = "200002:n(210014)",
                },
            ["NextDialogue"] = 12013417,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130710",
            },
        [12013417] = {
            ["Camera"] = "-139.459106,-137.644135,66.660156,0.00006,-13.600217,47.404423,35.000011,237.675415,false,DoNotOverride,2.8",
            ["Content"] = "好难懂的名字……",
            ["ContentJP"] = "うぅ～ん、またまた難しい名前！",
            ["DialogueId"] = 12013417,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "1E13073A",
            ["NextDialogue"] = 12013418,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_End",
                [2] = "200002:Shock03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13073A",
            },
        [12013418] = {
            ["Camera"] = "402.217285,92.511482,100.202637,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "唉，孺子不可教也——太虚，无形无色，却又四处充盈。这是鸿蒙之初的常态。",
            ["ContentJP"] = "はあ、こりゃ見込み薄かもな――「太虚」ってのはな、形も色もないくせに、この世のあらゆるところに満ちてる。いわば、天地がまだ分かれる前の、始まりの「在り方」ってやつだ。",
            ["DialogueId"] = 12013418,
            ["FacialId"] = {
                [1] = "210014:CM_Sad01",
                },
            ["FinalCamera"] = "364.499268,87.476112,95.80127,0.000005,-6.600066,-172.393372,35.000008,555.878662,false,DoNotOverride,2.8",
            ["GUID"] = "1E130764",
            ["NextDialogue"] = 12013419,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130764",
            },
        [12013419] = {
            ["Camera"] = "-1551.53418,-586.06665,694.782227,0.000069,-29.399681,18.407328,35.000011,555.878662,false,DoNotOverride,2.8",
            ["Content"] = "太虚被香所激化，乘风鼓动，便能成为大风九章运转的介质；静而不发，便能凝为浮盈空中的太虚符文。",
            ["ContentJP"] = "太虚は香に触れて活性化し、風に乗って流れ、大風九章を動かす媒介となる。逆に、静かに留まれば――空中にふわりと浮かぶ太虚符文として、その姿を成す。",
            ["DialogueId"] = 12013419,
            ["FacialId"] = {
                [1] = "210014:CM_Idle",
                },
            ["FinalCamera"] = "-1628.330078,-611.611572,740.382324,0.000072,-29.399687,18.407286,35.000011,555.878662,false,DoNotOverride,2.8",
            ["GUID"] = "1E13078E",
            ["NextDialogue"] = 12013420,
            ["SpeakNpcId"] = 210014,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13078E",
            },
        [12013420] = {
            ["Content"] = "但如今在这朔方之地，烛阴蒙尘，固而下之，太虚便凝成裹挟一切有形形体的尘漠。",
            ["ContentJP"] = "だがな、今の朔方じゃ事情が違う。<Default note=\"text:しょくいん\">燭陰</>の穢れが空を覆い、太虚は地へと沈み――その結果、生まれたのが、あらゆるものを飲み込む「塵砂」ってわけさ。",
            ["DialogueId"] = 12013420,
            ["GUID"] = "1E1307B8",
            ["NextDialogue"] = 12013421,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1307B8",
            },
        [12013421] = {
            ["Content"] = "而我这牵机方枢，其开天辟地之功效，便能吸收太虚，使异状归于常态。",
            ["ContentJP"] = "そこで登場したのが、この機巧制御盤さ。天地を切り開くほどの代物でね。太虚を吸収して、乱れた現象を元の姿に戻す力があるんだよ。",
            ["DialogueId"] = 12013421,
            ["GUID"] = "1E1307E2",
            ["SpeakNpcId"] = 210014,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1307E2",
            },
        [12013422] = {
            ["Content"] = "算你勉强过关。下一关考验，你能应付吗？",
            ["ContentJP"] = "まあ、ギリギリ合格ってとこだな。さて、次の試練はどうだ？乗り越えられるかな？",
            ["DialogueId"] = 12013422,
            ["GUID"] = "1E13080C",
            ["SpeakNpcId"] = 210014,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13080C",
            },
        [12013423] = {
            ["Camera"] = "628.248047,360.278137,60.518555,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一套下来行云流水，动作竟如此利索！我却是没什么能再传授与你了。",
            ["ContentJP"] = "いやはや、見事な手さばきだ！一連の流れも淀みなく、まるで水のよう。こりゃもう、私から教えられることはもうないな！",
            ["DialogueId"] = 12013423,
            ["FacialId"] = {
                [1] = "210014:CM_Shock01",
                },
            ["FinalCamera"] = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E130836",
            ["NextDialogue"] = 12013424,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Shock_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130836",
            },
        [12013424] = {
            ["Camera"] = "-127.312958,25.078018,85.87793,0.000067,-13.821461,9.846305,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎？那是不是意味着小仆从学成出师了？",
            ["ContentJP"] = "それって、卒業ってこと！？",
            ["DialogueId"] = 12013424,
            ["FacialId"] = {
                [1] = "210014:CM_Idle",
                [2] = "200002:Happy01",
                },
            ["GUID"] = "1E130860",
            ["NextDialogue"] = 12013425,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "210014:Shock_End",
                [2] = "200002:Excited01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130860",
            },
        [12013425] = {
            ["Camera"] = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "出师……也罢。当今世道，还有人愿意以我机枢派的名号为荣，不乏是一桩幸事。",
            ["ContentJP"] = "卒業……まあいいだろう。このご時世で、機枢派の名を背負いたいなんて言ってくれる者がいるだけでも、ありがたいことさ。",
            ["DialogueId"] = 12013425,
            ["GUID"] = "1E13088A",
            ["NextDialogue"] = 12013426,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Sigh_Start",
                [2] = "200002:Excited01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13088A",
            },
        [12013426] = {
            ["Camera"] = "-183.790024,-222.993271,212.301758,0.000059,-21.221882,58.649464,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "两位，我便授予你们<H>机枢派荣誉学徒</>的头衔。望你们博学笃志，切问近思。不要辜负我们机枢派上下求索、高天揽月之志。",
            ["ContentJP"] = "それじゃあ、お前たち二人には――「機枢派名誉見習い」の称号を授けよう。広く学び、志を深く持て。よく問い、よく考えるんだ。そして忘れるなよ、我ら機枢派の志は、果てなき空をも掴もうとするものだってことを！",
            ["DialogueId"] = 12013426,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                [2] = "200002:Smile01",
                },
            ["GUID"] = "1E1308B4",
            ["NextDialogue"] = 12013427,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_Start",
                [2] = "100001:Shy02_Start",
                [3] = "200002:Excited01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1308B4",
            },
        [12013427] = {
            ["Camera"] = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "高处便是烛阴鳞所在之地。以我先前教你的法子，将附着于烛阴鳞之上的尘漠尽数吸收，便可进行采摘。",
            ["ContentJP"] = "あの高所にあるのが、<Default note=\"text:しょくいん\">燭陰</>の鱗ってやつだ。さっき教えた方法を使って、鱗にまとわりついてる塵砂をすべて吸収すれば――無事に採取できよう。",
            ["DialogueId"] = 12013427,
            ["GUID"] = "1E1308DE",
            ["NextDialogue"] = 12013428,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1308DE",
            },
        [12013428] = {
            ["Content"] = "我一把老身子骨了，不便与你们同行。你们且去吧。",
            ["ContentJP"] = "私ももう年だ、そうそう一緒には動けん。さあ、あとはお前たちで行ってきなさい。",
            ["DialogueId"] = 12013428,
            ["FacialId"] = {
                [1] = "210014:CM_Sad01",
                },
            ["GUID"] = "1E130908",
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130908",
            },
        [12013429] = {
            ["Content"] = "小仆从，你看！那边有一个奇怪的东西，散发出邪恶的气息！",
            ["ContentJP"] = "下僕、見て見て！あっちにヘンなやつがいるよ！なんかすっごく……禍々しい気配出してる！",
            ["DialogueId"] = 12013429,
            ["GUID"] = "1E130932",
            ["NextDialogue"] = 12013430,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130932",
            },
        [12013430] = {
            ["Content"] = "以白魔王大人的洞见……那一定就是他们说的那个什么烛阴鳞了！",
            ["ContentJP"] = "この魔王様の鋭い洞察眼からすれば、あれこそが噂の……なんだっけ？あ、そう！<Default note=\"text:しょくいん\">燭陰</>の鱗にちがいないっ！",
            ["DialogueId"] = 12013430,
            ["GUID"] = "1E13095C",
            ["NextDialogue"] = 12013431,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E13095C",
            },
        [12013431] = {
            ["Content"] = "快用公尚师傅教我们的方法试试吧！",
            ["ContentJP"] = "早く！コウショウ師匠が教えてくれたやり方、試してみようよ！",
            ["DialogueId"] = 12013431,
            ["GUID"] = "1E130986",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130986",
            },
        [12013432] = {
            ["Content"] = "魂兮游离，循时索归：山之阴，海之涯……",
            ["ContentJP"] = "魂よ、彷徨い歩け。時が満ちるそのときまで。山の影に、海の果て。彷徨い、そして還れ。",
            ["DialogueId"] = 12013432,
            ["GUID"] = "1E1309B0",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1309B0",
            },
        [12013433] = {
            ["Content"] = "谁？什么声音？",
            ["ContentJP"] = "誰……？今の声は……？",
            ["DialogueId"] = 12013433,
            ["GUID"] = "1E1309DA",
            ["NextDialogue"] = 12013434,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E1309DA",
            },
        [12013434] = {
            ["Content"] = "小仆从，别发呆了，打起精神来！",
            ["ContentJP"] = "ちょっと、我が下僕、何ボーっとしてるの？しゃきっとしてよ！",
            ["DialogueId"] = 12013434,
            ["GUID"] = "1E130A04",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A04",
            },
        [12013435] = {
            ["Content"] = "（白听不到刚才的声音……难道说，又是与诫碑那时相同的情况？）",
            ["ContentJP"] = "（スノウには聞こえてない……さっき戒律の碑の前にいた時と同じだ……）",
            ["DialogueId"] = 12013435,
            ["GUID"] = "1E130A2E",
            ["NextDialogue"] = 120134351,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A2E",
            },
        [12013436] = {
            ["Content"] = "魂兮游离，循时索归：盈亏月下，若木长青……",
            ["ContentJP"] = "彷徨いし魂。時の巡りに従いて。還る場所を求め行く。月、満ちては欠け、若木、変わらず青く茂る……",
            ["DialogueId"] = 12013436,
            ["GUID"] = "1E130A58",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A58",
            },
        [12013437] = {
            ["Content"] = "好啦，还差最后一片烛阴鳞就可以收工啦！",
            ["ContentJP"] = "よーしっ！ラスト一枚だねっ！",
            ["DialogueId"] = 12013437,
            ["GUID"] = "1E130A82",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A82",
            },
        [12013438] = {
            ["Content"] = "比星斗兮天阙，纳阴灵兮坟茔。孰离合兮可为，蹇谁留兮他乡？",
            ["ContentJP"] = "星より遠く、天の果てに比す。陰の魂は、墓所に静まりぬ。誰ぞめぐり逢い、異郷に留むるか？",
            ["DialogueId"] = 12013438,
            ["GUID"] = "1E130AAC",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130AAC",
            },
        [12013439] = {
            ["Camera"] = "234.427734,226.169922,38.391602,0.000054,8.448527,-130.795746,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "小仆从，你怎么自顾自地往这个方向走了？这里空荡荡的，什么都没有的样子……",
            ["ContentJP"] = "ちょっと、下僕！さっきから様子が変じゃない？心ここにあらずって感じがするんだけど？",
            ["DialogueId"] = 12013439,
            ["GUID"] = "1E130AD6",
            ["NextDialogue"] = 12013457,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130AD6",
            },
        [12013440] = {
            ["Content"] = "……小仆从，我相信你。这么难懂的语句，绝对不是随随便便就能想出来的。",
            ["ContentJP"] = "……うん、信じるよ。だってあんな難しい言い回し、テキトーに思いつけるわけないもん！",
            ["DialogueId"] = 12013440,
            ["GUID"] = "1E130B00",
            ["NextDialogue"] = 12013441,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130B00",
            },
        [12013441] = {
            ["Content"] = "但是，这个家伙选择和我们说话算是白费力气了，压根一个字都听不懂嘛。",
            ["ContentJP"] = "でもさぁ、相談する相手間違えてない？私に話したところでひとっこともわかんないよ！！",
            ["DialogueId"] = 12013441,
            ["GUID"] = "1E130B2A",
            ["NextDialogue"] = 12013442,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130B2A",
            },
        [12013442] = {
            ["Content"] = "——喂，想和我们说话的家伙，无论你是谁，希望你可以说得再直白一点！",
            ["ContentJP"] = "ちょっと――！！誰だか知らないけど、何か伝えたいんなら、もっとわかりやすい単語使いなさいよ！！",
            ["DialogueId"] = 12013442,
            ["GUID"] = "1E130B54",
            ["NextDialogue"] = 12013443,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130B54",
            },
        [12013443] = {
            ["Camera"] = "1502.039062,552.960938,672.550781,0.000055,22.248343,-38.19368,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12013443,
            ["FinalCamera"] = "1502.039062,552.960938,672.550781,0.000055,22.248343,-38.19368,11.88,100000.0,false,Manual,2.8",
            ["GUID"] = "1E130B7E",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130B7E",
            },
        [12013444] = {
            ["ContentJP"] = "……",
            ["DialogueId"] = 12013444,
            ["GUID"] = "1E130BA8",
            ["NextDialogue"] = 12013445,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130BA8",
            },
        [12013445] = {
            ["Content"] = "群玄啸鸣，灾愆降世……",
            ["ContentJP"] = "群玄吼え、災い、かくしてこの世に降り立つ。",
            ["DialogueId"] = 12013445,
            ["GUID"] = "1E130BD2",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130BD2",
            },
        [12013446] = {
            ["Camera"] = "234.427734,226.169922,38.391602,0.000054,8.448527,-130.795746,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "……！！",
            ["ContentJP"] = "……！！",
            ["DialogueId"] = 12013446,
            ["GUID"] = "1E130BFC",
            ["NextDialogue"] = 12013447,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130BFC",
            },
        [12013447] = {
            ["Content"] = "哇——我只是随便喊喊，没想到真的奏效了，不愧是本魔王大人！",
            ["ContentJP"] = "わっ――効いた！？さ、さっすが魔王様！言霊パワーもバッチリなんだから！",
            ["DialogueId"] = 12013447,
            ["GUID"] = "1E130C26",
            ["NextDialogue"] = 12013448,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130C26",
            },
        [12013448] = {
            ["Content"] = "小仆从，所以那个声音对你说了什么？",
            ["ContentJP"] = "で、今度はなんて言われたの？",
            ["DialogueId"] = 12013448,
            ["GUID"] = "1E130C50",
            ["NextDialogue"] = 12013449,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130C50",
            },
        [12013449] = {
            ["Content"] = "我不太确定……但是我好像看见了……很多玄色狴犴，在围攻……百年春。而且，我有一种预感，这是即将发生的事情……<W>是预言</>！",
            ["ContentJP"] = "はっきりとは言えないけど……でも、見えたんだ。無数の黒い<Default note=\"text:ゲンビー\">玄狴</>が――「<Default note=\"text:ももとき\">百年春</>」を襲ってる光景が。それはこれから起きることのような気がしてならない……そう、<W>予言</>のような！",
            ["DialogueId"] = 12013449,
            ["GUID"] = "1E130C7A",
            ["NextDialogue"] = 12013450,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130C7A",
            },
        [12013450] = {
            ["Content"] = "哎？！",
            ["ContentJP"] = "へっ？",
            ["DialogueId"] = 12013450,
            ["GUID"] = "1E130CA4",
            ["NextDialogue"] = 12013451,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CA4",
            },
        [12013451] = {
            ["Content"] = "白，情况紧急，我们先赶回百年春看看吧。希望我的预感不要应验……",
            ["ContentJP"] = "とにかく急いで戻ろう！ただの気のせいだといいけど……",
            ["DialogueId"] = 12013451,
            ["GUID"] = "1E130CCE",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CCE",
            },
        [12013452] = {
            ["Camera"] = "244.181824,388.453522,209.890625,0.000027,-17.815693,-123.119537,35.0,647.922363,false,DoNotOverride,22.0",
            ["Content"] = "看见眼前这些尘漠了吗？这便是尘漠石海变成现今样貌的罪魁祸首。",
            ["ContentJP"] = "目の前の塵砂が見えるかい？これは、塵砂の荒海が今のままになった元凶なんだ。",
            ["DialogueId"] = 12013452,
            ["FacialId"] = {
                [1] = "210014:CM_Sad01",
                },
            ["FinalCamera"] = "146.362381,214.138016,192.261719,0.000026,-18.815668,-124.320526,35.0,647.922363,false,DoNotOverride,22.0",
            ["GUID"] = "1E130CCF",
            ["NextDialogue"] = 12013453,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CCF",
            },
        [12013453] = {
            ["Content"] = "试试用牵机方枢吸收尘漠吧。",
            ["ContentJP"] = "さぁさぁ、機巧制御盤でも使って、塵砂を吸収しよか。",
            ["DialogueId"] = 12013453,
            ["GUID"] = "1E130CD0",
            ["SpeakNpcId"] = 210014,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CD0",
            },
        [12013454] = {
            ["Camera"] = "628.248047,360.278137,60.518555,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "悟性不错，孺子可教也!",
            ["ContentJP"] = "悪くないね。さすが{nickname}、見どころがある。",
            ["DialogueId"] = 12013454,
            ["FacialId"] = {
                [1] = "210014:CM_Smile01",
                },
            ["FinalCamera"] = "520.870728,315.92218,63.3125,0.000079,1.378428,-157.552795,60.000004,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E130CD1",
            ["NextDialogue"] = 12013455,
            ["SpeakNpcId"] = 210014,
            ["TalkActionId"] = {
                [1] = "210014:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CD1",
            },
        [12013455] = {
            ["Camera"] = "37.220299,11.483425,-280.212891,0.000085,30.816399,-128.115143,23.740538,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "既然如此，不如再来试试我这匠心打造的独家机枢机关吧！这其中的诀窍你能掌握吗？",
            ["ContentJP"] = "では、この特製の仕掛けを試してみな。念入りに作った一品だ。見抜けるかな？",
            ["DialogueId"] = 12013455,
            ["FinalCamera"] = "-140.37941,-214.903625,-200.674316,0.000085,30.816399,-128.115158,23.740538,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E130CD2",
            ["NextDialogue"] = 12013456,
            ["SpeakNpcId"] = 210014,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CD2",
            },
        [12013456] = {
            ["Content"] = "若能顺利解开这道机关，其中的宝箱便作为见面礼赠予你二人了。",
            ["ContentJP"] = "もしうまく解けたら、中の宝はお前たちへの贈り物としょう",
            ["DialogueId"] = 12013456,
            ["GUID"] = "1E130CD3",
            ["SpeakNpcId"] = 210014,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CD3",
            },
        [12013457] = {
            ["Content"] = "（白听不到刚才的声音……难道说，又是与诫碑那时相同的情况？）",
            ["ContentJP"] = "（スノウには聞こえてない……さっき戒律の碑の前にいた時と同じだ……）",
            ["DialogueId"] = 12013457,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E130AD7",
            ["NextOptions"] = {
                [1] = 120134391,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A2E",
            },
        [12013501] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "您二位终于出来了——奉我们家老板的命令，冯某已在此恭候多时了。",
            ["ContentJP"] = "ようやくお越しくださいましたか。旦那様の命令で、ずっとここでお待ちしておりました。",
            ["DialogueId"] = 12013501,
            ["FacialId"] = {
                [1] = "210010:Cin_Happy01",
                [2] = "100001:Unhappy01",
                [3] = "200002:Unhappy02",
                },
            ["GUID"] = "1E131502",
            ["LookAt"] = {
                [1] = "100001:n(210010)",
                [2] = "200002:n(210010)",
                },
            ["NextOptions"] = {
                [1] = 120135011,
                [2] = 120135012,
                },
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131502",
            },
        [12013504] = {
            ["Content"] = "哎，哎——贵客您别走啊！",
            ["ContentJP"] = "ちょ、ちょっとどこ行くんですか！？",
            ["DialogueId"] = 12013504,
            ["FacialId"] = {
                [1] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131580",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12013505,
            ["SpeakNpcId"] = 210010,
            ["TurnTo"] = {
                [1] = "100001:p(120)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131580",
            },
        [12013505] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "找我什么事？",
            ["ContentJP"] = "何か用？",
            ["DialogueId"] = 12013505,
            ["GUID"] = "1E1315AA",
            ["LookAt"] = {
                [1] = "200002:n(210010)",
                },
            ["NextDialogue"] = 12013506,
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"100001:n(210010)\"}},\
PlayAnimation{ActorId{100001},AnimationId{\"ConfidentLR_Start\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "100001:n(210010)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1315AA",
            },
        [12013506] = {
            ["Content"] = "白和小仆从的时间可是很宝贵的！只能给你一分钟……不对，三十秒的时间！",
            ["ContentJP"] = "スノウたちの時間は貴重なんだ！用があるなら1分……いや、30秒で言え！",
            ["DialogueId"] = 12013506,
            ["GUID"] = "1E1315D4",
            ["NextDialogue"] = 12013507,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1315D4",
            },
        [12013507] = {
            ["Content"] = "我们家老板看中了{nickname}的身手，想邀请二位共襄义举，参加一场围猎行动。",
            ["ContentJP"] = "実は、旦那様が{nickname}の腕前にいたく感心されましてな。ぜひお二人に、お力添えを願いたいとのこと。ある討伐作戦に、ご同行いただけませんか。",
            ["DialogueId"] = 12013507,
            ["GUID"] = "1E1315FE",
            ["NextDialogue"] = 120135070,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1315FE",
            },
        [12013509] = {
            ["Content"] = "我们很熟吗？",
            ["ContentJP"] = "そこまで親しい間柄じゃないと思うけど？",
            ["DialogueId"] = 12013509,
            ["GUID"] = "1E131652",
            ["NextDialogue"] = 12013510,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToTalkL_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131652",
            },
        [12013510] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "您这话说的，这不是不打不相识吗？在冯某看来，已经和两位一见如故，简直是多年故交了！",
            ["ContentJP"] = "いやいや、そうおっしゃらずに。ほら、昔から「喧嘩するほど仲がいい」とも言いますし――俺から見れば、もうあなた方とは旧知の仲も同然！いや、意気投合ってやつですよ！",
            ["DialogueId"] = 12013510,
            ["FacialId"] = {
                [1] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E13167C",
            ["LookAt"] = {
                [1] = "210010:n(100001)",
                },
            ["NextDialogue"] = 12013511,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToTalkL_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13167C",
            },
        [12013511] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12013511,
            ["GUID"] = "1E1316A6",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12013512,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210010:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1316A6",
            },
        [12013512] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12013512,
            ["GUID"] = "1E1316D0",
            ["NextDialogue"] = 12013513,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1316D0",
            },
        [12013513] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了好了。俗话说得好，无恒久之友，亦无恒久之敌。这天下熙熙，皆为利来利往。只有利益永流转呀——",
            ["ContentJP"] = "まあまあ、そう固いこと言わずに。昔からこう言うでしょう？「永遠の味方もなければ、永遠の敵もなし」って。この世は所詮、利で集まり利で散る――結局のところ、巡るのは利益だけなんですよ。",
            ["DialogueId"] = 12013513,
            ["GUID"] = "1E1316FA",
            ["LookAt"] = {
                [1] = "100001:n(210010)",
                [2] = "200002:n(210010)",
                },
            ["NextDialogue"] = 12013514,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1316FA",
            },
        [12013514] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "听你话里的意思，你能拿出让我心动的报酬？",
            ["ContentJP"] = "……へぇ、つまり{性别:僕|私}が乗るほどの報酬を出すってこと？",
            ["DialogueId"] = 12013514,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131724",
            ["NextDialogue"] = 12013515,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToTalk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131724",
            },
        [12013515] = {
            ["Camera"] = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
            ["Content"] = "钱自不用说。我们家老板一向出手慷慨。",
            ["ContentJP"] = "金のことならご心配なく。旦那様は昔から気前の良さでは評判でしてな。",
            ["DialogueId"] = 12013515,
            ["FacialId"] = {
                [1] = "200002:Curious",
                },
            ["GUID"] = "1E13174E",
            ["NextDialogue"] = 12013516,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13174E",
            },
        [12013516] = {
            ["Content"] = "还有一项报酬，想必是合您心意的……",
            ["ContentJP"] = "それにもう一つ、きっとお気に召すであろう報酬がございます……",
            ["DialogueId"] = 12013516,
            ["GUID"] = "1E131778",
            ["NextDialogue"] = 12013517,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131778",
            },
        [12013517] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "说来听听。",
            ["ContentJP"] = "言ってみて。",
            ["DialogueId"] = 12013517,
            ["FacialId"] = {
                [1] = "100001:Think01",
                [2] = "200002:Smile01",
                },
            ["GUID"] = "1E1317A2",
            ["NextDialogue"] = 12013518,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1317A2",
            },
        [12013518] = {
            ["Content"] = "您或许不知，我们家老板的生意足迹遍布世界各地，与海伯利亚帝国也有盘根错节的联系……您可曾听说过格林威治考古协会？",
            ["ContentJP"] = "ご存じないかもしれませんが、うちのの商いは世界各地に広がっております……ヒュペリア帝国とも、なかなかに根深い繋がりがあるんですよ。――グリニッジ考古協会という名を聞いたことは？",
            ["DialogueId"] = 12013518,
            ["GUID"] = "1E1317CC",
            ["NextDialogue"] = 12013519,
            ["RelatedWikiId"] = {
                [1] = 406005,
                },
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "200002:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1317CC",
            },
        [12013519] = {
            ["Camera"] = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
            ["Content"] = "哇，我听卡米拉讲过！那是一个号称要让古迹重见天日的组织，很有名的！",
            ["ContentJP"] = "わあっ、それ聞いたことある！カミラが話してたよ！古代遺跡をもう一度世に出すんだっていう、有名な団体だって！",
            ["DialogueId"] = 12013519,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "1E1317F6",
            ["NextDialogue"] = 12013520,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1317F6",
            },
        [12013520] = {
            ["Camera"] = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
            ["Content"] = "呵呵，我家老板就是它背后的投资人之一。",
            ["ContentJP"] = "ふふ、うちの旦那様は――その協会を裏で支えている投資家のひとりなんですよ。",
            ["DialogueId"] = 12013520,
            ["FacialId"] = {
                [1] = "210010:Cin_Happy01",
                },
            ["GUID"] = "1E131820",
            ["NextDialogue"] = 12013521,
            ["RelatedWikiId"] = {
                [1] = 203005,
                },
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131820",
            },
        [12013521] = {
            ["Camera"] = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,50.0,374.245361,false,DoNotOverride,2.8",
            ["Content"] = "哎？！传闻中从不露面的格林威治考古协会幕后金主……竟然就藏在华胥！",
            ["ContentJP"] = "ええっ！？あの誰も姿を見たことがない噂のグリニッジ考古協会の黒幕が……まさか<Default note=\"text:カショ\">華胥</>にいたなんて！",
            ["DialogueId"] = 12013521,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-105.901047,-11.516113,305.875977,0.000081,-16.399591,37.201481,60,374.245361,false,DoNotOverride,2.8",
            ["GUID"] = "1E13184A",
            ["NextDialogue"] = 12013522,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13184A",
            },
        [12013522] = {
            ["Camera"] = "49.970024,127.262115,278.185547,0.000111,-6.199612,60.402637,35.0,190.711807,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，您在找某位失散的朋友，对吧？",
            ["ContentJP"] = "{nickname}様、ある行方知らずのご友人を探しているとか。違いましたかな？",
            ["DialogueId"] = 12013522,
            ["GUID"] = "1E131874",
            ["NextDialogue"] = 12013523,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_End",
                [2] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131874",
            },
        [12013523] = {
            ["Camera"] = "34.974609,-135.861816,425.904297,0.000123,-26.199484,77.799515,35.0,491.753998,false,DoNotOverride,2.8",
            ["Content"] = "……你怎么知道的？",
            ["ContentJP"] = "……なぜそれを？",
            ["DialogueId"] = 12013523,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                },
            ["GUID"] = "1E13189E",
            ["NextDialogue"] = 12013524,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock04_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13189E",
            },
        [12013524] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我如何知道这件事不要紧。要紧的是，考古协会提供的情报和人脉，在日后某一天说不定就能成为您达成心愿的助力。",
            ["ContentJP"] = "原因はさておき、大事なのは――いずれその願いを叶える日に、考古協会が持つ情報と人脈が、きっとあなたの力になるかもしれないということです。",
            ["DialogueId"] = 12013524,
            ["GUID"] = "1E1318C8",
            ["NextDialogue"] = 120135070,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Shock04_End",
                [2] = "210010:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1318C8",
            },
        [12013526] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "人们总是对我们黑市中人有些偏见，冯某十分理解。",
            ["ContentJP"] = "闇市の者はどうしたって偏見を持たれがちです。気持ちはわかりますよ。",
            ["DialogueId"] = 12013526,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "210010:CM_Idle",
                },
            ["GUID"] = "1E13191C",
            ["NextDialogue"] = 12013528,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13191C",
            },
        [12013528] = {
            ["Content"] = "但就算是我们，也会有一颗保卫家园的拳拳之心，偶尔想做些为民除害的好事！",
            ["ContentJP"] = "ですが、我々とて故郷を想う気持ちは同じです。たまには世のため人のため、悪を討とうと思うこともあるのですよ！",
            ["DialogueId"] = 12013528,
            ["GUID"] = "1E131970",
            ["NextDialogue"] = 12013529,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131970",
            },
        [12013529] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……听起来更可疑了。",
            ["ContentJP"] = "……余計怪しいよ。",
            ["DialogueId"] = 12013529,
            ["FacialId"] = {
                [1] = "100001:Think01",
                [2] = "200002:Doubt01",
                },
            ["GUID"] = "1E13199A",
            ["NextDialogue"] = 12013530,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E13199A",
            },
        [12013530] = {
            ["Camera"] = "236.166168,300.864075,264.609375,0.000073,0.600435,-149.201889,35.000008,370.433502,false,DoNotOverride,2.8",
            ["Content"] = "况且，这行动是止流掌柜嘱托给我们老板的，也是化解烛阴之灾布局的一子呢。",
            ["ContentJP"] = "それに今回の行動は、シリュウさんから旦那様に託されたものでもありましてな。<Default note=\"text:しょくいん\">燭陰</>の禍を収めるための、大事な一手でもあるのです。",
            ["DialogueId"] = 12013530,
            ["GUID"] = "1E1319C4",
            ["NextDialogue"] = 12013531,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1319C4",
            },
        [12013531] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……止流的委托？好吧。“猎物”是什么？",
            ["ContentJP"] = "シリュウさんが？わかったよ。で、「獲物」は？",
            ["DialogueId"] = 12013531,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E1319EE",
            ["NextDialogue"] = 12013532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E1319EE",
            },
        [12013532] = {
            ["Content"] = "这个冯某暂时无法透露，您可以视为玄色狴犴的同类。",
            ["ContentJP"] = "それについては、今はまだ申し上げられませんが……ひとまずは、<Default note=\"text:ゲンビー\">玄狴</>と「同じ類」とお考えいただければ。",
            ["DialogueId"] = 12013532,
            ["FacialId"] = {
                [1] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131A18",
            ["NextDialogue"] = 12013533,
            ["SpeakNpcId"] = 210010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A18",
            },
        [12013533] = {
            ["Content"] = "等您看到了再决定也不迟。毕竟，您随时有退出的权利。",
            ["ContentJP"] = "いざ目にしてから判断されても、遅くはありませんよ。あなたちには、手を引く権利があるのですから。",
            ["DialogueId"] = 12013533,
            ["GUID"] = "1E131A42",
            ["NextDialogue"] = 120135070,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A42",
            },
        [12013534] = {
            ["Camera"] = "-70.775307,-50.397655,304.739258,0.000104,-11.399626,52.60202,35.0,383.266479,false,DoNotOverride,2.8",
            ["Content"] = "……我先跟你们去看看吧。",
            ["ContentJP"] = "……ひとまず、ついて行ってみるよ。",
            ["DialogueId"] = 12013534,
            ["GUID"] = "1E131A6C",
            ["NextDialogue"] = 12013535,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                [2] = "210010:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A6C",
            },
        [12013535] = {
            ["Camera"] = "779.264404,211.306061,366.683594,0.000056,-11.199543,179.402878,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就好，不枉冯某费这一番口舌！",
            ["ContentJP"] = "ありがたい！長々と話した甲斐がありましたな！",
            ["DialogueId"] = 12013535,
            ["FacialId"] = {
                [1] = "210010:Cin_Happy01",
                },
            ["GUID"] = "1E131A96",
            ["NextDialogue"] = 12013536,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                [2] = "210010:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131A96",
            },
        [12013536] = {
            ["Content"] = "待您有空时，去沉船内找我们老板就好。等您来了，万事俱备，我们再开始！",
            ["ContentJP"] = "お時間が取れましたら、沈没船の中にいらっしゃる旦那様をお訪ねください。あなたが来てくれれば、すべて準備が整います。そうしたら作戦を始めましょう。",
            ["DialogueId"] = 12013536,
            ["GUID"] = "1E131AC0",
            ["NextDialogue"] = 12013537,
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131AC0",
            },
        [12013537] = {
            ["Content"] = "那冯某就先告退啦。",
            ["ContentJP"] = "では、俺はこれで。",
            ["DialogueId"] = 12013537,
            ["FacialId"] = {
                [1] = "210010:Cin_Smile01",
                },
            ["GUID"] = "1E131AEA",
            ["SpeakNpcId"] = 210010,
            ["TalkActionId"] = {
                [1] = "210010:Salute_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120135/1E131AEA",
            },
        [12013601] = {
            ["Camera"] = "-130.490814,92.101395,310.104492,0.000114,-12.999571,27.802591,35.000008,190.711807,false,DoNotOverride,2.8",
            ["Content"] = "希望他们这次不要再有什么坏心思……",
            ["ContentJP"] = "今度こそ、ヘンな企みをしてないといいけど……",
            ["DialogueId"] = 12013601,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "1E13256A",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12013602,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
