            ["GUID"] = "1E1335D2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120137/1E1335D2",
            },
        [12013702] = {
            ["Content"] = "不知道扶疏和那个被狴犴打伤的女孩子有没有好些。",
            ["ContentJP"] = "フーシュさんとあの女の子、少しは良くなってるといいけど。",
            ["DialogueId"] = 12013702,
