            ["Duration"] = 3,
            ["GUID"] = "1E1356A2",
            ["NextDialogue"] = 12013902,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120139/1E1356A2",
            },
        [12013902] = {
            ["Content"] = "就好像……完全没有人居住一样。",
            ["ContentJP"] = "まるで……最初から誰も住んでなかったみたい。",
            ["DialogueId"] = 12013902,
            ["Duration"] = 2,
