},\
PlayAnimation{_delay{5.01},ActorId{100001},AnimationId{\"Please01_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{210013},AnimationId{\"Baiheng_Story_Special03_Start\"},Duration{1}},\
LookAt{_delay{14.01},LookAtDescription{\"100001:p(BP_FixSimple_37_nvzhu04)\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E1368D8",
            },
        [12014013] = {
            ["Camera"] = "-3558.072266,-1192.942871,267.723633,0.000177,19.579582,18.021456,25.0,100000.0,false,Manual,2.8",
            ["Content"] = "想到她可能在某处遭遇着危险，或许还会因此受伤，我就会难过得睡不着觉。",
            ["ContentJP"] = "彼女がどこかで危ない目に遭ってるかもしれない、もしかしたら傷ついてるかもしれないって思うと……心配で、悲しくて、眠れなく{性别:なるんだ|なる}。",
            ["DialogueId"] = 12014013,
            ["FinalCamera"] = "-3558.072266,-1192.942871,267.723633,0.00018,25.379478,14.420898,25.0,100000.0,false,Manual,2.8",
