            ["VoiceName"] = "voice/$Locale$/story/1201/120140/1E136980",
            },
        [12014017] = {
            ["Camera"] = "-333.198242,-92.549561,186.976562,0.000109,-17.397945,13.034511,40.000011,340.723328,false,Manual,8.0",
            ["Content"] = "这样才对嘛！小仆从，没想到你的口才这么好，不愧是本魔王最得力的跟班！",
            ["ContentJP"] = "そうそう、そうこなくっちゃ！あんなに上手に言えるなんてびっくり〜！さっすがこの魔王さまの一番の下僕だねっ！",
            ["DialogueId"] = 12014017,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["FinalCamera"] = "-335.535034,-82.232544,186.976562,0.000107,-17.197903,11.034736,40.000011,340.337952,false,Manual,8.0",
