            },
        [12015525] = {
            ["Camera"] = "-171.576187,16.046459,219.450195,0.000053,-24.99765,-0.400124,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们专程来这里一趟，恐怕不是来叙旧的吧？",
            ["ContentJP"] = "まさか、昔話をしに来たわけではあるまいな？",
            ["DialogueId"] = 12015525,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["FinalCamera"] = "-237.973511,24.827023,258.312012,0.000038,-26.797733,2.000224,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E146112",
            ["LookAt"] = {
                [1] = "200002:n(210040)",
                [2] = "100001:n(210040)",
                [3] = "210013:n(210040)",
                },
            ["NextDialogue"] = 12015526,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["ToFinalCameraBlendTime"] = 15,
            ["TurnTo"] = {
                [1] = "200002:n(210040)",
                [2] = "100001:n(210040)",
                [3] = "210013:n(210040)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E146112",
            },
        [12015526] = {
            ["Content"] = "嗯……我们是来寻找一种古籍上称为“忘忧草”的植物。您知道它们可能分布在何处吗？",
            ["ContentJP"] = "ええ……古書に記された「忘れ草」という植物を探しに参ったのです。どこに生えているか、ご存じでしょうか？",
            ["DialogueId"] = 12015526,
            ["GUID"] = "1E14613C",
            ["NextDialogue"] = 12015527,
            ["SpeakNpcId"] = 210013,
            ["TalkActionId"] = {
                [1] = "210013:Shy03_Start",
                [2] = "100001:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E14613C",
            },
        [12015527] = {
            ["Camera"] = "784.648315,1688.77478,793.957031,0.000106,-20.798943,-107.790878,30.000013,212.18367,false,DoNotOverride,11.418732",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "呵呵，忘忧草啊……我年轻时，这种植物还长得漫山遍野都是。现在只有后山瀑布处才能零星看见它们生长了。",
            ["ContentJP"] = "ふふ、忘れ草とな……若い頃は、この植物が山の至るところに咲き誇っておったものじゃ。今では、裏山の滝のあたりで、まばらにしか見られんようになってしもうたがのう。",
            ["DialogueId"] = 12015527,
            ["FinalCamera"] = "784.648315,1688.77478,793.957031,0.000117,-5.398848,-81.190453,30.000013,212.18367,false,DoNotOverride,11.418732",
            ["GUID"] = "1E146166",
            ["NextDialogue"] = 12015528,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "210013:Shy03_End",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E146166",
            },
        [12015528] = {
            ["Camera"] = "97.456741,233.233795,41.130371,0.000063,8.802215,-50.793129,35.000008,224.867065,false,Manual,6.960648",
            ["Content"] = "后山瀑布……我明白了，感谢您提供的信息。",
            ["ContentJP"] = "裏山の滝、ですか……わかりました。貴重な情報をありがとうございます。",
            ["DialogueId"] = 12015528,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["FinalCamera"] = "92.520905,229.20755,41.130371,0.000063,8.802215,-50.793156,35.000008,224.867065,false,Manual,6.960648",
            ["GUID"] = "1E146190",
            ["NextDialogue"] = 12015529,
            ["Scripts"] = "PARA{\
