        [12015529] = {
            ["Camera"] = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "对了，如果你们是往那个方向走，可以帮我留神一件事吗？",
            ["ContentJP"] = "そうじゃ、もしその方向へ行くのなら、ひとつ頼みごとを聞いてくれんかのう？",
            ["DialogueId"] = 12015529,
            ["FinalCamera"] = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E1461BA",
            ["NextDialogue"] = 12015530,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "210013:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E1461BA",
            },
        [12015530] = {
            ["Content"] = "您说。",
            ["ContentJP"] = "もちろんです。",
            ["DialogueId"] = 12015530,
            ["GUID"] = "1E1461E4",
            ["LookAt"] = {
                [1] = "100001:n(210040)",
                },
            ["NextDialogue"] = 12015531,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E1461E4",
            },
        [12015531] = {
            ["Camera"] = "506.800385,633.872742,77.709961,0.000065,0.602477,-123.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们来前不久，尘漠灾害波及了虞泉。有无由生失踪了。它们最后的活动范围就在瀑布附近。",
            ["ContentJP"] = "お主たちが来る前のことじゃが、塵砂の災いが虞泉まで及んだのじゃ。ムユウセイが何匹か姿を消しておる。最後に見られたのは滝の周辺じゃった。",
            ["DialogueId"] = 12015531,
            ["FinalCamera"] = "543.195251,689.077759,77.014893,0.000065,0.60247,-123.397171,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E14620E",
            ["NextDialogue"] = 12015532,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E14620E",
            },
        [12015532] = {
            ["Camera"] = "81.046371,94.984283,109.258301,0.000053,-23.95587,34.01368,45.000011,118.771225,false,Manual,8.928488",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "若你们看到它们受困，还请施以援手……那边的小无由生为此可是日夜痛哭不已唷。",
            ["ContentJP"] = "もし困っているムユウセイを見かけたら、どうか助けてくれんかのう……あそこらのムユウセイたちは、昼夜そのことで泣いておるのじゃよ。",
            ["DialogueId"] = 12015532,
            ["FinalCamera"] = "81.046371,94.984283,109.258301,0.000052,-25.15588,33.813671,45.000011,118.771225,false,Manual,8.928488",
            ["GUID"] = "1E146238",
            ["NextDialogue"] = 12015533,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E146238",
            },
        [12015533] = {
            ["Content"] = "我会留意的。",
            ["ContentJP"] = "覚えておきます。",
            ["DialogueId"] = 12015533,
            ["GUID"] = "1E146262",
            ["NextDialogue"] = 12015534,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "100001:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E146262",
            },
        [12015534] = {
            ["Camera"] = "121.226036,125.787674,88.543091,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
            ["Content"] = "哈哈，快上路吧。生者的时间可是很宝贵的。",
            ["ContentJP"] = "はっはっは、さあ早く行きなされ。生者の時間は、何よりも貴重なのじゃからのう。",
            ["DialogueId"] = 12015534,
            ["FinalCamera"] = "146.449402,146.941391,76.819092,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
            ["GUID"] = "1E14628C",
            ["NextDialogue"] = 12015535,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E14628C",
            },
        [12015535] = {
            ["Camera"] = "1428.752563,1073.151489,38.327271,0.000178,-0.197604,-141.396988,30.000002,1974.44458,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "待你们百年之后，再回来这里畅谈也不迟。老骨头我有耐心，等得起呐。",
            ["ContentJP"] = "死後にでも、またここへ戻り、ゆっくり語り合うのも悪くはない。老骨ゆえ、いくらでも待てよう。",
            ["DialogueId"] = 12015535,
            ["FinalCamera"] = "1560.888916,1093.783447,38.735229,0.000178,-0.197604,-144.99707,30.000002,1974.44458,false,Manual,1.2",
            ["GUID"] = "1E1462B6",
            ["NextDialogue"] = 12015536,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210018,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E1462B6",
            },
        [12015536] = {
            ["Camera"] = "203.142548,172.754639,84.036987,0.000236,-41.194706,-124.995682,30.000013,127.563431,false,Manual,8.594169",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……明明知道他说的没错，但是莫名有一种背后发寒的感觉怎么回事！",
            ["ContentJP"] = "……なんだろう。普通のことを言ってるだけなのに、めちゃくちゃゾッとするんだけど！？",
            ["DialogueId"] = 12015536,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "215.009399,189.70047,102.144897,0.000229,-41.194721,-124.995827,30.000013,163.501831,false,Manual,8.594169",
            ["GUID"] = "1E1462E0",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(200002)",
                },
            ["NextDialogue"] = 12015537,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(200002)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E1462E0",
            },
        [12015537] = {
            ["Content"] = "小仆从，我们快走吧……！",
            ["ContentJP"] = "我が下僕、行くよ！",
            ["DialogueId"] = 12015537,
            ["GUID"] = "1E14630A",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shy01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120155/1E14630A",
            },
        [12015601] = {
            ["Camera"] = "77.056641,185.4375,189.325562,0.000108,-31.7983,-71.775475,35.000011,290.254242,false,Manual,6.747885",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "茎紫红色，叶对生，花小而白……看来便是这株植物了。",
            ["ContentJP"] = "茎は紫紅色で、葉は対生、花は小さく白い……どうやら、この植物で間違いなさそうです。",
            ["DialogueId"] = 12015601,
            ["FinalCamera"] = "63.588379,226.34082,216.024658,0.000108,-31.798326,-71.775505,35.000011,290.254242,false,Manual,6.747885",
