            },
        [12015701] = {
            ["Content"] = "喂——小仆从，你快过来看看！",
            ["ContentJP"] = "ちょっと、我が下僕、こっち来て！！",
            ["DialogueId"] = 12015701,
            ["Duration"] = 3,
            ["GUID"] = "1E147DF2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120157/1E147DF2",
            },
        [12015801] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……难道是白幻听了吗？小仆从，你来帮我确认一下，是不是有什么声音从这边传过来？",
            ["ContentJP"] = "……何か聞こえない？我が下僕よ、代わりに確かめてみて！まさか、スノウの幻聴じゃないよね！？",
            ["DialogueId"] = 12015801,
            ["GUID"] = "1E148E5A",
            ["NextDialogue"] = 12015802,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148E5A",
            },
        [12015802] = {
            ["Content"] = "好。",
            ["ContentJP"] = "了解。",
            ["DialogueId"] = 12015802,
            ["GUID"] = "1E148E84",
            ["NextDialogue"] = 12015803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148E84",
            },
        [12015803] = {
            ["Content"] = "……救救……救救……",
            ["ContentJP"] = "……た……けて……たす……",
            ["DialogueId"] = 12015803,
            ["GUID"] = "1E148EAE",
            ["NextDialogue"] = 12015804,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210028,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148EAE",
            },
        [12015804] = {
            ["Content"] = "是有什么人在说话，那个人好像在向路过的人求助。",
            ["ContentJP"] = "確かに……誰かが助けを求めるような声がする。",
            ["DialogueId"] = 12015804,
            ["GUID"] = "1E148ED8",
            ["NextDialogue"] = 12015805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148ED8",
            },
        [12015805] = {
            ["Content"] = "那人在喊……“舅舅”？她也是在找自己的亲人吗？",
            ["ContentJP"] = "た…け？タケノコ？お腹空いてんのかねぇ？",
            ["DialogueId"] = 12015805,
            ["GUID"] = "1E148F02",
            ["NextDialogue"] = 12015806,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F02",
            },
        [12015806] = {
            ["Content"] = "不能消失……我还有……",
            ["ContentJP"] = "消えたくない……まだ……",
            ["DialogueId"] = 12015806,
            ["GUID"] = "1E148F2C",
            ["NextDialogue"] = 12015807,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210028,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F2C",
            },
        [12015807] = {
            ["Content"] = "在……之前……请让我……",
            ["ContentJP"] = "どうか……会わせて……",
            ["DialogueId"] = 12015807,
            ["GUID"] = "1E148F56",
            ["NextDialogue"] = 12015808,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210028,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F56",
            },
        [12015808] = {
            ["Content"] = "对吧对吧，白没有听错！就是说嘛，本魔王的听力，连水仙平原最细微角落的悄悄话都能听得一清二楚！",
            ["ContentJP"] = "やっぱり！幻聴じゃなかったでしょ！まぁ、この魔王様にかかれば、アスフォデロスのどこで内緒話をしたって、全部聞こえちゃうんだから！",
            ["DialogueId"] = 12015808,
            ["GUID"] = "1E148F80",
            ["NextDialogue"] = 12015809,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148F80",
            },
        [12015809] = {
            ["Content"] = "明白了，下次有什么不能带你商量的事，一定让你走远点。",
            ["ContentJP"] = "そうなんだ。じゃあ次はなるべく君から離れたとこで話すことにするよ。",
            ["DialogueId"] = 12015809,
            ["GUID"] = "1E148FAA",
            ["NextDialogue"] = 12015810,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148FAA",
            },
        [12015810] = {
            ["Content"] = "喂，太过分了！！",
            ["ContentJP"] = "ちょっと！！",
            ["DialogueId"] = 12015810,
            ["GUID"] = "1E148FD4",
            ["NextDialogue"] = 12015811,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148FD4",
            },
        [12015811] = {
            ["Content"] = "……话说回来，这个声音的主人在哪里，我们又该怎么找到它呢？",
            ["ContentJP"] = "ところで……声の主はどこにいるんだろ？",
            ["DialogueId"] = 12015811,
            ["GUID"] = "1E148FFE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120158/1E148FFE",
            },
        [12015901] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "小仆从，刚刚什么动静？",
            ["ContentJP"] = "な、なんだなんだ！？",
            ["DialogueId"] = 12015901,
            ["GUID"] = "1E149EC2",
            ["NextDialogue"] = 12015902,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149EC2",
            },
        [12015902] = {
            ["Content"] = "小仆从，小仆从？……{nickname}？！",
            ["ContentJP"] = "ち、ちょっと、下僕？……{nickname}！！",
            ["DialogueId"] = 12015902,
            ["GUID"] = "1E149EEC",
            ["NextDialogue"] = 12015903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149EEC",
            },
        [12015903] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你、你怎么不说话呀……",
            ["ContentJP"] = "な、なんでなんにも言わないの！？",
            ["DialogueId"] = 12015903,
            ["GUID"] = "1E149F16",
            ["NextDialogue"] = 12015904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F16",
            },
        [12015904] = {
            ["Content"] = "怎么办！扶疏，扶疏，大事不好啦——",
            ["ContentJP"] = "ど、どうしよう！！フーシュ！！大変だ――！！",
            ["DialogueId"] = 12015904,
            ["GUID"] = "1E149F40",
            ["NextDialogue"] = 12015905,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F40",
            },
        [12015905] = {
            ["Content"] = "发生了什么？",
            ["ContentJP"] = "どうされました？",
            ["DialogueId"] = 12015905,
            ["GUID"] = "1E149F6A",
            ["NextDialogue"] = 12015906,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F6A",
            },
        [12015906] = {
            ["Content"] = "呜哇……刚刚有什么人在看不见的地方说话，我和小仆从准备去找找看，可是刚刚突然有一道光闪过，“滋溜”一声，小仆从就变成了这个呆呆的样子！",
            ["ContentJP"] = "うわあぁーん！さっき何か声が聞こえたから、見に行ったら、突然何か光みたいなものが通って、「シュッ」って……それで、我が下僕がこんな風になっちゃったんだぁ！！",
            ["DialogueId"] = 12015906,
            ["GUID"] = "1E149F94",
            ["NextDialogue"] = 12015907,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149F94",
            },
        [12015907] = {
            ["Content"] = "怎么喊都不答应……就像是灵魂被抽走了一样！",
            ["ContentJP"] = "何を言っても答えてくれないのぉ……まるで魂抜かれたみたいになっちゃったよぉ！！",
            ["DialogueId"] = 12015907,
            ["GUID"] = "1E149FBE",
            ["NextDialogue"] = 12015908,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149FBE",
            },
        [12015908] = {
            ["Content"] = "小白，你先镇定下来，焦急于情势无补。安心，有我在。",
            ["ContentJP"] = "スノウさん、落ち着いてください。焦っても何も解決しませんよ。ゆっくり話してください。",
            ["DialogueId"] = 12015908,
            ["GUID"] = "1E149FE8",
            ["NextDialogue"] = 12015910,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E149FE8",
            },
        [12015910] = {
            ["Content"] = "你是说……你最后一次看到正常的{nickname}，是在这里吗？",
            ["ContentJP"] = "つまり、最後に正常な{nickname}を見たのが、ここだったと？",
            ["DialogueId"] = 12015910,
            ["GUID"] = "1E14A03C",
            ["NextDialogue"] = 12015912,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A03C",
            },
        [12015912] = {
            ["Content"] = "这是什么？{nickname}该不会有危险吧？！",
            ["ContentJP"] = "何これ！？まさか{nickname}に何かあったんじゃ！？",
            ["DialogueId"] = 12015912,
            ["GUID"] = "1E14A090",
            ["NextDialogue"] = 12015913,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A090",
            },
        [12015913] = {
            ["Content"] = "如果我没有猜错，{性别：他|她}的精神被<H>往隙</>吞噬了。",
            ["ContentJP"] = "おそらく……{性别:彼|彼女}の精神が<H>「裂け目」</>に呑まれてしまったのでしょう。",
            ["DialogueId"] = 12015913,
            ["GUID"] = "1E14A0BA",
            ["NextDialogue"] = 12015914,
            ["RelatedWikiId"] = {
                [1] = 304008,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A0BA",
            },
        [12015914] = {
            ["Content"] = "往隙……那是什么？听你的语气好像很不妙！",
            ["ContentJP"] = "裂け目……？なにそれ！？すごくヤバそうなんだけど！？",
            ["DialogueId"] = 12015914,
            ["GUID"] = "1E14A0E4",
            ["NextDialogue"] = 12015915,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A0E4",
            },
        [12015915] = {
            ["Content"] = "倘若虞泉是由人的执念交织形成的彼界……那么虞泉受烛阴之灾影响，便生出往隙——令一切忘却消弭的无光之地。",
            ["ContentJP"] = "もし虞泉が、人の執念が幾重にも絡み合って生まれた「彼方の界」だとすれば……そこが<Default note=\"text:しょくいん\">燭陰</>の禍に侵されたことで生まれたのが「裂け目」――すべてを忘却させ、跡形もなく消し去る、光なき虚無の領域です。",
            ["DialogueId"] = 12015915,
            ["GUID"] = "1E14A10E",
            ["NextDialogue"] = 12015916,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A10E",
            },
        [12015916] = {
            ["Content"] = "失足坠入的行者，若是没有在往隙生成后的一个时辰内及时返回，其魂魄就会永久迷失在其中，不得归途。",
            ["ContentJP"] = "足を滑らせた者は、「裂け目」が生じてから二時間以内に戻らねば、魂は永久にその中を彷徨い、二度と還ることはできません。",
            ["DialogueId"] = 12015916,
            ["GUID"] = "1E14A138",
            ["NextDialogue"] = 12015917,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A138",
            },
        [12015917] = {
            ["Content"] = "那……",
            ["ContentJP"] = "そん……",
            ["DialogueId"] = 12015917,
            ["GUID"] = "1E14A162",
            ["NextDialogue"] = 12015918,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A162",
            },
        [12015918] = {
            ["Content"] = "不用心慌，我现在去带{性别：他|她}回来。你在原地等着我们。",
            ["ContentJP"] = "慌てなくて大丈夫です。今から私が、{性别:彼|彼女}を連れ戻して来ますから。――あなたは、ここで待っていてください。",
            ["DialogueId"] = 12015918,
            ["GUID"] = "1E14A18C",
            ["NextDialogue"] = 12015919,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A18C",
            },
        [12015919] = {
            ["Content"] = "……白也要跟着一起去！",
            ["ContentJP"] = "……スノウも一緒に行く！！",
            ["DialogueId"] = 12015919,
            ["GUID"] = "1E14A1B6",
            ["NextDialogue"] = 12015920,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A1B6",
            },
        [12015920] = {
            ["Content"] = "不行，往隙凶险异常。若是连你也陷于其中，事态只会更加失控。",
            ["ContentJP"] = "いけません。「裂け目」は非常に危険な場所です。あなたまで呑まれてしまえば、取り返しのつかないことになってしまいます。",
            ["DialogueId"] = 12015920,
            ["GUID"] = "1E14A1E0",
            ["NextDialogue"] = 12015921,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A1E0",
            },
        [12015921] = {
            ["Content"] = "但、但是，白只能在这里干等着，什么事情都做不了，也不知道里面是什么情况，小仆从到底怎么样了……",
            ["ContentJP"] = "で、でも……スノウ、ただ待つだけなんてイヤだ……何もできないし、中がどうなってるかもわからないし、下僕が無事なのかも……！",
            ["DialogueId"] = 12015921,
            ["GUID"] = "1E14A20A",
            ["NextDialogue"] = 12015922,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A20A",
            },
        [12015922] = {
            ["Content"] = "呜，这种感觉……太难受了……",
            ["ContentJP"] = "そんなの……耐えられない……",
            ["DialogueId"] = 12015922,
            ["GUID"] = "1E14A234",
            ["NextDialogue"] = 12015923,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A234",
            },
        [12015923] = {
            ["Content"] = "小白，来，手给我。",
            ["ContentJP"] = "……スノウさん、手を。",
            ["DialogueId"] = 12015923,
            ["GUID"] = "1E14A25E",
            ["NextDialogue"] = 12015924,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A25E",
            },
        [12015924] = {
            ["Content"] = "这……这是……",
            ["ContentJP"] = "ん、これは……？",
            ["DialogueId"] = 12015924,
            ["GUID"] = "1E14A288",
            ["NextDialogue"] = 12015925,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A288",
            },
        [12015925] = {
            ["Content"] = "家姐说过，药苦的话，吃枚蜜饯就会甜起来。我想，心里苦也是一样的。",
            ["ContentJP"] = "姉が言っていました。「薬苦けれど、蜜餞ひとつで甘きに転ず」と。きっと、「悲しい気持ち」も……それと同じなのかもしれませんね。",
            ["DialogueId"] = 12015925,
            ["GUID"] = "1E14A2B2",
            ["NextDialogue"] = 12015926,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A2B2",
            },
        [12015926] = {
            ["Content"] = "别哭了，好吗？我一定会平安带着{性别：他|她}归来的，这是约定。",
            ["ContentJP"] = "泣かないでください。必ず{性别:彼|彼女}を連れ戻します。約束です。",
            ["DialogueId"] = 12015926,
            ["GUID"] = "1E14A2DC",
            ["NextDialogue"] = 12015927,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A2DC",
            },
        [12015927] = {
            ["Content"] = "那……你赶紧去吧！我帮你们盯着这个什么缝隙，让它不要一下子关上！",
            ["ContentJP"] = "な、ならはやく行けば！？私はこのヘンテコな裂け目を見張っといてあげるから！！",
            ["DialogueId"] = 12015927,
            ["GUID"] = "1E14A306",
            ["NextDialogue"] = 12015928,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A306",
            },
        [12015928] = {
            ["Content"] = "整天说自己是什么魔王大人，结果连我的小仆从都护不住……",
            ["ContentJP"] = "自分の下僕すら守れないで……何が魔王だ……",
            ["DialogueId"] = 12015928,
            ["GUID"] = "1E14A330",
            ["NextDialogue"] = 12015929,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A330",
            },
        [12015929] = {
            ["Content"] = "坏东西，白看住你了，不许消失！",
            ["ContentJP"] = "ワルイやつめ！勝手に消えたりしたら、絶対に許さないよ！",
            ["DialogueId"] = 12015929,
            ["GUID"] = "1E14A35A",
            ["NextDialogue"] = 12015930,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A35A",
            },
        [12015930] = {
            ["Content"] = "笨蛋仆从，你一定要好好地回来哦！不然罚你给卡米拉打一年……不对，十年，一百年工！",
            ["ContentJP"] = "バカ{nickname}も！無事に帰ってこなきゃ許さないからね！カミラに言って一年……いや、じゅっ、100年タダ働きさせてやる！",
            ["DialogueId"] = 12015930,
            ["GUID"] = "1E14A384",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120159/1E14A384",
            },
        [12016001] = {
            ["Content"] = "（这里是……哪里……）",
            ["ContentJP"] = "（ここは……？）",
            ["DialogueId"] = 12016001,
            ["Duration"] = 2,
            ["GUID"] = "1E14AF2A",
            ["NextDialogue"] = 12016002,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120160/1E14AF2A",
            },
        [12016002] = {
            ["Content"] = "（谁也不在，什么声音都没有，安静到只能听见自己的心跳声……）",
            ["ContentJP"] = "（誰もいないし、なんの音もない。自分の鼓動以外……）",
            ["DialogueId"] = 12016002,
            ["Duration"] = 3,
            ["GUID"] = "1E14AF54",
            ["NextDialogue"] = 12016003,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120160/1E14AF54",
            },
        [12016003] = {
            ["Content"] = "（就像是……回到了白沙倾泻而下的原点，如同一切从未发生。）",
            ["ContentJP"] = "（まるで……白い砂がサラサラと流れ落ちる、あの原点に戻ってきたみたいだ。まるで、初めから何も起こっていなかった時のように。）",
            ["DialogueId"] = 12016003,
            ["Duration"] = 3,
            ["GUID"] = "1E14AF7E",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120160/1E14AF7E",
            },
        [12016101] = {
            ["Content"] = "{nickname}，听得到我的声音吗？",
            ["ContentJP"] = "{nickname}さん、聞こえますか？",
            ["DialogueId"] = 12016101,
            ["Duration"] = 3,
            ["GUID"] = "1E14BF92",
            ["NextDialogue"] = 12016102,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14BF92",
            },
        [12016102] = {
            ["Content"] = "扶疏？是你吗，你在哪里？！",
            ["ContentJP"] = "フーシュ？どこにいる{性别:んだ|の}！？",
            ["DialogueId"] = 12016102,
            ["Duration"] = 2,
            ["GUID"] = "1E14BFBC",
            ["NextDialogue"] = 12016103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14BFBC",
            },
        [12016103] = {
            ["Content"] = "我所处的位置和你有一段间隔。但这里是特殊的场域，人与人的思绪在此处得以相通。因而我能够看到你，把声音传达过去。",
            ["ContentJP"] = "私とあなたの間には、やや距離があります。ただ、ここは少々特殊でして――人と人の思念が自然と交わる場所なのです。ゆえに、私はあなたの姿を捉え、こうして声を届けることができるのです。",
            ["DialogueId"] = 12016103,
            ["Duration"] = 5,
            ["GUID"] = "1E14BFE6",
            ["NextDialogue"] = 12016104,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14BFE6",
            },
        [12016104] = {
            ["Content"] = "不用担忧，已经没事了。接下来我会引导你离开这里，回到安全的地方。",
            ["ContentJP"] = "ご安心ください、もう大丈夫です。これから私が、あなたを安全な場所へと連れ戻します。",
            ["DialogueId"] = 12016104,
            ["Duration"] = 4,
            ["GUID"] = "1E14C010",
            ["NextDialogue"] = 12016105,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14C010",
            },
        [12016105] = {
            ["Content"] = "……嗯，我明白了！",
            ["ContentJP"] = "……わかった！",
            ["DialogueId"] = 12016105,
            ["Duration"] = 2,
            ["GUID"] = "1E14C03A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120161/1E14C03A",
            },
        [12016201] = {
            ["Content"] = "看到那些灯花了吗？生者会将祈愿寄托于河灯之上，放入幽深的河水中，期望它们将思念载往亡者之域。",
            ["ContentJP"] = "あの灯籠の光が見えますか？生者は祈りと思いを込めて、川へ流したものです。やがてその光は、静かな流れに乗って、亡き人のもとへと届くのです。",
            ["DialogueId"] = 12016201,
            ["Duration"] = 4,
            ["GUID"] = "1E14CFFA",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120162/1E14CFFA",
            },
        [12016202] = {
            ["Content"] = "烛火的照耀可以护佑你，不受往隙的侵蚀。",
            ["ContentJP"] = "灯火のぬくもりが、あなたを包み、裂け目の侵蝕から守ってくれますように。",
            ["DialogueId"] = 12016202,
            ["Duration"] = 3,
            ["GUID"] = "1E14D024",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120162/1E14D024",
            },
        [12016251] = {
            ["Content"] = "扶疏，我应该怎么离开这里？",
            ["ContentJP"] = "教えて、どうやってここから出る{性别:んだ|の}？",
            ["DialogueId"] = 12016251,
            ["Duration"] = 3,
            ["GUID"] = "1E14D026",
            ["NextDialogue"] = 12016303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120162/1E14D026",
            },
        [12016301] = {
            ["Content"] = "小心身旁的河水。那是忘川，沾染到它会使人的存在逐渐淡薄，失去生之欲望。",
            ["ContentJP"] = "足元の川にはご注意を。それは「三途の川」と呼ばれています。触れれば、あなたという存在が少しずつ薄れ、生への意欲さえ失われていくのです。",
            ["DialogueId"] = 12016301,
            ["Duration"] = 3,
            ["GUID"] = "1E14E062",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E062",
            },
        [12016302] = {
            ["Content"] = "……可是周围都是河水，没有路了。该怎么办？",
            ["ContentJP"] = "……でも、あたり一面が川だらけで、道がないよ。どうすればいいの？",
            ["DialogueId"] = 12016302,
            ["Duration"] = 3,
            ["GUID"] = "1E14E08C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E08C",
            },
        [12016303] = {
            ["Content"] = "{nickname}，你有无论如何都要完成的心愿吗？",
            ["ContentJP"] = "{nickname}さん、たとえ何があっても、成し遂げたい願いはありますか？",
            ["DialogueId"] = 12016303,
            ["Duration"] = 3,
            ["GUID"] = "1E14E0B6",
            ["NextDialogue"] = 12016401,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E0B6",
            },
        [12016304] = {
            ["Content"] = "那就是你与此世的牵绊。对着前方的占风铎，默念你的心愿。",
            ["ContentJP"] = "それこそが、あなたとこの世を繋ぐ絆です。前方にある風鈴に向かって、心の中で願いをそっと唱えてみてください。",
            ["DialogueId"] = 12016304,
            ["Duration"] = 3,
            ["GUID"] = "1E14E0E0",
            ["NextDialogue"] = 12016305,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E0E0",
            },
        [12016305] = {
            ["Content"] = "它会唤来风，将你的执念送往更高更远处，助你重返生者之界。",
            ["ContentJP"] = "その鈴が風を呼び、あなたの願いを高く、遠くへと運んでくれるでしょう。そしてその風が、あなたを生者の世界へと導いてくれるはずです。",
            ["DialogueId"] = 12016305,
            ["Duration"] = 3,
            ["GUID"] = "1E14E10A",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120163/1E14E10A",
            },
        [12016401] = {
            ["Content"] = "（……无论如何都要去完成的事情。）",
            ["ContentJP"] = "（何としても成し遂げたいこと……）",
            ["DialogueId"] = 12016401,
            ["Duration"] = 2,
            ["GUID"] = "1E14F0CA",
            ["NextDialogue"] = 12016402,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120164/1E14F0CA",
            },
        [12016402] = {
            ["Content"] = "（贝蕾还在等着我……我要救出她，所以不能在这里止步！）",
            ["ContentJP"] = "（ベレを助け出さなきゃ。こんなところで立ち止まってる場合じゃない！）",
            ["DialogueId"] = 12016402,
            ["Duration"] = 3,
            ["GUID"] = "1E14F0F4",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120164/1E14F0F4",
            },
        [12016501] = {
            ["Content"] = "……！灯亮起来了，好美。",
            ["ContentJP"] = "……！灯りがともった……きれい。",
            ["DialogueId"] = 12016501,
            ["Duration"] = 2,
            ["GUID"] = "1E150132",
            ["NextDialogue"] = 12016502,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120165/1E150132",
            },
        [12016502] = {
            ["Content"] = "那些祈天灯的火焰，应当可以点燃灯花，帮你开辟新的道路。",
            ["ContentJP"] = "その祈りの灯火――その光なら、灯籠に火をともせるはずです。きっと、新たな道を照らしてくれるでしょう。",
            ["DialogueId"] = 12016502,
            ["Duration"] = 3,
            ["GUID"] = "1E15015C",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120165/1E15015C",
            },
        [12016601] = {
            ["Content"] = "{nickname}，是你吗？",
            ["ContentJP"] = "{nickname}、あなたなの？",
            ["DialogueId"] = 12016601,
            ["Duration"] = 2,
            ["GUID"] = "1E15119A",
            ["NextDialogue"] = 12016602,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210024,
            ["TalkActionId"] = {
                [1] = "210024:Explain01_Start",
                },
            ["TurnTo"] = {
                [1] = "210024:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E15119A",
            },
        [12016602] = {
            ["Content"] = "……贝蕾！",
            ["ContentJP"] = "……ベレ！？",
            ["DialogueId"] = 12016602,
            ["Duration"] = 2,
            ["GUID"] = "1E1511C4",
            ["NextDialogue"] = 12016603,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210024:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E1511C4",
            },
        [12016603] = {
            ["Content"] = "我们一定能够再次相逢的。在那之前，照顾好自己，不要受伤。",
            ["ContentJP"] = "きっとまた会える。だから、それまで元気で。怪我をしちゃダメよ。",
            ["DialogueId"] = 12016603,
            ["Duration"] = 3,
            ["GUID"] = "1E1511EE",
            ["NextDialogue"] = 12016604,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210024,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E1511EE",
            },
        [12016604] = {
            ["Content"] = "现在往前走吧，不要停下脚步。我会一直守望你的背影。",
            ["ContentJP"] = "さあ、前に進みなさい。私はここで見守ってるから。",
            ["DialogueId"] = 12016604,
            ["Duration"] = 3,
            ["GUID"] = "1E151218",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210024,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120166/1E151218",
            },
        [12016701] = {
            ["Content"] = "她就是你曾提及的“家人”吧。",
            ["ContentJP"] = "彼女があなたが話してた「家族」ですか。",
            ["DialogueId"] = 12016701,
            ["Duration"] = 2,
            ["GUID"] = "1E152202",
            ["NextDialogue"] = 12016702,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E152202",
            },
        [12016702] = {
            ["Content"] = "话虽扫兴……此处的她只是心愿和思念凝成的实体，并非真人。",
            ["ContentJP"] = "残念ですが、ここにいる彼女は、願いと想いが形となったもの。実体のある人間ではありません。",
            ["DialogueId"] = 12016702,
            ["Duration"] = 3,
            ["GUID"] = "1E15222C",
            ["NextDialogue"] = 12016703,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E15222C",
            },
        [12016703] = {
            ["Content"] = "我明白的。",
            ["ContentJP"] = "わかってる。",
            ["DialogueId"] = 12016703,
            ["Duration"] = 2,
            ["GUID"] = "1E152256",
            ["NextDialogue"] = 12016704,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E152256",
            },
        [12016704] = {
            ["Content"] = "就算如此，能在这里看到她，相信她还在世界上某个地方等我……我会安心许多。",
            ["ContentJP"] = "{性别:それでも、ここで彼女に会えたことで、まだどこかで僕を待っていると信じられる……それだけで、ずいぶん心が楽になるんだ。|それでも、ここで彼女に会えたことで、まだどこかで私を待っていると信じられる……それだけで、ずいぶん心が楽になるの。}",
            ["DialogueId"] = 12016704,
            ["Duration"] = 4,
            ["GUID"] = "1E152280",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120167/1E152280",
            },
        [12016801] = {
            ["Content"] = "又是新的占风铎。{nickname}，你知道该怎么做。",
            ["ContentJP"] = "また新しい風鈴が現れました。どうすべきかは、もうわかりますね？",
            ["DialogueId"] = 12016801,
            ["Duration"] = 3,
            ["GUID"] = "1E15326A",
            ["NextDialogue"] = 12016802,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120168/1E15326A",
            },
        [12016802] = {
            ["Content"] = "（我要平安回到冰湖城……大家还在等着我，我不能就此停下脚步！）",
            ["ContentJP"] = "（アイスレイク城に帰りたい……みんなが待ってるのに、ここで立ち止まるわけにはいかない！）",
            ["DialogueId"] = 12016802,
            ["Duration"] = 3,
            ["GUID"] = "1E153294",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120168/1E153294",
            },
        [12016901] = {
            ["Content"] = "好久不见，{nickname}。",
            ["ContentJP"] = "久しぶりね、{nickname}。",
            ["DialogueId"] = 12016901,
            ["Duration"] = 2,
            ["GUID"] = "1E1542D2",
            ["NextDialogue"] = 12016902,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "210025:n(0)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E1542D2",
            },
        [12016902] = {
            ["Content"] = "你是不是去了什么地方……一个我从未听过的、陌生又新鲜的地方？",
            ["ContentJP"] = "どこに行ってたの……私の知らない、未知の土地だったり？",
            ["DialogueId"] = 12016902,
            ["Duration"] = 3,
            ["GUID"] = "1E1542FC",
            ["NextDialogue"] = 12016903,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["TalkActionId"] = {
                [1] = "210024:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E1542FC",
            },
        [12016903] = {
            ["Content"] = "如果可以的话，等你什么时候回来冰湖城，可以讲给我听听吗？",
            ["ContentJP"] = "アイスレイク城に戻ってきたら、聞かせてくれると嬉しいな。",
            ["DialogueId"] = 12016903,
            ["Duration"] = 3,
            ["GUID"] = "1E154326",
            ["NextDialogue"] = 12016904,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["TalkActionId"] = {
                [1] = "210024:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E154326",
            },
        [12016904] = {
            ["Content"] = "虽然这个愿望有点奢侈……可以的话，请不要忘记我。",
            ["ContentJP"] = "贅沢なお願いかもしれないけど……私のこと、忘れないで欲しい。",
            ["DialogueId"] = 12016904,
            ["GUID"] = "1E154350",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210025,
            ["VoiceName"] = "voice/$Locale$/story/1201/120169/1E154350",
            },
        [12017001] = {
            ["Content"] = "小仆从，快跟上来，怎么这么慢！魔王大人还要带你一起去征服世界呢！",
            ["ContentJP"] = "我が下僕、遅いぞ！魔王様と共に世界を制服しようではないか！！",
            ["DialogueId"] = 12017001,
            ["Duration"] = 4,
            ["GUID"] = "1E15533A",
            ["NextDialogue"] = 12017002,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200002,
            ["SpeakNpcName"] = "UI_CMName_Name_BaiPhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E15533A",
            },
        [12017002] = {
            ["Content"] = "到底去哪儿了，让我好找。快回来吧，菲娜还想听你给她讲故事。",
            ["ContentJP"] = "探したぞ、どこに行ってたんだ？フィーナがお前と話したいってうるさいんだ。さっさと戻ってこい。",
            ["DialogueId"] = 12017002,
            ["GUID"] = "1E155364",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 100401,
            ["SpeakNpcName"] = "UI_CMName_Name_AotePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E155364",
            },
        [12017003] = {
            ["Content"] = "别在外面折断腿了。干完了活计就回水仙平原吧，我为你留了杯热饮，放凉了可就不好了。",
            ["ContentJP"] = "ケガをするんじゃないよ。さっさと仕事を終えてアスフォデロスに戻ってきなさい。暖かい飲み物を用意したの。冷めてしまってはいけないわ。",
            ["DialogueId"] = 12017003,
            ["Duration"] = 3,
            ["GUID"] = "1E15538E",
            ["NextDialogue"] = 12017004,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200003,
            ["SpeakNpcName"] = "UI_CMName_Name_KamiPhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E15538E",
            },
        [12017004] = {
            ["Content"] = "挣钱固然重要。要是有命赚钱没命花，可就得不偿失了。",
            ["ContentJP"] = "儲けに熱くなるのはいいけど、命を削るほどの情熱はほめられたものじゃない。何事もほどほどに、ね。",
            ["DialogueId"] = 12017004,
            ["Duration"] = 3,
            ["GUID"] = "1E1553B8",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E1553B8",
            },
        [12017005] = {
            ["Content"] = "看来，你有许多关心你、和你建立起牵绊的人……真好。",
            ["ContentJP"] = "心配してくれる方がたくさんいるようですね……とても、素敵なことです。",
            ["DialogueId"] = 12017005,
            ["Duration"] = 3,
            ["GUID"] = "1E1553E2",
            ["NextDialogue"] = 12017006,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E1553E2",
            },
        [12017006] = {
            ["Content"] = "出路就在前方了。趟过忘川，踏上眼前的奈何桥，它会渡你回彼岸。",
            ["ContentJP"] = "出口はもう目の前です。三途の川を渡り、あの奈何橋を渡れば、あなたは向こう岸へと戻れるでしょう。",
            ["DialogueId"] = 12017006,
            ["GUID"] = "1E15540C",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120170/1E15540C",
            },
        [12017101] = {
            ["Content"] = "……呼，{nickname}平安无虞了。",
            ["ContentJP"] = "……ふう、これで{nickname}は無事に出られるでしょう。",
            ["DialogueId"] = 12017101,
            ["Duration"] = 3,
            ["GUID"] = "1E1563A2",
            ["NextDialogue"] = 12017102,
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120171/1E1563A2",
            },
        [12017102] = {
            ["Content"] = "往隙与此世的联系正在逐渐关闭……得抓紧出去了。",
            ["ContentJP"] = "裂け目とこの世の繋がりが徐々に途切れ始めてる……急いで出ないと。",
            ["DialogueId"] = 12017102,
            ["Duration"] = 3,
            ["GUID"] = "1E1563CC",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120171/1E1563CC",
            },
        [12017201] = {
            ["Content"] = "咿咿呀——",
            ["ContentJP"] = "リォー",
            ["DialogueId"] = 12017201,
            ["GUID"] = "1E15740A",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E15740A",
            },
        [12017202] = {
            ["Content"] = "小家伙，你怎么在这里……？",
            ["ContentJP"] = "……ど、どうしてここに？",
            ["DialogueId"] = 12017202,
            ["GUID"] = "1E157434",
            ["NextDialogue"] = 12017203,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E157434",
            },
        [12017203] = {
            ["Content"] = "咿呀，咿！",
            ["ContentJP"] = "イッ、イッ！",
            ["DialogueId"] = 12017203,
            ["GUID"] = "1E15745E",
            ["NextDialogue"] = 12017204,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E15745E",
            },
        [12017204] = {
            ["Content"] = "……被此界侵染太久，已经失去说话的能力了吗？真可怜。",
            ["ContentJP"] = "裂け目にいすぎて、言葉を失ってしまったのね。なんて可哀そうなの。",
            ["DialogueId"] = 12017204,
            ["GUID"] = "1E157488",
            ["NextDialogue"] = 12017205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E157488",
            },
        [12017205] = {
            ["Content"] = "跟紧我，我也会将你带至安全的地方。",
            ["ContentJP"] = "ついてらっしゃい。あなたを安全な場所へ導きましょう。",
            ["DialogueId"] = 12017205,
            ["GUID"] = "1E1574B2",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E1574B2",
            },
        [12017206] = {
            ["Content"] = "咿！",
            ["ContentJP"] = "イッ！",
            ["DialogueId"] = 12017206,
            ["GUID"] = "1E1574DC",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120172/1E1574DC",
            },
        [12017301] = {
            ["Content"] = "（扶疏平生所愿，仅有以枯荣之术渡尽天下苍生。唯有此誓，不敢悖离。）",
            ["ContentJP"] = "（私の願いは、<Default note=\"text:こえい\">枯栄</>の術をもってこの世のすべての命を救うこと。ただこの誓いだけは、決して破りません。）",
            ["DialogueId"] = 12017301,
            ["Duration"] = 3,
            ["GUID"] = "1E158472",
            ["NextDialogue"] = 12017302,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120173/1E158472",
            },
        [12017302] = {
            ["Content"] = "烛火的颜色，有些不对劲……",
            ["ContentJP"] = "灯火の色が、少しおかしい……",
            ["DialogueId"] = 12017302,
            ["Duration"] = 2,
            ["GUID"] = "1E15849C",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120173/1E15849C",
            },
        [12017401] = {
            ["Content"] = "我好痛啊……我的疮口在流脓，痛到彻夜难眠……",
            ["ContentJP"] = "ああ痛い……傷口が膿んで、夜も眠れない……",
            ["DialogueId"] = 12017401,
            ["Duration"] = 2,
            ["GUID"] = "1E1594DA",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E1594DA",
            },
        [12017402] = {
            ["Content"] = "我……已经没有活路了吧。祝由大人，给我一个了断吧……",
            ["ContentJP"] = "もう私は助からない……どうか、楽にしてくれないか……",
            ["DialogueId"] = 12017402,
            ["Duration"] = 3,
            ["GUID"] = "1E159504",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E159504",
            },
        [12017403] = {
            ["Content"] = "我的孩儿刚出生，她都还没有开口唤过一声“阿娘”啊！求求您，救救她，救救她！",
            ["ContentJP"] = "娘は生まれたばかりなの！まだ「母さん」すら聞けてないわ！お願いよ、この子を助けて！お願いよぉぉ！！",
            ["DialogueId"] = 12017403,
            ["Duration"] = 3,
            ["GUID"] = "1E15952E",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E15952E",
            },
        [12017404] = {
            ["Content"] = "传闻中的扶氏不是手到病除吗？快治啊，莫非你不愿出力？",
            ["ContentJP"] = "フー家は万病を癒すのではなかったのか？まさか嘘だったのか？",
            ["DialogueId"] = 12017404,
            ["Duration"] = 4,
            ["GUID"] = "1E159558",
            ["SnapShot"] = "MEMORY",
            ["SpeakNpcName"] = "UI_CMName_Name_HuanzhePhantom",
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E159558",
            },
        [12017405] = {
            ["Content"] = "那是……百年之前的大疫。",
            ["ContentJP"] = "あれは……百年前の大疫病。",
            ["DialogueId"] = 12017405,
            ["Duration"] = 1,
            ["GUID"] = "1E159582",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12017406,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E159582",
            },
        [12017406] = {
            ["Content"] = "我四处奔走，精疲力尽，却只能眼睁睁地看着患者在绝望苦痛中死去。",
            ["ContentJP"] = "私はあちこち奔走し、疲れ果てながらも、患者たちが絶望と苦痛の中で死んでいくのをただ見守るしかなかった。",
            ["DialogueId"] = 12017406,
            ["Duration"] = 3,
            ["GUID"] = "1E1595AC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E1595AC",
            },
        [12017407] = {
            ["Content"] = "（烛火的回应……原来我的内心早有动摇吗？）",
            ["ContentJP"] = "（灯火が……私の心はいつの間に揺らいでいたのだろうか。）",
            ["DialogueId"] = 12017407,
            ["Duration"] = 2,
            ["GUID"] = "1E1595D6",
            ["NextDialogue"] = 12017501,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120174/1E1595D6",
            },
        [12017501] = {
            ["Content"] = "（我所牵挂的，不止是被病痛折磨的人们吗？）",
            ["ContentJP"] = "（私が案じてたのは、病に苦しむ人々だけではなかったのだろうか。）",
            ["DialogueId"] = 12017501,
            ["Duration"] = 3,
            ["GUID"] = "1E15A542",
            ["NextDialogue"] = 12017502,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120175/1E15A542",
            },
        [12017502] = {
            ["Content"] = "（但我平生所学，所践行，唯有枯荣之术。若是心不静了，我又该如何走出此地……）",
            ["ContentJP"] = "（私が生涯を以て学んだのは、<Default note=\"text:こえい\">枯栄</>の術のみ。心が乱れれば、この場所を抜け出す術など、もう……）",
            ["DialogueId"] = 12017502,
            ["Duration"] = 4,
            ["GUID"] = "1E15A56C",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120175/1E15A56C",
            },
        [12017601] = {
            ["Content"] = "……不出所料。",
            ["ContentJP"] = "……やっぱりダメなのね。",
            ["DialogueId"] = 12017601,
            ["Duration"] = 1,
            ["GUID"] = "1E15B5AA",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12017602,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120176/1E15B5AA",
            },
        [12017602] = {
            ["Content"] = "抱歉，说了带你出去，看来要食言了。",
            ["ContentJP"] = "ごめんなさい。あなたを連れ戻すという約束、守れそうにないわ。",
            ["DialogueId"] = 12017602,
            ["Duration"] = 2,
            ["GUID"] = "1E15B5D4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120176/1E15B5D4",
            },
        [12017701] = {
            ["Content"] = "咿呀，咿咿呀，咿！",
            ["ContentJP"] = "ユン、ユンユン！",
            ["DialogueId"] = 12017701,
            ["Duration"] = 1,
            ["GUID"] = "1E15C612",
            ["NextDialogue"] = 12017702,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C612",
            },
        [12017702] = {
            ["Content"] = "……！你将自己作为燃料吗？这样下去，你会彻底消散无形……",
            ["ContentJP"] = "……！？あ、あなた、自分を燃料に！？でも、それではあなたが……",
            ["DialogueId"] = 12017702,
            ["Duration"] = 3,
            ["GUID"] = "1E15C63C",
            ["NextDialogue"] = 12017703,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C63C",
            },
        [12017703] = {
            ["Content"] = "咿！",
            ["ContentJP"] = "イッ！",
            ["DialogueId"] = 12017703,
            ["Duration"] = 1,
            ["GUID"] = "1E15C666",
            ["NextDialogue"] = 12017704,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C666",
            },
        [12017704] = {
            ["Content"] = "……我明白了，我会尽力护佑你。",
            ["ContentJP"] = "……わかったわ。できるだけ、あなたを守るから。",
            ["DialogueId"] = 12017704,
            ["Duration"] = 2,
            ["GUID"] = "1E15C690",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120177/1E15C690",
            },
        [12017801] = {
            ["Content"] = "扶疏，我听闻你救治别人时倒下，千里迢迢赶回来看你……你不能继续使用枯荣之术了。",
            ["ContentJP"] = "フーシュ……人を救って倒れたって聞いて、千里の道を急いで帰ってきたのよ。もう……<Default note=\"text:こえい\">枯栄</>の術は使わないで。あなたの身が持たないわ。",
            ["DialogueId"] = 12017801,
            ["GUID"] = "1E15D67A",
            ["NextDialogue"] = 12017802,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D67A",
            },
        [12017802] = {
            ["Content"] = "多谢关心。我已经无恙，姐姐请回吧。",
            ["ContentJP"] = "ご心配、感謝します。私はもう大丈夫です――姉さん、どうかお戻りください。",
            ["DialogueId"] = 12017802,
            ["GUID"] = "1E15D6A4",
            ["NextDialogue"] = 12017803,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D6A4",
            },
        [12017803] = {
            ["Content"] = "无恙？！如此不爱惜自己，真要连性命都丢了才罢休吗？",
            ["ContentJP"] = "このどこが大丈夫なの！？そんなに自分を無下にして、命まで投げうるつもり！？",
            ["DialogueId"] = 12017803,
            ["GUID"] = "1E15D6CE",
            ["NextDialogue"] = 12017804,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D6CE",
            },
        [12017804] = {
            ["Content"] = "救治苍生本就是大风九章赋予扶氏的使命。你要我看人们受病痛煎熬，却置若罔闻吗？",
            ["ContentJP"] = "病に苦しむ人々を救うのは、大風九章がフ―家に与えた使命。患者を見捨てろと、おっしゃりたいのですか？",
            ["DialogueId"] = 12017804,
            ["GUID"] = "1E15D6F8",
            ["NextDialogue"] = 12017805,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D6F8",
            },
        [12017805] = {
            ["Content"] = "若不是姐姐当初执意要去研究什么<H>药理</>，弃家传枯荣术于不顾，我又何苦将自己逼至此境地？",
            ["ContentJP"] = "そもそも姉さんが、<H>薬理</>の研究とやらに固執して、家伝の<Default note=\"text:こえい\">枯栄</>の術を捨てなければ……私がこんな道を選ぶ必要など、なかった。",
            ["DialogueId"] = 12017805,
            ["GUID"] = "1E15D722",
            ["NextDialogue"] = 12017806,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D722",
            },
        [12017806] = {
            ["Content"] = "恕我做不到像姐姐一般惜命。",
            ["ContentJP"] = "私は姉さんのように、命を惜しむことはできません。",
            ["DialogueId"] = 12017806,
            ["GUID"] = "1E15D74C",
            ["NextDialogue"] = 12017901,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210029,
            ["VoiceName"] = "voice/$Locale$/story/1201/120178/1E15D74C",
            },
        [12017901] = {
            ["Content"] = "……扶疏。原来，你心中一直是这般想我。",
            ["ContentJP"] = "……フーシュ、あなたずっと私のことそんな風に思ってたのね。",
            ["DialogueId"] = 12017901,
            ["Duration"] = 2,
            ["GUID"] = "1E15E6E2",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120179/1E15E6E2",
            },
        [12017902] = {
            ["Content"] = "（那些话并非我本意。但我一开口，恶语竟如泉涌，滔滔而出。）",
            ["ContentJP"] = "（そんなつもりじゃなかったのに……口を開いた途端、毒のような言葉ばかりが、次から次へと溢れ出てしまった。）",
            ["DialogueId"] = 12017902,
            ["Duration"] = 3,
            ["GUID"] = "1E15E70C",
            ["NextDialogue"] = 12017903,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120179/1E15E70C",
            },
        [12017903] = {
            ["Content"] = "（最后，我不知如何面对姐姐，夺路而逃。那也是我与姐姐的最后一次交谈。）",
            ["ContentJP"] = "（結局、姉さんとどう向き合えばいいのか分からず、私はその場を逃げ出した……あれが、姉さんと言葉を交わした最後だった。）",
            ["DialogueId"] = 12017903,
            ["Duration"] = 3,
            ["GUID"] = "1E15E736",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120179/1E15E736",
            },
        [12018001] = {
            ["Camera"] = "-361.291565,868.035156,176.938965,0.000062,-2.401447,-174.821503,35.0,506.121063,false,Manual,2.8",
            ["Content"] = "扶疏……你正当英年，姐姐不允许你就这般离世……",
            ["ContentJP"] = "フーシュ……あなたはまだ若いわ。こんな形で逝くなんて、姉さん絶対に許さないから……",
            ["DialogueId"] = 12018001,
            ["Duration"] = 3,
            ["GUID"] = "1E15F74A",
            ["NextDialogue"] = 12018002,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120180/1E15F74A",
            },
        }
  end },
  { MinKey = 12018002, MaxKey = 12019814, Loader = function()
      return {
        [12018002] = {
            ["Content"] = "我定会研制出能救你的药物，就算耗尽余生也在所不惜……等着我。",
            ["ContentJP"] = "あなたを救える薬を、きっとこの手で作ってみせる。たとえ、一生をかけても……必ずね。だから待ってて、フーシュ――",
            ["DialogueId"] = 12018002,
            ["Duration"] = 2,
            ["GUID"] = "1E15F774",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcId"] = 210028,
            ["VoiceName"] = "voice/$Locale$/story/1201/120180/1E15F774",
            },
        [12018003] = {
            ["Content"] = "…………",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12018003,
            ["GUID"] = "1E15F775",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120180/1E15F775",
            },
        [12018004] = {
            ["DialogueId"] = 12018004,
            ["GUID"] = "1E15F776",
            },
        [12018101] = {
            ["Content"] = "……姐姐……",
            ["ContentJP"] = "……姉さん……",
            ["DialogueId"] = 12018101,
            ["Duration"] = 2,
            ["GUID"] = "1E1607B2",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12018102,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120181/1E1607B2",
            },
        [12018102] = {
            ["Content"] = "姐姐曾以至诚之心待我，我却未能珍视其意。",
            ["ContentJP"] = "姉さんはあんなに私を想ってくれたのに、私はその想いを大切にできなかった。",
            ["DialogueId"] = 12018102,
            ["Duration"] = 3,
            ["GUID"] = "1E1607DC",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 12018103,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120181/1E1607DC",
            },
        [12018103] = {
            ["Content"] = "我想和姐姐再见一面……哪怕只是说一句“对不起”……",
            ["ContentJP"] = "もう一度だけ……姉さんに会いたい。「ごめんなさい」って言わせてほしい……",
            ["DialogueId"] = 12018103,
            ["Duration"] = 2,
            ["GUID"] = "1E160806",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120181/1E160806",
            },
        [12018201] = {
            ["Content"] = "咿！咿！",
            ["ContentJP"] = "イッ！イッ！",
            ["DialogueId"] = 12018201,
            ["Duration"] = 1,
            ["GUID"] = "1E16181A",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E16181A",
            },
        [12018202] = {
            ["Content"] = "扶疏！我还以为你……",
            ["ContentJP"] = "フーシュ！良かった……てっきり……",
            ["DialogueId"] = 12018202,
            ["GUID"] = "1E161844",
            ["NextDialogue"] = 12018203,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161844",
            },
        [12018203] = {
            ["Content"] = "抱歉，使你担心了。",
            ["ContentJP"] = "心配をかけてごめんなさい。",
            ["DialogueId"] = 12018203,
            ["GUID"] = "1E16186E",
            ["NextDialogue"] = 12018204,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E16186E",
            },
        [12018204] = {
            ["Content"] = "多亏了这位不知名无由生的帮助，我才未在往隙中迷失。渡人亦是渡己，古语诚不欺我……",
            ["ContentJP"] = "このムユウセイの助けがなければ、私は過去の迷いに囚われたままだったでしょう。人を救うことは、己を救うことでもある――古の言葉は、やはり偽りではありませんでした。",
            ["DialogueId"] = 12018204,
            ["GUID"] = "1E161898",
            ["NextDialogue"] = 12018205,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161898",
            },
        [12018205] = {
            ["Content"] = "咿，咿呀咿，咿！",
            ["ContentJP"] = "イッ！イーヤッ！イッ！",
            ["DialogueId"] = 12018205,
            ["GUID"] = "1E1618C2",
            ["NextDialogue"] = 12018206,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1618C2",
            },
        [12018206] = {
            ["Content"] = "太好了。能与你会合，我就放心了许多。",
            ["ContentJP"] = "よかった。無事であなたと合流してほっとした{性别:んだ|よ}。",
            ["DialogueId"] = 12018206,
            ["GUID"] = "1E1618EC",
            ["NextDialogue"] = 12018207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1618EC",
            },
        [12018207] = {
            ["Content"] = "我们现在尚未脱离险境。虽已走出了最凶险的地带，但还不能松懈。随我尽早离开这里，回到此世吧。",
            ["ContentJP"] = "まだ、危機を脱したわけではありません。最も危うい場所は越えましたが、気を緩めるには早すぎます。さあ、私とともに――この地を離れ、現世へ戻りましょう。",
            ["DialogueId"] = 12018207,
            ["GUID"] = "1E161916",
            ["NextDialogue"] = 12018208,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161916",
            },
        [12018208] = {
            ["Content"] = "嗯，我明白了！",
            ["ContentJP"] = "うん、わかった！",
            ["DialogueId"] = 12018208,
            ["GUID"] = "1E161940",
            ["NextDialogue"] = 12018209,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161940",
            },
        [12018209] = {
            ["Content"] = "先顺着这些辉玉前行吧，它们会指引生路的方向。",
            ["ContentJP"] = "この発光する玉の並びに従って進みましょう。きっと、私たちを生の道へと導いてくれるはずです。",
            ["DialogueId"] = 12018209,
            ["GUID"] = "1E16196A",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E16196A",
            },
        [12018210] = {
            ["Content"] = "扶疏，你刚刚在忘川中看见了什么？",
            ["ContentJP"] = "そういえばフーシュ、三途の川で何を見たの？",
            ["DialogueId"] = 12018210,
            ["GUID"] = "1E161994",
            ["NextDialogue"] = 12018211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161994",
            },
        [12018211] = {
            ["Content"] = "只是一些过往的人事物……都已随时间故去了。",
            ["ContentJP"] = "ただの、過去の断片……時の流れとともに消えていったものに過ぎませんから。",
            ["DialogueId"] = 12018211,
            ["GUID"] = "1E1619BE",
            ["NextDialogue"] = 12018212,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1619BE",
            },
        [12018212] = {
            ["Content"] = "看来并不是什么愉快的回忆……",
            ["ContentJP"] = "あまりいい思い出ではなかったようだね。",
            ["DialogueId"] = 12018212,
            ["GUID"] = "1E1619E8",
            ["NextDialogue"] = 12018213,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E1619E8",
            },
        [12018213] = {
            ["Content"] = "救命——",
            ["ContentJP"] = "助ケ――",
            ["DialogueId"] = 12018213,
            ["GUID"] = "1E161A12",
            ["NextDialogue"] = 12018214,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A12",
            },
        [12018214] = {
            ["Content"] = "咿呀，咿！",
            ["ContentJP"] = "イッ、イッ！",
            ["DialogueId"] = 12018214,
            ["GUID"] = "1E161A3C",
            ["NextDialogue"] = 12018215,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A3C",
            },
        [12018215] = {
            ["Content"] = "那边好像有求救的声音，我们赶紧过去看看！",
            ["ContentJP"] = "あっちから助けを求める声がする。行ってみよう！",
            ["DialogueId"] = 12018215,
            ["GUID"] = "1E161A66",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A66",
            },
        [12018216] = {
            ["Content"] = "谢谢，好心人！",
            ["ContentJP"] = "アリガトウ！",
            ["DialogueId"] = 12018216,
            ["GUID"] = "1E161A90",
            ["NextDialogue"] = 12018217,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161A90",
            },
        [12018217] = {
            ["Content"] = "还有，更多的，同伴，散落了。",
            ["ContentJP"] = "マダ、仲間、タクサン迷子、ナッテル。",
            ["DialogueId"] = 12018217,
            ["GUID"] = "1E161ABA",
            ["NextDialogue"] = 12018218,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161ABA",
            },
        [12018218] = {
            ["Content"] = "这个地方，不好，赶紧逃出去。离开这里，需要，大家的力量！",
            ["ContentJP"] = "ココ、危険。逃ゲ出スニハ、ミンナノ力、必要。",
            ["DialogueId"] = 12018218,
            ["GUID"] = "1E161AE4",
            ["NextDialogue"] = 12018219,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161AE4",
            },
        [12018219] = {
            ["Content"] = "还有更多的无由生被困在这里吗？我明白了，我会留意的。",
            ["ContentJP"] = "ここには、ほかにもムユウセイが囚われているんだね？……わかった、できるだけ気を配るよ。",
            ["DialogueId"] = 12018219,
            ["GUID"] = "1E161B0E",
            ["NextDialogue"] = 12018220,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161B0E",
            },
        [12018220] = {
            ["Content"] = "谢谢，谢谢！力量，借给你！",
            ["ContentJP"] = "アリガトウ！ワタシノ力、貸ス！",
            ["DialogueId"] = 12018220,
            ["GUID"] = "1E161B38",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161B38",
            },
        [12018221] = {
            ["Content"] = "黯淡的石头，力量，发光！",
            ["ContentJP"] = "クスミシ石、力ヲ灯セ！",
            ["DialogueId"] = 12018221,
            ["GUID"] = "1E161B62",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161B62",
            },
        [12018222] = {
            ["Content"] = "前方的路被荆棘挡住了……",
            ["ContentJP"] = "石の扉が道を塞いでて、前に進めない……",
            ["DialogueId"] = 12018222,
            ["GUID"] = "1E161B8C",
            ["NextDialogue"] = 12018223,
            ["SpeakNpcId"] = 100001,
            },
        [12018223] = {
            ["Content"] = "观察一下附近吧，或许有什么玄机。",
            ["ContentJP"] = "このあたりをよく観察してみましょう。何か仕掛けが隠されているかもしれません。",
            ["DialogueId"] = 12018223,
            ["GUID"] = "1E161BB6",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161BB6",
            },
        [12018224] = {
            ["Content"] = "黯淡的石头，同时，发光！",
            ["ContentJP"] = "クスミシ石、同時ニ光レ！",
            ["DialogueId"] = 12018224,
            ["GUID"] = "1E161BE0",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161BE0",
            },
        [12018225] = {
            ["Content"] = "哇啊……！是祝由大人，还有陌生的人类！",
            ["ContentJP"] = "ワァ！祝由サマと……知ラナイ人間！",
            ["DialogueId"] = 12018225,
            ["GUID"] = "1E161C0A",
            ["NextDialogue"] = 12018226,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C0A",
            },
        [12018226] = {
            ["Content"] = "看着回到虞泉的出口，好远好远。不知不觉就泄气，走不动路了……",
            ["ContentJP"] = "虞泉ノ出口、見エテルノニ……トオイ、トオイ……イツノ間ニカ、元気ナクナッテ、歩ケナクナッチャッタ……",
            ["DialogueId"] = 12018226,
            ["GUID"] = "1E161C34",
            ["NextDialogue"] = 12018227,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C34",
            },
        [12018227] = {
            ["Content"] = "好像在这里一觉睡过去，忘记一切，就此消失也无所谓了……",
            ["ContentJP"] = "ココデ、ネチャッテ……全部、忘レテ……消エチャッテモ、イイカナ……ナンテ、思ッタ……",
            ["DialogueId"] = 12018227,
            ["GUID"] = "1E161C5E",
            ["NextDialogue"] = 12018228,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C5E",
            },
        [12018228] = {
            ["Content"] = "但是，既然同伴来了，就应当迈开脚步继续向前了吧！",
            ["ContentJP"] = "デモネ！仲間ガ来テクレタナラ、足、動カサナクチャ！前ニ、進マナクチャ！",
            ["DialogueId"] = 12018228,
            ["GUID"] = "1E161C88",
            ["NextDialogue"] = 12018229,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161C88",
            },
        [12018229] = {
            ["Content"] = "在忘川中跋涉了许久，是否觉得灵魂有些沉重呢？我来减轻你们的负担，让你们身轻如燕吧！",
            ["ContentJP"] = "三途ノ川、ズーット歩イテ……魂、重クナッテナイ？ワタシガ軽クスルネ！ヒュンッて飛ベル、燕ミタイニ！",
            ["DialogueId"] = 12018229,
            ["GUID"] = "1E161CB2",
            ["NextDialogue"] = 12018230,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161CB2",
            },
        [12018230] = {
            ["Content"] = "那，我来帮你们扫清远处的障碍，让你们的行动更加灵活！",
            ["ContentJP"] = "ジャア、遠クノジャマモ、ワタシガ片付ケチャウ！モットスイスイ動ケルヨ！",
            ["DialogueId"] = 12018230,
            ["GUID"] = "1E161CDC",
            ["NextDialogue"] = 12018231,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161CDC",
            },
        [12018231] = {
            ["Content"] = "咿，咿呀！这下完全没问题了，我们赶紧出发吧！",
            ["ContentJP"] = "イッ、イーヤッ！コレデ、モウゼンゼン平気！サァサァ、急イデ出発ダヨー！",
            ["DialogueId"] = 12018231,
            ["GUID"] = "1E161D06",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA&B",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D06",
            },
        [12018232] = {
            ["Content"] = "咿咿，呀！",
            ["ContentJP"] = "イッ、イーヤッ！",
            ["DialogueId"] = 12018232,
            ["GUID"] = "1E161D30",
            ["NextDialogue"] = 12018233,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D30",
            },
        [12018233] = {
            ["Content"] = "坏花困住了同伴，赶紧去帮忙！",
            ["ContentJP"] = "ワルイ花ガ、仲間ヲ捕マエチャッタ！早ク早ク、助ケテ！",
            ["DialogueId"] = 12018233,
            ["GUID"] = "1E161D5A",
            ["NextDialogue"] = 12018234,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D5A",
            },
        [12018234] = {
            ["Content"] = "我在古籍上见过此种异花。当其花瓣闭合时，刀枪难入，只能等候其绽开的时机。",
            ["ContentJP"] = "この異形の花――古い書で見たことがあります。花びらが閉じている間は、如何なる武器も通りません。開花の瞬間を待って、攻めましょう。",
            ["DialogueId"] = 12018234,
            ["GUID"] = "1E161D84",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161D84",
            },
        [12018235] = {
            ["Content"] = "花蕊暴露在外了，就趁现在！",
            ["ContentJP"] = "花蕊が露わになった……今です！",
            ["DialogueId"] = 12018235,
            ["GUID"] = "1E161DAE",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161DAE",
            },
        [12018236] = {
            ["Content"] = "祝由大人，还有没见过的白发勇者，谢谢你们！",
            ["ContentJP"] = "祝由サマ、白髪ノ勇者サマ、アリガトウ！",
            ["DialogueId"] = 12018236,
            ["GUID"] = "1E161DD8",
            ["NextDialogue"] = 12018237,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161DD8",
            },
        [12018237] = {
            ["Content"] = "俺也来助你们一臂之力！俺的铁头槌，连大地都能砸的梆梆作响哟！",
            ["ContentJP"] = "オレモ、手伝ウ！オレノ鉄頭槌、ドーン！大地モ、バンバン鳴ル！",
            ["DialogueId"] = 12018237,
            ["GUID"] = "1E161E02",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengShoukun",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E02",
            },
        [12018238] = {
            ["Content"] = "最后的同伴，最后的同伴！",
            ["ContentJP"] = "最後ノ仲間！最後ノ仲間！",
            ["DialogueId"] = 12018238,
            ["GUID"] = "1E161E2C",
            ["NextDialogue"] = 12018239,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E2C",
            },
        [12018239] = {
            ["Content"] = "还是先前那种异花。{nickname}，趁其绽开的时机，将花蕊连着枝蔓一举荡清吧。",
            ["ContentJP"] = "また先ほどと同じ異花です。{nickname}さん、花が開いたその瞬間、花蕊ごと枝まで、一気に断ち切ってください。",
            ["DialogueId"] = 12018239,
            ["GUID"] = "1E161E56",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E56",
            },
        [12018240] = {
            ["Content"] = "以老夫平生武艺，竟险些折在了此处。惭愧，惭愧……",
            ["ContentJP"] = "老いぼれとはいえ、この身、かつてはそれなりに武を心得ていたつもりじゃが……まさか、ここまで手こずるとはな。面目ない、面目ない……",
            ["DialogueId"] = 12018240,
            ["GUID"] = "1E161E80",
            ["NextDialogue"] = 12018241,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_CMName_Name_MatureWuyou",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161E80",
            },
        [12018241] = {
            ["Content"] = "这样一来，同伴就集齐啦！没有人被落下，没有人被落下！",
            ["ContentJP"] = "コレデ全員！ミンナイル？ミンナイル！",
            ["DialogueId"] = 12018241,
            ["GUID"] = "1E161EAA",
            ["NextDialogue"] = 12018242,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_Npc_Name_WuyoushengA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161EAA",
            },
        [12018242] = {
            ["Content"] = "前方为一巨花秽兽所盘踞，其把持了前往此世之出口。让老夫随你们同去，降妖除魔，清源正本！",
            ["ContentJP"] = "この先に、とんでもねぇ巨大な花の穢獣が出口を塞いでおる。わしを同行させとくれ。この手で直々に根っこを引き抜いてくれよう！",
            ["DialogueId"] = 12018242,
            ["GUID"] = "1E161ED4",
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcName"] = "UI_CMName_Name_MatureWuyou",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161ED4",
            },
        [12018243] = {
            ["Content"] = "{nickname}，忘川即将崩塌了，必须赶紧结束这一战！",
            ["ContentJP"] = "{nickname}さん、三途の川はまもなく崩壊します！一刻も早く片付けましょう！",
            ["DialogueId"] = 12018243,
            ["GUID"] = "1E161EFE",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161EFE",
            },
        [12018244] = {
            ["Content"] = "趁现在，把手递给我。",
            ["ContentJP"] = "さぁ、手を。",
            ["DialogueId"] = 12018244,
            ["GUID"] = "1E161F28",
            ["VoiceName"] = "voice/$Locale$/story/1201/120182/1E161F28",
            },
        [12018300] = {
            ["Content"] = "多谢两位救命之恩，以后必将回报。我们便先离去啦！",
            ["ContentJP"] = "アリガトウ！コノ恩、忘レナイ！先に失礼シマス！",
            ["DialogueId"] = 12018300,
            ["GUID"] = "1E162858",
            ["NextDialogue"] = 12018301,
            ["RelatedWikiId"] = {
                [1] = 408013,
                [2] = 303012,
                [3] = 203006,
                },
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wuyoushengmen",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162858",
            },
        [12018301] = {
            ["Content"] = "……呜呜……扶疏，{nickname}，你们终于回来了！我都快急坏了……",
            ["ContentJP"] = "……ううっ……フーシュ、{nickname}、遅いじゃないか！！",
            ["DialogueId"] = 12018301,
            ["GUID"] = "1E162882",
            ["NextDialogue"] = 12018302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162882",
            },
        [12018302] = {
            ["Content"] = "我还以为差一点就……呸呸呸！坏话不说出来就不会灵验！",
            ["ContentJP"] = "私はてっきり……いやいや！縁起のないことは言わない！！",
            ["DialogueId"] = 12018302,
            ["GUID"] = "1E1628AC",
            ["NextDialogue"] = 12018303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1628AC",
            },
        [12018303] = {
            ["Content"] = "扶疏，谢谢你以身涉险，把我带出来。",
            ["ContentJP"] = "フーシュ、あんな危険な場所から助け出してくれてありがとう。",
            ["DialogueId"] = 12018303,
            ["GUID"] = "1E1628D6",
            ["NextDialogue"] = 12018304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1628D6",
            },
        [12018304] = {
            ["Content"] = "这是我应做的。",
            ["ContentJP"] = "当然のことをしたまでです。",
            ["DialogueId"] = 12018304,
            ["GUID"] = "1E162900",
            ["NextDialogue"] = 12018305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162900",
            },
        [12018305] = {
            ["Content"] = "你没事吧？你看起来脸色好像不太好……",
            ["ContentJP"] = "大丈夫？なんだか顔色が悪いけど……",
            ["DialogueId"] = 12018305,
            ["GUID"] = "1E16292A",
            ["NextDialogue"] = 12018306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E16292A",
            },
        [12018306] = {
            ["Content"] = "我身体无大碍。只是心有点乱，需要静一静，整理一下思绪。",
            ["ContentJP"] = "平気です。ただ、心が乱れておりまして。少し落ち着くので時間をください。",
            ["DialogueId"] = 12018306,
            ["GUID"] = "1E162954",
            ["NextDialogue"] = 12018307,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162954",
            },
        [12018307] = {
            ["Content"] = "好……如果你有什么烦恼想找别人倾诉，我随时在。",
            ["ContentJP"] = "うん……もし、何か話したいことがあったら、いつでも声をかけて。",
            ["DialogueId"] = 12018307,
            ["GUID"] = "1E16297E",
            ["NextDialogue"] = 12018308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E16297E",
            },
        [12018308] = {
            ["Content"] = "那是自然。毕竟经此一遭，你们便是我在世界上唯二的友人了。",
            ["ContentJP"] = "もちろんです。共に窮地を乗り越えた、たった二人の友だちですから。",
            ["DialogueId"] = 12018308,
            ["GUID"] = "1E1629A8",
            ["NextDialogue"] = 12018309,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629A8",
            },
        [12018309] = {
            ["Content"] = "呜呜，扶疏……",
            ["ContentJP"] = "うう……ふーしゅ～…",
            ["DialogueId"] = 12018309,
            ["GUID"] = "1E1629D2",
            ["NextDialogue"] = 12018310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629D2",
            },
        [12018310] = {
            ["Content"] = "好啦。虽然过程有所波折，但所需的药草已经采摘到了。趁着露水还未褪去，我要尽早将其带回，研磨入药。",
            ["ContentJP"] = "さて、多少の意外はありましたが、必要な薬草は無事採取できました。露が乾く前に、調合しないと。",
            ["DialogueId"] = 12018310,
            ["GUID"] = "1E1629FC",
            ["NextDialogue"] = 12018311,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E1629FC",
            },
        [12018311] = {
            ["Content"] = "咿！",
            ["ContentJP"] = "イッ！",
            ["DialogueId"] = 12018311,
            ["GUID"] = "1E162A26",
            ["NextDialogue"] = 12018312,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A26",
            },
        [12018312] = {
            ["Content"] = "哇啊，你从哪里冒出来的！吓我一跳！",
            ["ContentJP"] = "わあっ、あんたどこから！？びっくりしたじゃないか！",
            ["DialogueId"] = 12018312,
            ["GUID"] = "1E162A50",
            ["NextDialogue"] = 12018313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A50",
            },
        [12018313] = {
            ["Content"] = "你竟没有与它们一同离去……",
            ["ContentJP"] = "あら、あなた……仲間と一緒に行かなかったのね……",
            ["DialogueId"] = 12018313,
            ["GUID"] = "1E162A7A",
            ["NextDialogue"] = 12018314,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162A7A",
            },
        [12018314] = {
            ["Content"] = "我在往隙深处偶遇了它，将它顺手带出。这也是一种萍水相逢的缘分吧。",
            ["ContentJP"] = "裂け目の奥で助け出した子です。これも何かの縁でしょう。",
            ["DialogueId"] = 12018314,
            ["GUID"] = "1E162AA4",
            ["NextDialogue"] = 12018315,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162AA4",
            },
        [12018315] = {
            ["Content"] = "咿！咿！",
            ["ContentJP"] = "イッ！イッ！",
            ["DialogueId"] = 12018315,
            ["GUID"] = "1E162ACE",
            ["NextDialogue"] = 12018316,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162ACE",
            },
        [12018316] = {
            ["Content"] = "它看起来好像格外亲近你。",
            ["ContentJP"] = "フーシュ、やけに気に入られてるね。",
            ["DialogueId"] = 12018316,
            ["GUID"] = "1E162AF8",
            ["NextDialogue"] = 12018317,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162AF8",
            },
        [12018317] = {
            ["Content"] = "这可有些头疼了……我接下来需要集中精神，治疗患者的过程中不好受外界打扰。",
            ["ContentJP"] = "困りましたね……私はこれから集中力を高めなければならないので。治療過程中は、なるべく静かな環境が必要なのですが……",
            ["DialogueId"] = 12018317,
            ["GUID"] = "1E162B22",
            ["NextDialogue"] = 12018318,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B22",
            },
        [12018318] = {
            ["Content"] = "{nickname}，可以拜托你先照料它一段时间吗？",
            ["ContentJP"] = "{nickname}さん、しばらくの間、世話をお願いできますか？",
            ["DialogueId"] = 12018318,
            ["GUID"] = "1E162B4C",
            ["NextDialogue"] = 12018319,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B4C",
            },
        [12018319] = {
            ["Content"] = "小跟班的小跟班……那岂不是小跟班二号！",
            ["ContentJP"] = "下僕の下僕って……下僕2号じゃん！",
            ["DialogueId"] = 12018319,
            ["GUID"] = "1E162B76",
            ["NextDialogue"] = 12018320,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162B76",
            },
        [12018320] = {
            ["Content"] = "咿呀咿！咿咿！",
            ["ContentJP"] = "イッ！イーヤッ！イッ！",
            ["DialogueId"] = 12018320,
            ["GUID"] = "1E162BA0",
            ["NextDialogue"] = 12018321,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BA0",
            },
        [12018321] = {
            ["Content"] = "它看起来似乎不太乐意的样子。",
            ["ContentJP"] = "嫌がってるようだけど。",
            ["DialogueId"] = 12018321,
            ["GUID"] = "1E162BCA",
            ["NextDialogue"] = 12018322,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BCA",
            },
        [12018322] = {
            ["Content"] = "……抱歉，是我轻慢了你的想法。既然你我有缘，从今往后，你就跟着我吧。我不会信手将你落下，可好？",
            ["ContentJP"] = "すみません。あなたの気持ちを考えてませんでしたね。これも何かの縁ですし、私と一緒に来ますか？決して置き去りにはしませんよ。",
            ["DialogueId"] = 12018322,
            ["GUID"] = "1E162BF4",
            ["NextDialogue"] = 12018323,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162BF4",
            },
        [12018323] = {
            ["Content"] = "咿！",
            ["ContentJP"] = "イッ！",
            ["DialogueId"] = 12018323,
            ["GUID"] = "1E162C1E",
            ["NextDialogue"] = 12018324,
            ["SnapShot"] = "WUYOU",
            ["SpeakNpcId"] = 210036,
            ["SpeakNpcName"] = "UI_CMName_Name_WuyouWuyan",
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C1E",
            },
        [12018324] = {
            ["Content"] = "{nickname}，无由生长老处也烦请你去回报了。待患者的病情稍有好转，我会再与你们见面的。",
            ["ContentJP"] = "{nickname}さん、すみませんが、長老への報告をお願いしても？患者の容体が良くなったら、会いに行きますので。",
            ["DialogueId"] = 12018324,
            ["GUID"] = "1E162C48",
            ["NextDialogue"] = 12018325,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C48",
            },
        [12018325] = {
            ["Content"] = "那就一言为定了！",
            ["ContentJP"] = "約束だよ！",
            ["DialogueId"] = 12018325,
            ["GUID"] = "1E162C72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120183/1E162C72",
            },
        [12018401] = {
