            },
        [12018406] = {
            ["Camera"] = "-113.994232,54.671646,165.879028,0.000155,-25.60232,96.198647,25.000002,113.956665,false,DoNotOverride,22.0",
            ["Content"] = "呜哇，气氛好紧张……小仆从，要不还是算了吧？",
            ["ContentJP"] = "うへぇ、緊張するよぉ……我が下僕、もういいんじゃない？",
            ["DialogueId"] = 12018406,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["GUID"] = "1E1639BC",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(210012)",
                [3] = "200002:n(100001)",
                },
            ["NextDialogue"] = 12018407,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E1639BC",
            },
        [12018407] = {
            ["Camera"] = "295.454956,542.930176,371.227875,0.000125,-26.204176,-133.401733,24.0,113.956657,false,DoNotOverride,22.0",
            ["Content"] = "哈哈……不卑不亢，据理力争。颇有我年轻时候的风采，我很欣赏。",
            ["ContentJP"] = "はは……卑屈にならず、堂々と理を主張するとは。若き日の私を思わせる風格で、なかなか見事だ。感心したよ。",
            ["DialogueId"] = 12018407,
            ["FacialId"] = {
                [1] = "210012:Ahaha01",
                },
            ["GUID"] = "1E1639E6",
            ["NextDialogue"] = 12018408,
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E1639E6",
            },
        [12018408] = {
            ["Camera"] = "-125.168137,93.99778,144.010498,0.000147,-24.602682,79.995262,25.000002,166.176483,false,Manual,6.0",
            ["Content"] = "……他竟然一下子变脸了！",
            ["ContentJP"] = "……えぇ！？態度変わるの早すぎない！？",
            ["DialogueId"] = 12018408,
            ["GUID"] = "1E163A10",
            ["NextDialogue"] = 12018409,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163A10",
            },
        [12018409] = {
            ["Camera"] = "-95.768387,166.50177,121.84198,0.000135,-26.202879,76.599541,24.0,113.956657,false,DoNotOverride,22.0",
            ["Content"] = "等等，哪有人用这么自恋的方式夸别人啊！简直是自大狂！",
            ["ContentJP"] = "ちょっと待ってよ、さりげなく自分のことほめてない！？ただのナルシストじゃんか！",
            ["DialogueId"] = 12018409,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "1E163A3A",
            ["NextDialogue"] = 12018410,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163A3A",
            },
        [12018410] = {
            ["Camera"] = "64.890961,321.150482,91.39502,0.000176,5.395296,-137.398178,24.0,297.770538,false,Manual,6.0",
            ["Content"] = "路上说吧，你们关心的问题，我都会尽力解答。",
            ["ContentJP"] = "移動しながら話そう。君たちの疑問には、できるだけ答えるつもりだ。",
            ["DialogueId"] = 12018410,
            ["FacialId"] = {
                [1] = "210012:None",
                },
            ["GUID"] = "1E163A64",
            ["LookAt"] = {
                [1] = "100001:n(210012)",
                [2] = "210012:n(200002)",
                [3] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120184/1E163A64",
            },
        [12018501] = {
            ["Content"] = "小友可曾有过疑惑，烛阴之灾为何以玄色狴犴的模样呈现？",
            ["ContentJP"] = "<Default note=\"text:しょくいん\">燭陰</>の禍がなぜ<Default note=\"text:ゲンビー\">玄狴</>となって現れるのか、疑問に思ったことはないかい？",
            ["DialogueId"] = 12018501,
            ["Duration"] = 3,
            ["GUID"] = "1E164952",
            ["NextDialogue"] = 12018502,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164952",
            },
        [12018502] = {
            ["Content"] = "华胥备受崇敬的狴犴，在外界却是引起灾厄和恐惧的秽兽。其间区别，便在于大风九章的约束。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>では敬われる<Default note=\"text:ビーアン\">狴犴</>も、外の世界では災いと恐怖を呼ぶ穢獣。その違いは、大風九章の戒律にあるのだ。",
            ["DialogueId"] = 12018502,
            ["Duration"] = 5,
            ["GUID"] = "1E16497C",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E16497C",
            },
        [12018503] = {
            ["Content"] = "玄色狴犴的出现，只能引向一种猜测——大风九章，如今正在失控。",
            ["ContentJP"] = "<Default note=\"text:ゲンビー\">玄狴</>が現れた今、考えられる可能性は一つ――大風九章は今、制御を失いつつあるということ。",
            ["DialogueId"] = 12018503,
            ["Duration"] = 3,
            ["GUID"] = "1E1649A6",
            ["NextDialogue"] = 12018504,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E1649A6",
            },
        [12018504] = {
            ["Content"] = "但止流掌柜说过，解决了烛阴之灾，这些问题就会正常。",
            ["ContentJP"] = "でも、<Default note=\"text:しょくいん\">燭陰</>の禍さえ乗り越えれば、事態を終息できるってシリュウさんが言ってたけど。",
            ["DialogueId"] = 12018504,
            ["Duration"] = 3,
            ["GUID"] = "1E1649D0",
            ["NextDialogue"] = 12018505,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E1649D0",
            },
        [12018505] = {
            ["Content"] = "是，但那也只能救得了一时。",
            ["ContentJP"] = "ええ。「一時的に」ね。",
            ["DialogueId"] = 12018505,
            ["Duration"] = 2,
            ["GUID"] = "1E1649FA",
            ["NextDialogue"] = 12018506,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E1649FA",
            },
        [12018506] = {
            ["Content"] = "若是烛阴之灾周而复返，长久引得民生积弱呢？",
            ["ContentJP"] = "だが、<Default note=\"text:しょくいん\">燭陰</>の禍が繰り返し発生し、民の暮らしを脅かし続けたら、どうだ？",
            ["DialogueId"] = 12018506,
            ["Duration"] = 3,
            ["GUID"] = "1E164A24",
            ["NextDialogue"] = 12018507,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164A24",
            },
        [12018507] = {
            ["Content"] = "止流掌柜有她的考虑。有些猜测，她未必会与你说。",
            ["ContentJP"] = "シリュウ嬢には彼女なりの考えがある。それをすべて君に話すと思うか？",
            ["DialogueId"] = 12018507,
            ["Duration"] = 3,
            ["GUID"] = "1E164A4E",
            ["NextDialogue"] = 12018508,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164A4E",
            },
        [12018508] = {
            ["Content"] = "在我看来，若是大风九章的根基出了问题，做再多修缮也只是表面功夫。",
            ["ContentJP"] = "私から見れば、大風九章は根本的な問題が発生している。いくら見た目を修繕しても、事態は収まらないだろう。",
            ["DialogueId"] = 12018508,
            ["Duration"] = 3,
            ["GUID"] = "1E164A78",
            ["NextDialogue"] = 12018509,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164A78",
            },
        [12018509] = {
            ["Content"] = "你的意思是，你从一开始就不认同大风九章？",
            ["ContentJP"] = "つまり、あなたは初めから大風九章には反対だったと？",
            ["DialogueId"] = 12018509,
            ["Duration"] = 2,
            ["GUID"] = "1E164AA2",
            ["NextDialogue"] = 12018510,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164AA2",
            },
        [12018510] = {
            ["Content"] = "哈哈哈……小友不用把话说得这么绝对。俗话说得好，知己知彼，方能百战百胜。",
            ["ContentJP"] = "ははは……随分はっきり物を言うな。「己と敵良く知りてこそ、百戦百勝なり」という言葉、聞いたことはあるかい？",
            ["DialogueId"] = 12018510,
            ["Duration"] = 4,
            ["GUID"] = "1E164ACC",
            ["NextDialogue"] = 12018511,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164ACC",
            },
        [12018511] = {
            ["Content"] = "此行的目的是捉来一只狴犴作为我的“收藏品”，试图研究透彻其中原理，做一些两手准备。",
            ["ContentJP"] = "今回の作戦はいたって簡単だ。私の「コレクション」に、<Default note=\"text:ビーアン\">狴犴</>を加えたい。その仕組みを解明し、万全の備えをする手伝いをしてほしいのだよ。",
            ["DialogueId"] = 12018511,
            ["Duration"] = 5,
            ["GUID"] = "1E164AF6",
            ["NextDialogue"] = 12018512,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164AF6",
            },
        [12018512] = {
            ["Content"] = "如何，这个理由，足以说服你吗？",
            ["ContentJP"] = "さて、この理由は、君を動かすに十分といえるかな？",
            ["DialogueId"] = 12018512,
            ["Duration"] = 2,
            ["GUID"] = "1E164B20",
            ["NextDialogue"] = 12018513,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164B20",
            },
        [12018513] = {
            ["Content"] = "……与狴犴为敌，不会招致大风九章的惩罚吗？",
            ["ContentJP"] = "……<Default note=\"text:ビーアン\">狴犴</>に手を出したら、大風九章の罰を受けるんじゃ？",
            ["DialogueId"] = 12018513,
            ["Duration"] = 5,
            ["GUID"] = "1E164B4A",
            ["NextDialogue"] = 12018514,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164B4A",
            },
        [12018514] = {
            ["Content"] = "呵呵，我等黑市中人常年游走于大风九章边缘，自有分寸。",
            ["ContentJP"] = "はは、闇市の者は年中、大風九章の縁を歩いてるんだ。心配には及ばないよ。",
            ["DialogueId"] = 12018514,
            ["Duration"] = 2,
            ["GUID"] = "1E164B74",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120185/1E164B74",
            },
        [12018601] = {
            ["Camera"] = "24.121033,469.795776,75.995605,0.000102,15.589243,-120.015869,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "头儿，您来了！",
            ["ContentJP"] = "お待ちしておりました！",
            ["DialogueId"] = 12018601,
            ["FacialId"] = {
                [1] = "210010:CM_Smile01",
                },
            ["FinalCamera"] = "24.121033,469.795776,75.995605,0.00012,7.589159,-99.01458,25.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "1E1659BA",
            ["NextDialogue"] = 12018602,
            ["RelatedWikiId"] = {
                [1] = 203005,
                },
            ["SpeakNpcId"] = 210010,
            ["SpeakNpcName"] = "UI_CMName_Name_HeiShiXiaoDi",
            ["TalkActionId"] = {
                [1] = "210010:Agree",
                },
            ["ToFinalCameraBlendTime"] = 2.5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E1659BA",
            },
        [12018602] = {
            ["Camera"] = "-136.252167,91.878937,113.345459,0.000122,16.784575,27.185421,35.000011,182.757812,false,Manual,4.0",
            ["Content"] = "情况如何了？",
            ["ContentJP"] = "状況は？",
            ["DialogueId"] = 12018602,
            ["FacialId"] = {
                [1] = "210012:Doubt01",
                },
            ["GUID"] = "1E1659E4",
            ["NextDialogue"] = 12018603,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120186/1E1659E4",
            },
        [12018603] = {
            ["Camera"] = "32.268948,257.847717,186.833252,0.00014,-8.414738,-115.807419,35.000011,279.251068,false,Manual,6.0",
            ["Content"] = "如您所料，那猎物负了伤，已被逼入了听鸦原。这儿四面环海，呈孤岛之势，它逃不掉的。接下来只要瓮中捉鳖就好了！",
            ["ContentJP"] = "御覧の通り、獲物は負傷し、鴉の孤原まで追い詰めました！あそこは海で囲まれてますし、逃げ場はないでしょう。後は囲って捕まえるだけっす！",
            ["DialogueId"] = 12018603,
            ["FacialId"] = {
                [1] = "210010:CM_Idle",
                },
            ["GUID"] = "1E165A0E",
            ["NextDialogue"] = 12018604,
            ["SpeakNpcId"] = 210010,
            ["SpeakNpcName"] = "UI_CMName_Name_HeiShiXiaoDi",
            ["TalkActionId"] = {
                [1] = "210010:Explain01_Start",
                },
