        [12018607] = {
            ["Camera"] = "-14.455,160.474716,158.683838,0.000099,-0.817505,-128.967682,35.0,196.648346,false,Manual,6.0",
            ["Content"] = "属下寻思这里是古战场遗址，平时阴风阵阵的，路人都会绕着走。在这儿行动不容易受打扰……",
            ["ContentJP"] = "こちらは古戦場の遺跡と聞いております。普段は陰気な風が吹き、道行く者も避けて通る場所。ゆえに、一番動きやすいかと思いまして……",
            ["DialogueId"] = 12018607,
            ["FacialId"] = {
                [1] = "210010:CM_Sad01",
                },
            ["GUID"] = "1E165AB6",
            ["NextDialogue"] = 12018608,
