        [12018701] = {
            ["Content"] = "追！",
            ["ContentJP"] = "追え！",
            ["DialogueId"] = 12018701,
            ["GUID"] = "1E166A22",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120187/1E166A22",
            },
        [12018801] = {
            ["Content"] = "这这这是什么从大地里苏醒了……？！好壮观的机关阵！",
            ["ContentJP"] = "なななにこれ……！？地面が目を覚ましたみたい……すっごいからくり！",
            ["DialogueId"] = 12018801,
            ["GUID"] = "1E167A8A",
            ["NextDialogue"] = 12018802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120188/1E167A8A",
            },
        [12018802] = {
            ["Content"] = "虬先生在前面。我们去找他问个明白。",
            ["ContentJP"] = "キョウンさんは前にいるはず。聞いてみよう。",
            ["DialogueId"] = 12018802,
            ["GUID"] = "1E167AB4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120188/1E167AB4",
            },
        [12018901] = {
            ["Camera"] = "1602.116455,-389.513306,871.401367,0.000128,-28.607693,165.210678,18.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "有趣，十足有趣……看来数百年的光阴，也未能将这些上古机括战阵摧折。至今尚能运转如常。",
            ["ContentJP"] = "面白い、実に面白い……。数百年を経ても、この古の機巧戦陣は錆びつくどころか、今なお見事に稼働しているとは。",
            ["DialogueId"] = 12018901,
            ["FacialId"] = {
                [1] = "210012:Smile01",
                },
