        [12018905] = {
            ["Camera"] = "99.821701,41.477108,120.901367,0.00014,11.999624,-174.197815,35.000008,210.213547,false,Manual,6.0",
            ["Content"] = "哼，不解风情。徒费古物之美。",
            ["ContentJP"] = "ちっ、風雅も解さぬか。古の宝の美をまるでわかっていないな。",
            ["DialogueId"] = 12018905,
            ["FacialId"] = {
                [1] = "200002:None",
                [2] = "210012:Doubt01",
                },
            ["GUID"] = "1E168B9A",
            ["NextDialogue"] = 12018906,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{210012},AnimationId{\"Confident_End\"},Duration{2}},",
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "210012:DisagreeHead",
                [2] = "200002:Angry02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168B9A",
            },
        [12018906] = {
            ["Camera"] = "99.821701,41.477108,120.901367,0.00014,11.999624,-174.197815,35.000008,210.213547,false,Manual,6.0",
            ["Content"] = "凡是机关，必留有后手……比如说，眼前这座醒世碑，不觉得它看起来就像是等待人敲的样子吗？",
            ["ContentJP"] = "仕掛けには必ず抜け道が仕込まれるもの……ほら、目の前の醒石碑、まるで叩かれるのを待っているみたいだろう？",
            ["DialogueId"] = 12018906,
            ["GUID"] = "1E168BC4",
            ["LookAt"] = {
                [1] = "210012:n(210012)",
                },
            ["NextDialogue"] = 12018907,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{2},TargetPosition{\"-2599.537109,-2099.010498,495.693359,0.00015,-8.80078,40.403954,18.0,256766.0625,false,DoNotOverride,22.0\"},duration{0}},\
CameraMoveTo{_delay{2.1},TargetPosition{\"-2722.54248,-2203.702393,520.700195,0.00015,-8.80078,40.403954,18.0,256766.0625,false,DoNotOverride,22.0\"},duration{8}},\
CameraMoveTo{_delay{4.5},TargetPosition{\"-6405.689453,-5441.508301,1031.489258,0.000213,13.197038,-140.794937,18.000008,256766.0625,false,DoNotOverride,22.0\"},duration{0}},\
CameraMoveTo{_delay{4.6},TargetPosition{\"-6437.628906,-5467.57373,1041.154297,0.000213,13.197038,-140.794937,18.000008,256766.0625,false,DoNotOverride,22.0\"},duration{6}}\
}",
            ["SpeakNpcId"] = 210012,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["TurnTo"] = {
                [1] = "210012:p(-179)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168BC4",
            },
        [12018907] = {
            ["Camera"] = "-94.359398,-63.731007,207.273438,0.000093,-26.399609,66.203903,20.0,285.160034,false,Manual,6.0",
            ["Content"] = "喂喂，万一猜错了怎么办？！",
            ["ContentJP"] = "ちょっと、間違えたらどうすんの！？",
            ["DialogueId"] = 12018907,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "1E168BEE",
            ["NextDialogue"] = 12018908,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168BEE",
            },
        [12018908] = {
            ["Content"] = "呵呵……那就得仰仗{nickname}矫健的身手了。",
            ["ContentJP"] = "ふっ……その時は、{nickname}の反応の早さだけが頼りかな。",
            ["DialogueId"] = 12018908,
            ["FacialId"] = {
                [1] = "210012:Ahaha01",
                },
            ["GUID"] = "1E168C18",
            ["SpeakNpcId"] = 210012,
            ["TurnTo"] = {
                [1] = "210012:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120189/1E168C18",
            },
        [12019001] = {
            ["Content"] = "我曾听闻，机枢派以赤色为尊。",
            ["ContentJP"] = "機枢派は赤を崇拝していると聞いた。",
            ["DialogueId"] = 12019001,
            ["GUID"] = "1E169B5A",
            ["NextDialogue"] = 12019002,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B5A",
            },
        [12019002] = {
            ["Content"] = "也就是说，红色的道路是安全的。",
            ["ContentJP"] = "つまり、赤い道は安全だってことだね。",
            ["DialogueId"] = 12019002,
            ["GUID"] = "1E169B84",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B84",
            },
        [12019050] = {
            ["Content"] = "好像有些机关块亮起来了……小仆从，这是什么意思？",
            ["ContentJP"] = "あそこの仕掛け、なんか急に光り出したぞ？これは…どういうこと？我が下僕よ、答えばよい。",
            ["DialogueId"] = 12019050,
            ["GUID"] = "1E169B85",
            ["NextDialogue"] = 12019051,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B85",
            },
        [12019051] = {
            ["Content"] = "用意很明显了。顺着机关块亮起的顺序前行，就能破解当下的困局。",
            ["ContentJP"] = "もう明白だろう？光った順にブロックを辿れば、この状況は解けるさ。",
            ["DialogueId"] = 12019051,
            ["GUID"] = "1E169B86",
            ["NextDialogue"] = 12019052,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B86",
            },
        [12019052] = {
            ["Content"] = "……这种事情不需要你提醒，我们小仆从也知道！",
            ["ContentJP"] = "…そんなこと、言わなくてもうちの下僕には分かるよ。",
            ["DialogueId"] = 12019052,
            ["GUID"] = "1E169B87",
            ["NextDialogue"] = 12019053,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B87",
            },
        [12019053] = {
            ["Content"] = "好，那我试试。",
            ["ContentJP"] = "……じゃあ、やってみるよ。",
            ["DialogueId"] = 12019053,
            ["GUID"] = "1E169B88",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B88",
            },
        [12019054] = {
            ["Content"] = "哇啊啊啊啊，这些机关块怎么还会动，要是不小心踩空就摔下去了！",
            ["ContentJP"] = "うわ、わわわ！ブロックが動いてる！一歩間違ったら落ちてしまうよ！",
            ["DialogueId"] = 12019054,
            ["GUID"] = "1E169B89",
            ["NextDialogue"] = 12019055,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B89",
            },
        [12019055] = {
            ["Content"] = "魔王大人英明一世，差点阴沟里翻船……实在是太阴险了！",
            ["ContentJP"] = "危ないとこだった！…この魔王を謀ったな。なんて卑怯なやつだ！",
            ["DialogueId"] = 12019055,
            ["GUID"] = "1E169B91",
            ["NextDialogue"] = 12019056,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B91",
            },
        [12019056] = {
            ["Content"] = "呵呵。若是难度不升级，何谈挑战呢？",
            ["ContentJP"] = "ははっ、先が読める道なんて、試練とは呼べないよな。",
            ["DialogueId"] = 12019056,
            ["GUID"] = "1E169B92",
            ["NextDialogue"] = 12019057,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B92",
            },
        [12019057] = {
            ["Content"] = "哼，轮不到你来说！",
            ["ContentJP"] = "ふんだ。お前が言うな！",
            ["DialogueId"] = 12019057,
            ["GUID"] = "1E169B93",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B93",
            },
        [12019058] = {
            ["Content"] = "呀！哪里冒出来的家伙，会动……还打我们！",
            ["ContentJP"] = "きゃあっ！！こやつら、一体どこから出てきたんだ！？う、動いってる…いや、襲ってきた！",
            ["DialogueId"] = 12019058,
            ["GUID"] = "1E169B94",
            ["NextDialogue"] = 12019059,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B94",
            },
        [12019059] = {
            ["Content"] = "想必是此地设计之初留下来的守备力量，用以防御外来的入侵者。",
            ["ContentJP"] = "どうやら、ここが造られた頃から残ってる守り手のようだ。侵入者を弾くためのやつだな。",
            ["DialogueId"] = 12019059,
            ["GUID"] = "1E169B95",
            ["NextDialogue"] = 12019060,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B95",
            },
        [12019060] = {
            ["Content"] = "提起精神应对他们，{nickname}。",
            ["ContentJP"] = "気を抜くなよ。やつらを片づけよう、{nickname}！",
            ["DialogueId"] = 12019060,
            ["GUID"] = "1E169B96",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120190/1E169B96",
            },
        [12019101] = {
            ["Content"] = "咦，同时出现了两座一模一样的醒世碑……",
            ["ContentJP"] = "あれ、まったく同じ醒石碑が現れたけど……",
            ["DialogueId"] = 12019101,
            ["GUID"] = "1E16ABC2",
            ["NextDialogue"] = 12019102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120191/1E16ABC2",
            },
        [12019102] = {
            ["Content"] = "嗯……莫非是需要二人分处两地，同时敲响。",
            ["ContentJP"] = "もしかすると、二人で別れて同時に叩く必要があるのかもしれん。",
            ["DialogueId"] = 12019102,
            ["GUID"] = "1E16ABEC",
            ["NextDialogue"] = 12019103,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120191/1E16ABEC",
            },
        [12019103] = {
            ["Content"] = "{nickname}，且与我一试。",
            ["ContentJP"] = "{nickname}、試してみるかい？",
            ["DialogueId"] = 12019103,
            ["GUID"] = "1E16AC16",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120191/1E16AC16",
            },
        [12019201] = {
            ["Content"] = "哇啊啊啊啊啊啊啊——白、白的屁股，摔得好痛！",
            ["ContentJP"] = "ぎゃああああぁぁぁ！いっ、いたたた……お尻が……",
            ["DialogueId"] = 12019201,
            ["GUID"] = "1E16BC2A",
            ["NextDialogue"] = 12019202,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BC2A",
            },
        [12019202] = {
            ["Content"] = "虬先生不知道掉到哪里去了……",
            ["ContentJP"] = "キョウンのやつはどこに……",
            ["DialogueId"] = 12019202,
            ["GUID"] = "1E16BC54",
            ["NextDialogue"] = 12019203,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BC54",
            },
        [12019203] = {
            ["Content"] = "难道说，这个机关战阵的用意就是把同行者分开……？",
            ["ContentJP"] = "まさか、この仕掛けの目的は、同行者を分けることだった……？",
            ["DialogueId"] = 12019203,
            ["GUID"] = "1E16BC7E",
            ["NextDialogue"] = 12019204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BC7E",
            },
        [12019204] = {
            ["Content"] = "等等，小仆从！前面有人！",
            ["ContentJP"] = "あれ、見て！あそこに誰かいるよ！",
            ["DialogueId"] = 12019204,
            ["GUID"] = "1E16BCA8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120192/1E16BCA8",
            },
        [12019301] = {
            ["Content"] = "真好，有人来了！这下不仅是我一人困在这里了。",
            ["ContentJP"] = "おっと、こりゃいい！一人で退屈してたとこなんだ。",
            ["DialogueId"] = 12019301,
            ["GUID"] = "1E16CC92",
            ["NextDialogue"] = 12019302,
            ["SpeakNpcId"] = 210021,
            ["SpeakNpcName"] = "UI_CMName_Name_SaTuoBuJi",
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CC92",
            },
        [12019302] = {
            ["Content"] = "我名刻舟，华胥一介飘零人是也。敢问两位姓名？",
            ["ContentJP"] = "俺はカシュウ。<Default note=\"text:カショ\">華胥</>の流れ者だ。あんたらは？",
            ["DialogueId"] = 12019302,
            ["GUID"] = "1E16CCBC",
            ["NextDialogue"] = 12019303,
            ["RelatedWikiId"] = {
                [1] = 203007,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CCBC",
            },
        [12019303] = {
            ["Content"] = "那……我是纯白的救赎☆光之魔王大人，简称白。如你所见，是一名魔王！征服世界的事找我就对了！",
            ["ContentJP"] = "へ、ああ……ゴッホン！私は純白の救い手☆そして光の魔王様！名をスノウと申す！世界征服関連のことは何でも質問して良いぞ！",
            ["DialogueId"] = 12019303,
            ["GUID"] = "1E16CCE6",
            ["NextDialogue"] = 12019304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CCE6",
            },
        [12019304] = {
            ["Content"] = "这位是我的小仆从，{nickname}。{性别：他|她}是仅次于白的最厉害的人！",
            ["ContentJP"] = "こっちは我が下僕、{nickname}なり！スノウの次にすごい人だぞ！",
            ["DialogueId"] = 12019304,
            ["GUID"] = "1E16CD10",
            ["NextDialogue"] = 12019305,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD10",
            },
        [12019305] = {
            ["Content"] = "哦哦……！原来如此！难怪我以随身的枪戟剑林将此地翻来覆去轰了几遍，都没能撼动分毫……竟是要敲击这里。话说回来，这机枢派的造物可真结实。",
            ["ContentJP"] = "ほぅ！なるほど！どうりで、持ってた槍やら剣やらを全部突き立てても、びくともしなかったわけだ、叩く場所を間違えてたんだな。さすがは機枢派の仕掛け、想像以上に頑丈だぜ。",
            ["DialogueId"] = 12019305,
            ["GUID"] = "120193141.0",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193141",
            },
        [12019306] = {
            ["Content"] = "幸会幸会……原来华胥之外的地方，还有如此拉风的职业！相逢即是有缘，何不结伴一程？",
            ["ContentJP"] = "どうもどうも……それにしても、<Default note=\"text:カショ\">華胥</>の外にはこんなイカした職業があったのか！せっかくだし、一緒に旅でもするか？",
            ["DialogueId"] = 12019306,
            ["GUID"] = "120193051.0",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193051",
            },
        [12019307] = {
            ["Content"] = "既然你如此仰慕魔王大人，那当然好！哼哼，还是华胥人有品位！",
            ["ContentJP"] = "ふふん、魔王を慕う者に悪いヤツなし！いいだろう！<Default note=\"text:カショ\">華胥</>人はやっぱりセンスがいいね！",
            ["DialogueId"] = 12019307,
            ["GUID"] = "1E16CD8E",
            ["NextDialogue"] = 12019308,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD8E",
            },
        [12019308] = {
            ["Content"] = "这样吧，白册封你为“黑白毛色的侠客，不羁的剑歌浪子，魔王国驻华胥外交大使”！",
            ["ContentJP"] = "ではでは、この際お前を「白黒流離いの剣士・魔王国駐在<Default note=\"text:カショ\">華胥</>外交官」に任命してやろう！",
            ["DialogueId"] = 12019308,
            ["GUID"] = "1E16CDB8",
            ["NextDialogue"] = 12019309,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CDB8",
            },
        [12019309] = {
            ["Content"] = "哈哈……结交两位，刻舟心中痛快不已！若不是困于此处，简直想舞剑助兴，与君畅饮至天明！",
            ["ContentJP"] = "ハハハ……それにしても、こんなところで会えてうれしいよ！ここで足止めさえされていなければ、剣の舞いを余興に一晩飲み明かしたいくらいだ！",
            ["DialogueId"] = 12019309,
            ["GUID"] = "1E16CDE2",
            ["NextDialogue"] = 12019310,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CDE2",
            },
        [12019310] = {
            ["Content"] = "对了，你们来时，有见过一名与我年岁相仿的男子吗？我好不容易追他的踪迹到这里。他黑发，穿一身墨色衣服，很好认的！",
            ["ContentJP"] = "ところで道中、俺と同じくらいの男をみなかったか？やつの痕跡を辿ってここまできたんだ。全身黒い服を着てるから、すぐわかると思うんだが……",
            ["DialogueId"] = 12019310,
            ["GUID"] = "1E16CE0C",
            ["NextDialogue"] = 12019311,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE0C",
            },
        [12019311] = {
            ["Content"] = "这样的人，满大街都是吧……",
            ["ContentJP"] = "そんなの、どこにでもいるでしょ……",
            ["DialogueId"] = 12019311,
            ["GUID"] = "1E16CE36",
            ["NextDialogue"] = 12019312,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE36",
            },
        [12019312] = {
            ["Content"] = "我们来的路上，没见到别人。",
            ["ContentJP"] = "ここに来るまで、誰にも会ってないよ。",
            ["DialogueId"] = 12019312,
            ["GUID"] = "1E16CE60",
            ["NextDialogue"] = 12019313,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE60",
            },
        [12019313] = {
            ["Content"] = "唉……罢了。找了四年了，也不差这一时半会儿。那你们知道该如何从这儿出去吗？",
            ["ContentJP"] = "はぁ……そうか。もう4年も探してたんだ、一時を焦る必要はねぇな。ところで、出口がどこかわかるか？",
            ["DialogueId"] = 12019313,
            ["GUID"] = "1E16CE8A",
            ["NextOptions"] = {
                [1] = 12019314,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CE8A",
            },
        [12019314] = {
            ["Content"] = "（告知机关诀窍）",
            ["ContentJP"] = "（仕掛けのことを教える）",
            ["DialogueId"] = 12019314,
            ["GUID"] = "1E16CEB4",
            ["NextDialogue"] = 120193141,
            },
        [12019315] = {
            ["Content"] = "你好。",
            ["ContentJP"] = "こんにちは。",
            ["DialogueId"] = 12019315,
            ["GUID"] = "12019315",
            },
        [12019316] = {
            ["Content"] = "好暴力狂的发言！",
            ["ContentJP"] = "物騒な発言だな、おい！",
            ["DialogueId"] = 12019316,
            ["GUID"] = "1E16CF08",
            ["NextDialogue"] = 12019317,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CF08",
            },
        [12019317] = {
            ["Content"] = "要是凡事都真能靠打一架解决就好了……那一切就简单多了。",
            ["ContentJP"] = "はぁ……何事も拳で片がつくなら、世の中どれほど楽か。",
            ["DialogueId"] = 12019317,
            ["GUID"] = "1E16CF32",
            ["NextDialogue"] = 12019318,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CF32",
            },
        [12019318] = {
            ["Content"] = "唉，多说无益，我们还是赶紧逃出去吧。",
            ["ContentJP"] = "これ以上言ってもしょうがねぇか、さっさと脱出しようぜ。",
            ["DialogueId"] = 12019318,
            ["GUID"] = "1E16CF5C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CF5C",
            },
        [12019401] = {
            ["Content"] = "机关块活过来了！{nickname}，不愧是你。",
            ["ContentJP"] = "お！仕掛けが動き出したぜ！さすがだな、{nickname}！",
            ["DialogueId"] = 12019401,
            ["GUID"] = "1E16DCFA",
            ["NextDialogue"] = 12019402,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120194/1E16DCFA",
            },
        [12019402] = {
            ["Content"] = "诶，它们排列的图案……是什么意思呢？",
            ["ContentJP"] = "ん～？この模様……何か意味があるのかな？",
            ["DialogueId"] = 12019402,
            ["GUID"] = "1E16DD24",
            ["NextDialogue"] = 12019403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120194/1E16DD24",
            },
        [12019403] = {
            ["Content"] = "如果踩上对应的机关块……或许可以到对岸去？",
            ["ContentJP"] = "正しいタイルを踏めば、向こう側まで行けるかも。",
            ["DialogueId"] = 12019403,
            ["GUID"] = "1E16DD4E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120194/1E16DD4E",
            },
        [12019501] = {
            ["Content"] = "活动筋骨的时候到了！",
            ["ContentJP"] = "腕が鳴るぜ！！",
            ["DialogueId"] = 12019501,
            ["GUID"] = "1E16ED62",
            ["NextDialogue"] = 12019502,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120195/1E16ED62",
            },
        [12019502] = {
            ["Content"] = "此前被关在这，做什么都不得劲……要说打架我可就不困了！{nickname}，你看好了！",
            ["ContentJP"] = "ずっと閉じ込められて、うずうずしてたとこなんだ……一気に目がさえたぜ！{nickname}、よーく見てな！",
            ["DialogueId"] = 12019502,
            ["GUID"] = "1E16ED8C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120195/1E16ED8C",
            },
        [12019601] = {
            ["Content"] = "这些机关块的排列……怎么越来越复杂了？看得我头晕眼花的。",
            ["ContentJP"] = "この仕掛けの並び方……どんどん複雑になってないか？目が回ってきたぜ。",
            ["DialogueId"] = 12019601,
            ["GUID"] = "1E16FDCA",
            ["NextDialogue"] = 12019602,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FDCA",
            },
        [12019602] = {
            ["Content"] = "哼哼……大个子只会用蛮力，还得我们小仆从来！",
            ["ContentJP"] = "ふん……まったく頭でっかちは武力しか取柄ないんだから！我が下僕に任せて！",
            ["DialogueId"] = 12019602,
            ["GUID"] = "1E16FDF4",
            ["NextDialogue"] = 12019603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FDF4",
            },
        [12019603] = {
            ["Content"] = "对对，全仰仗你了，{nickname}！",
            ["ContentJP"] = "はいはい、頼りにしてますぜ、{nickname}！",
            ["DialogueId"] = 12019603,
            ["GUID"] = "1E16FE1E",
            ["NextDialogue"] = 12019604,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE1E",
            },
        [12019604] = {
            ["Content"] = "……真拿你们没办法。",
            ["ContentJP"] = "まったくしょうがないな。",
            ["DialogueId"] = 12019604,
            ["GUID"] = "1E16FE48",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE48",
            },
        [12019605] = {
            ["Content"] = "小仆从，空中悬着的那个球看起来有点奇怪。要不要用牵机方枢试试看？",
            ["ContentJP"] = "ねぇ、下僕、あの宙に浮いてるボール、なんだか変じゃない？機巧制御盤、使ってみたら？",
            ["DialogueId"] = 12019605,
            ["GUID"] = "1E16FE72",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE72",
            },
        [12019606] = {
            ["Content"] = "竟一下就飞跃过来了，畅快！",
            ["ContentJP"] = "おぉ、一気に飛んでこれたぞ！こりゃいい！",
            ["DialogueId"] = 12019606,
            ["GUID"] = "1E16FE9C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE9C",
            },
        [12019610] = {
            ["Content"] = "好眼熟……小仆从，这不是公尚师傅教过我们的机关吗？竟然在这里也出现了！",
            ["ContentJP"] = "何だか見覚えがあるような……あれ、コウショウが教えてくれたトラップじゃないか？ここにもあるな",
            ["DialogueId"] = 12019610,
            ["GUID"] = "1E16FE9F",
            ["NextDialogue"] = 12019611,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FE9F",
            },
        [12019611] = {
            ["Content"] = "我们赶紧用那个牵机方枢试试看吧！",
            ["ContentJP"] = "さっそく機巧制御盤を使ってみよ",
            ["DialogueId"] = 12019611,
            ["GUID"] = "1E16FF11",
            ["NextDialogue"] = 12019612,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF11",
            },
        [12019612] = {
            ["Content"] = "千机……方什么输？这莫非是某柄上等宝剑的名字？",
            ["ContentJP"] = "きこうせいぎょって…上等な剣の名前か？",
            ["DialogueId"] = 12019612,
            ["GUID"] = "1E16FF12",
            ["NextDialogue"] = 12019613,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF12",
            },
        [12019613] = {
            ["Content"] = "没文化，这可是最新最劲的机枢派造物！你就站着瞧吧！",
            ["ContentJP"] = "勉強が足りないな。これはな、機枢派たちによって造られた、最新かつ最強の秘宝なんだ！見ていたまえ！",
            ["DialogueId"] = 12019613,
            ["GUID"] = "1E16FF13",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF13",
            },
        [12019616] = {
            ["Content"] = "如此轻易就能化解谜题，跟你们可真是跟对人了！",
            ["ContentJP"] = "こんな簡単に謎を解けるとは…やっぱりお前らについていくのは正しい選択だったな！",
            ["DialogueId"] = 12019616,
            ["GUID"] = "1E16FF14",
            ["NextDialogue"] = 12019617,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF14",
            },
        [12019617] = {
            ["Content"] = "哼哼，那可不！",
            ["ContentJP"] = "ふふん、当たり前でしょ！",
            ["DialogueId"] = 12019617,
            ["GUID"] = "1E16FF15",
            ["NextDialogue"] = 12019618,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF15",
            },
        [12019618] = {
            ["Content"] = "大个子，你要紧紧跟好我们。你要是走丢了，我们可帮不了你。",
            ["ContentJP"] = "頭でっかち、私たちにちゃんとついててな。もし見失っても、知らないからな。",
            ["DialogueId"] = 12019618,
            ["GUID"] = "1E16FF16",
            ["NextDialogue"] = 12019619,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF16",
            },
        [12019619] = {
            ["Content"] = "（不妙，白好像越来越得意了……她的尾巴都要翘到天上了！）",
            ["ContentJP"] = "(やばい、どんどん天狗になっていく…)",
            ["DialogueId"] = 12019619,
            ["GUID"] = "1E16FF17",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120196/1E16FF17",
            },
        [12019701] = {
            ["Content"] = "又出现了……这醒世碑需要两人同时敲击，之后脚下平台会翻转，让我们掉到不同的地方。",
            ["ContentJP"] = "この醒石碑は二人で同時に叩く必要がある。その後、足元の地面が動いて、{性别:僕|私}たちを別の場所に落とす仕掛けになってるんだ。",
            ["DialogueId"] = 12019701,
            ["GUID"] = "1E170E32",
            ["NextDialogue"] = 12019702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120197/1E170E32",
            },
        [12019702] = {
            ["Content"] = "那先就此别过啦。多谢两位带我一路，改日再会！",
            ["ContentJP"] = "じゃあ、ここでひとまずお別れか。随分世話になったな、ありがとよ。またいつか会おう！",
            ["DialogueId"] = 12019702,
            ["GUID"] = "1E170E5C",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120197/1E170E5C",
            },
        [12019800] = {
            ["Content"] = "虬先生就在前面。【废弃】",
            ["DialogueId"] = 12019800,
            ["GUID"] = "1E170E5D",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E170E5D",
            },
        [12019801] = {
            ["Content"] = "将分开时的经历告知了虬先生。",
            ["ContentJP"] = "別れていた間の出来事を、キョウンに伝えた。",
            ["DialogueId"] = 12019801,
            ["GUID"] = "1E171E9A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171E9A",
            },
        [12019802] = {
            ["Content"] = "竟这般节外生枝……呵呵，这场捕猎，越来越趣味横生了。",
            ["ContentJP"] = "ほう……とんだ横槍だな。面白い――此度の討伐、ますます愉快になりそうだ。",
            ["DialogueId"] = 12019802,
            ["GUID"] = "1E171EC4",
            ["NextDialogue"] = 12019803,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171EC4",
            },
        [12019803] = {
            ["Content"] = "在这里待久了，也有些腻味了。我们还是动身向前，趁早离开此地吧。",
            ["ContentJP"] = "長く留まりすぎたな。さすがに少々、飽いてきた。そろそろ先に進もうか。",
            ["DialogueId"] = 12019803,
            ["GUID"] = "1E171EEE",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171EEE",
            },
        [12019804] = {
            ["Content"] = "呵呵……瞧你们使用这机枢派的宝贝，是越来越熟练了。怎么样，还喜欢不？",
            ["ContentJP"] = "ふっ……見れば見るほど、君たちもこの機枢派の宝物の扱いに馴れてきたようだな。気に入ったかね？",
            ["DialogueId"] = 12019804,
            ["Duration"] = 3,
            ["GUID"] = "1E171F18",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F18",
            },
        [12019805] = {
            ["Content"] = "眼前看来就是最后的考验了。走吧，{nickname}。该结束这一切了。",
            ["ContentJP"] = "どうやら、目の前にあるのが最後の試練のようだ。さぁ、決着をつけようではないか。",
            ["DialogueId"] = 12019805,
            ["Duration"] = 2,
            ["GUID"] = "1E171F42",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F42",
            },
        [12019810] = {
            ["Content"] = "这个青铜大家伙是什么？！",
            ["ContentJP"] = "なんだこのでかいやつは？",
            ["DialogueId"] = 12019810,
            ["GUID"] = "1E171F43",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F43",
            },
        [12019811] = {
            ["Content"] = "此乃上古机枢派造物，名为<H>巨阙</>。",
            ["ContentJP"] = "これは「巨闕」なんだ。古代の機枢派によって造り上げたもの。",
            ["DialogueId"] = 12019811,
            ["GUID"] = "1E171F44",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F44",
            },
        [12019812] = {
            ["Content"] = "传闻中，机枢派曾想研制出能让人类驾驶的巨大人形机傀，巨阙是这种尝试留下的痕迹之一。",
            ["ContentJP"] = "噂によると、機枢派は昔、人が乗って操れる巨大な人型のからくり人形を\
開発しようとしていたらしい。――たぶん、こいつはあの計画で残されたもの。",
            ["DialogueId"] = 12019812,
            ["GUID"] = "1E171F45",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F45",
            },
        [12019813] = {
            ["Content"] = "诶，听起来还有点拉风呢……",
            ["ContentJP"] = "へ、そうなの？なんかすごいね…",
            ["DialogueId"] = 12019813,
            ["GUID"] = "1E171F46",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F46",
            },
        [12019814] = {
            ["Content"] = "要是有那种能驾驶的机傀存在，魔王大人也想试一试！",
            ["ContentJP"] = "乗って操れるからくり人形って、もしあったら、この魔王スノウも乘ってみたい！",
            ["DialogueId"] = 12019814,
            ["GUID"] = "1E171F47",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120198/1E171F47",
            },
        }
  end },
  { MinKey = 12019901, MaxKey = 12022514, Loader = function()
      return {
        [12019901] = {
            ["Content"] = "这场你追我逃的游戏……该到此为止了。你说是吗，应天尉？",
            ["ContentJP"] = "鬼ごっこもそろそろお開きの時間だ。そうだろう、<Default note=\"text:おうてんい\">応天尉</>？",
            ["DialogueId"] = 12019901,
            ["GUID"] = "1E172F02",
            ["NextDialogue"] = 12019902,
            ["RelatedWikiId"] = {
                [1] = 203005,
                [2] = 203004,
                },
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172F02",
            },
        [12019902] = {
            ["Content"] = "……",
            ["ContentJP"] = "ぜぇ……ぜぇ……",
            ["DialogueId"] = 12019902,
            ["GUID"] = "1E172F2C",
            ["NextDialogue"] = 12019903,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172F2C",
            },
        [12019903] = {
            ["Content"] = "煜明……怎么是你？！",
            ["ContentJP"] = "ユーミン！？",
            ["DialogueId"] = 12019903,
            ["GUID"] = "1E172F56",
            ["NextDialogue"] = 12019904,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172F56",
            },
        [12019904] = {
            ["Content"] = "你所说的“狴犴”，难不成就是他？",
            ["ContentJP"] = "あなたが言ってた「<Default note=\"text:ビーアン\">狴犴</>」って、まさか彼じゃないよね？",
            ["DialogueId"] = 12019904,
            ["GUID"] = "1E172F80",
            ["NextDialogue"] = 12019905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172F80",
            },
        [12019905] = {
            ["Content"] = "又玩文字游戏是吧。对不起，我不干了。",
            ["ContentJP"] = "卑怯なやり手{性别:だな|ね}。悪いけど、降りさせてもらうよ。",
            ["DialogueId"] = 12019905,
            ["GUID"] = "1E172FAA",
            ["NextDialogue"] = 12019906,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172FAA",
            },
        [12019906] = {
            ["Content"] = "就算是魔王大人，也是有底线的！",
            ["ContentJP"] = "この魔王様だって、なんでもアリってわけじゃないからな！",
            ["DialogueId"] = 12019906,
            ["GUID"] = "1E172FD4",
            ["NextDialogue"] = 12019907,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172FD4",
            },
        [12019907] = {
            ["Content"] = "小友先熄熄火气。",
            ["ContentJP"] = "落ち着きたまえ。",
            ["DialogueId"] = 12019907,
            ["GUID"] = "1E172FFE",
            ["NextDialogue"] = 12019908,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E172FFE",
            },
        [12019908] = {
            ["Content"] = "你们一个两个怎么都表现得如同我要取他性命？恰恰相反，我是想提供一个助他解脱大风九章束缚的机会。",
            ["ContentJP"] = "まるで私が彼を殺そうとしているかのような言い草だな。むしろ逆だよ。私は彼を、大風九章の束縛から解き放ちたいと思ってるんだ。",
            ["DialogueId"] = 12019908,
            ["GUID"] = "1E173028",
            ["NextDialogue"] = 12019909,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E173028",
            },
        [12019909] = {
            ["Content"] = "那你问过他的意见吗？",
            ["ContentJP"] = "彼の意見は聞いたの？",
            ["DialogueId"] = 12019909,
            ["GUID"] = "1E173052",
            ["NextDialogue"] = 12019910,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E173052",
            },
        [12019910] = {
            ["Content"] = "你的所作所为，已经危害到了苍生社稷。还请速速收手。",
            ["ContentJP"] = "あんたの所業は、世を危険にさらすだけだ。……今すぐ手を引け。",
            ["DialogueId"] = 12019910,
            ["GUID"] = "1E17307C",
            ["NextDialogue"] = 12019911,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E17307C",
            },
        [12019911] = {
            ["Content"] = "呵呵……是我在危害苍生社稷，还是这世道本身就分崩离析？大风九章所引发的种种弊端，你便视而不见吗？",
            ["ContentJP"] = "くくく……私が世を危険に？この世はとうに崩壊寸前だ、違うか？大風九章が生んだ数々の歪みに、君はなぜ目を背ける？",
            ["DialogueId"] = 12019911,
            ["GUID"] = "1E1730A6",
            ["NextDialogue"] = 12019912,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E1730A6",
            },
        [12019912] = {
            ["Content"] = "若是能藉由你转化为应天尉的原理，从中掌握对付玄色狴犴的后手，也助你重获自由身。岂不是一桩美事？",
            ["ContentJP"] = "<Default note=\"text:おうてんい\">応天尉</>の仕組みを解明すれば、<Default note=\"text:ゲンビー\">玄狴</>に対抗する術を得られるかもしれん。同時に、君は晴れて自由の身だ。一石二鳥だと思わんか？",
            ["DialogueId"] = 12019912,
            ["GUID"] = "1E1730D0",
            ["NextDialogue"] = 12019913,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E1730D0",
            },
        [12019913] = {
            ["Content"] = "……此事非你所当虑。",
            ["ContentJP"] = "……あんたには関係ないことだ。",
            ["DialogueId"] = 12019913,
            ["GUID"] = "1E1730FA",
            ["NextDialogue"] = 12019914,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E1730FA",
            },
        [12019914] = {
            ["Content"] = "他已经表达了不愿意，那我就不能帮你。",
            ["ContentJP"] = "彼は拒絶してる。さっきも言ったように、{性别:僕|私}は降りる{性别:よ|わ}。",
            ["DialogueId"] = 12019914,
            ["GUID"] = "1E173124",
            ["NextDialogue"] = 12019915,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E173124",
            },
        [12019915] = {
            ["Content"] = "又是无聊的仁义道德。啧……本不想用这种手段。",
            ["ContentJP"] = "都合のいい時だけ義理や道徳を持ち出す、実にくだらん。こんな手は使いたくなかったのだがな。",
            ["DialogueId"] = 12019915,
            ["GUID"] = "1E17314E",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120199/1E17314E",
            },
        [12020001] = {
            ["Content"] = "你……你干什么？！",
            ["ContentJP"] = "なっ……急に何するんだよ！？",
            ["DialogueId"] = 12020001,
            ["Duration"] = 2,
            ["GUID"] = "1E173F6A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120200/1E173F6A",
            },
        [12020002] = {
            ["Content"] = "{nickname}，你不愿对他出手，他却是要对你亮出兵戈了。",
            ["ContentJP"] = "{nickname}よ、その善意、果たして報われるかな？",
            ["DialogueId"] = 12020002,
            ["Duration"] = 3,
            ["GUID"] = "1E173F94",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120200/1E173F94",
            },
        [12020003] = {
            ["Content"] = "如何，那边的应天尉？受害者已经出现了，你便只袖手旁观吗？这可不符合大风九章的规矩！",
            ["ContentJP"] = "さて、<Default note=\"text:おうてんい\">応天尉</>、見ての通り私はこの者によってケガを負わされた。大風九章に反する行為を、黙って見ているつもりかい？",
            ["DialogueId"] = 12020003,
            ["Duration"] = 5,
            ["GUID"] = "1E173FBE",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120200/1E173FBE",
            },
        [12020004] = {
            ["Content"] = "……无耻！！明明你才是动手的那个！",
            ["ContentJP"] = "……卑怯者！先に手を出したのはそっちなのに！",
            ["DialogueId"] = 12020004,
            ["Duration"] = 3,
            ["GUID"] = "1E173FE8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120200/1E173FE8",
            },
        [12020005] = {
            ["Content"] = "哈哈哈……！只认古板的伤人事实，却不论伤人动机和公理。应天尉，你所捍卫的便是这等死物吗？",
            ["ContentJP"] = "くっははは！傷つけた結果は咎めるが、その動機や理は顧みぬ。<Default note=\"text:おうてんい\">応天尉</>よ、その血も涙もない掟を守ってるのは……確か君だったか？",
            ["DialogueId"] = 12020005,
            ["Duration"] = 5,
            ["GUID"] = "1E174012",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120200/1E174012",
            },
        [12020006] = {
            ["Content"] = "……{nickname}，得罪了。这并非我愿。",
            ["ContentJP"] = "{nickname}……すまない。",
            ["DialogueId"] = 12020006,
            ["Duration"] = 2,
            ["GUID"] = "1E17403C",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120200/1E17403C",
            },
        [12020101] = {
            ["Content"] = "看好我的招式，仔细躲闪。",
            ["ContentJP"] = "俺の動きをよく見て、避けてくれ。",
            ["DialogueId"] = 12020101,
            ["Duration"] = 2,
            ["GUID"] = "1E174FD2",
            ["NextDialogue"] = 12020102,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174FD2",
            },
        [12020102] = {
            ["Content"] = "我会尽力违抗大风九章的命令……别受伤了。",
            ["ContentJP"] = "できるだけ大風九章に抗ってみる……だからどうか、ケガをしないでくれ、頼む。",
            ["DialogueId"] = 12020102,
            ["Duration"] = 3,
            ["GUID"] = "1E174FFC",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174FFC",
            },
        [12020103] = {
            ["Content"] = "{nickname}，下一击要来了……当心。",
            ["ContentJP"] = "次が来るぞ！気をつけろ！{nickname}。",
            ["DialogueId"] = 12020103,
            ["GUID"] = "1E174FFD",
            ["NextDialogue"] = 12020104,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174FFD",
            },
        [12020104] = {
            ["Content"] = "应天尉的攻势也太猛了！大风九章的力量竟然这么厉害……",
            ["ContentJP"] = "<Default note=\"text:おうてんい\">応天尉</>の攻撃が激しすぎる！こんなに強いか大風九章の力は……",
            ["DialogueId"] = 12020104,
            ["GUID"] = "1E174FFF",
            ["NextDialogue"] = 12020105,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174FFF",
            },
        [12020105] = {
            ["Content"] = "怎么办，小仆从，你还好吗？",
            ["ContentJP"] = "どうしよう、下僕は……大丈夫？",
            ["DialogueId"] = 12020105,
            ["GUID"] = "1E174111",
            ["NextDialogue"] = 12020106,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174111",
            },
        [12020106] = {
            ["Content"] = "放心，我还能应付。煜明，你没事吗？",
            ["ContentJP"] = "安心して、まだ平気。ユーミン、無事なの{性别:か|}？",
            ["DialogueId"] = 12020106,
            ["GUID"] = "1E174112",
            ["NextDialogue"] = 12020107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174112",
            },
        [12020107] = {
            ["Content"] = "……你无需顾虑我。我会尽早结束此番闹剧。",
            ["ContentJP"] = "…俺のこと心配するな。この茶番を早く終わらせてやる。",
            ["DialogueId"] = 12020107,
            ["GUID"] = "1E174113",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174113",
            },
        [12020108] = {
            ["Content"] = "呜，你们别再打了……",
            ["ContentJP"] = "嫌だ。ふたりともやめて…",
            ["DialogueId"] = 12020108,
            ["GUID"] = "1E174114",
            ["NextDialogue"] = 12020109,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174114",
            },
        [12020109] = {
            ["Content"] = "两个人明明好好的，结果不得不打起来，气死我了！",
            ["ContentJP"] = "あんなに仲良しだったのに、戦わなくちゃいけないなんて…も～う、腹立つだ！",
            ["DialogueId"] = 12020109,
            ["GUID"] = "1E174115",
            ["NextDialogue"] = 12020110,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174115",
            },
        [12020110] = {
            ["Content"] = "都怪大风九章不懂事……不对，还是那个卑鄙的家伙更坏！",
            ["ContentJP"] = "すべてはあの大風九章が悪いんだ！いや、違う……あの卑怯なやつのほうが悪い！",
            ["DialogueId"] = 12020110,
            ["GUID"] = "1E174116",
            ["NextDialogue"] = 12020111,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174116",
            },
        [12020111] = {
            ["Content"] = "哈哈，我可以将这句话当成是一种赞赏吗？",
            ["ContentJP"] = "ははは……それは、褒め言葉として受け取ってもいいのか？",
            ["DialogueId"] = 12020111,
            ["GUID"] = "1E174117",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120201/1E174117",
            },
        [12020201] = {
            ["Content"] = "喂，你们这些鼠辈，怎么聚首在这里对付我师兄！！",
            ["ContentJP"] = "おぅおぅ！よくも俺の兄弟に手を出してくれたなぁ！",
            ["DialogueId"] = 12020201,
            ["Duration"] = 2,
            ["GUID"] = "1E17603A",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E17603A",
            },
        [12020202] = {
            ["Content"] = "头儿，他要逃了……！",
            ["ContentJP"] = "かしら！逃げられますぜ……！",
            ["DialogueId"] = 12020202,
            ["Duration"] = 2,
            ["GUID"] = "1E176064",
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E176064",
            },
        [12020203] = {
            ["Content"] = "都停手吧。",
            ["ContentJP"] = "ここまでだ。",
            ["DialogueId"] = 12020203,
            ["Duration"] = 2,
            ["GUID"] = "1E17608E",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E17608E",
            },
        [12020204] = {
            ["Content"] = "那不是前功尽弃了——",
            ["ContentJP"] = "ですが、せっかくここまで――",
            ["DialogueId"] = 12020204,
            ["Duration"] = 2,
            ["GUID"] = "1E1760B8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E1760B8",
            },
        [12020205] = {
            ["Content"] = "无妨。",
            ["ContentJP"] = "構わんよ。",
            ["DialogueId"] = 12020205,
            ["Duration"] = 1,
            ["GUID"] = "1E1760E2",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120202/1E1760E2",
            },
        [12020301] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉……好不容易见到师兄一面，又被旁人打搅，让他逃了去了。",
            ["ContentJP"] = "はぁ……せっかくユーミンに会えたってのに、あいつらのせいで逃げられちまったじゃねぇか。",
            ["DialogueId"] = 12020301,
            ["GUID"] = "1E1770A2",
            ["NextDialogue"] = 12020302,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                [3] = 203005,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1770A2",
            },
        [12020302] = {
            ["Content"] = "这桂花糕，在怀里揣了半晌，揣得都冷了硬了。也不知道猴年马月才能让师兄吃上。",
            ["ContentJP"] = "せっかくの <Default note=\"text:グイホアガオ\">桂花菓子</>、懐に入れてたのにすっかり冷えて固くなっちまった。いつユーミンに渡せるんだろうな……",
            ["DialogueId"] = 12020302,
            ["GUID"] = "1E1770CC",
            ["NextDialogue"] = 12020303,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1770CC",
            },
        [12020303] = {
            ["Content"] = "原来你在找的人，就是煜明。",
            ["ContentJP"] = "探してた人って、ユーミンだったんだね。",
            ["DialogueId"] = 12020303,
            ["GUID"] = "1E1770F6",
            ["NextDialogue"] = 12020304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1770F6",
            },
        [12020304] = {
            ["Content"] = "话说回来，你怎么在这。我赶到之前，这里都发生了什么？",
            ["ContentJP"] = "そういえば、なんでいるんだ？てか、ここで何があったんだ？",
            ["DialogueId"] = 12020304,
            ["GUID"] = "1E177120",
            ["NextDialogue"] = 12020305,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177120",
            },
        [12020305] = {
            ["Content"] = "（向刻舟讲述之前发生的事情。）",
            ["ContentJP"] = "カシュウに事情を説明する。",
            ["DialogueId"] = 12020305,
            ["GUID"] = "1E17714A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 12020306,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17714A",
            },
        [12020306] = {
            ["Content"] = "这人怎么如此过分！{nickname}，你被他算计，没有受伤吧？！",
            ["ContentJP"] = "なんてやつだ！{nickname}、あんたハメられたな。ケガはねぇか？",
            ["DialogueId"] = 12020306,
            ["GUID"] = "1E177174",
            ["NextDialogue"] = 12020307,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177174",
            },
        [12020307] = {
            ["Content"] = "可恶，师兄受那重重规矩束缚，我行事可是无法无天……惹了我，横竖也要让他吃点教训才是！",
            ["ContentJP"] = "くそっ、ユーミンはあの堅っ苦しい掟に縛られてるが、俺はそんな規制ねぇからな……ただじゃ済まさねぇ！",
            ["DialogueId"] = 12020307,
            ["GUID"] = "1E17719E",
            ["NextDialogue"] = 12020308,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17719E",
            },
        [12020308] = {
            ["Content"] = "白也看这伙人不爽很久了！我们联手把这里掀翻天吧！",
            ["ContentJP"] = "そうだそうだ！スノウもずっと胡散臭いって思ってたんだよね！一緒にボコボコするのを手伝うぞ！",
            ["DialogueId"] = 12020308,
            ["GUID"] = "1E1771C8",
            ["NextDialogue"] = 12020309,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1771C8",
            },
        [12020309] = {
            ["Content"] = "两位，你们的交谈我可都听见了。我向你们赔礼道歉可好？",
            ["ContentJP"] = "お二人さん、聞こえてるぞ。謝るから許してくれぬか？",
            ["DialogueId"] = 12020309,
            ["GUID"] = "1E1771F2",
            ["NextDialogue"] = 12020310,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1771F2",
            },
        [12020310] = {
            ["Content"] = "我劝你少说些话，我的气可还没消。",
            ["ContentJP"] = "黙ってて。ぜんぜん許す気になれないから。",
            ["DialogueId"] = 12020310,
            ["GUID"] = "1E17721C",
            ["NextDialogue"] = 12020311,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17721C",
            },
        [12020311] = {
            ["Content"] = "现在不对你出手，只是因为我不想变成和你一样的渣滓。",
            ["ContentJP"] = "ただ、あなたみたいな卑怯者になりたくもない。だから、手は出さないよ。",
            ["DialogueId"] = 12020311,
            ["GUID"] = "1E177246",
            ["NextDialogue"] = 12020312,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177246",
            },
        [12020312] = {
            ["Content"] = "好、好，小友宽宏大量。",
            ["ContentJP"] = "そうかそうか、いやぁ、実にお優しい方だ。",
            ["DialogueId"] = 12020312,
            ["GUID"] = "1E177270",
            ["NextDialogue"] = 12020313,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177270",
            },
        [12020313] = {
            ["Content"] = "小友的义气着实让人动容。虬某心服口服，甘愿担下任务失败的责任，也要卖小友一个面子，放归猎物。之后止掌柜那边，我会去交代。",
            ["ContentJP"] = "その義気、大したものだ。今回は私の負けということにしよう。君に免じて、あの獲物は逃がしてやろう。シリュウ嬢の方には、私から話しておくよ。",
            ["DialogueId"] = 12020313,
            ["GUID"] = "1E17729A",
            ["NextDialogue"] = 12020314,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17729A",
            },
        [12020314] = {
            ["Content"] = "这真是止流掌柜的意思吗？我不信你说的话。还有，我不想再听到“猎物”这个词。",
            ["ContentJP"] = "これがシリュウさんの指図なんて、とても信じられない。それから、彼を「獲物」と{性别:呼ぶな|呼ばないで}。",
            ["DialogueId"] = 12020314,
            ["GUID"] = "1E1772C4",
            ["NextDialogue"] = 12020315,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1772C4",
            },
        [12020315] = {
            ["Content"] = "哈哈……正如我先前所说，止掌柜自有她的考虑。",
            ["ContentJP"] = "ははは……前にも話したが、シリュウ嬢には彼女なりの考えがある。",
            ["DialogueId"] = 12020315,
            ["GUID"] = "1E1772EE",
            ["NextDialogue"] = 12020316,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1772EE",
            },
        [12020316] = {
            ["Content"] = "要不是你们这伙人横插一杠，我和师兄早就重新聚首了！黑瞎子，你欠我的如何赔？",
            ["ContentJP"] = "あんたらのせいで、ユーミンと再会する機会を逃しちまったじゃねぇか！",
            ["DialogueId"] = 12020316,
            ["GUID"] = "1E177318",
            ["NextDialogue"] = 12020317,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177318",
            },
        [12020317] = {
            ["Content"] = "哦？依我看，那应天尉分明是刻意躲着你。若是他留下，你俩二人联手，在场各位又有谁能抵挡？",
            ["ContentJP"] = "おや、彼はあなたを見て逃げたのように見えたがね。そうでなければ、なぜ君を手を組んで私を撃退しようとしなかったのかな？",
            ["DialogueId"] = 12020317,
            ["GUID"] = "1E177342",
            ["NextDialogue"] = 12020318,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177342",
            },
        [12020318] = {
            ["Content"] = "住口！要你在这边啰嗦！",
            ["ContentJP"] = "黙れ！殺すぞ！",
            ["DialogueId"] = 12020318,
            ["GUID"] = "1E17736C",
            ["NextDialogue"] = 12020319,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E17736C",
            },
        [12020319] = {
            ["Content"] = "哈哈哈！",
            ["ContentJP"] = "ははは！",
            ["DialogueId"] = 12020319,
            ["GUID"] = "1E177396",
            ["NextDialogue"] = 12020320,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177396",
            },
        [12020320] = {
            ["Content"] = "我还有要事处理，便先行告退。",
            ["ContentJP"] = "私は用があるゆえ、先に失礼する。だが、その前に……",
            ["DialogueId"] = 12020320,
            ["GUID"] = "1E1773C0",
            ["NextDialogue"] = 12020321,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1773C0",
            },
        [12020321] = {
            ["Content"] = "这位朋友，我且提醒你一句。你师兄往那个方向撤离，再不去追怕是又要来不及了。",
            ["ContentJP"] = "そこの熱血くん、私に構ってるより、はやく<Default note=\"text:おうてんい\">応天尉</>を追いかけるべきでは？",
            ["DialogueId"] = 12020321,
            ["GUID"] = "1E1773EA",
            ["NextDialogue"] = 12020322,
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E1773EA",
            },
        [12020322] = {
            ["Content"] = "小友，你也听我一句劝告。不是所有人行事都如我这般坦荡。知人知面，未必知心。",
            ["ContentJP"] = "それと、君、一つ忠告だ。私のように、腹を割って話す者はそう多くはない。表面とは違い、胸の内はなかなかに見えぬものだ。",
            ["DialogueId"] = 12020322,
            ["GUID"] = "1E177414",
            ["SpeakNpcId"] = 210012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120203/1E177414",
            },
        [12020401] = {
            ["Content"] = "他的自恋狂发言又增加了！",
            ["ContentJP"] = "あいつ、いちいちナルシストだな！",
            ["DialogueId"] = 12020401,
            ["Duration"] = 2,
            ["GUID"] = "1E17810A",
            ["NextDialogue"] = 12020402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120204/1E17810A",
            },
        [12020402] = {
            ["Content"] = "最后那句话到底是什么意思哇？神神秘秘的……",
            ["ContentJP"] = "ところで最後のアレはなんだったんだ？変なやつ……",
            ["DialogueId"] = 12020402,
            ["Duration"] = 3,
            ["GUID"] = "1E178134",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120204/1E178134",
            },
        [12020501] = {
            ["Camera"] = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉……",
            ["ContentJP"] = "はぁ……",
            ["DialogueId"] = 12020501,
            ["FacialId"] = {
                [1] = "210021:Unhappy01",
                },
            ["FinalCamera"] = "-39.296875,19.130371,149.838379,0.000004,-2.785276,-161.556458,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E179172",
            ["LookAt"] = {
                [1] = "100001:n(210021)",
                [2] = "210021:n(100001)",
                },
            ["NextDialogue"] = 12020502,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E179172",
            },
        [12020502] = {
            ["Content"] = "{nickname}，你是不是和师兄挺熟的？",
            ["ContentJP"] = "{nickname}、もしかしてユーミンと仲がいいんじゃないのか？",
            ["DialogueId"] = 12020502,
            ["FacialId"] = {
                [1] = "210021:Think01",
                },
            ["GUID"] = "1E17919C",
            ["NextDialogue"] = 12020503,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:ScratchHead_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E17919C",
            },
        [12020503] = {
            ["Content"] = "师兄成为应天尉是因为一场意外变故。但我能感觉到，他并不开心……",
            ["ContentJP"] = "あいつは自ら望んで<Default note=\"text:おうてんい\">応天尉</>になったわけじゃない。さっきも思ったが、とても心の底から喜んでるようには見えなかった……",
            ["DialogueId"] = 12020503,
            ["FacialId"] = {
                [1] = "210021:Angry01",
                },
            ["GUID"] = "1E1791C6",
            ["NextDialogue"] = 12020504,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E1791C6",
            },
        [12020504] = {
            ["Camera"] = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你下次要是见到他，帮我带一句话，就说当年那件事不怪他，山外山的大家都希望他回来。",
            ["ContentJP"] = "もし、次に会うことがあったら伝えてくれ。あの時のこと、誰も責めてないと。山外山のみんな、あいつの帰りを待ってると……",
            ["DialogueId"] = 12020504,
            ["GUID"] = "1E1791F0",
            ["NextDialogue"] = 12020505,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E1791F0",
            },
        [12020505] = {
            ["Camera"] = "-286.9375,-213.182617,178.568115,0.000013,-9.985319,62.043591,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当年？发生了什么事情？",
            ["ContentJP"] = "あの時……？何かあったの……？",
            ["DialogueId"] = 12020505,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "1E17921A",
            ["NextDialogue"] = 12020506,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "210021:Talk02_End",
                [2] = "100001:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E17921A",
            },
        [12020506] = {
            ["Camera"] = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这件事儿挺麻烦的，三言两语说不清楚。我还得赶着去追师兄，下次再和你讲吧。",
            ["ContentJP"] = "悪いが、この話は長くなる。あいつを追わないといけねぇから、また今度話してやるよ。",
            ["DialogueId"] = 12020506,
            ["FacialId"] = {
                [1] = "210021:Uninterested01",
                },
            ["GUID"] = "1E179244",
            ["NextDialogue"] = 12020507,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:Talk01_Start",
                [2] = "100001:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E179244",
            },
        [12020507] = {
            ["Camera"] = "254.949219,-102.718262,275.353027,0.000008,-18.585285,170.644135,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，你说，人活在这世上，为何不能随性所动，兴致来了便做自己想做的。偏偏要受这么多约束呢？",
            ["ContentJP"] = "{nickname}、この世に生まれたからには、自由に生きるべきだとおもわねぇか？なぜ、人は自分を縛るようなことするんだろうな。",
            ["DialogueId"] = 12020507,
            ["FacialId"] = {
                [1] = "210021:Unhappy01",
                },
            ["FinalCamera"] = "465.136719,-137.344727,314.913086,0.000008,-18.585264,170.644104,30.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E17926E",
            ["NextDialogue"] = 12020508,
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E17926E",
            },
        [12020508] = {
            ["Camera"] = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我得走了。别忘了我们的约定啊！下次见面，可得把盏言欢，畅谈至尽兴才行！",
            ["ContentJP"] = "おっと、もう行かねぇと。約束、忘れるなよ！次会った時は、酒でも飲みながら、腹割って話そうぜ！",
            ["DialogueId"] = 12020508,
            ["FacialId"] = {
                [1] = "210021:Smile01",
                },
            ["GUID"] = "1E179298",
            ["SpeakNpcId"] = 210021,
            ["TalkActionId"] = {
                [1] = "210021:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120205/1E179298",
            },
        [12020601] = {
            ["Content"] = "感觉出来逛了好久，不知道止流那边怎么样了……",
            ["ContentJP"] = "出てから随分経つなぁ。シリュウの方はどうなってるんだろ……",
            ["DialogueId"] = 12020601,
            ["Duration"] = 3,
            ["GUID"] = "1E17A1DA",
            ["NextDialogue"] = 12020602,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120206/1E17A1DA",
            },
        [12020602] = {
            ["Content"] = "小仆从，我们回百年春看看吧！",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>に戻ろうぜ！",
            ["DialogueId"] = 12020602,
            ["Duration"] = 2,
            ["GUID"] = "1E17A204",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120206/1E17A204",
            },
        [12020701] = {
            ["Camera"] = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个动静……发生什么事情了吗？",
            ["ContentJP"] = "なに、この揺れ……？",
            ["DialogueId"] = 12020701,
            ["GUID"] = "1E17B242",
            ["NextDialogue"] = 12020702,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B242",
            },
        [12020702] = {
            ["Content"] = "看来，是大当家在烛阴祭坛的布置已经完成了。",
            ["ContentJP"] = "どうやら、<Default note=\"text:しょくいん\">燭陰</>の祭壇での準備が完了したようね。",
            ["DialogueId"] = 12020702,
            ["GUID"] = "1E17B26C",
            ["NextDialogue"] = 12020703,
            ["RelatedWikiId"] = {
                [1] = 408015,
                [2] = 303011,
                },
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B26C",
            },
        [12020703] = {
            ["Content"] = "她曾嘱咐过，若您来寻她，让您在大厅静候。等到事成之后，她会回来见您。",
            ["ContentJP"] = "そういえば、シリュウさんから伝言を預かってるわ。あなたが戻ってきたら、大広間で待っててほしいそうよ。すべてが終わったら、必ず会いに行くからって言ってたわ。",
            ["DialogueId"] = 12020703,
            ["GUID"] = "1E17B296",
            ["NextDialogue"] = 12020704,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B296",
            },
        [12020704] = {
            ["Content"] = "等等，不需要我们去帮忙吗？！",
            ["ContentJP"] = "待って、私たちは手伝わなくていいのか！？",
            ["DialogueId"] = 12020704,
            ["GUID"] = "1E17B2C0",
            ["NextDialogue"] = 12020705,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B2C0",
            },
        [12020705] = {
            ["Content"] = "封印烛阴之行险阻重重，你们若是前去，可能会受伤……",
            ["ContentJP"] = "<Default note=\"text:しょくいん\">燭陰</>の封印はとても危険よ。ケガをしてしまうこともあるのよ……",
            ["DialogueId"] = 12020705,
            ["GUID"] = "1E17B2EA",
            ["NextDialogue"] = 12020706,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B2EA",
            },
        [12020706] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "グオォォォ……！",
            ["DialogueId"] = 12020706,
            ["GUID"] = "1E17B314",
            ["NextDialogue"] = 12020707,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B314",
            },
        [12020707] = {
            ["Content"] = "那边的情况听起来不太妙。让我们去吧，多一个人就是多一份助力。",
            ["ContentJP"] = "様子がおかしい……行ってみよう！人が多いに越したことはないし。",
            ["DialogueId"] = 12020707,
            ["GUID"] = "1E17B33E",
            ["NextDialogue"] = 12020708,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B33E",
            },
        [12020708] = {
            ["Content"] = "但，大当家的嘱咐……",
            ["ContentJP"] = "でも、シリュウさんはここで待てと……",
            ["DialogueId"] = 12020708,
            ["GUID"] = "1E17B368",
            ["NextDialogue"] = 12020709,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B368",
            },
        [12020709] = {
            ["Content"] = "哎呀，都到这种时候了，你还在犹豫什么！",
            ["ContentJP"] = "あのね、そんなの気にしてる場合！？",
            ["DialogueId"] = 12020709,
            ["GUID"] = "1E17B392",
            ["NextDialogue"] = 12020710,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B392",
            },
        [12020710] = {
            ["Content"] = "……我明白了。您可以去尘漠石海最高处的位置，那里通往烛阴祭坛的临时道路已经搭建完毕。",
            ["ContentJP"] = "……わかったわ。塵砂の荒海の頂上に行きなさい。<Default note=\"text:しょくいん\">燭陰</>の祭壇へと通ずる道は既に開いているから。",
            ["DialogueId"] = 12020710,
            ["GUID"] = "1E17B3BC",
            ["NextDialogue"] = 12020711,
            ["SpeakNpcId"] = 210022,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B3BC",
            },
        [12020711] = {
            ["Content"] = "白嗅到了征服恶龙的决战气息……等等，怎么听起来不像是魔王该干的事情？！",
            ["ContentJP"] = "悪しきドラゴン退治の匂いがプンプンするよ！……ってそれ、魔王のやることじゃなくない！？",
            ["DialogueId"] = 12020711,
            ["GUID"] = "1E17B3E6",
            ["NextDialogue"] = 12020712,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B3E6",
            },
        [12020712] = {
            ["Content"] = "……我们赶快过去吧。",
            ["ContentJP"] = "行こう。",
            ["DialogueId"] = 12020712,
            ["GUID"] = "1E17B410",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120207/1E17B410",
            },
        [12020901] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呼……千钧一发之际，险险成功了。",
            ["ContentJP"] = "ふぅ……なんとか成功しましたな。",
            ["DialogueId"] = 12020901,
            ["GUID"] = "1E17D312",
            ["NextDialogue"] = 12020902,
            ["RelatedWikiId"] = {
                [1] = 408015,
                [2] = 303011,
                },
            ["SpeakNpcId"] = 210005,
            ["SpeakNpcName"] = "UI_Npc_Name_Goodshangren",
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D312",
            },
        [12020902] = {
            ["Content"] = "还不能松懈，我能感受到上方的封印尚不稳固。",
            ["ContentJP"] = "油断しないで。上の方の封印があまいわ。",
            ["DialogueId"] = 12020902,
            ["GUID"] = "1E17D33C",
            ["NextDialogue"] = 12020903,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D33C",
            },
        [12020903] = {
            ["Content"] = "我要维持此处阵眼，暂时无法抽身。你们谁能上去检查一下吗？",
            ["ContentJP"] = "私は陣の要を維持しないとだから、動けそうにない。誰か、上の様子を見に行ってくれない？",
            ["DialogueId"] = 12020903,
            ["GUID"] = "1E17D366",
            ["NextDialogue"] = 12020904,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D366",
            },
        [12020904] = {
            ["Content"] = "止流掌柜，我去吧。",
            ["ContentJP"] = "シリュウさん、{性别:僕|私}に行かせてください。",
            ["DialogueId"] = 12020904,
            ["GUID"] = "1E17D390",
            ["NextDialogue"] = 12020905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D390",
            },
        [12020905] = {
            ["Content"] = "……{nickname}，怎么是你？",
            ["ContentJP"] = "……{nickname}、どうしてここに……",
            ["DialogueId"] = 12020905,
            ["GUID"] = "1E17D3BA",
            ["NextDialogue"] = 12020906,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D3BA",
            },
        [12020906] = {
            ["Content"] = "你们的工作已经完成了。我分明嘱咐过望春，让你们在商会等候我归来即可。",
            ["ContentJP"] = "あなたたちの仕事はもう終わりよ。<Default note=\"text:ももとき\">百年春</>で待ってもらうよう、ボウシュンに伝えたはずだけど……",
            ["DialogueId"] = 12020906,
            ["GUID"] = "1E17D3E4",
            ["NextDialogue"] = 12020907,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D3E4",
            },
        [12020907] = {
            ["Content"] = "这里的动静太大，我放心不下来。不如来看看能做些什么。",
            ["ContentJP"] = "あんな騒動を見て、じっとしてなんていられません。何かできることがあるんじゃないかと思って。",
            ["DialogueId"] = 12020907,
            ["GUID"] = "1E17D40E",
            ["NextDialogue"] = 12020908,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D40E",
            },
        [12020908] = {
            ["Content"] = "这就是我们狩月人倾情提供的售后服务，包老板满意！",
            ["ContentJP"] = "これは月狩り人ならではのスペシャルアフターサービスだよ！クレームゼロをなめてもらっちゃ困るよ～",
            ["DialogueId"] = 12020908,
            ["GUID"] = "1E17D438",
            ["NextDialogue"] = 12020909,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D438",
            },
        [12020909] = {
            ["Content"] = "您就放一百个心吧，止掌柜。{nickname}身手可灵活了，尤其擅长旋转跳跃，多高的障碍都不在话下！",
            ["ContentJP"] = "安心しなって、うちの{nickname}はすばしっこいし、回転も跳躍もお手の物だから！どんな高い障害だって、ひょいと乗り越えちゃうよ！",
            ["DialogueId"] = 12020909,
            ["GUID"] = "1E17D462",
            ["NextDialogue"] = 12020910,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D462",
            },
        [12020910] = {
            ["Content"] = "若是你们坚持……",
            ["ContentJP"] = "そこまで言うのなら……",
            ["DialogueId"] = 12020910,
            ["GUID"] = "1E17D48C",
            ["NextDialogue"] = 12020911,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D48C",
            },
        [12020911] = {
            ["Content"] = "{nickname}，拿住这枚铜钱。将它放至烛阴的额首处，剩下的我会操作。",
            ["ContentJP"] = "{nickname}、これを。この銅貨を<Default note=\"text:しょくいん\">燭陰</>の首にかけてちょうだい。残りのことは私がやるわ。",
            ["DialogueId"] = 12020911,
            ["GUID"] = "1E17D4B6",
            ["NextDialogue"] = 12020912,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D4B6",
            },
        [12020912] = {
            ["Content"] = "当心，别受伤了。",
            ["ContentJP"] = "絶対に、ケガしないでね。",
            ["DialogueId"] = 12020912,
            ["GUID"] = "1E17D4E0",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120209/1E17D4E0",
            },
        [12020913] = {
            ["Content"] = "杜立，先带着伤者下去吧。",
            ["ContentJP"] = "ドゥリ、負傷者を連れて行きなさい。",
            ["DialogueId"] = 12020913,
            ["GUID"] = "1E13468F",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E13468F",
            },
        [12020914] = {
            ["Content"] = "是，大当家！",
            ["ContentJP"] = "御意のままに、シリュウさん！",
            ["DialogueId"] = 12020914,
            ["GUID"] = "1E134691",
            ["SpeakNpcId"] = 210004,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Duli",
            ["VoiceName"] = "voice/$Locale$/story/1201/120138/1E134691",
            },
        [12021001] = {
            ["Content"] = "魂兮游离，北狩荒秽……彼我烛阴，罹殃千岁……",
            ["ContentJP"] = "魂よ、遊離せり――北に荒穢を狩り、彼と我、烛陰にて相対し、禍に罹りて千歳を経ん……",
            ["DialogueId"] = 12021001,
            ["Duration"] = 2,
            ["GUID"] = "1E17E37A",
            ["NextDialogue"] = 12021002,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E37A",
            },
        [12021002] = {
            ["Content"] = "（……！又出现了，先前在尘漠石海听到的那个声音。）",
            ["ContentJP"] = "（……！この声、以前塵砂の荒海で聞いたものだ……）",
            ["DialogueId"] = 12021002,
            ["Duration"] = 2,
            ["GUID"] = "1E17E3A4",
            ["NextDialogue"] = 12021003,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E3A4",
            },
        [12021003] = {
            ["Content"] = "（果然，这就是烛阴的呓语吗？）",
            ["ContentJP"] = "（もしかして、<Default note=\"text:しょくいん\">燭陰</>の声……？）",
            ["DialogueId"] = 12021003,
            ["Duration"] = 2,
            ["GUID"] = "1E17E3CE",
            ["NextDialogue"] = 12021004,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E3CE",
            },
        [12021004] = {
            ["Content"] = "怎么了，{nickname}？",
            ["ContentJP"] = "どうしたの、{nickname}？",
            ["DialogueId"] = 12021004,
            ["Duration"] = 2,
            ["GUID"] = "1E17E3F8",
            ["NextDialogue"] = 12021005,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E3F8",
            },
        [12021005] = {
            ["Content"] = "不，没什么……",
            ["ContentJP"] = "……いえ。",
            ["DialogueId"] = 12021005,
            ["Duration"] = 2,
            ["GUID"] = "1E17E422",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120210/1E17E422",
            },
        [12021201] = {
            ["Content"] = "魂魄佚散，畴昔倾颓……荒忽焉极，循时索归……",
            ["ContentJP"] = "魂散りて、往昔は崩れん……荒寂の果てに時を辿り、なお帰路を求めん……",
            ["DialogueId"] = 12021201,
            ["Duration"] = 2,
            ["GUID"] = "1E18044A",
            ["NextDialogue"] = 12021202,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120212/1E18044A",
            },
        [12021202] = {
            ["Content"] = "（烛阴的声音，越来越清晰了……）",
            ["ContentJP"] = "（声が……だんだん鮮明に……）",
            ["DialogueId"] = 12021202,
            ["Duration"] = 2,
            ["GUID"] = "1E180474",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120212/1E180474",
            },
        [12021301] = {
            ["Content"] = "……汝乃何人？",
            ["ContentJP"] = "……何者か。",
            ["DialogueId"] = 12021301,
            ["Duration"] = 2,
            ["GUID"] = "1E1814B2",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E1814B2",
            },
        [12021302] = {
            ["Content"] = "汝亦是来加害于吾乎？",
            ["ContentJP"] = "我を害さんとて、ここへ参ったのか？",
            ["DialogueId"] = 12021302,
            ["Duration"] = 2,
            ["GUID"] = "1E1814DC",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E1814DC",
            },
        [12021303] = {
            ["Content"] = "不好，它发狂了！小仆从！！！",
            ["ContentJP"] = "ぎゃー！なんかめちゃくちゃ怒ってるよ！！",
            ["DialogueId"] = 12021303,
            ["Duration"] = 2,
            ["GUID"] = "1E181506",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E181506",
            },
        [12021304] = {
            ["Content"] = "听得到我的声音吗？你是不是想对我们说什么？",
            ["ContentJP"] = "あの声、あなただよね？{性别:僕|私}に何を伝えたい{性别:んだ|の}？",
            ["DialogueId"] = 12021304,
            ["Duration"] = 4,
            ["GUID"] = "1E181530",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E181530",
            },
        [12021305] = {
            ["Content"] = "吼————",
            ["ContentJP"] = "グオォォォ……！",
            ["DialogueId"] = 12021305,
            ["Duration"] = 2,
            ["GUID"] = "1E18155A",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E18155A",
            },
        [12021306] = {
            ["Content"] = "烛阴已力竭了。",
            ["ContentJP"] = "<Default note=\"text:しょくいん\">燭陰</>はもう、力尽きたわ。",
            ["DialogueId"] = 12021306,
            ["Duration"] = 2,
            ["GUID"] = "1E181584",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E181584",
            },
        [12021307] = {
            ["Content"] = "最后一击，要拜托你了，{nickname}。",
            ["ContentJP"] = "{nickname}、トドメをお願い。",
            ["DialogueId"] = 12021307,
            ["Duration"] = 4,
            ["GUID"] = "1E1815AE",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120213/1E1815AE",
            },
        [12022001] = {
            ["Content"] = "——至此，大风九章已成！",
            ["ContentJP"] = "――大風九章、これにて完成！",
            ["DialogueId"] = 12022001,
            ["GUID"] = "1E18878A",
            ["NextDialogue"] = 12022002,
            ["RelatedWikiId"] = {
                [1] = 304003,
                [2] = 303008,
                [3] = 303011,
                },
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E18878A",
            },
        [12022002] = {
            ["Content"] = "华胥黎庶，自兹以往，将永离战乱之苦，无受纷争之扰！",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>の民よ――これより先、戦乱の苦しみとは永く決別し、争いの禍に悩まされることも断じて無かろう！",
            ["DialogueId"] = 12022002,
            ["GUID"] = "1E1887B4",
            ["NextDialogue"] = 12022003,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1887B4",
            },
        [12022003] = {
            ["Content"] = "太皓，执理。烛阴，执心。",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>は理を執り、<Default note=\"text:しょくいん\">燭陰</>は心を執る。",
            ["DialogueId"] = 12022003,
            ["GUID"] = "1E1887DE",
            ["NextDialogue"] = 12022004,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1887DE",
            },
        [12022004] = {
            ["Content"] = "二位尊神，将共御大风九章，庇佑苍生，护万世安泰——",
            ["ContentJP"] = "両神はともに大風九章を御し、蒼生を庇護し、万世の安寧を守られん――",
            ["DialogueId"] = 12022004,
            ["GUID"] = "1E188808",
            ["NextDialogue"] = 12022005,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188808",
            },
        [12022005] = {
            ["Content"] = "心为一切混乱之肇始！",
            ["ContentJP"] = "混乱の根は、「心」より始まる！",
            ["DialogueId"] = 12022005,
            ["GUID"] = "1E188832",
            ["NextDialogue"] = 12022006,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188832",
            },
        [12022006] = {
            ["Content"] = "我泱泱华胥，卷入如今兵戈之乱，全因人心混沌所起！",
            ["ContentJP"] = "我が<Default note=\"text:カショ\">華胥</>が乱世の戦に巻き込まれたのも、すべては人の心が混沌に堕ちたがゆえ！",
            ["DialogueId"] = 12022006,
            ["GUID"] = "1E18885C",
            ["NextDialogue"] = 12022007,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E18885C",
            },
        [12022007] = {
            ["Content"] = "今日，烛阴必须受封印。",
            ["ContentJP"] = "今この日をもって――<Default note=\"text:しょくいん\">燭陰</>は、追放されねばならぬ。",
            ["DialogueId"] = 12022007,
            ["GUID"] = "1E188886",
            ["NextDialogue"] = 12022008,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188886",
            },
        [12022008] = {
            ["Content"] = "唯有不受干扰之理，方有资格执掌统御之法！",
            ["ContentJP"] = "まことに、いかなる揺らぎにも染まぬ「理」こそが、統べる法を執るにふさわしい！",
            ["DialogueId"] = 12022008,
            ["GUID"] = "1E1888B0",
            ["NextDialogue"] = 12022009,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1888B0",
            },
        [12022009] = {
            ["Content"] = "此举不可！倘若心、理失衡， 后患无穷尽也！",
            ["ContentJP"] = "ならぬ！心と理の均衡を欠けば――その禍根、尽きることなき災いを呼ぶぞ！",
            ["DialogueId"] = 12022009,
            ["GUID"] = "1E1888DA",
            ["NextDialogue"] = 12022010,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1888DA",
            },
        [12022010] = {
            ["Content"] = "退下！休要坏了正事！",
            ["ContentJP"] = "無礼な！余計な口出しをするな！",
            ["DialogueId"] = 12022010,
            ["GUID"] = "1E188904",
            ["NextDialogue"] = 12022011,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188904",
            },
        [12022011] = {
            ["Content"] = "自尔后数百载，玄色狴犴生，灾祸暗起……今日之果，皆为当日之因呐！",
            ["ContentJP"] = "それから幾百年――<Default note=\"text:ゲンビー\">玄狴</>が現れ、禍は静かに芽吹いていた……今日の報いは、すべてあの日の選択の種から生じたものなのだよ……！",
            ["DialogueId"] = 12022011,
            ["GUID"] = "1E18892E",
            ["NextDialogue"] = 12022012,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E18892E",
            },
        [12022012] = {
            ["Content"] = "夫烛阴者，由心而生。人心不灭，烛阴如何能灭？",
            ["ContentJP"] = "そもそも<Default note=\"text:しょくいん\">燭陰</>とは、心より生まれしもの――人の心が尽きぬ限り、<Default note=\"text:しょくいん\">燭陰</>を滅ぼすなど、どうして叶おうか……！",
            ["DialogueId"] = 12022012,
            ["GUID"] = "1E188958",
            ["NextDialogue"] = 12022013,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188958",
            },
        [12022013] = {
            ["Content"] = "以秘术暂封之，如扬汤止沸。俟烛阴挣脱封印，附骨之疽，必酿大患！",
            ["ContentJP"] = "秘術でもって一時しのぎに追いやったところで、湯をかきまわして沸騰を止めるようなもの……いずれ<Default note=\"text:しょくいん\">燭陰</>は巡って戻り、骨に巣くう毒のごとく、大いなる災いをもたらすであろう！",
            ["DialogueId"] = 12022013,
            ["GUID"] = "1E188982",
            ["NextDialogue"] = 12022014,
            ["SnapShot"] = "MEMORY",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188982",
            },
        [12022014] = {
            ["Content"] = "……孰离合兮可为，蹇谁留兮他乡？",
            ["ContentJP"] = "……誰ぞめぐり逢い、異郷に留むるか？",
            ["DialogueId"] = 12022014,
            ["GUID"] = "1E1889AC",
            ["NextDialogue"] = 12022015,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_CMName_Name_ZhuYing",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1889AC",
            },
        [12022015] = {
            ["Content"] = "烛阴，刚刚那些是你的记忆吗？！你究竟想告诉我什么？",
            ["ContentJP"] = "{性别:<Default note=\"text:しょくいん\">燭陰</>、さっきのはあなたの記憶なのか？いったい何を伝えようとしているんだ？|<Default note=\"text:しょくいん\">燭陰</>、さっきのはあなたの記憶なの？いったい何を伝えようとしているの？}",
            ["DialogueId"] = 12022015,
            ["GUID"] = "1E1889D6",
            ["NextDialogue"] = 12022016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E1889D6",
            },
        [12022016] = {
            ["Content"] = "万事已矣，不可复挽矣。天下将趋不可避之大祸……",
            ["ContentJP"] = "すべては、すでに定まりしこと……もはや引き返す術は無い。この世は、避け得ぬ大いなる禍へと、歩みを進めておる……",
            ["DialogueId"] = 12022016,
            ["GUID"] = "1E188A00",
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_CMName_Name_ZhuYing",
            ["VoiceName"] = "voice/$Locale$/story/1201/120220/1E188A00",
            },
        [12022101] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "小仆从，你没事吧？",
            ["ContentJP"] = "あわわ、我が下僕、大丈夫か？",
            ["DialogueId"] = 12022101,
            ["GUID"] = "1E1897F2",
            ["NextDialogue"] = 12022102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120221/1E1897F2",
            },
        [12022102] = {
            ["Content"] = "没事。我好像看到了一些……画面。",
            ["ContentJP"] = "うん……ただ少し不思議なものが、見えただけ。",
            ["DialogueId"] = 12022102,
            ["GUID"] = "1E18981C",
            ["NextDialogue"] = 12022103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120221/1E18981C",
            },
        [12022103] = {
            ["Content"] = "诸位，趁它被束缚住，赶紧发动攻击！能否拿下便在此一举了！",
            ["ContentJP"] = "皆の者、今よ！やつが束縛されているうちに、攻め落とすのよ！",
            ["DialogueId"] = 12022103,
            ["GUID"] = "1E189846",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120221/1E189846",
            },
        [12022201] = {
            ["Content"] = "等等！",
            ["ContentJP"] = "待ってください！",
            ["DialogueId"] = 12022201,
            ["GUID"] = "1E18A85A",
            ["NextDialogue"] = 12022202,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A85A",
            },
        [12022202] = {
            ["Content"] = "就在刚刚，我好像从烛阴的记忆中瞥见了一些大风九章的内情……或许会和烛阴之灾有关！",
            ["ContentJP"] = "つい先ほど、<Default note=\"text:しょくいん\">燭陰</>の記憶を通じて、大風九章にまつわる、何かしらの内情を垣間見た気がします。<Default note=\"text:しょくいん\">燭陰</>の災いと、深く関係しているのかもしれません……！",
            ["DialogueId"] = 12022202,
            ["GUID"] = "1E18A884",
            ["NextDialogue"] = 12022203,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A884",
            },
        [12022203] = {
            ["Content"] = "我们也许可以和它谈谈！如果能平息它的愤怒，或许我们不必与它为敌！",
            ["ContentJP"] = "話し合える余地が、まだあるかもしれないんです！もし怒りを鎮めることができれば、きっと――争わずにすむ道だってあるはずです！",
            ["DialogueId"] = 12022203,
            ["GUID"] = "1E18A8AE",
            ["NextDialogue"] = 12022204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A8AE",
            },
        [12022204] = {
            ["Content"] = "不必了。",
            ["ContentJP"] = "必要はないわ。",
            ["DialogueId"] = 12022204,
            ["GUID"] = "1E18A8D8",
            ["NextDialogue"] = 12022205,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A8D8",
            },
        [12022205] = {
            ["Content"] = "看你的反应……你早就知道？",
            ["ContentJP"] = "その反応……知っていたのですか？",
            ["DialogueId"] = 12022205,
            ["GUID"] = "1E18A902",
            ["NextDialogue"] = 12022206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A902",
            },
        [12022206] = {
            ["Content"] = "你窥见的或许为真……可那又怎样？",
            ["ContentJP"] = "たとえ、あなたが見たものが真実だったとして――それが、何だというの？",
            ["DialogueId"] = 12022206,
            ["GUID"] = "1E18A92C",
            ["NextDialogue"] = 12022207,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A92C",
            },
        [12022207] = {
            ["Content"] = "<H>白龙神君</>的时代，该结束了。而我，将执起祂的权柄。",
            ["ContentJP"] = "<H>白龍様</>の時代は、いい加減終わるべきよ。そしてこの私が、その御力を引き継ぐ。",
            ["DialogueId"] = 12022207,
            ["GUID"] = "1E18A956",
            ["NextDialogue"] = 12022208,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A956",
            },
        [12022208] = {
            ["Content"] = "什么……",
            ["ContentJP"] = "え……",
            ["DialogueId"] = 12022208,
            ["GUID"] = "1E18A980",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A980",
            },
        [12022209] = {
            ["Content"] = "真是遗憾……若不是事急从权，也不必对你用这种手段。",
            ["ContentJP"] = "残念だわ……あなたにこんな手を使いたくはなかったのだけれど。",
            ["DialogueId"] = 12022209,
            ["GUID"] = "1E18A9AA",
            ["NextDialogue"] = 12022210,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A9AA",
            },
        [12022210] = {
            ["Content"] = "……止流！！放我出去！",
            ["ContentJP"] = "……シリュウさん、ここから出してください！",
            ["DialogueId"] = 12022210,
            ["GUID"] = "1E18A9D4",
            ["NextDialogue"] = 12022211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A9D4",
            },
        [12022211] = {
            ["Content"] = "秦虬先前对我说，你一片赤子之心，怕会影响到计划的实行。",
            ["ContentJP"] = "キョウンの言うとおりね。あなたはまっすぐすぎる。ゆえに計画に支障をきたすだろうって。",
            ["DialogueId"] = 12022211,
            ["GUID"] = "1E18A9FE",
            ["NextDialogue"] = 12022212,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18A9FE",
            },
        [12022212] = {
            ["Content"] = "我特意把你支走，未想到你还是来了。",
            ["ContentJP"] = "だから、ここへ来させたくなかったのに。",
            ["DialogueId"] = 12022212,
            ["GUID"] = "1E18AA28",
            ["NextDialogue"] = 12022213,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AA28",
            },
        [12022213] = {
            ["Content"] = "在冰湖城和你相处的那段日子，确实是难得的闲暇时光，如一梦黄粱。",
            ["ContentJP"] = "アイスレイク城であなたと過ごしたひとときは……得難い安らぎのひと時だったわ。まるで束の間の黄粱の夢ようにね。",
            ["DialogueId"] = 12022213,
            ["GUID"] = "1E18AA52",
            ["NextDialogue"] = 12022214,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AA52",
            },
        [12022214] = {
            ["Content"] = "倘若你没有恰好出现在这里，就好了。我们还能如往常一样谈天说笑。",
            ["ContentJP"] = "もし、あなたがここに現れさえしなければ、きっとあの時のように、並んで笑い合えたのに。",
            ["DialogueId"] = 12022214,
            ["GUID"] = "1E18AA7C",
            ["NextDialogue"] = 12022215,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AA7C",
            },
        [12022215] = {
            ["Content"] = "可惜商人的行事准则里，不存在如果。",
            ["ContentJP"] = "残念ながら、商人の掟に「もしも」なんて存在しない。",
            ["DialogueId"] = 12022215,
            ["GUID"] = "1E18AAA6",
            ["NextDialogue"] = 12022216,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AAA6",
            },
        [12022216] = {
            ["Content"] = "你到底想做什么……",
            ["ContentJP"] = "いったい何をするつもりですか。",
            ["DialogueId"] = 12022216,
            ["GUID"] = "1E18AAD0",
            ["NextDialogue"] = 12022217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AAD0",
            },
        [12022217] = {
            ["Content"] = "嘘——这是为你好。虽然，可能不是以你喜欢的方式。",
            ["ContentJP"] = "シー。これもあなたのためよ。もっとも、あなたが望む形ではないかもしれないけどね。",
            ["DialogueId"] = 12022217,
            ["GUID"] = "1E18AAFA",
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AAFA",
            },
        [12022219] = {
            ["Content"] = "（逐渐扭曲的嘶鸣声）",
            ["ContentJP"] = "（おぞましい鳴き声）",
            ["DialogueId"] = 12022219,
            ["GUID"] = "1E18AB4E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AB4E",
            },
        [12022220] = {
            ["Content"] = "喂，这里发生什么了？——放开{性别：他|她}！",
            ["ContentJP"] = "いったい何があったんだ……おい、{性别:彼|彼女}を放せ！",
            ["DialogueId"] = 12022220,
            ["GUID"] = "1E18AB78",
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AB78",
            },
        [12022221] = {
            ["Content"] = "啧，撤。",
            ["ContentJP"] = "ち…撤退しよう。",
            ["DialogueId"] = 12022221,
            ["GUID"] = "1E18AB79",
            ["VoiceName"] = "voice/$Locale$/story/1201/120222/1E18AB79",
            },
        [12022250] = {
            ["Content"] = "一段时间后……",
            ["ContentJP"] = "しばらくして……",
            ["DialogueId"] = 12022250,
            ["GUID"] = "1E18AB8A",
            },
        [12022301] = {
            ["Camera"] = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{nickname}，你受伤了吗？",
            ["ContentJP"] = "{nickname}、ご無事ですか？",
            ["DialogueId"] = 12022301,
            ["GUID"] = "1E18B8C2",
            ["NextDialogue"] = 12022302,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 203006,
                [3] = 203007,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B8C2",
            },
        [12022302] = {
            ["Content"] = "深呼吸，排清杂念，我来为你调养。",
            ["ContentJP"] = "さあ、深呼吸を。雑念を払い、心を静めてください。これより、私があなたの気を整えましょう。",
            ["DialogueId"] = 12022302,
            ["GUID"] = "1E18B8EC",
            ["NextDialogue"] = 12022303,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B8EC",
            },
        [12022303] = {
            ["Content"] = "我没事，只是有点头晕……扶疏，不要再消耗你的力量了，你答应过……",
            ["ContentJP"] = "大丈夫……ちょっと、頭がふらつくだけだから……フーシュ、もう力を使わないで。約束したばかりなのに……",
            ["DialogueId"] = 12022303,
            ["GUID"] = "1E18B916",
            ["NextDialogue"] = 12022304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B916",
            },
        [12022304] = {
            ["Content"] = "安心，我自有分寸。当下还是以你的安危为重。",
            ["ContentJP"] = "ご安心ください、心得ております。今は何より、あなたの無事が第一ですから。",
            ["DialogueId"] = 12022304,
            ["GUID"] = "1E18B940",
            ["NextDialogue"] = 12022305,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B940",
            },
        [12022305] = {
            ["Content"] = "可恶，今天怎么总是迟来一步！要是当初学轻功时没有偷懒就好了，都怪我总是睡到日上三竿才醒……",
            ["ContentJP"] = "くそっ、今日はどうにも一歩遅れてばっかだ！あのとき真面目に軽功の稽古してりゃ……！朝日がてっぺん昇るまで寝てた俺が悪いな……！",
            ["DialogueId"] = 12022305,
            ["GUID"] = "1E18B96A",
            ["NextDialogue"] = 12022306,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B96A",
            },
        [12022306] = {
            ["Content"] = "我还好……你们怎么一起来了？",
            ["ContentJP"] = "大丈夫だよ……でも、どうしてあなたたちが一緒に？",
            ["DialogueId"] = 12022306,
            ["GUID"] = "1E18B994",
            ["NextDialogue"] = 12022307,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B994",
            },
        [12022307] = {
            ["Content"] = "我想明白了一些事情，正欲说与你听。",
            ["ContentJP"] = "少し、思い至ったことがございまして、あなたにお話しておきたいと思っていたのです。",
            ["DialogueId"] = 12022307,
            ["GUID"] = "1E18B9BE",
            ["NextDialogue"] = 12022308,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B9BE",
            },
        [12022308] = {
            ["Content"] = "我去百年春没有寻见你。听旁人说你往此处来了，便来碰碰运气，恰好在途中遇见了这位义士。",
            ["ContentJP"] = "そこで<Default note=\"text:ももとき\">百年春</>に行ったのですが、あなたの姿はありませんでした。人づてにここの場所を聞き、道中でこの剣士と出会った次第です。",
            ["DialogueId"] = 12022308,
            ["GUID"] = "1E18B9E8",
            ["NextDialogue"] = 12022309,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18B9E8",
            },
        [12022309] = {
            ["Content"] = "听鸦原一别后，我寻思师兄可能往尘漠石海的方向去了，便在这附近徘徊游荡。",
            ["ContentJP"] = "鴉の孤原で別れたあと、ユーミンが塵砂の荒海のほうへ向かったんじゃないかと思ってさ、この辺りをあてもなく、うろついてたんだよ。",
            ["DialogueId"] = 12022309,
            ["GUID"] = "1E18BA12",
            ["NextDialogue"] = 12022310,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA12",
            },
        [12022310] = {
            ["Content"] = "不想那祭坛处突然刮起大风，天地震荡。我便赶过来瞧，结果竟碰上了你……若是来得早点就好了！",
            ["ContentJP"] = "そうしたら、祭壇からどでかい突風が吹いてきて、その上、地震がだろ？何事かと駆けつけたら、あんたに出くわしたってわけだ。くそっ、もっと早く来れていたら……！",
            ["DialogueId"] = 12022310,
            ["GUID"] = "1E18BA3C",
            ["NextDialogue"] = 12022311,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA3C",
            },
        [12022311] = {
            ["Content"] = "我和你说，刚刚发生的事情太可怕了！就算十个你来了也没用！",
            ["ContentJP"] = "聞いてよ！ほんっっっっと怖かったんだから！あんたなんか、十人いても意味ないね！",
            ["DialogueId"] = 12022311,
            ["GUID"] = "1E18BA66",
            ["NextDialogue"] = 12022312,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA66",
            },
        [12022312] = {
            ["Content"] = "那个女人，她不仅把本魔王和小仆从囚禁起来，还硬生生地吞了一条龙！那可是龙诶！",
            ["ContentJP"] = "シリュウのやつ、私と下僕を閉じ込めたあげく、あの黒龍をぱっくり食べたんだよ！？龍を！もう怖すぎるって！！",
            ["DialogueId"] = 12022312,
            ["GUID"] = "1E18BA90",
            ["NextDialogue"] = 12022313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BA90",
            },
        [12022313] = {
            ["Content"] = "白现在想想还心有余悸……竟然和这样的人相处了这么久！",
            ["ContentJP"] = "思い出しただけでゾッとするぞ……あんな人とずっと一緒にいたなんて！",
            ["DialogueId"] = 12022313,
            ["GUID"] = "1E18BABA",
            ["NextDialogue"] = 12022314,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BABA",
            },
        [12022314] = {
            ["Content"] = "{nickname}，真有此事吗？",
            ["ContentJP"] = "{nickname}さん、今の話は本当ですか？",
            ["DialogueId"] = 12022314,
            ["GUID"] = "1E18BAE4",
            ["NextOptions"] = {
                [1] = 12022315,
                },
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BAE4",
            },
        [12022315] = {
            ["Content"] = "（讲述事情经过。）",
            ["ContentJP"] = "これまでの出来事を話す",
            ["DialogueId"] = 12022315,
            ["GUID"] = "1E18BB0E",
            ["NextDialogue"] = 12022327,
            },
        [12022316] = {
            ["Content"] = "她弄这么一出，到底是何居心？",
            ["ContentJP"] = "あいつ、いったい何を企んでるんだ！？",
            ["DialogueId"] = 12022316,
            ["GUID"] = "1E18BB38",
            ["NextDialogue"] = 12022317,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BB38",
            },
        [12022317] = {
            ["Content"] = "我也回答不上来……",
            ["ContentJP"] = "それは……{性别:僕|私}にもわからない。",
            ["DialogueId"] = 12022317,
            ["GUID"] = "1E18BB62",
            ["NextDialogue"] = 12022318,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BB62",
            },
        [12022318] = {
            ["Content"] = "依我看，她就是想霸占烛阴的力量，征服世界，成为大魔王！",
            ["ContentJP"] = "見ればわかるでしょ！<Default note=\"text:しょくいん\">燭陰</>の力を独り占めして、世界征服を企んでるんだよ！きっと魔王の座を狙ってるに決まってるよ！",
            ["DialogueId"] = 12022318,
            ["GUID"] = "1E18BB8C",
            ["NextDialogue"] = 12022319,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BB8C",
            },
        [12022319] = {
            ["Content"] = "征服世界……吗……",
            ["ContentJP"] = "そうなの……かな……",
            ["DialogueId"] = 12022319,
            ["GUID"] = "1E18BBB6",
            ["NextDialogue"] = 12022320,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BBB6",
            },
        [12022320] = {
            ["Content"] = "她当时的确说了那样的话……",
            ["ContentJP"] = "確かにそんなこと言ってたような……",
            ["DialogueId"] = 12022320,
            ["GUID"] = "1E18BBE0",
            ["NextDialogue"] = 12022321,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BBE0",
            },
        [12022321] = {
            ["Content"] = "<H>白龙神君</>的时代，该结束了。而我，将执起祂的权柄。",
            ["ContentJP"] = "<H>白龍様</>の時代は、いい加減終わるべきよ。そしてこの私が、その御力を引き継ぐ。",
            ["DialogueId"] = 12022321,
            ["GUID"] = "1E18BC0A",
            ["NextDialogue"] = 12022322,
            ["SpeakNpcId"] = 210004,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC0A",
            },
        [12022322] = {
            ["Content"] = "她……想自己<H>成神</>吗？",
            ["ContentJP"] = "彼女は……<H>神</>になりたいのかな。",
            ["DialogueId"] = 12022322,
            ["GUID"] = "1E18BC34",
            ["NextDialogue"] = 12022323,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC34",
            },
        [12022323] = {
            ["Content"] = "依你所述，若止流早在万里之外的“冰湖城”就已开始布局，那她的计划恐怕比你我能猜到的更加周密。",
            ["ContentJP"] = "その話を聞く限り、もしシリュウさんが遥か遠く「アイスレイク城」にいた頃から、既に策を巡らせていたとすれば……私たちが想像するより遥かに綿密で、深いものかもしれませんね。",
            ["DialogueId"] = 12022323,
            ["GUID"] = "1E18BC5E",
            ["NextDialogue"] = 12022324,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC5E",
            },
        [12022324] = {
            ["Content"] = "我看一时半会儿也商量不出啥，咱们不如都先回去收集些情报！唉，本来只是溜出来找师兄，不想竟撞见了不得了的大事……",
            ["ContentJP"] = "ここでアレコレ言っても、答えは出ねぇよ。とりあえず、一度戻って情報を集めようぜ！……ったく、ユーミンを探しにちょっと抜け出しただけのつもりが、まさかこんな大ごとに巻き込まれるとはな……",
            ["DialogueId"] = 12022324,
            ["GUID"] = "1E18BC88",
            ["NextDialogue"] = 12022325,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BC88",
            },
        [12022325] = {
            ["Content"] = "我得回去山外山一趟，把这事儿告诉他们才行。这样就算出了更大的变故，他们也好有个应对。",
            ["ContentJP"] = "俺は一度山外山に戻るわ。この一件、向こうにもちゃんと伝えておかねぇと。……これ以上の異変に備えてな。",
            ["DialogueId"] = 12022325,
            ["GUID"] = "1E18BCB2",
            ["NextDialogue"] = 12022326,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BCB2",
            },
        [12022326] = {
            ["Content"] = "我也会去无由生处打听消息。它们有些生于上古年间，或许了解失传的历史密辛。",
            ["ContentJP"] = "私もムユウセイの地へ赴き、情報を探ってまいります。彼らの中には太古の昔より生きる者もおり、失われた歴史の秘密を知る者がいるかもしれませんから。",
            ["DialogueId"] = 12022326,
            ["GUID"] = "1E18BCDC",
            ["NextDialogue"] = 12022328,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BCDC",
            },
        [12022327] = {
            ["Content"] = "……我就知道，和黑瞎子一伙的，准没什么好东西！",
            ["ContentJP"] = "やっぱりな。",
            ["DialogueId"] = 12022327,
            ["GUID"] = "120223151.0",
            ["NextDialogue"] = 12022316,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/120223151",
            },
        [12022328] = {
            ["Content"] = "{nickname}，你作何打算？",
            ["ContentJP"] = "{nickname}、あんたはどうするんだ？",
            ["DialogueId"] = 12022328,
            ["GUID"] = "1E18BD30",
            ["NextOptions"] = {
                [1] = 120223281,
                [2] = 120223282,
                },
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BD30",
            },
        [12022329] = {
            ["Content"] = "{性别：兄弟|姑娘}你竟也是一位心忧天下的侠士，刻舟果然不曾结交错人！",
            ["ContentJP"] = "{性别:兄弟|嬢ちゃん}、あんたも世を憂う侠士だったとはな。俺の目は狂ってなかったぜ！",
            ["DialogueId"] = 12022329,
            ["GUID"] = "1E18BD5A",
            ["NextDialogue"] = 12022331,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BD5A",
            },
        [12022330] = {
            ["Content"] = "由你一人承担诸多事宜，属实辛苦了。",
            ["ContentJP"] = "一人でたくさん抱え込んで、さぞかしお疲れでしょう。",
            ["DialogueId"] = 12022330,
            ["GUID"] = "1E18BD84",
            ["NextDialogue"] = 12022331,
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BD84",
            },
        [12022331] = {
            ["Content"] = "眼见着太阳都快没影了，我们赶紧下山去吧。这儿到了晚上可是寒冷刺骨，继续在这待下去也没用。",
            ["ContentJP"] = "もう日も暮れかけてるし、さっさと下山しようぜ。ここは夜になると骨身に染みる寒さだ。いつまでもここにいても仕方ねぇだろ。",
            ["DialogueId"] = 12022331,
            ["GUID"] = "1E18BDAE",
            ["NextDialogue"] = 12022332,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BDAE",
            },
        [12022332] = {
            ["Content"] = "先离去吧。",
            ["ContentJP"] = "そうですね。",
            ["DialogueId"] = 12022332,
            ["GUID"] = "1E18BDD8",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120223/1E18BDD8",
            },
        [12022401] = {
            ["Content"] = "等等，说好要给我们的报酬，该不会也要赖掉了吧？",
            ["ContentJP"] = "ちょっと待ってよ！約束してた報酬、まさかナシってことないよね？",
            ["DialogueId"] = 12022401,
            ["Duration"] = 3,
            ["GUID"] = "1E18C92A",
            ["NextDialogue"] = 12022402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120224/1E18C92A",
            },
        [12022402] = {
            ["Content"] = "委托就这样黄了……小仆从，你说我们大老远来华胥，是不是白跑一趟？",
            ["ContentJP"] = "依頼がパーになっちゃうなんて……はるばる<Default note=\"text:カショ\">華胥</>まで、タダ働きに来たってこと！？",
            ["DialogueId"] = 12022402,
            ["Duration"] = 4,
            ["GUID"] = "1E18C954",
            ["NextDialogue"] = 12022403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120224/1E18C954",
            },
        [12022403] = {
            ["Content"] = "倒是还有止流给我们的天价零花钱就是了，也不亏。早知道，当初就该多拿点花！",
            ["ContentJP"] = "まあ、シリュウがくれたお小遣いはすごい額だったけどね。どうせならもっと贅沢しとけばよかったー！",
            ["DialogueId"] = 12022403,
            ["Duration"] = 4,
            ["GUID"] = "1E18C97E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120224/1E18C97E",
            },
        [12022501] = {
            ["Content"] = "天地大德，其名为生。戕身害命，不可为也。",
            ["ContentJP"] = "天地の大徳、生と称す。身を戕い、命を奪うこと、為すべからず。",
            ["DialogueId"] = 12022501,
            ["GUID"] = "1E18D992",
            ["NextDialogue"] = 12022502,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18D992",
            },
        [12022502] = {
            ["Content"] = "夫人根基，定文为信。毁约背盟，不可为也。",
            ["ContentJP"] = "人の根、信に立つ。誓いを破り、盟を背くこと、為すべからず。",
            ["DialogueId"] = 12022502,
            ["GUID"] = "1E18D9BC",
            ["NextDialogue"] = 12022503,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18D9BC",
            },
        [12022503] = {
            ["Content"] = "著真去伪，赤心为诚。妄言欺众，不可为也。",
            ["ContentJP"] = "真を著し、偽を払うは、赤心の証。虚を語り、衆を惑わすこと、為すべからず。",
            ["DialogueId"] = 12022503,
            ["GUID"] = "1E18D9E6",
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18D9E6",
            },
        [12022504] = {
            ["Content"] = "卑以自牧，束己为谦。骄狂跋扈，不可为也。",
            ["ContentJP"] = "己を抑え、慎みを守るは謙なり。驕りて狂い、道を踏み外すこと、為すべからず。",
            ["DialogueId"] = 12022504,
            ["GUID"] = "1E18DA10",
            ["NextDialogue"] = 12022505,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA10",
            },
        [12022505] = {
            ["Content"] = "尊贤友客，守序为礼。放诞无忌，不可为也。",
            ["ContentJP"] = "賢を敬し、客を友とし、序を正すは礼なり。節を乱し、礼を蔑ろにすること、為すべからず。",
            ["DialogueId"] = 12022505,
            ["GUID"] = "1E18DA3A",
            ["NextDialogue"] = 12022506,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA3A",
            },
        [12022506] = {
            ["Content"] = "以我及人，制宜为义。恃强凌弱，不可为也。",
            ["ContentJP"] = "我をもって他を量り、宜しく処するは義なり。強きを恃み、弱きを虐ぐること、為すべからず。",
            ["DialogueId"] = 12022506,
            ["GUID"] = "1E18DA64",
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA64",
            },
        [12022507] = {
            ["Content"] = "清心敛行，身正为廉。枉法贪酷，不可为也。",
            ["ContentJP"] = "心を清め、行を慎むは廉なり。法を曲げ、貪り極むること、為すべからず。",
            ["DialogueId"] = 12022507,
            ["GUID"] = "1E18DA8E",
            ["NextDialogue"] = 12022508,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DA8E",
            },
        [12022508] = {
            ["Content"] = "裁辨是非，知之为明。淆乱颠倒，不可为也。",
            ["ContentJP"] = "是を是とし、非を非と知るは明なり。理を乱し、真を覆すこと、為すべからず。",
            ["DialogueId"] = 12022508,
            ["GUID"] = "1E18DAB8",
            ["NextDialogue"] = 12022509,
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DAB8",
            },
        [12022509] = {
            ["Content"] = "垂聆天宪，恭肃为敬。离经叛道，不可为也。",
            ["ContentJP"] = "天の戒を仰ぎ、慎みて従うは敬なり。道を離れ、教えに逆らうこと、為すべからず。",
            ["DialogueId"] = 12022509,
            ["GUID"] = "1E18DAE2",
            ["SnapShot"] = "ECHO",
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DAE2",
            },
        [12022510] = {
            ["Content"] = "我们继续前行吧。",
            ["ContentJP"] = "さあ、進みましょう。",
            ["DialogueId"] = 12022510,
            ["GUID"] = "1E18DAE3",
            ["SpeakNpcId"] = 210013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120225/1E18DAE3",
            },
        [12022511] = {
            ["Content"] = "让开，让我来解决祂。",
            ["ContentJP"] = "どきなさい、私がトドメをさすわ。",
            ["DialogueId"] = 12022511,
            ["Duration"] = 4,
            ["GUID"] = "1E18DB36",
            },
        [12022512] = {
            ["Content"] = "等等！",
            ["ContentJP"] = "待ってください！",
            ["DialogueId"] = 12022512,
            ["Duration"] = 4,
            ["GUID"] = "1E18DB60",
            },
        [12022513] = {
            ["Content"] = "喂，这里发生什么了？——放开{性别：他|她}！",
            ["ContentJP"] = "いったい何があったんだ……おい、{性别:彼|彼女}を放せ！",
            ["DialogueId"] = 12022513,
            ["Duration"] = 4,
            ["GUID"] = "1E18DB8A",
            },
        [12022514] = {
            ["Content"] = "到咯！",
            ["ContentJP"] = "ついたぞ！",
            ["DialogueId"] = 12022514,
            ["Duration"] = 4,
            ["GUID"] = "1E18DBB4",
            },
        }
  end },
