            },
        [12023809] = {
            ["Content"] = "【战斗】烛阴BOSS战",
            ["DialogueId"] = 12023809,
            ["Duration"] = 4,
            ["GUID"] = "1E19B02A",
            },
        [12023810] = {
            ["Content"] = "【机关】采集黑龙鳞",
            ["DialogueId"] = 12023810,
            ["Duration"] = 4,
            ["GUID"] = "1E19B054",
            },
        [12023811] = {
            ["Content"] = "【系统（战斗轮盘）-引导需求】\
1.UI：引导打开军械库轮盘装备<牵机公枢>\
2.UI：引导打开探索背包启用<牵机关公枢>",
            ["DialogueId"] = 12023811,
