            ["GUID"] = "1E19B07E",
            },
        [12023812] = {
            ["Content"] = "【玩法（吸收晶垢-引导需求】\
1.图文:使用机关对着晶垢吸，去除晶垢",
            ["DialogueId"] = 12023812,
            ["Duration"] = 4,
            ["GUID"] = "1E19B0A8",
            },
        [12023850] = {
            ["Content"] = "烟津掠影蔽香尘",
            ["ContentJP"] = "煙津に影掠れ香塵を覆う",
            ["DialogueId"] = 12023850,
            ["GUID"] = "1E19B0A1",
            },
        [12023851] = {
            ["Content"] = "终",
            ["ContentJP"] = "完",
            ["DialogueId"] = 12023851,
            ["GUID"] = "1E19B0A2",
            },
        [12023852] = {
            ["Content"] = "未完待续",
            ["ContentJP"] = "つづく",
            ["DialogueId"] = 12023852,
            ["GUID"] = "1E19B0A3",
            },
        [12025001] = {
            ["Content"] = "又一船货物到了！兄弟们，清点好名单再搬运，切莫急躁，心急吃不到热豆腐哟。",
            ["ContentJP"] = "また荷物の船が着いたぞ！みんな、名簿をちゃんと確認してから運ぶんだ。焦っちゃ駄目だぜ、急いては事を仕損じるからな。",
            ["DialogueId"] = 12025001,
            ["GUID"] = "1E1A73BA",
            ["SpeakNpcId"] = 210112,
            },
        [12025101] = {
            ["Content"] = "针头线脑，香脂香囊，走过路过不要错过——",
            ["ContentJP"] = "針と糸、香油と香り袋――通りすがりのお客さん、お見逃しなく～！",
            ["DialogueId"] = 12025101,
            ["GUID"] = "1E1A8422",
            ["SpeakNpcId"] = 210113,
            },
        [12025201] = {
            ["Content"] = "哟，{性别：小弟弟|小妹妹}，你来啦。看中了什么随便挑，你是止流大当家的客人，那便也是我的客人。",
            ["ContentJP"] = "おや、{性别:ぼうず|嬢ちゃん}、来てくれたのかい。欲しいものがあれば好きに選びな。シリュウ当主の客なら、うちにとっちゃあんたも大事なお客さんだ。",
            ["DialogueId"] = 12025201,
            ["GUID"] = "1E1A948A",
            ["NextOptions"] = {
                [1] = 12025203,
                [2] = 12025212,
                },
            ["SpeakNpcId"] = 210113,
            },
        [12025203] = {
            ["Content"] = "你在码头卖这些，生意好吗？",
            ["ContentJP"] = "港でこういうものを売って、商売になるの{性别:か|}？",
            ["DialogueId"] = 12025203,
            ["GUID"] = "1E1A94DE",
            ["NextDialogue"] = 12025204,
            },
        [12025204] = {
            ["Content"] = "哈哈，做生意，无非是一个找到客户需求，满足客户需求的过程。这便是织星客上路的第一门诀窍。",
            ["ContentJP"] = "ははは、商売ってのはね、要するに「客の欲しがる物を見つけて、それを満たす」ってことさ。これが星織人が旅に出るとき、最初に覚えるコツってやつだ。",
            ["DialogueId"] = 12025204,
            ["GUID"] = "1E1A9508",
            ["NextDialogue"] = 12025205,
            ["SpeakNpcId"] = 210113,
            },
        [12025205] = {
            ["Content"] = "织星客远航出海，在船上常常一待就要带上个把月。",
            ["ContentJP"] = "星織人は遠洋に出れば、船の上で一か月なんてざらだからね。",
            ["DialogueId"] = 12025205,
            ["GUID"] = "1E1A9532",
            ["NextDialogue"] = 12025206,
            ["SpeakNpcId"] = 210113,
            },
        [12025206] = {
            ["Content"] = "总有些冒失鬼，临到出航前才发现这没带那没带。我这些生活杂货呀，就起到一个江湖救急的作用——当然，价格那也是绝对实惠，童叟无欺！",
            ["ContentJP"] = "出航直前になって「あれが無い、これが無い」って気づくおっちょこちょいが必ずいるんだ。そんなとき、うちみたいな生活雑貨が役に立つってわけ——もちろん値段も良心的、ぼったくりなんてしないさ！",
            ["DialogueId"] = 12025206,
            ["GUID"] = "1E1A955C",
            ["NextDialogue"] = 12025207,
            ["SpeakNpcId"] = 210113,
            },
        [12025207] = {
            ["Content"] = "离开华胥的游客，在等渡船的过程中，也往往要带上几样特色纪念品。销量这不就来了？",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>を離れる観光客も、渡し船を待つ間に記念品を買っていく。それで売れ行きが伸びるって寸法よ。",
            ["DialogueId"] = 12025207,
            ["GUID"] = "1E1A9586",
            ["NextDialogue"] = 12025208,
            ["SpeakNpcId"] = 210113,
            },
        [12025208] = {
            ["Content"] = "更何况，本小店还有一个赚钱的独家诀窍——",
            ["ContentJP"] = "それに、うちの店にはもうひとつ「稼げる秘訣」があってね——",
            ["DialogueId"] = 12025208,
            ["GUID"] = "1E1A95B0",
            ["NextOptions"] = {
                [1] = 12025209,
                },
            ["SpeakNpcId"] = 210113,
            },
        [12025209] = {
            ["Content"] = "什么诀窍？",
            ["ContentJP"] = "どんな秘訣？",
            ["DialogueId"] = 12025209,
            ["GUID"] = "1E1A95DA",
            ["NextDialogue"] = 12025210,
            },
        [12025210] = {
            ["Content"] = "{性别：小弟弟|小妹妹}，刚刚我送你的香囊，可不是什么普通物什，而是获得悬衡派授权的独家限量版香囊。",
            ["ContentJP"] = "{性别:ぼうず|嬢ちゃん}，さっきあんたに渡した香袋、ありゃ普通の品じゃないんだ。<Default note=\"text:けんこうは\">懸衡派</>が正式に許可した「限定版香袋」なんだよ。",
            ["DialogueId"] = 12025210,
            ["GUID"] = "1E1A9604",
            ["NextDialogue"] = 12025211,
            ["SpeakNpcId"] = 210113,
            },
        [12025211] = {
            ["Content"] = "类似的香囊在华胥各地只有几家能贩售，款式还各有不同，香囊爱好者自然是趋之若鹜。我这摊子在烟津渡到此必游的清单里，也是榜上有名呢！",
            ["ContentJP"] = "似たようなのを扱ってる店は<Default note=\"text:カショ\">華胥</>でもごく少数で、それぞれ柄も違う。香袋好きの人たちは放っておかないってわけ。うちの屋台が「<Default note=\"text:えんしんと\">煙津渡</>に来たら必ず寄る名物スポット」として評判なのも、そのおかげさ。",
            ["DialogueId"] = 12025211,
            ["GUID"] = "1E1A962E",
            ["SpeakNpcId"] = 210113,
            },
        [12025212] = {
            ["Content"] = "你也承过止流掌柜的人情吗？",
            ["ContentJP"] = "シリュウさんに恩でもあるの？",
            ["DialogueId"] = 12025212,
            ["GUID"] = "1E1A9658",
            ["NextDialogue"] = 12025213,
            },
        [12025213] = {
            ["Content"] = "当年我押上全部身家的一船货物不小心遇到海难，全翻了。我这半辈子的积蓄一夜之间打了水漂。",
            ["ContentJP"] = "ああ、あるとも。昔、全財産を積んだ荷船が海難に遭ってね……全部失っちまったんだ。半生の貯えが、一晩で水の泡さ。",
            ["DialogueId"] = 12025213,
            ["GUID"] = "1E1A9682",
            ["NextDialogue"] = 12025214,
            ["SpeakNpcId"] = 210113,
            },
        [12025214] = {
            ["Content"] = "我去百年春延期借款时偶遇了止流大当家。她听了我的遭遇后，把我的借款一笔勾销了，还额外给我了笔启动资金。",
            ["ContentJP"] = "借金を延長してもらいに<Default note=\"text:ももとき\">百年春</>へ行ったときに、ちょうどシリュウ当主と会ってね。事情を話したら、借金をきれいに帳消しにしてくれて、しかも再出発の資金まで渡してくれたんだ。",
            ["DialogueId"] = 12025214,
            ["GUID"] = "1E1A96AC",
            ["NextDialogue"] = 12025215,
            ["SpeakNpcId"] = 210113,
            },
        [12025215] = {
            ["Content"] = "对她而言，这可能只是一点不值一提的小恩惠，却是实实在在地改变了我的人生。",
            ["ContentJP"] = "あの人にとっちゃ大したことない小さな施しだったのかもしれない。でも、あれは間違いなく俺の人生を救ってくれた恩だよ。",
            ["DialogueId"] = 12025215,
            ["GUID"] = "1E1A96D6",
            ["NextDialogue"] = 12025216,
            ["SpeakNpcId"] = 210113,
            },
        [12025216] = {
            ["Content"] = "后来那笔钱我早就还上了，但止流大当家的人情我可是一直记在心里。{性别：小弟弟|小妹妹}，要是你以后有什么忙需要我帮，直接开口，千万不用客气哈。",
            ["ContentJP"] = "借りた金はとっくに返したけど……シリュウ当主への恩は、今もずっと忘れずにいる。{性别:ぼうず|嬢ちゃん}、もしあんたが将来困ったことがあったら、そのときは遠慮なく言ってくれよ。",
            ["DialogueId"] = 12025216,
            ["GUID"] = "1E1A9700",
            ["SpeakNpcId"] = 210113,
            },
        [12025301] = {
            ["Content"] = "是你啊。怎么样，对百年春这边还算熟悉起来了吗？",
            ["ContentJP"] = "あら、あなたなのね。どう？ <Default note=\"text:ももとき\">百年春</>にはもう慣れてきたかしら？",
            ["DialogueId"] = 12025301,
            ["GUID"] = "1E1AA4F2",
            ["NextDialogue"] = 12025302,
            ["SpeakNpcId"] = 210114,
            },
        [12025302] = {
            ["Content"] = "若是有什么人生地不熟的不便之处，来找我，我会尽力帮你解决。",
            ["ContentJP"] = "もし土地勘がなくて困ることがあったら、遠慮しないで私に聞いて。できる限り力になってあげるわよ。",
            ["DialogueId"] = 12025302,
            ["GUID"] = "1E1AA51C",
            ["SpeakNpcId"] = 210114,
            },
        [12025401] = {
            ["Content"] = "{nickname}，还有什么问题想问我吗？尽管开口，我会逐一解答。",
            ["ContentJP"] = "{nickname}、何かほかに聞きたいことはあるかしら？遠慮しないでいいわ。ひとつずつ答えてあげる。",
            ["DialogueId"] = 12025401,
            ["GUID"] = "1E1AB55A",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025402] = {
            ["Content"] = "你好像是个大人物。",
            ["ContentJP"] = "あなた、なんだか大物っぽい{性别:な|ね}。",
            ["DialogueId"] = 12025402,
            ["GUID"] = "1E1AB584",
            ["NextDialogue"] = 12025403,
            },
        [12025403] = {
            ["Content"] = "呵呵，都是些身外之名罢了。我已经过了为一些浮名薄利而沾沾自喜的年龄。",
            ["ContentJP"] = "ふふ、そんなのは外につく名前にすぎないわ。もうね、名声や小さな利益に浮かれる年齢じゃないの。",
            ["DialogueId"] = 12025403,
            ["GUID"] = "1E1AB5AE",
            ["NextDialogue"] = 12025404,
            ["SpeakNpcId"] = 210115,
            },
        [12025404] = {
            ["Content"] = "止流掌柜，我可以冒昧问一句，你今年多大了吗？",
            ["ContentJP"] = "シリュウさん、失礼ですが……今年って、おいくつなんですか？",
            ["DialogueId"] = 12025404,
            ["GUID"] = "1E1AB5D8",
            ["NextDialogue"] = 12025405,
            ["SpeakNpcId"] = 100001,
            },
        [12025405] = {
            ["Content"] = "嗯，这可是个危险的问题……卡米拉没有教过你这个道理吗？还是让我们之间保留一些神秘感吧。",
            ["ContentJP"] = "あら、それはちょっと危険な質問よ？カミラに「女性に年齢を聞いては駄目」って教わらなかったかしら。ふふ……少しぐらい、あなたと私の間に謎が残っていた方がいいでしょう？",
            ["DialogueId"] = 12025405,
            ["GUID"] = "1E1AB602",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025406] = {
            ["Content"] = "百年春是个什么样的商会？",
            ["ContentJP"] = "百年春ってどんな商会なの{性别:か|}？",
            ["DialogueId"] = 12025406,
            ["GUID"] = "1E1AB62C",
            ["NextDialogue"] = 12025407,
            },
        [12025407] = {
            ["Content"] = "它的历史与织星客一般悠久，可以上溯到华胥立国之初。",
            ["ContentJP"] = "その歴史は<Default note=\"text:ほしおりびと\">星織人</>と同じくらい古く、<Default note=\"text:カショ\">華胥</>建国の頃にまで遡れるの。",
            ["DialogueId"] = 12025407,
            ["GUID"] = "1E1AB656",
            ["NextDialogue"] = 12025408,
            ["SpeakNpcId"] = 210115,
            },
        [12025408] = {
            ["Content"] = "起先，百年春只是诸多民间商会之一。但随着历史演变，它逐渐承担起了如同织星客行会一般的影响力。",
            ["ContentJP"] = "最初の百年春は、ただの民間商会のひとつでしかなかったわ。でも時代が進むにつれ、星織人の組合と同じくらいの影響力を持つようになったの。",
            ["DialogueId"] = 12025408,
            ["GUID"] = "1E1AB680",
            ["NextDialogue"] = 12025409,
            ["SpeakNpcId"] = 210115,
            },
        [12025409] = {
            ["Content"] = "再后来，天禄司将其收编国有，百年春肩负起了给织星客颁发贸易许可、拨发借款等诸多社会功能。",
            ["ContentJP"] = "さらに後になって<Default note=\"text:てんろくし\">天禄司</>に国有化されてからは、<Default note=\"text:ほしおりびと\">星織人</>への貿易許可の発行、貸付金の管理など……さまざまな社会的役割を担うようになったわ。",
            ["DialogueId"] = 12025409,
            ["GUID"] = "1E1AB6AA",
            ["NextDialogue"] = 12025410,
            ["SpeakNpcId"] = 210115,
            },
        [12025410] = {
            ["Content"] = "更具体的情况，你可以去问我的秘书望春。她会为你详细解答。",
            ["ContentJP"] = "もっと詳しい内容は、わたしの秘書、望春に聞くといいわ。彼女なら丁寧に教えてくれるはずよ。",
            ["DialogueId"] = 12025410,
            ["GUID"] = "1E1AB6D4",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025411] = {
            ["Content"] = "烛阴之灾能顺利解决吗？",
            ["ContentJP"] = "燭陰の禍って、解決できるの{性别:か|}？",
            ["DialogueId"] = 12025411,
            ["GUID"] = "1E1AB6FE",
            ["NextDialogue"] = 12025412,
            },
        [12025412] = {
            ["Content"] = "比起给你一个确切的答案，我更愿意相信事在人为。",
            ["ContentJP"] = "確かな答えを出すより、わたしは「人の手で道を切り開く」ということを信じたいわ。",
            ["DialogueId"] = 12025412,
            ["GUID"] = "1E1AB728",
            ["NextDialogue"] = 12025413,
            ["SpeakNpcId"] = 210115,
            },
        [12025413] = {
            ["Content"] = "不过……虽然烛阴之灾来势汹汹，但百年春众人已经做了足够多的筹备，如今还有了你的加入。所以我相信它能够顺利解决。",
            ["ContentJP"] = "……とはいえ、<Default note=\"text:しょくいん\">燭陰</>の禍は確かに勢いが激しい。けれど百年春のみんなは準備を重ねてきたし、今はあなたも力を貸してくれている。だからこそ——わたしは解決できると信じているの。",
            ["DialogueId"] = 12025413,
            ["GUID"] = "1E1AB752",
            ["NextDialogue"] = 12025414,
            ["SpeakNpcId"] = 210115,
            },
        [12025414] = {
            ["Content"] = "止流掌柜，你好像很有把握的样子。",
            ["ContentJP"] = "シリュウさん、なんだかすごく自信ありそうですね。",
            ["DialogueId"] = 12025414,
            ["GUID"] = "1E1AB77C",
            ["NextDialogue"] = 12025415,
            ["SpeakNpcId"] = 100001,
            },
        [12025415] = {
            ["Content"] = "你想做成的事情，至今没有失败过的吗？这使我有点好奇。",
            ["ContentJP"] = "シリュウさんが成し遂げようとして、失敗したことって……今までないんですか？気になっちゃって。",
            ["DialogueId"] = 12025415,
            ["GUID"] = "1E1AB7A6",
            ["NextDialogue"] = 12025416,
            ["SpeakNpcId"] = 100001,
            },
        [12025416] = {
            ["Content"] = "呵呵……你猜？",
            ["ContentJP"] = "ふふ……さて、どうかしらね？ さあ、あなたはどう思う？",
            ["DialogueId"] = 12025416,
            ["GUID"] = "1E1AB7D0",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025417] = {
            ["Content"] = "我应该怎么去黑市拿工具？",
            ["ContentJP"] = "どうやって闇市に道具を取りに行けばいい？",
            ["DialogueId"] = 12025417,
            ["GUID"] = "1E1AB7FA",
            ["NextDialogue"] = 12025418,
            },
        [12025418] = {
            ["Content"] = "初次造访黑市的人，要从沿海洞窟行出，腰上佩饰特定的挂坠。他们见着这“暗号”对上了，就会知道你是自己人。",
            ["ContentJP"] = "闇市を初めて訪れる人は、海沿いの洞窟から向かって、腰に特定の飾りを下げておくの。それが「合言葉代わり」なのよ。それを見れば、向こうも仲間だと分かるわ。",
            ["DialogueId"] = 12025418,
            ["GUID"] = "1E1AB824",
            ["NextDialogue"] = 12025419,
            ["SpeakNpcId"] = 210115,
            },
        [12025419] = {
            ["Content"] = "为什么一定要从沿海洞穴过去，不能从大路走吗？",
            ["ContentJP"] = "なんで海沿いの洞窟から？ 普通に道から行っちゃ駄目？",
            ["DialogueId"] = 12025419,
            ["GUID"] = "1E1AB84E",
            ["NextDialogue"] = 12025420,
            ["SpeakNpcId"] = 100001,
            },
        [12025420] = {
            ["Content"] = "如我所说，这是暗号的一环。",
            ["ContentJP"] = "言ったでしょう？ それが暗号の一部なの。",
            ["DialogueId"] = 12025420,
            ["GUID"] = "1E1AB878",
            ["NextDialogue"] = 12025421,
            ["SpeakNpcId"] = 210115,
            },
        [12025421] = {
            ["Content"] = "想以各种理由混入黑市的无关人士不在少数。如果没有一些用来分辨“自己人”的手段，他们的老大也会很头疼呢。",
            ["ContentJP"] = "闇市には、いろんな理由で潜り込もうとする不審者が後を絶たないのよ。だから「身内を判別する仕組み」が必要なの。そうじゃないと、闇市の親分も苦労してしまうわ。",
            ["DialogueId"] = 12025421,
            ["GUID"] = "1E1AB8A2",
            ["NextDialogue"] = 12025425,
            ["SpeakNpcId"] = 210115,
            },
        [12025422] = {
            ["Content"] = "没什么想问的。",
            ["ContentJP"] = "もう聞きたいことはないよ。",
            ["DialogueId"] = 12025422,
            ["GUID"] = "1E1AB8CC",
            ["NextDialogue"] = 12025423,
            },
        [12025423] = {
            ["Content"] = "{nickname}，你要出发了吗？",
            ["ContentJP"] = "{nickname}、もう出発するのね？",
            ["DialogueId"] = 12025423,
            ["GUID"] = "1E1AB8F6",
            ["NextDialogue"] = 12025424,
            ["SpeakNpcId"] = 210115,
            },
        [12025424] = {
            ["Content"] = "一路小心，我等着你平安归来。",
            ["ContentJP"] = "道中、気をつけて。あなたが無事に戻ってくるのを、わたしはここで待っているわ。",
            ["DialogueId"] = 12025424,
            ["GUID"] = "1E1AB920",
            ["SpeakNpcId"] = 210115,
            },
        [12025425] = {
            ["DialogueId"] = 12025425,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025423,
            ["GUID"] = "1E1AB921",
            ["NextOptions"] = {
                [1] = 12025402,
                [2] = 12025406,
                [3] = 12025411,
                [4] = 12025417,
                [5] = 12025422,
                },
            },
        [12025501] = {
            ["Content"] = "您就是止流大当家从帝国不远千里请来的贵客吧。没想到您这么年轻俊俏……啊不，年轻有为！",
            ["ContentJP"] = "あなたが、シリュウ様が帝国からはるばるお招きした「特別なお客さま」ですよね。こんなに若くてかっこいい……いえっ、若くて有望な方だとは思いませんでした！",
            ["DialogueId"] = 12025501,
            ["GUID"] = "1E1AC5C2",
            ["NextDialogue"] = 12025502,
            ["SpeakNpcId"] = 210116,
            },
        [12025502] = {
            ["Content"] = "止流大当家平时太忙了，总有事务缠身，很少能有闲下来的时候。要是有什么照顾不周的地方，您来找我，我都会帮您处理！",
            ["ContentJP"] = "シリュウ様はいつもとてもお忙しくて、手の離せない用件が山ほどあるんです。もし何か至らないところがあれば、どうぞ私にお声がけください。必ずお手伝いします！",
            ["DialogueId"] = 12025502,
            ["GUID"] = "1E1AC5EC",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025503] = {
            ["Content"] = "百年春是个什么样的商会？",
            ["ContentJP"] = "百年春ってどんな商会なの{性别:か|}？",
            ["DialogueId"] = 12025503,
            ["GUID"] = "1E1AC616",
            ["NextDialogue"] = 12025504,
            },
        [12025504] = {
            ["Content"] = "不仅在烟津渡，对于整个皓京来说，百年春都是这里规模最大的商会了。",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>は、<Default note=\"text:えんしんと\">煙津渡</>だけでなく、<Default note=\"text:こうけい\">皓京</>全体でも最大規模の商会です。",
            ["DialogueId"] = 12025504,
            ["GUID"] = "1E1AC640",
            ["NextDialogue"] = 12025505,
            ["SpeakNpcId"] = 210116,
            },
        [12025505] = {
            ["Content"] = "华胥人的生活更是离不开百年春，无论是采购日用品，抑或西洋舶来的珍贵货物，再到香料的运输供给，正式成为一名织星客……都与我们百年春脱不开干系。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>の人々の暮らしは<Default note=\"text:ももとき\">百年春</>と深く結びついていて、日用品の仕入れ、西洋から運ばれてくる貴重な品、香料の供給、さらには正式な<Default note=\"text:ほしおりびと\">星織人</>になるための手続きに至るまで……すべて<Default note=\"text:ももとき\">百年春</>が関わっているんですよ。",
            ["DialogueId"] = 12025505,
            ["GUID"] = "1E1AC66A",
            ["NextDialogue"] = 12025506,
            ["SpeakNpcId"] = 210116,
            },
        [12025506] = {
            ["Content"] = "如您面前所见，百年春前各个摊贩售卖着天南海北的商品，您可以自由采购。这里的交易受到天禄司和大风九章的担保。",
            ["ContentJP"] = "見てのとおり、<Default note=\"text:ももとき\">百年春</>の前には各地の特産品を並べた屋台がずらりと並んでいて、自由に見て回れます。ここでの取引は、<Default note=\"text:てんろくし\">天禄司</>と<Default note=\"text:たいふうきゅうしょう\">大風九章</>の保障付きですので安心して購入できますよ。",
            ["DialogueId"] = 12025506,
            ["GUID"] = "1E1AC694",
            ["NextDialogue"] = 12025507,
            ["SpeakNpcId"] = 210116,
            },
        [12025507] = {
            ["Content"] = "如果您想成为一名织星客，也可以去旁边的窗口递交手续。我们针对织星客推出了很多扶持计划，不仅能出借起始资金，还有航海技术的全套免费培训。",
            ["ContentJP"] = "もし<Default note=\"text:ほしおりびと\">星織人</>になりたいのでしたら、すぐ隣の窓口で手続きをどうぞ。<Default note=\"text:ももとき\">百年春</>には星織人向けの支援制度がたくさんあって、初期資金の貸付から航海技術の全課程の無料訓練までやっているんです！",
            ["DialogueId"] = 12025507,
            ["GUID"] = "1E1AC6BE",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025508] = {
            ["Content"] = "禁行令对大家的影响很大吗？",
            ["ContentJP"] = "通行禁止令って、みんなにとって負担が大きいの{性别:か|}？",
            ["DialogueId"] = 12025508,
            ["GUID"] = "1E1AC6E8",
            ["NextDialogue"] = 12025509,
            },
        [12025509] = {
            ["Content"] = "禁行令是给众人带来了一些不便……但这也是无奈之举，它主要针对受玄色狴犴影响的内陆区域。",
            ["ContentJP"] = "「通行禁止令」は確かに少し不便をもたらします……でも仕方のない措置なのです。あれは<Default note=\"text:ゲンビー\">玄狴</>の影響を受けた内陸部を中心に出されているもので。",
            ["DialogueId"] = 12025509,
            ["GUID"] = "1E1AC712",
            ["NextDialogue"] = 12025510,
            ["SpeakNpcId"] = 210116,
            },
        [12025510] = {
            ["Content"] = "毕竟，各位的性命安危是百年春首先需要保障的。我相信等到大当家找到方法重新封印烛阴后，大家的生活会很快恢复如初。",
            ["ContentJP"] = "何より皆さまの安全が最優先ですから。シリュウ御当家が<Default note=\"text:しょくいん\">燭陰</>を再び封印する手立てを見つければ、生活はすぐに元通りになるはずです。",
            ["DialogueId"] = 12025510,
            ["GUID"] = "1E1AC73C",
            ["NextDialogue"] = 12025511,
            ["SpeakNpcId"] = 210116,
            },
        [12025511] = {
            ["Content"] = "有了您的帮助，这一天很快就会到来吧。",
            ["ContentJP"] = "あなたのお力も加われば、その日はもっと早く来るでしょうね。",
            ["DialogueId"] = 12025511,
            ["GUID"] = "1E1AC766",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025512] = {
            ["Content"] = "止流掌柜是什么样的人？",
            ["ContentJP"] = "シリュウさんって、どんな人？",
            ["DialogueId"] = 12025512,
            ["GUID"] = "1E1AC790",
            ["NextDialogue"] = 12025513,
            },
        [12025513] = {
            ["Content"] = "大当家她呀，特别厉害！无论多么棘手的事务，她都能轻易化解。",
            ["ContentJP"] = "当主様は……本当にすごい方なんです！どんな難しい問題でも、まるで簡単なことみたいに片づけてしまって。",
            ["DialogueId"] = 12025513,
            ["GUID"] = "1E1AC7BA",
            ["NextDialogue"] = 12025514,
            ["SpeakNpcId"] = 210116,
            },
        [12025514] = {
            ["Content"] = "她身为龙渊上卿，协理天禄司，又管着百年春，我们一般人简直想象不到有多少事务等着她去处理。这些事情要是堆在同一个人身上，早就把那个人压垮了！",
            ["ContentJP"] = "<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>として<Default note=\"text:てんろくし\">天禄司</>を補佐しつつ、<Default note=\"text:ももとき\">百年春</>の経営も取り仕切って……普通の人なら、あんな膨大な事務量、到底抱えきれませんよ！",
            ["DialogueId"] = 12025514,
            ["GUID"] = "1E1AC7E4",
            ["NextDialogue"] = 12025515,
            ["SpeakNpcId"] = 210116,
            },
        [12025515] = {
            ["Content"] = "但对于大当家来说，这好像都不是什么大事。无论什么时候看到她，她都是那么从容不迫，做什么事都游刃有余的样子，让人心里一下子就能安定下来。",
            ["ContentJP"] = "でも当主様にとっては、それら全部が大ごとですらないみたいなんです。いつ見ても落ち着いていて、余裕があって……あの方の姿を見れば、誰だって不思議と安心してしまうんです。",
            ["DialogueId"] = 12025515,
            ["GUID"] = "1E1AC80E",
            ["NextDialogue"] = 12025516,
            ["SpeakNpcId"] = 210116,
            },
        [12025516] = {
            ["Content"] = "呀，我好像一下子滔滔不绝了起来。",
            ["ContentJP"] = "あっ……す、すみません。つい熱く語りすぎちゃいました。",
            ["DialogueId"] = 12025516,
            ["GUID"] = "1E1AC838",
            ["NextDialogue"] = 12025517,
            ["SpeakNpcId"] = 210116,
            },
        [12025517] = {
            ["Content"] = "说出来有点不好意思，我其实非常崇拜大当家……",
            ["ContentJP"] = "恥ずかしいんですが……実は、わたし、当主様のことを心から尊敬していて……",
            ["DialogueId"] = 12025517,
            ["GUID"] = "1E1AC862",
            ["NextDialogue"] = 12025518,
            ["SpeakNpcId"] = 210116,
            },
        [12025518] = {
            ["Content"] = "她好像特别青睐于您。大当家的客人，就是我们百年春的客人！所以您有什么要求尽管说，我会尽量满足的。",
            ["ContentJP"] = "それに、どうやら当主様もあなたのことを特に気に入っているみたい。当主様の客人は、<Default note=\"text:ももとき\">百年春</>全員の客人です！だから、何かご要望があれば遠慮なくおっしゃってくださいね。できる限りお応えします！",
            ["DialogueId"] = 12025518,
            ["GUID"] = "1E1AC88C",
            ["NextDialogue"] = 12025521,
            ["SpeakNpcId"] = 210116,
            },
        [12025519] = {
            ["Content"] = "没什么想问的。",
            ["ContentJP"] = "もう聞きたいことはないよ。",
            ["DialogueId"] = 12025519,
            ["GUID"] = "1E1AC8B6",
            ["NextDialogue"] = 12025520,
            },
        [12025520] = {
            ["Content"] = "如果有需要，随时再来找我！我会一直在这里为您提供服务。",
            ["ContentJP"] = "必要なことがあれば、いつでもどうぞ。ここで、ずっとお待ちしております。",
            ["DialogueId"] = 12025520,
            ["GUID"] = "1E1AC8E0",
            ["SpeakNpcId"] = 210116,
            },
        [12025521] = {
            ["DialogueId"] = 12025521,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025520,
            ["GUID"] = "1E1AC8E1",
            ["NextOptions"] = {
                [1] = 12025503,
                [2] = 12025508,
                [3] = 12025512,
                [4] = 12025519,
                },
            },
        [12025601] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12025601,
            ["GUID"] = "1E1AD62A",
            ["NextDialogue"] = 12025602,
            ["SpeakNpcId"] = 210117,
            },
        [12025602] = {
            ["Content"] = "（这位负伤的应天尉在你眼前沉沉睡去，眉头紧蹙，似乎一时半会不会醒来……）",
            ["ContentJP"] = "（負傷した応天尉はあなたの目の前で深い眠りに落ちていく。険しい眉のまま、しばらくは目を覚ましそうにない……）",
            ["DialogueId"] = 12025602,
            ["GUID"] = "1E1AD654",
            ["NextDialogue"] = 12025603,
            },
        [12025603] = {
            ["Content"] = "（应天尉也会做梦吗？他在自己的梦境中又会看到什么？你不禁开始思考。）",
            ["ContentJP"] = "（応天尉も夢を見るのだろうか？彼は夢の中で何を目にしているのか——そんな疑問がふと胸によぎる。）",
            ["DialogueId"] = 12025603,
            ["GUID"] = "1E1AD67E",
            ["NextDialogue"] = 12025604,
            },
        [12025604] = {
            ["Content"] = "怎么了小仆从，在欣赏本魔王的大作吗？",
            ["ContentJP"] = "どうしたの、我が下僕よ。 この魔王さまの傑作に見惚れちゃった？",
            ["DialogueId"] = 12025604,
            ["GUID"] = "1E1AD6A8",
            ["NextDialogue"] = 12025605,
            ["SpeakNpcName"] = "UI_Npc_Name_Bai",
            },
        [12025605] = {
            ["Content"] = "想要的话，我也可以给你脸上画一个皎皎涂鸦哟！只要是小仆从的要求，白都会满足！",
            ["ContentJP"] = "欲しいなら、あんたの顔にもルーナ族の落書き描いてあげるよ！我が下僕の望みなら、スノウはなんだって叶えてあげるんだから！",
            ["DialogueId"] = 12025605,
            ["GUID"] = "1E1AD6D2",
            ["NextDialogue"] = 12025606,
            ["SpeakNpcName"] = "UI_Npc_Name_Bai",
            },
        [12025606] = {
            ["Content"] = "……谢了，白。我们还是赶紧走吧。",
            ["ContentJP"] = "……ありがとう、スノウ。でも今は……早く行こう。",
            ["DialogueId"] = 12025606,
            ["GUID"] = "1E1AD6FC",
            ["SpeakNpcId"] = 100001,
            },
        }
  end },
  { MinKey = 12025701, MaxKey = 12030511, Loader = function()
      return {
        [12025701] = {
            ["Content"] = "嘿，我说你们俩——还真是止流掌柜的客人。",
            ["ContentJP"] = "おいおい、あんたら二人……本当にシリュウさんのお客さんだったとはね。",
            ["DialogueId"] = 12025701,
            ["GUID"] = "1E1AE692",
            ["NextDialogue"] = 12025702,
            ["SpeakNpcId"] = 210118,
            },
        [12025702] = {
            ["Content"] = "我天天在这儿望风，想混进黑市的人可真不少，各种借口我都听得耳朵起茧子了。但像你们这么冒失的我还是头一回见。",
            ["ContentJP"] = "俺は毎日ここで見張りをしてるが、闇市に潜り込もうとする連中がまぁ多いこと多いこと。言い訳なんて聞きすぎて耳にタコができるくらいだ。でも、あんたらみたいに堂々とした無鉄砲さは初めて見たよ。",
            ["DialogueId"] = 12025702,
            ["GUID"] = "1E1AE6BC",
            ["NextDialogue"] = 12025703,
            ["SpeakNpcId"] = 210118,
            },
        [12025703] = {
            ["Content"] = "既然你们现在已经是虬先生的座上宾了……嘿嘿，能不能帮我在老大面前美言两句。就说他手下的张三，愿意鞍前马后为他老人家效劳！",
            ["ContentJP"] = "ま、もうキョウン様の「お得意さま」になったんだろ？へへ……頼むよ、俺のことをボスにちょっといい感じに言っておいてくれないか。「うちのヨウギは、命じられりゃ何でも喜んでやります！」ってさ！",
            ["DialogueId"] = 12025703,
            ["GUID"] = "1E1AE6E6",
            ["NextDialogue"] = 12025704,
            ["SpeakNpcId"] = 210118,
            },
        [12025704] = {
            ["Content"] = "你们说，我天天在这儿望着，连潮声岩穴的对侧都快望穿了，按照风水轮流转的道理，也该轮到些能捞油水的位置了。",
            ["ContentJP"] = "見てみろよ、俺なんて毎日毎日ここで見張ってて、<Default note=\"text:しおさい\">潮騒</>の洞窟の向こう側まで見通せるようになっちまってるんだ。「運は巡る」っていうだろ？ そろそろ俺にも、ちょっとはおいしい仕事が回ってきてもいい頃だって思うんだよ。",
            ["DialogueId"] = 12025704,
            ["GUID"] = "1E1AE710",
            ["NextDialogue"] = 12025705,
            ["SpeakNpcId"] = 210118,
            },
        [12025705] = {
            ["Content"] = "总不能苦活都给我一个人干了吧，是不是这个理？",
            ["ContentJP"] = "いつまでもこんな仕事ばかり押しつけられてんじゃ、たまったもんじゃないだろ？なぁ、そう思わないか？",
            ["DialogueId"] = 12025705,
            ["GUID"] = "1E1AE73A",
            ["SpeakNpcId"] = 210118,
            },
        [12025801] = {
            ["Content"] = "小友，你来了，坐。",
            ["ContentJP"] = "友よ、来たか。座りなさい。",
            ["DialogueId"] = 12025801,
            ["GUID"] = "1E1AF6FA",
            ["NextDialogue"] = 12025802,
            ["SpeakNpcId"] = 210119,
            },
        [12025802] = {
            ["Content"] = "百年的陈皮，刚沏好的，润润嗓子再来与我分享旅途的见闻吧。",
            ["ContentJP"] = "百年物の陳皮を使った茶だ。今しがた淹れたところでね。まずは喉を潤してから、旅の見聞でも聞かせてくれ。",
            ["DialogueId"] = 12025802,
            ["GUID"] = "1E1AF724",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025803] = {
            ["Content"] = "你为什么收藏这么多古董？",
            ["ContentJP"] = "どうしてこんなにたくさんの骨董を集めているの{性别:か|}？",
            ["DialogueId"] = 12025803,
            ["GUID"] = "1E1AF74E",
            ["NextDialogue"] = 12025804,
            },
        [12025804] = {
            ["Content"] = "物欲深重，想要自然就要得到，这是所有活物最真实的本能。",
            ["ContentJP"] = "人はどうしても欲に駆られる生き物だ。手に入れたいものがあれば、自然と手を伸ばしてしまう、それが人というものだろう。",
            ["DialogueId"] = 12025804,
            ["GUID"] = "1E1AF778",
            ["NextDialogue"] = 12025805,
            ["SpeakNpcId"] = 210119,
            },
        [12025805] = {
            ["Content"] = "更何况，古董并非仅是眼前的死物，它们都曾经在他人的故事中活过，说是牵连着千百个春秋，也不为过。",
            ["ContentJP"] = "それに、骨董品はただの物じゃない。どれもかつては誰かの物語の中で生きてきた代物だ。千年もの歴史の息吹といっても過言ではない。",
            ["DialogueId"] = 12025805,
            ["GUID"] = "1E1AF7A2",
            ["NextDialogue"] = 12025806,
            ["SpeakNpcId"] = 210119,
            },
        [12025806] = {
            ["Content"] = "听着玄之又玄，怪难懂的。",
            ["ContentJP"] = "あんまり理解できないかな。",
            ["DialogueId"] = 12025806,
            ["GUID"] = "1E1AF7CC",
            ["NextDialogue"] = 12025807,
            ["SpeakNpcId"] = 100001,
            },
        [12025807] = {
            ["Content"] = "这柄短剑，抵御过外敌，刺杀过君主，最后是殉了主。这碎茶盏呢，迎接了游子，送别了挚爱，最后是在赌书时被打翻在地。",
            ["ContentJP"] = "この短剣は、敵を撃退し、王を殺し、最終的にはその主と共に葬られた。この割れた茶碗は、旅人を迎え、愛する者を見送り、最後は賭け事の最中にひっくり返された。",
            ["DialogueId"] = 12025807,
            ["GUID"] = "1E1AF7F6",
            ["NextDialogue"] = 12025808,
            ["SpeakNpcId"] = 210119,
            },
        [12025808] = {
            ["Content"] = "当我触碰到这些古物时，好像此间并非只有你我二人，而是有七八幕景，十二三人，几百年事。这就是为什么我要收集它们，绝不收手。",
            ["ContentJP"] = "わたしが古物に触れる時、そこにいるのはあなただけじゃない。七八幕の情景、十数人の人生、数百年の時間が同時に息づくのだ。だから私は集め続ける。決して手を止めない。",
            ["DialogueId"] = 12025808,
            ["GUID"] = "1E1AF820",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025809] = {
            ["Content"] = "听说你很贪得无厌。",
            ["ContentJP"] = "あなた、すごく欲深いって聞いたけど？",
            ["DialogueId"] = 12025809,
            ["GUID"] = "1E1AF84A",
            ["NextDialogue"] = 12025810,
            },
        [12025810] = {
            ["Content"] = "贪得无厌？我喜欢这个评价。",
            ["ContentJP"] = "ほぅ？そりゃあいい評価だ。",
            ["DialogueId"] = 12025810,
            ["GUID"] = "1E1AF874",
            ["NextDialogue"] = 12025811,
            ["SpeakNpcId"] = 210119,
            },
        [12025811] = {
            ["Content"] = "我若不贪，便是暴殄天物，无数珍宝与秘密将被埋葬于过去，永世无人知晓。",
            ["ContentJP"] = "私が欲を捨てれば、無数の宝や秘められた真実が過去に埋もれ、永遠に誰の目にも触れぬまま消えゆくだけだ。それを見過ごすなど、私には到底できんな。",
            ["DialogueId"] = 12025811,
            ["GUID"] = "1E1AF89E",
            ["NextDialogue"] = 12025812,
            ["SpeakNpcId"] = 210119,
            },
        [12025812] = {
            ["Content"] = "人若不贪，便是有违这世间最朴素的道理：物欲，才是让人前行的动力，让万物演进的根本。",
            ["ContentJP"] = "無欲など、人の摂理に反してる。物への欲望は人を前進させる原動力であり、万物の進化の源とも言える。",
            ["DialogueId"] = 12025812,
            ["GUID"] = "1E1AF8C8",
            ["NextDialogue"] = 12025813,
            ["SpeakNpcId"] = 210119,
            },
        [12025813] = {
            ["Content"] = "可并不是所有人都这么想。",
            ["ContentJP"] = "でも、考え方は人それぞれだよ。",
            ["DialogueId"] = 12025813,
            ["GUID"] = "1E1AF8F2",
            ["NextDialogue"] = 12025814,
            ["SpeakNpcId"] = 100001,
            },
        [12025814] = {
            ["Content"] = "无所谓，你大可以说这是厚颜无耻的诡辩，但我更喜欢将它描述为，顺应自我，随心所欲。",
            ["ContentJP"] = "そんなことはどうでもいい。それを厚かましい弁解だと思うのは君の勝手だ。私は自分のエゴに従い、心のままに生きることを選んだ、それだけだ。",
            ["DialogueId"] = 12025814,
            ["GUID"] = "1E1AF91C",
            ["NextDialogue"] = 12025815,
            ["SpeakNpcId"] = 210119,
            },
        [12025815] = {
            ["Content"] = "大部分人想成为虬先生，但是却不会做虬先生，不敢做虬先生。最终连自己也做不成，只会躲在道理规矩背后谩骂我，可怜呐。",
            ["ContentJP"] = "大多数の者は「キョウン」を羨み、それでいて「キョウン」になる勇気がない。結局、彼らは自我を失い、ただ道理や規則の後ろに隠れて私を非難するしかできないのさ。まったく哀れなものだ。",
            ["DialogueId"] = 12025815,
            ["GUID"] = "1E1AF946",
            ["NextDialogue"] = 12025802,
            ["SpeakNpcId"] = 210119,
            },
        [12025816] = {
            ["Content"] = "公尚师傅是谁？",
            ["ContentJP"] = "コウショウ師匠は誰？",
            ["DialogueId"] = 12025816,
            ["GUID"] = "1E1AF970",
            ["NextDialogue"] = 12025817,
            },
        [12025817] = {
            ["Content"] = "我资助的一位机枢派奇人。",
            ["ContentJP"] = "私が支援している<Default note=\"text:きすうは\">機枢派</>の奇才だ。",
            ["DialogueId"] = 12025817,
            ["GUID"] = "1E1AF99A",
            ["NextDialogue"] = 12025818,
            ["SpeakNpcId"] = 210119,
            },
        [12025818] = {
            ["Content"] = "俗语说“人无癖不可交”。他便是我所见之人中癖好最为深重，行事最为乖张的一位了。",
            ["ContentJP"] = "「人に癖なければ交わるに値せず」というだろう。彼は私の見た中で最も変な癖を持ち、最も奇矯な行動をする人物だ。",
            ["DialogueId"] = 12025818,
            ["GUID"] = "1E1AF9C4",
            ["NextDialogue"] = 12025819,
            ["SpeakNpcId"] = 210119,
            },
        [12025819] = {
            ["Content"] = "人不怕性情怪异，怕的是平庸。他那打造机枢的手艺，当世也没几位比得上的。要不是他看不上天梁司的做派，也不会流落民间受我资助。",
            ["ContentJP"] = "癖が強いことなど恐れる必要はない。恐れるべきは凡庸さだ。彼の<Default note=\"text:きすう\">機枢</>造りの腕前は、この時代に並ぶ者がほとんどいないほどだよ。天梁司のやり方が気に入らないからこそ、民間に流れ、私の庇護を受けているわけだ。",
            ["DialogueId"] = 12025819,
            ["GUID"] = "1E1AF9EE",
            ["NextDialogue"] = 12025820,
            ["SpeakNpcId"] = 210119,
            },
        [12025820] = {
            ["Content"] = "这等性情的奇人，就算当着面骂我，我也只会一笑了之。",
            ["ContentJP"] = "ああいう奇人は、面と向かって私を罵ったとしても……私はただ笑って流すだけだよ。",
            ["DialogueId"] = 12025820,
            ["GUID"] = "1E1AFA18",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025821] = {
            ["Content"] = "你和止流掌柜是合作关系吗？",
            ["ContentJP"] = "あなたとシリュウさんは「協力関係」なの{性别:か|}？",
            ["DialogueId"] = 12025821,
            ["GUID"] = "1E1AFA42",
            ["NextDialogue"] = 12025822,
            },
        [12025822] = {
            ["Content"] = "你如果这样定义各取所需，那便是。",
            ["ContentJP"] = "もし「互いに求める物を交換する関係」を、そう呼ぶのなら……その通りだ。",
            ["DialogueId"] = 12025822,
            ["GUID"] = "1E1AFA6C",
            ["NextDialogue"] = 12025823,
            ["SpeakNpcId"] = 210119,
            },
        [12025823] = {
            ["Content"] = "那要是有一天她不再能提供你需要的东西，你会背叛她吗？",
            ["ContentJP"] = "じゃあ、もし彼女が必要な物を与えられなくなったら……裏切るの{性别:か|}？",
            ["DialogueId"] = 12025823,
            ["GUID"] = "1E1AFA96",
            ["NextDialogue"] = 12025824,
            ["SpeakNpcId"] = 100001,
            },
        [12025824] = {
            ["Content"] = "哈哈，小友这个问题有些天真了！世上无恒久之友，也无恒久之敌。人与人之间的立场流动不定，又何来背不背叛一说呢？",
            ["ContentJP"] = "ははは、友よ、それは少し幼い質問だ！この世には「永遠の味方」も「永遠の敵」もいない。人の立場は常に移ろう。「裏切り」という概念さえ、曖昧なものだよ。",
            ["DialogueId"] = 12025824,
            ["GUID"] = "1E1AFAC0",
            ["NextDialogue"] = 12025825,
            ["SpeakNpcId"] = 210119,
            },
        [12025825] = {
            ["Content"] = "不过有一件事你大可放心。你们止流掌柜是个聪明人，她会用利益将别人紧紧和她捆绑在一条战船上。你说的那一天，大抵是不会发生的。",
            ["ContentJP"] = "だがひとつ言えるのは——シリュウさんは賢い。彼女は利益で人を結びつけ、同じ船に乗せる術を知っている。だから君の言うような状況は、まず訪れない。",
            ["DialogueId"] = 12025825,
            ["GUID"] = "1E1AFAEA",
            ["NextDialogue"] = 12025828,
            ["SpeakNpcId"] = 210119,
            },
        [12025826] = {
            ["Content"] = "我先走了。",
            ["ContentJP"] = "お先に失礼します。",
            ["DialogueId"] = 12025826,
            ["GUID"] = "1E1AFB14",
            ["NextDialogue"] = 12025827,
            },
        [12025827] = {
            ["Content"] = "慢走，不送。",
            ["ContentJP"] = "もう帰るのか、ではごくろうさん。",
            ["DialogueId"] = 12025827,
            ["GUID"] = "1E1AFB3E",
            ["SpeakNpcId"] = 210119,
            },
        [12025828] = {
            ["DialogueId"] = 12025828,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12025827,
            ["GUID"] = "1E1AFB3F",
            ["NextOptions"] = {
                [1] = 12025803,
                [2] = 12025809,
                [3] = 12025816,
                [4] = 12025821,
                [5] = 51155701,
                [6] = 12025826,
                },
            },
        [12025901] = {
            ["Content"] = "恩人……谢……谢你…………",
            ["ContentJP"] = "……恩人……あ、ありがとう……ございます…………",
            ["DialogueId"] = 12025901,
            ["GUID"] = "1E1B0762",
            ["NextDialogue"] = 12025902,
            ["SpeakNpcId"] = 210120,
            },
        [12025902] = {
            ["Content"] = "（你眼前的姑娘面色苍白，额头上冒出豆大的汗珠，却还在勉力向你道谢。被狴犴惩戒后，她明显需要休息。）",
            ["ContentJP"] = "（娘は顔色が真っ青で、額には大粒の汗がにじみ、立っているのもやっとなくらいだ。狴犴の罰を受けた後遺症だろう……今は安静が必要なのが一目で分かる。）",
            ["DialogueId"] = 12025902,
            ["GUID"] = "1E1B078C",
            ["NextDialogue"] = 12025903,
            },
        [12025903] = {
            ["Content"] = "您放心，您放心，大家都是朋友！我一定把她照顾得妥妥帖帖，一根毫毛都不会伤到！",
            ["ContentJP"] = "ご安心を、ご安心を！ みんな仲間ですって！彼女のことは私がしっかり面倒みますよ、毛一本だって傷つけたりしませんから！",
            ["DialogueId"] = 12025903,
            ["GUID"] = "1E1B07B6",
            ["NextDialogue"] = 12025904,
            ["SpeakNpcName"] = "UI_Npc_Name_Badshangren",
            },
        [12025904] = {
            ["Content"] = "哎呀，我的{性别：姑爷爷|姑奶奶}，算我求求您，赶紧去见虬先生吧，别让他老人家久等。您们在这里，她也没法安心休息呀。",
            ["ContentJP"] = "ああもう、どうかお願いです、早くキョウン様のところへ行ってくださいな。あの御方をお待たせするわけにはいきませんし、あんたらがここにいたんじゃ、彼女も落ち着いて休めやしませんよ。",
            ["DialogueId"] = 12025904,
            ["GUID"] = "1E1B07E0",
            ["SpeakNpcName"] = "UI_Npc_Name_Badshangren",
            },
        [12026001] = {
            ["Content"] = "这位荣誉学徒，有什么想向我请教的？",
            ["ContentJP"] = "おう、名誉見習い。何か私に聞きたいことでもあるのか？",
            ["DialogueId"] = 12026001,
            ["GUID"] = "1E1B17CA",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026002] = {
            ["Content"] = "可以再说明一下什么是尘漠吗？",
            ["ContentJP"] = "塵砂について、もう一度説明してもらえますか？",
            ["DialogueId"] = 12026002,
            ["GUID"] = "1E1B17F4",
            ["NextDialogue"] = 12026003,
            },
        [12026003] = {
            ["Content"] = "唉，遥想当初，过目不忘可是入门我机枢派的最基础。资质愚钝者，早在娃娃之时就被刷下去了。",
            ["ContentJP"] = "はぁ……昔ならな、ものを一度見りゃ忘れないのは<Default note=\"text:きすうは\">機枢派</>入門の最低条件だった。物覚えの悪い子は、幼い頃にさっさと落とされていたものだ。",
            ["DialogueId"] = 12026003,
            ["GUID"] = "1E1B181E",
            ["NextDialogue"] = 12026004,
            ["SpeakNpcId"] = 210121,
            },
        [12026004] = {
            ["Content"] = "罢了罢了。做人不能强求，你有这份求知欲，也算是很珍贵了。我就再给你说明一次吧。",
            ["ContentJP"] = "まぁいい。人に無理を強いても仕方がない。知りたいという気持ちがあるだけ、お前はまだマシだ。では、もう一度だけ説明してやろう。",
            ["DialogueId"] = 12026004,
            ["GUID"] = "1E1B1848",
            ["NextDialogue"] = 12026005,
            ["SpeakNpcId"] = 210121,
            },
        [12026005] = {
            ["Content"] = "这空气中弥漫着一种名为太虚，看不见摸不着的物质。这时你就要问了，既然是看不见摸不着，那怎么确定它存在呢？",
            ["ContentJP"] = "空気中には「<Default note=\"text:たいきょ\">太虚</>」と呼ばれる、目にも触れにも引っかからない物質が漂っている。そこでお前はこう聞くんだろう——そんな見えないもの、どうやって存在を確かめるんだ、と。",
            ["DialogueId"] = 12026005,
            ["GUID"] = "1E1B1872",
            ["NextDialogue"] = 12026006,
            ["SpeakNpcId"] = 210121,
            },
        [12026006] = {
            ["Content"] = "我们研究者自有各种手段去侧面观察它。这尘漠，便是太虚存在的最好佐证——",
            ["ContentJP"] = "研究者にはな、いくらでも側面から観測する手段がある。<Default note=\"text:じんじゃ\">塵砂</>こそが太虚の存在を示す最良の証拠だ。",
            ["DialogueId"] = 12026006,
            ["GUID"] = "1E1B189C",
            ["NextDialogue"] = 12026007,
            ["SpeakNpcId"] = 210121,
            },
        [12026007] = {
            ["Content"] = "空气中的太虚受烛阴之灾影响，其性质发生转变，固化成蒙于物体表面的粉末。这对一般生命有害的粉末便是尘漠。这样一说，你可懂了？",
            ["ContentJP"] = "太虚は<Default note=\"text:しょくいん\">燭陰</>の禍に影響を受け、その性質が変質し、こうして物体表面に粉末として固まる。そして通常の生命には有害なその粉末こそ「<Default note=\"text:じんじゃ\">塵砂</>」だ。——これで分かったな？",
            ["DialogueId"] = 12026007,
            ["GUID"] = "1E1B18C6",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026008] = {
            ["Content"] = "可以再说明一下牵机方枢的用法吗？",
            ["ContentJP"] = "機巧制御盤の使い方をもう一回教えて？",
            ["DialogueId"] = 12026008,
            ["GUID"] = "1E1B18F0",
            ["NextDialogue"] = 12026009,
            },
        [12026009] = {
            ["Content"] = "嗯？我手写的数百页使用说明书与牵机方枢一并存放于秦虬那里，他没有交给你们吗？",
            ["ContentJP"] = "ん？ 数百ページの説明書を、<Default note=\"text:きこうせいぎょばん\">機巧制御盤</>と一緒にキョウンに預けてあるんだが……渡されなかったのか？",
            ["DialogueId"] = 12026009,
            ["GUID"] = "1E1B191A",
            ["NextDialogue"] = 12026010,
            ["SpeakNpcId"] = 210121,
            },
        [12026010] = {
            ["Content"] = "没有。他只让我来请教你。",
            ["ContentJP"] = "渡されてません。あなたに直接聞きに行けって言われました。",
            ["DialogueId"] = 12026010,
            ["GUID"] = "1E1B1944",
            ["NextDialogue"] = 12026011,
            ["SpeakNpcId"] = 100001,
            },
        [12026011] = {
            ["Content"] = "……那老东西，我就知道。他一定觉得你会字多不看，没必要把这洋洋洒洒数十万字的说明书交给你。我机枢派的荣誉学徒，能是这种品性的人吗？",
            ["ContentJP"] = "……あの老いぼれが。どうせ「あいつは字が多いと読まん、渡すだけ無駄だ」なんて思ったんだろう。我ら<Default note=\"text:きすうは\">機枢派</>の名誉見習いがそんな怠け者であってたまるか。",
            ["DialogueId"] = 12026011,
            ["GUID"] = "1E1B196E",
            ["NextDialogue"] = 12026012,
            ["SpeakNpcId"] = 210121,
            },
        [12026012] = {
            ["Content"] = "算了，我就简单解说一下吧。很简单，按下这个按钮，对着尘漠，吸。完事了。",
            ["ContentJP"] = "いいだろう、簡単に説明してやる。やることは単純だ。このボタンを押す、<Default note=\"text:じんじゃ\">塵砂</>に向ける、吸い込む。以上だ。",
            ["DialogueId"] = 12026012,
            ["GUID"] = "1E1B1998",
            ["NextDialogue"] = 12026013,
            ["SpeakNpcId"] = 210121,
            },
        [12026013] = {
            ["Content"] = "就这样？",
            ["ContentJP"] = "……これだけ？",
            ["DialogueId"] = 12026013,
            ["GUID"] = "1E1B19C2",
            ["NextDialogue"] = 12026014,
            ["SpeakNpcId"] = 100001,
            },
        [12026014] = {
            ["Content"] = "就这样。你莫非还要我从原理开始解说不成？",
            ["ContentJP"] = "これだけだ。まさか原理の説明から始めろと言うまいな？",
            ["DialogueId"] = 12026014,
            ["GUID"] = "1E1B19EC",
            ["NextDialogue"] = 12026015,
            ["SpeakNpcId"] = 210121,
            },
        [12026015] = {
            ["Content"] = "没有没有，这样就很好了。谢谢师父！",
            ["ContentJP"] = "……いや、これで十分です。ありがとうございます、師匠！",
            ["DialogueId"] = 12026015,
            ["GUID"] = "1E1B1A16",
            ["NextDialogue"] = 12026025,
            },
        [12026016] = {
            ["Content"] = "机枢派为什么没落了？",
            ["ContentJP"] = "どうして機枢派は衰退したの{性别:か|}？",
            ["DialogueId"] = 12026016,
            ["GUID"] = "1E1B1A40",
            ["NextDialogue"] = 12026017,
            },
        [12026017] = {
            ["Content"] = "我机枢派的人，首先要学会用辨证的思维看待事物——何为没落？",
            ["ContentJP"] = "<Default note=\"text:きすうは\">機枢派</>の者ならまず、物事を違う角度から見ることを学べ。さて、何をもって「衰退」と呼ぶ？",
            ["DialogueId"] = 12026017,
            ["GUID"] = "1E1B1A6A",
            ["NextDialogue"] = 12026018,
            ["SpeakNpcId"] = 210121,
            },
        [12026018] = {
            ["Content"] = "机枢派的造物从南向北遍布整个华胥，哪个码头见不到搬运货物的木走马？天梁司还高居华胥三大司之一，这能叫没落吗？",
            ["ContentJP"] = "<Default note=\"text:きすうは\">機枢派</>の造物は南から北まで)<Default note=\"text:カショ\">華胥</>全土に広がっている。どこの港にも「<Default note=\"text:きんま\">木走馬</>」があるだろう？<Default note=\"text:てんりょうし\">天梁司</>だっていまだに華胥三大司のひとつだ。これを衰退と呼ぶかね？",
            ["DialogueId"] = 12026018,
            ["GUID"] = "1E1B1A94",
            ["NextDialogue"] = 12026019,
            ["SpeakNpcId"] = 210121,
            },
        [12026019] = {
            ["Content"] = "那个……机枢派没落了招不到学生，好像是你和我说的？",
            ["ContentJP"] = "えっと……「機枢派が衰退して学生が来ない」って、師匠自身が言ってましたよね？",
            ["DialogueId"] = 12026019,
            ["GUID"] = "1E1B1ABE",
            ["NextDialogue"] = 12026020,
            ["SpeakNpcId"] = 100001,
            },
        [12026020] = {
            ["Content"] = "聪明，这就是辨证思维的另一面了。",
            ["ContentJP"] = "ふむ。察しがいいじゃないか。それこそが「物事のもう一つの側面」だ。",
            ["DialogueId"] = 12026020,
            ["GUID"] = "1E1B1AE8",
            ["NextDialogue"] = 12026021,
            ["SpeakNpcId"] = 210121,
            },
        [12026021] = {
            ["Content"] = "世人失去了求知欲，无人愿意考入机枢派，天梁司那些老东西只知道闭门造车，不再去穷事物之极理——这是没落。",
            ["ContentJP"] = "世の中から求知の心が失われ、誰も<Default note=\"text:きすうは\">機枢派</>を目指さなくなった。<Default note=\"text:てんりょうし\">天梁司</>の老いぼれどもは閉じこもって、学問の極みを追わなくなった。——これは「衰退」だ。",
            ["DialogueId"] = 12026021,
            ["GUID"] = "1E1B1B12",
            ["NextDialogue"] = 12026022,
            ["SpeakNpcId"] = 210121,
            },
        [12026022] = {
            ["Content"] = "现在我回答你的问题，机枢派为什么没落？是悬衡派那些家伙干的，因为他们害怕知识带来的力量会超出他们的掌控，所以让机枢派没落了。就这么简单。",
            ["ContentJP"] = "さて、どうして衰退したか？答えは簡単だ。<Default note=\"text:けんこうは\">懸衡派</>の連中のせいだよ。知識が力になるのを恐れ、機枢派の隆盛が手に負えなくなることを危惧した。だから、機枢派は衰退させられた——それだけのことだ。",
            ["DialogueId"] = 12026022,
            ["GUID"] = "1E1B1B3C",
            ["NextDialogue"] = 12026025,
            ["SpeakNpcId"] = 210121,
            },
        [12026023] = {
            ["Content"] = "还有好多问题，我想想。",
            ["ContentJP"] = "まだ聞きたいことがいっぱいあるから、ちょっと考えさせて。",
            ["DialogueId"] = 12026023,
            ["GUID"] = "1E1B1B66",
            ["NextDialogue"] = 12026024,
            },
        [12026024] = {
            ["Content"] = "打破砂锅问到底，是个好苗子。好了，我要忙去了，你也不要疏忽了日常功课啊。",
            ["ContentJP"] = "よし、何でもかんでも質問する姿勢は悪くない。だが私は忙しい。お前も日々の修行を怠るなよ。",
            ["DialogueId"] = 12026024,
            ["GUID"] = "1E1B1B90",
            ["SpeakNpcId"] = 210121,
            },
        [12026025] = {
            ["DialogueId"] = 12026025,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026024,
            ["GUID"] = "1E1B1B91",
            ["NextOptions"] = {
                [1] = 12026002,
                [2] = 12026008,
                [3] = 12026016,
                [4] = 12026023,
                },
            },
        [12026101] = {
            ["Content"] = "瞧瞧是谁来了——原来是帮百年春化解危机的大英雄{nickname}！",
            ["ContentJP"] = "あらあら、誰かと思ったら——百年春の危機を救った大英雄、{nickname}じゃないの！",
            ["DialogueId"] = 12026101,
            ["GUID"] = "1E1B2832",
            ["NextDialogue"] = 12026102,
            ["SpeakNpcId"] = 210122,
            },
        [12026102] = {
            ["Content"] = "哪里哪里。我只是做了一些微小的工作，主要还是靠止流掌柜和大家的力量。",
            ["ContentJP"] = "大英雄なんて、とんでもないよ。{性别:僕|私}はほんの少し手を貸しただけで、功績の大半はシリュウさんや皆のおかげだよ。",
            ["DialogueId"] = 12026102,
            ["GUID"] = "1E1B285C",
            ["NextDialogue"] = 12026103,
            ["SpeakNpcId"] = 100001,
            },
        [12026103] = {
            ["Content"] = "倒是你经历了这些之后，现在还好吗？",
            ["ContentJP"] = "それより、ギョクセイこそ……あんなことがあって、もう大丈夫なの{性别:か|}？",
            ["DialogueId"] = 12026103,
            ["GUID"] = "1E1B2886",
            ["NextDialogue"] = 12026104,
            ["SpeakNpcId"] = 100001,
            },
        [12026104] = {
            ["Content"] = "呵呵，说出来不怕你笑话……现在比起后怕，我心里反而激荡着一种能够保卫家园的兴奋感，甚至感觉身体里充满了力量。",
            ["ContentJP"] = "ふふ、笑わないで聞いてほしいんだけど……怖かったはずなのにね、今はそれ以上に「家を守れた」っていう高揚感があって。胸の奥が熱くなるような、不思議な力が湧いてくるの。",
            ["DialogueId"] = 12026104,
            ["GUID"] = "1E1B28B0",
            ["NextDialogue"] = 12026105,
            ["SpeakNpcId"] = 210122,
            },
        [12026105] = {
            ["Content"] = "我甚至动了学几招防身手段的念头，这样以后去别的危险地区行商，也不用光等着护卫来保护自己了。",
            ["ContentJP"] = "それでつい、防身術でも習おうかな……なんて考えちゃって。危険な土地を商いで回る時に、護衛に守ってもらうだけじゃなくて、自分でも身を守れたら素敵かなって。",
            ["DialogueId"] = 12026105,
            ["GUID"] = "1E1B28DA",
            ["NextDialogue"] = 12026106,
            ["SpeakNpcId"] = 210122,
            },
        [12026106] = {
            ["Content"] = "不过这种念头终归是不符合大风九章的吧……",
            ["ContentJP"] = "……でも、そういう考え方って、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の教えには反するのかしらね……",
            ["DialogueId"] = 12026106,
            ["GUID"] = "1E1B2904",
            ["SpeakNpcId"] = 210122,
            },
        [12026201] = {
            ["Content"] = "怎么了，{nickname}？有什么事吗？",
            ["ContentJP"] = "どうしたの、{nickname}？ 何か用かしら？",
            ["DialogueId"] = 12026201,
            ["GUID"] = "1E1B389A",
            ["NextDialogue"] = 12026202,
            ["SpeakNpcId"] = 210123,
            },
        [12026202] = {
            ["Content"] = "（止流的举止一如往常，但你总觉得她有些不易察觉的疲惫……是错觉吗？）",
            ["ContentJP"] = "（シリュウの所作はいつも通り落ち着いている……けれど、その奥にごく僅かな疲れが滲んでいる気がする。気のせいだろうか……？）",
            ["DialogueId"] = 12026202,
            ["GUID"] = "1E1B38C4",
            ["NextDialogue"] = 12026213,
            },
        [12026203] = {
            ["Content"] = "止流掌柜，你接下来有什么安排？",
            ["ContentJP"] = "シリュウさん、このあとどうする予定な{性别:んだ|の}？",
            ["DialogueId"] = 12026203,
            ["GUID"] = "1E1B38EE",
            ["NextDialogue"] = 12026204,
            },
        [12026204] = {
            ["Content"] = "有了你采来的这些烛阴鳞，封印烛阴的准备也算是完毕了。接下来我便要先筹备此事，可能暂时无法分神接待你们了，先说一句抱歉。",
            ["ContentJP"] = "あなたが集めてきてくれた<Default note=\"text:しょくいん\">燭陰</>の鱗で、封印の準備はひとまず整ったわ。これからはそちらの段取りに集中しなくてはいけないから、しばらくはゆっくりあなたたちをもてなす余裕がなくなってしまいそう。先に謝っておくわね。",
            ["DialogueId"] = 12026204,
            ["GUID"] = "1E1B3918",
            ["NextDialogue"] = 12026205,
            ["SpeakNpcId"] = 210123,
            },
        [12026205] = {
            ["Content"] = "真的不需要我帮忙吗？",
            ["ContentJP"] = "本当に、手伝わなくて大丈夫？",
            ["DialogueId"] = 12026205,
            ["GUID"] = "1E1B3942",
            ["NextDialogue"] = 12026206,
            ["SpeakNpcId"] = 100001,
            },
        [12026206] = {
            ["Content"] = "呵呵，你倒是有心了。也不能总让你一个人忙前忙后。若出现了难以搞定的事情，我会再来委托你们的。",
            ["ContentJP"] = "ふふ、気にかけてくれるなんて嬉しいわ。でも、いつもあなた一人にばかり頑張らせるわけにはいかないもの。もし私たちだけでは対処できない事態が起きたら、そのときはまたお願いするわ。",
            ["DialogueId"] = 12026206,
            ["GUID"] = "1E1B396C",
            ["NextDialogue"] = 12026213,
            ["SpeakNpcId"] = 210123,
            },
        [12026207] = {
            ["Content"] = "刚刚百年春的危机真是凶险。",
            ["ContentJP"] = "さっきの百年春の危機、本当にすごかった{性别:なぁ|ね}。",
            ["DialogueId"] = 12026207,
            ["GUID"] = "1E1B3996",
            ["NextDialogue"] = 12026208,
            },
        [12026208] = {
            ["Content"] = "嗯。这场危机化解也有你的一份功劳。多谢了，{nickname}。",
            ["ContentJP"] = "ええ。今回の危機が収まったのも、あなたの働きのおかげよ。助かったわ、{nickname}。",
            ["DialogueId"] = 12026208,
            ["GUID"] = "1E1B39C0",
            ["NextDialogue"] = 12026209,
            ["SpeakNpcId"] = 210123,
            },
        [12026209] = {
            ["Content"] = "我没做什么，主要还是靠你组织起来了大家，你当时的应对好迅速。",
            ["ContentJP"] = "{性别:僕|私}は大したことしてないよ。シリュウさんが皆をまとめてくれたからこそ、あんな早さで対処できたんだ。",
            ["DialogueId"] = 12026209,
            ["GUID"] = "1E1B39EA",
            ["NextDialogue"] = 12026210,
            ["SpeakNpcId"] = 100001,
            },
        [12026210] = {
            ["Content"] = "呵呵，做事若是畏手畏脚，瞻前顾后，又怎能负起众人之望呢？",
            ["ContentJP"] = "ふふ……物事は、あれこれ迷っていたら務まらないの。恐れず前に進むことで、ようやく「皆に託される存在」になれるのよ。",
            ["DialogueId"] = 12026210,
            ["GUID"] = "1E1B3A14",
            ["NextDialogue"] = 12026213,
            ["SpeakNpcId"] = 210123,
            },
        [12026211] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12026211,
            ["GUID"] = "1E1B3A3E",
            ["NextDialogue"] = 12026212,
            },
        [12026212] = {
            ["Content"] = "我要先去筹备封印烛阴的相关事宜了。你现在得了空闲，去逛逛吧。有什么开销记在我账上就行，不用对我客气。",
            ["ContentJP"] = "さて、私は封印の準備を進めに行くわね。あなたは今、少し時間が取れるんでしょう？せっかくだから街を見て回っていらっしゃい。そこでの出費は全部、私の勘定につけていいわ。遠慮なんていらないのよ。",
            ["DialogueId"] = 12026212,
            ["GUID"] = "1E1B3A68",
            ["SpeakNpcId"] = 210123,
            },
        [12026213] = {
            ["DialogueId"] = 12026213,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026212,
            ["GUID"] = "1E1B3A69",
            ["NextOptions"] = {
                [1] = 12026203,
                [2] = 12026207,
                [3] = 12026211,
                },
            },
        [12026301] = {
            ["Content"] = "恩人，你来看望我了……",
            ["ContentJP"] = "恩人さま……わざわざ様子を見に来てくださったんですね……",
            ["DialogueId"] = 12026301,
            ["GUID"] = "1E1B4902",
            ["NextDialogue"] = 12026302,
            ["SpeakNpcId"] = 210124,
            },
        [12026302] = {
            ["Content"] = "你现在好点了吗？",
            ["ContentJP"] = "身体の具合は、少しは良くなった？",
            ["DialogueId"] = 12026302,
            ["GUID"] = "1E1B492C",
            ["NextDialogue"] = 12026303,
            ["SpeakNpcId"] = 100001,
            },
        [12026303] = {
            ["Content"] = "多亏了您和扶疏大人为我采回来的药，现在我的伤势已经稳定，再过一两天就能下床走动了。",
            ["ContentJP"] = "ええ……あなたとフーシュさまが集めてくださった薬のおかげで、傷も落ち着いてきました。あと一、二日すれば、歩けるくらいには回復できそうです。",
            ["DialogueId"] = 12026303,
            ["GUID"] = "1E1B4956",
            ["NextDialogue"] = 12026304,
            ["SpeakNpcId"] = 210124,
            },
        [12026304] = {
            ["Content"] = "这一遭下来，不知道受了您的多少恩惠……除了言谢之外，我、我想不到别的方式可以报答你。以后有需要我做的，尽管开口，千万不用客气。",
            ["ContentJP"] = "今回のことで、どれだけあなたに助けられたか……もう、感謝してもしきれません。お礼の言葉以外、何を返せばいいのか分からなくて……これから先、私にできることがあれば、どうか遠慮なく言ってください。本当に……何でもお手伝いしますから。",
            ["DialogueId"] = 12026304,
            ["GUID"] = "1E1B4980",
            ["SpeakNpcId"] = 210124,
            },
        [12026401] = {
            ["Content"] = "如果你们在瀑布附近看到了受困的无由生，还请施以援手……多谢二位了。",
            ["ContentJP"] = "もし滝のそばで困っているムユウセイを見かけたら、どうか助けてやってくだされ……お二人とも、本当に感謝いたします。",
            ["DialogueId"] = 12026401,
            ["GUID"] = "1E1B596A",
            ["SpeakNpcId"] = 210125,
            },
        [12026501] = {
            ["Content"] = "多谢二位，失踪的无由生都被救回来了！真是功德一桩呐！",
            ["ContentJP"] = "ありがたい……！行方不明だったムユウセイは皆、無事に救い出されましたぞ！お二人はまさに大きな功徳を積まれましたな！",
            ["DialogueId"] = 12026501,
            ["GUID"] = "1E1B69D2",
            ["SpeakNpcId"] = 210126,
            },
        [12026601] = {
            ["Content"] = "{nickname}，你来了。",
            ["ContentJP"] = "{nickname}、来てくれたのですね。",
            ["DialogueId"] = 12026601,
            ["GUID"] = "1E1B7A3A",
            ["NextDialogue"] = 12026602,
            ["SpeakNpcId"] = 210127,
            },
        [12026602] = {
            ["Content"] = "我性喜清净，这枯荣阁中没什么可以用来招待你的，只有半壁医书，一壶茗茶……希望不会使你感到枯燥。",
            ["ContentJP"] = "私は静かな場所が好きで……この「<Default note=\"text:こえいかく\">枯栄閣</>」には、お客さまをもてなせるようなものはほとんどありません。あるのは壁一面の医書と、一壺の茶だけ……退屈に感じなければよいのですが。",
            ["DialogueId"] = 12026602,
            ["GUID"] = "1E1B7A64",
            ["NextDialogue"] = 12026603,
            ["SpeakNpcId"] = 210127,
            },
        [12026603] = {
            ["Content"] = "你可以随意走动，把这里当做自己家一般便好。",
            ["ContentJP"] = "ここでは好きにしてかまいません。自分の家だと思って、ゆっくりしていってください。",
            ["DialogueId"] = 12026603,
            ["GUID"] = "1E1B7A8E",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026604] = {
            ["Content"] = "除了治病救人，你在闲暇时间还会做些什么？",
            ["ContentJP"] = "診療や救護以外の時間は何をしている？",
            ["DialogueId"] = 12026604,
            ["GUID"] = "1E1B7AB8",
            ["NextDialogue"] = 12026605,
            },
        [12026605] = {
            ["Content"] = "照料病人往往已占据我大部分时间。若是偷得浮生半日闲……我许是会研究家姐留下的医书吧。",
            ["ContentJP"] = "病人の世話だけで、大抵の時間は過ぎていきます。もしわずかに自由な時間を得られたら……姉が残してくれた医書を読むことでしょうね。",
            ["DialogueId"] = 12026605,
            ["GUID"] = "1E1B7AE2",
            ["NextDialogue"] = 12026606,
            ["SpeakNpcId"] = 210127,
            },
        [12026606] = {
            ["Content"] = "那不还是治病救人吗？！",
            ["ContentJP"] = "それ、結局また治療の勉強じゃない？！",
            ["DialogueId"] = 12026606,
            ["GUID"] = "1E1B7B0C",
            ["NextDialogue"] = 12026607,
            ["SpeakNpcId"] = 100001,
            },
        [12026607] = {
            ["Content"] = "若是病人就在眼前，我往往心思急切，无法沉下心去研究药理关联。反倒是漫无目的翻开某页医书，细细研究其晦涩之语时，能体会到一种茅塞顿开的喜悦。",
            ["ContentJP"] = "患者が目の前にいると、どうしても気が急いてしまい、薬理を落ち着いて考える余裕がありません。むしろ、何の目的もなく医書を開き、難解な一節に向き合うと、ふっと霧が晴れるような喜びがあるのです。",
            ["DialogueId"] = 12026607,
            ["GUID"] = "1E1B7B36",
            ["NextDialogue"] = 12026608,
            ["SpeakNpcId"] = 210127,
            },
        [12026608] = {
            ["Content"] = "你就没有这之外的爱好了吗？",
            ["ContentJP"] = "他に趣味みたいなものは無いの{性别:か|}？",
            ["DialogueId"] = 12026608,
            ["GUID"] = "1E1B7B60",
            ["NextDialogue"] = 12026609,
            ["SpeakNpcId"] = 100001,
            },
        [12026609] = {
            ["Content"] = "待我想想……抚上一首琴曲，或是与云螭嬉戏，这都是我少时的乐趣。",
            ["ContentJP"] = "そうですね……琴を弾いたり、子供のころは雲龍と戯れたりするのが好きでした。",
            ["DialogueId"] = 12026609,
            ["GUID"] = "1E1B7B8A",
            ["NextDialogue"] = 12026610,
            ["SpeakNpcId"] = 210127,
            },
        [12026610] = {
            ["Content"] = "那下次弹首琴曲给我听吧。",
            ["ContentJP"] = "じゃあ今度、一曲聴かせてよ。",
            ["DialogueId"] = 12026610,
            ["GUID"] = "1E1B7BB4",
            ["NextDialogue"] = 12026611,
            ["SpeakNpcId"] = 100001,
            },
        [12026611] = {
            ["Content"] = "……是了，我怎么忘了呢。最大的乐趣还是与友人共处，无论赏曲或是谈天说地，都别有一份逸趣。",
            ["ContentJP"] = "……ああ、忘れていました。何よりの楽しみは、友と過ごすひとときですね。音を楽しむのも、おしゃべりするのも、誰かと共にあるからこそ味わえる妙味があります。",
            ["DialogueId"] = 12026611,
            ["GUID"] = "1E1B7BDE",
            ["NextDialogue"] = 12026612,
            ["SpeakNpcId"] = 210127,
            },
        [12026612] = {
            ["Content"] = "{nickname}，你随时可以来枯荣阁找我打发闲暇。我会很乐意你来访。",
            ["ContentJP"] = "{nickname}、いつでも<Default note=\"text:こえいかく\">枯栄閣</>に来てください。あなたが来てくれたら、私は嬉しいですよ。",
            ["DialogueId"] = 12026612,
            ["GUID"] = "1E1B7C08",
            ["NextDialogue"] = 12026613,
            ["SpeakNpcId"] = 210127,
            },
        [12026613] = {
            ["Content"] = "那就一言为定！",
            ["ContentJP"] = "それじゃ、約束だね！",
            ["DialogueId"] = 12026613,
            ["GUID"] = "1E1B7C32",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 100001,
            },
        [12026614] = {
            ["Content"] = "我最近有些不舒服。",
            ["ContentJP"] = "最近ちょっと体調が悪くて……",
            ["DialogueId"] = 12026614,
            ["GUID"] = "1E1B7C5C",
            ["NextDialogue"] = 12026615,
            },
        [12026615] = {
            ["Content"] = "怎么了？哪里痛，还是在烟津渡奔行时不慎受伤了？快把手递给我，我帮你细细查探一番。",
            ["ContentJP"] = "どうしたのです？どこが痛むのですか？それとも<Default note=\"text:えんしんと\">煙津渡</>を駆け回っているときに怪我でも……？手を見せてください、じっくり診ますから。",
            ["DialogueId"] = 12026615,
            ["GUID"] = "1E1B7C86",
            ["NextDialogue"] = 12026616,
            ["SpeakNpcId"] = 210127,
            },
        [12026616] = {
            ["Content"] = "噗嗤，扶疏，你好紧张。",
            ["ContentJP"] = "クスッ……フーシュ、そんなに慌てなくても。",
            ["DialogueId"] = 12026616,
            ["GUID"] = "1E1B7CB0",
            ["NextDialogue"] = 12026617,
            ["SpeakNpcId"] = 100001,
            },
        [12026617] = {
            ["Content"] = "没有那么严重，只是睡醒时常常感觉腰酸背痛而已。",
            ["ContentJP"] = "たいしたことじゃなくて、寝起きに腰と背中が少し痛むだけだよ。",
            ["DialogueId"] = 12026617,
            ["GUID"] = "1E1B7CDA",
            ["NextDialogue"] = 12026618,
            ["SpeakNpcId"] = 100001,
            },
        [12026618] = {
            ["Content"] = "健康乃大事，就算是小病小痛也不可随意对待。我这里有一套强身健体的五禽戏可以传授于你，助你活络筋骨。",
            ["ContentJP"] = "健康は一番大事です。たとえ小さな不調でも放置するのは良くありません。ここに<Default note=\"text:ごきんぎ\">五禽戯</>という養生法があるので、あなたにお教えします。筋や骨がしっかり伸び、体が軽くなるはずです。",
            ["DialogueId"] = 12026618,
            ["GUID"] = "1E1B7D04",
            ["NextDialogue"] = 12026619,
            ["SpeakNpcId"] = 210127,
            },
        [12026619] = {
            ["Content"] = "为了充分领略五禽的形意，这套拳法须在鸡犬鸣叫，夜色将褪未褪之时开始练习。待到旭阳将出，清风拂面，你必定能感受到锻炼带来的身心舒畅……",
            ["ContentJP"] = "この拳法は、鶏と犬が鳴き出し、夜が明けきる前の時間に始めるのが最も良いのです。朝日が差し込み、風が肌を撫でるころには、心身ともに爽快になりますよ——",
            ["DialogueId"] = 12026619,
            ["GUID"] = "1E1B7D2E",
            ["NextDialogue"] = 12026620,
            ["SpeakNpcId"] = 210127,
            },
        [12026620] = {
            ["Content"] = "不、不用了！",
            ["ContentJP"] = "い、いやいや！",
            ["DialogueId"] = 12026620,
            ["GUID"] = "1E1B7D58",
            ["NextDialogue"] = 12026621,
            ["SpeakNpcId"] = 100001,
            },
        [12026621] = {
            ["Content"] = "我又想了想，我很好，再好不过了，我从来没有这么健康过！所以你的好意我就心领了，千万不用实践。",
            ["ContentJP"] = "やっぱりなんともない！ すごく健康！ 人生で一番調子がいいくらい！だからそのありがたい教えは、気持ちだけ受け取るよ……！",
            ["DialogueId"] = 12026621,
            ["GUID"] = "1E1B7D82",
            ["NextDialogue"] = 12026622,
            ["SpeakNpcId"] = 100001,
            },
        [12026622] = {
            ["Content"] = "唉，你呀……",
            ["ContentJP"] = "まったく……あなたって本当に。",
            ["DialogueId"] = 12026622,
            ["GUID"] = "1E1B7DAC",
            ["NextDialogue"] = 12026623,
            ["SpeakNpcId"] = 210127,
            },
        [12026623] = {
            ["Content"] = "这次便让你逃过去了。但若再遇到身体不适的情况，千万不要硬撑，我会为你排忧解难。",
            ["ContentJP"] = "今回は見逃しますが、また体調を崩したら絶対に無理をしないこと。ちゃんと私を頼りなさい。",
            ["DialogueId"] = 12026623,
            ["GUID"] = "1E1B7DD6",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026624] = {
            ["Content"] = "你离开往隙之后好像有什么烦恼。",
            ["ContentJP"] = "裂け目を離れてから、何か悩んでいるようだけど……",
            ["DialogueId"] = 12026624,
            ["GUID"] = "1E1B7E00",
            ["NextDialogue"] = 12026625,
            },
        [12026625] = {
            ["Content"] = "这也被你察觉到了……多谢你牵挂着我。",
            ["ContentJP"] = "……それも気づいてくださったのですね。気にかけてくれて、ありがとうございます。",
            ["DialogueId"] = 12026625,
            ["GUID"] = "1E1B7E2A",
            ["NextDialogue"] = 12026626,
            ["SpeakNpcId"] = 210127,
            },
        [12026626] = {
            ["Content"] = "{nickname}，你也有对你而言意义重大的家人吧。倘若你犯下了言语过失，伤了那人的心，你会怎么做？",
            ["ContentJP"] = "{nickname}、あなたにも、とても大切に思う家族がいるでしょう？もし、あなたの不用意な言葉がその人を傷つけてしまったら……あなたはどうしますか？",
            ["DialogueId"] = 12026626,
            ["GUID"] = "1E1B7E54",
            ["NextDialogue"] = 12026627,
            ["SpeakNpcId"] = 210127,
            },
        [12026627] = {
            ["Content"] = "既然是家人，肯定不会有化解不了的矛盾。我想如果有一天真的发生了那种事情，我会很努力地去道歉，那样她一定会接受的。",
            ["ContentJP"] = "家族なら、きっとどんな喧嘩でも仲直りできると思う。だから、もし本当にそうなったら、{性别:僕|私}は一生懸命謝るよ。きっと許してくれるはず。",
            ["DialogueId"] = 12026627,
            ["GUID"] = "1E1B7E7E",
            ["NextDialogue"] = 12026628,
            ["SpeakNpcId"] = 100001,
            },
        [12026628] = {
            ["Content"] = "但若是伊人已逝，此时再想道歉，也无人聆听……那又该如何是好？",
            ["ContentJP"] = "……では、もしその相手がもうこの世にいなかったら？今さら謝りたいと思っても、聞いてくれる相手がいなかったら？——そのとき、あなたはどうするのでしょうね。",
            ["DialogueId"] = 12026628,
            ["GUID"] = "1E1B7EA8",
            ["NextDialogue"] = 12026629,
            ["SpeakNpcId"] = 210127,
            },
        [12026629] = {
            ["Content"] = "扶疏…………",
            ["ContentJP"] = "フーシュ…………",
            ["DialogueId"] = 12026629,
            ["GUID"] = "1E1B7ED2",
            ["NextDialogue"] = 12026630,
            ["SpeakNpcId"] = 100001,
            },
        [12026630] = {
            ["Content"] = "抱歉。不小心竟将自己的愁绪强加于你了。",
            ["ContentJP"] = "すみません。自分の憂いを、あなたに押しつけてしまいましたね。",
            ["DialogueId"] = 12026630,
            ["GUID"] = "1E1B7EFC",
            ["NextDialogue"] = 12026631,
            ["SpeakNpcId"] = 210127,
            },
        [12026631] = {
            ["Content"] = "没关系，如果你有什么不开心的，都可以来和我说，我随时在这里。",
            ["ContentJP"] = "いいんだよ。辛い時は、いつでも話して。{性别:僕|私}はここにいるから。",
            ["DialogueId"] = 12026631,
            ["GUID"] = "1E1B7F26",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 100001,
            },
        [12026632] = {
            ["Content"] = "你真的是百年之前的人吗？",
            ["ContentJP"] = "あなたは、本当に百年以上前の人なの？",
            ["DialogueId"] = 12026632,
            ["GUID"] = "1E1B7F50",
            ["NextDialogue"] = 12026633,
            },
        [12026633] = {
            ["Content"] = "嗯……如我先前所说，家姐为了延缓我的疾病进程，将我的躯体冻结。直至最近，我才被从百年的沉眠中唤醒。",
            ["ContentJP"] = "はい。先ほども言ったように、姉が私の病を遅らせるために、私の身体を凍結させたのです。そして最近になって、ようやく百年の眠りから目覚めました。",
            ["DialogueId"] = 12026633,
            ["GUID"] = "1E1B7F7A",
            ["NextDialogue"] = 12026634,
            ["SpeakNpcId"] = 210127,
            },
        [12026634] = {
            ["Content"] = "这个世界会让你感到陌生吗？",
            ["ContentJP"] = "それって……この世界がすごく知らないものに見えたりしない？",
            ["DialogueId"] = 12026634,
            ["GUID"] = "1E1B7FA4",
            ["NextDialogue"] = 12026635,
            ["SpeakNpcId"] = 100001,
            },
        [12026635] = {
            ["Content"] = "或许吧。我刚刚醒来时，只感觉这世上的云卷云舒，一草一木，都不再和我有半分关联。",
            ["ContentJP"] = "最初はそうでした。目に映る空も草木も、まるで自分とは関係のない世界のように思えました。",
            ["DialogueId"] = 12026635,
            ["GUID"] = "1E1B7FCE",
            ["NextDialogue"] = 12026636,
            ["SpeakNpcId"] = 210127,
            },
        [12026636] = {
            ["Content"] = "但随着时间发展，我也慢慢结识了你这样的友人。",
            ["ContentJP"] = "でも……あなたのような友人ができて、少しずつ景色に色が戻りました。",
            ["DialogueId"] = 12026636,
            ["GUID"] = "1E1B7FF8",
            ["NextDialogue"] = 12026637,
            ["SpeakNpcId"] = 210127,
            },
        [12026637] = {
            ["Content"] = "现今世间百态，抑或是医理发展，都使我感到新奇。换个角度来看，也是一件幸事。",
            ["ContentJP"] = "今の世界の移ろいや新しい医理の発展も、私にとってはとても新鮮で、別の見方をすれば……幸運だったのかもしれません。",
            ["DialogueId"] = 12026637,
            ["GUID"] = "1E1B8022",
            ["NextDialogue"] = 12026640,
            ["SpeakNpcId"] = 210127,
            },
        [12026638] = {
            ["Content"] = "我先走了。",
            ["ContentJP"] = "お先に失礼します。",
            ["DialogueId"] = 12026638,
            ["GUID"] = "1E1B804C",
            ["NextDialogue"] = 12026639,
            },
        [12026639] = {
            ["Content"] = "你且去忙吧，注意身体。",
            ["ContentJP"] = "では、あなたもどうか無理なさらず。身体に気をつけて、お過ごしください。",
            ["DialogueId"] = 12026639,
            ["GUID"] = "1E1B8076",
            ["SpeakNpcId"] = 210127,
            },
        [12026640] = {
            ["DialogueId"] = 12026640,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0,
            ["FinalDialogueId"] = 12026639,
            ["GUID"] = "1E1B8077",
            ["NextOptions"] = {
                [1] = 12026604,
                [2] = 12026614,
                [3] = 12026624,
                [4] = 12026632,
                [5] = 12026638,
                },
            },
        [12026701] = {
            ["Content"] = "咿呀，咿咿呀，咿！",
            ["ContentJP"] = "いぃや〜、いぃいぃや、いっ！",
            ["DialogueId"] = 12026701,
            ["GUID"] = "1E1B8AA2",
            ["NextDialogue"] = 12026702,
            ["SpeakNpcId"] = 210128,
            },
        [12026702] = {
            ["Content"] = "（它跟在扶疏身边，好像很开心的样子。）",
            ["ContentJP"] = "（フーシュのそばに寄り添って、とても嬉しそうにしている……。）",
            ["DialogueId"] = 12026702,
            ["GUID"] = "1E1B8ACC",
            ["SpeakNpcId"] = 100001,
            },
        [12026801] = {
            ["Content"] = "猎物已经入网，此时行事须格外慎重，切忌打草惊蛇。",
            ["ContentJP"] = "獲物はすでに網にかかった、ここからは慎重に動くんだ。決して驚かすような真似をしてはならん。",
            ["DialogueId"] = 12026801,
            ["GUID"] = "1E1B9B0A",
            ["NextDialogue"] = 12026802,
            },
        [12026802] = {
            ["Content"] = "{nickname}，你若已经准备好了，我们就继续向前吧。",
            ["ContentJP"] = "{nickname}、準備ができたなら、行こうか。この先へ進むとしよう。",
            ["DialogueId"] = 12026802,
            ["GUID"] = "1E1B9B34",
            },
        [12026901] = {
            ["Content"] = "如果我没有猜错，这上古机括战阵，其真名为千枢狩阵。取千枢为引，万隙囚光之意。",
            ["ContentJP"] = "もし私の推測が正しければ——この古代の機巧戦陣、その真名は「<Default note=\"text:せんすうかりのじん\">千枢狩陣</>」。千の<Default note=\"text:きすう\">機枢</>を媒介とし、万の隙間を封じ光を囚える……そんな意味を持つんだ。",
            ["DialogueId"] = 12026901,
            ["GUID"] = "1E1BAB72",
            ["NextDialogue"] = 12026902,
            },
        [12026902] = {
            ["Content"] = "古物于我们面前重焕生机……不觉得这景象很壮观吗？",
            ["ContentJP"] = "見よ、古の物が我らの前で再び息を吹き返している。……壮観だとは思わないか？",
            ["DialogueId"] = 12026902,
            ["GUID"] = "1E1BAB9C",
            },
        [12027001] = {
            ["Content"] = "您可以去尘漠石海最高处的位置，那里通往烛阴祭坛的临时道路已经搭建完毕。",
            ["ContentJP"] = "<Default note=\"text:じんじゃのあらうみ\">塵砂の荒海</>の最も高い場所から、<Default note=\"text:しょくいんさいだん\">燭陰祭壇</>へ向かう仮設の道が既に開いています。どうぞそちらへお進みください。",
            ["DialogueId"] = 12027001,
            ["GUID"] = "1E1BBBDA",
            ["NextDialogue"] = 12027002,
            ["SpeakNpcId"] = 210129,
            },
        [12027002] = {
            ["Content"] = "封印仪式一旦开启，烛阴极有可能受刺激狂化。祭坛周围危机四伏，不可大意。",
            ["ContentJP"] = "封印の儀が始まれば、<Default note=\"text:しょくいん\">燭陰</>が刺激を受けて狂乱状態になる恐れがあります。祭壇の周囲は危険が満ちています、決して気を抜かないでください。",
            ["DialogueId"] = 12027002,
            ["GUID"] = "1E1BBC04",
            ["NextDialogue"] = 12027003,
            ["SpeakNpcId"] = 210129,
            },
        [12027003] = {
            ["Content"] = "狩月人，您务必要小心，您的安危才是第一位的。我在这里等待您顺利归来。",
            ["ContentJP"] = "月狩り人さん……どうか、ご無事で。あなたの身の安全こそが最も大切なのです。私はここで、あなたが無事に戻られるのをお待ちしています。",
            ["DialogueId"] = 12027003,
            ["GUID"] = "1E1BBC2E",
            ["SpeakNpcId"] = 210129,
            },
        [12027101] = {
            ["Content"] = "姐姐不在菱生身边了……但是姐姐现在很高兴，菱生能感觉得到。",
            ["ContentJP"] = "お姉ちゃんは、もうリョウセイのそばにいない……でもね……お姉ちゃん、今はすごく嬉しそうなの。……リョウセイには、それがちゃんと分かるんだよ。",
            ["DialogueId"] = 12027101,
            ["GUID"] = "1E1BCC42",
            ["SpeakNpcId"] = 210130,
            },
        [12030001] = {
            ["Content"] = "那是不久之前，发生在冰湖城的一段故事——",
            ["ContentJP"] = "つい最近のこと、アイスレイク城で語り継がれた物語――",
            ["DialogueId"] = 12030001,
            ["Duration"] = 4,
            ["GUID"] = "1E1DA80A",
            ["NextDialogue"] = 12030002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA80A",
            },
        [12030002] = {
            ["Content"] = "当一只小夜莺，决定勇敢地飞出它温暖的巢穴。",
            ["ContentJP"] = "一羽の小さなナイチンゲールが、あたたかな巣を飛び出す決心をしました。",
            ["DialogueId"] = 12030002,
            ["Duration"] = 4,
            ["GUID"] = "1E1DA834",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA834",
            },
        [12030003] = {
            ["Content"] = "菲娜坐在家里，看着故事书",
            ["DialogueId"] = 12030003,
            ["GUID"] = "1E1DA85E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DA85E",
            },
        [12030101] = {
            ["Content"] = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
            ["DialogueId"] = 12030101,
            ["GUID"] = "1E1DB872",
            ["NextDialogue"] = 12030102,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB872",
            },
        [12030102] = {
            ["Content"] = "唔……",
            ["DialogueId"] = 12030102,
            ["GUID"] = "1E1DB89C",
            ["NextDialogue"] = 12030103,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB89C",
            },
        [12030103] = {
            ["Content"] = "怎么了？",
            ["DialogueId"] = 12030103,
            ["GUID"] = "1E1DB8C6",
            ["NextDialogue"] = 12030104,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB8C6",
            },
        [12030104] = {
            ["Content"] = "奥特赛德，菲娜……菲娜有一个愿望！",
            ["DialogueId"] = 12030104,
            ["GUID"] = "1E1DB8F0",
            ["NextDialogue"] = 12030105,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB8F0",
            },
        [12030105] = {
            ["Content"] = "是吗？你说，是什么愿望？",
            ["DialogueId"] = 12030105,
            ["GUID"] = "1E1DB91A",
            ["NextDialogue"] = 12030106,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB91A",
            },
        [12030106] = {
            ["Content"] = "菲娜想出去看看。",
            ["DialogueId"] = 12030106,
            ["GUID"] = "1E1DB944",
            ["NextDialogue"] = 12030107,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB944",
            },
        [12030107] = {
            ["Content"] = "出去……？现在吗？",
            ["DialogueId"] = 12030107,
            ["GUID"] = "1E1DB96E",
            ["NextDialogue"] = 12030108,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB96E",
            },
        [12030108] = {
            ["Content"] = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
            ["DialogueId"] = 12030108,
            ["GUID"] = "1E1DB998",
            ["NextDialogue"] = 12030109,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB998",
            },
        [12030109] = {
            ["Content"] = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
            ["DialogueId"] = 12030109,
            ["GUID"] = "1E1DB9C2",
            ["NextDialogue"] = 12030110,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB9C2",
            },
        [12030110] = {
            ["Content"] = "所以，你还是待在家里最安全。",
            ["DialogueId"] = 12030110,
            ["GUID"] = "1E1DB9EC",
            ["NextDialogue"] = 12030111,
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DB9EC",
            },
        [12030111] = {
            ["Content"] = "呜……",
            ["DialogueId"] = 12030111,
            ["GUID"] = "1E1DBA16",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DBA16",
            },
        [12030112] = {
            ["Content"] = "转场，菲娜在睡觉，奥特赛德看到桌上的故事书",
            ["ContentJP"] = "フィーナは眠っている。アウトサイダーが、机の上に置かれたフィーナの本を見ている",
            ["DialogueId"] = 12030112,
            ["GUID"] = "1E1DBA40",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DBA40",
            },
        [12030201] = {
            ["Camera"] = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
            ["Content"] = "“大魔法师总是说，巢穴外的世界充满了危险，呆在巢穴里才是最安全的……可是小小的巢穴虽然温暖，却只能看到一小片方形的天空。”",
            ["ContentJP"] = "「大魔法使いはいつも言っていました。外の世界は危険で、巣の中が一番安全だと……でも、小さな巣から見えるのは、四角く切り取られた空だけ」",
            ["DialogueId"] = 12030201,
            ["FinalCamera"] = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
            ["GUID"] = "1E1DC8DA",
            ["LookAt"] = {
                [1] = "211002:p(pFeina_FixSimple02_LookAt01)",
                },
            ["NextDialogue"] = 12030202,
            ["TalkActionId"] = {
                [1] = "211024:Feina_Story_Lieidle",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC8DA",
            },
        [12030202] = {
            ["Camera"] = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
            ["Content"] = "“有一天，从很远很远的地方漂流而来的独角兽{性别：先生|小姐}来到了小夜莺的巢穴，为小夜莺捎来了远方的故事……”",
            ["ContentJP"] = "「ある日、遠い国からユニコーンの{性别:お兄さん|お姉さん}がやってきて、\
ナイチンゲールに、遠くの世界の話を聞かせてくれました」",
            ["DialogueId"] = 12030202,
            ["FinalCamera"] = "-445.522095,482.669922,106.667969,0.000118,8.757859,54.209782,35.000008,212.663025,false,Manual,2.8",
            ["GUID"] = "1E1DC904",
            ["NextDialogue"] = 12030203,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC904",
            },
        [12030203] = {
            ["Camera"] = "-93.792816,296.109375,123.785156,0.000262,-14.836967,-25.180407,28.0,180.0,false,Manual,3.5",
            ["Content"] = "“在巢穴之外那广阔的世界里，有枝条能挂在月亮上的大树，有怀抱着一百座小岛的大海……”",
            ["ContentJP"] = "「巣の外には、月に届く枝を伸ばす木があって、百の小島を抱く大きな海が広がっていると……」",
            ["DialogueId"] = 12030203,
            ["FinalCamera"] = "-93.792816,296.109375,123.785156,0.000261,-34.236603,-38.179943,28.000006,63.699184,false,Manual,3.5",
            ["GUID"] = "1E1DC92E",
            ["NextDialogue"] = 12030204,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC92E",
            },
        [12030204] = {
            ["Camera"] = "-93.792816,296.109375,123.785156,0.000249,-34.236633,-38.180016,28.0,180.0,false,Manual,3.5",
            ["Content"] = "“小夜莺也好想飞到大树的枝头，和每一朵绽放的花打招呼，去小松鼠的家里做客……”",
            ["ContentJP"] = "「ナイチンゲールは思いました。私もあの枝の上まで飛んでいって、咲き誇る花に挨拶して、リスの家に遊びに行きたい……」",
            ["DialogueId"] = 12030204,
            ["FinalCamera"] = "-222.147125,357.158203,220.230469,0.000264,-30.234377,-29.18161,35.0,180.0,false,Manual,3.5",
            ["GUID"] = "1E1DC958",
            ["NextDialogue"] = 12030205,
            ["Scripts"] = "SEQ{LookAt{LookAtDescription{\"211002:p(pFeina_FixSimple02_LookAt01)\"}}}",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC958",
            },
        [12030205] = {
            ["Camera"] = "-139.631927,210.423828,144.097656,0.000295,7.366509,66.22287,35.0,112.741165,false,Manual,4.0",
            ["Content"] = "“想乘上柔软的云，和掠过高空的海燕并肩翱翔，和跃出海面的鱼儿一起嬉戏……”",
            ["ContentJP"] = "ふわふわな雲に乗って、燕と並んで空を飛んで、海から跳ねる魚たちといっしょに遊んでみたい……」",
            ["DialogueId"] = 12030205,
            ["GUID"] = "1E1DC982",
            ["NextDialogue"] = 12030206,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC982",
            },
        [12030206] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12030206,
            ["GUID"] = "1E1DC9AC",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC9AC",
            },
        [12030207] = {
            ["Content"] = "转场，白天",
            ["DialogueId"] = 12030207,
            ["GUID"] = "1E1DC9D6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DC9D6",
            },
        [12030300] = {
            ["Camera"] = "-201.678467,47.8125,111.152344,0.000102,20.154959,-60.375671,28.0,293.312073,false,Manual,2.8",
            ["DialogueId"] = 12030300,
            ["FinalCamera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,125.074371,false,Manual,2.8",
            ["GUID"] = "1E1DD941",
            ["NextDialogue"] = 12030301,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [12030301] = {
            ["Camera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,125.074371,false,Manual,2.8",
            ["Content"] = "菲娜。",
            ["ContentJP"] = "フィーナ。",
            ["DialogueId"] = 12030301,
            ["FinalCamera"] = "-214.884705,6.785156,112.378906,0.00011,6.354692,-2.17627,28.0,324.258209,false,Manual,2.8",
            ["GUID"] = "1E1DD942",
            ["NextDialogue"] = 12030302,
            ["Scripts"] = "LookAt{LookAtDescription{\"211002:n(211001)\"}},\
",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 2,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD942",
            },
        [12030302] = {
            ["Camera"] = "53.489204,-49.375,131.65625,0.000106,-4.241547,154.817291,35.0,172.252792,false,Manual,2.8",
            ["Content"] = "奥特赛德？你今天怎么回来得这么早……发生什么事了吗？",
            ["ContentJP"] = "アウトサイダー？今日はずいぶん早かったね……何かあったの？",
            ["DialogueId"] = 12030302,
            ["FinalCamera"] = "26.751808,-36.806641,129.472656,0.00011,-4.24154,154.817642,35.0,132.363815,false,Manual,2.8",
            ["GUID"] = "1E1DD96C",
            ["NextDialogue"] = 12030303,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211001:n(211002)\"}},\
PlayFacial{_delay{1.5},ActorId{211001},FacialId{\"Happy01\"}},\
PlayAnimation{_delay{1.5},ActorId{211001},AnimationId{\"Shy01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211001:p(40)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD96C",
            },
        [12030303] = {
            ["Camera"] = "-10.235954,65.589844,155.683594,0.000051,-1.24011,-35.390144,35.000008,286.639435,false,Manual,2.8",
            ["Content"] = "确实有一件重要的事——今天是新手魔法师菲娜的第一次冒险之旅，我特地回来给她加油鼓劲。",
            ["ContentJP"] = "ああ、ちょっと大事な用があってな――今日は、新人魔法使いフィーナの初めての冒険日だろ？応援しに戻ってきたのさ。",
            ["DialogueId"] = 12030303,
            ["FinalCamera"] = "4.515831,55.119141,155.300781,0.000051,-1.24011,-35.390144,35.000008,286.639435,false,Manual,2.8",
            ["GUID"] = "1E1DD996",
            ["NextDialogue"] = 12030304,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"ConfidentR_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD996",
            },
        [12030304] = {
            ["Camera"] = "80.626434,-20.03125,162.339844,0.000114,-10.841299,166.216843,55.000008,178.363068,false,Manual,2.8",
            ["Content"] = "咦？",
            ["ContentJP"] = "え……？",
            ["DialogueId"] = 12030304,
            ["GUID"] = "1E1DD9C0",
            ["NextDialogue"] = 12030305,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0.1},ActorId{211001},FacialId{\"None\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD9C0",
            },
        [12030305] = {
            ["Camera"] = "-108.768295,398.734375,113.765625,0.000063,0.559174,-73.189148,28.0,366.148499,false,Manual,2.8",
            ["Content"] = "我看了你写的故事，你很想去外面的世界看看，对吧？我同意了，你现在就可以出门去冒险啦。",
            ["ContentJP"] = "お前が書いた物語、読んだぞ。外の世界に行ってみたいんだろ？いいぜ、俺が許可する。今から冒険に出てもいいぜ。",
            ["DialogueId"] = 12030305,
            ["FinalCamera"] = "-97.715012,362.148438,114.128906,0.000063,0.559174,-73.189117,28.000006,366.148499,false,Manual,2.8",
            ["GUID"] = "1E1DD9EA",
            ["NextDialogue"] = 12030306,
            ["Scripts"] = "\
SEQ{\
PlayAnimation{ActorId{211002},AnimationId{\"ConfidentRToExplain_Start\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"TilteHead_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DD9EA",
            },
        [12030306] = {
            ["Camera"] = "52.159672,-22.074219,168.640625,0.000079,-14.240568,163.610046,55.0,154.192795,false,Manual,2.8",
            ["Content"] = "可是，你不是说外面很危险，还有很多坏巫师吗……？",
            ["ContentJP"] = "でも……外は危ないって言ってたじゃない。悪い魔法使い、たくさんいるんでしょ……？",
            ["DialogueId"] = 12030306,
            ["FinalCamera"] = "37.80537,-17.855469,164.851562,0.000084,-14.240541,163.610001,55.0,138.46257,false,Manual,2.8",
            ["GUID"] = "1E1DDA14",
            ["NextDialogue"] = 12030307,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Shy02_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Sad01\"}}\
}\
\
",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA14",
            },
        [12030307] = {
            ["Camera"] = "53.723839,-28.212891,158.828125,0.000089,-2.841516,-22.7857,28.000008,150.228668,false,Manual,2.8",
            ["Content"] = "不用担心，我这个“大魔法师”已经给你使用了最厉害的守护魔法，坏巫师根本不敢靠近。",
            ["ContentJP"] = "心配すんな。この「大魔法使い」が、最強の守護魔法をかけてやった。悪党どもなんざ、びびって近づきもしねぇよ。",
            ["DialogueId"] = 12030307,
            ["FinalCamera"] = "68.022377,-34.214844,158.117188,0.000089,-2.6415,-22.785671,28.000008,150.228668,false,Manual,2.8",
            ["GUID"] = "1E1DDA3E",
            ["NextDialogue"] = 12030308,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211002},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"ConfidentRToExplain_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA3E",
            },
        [12030308] = {
            ["Content"] = "不过，就像故事书里说的，魔法不是永久的——所以你只能在白天出门，而且也不能走得太远，否则魔法就会失效了。",
            ["ContentJP"] = "ただな、本にあった通り――魔法ってのは永遠じゃねぇ。だから出かけていいのは昼間だけ。それと、あんまり遠くまでは行くなよ。魔法が薄まっちまうからな。",
            ["DialogueId"] = 12030308,
            ["FinalCamera"] = "74.63475,-33.244141,159.617188,0.000087,-1.641288,-22.979761,28.000006,146.329025,false,Manual,2.8",
            ["GUID"] = "1E1DDA68",
            ["NextDialogue"] = 12030309,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA68",
            },
        [12030309] = {
            ["Camera"] = "68.511589,-59.673828,134.019531,0.000108,-2.441301,153.218155,55.0,178.363068,false,Manual,2.8",
            ["Content"] = "……好！",
            ["ContentJP"] = "……うん、わかった！",
            ["DialogueId"] = 12030309,
            ["FacialId"] = {
                [1] = "211001:Happy01",
                },
            ["GUID"] = "1E1DDA92",
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211001:n(211002)\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["TalkActionId"] = {
                [1] = "211001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDA92",
            },
        [12030310] = {
            ["Content"] = "菲娜拿着魔法书出门，奥特赛德看着她离开，随后主角入镜",
            ["ContentJP"] = "フィーナは魔法書を手に、外へと出ていった。アウトサイダーは彼女の背を見送ったあと、こちらを振り向く。",
            ["DialogueId"] = 12030310,
            ["GUID"] = "1E1DDABC",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DDABC",
            },
        [12030400] = {
            ["Camera"] = "1266.484619,-178.583984,366.181152,0.000043,-9.398552,-176.39032,35.000011,100000.0,false,Manual,4.0",
            ["Content"] = "冰湖城，上午【临时】",
            ["DialogueId"] = 12030400,
            ["Duration"] = 8,
            ["FinalCamera"] = "1301.278198,-365.192383,256.428711,0.000054,-9.198332,163.00029,35.000011,622.412903,false,Manual,4.0",
            ["GUID"] = "1E1DE9A9",
            ["NextDialogue"] = 12030401,
            ["ToFinalCameraBlendTime"] = 8,
            },
        [12030401] = {
            ["Camera"] = "1305.487793,-265.864258,306.96875,0.00014,-3.399658,179.117737,35.000008,272.126312,false,Manual,22.0",
            ["Content"] = "接下来就交给你了。",
            ["ContentJP"] = "あとは任せるぜ。",
            ["DialogueId"] = 12030401,
            ["FinalCamera"] = "1354.122437,-266.613281,197.483887,0.00014,-2.999628,179.117737,35.000008,272.126312,false,Manual,22.0",
            ["GUID"] = "1E1DE9AA",
            ["NextDialogue"] = 12030402,
            ["Scripts"] = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Look01_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9AA",
            },
        [12030402] = {
            ["Camera"] = "699.66394,-379.948242,204.811523,0.000031,-5.9989,24.603928,35.000011,249.091507,false,Manual,4.0",
            ["Content"] = "你大概也猜到了，菲娜在过去经历过一些……很复杂的事情。虽说都过去了，但我还是有点担心她会被什么人认出来，引来不必要的麻烦。",
            ["ContentJP"] = "なんとなく察してるかもしれねぇけど、フィーナは昔、ちょっとややこしいことがあってな。もう全部終わったことではあるけど……万が一、誰かに気付かれたら厄介だからな。",
            ["DialogueId"] = 12030402,
            ["FinalCamera"] = "729.398315,-366.335938,201.375,0.000031,-5.9989,24.603533,35.000011,249.091507,false,Manual,4.0",
            ["GUID"] = "1E1DE9D4",
            ["NextDialogue"] = 12030403,
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9D4",
            },
        [12030403] = {
            ["Content"] = "你为什么不自己跟着她呢？",
            ["ContentJP"] = "だったら自分でついて行けばいいのに。",
            ["DialogueId"] = 12030403,
            ["GUID"] = "1E1DE9FE",
            ["NextDialogue"] = 12030404,
            ["Scripts"] = "LookAt{LookAtDescription{\"100001:n(211002)\"}}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DE9FE",
            },
        [12030404] = {
            ["Camera"] = "775.80603,-164.087891,170.229492,0.000074,3.000078,-28.687651,39.289318,212.725189,false,Manual,2.8",
            ["Content"] = "毕竟是小朋友的娱乐活动，我跟着也不太合适……",
            ["ContentJP"] = "いや、子どものお遊びに俺がついて行くのも変だろ？場違いっつーか……",
            ["DialogueId"] = 12030404,
            ["FinalCamera"] = "787.402832,-170.431641,170.922363,0.000074,3.000078,-28.687651,39.289318,212.725189,false,Manual,2.8",
            ["GUID"] = "1E1DEA28",
            ["NextDialogue"] = 12030405,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211002:n(100001)\"}},\
PlayAnimation{ActorId{211002},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk01_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA28",
            },
        [12030405] = {
            ["Camera"] = "847.966919,-332.923828,167.130371,0.000161,-0.199687,43.514797,35.000008,140.89209,false,Manual,2.8",
            ["Content"] = "唉，可怜的奥特赛德，已经变成无聊的大人了呀。",
            ["ContentJP"] = "はぁ、かわいそうなアウトサイダー。すっかりつまらない大人になったね。",
            ["DialogueId"] = 12030405,
            ["FinalCamera"] = "858.939087,-322.508789,167.078125,0.000161,-0.199687,43.514797,35.000008,125.894028,false,Manual,2.8",
            ["GUID"] = "1E1DEA52",
            ["NextDialogue"] = 12030406,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{_delay{0.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Talk01_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA52",
            },
        [12030406] = {
            ["Camera"] = "704.098999,-7.766602,177.265137,0.000081,0.200049,-46.484791,39.289318,402.856293,false,Manual,2.8",
            ["Content"] = "哪有！主要是我都答应让她自己出门了，还跟在后面的话，我怕她会不高兴。",
            ["ContentJP"] = "違うって！ちゃんと許可出したんだから、あとからコソコソついて行ったら、本人に怒られるっての。",
            ["DialogueId"] = 12030406,
            ["FinalCamera"] = "690.504517,6.551758,177.196289,0.000081,0.200049,-46.484791,39.289318,402.856293,false,Manual,2.8",
            ["GUID"] = "1E1DEA7C",
            ["NextDialogue"] = 12030407,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk01_End\"},Duration{1}},\
LookAt{LookAtDescription{\"211002:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEA7C",
            },
        [12030407] = {
            ["Content"] = "我看她挺喜欢你这个“独角兽{性别：先生|小姐}”的，你就当帮我个忙嘛，我的好队长！",
            ["ContentJP"] = "それにあの子、お前のこと気に入ってるみたいだしよ。な？「ユニコーンの{性别:お兄さん|お姉さん}」として、ちょっとだけ見守ってやってくれよ、頼む！",
            ["DialogueId"] = 12030407,
            ["GUID"] = "1E1DEAA6",
            ["NextDialogue"] = 12030408,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Talk02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAA6",
            },
        [12030408] = {
            ["Camera"] = "854.199219,-325.050781,195.624023,0.000087,-9.39987,37.314049,39.289318,140.252518,false,Manual,2.8",
            ["Content"] = "我可不是免费的哦。",
            ["ContentJP"] = "タダ仕事は引き受けないよ。",
            ["DialogueId"] = 12030408,
            ["FinalCamera"] = "871.305054,-312.015625,192.064453,0.000087,-9.39987,37.314049,39.289318,116.633705,false,Manual,2.8",
            ["GUID"] = "1E1DEAD0",
            ["NextDialogue"] = 12030409,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(211002)\"}},\
PlayFacial{ActorId{100001},FacialId{\"Smile02\"}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk03_Start\"},Duration{1}}\
}\
",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAD0",
            },
        [12030409] = {
            ["Camera"] = "787.42334,-98.248047,152.363281,0.000112,6.400467,-44.484207,39.289318,176.364334,false,Manual,10.0",
            ["Content"] = "这好说，你想要什么报答尽管提，请你吃饭，帮你干活，或者叫你一个月{性别：大哥|大姐头}都行……学狗叫除外！",
            ["ContentJP"] = "そりゃもちろん。報酬は何でも言ってくれ。飯でも奢るし、手伝ってほしいことがあればやるし、「一ヶ月ずっと{性别:兄貴|姉貴}」って呼んでほしけりゃ、それでもいいぞ？……犬の鳴きマネ以外ならな！",
            ["DialogueId"] = 12030409,
            ["FinalCamera"] = "797.796387,-108.432617,153.995117,0.000112,6.400467,-44.484207,39.289318,176.364334,false,Manual,10.0",
            ["GUID"] = "1E1DEAFA",
            ["NextDialogue"] = 12030410,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"AgreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEAFA",
            },
        [12030410] = {
            ["Camera"] = "461.232666,-276.961914,161.877441,0.000121,-0.399593,4.115808,35.0,272.126312,false,Manual,10.0",
            ["Content"] = "那真是太可惜了，我正想复习一下驯兽技巧。",
            ["ContentJP"] = "あー、それは残念。ちょうど調教の復習をしようと思ってたのに。",
            ["DialogueId"] = 12030410,
            ["FinalCamera"] = "426.237671,-279.481445,162.121582,0.000121,-0.399593,4.115808,35.0,272.126312,false,Manual,10.0",
            ["GUID"] = "1E1DEB24",
            ["NextDialogue"] = 12030411,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{ActorId{211002},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayFacial{ActorId{100001},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DEB24",
            },
        [12030411] = {
            ["Content"] = "你就饶了我吧……",
            ["ContentJP"] = "勘弁してくれ……",
            ["DialogueId"] = 12030411,
            ["GUID"] = "1E1DEB4E",
            ["NextDialogue"] = 12030412,
