            ["SpeakNpcId"] = 211013,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFA90",
            },
        [12030505] = {
            ["Content"] = "这个嘛……说不定她现在变得厉害了，就不怕出门了！",
            ["ContentJP"] = "ふふーん、もしかしたらパワーアップして外にも出られるようになったのかもよ！",
