            ["Camera"] = "-45.714355,-177.095703,117.589355,0.000137,-0.198854,82.011528,35.000019,218.878983,false,Manual,2.8",
            ["Content"] = "好呀！可是，“贪吃鬼”是什么游戏？我可能不会玩……",
            ["ContentJP"] = "いいよ！でも、ルールわからない……",
            ["DialogueId"] = 12030520,
            ["FinalCamera"] = "-43.980469,-164.746094,117.545898,0.000137,-0.198854,82.011528,35.000019,218.878983,false,Manual,2.8",
            ["GUID"] = "1E1DFD30",
            ["NextDialogue"] = 12030521,
            ["Scripts"] = "SEQ{\
PlayFacial{ActorId{211001},FacialId{\"Happy02\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFD30",
            },
        [12030521] = {
            ["Camera"] = "-253.641113,416.605469,138.781738,0.000156,-6.998512,-71.883408,24.419483,1094.441895,false,Manual,15.0",
            ["Content"] = "很简单的，你听我说！一个人扮贪吃鬼，其他人扮烤土豆。游戏开始的时候，贪吃鬼闭上眼睛，烤土豆们就趁这个时候找地方躲起来。",
            ["ContentJP"] = "大丈夫、簡単だよ！ひとりが「食いしん坊鬼」で、他の人は「焼きいも」。鬼は目をつぶって60数える。そのあいだに焼きいもたちは隠れるの！",
            ["DialogueId"] = 12030521,
            ["FinalCamera"] = "-240.412598,376.173828,133.561035,0.000156,-6.998512,-71.883408,24.419483,1094.441895,false,Manual,15.0",
            ["GUID"] = "1E1DFD5A",
            ["NextDialogue"] = 12030522,
            ["SpeakNpcId"] = 211011,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFD5A",
            },
        [12030522] = {
            ["Content"] = "贪吃鬼数完60下，就可以睁开眼睛开始找吃的。找到烤土豆的话，贪吃鬼就可以“嗷呜！”一口把烤土豆吃掉。",
            ["ContentJP"] = "60数え終わったら、鬼が目を開けて、かくれた焼きいもを探すの。見つけたら「ガブッ！」って食べるマネするんだよ！",
            ["DialogueId"] = 12030522,
            ["GUID"] = "1E1DFD84",
            ["NextDialogue"] = 12030523,
            ["SpeakNpcId"] = 211011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFD84",
            },
        [12030523] = {
            ["Content"] = "三分钟里吃掉所有的烤土豆，就是贪吃鬼赢；没吃完的话，贪吃鬼就会饿晕过去，烤土豆赢！",
            ["ContentJP"] = "3分以内に全部食べたら鬼の勝ち！残ってたら、鬼はおなかすきすぎて倒れちゃうの！",
            ["DialogueId"] = 12030523,
            ["GUID"] = "1E1DFDAE",
            ["NextDialogue"] = 12030524,
            ["SpeakNpcId"] = 211011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFDAE",
            },
        [12030524] = {
            ["Camera"] = "-58.322266,-105.651367,119.556152,0.000138,0.401116,79.010231,35.000019,178.36145,false,Manual,2.8",
            ["Content"] = "可是，烤土豆为什么会动呢？",
            ["ContentJP"] = "でも……焼きいもって、動かないよね？",
            ["DialogueId"] = 12030524,
            ["FinalCamera"] = "-56.606445,-96.818359,119.618652,0.000138,0.401116,79.010231,35.000019,159.390686,false,Manual,2.8",
            ["GUID"] = "1E1DFDD8",
            ["NextDialogue"] = 12030525,
            ["Scripts"] = "PARA{\
PlayFacial{ActorId{211001},FacialId{\"Think01\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_CuteHairAction_Loop\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFDD8",
            },
        [12030525] = {
            ["Camera"] = "-157.704102,-477.165039,108.151855,0.000125,-0.99884,82.013466,35.000015,251.595764,false,Manual,22.0",
            ["Content"] = "对哦，为什么呢……？我家里的烤土豆也不会动。",
            ["ContentJP"] = "あっ、たしかに……うちの焼きいもも動かないもん！",
            ["DialogueId"] = 12030525,
            ["GUID"] = "1E1DFE02",
            ["NextDialogue"] = 12030526,
            ["SpeakNpcId"] = 211010,
            ["TalkActionId"] = {
                [1] = "211010:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFE02",
            },
        [12030526] = {
            ["Content"] = "这不重要吧……",
            ["ContentJP"] = "そこは気にしなーい！",
            ["DialogueId"] = 12030526,
            ["GUID"] = "1E1DFE2C",
            ["NextDialogue"] = 12030527,
            ["SpeakNpcId"] = 211011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFE2C",
            },
        [12030527] = {
            ["Camera"] = "-27.393555,-102.768555,119.618652,0.000139,-0.198916,89.009705,35.000019,159.390686,false,Manual,2.8",
            ["Content"] = "啊，我知道了——也许，它们是被善良的魔法师祝福过的魔法烤土豆！",
            ["ContentJP"] = "あ、そっか――きっと、魔法の焼きいもなんだね！優しい魔法使いが、動ける魔法をかけてくれたんだよ！",
            ["DialogueId"] = 12030527,
            ["FinalCamera"] = "-26.844238,-70.899414,119.508301,0.000139,-0.198916,89.009674,35.000019,129.833313,false,Manual,2.8",
            ["GUID"] = "1E1DFE56",
            ["NextDialogue"] = 12030528,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"211001:n(211011)\"}},\
PlayAnimation{ActorId{211001},AnimationId{\"Think_End\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFE56",
            },
        [12030528] = {
            ["Content"] = "原来是这样！那我要当最厉害的魔法烤土豆。",
            ["ContentJP"] = "なるほど！じゃあ、私、最強の「魔法の焼きいも」になる！",
            ["DialogueId"] = 12030528,
            ["GUID"] = "1E1DFE80",
            ["NextDialogue"] = 12030529,
            ["SpeakNpcId"] = 211010,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFE80",
            },
        [12030529] = {
            ["Content"] = "魔法烤土豆……听起来很好吃……",
            ["ContentJP"] = "「魔法の焼きいも」……めっちゃうまそう……",
            ["DialogueId"] = 12030529,
            ["GUID"] = "1E1DFEAA",
            ["NextDialogue"] = 12030530,
            ["SpeakNpcId"] = 211013,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFEAA",
            },
        [12030530] = {
            ["Camera"] = "-224.390625,-505.521484,146.001465,0.000133,-7.598578,76.013123,35.000019,329.374176,false,Manual,22.0",
            ["Content"] = "那我们都当烤土豆，让菲娜姐姐来当贪吃鬼吧！好不好呀，菲娜姐姐？",
            ["ContentJP"] = "だーめ！あんたは鬼じゃないもん！さあさあ、ゲーム開始！フィーナお姉さんが鬼ね！",
            ["DialogueId"] = 12030530,
            ["FinalCamera"] = "-229.759766,-527.399414,148.927734,0.000134,-7.398529,76.212738,35.000019,329.374176,false,Manual,22.0",
            ["GUID"] = "1E1DFED4",
            ["NextDialogue"] = 12030531,
            ["SpeakNpcId"] = 211011,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFED4",
            },
        [12030531] = {
            ["Camera"] = "-94.611328,-127.818359,128.793945,0.000135,-2.398503,70.012207,35.000019,329.374176,false,Manual,22.0",
            ["Content"] = "好呀！那我就闭上眼睛，开始数数咯，1、2、3……",
            ["ContentJP"] = "うん、じゃあ……目をつぶるね。いーち、にー、さーん……",
            ["DialogueId"] = 12030531,
            ["FinalCamera"] = "-89.286133,-113.015625,128.135254,0.000136,-2.398503,70.212196,35.000019,329.374176,false,Manual,22.0",
            ["GUID"] = "1E1DFEFE",
            ["Scripts"] = "PlayFacial{_delay{2},ActorId{211001},FacialId{\"Confident02\"}}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFEFE",
            },
        [12030532] = {
            ["Content"] = "转场，小孩们消失，出现三个调查点（没有先后顺序）",
            ["DialogueId"] = 12030532,
            ["GUID"] = "1E1DFF28",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1DFF28",
            },
        [12030601] = {
            ["Content"] = "唔……烤土豆们在哪里呢？",
            ["ContentJP"] = "ん～……焼きいもたちはどこに隠れたのかな？",
            ["DialogueId"] = 12030601,
            ["GUID"] = "1E1E0A7A",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0A7A",
            },
        [12030605] = {
            ["Content"] = "调查第一处地点",
            ["ContentJP"] = "地点①を調査",
            ["DialogueId"] = 12030605,
            ["GUID"] = "1E1E0B22",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0B22",
            },
        [12030610] = {
            ["Content"] = "这只是一块松动的木板……",
            ["ContentJP"] = "あら……ただのグラグラしてる木の板だ……",
            ["DialogueId"] = 12030610,
            ["GUID"] = "1E1E0BF4",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0BF4",
            },
        [12030615] = {
            ["Content"] = "调查第二处地点",
            ["ContentJP"] = "地点②を調査",
            ["DialogueId"] = 12030615,
            ["GUID"] = "1E1E0CC6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0CC6",
            },
        [12030620] = {
            ["Content"] = "嗯？小姑娘，有啥事吗？",
            ["ContentJP"] = "ん？嬢ちゃん、どうした？",
            ["DialogueId"] = 12030620,
            ["GUID"] = "1E1E0D98",
            ["NextDialogue"] = 12030621,
            ["SpeakNpcId"] = 211016,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0D98",
            },
        [12030621] = {
            ["Content"] = "抱歉，我找错人了……",
            ["ContentJP"] = "ごめんなさい、間違えました……",
            ["DialogueId"] = 12030621,
            ["GUID"] = "1E1E0DC2",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0DC2",
            },
        [12030625] = {
            ["Content"] = "调查第三处地点",
            ["ContentJP"] = "地点③を調査",
            ["DialogueId"] = 12030625,
            ["GUID"] = "1E1E0E6A",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0E6A",
            },
        [12030630] = {
            ["Content"] = "喵~~",
            ["ContentJP"] = "にゃ～ん。",
            ["DialogueId"] = 12030630,
            ["GUID"] = "1E1E0F3C",
            ["NextDialogue"] = 12030631,
            ["SpeakNpcId"] = 211008,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0F3C",
            },
        [12030631] = {
            ["Content"] = "好可爱的小猫……喵喵~~啊，我要找的是烤土豆，差点忘记了！",
            ["ContentJP"] = "かわいい猫ちゃん……にゃんにゃん♪……あっ、いけない！焼きいも探してたんだった！",
            ["DialogueId"] = 12030631,
            ["GUID"] = "1E1E0F66",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E0F66",
            },
        [12030635] = {
            ["Content"] = "彩蛋调查点（放在比较远的某个墙角之类的地方，不挂指引）",
            ["ContentJP"] = "隠し調査ポイント（遠くの壁の隅など、誘導なし）",
            ["DialogueId"] = 12030635,
            ["GUID"] = "1E1E100E",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E100E",
            },
        [12030640] = {
            ["Content"] = "咦？独角兽{性别：先生|小姐}，你怎么在这里呀？",
            ["ContentJP"] = "あれ？ユニコーンの{性别:お兄さん|お姉さん}、どうしてここに？",
            ["DialogueId"] = 12030640,
            ["GUID"] = "1E1E10E0",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E10E0",
            },
        [12030641] = {
            ["Content"] = "啊哈哈……菲娜，你好呀！我、我在这附近散步呢，好巧啊~",
            ["ContentJP"] = "あはは……やあ、フィーナ！えっと、ここら辺をお散歩してたんだ。偶然だね〜",
            ["DialogueId"] = 12030641,
            ["GUID"] = "1E1E110A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E110A",
            },
        [12030642] = {
            ["Content"] = "原来是这样！很高兴见到你，不过，菲娜现在正在玩游戏。下次有机会我们再一起办茶会吧！",
            ["ContentJP"] = "そうだったんだ！会えてうれしいな。でもね、フィーナはいまごっこ遊びの最中なの。また今度、いっしょにお茶会しようね！",
            ["DialogueId"] = 12030642,
            ["GUID"] = "1E1E1134",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1134",
            },
        [12030643] = {
            ["Content"] = "嗯，好呀！",
            ["ContentJP"] = "うん！",
            ["DialogueId"] = 12030643,
            ["GUID"] = "1E1E115E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E115E",
            },
        [12030645] = {
            ["Content"] = "三处调查完毕后",
            ["ContentJP"] = "3か所すべての調査が終わる",
            ["DialogueId"] = 12030645,
            ["GUID"] = "1E1E11B2",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E11B2",
            },
        [12030650] = {
            ["Content"] = "就这样，三分钟过去了……",
            ["ContentJP"] = "こうして、3分が経った――",
            ["DialogueId"] = 12030650,
            ["GUID"] = "1E1E1284",
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1284",
            },
        [12030701] = {
            ["Camera"] = "-360.602539,-341.077148,99.427734,0.000126,-3.59912,46.511829,35.000015,355.657684,false,DoNotOverride,22.0",
            ["Content"] = "嘿嘿，魔法烤土豆赢啦！",
            ["ContentJP"] = "えへへっ、魔法の焼きいもの勝ちー！",
            ["DialogueId"] = 12030701,
            ["FinalCamera"] = "-409.727051,-288.272461,99.427734,0.000127,-3.19909,37.711613,35.000015,355.657684,false,DoNotOverride,22.0",
            ["GUID"] = "1E1E1AE2",
            ["LookAt"] = {
                [1] = "211001:n(211011)",
                },
            ["NextDialogue"] = 12030702,
            ["SpeakNpcId"] = 211011,
            ["TalkActionId"] = {
                [1] = "211011:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1AE2",
            },
        [12030702] = {
            ["Content"] = "三个烤土豆都赢了耶，贪吃鬼肚子空空~",
            ["ContentJP"] = "3人とも見つからなかったもんね！食いしん坊鬼のおなか、ぺっこぺこ～！",
            ["DialogueId"] = 12030702,
            ["GUID"] = "1E1E1B0C",
            ["LookAt"] = {
                [1] = "211001:n(211010)",
                },
            ["NextDialogue"] = 12030703,
            ["SpeakNpcId"] = 211010,
            ["TalkActionId"] = {
                [1] = "211010:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1B0C",
            },
        [12030703] = {
            ["Camera"] = "-131.468262,-22.850586,110.526367,0.000134,4.400882,43.107666,35.000015,355.657684,false,DoNotOverride,22.0",
            ["Content"] = "嗯……是我太笨啦，还是烤土豆们更厉害！",
            ["ContentJP"] = "うぅ……わたしがへたっぴだったのかも。みんなの隠れ方、すっごく上手だったね！",
            ["DialogueId"] = 12030703,
            ["FacialId"] = {
                [1] = "211001:Happy01",
                },
            ["GUID"] = "1E1E1B36",
            ["LookAt"] = {
                [1] = "211001:n(211001)",
                [2] = "211013:n(211001)",
                },
            ["NextDialogue"] = 12030704,
            ["Scripts"] = "SEQ{\
PARA{\
PlayFacial{ActorId{211001},FacialId{\"Disappoint01\"},Duration{1.3}},\
PlayAnimation{ActorId{211001},AnimationId{\"Explain02_Start\"},Duration{1.3}}\
},\
