}",
            ["SpeakNpcId"] = 211001,
            ["TalkActionId"] = {
                [1] = "211010:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1B36",
            },
        [12030704] = {
            ["Camera"] = "-495.039551,-191.916016,131.40332,0.000119,-5.799226,20.708221,35.000015,355.657684,false,DoNotOverride,22.0",
            ["Content"] = "没关系的，菲娜姐姐，我第一次玩的时候也一个烤土豆都没找到……",
            ["ContentJP"] = "大丈夫だよ、フィーナお姉さん。ぼくも最初は、ひとりも見つけられなかったし！",
            ["DialogueId"] = 12030704,
            ["GUID"] = "1E1E1B60",
            ["LookAt"] = {
                [1] = "211001:n(211013)",
                },
            ["NextDialogue"] = 12030705,
            ["Scripts"] = "SEQ{\
PlayFacial{ActorId{211001},FacialId{\"None\"},Duration{1.3}},\
PlayAnimation{_delay{3},ActorId{211013},AnimationId{\"Explain02_Start\"},Duration{1.3}}\
}",
            ["SpeakNpcId"] = 211013,
            ["TalkActionId"] = {
                [1] = "211001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1B60",
            },
        [12030705] = {
            ["Content"] = "对呀对呀，我们再来一局吧，这次你一定能找到的！",
            ["ContentJP"] = "そうそう！もう一回やろうよ！今度はきっと見つけられるよ！",
            ["DialogueId"] = 12030705,
            ["GUID"] = "1E1E1B8A",
            ["LookAt"] = {
                [1] = "211011:n(211001)",
                [2] = "211010:n(211010)",
                [3] = "211001:n(211011)",
                },
            ["NextDialogue"] = 12030706,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{211011},AnimationId{\"Agree\"},Duration{1.5}},\
PlayAnimation{_delay{3},ActorId{211011},AnimationId{\"Confident_Start\"},Duration{3}}\
}",
            ["SpeakNpcId"] = 211011,
            ["VoiceName"] = "voice/$Locale$/story/1201/120111/1E1E1B8A",
            },
        [12030706] = {
            ["Camera"] = "-114.803711,-76.038086,121.975098,0.000119,-0.199209,59.907368,35.000015,355.657684,false,DoNotOverride,22.0",
            ["Content"] = "好，这次我会努力的！",
