            },
        [12030901] = {
            ["Camera"] = "-69.249512,169.701172,119.054199,0.000114,2.200639,-59.584778,35.000011,113.605156,false,DoNotOverride,6.0",
            ["Content"] = "可是，故事里的主人公们总是充满勇气，无论遇到怎样的困难，都会和伙伴们一起克服……",
            ["ContentJP"] = "でも……お話の中の主人公たちは、どんな困難でも、仲間といっしょに乗り越えてた……",
            ["DialogueId"] = 12030901,
            ["GUID"] = "1E1E3BB2",
            ["NextDialogue"] = 12030902,
            ["Scripts"] = "PARA{\
