        [12031202] = {
            ["Camera"] = "-277.675354,150.824219,139.609375,0.000107,-4.396757,-42.767723,35.000015,300.0,false,DoNotOverride,3.0",
            ["Content"] = "今天我认识了三个聪明的新朋友，还和他们一起玩了贪吃鬼的游戏！虽然一开始不太顺利，但是，在我请来了大魔法师之后……",
            ["ContentJP"] = "うん！今日は新しいお友だちが3人できて、「食いしん坊鬼」で遊んだの。最初は全然見つけられなかったけど……でもね、大魔法使いを呼んだら……！",
            ["DialogueId"] = 12031202,
            ["FacialId"] = {
                [1] = "211001:Smile01",
                },
            ["GUID"] = "1E1E6D14",
            ["LookAt"] = {
                [1] = "211001:n(211002)",
                },
            ["NextDialogue"] = 12031203,
            ["Scripts"] = "SEQ{\
