        [12031301] = {
            ["Content"] = "今天是冒险之旅的第二天……菲娜要试着探索新的国度！",
            ["ContentJP"] = "冒険2日目……今日は新しい国に行ってみよう！",
            ["DialogueId"] = 12031301,
