}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8E38",
            },
        [12031405] = {
            ["Camera"] = "-156.79039,1.709183,91.499512,0.000147,7.401883,17.145016,35.000011,278.655243,false,DoNotOverride,2.8",
            ["Content"] = "“冰湖城的市民都知道昙花一现的格伦维尔家族”……咦？！",
            ["ContentJP"] = "「アイスレイク城の住民なら誰もが知ってる、グレンヴィル家の一瞬の栄光」……えっ！？",
            ["DialogueId"] = 12031405,
            ["FinalCamera"] = "-108.686592,16.733475,98.225098,0.000142,7.601891,17.344889,35.000011,130.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E1E8E62",
            ["NextDialogue"] = 12031406,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"Think_Start\"}},\
PlayFacial{_delay{5.01},ActorId{211001},FacialId{\"Shock02\"}},\
CameraMoveTo{_delay{5.01},TargetPosition{\"-96.672791,18.322319,115.384521,0.000154,1.601871,16.545654,35.000011,109.004112,false,DoNotOverride,2.8\"},duration{0}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8E62",
            },
        [12031406] = {
            ["Content"] = "……还好，没有写到妈妈和菲娜的事。“隐秘的往事”是什么意思呢？唔……算啦，这和缄默侦探的案件没有关系，还是当作没看见吧。",
            ["ContentJP"] = "……よかった、ママやフィーナのことは書かれてなかった。「隠された過去」ってどういう意味だろ……うーん、これは物言わぬ探偵の事件とは関係ないよね。見なかったことにしよっと。",
            ["DialogueId"] = 12031406,
            ["GUID"] = "1E1E8E8C",
            ["Scripts"] = "SEQ{\
PARA{\
PlayAnimation{_delay{0},ActorId{211001},AnimationId{\"DisagreeHead\"}},\
PlayFacial{_delay{0.5},ActorId{211001},FacialId{\"Syouganai01\"}}\
},\
PARA{\
PlayAnimation{_delay{3},ActorId{211001},AnimationId{\"Explain02_Start\"}},\
PlayFacial{_delay{3},ActorId{211001},FacialId{\"Disappoint01\"}},\
PlayAnimation{_delay{6},ActorId{211001},AnimationId{\"Explain02_End\"}},\
PlayFacial{_delay{5},ActorId{211001},FacialId{\"Smile01\"}}\
}\
}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8E8C",
            },
        [12031407] = {
            ["Content"] = "菲娜翻开了一张又一张纸片，却始终没有找到线索……",
            ["ContentJP"] = "フィーナは一枚、また一枚と紙切れをめくっていくーーけれど、手がかりは見つからなかった。",
            ["DialogueId"] = 12031407,
            ["GUID"] = "1E1E8EB6",
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8EB6",
            },
        [12031408] = {
            ["Content"] = "回去找玛尔洁",
            ["ContentJP"] = "マギーを探す",
            ["DialogueId"] = 12031408,
            ["GUID"] = "1E1E8EE0",
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E8EE0",
            },
        [12031501] = {
            ["Camera"] = "82.075974,-10.556297,110.049805,0.000183,0.601678,154.418808,35.000011,112.418152,false,DoNotOverride,12.0",
            ["Content"] = "小助手，你回来啦！快看，我又找到了一张带记号的报纸！这张报纸上写着剧院的广告，说不定强盗们的目标就是剧院。",
            ["ContentJP"] = "おかえり、助手！見て見て、またマークつきの新聞を見つけたよ！これ、劇場の広告なんだけど……もしかしたら、あいつらの狙いは劇場かもしれない！",
            ["DialogueId"] = 12031501,
            ["GUID"] = "1E1E9E22",
            ["NextDialogue"] = 12031502,
            ["Scripts"] = "PARA{\
LookAt{_delay{0},LookAtDescription{\"211001:n(211003)\"}},\
PlayFacial{_delay{1},ActorId{211003},FacialId{\"Smile02\"}},\
PlayAnimation{_delay{2},ActorId{211003},AnimationId{\"ConfidentR_Start\"}},\
PlayAnimation{_delay{5},ActorId{211003},AnimationId{\"ConfidentRToExplain_Start\"}},\
PlayAnimation{_delay{8},ActorId{211003},AnimationId{\"ConfidentRToExplain_End\"}}\
}",
            ["SpeakNpcId"] = 211003,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E9E22",
            },
        [12031502] = {
            ["Camera"] = "-100.437286,39.990219,115.680176,0.000186,-1.198357,5.82005,35.000011,112.418152,false,DoNotOverride,12.0",
            ["Content"] = "对不起……我什么也没找到……",
            ["ContentJP"] = "ごめんね……私の方は、何にも見つからなかった……",
            ["DialogueId"] = 12031502,
            ["GUID"] = "1E1E9E4C",
            ["NextDialogue"] = 12031503,
            ["Scripts"] = "PARA{\
