}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E9E4C",
            },
        [12031503] = {
            ["Camera"] = "71.372574,-11.404465,125.61084,0.000183,-5.398342,153.82045,35.000011,112.418152,false,DoNotOverride,12.0",
            ["Content"] = "别灰心呀，小助手！忍受真相的黎明到来之前的漫漫长夜，也是成为一名优秀侦探的必经之路！",
            ["ContentJP"] = "落ち込まないで、助手！真の夜明けが来るまでの「長い夜」に耐えるのも、一流の探偵になるための試練なんだから！",
            ["DialogueId"] = 12031503,
            ["FinalCamera"] = "54.87048,-3.646893,123.887939,0.000183,-3.598328,156.020584,35.000011,112.418152,false,DoNotOverride,12.0",
            ["GUID"] = "1E1E9E76",
            ["NextDialogue"] = 12031504,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{0},ActorId{211003},FacialId{\"Smile02\"}},\
PlayFacial{_delay{3},ActorId{211003},FacialId{\"Confident02\"}},\
PlayAnimation{_delay{1},ActorId{211001},AnimationId{\"Explain02_End\"}},\
SEQ{\
PlayAnimation{_delay{0},ActorId{211003},AnimationId{\"SpecialHoldHelmet_Start\"}},\
PlayAnimation{_delay{2},ActorId{211003},AnimationId{\"SpecialHoldHelmet_End\"}}\
}\
}",
            ["SpeakNpcId"] = 211003,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1E9E76",
            },
        [12031504] = {
            ["Camera"] = "-303.668518,36.957611,131.155273,0.000187,-3.798767,9.824474,35.000015,112.418152,false,DoNotOverride,12.0",
            ["Content"] = "唔……就像，魔女小姐必须炸掉一百个亮晶晶的玻璃瓶，才能找出神奇魔药的配方吗？",
            ["ContentJP"] = "うーん……つまり、魔女さんがピカピカのビンを100個も爆破しないと、魔法薬のレシピが見つからないのと同じ？",
