            },
        [12031702] = {
            ["Content"] = "我来把它拼起来看看……啊，这不是缄默侦探说的记号吗！",
            ["ContentJP"] = "ちょっと繋げてみよっと――あっ！これって、物言わぬ探偵が言ってた「マーク」じゃない！？",
            ["DialogueId"] = 12031702,
            ["GUID"] = "1E1EBF1C",
            ["NextDialogue"] = 12031703,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1EBF1C",
            },
        [12031703] = {
            ["Camera"] = "172.084702,-47.944427,125.723877,0.000155,-8.597767,137.546112,35.000008,250.932434,false,DoNotOverride,4.792607",
            ["Content"] = "独角兽{性别：先生|小姐}，你竟然真的发现了线索，好厉害！谢谢你！",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}、すごい！ほんとに見つけてくれたんだね。ありがとう！",
            ["DialogueId"] = 12031703,
            ["GUID"] = "1E1EBF46",
            ["NextDialogue"] = 12031704,
            ["Scripts"] = "SEQ{\
LookAt{_delay{0},LookAtDescription{\"211001:n(211006)\"}},\
