}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1EBF46",
            },
        [12031704] = {
            ["Content"] = "咴~",
            ["ContentJP"] = "ヒヒ〜ン♪",
            ["DialogueId"] = 12031704,
            ["GUID"] = "1E1EBF70",
            ["NextDialogue"] = 12031705,
            ["SpeakNpcId"] = 211006,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/1E1EBF70",
            },
        [12031705] = {
            ["Camera"] = "128.401428,-39.504219,87.245117,0.000162,5.202166,114.146538,35.000008,221.916321,false,DoNotOverride,4.792607",
            ["Content"] = "不过，这张画到底是什么意思呢？这个黄色的三角形图案为什么在这里……唔，还是拿去给缄默侦探阁下看看吧。",
            ["ContentJP"] = "でも、この絵……なんだろう？黄色い三角形のマーク……なんでこんなところに？うーん、とにかく、物言わぬ探偵に見てもらおう！",
            ["DialogueId"] = 12031705,
            ["FinalCamera"] = "114.89032,-9.031448,91.333008,0.000164,6.60217,113.746613,35.000008,133.916702,false,DoNotOverride,4.792607",
            ["GUID"] = "1E1EBF9A",
