            ["GUID"] = "1E1EE30C",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 211001,
            },
        [12032001] = {
            ["Content"] = "今天天气真好呀~是适合冒险的日子！",
