            },
        [12032002] = {
            ["Content"] = "前往冰湖城广场，在贫民窟入口处触发剧情",
            ["DialogueId"] = 12032002,
            ["GUID"] = "1E1EF054",
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/1E1EF054",
