        [12032023] = {
            ["Camera"] = "112.474983,29.235161,104.275879,0.00011,2.399992,175.923996,35.000011,175.784409,false,Manual,2.8",
            ["Content"] = "太好了——呃……咳！听好了，卡戎人，我需要你帮我做件事。放心，不难的，只要你按我说的用一下魔法就行。",
            ["ContentJP"] = "それならちょうどいいわ！――あ、いや、ゴホン！よく聞きなさい、カロン。ちょっと魔法を使ってもらいたいの。たいしたことじゃないでしょ。",
            ["DialogueId"] = 12032023,
