            ["Content"] = "我也帮忙一起找。",
            ["ContentJP"] = "私も手伝うわ。",
            ["DialogueId"] = 12033301,
            ["GUID"] = "1E1FC572",
            ["NextDialogue"] = 12033302,
            ["Scripts"] = "PARA{\
