        [12033419] = {
            ["Camera"] = "-312.716248,-126.369667,120.318848,0.00011,-1.122282,47.925896,35.000011,246.67305,false,DoNotOverride,12.0",
            ["Content"] = "呜……算了，城外我们确实不熟，看来只能提前出局啦。",
            ["ContentJP"] = "むぅ……しょうがないね。城外は確かに知らないし、今回はパスってことにするよ。",
            ["DialogueId"] = 12033419,
            ["GUID"] = "1E1FD8CE",
