            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FD94C",
            },
        [12033423] = {
            ["Camera"] = "-180.779297,226.290405,147.938721,0.000153,-7.32199,-70.676788,35.000011,183.042328,false,DoNotOverride,6.0",
            ["Content"] = "嗯，当然了！",
            ["ContentJP"] = "うん、もちろん！",
            ["DialogueId"] = 12033423,
            ["FinalCamera"] = "-160.119675,227.610596,139.820312,0.000149,-3.92199,-79.276695,35.000011,183.042328,false,DoNotOverride,6.0",
