            ["Content"] = "等等，那边地上的是……",
            ["ContentJP"] = "あれ……あそこに落ちてるのは……？",
            ["DialogueId"] = 12033601,
            ["FinalCamera"] = "1271.21228,296.156647,52.055664,0.000115,-6.200315,-148.689377,35.000015,267.529114,false,Manual,8.0",
