            },
        [12033602] = {
            ["Content"] = "好像是一枚银币？",
            ["ContentJP"] = "これ、銀貨……？",
            ["DialogueId"] = 12033602,
            ["GUID"] = "1E1FF6D4",
            ["NextDialogue"] = 12033603,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF6D4",
            },
        [12033603] = {
            ["Camera"] = "234.363953,-50.952301,24.949219,0.000154,-4.399441,4.909956,35.000015,244.392456,false,Manual,10.0",
            ["Content"] = "不，这是硬纸板，只是涂成了银币的颜色……这是之前我们玩游戏的时候，塞维欧亲手做的道具！",
            ["ContentJP"] = "いや、違う。厚紙に銀色を塗っただけよ……！これは……この前のごっこ遊びで、セヴィオが自分で作った小道具だわ……！",
            ["DialogueId"] = 12033603,
            ["FinalCamera"] = "253.116959,-20.29356,23.308594,0.000155,-4.399441,4.909863,35.000015,244.392456,false,Manual,10.0",
            ["GUID"] = "1E1FF6FE",
            ["NextDialogue"] = 12033604,
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF6FE",
            },
        [12033604] = {
            ["Camera"] = "620.08136,271.415924,29.961914,0.000183,-8.999266,-35.888649,35.000023,354.210571,false,Manual,10.0",
            ["Content"] = "他那么细心，绝对不会把这么重要的东西丢在地上的。他该不会……该不会是出了什么事吧……呜呜……",
            ["ContentJP"] = "あの子がこんな大事なものを、うっかり落とすはずがない。まさか……なにかあったんじゃ……っ。",
            ["DialogueId"] = 12033604,
            ["FinalCamera"] = "640.950745,256.320587,25.977539,0.000182,-8.799243,-35.888645,35.000023,354.210571,false,Manual,10.0",
            ["GUID"] = "1E1FF728",
            ["NextDialogue"] = 12033605,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"211012:n(100001)\"}},\
LookAt{LookAtDescription{\"100001:n(211012)\"}},\
LookAt{LookAtDescription{\"211001:n(100001)\"}},\
PlayAnimation{_dalay{3},ActorId{211012},AnimationId{\"Talk02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211012:p(-60)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF728",
            },
        [12033605] = {
            ["Camera"] = "751.478516,230.02742,-0.833008,0.000126,1.799482,-67.086746,28.0,267.67627,false,Manual,2.8",
            ["Content"] = "啊——！我想起来了，缄默侦探阁下说过，她在追查的那伙强盗是专门绑架小孩子的……",
            ["ContentJP"] = "あっ……！思い出した！あのとき、物言わぬ探偵が言ってたの！今追ってる盗賊団、子どもをさらう連中だって――！",
            ["DialogueId"] = 12033605,
            ["FinalCamera"] = "753.482544,225.280487,-0.672852,0.000128,1.799482,-67.086746,28.0,267.67627,false,Manual,2.8",
            ["GUID"] = "1E1FF752",
            ["NextDialogue"] = 12033606,
            ["Scripts"] = "\
PARA{\
CameraMoveTo{_delay{2},TargetPosition{\"733.204773,47.31937,-5.9375,0.000039,15.199123,-64.687424,35.000011,144.720703,false,Manual,2.8\"},duration{0}},\
