",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "211001:p(-60)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E1FF752",
            },
        [12033606] = {
            ["Camera"] = "1012.578003,-274.137573,18.267578,0.00017,-1.801906,125.509743,35.0,294.264496,false,Manual,2.8",
            ["Content"] = "呜哇，强、强盗？！塞维欧被强盗抓走了吗？",
            ["ContentJP"] = "ええっ、と、盗賊！？セヴィオが、さらわれたってこと……！？",
            ["DialogueId"] = 12033606,
            ["FinalCamera"] = "1000.873535,-257.73819,17.636719,0.00017,-1.801906,125.509743,35.0,294.264496,false,Manual,2.8",
