                [2] = "\
211001:n(100001)",
                },
            ["NextDialogue"] = 12034102,
            ["Scripts"] = "TurnTo{_delay{1},TurnToDescription{\"100001:n(211012)\"}}",
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2048B2",
            },
        [12034102] = {
            ["Camera"] = "986.973083,1585.42395,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeOutQuad",
            ["Content"] = "嗯……？这些强盗……已经被制服了？",
            ["ContentJP"] = "ん……？なんだ、盗賊たち完全にのびてるじゃないか。",
            ["DialogueId"] = 12034102,
            ["FinalCamera"] = "977.238586,1591.515625,715.091797,0.00005,-23.758293,-121.993103,35.0,1732.474731,false,Manual,1.2",
            ["GUID"] = "1E2048DC",
            ["NextDialogue"] = 12034103,
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2048DC",
            },
        [12034103] = {
            ["Camera"] = "483.208221,510.672333,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "是的，我们是卡珊德拉小姐雇佣的狩月人，已经把强盗打倒了。",
            ["ContentJP"] = "はい。{性别:僕|私}たちはカサンドラさんに雇われた月狩り人です。盗賊は、すでに倒しました。",
            ["DialogueId"] = 12034103,
            ["FinalCamera"] = "486.036987,505.621124,132.758789,0.000056,-4.557485,-150.607956,50.0,557.577881,false,Manual,8.0",
            ["GUID"] = "1E204906",
            ["NextDialogue"] = 12034104,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{100001},TargetPoint{\"Feina_FixSimple38_nvzhuMove1\"},MoveSpeed{40},Visibility{\"Show\"}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain01L_Start\"},Duration{1}}\
\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E204906",
            },
        [12034104] = {
            ["Camera"] = "229.517212,445.407562,72.137695,-0.0,16.841286,-9.204861,50.0,173.055267,false,Manual,8.0",
            ["Content"] = "是吗？",
            ["ContentJP"] = "……そうなのか？",
            ["DialogueId"] = 12034104,
            ["GUID"] = "1E204930",
            ["NextDialogue"] = 12034105,
            ["Scripts"] = "PlayAnimation{ActorId{100001},AnimationId{\"Explain01L_End\"},Duration{1}}",
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E204930",
            },
        [12034105] = {
            ["Camera"] = "-876.449036,601.317261,201.322266,0.000065,-11.157715,-19.005154,30.0,173.055267,false,DoNotOverride,8.0",
            ["Content"] = "没错没错，他们俩都是我雇的人，不是可疑人物！",
            ["ContentJP"] = "そうそう、この二人はあたしの雇った人よ！ぜんっぜん怪しくなんかないから！",
            ["DialogueId"] = 12034105,
            ["FinalCamera"] = "-876.449036,601.317261,217.300781,0.000066,-10.35766,-19.005308,30.0,173.055267,false,DoNotOverride,8.0",
            ["GUID"] = "1E20495A",
            ["NextDialogue"] = 12034106,
            ["SpeakNpcId"] = 211012,
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "211012:p(-180)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20495A",
            },
        [12034106] = {
            ["Camera"] = "-261.812439,310.25946,99.939453,0.000086,-2.357686,-2.005544,35.0,688.037964,false,Manual,4.0",
            ["Content"] = "……好吧，那我们就把这些强盗带走了。",
            ["ContentJP"] = "……わかった。では、こいつらの身柄はこっちで引き取らせてもらう。",
            ["DialogueId"] = 12034106,
            ["FinalCamera"] = "-261.654846,314.867767,99.939453,0.000086,-2.357686,-1.605461,35.0,688.037964,false,Manual,4.0",
            ["GUID"] = "1E204984",
