            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 4.5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E204984",
            },
        [12034107] = {
            ["Camera"] = "199.814636,389.031067,112.981445,0.000071,1.842389,7.599753,50.0,198.341919,false,Manual,5.0",
            ["Content"] = "之前有个臭捡垃圾的卡戎一直来署里吵着说什么泪湖有强盗，还以为她是瞎编的，没想到居然是真的……",
            ["ContentJP"] = "前に変なカロンの女が署に来て、「ダクリ湖に盗賊がいる」って大騒ぎしてたんだが……まさか本当だったとはな。",
            ["DialogueId"] = 12034107,
            ["FinalCamera"] = "199.727524,389.644745,112.981445,0.000072,2.04239,8.399999,55.0,198.341919,false,Manual,5.0",
            ["GUID"] = "1E2049AE",
            ["SpeakNpcName"] = "UI_FNNpc_Name_SoldierPSD",
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2049AE",
            },
        [12034108] = {
            ["Content"] = "转场，帝国兵和强盗消失",
            ["ContentJP"] = "帝国兵とともに盗賊たちが連行された。\
カサンドラと話そう",
            ["DialogueId"] = 12034108,
            ["GUID"] = "1E2049D8",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2049D8",
            },
        [12034201] = {
            ["Camera"] = "87.895348,214.805466,327.84668,0.000057,-19.94603,160.421906,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "卡珊德拉……是你让他们来找我的吗？",
            ["ContentJP"] = "カサンドラ……彼らを呼んでくれたの、君なの？",
            ["DialogueId"] = 12034201,
            ["FinalCamera"] = "82.289337,199.953339,327.84668,0.000058,-19.546021,158.621765,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E20591A",
            ["LookAt"] = {
                [1] = "100001:n(211012)",
                [2] = "\
211001:n(211012)",
                },
            ["NextDialogue"] = 12034202,
            ["SpeakNpcId"] = 211015,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20591A",
            },
        [12034202] = {
            ["Camera"] = "-942.397278,-54.10989,181.074219,0.000047,-11.546441,59.81805,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "当然了，不是我还能是谁？你为什么要跑到城外来呀，吓死我了！",
            ["ContentJP"] = "当たり前でしょ！他に誰がいるのよ。あんた、なんで城の外なんかに出たのよ、心配したんだから！",
            ["DialogueId"] = 12034202,
            ["FinalCamera"] = "-947.833069,-50.950378,181.074219,0.000047,-11.546441,59.81805,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E205944",
            ["NextDialogue"] = 12034203,
            ["SpeakNpcId"] = 211012,
            ["TalkActionId"] = {
                [1] = "211012:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205944",
            },
        [12034203] = {
            ["Camera"] = "-317.916473,488.004974,97.504883,0.000046,-2.946106,-178.584473,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……我还以为你也不想跟我玩了。如果谁都不想看见我，那我还不如不回学校了……",
            ["ContentJP"] = "……もう、君も僕と遊びたくないのかと思った。誰にも会いたくなかったから、学校にも戻りたくなくて……",
            ["DialogueId"] = 12034203,
            ["FinalCamera"] = "-317.916473,488.004974,90.661133,0.000046,-3.146053,-178.384689,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E20596E",
            ["NextDialogue"] = 12034204,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211012:Confident_End",
                [2] = "\
211015:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 13,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20596E",
            },
        [12034204] = {
            ["Camera"] = "-896.072571,82.03035,63.115234,0.00007,-0.346345,57.812359,50.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说什么傻话呢，我们是朋友啊！你再把我想得和那些坏小孩一样，我可是会生气——啊，你受伤了吗？！",
            ["ContentJP"] = "バカなこと言わないで！あたしたち、友達でしょ！？そんなこと言うなら怒るわよ……って、ちょっと、ケガしてるじゃない！",
            ["DialogueId"] = 12034204,
            ["FinalCamera"] = "-890.340332,78.4217,63.115234,0.00007,-0.346345,57.811806,50.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "1E205998",
            ["NextDialogue"] = 12034205,
            ["Scripts"] = "PlayAnimation{_delay{11},ActorId{211012},AnimationId{\"Angry01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 211012,
            ["TalkActionId"] = {
                [1] = "211015:Sigh_End",
                [2] = "\
211012:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205998",
            },
        [12034205] = {
            ["Camera"] = "-405.626709,506.263672,87.52832,0.000071,-1.545767,-172.392715,50.0,285.715515,false,Manual,8.0",
            ["Content"] = "没事的，只是一点擦伤。谢谢你，卡珊德拉。",
            ["ContentJP"] = "大丈夫、かすり傷だよ。ありがとう、カサンドラ。",
            ["DialogueId"] = 12034205,
            ["GUID"] = "1E2059C2",
            ["NextDialogue"] = 12034206,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211015:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2059C2",
            },
        [12034206] = {
            ["Camera"] = "151.844269,80.657501,37.138672,0.000095,1.654081,151.40625,50.0,940.830017,false,Manual,8.0",
            ["Content"] = "多亏了你，我不仅得救了，而且……我终于找到蝴蝶精灵了。",
            ["ContentJP"] = "君のおかげで助かったし……それに、ようやく見つけたんだ。あの頃の「蝶の精霊」を。",
            ["DialogueId"] = 12034206,
            ["FinalCamera"] = "149.475693,76.349304,37.138672,0.000096,1.654081,150.606277,50.0,940.830017,false,Manual,8.0",
            ["GUID"] = "1E2059EC",
            ["NextDialogue"] = 12034207,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211015:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E2059EC",
            },
        [12034207] = {
            ["Camera"] = "-899.9151,108.874062,146.229492,0.000112,-9.546234,55.209587,50.0,552.772644,false,DoNotOverride,8.0",
            ["Content"] = "喔，那真是太好了！等回到学校，你一定要给我好好讲讲。",
            ["ContentJP"] = "ほんと！？よかった！帰ったら、ぜーったい詳しく聞かせてね！",
            ["DialogueId"] = 12034207,
            ["FinalCamera"] = "-899.9151,108.874062,133.772461,0.000113,-8.146189,54.209774,50.0,552.772644,false,DoNotOverride,8.0",
            ["GUID"] = "1E205A16",
            ["NextDialogue"] = 12034208,
            ["SpeakNpcId"] = 211012,
            ["TalkActionId"] = {
                [1] = "211015:Explain02_End",
                [2] = "\
211012:Agree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205A16",
            },
        [12034208] = {
            ["Content"] = "嗯！",
            ["ContentJP"] = "うん！",
            ["DialogueId"] = 12034208,
            ["GUID"] = "1E205A40",
            ["NextDialogue"] = 12034209,
            ["SpeakNpcId"] = 211015,
            ["TalkActionId"] = {
                [1] = "211015:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E205A40",
            },
        [12034209] = {
            ["Camera"] = "-690.500427,676.570496,85.366211,0.000123,0.853248,-66.382408,40.0,552.772644,false,DoNotOverride,8.0",
            ["Content"] = "菲娜，{nickname}{性别：哥哥|姐姐}，谢谢你们救了我的朋友！",
            ["ContentJP"] = "フィーナ、{nickname}{性别:お兄さん|お姉さん}、あたしの大切な友だちを助けてくれて、本当にありがとう！",
            ["DialogueId"] = 12034209,
            ["FinalCamera"] = "-706.813965,669.448181,85.366211,0.000124,1.053249,-65.382294,40.0,552.772644,false,DoNotOverride,8.0",
            ["GUID"] = "1E205A6A",
            ["NextDialogue"] = 12034210,
            ["Scripts"] = "PARA{\
