        [12034505] = {
            ["Content"] = "转场，菲娜和塞维欧站在房间里，菲娜的床上摆放白鸟玩偶",
            ["DialogueId"] = 12034505,
            ["GUID"] = "1E208AFA",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E208AFA",
            },
        [12034601] = {
            ["Camera"] = "222.182312,78.296875,125.328125,0.000062,1.812971,58.197723,35.000011,70.022163,false,DoNotOverride,2.8",
            ["Content"] = "是白鸟先生……！",
            ["ContentJP"] = "……白鳥さん……！",
            ["DialogueId"] = 12034601,
            ["GUID"] = "1E209ABA",
            ["NextDialogue"] = 12034602,
            ["Scripts"] = "SEQ{\
