}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209B0E",
            },
        [12034604] = {
            ["Content"] = "菲娜姐姐……我现在想起来了，你在我们的家里总是不太开心。现在的这个家呢，你在这里开心吗？",
            ["ContentJP"] = "僕……思い出したんだ。昔のおうちで、あんまり楽しそうじゃなかったよね。今のおうちは……楽しい？",
            ["DialogueId"] = 12034604,
            ["GUID"] = "1E209B38",
            ["NextDialogue"] = 12034605,
            ["Scripts"] = "PlayAnimation{_delay{4.5},ActorId{211001},AnimationId{\"Explain02_End\"}}",
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E209B38",
            },
        [12034605] = {
