            ["Content"] = "当然可以，因为，我们是朋友呀。",
            ["ContentJP"] = "もちろんだよ。だって、私たち……もう友だちだもん。",
            ["DialogueId"] = 12034607,
            ["FinalCamera"] = "143.822983,-105.402344,95.390625,0.00015,6.012875,55.007545,35.000015,262.416931,false,DoNotOverride,3.5",
