        [12034608] = {
            ["Content"] = "菲娜，菲娜！我们也来咯！",
            ["ContentJP"] = "フィーナ！あたしたちも来たわよー！",
            ["DialogueId"] = 12034608,
            ["GUID"] = "1E209BE0",
            ["SpeakNpcId"] = 211012,
