            ["bAllowClickSkipScript"] = false,
            },
        [12034705] = {
            ["Camera"] = "-133.212585,185.379044,127.350098,0.000116,-4.629789,-85.284157,35.0,173.365967,false,Manual,2.799999",
            ["Content"] = "独角兽{性别：先生|小姐}……你还记得小夜莺的故事吗？",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}……小さなナイチンゲールのお話、覚えてる？",
            ["DialogueId"] = 12034705,
            ["FinalCamera"] = "-131.751953,167.669998,125.972656,0.000117,-4.42978,-85.28421,35.0,152.132278,false,Manual,2.799999",
            ["GUID"] = "1E20ABCA",
            ["NextDialogue"] = 12034706,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_Start\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Sad01\"}},\
LookAt{LookAtDescription{\"211001:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ABCA",
            },
        [12034706] = {
            ["Camera"] = "-133.403595,189.181717,129.325195,0.000126,-3.629699,-86.884636,55.000008,157.409622,false,Manual,2.8",
            ["Content"] = "为了在自由的世界里活下去、为了保护新的家人，小夜莺鼓起勇气，啄走了野兽的心脏……可它当时并没有想到，这样做也会让无辜的小兽失去家人。",
            ["ContentJP"] = "自由な世界で生きるために、家族を守るために、小さなナイチンゲールは勇気を出して、野獣の心臓をくちばしで奪ったの……でもそのせいで、無実の小さな獣が家族を失うことになっちゃった。",
            ["DialogueId"] = 12034706,
            ["FinalCamera"] = "-132.252869,168.031204,127.981934,0.000126,-3.629699,-86.884636,55.000008,146.218048,false,Manual,2.8",
            ["GUID"] = "1E20ABF4",
            ["NextDialogue"] = 12034707,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{211001},AnimationId{\"Shy01_End\"},Duration{1}},\
PlayFacial{ActorId{211001},FacialId{\"Sad01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ABF4",
            },
        [12034707] = {
            ["Camera"] = "-152.890121,280.265839,135.861328,0.000102,-5.429713,-95.086906,28.0,289.881348,false,Manual,2.8",
            ["Content"] = "塞维欧，他还不知道……都是因为我，他才会失去爸爸妈妈。如果他知道了，他是不是就会讨厌我了？",
            ["ContentJP"] = "セヴィオは、まだ知らないの……全部、フィーナのせいで、あの子はパパとママを失ったんだってこと。もし知ったら……きっと、私のこと、嫌いになるよね……？",
            ["DialogueId"] = 12034707,
            ["FinalCamera"] = "-152.054337,290.041656,136.793945,0.000102,-5.42972,-94.886803,28.0,289.881348,false,Manual,2.8",
            ["GUID"] = "1E20AC1E",
            ["NextDialogue"] = 12034708,
            ["Scripts"] = "\
PlayAnimation{ActorId{211001},AnimationId{\"Shy02_Start\"},Duration{1}}\
",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AC1E",
            },
        [12034708] = {
            ["Camera"] = "-54.464836,-58.781464,137.340332,0.000137,-3.229825,122.725037,55.000019,280.639313,false,Manual,2.8",
            ["Content"] = "菲娜还记得我刚才给塞维欧讲的那个故事吗？我认为，虽然小夜莺啄去了野兽的心脏，但真正引来了这一切悲剧的，是那个<H>看不见的怪物</>。",
            ["ContentJP"] = "さっき{性别:僕|私}がセヴィオに話した物語、覚えてる？小さなナイチンゲールが心臓を奪ったことが全ての始まり……でも、本当に悲劇を引き起こしたのは、<H>見えない怪物</>{性别:だ|よ}。",
            ["DialogueId"] = 12034708,
            ["FinalCamera"] = "-65.446648,-41.691383,136.194824,0.000137,-3.229825,122.725037,55.000019,265.368195,false,Manual,2.8",
            ["GUID"] = "1E20AC48",
            ["NextDialogue"] = 12034709,
            ["Scripts"] = "PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayFacial{ActorId{100001},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AC48",
            },
        [12034709] = {
            ["Content"] = "如果塞维欧听懂了我的故事，那么等他知道真相的时候，他一定也会明白，发生在他爸爸妈妈身上的事并不是菲娜的错。",
            ["ContentJP"] = "セヴィオがその意味を理解してくれてたら……きっと、真実を知っても、パパとママのことをフィーナのせいだとは思わないはずだよ。",
            ["DialogueId"] = 12034709,
            ["GUID"] = "1E20AC72",
            ["NextDialogue"] = 12034710,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk03ToThink_Start\"},Duration{1}},\
PlayFacial{ActorId{100001},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AC72",
            },
        [12034710] = {
            ["Camera"] = "-89.602119,72.514511,130.676758,0.000117,-1.429961,130.515015,35.0,135.543976,false,Manual,2.8",
            ["Content"] = "不过啊，现在你们都还小，只要好好吃饭，按时睡觉，快快乐乐举办茶会就好了。这些复杂的事情，还是长大再去想吧。",
            ["ContentJP"] = "でもね、今はまだ、みんな子どもだから。しっかりごはん食べて、ちゃんと寝て、楽しくお茶会を開けば、それでいい。むずかしいことは、大人になってから考えよう。",
            ["DialogueId"] = 12034710,
            ["FinalCamera"] = "-98.979286,83.485565,130.317871,0.000119,-1.429961,130.514984,35.000008,135.543976,false,Manual,2.8",
            ["GUID"] = "1E20AC9C",
            ["NextDialogue"] = 12034711,
            ["Scripts"] = "PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AC9C",
            },
        [12034711] = {
            ["Camera"] = "-128.947433,25.479841,130.805176,0.000126,-0.629784,109.314728,55.0,161.758026,false,Manual,1.4",
            ["Content"] = "等到必须要面对真相的那一天，我会陪着菲娜一起的。",
            ["ContentJP"] = "そのときが来たら、{性别:僕|私}が一緒にいるから。",
            ["DialogueId"] = 12034711,
            ["FinalCamera"] = "-135.851639,45.178505,130.649414,0.000126,-0.429776,109.314743,55.0,143.136322,false,Manual,1.4",
            ["GUID"] = "1E20ACC6",
            ["NextDialogue"] = 12034712,
            ["Scripts"] = "\
PARA{\
PlayAnimation{ActorId{100001},AnimationId{\"Talk02R_Start\"},Duration{1}},\
PlayFacial{_delay{4.5},ActorId{100001},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ACC6",
            },
        [12034712] = {
            ["Camera"] = "-171.437988,175.135666,121.905762,0.000136,-1.629813,-72.084328,55.000008,167.31073,false,Manual,1.4",
            ["Content"] = "……嗯，一言为定！谢谢你，独角兽{性别：先生|小姐}。",
            ["ContentJP"] = "うん、約束ね、ユニコーンの{性别:お兄さん|お姉さん}！",
            ["DialogueId"] = 12034712,
            ["FinalCamera"] = "-164.531647,153.772919,121.268555,0.000136,-1.629813,-72.084328,55.000008,142.088089,false,Manual,1.4",
