            ["TurnTo"] = {
                [1] = "211001:p(-70)",
                },
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AD1A",
            },
        [12034714] = {
            ["Content"] = "来了来了。",
            ["ContentJP"] = "はいはい、今行くよ。",
            ["DialogueId"] = 12034714,
            ["GUID"] = "1E20AD44",
            ["NextDialogue"] = 12034715,
