        [12034716] = {
            ["Camera"] = "404.343994,-127.544922,169.554688,0.000054,-7.335021,141.091019,28.0,100000.0,false,Manual,22.0",
            ["Content"] = "菲娜，我回来——呜哇……？！怎、怎么这么多小孩？",
            ["ContentJP"] = "フィーナ、ただいまー……うわっ！？な、なぜガキがこんなに！？",
            ["DialogueId"] = 12034716,
            ["GUID"] = "1E20AD98",
