            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AD98",
            },
        [12034717] = {
            ["Content"] = "你回来得正好，快来加入菲娜的茶会吧，大魔法狗，啊，不对，大魔法师。",
            ["ContentJP"] = "ナイスタイミング！フィーナのお茶会に参加しなよ、大魔法ワンコ……じゃなくて、大魔法使いさん。",
            ["DialogueId"] = 12034717,
            ["GUID"] = "1E20ADC2",
