        [12034718] = {
            ["Content"] = "你故意的吧！",
            ["ContentJP"] = "わざとだろ、それ！",
            ["DialogueId"] = 12034718,
            ["GUID"] = "1E20ADEC",
            ["NextDialogue"] = 12034719,
            ["Scripts"] = "PlayAnimation{ActorId{211002},AnimationId{\"Sigh_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20ADEC",
            },
        [12034719] = {
            ["Content"] = "奥特赛德，你回来啦！他们都是菲娜的新朋友，让我来给你介绍吧！",
            ["ContentJP"] = "アウトサイダー、おかえりなさい！この子たちはフィーナの新しいお友だちよ。紹介するね！",
            ["DialogueId"] = 12034719,
            ["GUID"] = "1E20AE16",
            ["Scripts"] = "PARA{\
