            },
        [12034720] = {
            ["Content"] = "下面这段茶会剧情希望能用动画的形式制作，但并不需要额外动作资源，打一个慢慢移动的全景镜头，五个角色站在一起做说话动作即可（效果不好的话也可以打空镜头放个暖色灯光）\
角色台词不显示在对话框里，作为背景音播放，每两句一组",
            ["DialogueId"] = 12034720,
            ["GUID"] = "1E20AE40",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20AE40",
            },
        [12034801] = {
            ["Content"] = "大魔法狗是什么？",
            ["ContentJP"] = "大魔法ワンコってなに？",
            ["DialogueId"] = 12034801,
            ["GUID"] = "1E20BB8A",
            ["NextDialogue"] = 12034802,
            ["SpeakNpcId"] = 211012,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BB8A",
            },
        [12034802] = {
            ["Content"] = "是大魔法师哦。",
            ["ContentJP"] = "大魔法使いのことだよ。",
            ["DialogueId"] = 12034802,
            ["GUID"] = "1E20BBB4",
            ["NextDialogue"] = 12034803,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BBB4",
            },
        [12034803] = {
            ["Content"] = "咳、咳……",
            ["ContentJP"] = "けほっ、けほっ……",
            ["DialogueId"] = 12034803,
            ["GUID"] = "1E20BBDE",
            ["NextDialogue"] = 12034804,
            ["SpeakNpcId"] = 211015,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BBDE",
            },
        [12034804] = {
            ["Content"] = "没事吧？快喝点水——",
            ["ContentJP"] = "大丈夫？ほら、お水飲んで。",
            ["DialogueId"] = 12034804,
            ["GUID"] = "1E20BC08",
            ["NextDialogue"] = 12034805,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC08",
            },
        [12034805] = {
            ["Content"] = "啾啾，白鸟先生！",
            ["ContentJP"] = "ちゅんちゅん！白鳥さん！",
            ["DialogueId"] = 12034805,
            ["GUID"] = "1E20BC32",
            ["NextDialogue"] = 12034806,
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC32",
            },
        [12034806] = {
            ["Content"] = "嚯，好肥美……",
            ["ContentJP"] = "おぉ……ふっくらしててうまそう……",
            ["DialogueId"] = 12034806,
            ["GUID"] = "1E20BC5C",
            ["SpeakNpcId"] = 211002,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC5C",
            },
        [12034807] = {
            ["Content"] = "转场，茶会结束后，菲娜一个人坐在家里",
            ["DialogueId"] = 12034807,
            ["GUID"] = "1E20BC86",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20BC86",
            },
        [12034901] = {
            ["Camera"] = "-16.293289,323.111328,136.453125,0.000086,-7.199647,126.990501,35.0,69.843971,false,DoNotOverride,12.0",
            ["Content"] = "小夜莺飞出自己的巢穴，向未知的世界出发冒险……一路上，小夜莺见到了可爱的魔法烤土豆、机灵的缄默侦探阁下，还有许许多多的新朋友……",
            ["ContentJP"] = "小さなナイチンゲールは、自分の巣を飛び立って、知らない世界へ冒険に出ました……。その道中で、小さなナイチンゲールはかわいい魔法の焼き芋に、すばしっこい物言わぬ探偵、それからたくさんの新しい友だちに出会いました。",
            ["DialogueId"] = 12034901,
            ["FinalCamera"] = "-29.425766,297.828125,134.542969,0.000094,-5.599942,111.788467,35.0,90.44413,false,DoNotOverride,12.0",
            ["GUID"] = "1E20CBF2",
            ["NextDialogue"] = 12034902,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{8.01},TargetPosition{\"-42.475677,435.521484,112.582031,0.000114,6.399675,-88.810791,35.0,244.499649,false,DoNotOverride,12.0\"},duration{0}},\
CameraMoveTo{_delay{8.01},TargetPosition{\"-44.494888,523.302734,101.164062,0.000112,9.799627,-88.410698,35.0,244.499649,false,DoNotOverride,12.0\"},duration{12}},\
PARA{\
PlayFacial{_delay{2.5},ActorId{211001},FacialId{\"Smile01\"}}\
}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CBF2",
            },
        [12034902] = {
            ["Camera"] = "65.885368,364.457031,142.957031,0.000107,-13.200897,166.389648,35.0,111.809486,false,DoNotOverride,12.0",
            ["Content"] = "小夜莺不再害怕坏巫师，也不再担心被野兽追捕了。",
            ["ContentJP"] = "もう悪い魔女も怖くないし、野獣に追いかけられる心配もありません。",
            ["DialogueId"] = 12034902,
            ["GUID"] = "1E20CC1C",
            ["NextDialogue"] = 12034903,
            ["Scripts"] = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 211001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC1C",
            },
        [12034903] = {
            ["Camera"] = "-31.965088,301.212891,134.277344,0.000101,-7.000998,109.790298,35.0,90.981918,false,DoNotOverride,12.0",
            ["Content"] = "因为，现在它知道，无论外面的世界多么阴森可怕……只要和朋友们手拉着手，就总能围出一个彩色的梦。",
            ["ContentJP"] = "だって、彼女にはわかっているのです。どんなに外の世界が暗くてこわくても……みんなと手をつないでいれば、きっとどこにだって虹色の夢を咲かせられると――",
            ["DialogueId"] = 12034903,
            ["FinalCamera"] = "-35.076675,309.947266,133.269531,0.000102,-5.800961,109.79023,35.0,70.654915,false,DoNotOverride,12.0",
            ["GUID"] = "1E20CC46",
            ["Scripts"] = "PARA{\
PlayFacial{_delay{2.5},ActorId{211001},FacialId{\"Satisfy01\"}},\
PlayFacial{_delay{5.5},ActorId{211001},FacialId{\"Smile02\"}},\
PlayFacial{_delay{8.5},ActorId{211001},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 211001,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC46",
            },
        [12034904] = {
            ["Content"] = "解锁并完成玩法第四关",
            ["ContentJP"] = "第四ステージ解放・クリア",
            ["DialogueId"] = 12034904,
            ["GUID"] = "1E20CC70",
            ["NextDialogue"] = 12034905,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC70",
            },
        [12034905] = {
            ["Content"] = "第四关通过后，直接进入收尾动画",
            ["ContentJP"] = "第四ステージをクリアすると、自動でエンディングアニメへ",
            ["DialogueId"] = 12034905,
            ["GUID"] = "1E20CC9A",
            ["NextDialogue"] = 12034906,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CC9A",
            },
        [12034906] = {
            ["Content"] = "菲娜拿着魔法书，四个召唤兽围绕在她身边。她微笑着合上书，召唤兽们也随之消失了。",
            ["ContentJP"] = "フィーナが魔法の本を手に取り、四体の召喚獣が彼女のまわりに現れる。フィーナはやさしく微笑んで、本を閉じる。それにあわせて、召喚獣たちも静かに姿を消していく",
            ["DialogueId"] = 12034906,
            ["GUID"] = "1E20CCC4",
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/1E20CCC4",
            },
        [12034910] = {
            ["Content"] = "【过场1】菲娜抵御强盗Activty_Feina_SC001",
            ["DialogueId"] = 12034910,
            ["GUID"] = "1E20CCC5",
            },
        [12034911] = {
            ["Content"] = "【过场2】结局大合照Activty_Feina_SC002",
            ["DialogueId"] = 12034911,
            ["GUID"] = "1E20CCC6",
            },
        [12034912] = {
            ["Content"] = "【过场3】奥特赛德家的晚会Activty_Feina_SC003",
            ["DialogueId"] = 12034912,
            ["GUID"] = "1E20CCC7",
            },
        [12035001] = {
            ["Content"] = "今天还是不要走太远比较好。",
            ["DialogueId"] = 12035001,
            ["GUID"] = "1E20DC5A",
            },
        [12035002] = {
            ["Content"] = "巢穴之外，有着广阔的世界。",
            ["DialogueId"] = 12035002,
            ["GUID"] = "1E20DC84",
            },
        [12035003] = {
            ["Content"] = "这条河流，一路向着危险的秘境。",
            ["DialogueId"] = 12035003,
            ["GUID"] = "1E20DCAE",
            },
        [12035004] = {
            ["Content"] = "是点石成金的公主殿下！",
            ["DialogueId"] = 12035004,
            ["GUID"] = "1E20DCD8",
            },
        [12035005] = {
            ["Content"] = "公主殿下看上去似乎很忙，还是不要打扰她了。",
            ["DialogueId"] = 12035005,
            ["GUID"] = "1E20DD02",
            },
        [12035006] = {
            ["Content"] = "小夜莺与点石成金的公主殿下擦肩而过，继续踏上旅途。",
            ["DialogueId"] = 12035006,
            ["GUID"] = "1E20DD2C",
            },
        [12035007] = {
            ["Content"] = "穿过砖石和钢铁铸造的森林。",
            ["DialogueId"] = 12035007,
            ["GUID"] = "1E20DD56",
            },
        [12035008] = {
            ["Content"] = "前方还有什么在等待着她呢？",
            ["DialogueId"] = 12035008,
            ["GUID"] = "1E20DD80",
            },
        [12035009] = {
            ["Content"] = "就像是童话里魔龙的嘴。",
            ["DialogueId"] = 12035009,
            ["GUID"] = "1E20DDAA",
            },
        [12035010] = {
            ["Content"] = "吸血鬼？他们似乎在谈论菲娜的事。",
            ["DialogueId"] = 12035010,
            ["GUID"] = "1E20DDD4",
            },
        [12035011] = {
            ["Content"] = "怎么办！她过来了！",
            ["DialogueId"] = 12035011,
            ["GUID"] = "1E20DDFE",
            },
        [12035012] = {
            ["Content"] = "先往这个方向看看？",
            ["DialogueId"] = 12035012,
            ["GUID"] = "1E20DE28",
            },
        [12035013] = {
            ["Content"] = "似乎不在这里……",
            ["DialogueId"] = 12035013,
            ["GUID"] = "1E20DE52",
            },
        [12035014] = {
            ["Content"] = "也许……",
            ["DialogueId"] = 12035014,
            ["GUID"] = "1E20DE7C",
            },
        [12035015] = {
            ["Content"] = "是保卫水管的叔叔。",
            ["DialogueId"] = 12035015,
            ["GUID"] = "1E20DEA6",
            },
        [12035016] = {
            ["Content"] = "那边的是！",
            ["DialogueId"] = 12035016,
            ["GUID"] = "1E20DED0",
            },
        [12035017] = {
            ["Content"] = "好可爱！",
            ["DialogueId"] = 12035017,
            ["GUID"] = "1E20DEFA",
            },
        [12035050] = {
            ["Content"] = "这次，菲娜去这个方向找小土豆们！",
            ["DialogueId"] = 12035050,
            ["GUID"] = "1E20E464",
            },
        [12035051] = {
            ["Content"] = "难道说小土豆们钻到了井盖下面？",
            ["DialogueId"] = 12035051,
            ["GUID"] = "1E20E48E",
            },
        [12035052] = {
            ["Content"] = "果然不在这里……",
            ["DialogueId"] = 12035052,
            ["GUID"] = "1E20E4B8",
            },
        [12035053] = {
            ["Content"] = "不对不对，得先去找小土豆们。",
            ["DialogueId"] = 12035053,
            ["GUID"] = "1E20E4E2",
            },
        [12035054] = {
            ["Content"] = "那里有声音！",
            ["DialogueId"] = 12035054,
            ["GUID"] = "1E20E50C",
            },
        [12035055] = {
            ["Content"] = "小土豆肯定藏在这里。",
            ["DialogueId"] = 12035055,
            ["GUID"] = "1E20E536",
            },
        [12035056] = {
            ["Content"] = "是小猫！",
            ["DialogueId"] = 12035056,
            ["GUID"] = "1E20E560",
            },
        [12035075] = {
            ["Content"] = "这是我。",
            ["DialogueId"] = 12035075,
            ["GUID"] = "1E20E87E",
            },
        [12035076] = {
            ["Content"] = "菲娜。",
            ["DialogueId"] = 12035076,
            ["GUID"] = "1E20E8A8",
            },
        [12035077] = {
            ["Content"] = "是大魔法师。",
            ["DialogueId"] = 12035077,
            ["GUID"] = "1E20E8D2",
            },
        [12035101] = {
            ["Content"] = "熟悉的天花板。",
            ["DialogueId"] = 12035101,
            ["GUID"] = "1E20ECC2",
            },
        [12035102] = {
            ["Content"] = "夜莺",
            ["DialogueId"] = 12035102,
            ["GUID"] = "1E20ECEC",
            },
        [12035103] = {
            ["Content"] = "还有",
            ["DialogueId"] = 12035103,
            ["GUID"] = "1E20ED16",
            },
        [12035104] = {
            ["Content"] = "大魔法师",
            ["DialogueId"] = 12035104,
            ["GUID"] = "1E20ED40",
            },
        [12035105] = {
            ["Content"] = "太阳",
            ["DialogueId"] = 12035105,
            ["GUID"] = "1E20ED6A",
            },
        [12035106] = {
            ["Content"] = "好刺眼",
            ["DialogueId"] = 12035106,
            ["GUID"] = "1E20ED94",
            },
        [12035107] = {
            ["Content"] = "菲娜得起床了……",
            ["DialogueId"] = 12035107,
            ["GUID"] = "1E20EDBE",
            },
        [12035108] = {
            ["Content"] = "昨晚写的故事",
            ["DialogueId"] = 12035108,
            ["GUID"] = "1E20EDE8",
            },
        [12035109] = {
            ["Content"] = "头好重",
            ["DialogueId"] = 12035109,
            ["GUID"] = "1E20EE12",
            },
        [12035110] = {
            ["Content"] = "早起的鸟儿有虫吃",
            ["DialogueId"] = 12035110,
            ["GUID"] = "1E20EE3C",
            },
        [12035111] = {
            ["Content"] = "奥特赛德已经出门了",
            ["DialogueId"] = 12035111,
            ["GUID"] = "1E20EE66",
            },
        [12035113] = {
            ["Content"] = "你一觉睡到了下午，明天的事明天再说吧。",
            ["DialogueId"] = 12035113,
            ["GUID"] = "1E20EEBA",
            },
        [12035114] = {
            ["Content"] = "尝试起床",
            ["DialogueId"] = 12035114,
            ["GUID"] = "1E20EEE4",
            },
        [12035115] = {
            ["Content"] = "……",
            ["DialogueId"] = 12035115,
            ["GUID"] = "1E20EF0E",
            },
        [12035201] = {
            ["Content"] = "菲娜的书",
            ["DialogueId"] = 12035201,
            ["GUID"] = "1E20FD2A",
            },
        [12035202] = {
            ["Content"] = "温暖的火炉",
            ["DialogueId"] = 12035202,
            ["GUID"] = "1E20FD54",
            },
        [12035203] = {
            ["Content"] = "窗外的世界……",
            ["DialogueId"] = 12035203,
            ["GUID"] = "1E20FD7E",
            },
        [12035204] = {
            ["Content"] = "大魔法师和夜莺",
            ["DialogueId"] = 12035204,
            ["GUID"] = "1E20FDA8",
            },
        [12035205] = {
            ["Content"] = "大魔法师很早就会起床",
            ["DialogueId"] = 12035205,
            ["GUID"] = "1E20FDD2",
            },
        [12035206] = {
            ["Content"] = "很久没有出门了",
            ["DialogueId"] = 12035206,
            ["GUID"] = "1E20FDFC",
            },
        [12035301] = {
            ["Content"] = "大魔法师，有着敏锐的嗅觉。",
            ["DialogueId"] = 12035301,
            ["GUID"] = "1E210D92",
            },
        [12035302] = {
            ["Content"] = "他能做到很多不可思议的事情。",
            ["DialogueId"] = 12035302,
            ["GUID"] = "1E210DBC",
            },
        [12035303] = {
            ["Content"] = "大魔法的意思应该是让菲娜看看箱子后面？",
            ["DialogueId"] = 12035303,
            ["GUID"] = "1E210DE6",
            },
        [12035304] = {
            ["Content"] = "大魔法师说\"菲娜要尝试全力向上跳跃！\"",
            ["DialogueId"] = 12035304,
            ["GUID"] = "1E210E10",
            },
        [12035310] = {
            ["Camera"] = "-182.732056,402.138672,75.417969,0.000544,6.001974,107.204239,35.0,252.889053,false,Manual,8.0",
            ["Content"] = "（曾在冰冷的大宅邸中陪伴菲娜度过许多孤独时刻的可靠伙伴，拥有柔软羽毛和宽大翅膀的白鸟先生。）",
            ["DialogueId"] = 12035310,
            ["NextDialogue"] = 12035311,
            },
        [12035311] = {
            ["Content"] = "（虽然一度失散，但在塞维欧的帮助下，白鸟先生现在又重新回到了菲娜的身边，从今往后也会继续用它圆溜溜的眼睛一直守望着菲娜。）",
            ["DialogueId"] = 12035311,
            },
        [12040101] = {
            ["Content"] = "……一切难道就会完全按照<H>你</>的想法去发生吗？",
            ["ContentJP"] = "……すべてが、<H>あなた</>の思い通りに進むとでも？",
            ["DialogueId"] = 12040101,
            ["GUID"] = "1E242112",
            ["NextDialogue"] = 12040102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E242112",
            },
        [12040102] = {
            ["Content"] = "是的，{nickname}，这就是定数。定数是不可更改的。",
            ["ContentJP"] = "ええ、{nickname}。これは定め、変えることなんてできないの。",
            ["DialogueId"] = 12040102,
            ["GUID"] = "1E24213C",
            ["NextDialogue"] = 12040103,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E24213C",
            },
        [12040103] = {
            ["Content"] = "人心、变量，难道一切都在你的算计中吗？我不信。人既然有着选择的自由，就不可能被所谓的预言摆布——",
            ["ContentJP"] = "人の心や変化まで、全部あなたの計算通りってこと？信じない。人には選ぶ自由がある。\
くだらない予言に操られたりなんかしない――",
            ["DialogueId"] = 12040103,
            ["GUID"] = "1E242166",
            ["NextDialogue"] = 12040104,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E242166",
            },
        [12040104] = {
            ["Content"] = "呵呵……虽然和你聊天很愉快，但我们的时间已经所剩无几了。",
            ["ContentJP"] = "ふふ……おしゃべりは楽しいけれど、もう時間がないわ。",
            ["DialogueId"] = 12040104,
            ["GUID"] = "1E242190",
            ["NextDialogue"] = 12040105,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E242190",
            },
        [12040105] = {
            ["Content"] = "接下来，<W>忘记我，忘记我们说过的一切</>，好吗？",
            ["ContentJP"] = "<W>私のことも、私との会話も全部忘れてくれるかしら</>。",
            ["DialogueId"] = 12040105,
            ["GUID"] = "1E2421BA",
            ["NextDialogue"] = 12040106,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E2421BA",
            },
        [12040106] = {
            ["Content"] = "不，我拒绝——",
            ["ContentJP"] = "{性别:断る……|いやよ……}",
            ["DialogueId"] = 12040106,
            ["GUID"] = "1E2421E4",
            ["NextDialogue"] = 12040107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E2421E4",
            },
        [12040107] = {
            ["Content"] = "……抱歉，{nickname}。命运的算筹已经掷下，我们都没有拒绝的资格。",
            ["ContentJP"] = "……ごめんなさい、{nickname}。運命のサイコロは既に放たれた。\
誰であれ、それに背く権利はないわ。",
            ["DialogueId"] = 12040107,
            ["GUID"] = "1E24220E",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120401/1E24220E",
            },
        [12040201] = {
            ["Content"] = "呵呵……也是正巧被你们赶上这时节了。<H>奉香大典</>可是华胥一年到头中顶顶热闹的日子。",
            ["ContentJP"] = "ふふ……いい時期に来てくれたわね。<H><Default note=\"text:ほうこうのぎ\">奉香の儀</></>は、\
華胥で一年を通して一番賑やかな日よ。",
            ["DialogueId"] = 12040201,
            ["GUID"] = "1E24317A",
            ["NextDialogue"] = 12040202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 203001,
                [3] = 405014,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24317A",
            },
        [12040202] = {
            ["Content"] = "临近节庆，四面八方的华胥民众都会汇聚到辇毂之下的皓京。种种节庆限定的美食、布景、仪典，都会在最近筹备起来。",
            ["ContentJP"] = "祭りが近づくと、華胥の各地から人々がお膝元の<Default note=\"text:こうけい\">皓京</>に集まるの。\
特別な料理や飾り、儀式があちこちで準備されてね。",
            ["DialogueId"] = 12040202,
            ["GUID"] = "1E2431A4",
            ["NextDialogue"] = 12040203,
            ["RelatedWikiId"] = {
                [1] = 408016,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2431A4",
            },
        }
  end },
  { MinKey = 12040203, MaxKey = 12041806, Loader = function()
      return {
        [12040203] = {
            ["Content"] = "哇！那个什么限定美食听起来好有意思，止流姐姐能不能展开来讲讲？",
            ["ContentJP"] = "わぁ！その特別な料理ってやつ、すっごく興味深い！シリュウ、詳しく聞かせてよ！",
            ["DialogueId"] = 12040203,
            ["GUID"] = "1E2431CE",
            ["NextDialogue"] = 12040204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2431CE",
            },
        [12040204] = {
            ["Content"] = "嗯，就比如说城东的八珍楼，在奉香大典前后会出售一种独特的香糕。因其用到了一种极难采集的花蕊，一天只供应十笼。",
            ["ContentJP"] = "例えば城東の<Default note=\"text:はっちんろう\">八珍楼</>では、この祭りの時だけ特別な蒸し菓子を売るの。\
滅多に手に入らない花の蕊を使っていて、一日わずか十籠しか作られない。まさに貴重な一品よ。",
            ["DialogueId"] = 12040204,
            ["GUID"] = "1E2431F8",
            ["NextDialogue"] = 12040205,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2431F8",
            },
        [12040205] = {
            ["Content"] = "香糕一旦掀笼，香气四溢，使人没齿难忘。因此，每日排队的人络绎不绝，被吸引来的路人在店铺旁久久徘徊不去，也是城中一景呢。",
            ["ContentJP"] = "一度蓋を開ければ香りがふわっと広がって、忘れられなくなるわ。\
そのせいで毎日長蛇の列ができ、通りがかりの人も思わず立ち止まるくらいよ。\
もはや皓京一の絶景とも言えるわ。",
            ["DialogueId"] = 12040205,
            ["GUID"] = "1E243222",
            ["NextDialogue"] = 12040206,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243222",
            },
        [12040206] = {
            ["Content"] = "什么，要排队吗？！那我们走快点——",
            ["ContentJP"] = "えっ、並ぶの！？じゃ、急ごう――",
            ["DialogueId"] = 12040206,
            ["GUID"] = "1E24324C",
            ["NextDialogue"] = 12040207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24324C",
            },
        [12040207] = {
            ["Content"] = "{nickname}，你今天怎么走得这么慢？赶紧跟上来啦！",
            ["ContentJP"] = "{nickname}、遅いぞ！早く早く！",
            ["DialogueId"] = 12040207,
            ["GUID"] = "1E243276",
            ["NextDialogue"] = 12040208,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243276",
            },
        [12040208] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12040208,
            ["GUID"] = "1E2432A0",
            ["NextDialogue"] = 12040209,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2432A0",
            },
        [12040209] = {
            ["Content"] = "小仆从，你还好吗？你的脸色看起来好苍白……",
            ["ContentJP"] = "おい、下僕。なんだか顔色が悪いぞ……大丈夫？",
            ["DialogueId"] = 12040209,
            ["GUID"] = "1E2432CA",
            ["NextOptions"] = {
                [1] = 12040210,
                [2] = 12040211,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2432CA",
            },
        [12040210] = {
            ["Content"] = "这里是哪……？",
            ["ContentJP"] = "ここは……？",
            ["DialogueId"] = 12040210,
            ["GUID"] = "1E2432F4",
            ["NextDialogue"] = 12040212,
            },
        [12040211] = {
            ["Content"] = "我们怎么在这里……？",
            ["ContentJP"] = "どうしてここに……？",
            ["DialogueId"] = 12040211,
            ["GUID"] = "1E24331E",
            ["NextDialogue"] = 12040212,
            },
        [12040212] = {
            ["Content"] = "诶诶诶——你可别吓我啊！",
            ["ContentJP"] = "ちょ、ちょっと！？脅かさないでよ！？",
            ["DialogueId"] = 12040212,
            ["GUID"] = "1E243348",
            ["NextDialogue"] = 12040213,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243348",
            },
        [12040213] = {
            ["Content"] = "小仆从，你还能记起来多少东西？我们一起并肩作战打坏人的珍贵经历，白罩着你的那些日子，统统不记得了吗？！",
            ["ContentJP"] = "この魔王様と悪党をやっつけたり、スノウに守られてたありがたい日々、忘れたとか言わないよね！？",
            ["DialogueId"] = 12040213,
            ["GUID"] = "1E243372",
            ["NextDialogue"] = 12040214,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243372",
            },
        [12040214] = {
            ["Content"] = "完、完蛋了，这下该怎么办……一定是在开玩笑吧！白可不想失去小仆从这个朋友，呜呜……",
            ["ContentJP"] = "な、なんてこった……！冗談でしょ！？スノウを忘れないで……ぐすっ……",
            ["DialogueId"] = 12040214,
            ["GUID"] = "1E24339C",
            ["NextOptions"] = {
                [1] = 12040215,
                [2] = 12040216,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24339C",
            },
        [12040215] = {
            ["Content"] = "（捉弄白。）",
            ["ContentJP"] = "スノウをからかう",
            ["DialogueId"] = 12040215,
            ["GUID"] = "1E2433C6",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12040217,
            },
        [12040216] = {
            ["Content"] = "（安慰白。）",
            ["ContentJP"] = "スノウを慰める",
            ["DialogueId"] = 12040216,
            ["GUID"] = "1E2433F0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12040222,
            },
        [12040217] = {
            ["Content"] = "是啊，都忘了。包括你说要罩着我，结果躲在我身后瑟瑟发抖的那件事，都忘得一干二净了。",
            ["ContentJP"] = "うん、全部忘れちゃった。\
{性别:君が僕を守るって言って、後ろで震えてたのもな。|君が私を守るって言って、後ろで震えてたのもね。}",
            ["DialogueId"] = 12040217,
            ["GUID"] = "1E24341A",
            ["NextDialogue"] = 12040218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24341A",
            },
        [12040218] = {
            ["Content"] = "什么嘛！这不是该有不该有的记忆，统统都在嘛！",
            ["ContentJP"] = "なっ……覚えてるじゃんか！！",
            ["DialogueId"] = 12040218,
            ["GUID"] = "1E243444",
            ["NextDialogue"] = 12040219,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243444",
            },
        [12040219] = {
            ["Content"] = "小仆从整天就知道捉弄我，魔王大人也是有脾气的！",
            ["ContentJP"] = "ぐぬぬ、いっつもスノウをからかってばっか！これ以上は怒っちゃうぞ！",
            ["DialogueId"] = 12040219,
            ["GUID"] = "1E24346E",
            ["NextDialogue"] = 12040220,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24346E",
            },
        [12040220] = {
            ["Content"] = "好啦好啦，白，听我说。",
            ["ContentJP"] = "はいはい。それよりスノウ、聞いて。",
            ["DialogueId"] = 12040220,
            ["GUID"] = "1E243498",
            ["NextDialogue"] = 12040221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243498",
            },
        [12040221] = {
            ["Content"] = "我记得你、记得止流掌柜，记得我们在冰湖城的日子，也记得我们一起来华胥的原因。",
            ["ContentJP"] = "君のこともシリュウさんのことも覚えてる。アイスレイク城で過ごした日々も、華胥に来た理由もね。",
            ["DialogueId"] = 12040221,
            ["GUID"] = "1E2434C2",
            ["NextDialogue"] = 12040223,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2434C2",
            },
        [12040222] = {
            ["Content"] = "……白，别慌。",
            ["ContentJP"] = "……スノウ、落ち着いて。",
            ["DialogueId"] = 12040222,
            ["GUID"] = "1E2434EC",
            ["NextDialogue"] = 12040221,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2434EC",
            },
        [12040223] = {
            ["Content"] = "只是印象里……我们明明在赶去祭坛解决烛阴之灾的路上。再往后的事情，我再怎么努力去想也想不起来。",
            ["ContentJP"] = "ただ……祭壇へ向かって<Default note=\"text:しょくいん\">燭陰</>を倒す途中までは覚えてるけど、\
それ以降はどうしても思い出せない{性别:んだ|の}。",
            ["DialogueId"] = 12040223,
            ["GUID"] = "1E243516",
            ["NextDialogue"] = 12040224,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243516",
            },
        [12040224] = {
            ["Content"] = "呼……还好还好，忘的不多。",
            ["ContentJP"] = "ふぅ……よかった、全部じゃないんだな。",
            ["DialogueId"] = 12040224,
            ["GUID"] = "1E243540",
            ["NextDialogue"] = 12040225,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243540",
            },
        [12040225] = {
            ["Content"] = "你刚刚提到烛阴？那条恶龙早就被我们打败啦，就在昨天！",
            ["ContentJP"] = "あ、<Default note=\"text:しょくいん\">燭陰</>？あの悪龍なら昨日倒したじゃんか！",
            ["DialogueId"] = 12040225,
            ["GUID"] = "1E24356A",
            ["NextDialogue"] = 12040226,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24356A",
            },
        [12040226] = {
            ["Content"] = "之后，百年春还开了场庆功宴，表彰我们是为民除害的大英雄呢。当然，报酬自然也是少不了我们的！",
            ["ContentJP"] = "そのあと百年春で祝宴があって、私たちは超英雄扱いされてさ！もちろん報酬もバッチリ！",
            ["DialogueId"] = 12040226,
            ["GUID"] = "1E243594",
            ["NextDialogue"] = 12040227,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243594",
            },
        [12040227] = {
            ["Content"] = "回冰湖城的飞艇还有几天才出发。闲着也是闲着，我干脆让止流姐姐带我们来附近的大城市逛逛——最近华胥在准备过节哦！",
            ["ContentJP"] = "アイスレイク城への飛行船はまだ数日後だし、\
シリュウに街案内をお願いしたんだぞ。それで、今は祭り準備中だ！",
            ["DialogueId"] = 12040227,
            ["GUID"] = "1E2435BE",
            ["NextDialogue"] = 12040228,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2435BE",
            },
        [12040228] = {
            ["Content"] = "你还记得吗，这座城市叫皓京，是华胥曾经的首都，比烟津渡热闹多啦！",
            ["ContentJP"] = "ここは<Default note=\"text:こうけい\">皓京</>、華胥の元首都！\
<Default note=\"text:えんしんと\">煙津渡</>よりずっと賑やかなんだぞ！",
            ["DialogueId"] = 12040228,
            ["GUID"] = "1E2435E8",
            ["NextDialogue"] = 12040229,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2435E8",
            },
        [12040229] = {
            ["Content"] = "我们才刚刚坐小船到这儿，还没有开始玩呢，结果就发现你看起来好像不太舒服。",
            ["ContentJP"] = "ちょうど船に乗ってきたばかりで、まだ遊んでもないのに……あんたが具合悪そうだったから。",
            ["DialogueId"] = 12040229,
            ["GUID"] = "1E243612",
            ["NextDialogue"] = 12040230,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243612",
            },
        [12040230] = {
            ["Content"] = "怎么样，小仆从。我这样说，有没有让你回忆起来一点点？",
            ["ContentJP"] = "どうだ、我が下僕？少しは思い出した？",
            ["DialogueId"] = 12040230,
            ["FinalDialogueId"] = 12040243,
            ["GUID"] = "1E24363C",
            ["NextOptions"] = {
                [1] = 12040231,
                [2] = 12040232,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24363C",
            },
        [12040231] = {
            ["Content"] = "试图否认。",
            ["ContentJP"] = "否定しようとする。",
            ["DialogueId"] = 12040231,
            ["GUID"] = "1E243666",
            ["NextDialogue"] = 12040238,
            },
        [12040232] = {
            ["Content"] = "好像是这样……",
            ["ContentJP"] = "そうかもしれない……",
            ["DialogueId"] = 12040232,
            ["GUID"] = "1E243690",
            ["NextDialogue"] = 12040243,
            },
        [12040238] = {
            ["Content"] = "（一种异样的陌生感冲刷着你的神经。哪里不对劲——你的内心有一个细小的声音如此呐喊着。）",
            ["ContentJP"] = "（得体の知れぬ違和感が神経を走る。どこかおかしい――心の奥で小さな声が叫んでいる。）",
            ["DialogueId"] = 12040238,
            ["GUID"] = "1E24378C",
            ["NextDialogue"] = 12040239,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24378C",
            },
        [12040239] = {
            ["Content"] = "（烛阴果真被打败了吗？在烛阴祭坛上，是否还发生了什么？造成了某种让你惊愕，不可置信，并且不应忘记的危机？）",
            ["ContentJP"] = "（<Default note=\"text:しょくいん\">燭陰</>は本当に倒された{性别:のか？あの祭壇で、何か信じ難い危機が起こってはいないか？）|の？あの祭壇で、何か信じ難い危機が起こってはいないの？）}",
            ["DialogueId"] = 12040239,
            ["GUID"] = "1E2437B6",
            ["NextDialogue"] = 12040240,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2437B6",
            },
        [12040240] = {
            ["Content"] = "（你试图回想起什么。几乎在一瞬间，钻心的疼痛刺痛了你的脑海。你在冰冷的战栗中忘记了如何思考。）",
            ["ContentJP"] = "（思い出そうとした瞬間、頭を裂くような痛みが走り、思考は凍りつく。）",
            ["DialogueId"] = 12040240,
            ["GUID"] = "1E2437E0",
            ["NextDialogue"] = 12040241,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2437E0",
            },
        [12040241] = {
            ["Content"] = "…………头、好疼……",
            ["ContentJP"] = "……あ、頭が……っ",
            ["DialogueId"] = 12040241,
            ["GUID"] = "1E24380A",
            ["NextDialogue"] = 12040242,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24380A",
            },
        [12040242] = {
            ["Content"] = "呜，小仆从，你的脸色看起来真的好差。",
            ["ContentJP"] = "うわっ、下僕、本当に顔色やばいぞ！",
            ["DialogueId"] = 12040242,
            ["GUID"] = "1E243834",
            ["NextDialogue"] = 12040230,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243834",
            },
        [12040243] = {
            ["Content"] = "（你的记忆逐渐复苏……似乎确实如白所说，你们去了庆功宴，然后坐船来到这里……但这些记忆好像又朦朦胧胧隔着一层雾，看不真切。）",
            ["ContentJP"] = "（少しずつ記憶が戻る……確かに祝宴に出て、船でここに来た……だが、霧の向こうにあるように曖昧だ。）",
            ["DialogueId"] = 12040243,
            ["GUID"] = "1E24385E",
            ["NextDialogue"] = 12040244,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24385E",
            },
        [12040244] = {
            ["Content"] = "……啊！我想起来了，之前和那条坏龙打架的时候，掉了好多好多碎石块。",
            ["ContentJP"] = "……あっ、思い出した！あの悪龍と戦ったとき、岩がいっぱい落ちてきたんだった！",
            ["DialogueId"] = 12040244,
            ["GUID"] = "1E243888",
            ["NextDialogue"] = 12040245,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243888",
            },
        [12040245] = {
            ["Content"] = "会不会小仆从的脑袋在那时候不小心被石块击中了，才落下了后遗症……止流姐姐，你有什么解决办法吗？",
            ["ContentJP"] = "もしかして、その時頭をぶつけて後遺症が……シリュウ、なんとかできないの？",
            ["DialogueId"] = 12040245,
            ["GUID"] = "1E2438B2",
            ["NextDialogue"] = 12040246,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2438B2",
            },
        [12040246] = {
            ["Content"] = "嗯……确有这种可能。",
            ["ContentJP"] = "……そうね、その可能性はあるわ。",
            ["DialogueId"] = 12040246,
            ["GUID"] = "1E2438DC",
            ["NextDialogue"] = 12040247,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2438DC",
            },
        [12040247] = {
            ["Content"] = "抱歉，是我疏忽了。没有及时察觉到{nickname}身体抱恙，实在是东道主的失责。",
            ["ContentJP"] = "ごめんなさい。客人の体調不良に気付けなかったなんて、私の問題だわ。",
            ["DialogueId"] = 12040247,
            ["GUID"] = "1E243906",
            ["NextDialogue"] = 12040248,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243906",
            },
        [12040248] = {
            ["Content"] = "前方不远就是皓京近些年声名鹊起的药堂，泽生阁。其门专精药学，虽不如祝由扶氏那样手到病除，几如神迹，但常见的病痛都能及时治疗。",
            ["ContentJP"] = "この先に最近<Default note=\"text:こうけい\">皓京</>で有名になった薬堂、<Default note=\"text:たくせいかく\">澤生閣</>があるの。<Default note=\"text:しゅくゆけ\">祝由家</>とまではいかないけれど、たいていの病は治せるわ。",
            ["DialogueId"] = 12040248,
            ["GUID"] = "1E243930",
            ["NextDialogue"] = 12040249,
            ["RelatedWikiId"] = {
                [1] = 406006,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243930",
            },
        [12040249] = {
            ["Content"] = "经年累月下来，在民众之间积累了不错的口碑。",
            ["ContentJP"] = "長年にわたり、民の間でも評判はいいわ。",
            ["DialogueId"] = 12040249,
            ["GUID"] = "1E24395A",
            ["NextDialogue"] = 12040250,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E24395A",
            },
        [12040250] = {
            ["Content"] = "我们可以去那里抓些药材，煎一味提神醒脑的汤药，看看能否好转。若是效果不佳，我们就立刻打道回府，不要耽误了{nickname}的病情。",
            ["ContentJP"] = "そこで薬を調えて、気付けの湯薬を飲ませましょう。それで駄目なら、すぐ引き返すわ。長引かせるわけにはいかないもの。",
            ["DialogueId"] = 12040250,
            ["GUID"] = "1E243984",
            ["NextDialogue"] = 12040251,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243984",
            },
        [12040251] = {
            ["Content"] = "好，就按止流姐姐说的！那我们赶紧过去吧！",
            ["ContentJP"] = "そうだね、じゃあシリュウの案で行こう！",
            ["DialogueId"] = 12040251,
            ["GUID"] = "1E2439AE",
            ["NextDialogue"] = 12040252,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2439AE",
            },
        [12040252] = {
            ["Content"] = "小仆从，你慢慢走。不用着急，我就跟在你身后，看着你的状态。",
            ["ContentJP"] = "我が下僕、ゆっくりでいいぞ！私が後ろについてるから！",
            ["DialogueId"] = 12040252,
            ["GUID"] = "1E2439D8",
            ["NextDialogue"] = 12040253,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E2439D8",
            },
        [12040253] = {
            ["Content"] = "要是你身体没有好起来，我也没心思玩。还是你比较重要，要是不行我们就先回去休息！",
            ["ContentJP"] = "お前が元気じゃなきゃ遊ぶ気にもなれないし、お前の方が大事だ！無理せず休め！",
            ["DialogueId"] = 12040253,
            ["GUID"] = "1E243A02",
            ["NextDialogue"] = 12040254,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243A02",
            },
        [12040254] = {
            ["Content"] = "……嗯，我应该没什么大碍。我们走吧。",
            ["ContentJP"] = "……うん、大丈夫だと思う。行こう。",
            ["DialogueId"] = 12040254,
            ["GUID"] = "1E243A2C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120402/1E243A2C",
            },
        [12040301] = {
            ["Content"] = "竟、竟然有这么多人……这就是过节吗？",
            ["ContentJP"] = "うわっ、人だらけじゃん……これが祭りってやつか？",
            ["DialogueId"] = 12040301,
            ["GUID"] = "1E2441E2",
            ["NextDialogue"] = 12040302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 406006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E2441E2",
            },
        [12040302] = {
            ["Content"] = "诶……那里！能休息的座位竟然只剩一个了！",
            ["ContentJP"] = "あっ……あそこ！座れる場所、あと一つしかないぞ！",
            ["DialogueId"] = 12040302,
            ["GUID"] = "1E24420C",
            ["NextDialogue"] = 12040303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E24420C",
            },
        [12040303] = {
            ["Content"] = "小仆从，你赶紧过去占着位置，坐下先好好休息。我和止流姐姐去买药……",
            ["ContentJP"] = "お前は先に行って席取って休んでな。私とシリュウで薬を――",
            ["DialogueId"] = 12040303,
            ["GUID"] = "1E244236",
            ["NextDialogue"] = 12040304,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E244236",
            },
        [12040304] = {
            ["Content"] = "白，我去买药吧。",
            ["ContentJP"] = "{性别:いや|いいえ}、自分で行く{性别:よ|わ}。",
            ["DialogueId"] = 12040304,
            ["GUID"] = "1E244260",
            ["NextDialogue"] = 12040305,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E244260",
            },
        [12040305] = {
            ["Content"] = "哎？小仆从，你身体不舒服，这种时候不应该到处乱跑吧？",
            ["ContentJP"] = "へ？でも体調が悪いんだし、座って休んでた方がいいんじゃ……",
            ["DialogueId"] = 12040305,
            ["GUID"] = "1E24428A",
            ["NextDialogue"] = 12040306,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E24428A",
            },
        [12040306] = {
            ["Content"] = "没事的，我感觉已经好一些了。走一走反而对身体有好处，你就放一万个心吧。",
            ["ContentJP"] = "平気{性别:さ|だよ}、もうだいぶ楽になった。むしろ歩いた方が楽な気がする。心配いらないって。",
            ["DialogueId"] = 12040306,
            ["GUID"] = "1E2442B4",
            ["NextDialogue"] = 12040307,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E2442B4",
            },
        [12040307] = {
            ["Content"] = "嗯……你可别逞强哦。那你们速去速回，白就在那里等着你们。",
            ["ContentJP"] = "……ほんとだな？無理するなよ！二人ともすぐ戻ってくるんだぞ！私はあそこで待ってるからな！",
            ["DialogueId"] = 12040307,
            ["GUID"] = "1E2442DE",
            ["NextDialogue"] = 12040308,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E2442DE",
            },
        [12040308] = {
            ["Content"] = "跟我来，{nickname}。泽生阁就在前方。",
            ["ContentJP"] = "ついてきて、{nickname}。<Default note=\"text:たくせいかく\">澤生閣</>はこの先よ。",
            ["DialogueId"] = 12040308,
            ["GUID"] = "1E244308",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120403/1E244308",
            },
        [12040401] = {
            ["Content"] = "两位客官安康。今日是来抓什么药的？",
            ["ContentJP"] = "いらっしゃいませ。本日はどのような薬を？",
            ["DialogueId"] = 12040401,
            ["GUID"] = "1E24524A",
            ["NextDialogue"] = 12040402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 406006,
                },
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24524A",
            },
        [12040402] = {
            ["Content"] = "劳烦您抓一剂川息茶，一剂辟秽正气散，再添四钱凉络根作为佐剂……",
            ["ContentJP"] = "<Default note=\"text:せんそくちゃ\">川息茶</>を一服、邪気払いの<Default note=\"text:しょうきさん\">正気散</>を一服、\
それから<Default note=\"text:りょうらくこん\">涼絡根</>を四銭、佐薬としてお願い。",
            ["DialogueId"] = 12040402,
            ["GUID"] = "1E245274",
            ["NextOptions"] = {
                [1] = 12040403,
                [2] = 12040404,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245274",
            },
        [12040403] = {
            ["Content"] = "听他们交谈。",
            ["ContentJP"] = "二人の会話を聞く。",
            ["DialogueId"] = 12040403,
            ["GUID"] = "1E24529E",
            ["NextDialogue"] = 12040405,
            },
        [12040404] = {
            ["Content"] = "打断止流，描述自己的症状。",
            ["ContentJP"] = "シリュウを遮り、自分で症状を説明する",
            ["DialogueId"] = 12040404,
            ["GUID"] = "1E2452C8",
            ["NextDialogue"] = 12040409,
            },
        [12040405] = {
            ["Content"] = "听这药方，您的家人或朋友是否有些头疼、体虚，甚至神志恍惚的毛病？",
            ["ContentJP"] = "その<Default note=\"text:しょほうせん\">処方箋</>……頭痛や虚弱、意識がぼんやりするような症状をお持ちの方がいるのですね？",
            ["DialogueId"] = 12040405,
            ["GUID"] = "1E2452F2",
            ["NextDialogue"] = 12040406,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2452F2",
            },
        [12040406] = {
            ["Content"] = "呵呵……不愧是泽生阁，果真名不虚传。",
            ["ContentJP"] = "ふふ……さすが<Default note=\"text:たくせいかく\">澤生閣</>、処方箋だけでわかるのね。",
            ["DialogueId"] = 12040406,
            ["GUID"] = "1E24531C",
            ["NextDialogue"] = 12040407,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24531C",
            },
        [12040407] = {
            ["Content"] = "客官过奖。瞧您这方子，在药理上倒是颇有几分造诣。是谁身体不舒服，您身边这位{性别：小兄弟|姑娘}吗？",
            ["ContentJP"] = "お褒めにあずかり光栄です。処方からして薬理にも通じておられるようですね。\
具合が悪いのは……そちらの{性别:坊や|お嬢さん}ですか？",
            ["DialogueId"] = 12040407,
            ["GUID"] = "1E245346",
            ["NextDialogue"] = 12040408,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245346",
            },
        [12040408] = {
            ["Content"] = "嗯，我从早上开始就有点不太舒服，头一直隐隐作痛。",
            ["ContentJP"] = "ええ、今朝からちょっと頭が重くて……ずっと鈍く痛むんです。",
            ["DialogueId"] = 12040408,
            ["GUID"] = "1E245370",
            ["NextDialogue"] = 12040411,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245370",
            },
        [12040409] = {
            ["Content"] = "您好。我今天有点头疼，而且好像有点健忘，老是想不起最近发生的事情。",
            ["ContentJP"] = "今日は頭痛があって、なんだか物忘れもひどくて……最近のことが思い出せないんです。",
            ["DialogueId"] = 12040409,
            ["GUID"] = "1E24539A",
            ["NextDialogue"] = 12040410,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24539A",
            },
        [12040410] = {
            ["Content"] = "刚才这位客官所报的药方恰好对症，在药理上倒是颇有几分造诣。",
            ["ContentJP"] = "なるほど、先ほどの処方は確かに症状に合っています。どうやら、薬理にも通じておられるようですね。",
            ["DialogueId"] = 12040410,
            ["GUID"] = "1E2453C4",
            ["NextDialogue"] = 12040411,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2453C4",
            },
        [12040411] = {
            ["Content"] = "观您气色，虽有些虚汗神浮，但总体并无大碍。在刚刚的药方基础上，再加一钱茯神，服下后应当就能好转。",
            ["ContentJP"] = "お顔の色はやや汗ばんでいますが、大事には至らないでしょう。\
先ほどの処方に<Default note=\"text:ぶくしん\">茯神</>を一銭加えて飲めば、すぐ楽になるはずです。",
            ["DialogueId"] = 12040411,
            ["GUID"] = "1E2453EE",
            ["NextDialogue"] = 12040412,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2453EE",
            },
        [12040412] = {
            ["Content"] = "那就多谢你了。",
            ["ContentJP"] = "ありがとうございます。",
            ["DialogueId"] = 12040412,
            ["GUID"] = "1E245418",
            ["NextDialogue"] = 12040413,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245418",
            },
        [12040413] = {
            ["Content"] = "(你们在原地等待了一会儿，热腾腾的汤药被药师煎好，送到了你手上。棕黑色的液体散发出不容忽视的苦味。)",
            ["ContentJP"] = "しばらく待つと、煎じたての薬が手渡された。黒褐色の液体から、強烈な苦味が立ちのぼる。",
            ["DialogueId"] = 12040413,
            ["GUID"] = "1E245442",
            ["NextDialogue"] = 12040414,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245442",
            },
        [12040414] = {
            ["Content"] = "{nickname}，汤药烫手，好拿吗？",
            ["ContentJP"] = "{nickname}、熱いけど、持てる？",
            ["DialogueId"] = 12040414,
            ["GUID"] = "1E24546C",
            ["NextDialogue"] = 12040415,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24546C",
            },
        [12040415] = {
            ["Content"] = "嗯，没问题。",
            ["ContentJP"] = "ええ。",
            ["DialogueId"] = 12040415,
            ["GUID"] = "1E245496",
            ["NextDialogue"] = 12040416,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245496",
            },
        [12040416] = {
            ["Content"] = "走，去坐下，吹凉了再慢慢喝吧。",
            ["ContentJP"] = "じゃあ、座って冷ましてからゆっくり飲みなさい。",
            ["DialogueId"] = 12040416,
            ["GUID"] = "1E2454C0",
            ["NextDialogue"] = 12040417,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2454C0",
            },
        [12040417] = {
            ["Content"] = "（止流掌柜的药方确实是用来治头疼的。她的言行与往常一样，没有异样……）",
            ["ContentJP"] = "（シリュウさんの処方は確かに頭痛用だ。言動もいつも通り、変なところはない……）",
            ["DialogueId"] = 12040417,
            ["GUID"] = "1E2454EA",
            ["NextDialogue"] = 12040418,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E2454EA",
            },
        [12040418] = {
            ["Content"] = "（奇怪，我今天怎么好像有些疑心病？是我多想了吗……？）",
            ["ContentJP"] = "（でも、なんでだろう……今日はやけに疑い深くなってる。気のせい……？）",
            ["DialogueId"] = 12040418,
            ["GUID"] = "1E245514",
            ["NextDialogue"] = 12040419,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E245514",
            },
        [12040419] = {
            ["Content"] = "（可能最近连续奔波，有些累到了……还是赶紧回去找白吧。）",
            ["ContentJP"] = "（たぶん最近動きっぱなしで疲れてるんだ……スノウのところに戻ろう）",
            ["DialogueId"] = 12040419,
            ["GUID"] = "1E24553E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120404/1E24553E",
            },
        [12040501] = {
            ["Content"] = "哇，小仆从，看你喝了药，脸都皱成一团了。听说东方的药剂很苦，真有这么夸张吗？",
            ["ContentJP"] = "うわ、何その顔！そんなに苦いの？東の薬はやたら苦いって聞いたけど、ほんと？",
            ["DialogueId"] = 12040501,
            ["GUID"] = "1E2462B2",
            ["NextOptions"] = {
                [1] = 12040502,
                [2] = 12040503,
                },
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 406006,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2462B2",
            },
        [12040502] = {
            ["Content"] = "不苦，甜的，很好喝，你要不要来试试？",
            ["ContentJP"] = "いや、甘くて美味しいよ。試してみる？",
            ["DialogueId"] = 12040502,
            ["GUID"] = "1E2462DC",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12040504,
            },
        [12040503] = {
            ["Content"] = "确实很苦，是尝过之后就很难忘记的味道……",
            ["ContentJP"] = "うん、確かに苦い。忘れられない味だな……",
            ["DialogueId"] = 12040503,
            ["GUID"] = "1E246306",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12040505,
            },
        [12040504] = {
            ["Content"] = "还、还是算了吧……",
            ["ContentJP"] = "……や、やめとく。",
            ["DialogueId"] = 12040504,
            ["GUID"] = "1E246330",
            ["NextDialogue"] = 12040505,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246330",
            },
        [12040505] = {
            ["Content"] = "那，小仆从，你现在感觉怎么样了，有好一点吗？",
            ["ContentJP"] = "で、どう？ちょっとはマシになった？",
            ["DialogueId"] = 12040505,
            ["GUID"] = "1E24635A",
            ["NextDialogue"] = 12040506,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24635A",
            },
        [12040506] = {
            ["Content"] = "嗯，头已经不疼了。大概只是昨晚没睡好吧。",
            ["ContentJP"] = "{ああ、もう頭痛は治まったよ。昨日あんまり眠れなかっただけだと思う。|ええ、もう頭痛は治まったわ。昨日あんまり眠れなかっただけだと思う。}",
            ["DialogueId"] = 12040506,
            ["GUID"] = "1E246384",
            ["NextDialogue"] = 12040507,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246384",
            },
        [12040507] = {
            ["Content"] = "那就好！我待会儿再去给你买点那个节庆限定的香糕，多吃点甜甜的东西，嘴里就不会苦了。",
            ["ContentJP"] = "それならよかった！あとで祭り限定の蒸し菓子を買ってきてあげる。甘いもの食べれば口の中の苦味も消えるでしょ？",
            ["DialogueId"] = 12040507,
            ["GUID"] = "1E2463AE",
            ["NextDialogue"] = 12040508,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2463AE",
            },
        [12040508] = {
            ["Content"] = "今天你怎么对我这么好？我都有点意外了。",
            ["ContentJP"] = "今日はやけに優しいじゃん。ちょっと意外{性别:だな|ね}。",
            ["DialogueId"] = 12040508,
            ["GUID"] = "1E2463D8",
            ["NextDialogue"] = 12040509,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2463D8",
            },
        [12040509] = {
            ["Content"] = "哼哼，毕竟白是体贴下属的好魔王嘛！来，我们继续在这里休息一会儿，今天不赶时间，不着急。",
            ["ContentJP"] = "ふふん、私は部下思いのいい魔王なんだぞ！さ、もうちょっと休もう。今日は時間あるし、のんびりするのも悪くない。",
            ["DialogueId"] = 12040509,
            ["GUID"] = "1E246402",
            ["NextDialogue"] = 12040510,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246402",
            },
        [12040510] = {
            ["Content"] = "你们坐在原地休息。过了一会儿，档口旁突然传来了兴高采烈的喧哗声。",
            ["ContentJP"] = "休んでいると、屋台のほうから賑やかな声が聞こえてきた。",
            ["DialogueId"] = 12040510,
            ["GUID"] = "1E24642C",
            ["NextDialogue"] = 12040511,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24642C",
            },
        [12040511] = {
            ["Content"] = "我听说<H>奉香群英试</>的获胜者，可以登上执律阁，一览绝景风光，甚至让白龙神君亲口回答一个问题呢！",
            ["ContentJP"] = "<Default note=\"text:ほうこうえいゆうたいかい\">奉香英雄大会</>で勝てば、<Default note=\"text:しつりつかく\">執律閣</>に登って絶景を眺められるし、白龍様に直接お会いし、一つ質問をしていいらしい！",
            ["DialogueId"] = 12040511,
            ["GUID"] = "1E246456",
            ["NextDialogue"] = 12040512,
            ["RelatedWikiId"] = {
                [1] = 405015,
                },
            ["SpeakNpcId"] = 240010,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246456",
            },
        [12040512] = {
            ["Content"] = "哎？那边好吵，他们都在聊些什么呀？",
            ["ContentJP"] = "あれ？向こうやけに騒がしいね。何の話してるんだろ？",
            ["DialogueId"] = 12040512,
            ["GUID"] = "1E246480",
            ["NextDialogue"] = 12040513,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246480",
            },
        [12040513] = {
            ["Content"] = "执律阁就是白龙神君下榻的神所吧！与神近距离面对面，到底是什么感觉呢……好想知道啊。",
            ["ContentJP"] = "<Default note=\"text:しつりつかく\">執律閣</>って、白龍様がおられる神殿でしょ？神様と間近で会えるなんてどんな気持ちなんだろ……気になるなあ。",
            ["DialogueId"] = 12040513,
            ["GUID"] = "1E2464AA",
            ["NextDialogue"] = 12040514,
            ["RelatedWikiId"] = {
                [1] = 407009,
                },
            ["SpeakNpcId"] = 240010,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2464AA",
            },
        [12040514] = {
            ["Content"] = "我舅舅的好友的姑奶奶，就说她曾经登上过执律阁顶，那风景叫一个终生难忘！",
            ["ContentJP"] = "うちの叔父さんの友達の大伯母が、一度だけ執律閣の頂上に登ったことがあるんだって。あの景色は一生忘れられないってさ！",
            ["DialogueId"] = 12040514,
            ["GUID"] = "1E2464D4",
            ["NextDialogue"] = 12040515,
            ["SpeakNpcId"] = 240011,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2464D4",
            },
        [12040515] = {
            ["Content"] = "有道是：凌霄悬阁镇云关，瞰尽千城暮色间。龙鳞映日金波转，万仞秋光赤玉山。",
            ["ContentJP"] = "「<Default note=\"text:りょうしょう\">凌霄</>の<Default note=\"text:かけたかどの\">懸閣</>、<Default note=\"text:うんかん\">雲関</>を鎮め、<Default note=\"text:せんじょう\">千城</>、<Default note=\"text:ぼしょく\">暮色</>の間に<Default note=\"text:のぞ\">瞰</>み<Default note=\"text:つく\">尽</>す。<Default note=\"text:りょうりん\">龍鱗</>は日を映し、<Default note=\"text:きんぱ\">金波</>を転じ、<Default note=\"text:ばんじん\">万仞</>の<Default note=\"text:しゅうこう\">秋光</>。山も<Default note=\"text:あかだま\">赤玉</>のごとし。」――だそうだ。",
            ["DialogueId"] = 12040515,
            ["GUID"] = "1E2464FE",
            ["NextDialogue"] = 12040516,
            ["SpeakNpcId"] = 240012,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2464FE",
            },
        [12040516] = {
            ["Content"] = "执律归来再无阁，若是能有幸造访一番，也算是此生无憾了……",
            ["ContentJP"] = "<Default note=\"text:しつりつ\">執律</>に登った者は、<Default note=\"text:たかどの\">閣</>を<Default note=\"text:な\">為</>し<Default note=\"text:がた\">難</>し。あれはもう……人生悔いなしってほどの景色だとか……",
            ["DialogueId"] = 12040516,
            ["GUID"] = "1E246528",
            ["NextDialogue"] = 12040517,
            ["SpeakNpcId"] = 240012,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246528",
            },
        [12040517] = {
            ["Content"] = "止流姐姐，那个执律阁真有他们说的那么神奇吗？",
            ["ContentJP"] = "シリュウ、<Default note=\"text:しつりつかく\">執律閣</>って本当にあんなにすごいの？",
            ["DialogueId"] = 12040517,
            ["GUID"] = "1E246552",
            ["NextDialogue"] = 12040518,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246552",
            },
        [12040518] = {
            ["Content"] = "呵呵，道听途说，未免有夸大之词。不过执律阁横跨两岳之巅，凌驾云霄之上，纵览皓京，气象万千。对于初访皓京的人，倒确实值得一看。",
            ["ContentJP"] = "ふふ、多少は盛ってるだろうけど……二つの山の頂をつなぎ、雲よりも高く、\
<Default note=\"text:こうけい\">皓京</>の街を一望できる。初めて来た人には、確かに見る価値はあるわね。",
            ["DialogueId"] = 12040518,
            ["GUID"] = "1E24657C",
            ["NextDialogue"] = 12040519,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24657C",
            },
        [12040519] = {
            ["Content"] = "只可惜，执律阁是白龙神君降旨的要地，寻常民众和游客非传召不得进入。",
            ["ContentJP"] = "ただ、執律閣は白龍様の勅命の場。一般人や観光客は招待なしじゃ入れないの。",
            ["DialogueId"] = 12040519,
            ["GUID"] = "1E2465A6",
            ["NextDialogue"] = 12040520,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2465A6",
            },
        [12040520] = {
            ["Content"] = "这样哦……",
            ["ContentJP"] = "そっか……",
            ["DialogueId"] = 12040520,
            ["GUID"] = "1E2465D0",
            ["NextDialogue"] = 12040521,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2465D0",
            },
        [12040521] = {
            ["Content"] = "不过，你们若是当真感兴趣，我这里倒恰好有个委托。",
            ["ContentJP"] = "でも、もし興味があるなら、ちょうどいい依頼があるわ。",
            ["DialogueId"] = 12040521,
            ["GUID"] = "1E2465FA",
            ["NextDialogue"] = 12040522,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2465FA",
            },
        [12040522] = {
            ["Content"] = "临近奉香大典，天禄司事务繁忙，正需要差人去各司取了仪式所用的种种器具，送上执律阁。",
            ["ContentJP"] = "<Default note=\"text:ほうこうのぎ\">奉香の儀</>が近くて、<Default note=\"text:てんろくし\">天禄司</>は忙しいの。\
儀式で使う道具を各司から集めて、<Default note=\"text:しつりつかく\">執律閣</>まで届けてほしいのよね。",
            ["DialogueId"] = 12040522,
            ["GUID"] = "1E246624",
            ["NextDialogue"] = 12040523,
            ["RelatedWikiId"] = {
                [1] = 407010,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246624",
            },
        [12040523] = {
            ["Content"] = "你们不妨为我跑上一趟，沿途恰好能感受这里的节日氛围。怎么样，考虑一下？",
            ["ContentJP"] = "道中、祭りの雰囲気も味わえるし……どうかしら？",
            ["DialogueId"] = 12040523,
            ["GUID"] = "1E24664E",
            ["NextDialogue"] = 12040524,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24664E",
            },
        [12040524] = {
            ["Content"] = "哎？这不就是那什么，瞌睡了刚好有人递枕头嘛！啊不过……小仆从，我们去不去还是看你的想法。",
            ["ContentJP"] = "え、まさに渡りに船ってやつ！？……あ、でも、行くかどうかはお前が決めていいぞ、我が下僕！",
            ["DialogueId"] = 12040524,
            ["GUID"] = "1E246678",
            ["NextDialogue"] = 12040525,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246678",
            },
        [12040525] = {
            ["Content"] = "难得来一次，你如果真那么感兴趣，去看看也行。",
            ["ContentJP"] = "せっかくだし、そんなに興味あるなら行ってみようか。",
            ["DialogueId"] = 12040525,
            ["GUID"] = "1E2466A2",
            ["NextDialogue"] = 12040526,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2466A2",
            },
        [12040526] = {
            ["Content"] = "哇，就知道小仆从对我最好了！那还等什么，我们赶紧走吧！",
            ["ContentJP"] = "へへへ、我が下僕ならそういうと思った！じゃあ決まり！",
            ["DialogueId"] = 12040526,
            ["GUID"] = "1E2466CC",
            ["NextDialogue"] = 12040527,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2466CC",
            },
        [12040527] = {
            ["Content"] = "呵呵……天禄司就在桥对岸的西城区，你们陪我走上一趟吧，我好将信物交予你们。",
            ["ContentJP"] = "<Default note=\"text:てんろくし\">天禄司</>は橋を渡った西の街よ。一緒に行きましょう。<Default note=\"text:しるし\">信物</>を渡しておくわね。",
            ["DialogueId"] = 12040527,
            ["GUID"] = "1E2466F6",
            ["NextDialogue"] = 12040528,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2466F6",
            },
        [12040528] = {
            ["Content"] = "咦，那几人是……？",
            ["ContentJP"] = "……あれ、今し方の方々は……？",
            ["DialogueId"] = 12040528,
            ["GUID"] = "1E246720",
            ["NextDialogue"] = 12040529,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246720",
            },
        [12040529] = {
            ["Content"] = "扶疏阁下，怎么了？",
            ["ContentJP"] = "どうかされましたか？フーシュ殿。",
            ["DialogueId"] = 12040529,
            ["GUID"] = "1E24674A",
            ["NextDialogue"] = 12040530,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24674A",
            },
        [12040530] = {
            ["Content"] = "无妨，她们应当不会走在一起，许是我看错了。还是说回正事吧。",
            ["ContentJP"] = "いえ、おそらくは見間違いにございましょう。それより、先ほどの件に戻りましょう。",
            ["DialogueId"] = 12040530,
            ["GUID"] = "1E246774",
            ["NextDialogue"] = 12040531,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E246774",
            },
        [12040531] = {
            ["Content"] = "抱歉，扶疏阁下。这回魂散的功效简直闻所未闻。恕我才疏学浅，可能没法帮上您的忙。",
            ["ContentJP"] = "……この「<Default note=\"text:はんごんさん\">反魂散</>」という薬の効能は、聞いたこともありません。\
お力になれず、申し訳ありません。",
            ["DialogueId"] = 12040531,
            ["GUID"] = "1E24679E",
            ["NextDialogue"] = 12040532,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E24679E",
            },
        [12040532] = {
            ["Content"] = "容我多说一句……人死灯灭，生者还请节哀。但这倒行逆施之事，望您能慎重考虑。",
            ["ContentJP"] = "僭越ながら……人は亡くなれば戻らないものです。どうかお気持ちを落ち着けてください。禁忌にはくれぐれも触れぬよう。",
            ["DialogueId"] = 12040532,
            ["GUID"] = "1E2467C8",
            ["NextDialogue"] = 12040533,
            ["SpeakNpcId"] = 240003,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2467C8",
            },
        [12040533] = {
            ["Content"] = "嗯……我明白了，多谢。",
            ["ContentJP"] = "……心得ました。御忠言、痛み入ります。",
            ["DialogueId"] = 12040533,
            ["GUID"] = "1E2467F2",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120405/1E2467F2",
            },
        [12040601] = {
            ["Content"] = "这里就是天禄司，分管华胥经济、贸易、赋税的部门。你们在这里稍等片刻。",
            ["ContentJP"] = "ここが<Default note=\"text:てんろくし\">天禄司</>よ。華胥の経済や交易、税を取り仕切っている所。少し待っていてね。",
            ["DialogueId"] = 12040601,
            ["GUID"] = "1E24731A",
            ["NextDialogue"] = 12040602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203001,
                [4] = 405014,
                [5] = 407010,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24731A",
            },
        [12040602] = {
            ["Content"] = "一会儿之后，止流拿着信物和地图走了出来。",
            ["ContentJP"] = "しばらくしてシリュウが信物と地図を手に戻ってくる。",
            ["DialogueId"] = 12040602,
            ["GUID"] = "1E247344",
            ["NextDialogue"] = 12040603,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247344",
            },
        [12040603] = {
            ["Content"] = "该去的地点我已经给你们标注在上面了。分别是西南方的<H>参商港</>，内城的<H>祀烟阁</>，以及与其临对的<H>匠矩阁</>。",
            ["ContentJP"] = "目的地は地図に記しておいたわ。西南の<H><Default note=\"text:さんしょうこう\">参商港</></>、\
内城の<H><Default note=\"text:しえんかく\">祀煙閣</></>、その向かいにある<H><Default note=\"text:しょうくかく\">匠矩閣</></>。",
            ["DialogueId"] = 12040603,
            ["GUID"] = "1E24736E",
            ["NextDialogue"] = 12040604,
            ["RelatedWikiId"] = {
                [1] = 408017,
                [2] = 407011,
                [3] = 407012,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24736E",
            },
        [12040604] = {
            ["Content"] = "他们看到这样信物，就知道你是天禄司差遣来的信使，会将东西交予你。",
            ["ContentJP"] = "この<Default note=\"text:しるし\">信物</>を見せれば、<Default note=\"text:てんろくし\">天禄司</>からの使いだと分かって品を渡してくれるはずよ。",
            ["DialogueId"] = 12040604,
            ["GUID"] = "1E247398",
            ["NextDialogue"] = 12040605,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247398",
            },
        [12040605] = {
            ["Content"] = "好嘞，止流姐姐。那这些东西拿到之后，我们在哪里会合？",
            ["ContentJP"] = "了解！で、全部集めたらどこで待ち合わせる？",
            ["DialogueId"] = 12040605,
            ["GUID"] = "1E2473C2",
            ["NextDialogue"] = 12040606,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2473C2",
            },
        [12040606] = {
            ["Content"] = "……很遗憾。我有一些紧要事情需要去处理。接下来，你们或许会有一段时间见不到我。",
            ["ContentJP"] = "……残念だけど、これから少し急ぎの用事があるの。しばらく会えないかもしれないわ。",
            ["DialogueId"] = 12040606,
            ["GUID"] = "1E2473EC",
            ["NextDialogue"] = 12040607,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2473EC",
            },
        [12040607] = {
            ["Content"] = "等你们到了执律阁之上，只要说明来意，就会有专人与你们对接。",
            ["ContentJP"] = "<Default note=\"text:しつりつかく\">執律閣</>に着いたら、そこにいる係の者に用件を伝えて。",
            ["DialogueId"] = 12040607,
            ["GUID"] = "1E247416",
            ["NextDialogue"] = 12040608,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247416",
            },
        [12040608] = {
            ["Content"] = "哎？那好吧，没想到这么快就要和止流姐姐说再见了。",
            ["ContentJP"] = "そっか……もうお別れかぁ。",
            ["DialogueId"] = 12040608,
            ["GUID"] = "1E247440",
            ["NextDialogue"] = 12040609,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247440",
            },
        [12040609] = {
            ["Content"] = "呵呵……华胥有句古话，叫做难得是欢聚，唯有别离多。{nickname}，在我们道别之前，我还有几句话想和你说。",
            ["ContentJP"] = "「出会いは別れのはじまり」って言うでしょう？{nickname}、別れる前に伝えておきたいことがあるの。",
            ["DialogueId"] = 12040609,
            ["GUID"] = "1E24746A",
            ["NextDialogue"] = 12040610,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24746A",
            },
        [12040610] = {
            ["Content"] = "……？",
            ["ContentJP"] = "……？",
            ["DialogueId"] = 12040610,
            ["GUID"] = "1E247494",
            ["NextDialogue"] = 12040611,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247494",
            },
        [12040611] = {
            ["Content"] = "止流掌柜，你想说什么？",
            ["ContentJP"] = "シリュウさん、なんです？",
            ["DialogueId"] = 12040611,
            ["GUID"] = "1E2474BE",
            ["NextDialogue"] = 12040612,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2474BE",
            },
        [12040612] = {
            ["Content"] = "我为你卜了一卦，你当做是临行嘱托也好。未来几日，可能会发生一些出乎你意料的事情。",
            ["ContentJP"] = "あなたの旅路を占ってみたの。別れ際の一言にしてもいいわ。これから先、思いがけない出来事が起こるでしょう。",
            ["DialogueId"] = 12040612,
            ["GUID"] = "1E2474E8",
            ["NextDialogue"] = 12040613,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2474E8",
            },
        [12040613] = {
            ["Content"] = "如果中途你有动摇的时候，稍微耐下心来，静候事态发展。最终，你会获得令你满意的报酬。",
            ["ContentJP"] = "もし迷うことがあったら、少し立ち止まって成り行きを見守って。きっと、満足のいく結果が待っているはず。",
            ["DialogueId"] = 12040613,
            ["GUID"] = "1E247512",
            ["NextDialogue"] = 12040614,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247512",
            },
        [12040614] = {
            ["Content"] = "出乎意料的事情……令我满意的报酬？我听不太懂。",
            ["ContentJP"] = "思いがけない出来事……満足のいく結果？なんのこと？",
            ["DialogueId"] = 12040614,
            ["GUID"] = "1E24753C",
            ["NextDialogue"] = 12040615,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24753C",
            },
        [12040615] = {
            ["Content"] = "卦象并不会将未来解释得如此清晰，它只能给出预测，或者说征兆。直到事情发生的一刻，卦象的寓意才能够得到解答。",
            ["ContentJP"] = "占いは未来を細かく教えてはくれないの。ただ兆しを示すだけ。意味が分かるのは、すべてが起きた後よ。",
            ["DialogueId"] = 12040615,
            ["GUID"] = "1E247566",
            ["NextDialogue"] = 12040616,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247566",
            },
        [12040616] = {
            ["Content"] = "……虽然有点突兀，止流掌柜，我可以问你一个问题吗？",
            ["ContentJP"] = "……一つ質問してもいいですか？",
            ["DialogueId"] = 12040616,
            ["GUID"] = "1E247590",
            ["NextDialogue"] = 12040617,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247590",
            },
        [12040617] = {
            ["Content"] = "你说。",
            ["ContentJP"] = "何かしら。",
            ["DialogueId"] = 12040617,
            ["GUID"] = "1E2475BA",
            ["NextOptions"] = {
                [1] = 12040618,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2475BA",
            },
        [12040618] = {
            ["Content"] = "你是不是还有什么事情瞒着我？",
            ["ContentJP"] = "何か隠してますよね？",
            ["DialogueId"] = 12040618,
            ["GUID"] = "1E2475E4",
            ["NextDialogue"] = 12040619,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2475E4",
            },
        [12040619] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12040619,
            ["GUID"] = "1E24760E",
            ["NextDialogue"] = 12040620,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24760E",
            },
        [12040620] = {
            ["Content"] = "我<H>现在</>还无法给出这个问题的答案。有些事，待时机到时，方见分晓。",
            ["ContentJP"] = "……<H>今は</>答えられないわ。時が来れば、分かるはずよ。",
            ["DialogueId"] = 12040620,
            ["GUID"] = "1E247638",
            ["NextDialogue"] = 12040621,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247638",
            },
        [12040621] = {
            ["Content"] = "诶，你们怎么了，怎么气氛突然那么沉重……没关系，以后还会见面啦！",
            ["ContentJP"] = "なんだなんだ、急に重い空気になっちゃって！また会えるんだからいいじゃん！",
            ["DialogueId"] = 12040621,
            ["GUID"] = "1E247662",
            ["NextDialogue"] = 12040622,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E247662",
            },
        [12040622] = {
            ["Content"] = "止流姐姐，等我们回了冰湖城，就给你寄泪湖的明信片！泪湖水蓝汪汪的，可好看了。",
            ["ContentJP"] = "シリュウ、アイスレイク城に帰ったらダクリ湖の絵ハガキ送ってあげるよ！水が真っ青でめっちゃ綺麗なんだから！",
            ["DialogueId"] = 12040622,
            ["GUID"] = "1E24768C",
            ["NextDialogue"] = 12040623,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24768C",
            },
        [12040623] = {
            ["Content"] = "好呀，我很期待。",
            ["ContentJP"] = "ふふ、楽しみにしてるわ。",
            ["DialogueId"] = 12040623,
            ["GUID"] = "1E2476B6",
            ["NextDialogue"] = 12040624,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2476B6",
            },
        [12040624] = {
            ["Content"] = "那，使命必达小分队要出发了！小仆从，我们走！",
            ["ContentJP"] = "よーし！任務必達隊、出発ー！行くぞ！我が下僕！",
            ["DialogueId"] = 12040624,
            ["GUID"] = "1E2476E0",
            ["NextDialogue"] = 12040625,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E2476E0",
            },
        [12040625] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12040625,
            ["GUID"] = "1E24770A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120406/1E24770A",
            },
        [12040701] = {
            ["Content"] = "你好，我们受天禄司所托，来取准备奉香大典需要的道具。这是我们的信物。",
            ["ContentJP"] = "こんにちは。<Default note=\"text:てんろくし\">天禄司</>からの依頼で、\
<Default note=\"text:ほうこうのぎ\">奉香の儀</>の道具を受け取りに来ました。こちらが<Default note=\"text:しるし\">信物</>です。",
            ["DialogueId"] = 12040701,
            ["GUID"] = "1E248382",
            ["NextDialogue"] = 12040702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 408017,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E248382",
            },
        [12040702] = {
            ["Content"] = "好嘞。您要拿的就是那些上等绸布是吧？早上刚刚清点完毕，现在都整整齐齐地码在仓库里了。",
            ["ContentJP"] = "はいはい、探してるのは上等な絹布ですね？今朝倉庫に並べておきましたよ。",
            ["DialogueId"] = 12040702,
            ["GUID"] = "1E2483AC",
            ["NextDialogue"] = 12040703,
            ["SpeakNpcId"] = 240027,
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E2483AC",
            },
        [12040703] = {
            ["Content"] = "抱歉啊，最近这奉香大典快到了，天南地北的船只都停在了参商港。我们这里人手不够，暂且抽不开身。可以请您去仓库里取一下吗？",
            ["ContentJP"] = "すみません、もうすぐ<Default note=\"text:ほうこうのぎ\">奉香の儀</>だから、\
港が込み合ってて手が離せなくて……悪いんですが倉庫から直接取ってきてもらえます？",
            ["DialogueId"] = 12040703,
            ["GUID"] = "1E2483D6",
            ["NextDialogue"] = 12040704,
            ["SpeakNpcId"] = 240027,
            ["TalkActionId"] = {
                [1] = "240027:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E2483D6",
            },
        [12040704] = {
            ["Content"] = "没问题。您可以告诉我货物的特征吗？",
            ["ContentJP"] = "分かりました。特徴はありますか？",
            ["DialogueId"] = 12040704,
            ["GUID"] = "1E248400",
            ["NextDialogue"] = 12040705,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "240027:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E248400",
            },
        [12040705] = {
            ["Content"] = "您朝着右手边的方向走下去，货物堆中贴着货签的那个箱子便是。真是多谢了啊。",
            ["ContentJP"] = "右に進んだ先の貨物の山に、札が貼ってある箱があります。ではお願いしますね。",
            ["DialogueId"] = 12040705,
            ["GUID"] = "1E24842A",
            ["SpeakNpcId"] = 240027,
            ["VoiceName"] = "voice/$Locale$/story/1204/120407/1E24842A",
            },
        [12040801] = {
            ["Content"] = "呜哇！好大一个箱子在空中飘着！",
            ["ContentJP"] = "うわっ！でっかい箱が宙に浮いてる！？",
            ["DialogueId"] = 12040801,
            ["GUID"] = "1E2493EA",
            ["NextDialogue"] = 12040802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E2493EA",
            },
        [12040802] = {
            ["Content"] = "看那上面贴着的封纸，莫非是我们要找的——",
            ["ContentJP"] = "あの札……もしかして探してたやつじゃ――",
            ["DialogueId"] = 12040802,
            ["GUID"] = "1E249414",
            ["NextDialogue"] = 12040803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E249414",
            },
        [12040803] = {
            ["Content"] = "绫罗绸缎，金樽玉盏，好不逍遥～",
            ["ContentJP"] = "絹も酒器も、美しきものは我が糧……",
            ["DialogueId"] = 12040803,
            ["GUID"] = "1E24943E",
            ["NextDialogue"] = 12040804,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E24943E",
            },
        [12040804] = {
            ["Content"] = "我逍遥生看中的美物，被你们这等俗人拿走，岂不是一桩憾事。且让我先行一步——",
            ["ContentJP"] = "凡俗の手に渡すなど惜しいものよ。さて、先に頂戴つかまつる。",
            ["DialogueId"] = 12040804,
            ["GUID"] = "1E249468",
            ["NextDialogue"] = 12040805,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E249468",
            },
        [12040805] = {
            ["Content"] = "喂，怎么说话的，看不起谁呢！",
            ["ContentJP"] = "はぁ！？誰に向かって物言ってんの！？",
            ["DialogueId"] = 12040805,
            ["GUID"] = "1E249492",
            ["NextDialogue"] = 12040806,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E249492",
            },
        [12040806] = {
            ["Content"] = "不好，无由生拿着我们要的东西跑了！不能让它得逞，小仆从，我们快追！",
            ["ContentJP"] = "やばっ！持ってかれた！はやく追うよ！",
            ["DialogueId"] = 12040806,
            ["GUID"] = "1E2494BC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120408/1E2494BC",
            },
        [12040901] = {
            ["Content"] = "无趣无趣，你们既然如此执着，这东西还给你们也罢。拿着吧——",
            ["ContentJP"] = "つまらぬ……そこまで欲しければ返してやろう。ほれ。",
            ["DialogueId"] = 12040901,
            ["GUID"] = "1E24A452",
            ["NextDialogue"] = 12040902,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A452",
            },
        [12040902] = {
            ["Content"] = "喂，以为这样就算了嘛？你还没向白魔王大人和小仆从道歉呢！",
            ["ContentJP"] = "それだけじゃないぞ！！このスノウ様と下僕に謝れ！",
            ["DialogueId"] = 12040902,
            ["GUID"] = "1E24A47C",
            ["NextDialogue"] = 12040903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A47C",
            },
        [12040903] = {
            ["Content"] = "哈哈！贪愚痴妄，转首空空，不如逍遥～二位，我们有缘再会！",
            ["ContentJP"] = "ふふ……欲も執着も、振り返れば空。さらばだ、また会おうぞ。",
            ["DialogueId"] = 12040903,
            ["GUID"] = "1E24A4A6",
            ["NextDialogue"] = 12040904,
            ["RelatedWikiId"] = {
                [1] = 203008,
                },
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A4A6",
            },
        [12040904] = {
            ["Content"] = "可恶，这家伙就这样跑掉了……下次再见到它，一定要给它点颜色看看！",
            ["ContentJP"] = "くそっ、逃げられた……次に会ったらただじゃおかないからな！",
            ["DialogueId"] = 12040904,
            ["GUID"] = "1E24A4D0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120409/1E24A4D0",
            },
        [12041001] = {
            ["Content"] = "你好，我们是来拿奉香大典需要的……",
            ["ContentJP"] = "こんにちはー、<Default note=\"text:ほうこうのぎ\">奉香の儀</>に使う――",
            ["DialogueId"] = 12041001,
            ["GUID"] = "1E24B4BA",
            ["NextDialogue"] = 12041002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B4BA",
            },
        [12041002] = {
            ["Content"] = "喂喂，你这个皎皎怎么插队呢？明明是本姑娘先来的！",
            ["ContentJP"] = "ちょっと！あんた今、割り込んだでしょ！？先に並んでたのは私よ！",
            ["DialogueId"] = 12041002,
            ["GUID"] = "1E24B4E4",
            ["NextDialogue"] = 12041003,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B4E4",
            },
        [12041003] = {
            ["Content"] = "插队？没有没有，你搞错了，我们是过来拿……",
            ["ContentJP"] = "え？違うって、私たちは――",
            ["DialogueId"] = 12041003,
            ["GUID"] = "1E24B50E",
            ["NextDialogue"] = 12041004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B50E",
            },
        [12041004] = {
            ["Content"] = "好好好，打住打住。这位皎皎，还有这位白衣服的朋友，本姑娘理解你们对于求香的渴望，但是请乖乖到队尾站好。",
            ["ContentJP"] = "はいはいここまで！気持ちは分かるけど、順番はちゃんと守って後ろに並びなさいな。",
            ["DialogueId"] = 12041004,
            ["GUID"] = "1E24B538",
            ["NextDialogue"] = 12041005,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B538",
            },
        [12041005] = {
            ["Content"] = "喂，你这个人，怎么不听别人讲完话！",
            ["ContentJP"] = "ちょっと！最後まで聞いてよ！",
            ["DialogueId"] = 12041005,
            ["GUID"] = "1E24B562",
            ["NextDialogue"] = 12041006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B562",
            },
        [12041006] = {
            ["Content"] = "这种招数，本姑娘见得多啦。临近奉香大典，为了在奉香群英试上拔得头筹，祀烟阁前全都是来求香博个好彩头的。",
            ["ContentJP"] = "こういう抜け駆け、祭りの時期は特に多いんだから。英雄大会でいい結果を出そうって、みんな必死なんだからね。",
            ["DialogueId"] = 12041006,
            ["GUID"] = "1E24B58C",
            ["NextDialogue"] = 12041007,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B58C",
            },
        [12041007] = {
            ["Content"] = "但是！求香切记要心诚，想使小伎俩取巧逃避排队，那可是万、万、不、行——",
            ["ContentJP"] = "でもね！香を求める時は心を込めないとなのよ。ずるは絶対――だ・め！",
            ["DialogueId"] = 12041007,
            ["GUID"] = "1E24B5B6",
            ["NextDialogue"] = 12041008,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B5B6",
            },
        [12041008] = {
            ["Content"] = "你们争执之时，突然有一阵大风刮来，吹得行人衣袂纷飞。",
            ["ContentJP"] = "言い合っていると突然突風が吹き抜けた。",
            ["DialogueId"] = 12041008,
            ["GUID"] = "1E24B5E0",
            ["NextDialogue"] = 12041009,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B5E0",
            },
        [12041009] = {
            ["Content"] = "余光里，你好像看到什么轻飘飘的东西被大风卷起，直上云霄，最终落在了屋顶上。",
            ["ContentJP"] = "何かが宙に舞い屋根の上へ舞い上がった。",
            ["DialogueId"] = 12041009,
            ["GUID"] = "1E24B60A",
            ["NextDialogue"] = 12041010,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B60A",
            },
        [12041010] = {
            ["Content"] = "呜哇——本姑娘精心准备的节日限定版香囊！",
            ["ContentJP"] = "あーっ！ 大事にしてた限定物の香り袋が！",
            ["DialogueId"] = 12041010,
            ["GUID"] = "1E24B634",
            ["NextDialogue"] = 12041011,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B634",
            },
        [12041011] = {
            ["Content"] = "……小仆从，看她好像很苦恼的样子。我们就大人有大量，帮她去把香囊捡回来吧。",
            ["ContentJP"] = "……我が下僕、困ってるみたいだし、取ってあげようよ。",
            ["DialogueId"] = 12041011,
            ["GUID"] = "1E24B65E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120410/1E24B65E",
            },
        [12041101] = {
            ["Content"] = "给，这是你的东西，别再弄丢了。",
            ["ContentJP"] = "ほら、これ。もう落とさないようにね。",
            ["DialogueId"] = 12041101,
            ["GUID"] = "1E24C522",
            ["NextDialogue"] = 12041102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C522",
            },
        [12041102] = {
            ["Content"] = "……早就和你说了，我们才不是来插队的呢。魔王大人才不会做那种没素质的事情。",
            ["ContentJP"] = "だから言ったでしょ、私たちは割り込みなんてしてないって。スノウはマナーを守る魔王なんだから！",
            ["DialogueId"] = 12041102,
            ["GUID"] = "1E24C54C",
            ["NextDialogue"] = 12041103,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C54C",
            },
        [12041103] = {
            ["Content"] = "对不起……明明是我误会了你们，你们还不计前嫌地帮我取回香囊！",
            ["ContentJP"] = "……ごめんなさい、私の勘違いだったようね。それと、拾ってくれてありがとう！",
            ["DialogueId"] = 12041103,
            ["GUID"] = "1E24C576",
            ["NextDialogue"] = 12041104,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C576",
            },
        [12041104] = {
            ["Content"] = "……今天的新闻有素材了！我要把两位的善举整理成文章，刊登在《皓京市声报》上！",
            ["ContentJP"] = "今日の出来事を記事にして『<Default note=\"text:こうけいしそくほう\">皓京市速報</>』に載せちゃおうかな！",
            ["DialogueId"] = 12041104,
            ["GUID"] = "1E24C5A0",
            ["NextDialogue"] = 12041105,
            ["SpeakNpcId"] = 240007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C5A0",
            },
        [12041105] = {
            ["Content"] = "呵呵……晚来一步，倒是见识了一则明德惟馨的佳话。",
            ["ContentJP"] = "ふふ……一歩遅かったけど、いい話を聞かせてもらいました。",
            ["DialogueId"] = 12041105,
            ["GUID"] = "1E24C5CA",
            ["NextDialogue"] = 12041106,
            ["SpeakNpcId"] = 240008,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C5CA",
            },
        [12041106] = {
            ["Content"] = "两位可是来领奉香大典所需的皓烟香？抱歉让你们久等了，在此原物奉上。",
            ["ContentJP"] = "お待たせしました、こちらが<Default note=\"text:ほうこうのぎ\">奉香の儀</>用の<Default note=\"text:こうえんこう\">皓煙香</>です。",
            ["DialogueId"] = 12041106,
            ["GUID"] = "1E24C5F4",
            ["SpeakNpcId"] = 240008,
            ["VoiceName"] = "voice/$Locale$/story/1204/120411/1E24C5F4",
            },
        [12041201] = {
            ["Content"] = "对面忙得要命，这边反而都见不着几个人……好冷清哦。",
            ["ContentJP"] = "向こうは賑やかなのに、こっちは静かだなぁ……人も見当たらないし。",
            ["DialogueId"] = 12041201,
            ["GUID"] = "1E24D58A",
            ["NextDialogue"] = 12041202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120412/1E24D58A",
            },
        [12041202] = {
            ["Content"] = "有点看不出谁才是匠矩阁的人。小仆从，我们在附近找找看吧。",
            ["ContentJP"] = "<Default note=\"text:しょうくかく\">匠矩閣</>の人、どこにいるんだろ。探してみよっ。",
            ["DialogueId"] = 12041202,
            ["GUID"] = "1E24D5B4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120412/1E24D5B4",
            },
        [12041301] = {
            ["Content"] = "你好，请问你是匠矩阁的人吗？",
            ["ContentJP"] = "すみません、<Default note=\"text:しょうくかく\">匠矩閣</>の人ですか？",
            ["DialogueId"] = 12041301,
            ["GUID"] = "1E24E5F2",
            ["NextDialogue"] = 12041302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120413/1E24E5F2",
            },
        [12041302] = {
            ["Content"] = "匠矩阁？你说那帮神龙见首不见尾的人吗？我和他们不熟。",
            ["ContentJP"] = "<Default note=\"text:しょうくかく\">匠矩閣</>？あの姿を見せない連中か？知らないなぁ。",
            ["DialogueId"] = 12041302,
            ["GUID"] = "1E24E61C",
            ["SpeakNpcId"] = 240004,
            ["TalkActionId"] = {
                [1] = "240004:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120413/1E24E61C",
            },
        [12041401] = {
            ["Content"] = "你好，请问你是匠矩阁的人吗？",
            ["ContentJP"] = "すみません、<Default note=\"text:しょうくかく\">匠矩閣</>の人ですか？",
            ["DialogueId"] = 12041401,
            ["GUID"] = "1E24F65A",
            ["NextDialogue"] = 12041402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120414/1E24F65A",
            },
        [12041402] = {
            ["Content"] = "啊？不是，我就是看这儿清净，不像隔壁吵吵闹闹的。",
            ["ContentJP"] = "違う違う、ただ静かな場所が好きでここにいるだけだよ。",
            ["DialogueId"] = 12041402,
            ["GUID"] = "1E24F684",
            ["SpeakNpcId"] = 240005,
            ["TalkActionId"] = {
                [1] = "240005:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120414/1E24F684",
            },
        [12041501] = {
            ["Content"] = "你好，请问你是匠矩阁的人吗？",
            ["ContentJP"] = "すみません、<Default note=\"text:しょうくかく\">匠矩閣</>の人ですか？",
            ["DialogueId"] = 12041501,
            ["GUID"] = "1E2506C2",
            ["NextDialogue"] = 12041502,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120415/1E2506C2",
            },
        [12041502] = {
            ["Content"] = "呸呸呸，别乱说，我在准备会考呢。天禄司，天礼司，去哪都好，就是不能沾上这天梁司的晦气啊。",
            ["ContentJP"] = "おいおい、縁起でもないこと言うな。今は会試の準備中なんだ。\
<Default note=\"text:てんろくし\">天禄司</>や<Default note=\"text:てんれいし\">天礼司</>ならともかく……<Default note=\"text:てんりょうし\">天梁司</>だけはごめんだね。",
            ["DialogueId"] = 12041502,
            ["GUID"] = "1E2506EC",
            ["SpeakNpcId"] = 240006,
            ["TalkActionId"] = {
                [1] = "240005:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120415/1E2506EC",
            },
        [12041601] = {
            ["Content"] = "问了一圈，结果都不是。那这里眼看着也没别人了……",
            ["ContentJP"] = "誰も知らないじゃんか！こうなったら……",
            ["DialogueId"] = 12041601,
            ["GUID"] = "1E25172A",
            ["NextDialogue"] = 12041602,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407010,
                [5] = 407012,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E25172A",
            },
        [12041602] = {
            ["Content"] = "喂？有——人——在——吗——",
            ["ContentJP"] = "おーい！誰かいないかー！！",
            ["DialogueId"] = 12041602,
            ["GUID"] = "1E251754",
            ["NextDialogue"] = 12041603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E251754",
            },
        [12041603] = {
            ["Content"] = "在呢，别扯嗓子吆喝了——来了来了。",
            ["ContentJP"] = "はいはい、いるよいるよ、そんな大声出さなくてもねぇ。",
            ["DialogueId"] = 12041603,
            ["GUID"] = "1E25177E",
            ["NextDialogue"] = 12041604,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E25177E",
            },
        [12041604] = {
            ["Content"] = "看，这是天禄司的信物！我说大叔，你不是应该在这儿等着交接奉香大典的物资吗？怎么跑那么远啦，该不会是上班偷懒——",
            ["ContentJP"] = "ほら、<Default note=\"text:てんろくし\">天禄司</>からの<Default note=\"text:しるし\">信物</>！\
おじちゃん、<Default note=\"text:ほうこうのぎ\">奉香の儀</>の品を渡すためにここで待ってたんじゃないの？\
どこ行ってたのさ？まさかおサボり？",
            ["DialogueId"] = 12041604,
            ["GUID"] = "1E2517A8",
            ["NextDialogue"] = 12041605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E2517A8",
            },
        [12041605] = {
            ["Content"] = "嘿，你这小豆丁怎么说话呢？人生在世屈指算，最多三万六千天。那自然是图个清净，开心一天算一天。",
            ["ContentJP"] = "はは、口の減らないガキだな。人の一生なんてせいぜい三万六千日。静かに過ごせる日は貴重なんだよ。",
            ["DialogueId"] = 12041605,
            ["GUID"] = "1E2517D2",
            ["NextDialogue"] = 12041606,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E2517D2",
            },
        [12041606] = {
            ["Content"] = "当值的活都干完了，光人杵在这儿，有什么用？最瞧不起没活还要硬忙活的人了，净装样子，不干实事。",
            ["ContentJP"] = "仕事が終わってるのに、わざわざ突っ立って時間潰すのは性に合わん。",
            ["DialogueId"] = 12041606,
            ["GUID"] = "1E2517FC",
            ["NextDialogue"] = 12041607,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E2517FC",
            },
        [12041607] = {
            ["Content"] = "我们匠矩阁，光是修这个桥那个路，交付各式民用机傀，便要一个月忙活上二十几天，好不容易得了闲，休息片刻，还不行了？",
            ["ContentJP"] = "うち<Default note=\"text:しょうくかく\">匠矩閣</>はな、この橋やあの道の修理から、いろんな生活用のからくり人形の納品まで、ひと月のうち二十日以上は働きづめなんだ。\
やっと暇ができたのなら、休むくらい普通だろう？",
            ["DialogueId"] = 12041607,
            ["GUID"] = "1E251826",
            ["NextDialogue"] = 12041608,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E251826",
            },
        [12041608] = {
            ["Content"] = "嗯……也是这个理！白赞同！",
            ["ContentJP"] = "……まあ、確かにそうかも。言えてるな。",
            ["DialogueId"] = 12041608,
            ["GUID"] = "1E251850",
            ["NextDialogue"] = 12041609,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E251850",
            },
        [12041609] = {
            ["Content"] = "瞧你们还算讲道理的。喏，那就是奉香大典需要的奉香炉。早就放那台阶上了，你们去取吧。",
            ["ContentJP"] = "分かればよし。ほら、奉香炉はそこに置いてある。持っていきな。",
            ["DialogueId"] = 12041609,
            ["GUID"] = "1E25187A",
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120416/1E25187A",
            },
        [12041701] = {
            ["Content"] = "咚——咚——咚——咚——",
            ["ContentJP"] = "ゴーン――ゴーン――ゴーン――ゴーン――",
            ["DialogueId"] = 12041701,
            ["GUID"] = "1E252792",
            ["NextDialogue"] = 12041702,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407009,
                },
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252792",
            },
        [12041702] = {
            ["Content"] = "这是什么动静？",
            ["ContentJP"] = "ん？何の音？",
            ["DialogueId"] = 12041702,
            ["GUID"] = "1E2527BC",
            ["NextDialogue"] = 12041703,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2527BC",
            },
        [12041703] = {
            ["Content"] = "邪门了……这是执律阁的钟声。今天可真是撞上太阳从西边出来了。",
            ["ContentJP"] = "……あれは<Default note=\"text:しつりつかく\">執律閣</>の鐘じゃないか。驚いたな……",
            ["DialogueId"] = 12041703,
            ["GUID"] = "1E2527E6",
            ["NextDialogue"] = 12041704,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2527E6",
            },
        [12041704] = {
            ["Content"] = "这钟平时很少敲响吗？",
            ["ContentJP"] = "滅多に鳴らないんですか？",
            ["DialogueId"] = 12041704,
            ["GUID"] = "1E252810",
            ["NextDialogue"] = 12041705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252810",
            },
        [12041705] = {
            ["Content"] = "何止是少有？我活了大半辈子，就从未听到它响起过！",
            ["ContentJP"] = "滅多どころか、この歳になるまで一度も聞いたことがない。",
            ["DialogueId"] = 12041705,
            ["GUID"] = "1E25283A",
            ["NextDialogue"] = 12041706,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25283A",
            },
        [12041706] = {
            ["Content"] = "哎？！那是发生了什么大事吗？",
            ["ContentJP"] = "へ！？じゃあ、もしかして何か大事件が！？",
            ["DialogueId"] = 12041706,
            ["GUID"] = "1E252864",
            ["NextDialogue"] = 12041707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252864",
            },
        [12041707] = {
            ["Content"] = "冰湖城进行军事演练的时候，就会在全城响起乌拉乌拉的刺耳警笛声，白每次听到都会吓一跳。这也是类似的情况吗？",
            ["ContentJP"] = "アイスレイク城で軍事演習するときも、街中に耳をつんざくサイレンが鳴り響くんだよ。スノウ、あれ鳴るたびビクッてなるけど……これもそういうやつ？",
            ["DialogueId"] = 12041707,
            ["GUID"] = "1E25288E",
            ["NextDialogue"] = 12041708,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25288E",
            },
        [12041708] = {
            ["Content"] = "被你这样一说……",
            ["ContentJP"] = "そう言われりゃ……思い出した。",
            ["DialogueId"] = 12041708,
            ["GUID"] = "1E2528B8",
            ["NextDialogue"] = 12041709,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2528B8",
            },
        [12041709] = {
            ["Content"] = "我祖父好像从他的曾祖父那里听说过，在上古时期，若是有罪情复杂难辨之人出现，执律阁顶的钟声就会鸣响。",
            ["ContentJP"] = "俺のじいさんが、そのまたじいさんから聞いた話だが……大昔、罪が複雑で裁きが難しい者が現れると、<Default note=\"text:しつりつかく\">執律閣</>の鐘が鳴ったらしい。",
            ["DialogueId"] = 12041709,
            ["GUID"] = "1E2528E2",
            ["NextDialogue"] = 12041710,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2528E2",
            },
        [12041710] = {
            ["Content"] = "届时，龙神将与凡人一起，于执律阁巅<H>辩法</>，共商案情。但这已经是少有人知的传闻了。",
            ["ContentJP"] = "その時は、龍神が人間と共に<Default note=\"text:しつりつかく\">執律閣</>の頂で<H>裁定</>し、真相を議したってな。……まあ、今じゃ知ってる奴もほとんどいない昔話だ。",
            ["DialogueId"] = 12041710,
            ["GUID"] = "1E25290C",
            ["NextDialogue"] = 12041711,
            ["RelatedWikiId"] = {
                [1] = 407013,
                },
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25290C",
            },
        [12041711] = {
            ["Content"] = "如今承蒙大风九章荫蔽，华胥海晏河清，罪徒早就被那狴犴降服了，哪里还用得着这老掉牙的辩法。",
            ["ContentJP"] = "今は<Default note=\"text:たいふうきゅうしょう\">大風九章</>のおかげで平和そのもの。悪党なんざとっくに<Default note=\"text:ビーアン\">狴犴</>に捕まってるから、そんな古臭いやり方は必要ないはずだ。",
            ["DialogueId"] = 12041711,
            ["GUID"] = "1E252936",
            ["NextDialogue"] = 12041712,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252936",
            },
        [12041712] = {
            ["Content"] = "嗐，尽在这瞎想也没用。无论内情如何，都会有相关榜文张贴在执律阁前广场的告示板上。想必那白纸黑字，比我在这儿空口无凭来得有用。",
            ["ContentJP"] = "まあ考えても仕方ない。事情がどうであれ、<Default note=\"text:しつりつかく\">執律閣</>前の広場にある告示板にお触れが出るだろう。あれの方が、俺の与太話より確かだよ。",
            ["DialogueId"] = 12041712,
            ["GUID"] = "1E252960",
            ["NextDialogue"] = 12041713,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E252960",
            },
        [12041713] = {
            ["Content"] = "执律阁前广场……啊，小仆从，那我们岂不是刚好顺路？",
            ["ContentJP"] = "<Default note=\"text:しつりつかく\">執律閣</>前の広場……ちょうど通り道じゃん！",
            ["DialogueId"] = 12041713,
            ["GUID"] = "1E25298A",
            ["NextDialogue"] = 12041714,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E25298A",
            },
        [12041714] = {
            ["Content"] = "去吧去吧，年轻人就是好奇心重。我一把老骨头，就不跟你们去凑热闹了。",
            ["ContentJP"] = "おうおう、若いもんは好奇心旺盛でいいな。俺は年寄りだから、ここでのんびりしてるよ。",
            ["DialogueId"] = 12041714,
            ["GUID"] = "1E2529B4",
            ["NextDialogue"] = 12041715,
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2529B4",
            },
        [12041715] = {
            ["Content"] = "只希望，这次可别出什么大事哟……",
            ["ContentJP"] = "……何も大事が起きなきゃいいがな。",
            ["DialogueId"] = 12041715,
            ["GUID"] = "1E2529DE",
            ["SpeakNpcId"] = 240009,
            ["VoiceName"] = "voice/$Locale$/story/1204/120417/1E2529DE",
            },
        [12041801] = {
            ["Content"] = "\"……竟然……",
            ["ContentJP"] = "……なんと……",
            ["DialogueId"] = 12041801,
            ["GUID"] = "1E2537FA",
            ["NextDialogue"] = 12041803,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 407009,
                [5] = 407013,
                [6] = 304003,
                },
            ["SpeakNpcId"] = 240004,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2537FA",
            },
        [12041803] = {
            ["Content"] = "\"……闻所未闻……",
            ["ContentJP"] = "……前代未聞だ……",
            ["DialogueId"] = 12041803,
            ["GUID"] = "1E25384E",
            ["NextDialogue"] = 12041805,
            ["SpeakNpcId"] = 240005,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E25384E",
            },
        [12041805] = {
            ["Content"] = "……罪大恶极……这是他应得的……",
            ["ContentJP"] = "……なんと極悪非道な……当然の報いだ……",
            ["DialogueId"] = 12041805,
            ["GUID"] = "1E2538A2",
            ["NextDialogue"] = 12041806,
            ["SpeakNpcId"] = 240006,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2538A2",
            },
        [12041806] = {
            ["Content"] = "前面都被他们挡住了，什么都看不见……",
            ["ContentJP"] = "前が人で塞がってて、全然見えない……",
            ["DialogueId"] = 12041806,
            ["GUID"] = "1E2538CC",
            ["NextDialogue"] = 12041807,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2538CC",
            },
        }
  end },
  { MinKey = 12041807, MaxKey = 12043326, Loader = function()
      return {
        [12041807] = {
            ["Content"] = "可恶！看我原地霹雳闪电跳！",
            ["ContentJP"] = "よし！こうなったら……必殺・魔王ジャンプ！",
            ["DialogueId"] = 12041807,
            ["GUID"] = "1E2538F6",
            ["NextDialogue"] = 12041808,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2538F6",
            },
        [12041808] = {
            ["Content"] = "在人群的推挤中，你努力踮起脚，往前看去。",
            ["ContentJP"] = "押し寄せる人波の中、つま先立ちになって必死に覗き込む。",
            ["DialogueId"] = 12041808,
            ["GUID"] = "1E253920",
            ["NextDialogue"] = 12041809,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E253920",
            },
        [12041809] = {
            ["Content"] = "视线好不容易越过人群，捕捉到了告示板上的内容。画像中熟悉的面容却让你和白齐齐一惊。",
            ["ContentJP"] = "そして、ようやく見えたその顔に、あなたとスノウは同時に息を呑んだ。",
            ["DialogueId"] = 12041809,
            ["GUID"] = "1E25394A",
            ["NextDialogue"] = 12041810,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E25394A",
            },
        [12041810] = {
            ["Content"] = "怎么是他？！",
            ["ContentJP"] = "あの人って……！",
            ["DialogueId"] = 12041810,
            ["GUID"] = "1E253974",
            ["RelatedWikiId"] = {
                [1] = 203007,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuJueBai",
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E253974",
            },
        [12041901] = {
            ["Content"] = "怎么，终于忍不住露面了？",
            ["ContentJP"] = "おや、ようやく顔を出す気になったか？",
            ["DialogueId"] = 12041901,
            ["GUID"] = "1E254862",
            ["NextDialogue"] = 12041902,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 405010,
                [3] = 304003,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254862",
            },
        [12041902] = {
            ["Content"] = "……鲜廉寡耻之徒。",
            ["ContentJP"] = "……恥知らずめ。",
            ["DialogueId"] = 12041902,
            ["GUID"] = "1E25488C",
            ["NextDialogue"] = 12041903,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E25488C",
            },
        [12041903] = {
            ["Content"] = "尔等飘零人，本为天理所不容。因你们踪迹难寻，才暂且教你们苟且偷生。",
            ["ContentJP"] = "貴様ら流れ者は天理に背く存在。本来ならとっくに滅ぼすべきだったが、居所が掴めぬゆえ放置していただけだ。",
            ["DialogueId"] = 12041903,
            ["GUID"] = "1E2548B6",
            ["NextDialogue"] = 12041904,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2548B6",
            },
        [12041904] = {
            ["Content"] = "如今竟自投罗网，当真以为大风九章的律法宽松至此，容得下你们这些人了？",
            ["ContentJP"] = "それが自ら罠に飛び込むとは……大風九章の法も随分なめられたものだ。",
            ["DialogueId"] = 12041904,
            ["GUID"] = "1E2548E0",
            ["NextDialogue"] = 12041905,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2548E0",
            },
        [12041905] = {
            ["Content"] = "哈哈……同僚都被击倒了，说这些大话，不觉得太早了吗？",
            ["ContentJP"] = "ハハ……仲間を全部倒されてまだそんな口を利くか。",
            ["DialogueId"] = 12041905,
            ["GUID"] = "1E25490A",
            ["NextDialogue"] = 12041906,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E25490A",
            },
        [12041906] = {
            ["Content"] = "纵使你击退了这数十狴犴，又能说明什么？",
            ["ContentJP"] = "数十の<Default note=\"text:ビーアン\">狴犴</>を退けたところで、何の証にもならぬ。",
            ["DialogueId"] = 12041906,
            ["GUID"] = "1E254934",
            ["NextDialogue"] = 12041907,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254934",
            },
        [12041907] = {
            ["Content"] = "但凡大风九章高悬一日，我等代行者便将前仆后继，不死不息，直至天理昭彰，尔等伏法方休。",
            ["ContentJP"] = "大風九章の秩序がある限り、我らは命尽きるまで貴様らを追い詰め、天理の下に裁きを下す。",
            ["DialogueId"] = 12041907,
            ["GUID"] = "1E25495E",
            ["NextDialogue"] = 12041908,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E25495E",
            },
        [12041908] = {
            ["Content"] = "以你一人之力，莫非还能敌得过大风九章天命之力？",
            ["ContentJP"] = "その身一つで、天命の力に抗えるとでも？",
            ["DialogueId"] = 12041908,
            ["GUID"] = "1E254988",
            ["NextDialogue"] = 12041909,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254988",
            },
        [12041909] = {
            ["Content"] = "说得好！",
            ["ContentJP"] = "いいねぇ、その意気だ！",
            ["DialogueId"] = 12041909,
            ["GUID"] = "1E2549B2",
            ["NextDialogue"] = 12041910,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2549B2",
            },
        [12041910] = {
            ["Content"] = "干架是很痛快，可惜总是干架也解决不了事情。今天倒是要委屈我这把老伙计了。",
            ["ContentJP"] = "戦うのは楽しいが、斬るだけじゃ話は進まねぇ。今日はこいつをちょいと休ませてやるか。",
            ["DialogueId"] = 12041910,
            ["GUID"] = "1E2549DC",
            ["NextDialogue"] = 12041911,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E2549DC",
            },
        [12041911] = {
            ["Content"] = "喂，对面的，你也别紧张了，放轻松点。",
            ["ContentJP"] = "おい、そんな肩肘張んな。気楽にいこうぜ。",
            ["DialogueId"] = 12041911,
            ["GUID"] = "1E254A06",
            ["NextDialogue"] = 12041912,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A06",
            },
        [12041912] = {
            ["Content"] = "我刻舟，行不改名坐不改姓，这次是来申请<H>辩法</>的。",
            ["ContentJP"] = "俺はカシュウ。名も立場も隠す気はねぇ。今日は<H>裁定</>を申し込みに来た。",
            ["DialogueId"] = 12041912,
            ["GUID"] = "1E254A30",
            ["NextDialogue"] = 12041913,
            ["RelatedWikiId"] = {
                [1] = 407013,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A30",
            },
        [12041913] = {
            ["Content"] = "<H>辩法</>……？",
            ["ContentJP"] = "<H>裁定</>だと……？",
            ["DialogueId"] = 12041913,
            ["GUID"] = "1E254A5A",
            ["NextDialogue"] = 12041914,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A5A",
            },
        [12041914] = {
            ["Content"] = "你既然知晓这沉寂已久的上古礼法，便应当了解，如今的辩法已经名存实亡。",
            ["ContentJP"] = "その古き儀を知っているなら、既に形骸化していることも承知していよう。",
            ["DialogueId"] = 12041914,
            ["GUID"] = "1E254A84",
            ["NextDialogue"] = 12041915,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254A84",
            },
        [12041915] = {
            ["Content"] = "凡人早已将裁决的权力托付给神明，而白龙神君的意志一以贯之。于尔等狂徒而言，下场唯有伏诛。",
            ["ContentJP"] = "人の裁きは久しく神に委ねられ、白龍様の御心こそが絶対。貴様の末路はただ一つ、死あるのみ。",
            ["DialogueId"] = 12041915,
            ["GUID"] = "1E254AAE",
            ["NextDialogue"] = 12041916,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254AAE",
            },
        [12041916] = {
            ["Content"] = "哈哈！这种事情，不试上一试怎么知道？",
            ["ContentJP"] = "ハッ！やってみなきゃ分からねぇだろ。",
            ["DialogueId"] = 12041916,
            ["GUID"] = "1E254AD8",
            ["NextDialogue"] = 12041917,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254AD8",
            },
        [12041917] = {
            ["Content"] = "我刻舟自觉无罪。如今甘愿束手就擒，走上一趟程序，你也没有拒绝的理由吧？",
            ["ContentJP"] = "俺は無実だ。手順通りに捕まってやる。拒む理由はねぇよな？",
            ["DialogueId"] = 12041917,
            ["GUID"] = "1E254B02",
            ["NextDialogue"] = 12041918,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254B02",
            },
        [12041918] = {
            ["Content"] = "……呵。你执意赴死，我自当奉陪。",
            ["ContentJP"] = "……ふん。死地に飛び込むというなら、相手をしてやろう。",
            ["DialogueId"] = 12041918,
            ["GUID"] = "1E254B2C",
            ["NextDialogue"] = 12041919,
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254B2C",
            },
        [12041919] = {
            ["Content"] = "剑，交出来吧。",
            ["ContentJP"] = "剣を渡せ。",
            ["DialogueId"] = 12041919,
            ["GUID"] = "1E254B56",
            ["SpeakNpcId"] = 240103,
            ["VoiceName"] = "voice/$Locale$/story/1204/120419/1E254B56",
            },
        [12042001] = {
            ["Content"] = "“今有案犯刻舟，不服判决，审议辩法。定于公示次日午时，执律阁巅，叩准陈情圣裁。若情实无疑，则当场诛灭。”",
            ["ContentJP"] = "「本日、<Default note=\"text:とがにん\">科人</>カシュウ、御沙汰に不服の旨を申し立てにつき、裁定の儀、明日<Default note=\"text:うま\">午</>の刻、\
<Default note=\"text:しつりつかく\">執律閣</>頂上において執行いたすべし。\
右につき、当人を召し出し、<Default note=\"text:しんめいちんべん\">申明陳弁</>いたさしむ。\
もし罪状明白の趣あい立たば、その場において直ちに死罪に処すべし。」",
            ["DialogueId"] = 12042001,
            ["GUID"] = "1E2558CA",
            ["NextDialogue"] = 12042002,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 407009,
                [3] = 407013,
                },
            ["SpeakNpcId"] = 240004,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E2558CA",
            },
        [12042002] = {
            ["Content"] = "“此示晓谕，各宜凛遵！”",
            ["ContentJP"] = "「右の触、胸に銘じ、したがうべし。」",
            ["DialogueId"] = 12042002,
            ["GUID"] = "1E2558F4",
            ["NextDialogue"] = 12042003,
            ["SpeakNpcId"] = 240004,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E2558F4",
            },
        [12042003] = {
            ["Content"] = "嚯，这么吓人！这个刻舟，不就是我们之前在听鸦原见过一面的那家伙吗？竟然还是个熟人。",
            ["ContentJP"] = "……ひえぇ、物騒だな！カシュウって、あの<Default note=\"text:からすのこげん\">鴉の孤原</>で会った人だよね？まさかの知り合いじゃん。",
            ["DialogueId"] = 12042003,
            ["GUID"] = "1E25591E",
            ["NextDialogue"] = 12042004,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E25591E",
            },
        [12042004] = {
            ["Content"] = "就是不知道他到底犯下了什么罪，画像都被放上通缉令了……",
            ["ContentJP"] = "でも何やらかしたんだろ……指名手配までされちゃってるし。",
            ["DialogueId"] = 12042004,
            ["GUID"] = "1E255948",
            ["NextDialogue"] = 12042005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E255948",
            },
        [12042005] = {
            ["Content"] = "……白，这里人太多了。我们去找个僻静的地方，我有话要和你说。",
            ["ContentJP"] = "……スノウ、ここは人が多すぎる。ちょっと静かな場所に移動しよう、話がある。",
            ["DialogueId"] = 12042005,
            ["GUID"] = "1E255972",
            ["NextDialogue"] = 12042006,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E255972",
            },
        [12042006] = {
            ["Content"] = "哎？搞得这么神秘兮兮的……哼哼，你成功勾起了我的兴趣！",
            ["ContentJP"] = "おっと、なんか秘密めいてきたな……ふふん、興味わいてきちゃった！",
            ["DialogueId"] = 12042006,
            ["GUID"] = "1E25599C",
            ["NextDialogue"] = 12042007,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E25599C",
            },
        [12042007] = {
            ["Content"] = "那，我们去那片树荫底下。那里看起来比较适合说悄悄话。",
            ["ContentJP"] = "じゃ、あの木陰に行こう。あそこなら人目もないし。",
            ["DialogueId"] = 12042007,
            ["GUID"] = "1E2559C6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120420/1E2559C6",
            },
        [12042101] = {
            ["Content"] = "好啦，旁边都没有人。小仆从，有什么话，你就放心大胆地说吧。",
            ["ContentJP"] = "よし、誰もいないね。さあ、我が下僕、思いっきり話しなさいな。",
            ["DialogueId"] = 12042101,
            ["GUID"] = "1E256932",
            ["NextDialogue"] = 12042102,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 407009,
                [3] = 407013,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256932",
            },
        [12042102] = {
            ["Content"] = "白，听我说。那个刻舟……我们得想办法去救他。",
            ["ContentJP"] = "その…………カシュウを助けたい。",
            ["DialogueId"] = 12042102,
            ["GUID"] = "1E25695C",
            ["NextDialogue"] = 12042103,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E25695C",
            },
        [12042103] = {
            ["Content"] = "哎？！",
            ["ContentJP"] = "へっ？",
            ["DialogueId"] = 12042103,
            ["GUID"] = "1E256986",
            ["NextDialogue"] = 12042104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256986",
            },
        [12042104] = {
            ["Content"] = "倒不是我不愿意啦……小仆从，我们和那家伙的交情有好到那个程度吗？",
            ["ContentJP"] = "いや、別に反対じゃないけどさ……私たち、あの人とそこまで仲良かったっけ？",
            ["DialogueId"] = 12042104,
            ["GUID"] = "1E2569B0",
            ["NextDialogue"] = 12042105,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E2569B0",
            },
        [12042105] = {
            ["Content"] = "只是曾经在听鸦原见过一面而已，虽然他说话挺有意思的，但好像还犯不着为他这么冒险吧……",
            ["ContentJP"] = "鴉の孤原で少し話したくらいじゃん。面白い人だったけど、命懸けで助けるほどかって言われると……",
            ["DialogueId"] = 12042105,
            ["GUID"] = "1E2569DA",
            ["NextDialogue"] = 12042106,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E2569DA",
            },
        [12042106] = {
            ["Content"] = "刚刚看到那张画像的时候，我的脑海中突然闪过一个念头：我们曾经和他在某处，一起商量过某些非常重要的事情。但更具体的，我都想不起来了。",
            ["ContentJP"] = "あの指名手配書を見た瞬間、頭に一瞬だけ何かがよぎった。前に彼と一緒に、すごく大事なことを相談してた気がする。でも、それ以上思い出せないんだ。",
            ["DialogueId"] = 12042106,
            ["GUID"] = "1E256A04",
            ["NextDialogue"] = 12042107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A04",
            },
        [12042107] = {
            ["Content"] = "白，从今天早上开始，我一直若隐若现地觉得不太对劲，我不知道你有没有相同的感受……好像有什么很紧迫的事情被我们忘在脑后了。",
            ["ContentJP"] = "それに……今朝から、何か妙な気がするんだ。そう思わない？胸の奥で急かされるような感覚があるのに、肝心なことが思い出せない。",
            ["DialogueId"] = 12042107,
            ["GUID"] = "1E256A2E",
            ["NextDialogue"] = 12042108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A2E",
            },
        [12042108] = {
            ["Content"] = "我一直说不出哪里不对劲，直到刚刚看到那张画像为止。我有一种预感，找到他可能是解开这个谜题的关键。",
            ["ContentJP"] = "さっきカシュウの顔を見て、やっと確信した。彼を見つけることが、この謎を解く鍵かもしれない。",
            ["DialogueId"] = 12042108,
            ["GUID"] = "1E256A58",
            ["NextDialogue"] = 12042109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A58",
            },
        [12042109] = {
            ["Content"] = "不、对、对对、劲劲劲劲劲？",
            ["ContentJP"] = "み、ミミ妙…な感ジ……？",
            ["DialogueId"] = 12042109,
            ["GUID"] = "1E256A82",
            ["NextDialogue"] = 12042110,
            ["SnapShot"] = "ELECTRIC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256A82",
            },
        [12042110] = {
            ["Content"] = "白，你刚才……",
            ["ContentJP"] = "スノウ、今……何て？",
            ["DialogueId"] = 12042110,
            ["GUID"] = "1E256AAC",
            ["NextDialogue"] = 12042111,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256AAC",
            },
        [12042111] = {
            ["Content"] = "我刚刚？哎，我，我怎么会那样子说话？！",
            ["ContentJP"] = "えっ、私？え、あれ？私、どうしちゃったんだろ！？",
            ["DialogueId"] = 12042111,
            ["GUID"] = "1E256AD6",
            ["NextDialogue"] = 12042112,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256AD6",
            },
        [12042112] = {
            ["Content"] = "难道说，真像小仆从你说的那样，我们身上发生了什么奇怪的事情？这该不会是中邪，或者被诅咒了吧？！",
            ["ContentJP"] = "もしかして……下僕の言う通り、私たちの身に本当に何か起こってる……？例えば呪いとか！？",
            ["DialogueId"] = 12042112,
            ["GUID"] = "1E256B00",
            ["NextDialogue"] = 12042113,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B00",
            },
        [12042113] = {
            ["Content"] = "冒险小说里就有那种躲在沼泽里，发出阴森笑声的老巫婆，会一边搅着咕噜咕噜冒泡的药水，一边给别人下诅咒。难不成华胥也有？",
            ["ContentJP"] = "ほら、冒険小説に出てくる、沼地に住む魔女が、鍋をぐつぐつ煮ながら呪いをかける……みたいな。まさか華胥にもそういうのいるの？",
            ["DialogueId"] = 12042113,
            ["GUID"] = "1E256B2A",
            ["NextDialogue"] = 12042114,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B2A",
            },
        [12042114] = {
            ["Content"] = "虽然冒险小说大部分都是杜撰……不过这种可能性倒也不能排除。",
            ["ContentJP"] = "まあ、作り話が多いけど……完全に否定はできない{性别:な|ね}。",
            ["DialogueId"] = 12042114,
            ["GUID"] = "1E256B54",
            ["NextDialogue"] = 12042115,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B54",
            },
        [12042115] = {
            ["Content"] = "哇，想想就后背发凉……！那，小仆从，我支持你的决定！",
            ["ContentJP"] = "うわぁ、考えたらゾクッとする……よし下僕の言う通り、カシュウを助けに行こう！",
            ["DialogueId"] = 12042115,
            ["GUID"] = "1E256B7E",
            ["NextDialogue"] = 12042116,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256B7E",
            },
        [12042116] = {
            ["Content"] = "海伯利亚的军团我们都交手过好几次了，这样想想，到执律阁顶兜一圈，好像也不是什么大不了的事情嘛。",
            ["ContentJP"] = "ヒュペリアの帝国軍とも何度もやり合ってきたし、<Default note=\"text:しつりつかく\">執律閣</>の頂上だって大したことないでしょ。",
            ["DialogueId"] = 12042116,
            ["GUID"] = "1E256BA8",
            ["NextDialogue"] = 12042117,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256BA8",
            },
        [12042117] = {
            ["Content"] = "有信心是好事……不过我们要去的毕竟是华胥的重地，还是谨慎对待为好。",
            ["ContentJP"] = "気合はいいけど、行き先は華胥の中枢だ{性别:|よ}。慎重に動こう。",
            ["DialogueId"] = 12042117,
            ["GUID"] = "1E256BD2",
            ["NextDialogue"] = 12042118,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256BD2",
            },
        [12042118] = {
            ["Content"] = "唔……你说得对！榜文上写了“明日午时辩法”。我们在那之前做好准备，再进去吧。",
            ["ContentJP"] = "……そうだね。お触れに「裁定の儀は明日<Default note=\"text:うま\">午</>の刻に」って書いてあったし、それまでに準備を整えてから入ろ。",
            ["DialogueId"] = 12042118,
            ["GUID"] = "1E256BFC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120421/1E256BFC",
            },
        [12042201] = {
            ["Content"] = "（即将开始连续剧情内容，建议做好充分准备后进行体验。）",
            ["ContentJP"] = "（まもなく連続したストーリーが始まります。十分な準備を整えてから先に進みましょう）",
            ["DialogueId"] = 12042201,
            ["GUID"] = "1E25799A",
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120422/1E25799A",
            },
        [12042202] = {
            ["Content"] = "准备好了",
            ["ContentJP"] = "準備できた。",
            ["DialogueId"] = 12042202,
            ["GUID"] = "1E2579C4",
            },
        [12042203] = {
            ["Content"] = "再准备一下",
            ["ContentJP"] = "まだだ。",
            ["DialogueId"] = 12042203,
            ["GUID"] = "1E2579EE",
            },
        [12042301] = {
            ["Content"] = "烦请两位出示通行信物。",
            ["ContentJP"] = "通行証をお見せください。",
            ["DialogueId"] = 12042301,
            ["GUID"] = "1E258A02",
            ["SpeakNpcId"] = 240015,
            ["VoiceName"] = "voice/$Locale$/story/1204/120423/1E258A02",
            },
        [12042401] = {
            ["Content"] = "您好，我们是替止流掌柜来递交奉香大典所需的器具的。",
            ["ContentJP"] = "こんにちは。シリュウさんの使いで、<Default note=\"text:ほうこうのぎ\">奉香の儀</>に使う品をお届けに参りました。",
            ["DialogueId"] = 12042401,
            ["GUID"] = "1E259A6A",
            ["NextDialogue"] = 12042402,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 407009,
                [3] = 407013,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259A6A",
            },
        [12042402] = {
            ["Content"] = "奉香炉、皓烟香、绸布……清点完毕了，与清单上一致，多谢。辛苦你们跑这一趟了。",
            ["ContentJP"] = "奉香炉、<Default note=\"text:こうえんこう\">皓煙香</>、絹布……はい、すべて確認しました。ご協力ありがとうございました。",
            ["DialogueId"] = 12042402,
            ["GUID"] = "1E259A94",
            ["NextDialogue"] = 12042403,
            ["SpeakNpcId"] = 240016,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259A94",
            },
        [12042403] = {
            ["Content"] = "姐姐，我们难得来一趟，可以在这四处逛逛吗？",
            ["ContentJP"] = "ねえねえ、お姉さん！せっかく来たんだし、この辺りを見て回ってもいい？",
            ["DialogueId"] = 12042403,
            ["GUID"] = "1E259ABE",
            ["NextDialogue"] = 12042404,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259ABE",
            },
        [12042404] = {
            ["Content"] = "两位来得不巧。今日执律阁顶从午时起封闭，期间一切无关人员禁止出入。",
            ["ContentJP"] = "あいにく、本日<Default note=\"text:うま\">午</>の刻から最上階は封鎖中でして、関係者以外は立ち入りできません。",
            ["DialogueId"] = 12042404,
            ["GUID"] = "1E259AE8",
            ["NextDialogue"] = 12042405,
            ["SpeakNpcId"] = 240016,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259AE8",
            },
        [12042405] = {
            ["Content"] = "不过……远道而来即为客。大厅之中你们可以随意走动参观，只要不上两侧的楼梯便好。",
            ["ContentJP"] = "……とはいえ、遠路はるばるお越しいただいたお客様ですし、大広間ならご自由にご覧ください。\
ただし、両側の階段には上らないようお願いします。",
            ["DialogueId"] = 12042405,
            ["GUID"] = "1E259B12",
            ["NextDialogue"] = 12042406,
            ["SpeakNpcId"] = 240016,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259B12",
            },
        [12042406] = {
            ["Content"] = "嗯，我们明白啦！谢谢姐姐！",
            ["ContentJP"] = "わかったぞ！ありがと、お姉さん！",
            ["DialogueId"] = 12042406,
            ["GUID"] = "1E259B3C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120424/1E259B3C",
            },
        [12042501] = {
            ["Content"] = "前方禁地，阁下请止步。",
            ["ContentJP"] = "この先は立入禁止です。お下がりください。",
            ["DialogueId"] = 12042501,
            ["GUID"] = "1E25AAD2",
            ["SpeakNpcId"] = 240017,
            ["VoiceName"] = "voice/$Locale$/story/1204/120425/1E25AAD2",
            },
        [12042601] = {
            ["Content"] = "怎么办，小仆从，完全找不到突破口……",
            ["ContentJP"] = "どうする、下僕……",
            ["DialogueId"] = 12042601,
            ["GUID"] = "1E25BB3A",
            ["NextDialogue"] = 12042602,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BB3A",
            },
        [12042602] = {
            ["Content"] = "这里也太空旷了，那些守卫一眼就能看穿我们的小动作，都不好偷偷溜进去了。",
            ["ContentJP"] = "こんな人目のつくとこじゃ、ちょっとの動きでも守衛に丸見えで、こっそり入り込むのは無理だし……",
            ["DialogueId"] = 12042602,
            ["GUID"] = "1E25BB64",
            ["NextDialogue"] = 12042603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BB64",
            },
        [12042603] = {
            ["Content"] = "哔——哔——",
            ["ContentJP"] = "ビッ――ビッ――",
            ["DialogueId"] = 12042603,
            ["GUID"] = "1E25BB8E",
            ["NextDialogue"] = 12042604,
            ["SpeakNpcId"] = 240020,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BB8E",
            },
        [12042604] = {
            ["Content"] = "哪儿来的声音？",
            ["ContentJP"] = "な、何この音！？",
            ["DialogueId"] = 12042604,
            ["GUID"] = "1E25BBB8",
            ["NextDialogue"] = 12042605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BBB8",
            },
        [12042605] = {
            ["Content"] = "薛兄，那机傀从早上起便频频无端作响，怕是损耗已久，该修理了。",
            ["ContentJP"] = "セツさん、あのからくり人形、朝から頻繁に変な音を出してますな。だいぶガタが来てるようで。修理したほうがいいかと。",
            ["DialogueId"] = 12042605,
            ["GUID"] = "1E25BBE2",
            ["NextDialogue"] = 12042606,
            ["SpeakNpcId"] = 240018,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BBE2",
            },
        [12042606] = {
            ["Content"] = "嗯。今日轮值结束后，顺手将其交给匠矩阁吧。",
            ["ContentJP"] = "ああ。今日の勤務が終わったら、<Default note=\"text:しょうくかく\">匠矩閣</>に持っていこう。",
            ["DialogueId"] = 12042606,
            ["GUID"] = "1E25BC0C",
            ["NextDialogue"] = 12042607,
            ["SpeakNpcId"] = 240019,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BC0C",
            },
        [12042607] = {
            ["Content"] = "……白，我有想法了。",
            ["ContentJP"] = "……スノウ、ちょっといい考えを思いついたかも。",
            ["DialogueId"] = 12042607,
            ["GUID"] = "1E25BC36",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120426/1E25BC36",
            },
        [12042701] = {
            ["Content"] = "哔——哔——枢轮啮日月，铁骨镇山河——",
            ["ContentJP"] = "ビッ――ビッ――枢輪は日月を噛み、鉄骨は山河を鎮める――",
            ["DialogueId"] = 12042701,
            ["GUID"] = "1E25CBA2",
            ["NextDialogue"] = 12042702,
            ["SpeakNpcId"] = 240020,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CBA2",
            },
        [12042702] = {
            ["Content"] = "……薛兄，机傀竟自己启动了！",
            ["ContentJP"] = "へ……？からくり人形が勝手に動き出しましたと！？",
            ["DialogueId"] = 12042702,
            ["GUID"] = "1E25CBCC",
            ["NextDialogue"] = 12042703,
            ["SpeakNpcId"] = 240018,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CBCC",
            },
        [12042703] = {
            ["Content"] = "哔——犯界者，齑灭于此——",
            ["ContentJP"] = "ビッ――境を犯す者は、此処で灰となれ――",
            ["DialogueId"] = 12042703,
            ["GUID"] = "1E25CBF6",
            ["NextDialogue"] = 12042704,
            ["SpeakNpcId"] = 240020,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CBF6",
            },
        [12042704] = {
            ["Content"] = "糟糕！看它前进的方向，执律阁的内饰都要被殃及！赶紧去阻止它！",
            ["ContentJP"] = "まずい！このままじゃ<Default note=\"text:しつりつかく\">執律閣</>の中がメチャクチャになる！急いで止めろ！",
            ["DialogueId"] = 12042704,
            ["GUID"] = "1E25CC20",
            ["NextDialogue"] = 12042705,
            ["SpeakNpcId"] = 240019,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CC20",
            },
        [12042705] = {
            ["Content"] = "他们的注意力被吸引走了！小仆从，就趁现在！",
            ["ContentJP"] = "よし、今のうちに行くよ！",
            ["DialogueId"] = 12042705,
            ["GUID"] = "1E25CC4A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120427/1E25CC4A",
            },
        [12042801] = {
            ["Content"] = "白龙神君，要见上你一面可真是费劲啊……你给我听好了，今天我来这里，是为了——",
            ["ContentJP"] = "白龍さん、あんたに会うのは骨が折れたぜ……いいか、あんたに言いたいことがあってな――",
            ["DialogueId"] = 12042801,
            ["GUID"] = "1E25DC0A",
            ["NextDialogue"] = 12042802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 303008,
                [3] = 407009,
                [4] = 407013,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC0A",
            },
        [12042802] = {
            ["Content"] = "耻笑你。",
            ["ContentJP"] = "あんた、実に滑稽なやつだな。",
            ["DialogueId"] = 12042802,
            ["GUID"] = "1E25DC34",
            ["NextDialogue"] = 12042803,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC34",
            },
        [12042803] = {
            ["Content"] = "我笑你自蔽双眼，但见那匪徒施暴无辜者，竟不能即刻阻止，枉受众生供奉。",
            ["ContentJP"] = "目を閉ざし、悪党が無罪の民を痛めつけてもすぐ止めようともしねぇ。祀るに値せぬにもほどがある。",
            ["DialogueId"] = 12042803,
            ["GUID"] = "1E25DC5E",
            ["NextDialogue"] = 12042804,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC5E",
            },
        [12042804] = {
            ["Content"] = "我笑你好歹不分，有侠士杀贼寇为民除害，却判其杀生之罪，谈何正义之名？",
            ["ContentJP"] = "悪と善の区別もつかず、賊を討った<Default note=\"text:おとこだて\">侠</>を罪人扱いする、何という腐った正義だ。",
            ["DialogueId"] = 12042804,
            ["GUID"] = "1E25DC88",
            ["NextDialogue"] = 12042805,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DC88",
            },
        [12042805] = {
            ["Content"] = "我刻舟自习武以来，行侠仗义，惩奸除恶，从未将剑尖对准过一个好人。却因制止一起强盗路劫，日日受狴犴追猎不休。",
            ["ContentJP"] = "俺は剣を取って以来、悪党しか斬っちゃいねぇ。強盗を止めただけで、日々狴犴に追われる身になった。",
            ["DialogueId"] = 12042805,
            ["GUID"] = "1E25DCB2",
            ["NextDialogue"] = 12042806,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DCB2",
            },
        [12042806] = {
            ["Content"] = "伸张正义，究竟何罪之有？",
            ["ContentJP"] = "正義を通すことに、なんの罪がある？",
            ["DialogueId"] = 12042806,
            ["GUID"] = "1E25DCDC",
            ["NextDialogue"] = 12042807,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DCDC",
            },
        [12042807] = {
            ["Content"] = "尔等口口声声为伸张正义，然私欲邪，大义邪？凡人行事，只在一念之差。",
            ["ContentJP"] = "正義を掲げるその言葉——果たして私欲か、大義か？人の振る舞いなど、心ひとつで善にも悪にも転ずるものなり。",
            ["DialogueId"] = 12042807,
            ["GUID"] = "1E25DD06",
            ["NextDialogue"] = 12042808,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD06",
            },
        [12042808] = {
            ["Content"] = "以心定法，则纲常崩毁，国将不国。",
            ["ContentJP"] = "心を法とすれば、掟は崩れ、国は滅ぶ。",
            ["DialogueId"] = 12042808,
            ["GUID"] = "1E25DD30",
            ["NextDialogue"] = 12042809,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD30",
            },
        [12042809] = {
            ["Content"] = "罪愆自有天命律法定夺。以凡人之身生杀予夺，是为越俎代庖。",
            ["ContentJP"] = "罪を裁くのは天命の律法。凡人が<Default note=\"text:せいさつよだつ\">生殺与奪</>を握るなど、僭越の極み。",
            ["DialogueId"] = 12042809,
            ["GUID"] = "1E25DD5A",
            ["NextDialogue"] = 12042810,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD5A",
            },
        [12042810] = {
            ["Content"] = "呵……意思是只有你认可的才是正义呗？我还以为你们神仙能有什么新鲜话，结果还是香官老儿们的陈词滥调，也罢。我自己的事先放一边。",
            ["ContentJP"] = "つまり、あんたが認めたものだけが正義ってわけだな。神様も、結局は役人と変わらねぇってわけか……まあいい、俺のことは後回しだ。",
            ["DialogueId"] = 12042810,
            ["GUID"] = "1E25DD84",
            ["NextDialogue"] = 12042811,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DD84",
            },
        [12042811] = {
            ["Content"] = "你让应天尉执你的法，可曾问过他们的意见？我那师兄煜明，为何要被你日夜役使，满手罪孽，不得解脱？",
            ["ContentJP"] = "お前は<Default note=\"text:おうてんい\">応天尉</>に法を執らせているが、その本人たちの意志は聞いたことがあるか？\
俺の兄弟弟子のユーミンが、なぜ日夜お前にこき使われ、罪にまみれたまま解放されないのだ？",
            ["DialogueId"] = 12042811,
            ["GUID"] = "1E25DDAE",
            ["NextDialogue"] = 12042812,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DDAE",
            },
        [12042812] = {
            ["Content"] = "大风九章之下，又为何常有不平之事？该死的人不死，正直之人却枉死！白龙，但凡你愿低头看看这世间的荒诞、错乱，便知我今日辩法为何！",
            ["ContentJP"] = "大風九章の下では、なぜ不正ばかりが生まれ、死ぬべき者は生き、正しき者が命を落とす？\
白龍よ、少しでも頭を垂れて、この世の荒れ様と理不尽を見下ろしてみろ。それが、俺が今日ここで理を問う理由だ！",
            ["DialogueId"] = 12042812,
            ["GUID"] = "1E25DDD8",
            ["NextDialogue"] = 12042813,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DDD8",
            },
        [12042813] = {
            ["Content"] = "不过是妄议天道，老生常谈。",
            ["ContentJP"] = "天道を <Default note=\"text:みだ\">妄</>りに語るは愚か。老いぼれた言葉にすぎぬ。",
            ["DialogueId"] = 12042813,
            ["GUID"] = "1E25DE02",
            ["NextDialogue"] = 12042814,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE02",
            },
        [12042814] = {
            ["Content"] = "凡人为心所累，受情所扰。法却清正自明，如昭昭天理。",
            ["ContentJP"] = "凡人は心に囚われ、情に惑う。だが法は清く明らかで、天理のごとく揺るがない。",
            ["DialogueId"] = 12042814,
            ["GUID"] = "1E25DE2C",
            ["NextDialogue"] = 12042815,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE2C",
            },
        [12042815] = {
            ["Content"] = "法无仁心，岂容怨戾撼分毫？",
            ["ContentJP"] = "法に情けは不要、怨みや怒りで揺らぐことはない。",
            ["DialogueId"] = 12042815,
            ["GUID"] = "1E25DE56",
            ["NextDialogue"] = 12042816,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE56",
            },
        [12042816] = {
            ["Content"] = "哈哈……好一个法无仁心。既然如此，也没什么好说的了。",
            ["ContentJP"] = "……なるほど、「法に情けは不要」か。ならもう言うことはない。",
            ["DialogueId"] = 12042816,
            ["GUID"] = "1E25DE80",
            ["NextDialogue"] = 12042817,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DE80",
            },
        [12042817] = {
            ["Content"] = "你这天道教我乞求天降正义，教我做羔羊，做胆小鬼，做摇尾乞怜的狗。很可惜，我不愿。",
            ["ContentJP"] = "お前の天道は、天からの正義を乞えと教え、羊のように従えと命じ、尻尾を振って生きろと言う。悪いが、俺は従わない。",
            ["DialogueId"] = 12042817,
            ["GUID"] = "1E25DEAA",
            ["NextDialogue"] = 12042818,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DEAA",
            },
        [12042818] = {
            ["Content"] = "因为爹娘和师父从小便要我挺直脊梁，做一个堂堂正正的人！",
            ["ContentJP"] = "俺の親も師匠も、まっすぐ背を伸ばし、胸を張って生きろと教えてくれたからな！",
            ["DialogueId"] = 12042818,
            ["GUID"] = "1E25DED4",
            ["NextDialogue"] = 12042819,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DED4",
            },
        [12042819] = {
            ["Content"] = "听了你的亲口回答，也不枉我走上这一回了。",
            ["ContentJP"] = "あんたの口から直接聞けただけでも、ここまで来た甲斐はあった。",
            ["DialogueId"] = 12042819,
            ["GUID"] = "1E25DEFE",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120428/1E25DEFE",
            },
        [12042901] = {
            ["Content"] = "呼……暂时安全了……",
            ["ContentJP"] = "……ふぅ、ひとまず安全かな……",
            ["DialogueId"] = 12042901,
            ["GUID"] = "1E25EC72",
            ["NextDialogue"] = 12042902,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203008,
                [3] = 303012,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EC72",
            },
        [12042902] = {
            ["Content"] = "多谢阁下，带我们逃出生天！",
            ["ContentJP"] = "助かったぜ。おかげで命拾いしたよ！",
            ["DialogueId"] = 12042902,
            ["GUID"] = "1E25EC9C",
            ["NextDialogue"] = 12042903,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EC9C",
            },
        [12042903] = {
            ["Content"] = "既然你帮了我们的忙，上次你遛着我和小仆从到处跑的事情，就不和你计较了。",
            ["ContentJP"] = "ま、あんたも助けてくれたことだし、この前、私と下僕を振り回したことは水に流してあげる！",
            ["DialogueId"] = 12042903,
            ["GUID"] = "1E25ECC6",
            ["NextDialogue"] = 12042904,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ECC6",
            },
        [12042904] = {
            ["Content"] = "嘻嘻……大梦谁先觉？平生我自知！不如逍遥～",
            ["ContentJP"] = "ふふ……大夢誰か先に覚む？平生我自ら知る！これぞ<Default note=\"text:しょうよう\">逍遥</>よ～",
            ["DialogueId"] = 12042904,
            ["GUID"] = "1E25ECF0",
            ["NextDialogue"] = 12042905,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ECF0",
            },
        [12042905] = {
            ["Content"] = "……哈哈，刚刚可真是好一出畅快淋漓的过招！不虚此行！",
            ["ContentJP"] = "……いやあ、さっきはまさに胸のすくような立ち回りだった！来た甲斐があったぜ！",
            ["DialogueId"] = 12042905,
            ["GUID"] = "1E25ED1A",
            ["NextDialogue"] = 12042906,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203008,
                [3] = 303012,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED1A",
            },
        [12042906] = {
            ["Content"] = "以后说出去，我刻舟也是与神明交手，最后全身而退、毫发无伤的传奇人士了！",
            ["ContentJP"] = "これで俺も「神と渡り合い、無傷で生還した男」として語り草になるってもんだ！",
            ["DialogueId"] = 12042906,
            ["GUID"] = "1E25ED44",
            ["NextDialogue"] = 12042907,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED44",
            },
        [12042907] = {
            ["Content"] = "当然，都是承蒙你出手相助。救命之恩，刻舟定不相忘。",
            ["ContentJP"] = "もちろん、全部あんたのおかげだ。恩は忘れねえ。",
            ["DialogueId"] = 12042907,
            ["GUID"] = "1E25ED6E",
            ["NextDialogue"] = 12042908,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED6E",
            },
        [12042908] = {
            ["Content"] = "喂喂，先别急着得意啊！到底都是怎么一回事？",
            ["ContentJP"] = "ちょっと！浮かれてないで説明しなさいよ！",
            ["DialogueId"] = 12042908,
            ["GUID"] = "1E25ED98",
            ["NextDialogue"] = 12042909,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25ED98",
            },
        [12042909] = {
            ["Content"] = "上次见你，可没看出你是个重刑犯……你、你都干过什么坏事啊！糟了，我和小仆从会不会有危……",
            ["ContentJP"] = "あんた、一体何やらかして捕まったの？私と下僕まで巻き込まれちゃったじゃんか！！",
            ["DialogueId"] = 12042909,
            ["GUID"] = "1E25EDC2",
            ["NextDialogue"] = 12042910,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EDC2",
            },
        [12042910] = {
            ["Content"] = "喂喂，你这话说的，像是我是什么大奸大恶之徒一样。咳……既然你好奇，那我再重新做个自我介绍吧。",
            ["ContentJP"] = "おいおい、その言い方、まるで俺が極悪人みたいじゃねえか。……まあいい、改めて自己紹介しようじゃねえか。",
            ["DialogueId"] = 12042910,
            ["GUID"] = "1E25EDEC",
            ["NextDialogue"] = 12042911,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EDEC",
            },
        [12042911] = {
            ["Content"] = "拒不随波逐流，飘零世事之外，仅为心中一杆尺而行。以天为被，以地为席，仗剑日月间，专管不平事——华胥<H>飘零人</>，刻舟！怎么样，是不是很拉风？",
            ["ContentJP"] = "流れに背を向け、世のしがらみを捨て、心の物差しだけを頼りに生きる。\
天地を舞台に、剣を振るい、昼夜問わず、悪を討たん――華胥の<H>流れ者</>カシュウだ！\
どうだ？かっこいいだろ？",
            ["DialogueId"] = 12042911,
            ["GUID"] = "1E25EE16",
            ["NextOptions"] = {
                [1] = 12042912,
                [2] = 12042913,
                },
            ["RelatedWikiId"] = {
                [1] = 103001,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EE16",
            },
        [12042912] = {
            ["Content"] = "听起来很帅气。",
            ["ContentJP"] = "うん、確かに。",
            ["DialogueId"] = 12042912,
            ["GUID"] = "1E25EE40",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12042914,
            },
        [12042913] = {
            ["Content"] = "懂了，就是法外狂徒呗。",
            ["ContentJP"] = "つまり法外のならず者ってわけだ。",
            ["DialogueId"] = 12042913,
            ["GUID"] = "1E25EE6A",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12042915,
            },
        [12042914] = {
            ["Content"] = "那是自然。那些神仙香官自己对不公之事视而不见，还不准别人伸张正义，实属瞎眼！但，他们不管的，我们飘零人管。",
            ["ContentJP"] = "だろ？あの神や香官は不正を見て見ぬふりだ。正義を貫くことすら許されねぇ。ならば、俺たち流れ者がやるしかねえだろ。",
            ["DialogueId"] = 12042914,
            ["GUID"] = "1E25EE94",
            ["NextDialogue"] = 12042916,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EE94",
            },
        [12042915] = {
            ["Content"] = "话可不能这么说，有道是“侠以武犯禁”，要不是那些神仙香官自己对不公之事视而不见，还不准别人伸张正义，哪会有我们飘零人。",
            ["ContentJP"] = "そう言うな。「<Default note=\"text:おとこだて\">侠</>は武をもって禁を犯す」ってな。\
あの神や香官が不正を放置し、正義を縛るから、俺たち流れ者が動くことになるんだ。",
            ["DialogueId"] = 12042915,
            ["GUID"] = "1E25EEBE",
            ["NextDialogue"] = 12042916,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EEBE",
            },
        [12042916] = {
            ["Content"] = "停停停！知道你不是故意犯事的大坏蛋了。",
            ["ContentJP"] = "はいはい、悪人じゃないのはわかったよ！",
            ["DialogueId"] = 12042916,
            ["GUID"] = "1E25EEE8",
            ["NextDialogue"] = 12042917,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EEE8",
            },
        [12042917] = {
            ["Content"] = "哈哈，头一次遇到自我介绍比白还长的，魔王大人这下算是遇到对手了。",
            ["ContentJP"] = "へえ、スノウより長い自己紹介は初めて聞いたかも。魔王様、ライバル出現じゃない？",
            ["DialogueId"] = 12042917,
            ["GUID"] = "1E25EF12",
            ["NextDialogue"] = 12042918,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF12",
            },
        [12042918] = {
            ["Content"] = "这家伙准是吹牛！要是真身手这么好，怎么会被那些应天尉抓去……丢人！",
            ["ContentJP"] = "ふん！もし本当に腕が立つなら、どうして<Default note=\"text:おうてんい\">応天尉</>に捕まるの？ああ、みっともない！",
            ["DialogueId"] = 12042918,
            ["GUID"] = "1E25EF3C",
            ["NextDialogue"] = 12042919,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF3C",
            },
        [12042919] = {
            ["Content"] = "你可别误会了，我刻舟是主动送上门的。不然，再给那些家伙八百年的功夫，他们也奈何不了我！",
            ["ContentJP"] = "勘違いすんな、俺は自分から捕まったんだ。あんな連中、八百年あっても捕まえられやしねえ。",
            ["DialogueId"] = 12042919,
            ["GUID"] = "1E25EF66",
            ["NextDialogue"] = 12042920,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF66",
            },
        [12042920] = {
            ["Content"] = "主动送上门？就为了骂白龙神君一顿吗？",
            ["ContentJP"] = "わざと？白龍様の悪口をいうために？",
            ["DialogueId"] = 12042920,
            ["GUID"] = "1E25EF90",
            ["NextDialogue"] = 12042921,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EF90",
            },
        [12042921] = {
            ["Content"] = "怎么可能，你把我刻舟的头脑想得太简单了。",
            ["ContentJP"] = "まさか。俺がそんな単細胞に見えるか？",
            ["DialogueId"] = 12042921,
            ["GUID"] = "1E25EFBA",
            ["NextDialogue"] = 12042922,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EFBA",
            },
        [12042922] = {
            ["Content"] = "你还有别的目的？",
            ["ContentJP"] = "じゃあ、何のために？",
            ["DialogueId"] = 12042922,
            ["GUID"] = "1E25EFE4",
            ["NextDialogue"] = 12042923,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25EFE4",
            },
        [12042923] = {
            ["Content"] = "当然是为了——揍它一顿了！",
            ["ContentJP"] = "もちろん——ぶん殴るためさ！",
            ["DialogueId"] = 12042923,
            ["GUID"] = "1E25F00E",
            ["NextDialogue"] = 12042924,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F00E",
            },
        [12042924] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12042924,
            ["GUID"] = "1E25F038",
            ["NextDialogue"] = 12042925,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F038",
            },
        [12042925] = {
            ["Content"] = "这头脑也没复杂到哪去吧！",
            ["ContentJP"] = "……単細胞じゃん。",
            ["DialogueId"] = 12042925,
            ["GUID"] = "1E25F062",
            ["NextDialogue"] = 12042926,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F062",
            },
        [12042926] = {
            ["Content"] = "上次烛阴祭坛一别后，我一个人回去越想越乱，完全理不出头绪。最后我灵光一现：山不来就我，我便去就山。",
            ["ContentJP"] = "<Default note=\"text:しょくいんさいだん\">燭陰祭壇</>で別れた後、頭をひねっても答えが出なかった。\
だから向こうから来ねぇなら、こっちから行ってやるまでだって思ってな。",
            ["DialogueId"] = 12042926,
            ["GUID"] = "1E25F08C",
            ["NextDialogue"] = 12042927,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F08C",
            },
        [12042927] = {
            ["Content"] = "无论她想用烛阴搞出什么名堂，只要那白龙受创，狴犴和应天尉群龙无首，大风九章失去力量，一切问题岂不是迎刃而解了？",
            ["ContentJP"] = "何を企んでいようと、白龍さえ傷を負えば、<Default note=\"text:ビーアン\">狴犴</>も<Default note=\"text:おうてんい\">応天尉</>も頭を失い、大風九章も力を失う。そうなりゃ全て片が付くはずだろ？",
            ["DialogueId"] = 12042927,
            ["GUID"] = "1E25F0B6",
            ["NextDialogue"] = 12042928,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F0B6",
            },
        [12042928] = {
            ["Content"] = "正好我瞧那白龙不顺眼很久了，那该出手就出手，大不了就是一死嘛！只是……咳，神明还是神明，虽然是个死脑筋，但厉害还是怪厉害的。",
            ["ContentJP"] = "しかも俺は、あの白龍が前から気に食わなかったんだ。だから迷わず斬りかかった。死んだって構わねえ……とはいえ、神はやっぱり神だな。頑固なだけじゃなく、腕っぷしも化け物級だった。",
            ["DialogueId"] = 12042928,
            ["GUID"] = "1E25F0E0",
            ["NextDialogue"] = 12042929,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F0E0",
            },
        [12042929] = {
            ["Content"] = "要不是方才{nickname}出手相助，那就二十年后又是一条好汉喽。",
            ["ContentJP"] = "もしさっきお前が助けてくれなきゃ……来世でまた会う羽目になってたな。",
            ["DialogueId"] = 12042929,
            ["GUID"] = "1E25F10A",
            ["NextDialogue"] = 12042930,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F10A",
            },
        [12042930] = {
            ["Content"] = "原来你知道会死啊！你差点害死我们小仆从了！",
            ["ContentJP"] = "じゃあ、死ぬのわかってたの！？うちの下僕まで危ない目にあったんだけど！？",
            ["DialogueId"] = 12042930,
            ["GUID"] = "1E25F134",
            ["NextDialogue"] = 12042931,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F134",
            },
        [12042931] = {
            ["Content"] = "我也不知道你们会出现在那儿，抱歉啦，反正结果皆大欢喜不是？你们要还是生气，改天我拿我师父宝贝了几十年的佳酿赔罪。",
            ["ContentJP"] = "いや、まさかお前らがそこにいるとは思わなかった。悪かったよ。……でも終わりよけりゃすべてよしだろ？\
今度師匠が何十年も大事にしてる秘蔵の酒を持ってくるから怒るなって。",
            ["DialogueId"] = 12042931,
            ["GUID"] = "1E25F15E",
            ["NextDialogue"] = 12042932,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F15E",
            },
        [12042932] = {
            ["Content"] = "哼，水仙平原有的是佳酿，我才不稀罕！不过看在白捡了个大宝贝的份上，不生你气啦。",
            ["ContentJP"] = "ふん、酒なんてアスフォデロスにいくらでもあるし！でもまあ……スノウ、お宝拾っちゃったし、今回は許してあげる！",
            ["DialogueId"] = 12042932,
            ["GUID"] = "1E25F188",
            ["NextDialogue"] = 12042933,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F188",
            },
        [12042933] = {
            ["Content"] = "“大宝贝”？",
            ["ContentJP"] = "お宝？",
            ["DialogueId"] = 12042933,
            ["GUID"] = "1E25F1B2",
            ["NextDialogue"] = 12042934,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F1B2",
            },
        [12042934] = {
            ["Content"] = "展示均天玉律图标",
            ["ContentJP"] = "均天玉律の半欠けを見せる",
            ["DialogueId"] = 12042934,
            ["GUID"] = "1E25F1DC",
            ["NextDialogue"] = 12042935,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F1DC",
            },
        [12042935] = {
            ["Content"] = "这是刚刚那白龙飞走时掉下来的！神明的东西，想来肯定是了不起的宝贝！",
            ["ContentJP"] = "白龍が飛び去るときに落としたんだよ！神様の物なんだから、絶対すごいお宝に決まってるよね！",
            ["DialogueId"] = 12042935,
            ["GUID"] = "1E25F206",
            ["NextDialogue"] = 12042936,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F206",
            },
        [12042936] = {
            ["Content"] = "这……不就是半块玉佩吗，看着也没甚稀奇。不过既然是白龙的东西，说不定黑市的老爷子会喜欢。",
            ["ContentJP"] = "……半分の<Default note=\"text:ぎょくはい\">玉佩</>か。\
見た目は大したことなさそうだが、白龍の物となりゃ闇市の爺さんが喜ぶかもしれねえな。",
            ["DialogueId"] = 12042936,
            ["GUID"] = "1E25F230",
            ["NextDialogue"] = 12042937,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F230",
            },
        [12042937] = {
            ["Content"] = "那我就收好，等卖一大笔钱，就给小仆从当路费啦。",
            ["ContentJP"] = "じゃあ大事に持っておく！高く売って、下僕の旅費にしてあげるんだから！",
            ["DialogueId"] = 12042937,
            ["GUID"] = "1E25F25A",
            ["NextDialogue"] = 12042938,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F25A",
            },
        [12042938] = {
            ["Content"] = "说起来，{nickname}，你刚刚做了什么？那可是神啊，我拼尽全力也动不得他分毫。你是怎么把它击伤的？",
            ["ContentJP"] = "そういや、お前さっき何をしたんだ？相手は神だぞ？俺が全力を尽くしてもかすり傷ひとつ付けられなかったのに……いったいどうやって？",
            ["DialogueId"] = 12042938,
            ["GUID"] = "1E25F284",
            ["NextDialogue"] = 12042939,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F284",
            },
        [12042939] = {
            ["Content"] = "说实话，我也不知道。而且我觉得不太对劲。",
            ["ContentJP"] = "正直、自分でもわからない……なんだか妙な感じがした。",
            ["DialogueId"] = 12042939,
            ["GUID"] = "1E25F2AE",
            ["NextDialogue"] = 12042940,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F2AE",
            },
        [12042940] = {
            ["Content"] = "当时白龙打过来，我唯一能做的只有拼死抵抗。但……不知为什么，我感到一种力量不受控制地从我身体里倾泻出来。",
            ["ContentJP"] = "あの時、白龍が襲ってきて……必死で防ごうとしたら……何かが勝手に溢れ出すみたいに力が流れ出てきて……",
            ["DialogueId"] = 12042940,
            ["GUID"] = "1E25F2D8",
            ["NextDialogue"] = 12042941,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F2D8",
            },
        [12042941] = {
            ["Content"] = "回闪一下CG中的金钱迷卦",
            ["ContentJP"] = "CG回想：金銭の迷卦が発動",
            ["DialogueId"] = 12042941,
            ["GUID"] = "1E25F302",
            ["NextDialogue"] = 12042942,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F302",
            },
        [12042942] = {
            ["Content"] = "就像是……被什么操控了一样。",
            ["ContentJP"] = "……まるで操られてるみたいだった。",
            ["DialogueId"] = 12042942,
            ["GUID"] = "1E25F32C",
            ["NextDialogue"] = 12042943,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F32C",
            },
        [12042943] = {
            ["Content"] = "竟有此般蹊跷……",
            ["ContentJP"] = "……妙だな。",
            ["DialogueId"] = 12042943,
            ["GUID"] = "1E25F356",
            ["NextDialogue"] = 12042944,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F356",
            },
        [12042944] = {
            ["Content"] = "……想不明白的事还有很多。刻舟，你是不是说过，我们“在烛阴祭坛商量过对策”？可是我一点也想不起来——我不记得和你在那里说过话。",
            ["ContentJP"] = "まだわからないことが山ほどある。そういえばカシュウ、<Default note=\"text:しょくいんさいだん\">燭陰祭壇</>で作戦を練ったって言った{性别:よな？でも僕……全く覚えてないんだ。|よね？でも私……全く覚えてないの。}",
            ["DialogueId"] = 12042944,
            ["GUID"] = "1E25F380",
            ["NextDialogue"] = 12042945,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F380",
            },
        [12042945] = {
            ["Content"] = "不会吧？这么重要的事情，你都不记得了？当时我们……",
            ["ContentJP"] = "なんだと？あんな大事なことをか？あの時俺らは……",
            ["DialogueId"] = 12042945,
            ["GUID"] = "1E25F3AA",
            ["NextDialogue"] = 12042946,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F3AA",
            },
        [12042946] = {
            ["Content"] = "噤声，附近有脚步声——",
            ["ContentJP"] = "静かに。足音がする……",
            ["DialogueId"] = 12042946,
            ["GUID"] = "1E25F3D4",
            ["NextDialogue"] = 12042947,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F3D4",
            },
        [12042947] = {
            ["Content"] = "……那边……明白……",
            ["ContentJP"] = "……あっちだ……わかった……",
            ["DialogueId"] = 12042947,
            ["GUID"] = "1E25F3FE",
            ["NextDialogue"] = 12042948,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoYaoShengWenHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F3FE",
            },
        [12042948] = {
            ["Content"] = "不知来者何人。{nickname}，先找个角落躲藏起来，我们见机行事。",
            ["ContentJP"] = "誰か分からん以上、ひとまず身を隠して様子見よう。",
            ["DialogueId"] = 12042948,
            ["GUID"] = "1E25F428",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120429/1E25F428",
            },
        [12043001] = {
            ["Content"] = "……无由生本因大风九章倒转天地之法则而创生。您身为祝由，天然可以调动大风九章的力量。",
            ["ContentJP"] = "……我らムユウセイは大風九章が天地の法則を逆転させて生まれたもの。\
あなたは<Default note=\"text:しゅくゆ\">祝由</>、ゆえに大風九章の力を自在に操れる。",
            ["DialogueId"] = 12043001,
            ["GUID"] = "1E25FCDA",
            ["NextDialogue"] = 12043003,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203006,
                [3] = 303012,
                },
            ["SpeakNpcId"] = 210040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FCDA",
            },
        [12043002] = {
            ["Content"] = "只要算出正确的时日，于虞渊之底动用泽生之术，届时，您想见之故人自当应召而来——前提是，她的灵魂还尚存于世。",
            ["ContentJP"] = "正しい時を割り出し、<Default note=\"text:ぐえん\">虞淵</>の底で<Default note=\"text:たくせいのじゅつ\">澤生の術</>を使えば……\
あなたが会いたい故人は必ず現れるだろう。ただし——その魂がまだ世にあれば、の話だが。",
            ["DialogueId"] = 12043002,
            ["GUID"] = "1E25FD04",
            ["NextDialogue"] = 12043003,
            ["SpeakNpcId"] = 210040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD04",
            },
        [12043003] = {
            ["Content"] = "只是这其中的代价……",
            ["ContentJP"] = "だが……その代償に——",
            ["DialogueId"] = 12043003,
            ["GUID"] = "1E25FD2E",
            ["NextDialogue"] = 12043004,
            ["SpeakNpcId"] = 210040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD2E",
            },
        [12043004] = {
            ["Content"] = "我已明白，无需多言。如今终于有眉目了，实在是感激不尽。",
            ["ContentJP"] = "もう結構にございます。道筋が見えた今、感謝の言葉もございません。",
            ["DialogueId"] = 12043004,
            ["GUID"] = "1E25FD58",
            ["NextDialogue"] = 12043005,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD58",
            },
        [12043005] = {
            ["Content"] = "……扶疏姐姐，是你！",
            ["ContentJP"] = "……フーシュ！？なんでここに？",
            ["DialogueId"] = 12043005,
            ["GUID"] = "1E25FD82",
            ["NextDialogue"] = 12043006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FD82",
            },
        [12043006] = {
            ["Content"] = "咦？小白，你怎么在这里，又怎生弄得如此狼狈？",
            ["ContentJP"] = "まあ……スノウさん？何ゆえこちらに？ それに、どことなく随分とお汚れのご様子……。",
            ["DialogueId"] = 12043006,
            ["GUID"] = "1E25FDAC",
            ["NextDialogue"] = 12043007,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FDAC",
            },
        [12043007] = {
            ["Content"] = "警报解除。{nickname}，不用躲了，出来吧。",
            ["ContentJP"] = "警戒解除だ、{nickname}。出てきな。",
            ["DialogueId"] = 12043007,
            ["GUID"] = "1E25FDD6",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120430/1E25FDD6",
            },
        [12043101] = {
            ["Content"] = "……原来外面闹得沸沸扬扬的执律阁行刺案，竟是你们所为。",
            ["ContentJP"] = "……なるほど。外で騒ぎになっている執律閣襲撃は、あなたたちの仕業でございましたか。",
            ["DialogueId"] = 12043101,
            ["GUID"] = "1E260D42",
            ["NextDialogue"] = 12043102,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260D42",
            },
        [12043102] = {
            ["Content"] = "前后的来龙去脉，可以与我讲讲吗？",
            ["ContentJP"] = "経緯を詳しくお聞かせ願えますか？",
            ["DialogueId"] = 12043102,
            ["GUID"] = "1E260D6C",
            ["NextDialogue"] = 12043103,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260D6C",
            },
        [12043103] = {
            ["Content"] = "这说来可就话长了，得从今天早上，我和小仆从帮止流姐姐去各个地方跑腿取东西讲起……",
            ["ContentJP"] = "話せば長くなるんだけどね～今朝、私と下僕がシリュウにお使いを頼まれて～",
            ["DialogueId"] = 12043103,
            ["GUID"] = "1E260D96",
            ["NextDialogue"] = 12043104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260D96",
            },
        [12043104] = {
            ["Content"] = "止流掌柜？&那个女人？！",
            ["ContentJP"] = "シリュウ！？＆シリュウだと！？",
            ["DialogueId"] = 12043104,
            ["GUID"] = "1E260DC0",
            ["NextDialogue"] = 12043105,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_FuShuKeZhou",
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260DC0",
            },
        [12043105] = {
            ["Content"] = "恕我冒昧，上次降服烛阴时，止流掌柜应当已经与你们反目了。难道在那之后还有什么我们所不知的内情吗？",
            ["ContentJP"] = "恐れながら、<Default note=\"text:しょくいん\">燭陰</>を降した折には、\
すでにシリュウとは決裂していたはず。……その後、何があったのです？",
            ["DialogueId"] = 12043105,
            ["GUID"] = "1E260DEA",
            ["NextDialogue"] = 12043106,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260DEA",
            },
        [12043106] = {
            ["Content"] = "反目……？",
            ["ContentJP"] = "決裂……？",
            ["DialogueId"] = 12043106,
            ["GUID"] = "1E260E14",
            ["NextDialogue"] = 12043107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E14",
            },
        [12043107] = {
            ["Content"] = "<H>白龙神君</>的时代，该结束了。而我，将执起祂的权柄。",
            ["ContentJP"] = "<H>白龍様</>の時代は、いい加減終わるべきよ。そしてこの私が、その御力を引き継ぐ。",
            ["DialogueId"] = 12043107,
            ["GUID"] = "1E260E3E",
            ["NextDialogue"] = 12043108,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E3E",
            },
        [12043108] = {
            ["Content"] = "接下来，<W>忘记我，忘记刚才这里发生的一切对话</>，好吗？",
            ["ContentJP"] = "<W>私のことも、私との会話も全部忘れてくれるかしら</>。",
            ["DialogueId"] = 12043108,
            ["GUID"] = "1E260E68",
            ["NextDialogue"] = 12043109,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E68",
            },
        [12043109] = {
            ["Content"] = "（随着记忆的复苏，一阵前所未有的剧烈疼痛如同海啸般扑来，淹没了你的思维。你的每一根神经末梢都在惊涛骇浪中叫嚣。）",
            ["ContentJP"] = "記憶がよみがえると同時に、これまでにない激しい痛みが津波のように押し寄せ、意識を呑み込んでいく。\
全身の神経の一本一本が、荒れ狂う波濤の中で悲鳴を上げていた。",
            ["DialogueId"] = 12043109,
            ["GUID"] = "1E260E92",
            ["NextDialogue"] = 12043110,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260E92",
            },
        [12043110] = {
            ["Content"] = "……疼！",
            ["ContentJP"] = "……いっ！",
            ["DialogueId"] = 12043110,
            ["GUID"] = "1E260EBC",
            ["NextDialogue"] = 12043111,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260EBC",
            },
        [12043111] = {
            ["Content"] = "{nickname}，你怎么了？！你的脉象怎如此杂乱？",
            ["ContentJP"] = "{nickname}さん、いかがされました！？脈がこんなに乱れて……",
            ["DialogueId"] = 12043111,
            ["GUID"] = "1E260EE6",
            ["NextDialogue"] = 12043112,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260EE6",
            },
        [12043112] = {
            ["Content"] = "忍耐片刻，我来为你调理。",
            ["ContentJP"] = "しばしご辛抱を。すぐに治療を施しますので。",
            ["DialogueId"] = 12043112,
            ["GUID"] = "1E260F10",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120431/1E260F10",
            },
        [12043201] = {
            ["Content"] = "……你把我带到这里，又是想说什么？",
            ["ContentJP"] = "……で？{性别:僕をわざわざここに連れてきて、何を話すつもりだ？|私をわざわざここに連れてきて、何を話すつもり？}",
            ["DialogueId"] = 12043201,
            ["GUID"] = "1E261DAA",
            ["NextDialogue"] = 12043202,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261DAA",
            },
        [12043202] = {
            ["Content"] = "呵呵。先前应对烛阴时有些仓促了，我们还没有坐下来好好聊过。若是就结束在这里，我想，对于你我来说，都是一种遗憾。",
            ["ContentJP"] = "ふふ……<Default note=\"text:しょくいん\">燭陰</>の時は少々慌ただしかったからね。こうして腰を据えて話すのは、これが初めてでしょう\
。もしここで終わってしまえば、私にもあなたにも心残りになってしまうわ。",
            ["DialogueId"] = 12043202,
            ["GUID"] = "1E261DD4",
            ["NextDialogue"] = 12043203,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261DD4",
            },
        [12043203] = {
            ["Content"] = "你强行带我到这里，一句“仓促”就可以敷衍了事吗？",
            ["ContentJP"] = "強引に連れてきておいて、「慌ただしかった」で済ませる気？",
            ["DialogueId"] = 12043203,
            ["GUID"] = "1E261DFE",
            ["NextDialogue"] = 12043204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261DFE",
            },
        [12043204] = {
            ["Content"] = "{nickname}，我理解你的心情。你完全有理由感到愤怒。",
            ["ContentJP"] = "怒る気持ちもわかるわ。",
            ["DialogueId"] = 12043204,
            ["GUID"] = "1E261E28",
            ["NextDialogue"] = 12043205,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261E28",
            },
        [12043205] = {
            ["Content"] = "既然你已经选择撕破了脸，这种客套话还是不必了。",
            ["ContentJP"] = "もう探り合いは不要だと思うが？",
            ["DialogueId"] = 12043205,
            ["GUID"] = "1E261E52",
            ["NextDialogue"] = 12043206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261E52",
            },
        [12043206] = {
            ["Content"] = "止流掌柜，刚刚在祭坛顶端，你为什么要不顾我的反对，强行吸收烛阴的力量？你真的是想<H>成神</>吗？",
            ["ContentJP"] = "シリュウさん、なぜ{性别:僕|私}の反対を押し切ってまで <Default note=\"text:しょくいん\">燭陰</>の力を吸収した{性别:んだ|の}？本当に<H>神になる</>つもり{性别:か|}？",
            ["DialogueId"] = 12043206,
            ["GUID"] = "1E261E7C",
            ["NextDialogue"] = 12043207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261E7C",
            },
        [12043207] = {
            ["Content"] = "既然你已经得偿所愿，又为什么要把我关在这里？",
            ["ContentJP"] = "それに、望みが叶ったのなら、{性别:僕|私}をここに閉じ込める必要はないのでは？",
            ["DialogueId"] = 12043207,
            ["GUID"] = "1E261EA6",
            ["NextDialogue"] = 12043208,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261EA6",
            },
        [12043208] = {
            ["Content"] = "呵呵……开场的寒暄就到此为止吧，我们该进入正题了。",
            ["ContentJP"] = "……世間話はここまでにしましょう。本題に入るわよ。",
            ["DialogueId"] = 12043208,
            ["GUID"] = "1E261ED0",
            ["NextDialogue"] = 12043209,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261ED0",
            },
        [12043209] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12043209,
            ["GUID"] = "1E261EFA",
            ["NextDialogue"] = 12043210,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261EFA",
            },
        [12043210] = {
            ["Content"] = "你所谓的“好好聊聊”，似乎并没有多少诚意。",
            ["ContentJP"] = "「腰を据えて話す」って言ってた割に、誠意が全く感じられないけど。",
            ["DialogueId"] = 12043210,
            ["GUID"] = "1E261F24",
            ["NextDialogue"] = 12043211,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261F24",
            },
        [12043211] = {
            ["Content"] = "耐心，{nickname}——你的疑问，接下来我会向你一一解释。但在那之前，有一件更加重要的事情。",
            ["ContentJP"] = "静かに、{nickname}……疑問には全部答えるわ。でもその前に、もっと大事なことがあるの。",
            ["DialogueId"] = 12043211,
            ["GUID"] = "1E261F4E",
            ["NextDialogue"] = 12043212,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261F4E",
            },
        [12043212] = {
            ["Content"] = "你知道吗？未来的走向，在卦象之中是早已谱写好的。这三起卦象，便是我为你揭示的未来。",
            ["ContentJP"] = "未来の流れは既に卦の中に描かれているの。この三つの卦が、あなたに訪れる未来よ。",
            ["DialogueId"] = 12043212,
            ["GUID"] = "1E261F78",
            ["NextDialogue"] = 12043213,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261F78",
            },
        [12043213] = {
            ["Content"] = "第一起，乾之太过：亢龙有悔，过涉灭顶。",
            ["ContentJP"] = "ひとつ目——『<Default note=\"text:けんのたいか\">乾の大過</>』。<Default note=\"text:こうりょうくいあり\">亢龍悔いあり</>、深き淵を越えんとして滅びる。",
            ["DialogueId"] = 12043213,
            ["GUID"] = "1E261FA2",
            ["NextDialogue"] = 12043214,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261FA2",
            },
        [12043214] = {
            ["Content"] = "{nickname}，<H>你将会前往极天之巅，与华胥的至高存在交手，并最终生还。</>",
            ["ContentJP"] = "{nickname}、<H>あなたは「極天の頂」に向かい、華胥の至高なる存在と刃を交え、そして——生きて戻るでしょう。</>",
            ["DialogueId"] = 12043214,
            ["GUID"] = "1E261FCC",
            ["NextDialogue"] = 12043215,
            ["RelatedWikiId"] = {
                [1] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261FCC",
            },
        [12043215] = {
            ["Content"] = "我？至高存在？交手？",
            ["ContentJP"] = "至高なる存在と戦う？",
            ["DialogueId"] = 12043215,
            ["GUID"] = "1E261FF6",
            ["NextDialogue"] = 12043216,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E261FF6",
            },
        [12043216] = {
            ["Content"] = "我有什么理由做这件事吗？",
            ["ContentJP"] = "何のために？",
            ["DialogueId"] = 12043216,
            ["GUID"] = "1E262020",
            ["NextDialogue"] = 12043217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E262020",
            },
        [12043217] = {
            ["Content"] = "呵呵……{nickname}。这是注定会发生的事情，你很快就会明白了。",
            ["ContentJP"] = "……これは避けられないことよ。すぐにわかるわ。",
            ["DialogueId"] = 12043217,
            ["GUID"] = "1E26204A",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120432/1E26204A",
            },
        [12043301] = {
            ["Content"] = "{nickname}，你现在感觉怎样了？",
            ["ContentJP"] = "{nickname}、調子はどう？",
            ["DialogueId"] = 12043301,
            ["GUID"] = "1E262E12",
            ["NextDialogue"] = 12043302,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203006,
                [3] = 203001,
                [4] = 401005,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E12",
            },
        [12043302] = {
            ["Content"] = "我……想起来了。止流向我预言了三件将要发生的事情。",
            ["ContentJP"] = "……思い出した。シリュウさんは、これから起こる三つの出来事を予言してた。",
            ["DialogueId"] = 12043302,
            ["GUID"] = "1E262E3C",
            ["NextDialogue"] = 12043303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E3C",
            },
        [12043303] = {
            ["Content"] = "其中第一件，就是我会在执律阁上与白龙神君交手。这样看来，交手时的力量失控，可能是止流动的手脚。",
            ["ContentJP"] = "ひとつ目は——{性别:僕|私}が<Default note=\"text:しつりつかく\">執律閣</>で白龍様と戦うこと。\
そう考えると、あの時の力の暴走は……彼女の仕業かもしれない。",
            ["DialogueId"] = 12043303,
            ["GUID"] = "1E262E66",
            ["NextDialogue"] = 12043304,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E66",
            },
        [12043304] = {
            ["Content"] = "你提到三件事情，那还有两件事是什么？",
            ["ContentJP"] = "三つって言ったな。他の二つは？",
            ["DialogueId"] = 12043304,
            ["GUID"] = "1E262E90",
            ["NextDialogue"] = 12043305,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262E90",
            },
        [12043305] = {
            ["Content"] = "我不记得了。",
            ["ContentJP"] = "思い出せない。",
            ["DialogueId"] = 12043305,
            ["GUID"] = "1E262EBA",
            ["NextDialogue"] = 12043306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262EBA",
            },
        [12043306] = {
            ["Content"] = "我唯一能确定的是，剩下两样“预言”尚未发生。并且，必须在它们成真之前尽快阻止。",
            ["ContentJP"] = "ただ、残り二つはまだ起きてない……起こる前に、何としてでも止めなきゃ。",
            ["DialogueId"] = 12043306,
            ["GUID"] = "1E262EE4",
            ["NextDialogue"] = 12043307,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262EE4",
            },
        [12043307] = {
            ["Content"] = "我有一种预感，最后一件事，是我极度不愿意看到它实现的。它会带来非常糟糕的后果。",
            ["ContentJP"] = "特に最後のひとつは……絶対に実現させたくない。あれが起きれば、とんでもないことになる。そんな気がする{性别:んだ|の}。",
            ["DialogueId"] = 12043307,
            ["GUID"] = "1E262F0E",
            ["NextDialogue"] = 12043308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F0E",
            },
        [12043308] = {
            ["Content"] = "……{nickname}，如果我没有猜错的话，你所说的“预言”，并非是真正意义上的预测未来。",
            ["ContentJP"] = "……{nickname}さん、私の予想が正しければ、その「予言」なるもの、真の未来視ではございません。",
            ["DialogueId"] = 12043308,
            ["GUID"] = "1E262F38",
            ["NextDialogue"] = 12043309,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F38",
            },
        [12043309] = {
            ["Content"] = "没有人能断言自己可以勘破命运。止流所作出的预言，其实是扎根于你意识深层的咒印。或者换言之，一种<W>催眠</>。",
            ["ContentJP"] = "人の身にて運命を見通すことは叶わぬ道理。シリュウが為したのは、あなたの深層意識に刻まれし呪い……いわば<W>催眠</>にございます。",
            ["DialogueId"] = 12043309,
            ["GUID"] = "1E262F62",
            ["NextDialogue"] = 12043310,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F62",
            },
        [12043310] = {
            ["Content"] = "她用言语影响你对未来的认知，从而把命运拨弄到她期望的方向。你刚刚提到的“力量失控”就是很好的佐证。",
            ["ContentJP"] = "言葉をもって未来の像を植え付け、己の望む方へと運命を操るのでございましょう。先ほどの「力の暴走」こそ、その証左かと。",
            ["DialogueId"] = 12043310,
            ["GUID"] = "1E262F8C",
            ["NextDialogue"] = 12043311,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262F8C",
            },
        [12043311] = {
            ["Content"] = "……原来是这样，难怪早上开始小仆从就感觉不对劲！",
            ["ContentJP"] = "なるほど……だから朝から下僕の様子が変だったんだな！",
            ["DialogueId"] = 12043311,
            ["GUID"] = "1E262FB6",
            ["NextDialogue"] = 12043312,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262FB6",
            },
        [12043312] = {
            ["Content"] = "扶疏，你有办法帮我找回记忆吗？",
            ["ContentJP"] = "フーシュ、記憶を取り戻す方法はある？",
            ["DialogueId"] = 12043312,
            ["GUID"] = "1E262FE0",
            ["NextDialogue"] = 12043313,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E262FE0",
            },
        [12043313] = {
            ["Content"] = "现在影响你的，并非是一种“疾病”，而是一种特殊的力量。",
            ["ContentJP"] = "これは病ではなく、特異なる力の作用にございます。",
            ["DialogueId"] = 12043313,
            ["GUID"] = "1E26300A",
            ["NextDialogue"] = 12043314,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26300A",
            },
        [12043314] = {
            ["Content"] = "若只是通常疾病，我能将其渡之己身。但对于这种特殊的力量，我需要更多时间去寻找它的解法。可能短时间内无法对症治愈，抱歉。",
            ["ContentJP"] = "常の病ならば、私が身に引き受けられましょう。されどこの力を解くには時を要し、短き間にては叶いませぬ。……申し訳ございません。",
            ["DialogueId"] = 12043314,
            ["GUID"] = "1E263034",
            ["NextDialogue"] = 12043315,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263034",
            },
        [12043315] = {
            ["Content"] = "要是这样的话，我们现在还在被全城通缉呢，一直待在这儿也不是个办法。{nickname}，和我回山外山吧。",
            ["ContentJP"] = "だったら、いつまでもここでくすぶっててもしょうがねぇ。{nickname}、俺と<Default note=\"text:さんがいさん\">山外山</>まで来い。",
            ["DialogueId"] = 12043315,
            ["GUID"] = "1E26305E",
            ["NextDialogue"] = 12043316,
            ["RelatedWikiId"] = {
                [1] = 408018,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26305E",
            },
        [12043316] = {
            ["Content"] = "山外山？这又是什么地方？",
            ["ContentJP"] = "山外山って？",
            ["DialogueId"] = 12043316,
            ["GUID"] = "1E263088",
            ["NextDialogue"] = 12043317,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263088",
            },
        [12043317] = {
            ["Content"] = "物不平则鸣。如今这世道，只是看上去平和，内里却是千疮百孔。人若是把这种种不公看在眼里，又怎会服气？",
            ["ContentJP"] = "物は平らかなるを得ざれば<Default note=\"text:すなわ\">則</>ち鳴る。世の中は見た目こそ穏やかだが、中身は穴だらけだ。",
            ["DialogueId"] = 12043317,
            ["GUID"] = "1E2630B2",
            ["NextDialogue"] = 12043318,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2630B2",
            },
        [12043318] = {
            ["Content"] = "有意对抗大风九章的能人异士，以飘零人的名号集结在了一起，山外山就是我们的秘密基地。信我，那里安全得很！",
            ["ContentJP"] = "そんな不公平を黙って見てられねえ奴らが流れ者の名において集まってる場所——\
それが<Default note=\"text:さんがいさん\">山外山</>。俺たち大風九章と抗う英傑の秘密基地ってとこだ。安全は保証するぜ。",
            ["DialogueId"] = 12043318,
            ["GUID"] = "1E2630DC",
            ["NextDialogue"] = 12043319,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2630DC",
            },
        [12043319] = {
            ["Content"] = "对此我也有所耳闻。传言那山外山藏于云雾山隐之中，踪迹难寻。对于你们倒是个安全去处。",
            ["ContentJP"] = "私もその噂を耳にいたしております。霧の立ち込める山奥にひそみ、足跡掴ませぬゆえ、まことに隠れ住むにはうってつけの地でございましょう。",
            ["DialogueId"] = 12043319,
            ["GUID"] = "1E263106",
            ["NextDialogue"] = 12043320,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263106",
            },
        [12043320] = {
            ["Content"] = "那就按你说的做吧。",
            ["ContentJP"] = "わかった、そこに行こう。",
            ["DialogueId"] = 12043320,
            ["GUID"] = "1E263130",
            ["NextDialogue"] = 12043321,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263130",
            },
        [12043321] = {
            ["Content"] = "一言为定！",
            ["ContentJP"] = "んじゃ、決まりだ！",
            ["DialogueId"] = 12043321,
            ["GUID"] = "1E26315A",
            ["NextDialogue"] = 12043322,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26315A",
            },
        [12043322] = {
            ["Content"] = "我随后先出去将追兵引开，为你们制造空隙。",
            ["ContentJP"] = "俺が先に出て追っ手を引きつける。",
            ["DialogueId"] = 12043322,
            ["GUID"] = "1E263184",
            ["NextDialogue"] = 12043323,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263184",
            },
        [12043323] = {
            ["Content"] = "你们<H>去东郊野外，找到沿途的记号</>，一路跟着走。我待会儿给我姑奶奶苏乙传信，让她来接应你们。",
            ["ContentJP"] = "お前らは<H>東郊外まで行って、道中の印を辿れ</>。迎えは俺の叔母のスーイーだ。",
            ["DialogueId"] = 12043323,
            ["GUID"] = "1E2631AE",
            ["NextDialogue"] = 12043324,
            ["RelatedWikiId"] = {
                [1] = 203009,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2631AE",
            },
        [12043324] = {
            ["Content"] = "啊对了……我那姑奶奶特别讲规矩，接头暗号日日都要更换。你得一路沿着记号，在终点找到今日的暗号动作。你做了那个动作，才有人搭理你。",
            ["ContentJP"] = "あいつ、妙にきっちりしてて、暗号は毎日変える。終点で今日の暗号となる動作を見つけてその通りのしぐさをすれば、話しかけてくるはずだ。",
            ["DialogueId"] = 12043324,
            ["GUID"] = "1E2631D8",
            ["NextDialogue"] = 12043325,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E2631D8",
            },
        [12043325] = {
            ["Content"] = "哦还有，她脾气不太好，你见了她说话可要小心点，别把她惹火了。不过就算惹火了也有办法，只要使劲夸她几句，她就什么气都消了。",
            ["ContentJP"] = "それと……叔母はちょっと気が短いから、言葉には気をつけろよ。\
もし怒らせたら、とにかく褒めちぎれ。それで大抵は機嫌が直る。",
            ["DialogueId"] = 12043325,
            ["GUID"] = "1E263202",
            ["NextDialogue"] = 12043326,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263202",
            },
        [12043326] = {
            ["Content"] = "要叮嘱的差不多就是这些，我且去了！我们在山外山见！",
            ["ContentJP"] = "じゃ、そんなとこだ。俺は行く！山外山で会おう！",
            ["DialogueId"] = 12043326,
            ["GUID"] = "1E26322C",
            ["NextDialogue"] = 12043327,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E26322C",
            },
        }
  end },
  { MinKey = 12043327, MaxKey = 12044312, Loader = function()
      return {
        [12043327] = {
            ["Content"] = "小仆从，等我们准备好，也尽快出发吧！",
            ["ContentJP"] = "下僕、準備ができたら出発するよ！",
            ["DialogueId"] = 12043327,
            ["GUID"] = "1E263256",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120433/1E263256",
            },
        [12043401] = {
            ["Content"] = "你好，请问你认识一位叫做苏乙的老人家吗？",
            ["ContentJP"] = "こんにちは！「スーイー」っておばあさん、知ってるか？",
            ["DialogueId"] = 12043401,
            ["GUID"] = "1E263E7A",
            ["NextDialogue"] = 12043402,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263E7A",
            },
        [12043402] = {
            ["Content"] = "老、老人家？！",
            ["ContentJP"] = "お、おばあさんですって！？",
            ["DialogueId"] = 12043402,
            ["GUID"] = "1E263EA4",
            ["NextDialogue"] = 12043403,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263EA4",
            },
        [12043403] = {
            ["Content"] = "不认识，你找错人了吧。",
            ["ContentJP"] = "知らないわ！人違いよ。",
            ["DialogueId"] = 12043403,
            ["GUID"] = "1E263ECE",
            ["NextDialogue"] = 12043404,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263ECE",
            },
        [12043404] = {
            ["Content"] = "那，你是那个山什么的接头人……",
            ["ContentJP"] = "じゃあ……あんた、あの山なんとかの仲間だったり……",
            ["DialogueId"] = 12043404,
            ["GUID"] = "1E263EF8",
            ["NextDialogue"] = 12043405,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263EF8",
            },
        [12043405] = {
            ["Content"] = "说了你找错人了，别再来问我了。",
            ["ContentJP"] = "人違いだって言ってるでしょ。もう話しかけないで。",
            ["DialogueId"] = 12043405,
            ["GUID"] = "1E263F22",
            ["NextDialogue"] = 12043406,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263F22",
            },
        [12043406] = {
            ["Content"] = "我还没把话说完呢！再说了，正常人谁会在荒郊野岭晃来晃去啊！",
            ["ContentJP"] = "まだ最後まで言ってないじゃんか！だいたい、一般人がこんな荒れ地をうろつく？",
            ["DialogueId"] = 12043406,
            ["GUID"] = "1E263F4C",
            ["NextDialogue"] = 12043407,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263F4C",
            },
        [12043407] = {
            ["Content"] = "这里又不是什么私家园林，无主之地而已。我就爱在这儿散步，越偏僻越能激发灵感，不行吗？",
            ["ContentJP"] = "ここは誰かの私有地じゃないわ。私はこういう人気のない場所を歩くのが好きなの。\
静かな方がアイデアも湧くんだから。文句ある？",
            ["DialogueId"] = 12043407,
            ["GUID"] = "1E263F76",
            ["NextDialogue"] = 12043408,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263F76",
            },
        [12043408] = {
            ["Content"] = "小仆从，难不成我们找错人了，她只是恰好路过？",
            ["ContentJP"] = "もしかして……本当に人違いだったりして？",
            ["DialogueId"] = 12043408,
            ["GUID"] = "1E263FA0",
            ["NextDialogue"] = 12043409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263FA0",
            },
        [12043409] = {
            ["Content"] = "……白，刻舟还叮嘱过我们一些话。你忘了吗？",
            ["ContentJP"] = "……スノウ、カシュウの言葉を忘れたの{性别:か|}？",
            ["DialogueId"] = 12043409,
            ["GUID"] = "1E263FCA",
            ["NextDialogue"] = 12043410,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263FCA",
            },
        [12043410] = {
            ["Content"] = "啊……！我想起来了，要<H>一路沿着记号，找到今天的暗号动作。对过暗号，她才会搭理我们！</>",
            ["ContentJP"] = "あっ……そうだ、確か<H>道中の印を辿って今日の動作を探せだったっけ。それをやれば話しかけてくれるんだよね！</>",
            ["DialogueId"] = 12043410,
            ["GUID"] = "1E263FF4",
            ["NextDialogue"] = 12043411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E263FF4",
            },
        [12043411] = {
            ["Content"] = "……哼，这么麻烦的规矩是谁定的，就喜欢让人跑来跑去是吧。",
            ["ContentJP"] = "……ったく、なんて面倒くさい決まりなんだか！無駄に人を走らせて何が楽しいんだろ！",
            ["DialogueId"] = 12043411,
            ["GUID"] = "1E26401E",
            ["NextDialogue"] = 12043412,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E26401E",
            },
        [12043412] = {
            ["Content"] = "呵呵，小白莫要心急。华胥有句古话叫做好事多磨。耐心些，终点就在不远处了。",
            ["ContentJP"] = "ふふ、スノウさま、どうぞ焦らずに。「良き事ほど時を要す」という古いことわざがおります。\
終わりは、さほど遠くはありますまい。",
            ["DialogueId"] = 12043412,
            ["GUID"] = "1E264048",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120434/1E264048",
            },
        [12043501] = {
            ["Content"] = "跟我来吧，我就是你们要找的苏乙。",
            ["ContentJP"] = "私がスーイーだよ。着いてきなさい。",
            ["DialogueId"] = 12043501,
            ["GUID"] = "1E264EE2",
            ["NextDialogue"] = 12043502,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264EE2",
            },
        [12043502] = {
            ["Content"] = "哎？你就是苏乙？！刻舟的姑奶奶不应该是个七八十岁的老人家吗！",
            ["ContentJP"] = "えっ！？あんたが！？カシュウの叔母っていうから、てっきり七十や八十のババァかと思ったのに！",
            ["DialogueId"] = 12043502,
            ["GUID"] = "1E264F0C",
            ["NextDialogue"] = 12043503,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F0C",
            },
        [12043503] = {
            ["Content"] = "我懂了……这一定是某种返老还童的神秘魔法力量……",
            ["ContentJP"] = "……わかったぞ。きっと「若返りの秘術」ってやつだな！",
            ["DialogueId"] = 12043503,
            ["GUID"] = "1E264F36",
            ["NextDialogue"] = 12043504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F36",
            },
        [12043504] = {
            ["Content"] = "咳咳，本姑娘只是辈分高而已。辈分又不一定和年龄挂钩！",
            ["ContentJP"] = "ゴホン、ただ血筋上の呼び名がそうなってるだけよ。年齢とは関係ないわ。",
            ["DialogueId"] = 12043504,
            ["GUID"] = "1E264F60",
            ["NextDialogue"] = 12043505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F60",
            },
        [12043505] = {
            ["Content"] = "自我介绍一下，我是山外山的司廪，机枢派第十七代传人。刻舟那家伙的师爷和我同辈，所以他得尊称我一声姑奶奶。接下来，我会为你们带路。",
            ["ContentJP"] = "私は<Default note=\"text:さんがいさん\">山外山</>の<Default note=\"text:しりん\">司廪</>、<Default note=\"text:きすうは\">機枢派</>十七代目の継承者。\
カシュウの師匠と同格だから、あいつは「叔母」と呼ばなきゃならないってわけ。さあ着いてきなさい。",
            ["DialogueId"] = 12043505,
            ["GUID"] = "1E264F8A",
            ["NextDialogue"] = 12043506,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264F8A",
            },
        [12043506] = {
            ["Content"] = "你好，我是……",
            ["ContentJP"] = "はじめまして、{性别:僕|私}は……",
            ["DialogueId"] = 12043506,
            ["GUID"] = "1E264FB4",
            ["NextDialogue"] = 12043507,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264FB4",
            },
        [12043507] = {
            ["Content"] = "不必介绍。你们几位的大名，我早有所耳闻啦。",
            ["ContentJP"] = "自己紹介はいらないよ。あんたたちの名前はとっくに知ってるからね。",
            ["DialogueId"] = 12043507,
            ["GUID"] = "1E264FDE",
            ["NextDialogue"] = 12043508,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E264FDE",
            },
        [12043508] = {
            ["Content"] = "你是扶氏家主，于六十年前的大疫中沉睡，又于去年苏醒的祝由扶疏。",
            ["ContentJP"] = "そっちはフー氏の当主、六十年前の疫病で眠り、去年目覚めた<Default note=\"text:しゅくゆ\">祝由</>フーシュ。",
            ["DialogueId"] = 12043508,
            ["GUID"] = "1E265008",
            ["NextDialogue"] = 12043509,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265008",
            },
        [12043509] = {
            ["Content"] = "你是自称“纯白的救赎☆光之魔王大人”，虽然总是爱说大话，但其实心思简单的海伯利亚皎皎，白。",
            ["ContentJP"] = "そっちは「純白の救い手☆そして光の魔王様」を名乗るヒュペリアのルーナ。大口ばかり叩くのが難点だが、純粋な心の持ち主。",
            ["DialogueId"] = 12043509,
            ["GUID"] = "1E265032",
            ["NextDialogue"] = 12043510,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265032",
            },
        [12043510] = {
            ["Content"] = "呜……你这人长得可可爱爱的，怎么说话和那个狗耳朵一样无情！",
            ["ContentJP"] = "うぅ……可愛い顔して、あのイヌミミみたいに毒舌だな！",
            ["DialogueId"] = 12043510,
            ["GUID"] = "1E26505C",
            ["NextDialogue"] = 12043511,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E26505C",
            },
        [12043511] = {
            ["Content"] = "嘻嘻……",
            ["ContentJP"] = "ふふ……",
            ["DialogueId"] = 12043511,
            ["GUID"] = "1E265086",
            ["NextDialogue"] = 12043512,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265086",
            },
        [12043512] = {
            ["Content"] = "以及你……来历神秘，有着奇特能力的白发勇者，{nickname}。止流万里迢迢请来的座上宾，解决烛阴之灾的大功臣。我说得没错吧？",
            ["ContentJP"] = "そしてあんた。素性不明で奇妙な力を持つ白髪の勇者、{nickname}。\
シリュウが遥々呼び寄せ、燭陰退治で大手柄を立てた客人。何か間違っていたかしら？",
            ["DialogueId"] = 12043512,
            ["GUID"] = "1E2650B0",
            ["NextDialogue"] = 12043513,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2650B0",
            },
        [12043513] = {
            ["Content"] = "对了，听说你超级厉害！之后有空，请务必来帮我测试机傀的实战数据，拜托你了！",
            ["ContentJP"] = "聞いてるよ、腕が立つって。今度時間があったら、ぜひ私のからくり人形の実戦テストに付き合ってほしいね。頼むよ！",
            ["DialogueId"] = 12043513,
            ["GUID"] = "1E2650DA",
            ["NextOptions"] = {
                [1] = 12043514,
                [2] = 12043515,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2650DA",
            },
        [12043514] = {
            ["Content"] = "谬传而已，我只是帮了一点小忙。",
            ["ContentJP"] = "噂ほどじゃない。少し手を貸しただけ{性别:さ|だよ}。",
            ["DialogueId"] = 12043514,
            ["GUID"] = "1E265104",
            ["NextDialogue"] = 12043516,
            },
        [12043515] = {
            ["Content"] = "哦？原来我这么能打？",
            ["ContentJP"] = "へぇ、そんなに強い{性别:のか、僕。|んだ、私。}",
            ["DialogueId"] = 12043515,
            ["GUID"] = "1E26512E",
            ["NextDialogue"] = 12043516,
            },
        [12043516] = {
            ["Content"] = "原来你早就知道我们了！那刚刚干嘛还要装出一副不认识的样子？",
            ["ContentJP"] = "じゃあ何で最初は知らないふりしたんだよ！",
            ["DialogueId"] = 12043516,
            ["GUID"] = "1E265158",
            ["NextDialogue"] = 12043517,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265158",
            },
        [12043517] = {
            ["Content"] = "嘿嘿，刚刚真是对不起啦。消消气，苏乙给你赔罪可好？——就让这只小小乙鸟给你们表演一段飞行绝活吧！",
            ["ContentJP"] = "へへ、悪かったね。機嫌を直して。お詫びにこの小さな「<Default note=\"text:いちょう\">乙鳥</>」の空中芸を見せてあげるからさ！",
            ["DialogueId"] = 12043517,
            ["GUID"] = "1E265182",
            ["NextDialogue"] = 12043518,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265182",
            },
        [12043518] = {
            ["Content"] = "但是，确认暗号的步骤是必不可少的哦。如果疏忽了保密工作，因此带来不可控的风险，甚至导致有人殒命……我是不会让这种事情发生的。",
            ["ContentJP"] = "……でも暗号確認は絶対必要なの。もしおろそかにして危険を招き、死人でも出たら……それだけは何としても防ぎたいわ。",
            ["DialogueId"] = 12043518,
            ["GUID"] = "1E2651AC",
            ["NextDialogue"] = 12043519,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2651AC",
            },
        [12043519] = {
            ["Content"] = "嗯。你的顾虑我能够理解。",
            ["ContentJP"] = "その気持ちはわかるよ。",
            ["DialogueId"] = 12043519,
            ["GUID"] = "1E2651D6",
            ["NextDialogue"] = 12043520,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E2651D6",
            },
        [12043520] = {
            ["Content"] = "如果是这种理由……那白也原谅你了！",
            ["ContentJP"] = "そういうことなら……許してあげる！",
            ["DialogueId"] = 12043520,
            ["GUID"] = "1E265200",
            ["NextDialogue"] = 12043521,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265200",
            },
        [12043521] = {
            ["Content"] = "接下来这段路，有非常多的岔路口。通往基地的路线每日按周天大衍之数轮换，若是走错一步，便要迷失在荒郊野岭中了。",
            ["ContentJP"] = "この先は分かれ道が多い。基地へのルートは暦数で毎日変わるの。ひとつでも間違えたら、荒野で迷子よ。",
            ["DialogueId"] = 12043521,
            ["GUID"] = "1E26522A",
            ["NextDialogue"] = 12043522,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E26522A",
            },
        [12043522] = {
            ["Content"] = "你们可要跟紧了，别走丢哦！",
            ["ContentJP"] = "だから、ちゃんと着いてきなさい。",
            ["DialogueId"] = 12043522,
            ["GUID"] = "1E265254",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120435/1E265254",
            },
        [12043601] = {
            ["Content"] = "回来啦，小苏。外面还平安吗？",
            ["ContentJP"] = "おかえり、スー。外はどうだった？",
            ["DialogueId"] = 12043601,
            ["GUID"] = "1E265F4A",
            ["NextDialogue"] = 12043602,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265F4A",
            },
        [12043602] = {
            ["Content"] = "唐叔，你怎么出来了？你前几天测试“螺旋升天式斗笠试验机”时落下的腿伤还没好利索呢，还是要乖乖躺着才好——",
            ["ContentJP"] = "タンさん、どうして出てきてるの。こないだ「<Default note=\"text:らせんしょうてんしきしさくかさひこうき\">螺旋昇天式試作笠飛行機</>」の実験で痛めた足、まだ治ってないでしょ。\
ちゃんと休んでなきゃ――",
            ["DialogueId"] = 12043602,
            ["GUID"] = "1E265F74",
            ["NextDialogue"] = 12043603,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265F74",
            },
        [12043603] = {
            ["Content"] = "呵呵，小伤，不碍事。倒是你，还是那么爱操心。",
            ["ContentJP"] = "はは、かすり傷だ。お前は相変わらず人のことばかり気にするなあ。",
            ["DialogueId"] = 12043603,
            ["GUID"] = "1E265F9E",
            ["NextDialogue"] = 12043604,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265F9E",
            },
        [12043604] = {
            ["Content"] = "还记得你刚来的时候，也就和天天抱着的牵机鸟一般高，一转眼，就成小大人喽。",
            ["ContentJP"] = "そういや来たばかりの頃は、からくり鳥と同じくらいの背丈だったのに……もうすっかり大人だな。",
            ["DialogueId"] = 12043604,
            ["GUID"] = "1E265FC8",
            ["NextDialogue"] = 12043605,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265FC8",
            },
        [12043605] = {
            ["Content"] = "……唐叔！外人面前就别唠叨这些啦！",
            ["ContentJP"] = "……タンさん！他人の前でそういう昔話はやめてよ！",
            ["DialogueId"] = 12043605,
            ["GUID"] = "1E265FF2",
            ["NextDialogue"] = 12043606,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E265FF2",
            },
        [12043606] = {
            ["Content"] = "哎呀，老了老了，眼神不好。原来是你们口中的那位{nickname}来了。刻舟那小子正念着你们呢。",
            ["ContentJP"] = "おっと、まったく俺も年を取ったものだ。君が言ってた{nickname}じゃないか。カシュウが首を長くして待ってたぞ。",
            ["DialogueId"] = 12043606,
            ["GUID"] = "1E26601C",
            ["NextDialogue"] = 12043607,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E26601C",
            },
        [12043607] = {
            ["Content"] = "刻舟？他已经回来了吗？",
            ["ContentJP"] = "カシュウ？もう帰ってきてるの？",
            ["DialogueId"] = 12043607,
            ["GUID"] = "1E266046",
            ["NextDialogue"] = 12043608,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E266046",
            },
        [12043608] = {
            ["Content"] = "刚回来，他在前头等着你们呢。",
            ["ContentJP"] = "ついさっきな。この先の広場で待っているよ。",
            ["DialogueId"] = 12043608,
            ["GUID"] = "1E266070",
            ["NextDialogue"] = 12043609,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E266070",
            },
        [12043609] = {
            ["Content"] = "好啊，我可是有不少账要和他好好算算……{nickname}，我们走！",
            ["ContentJP"] = "へえ……ちょうど積もる話が山ほどあったのよね。{nickname}、行くわよ！",
            ["DialogueId"] = 12043609,
            ["GUID"] = "1E26609A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120436/1E26609A",
            },
        [12043701] = {
            ["Content"] = "哟，你们来啦！怎么样，所谓云山深处更有洞天，我们这山外山的风景是不是很——",
            ["ContentJP"] = "おっ、来たな！どうだ、雲の奥の桃源郷――俺たちの<Default note=\"text:さんがいさんン\">山外山</>の景色は――",
            ["DialogueId"] = 12043701,
            ["GUID"] = "1E266FB2",
            ["NextDialogue"] = 12043702,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E266FB2",
            },
        [12043702] = {
            ["Content"] = "刻——舟！",
            ["ContentJP"] = "カ――シュウ！",
            ["DialogueId"] = 12043702,
            ["GUID"] = "1E266FDC",
            ["NextDialogue"] = 12043703,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E266FDC",
            },
        [12043703] = {
            ["Content"] = "刚瞒着大家在外面捅出天大的篓子，就装出一副若无其事的样子，这像话吗？啊？这像话吗？",
            ["ContentJP"] = "あんたね、みんなに内緒で外でとんでもない騒ぎ起こしておいて、よくもまぁ涼しい顔で帰ってきたわね！",
            ["DialogueId"] = 12043703,
            ["GUID"] = "1E267006",
            ["NextDialogue"] = 12043704,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267006",
            },
        [12043704] = {
            ["Content"] = "哈哈……这不是知道姑奶奶办事熨帖，滴水不漏，让基地的大家都无后顾之忧吗？要是离了姑奶奶，这个家得散！",
            ["ContentJP"] = "ははは、ほら、叔母さまの手腕は天下一品。俺が外しても拠点は安泰、心配ご無用ってわけだ！",
            ["DialogueId"] = 12043704,
            ["GUID"] = "1E267030",
            ["NextDialogue"] = 12043705,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267030",
            },
        [12043705] = {
            ["Content"] = "别以为你说几句好话，我就能放过你。这次可没这么简单！",
            ["ContentJP"] = "おだてたって許さないわよ！",
            ["DialogueId"] = 12043705,
            ["GUID"] = "1E26705A",
            ["NextDialogue"] = 12043706,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26705A",
            },
        [12043706] = {
            ["Content"] = "你招惹什么不好，非得招惹白龙那个狴犴头子！这下好了，外面全都是狴犴和应天尉，够你喝好几壶的！",
            ["ContentJP"] = "よりによってあの幹部の白龍なんかに喧嘩売って……今ごろ外は<Default note=\"text:ビーアン\">狴犴</>と<Default note=\"text:おうてんい\">応天尉</>だらけよ！",
            ["DialogueId"] = 12043706,
            ["GUID"] = "1E267084",
            ["NextDialogue"] = 12043707,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267084",
            },
        [12043707] = {
            ["Content"] = "嘿嘿，我这不是全须全尾地回来山外山了么。有咱们<H>天罗拒风仪</>在，能切断大风九章的感应，那些蠢狼寻不过来的。",
            ["ContentJP"] = "まあまあ、こうして無事に帰ってきただろ？<H><Default note=\"text:てんらきょふうぎ\">天羅拒風儀</></>、これさえあれば大風九章には探知されねぇし。",
            ["DialogueId"] = 12043707,
            ["GUID"] = "1E2670AE",
            ["NextDialogue"] = 12043708,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2670AE",
            },
        [12043708] = {
            ["Content"] = "你还狡辩！要不是有{nickname}在，你的小命早就不知道丢哪里去了！",
            ["ContentJP"] = "言い訳は結構！ {nickname}がいなかったら、あんた今ごろここにいなかったのよ！",
            ["DialogueId"] = 12043708,
            ["GUID"] = "1E2670D8",
            ["NextDialogue"] = 12043709,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2670D8",
            },
        [12043709] = {
            ["Content"] = "{nickname}，快，赶紧帮我求求情啊！",
            ["ContentJP"] = "なあ、{nickname}も何とか言ってくれよ。",
            ["DialogueId"] = 12043709,
            ["GUID"] = "1E267102",
            ["NextDialogue"] = 12043710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267102",
            },
        [12043710] = {
            ["Content"] = "刻舟先前和我们说……",
            ["ContentJP"] = "そういえば、さっきカシュウ……",
            ["DialogueId"] = 12043710,
            ["GUID"] = "1E26712C",
            ["NextOptions"] = {
                [1] = 12043711,
                [2] = 12043712,
                },
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26712C",
            },
        [12043711] = {
            ["Content"] = "（附和刻舟）",
            ["ContentJP"] = "（カシュウに合わせる）",
            ["DialogueId"] = 12043711,
            ["GUID"] = "1E267156",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12043713,
            },
        [12043712] = {
            ["Content"] = "（揭穿刻舟）",
            ["ContentJP"] = "（ありのまま話す）",
            ["DialogueId"] = 12043712,
            ["GUID"] = "1E267180",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12043716,
            },
        [12043713] = {
            ["Content"] = "他说你是举世无双的天才美少女，人很好，做事特别可靠，非常值得信赖！",
            ["ContentJP"] = "あなたは世界一の天才美少女で、人柄も良く、仕事は超頼りになる……そんな人だって言ってた{性别:なぁ|よ}！",
            ["DialogueId"] = 12043713,
            ["GUID"] = "1E2671AA",
            ["NextDialogue"] = 12043714,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2671AA",
            },
        [12043714] = {
            ["Content"] = "哇，小仆从，你还真是脸不红心不跳，张口就来……",
            ["ContentJP"] = "わー、下僕、よくもまあ平然とそんな嘘を……",
            ["DialogueId"] = 12043714,
            ["GUID"] = "1E2671D4",
            ["NextDialogue"] = 12043715,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2671D4",
            },
        [12043715] = {
            ["Content"] = "够了够了，别再说啦——",
            ["ContentJP"] = "や、やめなさいよ！そんなこと――",
            ["DialogueId"] = 12043715,
            ["GUID"] = "1E2671FE",
            ["NextDialogue"] = 12043719,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2671FE",
            },
        [12043716] = {
            ["Content"] = "他说你脾气不太好，规矩也多。只有耳根子软，只要说两句好话，就能把事情揭过去了。",
            ["ContentJP"] = "あなたは気が短くて口うるさいけど、褒められるとなんでも許しちゃう……って言ってたよ。",
            ["DialogueId"] = 12043716,
            ["GUID"] = "1E267228",
            ["NextDialogue"] = 12043717,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267228",
            },
        [12043717] = {
            ["Content"] = "喂喂喂，{nickname}，你还真是一点情面都不留啊……",
            ["ContentJP"] = "おいおい、{nickname}、少しは穏やかに言えよ……",
            ["DialogueId"] = 12043717,
            ["GUID"] = "1E267252",
            ["NextDialogue"] = 12043718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267252",
            },
        [12043718] = {
            ["Content"] = "呵，我就知道！我再也不会上他的当了！",
            ["ContentJP"] = "ふん！そんなことだろうと思ったわ！",
            ["DialogueId"] = 12043718,
            ["GUID"] = "1E26727C",
            ["NextDialogue"] = 12043719,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26727C",
            },
        [12043719] = {
            ["Content"] = "哼，刻舟那小子的帐我之后再和他慢慢清算，还是先说回正事吧。",
            ["ContentJP"] = "ま、カシュウのことは後でしっかり落とし前つけるとして……本題に戻りましょう。",
            ["DialogueId"] = 12043719,
            ["GUID"] = "1E2672A6",
            ["NextDialogue"] = 12043720,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2672A6",
            },
        [12043720] = {
            ["Content"] = "事情的前因后果我已经了解了，止流吸收了烛阴的力量，欲求成神……虽然暂时无法确认她的真实意图，但她很有可能成为山外山的潜在威胁。",
            ["ContentJP"] = "事情は大体わかったわ。シリュウは<Default note=\"text:しょくいん\">燭陰</>の力を取り込み、神になろうとしてる……\
本当の目的はまだ分からないけど、山外山にとっては確実に脅威になり得る存在よ。",
            ["DialogueId"] = 12043720,
            ["GUID"] = "1E2672D0",
            ["NextDialogue"] = 12043721,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2672D0",
            },
        [12043721] = {
            ["Content"] = "总之这次情况不容小觑。你们接下来有什么计划？",
            ["ContentJP"] = "油断はできないわ。あんたたち、これからどう動くつもり？",
            ["DialogueId"] = 12043721,
            ["GUID"] = "1E2672FA",
            ["NextDialogue"] = 12043722,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2672FA",
            },
        [12043722] = {
            ["Content"] = "我不想被止流牵着鼻子走。我得尽快打破她的布局。",
            ["ContentJP"] = "シリュウの思い通りになんてさせない。もちろん阻止するつもりだよ。",
            ["DialogueId"] = 12043722,
            ["GUID"] = "1E267324",
            ["NextDialogue"] = 12043723,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267324",
            },
        [12043723] = {
            ["Content"] = "赞同！如今的当务之急，是早日找到那个女人的踪迹，也好对她下一步的谋划有所打算。",
            ["ContentJP"] = "俺も賛成だ！とにかく早くあの女の行方を掴んで、次の一手を考えないとな。",
            ["DialogueId"] = 12043723,
            ["GUID"] = "1E26734E",
            ["NextDialogue"] = 12043724,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26734E",
            },
        [12043724] = {
            ["Content"] = "很遗憾……这点我早就想到了。",
            ["ContentJP"] = "残念だけど……それは難しいでしょう。",
            ["DialogueId"] = 12043724,
            ["GUID"] = "1E267378",
            ["NextDialogue"] = 12043725,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267378",
            },
        [12043725] = {
            ["Content"] = "根据城中密探传回的消息，自从她昨日在天禄司门口现身后，整个皓京城，再无人目击到止流的踪迹，就连天上徘徊的机关鸟也无能为力。她就这样人间蒸发了。",
            ["ContentJP"] = "密偵の報告じゃ、昨日<Default note=\"text:てんろくし\">天禄司</>の門前に姿を見せた後の行方は掴めなかった。\
空を飛ぶからくり鳥ですら追えなかった。まるで消えたみたいにね。",
            ["DialogueId"] = 12043725,
            ["GUID"] = "1E2673A2",
            ["NextDialogue"] = 12043726,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2673A2",
            },
        [12043726] = {
            ["Content"] = "或许……我们现在的反应，也在她的预料之中。",
            ["ContentJP"] = "……{性别:僕|私}たちの動きを読んでいたのかも。",
            ["DialogueId"] = 12043726,
            ["GUID"] = "1E2673CC",
            ["NextDialogue"] = 12043727,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2673CC",
            },
        [12043727] = {
            ["Content"] = "目前看来，比起找寻止流的下落，破解{nickname}身上的催眠，从而知道她接下来的布置，可能更加现实一点。",
            ["ContentJP"] = "今はシリュウの居場所探しより、{nickname}にかけられた催眠術を解いて、奴の次の手を見抜いた方が早いと思うわ。",
            ["DialogueId"] = 12043727,
            ["GUID"] = "1E2673F6",
            ["NextDialogue"] = 12043728,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2673F6",
            },
        [12043728] = {
            ["Content"] = "我……或许有些眉目。",
            ["ContentJP"] = "少し……心当たりがございます。",
            ["DialogueId"] = 12043728,
            ["GUID"] = "1E267420",
            ["NextDialogue"] = 12043729,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267420",
            },
        [12043729] = {
            ["Content"] = "扶疏姐姐，你想到了什么吗？",
            ["ContentJP"] = "ん？なになに！？",
            ["DialogueId"] = 12043729,
            ["GUID"] = "1E26744A",
            ["NextDialogue"] = 12043730,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26744A",
            },
        [12043730] = {
            ["Content"] = "世人皆知悬衡、机枢两门显学。却少有人知，上古时期本是百家争鸣。其中不乏传承至今避世简出的旁门奇派，如秉烛、观微派……",
            ["ContentJP"] = "世の人は<Default note=\"text:けんこう\">懸衡</>と<Default note=\"text:きすう\">機枢</>という二大流派しか知りませんが……古代には百家が並び立っておりました。\
その中には今も隠れて生きる傍流がございます。たとえば<Default note=\"text:へいしょくは\">秉燭派</>や<Default note=\"text:かんびは\">観微派</>……",
            ["DialogueId"] = 12043730,
            ["GUID"] = "1E267474",
            ["NextDialogue"] = 12043731,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267474",
            },
        [12043731] = {
            ["Content"] = "我明白了！",
            ["ContentJP"] = "なるほど！",
            ["DialogueId"] = 12043731,
            ["GUID"] = "1E26749E",
            ["NextDialogue"] = 12043732,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26749E",
            },
        [12043732] = {
            ["Content"] = "卜卦奇算，窥伺未来，甚至于以特定手法操纵人心……你想说的，莫非是<H>无穷藏派</>？",
            ["ContentJP"] = "占いで未来を読み、人心を操るといえば……まさか<H>「<Default note=\"text:むきゅうぞうは\">無窮蔵派</>」</>のこと？",
            ["DialogueId"] = 12043732,
            ["GUID"] = "1E2674C8",
            ["NextDialogue"] = 12043733,
            ["RelatedWikiId"] = {
                [1] = 407014,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2674C8",
            },
        [12043733] = {
            ["Content"] = "正是如此。",
            ["ContentJP"] = "まさしく。",
            ["DialogueId"] = 12043733,
            ["GUID"] = "1E2674F2",
            ["NextDialogue"] = 12043734,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2674F2",
            },
        [12043734] = {
            ["Content"] = "先前为{nickname}把脉时，我便隐隐有些预感。未曾想到，身为龙渊上卿的止流竟是无穷藏派的传人。",
            ["ContentJP"] = "先日{nickname}さんの脈を診たとき、うっすら予感しておりました。とはいえ、まさか龍淵の上卿であるシリュウが、その伝人とは……",
            ["DialogueId"] = 12043734,
            ["GUID"] = "1E26751C",
            ["NextDialogue"] = 12043735,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26751C",
            },
        [12043735] = {
            ["Content"] = "接下来，我打算去城中寻访无穷藏派的隐居踪迹，好为{nickname}的记忆恢复做打算。",
            ["ContentJP"] = "{nickname}さんの記憶を取り戻すためにも、今から城で<Default note=\"text:むきゅうぞうは\">無窮蔵派</>の痕跡を探そうかと。",
            ["DialogueId"] = 12043735,
            ["GUID"] = "1E267546",
            ["NextDialogue"] = 12043736,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267546",
            },
        [12043736] = {
            ["Content"] = "我也跟你一起去。",
            ["ContentJP"] = "{性别:僕も行くよ。|私も行くわ。}",
            ["DialogueId"] = 12043736,
            ["GUID"] = "1E267570",
            ["NextDialogue"] = 12043737,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267570",
            },
        [12043737] = {
            ["Content"] = "不妥。",
            ["ContentJP"] = "ダメ。（いけません。）",
            ["DialogueId"] = 12043737,
            ["GUID"] = "1E26759A",
            ["NextDialogue"] = 12043738,
            ["SpeakNpcName"] = "UI_Npc_Name_FuShuSuYi",
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26759A",
            },
        [12043738] = {
            ["Content"] = "根据线报，城中如今风声正紧呢。你们在执律阁对白龙神大不敬，现在狴犴和应天尉都在四处抓捕你们。依我看，你们还是先待在这里暂避风头比较好。",
            ["ContentJP"] = "今、城は物々しい雰囲気よ。<Default note=\"text:しつりつかく\">執律閣</>で白龍様を怒らせた件で、<Default note=\"text:ビーアン\">狴犴</>や<Default note=\"text:おうてんい\">応天尉</>があんたたちを探し回ってる。\
今ここにいた方が安全だわ。",
            ["DialogueId"] = 12043738,
            ["GUID"] = "1E2675C4",
            ["NextDialogue"] = 12043739,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2675C4",
            },
        [12043739] = {
            ["Content"] = "苏姑娘所言有理。{nickname}，先前你与太皓交手，力量过度消耗，正是应当静养的时候。",
            ["ContentJP"] = "スーイーさんの言う通りです。太皓との戦いで力も消耗しておられるはず。今は養生なさるべきです。",
            ["DialogueId"] = 12043739,
            ["GUID"] = "1E2675EE",
            ["NextDialogue"] = 12043740,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2675EE",
            },
        [12043740] = {
            ["Content"] = "此外，这趟我还有些私事要处理，可能不便与人同行……抱歉。",
            ["ContentJP"] = "それに、この道中には私事も絡みますので、同行は同意できかねます……申し訳ございません。",
            ["DialogueId"] = 12043740,
            ["GUID"] = "1E267618",
            ["NextOptions"] = {
                [1] = 12043741,
                [2] = 12043742,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267618",
            },
        [12043741] = {
            ["Content"] = "好吧，那我尊重你的想法。",
            ["ContentJP"] = "わかった。あなたの考えに従うよ。",
            ["DialogueId"] = 12043741,
            ["GUID"] = "1E267642",
            ["NextDialogue"] = 12043743,
            },
        [12043742] = {
            ["Content"] = "有点不甘心……",
            ["ContentJP"] = "ちょっと納得いかないな……",
            ["DialogueId"] = 12043742,
            ["GUID"] = "1E26766C",
            ["NextDialogue"] = 12043743,
            },
        [12043743] = {
            ["Content"] = "既然{nickname}暂时不方便露面，就让本人替你出去一转——",
            ["ContentJP"] = "そんじゃあ、{nickname}の代わりに俺がひとっ走りして――",
            ["DialogueId"] = 12043743,
            ["GUID"] = "1E267696",
            ["NextDialogue"] = 12043744,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267696",
            },
        [12043744] = {
            ["Content"] = "你？你就给我好好待在山外山，别出去添乱了。别忘了，基地里的大小事宜都需要人手。谷底伤人的野兽清理了吗？破损的屋顶修缮了吗？",
            ["ContentJP"] = "はぁ？ あんたはおとなしく<Default note=\"text:さんがいさん\">山外山</>に居なさいっての。\
他にやることは山ほどあるでしょ？谷底で人を襲う獣は片づけたの？壊れた屋根は直した？口だけで手は動いてないよね？",
            ["DialogueId"] = 12043744,
            ["GUID"] = "1E2676C0",
            ["NextDialogue"] = 12043745,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2676C0",
            },
        [12043745] = {
            ["Content"] = "先前你满口打包票说要帮忙，这些空口支票还从来没兑现过呢。",
            ["ContentJP"] = "前に約束したこと、まだ一つも果たせてないんだけど！？",
            ["DialogueId"] = 12043745,
            ["GUID"] = "1E2676EA",
            ["NextDialogue"] = 12043746,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2676EA",
            },
        [12043746] = {
            ["Content"] = "咳咳，有一件事姑奶奶可能不知。这里的两位和我可是拜过把子的交情。很乐意替我代劳，一起为基地建设添砖加瓦。",
            ["ContentJP"] = "ゴホン……そ、その、実は{nickname}とはもう兄弟みたいなもんでな。\
きっと、俺の代わりにでも喜んで働いてくれるさ――基地づくりにも、一役買ってくれるだろうよ。",
            ["DialogueId"] = 12043746,
            ["GUID"] = "1E267714",
            ["NextDialogue"] = 12043747,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267714",
            },
        [12043747] = {
            ["Content"] = "刻舟！你不想干活也就算了，怎么还推脱到别人身上！",
            ["ContentJP"] = "カシュウ！やりなくないからって客人に押し付ける気！？",
            ["DialogueId"] = 12043747,
            ["GUID"] = "1E26773E",
            ["NextDialogue"] = 12043748,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26773E",
            },
        [12043748] = {
            ["Content"] = "非也。乍看之下，是我刻舟在找借口。但其实是姑奶奶听了{nickname}的事迹后，对你们仰慕已久。我为几位创造相处机会，可谓用心良苦——",
            ["ContentJP"] = "誤解だって。{nickname}の話を聞いてから、ずっと会いたがってただろう？だから時間作ってやろうって思ってな。\
俺なりの気遣いってやつだ。",
            ["DialogueId"] = 12043748,
            ["GUID"] = "1E267768",
            ["NextDialogue"] = 12043749,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267768",
            },
        [12043749] = {
            ["Content"] = "……闭嘴！！真是的！{nickname}，你可别听那家伙的胡言乱语！他满嘴跑火车，就没一句是真的！",
            ["ContentJP"] = "……お黙り！！もう！{nickname}、こいつの言うこと真に受けないで。ほとんど作り話なんだから！",
            ["DialogueId"] = 12043749,
            ["GUID"] = "1E267792",
            ["NextOptions"] = {
                [1] = 12043750,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267792",
            },
        [12043750] = {
            ["Content"] = "所以“仰慕已久”也是假的？",
            ["ContentJP"] = "じゃあ、「ずっと会いたかった」ってのも嘘？",
            ["DialogueId"] = 12043750,
            ["GUID"] = "1E2677BC",
            ["NextDialogue"] = 12043751,
            },
        [12043751] = {
            ["Content"] = "那，我确实觉得你很厉害啦……不对，被他绕进去了！你们是客人，哪有让客人来干活的道理。",
            ["ContentJP"] = "……まあ、すごいなとは思ってたけど……って、違う違う！客人に働かせるわけないでしょ！",
            ["DialogueId"] = 12043751,
            ["GUID"] = "1E2677E6",
            ["NextDialogue"] = 12043752,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2677E6",
            },
        [12043752] = {
            ["Content"] = "哼哼，看在你如此仰慕白和小仆从的份上，也不是不能搭把手啦！",
            ["ContentJP"] = "ふふん♪そこまで言うなら、ちょっとくらい手伝ってあげてもいいけど？",
            ["DialogueId"] = 12043752,
            ["GUID"] = "1E267810",
            ["NextDialogue"] = 12043753,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267810",
            },
        [12043753] = {
            ["Content"] = "我们留在这里，帮忙做点事也是应该的。",
            ["ContentJP"] = "せっかくだし、できることはやるよ。",
            ["DialogueId"] = 12043753,
            ["GUID"] = "1E26783A",
            ["NextDialogue"] = 12043754,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26783A",
            },
        [12043754] = {
            ["Content"] = "你们愿意固然好啦……不要受那个家伙的话术影响就行！我先替山外山的大伙谢谢你们啦。",
            ["ContentJP"] = "助かるけど……あいつの口車には乗らない方がいいよ。まぁ、先に礼を言っとくわ。",
            ["DialogueId"] = 12043754,
            ["GUID"] = "1E267864",
            ["NextDialogue"] = 12043755,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E267864",
            },
        [12043755] = {
            ["Content"] = "那我便先告辞了。若有了消息，我会第一时间赶回来。",
            ["ContentJP"] = "では、私はこれで。何かしらの報せがありましたなら、すぐさま戻ってまいりますゆえ。",
            ["DialogueId"] = 12043755,
            ["GUID"] = "1E26788E",
            ["NextDialogue"] = 12043756,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E26788E",
            },
        [12043756] = {
            ["Content"] = "好，扶疏姐姐，我们等着你！你一路上也要小心哦！",
            ["ContentJP"] = "うん、フーシュも気をつけてね！",
            ["DialogueId"] = 12043756,
            ["GUID"] = "1E2678B8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120437/1E2678B8",
            },
        [12043801] = {
            ["Content"] = "依我看，只要在那恶鸟大咧咧靠近之时，趁其不备，引弓长射，就能将它一击拿下！",
            ["ContentJP"] = "あの鳥が油断して近づいた瞬間に矢を放てば、一発で仕留められるはず……",
            ["DialogueId"] = 12043801,
            ["GUID"] = "1E26801A",
            ["NextDialogue"] = 12043802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26801A",
            },
        [12043802] = {
            ["Content"] = "唉，可惜我的准头还是不太行……要是一箭射空，在这埋伏半天的功夫就白费了，身上这些豆大的蚊子包也白被咬了。",
            ["ContentJP"] = "けど俺の腕じゃ外すかもしれねぇ。そうなったら何日も張ってたのが無駄になる。ただ蚊に刺されまくってただけになっちまうな……",
            ["DialogueId"] = 12043802,
            ["GUID"] = "1E268044",
            ["NextDialogue"] = 12043803,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268044",
            },
        [12043803] = {
            ["Content"] = "不行不行，还是得想想其他法子。",
            ["ContentJP"] = "ダメだ、他の手を考えねぇと。",
            ["DialogueId"] = 12043803,
            ["GUID"] = "1E26806E",
            ["NextDialogue"] = 12043804,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26806E",
            },
        [12043804] = {
            ["Content"] = "嗯……师傅前几日刚教过感应机关的制备方法，正好适用于这种场景。",
            ["ContentJP"] = "この前、師匠から感応からくりの作り方を教わったばかりなんだ。まさにこういう場面で使えるはずなんだけど……",
            ["DialogueId"] = 12043804,
            ["GUID"] = "1E268098",
            ["NextDialogue"] = 12043805,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268098",
            },
        [12043805] = {
            ["Content"] = "但是要把它还原出来，还缺上几种材料。要等到找齐材料，这坏鸟早就吃饱喝足，抖抖羽毛飞走了。要是能在哪里找到制备好的现成机关就好了……",
            ["ContentJP"] = "でも、完成させるには材料がまだ足りない。全部集めてる間に、あの鳥は腹を満たして羽ばたいて行っちまうだろうな……どこかに完成品が落ちてりゃいいのに。",
            ["DialogueId"] = 12043805,
            ["GUID"] = "1E2680C2",
            ["NextDialogue"] = 12043806,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2680C2",
            },
        [12043806] = {
            ["Content"] = "阿晨，小野，我说你们两个，现在还是课业时间吧。怎么不去上课习武，反而躲在这里偷懒了？",
            ["ContentJP"] = "シン！リク！今は授業の時間でしょ？なんでこんなところでサボってるの。",
            ["DialogueId"] = 12043806,
            ["GUID"] = "1E2680EC",
            ["NextDialogue"] = 12043807,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2680EC",
            },
        [12043807] = {
            ["Content"] = "哇啊啊——是苏乙姐姐！",
            ["ContentJP"] = "わっ！？スーイー姉ちゃん！？",
            ["DialogueId"] = 12043807,
            ["GUID"] = "1E268116",
            ["NextDialogue"] = 12043808,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268116",
            },
        [12043808] = {
            ["Content"] = "好的不学，偏学刻舟那家伙逃课是吧？被我逮了个正着，这下可有人要吃苦头咯。",
            ["ContentJP"] = "なるほど、どうやら、カシュウのサボり癖はしっかり受け継いだわけだ。覚悟はできてるんでしょうね？",
            ["DialogueId"] = 12043808,
            ["GUID"] = "1E268140",
            ["NextDialogue"] = 12043809,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268140",
            },
        [12043809] = {
            ["Content"] = "苏乙姐姐，你先听我们说完！",
            ["ContentJP"] = "ちょっ、違うって！聞いてよ！",
            ["DialogueId"] = 12043809,
            ["GUID"] = "1E26816A",
            ["NextDialogue"] = 12043810,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26816A",
            },
        [12043810] = {
            ["Content"] = "那个，逃课是我们不对。但我前几天在药田里值勤时，飞来一只恶鸟。它不仅糟蹋田里面的药草，把叶子扯得到处都是，还耀武扬威地在我头上拉屎——",
            ["ContentJP"] = "この前、薬草畑の見回りしてたら、あの鳥が飛んできてな。薬草を食い荒らして、葉っぱまでちぎるんだ。しかも、俺の頭にフンを…！",
            ["DialogueId"] = 12043810,
            ["GUID"] = "1E268194",
            ["NextDialogue"] = 12043811,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268194",
            },
        [12043811] = {
            ["Content"] = "我们飘零人，仗剑日月间，专管不平事，怎么能被一只鸟欺在头上？就算不为自己，为了朋友，我也得出了这口气！",
            ["ContentJP"] = "俺たち流れ者は、剣ひとつで世をさすらう。悪を討ち、不正を見過ごさないのが筋だ。鳥一羽にバカにされっぱなしじゃ、剣を持つ意味がねぇ！",
            ["DialogueId"] = 12043811,
            ["GUID"] = "1E2681BE",
            ["NextDialogue"] = 12043812,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2681BE",
            },
        [12043812] = {
            ["Content"] = "就像这样，小野他听了这事之后就打包票说要来帮忙。但是那鸟浑身心眼子，警惕得很。我们在这里蹲守了好几天，都没捉住它的一根羽毛……",
            ["ContentJP"] = "それでリクが「任せろ！」って言ってくれたんだけど、あの鳥、すっごく用心深くて。何日も張ってるのに羽の一本すら触れられなかったんだ。",
            ["DialogueId"] = 12043812,
            ["GUID"] = "1E2681E8",
            ["NextDialogue"] = 12043813,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E2681E8",
            },
        [12043813] = {
            ["Content"] = "那你们怎么不叫人帮忙？",
            ["ContentJP"] = "じゃあ最初から助っ人を呼べばよかったでしょ。",
            ["DialogueId"] = 12043813,
            ["GUID"] = "1E268212",
            ["NextDialogue"] = 12043814,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268212",
            },
        [12043814] = {
            ["Content"] = "……要是连一只鸟都降服不住，以后还谈什么惩恶扬善，仗剑助人。我、我丢不起这个人。",
            ["ContentJP"] = "……鳥一羽すら仕留められないようじゃ、この先どうやって悪を討つんだって話になるだろ。情けなくて頼めねぇよ。",
            ["DialogueId"] = 12043814,
            ["GUID"] = "1E26823C",
            ["NextDialogue"] = 12043815,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26823C",
            },
        [12043815] = {
            ["Content"] = "唉，你们啊……算了，正巧{nickname}来了，就让{性别：他|她}给你们露一手吧。",
            ["ContentJP"] = "……やれやれ。じゃ、{nickname}、あんたの腕前を見せてやって。",
            ["DialogueId"] = 12043815,
            ["GUID"] = "1E268266",
            ["NextDialogue"] = 12043816,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268266",
            },
        [12043816] = {
            ["Content"] = "{nickname}？！难、难不成是和刻舟哥哥一起手撕烛阴、脚踩太皓的那位绝世{性别：大侠|女侠}？这下见到真人了！",
            ["ContentJP"] = "えっ、{nickname}って……もしかして、カシュウ兄ちゃんと一緒に燭陰や太皓を見事に討ち取った、あの大英雄さん！？",
            ["DialogueId"] = 12043816,
            ["GUID"] = "1E268290",
            ["NextOptions"] = {
                [1] = 12043817,
                [2] = 12043818,
                },
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E268290",
            },
        [12043817] = {
            ["Content"] = "他都给你们灌输了什么奇怪故事……",
            ["ContentJP"] = "一体どんな話を吹き込まれた{性别:んだ……|の……}",
            ["DialogueId"] = 12043817,
            ["GUID"] = "1E2682BA",
            ["NextDialogue"] = 12043819,
            },
        [12043818] = {
            ["Content"] = "没错，正是本人！",
            ["ContentJP"] = "その通り！",
            ["DialogueId"] = 12043818,
            ["GUID"] = "1E2682E4",
            ["NextDialogue"] = 12043819,
            },
        [12043819] = {
            ["Content"] = "这可是个难得的机会，你们可要好好观摩了。",
            ["ContentJP"] = "いい機会だし、しっかり見ときな。",
            ["DialogueId"] = 12043819,
            ["GUID"] = "1E26830E",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120438/1E26830E",
            },
        [12043901] = {
            ["Content"] = "坏鸟、坏鸟！叫你成天得意洋洋，这下阴沟里翻船了吧。以后不许再偷吃我们的药草！",
            ["ContentJP"] = "よっしゃ！ざまぁみろ！こんど薬草畑を荒したらただじゃおかねぇぞ！",
            ["DialogueId"] = 12043901,
            ["GUID"] = "1E269082",
            ["NextDialogue"] = 12043902,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269082",
            },
        [12043902] = {
            ["Content"] = "欧——欧欧——",
            ["ContentJP"] = "ピィー！",
            ["DialogueId"] = 12043902,
            ["GUID"] = "1E2690AC",
            ["NextDialogue"] = 12043903,
            ["SpeakNpcId"] = 240032,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2690AC",
            },
        [12043903] = {
            ["Content"] = "这只白身苍尾的云翎鸥在你们面前呜咽了两声，灰溜溜地飞走了。",
            ["ContentJP"] = "蒼色の尾を持つ白いクモハネカモメはしょんぼりした様子で飛び去った。",
            ["DialogueId"] = 12043903,
            ["GUID"] = "1E2690D6",
            ["NextDialogue"] = 12043904,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2690D6",
            },
        [12043904] = {
            ["Content"] = "太厉害了，{nickname}{性别：哥哥|姐姐}！简直是闪电般的身手，我们还没看清楚动作就结束了！",
            ["ContentJP"] = "すごい……{nickname}{性别:お兄さん|お姉さん}、まるで稲妻みたいに一瞬だったよ！",
            ["DialogueId"] = 12043904,
            ["GUID"] = "1E269100",
            ["NextDialogue"] = 12043905,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269100",
            },
        [12043905] = {
            ["Content"] = "先别急着高兴——小小一只鸟儿，耗上几天功夫还捉不到。这说明了什么？只能说明你们现在学业不精。",
            ["ContentJP"] = "浮かれてる場合？小鳥一羽に何日も手こずるなんて、稽古不足だって証拠よ。",
            ["DialogueId"] = 12043905,
            ["GUID"] = "1E26912A",
            ["NextDialogue"] = 12043906,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E26912A",
            },
        [12043906] = {
            ["Content"] = "阿晨，感应机关的制备材料明明有很多种替代方法。再不济，为牵机鸢加装射击模组，通过手动操控也能将鸟儿抓获。",
            ["ContentJP"] = "シン、からくりの材料なんて代用品はいくらでもある。最悪、からくり鳶に射撃モジュールをつければ捕まえられたはず。",
            ["DialogueId"] = 12043906,
            ["GUID"] = "1E269154",
            ["NextDialogue"] = 12043907,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269154",
            },
        [12043907] = {
            ["Content"] = "要是思维不够灵活，拘泥于定式中，可没法成长为优秀的机傀师哦。",
            ["ContentJP"] = "型にとらわれてたら一流のからくり師にはなれないよ。",
            ["DialogueId"] = 12043907,
            ["GUID"] = "1E26917E",
            ["NextDialogue"] = 12043908,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E26917E",
            },
        [12043908] = {
            ["Content"] = "是哦，我怎么没想到呢……",
            ["ContentJP"] = "……たしかに、そこまで考えてなかった……",
            ["DialogueId"] = 12043908,
            ["GUID"] = "1E2691A8",
            ["NextDialogue"] = 12043909,
            ["SpeakNpcId"] = 240031,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2691A8",
            },
        [12043909] = {
            ["Content"] = "再说你，小野。高明的射手不用说这么近的目标，就算是高空之中几不可见的鸿雁，也能一气呵成地拉弓击坠。你近期的射靶是不是疏于练习了？",
            ["ContentJP"] = "それから、リク。上手い射手ってのは、近距離はもちろん、空のかなたにいる雁だって一矢で落とせるもんだよ。最近、射的の稽古サボってない？",
            ["DialogueId"] = 12043909,
            ["GUID"] = "1E2691D2",
            ["NextDialogue"] = 12043910,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2691D2",
            },
        [12043910] = {
            ["Content"] = "可能是有偷懒了那么几次啦……",
            ["ContentJP"] = "……ちょ、ちょっとだけ……",
            ["DialogueId"] = 12043910,
            ["GUID"] = "1E2691FC",
            ["NextDialogue"] = 12043911,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2691FC",
            },
        [12043911] = {
            ["Content"] = "自己去武场领三十组射靶训练吧。你们这功夫对上应天尉，连一招都撑不过。",
            ["ContentJP"] = "弓の訓練、三十本！さっさと稽古しなさい！あんたたちの腕じゃ、<Default note=\"text:おうてんい\">応天尉</>とやり合ったって一瞬で終わるよ！",
            ["DialogueId"] = 12043911,
            ["GUID"] = "1E269226",
            ["NextDialogue"] = 12043912,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269226",
            },
        [12043912] = {
            ["Content"] = "我、我明白了！",
            ["ContentJP"] = "……わかった。",
            ["DialogueId"] = 12043912,
            ["GUID"] = "1E269250",
            ["NextDialogue"] = 12043913,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269250",
            },
        [12043913] = {
            ["Content"] = "你们先回去上课吧，我待会儿会来检查你们有没有在好好听讲的。不许一副没精打采的样子，快去！",
            ["ContentJP"] = "さ、授業に戻って。あとでちゃんと見に行くからね。だらけてたら許さないよ。",
            ["DialogueId"] = 12043913,
            ["GUID"] = "1E26927A",
            ["NextDialogue"] = 12043914,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E26927A",
            },
        [12043914] = {
            ["Content"] = "知道了，苏乙姐姐……",
            ["ContentJP"] = "はーい……",
            ["DialogueId"] = 12043914,
            ["GUID"] = "1E2692A4",
            ["NextDialogue"] = 12043915,
            ["SpeakNpcId"] = 240030,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2692A4",
            },
        [12043915] = {
            ["Content"] = "一打岔差点忘了正事，{nickname}，不好意思，让你见笑了……",
            ["ContentJP"] = "……と、大事な用事を忘れるところだった。{nickname}、情けないもの見せちゃったね。",
            ["DialogueId"] = 12043915,
            ["GUID"] = "1E2692CE",
            ["NextDialogue"] = 12043916,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2692CE",
            },
        [12043916] = {
            ["Content"] = "……{nickname}，小白，你们看我的眼神怎么这么犀利？",
            ["ContentJP"] = "……ちょっと、何よその目は。",
            ["DialogueId"] = 12043916,
            ["GUID"] = "1E2692F8",
            ["NextOptions"] = {
                [1] = 12043917,
                [2] = 12043918,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2692F8",
            },
        [12043917] = {
            ["Content"] = "还好我已经不需要上学了。",
            ["ContentJP"] = "いや、学生じゃなくてよかった{性别:な|ね}と。",
            ["DialogueId"] = 12043917,
            ["GUID"] = "1E269322",
            ["NextDialogue"] = 12043919,
            },
        [12043918] = {
            ["Content"] = "苏乙，你一定能成为让人闻风丧胆的好老师！",
            ["ContentJP"] = "スーイー、将来すごい先生になりそう。",
            ["DialogueId"] = 12043918,
            ["GUID"] = "1E26934C",
            ["NextDialogue"] = 12043919,
            },
        [12043919] = {
            ["Content"] = "咳咳，只是山外山的孩子们比较无拘无束。他们大多数因为大风九章失去了父母，所以我才会偶尔替师长管教一下他们……",
            ["ContentJP"] = "ゴホン、ここは親を亡くした子も多いからね。だから時々、代わりにちょっとだけ叱ってるだけよ。",
            ["DialogueId"] = 12043919,
            ["GUID"] = "1E269376",
            ["NextDialogue"] = 12043920,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E269376",
            },
        [12043920] = {
            ["Content"] = "好啦，不聊这些了。我们还是赶紧去采药吧！",
            ["ContentJP"] = "さて……薬草を摘みに行きましょう。",
            ["DialogueId"] = 12043920,
            ["GUID"] = "1E2693A0",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120439/1E2693A0",
            },
        [12044001] = {
            ["Content"] = "唐叔——我和{nickname}去采了些摔伤的药草，特意给你带来了！",
            ["ContentJP"] = "タンさん！{nickname}と一緒に薬草を取ってきたよ！",
            ["DialogueId"] = 12044001,
            ["GUID"] = "1E26A0EA",
            ["NextDialogue"] = 12044002,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A0EA",
            },
        [12044002] = {
            ["Content"] = "把药草捣碎了和上姜黄粉，再敷上几回，伤就基本好了，你就也能自由走动了。",
            ["ContentJP"] = "これをすり潰してウコン粉と混ぜて何度か貼れば、すぐ歩けるようになるよ。",
            ["DialogueId"] = 12044002,
            ["GUID"] = "1E26A114",
            ["NextDialogue"] = 12044003,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A114",
            },
        [12044003] = {
            ["Content"] = "呵呵……小苏还这么记挂着我的伤，真是大家的贴心小棉袄。那我可得赶紧把伤养好，不能让小苏天天操心喽。",
            ["ContentJP"] = "ははっ、スーは本当に気が利くな。じゃあ早く治して、心配かけないようにしないとな。",
            ["DialogueId"] = 12044003,
            ["GUID"] = "1E26A13E",
            ["NextDialogue"] = 12044004,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A13E",
            },
        [12044004] = {
            ["Content"] = "来得正好，这天罗拒风仪的调校工具你也一并拿走吧。省得我再找别人捎给你了。",
            ["ContentJP"] = "そうだ、ちょうどいい。<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>の調整道具を持っていきな。\
わざわざ誰かに届けてもらう手間も省けるしな。",
            ["DialogueId"] = 12044004,
            ["GUID"] = "1E26A168",
            ["NextDialogue"] = 12044005,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A168",
            },
        [12044005] = {
            ["Content"] = "天罗拒风仪……那是什么呀？",
            ["ContentJP"] = "てんらきょふうぎ……って何？",
            ["DialogueId"] = 12044005,
            ["GUID"] = "1E26A192",
            ["NextDialogue"] = 12044006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A192",
            },
        [12044006] = {
            ["Content"] = "小白，快别问——！唉，来不及了。",
            ["ContentJP"] = "あ、スノウ！それを聞いちゃダメ――",
            ["DialogueId"] = 12044006,
            ["GUID"] = "1E26A1BC",
            ["NextDialogue"] = 12044007,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A1BC",
            },
        [12044007] = {
            ["Content"] = "那是机枢派的得意之作。就算是路边碰见的一条大黄狗，唐叔也得拉住它叨叨个半天原理。你这样一问，他更是三天三夜都说不完了。",
            ["ContentJP"] = "あれは<Default note=\"text:きすうは\">機枢派</>の誇りみたいな装置でね。\
その気になれば、タンさんは道ばたの犬にでさえ三日三晩説明し続けるよ……恐ろしいったらありゃしない。",
            ["DialogueId"] = 12044007,
            ["GUID"] = "1E26A1E6",
            ["NextDialogue"] = 12044008,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A1E6",
            },
        [12044008] = {
            ["Content"] = "哪有小苏说的这么夸张！",
            ["ContentJP"] = "おいおい、そんな大げさな。",
            ["DialogueId"] = 12044008,
            ["GUID"] = "1E26A210",
            ["NextDialogue"] = 12044009,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A210",
            },
        [12044009] = {
            ["Content"] = "咳咳，不过年轻人有求知欲是好事。唐叔今天就给你们浅上一课，讲讲这天罗拒风仪的来龙去脉。话得从我年轻学艺时说起——",
            ["ContentJP"] = "……まあ、好奇心があるのはいいことだ。今日はまずこの<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>の由来から話してやろう。\
あの頃、俺はまだ若造で、修行の旅に出ていた――",
            ["DialogueId"] = 12044009,
            ["GUID"] = "1E26A23A",
            ["NextDialogue"] = 12044010,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A23A",
            },
        [12044010] = {
            ["Content"] = "天罗拒风仪是机枢派为了切断大风九章的感应能力，众人合力潜心研究出的装置。其原理是把区域中的香完全滤净，同时反制一种欺骗信号。",
            ["ContentJP"] = "<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>は、大風九章の感知を断ち切るために作られた<Default note=\"text:きすうは\">機枢派</>の装置よ。空気中の<Default note=\"text:こう\">香</>を全部消しつつ、偽りの信号を発信するの。",
            ["DialogueId"] = 12044010,
            ["GUID"] = "1E26A264",
            ["NextDialogue"] = 12044011,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A264",
            },
        [12044011] = {
            ["Content"] = "大风九章失去了承载的介质，就失去了对这片区域的实际感知。而欺骗信号又能阻止龙神察觉到这片区域的空白。",
            ["ContentJP"] = "これがあれば、大風九章に場所を探知できなくなるし、龍神にも悟られない。",
            ["DialogueId"] = 12044011,
            ["GUID"] = "1E26A28E",
            ["NextDialogue"] = 12044012,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A28E",
            },
        [12044012] = {
            ["Content"] = "有了这个装置，我们飘零人终于不用频繁转移地点，可以在山外山扎根发展了。好了唐叔，原理我替你讲完了。",
            ["ContentJP"] = "だから私たち流れ者は拠点を転々とせず、腰を据えて暮らせるってわけ。――はい、説明終わり！",
            ["DialogueId"] = 12044012,
            ["GUID"] = "1E26A2B8",
            ["NextDialogue"] = 12044013,
            ["RelatedWikiId"] = {
                [1] = 403008,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A2B8",
            },
        [12044013] = {
            ["Content"] = "唉，小苏啊，唐叔生命中的乐趣都要被你剥夺了。",
            ["ContentJP"] = "……スーよ、お前、俺の楽しみを全部奪ってくれるなぁ。",
            ["DialogueId"] = 12044013,
            ["GUID"] = "1E26A2E2",
            ["NextDialogue"] = 12044014,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A2E2",
            },
        [12044014] = {
            ["Content"] = "不用这样说啦唐叔，人家只是怕你说的太累，帮你分担一下而已～",
            ["ContentJP"] = "まぁまぁ！タンさんが疲れないように気を利かせただけなんだから～",
            ["DialogueId"] = 12044014,
            ["GUID"] = "1E26A30C",
            ["NextDialogue"] = 12044015,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A30C",
            },
        [12044015] = {
            ["Content"] = "算了算了，你们年轻人做事就是这么风风火火。你们赶紧去调校天罗拒风仪吧，之后得空了再来找唐叔，给你们细细上一上课。",
            ["ContentJP"] = "はいはい、若いもんはせっかちでいかん。さあ、さっさと<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>儀の整備に行ってこい。また暇ができたら、ゆっくり話してやるからな。",
            ["DialogueId"] = 12044015,
            ["GUID"] = "1E26A336",
            ["NextDialogue"] = 12044016,
            ["SpeakNpcId"] = 240029,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A336",
            },
        [12044016] = {
            ["Content"] = "啊哈哈……有空一定。",
            ["ContentJP"] = "あ、はは……ぜひ。",
            ["DialogueId"] = 12044016,
            ["GUID"] = "1E26A360",
            ["NextDialogue"] = 12044017,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A360",
            },
        [12044017] = {
            ["Content"] = "那我们走啦，药你别忘了敷哟！",
            ["ContentJP"] = "じゃ、行こ！タンさん、忘れずに薬を塗るんだよ！",
            ["DialogueId"] = 12044017,
            ["GUID"] = "1E26A38A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120440/1E26A38A",
            },
        [12044101] = {
            ["Content"] = "好！这下就大功告成啦。",
            ["ContentJP"] = "これでよしっと！",
            ["DialogueId"] = 12044101,
            ["GUID"] = "1E26B152",
            ["NextDialogue"] = 12044102,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                [4] = 403008,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B152",
            },
        [12044102] = {
            ["Content"] = "小苏，原来你在这儿。你现在有空吗？有件事我有些担忧……",
            ["ContentJP"] = "スー、こんなところにいたの。ちょっと相談があるんだけど……",
            ["DialogueId"] = 12044102,
            ["GUID"] = "1E26B17C",
            ["NextDialogue"] = 12044103,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B17C",
            },
        [12044103] = {
            ["Content"] = "是阿晨小野那俩小子逃课的事吗？我刚刚在药田将他俩抓了个正着，叮嘱他们回去好好听课呢。",
            ["ContentJP"] = "シンとリクのおサボりのことでしょ？さっき薬草畑で捕まえたわ。ちゃんと授業に戻るよう言っといたから安心して。",
            ["DialogueId"] = 12044103,
            ["GUID"] = "1E26B1A6",
            ["NextDialogue"] = 12044104,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B1A6",
            },
        [12044104] = {
            ["Content"] = "呵呵……他们和我说了，这两人倒还是一如既往没心没肺。要只是这种小事就好了。",
            ["ContentJP"] = "ふふ……やっぱりね。あの二人は相変わらず呑気ね。でも、そのことじゃないの。",
            ["DialogueId"] = 12044104,
            ["GUID"] = "1E26B1D0",
            ["NextDialogue"] = 12044105,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B1D0",
            },
        [12044105] = {
            ["Content"] = "实不相瞒，我有些担心朴儿。他最近把自己关在山洞中，独来独往，也不与同龄人玩耍，只是没日没夜地扑在练武上。",
            ["ContentJP"] = "シュのことよ。最近洞窟にこもりっきりで剣の稽古をしてるの。",
            ["DialogueId"] = 12044105,
            ["GUID"] = "1E26B1FA",
            ["NextDialogue"] = 12044106,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B1FA",
            },
        [12044106] = {
            ["Content"] = "这样下去，且不说练武过度会伤筋动骨，心……也会垮。",
            ["ContentJP"] = "あのままじゃ身体だけでなく、心まで壊れちゃうわ。",
            ["DialogueId"] = 12044106,
            ["GUID"] = "1E26B224",
            ["NextDialogue"] = 12044107,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B224",
            },
        [12044107] = {
            ["Content"] = "他为什么要这么拼命？",
            ["ContentJP"] = "どうして、そこまで……？",
            ["DialogueId"] = 12044107,
            ["GUID"] = "1E26B24E",
            ["NextDialogue"] = 12044108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B24E",
            },
        [12044108] = {
            ["Content"] = "菡姐，这位是{nickname}，我新结识的朋友！{nickname}，这位是山外山中负责给大家讲学的菡姐，你们不要见外。",
            ["ContentJP"] = "カンさん、こちらは私の友だち、{nickname}よ。{nickname}、彼女は<Default note=\"text:さんがいさん\">山外山</>で教師をしてるカンさん。",
            ["DialogueId"] = 12044108,
            ["GUID"] = "1E26B278",
            ["NextDialogue"] = 12044109,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B278",
            },
        [12044109] = {
            ["Content"] = "原来您便是刻舟的那位救命恩人，幸会。",
            ["ContentJP"] = "ああ、カシュウの命を救ったっていう……お会いできてうれしいわ。",
            ["DialogueId"] = 12044109,
            ["GUID"] = "1E26B2A2",
            ["NextDialogue"] = 12044110,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B2A2",
            },
        [12044110] = {
            ["Content"] = "实不相瞒，山外山收留的尽是一些大风九章所不容之人。",
            ["ContentJP"] = "実はね、この<Default note=\"text:さんがいさん\">山外山</>にいるのは、皆、大風九章に居場所を奪われた者たちなの。",
            ["DialogueId"] = 12044110,
            ["GUID"] = "1E26B2CC",
            ["NextDialogue"] = 12044111,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B2CC",
            },
        [12044111] = {
            ["Content"] = "他们有些如刻舟，因自保或助人而触犯大风九章。有些因亲朋蒙冤，不得不投靠山外山，好比小苏。",
            ["ContentJP"] = "カシュウのように助け合って罪に問われた者もいれば、家族が濡れ衣を着せられ山外山に入るしかなかった者もいる。スーもそうよ。",
            ["DialogueId"] = 12044111,
            ["GUID"] = "1E26B2F6",
            ["NextDialogue"] = 12044112,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B2F6",
            },
        [12044112] = {
            ["Content"] = "朴儿也是后者，他的爹娘在他九岁时离世了。这些日子，朴儿总是念叨着要手刃白龙，为爹娘报仇，所以……",
            ["ContentJP"] = "シュも同じ。九歳の時に両親を失って以来、白龍を討つことに執着しているわ。だから……",
            ["DialogueId"] = 12044112,
            ["GUID"] = "1E26B320",
            ["NextDialogue"] = 12044113,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B320",
            },
        [12044113] = {
            ["Content"] = "他现在还在山洞中练武吗？",
            ["ContentJP"] = "今も洞窟で稽古を？",
            ["DialogueId"] = 12044113,
            ["GUID"] = "1E26B34A",
            ["NextDialogue"] = 12044114,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B34A",
            },
        [12044114] = {
            ["Content"] = "嗯。今天天还没亮我就见他一头扎进去，到现在还没出来过。",
            ["ContentJP"] = "ええ。夜明け前に入ったきり、一度も出てきていないわ。",
            ["DialogueId"] = 12044114,
            ["GUID"] = "1E26B374",
            ["NextDialogue"] = 12044115,
            ["SpeakNpcId"] = 240033,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B374",
            },
        [12044115] = {
            ["Content"] = "好，我和{nickname}去看看，要是之后有什么进展再告诉你。不用太担心了，这件事我们会妥善解决的。",
            ["ContentJP"] = "わかった。{nickname}と一緒に様子を見てくる。何かあればすぐ報せるから安心して。",
            ["DialogueId"] = 12044115,
            ["GUID"] = "1E26B39E",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120441/1E26B39E",
            },
        [12044201] = {
            ["Content"] = "呵——哈——",
            ["ContentJP"] = "はぁっ……はぁっ……！",
            ["DialogueId"] = 12044201,
            ["GUID"] = "1E26C1BA",
            ["NextDialogue"] = 12044202,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                [4] = 403008,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C1BA",
            },
        [12044202] = {
            ["Content"] = "呼……呼……",
            ["ContentJP"] = "はぁ……はぁ……",
            ["DialogueId"] = 12044202,
            ["GUID"] = "1E26C1E4",
            ["NextDialogue"] = 12044203,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C1E4",
            },
        [12044203] = {
            ["Content"] = "已经站不起来了吗……",
            ["ContentJP"] = "ここまでか……",
            ["DialogueId"] = 12044203,
            ["GUID"] = "1E26C20E",
            ["NextDialogue"] = 12044204,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C20E",
            },
        [12044204] = {
            ["Content"] = "要是连这点小事都办不到，还怎么祭奠阿爹阿娘的在天之灵？站起来继续啊，朱朴！",
            ["ContentJP"] = "くそっ！この程度でバテてどうする！こんなんじゃ父ちゃんと母ちゃんに顔向けできねぇ！",
            ["DialogueId"] = 12044204,
            ["GUID"] = "1E26C238",
            ["NextDialogue"] = 12044205,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C238",
            },
        [12044205] = {
            ["Content"] = "（鼓掌声）",
            ["ContentJP"] = "拍手",
            ["DialogueId"] = 12044205,
            ["GUID"] = "1E26C262",
            ["NextDialogue"] = 12044206,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C262",
            },
        [12044206] = {
            ["Content"] = "小小年纪能有如此决心，了不起。",
            ["ContentJP"] = "その歳ですごい根性ね。",
            ["DialogueId"] = 12044206,
            ["GUID"] = "1E26C28C",
            ["NextDialogue"] = 12044207,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C28C",
            },
        [12044207] = {
            ["Content"] = "……苏乙姐，是你。",
            ["ContentJP"] = "……スーねぇ。",
            ["DialogueId"] = 12044207,
            ["GUID"] = "1E26C2B6",
            ["NextDialogue"] = 12044208,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C2B6",
            },
        [12044208] = {
            ["Content"] = "你也是听了菡姐的话，想过来阻止我的吗？你走吧，你们无论说什么话，我都不会听的。",
            ["ContentJP"] = "どうせカンねぇに言われて、止めに来たんだろ？無駄だよ。何を言われても、俺はやめない。",
            ["DialogueId"] = 12044208,
            ["GUID"] = "1E26C2E0",
            ["NextDialogue"] = 12044209,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C2E0",
            },
        [12044209] = {
            ["Content"] = "别急——你不用擅自觉得我和他们是一伙的。",
            ["ContentJP"] = "そう決断を急がないで。",
            ["DialogueId"] = 12044209,
            ["GUID"] = "1E26C30A",
            ["NextDialogue"] = 12044210,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C30A",
            },
        [12044210] = {
            ["Content"] = "你不是一直不满大家不允许你加入外出巡逻的队伍里吗？我现在破格给你一个机会。",
            ["ContentJP"] = "ずっと巡回に出たかったのよね？特別に、チャンスを与えてあげる。",
            ["DialogueId"] = 12044210,
            ["GUID"] = "1E26C334",
            ["NextDialogue"] = 12044211,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C334",
            },
        [12044211] = {
            ["Content"] = "只要你能在这位{nickname}{性别：哥哥|姐姐}手下撑过十招，我就认可你能够独当一面了。怎么样？这个要求不过分吧。",
            ["ContentJP"] = "この{nickname}と腕試ししてみなさい。10回以上手を交えることができたら、一人前だと認めてあげる。悪くない話しでしょ？",
            ["DialogueId"] = 12044211,
            ["GUID"] = "1E26C35E",
            ["NextDialogue"] = 12044212,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C35E",
            },
        [12044212] = {
            ["Content"] = "……{nickname}，难道就是那位与太皓正面交过手的……！",
            ["ContentJP"] = "……！{nickname}って、太皓と戦ったあの！？",
            ["DialogueId"] = 12044212,
            ["GUID"] = "1E26C388",
            ["NextOptions"] = {
                [1] = 12044213,
                [2] = 12044214,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C388",
            },
        [12044213] = {
            ["Content"] = "刻舟该不会逢人就提我一嘴吧？",
            ["ContentJP"] = "カシュウ……誰彼かまわず話して……",
            ["DialogueId"] = 12044213,
            ["GUID"] = "1E26C3B2",
            ["NextDialogue"] = 12044215,
            },
        [12044214] = {
            ["Content"] = "怎么又要我出手了？",
            ["ContentJP"] = "なんで{性别:僕|私}が……",
            ["DialogueId"] = 12044214,
            ["GUID"] = "1E26C3DC",
            ["NextDialogue"] = 12044216,
            },
        [12044215] = {
            ["Content"] = "那小子就是嘴上没个把门的，遇到兴奋的事就恨不得马上拿个大喇叭昭告全天下。",
            ["ContentJP"] = "まったく、あの子は口が軽すぎるのよ！うれしいことがあると、すぐ大声で吹聴したがるんだから。",
            ["DialogueId"] = 12044215,
            ["GUID"] = "1E26C406",
            ["NextDialogue"] = 12044217,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C406",
            },
        [12044216] = {
            ["Content"] = "拜托啦，这个年纪的孩子容易有逆反心理。这时候我们说上一百句话都不如你这外人挥一次剑来得有用。",
            ["ContentJP"] = "お願い！この年頃の子は、こっちが何言っても反抗するのよ。外部の者に剣を振ってもらったほうが、よっぽど効き目があるわ。",
            ["DialogueId"] = 12044216,
            ["GUID"] = "1E26C430",
            ["NextDialogue"] = 12044217,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C430",
            },
        [12044217] = {
            ["Content"] = "我明白了，请您赐教。",
            ["ContentJP"] = "わかりました。では、お願いします。",
            ["DialogueId"] = 12044217,
            ["GUID"] = "1E26C45A",
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120442/1E26C45A",
            },
        [12044301] = {
            ["Content"] = "竟然……就这样输了……",
            ["ContentJP"] = "そ……そんな……",
            ["DialogueId"] = 12044301,
            ["GUID"] = "1E26D222",
            ["NextDialogue"] = 12044302,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                [4] = 403008,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D222",
            },
        [12044302] = {
            ["Content"] = "朱朴，你太操之过急了。在{nickname}手底下，你连三招都撑不了。",
            ["ContentJP"] = "シュ、焦りすぎよ。{nickname}相手で3回ももたなかったじゃない。",
            ["DialogueId"] = 12044302,
            ["GUID"] = "1E26D24C",
            ["NextDialogue"] = 12044303,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D24C",
            },
        [12044303] = {
            ["Content"] = "你现在还如此弱小。等你成长到能和白龙过招的水平，要多久？一个月？半年？一年？还是十年？这十年内，你便要日日如此度过吗？",
            ["ContentJP"] = "今のあんたは、まだ弱い。白龍と渡り合えるまで、どれくらいかかると思う？一ヶ月？半年？一年？それとも十年かしら？",
            ["DialogueId"] = 12044303,
            ["GUID"] = "1E26D276",
            ["NextDialogue"] = 12044304,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D276",
            },
        [12044304] = {
            ["Content"] = "太紧的弦会崩断。仇恨会蒙蔽你的双眼，影响你在战斗中的挥剑，让你无法再做出准确的判断。",
            ["ContentJP"] = "憎しみに囚われていては正しい判断はできない。一人前になる前に、自分を見失ってしまうわ。",
            ["DialogueId"] = 12044304,
            ["GUID"] = "1E26D2A0",
            ["NextDialogue"] = 12044305,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D2A0",
            },
        [12044305] = {
            ["Content"] = "给自己一些喘息的时间 ，答应我，好吗？",
            ["ContentJP"] = "だから……少し休みなさい、ね？",
            ["DialogueId"] = 12044305,
            ["GUID"] = "1E26D2CA",
            ["NextDialogue"] = 12044306,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D2CA",
            },
        [12044306] = {
            ["Content"] = "在你们面前，少年恍然松开了手中的剑，跪在地上失声痛哭了起来。",
            ["ContentJP"] = "目の前で、少年は剣を落とし、泣き崩れる。",
            ["DialogueId"] = 12044306,
            ["GUID"] = "1E26D2F4",
            ["NextDialogue"] = 12044307,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D2F4",
            },
        [12044307] = {
            ["Content"] = "那我该怎么办，告诉我啊！我该怎么办！！",
            ["ContentJP"] = "じゃあ……俺はどうすればいいんだ！教えてくれよ！",
            ["DialogueId"] = 12044307,
            ["GUID"] = "1E26D31E",
            ["NextDialogue"] = 12044308,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D31E",
            },
        [12044308] = {
            ["Content"] = "每次我看到小野、阿晨他们那种没心没肺的样子，我就打心底里怕——我怕自己像他们一样快乐，把至今为止的事情都忘得一干二净！",
            ["ContentJP"] = "リクやシンみたいに何も考えず笑って過ごしてたら、今までのことを全部忘れちまいそうで怖いんだ！",
            ["DialogueId"] = 12044308,
            ["GUID"] = "1E26D348",
            ["NextDialogue"] = 12044309,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D348",
            },
        [12044309] = {
            ["Content"] = "害得我们家破人亡的骗子还好端端地活在这世上，阿爹阿娘去讨说法，却被狴犴惩戒，就这么伤重不治走了。",
            ["ContentJP"] = "我らを騙して、一家離散にまで追い込みかけた悪人はのうのうと生きてるのに、正義を求む父ちゃんと母ちゃんは……<Default note=\"text:ビーアン\">狴犴</>に罰せられ、重傷を負って亡くなった。",
            ["DialogueId"] = 12044309,
            ["GUID"] = "1E26D372",
            ["NextDialogue"] = 12044310,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D372",
            },
        [12044310] = {
            ["Content"] = "而包庇坏人的大风九章、太皓，依然受到万人顶礼、万人膜拜！",
            ["ContentJP"] = "悪者を守る大風九章や太皓は今も崇められている……",
            ["DialogueId"] = 12044310,
            ["GUID"] = "1E26D39C",
            ["NextDialogue"] = 12044311,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D39C",
            },
        [12044311] = {
            ["Content"] = "大家受大风九章的愚弄，偏偏把坏的说成好的，青的说成白的。阿爹阿娘的清白，也就这样洗不清了。",
            ["ContentJP"] = "みんな大風九章に騙されてる。悪を神だと思い込んでるんだ……これじゃあ、父ちゃんたちの無念も晴らせない……！",
            ["DialogueId"] = 12044311,
            ["GUID"] = "1E26D3C6",
            ["NextDialogue"] = 12044312,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D3C6",
            },
        [12044312] = {
            ["Content"] = "我好害怕，苏乙姐，我怕我一觉醒来就忘了。我怕我这辈子都没有能力去报仇，我怕有一天我就像甘愿受大风九章庇护的人一样，度过庸庸碌碌的一生。",
            ["ContentJP"] = "スーねぇ、俺怖いんだ。普通の暮らしをして、もし憎しみが消えてしまったら……このまま何もできずに一生が終わってしまったら……",
            ["DialogueId"] = 12044312,
            ["GUID"] = "1E26D3F0",
            ["NextDialogue"] = 12044313,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D3F0",
            },
        }
  end },
  { MinKey = 12044313, MaxKey = 12045529, Loader = function()
      return {
        [12044313] = {
            ["Content"] = "到时候，我又该怎么和阿爹阿娘交代，怎么和曾经的自己交代……呜呜……告诉我，我该怎么办……",
            ["ContentJP"] = "俺は父ちゃんたちに顔向けできなくなってしまう……うっ……俺はどうすればいいんだ……",
            ["DialogueId"] = 12044313,
            ["GUID"] = "1E26D41A",
            ["NextDialogue"] = 12044314,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D41A",
            },
        [12044314] = {
            ["Content"] = "别哭，朱朴，别哭了……",
            ["ContentJP"] = "シュ、泣かないで。",
            ["DialogueId"] = 12044314,
            ["GUID"] = "1E26D444",
            ["NextDialogue"] = 12044315,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D444",
            },
        [12044315] = {
            ["Content"] = "少年恸哭许久，终于在苏乙的安抚下渐渐平复了情绪。",
            ["ContentJP"] = "少年は長い間泣き続けた。そして嗚咽の果てに、ようやく落ち着いた。",
            ["DialogueId"] = 12044315,
            ["GUID"] = "1E26D46E",
            ["NextDialogue"] = 12044316,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D46E",
            },
        [12044316] = {
            ["Content"] = "朱朴，我懂你的感受……姑姑死之后的一段时间，我也和你有一样的想法。这里每个人都经历过这样夜不能寐的时刻。",
            ["ContentJP"] = "気持ちは痛いほどわかるわ。私だって叔母を失った。ここにいる者は皆、眠れない夜を何度も過ごしてきた。",
            ["DialogueId"] = 12044316,
            ["GUID"] = "1E26D498",
            ["NextDialogue"] = 12044317,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D498",
            },
        [12044317] = {
            ["Content"] = "相信我，这里不会有人忘记。飘零人的存在就是为了颠覆这些不公。",
            ["ContentJP"] = "誰ひとり、それを忘れた者はいない。その不義を正すのが、私たち流れ者よ。",
            ["DialogueId"] = 12044317,
            ["GUID"] = "1E26D4C2",
            ["NextDialogue"] = 12044318,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D4C2",
            },
        [12044318] = {
            ["Content"] = "但是不忘记并不意味着仇恨就是飘零人的全部，更不意味着我们就丧失了快乐的资格。毕竟，大家离开大风九章就是为了更好的生活，不是吗？",
            ["ContentJP"] = "でもね、「忘れないこと」と「憎しみに囚われること」は別物よ。\
大風九章を脱出するのは、もっといい生き方を手に入れるため、そうでしょう？",
            ["DialogueId"] = 12044318,
            ["GUID"] = "1E26D4EC",
            ["NextDialogue"] = 12044319,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D4EC",
            },
        [12044319] = {
            ["Content"] = "答应我，照顾好自己的身体，好吗？健健康康地走下去，才能看到报仇雪恨的那天呀。",
            ["ContentJP"] = "そのためにも、まずは自分を大切にしないと。元気でいなきゃ、復讐の日なんて来ないんだから。",
            ["DialogueId"] = 12044319,
            ["GUID"] = "1E26D516",
            ["NextDialogue"] = 12044320,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D516",
            },
        [12044320] = {
            ["Content"] = "呜……呜……好的。我不该对菡姐说那些伤人的话，我之后会再找时间和她道歉……",
            ["ContentJP"] = "……う、うん……わかった。カンねぇにも……ちゃんと謝る……",
            ["DialogueId"] = 12044320,
            ["GUID"] = "1E26D540",
            ["NextDialogue"] = 12044321,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D540",
            },
        [12044321] = {
            ["Content"] = "放心吧，菡姐只希望你们每一个都平平安安长大，她不会把你的话记在心上的。",
            ["ContentJP"] = "心配しないで。あんたが無事でさえいてくれれば、あの人も気にしないわ。",
            ["DialogueId"] = 12044321,
            ["GUID"] = "1E26D56A",
            ["NextDialogue"] = 12044322,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D56A",
            },
        [12044322] = {
            ["Content"] = "苏乙姐，还有这位远道而来的{性别：大哥哥|大姐姐}，真的谢谢你们……",
            ["ContentJP"] = "スーねぇ……それから{性别:お兄さん|お姉さん}、本当にありがとう……",
            ["DialogueId"] = 12044322,
            ["GUID"] = "1E26D594",
            ["NextDialogue"] = 12044323,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D594",
            },
        [12044323] = {
            ["Content"] = "你、你们不用再管我了，我想一个人再静一静……",
            ["ContentJP"] = "少しだけ、ひとりにしてほしいな……",
            ["DialogueId"] = 12044323,
            ["GUID"] = "1E26D5BE",
            ["NextDialogue"] = 12044324,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D5BE",
            },
        [12044324] = {
            ["Content"] = "我们走吧，{nickname}，给他留一些独处的时间。",
            ["ContentJP"] = "行こ、{nickname}。この子に少しだけ時間をあげましょう。",
            ["DialogueId"] = 12044324,
            ["GUID"] = "1E26D5E8",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120443/1E26D5E8",
            },
        [12044401] = {
            ["Content"] = "这些狴犴，打退一波又来一波，简直没完没了……",
            ["ContentJP"] = "くそっ……次から次へと……キリがねぇ！",
            ["DialogueId"] = 12044401,
            ["GUID"] = "1E26E28A",
            ["NextDialogue"] = 12044402,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                [3] = 408018,
                [4] = 103001,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E28A",
            },
        [12044402] = {
            ["Content"] = "这么多年来，山外山的坐标一直隐藏得很好。今日怎么会突然暴露？！小苏，你找到缘由了吗？",
            ["ContentJP"] = "ここ数年ずっと問題なかったのに、なぜ今日に限って……スー、原因は突き止めたのか？",
            ["DialogueId"] = 12044402,
            ["GUID"] = "1E26E2B4",
            ["NextDialogue"] = 12044403,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E2B4",
            },
        [12044403] = {
            ["Content"] = "我、我不知道……天罗拒风仪我今天还调校过，是完好的……",
            ["ContentJP"] = "わ、私にもわからない……<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>は今日整備したばかりなのに……",
            ["DialogueId"] = 12044403,
            ["GUID"] = "1E26E2DE",
            ["NextDialogue"] = 12044404,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E2DE",
            },
        [12044404] = {
            ["Content"] = "但必须防守好天罗拒风仪，要是它被破坏了，山外山的自保手段就要彻底失效了……！",
            ["ContentJP"] = "何はともあれ、<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>を守り抜かないと！\
これが壊されたら、<Default note=\"text:さんがいさん\">山外山</>は丸裸同然になっちゃうわ！",
            ["DialogueId"] = 12044404,
            ["GUID"] = "1E26E308",
            ["NextDialogue"] = 12044424,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E308",
            },
        [12044405] = {
            ["Content"] = "你怎么来了？！",
            ["ContentJP"] = "なぜお前がここに！？",
            ["DialogueId"] = 12044405,
            ["GUID"] = "1E26E332",
            ["NextDialogue"] = 12044406,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E332",
            },
        [12044406] = {
            ["Content"] = "……叛徒！！",
            ["ContentJP"] = "この……裏切り者！！",
            ["DialogueId"] = 12044406,
            ["GUID"] = "1E26E35C",
            ["NextDialogue"] = 12044407,
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E35C",
            },
        [12044407] = {
            ["Content"] = "师兄，这起袭击是你所策划的吗？",
            ["ContentJP"] = "ユーミン、この奇襲はお前の仕業か？",
            ["DialogueId"] = 12044407,
            ["GUID"] = "1E26E386",
            ["NextDialogue"] = 12044408,
            ["RelatedWikiId"] = {
                [1] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E386",
            },
        [12044408] = {
            ["Content"] = "……我只是奉命而来。",
            ["ContentJP"] = "……命令を受けて来ただけだ。",
            ["DialogueId"] = 12044408,
            ["GUID"] = "1E26E3B0",
            ["NextDialogue"] = 12044409,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E3B0",
            },
        [12044409] = {
            ["Content"] = "好你个煜明！出卖基地位置，向你的新主子求荣是吧？",
            ["ContentJP"] = "ユーミン貴様！さては、新しい主に媚びるために、基地の位置をバラしたな！！",
            ["DialogueId"] = 12044409,
            ["GUID"] = "1E26E3DA",
            ["NextDialogue"] = 12044430,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E3DA",
            },
        [12044410] = {
            ["Content"] = "我已经回答过了，我是奉大风九章的旨意，前来征讨飘零人。此外的事，一概不知。",
            ["ContentJP"] = "何度も言うが、俺は大風九章の命を受け、流れ者の討伐に来ただけだ。他のことは知らん。",
            ["DialogueId"] = 12044410,
            ["GUID"] = "1E26E404",
            ["NextDialogue"] = 12044411,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E404",
            },
        [12044411] = {
            ["Content"] = "更何况，我皈依大风九章之后，你们不是已经把旧时入口尽数更换了吗？",
            ["ContentJP"] = "それに……俺が大風九章に帰依した後、あんたたちは入口の位置をすべて変えただろう？",
            ["DialogueId"] = 12044411,
            ["GUID"] = "1E26E42E",
            ["NextDialogue"] = 12044412,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E42E",
            },
        [12044412] = {
            ["Content"] = "……不用再说了。师兄，我信你。",
            ["ContentJP"] = "……もういい。お前を信じるよ。",
            ["DialogueId"] = 12044412,
            ["GUID"] = "1E26E458",
            ["NextDialogue"] = 12044413,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E458",
            },
        [12044413] = {
            ["Content"] = "现在站在这里的，都是你曾经的同伴、师长、后辈。我们是否有罪，我相信你比任何人都更清楚。",
            ["ContentJP"] = "ここに立っているのは、お前がかつて共に戦った仲間であり、師であり、後輩たちだ。\
俺たちが罪人かどうかは……お前が一番知っているはずだろう。",
            ["DialogueId"] = 12044413,
            ["GUID"] = "1E26E482",
            ["NextDialogue"] = 12044414,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E482",
            },
        [12044414] = {
            ["Content"] = "师兄，我只问你一次。你确定要对我们挥刀吗？",
            ["ContentJP"] = "一度だけ聞こう。ユーミン、本当に俺たちに刃を向けるのか？",
            ["DialogueId"] = 12044414,
            ["GUID"] = "1E26E4AC",
            ["NextDialogue"] = 12044415,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E4AC",
            },
        [12044415] = {
            ["Content"] = "我……",
            ["ContentJP"] = "俺は……",
            ["DialogueId"] = 12044415,
            ["GUID"] = "1E26E4D6",
            ["NextDialogue"] = 12044416,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E4D6",
            },
        [12044416] = {
            ["Content"] = "我不要听大风九章的判断。师兄，我要听“你”出自本心的判断。",
            ["ContentJP"] = "大風九章の裁きなどどうでもいい。俺が聞きたいのは……「お前」の声だ。",
            ["DialogueId"] = 12044416,
            ["GUID"] = "1E26E500",
            ["NextDialogue"] = 12044417,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E500",
            },
        [12044417] = {
            ["Content"] = "飘零人虽屡触天律，但并未犯下大过，也不曾主动戕害无辜。目前的刑罚……重了。",
            ["ContentJP"] = "お前たちは律を破った。だが、大罪を犯したわけではない。今回の刑は、確かに重すぎる。",
            ["DialogueId"] = 12044417,
            ["GUID"] = "1E26E52A",
            ["NextDialogue"] = 12044425,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E52A",
            },
        [12044418] = {
            ["Content"] = "既然如此，回来吧，师兄！",
            ["ContentJP"] = "だったら、戻って来いよ！",
            ["DialogueId"] = 12044418,
            ["GUID"] = "1E26E554",
            ["NextDialogue"] = 12044419,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E554",
            },
        [12044419] = {
            ["Content"] = "当初<H>那件事</>只是一时意外。若是你沉溺过往，终生被大风九章束缚住了，不夏一定也不想看到你现在这副颓唐模样的！",
            ["ContentJP"] = "<H>あの件</>はただの事故だ！過去に囚われて大風九章に縋りつくな！フウカだって、きっとこうなることは望んでいない！",
            ["DialogueId"] = 12044419,
            ["GUID"] = "1E26E57E",
            ["NextDialogue"] = 12044420,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E57E",
            },
        [12044420] = {
            ["Content"] = "……那件事？你竟还敢提那件事。",
            ["ContentJP"] = "……よくも、そんなこと口にできたな。",
            ["DialogueId"] = 12044420,
            ["GUID"] = "1E26E5A8",
            ["NextDialogue"] = 12044421,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E5A8",
            },
        [12044421] = {
            ["Content"] = "师父、师妹的在天之灵尚未安奠息，一句轻飘飘的意外，难道就能让他们活过来吗？",
            ["ContentJP"] = "師匠やフウカたちが死んでから……まだそんなに経ってない。事故で片付けて……彼らは生き返るのか？",
            ["DialogueId"] = 12044421,
            ["GUID"] = "1E26E5D2",
            ["NextDialogue"] = 12044426,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E5D2",
            },
        [12044422] = {
            ["Content"] = "刻舟，当初我叛出飘零人时，就与你提过：从此世上再无煜明，我只是一介无名无姓的应天尉罢了。",
            ["ContentJP"] = "カシュウ、<Default note=\"text:さんがいさん\">山外山</>を捨てた時に言ったはずだ。「ユーミン」は死んだ。俺は<Default note=\"text:おうてんい\">応天尉</>だ。",
            ["DialogueId"] = 12044422,
            ["GUID"] = "1E26E5FC",
            ["NextDialogue"] = 12044427,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E5FC",
            },
        [12044423] = {
            ["Content"] = "拔出你们的剑吧，我不对无刃之人出手。",
            ["ContentJP"] = "剣を抜け。武器を構えぬ者に、俺は刃を振るわん。",
            ["DialogueId"] = 12044423,
            ["GUID"] = "1E26E626",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120444/1E26E626",
            },
        [12044424] = {
            ["Content"] = "......",
            ["ContentJP"] = "……なんと……",
            ["DialogueId"] = 12044424,
            ["GUID"] = "12044424.0",
            ["NextDialogue"] = 12044405,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120418/1E2537FA",
            },
        [12044425] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044425,
            ["GUID"] = "12044425.0",
            ["NextDialogue"] = 12044418,
            },
        [12044426] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044426,
            ["GUID"] = "12044426.0",
            ["NextDialogue"] = 12044422,
            },
        [12044427] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044427,
            ["GUID"] = "12044427.0",
            ["NextDialogue"] = 12044428,
            },
        [12044428] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044428,
            ["GUID"] = "12044428.0",
            ["NextDialogue"] = 12044429,
            },
        [12044429] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044429,
            ["GUID"] = "12044429.0",
            ["NextDialogue"] = 12044423,
            },
        [12044430] = {
            ["Content"] = "......",
            ["DialogueId"] = 12044430,
            ["GUID"] = "12044430.0",
            ["NextDialogue"] = 12044410,
            },
        [12044501] = {
            ["Content"] = "抱歉，突然把你拽来了这里。",
            ["ContentJP"] = "ごめんね、急に連れてきちゃって。",
            ["DialogueId"] = 12044501,
            ["FacialId"] = {
                [1] = "240026:Serious",
                },
            ["GUID"] = "1E26F2F2",
            ["NextDialogue"] = 12044502,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F2F2",
            },
        [12044502] = {
            ["Content"] = "根据我的计算……继续抵抗下去，胜算不足一成。",
            ["ContentJP"] = "私の計算じゃ……このまま抵抗を続けても、勝てる可能性は一割もない。",
            ["DialogueId"] = 12044502,
            ["GUID"] = "1E26F31C",
            ["NextDialogue"] = 12044503,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F31C",
            },
        [12044503] = {
            ["Content"] = "对面是守卫执律阁和大风九章中枢的钧天铁卫，实力远非普通应天尉可比，而且大风九章会为他们提供源源不断的支持。",
            ["ContentJP"] = "向こうは、<Default note=\"text:しつりつかく\">執律閣</>と大風九章の中枢を守る天衡の鉄衛。\
普通の<Default note=\"text:おうてんい\">応天尉</>なんかとは比べものにならない。しかも、大風九章からは絶え間なく援軍が送られてくる……",
            ["DialogueId"] = 12044503,
            ["GUID"] = "1E26F346",
            ["NextDialogue"] = 12044504,
            ["RelatedWikiId"] = {
                [1] = 405016,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F346",
            },
        [12044504] = {
            ["Content"] = "但飘零人都是血肉之躯，受了伤需要时间恢复……这样消耗下去，山外山很快就会支持不住的。",
            ["ContentJP"] = "でも、私たちは血の通った人間。傷を負えば回復に時間がかかる。こんな消耗戦を続けたら……<Default note=\"text:さんがいさん\">山外山</>はすぐに持たなくなる。",
            ["DialogueId"] = 12044504,
            ["GUID"] = "1E26F370",
            ["NextDialogue"] = 12044505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F370",
            },
        [12044505] = {
            ["Content"] = "我不想只能看着他们交手……我要兵行险着，赌一把。",
            ["ContentJP"] = "だから……私は賭けるしかないの。危ない橋を渡ってでもね。",
            ["DialogueId"] = 12044505,
            ["FinalDialogueId"] = 12044514,
            ["GUID"] = "1E26F39A",
            ["NextOptions"] = {
                [1] = 12044506,
                [2] = 12044507,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F39A",
            },
        [12044506] = {
            ["Content"] = "这里是什么地方？",
            ["ContentJP"] = "ここは？",
            ["DialogueId"] = 12044506,
            ["GUID"] = "1E26F3C4",
            ["NextDialogue"] = 12044508,
            },
        [12044507] = {
            ["Content"] = "你的办法是什么？",
            ["ContentJP"] = "作戦は？",
            ["DialogueId"] = 12044507,
            ["GUID"] = "1E26F3EE",
            ["NextDialogue"] = 12044511,
            },
        [12044508] = {
            ["Content"] = "这里是偃隐宫，机枢派先人铸造的地宫。",
            ["ContentJP"] = "ここは<Default note=\"text:えんいんきゅう\">偃隠宮</>。<Default note=\"text:きすうは\">機枢派</>の先人たちが築いた地下宮殿よ。",
            ["DialogueId"] = 12044508,
            ["GUID"] = "1E26F418",
            ["NextDialogue"] = 12044509,
            ["RelatedWikiId"] = {
                [1] = 408019,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F418",
            },
        [12044509] = {
            ["Content"] = "上古鼎盛时期的机枢派能人辈出。那时最厉害的机傀大如鲲鹏，行于凌霄之上，足以遮天蔽日！可惜，那些伟大的造物，都在黍离之战后被毁之一炬了。",
            ["ContentJP"] = "昔、<Default note=\"text:きすうは\">機枢派</>が最盛だった頃――空を覆うほど巨大なからくりを生み出したって言われてる。\
その栄光も<Default note=\"text:しょりのらん\">黍離の乱</>で燃え尽きたけどね。",
            ["DialogueId"] = 12044509,
            ["GUID"] = "1E26F442",
            ["NextDialogue"] = 12044510,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F442",
            },
        [12044510] = {
            ["Content"] = "这处地宫也是那时留下的遗产。我们飘零人正是为了破解它的奥秘，才把新基地建在这处悬崖峭壁之中。",
            ["ContentJP"] = "この宮殿は、その時代の遺産として残されたものよ。だからこそ、私たちはここを拠点にして秘密を解こうとした。",
            ["DialogueId"] = 12044510,
            ["GUID"] = "1E26F46C",
            ["NextDialogue"] = 12044505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F46C",
            },
        [12044511] = {
            ["Content"] = "传闻，在这偃隐宫的深处，机枢派的先人留下了某样足以扭转局势的宝物。",
            ["ContentJP"] = "伝説によれば、この<Default note=\"text:えんいんきゅう\">偃隠宮</>の奥に……形勢をひっくり返すほどの宝が眠ってるの。",
            ["DialogueId"] = 12044511,
            ["GUID"] = "1E26F496",
            ["NextDialogue"] = 12044512,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F496",
            },
        [12044512] = {
            ["Content"] = "只是这么多年来，没有人能够成功破解防御机制，抵达终点。我之前尝试了几次，都以失败告终。",
            ["ContentJP"] = "ただし、誰も防御機構を突破できたことはないわ。私も何度か挑戦したけど、全部失敗に終わった。",
            ["DialogueId"] = 12044512,
            ["GUID"] = "1E26F4C0",
            ["NextDialogue"] = 12044513,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F4C0",
            },
        [12044513] = {
            ["Content"] = "但现在有了你的帮助，我想再尝试一把……万一这次就成功了呢！",
            ["ContentJP"] = "でも今は、あんたがいる。もしかしたら、今度こそ辿り着けるかもしれない！",
            ["DialogueId"] = 12044513,
            ["GUID"] = "1E26F4EA",
            ["NextDialogue"] = 12044505,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F4EA",
            },
        [12044514] = {
            ["Content"] = "我明白了。",
            ["ContentJP"] = "わかった。",
            ["DialogueId"] = 12044514,
            ["GUID"] = "1E26F514",
            ["NextDialogue"] = 12044515,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F514",
            },
        [12044515] = {
            ["Content"] = "大家还在外面苦苦抵抗，时间紧迫，我们赶紧出发吧！",
            ["ContentJP"] = "みんなが外で必死に戦ってる。時間がないわ、すぐに行きましょう！",
            ["DialogueId"] = 12044515,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E26F53E",
            ["NextDialogue"] = 12044516,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F53E",
            },
        [12044516] = {
            ["Content"] = "如果最终失败了，我只是说如果……那我们还来得及出去，重新加入他们的战线。",
            ["ContentJP"] = "……もし、今回も失敗したら――その時は外に戻って、一緒に戦うまでよ。",
            ["DialogueId"] = 12044516,
            ["GUID"] = "1E26F568",
            ["NextDialogue"] = 12044517,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F568",
            },
        [12044517] = {
            ["Content"] = "这种时候就别说丧气话啦。魔王大人和小仆从搭档至今，就还没有破解不了的迷宫！放心，包在我们身上了！",
            ["ContentJP"] = "もう！こんな時に縁起でもないこと言わないの！この魔王様と下僕さえいれば、解けない迷宮なんてないって！任せなさい！",
            ["DialogueId"] = 12044517,
            ["GUID"] = "1E26F592",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120445/1E26F592",
            },
        [12044601] = {
            ["Content"] = "这……我曾在古籍中读过它的作用！",
            ["ContentJP"] = "これ……古書で読んだことがあるわ！",
            ["DialogueId"] = 12044601,
            ["GUID"] = "1E27035A",
            ["NextDialogue"] = 12044602,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120446/1E27035A",
            },
        [12044602] = {
            ["Content"] = "它叫做牵机方枢·却邪。它射出的光束能激活别的机枢派造物，使其依照规则而变。",
            ["ContentJP"] = "<Default note=\"text:きこうせいぎょばん・じゃばらい\">機巧制御盤・邪払</>と呼ばれてるの。放ったビームでほかの<Default note=\"text:きすうは\">機枢派</>の造物をアクティブでき、一定の規則に従って変換させるって。",
            ["DialogueId"] = 12044602,
            ["GUID"] = "1E270384",
            ["NextDialogue"] = 12044603,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120446/1E270384",
            },
        [12044603] = {
            ["Content"] = "好耶，是大宝贝！小仆从，我们赶紧试试它的效果吧！",
            ["ContentJP"] = "やったー！お宝ゲット！さっそく使ってみよ！",
            ["DialogueId"] = 12044603,
            ["GUID"] = "1E2703AE",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120446/1E2703AE",
            },
        [12044701] = {
            ["Content"] = "\"吾平生碌碌，壮志不酬。追忆往昔，唯留憾恨。怀一密辛，关乎天下鼎革，恐言发而祸至，又不忍其泯于尘埃。遂藏之重楼，望后来者令其复启于天日。\
今汝既见此碑，必已通吾所设机枢之试。继之，<H>使塔中巨枢复位，玄机自现</>。吾毕生心血所铸神兵，亦当奉上。望汝持此神兵，匡时济世，勿蹈吾之覆辙。\"",
            ["ContentJP"] = "我が人生、志を果たせず、空しく歳月を重ねたり。想いは今なお胸にあり、この秘められし真を世に明かすこと叶わず。\
ただ滅びを恐れ、それを語ることもできぬまま、ここに封ず。もしこの碑を見る者あらば、汝はすでに我が試練を越えし者なり。\
よって命ず――<H>塔の巨枢を復位せよ。さすれば真なる兵器が姿を現すであろう。</>汝、この神兵を手に取り、時を正せ。二度と我と同じ過ちを繰り返すなかれ……",
            ["DialogueId"] = 12044701,
            ["GUID"] = "1E2713C2",
            ["NextDialogue"] = 12044703,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E2713C2",
            },
        [12044703] = {
            ["Content"] = "唔，抛开那些很难懂的部分不管……本魔王敏锐地察觉到了神兵的存在！",
            ["ContentJP"] = "うーん、難しいとこは置いといて……この中には物凄い武器があるよ！魔王センサーが反応してるもん！",
            ["DialogueId"] = 12044703,
            ["GUID"] = "1E271416",
            ["NextDialogue"] = 12044704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E271416",
            },
        [12044704] = {
            ["Content"] = "太好了，这说明我们来对地方了。",
            ["ContentJP"] = "よかった。場所は間違ってないみたい。",
            ["DialogueId"] = 12044704,
            ["GUID"] = "1E271440",
            ["NextDialogue"] = 12044705,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E271440",
            },
        [12044705] = {
            ["Content"] = "嗯，接下来只要<H>复原高塔的中轴</>，就能触及最后的答案了。",
            ["ContentJP"] = "うん。あとは――<H>塔の中枢を元に戻せば</>、全てが明らかになる。",
            ["DialogueId"] = 12044705,
            ["GUID"] = "1E27146A",
            ["NextDialogue"] = 12044706,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E27146A",
            },
        [12044706] = {
            ["Content"] = "走吧。大家还在外面和应天尉奋战，我们也要加快脚步！",
            ["ContentJP"] = "行こう！外ではまだ、みんなが戦っている。私たちも急がなきゃ！",
            ["DialogueId"] = 12044706,
            ["GUID"] = "1E271494",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120447/1E271494",
            },
        [12044801] = {
            ["Content"] = "真是的，非要设置这么多重考验，还得是我和小仆从。要是一般人来，早就被拦在外面了。",
            ["ContentJP"] = "まったく、試練の多さが伝説級だね！ここまで来られるの、スノウたちぐらいじゃない？",
            ["DialogueId"] = 12044801,
            ["GUID"] = "1E27242A",
            ["NextDialogue"] = 12044802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27242A",
            },
        [12044802] = {
            ["Content"] = "千辛万苦来到这儿，也该有点传说中的宝藏了吧？最好不要让白魔王大人失望！",
            ["ContentJP"] = "これだけ苦労したんだから、きっととんでもないお宝があるんだよね？",
            ["DialogueId"] = 12044802,
            ["GUID"] = "1E272454",
            ["NextDialogue"] = 12044803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272454",
            },
        [12044803] = {
            ["ContentJP"] = "これは……また石碑か。",
            ["DialogueId"] = 12044803,
            ["GUID"] = "1E27247E",
            ["NextDialogue"] = 12044804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27247E",
            },
        [12044804] = {
            ["Content"] = "\"幸哉！汝既历劫至此，终抵此境。吾积年幽怀，亦可昭彰于天日矣。",
            ["ContentJP"] = "よくぞ辿り着いた。我が思いも、ようやく世に示される時が来た。\
『黍離の乱』では、機枢と懸衡、両派が多くの犠牲を払った。\
かかる惨禍は、華胥の建国以来かつて無し。天地さえ涙し、山川までもが喪に服した。\
この一戦を機に、大風九章の在り方も大きく変わったのだ。\
\
戦乱の火種は、機枢側にありと世間には語られておる。\
然れども合戦のさなか、深手を負った機枢の大将は我に真実を託した。\
あの日は霧深く、偃甲の暴走が誤解を呼んだだけ――\
一方が先に手を出したと勘違いした双方は、引くに引けず全面衝突に至った。\
もはや誰にも止められず、惨事と相成ったのだ。\
\
されど、この真実を語ったところで、誰が信ずるか。\
二派の間には深き確執あり。語れば命を落とすのみ……。\
ゆえに我は沈黙を貫き、真実をこの地に封じた。\
\
この半分の均天玉律は、機枢に伝わる証なり。\
すでにその力は尽きたといえども、懸衡に奪われぬよう、ここに封じ置いた。\
\
また、我が生涯を賭して鍛え上げた<H>神機銃</>は、偃隠宮の外に眠らせてある。\
この文を見し者よ、石碑の前にある機巧の鍵を用いて、それを然るべき者の手に託してほしい。\
\
我らの果たせざりし願い――\
後に続く者よ、世に和をもたらし、再び太古の如き友好を取り戻してくれ。心より祈る。",
            ["DialogueId"] = 12044804,
            ["DialoguePanelType"] = "{type:showtext;topic:READ_NAME_2000117;content:READ_TEXT_2000049}",
            ["GUID"] = "1E2724A8",
            ["NextDialogue"] = 12044813,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2724A8",
            },
        [12044805] = {
            ["Content"] = "黍离之役，机枢与悬衡两派皆死伤无算。自华胥开国以来，未有此等大劫难，天地为之泣血。山川缟素，桃李含悲，大风九章亦由此易弦更张，为之一肃。",
            ["DialogueId"] = 12044805,
            ["GUID"] = "1E2724D2",
            ["NextDialogue"] = 12044806,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2724D2",
            },
        [12044806] = {
            ["Content"] = "至于此难由何而起，世皆谓我机枢启衅，罪有应得。",
            ["DialogueId"] = 12044806,
            ["GUID"] = "1E2724FC",
            ["NextDialogue"] = 12044807,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2724FC",
            },
        [12044807] = {
            ["Content"] = "然此乃后见之言，非是也。",
            ["DialogueId"] = 12044807,
            ["GUID"] = "1E272526",
            ["NextDialogue"] = 12044808,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272526",
            },
        [12044808] = {
            ["Content"] = "犹记两派乱战，机枢一派领兵之主伤重将死，气息尚存之际传密讯于吾，曰：机枢一派从未妄开兵燹！皆因是日晦，雾如笼纱，恰一偃甲偶失制御，两派人马皆惊，以为宿怨激发，遂相互以白刃相见。方其时，两派俱恐为对方所灭，不敢不用其全力抗敌，无人可制，终有此劫。",
            ["DialogueId"] = 12044808,
            ["GUID"] = "1E272550",
            ["NextDialogue"] = 12044809,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272550",
            },
        [12044809] = {
            ["Content"] = "然此间曲折，纵说与世人听之，孰可采信？机枢、悬衡二派，嫌隙已深，万难冰释。言出非但不能明志，徒惹杀身之祸。是以吾缄默不语，隐此秘辛，以俟来者。",
            ["DialogueId"] = 12044809,
            ["GUID"] = "1E27257A",
            ["NextDialogue"] = 12044810,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27257A",
            },
        [12044810] = {
            ["Content"] = "此半壁均天玉律，本为机枢信物。余知其功用已尽，又不忍见没于悬衡之手，故藏于兹。",
            ["DialogueId"] = 12044810,
            ["GUID"] = "1E2725A4",
            ["NextDialogue"] = 12044811,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2725A4",
            },
        [12044811] = {
            ["Content"] = "吾平生沥血所铸之<H>神机铳</>，长眠于偃隐宫外。得见此文者，可取碑前偃钥善用之。",
            ["DialogueId"] = 12044811,
            ["GUID"] = "1E2725CE",
            ["NextDialogue"] = 12044812,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2725CE",
            },
        [12044812] = {
            ["Content"] = "吾辈避世抱憾，难见二派弥合，唯愿后人承此遗志，修世人之罅隙，复上古之敦睦！切望！\"",
            ["DialogueId"] = 12044812,
            ["GUID"] = "1E2725F8",
            ["NextDialogue"] = 12044813,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2725F8",
            },
        [12044813] = {
            ["Content"] = "咦，小仆从，石碑前的这半块东西，和之前白龙受伤逃离时掉落的那玩意儿，好像刚刚好可以拼在一起耶！",
            ["ContentJP"] = "あれ、この石碑の前のやつ……白龍が逃げた時に落としたやつとぴったりくっつきそうじゃない！？",
            ["DialogueId"] = 12044813,
            ["GUID"] = "1E272622",
            ["NextDialogue"] = 12044814,
            ["RelatedWikiId"] = {
                [1] = 401003,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272622",
            },
        [12044814] = {
            ["Content"] = "神机铳……难道说是……",
            ["ContentJP"] = "神機銃……まさか、これは……！",
            ["DialogueId"] = 12044814,
            ["GUID"] = "1E27264C",
            ["NextDialogue"] = 12044815,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27264C",
            },
        [12044815] = {
            ["Content"] = "苏乙，你找到你想要的东西了吗？",
            ["ContentJP"] = "スーイー、探してたのってこれ？",
            ["DialogueId"] = 12044815,
            ["GUID"] = "1E272676",
            ["NextDialogue"] = 12044816,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E272676",
            },
        [12044816] = {
            ["Content"] = "没错，这一定就是致胜的奇招……太好了，{nickname}，果然有了你的帮助，我们就一定能够做到的！",
            ["ContentJP"] = "うん、間違いない……これこそ、勝利の切り札だよ！ありがとう、{nickname}！あんたがいてくれたおかげだよ！",
            ["DialogueId"] = 12044816,
            ["GUID"] = "1E2726A0",
            ["NextOptions"] = {
                [1] = 12044817,
                [2] = 12044818,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E2726A0",
            },
        [12044817] = {
            ["Content"] = "还等什么？",
            ["ContentJP"] = "じゃあ行こう！",
            ["DialogueId"] = 12044817,
            ["GUID"] = "1E2726CA",
            ["NextDialogue"] = 12044819,
            },
        [12044818] = {
            ["Content"] = "我们走，去终结外面的战斗！",
            ["ContentJP"] = "戦いを終わらせよう！",
            ["DialogueId"] = 12044818,
            ["GUID"] = "1E2726F4",
            ["NextDialogue"] = 12044819,
            },
        [12044819] = {
            ["Content"] = "哼哼，辛苦了这么久，白魔王大人也应该有一个潇洒帅气的亮相啦！好好记住我们的英姿吧！",
            ["ContentJP"] = "ふふん、いやぁ長かったね。そろそろスノウ様がカッコよく決める番かな！この勇姿、しかと見届けなさいよ！",
            ["DialogueId"] = 12044819,
            ["GUID"] = "1E27271E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120448/1E27271E",
            },
        [12044901] = {
            ["Content"] = "好样的，痛快！",
            ["ContentJP"] = "よっしゃ！",
            ["DialogueId"] = 12044901,
            ["GUID"] = "1E273492",
            ["NextDialogue"] = 12044902,
            ["RelatedWikiId"] = {
                [1] = 407008,
                [2] = 405010,
                },
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E273492",
            },
        [12044902] = {
            ["Content"] = "哈哈……我机枢派的上古造物终见天日了。怎么样，对面的应天尉，还有胆量来战吗？",
            ["ContentJP"] = "機枢の秘宝が、ついに目を覚ました……さあ、<Default note=\"text:おうてんい\">応天尉</>――まだやるか？",
            ["DialogueId"] = 12044902,
            ["GUID"] = "1E2734BC",
            ["NextDialogue"] = 12044903,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2734BC",
            },
        [12044903] = {
            ["Content"] = "一时胜负，终不能左右大局。奇技淫巧，岂可抵天命昭昭。",
            ["ContentJP"] = "勝敗は一時のこと。奇術で天命に抗えぬ",
            ["DialogueId"] = 12044903,
            ["GUID"] = "1E2734E6",
            ["NextDialogue"] = 12044904,
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2734E6",
            },
        [12044904] = {
            ["Content"] = "不好！",
            ["ContentJP"] = "まさか！",
            ["DialogueId"] = 12044904,
            ["GUID"] = "1E273510",
            ["NextDialogue"] = 12044905,
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E273510",
            },
        [12044905] = {
            ["Content"] = "太虚陵遇袭，速速回防、速速回防！",
            ["ContentJP"] = "太虚陵が襲撃された！全軍、撤退せよ！",
            ["DialogueId"] = 12044905,
            ["GUID"] = "1E27353A",
            ["NextDialogue"] = 12044906,
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E27353A",
            },
        [12044906] = {
            ["Content"] = "随着城区传来的巨大震动，众应天尉整齐划一地退军。",
            ["ContentJP"] = "<Default note=\"text:おうてんい\">応天尉</>たちは整然と戦場を離れていく。",
            ["DialogueId"] = 12044906,
            ["GUID"] = "1E273564",
            ["NextDialogue"] = 12044907,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E273564",
            },
        [12044907] = {
            ["Content"] = "片刻之后，山外山恢复了往常的清净，仿佛大军从未来袭。只有战斗留下的狼藉提醒你这一切并非幻觉。",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>には、静けさが戻った――まるで何もなかったかのように。ただ、荒れ果てた跡だけが、それが現実だったと語っていた。",
            ["DialogueId"] = 12044907,
            ["GUID"] = "1E27358E",
            ["NextDialogue"] = 12044908,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E27358E",
            },
        [12044908] = {
            ["Content"] = "……第二起，贲之涣。白贲饰伪，涣群为引。泽涸于山，损一隅而全大势。",
            ["ContentJP"] = "二つ目――『<Default note=\"text:ひのかん\">賁の渙</>』。\
荒れ山に、雨が下る。偽りで飾られた真が、群れを誘い、一隅を切り捨てて大局を救うでしょう。",
            ["DialogueId"] = 12044908,
            ["GUID"] = "1E2735B8",
            ["NextDialogue"] = 12044909,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2735B8",
            },
        [12044909] = {
            ["Content"] = "（头又开始疼起来了。这种感觉，难道说……）",
            ["ContentJP"] = "……また、頭が……この感覚……まさか……",
            ["DialogueId"] = 12044909,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E2735E2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120449/1E2735E2",
            },
        [12045001] = {
            ["Content"] = "刚刚那招实在是太帅了！优雅精准的弹道瞄准，兼以华丽的火力倾泻功率……",
            ["ContentJP"] = "さっきの一撃、すごくカッコよかった！エレガントな弾道に、華やかな火力の一斉掃射……これぞ美学ってやつだよ！",
            ["DialogueId"] = 12045001,
            ["GUID"] = "1E2744FA",
            ["NextDialogue"] = 12045002,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203007,
                [3] = 407008,
                [4] = 405010,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2744FA",
            },
        [12045002] = {
            ["Content"] = "喂喂，重点错了吧！你夸的到底是小仆从，还是你们机枢派的传奇机关造物？！",
            ["ContentJP"] = "ちょっと待った！どう見ても、お前たちの機関兵器を褒めてない！？",
            ["DialogueId"] = 12045002,
            ["GUID"] = "1E274524",
            ["NextDialogue"] = 12045003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E274524",
            },
        [12045003] = {
            ["Content"] = "嘻嘻，机枢派先人的造物，自然是鬼斧神工、集天地智慧之大成于一体……好了，还是不开玩笑啦。",
            ["ContentJP"] = "えへへ、だって<Default note=\"text:きすうは\">機枢派</>の技術って、神がかってるんだもん。\
智と技の結晶、芸術と戦術の極みっていうか――なーんて、冗談冗談。",
            ["DialogueId"] = 12045003,
            ["GUID"] = "1E27454E",
            ["NextDialogue"] = 12045004,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E27454E",
            },
        [12045004] = {
            ["Content"] = "{nickname}，若是没有你，山外山的危机不会如此轻易度过。请容我郑重地说一句感谢。",
            ["ContentJP"] = "{nickname}、あんたがいなかったら、<Default note=\"text:さんがいさん\">山外山</>はこの危機を乗り越えられなかったかもしれない。本当にありがとう。",
            ["DialogueId"] = 12045004,
            ["GUID"] = "1E274578",
            ["NextDialogue"] = 12045005,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E274578",
            },
        [12045005] = {
            ["Content"] = "真不愧是你！这身手，我刻舟都要甘拜下风了……",
            ["ContentJP"] = "……さすがだな。その身のこなし、さすがの俺も見入ったぜ……",
            ["DialogueId"] = 12045005,
            ["GUID"] = "1E2745A2",
            ["NextDialogue"] = 12045006,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2745A2",
            },
        [12045006] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12045006,
            ["GUID"] = "1E2745CC",
            ["NextDialogue"] = 12045007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2745CC",
            },
        [12045007] = {
            ["Content"] = "咦，{nickname}，你怎么看起来有些疲惫？刚刚没伤到哪里吧？",
            ["ContentJP"] = "えっ、{nickname}？ちょっと顔色悪くない？もしかして、どこかケガを！？",
            ["DialogueId"] = 12045007,
            ["GUID"] = "1E2745F6",
            ["NextDialogue"] = 12045008,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E2745F6",
            },
        [12045008] = {
            ["Content"] = "……小仆从，你还好吗？！……",
            ["ContentJP"] = "ひゃわわ、大丈夫！？",
            ["DialogueId"] = 12045008,
            ["GUID"] = "1E274620",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120450/1E274620",
            },
        [12045101] = {
            ["Content"] = "……第二起，贲之涣。白贲饰伪，涣群为引。泽涸于山，损一隅而全大势。",
            ["ContentJP"] = "二つ目――『<Default note=\"text:ひのかん\">賁の渙</>』。\
荒れ山に、雨が下る。偽りで飾られた真が、群れを誘い、一隅を切り捨てて大局を救うでしょう。",
            ["DialogueId"] = 12045101,
            ["GUID"] = "1E275562",
            ["NextDialogue"] = 12045102,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275562",
            },
        [12045102] = {
            ["Content"] = "{nickname}，<H>你将会匿入深山，使得山外山的位置暴露，并因此引来钧天铁卫。 </>",
            ["ContentJP"] = "{nickname}、<H>あなたは山奥に身を隠し、\
それによって<Default note=\"text:さんがいさん\">山外山</>の位置が敵に知られ、天衡の鉄衛が動き出す。</>",
            ["DialogueId"] = 12045102,
            ["GUID"] = "1E27558C",
            ["NextDialogue"] = 12045103,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27558C",
            },
        [12045103] = {
            ["Content"] = "这只是借用你的行踪，暂且调开城区的守备。你们只要坚持片刻，对面就会撤军。",
            ["ContentJP"] = "でも、これはあなたの足取りを借りて、都の守りを引き離しただけのこと。少し耐えれば、奴らは退くわ。",
            ["DialogueId"] = 12045103,
            ["GUID"] = "1E2755B6",
            ["NextDialogue"] = 12045104,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2755B6",
            },
        [12045104] = {
            ["Content"] = "我没兴趣听你这些预言。",
            ["ContentJP"] = "予言なんて興味ない。",
            ["DialogueId"] = 12045104,
            ["GUID"] = "1E2755E0",
            ["NextDialogue"] = 12045105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2755E0",
            },
        [12045105] = {
            ["Content"] = "如果结局都被你谱写好了，知道这些又有什么意义。放我出去。",
            ["ContentJP"] = "あらかじめ決められた結末なんて聞かされて、何の意味がある。……ここから出して。",
            ["DialogueId"] = 12045105,
            ["GUID"] = "1E27560A",
            ["NextDialogue"] = 12045106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27560A",
            },
        [12045106] = {
            ["Content"] = "别急——我们之间可能有很多误会。你的问题，我会一一解答。比如说，我的目标从来不是成神。",
            ["ContentJP"] = "焦らないで――誤解もあるでしょう。聞きたいことには、ちゃんと答えるわ。これだけは言わせて。私の目的は、神になることではない。",
            ["DialogueId"] = 12045106,
            ["GUID"] = "1E275634",
            ["NextDialogue"] = 12045107,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275634",
            },
        [12045107] = {
            ["Content"] = "对于烛阴祭坛之事，我表示十分抱歉。{nickname}，我很重视你。纵使有迫不得已的情形，但我从未将你作为一枚用而后弃的棋子看待。",
            ["ContentJP"] = "<Default note=\"text:しょくいんさいだん\">燭陰祭壇</>の件は、謝らせて。\
{nickname}……あなたのことは大切に思ってるわ。たとえどんな事情があったとしても、あなたを捨て駒にするつもりは、なかった。",
            ["DialogueId"] = 12045107,
            ["GUID"] = "1E27565E",
            ["NextDialogue"] = 12045108,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27565E",
            },
        [12045108] = {
            ["Content"] = "那你的目标是什么？",
            ["ContentJP"] = "……じゃあ、何が目的？",
            ["DialogueId"] = 12045108,
            ["GUID"] = "1E275688",
            ["NextDialogue"] = 12045109,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275688",
            },
        [12045109] = {
            ["Content"] = "如今的华胥，神明漠视众生，凡人麻木不仁。这僵化的大风九章种种，你也见证过了。",
            ["ContentJP"] = "いまの華胥では、神は人々に背を向けた。民もそれに慣れてしまっている。腐りきった大風九章のありよう……あなたも見たでしょう。",
            ["DialogueId"] = 12045109,
            ["GUID"] = "1E2756B2",
            ["NextDialogue"] = 12045110,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2756B2",
            },
        [12045110] = {
            ["Content"] = "我想做的事情很简单——<W>将那神明，自高天之上击落</>。",
            ["ContentJP"] = "私は――<W>その神を空から引きずり落としたい</>の。",
            ["DialogueId"] = 12045110,
            ["GUID"] = "1E2756DC",
            ["NextDialogue"] = 12045111,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2756DC",
            },
        [12045111] = {
            ["Content"] = "击落神明？",
            ["ContentJP"] = "神を……落とす？",
            ["DialogueId"] = 12045111,
            ["GUID"] = "1E275706",
            ["NextDialogue"] = 12045112,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275706",
            },
        [12045112] = {
            ["Content"] = "你的意思是……你要弑神？",
            ["ContentJP"] = "まさか、神殺しを？",
            ["DialogueId"] = 12045112,
            ["GUID"] = "1E275730",
            ["NextDialogue"] = 12045113,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275730",
            },
        [12045113] = {
            ["Content"] = "正是如此。",
            ["ContentJP"] = "まさしく。",
            ["DialogueId"] = 12045113,
            ["GUID"] = "1E27575A",
            ["NextDialogue"] = 12045114,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27575A",
            },
        [12045114] = {
            ["Content"] = "然而大风九章之力，并非平常手段可以抗衡。除非，借助某些这世上绝无仅有的能力。",
            ["ContentJP"] = "でも、大風九章の力に普通の手段が通用するはずもない。神を討てるのは、あの力だけなの。",
            ["DialogueId"] = 12045114,
            ["GUID"] = "1E275784",
            ["NextDialogue"] = 12045115,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275784",
            },
        [12045115] = {
            ["Content"] = "……和鸣之力。这就是你找上我的原因。",
            ["ContentJP"] = "……レゾナンス、か。{性别:だから僕に接触したんだな。|だから私に接触したんだね。}",
            ["DialogueId"] = 12045115,
            ["GUID"] = "1E2757AE",
            ["NextDialogue"] = 12045116,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2757AE",
            },
        [12045116] = {
            ["Content"] = "呵呵……没错。我以为这份古老的力量早已埋没于古籍之间，直到偶然发现了你的存在。",
            ["ContentJP"] = "ふふ……そうよ。この古い力なんて、とっくに忘れられたものだと思ってた。――あなたに出会うまでは。",
            ["DialogueId"] = 12045116,
            ["GUID"] = "1E2757D8",
            ["NextDialogue"] = 12045117,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E2757D8",
            },
        [12045117] = {
            ["Content"] = "你或许还对和鸣之力的本质懵懂无知——这是一份“引导”与“操控”的力量。华胥先祖<H>飏</>正是以相同的力量创立“大风九章”，将肆虐的秽兽化为龙神的爪牙。",
            ["ContentJP"] = "あなたはまだ、その力の本質を知らないでしょうけど……レゾナンスは「導き」と「支配」を司るもの。\
華胥の始祖・<H>ヤン</>は、この力を使って「大風九章」を築き上げ、あの荒れ狂う穢獣を、神の爪牙へと変えたの。",
            ["DialogueId"] = 12045117,
            ["GUID"] = "1E275802",
            ["NextDialogue"] = 12045118,
            ["RelatedWikiId"] = {
                [1] = 304002,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275802",
            },
        [12045118] = {
            ["Content"] = "因而，能够伤及太皓的，也便只有这份<H>同源的力量</>。",
            ["ContentJP"] = "つまり、太皓を傷つけられるのも――この<H>同じ源を持つ力</>だけ。",
            ["DialogueId"] = 12045118,
            ["GUID"] = "1E27582C",
            ["NextDialogue"] = 12045119,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E27582C",
            },
        [12045119] = {
            ["Content"] = "借你之手重创太皓、引开钧天铁卫……便能在那肆虐的风暴中，撕开一道足以击落神明的缝隙。",
            ["ContentJP"] = "あなたの手で太皓を討ち、天衡の鉄衛を引き離す……その混乱の中にこそ、神を堕とすための隙が生まれる。",
            ["DialogueId"] = 12045119,
            ["GUID"] = "1E275856",
            ["NextDialogue"] = 12045120,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275856",
            },
        [12045120] = {
            ["Content"] = "{nickname}，在这个结局中，也安排好了你的位置。不打算听听我能给出的报酬吗？",
            ["ContentJP"] = "{nickname}――この結末の中には、ちゃんとあなたの居場所もあるわ。……報酬の話、聞いてみる気はない？",
            ["DialogueId"] = 12045120,
            ["GUID"] = "1E275880",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120451/1E275880",
            },
        [12045201] = {
            ["Content"] = "嘘……听——是命运的车轮开始转动的声音。",
            ["ContentJP"] = "……聞いて。運命の車輪が……いま、回り始めた。",
            ["DialogueId"] = 12045201,
            ["GUID"] = "1E2765CA",
            ["NextDialogue"] = 12045202,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                [3] = 304002,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2765CA",
            },
        [12045202] = {
            ["Content"] = "如何？我所做的准备已经完毕。",
            ["ContentJP"] = "……準備は、すべて整ってる。",
            ["DialogueId"] = 12045202,
            ["GUID"] = "1E2765F4",
            ["NextDialogue"] = 12045203,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2765F4",
            },
        [12045203] = {
            ["Content"] = "如今太皓受创，守备空虚，接下来的关键，便是以你之力破开<H>太虚陵</>。",
            ["ContentJP"] = "太皓は傷を負い、守りも手薄になった。次は、あなたの力で<H>太虚陵</>をこじ開けるだけ。",
            ["DialogueId"] = 12045203,
            ["GUID"] = "1E27661E",
            ["NextDialogue"] = 12045204,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27661E",
            },
        [12045204] = {
            ["Content"] = "计划一旦开始，此后就是玉石俱焚，乾坤倒转。",
            ["ContentJP"] = "この計画が始まれば、もう後戻りはできない。――あとは全部、焼き尽くすだけよ。",
            ["DialogueId"] = 12045204,
            ["GUID"] = "1E276648",
            ["NextDialogue"] = 12045205,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276648",
            },
        [12045205] = {
            ["Content"] = "烛阴，你可准备好了？",
            ["ContentJP"] = "……<Default note=\"text:しょくいん\">燭陰</>、準備はできたかしら？",
            ["DialogueId"] = 12045205,
            ["GUID"] = "1E276672",
            ["NextDialogue"] = 12045206,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276672",
            },
        [12045206] = {
            ["Content"] = "……自吾黜落之日，便久待此刻。",
            ["ContentJP"] = "墜ちしその日より、ずっとこの刻を待ち続けてきた。",
            ["DialogueId"] = 12045206,
            ["GUID"] = "1E27669C",
            ["NextDialogue"] = 12045207,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27669C",
            },
        [12045207] = {
            ["Content"] = "自晦朔以望月，度春秋而经岁，终俟此报偿之期。吾之决意，岂容质疑。",
            ["ContentJP"] = "新月より満ち月を重ね、春を越え秋を越え――ようやく、この報いの時が訪れたのだ。",
            ["DialogueId"] = 12045207,
            ["GUID"] = "1E2766C6",
            ["NextDialogue"] = 12045208,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2766C6",
            },
        [12045208] = {
            ["Content"] = "反顾尔心，却似有不决。往昔之谊，竟使尔心志移易乎？",
            ["ContentJP"] = "我が決意に揺らぎはない。されと……汝の心は、かつての縁に迷わされてはおらぬか？",
            ["DialogueId"] = 12045208,
            ["GUID"] = "1E2766F0",
            ["NextDialogue"] = 12045209,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2766F0",
            },
        [12045209] = {
            ["Content"] = "……烛阴，我当初与你在祭坛上定下<H>魂契</>，可不是为了让你窥探我的内心。",
            ["ContentJP"] = "……<Default note=\"text:しょくいん\">燭陰</>。あのとき私があなたと<H>魂の契</>を交わしたのは、私の心を読ませるためじゃないと思うけど？",
            ["DialogueId"] = 12045209,
            ["GUID"] = "1E27671A",
            ["NextDialogue"] = 12045210,
            ["RelatedWikiId"] = {
                [1] = 304009,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27671A",
            },
        [12045210] = {
            ["Content"] = "不过，往昔之谊吗？或许吧……",
            ["ContentJP"] = "……昔の情かどうかは、わからない。でも……少しくらい、心は揺れるものよ。",
            ["DialogueId"] = 12045210,
            ["GUID"] = "1E276744",
            ["NextDialogue"] = 12045211,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276744",
            },
        [12045211] = {
            ["Content"] = "不知{nickname}在那里，是否安好。{性别：他|她}现在一定十分憎恨我吧。",
            ["ContentJP"] = "{nickname}……今ごろ、どうしてるかしら。きっと私のことをひどく恨んでいるんでしょうね。",
            ["DialogueId"] = 12045211,
            ["GUID"] = "1E27676E",
            ["NextDialogue"] = 12045212,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27676E",
            },
        [12045212] = {
            ["Content"] = "<H>和鸣之力</>，这曾为大风九章奠基者所掌握的能力，却在千年之后，经由一位异国旅者重新回到这片大地上。",
            ["ContentJP"] = "<H>レゾナンス</>――大風九章を築いた始祖がかつて手にした力。それが千年を越えて、異国の旅人によってこの地に再び現れた……",
            ["DialogueId"] = 12045212,
            ["GUID"] = "1E276798",
            ["NextDialogue"] = 12045213,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276798",
            },
        [12045213] = {
            ["Content"] = "这在冥冥之中意味着什么，烛阴，你有想过吗？",
            ["ContentJP"] = "それが何を意味するか……あなたは考えたこと、ある？",
            ["DialogueId"] = 12045213,
            ["GUID"] = "1E2767C2",
            ["NextDialogue"] = 12045214,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2767C2",
            },
        [12045214] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12045214,
            ["GUID"] = "1E2767EC",
            ["NextDialogue"] = 12045215,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2767EC",
            },
        [12045215] = {
            ["Content"] = "呵呵。时移势迁，世人早已忘却神因何存在。若是他们回想起自己顶礼膜拜的尊神，不过是凡人的造物，不知会作何感想。",
            ["ContentJP"] = "ふふ。時は流れ、人は忘れていく。神がなぜ神であるのかすら、誰も覚えていない。自分たちが信仰している偶像が、ただの人の手で作られた存在だと知ったら……どうするのかしらね。",
            ["DialogueId"] = 12045215,
            ["GUID"] = "1E276816",
            ["NextDialogue"] = 12045216,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276816",
            },
        [12045216] = {
            ["Content"] = "世人之念，非吾所顾。",
            ["ContentJP"] = "人の想いなど、我には関係ない。",
            ["DialogueId"] = 12045216,
            ["GUID"] = "1E276840",
            ["NextDialogue"] = 12045217,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276840",
            },
        [12045217] = {
            ["Content"] = "今吾所求者，唯有携太皓同烬，了却数百年之长恨！",
            ["ContentJP"] = "いま我が求めるのは、ただ太皓を灰と帰すこと。それが、幾百年にわたる憎しみを終える道だ。",
            ["DialogueId"] = 12045217,
            ["GUID"] = "1E27686A",
            ["NextDialogue"] = 12045218,
            ["SpeakNpcId"] = 240025,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E27686A",
            },
        [12045218] = {
            ["Content"] = "你我倒是各取所需。那么，走吧——",
            ["ContentJP"] = "私たちの望みは同じよ。行きましょう。",
            ["DialogueId"] = 12045218,
            ["GUID"] = "1E276894",
            ["NextDialogue"] = 12045219,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E276894",
            },
        [12045219] = {
            ["Content"] = "前往命运为我们设置的葬身之所吧……华胥这颠倒黑白的现状，也该在今日纠正过来了。",
            ["ContentJP"] = "私たちが辿り着く「運命の終点」へ。この歪んだ華胥を、今日こそ終わらせるのよ。",
            ["DialogueId"] = 12045219,
            ["GUID"] = "1E2768BE",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120452/1E2768BE",
            },
        [12045301] = {
            ["Content"] = "{nickname}，你休息得如何了？",
            ["ContentJP"] = "{nickname}、少しは楽になられましたか？",
            ["DialogueId"] = 12045301,
            ["GUID"] = "1E277632",
            ["NextDialogue"] = 12045302,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 203006,
                [3] = 401005,
                [4] = 304009,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277632",
            },
        [12045302] = {
            ["Content"] = "谢谢你，现在头已经不疼了。",
            ["ContentJP"] = "おかげで、頭痛は治まったよ。",
            ["DialogueId"] = 12045302,
            ["GUID"] = "1E27765C",
            ["NextDialogue"] = 12045303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E27765C",
            },
        [12045303] = {
            ["Content"] = "此次我不在你的身旁，无法及时照看你，现在才迟迟赶回……止流的第二个预言，是否已经应验了？",
            ["ContentJP"] = "傍におらず、お支えできなかったこと……心苦しく思っております。――シリュウの第二の予言、やはり成就してしまったのでございましょうか。",
            ["DialogueId"] = 12045303,
            ["GUID"] = "1E277686",
            ["NextDialogue"] = 12045304,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277686",
            },
        [12045304] = {
            ["Content"] = "嗯。以我为饵，诱使应天尉袭击山外山，就是止流第二个预言的内容。",
            ["ContentJP"] = "うん。{性别:僕|私}を囮にして応天尉を山外山に引き寄せる――それがシリュウさんの狙いだった。",
            ["DialogueId"] = 12045304,
            ["GUID"] = "1E2776B0",
            ["NextDialogue"] = 12045305,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2776B0",
            },
        [12045305] = {
            ["Content"] = "但她的目标并非摧毁山外山，而是调开应天尉和狴犴，以方便她在其他地方做手脚……",
            ["ContentJP"] = "けど彼女の本当の目的は、<Default note=\"text:さんがいさん\">山外山</>を滅ぼすことじゃない。\
<Default note=\"text:おうてんい\">応天尉</>や<Default note=\"text:ビーアン\">狴犴</>を引き離し、別の場所で仕掛けをするためだった{性别:んだ|の}。",
            ["DialogueId"] = 12045305,
            ["GUID"] = "1E2776DA",
            ["NextDialogue"] = 12045306,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2776DA",
            },
        [12045306] = {
            ["Content"] = "原来如此，这就是应天尉突然撤离的原因吗……",
            ["ContentJP"] = "なるほど……。だから、<Default note=\"text:おうてんい\">応天尉</>は突然退いたのですね。",
            ["DialogueId"] = 12045306,
            ["GUID"] = "1E277704",
            ["NextDialogue"] = 12045307,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277704",
            },
        [12045307] = {
            ["Content"] = "事件发生之时，我恰好身在城区中，目睹了从执律阁顶传来的巨大震动，路人们惊骇不已。",
            ["ContentJP"] = "私はちょうど城下におりまして、<Default note=\"text:しつりつかく\">執律閣</>の頂より響いた大きな震動を目にいたしました。人々は恐れ、騒ぎ立つばかり……",
            ["DialogueId"] = 12045307,
            ["GUID"] = "1E27772E",
            ["NextDialogue"] = 12045308,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E27772E",
            },
        [12045308] = {
            ["Content"] = "我离开时，情况已经得到控制，但具体的内情却无人知晓。",
            ["ContentJP"] = "私が立ち去る頃には収まっておりましたが、真相を知る者は誰もおりませんでした。",
            ["DialogueId"] = 12045308,
            ["GUID"] = "1E277758",
            ["NextDialogue"] = 12045309,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277758",
            },
        [12045309] = {
            ["Content"] = "抱歉，因为一些私事，我在城中有所逗留。若是我能更早赶回来……",
            ["ContentJP"] = "……申し訳ございません。私事にて城に留まっておりましたゆえ、戻りが遅れてしまいました。もしも、もっと早く駆けつけていれば……",
            ["DialogueId"] = 12045309,
            ["GUID"] = "1E277782",
            ["NextDialogue"] = 12045310,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277782",
            },
        [12045310] = {
            ["Content"] = "扶疏，不用向我道歉。你有你自己要忙的事情，作为朋友，我只希望你能够完成你的心愿。",
            ["ContentJP"] = "謝{性别:るな|らないで}。あなたにはあなたのやるべきことがある。あなたが自分の願いを果たせるのなら、友としてはうれしいよ。",
            ["DialogueId"] = 12045310,
            ["GUID"] = "1E2777AC",
            ["NextDialogue"] = 12045311,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2777AC",
            },
        [12045311] = {
            ["Content"] = "不过，如果你遇到了一个人没法解决的难题，一定要告诉我。我会帮你一起想办法的，好吗？",
            ["ContentJP"] = "でも、一人で抱えきれない問題があったら、必ず言ってほしい。きっと力になるから。",
            ["DialogueId"] = 12045311,
            ["GUID"] = "1E2777D6",
            ["NextDialogue"] = 12045312,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E2777D6",
            },
        [12045312] = {
            ["Content"] = "……嗯。{nickname}，你这番话，我会记住的。",
            ["ContentJP"] = "……はい。{nickname}さんのお言葉、しっかり胸に刻んでおきましょう。",
            ["DialogueId"] = 12045312,
            ["GUID"] = "1E277800",
            ["NextDialogue"] = 12045313,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E277800",
            },
        [12045313] = {
            ["Content"] = "解除催眠的线索我已经有所掌握，待人齐了，再一起细说。你若是感觉好些了，先出去转转吧。",
            ["ContentJP"] = "催眠を解く手立てについては、すでに見当がついております。皆が揃いました折に、改めて詳しくお話しいたしましょう。\
それまでは、どうぞ少し外を歩き、気を紛らわせてくださいませ。",
            ["DialogueId"] = 12045313,
            ["GUID"] = "1E27782A",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120453/1E27782A",
            },
        [12045401] = {
            ["Content"] = "苏姑娘，今天我就来讨个准话，那{nickname}，你是赶还是不赶？",
            ["ContentJP"] = "スーさん、はっきりさせてもらおうか。{nickname}を、ここから追い出す件についてな！",
            ["DialogueId"] = 12045401,
            ["GUID"] = "1E27869A",
            ["NextDialogue"] = 12045402,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                },
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E27869A",
            },
        [12045402] = {
            ["Content"] = "我苏乙在这里用名誉担保，{nickname}绝不是什么悬衡派细作！",
            ["ContentJP"] = "私の名にかけて保証するわ。{nickname}は決して<Default note=\"text:けんこうは\">懸衡派</>の密偵なんかじゃない！",
            ["DialogueId"] = 12045402,
            ["GUID"] = "1E2786C4",
            ["NextDialogue"] = 12045403,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2786C4",
            },
        [12045403] = {
            ["Content"] = "不是细作？哈，你说巧不巧，这些年来山外山入口从未暴露半分，{性别：他|她}这个外人刚一脚踏进门，那些恶狼就闻着味儿追上来了！",
            ["ContentJP"] = "密偵じゃない？笑わせるな。これまで<Default note=\"text:さんがいさん\">山外山</>の入口が敵に嗅ぎつけられたことなどなかった。なのに、あいつが足を踏み入れた途端、奴らは押し寄せてきたんだぞ！",
            ["DialogueId"] = 12045403,
            ["GUID"] = "1E2786EE",
            ["NextDialogue"] = 12045404,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2786EE",
            },
        [12045404] = {
            ["Content"] = "我不信猜测。我相信的，只有亲眼所见的事实。",
            ["ContentJP"] = "あくまで憶測でしょ！私は自分の目で見たものしか信じないわ。",
            ["DialogueId"] = 12045404,
            ["GUID"] = "1E278718",
            ["NextDialogue"] = 12045405,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278718",
            },
        [12045405] = {
            ["Content"] = "刚刚钧天铁卫袭来时，{性别：他|她}帮我们击退了敌人——这才是我看到的。",
            ["ContentJP"] = "{性别:彼|彼女}は天衡の鉄衛から私たちを守るために戦った。それが、私が見た事実よ！",
            ["DialogueId"] = 12045405,
            ["GUID"] = "1E278742",
            ["NextDialogue"] = 12045406,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278742",
            },
        [12045406] = {
            ["Content"] = "你怎知{性别：他|她}不是在骗取你信任？",
            ["ContentJP"] = "ふん……あの者の芝居かもしれんだろう！",
            ["DialogueId"] = 12045406,
            ["GUID"] = "1E27876C",
            ["NextDialogue"] = 12045407,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E27876C",
            },
        [12045407] = {
            ["Content"] = "钧天铁卫是自己跑的，不是被我们打退的！山外山的位置已经暴露，那些走狗随时可能卷土重来！到时候，你还有信心打赢第二次吗？",
            ["ContentJP"] = "山外山の位置は既に知られた。奴らは必ず戻ってくる。次もまた勝てる保証はあるのか！？",
            ["DialogueId"] = 12045407,
            ["GUID"] = "1E278796",
            ["NextDialogue"] = 12045408,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278796",
            },
        [12045408] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12045408,
            ["GUID"] = "1E2787C0",
            ["NextDialogue"] = 12045409,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2787C0",
            },
        [12045409] = {
            ["Content"] = "我们机枢派如今衰颓至此，还不是因为你们这些人行事软弱，一退再退吗？！",
            ["ContentJP"] = "我ら<Default note=\"text:きすう\">機枢</>が落ちぶれたのも、お前たちのような弱腰のせいだ！",
            ["DialogueId"] = 12045409,
            ["GUID"] = "1E2787EA",
            ["NextDialogue"] = 12045410,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2787EA",
            },
        [12045410] = {
            ["Content"] = "当初我们在<H>黍离之战</>中被泼了污名，无人奋起反抗，任由那悬衡奸贼瓜分我派。后来他们对机括术百般打压，我们还是忍气吞声。",
            ["ContentJP"] = "<H><Default note=\"text:しょりのらん\">黍離の乱</></>で濡れ衣を着せられ、誰も声を上げず、<Default note=\"text:けんこうは\">懸衡派</>に食い荒らされた……",
            ["DialogueId"] = 12045410,
            ["GUID"] = "1E278814",
            ["NextDialogue"] = 12045411,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278814",
            },
        [12045411] = {
            ["Content"] = "如今机枢派后人不是在天梁司摇尾乞怜，就是龟缩在这不见天日的山外山，谁还记得我们机枢派曾是和悬衡派并立的华胥支柱？！",
            ["ContentJP"] = "その後も弾圧に耐え、今や一部は<Default note=\"text:てんりょうし\">天梁司</>に尻尾を振り、残りはこうして穴蔵に籠るだけ。\
かつての<Default note=\"text:きすう\">機枢</>の誇りを覚えている者など、もうどこにもおらん！",
            ["DialogueId"] = 12045411,
            ["GUID"] = "1E27883E",
            ["NextDialogue"] = 12045412,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E27883E",
            },
        [12045412] = {
            ["Content"] = "……够了。",
            ["ContentJP"] = "……もうやめて！",
            ["DialogueId"] = 12045412,
            ["GUID"] = "1E278868",
            ["NextDialogue"] = 12045413,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278868",
            },
        [12045413] = {
            ["Content"] = "徐泓，我知道你操心的一切都是为了机枢派，为了山外山。",
            ["ContentJP"] = "ジョコウ、あなたが<Default note=\"text:きすう\">機枢</>を思う気持ちはわかる。<Default note=\"text:きすうは\">機枢派</>を守りたいのもわかる。",
            ["DialogueId"] = 12045413,
            ["GUID"] = "1E278892",
            ["NextDialogue"] = 12045414,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278892",
            },
        [12045414] = {
            ["Content"] = "但我更知道，“兼爱幽明，天地一心”……以心为本，兼爱世人，才是机枢派入门传授的第一课。",
            ["ContentJP"] = "けれど、忘れないで。「生も死も、明も暗も、分け隔てなく愛し、天地をひとつと見よ」――それが機枢派の教えよ！",
            ["DialogueId"] = 12045414,
            ["GUID"] = "1E2788BC",
            ["NextDialogue"] = 12045415,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2788BC",
            },
        [12045415] = {
            ["Content"] = "{nickname}是我的朋友，也是方才帮了我们的恩人，如果在此时此刻弃之不顾，任由{性别：他|她}陷于危险之中，我们才是真正背叛了机枢之道！",
            ["ContentJP"] = "{nickname}は私の友達であり、命を賭して助けてくれた恩人よ。その恩人を突き放すなんて、<Default note=\"text:きすう\">機枢</>の教えに背く裏切りだわ！",
            ["DialogueId"] = 12045415,
            ["GUID"] = "1E2788E6",
            ["NextDialogue"] = 12045416,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E2788E6",
            },
        [12045416] = {
            ["Content"] = "你……哼！",
            ["ContentJP"] = "……ふん、好きにしろ！",
            ["DialogueId"] = 12045416,
            ["GUID"] = "1E278910",
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1204/120454/1E278910",
            },
        [12045501] = {
            ["Content"] = "如果你们还是想劝我赶走{nickname}，就请回吧！我说过很多次——我不会答应的！",
            ["ContentJP"] = "何度言っても無駄よ！絶対に{nickname}を追い出したりしないから！",
            ["DialogueId"] = 12045501,
            ["GUID"] = "1E279702",
            ["NextDialogue"] = 12045502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 408018,
                [3] = 103001,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279702",
            },
        [12045502] = {
            ["Content"] = "苏乙姐姐……",
            ["ContentJP"] = "スーイー……",
            ["DialogueId"] = 12045502,
            ["GUID"] = "1E27972C",
            ["NextDialogue"] = 12045503,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E27972C",
            },
        [12045503] = {
            ["Content"] = "哇啊啊啊，{nickname}，还有小白，原、原来是你们来了……",
            ["ContentJP"] = "わ、わあっ！？{nickname}にスノウまで……",
            ["DialogueId"] = 12045503,
            ["GUID"] = "1E279756",
            ["NextDialogue"] = 12045504,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279756",
            },
        [12045504] = {
            ["Content"] = "你、你们不会都听到了吧？！",
            ["ContentJP"] = "もしかして、聞いてた？",
            ["DialogueId"] = 12045504,
            ["GUID"] = "1E279780",
            ["NextDialogue"] = 12045505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279780",
            },
        [12045505] = {
            ["Content"] = "……嗯。",
            ["ContentJP"] = "……うん。",
            ["DialogueId"] = 12045505,
            ["GUID"] = "1E2797AA",
            ["NextDialogue"] = 12045506,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2797AA",
            },
        [12045506] = {
            ["Content"] = "……好吧，我本不希望你们知道这些。",
            ["ContentJP"] = "……そっか。本当は隠しておきたかったんだけど。",
            ["DialogueId"] = 12045506,
            ["GUID"] = "1E2797D4",
            ["NextDialogue"] = 12045507,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2797D4",
            },
        [12045507] = {
            ["Content"] = "是这样的，有些人认为你们故意泄露了基地的位置，与大风九章沆瀣一气……但是，不用担心！我已经和他们说过了！他们不会再来找麻烦的！",
            ["ContentJP"] = "実はね、あんたがわざと敵を引き寄せたんじゃないかって疑ってる人たちがいるの。でも安心して！私がそんなことさせないから！もう大丈夫よ！",
            ["DialogueId"] = 12045507,
            ["GUID"] = "1E2797FE",
            ["NextDialogue"] = 12045508,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2797FE",
            },
        [12045508] = {
            ["Content"] = "你们不要生气，那些人的说法是很过分，但他们只是太担心了……毕竟山外山是我们唯一的家。",
            ["ContentJP"] = "あの人たち、言葉はキツイけど、本当は不安なだけよ。<Default note=\"text:さんがいさん\">山外山</>は私たちに残された唯一の居場所だから……",
            ["DialogueId"] = 12045508,
            ["GUID"] = "1E279828",
            ["NextDialogue"] = 12045509,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279828",
            },
        [12045509] = {
            ["Content"] = "谢谢你。不过，有一点他们说的没错……钧天铁卫，确实是我引来的。",
            ["ContentJP"] = "ありがとう。でも、{性别:彼らは間違ってないよ……天衡の鉄衛を呼び寄せたのは、確かに僕なんだ。|彼らは間違ってないわ……天衡の鉄衛を呼び寄せたのは、確かに私なの。}",
            ["DialogueId"] = 12045509,
            ["GUID"] = "1E279852",
            ["NextDialogue"] = 12045510,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279852",
            },
        [12045510] = {
            ["Content"] = "什——",
            ["ContentJP"] = "え……",
            ["DialogueId"] = 12045510,
            ["GUID"] = "1E27987C",
            ["NextDialogue"] = 12045511,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E27987C",
            },
        [12045511] = {
            ["Content"] = "止流在我身上做了特殊的手脚，引得此地坐标暴露于大风九章的监视下。这是她在第二卦中亲口告诉我的。所以，我不能继续留在这里了。",
            ["ContentJP"] = "シリュウに術をかけられててね。{性别:僕の存在そのものが、居場所を暴かれる原因になったんだ。|私の存在そのものが、居場所を暴かれる原因になったの。}だからもう、ここにはいられない。",
            ["DialogueId"] = 12045511,
            ["GUID"] = "1E2798A6",
            ["NextDialogue"] = 12045512,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2798A6",
            },
        [12045512] = {
            ["Content"] = "可、可是，你对这事并不知情，不是你的错……我再想想办法！",
            ["ContentJP"] = "そ、そんな……！でも、あんたは知らなかったんでしょ？あんたのせいじゃないよ！私、方法を考えるから……！",
            ["DialogueId"] = 12045512,
            ["GUID"] = "1E2798D0",
            ["NextDialogue"] = 12045513,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2798D0",
            },
        [12045513] = {
            ["Content"] = "没关系的，苏乙，你的心意我领会到了。但是山外山刚刚受袭，你还有很多更重要的事情要做。",
            ["ContentJP"] = "{性别:いいんだ|いいの}、スーイー。気持ちは嬉しいけど、あなたには他にやるべきことがある。",
            ["DialogueId"] = 12045513,
            ["GUID"] = "1E2798FA",
            ["NextOptions"] = {
                [1] = 12045514,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2798FA",
            },
        [12045514] = {
            ["Content"] = "（摸摸苏乙的头。）",
            ["ContentJP"] = "スーイーの頭をなでる",
            ["DialogueId"] = 12045514,
            ["GUID"] = "1E279924",
            ["NextDialogue"] = 12045515,
            },
        [12045515] = {
            ["Content"] = "我也有自己的事要解决。我必须在止流的第三卦应验前找到她。约好了，我们会平安再见的，好吗？",
            ["ContentJP"] = "{性别:僕も自分のすべきことを探しに行く。シリュウの第三の予言が現実になる前に、彼女を見つけ出すんだ。必ずまた会えるよ。約束する。|私も自分のすべきことを探しに行く。シリュウの第三の予言が現実になる前に、彼女を見つけ出すんだ。必ずまた会えるわ。約束する。}",
            ["DialogueId"] = 12045515,
            ["GUID"] = "1E27994E",
            ["NextDialogue"] = 12045516,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E27994E",
            },
        [12045516] = {
            ["Content"] = "……那你……不许食言！",
            ["ContentJP"] = "……絶対よ！破ったら許さないんだから！",
            ["DialogueId"] = 12045516,
            ["GUID"] = "1E279978",
            ["NextDialogue"] = 12045517,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279978",
            },
        [12045517] = {
            ["Content"] = "对了，刻舟那家伙不知道跑到哪儿去了，可能刚和煜明大吵一架，心情不太好吧。",
            ["ContentJP"] = "そういえば、カシュウが見当たらないのよね。ユーミンとのことでふてくされてるんでしょうけど。",
            ["DialogueId"] = 12045517,
            ["GUID"] = "1E2799A2",
            ["NextDialogue"] = 12045518,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2799A2",
            },
        [12045518] = {
            ["Content"] = "你找到他，带他一起出发吧。那家伙前头一直说，他欠你一条命，所以你的忙，他帮定了。",
            ["ContentJP"] = "見つけたら、一緒に連れて行くといいわ。あんたに借りがあるって言ってたし、きっと力を貸してくれるはずよ。",
            ["DialogueId"] = 12045518,
            ["GUID"] = "1E2799CC",
            ["NextDialogue"] = 12045519,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2799CC",
            },
        [12045519] = {
            ["Content"] = "城中现在暗潮汹涌，多个帮手总是好的。而且那个大块头还算能打。",
            ["ContentJP"] = "今の城は波立つ水面みたいに不安定だわ。味方は一人でも多い方がいいし……それにあいつ、腕っぷしだけは確かだから！",
            ["DialogueId"] = 12045519,
            ["GUID"] = "1E2799F6",
            ["NextDialogue"] = 12045520,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E2799F6",
            },
        [12045520] = {
            ["Content"] = "对了，还有！",
            ["ContentJP"] = "あっ、そうだ、もうひとつ！",
            ["DialogueId"] = 12045520,
            ["GUID"] = "1E279A20",
            ["NextDialogue"] = 12045521,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279A20",
            },
        [12045521] = {
            ["Content"] = "以后不许摸我脑袋！在我们华胥只有长辈可以摸小辈的头！我的脑袋只有我姑姑摸过！",
            ["ContentJP"] = "もう頭を撫でるのは禁止ね！私たち華胥では、頭を撫でていいのは年長者だけよ！私の頭に触れたことがあるのは、叔母さまだけなんだから！",
            ["DialogueId"] = 12045521,
            ["GUID"] = "1E279A4A",
            ["NextOptions"] = {
                [1] = 12045522,
                [2] = 12045523,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279A4A",
            },
        [12045522] = {
            ["Content"] = "抱歉，失礼了。",
            ["ContentJP"] = "あ、ごめん。",
            ["DialogueId"] = 12045522,
            ["GUID"] = "1E279A74",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12045524,
            },
        [12045523] = {
            ["Content"] = "好的，叫{性别：爸爸|姑奶奶}。",
            ["ContentJP"] = "じゃあ{性别:叔父さま|叔母さま}って呼んでいいよ。",
            ["DialogueId"] = 12045523,
            ["GUID"] = "1E279A9E",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12045525,
            },
        [12045524] = {
            ["Content"] = "好，好了……反正你也不是本地人，我也没那么介意啦！",
            ["ContentJP"] = "も、もういいわ……あなたはよそ者だしね。そんなに気にしてないわ。",
            ["DialogueId"] = 12045524,
            ["GUID"] = "1E279AC8",
            ["NextDialogue"] = 12045528,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279AC8",
            },
        [12045525] = {
            ["Content"] = "……？反了你了！",
            ["ContentJP"] = "な、なによそれ！失礼ね！",
            ["DialogueId"] = 12045525,
            ["GUID"] = "1E279AF2",
            ["NextDialogue"] = 12045526,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279AF2",
            },
        [12045526] = {
            ["Content"] = "既然刻舟是你兄弟，你要跟着他一起喊姑奶奶——听到了没，姑，奶，奶！",
            ["ContentJP"] = "カシュウとは友達なんでしょ？華胥の掟だったら私はあんたの叔母さまでもあるんだから！いい？お・ば・さ・ま。",
            ["DialogueId"] = 12045526,
            ["GUID"] = "1E279B1C",
            ["NextDialogue"] = 12045527,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B1C",
            },
        [12045527] = {
            ["Content"] = "哈哈，你看上去总算精神些了。",
            ["ContentJP"] = "うふふ、元気が出てきたようだね。",
            ["DialogueId"] = 12045527,
            ["GUID"] = "1E279B46",
            ["NextDialogue"] = 12045528,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B46",
            },
        [12045528] = {
            ["Content"] = "唔，接下来我得先清点基地受损状况，给大家送药……晚点还要修整机关……",
            ["ContentJP"] = "……とにかく、私は基地の損害を確認して、薬を配って、壊れた機関を直さなきゃいけないから。",
            ["DialogueId"] = 12045528,
            ["GUID"] = "1E279B70",
            ["NextDialogue"] = 12045529,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B70",
            },
        [12045529] = {
            ["Content"] = "你找到刻舟后，先过来汇总情报，确认一下之后的行动方向再出发。虽然我暂时抽不开身，没法支援你们，但提供些情报支持还是小事一桩。",
            ["ContentJP"] = "カシュウを見つけたら、必ずここに戻ってきて。今後の計画を決めておかないと。直接力にはなれないけど、情報なら提供できるわ。",
            ["DialogueId"] = 12045529,
            ["GUID"] = "1E279B9A",
            ["NextDialogue"] = 12045530,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279B9A",
            },
        }
  end },
  { MinKey = 12045530, MaxKey = 12046431, Loader = function()
      return {
        [12045530] = {
            ["Content"] = "小仆从，你先去吧。我留在这里等你。",
            ["ContentJP"] = "下僕、先に行きな！スノウはここで待ってるよ！",
            ["DialogueId"] = 12045530,
            ["GUID"] = "1E279BC4",
            ["NextDialogue"] = 12045531,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279BC4",
            },
        [12045531] = {
            ["Content"] = "太阳从西边出来了么？你怎么突然不跟着我了？",
            ["ContentJP"] = "えぇ！？{性别:僕|私}と別行動なんて珍しい……どうしたの？",
            ["DialogueId"] = 12045531,
            ["GUID"] = "1E279BEE",
            ["NextDialogue"] = 12045532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279BEE",
            },
        [12045532] = {
            ["Content"] = "我……我对刚刚他们吵架时提到的那些悬衡啊机枢啊黍离之战什么的很好奇，不行吗！我的好学之心现在正在熊熊燃烧！",
            ["ContentJP"] = "い、いいじゃん！さっきの言い合いで聞いた「<Default note=\"text:けんこうは\">懸衡派</>」とか「<Default note=\"text:きすうは\">機枢派</>」とか「<Default note=\"text:しょりのらん\">黍離の乱</>」とか…気になることがいっぱいだから！",
            ["DialogueId"] = 12045532,
            ["GUID"] = "1E279C18",
            ["NextDialogue"] = 12045533,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279C18",
            },
        [12045533] = {
            ["Content"] = "你该不会是今天一天走累了，想偷懒吧？",
            ["ContentJP"] = "ふーん？ほんとは疲れちゃってサボりたいんじゃないの{性别:か|}？",
            ["DialogueId"] = 12045533,
            ["GUID"] = "1E279C42",
            ["NextDialogue"] = 12045534,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279C42",
            },
        [12045534] = {
            ["Content"] = "我、我才不会呢！小仆从你快去找刻舟啦，别让那家伙溜了！",
            ["ContentJP"] = "ち、ちがうもんっ！とにかく、早くカシュウを見つけてきて！逃がしちゃダメだからな！",
            ["DialogueId"] = 12045534,
            ["GUID"] = "1E279C6C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120455/1E279C6C",
            },
        [12045601] = {
            ["Content"] = "说起来，苏乙姐姐，我和小仆从成为你们机枢派的荣誉学徒这么久，还对机枢派的过往一无所知呢。",
            ["ContentJP"] = "そうだ、スーイー。スノウと下僕ってさ、けっこう前から<Default note=\"text:きすうは\">機枢派</>の優秀な名誉見習いなのに、機枢派のことほとんど知らないんだよね。",
            ["DialogueId"] = 12045601,
            ["GUID"] = "1E27A76A",
            ["NextDialogue"] = 12045602,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 407008,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A76A",
            },
        [12045602] = {
            ["Content"] = "听起来，机枢派也有过很拉风的时候，非常配得上白魔王大人的身份！啊对，后来发生了什么哇？给我也讲讲吧！",
            ["ContentJP"] = "聞いた感じだと、<Default note=\"text:きすうは\">機枢派</>って昔はかなりイケてたんでしょ？このスノウ様の名にふさわしいくらいにさ！…で、何があったの？",
            ["DialogueId"] = 12045602,
            ["GUID"] = "1E27A794",
            ["NextDialogue"] = 12045603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A794",
            },
        [12045603] = {
            ["Content"] = "荣誉学徒？我明白了，一定是公尚师傅那家伙又在外面试图捡徒弟了。",
            ["ContentJP"] = "名誉見習い？……ふふん、なるほどね。きっとコウショウ師匠がまた弟子を取ろうとしたのね。",
            ["DialogueId"] = 12045603,
            ["GUID"] = "1E27A7BE",
            ["NextDialogue"] = 12045604,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A7BE",
            },
        [12045604] = {
            ["Content"] = "既然如此，那本师姐可要好好说一说了，你就洗耳恭听吧！",
            ["ContentJP"] = "ま、いいわ。せっかくだから、先輩としてしっかり教えてあげる！耳かっぽじって聞きなさい！",
            ["DialogueId"] = 12045604,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E27A7E8",
            ["NextDialogue"] = 12045605,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A7E8",
            },
        [12045605] = {
            ["Content"] = "先问你一个问题，对于大风九章的来历，你知道多少？",
            ["ContentJP"] = "まず一つ質問。大風九章って、誰が作ったか知ってる？",
            ["DialogueId"] = 12045605,
            ["GUID"] = "1E27A812",
            ["NextDialogue"] = 12045606,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A812",
            },
        [12045606] = {
            ["Content"] = "我记得我记得！是一个很厉害的家伙创立的，那个人叫……",
            ["ContentJP"] = "えーとね、えーと……すごい人だったのは覚えてる！名前は……",
            ["DialogueId"] = 12045606,
            ["GUID"] = "1E27A83C",
            ["NextOptions"] = {
                [1] = 12045607,
                [2] = 12045608,
                [3] = 12045609,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A83C",
            },
        [12045607] = {
            ["Content"] = "是悬衡派的先人飏创立的。",
            ["ContentJP"] = "懸衡派の先祖、ヤンでしょ？",
            ["DialogueId"] = 12045607,
            ["GUID"] = "1E27A866",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12045610,
            },
        [12045608] = {
            ["Content"] = "是光之魔王大人白女士穿越时空创立的！",
            ["ContentJP"] = "光の魔王、スノウ様が時空を超えて創ったんだよ！",
            ["DialogueId"] = 12045608,
            ["GUID"] = "1E27A890",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12045611,
            },
        [12045609] = {
            ["Content"] = "我想不起来了……",
            ["ContentJP"] = "えーと……忘れた。",
            ["DialogueId"] = 12045609,
            ["GUID"] = "1E27A8BA",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12045612,
            },
        [12045610] = {
            ["Content"] = "哼，就知道悬衡派会把功劳全都揽到自己头上。",
            ["ContentJP"] = "あーあ、やっぱり。<Default note=\"text:けんこうは\">懸衡派</>ってすぐ自分たちの手柄にしたがるのよねぇ。",
