            ["NextDialogue"] = 12045612,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A90E",
            },
        [12045612] = {
            ["Content"] = "呀！小仆从你什么时候回来的！",
            ["ContentJP"] = "あれ、もう戻ってきたの！？",
            ["DialogueId"] = 12045612,
            ["GUID"] = "1E27A938",
            ["NextDialogue"] = 12045613,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A938",
            },
        [12045613] = {
            ["Content"] = "怎么啦，你能听师姐讲课，我就不能听了吗？",
            ["ContentJP"] = "ええ、先輩の講義を独り占めしたいのかな？",
            ["DialogueId"] = 12045613,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E27A962",
            ["NextDialogue"] = 12045614,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A962",
            },
        [12045614] = {
            ["Content"] = "当然欢迎！那么，我继续讲——上古时期，秽兽频出，纷争不绝于境。",
            ["ContentJP"] = "もちろん大歓迎よ。じゃあ、続けるわね――古の時代、華胥の地には穢獣があふれ、争いが絶えなかったの。",
            ["DialogueId"] = 12045614,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E27A98C",
            ["NextDialogue"] = 12045615,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A98C",
            },
        [12045615] = {
            ["Content"] = "如何才能让华胥子民免受秽蚀和战争的困扰呢，开国先祖<H>矩</>和<H>飏</>二人进行了长足的思考。",
            ["ContentJP"] = "その混乱をどうにかしようと、開祖である<H>ノリ</>と<H>ヤン</>は、長い間知恵を絞り続けた。",
            ["DialogueId"] = 12045615,
            ["GUID"] = "1E27A9B6",
            ["NextDialogue"] = 12045616,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A9B6",
            },
        [12045616] = {
            ["Content"] = "最终，大风九章横空出世，给华胥带来了绵延数百年的和平。",
            ["ContentJP"] = "そして、ようやく編み出されたのが「大風九章」。それは華胥に数百年の平穏をもたらした偉大な技術体系だった。",
            ["DialogueId"] = 12045616,
            ["GUID"] = "1E27A9E0",
            ["NextDialogue"] = 12045617,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27A9E0",
            },
        [12045617] = {
            ["Content"] = "这庇佑华胥全境的惊世之术，可不是光凭飏一人就能完成的，我们机枢派的先人<H>矩</>在此过程中也发挥了必不可少的作用。",
            ["ContentJP"] = "でも、それを実現するにはヤン一人の力では足りなかった。我が<Default note=\"text:きすうは\">機枢派</>の始祖<H>ノリ</>が、極めて重要な役割を果たしたの。",
            ["DialogueId"] = 12045617,
            ["GUID"] = "1E27AA0A",
            ["NextDialogue"] = 12045618,
            ["RelatedWikiId"] = {
                [1] = 203010,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA0A",
            },
        [12045618] = {
            ["Content"] = "你们或许知道，飏有一种特殊的能力，通过焚烧“香”这种介质，她能够影响和操控区域中的秽兽，让它们乖乖听话，不再伤人。",
            ["ContentJP"] = "知っていると思ったが、ヤンは「香」という媒介を使って、穢獣を制御する能力があった。",
            ["DialogueId"] = 12045618,
            ["GUID"] = "1E27AA34",
            ["NextDialogue"] = 12045619,
            ["RelatedWikiId"] = {
                [1] = 203003,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA34",
            },
        [12045619] = {
            ["Content"] = "但是怎么才能将这种能力固定和放大呢？",
            ["ContentJP"] = "けど、その力を固定化し、増幅するのは課題となってた。",
            ["DialogueId"] = 12045619,
            ["GUID"] = "1E27AA5E",
            ["NextDialogue"] = 12045620,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA5E",
            },
        [12045620] = {
            ["Content"] = "为了寻找这个答案，矩四处游学，甚至最远抵达了艾利西安的“塔”下，与你们海伯利亚的先祖展开了一场激动人心的史诗大冒险——咳咳，扯远了。",
            ["ContentJP"] = "ノリはその答えを求めて旅に出て、ついにはエリュシオンの「塔」にまで辿り着き、あなたたちヒュペリアの先祖と心躍る冒険を――って、少し脱線しちゃったわね。",
            ["DialogueId"] = 12045620,
            ["GUID"] = "1E27AA88",
            ["NextDialogue"] = 12045621,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AA88",
            },
        [12045621] = {
            ["Content"] = "总之，矩最后找到了答案。他带着这个答案回到华胥，集齐人力物力，打造了一个巨大的工程。",
            ["ContentJP"] = "やがて、ノリは答えに辿り着いた。その知を携え、彼は華胥へ戻ると、人と資源を総動員し、かつてない規模の大事業に着手した。",
            ["DialogueId"] = 12045621,
            ["GUID"] = "1E27AAB2",
            ["NextDialogue"] = 12045622,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AAB2",
            },
        [12045622] = {
            ["Content"] = "然后，飏、矩，还有许多有龙氏先人，一起在这个工程内祭献了身躯，用生命让飏的分香术永久固定下来，这就形成了大风九章的根基。",
            ["ContentJP"] = "完成したその場で、ヤンとノリ、そして<Default note=\"text:りゅうのたみ\">龍の民</>の多くの先人たちは、自らの身を供物として捧げたのだ。\
ヤンの操香術をこの地に永遠に刻みつけるために――その命の結晶こそが、「大風九章」の礎となった。",
            ["DialogueId"] = 12045622,
            ["GUID"] = "1E27AADC",
            ["NextDialogue"] = 12045623,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AADC",
            },
        [12045623] = {
            ["Content"] = "传闻中，那个工程的本体就藏在执律阁上方。其中原理以及用到的种种精妙术式，到今天已经失传了。",
            ["ContentJP"] = "噂によれば、その巨大な装置は、<Default note=\"text:しつりつかく\">執律閣</>の最上層に今なお隠されているらしいわ。中\
で用いられていた術式や構造の詳細は、もはや現代では誰にも再現できない。",
            ["DialogueId"] = 12045623,
            ["GUID"] = "1E27AB06",
            ["NextDialogue"] = 12045624,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB06",
            },
        [12045624] = {
            ["Content"] = "要不是那里是常人无法进入的禁地，可真想进去看一看啊……",
            ["ContentJP"] = "もし禁域じゃなかったら……一度でいいからこの目で見てみたいものだけどね。",
            ["DialogueId"] = 12045624,
            ["GUID"] = "1E27AB30",
            ["NextDialogue"] = 12045625,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB30",
            },
        [12045625] = {
            ["Content"] = "飏和矩祭献了生命之后，太皓和烛阴作为他们意志的代行者，一直统领着华胥。他们所创立的悬衡和机枢两派，也携手在治理上出力。",
            ["ContentJP"] = "ヤンとノリが命を捧げたあと、<Default note=\"text:たいこう\">太皓</>と<Default note=\"text:しょくいん\">燭陰</>がその意志を継ぎ、華胥を統べることになったの。\
彼らが創ったのが、後に二大派閥となる「<Default note=\"text:けんこう\">懸衡</>」と「<Default note=\"text:きすう\">機枢</>」だった。",
            ["DialogueId"] = 12045625,
            ["GUID"] = "1E27AB5A",
            ["NextDialogue"] = 12045626,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB5A",
            },
        [12045626] = {
            ["Content"] = "那时候，机枢派的弟子名册每年都是厚厚一大本，研究经费更是要多少有多少，可不用像现在这样紧巴巴地过日子……这或许就是祖上阔过吧。",
            ["ContentJP"] = "その頃の<Default note=\"text:きすうは\">機枢派</>は、今とは比べものにならないほど栄えていて――弟子名簿は毎年厚くなるばかり、研究費も湯水のように使えた。あの頃の贅沢っぷり……まさに「ご先祖様が栄華を極めた証」ってやつね。",
            ["DialogueId"] = 12045626,
            ["GUID"] = "1E27AB84",
            ["NextDialogue"] = 12045627,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AB84",
            },
        [12045627] = {
            ["Content"] = "原来机枢派曾经这么风光——那怎么沦落到现在这种地步了？",
            ["ContentJP"] = "そんなに栄えてたのに、どうして今は……",
            ["DialogueId"] = 12045627,
            ["GUID"] = "1E27ABAE",
            ["NextDialogue"] = 12045628,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ABAE",
            },
        [12045628] = {
            ["Content"] = "苏乙，你刚刚提到了烛阴曾经是受人崇敬的神明，但现在它在大家眼里却是带来祸患的恶龙。机枢派的衰落与这个也有关系吗？",
            ["ContentJP"] = "それと、さっき言ってたけど、<Default note=\"text:しょくいん\">燭陰</>って昔は神として尊ばれてたんだよね？\
それが今では「災いを招く悪龍」に……<Default note=\"text:きすうは\">機枢派</>の没落と何か関係あるの{性别:か|}？",
            ["DialogueId"] = 12045628,
            ["GUID"] = "1E27ABD8",
            ["NextDialogue"] = 12045629,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ABD8",
            },
        [12045629] = {
            ["Content"] = "很敏锐嘛，{nickname}，不愧是你。",
            ["ContentJP"] = "ふふ、鋭いわね、さすが{nickname}だわ。",
            ["DialogueId"] = 12045629,
            ["GUID"] = "1E27AC02",
            ["NextDialogue"] = 12045630,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC02",
            },
        [12045630] = {
            ["Content"] = "黍离之战的剧变后，悬衡派的那些家伙将很多事实都隐瞒了。这个版本的历史，也只有我们这支机枢派的亲传保留了下来。所以接下来也要听好了哦。",
            ["ContentJP"] = "<Default note=\"text:しょりのらん\">黍離の乱</>――あの激動の時代のあと、<Default note=\"text:けんこうは\">懸衡派</>は都合の悪い事実をいくつも隠蔽した。\
今、私が語ってるこの歴史は、私たち<Default note=\"text:きすうは\">機枢派</>の血筋にだけ密かに伝えられてきたものなの。",
            ["DialogueId"] = 12045630,
            ["GUID"] = "1E27AC2C",
            ["NextDialogue"] = 12045631,
            ["RelatedWikiId"] = {
                [1] = 407006,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC2C",
            },
        [12045631] = {
            ["Content"] = "说回上古时期，虽然悬衡和机枢派曾经共同治理华胥，但是双方的理念有所不同。那时候大风九章远不像现在这么死板——甚至人类是可以和神明共治华胥的。",
            ["ContentJP"] = "古の時代、<Default note=\"text:けんこう\">懸衡</>と<Default note=\"text:きすう\">機枢</>はともに華胥を治めていた。\
だけど、その理念には大きな隔たりがあった。当時の大風九章は、今みたいに形骸化してはいなかった。神と人が肩を並べ、共に国を治めることも可能だったのよ。",
            ["DialogueId"] = 12045631,
            ["GUID"] = "1E27AC56",
            ["NextDialogue"] = 12045632,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC56",
            },
        [12045632] = {
            ["Content"] = "我们机枢派认为，应该以心为基准去衡量万物，悬衡派却坚持法不留情的原则，双方在很多案件的判定上有争执。这样日积月累下来，产生了很多摩擦。",
            ["ContentJP"] = "私たち<Default note=\"text:きすうは\">機枢派</>は「心こそすべての尺度」だと信じ、一方で<Default note=\"text:けんこうは\">懸衡派</>は「法に情は不要」と頑なに主張した。\
その考え方の違いは、年月と共にあちこちで衝突を生んでいったの。",
            ["DialogueId"] = 12045632,
            ["GUID"] = "1E27AC80",
            ["NextDialogue"] = 12045633,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AC80",
            },
        [12045633] = {
            ["Content"] = "当时积攒的种种矛盾，在黍离之战时被彻底引燃了。",
            ["ContentJP"] = "そして――その積もり積もった軋轢が、一気に爆発したのが「<Default note=\"text:しょりのらん\">黍離の乱</>」だった。",
            ["DialogueId"] = 12045633,
            ["GUID"] = "1E27ACAA",
            ["NextDialogue"] = 12045634,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACAA",
            },
        [12045634] = {
            ["Content"] = "听鸦原所在的位置，曾经是机枢派的研究重地，却在内战中被彻底付之一炬。",
            ["ContentJP"] = "<Default note=\"text:きすうは\">機枢派</>の研究拠点だった「<Default note=\"text:からすのこげん\">鴉の孤原</>」は戦火に包まれた。そして、すべては炎に焼き尽くされた。",
            ["DialogueId"] = 12045634,
            ["GUID"] = "1E27ACD4",
            ["NextDialogue"] = 12045635,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACD4",
            },
        [12045635] = {
            ["Content"] = "当时的内情谁也不清楚。只知道悬衡派怀疑我们机枢派有叛乱风险，带兵前去探查，最后不知怎的就变成了战争，双方无一生还。",
            ["ContentJP"] = "その原因は、今でも謎のままよ。わかっているのは、<Default note=\"text:けんこうは\">懸衡派</>が「<Default note=\"text:きすうは\">機枢派</>に反乱の兆しあり」として兵を動かし――どういうわけか戦争に発展し、双方全滅という最悪の結果になったということ。",
            ["DialogueId"] = 12045635,
            ["GUID"] = "1E27ACFE",
            ["NextDialogue"] = 12045636,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ACFE",
            },
        [12045636] = {
            ["Content"] = "这个消息传来后，所有人都非常震惊。明明有了为祈愿和平而诞生的大风九章，却依然酿成了如此大的灾祸，这是无论如何也不能允许的。",
            ["ContentJP"] = "人々は衝撃を受けたわ。平和の象徴だったはずの大風九章が、こんな大惨事を引き起こすなんて……そんなこと、絶対にあってはならなかった。",
            ["DialogueId"] = 12045636,
            ["GUID"] = "1E27AD28",
            ["NextDialogue"] = 12045637,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD28",
            },
        [12045637] = {
            ["Content"] = "那时的悬衡派认为失控的愤怒和猜疑让人们割舍了理性，不再遵守秩序，从而引发了这场战争，因此心便是祸患之源。",
            ["ContentJP"] = "<Default note=\"text:けんこうは\">懸衡派</>はその原因を「感情の暴走」や「疑念」と断じ、理性を手放した「心」こそが秩序を壊す元凶だと決めつけた。",
            ["DialogueId"] = 12045637,
            ["GUID"] = "1E27AD52",
            ["NextDialogue"] = 12045638,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD52",
            },
        [12045638] = {
            ["Content"] = "最终他们将机枢派的守护神烛阴封印了起来。也正是从那时开始，大风九章开始失衡，太皓变得一味强调死板的诫律，也不再聆听人类的声音。",
            ["ContentJP"] = "結果――彼らは、<Default note=\"text:きすうは\">機枢派</>の守護神だった<Default note=\"text:しょくいん\">燭陰</>を封印したの。その瞬間から、大風九章はバランスを崩し始めた。<Default note=\"text:たいこう\">太皓</>は融通の利かない律法主義者になり、神は人の声に耳を貸さなくなった。",
            ["DialogueId"] = 12045638,
            ["GUID"] = "1E27AD7C",
            ["NextDialogue"] = 12045639,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AD7C",
            },
        [12045639] = {
            ["Content"] = "机枢派受到打压，很多技术从此成为禁忌。人们还需要匠矩阁的机傀技术帮助生产建设，但却添加了重重限制和偏见。",
            ["ContentJP"] = "<Default note=\"text:きすうは\">機枢派</>は弾圧され、伝統技術は禁忌とされた。それでも、社会に必要とされた技術――たとえば<Default note=\"text:しょうくかく\">匠矩閣</>のからくりの術などは、制限つきで細々と利用され続けたわ。重い偏見と制約のもとでね。",
            ["DialogueId"] = 12045639,
            ["FacialId"] = {
                [1] = "240026:Sad03",
                },
            ["GUID"] = "1E27ADA6",
            ["NextDialogue"] = 12045640,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADA6",
            },
        [12045640] = {
            ["Content"] = "有些机枢派传人不满大风九章的僵化，便单独分家出去，和飘零人一起找到这里作为藏身之处。这就是山外山的前身啦。",
            ["ContentJP"] = "その状況に耐えきれなかった一部の後継者たちは、<Default note=\"text:きすうは\">機枢派</>を離れ、「流れ者」と手を組み、身を隠すようにこの地を築いた。……それが、この「<Default note=\"text:さんがいさん\">山外山</>」の始まりよ。",
            ["DialogueId"] = 12045640,
            ["GUID"] = "1E27ADD0",
            ["NextDialogue"] = 12045641,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADD0",
            },
        [12045641] = {
            ["Content"] = "嗯……事情经过大概就是这些。怎么样，你们还有问题吗？",
            ["ContentJP"] = "ふぅ……だいたいこんなところかしら。どう？ここまでで、何か聞きたいはことはある？",
            ["DialogueId"] = 12045641,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E27ADFA",
            ["NextOptions"] = {
                [1] = 12045642,
                [2] = 12045643,
                [3] = 12045644,
                },
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Sad02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27ADFA",
            },
        [12045642] = {
            ["Content"] = "提到烛阴的回忆。",
            ["ContentJP"] = "燭陰の記憶について。",
            ["DialogueId"] = 12045642,
            ["GUID"] = "1E27AE24",
            ["NextDialogue"] = 12045645,
            },
        [12045643] = {
            ["Content"] = "提到偃隐宫中的卷轴。",
            ["ContentJP"] = "偃隠宮の巻物について。",
            ["DialogueId"] = 12045643,
            ["GUID"] = "1E27AE4E",
            ["NextDialogue"] = 12045647,
            },
        [12045644] = {
            ["Content"] = "没什么想说的。",
            ["ContentJP"] = "特にない。",
            ["DialogueId"] = 12045644,
            ["GUID"] = "1E27AE78",
            ["NextDialogue"] = 12045651,
            },
        [12045645] = {
            ["Content"] = "是吗……原来这些过往历史的碎片，你曾经在烛阴的记忆中看到过。",
            ["ContentJP"] = "……そう。あの歴史の断片を、あなたは<Default note=\"text:しょくいん\">燭陰</>の記憶で見たのね。",
            ["DialogueId"] = 12045645,
            ["GUID"] = "1E27AEA2",
            ["NextDialogue"] = 12045646,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AEA2",
            },
        [12045646] = {
            ["Content"] = "心理失衡，后患无穷……现在这风雨飘摇的现状，或许证明了当初悬衡派的做法过于激进吧。",
            ["ContentJP"] = "心の均衡を失えば、未来にまで禍根を残す……今のこの混迷を見れば、当時の<Default note=\"text:けんこうは\">懸衡派</>のやり方が極端すぎたと証明してるのかもしれない。",
            ["DialogueId"] = 12045646,
            ["GUID"] = "1E27AECC",
            ["NextDialogue"] = 12045651,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AECC",
            },
        [12045647] = {
            ["Content"] = "没错，那位建造偃隐宫的前辈所留下的手记，或许能成为解开黍离之战内情的关键线索。",
            ["ContentJP"] = "ええ、その<Default note=\"text:えんいんきゅう\">偃隠宮</>を築いた先人が遺した手記――あれこそ、<Default note=\"text:しょりのらん\">黍離の乱</>の真相に迫る鍵かもしれない。",
            ["DialogueId"] = 12045647,
            ["GUID"] = "1E27AEF6",
            ["NextDialogue"] = 12045648,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AEF6",
            },
        [12045648] = {
            ["Content"] = "要是如他所说……当时机枢派并没有主动挑起叛乱，在那个大雾弥漫、地磁紊乱的拂晓之中，某具机傀突然失灵了，让双方都以为对面先动了手。",
            ["ContentJP"] = "もし彼の言う通りなら、あのとき<Default note=\"text:きすうは\">機枢派</>は反乱など起こしていなかった。霧が濃く、地磁気が乱れたあの夜明け――突然暴走した一体のからくり人形が、互いを誤解させ、戦争の引き金を引いた。",
            ["DialogueId"] = 12045648,
            ["GUID"] = "1E27AF20",
            ["NextDialogue"] = 12045649,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF20",
            },
        [12045649] = {
            ["Content"] = "数百年的打压和悲剧，竟是这种意外误解带来的。",
            ["ContentJP"] = "それが事実なら、数百年もの弾圧と悲劇が、たったひとつの「誤解」から始まったことになるのよ。",
            ["DialogueId"] = 12045649,
            ["GUID"] = "1E27AF4A",
            ["NextDialogue"] = 12045650,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF4A",
            },
        [12045650] = {
            ["Content"] = "事到如今，这个真相也失去了它本该拥有的意义……心与心之间的矛盾，并非是那么轻易就能弥合的。",
            ["ContentJP"] = "でも……この真実も、もはや本来の意味を失った。心と心の溝は、そんなに簡単には埋まらないのよ。",
            ["DialogueId"] = 12045650,
            ["GUID"] = "1E27AF74",
            ["NextDialogue"] = 12045651,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF74",
            },
        [12045651] = {
            ["Content"] = "呀，不知不觉就讲了这么长时间……总而言之，无论机枢派曾经是风光还是落寞，那都是过去的事情了！",
            ["ContentJP"] = "あら……いつの間にか、随分しゃべっちゃったわね。ま、どれだけ<Default note=\"text:きすうは\">機枢派</>が繁盛してたとしても――あるいは、どれだけ堕ちぶれたとしても――すべて過去のことよ。",
            ["DialogueId"] = 12045651,
            ["GUID"] = "1E27AF9E",
            ["NextDialogue"] = 12045652,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AF9E",
            },
        [12045652] = {
            ["Content"] = "比起那些陈年旧事，还是当下比较重要啦。还有这么多要务得赶紧去处理呢，可不是缅怀往事的时候。",
            ["ContentJP"] = "今は今！まだ片付いてない仕事も山ほどあるんだから、感傷に浸ってる場合じゃないわ。",
            ["DialogueId"] = 12045652,
            ["GUID"] = "1E27AFC8",
            ["NextDialogue"] = 12045653,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AFC8",
            },
        [12045653] = {
            ["Content"] = "你们赶紧忙去吧。要是有什么问题，随时再来问我。本师姐会为你们好好答疑解惑的！",
            ["ContentJP"] = "二人とも早く行きなさい。……なにかあれば、また来なさいな。この大先輩が、答えてあげるから！",
            ["DialogueId"] = 12045653,
            ["GUID"] = "1E27AFF2",
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120456/1E27AFF2",
            },
        [12045701] = {
            ["Content"] = "……{nickname}，你来了啊。",
            ["ContentJP"] = "……{nickname}か。",
            ["DialogueId"] = 12045701,
            ["GUID"] = "1E27B7D2",
            ["NextDialogue"] = 12045702,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B7D2",
            },
        [12045702] = {
            ["Content"] = "本欲来这竹林中练练剑，结果始终找不到手感。想来是我满心杂念，浑身不得劲，连剑老兄也看不过去了。",
            ["ContentJP"] = "この竹林で久しぶりに剣を振ろうと思って来たんだが……どうにも手応えがない。身体が重いというより、心がもつれてる感じでな。剣までそっぽ向いてる気がするんだ。",
            ["DialogueId"] = 12045702,
            ["GUID"] = "1E27B7FC",
            ["NextDialogue"] = 12045703,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B7FC",
            },
        [12045703] = {
            ["Content"] = "刻舟，你还好吗？看你平时总是大咧咧的，没想到也会有这样心事重重的时候。",
            ["ContentJP"] = "大丈夫？カシュウでもそんな風になるんだね。いつもは豪快なイメージだったから、ちょっと意外かも。",
            ["DialogueId"] = 12045703,
            ["GUID"] = "1E27B826",
            ["NextDialogue"] = 12045704,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B826",
            },
        [12045704] = {
            ["Content"] = "……以前看不起别人在深夜多愁善感，没想到风水轮流转，这种不潇洒的事也轮到自己身上了。",
            ["ContentJP"] = "……昔はさ、夜中に悩んでる奴なんて馬鹿にしてたのに……気づけば自分がその側になってるとはな。",
            ["DialogueId"] = 12045704,
            ["GUID"] = "1E27B850",
            ["NextDialogue"] = 12045705,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B850",
            },
        [12045705] = {
            ["Content"] = "我总想起当年的事，那时我也在这儿练剑，先是树枝，然后是木剑，最后才是真正的剑。",
            ["ContentJP"] = "ここで剣の練習をしてたんだ、昔も。最初は枝切れで、次は木刀、そして本物の剣。",
            ["DialogueId"] = 12045705,
            ["GUID"] = "1E27B87A",
            ["NextDialogue"] = 12045706,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B87A",
            },
        [12045706] = {
            ["Content"] = "师兄和不夏就站在你现在站的地方。师兄板着脸指点我招式，不夏就老在那儿上蹿下跳地喝彩，跳得老高。",
            ["ContentJP"] = "あの頃、ユーミンとフウカは、まさにお前が立ってるその辺りにいたんだ。ユーミンは真剣な顔で技を教えて、フウカはその後ろで「すごいすごい！」ってはしゃいで飛び跳ねててさ……",
            ["DialogueId"] = 12045706,
            ["GUID"] = "1E27B8A4",
            ["NextDialogue"] = 12045707,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8A4",
            },
        [12045707] = {
            ["Content"] = "可如今这大好月色，只能照我一个心有郁结的失意人，属实是浪费了。",
            ["ContentJP"] = "でも今は、この綺麗な月明かりすら……悩みしか映さないってのが、やるせないな。",
            ["DialogueId"] = 12045707,
            ["GUID"] = "1E27B8CE",
            ["NextDialogue"] = 12045708,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8CE",
            },
        [12045708] = {
            ["Content"] = "“不夏”……这个名字，煜明白天和你吵架的时候也提到过。她是谁？",
            ["ContentJP"] = "「フウカ」って……昼間、ユーミンとの言い争いでも言ってたよね。彼女は誰な{性别:んだ|の}？",
            ["DialogueId"] = 12045708,
            ["GUID"] = "1E27B8F8",
            ["NextDialogue"] = 12045709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B8F8",
            },
        [12045709] = {
            ["Content"] = "是我和师兄从烟津渡捡来的小师妹，如今已经不在人世了。",
            ["ContentJP"] = "<Default note=\"text:えんしんと\">煙津渡</>で俺とユーミンが拾った子だ。俺たちの妹分……だった。",
            ["DialogueId"] = 12045709,
            ["GUID"] = "1E27B922",
            ["NextDialogue"] = 12045710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B922",
            },
        [12045710] = {
            ["Content"] = "她是因为什么去世的？",
            ["ContentJP"] = "亡くなったの？なぜ？",
            ["DialogueId"] = 12045710,
            ["GUID"] = "1E27B94C",
            ["NextDialogue"] = 12045711,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B94C",
            },
        [12045711] = {
            ["Content"] = "因为“自由”。",
            ["ContentJP"] = "ああ、「自由」が原因でな。",
            ["DialogueId"] = 12045711,
            ["GUID"] = "1E27B976",
            ["NextDialogue"] = 12045712,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B976",
            },
        [12045712] = {
            ["Content"] = "说来可笑吧？我们飘零人终其一生追求的自由无拘，最终害死了她。",
            ["ContentJP"] = "……皮肉なもんだ。俺たち流れ者が、一生かけて求め続けていた自由が、あの子を殺したんだから。",
            ["DialogueId"] = 12045712,
            ["GUID"] = "1E27B9A0",
            ["NextDialogue"] = 12045713,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9A0",
            },
        [12045713] = {
            ["Content"] = "你或许知道，华胥人打从一生下来就活在大风九章的条条框框之中。不许做这，不许做那。不许习武，不许打架，更不许对龙神不敬。",
            ["ContentJP"] = "華胥の民ってのは、生まれた時から全てが大風九章に縛られてる。武術もダメ、喧嘩もダメ……神への無礼なんてもってのほかだ。",
            ["DialogueId"] = 12045713,
            ["GUID"] = "1E27B9CA",
            ["NextDialogue"] = 12045714,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9CA",
            },
        [12045714] = {
            ["Content"] = "那要是想争出一身自由怎么办？就只能想办法跳出这大风九章的重重束缚，这也正是飘零人一直以来追求的目标。",
            ["ContentJP"] = "でも、それを打ち破って「本当の自由」を手に入れたくて……俺たちは抗ってきた。",
            ["DialogueId"] = 12045714,
            ["GUID"] = "1E27B9F4",
            ["NextDialogue"] = 12045715,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27B9F4",
            },
        [12045715] = {
            ["Content"] = "五年前，能将大风九章隔绝在外的天罗拒风仪发明出来了，我们终于做到了！",
            ["ContentJP"] = "そしてついに、5年前――「大風九章」の加護を遮断できる装置、「<Default note=\"text:てんらきょふうぎ\">天羅拒風儀</>」が完成したんだ！",
            ["DialogueId"] = 12045715,
            ["GUID"] = "1E27BA1E",
            ["NextDialogue"] = 12045716,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA1E",
            },
        [12045716] = {
            ["Content"] = "山外山的每个人都高兴得紧，光是庆功宴就连着开了一场又一场。那阵子啊，隔着几米远就能闻到别人衣服上烤肉留下的烟熏味。",
            ["ContentJP"] = "その時の<Default note=\"text:さんがいさん\">山外山</>は、まさにお祭り騒ぎだったよ。祝宴は何日も続いた。数メートル離れてても、服にこびりついた焼き肉の匂いが漂ってくるくらいにな。",
            ["DialogueId"] = 12045716,
            ["GUID"] = "1E27BA48",
            ["NextDialogue"] = 12045717,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA48",
            },
        [12045717] = {
            ["Content"] = "但我们谁都忘了。大风九章不仅仅是惩戒逾矩的家伙，它还有个重要的功能——将秽蚀隔绝于外。",
            ["ContentJP"] = "……でもな。俺たち、忘れてたんだよ。大風九章ってのは、ただ規律を押し付けるものじゃなかった。もう一つ、超重要な役割があったんだ――それが穢蝕の抑制だ。",
            ["DialogueId"] = 12045717,
            ["GUID"] = "1E27BA72",
            ["NextDialogue"] = 12045718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA72",
            },
        [12045718] = {
            ["Content"] = "难道说……？！",
            ["ContentJP"] = "まさか……！！",
            ["DialogueId"] = 12045718,
            ["GUID"] = "1E27BA9C",
            ["NextDialogue"] = 12045719,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BA9C",
            },
        [12045719] = {
            ["Content"] = "……正是你想的那样。",
            ["ContentJP"] = "ああ。あんたの察した通りだ。",
            ["DialogueId"] = 12045719,
            ["GUID"] = "1E27BAC6",
            ["NextDialogue"] = 12045720,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BAC6",
            },
        [12045720] = {
            ["Content"] = "我们过了太久的太平日子，“秽蚀”这个对外国人来说很恐怖的词，在华胥这儿却只存在在古书里。",
            ["ContentJP"] = "俺たちは長い間、穢蝕の脅威から守られていたことに気づかなかった。そんなもの、異国の神話に出てくる化け物くらいにしか思ってなかったさ。",
            ["DialogueId"] = 12045720,
            ["GUID"] = "1E27BAF0",
            ["NextDialogue"] = 12045721,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BAF0",
            },
        [12045721] = {
            ["Content"] = "在大风九章治下，秽蚀者会直接化为狴犴，执行大风九章的意志。但当大风九章被我们隔绝之后，那些怪物……回来了。",
            ["ContentJP"] = "大風九章の加護があった頃――穢蝕者は、即座に「<Default note=\"text:ビーアン\">狴犴</>」へと変貌し、大風九章の意志そのものとなって動いた。だが、俺たちはその加護を遮断した……そのせいで、奴らは戻ってきてしまった。",
            ["DialogueId"] = 12045721,
            ["GUID"] = "1E27BB1A",
            ["NextDialogue"] = 12045722,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB1A",
            },
        [12045722] = {
            ["Content"] = "不夏那时候快要成年了。就在成年的前一天，她变成了可怖的秽兽，袭击了我们的基地。很多人在那场事故中死去了，包括我们的师父。",
            ["ContentJP"] = "ちょうどその頃、フウカは成人を迎えようとしてた。その前夜、突然彼女は「穢獣」に変わったんだ。仲間を襲い、基地は壊滅。多くの命が失われた。……俺たちの師匠も、な。",
            ["DialogueId"] = 12045722,
            ["GUID"] = "1E27BB44",
            ["NextDialogue"] = 12045723,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB44",
            },
        [12045723] = {
            ["Content"] = "她之前嚷嚷着头痛的时候，我们都没当回事，以为只是普通风寒，习武之人的身子骨硬朗，挺过去便是了。只有师兄细心，一人潜进城里药堂买药。",
            ["ContentJP"] = "彼女が「頭が痛い」って言ってたとき、俺たちはただの風邪だと思ってた。剣士の身体は丈夫だし、放っておいても治るって、そんな軽い気持ちでさ。でも、ユーミンだけは違った。一人でこっそり街へ降りて、薬を買ってきてくれたんだ。",
            ["DialogueId"] = 12045723,
            ["GUID"] = "1E27BB6E",
            ["NextDialogue"] = 12045724,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB6E",
            },
        [12045724] = {
            ["Content"] = "师兄让我留下来看住她的情况。我没听。一点城里杂耍班子的消息就把我勾走了。是啊，照看小师妹，哪里有进城看热闹来得有意思。",
            ["ContentJP"] = "俺？俺はその時、街の見世物小屋の噂を聞いて、ふらっと出かけちまった。妹の看病より、外の賑やかさに釣られちまったんだ。",
            ["DialogueId"] = 12045724,
            ["GUID"] = "1E27BB98",
            ["NextDialogue"] = 12045725,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BB98",
            },
        [12045725] = {
            ["Content"] = "最后……怎么样了？",
            ["ContentJP"] = "その後は……どうなった{性别:んだ|の}？",
            ["DialogueId"] = 12045725,
            ["GUID"] = "1E27BBC2",
            ["NextDialogue"] = 12045726,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BBC2",
            },
        [12045726] = {
            ["Content"] = "几个时辰后，我回到山外山，只看到一地血泊……以及站在血泊中的师兄。那让人几欲呕吐的鲜红，我恐怕这辈子都忘不掉了。",
            ["ContentJP"] = "数時間後に戻った俺が見たのは――血の海と、そこに立ち尽くすユーミンだった。あの光景は一生忘れねぇ。",
            ["DialogueId"] = 12045726,
            ["GUID"] = "1E27BBEC",
            ["NextDialogue"] = 12045727,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BBEC",
            },
        [12045727] = {
            ["Content"] = "师兄亲手杀了她——这个我们亲手养大，视为妹妹的孩子。他求来的药洒了一地，和那些血混在一起。",
            ["ContentJP"] = "フウカは俺らにとって、妹のようなもんだった。あいつは、その手であの子を切ったんだ。買ってきた薬も、地面にぶちまけられ、血に染まっていた。",
            ["DialogueId"] = 12045727,
            ["GUID"] = "1E27BC16",
            ["NextDialogue"] = 12045728,
            ["RelatedWikiId"] = {
                [1] = 203011,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC16",
            },
        [12045728] = {
            ["Content"] = "从那之后，师兄几乎再也没有笑过，人也变得更加寡言少语。后来，一个满月的夜晚，师兄独自离开了。再见面时，他已经变成了应天尉。",
            ["ContentJP"] = "それからのユーミンは……笑わなくなった。口数も激減して、ある満月の夜、黙って山外山を出ていった。次に会ったときには、<Default note=\"text:おうてんい\">応天尉</>の装束を纏ってた。",
            ["DialogueId"] = 12045728,
            ["GUID"] = "1E27BC40",
            ["NextDialogue"] = 12045729,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC40",
            },
        [12045729] = {
            ["Content"] = "我不知道他和白龙达成了什么交易，我只知道，那个小时候带着我偷溜出去买桂花糕，会手把手指导我剑术的师兄再也不会回来了。",
            ["ContentJP"] = "きっと白龍と、何らかの取引をしたんだろう。……あの頃のユーミンはどこにもいなかった。一緒に<Default note=\"text:グイホアガオ\">桂花菓子</>を買いに行ってくれたあの人は、剣の構えを教えてくれた兄は――帰ってこなかった。",
            ["DialogueId"] = 12045729,
            ["GUID"] = "1E27BC6A",
            ["NextDialogue"] = 12045730,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC6A",
            },
        [12045730] = {
            ["Content"] = "自那天起，我也再没看过一次杂耍。",
            ["ContentJP"] = "それ以来、一度も見世物小屋には行ってないよ。",
            ["DialogueId"] = 12045730,
            ["GUID"] = "1E27BC94",
            ["NextDialogue"] = 12045731,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BC94",
            },
        [12045731] = {
            ["Content"] = "……其实，师兄说的那些，我全都明白。白天他质问我为何“只破不立”时，我也确实回答不上来。",
            ["ContentJP"] = "ユーミンの昼間の言葉が頭から離れないんだ。壊すばかりで、何も築けない俺に、自由を語る資格があるのか……",
            ["DialogueId"] = 12045731,
            ["GUID"] = "1E27BCBE",
            ["NextDialogue"] = 12045732,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BCBE",
            },
        [12045732] = {
            ["Content"] = "这些年来，我总是懊悔，如果不夏秽蚀发作的那一刻，我和师兄在她身边……该有多好。或者再往前，要是我们没有隔绝大风九章，是不是这一切都不会发生？",
            ["ContentJP"] = "あの時、フウカが穢蝕になりかけていた時、もし俺とユーミンが、そばにいてやれたら、何か変わっていたのか？いや、それ以前に。そもそも俺たちが大風九章を遮断しなければ、あんな悲劇は起きなかったんじゃないか？",
            ["DialogueId"] = 12045732,
            ["GUID"] = "1E27BCE8",
            ["NextDialogue"] = 12045733,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BCE8",
            },
        [12045733] = {
            ["Content"] = "我们为了追求自由，却忽视了与之而来的危险。{nickname}，你说，难道从一开始，我们就做错了吗？",
            ["ContentJP"] = "……俺たちは、「自由」の名のもとに、大事なものを見落としていたんだよ。なあ、{nickname}……俺たちは間違っていたのか？",
            ["DialogueId"] = 12045733,
            ["GUID"] = "1E27BD12",
            ["NextDialogue"] = 12045734,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD12",
            },
        [12045734] = {
            ["Content"] = "……刻舟，我也有很要好的朋友因为秽蚀而去世了，所以我明白你的心情。",
            ["ContentJP"] = "……カシュウ、{性别:僕も穢蝕によって大事な友達を失った。気持ちはわかるよ。|私も穢蝕によって大事な友達を失った。気持ちはわかるわ。}",
            ["DialogueId"] = 12045734,
            ["GUID"] = "1E27BD3C",
            ["NextDialogue"] = 12045735,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD3C",
            },
        [12045735] = {
            ["Content"] = "但是，这件事的根源不在于大风九章，也不在于你们，而是秽蚀的错。所以不要自责。",
            ["ContentJP"] = "でも……これは大風九章やあなたたちのせいではない。悪いのは……穢蝕だよ。だから自分を責め{性别:るな|ないで}。",
            ["DialogueId"] = 12045735,
            ["GUID"] = "1E27BD66",
            ["NextDialogue"] = 12045736,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD66",
            },
        [12045736] = {
            ["Content"] = "就算在大风九章统治的地方，不夏照样会变成无神无志的狴犴，无法和亲人交谈……我想，那也并不算是活着。",
            ["ContentJP"] = "仮にあの時、大風九章が機能してたとしても……フウカは「狴犴」になって、あなたたちの声は届かなくなってた{性别:だろう|でしょう}。それは本当に「生きてる」って言えるのかな？",
            ["DialogueId"] = 12045736,
            ["GUID"] = "1E27BD90",
            ["NextDialogue"] = 12045737,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BD90",
            },
        [12045737] = {
            ["Content"] = "是非对错，往往难以判断……但我唯一可以肯定的是，你想要保护他人的心，绝不是错误的。",
            ["ContentJP"] = "何が正しくて、何が間違ってるかなんて、簡単には決められない――ただ一つだけ確かなのは、誰かを守りたいって思ったその気持ちだけは、絶対に間違ってないよ。",
            ["DialogueId"] = 12045737,
            ["GUID"] = "1E27BDBA",
            ["NextDialogue"] = 12045738,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BDBA",
            },
        [12045738] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12045738,
            ["GUID"] = "1E27BDE4",
            ["NextDialogue"] = 12045739,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BDE4",
            },
        [12045739] = {
            ["Content"] = "我曾经的生活非常简单。在鱼钩挂上饵食就能吸引鱼群，野兔被猎枪打中就会死，一切都遵循着最简单不过的原则。",
            ["ContentJP"] = "……{性别:僕|私}の故郷の暮らしは、とても単純だった。釣り針に餌をつければ魚が食いつく。兎は撃たれれば倒れる。世界は単純な因果で動いてるんだって、そう信じてた。",
            ["DialogueId"] = 12045739,
            ["GUID"] = "1E27BE0E",
            ["NextDialogue"] = 12045740,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE0E",
            },
        [12045740] = {
            ["Content"] = "直到我离开故乡、踏上旅途，我才意识到世界远比我想象得更加复杂，事情也常常会偏离自己的预料。",
            ["ContentJP"] = "でも、旅に出てから気づいたんだ。{性别:世の中は僕が思ってたより、ずっと複雑だってことに。|世の中は私が思ってたより、ずっと複雑だってことにね。}",
            ["DialogueId"] = 12045740,
            ["GUID"] = "1E27BE38",
            ["NextDialogue"] = 12045741,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE38",
            },
        [12045741] = {
            ["Content"] = "我认识一个医生，他一直想拯救人，可他做不到。为了让那些人不至于死得更痛苦，他不得不杀死那些人，最终他也失去了生命。",
            ["ContentJP"] = "知り合いに、一心に人を救おうとする医者がいた。けれどどうしても助けられないときがあって……苦しまないようにと、彼は自らその命を断つしかなかった。結局、彼自身も命を落とした。",
            ["DialogueId"] = 12045741,
            ["GUID"] = "1E27BE62",
            ["NextDialogue"] = 12045742,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE62",
            },
        [12045742] = {
            ["Content"] = "我听说过一个孩子，他只想实现幼时的梦想。可是他为了追逐梦想做出的选择，却让他万劫不复。他失去了人类的身躯，在怪物的躯壳里苟延残喘。",
            ["ContentJP"] = "一心に夢を叶えようとした少年がいた。けどその選択の果てに、人の姿を失い、化け物の殻に囚われたまま生きることになってしまった。",
            ["DialogueId"] = 12045742,
            ["GUID"] = "1E27BE8C",
            ["NextDialogue"] = 12045743,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BE8C",
            },
        [12045743] = {
            ["Content"] = "短短数天，我发现原来命运是这么无常的东西。即使你做出其他选择，结果也未必一定比今天更好。",
            ["ContentJP"] = "ほんの数日間で思い知らされたよ{性别:よ|わ}。運命ってやつは、こんなにも気まぐれで、どう転ぶか分からないものなんだって。別の選択をしたとしても、今より良い結果になるとは限らない。",
            ["DialogueId"] = 12045743,
            ["GUID"] = "1E27BEB6",
            ["NextDialogue"] = 12045744,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BEB6",
            },
        [12045744] = {
            ["Content"] = "所以我想，与其去哀叹无法挽回的过去，不如去做些还来得及的事情。比如，如果秽蚀再度发生，该如何保护这里的人们。",
            ["ContentJP"] = "取り戻せない過去を悔やむより、まだ手を伸ばせる「今」をどう生きるかの方が大事なんじゃないかな。例えば……穢蝕がまた現れたら、どうやって仲間を守るか。考えるべきは、そういうことじゃないかな。",
            ["DialogueId"] = 12045744,
            ["GUID"] = "1E27BEE0",
            ["NextDialogue"] = 12045745,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BEE0",
            },
        [12045745] = {
            ["Content"] = "……但是，唯独不要停下脚步，因为躲在原地是解决不了任何问题的。",
            ["ContentJP"] = "ひとつだけ言えるのは――立ち止まっちゃいけない。どれだけ悔やんでも、そこで止まっていたら何も変わらない。",
            ["DialogueId"] = 12045745,
            ["GUID"] = "1E27BF0A",
            ["NextDialogue"] = 12045746,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF0A",
            },
        [12045746] = {
            ["Content"] = "“不要停下脚步”……",
            ["ContentJP"] = "「立ち止まるな」……か。",
            ["DialogueId"] = 12045746,
            ["GUID"] = "1E27BF34",
            ["NextDialogue"] = 12045747,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF34",
            },
        [12045747] = {
            ["Content"] = "哈哈……是啊。光躲在这里自怨自艾有什么用。往事不可谏，但那来者，我刻舟还得去追上一追。",
            ["ContentJP"] = "……ハハッ、まったくその通りだな。こんなふうにウジウジしてても仕方がない。過去はもう変えられない。けど、これから先に続く道は……まだ俺の足で追いかけられる。",
            ["DialogueId"] = 12045747,
            ["GUID"] = "1E27BF5E",
            ["NextDialogue"] = 12045748,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF5E",
            },
        [12045748] = {
            ["Content"] = "多谢你了……{nickname}。",
            ["ContentJP"] = "ありがとな、{nickname}。",
            ["DialogueId"] = 12045748,
            ["GUID"] = "1E27BF88",
            ["NextDialogue"] = 12045749,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BF88",
            },
        [12045749] = {
            ["Content"] = "好啦，我们出来了这么久，姑奶奶嘴上不说，心中一定着急得很。我们还是赶紧回去商议正事吧，别让她老人家担心了！",
            ["ContentJP"] = "さあ、長話はこれまでだ。あのばばぁ、表では平気な顔してても心配してるに決まってる。急いで戻ろう。",
            ["DialogueId"] = 12045749,
            ["GUID"] = "1E27BFB2",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120457/1E27BFB2",
            },
        [12045801] = {
            ["Content"] = "你们回来啦！",
            ["ContentJP"] = "あっ、お帰り！",
            ["DialogueId"] = 12045801,
            ["GUID"] = "1E27C83A",
            ["NextDialogue"] = 12045802,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203009,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C83A",
            },
        [12045802] = {
            ["Content"] = "怎么都哭丧着脸？不会还在为白天的事发愁吧？没事没事，那么多应天尉呼啦啦一起上，还能守半个时辰，四舍五入不就是咱们和白龙五五开！",
            ["ContentJP"] = "なんだなんだ、その沈んだ顔は？まさかまだ昼間のことを引きずってるんじゃないだろうな？いいっていいって！\
あれだけの<Default note=\"text:おうてんい\">応天尉</>相手に半刻も粘ったんだぞ？ざっくり計算すりゃ、俺たちと白龍は五分五分ってことだ！",
            ["DialogueId"] = 12045802,
            ["GUID"] = "1E27C864",
            ["NextDialogue"] = 12045803,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C864",
            },
        [12045803] = {
            ["Content"] = "谁沮丧了。我可是一直在这儿统计损失，修理机傀，可不像某些人躲去林子里偷偷哭鼻子。",
            ["ContentJP"] = "誰が落ち込んでるって？私はずっとここで損害の確認とからくり人形の修理をしてたの。……竹林に隠れて涙ぐんでた誰かさんと一緒にしないでくれる？",
            ["DialogueId"] = 12045803,
            ["GUID"] = "1E27C88E",
            ["NextDialogue"] = 12045804,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C88E",
            },
        [12045804] = {
            ["Content"] = "倒是你，心情好点了没？可别拖我们的后腿哦。",
            ["ContentJP"] = "で、あなたはどうなの？気持ちの整理はついた？足を引っ張るような真似はしないでよね。",
            ["DialogueId"] = 12045804,
            ["GUID"] = "1E27C8B8",
            ["NextDialogue"] = 12045805,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C8B8",
            },
        [12045805] = {
            ["Content"] = "哈哈，谢姑奶奶关心！",
            ["ContentJP"] = "ははは！ご心配どうも！",
            ["DialogueId"] = 12045805,
            ["GUID"] = "1E27C8E2",
            ["NextDialogue"] = 12045806,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C8E2",
            },
        [12045806] = {
            ["Content"] = "多亏了{nickname}的开解，师兄那个问题我想明白了——谁规定我们就一定要被大风九章保护了？",
            ["ContentJP"] = "{nickname}のおかげで吹っ切れたよ！大風九章に守られなきゃ生きられないって誰が決めたんだ？",
            ["DialogueId"] = 12045806,
            ["GUID"] = "1E27C90C",
            ["NextDialogue"] = 12045807,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C90C",
            },
        [12045807] = {
            ["Content"] = "我刻舟一人除不完秽蚀。若是十人、百人联手起来，大家都拿起武器，众志成城，还怕打不过一两个秽蚀者？",
            ["ContentJP"] = "確かに、俺一人じゃ穢蝕を斬り尽くせない。けど十人、百人で力を合わせたらどうだ？皆で武器を取って立ち向かえば、たかが一、二体の穢蝕者に負けるはずがない！",
            ["DialogueId"] = 12045807,
            ["GUID"] = "1E27C936",
            ["NextDialogue"] = 12045808,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C936",
            },
        [12045808] = {
            ["Content"] = "事在人为。先前输止流两招，下一局，我们就一举把赢面扳回来。不管她在谋划什么，只要干脆利落地统统打破就可以！",
            ["ContentJP"] = "勝敗なんて人の手で決まるものだ。昼間はシリュウに一手を取られたけど……次こそ全部ひっくり返してやる！奴が何を企んでようと関係ねぇ、叩き壊しゃいいだけだ！",
            ["DialogueId"] = 12045808,
            ["GUID"] = "1E27C960",
            ["NextDialogue"] = 12045809,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C960",
            },
        [12045809] = {
            ["Content"] = "气势不错，但光有气势可不行。那么，商量一下接下来的计划吧。",
            ["ContentJP"] = "気合は悪くないけど、それだけじゃ足りないわ。これからの動きを話し合いましょう。",
            ["DialogueId"] = 12045809,
            ["GUID"] = "1E27C98A",
            ["NextDialogue"] = 12045810,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C98A",
            },
        [12045810] = {
            ["Content"] = "我想，山外山如今要做的是协助{nickname}，等{性别：他|她}解开止流的第三卦再做打算。对了，扶疏姑娘那边……",
            ["ContentJP"] = "山外山が今すべきは、{nickname}の手助けをすることだと思う。シリュウの第三の予言を解くまで、軽率に動くわけにはいかない。それから、フーシュさんの方は……",
            ["DialogueId"] = 12045810,
            ["GUID"] = "1E27C9B4",
            ["NextDialogue"] = 12045811,
            ["RelatedWikiId"] = {
                [1] = 401005,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C9B4",
            },
        [12045811] = {
            ["Content"] = "我已经寻访到了无穷藏派传人隐居的地方，就在皓京西郊的椒兰村。",
            ["ContentJP"] = "はい。<Default note=\"text:むきゅうぞうは\">無窮蔵派</>の末裔が身を隠している場所を突き止めました。\
<Default note=\"text:こうけい\">皓京</>の西郊外にある――<Default note=\"text:しょうらんむら\">椒蘭村</>です。",
            ["DialogueId"] = 12045811,
            ["GUID"] = "1E27C9DE",
            ["NextDialogue"] = 12045812,
            ["RelatedWikiId"] = {
                [1] = 408020,
                [2] = 407014,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27C9DE",
            },
        [12045812] = {
            ["Content"] = "椒兰村？巧了，这里恰好有一位“本地向导”可以为你们带路。",
            ["ContentJP"] = "椒蘭村……ちょうど「案内役」がここにいるじゃない。",
            ["DialogueId"] = 12045812,
            ["GUID"] = "1E27CA08",
            ["NextDialogue"] = 12045813,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA08",
            },
        [12045813] = {
            ["Content"] = "哎？难不成这个地方就是刻舟你的老家？",
            ["ContentJP"] = "え？まさか……カシュウの故郷！？",
            ["DialogueId"] = 12045813,
            ["GUID"] = "1E27CA32",
            ["NextDialogue"] = 12045814,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA32",
            },
        [12045814] = {
            ["Content"] = "许久没回去了，没想到却是以这样的理由。哈哈，也好！是时候故地重游了！",
            ["ContentJP"] = "ああ、ずっと帰ってなかったが……こんな形で戻るとはな。フッ、いいだろう。たまには里帰りってのも悪くない！",
            ["DialogueId"] = 12045814,
            ["GUID"] = "1E27CA5C",
            ["NextDialogue"] = 12045815,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA5C",
            },
        [12045815] = {
            ["Content"] = "根据线报，自从执律阁震动之后，原本追捕你们的应天尉已经全线回撤。如今你们回去不会引起太多注意，正是潜入调查的好时机。",
            ["ContentJP"] = "ちょうどいいことに、<Default note=\"text:しつりつかく\">執律閣</>の騒動の後、<Default note=\"text:おうてんい\">応天尉</>たちは追撃をやめて全線撤退したわ。\
今なら目立たず潜り込める。調査には絶好の機会よ。",
            ["DialogueId"] = 12045815,
            ["GUID"] = "1E27CA86",
            ["NextDialogue"] = 12045816,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CA86",
            },
        [12045816] = {
            ["Content"] = "好。待你们准备好了，我们就走吧。",
            ["ContentJP"] = "よし！準備が整い次第、すぐに出発だ！",
            ["DialogueId"] = 12045816,
            ["GUID"] = "1E27CAB0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120458/1E27CAB0",
            },
        [12045901] = {
            ["Content"] = "小朋友，你知道村庄中关于“无穷藏派”的传闻吗？",
            ["ContentJP"] = "こんにちは、「無窮蔵派」について、何か知ってる？",
            ["DialogueId"] = 12045901,
            ["GUID"] = "1E27D8A2",
            ["NextDialogue"] = 12045902,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8A2",
            },
        [12045902] = {
            ["Content"] = "虎子不太清楚……",
            ["ContentJP"] = "聞いたことないな……",
            ["DialogueId"] = 12045902,
            ["GUID"] = "1E27D8CC",
            ["NextDialogue"] = 12045903,
            ["SpeakNpcId"] = 240037,
            ["TalkActionId"] = {
                [1] = "240037:Shy03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8CC",
            },
        [12045903] = {
            ["Content"] = "对了，阿爸说过，不能和陌生人说话！你们是陌生人吗？",
            ["ContentJP"] = "あ、父ちゃんが知らない人とは話すなって言ってた！お前たち、知らない人か？",
            ["DialogueId"] = 12045903,
            ["GUID"] = "1E27D8F6",
            ["NextDialogue"] = 12045904,
            ["SpeakNpcId"] = 240037,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D8F6",
            },
        [12045904] = {
            ["Content"] = "哈哈，我们已经说过两句话，就是朋友，不能算陌生人了。",
            ["ContentJP"] = "ははは、もう言葉を交わしたんだから、知らない人じゃないだろう？",
            ["DialogueId"] = 12045904,
            ["GUID"] = "1E27D920",
            ["NextDialogue"] = 12045905,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D920",
            },
        [12045905] = {
            ["Content"] = "对了，小朋友，你的阿爸现在在哪儿？",
            ["ContentJP"] = "そうだ、お前の父さんはどこにいるんだ？",
            ["DialogueId"] = 12045905,
            ["GUID"] = "1E27D94A",
            ["NextDialogue"] = 12045906,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D94A",
            },
        [12045906] = {
            ["Content"] = "阿爸不在家，早上就出去砍柴啦。如果有什么问题，问我阿娘吧，她就在对面那儿晒香呢！",
            ["ContentJP"] = "うーんとね、朝早くから山に薪を取りに行ったんだ。何か聞きたいことがあるなら、向かいで香草を干してる母ちゃんに聞いて！",
            ["DialogueId"] = 12045906,
            ["GUID"] = "1E27D974",
            ["SpeakNpcId"] = 240037,
            ["VoiceName"] = "voice/$Locale$/story/1204/120459/1E27D974",
            },
        [12046001] = {
            ["Content"] = "请问，您对村中隐居的无穷藏派有所了解吗？",
            ["ContentJP"] = "すみません、この村に無窮蔵派が隠れ住んでると聞いたのですが……",
            ["DialogueId"] = 12046001,
            ["GUID"] = "1E27E90A",
            ["NextDialogue"] = 12046002,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E90A",
            },
        [12046002] = {
            ["Content"] = "无穷藏派？有些陌生……若说到能教经纶数算的先生，倒还能想起一二。",
            ["ContentJP"] = "むきゅうぞうは？聞かないわね……経書や算術を教えてくれる先生なら、何人か思い当たるけど。",
            ["DialogueId"] = 12046002,
            ["FacialId"] = {
                [1] = "240038:Cin_Think",
                },
            ["GUID"] = "1E27E934",
            ["NextDialogue"] = 12046003,
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E934",
            },
        [12046003] = {
            ["Content"] = "这些人精通卜算奇门之术，也就是说热爱捣鼓铜钱、龟壳这些玩意儿。这样说，能让你想起点什么吗？",
            ["ContentJP"] = "そうそう。易占や奇門の術に長けていて、銅銭や亀の甲羅で占いをするのが好きな連中だ。……どうだ、心当たりは？",
            ["DialogueId"] = 12046003,
            ["GUID"] = "1E27E95E",
            ["NextDialogue"] = 12046004,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240038:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E95E",
            },
        [12046004] = {
            ["Content"] = "……刻舟，怎么是你？！",
            ["ContentJP"] = "カシュウ！？なんであんたがここに！",
            ["DialogueId"] = 12046004,
            ["FacialId"] = {
                [1] = "240038:Cin_Angry01",
                },
            ["GUID"] = "1E27E988",
            ["NextDialogue"] = 12046005,
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E988",
            },
        [12046005] = {
            ["Content"] = "啊，咳，是啊……香芸姐。那个，你们身体可还好？一别数年，孩子都这么高了——",
            ["ContentJP"] = "あ……ゴホン、コウエンさんか。いやぁ、久しぶりだな。子どもも随分大きくなって――",
            ["DialogueId"] = 12046005,
            ["GUID"] = "1E27E9B2",
            ["NextDialogue"] = 12046006,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E9B2",
            },
        [12046006] = {
            ["Content"] = "虎子，不许在外面玩了，赶紧回家做功课去！小心沾染上什么不三不四的人。",
            ["ContentJP"] = "トラ！さっさと中に入って宿題をやりなさい！こんな怪しい人たちに関わるんじゃありません！",
            ["DialogueId"] = 12046006,
            ["GUID"] = "1E27E9DC",
            ["NextDialogue"] = 12046007,
            ["SpeakNpcId"] = 240038,
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27E9DC",
            },
        [12046007] = {
            ["Content"] = "恕我无话与各位可说。<H>罪人之后</>还是赶紧请回吧，可别把晦气带来村子了。",
            ["ContentJP"] = "悪いけど、話すことなんてないわ。<H>罪人の子</>が村にいると、不運を招きかねない。さっさと出てってちょうだい。",
            ["DialogueId"] = 12046007,
            ["GUID"] = "1E27EA06",
            ["SpeakNpcId"] = 240038,
            ["TalkActionId"] = {
                [1] = "240038:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120460/1E27EA06",
            },
        [12046101] = {
            ["Content"] = "李阿伯，我回来了。向你打听一件事可好？",
            ["ContentJP"] = "リーさん、ただいま。少し尋ねたいことがあるんだが……",
            ["DialogueId"] = 12046101,
            ["GUID"] = "1E27F972",
            ["NextDialogue"] = 12046102,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F972",
            },
        [12046102] = {
            ["Content"] = "……你是，刻舟……你长高了，也壮实了……",
            ["ContentJP"] = "……お前は……カシュウか？随分立派になったなぁ。背も伸びた。",
            ["DialogueId"] = 12046102,
            ["FacialId"] = {
                [1] = "240039:CM_Happy01",
                },
            ["GUID"] = "1E27F99C",
            ["NextDialogue"] = 12046103,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F99C",
            },
        [12046103] = {
            ["Content"] = "时隔十几年，你终于愿意回村看看了……",
            ["ContentJP"] = "十数年ぶりか……やっと村に戻ってきてくれたのか。",
            ["DialogueId"] = 12046103,
            ["GUID"] = "1E27F9C6",
            ["NextDialogue"] = 12046104,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F9C6",
            },
        [12046104] = {
            ["Content"] = "我想向您打听个人。放心，我只是帮朋友个忙，问完就走，一刻钟都不多留。",
            ["ContentJP"] = "ええ。ただ友人に頼まれ、人を探しに来ただけだ。用が済んだらすぐに立ち去るよ。",
            ["DialogueId"] = 12046104,
            ["GUID"] = "1E27F9F0",
            ["NextDialogue"] = 12046105,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27F9F0",
            },
        [12046105] = {
            ["Content"] = "唉，我不是这个意思……算了，你问吧。",
            ["ContentJP"] = "そういう意味じゃ……まあいい。言ってみなさい。",
            ["DialogueId"] = 12046105,
            ["FacialId"] = {
                [1] = "240039:CM_Sad01",
                },
            ["GUID"] = "1E27FA1A",
            ["NextDialogue"] = 12046106,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA1A",
            },
        [12046106] = {
            ["Content"] = "您知道有位无穷藏派高人在村里隐居吗？",
            ["ContentJP"] = "<Default note=\"text:むきゅうぞうは\">無窮蔵派</>の者がこの村にいると聞いたんだが、何か知らないか？",
            ["DialogueId"] = 12046106,
            ["GUID"] = "1E27FA44",
            ["NextDialogue"] = 12046107,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA44",
            },
        [12046107] = {
            ["Content"] = "你是说<H>静渊居士</>？断桥对面，崖边那处屋舍便是。",
            ["ContentJP"] = "<H>静淵</>殿のことか？だったら断橋を渡った先の、崖っぷちにある小屋に住んでおる。",
            ["DialogueId"] = 12046107,
            ["FacialId"] = {
                [1] = "240039:CM_Idle",
                },
            ["GUID"] = "1E27FA6E",
            ["NextDialogue"] = 12046108,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA6E",
            },
        [12046108] = {
            ["Content"] = "哦！原来就是我以前总是绕着走的那块地儿！",
            ["ContentJP"] = "なるほど！あそこは俺が唯一近寄らなかった場所だ。",
            ["DialogueId"] = 12046108,
            ["GUID"] = "1E27FA98",
            ["NextDialogue"] = 12046109,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240039:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FA98",
            },
        [12046109] = {
            ["Content"] = "我小时候到处上墙揭瓦，村里全都被我倒腾了个遍，每块石头在哪儿我都记得。唯有那里，我每次跑去，就迷迷瞪瞪，不知怎的就发现自己倒栽在树桩旁。",
            ["ContentJP"] = "ガキの頃は、村中の塀によじ登ったり瓦を剥がしたり、もう隅から隅までひっくり返して遊んでた。どの石がどこにあるかだって全部覚えてる。……\
けど、あそこだけは違った。行くたびに頭がぼんやりして、気がつくと決まって切り株にひっくり返って倒れてたんだよな。",
            ["DialogueId"] = 12046109,
            ["GUID"] = "1E27FAC2",
            ["NextDialogue"] = 12046110,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FAC2",
            },
        [12046110] = {
            ["Content"] = "若那是无穷藏派的地界，一切都说得通了！谢啦，伯伯。那我们就先告辞了——",
            ["ContentJP"] = "なるほど……もしあそこが<Default note=\"text:むきゅうぞうは\">無窮蔵派</>の縄張りだったってんなら、全部つじつまが合う！ありがとよ、爺さん。俺たちはこれで失礼するぜ――",
            ["DialogueId"] = 12046110,
            ["GUID"] = "1E27FAEC",
            ["NextDialogue"] = 12046111,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FAEC",
            },
        [12046111] = {
            ["Content"] = "……刻舟，稍等片刻。",
            ["ContentJP"] = "……ちょいと待て。",
            ["DialogueId"] = 12046111,
            ["GUID"] = "1E27FB16",
            ["NextDialogue"] = 12046112,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB16",
            },
        [12046112] = {
            ["Content"] = "嗯？怎么了，阿伯？",
            ["ContentJP"] = "ん？まだ何か？",
            ["DialogueId"] = 12046112,
            ["GUID"] = "1E27FB40",
            ["NextDialogue"] = 12046113,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB40",
            },
        [12046113] = {
            ["Content"] = "当初赶走你们，我自觉亏欠。这些年来，你过得可还好？",
            ["ContentJP"] = "あの時、お前たちを追い出す形になってしまったこと……今でも後悔してるんだ。ここ数十年、元気だったか？",
            ["DialogueId"] = 12046113,
            ["GUID"] = "1E27FB6A",
            ["NextDialogue"] = 12046114,
            ["SpeakNpcId"] = 240039,
            ["TalkActionId"] = {
                [1] = "240039:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB6A",
            },
        [12046114] = {
            ["Content"] = "嗨呀，您千万别放在心上。我现在活得好好的，吃好喝好，逍遥自在。我爹心宽，也绝不会念你。",
            ["ContentJP"] = "あー気にすんなって。ピンピンしてるから。うまいもん食って、のんびりやってる。親父だって気にしちゃいねぇさ。",
            ["DialogueId"] = 12046114,
            ["GUID"] = "1E27FB94",
            ["NextDialogue"] = 12046115,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FB94",
            },
        [12046115] = {
            ["Content"] = "……唉。你爹他从始至终都是个好人。",
            ["ContentJP"] = "……お前の親父さんは、最期まで立派な人だった。",
            ["DialogueId"] = 12046115,
            ["FacialId"] = {
                [1] = "240039:CM_Sad01",
                },
            ["GUID"] = "1E27FBBE",
            ["NextDialogue"] = 12046116,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FBBE",
            },
        [12046116] = {
            ["Content"] = "可惜，可惜了。也怨我那时候没有站出来为你们说话……",
            ["ContentJP"] = "もったいないことをした。あの時、わしが一声でも上げていれば……",
            ["DialogueId"] = 12046116,
            ["GUID"] = "1E27FBE8",
            ["NextDialogue"] = 12046117,
            ["SpeakNpcId"] = 240039,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FBE8",
            },
        [12046117] = {
            ["Content"] = "别，您可千万别自责啊！我们家当初出事，您为我们送水送食，上下打点。我和我娘对您从来没有一分怨言。",
            ["ContentJP"] = "やめてくれって、爺さんがそんなんじゃ、うちの親父とお袋が報われねえよ。あの時、あんたは毎日飯や水を運んでくれたじゃねえか。それで十分さ。",
            ["DialogueId"] = 12046117,
            ["GUID"] = "1E27FC12",
            ["NextDialogue"] = 12046118,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC12",
            },
        [12046118] = {
            ["Content"] = "总是想那些过去的事情，会折寿的。您老可要放宽心，争取活到一百岁。到时候，我再来给您贺寿！",
            ["ContentJP"] = "昔のことばかり思い返してちゃ、寿命が縮むぞ。長生きしてくれよ！百歳の時には、俺が盛大に祝いに来るからさ。",
            ["DialogueId"] = 12046118,
            ["GUID"] = "1E27FC3C",
            ["NextDialogue"] = 12046119,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC3C",
            },
        [12046119] = {
            ["Content"] = "这次真得走啦，以后再来找您叙旧。希望下次见到您，您还能这么精神矍铄。",
            ["ContentJP"] = "じゃ、もう行くよ。また改めて遊びにくる。そのときも元気な姿、見せてくれよな。",
            ["DialogueId"] = 12046119,
            ["GUID"] = "1E27FC66",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120461/1E27FC66",
            },
        [12046201] = {
            ["Content"] = "……你们终于来了。",
            ["ContentJP"] = "……やっと来たか。",
            ["DialogueId"] = 12046201,
            ["GUID"] = "1E2809DA",
            ["NextDialogue"] = 12046202,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E2809DA",
            },
        [12046202] = {
            ["Content"] = "今日自旭日初升，我便候在这棵梧桐树下，等着诸位的到访。",
            ["ContentJP"] = "本日、朝日が昇ったときから、ずっとこの青桐の下でお前たちを待っていた。",
            ["DialogueId"] = 12046202,
            ["GUID"] = "1E280A04",
            ["NextDialogue"] = 12046203,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A04",
            },
        [12046203] = {
            ["Content"] = "您早已知道我们要来？",
            ["ContentJP"] = "え……{性别:僕たちが来るって分かってたのか？|私たちが来るって分かってたの？}",
            ["DialogueId"] = 12046203,
            ["GUID"] = "1E280A2E",
            ["NextDialogue"] = 12046204,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A2E",
            },
        [12046204] = {
            ["Content"] = "无穷藏派自诩以卜算奇门之术窥测天命。虽凭凡人之身，妄言未来，终为枉然。但这无伤大雅的预测还未曾失了准头。",
            ["ContentJP"] = "<Default note=\"text:むきゅうぞうは\">無窮蔵派</>は易占と奇門の術で天命を読み取る。\
凡人の身で未来を語るのは分不相応かもしれんが……私の予測は、外れたことがない。",
            ["DialogueId"] = 12046204,
            ["GUID"] = "1E280A58",
            ["NextDialogue"] = 12046205,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A58",
            },
        [12046205] = {
            ["Content"] = "却未自我介绍。我是本代掌门，号静渊居士，我那逆徒止流承蒙你们照顾了。",
            ["ContentJP"] = "名乗っていなかったね。私はこの代の掌門、「静淵」だ。うちの弟子――シリュウが世話になったね。",
            ["DialogueId"] = 12046205,
            ["GUID"] = "1E280A82",
            ["NextDialogue"] = 12046206,
            ["RelatedWikiId"] = {
                [1] = 203012,
                [2] = 203001,
                [3] = 407014,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280A82",
            },
        [12046206] = {
            ["Content"] = "你说自己什么都能猜到，那让白考考你！你猜到我们此行的目的了吗？",
            ["ContentJP"] = "ふーん、じゃあさ、スノウたちの旅の目的も分かってるわけ？",
            ["DialogueId"] = 12046206,
            ["GUID"] = "1E280AAC",
            ["NextDialogue"] = 12046207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280AAC",
            },
        [12046207] = {
            ["Content"] = "呵呵，放心。这位小友所中的迷卦，我随后就为你们化解。届时{性别：他|她}被遮蔽的记忆也将悉数复原。",
            ["ContentJP"] = "ええ、もちろん。その子にかけられた迷卦の術――私が解いてやろう。記憶も、すべて取り戻せるでしょう。",
            ["DialogueId"] = 12046207,
            ["GUID"] = "1E280AD6",
            ["NextDialogue"] = 12046208,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280AD6",
            },
        [12046208] = {
            ["Content"] = "但在那之前，可否赏光，先听一则故事呢？",
            ["ContentJP"] = "だが、その前に――一つ、話を聞いてもらおう。",
            ["DialogueId"] = 12046208,
            ["GUID"] = "1E280B00",
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120462/1E280B00",
            },
        [12046301] = {
            ["Content"] = "您故事中的那个小女孩……就是止流吗？",
            ["ContentJP"] = "さっきの話に出てきたあの少女って……もしかして、シリュウさんですか？",
            ["DialogueId"] = 12046301,
            ["GUID"] = "1E281A42",
            ["NextDialogue"] = 12046302,
            ["RelatedWikiId"] = {
                [1] = 203012,
                [2] = 203001,
                [3] = 203007,
                [4] = 407014,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A42",
            },
        [12046302] = {
            ["Content"] = "正是。",
            ["ContentJP"] = "そうだ。",
            ["DialogueId"] = 12046302,
            ["GUID"] = "1E281A6C",
            ["NextDialogue"] = 12046303,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A6C",
            },
        [12046303] = {
            ["Content"] = "……原来老爹救下的那个小女孩，从来没有忘掉过这件事情。",
            ["ContentJP"] = "……親父が助けたあの子が、ずっとあの件を忘れずにいたなんて。",
            ["DialogueId"] = 12046303,
            ["GUID"] = "1E281A96",
            ["NextDialogue"] = 12046304,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281A96",
            },
        [12046304] = {
            ["Content"] = "老爹若是知道他当年的见义勇为，会在十几年后掀起这么大的风波，恐怕在虞渊之底都会吓一大跳吧。",
            ["ContentJP"] = "もし父さんが聞いたら、きっとびっくりしてるだろうな。虞淵の底から飛び起きるんじゃないか？",
            ["DialogueId"] = 12046304,
            ["GUID"] = "1E281AC0",
            ["NextDialogue"] = 12046305,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281AC0",
            },
        [12046305] = {
            ["Content"] = "我已出世。徒弟的是非对错，我无意评判。",
            ["ContentJP"] = "私は俗世から脱した者で、弟子のことに口を挟むつもりはない。善悪の判断も、お前たちに任せる。",
            ["DialogueId"] = 12046305,
            ["GUID"] = "1E281AEA",
            ["NextDialogue"] = 12046306,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281AEA",
            },
        [12046306] = {
            ["Content"] = "{nickname}，我可为你解开你身上的迷卦。等你准备好，就与我说吧。",
            ["ContentJP"] = "{nickname}、お前の身にかかっている迷卦――解く準備ができたら、声をかけて。",
            ["DialogueId"] = 12046306,
            ["GUID"] = "1E281B14",
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120463/1E281B14",
            },
        [12046401] = {
            ["Content"] = "{nickname}，很抱歉把你卷入了这一切。",
            ["ContentJP"] = "{nickname}、巻き込んでごめんなさい。",
            ["DialogueId"] = 12046401,
            ["GUID"] = "1E282AAA",
            ["NextDialogue"] = 12046402,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 401005,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AAA",
            },
        [12046402] = {
            ["Content"] = "现在再说抱歉，是不是有点晚了？",
            ["ContentJP"] = "今更謝っても、遅すぎるんじゃない？",
            ["DialogueId"] = 12046402,
            ["GUID"] = "1E282AD4",
            ["NextDialogue"] = 12046403,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AD4",
            },
        [12046403] = {
            ["Content"] = "呵呵……说的也是呢。我并没有留给你选择的机会。",
            ["ContentJP"] = "ふふ……確かにね。そもそもあなたに選択肢なんて与えなかったから。",
            ["DialogueId"] = 12046403,
            ["GUID"] = "1E282AFE",
            ["NextDialogue"] = 12046404,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282AFE",
            },
        [12046404] = {
            ["Content"] = "我必须承认，从发现你的能力开始，我便谋划着如何将你带回华胥，让这份力量成为我的助力。",
            ["ContentJP"] = "正直に言うわ。あなたの力に気づいたときから、どうやって華胥に連れて帰るか、そればかり考えてた。その力を、私の目的のために使おうとしてた。",
            ["DialogueId"] = 12046404,
            ["GUID"] = "1E282B28",
            ["NextDialogue"] = 12046405,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B28",
            },
        [12046405] = {
            ["Content"] = "怀璧其罪。你有着这份奇异的和鸣之力，便注定与平凡的命运无缘。敌人接踵而至，夹道荆棘丛生，你接下来的路，一定走得很艰难。",
            ["ContentJP"] = "――力ある者は、その力ゆえに罪を招く。あなたの「レゾナンス」も例外じゃない。敵が後を絶たず、茨だらけの道を歩むことになるでしょう。",
            ["DialogueId"] = 12046405,
            ["GUID"] = "1E282B52",
            ["NextDialogue"] = 12046406,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B52",
            },
        [12046406] = {
            ["Content"] = "那是我要面对的事情，与你无关。",
            ["ContentJP"] = "{性别:それは僕の選択だ。あなたには関係ない。|それは私の選択よ。あなたには関係ない。}",
            ["DialogueId"] = 12046406,
            ["GUID"] = "1E282B7C",
            ["NextDialogue"] = 12046407,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282B7C",
            },
        [12046407] = {
            ["Content"] = "我并非想故意为难你，恰恰相反，我是在允诺你一份报酬。",
            ["ContentJP"] = "……あなたを苦しめたいわけじゃないわ。むしろ、これは報酬のつもりよ。",
            ["DialogueId"] = 12046407,
            ["GUID"] = "1E282BA6",
            ["NextDialogue"] = 12046408,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BA6",
            },
        [12046408] = {
            ["Content"] = "憎恨我吗？认为我惺惺作态吗？",
            ["ContentJP"] = "……私を恨んでる？それとも、芝居じみた偽善だと思ってるかしら？",
            ["DialogueId"] = 12046408,
            ["GUID"] = "1E282BD0",
            ["NextDialogue"] = 12046409,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BD0",
            },
        [12046409] = {
            ["Content"] = "怎样都好……我只希望，接下来的这起卦象可以成为对你的部分补偿。",
            ["ContentJP"] = "どうでもいいわ。ただ願うのは――これから解き明かす卦象が、ほんの少しでもあなたへの償いになれば、ってことだけ。",
            ["DialogueId"] = 12046409,
            ["GUID"] = "1E282BFA",
            ["NextDialogue"] = 12046410,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282BFA",
            },
        [12046410] = {
            ["Content"] = "第三起，革之明夷。大人虎变，晦若坠星，陵悬于虚，辰宿易主。",
            ["ContentJP"] = "三つ目――『<Default note=\"text:かくのめいい\">革の明夷</>』。世は大きく姿を変え、強き者は猛虎となる。\
光は墜ちる星のように翳り、天の陵は虚空に漂い、星々の座は主を失う。秩序は揺らぎ、新たな運命がその座に就くであろう。",
            ["DialogueId"] = 12046410,
            ["GUID"] = "1E282C24",
            ["NextDialogue"] = 12046411,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C24",
            },
        [12046411] = {
            ["Content"] = "大风九章的中枢，其名为太虚陵，高悬于执律阁上方的穹顶之中。那里是一切之始。",
            ["ContentJP"] = "大風九章の中枢――<Default note=\"text:たいきょりょう\">太虚陵</>。<Default note=\"text:しつりつかく\">執律閣</>のさらに上、天空の穹頂に掲げられた聖域。すべての源がそこにある。",
            ["DialogueId"] = 12046411,
            ["GUID"] = "1E282C4E",
            ["NextDialogue"] = 12046412,
            ["RelatedWikiId"] = {
                [1] = 408021,
                },
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C4E",
            },
        [12046412] = {
            ["Content"] = "弑神并非易事……凡人之力，岂可窥伺神明？",
            ["ContentJP"] = "けれど、神を討つなんて断じて容易じゃない。",
            ["DialogueId"] = 12046412,
            ["GUID"] = "1E282C78",
            ["NextDialogue"] = 12046413,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282C78",
            },
        [12046413] = {
            ["Content"] = "即便太皓已被种种手段削弱，其力生生不息，与凡人之别，仍不啻天渊。能杀死神明的，唯有神明。",
            ["ContentJP"] = "いくら弱体化しても、人ごときで神に挑めるはずがないわ。神を屠れるのは、神だけ。",
            ["DialogueId"] = 12046413,
            ["GUID"] = "1E282CA2",
            ["NextDialogue"] = 12046414,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CA2",
            },
        [12046414] = {
            ["Content"] = "因此，当初在祭坛之上，我必须与烛阴缔结同生共死的契约。此棋不容有失。",
            ["ContentJP"] = "だから私は、祭壇の上で<Default note=\"text:しょくいん\">燭陰</>と契った。生死を共にする契約をね。この一手だけは、どうしても欠かせなかった。",
            ["DialogueId"] = 12046414,
            ["GUID"] = "1E282CCC",
            ["NextDialogue"] = 12046415,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CCC",
            },
        [12046415] = {
            ["Content"] = "魂契是亘古传下的几大术式其一。龙渊上卿的力量本为大风九章所授予，借助这点，我能成为承载魂契的容器，我的生命也从此与烛阴相连。",
            ["ContentJP"] = "魂の契――古くから伝わる禁術のひとつ。龍淵の上卿に授けられた力を媒介に、私は器となり、己の命を燭陰に繋ぎ止めたの。",
            ["DialogueId"] = 12046415,
            ["GUID"] = "1E282CF6",
            ["NextDialogue"] = 12046416,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282CF6",
            },
        [12046416] = {
            ["Content"] = "烛阴久经封印，其力已衰。下一步，我将在天人陵墓之巅，燃烧己身性命，作为烛阴的祭牲，增幅其力量。",
            ["ContentJP"] = "長い封印で<Default note=\"text:しょくいん\">燭陰</>の力は既に衰えていた。だからこそ、次の一手は決まっていたの。天人陵墓の頂にて、この身を炎とし、燭陰を強めるための生贄となるわ。",
            ["DialogueId"] = 12046416,
            ["GUID"] = "1E282D20",
            ["NextDialogue"] = 12046417,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D20",
            },
        [12046417] = {
            ["Content"] = "使烛阴归于巢，自相残杀，双龙同归于尽。这便是我能算出的解法。",
            ["ContentJP"] = "そして、巣へ戻った龍神同士は相討ちとなり、滅びを迎える。……それが私の描いた結末よ。",
            ["DialogueId"] = 12046417,
            ["GUID"] = "1E282D4A",
            ["NextDialogue"] = 12046418,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D4A",
            },
        [12046418] = {
            ["Content"] = "而你在这棋局中，要做的事情很简单：在祂们双双力竭之时，杀死我，终结这一切。如此一来，大风九章便能宣告颠覆。",
            ["ContentJP"] = "あなたに託す役目はひとつだけ。二柱が力尽きたその瞬間――私を殺して。契約を終わらせてほしい。そうすれば、大風九章は崩れるわ。",
            ["DialogueId"] = 12046418,
            ["GUID"] = "1E282D74",
            ["NextDialogue"] = 12046419,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D74",
            },
        [12046419] = {
            ["Content"] = "……杀死你？",
            ["ContentJP"] = "……あなたを、殺す？",
            ["DialogueId"] = 12046419,
            ["GUID"] = "1E282D9E",
            ["NextDialogue"] = 12046420,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282D9E",
            },
        [12046420] = {
            ["Content"] = "没错。",
            ["ContentJP"] = "ええ。",
            ["DialogueId"] = 12046420,
            ["GUID"] = "1E282DC8",
            ["NextDialogue"] = 12046421,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282DC8",
            },
        [12046421] = {
            ["Content"] = "魂契的一方死亡时，另一方也无法逃过契约的反噬。",
            ["ContentJP"] = "魂の契はどちらかが死ねば、もう一方も逃れられない。",
            ["DialogueId"] = 12046421,
            ["GUID"] = "1E282DF2",
            ["NextDialogue"] = 12046422,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282DF2",
            },
        [12046422] = {
            ["Content"] = "太皓、烛阴本出同源，无法真正给对方带来了断，但魂契的反噬却由祂们共同承担。此时借助契约的力量，就能以我的死亡给一切划下终结。",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>と<Default note=\"text:しょくいん\">燭陰</>は同源の存在、互いに決定打を与えることはできない。だけど、<Default note=\"text:たましのちぎり\">魂の契</>による反動だけは、二柱が共に背負うことになる。だから私はそれを利用して、自分の死ですべてを断ち切る。",
            ["DialogueId"] = 12046422,
            ["GUID"] = "1E282E1C",
            ["NextDialogue"] = 12046423,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E1C",
            },
        [12046423] = {
            ["Content"] = "鼎盛状态的神明，或许能够承受住契约的反噬。但力竭的神明可未必。",
            ["ContentJP"] = "全盛の神なら反動に耐えられるかもしれない。けれど、衰え果てた今の彼らには多分無理よ。",
            ["DialogueId"] = 12046423,
            ["GUID"] = "1E282E46",
            ["NextDialogue"] = 12046424,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E46",
            },
        [12046424] = {
            ["Content"] = "而你，将收获名望，以及助力。",
            ["ContentJP"] = "そしてあなたは、名誉と力を得られる。",
            ["DialogueId"] = 12046424,
            ["GUID"] = "1E282E70",
            ["NextDialogue"] = 12046425,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E70",
            },
        [12046425] = {
            ["Content"] = "华胥已被神明护佑近千年，一旦龙神陨落，必将群龙无首。这时候，需要一个人走出来鼓舞他们，将人心重新凝聚起来。这个英雄，就是你。",
            ["ContentJP"] = "千年にわたり神に庇護された華胥は、龍を失えば主を失うに等しい。その時、人々を導き、心をひとつにする英雄が必要になる。その役目を、あなたに託したい。",
            ["DialogueId"] = 12046425,
            ["GUID"] = "1E282E9A",
            ["NextDialogue"] = 12046426,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282E9A",
            },
        [12046426] = {
            ["Content"] = "届时，英雄的名声能带来莫大的助力。这样的报酬，你满意吗？",
            ["ContentJP"] = "英雄の名は、計り知れない力を持つ。それが、私からあなたへの報酬よ。これで、満足いただけたかしら？",
            ["DialogueId"] = 12046426,
            ["GUID"] = "1E282EC4",
            ["NextDialogue"] = 12046427,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282EC4",
            },
        [12046427] = {
            ["Content"] = "止流掌柜，你恐怕弄错了什么。",
            ["ContentJP"] = "……シリュウさん、あなたは勘違いをしている。",
            ["DialogueId"] = 12046427,
            ["GUID"] = "1E282EEE",
            ["NextDialogue"] = 12046428,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282EEE",
            },
        [12046428] = {
            ["Content"] = "你利用我、强迫我，确实使我愤怒。但这并不意味着我愿意看着任何一个人死去。",
            ["ContentJP"] = "{性别:僕を利用し、縛り付けたことは許せない。でもだからといって、誰かが死ぬのを見過ごすなんてできないよ。|私を利用し、縛り付けたことは許せない。でもだからといって、誰かが死ぬのを見過ごすなんてできないわ。}",
            ["DialogueId"] = 12046428,
            ["GUID"] = "1E282F18",
            ["NextDialogue"] = 12046429,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F18",
            },
        [12046429] = {
            ["Content"] = "我们刚见面时，你问过我，究竟有什么值得用性命去衡量。你明明恐惧着死亡……又为何能如此轻易地献祭自己的生命。",
            ["ContentJP"] = "{性别:初めて会ったとき、訊いたよな。「命を懸けてまで守るものがあるか」と。死を恐れていたあなたが……なぜ自分の命をないがしろにするんだ？|初めて会ったとき、訊いたよね。「命を懸けてまで守るものがあるか」と。死を恐れていたあなたが……なぜ自分の命をないがしろにするの？}",
            ["DialogueId"] = 12046429,
            ["GUID"] = "1E282F42",
            ["NextDialogue"] = 12046430,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F42",
            },
        [12046430] = {
            ["Content"] = "……那只是随口一提，你却当真了。",
            ["ContentJP"] = "あれは……ただの戯言のつもりだった。けど、あなたは本気で受け止めてくれたのね。",
            ["DialogueId"] = 12046430,
            ["GUID"] = "1E282F6C",
            ["NextDialogue"] = 12046431,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F6C",
            },
        [12046431] = {
            ["Content"] = "为了达成既定的结局，这一切牺牲都是必须的。你愿或不愿，都别无选择。",
            ["ContentJP"] = "でも、この結末のためには犠牲は避けられない。あなたがどう思おうと、選択肢はもう残されていないわ。",
            ["DialogueId"] = 12046431,
            ["GUID"] = "1E282F96",
            ["NextDialogue"] = 12046432,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282F96",
            },
        }
  end },
  { MinKey = 12046432, MaxKey = 12048202, Loader = function()
      return {
        [12046432] = {
            ["Content"] = "若是我不死去，失控的太皓、烛阴将使华胥彻底陷入混乱。{nickname}，我只能寄希望于你去完成这最后一举。",
            ["ContentJP"] = "私が死ななければ、暴走した<Default note=\"text:たいこう\">太皓</>と<Default note=\"text:しょくいん\">燭陰</>は、華胥を滅ぼす。最後の一手は、あなたに託すしかないの。",
            ["DialogueId"] = 12046432,
            ["GUID"] = "1E282FC0",
            ["NextDialogue"] = 12046433,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282FC0",
            },
        [12046433] = {
            ["Content"] = "倘若有任何后果或是骂名，都由我来背负……这样便好。",
            ["ContentJP"] = "……その報いも、罵声も、全部、私が背負うわ。これでいいの。",
            ["DialogueId"] = 12046433,
            ["GUID"] = "1E282FEA",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120464/1E282FEA",
            },
        [12046501] = {
            ["Content"] = "烛阴的气息……是谁任由污秽沾染这神圣之地？",
            ["ContentJP"] = "……この気配……燭陰か。神聖な地を汚したのは何者だ！",
            ["DialogueId"] = 12046501,
            ["GUID"] = "1E283B12",
            ["NextDialogue"] = 12046502,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B12",
            },
        [12046502] = {
            ["Content"] = "奉香大典的仪式并未开始。止流，你何故现身于此？",
            ["ContentJP"] = "<Default note=\"text:ほうこうのぎ\">奉香の儀</>はまだ始まっていない。シリュウよ、なぜここに？",
            ["DialogueId"] = 12046502,
            ["GUID"] = "1E283B3C",
            ["NextDialogue"] = 12046503,
            ["SpeakNpcId"] = 240073,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B3C",
            },
        [12046503] = {
            ["Content"] = "呵呵……你们何必明知故问呢。",
            ["ContentJP"] = "ふふ……わかっているくせに。",
            ["DialogueId"] = 12046503,
            ["GUID"] = "1E283B66",
            ["NextDialogue"] = 12046504,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B66",
            },
        [12046504] = {
            ["Content"] = "我在这里的原因，你我都心知肚明。我是来终结大风九章的。",
            ["ContentJP"] = "ご存じの通り、大風九章を終わらせに来たわ。",
            ["DialogueId"] = 12046504,
            ["GUID"] = "1E283B90",
            ["NextDialogue"] = 12046505,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283B90",
            },
        [12046505] = {
            ["Content"] = "大胆！你清楚自己在做什么吗？！",
            ["ContentJP"] = "無礼もの！自分が何を言ってるかわかってるのか！？",
            ["DialogueId"] = 12046505,
            ["GUID"] = "1E283BBA",
            ["NextDialogue"] = 12046506,
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283BBA",
            },
        [12046506] = {
            ["Content"] = "止流，吾辈从来对你寄予重望。龙渊上卿的殊荣和力量，可不是随便授于你身的！",
            ["ContentJP"] = "シリュウ、我らはそなたに大きな望みを託してきた。「龍淵の上卿」の名誉と力は、軽々しく授けられるものではないぞ！",
            ["DialogueId"] = 12046506,
            ["GUID"] = "1E283BE4",
            ["NextDialogue"] = 12046507,
            ["SpeakNpcId"] = 240073,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283BE4",
            },
        [12046507] = {
            ["Content"] = "放心。我既然站在这里，便已经做好了必死的觉悟。",
            ["ContentJP"] = "安心して。ここに来た時点で、死は覚悟しているわ。",
            ["DialogueId"] = 12046507,
            ["GUID"] = "1E283C0E",
            ["NextDialogue"] = 12046508,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283C0E",
            },
        [12046508] = {
            ["Content"] = "“承九鼎，济苍黎”，此为龙渊上卿应尽之职……虽九死其犹未悔。",
            ["ContentJP"] = "「九鼎を継ぎ、蒼生を救う」――それが龍淵の上卿の務め。たとえ命を落としても、悔いはないわ。",
            ["DialogueId"] = 12046508,
            ["GUID"] = "1E283C38",
            ["NextDialogue"] = 12046509,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283C38",
            },
        [12046509] = {
            ["Content"] = "你……！",
            ["ContentJP"] = "なっ……！",
            ["DialogueId"] = 12046509,
            ["GUID"] = "1E283C62",
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120465/1E283C62",
            },
        [12046601] = {
            ["Content"] = "若太皓陨落，万古秩序将毁于一旦！",
            ["ContentJP"] = "もし太皓が墜ちれば、万古の秩序は一瞬で崩れ去るぞ！",
            ["DialogueId"] = 12046601,
            ["GUID"] = "1E284B7A",
            ["NextDialogue"] = 12046602,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284B7A",
            },
        [12046602] = {
            ["Content"] = "止流，你缘何做出如此倒行逆施之举？",
            ["ContentJP"] = "シリュウよ――何故そんな愚行に手を染めた！？",
            ["DialogueId"] = 12046602,
            ["GUID"] = "1E284BA4",
            ["NextDialogue"] = 12046603,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284BA4",
            },
        [12046603] = {
            ["Content"] = "理由吗……",
            ["ContentJP"] = "理由か……",
            ["DialogueId"] = 12046603,
            ["GUID"] = "1E284BCE",
            ["NextDialogue"] = 12046604,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284BCE",
            },
        [12046604] = {
            ["Content"] = "现今的华胥，民众习惯了向神明祈求一切。",
            ["ContentJP"] = "いまの華胥の民は、すべてを神に祈り、委ねて生きている。",
            ["DialogueId"] = 12046604,
            ["GUID"] = "1E284BF8",
            ["NextDialogue"] = 12046605,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284BF8",
            },
        [12046605] = {
            ["Content"] = "他们放下武器，不再以双手守护自己。",
            ["ContentJP"] = "武を捨て、牙を抜かれ――",
            ["DialogueId"] = 12046605,
            ["GUID"] = "1E284C22",
            ["NextDialogue"] = 12046606,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284C22",
            },
        [12046606] = {
            ["Content"] = "他们闭目塞听，只顺从大风九章之音。",
            ["ContentJP"] = "ただ大風九章の声に従うだけ。",
            ["DialogueId"] = 12046606,
            ["GUID"] = "1E284C4C",
            ["NextDialogue"] = 12046607,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284C4C",
            },
        [12046607] = {
            ["Content"] = "他们泯灭内心的想法，把善恶托付于天命裁决。",
            ["ContentJP"] = "己の思考を眠らせ、善悪すら天命に裁かせている。",
            ["DialogueId"] = 12046607,
            ["GUID"] = "1E284C76",
            ["NextDialogue"] = 12046608,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284C76",
            },
        [12046608] = {
            ["Content"] = "可神明真的能永远庇护华胥吗？烛阴之灾横生，太皓无力阻止，难道不是昭示着大风九章正在衰弱？",
            ["ContentJP"] = "しかし、神は果たして、この華胥をいつまでも守ってくれるのかしら。燭陰の禍は太皓にもどうすることもできないでしょう。大風九章も日ごとに弱くなってるよ。",
            ["DialogueId"] = 12046608,
            ["GUID"] = "1E284CA0",
            ["NextDialogue"] = 12046613,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284CA0",
            },
        [12046610] = {
            ["Content"] = "糊涂！凡人一孔之见，岂能独当大局？",
            ["ContentJP"] = "愚か者め！庶民の浅知恵で、大局を背負えるものか！",
            ["DialogueId"] = 12046610,
            ["GUID"] = "1E284CF4",
            ["NextDialogue"] = 12046611,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284CF4",
            },
        [12046611] = {
            ["Content"] = "呵呵……受缚于陶俑之中，你怎知你不是自己口中的凡人呢？",
            ["ContentJP"] = "……哀れなものね。石に縛られたまま、よくそんな口がきける。あなた自身も、自ら嘲った庶民と変わらぬと気づきもしないで。",
            ["DialogueId"] = 12046611,
            ["GUID"] = "1E284D1E",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/1E284D1E",
            },
        [12046613] = {
            ["Content"] = "看，大陆的另一端，帝国与传颂会的战争已经绵延千年。当大风九章彻底衰竭，神明不再能庇护这片土地，华胥人如何才能在纷争的涡旋中独善其身？",
            ["ContentJP"] = "分かったかしら？大陸の向こう側に、帝国と礼賛会の戦争はもう千年以上に続いてきたよ。この華胥の地に、もし大風九章の力が衰えたらどうする？",
            ["DialogueId"] = 12046613,
            ["GUID"] = "12046613.0",
            ["NextDialogue"] = 12046614,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/12046613",
            },
        [12046614] = {
            ["Content"] = "若是有一天，大风九章力量耗尽，人们应当如何用自己的双眼重新丈量世界？又当如何生存，如何抗争，如何明断善恶，如何重塑秩序？",
            ["ContentJP"] = "もし大風九章の加護が絶えたらどうする？どう世界を見極め、どう生き延びればいいの？どう抗い、善悪を定め、秩序を築き直すの？",
            ["DialogueId"] = 12046614,
            ["GUID"] = "12046614.0",
            ["NextDialogue"] = 12046610,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120466/12046614",
            },
        [12046701] = {
            ["Content"] = "止流，这样做的后果，你可想好了？你一个人担得起吗？",
            ["ContentJP"] = "シリュウ…………この選択の果てに何が待つか、分かっているのか？お前ひとりで背負いきれると思うのか！",
            ["DialogueId"] = 12046701,
            ["GUID"] = "1E285BE2",
            ["NextDialogue"] = 12046702,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285BE2",
            },
        [12046702] = {
            ["Content"] = "自然是担得起。",
            ["ContentJP"] = "もちろん。",
            ["DialogueId"] = 12046702,
            ["GUID"] = "1E285C0C",
            ["NextDialogue"] = 12046703,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C0C",
            },
        [12046703] = {
            ["Content"] = "竟自私至此！",
            ["ContentJP"] = "なんという身勝手！",
            ["DialogueId"] = 12046703,
            ["GUID"] = "1E285C36",
            ["NextDialogue"] = 12046704,
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C36",
            },
        [12046704] = {
            ["Content"] = "你是可以闹完这出，两眼一闭，不管身后事了。但那些失去了大风九章庇护的民众呢？他们该如何自处？",
            ["ContentJP"] = "お前は好きに幕を引いて、目を閉じれば終わりだろう……だが、大風九章に守られてきた民はどうなる？彼らは誰にすがり、どう生きていけばいい！",
            ["DialogueId"] = 12046704,
            ["GUID"] = "1E285C60",
            ["NextDialogue"] = 12046708,
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C60",
            },
        [12046705] = {
            ["Content"] = "人性没有你想的那么脆弱。当不再仰赖神明，人类便会重新学习如何用自己的双手应对秽蚀、战争、伤害、和罪恶。",
            ["ContentJP"] = "人は、あなたが思うほど弱くはない。神の加護を失った彼らは必ず、再び学ぶでしょう。穢蝕に抗う術を。戦いの痛みを。そして、罪と向き合う覚悟を。",
            ["DialogueId"] = 12046705,
            ["GUID"] = "1E285C8A",
            ["NextDialogue"] = 12046708,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285C8A",
            },
        [12046706] = {
            ["Content"] = "在这个过程中，或许会有阵痛，或许会出现牺牲，但这是剜骨疗伤所必须经历的一环。",
            ["ContentJP"] = "その道は苦しく、犠牲も避けられない……",
            ["DialogueId"] = 12046706,
            ["GUID"] = "1E285CB4",
            ["NextDialogue"] = 12046707,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285CB4",
            },
        [12046707] = {
            ["Content"] = "只有在病灶清除后，生命才能找寻新的出路。",
            ["ContentJP"] = "けれど、膿を切り裂かなければ、新しい命は芽吹かない。",
            ["DialogueId"] = 12046707,
            ["GUID"] = "1E285CDE",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/1E285CDE",
            },
        [12046708] = {
            ["Content"] = "那自愿悖离于大风九章之外的飘零人，不照样依靠机括术和传承下来的武艺庇护了自己吗？",
            ["ContentJP"] = "自らで大風九章を脱出した流れ者たちさえも、からくりの術と代々受け継がれた武芸で自分を守ってきたのではないかしら？",
            ["DialogueId"] = 12046708,
            ["GUID"] = "12046708.0",
            ["NextDialogue"] = 12046706,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120467/12046708",
            },
        [12046801] = {
            ["Content"] = "令人赞叹的谋划布局……止流，千古以来，能给中枢真正带来威胁的，你是第一人。",
            ["ContentJP"] = "まぁ……なんと見事な策だこと、シリュウ。千年を超えるこの時代の中枢に、本気で刃を向けたのは……あなたが初めてよ。",
            ["DialogueId"] = 12046801,
            ["GUID"] = "1E286C4A",
            ["NextDialogue"] = 12046802,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286C4A",
            },
        [12046802] = {
            ["Content"] = "当初选了你作为龙渊上卿，便是看中了你的才智，却未想到会带来这样的结局。",
            ["ContentJP"] = "かつてあなたを龍淵の上卿に選んだとき、確かにその才に目をかけたわ。けれど、まさかこんな結末を迎えるとは思っていなかった。",
            ["DialogueId"] = 12046802,
            ["GUID"] = "1E286C74",
            ["NextDialogue"] = 12046803,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286C74",
            },
        [12046803] = {
            ["Content"] = "呵呵……未有机会感谢你对我的提拔，现在道谢也不算晚。",
            ["ContentJP"] = "ふふ……あの時は世話になったわね。今更だけど、お礼を言わせてほしいわ。",
            ["DialogueId"] = 12046803,
            ["GUID"] = "1E286C9E",
            ["NextDialogue"] = 12046804,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286C9E",
            },
        [12046804] = {
            ["Content"] = "止流，你我都是聪明人。我不像那些蠢物一样和你大发雷霆，谈论那虚无缥缈的道德义务。",
            ["ContentJP"] = "……やっぱり聡い娘ね。私は他の者たちみたいに、怒鳴ったりはしないわ。あの空っぽな「道徳」を振りかざす気もない。",
            ["DialogueId"] = 12046804,
            ["GUID"] = "1E286CC8",
            ["NextDialogue"] = 12046805,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286CC8",
            },
        [12046805] = {
            ["Content"] = "道德只是对于庸人的束缚。而所谓龙神，不过是太虚凝结成的造物，幕后意志的代行者罢了。",
            ["ContentJP"] = "「道徳」とは、所詮凡人を縛るものでしかない。「龍神」と呼ばれる存在もまた、虚無の意思が形をとったただの器に過ぎない。",
            ["DialogueId"] = 12046805,
            ["GUID"] = "1E286CF2",
            ["NextDialogue"] = 12046806,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286CF2",
            },
        [12046806] = {
            ["Content"] = "真正掌控大风九章的，是<W>吾辈</>——千年来列代祭献身躯，汇入中枢的时代精英所构成的共同意志。",
            ["ContentJP"] = "本当に大風九章を動かしてきたのは、<W>私たち</>――千年続く、代々己の身を捧げ、中枢に意志を積み重ねてきた精鋭たちの共同体よ。",
            ["DialogueId"] = 12046806,
            ["GUID"] = "1E286D1C",
            ["NextDialogue"] = 12046807,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D1C",
            },
        [12046807] = {
            ["Content"] = "止流，以吾辈的意志，我向你发来真正的邀请。",
            ["ContentJP"] = "シリュウ、あなたにはその意志を継ぐ資格がある。",
            ["DialogueId"] = 12046807,
            ["GUID"] = "1E286D46",
            ["NextDialogue"] = 12046808,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D46",
            },
        [12046808] = {
            ["Content"] = "你已经证明了自己的决心和才华。我可将你迎入中枢，加入<W>吾辈</>，你便能够以你的意志重塑华胥。",
            ["ContentJP"] = "<W>私たち</>に加わりなさい。そうすれば――あなたの望む華胥を、この手で現実にできるのよ。",
            ["DialogueId"] = 12046808,
            ["GUID"] = "1E286D70",
            ["NextDialogue"] = 12046809,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D70",
            },
        [12046809] = {
            ["Content"] = "如何，这份邀请，能让你满意吗？",
            ["ContentJP"] = "どうかしら？",
            ["DialogueId"] = 12046809,
            ["GUID"] = "1E286D9A",
            ["NextDialogue"] = 12046810,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286D9A",
            },
        [12046810] = {
            ["Content"] = "你倒是比先前那些人更懂得谈判。不过……还是不必了。",
            ["ContentJP"] = "……なるほど。あなたは他の連中よりよほど筋が通っているのね。けど、断るわ。",
            ["DialogueId"] = 12046810,
            ["GUID"] = "1E286DC4",
            ["NextDialogue"] = 12046811,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286DC4",
            },
        [12046811] = {
            ["Content"] = "为何？无论你有怎样的诉求，引领民众也好，或是革新华胥也罢，这万人之巅的位置都能帮你实现。",
            ["ContentJP"] = "なぜ？どんな願いでもいい。人々を導く理想でも、国を変える野心でも――この「神位」に立てば、すべて叶えられる。万人の頂に立てば、あなたの革新は現実になるのよ！",
            ["DialogueId"] = 12046811,
            ["GUID"] = "1E286DEE",
            ["NextDialogue"] = 12046812,
            ["SpeakNpcId"] = 240071,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286DEE",
            },
        [12046812] = {
            ["Content"] = "你可能搞错了一点，我对成神从未有过欲求。",
            ["ContentJP"] = "一つ間違えていることがあるの。私は神になる気はない。",
            ["DialogueId"] = 12046812,
            ["GUID"] = "1E286E18",
            ["NextDialogue"] = 12046813,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286E18",
            },
        [12046813] = {
            ["Content"] = "华胥，不应当再有新的神明了。",
            ["ContentJP"] = "華胥に、新しい神は必要ないわ。",
            ["DialogueId"] = 12046813,
            ["GUID"] = "1E286E42",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120468/1E286E42",
            },
        [12046901] = {
            ["Content"] = "我知道止流的完整计划了！",
            ["ContentJP"] = "シリュウさんの計画がわかった！",
            ["DialogueId"] = 12046901,
            ["GUID"] = "1E287CB2",
            ["NextDialogue"] = 12046902,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 304003,
                [3] = 303008,
                [4] = 303011,
                [5] = 304004,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287CB2",
            },
        [12046902] = {
            ["Content"] = "小仆从，这、这和我们头上突然出现的两条巨龙有关系吗？",
            ["ContentJP"] = "き、急に龍が二体現れたけど……それと何か関係があるのか！？",
            ["DialogueId"] = 12046902,
            ["GUID"] = "1E287CDC",
            ["NextDialogue"] = 12046903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287CDC",
            },
        [12046903] = {
            ["Content"] = "现在阻止她还来得及！事情是这样的……",
            ["ContentJP"] = "今なら、まだ止められるかもしれない――{性别:聞いてくれ|みんな聞いて}。",
            ["DialogueId"] = 12046903,
            ["GUID"] = "1E287D06",
            ["NextDialogue"] = 12046905,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287D06",
            },
        [12046904] = {
            ["Content"] = "听苏乙说过一些。",
            ["ContentJP"] = "スーイーから少し聞きました。",
            ["DialogueId"] = 12046904,
            ["GUID"] = "1E287D30",
            ["NextDialogue"] = 12046912,
            },
        [12046905] = {
            ["Content"] = "{nickname}，你的意思莫非是……大风九章要终结了？！",
            ["ContentJP"] = "つまり………大風九章が崩壊するということですか！？",
            ["DialogueId"] = 12046905,
            ["GUID"] = "1E287D5A",
            ["NextDialogue"] = 12046906,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287D5A",
            },
        [12046906] = {
            ["Content"] = "惊才绝艳的想法，铤而走险的性格，苛责己身的执行力……这么多年了，她还是一如既往。",
            ["ContentJP"] = "あの子の発想力、思い切った行動力、そして自分にさえ容赦しない苛烈さ……何も変わってないね。",
            ["DialogueId"] = 12046906,
            ["GUID"] = "1E287D84",
            ["NextDialogue"] = 12046907,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287D84",
            },
        [12046907] = {
            ["Content"] = "喂，现在可不是感慨的时候了，还有办法阻止她吗？！",
            ["ContentJP"] = "感心してる場合かよ！止める方法は！？間に合うのか！？",
            ["DialogueId"] = 12046907,
            ["GUID"] = "1E287DAE",
            ["NextDialogue"] = 12046908,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287DAE",
            },
        [12046908] = {
            ["Content"] = "若烛阴尚未封印，或许还有办法，但现在怕是已无计可施了……",
            ["ContentJP"] = "……もし<Default note=\"text:しょくいん\">燭陰</>がまだ完全には封印されていないのなら、あるいは――いいえ、もう間に合わないでしょう。",
            ["DialogueId"] = 12046908,
            ["GUID"] = "1E287DD8",
            ["NextDialogue"] = 12046909,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287DD8",
            },
        [12046909] = {
            ["Content"] = "就算是最渺茫的希望也好，请告诉我！",
            ["ContentJP"] = "たとえ一縷の望みでもいい、教えてください！",
            ["DialogueId"] = 12046909,
            ["GUID"] = "1E287E02",
            ["NextDialogue"] = 12046910,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287E02",
            },
        [12046910] = {
            ["Content"] = "这便要从大风九章的由来说起了。你对其中内情有多少了解？",
            ["ContentJP"] = "……ではまず、大風九章の成り立ちから話そう。この儀式の真相を、お前はどれほど知ってるかな？",
            ["DialogueId"] = 12046910,
            ["GUID"] = "1E287E2C",
            ["NextOptions"] = {
                [1] = 12046904,
                [2] = 12046911,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287E2C",
            },
        [12046911] = {
            ["Content"] = "不太了解。",
            ["ContentJP"] = "正直、あまりわかりません。",
            ["DialogueId"] = 12046911,
            ["GUID"] = "1E287E56",
            ["NextDialogue"] = 12046912,
            },
        [12046912] = {
            ["Content"] = "大风九章今日虽已被神化，究其本质，却是人为固定在这片土地上的巨型魔法仪式。",
            ["ContentJP"] = "大風九章はすでに神格化されている――でもその本質は、元々人の手で築かれた巨大な魔法陣に過ぎない。",
            ["DialogueId"] = 12046912,
            ["GUID"] = "1E287E80",
            ["NextDialogue"] = 12046913,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287E80",
            },
        [12046913] = {
            ["Content"] = "既是人为，在创立之初，便设置了规则和约定。狴犴，应天尉，乃至于太皓、烛阴，都是遵从着这规则而运转的。",
            ["ContentJP"] = "神ではなく、人が作り出したものならば——その始まりには、必ず「理」と「約定」があったはずだ。<Default note=\"text:ビーアン\">狴犴</>や<Default note=\"text:おうてんい\">応天尉</>、\
<Default note=\"text:たいこう\">太皓</>や<Default note=\"text:しょくいん\">燭陰</>……彼らは皆、その規則に則って動く存在に過ぎない。",
            ["DialogueId"] = 12046913,
            ["GUID"] = "1E287EAA",
            ["NextDialogue"] = 12046914,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287EAA",
            },
        [12046914] = {
            ["Content"] = "悬衡派的创立者<H>飏</>，以及机枢派的创立者<H>矩</>，他们二人献祭自身，将思想融于大风九章中枢，成为了太皓和烛阴最早的意志。",
            ["ContentJP"] = "かつて、<Default note=\"text:けんこうは\">懸衡派</>を興した<H>ヤン</>と、<Default note=\"text:きすうは\">機枢派</>の祖である<H>ノリ</>は——自らの命を捧げ、その思想を大風九章の中枢に刻み込んだ。彼らは<Default note=\"text:たいこう\">太皓</>と<Default note=\"text:しょくいん\">燭陰</>の最初の「意志」となった。",
            ["DialogueId"] = 12046914,
            ["GUID"] = "1E287ED4",
            ["NextDialogue"] = 12046915,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287ED4",
            },
        [12046915] = {
            ["Content"] = "上古时期，龙神并非高高在上，与凡人泾渭分明。彼时，凡人会于执律阁端，和龙神论辩律法，共商裁决。",
            ["ContentJP"] = "かつての龍神は、今のような高位の存在ではなかった。人と語らい、共に律を立て、裁きを分かち合っていたのだ。",
            ["DialogueId"] = 12046915,
            ["GUID"] = "1E287EFE",
            ["NextDialogue"] = 12046916,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287EFE",
            },
        [12046916] = {
            ["Content"] = "为预防仪式偏离初衷，日久生患，飏和矩设计了均天玉律这一信物。分为两份，由悬衡、机枢两派各执其一。",
            ["ContentJP"] = "儀式が歪むことを恐れたのだろう。ヤンとノリは「均天玉律」という<Default note=\"text:しるし\">信物</>をつくり、二つに分けて<Default note=\"text:けんこうは\">懸衡派</>と<Default note=\"text:きすうは\">機枢派</>に託した。",
            ["DialogueId"] = 12046916,
            ["GUID"] = "1E287F28",
            ["NextDialogue"] = 12046917,
            ["RelatedWikiId"] = {
                [1] = 407015,
                },
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287F28",
            },
        [12046917] = {
            ["Content"] = "于太虚陵之巅，将分开的均天玉律合二为一，即可踏入大风九章中枢，让这一仪式重归原点。",
            ["ContentJP"] = "そして、<Default note=\"text:たいきょりょう\">太虚陵</>の頂でふたたび一つに戻せば――大風九章の中枢へと至り、儀式そのものを「初期状態」へと巻き戻すことができる。",
            ["DialogueId"] = 12046917,
            ["GUID"] = "1E287F52",
            ["NextDialogue"] = 12046918,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287F52",
            },
        [12046918] = {
            ["Content"] = "重归原点？那样的话，止流进行的祭献仪式，是不是可以中断了？！",
            ["ContentJP"] = "つまり……シリュウさんの儀式を中断できるってこと？",
            ["DialogueId"] = 12046918,
            ["GUID"] = "1E287F7C",
            ["NextDialogue"] = 12046919,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287F7C",
            },
        [12046919] = {
            ["Content"] = "不仅如此。",
            ["ContentJP"] = "それだけではない。",
            ["DialogueId"] = 12046919,
            ["GUID"] = "1E287FA6",
            ["NextDialogue"] = 12046920,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287FA6",
            },
        [12046920] = {
            ["Content"] = "如今大风九章僵化，究其原因，全为黍离之战后悬衡派一意孤行，封印烛阴所致。",
            ["ContentJP"] = "大風九章が今のように腐ってしまった元凶は――あの「<Default note=\"text:しょりのらん\">黍離の乱</>」以降、<Default note=\"text:けんこうは\">懸衡派</>が勝手に<Default note=\"text:しょくいん\">燭陰</>を封印したからだ。",
            ["DialogueId"] = 12046920,
            ["GUID"] = "1E287FD0",
            ["NextDialogue"] = 12046921,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287FD0",
            },
        [12046921] = {
            ["Content"] = "“心”、“理”的平衡之道被打破，太皓逐渐变为绝对秩序的代名词，只问法条，不再听取子民的心声。",
            ["ContentJP"] = "「心」と「理」の均衡は失われ、<Default note=\"text:たいこう\">太皓</>は法の名のもとに秩序を押し付ける存在となり、民の声を聞こうともしなくなった。",
            ["DialogueId"] = 12046921,
            ["GUID"] = "1E287FFA",
            ["NextDialogue"] = 12046922,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E287FFA",
            },
        [12046922] = {
            ["Content"] = "而失去理性的烛阴则不断被心中愤怒驱使，为祸一方，使得烛阴之灾周而复返。",
            ["ContentJP"] = "理を失った<Default note=\"text:しょくいん\">燭陰</>は怒りに飲まれ、禍の化身と化した。",
            ["DialogueId"] = 12046922,
            ["GUID"] = "1E288024",
            ["NextDialogue"] = 12046923,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288024",
            },
        [12046923] = {
            ["Content"] = "若是一切重归原点，这僵化的现状，或许也能焕发新机。",
            ["ContentJP"] = "もしすべてを「原点」に戻せるのなら――この行き詰まった現状にも、再び息を吹き込めるかもしれない。",
            ["DialogueId"] = 12046923,
            ["GUID"] = "1E28804E",
            ["NextDialogue"] = 12046924,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E28804E",
            },
        [12046924] = {
            ["Content"] = "然黍离一役中，机枢派持有的那份均天玉律下落不明，如今已是无迹可寻，这唯一的线索也就此断绝。",
            ["ContentJP"] = "だが、<Default note=\"text:しょりのらん\">黍離の乱</>で<Default note=\"text:きすう\">機枢</>が持っていた玉律は行方不明になった。手がかりもすべて途絶えててね……",
            ["DialogueId"] = 12046924,
            ["GUID"] = "1E288078",
            ["NextDialogue"] = 12046925,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288078",
            },
        [12046925] = {
            ["Content"] = "双份合二为一……",
            ["ContentJP"] = "ふたつをひとつに……",
            ["DialogueId"] = 12046925,
            ["GUID"] = "1E2880A2",
            ["NextDialogue"] = 12046926,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2880A2",
            },
        [12046926] = {
            ["Content"] = "这位前辈，你说的那个均天玉律，是什么样子的？难不成，长这样？",
            ["ContentJP"] = "その玉律って……もしかして、これのこと？",
            ["DialogueId"] = 12046926,
            ["GUID"] = "1E2880CC",
            ["NextDialogue"] = 12046927,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2880CC",
            },
        [12046927] = {
            ["Content"] = "……你们，竟寻得了此物。",
            ["ContentJP"] = "お前たち、見つけていたの……！",
            ["DialogueId"] = 12046927,
            ["GUID"] = "1E2880F6",
            ["NextDialogue"] = 12046928,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2880F6",
            },
        [12046928] = {
            ["Content"] = "晨起我算得一卦，谓“休复吉”。然复从何来？原来竟应在你们身上。",
            ["ContentJP"] = "今朝の卦は「<Default note=\"text:よくかえるきち\">休復吉</>」。まさかとは思ったが……お前たちが鍵を握っていたとはね。",
            ["DialogueId"] = 12046928,
            ["GUID"] = "1E288120",
            ["NextDialogue"] = 12046929,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288120",
            },
        [12046929] = {
            ["Content"] = "有孚惠心者，非求而得，乃天授也……这局，合该由你来破。",
            ["ContentJP"] = "真心ある者には、求めずとも天が応える。この結末、お前が導くべきもののようだね。",
            ["DialogueId"] = 12046929,
            ["GUID"] = "1E28814A",
            ["NextDialogue"] = 12046930,
            ["SpeakNpcId"] = 240040,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E28814A",
            },
        [12046930] = {
            ["Content"] = "抛开听不懂的部分……总而言之，拿着这块免死券，冲上那个什么陵墓，就有机会中断止流的计划，是吗？",
            ["ContentJP"] = "難しいとこは置いといて……これを持ってあの墓に行けば、シリュウの儀式を止められるってことだよな！？",
            ["DialogueId"] = 12046930,
            ["GUID"] = "1E288174",
            ["NextDialogue"] = 12046931,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E288174",
            },
        [12046931] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "グオォォォ……！",
            ["DialogueId"] = 12046931,
            ["GUID"] = "1E28819E",
            ["NextDialogue"] = 12046932,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E28819E",
            },
        [12046932] = {
            ["Content"] = "刻不容缓，{nickname}，我们走！",
            ["ContentJP"] = "ぐずぐずしてる暇はねえな、{nickname}！行くぞ！",
            ["DialogueId"] = 12046932,
            ["GUID"] = "1E2881C8",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120469/1E2881C8",
            },
        [12047001] = {
            ["Content"] = "来人——救命啊！",
            ["ContentJP"] = "誰か……助けてくれぇ！",
            ["DialogueId"] = 12047001,
            ["GUID"] = "1E288D1A",
            ["NextDialogue"] = 12047002,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240041,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D1A",
            },
        [12047002] = {
            ["Content"] = "白龙神君护佑，白龙神君护佑——",
            ["ContentJP"] = "白龍様……どうか御守り下さい……",
            ["DialogueId"] = 12047002,
            ["GUID"] = "1E288D44",
            ["NextDialogue"] = 12047003,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D44",
            },
        [12047003] = {
            ["Content"] = "阿爷，囡囡没有不乖，为什么白色的大狼要来吃掉囡囡？",
            ["ContentJP"] = "おじいちゃん、私いい子にしてたのに、どうしてあの狼、襲ってくるの？",
            ["DialogueId"] = 12047003,
            ["GUID"] = "1E288D6E",
            ["NextDialogue"] = 12047004,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D6E",
            },
        [12047004] = {
            ["Content"] = "囡囡，这是上天降下来的考验，是白龙神君给我们的考验！明白吗？你一定要心诚，才能度过此劫……",
            ["ContentJP"] = "これは神の試練だ。心を強く持て。白龍様がお前を見守ってくださる……信じるのだ……",
            ["DialogueId"] = 12047004,
            ["GUID"] = "1E288D98",
            ["NextDialogue"] = 12047005,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288D98",
            },
        [12047005] = {
            ["Content"] = "快躲开，爹，囡囡——",
            ["ContentJP"] = "父さん、ナナ！はやく逃げて！！",
            ["DialogueId"] = 12047005,
            ["GUID"] = "1E288DC2",
            ["NextDialogue"] = 12047006,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288DC2",
            },
        [12047006] = {
            ["Content"] = "城里都乱成这样了，狴犴和玄色狴犴一同转过身来攻击大家了！爹，你怎么还有空在这里祈祷？！",
            ["ContentJP"] = "街はもう滅茶苦茶よ、<Default note=\"text:ビーアン\">狴犴</>と<Default note=\"text:ゲンビー\">玄狴</>が人に襲いかかってる！祈ってる場合じゃないわ！",
            ["DialogueId"] = 12047006,
            ["GUID"] = "1E288DEC",
            ["NextDialogue"] = 12047007,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288DEC",
            },
        [12047007] = {
            ["Content"] = "没人能保护我们了！赶紧带着囡囡快逃啊！",
            ["ContentJP"] = "もう私たちを守ってくれるものなんてないの！はやくナナを連れて逃げて！！",
            ["DialogueId"] = 12047007,
            ["GUID"] = "1E288E16",
            ["NextDialogue"] = 12047008,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E16",
            },
        [12047008] = {
            ["Content"] = "住口！休要对狴犴不敬！",
            ["ContentJP"] = "黙れ！<Default note=\"text:ビーアン\">狴犴</>様を侮辱する気か！",
            ["DialogueId"] = 12047008,
            ["GUID"] = "1E288E40",
            ["NextDialogue"] = 12047009,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E40",
            },
        [12047009] = {
            ["Content"] = "白龙神君谅解小女无心之言……",
            ["ContentJP"] = "白龍様……どうか、娘の無礼をお許しください……",
            ["DialogueId"] = 12047009,
            ["GUID"] = "1E288E6A",
            ["NextDialogue"] = 12047010,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E6A",
            },
        [12047010] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "グオォォォ……！",
            ["DialogueId"] = 12047010,
            ["GUID"] = "1E288E94",
            ["NextDialogue"] = 12047011,
            ["SpeakNpcId"] = 240045,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288E94",
            },
        [12047011] = {
            ["Content"] = "呀！！",
            ["ContentJP"] = "きゃあっ！！",
            ["DialogueId"] = 12047011,
            ["GUID"] = "1E288EBE",
            ["NextDialogue"] = 12047012,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288EBE",
            },
        [12047012] = {
            ["Content"] = "闪开——",
            ["ContentJP"] = "どいて！",
            ["DialogueId"] = 12047012,
            ["GUID"] = "1E288EE8",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120470/1E288EE8",
            },
        [12047101] = {
            ["Content"] = "小妹妹，你还好吗，有没有伤到哪里？",
            ["ContentJP"] = "大丈夫？怪我してない？",
            ["DialogueId"] = 12047101,
            ["GUID"] = "1E289D82",
            ["NextDialogue"] = 12047102,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289D82",
            },
        [12047102] = {
            ["Content"] = "谢谢姐姐，囡囡没事！",
            ["ContentJP"] = "ありがとう！大丈夫だよ！",
            ["DialogueId"] = 12047102,
            ["GUID"] = "1E289DAC",
            ["NextDialogue"] = 12047103,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289DAC",
            },
        [12047103] = {
            ["Content"] = "囡囡——太好了，幸好你没出事……",
            ["ContentJP"] = "ああ、ナナ――無事でよかった……！",
            ["DialogueId"] = 12047103,
            ["GUID"] = "1E289DD6",
            ["NextDialogue"] = 12047104,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289DD6",
            },
        [12047104] = {
            ["Content"] = "城中竟然已经是这副乱象了……幸好我们赶来及时。",
            ["ContentJP"] = "街の中がここまで混乱しているとは……間一髪だったな。",
            ["DialogueId"] = 12047104,
            ["GUID"] = "1E289E00",
            ["NextDialogue"] = 12047105,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E00",
            },
        [12047105] = {
            ["Content"] = "大姐姐，你是上天派来救我们的使者吗？",
            ["ContentJP"] = "お姉さん……もしかして、龍神様の使者なの？",
            ["DialogueId"] = 12047105,
            ["GUID"] = "1E289E2A",
            ["NextDialogue"] = 12047106,
            ["SpeakNpcId"] = 240043,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E2A",
            },
        [12047106] = {
            ["Content"] = "上天？你误会啦，我们是……",
            ["ContentJP"] = "龍神？いいえ、私たちは……",
            ["DialogueId"] = 12047106,
            ["GUID"] = "1E289E54",
            ["NextDialogue"] = 12047107,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E54",
            },
        [12047107] = {
            ["Content"] = "……快离开她！我认出来了，这些人是飘零人！沾上他们不会有什么好下场的！",
            ["ContentJP"] = "……ナナから離れろ！お前たち、「流れ者」だろう！関われば不幸を招くぞ！！",
            ["DialogueId"] = 12047107,
            ["GUID"] = "1E289E7E",
            ["NextDialogue"] = 12047108,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289E7E",
            },
        [12047108] = {
            ["Content"] = "你们这些离经叛道的家伙，赶紧放开我们家囡囡！",
            ["ContentJP"] = "お前たちみたいな不届き者が、ナナに触れるな！",
            ["DialogueId"] = 12047108,
            ["GUID"] = "1E289EA8",
            ["NextDialogue"] = 12047109,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289EA8",
            },
        [12047109] = {
            ["Content"] = "爹，都这种时候了，你少说两句吧！",
            ["ContentJP"] = "父さん、今はそんなこと言ってる場合じゃないでしょ！",
            ["DialogueId"] = 12047109,
            ["GUID"] = "1E289ED2",
            ["NextDialogue"] = 12047110,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289ED2",
            },
        [12047110] = {
            ["Content"] = "“不会有什么好下场”……？呵，你该不会搞错了吧。",
            ["ContentJP"] = "「不幸になる」か……ハハハ、勘違いも大概にしろよ。",
            ["DialogueId"] = 12047110,
            ["GUID"] = "1E289EFC",
            ["NextDialogue"] = 12047111,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289EFC",
            },
        [12047111] = {
            ["Content"] = "你口中离经叛道的，刚刚救了你的命。至于你对着祈祷的神，现在还不知道在哪里呢。",
            ["ContentJP"] = "お前が今生きてるのは、その流れ者に救われたからだ。お前が拝んでた神とやらは、現れたのか？",
            ["DialogueId"] = 12047111,
            ["GUID"] = "1E289F26",
            ["NextDialogue"] = 12047112,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289F26",
            },
        [12047112] = {
            ["Content"] = "一切都乱套了，乱套了……华胥的天是要塌下来了呀！",
            ["ContentJP"] = "もう……終わりだ……世も末だ……",
            ["DialogueId"] = 12047112,
            ["GUID"] = "1E289F50",
            ["NextDialogue"] = 12047113,
            ["SpeakNpcId"] = 240042,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289F50",
            },
        [12047113] = {
            ["Content"] = "谁都好，来人，救救我啊——",
            ["ContentJP"] = "誰かっ！誰でもいい！助けてくれ——！",
            ["DialogueId"] = 12047113,
            ["GUID"] = "1E289F7A",
            ["NextDialogue"] = 12047114,
            ["SpeakNpcId"] = 240041,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289F7A",
            },
        [12047114] = {
            ["Content"] = "朱朴，不用和他多费口舌。这个节骨眼上，还是救人要紧。",
            ["ContentJP"] = "シュ、議論してる暇はないわ。人助けが先よ。",
            ["DialogueId"] = 12047114,
            ["GUID"] = "1E289FA4",
            ["NextDialogue"] = 12047115,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289FA4",
            },
        [12047115] = {
            ["Content"] = "明白了，我们走。",
            ["ContentJP"] = "わかってる。行こう。",
            ["DialogueId"] = 12047115,
            ["GUID"] = "1E289FCE",
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120471/1E289FCE",
            },
        [12047201] = {
            ["Content"] = "这些狴犴是暂且击退了，可下一批狴犴何时来袭还未曾可知……大风九章，究竟发生了怎样的异变？",
            ["ContentJP"] = "この街の<Default note=\"text:ビーアン\">狴犴</>は一時的に退けたが、次にいつ襲いかかってくるかわからない……\
一体、大風九章に何が起きているんだ？",
            ["DialogueId"] = 12047201,
            ["GUID"] = "1E28ADEA",
            ["NextDialogue"] = 12047202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28ADEA",
            },
        [12047202] = {
            ["Content"] = "只要与{nickname}会合，真相就能水落石出了，相信{性别：他|她}吧。大家齐心协力，一定能解决这场危机。",
            ["ContentJP"] = "{nickname}と合流できれば、わかるはずよ。皆で力を合わせれば、きっとこの危機を乗り越えられるわ。",
            ["DialogueId"] = 12047202,
            ["GUID"] = "1E28AE14",
            ["NextDialogue"] = 12047203,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE14",
            },
        [12047203] = {
            ["Content"] = "话音刚落，这就有了消息。他们几人正在赶往执律阁的途中，我们也赶紧前去支援吧。",
            ["ContentJP"] = "……噂をすれば、ってとこね。{nickname}たちは執律閣へ向かってるみたい。私たちも行くわよ。",
            ["DialogueId"] = 12047203,
            ["GUID"] = "1E28AE3E",
            ["NextDialogue"] = 12047204,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE3E",
            },
        [12047204] = {
            ["Content"] = "那这里的局面……",
            ["ContentJP"] = "でも、ここは……",
            ["DialogueId"] = 12047204,
            ["GUID"] = "1E28AE68",
            ["NextDialogue"] = 12047205,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE68",
            },
        [12047205] = {
            ["Content"] = "放心，我早有准备。孙宇，赵承，你们两位留在这里，防备陷入混乱的狴犴再流窜到附近。",
            ["ContentJP"] = "大丈夫、ちゃんと手を打ってある。ソンユ、チョウジョウ、ふたりはここに残って、<Default note=\"text:ビーアン\">狴犴</>の再侵入に備えて。",
            ["DialogueId"] = 12047205,
            ["GUID"] = "1E28AE92",
            ["NextDialogue"] = 12047206,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AE92",
            },
        [12047206] = {
            ["Content"] = "此外，麻烦大家随我一起，将这些带来的备用武器分发给这里的居民，让他们也有自卫的力量。",
            ["ContentJP"] = "それから、ほかのみんなは私について、持ってきた武器をここの住民に配って。自分の身を自分で守れるようにね。",
            ["DialogueId"] = 12047206,
            ["GUID"] = "1E28AEBC",
            ["NextDialogue"] = 12047207,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AEBC",
            },
        [12047207] = {
            ["Content"] = "你是说让他们也拿起武器战斗？这真的可行吗？",
            ["ContentJP"] = "彼らに……武器を持たせて戦えと？しかし……",
            ["DialogueId"] = 12047207,
            ["GUID"] = "1E28AEE6",
            ["NextDialogue"] = 12047208,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AEE6",
            },
        [12047208] = {
            ["Content"] = "且不说未经训练的人能否发挥出战力，这些人一直生活在大风九章的规训之下，怕是压根不愿意碰半点武器吧……",
            ["ContentJP"] = "規律に縛られてきた人たちだぞ？ 武器にすら触れたことない連中が……",
            ["DialogueId"] = 12047208,
            ["GUID"] = "1E28AF10",
            ["NextDialogue"] = 12047209,
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF10",
            },
        [12047209] = {
            ["Content"] = "不仅白费力气，还要遭人冷眼，苏乙姐，我们真的要做这种吃力不讨好的事情吗？",
            ["ContentJP"] = "民からは煙たがられ、敵からも恨まれ、こんなことに何の意味があるんだ……",
            ["DialogueId"] = 12047209,
            ["GUID"] = "1E28AF3A",
            ["NextDialogue"] = 12047210,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF3A",
            },
        [12047210] = {
            ["Content"] = "那种事情，不试试怎么知道呢？",
            ["ContentJP"] = "やってみなきゃ、わからないでしょ？",
            ["DialogueId"] = 12047210,
            ["GUID"] = "1E28AF64",
            ["NextDialogue"] = 12047211,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF64",
            },
        [12047211] = {
            ["Content"] = "轻言放弃可不是飘零人的作风。拜托了，请和我一起尝试一下吧！",
            ["ContentJP"] = "私たちの辞書に諦めるって単語はないわ。お願いよ。",
            ["DialogueId"] = 12047211,
            ["GUID"] = "1E28AF8E",
            ["NextDialogue"] = 12047212,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AF8E",
            },
        [12047212] = {
            ["Content"] = "既然你坚持……",
            ["ContentJP"] = "スーがそこまで言うなら……",
            ["DialogueId"] = 12047212,
            ["GUID"] = "1E28AFB8",
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120472/1E28AFB8",
            },
        [12047301] = {
            ["Content"] = "问完一圈了，没人愿意收下……苏乙姐，我们还是别指望这些人了。",
            ["ContentJP"] = "一通り声をかけてみたが……誰も受け取ってくれない。スーさん、こんな奴らに期待するだけ無駄だと思うぜ。",
            ["DialogueId"] = 12047301,
            ["GUID"] = "1E28BE52",
            ["NextDialogue"] = 12047302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BE52",
            },
        [12047302] = {
            ["Content"] = "不要这么轻易下定论。要是仅仅通过一次实验就得出失败的结论，那机枢派的前辈们可发明不出那么多巧夺天工的造物。",
            ["ContentJP"] = "一度や二度の失敗で諦めてたら、<Default note=\"text:きすう\">機枢</>の技なんて、この世に残っちゃいないわよ。",
            ["DialogueId"] = 12047302,
            ["GUID"] = "1E28BE7C",
            ["NextDialogue"] = 12047303,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BE7C",
            },
        [12047303] = {
            ["Content"] = "你……还是不愿意放弃他们吗……",
            ["ContentJP"] = "やっぱり……彼らを諦めたくないのか……",
            ["DialogueId"] = 12047303,
            ["GUID"] = "1E28BEA6",
            ["NextDialogue"] = 12047327,
            ["SpeakNpcId"] = 240036,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BEA6",
            },
        [12047304] = {
            ["Content"] = "在场的各位，请听我说——",
            ["ContentJP"] = "皆さん、聞いてください！",
            ["DialogueId"] = 12047304,
            ["GUID"] = "1E28BED0",
            ["NextDialogue"] = 12047305,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BED0",
            },
        [12047305] = {
            ["Content"] = "现在大风九章正在陷入混乱，我们华胥面临着前所未有的变局。狴犴现在无法保护大家，反而有可能危害到大家的性命。",
            ["ContentJP"] = "今、大風九章は前代未聞の混乱に見舞われています。守ってくれるはずだった<Default note=\"text:ビーアン\">狴犴</>は、今や暴走し、命を脅かす存在となりました。",
            ["DialogueId"] = 12047305,
            ["GUID"] = "1E28BEFA",
            ["NextDialogue"] = 12047306,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BEFA",
            },
        [12047306] = {
            ["Content"] = "我们几位接下来还要奔赴别的战场，无法一直留在这里守护大家。在危机解除之前，能够为自己的生命负起责任的，如今只有各位自己了。",
            ["ContentJP"] = "他にも助けを必要としている人々がいる以上、ここに長居することはできません。危機が去るまで、皆さんの命を守れるのは……あなたたち自身だけです。",
            ["DialogueId"] = 12047306,
            ["GUID"] = "1E28BF24",
            ["NextDialogue"] = 12047307,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BF24",
            },
        [12047307] = {
            ["Content"] = "没错，大风九章教谕我们不要戕身害命，伤害他人。但大风九章从未说过不能为了保卫自己的家园而举起武器！",
            ["ContentJP"] = "たしかに、「自分や他人を傷つける行為」は大風九章に反します。けれど、自分の大切な人を守るために武器を持つことは、禁じられていないはずです！",
            ["DialogueId"] = 12047307,
            ["GUID"] = "1E28BF4E",
            ["NextDialogue"] = 12047308,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BF4E",
            },
        [12047308] = {
            ["Content"] = "是非对错，除了一直以来接受的教谕，更要依靠自己的心去判断！",
            ["ContentJP"] = "正しいか間違ってるかを決めるのは、教えじゃない。あなた自身の心でしょう？",
            ["DialogueId"] = 12047308,
            ["GUID"] = "1E28BF78",
            ["NextDialogue"] = 12047309,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BF78",
            },
        [12047309] = {
            ["Content"] = "你们不妨问问自己的本心，为了保护亲朋好友而拿起武器，真的是罪恶的吗？",
            ["ContentJP"] = "本当に大切な人を守るために武器を取ること――それが罪だって、本気で思ってるのですか？",
            ["DialogueId"] = 12047309,
            ["GUID"] = "1E28BFA2",
            ["NextDialogue"] = 12047310,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BFA2",
            },
        [12047310] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12047310,
            ["GUID"] = "1E28BFCC",
            ["NextDialogue"] = 12047311,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BFCC",
            },
        [12047311] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12047311,
            ["GUID"] = "1E28BFF6",
            ["NextDialogue"] = 12047312,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28BFF6",
            },
        [12047312] = {
            ["Content"] = "也给我来一把武器吧。",
            ["ContentJP"] = "……武器を、くれませんか。",
            ["DialogueId"] = 12047312,
            ["GUID"] = "1E28C020",
            ["NextDialogue"] = 12047313,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C020",
            },
        [12047313] = {
            ["Content"] = "咦，你是刚刚的……",
            ["ContentJP"] = "あれ、あなたはさっきの……",
            ["DialogueId"] = 12047313,
            ["GUID"] = "1E28C04A",
            ["NextDialogue"] = 12047314,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C04A",
            },
        [12047314] = {
            ["Content"] = "恩人，你救了囡囡，我还未向你道谢呢。",
            ["ContentJP"] = "うちのナナを助けて頂いたのに、まだお礼も言えてなかったわね。",
            ["DialogueId"] = 12047314,
            ["GUID"] = "1E28C074",
            ["NextDialogue"] = 12047315,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C074",
            },
        [12047315] = {
            ["Content"] = "要是囡囡出了什么事，我一定会在悔恨中度过一生。哪怕是未来遭到天罚，至少这一刻，我一定要保护我的囡囡！",
            ["ContentJP"] = "あの子に何かあったら、私はきっと、一生悔やんで生きることになってた。たとえ天罰を受けることになっても……今この瞬間だけは、あの子のために戦いたい！",
            ["DialogueId"] = 12047315,
            ["GUID"] = "1E28C09E",
            ["NextDialogue"] = 12047316,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C09E",
            },
        [12047316] = {
            ["Content"] = "自己家人的性命，怎么能全寄托在别人身上。",
            ["ContentJP"] = "自分の家族を守る責任まで、誰かに押しつけて生きたくはないの。",
            ["DialogueId"] = 12047316,
            ["GUID"] = "1E28C0C8",
            ["NextDialogue"] = 12047317,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C0C8",
            },
        [12047317] = {
            ["Content"] = "说得好！武器来嘞，您接好咯！",
            ["ContentJP"] = "いいこと言うねぇ！ほらよ！",
            ["DialogueId"] = 12047317,
            ["GUID"] = "1E28C0F2",
            ["NextDialogue"] = 12047318,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C0F2",
            },
        [12047318] = {
            ["Content"] = "这可是我师傅精心打造的连环弩，扣下扳机就能连珠发射弩箭，包您上手就能使用，没有任何门槛！",
            ["ContentJP"] = "これは俺の師匠が魂込めて作った連撃弩だ。引き金を引けば、矢が次々と飛ぶ！誰でもすぐ使いこなせるぜ！",
            ["DialogueId"] = 12047318,
            ["GUID"] = "1E28C11C",
            ["NextDialogue"] = 12047319,
            ["SpeakNpcId"] = 240034,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C11C",
            },
        [12047319] = {
            ["Content"] = "那，请给我也来一把……",
            ["ContentJP"] = "あの……僕にも、一本、いただけませんか……",
            ["DialogueId"] = 12047319,
            ["GUID"] = "1E28C146",
            ["NextDialogue"] = 12047320,
            ["SpeakNpcId"] = 240046,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C146",
            },
        [12047320] = {
            ["Content"] = "我长一身腱子肉，怎么能眼睁睁看着别人杀敌，自己躲在后面。小伙子，给我也来一把！",
            ["ContentJP"] = "俺だって、腕っぷしには自信ある。誰かが戦ってるのを、黙って見てるだけなんて……そんなのまっぴらだ！若いの、俺にも一本くれ！",
            ["DialogueId"] = 12047320,
            ["GUID"] = "1E28C170",
            ["NextDialogue"] = 12047321,
            ["SpeakNpcId"] = 240047,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C170",
            },
        [12047321] = {
            ["Content"] = "呼、呼……这边的情况，如何了？",
            ["ContentJP"] = "はあっ、はあっ……ここの状況は！？",
            ["DialogueId"] = 12047321,
            ["GUID"] = "1E28C19A",
            ["NextDialogue"] = 12047322,
            ["SpeakNpcId"] = 240048,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C19A",
            },
        [12047322] = {
            ["Content"] = "我们是自泽生阁赶来的草药学徒，若出现伤者，请交由我们照料。我们会尽自己所能，挽救每一条生命的！",
            ["ContentJP"] = "俺たちは<Default note=\"text:たくせいかく\">澤生閣</>の薬師見習いです！ケガ人が出たら、任せてください。一人でも多く、生きて帰れるように全力を尽くします！",
            ["DialogueId"] = 12047322,
            ["GUID"] = "1E28C1C4",
            ["NextDialogue"] = 12047323,
            ["SpeakNpcId"] = 240049,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C1C4",
            },
        [12047323] = {
            ["Content"] = "哈哈！泽生阁的招牌，我放心！这下没有后顾之忧，可以放心御敌了！",
            ["ContentJP"] = "おお、澤生閣か！なら安心だな。これで、思いっきり戦える！",
            ["DialogueId"] = 12047323,
            ["GUID"] = "1E28C1EE",
            ["NextDialogue"] = 12047324,
            ["SpeakNpcId"] = 240047,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C1EE",
            },
        [12047324] = {
            ["Content"] = "恩人，你们是否还有更要紧的事情？赶紧去吧。这边就放心交给我们好了！",
            ["ContentJP"] = "お嬢さん、他にもやるべきことがあるんでしょう？ここはもう、私たちに任せて――あなたたちは、行きなさい！",
            ["DialogueId"] = 12047324,
            ["GUID"] = "1E28C218",
            ["NextDialogue"] = 12047325,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C218",
            },
        [12047325] = {
            ["Content"] = "大家……太好了！",
            ["ContentJP"] = "みんな……ありがとう！",
            ["DialogueId"] = 12047325,
            ["GUID"] = "1E28C242",
            ["NextDialogue"] = 12047326,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C242",
            },
        [12047326] = {
            ["Content"] = "那我们先走了！放心吧，我的同伴们一定能尽早结束这场混乱，还大家一个平安！等我们的好消息！",
            ["ContentJP"] = "じゃあ、行くね！心配しないで、大丈夫！絶対にこの混乱を終わらせて、また平穏を取り戻してみせるから！――いい知らせ、待ってて！",
            ["DialogueId"] = 12047326,
            ["GUID"] = "1E28C26C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120473/1E28C26C",
            },
        [12047327] = {
            ["DialogueId"] = 12047327,
            ["NextDialogue"] = 12047304,
            },
        [12047401] = {
            ["Content"] = "哇，城里到处都是狴犴，乱糟糟的……白还从来没看过这种景象。",
            ["ContentJP"] = "うわあ、<Default note=\"text:ビーアン\">狴犴</>だらけ……めちゃくちゃじゃん。スノウ、こんな光景はじめて見たよ。",
            ["DialogueId"] = 12047401,
            ["GUID"] = "1E28CEBA",
            ["NextDialogue"] = 12047402,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 304003,
                [3] = 303009,
                [4] = 303010,
                [5] = 303008,
                [6] = 303011,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CEBA",
            },
        [12047402] = {
            ["Content"] = "不能再放任这种情况下去了！{nickname}，你带头，我殿后，我们杀出一条路来！",
            ["ContentJP"] = "これ以上、成り行き任せにはできねえ！{nickname}、前を頼む！俺は背中を守る。一気に突破するぞ！",
            ["DialogueId"] = 12047402,
            ["GUID"] = "1E28CEE4",
            ["NextDialogue"] = 12047403,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CEE4",
            },
        [12047403] = {
            ["Content"] = "那这些平民该怎么办？",
            ["ContentJP"] = "でも、ほかの人たちは……",
            ["DialogueId"] = 12047403,
            ["GUID"] = "1E28CF0E",
            ["NextDialogue"] = 12047404,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF0E",
            },
        [12047404] = {
            ["Content"] = "——放心，有我们呢！",
            ["ContentJP"] = "安心して！ここは私たちが引き受けるわ！",
            ["DialogueId"] = 12047404,
            ["GUID"] = "1E28CF38",
            ["NextDialogue"] = 12047405,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF38",
            },
        [12047405] = {
            ["Content"] = "姑奶奶，你来得真及时！",
            ["ContentJP"] = "おお、スーイー！助かったぜ！",
            ["DialogueId"] = 12047405,
            ["GUID"] = "1E28CF62",
            ["NextDialogue"] = 12047406,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF62",
            },
        [12047406] = {
            ["Content"] = "呵，你也不想想我是谁。城中一草一木的情报，都在我的掌控之中。得知城中异变，我可是一收拾好山外山的残局，就带着大家马不停蹄地赶来了。",
            ["ContentJP"] = "ふふん、私を誰だと思ってるの！城の動きは、すべて把握済みよ。異変に気付いてすぐに、事件の後始末をこなして、みんなを引き連れて来たんだから！",
            ["DialogueId"] = 12047406,
            ["GUID"] = "1E28CF8C",
            ["NextDialogue"] = 12047407,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CF8C",
            },
        [12047407] = {
            ["Content"] = "{nickname}，你只管一直向前便是。这里的局面，我会处理好的，放心交给我吧！",
            ["ContentJP"] = "{nickname}、迷わず突き進みなさい！ここは私に任せて！",
            ["DialogueId"] = 12047407,
            ["GUID"] = "1E28CFB6",
            ["NextDialogue"] = 12047408,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CFB6",
            },
        [12047408] = {
            ["Content"] = "那，小仆从，我们赶紧往前……",
            ["ContentJP"] = "そういうことなら、急いで……",
            ["DialogueId"] = 12047408,
            ["GUID"] = "1E28CFE0",
            ["NextDialogue"] = 12047409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28CFE0",
            },
        [12047409] = {
            ["Content"] = "……稍等。",
            ["ContentJP"] = "……お待ちください。",
            ["DialogueId"] = 12047409,
            ["GUID"] = "1E28D00A",
            ["NextDialogue"] = 12047410,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D00A",
            },
        [12047410] = {
            ["Content"] = "抱歉，{nickname}，接下来的路，我……恐怕没法陪伴你了。",
            ["ContentJP"] = "申し訳ありません、{nickname}さん。この先は、同行できません。",
            ["DialogueId"] = 12047410,
            ["GUID"] = "1E28D034",
            ["NextDialogue"] = 12047411,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D034",
            },
        [12047411] = {
            ["Content"] = "倘若大风九章即将告终，在一切成为定局之前，我有必须完成的夙愿……",
            ["ContentJP"] = "大風九章が終わるその時までに、果たさなければならない誓いがあるんです……",
            ["DialogueId"] = 12047411,
            ["GUID"] = "1E28D05E",
            ["NextOptions"] = {
                [1] = 12047412,
                [2] = 12047413,
                },
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D05E",
            },
        [12047412] = {
            ["Content"] = "我之前说过，你不用和我道歉。",
            ["ContentJP"] = "前に言ったよね。謝る必要なんてない。",
            ["DialogueId"] = 12047412,
            ["GUID"] = "1E28D088",
            ["NextDialogue"] = 12047414,
            },
        [12047413] = {
            ["Content"] = "作为朋友，我希望你能完成你的心愿。",
            ["ContentJP"] = "友達として……あなたの願いが叶うことを、願ってるよ。",
            ["DialogueId"] = 12047413,
            ["GUID"] = "1E28D0B2",
            ["NextDialogue"] = 12047414,
            },
        [12047414] = {
            ["Content"] = "……{nickname}，谢谢。",
            ["ContentJP"] = "{nickname}さん……ありがとう。",
            ["DialogueId"] = 12047414,
            ["GUID"] = "1E28D0DC",
            ["NextDialogue"] = 12047415,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D0DC",
            },
        [12047415] = {
            ["Content"] = "我们走吧，去终结这一切！",
            ["ContentJP"] = "さあ、行こう――すべてを終わらせに。",
            ["DialogueId"] = 12047415,
            ["GUID"] = "1E28D106",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120474/1E28D106",
            },
        [12047501] = {
            ["Content"] = "师兄，这次你也是来阻止我们的吗？",
            ["ContentJP"] = "ユーミン……俺たちを阻止するつもりか？",
            ["DialogueId"] = 12047501,
            ["GUID"] = "1E28DF22",
            ["NextDialogue"] = 12047502,
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 203004,
                },
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DF22",
            },
        [12047502] = {
            ["Content"] = "我……",
            ["ContentJP"] = "俺は……",
            ["DialogueId"] = 12047502,
            ["GUID"] = "1E28DF4C",
            ["NextDialogue"] = 12047503,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DF4C",
            },
        [12047503] = {
            ["Content"] = "“职责所在”是吧？你得护卫这大风九章核心区域，我懂，不用说了。",
            ["ContentJP"] = "はいはい、「使命だから」だろう？お前はここの番人ってこと、わかってるよ。",
            ["DialogueId"] = 12047503,
            ["GUID"] = "1E28DF76",
            ["NextDialogue"] = 12047504,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DF76",
            },
        [12047504] = {
            ["Content"] = "{nickname}，你们先走，别在这儿耽搁了。",
            ["ContentJP"] = "{nickname}、あんたらは先に行け。ここは俺に任せろ！",
            ["DialogueId"] = 12047504,
            ["GUID"] = "1E28DFA0",
            ["NextDialogue"] = 12047505,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DFA0",
            },
        [12047505] = {
            ["Content"] = "好。",
            ["ContentJP"] = "わかった。",
            ["DialogueId"] = 12047505,
            ["GUID"] = "1E28DFCA",
            ["NextDialogue"] = 12047506,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DFCA",
            },
        [12047506] = {
            ["Content"] = "师兄，拔出武器吧，在这里拦下你，也是我的职责！",
            ["ContentJP"] = "そういうことで、お前をここで食い止めるのも、俺の「使命」だ。",
            ["DialogueId"] = 12047506,
            ["GUID"] = "1E28DFF4",
            ["NextDialogue"] = 12047507,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28DFF4",
            },
        [12047507] = {
            ["Content"] = "先前我可能还心有动摇，但现在已经不会了！",
            ["ContentJP"] = "以前は迷いもあった。だが、今は違う！",
            ["DialogueId"] = 12047507,
            ["GUID"] = "1E28E01E",
            ["NextDialogue"] = 12047508,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E01E",
            },
        [12047508] = {
            ["Content"] = "你问我的问题，我已经想明白了！是谁规定鱼和熊掌不可兼得？我刻舟偏就全都要！",
            ["ContentJP"] = "「二兎を追う者は一兎も得ず」なんて、誰が決めた？俺は全部、手に入れる！",
            ["DialogueId"] = 12047508,
            ["GUID"] = "1E28E048",
            ["NextDialogue"] = 12047509,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E048",
            },
        [12047509] = {
            ["Content"] = "谁说了人非得为别人而战？若是人人拿起武器，齐心协力，别说区区秽蚀，还有什么能够抵挡其势？这样一个未来，我便证明给你看！",
            ["ContentJP"] = "「誰かのために戦え」？そんな縛りなどいらん。皆が自分の意志で武器を取れば、たかが穢蝕ごとき、敵ではならん！そんな未来を、俺が必ず証明してやる！",
            ["DialogueId"] = 12047509,
            ["GUID"] = "1E28E072",
            ["NextDialogue"] = 12047510,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E072",
            },
        [12047510] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12047510,
            ["GUID"] = "1E28E09C",
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120475/1E28E09C",
            },
        [12047511] = {
            ["DialogueId"] = 12047511,
            ["GUID"] = "12047511.0",
            ["NextDialogue"] = 12047501,
            },
        [12047601] = {
            ["Content"] = "你们，不许再靠近我家囡囡一步！",
            ["ContentJP"] = "うちのナナに、指一本触れさせないよ！",
            ["DialogueId"] = 12047601,
            ["GUID"] = "1E28EF8A",
            ["NextDialogue"] = 12047602,
            ["SpeakNpcId"] = 240044,
            ["VoiceName"] = "voice/$Locale$/story/1204/120476/1E28EF8A",
            },
        [12047602] = {
            ["Content"] = "我今天的英勇表现，怎么也能刊于那个《皓京市声报》上吧！不止是应天尉，我们普通人也能当英雄啊！",
            ["ContentJP"] = "俺の今日の活躍、「皓京市速報」に載ってもおかしくないんじゃないか！？俺ら凡人だって英雄になれるんだぞ！！",
            ["DialogueId"] = 12047602,
            ["GUID"] = "1E28EFB4",
            ["NextDialogue"] = 12047603,
            ["SpeakNpcId"] = 240047,
            ["VoiceName"] = "voice/$Locale$/story/1204/120476/1E28EFB4",
            },
        [12047603] = {
            ["Content"] = "集中精神，这里再缠些绷带！今天，每一个伤者都务必照料好了！",
            ["ContentJP"] = "傷の手当てを急げ！誰ひとりとして、死なせないぞ！",
            ["DialogueId"] = 12047603,
            ["GUID"] = "1E28EFDE",
            ["SpeakNpcId"] = 240048,
            ["VoiceName"] = "voice/$Locale$/story/1204/120476/1E28EFDE",
            },
        [12047701] = {
            ["Content"] = "狴犴纷纷在向执律阁涌来，苏乙姐，怎么会有如此之多……",
            ["ContentJP"] = "<Default note=\"text:ビーアン\">狴犴</>がどんどん押し寄せてきます……スーさん、こんな数、どうすれば……！",
            ["DialogueId"] = 12047701,
            ["GUID"] = "1E28FFF2",
            ["NextDialogue"] = 12047702,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120477/1E28FFF2",
            },
        [12047702] = {
            ["Content"] = "再坚持一下，{nickname}还在上方为我们战斗呢！曙光就在眼前了！",
            ["ContentJP"] = "みんなもう少しの辛抱よ！{nickname}は上で戦っているわ！夜明けはもう目の前よ！！",
            ["DialogueId"] = 12047702,
            ["GUID"] = "1E29001C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120477/1E29001C",
            },
        [12047801] = {
            ["Content"] = "一日未见，你的剑……竟变得如此凌厉。",
            ["ContentJP"] = "……その剣の冴え、まるで別人のようだな。",
            ["DialogueId"] = 12047801,
            ["GUID"] = "1E29105A",
            ["NextDialogue"] = 12047802,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120478/1E29105A",
            },
        [12047802] = {
            ["Content"] = "哈哈！心无旁骛，剑法也自然轻快！师兄，我已找到了前进的方向，你呢？",
            ["ContentJP"] = "迷いが消えりゃ、剣も軽くなる。俺はようやく見つけたんだ。――自分の進むべき道をな。ならお前はどうだ？",
            ["DialogueId"] = 12047802,
            ["GUID"] = "1E291084",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120478/1E291084",
            },
        [12047901] = {
            ["Content"] = "人之为人，皆因有心。以人为本，亦是以心为本。若要华胥万世太平，怎能忽视了心，使得本末倒置，阴阳颠倒？",
            ["ContentJP"] = "人が人であるのは、心があるからこそ。人を軸に据えるというのは、すなわち心を重んじるということ。もし心を軽んじ、理ばかりを押しつければ、華胥に真の安寧は訪れまい。",
            ["DialogueId"] = 12047901,
            ["GUID"] = "1E2920C2",
            ["NextDialogue"] = 12047902,
            ["SpeakNpcId"] = 240050,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2920C2",
            },
        [12047902] = {
            ["Content"] = "人心似川流，若无理之约束便会漫溢。法应如堤岸，顺应心之所向而不违其渊。",
            ["ContentJP"] = "人の心は川の流れ。理で囲わねば、あふれ出して混乱を招く。法とはその堤。心に寄り添い、渓を導くものでなければならぬ。",
            ["DialogueId"] = 12047902,
            ["GUID"] = "1E2920EC",
            ["NextDialogue"] = 12047903,
            ["SpeakNpcId"] = 240051,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2920EC",
            },
        [12047903] = {
            ["Content"] = "心、理平衡，则道生，圣人以道莅天下，其治若水，不争而善应，不令而自正……",
            ["ContentJP"] = "心と理が釣り合ってこそ、道は生まれる。聖人はその道に則り、民を治めた。争うことなく応じ、命ずることなく秩序を得る……それが真の統治というものだ。",
            ["DialogueId"] = 12047903,
            ["GUID"] = "1E292116",
            ["NextDialogue"] = 12047904,
            ["SpeakNpcName"] = "UI_Npc_Name_JuYang",
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292116",
            },
        [12047904] = {
            ["Content"] = "此理，你们二位如何见得？",
            ["ContentJP"] = "君たちは、どう思う？",
            ["DialogueId"] = 12047904,
            ["GUID"] = "1E292140",
            ["NextDialogue"] = 12047905,
            ["SpeakNpcName"] = "UI_Npc_Name_JuYang",
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292140",
            },
        [12047905] = {
            ["Content"] = "两位莫非是……矩和飏先辈？",
            ["ContentJP"] = "……あなた方は……まさか、ノリさま、ヤンさま……！",
            ["DialogueId"] = 12047905,
            ["GUID"] = "1E29216A",
            ["NextDialogue"] = 12047906,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E29216A",
            },
        [12047906] = {
            ["Content"] = "呵呵……千年已逝，吾等意志运转过久，逐渐忘却自身存在，直到被尔等作为唤醒。",
            ["ContentJP"] = "ふふ……千年という時が流れる中で、我らは己の存在すら忘れていた。だが、君たちの声が、我らの意志を呼び覚ましたのだ。",
            ["DialogueId"] = 12047906,
            ["GUID"] = "1E292194",
            ["NextDialogue"] = 12047907,
            ["SpeakNpcId"] = 240050,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292194",
            },
        [12047907] = {
            ["Content"] = "大风九章极兴则人弱，骤亡则人危。舍弃一方以致心、理失衡固不可为，玉石俱焚亦非明德之举。止流，你看破大风九章的弊端，手法却过于极端。",
            ["ContentJP"] = "大風九章が強まれば民は弱り、滅びれば民は混乱する。一方を捨てて心と理の均衡を壊すのは、決して道とは呼べぬ。君がその歪みに気づいたのは確かだ、シリュウ。だが、手段があまりに過激すぎた。",
            ["DialogueId"] = 12047907,
            ["GUID"] = "1E2921BE",
            ["NextDialogue"] = 12047908,
            ["SpeakNpcId"] = 240051,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2921BE",
            },
        [12047908] = {
            ["Content"] = "唯窥破“中庸”、“谐和”之道，方为智者。",
            ["ContentJP"] = "「<Default note=\"text:ちゅうよう\">中庸</>」と「<Default note=\"text:ちょうわ\">調和</>」――それこそが賢者の道なり。",
            ["DialogueId"] = 12047908,
            ["GUID"] = "1E2921E8",
            ["NextDialogue"] = 12047909,
            ["SpeakNpcId"] = 240051,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E2921E8",
            },
        [12047909] = {
            ["Content"] = "使大风九章复归赤子，顺应万民之念。如此，可遂君愿？",
            ["ContentJP"] = "ならば大風九章を本来の姿に戻し、民の声に応える存在にすればよい。……それで、君の願いは叶うのではないか？",
            ["DialogueId"] = 12047909,
            ["GUID"] = "1E292212",
            ["NextOptions"] = {
                [1] = 12047911,
                },
            ["SpeakNpcId"] = 240050,
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E292212",
            },
        [12047910] = {
            ["Content"] = "二位，将手递与我罢。",
            ["ContentJP"] = "ならば、その手を、我らに――",
            ["DialogueId"] = 12047910,
            ["GUID"] = "1E29223C",
            ["SpeakNpcName"] = "UI_Npc_Name_JuYang",
            ["VoiceName"] = "voice/$Locale$/story/1204/120479/1E29223C",
            },
        [12047911] = {
            ["Content"] = "我答应！",
            ["ContentJP"] = "……はい、約束します！",
            ["DialogueId"] = 12047911,
            ["GUID"] = "1E292266",
            ["NextDialogue"] = 12047910,
            },
        [12048001] = {
            ["Content"] = "昔日华胥先人，见秽蚀频生，不忍之，故造大风九章之伟业。望心、理平衡，人、神共治，保华胥万世之安泰。",
            ["ContentJP"] = "昔、大風九章は、穢蝕の乱を憂いた先人たちが築いたものだった。心と理が調和し、神と人とが共に治める平和の華胥を目指して――",
            ["DialogueId"] = 12048001,
            ["GUID"] = "1E29312A",
            ["NextDialogue"] = 12048002,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E29312A",
            },
        [12048002] = {
            ["Content"] = "然烛阴被封，吾独掌大风九章，渐忘四时有序之理。以天罚代仁心，借律典筑高墙……此乃吾之罪衍。",
            ["ContentJP"] = "だが、<Default note=\"text:しょくいん\">燭陰</>を失い、我ひとりが大風九章を担ううちに、いつしか道を見失ってしまった。理に偏り、天罰という名の壁で、民の心を封じた。……それが、我の犯した過ちだ。",
            ["DialogueId"] = 12048002,
            ["GUID"] = "1E293154",
            ["NextDialogue"] = 12048003,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E293154",
            },
        [12048003] = {
            ["Content"] = "孤阴不生，独阳不长，吾已一意孤行了太久。",
            ["ContentJP"] = "陰だけでは命は生まれず、陽だけでも育たない――",
            ["DialogueId"] = 12048003,
            ["GUID"] = "1E29317E",
            ["NextDialogue"] = 12048004,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E29317E",
            },
        [12048004] = {
            ["Content"] = "幸哉！尔以赤子之心，破吾迷障。",
            ["ContentJP"] = "君の純粋な想いが、その迷いを断ってくれた。",
            ["DialogueId"] = 12048004,
            ["GUID"] = "1E2931A8",
            ["NextDialogue"] = 12048005,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E2931A8",
            },
        [12048005] = {
            ["Content"] = "如今阴阳重调，烛阴归位，吾等将重振上古辩法之制，与凡人共治华胥。",
            ["ContentJP"] = "今、ふたたび陰陽は交わり、我らは古の<Default note=\"text:べんぽう\">辯法</>を取り戻す。人と共に、華胥を治める世を、もう一度築こう。",
            ["DialogueId"] = 12048005,
            ["GUID"] = "1E2931D2",
            ["NextDialogue"] = 12048006,
            ["RelatedWikiId"] = {
                [1] = 304003,
                },
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E2931D2",
            },
        [12048006] = {
            ["Content"] = "{nickname}，此枚鳞片，愿君纳之。",
            ["ContentJP"] = "{nickname}、この鱗を授けよう。",
            ["DialogueId"] = 12048006,
            ["GUID"] = "1E2931FC",
            ["NextDialogue"] = 12048007,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E2931FC",
            },
        [12048007] = {
            ["Content"] = "他日君若有需，凡在华胥之土，凭此信物，吾必竭力以助。",
            ["ContentJP"] = "いずれ君が道に迷ったとき、これがきっと助けとなる。",
            ["DialogueId"] = 12048007,
            ["GUID"] = "1E293226",
            ["NextDialogue"] = 12048008,
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E293226",
            },
        [12048008] = {
            ["Content"] = "获得一条神龙的感激……这种感觉还蛮不错的诶！很符合魔王大人的身份！",
            ["ContentJP"] = "ふふ、神龍に感謝されるなんて――ちょっと気分いいかも！魔王としての格ってやつ？ ふふーん！",
            ["DialogueId"] = 12048008,
            ["GUID"] = "1E293250",
            ["NextDialogue"] = 12048009,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E293250",
            },
        [12048009] = {
            ["Content"] = "此间事毕。若无他务，君等可去矣。",
            ["ContentJP"] = "他に用はない……行くが良い。",
            ["DialogueId"] = 12048009,
            ["GUID"] = "1E29327A",
            ["SpeakNpcId"] = 240024,
            ["VoiceName"] = "voice/$Locale$/story/1204/120480/1E29327A",
            },
        [12048101] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12048101,
            ["GUID"] = "1E294192",
            ["NextDialogue"] = 12048102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120481/1E294192",
            },
        [12048102] = {
            ["Content"] = "{nickname}……陪我去一个地方走走，好吗？",
            ["ContentJP"] = "{nickname}……少し散歩に付き合ってくれるかしら？",
            ["DialogueId"] = 12048102,
            ["GUID"] = "1E2941BC",
            ["NextDialogue"] = 12048103,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120481/1E2941BC",
            },
        [12048103] = {
            ["Content"] = "……倘若你还愿意。",
            ["ContentJP"] = "……もし、嫌じゃなければ。",
            ["DialogueId"] = 12048103,
            ["GUID"] = "1E2941E6",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120481/1E2941E6",
            },
        [12048201] = {
            ["Content"] = "止流，我……",
            ["ContentJP"] = "シリュウさん、{性别:僕|私}は……",
            ["DialogueId"] = 12048201,
            ["GUID"] = "1E2951FA",
            ["NextOptions"] = {
                [1] = 12048202,
                [2] = 12048203,
                [3] = 12048204,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2951FA",
            },
        [12048202] = {
            ["Content"] = "（并没有生她的气。）",
            ["ContentJP"] = "もう怒っていない。",
            ["DialogueId"] = 12048202,
            ["GUID"] = "1E295224",
            ["NextDialogue"] = 12048205,
            },
        }
  end },
  { MinKey = 12048203, MaxKey = 12049105, Loader = function()
      return {
        [12048203] = {
            ["Content"] = "（还没有能够原谅她。）",
            ["ContentJP"] = "まだ許せない。",
            ["DialogueId"] = 12048203,
            ["GUID"] = "1E29524E",
            ["NextDialogue"] = 12048209,
            },
        [12048204] = {
            ["Content"] = "（让止流猜。）",
            ["ContentJP"] = "シリュウに考えさせる。",
            ["DialogueId"] = 12048204,
            ["GUID"] = "1E295278",
            ["NextDialogue"] = 12048211,
            },
        [12048205] = {
            ["Content"] = "你突然这么拘谨，我好不习惯……放心吧，我早就不生气了。相反，我很感谢你让我成为英雄。",
            ["ContentJP"] = "{性别:そんなに改まられると、逆に落ち着かないな。……怒ってなんかないよ。むしろ……ありがとう、僕を「英雄」にしてくれて。|そんなに改まられると、逆に落ち着かないね。……怒ってなんかないよ。むしろ……ありがとう、私を「英雄」にしてくれて。}",
            ["DialogueId"] = 12048205,
            ["GUID"] = "1E2952A2",
            ["NextDialogue"] = 12048206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2952A2",
            },
        [12048206] = {
            ["Content"] = "倒是你坦诚得让我有些意外。我原本以为你会更……心安理得一些？",
            ["ContentJP"] = "……ただ、あなたがあまりに素直だから、ちょっと驚いたよ。",
            ["DialogueId"] = 12048206,
            ["GUID"] = "1E2952CC",
            ["NextDialogue"] = 12048207,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2952CC",
            },
        [12048207] = {
            ["Content"] = "如果我像计划中一样死在了太虚陵，或许会如此吧……我可以心安理得地告诉自己，在生命的筹码面前，一切都已经无足轻重。",
            ["ContentJP"] = "……もし予定通り、私が太虚陵で命を落としていたら、きっと今ごろは何も感じなかったと思う。すべてがどうでもいい、そう言い聞かせて……終わらせるつもりだった。",
            ["DialogueId"] = 12048207,
            ["GUID"] = "1E2952F6",
            ["NextDialogue"] = 12048208,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2952F6",
            },
        [12048208] = {
            ["Content"] = "但我未曾算到，我会托你的福活下来。",
            ["ContentJP"] = "でもね。あなたのおかげで、私は生き残ってしまった。",
            ["DialogueId"] = 12048208,
            ["GUID"] = "1E295320",
            ["NextDialogue"] = 12048213,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295320",
            },
        [12048209] = {
            ["Content"] = "你之前对我的利用，我还没能够原谅你。或许之后也不能。",
            ["ContentJP"] = "……正直に言えば、あなたのあのやり方、まだ完全に許せてはいない。この先も、どうなるかはわからない。",
            ["DialogueId"] = 12048209,
            ["GUID"] = "1E29534A",
            ["NextDialogue"] = 12048210,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29534A",
            },
        [12048210] = {
            ["Content"] = "但是时间总是能够冲刷一切，以后的事情谁也无法断定。所以，让我们把这个问题交给未来吧。",
            ["ContentJP"] = "でも、時間が経てば変わることもある。\
その決断は、{性别:未来の僕たちに委ねよう。|未来の私たちに委ねましょう。}",
            ["DialogueId"] = 12048210,
            ["GUID"] = "1E295374",
            ["NextDialogue"] = 12048213,
            ["SpeakNpcId"] = 0,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295374",
            },
        [12048211] = {
            ["Content"] = "你不是很擅长卜算人心吗？那来猜猜看吧，我究竟有没有原谅你。",
            ["ContentJP"] = "シリュウさんって、{性别:人の心を読むのが得意なんでろう？じゃあ、僕がどう思ってるのか、当ててみてな。|人の心を読むのが得意なんでしょ？じゃあ、私がどう思ってるのか、当ててみてよ。}",
            ["DialogueId"] = 12048211,
            ["GUID"] = "1E29539E",
            ["NextDialogue"] = 12048212,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29539E",
            },
        [12048212] = {
            ["Content"] = "……呵呵。这是我遇到过最难的卜算，我恐怕要用毕生来寻找这个答案了。",
            ["ContentJP"] = "……ふふっ、それはきっと、私が生涯解けない問いかもね。",
            ["DialogueId"] = 12048212,
            ["GUID"] = "1E2953C8",
            ["NextDialogue"] = 12048213,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2953C8",
            },
        [12048213] = {
            ["Content"] = "止流，还有一件事我想告诉你……人心是复杂的。",
            ["ContentJP"] = "シリュウさん、もう一つ伝えて置きたいことがある。",
            ["DialogueId"] = 12048213,
            ["GUID"] = "1E2953F2",
            ["NextDialogue"] = 12048214,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2953F2",
            },
        [12048214] = {
            ["Content"] = "人有懦弱的一面，就有勇敢的一面。有为恶的一面，就有善良的一面。",
            ["ContentJP"] = "人には、いろんな面がある。臆病なところも、勇気あるところも。時に罪を犯すこともあれば、優しさを見せることだってある。",
            ["DialogueId"] = 12048214,
            ["GUID"] = "1E29541C",
            ["NextDialogue"] = 12048215,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29541C",
            },
        [12048215] = {
            ["Content"] = "人永远能够挣脱所谓的宿命和计划，创造出新的意外。",
            ["ContentJP"] = "でも――人は、そんな自分自身から逃げずに、変わっていける。宿命も、計画も、意志次第で超えていける。",
            ["DialogueId"] = 12048215,
            ["GUID"] = "1E295446",
            ["NextDialogue"] = 12048216,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295446",
            },
        [12048216] = {
            ["Content"] = "所以……你可以试着去更加信任别人，而不是自己背负起一切。",
            ["ContentJP"] = "だから……一人で背負い込まないで。これからは、もっと周りを頼って、生きてほしい。",
            ["DialogueId"] = 12048216,
            ["GUID"] = "1E295470",
            ["NextDialogue"] = 12048217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295470",
            },
        [12048217] = {
            ["Content"] = "从今往后，我不希望你随意将自己的生命作为筹码。活下去，见证华胥的未来，好吗？答应我。",
            ["ContentJP"] = "それから、自分の命を蔑ろにしないで。生きて、未来の華胥を見届けるって約束して。",
            ["DialogueId"] = 12048217,
            ["GUID"] = "1E29549A",
            ["NextDialogue"] = 12048218,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E29549A",
            },
        [12048218] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12048218,
            ["GUID"] = "1E2954C4",
            ["NextDialogue"] = 12048219,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2954C4",
            },
        [12048219] = {
            ["Content"] = "虽然你大概早已不需要我的道谢……但是谢谢你，{nickname}。",
            ["ContentJP"] = "ふふ、必要ないとは思うけど、言わせて……本当にありがとう。",
            ["DialogueId"] = 12048219,
            ["GUID"] = "1E2954EE",
            ["NextDialogue"] = 12048220,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E2954EE",
            },
        [12048220] = {
            ["Content"] = "在冰湖城偶遇你，大约是命运对我最深的一次眷顾。",
            ["ContentJP"] = "あの日、アイスレイク城で出会ったのは……運命だったのかもね。",
            ["DialogueId"] = 12048220,
            ["GUID"] = "1E295518",
            ["NextDialogue"] = 12048221,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295518",
            },
        [12048221] = {
            ["Content"] = "我们到了，陪我上完这柱香吧。",
            ["ContentJP"] = "さあ。あの人のために、線香を一本あげましょう。",
            ["DialogueId"] = 12048221,
            ["GUID"] = "1E295542",
            ["NextDialogue"] = 12048222,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120482/1E295542",
            },
        [12048222] = {
            ["DialogueId"] = 12048222,
            ["GUID"] = "12048222.0",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12048201.T_Story_Recall_12048201'",
            ["bNotRecall"] = 1,
            },
        [12048223] = {
            ["DialogueId"] = 12048223,
            ["NextDialogue"] = 12048224,
            },
        [12048224] = {
            ["DialogueId"] = 12048224,
            ["NextDialogue"] = 12048201,
            },
        [12048304] = {
            ["Content"] = "你竟能做到如此地步……",
            ["ContentJP"] = "まさか、あなたがこんなことを成し遂げるなんてね。",
            ["DialogueId"] = 12048304,
            ["GUID"] = "1E2962E0",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E2962E0",
            },
        [12048305] = {
            ["Content"] = "{nickname}，虽然初次见面时，我便从你身上窥见了潜龙之姿，但你所做的一切，确是连我的算筹都未曾算到的。",
            ["ContentJP"] = "初めて会ったとき、私は感じたわ。君の内には龍のような力が眠っているとね。けどあなたは、私の読みを遥かに超えてみせた。",
            ["DialogueId"] = 12048305,
            ["GUID"] = "1E29630A",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E29630A",
            },
        [12048306] = {
            ["Content"] = "怎么样，止流掌柜？现在愿意听进去我说的话了吗？",
            ["ContentJP"] = "どう、シリュウさん？少しは{性别:僕|私}の言葉を聞いてくれる気になった？",
            ["DialogueId"] = 12048306,
            ["GUID"] = "1E296334",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296334",
            },
        [12048307] = {
            ["Content"] = "……愿赌服输。",
            ["ContentJP"] = "……私の負けよ。",
            ["DialogueId"] = 12048307,
            ["GUID"] = "1E29635E",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E29635E",
            },
        [12048308] = {
            ["Content"] = "以和鸣之力干预我与烛阴的契约，借助祭献仪式将力量转移到自己身上，从而争取到使用均天玉律的一线之机……这般冒险的举动，也只有你才能做到了。",
            ["ContentJP"] = "レゾナンスで、私と<Default note=\"text:しょくいん\">燭陰</>の契約に干渉し、供犠の力を逆に自分のものとした――そんな無茶をやってのける者が、他にいるとは思えないわ。",
            ["DialogueId"] = 12048308,
            ["GUID"] = "1E296388",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296388",
            },
        [12048309] = {
            ["Content"] = "但只有这一点还不够。机枢派的那半壁均天玉律，你又是从何处寻得？",
            ["ContentJP"] = "ただそれだけではまだ足りない。それと……あなたの持っていた、もう半分の均天玉律。一体どこで？",
            ["DialogueId"] = 12048309,
            ["GUID"] = "1E2963B2",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E2963B2",
            },
        [12048310] = {
            ["Content"] = "山外山遇袭时，飘零人将我带去偃隐宫底寻找转机，均天玉律是在那里发现的。",
            ["ContentJP"] = "山外山が襲撃されたとき、{性别:スーイーが偃隠宮まで連れて行ってくれてな……そこで、見つけたんだ。|スーイーが偃隠宮まで連れて行ってくれてね……そこで、見つけたの。}",
            ["DialogueId"] = 12048310,
            ["GUID"] = "1E2963DC",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E2963DC",
            },
        [12048311] = {
            ["Content"] = "我多年苦寻无果之物，原来藏在那里……也罢。我心中只留有毁灭的决意，这样的物件交由你，才是更好的选择。",
            ["ContentJP"] = "長年探し続けても見つからなかったのに……まさか、そんな場所に……いや、それでいい。破壊しか見えていなかった私より、あなたの手にある方がふさわしいわ。",
            ["DialogueId"] = 12048311,
            ["GUID"] = "1E296406",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296406",
            },
        [12048312] = {
            ["Content"] = "止流掌柜，有什么话待会再说吧。前面还有人在等着我们呢。",
            ["ContentJP"] = "{性别:……その話はあとにしよう。僕たちを待ってる人が、この先にいるんだ。|……その話はあとにしよう。私たちを待ってる人が、この先にいるの。}",
            ["DialogueId"] = 12048312,
            ["GUID"] = "1E296430",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/1E296430",
            },
        [12048313] = {
            ["Content"] = "其实那时在执律阁顶意外抗住太皓的一击……甚至更早之前，从伤及烛阴开始，我就非常意外。与神明交手，这种事情我以前连想都没想过。",
            ["ContentJP"] = "実はさ……あのとき<Default note=\"text:しつりつかく\">執律閣</>のいちばん上で、うっかり<Default note=\"text:たいこう\">太皓</>の一撃を受け止めた時から……いや、もっと前に、あの<Default note=\"text:しょくいん\">燭陰</>に傷つけられた時から？本当に、びっくりしたんだ。「え、今のマジ？」ってなったよ。神様と剣をぶつけ合うなんて、想像すらしてなかったし。",
            ["DialogueId"] = 12048313,
            ["GUID"] = "12048313.0",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/12048313",
            },
        [12048314] = {
            ["Content"] = "是因为……和鸣之力与大风九章创立者的力量系出同源吗？",
            ["ContentJP"] = "もしかして……「レゾナンス」って、<Default note=\"text:たいふうきゅうしょう\">大風九章</>を作った人の力と、同じところから来てるからなのかな？",
            ["DialogueId"] = 12048314,
            ["GUID"] = "12048314.0",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/12048314",
            },
        [12048315] = {
            ["Content"] = "不错。大风九章这一术式，从一开始便是为了放大飏的力量而布设。术式的加持，足以让你触及神明。",
            ["ContentJP"] = "そうよ。大風九章という術式は最初から、「ヤン」の力を増幅させるために仕組まれていたの。術式の加護がある限り、神の領域に達していてもおかしくないわ。",
            ["DialogueId"] = 12048315,
            ["GUID"] = "12048315.0",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120483/12048315",
            },
        [12048401] = {
            ["Content"] = "这是什么不详的东西，不要给我，快拿走！",
            ["ContentJP"] = "そ、そんな不吉な物を近づけるな！早く持って行け！",
            ["DialogueId"] = 12048401,
            ["FacialId"] = {
                [1] = "240067:Cin_Angry01",
                },
            ["GUID"] = "1E2972CA",
            ["SpeakNpcId"] = 240067,
            ["TalkActionId"] = {
                [1] = "240067:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120484/1E2972CA",
            },
        [12048402] = {
            ["Content"] = "我、我连一只鸡都没有杀过，更别提拿起武器抵抗敌人了……",
            ["ContentJP"] = "わ、私……鶏一羽殺したことがないのよ……武器なんて……とてもじゃないけど無理……",
            ["DialogueId"] = 12048402,
            ["FacialId"] = {
                [1] = "240068:Cin_Nervous",
                },
            ["GUID"] = "1E2972F4",
            ["SpeakNpcId"] = 240068,
            ["TalkActionId"] = {
                [1] = "240068:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120484/1E2972F4",
            },
        [12048403] = {
            ["Content"] = "动了武就会触犯天条，这是万万不能拿呀呐！",
            ["ContentJP"] = "武器を手に取るなんて……天律に触れるぞ！絶対に受け取れん！",
            ["DialogueId"] = 12048403,
            ["FacialId"] = {
                [1] = "240066:Cin_Angry02",
                },
            ["GUID"] = "1E29731E",
            ["SpeakNpcId"] = 240066,
            ["TalkActionId"] = {
                [1] = "240066:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120484/1E29731E",
            },
        [12048501] = {
            ["Content"] = "{nickname}，我就知道你能做到！",
            ["ContentJP"] = "{nickname}、よかった、本当に……！あんたなら絶対にやり遂げられるって信じてたわ！",
            ["DialogueId"] = 12048501,
            ["FacialId"] = {
                [1] = "240026:Smile02",
                },
            ["GUID"] = "1E298332",
            ["NextDialogue"] = 12048502,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Excited02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298332",
            },
        [12048502] = {
            ["Content"] = "白龙神君在前面……祂好像有话想和你说。",
            ["ContentJP"] = "ねぇ、白龍様が……なにやら、あんたに話したいことがあるみたい。",
            ["DialogueId"] = 12048502,
            ["FacialId"] = {
                [1] = "240026:None",
                },
            ["GUID"] = "1E29835C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29835C",
            },
        [12048503] = {
            ["Content"] = "呼，想不到短短一天内发生了这么多事……我平时连做梦也不会梦到这样的景象。",
            ["ContentJP"] = "ふぅ……たった一日で、いろんなことが起きたね。今までなら想像もできなかった光景だよ。",
            ["DialogueId"] = 12048503,
            ["FacialId"] = {
                [1] = "240026:Smile01",
                },
            ["GUID"] = "1E298386",
            ["NextDialogue"] = 12048504,
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298386",
            },
        [12048504] = {
            ["Content"] = "之后可要有的忙了。得把大家的陈年案情整理出来，一件件翻案。",
            ["ContentJP"] = "昔の事件記録も、今のうちに整理しなきゃ。",
            ["DialogueId"] = 12048504,
            ["GUID"] = "1E2983B0",
            ["NextDialogue"] = 12048505,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2983B0",
            },
        [12048505] = {
            ["Content"] = "若是见义勇为就既往不咎。当然，要真是有作奸犯科的家伙混进去，那可得让他好好地受罚！",
            ["ContentJP"] = "正しいものは正しく、そうじゃないものはきちんと裁かないと。",
            ["DialogueId"] = 12048505,
            ["GUID"] = "1E2983DA",
            ["NextDialogue"] = 12048506,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2983DA",
            },
        [12048506] = {
            ["Content"] = "不过……我们平安再见了。{nickname}，这个约定，我们都做到了。",
            ["ContentJP"] = "でも……また、こうして笑って会えてよかった。{nickname}、ちゃんと約束を果たしてくれたようね！",
            ["DialogueId"] = 12048506,
            ["GUID"] = "1E298404",
            ["SpeakNpcId"] = 240026,
            ["TalkActionId"] = {
                [1] = "240026:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298404",
            },
        [12048507] = {
            ["Content"] = "好样的，{nickname}！",
            ["ContentJP"] = "やるじゃねぇか、{nickname}！",
            ["DialogueId"] = 12048507,
            ["FacialId"] = {
                [1] = "240013:Smile02",
                },
            ["GUID"] = "1E29842E",
            ["NextDialogue"] = 12048508,
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240013:ConfidentR_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29842E",
            },
        [12048508] = {
            ["Content"] = "虽然早知道你是豪侠高手，但没想到你能以一人之力鏖战双龙还不落下风，不亏是我刻舟的{性别：兄弟|挚友}！",
            ["ContentJP"] = "腕が立つのは知ってたが……まさか双龍相手にここまでやれるとはな。さすがは、このカシュウの{性别:兄弟|マブダチ}だ！",
            ["DialogueId"] = 12048508,
            ["GUID"] = "1E298458",
            ["NextDialogue"] = 12048509,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298458",
            },
        [12048509] = {
            ["Content"] = "看得我心痒痒的。之后得闲，我们再找个地方过两招吧！",
            ["ContentJP"] = "なんだかムズムズしてきたな。今度どっかで一勝負しようぜ！",
            ["DialogueId"] = 12048509,
            ["GUID"] = "1E298482",
            ["SpeakNpcId"] = 240013,
            ["TalkActionId"] = {
                [1] = "240013:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298482",
            },
        [12048510] = {
            ["Content"] = "……{nickname}，未想到，你竟能完成如此壮举。",
            ["ContentJP"] = "……{nickname}、まさか本当にやってのけるとは思わなかったよ。",
            ["DialogueId"] = 12048510,
            ["FacialId"] = {
                [1] = "240100:Smile01",
                },
            ["GUID"] = "1E2984AC",
            ["NextDialogue"] = 12048511,
            ["SpeakNpcId"] = 240100,
            ["TalkActionId"] = {
                [1] = "240100:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2984AC",
            },
        [12048511] = {
            ["Content"] = "我自皈依大风九章后，不过是随波逐流，如风中蓬草。期间所做所为，不乏违心之举。",
            ["ContentJP"] = "大風九章に身を置いてからというもの、俺はただ命じられるがままに動いた。時には、自分でも納得できないことまでした。",
            ["DialogueId"] = 12048511,
            ["GUID"] = "1E2984D6",
            ["NextDialogue"] = 12048512,
            ["SpeakNpcId"] = 240100,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E2984D6",
            },
        [12048512] = {
            ["Content"] = "说来惭愧，我本以为世事两难，大风九章不堪之处只能这样忍受过去了。从未想过大风九章竟有修正之法。",
            ["ContentJP"] = "恥ずかしい話だが……ずっと、矛盾を抱えながらも「仕方ない」と思い込んでいたんだ。だが、お前が教えてくれた。どんなものでも、変えられるとね。",
            ["DialogueId"] = 12048512,
            ["GUID"] = "1E298500",
            ["NextDialogue"] = 12048513,
            ["SpeakNpcId"] = 240100,
            ["TalkActionId"] = {
                [1] = "240100:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298500",
            },
        [12048513] = {
            ["Content"] = "煜明，你打算回山外山看看吗？",
            ["ContentJP"] = "……ユーミン。<Default note=\"text:さんがいさん\">山外山</>に、戻るつもりは？",
            ["DialogueId"] = 12048513,
            ["GUID"] = "1E29852A",
            ["NextDialogue"] = 12048514,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "240100:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29852A",
            },
        [12048514] = {
            ["Content"] = "……我现在心如乱麻，需要一段时间理清头绪。",
            ["ContentJP"] = "……今の私には、まだ答えが出せない。気持ちの整理がつくまで、少し時間がほしい。",
            ["DialogueId"] = 12048514,
            ["FacialId"] = {
                [1] = "240100:Sad01",
                },
            ["GUID"] = "1E298554",
            ["NextDialogue"] = 12048515,
            ["SpeakNpcId"] = 240100,
            ["TalkActionId"] = {
                [1] = "240100:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E298554",
            },
        [12048515] = {
            ["Content"] = "待我想清之时，或许吧。",
            ["ContentJP"] = "考えがまとまったら、もしかしたら……ね。",
            ["DialogueId"] = 12048515,
            ["GUID"] = "1E29857E",
            ["SpeakNpcId"] = 240100,
            ["VoiceName"] = "voice/$Locale$/story/1204/120485/1E29857E",
            },
        [12048601] = {
            ["Content"] = "演出目前还没有，请等候后续制作",
            ["DialogueId"] = 12048601,
            ["GUID"] = "1E29939A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120486/1E29939A",
            },
        [12048602] = {
            ["Content"] = "玩法目前还没有，请等候后续制作",
            ["DialogueId"] = 12048602,
            ["GUID"] = "1E2993C4",
            ["VoiceName"] = "voice/$Locale$/story/1204/120486/1E2993C4",
            },
        [12048701] = {
            ["Content"] = "小仆从，我已经占好位置啦！你赶紧去买药吧，要快去快回哦。",
            ["ContentJP"] = "我が下僕よ、席はちゃんと取ったぞ！はやく薬を買ってこよう！",
            ["DialogueId"] = 12048701,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "1E29A402",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A402",
            },
        [12048702] = {
            ["Content"] = "原来如此！只要这样动一点小小的手脚……嘿嘿嘿……",
            ["ContentJP"] = "なるほど！こうしてちょっとだけ小細工をすれば…ぐへへ…",
            ["DialogueId"] = 12048702,
            ["GUID"] = "1E29A42C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A42C",
            },
        [12048703] = {
            ["Content"] = "干得好，小仆从！",
            ["ContentJP"] = "よくやった、下僕！",
            ["DialogueId"] = 12048703,
            ["GUID"] = "1E29A456",
            ["NextDialogue"] = 12048704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A456",
            },
        [12048704] = {
            ["Content"] = "这样就暂时不需要担心被它们发现了，还是你的办法多！",
            ["ContentJP"] = "これで気づかれないよな。さすがは我が下僕、頭脳明晰だね！",
            ["DialogueId"] = 12048704,
            ["GUID"] = "1E29A480",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A480",
            },
        [12048705] = {
            ["Content"] = "弄坏了这么多偃雀，该不会找我们索赔吧……小仆从，我们跑快点。",
            ["ContentJP"] = "これだけ<Default note=\"text:えんじゃく\">偃雀</>を壊したから、弁償する必要はあるよね……下僕、念のためはやく逃げよう。",
            ["DialogueId"] = 12048705,
            ["GUID"] = "1E29A4AA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A4AA",
            },
        [12048707] = {
            ["Content"] = "哇啊啊啊……涌出来好多应天尉和狴犴，这个突然出现的大罩子又是什么！",
            ["ContentJP"] = "うわあああああ…<Default note=\"text:おうてんい\">応天尉</>に<Default note=\"text:ビーアン\">狴犴</>、いっぱい出ちゃったよ！それにあのデカいカバーってなんだよ！",
            ["DialogueId"] = 12048707,
            ["GUID"] = "1E29A4FE",
            ["NextDialogue"] = 12048708,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A4FE",
            },
        [12048708] = {
            ["Content"] = "来的正好！{nickname}，你去想办法破坏那两座玄俑，我来会会这些刍狗！",
            ["ContentJP"] = "おお！{nickname}。ちょうどいいところに来たぜ！あんた、そこの二つの石人形は任せたな！俺はこの虫けらどもと相手してやる！",
            ["DialogueId"] = 12048708,
            ["GUID"] = "1E29A528",
            ["NextDialogue"] = 12048709,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A528",
            },
        [12048709] = {
            ["Content"] = "被绑了这么久，我刻某人正愁没有地方活动活动筋骨呢！",
            ["ContentJP"] = "あれだけ縛れたら、このカシュウ様はどうしても体を動かしたくなっちまうよ！",
            ["DialogueId"] = 12048709,
            ["GUID"] = "1E29A552",
            ["NextDialogue"] = 12048710,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A552",
            },
        [12048710] = {
            ["Content"] = "这个人的字典里到底有没有害怕这个词啊！",
            ["ContentJP"] = "この人、ぜんぜん怖いってもんは知ってないよな…",
            ["DialogueId"] = 12048710,
            ["GUID"] = "1E29A57C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A57C",
            },
        [12048712] = {
            ["Content"] = "{nickname}，那座镇律玄俑快要充能完毕了，别让他们得逞！",
            ["ContentJP"] = "{nickname}、そこの「<Default note=\"text:ちんりつのせきじん\">鎮律の石人</>」ってやつも間もなくチャージ完了だ、思うままにはさせないぞ！",
            ["DialogueId"] = 12048712,
            ["GUID"] = "1E29A5D0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A5D0",
            },
        [12048713] = {
            ["Content"] = "小仆从，这边的玄俑也不太妙的样子！快想想办法！",
            ["ContentJP"] = "下僕よ、こっちの石人形もやばそう！なんとかしないと！",
            ["DialogueId"] = 12048713,
            ["GUID"] = "1E29A5FA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A5FA",
            },
        [12048714] = {
            ["Content"] = "干得好！就这样一鼓作气，把另一座玄俑也解决掉吧！",
            ["ContentJP"] = "よくやった！このまま一気にもう一つの石人形をやっちまえ！",
            ["DialogueId"] = 12048714,
            ["GUID"] = "1E29A624",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A624",
            },
        [12048716] = {
            ["Content"] = "完了完了，突然冒出来好多追兵跟在我们屁股后面……",
            ["ContentJP"] = "大変だ大変だ！急に後ろから追手がいっぱい湧いてくるぞ！",
            ["DialogueId"] = 12048716,
            ["GUID"] = "1E29A678",
            ["NextDialogue"] = 12048717,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A678",
            },
        [12048717] = {
            ["Content"] = "你不觉得他们那追又追不上的咬牙切齿的表情，欣赏起来别有一番乐趣吗？",
            ["ContentJP"] = "ほぉ？追い続けても追いつかない恨めしい顔が、結構気に入ったとは思わないかい？",
            ["DialogueId"] = 12048717,
            ["GUID"] = "1E29A6A2",
            ["NextDialogue"] = 12048718,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A6A2",
            },
        [12048718] = {
            ["Content"] = "我、我才没有这种闲工夫——小仆从，我们跑快点！",
            ["ContentJP"] = "そん、そんな思いはするもんか！下僕よ、急げ！",
            ["DialogueId"] = 12048718,
            ["GUID"] = "1E29A6CC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A6CC",
            },
        [12048720] = {
            ["Content"] = "哼哼……坏鸟，汝等克星已至，还不快速速来降！",
            ["ContentJP"] = "ふふん…怪鳥め、汝らの天敵はここに来たれり、速やかに降伏せよ！",
            ["DialogueId"] = 12048720,
            ["GUID"] = "1E29A720",
            ["NextDialogue"] = 12048721,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A720",
            },
        [12048721] = {
            ["Content"] = "……白，你这又是从哪里学来的台词？鸟又听不懂你说话。",
            ["ContentJP"] = "スノウ、それはどこで学んだセリフ{性别:だ|なの}？鳥はスノウの言葉を理解しない{性别:ぞ|よ}。",
            ["DialogueId"] = 12048721,
            ["GUID"] = "1E29A74A",
            ["NextDialogue"] = 12048722,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A74A",
            },
        [12048722] = {
            ["Content"] = "诶嘿嘿，是刚刚听到有人在念“话本”，台词还挺威风的。被你听出来啦？",
            ["ContentJP"] = "えへへ…ちょうど先まで小説の話を読み聞かせる人がいたんだ…結構かっこいいセリフだからつい…\
下僕も聞いたことある？",
            ["DialogueId"] = 12048722,
            ["GUID"] = "1E29A774",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A774",
            },
        [12048724] = {
            ["Content"] = "…………",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12048724,
            ["GUID"] = "1E29A7C8",
            ["NextDialogue"] = 12048725,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A7C8",
            },
        [12048725] = {
            ["Content"] = "苏乙，怎么了？你是在担心他们吗？",
            ["ContentJP"] = "スーイー、どうしたの？彼らのこと、心配してるの{性别:か|}？",
            ["DialogueId"] = 12048725,
            ["GUID"] = "1E29A7F2",
            ["NextDialogue"] = 12048726,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A7F2",
            },
        [12048726] = {
            ["Content"] = "嗯……我在想这里能不能找到我要的东西，会不会只是无用功。",
            ["ContentJP"] = "私は……ただ、ずっと探しているもの、本当に見つかるかなって。無駄足だったら嫌だなって……",
            ["DialogueId"] = 12048726,
            ["GUID"] = "1E29A81C",
            ["NextDialogue"] = 12048727,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A81C",
            },
        [12048727] = {
            ["Content"] = "但开弓没有回头箭。一旦下定决心，就要摈除杂念，全力以赴，这是姑姑教我的。",
            ["ContentJP"] = "でも、もう決めたんだ。ここで引くわけにはいかないでしょ。「覚悟を決めた道なら、一切の雑念を捨てて、張り切って進め」――それが叔母さんの教えだったの。",
            ["DialogueId"] = 12048727,
            ["GUID"] = "1E29A846",
            ["NextDialogue"] = 12048728,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A846",
            },
        [12048728] = {
            ["Content"] = "好。那让我们一起全力以赴吧！",
            ["ContentJP"] = "よし、一緒に張り切っていこう！",
            ["DialogueId"] = 12048728,
            ["GUID"] = "1E29A870",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A870",
            },
        [12048730] = {
            ["Content"] = "这里的重力有点蹊跷……这也是机枢派先人的手笔吗？",
            ["ContentJP"] = "ここの重力、ちょっとおかしいわ……これも<Default note=\"text:きすうは\">機枢派</>の先人が作った仕掛けなのかしら？",
            ["DialogueId"] = 12048730,
            ["GUID"] = "1E29A8C4",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A8C4",
            },
        [12048732] = {
            ["Content"] = "{nickname}，看到平台两旁的隼型机枢巨炮了吗？那就是神机铳！",
            ["ContentJP"] = "{nickname}、あそこの両脇にあるハヤブサのような巨砲、見えるかしら？あれが噂の<Default note=\"text:しんきじゅう\">神機銃</>よ！",
            ["DialogueId"] = 12048732,
            ["GUID"] = "1E29A918",
            ["NextDialogue"] = 12048733,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A918",
            },
        [12048733] = {
            ["Content"] = "只要用却邪为它指明方位，神机铳就能提供从空中倾泻而下的火力支援！",
            ["ContentJP"] = "<Default note=\"text:きこうせいぎょばん・じゃばらい\">機巧制御盤・邪払</>で方向を教えてあげれば、神機銃がそこに砲火の雨を降らせるの！",
            ["DialogueId"] = 12048733,
            ["GUID"] = "1E29A942",
            ["NextDialogue"] = 12048734,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A942",
            },
        [12048734] = {
            ["Content"] = "现在，好好感受炮火的威力吧！",
            ["ContentJP"] = "さあ、我らの砲火をじっくり味わえなさい！",
            ["DialogueId"] = 12048734,
            ["GUID"] = "1E29A96C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A96C",
            },
        [12048736] = {
            ["Content"] = "爽快，实在爽快——",
            ["ContentJP"] = "うひょ－すっきりした！",
            ["DialogueId"] = 12048736,
            ["GUID"] = "1E29A9C0",
            ["NextDialogue"] = 12048737,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A9C0",
            },
        [12048737] = {
            ["Content"] = "你们从何处寻来这巨炮的启动方式？简直是天降奇兵啊！",
            ["ContentJP"] = "どうやってあのバカでかい大砲を起動したんだ？助かったぜ！",
            ["DialogueId"] = 12048737,
            ["GUID"] = "1E29A9EA",
            ["NextDialogue"] = 12048738,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29A9EA",
            },
        [12048738] = {
            ["Content"] = "有了它的支援，看我不把对面打个落花流水……哎哟！",
            ["ContentJP"] = "こいつの支援があれば、向こうを木っ端みじんにしてやれる……って、いてっ！",
            ["DialogueId"] = 12048738,
            ["GUID"] = "1E29AA14",
            ["NextDialogue"] = 12048739,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AA14",
            },
        [12048739] = {
            ["Content"] = "……无聊至极！胜负未定，说这些大话还为时尚早。",
            ["ContentJP"] = "……くだらん！勝負はまだ決まっていない、大口を叩くにはまだ早い。",
            ["DialogueId"] = 12048739,
            ["GUID"] = "1E29AA3E",
            ["NextDialogue"] = 12048740,
            ["SpeakNpcId"] = 240100,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AA3E",
            },
        [12048740] = {
            ["Content"] = "好啊，那就让我先打倒你再说！",
            ["ContentJP"] = "いいだろう、まずはお前を叩き潰してからだ！",
            ["DialogueId"] = 12048740,
            ["GUID"] = "1E29AA68",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AA68",
            },
        [12048742] = {
            ["Content"] = "止流，既然你一心求死，就休怪我们不留情面！",
            ["ContentJP"] = "シリュウよ！そこまでして死を望むというのなら、もはや情けは無用。",
            ["DialogueId"] = 12048742,
            ["GUID"] = "1E29AABC",
            ["NextDialogue"] = 12048743,
            ["SpeakNpcId"] = 240072,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AABC",
            },
        [12048743] = {
            ["Content"] = "妄图以一人之力对抗大风九章，愚蠢！愚蠢至极！",
            ["ContentJP"] = "一人で<Default note=\"text:たいふうきゅうしょう\">大風九章</>に抗おうなど、愚かだ！あまりにも愚かだ！",
            ["DialogueId"] = 12048743,
            ["GUID"] = "1E29AAE6",
            ["NextDialogue"] = 12048744,
            ["SpeakNpcId"] = 240073,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AAE6",
            },
        [12048744] = {
            ["Content"] = "住手吧，止流！你是聪明人，何必挑起一场双输的斗争！",
            ["ContentJP"] = "おやめなさい、シリュウ！なぜ争いを招こうとする？共倒れになることは、あなたが一番良くわかっているはず。",
            ["DialogueId"] = 12048744,
            ["GUID"] = "1E29AB10",
            ["NextDialogue"] = 12048745,
            ["SpeakNpcId"] = 240074,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AB10",
            },
        [12048745] = {
            ["Content"] = "……冥顽不灵！",
            ["ContentJP"] = "……愚か者め、なぜ正道に逆らう！",
            ["DialogueId"] = 12048745,
            ["GUID"] = "1E29AB3A",
            ["NextDialogue"] = 12048746,
            ["SpeakNpcId"] = 240075,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AB3A",
            },
        [12048746] = {
            ["Content"] = "呵呵……很快，一切就要结束了。",
            ["ContentJP"] = "ふふ……もうすぐ、すべてが終わるわ。",
            ["DialogueId"] = 12048746,
            ["GUID"] = "1E29AB64",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29AB64",
            },
        [12048748] = {
            ["Content"] = "小、小仆从，天色像世界末日一样……有种不详的感觉……",
            ["ContentJP"] = "わっ、我が下僕よ。見て、そ、空が赤く燃えているよ！まるで、終末みたいで、なんだか嫌な予感がするね……",
            ["DialogueId"] = 12048748,
            ["GUID"] = "1E29ABB8",
            ["NextDialogue"] = 12048749,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29ABB8",
            },
        [12048749] = {
            ["Content"] = "加快脚步……一定还来得及！",
            ["ContentJP"] = "いそごう……まだ間に合うはず！",
            ["DialogueId"] = 12048749,
            ["GUID"] = "1E29ABE2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120487/1E29ABE2",
            },
        [12048751] = {
            ["Content"] = "异样感似乎还在隐隐跳动，先走吧……",
            ["DialogueId"] = 12048751,
            ["Duration"] = 7,
            ["SpeakNpcId"] = 100001,
            },
        [12048801] = {
            ["DialogueId"] = 12048801,
            },
        [12048802] = {
            ["Content"] = "咦，小仆从……重力好像恢复正常了？",
            ["DialogueId"] = 12048802,
            ["SpeakNpcId"] = 100001,
            },
        [12049001] = {
            ["Content"] = "小仆从，你回来了！这里这里。",
            ["ContentJP"] = "おっ、我が下僕、戻ったのか！こっちこっち！",
            ["DialogueId"] = 12049001,
            ["GUID"] = "1E29D53A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D53A",
            },
        [12049002] = {
            ["Content"] = "哇，这就是执律阁吗？果然非常厉害！",
            ["ContentJP"] = "わぁ……あれが<Default note=\"text:しつりつかく\">執律閣</>？すっごいなぁ！",
            ["DialogueId"] = 12049002,
            ["GUID"] = "1E29D564",
            ["NextDialogue"] = 12049003,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D564",
            },
        [12049003] = {
            ["Content"] = "小仆从，你说，站在那么高的地方，是不是能把地面上的东西看得一清二楚？我已经迫不及待了！",
            ["ContentJP"] = "ねぇ我が下僕、あんな高いとこに立ったら、下の景色ぜーんぶ見渡せちゃうんじゃない？もう待ちきれないよ！",
            ["DialogueId"] = 12049003,
            ["GUID"] = "1E29D58E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D58E",
            },
        [12049004] = {
            ["Content"] = "南边……嗯，就是这个方向。这张地图我完全看懂啦。",
            ["ContentJP"] = "南……うん、こっちこっち。この地図はバッチリ読めるぞ！",
            ["DialogueId"] = 12049004,
            ["GUID"] = "1E29D5B8",
            ["NextDialogue"] = 12049005,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D5B8",
            },
        [12049005] = {
            ["Content"] = "小仆从，你就跟着我走吧。接下来请尽情享受白魔王大人的导、导、导航服服服务。",
            ["ContentJP"] = "我が下僕、今からスノウ様のあア案……ナイサービビスを……",
            ["DialogueId"] = 12049005,
            ["GUID"] = "1E29D5E2",
            ["NextDialogue"] = 12049006,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D5E2",
            },
        [12049006] = {
            ["Content"] = "……白，你说什么？",
            ["ContentJP"] = "……スノウ、今なんて？",
            ["DialogueId"] = 12049006,
            ["GUID"] = "1E29D60C",
            ["NextDialogue"] = 12049007,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D60C",
            },
        [12049007] = {
            ["Content"] = "嗯？我说沿着这条路一直往前面走，有什么不对吗？难道白带错了路？",
            ["ContentJP"] = "ん？この道まっすぐ行こうって言っただけだよ。なんか変？もしかして道間違えたとか？",
            ["DialogueId"] = 12049007,
            ["GUID"] = "1E29D636",
            ["NextDialogue"] = 12049008,
            ["SpeakNpcId"] = 200001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D636",
            },
        [12049008] = {
            ["Content"] = "（刚刚那是怎么回事？）",
            ["ContentJP"] = "（今の……なんだった{性别:んだろう|のかな}？）",
            ["DialogueId"] = 12049008,
            ["GUID"] = "1E29D660",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D660",
            },
        [12049009] = {
            ["Content"] = "小仆从，那个人看起来像是管事的，我们去找他问问看吧！",
            ["ContentJP"] = "我が下僕、あそこにいるの責任者っぽくない？話聞いてみよう！",
            ["DialogueId"] = 12049009,
            ["GUID"] = "1E29D68A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D68A",
            },
        [12049010] = {
            ["Content"] = "哎，小仆从，头顶上是不是有什么亮晶晶的东西飞过去了？",
            ["ContentJP"] = "あれ？今、頭の上に何かキラッと光るものが飛んでなかった？",
            ["DialogueId"] = 12049010,
            ["GUID"] = "1E29D6B4",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D6B4",
            },
        [12049011] = {
            ["Content"] = "一、一下子穿墙而过，还有点晕乎乎的……",
            ["ContentJP"] = "うわっ、壁すり抜けた！ちょっと目が回る……",
            ["DialogueId"] = 12049011,
            ["GUID"] = "1E29D6DE",
            ["NextDialogue"] = 12049012,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D6DE",
            },
        [12049012] = {
            ["Content"] = "无由生在往那个方向跑，小仆从，我们赶紧跟上去！",
            ["ContentJP"] = "あっちに行った！下僕、はやくついてゆこう！",
            ["DialogueId"] = 12049012,
            ["GUID"] = "1E29D708",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D708",
            },
        [12049013] = {
            ["Content"] = "无由生消失了……它肯定又附身在什么东西上了！一切都瞒不过英明神武的白魔王和小仆从的眼睛！",
            ["ContentJP"] = "消えちゃった…？きっと何かに取りついたんだよな！でもこのスノウ様と下僕の目はごまかせないぞ！",
            ["DialogueId"] = 12049013,
            ["GUID"] = "1E29D732",
            ["NextDialogue"] = 12049301,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D732",
            },
        [12049014] = {
            ["Content"] = "哼哼，逮住你了。",
            ["ContentJP"] = "ふふん、見つけた！",
            ["DialogueId"] = 12049014,
            ["GUID"] = "1E29D75C",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D75C",
            },
        [12049015] = {
            ["Content"] = "还想跑？！",
            ["ContentJP"] = "まだ逃げる気！？",
            ["DialogueId"] = 12049015,
            ["GUID"] = "1E29D786",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D786",
            },
        [12049016] = {
            ["Content"] = "真是的，不知不觉跑了好多路，都搞不清楚这里是哪里了。",
            ["ContentJP"] = "はぁ……結構歩いたな。ここどこだ？",
            ["DialogueId"] = 12049016,
            ["GUID"] = "1E29D7B0",
            ["NextDialogue"] = 12049017,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D7B0",
            },
        [12049017] = {
            ["Content"] = "让我看看地图……嗯，白完全明白了！小仆从，我们赶紧出发去下一个地方吧！",
            ["ContentJP"] = "ちょっと地図を確認……ふぅ、もうわかった！さっさと次の場所へ行くぞ、我が下僕よ！",
            ["DialogueId"] = 12049017,
            ["GUID"] = "1E29D7DA",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D7DA",
            },
        [12049018] = {
            ["Content"] = "这个大炉子好气派！还有这么多人进进出出，这里一定就是祀烟阁了！",
            ["ContentJP"] = "この炉……すっごく大きい！しかも人が出たり入ったり……ここが<Default note=\"text:しえんかく\">祀煙閣</>か！",
            ["DialogueId"] = 12049018,
            ["GUID"] = "1E29D804",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D804",
            },
        [12049019] = {
            ["Content"] = "这里的屋顶上也有亮晶晶的尘漠耶……",
            ["ContentJP"] = "屋根にもキラキラした砂が積もってる……",
            ["DialogueId"] = 12049019,
            ["GUID"] = "1E29D82E",
            ["NextDialogue"] = 12049020,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D82E",
            },
        [12049020] = {
            ["Content"] = "香囊是不是掉在了这些尘漠堆里呢？小仆从，我们找找看吧！",
            ["ContentJP"] = "香り袋、砂に埋もれちゃったのかな？探してみよう！",
            ["DialogueId"] = 12049020,
            ["GUID"] = "1E29D858",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D858",
            },
        [12049021] = {
            ["Content"] = "好啦，就剩下匠矩阁的东西还没有拿到手了。就在祀烟阁对面，小仆从，我们走！",
            ["ContentJP"] = "あとは<Default note=\"text:しょうくかく\">匠矩閣</>だけだね！\
<Default note=\"text:しえんかく\">祀煙閣</>の向かいだからすぐだよ。行こっ！",
            ["DialogueId"] = 12049021,
            ["GUID"] = "1E29D882",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D882",
            },
        [12049022] = {
            ["Content"] = "哇，告示板前已经聚集了好多人，我们也过去看看！",
            ["ContentJP"] = "わぁ、もう人がいっぱい集まってる！私たちも見に行こう！",
            ["DialogueId"] = 12049022,
            ["GUID"] = "1E29D8AC",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D8AC",
            },
        [12049023] = {
            ["Content"] = "来来回回都是这些蠢狼，我都杀腻了！",
            ["ContentJP"] = "何度やっても同じツラばっか……飽きてきたぜ！",
            ["DialogueId"] = 12049023,
            ["GUID"] = "1E29D8D6",
            ["NextDialogue"] = 12049024,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D8D6",
            },
        [12049024] = {
            ["Content"] = "喂，躲在后面的应天尉！你能听清我这把剑在说什么吗？",
            ["ContentJP"] = "おい、後ろで隠れてる<Default note=\"text:おうてんい\">応天尉</>！この剣の声が聞こえてるか？",
            ["DialogueId"] = 12049024,
            ["GUID"] = "1E29D900",
            ["NextDialogue"] = 12049025,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D900",
            },
        [12049025] = {
            ["Content"] = "它在说无聊，无趣，不过尔尔！",
            ["ContentJP"] = "「退屈だ、つまらん、取るに足らん」ってな！",
            ["DialogueId"] = 12049025,
            ["GUID"] = "1E29D92A",
            ["NextDialogue"] = 12049026,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D92A",
            },
        [12049026] = {
            ["Content"] = "没想到你们这些刍狗，连正面对决的骨气都没有！可真让剑兄感到腻味啊！",
            ["ContentJP"] = "正面から挑む度胸もねぇとはな……なんとも呆れちまうぜ！",
            ["DialogueId"] = 12049026,
            ["GUID"] = "1E29D954",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D954",
            },
        [12049027] = {
            ["Content"] = "咚——咚——咚——咚——",
            ["ContentJP"] = "ゴーン――ゴーン――ゴーン――ゴーン――",
            ["DialogueId"] = 12049027,
            ["GUID"] = "1E29D97E",
            ["NextDialogue"] = 12049028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D97E",
            },
        [12049028] = {
            ["Content"] = "时间马上就要到了，小仆从，我们赶紧出发吧！",
            ["ContentJP"] = "時間だ！下僕、行くよ！",
            ["DialogueId"] = 12049028,
            ["GUID"] = "1E29D9A8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D9A8",
            },
        [12049029] = {
            ["Content"] = "小仆从，那里看起来比较像是通往顶层的出口。",
            ["ContentJP"] = "我が下僕、あそこ……たぶん最上階への出口だよね。",
            ["DialogueId"] = 12049029,
            ["GUID"] = "1E29D9D2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D9D2",
            },
        [12049030] = {
            ["Content"] = "小仆从，原来你还有机械修理的天赋！我们这机枢派荣誉学徒的名号，真不是盖的。",
            ["ContentJP"] = "それにしても、まさか君に機械いじりの才能まであったなんてね！これぞ我が <Default note=\"text:きすうは\">機枢派</>の優秀な名誉見習いだな！",
            ["DialogueId"] = 12049030,
            ["GUID"] = "1E29D9FC",
            ["NextDialogue"] = 12049031,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29D9FC",
            },
        [12049031] = {
            ["Content"] = "也只是试试，没想到今天运气这么好。",
            ["ContentJP"] = "ちょっと試してみただけ{性别:さ|だよ}。まさか上手くいくなんて思わなかった。",
            ["DialogueId"] = 12049031,
            ["GUID"] = "1E29DA26",
            ["NextDialogue"] = 12049032,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DA26",
            },
        [12049032] = {
            ["Content"] = "希望好运气可以保佑我们一路顺顺利利，可别出什么突发事件啊——",
            ["ContentJP"] = "このまま運が続けばいいな……途中で変な事件なんか起きないように！",
            ["DialogueId"] = 12049032,
            ["GUID"] = "1E29DA50",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DA50",
            },
        [12049033] = {
            ["Content"] = "{nickname}，此时无需恋战，走为上计！",
            ["ContentJP"] = "{nickname}、ひとまず退くぞ！",
            ["DialogueId"] = 12049033,
            ["GUID"] = "1E29DA7A",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DA7A",
            },
        [12049034] = {
            ["Content"] = "怎么办，四面八方都被他们堵住了……",
            ["ContentJP"] = "どうしよう、どこもかしこも見張りだらけだ……",
            ["DialogueId"] = 12049034,
            ["GUID"] = "1E29DAA4",
            ["NextDialogue"] = 12049035,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DAA4",
            },
        [12049035] = {
            ["Content"] = "上天入地，无拘无束，好不逍遥～",
            ["ContentJP"] = "天も地も、自由自在が一番さ～",
            ["DialogueId"] = 12049035,
            ["GUID"] = "1E29DACE",
            ["NextDialogue"] = 12049036,
            ["SpeakNpcName"] = "UI_Npc_Name_XiaoYaoShengWenHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DACE",
            },
        [12049036] = {
            ["Content"] = "哇！怎么是你！",
            ["ContentJP"] = "またあんたか！！",
            ["DialogueId"] = 12049036,
            ["GUID"] = "1E29DAF8",
            ["NextDialogue"] = 12049037,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DAF8",
            },
        [12049037] = {
            ["Content"] = "哈哈！行至山穷水尽，必有柳暗花明，正是适合我逍遥生登场之时～",
            ["ContentJP"] = "行き詰まった時こそ、我の出番というものよ～",
            ["DialogueId"] = 12049037,
            ["GUID"] = "1E29DB22",
            ["NextDialogue"] = 12049038,
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DB22",
            },
        [12049038] = {
            ["Content"] = "若想求一线生机，就跟上来吧～",
            ["ContentJP"] = "生き延びたくば、ついて参れ。",
            ["DialogueId"] = 12049038,
            ["GUID"] = "1E29DB4C",
            ["SpeakNpcId"] = 240028,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DB4C",
            },
        [12049039] = {
            ["Content"] = "下面黑压压一片都是追兵……我们只能先跟着这家伙走了。",
            ["ContentJP"] = "下は追っ手でぎっしりだ……もう、こいつについてくしかないよ！",
            ["DialogueId"] = 12049039,
            ["GUID"] = "1E29DB76",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DB76",
            },
        [12049040] = {
            ["Content"] = "虽然这个什么逍遥生十分可恶！但不得不说，它的能力在这种时候还真能派上用场。",
            ["ContentJP"] = "まぁ、いちいち腹立つやつだが……いざという時は役に立つな！",
            ["DialogueId"] = 12049040,
            ["GUID"] = "1E29DBA0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DBA0",
            },
        [12049041] = {
            ["Content"] = "绝处必得逢生路，江湖有友来相助，不愧是我替天行道刻舟刻某人的运气！",
            ["ContentJP"] = "絶境にも生の道あり。友来たりて助けるとは……まこと、天を代行し正義を成すカシュウ、この俺の運気だ！",
            ["DialogueId"] = 12049041,
            ["GUID"] = "1E29DBCA",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DBCA",
            },
        [12049042] = {
            ["Content"] = "前方……是死胡同，没有路了！",
            ["ContentJP"] = "ちょっと待って、行き止まりだよ！！",
            ["DialogueId"] = 12049042,
            ["GUID"] = "1E29DBF4",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DBF4",
            },
        [12049043] = {
            ["Content"] = "兀那贼人，逮住你了！",
            ["ContentJP"] = "賊め、もう逃がさんぞ！！",
            ["DialogueId"] = 12049043,
            ["GUID"] = "1E29DC1E",
            ["SpeakNpcId"] = 240014,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC1E",
            },
        [12049044] = {
            ["Content"] = "我想起来了……烛阴之战结束后，止流在山脚迷昏了我，然后把我带到了这里……",
            ["ContentJP"] = "……思い出した。<Default note=\"text:しょくいん\">燭陰</>との戦いが終わったあと、シリュウに術をかけられ、ここに連れてこられて……",
            ["DialogueId"] = 12049044,
            ["GUID"] = "1E29DC48",
            ["NextDialogue"] = 12049045,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC48",
            },
        [12049045] = {
            ["Content"] = "这些……又是什么？",
            ["ContentJP"] = "これらは……一体……",
            ["DialogueId"] = 12049045,
            ["GUID"] = "1E29DC72",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC72",
            },
        [12049046] = {
            ["Content"] = "追兵已经被引走了，但仍不可过于大意。",
            ["ContentJP"] = "追っ手は引き離しましたが、まだ油断はなりません。",
            ["DialogueId"] = 12049046,
            ["GUID"] = "1E29DC9C",
            ["NextDialogue"] = 12049047,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DC9C",
            },
        [12049047] = {
            ["Content"] = "{nickname}，按照先前所约定的，一边寻找沿途的暗号，一边谨慎前进吧。",
            ["ContentJP"] = "{nickname}さん、先ほど申し合わせたとおり、沿道の暗号を探しつつ、慎重に進みましょう。",
            ["DialogueId"] = 12049047,
            ["GUID"] = "1E29DCC6",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DCC6",
            },
        [12049048] = {
            ["Content"] = "那块大石头上的涂鸦，一定是刻舟说的那什么暗号了吧。",
            ["ContentJP"] = "ほら、あの大きな岩の落書き！きっとカシュウの言ってた暗号ってやつだぞ！",
            ["DialogueId"] = 12049048,
            ["GUID"] = "1E29DCF0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DCF0",
            },
        [12049049] = {
            ["Content"] = "是秽兽……{nickname}，注意安全，我来护你左右。",
            ["ContentJP"] = "……穢獣ですね。{nickname}さん、お気をつけください。私が共に戦いましょう。",
            ["DialogueId"] = 12049049,
            ["GUID"] = "1E29DD1A",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD1A",
            },
        [12049050] = {
            ["Content"] = "咦，这里怎么有人等着，难不成是派来接应我们的？",
            ["ContentJP"] = "おや？ここに誰かいるぞ。もしかして迎えか？",
            ["DialogueId"] = 12049050,
            ["GUID"] = "1E29DD44",
            ["NextDialogue"] = 12049051,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD44",
            },
        [12049051] = {
            ["Content"] = "但她看着也不像是刻舟的姑奶奶啊……不管了，向她打听一下吧！",
            ["ContentJP"] = "……でもカシュウの「叔母」には見えないぞ……ま、いいや、聞いてみよ！",
            ["DialogueId"] = 12049051,
            ["GUID"] = "1E29DD6E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD6E",
            },
        [12049052] = {
            ["Content"] = "这个机关白认得！",
            ["ContentJP"] = "スノウ、これ知ってる！",
            ["DialogueId"] = 12049052,
            ["GUID"] = "1E29DD98",
            ["NextDialogue"] = 12049053,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DD98",
            },
        [12049053] = {
            ["Content"] = "我懂的，这就是所谓的考验啊试炼啊什么的……看我们轻松解决。上吧，小仆从！",
            ["ContentJP"] = "試練ってやつでしょ……さぁ、我が下僕、さっさと解いちゃえ！",
            ["DialogueId"] = 12049053,
            ["GUID"] = "1E29DDC2",
            ["NextDialogue"] = 12049054,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DDC2",
            },
        [12049054] = {
            ["Content"] = "呵呵，很有干劲呢。",
            ["ContentJP"] = "ふふ、元気な方ですね。",
            ["DialogueId"] = 12049054,
            ["GUID"] = "1E29DDEC",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DDEC",
            },
        [12049055] = {
            ["Content"] = "呼，终于找到了，这个暗号动作藏得也太深了……一路上翻山越岭的。",
            ["ContentJP"] = "やっと見つけた！こんな奥に隠されてるなんて……まさに山越え谷越えだったな。",
            ["DialogueId"] = 12049055,
            ["GUID"] = "1E29DE16",
            ["NextDialogue"] = 12049056,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE16",
            },
        [12049056] = {
            ["Content"] = "既然接头暗号已经到手，事不宜迟，我们回去找那位接应人吧。",
            ["ContentJP"] = "暗号も手に入りましたし、早くお迎えの者のもとへ戻りましょう。",
            ["DialogueId"] = 12049056,
            ["GUID"] = "1E29DE40",
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE40",
            },
        [12049057] = {
            ["Content"] = "是对着她做出刚刚找到的那个动作，对吧？本魔王的记忆力可是很好的！",
            ["ContentJP"] = "この人に向かってさっきの動作をやればいいんだよな！スノウの記憶力を見せつけてやる！",
            ["DialogueId"] = 12049057,
            ["GUID"] = "1E29DE6A",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE6A",
            },
        [12049058] = {
            ["Content"] = "我们到啦——这里就是山外山！",
            ["ContentJP"] = "着いたわ――ここが<Default note=\"text:さんがいさん\">山外山</>よ！",
            ["DialogueId"] = 12049058,
            ["GUID"] = "1E29DE94",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DE94",
            },
        [12049059] = {
            ["Content"] = "哇，这里竟然是建在悬崖上的……我说，你们平时走路万一不小心掉下去该怎么办？",
            ["ContentJP"] = "うわぁ……崖の上に建ってる！こんな所、うっかり足滑らせたらどうするの？",
            ["DialogueId"] = 12049059,
            ["GUID"] = "1E29DEBE",
            ["NextDialogue"] = 12049060,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DEBE",
            },
        [12049060] = {
            ["Content"] = "白，你要是害怕了，就离我近一点。",
            ["ContentJP"] = "怖いなら、{性别:僕|私}のそばにいて。",
            ["DialogueId"] = 12049060,
            ["GUID"] = "1E29DEE8",
            ["NextDialogue"] = 12049061,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DEE8",
            },
        [12049061] = {
            ["Content"] = "谁谁谁谁害怕了，魔王大人才不会恐高呢。小仆从你可不要乱说……",
            ["ContentJP"] = "だ、誰が怖いって！？魔王たる者、高所ごときで怯えるわけないでしょ！",
            ["DialogueId"] = 12049061,
            ["GUID"] = "1E29DF12",
            ["NextDialogue"] = 12049062,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF12",
            },
        [12049062] = {
            ["Content"] = "嘻嘻，我在这里住了这么久，早就习惯了。就算真掉下去了，也会有牵机鸢接住你们的。所以不用担心！",
            ["ContentJP"] = "ふふっ、私はもう慣れっこ。もし落ちてもからくり<Default note=\"text:とび\">鳶</>が拾ってくれるから平気平気。",
            ["DialogueId"] = 12049062,
            ["GUID"] = "1E29DF3C",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF3C",
            },
        [12049063] = {
            ["Content"] = "你们跟着我来吧！这也是个带你们参观山外山的好机会。",
            ["ContentJP"] = "じゃ、ついてきて。ついでにこの山外山（さんがいさん）を案内してあげる。",
            ["DialogueId"] = 12049063,
            ["GUID"] = "1E29DF66",
            ["NextDialogue"] = 12049064,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF66",
            },
        [12049064] = {
            ["Content"] = "唐叔最近腿摔伤了，我想去采些药草给他敷上，让他能快点好起来。",
            ["ContentJP"] = "タンさんが最近足をくじいてね。薬草を摘んで湿布にしてあげたいんだ。",
            ["DialogueId"] = 12049064,
            ["GUID"] = "1E29DF90",
            ["NextDialogue"] = 12049065,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DF90",
            },
        [12049065] = {
            ["Content"] = "机枢派的实验，风险有这么高吗？",
            ["ContentJP"] = "<Default note=\"text:きすうは\">機枢派</>の実験って、そんなに危険なの？",
            ["DialogueId"] = 12049065,
            ["GUID"] = "1E29DFBA",
            ["NextDialogue"] = 12049066,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DFBA",
            },
        [12049066] = {
            ["Content"] = "嗯。但我们机枢派先祖<H>矩</>有训，“探新开物，虽险弗辞”——就算新的造物有风险，也要勇敢尝试。",
            ["ContentJP"] = "うん。でも我らのご先祖様<H>「ノリ」</>曰く――「新しいものに挑むなら、危険を恐れるべからず」ってね。",
            ["DialogueId"] = 12049066,
            ["GUID"] = "1E29DFE4",
            ["NextDialogue"] = 12049067,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29DFE4",
            },
        [12049067] = {
            ["Content"] = "试验新式机傀易出意外，习武之人也时常受伤。因此我们特意开垦了一块药田，就在山巅高处。",
            ["ContentJP"] = "新しいからくり人形は失敗作も多いし、武術の稽古でも怪我はつきもの。だから山の上に薬草畑を作ったの。",
            ["DialogueId"] = 12049067,
            ["GUID"] = "1E29E00E",
            ["NextDialogue"] = 12049068,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E00E",
            },
        [12049068] = {
            ["Content"] = "来，从前面穿过去就到啦。",
            ["ContentJP"] = "ほら、この先を抜ければ着くよ。",
            ["DialogueId"] = 12049068,
            ["GUID"] = "1E29E038",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E038",
            },
        [12049069] = {
            ["Content"] = "哎？！哪里来的声响？",
            ["ContentJP"] = "え！？今の音は……",
            ["DialogueId"] = 12049069,
            ["GUID"] = "1E29E062",
            ["NextDialogue"] = 12049070,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E062",
            },
        [12049070] = {
            ["Content"] = "那边发生什么事了？！",
            ["ContentJP"] = "あっちからだよ！！",
            ["DialogueId"] = 12049070,
            ["GUID"] = "1E29E08C",
            ["NextDialogue"] = 12049071,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E08C",
            },
        [12049071] = {
            ["Content"] = "怎么到处都是狴犴和应天尉，小仆从，感觉好像很不妙……我们赶紧过去看看！",
            ["ContentJP"] = "ひっ！<Default note=\"text:ビーアン\">狴犴</>と<Default note=\"text:おうてんい\">応天尉</>がいっぱいいる！なんだかいやな予感が……早く行こ！",
            ["DialogueId"] = 12049071,
            ["GUID"] = "1E29E0B6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E0B6",
            },
        [12049072] = {
            ["Content"] = "来得正好！助我一臂之力！",
            ["ContentJP"] = "ちょうどいいとこに来たな！手を貸してくれ！",
            ["DialogueId"] = 12049072,
            ["GUID"] = "1E29E0E0",
            ["NextDialogue"] = 12049073,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E0E0",
            },
        [12049073] = {
            ["Content"] = "现在是什么情况？",
            ["ContentJP"] = "いったい何が？",
            ["DialogueId"] = 12049073,
            ["GUID"] = "1E29E10A",
            ["NextDialogue"] = 12049074,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E10A",
            },
        [12049074] = {
            ["Content"] = "山外山的位置突然暴露，应天尉打上门来了！",
            ["ContentJP"] = "なぜかはわからんが、<Default note=\"text:さんがいさん\">山外山</>の位置を突き止められた！",
            ["DialogueId"] = 12049074,
            ["GUID"] = "1E29E134",
            ["NextDialogue"] = 12049075,
            ["SpeakNpcId"] = 240035,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E134",
            },
        [12049075] = {
            ["Content"] = "此刻不可分神！更具体的事先将他们打退再说！",
            ["ContentJP"] = "話しは、奴らを撃退してからだ！",
            ["DialogueId"] = 12049075,
            ["GUID"] = "1E29E15E",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E15E",
            },
        [12049076] = {
            ["Content"] = "师兄，你当真要攻过来吗？你可想好了？",
            ["ContentJP"] = "……本気なんだな？",
            ["DialogueId"] = 12049076,
            ["GUID"] = "1E29E188",
            ["NextDialogue"] = 12049077,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E188",
            },
        [12049077] = {
            ["Content"] = "你我之间，再无交情，只有立场。",
            ["ContentJP"] = "お前と俺の間にもう情はない。あるのは立場だけだ。",
            ["DialogueId"] = 12049077,
            ["GUID"] = "1E29E1B2",
            ["NextDialogue"] = 12049078,
            ["SpeakNpcId"] = 210007,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E1B2",
            },
        [12049078] = {
            ["Content"] = "若你执意如此……我也不得不认真起来了！",
            ["ContentJP"] = "ならば俺も……本気で応じるしかないな！",
            ["DialogueId"] = 12049078,
            ["GUID"] = "1E29E1DC",
            ["NextDialogue"] = 12049079,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E1DC",
            },
        [12049079] = {
            ["Content"] = "有什么话，待到打出个高下后再说也不迟！",
            ["ContentJP"] = "言葉は剣を交えたあとで――存分に語り合おう！",
            ["DialogueId"] = 12049079,
            ["GUID"] = "1E29E206",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E206",
            },
        [12049080] = {
            ["Content"] = "走珠入瓯，这是机枢派常给入门弟子设置的一道考验。",
            ["ContentJP"] = "ここは最初の試練、転珠の儀よ。",
            ["DialogueId"] = 12049080,
            ["GUID"] = "1E29E230",
            ["NextDialogue"] = 12049081,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E230",
            },
        [12049081] = {
            ["Content"] = "看你们手法很熟练的样子，我就不多做解说啦。",
            ["ContentJP"] = "手慣れてるようだし、説明は省略するわ。",
            ["DialogueId"] = 12049081,
            ["GUID"] = "1E29E25A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E25A",
            },
        [12049082] = {
            ["Content"] = "这里布置了御敌机傀……当心！",
            ["ContentJP"] = "ここに防御からくりが仕掛けられてる！気を付けて！",
            ["DialogueId"] = 12049082,
            ["GUID"] = "1E29E284",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E284",
            },
        [12049083] = {
            ["Content"] = "哎？怎么看不到这里的机枢球？好奇怪。",
            ["ContentJP"] = "あれ？変ね……からくり球が見当たらない。",
            ["DialogueId"] = 12049083,
            ["GUID"] = "1E29E2AE",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E2AE",
            },
        [12049084] = {
            ["Content"] = "小仆从，那边的装置好像有点蹊跷，要不要去看一看？",
            ["ContentJP"] = "ねぇねぇ、あっちの装置、ちょっと気にならない？調べてみよう！",
            ["DialogueId"] = 12049084,
            ["GUID"] = "1E29E2D8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E2D8",
            },
        [12049085] = {
            ["Content"] = "整个偃隐宫都是浑然一体的吗……不愧是前人巧思。",
            ["ContentJP"] = "……やっぱり、迷宮全体が大きなからくりなのね。見事だわ。",
            ["DialogueId"] = 12049085,
            ["GUID"] = "1E29E302",
            ["NextDialogue"] = 12049086,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E302",
            },
        [12049086] = {
            ["Content"] = "哇……是密室！",
            ["ContentJP"] = "わっ、密室だ！",
            ["DialogueId"] = 12049086,
            ["GUID"] = "1E29E32C",
            ["NextDialogue"] = 12049087,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E32C",
            },
        [12049087] = {
            ["Content"] = "消失的机枢球一定藏在这里，小仆从，我们赶紧一鼓作气解开这里的机关吧！",
            ["ContentJP"] = "あのからくり球、絶対この中にあるよ！下僕、一気に謎を解いちゃおう！",
            ["DialogueId"] = 12049087,
            ["GUID"] = "1E29E356",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E356",
            },
        [12049088] = {
            ["Content"] = "好，这下第一个机枢球就到手了！接下来只要如法炮制，就能继续往前啦！",
            ["ContentJP"] = "よし、これで最初の球が手に入った！同じ手順で集めれば、前に進められるはず。",
            ["DialogueId"] = 12049088,
            ["GUID"] = "1E29E380",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E380",
            },
        [12049089] = {
            ["Content"] = "太好了，没想到我们进展如此神速！",
            ["ContentJP"] = "やった……思ったより早い！",
            ["DialogueId"] = 12049089,
            ["GUID"] = "1E29E3AA",
            ["NextDialogue"] = 12049090,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E3AA",
            },
        [12049090] = {
            ["Content"] = "按这个势头，一定能及时赶回支援大家的。",
            ["ContentJP"] = "この調子なら、間に合うはずよ！",
            ["DialogueId"] = 12049090,
            ["GUID"] = "1E29E3D4",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E3D4",
            },
        [12049091] = {
            ["Content"] = "有巨阙镇守此处。{nickname}，这里一定有很重要的东西！",
            ["ContentJP"] = "この部屋、巨闕に守られてる……きっと重要な物が隠されてるはずよ！",
            ["DialogueId"] = 12049091,
            ["GUID"] = "1E29E3FE",
            ["NextDialogue"] = 12049092,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E3FE",
            },
        [12049092] = {
            ["Content"] = "玄铜为骨，机括藏锋。巨阙的攻击力道常人难以抵挡，尽量从侧面取巧吧。",
            ["ContentJP"] = "<Default note=\"text:げんどう\">玄銅</>の骨にからくり刀――正面から挑むのは危険よ。できるだけ側面から仕掛けましょう！",
            ["DialogueId"] = 12049092,
            ["GUID"] = "1E29E428",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E428",
            },
        [12049093] = {
            ["Content"] = "有了这样造物，我们就能深入偃隐宫了。",
            ["ContentJP"] = "これがあれば、さらに奥へ進めるわ。",
            ["DialogueId"] = 12049093,
            ["GUID"] = "1E29E452",
            ["NextDialogue"] = 12049094,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E452",
            },
        [12049094] = {
            ["Content"] = "{nickname}，小白，你们准备好了吗？这是数百年无人踏足过的地界，不知道埋藏着怎样的密辛。",
            ["ContentJP"] = "{nickname}、スノウ、準備はいい？この先は数百年、誰も足を踏み入れたことのない場所よ。\
何が隠されているかは、誰にもわからないわ。",
            ["DialogueId"] = 12049094,
            ["GUID"] = "1E29E47C",
            ["NextDialogue"] = 12049095,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E47C",
            },
        [12049095] = {
            ["Content"] = "哼哼，这才是适合魔王大人的冒险故事！",
            ["ContentJP"] = "ふふん、魔王様の冒険にぴったりの場所じゃん！",
            ["DialogueId"] = 12049095,
            ["GUID"] = "1E29E4A6",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E4A6",
            },
        [12049096] = {
            ["Content"] = "好壮观……没想到山体里面竟然藏着这么大的空间！",
            ["ContentJP"] = "うわぁ……すっごい。山の中に、こんな巨大な空間が……！",
            ["DialogueId"] = 12049096,
            ["GUID"] = "1E29E4D0",
            ["NextDialogue"] = 12049097,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E4D0",
            },
        [12049097] = {
            ["Content"] = "那处高塔应当是偃隐宫的核心了，我们赶紧去一探究竟吧。",
            ["ContentJP"] = "あの塔……<Default note=\"text:えんいんきゅう\">偃隠宮</>の核心部に違いないわ。急ぎましょう！",
            ["DialogueId"] = 12049097,
            ["GUID"] = "1E29E4FA",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E4FA",
            },
        [12049098] = {
            ["Content"] = "这些转轴看起来能带动邻近的机枢一起转动。",
            ["ContentJP"] = "この回転軸、他の機枢と連動して動くみたいね。",
            ["DialogueId"] = 12049098,
            ["GUID"] = "1E29E524",
            ["NextDialogue"] = 12049099,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E524",
            },
        [12049099] = {
            ["Content"] = "{nickname}，思考它们之间的组合关系，制造出一条通路吧。",
            ["ContentJP"] = "{nickname}、仕組みを見極めて、通路を作って！",
            ["DialogueId"] = 12049099,
            ["GUID"] = "1E29E54E",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120490/1E29E54E",
            },
        [12049101] = {
            ["Content"] = "咦，飘浮的石块竟然复原成了画中的样子……！好神奇！",
            ["ContentJP"] = "えっ！浮かんでた石が絵の通りに戻った……！すごい！",
            ["DialogueId"] = 12049101,
            ["GUID"] = "1E29E5A2",
            ["NextDialogue"] = 12049102,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E5A2",
            },
        [12049102] = {
            ["Content"] = "“巧构玲珑启万象”，我曾听说过这种神乎其神的技艺，没想到竟能在这里看到真迹……",
            ["ContentJP"] = "「玲瓏たる構築、万象を導く扉」――まさにその通りね。まさかこんな場所で、本物を目にするなんて……",
            ["DialogueId"] = 12049102,
            ["GUID"] = "1E29E5CC",
            ["NextDialogue"] = 12049103,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E5CC",
            },
        [12049103] = {
            ["Content"] = "……真是的，要不是时间紧迫，我苏乙横竖也得在这里待上十天半个月，把它研究彻底了再出关！",
            ["ContentJP"] = "……時間さえあれば、十日はここにこもって研究したいくらいだけど……そうもいかないわね！",
            ["DialogueId"] = 12049103,
            ["GUID"] = "1E29E5F6",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E5F6",
            },
        [12049104] = {
            ["Content"] = "这是牵机鸟的原型……真怀念，我小时候天天对着画本临摹它的样子，想象自己乘着它翱翔于长空。",
            ["ContentJP"] = "これは……からくり鳥の原型！懐かしい……子どもの頃、ずっと絵を見ながら、これに乗って空を飛ぶ自分を夢見てたわ。",
            ["DialogueId"] = 12049104,
            ["GUID"] = "1E29E620",
            ["NextDialogue"] = 12049105,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E620",
            },
        [12049105] = {
            ["Content"] = "登上去吧，{nickname}，它会将你载往下一个地点。",
            ["ContentJP"] = "さあ、{nickname}！これに乗って次の場所へ向かいましょう！",
            ["DialogueId"] = 12049105,
            ["GUID"] = "1E29E64A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E64A",
            },
        }
  end },
  { MinKey = 12049106, MaxKey = 12060401, Loader = function()
      return {
        [12049106] = {
            ["Content"] = "通体以榫卯结构打造的高塔……真是令人惊叹。",
            ["ContentJP"] = "この塔……榫卯構造だけで組み上げられてる……すごい……",
            ["DialogueId"] = 12049106,
            ["GUID"] = "1E29E674",
            ["NextDialogue"] = 12049107,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E674",
            },
        [12049107] = {
            ["Content"] = "苏乙，前方的石碑上，好像写着什么字。",
            ["ContentJP"] = "スーイー、あそこ……石碑に何か書いてあるよ。",
            ["DialogueId"] = 12049107,
            ["GUID"] = "1E29E69E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E69E",
            },
        [12049108] = {
            ["Content"] = "说起来，为什么你们机枢派的前辈，要费老大劲建这样一个地宫，来把东西藏起来呢？",
            ["ContentJP"] = "ねえ、なんでこ<Default note=\"text:きすうは\">機枢派</>の先人たちはこんなに大掛かりな仕掛けで宝を隠したんだろ？",
            ["DialogueId"] = 12049108,
            ["GUID"] = "1E29E6C8",
            ["NextDialogue"] = 12049109,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E6C8",
            },
        [12049109] = {
            ["Content"] = "值得这么大费周章，一定是很重要的秘密吧。",
            ["ContentJP"] = "それだけの労力をかけるってことは……きっと、とても大切な秘密だったんだよ。",
            ["DialogueId"] = 12049109,
            ["GUID"] = "1E29E6F2",
            ["NextDialogue"] = 12049110,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E6F2",
            },
        [12049110] = {
            ["Content"] = "嗯……根据史料考据，这座偃隐宫应当是在黍离之战后几十年内建起来的。",
            ["ContentJP"] = "うん。歴書によれば、この<Default note=\"text:えんいんきゅう\">偃隠宮</>は<Default note=\"text:しょりのらん\">黍離の乱</>のあと数十年以内に建てられたものらしいわ。",
            ["DialogueId"] = 12049110,
            ["GUID"] = "1E29E71C",
            ["NextDialogue"] = 12049111,
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E71C",
            },
        [12049111] = {
            ["Content"] = "黍离之战……我好像听别人提过好几次，但我始终不知道它是什么。",
            ["ContentJP"] = "その「黍離の乱」って、よく聞くけど……一体何があった{性别:んだ|の}？",
            ["DialogueId"] = 12049111,
            ["GUID"] = "1E29E746",
            ["NextDialogue"] = 12049112,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E746",
            },
        [12049112] = {
            ["Content"] = "那是导致机枢派衰落，也让大风九章逐渐变质的一场战役。之后有机会，我再慢慢讲给你们听。",
            ["ContentJP"] = "<Default note=\"text:きすうは\">機枢派</>を衰退させ、大風九章を歪めるきっかけになった戦争よ。……機会があれば、詳しく話すね。",
            ["DialogueId"] = 12049112,
            ["GUID"] = "1E29E770",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E770",
            },
        [12049113] = {
            ["Content"] = "我们正在接近最后的真相……越到这种时候，越不能放松警惕。",
            ["ContentJP"] = "真相はもうすぐそこよ……気を引き締めて。",
            ["DialogueId"] = 12049113,
            ["GUID"] = "1E29E79A",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E79A",
            },
        [12049114] = {
            ["Content"] = "呜啊啊……小仆从，黑白两色的大狼灵怎么联手一起打我们了！感觉不太妙的样子！",
            ["ContentJP"] = "うわああっ、どうしよう！あの黒白のウルフスピリッツが集団で押しかけてきたよ！！！",
            ["DialogueId"] = 12049114,
            ["GUID"] = "1E29E7C4",
            ["NextDialogue"] = 12049115,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E7C4",
            },
        [12049115] = {
            ["Content"] = "它们并非是真正的狴犴，而是模仿狴犴外形制造出的仿生机傀！要小心了！",
            ["ContentJP"] = "気をつけて！あれは本物の狴犴じゃない！狴犴の姿を真似て作られた生き人形よ！",
            ["DialogueId"] = 12049115,
            ["GUID"] = "1E29E7EE",
            ["SpeakNpcId"] = 240026,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E7EE",
            },
        [12049116] = {
            ["Content"] = "第二幅卦象也已经松动，这意味着预言已经实现了……",
            ["ContentJP"] = "二つ目の卦が動いた……つまり、あの予言は、もう実現してる……",
            ["DialogueId"] = 12049116,
            ["GUID"] = "1E29E818",
            ["NextDialogue"] = 12049117,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E818",
            },
        [12049117] = {
            ["Content"] = "止流……你的图谋到底是什么？",
            ["ContentJP"] = "シリュウさん……一体何を企んでいる{性别:んだ|の}？",
            ["DialogueId"] = 12049117,
            ["GUID"] = "1E29E842",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E842",
            },
        [12049118] = {
            ["Content"] = "数十年不见，村门口的树苗竟然已经蹿这么高了！",
            ["ContentJP"] = "うわぁ……数十年ぶりとはいえ、村の入口の木もずいぶん伸びたな！",
            ["DialogueId"] = 12049118,
            ["GUID"] = "1E29E86C",
            ["NextDialogue"] = 12049119,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E86C",
            },
        [12049119] = {
            ["Content"] = "哈哈，小时候我老爱在这儿爬上爬下，和小孩斗蛐蛐，用树枝戳村里的大鹅，被大鹅撵得满地跑……",
            ["ContentJP"] = "子どもの頃はよくここで木登りしてさ、友達とコオロギ戦わせたり、枝で村のガチョウつついて追いかけられたり……",
            ["DialogueId"] = 12049119,
            ["GUID"] = "1E29E896",
            ["NextDialogue"] = 12049120,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E896",
            },
        [12049120] = {
            ["Content"] = "唉，也不知道如今乡亲们还认不认得我。",
            ["ContentJP"] = "はは、みんな俺のこと、まだ覚えてるかな。",
            ["DialogueId"] = 12049120,
            ["GUID"] = "1E29E8C0",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E8C0",
            },
        [12049121] = {
            ["Content"] = "我只打探到无穷藏派的传人在此村中，但不知道具体姓甚名谁。",
            ["ContentJP"] = "<Default note=\"text:むきゅうぞうは\">無窮蔵派</>の伝人がこの村にいるのまでは突き止めたのですが、誰かまでは分からりませんでした。",
            ["DialogueId"] = 12049121,
            ["GUID"] = "1E29E8EA",
            ["NextDialogue"] = 12049122,
            ["SpeakNpcId"] = 240002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E8EA",
            },
        [12049122] = {
            ["Content"] = "说实话，我也不知道。你们先找人问问吧。",
            ["ContentJP"] = "正直、俺も分からないんだよな。まぁ、探してみようぜ。",
            ["DialogueId"] = 12049122,
            ["GUID"] = "1E29E914",
            ["NextDialogue"] = 12049123,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E914",
            },
        [12049123] = {
            ["Content"] = "刻舟你这个本地向导来打听不是更方便吗？你该不会想偷懒！",
            ["ContentJP"] = "ならカシュウが直接聞いた方が早いんじゃない？ほら、地元民なんだし！サボろうたってそうはいかないぞ！",
            ["DialogueId"] = 12049123,
            ["GUID"] = "1E29E93E",
            ["NextDialogue"] = 12049124,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E93E",
            },
        [12049124] = {
            ["Content"] = "还真不是这样……咳，你们等会儿就知道了。",
            ["ContentJP"] = "それがな……まぁ、すぐ分かるさ。",
            ["DialogueId"] = 12049124,
            ["GUID"] = "1E29E968",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E968",
            },
        [12049125] = {
            ["Content"] = "刻舟，她怎么一见到你就变了脸色？",
            ["ContentJP"] = "なんか、カシュウを見て、急に態度変えなかった！？",
            ["DialogueId"] = 12049125,
            ["GUID"] = "1E29E992",
            ["NextDialogue"] = 12049126,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E992",
            },
        [12049126] = {
            ["Content"] = "谁知道呢？可能是我小时候天天追着她家的鸡撵吧。",
            ["ContentJP"] = "さぁな……ガキのころ、よくあの人ん家の鶏を追いまわしてたから、その恨みじゃねぇか？",
            ["DialogueId"] = 12049126,
            ["GUID"] = "1E29E9BC",
            ["NextDialogue"] = 12049127,
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E9BC",
            },
        [12049127] = {
            ["Content"] = "罢了，这样四处瞎打听也问不出什么。我带你们去找村长吧。",
            ["ContentJP"] = "まぁいいさ。手あたり次第に聞き込みしても埒が明かない。村長んとこまで案内するよ。",
            ["DialogueId"] = 12049127,
            ["GUID"] = "1E29E9E6",
            ["SpeakNpcId"] = 240013,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29E9E6",
            },
        [12049128] = {
            ["Content"] = "最后一处卦象的封印松动了……一切的真相即将揭晓。",
            ["ContentJP"] = "……最後の卦、封印が緩んでる。いよいよ、すべての真相が明らかになる。",
            ["DialogueId"] = 12049128,
            ["GUID"] = "1E29EA10",
            ["NextDialogue"] = 12049129,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA10",
            },
        [12049129] = {
            ["Content"] = "止流，做出这些决定之时，你在想什么？",
            ["ContentJP"] = "シリュウさん……あの時、あなたは何を思っていた{性别:んだ|の}？",
            ["DialogueId"] = 12049129,
            ["GUID"] = "1E29EA3A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA3A",
            },
        [12049130] = {
            ["Content"] = "止流，你是要成为千古罪人吗？",
            ["ContentJP"] = "シリュウ！天下一の極悪人になるつもりか！",
            ["DialogueId"] = 12049130,
            ["GUID"] = "1E29EA64",
            ["NextDialogue"] = 12049131,
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennv1",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA64",
            },
        [12049131] = {
            ["Content"] = "天地大德，祖宗之法，岂容汝等凡人悖逆？！",
            ["ContentJP"] = "天地の理、祖先の掟――凡人ごときが逆らえると思うか！",
            ["DialogueId"] = 12049131,
            ["GUID"] = "1E29EA8E",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennan1",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EA8E",
            },
        [12049132] = {
            ["Content"] = "现在回头，为时不晚！",
            ["ContentJP"] = "今ならまだ間に合う！引き下がれ！",
            ["DialogueId"] = 12049132,
            ["GUID"] = "1E29EAB8",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennv2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EAB8",
            },
        [12049133] = {
            ["Content"] = "停下，别再前进了！",
            ["ContentJP"] = "止まれ！それ以上進むな！",
            ["DialogueId"] = 12049133,
            ["GUID"] = "1E29EAE2",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennan2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EAE2",
            },
        [12049134] = {
            ["Content"] = "千秋万代之伟业，便要终结在你手上！",
            ["ContentJP"] = "幾千年と積み重ねた偉業……それを終わらせる気か。",
            ["DialogueId"] = 12049134,
            ["GUID"] = "1E29EB0C",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennv3",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB0C",
            },
        [12049135] = {
            ["Content"] = "止流，你当真想好了吗——",
            ["ContentJP"] = "シリュウ……本当にそれでいいの？",
            ["DialogueId"] = 12049135,
            ["GUID"] = "1E29EB36",
            ["SpeakNpcName"] = "UI_Npc_Name_xianrennan3",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB36",
            },
        [12049136] = {
            ["Content"] = "成功了……！",
            ["ContentJP"] = "やった……！",
            ["DialogueId"] = 12049136,
            ["GUID"] = "1E29EB60",
            ["NextDialogue"] = 12049137,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB60",
            },
        [12049137] = {
            ["Content"] = "沿路的塑像都被打破了，止流一定就在前方！",
            ["ContentJP"] = "道中の像が全部壊されてた……きっとこの先にシリュウさんがいるはず！",
            ["DialogueId"] = 12049137,
            ["GUID"] = "1E29EB8A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EB8A",
            },
        [12049138] = {
            ["Content"] = "入侵者，可承天威之怒乎？",
            ["ContentJP"] = "侵入者よ、天の怒りに耐えられるか――！",
            ["DialogueId"] = 12049138,
            ["GUID"] = "1E29EBB4",
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuYinTaiHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EBB4",
            },
        [12049139] = {
            ["Content"] = "这里是……？",
            ["ContentJP"] = "……ここは……？",
            ["DialogueId"] = 12049139,
            ["GUID"] = "1E29EBDE",
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EBDE",
            },
        [12049140] = {
            ["Content"] = "……万物负阴而抱阳，冲气以为和……",
            ["ContentJP"] = "……<Default note=\"text:ばんぶつ\">万物</>は陰を負いて陽を抱き、<Default note=\"text:ちゅうき\">沖気</>以って和を為す……",
            ["DialogueId"] = 12049140,
            ["GUID"] = "1E29EC08",
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuYinTaiHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC08",
            },
        [12049141] = {
            ["Content"] = "……持而盈之，不如其已；揣而锐之，不可长保……",
            ["ContentJP"] = "……<Default note=\"text:じ\">持</>してこれを盈たすは、その<Default note=\"text:や\">已</>むるに<Default note=\"text:し\">如</>かず。<Default note=\"text:し\">揣</>してこれを鋭くするは、長く保つべからず……",
            ["DialogueId"] = 12049141,
            ["GUID"] = "1E29EC32",
            ["SpeakNpcName"] = "UI_Npc_Name_ZhuYinTaiHao",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC32",
            },
        [12049142] = {
            ["Content"] = "想不到，事情解决后，你来的第一个地方竟然是这里。",
            ["ContentJP"] = "……驚いた{性别:よ|わ}。真っ先にここを訪れるなんて。",
            ["DialogueId"] = 12049142,
            ["GUID"] = "1E29EC5C",
            ["NextDialogue"] = 12049143,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC5C",
            },
        [12049143] = {
            ["Content"] = "是想去那个人墓前看看吗？",
            ["ContentJP"] = "……あの人の墓を訪ねに？",
            ["DialogueId"] = 12049143,
            ["GUID"] = "1E29EC86",
            ["NextDialogue"] = 12049144,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EC86",
            },
        [12049144] = {
            ["Content"] = "……看来我那师父都告诉你们了啊。真是多此一举。",
            ["ContentJP"] = "……ふふ、やっぱり師父ってば口が軽いんだから。",
            ["DialogueId"] = 12049144,
            ["GUID"] = "1E29ECB0",
            ["NextDialogue"] = 12049145,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ECB0",
            },
        [12049145] = {
            ["Content"] = "不过，也正是多亏了她多管闲事，这场变局才得以圆满收场。",
            ["ContentJP"] = "でも、そのおかげで今こうして、話せてるのかもね。",
            ["DialogueId"] = 12049145,
            ["GUID"] = "1E29ECDA",
            ["NextDialogue"] = 12049146,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ECDA",
            },
        [12049146] = {
            ["Content"] = "那件事发生后，每一个下雨的夜晚，我都无法入睡。只要一闭眼，耳旁就会响起永无止境的水滴声。",
            ["ContentJP"] = "あの出来事のあと、私は雨の音が怖くなった。目を閉じれば、終わりのない水音が耳元で鳴り続けるの。",
            ["DialogueId"] = 12049146,
            ["GUID"] = "1E29ED04",
            ["NextDialogue"] = 12049147,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED04",
            },
        [12049147] = {
            ["Content"] = "我总是在噩梦中回到那个山洞，看到那些人冷漠的眼神。于是我不再信任旁人。",
            ["ContentJP"] = "悪夢の中で、何度もあの洞窟に引き戻されて、あの人たちの、冷たい目だけが繰り返し浮かんでくる――だから私は、他人を信じるのをやめた。",
            ["DialogueId"] = 12049147,
            ["GUID"] = "1E29ED2E",
            ["NextDialogue"] = 12049148,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED2E",
            },
        [12049148] = {
            ["Content"] = "我选择去掌控一切，算计一切，归根结底，是因为我只能看到自己愿意相信的。",
            ["ContentJP"] = "だから、私はすべてを自分で掌握しようとした。信じられるものしか信じたくなかった。",
            ["DialogueId"] = 12049148,
            ["GUID"] = "1E29ED58",
            ["NextDialogue"] = 12049149,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED58",
            },
        [12049149] = {
            ["Content"] = "{nickname}，你或许还在生我的气吧……如果当初我选择多信任你一点，现在是否能更加坦然地面对你呢？",
            ["ContentJP"] = "{nickname}……きっと、まだ私を責めているよね。あの時、少しでもあなたを信じられていれば……今よりもっと、胸を張って向き合えたのかもしれない。",
            ["DialogueId"] = 12049149,
            ["GUID"] = "1E29ED82",
            ["NextDialogue"] = 12049150,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29ED82",
            },
        [12049150] = {
            ["Content"] = "呵呵，我也沉溺于这种无用的假设了。",
            ["ContentJP"] = "……こんな、無意味な「もしも」、今さら考えても仕方ないのにね。",
            ["DialogueId"] = 12049150,
            ["GUID"] = "1E29EDAC",
            ["NextDialogue"] = 12049151,
            ["SpeakNpcId"] = 240001,
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EDAC",
            },
        [12049151] = {
            ["Content"] = "不知不觉中，已经走到地方了啊……",
            ["ContentJP"] = "あら、いつの間に着いたみたいね……",
            ["DialogueId"] = 12049151,
            ["GUID"] = "1E29EDD6",
            ["VoiceName"] = "voice/$Locale$/story/1204/120491/1E29EDD6",
            },
        [12049201] = {
            ["Content"] = "一段时间前……某处雨夜……",
            ["ContentJP"] = "少し前……ある雨の夜――",
            ["DialogueId"] = 12049201,
            ["GUID"] = "1E29F60A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F60A",
            },
        [12049202] = {
            ["Content"] = "呵……就这点能耐吗？",
            ["ContentJP"] = "ふん……その程度か？",
            ["DialogueId"] = 12049202,
            ["GUID"] = "1E29F634",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F634",
            },
        [12049203] = {
            ["Content"] = "他就在那里！",
            ["ContentJP"] = "あそこだ！",
            ["DialogueId"] = 12049203,
            ["GUID"] = "1E29F65E",
            ["RelatedWikiId"] = {
                [1] = 203007,
                [2] = 407009,
                [3] = 407013,
                },
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F65E",
            },
        [12049204] = {
            ["Content"] = "今敕尔等——目见天宪即俯首，耳闻法音当束心。",
            ["ContentJP"] = "<Default note=\"text:なんじら\">汝等</>に告ぐ――天の御法度を見ば、<Default note=\"text:こうべ\">頭</>を垂れよ。\
法の御沙汰を聞かば、心を慎め。",
            ["DialogueId"] = 12049204,
            ["GUID"] = "1E29F688",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F688",
            },
        [12049205] = {
            ["Content"] = "来者，何敢叩情辩法？",
            ["ContentJP"] = "来たる者よ、何ゆえ情を以て裁定を求む？",
            ["DialogueId"] = 12049205,
            ["GUID"] = "1E29F6B2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F6B2",
            },
        [12049206] = {
            ["Content"] = "不自量力。",
            ["ContentJP"] = "身の程知らずめ。",
            ["DialogueId"] = 12049206,
            ["GUID"] = "1E29F6DC",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F6DC",
            },
        [12049207] = {
            ["Content"] = "……{nickname}，怎么是你？",
            ["ContentJP"] = "……{nickname}！？",
            ["DialogueId"] = 12049207,
            ["GUID"] = "1E29F706",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F706",
            },
        [12049208] = {
            ["Content"] = "好剑法！",
            ["ContentJP"] = "見事な腕だ！",
            ["DialogueId"] = 12049208,
            ["GUID"] = "1E29F730",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F730",
            },
        [12049209] = {
            ["Content"] = "师兄……原来你已经这么厉害了。",
            ["ContentJP"] = "ユーミン……腕を上げたな……",
            ["DialogueId"] = 12049209,
            ["GUID"] = "1E29F75A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F75A",
            },
        [12049210] = {
            ["Content"] = "刻舟，我问你。",
            ["ContentJP"] = "カシュウ、一つ問いたい。",
            ["DialogueId"] = 12049210,
            ["GUID"] = "1E29F784",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F784",
            },
        [12049211] = {
            ["Content"] = "飘零人只想过“破”，可曾想过“立”？",
            ["ContentJP"] = "お前らは壊すことばかり考えているが、「築く」ことを考えたことはあるのか？",
            ["DialogueId"] = 12049211,
            ["GUID"] = "1E29F7AE",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F7AE",
            },
        [12049212] = {
            ["Content"] = "若是大风九章倾覆，秽兽横行四野，暴行无人约束，芸芸众生将如何得以保全性命？",
            ["ContentJP"] = "もし大風九章が滅び、<Default note=\"text:エジュウ\">穢獣</>が野に放たれたら――縛りを失った地はどうなる？",
            ["DialogueId"] = 12049212,
            ["GUID"] = "1E29F7D8",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F7D8",
            },
        [12049213] = {
            ["Content"] = "自有我们！否则大家苦练这一身武艺做什么？",
            ["ContentJP"] = "俺たちがいる！そのために稽古をつんでいるんだろ！",
            ["DialogueId"] = 12049213,
            ["GUID"] = "1E29F802",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F802",
            },
        [12049214] = {
            ["Content"] = "那<H>秽蚀者</>呢？",
            ["ContentJP"] = "では、<H>穢蝕者</>はどうする。",
            ["DialogueId"] = 12049214,
            ["GUID"] = "1E29F82C",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F82C",
            },
        [12049215] = {
            ["Content"] = "秽蚀者已不复为人，杀了便是——",
            ["ContentJP"] = "アレは人にあらざるものだ。斬るしかない――",
            ["DialogueId"] = 12049215,
            ["GUID"] = "1E29F856",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F856",
            },
        [12049216] = {
            ["Content"] = "……如果那秽蚀者是你的师长、挚友、骨肉至亲呢？",
            ["ContentJP"] = "……もしその「穢蝕者」が、お前の師だったら？友だったら？肉親だったらどうする……？",
            ["DialogueId"] = 12049216,
            ["GUID"] = "1E29F880",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F880",
            },
        [12049217] = {
            ["Content"] = "……可是——！",
            ["ContentJP"] = "それは……！",
            ["DialogueId"] = 12049217,
            ["GUID"] = "1E29F8AA",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F8AA",
            },
        [12049218] = {
            ["Content"] = "够了……！",
            ["ContentJP"] = "もうやめて！",
            ["DialogueId"] = 12049218,
            ["GUID"] = "1E29F8D4",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F8D4",
            },
        [12049219] = {
            ["Content"] = "拜托了，{nickname}，跟我来。一定还有别的解决方法！",
            ["ContentJP"] = "お願い、{nickname}！ついてきて！まだ別の道があるはず……",
            ["DialogueId"] = 12049219,
            ["GUID"] = "1E29F8FE",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F8FE",
            },
        [12049220] = {
            ["Content"] = "让开，我们来了！",
            ["ContentJP"] = "みんな、どいて！！",
            ["DialogueId"] = 12049220,
            ["GUID"] = "1E29F928",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F928",
            },
        [12049221] = {
            ["Content"] = "看来你心意已决。",
            ["ContentJP"] = "……迷いは、もうないようだな。",
            ["DialogueId"] = 12049221,
            ["GUID"] = "1E29F952",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F952",
            },
        [12049222] = {
            ["Content"] = "从今往后，正义将被交还到华胥每一个人的手中。",
            ["ContentJP"] = "正義の定義を……華胥の民の手に返しなさい。",
            ["DialogueId"] = 12049222,
            ["GUID"] = "1E29F97C",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F97C",
            },
        [12049223] = {
            ["Content"] = "华胥子民将怀勇毅之心，行公正之事，无畏罪恶，亦不惧怕灾难。他们……将成为自己的主人。",
            ["ContentJP"] = "皆が勇敢な心を抱き、公正を行い、悪にも災いにも屈しない。そうして……自らが主になれる。",
            ["DialogueId"] = 12049223,
            ["GUID"] = "1E29F9A6",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F9A6",
            },
        [12049224] = {
            ["Content"] = "白龙，那般的未来，你不想看看吗？",
            ["ContentJP"] = "そんな未来を見てみたくない、白龍？",
            ["DialogueId"] = 12049224,
            ["GUID"] = "1E29F9D0",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F9D0",
            },
        [12049225] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "グオォォォ……！",
            ["DialogueId"] = 12049225,
            ["GUID"] = "1E29F9FA",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29F9FA",
            },
        [12049226] = {
            ["Content"] = "{nickname}，你来了。",
            ["ContentJP"] = "{nickname}、来たのね。",
            ["DialogueId"] = 12049226,
            ["GUID"] = "1E29FA24",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FA24",
            },
        [12049227] = {
            ["Content"] = "来，对着这里，捅下去，一剑贯穿。",
            ["ContentJP"] = "ほら、ここよ。ひと思いに、貫いて。",
            ["DialogueId"] = 12049227,
            ["GUID"] = "1E29FA4E",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FA4E",
            },
        [12049228] = {
            ["Content"] = "这不是我此行的目的。",
            ["ContentJP"] = "ここに来た目的はそれじゃない。",
            ["DialogueId"] = 12049228,
            ["GUID"] = "1E29FA78",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FA78",
            },
        [12049229] = {
            ["Content"] = "呵呵……事到如今，还有这种可爱的想法。",
            ["ContentJP"] = "ふふ、この期に及んで……まだそんな綺麗事を。",
            ["DialogueId"] = 12049229,
            ["GUID"] = "1E29FAA2",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FAA2",
            },
        [12049230] = {
            ["Content"] = "止流掌柜，你先前说，你没有留给我选择。但你错了。",
            ["ContentJP"] = "シリュウさん、あなたは間違ってる。",
            ["DialogueId"] = 12049230,
            ["GUID"] = "1E29FACC",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FACC",
            },
        [12049231] = {
            ["Content"] = "我来这里，就是为了向你证明——",
            ["ContentJP"] = "{性别:僕は証明しに来たんだ。|私は証明しに来たの。}",
            ["DialogueId"] = 12049231,
            ["GUID"] = "1E29FAF6",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FAF6",
            },
        [12049232] = {
            ["Content"] = "人是可以开辟出新的选项的。",
            ["ContentJP"] = "人には、別の道を切り開く力があるってことをね！",
            ["DialogueId"] = 12049232,
            ["GUID"] = "1E29FB20",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB20",
            },
        [12049233] = {
            ["Content"] = "和鸣之力……？",
            ["ContentJP"] = "レゾナンス……！？",
            ["DialogueId"] = 12049233,
            ["GUID"] = "1E29FB4A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB4A",
            },
        [12049234] = {
            ["Content"] = "……我们还会在这里，被困多久？",
            ["ContentJP"] = "ねえ……あとどれくらい歩いたら、ここから出られるのかな……？",
            ["DialogueId"] = 12049234,
            ["GUID"] = "1E29FB74",
            ["NextDialogue"] = 12049235,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB74",
            },
        [12049235] = {
            ["Content"] = "我们大人会找到出路的。安心，孩子，你现在要做的是好好休息，保存体力。",
            ["ContentJP"] = "あのお方が必ずや出口を見つけてくれるはずだ。お前はしっかり休んで、体力を温存しなさい。",
            ["DialogueId"] = 12049235,
            ["GUID"] = "1E29FB9E",
            ["NextDialogue"] = 12049236,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FB9E",
            },
        [12049236] = {
            ["Content"] = "好安静啊……我们会不会被所有人遗忘，就这样再也出不去了？",
            ["ContentJP"] = "……ここは本当に静かね。まさか……このまま、誰にも気づかれないまま、ここで……",
            ["DialogueId"] = 12049236,
            ["GUID"] = "1E29FBC8",
            ["NextDialogue"] = 12049237,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FBC8",
            },
        [12049237] = {
            ["Content"] = "你若是老想着这个问题，时间就会变得格外漫长。就像人平时习惯了待在屋檐底下，一旦屋檐失修，就会对迎面而来的雨水茫然失措。",
            ["ContentJP"] = "同じことばかり考えてると、時間はよけいに長く感じるもんだ。人は屋根の下に慣れすぎて、いざそれが失われた時、雨の冷たさに戸惑ってしまう。",
            ["DialogueId"] = 12049237,
            ["GUID"] = "1E29FBF2",
            ["NextDialogue"] = 12049238,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FBF2",
            },
        [12049238] = {
            ["Content"] = "不如换个视角，这跳出常规的雨水的滋味，在日常生活中可不多见。细细体验当下的感受，待日后被救出去了，不也是一桩不错的谈资？",
            ["ContentJP"] = "でもな、屋根が壊れたからこそ味わえる雨ってのもある。そう思えば、この経験もいつか語れる話になる。……だろ？",
            ["DialogueId"] = 12049238,
            ["GUID"] = "1E29FC1C",
            ["NextDialogue"] = 12049239,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC1C",
            },
        [12049239] = {
            ["Content"] = "事后想来，那一天的洞穴塌方，大约就是烛阴之灾初显的征兆。",
            ["ContentJP"] = "思えば、あの日の洞窟崩落が、燭陰の禍の始まりだったのかもしれない。",
            ["DialogueId"] = 12049239,
            ["GUID"] = "1E29FC46",
            ["NextDialogue"] = 12049240,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC46",
            },
        [12049240] = {
            ["Content"] = "虽然受困于此，实属不幸之事。但和这个生性乐观的人待在一起，好像也没那么难熬……这会成为一段终生难忘的经历吧，我如此想着。",
            ["ContentJP"] = "ここに閉じ込められたのは、不幸の事故だ。けれど――あの楽観的な人と一緒だったから、苦しさも、どこかやわらいでいた。\
この体験はきっと、私の人生でも忘れられない記憶になる。そう思っていた。",
            ["DialogueId"] = 12049240,
            ["GUID"] = "1E29FC70",
            ["NextDialogue"] = 12049241,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC70",
            },
        [12049241] = {
            ["Content"] = "……但随着时间推移，连续数日粒米未进后，我已经顾不上思考那么多事情了。",
            ["ContentJP"] = "……しかし、やがて食糧が尽き、何日も空腹が続いた。その後のことはもうあまり覚えていない。",
            ["DialogueId"] = 12049241,
            ["GUID"] = "1E29FC9A",
            ["NextDialogue"] = 12049242,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FC9A",
            },
        [12049242] = {
            ["Content"] = "好饿……好饿……救援何时才能到来？",
            ["ContentJP"] = "腹……減った……いつまで待てば、助けは来るの……",
            ["DialogueId"] = 12049242,
            ["GUID"] = "1E29FCC4",
            ["NextDialogue"] = 12049243,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FCC4",
            },
        [12049243] = {
            ["Content"] = "这山洞如此偏僻，等旁人发现我们失踪，再等救援队找过来，不知还要过上多少时日……",
            ["ContentJP"] = "この場所、あまりにも人里から離れてる。行方不明だって気づかれて、救助隊が来るまで、いったい何日かかるか……",
            ["DialogueId"] = 12049243,
            ["GUID"] = "1E29FCEE",
            ["NextDialogue"] = 12049244,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FCEE",
            },
        [12049244] = {
            ["Content"] = "啊啊……那，等他们寻过来，我们的尸骨不是都凉透了吗？",
            ["ContentJP"] = "その頃には……もう、骨だけになってるんじゃ……",
            ["DialogueId"] = 12049244,
            ["GUID"] = "1E29FD18",
            ["NextDialogue"] = 12049245,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD18",
            },
        [12049245] = {
            ["Content"] = "对了，我们有大风九章，我们还有大风九章不是吗？白龙神君总会庇佑祂的子民，对不对！",
            ["ContentJP"] = "でも、大風九章が……白龍様がきっと、私たちを守ってくれるよね……？",
            ["DialogueId"] = 12049245,
            ["GUID"] = "1E29FD42",
            ["NextDialogue"] = 12049246,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD42",
            },
        [12049246] = {
            ["Content"] = "但应天尉的职责是惩恶除奸，他们真的会为我们而来吗……",
            ["ContentJP"] = "でも、応天尉の役目は悪を裁くことだ。こんな私たちのために、ほんとに来てくれるの……？",
            ["DialogueId"] = 12049246,
            ["GUID"] = "1E29FD6C",
            ["NextDialogue"] = 12049247,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD6C",
            },
        [12049247] = {
            ["Content"] = "可恶！若我们饿死在此处，便只能成为意外卷宗上的一行数字了吗？",
            ["ContentJP"] = "……ふざけるな。ここで死んだって、結局「事故死」って記録されて終わりだろうが！",
            ["DialogueId"] = 12049247,
            ["GUID"] = "1E29FD96",
            ["NextDialogue"] = 12049248,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FD96",
            },
        [12049248] = {
            ["Content"] = "你疯了？！",
            ["ContentJP"] = "やめろ！！",
            ["DialogueId"] = 12049248,
            ["GUID"] = "1E29FDC0",
            ["NextDialogue"] = 12049249,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FDC0",
            },
        [12049249] = {
            ["Content"] = "你想干什么？！",
            ["ContentJP"] = "正気か！？",
            ["DialogueId"] = 12049249,
            ["GUID"] = "1E29FDEA",
            ["NextDialogue"] = 12049250,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FDEA",
            },
        [12049250] = {
            ["Content"] = "上天保佑——勿滥杀，休行凶！这可是诫律啊，你怎么能违反诫律呢？！",
            ["ContentJP"] = "お願い、やめて！暴力は……それは戒律違反だよ！！",
            ["DialogueId"] = 12049250,
            ["GUID"] = "1E29FE14",
            ["NextDialogue"] = 12049251,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE14",
            },
        [12049251] = {
            ["Content"] = "我不知道什么诫律——我只知道这里有活生生的食物！",
            ["ContentJP"] = "そんなもん知るか！今ここに「食い物」がある、それだけで十分だ！",
            ["DialogueId"] = 12049251,
            ["GUID"] = "1E29FE3E",
            ["NextDialogue"] = 12049252,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE3E",
            },
        [12049252] = {
            ["Content"] = "你、你就不怕大风九章降下惩罚吗？！",
            ["ContentJP"] = "お、お前……本気で罰が下るよ、大風九章は……",
            ["DialogueId"] = 12049252,
            ["GUID"] = "1E29FE68",
            ["NextDialogue"] = 12049253,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE68",
            },
        [12049253] = {
            ["Content"] = "应天尉也不是无所不能的。不是有那些什么飘零人吗？再不济，抢艘船，逃往海外去！",
            ["ContentJP"] = "応天尉も万能じゃねぇだろ。最悪、流れ者になり、船を奪っで異国にでも逃げちまえばいいんだよ！",
            ["DialogueId"] = 12049253,
            ["GUID"] = "1E29FE92",
            ["NextDialogue"] = 12049254,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FE92",
            },
        [12049254] = {
            ["Content"] = "但首先得吃饱了肚子。我可不会像你们一样干等着！要是饿死在这里，一切免谈！",
            ["ContentJP"] = "そのためにも――まずは腹を満たすことだ！飢え死にしてからじゃ何もできねぇ！",
            ["DialogueId"] = 12049254,
            ["GUID"] = "1E29FEBC",
            ["NextDialogue"] = 12049255,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FEBC",
            },
        [12049255] = {
            ["Content"] = "你、你…………",
            ["ContentJP"] = "お、お前……",
            ["DialogueId"] = 12049255,
            ["GUID"] = "1E29FEE6",
            ["NextDialogue"] = 12049256,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FEE6",
            },
        [12049256] = {
            ["Content"] = "就要死在这里了吗？尽管心中还留有对死亡的恐惧，但饥饿已经让我连一根手指都无法动弹。",
            ["ContentJP"] = "……ここで、死ぬのかな。怖い。でも、飢えた体がもう動かない。",
            ["DialogueId"] = 12049256,
            ["GUID"] = "1E29FF10",
            ["NextDialogue"] = 12049257,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF10",
            },
        [12049257] = {
            ["Content"] = "此时此刻，唯一能做的，恐怕只有闭上双眼，不去见证自己死亡的一刻吧。",
            ["ContentJP"] = "できるのは、ただ目を閉じることだけだった。",
            ["DialogueId"] = 12049257,
            ["GUID"] = "1E29FF3A",
            ["NextDialogue"] = 12049258,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF3A",
            },
        [12049258] = {
            ["Content"] = "——放开她！！",
            ["ContentJP"] = "――離れろッ！！",
            ["DialogueId"] = 12049258,
            ["GUID"] = "1E29FF64",
            ["NextDialogue"] = 12049259,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF64",
            },
        [12049259] = {
            ["Content"] = "呀！！有人杀人啦！！！",
            ["ContentJP"] = "ひっ！人殺し！！！",
            ["DialogueId"] = 12049259,
            ["GUID"] = "1E29FF8E",
            ["NextDialogue"] = 12049260,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FF8E",
            },
        [12049260] = {
            ["Content"] = "那时，我想到了自己各种可能的结局。饿死，或者被那些尖叫着的，昏了头的大人杀掉。",
            ["ContentJP"] = "あのとき私は、あらゆる最悪の結末を考えてた。飢えて死ぬか、あるいは錯乱した大人に殺されるか。",
            ["DialogueId"] = 12049260,
            ["GUID"] = "1E29FFB8",
            ["NextDialogue"] = 12049261,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FFB8",
            },
        [12049261] = {
            ["Content"] = "我唯独没有想到的是，没过多久，我们就看到了刺眼的阳光，还有那天神一般的应天尉——是的，我们获救了，大风九章的代行者清理开塌方，我们得见天日。",
            ["ContentJP"] = "だけど、思ってもみなかったことが起きた。まぶしい光――天から降りてきたような応天尉。崩れた岩が退けられ、私たちは助け出された。",
            ["DialogueId"] = 12049261,
            ["GUID"] = "1E29FFE2",
            ["NextDialogue"] = 12049262,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E29FFE2",
            },
        [12049262] = {
            ["Content"] = "我更没有想到的是，让他们赶来的，不是我们绝望的呼号……",
            ["ContentJP"] = "でも……あの人たちが来た理由は、私たちの悲鳴が届いたからではなかった。",
            ["DialogueId"] = 12049262,
            ["GUID"] = "1E2A000C",
            ["NextDialogue"] = 12049263,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A000C",
            },
        [12049263] = {
            ["Content"] = "而是那个触犯诫律之人。是的，他们来这儿，是为了处决那个男人——我的恩人。",
            ["ContentJP"] = "あの人――戒律を破った、私の恩人を処刑するためだったのだ。",
            ["DialogueId"] = 12049263,
            ["GUID"] = "1E2A0036",
            ["NextDialogue"] = 12049264,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0036",
            },
        [12049264] = {
            ["Content"] = "令夫虽有见义勇为之实，但诛人者受死，是大风九章定死的规矩。如今这下场，实属无奈……还请两位节哀顺变。",
            ["ContentJP"] = "旦那は確かに正義のために動かれた。だが――人を殺めた者には、死が与えられる。それが大風九章の厳格な規律だ。二人とも、どうか悲しまずに……",
            ["DialogueId"] = 12049264,
            ["GUID"] = "1E2A0060",
            ["NextDialogue"] = 12049265,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0060",
            },
        [12049265] = {
            ["Content"] = "阿爹是大英雄，有什么好节哀的！有爹这样的骄傲，我高兴还来不及！",
            ["ContentJP"] = "父ちゃんは英雄だ！悲しむもんか！父ちゃんは俺の誇りなんだ！",
            ["DialogueId"] = 12049265,
            ["GUID"] = "1E2A008A",
            ["NextDialogue"] = 12049266,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A008A",
            },
        [12049266] = {
            ["Content"] = "多谢您前后打点。只是，这墓上真不可留名吗？",
            ["ContentJP"] = "……いろいろと、お骨折りいただきありがとうございました。ただ、この墓に……名前を刻むことすらできないのでしょうか？",
            ["DialogueId"] = 12049266,
            ["GUID"] = "1E2A00B4",
            ["NextDialogue"] = 12049267,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A00B4",
            },
        [12049267] = {
            ["Content"] = "抱歉，伏天诛之人不可在墓前留名……这是古往今来定下的规矩。",
            ["ContentJP"] = "……申し訳ない。伏天の名のもと処された者の墓には、名を刻んではならぬ――それが、昔から定められてきた決まりだ。",
            ["DialogueId"] = 12049267,
            ["GUID"] = "1E2A00DE",
            ["NextDialogue"] = 12049268,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A00DE",
            },
        [12049268] = {
            ["Content"] = "……我明白了。那我们也不给您再多添麻烦了，我随后便带舟儿移居他处。但这墓还请您多照看，别使杂草淹没了。",
            ["ContentJP"] = "……分かりました。ではこれ以上ご迷惑はおかけしません。この子を連れて、村を出ます。\
ただ……この墓だけは、どうか……雑草に埋もれさせないよう、見守ってやってください。",
            ["DialogueId"] = 12049268,
            ["GUID"] = "1E2A0108",
            ["NextDialogue"] = 12049269,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0108",
            },
        [12049269] = {
            ["Content"] = "当得，当得。",
            ["ContentJP"] = "承知した。",
            ["DialogueId"] = 12049269,
            ["GUID"] = "1E2A0132",
            ["NextDialogue"] = 12049270,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0132",
            },
        [12049270] = {
            ["Content"] = "没想到村口那个叫刻铭的，平时看起来道貌岸然，却触犯了大风九章定下的诛人罪！",
            ["ContentJP"] = "まさかカメイが人を殺すなんてな……あんな真面目そうな顔して、裏じゃ何をしてたか分かったもんじゃない……",
            ["DialogueId"] = 12049270,
            ["GUID"] = "1E2A015C",
            ["NextDialogue"] = 12049271,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A015C",
            },
        [12049271] = {
            ["Content"] = "我们椒兰村，向来安分守己，谁想到却出了这样一个罪人。真是以后说出去都脸上无光呀。",
            ["ContentJP"] = "うちの村は、いつも清く正しくやってきたんだ。あんな奴が出たとあっちゃ……村の名折れだな。",
            ["DialogueId"] = 12049271,
            ["GUID"] = "1E2A0186",
            ["NextDialogue"] = 12049272,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0186",
            },
        [12049272] = {
            ["Content"] = "赶走，赶紧把那一家人逐出村外！",
            ["ContentJP"] = "さっさと一家まとめて、村から追い出せ！",
            ["DialogueId"] = 12049272,
            ["GUID"] = "1E2A01B0",
            ["NextDialogue"] = 12049273,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A01B0",
            },
        [12049273] = {
            ["Content"] = "不是的！他不是罪人，他明明是见义勇为的英雄！",
            ["ContentJP"] = "ちがう！あの人は罪人なんかじゃない！人を危機から救った英雄だよ！！",
            ["DialogueId"] = 12049273,
            ["GUID"] = "1E2A01DA",
            ["NextDialogue"] = 12049274,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A01DA",
            },
        [12049274] = {
            ["Content"] = "见义勇为？华胥不需要这种东西。有了大风九章的庇佑，一切等待狴犴和应天尉来解决不就好？",
            ["ContentJP"] = "英雄？そんなもの、華胥にはいらない。大風九章があればいい。狴犴と応天尉に任せておけば、全部解決する。",
            ["DialogueId"] = 12049274,
            ["GUID"] = "1E2A0204",
            ["NextDialogue"] = 12049275,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0204",
            },
        [12049275] = {
            ["Content"] = "如果应天尉迟到了呢？！如果没有人能帮助受害者呢？",
            ["ContentJP"] = "……でも！もし応天尉が来なかったら？もし誰も助けてくれなかったら？",
            ["DialogueId"] = 12049275,
            ["GUID"] = "1E2A022E",
            ["NextDialogue"] = 12049276,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A022E",
            },
        [12049276] = {
            ["Content"] = "迟到？不可能不可能！",
            ["ContentJP"] = "来ない？ありえないね！",
            ["DialogueId"] = 12049276,
            ["GUID"] = "1E2A0258",
            ["NextDialogue"] = 12049277,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0258",
            },
        [12049277] = {
            ["Content"] = "——但若是这种事情当真发生了，也只能算那个人运气不好吧。再怎么说，触犯戒律也是不对的呀！",
            ["ContentJP"] = "仮にそうだったとしても、それは運が悪かっただけだ。いくら正しかろうと、戒律を破ったら、それは罪なんだよ。",
            ["DialogueId"] = 12049277,
            ["GUID"] = "1E2A0282",
            ["NextDialogue"] = 12049278,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0282",
            },
        [12049278] = {
            ["Content"] = "若是径直走进这雨幕，就能体验到不一样的视角吗？我试图按他所言去尝试，却只感受到冰冷刺骨的雨水吞没了一切。",
            ["ContentJP"] = "もし、あの雨の中へ踏み出したら、彼の言った「別の視点」が見えると思った。でも――私の肌に触れたのは、ただ冷たく、鋭く、骨まで染み込む雨のみだった。",
            ["DialogueId"] = 12049278,
            ["GUID"] = "1E2A02AC",
            ["NextDialogue"] = 12049279,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A02AC",
            },
        [12049279] = {
            ["Content"] = "那一天，我茫然地在雨中走着。这是歹徒的错吗？亦或是大风九章酿成的悲剧？还是如他们所说——仅仅是一次坏运气招致的差错？",
            ["ContentJP"] = "その日、私は雨の中をひたすら歩いた。この悲劇は、あの暴徒のせいなのか？それとも、大風九章の制度が生んだもの？あるいは、彼らの言うとおり、単なる「不運」だったのかしら……？",
            ["DialogueId"] = 12049279,
            ["GUID"] = "1E2A02D6",
            ["NextDialogue"] = 12049280,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A02D6",
            },
        [12049280] = {
            ["Content"] = "不，不是这样的——我逐渐认识到。那些站在屋檐下的人，他们忘记了雨水的滋味。",
            ["ContentJP"] = "……いや、違う。私は、少しずつ気づき始めた。屋根の下に安住する人々は、雨の冷たさを忘れてしまった。",
            ["DialogueId"] = 12049280,
            ["GUID"] = "1E2A0300",
            ["NextDialogue"] = 12049281,
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A0300",
            },
        [12049281] = {
            ["Content"] = "他们变得软弱、冷漠，无法再用自己的意志判断什么是正义，也无法用双手保护自己。屋檐庇护了他们太久，但这种情况不应当再持续下去了。",
            ["ContentJP"] = "ぬるま湯の中で、意志と愛を失い、正義すら見分けられなくなっていた。その腕で何かを守ろうともせず、ただ誰かが来るのを待っているだけだった。\
――そのぬくもりの中に、私たちはいすぎた。もう終わらせなくちゃ。",
            ["DialogueId"] = 12049281,
            ["GUID"] = "1E2A032A",
            ["VoiceName"] = "voice/$Locale$/story/1204/120492/1E2A032A",
            },
        [12049301] = {
            ["Content"] = "这家伙一定留下了破绽，我们在附近找找看！",
            ["ContentJP"] = "こやつめ、しっぽを出すに違いない！近くを探してみよう！",
            ["DialogueId"] = 12049301,
            ["GUID"] = "12049301.0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120493/12049301",
            },
        [12049302] = {
            ["Content"] = "这里什么都没有……再去其他地方看看吧。",
            ["ContentJP"] = "ここはなにもない…ほかのところを探してみよう！",
            ["DialogueId"] = 12049302,
            ["GUID"] = "12049302.0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120493/12049302",
            },
        [12049303] = {
            ["Content"] = "大功告成！小仆从，我们赶紧回去把香囊还给她吧！",
            ["ContentJP"] = "よーし！我が下僕よ、はやく香袋を返しましょう！",
            ["DialogueId"] = 12049303,
            ["GUID"] = "12049303.0",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1204/120493/12049303",
            },
        [12060101] = {
            ["Content"] = "书接上回，英雄出少年，只见那白发独眼的年轻人提刀出阵，群玄色狴犴便齐齐战栗，退步低吼——",
            ["ContentJP"] = "さて、物語の続きを語るとしよう。英雄は若くして現れた――銀髪の隻眼、若き剣士が刀を手に陣を抜けるや、群がる玄狴は一斉に身を震わせ、唸り声を上げて後ずさった――",
            ["DialogueId"] = 12060101,
            ["GUID"] = "1E30F252",
            ["NextDialogue"] = 12060102,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 405014,
                [4] = 405015,
                },
            ["SpeakNpcId"] = 250007,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F252",
            },
        [12060102] = {
            ["Content"] = "号外——号外——华胥四年一度的至高盛事，奉香群英试今日召开。想看热门参赛队伍分析？尽在这份《皓京市声报》特刊中——",
            ["ContentJP"] = "号外だよーっ！号外ーっ！四年に一度、<Default note=\"text:カショ\">華胥</>を沸かす最大の祭典――「<Default note=\"text:ほうこうえいゆうたいかい\">奉香英雄大会</>」が、ついに本日開幕！注目のチームの徹底分析は、『皓京市速報』特別号にて！",
            ["DialogueId"] = 12060102,
            ["GUID"] = "1E30F27C",
            ["NextDialogue"] = 12060103,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F27C",
            },
        [12060103] = {
            ["Content"] = "老板，小笼包再来一笼，要刚刚出锅皮薄馅大的！",
            ["ContentJP"] = "店長さーん、<Default note=\"text:ショウロンポウ\">小籠包</>、もうひと<Default note=\"text:かご\">籠</>お願い！蒸したての、皮が透けるくらい薄くて、肉汁がじゅわっと出るやつね！",
            ["DialogueId"] = 12060103,
            ["GUID"] = "1E30F2A6",
            ["NextDialogue"] = 12060104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F2A6",
            },
        [12060104] = {
            ["Content"] = "好嘞——",
            ["ContentJP"] = "へいっ！",
            ["DialogueId"] = 12060104,
            ["GUID"] = "1E30F2D0",
            ["NextDialogue"] = 12060105,
            ["SpeakNpcId"] = 250008,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F2D0",
            },
        [12060105] = {
            ["Content"] = "嘿嘿，他们要是知道那 “白发独眼”的大英雄就坐在这里，会不会吓一大跳？小仆从，这就是出名的感觉吗！",
            ["ContentJP"] = "ふふ、もしみんなが知ったらどうなるだろうね？あの「白髪で隻眼」の英雄が――いま、<Default note=\"text:こうけい\">皓京</>の朝の光の中で、小籠包なんか頬張ってるって知ったらさ。「名を馳せる」って……こんな気持ちなんだね！？",
            ["DialogueId"] = 12060105,
            ["GUID"] = "1E30F2FA",
            ["NextDialogue"] = 12060106,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F2FA",
            },
        [12060106] = {
            ["Content"] = "吹着小风，在皓京的街头吃吃早茶，听听人来人往的聊天。这才是我们在华胥应当过上的悠闲生活嘛！",
            ["ContentJP"] = "ほら、風が気持ちいい。人の声が重なりあって、街が生きてるって感じがする。こうして茶をすするだけで、胸の奥がふわっと温かくなるんだ――これぞ理想の朝じゃない！？",
            ["DialogueId"] = 12060106,
            ["GUID"] = "1E30F324",
            ["NextDialogue"] = 12060107,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F324",
            },
        [12060107] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………（遠くを見つめたまま沈黙）",
            ["DialogueId"] = 12060107,
            ["GUID"] = "1E30F34E",
            ["NextDialogue"] = 12060108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F34E",
            },
        [12060108] = {
            ["Content"] = "喂——小仆从——",
            ["ContentJP"] = "おーい、我が下僕ー？ねえってば！",
            ["DialogueId"] = 12060108,
            ["GUID"] = "1E30F378",
            ["NextDialogue"] = 12060109,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F378",
            },
        [12060109] = {
            ["Content"] = "哎？啊，嗯……",
            ["ContentJP"] = "あっ、うん……なに？",
            ["DialogueId"] = 12060109,
            ["GUID"] = "1E30F3A2",
            ["NextDialogue"] = 12060110,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F3A2",
            },
        [12060110] = {
            ["Content"] = "我说，你怎么有点心不在焉的样子？莫非是在担心黎瑟留给你的那个情报？",
            ["ContentJP"] = "なんか、考えごとしてたでしょ？もしかして――リズムがくれた「あの情報」、引っかかってる？",
            ["DialogueId"] = 12060110,
            ["GUID"] = "1E30F3CC",
            ["NextDialogue"] = 12060111,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F3CC",
            },
        [12060111] = {
            ["Content"] = "是有点……竟然被你看出来了。",
            ["ContentJP"] = "うん、まあね……見抜かれちゃったか。",
            ["DialogueId"] = 12060111,
            ["GUID"] = "1E30F3F6",
            ["NextDialogue"] = 12060112,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F3F6",
            },
        [12060112] = {
            ["Content"] = "明明我们在华胥只待了几天，但是发生太多太多事情了，像是过去了很长时间一样。",
            ["ContentJP"] = "ここに来て、まだほんの数日しか経ってないのに、たくさんのことがあって――時間がね、すごく長く感じる{性别:んだ|の}。",
            ["DialogueId"] = 12060112,
            ["GUID"] = "1E30F420",
            ["NextDialogue"] = 12060113,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F420",
            },
        [12060113] = {
            ["Content"] = "这些天不在冰湖城，难免会担心会不会再有什么变数。",
            ["ContentJP"] = "アイスレイク城を離れてずいぶん経つし、また何か起きてるんじゃないかって、つい考えてしまって……",
            ["DialogueId"] = 12060113,
            ["GUID"] = "1E30F44A",
            ["NextDialogue"] = 12060114,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F44A",
            },
        [12060114] = {
            ["Content"] = "放心吧！止流姐姐拍着胸脯保证，三天后给我们加急安排回冰湖城的空艇一定会启程，这次风雨无阻，什么意外都阻止不了它！",
            ["ContentJP"] = "だいじょーぶ！シリュウが、ちゃーんと保証してくれたからね！三日後には急行飛空艇が出発するって。嵐が来ようが雷が落ちようが、絶対に問題ナッシング！",
            ["DialogueId"] = 12060114,
            ["GUID"] = "1E30F474",
            ["NextDialogue"] = 12060115,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F474",
            },
        [12060115] = {
            ["Content"] = "我谢谢你，白。本来没太担心的，被你这张乌鸦嘴一说，可就不一定了。",
            ["ContentJP"] = "うん、ありがとう。でもさ……なんか逆に不安になってきた。フラグにしか聞こえないっていうか……",
            ["DialogueId"] = 12060115,
            ["GUID"] = "1E30F49E",
            ["NextDialogue"] = 12060116,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F49E",
            },
        [12060116] = {
            ["Content"] = "我、我什么时候乌鸦嘴了，小仆从，你可别乱说话！魔王大人怎么会和那种晦气的属性挂钩！",
            ["ContentJP"] = "ちょ、ちょっと待って！？フラグってなんだよ！？そんな縁起でもないキャラじゃないでしょ！？魔王様を疫病神扱いするとは、不敬な！！",
            ["DialogueId"] = 12060116,
            ["GUID"] = "1E30F4C8",
            ["NextDialogue"] = 12060117,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F4C8",
            },
        [12060117] = {
            ["Content"] = "话音刚落，不远处的巷尾就爆发出一阵激烈的争吵声。",
            ["ContentJP"] = "その瞬間――まるで運命が応えたかのように、路地の奥から騒がしい声が響き渡る。",
            ["DialogueId"] = 12060117,
            ["GUID"] = "1E30F4F2",
            ["NextDialogue"] = 12060118,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F4F2",
            },
        [12060118] = {
            ["Content"] = "……这、这是什么玩意？！……",
            ["ContentJP"] = "…………な、なんだこれ！？……（混乱と叫び）",
            ["DialogueId"] = 12060118,
            ["GUID"] = "1E30F51C",
            ["NextDialogue"] = 12060119,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F51C",
            },
        [12060119] = {
            ["Content"] = "哇，那边有人吵起来了，小仆从，我们赶紧去看看！去晚了可凑不上新鲜的热闹了！",
            ["ContentJP"] = "おおっ！？どうしたんだろ！行くよっ！今ならまだ間に合う、出来立てほやほやの事件現場！出遅れたら、話題に乗り遅れちゃうよーっ！",
            ["DialogueId"] = 12060119,
            ["GUID"] = "1E30F546",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120601/1E30F546",
            },
        [12060201] = {
            ["Content"] = "等等，你们听我解释，事情绝对不是你们想的那样——",
            ["ContentJP"] = "待って、お願い、聞いて――本当に、みんなが思ってるようなことじゃないのよ……！",
            ["DialogueId"] = 12060201,
            ["GUID"] = "1E3102BA",
            ["NextDialogue"] = 12060202,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203009,
                [4] = 103001,
                [5] = 405014,
                [6] = 405015,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3102BA",
            },
        [12060202] = {
            ["Content"] = "咳咳，苏乙姑娘，我突然想起来家里有点急事。",
            ["ContentJP"] = "え、ええと、スーイーさん？",
            ["DialogueId"] = 12060202,
            ["GUID"] = "1E3102E4",
            ["NextDialogue"] = 12060203,
            ["SpeakNpcId"] = 250009,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3102E4",
            },
        [12060203] = {
            ["Content"] = "瞧我这脑子，早上出门前老娘还叮嘱过我呢，一转眼就忘了。我就先告辞了哈。",
            ["ContentJP"] = "そ、そうだ、今朝出かける前に、母さんから頼まれごとしてたんだ。うっかり忘れてたよ、はは……じゃ、また。",
            ["DialogueId"] = 12060203,
            ["GUID"] = "1E31030E",
            ["NextDialogue"] = 12060204,
            ["SpeakNpcId"] = 250009,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31030E",
            },
        [12060204] = {
            ["Content"] = "苏乙姑娘，我……",
            ["ContentJP"] = "ええと、私も……",
            ["DialogueId"] = 12060204,
            ["GUID"] = "1E310338",
            ["NextDialogue"] = 12060205,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E310338",
            },
        [12060205] = {
            ["Content"] = "你又有什么借口，家中有事，还是突发恶疾？",
            ["ContentJP"] = "今度は何？家の都合？それとも、急に熱でも出たの？",
            ["DialogueId"] = 12060205,
            ["GUID"] = "1E310362",
            ["NextDialogue"] = 12060206,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E310362",
            },
        [12060206] = {
            ["Content"] = "……违心的话我说不出来，苏乙姑娘，我还是实情相告吧。和飘零人组队这种事情，我恐怕做不到。",
            ["ContentJP"] = "……ウソは、つけないようだね。正直に言うよ。流れ者と組むのは、やっぱり……無理だ。",
            ["DialogueId"] = 12060206,
            ["GUID"] = "1E31038C",
            ["NextDialogue"] = 12060207,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31038C",
            },
        [12060207] = {
            ["Content"] = "我知道飘零人并非什么十恶不赦的坏人，你们也有你们的苦衷。但稳妥起见，为了在这届群英试中拿到好名次，我不想招惹太多麻烦。",
            ["ContentJP"] = "君たちが、悪い人たちじゃないってことはわかってる。事情があることも、理解してるつもりだ。でも……英雄大会で結果を出すには、余計な火種は避けたい。波風立てたくないんだよ。",
            ["DialogueId"] = 12060207,
            ["GUID"] = "1E3103B6",
            ["NextDialogue"] = 12060208,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3103B6",
            },
        [12060208] = {
            ["Content"] = "呜……好吧，至少谢谢你愿意说出真话。",
            ["ContentJP"] = "……そっか。でも、正直に話してくれて、ありがとう。",
            ["DialogueId"] = 12060208,
            ["GUID"] = "1E3103E0",
            ["NextDialogue"] = 12060209,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E3103E0",
            },
        [12060209] = {
            ["Content"] = "苏乙姑娘，我多嘴一句。你知道的，大家对飘零人多少还是有点……介怀，至少短时间内是这样。这次群英试，你的麻烦恐怕还在后头。",
            ["ContentJP"] = "スーイーさん……ひとことだけ言わせて。やっぱり、流れ者のことを、みんな心のどこかで怖れてるんだと思う。少なくとも、すぐに受け入れられる状況じゃない。今回の試合、君にとっては……多難だと思う。",
            ["DialogueId"] = 12060209,
            ["GUID"] = "1E31040A",
            ["NextDialogue"] = 12060210,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31040A",
            },
        [12060210] = {
            ["Content"] = "抱歉。祝你能找到称心如意的队友。",
            ["ContentJP"] = "ごめん。いい仲間が見つかるよう、祈ってる。",
            ["DialogueId"] = 12060210,
            ["GUID"] = "1E310434",
            ["NextDialogue"] = 12060211,
            ["SpeakNpcId"] = 250010,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E310434",
            },
        [12060211] = {
            ["Content"] = "唉，怎么会变成这样……",
            ["ContentJP"] = "……どうして、こんなことに……",
            ["DialogueId"] = 12060211,
            ["GUID"] = "1E31045E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120602/1E31045E",
            },
        [12060301] = {
            ["Content"] = "你还好吗，苏乙？",
            ["ContentJP"] = "……大丈夫？スーイー。",
            ["DialogueId"] = 12060301,
            ["GUID"] = "1E311322",
            ["NextDialogue"] = 12060302,
            ["RelatedWikiId"] = {
                [1] = 408010,
                [2] = 408016,
                [3] = 203009,
                [4] = 103001,
                [5] = 405014,
                [6] = 405015,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311322",
            },
        [12060302] = {
            ["Content"] = "哇啊啊！{nickname}，还有小白，你们怎么来了？刚才那一幕该不会都被你们看到了吧？！",
            ["ContentJP"] = "わあっ！？{nickname}にスノウまで！もしかして、今の一部始終……見ちゃってた！？",
            ["DialogueId"] = 12060302,
            ["GUID"] = "1E31134C",
            ["NextDialogue"] = 12060303,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31134C",
            },
        [12060303] = {
            ["Content"] = "怎么老是被你们撞见落魄的时刻……比起这样，我还是更想在你们心中留下一些光辉形象……",
            ["ContentJP"] = "はあ……なんでこう、毎回毎回――よりによって、こういうときに限って、君たちに会うんだろうね。もっとこう、カッコいいとこ、見せたいのにさ……",
            ["DialogueId"] = 12060303,
            ["GUID"] = "1E311376",
            ["NextOptions"] = {
                [1] = 12060304,
                [2] = 12060305,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311376",
            },
        [12060304] = {
            ["Content"] = "所以发生了什么？",
            ["ContentJP"] = "それで、何があったの？（共感+）",
            ["DialogueId"] = 12060304,
            ["GUID"] = "1E3113A0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12060307,
            },
        [12060305] = {
            ["Content"] = "抱歉，我突然想起来家里有点急事。",
            ["ContentJP"] = "ごめん、ちょっと急用を思い出した……（混沌+）",
            ["DialogueId"] = 12060305,
            ["GUID"] = "1E3113CA",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12060306,
            },
        [12060306] = {
            ["Content"] = "好了好了，知道你从一开始就在了——不用再戳一次本姑娘的伤心事啦！",
            ["ContentJP"] = "わ、わかってるよ！最初からそこにいたんでしょ！？もう、わざわざ傷を抉らなくてもいいじゃない……",
            ["DialogueId"] = 12060306,
            ["GUID"] = "1E3113F4",
            ["NextDialogue"] = 12060307,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3113F4",
            },
        [12060307] = {
            ["Content"] = "我听你们提到了群英试，刚刚的事情和这个有关吗？",
            ["ContentJP"] = "さっき英雄大会って言ってたけど、あの騒ぎ、関係あるの？",
            ["DialogueId"] = 12060307,
            ["GUID"] = "1E31141E",
            ["NextDialogue"] = 12060308,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31141E",
            },
        [12060308] = {
            ["Content"] = "哎？小白，{nickname}，你们难不成也知道今日要召开的<H>奉香群英试</>？",
            ["ContentJP"] = "え、もしかして……スノウと{nickname}も、今日が<H>奉香英雄大会</>の日って知ってたの？",
            ["DialogueId"] = 12060308,
            ["GUID"] = "1E311448",
            ["NextDialogue"] = 12060309,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311448",
            },
        [12060309] = {
            ["Content"] = "当然知道啦，我已经听人们讨论了一早上了！这一定像银烛狂欢一样，是华胥这边很重要的节日吧，就算前面出了这么大的事，还是要如期举行呢。",
            ["ContentJP"] = "もちろん知ってるさ！朝からその話で持ちきりだったもん。銀燭祭りみたいなもんでしょ？<Default note=\"text:カショ\">華胥</>の人たちにとって大事な行事なんだって。前にあんな事件があったのに、ちゃんと開催するんだから、よっぽどだよね。",
            ["DialogueId"] = 12060309,
            ["GUID"] = "1E311472",
            ["NextDialogue"] = 12060310,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311472",
            },
        [12060310] = {
            ["Content"] = "嗯，虽然不确定你说的银烛狂欢具体是什么样的，但应该差不多！",
            ["ContentJP"] = "銀燭祭りってのはよく知らないけど……たぶん、近いと思う！",
            ["DialogueId"] = 12060310,
            ["GUID"] = "1E31149C",
            ["NextDialogue"] = 12060311,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31149C",
            },
        [12060311] = {
            ["Content"] = "<H>奉香大典</>可以追溯到大风九章建立之初，是非常古老的节日哦。每年，华胥人在“奉香人”的带领下，在执律阁向龙神奉香，祈求神明庇佑华胥海晏河清，永世太平。",
            ["ContentJP"] = "<H><Default note=\"text:ほうこうのぎ\">奉香の儀</></>の歴史は、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の創建期にまで遡るの。毎年、<Default note=\"text:カショ\">華胥</>の民は奉香人の先導で、<Default note=\"text:しつりつかく\">執律閣</>に香を献じて龍神に平安と清らかな海の加護を祈る――とても神聖で古い儀式よ。",
            ["DialogueId"] = 12060311,
            ["GUID"] = "1E3114C6",
            ["NextDialogue"] = 12060312,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3114C6",
            },
        [12060312] = {
            ["Content"] = "而<H>奉香群英试</>则是为了选出一位最有资格带领华胥人与神明沟通的“奉香人”。对华胥人来说，这几乎是最光耀门楣，万众瞩目的事了。",
            ["ContentJP"] = "そして<H>奉香英雄大会</>は、その奉香人を選ぶための戦――誰が最もふさわしく神に仕え、祈りを捧げるかを競うの。華胥の民にとっては、この上ない名誉なのよ。",
            ["DialogueId"] = 12060312,
            ["GUID"] = "1E3114F0",
            ["NextDialogue"] = 12060313,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3114F0",
            },
        [12060313] = {
            ["Content"] = "每届奉香大典前，群英试都会如期举办。不过每一届的赛事都不太一样，之前的我也不太清楚……不过我看了今年的赛事安排，居然连我们飘零人都能发挥所长呢！",
            ["ContentJP"] = "年ごとに競技内容は変わるんだけど……今年の試合内容を見て、思わず目を疑っちゃった！なんと、流れ者の得意分野が活かせそうだったの！",
            ["DialogueId"] = 12060313,
            ["GUID"] = "1E31151A",
            ["NextDialogue"] = 12060314,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31151A",
            },
        [12060314] = {
            ["Content"] = "所以，我也想试上一试。",
            ["ContentJP"] = "だから……私も挑戦してみようって、そう思ったんだ。",
            ["DialogueId"] = 12060314,
            ["GUID"] = "1E311544",
            ["NextDialogue"] = 12060315,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311544",
            },
        [12060315] = {
            ["Content"] = "只是，今年的赛制需要三人结伴成队。我就偷偷瞒着山外山的人溜出来，拉了两个好奇的路人组队。哪知他们一听说我是飘零人，就脚底一抹油溜了……唉！",
            ["ContentJP"] = "……ただね、今年は三人一組じゃないと参加できない決まりで。こっそり<Default note=\"text:さんがいさん\">山外山</>を抜け出して、街で声をかけた人たちと即席チームを組んだんだけど……わたしが流れ者だってわかった途端、蜘蛛の子を散らすみたいに逃げていっちゃって……",
            ["DialogueId"] = 12060315,
            ["FinalDialogueId"] = 12060323,
            ["GUID"] = "1E31156E",
            ["NextOptions"] = {
                [1] = 12060316,
                [2] = 12060320,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31156E",
            },
        [12060316] = {
            ["Content"] = "为什么要瞒着山外山？",
            ["ContentJP"] = "どうして山外山に黙って出てきたの？",
            ["DialogueId"] = 12060316,
            ["GUID"] = "1E311598",
            ["NextDialogue"] = 12060317,
            },
        [12060317] = {
            ["Content"] = "那、那个，唐叔那人你也知道，又唠叨又爱操心。要是和他说了我要参赛，他一定会搞得人尽皆知。到时候如果他带一群人来看热闹，我可丢不起这个人……",
            ["ContentJP"] = "そ、それはさ……タンさんのこと、知ってるでしょ？おしゃべりで心配性で、すぐ大騒ぎするから。もし参加のことなんか話したら、山外山の連中全員連れて応援に来るに決まってるでしょ？それって、めちゃくちゃ恥ずかしいじゃん……",
            ["DialogueId"] = 12060317,
            ["GUID"] = "1E3115C2",
            ["NextDialogue"] = 12060318,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3115C2",
            },
        [12060318] = {
            ["Content"] = "（又唠叨又爱操心……你确定说的不是自己吗？）",
            ["ContentJP"] = "（おしゃべりで心配性……それ、自分のことじゃん。）（目を細めて微笑む）",
            ["DialogueId"] = 12060318,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E3115EC",
            ["NextDialogue"] = 12060319,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3115EC",
            },
        [12060319] = {
            ["Content"] = "而且，很多飘零人还是对山外山外面的世界有戒心，一时半会儿也不好改过来，免不了要反对我参赛。在给他们一个大大的惊喜之前，我就先不走露风声啦。",
            ["ContentJP"] = "それにさ、山外山の仲間たちも、外の世界に不安や偏見を抱えてる人が多いんだ。私の参加にも反対するかもしれないし――だったら、結果で驚かせてやったほうが早いでしょ？",
            ["DialogueId"] = 12060319,
            ["GUID"] = "1E311616",
            ["NextDialogue"] = 12060315,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311616",
            },
        [12060320] = {
            ["Content"] = "参加奉香群英试有什么好处吗？",
            ["ContentJP"] = "英雄大会に出ると、何かいいことあるの？",
            ["DialogueId"] = 12060320,
            ["GUID"] = "1E311640",
            ["NextDialogue"] = 12060321,
            },
        [12060321] = {
            ["Content"] = "刚刚说了，在奉香群英试上夺魁是华胥的最高荣誉之一！",
            ["ContentJP"] = "さっきも言ったけど、<Default note=\"text:ほうこうえいゆうたいかい\">奉香英雄大会</>で勝ち残るってことは、<Default note=\"text:カショ\">華胥</>で最も誉れ高い称号を得るってことなの！",
            ["DialogueId"] = 12060321,
            ["GUID"] = "1E31166A",
            ["NextDialogue"] = 12060322,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31166A",
            },
        [12060322] = {
            ["Content"] = "我、我想让全华胥人看到……飘零人不是什么阴沟老鼠，什么法外狂徒，我们也可以非常非常了不起！",
            ["ContentJP"] = "私は……みんなに見せたい。流れ者が、陰に潜んで生きるしかない存在なんかじゃないって。罪人でも、のけ者でもないって――私たちだって、胸を張って生きられるって、証明したいんだ。",
            ["DialogueId"] = 12060322,
            ["GUID"] = "1E311694",
            ["NextDialogue"] = 12060315,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311694",
            },
        [12060323] = {
            ["Content"] = "总而言之，今天出门真是诸事不顺。再这样下去，我都要考虑去算上一卦转转运了……",
            ["ContentJP"] = "……はぁ。だけど今日に限って、ほんとツイてない。このままだと、お祓いでもしてもらいたくなってきたよ……",
            ["DialogueId"] = 12060323,
            ["GUID"] = "1E3116BE",
            ["NextDialogue"] = 12060324,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3116BE",
            },
        [12060324] = {
            ["Content"] = "说起来，飘零人三个字又没写在你脑门上，好好的怎么会身份暴露？难不成你现在也是城里的大名人了嘛？",
            ["ContentJP"] = "でもさ、流れ者なんて額に書いてあるわけじゃないでしょ？どうして身バレしたのさ？まさか、スーイーって、もう街じゃ有名人なの？",
            ["DialogueId"] = 12060324,
            ["GUID"] = "1E3116E8",
            ["NextDialogue"] = 12060325,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3116E8",
            },
        [12060325] = {
            ["Content"] = "呜，那倒没有啦……这就要说到我为这次群英试特意准备的“矩子巡枢贰型·青鸾”了，简称青鸾贰型，这可是我的制胜绝招！",
            ["ContentJP"] = "や、やめてよっ、そんなわけないってば！でも、ちょっとした事情があってね……今回のために開発した切り札――「ノリ機装・二ノ型『<Default note=\"text:せいほう\">青鳳</>』」、通称「青鳳二型」があるんだけど、これがまたすごくてね！",
            ["DialogueId"] = 12060325,
            ["GUID"] = "1E311712",
            ["NextDialogue"] = 12060326,
            ["RelatedWikiId"] = {
                [1] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311712",
            },
        [12060326] = {
            ["Content"] = "矩子什么什么……虽然不太明白，但是这么长的名字，一听就很有实力。魔王大人表示认可！",
            ["ContentJP"] = "ノリ……なんだって？うーん、よくわかんないけど、その長ったらしい名前、強そう！この魔王様が太鼓判を押してやろう！",
            ["DialogueId"] = 12060326,
            ["GUID"] = "1E31173C",
            ["NextDialogue"] = 12060327,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31173C",
            },
        [12060327] = {
            ["Content"] = "（倒也不是名字越长就越拉风啦……）",
            ["ContentJP"] = "（いや、長けりゃいいってもんじゃ……）",
            ["DialogueId"] = 12060327,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E311766",
            ["NextDialogue"] = 12060328,
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311766",
            },
        [12060328] = {
            ["Content"] = "我原本和队友们约定好，进了赛场就兵分两路，准备单独行动时再把青鸾贰型拿出来。所以用包袱皮将它裹得严严实实的。",
            ["ContentJP"] = "一応チームでは、途中から別行動を取る作戦だったの。だから青鳳二型も、風呂敷でぐるぐるに包んで、こっそり持ち込んでたんだけど――",
            ["DialogueId"] = 12060328,
            ["GUID"] = "1E311790",
            ["NextDialogue"] = 12060329,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311790",
            },
        [12060329] = {
            ["Content"] = "结果包袱皮不知道怎么的突然散开了。我先前给它加装了一些……咳咳，重火力的先进模块，还没来得及掩饰。别人一看到就暴露了。",
            ["ContentJP"] = "何がどうしたのか、急に包みが解けちゃって……！\
しかも、あれ、実は……ちょっとした重火力モジュールを搭載してて……うっかり人目についちゃって、そっからバレバレに……！",
            ["DialogueId"] = 12060329,
            ["GUID"] = "1E3117BA",
            ["NextDialogue"] = 12060330,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3117BA",
            },
        [12060330] = {
            ["Content"] = "在哪里在哪里，这么有意思的东西，我也要看！",
            ["ContentJP"] = "え、なになに！？そんなおもしろそうなもの、どこどこ！？ねえ、私にも見せてよー！",
            ["DialogueId"] = 12060330,
            ["GUID"] = "1E3117E4",
            ["NextDialogue"] = 12060331,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3117E4",
            },
        [12060331] = {
            ["Content"] = "喏，就放在我背后的桌子上。",
            ["ContentJP"] = "あそこ、後ろの机の上に置いてあるやつ……",
            ["DialogueId"] = 12060331,
            ["GUID"] = "1E31180E",
            ["NextDialogue"] = 12060332,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31180E",
            },
        [12060332] = {
            ["Content"] = "苏乙，你说的那个青鸾贰型，难不成是一截章鱼触手的模样？",
            ["ContentJP"] = "……スーイー。まさか、あれが<Default note=\"text:せいほう\">青鳳</>二型ってやつ？どう見ても……タコの足なんだけど……？",
            ["DialogueId"] = 12060332,
            ["GUID"] = "1E311838",
            ["NextDialogue"] = 12060333,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311838",
            },
        [12060333] = {
            ["Content"] = "嗯，怎么可能？本姑娘的得意作品，自然是以乙鸟为原型。",
            ["ContentJP"] = "ばっ、ばかなこと言わないで！これは<Default note=\"text:いちょう\">乙鳥</>をモデルにしたからくりだよ！",
            ["DialogueId"] = 12060333,
            ["GUID"] = "1E311862",
            ["NextDialogue"] = 12060334,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311862",
            },
        [12060334] = {
            ["Content"] = "再说了，谁会选择章鱼触手作为机傀的外型啊。湿哒哒的满是粘液，仿生细节处理起来还很麻烦。只能说是没品味！",
            ["ContentJP"] = "タコの触手なんて、誰が選ぶもんですか！ぬめってるし、粘液まみれだし、手入れも大変だし……センスなさすぎでしょ！",
            ["DialogueId"] = 12060334,
            ["GUID"] = "1E31188C",
            ["NextDialogue"] = 12060335,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31188C",
            },
        [12060335] = {
            ["Content"] = "不好，是小贼！我倾注了无数个日夜的心血才造出来的青鸾贰型！",
            ["ContentJP"] = "――あれ！？青鳳が……ない！？やだ、誰かに盗まれた！？あれは、私が何日も何夜も徹して作った、心血注いだ機体なのに！！",
            ["DialogueId"] = 12060335,
            ["GUID"] = "1E3118B6",
            ["NextDialogue"] = 12060336,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3118B6",
            },
        [12060336] = {
            ["Content"] = "触手往那个方向去了，我们快追！",
            ["ContentJP"] = "あっちに動いたよ！急いで追おう！",
            ["DialogueId"] = 12060336,
            ["GUID"] = "1E3118E0",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E3118E0",
            },
        [12060337] = {
            ["Content"] = "地上有粘液，小贼一定来过这里！",
            ["ContentJP"] = "ここ……地面にぬるっとした跡がある！あのコソ泥、ここを通ったのは間違いないわ！",
            ["DialogueId"] = 12060337,
            ["GUID"] = "1E31190A",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31190A",
            },
        [12060338] = {
            ["Content"] = "小仆从，好像不是这边……",
            ["ContentJP"] = "あれ、下僕、こっちは違うかも～？",
            ["DialogueId"] = 12060338,
            ["GUID"] = "1E311934",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E311934",
            },
        [12060339] = {
            ["Content"] = "小贼逃进巷口了。{nickname}，小白，我们兵分两路！",
            ["ContentJP"] = "ここだ！あの泥棒、きっとこの路地に逃げ込んだのね。{nickname}、スノウ、ここで別れて挟み撃ちよ！",
            ["DialogueId"] = 12060339,
            ["GUID"] = "1E31195E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120603/1E31195E",
            },
        [12060401] = {
            ["Content"] = "嘻嘻，你们来啦！那位大盗刚刚翻墙跑走了，你们赶紧追上去，我断后！",
            ["ContentJP"] = "キキキ、来てくれたのね♪泥棒さんなら、さっき塀を越えて逃げていったわよ？さあ、急いで追って！後ろは私に任せてさ！",
            ["DialogueId"] = 12060401,
            ["GUID"] = "1E31238A",
            ["NextDialogue"] = 12060402,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E31238A",
            },
        }
  end },
  { MinKey = 12060402, MaxKey = 12061110, Loader = function()
      return {
        [12060402] = {
            ["Content"] = "苏乙，你说话怎么怪怪的？",
            ["ContentJP"] = "……スーイー？なんか、声の感じが変じゃない？",
            ["DialogueId"] = 12060402,
            ["GUID"] = "1E3123B4",
            ["NextDialogue"] = 12060403,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3123B4",
            },
        [12060403] = {
            ["Content"] = "怪吗？大概是刚刚跑的太急，咬到舌头了。",
            ["ContentJP"] = "え、そ、そう？きっとさっき走ってて舌を噛んじゃったんですの～。 ",
            ["DialogueId"] = 12060403,
            ["GUID"] = "1E3123DE",
            ["NextDialogue"] = 12060404,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3123DE",
            },
        [12060404] = {
            ["Content"] = "不要在意这种细节啦，再耽误时间，那个家伙就要逃掉了！",
            ["ContentJP"] = "細かいことは気にしないで！逃げられちゃうよ、急いで急いで！",
            ["DialogueId"] = 12060404,
            ["GUID"] = "1E312408",
            ["NextDialogue"] = 12060405,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E312408",
            },
        [12060405] = {
            ["Content"] = "……苏乙，你还记得我们在找的是什么吗？",
            ["ContentJP"] = "……じゃあ、聞くけど。{性别:僕|私}たち、何を探してたんだっけ？",
            ["DialogueId"] = 12060405,
            ["GUID"] = "1E312432",
            ["NextDialogue"] = 12060406,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E312432",
            },
        [12060406] = {
            ["Content"] = "当然记得啊，不就是一个怪模怪样的机关鸟吗？",
            ["ContentJP"] = "えっ、そりゃもちろん……妙ちくりんなからくり鳥に決まってんだろ？",
            ["DialogueId"] = 12060406,
            ["GUID"] = "1E31245C",
            ["NextDialogue"] = 12060407,
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E31245C",
            },
        [12060407] = {
            ["Content"] = "什么机关鸟，那可是做了最新改装的“矩子巡枢贰型·青鸾”！",
            ["ContentJP"] = "妙ちくりーん！？なによその言い方っ！あれは、「<Default note=\"text:せいほう\">青鳳</>二型」っていう改良型のからくり鳥なの！",
            ["DialogueId"] = 12060407,
            ["GUID"] = "1E312486",
            ["NextDialogue"] = 12060408,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E312486",
            },
        [12060408] = {
            ["Content"] = "不仅偷走我的东西，还装成本姑娘的样子说出这么没文化的话，简直不可饶恕！",
            ["ContentJP"] = "それを盗んだ上に、私のマネまでして――センスも教養もゼロ！絶対に許さないからっ！！",
            ["DialogueId"] = 12060408,
            ["GUID"] = "1E3124B0",
            ["NextDialogue"] = 12060409,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3124B0",
            },
        [12060409] = {
            ["Content"] = "啧……真是难缠。",
            ["ContentJP"] = "ちぇっ……バレちゃったか。やりにくいヤツだな……！",
            ["DialogueId"] = 12060409,
            ["GUID"] = "1E3124DA",
            ["SpeakNpcId"] = 250029,
            ["VoiceName"] = "voice/$Locale$/story/1206/120604/1E3124DA",
            },
        [12060501] = {
            ["Content"] = "束手就擒吧，小贼！",
            ["ContentJP"] = "観念しなさい、悪党め！",
            ["DialogueId"] = 12060501,
            ["GUID"] = "1E3133F2",
            ["NextDialogue"] = 12060502,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3133F2",
            },
        [12060502] = {
            ["Content"] = "嘻嘻嘻……什么小贼、小贼的，我可是大名鼎鼎的恶魔大盗塔比瑟，别搞错了！",
            ["ContentJP"] = "キキキキ、コソ泥扱いすんなよ？ オレ様は「悪魔の大泥棒・タビテ」！ そこらのザコとは格が違ぇの！",
            ["DialogueId"] = 12060502,
            ["GUID"] = "1E31341C",
            ["NextDialogue"] = 12060503,
            ["RelatedWikiId"] = {
                [1] = 201029,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31341C",
            },
        [12060503] = {
            ["Content"] = "恶魔大盗？吹得这么厉害，结果还不是我们小仆从的手下败将。要我说，含金量比不上光之魔王大人的一根毫毛！",
            ["ContentJP"] = "ふ～ん、肩書きは立派だけど、結局我が下僕に捕まってるじゃん？魔王様の名に比べたら、まるで霞みたいなもんだねっ！",
            ["DialogueId"] = 12060503,
            ["GUID"] = "1E313446",
            ["NextDialogue"] = 12060504,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313446",
            },
        [12060504] = {
            ["Content"] = "呜呜……你们两个大人一起欺负我这个柔弱可怜又无助的小女孩，这不公平！",
            ["ContentJP"] = "ええん……大人ふたりがかりで、こんなか弱い女の子をいじめるなんて、ひど～い！ずる～い！（ウソ泣き）",
            ["DialogueId"] = 12060504,
            ["GUID"] = "1E313470",
            ["NextDialogue"] = 12060505,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313470",
            },
        [12060505] = {
            ["Content"] = "要不我们单挑再试试？",
            ["ContentJP"] = "……ねえねえ、そこの君？もう一回、ふたりきりで勝負しない？（ウソ泣き）",
            ["DialogueId"] = 12060505,
            ["GUID"] = "1E31349A",
            ["NextOptions"] = {
                [1] = 12060506,
                [2] = 12060507,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31349A",
            },
        [12060506] = {
            ["Content"] = "这招对我没用。",
            ["ContentJP"] = "そんな手は通じない。",
            ["DialogueId"] = 12060506,
            ["GUID"] = "1E3134C4",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12060508,
            },
        [12060507] = {
            ["Content"] = "嘤嘤嘤，我也是小孩子……",
            ["ContentJP"] = "えーん、わたしも子どもです～……（混沌+）",
            ["DialogueId"] = 12060507,
            ["GUID"] = "1E3134EE",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12060508,
            },
        [12060508] = {
            ["Content"] = "别想着蒙混过关。我的青鸾贰型呢？赶紧交出来。要是哪里的元件折了断了，十个你都赔不起！",
            ["ContentJP"] = "とぼけたって無駄よ。私の「<Default note=\"text:せいほう\">青鳳</>二型」、今すぐ返して！もし部品のひとつでも壊れてたら……十倍返しじゃすまないからねっ！",
            ["DialogueId"] = 12060508,
            ["GUID"] = "1E313518",
            ["NextDialogue"] = 12060509,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313518",
            },
        [12060509] = {
            ["Content"] = "嘻嘻……藏在哪里了呢？不如来猜一猜～猜中了有惊喜哟。",
            ["ContentJP"] = "キキキ、どこに隠したと思う～？ちゃんと当てられたら返してあ・げ・る♥ご褒美付きでな！",
            ["DialogueId"] = 12060509,
            ["GUID"] = "1E313542",
            ["NextDialogue"] = 12060510,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313542",
            },
        [12060510] = {
            ["Content"] = "先给你一个小小提示，恶魔大盗藏东西的伪装天衣无缝，你就算在原地跳脚，把这里翻个底朝天也找不出来哟～",
            ["ContentJP"] = "ヒントをやる。オレの隠し技、誰にも見破れねぇんだ。お前らがその辺ひっくり返したって、見つからないよ～ん？",
            ["DialogueId"] = 12060510,
            ["GUID"] = "1E31356C",
            ["NextDialogue"] = 12060511,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31356C",
            },
        [12060511] = {
            ["Content"] = "……我说，我怎么感觉你好像有点针对我的意思？",
            ["ContentJP"] = "……あんたさ、ちょっと意地悪すぎない？私たち別に、あんたに恨みがあるわけじゃないのに……",
            ["DialogueId"] = 12060511,
            ["GUID"] = "1E313596",
            ["NextDialogue"] = 12060512,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313596",
            },
        [12060512] = {
            ["Content"] = "我们明明素不相识，那牵机鸢你拿着也不好销赃。你若是实在缺钱，我向你赎回来就是了。",
            ["ContentJP"] = "そもそも、あのからくり<Default note=\"text:とび\">鳶は売り物にならないでしょ？いらないなら返してよ。もしお金が目的なら……ちゃんと買い戻すから。",
            ["DialogueId"] = 12060512,
            ["GUID"] = "1E3135C0",
            ["NextDialogue"] = 12060513,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3135C0",
            },
        [12060513] = {
            ["Content"] = "但青鸾贰型是我的心血，对我来说非常重要，请你尽快还给我。",
            ["ContentJP"] = "……あれは、私の「証」なの。だから――お願い、返して。",
            ["DialogueId"] = 12060513,
            ["GUID"] = "1E3135EA",
            ["NextDialogue"] = 12060514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3135EA",
            },
        [12060514] = {
            ["Content"] = "嘁……你可别误会一点。恶魔大盗只偷坏人的东西，从来不欺负好人。",
            ["ContentJP"] = "チッ…………ひとつだけ勘違いすんな。オレは、悪党からしか盗らねぇって決めてんだ。弱いヤツをいじめる趣味はねぇ。（真顔になり、声のトーンが変わる）",
            ["DialogueId"] = 12060514,
            ["GUID"] = "1E313614",
            ["NextDialogue"] = 12060515,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313614",
            },
        [12060515] = {
            ["Content"] = "在港口我就看见你鬼鬼祟祟地把那个机关鸟藏在包袱里带了进来。你就是那些人嘴里说的飘什么人是吧？",
            ["ContentJP"] = "港で見かけたんだ。お前、変な包みをコソコソ持ち込んでたろ？どうせ「あの噂の」流れ人だろ。",
            ["DialogueId"] = 12060515,
            ["GUID"] = "1E31363E",
            ["NextDialogue"] = 12060516,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31363E",
            },
        [12060516] = {
            ["Content"] = "虽然不知道你到底想做什么，但想装成正义的受害者还是免了吧。恶魔大盗是不会上你的当的。",
            ["ContentJP"] = "正直、何をたくらんでるのかは知らねぇけど――オレをナメて騙せると思ったら大間違いだ。",
            ["DialogueId"] = 12060516,
            ["GUID"] = "1E313668",
            ["NextDialogue"] = 12060517,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313668",
            },
        [12060517] = {
            ["Content"] = "小仆从，怎么办，这个恶魔大盗好像对苏乙有不少误会……",
            ["ContentJP"] = "ねえ……この悪魔の大泥棒さん、どうもスーイーに誤解してるみたいだよ……？",
            ["DialogueId"] = 12060517,
            ["GUID"] = "1E313692",
            ["NextDialogue"] = 12060518,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313692",
            },
        [12060518] = {
            ["Content"] = "让我来试试说服她吧。",
            ["ContentJP"] = "ひとまず話しをしてみよう。",
            ["DialogueId"] = 12060518,
            ["GUID"] = "1E3136BC",
            ["NextOptions"] = {
                [1] = 12060519,
                [2] = 12060526,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3136BC",
            },
        [12060519] = {
            ["Content"] = "晓之以理。",
            ["ContentJP"] = "道理を説く。（才知+）",
            ["DialogueId"] = 12060519,
            ["GUID"] = "1E3136E6",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12060520,
            },
        [12060520] = {
            ["Content"] = "听你的口音，你应该也不是华胥本地人吧？",
            ["ContentJP"] = "……君の口ぶりから察するに、華胥の生まれじゃないね？",
            ["DialogueId"] = 12060520,
            ["GUID"] = "1E313710",
            ["NextDialogue"] = 12060521,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313710",
            },
        [12060521] = {
            ["Content"] = "那你也许知道，在海伯利亚，有些卡戎为了避免被贵族老爷刁难，会把自己的角用帽子隐藏起来。你觉得这些卡戎是坏人，还是刁难他们的贵族老爷是坏人呢？",
            ["ContentJP"] = "だったら、ヒュペリアの話も聞いたことあるはず。あそこにはね、角を隠して暮らすカロンがいる。貴族に目をつけられないよう、帽子で必死に自分を覆ってさ――そんな彼らと、それを嘲る貴族たち。……君は、どっちが悪だと思う？",
            ["DialogueId"] = 12060521,
            ["GUID"] = "1E31373A",
            ["NextDialogue"] = 12060522,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31373A",
            },
        [12060522] = {
            ["Content"] = "那还用说？当然是贵族老爷的问题了！仗着自己是人上人，天天欺负别人。最看不惯他们那副做派了，呸呸呸。",
            ["ContentJP"] = "そんなの聞くまでもねぇだろ！悪いのは貴族だよ、あいつらはいつも威張って、人を見下して、好き勝手して……そういう連中のツラ見るだけでムカつくんだよ、マジで！",
            ["DialogueId"] = 12060522,
            ["GUID"] = "1E313764",
            ["NextDialogue"] = 12060523,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313764",
            },
        [12060523] = {
            ["Content"] = "有些传闻说沿海区域有义贼出没，偷走富人的不义之财，接济吃不起饭的穷人。那么他是十恶不赦的大坏蛋吗？",
            ["ContentJP"] = "じゃあ、もうひとつ。沿岸部には義賊がいるって話、聞いたことある？不正に蓄えた金を富豪から盗んで、貧しくて明日食べるものもない人に分け与える――そんな盗人は、果たして極悪人かな？",
            ["DialogueId"] = 12060523,
            ["GUID"] = "1E31378E",
            ["NextDialogue"] = 12060524,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31378E",
            },
        [12060524] = {
            ["Content"] = "义贼？嘻嘻嘻……那当然是响当当的大英雄！",
            ["ContentJP"] = "キキキキ、それは違うね。義賊ってのは――オレらのヒーローだぞ！",
            ["DialogueId"] = 12060524,
            ["GUID"] = "1E3137B8",
            ["NextDialogue"] = 12060525,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3137B8",
            },
        [12060525] = {
            ["Content"] = "还需要我继续说下去吗？你只是受到了一些言论的误导，未必是事情的原貌。飘零人一向主张锄强扶弱，不是你以为的坏人。",
            ["ContentJP"] = "……だったら、答えはもう出てるよね。誰かの言葉を鵜呑みにして、全部を悪と決めつけるのは、ちょっと早すぎたんじゃない？流れ者は、声高に正義を語るような集団じゃない。でも――弱者を助ける点では、君の信じる義賊と、きっと同じところに立ってるはずだよ。",
            ["DialogueId"] = 12060525,
            ["GUID"] = "1E3137E2",
            ["NextDialogue"] = 12060532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3137E2",
            },
        [12060526] = {
            ["Content"] = "动之以情。",
            ["ContentJP"] = "同情を煽る。（共感+）",
            ["DialogueId"] = 12060526,
            ["GUID"] = "1E31380C",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12060527,
            },
        [12060527] = {
            ["Content"] = "塔比瑟，你刚刚说自己只偷坏人的东西，从来不欺负好人。看来你也是个伸张正义的好侠盗，在这一点上，大家的心都是一样的。",
            ["ContentJP"] = "タビテ、君はさっき言ってたよね――悪い奴からしか盗まない、善人は傷つけないって。だったら君も、正義を信じてるひとりだ。その気持ち、きっと{性别:僕|私}たちとも通じてるよ。",
            ["DialogueId"] = 12060527,
            ["GUID"] = "1E313836",
            ["NextDialogue"] = 12060528,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313836",
            },
        [12060528] = {
            ["Content"] = "怎么？想用糖衣炮弹腐化本大盗？我吃不吃这一套呢……嘻嘻，你不如再多说点试试？",
            ["ContentJP"] = "なになに？甘い言葉でこの大泥棒を言いくるめるつもり？オレ様がその手に乗るとでも……ふふ、試しにもうちょい口説いてみろよ？",
            ["DialogueId"] = 12060528,
            ["GUID"] = "1E313860",
            ["NextDialogue"] = 12060529,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313860",
            },
        [12060529] = {
            ["Content"] = "飘零人也是一样的，他们向来都是锄强扶弱，没有做过伤天害理的事情。我可以为他们担保。",
            ["ContentJP"] = "流れ者も同じだよ。力に屈せず、弱きを助ける――誰かを傷つけるような真似なんて、してこなかった。{性别:僕|私}が保証するよ。",
            ["DialogueId"] = 12060529,
            ["GUID"] = "1E31388A",
            ["NextDialogue"] = 12060530,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E31388A",
            },
        [12060530] = {
            ["Content"] = "正义的伙伴往往会受到很多误解，相信你也明白这一点。但你依然坚持着自己的准则，说明你是个了不起的大盗。",
            ["ContentJP"] = "「正義」は、誤解されやすい。きっと君も、それはよくわかってるはず。それでも、自分のやり方を貫いてきた――君は、誇っていい大盗賊だよ。",
            ["DialogueId"] = 12060530,
            ["GUID"] = "1E3138B4",
            ["NextDialogue"] = 12060531,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3138B4",
            },
        [12060531] = {
            ["Content"] = "所以这位了不起的大盗，你愿意再多相信一点我们吗？",
            ["ContentJP"] = "だからこそお願いしたい。そんな君に……少しでも信じてもらえないかな？",
            ["DialogueId"] = 12060531,
            ["GUID"] = "1E3138DE",
            ["NextDialogue"] = 12060532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E3138DE",
            },
        [12060532] = {
            ["Content"] = "够了够了——再念下去，我的耳膜都要被你念穿啦！不就是一个机关鸟吗？这玩意儿我才不稀罕呢，还给你们就是了。",
            ["ContentJP"] = "はいはい、もういいって！ これ以上しゃべられたら耳にタコできるっての！ まったく、こんなガラクタ鳥のために熱弁ふるうなんて……ほんっと物好きだなお前ら。",
            ["DialogueId"] = 12060532,
            ["GUID"] = "1E313908",
            ["NextDialogue"] = 12060533,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313908",
            },
        [12060533] = {
            ["Content"] = "喏，就藏在那边的箱子里。你们自己拿吧。",
            ["ContentJP"] = "ほら、その箱の中だよ。勝手に持ってきな。",
            ["DialogueId"] = 12060533,
            ["GUID"] = "1E313932",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313932",
            },
        [12060534] = {
            ["Content"] = "机关鸟就藏在那边的箱子里。怎么？需不需要恶魔大盗给你带路？",
            ["DialogueId"] = 12060534,
            ["GUID"] = "1E313933",
            ["NextDialogue"] = 12060535,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313933",
            },
        [12060535] = {
            ["Content"] = "这次我盯住你了，不要有什么小心思，也别想着轻举妄动！",
            ["DialogueId"] = 12060535,
            ["GUID"] = "1E313934",
            ["NextDialogue"] = 12060536,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313934",
            },
        [12060536] = {
            ["Content"] = "嘻嘻，需要恶魔大盗表演一下从你眼皮底子下消失的魔术吗~这可是我的拿手绝活~",
            ["DialogueId"] = 12060536,
            ["GUID"] = "1E313935",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120605/1E313935",
            },
        [12060601] = {
            ["Camera"] = "721.375,-25.105469,239.573486,0.000103,-12.201231,176.825256,28.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "外观没有损坏，功能也都完好……只是元件里落了不少尘土，之后细细清一下灰就好了。",
            ["ContentJP"] = "見た感じは無事、機能もちゃんと動いてる……ただ、細かい部品にちょっとホコリが溜まってるみたい。あとで掃除すれば大丈夫ね。",
            ["DialogueId"] = 12060601,
            ["GUID"] = "1E31445A",
            ["NextDialogue"] = 12060602,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["Scripts"] = "SEQ{\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}},\
LookAt{LookAtDescription{\"200002:n(250003)\"}}\
},\
PlayAnimation{_delay{1.5},ActorId{250003},AnimationId{\"ConfidentR_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31445A",
            },
        [12060602] = {
            ["Content"] = "呼，还好我的青鸾贰型没有出事，真是不幸中的万幸。",
            ["ContentJP"] = "ふぅ……<Default note=\"text:せいほう\">青鳳</>二型に異常がなくてほんとによかった……まさに不幸中の幸いってやつだね。",
            ["DialogueId"] = 12060602,
            ["GUID"] = "1E314484",
            ["NextDialogue"] = 12060603,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.0},ActorId{250003},AnimationId{\"ConfidentRToSigh_Start\"},Duration{1}},\
PlayAnimation{_delay{2.0},ActorId{250003},AnimationId{\"ConfidentRToSigh_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314484",
            },
        [12060603] = {
            ["Content"] = "唉，虽然失物是找回来了，但是离奉香群英试报名截止只有一个小时了。到哪里再找到两个队友呢……",
            ["ContentJP"] = "……戻ってきたのはいいけど、英雄大会のエントリー締切まで、あと1時間。あと2人、どうやって見つけよう……",
            ["DialogueId"] = 12060603,
            ["GUID"] = "1E3144AE",
            ["NextDialogue"] = 12060604,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.0},ActorId{250003},AnimationId{\"ConfidentR_End\"},Duration{1}},\
PlayAnimation{_delay{1.0},ActorId{250003},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3144AE",
            },
        [12060604] = {
            ["Content"] = "咳咳……",
            ["ContentJP"] = "コホン……",
            ["DialogueId"] = 12060604,
            ["GUID"] = "1E3144D8",
            ["NextDialogue"] = 12060605,
            ["Scripts"] = "PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3144D8",
            },
        [12060605] = {
            ["Content"] = "如果你愿意承认章鱼触手是世界上最有品味，最优雅，最完美的造型，那本大盗也不是不能帮你一把。",
            ["ContentJP"] = "……もし、タコの触手がこの世で一番センスがあって、上品で、完璧なフォルムだって認めてくれんなら――この大泥棒、ひと肌脱いでもいいけど？",
            ["DialogueId"] = 12060605,
            ["GUID"] = "1E314502",
            ["NextDialogue"] = 12060606,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"250006:n(250003)\"}},\
LookAt{LookAtDescription{\"200002:n(250006)\"}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314502",
            },
        [12060606] = {
            ["Content"] = "好啊！刚刚你果然躲在一旁偷听我们说话！",
            ["ContentJP"] = "あー！さては近くで盗み聞きしてたな！",
            ["DialogueId"] = 12060606,
            ["GUID"] = "1E31452C",
            ["NextDialogue"] = 12060607,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Angry01_Start\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(200002)\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31452C",
            },
        [12060607] = {
            ["Content"] = "嘻嘻……合格的大盗当然要回到犯罪现场，关注现场的每一丝风吹草动啦～",
            ["ContentJP"] = "キキキ。優秀な盗賊ってのはな、必ず現場に戻るもんなんだよ♪一挙一動、風の音すら聞き逃さないのがプロの仕事よ～",
            ["DialogueId"] = 12060607,
            ["GUID"] = "1E314556",
            ["NextDialogue"] = 12060608,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_End\"},Duration{1}},\
PlayAnimation{_delay{0.8},ActorId{250006},AnimationId{\"Confident_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314556",
            },
        [12060608] = {
            ["Content"] = "你态度怎么突然一百八十度大转变了？该不会又想打什么鬼主意吧。",
            ["ContentJP"] = "急に態度変わりすぎじゃない？……何か裏があるとか？",
            ["DialogueId"] = 12060608,
            ["GUID"] = "1E314580",
            ["NextDialogue"] = 12060609,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"250003:n(250006)\"}},\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Think_End\"},Duration{1}},\
PlayAnimation{_delay{2.5},ActorId{250003},AnimationId{\"Angry01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314580",
            },
        [12060609] = {
            ["Content"] = "喂喂，我看你很苦恼的样子，难得提出要当你的队友。你怎么把别人的好意当成驴肝肺！",
            ["ContentJP"] = "ちょっと！オレ様なりに気を利かせて仲間になってやろうってのに、なんでそれを「腹黒」って取るわけ！？人の善意を台無しにしないでよねっ！",
            ["DialogueId"] = 12060609,
            ["GUID"] = "1E3145AA",
            ["NextDialogue"] = 12060610,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.0},ActorId{250003},AnimationId{\"Angry01_End\"},Duration{1}},\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Confident_End\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(250003)\"}},\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}\
},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Angry01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3145AA",
            },
        [12060610] = {
            ["Content"] = "莫非……你愧疚感上涌，想要弥补自己的过错了？",
            ["ContentJP"] = "もしかして……ちょっとは悪いことしたって自覚してて、反省してるとか？",
            ["DialogueId"] = 12060610,
            ["GUID"] = "1E3145D4",
            ["NextDialogue"] = 12060611,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{1.2},ActorId{250006},AnimationId{\"Talk03_End\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}}\
},\
PlayAnimation{_delay{0.2},ActorId{100001},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3145D4",
            },
        [12060611] = {
            ["Content"] = "才不是呢，恶魔大盗行事随心所欲，哪里有什么过错！只是一直听你们把这个什么群英试吹得这么有意思，这种出风头的机会，我才不会放过！",
            ["ContentJP"] = "はぁ？んなわけねぇだろ！悪魔の大泥棒は気まぐれで動くんだよ。別に謝る気なんてこれっぽっちもねぇし！ただ……そのなんちゃら大会？なんか面白そうだったから。目立つチャンスは逃さねぇ主義なんだオレは。",
            ["DialogueId"] = 12060611,
            ["GUID"] = "1E3145FE",
            ["NextDialogue"] = 12060612,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Angry01_Start\"},Duration{1}},\
PlayAnimation{_delay{2.2},ActorId{250006},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3145FE",
            },
        [12060612] = {
            ["Content"] = "嗯……仔细想想，你能从本姑娘眼皮底下把东西偷走，说明胆识不错。和我们过了两招，身手也算过关。说不定你意外地适合群英试呢。",
            ["ContentJP"] = "ふぅん……でも、私の目の前であれを盗んだってのは、それなりの度胸だし。さっきの動きもなかなかだったし、意外と向いてるかもね。",
            ["DialogueId"] = 12060612,
            ["GUID"] = "1E314628",
            ["NextDialogue"] = 12060613,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Talk03_Start\"},Duration{1}},\
LookAt{LookAtDescription{\"250006:n(250003)\"}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314628",
            },
        [12060613] = {
            ["Content"] = "好吧，那我就勉强认可你了。",
            ["ContentJP"] = "しょうがない……そこまで言うなら、仲間に「してあげる」わ。",
            ["DialogueId"] = 12060613,
            ["GUID"] = "1E314652",
            ["NextDialogue"] = 12060614,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{_delay{0.8},ActorId{250003},AnimationId{\"Talk03_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314652",
            },
        [12060614] = {
            ["Content"] = "提前先说好，最后的奖品得三七分哦——你三我七。",
            ["ContentJP"] = "じゃあ、先に決めとこ。勝ったら賞品は……オレ7割、お前3割な♪",
            ["DialogueId"] = 12060614,
            ["GUID"] = "1E31467C",
            ["NextDialogue"] = 12060615,
            ["Scripts"] = "PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31467C",
            },
        [12060615] = {
            ["Camera"] = "380.75,-18.171875,137.20459,0.000082,-5.200806,170.601486,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样一来就凑齐两个人了，只差最后的一名队友……",
            ["ContentJP"] = "……まあ、これで2人は揃ったわけだし――あとは、最後のひとり……",
            ["DialogueId"] = 12060615,
            ["GUID"] = "1E3146A6",
            ["NextDialogue"] = 12060616,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{250006},AnimationId{\"Confident_End\"},Duration{1}},\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}},\
PlayAnimation{_delay{1.2},ActorId{250003},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayAnimation{_delay{1.2},ActorId{250006},AnimationId{\"Talk03_Start\"},Duration{1}}\
}\
}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3146A6",
            },
        [12060616] = {
            ["Content"] = "哇啊啊，小仆从，她们俩怎么齐齐地盯着我们看。难不成是想要招揽——",
            ["ContentJP"] = "えっ、ちょっと！？いま二人してこっち見なかった！？ま、まさか――誘おうとしてる……！？",
            ["DialogueId"] = 12060616,
            ["GUID"] = "1E3146D0",
            ["NextOptions"] = {
                [1] = 12060617,
                [2] = 12060620,
                },
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"200002:n(100001)\"}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Shock02_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3146D0",
            },
        [12060617] = {
            ["Content"] = "白。",
            ["ContentJP"] = "スノウ。",
            ["DialogueId"] = 12060617,
            ["GUID"] = "1E3146FA",
            ["NextDialogue"] = 12060618,
            },
        [12060618] = {
            ["Content"] = "咳咳，光之魔王大人这么有实力的重量级选手。要是上场后一下子就结束了比赛，对其他选手不太公平吧……？",
            ["ContentJP"] = "えっと、その……光の魔王ともあろう者が本気を出したら、試合なんて一瞬で終わっちゃうでしょ？",
            ["DialogueId"] = 12060618,
            ["GUID"] = "1E314724",
            ["NextDialogue"] = 12060619,
            ["Scripts"] = "PARA{\
PARA{\
LookAt{LookAtDescription{\"250003:n(200002)\"}},\
LookAt{LookAtDescription{\"250006:n(200002)\"}}\
},\
SEQ{\
LookAt{LookAtDescription{\"200002:n(250003)\"}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Shock02_End\"},Duration{1}},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Disagree\"},Duration{1}}\
}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314724",
            },
        [12060619] = {
            ["Content"] = "我呢，其实是非常心系正义的一个好魔王，不想随随便便破坏比赛规则。还是把这个宝贵的机会让给别人吧。",
            ["ContentJP"] = "他の参加者のことも考えなきゃ。私はね、正義を大事にするタイプの魔王だから……今回は身を引いて、他の人にチャンスを譲るよ！",
            ["DialogueId"] = 12060619,
            ["GUID"] = "1E31474E",
            ["NextOptions"] = {
                [1] = 12060620,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}},\
LookAt{_delay{3.2},LookAtDescription{\"200002:n(100001)\"}},\
PlayAnimation{_delay{2.2},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31474E",
            },
        [12060620] = {
            ["Content"] = "{nickname}。",
            ["ContentJP"] = "{nickname}。",
            ["DialogueId"] = 12060620,
            ["GUID"] = "1E314778",
            ["NextDialogue"] = 12060621,
            },
        [12060621] = {
            ["Content"] = "对哦！有了小仆从的加入，她们岂不是像老虎长出了翅膀一样，所到之处完全没有敌手，轻轻松松拿下比赛！",
            ["ContentJP"] = "そっか！我が下僕が入れば、もう敵なしじゃん！鬼に翼、いや、まさに最強チームの誕生ってわけ！",
            ["DialogueId"] = 12060621,
            ["GUID"] = "1E3147A2",
            ["NextDialogue"] = 12060622,
            ["Scripts"] = "PARA{\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}}\
},\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}},\
LookAt{_delay{1.2},LookAtDescription{\"200002:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3147A2",
            },
        [12060622] = {
            ["Content"] = "那叫如虎添翼啦——不过没想到你还多少学了点成语，看来你在华胥的日子也算有所收获了！",
            ["ContentJP"] = "「虎に翼」ね。そんな熟語、よく知ってるね。華胥でちょっとは収穫があったようだね。",
            ["DialogueId"] = 12060622,
            ["GUID"] = "1E3147CC",
            ["NextDialogue"] = 12060623,
            ["Scripts"] = "PARA{\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Talk03ToTalkL_Start\"},Duration{1}},\
PlayAnimation{_delay{3.2},ActorId{250003},AnimationId{\"Talk03ToTalkL_End\"},Duration{1}}\
},\
LookAt{_delay{1.2},LookAtDescription{\"250003:n(200002)\"}},\
LookAt{_delay{1.2},LookAtDescription{\"200002:n(250003)\"}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3147CC",
            },
        [12060623] = {
            ["Content"] = "哼哼，那是当然！",
            ["ContentJP"] = "ふふん、当然でしょ！",
            ["DialogueId"] = 12060623,
            ["GUID"] = "1E3147F6",
            ["NextDialogue"] = 12060624,
            ["Scripts"] = "PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"AgreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3147F6",
            },
        [12060624] = {
            ["Content"] = "那现在只剩下一个难题需要解决了……我们三天后就要坐飞艇回冰湖城了，时间上会不会来不及呀？",
            ["ContentJP"] = "でも、ひとつだけ問題が……私たち、三日後にはアイスレイク城に戻る飛行艇に乗る予定だけど、間に合うのかな？",
            ["DialogueId"] = 12060624,
            ["GUID"] = "1E314820",
            ["NextDialogue"] = 12060625,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314820",
            },
        [12060625] = {
            ["Content"] = "完全没问题！奉香群英试为时两天，到明天日落之前就能决出最后的胜利队伍，绝对绝对不会耽误你们的回程。",
            ["ContentJP"] = "大丈夫！英雄大会は二日間で終わるし、明日の夕方には優勝チームが決まるから、帰りの予定に影響は出ないわ！",
            ["DialogueId"] = 12060625,
            ["GUID"] = "1E31484A",
            ["NextDialogue"] = 12060626,
            ["Scripts"] = "SEQ{\
PARA{\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Talk03_End\"},Duration{1}}\
},\
PlayAnimation{_delay{1.2},ActorId{250003},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31484A",
            },
        [12060626] = {
            ["Content"] = "那我好像没有拒绝你的理由。待在华胥的最后几天，陪朋友一起玩玩也挺不错的。",
            ["ContentJP"] = "そっか……じゃあ、断る理由はなさそうだね。<Default note=\"text:カショ\">華胥</>での最後の数日、友だちと過ごすなら……いい思い出になるかも。",
            ["DialogueId"] = 12060626,
            ["GUID"] = "1E314874",
            ["NextDialogue"] = 12060627,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314874",
            },
        [12060627] = {
            ["Content"] = "好耶，友谊第一比赛第二！不对不对——比赛也是很重要的，小仆从你可一定得给我拿个冠军回来！",
            ["ContentJP"] = "やった～！友情第一、勝負は……えっと、いやいや、勝負も大事だよね！せっかくだから優勝目指しちゃおう！",
            ["DialogueId"] = 12060627,
            ["GUID"] = "1E31489E",
            ["NextDialogue"] = 12060628,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},\
SEQ{\
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{\"SpecialHappy_Start\"},Duration{1}},\
PlayAnimation{_delay{4.2},ActorId{200002},AnimationId{\"SpecialHappy_End\"},Duration{1}},\
LookAt{_delay{1.2},LookAtDescription{\"200002:n(100001)\"}}\
}\
}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31489E",
            },
        [12060628] = {
            ["Content"] = "对啦。你那个机关鸟如果再暴露了会很麻烦的吧？既然这样，恶魔大盗来帮你掩饰一下~",
            ["ContentJP"] = "そうそう、あの鳥……また人目にさらされたらやっかいだろ？ここは悪魔の大泥棒が、いい感じにカモフラージュしてあげよう！",
            ["DialogueId"] = 12060628,
            ["GUID"] = "1E3148C8",
            ["NextDialogue"] = 12060629,
            ["Scripts"] = "LookAt{_delay{1.2},LookAtDescription{\"250006:n(250003)\"}}",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3148C8",
            },
        [12060629] = {
            ["Content"] = "……你这一手倒是方便。",
            ["ContentJP"] = "……うわっ、何それ、便利……（びっくり）",
            ["DialogueId"] = 12060629,
            ["GUID"] = "1E3148F2",
            ["NextDialogue"] = 12060630,
            ["Scripts"] = "PARA{\
LookAt{_delay{1.2},LookAtDescription{\"250003:n(250006)\"}},\
PlayAnimation{_delay{0.2},ActorId{250003},AnimationId{\"Agree\"},Duration{1}},\
PlayAnimation{_delay{0.5},ActorId{250003},AnimationId{\"Think_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3148F2",
            },
        [12060630] = {
            ["Content"] = "时候不早了，我们赶紧去报名处吧。",
            ["ContentJP"] = "さてと、あんまりのんびりしてる暇はないわね。急いで受付に行きましょ！",
            ["DialogueId"] = 12060630,
            ["GUID"] = "1E31491C",
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.5},ActorId{250003},AnimationId{\"Think_End\"},Duration{1}},\
PARA{\
LookAt{LookAtDescription{\"250003:n(100001)\"}},\
LookAt{LookAtDescription{\"250006:n(100001)\"}}\
}\
}",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31491C",
            },
        [12060631] = {
            ["Content"] = "听好了，我们先约法三章。组队期间，你不许随便偷东西，不许到处乱跑，不许不听指挥。明白了吗？",
            ["ContentJP"] = "よーく聞いて！試合が終わるまでは――勝手に盗みは禁止、勝手に行動も禁止、指示無視も絶対禁止！いいわね！？",
            ["DialogueId"] = 12060631,
            ["GUID"] = "1E314946",
            ["NextDialogue"] = 12060632,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314946",
            },
        [12060632] = {
            ["Content"] = "好好好，明白了，苏乙妈妈——",
            ["ContentJP"] = "はいはい～、わかってますって、お母さま～♪——（ふてぶてしく）",
            ["DialogueId"] = 12060632,
            ["GUID"] = "1E314970",
            ["NextDialogue"] = 12060633,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E314970",
            },
        [12060633] = {
            ["Content"] = "喂，好敷衍的语气！你真的听进去了吗？",
            ["ContentJP"] = "ちょっと！？その言い方、絶対わかってないでしょ！",
            ["DialogueId"] = 12060633,
            ["GUID"] = "1E31499A",
            ["NextDialogue"] = 12060634,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E31499A",
            },
        [12060634] = {
            ["Content"] = "嘻嘻，你猜——？",
            ["ContentJP"] = "キキキ、さあ、どうかな～？",
            ["DialogueId"] = 12060634,
            ["GUID"] = "1E3149C4",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120606/1E3149C4",
            },
        [12060701] = {
            ["Content"] = "你好！我们是来报名参加群英试的！呼……应该赶上了吧？",
            ["ContentJP"] = "すみません！英雄大会に参加したくて来ました！ふぅ……間に合ってる、よね？",
            ["DialogueId"] = 12060701,
            ["GUID"] = "1E3154C2",
            ["NextDialogue"] = 12060702,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3154C2",
            },
        [12060702] = {
            ["Content"] = "没问题，离报名结束还有半个时辰。请在这张报名表上签署几位的姓名和小队名称。",
            ["ContentJP"] = "はい、大丈夫です。締切まであと1時間ほどありますから。こちらの申請書に、代表者のお名前とチーム名をご記入ください。",
            ["DialogueId"] = 12060702,
            ["GUID"] = "1E3154EC",
            ["NextDialogue"] = 12060703,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3154EC",
            },
        [12060703] = {
            ["Content"] = "小队名称？糟糕糟糕，差点忘了！我们得现在赶紧想一个。",
            ["ContentJP"] = "チーム名！？しまった……すっかり忘れてた！今すぐ決めなきゃ！",
            ["DialogueId"] = 12060703,
            ["GUID"] = "1E315516",
            ["NextDialogue"] = 12060704,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315516",
            },
        [12060704] = {
            ["Content"] = "“腕足很大”小队，这个怎么样，是不是很拉风？",
            ["ContentJP"] = "「ドデカ腕脚」チームとかどう？インパクトあるだろ♪",
            ["DialogueId"] = 12060704,
            ["GUID"] = "1E315540",
            ["NextDialogue"] = 12060705,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315540",
            },
        [12060705] = {
            ["Content"] = "你的品味还是一如既往的糟糕……要我说，不如“天工开物”小队吧。",
            ["ContentJP"] = "相変わらずセンスないわね……「天工ノ匠」チームなんてどう？",
            ["DialogueId"] = 12060705,
            ["GUID"] = "1E31556A",
            ["NextDialogue"] = 12060706,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31556A",
            },
        [12060706] = {
            ["Content"] = "什么嘛，老土！你起的名字明明也没有好到哪里去！",
            ["ContentJP"] = "だっさ！お前のも大差ないでしょ！",
            ["DialogueId"] = 12060706,
            ["GUID"] = "1E315594",
            ["NextDialogue"] = 12060707,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315594",
            },
        [12060707] = {
            ["Content"] = "……{nickname}，还是你来定吧。",
            ["ContentJP"] = "……{nickname}、決めてくれる？",
            ["DialogueId"] = 12060707,
            ["GUID"] = "1E3155BE",
            ["NextDialogue"] = 12060708,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3155BE",
            },
        [12060708] = {
            ["Content"] = "小仆从，你有没有觉得这一幕似曾相识……",
            ["ContentJP"] = "……この光景、なんだか既視感ない？（にやにや）",
            ["DialogueId"] = 12060708,
            ["GUID"] = "1E3155E8",
            ["NextDialogue"] = 12060709,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3155E8",
            },
        [12060709] = {
            ["Content"] = "也许人类的本质就是总是重复做相同的事……好吧，我瞧瞧。小队名字的话——",
            ["ContentJP"] = "もしかしたら人間の本質って同じことを繰り返すことなのかもね……じゃあ――チーム名は……（笑いながら）",
            ["DialogueId"] = 12060709,
            ["FinalDialogueId"] = 12060716,
            ["GUID"] = "1E315612",
            ["NextOptions"] = {
                [1] = 12060710,
                [2] = 12060713,
                [3] = 12060715,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315612",
            },
        [12060710] = {
            ["Content"] = "光之魔王和她的三个跟班。",
            ["ContentJP"] = "光の魔王と三人のしもべたち。",
            ["DialogueId"] = 12060710,
            ["GUID"] = "1E31563C",
            ["NextDialogue"] = 12060711,
            },
        [12060711] = {
            ["Content"] = "跟班？不吉利不吉利，堂堂恶魔大盗怎么能当别人的跟班呢！",
            ["ContentJP"] = "し、しもべだと！？ 縁起でもねぇ！この悪魔の大泥棒が、誰かのしもべになるわけねぇだろ！",
            ["DialogueId"] = 12060711,
            ["GUID"] = "1E315666",
            ["NextDialogue"] = 12060712,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315666",
            },
        [12060712] = {
            ["Content"] = "喂喂，华胥的皎皎们排着队想拜入本魔王麾下呢，你不做有的是皎皎做！",
            ["ContentJP"] = "ふふん、<Default note=\"text:カショ\">華胥</>中のルーナたちが、我が軍門に下ろうとしてるのに～？君が断るなら、他に志願者はいくらでもいるんだからね！",
            ["DialogueId"] = 12060712,
            ["GUID"] = "1E315690",
            ["NextDialogue"] = 12060709,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315690",
            },
        [12060713] = {
            ["Content"] = "夜航者小队华胥分队。",
            ["ContentJP"] = "「ノクトボイジャー」華胥チーム。",
            ["DialogueId"] = 12060713,
            ["GUID"] = "1E3156BA",
            ["NextDialogue"] = 12060714,
            },
        [12060714] = {
            ["Content"] = "咳咳……要不咱们再想想？",
            ["ContentJP"] = "え、ええと……それはちょっと……再考の余地あり、かな。",
            ["DialogueId"] = 12060714,
            ["GUID"] = "1E3156E4",
            ["NextDialogue"] = 12060709,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3156E4",
            },
        [12060715] = {
            ["Content"] = "狩月逐香队。",
            ["ContentJP"] = "香狩りチーム。",
            ["DialogueId"] = 12060715,
            ["GUID"] = "1E31570E",
            ["NextDialogue"] = 12060716,
            },
        [12060716] = {
            ["Content"] = "嗯，这个不错，就决定是它了！",
            ["ContentJP"] = "うん、それ、いい感じ。決まりね！",
            ["DialogueId"] = 12060716,
            ["GUID"] = "1E315738",
            ["NextDialogue"] = 12060717,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315738",
            },
        [12060717] = {
            ["Content"] = "久等了，这是我们的报名表。",
            ["ContentJP"] = "お待たせしました。これがチーム申請書です。",
            ["DialogueId"] = 12060717,
            ["GUID"] = "1E315762",
            ["NextDialogue"] = 12060718,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315762",
            },
        [12060718] = {
            ["Content"] = "让我确认一下，苏乙女士、塔比瑟女士，以及……{nickname}，等等，我没有看错吧？",
            ["ContentJP"] = "確認しますね……スーイーさん、タビテさん、そして――{nickname}さん。……あれ？まさか……！",
            ["DialogueId"] = 12060718,
            ["GUID"] = "1E31578C",
            ["NextDialogue"] = 12060719,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31578C",
            },
        [12060719] = {
            ["Content"] = "……您莫非就是此前在皓京乱象中，协助大风九章归位的那位少年英杰？",
            ["ContentJP"] = "以前、<Default note=\"text:こうけい\">皓京</>での騒乱で、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の復帰に関わったという……あの！？",
            ["DialogueId"] = 12060719,
            ["GUID"] = "1E3157B6",
            ["NextDialogue"] = 12060720,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3157B6",
            },
        [12060720] = {
            ["Content"] = "按照华胥人的说话方式应该是……“正是在下”？",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>風に言うなら……「いかにも、拙者でございます」かな？",
            ["DialogueId"] = 12060720,
            ["GUID"] = "1E3157E0",
            ["NextDialogue"] = 12060721,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3157E0",
            },
        [12060721] = {
            ["Content"] = "看不出来，你在这里竟然还是个大人物。",
            ["ContentJP"] = "へぇ～、こんなとこでも有名人だったとはな。",
            ["DialogueId"] = 12060721,
            ["GUID"] = "1E31580A",
            ["NextDialogue"] = 12060722,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31580A",
            },
        [12060722] = {
            ["Content"] = "呵呵，既然是亲历者，那倒是省去了我介绍前因后果的工夫。",
            ["ContentJP"] = "それなら話が早い。改制のきっかけとなった方なら、説明を省いてもよさそうですね。",
            ["DialogueId"] = 12060722,
            ["GUID"] = "1E315834",
            ["NextDialogue"] = 12060723,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315834",
            },
        [12060723] = {
            ["Content"] = "{nickname}{性别：先生|女士}，正因您参与推动的改制，如今人之力量成为重新被审视的课题。",
            ["ContentJP"] = "{nickname}{性别：様|様}の関与もあって、今では「人の力」が再び見直されるようになりました。",
            ["DialogueId"] = 12060723,
            ["GUID"] = "1E31585E",
            ["NextDialogue"] = 12060724,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31585E",
            },
        [12060724] = {
            ["Content"] = "故而这次的赛事鼓励人们拿起武器，与如今仍游荡在外，尚未被完全清除的混乱狴犴作战。",
            ["ContentJP"] = "今回の英雄大会もその流れに沿ったもので、混乱をもたらした<Default note=\"text:ビーアン\">狴犴</>たちと向き合う力を、民に試してもらう機会となっています。",
            ["DialogueId"] = 12060724,
            ["GUID"] = "1E315888",
            ["NextDialogue"] = 12060725,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315888",
            },
        [12060725] = {
            ["Content"] = "意思是……这次比赛就是比谁打的怪物多，是嘛？",
            ["ContentJP"] = "つまり……いっぱいモンスター倒せば勝ちってこと？",
            ["DialogueId"] = 12060725,
            ["GUID"] = "1E3158B2",
            ["NextDialogue"] = 12060726,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3158B2",
            },
        [12060726] = {
            ["Content"] = "并非如此。对于大部分未曾接触过武器的华胥人来说，直接比拼武艺还是有些一步登天了。",
            ["ContentJP"] = "それが、少し違うんです。<Default note=\"text:カショ\">華胥</>の多くの人々は、武器を手に取ることすら経験がありません。",
            ["DialogueId"] = 12060726,
            ["GUID"] = "1E3158DC",
            ["NextDialogue"] = 12060727,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3158DC",
            },
        [12060727] = {
            ["Content"] = "本次群英试的主题是“争锋”——简单来说您可以理解成“夺宝”。在指定的赛场中，布置了多处藏有宝物的器具。不同宝物对应着不同的文筹，清缴狴犴能够带来武筹。",
            ["ContentJP"] = "そこで今回は、「争奪」をテーマにした――いわば宝探しがメインのルールとなっています。決められたエリアに、複数の宝物が仕込まれていて、それを回収すると文得点という得点になります。さらに、現れる<Default note=\"text:ビーアン\">狴犴</>を討伐すれば武得点が得られます。このふたつを競うわけです。",
            ["DialogueId"] = 12060727,
            ["GUID"] = "1E315906",
            ["NextDialogue"] = 12060728,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315906",
            },
        [12060728] = {
            ["Content"] = "赛事总共有五轮。每轮次会统计各个参赛队伍的总筹数，达到足够名次的队伍能够晋级。",
            ["ContentJP"] = "全五ラウンドで争われ、各ラウンドでの合計得点が上位に入れば次に進めます。",
            ["DialogueId"] = 12060728,
            ["GUID"] = "1E315930",
            ["NextDialogue"] = 12060729,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315930",
            },
        [12060729] = {
            ["Content"] = "如何在抵御混乱狴犴的同时，搜集到足够多的宝物，就是本次夺魁的关键。",
            ["ContentJP"] = "<Default note=\"text:ビーアン\">狴犴</>の妨害をかいくぐって、いかに多くの宝を手に入れるかが勝負のカギですね。",
            ["DialogueId"] = 12060729,
            ["GUID"] = "1E31595A",
            ["NextDialogue"] = 12060730,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E31595A",
            },
        [12060730] = {
            ["Content"] = "怎么样，关于这次的赛制还有问题吗？",
            ["ContentJP"] = "ご不明な点はありますか？",
            ["DialogueId"] = 12060730,
            ["GUID"] = "1E315984",
            ["NextDialogue"] = 12060731,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315984",
            },
        [12060731] = {
            ["Content"] = "哇，本来只是好心帮人参赛，没想到歪打正着——竟然是这么有意思的赛制！",
            ["ContentJP"] = "なるほど～！ただのお手伝いのつもりだったけど、思いがけず面白くなってきたじゃん！",
            ["DialogueId"] = 12060731,
            ["GUID"] = "1E3159AE",
            ["NextDialogue"] = 12060732,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3159AE",
            },
        [12060732] = {
            ["Content"] = "把宝物放在地里让别人随意挖，我说你们华胥人都这么有钱，玩这么大嘛？太好了太好了，要发大财了！",
            ["ContentJP"] = "宝探しってことは、オレの得意分野じゃん！いやはや、流石<Default note=\"text:カショ\">華胥</>人。太っ腹すぎる…！！よっしゃあ！掘って掘って大もうけ～！",
            ["DialogueId"] = 12060732,
            ["GUID"] = "1E3159D8",
            ["NextDialogue"] = 12060733,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E3159D8",
            },
        [12060733] = {
            ["Content"] = "咳咳……这位外乡来的朋友，你可能有一些误解。这场赛事中所用的宝物都由某位不知名织星客友情赞助，仅供积分统计，赛后是要归还的。",
            ["ContentJP"] = "あー……いえ、それについては少々誤解が。使用される宝物は、<Default note=\"text:ほしおりびと\">星織人</>の方からのご厚意による提供でして、試合後には全て返却されます。",
            ["DialogueId"] = 12060733,
            ["GUID"] = "1E315A02",
            ["NextDialogue"] = 12060734,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A02",
            },
        [12060734] = {
            ["Content"] = "有借有还是吧，你不用解释，我懂我懂～",
            ["ContentJP"] = "借りたら返す、ね。りょーかいりょーかい。説明なんかいらねぇよ～♪",
            ["DialogueId"] = 12060734,
            ["GUID"] = "1E315A2C",
            ["NextDialogue"] = 12060735,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A2C",
            },
        [12060735] = {
            ["Content"] = "…………您确定您正确理解了这次的赛制吗？",
            ["ContentJP"] = "……本当にご理解いただけてます？",
            ["DialogueId"] = 12060735,
            ["GUID"] = "1E315A56",
            ["NextDialogue"] = 12060736,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A56",
            },
        [12060736] = {
            ["Content"] = "放心吧。我会负起责任，看住她的！",
            ["ContentJP"] = "大丈夫です、私が責任持って彼女を見張ります！",
            ["DialogueId"] = 12060736,
            ["GUID"] = "1E315A80",
            ["NextDialogue"] = 12060737,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315A80",
            },
        [12060737] = {
            ["Content"] = "嘁，没劲。",
            ["ContentJP"] = "ちぇーっ、つまんねぇの。",
            ["DialogueId"] = 12060737,
            ["GUID"] = "1E315AAA",
            ["NextDialogue"] = 12060738,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315AAA",
            },
        [12060738] = {
            ["Content"] = "呵呵，那我就放下心来了。",
            ["ContentJP"] = "ふふ、では心配無用ですね。",
            ["DialogueId"] = 12060738,
            ["GUID"] = "1E315AD4",
            ["NextDialogue"] = 12060739,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315AD4",
            },
        [12060739] = {
            ["Content"] = "赛事即将开始，待几位准备好，就和我说吧。祝您和您的小队旗开得胜。",
            ["ContentJP"] = "まもなく試合開始でございます。準備ができましたら、お声がけください。健闘をお祈りします！",
            ["DialogueId"] = 12060739,
            ["GUID"] = "1E315AFE",
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315AFE",
            },
        [12060740] = {
            ["Content"] = "准备好进入赛场了吗？",
            ["ContentJP"] = "ご準備はよろしいですか？",
            ["DialogueId"] = 12060740,
            ["GUID"] = "1E315B28",
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120607/1E315B28",
            },
        [12060741] = {
            ["Content"] = "我们走吧！",
            ["ContentJP"] = "出発しよう！",
            ["DialogueId"] = 12060741,
            ["GUID"] = "1E315B52",
            },
        [12060742] = {
            ["Content"] = "等等，还有事情没有处理。",
            ["ContentJP"] = "もう少し待って。",
            ["DialogueId"] = 12060742,
            ["GUID"] = "1E315B7C",
            },
        [12060801] = {
            ["Content"] = "你们出来啦，我在观众席上看得一清二楚！按这个节奏下去，一定能稳拿冠军！",
            ["ContentJP"] = "おかえりーっ！観客席からばっちり見てたよ！この調子なら、優勝だって狙えるかも！",
            ["DialogueId"] = 12060801,
            ["GUID"] = "1E31652A",
            ["NextDialogue"] = 12060802,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31652A",
            },
        [12060802] = {
            ["Content"] = "哼哼，简直轻轻松松！我就说嘛，这种“偷宝物”的比赛，简直就是恶魔大盗的专业领域！",
            ["ContentJP"] = "ふふん、ちょろかったな～！宝を盗むなんて、オレ様の十八番なんだから♪",
            ["DialogueId"] = 12060802,
            ["GUID"] = "1E316554",
            ["NextDialogue"] = 12060803,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316554",
            },
        [12060803] = {
            ["Content"] = "明明是寻宝的赛制，竟然被你说成是“偷宝物”……还真是本性不改。",
            ["ContentJP"] = "「盗む」じゃなくて、「探す」ね……本性が漏れてるわよ。",
            ["DialogueId"] = 12060803,
            ["GUID"] = "1E31657E",
            ["NextDialogue"] = 12060804,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31657E",
            },
        [12060804] = {
            ["Content"] = "嘻嘻……一般这种时候，要一群人一起去庆功的吧！我还只听别人说过，没有亲自体会过呢！我们一起去吃小吃吃到饱吧！",
            ["ContentJP"] = "えへへ～、でも、こういう時ってさ、打ち上げってやつするんだろ？ オレ、話でしか聞いたことなかったけど……やってみたーい！みんなで食べ放題とかさ！",
            ["DialogueId"] = 12060804,
            ["GUID"] = "1E3165A8",
            ["NextDialogue"] = 12060805,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3165A8",
            },
        [12060805] = {
            ["Content"] = "刚好，热身完差不多也消食了，再吃一顿也没问题！",
            ["ContentJP"] = "ちょうどお腹空いてきた頃だし、いい提案かも。",
            ["DialogueId"] = 12060805,
            ["GUID"] = "1E3165D2",
            ["NextDialogue"] = 12060806,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3165D2",
            },
        [12060806] = {
            ["Content"] = "喂喂我说你们俩……只是通过了海选赛而已，群英试强敌如云，还不到能大意的时候。",
            ["ContentJP"] = "ちょっと待ってよ、あんたたち……まだ予選通過しただけなんだからね！？この先には強豪がひしめいてるの、忘れないで！",
            ["DialogueId"] = 12060806,
            ["GUID"] = "1E3165FC",
            ["NextDialogue"] = 12060807,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3165FC",
            },
        [12060807] = {
            ["Content"] = "现在小队的战术配合还有不少欠缺之处，所以刚刚我特意让青鸾贰型把我们赛中的表现录了下来。",
            ["ContentJP"] = "チームの連携もまだまだ課題多い。さっきの試合、<Default note=\"text:せいほう\">青鳳</>二型で録画しておいたわ。",
            ["DialogueId"] = 12060807,
            ["GUID"] = "1E316626",
            ["NextDialogue"] = 12060808,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316626",
            },
        [12060808] = {
            ["Content"] = "有道是温故而知新，我们如果用赛中的间隙复盘，一定能领先别人一步，让之后的成绩更上一层楼。",
            ["ContentJP"] = "いい？勝機を上げるには、相手をちゃんと見極めるべし！ちゃんと復習しておくこと！分かった？",
            ["DialogueId"] = 12060808,
            ["GUID"] = "1E316650",
            ["NextDialogue"] = 12060809,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316650",
            },
        [12060809] = {
            ["Content"] = "呜哇，我最讨厌学习了——孤儿院的妈妈都没你能念叨，不听不听，王八念经！",
            ["ContentJP"] = "うわぁぁ、説教タイム来た～！孤児院のママですらそんなに言わなかったよ！聞こえなーい、聞こえなーい！",
            ["DialogueId"] = 12060809,
            ["GUID"] = "1E31667A",
            ["NextDialogue"] = 12060810,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31667A",
            },
        [12060810] = {
            ["Content"] = "顽冥不化！{nickname}，你帮我也说说这家伙！",
            ["ContentJP"] = "このっ……本っ当に言うこと聞かないんだから……！{nickname}からもなんとか言ってやって！",
            ["DialogueId"] = 12060810,
            ["GUID"] = "1E3166A4",
            ["NextOptions"] = {
                [1] = 12060811,
                [2] = 12060812,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3166A4",
            },
        [12060811] = {
            ["Content"] = "饿着肚子是没法赢的。",
            ["ContentJP"] = "腹が減っては戦はできぬ、だよ。（才知+）",
            ["DialogueId"] = 12060811,
            ["GUID"] = "1E3166CE",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12060813,
            },
        [12060812] = {
            ["Content"] = "妈——",
            ["ContentJP"] = "かーちゃーん——（混沌+）",
            ["DialogueId"] = 12060812,
            ["GUID"] = "1E3166F8",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12060813,
            },
        [12060813] = {
            ["Content"] = "{nickname}，怎么你也……",
            ["ContentJP"] = "{nickname}まで……！",
            ["DialogueId"] = 12060813,
            ["GUID"] = "1E316722",
            ["NextDialogue"] = 12060814,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316722",
            },
        [12060814] = {
            ["Content"] = "苏乙你操心太多啦，适当放松才有助于更好赢下比赛嘛。",
            ["ContentJP"] = "でもさ、たまには息抜きも必要でしょ。その方が結果的に、勝てる気が{性别:するな|するよ}。",
            ["DialogueId"] = 12060814,
            ["GUID"] = "1E31674C",
            ["NextDialogue"] = 12060815,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31674C",
            },
        [12060815] = {
            ["Content"] = "……唉，拿你们没办法。",
            ["ContentJP"] = "……まったく、もう。仕方ないわね。",
            ["DialogueId"] = 12060815,
            ["GUID"] = "1E316776",
            ["NextDialogue"] = 12060816,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316776",
            },
        [12060816] = {
            ["Content"] = "走吧，今天我请客。毕竟是我拜托你们参赛在先。",
            ["ContentJP"] = "今日は私が奢るわ。誘ったのはこっちなんだし、ちゃんとお礼くらいはしないとね。",
            ["DialogueId"] = 12060816,
            ["GUID"] = "1E3167A0",
            ["NextDialogue"] = 12060817,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3167A0",
            },
        [12060817] = {
            ["Content"] = "请客？那岂不是意味着随便吃？好耶——记住你这句话了，要把我的八根腕足都喂饱才可以哟，这个我就先收下啦～",
            ["ContentJP"] = "奢り！？好きなだけ食べていいってこと！？やったー！オレの腕足8本、ぜーんぶ満腹にしてもらうからな～！\
 ",
            ["DialogueId"] = 12060817,
            ["GUID"] = "1E3167CA",
            ["NextDialogue"] = 12060818,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3167CA",
            },
        [12060818] = {
            ["Content"] = "……我的钱包！什么时候到你手上的！你给我等等！",
            ["ContentJP"] = "え、ちょっ……財布！？いつの間にっ！？返しなさーいっ！",
            ["DialogueId"] = 12060818,
            ["GUID"] = "1E3167F4",
            ["NextDialogue"] = 12060819,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3167F4",
            },
        [12060819] = {
            ["Content"] = "喂喂，她们怎么一溜烟就没影了，这也跑太快了……小仆从，我们也跟上去吧！",
            ["ContentJP"] = "わっ、二人とも速っ……！ほら下僕、置いてかれないうちに急ごう！",
            ["DialogueId"] = 12060819,
            ["GUID"] = "1E31681E",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31681E",
            },
        [12060820] = {
            ["Content"] = "听我的，押注“衡起天香”队伍。",
            ["ContentJP"] = "いいか？「香律の使徒」チームに賭けるべきだって！",
            ["DialogueId"] = 12060820,
            ["GUID"] = "1E316848",
            ["NextDialogue"] = 12060827,
            ["SpeakNpcId"] = 250012,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316848",
            },
        [12060821] = {
            ["Content"] = "狩月逐香队看起来也非常有潜力！",
            ["ContentJP"] = "でも「香狩り」チームもすごいぞ？あのチームには、白髪隻眼の異国戦士がいるんだ。",
            ["DialogueId"] = 12060821,
            ["GUID"] = "1E316872",
            ["NextDialogue"] = 12060828,
            ["SpeakNpcId"] = 250013,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316872",
            },
        [12060822] = {
            ["Content"] = "不仅参赛的队伍很多，城里的大家也在积极讨论群英试的事情……华胥人对奉香大典还真是热情呢。",
            ["ContentJP"] = "参加チームも多いけど、それ以上に街の人たちも英雄大会の話題で盛り上がってるね……<Default note=\"text:カショ\">華胥</>の人たち、<Default note=\"text:ほうこうのぎ\">奉香の儀</>には本当に情熱を注いでるんだな。",
            ["DialogueId"] = 12060822,
            ["GUID"] = "1E31689C",
            ["NextDialogue"] = 12060823,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31689C",
            },
        [12060823] = {
            ["Content"] = "毕竟是万众瞩目的赛事，大家的兴趣自然就会被吊起来嘛~",
            ["ContentJP"] = "皆の注目が集まる一大イベントだからね。自然と興味も沸いてくるんだよ。",
            ["DialogueId"] = 12060823,
            ["GUID"] = "1E3168C6",
            ["NextDialogue"] = 12060824,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3168C6",
            },
        [12060824] = {
            ["Content"] = "你们怎么走这么慢，赶紧过来排队！",
            ["ContentJP"] = "ちょっとー！のんびり歩いてんじゃねぇよ、早く来い。ほら、列に並ぶんだって！",
            ["DialogueId"] = 12060824,
            ["GUID"] = "1E3168F0",
            ["NextDialogue"] = 12060825,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E3168F0",
            },
        [12060825] = {
            ["Content"] = "就是啊！走路慢腾腾的，知不知道小吃只有刚刚出炉的才好吃！",
            ["ContentJP"] = "そうそう！菓子でも見ながらさ。菓子は焼きたてが一番おいしいんだから！出遅れたら損だよ～！",
            ["DialogueId"] = 12060825,
            ["GUID"] = "1E31691A",
            ["NextDialogue"] = 12060826,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E31691A",
            },
        [12060826] = {
            ["Content"] = "这两人在吃方面倒是莫名地有共同语言呢……",
            ["ContentJP"] = "このふたり、食べ物の好みだけはやたら息ぴったりなんだよ{性别:な|ね}……",
            ["DialogueId"] = 12060826,
            ["GUID"] = "1E316944",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316944",
            },
        [12060827] = {
            ["Content"] = "这支队伍由悬衡派弟子中的后起之秀组成，可谓是今年的全明星阵容，妥妥的夺冠热门选手——",
            ["ContentJP"] = "あれは<Default note=\"text:けんこうは\">懸衡派</>のホープが集まった最強布陣なんだぞ。今大会の大本命だ！",
            ["DialogueId"] = 12060827,
            ["GUID"] = "1E316849",
            ["NextDialogue"] = 12060821,
            ["SpeakNpcId"] = 250012,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316849",
            },
        [12060828] = {
            ["Content"] = "有那白发独眼单刀赴会的异国人助阵，绝对是本届群英试的一匹黑马！",
            ["ContentJP"] = "ダークホースって言うなら、間違いなくここだよ！",
            ["DialogueId"] = 12060828,
            ["GUID"] = "1E316873",
            ["SpeakNpcId"] = 250013,
            ["VoiceName"] = "voice/$Locale$/story/1206/120608/1E316873",
            },
        [12060901] = {
            ["Content"] = "我说，华胥人是魔鬼吗，竟然把章鱼触手放在铁板上烤！",
            ["ContentJP"] = "ちょ、ちょっと待って！？鉄板で……タコの足を焼いてる！？ <Default note=\"text:カショ\">華胥</>人って魔人か！？",
            ["DialogueId"] = 12060901,
            ["GUID"] = "1E317592",
            ["NextDialogue"] = 12060902,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 403009,
                [5] = 201029,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317592",
            },
        [12060902] = {
            ["Content"] = "哼哼，这个我知道！锦鲤皎皎早就和本魔王说过了。华胥啊就是万物皆可吃，只有你想不到的菜，没有华胥人做不出来的菜！",
            ["ContentJP"] = "ふふん、それくらい知ってるもんね。ニシキが言ってたよ～。<Default note=\"text:カショ\">華胥</>ではね、「食べられないものはない」んだって！思いついたら、何でも料理にしちゃうんだってさ！",
            ["DialogueId"] = 12060902,
            ["GUID"] = "1E3175BC",
            ["NextDialogue"] = 12060903,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3175BC",
            },
        [12060903] = {
            ["Content"] = "哇，那他们岂不是得有钢铁一样的肠胃……某种意义上还蛮厉害的。",
            ["ContentJP"] = "ひえ～……胃袋強すぎ。逆にすげぇかも……",
            ["DialogueId"] = 12060903,
            ["GUID"] = "1E3175E6",
            ["NextDialogue"] = 12060904,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3175E6",
            },
        [12060904] = {
            ["Content"] = "老板，我现在有钱了，来一份……不对，给我来十份！",
            ["ContentJP"] = "今ならお金もあることだし……よし。――大将！一人前……いや、十人前で！",
            ["DialogueId"] = 12060904,
            ["GUID"] = "1E317610",
            ["NextDialogue"] = 12060905,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317610",
            },
        [12060905] = {
            ["Content"] = "喂喂，我说你可悠着点花啊！",
            ["ContentJP"] = "ちょ、ちょっと！？あんた、財布の中身考えて使いなさいよ！",
            ["DialogueId"] = 12060905,
            ["GUID"] = "1E31763A",
            ["NextDialogue"] = 12060906,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31763A",
            },
        [12060906] = {
            ["Content"] = "哇，你看那个大叔手唰唰抖几下就画出了好大一条龙，动作简直快到看不清！",
            ["ContentJP"] = "見て見て！あのおじさん、手をひと振りしただけで龍の飴細工ができてる！動きが速すぎて目が追いつかなかったぞ！",
            ["DialogueId"] = 12060906,
            ["GUID"] = "1E317664",
            ["NextDialogue"] = 12060907,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317664",
            },
        [12060907] = {
            ["Content"] = "这是糖人张。他在皓京的孩子中间可是很受欢迎的，这铺位从我小的时候就开在这里了。",
            ["ContentJP"] = "あれは「飴屋のチヤウ」っていう飴職人よ。<Default note=\"text:こうけい\">皓京</>の子どもたちに大人気で、私が小さい頃から、ずっとあそこでお店を出してるの。",
            ["DialogueId"] = 12060907,
            ["GUID"] = "1E31768E",
            ["NextDialogue"] = 12060908,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31768E",
            },
        [12060908] = {
            ["Content"] = "好厉害……",
            ["ContentJP"] = "すごいなあ……",
            ["DialogueId"] = 12060908,
            ["GUID"] = "1E3176B8",
            ["NextDialogue"] = 12060909,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3176B8",
            },
        [12060909] = {
            ["Content"] = "可惜食物很快就会坏掉……要是能带回海伯利亚，让别人也能尝尝就好了……",
            ["ContentJP"] = "でもさ、食いもんってすぐダメになっちまうよな……ヒュペリアに持ち帰れたら、みんなにも食わせてやれるのに。",
            ["DialogueId"] = 12060909,
            ["GUID"] = "1E3176E2",
            ["NextDialogue"] = 12060910,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3176E2",
            },
        [12060910] = {
            ["Content"] = "我有个主意，要不我们来拍照吧。用照片就可以把这些记忆定格下来了。",
            ["ContentJP"] = "じゃあ、写真に撮ってみるのはどう？こうしてる瞬間を残しておけば、あとで思い出を共有できるよ。",
            ["DialogueId"] = 12060910,
            ["GUID"] = "1E31770C",
            ["NextDialogue"] = 12060911,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31770C",
            },
        [12060911] = {
            ["Content"] = "原来你还有相机这种高档货！",
            ["ContentJP"] = "なになに！？カメラなんて高級アイテム、持ってたのかよ！",
            ["DialogueId"] = 12060911,
            ["GUID"] = "1E317736",
            ["NextDialogue"] = 12060912,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317736",
            },
        [12060912] = {
            ["Content"] = "那还等什么，赶紧赶紧，先拍一下那里的小吃！",
            ["ContentJP"] = "じゃあはやく撮って撮って！まずはあっちの屋台からな！",
            ["DialogueId"] = 12060912,
            ["GUID"] = "1E317760",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317760",
            },
        [12060913] = {
            ["Content"] = "让我来看看……",
            ["ContentJP"] = "どれどれ……",
            ["DialogueId"] = 12060913,
            ["FinalDialogueId"] = 12060918,
            ["GUID"] = "1E31778A",
            ["NextOptions"] = {
                [1] = 12060914,
                [2] = 12060916,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31778A",
            },
        [12060914] = {
            ["Content"] = "苏乙，你的表情怎么这么严肃。",
            ["ContentJP"] = "スーイー、表情が硬すぎない？",
            ["DialogueId"] = 12060914,
            ["GUID"] = "1E3177B4",
            ["NextDialogue"] = 12060915,
            },
        [12060915] = {
            ["Content"] = "哎？！别人和我说拍照就应该摆这样的表情，难道不是吗？",
            ["ContentJP"] = "えっ！？だって、写真ってこういう表情するものだって聞いたから……違ったの！？",
            ["DialogueId"] = 12060915,
            ["GUID"] = "1E3177DE",
            ["NextDialogue"] = 12060913,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E3177DE",
            },
        [12060916] = {
            ["Content"] = "塔比瑟，你的脸占了半张照片这么大。",
            ["ContentJP"] = "タビテはカメラに近づきすぎ！",
            ["DialogueId"] = 12060916,
            ["GUID"] = "1E317808",
            ["NextDialogue"] = 12060917,
            },
        [12060917] = {
            ["Content"] = "这样才可以尽显恶魔大盗的风采嘛！",
            ["ContentJP"] = "ふふん、これぞ「悪魔の大泥棒」の存在感ってやつよ～！一枚に収まるにはこのくらいでちょうどいいんだ！",
            ["DialogueId"] = 12060917,
            ["GUID"] = "1E317832",
            ["NextDialogue"] = 12060913,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317832",
            },
        [12060918] = {
            ["Content"] = "哼哼～继续继续，小吃街的那一头还没有逛过呢！",
            ["ContentJP"] = "よしよし、次行こう次！あっちの方、まだ制覇してねぇだろ～",
            ["DialogueId"] = 12060918,
            ["GUID"] = "1E31785C",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E31785C",
            },
        [12060919] = {
            ["Content"] = "小仆从小仆从，机会难得，不如趁这个机会来拍一张合影吧！",
            ["ContentJP"] = "我が下僕よ、せっかくだから記念写真も撮ろうよ！こういう時って、一緒に撮らなきゃもったいないって！",
            ["DialogueId"] = 12060919,
            ["GUID"] = "1E317886",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120609/1E317886",
            },
        [12061001] = {
            ["Content"] = "说书人叔叔，再给我们讲讲上回<H>飘零四杰</>的故事吧，我还想听！",
            ["ContentJP"] = "おじさん、<H>山外山四天王</>の話の続きして～！もっと聞きたいっ！",
            ["DialogueId"] = 12061001,
            ["GUID"] = "1E3185FA",
            ["NextDialogue"] = 12061002,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 201029,
                [5] = 103001,
                },
            ["SpeakNpcId"] = 250014,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3185FA",
            },
        [12061002] = {
            ["Content"] = "那好——书接上回，话说到那“飘零四杰” 在江边义结金兰，正是年少轻狂，意气风发之时！谁能料想到他们后来……",
            ["ContentJP"] = "よしよし、では続きを――かの「山外山四天王」が川辺にて義兄弟の契りを交わしたのは、若さと志に満ちた時代……まさかその後、あのような運命が待ち受けていようとは――",
            ["DialogueId"] = 12061002,
            ["GUID"] = "1E318624",
            ["NextDialogue"] = 12061003,
            ["SpeakNpcId"] = 250007,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318624",
            },
        [12061003] = {
            ["Content"] = "真是太阳打西边出来——世风日下，还有人帮着飘零人说话了。什么“飘零四杰”，简直荒唐！",
            ["ContentJP"] = "へぇ、時代も変わったもんだね。まさか流れ者を褒めそやす声が、堂々と街中に響く日が来るとは。",
            ["DialogueId"] = 12061003,
            ["GUID"] = "1E31864E",
            ["NextDialogue"] = 12061004,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31864E",
            },
        [12061004] = {
            ["Content"] = "……这位客官。我们无冤无仇，您突然冒出来踢场子，这不妥当吧？",
            ["ContentJP"] = "……お客様。我々には何の恨みもないはずですが、突然現れて茶々を入れるのは筋が違うのでは？",
            ["DialogueId"] = 12061004,
            ["GUID"] = "1E318678",
            ["NextDialogue"] = 12061005,
            ["SpeakNpcId"] = 250007,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318678",
            },
        [12061005] = {
            ["Content"] = "妥当？那你在这里妖言惑众就妥当了？",
            ["ContentJP"] = "筋違い？あんたがここでデタラメを吹いてるのは筋が通ってるって？",
            ["DialogueId"] = 12061005,
            ["GUID"] = "1E3186A2",
            ["NextDialogue"] = 12061006,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3186A2",
            },
        [12061006] = {
            ["Content"] = "那飘零四杰引河水浇灭百年不熄的香炉，纵火烧光了六座藏书阁，如此大的动作，当真没有人伤亡？",
            ["ContentJP"] = "山外山四天王だか何だか知らないけど――川をせき止めて香炉を消し、六つの書庫を焼いたあの事件の犠牲者の気持ち、考えたことあるのか？",
            ["DialogueId"] = 12061006,
            ["GUID"] = "1E3186CC",
            ["NextDialogue"] = 12061007,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3186CC",
            },
        [12061007] = {
            ["Content"] = "那“文竹衔环”在人门前悬挂文竹，行凶伤人。说是为了寻仇，但那手下亡魂就当真是罪有应得？谁给了她们裁决断罪的权力？",
            ["ContentJP"] = "人の門に門松を立てて、私刑を執行。仇討ちのつもりだろうが、命を奪っていい理由にはならないだろう。誰が奴らに裁きを下す権利を与えたんだ？",
            ["DialogueId"] = 12061007,
            ["GUID"] = "1E3186F6",
            ["NextDialogue"] = 12061008,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3186F6",
            },
        [12061008] = {
            ["Content"] = "还有那坠落在荒野郊外的机关巨鸟，你应当见过才是。那自天而降的庞然大物毁了多少段河堤，又淹了多少顷良田。此等行径的始作俑者，我说一句居心险恶不为过吧。",
            ["ContentJP"] = "それと――郊外に落ちた巨大なからくり鳥。あれでどれだけの堤が壊され、田畑が水に沈んだか。それを「善意」の造物だと？笑わせるなよ。",
            ["DialogueId"] = 12061008,
            ["GUID"] = "1E318720",
            ["NextDialogue"] = 12061009,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318720",
            },
        [12061009] = {
            ["Content"] = "什么飘零人，一群狼狈为奸的恶徒罢了！",
            ["ContentJP"] = "何が流れ者だ。所詮、結託した無法者の群れじゃないか！",
            ["DialogueId"] = 12061009,
            ["GUID"] = "1E31874A",
            ["NextDialogue"] = 12061010,
            ["RelatedWikiId"] = {
                [1] = 203013,
                },
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31874A",
            },
        [12061010] = {
            ["Content"] = "一派胡言！",
            ["ContentJP"] = "……いい加減にして！全部でたらめよ！",
            ["DialogueId"] = 12061010,
            ["GUID"] = "1E318774",
            ["NextDialogue"] = 12061011,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318774",
            },
        [12061011] = {
            ["Content"] = "那灭蒙巨鸟本是为了清通沟渠，兴修水利，是为造福百姓而设计的造物！使它坠毁的另有其人！",
            ["ContentJP"] = "あの「<Default note=\"text:あおばきょちょう\">青羽巨鳥</>」は、本来は水路を整備するために造られたもの。事故を起こしたのは、操縦者じゃない――他の誰かの仕業よ！",
            ["DialogueId"] = 12061011,
            ["GUID"] = "1E31879E",
            ["NextDialogue"] = 12061012,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31879E",
            },
        [12061012] = {
            ["Content"] = "你不知道事情原委，就不要在这里信口开河，诋毁别人的身后名！",
            ["ContentJP"] = "何も知らないくせに、よくもまあ好き勝手に悪し様を言えたものね。死んだ人の名誉を、これ以上傷つけないで！",
            ["DialogueId"] = 12061012,
            ["GUID"] = "1E3187C8",
            ["NextDialogue"] = 12061013,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3187C8",
            },
        [12061013] = {
            ["Content"] = "呵……这事情原委，我不知道，你反倒就知道了？难不成你也是那飘零人的一份子？",
            ["ContentJP"] = "ふぅん……そんなに必死に庇うってことは、お前も流れ者の一味ってわけだ？",
            ["DialogueId"] = 12061013,
            ["GUID"] = "1E3187F2",
            ["NextDialogue"] = 12061014,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3187F2",
            },
        [12061014] = {
            ["Content"] = "（糟糕，如果苏乙的身份在此时暴露，被有心人做文章可能就麻烦了……！）",
            ["ContentJP"] = "（まずい……今ここでスーイーの素性が知られたら、あとあと面倒なことになるかも……！）",
            ["DialogueId"] = 12061014,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E31881C",
            ["NextDialogue"] = 12061015,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31881C",
            },
        [12061015] = {
            ["Content"] = "当然啦，大家都是道听途说嘛。这事情原委，就看谁编得更真——干脆举办一个讲故事大会好了！",
            ["ContentJP"] = "まあまあ、みんなただの噂で喋ってるだけだよ～。こうなったらさ、どっちが本当の話を「うまく」作れるか、話し合い大会でもやろうぜ♪",
            ["DialogueId"] = 12061015,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E318846",
            ["NextDialogue"] = 12061016,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_AomanT",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318846",
            },
        [12061016] = {
            ["Content"] = "哎呀，这样一想，万一我编的故事不好，听众会不会不喜欢我呀？不行不行，得赶紧对镜练习一下才行。",
            ["ContentJP"] = "でも、もし話がつまんなかったら……オレ、みんなに嫌われちゃうかもな～？あ～大変大変、練習しとかねぇと～♪",
            ["DialogueId"] = 12061016,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E318870",
            ["NextDialogue"] = 12061017,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_AomanT",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318870",
            },
        [12061017] = {
            ["Content"] = "……这个人说话怎么颠三倒四的，难不成脑子不好？",
            ["ContentJP"] = "……あれ、何言ってんの？頭おかしいのか？",
            ["DialogueId"] = 12061017,
            ["GUID"] = "1E31889A",
            ["NextDialogue"] = 12061018,
            ["SpeakNpcName"] = "UI_Npc_Name_Guanzhong",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31889A",
            },
        [12061018] = {
            ["Content"] = "什么人？！竟然敢冒充我说话？！不成体统！",
            ["ContentJP"] = "だ、誰だ！？俺の真似してんのは……っ！ぶっ飛ばすぞ！",
            ["DialogueId"] = 12061018,
            ["GUID"] = "1E3188C4",
            ["NextDialogue"] = 12061019,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3188C4",
            },
        [12061019] = {
            ["Content"] = "嘻嘻……什么人吵不过别人就开始反咬一口，惹人发笑！",
            ["ContentJP"] = "キキキ、論破できないからって怒鳴りだすの、ダサすぎだろ？",
            ["DialogueId"] = 12061019,
            ["DisableMouth"] = 1,
            ["GUID"] = "1E3188EE",
            ["NextDialogue"] = 12061020,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_AomanT",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E3188EE",
            },
        [12061020] = {
            ["Content"] = "你……！",
            ["ContentJP"] = "なっ……！",
            ["DialogueId"] = 12061020,
            ["GUID"] = "1E318918",
            ["NextDialogue"] = 12061021,
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318918",
            },
        [12061021] = {
            ["Content"] = "妈妈，你快过来看，这个大哥哥在和自己吵架耶！",
            ["ContentJP"] = "お母さん見てー！このお兄ちゃん、自分で自分とケンカしてるー！",
            ["DialogueId"] = 12061021,
            ["GUID"] = "1E318942",
            ["NextDialogue"] = 12061022,
            ["SpeakNpcName"] = "UI_Npc_Name_Guanzhong",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318942",
            },
        [12061022] = {
            ["Content"] = "……怀远哥，围过来的路人越来越多了。这种时机引人注目，可能会带来不必要的麻烦，别耽误了大计。",
            ["ContentJP"] = "……カイエンさん、人が集まってきてます。今は目立たない方が……計画に響いては大変ですし。",
            ["DialogueId"] = 12061022,
            ["GUID"] = "1E31896C",
            ["NextDialogue"] = 12061023,
            ["SpeakNpcId"] = 250016,
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E31896C",
            },
        [12061023] = {
            ["Content"] = "算了，赛事在际，不和你纠缠。我们走！",
            ["ContentJP"] = "……チッ。今は英雄大会が先だ。今日のところは許してやろう。行くぞ！",
            ["DialogueId"] = 12061023,
            ["GUID"] = "1E318996",
            ["SpeakNpcId"] = 250015,
            ["SpeakNpcName"] = "UI_Npc_Name_Aoman",
            ["VoiceName"] = "voice/$Locale$/story/1206/120610/1E318996",
            },
        [12061101] = {
            ["Content"] = "抱歉，{nickname}。我刚刚没有控制住自己的情绪……",
            ["ContentJP"] = "ごめんなさい、{nickname}。カッとなってつい……",
            ["DialogueId"] = 12061101,
            ["GUID"] = "1E319662",
            ["NextOptions"] = {
                [1] = 12061102,
                [2] = 12061103,
                },
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 201029,
                [5] = 103001,
                [6] = 203013,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319662",
            },
        [12061102] = {
            ["Content"] = "不是你的问题，是那个人说话难听。",
            ["ContentJP"] = "あんな言い方されたら誰でも怒るよ。あなたのせいじゃない。",
            ["DialogueId"] = 12061102,
            ["GUID"] = "1E31968C",
            ["NextDialogue"] = 12061104,
            },
        [12061103] = {
            ["Content"] = "冲动一下又怎么了。",
            ["ContentJP"] = "たまには感情に任せたっていい。",
            ["DialogueId"] = 12061103,
            ["GUID"] = "1E3196B6",
            ["NextDialogue"] = 12061104,
            },
        [12061104] = {
            ["Content"] = "那个人刚刚提到的灭蒙巨鸟，是我的姑姑苏暮鹧所造。",
            ["ContentJP"] = "あの人が言ってたあのからくり鳥「<Default note=\"text:あおばきょちょう\">青羽巨鳥</>」……私の叔母、ムーチョさんが作ったものなの。",
            ["DialogueId"] = 12061104,
            ["GUID"] = "1E3196E0",
            ["NextDialogue"] = 12061105,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3196E0",
            },
        [12061105] = {
            ["Content"] = "姑姑她一生都想着怎么用机傀术造福华胥，结果死后还要蒙受这样的冤名。我一时冲动就……",
            ["ContentJP"] = "彼女は、生涯をかけてからくりで<Default note=\"text:カショ\">華胥</>を支えようとしていた。なのに死んだ後まで、あんな濡れ衣を着せられるなんて……つい、我を忘れてしまったの。",
            ["DialogueId"] = 12061105,
            ["GUID"] = "1E31970A",
            ["NextDialogue"] = 12061106,
            ["RelatedWikiId"] = {
                [1] = 203014,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31970A",
            },
        [12061106] = {
            ["Content"] = "没关系的，我理解你。换我在你的位置上，我也会这样做。",
            ["ContentJP"] = "気持ちはわかるよ。{性别:僕が君の立場だったら、きっと同じことをしてる|私があなたの立場だったら、きっと同じことをしてるから}。",
            ["DialogueId"] = 12061106,
            ["GUID"] = "1E319734",
            ["NextDialogue"] = 12061107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319734",
            },
        [12061107] = {
            ["Content"] = "……{nickname}，还好有你陪在我身边。",
            ["ContentJP"] = "……ありがとう、{nickname}。あんたがいてくれて、本当によかった。",
            ["DialogueId"] = 12061107,
            ["GUID"] = "1E31975E",
            ["NextDialogue"] = 12061108,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31975E",
            },
        [12061108] = {
            ["Content"] = "我呢我呢？是不是也该谢谢帮你解围的本大盗呀？",
            ["ContentJP"] = "ねぇねぇ、ちょっとぉ？さっきピンチの時に助けてあげたこの大泥棒様にも、感謝のひと言くらいあってもいいんじゃねぇの？",
            ["DialogueId"] = 12061108,
            ["GUID"] = "1E319788",
            ["NextDialogue"] = 12061109,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319788",
            },
        [12061109] = {
            ["Content"] = "不仅帮你教训了一通那个人，我刚刚还偷偷跟了上去，从他们的背包里顺了点有意思的东西哟～怎么样，想不想看看？",
            ["ContentJP"] = "あの嫌なヤツをこらしめたついでにな、あとをつけて背中の荷物から面白いモンをちょいといただいてきたんだ～♪ねえ見たい？ 絶対興味あるって！",
            ["DialogueId"] = 12061109,
            ["GUID"] = "1E3197B2",
            ["NextDialogue"] = 12061110,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3197B2",
            },
        [12061110] = {
            ["Content"] = "塔·比·瑟！我们不是约法三章了吗？不许偷别人的东西，就算对面是坏人也不能打破这个规矩！",
            ["ContentJP"] = "タ・ビ・テ！約束したでしょ？ チームを組んでる間は盗み禁止、どんな相手だろうとそれは守るって！",
            ["DialogueId"] = 12061110,
            ["GUID"] = "1E3197DC",
            ["NextDialogue"] = 12061111,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3197DC",
            },
        }
  end },
  { MinKey = 12061111, MaxKey = 12061732, Loader = function()
      return {
        [12061111] = {
            ["Content"] = "哎？人家明明帮了你，你怎么恩将仇报，好伤心……",
            ["ContentJP"] = "えー、恩を仇で返すってこういうことだな。。せっかく助けたのにぃ、ショック……",
            ["DialogueId"] = 12061111,
            ["GUID"] = "1E319806",
            ["NextDialogue"] = 12061112,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319806",
            },
        [12061112] = {
            ["Content"] = "虽然不知道你是怎么躲过大风九章的感应，但那些狴犴和应天尉可不是随便招惹的，要是被他们盯上了，有你的好果子吃。",
            ["ContentJP"] = "どうやって<Default note=\"text:たいふうきゅうしょう\">大風九章</>の感知をすり抜けたのか知らないけど、<Default note=\"text:ビーアン\">狴犴</>や<Default note=\"text:おうてんい\">応天尉</>に目をつけられたら大変よ。",
            ["DialogueId"] = 12061112,
            ["GUID"] = "1E319830",
            ["NextDialogue"] = 12061113,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319830",
            },
        [12061113] = {
            ["Content"] = "嘻嘻，原来你是在关心我呀！那你可放心吧，恶魔大盗自有妙计！",
            ["ContentJP"] = "キキキ、心配してくれてんだ？ 大丈夫だって。オレには秘密兵器があるからな！",
            ["DialogueId"] = 12061113,
            ["GUID"] = "1E31985A",
            ["NextDialogue"] = 12061114,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31985A",
            },
        [12061114] = {
            ["Content"] = "真的不想看看吗？我在他们背包里找到的这个东西，和你的机关鸟非常相似呢！",
            ["ContentJP"] = "でもさ、このブツ、見覚えねぇの？ お前のあの鳥とよく似てるんだけど？",
            ["DialogueId"] = 12061114,
            ["GUID"] = "1E319884",
            ["NextDialogue"] = 12061115,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319884",
            },
        [12061115] = {
            ["Content"] = "……这是！",
            ["ContentJP"] = "……これは！",
            ["DialogueId"] = 12061115,
            ["GUID"] = "1E3198AE",
            ["NextDialogue"] = 12061116,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3198AE",
            },
        [12061116] = {
            ["Content"] = "“塔比瑟，不许偷别人的东西”，刚刚这话是谁说的？现在怎么不气急败坏了？",
            ["ContentJP"] = "ねえねえ、「盗みは禁止」って言ってたのは誰だっけ～？なんで今は怒ってないの～？",
            ["DialogueId"] = 12061116,
            ["GUID"] = "1E3198D8",
            ["NextDialogue"] = 12061117,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3198D8",
            },
        [12061117] = {
            ["Content"] = "一码归一码……现在有更要紧的问题。",
            ["ContentJP"] = "これは別の話よ……今はもっと大事なことがあるの。",
            ["DialogueId"] = 12061117,
            ["GUID"] = "1E319902",
            ["NextDialogue"] = 12061118,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319902",
            },
        [12061118] = {
            ["Content"] = "每位机傀师的造物都有自己独一无二的特征。我一眼就能看出，你手上拿着的牵机鸢是我姑姑的遗物。",
            ["ContentJP"] = "からくり師の造るものには、それぞれ固有の印がある。これは間違いなく、叔母の「からくり<Default note=\"text:とび\">鳶」よ。",
            ["DialogueId"] = 12061118,
            ["GUID"] = "1E31992C",
            ["NextDialogue"] = 12061119,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E31992C",
            },
        [12061119] = {
            ["Content"] = "但这是怎么到他们手上的？他们又为什么会随身带着姑姑的牵机鸢……莫非这些人对飘零人的厌恶并非空穴来风，还有更深一层的关联……",
            ["ContentJP"] = "でも、どうして彼らがそれを持ってたの？まさか……彼らの流れ者への憎しみには、もっと深い理由が？",
            ["DialogueId"] = 12061119,
            ["GUID"] = "1E319956",
            ["NextDialogue"] = 12061120,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319956",
            },
        [12061120] = {
            ["Content"] = "哎？也就是说本大盗立功了的意思？",
            ["ContentJP"] = "つまり！オレ様の大手柄ね？",
            ["DialogueId"] = 12061120,
            ["GUID"] = "1E319980",
            ["NextDialogue"] = 12061121,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319980",
            },
        [12061121] = {
            ["Content"] = "那就再告诉你一件事——我刚刚想起来，我来到华胥码头上第一眼就撞见了这几个人。他们在那边小声议论着飘零人怎么怎么样，所以我才不小心误解了你。",
            ["ContentJP"] = "あ、そうだ、思い出した。<Default note=\"text:カショ\">華胥</>の港に着いて、最初に見かけたのがあの連中だったんだ。流れ者がどうとか、こそこそ話しててさ。それで……オレ、お前を勘違いしちゃった。",
            ["DialogueId"] = 12061121,
            ["GUID"] = "1E3199AA",
            ["NextDialogue"] = 12061122,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3199AA",
            },
        [12061122] = {
            ["Content"] = "怎么样怎么样？本大盗提供的情报是不是很有用，赶紧夸夸我！",
            ["ContentJP"] = "どう？この情報、役に立っただろ。ほら、褒めていいぞ？",
            ["DialogueId"] = 12061122,
            ["GUID"] = "1E3199D4",
            ["NextDialogue"] = 12061123,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3199D4",
            },
        [12061123] = {
            ["Content"] = "……谢谢。",
            ["ContentJP"] = "……ありがとう。",
            ["DialogueId"] = 12061123,
            ["GUID"] = "1E3199FE",
            ["NextDialogue"] = 12061124,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E3199FE",
            },
        [12061124] = {
            ["Content"] = "哇！太阳从西边出来了！总是板着一张脸的苏乙竟然会对别人说谢谢！",
            ["ContentJP"] = "えっ……？今の、聞き間違いじゃねぇよな？あのスーイーが、「ありがとう」って言った？",
            ["DialogueId"] = 12061124,
            ["GUID"] = "1E319A28",
            ["NextDialogue"] = 12061125,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319A28",
            },
        [12061125] = {
            ["Content"] = "……你这话说的，好像我是什么洪水猛兽一样！受到别人帮助就要说谢谢，这是天经地义的事情，姑姑从小就是这样教我的！",
            ["ContentJP"] = "……まるで、私が化け物みたいな言い方ね。助けてもらったら礼を言う、それだけのことよ。叔母の教えだもの。",
            ["DialogueId"] = 12061125,
            ["GUID"] = "1E319A52",
            ["NextDialogue"] = 12061126,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319A52",
            },
        [12061126] = {
            ["Content"] = "什么嘛！你对恶魔大盗的感激之情才持续了不到半分钟，没劲。",
            ["ContentJP"] = "なんだそれ。悪魔の大泥棒への感謝、三十秒も続かねぇじゃん。つまんねぇ。",
            ["DialogueId"] = 12061126,
            ["GUID"] = "1E319A7C",
            ["NextDialogue"] = 12061127,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319A7C",
            },
        [12061127] = {
            ["Content"] = "我说，小插曲到此为止，我们继续去庆功吧。这个摊子，那里，还有拐角那边，都没有吃过呢。",
            ["ContentJP"] = "さ、じゃあ小芝居はここまで。改めて食べに行こ！ここの屋台も、あそこも、角の向こうも――まだ制覇してねぇだろ？",
            ["DialogueId"] = 12061127,
            ["GUID"] = "1E319AA6",
            ["NextDialogue"] = 12061128,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AA6",
            },
        [12061128] = {
            ["Content"] = "{nickname}，塔比瑟，你们先去逛吧。",
            ["ContentJP"] = "{nickname}、タビテ、先に行ってて。",
            ["DialogueId"] = 12061128,
            ["GUID"] = "1E319AD0",
            ["NextDialogue"] = 12061129,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AD0",
            },
        [12061129] = {
            ["Content"] = "离下午的赛事还有一段时间，我想研究一下姑姑的遗物，看看能不能获得什么有用的信息。",
            ["ContentJP"] = "午後の試合までは、まだ時間がある。叔母の遺品を調べて、何か手がかりが得られないか確かめたいの。",
            ["DialogueId"] = 12061129,
            ["GUID"] = "1E319AFA",
            ["NextDialogue"] = 12061130,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319AFA",
            },
        [12061130] = {
            ["Content"] = "反正我的钱包也在你手里了……但你们别吃太多了，影响下午的比赛状态，听到了吗？",
            ["ContentJP"] = "……財布は、あんたに預けたし大丈夫でしょ。でも食べすぎないで。午後に響くから。いい？",
            ["DialogueId"] = 12061130,
            ["GUID"] = "1E319B24",
            ["NextDialogue"] = 12061131,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B24",
            },
        [12061131] = {
            ["Content"] = "知——道——啦——苏乙妈妈！",
            ["ContentJP"] = "はーいはーい、分かってますよ～、スーイーママ！",
            ["DialogueId"] = 12061131,
            ["GUID"] = "1E319B4E",
            ["NextDialogue"] = 12061132,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B4E",
            },
        [12061132] = {
            ["Content"] = "好，那我们一会儿在赛场会合。",
            ["ContentJP"] = "じゃあ、あとで試合会場で合流しよう。",
            ["DialogueId"] = 12061132,
            ["GUID"] = "1E319B78",
            ["NextDialogue"] = 12061133,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319B78",
            },
        [12061133] = {
            ["Content"] = "嗯，赛场见。",
            ["ContentJP"] = "ええ。",
            ["DialogueId"] = 12061133,
            ["GUID"] = "1E319BA2",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BA2",
            },
        [12061134] = {
            ["DialogueId"] = 12061134,
            ["GUID"] = "1E319BCC",
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BCC",
            },
        [12061135] = {
            ["Content"] = "地狱辣挑战火热进行中——能吃完这碗担担面的挑战者，不仅能够免单，还将获得本店专门准备的豪华大礼！",
            ["ContentJP"] = "地獄の辛味チャレンジ、ただいま開催中！この<Default note=\"text:たんたんめん\">担々麺</>を完食できた方には――お代は免除！さらに、当店特製の豪華賞品を進呈します！",
            ["DialogueId"] = 12061135,
            ["GUID"] = "1E319BF6",
            ["NextDialogue"] = 12061136,
            ["SpeakNpcId"] = 250031,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319BF6",
            },
        [12061136] = {
            ["Content"] = "豪华大礼？",
            ["ContentJP"] = "……豪華賞品？",
            ["DialogueId"] = 12061136,
            ["GUID"] = "1E319C20",
            ["NextDialogue"] = 12061137,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C20",
            },
        [12061137] = {
            ["Content"] = "嘻嘻，说出口的事情可不能再反悔，算上我一个！",
            ["ContentJP"] = "キキキ。言ったからには、取り消しなしな。オレ様も参加するぜー！",
            ["DialogueId"] = 12061137,
            ["GUID"] = "1E319C4A",
            ["NextDialogue"] = 12061138,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C4A",
            },
        [12061138] = {
            ["Content"] = "好嘞！这就给您端上来！",
            ["ContentJP"] = "へい、かしこまり！ただいまお持ちします！",
            ["DialogueId"] = 12061138,
            ["GUID"] = "1E319C74",
            ["SpeakNpcId"] = 250031,
            ["VoiceName"] = "voice/$Locale$/story/1206/120611/1E319C74",
            },
        [12061201] = {
            ["Content"] = "一个小时后，奉香群英试报名处。",
            ["ContentJP"] = "一時間後――奉香英雄大会・受付付近。",
            ["DialogueId"] = 12061201,
            ["GUID"] = "1E31A6CA",
            ["NextDialogue"] = 12061202,
            ["RelatedWikiId"] = {
                [1] = 405014,
                [2] = 405015,
                [3] = 203009,
                [4] = 201029,
                [5] = 103001,
                [6] = 203013,
                [7] = 203014,
                },
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A6CA",
            },
        [12061202] = {
            ["Content"] = "塔比瑟那家伙呢，还没出现吗？！",
            ["ContentJP"] = "タビテは？まだ来てないの？",
            ["DialogueId"] = 12061202,
            ["GUID"] = "1E31A6F4",
            ["NextDialogue"] = 12061203,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A6F4",
            },
        [12061203] = {
            ["Content"] = "半小时前她跑去买吃的，然后就没看到过她了……要不我去找找她？",
            ["ContentJP"] = "1時間ほど前に、食べ物を買いに行くって走っていって……それきり姿を見てないなぁ。探しに行こっか？",
            ["DialogueId"] = 12061203,
            ["GUID"] = "1E31A71E",
            ["NextDialogue"] = 12061204,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A71E",
            },
        [12061204] = {
            ["Content"] = "好，你赶紧去。我们在这里等你的消息。",
            ["ContentJP"] = "お願い。{性别:僕|私}たちは、ここで待ってる。",
            ["DialogueId"] = 12061204,
            ["GUID"] = "1E31A748",
            ["NextDialogue"] = 12061205,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A748",
            },
        [12061205] = {
            ["Content"] = "几位，入场时间快截止了，你们的队伍还没有到齐吗？",
            ["ContentJP"] = "皆さま、まもなく入場締切です。まだ、メンバーが揃っていないようですが……？",
            ["DialogueId"] = 12061205,
            ["GUID"] = "1E31A772",
            ["NextDialogue"] = 12061206,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A772",
            },
        [12061206] = {
            ["Content"] = "等等！这次赛事手册的一万三千字规则我都细细通读过，如果临时更换队员，可以申请十分钟的延迟入场，对吗？",
            ["ContentJP"] = "少し待ってください。――今回の大会ルール、全て目を通しました。急なメンバー変更の場合、十分間の入場猶予を申請できる……そうですよね？",
            ["DialogueId"] = 12061206,
            ["GUID"] = "1E31A79C",
            ["NextDialogue"] = 12061207,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A79C",
            },
        [12061207] = {
            ["Content"] = "呵呵，倒是少有人将赛事规则研究得这么细致。",
            ["ContentJP"] = "ほう。そこまで細かく読み込む方は、珍しい。確かに、その規定はあります。",
            ["DialogueId"] = 12061207,
            ["GUID"] = "1E31A7C6",
            ["NextDialogue"] = 12061208,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A7C6",
            },
        [12061208] = {
            ["Content"] = "是有这个规定，那便依了你。但如果十分钟后你们的同伴还没有来，那就过时不候了。",
            ["ContentJP"] = "では、十分だけお待ちしましょう。それを過ぎれば……その時点で失格です。",
            ["DialogueId"] = 12061208,
            ["GUID"] = "1E31A7F0",
            ["NextDialogue"] = 12061209,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A7F0",
            },
        [12061209] = {
            ["Content"] = "那家伙，到底跑去哪里了……实在是让人不省心……",
            ["ContentJP"] = "……あの人、どこをほっつき歩いてるの。本当に、手のかかる……",
            ["DialogueId"] = 12061209,
            ["GUID"] = "1E31A81A",
            ["NextDialogue"] = 12061210,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A81A",
            },
        [12061210] = {
            ["Content"] = "大老远我就听到有谁在这里磨磨蹭蹭的，没想到竟是你。这叫什么，不是冤家不聚头吗？",
            ["ContentJP"] = "遠くからでも聞こえたぞ。ここで足踏みしてるの、誰かと思えば……お前か。これぞ因縁、というやつかな。",
            ["DialogueId"] = 12061210,
            ["GUID"] = "1E31A844",
            ["NextDialogue"] = 12061211,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A844",
            },
        [12061211] = {
            ["Content"] = "别把希望寄托在虚无缥缈的事情上了。比赛都要开始了，你这同伴怕不是已经胆小逃跑了吧？",
            ["ContentJP"] = "そんな当てのない望みに縋ってどうする。もうすぐ開幕だ。お仲間は――怖気づいて逃げたんじゃないのか？",
            ["DialogueId"] = 12061211,
            ["GUID"] = "1E31A86E",
            ["NextDialogue"] = 12061212,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A86E",
            },
        [12061212] = {
            ["Content"] = "刚刚落荒而逃的明明是你吧？",
            ["ContentJP"] = "……さっき、逃げ腰だったのはあんたでしょう。",
            ["DialogueId"] = 12061212,
            ["GUID"] = "1E31A898",
            ["NextDialogue"] = 12061213,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A898",
            },
        [12061213] = {
            ["Content"] = "落荒而逃？呵，看来苏暮鹧的支持者就和她本人一样，不分青红皂白，黑的都能说成白的。",
            ["ContentJP"] = "逃げ腰？ふん……黒を白と言い張るか。いかにもムーチョの取り巻きらしい。",
            ["DialogueId"] = 12061213,
            ["GUID"] = "1E31A8C2",
            ["NextDialogue"] = 12061214,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A8C2",
            },
        [12061214] = {
            ["Content"] = "……我奉劝你不要再说她半个字坏话！",
            ["ContentJP"] = "……それ以上、彼女を侮辱するな。",
            ["DialogueId"] = 12061214,
            ["GUID"] = "1E31A8EC",
            ["NextOptions"] = {
                [1] = 12061215,
                [2] = 12061216,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A8EC",
            },
        [12061215] = {
            ["Content"] = "（沉默地上前站在苏乙身旁。）",
            ["ContentJP"] = "（黙ってスーイーの隣に立つ）（共感+）",
            ["DialogueId"] = 12061215,
            ["GUID"] = "1E31A916",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12061217,
            },
        [12061216] = {
            ["Content"] = "来，战啊！",
            ["ContentJP"] = "相手になろう！（混沌+）",
            ["DialogueId"] = 12061216,
            ["GUID"] = "1E31A940",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12061217,
            },
        [12061217] = {
            ["Content"] = "何事在此喧闹？",
            ["ContentJP"] = "……何やら、騒がしいな。",
            ["DialogueId"] = 12061217,
            ["GUID"] = "1E31A96A",
            ["NextDialogue"] = 12061218,
            ["RelatedWikiId"] = {
                [1] = 203004,
                },
            ["SpeakNpcId"] = 250005,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A96A",
            },
        [12061218] = {
            ["Content"] = "……应天尉大人？",
            ["ContentJP"] = "……<Default note=\"text:おうてんい\">応天尉</>、様！？",
            ["DialogueId"] = 12061218,
            ["GUID"] = "1E31A994",
            ["NextDialogue"] = 12061219,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A994",
            },
        [12061219] = {
            ["Content"] = "煜明，你怎么来了？是来这里处理公务的吗？",
            ["ContentJP"] = "ユーミン？どうしてここに？もしかして公務？",
            ["DialogueId"] = 12061219,
            ["GUID"] = "1E31A9BE",
            ["NextDialogue"] = 12061220,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A9BE",
            },
        [12061220] = {
            ["Content"] = "并非，在下此行因私事前来。虽非在职之身，但若有纠纷，我可调解一二。",
            ["ContentJP"] = "いや。本日は私用だ。職務中ではないが――仲裁程度なら、役に立てよう。",
            ["DialogueId"] = 12061220,
            ["GUID"] = "1E31A9E8",
            ["NextDialogue"] = 12061221,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31A9E8",
            },
        [12061221] = {
            ["Content"] = "……只是些平常口角，还不需要劳烦应天尉大人出面。",
            ["ContentJP"] = "……ただの口論です。<Default note=\"text:おうてんい\">応天尉</>様のお手を煩わせるほどでは。",
            ["DialogueId"] = 12061221,
            ["GUID"] = "1E31AA12",
            ["NextDialogue"] = 12061222,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA12",
            },
        [12061222] = {
            ["Content"] = "既然是不违背大风九章的争执，二位还请各退一步，息事宁人吧。如此可好？",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>に触れない争いなら、ここで終わらせろ。互いに引け。",
            ["DialogueId"] = 12061222,
            ["GUID"] = "1E31AA3C",
            ["NextDialogue"] = 12061223,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA3C",
            },
        [12061223] = {
            ["Content"] = "诸位，别来无恙。",
            ["ContentJP"] = "……久しぶりだな。",
            ["DialogueId"] = 12061223,
            ["GUID"] = "1E31AA66",
            ["NextDialogue"] = 12061224,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA66",
            },
        [12061224] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12061224,
            ["GUID"] = "1E31AA90",
            ["NextDialogue"] = 12061225,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AA90",
            },
        [12061225] = {
            ["Content"] = "小仆从小仆从，大事不好了！塔比瑟说她肚子不舒服来不了了——咦，煜明，你怎么在这里？",
            ["ContentJP"] = "た、大変だぁ！タビテが、お腹を壊して来られないって――ユーミン？なんでここに？",
            ["DialogueId"] = 12061225,
            ["GUID"] = "1E31AABA",
            ["NextDialogue"] = 12061226,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AABA",
            },
        [12061226] = {
            ["Content"] = "在下受人所托，那位关注到你们的困境，特意委托我前来助你们参加群英试。公平起见，本次赛事中煜明不会借用大风九章的力量，仅以一身武艺参赛。",
            ["ContentJP"] = "頼まれただけだ。お前たちの状況を見かねた人物がいてな。公平のため、この試合では大風九章の力は使わない。技のみで出る。（人物=シリュウ",
            ["DialogueId"] = 12061226,
            ["GUID"] = "1E31AAE4",
            ["NextDialogue"] = 12061227,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AAE4",
            },
        [12061227] = {
            ["Content"] = "哇，是谁这么好心！",
            ["ContentJP"] = "えっ、そんな人が！？",
            ["DialogueId"] = 12061227,
            ["GUID"] = "1E31AB0E",
            ["NextDialogue"] = 12061228,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB0E",
            },
        [12061228] = {
            ["Content"] = "……受人所托？……我不需要谁的帮助，自己就能渡过难关。",
            ["ContentJP"] = "……人に頼まれた？……私は、助けはいらない。自分で切り抜けられるわ。",
            ["DialogueId"] = 12061228,
            ["GUID"] = "1E31AB38",
            ["NextDialogue"] = 12061229,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB38",
            },
        [12061229] = {
            ["Content"] = "诶？苏乙……",
            ["ContentJP"] = "え……（疑問）",
            ["DialogueId"] = 12061229,
            ["GUID"] = "1E31AB62",
            ["NextDialogue"] = 12061230,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB62",
            },
        [12061230] = {
            ["Content"] = "几位，抱歉打断你们的交谈。时限快到了，无论是更换队友继续参赛，还是在这里弃权，都需要你们尽快做出决定。",
            ["ContentJP"] = "お話し中失礼します。残り時間がわずかです。メンバーを変更するか、ここで棄権するか――早急にお決めください。",
            ["DialogueId"] = 12061230,
            ["GUID"] = "1E31AB8C",
            ["NextDialogue"] = 12061231,
            ["SpeakNpcId"] = 250011,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AB8C",
            },
        [12061231] = {
            ["Content"] = "呜啊，这就是糟糕的事情一定会同时发生的定律吧！怎么办，急得快团团转了！",
            ["ContentJP"] = "うわぁ……悪いことってほんと重なるもんだね……どうする{nickname}！これまずいって！",
            ["DialogueId"] = 12061231,
            ["GUID"] = "1E31ABB6",
            ["NextDialogue"] = 12061232,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31ABB6",
            },
        [12061232] = {
            ["Content"] = "苏乙，先开始比赛吧。有什么事赛后再说，好吗？",
            ["ContentJP"] = "スーイー。まずは、試合が最優先だ。話は、終わってからすればいい。",
            ["DialogueId"] = 12061232,
            ["GUID"] = "1E31ABE0",
            ["NextDialogue"] = 12061233,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31ABE0",
            },
        [12061233] = {
            ["Content"] = "……好，我答应你。",
            ["ContentJP"] = "……わかった。",
            ["DialogueId"] = 12061233,
            ["GUID"] = "1E31AC0A",
            ["NextDialogue"] = 12061234,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AC0A",
            },
        [12061234] = {
            ["Content"] = "煜明，接下来的比赛，还要拜托你了。",
            ["ContentJP"] = "ユーミン。次の試合、お願い{性别：|ね}。",
            ["DialogueId"] = 12061234,
            ["GUID"] = "1E31AC34",
            ["NextDialogue"] = 12061235,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AC34",
            },
        [12061235] = {
            ["Content"] = "愿为驱驰。",
            ["ContentJP"] = "……了解した。",
            ["DialogueId"] = 12061235,
            ["GUID"] = "1E31AC5E",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120612/1E31AC5E",
            },
        [12061301] = {
            ["Content"] = "明明比赛获胜了，大家怎么都板着脸一副不高兴的样子……",
            ["ContentJP"] = "勝ったのに、なんだかみんな浮かない顔してる……？",
            ["DialogueId"] = 12061301,
            ["GUID"] = "1E31B732",
            ["NextDialogue"] = 12061302,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B732",
            },
        [12061302] = {
            ["Content"] = "那个……虽然塔比瑟那家伙放鸽子了，但你们也不用这么生气吧。",
            ["ContentJP"] = "……その、タビサがドタキャンしたのは残念だけど、そんなに怒らなくても……",
            ["DialogueId"] = 12061302,
            ["GUID"] = "1E31B75C",
            ["NextDialogue"] = 12061303,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B75C",
            },
        [12061303] = {
            ["Content"] = "苏乙，赛前时间仓促，我无暇过问。但有一件事让我无法不挂心。",
            ["ContentJP"] = "スーイー、試合前は時間がなさすぎて何も言えなかった。だが、どうしても気になっていることがある。",
            ["DialogueId"] = 12061303,
            ["GUID"] = "1E31B786",
            ["NextDialogue"] = 12061304,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B786",
            },
        [12061304] = {
            ["Content"] = "刚刚你和那人争执之时，提到了苏暮鹧的名字。你们的口角因何而起？事到如今，你……依然无法释怀吗？",
            ["ContentJP"] = "先ほど口論になった際、あんたはムーチョの名を出したな。何があった？……まさか、まだ忘れられないのか？",
            ["DialogueId"] = 12061304,
            ["GUID"] = "1E31B7B0",
            ["NextDialogue"] = 12061305,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B7B0",
            },
        [12061305] = {
            ["Content"] = "有人侮辱了姑姑的名誉，我自然要还击。怎么，你有意见吗？",
            ["ContentJP"] = "叔母を貶されたら、黙っていられないでしょう？それだけよ……何か文句ある？",
            ["DialogueId"] = 12061305,
            ["GUID"] = "1E31B7DA",
            ["NextDialogue"] = 12061306,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B7DA",
            },
        [12061306] = {
            ["Content"] = "煜明无意多事。只是这样妄起争执，或许会让山外山的人担心。",
            ["ContentJP"] = "いや、咎めるつもりはない。ただ、ああした場で争えば、<Default note=\"text:さんがいさん\">山外山</>の者たちにも波紋が及ぶかもしれない。",
            ["DialogueId"] = 12061306,
            ["GUID"] = "1E31B804",
            ["NextDialogue"] = 12061307,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B804",
            },
        [12061307] = {
            ["Content"] = "你的意思是让我在这个节骨眼上安分一点？觉得飘零人在这种敏感时候出风头会给山外山带来麻烦？",
            ["ContentJP"] = "つまり、大人しくしてろって言いたいのね？流れ者が余計な目立ち方をすれば、組織全体の足を引っ張るかもしれないって？",
            ["DialogueId"] = 12061307,
            ["GUID"] = "1E31B82E",
            ["NextDialogue"] = 12061308,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B82E",
            },
        [12061308] = {
            ["Content"] = "抱歉，虽然不知道是谁拜托你来的，但是我拒绝。你或许能以身作则，说着什么“既往不咎”就转身投靠大风九章，但我做不到。",
            ["ContentJP"] = "……誰に頼まれて来たのか知らないけど、忠告はお断りよ。あんたは「水に流せばいい」とでも思って、<Default note=\"text:たいふうきゅうしょう\">大風九章</>に擦り寄ったんでしょうけど――私には、できない。",
            ["DialogueId"] = 12061308,
            ["GUID"] = "1E31B858",
            ["NextDialogue"] = 12061309,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B858",
            },
        [12061309] = {
            ["Content"] = "…………苏乙，你可能有所误解。",
            ["ContentJP"] = "…………スーイー、それは誤解だ。",
            ["DialogueId"] = 12061309,
            ["GUID"] = "1E31B882",
            ["NextDialogue"] = 12061310,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B882",
            },
        [12061310] = {
            ["Content"] = "这里的空气太闷了。下场赛事开始还要半个小时吧？中场休息时间我想出去走走。",
            ["ContentJP"] = "この場の空気、息が詰まりそう。次の試合まで、まだ時間あるでしょ？ちょっと外の風に当たってくる。（ユーミンを無視して立ち去る）",
            ["DialogueId"] = 12061310,
            ["GUID"] = "1E31B8AC",
            ["NextDialogue"] = 12061311,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B8AC",
            },
        [12061311] = {
            ["Content"] = "{nickname}，这边就先交给你们了。",
            ["ContentJP"] = "{nickname}、あとはお願いね。",
            ["DialogueId"] = 12061311,
            ["GUID"] = "1E31B8D6",
            ["NextDialogue"] = 12061312,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B8D6",
            },
        [12061312] = {
            ["Content"] = "呜，气氛怎么会变成这样……",
            ["ContentJP"] = "……うぅ、なんでこんなことに……",
            ["DialogueId"] = 12061312,
            ["GUID"] = "1E31B900",
            ["NextDialogue"] = 12061313,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B900",
            },
        [12061313] = {
            ["Content"] = "……{nickname}，苏乙和我之间恐怕有着诸多误会。我若是继续失言，只会让她徒增烦恼。可否劳烦你去安抚她一二？",
            ["ContentJP"] = "……{nickname}、スーイーとは、どうにも誤解が生まれているようだ。これ以上、拙い言葉を重ねても、彼女を煩わせるだけだろう。すまないが……どうか、彼女の気持ちを少しでも和らげてやってくれないか。",
            ["DialogueId"] = 12061313,
            ["GUID"] = "1E31B92A",
            ["NextDialogue"] = 12061314,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B92A",
            },
        [12061314] = {
            ["Content"] = "嗯，不用你说我也会的。",
            ["ContentJP"] = "言われなくても、そのつもりだよ。",
            ["DialogueId"] = 12061314,
            ["GUID"] = "1E31B954",
            ["NextDialogue"] = 12061315,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B954",
            },
        [12061315] = {
            ["Content"] = "白，你和煜明在这里等着我好吗？我去带苏乙回来。",
            ["ContentJP"] = "スノウ、ユーミンと一緒にここで待ってて。",
            ["DialogueId"] = 12061315,
            ["GUID"] = "1E31B97E",
            ["NextDialogue"] = 12061316,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B97E",
            },
        [12061316] = {
            ["Content"] = "好，小仆从，那你快去快回。",
            ["ContentJP"] = "うん、はやく戻ってきてね！",
            ["DialogueId"] = 12061316,
            ["GUID"] = "1E31B9A8",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120613/1E31B9A8",
            },
        [12061401] = {
            ["Content"] = "找你找了半天，没想到你一个人躲在这儿玩狗尾巴草。怎么样，这草好玩吗？",
            ["ContentJP"] = "やっと見つけた。こんなとこで猫じゃらしなんか弄って……楽しい？",
            ["DialogueId"] = 12061401,
            ["GUID"] = "1E31C79A",
            ["NextDialogue"] = 12061402,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C79A",
            },
        [12061402] = {
            ["Content"] = "……不好玩。草的汁液全沾到手指缝里了，鼻腔里也都是土腥味，玩一会儿就腻了。",
            ["ContentJP"] = "……別に。手はベタベタするし、土臭い匂いも鼻につくし、もう飽きた。",
            ["DialogueId"] = 12061402,
            ["GUID"] = "1E31C7C4",
            ["NextDialogue"] = 12061403,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C7C4",
            },
        [12061403] = {
            ["Content"] = "不好玩你还在这里待这么久？",
            ["ContentJP"] = "なのにずっとここにいるんだ？",
            ["DialogueId"] = 12061403,
            ["GUID"] = "1E31C7EE",
            ["NextDialogue"] = 12061404,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C7EE",
            },
        [12061404] = {
            ["Content"] = "呜，因为我没想好该怎么回去和那家伙道歉嘛……我刚一跑出来就已经后悔了。",
            ["ContentJP"] = "うぅ……あの人に謝ろうと思ったのに、どうしても言葉が見つからなくて……逃げ出した時点で、もう後悔してたのに……",
            ["DialogueId"] = 12061404,
            ["GUID"] = "1E31C818",
            ["NextDialogue"] = 12061405,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C818",
            },
        [12061405] = {
            ["Content"] = "我也不知道自己刚刚为什么会那么冲动。{nickname}，感觉我一辈子的丢脸时刻都要被你看光了……",
            ["ContentJP"] = "なんでだろう…私、ついカッとなって冷静さを失ってしまった。{nickname}の前じゃいつもカッコ悪いとこばっかり見せてる気がする……",
            ["DialogueId"] = 12061405,
            ["GUID"] = "1E31C842",
            ["NextDialogue"] = 12061406,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C842",
            },
        [12061406] = {
            ["Content"] = "不过你愿意来找我，我很高兴。",
            ["ContentJP"] = "でも……探しに来てくれて、嬉しかったよ。",
            ["DialogueId"] = 12061406,
            ["GUID"] = "1E31C86C",
            ["NextDialogue"] = 12061407,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C86C",
            },
        [12061407] = {
            ["Content"] = "我知道原因。因为你很在乎他们一直提到的那个人，你的姑姑。她的名字是苏暮鹧，对吧？",
            ["ContentJP"] = "きっと、スーイーがあんなに怒ったのは、あの人――あなたの「叔母さん」のことを大事に思ってるからだよね。ムーチョさん、だっけ？",
            ["DialogueId"] = 12061407,
            ["GUID"] = "1E31C896",
            ["NextDialogue"] = 12061408,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C896",
            },
        [12061408] = {
            ["Content"] = "如果不介意的话，你可以对我多讲讲她的事情吗？我想这样或许能让你好受一些。",
            ["ContentJP"] = "もしよかったら……その人の話、もっと聞かせてくれない{性别:か|}？話すことで、少しでも気が紛れるなら。",
            ["DialogueId"] = 12061408,
            ["GUID"] = "1E31C8C0",
            ["NextDialogue"] = 12061409,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C8C0",
            },
        [12061409] = {
            ["Content"] = "……谢谢你，{nickname}。你没猜错，姑姑是我在这个世界上最重要的人。",
            ["ContentJP"] = "……ありがとう、{nickname}。あんたの言うとおり、叔母は……私にとって、世界でいちばん大事な人だった。",
            ["DialogueId"] = 12061409,
            ["GUID"] = "1E31C8EA",
            ["NextDialogue"] = 12061410,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C8EA",
            },
        [12061410] = {
            ["Content"] = "让我想想，该从哪里说起呢……或许就从“天工苏氏”说起吧。",
            ["ContentJP"] = "どこから話せばいいかな……そうね、「<Default note=\"text:てんこう\">天工</>のスー氏」のことから始めようか。",
            ["DialogueId"] = 12061410,
            ["GUID"] = "1E31C914",
            ["NextDialogue"] = 12061411,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C914",
            },
        [12061411] = {
            ["Content"] = "“天工苏氏”……这是你家族的名号吗？",
            ["ContentJP"] = "「天工のスー氏」……君の一家のこと？",
            ["DialogueId"] = 12061411,
            ["GUID"] = "1E31C93E",
            ["NextDialogue"] = 12061412,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C93E",
            },
        [12061412] = {
            ["Content"] = "嗯，天工苏氏曾经是机枢派最响亮的名号哦！……不过，都是黍离之战之前的事了。",
            ["ContentJP"] = "うん。<Default note=\"text:きすうは\">機枢派</>では、かつて誰もがその名を知っていた一族だったの。でもそれも……<Default note=\"text:しょりのらん\">黍離の乱</>より前の話。",
            ["DialogueId"] = 12061412,
            ["GUID"] = "1E31C968",
            ["NextDialogue"] = 12061413,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C968",
            },
        [12061413] = {
            ["Content"] = "我还记得，七岁那年，我照着父母藏在箱底的图纸造出一台机傀，举在头顶上一路跑去交给母亲，向她讨要奖赏。",
            ["ContentJP"] = "私、七つの頃にね、両親が箱の奥に隠してた図面を真似て、小さなからくり人形を作ったの。得意になって、頭の上に掲げて母さんのところまで走ってった。きっと褒めてもらえると思って。",
            ["DialogueId"] = 12061413,
            ["GUID"] = "1E31C992",
            ["NextDialogue"] = 12061414,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C992",
            },
        [12061414] = {
            ["Content"] = "她接过那台机傀，反复把玩。我以为她会夸我，没想到她突然哭了。",
            ["ContentJP"] = "でも……母さん、それを手にした途端、泣き出したの。",
            ["DialogueId"] = 12061414,
            ["GUID"] = "1E31C9BC",
            ["NextDialogue"] = 12061415,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C9BC",
            },
        [12061415] = {
            ["Content"] = "“我的女儿，她这般天赐的巧手，为何偏偏生在这个世道？”母亲一直这样自言自语——那时我不知她为什么哭，只能不停地帮她擦眼泪，答应她再也不摆弄机傀了。",
            ["ContentJP"] = "「こんな時代に、どうしてこの子にだけ、こんな器用な手を……」って。私は理由がわからなくて、ただ泣く母さんの涙を拭いて、「もう創らない」って、何度も誓った。",
            ["DialogueId"] = 12061415,
            ["GUID"] = "1E31C9E6",
            ["NextDialogue"] = 12061416,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31C9E6",
            },
        [12061416] = {
            ["Content"] = "后来我才知道，自黍离之战、机枢派衰落后，很多珍贵的技术被悬衡派视为不可触碰的禁忌，加以封存。",
            ["ContentJP"] = "あとになって知ったの。<Default note=\"text:しょりのらん\">黍離の乱</>の後、<Default note=\"text:きすうは\">機枢派</>の多くの技術は禁忌とされ、封印されてしまったってこと。",
            ["DialogueId"] = 12061416,
            ["GUID"] = "1E31CA10",
            ["NextDialogue"] = 12061417,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA10",
            },
        [12061417] = {
            ["Content"] = "天工苏氏虽得以保全自身，但也只得将引以为傲的机傀术藏进箱底，如履薄冰地度日。",
            ["ContentJP"] = "天工のスー氏は命こそ守れたけど、誇りだったからくり術は、誰にも見せられず箱の底にしまわれた。",
            ["DialogueId"] = 12061417,
            ["GUID"] = "1E31CA3A",
            ["NextDialogue"] = 12061418,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA3A",
            },
        [12061418] = {
            ["Content"] = "我曾以为自己也会像父母那样再不逾矩，平凡安稳地度过一生。直到有一天，姑姑神神秘秘地问我——“你其实很想学机傀术，是不是？那我来教你啊。”",
            ["ContentJP"] = "そんな状況だから、私も、両親と同じように一生おとなしく暮らすんだと思ってた。でもある日、叔母が言ったの――「本当は、からくり術を学びたいんでしょう？なら、私が教えてあげる」って。",
            ["DialogueId"] = 12061418,
            ["GUID"] = "1E31CA64",
            ["NextDialogue"] = 12061419,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA64",
            },
        [12061419] = {
            ["Content"] = "那时我就知道，我逃不掉了。",
            ["ContentJP"] = "その瞬間、私の運命は決まった。",
            ["DialogueId"] = 12061419,
            ["GUID"] = "1E31CA8E",
            ["NextDialogue"] = 12061420,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CA8E",
            },
        [12061420] = {
            ["Content"] = "姑姑在工造局当值。只要有空，她就会来后院陪着我，教我机傀制造的技巧，还给我讲各种各样有意思的故事。",
            ["ContentJP"] = "叔母は<Default note=\"text:こうぞうきょく\">工造局</>で働いてたの。仕事が終わると、よく裏庭に来てくれて、からくりの作り方や、面白い話をたくさん教えてくれた。",
            ["DialogueId"] = 12061420,
            ["GUID"] = "1E31CAB8",
            ["NextDialogue"] = 12061421,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CAB8",
            },
        [12061421] = {
            ["Content"] = "你知道我为什么叫这个名字吗？",
            ["ContentJP"] = "ねぇ、私の名前の由来、知ってる？",
            ["DialogueId"] = 12061421,
            ["GUID"] = "1E31CAE2",
            ["NextDialogue"] = 12061422,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CAE2",
            },
        [12061422] = {
            ["Content"] = "姑姑那时候，总是和我描述一种从不归巢的燕子，叫做乙鸟。 它们翔于长空中，自由自在不受束缚。我可向往了。",
            ["ContentJP"] = "叔母はいつも、「<Default note=\"text:いちょう\">乙鳥</>」の話をしてくれたの。巣を持たず空を漂う自由な鳥。私はその姿に、心を奪われた。",
            ["DialogueId"] = 12061422,
            ["GUID"] = "1E31CB0C",
            ["NextDialogue"] = 12061423,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB0C",
            },
        [12061423] = {
            ["Content"] = "向往“自由”的姑姑，逐渐被山外山的理想所吸引。为了创造一个机枢术不再处处受限的未来，她与飘零人开始进行书信往来。",
            ["ContentJP"] = "そんな自由を愛する叔母は、やがて<Default note=\"text:さんがいさん\">山外山</>の理念に惹かれ、流れ者と文を交わすようになった。",
            ["DialogueId"] = 12061423,
            ["GUID"] = "1E31CB36",
            ["NextDialogue"] = 12061424,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB36",
            },
        [12061424] = {
            ["Content"] = "后来有一天，姑姑与飘零人的联系暴露，于是她离开皓京加入山外山，像乙鸟一样去追寻那份自由了，只剩下留在原地的我。",
            ["ContentJP"] = "でも、その繋がりが露見してしまい……彼女は<Default note=\"text:こうけい\">皓京</>を去り、<Default note=\"text:さんがいさん\">山外山</>に加わったの。まるで<Default note=\"text:いちょう\">乙鳥</>のように、自らの理想を追って。",
            ["DialogueId"] = 12061424,
            ["GUID"] = "1E31CB60",
            ["NextDialogue"] = 12061425,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB60",
            },
        [12061425] = {
            ["Content"] = "再后来，当我决心跟随姑姑的脚步离家加入山外山时，我将自己的名字改成了苏乙。可惜那时候姑姑已经再也看不到了……",
            ["ContentJP"] = "残された私は、彼女を追いかけるように<Default note=\"text:さんがいさん\">山外山</>へ向かい、名前も「スーイー」に改めた。けれど――その時にはもう、叔母はいなかった……",
            ["DialogueId"] = 12061425,
            ["GUID"] = "1E31CB8A",
            ["NextOptions"] = {
                [1] = 12061426,
                [2] = 12061427,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CB8A",
            },
        [12061426] = {
            ["Content"] = "节哀……",
            ["ContentJP"] = "……うん。",
            ["DialogueId"] = 12061426,
            ["GUID"] = "1E31CBB4",
            ["NextDialogue"] = 12061428,
            },
        [12061427] = {
            ["Content"] = "她发生了什么？",
            ["ContentJP"] = "何があったの？",
            ["DialogueId"] = 12061427,
            ["GUID"] = "1E31CBDE",
            ["NextDialogue"] = 12061428,
            },
        [12061428] = {
            ["Content"] = "姑姑在工造局时期设计了一种用于疏通水路的灭蒙巨鸟。她走后，灭蒙巨鸟无人修缮，日久生患。",
            ["ContentJP"] = "叔母はね、<Default note=\"text:こうぞうきょく\">工造局</>にいた時、「<Default note=\"text:あおばきょちょう\">青羽巨鳥</>」っていう、水路を整えるからくりを設計したの。でも彼女が去った後、手入れされずに放置されて……それが原因で、事故が起き始めた。",
            ["DialogueId"] = 12061428,
            ["GUID"] = "1E31CC08",
            ["NextDialogue"] = 12061429,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC08",
            },
        [12061429] = {
            ["Content"] = "为了大家的安全，姑姑冒险离开山外山，赶回皓京城郊，却被应天尉当场诛杀。但这在某些人口中，竟被歪曲成了她试图操纵灭蒙、造成破坏。",
            ["ContentJP"] = "それを知った叔母は、<Default note=\"text:さんがいさん\">山外山</>を出て、こっそり<Default note=\"text:こうけい\">皓京</>に戻ったの。でも現地で彼女を待っていたのは、救いではなく処刑だった。「青羽巨鳥を使って破壊工作を企んだ」――そう、決めつけられて。",
            ["DialogueId"] = 12061429,
            ["GUID"] = "1E31CC32",
            ["NextDialogue"] = 12061430,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC32",
            },
        [12061430] = {
            ["Content"] = "所以你没法接受别人诋毁她的所作所为，是吗？",
            ["ContentJP"] = "……そんな言われ方、納得できるわけないよね。",
            ["DialogueId"] = 12061430,
            ["GUID"] = "1E31CC5C",
            ["NextDialogue"] = 12061431,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC5C",
            },
        [12061431] = {
            ["Content"] = "嗯……抱歉，之前一直没有告诉你我参加这次比赛的初衷，以及自己的私心，我应该更早对你全盘托出的。",
            ["ContentJP"] = "……うん。ごめんね。試合に出た理由、ずっと話せなくて。本当は、最初から全部伝えるべきだった。",
            ["DialogueId"] = 12061431,
            ["GUID"] = "1E31CC86",
            ["NextDialogue"] = 12061432,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CC86",
            },
        [12061432] = {
            ["Content"] = "我想在群英试中拨得头筹，想站在皓京的制高点，在万众瞩目之下，在龙神面前为我的姑姑苏暮鹧正名。告诉世人——她和她的理念没有错。",
            ["ContentJP"] = "私ね、英雄大会で勝ちたかったの。<Default note=\"text:こうけい\">皓京</>の頂点に立って、みんなの前で、龍神の前で叫びたかった――叔母とその理想は、間違ってなんかいなかったって。",
            ["DialogueId"] = 12061432,
            ["GUID"] = "1E31CCB0",
            ["NextDialogue"] = 12061433,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CCB0",
            },
        [12061433] = {
            ["Content"] = "当大风九章开始推动辩法改制后，我以为这个梦想已经触手可及了……但想法总是比现实美好。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>が裁定を見直すって動き出したとき、夢が手の届くところに来たと思った。でも……現実は、そう簡単にはいかなかった。",
            ["DialogueId"] = 12061433,
            ["GUID"] = "1E31CCDA",
            ["NextDialogue"] = 12061434,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CCDA",
            },
        [12061434] = {
            ["Content"] = "人们对飘零人的回归不知所措，皓京还爆发了抗议。面对这种天翻地覆的改变，他们会迷茫也是在所难免的吧。",
            ["ContentJP"] = "流れ者の帰還に、人々は戸惑ってる。<Default note=\"text:こうけい\">皓京</>では抗議すら起きた。……無理もないよね。あまりに急な変化に、皆がついていけないのも当然だ。",
            ["DialogueId"] = 12061434,
            ["GUID"] = "1E31CD04",
            ["NextDialogue"] = 12061435,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD04",
            },
        [12061435] = {
            ["Content"] = "如果对面是狴犴，飘零人可以去争，可以去反抗。但当面对的是一种看不见摸不着的“大众偏见”的时候，那些激进的手段反而适得其反。",
            ["ContentJP"] = "<Default note=\"text:ビーアン\">狴犴</>みたいに、目に見える敵なら戦える。けど、「世間の偏見」みたいに姿のない相手は……強引な手段じゃ、かえって逆効果になる。",
            ["DialogueId"] = 12061435,
            ["GUID"] = "1E31CD2E",
            ["NextDialogue"] = 12061436,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD2E",
            },
        [12061436] = {
            ["Content"] = "唐叔劝我先等等，但我等不及了。所以我偷偷跑出来，参加了这次群英试。",
            ["ContentJP"] = "タンさんには「今は待て」と言われた。でも、私は待てなかった。だから……内緒で出場したの。",
            ["DialogueId"] = 12061436,
            ["GUID"] = "1E31CD58",
            ["NextDialogue"] = 12061437,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD58",
            },
        [12061437] = {
            ["Content"] = "{nickname}，你说，姑姑如果看到我变得这么任性了，会很失望吗？",
            ["ContentJP"] = "{nickname}……こんなわがままな私を見たら……叔母さん、きっと呆れるよね。",
            ["DialogueId"] = 12061437,
            ["GUID"] = "1E31CD82",
            ["NextOptions"] = {
                [1] = 12061438,
                [2] = 12061439,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CD82",
            },
        [12061438] = {
            ["Content"] = "你不需要一个人扛起所有。",
            ["ContentJP"] = "ひとりで背負わなくていい。",
            ["DialogueId"] = 12061438,
            ["GUID"] = "1E31CDAC",
            ["NextDialogue"] = 12061440,
            },
        [12061439] = {
            ["Content"] = "就算任性也没有关系。",
            ["ContentJP"] = "多少わがままでもいいと思う。",
            ["DialogueId"] = 12061439,
            ["GUID"] = "1E31CDD6",
            ["NextDialogue"] = 12061440,
            },
        [12061440] = {
            ["Content"] = "苏乙，你有时候考虑太多了，其实你可以更加任性一点。",
            ["ContentJP"] = "スーイー、あなたは時々、ひとりで抱え込みすぎだよ。もっと、わがままになってもいい。",
            ["DialogueId"] = 12061440,
            ["GUID"] = "1E31CE00",
            ["NextDialogue"] = 12061441,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE00",
            },
        [12061441] = {
            ["Content"] = "能找到自己的目标并全力以赴去达成它，我觉得这是一件非常非常了不起的事情。",
            ["ContentJP"] = "自分の気持ちを貫くのは、悪いことじゃない。目的を見つけて、それに向かって突き進んでいる。それだけで、すごいことだと思うよ。",
            ["DialogueId"] = 12061441,
            ["GUID"] = "1E31CE2A",
            ["NextDialogue"] = 12061442,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE2A",
            },
        [12061442] = {
            ["Content"] = "姑姑如果能看到现在的你，也一定会为你感到自豪的。",
            ["ContentJP"] = "きっと、叔母さんも……今のあなたを、誇りに思うはず。",
            ["DialogueId"] = 12061442,
            ["GUID"] = "1E31CE54",
            ["NextDialogue"] = 12061443,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE54",
            },
        [12061443] = {
            ["Content"] = "呼……{nickname}，和你聊完后，我感觉神清气爽了好多。",
            ["ContentJP"] = "……ふふ。{nickname}と話してたら、胸のもやもやが少し晴れた気がする。",
            ["DialogueId"] = 12061443,
            ["GUID"] = "1E31CE7E",
            ["NextDialogue"] = 12061444,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CE7E",
            },
        [12061444] = {
            ["Content"] = "我们回去吧，还得想办法和那家伙好好道歉呢。",
            ["ContentJP"] = "さ、戻ろっか。……まずは、ちゃんと謝らなきゃね。あの人に。",
            ["DialogueId"] = 12061444,
            ["GUID"] = "1E31CEA8",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CEA8",
            },
        [12061445] = {
            ["Content"] = "你、你们不要过来！",
            ["ContentJP"] = "や、やめて！こっちに来ないで……！",
            ["DialogueId"] = 12061445,
            ["GUID"] = "1E31CED2",
            ["NextDialogue"] = 12061446,
            ["SpeakNpcId"] = 250017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CED2",
            },
        [12061446] = {
            ["Content"] = "好像有孩子的求救声？！{nickname}，我们赶紧过去看看！",
            ["ContentJP"] = "……今、子どもの叫び声がしなかった！？{nickname}、行ってみよう！",
            ["DialogueId"] = 12061446,
            ["GUID"] = "1E31CEFC",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120614/1E31CEFC",
            },
        [12061501] = {
            ["Content"] = "小朋友，你还好吗，有没有哪里受伤？",
            ["ContentJP"] = "あんた大丈夫？怪我してない？",
            ["DialogueId"] = 12061501,
            ["GUID"] = "1E31D802",
            ["NextDialogue"] = 12061502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D802",
            },
        [12061502] = {
            ["Content"] = "小安没事，谢谢大姐姐！",
            ["ContentJP"] = "うんっ、平気だよ！お姉ちゃん、ありがとう！",
            ["DialogueId"] = 12061502,
            ["GUID"] = "1E31D82C",
            ["NextDialogue"] = 12061503,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D82C",
            },
        [12061503] = {
            ["Content"] = "外面危险，小朋友还是不要乱跑啦。之前大乱的影响还没完全消失，等到玄色狴犴都被扫除后，小安才能出来走动哦。",
            ["ContentJP"] = "外はまだ危ないからね、あんまりひとりでうろうろしちゃダメだよ。この前の混乱の影響も、まだ完全には収まってないし……<Default note=\"text:ゲンビー\">玄狴</>が全部片付くまで、お出かけは我慢しようね。",
            ["DialogueId"] = 12061503,
            ["GUID"] = "1E31D856",
            ["NextDialogue"] = 12061504,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D856",
            },
        [12061504] = {
            ["Content"] = "小安！小安，你在那里吗？！",
            ["ContentJP"] = "アン――！どこだ！？",
            ["DialogueId"] = 12061504,
            ["GUID"] = "1E31D880",
            ["NextDialogue"] = 12061505,
            ["SpeakNpcId"] = 250018,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D880",
            },
        [12061505] = {
            ["Content"] = "你这孩子，明明腿有旧疾，怎么还非要跑出来……",
            ["ContentJP"] = "……この子ったら、足に持病があるっていうのに、どうして外なんかに――！",
            ["DialogueId"] = 12061505,
            ["GUID"] = "1E31D8AA",
            ["NextDialogue"] = 12061506,
            ["SpeakNpcId"] = 250018,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D8AA",
            },
        [12061506] = {
            ["Content"] = "对不起，小安错了……",
            ["ContentJP"] = "ごめんなさい……",
            ["DialogueId"] = 12061506,
            ["GUID"] = "1E31D8D4",
            ["NextDialogue"] = 12061518,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D8D4",
            },
        [12061507] = {
            ["Content"] = "是你们救了小安吗？在下潇湘，目前于天梁司当职，以后若有要事，我定当回报。",
            ["ContentJP"] = "あなたたちがアンを助けてくれたのね？私はショウ、<Default note=\"text:てんりょうし\">天梁司</>で働いてるの。何か困ったことがいつでもいらっしゃい。",
            ["DialogueId"] = 12061507,
            ["GUID"] = "1E31D8FE",
            ["NextDialogue"] = 12061508,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D8FE",
            },
        [12061508] = {
            ["Content"] = "举手之劳啦，不用放在心上。倒是小安的腿怎么了？",
            ["ContentJP"] = "たいしたことじゃないよ、困ってる子がいたら助けるのが当然でしょ。それより……アンの足、どうした{性别:んだ|の}？",
            ["DialogueId"] = 12061508,
            ["GUID"] = "1E31D928",
            ["NextDialogue"] = 12061509,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D928",
            },
        [12061509] = {
            ["Content"] = "……小安小时候曾经被卷入一场事故。",
            ["ContentJP"] = "……アンは幼いころ、大きな事故に巻き込まれまして。",
            ["DialogueId"] = 12061509,
            ["GUID"] = "1E31D952",
            ["NextDialogue"] = 12061510,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D952",
            },
        [12061510] = {
            ["Content"] = "那场事故不仅让他落下了腿疾，还令他失去了父母，只能由我代为抚养。所以我一直对这孩子放不下心来。",
            ["ContentJP"] = "そのせいで足を痛めただけでなく、両親も……亡くしました。以来、私がこの子を育ててきたんです。だから、つい心配しすぎてしまって……",
            ["DialogueId"] = 12061510,
            ["GUID"] = "1E31D97C",
            ["NextDialogue"] = 12061511,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D97C",
            },
        [12061511] = {
            ["Content"] = "阿姨别再想那些伤心事了！小安有阿姨养大，所以小安非常幸福！",
            ["ContentJP"] = "おばさん、もう悲しいこと考えないで！アン、おばさんに育ててもらえて、すっごく幸せだよ！",
            ["DialogueId"] = 12061511,
            ["GUID"] = "1E31D9A6",
            ["NextDialogue"] = 12061512,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D9A6",
            },
        [12061512] = {
            ["Content"] = "……你这孩子。",
            ["ContentJP"] = "……本当に、この子は。",
            ["DialogueId"] = 12061512,
            ["GUID"] = "1E31D9D0",
            ["NextDialogue"] = 12061513,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D9D0",
            },
        [12061513] = {
            ["Content"] = "看来小安很喜欢你呢，我能感受到他的这些话是发自内心的。",
            ["ContentJP"] = "ふふ……アンくん、あんたのことが大好きなんですね。今の言葉、全部本心だって伝わってきます。",
            ["DialogueId"] = 12061513,
            ["GUID"] = "1E31D9FA",
            ["NextDialogue"] = 12061514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31D9FA",
            },
        [12061514] = {
            ["Content"] = "多谢二位了。比赛快要开始，就不耽误你们时间了。我家就在那座屋舍，二位若有机会一定要去坐坐。",
            ["ContentJP"] = "……ありがとうございます。まもなく試合も始まりますし、これ以上お引き止めはしません。あの屋敷が我が家です。今度、ぜひ立ち寄ってください。",
            ["DialogueId"] = 12061514,
            ["GUID"] = "1E31DA24",
            ["NextDialogue"] = 12061515,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DA24",
            },
        [12061515] = {
            ["Content"] = "没事，你快带小安回去吧。",
            ["ContentJP"] = "うん。さあ、アンを連れて、早く帰ってあげて。",
            ["DialogueId"] = 12061515,
            ["GUID"] = "1E31DA4E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DA4E",
            },
        [12061516] = {
            ["Content"] = "他们的相处方式，有点让我想起曾经的我和姑姑……",
            ["ContentJP"] = "……あの二人の関係、少しだけ、昔の私と叔母を思い出すわ。",
            ["DialogueId"] = 12061516,
            ["GUID"] = "1E31DA78",
            ["NextDialogue"] = 12061517,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DA78",
            },
        [12061517] = {
            ["Content"] = "小安的心愿，一定是能一直一直和他的阿姨待在一起吧。就像当初的我一样……",
            ["ContentJP"] = "アンくんの願いは、きっと――ずっと、ずっと、あの人と一緒にいること。……かつての私と、同じだ。",
            ["DialogueId"] = 12061517,
            ["GUID"] = "1E31DAA2",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DAA2",
            },
        [12061518] = {
            ["Content"] = "在赶来的女子的帮助下，小安略显吃力地站了起来。",
            ["DialogueId"] = 12061518,
            ["GUID"] = "1E31DAA3",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 12061507,
            ["VoiceName"] = "voice/$Locale$/story/1206/120615/1E31DAA3",
            },
        [12061601] = {
            ["Content"] = "小仆从，你回来了！咳咳，“那件事情”办的怎么样了？",
            ["ContentJP"] = "おお、下僕！戻ってきたか！……こほん。――で、「あの件」はどうなった？（もったいぶった調子で）",
            ["DialogueId"] = 12061601,
            ["GUID"] = "1E31E86A",
            ["NextDialogue"] = 12061602,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E86A",
            },
        [12061602] = {
            ["Content"] = "如果顺利，你就眨眨眼。要是遇到什么问题需要白出马，你就……嗯，不如高呼“魔王大人万岁”吧！",
            ["ContentJP"] = "順調ならウィンクして。このスノウ様の口だしが必要なら……そうだな、「魔王さま万歳！」って高らかに叫ぶといいぞ！",
            ["DialogueId"] = 12061602,
            ["GUID"] = "1E31E894",
            ["NextDialogue"] = 12061603,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E894",
            },
        [12061603] = {
            ["Content"] = "白……你说话怎么也这么拐弯抹角了。放心，苏乙的心情已经平复下来了，她是回来找煜明道歉的。",
            ["ContentJP"] = "スノウ……なんで君まで回りくどくなってるんだ。大丈夫だよ。スーイーはもう落ち着いた。ユーミンにちゃんと謝りに戻ってきたんだよ。",
            ["DialogueId"] = 12061603,
            ["GUID"] = "1E31E8BE",
            ["NextDialogue"] = 12061604,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E8BE",
            },
        [12061604] = {
            ["Content"] = "呼……那就好那就好！",
            ["ContentJP"] = "ふぅ……それならよし！",
            ["DialogueId"] = 12061604,
            ["GUID"] = "1E31E8E8",
            ["NextDialogue"] = 12061605,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E8E8",
            },
        [12061605] = {
            ["Content"] = "苏乙，你是不是有话要和煜明说？去吧，他就在那里。",
            ["ContentJP"] = "ほら、スーイー、ユーミンに話があるん{性别:だろう|でしょ}？",
            ["DialogueId"] = 12061605,
            ["GUID"] = "1E31E912",
            ["NextDialogue"] = 12061624,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E912",
            },
        [12061606] = {
            ["Content"] = "抱歉，煜明。你明明在紧急时刻帮了我，我却没有对你表达感谢，甚至反过来说了些很过分的话……真的非常非常对不起！",
            ["ContentJP"] = "……ごめんなさい、ユーミン。あんたはあの緊急の場面で私を助けてくれたのに、感謝も伝えられず、ひどい言葉まで投げつけてしまった。本当に……ごめんなさい！",
            ["DialogueId"] = 12061606,
            ["GUID"] = "1E31E93C",
            ["NextDialogue"] = 12061607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E93C",
            },
        [12061607] = {
            ["Content"] = "无妨，只是些许龃龉，我并未介怀。",
            ["ContentJP"] = "気にするな。些細な行き違いだ。俺は何とも思っていない。",
            ["DialogueId"] = 12061607,
            ["GUID"] = "1E31E966",
            ["NextDialogue"] = 12061608,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E966",
            },
        [12061608] = {
            ["Content"] = "但是，我还有一件很重要的事情要对你说……就算你不认可，我也必须告诉你。",
            ["ContentJP"] = "……でも、もう一つ。どうしても、伝えなければならないことがあるの。あんたが認めてくれなくても、言わせて。",
            ["DialogueId"] = 12061608,
            ["GUID"] = "1E31E990",
            ["NextDialogue"] = 12061609,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E990",
            },
        [12061609] = {
            ["Content"] = "我是绝对不会放弃为姑姑正名的！就算遇到多少阻挠，经历多少困难，我也想向世人证明她的理念。",
            ["ContentJP"] = "私は、叔母――ムーチョの汚名を晴らす。何度止められても、どれほど困難があっても、彼女の理念が間違っていなかったと、世の中に証明したい。",
            ["DialogueId"] = 12061609,
            ["GUID"] = "1E31E9BA",
            ["NextDialogue"] = 12061610,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E9BA",
            },
        [12061610] = {
            ["Content"] = "只有这件事情，我绝对绝对不能让步。所以只能再说一次对不起了！",
            ["ContentJP"] = "このことだけは……どうしても譲れない。もう一度だけ言うわ、ごめん！",
            ["DialogueId"] = 12061610,
            ["GUID"] = "1E31E9E4",
            ["NextDialogue"] = 12061611,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31E9E4",
            },
        [12061611] = {
            ["Content"] = "苏乙，先前已经说了，这件事你可能有所误解。我并未否定你为苏暮鹧正名的目标。",
            ["ContentJP"] = "スーイー。先ほども言ったが、この件について、あんたを否定した覚えはない。",
            ["DialogueId"] = 12061611,
            ["GUID"] = "1E31EA0E",
            ["NextDialogue"] = 12061612,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA0E",
            },
        [12061612] = {
            ["Content"] = "更何况，我并没有资格阻挠你。放弃的代价，没有人比我更加清楚。",
            ["ContentJP"] = "それに――あんたを止める資格が、俺にあるとも思っていない。「諦める」という選択の重さは、誰よりも知っている。",
            ["DialogueId"] = 12061612,
            ["GUID"] = "1E31EA38",
            ["NextDialogue"] = 12061613,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA38",
            },
        [12061613] = {
            ["Content"] = "……谢谢你能理解我。",
            ["ContentJP"] = "……理解してくれて、ありがとう。",
            ["DialogueId"] = 12061613,
            ["GUID"] = "1E31EA62",
            ["NextDialogue"] = 12061614,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA62",
            },
        [12061614] = {
            ["Content"] = "既然你已认清此心所向，煜明定将尽己所能，竭力助你拿下赛事冠军。",
            ["ContentJP"] = "己の進む道を定めたのなら。全力で支えよう。必ず、あんたを優勝へ導く。",
            ["DialogueId"] = 12061614,
            ["GUID"] = "1E31EA8C",
            ["NextDialogue"] = 12061615,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EA8C",
            },
        [12061615] = {
            ["Content"] = "还有我。",
            ["ContentJP"] = "{性别:僕|私}も。",
            ["DialogueId"] = 12061615,
            ["GUID"] = "1E31EAB6",
            ["NextDialogue"] = 12061616,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EAB6",
            },
        [12061616] = {
            ["Content"] = "到了夺冠的时候，我会站在你身边，让你的姑姑看到小苏现在已经有了这么多朋友。这样她在九泉之下也能安心了。",
            ["ContentJP"] = "優勝までそばにいるよ。あなたの叔母もスーイーにこんな頼れる仲間がいるって知れば、安心できる{性别:だろう|でしょ}。",
            ["DialogueId"] = 12061616,
            ["GUID"] = "1E31EAE0",
            ["NextDialogue"] = 12061617,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EAE0",
            },
        [12061617] = {
            ["Content"] = "这种时候自然也少不了魔王大人的身影！包在我和小仆从身上吧！",
            ["ContentJP"] = "ふふん！この魔王さまを忘れてもらっちゃ困るね！我が下僕と二人で、しっかり支えてやるさ！",
            ["DialogueId"] = 12061617,
            ["GUID"] = "1E31EB0A",
            ["NextDialogue"] = 12061618,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB0A",
            },
        [12061618] = {
            ["Content"] = "大家……有你们真好！",
            ["ContentJP"] = "……みんな。ほんとに……ありがと。",
            ["DialogueId"] = 12061618,
            ["GUID"] = "1E31EB34",
            ["NextDialogue"] = 12061619,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB34",
            },
        [12061619] = {
            ["Content"] = "这种时候再说谢谢好像有点见外了，我们还是赶紧进入赛场吧！",
            ["ContentJP"] = "今さら「ありがとう」なんて言うのも、ちょっとよそよそしいよね。よし、そろそろ会場に戻ろっか！",
            ["DialogueId"] = 12061619,
            ["GUID"] = "1E31EB5E",
            ["NextDialogue"] = 12061625,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB5E",
            },
        [12061620] = {
            ["Content"] = "“姑姑”……",
            ["ContentJP"] = "「叔母」、ね……",
            ["DialogueId"] = 12061620,
            ["GUID"] = "1E31EB88",
            ["NextDialogue"] = 12061621,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EB88",
            },
        [12061621] = {
            ["Content"] = "苏暮鹧……你曾经天天挂在嘴边的侄女，现在也已经长这么大了啊。",
            ["ContentJP"] = "ムーチョ……あんたがいつも口にしてた姪っ子ちゃん、もうあんなに大きくなって……",
            ["DialogueId"] = 12061621,
            ["GUID"] = "1E31EBB2",
            ["NextDialogue"] = 12061622,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EBB2",
            },
        [12061622] = {
            ["Content"] = "和当年的你一样聪明、骄傲，以及……恬不知耻。",
            ["ContentJP"] = "頭が良くて、誇り高くて……それから、図々しいところまで、そっくり。",
            ["DialogueId"] = 12061622,
            ["GUID"] = "1E31EBDC",
            ["NextDialogue"] = 12061623,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EBDC",
            },
        [12061623] = {
            ["Content"] = "在这种时候认出她，这是命运对你我的安排吗……",
            ["ContentJP"] = "こんな時にあの子と出会うなんて……ふふ……これも、あんたと私の因縁ってやつかね。",
            ["DialogueId"] = 12061623,
            ["GUID"] = "1E31EC06",
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120616/1E31EC06",
            },
        [12061624] = {
            ["DialogueId"] = 12061624,
            ["GUID"] = "1E31E913",
            ["NextDialogue"] = 12061606,
            },
        [12061625] = {
            ["DialogueId"] = 12061625,
            ["GUID"] = "1E31EB5F",
            ["NextDialogue"] = 12061620,
            },
        [12061701] = {
            ["Content"] = "呼……今天的赛事告一段落了。干得不错！如果明天能继续保持这个节奏，夺冠绝对是板上钉钉的事情！",
            ["ContentJP"] = "ふぅ……今日の試合はここまでだね。よくやったよ、みんな！明日もこの調子で行けたら、優勝確定ね！",
            ["DialogueId"] = 12061701,
            ["GUID"] = "1E31F8D2",
            ["NextDialogue"] = 12061702,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203004,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F8D2",
            },
        [12061702] = {
            ["Content"] = "不负所望。",
            ["ContentJP"] = "期待に応えられたようで。",
            ["DialogueId"] = 12061702,
            ["GUID"] = "1E31F8FC",
            ["NextDialogue"] = 12061703,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F8FC",
            },
        [12061703] = {
            ["Content"] = "是不是该开始想获胜致辞该怎么说了？你好，我是苏乙，今天很荣幸能站在这里……",
            ["ContentJP"] = "優勝スピーチでも考えとく？「えー、本日はこのような素晴らしい舞台に立てて光栄です……」ってさ……（笑）",
            ["DialogueId"] = 12061703,
            ["GUID"] = "1E31F926",
            ["NextDialogue"] = 12061744,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F926",
            },
        [12061704] = {
            ["Content"] = "小仆从小仆从，你们终于出来了！那个，赛场氛围好像有点不太对劲……",
            ["ContentJP"] = "我が下僕！ようやく終わったんだね！あのさ、ちょっと会場の空気が……なんか変なんだけど！",
            ["DialogueId"] = 12061704,
            ["GUID"] = "1E31F950",
            ["NextDialogue"] = 12061705,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F950",
            },
        [12061705] = {
            ["Content"] = "发生什么了？",
            ["ContentJP"] = "何があったの？",
            ["DialogueId"] = 12061705,
            ["GUID"] = "1E31F97A",
            ["NextDialogue"] = 12061745,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F97A",
            },
        [12061706] = {
            ["Content"] = "喂喂，听说有飘零人混入了比赛，是真的吗……？",
            ["ContentJP"] = "ねぇねぇ、流れ者が試合に紛れ込んでるって本当？",
            ["DialogueId"] = 12061706,
            ["GUID"] = "1E31F9A4",
            ["NextDialogue"] = 12061707,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F9A4",
            },
        [12061707] = {
            ["Content"] = "飘零人？那些传说中青面獠牙，手持大棒的恶棍？他们该不会是专门趁这个风云变幻的时机，来搞什么破坏的吧？",
            ["ContentJP"] = "流れ者？あの、顔が青くて牙むいてて、棍棒持ってるって噂の連中？まさかこのタイミングで暴れに来たんじゃ……",
            ["DialogueId"] = 12061707,
            ["GUID"] = "1E31F9CE",
            ["NextDialogue"] = 12061708,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F9CE",
            },
        [12061708] = {
            ["Content"] = "原来飘零人这么可怕吗，我还只在小说话本中看到过呢……",
            ["ContentJP"] = "怖っ……本でしか見たことなかったけど、マジでいたんだ……",
            ["DialogueId"] = 12061708,
            ["GUID"] = "1E31F9F8",
            ["NextDialogue"] = 12061709,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31F9F8",
            },
        [12061709] = {
            ["Content"] = "我倒是也听说过飘零人行侠仗义的故事……不过创作归创作，在现实中果然还是不想遇到这些人。",
            ["ContentJP"] = "でもさ、流れ者が義を重んじるって話も聞いたことあるよ？とはいえ……やっぱり実際に出くわすのはちょっと……",
            ["DialogueId"] = 12061709,
            ["GUID"] = "1E31FA22",
            ["NextDialogue"] = 12061710,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FA22",
            },
        [12061710] = {
            ["Content"] = "虽然不知道是怎么一回事，小仆从，你说我们要不要赶紧离开这里，暂时避一避风头——",
            ["ContentJP"] = "な、なんだかヤバそうだよね……今日のところは、いったん引こうか？今は目立たないほうが——",
            ["DialogueId"] = 12061710,
            ["GUID"] = "1E31FA4C",
            ["NextDialogue"] = 12061746,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FA4C",
            },
        [12061711] = {
            ["Content"] = "——呀，长官，我们是良民，我们什么都没说！",
            ["ContentJP"] = "——ひぃっ！ち、長官！？私たちは善良な一般市民だぞ！なんにも言ってないからなっ！",
            ["DialogueId"] = 12061711,
            ["GUID"] = "1E31FA76",
            ["NextDialogue"] = 12061712,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FA76",
            },
        [12061712] = {
            ["Content"] = "不必惊慌。{nickname}是华胥的贵客，{性别：他|她}的同伴也需恭敬以待，此乃太皓的意志。",
            ["ContentJP"] = "ご心配なく。{nickname}{性别：様|様}は我らが<Default note=\"text:カショ\">華胥</>の貴客。そのご一行も同様に敬意を払うよう、<Default note=\"text:たいこう\">太皓</>さまより仰せつかっております。",
            ["DialogueId"] = 12061712,
            ["GUID"] = "1E31FAA0",
            ["NextDialogue"] = 12061713,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FAA0",
            },
        [12061713] = {
            ["Content"] = "但仍有一事需叨扰几位——请问是苏乙姑娘吗？",
            ["ContentJP"] = "ただ、ひとつだけ確認が。……スーイーさんで間違いないでしょうか？",
            ["DialogueId"] = 12061713,
            ["GUID"] = "1E31FACA",
            ["NextDialogue"] = 12061714,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FACA",
            },
        [12061714] = {
            ["Content"] = "正是我。什么事？",
            ["ContentJP"] = "そうだけど。何？",
            ["DialogueId"] = 12061714,
            ["GUID"] = "1E31FAF4",
            ["NextDialogue"] = 12061715,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FAF4",
            },
        [12061715] = {
            ["Content"] = "我们收到检举消息，有人怀疑你用于参赛的机傀不合用例，需要接受检查。抱歉，这是例行手续。",
            ["ContentJP"] = "匿名の通報がありまして。あなたの使用するからくりがルールに抵触しているのではないかと。申し訳ありませんが、規定により調査が必要になります。",
            ["DialogueId"] = 12061715,
            ["GUID"] = "1E31FB1E",
            ["NextDialogue"] = 12061716,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB1E",
            },
        [12061716] = {
            ["Content"] = "原来是她！",
            ["ContentJP"] = "あの子が……！（ひそひそ）",
            ["DialogueId"] = 12061716,
            ["GUID"] = "1E31FB48",
            ["NextDialogue"] = 12061717,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB48",
            },
        [12061717] = {
            ["Content"] = "看着文文弱弱一个小姑娘，没想到竟然是传说中的飘零人……但好像也没有传说中的那么可怕？",
            ["ContentJP"] = "えっ、あんな華奢な子が流れ者？……話で聞いてたよりずっと……普通だな……（ひそひそ）",
            ["DialogueId"] = 12061717,
            ["GUID"] = "1E31FB72",
            ["NextDialogue"] = 12061718,
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB72",
            },
        [12061718] = {
            ["Content"] = "我的青鸾贰型？喏，拿去吧。",
            ["ContentJP"] = "<Default note=\"text:せいほう\">青鳳</>二型のことね。ほら、これよ。",
            ["DialogueId"] = 12061718,
            ["GUID"] = "1E31FB9C",
            ["NextDialogue"] = 12061719,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FB9C",
            },
        [12061719] = {
            ["Content"] = "事先说好，我对照过本次赛事的条例，制作手法是百分百合规的。你们可以尽管检查。但请不要破坏它的结构，这其中每个零件都是机傀师的心血。",
            ["ContentJP"] = "言っとくけど、今回のレギュレーションに沿って作ってるから。好きなだけ調べていいけど、壊さないでよね。どのパーツも、からくり師の命かけて組んでるんだから。",
            ["DialogueId"] = 12061719,
            ["GUID"] = "1E31FBC6",
            ["NextDialogue"] = 12061720,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FBC6",
            },
        [12061720] = {
            ["Content"] = "感谢您的配合。这机傀由司事会代为保管，明早赛前即可交还，您请放心。",
            ["ContentJP"] = "ご協力ありがとうございます。こちらでお預かりして、明日の試合前にお返ししますのでご安心を。",
            ["DialogueId"] = 12061720,
            ["GUID"] = "1E31FBF0",
            ["NextDialogue"] = 12061747,
            ["SpeakNpcId"] = 250030,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FBF0",
            },
        [12061721] = {
            ["Content"] = "合规？这就是你们飘零人用以伪饰自己行为的借口吗？",
            ["ContentJP"] = "よく言うぜ。そんなの流れ者の常套句だ。自らの悪事を覆い隠すためのな。",
            ["DialogueId"] = 12061721,
            ["GUID"] = "1E31FC1A",
            ["NextDialogue"] = 12061722,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC1A",
            },
        [12061722] = {
            ["Content"] = "怎么还是你？阴魂不散的。这检举该不会也是你干的吧？",
            ["ContentJP"] = "またあんたか。ほんとしつこいわね。その通報も……あんたの仕業でしょ？",
            ["DialogueId"] = 12061722,
            ["GUID"] = "1E31FC44",
            ["NextDialogue"] = 12061723,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC44",
            },
        [12061723] = {
            ["Content"] = "呵，先前与你打了几次照面，我早就有所预感。本以为你们这些不法之徒只敢像老鼠一样躲在大风九章的缝隙中，如今却敢混入奉香大典，不知有何企图。",
            ["ContentJP"] = "ふん、これまで何度か顔を合わせてわかったよ。こういう連中は、普段は陰に潜んで牙を研ぐだけかと思ってたが……まさか、<Default note=\"text:ほうこうのぎ\">奉香の儀</>にまで潜り込むとはな。",
            ["DialogueId"] = 12061723,
            ["GUID"] = "1E31FC6E",
            ["NextDialogue"] = 12061724,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC6E",
            },
        [12061724] = {
            ["Content"] = "若非有人明确指出你的身份，恐怕大家到现在还蒙在鼓里。",
            ["ContentJP"] = "身元を暴露されなければ、今も周囲を欺いていたことだろう。",
            ["DialogueId"] = 12061724,
            ["GUID"] = "1E31FC98",
            ["NextDialogue"] = 12061725,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FC98",
            },
        [12061725] = {
            ["Content"] = "本姑娘行得端做得正，从未刻意掩饰过自己的身份，只是没有特意说出来的必要罢了。",
            ["ContentJP"] = "私はやましいことなんかしてない。正々堂々と来たわ。それをわざわざ言いふらす必要がなかっただけ。",
            ["DialogueId"] = 12061725,
            ["GUID"] = "1E31FCC2",
            ["NextDialogue"] = 12061726,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FCC2",
            },
        [12061726] = {
            ["Content"] = "说到底，飘零人怎么你了？",
            ["ContentJP"] = "ていうか、流れ者が何したっていうの？",
            ["DialogueId"] = 12061726,
            ["GUID"] = "1E31FCEC",
            ["NextDialogue"] = 12061727,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FCEC",
            },
        [12061727] = {
            ["Content"] = "……飘零人怎么我了？前辈犯下的累累恶行竟被你说的如此轻巧。你们作恶多端，谁人不知？还需要我细数你们的一桩桩罪行吗？",
            ["ContentJP"] = "「何をしたか」だと？前代の連中がどれだけの罪を犯したか、忘れたとでも？あの数々の蛮行、列挙してやろうか？",
            ["DialogueId"] = 12061727,
            ["GUID"] = "1E31FD16",
            ["NextDialogue"] = 12061728,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD16",
            },
        [12061728] = {
            ["Content"] = "那些以讹传讹、捉风捕影的罪行？你说再多又能证明什么？",
            ["ContentJP"] = "それ、ただの噂とデマでしょ。そんなの持ち出して、何が証明できるの？",
            ["DialogueId"] = 12061728,
            ["GUID"] = "1E31FD40",
            ["NextDialogue"] = 12061729,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD40",
            },
        [12061729] = {
            ["Content"] = "（喧闹的议论声。）",
            ["ContentJP"] = "観衆がざわつく",
            ["DialogueId"] = 12061729,
            ["GUID"] = "1E31FD6A",
            ["NextDialogue"] = 12061748,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD6A",
            },
        [12061730] = {
            ["Content"] = "我还以为何事引起嘈杂，原来是选手之间有些误会。",
            ["ContentJP"] = "……騒がしいと思えば、どうやら選手間の認識に食い違いがあったようね。",
            ["DialogueId"] = 12061730,
            ["GUID"] = "1E31FD94",
            ["NextDialogue"] = 12061731,
            ["RelatedWikiId"] = {
                [1] = 203001,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FD94",
            },
        [12061731] = {
            ["Content"] = "止流……？",
            ["ContentJP"] = "シリュウさん……？",
            ["DialogueId"] = 12061731,
            ["GUID"] = "1E31FDBE",
            ["NextDialogue"] = 12061732,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FDBE",
            },
        [12061732] = {
            ["Content"] = "……我听闻那起风波后，现任龙渊上卿引起诸多非议，已经被迫请辞在家。这件事，恐怕不适合阁下来横插一脚吧？",
            ["ContentJP"] = "……聞き及んでますよ。<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>は先の騒動で非難を浴び、すでに辞職されたと。今はもう、立ち入る資格などないのでは？",
            ["DialogueId"] = 12061732,
            ["GUID"] = "1E31FDE8",
            ["NextDialogue"] = 12061733,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FDE8",
            },
        }
  end },
  { MinKey = 12061733, MaxKey = 12062517, Loader = function()
      return {
        [12061733] = {
            ["Content"] = "呵呵……很不巧，我虽已不是龙渊上卿，却仍肩负本次奉香群英试的协理职责。因而我依然有在这里发言的位置。",
            ["ContentJP"] = "あいにくだけど、私は今回の英雄大会において「協力」の任を負っているの。発言の権利も、まだ持ってるわ。",
            ["DialogueId"] = 12061733,
            ["GUID"] = "1E31FE12",
            ["NextDialogue"] = 12061734,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE12",
            },
        [12061734] = {
            ["Content"] = "诸位的担忧我已知晓，即便是飘零人，也仍是我华胥民众。大风九章已既往不咎，若无作奸犯科之实，他们参加群英试并无不可。",
            ["ContentJP"] = "皆さまの不安も理解します。ですが、流れ者もまた、我が<Default note=\"text:カショ\">華胥</>の民。<Default note=\"text:たいふうきゅうしょう\">大風九章</>により、過去は問われないとされています。よって、彼らが試合に出ること自体に問題はありません。",
            ["DialogueId"] = 12061734,
            ["GUID"] = "1E31FE3C",
            ["NextDialogue"] = 12061735,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE3C",
            },
        [12061735] = {
            ["Content"] = "如今太皓神君已将裁决定夺之权重新托付于众人。因而诸位更要以自己的双眼去判定何者为伪，何者为真。",
            ["ContentJP"] = "いま<Default note=\"text:たいこう\">太皓</>様は、決断を「人々の目」に託されました。ならば皆さま自身の目で、誰が真で誰が偽かを見極めるべきでは？",
            ["DialogueId"] = 12061735,
            ["GUID"] = "1E31FE66",
            ["NextDialogue"] = 12061736,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE66",
            },
        [12061736] = {
            ["Content"] = "在尚无证据之时就去断定这位苏乙姑娘居心叵测，恐怕有失偏颇吧？",
            ["ContentJP"] = "証拠もないままに、スーイーさんを悪し様に断ずるのは、いささか早計では？",
            ["DialogueId"] = 12061736,
            ["GUID"] = "1E31FE90",
            ["NextDialogue"] = 12061737,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FE90",
            },
        [12061737] = {
            ["Content"] = "哼，我没有证据不假。但总不能就此放任这些目无法纪的狂徒继续在这里招摇过市！要是纵容其人犯下罪行，到时候证据倒是确凿，可为时已晚了。",
            ["ContentJP"] = "証拠がない？だからといって野放しにするのか？あとから何かあっても遅い。手遅れになってからじゃ、何の意味もないんだ！",
            ["DialogueId"] = 12061737,
            ["GUID"] = "1E31FEBA",
            ["NextDialogue"] = 12061738,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FEBA",
            },
        [12061738] = {
            ["Content"] = "嗯，你的担忧也不无道理。",
            ["ContentJP"] = "……その懸念も、もっともです。",
            ["DialogueId"] = 12061738,
            ["GUID"] = "1E31FEE4",
            ["NextDialogue"] = 12061739,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FEE4",
            },
        [12061739] = {
            ["Content"] = "喂喂，怎么突然向着那家伙说话了……！",
            ["ContentJP"] = "えっ、今度はそっちの味方！？",
            ["DialogueId"] = 12061739,
            ["GUID"] = "1E31FF0E",
            ["NextDialogue"] = 12061740,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF0E",
            },
        [12061740] = {
            ["Content"] = "赛事安全是本届群英试的重中之重，任何潜在的隐患都会引起重视。",
            ["ContentJP"] = "今回の試合では、安全こそが最優先事項。いかなる火種も、見逃すわけにはいきません。",
            ["DialogueId"] = 12061740,
            ["GUID"] = "1E31FF38",
            ["NextDialogue"] = 12061741,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF38",
            },
        [12061741] = {
            ["Content"] = "所以眼下还请几位随我走一遭，配合官方调查。在场的各位还请稍安勿躁，之后定会给诸位一个交代。",
            ["ContentJP"] = "よって、同行をお願いできますか。調査にご協力を。会場の皆さまはどうかご心配なく、後ほど必ずご報告いたします。",
            ["DialogueId"] = 12061741,
            ["GUID"] = "1E31FF62",
            ["NextDialogue"] = 12061742,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF62",
            },
        [12061742] = {
            ["Content"] = "苏乙姑娘，没问题吧？",
            ["ContentJP"] = "スーイーさん……よろしいでしょうか？",
            ["DialogueId"] = 12061742,
            ["GUID"] = "1E31FF8C",
            ["NextDialogue"] = 12061743,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FF8C",
            },
        [12061743] = {
            ["Content"] = "……知道了，依你便是。",
            ["ContentJP"] = "……わかったわ。",
            ["DialogueId"] = 12061743,
            ["GUID"] = "1E31FFB6",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120617/1E31FFB6",
            },
        [12061744] = {
            ["DialogueId"] = 12061744,
            ["GUID"] = "1E31FFB7",
            ["NextDialogue"] = 12061704,
            },
        [12061745] = {
            ["DialogueId"] = 12061745,
            ["GUID"] = "1E31FFB8",
            ["NextDialogue"] = 12061706,
            },
        [12061746] = {
            ["DialogueId"] = 12061746,
            ["GUID"] = "1E31FFB9",
            ["NextDialogue"] = 12061711,
            },
        [12061747] = {
            ["DialogueId"] = 12061747,
            ["GUID"] = "1E31FFBA",
            ["NextDialogue"] = 12061721,
            },
        [12061748] = {
            ["DialogueId"] = 12061748,
            ["GUID"] = "1E31FFBB",
            ["NextDialogue"] = 12061730,
            },
        [12061801] = {
            ["Content"] = "到这里应该就可以敞开说话了。",
            ["ContentJP"] = "……このあたりなら、腹を割って話せそうね。",
            ["DialogueId"] = 12061801,
            ["GUID"] = "1E32093A",
            ["NextDialogue"] = 12061802,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203001,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E32093A",
            },
        [12061802] = {
            ["Content"] = "抱歉，几位。刚刚的场合，即便是我也无法为苏乙姑娘进行担保，只能出此下策。",
            ["ContentJP"] = "さっきは……ごめんなさい。あの場では、私にもどうすることもできなかったの。だから、あんな形でしか動けなかった。",
            ["DialogueId"] = 12061802,
            ["GUID"] = "1E320964",
            ["NextDialogue"] = 12061803,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320964",
            },
        [12061803] = {
            ["Content"] = "原、原来是这样啊，那是白错怪你了。",
            ["ContentJP"] = "な、なるほど～！てっきり裏切られたかと……！",
            ["DialogueId"] = 12061803,
            ["GUID"] = "1E32098E",
            ["NextDialogue"] = 12061804,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E32098E",
            },
        [12061804] = {
            ["Content"] = "……可以理解。",
            ["ContentJP"] = "……ううん、気にしてない。",
            ["DialogueId"] = 12061804,
            ["GUID"] = "1E3209B8",
            ["NextDialogue"] = 12061805,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E3209B8",
            },
        [12061805] = {
            ["Content"] = "对这种情况我早有预料，就算不被认可也没关系，我只为获胜而来。",
            ["ContentJP"] = "こんなこと、最初から想像ついてたし。別に誰にどう思われてもいい。私は、勝ちに来ただけだから。",
            ["DialogueId"] = 12061805,
            ["GUID"] = "1E3209E2",
            ["NextDialogue"] = 12061806,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E3209E2",
            },
        [12061806] = {
            ["Content"] = "止流，谢谢你出现得这么及时，为我们解围。",
            ["ContentJP"] = "シリュウさん、助けてくれてありがとう。あのままいがみ合ってたら、どうなってたか……",
            ["DialogueId"] = 12061806,
            ["GUID"] = "1E320A0C",
            ["NextDialogue"] = 12061807,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A0C",
            },
        [12061807] = {
            ["Content"] = "呵呵……从你报名那刻起，我就一直关注着你们。",
            ["ContentJP"] = "ふふ……エントリーした時から、あなたたちのこと、ずっと見てたのよ。",
            ["DialogueId"] = 12061807,
            ["GUID"] = "1E320A36",
            ["NextDialogue"] = 12061808,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A36",
            },
        [12061808] = {
            ["Content"] = "本届群英试意义特殊。作为风波平息之后的首次大典，它被寄予了平定民心、彰显“人”之力量的厚望。",
            ["ContentJP"] = "今回の英雄大会は、これまでとは違う。事件のあと初めての式典で、民の心を静めて、「人の力」を示す場でもあるの。",
            ["DialogueId"] = 12061808,
            ["GUID"] = "1E320A60",
            ["NextDialogue"] = 12061809,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A60",
            },
        [12061809] = {
            ["Content"] = "昔日华胥人习惯于依靠太皓一成不变的力量，而引导大家审视自我，拥抱变化，是本届赛事举办的用意。",
            ["ContentJP"] = "これまでの<Default note=\"text:カショ\">華胥</>は、<Default note=\"text:たいこう\">太皓</>の変わらない力に寄りかかってきたわ。でも……これからは、自分自身を見つめ直して、変化を受け入れる覚悟が求められる。英雄大会は、その第一歩でもあるのよ。",
            ["DialogueId"] = 12061809,
            ["GUID"] = "1E320A8A",
            ["NextDialogue"] = 12061810,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320A8A",
            },
        [12061810] = {
            ["Content"] = "{nickname}，我虽想过邀请你来参赛，但考虑到你归乡心切，便未能开口。不曾想你竟与苏乙姑娘一同组队，却是正中我下怀了。",
            ["ContentJP"] = "{nickname}、本当はね、あなたのこと、試合に誘おうと思ってた。でも、帰りを急いでるって聞いて、声をかけそびれちゃったの。まさかスーイーさんと組んで出てくるなんて……正直、驚いたけど……嬉しかった。",
            ["DialogueId"] = 12061810,
            ["GUID"] = "1E320AB4",
            ["NextDialogue"] = 12061811,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320AB4",
            },
        [12061811] = {
            ["Content"] = "啊！之前煜明说自己受人所托，及时出现帮我们解围。难不成……",
            ["ContentJP"] = "あーっ！そういえばユーミンが「頼まれて来た」って言ってたよね！まさか……！",
            ["DialogueId"] = 12061811,
            ["GUID"] = "1E320ADE",
            ["NextDialogue"] = 12061812,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320ADE",
            },
        [12061812] = {
            ["Content"] = "如你所想，正是止流掌柜托在下前来相助。",
            ["ContentJP"] = "ああ。俺を動かしたのは、シリュウさんだ。",
            ["DialogueId"] = 12061812,
            ["GUID"] = "1E320B08",
            ["NextDialogue"] = 12061813,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B08",
            },
        [12061813] = {
            ["Content"] = "此前未能及时澄清，反倒引发误会，是煜明之过。",
            ["ContentJP"] = "説明が遅れてしまい、誤解を招いたのは俺の責任だ。",
            ["DialogueId"] = 12061813,
            ["GUID"] = "1E320B32",
            ["NextDialogue"] = 12061814,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B32",
            },
        [12061814] = {
            ["Content"] = "大众和飘零人之间的偏见与对立由来已久。如何推动飘零人重新融入华胥，也是现今亟待解决的课题之一。",
            ["ContentJP"] = "流れ者と<Default note=\"text:カショ\">華胥</>のあいだにあるわだかまりは、そう簡単には解けない。でも……それを解いていかなきゃ、先には進めない。",
            ["DialogueId"] = 12061814,
            ["GUID"] = "1E320B5C",
            ["NextDialogue"] = 12061815,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B5C",
            },
        [12061815] = {
            ["Content"] = "目前你们正处于风口浪尖，众人情绪已经被煽动了起来，此时无论说什么都容易遭到曲解。不如先按下不表，等待时间抚平一切。",
            ["ContentJP"] = "あなたたちは今、まさにその渦中にいる。民の感情も高ぶってるし、何を言っても曲げて受け取られるだけ。だったら、今は焦らず、少し時間に任せましょう。",
            ["DialogueId"] = 12061815,
            ["GUID"] = "1E320B86",
            ["NextDialogue"] = 12061816,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320B86",
            },
        [12061816] = {
            ["Content"] = "我稍后会出具一份调查说明为你们背书，有了这份说明，你们后续参加群英试就不会再受阻挠。",
            ["ContentJP"] = "後ほど、私から正式な報告を出しておくわ。それがあれば、これからの試合も問題なく進められるはずよ。",
            ["DialogueId"] = 12061816,
            ["GUID"] = "1E320BB0",
            ["NextDialogue"] = 12061817,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320BB0",
            },
        [12061817] = {
            ["Content"] = "……多谢。",
            ["ContentJP"] = "……ありがと。",
            ["DialogueId"] = 12061817,
            ["GUID"] = "1E320BDA",
            ["NextDialogue"] = 12061818,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320BDA",
            },
        [12061818] = {
            ["Content"] = "呵呵，只是举手之劳。",
            ["ContentJP"] = "ううん、気にしないで。",
            ["DialogueId"] = 12061818,
            ["GUID"] = "1E320C04",
            ["NextDialogue"] = 12061819,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320C04",
            },
        [12061819] = {
            ["Content"] = "今日的赛事已经结束了，你们先回去休息吧。",
            ["ContentJP"] = "今日はもう休んで。",
            ["DialogueId"] = 12061819,
            ["GUID"] = "1E320C2E",
            ["NextDialogue"] = 12061820,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320C2E",
            },
        [12061820] = {
            ["Content"] = "{nickname}，你可以稍微留一下吗？有一些话，我想单独嘱托给你。",
            ["ContentJP"] = "……{nickname}、ちょっとだけ、残ってくれる？話しておきたいことがあるの。",
            ["DialogueId"] = 12061820,
            ["GUID"] = "1E320C58",
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120618/1E320C58",
            },
        [12061901] = {
            ["Content"] = "怎么了，止流掌柜？",
            ["ContentJP"] = "どうしたの、シリュウさん？",
            ["DialogueId"] = 12061901,
            ["GUID"] = "1E3219A2",
            ["NextDialogue"] = 12061902,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203001,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E3219A2",
            },
        [12061902] = {
            ["Content"] = "你的同伴……苏乙，她正在面临的是一场关于人心和自我的挑战。",
            ["ContentJP"] = "スーイーさんのこと……少し、話しておきたくて。彼女はいま、他人と、自分自身の両方を相手にしてる。",
            ["DialogueId"] = 12061902,
            ["GUID"] = "1E3219CC",
            ["NextDialogue"] = 12061903,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E3219CC",
            },
        [12061903] = {
            ["Content"] = "人心向来是看不见摸不着的东西。这不同于显性的斗争，那些藏于水面之下的仇恨、恐惧、偏见如同暗藻一样，会绊住每一个泅泳者，使其溺亡。",
            ["ContentJP"] = "表立った争いとは違って……人の心って、目に見えないし、掴みどころがないの。水面下に沈んだ藻のように。見えなくても、確かにそこにあって……気づいたときには、足を取られて、沈んでしまう。",
            ["DialogueId"] = 12061903,
            ["GUID"] = "1E3219F6",
            ["NextDialogue"] = 12061904,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E3219F6",
            },
        [12061904] = {
            ["Content"] = "古往今来，贸然向人心发起的挑战，往往会以悲剧收尾。",
            ["ContentJP"] = "後にも先にも、人の心に真正面から挑もうとした人は、たいてい報われなかった。その多くが、悲しい結末を迎えてきたの。",
            ["DialogueId"] = 12061904,
            ["GUID"] = "1E321A20",
            ["NextDialogue"] = 12061905,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A20",
            },
        [12061905] = {
            ["Content"] = "这其中的关窍，不在于如何应对对面的恶意，而是挑战者的内心也会在不知不觉中被仇恨同化，最终以怨报怨，走向彻底的对抗。",
            ["ContentJP"] = "いちばん怖いのはね――誰かの悪意に立ち向かっているうちに、自分の中にも憎しみが生まれてしまうこと。気づいたときには、その憎しみに飲まれて、正しさのつもりだったものが、報復に変わってしまう。そこからは、もう後戻りができない。",
            ["DialogueId"] = 12061905,
            ["GUID"] = "1E321A4A",
            ["NextDialogue"] = 12061906,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A4A",
            },
        [12061906] = {
            ["Content"] = "如何审视自我，开辟一条新的道路……这场挑战注定会异常艰辛。",
            ["ContentJP"] = "どうやって自分と向き合って、どうやって新しい道を見つけるか。それを決めるのは彼女自身……きっと簡単な道じゃないわ。",
            ["DialogueId"] = 12061906,
            ["GUID"] = "1E321A74",
            ["NextDialogue"] = 12061907,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A74",
            },
        [12061907] = {
            ["Content"] = "谢谢你的提醒，止流。我相信她能做到的。",
            ["ContentJP"] = "……ありがとう、シリュウさん。でも……大丈夫。彼女なら、きっと乗り越えられるよ。",
            ["DialogueId"] = 12061907,
            ["GUID"] = "1E321A9E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120619/1E321A9E",
            },
        [12062001] = {
            ["Content"] = "虽然早想到可能会有飘零人在奉香大典期间混进来，但在这茫茫人海里找出他们也无异于大海捞针。幸亏你认出了那天工苏氏的后人。",
            ["ContentJP"] = "<Default note=\"text:ほうこうのぎ\">奉香の儀</>に紛れて、流れ者が入り込む可能性は、最初から想定していた。だが、この人混みの中で見つけ出すとなると……正直、骨が折れる。その点、<Default note=\"text:てんこう\">天工</>のスー氏の後継だと気づいてくれたのは助かった。",
            ["DialogueId"] = 12062001,
            ["GUID"] = "1E322A0A",
            ["NextDialogue"] = 12062002,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203001,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                },
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A0A",
            },
        [12062002] = {
            ["Content"] = "不过听你描述，你们似乎更早之前还有过碰面？",
            ["ContentJP"] = "それで──君の話だと、彼らとはもっと前に会っていたと？",
            ["DialogueId"] = 12062002,
            ["GUID"] = "1E322A34",
            ["NextDialogue"] = 12062003,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A34",
            },
        [12062003] = {
            ["Content"] = "……小安在野外遭到玄色狴犴的袭击，被{性别：他|她}们二人所救。",
            ["ContentJP"] = "……アンが野外で、<Default note=\"text:ゲンビー\">玄狴</>に襲われました。そのとき、{性别：あの子|あの子}たちに助けられたの。",
            ["DialogueId"] = 12062003,
            ["GUID"] = "1E322A5E",
            ["NextDialogue"] = 12062004,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A5E",
            },
        [12062004] = {
            ["Content"] = "救人？{性别：他|她}们？那位白发年轻人暂且不提，那个飘零人小姑娘去救人？可笑，不过是趁着如今华胥正当变局，惺惺作态而已。",
            ["ContentJP"] = "助けた？{性别：あいつ|あいつ}らにたちが？白髪のほうはともかく……あの流れ者の女が人助けとはね。今の<Default note=\"text:カショ\">華胥</>の情勢に乗じた、見せかけの善意だろう。",
            ["DialogueId"] = 12062004,
            ["GUID"] = "1E322A88",
            ["NextDialogue"] = 12062005,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322A88",
            },
        [12062005] = {
            ["Content"] = "时候差不多了。西郊的那处<W>地宫</>，布置如何了？",
            ["ContentJP"] = "……そろそろだ。西郊の<W>地下宮殿</>、準備はどうなっている？",
            ["DialogueId"] = 12062005,
            ["GUID"] = "1E322AB2",
            ["NextDialogue"] = 12062006,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322AB2",
            },
        [12062006] = {
            ["Content"] = "万事俱备，只等决赛了。",
            ["ContentJP"] = "準備はそろったわ。あとは決戦を待つのみよ。",
            ["DialogueId"] = 12062006,
            ["GUID"] = "1E322ADC",
            ["NextDialogue"] = 12062007,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322ADC",
            },
        [12062007] = {
            ["Content"] = "呵呵……恰巧在这个时间点上发现了掩藏在山体中的昔日机枢派地宫，这是不是说明这次连天意都站在我们这边？",
            ["ContentJP"] = "はは……このタイミングで、山に隠れていた旧・<Default note=\"text:きすうは\">機枢派</>の地下宮殿が見つかるとは。天まで、こちらに味方しているようだ。",
            ["DialogueId"] = 12062007,
            ["GUID"] = "1E322B06",
            ["NextDialogue"] = 12062008,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B06",
            },
        [12062008] = {
            ["Content"] = "只要<W>计划顺利</>……那些飘零人就能滚回他们该回的地方了。",
            ["ContentJP"] = "<W>計画が順調に進めば</>……流れ者たちは、いずれ元いる場所へ戻る。",
            ["DialogueId"] = 12062008,
            ["GUID"] = "1E322B30",
            ["NextDialogue"] = 12062009,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B30",
            },
        [12062009] = {
            ["Content"] = "要怪，就怪她的那些前辈肆意妄为。要怪，就怪我们这些大人既胆怯又执拗，放不下这些糟心的过往吧。",
            ["ContentJP"] = "責めるなら、好き勝手をしてきた先人たちを責めるんだな。あるいは──恐れながらも、過去を手放せなかった俺たち大人を、な。",
            ["DialogueId"] = 12062009,
            ["GUID"] = "1E322B5A",
            ["NextDialogue"] = 12062010,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B5A",
            },
        [12062010] = {
            ["Content"] = "你说，要是小安长大了，知道他母亲和叔叔阿姨们做的这些事，他会理解我们吗？",
            ["ContentJP"] = "なあ……アンが大人になって、母親たちのしてきたことを知ったとしたら……彼は、俺たちを理解してくれると思うか？",
            ["DialogueId"] = 12062010,
            ["GUID"] = "1E322B84",
            ["NextDialogue"] = 12062011,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322B84",
            },
        [12062011] = {
            ["Content"] = "我不是他的母亲。",
            ["ContentJP"] = "……私は、彼の母親じゃない。",
            ["DialogueId"] = 12062011,
            ["GUID"] = "1E322BAE",
            ["NextDialogue"] = 12062012,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322BAE",
            },
        [12062012] = {
            ["Content"] = "看我这脑子，差点都忘了。",
            ["ContentJP"] = "ああ……そうだったな。すまない。",
            ["DialogueId"] = 12062012,
            ["GUID"] = "1E322BD8",
            ["NextDialogue"] = 12062013,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322BD8",
            },
        [12062013] = {
            ["Content"] = "还有，我希望小安永远都不要知道这些事。如果知道了，我希望他永远都不要理解我们——他已经经历了太多事情了。",
            ["ContentJP"] = "それに──アンには、できることなら何も知らずにいてほしい。もし知ってしまったとしても……どうか、私たちを理解しないでほしい。あの子は、もう十分すぎるほど、背負ってきた。",
            ["DialogueId"] = 12062013,
            ["GUID"] = "1E322C02",
            ["NextDialogue"] = 12062014,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C02",
            },
        [12062014] = {
            ["Content"] = "但愿如此吧。",
            ["ContentJP"] = "……そうなることを、願うしかないな。",
            ["DialogueId"] = 12062014,
            ["GUID"] = "1E322C2C",
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C2C",
            },
        [12062015] = {
            ["Content"] = "一天的赛事终于结束了，不知道苏乙现在心情怎么样了……",
            ["ContentJP"] = "今日の試合も、ようやく終わりか。スーイー、今はどんな気持ちなんだろ……",
            ["DialogueId"] = 12062015,
            ["GUID"] = "1E322C56",
            ["NextDialogue"] = 12062016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C56",
            },
        [12062016] = {
            ["Content"] = "睡觉之前，去找找她吧……",
            ["ContentJP"] = "休む前に、少し顔を見に行こう。",
            ["DialogueId"] = 12062016,
            ["GUID"] = "1E322C80",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120620/1E322C80",
            },
        [12062101] = {
            ["Content"] = "终于把姑姑留下的牵机鸢的大部分结构解析完毕了……",
            ["ContentJP"] = "これで叔母さんが残したからくり<Default note=\"text:とび\">鳶、主要な構造はだいたい解析できたね……（ブツブツ）",
            ["DialogueId"] = 12062101,
            ["GUID"] = "1E323A72",
            ["NextDialogue"] = 12062102,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 103001,
                [3] = 203013,
                [4] = 203014,
                [5] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323A72",
            },
        [12062102] = {
            ["Content"] = "原来姑姑早在十几年前就已经达到了这样的水平。我还要努力多久，才能追上姑姑的脚步呢……",
            ["ContentJP"] = "十年以上前に、ここまで完成させていたなんて……私は、あとどれだけ積み重ねれば、叔母の背中に届くんだろう。",
            ["DialogueId"] = 12062102,
            ["GUID"] = "1E323A9C",
            ["NextDialogue"] = 12062103,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323A9C",
            },
        [12062103] = {
            ["Content"] = "只是这个强化机傀运动性能的组件在整个设计里格格不入，姑姑把它安装在这里，又是什么用意……",
            ["ContentJP"] = "ただ……この運動性能を強化する部品だけが、どうしても浮いている。どういう意図でここに組み込んだのかしら……？",
            ["DialogueId"] = 12062103,
            ["GUID"] = "1E323AC6",
            ["NextDialogue"] = 12062104,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323AC6",
            },
        [12062104] = {
            ["Content"] = "苏乙，原来你在这里。",
            ["ContentJP"] = "スーイー、こんなところにいたんだ。",
            ["DialogueId"] = 12062104,
            ["GUID"] = "1E323AF0",
            ["NextDialogue"] = 12062105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323AF0",
            },
        [12062105] = {
            ["Content"] = "嗯？{nickname}，找我有什么事吗？",
            ["ContentJP"] = "ん、{nickname}？どうしたの？",
            ["DialogueId"] = 12062105,
            ["GUID"] = "1E323B1A",
            ["NextDialogue"] = 12062106,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B1A",
            },
        [12062106] = {
            ["Content"] = "来看看你现在心情怎么样了。",
            ["ContentJP"] = "いや、大丈夫かなって。",
            ["DialogueId"] = 12062106,
            ["GUID"] = "1E323B44",
            ["NextDialogue"] = 12062107,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B44",
            },
        [12062107] = {
            ["Content"] = "我能有什么事……啊，你难不成是想为白天发生的事情来安慰我吗？",
            ["ContentJP"] = "……もしかして、昼間のことで心配してくれてるの？",
            ["DialogueId"] = 12062107,
            ["GUID"] = "1E323B6E",
            ["NextDialogue"] = 12062108,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B6E",
            },
        [12062108] = {
            ["Content"] = "不需要为我担心，我没事的。甚至恰恰相反，我现在感觉前所未有的好。",
            ["ContentJP"] = "大丈夫。気にしないで。それどころか……今は、前にないくらい、気分がいいの。",
            ["DialogueId"] = 12062108,
            ["GUID"] = "1E323B98",
            ["NextDialogue"] = 12062109,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323B98",
            },
        [12062109] = {
            ["Content"] = "……你确定吗，苏乙？",
            ["ContentJP"] = "……本当に？",
            ["DialogueId"] = 12062109,
            ["GUID"] = "1E323BC2",
            ["NextDialogue"] = 12062110,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323BC2",
            },
        [12062110] = {
            ["Content"] = "嗯，因为我已经想明白了一些事情。",
            ["ContentJP"] = "うん。いろいろ、考えが整理できたの。",
            ["DialogueId"] = 12062110,
            ["GUID"] = "1E323BEC",
            ["NextDialogue"] = 12062111,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323BEC",
            },
        [12062111] = {
            ["Content"] = "换做从前的我，或许会不甘心吧。我没有办法接受前人的理想，他们的抗争……就这么被歪曲成毫无来由的恶意。",
            ["ContentJP"] = "前の私だったら……叔母たちの理想や抗いが、理由もなく「悪意」にすり替えられるなんて、絶対に受け入れられなかった。",
            ["DialogueId"] = 12062111,
            ["GUID"] = "1E323C16",
            ["NextDialogue"] = 12062112,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C16",
            },
        [12062112] = {
            ["Content"] = "但现在我明白了，有些偏见不是能轻易化解的。如果那些人选择蒙蔽自己的双眼，固步自封，只听从心中仇恨的教唆，那他们被时代抛下也是难免的。对此我无能为力。",
            ["ContentJP"] = "でも今は分かる。偏見って、簡単に溶けるものじゃない。自分の目を閉じて、憎しみの声だけを信じるなら……時代に取り残されるのも、仕方のないこと。私にはどうしようもできない。",
            ["DialogueId"] = 12062112,
            ["GUID"] = "1E323C40",
            ["NextDialogue"] = 12062113,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C40",
            },
        [12062113] = {
            ["Content"] = "现在的我不再想着去改变别人了。我只需要战胜他们，证明自己就可以。",
            ["ContentJP"] = "もう、人を変えようとは思わない。私はただ、彼らを越えて、自分を証明すればいい。",
            ["DialogueId"] = 12062113,
            ["GUID"] = "1E323C6A",
            ["NextDialogue"] = 12062114,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C6A",
            },
        [12062114] = {
            ["Content"] = "苏乙…………",
            ["ContentJP"] = "スーイー……",
            ["DialogueId"] = 12062114,
            ["GUID"] = "1E323C94",
            ["NextDialogue"] = 12062115,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323C94",
            },
        [12062115] = {
            ["Content"] = "{nickname}，你怎么一副担心的表情？说过啦，我没事的，笑一笑嘛。无论在什么逆境下都要放声笑出来，这是姑姑教过我的。",
            ["ContentJP"] = "{nickname}、そんな顔しないで。言ったでしょ、大丈夫だって。どんな逆境でも、ちゃんと笑うこと。それが、叔母の教えなの。",
            ["DialogueId"] = 12062115,
            ["GUID"] = "1E323CBE",
            ["NextDialogue"] = 12062116,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323CBE",
            },
        [12062116] = {
            ["Content"] = "（远处传来了什么东西破碎的声音。）",
            ["ContentJP"] = "遠くで、何かが砕ける音が聞こえてきた。",
            ["DialogueId"] = 12062116,
            ["GUID"] = "1E323CE8",
            ["NextDialogue"] = 12062117,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323CE8",
            },
        [12062117] = {
            ["Content"] = "那边好像有什么动静……你可以帮我去看看吗？",
            ["ContentJP"] = "今の音、聞こえた？悪いけど、様子を見てきてくれる？",
            ["DialogueId"] = 12062117,
            ["GUID"] = "1E323D12",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323D12",
            },
        [12062118] = {
            ["Content"] = "咦，刚刚路过这里的时候，有这么多箱子吗……？",
            ["ContentJP"] = "あれ？さっき通ったとき、こんなに箱、あったかな……",
            ["DialogueId"] = 12062118,
            ["GUID"] = "1E323D3C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120621/1E323D3C",
            },
        [12062201] = {
            ["Content"] = "别打了别打了——是我，是唐叔啊！",
            ["ContentJP"] = "ちょ、ちょっと待った待った！俺だよ、タンだ！",
            ["DialogueId"] = 12062201,
            ["GUID"] = "1E324ADA",
            ["NextDialogue"] = 12062202,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 103001,
                [3] = 203013,
                [4] = 203014,
                [5] = 408018,
                },
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324ADA",
            },
        [12062202] = {
            ["Content"] = "哎哟喂我这一把老腰。你们年轻人倒好，一言不合就动刀动枪的，差点把我闪着了。",
            ["ContentJP"] = "いやぁ……腰が抜けるかと思った。最近の若いもんは、物騒だなぁ。危うく、ぎっくり腰になるところだったぞ。",
            ["DialogueId"] = 12062202,
            ["GUID"] = "1E324B04",
            ["NextOptions"] = {
                [1] = 12062203,
                [2] = 12062204,
                },
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324B04",
            },
        [12062203] = {
            ["Content"] = "对不起，我不知道是你。",
            ["ContentJP"] = "ごめんなさい、あなただって知らなくて。（道徳+）",
            ["DialogueId"] = 12062203,
            ["GUID"] = "1E324B2E",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12062205,
            },
        [12062204] = {
            ["Content"] = "不能怪我，只能怪你自己行踪可疑。",
            ["ContentJP"] = "そんな怪しいことするからですよ。（功利+）",
            ["DialogueId"] = 12062204,
            ["GUID"] = "1E324B58",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12062205,
            },
        [12062205] = {
            ["Content"] = "你为什么要大半夜的躲在这个……箱子里？",
            ["ContentJP"] = "どうして、こんな夜中に箱の中に？",
            ["DialogueId"] = 12062205,
            ["GUID"] = "1E324B82",
            ["NextDialogue"] = 12062206,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324B82",
            },
        [12062206] = {
            ["Content"] = "自然是担心我们小苏了！",
            ["ContentJP"] = "スーが心配でな。",
            ["DialogueId"] = 12062206,
            ["GUID"] = "1E324BAC",
            ["NextDialogue"] = 12062207,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324BAC",
            },
        [12062207] = {
            ["Content"] = "唉，孩子大了不中留，我要是进去啊，她肯定得嘴硬把我轰出来。所以我就只好在外面偷摸张望一下。",
            ["ContentJP"] = "中に入ったら入ったで、あの子、きっと強がって追い返すだろ？だから外から、こっそり様子を見てたんだ。",
            ["DialogueId"] = 12062207,
            ["GUID"] = "1E324BD6",
            ["NextDialogue"] = 12062208,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324BD6",
            },
        [12062208] = {
            ["Content"] = "小苏这次参加比赛也是，一声不吭就跑了出去。她这点心思山外山上下谁人不知啊，明明大家都能理解她，但她自己别扭，过意不去。",
            ["ContentJP"] = "今回の大会だってそうだ。何も言わずに、ふらっと出ていっちまって。<Default note=\"text:さんがいさん\">山外山</>のみんな、あの子の気持ちは分かってるのに、本人はどうも素直じゃなくてね。",
            ["DialogueId"] = 12062208,
            ["GUID"] = "1E324C00",
            ["NextDialogue"] = 12062209,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324C00",
            },
        [12062209] = {
            ["Content"] = "这孩子，平时身上的包袱太重了，觉得自己不应当如此任性，所以瞒着大家谁也不说。",
            ["ContentJP"] = "責任感が強すぎるんだよ。「自分はわがまま言っちゃいけない」って、全部、胸の奥にしまい込んでな。",
            ["DialogueId"] = 12062209,
            ["GUID"] = "1E324C2A",
            ["NextDialogue"] = 12062210,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324C2A",
            },
        [12062210] = {
            ["Content"] = "好在小苏遇着了你，有你和她组队，我这提着的心啊才算是放下了一点。对了，她刚刚和你说什么了？",
            ["ContentJP"] = "……でもな。お前さんと組んでると聞いて、少し安心した。ところでスー、何か言ってなかったか？",
            ["DialogueId"] = 12062210,
            ["GUID"] = "1E324C54",
            ["NextOptions"] = {
                [1] = 12062211,
                },
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324C54",
            },
        [12062211] = {
            ["Content"] = "转述和苏乙的聊天。",
            ["ContentJP"] = "スーイーとの会話を伝える。",
            ["DialogueId"] = 12062211,
            ["GUID"] = "1E324C7E",
            ["NextDialogue"] = 12062212,
            },
        [12062212] = {
            ["Content"] = "她说自己“前所未有的好”？完了完了。",
            ["ContentJP"] = "「前にないくらい、気分がいい」……か。あちゃあ、それは一番まずい。",
            ["DialogueId"] = 12062212,
            ["GUID"] = "1E324CA8",
            ["NextDialogue"] = 12062213,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324CA8",
            },
        [12062213] = {
            ["Content"] = "小苏这丫头我看着长大的，我太了解她了。她呀，越生气的时候，表面看起来反而越冷静。如果说“前所未有的好”，那得是气急了。",
            ["ContentJP"] = "あの子、怒ってるときほど、妙に落ち着くんだ。そんな言葉が出るってことは……相当、溜め込んでる。",
            ["DialogueId"] = 12062213,
            ["GUID"] = "1E324CD2",
            ["NextDialogue"] = 12062214,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324CD2",
            },
        [12062214] = {
            ["Content"] = "她平时表现得很成熟可靠，常常让人忘了她还只是一个半大的姑娘呢。这丫头啊，遇上她姑姑的事就会表现得很不冷静。",
            ["ContentJP"] = "普段は大人びてて、頼りになるから、つい忘れちまうが……まだ、半人前の娘なんだ。叔母のことになると、特にな。",
            ["DialogueId"] = 12062214,
            ["GUID"] = "1E324CFC",
            ["NextDialogue"] = 12062215,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324CFC",
            },
        [12062215] = {
            ["Content"] = "对了，小苏有和你说过她姑姑苏暮鹧的事情吗？这前后的来龙去脉你了解多少？",
            ["ContentJP"] = "そうだ、ムーチョの話は……もう聞いたか？",
            ["DialogueId"] = 12062215,
            ["GUID"] = "1E324D26",
            ["NextDialogue"] = 12062216,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324D26",
            },
        [12062216] = {
            ["Content"] = "她说过，她的姑姑为了修一架叫做“灭蒙巨鸟”的水利机傀，冒险赶回城里，但是被应天尉当场诛杀了。",
            ["ContentJP"] = "水路整備用のからくり「<Default note=\"text:あおばきょちょう\">青羽巨鳥</>」を修復するために、危険を承知で城に戻って……<Default note=\"text:おうてんい\">応天尉</>に、その場で討たれたって。",
            ["DialogueId"] = 12062216,
            ["GUID"] = "1E324D50",
            ["NextDialogue"] = 12062217,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324D50",
            },
        [12062217] = {
            ["Content"] = "连这个都说了？看来她真的很信任你。",
            ["ContentJP"] = "そこまで話してたか……それだけ、お前さんを信じてるんだろう。",
            ["DialogueId"] = 12062217,
            ["GUID"] = "1E324D7A",
            ["NextDialogue"] = 12062218,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324D7A",
            },
        [12062218] = {
            ["Content"] = "当时消息传来时，我们便都知道这是个死局。但没人劝得住她，她却还是去了。",
            ["ContentJP"] = "知らせが届いた時点で、誰の目にも、戻れない道だと分かってた。それでも……止められなかった。",
            ["DialogueId"] = 12062218,
            ["GUID"] = "1E324DA4",
            ["NextDialogue"] = 12062219,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324DA4",
            },
        [12062219] = {
            ["Content"] = "那灭蒙巨鸟最终没被控制住，将那东郊砸了个稀巴烂，和她前半生的理想背道而驰。小苏一直释怀不下。",
            ["ContentJP"] = "結局、<Default note=\"text:あおばきょちょう\">青羽巨鳥</>は制御を失って、東郊をめちゃくちゃにした。あの人が信じてきた理想とは、正反対の結果だ。スーにとっては……忘れたくても忘れられないことだ。",
            ["DialogueId"] = 12062219,
            ["GUID"] = "1E324DCE",
            ["NextDialogue"] = 12062220,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324DCE",
            },
        [12062220] = {
            ["Content"] = "我们这些老家伙都快半截入土了，操心不了年轻人的爱恨纠葛。希望小苏有一天能想明白，人不能总被过去的仇恨束缚住，还是得向前看哟……",
            ["ContentJP"] = "俺たちみたいな年寄りは、若いもんの愛憎に、いつまでも口出しはできん。だがな……いつかあの子が分かってくれるといい。",
            ["DialogueId"] = 12062220,
            ["GUID"] = "1E324DF8",
            ["NextDialogue"] = 12062221,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324DF8",
            },
        [12062221] = {
            ["Content"] = "（远处传来了什么东西破碎的声音。）",
            ["ContentJP"] = "遠くで、何かが砕ける音が聞こえてきた。",
            ["DialogueId"] = 12062221,
            ["GUID"] = "1E324E22",
            ["NextDialogue"] = 12062222,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324E22",
            },
        [12062222] = {
            ["Content"] = "哇！什么动静？！",
            ["ContentJP"] = "うわっ！？何だ？",
            ["DialogueId"] = 12062222,
            ["GUID"] = "1E324E4C",
            ["NextDialogue"] = 12062223,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324E4C",
            },
        [12062223] = {
            ["Content"] = "我刚刚追着这个声音出来，唐叔，这原来不是你弄出来的响动吗？",
            ["ContentJP"] = "あの音を追って来たけど……タンさんじゃ、なかったんだね。",
            ["DialogueId"] = 12062223,
            ["GUID"] = "1E324E76",
            ["NextDialogue"] = 12062224,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324E76",
            },
        [12062224] = {
            ["Content"] = "我唐叔再不小心，也不会一下碰倒这么多东西，这声音不太寻常。听这动静，好像是从山外山入口处传来的。",
            ["ContentJP"] = "さすがに、あんな大きな音は立てられんよ。どうやら<Default note=\"text:さんがいさん\">山外山</>の入口の方だな……",
            ["DialogueId"] = 12062224,
            ["GUID"] = "1E324EA0",
            ["NextDialogue"] = 12062225,
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_250024",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324EA0",
            },
        [12062225] = {
            ["Content"] = "我知道了。晚上天凉，你早点回去歇着吧，我去看看就好。",
            ["ContentJP"] = "分かった。夜は冷えるし、タンさんはもう休んで。{性别:僕|私}が様子を見てくるよ。",
            ["DialogueId"] = 12062225,
            ["GUID"] = "1E324ECA",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324ECA",
            },
        [12062226] = {
            ["Content"] = "别打了别打了——是我，是唐叔啊！",
            ["DialogueId"] = 12062226,
            ["GUID"] = "1E324ECB",
            ["SpeakNpcId"] = 250024,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120622/1E324ADA",
            },
        [12062301] = {
            ["Content"] = "………………",
            ["ContentJP"] = "………………",
            ["DialogueId"] = 12062301,
            ["GUID"] = "1E325B42",
            ["NextDialogue"] = 12062302,
            ["RelatedWikiId"] = {
                [1] = 203004,
                [2] = 203009,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                },
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325B42",
            },
        [12062302] = {
            ["Content"] = "好啊。上次钧天铁卫袭来之后，我就多长了个心眼，升级了警报装置。瞧瞧这逮住的是谁，真稀罕啊。",
            ["ContentJP"] = "ほう、珍しい客だな。前回、<Default note=\"text:てんこうのてつえい\">天衡の鉄衛</>の襲撃があったろう？それで警戒を強めて、警報装置を新調しておいたんだが……まさか引っかかるのがあんただとはね。",
            ["DialogueId"] = 12062302,
            ["GUID"] = "1E325B6C",
            ["NextDialogue"] = 12062303,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325B6C",
            },
        [12062303] = {
            ["Content"] = "……我并非以应天尉之身前来。只是有要事需要告知苏乙和{nickname}两位，说完事了就走，绝不多叨扰。",
            ["ContentJP"] = "……俺は<Default note=\"text:おうてんい\">応天尉</>として来たのではない。スーイーと{nickname}両名に急ぎ伝えるべき事があって、それを果たしたらすぐに立ち去るつもりだ。邪魔する気はない。",
            ["DialogueId"] = 12062303,
            ["GUID"] = "1E325B96",
            ["NextDialogue"] = 12062304,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325B96",
            },
        [12062304] = {
            ["Content"] = "你以为这山外山是你家后院，你想来就来，想走就走？",
            ["ContentJP"] = "ここを何だと思ってる？貴様の庭じゃないんだ。",
            ["DialogueId"] = 12062304,
            ["GUID"] = "1E325BC0",
            ["NextDialogue"] = 12062305,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325BC0",
            },
        [12062305] = {
            ["Content"] = "闹了那么大的风波还能装作若无其事。你与其征询我的意见，不如先问问你死去的师父和师妹的在天之灵同不同意！",
            ["ContentJP"] = "大騒ぎを起こした張本人が、しれっと顔を出すとはね……私に話す前に、貴様の師匠と妹弟子の墓前で許しを請うたらどうだ！",
            ["DialogueId"] = 12062305,
            ["GUID"] = "1E325BEA",
            ["NextDialogue"] = 12062306,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325BEA",
            },
        [12062306] = {
            ["Content"] = "——我替他们同意了。",
            ["ContentJP"] = "——その許し、俺が代わりに出しておいた。（登場）",
            ["DialogueId"] = 12062306,
            ["GUID"] = "1E325C14",
            ["NextDialogue"] = 12062307,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C14",
            },
        [12062307] = {
            ["Content"] = "……你！",
            ["ContentJP"] = "……貴様！",
            ["DialogueId"] = 12062307,
            ["GUID"] = "1E325C3E",
            ["NextDialogue"] = 12062308,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C3E",
            },
        [12062308] = {
            ["Content"] = "怎么，你觉得我说话不好使吗？要不这样好了，你去师父他老人家坟前上柱香，问问他的意见。要是他老人家吹胡子瞪眼睛从坟里面跳出来阻止，那我听你的。",
            ["ContentJP"] = "何だ、俺の言葉じゃ信用できんか？だったら、師匠の墓前に香でも供えて聞いてくればいい。もしヒゲ逆立てて墓から飛び出してくるようなら、あんたの言う通りにしよう。",
            ["DialogueId"] = 12062308,
            ["GUID"] = "1E325C68",
            ["NextDialogue"] = 12062309,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C68",
            },
        [12062309] = {
            ["Content"] = "但要是那坟前静悄悄的没动静，我看就不如省了这功夫，我们前尘往事，一笔勾销，如何？",
            ["ContentJP"] = "でも、何の返事もないってんなら――過去のことは水に流して、ここらで手打ちってことでどうだ？",
            ["DialogueId"] = 12062309,
            ["GUID"] = "1E325C92",
            ["NextDialogue"] = 12062310,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325C92",
            },
        [12062310] = {
            ["Content"] = "……哼。你想袒护他，那就遂了你的意吧。但要是闹出什么事来，少不了你的好果子吃！",
            ["ContentJP"] = "……フン。そこまで言うなら好きにしな。ただし、また何かあったら……今度はお前もただじゃ済まんぞ。",
            ["DialogueId"] = 12062310,
            ["GUID"] = "1E325CBC",
            ["NextDialogue"] = 12062311,
            ["SpeakNpcId"] = 240052,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325CBC",
            },
        [12062311] = {
            ["Content"] = "……刻舟，多谢你解围。",
            ["ContentJP"] = "……カシュウ、助かった。",
            ["DialogueId"] = 12062311,
            ["GUID"] = "1E325CE6",
            ["NextDialogue"] = 12062312,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325CE6",
            },
        [12062312] = {
            ["Content"] = "你这话说的，我们师兄弟之间，哪有什么谢来谢去的！倒是师兄你……你终于愿意回来看看了！",
            ["ContentJP"] = "何を他人行儀な！兄弟同士、礼を言うほどのことかよ。……それにしても、やっと戻ってきたな、ユーミン！",
            ["DialogueId"] = 12062312,
            ["GUID"] = "1E325D10",
            ["NextDialogue"] = 12062313,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D10",
            },
        [12062313] = {
            ["Content"] = "煜明，分开时不是约好了明早在赛场见吗。你怎么赶来山外山了？发生了什么事吗？",
            ["ContentJP"] = "ユーミン！？明日の試合で会おうって、別れ際に言ったのに。どうして<Default note=\"text:さんがいさん\">山外山</>に？何かあったの{性别:か|}？",
            ["DialogueId"] = 12062313,
            ["GUID"] = "1E325D3A",
            ["NextDialogue"] = 12062314,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D3A",
            },
        [12062314] = {
            ["Content"] = "被你不幸言中了。",
            ["ContentJP"] = "お前の言葉が、不幸にも現実になった。",
            ["DialogueId"] = 12062314,
            ["GUID"] = "1E325D64",
            ["NextDialogue"] = 12062315,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D64",
            },
        [12062315] = {
            ["DialogueId"] = 12062315,
            ["GUID"] = "1E325D8E",
            ["NextDialogue"] = 12062316,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325D8E",
            },
        [12062316] = {
            ["Content"] = "这是……青鸾贰型！怎么坏成这样了？",
            ["ContentJP"] = "これは……<Default note=\"text:せいほう\">青鳳</>二型！？どうしてこんな無残な姿に……",
            ["DialogueId"] = 12062316,
            ["GUID"] = "1E325DB8",
            ["NextDialogue"] = 12062317,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325DB8",
            },
        [12062317] = {
            ["Content"] = "白日的事端之后，需接受检查的青鸾贰型暂存在赛场库房中。半夜有贼人入侵，将其破坏。",
            ["ContentJP"] = "昼間の騒動の後、問題がある個体として保管庫に預けられていた。だが深夜、何者かが侵入し、破壊していった。",
            ["DialogueId"] = 12062317,
            ["GUID"] = "1E325DE2",
            ["NextDialogue"] = 12062318,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325DE2",
            },
        [12062318] = {
            ["Content"] = "如今大风九章改制，新的律法尚未定下，狴犴凭兽性行事，由它们贸然执行旧日刑罚恐再生祸乱。故而太皓暂时召回了狴犴，仅由应天尉代为执法，才让这些人钻了空子。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>は改組され、新たな律法も未整備のまま。<Default note=\"text:ビーアン\">狴犴</>たちは本能に従い旧法を振りかざす恐れがあるため、<Default note=\"text:たいこう\">太皓</>が一時的に召還し、代わりに<Default note=\"text:おうてんい\">応天尉</>が職務を引き継いだ。そこに、つけ込んだのだろう。",
            ["DialogueId"] = 12062318,
            ["GUID"] = "1E325E0C",
            ["NextDialogue"] = 12062319,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E0C",
            },
        [12062319] = {
            ["Content"] = "库房原不是什么要地。感知到案件发生后，我循着动静去追。却是迟了一步，让贼人逃了。",
            ["ContentJP"] = "保管庫は要所でもなかったが、異常を感知して駆けつけた。……しかし、一足遅かった。賊はすでに逃走した後だった。",
            ["DialogueId"] = 12062319,
            ["GUID"] = "1E325E36",
            ["NextDialogue"] = 12062320,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E36",
            },
        [12062320] = {
            ["Content"] = "糟了糟了，我那姑奶奶知道一定会伤心异常的，她最宝贵这些玩意儿了。",
            ["ContentJP"] = "あちゃー……スーイーが知ったら、泣くどころじゃ済まねぇな。あいつ、こういうのやたら大事にしてたのによ。",
            ["DialogueId"] = 12062320,
            ["GUID"] = "1E325E60",
            ["NextDialogue"] = 12062321,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E60",
            },
        [12062321] = {
            ["Content"] = "你们明天还得继续比赛呢，万一影响了心态怎么办？要我说，找个借口，让我刻舟背个黑锅得了。就说我耍剑时不小心，把它戳了个稀巴烂。",
            ["ContentJP"] = "明日は試合だろ？気持ちが乱れたらどうすんだよ。だったらいっそ俺が悪者になるって手もあるぜ。剣の稽古中に、うっかりぶっ壊しちまったってことにしてさ。",
            ["DialogueId"] = 12062321,
            ["GUID"] = "1E325E8A",
            ["NextDialogue"] = 12062322,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325E8A",
            },
        [12062322] = {
            ["Content"] = "……以谎圆谎，怕是不妥。",
            ["ContentJP"] = "……嘘を塗り重ねるのは、良策とは思えない。",
            ["DialogueId"] = 12062322,
            ["GUID"] = "1E325EB4",
            ["NextDialogue"] = 12062323,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325EB4",
            },
        [12062323] = {
            ["Content"] = "哎呀师兄你放心，俗话说得好，债多不压身嘛。反正惹她生气了这么多次，也不差这一回。",
            ["ContentJP"] = "まーまー、気楽に考えなって！借金も積もれば恐れなしって言うしな。ビビっても始まんねぇだろ。それに、もう何度も怒らせてんだろ？いまさら何を――",
            ["DialogueId"] = 12062323,
            ["GUID"] = "1E325EDE",
            ["NextDialogue"] = 12062324,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325EDE",
            },
        [12062324] = {
            ["Content"] = "没有那个必要。",
            ["ContentJP"] = "その必要はないわ。",
            ["DialogueId"] = 12062324,
            ["GUID"] = "1E325F08",
            ["NextDialogue"] = 12062325,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F08",
            },
        [12062325] = {
            ["Content"] = "苏乙……你都听见了吗？",
            ["ContentJP"] = "スーイー……聞いていたのか？",
            ["DialogueId"] = 12062325,
            ["GUID"] = "1E325F32",
            ["NextDialogue"] = 12062326,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F32",
            },
        [12062326] = {
            ["Content"] = "你们这么吵，想不注意到都难。",
            ["ContentJP"] = "あれだけ騒げば、嫌でも耳に入るわ。",
            ["DialogueId"] = 12062326,
            ["GUID"] = "1E325F5C",
            ["NextDialogue"] = 12062327,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F5C",
            },
        [12062327] = {
            ["Content"] = "想来是白天那伙人干的吧，以为这样就能让我打退堂鼓。",
            ["ContentJP"] = "思い当たる節はある。昼間の連中の仕業でしょう。私が大会を降りるとでも思ったかしら。",
            ["DialogueId"] = 12062327,
            ["GUID"] = "1E325F86",
            ["NextDialogue"] = 12062328,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325F86",
            },
        [12062328] = {
            ["Content"] = "他们没有料到的是，我早已打算把青鸾贰型拆装重组成更强大的机体。他们潜入破坏反而省了我这个功夫。",
            ["ContentJP"] = "彼らの誤算は、私がいずれ<Default note=\"text:せいほう\">青鳳</>二型を分解・再構築して、より強化するつもりだったことね。今回の破壊は、むしろ手間が省けたくらいよ。",
            ["DialogueId"] = 12062328,
            ["GUID"] = "1E325FB0",
            ["NextDialogue"] = 12062329,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325FB0",
            },
        [12062329] = {
            ["Content"] = "在足够强的实力面前，什么伎俩都会不攻自破。",
            ["ContentJP"] = "実力さえあれば、どんな悪策も無意味よ。",
            ["DialogueId"] = 12062329,
            ["GUID"] = "1E325FDA",
            ["NextDialogue"] = 12062330,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E325FDA",
            },
        [12062330] = {
            ["Content"] = "苏乙……",
            ["ContentJP"] = "スーイー……",
            ["DialogueId"] = 12062330,
            ["GUID"] = "1E326004",
            ["NextDialogue"] = 12062331,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326004",
            },
        [12062331] = {
            ["Content"] = "好了，我要彻夜改装青鸾贰型了，你们也早点休息吧。晚安。",
            ["ContentJP"] = "私は徹夜で改造に取りかかるわ。あんたたちは、早く休んでちょうだい。おやすみ。",
            ["DialogueId"] = 12062331,
            ["GUID"] = "1E32602E",
            ["NextDialogue"] = 12062332,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32602E",
            },
        [12062332] = {
            ["Content"] = "喂喂，姑奶奶这发言，好像不太对劲啊……！你们白天到底都经历了什么？",
            ["ContentJP"] = "おいおいおい……今の発言、ちょっと怖くなかったか？お前ら、昼間いったい何があったんだ？",
            ["DialogueId"] = 12062332,
            ["GUID"] = "1E326058",
            ["NextOptions"] = {
                [1] = 12062333,
                },
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326058",
            },
        [12062333] = {
            ["Content"] = "转述白天的遭遇。",
            ["ContentJP"] = "昼間の出来事を伝える。",
            ["DialogueId"] = 12062333,
            ["GUID"] = "1E326082",
            ["NextDialogue"] = 12062334,
            },
        [12062334] = {
            ["Content"] = "也难怪姑奶奶这样……",
            ["ContentJP"] = "なるほどね……そりゃ、あの人も腹くくるわけだ。",
            ["DialogueId"] = 12062334,
            ["GUID"] = "1E3260AC",
            ["NextDialogue"] = 12062335,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3260AC",
            },
        [12062335] = {
            ["Content"] = "体悟不能由旁人代劳，必须她自己做出。此时旁人再做劝说也是徒劳。",
            ["ContentJP"] = "悟りとは、人から与えられるものではない。彼女自身が辿り着くべき道だ。今は何を言っても届かない。",
            ["DialogueId"] = 12062335,
            ["GUID"] = "1E3260D6",
            ["NextDialogue"] = 12062336,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3260D6",
            },
        [12062336] = {
            ["Content"] = "以他们的不依不挠，破坏青鸾贰型恐怕并非终点。我会继续追查此事，{nickname}，你也需多加小心。",
            ["ContentJP"] = "奴らの執念を思えば、<Default note=\"text:せいほう\">青鳳</>二型の破壊が終わりとは思えない。俺は追って調べるつもりだ。{nickname}、お前も気をつけてくれ。",
            ["DialogueId"] = 12062336,
            ["GUID"] = "1E326100",
            ["NextDialogue"] = 12062337,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326100",
            },
        [12062337] = {
            ["Content"] = "好，我也会把这件事告诉止流，让他们提高警惕。",
            ["ContentJP"] = "わかった。シリュウさんにも話しておく。備えておいた方がいいからね。",
            ["DialogueId"] = 12062337,
            ["GUID"] = "1E32612A",
            ["NextDialogue"] = 12062338,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32612A",
            },
        [12062338] = {
            ["Content"] = "嗯，目前情报欠缺。只能见机行事，后发制人了。",
            ["ContentJP"] = "うむ……今は情報が少ない。動きが見えた時点で、こちらが出るしかない。",
            ["DialogueId"] = 12062338,
            ["GUID"] = "1E326154",
            ["NextDialogue"] = 12062339,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326154",
            },
        [12062339] = {
            ["Content"] = "{nickname}，今日多有操劳。你先回去休息，为明日的赛事养精蓄锐吧。",
            ["ContentJP"] = "{nickname}、今日は疲れただろう。ひとまず休んで、明日の試合に備えるといい。",
            ["DialogueId"] = 12062339,
            ["GUID"] = "1E32617E",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32617E",
            },
        [12062340] = {
            ["Content"] = "师兄，你终于愿意回来看看了！",
            ["ContentJP"] = "ユーミン、やっと戻ってきてくれたんだな！待ってたぜ！",
            ["DialogueId"] = 12062340,
            ["GUID"] = "1E3261A8",
            ["NextDialogue"] = 12062341,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3261A8",
            },
        [12062341] = {
            ["Content"] = "……只是此次群英试受人所托，不好半途而废。赛场上遭此变故，于情于理我都该陪着{nickname}与苏乙二位走完全程。",
            ["ContentJP"] = "……今回は英雄大会に際して、ある方から託された務めがある。途中で投げ出すわけにもいかない。試合中にこんな事態が起きた以上、{nickname}とスーイーの二人には最後まで付き添う義務がある。",
            ["DialogueId"] = 12062341,
            ["GUID"] = "1E3261D2",
            ["NextDialogue"] = 12062342,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3261D2",
            },
        [12062342] = {
            ["Content"] = "有些话不好意思直接说出口是吧，我懂，我懂～是我不该这样问，我自罚一杯！",
            ["ContentJP"] = "ははっ、そういうのってさ、素直に言えねぇもんだよな～わかってるって！余計なこと聞いた俺が悪かった。ほら、一杯飲んで反省するぜ！",
            ["DialogueId"] = 12062342,
            ["GUID"] = "1E3261FC",
            ["NextDialogue"] = 12062343,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3261FC",
            },
        [12062343] = {
            ["Content"] = "师兄，我和你说啊，昨天我在山外山附近看到一只大红狐狸窜过去，嗬，那一身毛啊，油光水滑的！你说，它会不会就是咱们一起养过的小橙子？",
            ["ContentJP"] = "なあ、聞いてくれよユーミン。昨日な、<Default note=\"text:さんがいさん\">山外山</>の近くで真っ赤な狐を見かけたんだ！あの毛並みときたら、ツヤッツヤでまるで油塗ったみてぇで……ひょっとしてあれ、昔一緒に育てた「ミカン」だったりしてな？",
            ["DialogueId"] = 12062343,
            ["GUID"] = "1E326226",
            ["NextDialogue"] = 12062344,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326226",
            },
        [12062344] = {
            ["Content"] = "还有啊，我和你说。上个月我睡得正熟呢，突然闪过一阵惊雷，恰好劈到我们一起练剑过的那片竹林上，你说邪不邪门？",
            ["ContentJP"] = "それからそれから、先月の話なんだけどよ……夜中に寝てたら、突然ドカン！って雷が鳴ってさ。んでそのまんま、俺らが剣の稽古してた竹林にドンピシャで落ちたんだよ！すごくねぇ？",
            ["DialogueId"] = 12062344,
            ["GUID"] = "1E326250",
            ["NextDialogue"] = 12062345,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E326250",
            },
        [12062345] = {
            ["Content"] = "竹子被劈倒后，反而周围的花啊草啊都更茂盛了。那雷劈到竹子上的焦痕还在呢。来来来，我现在就带你去看看！",
            ["ContentJP"] = "でも不思議なことに、竹は焼けて倒れたのに、まわりの草花は逆にすごく元気になってさ。焦げ跡もまだ残ってるぜ？今すぐ見に行こうぜ、ユーミン！",
            ["DialogueId"] = 12062345,
            ["GUID"] = "1E32627A",
            ["NextDialogue"] = 12062346,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E32627A",
            },
        [12062346] = {
            ["Content"] = "………………",
            ["ContentJP"] = "………………",
            ["DialogueId"] = 12062346,
            ["GUID"] = "1E3262A4",
            ["RelatedWikiId"] = {
                [1] = 203007,
                },
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3262A4",
            },
        [12062347] = {
            ["Content"] = "翌日清晨，奉香群英试报名点处……",
            ["DialogueId"] = 12062347,
            ["GUID"] = "1E3262A5",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1206/120623/1E3262A5",
            },
        [12062401] = {
            ["Content"] = "早上好。哈——好困。",
            ["ContentJP"] = "おはよう……ふぁあ——眠い……（ぐったり）",
            ["DialogueId"] = 12062401,
            ["GUID"] = "1E326BAA",
            ["NextDialogue"] = 12062402,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 103001,
                [3] = 203013,
                [4] = 203014,
                [5] = 408018,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326BAA",
            },
        [12062402] = {
            ["Content"] = "苏乙……你还好吗？你的黑眼圈看起来好重！",
            ["ContentJP"] = "スーイー、大丈夫？ すごいクマ……顔、真っ青だよ！",
            ["DialogueId"] = 12062402,
            ["GUID"] = "1E326BD4",
            ["NextDialogue"] = 12062403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326BD4",
            },
        [12062403] = {
            ["Content"] = "不过是为了改造青鸾贰型一夜没睡。放心，熬夜对于机傀师来说只是稀松平常的小事。",
            ["ContentJP"] = "たかが一晩寝なかっただけ。からくり師にとっては日常の一コマにすぎないわ。",
            ["DialogueId"] = 12062403,
            ["GUID"] = "1E326BFE",
            ["NextDialogue"] = 12062404,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326BFE",
            },
        [12062404] = {
            ["Content"] = "比起这个，重要的是青鸾贰型的性能已经全面升级完毕……",
            ["ContentJP"] = "それより大事なのは――<Default note=\"text:せいほう\">青鳳</>二型の改造が無事完了したということ。",
            ["DialogueId"] = 12062404,
            ["GUID"] = "1E326C28",
            ["NextDialogue"] = 12062433,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326C28",
            },
        [12062405] = {
            ["Content"] = "塔比瑟？！你怎么来了？",
            ["ContentJP"] = "タビテ！？なんでここに……？",
            ["DialogueId"] = 12062405,
            ["GUID"] = "1E326C52",
            ["NextDialogue"] = 12062406,
            ["RelatedWikiId"] = {
                [1] = 201029,
                },
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326C52",
            },
        [12062406] = {
            ["Content"] = "哼哼哼，怎么样？吓了一跳吧！",
            ["ContentJP"] = "ふふん、驚いた？ド派手な再登場、ってな！",
            ["DialogueId"] = 12062406,
            ["GUID"] = "1E326C7C",
            ["NextDialogue"] = 12062407,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326C7C",
            },
        [12062407] = {
            ["Content"] = "没想到，总是趾高气扬的苏乙妈妈竟然连这点小计俩都没躲过，难不成是没睡醒？",
            ["ContentJP"] = "いつも高飛車で偉そうなスーイーママが、まさかこんな簡単なトラップに引っかかるとは～。まさか、まだ寝ぼけてんの？",
            ["DialogueId"] = 12062407,
            ["GUID"] = "1E326CA6",
            ["NextDialogue"] = 12062408,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326CA6",
            },
        [12062408] = {
            ["Content"] = "你你你，你怎么在这儿，上场比赛你怎么突然失踪了！",
            ["ContentJP"] = "な、なんであんたがここにいるの！？前の試合、突然いなくなったくせに！",
            ["DialogueId"] = 12062408,
            ["GUID"] = "1E326CD0",
            ["NextDialogue"] = 12062409,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326CD0",
            },
        [12062409] = {
            ["Content"] = "可别提了……有个小吃摊老板搞什么“地狱辣挑战”，说是挑战成功就能拿到豪华大礼，我想着光是辣能辣到哪里去嘛。",
            ["ContentJP"] = "ああ……それ聞いちゃう？実は屋台の「地獄級激辛チャレンジ」ってやつに惹かれてさ。成功したら豪華景品って書いてあったんだよ。",
            ["DialogueId"] = 12062409,
            ["GUID"] = "1E326CFA",
            ["NextDialogue"] = 12062410,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326CFA",
            },
        [12062410] = {
            ["Content"] = "结果吃了一半，吃得我鼻涕连泪一起流，肚子里像火烧一样，半天才缓过来。我再也不敢小瞧华胥的辣椒了……",
            ["ContentJP"] = "「辛いったってたかが知れてる」って思ったら、半分食べたところで涙も鼻水も止まらなくなってさ……お腹は火事だし、立ち上がるのに一時間かかった。……<Default note=\"text:カショ\">華胥</>の辛味、ナメてたわ。",
            ["DialogueId"] = 12062410,
            ["GUID"] = "1E326D24",
            ["NextDialogue"] = 12062411,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326D24",
            },
        [12062411] = {
            ["Content"] = "你你你，原来就因为这种事情……",
            ["ContentJP"] = "そ、それで欠場って、あんたってほんと……",
            ["DialogueId"] = 12062411,
            ["GUID"] = "1E326D4E",
            ["NextDialogue"] = 12062412,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326D4E",
            },
        [12062412] = {
            ["Content"] = "还说我，你们也没多讲义气嘛，居然直接就抛下我和这个一身黑像乌鸦一样的怪家伙混在一起了！",
            ["ContentJP"] = "そっちこそ、冷てぇよ！オレ様を置いて、この黒ずくめの謎男とタッグ組んでさ！",
            ["DialogueId"] = 12062412,
            ["GUID"] = "1E326D78",
            ["NextDialogue"] = 12062413,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326D78",
            },
        [12062413] = {
            ["Content"] = "所以！作为抛下队友的惩罚，今天我要为你对面的队伍摇旗呐喊~歪歪歪！",
            ["ContentJP"] = "だから今日は、その罰として――あっちのチームに全力で声援送っちゃうからな～！フレーフレー！",
            ["DialogueId"] = 12062413,
            ["GUID"] = "1E326DA2",
            ["NextDialogue"] = 12062414,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326DA2",
            },
        [12062414] = {
            ["Content"] = "明明是你自己吃坏肚子，怎么还赖在我们头上！",
            ["ContentJP"] = "自分が勝手にお腹壊したくせに、なんでこっちが責められてんだよ！",
            ["DialogueId"] = 12062414,
            ["GUID"] = "1E326DCC",
            ["NextDialogue"] = 12062415,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326DCC",
            },
        [12062415] = {
            ["Content"] = "……够了。",
            ["ContentJP"] = "……やめて。",
            ["DialogueId"] = 12062415,
            ["GUID"] = "1E326DF6",
            ["NextDialogue"] = 12062416,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326DF6",
            },
        [12062416] = {
            ["Content"] = "苏乙？",
            ["ContentJP"] = "スーイー？",
            ["DialogueId"] = 12062416,
            ["GUID"] = "1E326E20",
            ["NextDialogue"] = 12062417,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E20",
            },
        [12062417] = {
            ["Content"] = "没什么好争执的。",
            ["ContentJP"] = "言い争っても意味はないわ。（冷静）",
            ["DialogueId"] = 12062417,
            ["GUID"] = "1E326E4A",
            ["NextDialogue"] = 12062418,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E4A",
            },
        [12062418] = {
            ["Content"] = "与其和没必要的人浪费时间，不如用实力向所有人证明自己。走吧，比赛要开始了。",
            ["ContentJP"] = "時間を無駄にするより力で証明する。……行きましょう。試合、始まるわ。",
            ["DialogueId"] = 12062418,
            ["GUID"] = "1E326E74",
            ["NextDialogue"] = 12062419,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E74",
            },
        [12062419] = {
            ["Content"] = "谁是没必要的人呀，你回来——喂，给我说清楚！",
            ["ContentJP"] = "ちょ、ちょっと！「無駄」って何よ！？待てって！ ちゃんと説明しろってば！",
            ["DialogueId"] = 12062419,
            ["GUID"] = "1E326E9E",
            ["NextDialogue"] = 12062420,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326E9E",
            },
        [12062420] = {
            ["Content"] = "……这家伙，今天这是怎么了？",
            ["ContentJP"] = "……なによ、今日のスーイー、やけにピリピリしてねぇ？",
            ["DialogueId"] = 12062420,
            ["GUID"] = "1E326EC8",
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326EC8",
            },
        [12062421] = {
            ["Content"] = "青鸾贰型自检完成，执行积极作战模式。",
            ["ContentJP"] = "機体チェック完了。積極作戦モード、起動。",
            ["DialogueId"] = 12062421,
            ["GUID"] = "1E326EF2",
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326EF2",
            },
        [12062422] = {
            ["Content"] = "这样什么都证明不了……青鸾贰型，提高输出功率。",
            ["ContentJP"] = "これじゃ……足りない。<Default note=\"text:せいほう\">青鳳</>二型、出力を上げなさい。",
            ["DialogueId"] = 12062422,
            ["GUID"] = "1E326F1C",
            ["NextDialogue"] = 12062423,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F1C",
            },
        [12062423] = {
            ["Content"] = "指令确认，输出功率提升至额定上限。",
            ["ContentJP"] = "指令確認。出力、定格上限に到達。",
            ["DialogueId"] = 12062423,
            ["GUID"] = "1E326F46",
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F46",
            },
        [12062424] = {
            ["Content"] = "还不够……继续。",
            ["ContentJP"] = "まだ……足りない。もっと上げて。",
            ["DialogueId"] = 12062424,
            ["GUID"] = "1E326F70",
            ["NextDialogue"] = 12062425,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F70",
            },
        [12062425] = {
            ["Content"] = "警告，部件存在超载风险。",
            ["ContentJP"] = "警告：部品に過負荷の危険あり。",
            ["DialogueId"] = 12062425,
            ["GUID"] = "1E326F9A",
            ["NextDialogue"] = 12062426,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326F9A",
            },
        [12062426] = {
            ["Content"] = "如果只能做到这个程度，那要怎么才能……继续！",
            ["ContentJP"] = "その程度で……どうやって未来を変えるの。いいから続けて！",
            ["DialogueId"] = 12062426,
            ["GUID"] = "1E326FC4",
            ["NextDialogue"] = 12062427,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326FC4",
            },
        [12062427] = {
            ["Content"] = "……苏乙，它的提示好像不太对劲……这样真的没问题吗？",
            ["ContentJP"] = "スーイー、なんか様子が変だよ……本当にそのまま続けるつもり？",
            ["DialogueId"] = 12062427,
            ["GUID"] = "1E326FEE",
            ["NextDialogue"] = 12062428,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E326FEE",
            },
        [12062428] = {
            ["Content"] = "放心，我是青鸾贰型的制造者。我心中有数。",
            ["ContentJP"] = "大丈夫。私は、この機体を誰より知ってる。",
            ["DialogueId"] = 12062428,
            ["GUID"] = "1E327018",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E327018",
            },
        [12062429] = {
            ["Content"] = "警告、警告，功率过载。",
            ["ContentJP"] = "警告、警告、出力オーバー。",
            ["DialogueId"] = 12062429,
            ["GUID"] = "1E327042",
            ["NextDialogue"] = 12062430,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E327042",
            },
        [12062430] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12062430,
            ["GUID"] = "1E32706C",
            ["NextDialogue"] = 12062431,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E32706C",
            },
        [12062431] = {
            ["Content"] = "警告、警……",
            ["ContentJP"] = "警告、ケイ……",
            ["DialogueId"] = 12062431,
            ["GUID"] = "1E327096",
            ["NextDialogue"] = 12062432,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E327096",
            },
        [12062432] = {
            ["Content"] = "青鸾贰型？！",
            ["ContentJP"] = "<Default note=\"text:せいほう\">青鳳</>二型！？返事なさい！",
            ["DialogueId"] = 12062432,
            ["GUID"] = "1E3270C0",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120624/1E3270C0",
            },
        [12062433] = {
            ["DialogueId"] = 12062433,
            ["GUID"] = "1E3270C1",
            ["NextDialogue"] = 12062405,
            },
        [12062501] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12062501,
            ["GUID"] = "1E327C12",
            ["NextDialogue"] = 12062502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_Zhongren",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327C12",
            },
        [12062502] = {
            ["Content"] = "我与司事会确认过了。幸好爆炸的地点是在人烟稀疏的空旷之地，未造成任何人员财物损伤。",
            ["ContentJP"] = "<Default note=\"text:しきじ\">職事</>の方に確認を取った。幸い爆発地点は人がまばらな場所で、人的・物的被害はなかった。",
            ["DialogueId"] = 12062502,
            ["GUID"] = "1E327C3C",
            ["NextDialogue"] = 12062503,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327C3C",
            },
        [12062503] = {
            ["Content"] = "但仍有一些选手目击到了这场爆炸，这引起了参赛人员恐慌。由于我们队伍的明显过失，本次比赛结果只能判为落败。",
            ["ContentJP"] = "だが一部の参加者が爆発を目撃しており、不安を煽る結果になった。今回の件について、我々の明確な過失として、試合結果は脱落と判定された。",
            ["DialogueId"] = 12062503,
            ["GUID"] = "1E327C66",
            ["NextDialogue"] = 12062504,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327C66",
            },
        [12062504] = {
            ["Content"] = "好在，在止流的争取之下，我们的参赛资格并未被取消。目前还有通过复活赛转败为胜的机会。",
            ["ContentJP"] = "だがシリュウの尽力もあって、出場資格そのものは保たれている。まだ、敗者復活戦のチャンスが残っている。",
            ["DialogueId"] = 12062504,
            ["GUID"] = "1E327C90",
            ["NextDialogue"] = 12062505,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327C90",
            },
        [12062505] = {
            ["Content"] = "对不起……都是因为我。",
            ["ContentJP"] = "ごめんなさい……私のせいで……（すすり泣き）",
            ["DialogueId"] = 12062505,
            ["GUID"] = "1E327CBA",
            ["NextDialogue"] = 12062506,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327CBA",
            },
        [12062506] = {
            ["Content"] = "苏乙……之后还有复活赛的机会，我们还能赢的，你不需要这么自责。",
            ["ContentJP"] = "スーイー……まだ復活戦がある。これから巻き返せばいい、そんなに自分を責めないで。",
            ["DialogueId"] = 12062506,
            ["GUID"] = "1E327CE4",
            ["NextDialogue"] = 12062507,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327CE4",
            },
        [12062507] = {
            ["Content"] = "不，不是因为输赢这种微不足道的小事……",
            ["ContentJP"] = "……違うの。勝ち負けなんかの問題じゃない。",
            ["DialogueId"] = 12062507,
            ["GUID"] = "1E327D0E",
            ["NextDialogue"] = 12062508,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327D0E",
            },
        [12062508] = {
            ["Content"] = "差一点，差一点我就变成了他们所说的那种罔顾他人性命的飘零人……",
            ["ContentJP"] = "あと一歩で……私も、あの人たちの言う通りの「命を顧みない流れ者」になるところだったのよ。",
            ["DialogueId"] = 12062508,
            ["GUID"] = "1E327D38",
            ["NextDialogue"] = 12062509,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327D38",
            },
        [12062509] = {
            ["Content"] = "我明明那么想否定他们的指责，到头来，那些指责全都应验了，我压根没有搞清楚什么是真正应该证明的东西……",
            ["ContentJP"] = "あれほど否定したかったのに……結局、自分が何を証明したかったのかすら見失ってた。",
            ["DialogueId"] = 12062509,
            ["GUID"] = "1E327D62",
            ["NextDialogue"] = 12062510,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327D62",
            },
        [12062510] = {
            ["Content"] = "原来你们都聚在这里啊。",
            ["ContentJP"] = "あ、ここにいたのね。",
            ["DialogueId"] = 12062510,
            ["GUID"] = "1E327D8C",
            ["NextDialogue"] = 12062511,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327D8C",
            },
        [12062511] = {
            ["Content"] = "塔比瑟？",
            ["ContentJP"] = "タビテ？",
            ["DialogueId"] = 12062511,
            ["GUID"] = "1E327DB6",
            ["NextDialogue"] = 12062512,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327DB6",
            },
        [12062512] = {
            ["Content"] = "那个……我是来道歉的。",
            ["ContentJP"] = "えっと……謝りに来たの。さっきは、ごめん。",
            ["DialogueId"] = 12062512,
            ["GUID"] = "1E327DE0",
            ["NextDialogue"] = 12062513,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327DE0",
            },
        [12062513] = {
            ["Content"] = "我知道你们没有抛下我，这位老兄也是为了让你们能继续参赛才临时来补我的位置……",
            ["ContentJP"] = "置いてかれたんじゃないって、わかってるよ。このお兄さんも、試合続行のために急遽代役をしてくれただけだって。",
            ["DialogueId"] = 12062513,
            ["GUID"] = "1E327E0A",
            ["NextDialogue"] = 12062514,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327E0A",
            },
        [12062514] = {
            ["Content"] = "赛前说的那些话也只是想捉弄一下你们……我也不知道会让你气成这样。",
            ["ContentJP"] = "あんなこと言ったのも、ちょっとからかいたかっただけで……まさか、あそこまで怒るとは思わなかった。",
            ["DialogueId"] = 12062514,
            ["GUID"] = "1E327E34",
            ["NextDialogue"] = 12062515,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327E34",
            },
        [12062515] = {
            ["Content"] = "塔比瑟，不是因为你，是我自己的问题……",
            ["ContentJP"] = "……タビテ、違うの。あんたのせいじゃない。全部、私が悪いの。",
            ["DialogueId"] = 12062515,
            ["GUID"] = "1E327E5E",
            ["NextDialogue"] = 12062516,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327E5E",
            },
        [12062516] = {
            ["Content"] = "呜……苏乙，打起精神来，大家还要一起领奖呢！",
            ["ContentJP"] = "うぅ……スーイー、元気出してよ～だって、まだみんなで表彰台に立たなきゃいけないんだから！",
            ["DialogueId"] = 12062516,
            ["GUID"] = "1E327E88",
            ["NextDialogue"] = 12062517,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327E88",
            },
        [12062517] = {
            ["Content"] = "那个，我知道你不是坏人……虽然我老是气你，但我还是更喜欢看你耍威风的样子……",
            ["ContentJP"] = "……オレ、スーイーのこと悪い人だなんて思ってねぇよ。からかうのはクセだけどさ……やっぱり、お前がかっこよく戦ってる姿、好きなんだよな。",
            ["DialogueId"] = 12062517,
            ["GUID"] = "1E327EB2",
            ["NextDialogue"] = 12062518,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327EB2",
            },
        }
  end },
  { MinKey = 12062518, MaxKey = 12063301, Loader = function()
      return {
        [12062518] = {
            ["Content"] = "（嘈杂的议论声。）",
            ["ContentJP"] = "観衆がざわつく",
            ["DialogueId"] = 12062518,
            ["GUID"] = "1E327EDC",
            ["NextDialogue"] = 12062519,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327EDC",
            },
        [12062519] = {
            ["Content"] = "……观众情绪已是沸反盈天，此处不宜久留。",
            ["ContentJP"] = "……観客の動揺が広がっている。長居すべきではない。",
            ["DialogueId"] = 12062519,
            ["GUID"] = "1E327F06",
            ["NextDialogue"] = 12062520,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F06",
            },
        [12062520] = {
            ["Content"] = "{nickname}，我出面转移观众注意力，你掩护苏乙先行退场吧。",
            ["ContentJP"] = "{nickname}、俺が観客の注意を引く。お前はスーイーを連れて、先に退場を。",
            ["DialogueId"] = 12062520,
            ["GUID"] = "1E327F30",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F30",
            },
        [12062521] = {
            ["Content"] = "这么危险的东西，司事会怎么允许使用的……？",
            ["ContentJP"] = "あんな危ないものを、どうして職事様は許可したんだ……？（ヒソヒソ）",
            ["DialogueId"] = 12062521,
            ["GUID"] = "1E327F5A",
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F5A",
            },
        [12062522] = {
            ["Content"] = "那个机傀如果在人群里爆炸了，后果简直不堪设想……",
            ["ContentJP"] = "もし群衆の中で爆発してたら……考えるだけでゾッとするわ…………（ヒソヒソ）",
            ["DialogueId"] = 12062522,
            ["GUID"] = "1E327F84",
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327F84",
            },
        [12062523] = {
            ["Content"] = "要是飘零人都是这样的危险份子，谁来保障我们的安全？！把他们赶出去！",
            ["ContentJP"] = "あんなのが流れ者の正体だっていうなら、誰が私たちの安全を守るのよ！？出ていってもらわなきゃ困るわ！（ヒソヒソ）",
            ["DialogueId"] = 12062523,
            ["GUID"] = "1E327FAE",
            ["SpeakNpcName"] = "UI_Npc_Name_Siyu",
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327FAE",
            },
        [12062524] = {
            ["Content"] = "苏乙，你不用太在意他们说了什么……",
            ["ContentJP"] = "……気にしなくていい。誰が何を言っても、あなたの価値が変わるわけじゃない。",
            ["DialogueId"] = 12062524,
            ["GUID"] = "1E327FD8",
            ["NextDialogue"] = 12062525,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E327FD8",
            },
        [12062525] = {
            ["Content"] = "……好。",
            ["ContentJP"] = "……うん、わかってる。",
            ["DialogueId"] = 12062525,
            ["GUID"] = "1E328002",
            ["NextDialogue"] = 12062526,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E328002",
            },
        [12062526] = {
            ["Content"] = "出口就在前方了。",
            ["ContentJP"] = "もうすぐ出口だよ。",
            ["DialogueId"] = 12062526,
            ["GUID"] = "1E32802C",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120625/1E32802C",
            },
        [12062601] = {
            ["Content"] = "想装作无事发生，就这样视而不见地走过去吗？",
            ["ContentJP"] = "このまま知らぬ顔で行っちゃうつもり？",
            ["DialogueId"] = 12062601,
            ["GUID"] = "1E328C7A",
            ["NextDialogue"] = 12062602,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328C7A",
            },
        [12062602] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12062602,
            ["GUID"] = "1E328CA4",
            ["NextDialogue"] = 12062603,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328CA4",
            },
        [12062603] = {
            ["Content"] = "呵，伤人却毫无悔意，你和你的姑姑苏暮鹧倒是如出一辙。",
            ["ContentJP"] = "ふん。人を傷つけておいて、詫びのひとこともないなんて。まるであなたの叔母、ムーチョとそっくり。",
            ["DialogueId"] = 12062603,
            ["GUID"] = "1E328CCE",
            ["NextDialogue"] = 12062604,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328CCE",
            },
        [12062604] = {
            ["Content"] = "想来嘲笑我吗？随便你怎么说好了。我不会辩解。",
            ["ContentJP"] = "……嘲笑したいなら、ご自由に。弁解はしないわ。",
            ["DialogueId"] = 12062604,
            ["GUID"] = "1E328CF8",
            ["NextDialogue"] = 12062605,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328CF8",
            },
        [12062605] = {
            ["Content"] = "都是因为我过度改装青鸾贰号才导致它爆炸，这一点上我没什么可否认的。",
            ["ContentJP"] = "今回の爆発は、私の過剰な改造が原因。それは紛れもない事実だから。",
            ["DialogueId"] = 12062605,
            ["GUID"] = "1E328D22",
            ["NextDialogue"] = 12062606,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328D22",
            },
        [12062606] = {
            ["Content"] = "但这一切都与我姑姑无关。不要用我的错抹黑她……这是我唯一的底线。",
            ["ContentJP"] = "でも、叔母は関係ない。あの人の名誉だけは、決して穢させない。それだけは譲れないわ。",
            ["DialogueId"] = 12062606,
            ["GUID"] = "1E328D4C",
            ["NextDialogue"] = 12062607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328D4C",
            },
        [12062607] = {
            ["Content"] = "抹黑？",
            ["ContentJP"] = "名誉？",
            ["DialogueId"] = 12062607,
            ["GUID"] = "1E328D76",
            ["NextDialogue"] = 12062608,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328D76",
            },
        [12062608] = {
            ["Content"] = "等等，难不成你真的不清楚苏暮鹧到底做过什么？",
            ["ContentJP"] = "……まさか、本当に知らないの？",
            ["DialogueId"] = 12062608,
            ["GUID"] = "1E328DA0",
            ["NextDialogue"] = 12062609,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328DA0",
            },
        [12062609] = {
            ["Content"] = "……你到底想说什么？",
            ["ContentJP"] = "……なんのこと？",
            ["DialogueId"] = 12062609,
            ["GUID"] = "1E328DCA",
            ["NextDialogue"] = 12062610,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328DCA",
            },
        [12062610] = {
            ["Content"] = "看来你真的不知道……",
            ["ContentJP"] = "驚いた……本当に知らないのね。",
            ["DialogueId"] = 12062610,
            ["GUID"] = "1E328DF4",
            ["NextDialogue"] = 12062611,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328DF4",
            },
        [12062611] = {
            ["Content"] = "哈哈哈……原来你不知道……那个罪人的侄女，竟然不知道她的姑姑犯下的罪行！",
            ["ContentJP"] = "あはは……知らなかったのね……罪人の姪が、自分の叔母がどんな罪を犯したかも知らずに、のうのうと生きてきたなんて！",
            ["DialogueId"] = 12062611,
            ["GUID"] = "1E328E1E",
            ["NextDialogue"] = 12062612,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E1E",
            },
        [12062612] = {
            ["Content"] = "当我一天天在仇恨的怒火中辗转反侧，天色将明才勉强入睡时，她的侄女竟然能沉浸在恬不知耻的酣眠当中。",
            ["ContentJP"] = "私は憎しみに飲まれて眠れぬ夜を繰り返してたというのに、あなたは平然と夢につけたのね。",
            ["DialogueId"] = 12062612,
            ["GUID"] = "1E328E48",
            ["NextDialogue"] = 12062613,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E48",
            },
        [12062613] = {
            ["Content"] = "你明明早已见过受害者——小安的腿疾就是苏暮鹧那个女人造成的！听到这里，你还能心安理得地为她辩护吗？",
            ["ContentJP"] = "……あの事故の被害者を、あなたはもう見ているはずよ。アンの足――それはムーチョのせいで傷つけられたの。",
            ["DialogueId"] = 12062613,
            ["GUID"] = "1E328E72",
            ["NextDialogue"] = 12062614,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E72",
            },
        [12062614] = {
            ["Content"] = "你说……什么？",
            ["ContentJP"] = "今、なんて？",
            ["DialogueId"] = 12062614,
            ["GUID"] = "1E328E9C",
            ["NextDialogue"] = 12062615,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328E9C",
            },
        [12062615] = {
            ["Content"] = "你没听错。",
            ["ContentJP"] = "何度でもいうわ。",
            ["DialogueId"] = 12062615,
            ["GUID"] = "1E328EC6",
            ["NextDialogue"] = 12062616,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328EC6",
            },
        [12062616] = {
            ["Content"] = "不仅如此，小安的父母，还有更多受害者，都丧身于她引发的事故当中。",
            ["ContentJP"] = "アンの両親も、他の多くの人も……あの事故で命を奪われたの。",
            ["DialogueId"] = 12062616,
            ["GUID"] = "1E328EF0",
            ["NextDialogue"] = 12062617,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328EF0",
            },
        [12062617] = {
            ["Content"] = "那女人妄图操纵灭蒙巨鸟撞击执律阁，被击坠后，那足有千斤重的机关巨鸟直直冲向东郊。无数人躲闪不及，当场身陨。",
            ["ContentJP"] = "ムーチョは、制御を失った<Default note=\"text:あおばきょちょう\">青羽巨鳥</>で<Default note=\"text:しつりつかく\">執律閣</>へ突撃しようとした。だが撃墜され、その機体は東の郊外へ墜落したの。人々は逃げる間もなく命を落とした。",
            ["DialogueId"] = 12062617,
            ["GUID"] = "1E328F1A",
            ["NextDialogue"] = 12062618,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F1A",
            },
        [12062618] = {
            ["Content"] = "……不，那不是姑姑的本意！在灭蒙残留的信息匣里，她留下了最后的遗言！",
            ["ContentJP"] = "……でも、それは……叔母の本意じゃない。彼女は<Default note=\"text:あおばきょちょう\">青羽巨鳥</>の残骸に、最後の言葉を記していた。",
            ["DialogueId"] = 12062618,
            ["GUID"] = "1E328F44",
            ["NextDialogue"] = 12062619,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F44",
            },
        [12062619] = {
            ["Content"] = "“我想在生命最后的时刻飞去执律阁上空看一看，看看那支配着所有人的神明究竟是何模样。”",
            ["ContentJP"] = "「私は、最期に一度だけ、<Default note=\"text:しつりつかく\">執律閣</>の上空を飛びたかった。全てを支配する神の姿を、この目で見ておきたかった」と。",
            ["DialogueId"] = 12062619,
            ["GUID"] = "1E328F6E",
            ["NextDialogue"] = 12062620,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F6E",
            },
        [12062620] = {
            ["Content"] = "姑姑……是这样说的。她飞向执律阁，并非是为了什么袭击……她，她只是想看一眼……",
            ["ContentJP"] = "叔母は、ただ……見たかっただけなの。争いを起こすためじゃない……そう、願いだっただけ……",
            ["DialogueId"] = 12062620,
            ["GUID"] = "1E328F98",
            ["NextDialogue"] = 12062621,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328F98",
            },
        [12062621] = {
            ["Content"] = "你对那些亡魂解释去吧，如果他们还能听得到。",
            ["ContentJP"] = "その言い訳を、死んだ人たちに聞かせてあげなさい。もし彼らの声が、まだ届くというのなら。",
            ["DialogueId"] = 12062621,
            ["GUID"] = "1E328FC2",
            ["NextDialogue"] = 12062622,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328FC2",
            },
        [12062622] = {
            ["Content"] = "从知道那场事故因她而起的那一天，我就无时无刻地想要找到她，让她血债血偿。",
            ["ContentJP"] = "あの日の事故が彼女の仕業だと知ったときから、私の心は――憎しみの剣を手放せなくなった。",
            ["DialogueId"] = 12062622,
            ["GUID"] = "1E328FEC",
            ["NextDialogue"] = 12062623,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E328FEC",
            },
        [12062623] = {
            ["Content"] = "即便会遭受大风九章的制裁，我也要让她的血在我的剑下流淌，让她在死亡的绝望之中向所有因她而逝去的生命忏悔。",
            ["ContentJP"] = "たとえ<Default note=\"text:たいふうきゅうしょう\">大風九章</>に裁かれようとも、私は彼女の血でこの手を染めると決めた。命を奪われた者たちの無念を、その最期の絶望を、私は彼女に突きつけたかった。",
            ["DialogueId"] = 12062623,
            ["GUID"] = "1E329016",
            ["NextDialogue"] = 12062624,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329016",
            },
        [12062624] = {
            ["Content"] = "我要亲手杀了她。",
            ["ContentJP"] = "この手で、あの女を殺したかった。",
            ["DialogueId"] = 12062624,
            ["GUID"] = "1E329040",
            ["NextDialogue"] = 12062625,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329040",
            },
        [12062625] = {
            ["Content"] = "可是，姑姑早就死在了那场事故当中……！",
            ["ContentJP"] = "でも……でも、叔母は……あの事故で、もう……！",
            ["DialogueId"] = 12062625,
            ["GUID"] = "1E32906A",
            ["NextDialogue"] = 12062626,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32906A",
            },
        [12062626] = {
            ["Content"] = "是啊，正如你所说。她死了，没有哀嚎，没有忏悔。她就这么简简单单地死了。",
            ["ContentJP"] = "ええ、その通り。彼女は死んだ。あっさりと。悔いることもなく、叫ぶこともなく、ただ――終わったのよ。",
            ["DialogueId"] = 12062626,
            ["GUID"] = "1E329094",
            ["NextDialogue"] = 12062627,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329094",
            },
        [12062627] = {
            ["Content"] = "把周围变得天翻地覆之后，她就这么倒在了废墟里。她死了，然后呢？为什么始作俑者死得那么潇洒，幸存者却要经历漫长痛苦的折磨？",
            ["ContentJP"] = "あらゆるものを破壊しといて、あんなあっけなく死ぬなんてね。どうして……残された私たちが……どうして何年も、何十年も、痛みとともに生き続けなきゃならないの？",
            ["DialogueId"] = 12062627,
            ["GUID"] = "1E3290BE",
            ["NextDialogue"] = 12062628,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3290BE",
            },
        [12062628] = {
            ["Content"] = "我的愤怒，我的仇恨，就只能像是受了潮的火药，就这么强行被浇灭。直到你们飘零人重新回来……回到大家的眼前。",
            ["ContentJP"] = "私の怒りも、憎しみも、湿った火薬のように、何も燃やせないまま腐っていった。そう……あんたたち流れ者が、また人前に姿を現すまでは。",
            ["DialogueId"] = 12062628,
            ["GUID"] = "1E3290E8",
            ["NextDialogue"] = 12062629,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3290E8",
            },
        [12062629] = {
            ["Content"] = "残害人命的凶手不是你苏乙，但我不会让身为苏暮鹧传人的你，不会让飘零人就这么说走就走，说回就回。",
            ["ContentJP"] = "たとえ罪を犯したのがスーイーでなくとも、ムーチョの血を引く者として、流れ者の名を背負って、のうのうと現れておいて、タダで済むと思ったの？",
            ["DialogueId"] = 12062629,
            ["GUID"] = "1E329112",
            ["NextDialogue"] = 12062630,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329112",
            },
        [12062630] = {
            ["Content"] = "这下你明白了吧，飘零人小姑娘？",
            ["ContentJP"] = "これで理解できただろう、流れ者のお嬢さん？",
            ["DialogueId"] = 12062630,
            ["GUID"] = "1E32913C",
            ["NextDialogue"] = 12062631,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32913C",
            },
        [12062631] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12062631,
            ["GUID"] = "1E329166",
            ["NextDialogue"] = 12062632,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329166",
            },
        [12062632] = {
            ["Content"] = "飘零人就是一根刺，一根插在渴望和平厌倦纷争的华胥人身上的一根刺，华胥，不会接纳你们。",
            ["ContentJP"] = "流れ者は、この国の傷だ。平和を求め、争いに疲れた<Default note=\"text:カショ\">華胥</>にとっては、抜けぬ棘でしかない。<Default note=\"text:カショ\">華胥</>は、君たちを受け入れはしない。",
            ["DialogueId"] = 12062632,
            ["GUID"] = "1E329190",
            ["NextDialogue"] = 12062633,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329190",
            },
        [12062633] = {
            ["Content"] = "该传达的意思已经清楚了。潇湘，我们走吧。",
            ["ContentJP"] = "言うべきことは、すべて言った。行くぞ、ショウ。",
            ["DialogueId"] = 12062633,
            ["GUID"] = "1E3291BA",
            ["NextDialogue"] = 12062634,
            ["SpeakNpcId"] = 250015,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3291BA",
            },
        [12062634] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………（プレイヤーに背を向けて離れようとする）",
            ["DialogueId"] = 12062634,
            ["GUID"] = "1E3291E4",
            ["NextDialogue"] = 12062635,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3291E4",
            },
        [12062635] = {
            ["Content"] = "{nickname}，我先失陪一下……",
            ["ContentJP"] = "{nickname}、ごめん、少し、ひとりにさせて……（押し殺した嗚咽混じりに）",
            ["DialogueId"] = 12062635,
            ["GUID"] = "1E32920E",
            ["NextDialogue"] = 12062636,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32920E",
            },
        [12062636] = {
            ["Content"] = "苏乙……你是在哭吗？",
            ["ContentJP"] = "スーイー、泣いてるの{性别:か|}……？",
            ["DialogueId"] = 12062636,
            ["GUID"] = "1E329238",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329238",
            },
        [12062637] = {
            ["Content"] = "这种问题，你明明可以不用问的……",
            ["ContentJP"] = "わざわざ言わないで……",
            ["DialogueId"] = 12062637,
            ["GUID"] = "1E329262",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329262",
            },
        [12062638] = {
            ["Content"] = "呜……明明这种时候留我一个人在这里就好……",
            ["ContentJP"] = "うっ……こんな時ぐらい、ほっといてよ……",
            ["DialogueId"] = 12062638,
            ["GUID"] = "1E32928C",
            ["NextDialogue"] = 12062639,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32928C",
            },
        [12062639] = {
            ["DialogueId"] = 12062639,
            ["GUID"] = "1E32928D",
            ["NextDialogue"] = 12062640,
            },
        [12062640] = {
            ["DialogueId"] = 12062640,
            ["GUID"] = "1E32928E",
            },
        [12062641] = {
            ["Content"] = "说的也是呢……{nickname}，从我与你认识的第一面开始，你就是这样，总是在做正确的事情。不像我……",
            ["ContentJP"] = "ふふっ……たしかに、{nickname}はずっとそうよね。最初に会った時から、いつだって正しいことをしようとしてた。私とは違って……",
            ["DialogueId"] = 12062641,
            ["GUID"] = "1E32930A",
            ["NextDialogue"] = 12062642,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32930A",
            },
        [12062642] = {
            ["Content"] = "我从来没有想过我是不是做错了，只是一意孤行地想要证明自己，直到刚刚……",
            ["ContentJP"] = "私はただ、突き進むだけだった。正しいかどうかも考えずに、自分を証明したい一心で……さっきまで、ずっと……そのことに気づけなかった。",
            ["DialogueId"] = 12062642,
            ["GUID"] = "1E329334",
            ["NextDialogue"] = 12062643,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329334",
            },
        [12062643] = {
            ["Content"] = "我知道他们憎恨飘零人，但我以为他们只是讨厌飘零人不敬神明。我甚至没有尝试去理解一下他们，去理解他们真正的痛苦。",
            ["ContentJP"] = "流れ者が憎まれているのは知ってた。でも、てっきり神を敬わないからだとばかり……彼らの痛みを……苦しみを、理解しようともしなかった。",
            ["DialogueId"] = 12062643,
            ["GUID"] = "1E32935E",
            ["NextDialogue"] = 12062644,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32935E",
            },
        [12062644] = {
            ["Content"] = "我知道姑姑做的是正确的事情，却没想过她当年的事故酿成的后果，哪怕不是出于她的本意。",
            ["ContentJP"] = "叔母がやってきたことは正しいと、私は信じてた。けれど、その結果がもたらしたものには目を向けなかった……たとえ、それが彼女の本意じゃなかったとしても。",
            ["DialogueId"] = 12062644,
            ["GUID"] = "1E329388",
            ["NextDialogue"] = 12062645,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329388",
            },
        [12062645] = {
            ["Content"] = "我真是……糟透了。",
            ["ContentJP"] = "本当に……最低だよね。",
            ["DialogueId"] = 12062645,
            ["GUID"] = "1E3293B2",
            ["NextDialogue"] = 12062646,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3293B2",
            },
        [12062646] = {
            ["Content"] = "苏乙……我没有你说的那么厉害，你也没有自己想的那么糟糕。",
            ["ContentJP"] = "……スーイー。{性别:僕|私}はあなたが言うほど立派じゃない。でもあなただって、自分が思うほど悪くないよ。",
            ["DialogueId"] = 12062646,
            ["GUID"] = "1E3293DC",
            ["NextDialogue"] = 12062647,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E3293DC",
            },
        [12062647] = {
            ["Content"] = "不然，你不会往这个方向走的。我没猜错的话——你想去小安的家，不是吗？",
            ["ContentJP"] = "そうじゃなきゃ、今ここに立ってない――行きたいん{性别:だろう|でしょ}？アンの家へ。",
            ["DialogueId"] = 12062647,
            ["GUID"] = "1E329406",
            ["NextDialogue"] = 12062648,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329406",
            },
        [12062648] = {
            ["Content"] = "……连这也被你看出来了。",
            ["ContentJP"] = "そんなことまで、言い当てられちゃうなんてね。",
            ["DialogueId"] = 12062648,
            ["GUID"] = "1E329430",
            ["NextDialogue"] = 12062649,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E329430",
            },
        [12062649] = {
            ["Content"] = "走吧，我们一起。",
            ["ContentJP"] = "一緒に行くよ。",
            ["DialogueId"] = 12062649,
            ["GUID"] = "1E32945A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120626/1E32945A",
            },
        [12062701] = {
            ["Content"] = "{nickname}，苏乙姑娘，别来无恙。",
            ["ContentJP"] = "{nickname}、スーイーさん、お久しゅうございます。",
            ["DialogueId"] = 12062701,
            ["GUID"] = "1E329CE2",
            ["NextDialogue"] = 12062702,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 203006,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                [8] = 403009,
                },
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329CE2",
            },
        [12062702] = {
            ["Content"] = "扶疏……你怎么会在这里？",
            ["ContentJP"] = "フーシュ……どうしてここに？",
            ["DialogueId"] = 12062702,
            ["GUID"] = "1E329D0C",
            ["NextDialogue"] = 12062703,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D0C",
            },
        [12062703] = {
            ["Content"] = "这家的女主人收养了一位孤儿。那名幼童在一场机傀坠毁的灾难中父母双亡，自己亦险些丧生。",
            ["ContentJP"] = "このお宅の女主人が、孤児をお引き取りになったと伺いました。その子は、からくりの墜落による災厄にてご両親を失い、ご自身も命を落としかけたそうでございます。",
            ["DialogueId"] = 12062703,
            ["GUID"] = "1E329D36",
            ["NextDialogue"] = 12062704,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D36",
            },
        [12062704] = {
            ["Content"] = "根据卷宗记载，当年泽生阁的医师们虽然拼尽全力保住了幼童的性命，但那孩子还是落下了终身残疾。",
            ["ContentJP"] = "古き記録によれば、当時の<Default note=\"text:たくせいかく\">澤生閣</>の医師方が総力を挙げて命を救ったとのこと。されど……その子には、生涯消えぬ障りが残ってしまいました。",
            ["DialogueId"] = 12062704,
            ["GUID"] = "1E329D60",
            ["NextDialogue"] = 12062705,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D60",
            },
        [12062705] = {
            ["Content"] = "那……小安的腿，还有机会治好吗？",
            ["ContentJP"] = "じゃあ、アンの足は……もう治せないの？",
            ["DialogueId"] = 12062705,
            ["GUID"] = "1E329D8A",
            ["NextDialogue"] = 12062706,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329D8A",
            },
        [12062706] = {
            ["Content"] = "现在的我还办不到。枯荣之法虽可引渡浊气，但面对此等经年残疾，亦是无能为力。",
            ["ContentJP"] = "今の私には、叶いませぬ。たとえ枯栄の術にて穢れを祓えようとも、年深き障りにはなお及び難く……非力を恥じるばかりでございます。",
            ["DialogueId"] = 12062706,
            ["GUID"] = "1E329DB4",
            ["NextDialogue"] = 12062707,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329DB4",
            },
        [12062707] = {
            ["Content"] = "但我既然选择好好继承家姐的药学衣钵，便打算从拜访那些泽生阁未能完全治愈的患者开始。折磨他们的疑难杂症，也许有朝一日，可以在我手中克服。",
            ["ContentJP"] = "されど、姉の薬道を継ぐと決めたからには――まずは、<Default note=\"text:たくせいかく\">澤生閣</>ですら救い切れなかった御方を訪ね、積年の痛みに向き合う所存にございます。いつの日か、必ずやこの手で……乗り越えてみせとうございます。",
            ["DialogueId"] = 12062707,
            ["GUID"] = "1E329DDE",
            ["NextDialogue"] = 12062708,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329DDE",
            },
        [12062708] = {
            ["Content"] = "不愧是你，好惊人的行动力。",
            ["ContentJP"] = "さすが……行動の早さには毎回驚かされるよ。",
            ["DialogueId"] = 12062708,
            ["GUID"] = "1E329E08",
            ["NextDialogue"] = 12062709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E08",
            },
        [12062709] = {
            ["Content"] = "那是因为你不曾见过家姐，与她的果决相比，我还差得远。",
            ["ContentJP"] = "……あなたは姉をご存じないから、そう仰るのです。あの方のご決断の速さと比べれば、私など、まだまだ未熟の極みでございますよ。",
            ["DialogueId"] = 12062709,
            ["GUID"] = "1E329E32",
            ["NextDialogue"] = 12062710,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E32",
            },
        [12062710] = {
            ["Content"] = "那……如果——我不是故意乌鸦嘴，我只是说如果——",
            ["ContentJP"] = "じゃあ、もし――いえ、別に不吉なことを言いたいわけじゃないんだけど……",
            ["DialogueId"] = 12062710,
            ["GUID"] = "1E329E5C",
            ["NextDialogue"] = 12062711,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E5C",
            },
        [12062711] = {
            ["Content"] = "如果那些病你一辈子都治不好，该怎么办？",
            ["ContentJP"] = "もしも、その病が一生治らなかったら……どうするの？",
            ["DialogueId"] = 12062711,
            ["GUID"] = "1E329E86",
            ["NextDialogue"] = 12062712,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329E86",
            },
        [12062712] = {
            ["Content"] = "呵呵……那自然有下一个我接下这份使命。就像泽生阁的那些药师，姐姐把使命传给她的学生，她的学生又传给新的学生。",
            ["ContentJP"] = "ふふ……そのときは、次なる私がこの志を継ぐだけにございます。<Default note=\"text:たくせいかく\">澤生閣</>の薬師方も姉も、弟子へ、またその弟子へと志を託されてゆきました。",
            ["DialogueId"] = 12062712,
            ["GUID"] = "1E329EB0",
            ["NextDialogue"] = 12062713,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329EB0",
            },
        [12062713] = {
            ["Content"] = "更何况，对扶疏而言，还有一件极为重要之事。",
            ["ContentJP"] = "それに――もうひとつ、どうしても伝えたいことがございます。",
            ["DialogueId"] = 12062713,
            ["GUID"] = "1E329EDA",
            ["NextDialogue"] = 12062714,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329EDA",
            },
        [12062714] = {
            ["Content"] = "我希望那些病人知道，他们并不是独自与伤痛抗争——世界上还有另一个人，永远不会放弃他们。",
            ["ContentJP"] = "それは患者さまたちに、決しておひとりではないのだと知っていただくこと。この世には、あなたを見捨てぬ者が、必ずおるのだと。",
            ["DialogueId"] = 12062714,
            ["GUID"] = "1E329F04",
            ["NextDialogue"] = 12062715,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F04",
            },
        [12062715] = {
            ["Content"] = "如此，他们自己才不会轻言放弃。",
            ["ContentJP"] = "その想いがあれば、人は自らを見限らずにすみましょう。",
            ["DialogueId"] = 12062715,
            ["GUID"] = "1E329F2E",
            ["NextDialogue"] = 12062716,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F2E",
            },
        [12062716] = {
            ["Content"] = "……不放弃……",
            ["ContentJP"] = "……見限らずに……",
            ["DialogueId"] = 12062716,
            ["GUID"] = "1E329F58",
            ["NextDialogue"] = 12062717,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F58",
            },
        [12062717] = {
            ["Content"] = "即使前路多艰，希望微茫？",
            ["ContentJP"] = "どんなに道が険しくても、どんなに希望が薄くても？",
            ["DialogueId"] = 12062717,
            ["GUID"] = "1E329F82",
            ["NextDialogue"] = 12062718,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329F82",
            },
        [12062718] = {
            ["Content"] = "即使前路多艰，希望微茫。",
            ["ContentJP"] = "はい。歩みを止めなければ、夜は必ず明けるのです。",
            ["DialogueId"] = 12062718,
            ["GUID"] = "1E329FAC",
            ["NextDialogue"] = 12062719,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329FAC",
            },
        [12062719] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………（目を閉じる）",
            ["DialogueId"] = 12062719,
            ["GUID"] = "1E329FD6",
            ["NextDialogue"] = 12062720,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E329FD6",
            },
        [12062720] = {
            ["Content"] = "姑姑……你要去哪？！为什么不带上我！",
            ["ContentJP"] = "叔母さん……どこへ行くの？どうして連れていってくれないの！",
            ["DialogueId"] = 12062720,
            ["GUID"] = "1E32A000",
            ["NextDialogue"] = 12062721,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A000",
            },
        [12062721] = {
            ["Content"] = "对不起啊，小苏。姑姑如果继续留在这里，只会拖累你和你的母亲。",
            ["ContentJP"] = "ごめんね、スーちゃん。私がここにいれば、あなたとお母さんを危険に巻き込んでしまうわ。",
            ["DialogueId"] = 12062721,
            ["GUID"] = "1E32A02A",
            ["NextDialogue"] = 12062722,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A02A",
            },
        [12062722] = {
            ["Content"] = "为什么？是因为那些坏人要来抓姑姑吗？",
            ["ContentJP"] = "どうして？悪い人たちが、叔母さんを捕まえにくるの？",
            ["DialogueId"] = 12062722,
            ["GUID"] = "1E32A054",
            ["NextDialogue"] = 12062723,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A054",
            },
        [12062723] = {
            ["Content"] = "不，他们不是坏人。",
            ["ContentJP"] = "……あの人たちは悪人なんかじゃない。",
            ["DialogueId"] = 12062723,
            ["GUID"] = "1E32A07E",
            ["NextDialogue"] = 12062724,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A07E",
            },
        [12062724] = {
            ["Content"] = "虽然他们给小鸟儿戴上了黄金的脚链，但他们心里是为了小鸟儿好。",
            ["ContentJP"] = "ただ、小鳥に黄金の足枷をはめて「そのほうが安全」と信じているだけ。",
            ["DialogueId"] = 12062724,
            ["GUID"] = "1E32A0A8",
            ["NextDialogue"] = 12062725,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A0A8",
            },
        [12062725] = {
            ["Content"] = "那姑姑为什么要走？姑姑你在做的事难道不是能够造福大家的好事吗？",
            ["ContentJP"] = "でも叔母さんがやってることって、みんなの役に立つ良いことなんでしょう？だったら、行く必要なんてない！",
            ["DialogueId"] = 12062725,
            ["GUID"] = "1E32A0D2",
            ["NextDialogue"] = 12062726,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A0D2",
            },
        [12062726] = {
            ["Content"] = "当然了。因为小鸟儿自己知道，比起黄金的锁链，她更想要辽阔的天空，还有无拘无束、自在飞翔的未来。",
            ["ContentJP"] = "もちろん、良いことよ。でもね……鳥が本当に欲しいのは、輝く鎖じゃなくて――果てしない空。自由に羽ばたける未来なの。",
            ["DialogueId"] = 12062726,
            ["GUID"] = "1E32A0FC",
            ["NextDialogue"] = 12062727,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A0FC",
            },
        [12062727] = {
            ["Content"] = "如果那天真的到来了，我们小苏就不用被关在宅子里，人们也可以更加尽力去开发机枢术，研究出更多造福大家的技术。",
            ["ContentJP"] = "もしその日が本当に訪れたなら、スーちゃんはもう閉じ込められることなく、人々もまた、<Default note=\"text:きすう\">機枢</>術を思う存分に発展させられるでしょう。",
            ["DialogueId"] = 12062727,
            ["GUID"] = "1E32A126",
            ["NextDialogue"] = 12062728,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A126",
            },
        [12062728] = {
            ["Content"] = "姑姑你那么厉害，他们也不是坏人，那么是不是只要你证明给他们看，机枢是非常非常了不起的好东西，你们就能和好了？",
            ["ContentJP"] = "叔母さんはすごく強いし、あの人たちも悪い人じゃないなら……それを証明すればきっと、仲直りできるよね？",
            ["DialogueId"] = 12062728,
            ["GUID"] = "1E32A150",
            ["NextDialogue"] = 12062729,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A150",
            },
        [12062729] = {
            ["Content"] = "当然——如果姑姑能做得到的话。",
            ["ContentJP"] = "そうね――私もそうしたい。",
            ["DialogueId"] = 12062729,
            ["GUID"] = "1E32A17A",
            ["NextDialogue"] = 12062730,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A17A",
            },
        [12062730] = {
            ["Content"] = "可惜，姑姑并没有那么厉害。就连我最擅长的机枢工造，小苏也很快就能超过我。",
            ["ContentJP"] = "でも、残念ながら私はそこまで立派じゃない。私が一番得意な<Default note=\"text:きすう\">機枢</>術ですら、スーちゃんなら、すぐに追い越してしまうわ。",
            ["DialogueId"] = 12062730,
            ["GUID"] = "1E32A1A4",
            ["NextDialogue"] = 12062731,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A1A4",
            },
        [12062731] = {
            ["Content"] = "幸好，我已经把我毕生所学全部教给了你。遗憾的事呀，又少了一件。",
            ["ContentJP"] = "でもそれでいいの。私は、あなたにすべてを託した。「やり残したこと」が、また一つ減ったわね。",
            ["DialogueId"] = 12062731,
            ["GUID"] = "1E32A1CE",
            ["NextDialogue"] = 12062732,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A1CE",
            },
        [12062732] = {
            ["Content"] = "呜呜……呜呜……",
            ["ContentJP"] = "うう……うっ……",
            ["DialogueId"] = 12062732,
            ["GUID"] = "1E32A1F8",
            ["NextDialogue"] = 12062733,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A1F8",
            },
        [12062733] = {
            ["Content"] = "小苏，别哭。我们约好了，如果姑姑成功改变了大风九章，就回来带上你，还有你的父亲母亲，去东郊放飞我们一起做的机巧鸟玩，好吗？",
            ["ContentJP"] = "泣かないで、スーちゃん。私たち、約束したでしょう？もし私が<Default note=\"text:たいふうきゅうしょう\">大風九章</>を変えられたら、スーちゃんとご両親を連れて、東郊で一緒に作ったからくり鳥を飛ばしに行こうって。",
            ["DialogueId"] = 12062733,
            ["GUID"] = "1E32A222",
            ["NextDialogue"] = 12062734,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A222",
            },
        [12062734] = {
            ["Content"] = "呜……那如果失败了呢？",
            ["ContentJP"] = "じゃあ……もし、失敗したら？",
            ["DialogueId"] = 12062734,
            ["GUID"] = "1E32A24C",
            ["NextDialogue"] = 12062735,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A24C",
            },
        [12062735] = {
            ["Content"] = "如果失败了，姑姑还有你啊。就算失败，至少也能告诉你，我所行的乃是错误的道路。那样你就能及时避开啦。",
            ["ContentJP"] = "そのときは……あなたに託すわ。私が間違っていたなら、その道はあなたが避けてくれればいい。",
            ["DialogueId"] = 12062735,
            ["GUID"] = "1E32A276",
            ["NextDialogue"] = 12062736,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A276",
            },
        [12062736] = {
            ["Content"] = "可要是我也错了呢……",
            ["ContentJP"] = "でも……私も間違えるかもしれないよ……",
            ["DialogueId"] = 12062736,
            ["GUID"] = "1E32A2A0",
            ["NextDialogue"] = 12062737,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A2A0",
            },
        [12062737] = {
            ["Content"] = "没关系，像我一样，你也会拥有你的学生。你可以告诉他们，不要犯你犯的错误呀。学生又会有新的学生，总有一个人能看到一切改变的那一天，不是吗？",
            ["ContentJP"] = "それでも大丈夫。あなたも、いつか弟子を持つ。その子に伝えればいいの、「私はこう間違えた」と。そのまた弟子が、また新たな誰かに伝える。きっと、いつか――変革の果てに辿り着ける者が現れるはず。",
            ["DialogueId"] = 12062737,
            ["GUID"] = "1E32A2CA",
            ["NextDialogue"] = 12062738,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A2CA",
            },
        [12062738] = {
            ["Content"] = "可、可要等那么久的话，姑姑还能看到那一天吗？",
            ["ContentJP"] = "でも……そんなのすごく長い時間がかかっちゃう……叔母さん、見れるの？",
            ["DialogueId"] = 12062738,
            ["GUID"] = "1E32A2F4",
            ["NextDialogue"] = 12062739,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A2F4",
            },
        [12062739] = {
            ["Content"] = "这就难说了……唉，真头疼呀。",
            ["ContentJP"] = "さあ、どうかしらね……ほんと、困ったわ。",
            ["DialogueId"] = 12062739,
            ["GUID"] = "1E32A31E",
            ["NextDialogue"] = 12062740,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A31E",
            },
        [12062740] = {
            ["Content"] = "为了一起看到那一天，那不就只能在我这里成功了嘛。小苏一定要好好吃饭睡觉，等着我的好消息哦。",
            ["ContentJP"] = "だったらもう、私が今ここで成功させるしかないわね。スーちゃん、ちゃんとご飯を食べて、よく眠って、元気に待っていてちょうだい。",
            ["DialogueId"] = 12062740,
            ["GUID"] = "1E32A348",
            ["NextDialogue"] = 12062741,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A348",
            },
        [12062741] = {
            ["Content"] = "……还有最后一件事……",
            ["ContentJP"] = "それと、もうひとつだけ。",
            ["DialogueId"] = 12062741,
            ["GUID"] = "1E32A372",
            ["NextDialogue"] = 12062742,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A372",
            },
        [12062742] = {
            ["Content"] = "改变必定伴随着代价。如果——我不是故意乌鸦嘴，我只是说如果——姑姑有一天犯下了什么大错……",
            ["ContentJP"] = "変革には、必ず代償がつきもの。もしも――ただの仮定だけど――私が大きな過ちを犯したとしたら……",
            ["DialogueId"] = 12062742,
            ["GUID"] = "1E32A39C",
            ["NextDialogue"] = 12062743,
            ["SpeakNpcName"] = "UI_Npc_Name_Sumuo",
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A39C",
            },
        [12062743] = {
            ["Content"] = "就也交给我吧，谁让……我是姑姑的学生呢。",
            ["ContentJP"] = "そのときは、私が引き受ける。だって……私は叔母さんの弟子だもん。",
            ["DialogueId"] = 12062743,
            ["GUID"] = "1E32A3C6",
            ["NextDialogue"] = 12062744,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A3C6",
            },
        [12062744] = {
            ["Content"] = "……我知道了……",
            ["ContentJP"] = "……そうか……",
            ["DialogueId"] = 12062744,
            ["GUID"] = "1E32A3F0",
            ["NextDialogue"] = 12062745,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A3F0",
            },
        [12062745] = {
            ["Content"] = "……我知道该做什么了，姑姑。",
            ["ContentJP"] = "……何をすべきか……やっとわかったよ……叔母さん。",
            ["DialogueId"] = 12062745,
            ["GUID"] = "1E32A41A",
            ["NextDialogue"] = 12062746,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A41A",
            },
        [12062746] = {
            ["Content"] = "{nickname}，刚刚的我可能是个落荒而逃的胆小鬼。但现在不一样了！",
            ["ContentJP"] = "{nickname}、さっきまでの私は――ただ逃げていただけの臆病者だった。でも今は違う！",
            ["DialogueId"] = 12062746,
            ["GUID"] = "1E32A444",
            ["NextDialogue"] = 12062747,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A444",
            },
        [12062747] = {
            ["Content"] = "现在我有一件很重要很重要的事情要拜托你！",
            ["ContentJP"] = "お願い、どうしてもあんたに頼みたい、大事な、大事なことがあるの！",
            ["DialogueId"] = 12062747,
            ["GUID"] = "1E32A46E",
            ["NextDialogue"] = 12062748,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A46E",
            },
        [12062748] = {
            ["Content"] = "不愧是苏乙姑娘，行事风风火火。这样的人无论跌入何种低谷都能振作起来吧。",
            ["ContentJP"] = "……さすがはスーイーさん。お心のままに風を巻かれるそのご様子、まことに爽快にございます。",
            ["DialogueId"] = 12062748,
            ["GUID"] = "1E32A498",
            ["NextDialogue"] = 12062749,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A498",
            },
        [12062749] = {
            ["Content"] = "苏乙姑娘虽并非药师，但我能隐隐察觉……她似乎也想以自己的方式，治疗世界上的另一种伤痛。",
            ["ContentJP"] = "あの方は薬師ではございませぬが……それでも、私には感じられました。スーイーさんは、御自身のやり方で――世の中に満ちる、別種の痛みを癒やそうとしておられるのだと。",
            ["DialogueId"] = 12062749,
            ["GUID"] = "1E32A4C2",
            ["NextDialogue"] = 12062750,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A4C2",
            },
        [12062750] = {
            ["Content"] = "并非肉体之痛，而是心间之痛。",
            ["ContentJP"] = "それは、身体ではなく……心に刻まれた痛み。",
            ["DialogueId"] = 12062750,
            ["GUID"] = "1E32A4EC",
            ["NextDialogue"] = 12062751,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A4EC",
            },
        [12062751] = {
            ["Content"] = "但，即便方式不同，也仍然有人与我们走在相似的道路上，接下来的路，我们不会感到孤独了吧，姐姐。",
            ["ContentJP"] = "たとえ道が異なれど――それでも、共に歩む者が在るということは……きっと、私たちの旅路も、これより先、孤独ではございませんね……姉さん。",
            ["DialogueId"] = 12062751,
            ["GUID"] = "1E32A516",
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120627/1E32A516",
            },
        [12062801] = {
            ["Content"] = "呼啊——我说，比赛快开场了，别的队伍三三两两都已经入场了，她真的还会来吗？",
            ["ContentJP"] = "ふあぁ～～……なぁ、試合もうすぐ始まるんじゃねぇの？ ほかのチームはもう中に入ってるし……ほんとに、あの子来るのかなぁ？",
            ["DialogueId"] = 12062801,
            ["GUID"] = "1E32AD4A",
            ["NextDialogue"] = 12062802,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AD4A",
            },
        [12062802] = {
            ["Content"] = "再等五分钟……五分钟就好。",
            ["ContentJP"] = "あと……五分だけ待とう。",
            ["DialogueId"] = 12062802,
            ["GUID"] = "1E32AD74",
            ["NextDialogue"] = 12062803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AD74",
            },
        [12062803] = {
            ["Content"] = "如果那时候苏乙还没能赶过来，我们就先进场。",
            ["ContentJP"] = "もしそれでもスーイーが来なかったら、先に入場しよう。",
            ["DialogueId"] = 12062803,
            ["GUID"] = "1E32AD9E",
            ["NextDialogue"] = 12062804,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AD9E",
            },
        [12062804] = {
            ["Content"] = "喂喂，{nickname}，苏乙那家伙之前都和你说了什么啊？神神秘秘的。",
            ["ContentJP"] = "やれやれ……ところで{nickname}、スーイーと何話してたの？やけに真剣な顔してたけど。",
            ["DialogueId"] = 12062804,
            ["GUID"] = "1E32ADC8",
            ["NextDialogue"] = 12062805,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32ADC8",
            },
        [12062805] = {
            ["Content"] = "现在我有一件很重要很重要的事情要拜托你！",
            ["ContentJP"] = "お願い、どうしてもあんたに頼みたい、大事な、大事なことがあるの！",
            ["DialogueId"] = 12062805,
            ["GUID"] = "1E32ADF2",
            ["NextDialogue"] = 12062806,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32ADF2",
            },
        [12062806] = {
            ["Content"] = "你说，我在听。",
            ["ContentJP"] = "うん。",
            ["DialogueId"] = 12062806,
            ["GUID"] = "1E32AE1C",
            ["NextDialogue"] = 12062807,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE1C",
            },
        [12062807] = {
            ["Content"] = "我已经想清楚自己该做什么了。我必须现在立刻马上去，一分一秒都不能耽搁！",
            ["ContentJP"] = "やっとわかったの。私が、いま何をすべきか――もう一分、一秒でも無駄にできない……すぐ行かなきゃ！",
            ["DialogueId"] = 12062807,
            ["GUID"] = "1E32AE46",
            ["NextDialogue"] = 12062808,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE46",
            },
        [12062808] = {
            ["Content"] = "我会尽量在比赛前回来，但万一没能赶上的话，只能拜托你们先入场了。",
            ["ContentJP"] = "できる限り試合までに戻るつもり。でも、もし間に合わなかったら……そのときは、ごめんだけど先に出ててほしい。",
            ["DialogueId"] = 12062808,
            ["GUID"] = "1E32AE70",
            ["NextDialogue"] = 12062809,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE70",
            },
        [12062809] = {
            ["Content"] = "明明大家是因为我才参赛，我却擅自去忙自己的事情，真的非常对不起……",
            ["ContentJP"] = "みんなを巻き込んだのは私なのに、自分勝手で……ほんと、ごめん……",
            ["DialogueId"] = 12062809,
            ["GUID"] = "1E32AE9A",
            ["NextDialogue"] = 12062810,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AE9A",
            },
        [12062810] = {
            ["Content"] = "没关系。现在塔比瑟回来了，就算你真的缺席了这场比赛，她也能替补上场。",
            ["ContentJP"] = "大丈夫。今はタビテも戻ってきてるし、スーイーが欠場しても代わりはちゃんといる。",
            ["DialogueId"] = 12062810,
            ["GUID"] = "1E32AEC4",
            ["NextDialogue"] = 12062811,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AEC4",
            },
        [12062811] = {
            ["Content"] = "比起这个，我更高兴你找到了自己该做的事情。",
            ["ContentJP"] = "それよりも、自分のやるべきことを優先するといい。",
            ["DialogueId"] = 12062811,
            ["GUID"] = "1E32AEEE",
            ["NextDialogue"] = 12062812,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AEEE",
            },
        [12062812] = {
            ["Content"] = "……谢谢。",
            ["ContentJP"] = "……ありがとう。",
            ["DialogueId"] = 12062812,
            ["GUID"] = "1E32AF18",
            ["NextDialogue"] = 12062813,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF18",
            },
        [12062813] = {
            ["Content"] = "仔细想想，之前的我又迷茫又偏执，你却愿意陪着这样的我胡闹。但我可不能再这样一直不像话下去了！",
            ["ContentJP"] = "思えば、私はずっと迷ってばかりだったのに、あんたはいつも付き合ってくれたよね。でも、もう甘えてばかりじゃいられない！",
            ["DialogueId"] = 12062813,
            ["GUID"] = "1E32AF42",
            ["NextDialogue"] = 12062814,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF42",
            },
        [12062814] = {
            ["Content"] = "{nickname}，也是时候让你看到我的另外一面了。认准了一件事情就不撞南墙不回头，闪闪发光的那一面！",
            ["ContentJP"] = "{nickname}に見せてあげる。私が信じた道を突き進む姿――本気で、ぶつかっていく、もう一つの私を！",
            ["DialogueId"] = 12062814,
            ["GUID"] = "1E32AF6C",
            ["NextDialogue"] = 12062815,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF6C",
            },
        [12062815] = {
            ["Content"] = "正确的事，什么时候开始做都不算晚，你说对吗？",
            ["ContentJP"] = "正しいことって、きっといつ始めたって遅くないよね？……そう思わない？",
            ["DialogueId"] = 12062815,
            ["GUID"] = "1E32AF96",
            ["NextDialogue"] = 12062816,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AF96",
            },
        [12062816] = {
            ["Content"] = "如此一来，我们也不能辜负苏乙的决心了。",
            ["ContentJP"] = "そうと決まれば、我々も応えねばなるまい。スーイーの決意に。",
            ["DialogueId"] = 12062816,
            ["GUID"] = "1E32AFC0",
            ["NextDialogue"] = 12062817,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AFC0",
            },
        [12062817] = {
            ["Content"] = "嘻嘻，既然这样，我可不能让她小瞧了。没有那家伙，我们也能轻轻松松地拿下胜利嘛，到时候再向她要报酬好了——我要让她请我把八珍楼的所有菜吃个遍！",
            ["ContentJP"] = "キキキ、ならこっちも本気出さねぇとな！あの子抜きでも、しっかり勝って……あとで恩に着せてやろうっと。報酬は<Default note=\"text:はっちんろう\">八珍楼</>のメニュー、ぜ～んぶで♪",
            ["DialogueId"] = 12062817,
            ["GUID"] = "1E32AFEA",
            ["NextDialogue"] = 12062818,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32AFEA",
            },
        [12062818] = {
            ["Content"] = "嗯。就算身处不同的赛场，但是大家都在为自己的目标而奋斗，这样就好。",
            ["ContentJP"] = "うん。たとえ今は別の場所にいても、みんな、それぞれの戦いに挑んでいる。これで……いいんだよ。",
            ["DialogueId"] = 12062818,
            ["GUID"] = "1E32B014",
            ["NextDialogue"] = 12062819,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B014",
            },
        [12062819] = {
            ["Content"] = "走吧，我们很快就会再次和苏乙会合的——以胜者的姿势。",
            ["ContentJP"] = "行こう。次に会うときは――勝者の顔で。",
            ["DialogueId"] = 12062819,
            ["GUID"] = "1E32B03E",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B03E",
            },
        [12062820] = {
            ["Content"] = "最后果然还是没有赶上……",
            ["ContentJP"] = "結局、間に合わなかったか……",
            ["DialogueId"] = 12062820,
            ["GUID"] = "1E32B068",
            ["NextDialogue"] = 12062821,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B068",
            },
        [12062821] = {
            ["Content"] = "不过就算没有我，{nickname}他们也可以顺顺利利的吧。",
            ["ContentJP"] = "でも、{nickname}たちなら、きっと大丈夫。",
            ["DialogueId"] = 12062821,
            ["GUID"] = "1E32B092",
            ["NextDialogue"] = 12062822,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B092",
            },
        [12062822] = {
            ["Content"] = "该把做好的东西送过去给小安了。",
            ["ContentJP"] = "それより……これをあの子に届けに行かないと。",
            ["DialogueId"] = 12062822,
            ["GUID"] = "1E32B0BC",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120628/1E32B0BC",
            },
        [12062901] = {
            ["Content"] = "你好，请问有人在家吗……？",
            ["ContentJP"] = "あの……どなたか、ご在宅でしょうか……？（ノック）",
            ["DialogueId"] = 12062901,
            ["GUID"] = "1E32BDB2",
            ["NextDialogue"] = 12062902,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BDB2",
            },
        [12062902] = {
            ["Content"] = "小安，我为你赶制了一副义肢，希望可以帮上忙……",
            ["ContentJP"] = "アンくん……これは、君のために作った義肢なの。少しでも助けになればと思って……",
            ["DialogueId"] = 12062902,
            ["GUID"] = "1E32BDDC",
            ["NextDialogue"] = 12062903,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BDDC",
            },
        [12062903] = {
            ["Content"] = "我知道这弥补不了已经造成的伤害，但是……请至少让我尝试一下！",
            ["ContentJP"] = "もちろん、これだけじゃ償えない。でも……お願い。せめて――この想いだけでも、受け取って……！",
            ["DialogueId"] = 12062903,
            ["GUID"] = "1E32BE06",
            ["NextDialogue"] = 12062904,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE06",
            },
        [12062904] = {
            ["Content"] = "果然还是不行吗……",
            ["ContentJP"] = "やっぱり、ダメなのかな……",
            ["DialogueId"] = 12062904,
            ["GUID"] = "1E32BE30",
            ["NextDialogue"] = 12062905,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE30",
            },
        [12062905] = {
            ["Content"] = "……来人啊……有谁在吗…………",
            ["ContentJP"] = "……誰か……誰かいませんか…………（かすれた弱い声）",
            ["DialogueId"] = 12062905,
            ["GUID"] = "1E32BE5A",
            ["NextDialogue"] = 12062906,
            ["SpeakNpcId"] = 250017,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE5A",
            },
        [12062906] = {
            ["Content"] = "谁？",
            ["ContentJP"] = "ん？",
            ["DialogueId"] = 12062906,
            ["GUID"] = "1E32BE84",
            ["NextDialogue"] = 12062907,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BE84",
            },
        [12062907] = {
            ["Content"] = "等等……这个熟悉的声音，难不成是……",
            ["ContentJP"] = "この声……まさか！",
            ["DialogueId"] = 12062907,
            ["GUID"] = "1E32BEAE",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120629/1E32BEAE",
            },
        [12063001] = {
            ["Content"] = "……太好了，终于有人来了！！",
            ["ContentJP"] = "……よかった……やっと……誰か来てくれた……！（泣き声）",
            ["DialogueId"] = 12063001,
            ["GUID"] = "1E32CE1A",
            ["NextDialogue"] = 12063002,
            ["RelatedWikiId"] = {
                [1] = 203004,
                [2] = 203009,
                [3] = 201029,
                [4] = 103001,
                [5] = 203013,
                [6] = 203014,
                [7] = 408018,
                [8] = 403009,
                },
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE1A",
            },
        [12063002] = {
            ["Content"] = "小安？到底发生什么事了？！",
            ["ContentJP"] = "アンくん！？どうしたの！？",
            ["DialogueId"] = 12063002,
            ["GUID"] = "1E32CE44",
            ["NextDialogue"] = 12063003,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE44",
            },
        [12063003] = {
            ["Content"] = "苏乙姐姐！拜托你，可以去阻止阿姨吗！！",
            ["ContentJP"] = "スーイーお姉さん……お願い、おばさんを止めて……！（泣きながら）",
            ["DialogueId"] = 12063003,
            ["GUID"] = "1E32CE6E",
            ["NextDialogue"] = 12063004,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE6E",
            },
        [12063004] = {
            ["Content"] = "我听到阿姨和她的朋友们聊天，他们要去袭击赛场，这样就可以栽赃姐姐还有更多人！我想劝阿姨不要这样做，可是她不仅不听我的话，还把我关了起来！！",
            ["ContentJP"] = "さっき、おばさんが友だちと話してるのを聞いちゃったの。試合会場を襲って、お姉さんたちに罪をかぶせようとしてるって！止めようとしたけど、聞いてくれなくて……ここに閉じ込められちゃったんだ……！（泣き声）",
            ["DialogueId"] = 12063004,
            ["GUID"] = "1E32CE98",
            ["NextDialogue"] = 12063005,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CE98",
            },
        [12063005] = {
            ["Content"] = "袭击赛场？糟糕！！",
            ["ContentJP"] = "――なんてこと……！",
            ["DialogueId"] = 12063005,
            ["GUID"] = "1E32CEC2",
            ["NextDialogue"] = 12063006,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CEC2",
            },
        [12063006] = {
            ["Content"] = "她最终还是走到了这一步吗！{nickname}他们，还有更多人恐怕会遇到危险！！",
            ["ContentJP"] = "彼女、本当に……そこまで……！{nickname}たちが、会場にいるみんなが……危ない！",
            ["DialogueId"] = 12063006,
            ["GUID"] = "1E32CEEC",
            ["NextDialogue"] = 12063007,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CEEC",
            },
        [12063007] = {
            ["Content"] = "谢谢你的消息，小安，我这就赶过去。",
            ["ContentJP"] = "教えてくれてありがとう！すぐに向かうわ！",
            ["DialogueId"] = 12063007,
            ["GUID"] = "1E32CF16",
            ["NextDialogue"] = 12063008,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF16",
            },
        [12063008] = {
            ["Content"] = "等等，苏乙姐姐！可以带上我吗？现在的阿姨大概听不进去你说的话！",
            ["ContentJP"] = "待って、スーイーお姉さん！僕も連れて行って！今のおばさんは、お姉さんの言葉を聞き入れてくれるかわからない……",
            ["DialogueId"] = 12063008,
            ["GUID"] = "1E32CF40",
            ["NextDialogue"] = 12063009,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF40",
            },
        [12063009] = {
            ["Content"] = "拜托了，请让我一起去吧！我想阻止阿姨走向最坏的结局！",
            ["ContentJP"] = "でも、僕なら……僕なら、止められるかもしれないの！",
            ["DialogueId"] = 12063009,
            ["GUID"] = "1E32CF6A",
            ["NextDialogue"] = 12063010,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF6A",
            },
        [12063010] = {
            ["Content"] = "好，那我背着你。你小心点不要掉下来。",
            ["ContentJP"] = "わかった。一緒に行こう。私が背負うから、しっかりつかまっててね。",
            ["DialogueId"] = 12063010,
            ["GUID"] = "1E32CF94",
            ["NextDialogue"] = 12063011,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CF94",
            },
        [12063011] = {
            ["Content"] = "与此同时，另一边……",
            ["ContentJP"] = "その頃、試合会場では……",
            ["DialogueId"] = 12063011,
            ["GUID"] = "1E32CFBE",
            ["IsBlack"] = 1,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CFBE",
            },
        [12063012] = {
            ["Content"] = "你们先保护民众，我将他引走。",
            ["ContentJP"] = "先に市民を守れ！ こいつは俺が引きつける！",
            ["DialogueId"] = 12063012,
            ["GUID"] = "1E32CFBF",
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120630/1E32CFBF",
            },
        [12063101] = {
            ["Content"] = "煜明……！",
            ["ContentJP"] = "ユーミン……！",
            ["DialogueId"] = 12063101,
            ["GUID"] = "1E32DE82",
            ["NextDialogue"] = 12063102,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DE82",
            },
        [12063102] = {
            ["Content"] = "喂喂，这扇门压根打不开，一条缝隙都没有，你们华胥的门都这么结实的吗？！",
            ["ContentJP"] = "ねえちょっと、この扉ビクともしねぇんだけど！？隙間ひとつねぇじゃん！<Default note=\"text:カショ\">華胥</>の門ってみんなこんなにガッチガチなのかよ！？",
            ["DialogueId"] = 12063102,
            ["GUID"] = "1E32DEAC",
            ["NextDialogue"] = 12063103,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DEAC",
            },
        [12063103] = {
            ["Content"] = "……还是来晚了一步！！",
            ["ContentJP"] = "やっぱり……間に合わなかった……！",
            ["DialogueId"] = 12063103,
            ["GUID"] = "1E32DED6",
            ["NextDialogue"] = 12063104,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DED6",
            },
        [12063104] = {
            ["Content"] = "苏乙！！巨阙突然从山体里出现，煜明为了阻止它被困在里面了！",
            ["ContentJP"] = "スーイー！<Default note=\"text:こけつ\">巨闕</>が突然、山の中から姿を現して……ユーミンがそれを食い止めようとして、中に閉じ込められた{性别:んだ|の}！！",
            ["DialogueId"] = 12063104,
            ["GUID"] = "1E32DF00",
            ["NextDialogue"] = 12063105,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF00",
            },
        [12063105] = {
            ["Content"] = "这扇门看起来像是机枢派的技术，你知道有什么方法能打开它吗？！",
            ["ContentJP"] = "この扉……どう見ても<Default note=\"text:きすうは\">機枢派</>の技術だよね？ 何か開ける方法、知らない？",
            ["DialogueId"] = 12063105,
            ["GUID"] = "1E32DF2A",
            ["NextDialogue"] = 12063106,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF2A",
            },
        [12063106] = {
            ["Content"] = "这里的地宫是机枢派的旧址，与偃隐宫为同一前辈设计。比起外力破解，找到始作俑者会更加迅速。",
            ["ContentJP"] = "ここは<Default note=\"text:きすうは\">機枢派</>の旧跡、<Default note=\"text:えんいんきゅう\">偃隠宮</>と同じ設計者によるもの。外部から無理やりこじ開けるより――設計を知る者を探した方が早いわ。（考え込む）",
            ["DialogueId"] = 12063106,
            ["GUID"] = "1E32DF54",
            ["NextDialogue"] = 12063107,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF54",
            },
        [12063107] = {
            ["Content"] = "始作俑者？",
            ["ContentJP"] = "設計を知る者……？",
            ["DialogueId"] = 12063107,
            ["GUID"] = "1E32DF7E",
            ["NextDialogue"] = 12063108,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DF7E",
            },
        [12063108] = {
            ["Content"] = "没错，潇湘，以及她的同伴——计划没有按他们预想中去实施，这伙人一定还徘徊在附近寻找机会。",
            ["ContentJP"] = "そう、ショウと――その仲間たち。計画が思い通りに進まなかった今、まだ近くで機会を窺っているはず。",
            ["DialogueId"] = 12063108,
            ["GUID"] = "1E32DFA8",
            ["NextDialogue"] = 12063109,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DFA8",
            },
        [12063109] = {
            ["Content"] = "喂喂，你怎么突然知道了这么多情报？",
            ["ContentJP"] = "ちょっとぉ？ぜんっぜん頭回んねぇんだけど！？",
            ["DialogueId"] = 12063109,
            ["GUID"] = "1E32DFD2",
            ["NextDialogue"] = 12063110,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DFD2",
            },
        [12063110] = {
            ["Content"] = "来不及解释了，跟我来。",
            ["ContentJP"] = "後で説明する。今はついてきて。",
            ["DialogueId"] = 12063110,
            ["GUID"] = "1E32DFFC",
            ["NextDialogue"] = 12063111,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32DFFC",
            },
        [12063111] = {
            ["Content"] = "煜明还困在里面。现在耽误的每分每秒都会增加他受伤的风险！",
            ["ContentJP"] = "ユーミンが――まだ中で、ひとり戦ってるのよ！早く見つけないと。",
            ["DialogueId"] = 12063111,
            ["GUID"] = "1E32E026",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120631/1E32E026",
            },
        [12063201] = {
            ["Content"] = "找到你了。",
            ["ContentJP"] = "見つけた。",
            ["DialogueId"] = 12063201,
            ["GUID"] = "1E32EEEA",
            ["NextDialogue"] = 12063202,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 201029,
                [3] = 103001,
                [4] = 203013,
                [5] = 203014,
                [6] = 408018,
                [7] = 403009,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EEEA",
            },
        [12063202] = {
            ["Content"] = "快把地宫钥匙交出来，现在还没有人受伤，一切还来得及。",
            ["ContentJP"] = "地下宮殿の鍵を渡して。まだ誰も傷ついていない。今ならまだ引き返せる。",
            ["DialogueId"] = 12063202,
            ["GUID"] = "1E32EF14",
            ["NextDialogue"] = 12063203,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF14",
            },
        [12063203] = {
            ["Content"] = "呵，被你逮到是我技输一筹，我认输。",
            ["ContentJP"] = "……ふふ、捕まったのはこちらの落ち度。負けを認めるわ。",
            ["DialogueId"] = 12063203,
            ["GUID"] = "1E32EF3E",
            ["NextDialogue"] = 12063204,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF3E",
            },
        [12063204] = {
            ["Content"] = "但若是想让我交出地宫钥匙，还是死了这条心吧。我与你没什么话好说的。",
            ["ContentJP"] = "でも――鍵を渡す気はない。それだけは諦めなさい。",
            ["DialogueId"] = 12063204,
            ["GUID"] = "1E32EF68",
            ["NextDialogue"] = 12063205,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF68",
            },
        [12063205] = {
            ["Content"] = "够了……你们就恨飘零人恨到即使伤及无辜者的性命也在所不惜吗？！",
            ["ContentJP"] = "いい加減にして……あんたたちは、流れ者への憎しみのためなら、無関係な命さえ平気で巻き込むの？",
            ["DialogueId"] = 12063205,
            ["GUID"] = "1E32EF92",
            ["NextDialogue"] = 12063206,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EF92",
            },
        [12063206] = {
            ["Content"] = "如此大义凛然的话从那个苏暮鹧的侄女口中听到，真是让人想笑。",
            ["ContentJP"] = "「正義」を語るってるのが、あのムーチョの姪とはね。笑わせないで。",
            ["DialogueId"] = 12063206,
            ["GUID"] = "1E32EFBC",
            ["NextDialogue"] = 12063207,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EFBC",
            },
        [12063207] = {
            ["Content"] = "如果你和姑姑曾经共事过，你就应该知道她做出那些事究竟是为了什么。",
            ["ContentJP"] = "あんたが叔母と共に在ったなら……なぜ、彼女を理解しようとしないの？",
            ["DialogueId"] = 12063207,
            ["GUID"] = "1E32EFE6",
            ["NextDialogue"] = 12063208,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32EFE6",
            },
        [12063208] = {
            ["Content"] = "那般荒诞的理想，就算知道了又能如何？",
            ["ContentJP"] = "あんな夢物語、理解したところで現実は何も変わらない。",
            ["DialogueId"] = 12063208,
            ["GUID"] = "1E32F010",
            ["NextDialogue"] = 12063209,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F010",
            },
        [12063209] = {
            ["Content"] = "可如今烛阴归位，大风九章迎来改制——你口中荒诞的理想，如今已经成了现实！",
            ["ContentJP"] = "でも、今や<Default note=\"text:しょくいん\">燭陰</>は戻り、<Default note=\"text:たいふうきゅうしょう\">大風九章</>は再編を迎えた。叔母が掲げた夢物語は、現実になりつつあるのよ！",
            ["DialogueId"] = 12063209,
            ["GUID"] = "1E32F03A",
            ["NextDialogue"] = 12063210,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F03A",
            },
        [12063210] = {
            ["Content"] = "但她所犯下的罪行，她所造成的伤害，绝不会因此一笔勾销。",
            ["ContentJP"] = "だからって、あの女が犯した罪と、その代償まで帳消しになるとでも？",
            ["DialogueId"] = 12063210,
            ["GUID"] = "1E32F064",
            ["NextDialogue"] = 12063211,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F064",
            },
        [12063211] = {
            ["Content"] = "……你说得对。",
            ["ContentJP"] = "……そうね。",
            ["DialogueId"] = 12063211,
            ["GUID"] = "1E32F08E",
            ["NextDialogue"] = 12063212,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F08E",
            },
        [12063212] = {
            ["Content"] = "……！！",
            ["ContentJP"] = "……！！",
            ["DialogueId"] = 12063212,
            ["GUID"] = "1E32F0B8",
            ["NextDialogue"] = 12063213,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F0B8",
            },
        [12063213] = {
            ["Content"] = "所以姑姑她，已经得到了应有的制裁。你的复仇早就结束了……",
            ["ContentJP"] = "だからこそ、叔母は裁かれた。命を賭して、責任を果たしたのよ。あんたの復讐は――とっくに終わってる。",
            ["DialogueId"] = 12063213,
            ["GUID"] = "1E32F0E2",
            ["NextDialogue"] = 12063214,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F0E2",
            },
        [12063214] = {
            ["Content"] = "够了，我对今日的所作所为问心无愧。你说再多也只是徒劳。",
            ["ContentJP"] = "黙りなさい。私はこの行いを後悔しない。何を言われようと、変わらない。",
            ["DialogueId"] = 12063214,
            ["GUID"] = "1E32F10C",
            ["NextDialogue"] = 12063215,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F10C",
            },
        [12063215] = {
            ["Content"] = "问心无愧吗？那你听听这个人说什么吧。",
            ["ContentJP"] = "では……彼の言葉ならどう？",
            ["DialogueId"] = 12063215,
            ["GUID"] = "1E32F136",
            ["NextDialogue"] = 12063216,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F136",
            },
        [12063216] = {
            ["Content"] = "……阿姨。",
            ["ContentJP"] = "……おばさん。",
            ["DialogueId"] = 12063216,
            ["GUID"] = "1E32F160",
            ["NextDialogue"] = 12063217,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F160",
            },
        [12063217] = {
            ["Content"] = "收手吧，我们一起回家，好吗？",
            ["ContentJP"] = "ねえ、もうやめよう？ 一緒に、帰ろう……？",
            ["DialogueId"] = 12063217,
            ["GUID"] = "1E32F18A",
            ["NextDialogue"] = 12063218,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F18A",
            },
        [12063218] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………（目をそらす）",
            ["DialogueId"] = 12063218,
            ["GUID"] = "1E32F1B4",
            ["NextDialogue"] = 12063219,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F1B4",
            },
        [12063219] = {
            ["Content"] = "……以为搬出小安就能说服我吗？",
            ["ContentJP"] = "アンを出せば、私が折れるとでも？",
            ["DialogueId"] = 12063219,
            ["GUID"] = "1E32F1DE",
            ["NextDialogue"] = 12063220,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F1DE",
            },
        [12063220] = {
            ["Content"] = "这次行动前，我早已想好了。无论成败，我都要与他断绝关系。小安今后也与我再无瓜葛。",
            ["ContentJP"] = "この計画を始める前から、覚悟はできていた。結果がどうなろうと、アンとは……もう縁を切るつもりだった。",
            ["DialogueId"] = 12063220,
            ["GUID"] = "1E32F208",
            ["NextDialogue"] = 12063221,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F208",
            },
        [12063221] = {
            ["Content"] = "听到了吗，养了你这个无亲无故的孩子十几年，我已经受够了。",
            ["ContentJP"] = "聞こえなかったの？あんたみたいな身寄りのない子、もううんざりよ。",
            ["DialogueId"] = 12063221,
            ["GUID"] = "1E32F232",
            ["NextDialogue"] = 12063222,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F232",
            },
        [12063222] = {
            ["Content"] = "不，阿姨……好好看一看我吧，看看我的腿！",
            ["ContentJP"] = "違うよ、おばさん。お願いだから……僕の足を見て。",
            ["DialogueId"] = 12063222,
            ["GUID"] = "1E32F25C",
            ["NextDialogue"] = 12063223,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F25C",
            },
        [12063223] = {
            ["Content"] = "难道是……你真的攻克了那项禁忌的技术……",
            ["ContentJP"] = "その義肢……まさか……！あの禁術を！？（スーイーの方を見る）",
            ["DialogueId"] = 12063223,
            ["GUID"] = "1E32F286",
            ["NextDialogue"] = 12063224,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F286",
            },
        [12063224] = {
            ["Content"] = "是的！这是苏乙姐姐特地来送给我的机关义肢！！有了它的帮助，以后只要再练习一下，我就能像正常人一样走路了！！",
            ["ContentJP"] = "そうだよ。これはお姉さんが、僕のために創ってくれたの。この義肢があれば……練習すれば、きっと普通に歩けるようになる！",
            ["DialogueId"] = 12063224,
            ["GUID"] = "1E32F2B0",
            ["NextDialogue"] = 12063225,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F2B0",
            },
        [12063225] = {
            ["Content"] = "但其实就算没有它，我也一直在一个人偷偷练习走路！！因为总有一天，我想用自己的双腿走到阿姨面前，让阿姨不再总是皱着眉，就算付出再多努力也没关系！！",
            ["ContentJP"] = "でもね、本当は……義肢がなくても、ずっとひとりで歩く練習をしてたんだ。いつか、自分の足でおばさんの前に立てるようにって。おばさんに、もう眉間にしわを寄せないでほしくて……ただ、それだけで頑張れたの！",
            ["DialogueId"] = 12063225,
            ["GUID"] = "1E32F2DA",
            ["NextDialogue"] = 12063226,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F2DA",
            },
        [12063226] = {
            ["Content"] = "阿姨，你知道吗，这几年来我最难过的事……并不是这条腿。",
            ["ContentJP"] = "おばさん、あのね、 僕が本当に辛かったのは、脚を失ったことじゃないんだ。",
            ["DialogueId"] = 12063226,
            ["GUID"] = "1E32F304",
            ["NextDialogue"] = 12063227,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F304",
            },
        [12063227] = {
            ["Content"] = "当我醒过来发现自己的腿已经不在的时候，我难过得要命，痛得要命……但伤口是会随着时间慢慢愈合的！",
            ["ContentJP"] = "あの日、目を覚ました時、脚がなくなってて……すごくいたかったけど、でも傷口はゆっくり癒えていった。",
            ["DialogueId"] = 12063227,
            ["GUID"] = "1E32F32E",
            ["NextDialogue"] = 12063228,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F32E",
            },
        [12063228] = {
            ["Content"] = "我最难过的是……阿姨好像永远被困在那场机关坠毁的事故里，一直无法出来，但我不想看你一直痛苦！",
            ["ContentJP"] = "いちばん苦しかったのは……あの日以来、おばさんがずっとあの事故の中に囚われたままだったこと。あの痛みに、ずっと飲み込まれてたこと。",
            ["DialogueId"] = 12063228,
            ["GUID"] = "1E32F358",
            ["NextDialogue"] = 12063229,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F358",
            },
        [12063229] = {
            ["Content"] = "阿姨总说“小安的一生都被毁了”，但不是这样的！如果把自己关在过去的笼子里，认为自己没有了幸福的资格，那样的人生才是真的被毁掉了啊……",
            ["ContentJP"] = "「アンの人生は台無しになった」って言ってたけど、僕はそう思ってない……何より恐ろしいのは、自分を閉じ込めて、もう幸せになっちゃいけないって思ってしまうことなんだよ。",
            ["DialogueId"] = 12063229,
            ["GUID"] = "1E32F382",
            ["NextDialogue"] = 12063230,
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F382",
            },
        [12063230] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 12063230,
            ["GUID"] = "1E32F3AC",
            ["NextDialogue"] = 12063231,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F3AC",
            },
        [12063231] = {
            ["Content"] = "……我们走吧。",
            ["ContentJP"] = "……行きましょう。（仲間たちへ）",
            ["DialogueId"] = 12063231,
            ["GUID"] = "1E32F3D6",
            ["NextDialogue"] = 12063232,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F3D6",
            },
        [12063232] = {
            ["Content"] = "诶？现在吗？？但是地宫钥匙明明还没有拿到……",
            ["ContentJP"] = "え？今！？鍵がまだ……！",
            ["DialogueId"] = 12063232,
            ["GUID"] = "1E32F400",
            ["NextDialogue"] = 12063233,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F400",
            },
        [12063233] = {
            ["Content"] = "她如果不愿意开口，我们在这里空耗时间也只是徒劳。不如抓紧回去找其他人打听，有没有其他能打开那扇门的法子……",
            ["ContentJP"] = "彼女が口を閉ざすなら、ここで立ち止まっても無駄よ。他の方法を探しに行くわ。誰かがきっと、別の手段を知っているはず。",
            ["DialogueId"] = 12063233,
            ["GUID"] = "1E32F42A",
            ["NextDialogue"] = 12063234,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F42A",
            },
        [12063234] = {
            ["Content"] = "……你为了复仇，将无辜的人卷入其中，成为了你最痛恨的样子，甚至罔顾小安的幸福。但我不会变成你的模样。",
            ["ContentJP"] = "……あんたは、復讐に囚われて他人を巻き込み、かつて自分が最も憎んだ存在になってしまった。アンの願いすら、踏みにじって。私は絶対に、あんたのようにはならない。（ショウの方を見る）",
            ["DialogueId"] = 12063234,
            ["GUID"] = "1E32F454",
            ["NextDialogue"] = 12063235,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F454",
            },
        [12063235] = {
            ["Content"] = "我已经发誓过，我不会再让任何人受伤，无论是出于什么样的理由。",
            ["ContentJP"] = "私は誓ったの。誰であっても、どんな理由であっても……誰かを傷つけることは、二度としないと。",
            ["DialogueId"] = 12063235,
            ["GUID"] = "1E32F47E",
            ["NextDialogue"] = 12063236,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F47E",
            },
        [12063236] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 12063236,
            ["GUID"] = "1E32F4A8",
            ["NextDialogue"] = 12063237,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F4A8",
            },
        [12063237] = {
            ["Content"] = "等等……拿着。",
            ["ContentJP"] = "……待ちなさい。",
            ["DialogueId"] = 12063237,
            ["GUID"] = "1E32F4D2",
            ["NextDialogue"] = 12063238,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F4D2",
            },
        [12063238] = {
            ["Content"] = "…………阿姨……太好了！",
            ["ContentJP"] = "……おばさん……よかった……",
            ["DialogueId"] = 12063238,
            ["GUID"] = "1E32F4FC",
            ["SpeakNpcId"] = 250017,
            ["VoiceName"] = "voice/$Locale$/story/1206/120632/1E32F4FC",
            },
        [12063301] = {
            ["Content"] = "大当家，真的不需要赶紧请动应天尉，捉拿那些贼人吗？",
            ["ContentJP"] = "当主様、<Default note=\"text:おうてんい\">応天尉</>を呼んで賊を捕らえなくてよろしいのですか？",
            ["DialogueId"] = 12063301,
            ["GUID"] = "1E32FF52",
            ["NextDialogue"] = 12063302,
            ["RelatedWikiId"] = {
                [1] = 203001,
                [2] = 405015,
                },
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FF52",
            },
        }
  end },
  { MinKey = 12063302, MaxKey = 20000903, Loader = function()
      return {
        [12063302] = {
            ["Content"] = "之前或许还有这个必要，现在却是不必了。",
            ["ContentJP"] = "先ほどまでは、そのつもりだった。けど、もう必要ないわ。",
            ["DialogueId"] = 12063302,
            ["GUID"] = "1E32FF7C",
            ["NextDialogue"] = 12063303,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FF7C",
            },
        [12063303] = {
            ["Content"] = "你没有看出来吗？局势已经明朗。看来，这届群英试终于发挥了其应有的作用。",
            ["ContentJP"] = "気づかなかったの？情勢はすでに定まりつつある――英雄大会は、ようやく本来の意義を果たしたのよ。",
            ["DialogueId"] = 12063303,
            ["GUID"] = "1E32FFA6",
            ["NextDialogue"] = 12063304,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FFA6",
            },
        [12063304] = {
            ["Content"] = "应有的作用……群英试不是用来决出胜者的吗？",
            ["ContentJP"] = "本来の……？英雄大会とは、勝者を決める場では？",
            ["DialogueId"] = 12063304,
            ["GUID"] = "1E32FFD0",
            ["NextDialogue"] = 12063305,
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FFD0",
            },
        [12063305] = {
            ["Content"] = "胜者？呵呵……输赢从来不是这场比赛的重点，群英试从一开始，就是为了创造<H>英雄</>的。",
            ["ContentJP"] = "勝敗など、枝葉にすぎないわ。この大会の本質は、<H>英雄</>を育む場にある。",
            ["DialogueId"] = 12063305,
            ["GUID"] = "1E32FFFA",
            ["NextDialogue"] = 12063306,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E32FFFA",
            },
        [12063306] = {
            ["Content"] = "能够以人的力量，人的身姿，克服内心的所有动摇，无论如何弱小迷茫也不会放弃寻求正确之路，如此，才能称为英雄之姿。",
            ["ContentJP"] = "人の姿で、己の弱さや迷いを乗り越え、正しき道を求め続けること――それこそが英雄の証よ。",
            ["DialogueId"] = 12063306,
            ["GUID"] = "1E330024",
            ["NextDialogue"] = 12063307,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330024",
            },
        [12063307] = {
            ["Content"] = "竟然还有这层用意……不愧是大当家！",
            ["ContentJP"] = "まさか……そこまで深い意味が……さすが当主様！",
            ["DialogueId"] = 12063307,
            ["GUID"] = "1E33004E",
            ["NextDialogue"] = 12063308,
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33004E",
            },
        [12063308] = {
            ["Content"] = "大当家，我有个疑问。怀远、潇湘一伙人的行迹一直在您的掌握之中。中途您有多次机会可以出手阻止他们的计划，为何您没有那样做呢？",
            ["ContentJP"] = "……でも、ひとつだけ。懸念のあったショウたちの動き、当主様は終始把握しておられましたね？途中、止める機会も幾度もあったはず。なぜ、見逃したのです？",
            ["DialogueId"] = 12063308,
            ["GUID"] = "1E330078",
            ["NextDialogue"] = 12063309,
            ["SpeakNpcId"] = 250026,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330078",
            },
        [12063309] = {
            ["Content"] = "那是因为我对他们仍怀有期待。",
            ["ContentJP"] = "彼らに、最後まで希望をかけていたからよ。",
            ["DialogueId"] = 12063309,
            ["GUID"] = "1E3300A2",
            ["NextDialogue"] = 12063310,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3300A2",
            },
        [12063310] = {
            ["Content"] = "我期待他们能够跨越迷障，放弃执行中的计划……但他们最终还是向心中的仇恨屈服了。",
            ["ContentJP"] = "願っていたの。報復ではなく、赦しを選んでくれることを。",
            ["DialogueId"] = 12063310,
            ["GUID"] = "1E3300CC",
            ["NextDialogue"] = 12063311,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3300CC",
            },
        [12063311] = {
            ["Content"] = "那些人未能战胜心中的迷障，只能说是一桩憾事。",
            ["ContentJP"] = "けど、彼らは……その憎しみに飲まれてしまった。――それだけは、残念だわ。",
            ["DialogueId"] = 12063311,
            ["GUID"] = "1E3300F6",
            ["NextDialogue"] = 12063312,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3300F6",
            },
        [12063312] = {
            ["Content"] = "走吧，我们也当去见证最后的胜利时刻了。",
            ["ContentJP"] = "行きましょう。私たちも、「結末」を見届けないとね。",
            ["DialogueId"] = 12063312,
            ["GUID"] = "1E330120",
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330120",
            },
        [12063313] = {
            ["Content"] = "……！太好了，钥匙到手了！",
            ["ContentJP"] = "やった！鍵、手に入れたぞ！",
            ["DialogueId"] = 12063313,
            ["GUID"] = "1E33014A",
            ["NextDialogue"] = 12063314,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33014A",
            },
        [12063314] = {
            ["Content"] = "加快脚步，煜明还在等着我们！不要让他久等了！",
            ["ContentJP"] = "急ごう！ユーミンが待ってる！",
            ["DialogueId"] = 12063314,
            ["GUID"] = "1E330174",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330174",
            },
        [12063315] = {
            ["Content"] = "煜明，我们来了，你还支撑得住吗！",
            ["ContentJP"] = "ユーミン！大丈夫！？",
            ["DialogueId"] = 12063315,
            ["GUID"] = "1E33019E",
            ["NextDialogue"] = 12063316,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33019E",
            },
        [12063316] = {
            ["Content"] = "并无大碍。与巨阙纠缠这一阵，我已熟悉了它的攻击方式。",
            ["ContentJP"] = "心配には及ばぬ。<Default note=\"text:こけつ\">巨闕</>の攻撃、すでに見切った。",
            ["DialogueId"] = 12063316,
            ["GUID"] = "1E3301C8",
            ["NextDialogue"] = 12063317,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3301C8",
            },
        [12063317] = {
            ["Content"] = "好，我们一起击败它！",
            ["ContentJP"] = "よし、全員で撃破するわよ！",
            ["DialogueId"] = 12063317,
            ["GUID"] = "1E3301F2",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3301F2",
            },
        [12063318] = {
            ["Content"] = "呼……这次，总算是结束了。",
            ["ContentJP"] = "ふぅ、これで……本当に、終わったのね。",
            ["DialogueId"] = 12063318,
            ["GUID"] = "1E33021C",
            ["NextDialogue"] = 12063319,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33021C",
            },
        [12063319] = {
            ["Content"] = "（热烈的鼓掌声）",
            ["ContentJP"] = "拍手喝采",
            ["DialogueId"] = 12063319,
            ["GUID"] = "1E330246",
            ["NextDialogue"] = 12063320,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330246",
            },
        [12063320] = {
            ["Content"] = "哇啊啊啊，现在是什么情况？！怎么回事，怎么这么多人？！",
            ["ContentJP"] = "う、うわっ！？な、なにこれ！？なんでこんな人いんだ！？ ちょっとぉ、いま何が起こってんだよ！",
            ["DialogueId"] = 12063320,
            ["GUID"] = "1E330270",
            ["NextDialogue"] = 12063321,
            ["SpeakNpcId"] = 250006,
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E330270",
            },
        [12063321] = {
            ["Content"] = "又是那个少年英杰！{nickname}！",
            ["ContentJP"] = "見て、またあの子だ！{nickname}殿だ！",
            ["DialogueId"] = 12063321,
            ["GUID"] = "1E33029A",
            ["NextDialogue"] = 12063322,
            ["SpeakNpcName"] = "UI_Npc_Name_Yilun",
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E33029A",
            },
        [12063322] = {
            ["Content"] = "还有那个飘零人，我就说嘛，飘零人才不是传说中青面獠牙的样子咧！那个两条大辫子的小姑娘还怪可爱的！",
            ["ContentJP"] = "それに、あの流れ者の娘もね！だから言ったじゃん、流れ者って別に鬼みたいな連中じゃないって！あのツインテの子、けっこう可愛いし！",
            ["DialogueId"] = 12063322,
            ["GUID"] = "1E3302C4",
            ["NextDialogue"] = 12063323,
            ["SpeakNpcName"] = "UI_Npc_Name_Yilun",
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3302C4",
            },
        [12063323] = {
            ["Content"] = "我从未亲眼见过飘零人，或许，他们也只是和我们一样的普通人，会迷茫，也会奋起。",
            ["ContentJP"] = "本物の流れ者を見るのは初めてだけど……たぶん、僕らと同じなんだよ。迷うし、傷つく、それでも前に進もうとしてる。",
            ["DialogueId"] = 12063323,
            ["GUID"] = "1E3302EE",
            ["SpeakNpcName"] = "UI_Npc_Name_Yilun",
            ["VoiceName"] = "voice/$Locale$/story/1206/120633/1E3302EE",
            },
        [12063401] = {
            ["Content"] = "小仆从，你们终于出来了！你们刚刚说的话做的事情，全都被围观的大家看到了。",
            ["ContentJP"] = "やっと来たか～！あんたたちが戦ってたあいだ、ここにいたみんな、ぜーんぶ見てたよ。",
            ["DialogueId"] = 12063401,
            ["GUID"] = "1E330FBA",
            ["NextDialogue"] = 12063402,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E330FBA",
            },
        [12063402] = {
            ["Content"] = "大家完全知道谁是好人，谁是坏人了！现在他们都在很激烈地讨论着你们的英雄事迹呢！",
            ["ContentJP"] = "誰が正義で誰がそうじゃないか……ようやくはっきりしたね！",
            ["DialogueId"] = 12063402,
            ["GUID"] = "1E330FE4",
            ["NextDialogue"] = 12063403,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E330FE4",
            },
        [12063403] = {
            ["Content"] = "只是赛场被搞得一团糟，这下就算要重赛恐怕也要等好久了……",
            ["ContentJP"] = "まぁ……会場は完全にめちゃくちゃになってるけどね。次の大会は、相当先になるかも。",
            ["DialogueId"] = 12063403,
            ["GUID"] = "1E33100E",
            ["NextDialogue"] = 12063404,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33100E",
            },
        [12063404] = {
            ["Content"] = "等到那个时候，恐怕我们也已经不在华胥了吧。",
            ["ContentJP"] = "その頃には、{性别:もう僕たちは華胥にはいないかもしれないな。|もう私たちは華胥にはいないかもね。}",
            ["DialogueId"] = 12063404,
            ["GUID"] = "1E331038",
            ["NextDialogue"] = 12063405,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331038",
            },
        [12063405] = {
            ["Content"] = "塔比瑟，煜明，到时候只能交给你们咯？",
            ["ContentJP"] = "タビテ、ユーミン。あとは……{性别:君たち|あなたたち}に任せるよ。",
            ["DialogueId"] = 12063405,
            ["GUID"] = "1E331062",
            ["NextDialogue"] = 12063406,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331062",
            },
        [12063406] = {
            ["Content"] = "诸位多虑了。",
            ["ContentJP"] = "その必要はありません。",
            ["DialogueId"] = 12063406,
            ["GUID"] = "1E33108C",
            ["NextDialogue"] = 12063407,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33108C",
            },
        [12063407] = {
            ["Content"] = "无论是在赛场上的优异表现，又或者是在赛场外面对挫折时的反应，你们毫无疑问，是我见过的最优秀的队伍之一。",
            ["ContentJP"] = "あなたたちの戦いぶりも、そして戦場の外で見せたその決意も……すべてを通して、私はあなたたちを「最も優れたチーム」と呼ぶに相応しいと確信しました。",
            ["DialogueId"] = 12063407,
            ["GUID"] = "1E3310B6",
            ["NextDialogue"] = 12063408,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3310B6",
            },
        [12063408] = {
            ["Content"] = "而更重要的是……你们小队面对突然出现的危机临危不惧，为他人所不能及之勇。",
            ["ContentJP"] = "でもそれ以上に、突然の危機に際して示した勇気――他者のために、恐れず立ち向かうその姿勢こそ、何より尊い。",
            ["DialogueId"] = 12063408,
            ["GUID"] = "1E3310E0",
            ["NextDialogue"] = 12063409,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3310E0",
            },
        [12063409] = {
            ["Content"] = "这等表现，司事会找不到一定要举行重赛的理由。",
            ["ContentJP"] = "このような働きを目の当たりにして、<Default note=\"text:しきじしんぱんかい \">職事審判会</>が再試合を求める理由など、どこにもありません。",
            ["DialogueId"] = 12063409,
            ["GUID"] = "1E33110A",
            ["NextDialogue"] = 12063410,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33110A",
            },
        [12063410] = {
            ["Content"] = "等一下……止流的意思，莫非是……",
            ["ContentJP"] = "えっ……じゃあ、それって……！",
            ["DialogueId"] = 12063410,
            ["GUID"] = "1E331134",
            ["NextDialogue"] = 12063411,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331134",
            },
        [12063411] = {
            ["Content"] = "狩月逐香队，经过司事会的综合评判，你们已经正式赢得本届奉香群英试的优胜，登上执律阁尽情庆祝吧，你们的胜利毋庸置疑。",
            ["ContentJP"] = "香狩りチーム、あなたたちは<Default note=\"text:ほうこうえいゆうたいかい\">奉香英雄大会</>にて、その勝利を大いに祝ってください。――その栄光に、一片の疑いもありません。",
            ["DialogueId"] = 12063411,
            ["GUID"] = "1E33115E",
            ["NextDialogue"] = 12063412,
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E33115E",
            },
        [12063412] = {
            ["Content"] = "我们赢了？！",
            ["ContentJP"] = "やった！……私たち、勝ったんだ！！",
            ["DialogueId"] = 12063412,
            ["GUID"] = "1E331188",
            ["NextDialogue"] = 12063413,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331188",
            },
        [12063413] = {
            ["Content"] = "嗯，我们赢了，苏乙……苏乙？",
            ["ContentJP"] = "うん、勝ったんだよ、スーイー……あれ？",
            ["DialogueId"] = 12063413,
            ["GUID"] = "1E3311B2",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3311B2",
            },
        [12063414] = {
            ["Content"] = "找到了，原来她在那里。",
            ["ContentJP"] = "見つけた。あそこだ……",
            ["DialogueId"] = 12063414,
            ["GUID"] = "1E3311DC",
            ["NextDialogue"] = 12063415,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E3311DC",
            },
        [12063415] = {
            ["Content"] = "旁边的那是……潇湘？",
            ["ContentJP"] = "隣にいるのは……ショウ？",
            ["DialogueId"] = 12063415,
            ["GUID"] = "1E331206",
            ["NextDialogue"] = 12063416,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331206",
            },
        [12063416] = {
            ["Content"] = "不知道她们会聊些什么，过去看看吧。",
            ["ContentJP"] = "何を話してるんだろう……近づいてみよう。",
            ["DialogueId"] = 12063416,
            ["GUID"] = "1E331230",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120634/1E331230",
            },
        [12063501] = {
            ["Content"] = "请等一等，让我和她单独聊聊，可以吗？",
            ["ContentJP"] = "少しだけ、二人きりにしてくれる？",
            ["DialogueId"] = 12063501,
            ["GUID"] = "1E332022",
            ["NextDialogue"] = 12063502,
            ["RelatedWikiId"] = {
                [1] = 203009,
                [2] = 203014,
                [3] = 103001,
                [4] = 407008,
                },
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332022",
            },
        [12063502] = {
            ["Content"] = "苏乙姑娘是吧，龙渊上卿已有交代，不过还请您注意时间。",
            ["ContentJP"] = "スーイーさまですね。<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>より通達は受けております。ただし、なるべく早めに済ませてくださいね。",
            ["DialogueId"] = 12063502,
            ["GUID"] = "1E33204C",
            ["NextDialogue"] = 12063503,
            ["SpeakNpcId"] = 250027,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33204C",
            },
        [12063503] = {
            ["Content"] = "多谢。",
            ["ContentJP"] = "ありがと。",
            ["DialogueId"] = 12063503,
            ["GUID"] = "1E332076",
            ["NextDialogue"] = 12063504,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332076",
            },
        [12063504] = {
            ["Content"] = "是专程来嘲讽你的手下败将的吗，苏氏传人？",
            ["ContentJP"] = "わざわざ来るなんて、勝者の余裕かしら？スー家の後継者さん。",
            ["DialogueId"] = 12063504,
            ["GUID"] = "1E3320A0",
            ["NextDialogue"] = 12063505,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320A0",
            },
        [12063505] = {
            ["Content"] = "不，我是来向你道谢的……",
            ["ContentJP"] = "いいえ。今日は、あんたに……お礼を言いにきました。",
            ["DialogueId"] = 12063505,
            ["GUID"] = "1E3320CA",
            ["NextDialogue"] = 12063506,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320CA",
            },
        [12063506] = {
            ["Content"] = "谢谢你那个时候愿意把钥匙交出来，为我们争取了宝贵的救援时间。",
            ["ContentJP"] = "あのとき、鍵を渡してくださって……救出のための貴重な時間を、与えてくださった。それだけでも……本当に、感謝しています。",
            ["DialogueId"] = 12063506,
            ["GUID"] = "1E3320F4",
            ["NextDialogue"] = 12063507,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3320F4",
            },
        [12063507] = {
            ["Content"] = "别自作多情了，我这么做只是为了小安。仅此而已。",
            ["ContentJP"] = "勘違いしないで。アンのためにやっただけ。あんたのためじゃない。",
            ["DialogueId"] = 12063507,
            ["GUID"] = "1E33211E",
            ["NextDialogue"] = 12063508,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33211E",
            },
        [12063508] = {
            ["Content"] = "而且，这不代表我原谅了昔日种种，给我记住。",
            ["ContentJP"] = "それに、過去を忘れたわけじゃないから。",
            ["DialogueId"] = 12063508,
            ["GUID"] = "1E332148",
            ["NextDialogue"] = 12063509,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332148",
            },
        [12063509] = {
            ["Content"] = "嗯，我知道。",
            ["ContentJP"] = "わかっています。",
            ["DialogueId"] = 12063509,
            ["GUID"] = "1E332172",
            ["NextDialogue"] = 12063510,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332172",
            },
        [12063510] = {
            ["Content"] = "不管你怎么说，你愿意踏出这一步……我很高兴。",
            ["ContentJP"] = "でも、それでも――私は嬉しかった。あんたが、一歩踏み出してくれたことが。",
            ["DialogueId"] = 12063510,
            ["GUID"] = "1E33219C",
            ["NextDialogue"] = 12063511,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33219C",
            },
        [12063511] = {
            ["Content"] = "我曾经无数次想过，为何机枢派妄受非议，为何飘零人心生叛逆，为何大风九章如此蛮横强硬，为什么人们时常无法理解彼此……",
            ["ContentJP"] = "昔、何度も考えました。どうして<Default note=\"text:きすうは\">機枢派</>は誤解され、流れ者は疎まれ、<Default note=\"text:たいふうきゅうしょう\">大風九章</>はあそこまで強硬なのか。……どうして、人はわかり合えないのかって。",
            ["DialogueId"] = 12063511,
            ["GUID"] = "1E3321C6",
            ["NextDialogue"] = 12063512,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3321C6",
            },
        [12063512] = {
            ["Content"] = "只可惜，无论再怎么懂得机枢工造，被旁人称作天才，我也只不过是数千年的历史中，一个再普通不过的庸人罢了。",
            ["ContentJP"] = "いくら<Default note=\"text:きすう\">機枢</>術に通じ、「天才」と持て囃されたところで……結局のところ、私は何千年もの歴史のなかに埋もれる、ただの凡人に過ぎません。",
            ["DialogueId"] = 12063512,
            ["GUID"] = "1E3321F0",
            ["NextDialogue"] = 12063513,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3321F0",
            },
        [12063513] = {
            ["Content"] = "我想不明白这个问题的答案，也不知道如何才能根绝纷争。曾经的悬衡派为了消灭纷争封印烛阴，但这片土地并没有因此变得更好。",
            ["ContentJP"] = "答えは未だ見つからず、争いを根絶する術も分からない。かつての<Default note=\"text:けんこうは\">懸衡派</>は、争いの終焉を願って<Default note=\"text:しょくいん\">燭陰</>を封じました。でも、この地が平和になったとは到底言えません。",
            ["DialogueId"] = 12063513,
            ["GUID"] = "1E33221A",
            ["NextDialogue"] = 12063514,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33221A",
            },
        [12063514] = {
            ["Content"] = "我想，人与人终究是想法不同的，即使烛阴之灾结束，大风九章重启，人们也还是会因为各种各样的原因争论，冲突……",
            ["ContentJP"] = "人と人は、きっと分かり合えない。たとえ災厄が去り、<Default note=\"text:たいふうきゅうしょう\">大風九章</>が新たに始まったとしても、人はまた、さまざまな理由で争い、ぶつかるでしょう。",
            ["DialogueId"] = 12063514,
            ["GUID"] = "1E332244",
            ["NextDialogue"] = 12063515,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332244",
            },
        [12063515] = {
            ["Content"] = "我所能做的，也就只是倾尽我的所有，试着去治愈曾经的冲突所造成的伤痛。",
            ["ContentJP"] = "だから私は、せめて自分にできることをやろうと思うんです。かつての争いが残した傷痕を、少しでも癒せたらと。",
            ["DialogueId"] = 12063515,
            ["GUID"] = "1E33226E",
            ["NextDialogue"] = 12063516,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33226E",
            },
        [12063516] = {
            ["Content"] = "弥合些皮肉之伤罢了。",
            ["ContentJP"] = "皮一枚、なでるだけの癒やしにすぎないわね。",
            ["DialogueId"] = 12063516,
            ["GUID"] = "1E332298",
            ["NextDialogue"] = 12063517,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332298",
            },
        [12063517] = {
            ["Content"] = "嗯，但这就是我眼下能够做到的事。",
            ["ContentJP"] = "それでも、今の私にできる精一杯のことです。",
            ["DialogueId"] = 12063517,
            ["GUID"] = "1E3322C2",
            ["NextDialogue"] = 12063518,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3322C2",
            },
        [12063518] = {
            ["Content"] = "在那之后，我也会竭尽所能，让你与我经历的事不再上演。",
            ["ContentJP"] = "そしてこれからも、あんたと私が経験してきた悲劇が繰り返されぬよう、できる限りの力を尽くします。",
            ["DialogueId"] = 12063518,
            ["GUID"] = "1E3322EC",
            ["NextDialogue"] = 12063519,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3322EC",
            },
        [12063519] = {
            ["Content"] = "就凭你？",
            ["ContentJP"] = "あんた一人で？",
            ["DialogueId"] = 12063519,
            ["GUID"] = "1E332316",
            ["NextDialogue"] = 12063520,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332316",
            },
        [12063520] = {
            ["Content"] = "还有你，还有所有为了这个目标一同努力的人，就像千百年来，一直尝试着改变大风九章的人们一样。",
            ["ContentJP"] = "いいえ、私だけじゃない。あんたもいるし、同じ未来を目指して歩んでいる人たちが、きっと他にもいるはず。千年のあいだ、何度でも希望を捨てず、<Default note=\"text:たいふうきゅうしょう\">大風九章</>を変えようとしてきた人たちのように。",
            ["DialogueId"] = 12063520,
            ["GUID"] = "1E332340",
            ["NextDialogue"] = 12063521,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332340",
            },
        [12063521] = {
            ["Content"] = "现在，他们已经成功了，该轮到我们了。",
            ["ContentJP"] = "彼らが一歩を踏み出したなら、今度は私たちの番です。",
            ["DialogueId"] = 12063521,
            ["GUID"] = "1E33236A",
            ["NextDialogue"] = 12063522,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33236A",
            },
        [12063522] = {
            ["Content"] = "无论如何，你放弃了你们的计划，阻止了那台失控的机关巨阙。你还有我，我们已经共同踏出了第一步。",
            ["ContentJP"] = "……あんたは、あの暴走した<Default note=\"text:こけつ\">巨闕</>を止めてくれた。私たちは、ともに計画を捨て、最初の一歩を踏み出せた。",
            ["DialogueId"] = 12063522,
            ["GUID"] = "1E332394",
            ["NextDialogue"] = 12063523,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332394",
            },
        [12063523] = {
            ["Content"] = "也许我们也会成为不靠谱的前辈，只能把写了一半的答卷留给后人，甚至已经写好的部分也有可能是错误答案……",
            ["ContentJP"] = "たとえ将来、私たちが不完全な先人となって、書きかけの解答用紙を後の世に託すことになったとしても、あるいは、それが誤った答えだったとしても……",
            ["DialogueId"] = 12063523,
            ["GUID"] = "1E3323BE",
            ["NextDialogue"] = 12063524,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3323BE",
            },
        [12063524] = {
            ["Content"] = "但我相信，我们一定可以离那个未来更近一些，再近一些……一步一步。",
            ["ContentJP"] = "それでも私は信じています。私たちは、必ず未来に近づける。少しずつ、確実に。",
            ["DialogueId"] = 12063524,
            ["GUID"] = "1E3323E8",
            ["NextDialogue"] = 12063525,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3323E8",
            },
        [12063525] = {
            ["Content"] = "……天真，甚至近乎愚昧。",
            ["ContentJP"] = "甘い。もはや愚かとすら言える。",
            ["DialogueId"] = 12063525,
            ["GUID"] = "1E332412",
            ["NextDialogue"] = 12063526,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332412",
            },
        [12063526] = {
            ["Content"] = "时间差不多了，该上路了。",
            ["ContentJP"] = "時間です。もう行きましょう。",
            ["DialogueId"] = 12063526,
            ["GUID"] = "1E33243C",
            ["NextDialogue"] = 12063527,
            ["SpeakNpcId"] = 250027,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33243C",
            },
        [12063527] = {
            ["Content"] = "即便身为阶下之囚，我也会一直看着你……",
            ["ContentJP"] = "牢の中から、あんたの行く末を見届けているわよ。",
            ["DialogueId"] = 12063527,
            ["GUID"] = "1E332466",
            ["NextDialogue"] = 12063528,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332466",
            },
        [12063528] = {
            ["Content"] = "别让我看笑话，苏氏传人。",
            ["ContentJP"] = "せいぜい恥をかかないことね、スー家の娘よ。",
            ["DialogueId"] = 12063528,
            ["GUID"] = "1E332490",
            ["NextDialogue"] = 12063529,
            ["SpeakNpcId"] = 250018,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332490",
            },
        [12063529] = {
            ["Content"] = "{nickname}，谢谢你一直指引我走到这一步。",
            ["ContentJP"] = "{nickname}……ここまで来られたのは、あんたがいてくれたからよ。",
            ["DialogueId"] = 12063529,
            ["GUID"] = "1E3324BA",
            ["NextDialogue"] = 12063530,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3324BA",
            },
        [12063530] = {
            ["Content"] = "我并没有做什么。",
            ["ContentJP"] = "いや、別に何もしていないよ。",
            ["DialogueId"] = 12063530,
            ["GUID"] = "1E3324E4",
            ["NextDialogue"] = 12063531,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3324E4",
            },
        [12063531] = {
            ["Content"] = "真要说我有帮上什么忙，大概只是见证你用自己的意志一步一步走到这里吧。",
            ["ContentJP"] = "ただ、スーイーが自分の意志でここまで来たのを見届けただけ。",
            ["DialogueId"] = 12063531,
            ["GUID"] = "1E33250E",
            ["NextDialogue"] = 12063532,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33250E",
            },
        [12063532] = {
            ["Content"] = "既然这样，那就见证我直到今天的最后一刻吧。",
            ["ContentJP"] = "それなら……「最後の一歩」も、見ていてよね。",
            ["DialogueId"] = 12063532,
            ["GUID"] = "1E332538",
            ["NextDialogue"] = 12063533,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332538",
            },
        [12063533] = {
            ["Content"] = "走吧，一起去执律阁，享受属于我们的胜利时刻！",
            ["ContentJP"] = "さあ、行きましょう。この勝利の瞬間を祝いに――<Default note=\"text:しつりつかく\">執律閣</>へ！",
            ["DialogueId"] = 12063533,
            ["GUID"] = "1E332562",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332562",
            },
        [12063534] = {
            ["Content"] = "准备好了吗？",
            ["ContentJP"] = "準備はいい？",
            ["DialogueId"] = 12063534,
            ["GUID"] = "1E33258C",
            ["NextDialogue"] = 12063535,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33258C",
            },
        [12063535] = {
            ["Content"] = "嗯。",
            ["ContentJP"] = "ええ。",
            ["DialogueId"] = 12063535,
            ["GUID"] = "1E3325B6",
            ["NextDialogue"] = 12063536,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3325B6",
            },
        [12063536] = {
            ["Content"] = "昊天苍苍，玄水泱泱。",
            ["ContentJP"] = "蒼天たかく 玄水ながし",
            ["DialogueId"] = 12063536,
            ["GUID"] = "1E3325E0",
            ["NextDialogue"] = 12063537,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E3325E0",
            },
        [12063537] = {
            ["Content"] = "华胥承祀，爰奉馨香。",
            ["ContentJP"] = "華胥は祀りを継ぎて 香を捧ぐ",
            ["DialogueId"] = 12063537,
            ["GUID"] = "1E33260A",
            ["NextDialogue"] = 12063538,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33260A",
            },
        [12063538] = {
            ["Content"] = "润其五谷，泽彼田桑。",
            ["ContentJP"] = "五穀を潤し 田畑にめぐみ",
            ["DialogueId"] = 12063538,
            ["GUID"] = "1E332634",
            ["NextDialogue"] = 12063539,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332634",
            },
        [12063539] = {
            ["Content"] = "禔福兆民，惠汲四方。",
            ["ContentJP"] = "民に福を 四方に恵み",
            ["DialogueId"] = 12063539,
            ["GUID"] = "1E33265E",
            ["NextDialogue"] = 12063540,
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E33265E",
            },
        [12063540] = {
            ["Content"] = "永锡丰年，以宁万邦。",
            ["ContentJP"] = "豊穣つねにありて 万国やすらかならん",
            ["DialogueId"] = 12063540,
            ["GUID"] = "1E332688",
            ["VoiceName"] = "voice/$Locale$/story/1206/120635/1E332688",
            },
        [12063601] = {
            ["Content"] = "每个人的力量都是如此渺小，或许往后数十载，人们仍会对飘零人心生畏惧。",
            ["ContentJP"] = "人の力なんて、所詮ちっぽけなもの。きっとこれからも、流れ者は恐れられ、拒まれることだろう。（モノローグ）",
            ["DialogueId"] = 12063601,
            ["GUID"] = "1E33308A",
            ["NextDialogue"] = 12063602,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E33308A",
            },
        [12063602] = {
            ["Content"] = "或许即便付出一切，直至行将就木，我也无法见到人们彻底摒弃往日恩怨齐心协力的那一日。",
            ["ContentJP"] = "すべてを賭けたとしても——この身が果てるその日まで、人々が過去の憎しみを超えて、ひとつになれる日が来るかなんて、わからない。（モノローグ）",
            ["DialogueId"] = 12063602,
            ["GUID"] = "1E3330B4",
            ["NextDialogue"] = 12063603,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E3330B4",
            },
        [12063603] = {
            ["Content"] = "姐姐，那个机关鸟儿是怎么飞起来的呀？",
            ["ContentJP"] = "ねえ、お姉さん。その鳥さん、どうして飛べるの？",
            ["DialogueId"] = 12063603,
            ["GUID"] = "1E3330DE",
            ["NextDialogue"] = 12063604,
            ["SpeakNpcId"] = 250025,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E3330DE",
            },
        [12063604] = {
            ["Content"] = "但，我已经走上了这条道路。还有很多人，与我一起走上了这条道路——纵使星火黯然，改变也已然到来。",
            ["ContentJP"] = "それでも、私はもう、この道を選んだ。そして今、同じ道を歩んでくれる人たちがいる——たとえその光がかすかでも、変化はもう始まっている。（モノローグ）",
            ["DialogueId"] = 12063604,
            ["GUID"] = "1E333108",
            ["NextDialogue"] = 12063605,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333108",
            },
        [12063605] = {
            ["Content"] = "你看到了吗，姑姑？",
            ["ContentJP"] = "見てくれてるかな、叔母さん……（モノローグ）",
            ["DialogueId"] = 12063605,
            ["GUID"] = "1E333132",
            ["NextDialogue"] = 12063606,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333132",
            },
        [12063606] = {
            ["Content"] = "小妹妹，想学吗？",
            ["ContentJP"] = "どうやって飛ぶのか、知りたい？",
            ["DialogueId"] = 12063606,
            ["GUID"] = "1E33315C",
            ["NextDialogue"] = 12063607,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E33315C",
            },
        [12063607] = {
            ["Content"] = "——那便来当姐姐的第一个“学生”，好不好？",
            ["ContentJP"] = "教えてあげるから、私の最初の「弟子」になってくれるかしら？",
            ["DialogueId"] = 12063607,
            ["GUID"] = "1E333186",
            ["VoiceName"] = "voice/$Locale$/story/1206/120636/1E333186",
            },
        [12063701] = {
            ["Content"] = "一日后 浮星埠",
            ["ContentJP"] = "次の日 浮星埠",
            ["DialogueId"] = 12063701,
            ["GUID"] = "1E3340F2",
            ["NextDialogue"] = 12063702,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3340F2",
            },
        [12063702] = {
            ["Content"] = "小仆从，这次我们是真的要离开华胥了吧？",
            ["ContentJP"] = "しもべ～、今度こそ本当に<Default note=\"text:カショ\">華胥</>を出るんだよね？",
            ["DialogueId"] = 12063702,
            ["GUID"] = "1E33411C",
            ["NextDialogue"] = 12063703,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33411C",
            },
        [12063703] = {
            ["Content"] = "这么平平淡淡，没有波折，没有陷阱，没有奇怪的人突然冒出来阻止我们，还有点不习惯呢……",
            ["ContentJP"] = "なんか、波乱もトラップもヘンな人も出なんもないと……逆に拍子抜けしちゃう……",
            ["DialogueId"] = 12063703,
            ["GUID"] = "1E334146",
            ["NextDialogue"] = 12063704,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334146",
            },
        [12063704] = {
            ["Content"] = "呵呵……怎么，需要我扮演“奇怪的人”再来热情好客地阻拦一下你们的归程吗？",
            ["ContentJP"] = "ふふ……そんなに物足りないなら、私がその「へんな人」になって、もう一波乱起こしてあげようかしら？",
            ["DialogueId"] = 12063704,
            ["GUID"] = "1E334170",
            ["NextOptions"] = {
                [1] = 12063705,
                },
            ["SpeakNpcId"] = 250004,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334170",
            },
        [12063705] = {
            ["Content"] = "白，闭嘴！",
            ["ContentJP"] = "スノウ、お口チャック！",
            ["DialogueId"] = 12063705,
            ["GUID"] = "1E33419A",
            ["NextDialogue"] = 12063706,
            },
        [12063706] = {
            ["Content"] = "不不不不还是不用了！",
            ["ContentJP"] = "やっ、やっぱいい！それはほんとに勘弁して！",
            ["DialogueId"] = 12063706,
            ["GUID"] = "1E3341C4",
            ["NextDialogue"] = 12063707,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3341C4",
            },
        [12063707] = {
            ["Content"] = "白，{nickname}——",
            ["ContentJP"] = "スノウ、{nickname}――",
            ["DialogueId"] = 12063707,
            ["GUID"] = "1E3341EE",
            ["NextDialogue"] = 12063708,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3341EE",
            },
        [12063708] = {
            ["Content"] = "你们……怎么都来了？",
            ["ContentJP"] = "みんな、どうしてここに？",
            ["DialogueId"] = 12063708,
            ["GUID"] = "1E334218",
            ["NextDialogue"] = 12063709,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334218",
            },
        [12063709] = {
            ["Content"] = "自然是来送别你了！要是你回到那个叫冰湖城的地方被人欺负了，给我写封信，兄弟我不远千里也要来两肋插刀，帮你打架！",
            ["ContentJP"] = "そりゃあ、見送りに決まってんだろ！もしアイスレイク城ってとこで誰かにいじめられたら、手紙よこせよな。何千里離れてようが、駆けつけて、ぶっ飛ばしてやっから！",
            ["DialogueId"] = 12063709,
            ["GUID"] = "1E334242",
            ["NextDialogue"] = 12063710,
            ["SpeakNpcId"] = 250002,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334242",
            },
        [12063710] = {
            ["Content"] = "{nickname}，你要走了吗？保重。愿你平安无虞。但若是不慎有了伤痛，扶疏随时愿来为你治疗。",
            ["ContentJP"] = "{nickname}さん、もうお発ちになるのですね。道中どうかご無事で。……もし怪我などなさったら、いつでも私をお呼びくださいませ。",
            ["DialogueId"] = 12063710,
            ["GUID"] = "1E33426C",
            ["NextDialogue"] = 12063711,
            ["SpeakNpcId"] = 250001,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33426C",
            },
        [12063711] = {
            ["Content"] = "此去一别，山高水远。愿君万事顺遂。",
            ["ContentJP"] = "これより先は、山を越え、水を渡る遠き道。どうか安らかなる旅路を。",
            ["DialogueId"] = 12063711,
            ["GUID"] = "1E334296",
            ["NextDialogue"] = 12063712,
            ["SpeakNpcId"] = 250005,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334296",
            },
        [12063712] = {
            ["Content"] = "……呼。昨天比赛胜利后有好多好多事情要处理，又熬了个通宵，差一点没赶过来。",
            ["ContentJP"] = "はぁ……昨日の勝利のあと、片付けなきゃいけないことが山ほどあって……夜通し作業して、危うく見送りに間に合わないところだったよ。",
            ["DialogueId"] = 12063712,
            ["GUID"] = "1E3342C0",
            ["NextDialogue"] = 12063713,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3342C0",
            },
        [12063713] = {
            ["Content"] = "但是，{nickname}，有些话，我一定要当面和你说出口！",
            ["ContentJP"] = "でもね{nickname}、どうしても、直接伝えたかったの！",
            ["DialogueId"] = 12063713,
            ["GUID"] = "1E3342EA",
            ["NextDialogue"] = 12063714,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E3342EA",
            },
        [12063714] = {
            ["Content"] = "谢谢你帮助我认清了自己真正想要做的事情……谢谢你！你一定也有不顾一切都想做的事情吧，你一定能做到的！",
            ["ContentJP"] = "ありがとう。あんたのおかげで、私は、自分が本当にやりたいことに気づけた。きっと、あんたにもどうしても叶えたいことがあるよね？あんたなら、きっとできるわ！",
            ["DialogueId"] = 12063714,
            ["GUID"] = "1E334314",
            ["NextDialogue"] = 12063715,
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E334314",
            },
        [12063715] = {
            ["Content"] = "多写信回来——还有，不要忘了大家！",
            ["ContentJP"] = "手紙、たくさん書いてね。……それと、みんなのこと、忘れないで！",
            ["DialogueId"] = 12063715,
            ["GUID"] = "1E33433E",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120637/1E33433E",
            },
        [12063801] = {
            ["Content"] = "扫描完成……正在建立追踪路径……",
            ["ContentJP"] = "スキャン完了……追跡ルートを構築中……",
            ["DialogueId"] = 12063801,
            ["GUID"] = "1E33515A",
            ["NextDialogue"] = 12063802,
            ["SnapShot"] = "ROBOT",
            ["SpeakNpcName"] = "UI_Npc_Name_Qingluan",
            ["VoiceName"] = "voice/$Locale$/story/1206/120638/1E33515A",
            },
        [12063802] = {
            ["Content"] = "来，跟上青鸾贰型，它会为我们指明潇湘藏身的位置！",
            ["ContentJP"] = "さあ、<Default note=\"text:せいほう\">青鳳</>二型について来なさい。ショウが隠れている場所へ導いてくれるわ。",
            ["DialogueId"] = 12063802,
            ["GUID"] = "1E335184",
            ["SpeakNpcId"] = 250003,
            ["VoiceName"] = "voice/$Locale$/story/1206/120638/1E335184",
            },
        [20000401] = {
            ["Content"] = "喂。",
            ["ContentJP"] = "おい。",
            ["DialogueId"] = 20000401,
            ["Duration"] = 3,
            ["GUID"] = "3211A3CA",
            ["NextDialogue"] = 20000402,
            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200004/3211A3CA",
            },
        [20000402] = {
            ["Content"] = "我说，那边的年轻人……",
            ["ContentJP"] = "そこの若いの、聞こえんのか……？",
            ["DialogueId"] = 20000402,
            ["Duration"] = 3,
            ["GUID"] = "3211A3CB",
            ["SpeakNpcId"] = 200024,
            ["VoiceName"] = "voice/$Locale$/story/2001/200004/3211A3CB",
            },
        [20000501] = {
