        [20000816] = {
            ["Camera"] = "-367.966797,-133.300049,130.748047,0.000005,-3.600124,20.403618,30.0,285.329437,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "（你打量着那盆花——它看上去状况并不太好，茎叶有些发黄，花瓣也没有多少光泽。）",
            ["ContentJP"] = "（あなたは鉢植えの花をジッと見つめた――状態はあまりよくなさそうだ。茎や葉が黄ばんでいて、花びらにはつやがない）",
            ["DialogueId"] = 20000816,
