            },
        [20000908] = {
            ["Camera"] = "-6.515625,-43.923828,124.070312,0.000006,0.999926,-10.192293,30.0,147.70752,false,Manual,2.984025",
            ["Content"] = "毕竟是珍贵的礼物嘛。不过，你这么宝贝这些花，摘下来送给我，不会很心疼吗？",
            ["ContentJP"] = "大事なプレゼントだから。でもこれってサイキが大切にしていた花{性别:だよね|でしょ}？摘んでしまうとき、心が痛まなかった？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000908,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211F6F8",
            ["NextDialogue"] = 20000909,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200027:Explain02_End",
                [2] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F6F8",
            },
        [20000909] = {
            ["Camera"] = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,215.0,false,Manual,2.984025",
            ["Content"] = "心疼……嗯，我还是心疼过的。不过，是在小的时候。",
            ["ContentJP"] = "心が痛む……えと、小さい頃はそんな風に感じたかな。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000909,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Sad01",
                },
            ["GUID"] = "3211F722",
            ["NextDialogue"] = 20000910,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F722",
            },
        [20000910] = {
            ["Camera"] = "125.662109,-37.871582,125.59375,0.0,0.599998,-165.793549,25.0,127.299126,false,DoNotOverride,1.2",
            ["Content"] = "你见过花店里出售的鲜切花吧？其实，那时候我很不喜欢鲜切花……我觉得被剪下来的花很可怜。",
            ["ContentJP"] = "花屋さんで切り花を売っているのは見たことあるよね？実は昔は、切り花って全然好きになれなくて……切っちゃうなんてかわいそうだもの。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000910,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["FinalCamera"] = "125.382812,-36.4729,125.59375,0.0,0.599998,-168.793213,25.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F74C",
            ["NextDialogue"] = 20000911,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{200027},AnimationId{\"DisagreeHead\"},Duration{1}}}",
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F74C",
            },
        [20000911] = {
            ["Camera"] = "-6.826172,100.584717,97.013672,0.000043,9.999396,-119.386726,25.0,118.235596,false,DoNotOverride,1.2",
            ["Content"] = "花和根、茎、叶一样，都是植物的一部分。可人们却为了欣赏花的美丽，把它单独剪下来观赏，让它离开枝干，孤零零地死去。",
            ["ContentJP"] = "根っこも葉っぱも花も、植物にとっては身体の一部。でも私たちは花の美しさだけを楽しむために切り取って観賞するの。枝から切り離して、ひとりぼっちで死なせてしまう……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000911,
            ["Duration"] = 3,
            ["FinalCamera"] = "-38.798828,43.810303,123.986328,0.000043,9.999396,-119.386726,25.0,118.235596,false,DoNotOverride,1.2",
            ["GUID"] = "3211F776",
            ["NextOptions"] = {
                [1] = 200009111,
                [2] = 200009112,
                },
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F776",
            },
        [20000912] = {
            ["Camera"] = "278.988281,10.379639,123.230469,0.0,0.0,-157.596741,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "从我们的角度看也许是这样……",
            ["ContentJP"] = "私たちの視点だと、そうかもしれないけど……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000912,
            ["Duration"] = 3,
            ["GUID"] = "3211F7A0",
            ["NextDialogue"] = 20000913,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F7A0",
            },
        [20000913] = {
            ["Camera"] = "-76.474609,-28.993408,129.525391,0.000001,-2.400053,-20.986586,33.0,211.485077,false,Manual,4.671381",
            ["Content"] = "你刚才说“小时候”……那，现在你改变看法了？",
            ["ContentJP"] = "さっき「小さい頃は」って言っていたけど、いまのサイキはどうなのかな？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000913,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211F7CA",
            ["NextDialogue"] = 20000914,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F7CA",
            },
        [20000914] = {
            ["Camera"] = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,219.542435,false,Manual,2.984025",
            ["Content"] = "也没有完全改变。只是……",
            ["ContentJP"] = "完全には変わっていないよ。ただ……",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000914,
            ["Duration"] = 3,
            ["GUID"] = "3211F7F4",
            ["NextDialogue"] = 20000915,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "200027:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F7F4",
            },
        [20000915] = {
            ["Camera"] = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,219.542435,false,Manual,2.984025",
            ["Content"] = "我可以先问你一个问题吗？对于那些被摘下的花朵，你是怎么看的？",
            ["ContentJP"] = "質問に質問でかえす形になっちゃうけど、いいかな？{nickname}は、摘まれたお花について、どう思う？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000915,
            ["Duration"] = 3,
            ["GUID"] = "3211F81E",
            ["NextOptions"] = {
                [1] = 200009151,
                [2] = 200009152,
                [3] = 200009153,
                },
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F81E",
            },
        [20000916] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "嗯……看来把花送给你是对的，你一定会好好养护它们。",
            ["ContentJP"] = "うん……お花をあなたにプレゼントしたのは正解だった。絶対に大切にしてくれるって思っていたの。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000916,
            ["Duration"] = 3,
            ["GUID"] = "3211F848",
            ["NextDialogue"] = 20000919,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F848",
            },
        [20000917] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "嗯……我明白，我也是这么想的。",
            ["ContentJP"] = "うん……すごくわかる。私もそう思っているの。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000917,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["GUID"] = "3211F872",
            ["NextDialogue"] = 20000919,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F872",
            },
        [20000918] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "你和我小时候想的一样呢。",
            ["ContentJP"] = "小さい頃の私と一緒の考えなんだね。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000918,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["GUID"] = "3211F89C",
            ["NextDialogue"] = 20000919,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F89C",
            },
        [20000919] = {
            ["Camera"] = "624.845703,-2701.800537,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "现在的我啊，看到被切下来的花，还是会有点难过。但是，我也渐渐发觉，那些鲜切花很了不起，比我想象中更了不起。",
            ["ContentJP"] = "私はいまでもやっぱり、切り取られたお花を見ると悲しくなっちゃう。でも、切り花の素敵な部分にも気づいてきたの。私が考えていたより、ずっと素敵なんじゃないかなって。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000919,
            ["Duration"] = 3,
            ["FinalCamera"] = "624.845703,-2600.36084,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F8C6",
            ["NextDialogue"] = 20000920,
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F8C6",
            },
        [20000920] = {
            ["Camera"] = "260.572266,-2538.362549,380.068359,0.0,-7.500005,90.0,15.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "明明从被切断的那一刻起，它们就注定无法结出果实，只能慢慢枯萎——",
            ["ContentJP"] = "切り取られた瞬間から、実になることもなく、ゆっくり枯れていくだけの運命なのに――",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000920,
            ["Duration"] = 3,
            ["FinalCamera"] = "260.572266,-2339.146973,232.763672,0.0,-2.499965,90.0,17.5,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F8F0",
            ["NextDialogue"] = 20000921,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F8F0",
            },
        [20000921] = {
            ["Camera"] = "454.208984,234.598389,25.705078,0.000022,5.099815,-140.996017,30.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "但是它们还是会拼命吸收水分，在短暂的时间里竭尽全力盛开，仿佛它们还有根，仿佛它们从未被剪下。",
            ["ContentJP"] = "それでも必死に水分を吸収して、短いあいだでも全力を尽くして咲き続けようとするの。まだ根っことつながっていて、切り取られてなんかいないみたいに。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000921,
            ["Duration"] = 3,
            ["FinalCamera"] = "428.185547,247.284424,26.796875,0.000022,5.099815,-136.996017,30.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211F91A",
            ["NextDialogue"] = 20000922,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                [2] = "200027:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F91A",
            },
        [20000922] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "所以现在，我不可怜它们，我敬佩它们。",
            ["ContentJP"] = "だからいまは、「かわいそう」じゃなくて「えらいな」って思うんだ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000922,
            ["Duration"] = 3,
            ["GUID"] = "3211F944",
            ["NextOptions"] = {
                [1] = 200009221,
                [2] = 200009222,
                },
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F944",
            },
        [20000923] = {
            ["Camera"] = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
            ["Content"] = "嗯，你也这么觉得吧！",
            ["ContentJP"] = "だよね！そう思うよね！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000923,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Happy01",
                },
            ["GUID"] = "3211F96E",
            ["NextDialogue"] = 20000925,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F96E",
            },
        [20000924] = {
            ["Camera"] = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
            ["Content"] = "你真善良……嗯，你说的没错……如果不曾被切下，就更好了。",
            ["ContentJP"] = "{nickname}は本当に優しいね……うん、その通り……切り取られないほうが、本当はいいのに。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000924,
            ["Duration"] = 3,
            ["GUID"] = "3211F998",
            ["NextDialogue"] = 20000925,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F998",
            },
        [20000925] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "啊，一不小心就把话题搞沉重起来了，我的错我的错——",
            ["ContentJP"] = "あ、ごめんなさい。なんだか重い空気にしちゃったね。私ったら――",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000925,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Sad02",
                },
            ["GUID"] = "3211F9C2",
            ["NextDialogue"] = 20000926,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F9C2",
            },
        [20000926] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "谢谢你带回来的土壤，湿度和松软程度正合适……说不定你也有园艺方面的天分呢！",
            ["ContentJP"] = "土を持ってきてくれてありがとう。柔らかさも湿り気もバッチリな土なの……{nickname}にも園芸の才能があるかも！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000926,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Smile01",
                },
            ["GUID"] = "3211F9EC",
            ["NextOptions"] = {
                [1] = 200009261,
                [2] = 200009262,
                },
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211F9EC",
            },
        [20000927] = {
            ["Camera"] = "106.785156,-624.62207,37.896484,0.0,2.399917,5.600382,30.0,352.267853,false,Manual,1.2",
            ["Content"] = "好呀，我会把我了解的所有窍门都教给你的！……如果有时间。",
            ["ContentJP"] = "もちろん！私の知っていることなら全部教えてあげる。もしも……時間があれば。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000927,
            ["Duration"] = 3,
            ["FinalCamera"] = "106.785156,-624.62207,56.728516,0.000001,0.0,5.600479,30.0,352.267853,false,Manual,1.2",
            ["GUID"] = "3211FA16",
            ["NextDialogue"] = 20000928,
            ["SpeakNpcId"] = 200027,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA16",
            },
        [20000928] = {
            ["Camera"] = "-73.154297,-38.155029,129.271484,0.000001,-2.400053,-18.186663,33.0,255.978088,false,Manual,4.671381",
            ["Content"] = "嗯，就这么定了。",
            ["ContentJP"] = "うん、約束。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000928,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211FA40",
            ["NextDialogue"] = 20000929,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA40",
            },
        [20000929] = {
            ["Camera"] = "428.185547,247.284424,82.193359,0.000022,-0.999987,-136.995941,30.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "{nickname}，你……真好啊。",
            ["ContentJP"] = "{nickname}、あなたって……本当に優しいね。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000929,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3211FA6A",
            ["NextDialogue"] = 20000930,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA6A",
            },
        [20000930] = {
            ["Camera"] = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
            ["Content"] = "除了爸爸妈妈，不会有人把我微不足道的话记挂在心。更不用说为了一盆花，费这么大工夫了。",
            ["ContentJP"] = "私のちいさなお願いなんて、お父さんとお母さん以外は誰も気にかけてくれなかったのに。しかもただのお花のために、こんなに手間暇をかけてくれるだなんて。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000930,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Happy01",
                },
            ["GUID"] = "3211FA94",
            ["NextDialogue"] = 20000931,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FA94",
            },
        [20000931] = {
            ["Camera"] = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
            ["Content"] = "这是报酬。虽然不值多少钱，还是希望你能收下！",
            ["ContentJP"] = "これはお礼。あんまり価値はないかもだけど、受け取ってくれるとうれしいな！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000931,
            ["Duration"] = 3,
            ["GUID"] = "3211FABE",
            ["NextDialogue"] = 20000932,
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Give",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FABE",
            },
        [20000932] = {
            ["Camera"] = "-51.462891,437.980225,224.990234,0.000043,-14.999996,-75.99987,30.0,147.010483,false,DoNotOverride,1.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "等这些花儿重新开好了，你记得回来看看。",
            ["ContentJP"] = "このお花が元気になったら、また見にきてね！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 20000932,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "200027:Happy02",
                },
            ["FinalCamera"] = "-51.462891,437.980225,188.777344,0.000045,-10.999991,-75.998978,30.0,147.010483,false,DoNotOverride,1.8",
            ["GUID"] = "3211FAE8",
            ["SpeakNpcId"] = 200027,
            ["TalkActionId"] = {
                [1] = "200027:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200009/3211FAE8",
            },
        [20001001] = {
            ["Content"] = "这里的土壤好像有点干燥……再去别的地方看看吧。",
            ["ContentJP"] = "ここの土は少し乾燥している{性别:な|ね}……ほかを探そう。",
            ["DialogueId"] = 20001001,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212063A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200010/3212063A",
            },
        [20001201] = {
            ["Content"] = "找到了……！这里的土壤比较松软，湿度看起来也合适，多挖一点回去吧。",
            ["ContentJP"] = "見つけた……！この土は柔らかいし、湿度もよさそう{性别:だ|}。ちょっと多めに持って帰ろうか{性别:|な}。",
            ["DialogueId"] = 20001201,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212270A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200012/3212270A",
            },
        [20001301] = {
            ["Content"] = "{nickname}，你找到那种土壤了吗？",
            ["ContentJP"] = "{nickname}、土は見つかったかな？",
            ["DialogueId"] = 20001301,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32123772",
            ["NextDialogue"] = 20001302,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200013/32123772",
            },
        [20001302] = {
            ["Content"] = "还没有。",
            ["ContentJP"] = "{性别:いや|ううん}、まだ見つからない。",
            ["DialogueId"] = 20001302,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212379C",
            ["NextDialogue"] = 20001303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200013/3212379C",
            },
        [20001303] = {
            ["Content"] = "找不到也没关系的，不要勉强……",
            ["ContentJP"] = "別に見つからなくても大丈夫だから、無理はしないでね……",
            ["DialogueId"] = 20001303,
            ["GUID"] = "321237C6",
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200013/321237C6",
            },
        [20001401] = {
            ["Content"] = "对了对了，我还有几件事要问你。",
            ["ContentJP"] = "あ、そうだ。質問したいことがあるの。",
            ["DialogueId"] = 20001401,
            ["GUID"] = "321247DA",
            ["NextDialogue"] = 20001402,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/321247DA",
            },
        [20001402] = {
            ["Content"] = "你有没有亲自到天之树脚下去过呀，它是不是真的有传说中那——么大，大到遮天蔽日？从下往上看，会不会像……满天都是水晶？",
            ["ContentJP"] = "{nickname}って、天上樹の下に行ったことはあるかな？本当に伝承みたいに――太陽をさえぎっちゃうくらいすっごく大きいの？根元から見上げたら……枝や葉っぱが水晶みたいに透明で、空が透けて見えたりする？",
            ["DialogueId"] = 20001402,
            ["GUID"] = "32124804",
            ["NextDialogue"] = 20001403,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/32124804",
            },
        [20001403] = {
            ["Content"] = "还有还有……海边的沙子是不是都是软绵绵的，踩上去像面粉一样，一点儿也不硌脚？",
            ["ContentJP"] = "そらから……海岸の砂は小麦粉みたいにフカフカで、足で踏んでもちっとも痛くないって本当？",
            ["DialogueId"] = 20001403,
            ["GUID"] = "3212482E",
            ["NextDialogue"] = 20001404,
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/3212482E",
            },
        [20001404] = {
            ["Content"] = "问题可能会有点多！是帮大家问的……嘿嘿，不要嫌我烦哦！",
            ["ContentJP"] = "ほかにもいろいろ質問しちゃうかも。みんなに聞いて欲しいって頼まれたの……えへへ、うっとうしかったらごめんね。",
            ["DialogueId"] = 20001404,
            ["GUID"] = "32124858",
            ["SpeakNpcId"] = 200027,
            ["VoiceName"] = "voice/$Locale$/story/2001/200014/32124858",
            },
        [20001501] = {
            ["Content"] = "嗯……有这些应该够了，回去交给赛琪吧。",
            ["ContentJP"] = "うん……これだけあれば十分{性别:だ|}。帰ってサイキに渡そう。",
            ["DialogueId"] = 20001501,
            ["Duration"] = 4,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32125842",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200015/32125842",
            },
        [20001601] = {
            ["Camera"] = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯等。",
            ["DialogueId"] = 20001601,
            ["GUID"] = "321268AA",
            ["NextDialogue"] = 20001602,
            },
        [20001602] = {
            ["Camera"] = "1700.51709,233.67041,1259.031372,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "等不耐烦了。",
            ["DialogueId"] = 20001602,
            ["FinalCamera"] = "1700.51709,233.67041,212.238281,0.0,0.0,-179.999985,20.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "321268D4",
            ["NextDialogue"] = 20001603,
            ["ToFinalCameraBlendTime"] = 4,
            },
        [20001603] = {
            ["Content"] = "赛琪怎么还没出来，我们去瞅瞅吧。",
            ["DialogueId"] = 20001603,
            ["GUID"] = "321268FE",
            },
        [20001701] = {
            ["Camera"] = "-284.28125,-104.837433,123.125,0.000002,0.199954,98.206268,35.0,310.0,false,Manual,22.0",
            ["Content"] = "想要阻止秽蚀者并非易事，先做好准备再出城找赛琪吧。",
            ["ContentJP"] = "穢蝕者を止めるのは一筋縄ではいかないぞ。サイキを追うなら先に装備を整えたほうがいい。",
            ["DialogueId"] = 20001701,
            ["FinalCamera"] = "-286.169922,-91.687805,123.117188,0.000002,-0.200043,98.206268,35.0,310.0,false,Manual,22.0",
            ["GUID"] = "32127912",
            ["LookAt"] = {
                [1] = "100001:n(200021)",
                },
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{5},TargetPosition{\"-369.230469,214.921021,133.806641,0.000008,-2.000091,-40.793766,25.0,100.0,false,Manual,3.5\"},duration{0}},\
LookAt{_delay{5.5},LookAtDescription{\"100001:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 200021,
            ["TalkActionId"] = {
                [1] = "200021:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 3.5,
            ["VoiceName"] = "voice/$Locale$/story/2001/200017/32127912",
            },
        [20001801] = {
            ["Content"] = "哇……要被吹跑了！",
            ["ContentJP"] = "わわっと……吹きとばされちゃうよー！",
            ["DialogueId"] = 20001801,
            ["GUID"] = "3212897A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 20001802,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200018/3212897A",
            },
        [20001802] = {
            ["Content"] = "白，跟在我们后面，趁着风小一点的时候一起向前。",
            ["ContentJP"] = "スノウは{性别:僕|私}たちの後ろに。風が少しおさまるタイミングをみて進もう。",
            ["DialogueId"] = 20001802,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "321289A4",
            ["NextDialogue"] = 20001803,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200018/321289A4",
            },
        [20001803] = {
            ["Content"] = "风太大的时候也可以躲在石头后面，别着急。",
            ["ContentJP"] = "風が強いときは岩の後ろにかくれよう。焦らず、ゆっくりな。",
            ["DialogueId"] = 20001803,
            ["GUID"] = "321289CE",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200018/321289CE",
            },
        [20001901] = {
            ["Camera"] = "-362.765625,-80.016602,-24.530273,0.000006,17.167358,25.771385,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "远处的冰湖上刮起了风暴，赛琪应该就在那个方向……",
            ["ContentJP"] = "遠くの湖の上空に嵐が渦巻いている。サイキはあの嵐の方向にいるはずだ……",
            ["DialogueId"] = 20001901,
            ["GUID"] = "321299E2",
            },
        [20002001] = {
            ["Content"] = "……蝴蝶？冬天怎么会有蝴蝶？",
            ["ContentJP"] = "……蝶？どうして冬に蝶が？",
            ["DialogueId"] = 20002001,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212AA4A",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200020/3212AA4A",
            },
        [20002002] = {
            ["Content"] = "就像是……在为我们引路一样……",
            ["ContentJP"] = "なんだか……道案内をしてくれているみたい……",
            ["DialogueId"] = 20002002,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212AA74",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200020/3212AA74",
            },
        [20002101] = {
            ["Content"] = "这些秽兽都半死不活的，很可能是和赛琪交过手。",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>どもが半殺しに……恐らくだがサイキと戦ったんだろう。",
            ["DialogueId"] = 20002101,
            ["GUID"] = "3212BAB2",
            ["NextDialogue"] = 20002102,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200021/3212BAB2",
            },
        [20002102] = {
            ["Content"] = "看来只要沿着它们的反方向，就能找到赛琪了……",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>が逃げてきたのと反対方向に進めば、サイキが見つかるはずだ……",
            ["DialogueId"] = 20002102,
            ["GUID"] = "3212BADC",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200021/3212BADC",
            },
        [20002201] = {
            ["Content"] = "兄弟，你还好吗。",
            ["DialogueId"] = 20002201,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "3212CB1A",
            ["NextDialogue"] = 20002202,
            ["SpeakNpcId"] = 100001,
            },
        [20002202] = {
            ["Content"] = "不太好。",
            ["DialogueId"] = 20002202,
            ["GUID"] = "3212CB44",
            ["NextDialogue"] = 20002203,
            },
        [20002203] = {
            ["Content"] = "外面情况怎么样？",
            ["DialogueId"] = 20002203,
            ["GUID"] = "3212CB6E",
            ["NextDialogue"] = 20002204,
            },
        [20002204] = {
            ["Content"] = "刮了好大的风，秽兽的行为也很反常。",
            ["DialogueId"] = 20002204,
            ["GUID"] = "3212CB98",
            },
        [20002301] = {
            ["Content"] = "（已经失去理智的赛琪正在与秽蚀对抗……应该为她做些什么……）",
            ["ContentJP"] = "（理性を失ったサイキが、いままさに穢蝕と戦っている……何か彼女のためにできることは……）",
            ["DialogueId"] = 20002301,
            ["DisableMouth"] = 1,
            ["GUID"] = "3212DB82",
            },
        [20002401] = {
            ["Content"] = "……赛琪好像往城外去了。",
            ["ContentJP"] = "……サイキは街の外に向かったみたいね。",
            ["DialogueId"] = 20002401,
            ["GUID"] = "3212EBEA",
            ["NextDialogue"] = 20002402,
            ["SpeakNpcId"] = 700049,
            },
        [20002402] = {
            ["Content"] = "应该是因为城外人比较少吧，在还有最后一点理智的时候，尽量去人少的地方去。",
            ["ContentJP"] = "郊外ならあまり人がいないから。できるだけ人気のない場所に向かったんだと思う。まだ理性が残っているうちに……",
            ["DialogueId"] = 20002402,
            ["GUID"] = "3212EC14",
            ["SpeakNpcId"] = 700049,
            },
        [20002501] = {
            ["Content"] = "你们……要去找赛琪吗？",
            ["ContentJP"] = "……サイキを探しに行くの？",
            ["DialogueId"] = 20002501,
            ["GUID"] = "3212FC52",
            ["NextDialogue"] = 20002502,
            ["SpeakNpcId"] = 200045,
            },
        [20002502] = {
            ["Content"] = "找到她的话，不要犹豫，结束她的痛苦吧，我想她也希望你们这么做……",
            ["ContentJP"] = "あの子を見つけたら、どうかためらわないで。苦しみを終わらせてあげて。あの子もきっとそう望んでいるはずだから……",
            ["DialogueId"] = 20002502,
            ["GUID"] = "3212FC7C",
            ["SpeakNpcId"] = 200045,
            },
        [20002601] = {
            ["Content"] = "刚刚那个大姐姐怎么跑那么快？",
            ["ContentJP"] = "さっきのお姉ちゃん、どうしてあんなに走るの速いの？",
            ["DialogueId"] = 20002601,
            ["GUID"] = "32130CBA",
            ["NextDialogue"] = 20002602,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc1",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130CBA",
            },
        [20002602] = {
            ["Content"] = "别问了，快走，快到城里去，那是秽蚀者！",
            ["ContentJP"] = "いいから急ぐぞ、早く街に入るんだ。あ、あれは穢蝕者だ！",
            ["DialogueId"] = 20002602,
            ["GUID"] = "32130CE4",
            ["NextDialogue"] = 20002603,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc2",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130CE4",
            },
        [20002603] = {
            ["Content"] = "别……别慌……已经有人去找卫戍部队了！",
            ["ContentJP"] = "だ、だだ……大丈夫だ。警備部隊にはもう通報してある。",
            ["DialogueId"] = 20002603,
            ["GUID"] = "32130D0E",
            ["NextDialogue"] = 20002604,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc3",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D0E",
            },
        [20002604] = {
            ["Content"] = "你们不要想趁机溜进城里，通行证，出示通行证！",
            ["ContentJP"] = "どさくさに紛れてアイスレイク城に入ろうったってそうはいかないぞ。通行許可証を出せ！",
            ["DialogueId"] = 20002604,
            ["GUID"] = "32130D38",
            ["NextDialogue"] = 20002605,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc4",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D38",
            },
        [20002605] = {
            ["Content"] = "求求你们让我们进去吧，通行证真的只是不小心弄丢了！",
            ["ContentJP"] = "お願いします、街に入れてください。通行許可証をうっかりなくしてしまって……本当なんです。",
            ["DialogueId"] = 20002605,
            ["GUID"] = "32130D62",
            ["NextDialogue"] = 20002606,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc5",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D62",
            },
        [20002606] = {
            ["Content"] = "都什么时候了还通行证，反正在外面也是死，不如直接冲进去！",
            ["ContentJP"] = "こんな時まで通行許可証って……。このまま外にいても死ぬだけなんだから、無理やりにでもなかに入ってやるわ！",
            ["DialogueId"] = 20002606,
            ["GUID"] = "32130D8C",
            ["NextDialogue"] = 20002607,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc6",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130D8C",
            },
        [20002607] = {
            ["Content"] = "停，停，你们再过来我就开枪了！",
            ["ContentJP"] = "と、止まれ！これ以上近づくと撃つぞ！",
            ["DialogueId"] = 20002607,
            ["GUID"] = "32130DB6",
            ["NextDialogue"] = 20002608,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc7",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130DB6",
            },
        [20002608] = {
            ["Content"] = "开啊！开枪把秽蚀者引过来我们一起死！",
            ["ContentJP"] = "撃ちたきゃ撃ちなよ！銃声が穢蝕者を引き寄せてみんな一緒にみなごろしさ！",
            ["DialogueId"] = 20002608,
            ["GUID"] = "32130DE0",
            ["NextDialogue"] = 20002609,
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc8",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130DE0",
            },
        [20002609] = {
            ["Content"] = "你……算你狠。行吧，先进来，等卫戍部队处理掉秽蚀者再说。",
            ["ContentJP"] = "そ、それは……。まあいいだろう。警備部隊が穢蝕者を排除するまで、とりあえずは街に入れ。",
            ["DialogueId"] = 20002609,
            ["GUID"] = "32130E0A",
            ["SpeakNpcName"] = "UI_Npc_Name_FindSaiqiNpc9",
            ["VoiceName"] = "voice/$Locale$/story/2001/200026/32130E0A",
            },
        [20002701] = {
            ["Content"] = "好大的风……直接跳下去会被吹飞的。",
            ["ContentJP"] = "すげえ風だ……飛びおりても風に戻されちまう。",
            ["DialogueId"] = 20002701,
            ["GUID"] = "32131D22",
            ["NextDialogue"] = 20002702,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200027/32131D22",
            },
        [20002702] = {
            ["Content"] = "那边，我们坐升降机下去。",
            ["ContentJP"] = "あっちだ。エレベーターを使おう。",
            ["DialogueId"] = 20002702,
            ["GUID"] = "32131D4C",
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200027/32131D4C",
            },
        [20002801] = {
            ["Content"] = "没事的，我们知道了赛琪去了哪里，跟上去就是。",
            ["ContentJP"] = "そう心配すんなよ。サイキのいる場所は見当ついてるし、追いつけばなんとかなるさ。",
            ["DialogueId"] = 20002801,
            ["Duration"] = 3,
            ["GUID"] = "32132D8A",
            ["NextDialogue"] = 20002802,
            ["SpeakNpcId"] = 200021,
            ["VoiceName"] = "voice/$Locale$/story/2001/200028/32132D8A",
            },
        [20002802] = {
            ["Content"] = "嗯，没错，只要找到赛琪，就一定会有办法的！",
            ["ContentJP"] = "そうそう。サイキに会えれば必ず方法はあるはずだよ！",
            ["DialogueId"] = 20002802,
            ["Duration"] = 3,
            ["GUID"] = "32132DB4",
            ["NextDialogue"] = 20002803,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200028/32132DB4",
            },
        [20002803] = {
            ["Content"] = "谢谢你们……",
            ["ContentJP"] = "ありがとう……",
            ["DialogueId"] = 20002803,
            ["Duration"] = 3,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "32132DDE",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200028/32132DDE",
            },
        [20002901] = {
            ["Content"] = "（已经和奥特赛德和白交代好了今天发生的所有事。）",
            ["ContentJP"] = "（アウトサイダーとスノウに今日の出来事は全部話したし……）",
            ["DialogueId"] = 20002901,
            ["DisableMouth"] = 1,
            ["Duration"] = 3,
