            },
        [20004301] = {
            ["Camera"] = "101.757812,-139.77832,28.292236,0.000069,0.600367,129.191574,12.5,133.732285,false,DoNotOverride,2.0",
            ["DialogueId"] = 20004301,
            ["GUID"] = "321423A2",
            },
        [20004501] = {
            ["Content"] = "我最亲爱的孩子，谢谢你来到世界上。",
            ["ContentJP"] = "最愛の我が子、この世界に生まれてきてくれてありがとう。",
            ["DialogueId"] = 20004501,
            ["Duration"] = 4,
            ["GUID"] = "32144472",
            ["NextDialogue"] = 20004502,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA87",
            },
        [20004502] = {
            ["Content"] = "你是我们一生的骄傲。",
            ["ContentJP"] = "サイキはずっと私たちの自慢の娘だよ。",
            ["DialogueId"] = 20004502,
            ["Duration"] = 3,
            ["GUID"] = "3214449C",
            ["NextDialogue"] = 20004503,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA88",
            },
        [20004503] = {
            ["Content"] = "赛琪，来拉钩，我们要做一辈子的好朋友！",
            ["ContentJP"] = "サイキ、握手しよう。私たち、一生の友だちだよ！",
            ["DialogueId"] = 20004503,
            ["Duration"] = 5,
            ["GUID"] = "321444C6",
            ["NextDialogue"] = 20004504,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA89",
            },
        [20004504] = {
            ["Content"] = "我会记住你曾经活过。",
            ["ContentJP"] = "私は、あなたが生きていたことを忘れないよ。",
            ["DialogueId"] = 20004504,
            ["Duration"] = 3,
            ["GUID"] = "321444F0",
            ["NextDialogue"] = 20004505,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA90",
            },
        [20004505] = {
            ["Content"] = "我们等你回来。",
            ["ContentJP"] = "僕たちサイキの帰りを待ってるよ。",
            ["DialogueId"] = 20004505,
            ["Duration"] = 3,
            ["GUID"] = "3214451A",
            ["NextDialogue"] = 20004506,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA91",
            },
        [20004506] = {
            ["Content"] = "命运啊，求你怜悯我唯一一次，让我帮她实现这个愿望吧。",
            ["ContentJP"] = "ああ、運命よ……一度だけでいい。俺を哀れむのならどうか一度だけ……この子の願いを……叶えてやりたいんだ……",
            ["DialogueId"] = 20004506,
            ["Duration"] = 5,
            ["GUID"] = "32144544",
            ["NextDialogue"] = 20004507,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA92",
            },
        [20004507] = {
            ["Content"] = "带上这朵花吧，它会给你带来好运。",
            ["ContentJP"] = "この花を持っていきなさい。きっと幸運を運んでくれるから。",
            ["DialogueId"] = 20004507,
            ["Duration"] = 4,
            ["GUID"] = "3214456E",
            ["NextDialogue"] = 20004508,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA93",
            },
        [20004508] = {
            ["Content"] = "你可以去一座小岛，在那里盖几间房子，在房子边种满白色的花。",
            ["ContentJP"] = "小さな島で、小さな家を建てて。家の周りにたくさんの白い花を植えて。",
            ["DialogueId"] = 20004508,
            ["Duration"] = 5,
            ["GUID"] = "32144598",
            ["NextDialogue"] = 20004509,
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA94",
            },
        [20004509] = {
            ["Content"] = "赛琪，我来带你回家。",
            ["ContentJP"] = "サイキ、一緒に帰ろう。",
            ["DialogueId"] = 20004509,
            ["Duration"] = 3,
            ["GUID"] = "321445C2",
            ["SnapShot"] = "HEART",
            ["VoiceName"] = "voice/$Locale$/story/1002/200045/1950CA95",
            },
