        [20004804] = {
            ["Camera"] = "-143.963196,-59.587891,62.005508,0.000066,10.798099,-99.194954,35.0,379.954346,false,Manual,3.328919",
            ["CameraBlendCurve"] = "easeInQuad",
            ["Content"] = "可不能慢慢说！我听说，有人在冰湖城外看到了一头巨大的猪，个子比你还高，脑袋比货车还大，蹄子蹬一下，能让冰湖城的城墙倒掉！",
            ["ContentJP"] = "落ち着けないよ！アイスレイク城の外に、とんでもなくデカいブタが現れたんだって！君よりも高くて、一蹴りで城壁を壊せるぐらいのね！",
