        [20005005] = {
            ["Camera"] = "64.757812,-576.111328,76.646484,0.000102,-2.499965,77.999962,35.0,143.409622,false,DoNotOverride,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "诶诶别急。你看，那边也有两个人，好像待了很久了，像是在等什么的样子——说不定也在等巨大的猪，去看看吧。",
            ["ContentJP"] = "そう急がないでよ！ほら、あっちにいる二人も、もしかしたらブタを待ってるのかも！話しかけてみようよ！",
            ["DialogueId"] = 20005005,
            ["FinalCamera"] = "64.757812,-576.111328,115.820312,0.000103,-4.999971,77.999901,37.5,143.409622,false,DoNotOverride,1.2",
            ["GUID"] = "32149722",
