            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200050/32149722",
            },
        [20005101] = {
            ["Content"] = "来嘛来嘛，要是不是的话我们就回去。",
            ["ContentJP"] = "ほら、行こうってば。違ったら帰ればいいじゃん、ね？",
            ["DialogueId"] = 20005101,
            ["GUID"] = "3214A6E2",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200051/3214A6E2",
