        [20005208] = {
            ["Camera"] = "290.441406,1084.865234,40.077148,0.000001,-4.999971,-107.19886,35.0,350.360718,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "来了！老二，拉绳子！",
            ["ContentJP"] = "おい、来たぞ！ロープを引っ張れ！",
            ["DialogueId"] = 20005208,
            ["FinalCamera"] = "390.636719,1408.566406,69.72168,0.000001,-4.999971,-107.19886,35.0,716.16925,false,Manual,1.2",
            ["GUID"] = "3214B870",
            ["NextDialogue"] = 20005209,
            ["SpeakNpcId"] = 700262,
            ["ToFinalCameraBlendTime"] = 0.5,
            ["TurnTo"] = {
                [1] = "700262:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B870",
            },
        [20005209] = {
            ["Content"] = "只见这两个人正对的方向出现了几只小动物，摇头晃脑，走来走去。",
            ["ContentJP"] = "二人の視線の先には、小さな動物が数匹現れ、拙い足取りで行ったり来たりしていた。",
            ["DialogueId"] = 20005209,
            ["GUID"] = "3214B89A",
            },
        [20005210] = {
            ["Content"] = "而在领头人的一声令下之后，一道埋在雪地中的陷阱出现，把这些小动物尽数困住。",
            ["ContentJP"] = "そして、その者のかけ声と共に、雪の中に埋まっていた罠が現れ、動物たちは捕らえた。",
            ["DialogueId"] = 20005210,
            ["GUID"] = "3214B8C4",
            ["NextDialogue"] = 20005211,
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B8C4",
            },
        [20005211] = {
            ["DialogueId"] = 20005211,
            ["GUID"] = "3214B8EE",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 20005212,
            ["VoiceName"] = "voice/$Locale$/story/2001/200052/3214B8EE",
            },
