            ["SpeakNpcId"] = 700248,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200057/32150BF2",
            },
        [20005718] = {
            ["Camera"] = "141.321762,448.1875,118.052734,-0.000763,2.207988,-38.807972,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "那么，祝愿你能早一点找到那些魔灵猎人，小小粮秣官。",
            ["ContentJP"] = "それじゃ、悪者たちが見つかるといいわね、小さな食糧補給官様。",
            ["DialogueId"] = 20005718,
            ["FinalCamera"] = "123.571815,447.842773,138.019531,-0.000763,-2.595362,-36.363739,35.000011,503.919495,false,Manual,12.0",
            ["GUID"] = "32150C1C",
