        [20005719] = {
            ["Camera"] = "154.377365,415.154297,99.683594,-0.000763,-3.236574,-15.412816,35.000011,369.08606,false,Manual,12.0",
            ["Content"] = "你终于进来啦，松露，欢迎你！",
            ["ContentJP"] = "おお、中に入れたんだな、トリュフ！歓迎するぞ！",
            ["DialogueId"] = 20005719,
