        [20005722] = {
            ["Camera"] = "345.16864,317.928711,137.46875,-0.000763,1.607089,136.417633,35.0,169,false,Manual,12.0",
            ["Content"] = "你有头绪吗？",
            ["ContentJP"] = "目星はついてるの？",
            ["DialogueId"] = 20005722,
            ["FinalCamera"] = "311.653595,331.706055,134.34375,-0.000763,4.806766,132.015808,35.0,169.08606,false,Manual,12.0",
            ["GUID"] = "32150CC4",
            ["NextDialogue"] = 20005723,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200057/32150CC4",
            },
        [20005723] = {
            ["Camera"] = "427.671539,393.154297,128.347656,-0.000763,-6.992433,-162.983078,35.000008,216.630737,false,Manual,12.0",
            ["Content"] = "我有头猪——可靠的榛子。它嗅觉可灵敏啦，可以闻到附近魔灵们在哪里出没，应该能在附近逮到那些魔灵猎人！",
            ["ContentJP"] = "はい！ヘーゼルナッツは匂いでジェネモンの居場所を探知できるので、きっとハンターもその近くにいるはずです！",
            ["DialogueId"] = 20005723,
            ["FinalCamera"] = "427.671539,393.154297,128.347656,-0.000763,-8.192443,-154.983536,35.000008,216.630737,false,Manual,12.0",
            ["GUID"] = "32150CEE",
            ["LookAt"] = {
                [1] = "200074:n(200086)",
                },
            ["Scripts"] = "PARA{\
PlayFacial{_delay{2.1},ActorId{200074},FacialId{\"Happy01\"}},\
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{\"Confident_Start\"}}\
}",
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "200074:p(45)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200057/32150CEE",
            },
        [20005801] = {
            ["Content"] = "走吧，先往高处走，魔灵的气味更容易传到高处。",
            ["ContentJP"] = "どこか高い所に行きましょう。その方が遠くの匂いも探知しやすいので。",
            ["DialogueId"] = 20005801,
            ["GUID"] = "321519BA",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/321519BA",
            },
        [20005802] = {
            ["Content"] = "啊，榛子闻到了，在那里！",
            ["ContentJP"] = "むむ！ヘーゼルナッツが匂いを察知したようですね。あそこです！",
            ["DialogueId"] = 20005802,
            ["GUID"] = "321519E4",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/321519E4",
            },
        [20005803] = {
            ["Content"] = "是这里……但没有魔灵，只有……",
            ["ContentJP"] = "ここのようですが……ジェネモンはいませんね。これは……",
            ["DialogueId"] = 20005803,
            ["GUID"] = "32151A0E",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/32151A0E",
            },
        [20005804] = {
            ["Content"] = "这是他们陷阱的痕迹，好可恶，他们应该已经走了。",
            ["ContentJP"] = "罠の痕……なんて酷い……ハンターたちはもういないようですね。",
            ["DialogueId"] = 20005804,
            ["GUID"] = "32151A38",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20005805,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/32151A38",
            },
        [20005805] = {
            ["Content"] = "那接下来我们去人少一点的地方，气味会明显一些。",
            ["ContentJP"] = "次は人が少ないところへ行きましょう。その方が匂いを嗅ぎ分けやすいので。",
            ["DialogueId"] = 20005805,
            ["GUID"] = "32151A62",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200058/32151A62",
            },
        [20005901] = {
            ["Content"] = "这里这里，{性别：大哥哥|大姐姐}别着急，慢点一点走，别滑倒啦。",
            ["ContentJP"] = "ここです。滑らないよう気を付けてくださいね、{性别:お兄さん|お姉さん}。",
            ["DialogueId"] = 20005901,
            ["GUID"] = "32152A22",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152A22",
            },
        [20005902] = {
            ["Content"] = "呃……这里也是一样，有人布设过陷阱。",
            ["ContentJP"] = "うーん……ここも同じですね。誰かが罠を仕掛けていたようです。",
            ["DialogueId"] = 20005902,
            ["GUID"] = "32152A4C",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20005903,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152A4C",
            },
        [20005903] = {
            ["Content"] = "哼唧……",
            ["ContentJP"] = "ブヒッ……",
            ["DialogueId"] = 20005903,
            ["GUID"] = "32152A76",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20005904,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152A76",
            },
        [20005904] = {
            ["Content"] = "榛子别丧气，我们再试试下一处地方。",
            ["ContentJP"] = "落ち込まないでヘーゼルナッツ。他の場所に行ってみましょう。",
            ["DialogueId"] = 20005904,
            ["GUID"] = "32152AA0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200059/32152AA0",
            },
        [20006001] = {
            ["Camera"] = "606.297791,-918.271484,784.640625,0.000207,-7.459188,79.056267,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "这里是……下水道入口？",
            ["ContentJP"] = "ここは……下水道の入口？",
            ["DialogueId"] = 20006001,
            ["FinalCamera"] = "541.89978,-1160.757812,832.416992,0.000208,-8.459162,77.455727,35.000015,174.116943,false,Manual,12.0",
            ["GUID"] = "32153A8A",
            ["NextDialogue"] = 20006002,
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153A8A",
            },
        [20006002] = {
            ["Camera"] = "-38.9104,-306.495117,391.232422,0.000209,-8.45895,-1.344757,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "嗯，这附近有很多水汽，而又没什么人，肯定会有魔灵出没的。",
            ["ContentJP"] = "はい、湿気が高くて人気が少ないので、きっとジェネモンがいるはずです。",
            ["DialogueId"] = 20006002,
            ["FinalCamera"] = "-508.082397,-300.290039,450.730469,0.000209,-7.058932,-0.744781,35.000019,174.116943,false,Manual,12.0",
            ["GUID"] = "32153AB4",
            ["NextDialogue"] = 20006003,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153AB4",
            },
        [20006003] = {
            ["Camera"] = "-768.485962,-608.558594,293.948242,0.000155,-2.058947,167.054123,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "不过，刚刚那两处地方的魔灵都被抓走了，有点担心这里也……",
            ["ContentJP"] = "ですが、先ほどの二ヶ所は既にジェネモンが回収されていたようですし、もしかしたらここのも……",
            ["DialogueId"] = 20006003,
            ["FinalCamera"] = "-796.652222,-602.085938,292.908691,0.000155,-0.458948,167.453751,35.000015,174.116943,false,Manual,12.0",
            ["GUID"] = "32153ADE",
            ["NextDialogue"] = 20006004,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153ADE",
            },
        [20006004] = {
            ["Camera"] = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
            ["Content"] = "啊，是还没被收走的陷阱！里面还有一只魔灵！",
            ["ContentJP"] = "いや、まだ回収されてないぞ！罠の中にジェネモンがいる！",
            ["DialogueId"] = 20006004,
            ["FinalCamera"] = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
            ["GUID"] = "32153B08",
            ["NextDialogue"] = 20006005,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200074:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B08",
            },
        [20006005] = {
            ["Camera"] = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,733.116943,false,Manual,22.0",
            ["Content"] = "太好了，这次总算赶上了。先把它放出来，再等那些魔灵猎人出现吧。",
            ["ContentJP"] = "間に合ってよかった！あの子を逃がしてから、ハンターたちが来るのを待ちましょう。",
            ["DialogueId"] = 20006005,
            ["FinalCamera"] = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,733.116943,false,Manual,22.0",
            ["GUID"] = "32153B32",
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200002:SpecialHappy_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B32",
            },
        [20006006] = {
            ["Content"] = "一阵手忙脚乱，困在陷阱里的魔灵被救了出来，但它的态度好像……不是非常友好。",
            ["ContentJP"] = "罠にかかったジェネモンを救い出した。だが、恐怖からか非常に興奮している……",
            ["DialogueId"] = 20006006,
            ["GUID"] = "32153B5C",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B5C",
            },
        [20006007] = {
            ["Camera"] = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,22.0",
            ["Content"] = "别害怕了小魔灵，本魔王大人以及小跟班，还有魔灵猎人猎人是来解救你们的，现在你自由了，远离这里吧！",
            ["ContentJP"] = "怖がるな、この魔王様と我が下僕、それからジェネモンハンターハンターが助けてやったぞ！さあ、さっさと行きな！",
            ["DialogueId"] = 20006007,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "32153B86",
            ["LookAt"] = {
                [1] = "200002:n(820000)",
                },
            ["NextDialogue"] = 20006008,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153B86",
            },
        [20006008] = {
            ["Camera"] = "-1100.135376,-637.394531,335.55957,0.000086,-3.391571,1.375749,35.0,1674.542114,false,Manual,6.0",
            ["Content"] = "咿咿呀——",
            ["ContentJP"] = "リォー",
            ["DialogueId"] = 20006008,
            ["GUID"] = "32153BB0",
            ["NextDialogue"] = 20006009,
            ["SpeakNpcId"] = 820000,
            ["SpeakNpcName"] = "UI_Npc_Name_PanTuokun",
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153BB0",
            },
        [20006009] = {
            ["Camera"] = "-619.304932,-686.379883,266.316895,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
            ["Content"] = "不必如此激动，这都是我们应该做的——话说回来，有点眼熟诶？这只魔灵是不是在冰湖城外就被我们救过一次？",
            ["ContentJP"] = "そう興奮するな、当然のことをしたまでだ。それはそうと……お前、どこかで見たような……？街の外で一度助けた子じゃないか？",
            ["DialogueId"] = 20006009,
            ["FinalCamera"] = "-646.760498,-696.469727,267.117676,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
            ["GUID"] = "32153BDA",
            ["NextDialogue"] = 20006010,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153BDA",
            },
        [20006010] = {
            ["Camera"] = "-422.686035,-758.615234,323.150879,0.000171,-5.031971,158.176743,35.000019,294.116943,false,Manual,12.0",
            ["Content"] = "你们也都快回家吧，可不要再被那些魔灵猎人抓到了哦，在我能被称为真正的魔灵猎人猎人之前，你们还是要小心一点才是。",
            ["ContentJP"] = "さあ、早くお家へ帰りなさい。次は捕まらないように気を付けるんだよ。私がハンターたちを懲らしめるまで、くれぐれも気を抜かないように。",
            ["DialogueId"] = 20006010,
            ["GUID"] = "32153C04",
            ["LookAt"] = {
                [1] = "200074:n(820000)",
                },
            ["NextDialogue"] = 20006011,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Explain02_Start",
                [2] = "200002:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C04",
            },
        [20006011] = {
            ["Camera"] = "-781.993408,-607.023438,317.071777,0.00017,-1.2322,-155.023941,35.000019,174.116943,false,Manual,12.0",
            ["Content"] = "看起来确实……很像。",
            ["ContentJP"] = "確かに、似ている気がする……",
            ["DialogueId"] = 20006011,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "32153C2E",
            ["NextDialogue"] = 20006012,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                [2] = "200074:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C2E",
            },
        [20006012] = {
            ["Camera"] = "-823.676147,-643.197266,314.435547,0.00011,-1.391562,0.574502,35.000008,242.039719,false,Manual,3.5",
            ["Content"] = "咿咿咿呀——",
            ["ContentJP"] = "リォリォーー",
            ["DialogueId"] = 20006012,
            ["GUID"] = "32153C58",
            ["NextDialogue"] = 20006013,
            ["SpeakNpcId"] = 820000,
            ["SpeakNpcName"] = "UI_Npc_Name_PanTuokun",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C58",
            },
        [20006013] = {
            ["Camera"] = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,314.116943,false,Manual,2.8",
            ["Content"] = "哎呀，别乱叫了，快走快走。下一次再被抓的话，可就不一定有这么好的运气了。",
            ["ContentJP"] = "こらこら、鳴いてないでさっさと行きなって。次も運良く助かる保証はないし、気を付けるんだぞ。",
            ["DialogueId"] = 20006013,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "-444.914062,-637.505859,353.714355,0.000175,-13.432099,-162.221298,35.000019,324.116943,false,Manual,2.8",
            ["GUID"] = "32153C82",
            ["NextDialogue"] = 20006014,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153C82",
            },
        [20006014] = {
            ["Camera"] = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
            ["Content"] = "我看……这只魔灵不太聪明嘛，和它说了这么多，都还不走。",
            ["ContentJP"] = "うーん、これだけ言っても動かないなんて、頭悪そうだな……",
            ["DialogueId"] = 20006014,
            ["FacialId"] = {
                [1] = "200002:Unhappy02",
                },
            ["FinalCamera"] = "-644.868896,-667.681641,299.754395,0.000098,-11.858697,-147.368286,35.000023,174.116943,false,Manual,12.0",
            ["GUID"] = "32153CAC",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153CAC",
            },
        [20006015] = {
            ["Content"] = "啪叽——",
            ["ContentJP"] = "バチンッ！",
            ["DialogueId"] = 20006015,
            ["GUID"] = "32153CD6",
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153CD6",
            },
        [20006016] = {
            ["Camera"] = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
            ["Content"] = "诶？怎么又钻到陷阱里去了？这只魔灵，是不是太害怕我们，所以把陷阱当做是安全的地方了？",
            ["ContentJP"] = "え！？また罠の中に入ってったぞ！？まさか、スノウたちを怖がって、罠が安全な場所だと勘違いしてるのか？",
            ["DialogueId"] = 20006016,
            ["FinalCamera"] = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
            ["GUID"] = "32153D00",
            ["NextDialogue"] = 20006017,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialConfident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D00",
            },
        [20006017] = {
            ["Camera"] = "-760.560303,-565.728516,290.460938,0.000099,-1.191192,-176.627136,35.000011,174.459366,false,Manual,2.8",
            ["Content"] = "唔，不应该呀，我们明明救过它，并且也没有表现出敌意。魔灵们虽然不会说话，但是是能分清楚谁对它好，谁对它坏的。",
            ["ContentJP"] = "うーん、でも敵意は感じられませんね。たとえ喋れなくても、私たちの行為に悪意がないのはわかるはずです……",
            ["DialogueId"] = 20006017,
            ["FacialId"] = {
                [1] = "200074:Sad01",
                },
            ["FinalCamera"] = "-784.401123,-567.131836,289.964355,0.000099,-1.191192,-176.427139,35.000011,138.232086,false,Manual,2.8",
            ["GUID"] = "32153D2A",
            ["NextDialogue"] = 20006018,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                [2] = "200002:SpecialConfident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D2A",
            },
        [20006018] = {
            ["Camera"] = "-538.68689,-695.786133,229.021973,0.000027,5.603125,151.387604,35.000008,345.779022,false,Manual,12.0",
            ["Content"] = "我想想……榛子有没有像这样，做的事我一开始完全无法理解的时候……",
            ["ContentJP"] = "そう言えば、ヘーゼルナッツも、こんなふうに理解できない行動を取ったことが何度かありましたね……",
            ["DialogueId"] = 20006018,
            ["FinalCamera"] = "-556.785034,-685.914062,231.044922,0.000028,5.603125,151.387619,35.000008,278.757599,false,Manual,12.0",
            ["GUID"] = "32153D54",
            ["NextDialogue"] = 20006019,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D54",
            },
        [20006019] = {
            ["Camera"] = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
            ["Content"] = "一次非得去看起来光秃秃的山谷里，后来才知道是因为它闻到了山谷深处有许多浆果……一次是停在花店门口不走，等我买了花，它就开心地一口吃掉……",
            ["ContentJP"] = "植物がほとんど生えていない谷へ連れて行かれたと思ったら、そこでたくさんのベリーを見つけたり……花屋の前で立ち止まるから、花を買ったら、それを嬉しそうに食べちゃったり……",
            ["DialogueId"] = 20006019,
            ["FinalCamera"] = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
            ["GUID"] = "32153D7E",
            ["NextDialogue"] = 20006020,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153D7E",
            },
        [20006020] = {
            ["Content"] = "还有一次，是它丢下我，拼命往山坡上跑，是因为附近的草丛里有蛇……它想把蛇引开……",
            ["ContentJP"] = "他にも、私をその場に置き去りにして坂道を駆け上がったこともありました。実はあの時、草むらに蛇がいたんです。きっと私を危険から遠ざけようと……",
            ["DialogueId"] = 20006020,
            ["GUID"] = "32153DA8",
            ["NextDialogue"] = 20006021,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DA8",
            },
        [20006021] = {
            ["Camera"] = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
            ["Content"] = "嗯……都是因为有很在意的事情……魔灵会在意什么呢？食物……还有伙伴！",
            ["ContentJP"] = "なので……彼の行動にも理由があると思うんです……食糧を求めてか、それとも……仲間？",
            ["DialogueId"] = 20006021,
            ["FinalCamera"] = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
            ["GUID"] = "32153DD2",
            ["NextDialogue"] = 20006022,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DD2",
            },
        [20006022] = {
            ["Camera"] = "-800.104004,-669.561523,327.374512,0.000095,-2.797638,176.175522,35.000008,104.665184,false,Manual,12.0",
            ["Content"] = "伙伴……我明白了！如果猜得没错的话，那些魔灵猎人的藏身之处就在下水道里。",
            ["ContentJP"] = "仲間……そうだ！きっとハンターたちはこの下水道に隠れているんだよ。",
            ["DialogueId"] = 20006022,
            ["FacialId"] = {
                [1] = "100001:Satisfy01",
                },
            ["GUID"] = "32153DFC",
            ["NextDialogue"] = 20006023,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"535.722229,-1070.53125,709.230469,0.000068,-6.997009,79.177307,35.0,174.116943,false,Manual,12.0\"},duration{0}},CameraMoveTo{_delay{0.5},TargetPosition{\"868.026001,153.00293,482.812988,0.000102,-2.791628,85.174393,35.000008,1674.542114,false,Manual,2.8\"},duration{5}}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200074:Think_End",
                [2] = "100001:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153DFC",
            },
        [20006023] = {
            ["Camera"] = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "在这里能嗅到其他被抓的魔灵的气息，所以它才不愿意离开。",
            ["ContentJP"] = "奴らに捕まった仲間の気配を感じたから、ここを離れたくないんじゃないかな？",
            ["DialogueId"] = 20006023,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["FinalCamera"] = "-771.952148,-667.40625,310.516113,0.000069,5.202958,177.175873,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153E26",
            ["NextDialogue"] = 20006024,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E26",
            },
        [20006024] = {
            ["Camera"] = "-821.866577,-728.666992,342.821289,0.000095,-11.597776,130.969742,35.000008,178.123947,false,Manual,2.8",
            ["Content"] = "很有可能噢，那这样一来的话，我们就可以在边上等着，要是那些魔灵猎人出现了，就跟着他们，狠狠教训他们一顿！",
            ["ContentJP"] = "確かにあり得ますね。なら、しばらくここで待ってみて、もしハンターが現れたら、コテンパンに懲らしめてやりましょう！",
            ["DialogueId"] = 20006024,
            ["FacialId"] = {
                [1] = "200074:Confident01",
                },
            ["FinalCamera"] = "-828.375366,-721.172852,340.748047,0.000093,-11.797785,130.969742,35.000008,178.123947,false,Manual,2.8",
            ["GUID"] = "32153E50",
            ["NextDialogue"] = 20006025,
            ["Scripts"] = "SEQ{\
LookAt{LookAtDescription{\"200074:n(100001)\"}},\
LookAt{LookAtDescription{\"100001:n(200074)\"}},\
PlayAnimation{ActorId{200074},AnimationId{\"AgreeHead\"},Duration{1}},\
PlayAnimation{_delay{5},\
ActorId{200074},AnimationId{\"Angry01_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E50",
            },
        [20006025] = {
            ["Camera"] = "-788.137817,-637.754883,224.224121,0.000072,-2.597166,-0.625336,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "嗯嗯嗯！",
            ["ContentJP"] = "ンンンッ！",
            ["DialogueId"] = 20006025,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["FinalCamera"] = "-756.913574,-638.139648,223.32666,0.000072,-3.397097,-1.225342,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153E7A",
            ["NextDialogue"] = 20006026,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_PanBeikun",
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153E7A",
            },
        [20006026] = {
            ["Camera"] = "-412.370728,-629.598633,225.119141,0.000073,3.802544,-175.221069,28.0,265.494751,false,Manual,12.0",
            ["Content"] = "唔，该说这只魔灵是聪明还是笨呢？能想着要去找伙伴，算得上是聪明吧，但又自己进到陷阱里，有点笨笨的。",
            ["ContentJP"] = "にしても、こいつは賢いのかバカなのか……仲間思いなのは褒めるが……自分から罠に飛び込むなどバカ極まりないぞ？",
            ["DialogueId"] = 20006026,
            ["FinalCamera"] = "-412.370728,-629.598633,241.541992,0.000073,0.002452,-175.420853,28.0,265.494751,false,Manual,12.0",
            ["GUID"] = "32153EA4",
            ["LookAt"] = {
                [1] = "200002:n(700251)",
                },
            ["NextDialogue"] = 20006027,
            ["Scripts"] = "PARA{\
LookAt{LookAtDescription{\"200074:n(200074)\"}},\
LookAt{LookAtDescription{\"100001:n(100001)\"}},\
PlayAnimation{ActorId{200074},AnimationId{\"Angry01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153EA4",
            },
        [20006027] = {
            ["Camera"] = "-700.815918,-705.999023,263.483887,0.000069,3.402636,153.177032,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "说不定它是看到我们，才故意又进到陷阱里，让我们好跟踪呢。",
            ["ContentJP"] = "もしかしたら、私たちが尾行しやすいように、わざと罠に入ったのかも？",
            ["DialogueId"] = 20006027,
            ["FinalCamera"] = "-755.168457,-688.192383,266.806152,0.000068,3.602624,148.576843,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153ECE",
            ["NextDialogue"] = 20006028,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153ECE",
            },
        [20006028] = {
            ["Camera"] = "-486.203613,-623.530273,240.246582,0.000087,2.002625,-162.023193,35.0,174.116943,false,Manual,12.0",
            ["Content"] = "真的假的？我觉得——",
            ["ContentJP"] = "本当か？そうは見えな――",
            ["DialogueId"] = 20006028,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-531.324463,-638.469727,243.410156,0.000087,4.602584,-160.822952,35.0,174.116943,false,Manual,12.0",
            ["GUID"] = "32153EF8",
            ["NextDialogue"] = 20006029,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153EF8",
            },
        [20006029] = {
            ["Content"] = "哎？不错啊，真抓到了一只。",
            ["ContentJP"] = "お？本当に一匹かかってるぞ。",
            ["DialogueId"] = 20006029,
            ["GUID"] = "32153F22",
            ["NextDialogue"] = 20006030,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F22",
            },
        [20006030] = {
            ["Camera"] = "-647.833496,-724.029297,337.969727,0.000094,-6.997679,159.175262,35.0,324.116943,false,Manual,12.0",
            ["Content"] = "是魔灵猎人，快躲起来。",
            ["ContentJP"] = "ジェネモンハンター{性别:だ|よ}、早く隠れて。",
            ["DialogueId"] = 20006030,
            ["GUID"] = "32153F4C",
            ["NextDialogue"] = 20006031,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "100001:n(200074)",
                [2] = "200074:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F4C",
            },
        [20006031] = {
            ["Content"] = "好！",
            ["ContentJP"] = "はい！",
            ["DialogueId"] = 20006031,
            ["GUID"] = "32153F76",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153F76",
            },
        [20006032] = {
            ["Camera"] = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
            ["Content"] = "好想现在就揍他们一顿，不过算了，等会儿有他们好看的！",
            ["ContentJP"] = "今すぐ打ちのめしてやりたいけど……我慢してやる。後で痛い目見せてやるからな！",
            ["DialogueId"] = 20006032,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["FinalCamera"] = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
            ["GUID"] = "32153FA0",
            ["NextDialogue"] = 20006033,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FA0",
            },
        [20006033] = {
            ["Camera"] = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
            ["Content"] = "本来以为冰湖城里的魔灵已经快被抓完了，没想到还有收获。",
            ["ContentJP"] = "この街のジェネモンはほぼ取り尽くしたと思ってましたが、まだ零れものがいたとは。",
            ["DialogueId"] = 20006033,
            ["GUID"] = "32153FCA",
            ["NextDialogue"] = 20006034,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FCA",
            },
        [20006034] = {
            ["Camera"] = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
            ["Content"] = "还是得出城啊，出城才能抓到更多。也不知道那个骑猪的小女孩什么时候才走。",
            ["ContentJP"] = "だが、街の外の方が圧倒的に多いのは確かだ。あのブタに乗った小娘、いつまでいる気だ？",
            ["DialogueId"] = 20006034,
            ["FinalCamera"] = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
            ["GUID"] = "32153FF4",
            ["NextDialogue"] = 20006035,
            ["SpeakNpcId"] = 200087,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32153FF4",
            },
        [20006035] = {
            ["Content"] = "别急嘛，我就不信了，捱上半个月，她还能在那里守着。",
            ["ContentJP"] = "まあまあ、半月もすればきっと諦めますって。",
            ["DialogueId"] = 20006035,
            ["GUID"] = "3215401E",
            ["NextDialogue"] = 20006036,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/3215401E",
            },
        [20006036] = {
            ["Content"] = "也是，天寒地冻的还有秽兽，说不定明天她就哭着鼻子回家啦。",
            ["ContentJP"] = "だな、こんなに寒いし、<Default note=\"text:エジュウ\">穢獣</>までうろついてる。早ければ明日にでも泣きべそかいて帰るかもな。",
            ["DialogueId"] = 20006036,
            ["GUID"] = "32154048",
            ["NextDialogue"] = 20006037,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Talk02_End",
                [2] = "200087:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32154048",
            },
        [20006037] = {
            ["Content"] = "最好这样！",
            ["ContentJP"] = "そりゃいい！",
            ["DialogueId"] = 20006037,
            ["GUID"] = "32154072",
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200060/32154072",
            },
        [20006101] = {
            ["Camera"] = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
            ["Content"] = "他们回下水道里了，走，快跟上。",
            ["ContentJP"] = "下水道に下りていったぞ。早く追いかけよう！",
            ["DialogueId"] = 20006101,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "32154AF2",
            ["NextDialogue"] = 20006102,
            ["Scripts"] = "PARA{SEQ{TurnTo{TurnToDescription{\"200002:n(100001)\"}},PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}},CameraMoveTo{_delay{2},TargetPosition{\"-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8\"},duration{0}}}",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154AF2",
            },
        [20006102] = {
            ["Camera"] = "-691.08667,-817.638672,263.54541,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
            ["Content"] = "小声点，别兴高采烈的，如果惊动了魔灵猎人，那只魔灵要是会说话，一定会骂你笨蛋的。",
            ["ContentJP"] = "しーっ、静かに。相手に気づかれたらどうする{性别:んだ|の}。あのジェネモンが口を利けたら、きっと今頃君をバカだって罵ってるよ。",
            ["DialogueId"] = 20006102,
            ["FinalCamera"] = "-710.927734,-796.919922,267.683105,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
            ["GUID"] = "32154B1C",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["NextDialogue"] = 20006103,
            ["Scripts"] = "LookAt{LookAtDescription{\"200074:n(200002)\"}}",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B1C",
            },
        [20006103] = {
            ["Camera"] = "-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8",
            ["Content"] = "哼，才不会，我刚刚那么关心它，一定给它留下了好印象！",
            ["ContentJP"] = "そんなわけないよ。きっと、ここまでしてくれてるスノウたちに感謝してるはず！",
            ["DialogueId"] = 20006103,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "32154B46",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20006104,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B46",
            },
        [20006104] = {
            ["Camera"] = "-832.142822,-728.967773,342.387207,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
            ["Content"] = "噗哧……你们啊……虽然我年纪不大，但是带着榛子也见过很多人了，但像你们这样，在意魔灵想法的人可不多。",
            ["ContentJP"] = "ふふっ……今まで色んな人と出会ってきましたが、ジェネモンの気持ちを考えてくれる方は滅多にいませんでした。",
            ["DialogueId"] = 20006104,
            ["FinalCamera"] = "-837.814453,-721.487305,340.496582,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
            ["GUID"] = "32154B70",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                },
            ["NextDialogue"] = 20006105,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B70",
            },
        [20006105] = {
            ["Content"] = "要是每个人都像你们一样，意识到动物和魔灵也是有自己喜好的，就不会有魔灵猎人了！",
            ["ContentJP"] = "動物やジェネモンにも、感情があることをみんなが分かってくれたら、彼らを狩る人たちもいなくなるのに……",
            ["DialogueId"] = 20006105,
            ["GUID"] = "32154B9A",
            ["NextDialogue"] = 20006106,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154B9A",
            },
        [20006106] = {
            ["Camera"] = "-809.379883,-578.354492,277.954102,0.000212,5.809533,178.160782,35.000011,115.034302,false,Manual,2.8",
            ["Content"] = "走吧走吧，这一次我一定要让他们彻底知错！",
            ["ContentJP"] = "いきましょう。今度こそ彼らに反省してもらわなくちゃ！",
            ["DialogueId"] = 20006106,
            ["FinalCamera"] = "-822.223877,-577.945312,279.260742,0.000213,5.809533,178.160782,35.000011,110.479393,false,Manual,2.8",
            ["GUID"] = "32154BC4",
            ["LookAt"] = {
                [1] = "200074:n(200074)",
                },
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200061/32154BC4",
            },
        [20006201] = {
            ["Camera"] = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
            ["Content"] = "唔，原来这里的下水道这么复杂。榛子，能闻到魔灵的味道吗？",
            ["ContentJP"] = "すごく入り組んだ下水道ですね……ヘーゼルナッツ、ジェネモンの場所は分かる？",
            ["DialogueId"] = 20006201,
            ["GUID"] = "32155B5A",
            ["NextDialogue"] = 20006202,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155B5A",
            },
        [20006202] = {
            ["Content"] = "哼唧……",
            ["ContentJP"] = "ブヒッ……",
            ["DialogueId"] = 20006202,
            ["GUID"] = "32155B84",
            ["NextDialogue"] = 20006203,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155B84",
            },
        [20006203] = {
            ["Content"] = "味道太多了反而无法分辨方向？唔，只能先向前走了。",
            ["ContentJP"] = "匂いが多すぎて方角が分からない？うーん、このまま進むしかないようですね。",
            ["DialogueId"] = 20006203,
            ["GUID"] = "32155BAE",
            ["NextDialogue"] = 20006204,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155BAE",
            },
        [20006204] = {
            ["Content"] = "跟着我走就好，我对这里可熟悉了。",
            ["ContentJP"] = "ここには詳しいんだ、スノウに任せて！",
            ["DialogueId"] = 20006204,
            ["GUID"] = "32155BD8",
            ["NextDialogue"] = 20006205,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155BD8",
            },
        [20006205] = {
            ["Content"] = "咦，原来小白平时住在这种地方吗？",
            ["ContentJP"] = "詳しい？なるほど、スノウちゃんはこういう場所に住んでいるんですね？",
            ["DialogueId"] = 20006205,
            ["GUID"] = "32155C02",
            ["NextDialogue"] = 20006206,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C02",
            },
        [20006206] = {
            ["Content"] = "不……不是的，只是身为魔王大人，之前来过这里巡视过几次，远来的魔灵猎人猎人哟，跟紧了。",
            ["ContentJP"] = "ち、ちがう！何度か視察に来ただけだ。さあジェネモンハンターハンターよ、この魔王様についてくるがいい！",
            ["DialogueId"] = 20006206,
            ["GUID"] = "32155C2C",
            ["NextDialogue"] = 20006207,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C2C",
            },
        [20006207] = {
            ["Content"] = "好~",
            ["ContentJP"] = "了解！",
            ["DialogueId"] = 20006207,
            ["GUID"] = "32155C56",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200062/32155C56",
            },
        [20006301] = {
            ["Content"] = "啊，这个痕迹，之前巡视的时候可没有见到过。",
            ["ContentJP"] = "ん？この痕は……？視察の時にはなかったものだな。",
            ["DialogueId"] = 20006301,
            ["GUID"] = "32156BC2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20006302,
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200063/32156BC2",
            },
        [20006302] = {
            ["Content"] = "看起来像是被抓的那个魔灵留下来的，跟着这个痕迹吧。",
            ["ContentJP"] = "捕まったジェネモンが残したもののようですね。これを辿ってみましょう！",
            ["DialogueId"] = 20006302,
            ["GUID"] = "32156BEC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200063/32156BEC",
            },
        [20006401] = {
            ["Content"] = "痕迹越来越新，应该不远了……",
            ["ContentJP"] = "痕跡が新しい――かなり近くまで来ているかと……",
            ["DialogueId"] = 20006401,
            ["GUID"] = "32157C2A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 20006402,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200064/32157C2A",
            },
        [20006402] = {
            ["Content"] = "我好像听见有人在说话——",
            ["ContentJP"] = "むむ？何やら話し声が――",
            ["DialogueId"] = 20006402,
            ["GUID"] = "32157C54",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 200002,
            ["VoiceName"] = "voice/$Locale$/story/2001/200064/32157C54",
            },
        [20006501] = {
            ["Camera"] = "802.462891,37.094727,399.100616,0.000002,-18.600189,1.600099,35.000011,403.34671,false,Manual,12.0",
            ["Content"] = "我跟你说，这只魔灵……据说是所有魔灵里最聪明、最稀有、也是所有魔灵的最初形态——潘神。",
            ["ContentJP"] = "こいつはジェネモンの中でも一番賢くて、珍しい、すべてのジェネモンのオリジナル――パーンだ。",
            ["DialogueId"] = 20006501,
            ["FinalCamera"] = "559.453125,30.306641,481.861816,0.000002,-18.800184,1.600099,35.000011,403.34671,false,Manual,12.0",
            ["GUID"] = "32158C92",
            ["NextDialogue"] = 20006502,
            ["SpeakNpcId"] = 200075,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158C92",
            },
        [20006502] = {
            ["Content"] = "最聪明？真的假的？真要是最聪明，怎么会被我们抓到？",
            ["ContentJP"] = "賢い？僕たちに捕まったのに、ですか？",
            ["DialogueId"] = 20006502,
            ["GUID"] = "32158CBC",
            ["NextDialogue"] = 20006503,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200087:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158CBC",
            },
        [20006503] = {
            ["Camera"] = "565.943359,-554.305664,435.741028,0.000025,-6.400112,56.795567,35.000008,100000.0,false,Manual,22.0",
            ["Content"] = "你什么意思？你是说我们很笨，所以不可能抓到最聪明的魔灵？",
            ["ContentJP"] = "どういう意味だ？俺たちの頭じゃ、賢いジェネモンを捕まえられないって言いてえのか？",
            ["DialogueId"] = 20006503,
            ["FinalCamera"] = "586.517578,-522.865234,431.526306,0.000026,-6.400112,56.795399,35.000008,100000.0,false,Manual,22.0",
            ["GUID"] = "32158CE6",
            ["LookAt"] = {
                [1] = "200075:n(200087)",
                },
            ["NextDialogue"] = 20006504,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Talk03_Start",
                [2] = "200087:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158CE6",
            },
        [20006504] = {
            ["Camera"] = "485.179688,62.989258,489.663513,0.000012,-12.999386,-2.199652,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "我……我没这个意思，老大你可聪明了，要不是靠着你做的陷阱，我们怎么能抓到这么多魔灵。",
            ["ContentJP"] = "まさか！アニキの完璧な罠があったから、これだけたくさんのジェネモンを捕まえられたんじゃないですか。",
            ["DialogueId"] = 20006504,
            ["FinalCamera"] = "610.728516,58.283203,460.538757,0.000012,-13.199401,-1.999653,35.000008,450.0,false,Manual,6.0",
            ["GUID"] = "32158D10",
            ["LookAt"] = {
                [1] = "200087:n(200075)",
                },
            ["NextDialogue"] = 20006505,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200087:Shock_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D10",
            },
        [20006505] = {
            ["Content"] = "那是，你看，咱们已经抓了这么多魔灵，慢慢来研究，总能找出从它们身上炼出月石的方法，写出论文来。",
            ["ContentJP"] = "ふん、当然だ。さて、これだけのジェネモンがいれば、月ノ石を錬成する方法も見つかるだろう。そして、その過程を論文に残すんだ。",
            ["DialogueId"] = 20006505,
            ["GUID"] = "32158D3A",
            ["LookAt"] = {
                [1] = "200075:n(200075)",
                },
            ["NextDialogue"] = 20006506,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200087:Shock_End",
                [2] = "200075:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D3A",
            },
        [20006506] = {
            ["Content"] = "到时候，我看谁还敢嘲笑我是炼金院的肄业生！",
            ["ContentJP"] = "もう誰にも錬金院の落ちこぼれとは言わせねえぞ！",
            ["DialogueId"] = 20006506,
            ["GUID"] = "32158D64",
            ["NextDialogue"] = 20006507,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D64",
            },
        [20006507] = {
            ["Content"] = "老大，我对论文什么的不感兴趣，能分点银币给我就好了。",
            ["ContentJP"] = "僕は論文には興味ないので、報酬の分け前さえもらえれば……",
            ["DialogueId"] = 20006507,
            ["GUID"] = "32158D8E",
            ["NextDialogue"] = 20006508,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_End",
                [2] = "200087:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158D8E",
            },
        [20006508] = {
            ["Content"] = "好说，都好说。",
            ["ContentJP"] = "おう、期待しとけ。",
            ["DialogueId"] = 20006508,
            ["GUID"] = "32158DB8",
            ["LookAt"] = {
                [1] = "200087:n(200087)",
                },
            ["NextDialogue"] = 20006509,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200087:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158DB8",
            },
        [20006509] = {
            ["Camera"] = "0.919922,-0.328125,154.78241,0.000047,-0.999783,-169.994827,35.000008,147.718536,false,Manual,8.0",
            ["Content"] = "我觉得，不怎么好说。",
            ["ContentJP"] = "水をさすようで悪いけど、させないよ。",
            ["DialogueId"] = 20006509,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "32158DE2",
            ["NextDialogue"] = 20006510,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158DE2",
            },
        [20006510] = {
            ["Camera"] = "460.484375,70.31543,355.815216,0.000048,1.599391,-2.995058,35.000008,300.0,false,Manual,8.0",
            ["Content"] = "你们是……",
            ["ContentJP"] = "お前たちは……",
            ["DialogueId"] = 20006510,
            ["FinalCamera"] = "525.451172,67.851562,357.435608,0.000048,1.39939,-2.39505,35.000008,300.0,false,Manual,8.0",
            ["GUID"] = "32158E0C",
            ["NextDialogue"] = 20006511,
            ["Scripts"] = "PARA{TurnTo{TurnToDescription{\"200075:p(-150)\"}},TurnTo{TurnToDescription{\"200087:p(150)\"}}}",
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E0C",
            },
        [20006511] = {
            ["Camera"] = "47.310547,-89.34375,82.346375,0.000071,6.199694,-170.591293,35.000011,184.872482,false,Manual,8.0",
            ["Content"] = "我乃纯白之救赎，光之魔王大人！",
            ["ContentJP"] = "我は白き救世主、光の魔王様なり！",
            ["DialogueId"] = 20006511,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "33.654297,-91.604492,83.850006,0.000072,8.199676,-167.790817,35.000011,131.269821,false,Manual,8.0",
            ["GUID"] = "32158E36",
            ["NextDialogue"] = 20006512,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E36",
            },
        [20006512] = {
            ["Camera"] = "13.498047,83.051758,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
            ["Content"] = "我……我乃魔灵猎人猎人，粮秣专员松露！以及粮秣特别专员，榛子！",
            ["ContentJP"] = "わ、我々は、ジェネモンハンターハンターにして、食糧補給官トリュフ、そして食糧補給特別官ヘーゼルナッツなり！",
            ["DialogueId"] = 20006512,
            ["FinalCamera"] = "2.105469,81.813477,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
            ["GUID"] = "32158E60",
            ["NextDialogue"] = 20006513,
            ["Scripts"] = "PARA{\
CameraMoveTo{_delay{6.01},TargetPosition{\"150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0\"},duration{0}},\
SEQ{\
PlayFacial{_delay{3.5},ActorId{200074},FacialId{\"Confident01\"}},\
PlayAnimation{_delay{3.1},ActorId{200074},AnimationId{\"Confident_Start\"}}\
}\
}",
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E60",
            },
        [20006513] = {
            ["Camera"] = "150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0",
            ["Content"] = "哼哼！",
            ["ContentJP"] = "ブヒブヒ！",
            ["DialogueId"] = 20006513,
            ["FinalCamera"] = "134.871094,118.75,17.023186,0.000235,24.799322,157.617859,35.0,628.586243,false,Manual,12.0",
            ["GUID"] = "32158E8A",
            ["NextDialogue"] = 200065130,
            ["SpeakNpcId"] = 200086,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158E8A",
            },
        [20006514] = {
            ["Camera"] = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,16.0",
            ["Content"] = "懂了，你们是盖雷亚剧院的演员。",
            ["ContentJP"] = "あ？ガレア劇場の役者か？",
            ["DialogueId"] = 20006514,
            ["GUID"] = "32158EB4",
            ["NextDialogue"] = 20006515,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158EB4",
            },
        [20006515] = {
            ["Camera"] = "-26.337891,71.758789,115.010025,0.000102,5.001563,-179.000427,35.000019,100.535843,false,Manual,8.0",
            ["Content"] = "不……不是的！请你们放了这些魔灵！否则，我会让榛子撞飞你们！",
            ["ContentJP"] = "ち、違います！とにかく、ジェネモンたちを解放しなさい！さもないと、ヘーゼルナッツの体当たりをお見舞いしますよ！",
            ["DialogueId"] = 20006515,
            ["GUID"] = "32158EDE",
            ["Scripts"] = "SEQ{\
PlayFacial{_delay{0.1},ActorId{200074},FacialId{\"Unacceptable01\"}},\
PlayFacial{_delay{0.6},ActorId{200074},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_End",
                [2] = "200074:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158EDE",
            },
        [20006516] = {
            ["Camera"] = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
            ["Content"] = "刚刚在城外不就是你和这个什么光之魔头坏了我们的好事吗？",
            ["ContentJP"] = "嘘つけ！そこの光の魔物とやらと街の外で俺たちの邪魔をしたの、覚えてるぞ！",
            ["DialogueId"] = 20006516,
            ["GUID"] = "32158F08",
            ["NextDialogue"] = 20006517,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F08",
            },
        [20006517] = {
            ["Camera"] = "-27.242188,73.443359,154.929871,0.00007,-15.000351,-177.200226,35.000015,130.614029,false,Manual,8.0",
            ["Content"] = "是光之魔王大人，不好好记住别人的名字是很没有礼貌的行为，会被榛子撞飞的！",
            ["ContentJP"] = "光の魔王です！人の名前を間違える失礼な人には、ヘーゼルナッツの体当たりをお見舞いしますよ！",
            ["DialogueId"] = 20006517,
            ["FacialId"] = {
                [1] = "200074:Confident02",
                },
            ["GUID"] = "32158F32",
            ["LookAt"] = {
                [1] = "200074:n(200075)",
                },
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F32",
            },
        [20006518] = {
            ["Camera"] = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
            ["Content"] = "白日做——梦！",
            ["ContentJP"] = "できない相談だな！",
            ["DialogueId"] = 20006518,
            ["GUID"] = "32158F5C",
            ["NextDialogue"] = 20006519,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "200075:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F5C",
            },
        [20006519] = {
            ["Camera"] = "9.128906,71.000977,164.786407,0.000102,-18.198389,-178.600586,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "如果是这样的话，那……榛子，撞飞他们！",
            ["ContentJP"] = "そういうことなら……ヘーゼルナッツ、あいつらを吹き飛ばしちゃって！",
            ["DialogueId"] = 20006519,
            ["FinalCamera"] = "-9.466797,68.333008,115.745117,0.000102,3.801383,-177.600464,35.000011,131.004227,false,Manual,6.0",
            ["GUID"] = "32158F86",
            ["LookAt"] = {
                [1] = "200074:n(200075)",
                },
            ["Scripts"] = "SEQ{\
PlayFacial{_delay{0.1},ActorId{200074},FacialId{\"Confident02\"}},\
PlayFacial{_delay{1.6},ActorId{200074},FacialId{\"Doubt01\"}}\
}",
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_End",
                [2] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/story/2001/200065/32158F86",
            },
        [20006601] = {
            ["Content"] = "打就打，还怕你们几个半大孩子和一头畜生不成？",
            ["ContentJP"] = "けっ、ガキ三人と畜生一匹に、俺たちが負けるはずないだろ！",
            ["DialogueId"] = 20006601,
            ["GUID"] = "32159CFA",
            ["NextDialogue"] = 20006602,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159CFA",
            },
        [20006602] = {
            ["Content"] = "不可以这么骂榛子！向榛子道歉！",
            ["ContentJP"] = "畜生ですって！？ヘーゼルナッツに謝りなさい！",
            ["DialogueId"] = 20006602,
            ["GUID"] = "32159D24",
            ["NextDialogue"] = 20006603,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159D24",
            },
        [20006603] = {
            ["Content"] = "能打赢再说！",
            ["ContentJP"] = "俺たちに勝てたらな！",
            ["DialogueId"] = 20006603,
            ["GUID"] = "32159D4E",
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159D4E",
            },
        [20006604] = {
            ["Content"] = "咿咿呀——",
            ["ContentJP"] = "リォー",
            ["DialogueId"] = 20006604,
            ["GUID"] = "32159D78",
            ["NextDialogue"] = 20006605,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159D78",
            },
        [20006605] = {
            ["Content"] = "不好了老大，这个魔灵把其他魔灵都放出来了！",
            ["ContentJP"] = "大変です、アニキ！あのパーンが他のジェネモンを全部逃がしちゃいました！",
            ["DialogueId"] = 20006605,
            ["GUID"] = "32159DA2",
            ["NextDialogue"] = 20006606,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159DA2",
            },
        [20006606] = {
            ["Content"] = "啾——",
            ["ContentJP"] = "チィー！！",
            ["DialogueId"] = 20006606,
            ["GUID"] = "32159DCC",
            ["NextDialogue"] = 20006607,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159DCC",
            },
        [20006607] = {
            ["Content"] = "咩——",
            ["ContentJP"] = "メェー！",
            ["DialogueId"] = 20006607,
            ["GUID"] = "32159DF6",
            ["NextDialogue"] = 20006608,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159DF6",
            },
        [20006608] = {
            ["Content"] = "叮咚——",
            ["ContentJP"] = "ポロロンー",
            ["DialogueId"] = 20006608,
            ["GUID"] = "32159E20",
            ["NextDialogue"] = 20006609,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159E20",
            },
        [20006609] = {
            ["Content"] = "啊呀，好烫好烫——好麻——冷冷冷——",
            ["ContentJP"] = "ぎゃああ！アチチィ――し、痺れるぅ――冷てえー！！",
            ["DialogueId"] = 20006609,
            ["GUID"] = "32159E4A",
            ["NextDialogue"] = 20006610,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159E4A",
            },
        [20006610] = {
            ["Content"] = "我错了！我错了！",
            ["ContentJP"] = "わ、悪かった！悪かったから！",
            ["DialogueId"] = 20006610,
            ["GUID"] = "32159E74",
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200066/32159E74",
            },
        [20006701] = {
            ["Camera"] = "-939.216797,26.854492,320.087097,0.0,-13.407927,0.807412,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "{nickname}大人，魔灵猎人猎人大人，还有光之魔王大人，我错了，我们错了。这些魔灵我们都不要了，饶了我们。",
            ["ContentJP"] = "{nickname}様、ジェネモンハンターハンター様、そして光の魔王様！俺たちが間違ってた！ジェネモンは全部解放する、だから許してくれえぇ！",
            ["DialogueId"] = 20006701,
            ["GUID"] = "3215AD62",
            ["NextDialogue"] = 20006702,
            ["SpeakNpcId"] = 200087,
            ["TalkActionId"] = {
                [1] = "200075:Avoid",
                [2] = "200087:Avoid",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AD62",
            },
        [20006702] = {
            ["Content"] = "诶？不用这么害怕，只要你们保证以后不再乱捉魔灵，我和榛子就不会把你们怎么样的。",
            ["ContentJP"] = "あら、そんなに怖がらなくても、二度とジェネモンをいじめないと約束すれば、ワタシもヘーゼルナッツもこれ以上は何もしませんよ。",
            ["DialogueId"] = 20006702,
            ["GUID"] = "3215AD8C",
            ["NextDialogue"] = 20006703,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AD8C",
            },
        [20006703] = {
            ["Content"] = "一定，一定。",
            ["ContentJP"] = "も、もちろんだ！",
            ["DialogueId"] = 20006703,
            ["GUID"] = "3215ADB6",
            ["NextDialogue"] = 20006704,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215ADB6",
            },
        [20006704] = {
            ["Content"] = "我也一定不捉魔灵了！也监督老大，要是老大又开始抓魔灵，我第一个告诉你们！",
            ["ContentJP"] = "僕も二度とジェネモンを捕まえたりしないよ！もしアニキが捕まえようとしても、ちゃんと止めるから！",
            ["DialogueId"] = 20006704,
            ["GUID"] = "3215ADE0",
            ["NextDialogue"] = 20006705,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215ADE0",
            },
        [20006705] = {
            ["Content"] = "好，那么你们也需要向它们道歉。",
            ["ContentJP"] = "分かりました。では、この子たちに謝ってください。",
            ["DialogueId"] = 20006705,
            ["GUID"] = "3215AE0A",
            ["NextDialogue"] = 20006706,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE0A",
            },
        [20006706] = {
            ["Content"] = "非常抱歉！是我利欲熏心，本来想要研究魔灵，却怎么都写不出论文，所以动起了歪心思……你们来捕猎我吧，让我这个魔灵猎人体验魔灵猎人……",
            ["ContentJP"] = "申し訳なかった！一時の気の迷いだったんだ……俺はジェネモンの研究をしてたんだが、どうしても論文が書けなくて……な、なんなら今度は俺たちが狩られる側になってもいい。それで気が済むなら……",
            ["DialogueId"] = 20006706,
            ["GUID"] = "3215AE34",
            ["NextDialogue"] = 20006708,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE34",
            },
        [20006707] = {
            ["Content"] = "我实在是不聪明，居然质疑潘神大人的智力，潘神大人比我还要聪明……比老大还要聪明！今天开始我称呼你为老大……",
            ["ContentJP"] = "聡明なパーン様の前では、アニキや僕なんて足元にも及びません！き、今日からはあなたをアニキと呼ばせてください！",
            ["DialogueId"] = 20006707,
            ["GUID"] = "3215AE5E",
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE5E",
            },
        [20006708] = {
            ["Content"] = "咿咿。",
            ["ContentJP"] = "リリッ！",
            ["DialogueId"] = 20006708,
            ["GUID"] = "3215AE88",
            ["NextDialogue"] = 20006709,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AE88",
            },
        [20006709] = {
            ["Camera"] = "35.800781,50.916992,117.894058,0.000003,-4.407924,143.206772,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "唔，看你们这么诚恳，姑且相信你们吧。那么，接下来，{nickname}，小白，我们得想办法安置这些魔灵。",
            ["ContentJP"] = "いいでしょう、そこまで言うなら信じてあげます。さて……{nickname}さん、スノウちゃん、このジェネモンたち、どうしましょう？",
            ["DialogueId"] = 20006709,
            ["FinalCamera"] = "140.537109,-26.151367,129.112198,0.000003,-5.407959,144.206726,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215AEB2",
            ["NextDialogue"] = 20006710,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AEB2",
            },
        [20006710] = {
            ["Camera"] = "-101.119141,154.260742,108.99675,0.000025,3.592208,132.807907,35.000015,110.824821,false,Manual,6.0",
            ["Content"] = "这么多魔灵，应该没法带出冰湖城，直接放生的话，它们也会因为附近没有月石这样的能量来源陷入困境……",
            ["ContentJP"] = "これだけの数を街の外に連れ出すのは無理ですし、このまま逃がしても、近くには月ノ石のようなエネルギー源がないので、この子たちが困るだけです……",
            ["DialogueId"] = 20006710,
            ["FacialId"] = {
                [1] = "200074:Unhappy01",
                },
            ["GUID"] = "3215AEDC",
            ["NextDialogue"] = 20006711,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AEDC",
            },
        [20006711] = {
            ["Camera"] = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192425,35.000015,161.420593,false,Manual,6.0",
            ["Content"] = "怎么会这样……也就是说尽管我们救了它们，但还是不能确保它们一定都能活下来是吗？",
            ["ContentJP"] = "そんな……せっかく助け出せても、生き残れるか分からないってことか？",
            ["DialogueId"] = 20006711,
            ["FacialId"] = {
                [1] = "200002:Unacceptable01",
                },
            ["FinalCamera"] = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192459,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215AF06",
            ["NextDialogue"] = 20006712,
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF06",
            },
        [20006712] = {
            ["Camera"] = "-64.103516,31.655273,119.67865,0.000029,-4.808036,119.607536,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "是的，除非有足够多的月石……可是这么多的魔灵，除非冰湖城每户人家都拿出一块月石来……可是一般人都很害怕魔灵的，肯定不愿意这么做……",
            ["ContentJP"] = "そうなんです。こんなにたくさんのジェネモン、街の皆さんが一人ずつ月ノ石を提供してくれない限りはとても……でも、彼らは怖がられることが多いので、きっと厳しいかと……",
            ["DialogueId"] = 20006712,
            ["FinalCamera"] = "14.46875,-50.96875,106.754761,0.000019,-3.007906,-59.192356,35.000015,134.451996,false,Manual,6.0",
            ["GUID"] = "3215AF30",
            ["NextDialogue"] = 20006713,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF30",
            },
        [20006713] = {
            ["Camera"] = "-108.800781,-45.291992,165.959991,0.000029,-12.807772,59.206985,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "哼哼……",
            ["ContentJP"] = "ブヒブヒ……",
            ["DialogueId"] = 20006713,
            ["GUID"] = "3215AF5A",
            ["NextDialogue"] = 20006714,
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF5A",
            },
        [20006714] = {
            ["Camera"] = "-112.921875,-23.537109,160.274353,0.000064,1.1921,-114.590996,35.000011,159.3237,false,Manual,6.0",
            ["Content"] = "嗯……得想想办法……",
            ["ContentJP"] = "なんとか方法を考えないと……",
            ["DialogueId"] = 20006714,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["FinalCamera"] = "-122.841797,-45.224609,160.77063,0.000065,2.392089,-114.590553,35.000011,142.061966,false,Manual,6.0",
            ["GUID"] = "3215AF84",
            ["NextDialogue"] = 20006715,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AF84",
            },
        [20006715] = {
            ["Camera"] = "-20.984375,-89.079102,120.151733,0.000088,-7.208342,-37.78812,35.000015,123.723419,false,Manual,6.0",
            ["Content"] = "虽然我还没有亲眼见到，但是一想到这件事可能是真的，就觉得非常可怕！",
            ["ContentJP"] = "まだ実際に目にしたわけじゃないけど、もし本当なら、恐ろしいことになるぞ！",
            ["DialogueId"] = 20006715,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["FinalCamera"] = "-40.863281,-87.678711,84.628616,0.000085,7.591741,-32.988117,35.000015,161.950012,false,Manual,6.0",
            ["GUID"] = "3215AFAE",
            ["NextDialogue"] = 20006716,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AFAE",
            },
        [20006716] = {
            ["Camera"] = "-92.931641,513.984375,128.895233,0.000055,-1.407743,-97.792145,35.000008,450.0,false,Manual,6.0",
            ["Content"] = "松露，在你的家乡，大家会害怕榛子吗？",
            ["ContentJP"] = "トリュフ、君の故郷でも、ヘーゼルナッツは恐れられていたの？",
            ["DialogueId"] = 20006716,
            ["GUID"] = "3215AFD8",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                },
            ["NextDialogue"] = 20006717,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.1},ActorId{100001},AnimationId{\"Think_End\"}},\
PARA{\
PlayFacial{_delay{0.5},ActorId{100001},FacialId{\"Confident01\"}},\
PlayAnimation{_delay{2.1},ActorId{100001},AnimationId{\"Talk02_Start\"}}\
}\
}",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215AFD8",
            },
        [20006717] = {
            ["Camera"] = "-130.119141,-252.262695,186.619904,0.00007,-10.007689,106.210793,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "嗯？实话说，一开始大家没看过这么大的猪，都会有点害怕的。但是一旦知道榛子能够和我一起找到很多食物，非常能干，就不害怕了。",
            ["ContentJP"] = "え？うーん、この子は大きいから、皆さん最初は驚いてたし、少しは怖がってましたけど、私と一緒に食べ物を探すことができると知ってからは、そんなこともなくなりました。",
            ["DialogueId"] = 20006717,
            ["FacialId"] = {
                [1] = "200074:Smile01",
                },
            ["GUID"] = "3215B002",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20006718,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                [2] = "200074:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B002",
            },
        [20006718] = {
            ["Camera"] = "-143.039062,97.484375,110.879364,0.000087,0.791714,106.205078,35.000015,140.05127,false,Manual,6.0",
            ["Content"] = "是的，觉得害怕是因为不够了解，如果让大家了解魔灵的能力，获得魔灵的帮助，就一定不会害怕了。",
            ["ContentJP"] = "うん。人は分からないものを恐れる。だから、みんなにジェネモンの力や、彼らが役に立つことを知ってもらえれば、きっと恐怖も薄れるんじゃないかな。",
            ["DialogueId"] = 20006718,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["FinalCamera"] = "-146.861328,105.399414,111.090088,0.000087,1.391712,107.405457,35.000015,140.05127,false,Manual,6.0",
            ["GUID"] = "3215B02C",
            ["NextDialogue"] = 20006719,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B02C",
            },
        [20006719] = {
            ["Content"] = "松露，白，我们一起把这些魔灵带到水仙平原去。",
            ["ContentJP"] = "トリュフ、スノウ、この子たちをアスフォデロスまで連れて行こう。",
            ["DialogueId"] = 20006719,
            ["GUID"] = "3215B056",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B056",
            },
        [20006720] = {
            ["Camera"] = "390.472656,-23.833008,76.522202,0.000054,0.592102,149.805954,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "好的，榛子坐下，我们把魔灵放到你的背上，一口气都带出去。",
            ["ContentJP"] = "分かりました。ヘーゼルナッツ、ジェネモンたちをキミの背中に乗せて運ぶから、座って。",
            ["DialogueId"] = 20006720,
            ["FinalCamera"] = "290.703125,34.223633,80.627289,0.000054,2.592091,149.805908,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B080",
            ["LookAt"] = {
                [1] = "200074:n(200086)",
                },
            ["NextDialogue"] = 20006721,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B080",
            },
        [20006721] = {
            ["Content"] = "嗯？又要找卡米拉吗？她呀，肯定又要嘴上说着不愿意，然后和你一起想办法了。",
            ["ContentJP"] = "ということは、またカミラに頼むのか？まあ、あいつのことだから、口ではイヤイヤいいながら、一緒に方法を考えてくれるだろうけど。",
            ["DialogueId"] = 20006721,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "3215B0AA",
            ["NextDialogue"] = 20006722,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B0AA",
            },
        [20006722] = {
            ["Content"] = "我也来帮忙！",
            ["ContentJP"] = "俺も手伝わせてくれ！",
            ["DialogueId"] = 20006722,
            ["GUID"] = "3215B0D4",
            ["NextDialogue"] = 20006723,
            ["SpeakNpcId"] = 200087,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B0D4",
            },
        [20006723] = {
            ["Content"] = "还有我，还有我。",
            ["ContentJP"] = "ぼ、僕も！",
            ["DialogueId"] = 20006723,
            ["GUID"] = "3215B0FE",
            ["NextDialogue"] = 20006724,
            ["SpeakNpcId"] = 200075,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B0FE",
            },
        [20006724] = {
            ["Camera"] = "25.234375,43.664062,76.073486,0.000057,-10.207888,-1.19403,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "咿咿。",
            ["ContentJP"] = "リリッ！",
            ["DialogueId"] = 20006724,
            ["FinalCamera"] = "-37.855469,44.204102,84.949371,0.000057,-8.007871,-0.194,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B128",
            ["NextDialogue"] = 20006725,
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B128",
            },
        [20006725] = {
            ["Camera"] = "447.40625,104.102539,80.368851,0.000072,-1.207823,-159.593887,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "嗯？你不一起跟着来吗？",
            ["ContentJP"] = "ん？君は一緒に来ないの？",
            ["DialogueId"] = 20006725,
            ["FinalCamera"] = "483.496094,102.482422,81.651184,0.000072,-3.00781,-160.39386,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B152",
            ["LookAt"] = {
                [1] = "100001:n(700251)",
                },
            ["NextDialogue"] = 20006726,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B152",
            },
        [20006726] = {
            ["Camera"] = "45.181641,44.441406,28.436035,0.000076,6.992051,-0.794525,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "魔灵潘神一般都会和人尽可能保持距离，看起来刚刚它只是想靠你们把其他魔灵救出来。",
            ["ContentJP"] = "パーンジェネモンは滅多に人と接触しないんだ。お前たちに近づいたのも、仲間たちを助けてほしかったからだろうな。",
            ["DialogueId"] = 20006726,
            ["FinalCamera"] = "-94.589844,48.933594,37.514648,0.000076,0.791967,-1.194519,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B17C",
            ["NextDialogue"] = 20006727,
            ["SpeakNpcId"] = 200075,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B17C",
            },
        [20006727] = {
            ["Camera"] = "-76.480469,-72.768555,129.284988,0.000097,13.191738,-135.390411,35.000015,137.250519,false,Manual,6.0",
            ["Content"] = "好，那你也要小心。",
            ["ContentJP"] = "そっか、じゃあ気を付けて。",
            ["DialogueId"] = 20006727,
            ["FinalCamera"] = "-99.601562,-95.574219,136.62146,0.000099,15.191671,-135.990753,35.000015,105.456551,false,Manual,6.0",
            ["GUID"] = "3215B1A6",
            ["NextDialogue"] = 20006728,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B1A6",
            },
        [20006728] = {
            ["Camera"] = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
            ["Content"] = "咿咿咿。",
            ["ContentJP"] = "リリリッ！",
            ["DialogueId"] = 20006728,
            ["FinalCamera"] = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
            ["GUID"] = "3215B1D0",
            ["SpeakNpcId"] = 700251,
            ["SpeakNpcName"] = "UI_Npc_Name_Pan_Common",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200067/3215B1D0",
            },
        [20006801] = {
            ["Content"] = "最终，这些魔灵被一起带到了水仙平原，吓跑了一屋子的客人，并成功让卡米拉眉头紧锁，开始思考当初是不是不应该带{nickname}进城。",
            ["ContentJP"] = "アスフォデロスに現れたジェネモンたちを見て、客人は全員が逃げ出した。\
カミラは眉をひそめ、{nickname}を街に連れて来たことをしばし後悔し始めた。",
            ["DialogueId"] = 20006801,
            ["Duration"] = 5,
            ["GUID"] = "3215BDCA",
            ["VoiceName"] = "voice/$Locale$/story/2001/200068/3215BDCA",
            },
        [20006901] = {
            ["Content"] = "又过了一段时间，卡米拉的眉头终于缓缓舒展开来……",
            ["ContentJP"] = "だがやがて、その眉間のシワは徐々に消えていった……",
            ["DialogueId"] = 20006901,
            ["Duration"] = 3,
            ["GUID"] = "3215CE32",
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CE32",
            },
        [20006902] = {
            ["Camera"] = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "哟，卡米拉，给我来一杯“打火鸡特调”，这么冷的天来上一口，再合适不过了。",
            ["ContentJP"] = "よう、カミラ、「モエドリカクテル」を一杯くれや。こんな寒い日には、あれがぴったりだ。",
            ["DialogueId"] = 20006902,
            ["GUID"] = "3215CE5C",
            ["LookAt"] = {
                [1] = "700253:n(700248)",
                [2] = "700254:n(700253)",
                },
            ["NextDialogue"] = 20006903,
            ["Scripts"] = "PARA{\
PlayFacial{_delay{3.5},ActorId{700248},FacialId{\"Confident01\"}},\
PlayAnimation{_delay{3.1},ActorId{700248},AnimationId{\"Talk03_Start\"}}\
}",
            ["SpeakNpcId"] = 700253,
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CE5C",
            },
        [20006903] = {
            ["Content"] = "一开始我觉得这小东西很邪门，没想到喷出的火焰拿来温酒，绝了！",
            ["ContentJP"] = "いやあ、最初は怪しい鳥だと思ってたが、こいつが出す炎で温まった酒は絶品だ！",
            ["DialogueId"] = 20006903,
            ["GUID"] = "3215CE86",
            ["LookAt"] = {
                [1] = "700253:n(700253)",
                },
            ["NextDialogue"] = 20006904,
            ["SpeakNpcId"] = 700253,
            ["TalkActionId"] = {
                [1] = "700253:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CE86",
            },
        [20006904] = {
            ["Camera"] = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "可悲啊，威尔斯先生，可叹啊，威尔斯先生。",
            ["ContentJP"] = "まだまだですねえ、ウェルズさん。",
            ["DialogueId"] = 20006904,
            ["GUID"] = "3215CEB0",
            ["NextDialogue"] = 20006905,
            ["SpeakNpcId"] = 700254,
            ["TalkActionId"] = {
                [1] = "700254:Sigh_Start",
                [2] = "700253:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CEB0",
            },
        [20006905] = {
            ["Camera"] = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "你只知道打火鸡的火焰可以让酒水温热，暖及肚肠，却不知道它真正的价值，在于划破黑暗，在黑夜中为我点亮书本，带来灵感！",
            ["ContentJP"] = "モエドリの炎はお酒と体を温めるだけだと思っていませんか？その真価は、闇を裂き、夜を照らし、私に創造の光を授けることにあるのですよ！",
            ["DialogueId"] = 20006905,
            ["GUID"] = "3215CEDA",
            ["NextDialogue"] = 20006906,
            ["SpeakNpcId"] = 700254,
            ["TalkActionId"] = {
                [1] = "700254:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CEDA",
            },
        [20006906] = {
            ["Camera"] = "-89.716675,175.708008,152.642578,-0.000763,-3.992218,-88.380859,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "打，火，鸡。多么美妙的三个字，我的写作生命之光，我的创作欲念之火！我的罪恶，我的灵魂！",
            ["ContentJP"] = "モ・エ・ド・リ！なんと素晴らしい名前！我が創作を燃え上がらせる欲望の炎！まさに我が罪であり、我が魂そのもの！",
            ["DialogueId"] = 20006906,
            ["GUID"] = "3215CF04",
            ["SpeakNpcId"] = 700254,
            ["TalkActionId"] = {
                [1] = "700254:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200069/3215CF04",
            },
        [20007001] = {
            ["Camera"] = "410.60437,303.494141,154.748047,0.000089,0.396813,37.710804,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "有人用雨衣水滴浇花，有人用好梦先生助眠……就连我的生意，也离不开一只打火鸡。",
            ["ContentJP"] = "今じゃピチョンで花に水やりをする者や、ミスタードリームで眠りを改善する者もいる。私の商売ですら、モエドリ頼りになったわ。",
            ["DialogueId"] = 20007001,
            ["FinalCamera"] = "262.071167,223.890625,147.691406,0.000094,-1.403686,36.110554,35.000011,369.08606,false,Manual,12.0",
            ["GUID"] = "3215DE9A",
            ["NextDialogue"] = 20007002,
            ["Scripts"] = "PARA{\
SEQ{\
TurnTo{_delay{2},TurnToDescription{\"700248:p(180)\"}},\
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Confident_Start\"},Duration{1}}\
},\
PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}\
}",
            ["SpeakNpcId"] = 700248,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DE9A",
            },
        [20007002] = {
            ["Content"] = "现在根本不会有人想要从魔灵身上提炼月石，反而会为了和魔灵更加亲近，专门买月石去喂养它们，挺有趣的。",
            ["ContentJP"] = "今となっては、ジェネモンから月ノ石を精製しようなんて思う者もいなくなった。それどころか、月ノ石を買って彼らに与えているんだもの。面白いわよね。",
            ["DialogueId"] = 20007002,
            ["GUID"] = "3215DEC4",
            ["LookAt"] = {
                [1] = "100001:n(200074)",
                [2] = "200002:n(200074)",
                },
            ["NextDialogue"] = 20007003,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1},ActorId{700248},AnimationId{\"Confident_End\"},Duration{1}},\
PARA{\
PlayAnimation{_delay{1.5},ActorId{700248},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayFacial{_delay{7.5},ActorId{700248},FacialId{\"Smile02\"}}\
},\
PlayFacial{_delay{1.0},ActorId{700248},FacialId{\"None\"}}\
}",
            ["SpeakNpcId"] = 700248,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DEC4",
            },
        [20007003] = {
            ["Camera"] = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "这也是看到松露和榛子才想到的。既然榛子能和人类友好相处，那么魔灵也能。",
            ["ContentJP"] = "トリュフとヘーゼルナッツを見て思いついた{性别:んだ|の}。ヘーゼルナッツが人間と仲良くなれるのなら、他のジェネモンだってきっと同じだってね。",
            ["DialogueId"] = 20007003,
            ["GUID"] = "3215DEEE",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20007004,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1},ActorId{700248},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DEEE",
            },
        [20007004] = {
            ["Camera"] = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,169.08606,false,Manual,12.0",
            ["Content"] = "而如果魔灵都能和人类友好相处，那么卡戎和索拉之民，迟早有一天也会相处融洽的。",
            ["ContentJP"] = "それに、ジェネモンと人間が仲良くなれれば、カロン族とソラの民も、いつかはわかり合えるんじゃないかと思って。",
            ["DialogueId"] = 20007004,
            ["GUID"] = "3215DF18",
            ["NextDialogue"] = 20007005,
            ["Scripts"] = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF18",
            },
        [20007005] = {
            ["Camera"] = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "哈哈，我都不好说你是天真，还是看得足够远，让我好好期待那一天的到来吧。但在那之前，该送别那一位小朋友了。",
            ["ContentJP"] = "ふふ、ほんと、あなたってほんと、天然なのか計算高いのか分からないわ。まあ、その前に、まずはあの子にお別れを言わなきゃね。",
            ["DialogueId"] = 20007005,
            ["FinalCamera"] = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
            ["GUID"] = "3215DF42",
            ["NextDialogue"] = 20007006,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Sigh_Start\"},Duration{2}},\
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{\"Sigh_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 700248,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF42",
            },
        [20007006] = {
            ["Camera"] = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "呜呜呜，松露，你就不能留在冰湖城吗？光之魔王大人好不容易找到一个伙伴愿意和我一起大声念出自己的称号！",
            ["ContentJP"] = "ううう……トリュフ、本当に出ていくのか？せっかくこの光の魔王にノってくれる仲間を見つけたというのに！",
            ["DialogueId"] = 20007006,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["GUID"] = "3215DF6C",
            ["NextDialogue"] = 20007007,
            ["SpeakNpcId"] = 200002,
            ["TurnTo"] = {
                [1] = "200074:p(30)",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF6C",
            },
        [20007007] = {
            ["Content"] = "别哭呀小白，我已经出门很久啦，该回去了。再说了，那几个魔灵猎人都改行变成魔灵学者了，你可以让他们和你一起念称号呀。",
            ["ContentJP"] = "泣かないで、スノウちゃん。私は帰らないといけませんが、ここにはジェネモン博士になった元ジェネモンハンターたちがいるでしょう。",
            ["DialogueId"] = 20007007,
            ["GUID"] = "3215DF96",
            ["NextDialogue"] = 20007008,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DF96",
            },
        [20007008] = {
            ["Camera"] = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "不，他们说话没有你说话好听，也不能和你一样让榛子背着我兜风。{nickname}你也别傻站着，留一留松露呀。",
            ["ContentJP"] = "お前とは比べ物にもならないぞ。それに、ヘーゼルナッツに乗って散歩できなくなるし……{nickname}、お前も突っ立ってないで、一緒に引き留めてよ！",
            ["DialogueId"] = 20007008,
            ["FacialId"] = {
                [1] = "200002:Unhappy01",
                },
            ["GUID"] = "3215DFC0",
            ["NextOptions"] = {
                [1] = 200070081,
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "700248:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DFC0",
            },
        [20007009] = {
            ["Camera"] = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
            ["Content"] = "嘿嘿，以后我也会时不时来玩的。{性别：大哥哥|大姐姐}，悄悄告诉你哦，我要回去的那个很远很远的地方，其实是艾利西安传颂会。",
            ["ContentJP"] = "ふふ、また遊びに来ますから。{性别:お兄さん|お姉さん}にだけこっそり教えますね……実は私、エリュシオン礼賛会から来たんです。",
            ["DialogueId"] = 20007009,
            ["FacialId"] = {
                [1] = "200002:CM_Idle",
                },
            ["FinalCamera"] = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
            ["GUID"] = "3215DFEA",
            ["LookAt"] = {
                [1] = "200074:n(100001)",
                },
            ["NextDialogue"] = 20007010,
            ["SpeakNpcId"] = 200074,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215DFEA",
            },
        [20007010] = {
            ["Camera"] = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
            ["Content"] = "我收集食物时，偶尔会和榛子一起越过那些没有人看守的高山，到海伯利亚来。一开始我还有点害怕，因为传颂会和帝国一直在打仗嘛。",
            ["ContentJP"] = "ヘーゼルナッツと一緒に食べ物を探していると、たまに見張りのいない山を越えて、ヒュペリアまで来ることがあるんです。最初はちょっぴり怖かったんですよ。礼賛会と帝国はまだ戦争中だから……",
            ["DialogueId"] = 20007010,
            ["GUID"] = "3215E014",
            ["NextDialogue"] = 20007011,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E014",
            },
        [20007011] = {
            ["Content"] = "但是遇到了{性别：大哥哥|大姐姐}后，我就不害怕了。",
            ["ContentJP"] = "でも{性别:お兄さん|お姉さん}と会ってからは、全然怖くなくなりました。",
            ["DialogueId"] = 20007011,
            ["GUID"] = "3215E03E",
            ["NextDialogue"] = 20007012,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E03E",
            },
        [20007012] = {
            ["Content"] = "{性别：大哥哥|大姐姐}能够想出办法让魔灵和人类相处，那么就一定能让卡戎和索拉不再互相讨厌，帝国和传颂会也能不再打仗。",
            ["ContentJP"] = "ジェネモンと人間が共存できる方法を見つけてくれた{性别:お兄さん|お姉さん}なら、きっとカロン族とソラの対立や、帝国と礼賛会の戦争を終わらせることができると信じてます。",
            ["DialogueId"] = 20007012,
            ["GUID"] = "3215E068",
            ["NextDialogue"] = 20007013,
            ["SpeakNpcId"] = 200074,
            ["TalkActionId"] = {
                [1] = "200074:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E068",
            },
        [20007013] = {
            ["Content"] = "这样一来，大家就都不会饿肚子了！",
            ["ContentJP"] = "そうなれば、お腹を空かせる人もいなくなりますから！",
            ["DialogueId"] = 20007013,
            ["GUID"] = "3215E092",
            ["NextDialogue"] = 20007014,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E092",
            },
        [20007014] = {
            ["Content"] = "到那时候，也请你和小白，还有卡米拉女士，一起到南方。吃粉嘟嘟的红蕈、吹烫烫的海风、看这里看不到的星星，和我在这里一样开心！等着你哦！",
            ["ContentJP"] = "その時は是非、スノウちゃんやカミラさんと一緒に南に遊びに来て下さい。可愛いピンクのキノコを食べたり、暖かい海風を浴びたり、ここでは見られない星を眺めましょう！待ってますからね！",
            ["DialogueId"] = 20007014,
            ["GUID"] = "3215E0BC",
            ["NextDialogue"] = 20007015,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E0BC",
            },
        [20007015] = {
            ["Content"] = "嗯，我会尽量做到。",
            ["ContentJP"] = "うん、頑張るよ。",
            ["DialogueId"] = 20007015,
            ["GUID"] = "3215E0E6",
            ["NextDialogue"] = 20007016,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E0E6",
            },
        [20007016] = {
            ["Content"] = "拉钩为定。",
            ["ContentJP"] = "指切りげんまん！",
            ["DialogueId"] = 20007016,
            ["GUID"] = "3215E110",
            ["NextOptions"] = {
                [1] = 200070161,
                },
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E110",
            },
        [20007017] = {
            ["Content"] = "也要和榛子拉钩。",
            ["ContentJP"] = "ヘーゼルナッツとも指切りしてください。",
            ["DialogueId"] = 20007017,
            ["GUID"] = "3215E13A",
            ["NextDialogue"] = 20007018,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E13A",
            },
        [20007018] = {
            ["Content"] = "榛子的蹄子太粗，拉不了勾啦。",
            ["ContentJP"] = "さすがに無理かな。",
            ["DialogueId"] = 20007018,
            ["GUID"] = "3215E164",
            ["NextDialogue"] = 20007019,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E164",
            },
        [20007019] = {
            ["Content"] = "那握住它的蹄子就行。来，我们一起：拉钩上吊，一百年不许变！",
            ["ContentJP"] = "なら、足を握るだけでいいですよ。ほら、一緒に、指切りげんまん～嘘ついたら針千本の～ます。指切った！",
            ["DialogueId"] = 20007019,
            ["GUID"] = "3215E18E",
            ["NextDialogue"] = 20007020,
            ["SpeakNpcId"] = 200074,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E18E",
            },
        [20007020] = {
            ["Content"] = "哼唧！",
            ["ContentJP"] = "ブヒッ！",
            ["DialogueId"] = 20007020,
            ["GUID"] = "3215E1B8",
            ["SpeakNpcId"] = 200086,
            ["VoiceName"] = "voice/$Locale$/story/2001/200070/3215E1B8",
            },
        [20007101] = {
            ["Content"] = "我乃——冰湖城第一魔灵学者！有什么魔灵疑问，都可以问我——啊，是你啊……有……有什么事吗？",
            ["ContentJP"] = "我は、アイスレイク城いちのジェネモン博士！ジェネモンに関することは、なんでも俺に――あ、お前……な、何か用か？",
            ["DialogueId"] = 20007101,
            ["GUID"] = "3215EF02",
            ["NextOptions"] = {
                [1] = 200071011,
                [2] = 200071012,
                [3] = 200071013,
                },
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF02",
            },
        [20007102] = {
            ["Content"] = "你是说那个很聪明的魔灵吗？",
            ["ContentJP"] = "あの賢いジェネモンのことか？",
            ["DialogueId"] = 20007102,
            ["GUID"] = "3215EF2C",
            ["NextDialogue"] = 20007103,
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF2C",
            },
        [20007103] = {
            ["Content"] = "关于它的记录非常少，我也只见过那一次，听说只有受到它们的认可，才能找到他们。",
            ["ContentJP"] = "俺もあの時初めて見たんだが、あれに関する記録はほとんどないんだ。彼らは認めた相手の前にしか姿を現さないとか。",
            ["DialogueId"] = 20007103,
            ["GUID"] = "3215EF56",
            ["NextDialogue"] = 20007104,
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF56",
            },
        [20007104] = {
            ["Content"] = "不过，你应该可以顺着它们留下来的痕迹找到藏身的地方。",
            ["ContentJP"] = "でも、お前ならあいつらが残した痕跡を辿って隠れ家を見つけられるんじゃないか？",
            ["DialogueId"] = 20007104,
            ["GUID"] = "3215EF80",
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EF80",
            },
        [20007105] = {
            ["Content"] = "比做魔灵猎人要好多了，每天都有许多人来问我魔灵问题，好像我真的是什么大学者一样。",
            ["ContentJP"] = "ジェネモンハンターなんかより百倍マシだ。毎日色んな人からジェネモンのことを聞かれるんだ。本物の博士になった気分だよ。",
            ["DialogueId"] = 20007105,
            ["GUID"] = "3215EFAA",
            ["NextDialogue"] = 20007106,
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EFAA",
            },
        [20007106] = {
            ["Content"] = "多谢你和松露手下留情，多谢多谢。",
            ["ContentJP"] = "お前とトリュフちゃんが手加減してくれたおかげだな。ありがとよ。",
            ["DialogueId"] = 20007106,
            ["GUID"] = "3215EFD4",
            ["SpeakNpcId"] = 200075,
            ["SpeakNpcName"] = "UI_CMNpc_Name_MolingXZ",
            ["VoiceName"] = "voice/$Locale$/story/2001/200071/3215EFD4",
            },
        [20007107] = {
            ["Content"] = "若干道深深的刻痕，似是某种尖锐物体留下的痕迹。",
            ["ContentJP"] = "ぎざぎざの何かで抉られたような、深い傷跡がいくつも残っている。",
            ["DialogueId"] = 20007107,
            ["GUID"] = "3215EFD5",
            },
        [20007108] = {
            ["Content"] = "写着“禁区危险，严禁通行”的告示。贴了厚厚一叠，似乎是当老告示变旧了就会贴一张新告示上去。最新的一张告示落款是新历1004年，也就是二十年前——格雷姆矿场应当就是在那时彻底废弃的。",
            ["ContentJP"] = "「危険!立入禁止」と書かれた掲示が、何枚も分厚く重ねて貼られている。\
 古い掲示が色あせるたびに上から足してきたのだろう。いちばん新しい一枚の日付は新暦1004年――およそ二十年前。グルビューム鉱山はその頃に廃棄されたらしい。",
            ["DialogueId"] = 20007108,
            ["GUID"] = "3215EFD6",
            },
        [21000101] = {
            ["Content"] = "背白白进场台词（测试用）",
            ["DialogueId"] = 21000101,
            ["GUID"] = "34925112",
            ["TalkActionId"] = {
                [1] = "900005:Beibao_Start",
                },
            },
        [21000102] = {
            ["Content"] = "背白白退场台词（测试用）",
            ["DialogueId"] = 21000102,
            ["GUID"] = "3492513C",
            ["TalkActionId"] = {
                [1] = "900005:Beibao_Finish",
                },
            },
        [50000101] = {
            ["Content"] = "通行证——喂，说你呢，通行证带了吗？",
            ["ContentJP"] = "通行許可証を――おい、お前だよお前。通行許可証は持っているんだろうな？",
            ["DialogueId"] = 50000101,
            ["Duration"] = 3,
            ["GUID"] = "7D2B8592",
            ["SpeakNpcId"] = 700111,
            ["VoiceName"] = "voice/$Locale$/env/700002/7D2B8592",
            },
        [50000201] = {
            ["Content"] = "居然有狩月人能找到这里，看来你和它们一样，有着成为英雄的可能啊。",
            ["ContentJP"] = "月狩り人がよくここを見つけたな。お前さん、英雄になれる素質があるぞ。\
あいつらみたいな。",
            ["DialogueId"] = 50000201,
            ["Duration"] = 4,
            ["GUID"] = "7D2B95FA",
            ["SpeakNpcId"] = 700003,
            ["VoiceName"] = "voice/$Locale$/env/700003/7D2B95FA",
            },
        [50000301] = {
            ["Content"] = "**的都怪格朗德，我现在到底该怎么办呢……嗯？看什么看，我这今天也没有委托！",
            ["ContentJP"] = "**なグランドのせいだ！いったいどうすれば……\
ん？なんだね？今日は依頼はないぞ。",
            ["DialogueId"] = 50000301,
            ["Duration"] = 3,
            ["GUID"] = "7D2BA662",
            ["SpeakNpcId"] = 700004,
            ["VoiceName"] = "voice/$Locale$/env/700004/7D2BA662",
            },
        [50000401] = {
            ["Content"] = "我是……安妮？",
            ["ContentJP"] = "私の名前は……アニー、なの？",
            ["DialogueId"] = 50000401,
            ["Duration"] = 3,
            ["GUID"] = "7D2BB6CA",
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700032/7D2BB6CA",
            },
        [50000501] = {
            ["Content"] = "等身体养好了，我就打算开始下一段冒险了。",
            ["ContentJP"] = "体調が回復したら、旅を再開するつもりです。",
            ["DialogueId"] = 50000501,
            ["Duration"] = 3,
            ["GUID"] = "7D2BC732",
            ["SpeakNpcId"] = 700005,
            ["TalkActionId"] = {
                [1] = "700032:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700005/7D2BC732",
            },
        [50000601] = {
            ["Content"] = "我该带什么去见妈妈呢……她一定很想我。",
            ["ContentJP"] = "お母さんに会ったら何から話そうかな……きっと、すごく心配しているはず。",
            ["DialogueId"] = 50000601,
            ["Duration"] = 3,
            ["GUID"] = "7D2BD79A",
            ["SpeakNpcId"] = 700005,
            ["TalkActionId"] = {
                [1] = "700005:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700005/7D2BD79A",
            },
        [50000701] = {
            ["Content"] = "安妮……安妮！",
            ["ContentJP"] = "アニー……アニー！",
            ["DialogueId"] = 50000701,
            ["Duration"] = 3,
            ["GUID"] = "7D2BE802",
            ["SpeakNpcId"] = 700006,
            ["VoiceName"] = "voice/$Locale$/env/700006/7D2BE802",
            },
        [50000801] = {
            ["Content"] = "今天的鲜花真好看啊，得留几朵给那孩子送去。",
            ["ContentJP"] = "今日のお花はとてもきれいね。あの子のために何本か残しておこうかしら。",
            ["DialogueId"] = 50000801,
            ["Duration"] = 3,
            ["GUID"] = "7D2BF86A",
            ["SpeakNpcId"] = 700007,
            ["TalkActionId"] = {
                [1] = "700007:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700007/7D2BF86A",
            },
        [50000901] = {
            ["Content"] = "您好，这朵花与您今天的装扮很相称……如果那孩子还在的话，一定也会这么说吧。",
            ["ContentJP"] = "いらっしゃいませ。あなたの服装に合わせるなら、今日はこちらのお花がピッタリですよ……あの子がいたら、きっとこう言うはずです。",
            ["DialogueId"] = 50000901,
            ["Duration"] = 5,
            ["GUID"] = "7D2C08D2",
            ["SpeakNpcId"] = 700203,
            ["VoiceName"] = "voice/$Locale$/env/700007/7D2C08D2",
            },
        [50001001] = {
            ["Content"] = "您这身板样貌，不穿我家的衣服可惜了。",
            ["ContentJP"] = "その恵まれたルックスとスタイル！私の店の服を着ないなんて、もったいないですよ！",
            ["DialogueId"] = 50001001,
            ["Duration"] = 3,
            ["GUID"] = "7D2C193A",
            ["SpeakNpcId"] = 700008,
            ["VoiceName"] = "voice/$Locale$/env/700008/7D2C193A",
            },
        [50001101] = {
            ["Content"] = "自家庄园的好果子，别的地方没有这培育技术！",
            ["ContentJP"] = "自家農園の最高フルーツ！よそにはまねできない栽培技術で育てた一級品だ！",
            ["DialogueId"] = 50001101,
            ["Duration"] = 3,
            ["GUID"] = "7D2C29A2",
            ["SpeakNpcId"] = 700009,
            ["TalkActionId"] = {
                [1] = "700009:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700009/7D2C29A2",
            },
        [50001201] = {
            ["Content"] = "啊……哇哇我……",
            ["ContentJP"] = "あ……わ、わ、私……",
            ["DialogueId"] = 50001201,
            ["Duration"] = 2,
            ["GUID"] = "7D2C3A0A",
            ["SpeakNpcId"] = 700010,
            ["VoiceName"] = "voice/$Locale$/env/700010/7D2C3A0A",
            },
        [50001301] = {
            ["Content"] = "嗯……实验对象1号，就决定是你了！",
            ["ContentJP"] = "よし……栄えある実験体第1号は君に決まりだ！",
            ["DialogueId"] = 50001301,
            ["Duration"] = 3,
            ["GUID"] = "7D2C4A72",
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700011/7D2C4A72",
            },
        [50001401] = {
            ["Content"] = "{nickname}，又见面啦！我每天都在努力学习新知识哦，一起加油吧！",
            ["ContentJP"] = "{NickName}、また会ったね！僕は新しい知識を学んでいるところさ！お互い頑張ろう！",
            ["DialogueId"] = 50001401,
            ["Duration"] = 4,
            ["GUID"] = "7D2C5ADA",
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700011/7D2C5ADA",
            },
        [50001501] = {
            ["Content"] = "你……卡戎……我的同类……",
            ["ContentJP"] = "あなたは……カロン……私と同族……",
            ["DialogueId"] = 50001501,
            ["Duration"] = 6,
            ["GUID"] = "7D2C6B42",
            ["SpeakNpcId"] = 700012,
            ["VoiceName"] = "voice/$Locale$/env/700012/7D2C6B42",
            },
        [50001601] = {
            ["Content"] = "见不得人的事我见多了，涉事的主角们也不止有“恶魔”。\
……有时我也分不清，人类与卡戎，到底谁才是恶魔。",
            ["ContentJP"] = "表沙汰にできない物事は嫌というほど見てきたけど。関わっていたのは「悪魔」だけじゃない……時々わからなくなるの。ヒトとカロン、どちらが悪魔なのかしら。",
            ["DialogueId"] = 50001601,
            ["Duration"] = 4,
            ["GUID"] = "7D2C7BAA",
            ["SpeakNpcId"] = 700013,
            ["VoiceName"] = "voice/$Locale$/env/700013/7D2C7BAA",
            },
        [50001701] = {
            ["Content"] = "呸！不识货的蠢婆娘！我倒要看看你还能兴风作浪到什么时候！",
            ["ContentJP"] = "チッ！モノの価値がわからない年増女め！いつまでもいきがれると思うなよ！",
            ["DialogueId"] = 50001701,
            ["Duration"] = 4,
            ["GUID"] = "7D2C8C12",
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700014/7D2C8C12",
            },
        [50001801] = {
            ["Content"] = "皇帝在上，我这样善良的人儿却碰上了偷窃灵感的幽魂！哦，这真是一桩老天爷见了都会落泪的冤案！",
            ["ContentJP"] = "神よ、なぜだ！善なる者の私になぜ、無限のインスピレーションを盗み取る悪しき魂を遣わしたのだ\
！これは万物を司る大いなる神が見ても、悲嘆の涙を流すほどの冤罪ではなかろうか！",
            ["DialogueId"] = 50001801,
            ["Duration"] = 4,
            ["GUID"] = "7D2C9C7A",
            ["SpeakNpcId"] = 700015,
            ["VoiceName"] = "voice/$Locale$/env/700015/7D2C9C7A",
            },
        [50001901] = {
            ["Content"] = "真没劲！净组织些虚头巴脑的活动，还不如放半天假呢！",
            ["ContentJP"] = "つまんないの！こんな上っ面だけの儀式を繰りかえしてさ！こんなことより半日休みにして欲しいよ。",
            ["DialogueId"] = 50001901,
            ["Duration"] = 3,
            ["GUID"] = "7D2CACE2",
            ["SpeakNpcId"] = 700016,
            ["VoiceName"] = "voice/$Locale$/env/700016/7D2CACE2",
            },
        [50002001] = {
            ["Content"] = "“下雨了，妈妈的花被浇坏了，所以天空在水坑里赔给妈妈无数朵小花。”",
            ["ContentJP"] = "「雨がふりました。お母さんのお花は、ぬれてしょんぼりしています。おわびに、空は、水たまりにたくさんのお花を咲かせて、お母さんにあやまったのでした」",
            ["DialogueId"] = 50002001,
            ["Duration"] = 3,
            ["GUID"] = "7D2CBD4A",
            ["NextDialogue"] = 50002002,
            ["SpeakNpcId"] = 700017,
            ["VoiceName"] = "voice/$Locale$/env/700017/7D2CBD4A",
            },
        [50002002] = {
            ["Content"] = "——您知道吗，这首诗叫做《道歉》，是我六岁的学生写的。",
            ["ContentJP"] = "ねえ知ってる？この詩の題名は『ごめんね』。6歳の生徒が書いた作品なの。",
            ["DialogueId"] = 50002002,
            ["Duration"] = 3,
            ["GUID"] = "7D2CBD74",
            ["SpeakNpcId"] = 700017,
            ["TalkActionId"] = {
                [1] = "700017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700017/7D2CBD74",
            },
        [50002101] = {
            ["Content"] = "向自然法则扔出的石头，最终一定会砸到自己的头上。",
            ["ContentJP"] = "自然の摂理に逆らい天へ石を投げようとも、最終的には必ず返ってきて、自分の頭に当たるものなのです。",
            ["DialogueId"] = 50002101,
            ["Duration"] = 3,
            ["GUID"] = "7D2CCDB2",
            ["SpeakNpcId"] = 700018,
            ["TalkActionId"] = {
                [1] = "700018:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700018/7D2CCDB2",
            },
        [50002201] = {
            ["Content"] = "到底去了哪里啊……",
            ["ContentJP"] = "どこに行ってしまったの……",
            ["DialogueId"] = 50002201,
            ["Duration"] = 3,
            ["GUID"] = "7D2CDE1A",
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700019/7D2CDE1A",
            },
        [50002301] = {
            ["Content"] = "希望今晚的奶油蘑菇浓汤能让夫人感到稍许舒适。",
            ["ContentJP"] = "今夜はマッシュルームのクリームスープよ。おいしいスープで奥様の心が少しでも安らぎますように……",
            ["DialogueId"] = 50002301,
            ["Duration"] = 4,
            ["GUID"] = "7D2CEE82",
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700020/7D2CEE82",
            },
        [50002401] = {
            ["Content"] = "真可怜，每天疯疯癫癫的。",
            ["ContentJP"] = "かわいそうに……毎日、気も狂わんばかりのご様子で......",
            ["DialogueId"] = 50002401,
            ["Duration"] = 3,
            ["GUID"] = "7D2CFEEA",
            ["NextDialogue"] = 50002402,
            ["SpeakNpcId"] = 700023,
            ["VoiceName"] = "voice/$Locale$/env/700023/7D2CFEEA",
            },
        [50002402] = {
            ["Content"] = "怪不得她女儿会受不了她的管教。",
            ["ContentJP"] = "正直言って過保護過ぎるような……娘さんが耐えられなかったのもわかる気がしますね……",
            ["DialogueId"] = 50002402,
            ["Duration"] = 3,
            ["GUID"] = "7D2CFF14",
            ["SpeakNpcId"] = 700024,
            ["VoiceName"] = "voice/$Locale$/env/700024/7D2CFF14",
            },
        [50002501] = {
            ["Content"] = "全城的垃圾桶都归我管，那里有只穿过几回的鹿皮靴子，没来得及打蔫的百合花，还有不知道是谁碎掉的梦……",
            ["ContentJP"] = "街全体のゴミ箱は、その中のお宝も含めて、このマーティンが丸っと管理しておりますよ！\
数回しか履いてないシカ皮のブーツ、まだ生き生きと咲くユリの花、さらには誰かの砕けた夢の欠片まで……",
            ["DialogueId"] = 50002501,
            ["Duration"] = 3,
            ["GUID"] = "7D2D0F52",
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700022/7D2D0F52",
            },
        [50002601] = {
            ["Content"] = "开往下一站的列车即将出发，如有购票需求请您在此处办理——什么？没钱？那就少做不切实际的梦！一边儿去！",
            ["ContentJP"] = "まもなく、次の駅に向かう列車が出発いたします。切符はこちらで――なんですって？おカネがない？だったら早く白昼夢から目覚めてくださいませ！お帰りはあちらになります！",
            ["DialogueId"] = 50002601,
            ["Duration"] = 5,
            ["GUID"] = "7D2D0F53",
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Confident_Start",
                },
            },
        [50002701] = {
            ["Content"] = "13号管道已经在修了，我的天，里面老鼠实在是太多了。",
            ["ContentJP"] = "13号パイプの修理中だ。やれやれ、なかはネズミがうじゃうじゃいるぞ。",
            ["DialogueId"] = 50002701,
            ["Duration"] = 4,
            ["GUID"] = "7D2D3022",
            ["SpeakNpcId"] = 700069,
            ["TalkActionId"] = {
                [1] = "700069:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700069/7D2D3022",
            },
        [50002801] = {
            ["Content"] = "滚开！贱种卡戎！",
            ["ContentJP"] = "失せろ！卑しいカロンめ！",
            ["DialogueId"] = 50002801,
            ["DialoguePanelType"] = "{type:Bubble;style:ExcitedBubble}",
            ["Duration"] = 3,
            ["GUID"] = "7D2D408A",
            ["SpeakNpcId"] = 700068,
            ["VoiceName"] = "voice/$Locale$/env/700068/7D2D408A",
            },
        [50002901] = {
            ["Content"] = "诶……怎么都擦不掉啊。",
            ["ContentJP"] = "あぁ……血の跡がどうしても落ちないんだよ。",
            ["DialogueId"] = 50002901,
            ["Duration"] = 3,
            ["GUID"] = "7D2D50F2",
            ["SpeakNpcId"] = 700067,
            ["TalkActionId"] = {
                [1] = "700067:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700067/7D2D50F2",
            },
        [50003001] = {
            ["Content"] = "凶猛的狼咆哮着 撕咬着狡猾的狗",
            ["DialogueId"] = 50003001,
            ["Duration"] = 3,
            ["GUID"] = "7D2D615A",
            ["NextDialogue"] = 50003002,
            ["SpeakNpcId"] = 700071,
            ["TalkActionId"] = {
                [1] = "700071:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700071/7D2D615A",
            },
        [50003002] = {
            ["Content"] = "狡猾的狗呜咽着 啃食着腐朽的肉",
            ["DialogueId"] = 50003002,
            ["Duration"] = 3,
            ["GUID"] = "7D2D6184",
            ["SpeakNpcId"] = 700071,
            ["TalkActionId"] = {
                [1] = "700071:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700071/7D2D6184",
            },
        [50003101] = {
            ["Content"] = "您也喜欢这些百合吗？",
            ["DialogueId"] = 50003101,
            ["Duration"] = 3,
            ["GUID"] = "7D2D71C2",
            ["SpeakNpcId"] = 700072,
            ["TalkActionId"] = {
                [1] = "700072:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700072/7D2D71C2",
            },
        [50003201] = {
            ["Content"] = "城外的怪物吃我们的肉~城内的怪物剪我们的毛~猎犬们吃着白面包~咱们绵羊嚼着地上的草~",
            ["ContentJP"] = "お城の外の怪物は、僕らの肉を食べちゃう～お城のなかの怪物は、僕らの毛をむしっちゃう～\
猟犬はふかふかパンを食ってるけど～哀れな羊の僕たちは、地面の草を食むだけさ～",
            ["DialogueId"] = 50003201,
            ["Duration"] = 3,
            ["GUID"] = "7D2D822A",
            ["NextDialogue"] = 50003202,
            ["SpeakNpcId"] = 700073,
            ["TalkActionId"] = {
                [1] = "700073:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700073/7D2D822A",
            },
        [50003202] = {
            ["Content"] = "该死！你跟谁学的这首歌……早晚你要害死我们俩！",
            ["ContentJP"] = "ちょっ…黙りなさい！誰からそんな歌を教わったのやら……そのうちあんたのせいで私たちふたりとも酷い目にあうだろうよ。",
            ["DialogueId"] = 50003202,
            ["Duration"] = 3,
            ["GUID"] = "7D2D8254",
            ["NextDialogue"] = 50003203,
            ["SpeakNpcId"] = 700074,
            ["TalkActionId"] = {
                [1] = "700074:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700074/7D2D8254",
            },
        [50003203] = {
            ["Content"] = "哦！客人要买点什么？这都是我自己手工做的，质量可是一顶一的好！",
            ["ContentJP"] = "あぁ、何かご入り用ですかいお客さん？すべて私の手作り、最高品質ですよ！",
            ["DialogueId"] = 50003203,
            ["Duration"] = 3,
            ["GUID"] = "7D2D827E",
            ["SpeakNpcId"] = 700074,
            ["TalkActionId"] = {
                [1] = "700074:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700074/7D2D827E",
            },
        [50003301] = {
            ["Content"] = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
            ["DialogueId"] = 50003301,
            ["Duration"] = 3,
            ["GUID"] = "7D2D9292",
            ["SpeakNpcId"] = 700075,
            ["TalkActionId"] = {
                [1] = "700075:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700075/7D2D9292",
            },
        [50003401] = {
            ["Content"] = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
            ["DialogueId"] = 50003401,
            ["Duration"] = 3,
            ["GUID"] = "7D2DA2FA",
            ["SpeakNpcId"] = 700076,
            ["TalkActionId"] = {
                [1] = "700076:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700076/7D2DA2FA",
            },
        [50003501] = {
            ["Content"] = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
            ["DialogueId"] = 50003501,
            ["Duration"] = 3,
            ["GUID"] = "7D2DB362",
            ["SpeakNpcId"] = 700077,
            ["TalkActionId"] = {
                [1] = "700077:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700077/7D2DB362",
            },
        }
  end },
