      return {
        [50003601] = {
            ["Content"] = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
            ["DialogueId"] = 50003601,
            ["Duration"] = 3,
            ["GUID"] = "7D2DC3CA",
