                [1] = "700082:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700082/7D2DF502",
            },
        [50004001] = {
            ["Content"] = "………………（蛋皎在板子上飞速写下了“你好”的文字）",
            ["ContentJP"] = "………………（ルーナエッグはボードに「こんにちは」という文字を素早く書いた）",
            ["DialogueId"] = 50004001,
            ["Duration"] = 3,
            ["GUID"] = "7D2E056A",
            ["SpeakNpcId"] = 900008,
            ["VoiceName"] = "voice/$Locale$/env/900008/7D2E056A",
            },
        [50004101] = {
            ["Content"] = "我最近又接了个委托，老规矩，你八我二。等我喝完这瓶就出发，怎么样？",
            ["ContentJP"] = "新しい依頼をまた受けたんだが、一緒にどうだ？取り分はお前らが8割、俺が2割のいつも通りでさ。こいつを一杯飲んだら出発するつもりだ。",
            ["DialogueId"] = 50004101,
            ["Duration"] = 3,
            ["GUID"] = "7D2E15D2",
            ["SpeakNpcId"] = 200015,
            ["TalkActionId"] = {
                [1] = "200015:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/200015/7D2E15D2",
            },
        [50004201] = {
            ["Content"] = "要来一杯吗？",
            ["ContentJP"] = "一杯どうかしら？",
            ["DialogueId"] = 50004201,
            ["Duration"] = 3,
            ["GUID"] = "7D2E263A",
            ["SpeakNpcId"] = 200003,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_npc_01",
            },
        [50004301] = {
            ["Content"] = "断翅的夜莺，不要继续哭泣……",
            ["ContentJP"] = "♪翼折れたナイチンゲール……",
            ["DialogueId"] = 50004301,
            ["Duration"] = 3,
            ["GUID"] = "7D2E36A2",
            ["NextDialogue"] = 50004302,
            ["SpeakNpcId"] = 700142,
            ["TalkActionId"] = {
                [1] = "700142:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/200020/7D2E36A2",
            },
        [50004302] = {
            ["Content"] = "亲爱的夜莺，不要就此睡去……",
            ["ContentJP"] = "♪ナイチンゲールよ、もう泣かないで……",
            ["DialogueId"] = 50004302,
            ["Duration"] = 3,
            ["GUID"] = "7D2E36CC",
            ["SpeakNpcId"] = 700142,
            ["TalkActionId"] = {
                [1] = "700142:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/env/200020/7D2E36CC",
            },
        [50004401] = {
            ["Content"] = "走，走开……不买月石的话就赶紧走……别把那群当兵的引来了……",
            ["ContentJP"] = "じゃ、邪魔だ……月ノ石を買わないなら、どっかに行けってんだ……頼む、兵士たちの目を引かないでくれ……",
            ["DialogueId"] = 50004401,
            ["Duration"] = 4,
            ["GUID"] = "7D2E470A",
            ["SpeakNpcId"] = 700113,
            ["TalkActionId"] = {
                [1] = "700113:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700113/7D2E470A",
            },
        [50004501] = {
            ["Content"] = "跳舞吧！来跳舞！活着有什么意义？让我们把所有复杂的问题丢进垃圾桶，共舞直到明天！",
            ["ContentJP"] = "さあ踊ろう！生きる意味？そんなのどうでもいいじゃないか。面倒なことはゴミ箱にポイして、みんなで踊ろう、明日まで！",
            ["DialogueId"] = 50004501,
            ["Duration"] = 3,
            ["GUID"] = "7D2E5772",
            ["SpeakNpcId"] = 700129,
            ["VoiceName"] = "voice/$Locale$/env/700129/7D2E5772",
            },
        [50004601] = {
            ["Content"] = "老爷，这个月的帝国抚恤……啊，还没批下来啊，咳咳咳……没事，我先拿自己的钱垫一垫……给你们添麻烦了哈……",
            ["ContentJP"] = "旦那様、今月分の帝国からの手当は……ああ、まだ承認されていないのですね……、ゲホッ、ゲホ、ゴホッ……いいのです、自分の蓄えでしのいでおきますゆえ……お手数をおかけして申し訳ない……",
            ["DialogueId"] = 50004601,
            ["Duration"] = 4,
            ["GUID"] = "7D2E67DA",
            ["SpeakNpcId"] = 700070,
            ["TalkActionId"] = {
                [1] = "700070:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700070/7D2E67DA",
            },
        [50004701] = {
            ["Content"] = "宝藏情报，不可错过……",
            ["ContentJP"] = "さあさあ、お宝の情報を聞き逃しちゃもったいないぞ……",
            ["DialogueId"] = 50004701,
            ["Duration"] = 3,
            ["GUID"] = "7D2E7842",
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700048/7D2E7842",
            },
        [50004801] = {
            ["Content"] = "渔夫协会，了解一下！",
            ["ContentJP"] = "漁師互助会に興味はないかね？",
            ["DialogueId"] = 50004801,
            ["Duration"] = 3,
            ["GUID"] = "7D2E88AA",
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700048/7D2E88AA",
            },
        [50004901] = {
            ["Content"] = "只要消毒得当，就能成为一盘好菜！",
            ["ContentJP"] = "キチンと消毒さえすれば、ハラショーな料理に仕上がることでしょう！",
            ["DialogueId"] = 50004901,
            ["Duration"] = 3,
            ["GUID"] = "7D2E9912",
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700116/7D2E9912",
            },
        [50005001] = {
            ["Content"] = "啧，生面孔啊。",
            ["ContentJP"] = "チッ、知らねぇ顔だな。",
            ["DialogueId"] = 50005001,
            ["Duration"] = 3,
            ["GUID"] = "7D2EA97A",
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700096/7D2EA97A",
            },
        [50005101] = {
            ["Content"] = "要点什么。",
            ["ContentJP"] = "またブツが欲しいのか？",
            ["DialogueId"] = 50005101,
            ["Duration"] = 3,
            ["GUID"] = "7D2EB9E2",
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700096/7D2EB9E2",
            },
        [50005201] = {
            ["Content"] = "忠于欲望，忠于欲望，忠于欲望，哎，到底怎么才算忠于欲望啊……",
            ["ContentJP"] = "欲望のままに、欲望のままに、欲望のままに……ああ、欲望に忠実とは、一体何をすればいいのでしょうか……",
            ["DialogueId"] = 50005201,
            ["Duration"] = 4,
            ["GUID"] = "7D2ECA4A",
            ["SpeakNpcId"] = 700077,
            ["TalkActionId"] = {
                [1] = "700077:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/env/700077/7D2ECA4A",
            },
        [50005301] = {
            ["Content"] = "开往下一站的列车即将出发，如有购票需求请您在此处办理——什么？没钱？那就一边儿去！",
            ["ContentJP"] = "まもなく、次の駅に向かう列車が出発いたします。切符の購入はこちらで――\
\
なんですって？お金がない？だったら早く白昼夢から目覚めてくださいませ！お帰りはあちらになります！",
            ["DialogueId"] = 50005301,
            ["Duration"] = 4,
            ["GUID"] = "7D2D1FBA",
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/env/700021/7D2D1FBA",
            },
        [50005401] = {
            ["Content"] = "哈哈哈，她跑得好快啊，比老鼠还快！",
            ["ContentJP"] = "アッハハハ、見たかよ、あいつの逃げ足。ドブネズミかっつうの！",
            ["DialogueId"] = 50005401,
            ["Duration"] = 3,
            ["GUID"] = "7D2EEB1A",
            ["SpeakNpcId"] = 700089,
            },
        [50005501] = {
            ["Content"] = "臭卡戎，还愣着干什么呀，快去追你家小崽子吧！",
            ["ContentJP"] = "なにボケっとしてんだよ。臭っせえカロンはさっさと仲間を追っかけろよ！",
            ["DialogueId"] = 50005501,
            ["Duration"] = 3,
            ["GUID"] = "7D2EFB82",
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            },
        [50005601] = {
            ["Content"] = "要不要换一个大一点的看板啊……",
            ["ContentJP"] = "もっと大きな看板に交換しようかな……",
            ["DialogueId"] = 50005601,
            ["Duration"] = 3,
            ["GUID"] = "7D2F0BEA",
            ["SpeakNpcId"] = 700143,
            },
        [50100101] = {
            ["Content"] = "针头线脑，香脂香囊，走过路过不要错过——",
            ["ContentJP"] = "針と糸、香油と香り袋――通りすがりのお客さん、お見逃しなく～！",
            ["DialogueId"] = 50100101,
            ["GUID"] = "7D6B9BD2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6B9BD2",
            },
        [50100201] = {
            ["Content"] = "来看看华胥特色纪念品喽，给亲朋好友带一份吧！",
            ["ContentJP"] = "さあさあ、華胥の特産お土産はいかが？家族や友達への贈り物にぴったり！",
            ["DialogueId"] = 50100201,
            ["GUID"] = "7D6BAC3A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BAC3A",
            },
        [50100301] = {
            ["Content"] = "海的那边……是什么样子呢？",
            ["ContentJP"] = "海の向こうには……どんな景色があるんだろうな？",
            ["DialogueId"] = 50100301,
            ["GUID"] = "7D6BBCA2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BBCA2",
            },
        [50100311] = {
            ["Content"] = "工头昨天心情好，给我们都发了赏钱！",
            ["ContentJP"] = "昨日、親方が機嫌よくてさ、みんなにボーナスをくれたんだぜ！",
            ["DialogueId"] = 50100311,
            ["GUID"] = "7D6BBE46",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BBE46",
            },
        [50100312] = {
            ["Content"] = "那有什么！出船之前，老板来请吃了茶呢！",
            ["ContentJP"] = "それどころか、出航前に旦那が茶をごちそうしてくれたんだ！",
            ["DialogueId"] = 50100312,
            ["GUID"] = "7D6BBE70",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BBE70",
            },
        [50100401] = {
            ["Content"] = "腰酸背痛啊，抽空得找人好好按按……",
            ["ContentJP"] = "腰も背中も痛ぇ……暇ができたらマッサージしてもらわねぇと。",
            ["DialogueId"] = 50100401,
            ["GUID"] = "7D6BCD0A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BCD0A",
            },
        [50100501] = {
            ["Content"] = "这箱货物贵重，先包上一层软垫再搬吧。",
            ["ContentJP"] = "この箱は高価な品だ、先に柔らかい布で包んでから運ぼう。",
            ["DialogueId"] = 50100501,
            ["GUID"] = "7D6BDD72",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BDD72",
            },
        [50100601] = {
            ["Content"] = "这些木簪花钿，好看是好看，可我不会用呢。",
            ["ContentJP"] = "この木のかんざしや花飾り、きれいだけど……使い方がわからないですね。",
            ["DialogueId"] = 50100601,
            ["GUID"] = "7D6BEDDA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BEDDA",
            },
        [50100701] = {
            ["Content"] = "香料丝绸茶叶油膏器皿……种类也太多了！",
            ["ContentJP"] = "香料に絹、茶葉に軟膏に器……種類が多すぎる！",
            ["DialogueId"] = 50100701,
            ["GUID"] = "7D6BFE42",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6BFE42",
            },
        [50100801] = {
            ["Content"] = "沉月香卖完了？怎么可能，昨天才进的货！",
            ["ContentJP"] = "沈月香がもう売り切れ？まさか、昨日入荷したばっかじゃないの！",
            ["DialogueId"] = 50100801,
            ["GUID"] = "7D6C0EAA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C0EAA",
            },
        [50100901] = {
            ["Content"] = "点数清，码数齐，今日开市不慌矣~",
            ["ContentJP"] = "数も合ってるし、準備万端。今日の市は慌てずに始められるぞ～。",
            ["DialogueId"] = 50100901,
            ["GUID"] = "7D6C1F12",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C1F12",
            },
        [50101001] = {
            ["Content"] = "不愧是织星客的故乡，华胥果真名不虚传。",
            ["ContentJP"] = "さすが星織人の故郷、華胥は名に恥じない立派なところだな。",
            ["DialogueId"] = 50101001,
            ["GUID"] = "7D6C2F7A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C2F7A",
            },
        [50101101] = {
            ["Content"] = "山清水秀，在此品一盏香茗，妙趣横生呐~",
            ["ContentJP"] = "山は清らか、水は美しい。ここで香り高い茶を一杯……最高の贅沢だなぁ。",
            ["DialogueId"] = 50101101,
            ["GUID"] = "7D6C3FE2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C3FE2",
            },
        [50101201] = {
            ["Content"] = "说好打赌输了就欠我三根糖葫芦，你不许耍赖。",
            ["ContentJP"] = "勝負に負けたら飴串三本の約束だろ、ズルすんなよ！",
            ["DialogueId"] = 50101201,
            ["GUID"] = "7D6C504A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C504A",
            },
        [50101202] = {
            ["Content"] = "放心，明日阿娘给了零花钱就来请你！",
            ["ContentJP"] = "分かってるって。明日お袋が小遣いくれたら、ちゃんとおごってやるさ！",
            ["DialogueId"] = 50101202,
            ["GUID"] = "7D6C5074",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C5074",
            },
        [50101203] = {
            ["Content"] = "浮星埠是一年比一年热闹了啊……",
            ["ContentJP"] = "浮星埠も年々にぎやかになってきたなあ……",
            ["DialogueId"] = 50101203,
            ["GUID"] = "7D6C509E",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C509E",
            },
        [50101301] = {
            ["Content"] = "诶呀！撞得我发髻都散啦！",
            ["ContentJP"] = "あいたっ！髷がほどけちまった！",
            ["DialogueId"] = 50101301,
            ["GUID"] = "7D6C60B2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C60B2",
            },
        [50101401] = {
            ["Content"] = "嘿！小友走路别分心，撞到人可不好！",
            ["ContentJP"] = "おっと！お嬢さん、前をよく見て歩かないと危ないぞ！",
            ["DialogueId"] = 50101401,
            ["GUID"] = "7D6C711A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C711A",
            },
        [50101501] = {
            ["Content"] = "绸缎齐整，杂粮归铺，心才安……",
            ["ContentJP"] = "絹物を整え、穀物を並べ、心がようやく落ち着く……",
            ["DialogueId"] = 50101501,
            ["GUID"] = "7D6C8182",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C8182",
            },
        [50101601] = {
            ["Content"] = "祖传山参，百年阿胶，价优物美待君选！",
            ["ContentJP"] = "代々伝わる山参、百年物の阿膠、どれも安くていいものだぞ～！",
            ["DialogueId"] = 50101601,
            ["GUID"] = "7D6C91EA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6C91EA",
            },
        [50101701] = {
            ["Content"] = "好东西不贱卖哈，总有眼尖识货人！",
            ["ContentJP"] = "いい品は安くしねえけど、見る目のある人なら分かるはずさ！",
            ["DialogueId"] = 50101701,
            ["GUID"] = "7D6CA252",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CA252",
            },
        [50101801] = {
            ["Content"] = "瓷器娇贵，客人轻拿轻放~",
            ["ContentJP"] = "陶器は割れやすいから、手に取るときは優しくね～。",
            ["DialogueId"] = 50101801,
            ["GUID"] = "7D6CB2BA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CB2BA",
            },
        [50101901] = {
            ["Content"] = "再便宜点，我直接拿了。",
            ["ContentJP"] = "もう少し安くしてくれたら、すぐ買うんだけどな。",
            ["DialogueId"] = 50101901,
            ["GUID"] = "7D6CC322",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CC322",
            },
        [50102001] = {
            ["Content"] = "瓶子看着精致……没什么瑕疵吧？",
            ["ContentJP"] = "この瓶、見た目もきれいだし……傷もなさそうだな？",
            ["DialogueId"] = 50102001,
            ["GUID"] = "7D6CD38A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CD38A",
            },
        [50102101] = {
            ["Content"] = "称点桂花糕，我带回去给娘子吃~",
            ["ContentJP"] = "  <Default note=\"text:グイホアガオ\">桂花菓子</>を少し量ってくれ。嫁に持って帰ってやるんだ。",
            ["DialogueId"] = 50102101,
            ["GUID"] = "7D6CE3F2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CE3F2",
            },
        [50102201] = {
            ["Content"] = "这匹布料柔软顺滑，做成里衣定是舒适。",
            ["ContentJP"] = "この布、柔らかくてなめらかだな。肌着にしたら気持ちよさそうだ。",
            ["DialogueId"] = 50102201,
            ["GUID"] = "7D6CF45A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6CF45A",
            },
        [50102301] = {
            ["Content"] = "神君鉴上，我雪霁立誓一生不负初晴，如……",
            ["ContentJP"] = "神君に誓って、私・セッセは一生、ウイを裏切らないと……",
            ["DialogueId"] = 50102301,
            ["GUID"] = "7D6D04C2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D04C2",
            },
        [50102401] = {
            ["Content"] = "嘘！后面的话不许你说！我都明白……",
            ["ContentJP"] = "しっ！ それ以上言っちゃだめ！……分かってるから。",
            ["DialogueId"] = 50102401,
            ["GUID"] = "7D6D152A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D152A",
            },
        [50102501] = {
            ["Content"] = "白龙神君保佑此次出航平安无虞！",
            ["ContentJP"] = "白龍様よ、どうか今回の航海が無事でありますように！",
            ["DialogueId"] = 50102501,
            ["GUID"] = "7D6D2592",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D2592",
            },
        [50102601] = {
            ["Content"] = "小女愿家中长辈身体康健，福寿绵长。",
            ["ContentJP"] = "せつは願います――家族が健やかで、長く幸せに暮らせますように。",
            ["DialogueId"] = 50102601,
            ["GUID"] = "7D6D35FA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D35FA",
            },
        [50102701] = {
            ["Content"] = "明先生最近可是在哪发了大财？",
            ["ContentJP"] = "明さん、最近ずいぶん儲けてるって噂じゃないですか？",
            ["DialogueId"] = 50102701,
            ["GUID"] = "7D6D4662",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D4662",
            },
        [50102702] = {
            ["Content"] = "侥幸而已！还是江先生的生意更稳当。",
            ["ContentJP"] = "まぐれですよ！エーさんの商売の方がよっぽど堅実です。",
            ["DialogueId"] = 50102702,
            ["GUID"] = "7D6D468C",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D468C",
            },
        [50102801] = {
            ["Content"] = "下次出航得往赫墨北边再走一走……",
            ["ContentJP"] = "次の航海はケメトの北側まで行ってみようかな……",
            ["DialogueId"] = 50102801,
            ["GUID"] = "7D6D56CA",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D56CA",
            },
        [50102901] = {
            ["Content"] = "明明已经让了极大的利，为何销量还是……",
            ["ContentJP"] = "あれだけ値を下げたのに、なんで売れ行きが……",
            ["DialogueId"] = 50102901,
            ["GUID"] = "7D6D6732",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D6732",
            },
        [50103001] = {
            ["Content"] = "我才加入织星客，凡事劳请前辈多指点！",
            ["ContentJP"] = "俺、星織人になったばかりなんです。色々教えてください、よろしくお願いします！",
            ["DialogueId"] = 50103001,
            ["GUID"] = "7D6D779A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D779A",
            },
        [50103002] = {
            ["Content"] = "客气了，若有问题便尽管问吧。",
            ["ContentJP"] = "気にするな、困ったら何でも聞け。",
            ["DialogueId"] = 50103002,
            ["GUID"] = "7D6D77C4",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D77C4",
            },
        [50103003] = {
            ["Content"] = "您说我是要继续追资还是见好就收呢？",
            ["ContentJP"] = "これ以上投資を続けた方がいいですか、それとも引くべきですか？",
            ["DialogueId"] = 50103003,
            ["GUID"] = "7D6D77EE",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D77EE",
            },
        [50103101] = {
            ["Content"] = "新来的哥儿，皮子肥不肥？",
            ["ContentJP"] = "おい、新入り！金は持ってるのか？",
            ["DialogueId"] = 50103101,
            ["GUID"] = "7D6D8802",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D8802",
            },
        [50103201] = {
            ["Content"] = "穷地方来的，没挂多少老居米子。",
            ["ContentJP"] = "田舎もんだ、あまり貯えはねぇよ。",
            ["DialogueId"] = 50103201,
            ["GUID"] = "7D6D986A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6D986A",
            },
        [50103301] = {
            ["Content"] = "客人来看看？爬山头来的正经古董。",
            ["ContentJP"] = "お客さん、見てってくれ！山越えて手に入れた正真正銘の骨董品だ。",
            ["DialogueId"] = 50103301,
            ["GUID"] = "7D6DA8D2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DA8D2",
            },
        [50103401] = {
            ["Content"] = "以前都只做洋庄，好不容易才运回国的！",
            ["ContentJP"] = "前は洋館専門だったんだが、やっと国に持ち帰れたんだぜ！",
            ["DialogueId"] = 50103401,
            ["GUID"] = "7D6DB93A",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DB93A",
            },
        [50103501] = {
            ["Content"] = "风里有太皓的意志，只需静下心感受……",
            ["ContentJP"] = "風の中に、太皓の意志がある。心を静めて感じてみろ――",
            ["DialogueId"] = 50103501,
            ["GUID"] = "7D6DC9A2",
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DC9A2",
            },
        [50103601] = {
            ["Content"] = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
            ["ContentJP"] = "氷台五十斤に、春一品三十斤っと……おいおい、これらの香料はどれも珍しい品だ。運ぶときは気をつけてくれよ！",
            ["DialogueId"] = 50103601,
            ["GUID"] = "7D6DDA0A",
            ["SpeakNpcId"] = 701039,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DDA0A",
            },
        [50103701] = {
            ["Content"] = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
            ["ContentJP"] = "うちは異国のお客様に大人気の土産屋です！華胥を旅するなら、一度は立ち寄るべき名所！香り袋に扇子、古美術に珍宝まで――お探しの品が、きっと見つかりますよ！",
            ["DialogueId"] = 50103701,
            ["GUID"] = "7D6DEA72",
            ["SpeakNpcId"] = 701040,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DEA72",
            },
        [50103801] = {
            ["Content"] = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
            ["ContentJP"] = "ちょいと待たれよ、旅人さん。ここ浮星埠は千年の歴史を誇る。商いをする上で、過去を知るのは何よりも大切じゃ。",
            ["DialogueId"] = 50103801,
            ["GUID"] = "7D6DFADA",
            ["SpeakNpcId"] = 701041,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6DFADA",
            },
        [50103901] = {
            ["Content"] = "您可听好了，这大风九章的第一章就是：戕身害命，不可为也。",
            ["ContentJP"] = "いいですか。『大風九章』の第一章にはこうあります――「身を戕い、命を奪うこと、為すべからず」と。",
            ["DialogueId"] = 50103901,
            ["GUID"] = "7D6E0B42",
            ["SpeakNpcId"] = 701044,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E0B42",
            },
        [50104001] = {
            ["Content"] = "怎么样才能长出角呢，我揪……我揪……嗷！好痛……",
            ["ContentJP"] = "どうしたら角って生えてくるの？……うぅ、思いきって引っぱれば……いった〜っ！",
            ["DialogueId"] = 50104001,
            ["GUID"] = "7D6E1BAA",
            ["SpeakNpcId"] = 701045,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E1BAA",
            },
        [50104101] = {
            ["Content"] = "没想到成为织星客还有如此多的便利！百年春真是家大业大啊。",
            ["ContentJP"] = "まさか星織人になると、こんなに融通が利くとはね！百年春って、ほんとスケールが違うよ！",
            ["DialogueId"] = 50104101,
            ["GUID"] = "7D6E2C12",
            ["SpeakNpcId"] = 701046,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E2C12",
            },
        [50104201] = {
            ["Content"] = "盖个会客厅怎么样？要不再加个小厨房？",
            ["ContentJP"] = "応接室でも増築しない？ついでに小さなキッチンもつけてさ。",
            ["DialogueId"] = 50104201,
            ["GUID"] = "7D6E3C7A",
            ["SpeakNpcId"] = 701048,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E3C7A",
            },
        [50104301] = {
            ["Content"] = "爬到月亮上？咱们爬得上去吗？",
            ["ContentJP"] = "月に……？でも、登れるのかな？",
            ["DialogueId"] = 50104301,
            ["GUID"] = "7D6E4CE2",
            ["SpeakNpcId"] = 701050,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E4CE2",
            },
        [50104401] = {
            ["Content"] = "嚯，这块千星板的年岁可真够久了！",
            ["ContentJP"] = "ほら見てよ、この千星板、ほんとに年季入ってるな！",
            ["DialogueId"] = 50104401,
            ["GUID"] = "7D6E5D4A",
            ["SpeakNpcId"] = 701051,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E5D4A",
            },
        [50104501] = {
            ["Content"] = "不以利丰为荣，以义为荣；不以豪奢为高，以德为高……",
            ["ContentJP"] = "利を誇らず、義を尊び……贅を誇らず、徳を尊ぶ……",
            ["DialogueId"] = 50104501,
            ["GUID"] = "7D6E6DB2",
            ["SpeakNpcId"] = 701052,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E6DB2",
            },
        [50104601] = {
            ["Content"] = "如若对百年春业务相关有所疑问，可至此处问询。",
            ["ContentJP"] = "百年春の業務についてご不明な点がありましたら、どうぞこちらでお尋ねくださいませ。",
            ["DialogueId"] = 50104601,
            ["GUID"] = "7D6E7E1A",
            ["SpeakNpcId"] = 701054,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E7E1A",
            },
        [50104701] = {
            ["Content"] = "昨天到港的北风莓酱，怎么现在还没通过检查！快把货给我！",
            ["ContentJP"] = "昨日港に着いたアイスベリージャム、どうしてまだ検査が終わってないんだ！？早く荷物を渡してくれ！",
            ["DialogueId"] = 50104701,
            ["GUID"] = "7D6E8E82",
            ["SpeakNpcId"] = 701057,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E8E82",
            },
        [50104801] = {
            ["Content"] = "回家……可是，我的家又在哪里？这里……又是什么地方？",
            ["ContentJP"] = "帰ろう……でも、私の家はいったいどこ？ここは……どこ？",
            ["DialogueId"] = 50104801,
            ["GUID"] = "7D6E9EEA",
            ["SpeakNpcId"] = 701059,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6E9EEA",
            },
        [50104901] = {
            ["Content"] = "敕愿亡魂，早离迷茫，急急如律，往生乐乡……",
            ["ContentJP"] = "悪霊退散、急々如律令。亡魂よ、迷いを捨て早く離れよ。律に従い、速やかに極楽へ往け……",
            ["DialogueId"] = 50104901,
            ["GUID"] = "7D6EAF52",
            ["SpeakNpcId"] = 701060,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EAF52",
            },
        [50105001] = {
            ["Content"] = "如果爷爷回来看我的话，就让叶子落在我的头上吧！",
            ["ContentJP"] = "もしおじいちゃんが私のところに戻ってきてくれるなら、葉っぱを私の頭の上に落としてね！",
            ["DialogueId"] = 50105001,
            ["GUID"] = "7D6EBFBA",
            ["SpeakNpcId"] = 701061,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EBFBA",
            },
        [50105101] = {
            ["Content"] = "这棵树，一直在说话！",
            ["ContentJP"] = "この木が——ずっと話してるんだ！",
            ["DialogueId"] = 50105101,
            ["GUID"] = "7D6ED022",
            ["SpeakNpcId"] = 701063,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6ED022",
            },
        [50105201] = {
            ["Content"] = "你也是从外面过来的？",
            ["ContentJP"] = "あなたも外の世界から来たの？",
            ["DialogueId"] = 50105201,
            ["GUID"] = "7D6EE08A",
            ["SpeakNpcId"] = 701065,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EE08A",
            },
        [50105301] = {
            ["Content"] = "小鬼，微茫市可不是你随便乱逛的地方。",
            ["ContentJP"] = "小僧、微芒市はお前のようなものが勝手にうろつける場所じゃないぞ。",
            ["DialogueId"] = 50105301,
            ["GUID"] = "7D6EF0F2",
            ["SpeakNpcId"] = 701066,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6EF0F2",
            },
        [50105401] = {
            ["Content"] = "这缝儿得趁早补，再泡些日子，木芯都得烂透咯。",
            ["ContentJP"] = "この割れ目は早めに直しておかないとな。もう少し水に浸かってたら、木の芯まで腐っちまうよ。",
            ["DialogueId"] = 50105401,
            ["GUID"] = "7D6F015A",
            ["SpeakNpcId"] = 701067,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F015A",
            },
        [50105501] = {
            ["Content"] = "呼……呼……",
            ["ContentJP"] = "はぁ……はぁ……",
            ["DialogueId"] = 50105501,
            ["GUID"] = "7D6F11C2",
            ["SpeakNpcId"] = 701071,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F11C2",
            },
        [50105601] = {
            ["Content"] = "一会冷一会热……想当年我太姥姥还跟我说，这里是个春暖花开的好地方呢！",
            ["ContentJP"] = "寒かったり暑かったり……思えば昔、私のひいおばあちゃんが言ってたのよ。ここは春に花が咲き誇る、とてもいい場所だったって！",
            ["DialogueId"] = 50105601,
            ["GUID"] = "7D6F222A",
            ["SpeakNpcId"] = 701072,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F222A",
            },
        [50105701] = {
            ["Content"] = "就在这里点香，白龙神君一定会像神话里那样挺身而出，将那恶兽赶尽杀绝！",
            ["ContentJP"] = "ここで香を焚けば、白龍様がきっと神話みたいに現れて、あの悪獣をぶっ飛ばしてくれるはずだ！",
            ["DialogueId"] = 50105701,
            ["GUID"] = "7D6F3292",
            ["SpeakNpcId"] = 701073,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F3292",
            },
        [50105801] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentJP"] = "千星板、異常なしっと。そろそろメンテナンスの時期かしらね……",
            ["DialogueId"] = 50105801,
            ["GUID"] = "7D6F42FA",
            ["SpeakNpcId"] = 701042,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F42FA",
            },
        [50105901] = {
            ["Content"] = "龙老板，好久不见，新到的银针要尝尝吗，香的嘞~",
            ["ContentJP"] = "おやおや、龍さんじゃないか。ご無沙汰だねぇ。ちょうど新しい茶が入ったところなんだ、香りが抜群で……一杯どうだい？",
            ["DialogueId"] = 50105901,
            ["GUID"] = "7D6F5362",
            ["SpeakNpcId"] = 701055,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F5362",
            },
        [50106001] = {
            ["Content"] = "到底是什么时候就在这里的呢？",
            ["ContentJP"] = "いったいいつから、ここにこの木はあるんだろう？",
            ["DialogueId"] = 50106001,
            ["GUID"] = "7D6F63CA",
            ["SpeakNpcId"] = 701062,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F63CA",
            },
        [50106101] = {
            ["Content"] = "最近微茫市来了些新面孔，买卖时闲话许多，上不得台面。",
            ["ContentJP"] = "最近、微茫市には新しい顔ぶれが増えたな。商売のときに余計な話ばっかして、まったく品がない。",
            ["DialogueId"] = 50106101,
            ["GUID"] = "7D6F7432",
            ["SpeakNpcId"] = 701068,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F7432",
            },
        [50106201] = {
            ["Content"] = "下次和虬先生约见之时，定要选个风雅茶楼，而不是这种……",
            ["ContentJP"] = "次にキョウンと会うときは、もっと優雅な茶楼を選ばなきゃな。こんな場所じゃあ……。",
            ["DialogueId"] = 50106201,
            ["GUID"] = "7D6F849A",
            ["SpeakNpcId"] = 701070,
            ["VoiceName"] = "voice/$Locale$/env/Ver0101/7D6F849A",
            },
        [50106301] = {
            ["Content"] = "福运蛋上新款式啦，要不要来扭一发试试？",
            ["ContentJP"] = "ラッキーエッグに新しいラインナップが入ったよ、1回ガチャってみない？",
            ["DialogueId"] = 50106301,
            ["Duration"] = 5,
            ["GUID"] = "7D6F9502",
            ["SpeakNpcId"] = 900012,
            },
        [50107001] = {
            ["Content"] = "我的钱袋子呢？我的钱袋子怎么不见了？",
            ["ContentJP"] = "えっ、嘘でしょ！私の財布、どこ行っちゃったの？なんでどこにもいないのよ。",
            ["DialogueId"] = 50107001,
            ["GUID"] = "7D7007DA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028AA",
            },
        [50107002] = {
            ["Content"] = "定是那油嘴滑舌的小贩子偷的！",
            ["ContentJP"] = "あの怪しそうな行商人が盗んだに違いない！",
            ["DialogueId"] = 50107002,
            ["GUID"] = "7D700804",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028D4",
            },
        [50107003] = {
            ["Content"] = "诶？怎么就是找不到呢？",
            ["ContentJP"] = "え？どうして見つからないんだろう？",
            ["DialogueId"] = 50107003,
            ["GUID"] = "7D70082E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028FE",
            },
        [50107004] = {
            ["Content"] = "我早跟你说了这街上有贼，之前有人看到了，一个小女孩，皮肤黑黢黢的！",
            ["ContentJP"] = "だから言ったんだ、この街には泥棒がいるって！前に誰かが泥棒を見たんだ、黒い肌の小さな女泥棒が！",
            ["DialogueId"] = 50107004,
            ["GUID"] = "7D700858",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702928",
            },
        [50107005] = {
            ["Content"] = "博山香行周年店庆，来店订购香料满十赠五~",
            ["ContentJP"] = "博山香行はただいま周年記念セールを開催中です！今だけお得ですよ！",
            ["DialogueId"] = 50107005,
            ["GUID"] = "7D700882",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702952",
            },
        [50107006] = {
            ["Content"] = "你要知道一点——我对香料品质的要求很高，晒得太干我不要，香味散得太过我也不要。",
            ["ContentJP"] = "ひとつだけ知っておいてほしい、私は香料の品質にとてもこだわっている。乾きすぎているものは嫌だし、香りが飛びすぎているものも嫌だ。",
            ["DialogueId"] = 50107006,
            ["GUID"] = "7D7008AC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70297C",
            },
        [50107007] = {
            ["Content"] = "之前定的那批香料，品质相当不错，这次就按原先的订单再来一批，还是送到我家中。",
            ["ContentJP"] = "以前注文したあの香料は品質がとても良かったわ。今回も前回と同じ注文でお願いするわ。やっぱり私の家まで届けてちょうだい。",
            ["DialogueId"] = 50107007,
            ["GUID"] = "7D7008D6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029A6",
            },
        [50107008] = {
            ["Content"] = "噫！好酸的果干！",
            ["ContentJP"] = "うっ、このドライフルーツ、酸っぱい！",
            ["DialogueId"] = 50107008,
            ["GUID"] = "7D700900",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029D0",
            },
        [50107009] = {
            ["Content"] = "为什么没人来试试我做的糕点呢……难道是卖相不太好？可是味道很香呀……",
            ["ContentJP"] = "どうして誰も私のお菓子を食べに来ないんだろう......見た目が悪いから？でも、味は美味しいのに。",
            ["DialogueId"] = 50107009,
            ["GUID"] = "7D70092A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029FA",
            },
        [50107010] = {
            ["Content"] = "华胥特色小吃，吃一口念一年！",
            ["ContentJP"] = "華胥の名物ですよ、一口食べれば、一年恋しくなる！",
            ["DialogueId"] = 50107010,
            ["GUID"] = "7D700954",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A24",
            },
        [50107011] = {
            ["Content"] = "各色果干，酸甜可口，欢迎试吃品尝~",
            ["ContentJP"] = "ドライフルーツですよ、甘酸っぱくておいしいから、よかったら味見してみてください～",
            ["DialogueId"] = 50107011,
            ["GUID"] = "7D70097E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A4E",
            },
        [50107012] = {
            ["Content"] = "那里曾是家布鞋店，现在却已经改成了木雕摊……东市啊，大变样咯！",
            ["ContentJP"] = "あそこはねぇ、昔は靴屋さんだったのよ。それが今じゃ木彫りの露店になっちゃって……東市も本当に、ずいぶん変わったわねぇ。",
            ["DialogueId"] = 50107012,
            ["GUID"] = "7D7009A8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A78",
            },
        [50107013] = {
            ["Content"] = "这位客人，看你身材匀称，要不要来试试我们千绣阁里的成衣？",
            ["ContentJP"] = "お客さん、スタイルめっちゃ良いですよ。よかったら千繍閣でご試着してみてくださいね。",
            ["DialogueId"] = 50107013,
            ["GUID"] = "7D7009D2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AA2",
            },
        [50107014] = {
            ["Content"] = "同福饭馆菜品上新，外域高人指点，香料入菜，佳肴更添新风味。",
            ["ContentJP"] = "同福飯店の新メニューが登場！海外の有名料理人が監修！香料を加えた料理は、新しい風味が味わえますぞ。",
            ["DialogueId"] = 50107014,
            ["GUID"] = "7D7009FC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702ACC",
            },
        [50107015] = {
            ["Content"] = "香料做菜？听起来奇奇怪怪的，这做出来的东西能好吃吗？",
            ["ContentJP"] = "香料の料理？ちょっと変わった感じだねぇ……でも、これで作ったものって、美味しいのかな？",
            ["DialogueId"] = 50107015,
            ["GUID"] = "7D700A26",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AF6",
            },
        [50107016] = {
            ["Content"] = "同福饭馆的厨子发了疯，居然把莞婆娘碾碎包进丸子里！",
            ["ContentJP"] = "同福飯店のシェフ、ちょっとやりすぎじゃあない？なんでフトイを潰して団子の中に入れちゃってのよ。",
            ["DialogueId"] = 50107016,
            ["GUID"] = "7D700A50",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B20",
            },
        [50107017] = {
            ["Content"] = "一天到晚就知道折腾看似新颖实则无用的花招，可别忘了华胥美食的精髓是什么！",
            ["ContentJP"] = "見た目は新しいだけで実のない手法ばかり弄ってるんじゃない。華胥料理の真髄を忘れるとは！",
            ["DialogueId"] = 50107017,
            ["GUID"] = "7D700A7A",
            ["SpeakNpcId"] = 701266,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B4A",
            },
        [50107018] = {
            ["Content"] = "秀芳……不要离开我……秀芳……",
            ["ContentJP"] = "……行かないでくれ……カオ……",
            ["DialogueId"] = 50107018,
            ["GUID"] = "7D700AA4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B74",
            },
        [50107019] = {
            ["Content"] = "把翠屏雀搬来了皓京城？！还有此等奇事！",
            ["ContentJP"] = "スイヘイジャクをわざわざ皓京まで連れてきたのか？！驚いたぞ！",
            ["DialogueId"] = 50107019,
            ["GUID"] = "7D700ACE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B9E",
            },
        [50107020] = {
            ["Content"] = "雀翎茗轩……是在这里吗？",
            ["ContentJP"] = "雀の茶屋って……ここかしら？",
            ["DialogueId"] = 50107020,
            ["GUID"] = "7D700AF8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BC8",
            },
        [50107021] = {
            ["Content"] = "东市雀翎茗轩开张，凡携亲眷者入座，皆送花茶一壶。",
            ["ContentJP"] = "雀の茶屋・東市店、開店でーす！ご来店の皆さまに花茶をサービスいたします。",
            ["DialogueId"] = 50107021,
            ["GUID"] = "7D700B22",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BF2",
            },
        [50107022] = {
            ["Content"] = "呜呜……龙君不公啊！这茶舍还未开张，怎料运来的雀儿都不见踪影，我该如何是好……",
            ["ContentJP"] = "うう……白龍様、不公平です！この茶屋はまだ開店していないのに、運んできた雀たちはいなくなって、私は一体どうしたら……",
            ["DialogueId"] = 50107022,
            ["GUID"] = "7D700B4C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C1C",
            },
        [50107023] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["ContentJP"] = "遊覧船を乗りたい方はいませんか。並んでチケットを買ってください、満席になったら出発です。",
            ["DialogueId"] = 50107023,
            ["GUID"] = "7D700B76",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C46",
            },
        [50107024] = {
            ["Content"] = "这皓京城的地形，怎么看怎么觉得邪乎呢……",
            ["ContentJP"] = "この皓京の地形、どう見てもなんだか不気味だな……",
            ["DialogueId"] = 50107024,
            ["GUID"] = "7D700BA0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C70",
            },
        [50107025] = {
            ["Content"] = "想当初咱这湖边多清净？钓竿一放，不消半个时辰就能钓上好几尾大鱼。",
            ["ContentJP"] = "昔はこの湖、ほんとに静かでのう。竿を垂らすだけで、すぐに大きな魚が釣れたもんじゃ。",
            ["DialogueId"] = 50107025,
            ["GUID"] = "7D700BCA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C9A",
            },
        [50107026] = {
            ["Content"] = "若是能把这五禽戏练好，你平日的那些小病小灾，都可一并消弭！",
            ["ContentJP"] = "もしこの五禽戯をうまく習得できれば、ちょっとした病や災いもまとめて消せるぞ！",
            ["DialogueId"] = 50107026,
            ["GUID"] = "7D700BF4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CC4",
            },
        [50107027] = {
            ["Content"] = "他们还真把那五禽戏当真了不成？",
            ["ContentJP"] = "まさか、あの五禽戯を本気で信じてるのか？",
            ["DialogueId"] = 50107027,
            ["GUID"] = "7D700C1E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CEE",
            },
        [50107028] = {
            ["Content"] = "自己要早起练功也便罢了，为何还要拖着我早起……呵欠……",
            ["ContentJP"] = "早起きして修行したいなら自分でやれよ、どうして俺まで……ふぁぁ……",
            ["DialogueId"] = 50107028,
            ["GUID"] = "7D700C48",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D18",
            },
        [50107029] = {
            ["Content"] = "这皓京城还没有我说不成的媒！",
            ["ContentJP"] = "この皓京で、私が取り持てない縁談なんてないよ！",
            ["DialogueId"] = 50107029,
            ["GUID"] = "7D700C72",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D42",
            },
        [50107030] = {
            ["Content"] = "我这般主动找人说亲，会不会……被他看出来了？",
            ["ContentJP"] = "こんなふうに自分から縁談を持ちかけたりして……彼に、見抜かれてしまわないかしら……？",
            ["DialogueId"] = 50107030,
            ["GUID"] = "7D700C9C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D6C",
            },
        [50107031] = {
            ["Content"] = "咱皓京人，除了吃就是喝，没别的~",
            ["ContentJP"] = "金ならいくらでもあるさ。足りないって思ったこと、一度もないな～",
            ["DialogueId"] = 50107031,
            ["GUID"] = "7D700CC6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D96",
            },
        [50107032] = {
            ["Content"] = "瞧你这孩子，走起路来慌慌张张，留心点别踩到路上的石子了！",
            ["ContentJP"] = "あんたって子は、こんなに慌てて……転ばないように気をつけなさいよ！",
            ["DialogueId"] = 50107032,
            ["GUID"] = "7D700CF0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DC0",
            },
        [50107033] = {
            ["Content"] = "什么？涨了这么多？我没看错吧？",
            ["ContentJP"] = "えっ、こんなに値上がりしたのか！？マジかよ？",
            ["DialogueId"] = 50107033,
            ["GUID"] = "7D700D1A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DEA",
            },
        [50107034] = {
            ["Content"] = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
            ["ContentJP"] = "父上はきっと、母上が涙を流しているところを見たくないと思います。だから……",
            ["DialogueId"] = 50107034,
            ["GUID"] = "7D700D44",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E14",
            },
        [50107035] = {
            ["Content"] = "现在都什么年代了，哪有在丧礼上请乐队的人家！",
            ["ContentJP"] = "もういい加減にしてくださいよ、今どき葬式で挽歌を流す人なんてあるかよ！",
            ["DialogueId"] = 50107035,
            ["GUID"] = "7D700D6E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E3E",
            },
        [50107036] = {
            ["Content"] = "林兄，昔日你我诗会相逢，一见如故。高山流水，难遇知音，这杯，我敬你！",
            ["ContentJP"] = "私の親友よ、高山流水の如く、真の知音はなかなか得難い。この一杯、君に捧げる！ありがとうございました。",
            ["DialogueId"] = 50107036,
            ["GUID"] = "7D700D98",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E68",
            },
        [50107037] = {
            ["Content"] = "草木深胡同……是在这里？还是……",
            ["ContentJP"] = "草木通りって……ここかしら？",
            ["DialogueId"] = 50107037,
            ["GUID"] = "7D700DC2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E92",
            },
        [50107038] = {
            ["Content"] = "你说那家私房菜？我是听说过，但那家地方小，难订座，现下去问恐怕是吃不上了。",
            ["ContentJP"] = "あの料理店のことかい？噂には聞いたことがあるけど、あそこは場所も狭くて予約も難しい。今行っても、もう手遅れだぞ。",
            ["DialogueId"] = 50107038,
            ["GUID"] = "7D700DEC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EBC",
            },
        [50107039] = {
            ["Content"] = "若非有仙人指路，怎知这小巷深处竟藏着这庖厨圣地！",
            ["ContentJP"] = "もし仙人の導きがなければ、この小道の奥に料理の聖地があったなんて、知る由もなかった！",
            ["DialogueId"] = 50107039,
            ["GUID"] = "7D700E16",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EE6",
            },
        [50107040] = {
            ["Content"] = "老张啊，你那只八哥，今日居然念了几句诗，是不是你孙子整日在家背书被它听着学了去？",
            ["ContentJP"] = "そこのハッカチョウが今日、なんと詩をいくつか口ずさんだじゃ。お前の孫が毎日家で暗誦してるのを、そいつが聞いて覚えたんじゃないのか？",
            ["DialogueId"] = 50107040,
            ["GUID"] = "7D700E40",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F10",
            },
        [50107041] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟，他们那些鸟，能有我这只厉害吗？",
            ["ContentJP"] = "くだらん、あいつらの鳥が、俺の鳥に敵うわけないだろ？",
            ["DialogueId"] = 50107041,
            ["GUID"] = "7D700E6A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F3A",
            },
        [50107042] = {
            ["Content"] = "车三进六，将军！老友，这局棋，你该怎么破？",
            ["ContentJP"] = "王手！さて友よ、どうする？",
            ["DialogueId"] = 50107042,
            ["GUID"] = "7D700E94",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F64",
            },
        [50107043] = {
            ["Content"] = "叫上陈老太太，咱们也在家里聚上一聚，打打骨牌？",
            ["ContentJP"] = "チンさんも誘って、うちで麻雀でもやろうか？",
            ["DialogueId"] = 50107043,
            ["GUID"] = "7D700EBE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F8E",
            },
        [50107044] = {
            ["Content"] = "我看你是蹬鼻子上脸，三天不打上房揭瓦！给我回去复习功课！",
            ["ContentJP"] = "何回言わせるの？さっさと戻って勉強しなさい！",
            ["DialogueId"] = 50107044,
            ["GUID"] = "7D700EE8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FB8",
            },
        [50107045] = {
            ["Content"] = "我来了！不好意思，今天翻墙出来被阿娘逮到了……",
            ["ContentJP"] = "来たよ！……あ、わりぃ。今日こっそり出てきたらさ、オカンに見つかっちゃった……",
            ["DialogueId"] = 50107045,
            ["GUID"] = "7D700F12",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FE2",
            },
        [50107046] = {
            ["Content"] = "三……二……一……躲好了吗？无由生马上要出来抓你们咯？",
            ["ContentJP"] = "……はーち…きゅう…じゅう……。もういいかい？ムユウセイがみんなを捕まえに行くよ～！",
            ["DialogueId"] = 50107046,
            ["GUID"] = "7D700F3C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70300C",
            },
        [50107047] = {
            ["Content"] = "今年的税账至今还在统计之中，明年的汇算眼见着也要来了……真是忙到头晕眼花。",
            ["ContentJP"] = "今年の税務はまだ集計中で、来年の精算ももうすぐやってくる……まったく、忙しすぎて目が回りそうだ。",
            ["DialogueId"] = 50107047,
            ["GUID"] = "7D700F66",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703036",
            },
        [50107048] = {
            ["Content"] = "昨夜通宵整理典籍，今日双眼昏花，恐一蹬腿就要去往虞泉了！",
            ["ContentJP"] = "昨夜、徹夜で典籍を整理したせいで、虞泉行きになりそうだ！",
            ["DialogueId"] = 50107048,
            ["GUID"] = "7D700F90",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703060",
            },
        [50107049] = {
            ["Content"] = "奉香大典意味着什么？意味着休假呀！我一直想去海伯利亚看雪……",
            ["ContentJP"] = "奉香の儀って何かって？もちろんお休みよ！ヒュペリアで雪を見に行くつもり……",
            ["DialogueId"] = 50107049,
            ["GUID"] = "7D700FBA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70308A",
            },
        [50107050] = {
            ["Content"] = "这般数据出现在这栏不太应当，莫非是填错了？",
            ["ContentJP"] = "こんなデータがここにいるのはおかしいな……もしかして、入力ミス？",
            ["DialogueId"] = 50107050,
            ["GUID"] = "7D700FE4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030B4",
            },
        [50107051] = {
            ["Content"] = "最近的日子，真是难得的清闲啊~",
            ["ContentJP"] = "最近は、平和でのんびりだな～",
            ["DialogueId"] = 50107051,
            ["GUID"] = "7D70100E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030DE",
            },
        [50107052] = {
            ["Content"] = "下次遇到这种事情记得早些来泉通司，硬拖只会让事态恶化。",
            ["ContentJP"] = "次にこういうことがあったら、早めに泉通司に来てください。最適なタイミングを逃すと、事態が悪化するだけですよ。",
            ["DialogueId"] = 50107052,
            ["GUID"] = "7D701038",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703108",
            },
        [50107053] = {
            ["Content"] = "祀香阁今年为何额外申请了一笔经费，是作何用处的？",
            ["ContentJP"] = "祀煙閣は今年、なぜ追加で予算を申請したのですか？何に使うつもりなのでしょう？",
            ["DialogueId"] = 50107053,
            ["GUID"] = "7D701062",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703132",
            },
        [50107054] = {
            ["Content"] = "搭台子，修香炉，后续还有各种开销，我都递交申请了，只是拨款何时能来？",
            ["ContentJP"] = "祭壇の材料費と香炉の修繕、これからもいろいろ出費があるんだ。申請は全部出したけど、いつ予算が下りるんだ？",
            ["DialogueId"] = 50107054,
            ["GUID"] = "7D70108C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70315C",
            },
        [50107055] = {
            ["Content"] = "是，就是往西郊那个方向，鬼鬼祟祟的，看起来不像什么好人。",
            ["ContentJP"] = "そうそう、西郊のあの方向だ。こそこそしてて、どう見ても良い人には見えないな。",
            ["DialogueId"] = 50107055,
            ["GUID"] = "7D7010B6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703186",
            },
        [50107056] = {
            ["Content"] = "西郊西郊西郊，为何几封投诉信，来来回回都在提西郊？",
            ["ContentJP"] = "西郊、西郊、また西郊……苦情の手紙が、なんで全部西郊のことばかりなんだ？",
            ["DialogueId"] = 50107056,
            ["GUID"] = "7D7010E0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031B0",
            },
        [50107057] = {
            ["Content"] = "快给我来碗茶水，刚从西郊回来，渴死我了！",
            ["ContentJP"] = "早くお茶ちょうだい！西郊から戻ったばかりで、喉カラカラで死にそう……",
            ["DialogueId"] = 50107057,
            ["GUID"] = "7D70110A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031DA",
            },
        [50107058] = {
            ["Content"] = "嗯，是说您负责运输的一船货物在码头丢失了……不是货物？那是……翠屏雀？！",
            ["ContentJP"] = "ええ、つまり、あなたが運んでいた船の荷物が港でなくなったということ……荷物じゃない？……スイヘイジャク？！",
            ["DialogueId"] = 50107058,
            ["GUID"] = "7D701134",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703204",
            },
        [50107059] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["ContentJP"] = "一体どうやって外に出ちゃったんだろう……？",
            ["DialogueId"] = 50107059,
            ["GUID"] = "7D70115E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70322E",
            },
        [50107060] = {
            ["Content"] = "找不回来了……一切努力都付之东流了……",
            ["ContentJP"] = "見つからない……もう終わりだ……",
            ["DialogueId"] = 50107060,
            ["GUID"] = "7D701188",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703258",
            },
        [50107061] = {
            ["Content"] = "已经找到一只了？在民居的屋顶上？到底是怎么飞上去的？！",
            ["ContentJP"] = "もう一羽見つかったの？屋根の上に？いったいどうやって？！",
            ["DialogueId"] = 50107061,
            ["GUID"] = "7D7011B2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703282",
            },
        [50107062] = {
            ["Content"] = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
            ["ContentJP"] = "千繍閣の今年の注文量、またずいぶん増えたな。うちの刺繍、皓京で本当に人気ですな～",
            ["DialogueId"] = 50107062,
            ["GUID"] = "7D7011DC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032AC",
            },
        [50107063] = {
            ["Content"] = "此趟运输甜果只有百分之三损毁？甚好甚好~",
            ["ContentJP"] = "今回の輸送で、ロス率はわずか3％？よかった～",
            ["DialogueId"] = 50107063,
            ["GUID"] = "7D701206",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032D6",
            },
        [50107064] = {
            ["Content"] = "太皓神君的纹样大家早就看腻啦~一点新意也没有。",
            ["ContentJP"] = "太皓様の紋様、みんなもう見飽きちゃったわ～ワンパターンだよこれ。",
            ["DialogueId"] = 50107064,
            ["GUID"] = "7D701230",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703300",
            },
        [50107065] = {
            ["Content"] = "各位好姐姐好哥哥们，现在呢就已经到了咱们皓京，也是咱们华胥呢，最繁华的地方~",
            ["ContentJP"] = "みなさん、こっちですよ～今、私たちは華胥で一番賑やかな場所、皓京に到着しました～",
            ["DialogueId"] = 50107065,
            ["GUID"] = "7D70125A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70332A",
            },
        [50107066] = {
            ["Content"] = "三百九十九？！皓京三天两晚包吃包住包来回船票只需要三百九十九？",
            ["ContentJP"] = "あらまあ！皓京で2泊3日、食事付き・交通費宿泊費込みで、こんなに安いなんて！",
            ["DialogueId"] = 50107066,
            ["GUID"] = "7D701284",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703354",
            },
        [50107067] = {
            ["Content"] = "恁大一个皓京城，比我屋头看着气派多了哟！",
            ["ContentJP"] = "これが皓京か。さすがだじゃ！おいらこんな町見だごとぁねえ！",
            ["DialogueId"] = 50107067,
            ["GUID"] = "7D7012AE",
            ["SpecialConversation"] = "偏川普",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70337E",
            },
        [50107068] = {
            ["Content"] = "别靠过来！我……呕……我……头好晕……怎么有三个太阳……呕！",
            ["ContentJP"] = "近づかないで！私…うっ…頭が…クラクラする…太陽が三つも見える…うっ！",
            ["DialogueId"] = 50107068,
            ["GUID"] = "7D7012D8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033A8",
            },
        [50107069] = {
            ["Content"] = "水龙车我先带走了。不知道哪个龟孙以为是普通木桶，居然往里面放香油，被老鼠啃得面目全非。",
            ["ContentJP"] = "水龍車は先に持っていく。どいつだ、普通の木桶だと思ってごま油を入れやがったのは。ネズミにかじられて、めちゃくちゃになっちまったじゃないか。",
            ["DialogueId"] = 50107069,
            ["GUID"] = "7D701302",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033D2",
            },
        [50107070] = {
            ["Content"] = "匠矩阁的师傅已经来将水龙车全部取走了吗？太麻烦他们了。",
            ["ContentJP"] = "匠矩閣の師匠たちは、もう水龍車を全部取りに来たのか？ほんと、手間をかけさせちゃったな。",
            ["DialogueId"] = 50107070,
            ["GUID"] = "7D70132C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033FC",
            },
        [50107071] = {
            ["Content"] = "为何匠矩阁的人回回要来参商港跑个好几趟，来回拉扯不嫌麻烦吗？",
            ["ContentJP"] = "どうして匠矩閣の人たちは、毎回参商港まで何度も往復するんだろうな。面倒くさくないのかねぇ？",
            ["DialogueId"] = 50107071,
            ["GUID"] = "7D701356",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703426",
            },
        [50107072] = {
            ["Content"] = "凌波微步，且看我腾空起，驾云去，身似飞雁过南关，蜻蜓点水不留痕！嘿！哈！",
            ["ContentJP"] = "見ろ…奥義「水蜘蛛の術」！俺の身は空を駆け、雲を操り、まるで鷹の如く！蜻蛉の如く水面に触れ、痕跡など残さない！へっ！はっ！俺の力、思い知れ！",
            ["DialogueId"] = 50107072,
            ["GUID"] = "7D701380",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703450",
            },
        [50107073] = {
            ["Content"] = "天一热，潮一涨，这浸在水中的部分就开始疯狂长苔，转动都费劲……",
            ["ContentJP"] = "暑くなって潮が上がると、水に浸かっとる部分はたちまち苔だらけだ。回すのもひと苦労じゃ……",
            ["DialogueId"] = 50107073,
            ["GUID"] = "7D7013AA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70347A",
            },
        [50107074] = {
            ["Content"] = "要不是他们把水车停了下来，怎会有这多事端？",
            ["ContentJP"] = "もしあいつらが水車を止めなかったら、こんな面倒なことにはならなかったのに。",
            ["DialogueId"] = 50107074,
            ["GUID"] = "7D7013D4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034A4",
            },
        [50107075] = {
            ["Content"] = "你需谨记六字——明法、公心、勤谨。",
            ["ContentJP"] = "君はこの六つの字を心に刻むべきだ——明法、公心、勤勉。",
            ["DialogueId"] = 50107075,
            ["GUID"] = "7D7013FE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034CE",
            },
        [50107076] = {
            ["Content"] = "每至夜半三更，船舶抵港，那船工吆喝声、铁链撞击声、货箱搬运声，直吵得人不得安睡！",
            ["ContentJP"] = "深夜になると、船が港に着く。そのときの船頭の掛け声や鉄の鎖のぶつかる音、箱を運ぶ音がうるさくて、まったく寝られない！",
            ["DialogueId"] = 50107076,
            ["GUID"] = "7D701428",
            ["SpecialConversation"] = "该npc为一期印象npc",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034F8",
            },
        [50107077] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
            ["ContentJP"] = "遊覧船を乗りたい方はいませんか。並んでチケットを買ってください、満席になったら出発です。",
            ["DialogueId"] = 50107077,
            ["GUID"] = "7D701452",
            ["SpecialConversation"] = "该npc与刘福最好为一人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703522",
            },
        [50107078] = {
            ["Content"] = "稍……稍等一下……我查一下刚买的《华胥问候语录大全》。",
            ["ContentJP"] = "ちょ……ちょっと待ってください……今買ったばかりの『華胥あいさつフレーズブック』だと……",
            ["DialogueId"] = 50107078,
            ["GUID"] = "7D70147C",
            ["SpecialConversation"] = "外国人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70354C",
            },
        [50107079] = {
            ["Content"] = "他大舅母，晚上做了什么好吃的？可是来这儿散散步，消消食？",
            ["ContentJP"] = "今夜は何かおいしいものを作ったのかい？それとも、食後の腹ごなしにここへ散歩に来たのかね？",
            ["DialogueId"] = 50107079,
            ["GUID"] = "7D7014A6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703576",
            },
        [50107080] = {
            ["Content"] = "一，二，三，铁柱呢？铁柱为何不在？你们来的时候看到他了吗？",
            ["ContentJP"] = "いち、に、さん……あれ、テッチュウは？どこへ行ってしもうたのだ？そなた、来たとき見たか？",
            ["DialogueId"] = 50107080,
            ["GUID"] = "7D7014D0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035A0",
            },
        [50107081] = {
            ["Content"] = "尘香袅袅龙君现，典前争辉竞纷纭。奉香大典特别活动——灯谜会，待君赏玩！",
            ["ContentJP"] = "謎解きの達人は誰だ！？奉香の儀特別イベントですよ、お楽しみをお待ちしています！",
            ["DialogueId"] = 50107081,
            ["GUID"] = "7D7014FA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035CA",
            },
        [50107082] = {
            ["Content"] = "妈妈我到皓京了……",
            ["ContentJP"] = "ママ、俺、皓京に着いたよ……",
            ["DialogueId"] = 50107082,
            ["GUID"] = "7D701524",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035F4",
            },
        [50107083] = {
            ["Content"] = "这里面不能进去吗？我买票也不行？那有什么办法能进去看看？我想见白龙神君。",
            ["ContentJP"] = "ここ、中に入れないのか？チケットを買ってもダメなのか？じゃあ、どうすれば入ってもらえるんだ？俺は白龍様に会いたいのだ。",
            ["DialogueId"] = 50107083,
            ["GUID"] = "7D70154E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70361E",
            },
        [50107084] = {
            ["Content"] = "你看！只要内心足够虔诚，望向执律阁顶之时，就会看到白龙神君在云间遨游。",
            ["ContentJP"] = "ほら見て！心が清くあれば、執律閣の頂を見上げたとき、雲の間を泳ぐ白龍様が見えるんだよ。",
            ["DialogueId"] = 50107084,
            ["GUID"] = "7D701578",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703648",
            },
        [50107085] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报，皓京独家新闻，绝对真实绝对劲爆！",
            ["ContentJP"] = "茶も飲みたくない、ご飯も食べたくない、朝報だけ見たい！皓京特ダネニュースはいかがですか？",
            ["DialogueId"] = 50107085,
            ["GUID"] = "7D7015A2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703672",
            },
        [50107086] = {
            ["Content"] = "这字乍一看好似和海伯利亚那边没什么区别，可凑在一起为什么完全看不懂……",
            ["ContentJP"] = "この文字、ぱっと見るとヒュペリアの文字と変わらないようだけど、並べてみると、どうして全然読めないんだろう……",
            ["DialogueId"] = 50107086,
            ["GUID"] = "7D7015CC",
            ["SpecialConversation"] = "外国人",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70369C",
            },
        [50107087] = {
            ["Content"] = "您听我说，您去一个地方，吃什么玩什么，都是次要，主要的是要来感受当地的氛围，您说对不对？",
            ["ContentJP"] = "聞いておくれ、ある場所に行くとき、何を食べるか、何をするかなんてのは二の次でな、一番大事なのはその土地の雰囲気を感じることだ、そう思わんか？",
            ["DialogueId"] = 50107087,
            ["GUID"] = "7D7015F6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036C6",
            },
        [50107088] = {
            ["Content"] = "退一万步说，在人家办事处门口宣传这些也不合适吧……",
            ["ContentJP"] = "人の事務所の前でこういう宣伝をするのはやっぱり適切じゃないですよね……",
            ["DialogueId"] = 50107088,
            ["GUID"] = "7D701620",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036F0",
            },
        [50107089] = {
            ["Content"] = "我家老婆子好好地走在街上，他路也不看，直接推着车撞了过来。",
            ["ContentJP"] = "うちの奥さんが道を歩いてるのに、あいつは道も見ずに、いきなり車押してぶつかってきたんだ。",
            ["DialogueId"] = 50107089,
            ["GUID"] = "7D70164A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70371A",
            },
        [50107090] = {
            ["Content"] = "以香论道法，坐实众生象，天地为共生，万物与我一……",
            ["ContentJP"] = "天地は共に生き、万物は我と一つ……",
            ["DialogueId"] = 50107090,
            ["GUID"] = "7D701674",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703744",
            },
        [50107091] = {
            ["Content"] = "为人在世，奉天命当如沙洲，勤而学当如竹溪先生。",
            ["ContentJP"] = "世の中に生きる者として、天命に従うならば砂州のごとくあれ、勤勉に学ぶならば竹渓先生のごとくあれ。",
            ["DialogueId"] = 50107091,
            ["GUID"] = "7D70169E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70376E",
            },
        [50107092] = {
            ["Content"] = "我何时曾说我亲眼见过竹溪先生？我说的是父亲年幼之时，曾在学院听竹溪先生传授最后一课。",
            ["ContentJP"] = "わしが竹渓先生を見たことがあるって、いつ言うたかのう？言うたのは、わしの父が幼いころ、学院で竹渓先生の最後の授業を聞いたことがあるのじゃ。",
            ["DialogueId"] = 50107092,
            ["GUID"] = "7D7016C8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703798",
            },
        [50107093] = {
            ["Content"] = "吵死了……这怎么让人背书！",
            ["ContentJP"] = "うるさすぎる……こんなんじゃ勉強できない！",
            ["DialogueId"] = 50107093,
            ["GUID"] = "7D7016F2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037C2",
            },
        [50107094] = {
            ["Content"] = "所谓理一，即天地万物都只有一个理，所谓分殊，即千差万殊的事物都是一个理的体现。",
            ["ContentJP"] = "いわゆる「理一」とは、天地万物にはただ一つの道理しかないこと。いわゆる「分殊」とは、千差万別の事物はすべて一つの道理の現れである。",
            ["DialogueId"] = 50107094,
            ["GUID"] = "7D70171C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037EC",
            },
        [50107095] = {
            ["Content"] = "五味万殊，而大同于美；曲变虽众，亦大同于和；子性各异，但大同于敏；教术众多，然大同于情。",
            ["ContentJP"] = "五味は万殊なれど美味に同じ、曲変は衆多なれど和に同じ、子は各異なれど慧敏に同じ、教えは多けれど情に同じ。",
            ["DialogueId"] = 50107095,
            ["GUID"] = "7D701746",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703816",
            },
        [50107096] = {
            ["Content"] = "这万事万物，道理总是只有一个，但一个道理却可涵盖了世间万物，所以理一定是在前面的！",
            ["ContentJP"] = "この万事万物、道理はいつもひとつしかない。しかしそのひとつの道理が、世のすべてを包み込む。だから道理は、必ず先にあるのだ！",
            ["DialogueId"] = 50107096,
            ["GUID"] = "7D701770",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703840",
            },
        [50107097] = {
            ["Content"] = "今天该轮到你执勤了吧，之前你说你娘风寒，我可帮你顶了三天，夫子都起疑了！",
            ["ContentJP"] = "今日はあなたの当番でしょう？前にお母さんが風邪ひいたって言ってさ、三日も私が代わりにやったんだよ。",
            ["DialogueId"] = 50107097,
            ["GUID"] = "7D70179A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70386A",
            },
        [50107098] = {
            ["Content"] = "奉香大典期间放假，你们都去哪玩？我哥从外地回来了，说要给我带外国的新奇玩具呢。",
            ["ContentJP"] = "奉香の儀の休み、みんなどこ行くの？兄ちゃんが海外のおもちゃを買ってきてくれるんだ。",
            ["DialogueId"] = 50107098,
            ["GUID"] = "7D7017C4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703894",
            },
        [50107099] = {
            ["Content"] = "下午的蹴球赛，咱们队还差一人，你问过樾山哥没有？他要是肯来，咱们定能踢得对面满地找牙！",
            ["ContentJP"] = "午後の蹴球試合、うちのチームはあと一人足りない。エツサン兄さんには聞いたか？来てくれたら、相手をボコボコにできるぞ！",
            ["DialogueId"] = 50107099,
            ["GUID"] = "7D7017EE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038BE",
            },
        [50107100] = {
            ["Content"] = "按这个势头算下去，岂不是又要扩张？可这又还能往哪里扩呢？",
            ["ContentJP"] = "この勢いでいくと、また拡張することになるんじゃないか？でも、拡張できる場所なんてないな。",
            ["DialogueId"] = 50107100,
            ["GUID"] = "7D701818",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038E8",
            },
        [50107101] = {
            ["Content"] = "是了，来年开春便要递上辞函，到时候自然是会念着大家的，放心！",
            ["ContentJP"] = "そうだな、来年の春には辞表を出すつもりだ。いろいろ、お世話になりました。",
            ["DialogueId"] = 50107101,
            ["GUID"] = "7D701842",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703912",
            },
        [50107102] = {
            ["Content"] = "若华胥的安宁和平需要人们以不同的努力去守护，那为何飘零人的行为不能算是一种独特的方式？",
            ["ContentJP"] = "もし華胥の安寧と平和を守るために、人々がそれぞれ違った努力をする必要があるのなら、なぜ流れ者の行いは認められないのだろう？",
            ["DialogueId"] = 50107102,
            ["GUID"] = "7D70186C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70393C",
            },
        [50107103] = {
            ["Content"] = "好啊，今天的辩题有趣，我在学院许久没见过这么有意思的辩题了。",
            ["ContentJP"] = "今日の討論テーマは面白いな。久しぶりにこんな興味深いのを見た。",
            ["DialogueId"] = 50107103,
            ["GUID"] = "7D701896",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703966",
            },
        [50107104] = {
            ["Content"] = "空口说白话，不亚于纸上谈兵。有这闲工夫，不如多读些书！",
            ["ContentJP"] = "口だけで言っても、紙上の空論と変わらん。そんなことしてる暇があるなら、もっと本を読め！",
            ["DialogueId"] = 50107104,
            ["GUID"] = "7D7018C0",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703990",
            },
        [50107105] = {
            ["Content"] = "椒兰村的香料自然是地道，处理方式也多样，只是要论品质，外面的许多园子都不遑多让。",
            ["ContentJP"] = "やっぱり、椒蘭村の香料は絶品だわ、加工方法も多様で。ただ、品質だけだと、別の商店も負けてはいないわ。",
            ["DialogueId"] = 50107105,
            ["GUID"] = "7D7018EA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039BA",
            },
        [50107106] = {
            ["Content"] = "敢问祀烟阁的管事香官现在何处？鄙人自氤园而来，与他有约。",
            ["ContentJP"] = "失礼ながら、祀煙閣の香官は今どこにおいででしょうか？私は芳青園より参りました、彼とお約束がございます。",
            ["DialogueId"] = 50107106,
            ["GUID"] = "7D701914",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039E4",
            },
        [50107107] = {
            ["Content"] = "今日怎得是你来奉香，你哥又回烟津渡了？",
            ["ContentJP"] = "今日、どうして奉香に来たの？兄さんはまた煙津渡に戻ったの？",
            ["DialogueId"] = 50107107,
            ["GUID"] = "7D70193E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A0E",
            },
        }
  end },
  { MinKey = 50107108, MaxKey = 50107350, Loader = function()
      return {
        [50107108] = {
            ["Content"] = "伏惟上苍垂佑，神君护持，愿家父身体健康，百病不侵。",
            ["ContentJP"] = "天の加護あらんことを、神君の守りあれ、父が無病息災で過ごせますように。",
            ["DialogueId"] = 50107108,
            ["GUID"] = "7D701968",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A38",
            },
        [50107109] = {
            ["Content"] = "唔……我的愿望是，长高一点，也不用太高，像一个正常的抟土氏就好。",
            ["ContentJP"] = "うーん……べ、別に欲張ってないし。わたしのお願いは、ちょっとだけ背が伸びることよ。土の民くらいで十分なの。",
            ["DialogueId"] = 50107109,
            ["GUID"] = "7D701992",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A62",
            },
        [50107110] = {
            ["Content"] = "奉香大典今年比往年都热闹许多呢！香官跟我说的。",
            ["ContentJP"] = "今年の奉香の儀は、例年よりずっと賑やかね！香官もそう言ってたのよ。",
            ["DialogueId"] = 50107110,
            ["GUID"] = "7D7019BC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A8C",
            },
        [50107111] = {
            ["Content"] = "往年到了奉香大典期间，总是需要许多帮工入阁，今年怎得没动静了？",
            ["ContentJP"] = "例年、奉香の儀の時期になると、たくさんの手伝いが閣に入るのに、今年はどうしてないのじゃろう？",
            ["DialogueId"] = 50107111,
            ["GUID"] = "7D7019E6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AB6",
            },
        [50107112] = {
            ["Content"] = "全城的香炉都要仔细查验香料储备，尤其是中心广场水上的那个炉子，务必不能有疏漏。",
            ["ContentJP"] = "全市の香炉はすべての香料を入念に点検せねばならない。特に中央広場の水上にあるあの香炉、絶対に見落とししないで。",
            ["DialogueId"] = 50107112,
            ["GUID"] = "7D701A10",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AE0",
            },
        [50107113] = {
            ["Content"] = "难不成真是我思维迟缓，想不出新颖独特的香方了？",
            ["ContentJP"] = "わしの思考が鈍くなったのかのう？新しい薫物が思いつかんとは。",
            ["DialogueId"] = 50107113,
            ["GUID"] = "7D701A3A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B0A",
            },
        [50107114] = {
            ["Content"] = "不同的香方自然作用也不相同，你初来乍到，不了解也很正常。",
            ["ContentJP"] = "薫物が違えば、当然作用も異なる。初めて来たばかりなら、わからなくても当然だ。",
            ["DialogueId"] = 50107114,
            ["GUID"] = "7D701A64",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B34",
            },
        [50107115] = {
            ["Content"] = "听说了吗？祀香阁今年招了一位特殊香官，据说是……一位皎皎之民！",
            ["ContentJP"] = "聞いたかい？祀煙閣は今年、特別な香官を採用したのよ。なんでも、ルーナ族だそうよ！",
            ["DialogueId"] = 50107115,
            ["GUID"] = "7D701A8E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B5E",
            },
        [50107116] = {
            ["Content"] = "皎皎之民？！那矮冬瓜大头鱼一样的家伙，如何能担任香官一职？",
            ["ContentJP"] = "ルーナ族だって？！あの背が低くて頭が大きいやつが、香官を務めるのか？",
            ["DialogueId"] = 50107116,
            ["GUID"] = "7D701AB8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B88",
            },
        [50107117] = {
            ["Content"] = "去泉通司问过了吗？奉香大典前事务繁杂，那批拨款要早点讨过来才好做事。",
            ["ContentJP"] = "泉通司にはもう聞いたか？奉香の儀前は事務が立て込むから、あの費用は早めに回収しておかないと仕事が進まんぞ。",
            ["DialogueId"] = 50107117,
            ["GUID"] = "7D701AE2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BB2",
            },
        [50107118] = {
            ["Content"] = "师傅，我就是想来问问，这炉灶为何总是出问题，我这几番叨扰，自己都有点过意不去了。",
            ["ContentJP"] = "師匠、お尋ねしたくて来たのです。この炉はどうしていつも問題が起きるのでしょうか？何度もお邪魔してしまって、申し訳ございません。",
            ["DialogueId"] = 50107118,
            ["GUID"] = "7D701B0C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BDC",
            },
        [50107119] = {
            ["Content"] = "过两天不是休息了吗？你准备回家？还是带妻子出门逛逛？",
            ["ContentJP"] = "もうすぐ休みだろ？実家に帰るか？それとも奥さんと出かけるのか？",
            ["DialogueId"] = 50107119,
            ["GUID"] = "7D701B36",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C06",
            },
        [50107120] = {
            ["Content"] = "来奉香也有这么多嘁嘁喳喳嘟嘟囔囔，要么就是嘀嘀咕咕哼哼唧唧，这要我们如何兢兢业业干活？",
            ["ContentJP"] = "奉香に来ても、あちこちブツブツでうるさい！こんなんじゃ、働けないわよ！",
            ["DialogueId"] = 50107120,
            ["GUID"] = "7D701B60",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C30",
            },
        [50107121] = {
            ["Content"] = "你这关节做的根本不行！偶人要做抬手、转腰的动作，反复受力下来，榫头迟早开裂！",
            ["ContentJP"] = "この関節、全然ダメだ！人形が手を上げたり腰を回したりする動作を繰り返せば、遅かれ早かれ割れてしまう！",
            ["DialogueId"] = 50107121,
            ["GUID"] = "7D701B8A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C5A",
            },
        [50107122] = {
            ["Content"] = "你瞧瞧，这是咱们新研究的木头珍猪，上了发条后一下便能冲出十米，想学的话来机枢派报个名？",
            ["ContentJP"] = "見てごらん、これが我々の新しく開発した木製の珍猪だ。ゼンマイを巻くと、一気に10メートルも飛び出すんだ。習いたければ、機枢派にきたまえ。",
            ["DialogueId"] = 50107122,
            ["GUID"] = "7D701BB4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703C84",
            },
        [50107123] = {
            ["Content"] = "叔叔，这是什么？看着好可爱，可以送给我吗？",
            ["ContentJP"] = "おじさん、これなに？すごく可愛いね、わたしにくれる？",
            ["DialogueId"] = 50107123,
            ["GUID"] = "7D701BDE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CAE",
            },
        [50107124] = {
            ["Content"] = "年年招新，年年没人，与其把心思放在拉人进阁，还不如多花些时间造个惊天动地的大工程出来！",
            ["ContentJP"] = "毎年新入生を募集しても、毎年誰も来ない。人を閣に引き込むことより、いっそ時間をかけて、世を驚かす大プロジェクトをやる方がええじゃろう！",
            ["DialogueId"] = 50107124,
            ["GUID"] = "7D701C08",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703CD8",
            },
        [50107126] = {
            ["Content"] = "民以食为天，食以香为先，香……这香……香啊……香。",
            ["ContentJP"] = "美食は何よりも大切である。この香……美味そうだ。",
            ["DialogueId"] = 50107126,
            ["GUID"] = "7D701C5C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D2C",
            },
        [50107127] = {
            ["Content"] = "这就是华胥风格的服饰吗？嘶……我怎么觉得穿起来哪里怪怪的呢？",
            ["ContentJP"] = "これが華胥風の服装？うぅ……なんか着てみると、変な感じがするね。",
            ["DialogueId"] = 50107127,
            ["GUID"] = "7D701C86",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D56",
            },
        [50107128] = {
            ["Content"] = "青青子衿，悠悠我心，在这苍茫人世间，难道我真就无法找到相伴一生之人？",
            ["ContentJP"] = "この広大な世界で、ほんとうに一生を共にする人を見つけられないのだろうか？",
            ["DialogueId"] = 50107128,
            ["GUID"] = "7D701CB0",
            ["SpecialConversation"] = "该角色不怎么着调，可以跳脱一点",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703D80",
            },
        [50107129] = {
            ["Content"] = "要是我把这个人杀了……大家的反响一定很好，要是再把这个也顺便刀了……",
            ["ContentJP"] = "もしこの人を殺したら……みんなきっと良い反応するだろう。ついでに、こいつも斬ってしまえば……",
            ["DialogueId"] = 50107129,
            ["GUID"] = "7D701CDA",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DAA",
            },
        [50107130] = {
            ["Content"] = "天气大好啊，等开春，去收两斤新茶泡来喝！",
            ["ContentJP"] = "いい天気じゃ。春になったら、茶摘みをして、淹れて飲もう！",
            ["DialogueId"] = 50107130,
            ["GUID"] = "7D701D04",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DD4",
            },
        [50107131] = {
            ["Content"] = "瞧见那远处的楼没？我啊，小时候曾听老人说，其实它根本不存在，都是假的！",
            ["ContentJP"] = "あの遠くの建物、見える？私、子どものころに年寄りから聞いたんだけど、実はあれ、実体がない幻なのよ。",
            ["DialogueId"] = 50107131,
            ["GUID"] = "7D701D2E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703DFE",
            },
        [50107132] = {
            ["Content"] = "所有目光向我看齐，在场的各位，都是彻彻底底的聪明龙！聪明土！",
            ["ContentJP"] = "みんな、こっちを見て！ここにいる全員、間違いなく超ラッキーだよ！",
            ["DialogueId"] = 50107132,
            ["GUID"] = "7D701D58",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E28",
            },
        [50107133] = {
            ["Content"] = "怎就没有愿意与我辩论之人？莫非是我过于咄咄逼人了？",
            ["ContentJP"] = "どうして私と議論してくれる人がいないのでしょう？もしかして、私が怖そうから？",
            ["DialogueId"] = 50107133,
            ["GUID"] = "7D701D82",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E52",
            },
        [50107134] = {
            ["Content"] = "要说最为复杂的调解案……莫过于十年前的那场意外了。",
            ["ContentJP"] = "最も複雑な調停事件と言えば……十年前のあの事故かもね。",
            ["DialogueId"] = 50107134,
            ["GUID"] = "7D701DAC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703E7C",
            },
        [50107135] = {
            ["Content"] = "若是法理不通，又怎敢把评判的权利交由那劳什子人心私情？",
            ["ContentJP"] = "法や道理すら通らないのに、どうして評判や裁断の権限を、あてにならない個人的な感情や私心に委ねられようか。",
            ["DialogueId"] = 50107135,
            ["GUID"] = "7D701DD6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EA6",
            },
        [50107136] = {
            ["Content"] = "现在敲敲打打的这些木头块，那都没意思！要是放在以前，我能给你们看带劲的大家伙！",
            ["ContentJP"] = "全然面白くない！昔なら、あんたたちに見せてやれる迫力満点の大物があったのに！",
            ["DialogueId"] = 50107136,
            ["GUID"] = "7D701E00",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703ED0",
            },
        [50107137] = {
            ["Content"] = "皎皎为何不能当香官？我偏要当这皎皎第一人！",
            ["ContentJP"] = "ルーナ族が香官になれないって？そんなの関係ないもん！わたし、一番偉いの香官になってみせるんだから！",
            ["DialogueId"] = 50107137,
            ["GUID"] = "7D701E2A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703EFA",
            },
        [50107138] = {
            ["Content"] = "夫君莫急，你先将那筐香料放下再说，那种叶子娇贵，颠了撒了香味可要散一半呢。",
            ["ContentJP"] = "あなた、焦らないで。まずはその香料を下ろして。とてもデリケートだから、揺すってこぼしたら香りが半分は飛んでしまいますよ。",
            ["DialogueId"] = 50107138,
            ["GUID"] = "7D701E54",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F24",
            },
        [50107139] = {
            ["Content"] = "想起来了，我可都想起来了，由来巷的事儿，我可全都记着呢！",
            ["ContentJP"] = "思い出したよ、ぜーんぶ思い出した！由来の里のこと、全部覚えてるもん。",
            ["DialogueId"] = 50107139,
            ["GUID"] = "7D701E7E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F4E",
            },
        [50107140] = {
            ["Content"] = "飘零四杰啊……那可真是一段因为年代久远而模糊不清的故事啊……",
            ["ContentJP"] = "山外山四天王か……それはもう、遠い遠い昔の話じゃ……",
            ["DialogueId"] = 50107140,
            ["GUID"] = "7D701EA8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703F78",
            },
        [50107141] = {
            ["Content"] = "高高的台上我远远地望，见笨笨的家伙建高高的台~",
            ["ContentJP"] = "高い、高い舞台の上から、遠く、遠くまで見下ろす、のろまなあの子が舞台を作っている～",
            ["DialogueId"] = 50107141,
            ["GUID"] = "7D701ED2",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FA2",
            },
        [50107142] = {
            ["Content"] = "又来了一个长鼻子家伙，诶呀诶呀，这家伙怎么看着我？",
            ["ContentJP"] = "また長い鼻のが来たよ、あやや、あやや、どうして私のこと見てるの？",
            ["DialogueId"] = 50107142,
            ["GUID"] = "7D701EFC",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FCC",
            },
        [50107143] = {
            ["Content"] = "都去哪里了？我要开始抓你们了哦！",
            ["ContentJP"] = "みんな隠れた？捕まえちゃうよ〜！",
            ["DialogueId"] = 50107143,
            ["GUID"] = "7D701F26",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703FF6",
            },
        [50107144] = {
            ["Content"] = "谁家的孩子穿一身白，太素净，看着一点也不喜庆！",
            ["ContentJP"] = "あらっ、あんた！真っ白な格好だね。地味すぎるよ！",
            ["DialogueId"] = 50107144,
            ["GUID"] = "7D701F50",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704020",
            },
        [50107145] = {
            ["Content"] = "此香烘制程度不够，你闻，香味还没散出来呢。",
            ["ContentJP"] = "この香は焙じが足りない。ほら、嗅いでみてください、まだ香りが立ってきていないでしょう。",
            ["DialogueId"] = 50107145,
            ["GUID"] = "7D701F7A",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70404A",
            },
        [50107146] = {
            ["Content"] = "早跟你说了，收回来的新鲜吿苍要立即拿去晾晒，为何回回都能忘了呢？",
            ["ContentJP"] = "言ったでしょ、新鮮の告蒼はすぐに干さなきゃいけないのに、どうして毎回忘れちゃうのよ？",
            ["DialogueId"] = 50107146,
            ["GUID"] = "7D701FA4",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704074",
            },
        [50107147] = {
            ["Content"] = "落生香的原料研磨最讲究精细，一遍下来若是还有这种大颗粒，你得重新再来一遍。",
            ["ContentJP"] = "落生香の原料は、研磨のとき、細かさが何より大事だ。一度やって、まだこんな大きな粒が残っていたら、最初からやり直さなきゃいけない。",
            ["DialogueId"] = 50107147,
            ["GUID"] = "7D701FCE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70409E",
            },
        [50107148] = {
            ["Content"] = "亮哥亮哥！快来帮忙，炉子又炸了！",
            ["ContentJP"] = "リョウ兄、リョウ兄！助けて、炉がまた爆発したの！",
            ["DialogueId"] = 50107148,
            ["GUID"] = "7D701FF8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040C8",
            },
        [50107149] = {
            ["Content"] = "合香是一门技术活，没你想得那么简单，配比和时间都要多加注意，制香也要顺应天时呀~",
            ["ContentJP"] = "合香はな、ただの作業じゃない。配合も時間も、しっかり気をつけねばならん。",
            ["DialogueId"] = 50107149,
            ["GUID"] = "7D702022",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7040F2",
            },
        [50107150] = {
            ["Content"] = "那批香装好了吗？订货的那些人问过几回了。",
            ["ContentJP"] = "あの香、もう詰め終わった？注文した人たち、何度も聞いてきたよ。",
            ["DialogueId"] = 50107150,
            ["GUID"] = "7D70204C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70411C",
            },
        [50107151] = {
            ["Content"] = "抓紧犁完这片田，就能早些回家歇息了……",
            ["ContentJP"] = "この田んぼをさっさと耕し終えれば、早く家に帰って休める……",
            ["DialogueId"] = 50107151,
            ["GUID"] = "7D702076",
            ["SpeakNpcId"] = 701246,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704146",
            },
        [50107152] = {
            ["Content"] = "听说最近西郊有人借着飘零人的名头活动，不知道是打什么鬼主意。",
            ["ContentJP"] = "最近、西郊で流れ者の名をかたって動き回ってる奴がいるって聞いたど、いったい何を企んでるんだろうね。",
            ["DialogueId"] = 50107152,
            ["GUID"] = "7D7020A0",
            ["SpeakNpcId"] = 701247,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704170",
            },
        [50107153] = {
            ["Content"] = "是小苏带回来的那位？模样俊俏，当真是位妙人~",
            ["ContentJP"] = "スーイーが連れてきたあの人かい？見た目も端正で、本当にすてきな人だね〜",
            ["DialogueId"] = 50107153,
            ["GUID"] = "7D7020CA",
            ["SpeakNpcId"] = 701249,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70419A",
            },
        [50107154] = {
            ["Content"] = "大哥，我们什么时候才能出山啊，天天待在这里太无聊了……",
            ["ContentJP"] = "お兄ちゃん、いつになったら山を出られるの？毎日すっごく退屈だよ……",
            ["DialogueId"] = 50107154,
            ["GUID"] = "7D7020F4",
            ["SpeakNpcId"] = 701250,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7041C4",
            },
        [50107155] = {
            ["Content"] = "哼！我早说过不要随便带人回来，不然山外山迟早会暴露出去！",
            ["ContentJP"] = "前にも言っただろ、勝手に人を連れてくるなって。山外山のことが遅かれ早かれバレてしまうぞ！",
            ["DialogueId"] = 50107155,
            ["GUID"] = "7D70211E",
            ["SpeakNpcId"] = 701252,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7041EE",
            },
        [50107156] = {
            ["Content"] = "机枢有什么好！听我的，剑拿着，咱俩练两手才是真的。",
            ["ContentJP"] = "機枢の何がいいんだよ！ほら、剣だ、二人で手合わせするほうがましだろ。",
            ["DialogueId"] = 50107156,
            ["GUID"] = "7D702148",
            ["SpeakNpcId"] = 701253,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704218",
            },
        [50107157] = {
            ["Content"] = "是……新面孔……好想……好想和新面孔说说话……",
            ["ContentJP"] = "あ……見慣れない顔……お話ししたい……",
            ["DialogueId"] = 50107157,
            ["GUID"] = "7D702172",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704242",
            },
        [50107158] = {
            ["Content"] = "打打打打打劫！要从此巷过，留下姓名来！",
            ["ContentJP"] = "天下御免の大泥棒、参上！……この路地を通りてぇなら、名を置いてきやがれ！",
            ["DialogueId"] = 50107158,
            ["GUID"] = "7D70219C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70426C",
            },
        [50107159] = {
            ["Content"] = "我好像有一个哥哥……还有一个妹妹……但他们现在都在哪……",
            ["ContentJP"] = "わたし、お兄ちゃんが一人……それに妹も一人いたのに……でも、今、二人ともどこにいるんだろう……",
            ["DialogueId"] = 50107159,
            ["GUID"] = "7D7021C6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D704296",
            },
        [50107201] = {
            ["Content"] = "我的钱袋子呢？",
            ["ContentJP"] = "えっ、嘘でしょ！",
            ["DialogueId"] = 50107201,
            ["GUID"] = "7D7028AA",
            ["SpeakNpcId"] = 701113,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028AA",
            },
        [50107202] = {
            ["Content"] = "定是那油嘴滑舌的小贩子偷的！",
            ["ContentJP"] = "あの怪しそうな行商人が盗んだに違いない！",
            ["DialogueId"] = 50107202,
            ["GUID"] = "7D7028D4",
            ["SpeakNpcId"] = 701114,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028D4",
            },
        [50107203] = {
            ["Content"] = "诶？怎么就是找不到呢？",
            ["ContentJP"] = "え？どうして見つからないんだろう？",
            ["DialogueId"] = 50107203,
            ["GUID"] = "7D7028FE",
            ["SpeakNpcId"] = 701115,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7028FE",
            },
        [50107204] = {
            ["Content"] = "我早跟你说了这街上有贼！",
            ["ContentJP"] = "だから言ったんだ、この街には泥棒がいるって！",
            ["DialogueId"] = 50107204,
            ["GUID"] = "7D702928",
            ["SpeakNpcId"] = 701116,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702928",
            },
        [50107205] = {
            ["Content"] = "博山香行周年店庆！",
            ["ContentJP"] = "博山香行（はくさんこうぎょう）はただいま周年記念セールを開催中です！",
            ["DialogueId"] = 50107205,
            ["GUID"] = "7D702952",
            ["SpeakNpcId"] = 701118,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702952",
            },
        [50107206] = {
            ["Content"] = "我对香料品质的要求很高……",
            ["ContentJP"] = "ひとつだけ知っておいてほしい",
            ["DialogueId"] = 50107206,
            ["GUID"] = "7D70297C",
            ["SpeakNpcId"] = 701119,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70297C",
            },
        [50107207] = {
            ["Content"] = "再来一批！",
            ["ContentJP"] = "いつもので。",
            ["DialogueId"] = 50107207,
            ["GUID"] = "7D7029A6",
            ["SpeakNpcId"] = 701121,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029A6",
            },
        [50107208] = {
            ["Content"] = "噫！好酸的果干！",
            ["ContentJP"] = "うっ、このドライフルーツ、酸っぱい！",
            ["DialogueId"] = 50107208,
            ["GUID"] = "7D7029D0",
            ["SpeakNpcId"] = 701122,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029D0",
            },
        [50107209] = {
            ["Content"] = "为什么没人来试试我做的糕点呢……",
            ["ContentJP"] = "どうして誰も私のお菓子を食べに来ないんだろう......",
            ["DialogueId"] = 50107209,
            ["GUID"] = "7D7029FA",
            ["SpeakNpcId"] = 701123,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7029FA",
            },
        [50107210] = {
            ["Content"] = "华胥特色小吃！",
            ["ContentJP"] = "華胥の名物ですよ！",
            ["DialogueId"] = 50107210,
            ["GUID"] = "7D702A24",
            ["SpeakNpcId"] = 701124,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A24",
            },
        [50107211] = {
            ["Content"] = "欢迎试吃品尝~",
            ["ContentJP"] = "よかったら味見してみてください～",
            ["DialogueId"] = 50107211,
            ["GUID"] = "7D702A4E",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A4E",
            },
        [50107212] = {
            ["Content"] = "东市啊，大变样咯！",
            ["ContentJP"] = "東市（ひがしのいち）も本当に、ずいぶん変わったわねぇ。",
            ["DialogueId"] = 50107212,
            ["GUID"] = "7D702A78",
            ["SpeakNpcId"] = 701125,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702A78",
            },
        [50107213] = {
            ["Content"] = "要不要来试试我们千绣阁里的成衣？",
            ["ContentJP"] = "よかったらご試着してみてくださいね。",
            ["DialogueId"] = 50107213,
            ["GUID"] = "7D702AA2",
            ["SpeakNpcId"] = 701127,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AA2",
            },
        [50107214] = {
            ["Content"] = "同福饭馆菜品上新……",
            ["ContentJP"] = "新メニューが登場！",
            ["DialogueId"] = 50107214,
            ["GUID"] = "7D702ACC",
            ["SpeakNpcId"] = 701128,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702ACC",
            },
        [50107215] = {
            ["Content"] = "香料做菜？",
            ["ContentJP"] = "香料の料理？",
            ["DialogueId"] = 50107215,
            ["GUID"] = "7D702AF6",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702AF6",
            },
        [50107216] = {
            ["Content"] = "同福饭馆的厨子发了疯！",
            ["ContentJP"] = "同福飯店のシェフ、ちょっとやりすぎじゃあない？",
            ["DialogueId"] = 50107216,
            ["GUID"] = "7D702B20",
            ["SpeakNpcId"] = 701129,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B20",
            },
        [50107217] = {
            ["Content"] = "可别忘了华胥美食的精髓是什么！",
            ["ContentJP"] = "華胥料理の真髄を忘れるとは！",
            ["DialogueId"] = 50107217,
            ["GUID"] = "7D702B4A",
            ["SpeakNpcId"] = 701130,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B4A",
            },
        [50107218] = {
            ["Content"] = "秀芳……不要离开我……",
            ["ContentJP"] = "……行かないでくれ……",
            ["DialogueId"] = 50107218,
            ["GUID"] = "7D702B74",
            ["SpeakNpcId"] = 701131,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B74",
            },
        [50107219] = {
            ["Content"] = "把翠屏雀搬来了皓京城？！",
            ["ContentJP"] = "スイヘイジャクをわざわざ皓京まで？！",
            ["DialogueId"] = 50107219,
            ["GUID"] = "7D702B9E",
            ["SpeakNpcId"] = 701132,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702B9E",
            },
        [50107220] = {
            ["Content"] = "雀翎茗轩……",
            ["ContentJP"] = "ここかしら？",
            ["DialogueId"] = 50107220,
            ["GUID"] = "7D702BC8",
            ["SpeakNpcId"] = 701134,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BC8",
            },
        [50107221] = {
            ["Content"] = "东市雀翎茗轩开张！",
            ["ContentJP"] = "雀の茶屋、開店でーす！",
            ["DialogueId"] = 50107221,
            ["GUID"] = "7D702BF2",
            ["SpeakNpcId"] = 701258,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702BF2",
            },
        [50107222] = {
            ["Content"] = "呜呜……龙君不公啊！",
            ["ContentJP"] = "うう……白龍様、不公平です！",
            ["DialogueId"] = 50107222,
            ["GUID"] = "7D702C1C",
            ["SpeakNpcId"] = 701135,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C1C",
            },
        [50107223] = {
            ["Content"] = "游船游船，十文一趟。",
            ["ContentJP"] = "遊覧船に乗りたい方はいませんか？",
            ["DialogueId"] = 50107223,
            ["GUID"] = "7D702C46",
            ["SpeakNpcId"] = 701136,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C46",
            },
        [50107224] = {
            ["Content"] = "怎么看怎么觉得邪乎呢……",
            ["ContentJP"] = "どう見てもなんだか不気味だな……",
            ["DialogueId"] = 50107224,
            ["GUID"] = "7D702C70",
            ["SpeakNpcId"] = 701137,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C70",
            },
        [50107225] = {
            ["Content"] = "想当初咱这湖边多清净？",
            ["ContentJP"] = "昔はこの湖、ほんとに静かでのう。",
            ["DialogueId"] = 50107225,
            ["GUID"] = "7D702C9A",
            ["SpeakNpcId"] = 701138,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702C9A",
            },
        [50107226] = {
            ["Content"] = "若是能把这五禽戏练好……",
            ["ContentJP"] = "もしこの五禽戯（ごきんぎ）をうまく習得できれば……",
            ["DialogueId"] = 50107226,
            ["GUID"] = "7D702CC4",
            ["SpeakNpcId"] = 701139,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CC4",
            },
        [50107227] = {
            ["Content"] = "他们还真把那五禽戏当真了不成？",
            ["ContentJP"] = "まさか、あの五禽戯（ごきんぎ）を本気で信じてるのか？",
            ["DialogueId"] = 50107227,
            ["GUID"] = "7D702CEE",
            ["SpeakNpcId"] = 701141,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702CEE",
            },
        [50107228] = {
            ["Content"] = "呵欠……",
            ["ContentJP"] = "ふぁぁ……",
            ["DialogueId"] = 50107228,
            ["GUID"] = "7D702D18",
            ["SpeakNpcId"] = 701142,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D18",
            },
        [50107229] = {
            ["Content"] = "这皓京城还没有我说不成的媒！",
            ["ContentJP"] = "この皓京（こうけい）で、私が取り持てない縁談なんてないよ！",
            ["DialogueId"] = 50107229,
            ["GUID"] = "7D702D42",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D42",
            },
        [50107230] = {
            ["Content"] = "会不会……被他看出来了？",
            ["ContentJP"] = "彼に、見抜かれてしまわないかしら……？",
            ["DialogueId"] = 50107230,
            ["GUID"] = "7D702D6C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D6C",
            },
        [50107231] = {
            ["Content"] = "咱皓京人，除了吃就是喝，没别的~",
            ["ContentJP"] = "金ならいくらでもあるさ。足りないって思ったこと、一度もないな～",
            ["DialogueId"] = 50107231,
            ["GUID"] = "7D702D96",
            ["SpeakNpcId"] = 701143,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702D96",
            },
        [50107232] = {
            ["Content"] = "留心点别踩到路上的石子了！",
            ["ContentJP"] = "転ばないように気をつけなさいよ！",
            ["DialogueId"] = 50107232,
            ["GUID"] = "7D702DC0",
            ["SpeakNpcId"] = 701145,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DC0",
            },
        [50107233] = {
            ["Content"] = "什么？涨了这么多？",
            ["ContentJP"] = "えっ、こんなに値上がりしたのか！？",
            ["DialogueId"] = 50107233,
            ["GUID"] = "7D702DEA",
            ["SpeakNpcId"] = 701146,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702DEA",
            },
        [50107234] = {
            ["Content"] = "父亲想必在天上也是不愿看见娘亲落泪的。",
            ["ContentJP"] = "父上はきっと、母上が涙を流しているところを見たくないと思います。",
            ["DialogueId"] = 50107234,
            ["GUID"] = "7D702E14",
            ["SpeakNpcId"] = 701148,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E14",
            },
        [50107235] = {
            ["Content"] = "现在都什么年代了……",
            ["ContentJP"] = "もういい加減にしてくださいよ……",
            ["DialogueId"] = 50107235,
            ["GUID"] = "7D702E3E",
            ["SpeakNpcId"] = 701149,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E3E",
            },
        [50107236] = {
            ["Content"] = "这杯，我敬你！",
            ["ContentJP"] = "この一杯、君に捧げる！",
            ["DialogueId"] = 50107236,
            ["GUID"] = "7D702E68",
            ["SpeakNpcId"] = 701150,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E68",
            },
        [50107237] = {
            ["Content"] = "草木深胡同……是在这里？",
            ["ContentJP"] = "草木通り（くさきとおり）って……ここかしら？",
            ["DialogueId"] = 50107237,
            ["GUID"] = "7D702E92",
            ["SpeakNpcId"] = 701151,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702E92",
            },
        [50107238] = {
            ["Content"] = "你说那家私房菜？",
            ["ContentJP"] = "あの料理店のことかい？",
            ["DialogueId"] = 50107238,
            ["GUID"] = "7D702EBC",
            ["SpeakNpcId"] = 701152,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EBC",
            },
        [50107239] = {
            ["Content"] = "这小巷深处竟藏着这庖厨圣地！",
            ["ContentJP"] = "ここに料理の聖地があったなんて！",
            ["DialogueId"] = 50107239,
            ["GUID"] = "7D702EE6",
            ["SpeakNpcId"] = 701153,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702EE6",
            },
        [50107240] = {
            ["Content"] = "老张啊，你那只八哥……",
            ["ContentJP"] = "そこのハッカチョウが今日……",
            ["DialogueId"] = 50107240,
            ["GUID"] = "7D702F10",
            ["SpeakNpcId"] = 701154,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F10",
            },
        [50107241] = {
            ["Content"] = "凡夫俗子溜凡羽俗鸟！",
            ["ContentJP"] = "くだらん。",
            ["DialogueId"] = 50107241,
            ["GUID"] = "7D702F3A",
            ["SpeakNpcId"] = 701155,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F3A",
            },
        [50107242] = {
            ["Content"] = "老友，这局棋，你该怎么破？",
            ["ContentJP"] = "さて友よ、どうする？",
            ["DialogueId"] = 50107242,
            ["GUID"] = "7D702F64",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F64",
            },
        [50107243] = {
            ["Content"] = "在家里聚上一聚，打打骨牌？",
            ["ContentJP"] = "うちで麻雀でもやろうか？",
            ["DialogueId"] = 50107243,
            ["GUID"] = "7D702F8E",
            ["SpeakNpcId"] = 701157,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702F8E",
            },
        [50107244] = {
            ["Content"] = "给我回去复习功课！",
            ["ContentJP"] = "さっさと戻って勉強しなさい！",
            ["DialogueId"] = 50107244,
            ["GUID"] = "7D702FB8",
            ["SpeakNpcId"] = 701158,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FB8",
            },
        [50107245] = {
            ["Content"] = "今天翻墙出来被阿娘逮到了……",
            ["ContentJP"] = "オカンに見つかっちゃった……",
            ["DialogueId"] = 50107245,
            ["GUID"] = "7D702FE2",
            ["SpeakNpcId"] = 701160,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D702FE2",
            },
        [50107246] = {
            ["Content"] = "无由生马上要出来抓你们咯？",
            ["ContentJP"] = "もういいかい？",
            ["DialogueId"] = 50107246,
            ["GUID"] = "7D70300C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70300C",
            },
        [50107247] = {
            ["Content"] = "真是忙到头晕眼花。",
            ["ContentJP"] = "まったく、忙しすぎて目が回りそうだ。",
            ["DialogueId"] = 50107247,
            ["GUID"] = "7D703036",
            ["SpeakNpcId"] = 701162,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703036",
            },
        [50107248] = {
            ["Content"] = "恐一蹬腿就要去往虞泉了！",
            ["ContentJP"] = "虞泉（ぐせん）行きになりそうだ！",
            ["DialogueId"] = 50107248,
            ["GUID"] = "7D703060",
            ["SpeakNpcId"] = 701163,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703060",
            },
        [50107249] = {
            ["Content"] = "奉香大典意味着什么？",
            ["ContentJP"] = "奉香の儀って何かって？",
            ["DialogueId"] = 50107249,
            ["GUID"] = "7D70308A",
            ["SpeakNpcId"] = 701164,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70308A",
            },
        [50107250] = {
            ["Content"] = "莫非是填错了？",
            ["ContentJP"] = "もしかして、入力ミス？",
            ["DialogueId"] = 50107250,
            ["GUID"] = "7D7030B4",
            ["SpeakNpcId"] = 701165,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030B4",
            },
        [50107251] = {
            ["Content"] = "真是难得的清闲啊~",
            ["ContentJP"] = "最近は、平和でのんびりだな～",
            ["DialogueId"] = 50107251,
            ["GUID"] = "7D7030DE",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7030DE",
            },
        [50107252] = {
            ["Content"] = "下次记得早些来泉通司……",
            ["ContentJP"] = "次は早めに来てください。",
            ["DialogueId"] = 50107252,
            ["GUID"] = "7D703108",
            ["SpeakNpcId"] = 701166,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703108",
            },
        [50107253] = {
            ["Content"] = "祀香阁今年额外申请了一笔经费。",
            ["ContentJP"] = "なぜ追加で予算を申請したのですか？",
            ["DialogueId"] = 50107253,
            ["GUID"] = "7D703132",
            ["SpeakNpcId"] = 701167,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703132",
            },
        [50107254] = {
            ["Content"] = "搭台子，修香炉……",
            ["ContentJP"] = "いつ予算が下りるんだ？",
            ["DialogueId"] = 50107254,
            ["GUID"] = "7D70315C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70315C",
            },
        [50107255] = {
            ["Content"] = "鬼鬼祟祟的，看起来不像什么好人。",
            ["ContentJP"] = "こそこそしてて、どう見ても良い人には見えないな。",
            ["DialogueId"] = 50107255,
            ["GUID"] = "7D703186",
            ["SpeakNpcId"] = 701168,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703186",
            },
        [50107256] = {
            ["Content"] = "为何来来回回都在提西郊？",
            ["ContentJP"] = "なんで全部西郊のことばかりなんだ？",
            ["DialogueId"] = 50107256,
            ["GUID"] = "7D7031B0",
            ["SpeakNpcId"] = 701169,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031B0",
            },
        [50107257] = {
            ["Content"] = "快给我来碗茶水！",
            ["ContentJP"] = "早くお茶ちょうだい！",
            ["DialogueId"] = 50107257,
            ["GUID"] = "7D7031DA",
            ["SpeakNpcId"] = 701170,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7031DA",
            },
        [50107258] = {
            ["Content"] = "不是货物？那是……翠屏雀？！",
            ["ContentJP"] = "荷物じゃなく？……スイヘイジャクをなくしたの？！",
            ["DialogueId"] = 50107258,
            ["GUID"] = "7D703204",
            ["SpeakNpcId"] = 701171,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703204",
            },
        [50107259] = {
            ["Content"] = "它到底是怎么跑出去的呢？",
            ["ContentJP"] = "一体どうやって外に出ちゃったんだろう……？",
            ["DialogueId"] = 50107259,
            ["GUID"] = "7D70322E",
            ["SpeakNpcId"] = 701172,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70322E",
            },
        [50107260] = {
            ["Content"] = "一切努力都付之东流了……",
            ["ContentJP"] = "見つからない……もう終わりだ……",
            ["DialogueId"] = 50107260,
            ["GUID"] = "7D703258",
            ["SpeakNpcId"] = 701173,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703258",
            },
        [50107261] = {
            ["Content"] = "已经找到一只了？",
            ["ContentJP"] = "もう一羽見つかったの？",
            ["DialogueId"] = 50107261,
            ["GUID"] = "7D703282",
            ["SpeakNpcId"] = 701174,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703282",
            },
        [50107262] = {
            ["Content"] = "咱们的绣品在皓京城里很受欢迎呢~",
            ["ContentJP"] = "うちの刺繍、皓京で本当に人気ですな～",
            ["DialogueId"] = 50107262,
            ["GUID"] = "7D7032AC",
            ["SpeakNpcId"] = 701175,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032AC",
            },
        [50107263] = {
            ["Content"] = "甜果只有百分之三损毁？",
            ["ContentJP"] = "ロス率はわずか3％？",
            ["DialogueId"] = 50107263,
            ["GUID"] = "7D7032D6",
            ["SpeakNpcId"] = 701176,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7032D6",
            },
        [50107264] = {
            ["Content"] = "一点新意也没有。",
            ["ContentJP"] = "ワンパターンだよこれ",
            ["DialogueId"] = 50107264,
            ["GUID"] = "7D703300",
            ["SpeakNpcId"] = 701177,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703300",
            },
        [50107265] = {
            ["Content"] = "现在呢就已经到了咱们皓京……",
            ["ContentJP"] = "みなさん、こっちですよ～",
            ["DialogueId"] = 50107265,
            ["GUID"] = "7D70332A",
            ["SpeakNpcId"] = 701178,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70332A",
            },
        [50107266] = {
            ["Content"] = "三百九十九？！",
            ["ContentJP"] = "あらまあ！",
            ["DialogueId"] = 50107266,
            ["GUID"] = "7D703354",
            ["SpeakNpcId"] = 701179,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703354",
            },
        [50107267] = {
            ["Content"] = "恁大一个皓京城！",
            ["ContentJP"] = "おいらこんな町見だごとぁねえ！",
            ["DialogueId"] = 50107267,
            ["GUID"] = "7D70337E",
            ["SpeakNpcId"] = 701180,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70337E",
            },
        [50107268] = {
            ["Content"] = "别靠过来！",
            ["ContentJP"] = "近づかないで！",
            ["DialogueId"] = 50107268,
            ["GUID"] = "7D7033A8",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033A8",
            },
        [50107269] = {
            ["Content"] = "水龙车我先带走了。",
            ["ContentJP"] = "水龍車は先に持っていく。",
            ["DialogueId"] = 50107269,
            ["GUID"] = "7D7033D2",
            ["SpeakNpcId"] = 701181,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033D2",
            },
        [50107270] = {
            ["Content"] = "太麻烦他们了。",
            ["ContentJP"] = "ほんと、手間をかけさせちゃったな。",
            ["DialogueId"] = 50107270,
            ["GUID"] = "7D7033FC",
            ["SpeakNpcId"] = 701182,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7033FC",
            },
        [50107271] = {
            ["Content"] = "来回拉扯不嫌麻烦吗？",
            ["ContentJP"] = "面倒くさくないのかねぇ？",
            ["DialogueId"] = 50107271,
            ["GUID"] = "7D703426",
            ["SpeakNpcId"] = 701183,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703426",
            },
        [50107272] = {
            ["Content"] = "凌波疾步！",
            ["ContentJP"] = "奥義「水蜘蛛の術」！",
            ["DialogueId"] = 50107272,
            ["GUID"] = "7D703450",
            ["SpeakNpcId"] = 701184,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703450",
            },
        [50107273] = {
            ["Content"] = "疯狂长苔，转动都费劲……",
            ["ContentJP"] = "回すのもひと苦労じゃ……",
            ["DialogueId"] = 50107273,
            ["GUID"] = "7D70347A",
            ["SpeakNpcId"] = 701185,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70347A",
            },
        [50107274] = {
            ["Content"] = "怎会有这多事端？",
            ["ContentJP"] = "こんな面倒なことにはならなかったのに。",
            ["DialogueId"] = 50107274,
            ["GUID"] = "7D7034A4",
            ["SpeakNpcId"] = 701186,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034A4",
            },
        [50107275] = {
            ["Content"] = "明法、公心、勤谨。",
            ["ContentJP"] = "明法、公心、勤勉。",
            ["DialogueId"] = 50107275,
            ["GUID"] = "7D7034CE",
            ["SpeakNpcId"] = 701187,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034CE",
            },
        [50107276] = {
            ["Content"] = "直吵得人不得安睡！",
            ["ContentJP"] = "まったく寝られない！",
            ["DialogueId"] = 50107276,
            ["GUID"] = "7D7034F8",
            ["SpeakNpcId"] = 701188,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7034F8",
            },
        [50107277] = {
            ["Content"] = "游船游船，十文一趟。",
            ["ContentJP"] = "遊覧船に乗りたい方はいませんか？",
            ["DialogueId"] = 50107277,
            ["GUID"] = "7D703522",
            ["SpeakNpcId"] = 701189,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703522",
            },
        [50107278] = {
            ["Content"] = "我查一下刚买的《华胥问候语录大全》。",
            ["ContentJP"] = "ちょ……ちょっと待ってください……",
            ["DialogueId"] = 50107278,
            ["GUID"] = "7D70354C",
            ["SpeakNpcId"] = 701190,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70354C",
            },
        [50107279] = {
            ["Content"] = "晚上做了什么好吃的？",
            ["ContentJP"] = "今夜は何かおいしいものを作ったのかい？",
            ["DialogueId"] = 50107279,
            ["GUID"] = "7D703576",
            ["SpeakNpcId"] = 701191,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703576",
            },
        [50107280] = {
            ["Content"] = "铁柱呢？铁柱为何不在？",
            ["ContentJP"] = "テッチュウは？どこへ行ってしもうたのだ？",
            ["DialogueId"] = 50107280,
            ["GUID"] = "7D7035A0",
            ["SpeakNpcId"] = 701192,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035A0",
            },
        [50107281] = {
            ["Content"] = "灯谜会，待君赏玩！",
            ["ContentJP"] = "お楽しみをお待ちしています！",
            ["DialogueId"] = 50107281,
            ["GUID"] = "7D7035CA",
            ["SpeakNpcId"] = 701193,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035CA",
            },
        [50107282] = {
            ["Content"] = "妈妈我到皓京了……",
            ["ContentJP"] = "ママ、俺、皓京に着いたよ……",
            ["DialogueId"] = 50107282,
            ["GUID"] = "7D7035F4",
            ["SpeakNpcId"] = 701194,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7035F4",
            },
        [50107283] = {
            ["Content"] = "这里面不能进去吗？",
            ["ContentJP"] = "ここ、中に入れないのか？",
            ["DialogueId"] = 50107283,
            ["GUID"] = "7D70361E",
            ["SpeakNpcId"] = 701195,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70361E",
            },
        [50107284] = {
            ["Content"] = "会看到白龙神君在云间遨游。",
            ["ContentJP"] = "ほら見て！",
            ["DialogueId"] = 50107284,
            ["GUID"] = "7D703648",
            ["SpeakNpcId"] = 701196,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703648",
            },
        [50107285] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报。",
            ["ContentJP"] = "皓京特ダネニュース～",
            ["DialogueId"] = 50107285,
            ["GUID"] = "7D703672",
            ["SpeakNpcId"] = 701198,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703672",
            },
        [50107286] = {
            ["Content"] = "凑在一起为什么完全看不懂……",
            ["ContentJP"] = "どうして全然読めないんだろう……",
            ["DialogueId"] = 50107286,
            ["GUID"] = "7D70369C",
            ["SpeakNpcId"] = 701199,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70369C",
            },
        [50107287] = {
            ["Content"] = "主要的是感受当地的氛围，您说对不对？",
            ["ContentJP"] = "一番大事なのはその土地の雰囲気を感じることだ、そう思わんか？",
            ["DialogueId"] = 50107287,
            ["GUID"] = "7D7036C6",
            ["SpeakNpcId"] = 701200,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036C6",
            },
        [50107288] = {
            ["Content"] = "退一万步说……",
            ["ContentJP"] = "やっぱり適切じゃないですよね……",
            ["DialogueId"] = 50107288,
            ["GUID"] = "7D7036F0",
            ["SpeakNpcId"] = 701201,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7036F0",
            },
        [50107289] = {
            ["Content"] = "直接推着车撞了过来……",
            ["ContentJP"] = "いきなり車押してぶつかってきたんだ。",
            ["DialogueId"] = 50107289,
            ["GUID"] = "7D70371A",
            ["SpeakNpcId"] = 701202,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70371A",
            },
        [50107290] = {
            ["Content"] = "天地为共生，万物与我一……",
            ["ContentJP"] = "天地は共に生き、万物は我と一つ……",
            ["DialogueId"] = 50107290,
            ["GUID"] = "7D703744",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703744",
            },
        [50107291] = {
            ["Content"] = "为人在世……",
            ["ContentJP"] = "世の中に生きる者として……",
            ["DialogueId"] = 50107291,
            ["GUID"] = "7D70376E",
            ["SpeakNpcId"] = 701203,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70376E",
            },
        [50107292] = {
            ["Content"] = "曾在学院听竹溪先生传授最后一课。",
            ["ContentJP"] = "竹渓先生の最後の授業を聞いたことがあるのじゃ。",
            ["DialogueId"] = 50107292,
            ["GUID"] = "7D703798",
            ["SpeakNpcId"] = 701204,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703798",
            },
        [50107293] = {
            ["Content"] = "吵死了……",
            ["ContentJP"] = "うるさすぎる……",
            ["DialogueId"] = 50107293,
            ["GUID"] = "7D7037C2",
            ["SpeakNpcId"] = 701205,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037C2",
            },
        [50107294] = {
            ["Content"] = "所谓理一……",
            ["ContentJP"] = "いわゆる「理一（りいち）」とは……",
            ["DialogueId"] = 50107294,
            ["GUID"] = "7D7037EC",
            ["SpeakNpcId"] = 701206,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7037EC",
            },
        [50107295] = {
            ["Content"] = "五味万殊，而大同于美。",
            ["ContentJP"] = "五味は万殊（ばんしゅ）なれど美味に同じ……",
            ["DialogueId"] = 50107295,
            ["GUID"] = "7D703816",
            ["SpeakNpcId"] = 701207,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703816",
            },
        [50107296] = {
            ["Content"] = "所以理一定是在前面的！",
            ["ContentJP"] = "だから道理は、必ず先にあるのだ！",
            ["DialogueId"] = 50107296,
            ["GUID"] = "7D703840",
            ["SpeakNpcId"] = 701208,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703840",
            },
        [50107297] = {
            ["Content"] = "今天该轮到你执勤了吧？",
            ["ContentJP"] = "今日はあなたの当番でしょう？",
            ["DialogueId"] = 50107297,
            ["GUID"] = "7D70386A",
            ["SpeakNpcId"] = 701209,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70386A",
            },
        [50107298] = {
            ["Content"] = "放假你们都去哪玩？",
            ["ContentJP"] = "みんなどこ行くの？",
            ["DialogueId"] = 50107298,
            ["GUID"] = "7D703894",
            ["SpeakNpcId"] = 701210,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703894",
            },
        [50107299] = {
            ["Content"] = "蹴球赛咱们队还差一人！",
            ["ContentJP"] = "うちのチームはあと一人足りない。",
            ["DialogueId"] = 50107299,
            ["GUID"] = "7D7038BE",
            ["SpeakNpcId"] = 701211,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038BE",
            },
        [50107300] = {
            ["Content"] = "可这又还能往哪里扩呢？",
            ["ContentJP"] = "拡張できる場所なんてないな。",
            ["DialogueId"] = 50107300,
            ["GUID"] = "7D7038E8",
            ["SpeakNpcId"] = 701212,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7038E8",
            },
        [50107301] = {
            ["Content"] = "是了，来年开春便要递上辞函……",
            ["ContentJP"] = "そうだな、来年の春には辞表を出すつもりだ。",
            ["DialogueId"] = 50107301,
            ["GUID"] = "7D703912",
            ["SpeakNpcId"] = 701213,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703912",
            },
        [50107302] = {
            ["Content"] = "为何飘零人的行为不能算是一种独特的方式？",
            ["ContentJP"] = "なぜ流れ者の行いは認められないのだろう？",
            ["DialogueId"] = 50107302,
            ["GUID"] = "7D70393C",
            ["SpeakNpcId"] = 701214,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D70393C",
            },
        [50107303] = {
            ["Content"] = "今天的辩题有趣！",
            ["ContentJP"] = "今日の討論テーマは面白いな。",
            ["DialogueId"] = 50107303,
            ["GUID"] = "7D703966",
            ["SpeakNpcId"] = 701215,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703966",
            },
        [50107304] = {
            ["Content"] = "有这闲工夫，不如多读些书！",
            ["ContentJP"] = "そんなことしてる暇があるなら、もっと本を読め！",
            ["DialogueId"] = 50107304,
            ["GUID"] = "7D703990",
            ["SpeakNpcId"] = 701216,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703990",
            },
        [50107305] = {
            ["Content"] = "椒兰村的香料自然是地道。",
            ["ContentJP"] = "やっぱり、椒蘭村（しょうらんむら）の香料は絶品だわ。",
            ["DialogueId"] = 50107305,
            ["GUID"] = "7D7039BA",
            ["SpeakNpcId"] = 701217,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039BA",
            },
        [50107306] = {
            ["Content"] = "鄙人自氤园而来，与他有约。",
            ["ContentJP"] = "私は芳青園（ほうせいえん）より参りました、彼とお約束がございます。",
            ["DialogueId"] = 50107306,
            ["GUID"] = "7D7039E4",
            ["SpeakNpcId"] = 701219,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D7039E4",
            },
        [50107307] = {
            ["Content"] = "你哥又回烟津渡了？",
            ["ContentJP"] = "兄さんはまた煙津渡（えんしんと）に戻ったの？",
            ["DialogueId"] = 50107307,
            ["GUID"] = "7D703A0E",
            ["SpeakNpcId"] = 701220,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A0E",
            },
        [50107308] = {
            ["Content"] = "愿家父身体健康，百病不侵。",
            ["ContentJP"] = "父が無病息災（むびょうそくさい）で過ごせますように……",
            ["DialogueId"] = 50107308,
            ["GUID"] = "7D703A38",
            ["SpeakNpcId"] = 701221,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A38",
            },
        [50107309] = {
            ["Content"] = "唔……我的愿望是，长高一点！",
            ["ContentJP"] = "わたしのお願いは、ちょっとだけ背が伸びることよ。",
            ["DialogueId"] = 50107309,
            ["GUID"] = "7D703A62",
            ["SpeakNpcId"] = 701222,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A62",
            },
        [50107310] = {
            ["Content"] = "香官跟我说的。",
            ["ContentJP"] = "香官もそう言ってたのよ。",
            ["DialogueId"] = 50107310,
            ["GUID"] = "7D703A8C",
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703A8C",
            },
        [50107311] = {
            ["Content"] = "今年祀香阁怎得没动静了？",
            ["ContentJP"] = "今年はどうしてないのじゃろう？",
            ["DialogueId"] = 50107311,
            ["GUID"] = "7D703AB6",
            ["SpeakNpcId"] = 701223,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AB6",
            },
        [50107312] = {
            ["Content"] = "尤其是中心广场水上的那个炉子！",
            ["ContentJP"] = "絶対に見落とししないで。",
            ["DialogueId"] = 50107312,
            ["GUID"] = "7D703AE0",
            ["SpeakNpcId"] = 701224,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703AE0",
            },
        [50107313] = {
            ["Content"] = "难不成真是我思维迟缓？",
            ["ContentJP"] = "わしの思考が鈍くなったのかのう？",
            ["DialogueId"] = 50107313,
            ["GUID"] = "7D703B0A",
            ["SpeakNpcId"] = 701225,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B0A",
            },
        [50107314] = {
            ["Content"] = "不同的香方自然作用也不相同。",
            ["ContentJP"] = "薫物（たきもの）が違えば、当然作用も異なる。",
            ["DialogueId"] = 50107314,
            ["GUID"] = "7D703B34",
            ["SpeakNpcId"] = 701226,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B34",
            },
        [50107315] = {
            ["Content"] = "祀香阁今年招了一位皎皎之民！",
            ["ContentJP"] = "なんでも、ルーナ族だそうよ！",
            ["DialogueId"] = 50107315,
            ["GUID"] = "7D703B5E",
            ["SpeakNpcId"] = 701227,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B5E",
            },
        [50107316] = {
            ["Content"] = "那矮冬瓜大头鱼一样的家伙……",
            ["ContentJP"] = "ルーナ族だって？！",
            ["DialogueId"] = 50107316,
            ["GUID"] = "7D703B88",
            ["SpeakNpcId"] = 701228,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703B88",
            },
        [50107317] = {
            ["Content"] = "去泉通司问过了吗？",
            ["ContentJP"] = "泉通司にはもう聞いたか？",
            ["DialogueId"] = 50107317,
            ["GUID"] = "7D703BB2",
            ["SpeakNpcId"] = 701229,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BB2",
            },
        [50107318] = {
            ["Content"] = "几番叨扰，自己都有点过意不去了。",
            ["ContentJP"] = "何度もお邪魔してしまって、申し訳ございません。",
            ["DialogueId"] = 50107318,
            ["GUID"] = "7D703BDC",
            ["SpeakNpcId"] = 701230,
            ["VoiceName"] = "voice$ch$env$Ver0102$7D703BDC",
            },
        [50107319] = {
            ["Content"] = "你准备回家？",
