            ["SpeakNpcId"] = 700020,
            },
        [51000201] = {
            ["Content"] = "希望今晚的奶油蘑菇浓汤能让夫人舒服一点儿……啊呀？你回来了，孩子。",
            ["ContentJP"] = "今夜はマッシュルームのクリームスープで、どうか奥様の心が少しでも安らぎますように……あら？お帰りなさい、おチビさん。",
            ["DialogueId"] = 51000201,
            ["GUID"] = "7FAC747A",
            ["NextDialogue"] = 51000202,
            ["SpeakNpcId"] = 700020,
            },
        [51000202] = {
            ["Content"] = "（老妇人用她的大手重重地拍了拍你的脑袋，又捏了捏你的脸。她过分的热情甚至让你感到有些手足无措。还好，她看起来已经从悲伤中缓和了不少。）",
            ["ContentJP"] = "（老婦人は大きな手であなたの頭を何度もポンポンとなでたり、頬をつまんだ。過剰な反応があなたを困惑させる）",
            ["DialogueId"] = 51000202,
            ["GUID"] = "7FAC74A4",
            ["NextDialogue"] = 51000203,
            },
        [51000203] = {
            ["Content"] = "来，喝了这碗奶油蘑菇汤！婶婶这是丹流城带来的手艺，你肯定没见识过。",
            ["ContentJP"] = "おいで！スープをお飲みなさいな！おばさんはレッドバリー城で腕を振るっていたからね、経験したことないおいしさでホッペがとろけちゃうかもしれないわよ～？",
            ["DialogueId"] = 51000203,
            ["GUID"] = "7FAC74CE",
            ["NextDialogue"] = 51000204,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51000204] = {
            ["Content"] = "（老妇人不由分说，将一碗热汤端到你面前，你总觉得下一秒，她就要掰着你的脑袋强行灌下去了——）",
            ["ContentJP"] = "（老婦人は有無を言わさず熱々のスープをあなたの前に差し出す。次の瞬間には顔をガッチリとつかまれて、無理やりにでも飲まされそうだ――）",
            ["DialogueId"] = 51000204,
            ["GUID"] = "7FAC74F8",
            },
        [51000205] = {
            ["Content"] = "（香浓的菌类汤汁伴随着奶油的甘甜温润了你的喉咙，你感到异常舒适。）",
            ["ContentJP"] = "（コクのあるキノコの出汁とクリームの甘みで喉が優しく温まる。とてもおいしい）",
            ["DialogueId"] = 51000205,
            ["GUID"] = "7FAC7522",
            ["NextDialogue"] = 51000206,
            },
        [51000206] = {
            ["Content"] = "怎么样。莎莉婶婶是不会骗你的，哈哈。",
            ["ContentJP"] = "ね、サリーおばさんはあんたを騙したりしないわよ、ふふふ。",
            ["DialogueId"] = 51000206,
            ["GUID"] = "7FAC754C",
            ["NextDialogue"] = 51000208,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51000207] = {
            ["Content"] = "不懂事的小鬼！不知道什么是好东西。",
            ["ContentJP"] = "何もそんなに嫌がらなくたって！わかってくれない子だね本当！",
            ["DialogueId"] = 51000207,
            ["GUID"] = "7FAC7576",
            ["NextDialogue"] = 51000208,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51000208] = {
            ["Content"] = "夫人还是个年轻姑娘的时候就开始喝我煮的汤，已经快四十年了啦。",
            ["ContentJP"] = "私がお世話をする奥様なんてお嬢さんって年頃からずっとスープを飲んでくれていたわ。もう40年近くずっとよ？",
            ["DialogueId"] = 51000208,
            ["GUID"] = "7FAC75A0",
            ["NextDialogue"] = 51000209,
            ["SpeakNpcId"] = 700020,
            },
        [51000209] = {
            ["Content"] = "……唉，夫人！也不知道她那病还能不能好。",
            ["ContentJP"] = "だけども……あぁ、奥様！奥様のご病気は治るのかしらねぇ……",
            ["DialogueId"] = 51000209,
            ["GUID"] = "7FAC75CA",
            ["NextDialogue"] = 51000210,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51000210] = {
            ["Content"] = "（老妇人眼睛里洋溢的笑容逐渐消退，取而代之的是闪烁的泪花——刚刚的热情，似乎只是她的强颜欢笑。）",
            ["ContentJP"] = "（老婦人の顔からほほ笑みが薄れ、代わりに一筋の涙が頬を伝う）",
            ["DialogueId"] = 51000210,
            ["GUID"] = "7FAC75F4",
            ["TalkActionId"] = {
                [1] = "700020:Sigh_End",
                },
            },
        [51000301] = {
            ["Content"] = "到底去了哪里啊……",
            ["ContentJP"] = "いったいどこに行ってしまわれたの……",
            ["DialogueId"] = 51000301,
            ["GUID"] = "7FAC84E2",
            ["NextDialogue"] = 51000302,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Sigh_Start",
                },
            },
        [51000302] = {
            ["Content"] = "（老妇人悲伤的目光停驻在远方，对突如其来的搭话充耳不闻。）",
            ["ContentJP"] = "（老婦人が悲しい目で遠くを見つめている。話しかけても反応がない）",
            ["DialogueId"] = 51000302,
            ["GUID"] = "7FAC850C",
            ["NextOptions"] = {
                [1] = 510003021,
                [2] = 510003022,
                [3] = 510003023,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000303] = {
            ["Content"] = "（她的衣服有些旧，但布料精致，做工考究。或许，她来自一个富有的家庭。）",
            ["ContentJP"] = "（彼女の服は少し古いものだが、生地が上質でとても丁寧に仕立てられている。恐らく裕福な家庭で育ったのだろう）",
            ["DialogueId"] = 51000303,
            ["GUID"] = "7FAC8536",
            ["NextOptions"] = {
                [1] = 510003051,
                [2] = 510003053,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000304] = {
            ["Content"] = "（她始终盯着城外，似乎在等待什么人归来。）",
            ["ContentJP"] = "（彼女はじっと城外を見つめている。誰かの帰りを待っているのだろう）",
            ["DialogueId"] = 51000304,
            ["GUID"] = "7FAC8560",
            ["NextOptions"] = {
                [1] = 510003051,
                [2] = 510003053,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000305] = {
            ["Content"] = "（她衰老的双眼溢满悲伤，似乎经历了一场漫长无望的等待。）",
            ["ContentJP"] = "（老いた目は悲しみに満ちあふれている。何か望みを叶えられないまま、長い時を過ごしたのだろう）",
            ["DialogueId"] = 51000305,
            ["GUID"] = "7FAC858A",
            ["NextOptions"] = {
                [1] = 510003051,
                [2] = 510003053,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000306] = {
            ["Content"] = "（老妇人回望了你一眼，但又转过头去——她似乎并不关心你在说什么。）",
            ["ContentJP"] = "（老婦人は振り返ってあなたをチラッと見たが、すぐさま顔を背けてしまった。あなたが話しかけても上の空だ）",
            ["DialogueId"] = 51000306,
            ["GUID"] = "7FAC85B4",
            },
        [51000307] = {
            ["Content"] = "……你是……",
            ["ContentJP"] = "あなた……は……",
            ["DialogueId"] = 51000307,
            ["GUID"] = "7FAC85DE",
            ["NextDialogue"] = 51000308,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Sigh_End",
                },
            },
        [51000308] = {
            ["Content"] = "我之前没见过你。你是从附近村镇来的吗？",
            ["ContentJP"] = "初めまして、でよろしくて？近くの街からいらっしゃったのかしら？",
            ["DialogueId"] = 51000308,
            ["GUID"] = "7FAC8608",
            ["NextDialogue"] = 51000309,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Explain02_Start",
                },
            },
        [51000309] = {
            ["Content"] = "你有没有见过一个叫哈默尔·狄金森的卡戎男人？他生在冰湖城，浅棕色头发，十八九岁，喜欢穿……不，现在的话，应该是和我差不多的年纪。",
            ["ContentJP"] = "ハーメル・ディキンソンという名のカロン族の男性をご存じありませんか？アイスレイク城の生まれで、髪は薄茶色で、18、9歳ぐらいで、いつも着ていた服は……いえ、今はもう、年齢は私と同じぐらいです。",
            ["DialogueId"] = 51000309,
            ["GUID"] = "7FAC8632",
            ["NextDialogue"] = 51000310,
            ["SpeakNpcId"] = 700019,
            },
        [51000310] = {
            ["Content"] = "我离开冰湖城已经有四十年了，也是从那时起，我就失去了和他的联系。这次回来，也没能打听到他的消息。",
            ["ContentJP"] = "アイスレイク城を離れて彼と連絡が取れなくなって、もう40年が過ぎました。最近やっとこの街に戻ったのですが、誰一人として彼を知る者はおらず……",
            ["DialogueId"] = 51000310,
            ["GUID"] = "7FAC865C",
            ["NextDialogue"] = 51000311,
            ["SpeakNpcId"] = 700019,
            },
        [51000311] = {
            ["Content"] = "他在冰湖城出生、长大，我想，就算他不在城里了，应该也不会走得太远。年轻人，你有没有在哪里见过他？",
            ["ContentJP"] = "彼はアイスレイク城で生まれ育ったのですから、街を離れたとしてもそう遠くには行かないと思うのです。お若い方、どこかで彼にお会いになったりは？",
            ["DialogueId"] = 51000311,
            ["GUID"] = "7FAC8686",
            ["NextOptions"] = {
                [1] = 510003111,
                },
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000312] = {
            ["Content"] = "好吧……",
            ["ContentJP"] = "さようですか……",
            ["DialogueId"] = 51000312,
            ["GUID"] = "7FAC86B0",
            ["NextDialogue"] = 51000313,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Agree",
                },
            },
        [51000313] = {
            ["Content"] = "如果你以后见到他，能不能麻烦你转告他一句话？",
            ["ContentJP"] = "もし彼に会われる機会があれば、伝えてくださらない？",
            ["DialogueId"] = 51000313,
            ["GUID"] = "7FAC86DA",
            ["NextDialogue"] = 51000314,
            ["SpeakNpcId"] = 700019,
            },
        [51000314] = {
            ["Content"] = "“希琳回到了冰湖城。她一直在等你，等你给她一个迟到四十年的理由。”",
            ["ContentJP"] = "「セリーヌがアイスレイク城に戻ってきた。彼女はあなたをずっと待っている。40年も遅れている理由を教えてほしいと」",
            ["DialogueId"] = 51000314,
            ["GUID"] = "7FAC8704",
            ["NextDialogue"] = 51000315,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Explain01_Start",
                },
            },
        [51000315] = {
            ["Content"] = "要是明年见到他，就问他为什么迟到了四十一年，后年的话，就是四十二年……我可是一直在数着呢。",
            ["ContentJP"] = "もし来年彼にお会いになったら41年も遅れている理由を、再来年ならば42年……私はずっと指折り数えて待ち続けます。",
            ["DialogueId"] = 51000315,
            ["GUID"] = "7FAC872E",
            ["NextDialogue"] = 51000316,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Explain01_End",
                },
            },
        [51000316] = {
            ["Content"] = "（希琳夫人看起来无比困扰，想来这位就是莎莉口中的夫人，应该有什么办法可以帮到她们。）",
            ["ContentJP"] = "（本当に途方に暮れた様子のセリーヌ夫人……彼女がサリーおばさんの言っていた「奥様」なのだろう。何か手伝えることがあるはず）",
            ["DialogueId"] = 51000316,
            ["GUID"] = "7FAC8758",
            },
        [51000401] = {
            ["Content"] = "安妮……安妮！",
            ["ContentJP"] = "アニー……アニー！",
            ["DialogueId"] = 51000401,
            ["GUID"] = "7FAC954A",
            ["NextDialogue"] = 51000402,
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Shock_Start",
                },
            },
        [51000402] = {
            ["Content"] = "啊啊，你回来了，我的宝贝女儿！",
            ["ContentJP"] = "ああ、やっと帰ってきてくれたのね！私の愛しい娘！",
            ["DialogueId"] = 51000402,
            ["GUID"] = "7FAC9574",
            ["NextDialogue"] = 51000403,
            ["SpeakNpcId"] = 700006,
            },
        [51000403] = {
            ["Content"] = "（女子拦住了你的去路。她干涸而涣散的双眼在你身上四处游走着，似乎在拼尽全力从你身上找寻什么。）",
            ["ContentJP"] = "（女性が行く手を遮った。虚ろに乾いた目であなたの身体をくまなく眺め、何かを懸命に見つけようとしている）",
            ["DialogueId"] = 51000403,
            ["GUID"] = "7FAC959E",
            ["NextOptions"] = {
                [1] = 510004031,
                [2] = 510004032,
                [3] = 510004033,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000404] = {
            ["Content"] = "我就知道，你一定会回来的！你怎么忍心抛下妈妈呢！",
            ["ContentJP"] = "信じてたわ、あなたはきっと帰ってくるって！お母さんを置き去りにしたりなんかしないって！",
            ["DialogueId"] = 51000404,
            ["GUID"] = "7FAC95C8",
            ["NextDialogue"] = 51000493,
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Shock_End",
                },
            },
        [51000405] = {
            ["Content"] = "（女人沉浸在自己的世界里，不管你说什么都无济于事。）",
            ["ContentJP"] = "（女性は自分の世界に浸りきって、一方的に話しかけている。あなたが何を言っても聞く耳を持たない）",
            ["DialogueId"] = 51000405,
            ["GUID"] = "7FAC95F2",
            },
        [51000406] = {
            ["Content"] = "你说你不是安妮……",
            ["ContentJP"] = "あなた……アニーじゃないのね……",
            ["DialogueId"] = 51000406,
            ["GUID"] = "7FAC961C",
            ["NextDialogue"] = 51000407,
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Disagree",
                },
            },
        [51000407] = {
            ["Content"] = "都怪我！都怪我！是我逼走了安妮……我就这一个女儿，一直以来只有我们母女俩相依为命。只要你帮我找到她，我什么都答应你！",
            ["ContentJP"] = "私のせい！私のせいなの！私がアニーを追い出してしまったから！私にはあの子しかいないの、今までずっとふたりで生きてきたのよ……\
お願いします！あの子を見つけ出して！どんな報酬でもお約束しますから！",
            ["DialogueId"] = 51000407,
            ["GUID"] = "7FAC9646",
            ["NextOptions"] = {
                [1] = 510004071,
                [2] = 51000002,
                },
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Explain02_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000408] = {
            ["Content"] = "谢谢你，谢谢你……",
            ["ContentJP"] = "ありがとうございます……ありがとうございます……",
            ["DialogueId"] = 51000408,
            ["GUID"] = "7FAC9670",
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Explain02_End",
                },
            },
        [51000409] = {
            ["Content"] = "拜托你了……",
            ["ContentJP"] = "どうかお願いします……",
            ["DialogueId"] = 51000409,
            ["GUID"] = "7FAC969A",
            ["SpeakNpcId"] = 700006,
            },
        [51000420] = {
            ["Content"] = "你好，不知道您有没有见过……",
            ["ContentJP"] = "こんにちは、その……",
            ["DialogueId"] = 51000420,
            ["GUID"] = "7FAC969B",
            ["NextDialogue"] = 51000421,
            ["SpeakNpcId"] = 100001,
            },
        [51000421] = {
            ["Content"] = "我都看到啦。你也被那个女人认错成自己的女儿了是吧。我劝你还是不要去招惹她比较好。她……",
            ["ContentJP"] = "見てたよ。君もあの女性に、娘と間違えられたんでしょ？あんまり関わらないほうがいいよ。あの人はほら……",
            ["DialogueId"] = 51000421,
            ["GUID"] = "7FAC969C",
            ["NextDialogue"] = 51000422,
            ["SpeakNpcId"] = 700232,
            },
        [51000422] = {
            ["Content"] = "（女人指了指自己的脑袋。）",
            ["ContentJP"] = "女性は自分の頭を指さした。",
            ["DialogueId"] = 51000422,
            ["GUID"] = "7FAC969D",
            ["NextDialogue"] = 51000423,
            },
        [51000423] = {
            ["Content"] = "她这里有问题的，在这儿站了一年了。",
            ["ContentJP"] = "ちょっとおかしいのよ。もう一年はここにいるよ。",
            ["DialogueId"] = 51000423,
            ["GUID"] = "7FAC969E",
            ["NextDialogue"] = 51000424,
            ["SpeakNpcId"] = 700232,
            },
        [51000424] = {
            ["Content"] = "不能这么说。她一定是弄丢了女儿，太伤心了才会变成这样。",
            ["ContentJP"] = "そんな言い方、よくないですよ。きっと娘さんを失くして、悲しみに暮れてしまったんですから。",
            ["DialogueId"] = 51000424,
            ["GUID"] = "7FAC969F",
            ["NextDialogue"] = 51000425,
            ["SpeakNpcId"] = 100001,
            },
        [51000425] = {
            ["Content"] = "我劝你还是放弃吧，她女儿走了那么久，现在也没个影，能找到，早找到了。",
            ["ContentJP"] = "諦めたほうがいいよ。あれだけ時間が経っても見つからないんだ、もう……無理だよ。",
            ["DialogueId"] = 51000425,
            ["GUID"] = "7FAC96A0",
            ["NextDialogue"] = 51000426,
            ["SpeakNpcId"] = 700232,
            },
        [51000426] = {
            ["Content"] = "谢谢，不过既然答应人家了，还是找找看吧。",
            ["ContentJP"] = "教えてくれてありがとう。でも、一度約束した以上、もう少し探して見ます。",
            ["DialogueId"] = 51000426,
            ["GUID"] = "7FAC96A1",
            ["SpeakNpcId"] = 100001,
            },
        [51000427] = {
            ["Content"] = "走失的女孩？我可不太清楚，不过昨天我在城门那块儿见过一个小姑娘。",
            ["ContentJP"] = "迷子の女の子？よくわからないけど、昨日、城門のあたりで小さな女の子を見かけたよ。",
            ["DialogueId"] = 51000427,
            ["GUID"] = "7FAC96A2",
            ["NextDialogue"] = 51000428,
            ["SpeakNpcId"] = 700233,
            },
        [51000428] = {
            ["Content"] = "那孩子看着奇奇怪怪的，不知是不是你要找的人。",
            ["ContentJP"] = "その子、なんだか様子が変でさ……君が探してる子かどうかはわからないけど。",
            ["DialogueId"] = 51000428,
            ["GUID"] = "7FAC96A3",
            ["SpeakNpcId"] = 700233,
            },
        [51000429] = {
            ["Content"] = "街对面的那名女孩，我听说她是被一名医生救下的？",
            ["ContentJP"] = "通りの向こうにいたあの子なら、さすらいの医者に助けられたって聞いたよ。",
            ["DialogueId"] = 51000429,
            ["GUID"] = "7FAC96A4",
            ["NextDialogue"] = 51000430,
            ["SpeakNpcId"] = 100001,
            },
        [51000430] = {
            ["Content"] = "你说那个迷迷糊糊的小姑娘？是，前几天有个叫埃莉诺的医生把她带到这儿的。",
            ["ContentJP"] = "ああ、あのぼんやりした少女のことだろ？数日前にエリノアって医者が連れてきたらしい。",
            ["DialogueId"] = 51000430,
            ["GUID"] = "7FAC96A5",
            ["NextDialogue"] = 51000431,
            ["SpeakNpcId"] = 700234,
            },
        [51000431] = {
            ["Content"] = "这位埃莉诺医生住在哪儿？",
            ["ContentJP"] = "そのエリノアさんは、今どこに？",
            ["DialogueId"] = 51000431,
            ["GUID"] = "7FAC96A6",
            ["NextDialogue"] = 51000432,
            ["SpeakNpcId"] = 100001,
            },
        [51000432] = {
            ["Content"] = "她是个旅行医生，不是本地人。真不巧，今天我刚好看到她出城。要不你去泪湖方向看看吧，说不定她还没走远。",
            ["ContentJP"] = "さすらいの医者だから、ここの人じゃないんだ。運が悪いことに、今日ちょうど町を出たところを見たよ。ダクリ湖の方に向かったみたいだから、今追えば間に合うかも。",
            ["DialogueId"] = 51000432,
            ["GUID"] = "7FAC96A7",
            ["SpeakNpcId"] = 700234,
            },
        [51000433] = {
            ["Content"] = "谢谢您，好心人。承蒙您慷慨相救，让我捡了一条命，维瓦尔镇那里的病人还在等我。",
            ["ContentJP"] = "助けてくれてありがとう。あなたのおかげで命拾いしたわ。ヴィヴァルの町には、まだ私を待っている患者たちがいるの。",
            ["DialogueId"] = 51000433,
            ["GUID"] = "7FAC96A8",
            ["NextDialogue"] = 51000434,
            ["SpeakNpcId"] = 700235,
            },
        [51000434] = {
            ["Content"] = "你是医生？莫非你就是埃莉诺？",
            ["ContentJP"] = "あなたが医者のエリノアさんですね？",
            ["DialogueId"] = 51000434,
            ["GUID"] = "7FAC96A9",
            ["NextDialogue"] = 51000435,
            ["SpeakNpcId"] = 100001,
            },
        [51000435] = {
            ["Content"] = "是的，您找我……？",
            ["ContentJP"] = "ええ、そうだけど……あなたは？",
            ["DialogueId"] = 51000435,
            ["GUID"] = "7FAC96AA",
            ["NextDialogue"] = 51000436,
            ["SpeakNpcId"] = 700235,
            },
        [51000436] = {
            ["Content"] = "听说您前些日子从北边的雪山救了一个女孩。",
            ["ContentJP"] = "数日前、北の雪山で女の子を助けたと聞きました。",
            ["DialogueId"] = 51000436,
            ["GUID"] = "7FAC96AB",
            ["NextDialogue"] = 51000437,
            ["SpeakNpcId"] = 100001,
            },
        [51000437] = {
            ["Content"] = "啊，是我。您在冰湖城里见到她了吗？不知她现在是否安康？",
            ["ContentJP"] = "ええ、その子のことなら覚えてるわ。アイスレイク城で彼女に会ったのね？無事でよかった……",
            ["DialogueId"] = 51000437,
            ["GUID"] = "7FAC96AC",
            ["NextDialogue"] = 51000438,
            ["SpeakNpcId"] = 700235,
            },
        [51000438] = {
            ["Content"] = "她看起来身体还好，但好像什么都忘了。我想问的是，你找到她的时候，她身上还带着什么东西吗？或许会和她的身份有关？",
            ["ContentJP"] = "はい、元気そうでした。ただ、記憶を失ってしまっていて……救助したとき、彼女は何か身につけていましたか？手がかりになるものとか……",
            ["DialogueId"] = 51000438,
            ["GUID"] = "7FAC96AD",
            ["NextDialogue"] = 51000439,
            ["SpeakNpcId"] = 100001,
            },
        [51000439] = {
            ["Content"] = "嗯，有的。我本想看完这次的病人后再看看能不能帮她找到她的家人。如果您愿意帮忙，就再好不过了……",
            ["ContentJP"] = "ええ、確かに何か持ってたわ。すぐに渡せなくて申し訳ないわ。患者の治療が終わったら、家族を探すの手伝ってあげたいと思ってたの。よかったら、手伝ってあげて。",
            ["DialogueId"] = 51000439,
            ["GUID"] = "7FAC96AE",
            ["NextDialogue"] = 51000440,
            ["SpeakNpcId"] = 700235,
            },
        [51000440] = {
            ["Content"] = "给，这是她随身带着的。",
            ["ContentJP"] = "これが彼女が持っていたものよ。",
            ["DialogueId"] = 51000440,
            ["GUID"] = "7FAC96AF",
            ["NextDialogue"] = 51000441,
            ["SpeakNpcId"] = 700235,
            },
        [51000441] = {
            ["Content"] = "我要去维瓦尔镇了，再次感谢您救了我。",
            ["ContentJP"] = "それじゃあ、私はヴィヴァルへ向かうわ。本当にありがとう。",
            ["DialogueId"] = 51000441,
            ["GUID"] = "7FAC96B0",
            ["NextDialogue"] = 51000443,
            ["SpeakNpcId"] = 700235,
            },
        [51000442] = {
            ["Content"] = "（获得道具残破的日记本）",
            ["ContentJP"] = "アイテム獲得：ぼろぼろの日記",
            ["DialogueId"] = 51000442,
            ["GUID"] = "7FAC96B1",
            ["NextDialogue"] = 51000443,
            },
        [51000443] = {
            ["Content"] = "（如果日记上记录的内容属实，那么失忆少女的真实身份，就已十分明了了。）",
            ["ContentJP"] = "（もしこの日記に書かれていることが本当なら――少女の正体は明らかになる。）",
            ["DialogueId"] = 51000443,
            ["GUID"] = "7FAC96B2",
            ["NextDialogue"] = 51000444,
            },
        [51000444] = {
            ["Content"] = "（同样水落石出的，还有爱尔莎夫人那个失踪的女儿，安妮的下落……）",
            ["ContentJP"] = "（そして、水底に沈んでいたもう一つの真実――エルザ夫人が探し続けていた、失踪した娘・アニーの消息も……）",
            ["DialogueId"] = 51000444,
            ["GUID"] = "7FAC96B3",
            ["NextDialogue"] = 51000445,
            },
        [51000445] = {
            ["Content"] = "（……安妮已经不幸离世，而得到她衣物的另一位少女爱丽丝活了下来。尽管在雪山幸存，但连续高烧还是夺走了爱丽丝的记忆。）",
            ["ContentJP"] = "（残念ながら生きるという旅を終えてしまったアニー。そんな彼女から服をもらったアリスは、高熱のせいで記憶を失いながらも生き延びたのだろう）",
            ["DialogueId"] = 51000445,
            ["GUID"] = "7FAC96B4",
            },
        [51000490] = {
            ["Content"] = "……安妮，你在说什么呢？妈妈准备了你最爱吃的北风莓沙拉和奶油布丁……",
            ["ContentJP"] = "……アニー、何を言ってるの？お母さんね、あなたの大好きなアイスベリーのサラダと、クリームプリンも作って待ってたのよ……",
            ["DialogueId"] = 51000490,
            ["GUID"] = "7FACA3E4",
            ["NextDialogue"] = 51000491,
            ["SpeakNpcId"] = 700006,
            },
        [51000491] = {
            ["Content"] = "回家吧，妈妈再也不凶你，再也不要你做什么上流社会的淑女了，妈妈只要你好好的……",
            ["ContentJP"] = "家に帰りましょう？上流社会の淑女になれとか、お母さんもうガミガミ言わないようにするから……あなたが元気でいてくれたら、それだけでいいの……",
            ["DialogueId"] = 51000491,
            ["GUID"] = "7FACA40E",
            ["NextDialogue"] = 51000492,
            ["SpeakNpcId"] = 700006,
            },
        [51000492] = {
            ["Content"] = "（女子的精神状态不太好，听起来，她似乎弄丢了自己的女儿。试着说服她冷静下来吧。）",
            ["ContentJP"] = "（彼女は精神状態があまりよくない様子だ。話を聞くに、自分の娘が行方不明になったのだろうか。とにかく落ち着くよう話してみるべきか）",
            ["DialogueId"] = 51000492,
            ["GUID"] = "7FACA438",
            ["NextOptions"] = {
                [1] = 510004921,
                },
            ["SpeakNpcId"] = 700006,
            ["bForbidSkipOptions"] = true,
            },
        [51000493] = {
            ["Content"] = "（你知道，你只是在和她开个小小的玩笑。接下来，得想办法说服她冷静下来。听起来，她似乎弄丢了自己的女儿。）",
            ["ContentJP"] = "（軽い冗談のつもりで言ったものの、本気にしているのだろうか。彼女を落ち着かせないと収拾がつかなそうだ。話を聞くに、自分の娘が行方不明になった様子だが）",
            ["DialogueId"] = 51000493,
            ["GUID"] = "7FACA462",
            ["NextOptions"] = {
                [1] = 510004921,
                },
            ["RestartTag"] = 51000493,
            ["bForbidSkipOptions"] = true,
            },
        [51000501] = {
            ["Content"] = "拜托你了……",
            ["ContentJP"] = "どうかお願いします……",
            ["DialogueId"] = 51000501,
            ["GUID"] = "7FACA5B2",
            ["NextOptions"] = {
                [1] = 510005011,
                },
            ["SpeakNpcId"] = 700006,
            },
        [51000502] = {
            ["Content"] = "天呐！你找到安妮了？",
            ["ContentJP"] = "本当に！アニーが見つかったの！？",
            ["DialogueId"] = 51000502,
            ["GUID"] = "7FACA5DC",
            ["NextOptions"] = {
                [1] = 510005021,
                },
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Shock_Start",
                },
            },
        [51000503] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51000503,
            ["GUID"] = "7FACA606",
            ["NextDialogue"] = 51000504,
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Shock_End",
                },
            },
        [51000504] = {
            ["Content"] = "胡说……胡说，胡说！",
            ["ContentJP"] = "嘘よ……嘘よ、嘘、嘘、嘘だ！嘘つきめ！",
            ["DialogueId"] = 51000504,
            ["GUID"] = "7FACA630",
            ["NextDialogue"] = 51000591,
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Disagree",
                },
            },
        [51000505] = {
            ["Content"] = "你说，孩子没了母亲可怎么行呢……",
            ["ContentJP"] = "ええそうよ、あの娘には、必要なんだから……母親である私が……",
            ["DialogueId"] = 51000505,
            ["GUID"] = "7FACA65A",
            ["NextDialogue"] = 51000506,
            ["Scripts"] = "SEQ{\
MoveTo{ActorId{700006},TargetPoint{\"Point_510005_Aier2\"},MoveSpeed{150},Visibility{\"Show\"}},\
MoveTo{ActorId{700006},TargetPoint{\"Point_510005_Aier\"},MoveSpeed{150},Visibility{\"Hide\"}}\
}",
            ["SpeakNpcId"] = 700006,
            },
        [51000506] = {
            ["Content"] = "（爱尔莎像着了魔一样朝某个方向走去，泪水与笑容交织在她憔悴的脸上，很快她的身影就消失在了远方。）",
            ["ContentJP"] = "エルザはそっと財布をあなたの胸に押し込むと、何かに引き寄せられるように歩き出した。涙と笑顔が交じるやつれた顔を残し、やがて彼女の姿は遠くに消えていった。",
            ["DialogueId"] = 51000506,
            ["GUID"] = "7FACA684",
            ["NextDialogue"] = 51000507,
            },
        [51000507] = {
            ["Content"] = "（她匆忙中落下了一个小箱子——这是她原本打算赠与帮她找到女儿的好心人的。你为她的事奔忙了这么久，这些报酬理当属于你。）",
            ["ContentJP"] = "優しい嘘よりも、大切なのは真実と向き合うこと。時間は何よりの薬だ。きっと、いつか……彼女も立ち直れるかもしれない。",
            ["DialogueId"] = 51000507,
            ["GUID"] = "7FACA6AE",
            },
        [51000590] = {
            ["Content"] = "之前是我太疏忽，只知道拜托别人，傻傻地等，让我的安妮等了那么久，没关系，都没关系，我现在就启程去找她……自己去找……",
            ["ContentJP"] = "ああ、私ったらダメね……ただ人に頼って、待ってるだけなんて、私のアニーを、長く待たせてしまって……もう大丈夫、大丈夫よ……今すぐ、探しにいくからね……お母さんが、探しにいくからね……",
            ["DialogueId"] = 51000590,
            ["GUID"] = "7FACB44C",
            ["NextDialogue"] = 51000505,
            ["SpeakNpcId"] = 700006,
            },
        [51000591] = {
            ["Content"] = "我的安妮……我的安妮那么乖，她怎么可能抛下自己的妈妈呢！你骗我，你骗我！",
            ["ContentJP"] = "私のアニーは……アニーは、本当に優しい子なの……あの子が、お母さんを置き去りにするなんて、そんなのするわけ！そんなのないでしょうが！あなた私を騙して！騙して！！",
            ["DialogueId"] = 51000591,
            ["GUID"] = "7FACB476",
            ["NextDialogue"] = 51000590,
            ["SpeakNpcId"] = 700006,
            },
        [51000601] = {
            ["Camera"] = "-234.948181,323.855713,130.964355,0.00001,-3.599974,-48.399338,32.0,100000.0,false,Manual,2.8",
            ["Content"] = "拜托你了……",
            ["ContentJP"] = "どうかお願いします……",
            ["DialogueId"] = 51000601,
            ["GUID"] = "7FACB61A",
            ["LookAt"] = {
                [1] = "700006:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510006011,
                },
            ["Scripts"] = "TurnTo{TurnToDescription{\"700006:n(100001)\"}}",
            ["SpeakNpcId"] = 700006,
            },
        [51000602] = {
            ["Camera"] = "-110.428955,187.104736,199.557129,0.00006,-12.599321,-55.19915,32.0,500.0,false,Manual,2.8",
            ["Content"] = "……天啊，奇迹真的发生了……",
            ["ContentJP"] = "何て……ことなの？奇跡が……起きたのね……本当に……？",
            ["DialogueId"] = 51000602,
            ["FinalCamera"] = "-95.131409,197.827637,199.557129,0.000059,-12.799316,-54.799076,32.0,500.0,false,Manual,2.8",
            ["GUID"] = "7FACB644",
            ["LookAt"] = {
                [1] = "700006:n(700196)",
                },
            ["NextDialogue"] = 51000603,
            ["Scripts"] = "MoveTo{ActorId{700196},TargetPoint{\"Point200203_Alice\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Shock_Start",
                },
            ["ToFinalCameraBlendTime"] = 3,
            },
        [51000603] = {
            ["Content"] = "让妈妈好好看看，妈妈想你想得都快发疯了！嗯？你怎么和以前不太一样了？你变瘦了好多……",
            ["ContentJP"] = "お母さんに見せて、あなたの顔を……お母さんあなたのことで頭がいっぱいで……おかしくなりそうだったのよ！あら……？前と少し雰囲気が変わったわね？すごく痩せたような…",
            ["DialogueId"] = 51000603,
            ["FacialId"] = {
                [1] = "700006:CM_Happy01",
                },
            ["GUID"] = "7FACB66E",
            ["NextDialogue"] = 51000604,
            ["SpeakNpcId"] = 700006,
            },
        [51000604] = {
            ["Camera"] = "98.233093,31.165039,150.292969,0.000063,-2.599365,-39.19735,32.0,150.0,false,Manual,2.8",
            ["Content"] = "没关系的，没关系的，妈妈准备了你最爱吃的北风莓沙拉和奶油布丁，回家吧，我的孩子，都过去了，都过去了……",
            ["ContentJP"] = "でも大丈夫、大丈夫よ。お母さんあなたの大好きなアイスベリーのサラダとクリームプリンを作って待ってたの。帰りましょう、私の愛しい娘。全ては終わったことなの、もう全ては過去のこと……",
            ["DialogueId"] = 51000604,
            ["GUID"] = "7FACB698",
            ["NextDialogue"] = 51000605,
            ["SpeakNpcId"] = 700006,
            ["TalkActionId"] = {
                [1] = "700006:Shock_Start",
                },
            },
        [51000605] = {
            ["Content"] = "谢谢你，好心人，这是给你的报酬。我差点就以为我再也见不到我的安妮了。谢谢你，谢谢你……",
            ["ContentJP"] = "ありがとうございました。こちらはあなた様に贈ります。もうアニーとは二度と会えないと思っていました。厚くお礼を申し上げます……本当に、本当に……厚く……",
            ["DialogueId"] = 51000605,
            ["GUID"] = "7FACB6C2",
            ["NextDialogue"] = 51000690,
            ["SpeakNpcId"] = 700006,
            },
        [51000606] = {
            ["Content"] = "我的宝贝女儿……只要不离开妈妈，妈妈为你做什么都可以……",
            ["ContentJP"] = "私のかわいい娘……もうお母さんから離れないでね。あなたのためなら、お母さんなんだってするわ……",
            ["DialogueId"] = 51000606,
            ["GUID"] = "7FACB6EC",
            ["SpeakNpcId"] = 700006,
            },
        [51000690] = {
            ["Content"] = "（女人喜极而泣，不停道谢着。泪水流干后，就是幸福的未来……或许。）",
            ["ContentJP"] = "（喜びのあまり泣き出した母親は、何度も何度もあなたにお礼を言い続ける。彼女の涙が尽きた時、幸せな未来が始まるのだろう……恐らくだが）",
            ["DialogueId"] = 51000690,
            ["GUID"] = "7FACC4B4",
            },
        [51000701] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51000701,
            ["GUID"] = "7FACC682",
            ["NextOptions"] = {
                [1] = 510007011,
                },
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Sigh_Start",
                },
            },
        [51000702] = {
            ["Content"] = "我……我脑袋很昏沉。我不知道自己是谁，也不清楚这是哪里……",
            ["ContentJP"] = "私……頭がぼんやりしてて。自分が誰なのかも、ここがどこなのかもわからないの……",
            ["DialogueId"] = 51000702,
            ["GUID"] = "7FACC6AC",
            ["NextDialogue"] = 51000703,
            ["SpeakNpcId"] = 700032,
            },
        [51000703] = {
            ["Content"] = "我是被一个好心的旅行医生从北边雪山救回来的。他说我发了高烧，烧坏了脑子，所以才会失去记忆……",
            ["ContentJP"] = "北の雪山で、やさしいお医者さんに助けてもらったの。熱が出て……それで、あたま、こわれちゃったんだって……だから、何も思い出せないの……",
            ["DialogueId"] = 51000703,
            ["GUID"] = "7FACC6D6",
            ["NextOptions"] = {
                [1] = 510007031,
                [2] = 510007032,
                [3] = 510007033,
                },
            ["SpeakNpcId"] = 700032,
            ["bForbidSkipOptions"] = true,
            },
        [51000705] = {
            ["Content"] = "这几天我唯一能想起来的就是漫天的暴风雪，我在山上举步维艰……但我大病初愈，现在的身体状况估计连出城都难，可以拜托你帮我调查吗？",
            ["ContentJP"] = "この数日間で私が思い出せたのは、空を覆い尽くすほどの猛吹雪と、歩くのもやっとな状態で山を登っていたことだけ……ぶしつけなのは承知でお願いしたいのですが、私に関することを、私の代わりに調べてもらえたりはできませんか？街の外へ行こうにも、今の病み上がりの体調では難しく……",
            ["DialogueId"] = 51000705,
            ["GUID"] = "7FACC72A",
            ["NextOptions"] = {
                [1] = 510007051,
                [2] = 51000002,
                },
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Explain01_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000706] = {
            ["Content"] = "除了救我的好心人，你是唯一一个愿意对我这样一个身无分文的女孩子伸出援助之手的。除了谢谢，我不知道还能说什么好……",
            ["ContentJP"] = "あのお医者様以外にも私のような一文無しに手を差し伸べてくださる方がいるなんて。なんとお優しいのでしょうか、感謝してもしきれません。",
            ["DialogueId"] = 51000706,
            ["GUID"] = "7FACC754",
            ["NextDialogue"] = 51000790,
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Explain01_End",
                },
            },
        [51000707] = {
            ["Content"] = "有结果吗？",
            ["ContentJP"] = "何かわかったことはありますか？",
            ["DialogueId"] = 51000707,
            ["GUID"] = "7FACC77E",
            ["SpeakNpcId"] = 700032,
            },
        [51000790] = {
            ["Content"] = "对了，这里有一封信，医生说这是从我身上找到的。虽然我对这封信一点印象都没有……但这个线索可能会有用？",
            ["ContentJP"] = "あっ、そうだ……これ。コートのポケットから出てきたの。ぜんぜん覚えてないんだけど……でも、何かわかるかも？",
            ["DialogueId"] = 51000790,
            ["GUID"] = "7FACD51C",
            ["NextDialogue"] = 51000791,
            ["SpeakNpcId"] = 700032,
            },
        [51000791] = {
            ["Content"] = "（你开始思索最近遇到的两个人——近乎疯癫地寻找女儿的爱尔莎夫人，以及失忆的少女。当然，还有少女口袋里那封写给母亲的信。）",
            ["ContentJP"] = "（あなたは考えを巡らせる。常軌を逸した様子で娘を探していたエルザ夫人と記憶を失った少女、そのふたりについて。少女のポケットにあった手紙との関連性を）",
            ["DialogueId"] = 51000791,
            ["GUID"] = "7FACD546",
            ["NextDialogue"] = 51000792,
            },
        [51000792] = {
            ["Content"] = "（失忆的少女也许就是爱尔莎失踪的女儿，安妮——你这样猜测。）",
            ["ContentJP"] = "（記憶を失った少女は行方不明になったエルザの娘、アニーなのかもしれない——そう推測した）",
            ["DialogueId"] = 51000792,
            ["GUID"] = "7FACD570",
            ["NextDialogue"] = 51000793,
            },
        [51000793] = {
            ["Content"] = "（你应该带她去找爱尔莎确认的，但是，爱尔莎似乎会把每一个路过的年轻人当成安妮……也许还是先收集更多失忆少女身份的证据为好。）",
            ["ContentJP"] = "（彼女をエルザの元まで連れていき確認してみるべきか。しかしエルザは道ゆく若者全てをアニーと思い込むようになっている……まずはもっと少女の身元がわかる証拠を集めた方がいいかもしれない）",
            ["DialogueId"] = 51000793,
            ["GUID"] = "7FACD59A",
            ["NextDialogue"] = 51000794,
            },
        [51000794] = {
            ["Content"] = "（解铃还须系铃人，看来想要探知少女的身世，还得先想办法找到那位当初救下少女的医生。）",
            ["ContentJP"] = "糸を解くには、結び目から探すべし。少女の素性を知るには、最初に彼女を救った医者を探し出すしかなさそうだ。",
            ["DialogueId"] = 51000794,
            ["GUID"] = "7FACD59B",
            },
        [51000801] = {
            ["Content"] = "你平安回来了，辛苦你了，有什么发现吗？",
            ["ContentJP"] = "おかえりなさい、ご無事で何よりです。何かわかったことはありますか？",
            ["DialogueId"] = 51000801,
            ["GUID"] = "7FACD6EA",
            ["NextDialogue"] = 51000802,
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Agree",
                },
            },
        [51000802] = {
            ["Content"] = "（眼前的少女无依无靠，而爱尔莎夫人也因为爱女失踪而精神失常……你不禁想，如果少女就是安妮该有多好。）",
            ["ContentJP"] = "（目の前の少女には身寄りがない。エルザ夫人は娘が行方不明になって精神不安定な状態……少女がアニーであれば都合のよい話だったのだが）",
            ["DialogueId"] = 51000802,
            ["GUID"] = "7FACD714",
            ["NextDialogue"] = 51000890,
            },
        [51000803] = {
            ["Content"] = "……这是……！",
            ["ContentJP"] = "……これは……！",
            ["DialogueId"] = 51000803,
            ["GUID"] = "7FACD73E",
            ["NextDialogue"] = 51000893,
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Shock_Start",
                },
            },
        [51000804] = {
            ["Content"] = "我……我记起来了……",
            ["ContentJP"] = "私……私、思い出しました。",
            ["DialogueId"] = 51000804,
            ["GUID"] = "7FACD768",
            ["NextDialogue"] = 51000805,
            ["SpeakNpcId"] = 700032,
            ["TalkActionId"] = {
                [1] = "700032:Shock_End",
                },
            },
        [51000805] = {
            ["Content"] = "我叫爱丽丝，是一名来自伊瑟尔的考古学学生……",
            ["ContentJP"] = "私の名前はアリス。イーザーで考古学を専攻していた者です……",
            ["DialogueId"] = 51000805,
            ["GUID"] = "7FACD792",
            ["NextDialogue"] = 51000806,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            ["TalkActionId"] = {
                [1] = "700032:Talk02_Start",
                },
            },
        [51000806] = {
            ["Content"] = "当时我正在维德弗尼尔雪山勘查，却恰巧遭遇了接连数日的暴风雪，很快我就迷失了方向……",
            ["ContentJP"] = "ヴィドフニルの雪山で調査をしていたあの日、運悪く何日も収まらない吹雪に襲われて、進むべき方向を見失って……",
            ["DialogueId"] = 51000806,
            ["GUID"] = "7FACD7BC",
            ["NextDialogue"] = 51000807,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            },
        [51000807] = {
            ["Content"] = "后来，我遇见了奄奄一息的安妮，我们一起艰难生活了数日。我们鼓励着彼此活下去，约好在暴风雪停歇后，我要去她在冰湖城的家做客……",
            ["ContentJP"] = "その後に瀕死の状態だったアニーさんと出会い、数日間をふたりでなんとか耐え抜きました。生きていこうと励まし合いながら「吹雪がやんだらアイスレイク城の家に遊びにいく」なんて約束もしました……",
            ["DialogueId"] = 51000807,
            ["GUID"] = "7FACD7E6",
            ["NextDialogue"] = 51000808,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            },
        [51000808] = {
            ["Content"] = "可是她伤得太重了，最终还是没能挺过去……最后她把衣服给了我，希望我再穿暖和一些，能活着走出雪山……",
            ["ContentJP"] = "でも……あの子、傷がひどすぎて……結局助からなかったの。……最後に、自分の服を私に渡してくれて……「少しでもあったかくして、生きて雪山を出て」って……",
            ["DialogueId"] = 51000808,
            ["GUID"] = "7FACD810",
            ["NextDialogue"] = 51000809,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            ["TalkActionId"] = {
                [1] = "700032:Talk02_End",
                },
            },
        [51000809] = {
            ["Content"] = "安妮……",
            ["ContentJP"] = "アニーさん……",
            ["DialogueId"] = 51000809,
            ["GUID"] = "7FACD83A",
            ["NextDialogue"] = 51000810,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            ["TalkActionId"] = {
                [1] = "700032:Explain02_Start",
                },
            },
        [51000810] = {
            ["Content"] = "谢谢你……我会永远记住安妮的。",
            ["ContentJP"] = "はい……アニーさんのこと、一生忘れません。",
            ["DialogueId"] = 51000810,
            ["GUID"] = "7FACD864",
            ["NextDialogue"] = 51000811,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            ["TalkActionId"] = {
                [1] = "700032:Explain02_End",
                },
            },
        [51000811] = {
            ["Content"] = "（爱丽丝温柔地抚摸着衣物，这是一个女孩保护了另一个女孩的见证。你告别爱丽丝，准备将事实转告爱尔莎。）",
            ["ContentJP"] = "（アリスが優しく服をなでている。これはとある女の子が、見ず知らずの女の子を守った証だ。あなたはアリスに別れを告げ、あの母親に事実を伝えに行くことにした）",
            ["DialogueId"] = 51000811,
            ["GUID"] = "7FACD88E",
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            },
        [51000812] = {
            ["Content"] = "等身体养好了，我就打算开始下一段冒险了。",
            ["ContentJP"] = "体調が回復したら、旅を再開しようと考えています。",
            ["DialogueId"] = 51000812,
            ["GUID"] = "7FACD8B8",
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Alice",
            },
        [51000813] = {
            ["Content"] = "你的名字是安妮。我找到了你的母亲，你口袋里那封信就是写给她的。",
            ["ContentJP"] = "{性别:あなたのお母さんを見つけたよ。名前はアニーで間違いないと思う。ポケットの中にあった手紙はあなたがお母さん宛に書いた物じゃないかな？|あなたのお母さんを見つけた。名前はアニーで間違いないと思う。ポケットの中にあった手紙はあなたがお母さん宛に書いた物じゃないか？}",
            ["DialogueId"] = 51000813,
            ["GUID"] = "7FACD8E2",
            ["NextDialogue"] = 51000894,
            ["SpeakNpcId"] = 100001,
            },
        [51000814] = {
            ["Content"] = "谢谢你！她一定很担心我。",
            ["ContentJP"] = "ありがとうございます。お母さんきっと、私のことを心配してるはずだわ。",
            ["DialogueId"] = 51000814,
            ["GUID"] = "7FACD90C",
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_Npc_Name_Anni",
            },
        [51000815] = {
            ["Content"] = "等母亲好些，我就带她去看看大自然有多美！",
            ["ContentJP"] = "お母さんが落ち着いて元気になったら、きれいな大自然を一緒に見に行くのよ！",
            ["DialogueId"] = 51000815,
            ["GUID"] = "7FACD936",
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_Npc_Name_Anni",
            },
        [51000890] = {
            ["Content"] = "（回忆起爱尔莎说过，她家只有母女俩相依为命，你脑海中突然闪过一个可怕的念头——如果你<H>从未见过</>爱丽丝的日记……）",
            ["ContentJP"] = "（母と娘のふたりだけで支え合いながら生きていたとエルザが話していたことを思い出す。そしてふと、頭の中に恐ろしい考えが浮かんだ——もしあなたがアリスの日記を<H>発見していなかった</>としたら……）",
            ["DialogueId"] = 51000890,
            ["GUID"] = "7FACE584",
            ["NextDialogue"] = 51000891,
            },
        [51000891] = {
            ["Content"] = "（少女将有一个温暖的小家可以依靠，而爱尔莎的“女儿”也回来了。<H>这似乎是最完美的结局——只是，这两个人同样拥有知晓真相的权利……</>）",
            ["ContentJP"] = "（少女は温かな家を頼りにでき、エルザは「娘」が帰ってくる。<H>知らずに幕を閉じることが完璧な結末に思えるが——ふたりに真実を知る権利があるのも確かだ……</>）",
            ["DialogueId"] = 51000891,
            ["GUID"] = "7FACE5AE",
            ["NextDialogue"] = 51000892,
            },
        [51000892] = {
            ["Content"] = "（应该做出怎样的选择？将真相告知二人，还是这样将错就错下去？）",
            ["ContentJP"] = "（告げるべきか、目を背けるべきか……どちらを選ぶべきだろう？）",
            ["DialogueId"] = 51000892,
            ["GUID"] = "7FACE5D8",
            ["NextOptions"] = {
                [1] = 510008921,
                [2] = 510008121,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51000893] = {
            ["Content"] = "这是……我写的……",
            ["ContentJP"] = "これは……私の書いた……",
            ["DialogueId"] = 51000893,
            ["GUID"] = "7FACE602",
            ["NextDialogue"] = 51000804,
            ["SpeakNpcId"] = 700032,
            },
        [51000894] = {
            ["Content"] = "安妮……原来这就是我的名字啊。总觉得稍微有点陌生呢……",
            ["ContentJP"] = "アニー……それが私の名前……何かしっくりとこない感じはするけど……",
            ["DialogueId"] = 51000894,
            ["GUID"] = "7FACE62C",
            ["NextDialogue"] = 51000895,
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_Npc_Name_Anni",
            },
        [51000895] = {
            ["Content"] = "抱歉，我都忘了……谢谢，真的谢谢你！带我去找妈妈吧，她一定会重谢你的！",
            ["ContentJP"] = "ううん、ごめんなさい、すっかり忘れていたみたいです……本当にありがとう！お母さんのところまで案内してくれますか？お母さんもきっとあなたに感謝しているはず！",
            ["DialogueId"] = 51000895,
            ["GUID"] = "7FACE656",
            ["NextOptions"] = {
                [1] = 510008141,
                },
            ["SpeakNpcId"] = 700032,
            ["SpeakNpcName"] = "UI_Npc_Name_Anni",
            ["bForbidSkipOptions"] = true,
            },
        [51000901] = {
            ["Content"] = "陌生的客人！什么风把您吹到了我这里来？不过您要是想找点乐子，到马丁这来看看准没错！",
            ["ContentJP"] = "ようこそ見知らぬお客様！どこ吹く風が呼び寄せたのでしょうか、このマーティンの下を訪れるとはお目が高いですね？\
何か楽しいモノをお求めであれば、ここに来たのは大正解でしょう！",
            ["DialogueId"] = 51000901,
            ["GUID"] = "7FACE752",
            ["NextDialogue"] = 51000902,
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Talk01_Start",
                },
            },
        [51000902] = {
            ["Content"] = "（面前的男人对你行了一个花里胡哨的大礼，然后变戏法一样摆出一堆错落的商品）",
            ["ContentJP"] = "（目の前の男は仰々しいお辞儀をすると、手品師のようにさまざまな商品を並べた）",
            ["DialogueId"] = 51000902,
            ["GUID"] = "7FACE77C",
            ["NextDialogue"] = 51000903,
            ["SpeakNpcId"] = 700022,
            },
        [51000903] = {
            ["Content"] = "随意挑选，相信马丁的品味！您见过的没见过的都能在这里找到，偶尔给自己的生活带来点小惊喜！",
            ["ContentJP"] = "さあ、お好きなように選んでください！マーティンのセンスを信じて！あるものないものなんでも見つかりますよ！\
たまには生活にちょっとしたサプライズがないと！",
            ["DialogueId"] = 51000903,
            ["GUID"] = "7FACE7A6",
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Talk01_End",
                },
            ["TalkOptions"] = {
                [1] = 510009031,
                [2] = 510009032,
                [3] = 510009033,
                },
            },
        [51000904] = {
            ["Content"] = "你可真没礼貌~会估价可不等于你是个有品味的人，甜心。",
            ["ContentJP"] = "オォ～ウ、なんと意地悪で失礼なお人だこと！\
\
しかし見立てができるからといって、あなた様にセンスがあるのかどうかはわかりませんよ、スウィーティー？",
            ["DialogueId"] = 51000904,
            ["GUID"] = "7FACE7D0",
            ["SpeakNpcId"] = 700022,
            ["TalkOptions"] = {
                [1] = 510009071,
                },
            },
        [51000905] = {
            ["Content"] = "任由它们浪费难道不也是一种犯罪吗？我只是想给他们都找一个家~",
            ["ContentJP"] = "オォ～ノ～、私はただこの子たちの居場所を探してあげたいだけなのです。この子たちを無駄に放置しておくのは一種の犯罪行為だと思いません？",
            ["DialogueId"] = 51000905,
            ["GUID"] = "7FACE7FA",
            ["SpeakNpcId"] = 700022,
            ["TalkOptions"] = {
                [1] = 510009071,
                },
            },
        [51000906] = {
            ["Content"] = "哦~这可是商业机密。你想好用什么来和我交换了吗？",
            ["ContentJP"] = "オォ～ウ、それはトップシークレット！\
代わりに何を私に差し出すかよ～く考えましたか？",
            ["DialogueId"] = 51000906,
            ["GUID"] = "7FACE824",
            ["SpeakNpcId"] = 700022,
            ["TalkOptions"] = {
                [1] = 510009071,
                },
            },
        [51000907] = {
            ["Content"] = "（你看了看他的商品，遗憾地摇了摇头）",
            ["ContentJP"] = "（彼の商品を見て、あなたは残念そうに首を振った）",
            ["DialogueId"] = 51000907,
            ["GUID"] = "7FACE84E",
            ["TalkOptions"] = {
                [1] = 510009072,
                },
            },
        [51000908] = {
            ["Content"] = "那我大概不是你需要的那种人，但我会等到你愿意惠顾的那天的。",
            ["ContentJP"] = "な～るほど。私を必要としているタイプのお人ではなかったのですね。\
しかし気が変わることもありましょう。いつでもお待ちしておりますよ。",
            ["DialogueId"] = 51000908,
            ["GUID"] = "7FACE878",
            ["SpeakNpcId"] = 700022,
            },
        [51000909] = {
            ["Content"] = "我明白了！你是这个冰湖城里很罕见的一种人……",
            ["ContentJP"] = "オッケー丸っと理解完了！\
あなた様はこのアイスレイクキャッスルでも珍しいお人だ……！",
            ["DialogueId"] = 51000909,
            ["GUID"] = "7FACE8A2",
            ["NextDialogue"] = 51000910,
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Think_Start",
                },
            },
        [51000910] = {
            ["Content"] = "你既不是来采购廉价物资的贫民窟居民，也不是对邻居的私生活大有兴趣的贵族老爷，你对马丁无欲无求，甚至你从来没听过我的名字，对不对？",
            ["ContentJP"] = "安価な物資を買いに来たスラム街の住民でもなく、隣人の私生活に深い興味を持つ貴族の旦那様でもなく......\
マーティンに何も求めておらず、私の名前さえも聞いたことがない……ザッツライト？",
            ["DialogueId"] = 51000910,
            ["GUID"] = "7FACE8CC",
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Think_End",
                },
            ["TalkOptions"] = {
                [1] = 510009101,
                [2] = 510009102,
                [3] = 510009103,
                },
            },
        [51000911] = {
            ["Content"] = "那请容我为您自我介绍！我是冰湖城的拾荒者之王，每个垃圾桶的知心兄弟，废弃物品最好的代言者与推销者。",
            ["ContentJP"] = "では満を持して自己紹介いたしましょう！アイスレイクキャッスルのゴミ拾いのキングでありゴミ箱のフレンド、廃棄物のスピーカー券プロモーター......",
            ["DialogueId"] = 51000911,
            ["GUID"] = "7FACE8F6",
            ["NextDialogue"] = 51000990,
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Confident_Start",
                },
            },
        [51000912] = {
            ["Content"] = "事实上，垃圾桶里隐藏着各式各样的秘密，只要你足够耐心，不辞辛苦……它们就会把这户人家的心事源源不断地告诉你。",
            ["ContentJP"] = "実はゴミ箱というモノはさまざまなシークレットを知っておりましてね。根気強く彼らが語りかける声に耳を傾ければ……\
その家で何が起こっているのかなど、饒舌に話してくれるのです。",
            ["DialogueId"] = 51000912,
            ["GUID"] = "7FACE920",
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Confident_End",
                },
            },
        [51000913] = {
            ["Content"] = "你好奇了？真不错。我知道，惯常的商品打动不了你们，但马丁有自己的办法。",
            ["ContentJP"] = "好奇心が湧いてきたようで非常にグッド！私はもう理解しましたからね？ノーマルな商品であなた様のお眼鏡にはかなわないと！",
            ["DialogueId"] = 51000913,
            ["GUID"] = "7FACE94A",
            ["NextDialogue"] = 51000991,
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Explain01_Start",
                },
            },
        [51000914] = {
            ["Content"] = "如果你们能帮它们找到主人，或许就能更加了解这个城市，哪怕什么也没得到，至少你们满足了自己的好奇心。",
            ["ContentJP"] = "彼らの主人を発見できれば、あなた様はより深くこの街を知れるでしょう。\
何も得られなかった場合でも、いくばくかの好奇心は満たせるかと思います。",
            ["DialogueId"] = 51000914,
            ["GUID"] = "7FACE974",
            ["NextDialogue"] = 51000915,
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Explain01_End",
                },
            },
        [51000915] = {
            ["Content"] = "（马丁变出了一些无法具体名状的东西，然后朝着你们挤了挤眼睛。）",
            ["ContentJP"] = "（マーティンは名も知らぬ品々を魔法のように次々と取り出しながら、あなたに向かってウィンクした）",
            ["DialogueId"] = 51000915,
            ["GUID"] = "7FACE99E",
            ["NextDialogue"] = 51000916,
            },
        [51000916] = {
            ["Content"] = "想试试吗？",
            ["ContentJP"] = "どうでしょう？試してみませんか？",
            ["DialogueId"] = 51000916,
            ["GUID"] = "7FACE9C8",
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Talk01_Start",
                },
            },
        [51000917] = {
            ["Content"] = "祝您寻人顺利，侦探阁下。",
            ["ContentJP"] = "それでは名探偵閣下、人探しが成功するようお祈りしておきますね。",
            ["DialogueId"] = 51000917,
            ["GUID"] = "7FACE9F2",
            ["SpeakNpcId"] = 700022,
            ["TalkActionId"] = {
                [1] = "700022:Talk01_End",
                },
            },
        [51000918] = {
            ["Content"] = "进展得还顺利吗，侦探阁下？",
            ["ContentJP"] = "上手くいきましたか？名探偵閣下？",
            ["DialogueId"] = 51000918,
            ["GUID"] = "7FACEA1C",
            ["SpeakNpcId"] = 700022,
            },
        [51000990] = {
            ["Content"] = "我的名字想必已经无需重复，我就是马丁。",
            ["ContentJP"] = "そんな私のネームはぁ……もったいぶる要もないですかね？\
どうもどうも、マーティンです。",
            ["DialogueId"] = 51000990,
            ["GUID"] = "7FACF5EC",
            ["NextDialogue"] = 51000912,
            ["SpeakNpcId"] = 700022,
            },
        [51000991] = {
            ["Content"] = "我愿意把“谜题”卖给你们，你们可以把它们当做“某人的心结”或者“失物”。",
            ["ContentJP"] = "ですがこのマーティンにはとっておきの品がございまして……\
「クエスチョン」をお売りいたします。それを「誰かの心に刺さる棘」とするのか、はたまた「失せ物」とするのかはご自由に。",
            ["DialogueId"] = 51000991,
            ["GUID"] = "7FACF616",
            ["NextDialogue"] = 51000914,
            ["SpeakNpcId"] = 700022,
            },
        [51001001] = {
            ["Camera"] = "30.150391,500.332031,170.427734,0.000075,-9.398094,-93.777969,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（你远远地就看到一个商贩打扮的人站在售票处，他和售票员似乎起了些摩擦）",
            ["ContentJP"] = "（遠くの切符売り場で行商と思しき人が立っている。切符の販売員と何やら揉めているようだ）",
            ["DialogueId"] = 51001001,
            ["GUID"] = "7FACF7BA",
            ["LookAt"] = {
                [1] = "700021:n(700033)",
                },
            ["NextDialogue"] = 51001002,
            },
        [51001002] = {
            ["Camera"] = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
            ["Content"] = "我只是问问都不行吗！你妈妈没教你礼貌吗？！",
            ["ContentJP"] = "なんだその態度は！値段を聞いちゃいけないってのか！\
どんな口の利き方を母親から教わったんだよ！？",
            ["DialogueId"] = 51001002,
            ["GUID"] = "7FACF7E4",
            ["LookAt"] = {
                [1] = "0:n(700033)",
                },
            ["NextDialogue"] = 51001003,
            ["SpeakNpcId"] = 700033,
            ["TalkActionId"] = {
                [1] = "700033:Angry01_Start",
                },
            },
        [51001003] = {
            ["Camera"] = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
            ["Content"] = "哦好的先生，那么在我礼貌地告诉你票价后，你打算怎么做？",
            ["ContentJP"] = "あぁ、これは失礼しました。しかしお客様、私が切符の値段を懇切丁寧にお教えしたとして、どうなさるおつもりで？",
            ["DialogueId"] = 51001003,
            ["GUID"] = "7FACF80E",
            ["LookAt"] = {
                [1] = "0:n(700021)",
                },
            ["NextDialogue"] = 51001090,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Talk01_Start",
                },
            },
        [51001004] = {
            ["Camera"] = "117.787109,-25.775391,128.833679,0.000042,-3.198543,-174.177307,35.0,200.0,false,Manual,2.8",
            ["Content"] = "你你怎么知道我没……",
            ["ContentJP"] = "な、なにを根拠に言ってるんだよ？俺が一文無しだとでもいうつもりか……",
            ["DialogueId"] = 51001004,
            ["GUID"] = "7FACF838",
            ["LookAt"] = {
                [1] = "0:n(700033)",
                },
            ["NextDialogue"] = 51001005,
            ["SpeakNpcId"] = 700033,
            ["TalkActionId"] = {
                [1] = "700033:Angry01_End",
                },
            },
        [51001005] = {
            ["Camera"] = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
            ["Content"] = "滚吧住在窝棚板里的大富豪。",
            ["ContentJP"] = "どうぞお引き取りください、あばら家のご主人様。",
            ["DialogueId"] = 51001005,
            ["GUID"] = "7FACF862",
            ["LookAt"] = {
                [1] = "0:n(700021)",
                },
            ["NextDialogue"] = 51001091,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Talk01_End",
                },
            },
        [51001006] = {
            ["Camera"] = "319.767578,148.608398,91.180664,0.000064,-0.797267,-149.347275,35.0,400.0,false,Manual,2.8",
            ["Content"] = "（商贩哆嗦着嘴唇转身就走，而售票员高傲地哼了一声，不屑地瞥向你们。）",
            ["ContentJP"] = "（行商人は唇を震わせながら、身を翻して立ち去った。販売員は誇らしげに鼻を鳴らすと、今度はあなたの方を軽蔑の眼差しで見てくる）",
            ["DialogueId"] = 51001006,
            ["GUID"] = "7FACF88C",
            ["LookAt"] = {
                [1] = "0:n(700033)",
                },
            ["NextDialogue"] = 51001007,
            ["Scripts"] = "MoveTo{ActorId{700033},TargetPoint{\"Point200202_Shangfan\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            },
        [51001007] = {
            ["Content"] = "你呢？你又有什么事？我劝你不要浪费我的时间，不然你只能和他一样灰溜溜地滚回自己的老鼠洞。",
            ["ContentJP"] = "おやおや、あなた様も何かご用で？私の時間を無駄にする魂胆でしょうが、お勧めはしませんよ？さっきのアレと同じように自分の巣であるドブ穴に、醜態をさらして逃げ帰る羽目になるかと。",
            ["DefaultLookAt"] = "Self",
            ["DialogueId"] = 51001007,
            ["GUID"] = "7FACF8B6",
            ["LookAt"] = {
                [1] = "0:n(700021)",
                },
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Talk03_Start",
                },
            ["TalkOptions"] = {
                [1] = 510010071,
                [2] = 510010072,
                },
            ["TurnTo"] = {
                [1] = "700021:n(0)",
                },
            },
        [51001008] = {
            ["Content"] = "又一个！我不管你在虚张声势些什么，在我对你发出诚挚的问候之前，你最好赶紧消失！",
            ["ContentJP"] = "何をごちゃごちゃと！これ以上根拠のない御託を並べるなら、あんたとも「懇切丁寧」にお話してあげましょうかね！さっさと消えてくださいな、この身のほど知らずめ！",
            ["DialogueId"] = 51001008,
            ["GUID"] = "7FACF8E0",
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Talk03_End",
                },
            },
        [51001009] = {
            ["Content"] = "你、你在说什么，我可听不懂！",
            ["ContentJP"] = "な、何を仰っているの……意味がわからない！",
            ["DialogueId"] = 51001009,
            ["GUID"] = "7FACF90A",
            ["NextDialogue"] = 51001010,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Talk03_End",
                },
            },
        [51001010] = {
            ["Content"] = "（你拿出从马丁那拿来的“废品”，一罐用纸叠出来的五角星，你展开其中一颗，俨然是一张已经过期的废票。）",
            ["ContentJP"] = "（マーティンからもらった「ジャンク品」を取り出した。折り紙の星を1つ手に取って広げてみると、期限切れの切符だ）",
            ["DialogueId"] = 51001010,
            ["GUID"] = "7FACF934",
            },
        [51001012] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51001012,
            ["GUID"] = "7FACF988",
            ["NextDialogue"] = 51001013,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Shock_Start",
                },
            },
        [51001013] = {
            ["Content"] = "（她好像陷入了极度的震惊，很快，两行眼泪从这个趾高气昂的售票员脸上流了下来。）",
            ["ContentJP"] = "（彼女は相当なショックを受けたのか、威張っていた表情が崩れて、二筋の涙がこぼれ落ちた）",
            ["DialogueId"] = 51001013,
            ["GUID"] = "7FACF9B2",
            ["NextDialogue"] = 51001014,
            },
        [51001014] = {
            ["Content"] = "为什么……为什么要让我再看到它？",
            ["ContentJP"] = "どうして……どうしてまた……それを私に見せるの？",
            ["DialogueId"] = 51001014,
            ["GUID"] = "7FACF9DC",
            ["NextDialogue"] = 51001015,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Shock_End",
                },
            },
        [51001015] = {
            ["Content"] = "为什么要提醒我不能实现的梦？",
            ["ContentJP"] = "叶わない夢なのに……どうして思い出させるのよ……",
            ["DialogueId"] = 51001015,
            ["GUID"] = "7FACFA06",
            ["NextDialogue"] = 51001016,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Disagree",
                },
            },
        [51001016] = {
            ["Content"] = "每天，我看着火车轰鸣而来，又看着它呼啸而去，我希望能和那些达官贵人一样乘上去，但留给我的只有卖不完的票。",
            ["ContentJP"] = "毎日、汽車が轟音をあげてやって来て、また吠えるように去っていって……私もあの高貴な人たちみたいに、乗ってみたいなって。だけど私が手にできるのは、売れても売れてもキリがない切符だけ。",
            ["DialogueId"] = 51001016,
            ["GUID"] = "7FACFA30",
            ["NextDialogue"] = 51001017,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Explain02_Start",
                },
            },
        [51001017] = {
            ["Content"] = "有的人活了一辈子都没见过车票长什么样，我比他们的运气好一些，好歹能每天都握着这张无法兑现的入场券。",
            ["ContentJP"] = "一生で一度も切符を見れない人だっているのは知っているわ。この夢への入場券に毎日触れられるだけで、そんな人たちよりも運がいいことだって。",
            ["DialogueId"] = 51001017,
            ["GUID"] = "7FACFA5A",
            ["NextDialogue"] = 51001018,
            ["SpeakNpcId"] = 700021,
            },
        [51001018] = {
            ["Content"] = "但我的好运也就到此为止了，这个世界上有的是连星星都无法实现的愿望，我正是意识到这一点，才将它们丢弃……",
            ["ContentJP"] = "でもそこまでなの。それ以上の先へは進めない。この世の中は叶えられない願いであふれているから。星に頼っても無駄だと気づいて……私は星を捨てた……",
            ["DialogueId"] = 51001018,
            ["GUID"] = "7FACFA84",
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Explain02_End",
                },
            ["TalkOptions"] = {
                [1] = 510010181,
                [2] = 510010182,
                [3] = 510010183,
                [4] = 510010184,
                },
            },
        [51001019] = {
            ["Content"] = "那么谁来为我搭这条天梯呢？仙女教母吗？",
            ["ContentJP"] = "その方法は誰が教えてくれるの？お人好しの妖精さん？魔法使い？私なんかのために誰が断崖にハシゴをかけてくれるのよ？",
            ["DialogueId"] = 51001019,
            ["GUID"] = "7FACFAAE",
            ["NextDialogue"] = 51001023,
            ["SpeakNpcId"] = 700021,
            },
        [51001020] = {
            ["Content"] = "你说得对，我和他们又有什么差别呢？",
            ["ContentJP"] = "それは……あなたの言うとおりね。私とあの人たちに違いなんてないのにね？",
            ["DialogueId"] = 51001020,
            ["GUID"] = "7FACFAD8",
            ["NextDialogue"] = 51001023,
            ["SpeakNpcId"] = 700021,
            },
        [51001021] = {
            ["Content"] = "是啊……我还不能失去这份我痛恨又赖以生存的工作。",
            ["ContentJP"] = "そうね……大嫌いな仕事でも、生きていくためには失うわけにはいかないものね。",
            ["DialogueId"] = 51001021,
            ["GUID"] = "7FACFB02",
            ["NextDialogue"] = 51001023,
            ["SpeakNpcId"] = 700021,
            },
        [51001022] = {
            ["Content"] = "我是有些疾世愤俗，但还没发疯，不过也许那一天也不远了。",
            ["ContentJP"] = "私は世の中にうんざりしてるけど、そこまで狂ってはいないから。まあ狂う日は遠くないかもしれないけど……",
            ["DialogueId"] = 51001022,
            ["GUID"] = "7FACFB2C",
            ["NextDialogue"] = 51001023,
            ["SpeakNpcId"] = 700021,
            },
        [51001023] = {
            ["Content"] = "（售票员拿走了你手中的车票星星，找了个干燥的地方将这些寄宿着心愿的纸片付之一炬）",
            ["ContentJP"] = "（販売員はあなたから切符の星を受け取った。そして乾燥した場所を探して、願いを宿した紙くずを燃やした）",
            ["DialogueId"] = 51001023,
            ["GUID"] = "7FACFB56",
            ["NextDialogue"] = 51001024,
            ["SpeakNpcId"] = 700021,
            },
        [51001024] = {
            ["Content"] = "我总是骂那些想离开的家伙是做梦，",
            ["ContentJP"] = "あばら家から出ていこうとする人に、私はいつも夢を見るなって罵ってきたけど。",
            ["DialogueId"] = 51001024,
            ["GUID"] = "7FACFB80",
            ["NextDialogue"] = 51001025,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Explain01_Start",
                },
            },
        [51001025] = {
            ["Content"] = "但也许该从梦中醒来的是我自己。",
            ["ContentJP"] = "一番は私自身よね、夢から目覚めなきゃいけないのは。",
            ["DialogueId"] = 51001025,
            ["GUID"] = "7FACFBAA",
            ["NextDialogue"] = 51001026,
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Explain01_End",
                },
            },
        [51001026] = {
            ["Content"] = "（从此以后，杰西卡只是漠然地坐在售票厅里，不管谁问她都能得到机械的回答，好像某种售票的机器。）",
            ["ContentJP"] = "（以降のジェシカは、無表情で切符売り場に立つようになった。まるで券売機のように誰が尋ねても機械的に答えを返す。）",
            ["DialogueId"] = 51001026,
            ["GUID"] = "7FACFBD4",
            },
        [51001027] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51001027,
            ["GUID"] = "7FACFBFE",
            ["SpeakNpcId"] = 700021,
            },
        [51001090] = {
            ["Camera"] = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
            ["Content"] = "是礼貌地掏出一笔巨款向我买票，还是搓搓自己漏不出一个子儿的裤兜对我颐指气使？",
            ["ContentJP"] = "礼儀正しく正規料金を支払って、切符をお買い上げくださるのでしょうか？\
\
銅貨1枚も入ってないボロっちいズボンのポケットをさぐっていらっしゃいますが、まさかまさか私の口の利き方に文句をつけるおつもりではございませんよね？",
            ["DialogueId"] = 51001090,
            ["GUID"] = "7FAD0654",
            ["LookAt"] = {
                [1] = "0:n(700021)",
                },
            ["NextDialogue"] = 51001004,
            ["SpeakNpcId"] = 700021,
            },
        [51001091] = {
            ["Camera"] = "-104.777344,10.944336,99.62793,0.000124,-3.797551,-18.159431,35.0,200.0,false,Manual,2.8",
            ["Content"] = "这天气正适合你一边擦火柴一边叫奶奶，在梦里亲奶奶带你坐火车，到时候你想去哪去哪，再也不用在我跟前丢人现眼！",
            ["ContentJP"] = "今日の天気はマッチを擦って死んだおばあさんに想いを馳せるには絶好の日和ですよ。夢の中でおばあさんに泣きつくのはいかがでしょうか？汽車に乗せて欲しいってお願いして、お好きなところへどこにでも。そうすれば金輪際、私の前で恥をかくことはなくなりますし！",
            ["DialogueId"] = 51001091,
            ["GUID"] = "7FAD067E",
            ["LookAt"] = {
                [1] = "0:n(700021)",
                },
            ["NextDialogue"] = 51001006,
            ["SpeakNpcId"] = 700021,
            },
        [51001092] = {
            ["Content"] = "（不过好事是她再也不像从前一样脾气暴躁，骂骂咧咧了。）",
            ["ContentJP"] = "（冷たく感じるが、少なくとも皮肉めいた悪口をまくしたてるよりはいいだろう）",
            ["DialogueId"] = 51001092,
            ["GUID"] = "7FAD06A8",
            },
        [51001101] = {
            ["Content"] = "（不知从何处游荡而来的秽兽叼着一个记事本，击败秽兽后，你将它捡了起来……）",
            ["ContentJP"] = "（どこからやってきたのだろうか。何かを咥えた穢獣がいたので倒してみると、それは日記だった……）",
            ["DialogueId"] = 51001101,
            ["GUID"] = "7FAD0822",
            ["NextDialogue"] = 51001102,
            },
        [51001102] = {
            ["Content"] = "（如果日记上记录的内容属实，那么失忆少女的真实身份，就已十分明了了。同样水落石出的，还有爱尔莎夫人那个失踪的女儿，安妮的下落……）",
            ["ContentJP"] = "（もしこの日記に書かれていることが本当なら――少女の正体は明らかになる。）",
            ["DialogueId"] = 51001102,
            ["GUID"] = "7FAD084C",
            ["NextDialogue"] = 51001103,
            },
        [51001103] = {
            ["Content"] = "（……安妮已经不幸离世，而得到她衣物的另一位少女爱丽丝活了下来。尽管在雪山幸存，但连续高烧还是夺走了爱丽丝的记忆。）",
            ["ContentJP"] = "（残念ながら生きるという旅を終えてしまったアニー。そんな彼女から服をもらったアリスは、高熱のせいで記憶を失いながらも生き延びたのだろう）",
            ["DialogueId"] = 51001103,
            ["GUID"] = "7FAD0876",
            },
        [51001201] = {
            ["Content"] = "居然有狩月人能找到这里，看来你和它们一样，有着成为英雄的可能啊。",
            ["ContentJP"] = "月狩り人がここを見つけるとはな。お前さん、英雄になれる素質があるぞ。\
あいつらみたいな。",
            ["DialogueId"] = 51001201,
            ["GUID"] = "7FAD188A",
            ["NextDialogue"] = 51001212,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Explain01_Start",
                },
            },
        [51001202] = {
            ["Content"] = "嗯，除了我这怪老头，应该也没其他人会养金翎鸟了。",
            ["ContentJP"] = "ああ、そうだ。カナリアを飼うなんて、俺みたいな変わり者くらいさ。",
            ["DialogueId"] = 51001202,
            ["GUID"] = "7FAD18B4",
            ["NextDialogue"] = 51001204,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Explain01_End",
                },
            },
        [51001203] = {
            ["Content"] = "吃？？你知道金翎鸟对矿工来说有多珍贵吗！",
            ["ContentJP"] = "食べるだと？！鉱夫にとってカナリアがどれほど大切だと思ってるんだ！",
            ["DialogueId"] = 51001203,
            ["GUID"] = "7FAD18DE",
            ["NextDialogue"] = 51001204,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Disagree",
                },
            },
        [51001204] = {
            ["Content"] = "矿工们越加依赖炼金院鼓捣出来的那些高科技，反而忽视了传统的探测手段。",
            ["ContentJP"] = "最近は鉱夫も錬金院の技術を頼るようになってな。\
昔ながらの検知方法は廃れちまった。",
            ["DialogueId"] = 51001204,
            ["GUID"] = "7FAD1908",
            ["NextOptions"] = {
                [1] = 510012041,
                [2] = 510012042,
                [3] = 510012043,
                },
            ["SpeakNpcId"] = 700003,
            ["bForbidSkipOptions"] = true,
            },
        [51001205] = {
            ["Content"] = "是啊，正因为它们对毒气格外敏感，以前我们在进行地下工作的时候都会带一只在身边，帮我们探测坑道是否安全。",
            ["ContentJP"] = "その通り、カナリアは有毒ガスに敏感だからな。昔は、坑道の安全を確かめるのにカナリアを連れていったんだ。",
            ["DialogueId"] = 51001205,
            ["GUID"] = "7FAD1932",
            ["NextDialogue"] = 51001208,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Agree",
                },
            },
        [51001206] = {
            ["Content"] = "不错，真是不错，现在像你这样有独特理解的年轻人可不多了。",
            ["ContentJP"] = "そうそう、その通りだ。お前さんみたいに自分の頭で物事を考えられる若者は珍しい。",
            ["DialogueId"] = 51001206,
            ["GUID"] = "7FAD195C",
            ["NextDialogue"] = 51001208,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Explain01_Start",
                },
            },
        [51001207] = {
            ["Content"] = "哼，我做这些是为了矿工，不需要他人的理解。",
            ["ContentJP"] = "フン、俺は鉱夫たちのためにやっているんだ。わかってもらえなくても構わんさ。",
            ["DialogueId"] = 51001207,
            ["GUID"] = "7FAD1986",
            ["NextDialogue"] = 51001208,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Explain01_End",
                },
            },
        }
  end },
  { MinKey = 51001208, MaxKey = 51002028, Loader = function()
      return {
        [51001208] = {
            ["Content"] = "没有灵魂的工具会失灵，会背叛。倾注情感的伙伴才会陪你度过每一个难关。",
            ["ContentJP"] = "魂を持たない道具はいつか故障する。俺たちを裏切るんだ。\
どんな困難も一緒に乗り越えてくれるのは、感情を分かち合う仲間だけだ。",
            ["DialogueId"] = 51001208,
            ["GUID"] = "7FAD19B0",
            ["NextDialogue"] = 51001209,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Think_Start",
                },
            },
        [51001209] = {
            ["Content"] = "等哪天炼金院的那些探测工具失灵了，也许还能靠这些伙伴们挽回更多矿工的生命……",
            ["ContentJP"] = "いつか錬金院の検知機械が壊れたとき、こいつのおかげで鉱夫の命を救えるかも知れん……",
            ["DialogueId"] = 51001209,
            ["GUID"] = "7FAD19DA",
            ["NextDialogue"] = 51001210,
            ["SpeakNpcId"] = 700003,
            ["TalkActionId"] = {
                [1] = "700003:Think_End",
                },
            },
        [51001210] = {
            ["Content"] = "（老人看向一旁的土堆，嘴唇微动，努力地想要再说些什么，最终只从嘴里吐出一声叹息。）",
            ["ContentJP"] = "（老人は傍らの土の山に目を向けた。唇がわずかに動き、何かを言おうとしたようだが、結局はため息だけが漏れた）",
            ["DialogueId"] = 51001210,
            ["GUID"] = "7FAD1A04",
            },
        [51001211] = {
            ["Content"] = "（老人不发一语，只是每过一会，就从回忆中抽身，缓缓吐出一声叹息。不知是对同伴的缅怀，还是对时代变迁的感叹。）",
            ["ContentJP"] = "（老人は黙り込んでいる。ただ時折、過去から現実に引き戻されたように、ゆっくりとため息をつく。それは仲間への追憶か、時代の変化への嘆きなのだろうか…）",
            ["DialogueId"] = 51001211,
            ["GUID"] = "7FAD1A2E",
            },
        [51001212] = {
            ["Content"] = "老人温柔地注视着空中的一小片黑点，你顺着他的视线远眺，看到了一群离去的飞鸟。待到所有鸟群飞走后，老人才转身继续与你交谈。",
            ["ContentJP"] = "老人は、空に浮かぶ小さな黒点を優しい目で見つめていた。あなたも視線を上げると、はるか遠く空へ飛ぶ鳥の群れが見えた。最後の一羽が消えたのち、老人はようやくこっちに向き直った。",
            ["DialogueId"] = 51001212,
            ["GUID"] = "7FAD188B",
            ["NextOptions"] = {
                [1] = 510012011,
                [2] = 510012012,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51001301] = {
            ["Content"] = "天杀的卡米拉！不识货的瞎眼婆娘！",
            ["ContentJP"] = "カミラめ！モノの価値がわからないもうろくババアが！",
            ["DialogueId"] = 51001301,
            ["GUID"] = "7FAD28F2",
            ["NextDialogue"] = 510013013,
            ["SpeakNpcId"] = 700014,
            },
        [51001302] = {
            ["Content"] = "我呸！老子骂两句怎么了！",
            ["ContentJP"] = "ちっ！罵ったくらいでどうだってんだ！",
            ["DialogueId"] = 51001302,
            ["GUID"] = "7FAD291C",
            ["NextDialogue"] = 51001304,
            ["SpeakNpcId"] = 700014,
            },
        [51001303] = {
            ["Content"] = "医药费！必须给我医药费！你快把我鼻子打歪了！",
            ["ContentJP"] = "いってぇ！鼻が折れそうだ。おい、治療費を寄こせ。",
            ["DialogueId"] = 51001303,
            ["GUID"] = "7FAD2946",
            ["NextDialogue"] = 51001304,
            ["SpeakNpcId"] = 700014,
            },
        [51001304] = {
            ["Content"] = "这么着急替她出头？哈，我知道了，你也是“卡米拉后援会”的蠢蛋之一！可悲啊，被那个虚伪的女人骗得团团转！",
            ["ContentJP"] = "そんなに慌ててあの女を庇うとはな。さてはお前も「カミラ後援会」のアホか！あのネコかぶり女に騙されて、気の毒にな！",
            ["DialogueId"] = 51001304,
            ["GUID"] = "7FAD2970",
            ["NextOptions"] = {
                [1] = 510013041,
                [2] = 510013042,
                [3] = 510013043,
                },
            ["SpeakNpcId"] = 700014,
            ["bForbidSkipOptions"] = true,
            },
        [51001305] = {
            ["Content"] = "嘴巴刚刚不还挺能说的吗，怎么，脑袋终于被冷风吹醒，看清那婆娘了？",
            ["ContentJP"] = "さっきまでよく喋っていたのに、どうしたんだ？冷たい風で目が覚めたのか、その女がどんなやつか分かったか？",
            ["DialogueId"] = 51001305,
            ["GUID"] = "7FAD299A",
            ["SpeakNpcId"] = 700014,
            },
        [51001306] = {
            ["Content"] = "你，你说什么……",
            ["ContentJP"] = "何だと、お前…",
            ["DialogueId"] = 51001306,
            ["GUID"] = "7FAD29C4",
            ["NextDialogue"] = 510013061,
            ["SpeakNpcId"] = 700014,
            },
        [51001307] = {
            ["Camera"] = "-189.380859,-54.21875,122.534668,0.000015,3.499987,-5.919168,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "如果你货比三家，就会发现卡米拉售卖的发酵饮品和冰湖城格格不入。",
            ["ContentJP"] = "ほかの店と比べてみりゃわかるさ。カミラの売っているものはアイスレイク城のほかの店とは違うって。",
            ["DialogueId"] = 51001307,
            ["GUID"] = "7FAD29EE",
            ["LookAt"] = {
                [1] = "700014:n(100001)",
                [2] = "100001:n(700014)",
                },
            ["NextDialogue"] = 51001308,
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Explain01_Start",
                },
            },
        [51001308] = {
            ["Content"] = "冰湖城里所有的饮品老板都和我有合作，我家的手艺有口皆碑，只有她拒绝加入，油盐不进的家伙！你就不觉得这里面有猫腻吗？！",
            ["ContentJP"] = "この街の酒場のオーナーはみんな俺の取引相手さ。うちで扱うものはすごぶる評判がいいってのに、カミラだけは頑として俺と手を組まない。なにか裏がありそうだとは思わないか？",
            ["DialogueId"] = 51001308,
            ["GUID"] = "7FAD2A18",
            ["NextDialogue"] = 51001309,
            ["Scripts"] = "PlayAnimation{_delay{2.5},ActorId{700014},AnimationId{\"Explain02_End\"},Duration{0}}",
            ["SpeakNpcId"] = 700014,
            ["TalkActionId"] = {
                [1] = "700014:Explain02_Start",
                },
            },
        [51001309] = {
            ["Content"] = "事实是，我的发酵饮品价格只有卡米拉的一半，而且口味几乎没有差别，我敢保证！只要在我这里尝试一次，就能体会到“实惠”的味道。",
            ["ContentJP"] = "俺が卸す酒はカミラの店の半額、味はほとんど同じだ。保証するぜ！一度だけ味見すれば、「お値打ち」な味をわかってもらえるはずだ。",
            ["DialogueId"] = 51001309,
            ["GUID"] = "7FAD2A42",
