        [51002106] = {
            ["Camera"] = "-160.396484,-385.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（这些秽兽并不是你的对手，但这小小的插曲让你感到了一丝熟悉，久远的回忆开始苏醒，你仿佛听到了两个小孩在这间房子前打闹的声音。）",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>は問題なく倒せたが、不意に胸の奥で何かが震えた──この家の前で遊んでいた子どもたちの声が、記憶の底から蘇る。",
            ["DialogueId"] = 51002106,
            ["FinalCamera"] = "-160.396484,-404.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC89",
            ["NextDialogue"] = 51002107,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002107] = {
            ["Camera"] = "119.585938,-26.257812,128.0,-0.0,-9.999997,-145.798935,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想起来了，小时候我和这家的小孩打过一架。名字我已经记不清了，算起来，应该是布鲁内托的孙子吧。",
            ["ContentJP"] = "思い出した……小さいころ、ここで誰かとケンカしたんだ。名前はもう思い出せないけど、たぶんブルネットの孫だったのかな。",
            ["DialogueId"] = 51002107,
            ["FinalCamera"] = "119.585938,-26.257812,128.0,0.0,-9.999997,-138.598923,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC8A",
            ["NextDialogue"] = 51002108,
            ["Scripts"] = "TurnTo{_delay{3},TurnToDescription{\"100001:n(700211)\"}}",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002108] = {
            ["Camera"] = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "起因是什么已经想不起来了，但我还记得开打前的最后一句话是……那小鬼喊我独眼龙，我骂他是眼睛鼓鼓的大青蛙。",
            ["ContentJP"] = "何がきっかけだったか忘れたけど、あの子が「一つ目」ってからかってきて、こっちは「カエル顔」って言い返したんだっけ。",
            ["DialogueId"] = 51002108,
            ["GUID"] = "7FADAC8B",
            ["NextDialogue"] = 51002109,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Think_Start\"},Duration{2}},\
CameraMoveTo{_delay{3},TargetPosition{\"88.632812,-31.105469,133.52002,0.000039,-12.79989,-135.199905,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},\
PlayAnimation{_delay{1},ActorId{700211},AnimationId{\"Angry01_Start\"},Duration{1}},\
}",
            ["SpeakNpcId"] = 100001,
            },
        [51002109] = {
            ["Camera"] = "-143.595703,-312.263672,94.0,0.0,0.0,57.398624,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈，原来我也有这么口无遮拦的时候……现在想想，那时候我好像也没有那么生气，因为再怎么说，我的身边还有贝蕾在。",
            ["ContentJP"] = "普段なら、そんな強気になることもないのに。今思えば、そんなに怒ってなかった気がする。隣にベレがいたからかな……",
            ["DialogueId"] = 51002109,
            ["GUID"] = "7FADAC8C",
            ["NextDialogue"] = 51002110,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Sigh_Start\"},Duration{3}},\
PlayAnimation{ActorId{100001},AnimationId{\"Sigh_End\"},Duration{2}},\
PlayAnimation{ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}\
}",
            ["SpeakNpcId"] = 100001,
            },
        [51002110] = {
            ["Camera"] = "70.748047,32.113281,1751.04126,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "后来……好像是和好了吧？我记得我们爬到屋顶上……",
            ["ContentJP"] = "そのあと、一緒に屋根に登って……たしか、仲直りしたんだ。",
            ["DialogueId"] = 51002110,
            ["FinalCamera"] = "70.748047,32.113281,1859.0,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC8D",
            ["SpeakNpcId"] = 100001,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002111] = {
            ["Camera"] = "51.001041,365.471497,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊对，就是在这儿，过了几天他拿着一袋吃的和我道歉。我本来还想骂他来着，但看着那三人份的面包，最后还是让馋虫战胜了尊严。",
            ["ContentJP"] = "うん、ここだ。あのあと、向こうが謝りに来たんだ。食べ物を持ってね。最初は怒ってやろうと思ったのに、三人分のパンを見たら、もう何も言えなかった。",
            ["DialogueId"] = 51002111,
            ["FinalCamera"] = "14.224466,404.913452,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC8E",
            ["NextDialogue"] = 51002112,
            ["SpeakNpcId"] = 700210,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002112] = {
            ["Camera"] = "-78.281792,63.089108,96.67688,0.000094,-0.099919,90.79702,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……我们三个就这样坐在屋顶默默地吃着又硬又焦的面包，看着日头渐斜，大人们载着打来的鱼回村。",
            ["ContentJP"] = "三人で並んで、固くて焦げたパンをかじりながら、夕暮れの空を眺めたっけ。大人たちが漁から戻ってくる姿も見えたんだった。",
            ["DialogueId"] = 51002112,
            ["FinalCamera"] = "-123.657745,62.460995,96.67688,0.000094,-0.099919,90.797005,20.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC8F",
            ["NextDialogue"] = 51002113,
            ["SpeakNpcId"] = 700210,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002113] = {
            ["Camera"] = "-182.640976,408.587311,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最后那小鬼噎着了，连着打了一串嗝。我们三个一起笑了，那次吵架就这么过去了。",
            ["ContentJP"] = "最後は、あの子がパンを喉につまらせて、みんなで大笑いして……それで、全部どうでもよくなったんだ。",
            ["DialogueId"] = 51002113,
            ["FacialId"] = {
                [1] = "700210:Ahaha02",
                },
            ["FinalCamera"] = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC90",
            ["NextDialogue"] = 51002114,
            ["SpeakNpcId"] = 700210,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002114] = {
            ["Camera"] = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "四舍五入的话，我从那个时候就已经认识布鲁内托了吧。",
            ["ContentJP"] = "そう考えると、あの頃からブルネットさんとは縁があったってことかな。",
            ["DialogueId"] = 51002114,
            ["FacialId"] = {
                [1] = "700210:Smile02",
                },
            ["GUID"] = "7FADAC91",
            ["NextDialogue"] = 51002115,
            ["SpeakNpcId"] = 700210,
            },
        [51002115] = {
            ["Camera"] = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果实在什么都找不到的话，帮我带点东西回来吧，什么都行，一片草叶也行。",
            ["ContentJP"] = "何も見つからなかったら、葉っぱ一枚でもいい。持って帰ってきてくれ。",
            ["DialogueId"] = 51002115,
            ["GUID"] = "7FADAC92",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030106.T_Story_Recall_10030106'",
            ["NextDialogue"] = 51002116,
            ["SpeakNpcId"] = 700048,
            },
        [51002116] = {
            ["Camera"] = "167.319687,115.790215,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "再给布鲁内托带点特产吧，这个季节的鱼我记得都很肥美。",
            ["ContentJP"] = "せっかくだし、ブルネットさんに土産を持って帰ろう。今なら魚がたくさん獲れるはず。",
            ["DialogueId"] = 51002116,
            ["FinalCamera"] = "181.948135,137.309357,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FADAC93",
            ["SpeakNpcId"] = 700210,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51002117] = {
            ["Content"] = "回去吧，这些应该能够缓解布鲁内托的乡愁了。",
            ["ContentJP"] = "よし、ブルネットさん、喜んでくれるといいな。",
            ["DialogueId"] = 51002117,
            ["Duration"] = 3,
            ["GUID"] = "7FADAC94",
            ["NextDialogue"] = 51002118,
            ["SpeakNpcId"] = 100001,
            },
        [51002118] = {
            ["Content"] = "孙子通过打架认识，爷爷通过坑骗认识……哈……真是奇怪的缘分……",
            ["ContentJP"] = "孫とはケンカで仲良くなって、ブルネットさんとは騙されることで仲良くなるなんて……ほんと、不思議な縁だ。",
            ["DialogueId"] = 51002118,
            ["Duration"] = 4,
            ["GUID"] = "7FADAC95",
            ["SpeakNpcId"] = 100001,
            },
        [51002201] = {
            ["Content"] = "来往的朋友，稍微停一停脚步，给上几个银币，您就能加入冰湖城渔夫互助会，获得最好最新的——啊！是你……",
            ["ContentJP"] = "そこ行く人よ皆の衆よ、ちょいとこちらに寄っとくれ。なんと銅貨数枚っぽちの元手で、アイスレイク城の漁師互助会に加入できるのさ。そして最高かつ最新の――あ！君は……",
            ["DialogueId"] = 51002201,
            ["GUID"] = "7FADBC9A",
            ["NextDialogue"] = 51002202,
            ["SpeakNpcId"] = 700048,
            },
        [51002202] = {
            ["Content"] = "这应该是你的东西？",
            ["ContentJP"] = "これって、おじさんの本？",
            ["DialogueId"] = 51002202,
            ["GUID"] = "7FADBCC4",
            ["NextDialogue"] = 51002203,
            ["SpeakNpcId"] = 100001,
            },
        [51002203] = {
            ["Content"] = "啊！没错，这就是我小时候翻来覆去一直在看的书，那时候就是看着这本书，想离开巴掌大的小岛……",
            ["ContentJP"] = "ああ！間違いない、これだ。子どもの頃、飽きもせずに何度も読み返してた本だよ。あのころは、この本を眺めながら、こんな小さな島から飛び出したいって夢見てたんだ……",
            ["DialogueId"] = 51002203,
            ["GUID"] = "7FADBCEE",
            ["NextDialogue"] = 51002204,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Agree",
                },
            },
        [51002204] = {
            ["Content"] = "谢谢，谢谢你，我今天晚上得要好好再翻一遍。不过现在先不说了，唉，挣钱糊口要紧。",
            ["ContentJP"] = "ありがとう、ありがとうな。今晩はこいつをまた、じっくりと読まなきゃだが……何はさておき、おまんま代を稼ぐのが先決だ。",
            ["DialogueId"] = 51002204,
            ["GUID"] = "7FADBD18",
            ["NextDialogue"] = 51002205,
            ["SpeakNpcId"] = 700048,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_Start",
                },
            },
        [51002205] = {
            ["Content"] = "再见，不要再骗人了。哦对了，这些鱼干也拿去，净界岛钓上来做的。",
            ["ContentJP"] = "じゃあね。もう二度と人をだましたりしちゃだめだよ。あ、それと──この干し魚も持っていって。パーガトリー島で釣ってきたんだ。",
            ["DialogueId"] = 51002205,
            ["GUID"] = "7FADBD42",
            ["NextDialogue"] = 51002206,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700048:Explain01_End",
                },
            },
        [51002206] = {
            ["Content"] = "这是……谢谢，真的太谢谢你了……",
            ["ContentJP"] = "これは……ありがとう、本当に……",
            ["DialogueId"] = 51002206,
            ["GUID"] = "7FADBD6C",
            ["SpeakNpcId"] = 700048,
            },
        [51002207] = {
            ["Content"] = "冰湖城渔夫互助会，有兴趣的朋友了解一下，几十年经验老渔夫亲自指导，作为兴趣作为工作都棒极了！",
            ["ContentJP"] = "アイスレイク城の漁師互助会に興味がおありなら聞いとくれ！何十年もの経験を持つベテラン漁師が直々に指導！趣味としても仕事としても最高！手に職つければ将来は安泰、間違いなしだ！",
            ["DialogueId"] = 51002207,
            ["GUID"] = "7FADBD96",
            ["NextDialogue"] = 51002208,
            ["SpeakNpcId"] = 700048,
            },
        [51002208] = {
            ["Content"] = "哎呀，这不是{nickname}吗，都是老乡了，有空我们交流下捕鱼的技术？",
            ["ContentJP"] = "おや、{Nickname}じゃないか。こうしてみると、すっかり同郷だな。今度時間があったら、釣りのコツでも教え合わないか？",
            ["DialogueId"] = 51002208,
            ["GUID"] = "7FADBD97",
            ["NextDialogue"] = 51002209,
            ["SpeakNpcId"] = 700048,
            },
        [51002209] = {
            ["Content"] = "下次一定。",
            ["ContentJP"] = "うん、今度ぜひ。",
            ["DialogueId"] = 51002209,
            ["GUID"] = "7FADBDC0",
            ["SpeakNpcId"] = 100001,
            },
        [51002301] = {
            ["Content"] = "年轻人，你有哈默尔·狄金森的消息了吗？",
            ["ContentJP"] = "お若い方、ハーメル・ディキンソンの消息について何かおわかりになりまして？",
            ["DialogueId"] = 51002301,
            ["GUID"] = "7FADCD02",
            ["NextOptions"] = {
                [1] = 510023011,
                },
            ["SpeakNpcId"] = 700019,
            },
        [51002302] = {
            ["Content"] = "（是的，格雷姆矿坑的那本无名日记，它的扉页写着主人的名字——哈默尔·狄金森。）",
            ["ContentJP"] = "（そうだ、グルビューム鉱山で見つけたあの日記。最初のページに持ち主の名前が書いてあった――ハーメル・ディキンソンって）",
            ["DialogueId"] = 51002302,
            ["GUID"] = "7FADCD2C",
            ["NextDialogue"] = 51002303,
            },
        [51002303] = {
            ["Content"] = "（如果没猜错的话，那只盘踞在矿坑深处的怪物，它的真实身份就是……）",
            ["ContentJP"] = "（恐らくだけど、あの鉱山の奥深くにいた怪物の正体は……）",
            ["DialogueId"] = 51002303,
            ["GUID"] = "7FADCD56",
            ["NextDialogue"] = 51002304,
            },
        [51002304] = {
            ["Content"] = "（从言及那个男人开始，老妇人浑浊的眼睛就有了些光亮，看来哈默尔·狄金森这个名字对她而言并不一般。她在期待着一个答案。）",
            ["ContentJP"] = "（彼について話し始めると、老婦人の虚ろな瞳が少しだけ光を取り戻したように感じた。どうやらハーメル・ディキンソンの名前は彼女にとって特別なモノらしい。彼女は「答え」を待っているのだ）",
            ["DialogueId"] = 51002304,
            ["GUID"] = "7FADCD80",
            ["NextOptions"] = {
                [1] = 510023041,
                [2] = 510023042,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51002305] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51002305,
            ["GUID"] = "7FADCDAA",
            ["NextDialogue"] = 51002306,
            ["SpeakNpcId"] = 700019,
            },
        [51002306] = {
            ["Content"] = "（老妇人逐字逐句地默念着那本日记。泪水从她满是皱纹的眼角不断滚落。）",
            ["ContentJP"] = "（老婦人は書かれた1文字も見逃すまいと日記を熟読する。そしてシワだらけの目尻から感情がこぼれ落ちた）",
            ["DialogueId"] = 51002306,
            ["GUID"] = "7FADCDD4",
            ["NextDialogue"] = 51002307,
            },
        [51002307] = {
            ["Content"] = "（然后她将日记抱在胸前，像是在拥抱着一位久别重逢的爱人。）",
            ["ContentJP"] = "（彼女は日記を胸に抱いた。まるで久しぶりに再会した恋人を抱きしめるかのように）",
            ["DialogueId"] = 51002307,
            ["GUID"] = "7FADCDFE",
            ["NextDialogue"] = 51002308,
            },
        [51002308] = {
            ["Content"] = "……年轻人，谢谢你。谢谢你帮忙找到这个埋藏了四十年的答案。",
            ["ContentJP"] = "……ありがとうございました、お若い方。40年間ずっと埋まっていた答えを見つけてくださり、感謝に堪えません。",
            ["DialogueId"] = 51002308,
            ["GUID"] = "7FADCE28",
            ["NextDialogue"] = 51002309,
            ["SpeakNpcId"] = 700019,
            ["TalkActionId"] = {
                [1] = "700019:Explain02_Start",
                },
            },
        [51002309] = {
            ["Content"] = "请你去找我的女仆莎莉领取报酬吧。我想一个人待一会儿。",
            ["ContentJP"] = "報酬はメイドのサリーからお受け取りを。私は少し、独りにしていただきたく……",
            ["DialogueId"] = 51002309,
            ["GUID"] = "7FADCE52",
            ["NextDialogue"] = 51002310,
            ["SpeakNpcId"] = 700019,
            },
        [51002310] = {
            ["Content"] = "（老妇人转过身去，只留下衰老佝偻的背影。）",
            ["ContentJP"] = "（老婦人は背を向けた。見えるのは老いて小さくなった後ろ姿だけだ）",
            ["DialogueId"] = 51002310,
            ["GUID"] = "7FADCE7C",
            },
        [51002311] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51002311,
            ["GUID"] = "7FADCEA6",
            ["SpeakNpcId"] = 700019,
            },
        [51002312] = {
            ["Content"] = "抱歉，我没听过这个名字。如果以后有消息，我会回来找你的。",
            ["ContentJP"] = "申し訳ございません、そのお名前は存じておりません。また何か分かりましたら、必ずお知らせいたします。",
            ["DialogueId"] = 51002312,
            ["GUID"] = "7FADCED0",
            ["NextDialogue"] = 51002313,
            ["SpeakNpcId"] = 100001,
            },
        [51002313] = {
            ["Content"] = "好……好，谢谢你，年轻人。",
            ["ContentJP"] = "ああ......いいぞ、本当にありがとう、若い衆。",
            ["DialogueId"] = 51002313,
            ["GUID"] = "7FADCEFA",
            ["NextDialogue"] = 51002314,
            ["SpeakNpcId"] = 700019,
            },
        [51002314] = {
            ["Content"] = "我备好了一份薄礼，请你到我家去找我的女仆莎莉吧，就说是希琳夫人让你来的。",
            ["ContentJP"] = "ささやかなものを用意いたしましたので、私の屋敷までお越しください。そちらにいるサリーという者にお尋ねになって、「セリーヌからのご挨拶です」ってね。",
            ["DialogueId"] = 51002314,
            ["GUID"] = "7FADCF24",
            ["NextDialogue"] = 51002315,
            ["SpeakNpcId"] = 700019,
            },
        [51002315] = {
            ["Content"] = "去吧，愿你一路顺风……",
            ["ContentJP"] = "行ってらっしゃい。どうか道中、ご無事で......",
            ["DialogueId"] = 51002315,
            ["GUID"] = "7FADCF4E",
            ["SpeakNpcId"] = 700019,
            },
        [51002320] = {
            ["Content"] = "孩子，你就是那位叫做{nickname}的狩月人吧。希琳夫人让我将报酬预支给你。",
            ["ContentJP"] = "{性别:ぼうず|嬢ちゃん}、あなたが{nickname}と呼んでる月狩人さんですよね。セリーヌ夫人が、報酬を渡すように言っておられたよ。",
            ["DialogueId"] = 51002320,
            ["GUID"] = "7FADD020",
            ["NextDialogue"] = 51002321,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002321] = {
            ["Content"] = "如果你在哪里听说了哈默尔·狄金森的消息，一定要快点跟夫人讲！",
            ["ContentJP"] = "どこかでハーメル‐ディキンソンの消息を聞き及んだら、すぐにセリーヌ夫人にお伝えください。",
            ["DialogueId"] = 51002321,
            ["GUID"] = "7FADD04A",
            ["NextDialogue"] = 51002322,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002322] = {
            ["Content"] = "唉！她那身子从去年开始就越来越差，如今恐怕没有多少日子了。哈默尔的事情，是她的最后一桩心事……",
            ["ContentJP"] = "ああ…あの方の体調は去年からどんどん崩しつつあり、もう長くはあるまい...ハーメルの件は、彼女の最後の心残りなの…",
            ["DialogueId"] = 51002322,
            ["GUID"] = "7FADD074",
            ["NextOptions"] = {
                [1] = 51002323,
                },
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_End",
                },
            },
        [51002323] = {
            ["Content"] = "可以告诉我哈默尔的事情吗？",
            ["ContentJP"] = "ハーメルのことを教えてくれませんか？",
            ["DialogueId"] = 51002323,
            ["GUID"] = "51002323.0",
            ["NextDialogue"] = 51002404,
            },
        [51002401] = {
            ["Content"] = "孩子，你就是那个叫做{nickname}的狩月人吧。希琳夫人让我将报酬转交给你。",
            ["ContentJP"] = "優しいおチビさん、私と奥様のためにいろいろ駆け回ってくれて本当にありがとうね。これはほんの気持ちよ。",
            ["DialogueId"] = 51002401,
            ["GUID"] = "7FADDD6A",
            ["NextDialogue"] = 51002402,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002402] = {
            ["Content"] = "唉！她那身子从去年开始就越来越差，如今恐怕没有多少日子了。哈默尔的事情，是她的最后一桩心事……",
            ["ContentJP"] = "あぁ、奥様の体調は日を追うごとに悪くなるばかり。最後の心残りだったハーメルのことを、ずっと気に病んでらしたものね……もう残された時間は長くないのかも……",
            ["DialogueId"] = 51002402,
            ["GUID"] = "7FADDD94",
            ["NextDialogue"] = 51002403,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002403] = {
            ["Content"] = "虽然不是什么好消息，但婶婶还是要谢谢你！圆了她最后一桩心愿。",
            ["ContentJP"] = "うれしい知らせじゃなかったけど、おばさん感謝してるのよ？奥様の最後の願いを叶えてくれたんだもの。",
            ["DialogueId"] = 51002403,
            ["GUID"] = "7FADDDBE",
            ["NextOptions"] = {
                [1] = 510024031,
                },
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_End",
                },
            },
        [51002404] = {
            ["Content"] = "唉……到这份上，我们确实不能再瞒着你了。",
            ["ContentJP"] = "まあ……こうなったらもう、おチビさんに隠すようなこともないわね。",
            ["DialogueId"] = 51002404,
            ["GUID"] = "7FADDDE8",
            ["NextDialogue"] = 51002405,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002405] = {
            ["Content"] = "你可能猜到了，哈默尔是夫人四十年前的心上人。那时夫人……不，应该叫她小姐，还是个热情活泼的姑娘。哈默尔·狄金森是个和她年龄相仿的矿工，就在她父亲管理的格雷姆矿场工作。",
            ["ContentJP"] = "もうおわかりでしょうけど、ハーメルは奥様の40年前の恋人だったのよ。あの頃の奥様は……いえ、お嬢様は、情熱的で活発な子でね。ハーメル・ディキンソンはお嬢様と年齢が近い鉱山労働者で、お嬢様の父上が経営するグルビューム鉱山で働いていたわ。",
            ["DialogueId"] = 51002405,
            ["GUID"] = "7FADDE12",
            ["NextDialogue"] = 51002406,
            ["SpeakNpcId"] = 700020,
            },
        [51002406] = {
            ["Content"] = "像所有俗套的浪漫故事那样，他们越是地位悬殊，就越是执拗，非得逆着全世界的意思在一起。",
            ["ContentJP"] = "ありがちな恋物語みたいな話でね、身分の差が大きいほど愛し合うふたりは惹かれ合ったのね。世界中を敵に回してでも一緒にいたいってくらいに。",
            ["DialogueId"] = 51002406,
            ["GUID"] = "7FADDE3C",
            ["NextDialogue"] = 51002407,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002407] = {
            ["Content"] = "那些故事会告诉你，爱情就像一团火，旁人越想扑灭就越烧得旺。但他们不会告诉你，这团火在决堤的现实面前，是多么不值一提！",
            ["ContentJP"] = "そういう恋物語では、周りが消そうとするほど愛の炎が激しく燃え上がるのがお約束でしょ。でも物語は教えてくれないのよね。残酷な現実の前では愛の炎がどれほど無力なことか――",
            ["DialogueId"] = 51002407,
            ["GUID"] = "7FADDE66",
            ["NextDialogue"] = 51002408,
            ["SpeakNpcId"] = 700020,
            },
        [51002408] = {
            ["Content"] = "当这件事传到当年的老爷——也就是工程炼金院派驻格雷姆矿场的董事耳朵里的时候，哈默尔得到的不是祝福，而是一顿毒打。",
            ["ContentJP"] = "当時の鉱山の持ち主――ご主人様がふたりの仲を知ってハーメルに贈ったのは、祝福の言葉でなく手ひどい暴力だったわ。",
            ["DialogueId"] = 51002408,
            ["GUID"] = "7FADDE90",
            ["NextDialogue"] = 51002409,
            ["SpeakNpcId"] = 700020,
            },
        [51002409] = {
            ["Content"] = "不只是因为他的身份，更因为老爷已经为小姐安排了一门门当户对的亲事，对方是弗莱格桑行省的贵族——富豪新贵与没落贵族各取所需的联姻，没有比这更合适的婚事了。",
            ["ContentJP"] = "彼の身分が不相応なのも一因だけど、前々からご主人様はお嬢様のために家柄の釣り合う縁談を手配していたのでね。お相手はフレグサン領の貴族。鉱山の大富豪と没落貴族が互いの目的のために婚姻って流れで、本当におあつらえ向きな結婚相手だったのよ。",
            ["DialogueId"] = 51002409,
            ["GUID"] = "7FADDEBA",
            ["NextDialogue"] = 51002410,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002410] = {
            ["Content"] = "但小姐没有放弃，那时候的她勇敢又果决。她偷偷拜托我转交哈默尔一封信，约定一个月后，也就是4月26日零点，在银色和平广场见面。",
            ["ContentJP"] = "だけどお嬢様は諦めなかった。あの時のお嬢様は大胆で勇気に満ちていたわね。ハーメルに手紙を届けるよう私にこっそり頼んできたの。1ヶ月後の4月26日0時、シルバーピース広場で落ち合う約束の手紙を。",
            ["DialogueId"] = 51002410,
            ["GUID"] = "7FADDEE4",
            ["NextDialogue"] = 51002411,
            ["SpeakNpcId"] = 700020,
            },
        [51002411] = {
            ["Content"] = "那天正赶上老爷生日，仆人们都在为宴会忙前忙后。小姐便计划趁机逃出去，对她来说那是唯一一次逃离的机会。",
            ["ContentJP"] = "新鉱山の竣工式が盛大に行われる日で、使用人のほとんどが下働きに駆り出されていたから。逃げ出すチャンスは唯一この時だけと、お嬢様は狙いを定めて計画なさったのでしょうね。",
            ["DialogueId"] = 51002411,
            ["GUID"] = "7FADDF0E",
            ["NextDialogue"] = 51002412,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002412] = {
            ["Content"] = "她下定决心，只要哈默尔来，她就打算和他一起走，无论去哪里。",
            ["ContentJP"] = "ハーメルと一緒ならどこへでも行くと、決意なされていたのよ。",
            ["DialogueId"] = 51002412,
            ["GUID"] = "7FADDF38",
            ["NextOptions"] = {
                [1] = 510024141,
                },
            ["SpeakNpcId"] = 700020,
            },
        [51002415] = {
            ["Content"] = "是。希琳小姐在那里等到天亮，等来的却只有气急败坏的父亲。不久之后，她就像一件货物那样，被远嫁到了弗莱格桑行省。",
            ["ContentJP"] = "正解。セリーヌお嬢様は夜明けまで待ったそうだけど、結局は大層お怒りになられたご主人様だけがやってきて。そのままお嬢様はお荷物かのごとく、フレグサン領に嫁がされたのさ。",
            ["DialogueId"] = 51002415,
            ["GUID"] = "7FADDFB6",
            ["NextDialogue"] = 51002416,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002416] = {
            ["Content"] = "万幸！她的丈夫——也就是后来的老爷对她挺和善的，夫人也度过了四十年平静的时光。她从来不提当年的事情，就像是哈默尔·狄金森从未存在过一样。",
            ["ContentJP"] = "それでも幸運だった方なのよ！奥様の嫁ぎ先の――つまり結婚後の旦那様は優しいお方で、奥様は40年も穏やかな人生を過ごせたのだから。ハーメルなんて男は最初から存在していなかったかのように、奥様は昔のことを一度もお話にならなかった。",
            ["DialogueId"] = 51002416,
            ["GUID"] = "7FADDFE0",
            ["NextDialogue"] = 51002417,
            ["SpeakNpcId"] = 700020,
            },
        [51002417] = {
            ["Content"] = "一年前老爷去世了，夫人的身体也大不如前。一天，她突然告诉我，她想在人生的最后一段时间回到冰湖城，去找一个她一直未曾得到的答案。那时我才知道，哈默尔这个人，她从来都没有忘掉，只是变成了一根扎在心里的刺。",
            ["ContentJP"] = "1年前に旦那様がお亡くなりになってから、奥様も体調を崩されて……ある日、奥様は唐突におっしゃったのよ。人生の最後にアイスレイク城に戻って、得られなかった答えを探したいって。その時に初めて思い知ったさ。奥様はハーメルのことを一度たりとも忘れていなかった。心に刺さった棘は、抜けることなく残っていたんだと。",
            ["DialogueId"] = 51002417,
            ["GUID"] = "7FADE00A",
            ["NextDialogue"] = 51002418,
            ["SpeakNpcId"] = 700020,
            },
        [51002418] = {
            ["Content"] = "我们搬来了冰湖城，然而城里没有人知道哈默尔的下落。我们找到了几个还在世的老矿工，但他们回忆了半天，只能想起，最后一次见到哈默尔，已经是四十年前的事了……",
            ["ContentJP"] = "アイスレイク城に越してきたのはいいけど、あんたの知るとおり、私たちだけじゃハーメルの行方を探せなかったわ。やっとのことで年老いた鉱夫を見つけても、返ってくる言葉はいつも「最後にハーメルに会ったのは40年前だ」ってね。何度尋ねてもそれだけで。",
            ["DialogueId"] = 51002418,
            ["GUID"] = "7FADE034",
            ["NextDialogue"] = 51002419,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002419] = {
            ["Content"] = "唉，不知道夫人有生之年，还能不能了却最后的心事。",
            ["ContentJP"] = "はぁ…奥様が生きてるうちに最後の悲願を達成できるのでしょうか…",
            ["DialogueId"] = 51002419,
            ["GUID"] = "7FADE05E",
            ["NextDialogue"] = 51002420,
            ["SpeakNpcId"] = 700020,
            },
        [51002420] = {
            ["Content"] = "都是陈年往事……唉，拉着你唠唠叨叨了这么久，看来我也老了啊。",
            ["ContentJP"] = "私ったら…昔のことばっかり語っていたなんて…\
どうやら年を取った象徴なのね…",
            ["DialogueId"] = 51002420,
            ["GUID"] = "7FADE088",
            ["NextDialogue"] = 51002421,
            ["SpeakNpcId"] = 700020,
            },
        [51002421] = {
            ["Content"] = "你是狩月人，那肯定挺忙的，婶婶就不打扰你啦。",
            ["ContentJP"] = "月狩りさんとしてはさぞ大変忙しいでしょう？\
これで失礼いたします。",
            ["DialogueId"] = 51002421,
            ["GUID"] = "7FADE0B2",
            ["NextDialogue"] = 51002422,
            ["SpeakNpcId"] = 700020,
            },
        [51002422] = {
            ["Content"] = "（她不会得到答案了。）",
            ["ContentJP"] = "（彼女にはもう答えがくれないはず）",
            ["DialogueId"] = 51002422,
            ["GUID"] = "7FADE0DC",
            ["NextDialogue"] = 51002423,
            },
        [51002423] = {
            ["Content"] = "（哈默尔为了希琳而前往矿坑深处，在那里变成了秽兽，成为了四十年间可怖的传说，最后被击杀——这真相对一位时日无多的老妇人来说，实在是太残酷了。）",
            ["ContentJP"] = "（ハーメルがセリーヌ夫人のために鉱山の奥まで行き、そこで穢獣になってしまい、\
40年の間に恐ろしい言い伝えとして存在していて、最後は殺されてしまったーー\
この真相は死にかける老婦人にとってあんまりにも残酷だ。）",
            ["DialogueId"] = 51002423,
            ["GUID"] = "7FADE106",
            ["NextDialogue"] = 51002424,
            },
        [51002424] = {
            ["Content"] = "（这个残酷的真相会被永远埋葬在废墟深处，而希琳夫人将带着希望走到生命尽头。也许这已经是最好的结局了。）",
            ["ContentJP"] = "（この残酷な真相は永遠に廃墟の奥深いところにこのまま埋まれてしまうが、\
セリーヌ夫人が期待してるまま、命の果てまでに行く。\
これはエンディングとして悪くないかもしれない。）",
            ["DialogueId"] = 51002424,
            ["GUID"] = "7FADE130",
            },
        [51002425] = {
            ["Content"] = "……只是万万没想到会是这样！哈默尔并没有失约，而是为了和夫人的约定才会去那个矿坑……也不知道这对夫人来说，究竟算是宽慰还是残忍。",
            ["ContentJP"] = "……そんなこんな過去の蓋がついに開いたと思えば、なんとまあ！ハーメルは約束を無下にするような子じゃなかったのね。逆に奥様との約束を守るために鉱山へ行って……奥様にとって慰めなのか残酷な真実なのかは、私にはわからないけれど……",
            ["DialogueId"] = 51002425,
            ["GUID"] = "7FADE15A",
            ["NextDialogue"] = 51002426,
            ["SpeakNpcId"] = 700020,
            },
        [51002426] = {
            ["Content"] = "……现在夫人把自己锁在房间里，我也不知道该怎么安慰她才好……",
            ["ContentJP"] = "……奥様の今のご様子を見てご覧なさいな。どうやって慰めたらいいのやら……",
            ["DialogueId"] = 51002426,
            ["GUID"] = "7FADE184",
            ["NextDialogue"] = 51002427,
            ["SpeakNpcId"] = 700020,
            },
        [51002427] = {
            ["Content"] = "真头疼！只能先去准备晚饭了，至少让她喝点我煮的浓汤，身体稍微舒服点吧！",
            ["ContentJP"] = "困ったねえ！でもまあ、まずは夕食の準備をするしかないわね。私の特製スープを召し上がってもらって、お身体だけでも少しは楽にしてさしあげましょう！",
            ["DialogueId"] = 51002427,
            ["GUID"] = "7FADE1AE",
            ["NextDialogue"] = 51002428,
            ["SpeakNpcId"] = 700020,
            },
        [51002428] = {
            ["Content"] = "（是的，尽管真相是如此残酷，但在她最后的时日，终于还是找到了那个迟到了四十年的答案，而不是带着不解和不甘踏入坟墓。也许这已经是最好的结局了。）",
            ["ContentJP"] = "（そう、真実は残酷だったけれど。最後を迎える前に、40年待たされた「答え」がやっとわかったのだから。疑問と未練を抱えたまま永い眠りにつくよりは……これが最善の結末だったのかもしれない。）",
            ["DialogueId"] = 51002428,
            ["GUID"] = "7FADE1D8",
            },
        [51002432] = {
            ["Content"] = "唉……到这份上，我们确实不能再瞒着你了。",
            ["ContentJP"] = "まあ……こうなったらもう、おチビさんに隠すようなこともないわね。",
            ["DialogueId"] = 51002432,
            ["GUID"] = "51002432.0",
            ["NextDialogue"] = 51002433,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002433] = {
            ["Content"] = "你可能猜到了，哈默尔是夫人四十年前的心上人。那时夫人……不，应该叫她小姐，还是个热情活泼的姑娘。哈默尔·狄金森是个和她年龄相仿的矿工，就在她父亲管理的格雷姆矿场工作。",
            ["ContentJP"] = "もうおわかりでしょうけど、ハーメルは奥様の40年前の恋人だったのよ。あの頃の奥様は……いえ、お嬢様は、情熱的で活発な子でね。ハーメル・ディキンソンはお嬢様と年齢が近い鉱山労働者で、お嬢様の父上が経営するグルビューム鉱山で働いていたわ。",
            ["DialogueId"] = 51002433,
            ["GUID"] = "51002433.0",
            ["NextDialogue"] = 51002434,
            ["SpeakNpcId"] = 700020,
            },
        [51002434] = {
            ["Content"] = "像所有俗套的浪漫故事那样，他们越是地位悬殊，就越是执拗，非得逆着全世界的意思在一起。",
            ["ContentJP"] = "ありがちな恋物語みたいな話でね、身分の差が大きいほど愛し合うふたりは惹かれ合ったのね。世界中を敵に回してでも一緒にいたいってくらいに。",
            ["DialogueId"] = 51002434,
            ["GUID"] = "51002434.0",
            ["NextDialogue"] = 51002435,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002435] = {
            ["Content"] = "那些故事会告诉你，爱情就像一团火，旁人越想扑灭就越烧得旺。但他们不会告诉你，这团火在决堤的现实面前，是多么不值一提！",
            ["ContentJP"] = "そういう恋物語では、周りが消そうとするほど愛の炎が激しく燃え上がるのがお約束でしょ。でも物語は教えてくれないのよね。残酷な現実の前では愛の炎がどれほど無力なことか――",
            ["DialogueId"] = 51002435,
            ["GUID"] = "51002435.0",
            ["NextDialogue"] = 51002436,
            ["SpeakNpcId"] = 700020,
            },
        [51002436] = {
            ["Content"] = "当这件事传到当年的老爷——也就是工程炼金院派驻格雷姆矿场的董事耳朵里的时候，哈默尔得到的不是祝福，而是一顿毒打。",
            ["ContentJP"] = "当時の鉱山の持ち主――ご主人様がふたりの仲を知ってハーメルに贈ったのは、祝福の言葉でなく手ひどい暴力だったわ。",
            ["DialogueId"] = 51002436,
            ["GUID"] = "51002436.0",
            ["NextDialogue"] = 51002437,
            ["SpeakNpcId"] = 700020,
            },
        [51002437] = {
            ["Content"] = "不只是因为他的身份，更因为老爷已经为小姐安排了一门门当户对的亲事，对方是弗莱格桑行省的贵族——富豪新贵与没落贵族各取所需的联姻，没有比这更合适的婚事了。",
            ["ContentJP"] = "彼の身分が不相応なのも一因だけど、前々からご主人様はお嬢様のために家柄の釣り合う縁談を手配していたのでね。お相手はフレグサン領の貴族。鉱山の大富豪と没落貴族が互いの目的のために婚姻って流れで、本当におあつらえ向きな結婚相手だったのよ。",
            ["DialogueId"] = 51002437,
            ["GUID"] = "51002437.0",
            ["NextDialogue"] = 51002438,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_Start",
                },
            },
        [51002438] = {
            ["Content"] = "但小姐没有放弃，那时候的她勇敢又果决。她偷偷拜托我转交哈默尔一封信，约定一个月后，也就是4月26日零点，在银色和平广场见面。",
            ["ContentJP"] = "だけどお嬢様は諦めなかった。あの時のお嬢様は大胆で勇気に満ちていたわね。ハーメルに手紙を届けるよう私にこっそり頼んできたの。1ヶ月後の4月26日0時、シルバーピース広場で落ち合う約束の手紙を。",
            ["DialogueId"] = 51002438,
            ["GUID"] = "51002438.0",
            ["NextDialogue"] = 51002439,
            ["SpeakNpcId"] = 700020,
            },
        [51002439] = {
            ["Content"] = "那天正赶上老爷生日，仆人们都在为宴会忙前忙后。小姐便计划趁机逃出去，对她来说那是唯一一次逃离的机会。",
            ["ContentJP"] = "新鉱山の竣工式が盛大に行われる日で、使用人のほとんどが下働きに駆り出されていたから。逃げ出すチャンスは唯一この時だけと、お嬢様は狙いを定めて計画なさったのでしょうね。",
            ["DialogueId"] = 51002439,
            ["GUID"] = "51002439.0",
            ["NextDialogue"] = 51002440,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Explain01_End",
                },
            },
        [51002440] = {
            ["Content"] = "她下定决心，只要哈默尔来，她就打算和他一起走，无论去哪里。",
            ["ContentJP"] = "ハーメルと一緒ならどこへでも行くと、決意なされていたのよ。",
            ["DialogueId"] = 51002440,
            ["GUID"] = "51002440.0",
            ["NextOptions"] = {
                [1] = 51002441,
                },
            ["SpeakNpcId"] = 700020,
            },
        [51002441] = {
            ["Content"] = "但是哈默尔爽约了？",
            ["ContentJP"] = "だけど、ハーメルは約束の場所に来なかった？",
            ["DialogueId"] = 51002441,
            ["GUID"] = "51002441.0",
            ["NextDialogue"] = 51002442,
            },
        [51002442] = {
            ["Content"] = "是。希琳小姐在那里等到天亮，等来的却只有气急败坏的父亲。不久之后，她就像一件货物那样，被远嫁到了弗莱格桑行省。",
            ["ContentJP"] = "正解。セリーヌお嬢様は夜明けまで待ったそうだけど、結局は大層お怒りになられたご主人様だけがやってきて。そのままお嬢様はお荷物かのごとく、フレグサン領に嫁がされたのさ。",
            ["DialogueId"] = 51002442,
            ["GUID"] = "51002442.0",
            ["NextDialogue"] = 51002443,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Agree",
                },
            },
        [51002443] = {
            ["Content"] = "万幸！她的丈夫——也就是后来的老爷对她挺和善的，夫人也度过了四十年平静的时光。她从来不提当年的事情，就像是哈默尔·狄金森从未存在过一样。",
            ["ContentJP"] = "それでも幸運だった方なのよ！奥様の嫁ぎ先の――つまり結婚後の旦那様は優しいお方で、奥様は40年も穏やかな人生を過ごせたのだから。ハーメルなんて男は最初から存在していなかったかのように、奥様は昔のことを一度もお話にならなかった。",
            ["DialogueId"] = 51002443,
            ["GUID"] = "51002443.0",
            ["NextDialogue"] = 51002444,
            ["SpeakNpcId"] = 700020,
            },
        [51002444] = {
            ["Content"] = "一年前老爷去世了，夫人的身体也大不如前。一天，她突然告诉我，她想在人生的最后一段时间回到冰湖城，去找一个她一直未曾得到的答案。那时我才知道，哈默尔这个人，她从来都没有忘掉，只是变成了一根扎在心里的刺。",
            ["ContentJP"] = "1年前に旦那様がお亡くなりになってから、奥様も体調を崩されて……ある日、奥様は唐突におっしゃったのよ。人生の最後にアイスレイク城に戻って、得られなかった答えを探したいって。その時に初めて思い知ったさ。奥様はハーメルのことを一度たりとも忘れていなかった。心に刺さった棘は、抜けることなく残っていたんだと。",
            ["DialogueId"] = 51002444,
            ["GUID"] = "51002444.0",
            ["NextDialogue"] = 51002445,
            ["SpeakNpcId"] = 700020,
            },
        [51002445] = {
            ["Content"] = "我们搬来了冰湖城，然而城里没有人知道哈默尔的下落。我们找到了几个还在世的老矿工，但他们回忆了半天，只能想起，最后一次见到哈默尔，已经是四十年前的事了……",
            ["ContentJP"] = "アイスレイク城に越してきたのはいいけど、あんたの知るとおり、私たちだけじゃハーメルの行方を探せなかったわ。やっとのことで年老いた鉱夫を見つけても、返ってくる言葉はいつも「最後にハーメルに会ったのは40年前だ」ってね。何度尋ねてもそれだけで。",
            ["DialogueId"] = 51002445,
            ["GUID"] = "51002445.0",
            ["NextDialogue"] = 51002425,
            ["SpeakNpcId"] = 700020,
            ["TalkActionId"] = {
                [1] = "700020:Sigh_Start",
                },
            },
        [51002501] = {
            ["Content"] = "走，走开……不买月石的话就赶紧走……别把那群当兵的引来了……",
            ["ContentJP"] = "じゃ、邪魔だ……月ノ石を買わないなら、どっかに行けってんだ……頼む、兵士たちの目を引かないでくれ……",
            ["DialogueId"] = 51002501,
            ["GUID"] = "7FADEDD2",
            ["NextDialogue"] = 51002502,
            ["SpeakNpcId"] = 700113,
            ["TalkActionId"] = {
                [1] = "700113:Shock_Start",
                },
            },
        [51002502] = {
            ["Content"] = "（男人瑟缩在角落。他的眼神躲闪，渴望将身旁的月石脱手，却迟疑着要不要向他人寻求帮助。）",
            ["ContentJP"] = "（たくましい体の男が隅に縮こまっている。月ノ石を早急に売りつけるか、他者に助けを求めるか、色々とためらいが窺える目を逸らし方だ。見てくれのイメージとはまったく違う）",
            ["DialogueId"] = 51002502,
            ["GUID"] = "7FADEDFC",
            ["TalkActionId"] = {
                [1] = "700113:Shock_End",
                },
            ["TalkOptions"] = {
                [1] = 510025021,
                [2] = 510025022,
                [3] = 510025023,
                [4] = 510025024,
                },
            },
        [51002503] = {
            ["Content"] = "您高抬贵手，把我当个屁放了吧，我只要把这批月石卖掉就立马离开冰湖城，绝不回来。",
            ["ContentJP"] = "こ、今回だけは大目に見てくれないか。この月ノ石を売っぱらったらアイスレイク城から速攻で離れる。二度と帰ってこないから……",
            ["DialogueId"] = 51002503,
            ["GUID"] = "7FADEE26",
            ["SpeakNpcId"] = 700113,
            },
        [51002504] = {
            ["Content"] = "（男人听罢提起袋子就要跑，好不容易向他说明玩笑并解释身份后，他才悄声说明了自己的难处。）",
            ["ContentJP"] = "（男はそれを聞くや否や瞬間で袋を持ち上げて逃げようとした。慌てて自分の身分と冗談であることを説明すると、彼は小声で話し始める。何やら困った状況なようだ）",
            ["DialogueId"] = 51002504,
            ["GUID"] = "7FADEE50",
            },
        [51002505] = {
            ["Content"] = "只要你帮我找个买家，报酬分你七成，不，八成！拜托了，拜托！",
            ["ContentJP"] = "……買い手を探してくれたら報酬の70％、いや、80％を渡す！どうか頼む、後生の頼みだ！",
            ["DialogueId"] = 51002505,
            ["GUID"] = "7FADEE7A",
            ["SpeakNpcId"] = 700113,
            ["TalkActionId"] = {
                [1] = "700113:Sigh_Start",
                },
            },
        [51002506] = {
            ["Content"] = "（虽说答应了男人的委托，但他的神色和袋子上干涸的血迹都宣告着这批月石的危险性，想到这里，那“买家”就只能找那个人了。）",
            ["ContentJP"] = "男の依頼には応じたものの──あの表情と、袋に滲んだ暗赤色の染みが、この月ノ石たちがただの品物じゃないことを物語っている。",
            ["DialogueId"] = 51002506,
            ["GUID"] = "7FADEEA4",
            ["TalkActionId"] = {
                [1] = "700113:Sigh_End",
                },
            },
        [51002601] = {
            ["Content"] = "太好了，今天没碰到{nickname}……",
            ["ContentJP"] = "本日は吉日なり……なんせ{nickname}の顔を拝まずに済んでるからな……",
            ["DialogueId"] = 51002601,
            ["GUID"] = "7FADFE3A",
            ["NextDialogue"] = 51002602,
            ["SpeakNpcId"] = 700111,
            ["TalkActionId"] = {
                [1] = "700111:Think_Start",
                },
            },
        [51002602] = {
            ["Content"] = "你找我吗。",
            ["ContentJP"] = "{性别:僕をお探しかな？|私をお探しかい？}",
            ["DialogueId"] = 51002602,
            ["GUID"] = "7FADFE64",
            ["NextDialogue"] = 51002603,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700111:Think_End",
                },
            },
        [51002603] = {
            ["Content"] = "……啊！你怎么又来了！",
            ["ContentJP"] = "……おわぁ厄日が来やがったぁ！な、なんの用だよ！",
            ["DialogueId"] = 51002603,
            ["GUID"] = "7FADFE8E",
            ["NextOptions"] = {
                [1] = 510026031,
                },
            ["SpeakNpcId"] = 700111,
            ["TurnTo"] = {
                [1] = "700111:n(0)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51002604] = {
            ["Content"] = "啊……你想骗我，故意给我找点事做对吧。",
            ["ContentJP"] = "ふん……その手には乗らんぞ。何を騙して俺にやらせるつもりだ？",
            ["DialogueId"] = 51002604,
            ["GUID"] = "7FADFEB8",
            ["SpeakNpcId"] = 700111,
            ["TalkActionId"] = {
                [1] = "700111:Disagree",
                },
            },
        [51002605] = {
            ["Content"] = "（大门旁突然响起急促的电话铃声，凯文如同受惊的兔子一般跳起，急匆匆地接起电话。）",
            ["ContentJP"] = "（扉の方で急に騒々しい電話の着信音が鳴り響く。ケビンは驚いたウサギのように飛び上がって、慌ただしく電話を取った）",
            ["DialogueId"] = 51002605,
            ["GUID"] = "7FADFEE2",
            ["NextDialogue"] = 51002606,
            ["TurnTo"] = {
                [1] = "700111:p(90)",
                },
            },
        [51002606] = {
            ["Content"] = "是我……有可疑人士出没？收到，我这就过去。",
            ["ContentJP"] = "うん…不審者が？了解、すぐに向かう。",
            ["DialogueId"] = 51002606,
            ["GUID"] = "7FADFF0C",
            ["NextDialogue"] = 51002607,
            ["SpeakNpcId"] = 700111,
            ["TalkActionId"] = {
                [1] = "700111:Agree",
                },
            },
        [51002607] = {
            ["Content"] = "……该不会就是你说的那个人吧，走吧，带我去看看。",
            ["ContentJP"] = "……まさかお前の言う売人か？……よし、そいつのとこまで案内してくれ。",
            ["DialogueId"] = 51002607,
            ["GUID"] = "7FADFF36",
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"700111:n(0)\"}},PlayAnimation{ActorId{700111},AnimationId{\"Think_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700111,
            },
        [51002701] = {
            ["Camera"] = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦，这不是曾经的模范劳工拉里吗？你平时身边不是老跟着几个兄弟的吗，咋今天就一个人了。",
            ["ContentJP"] = "え、ひょっとしてお前、模範労働者だったラリーか？いつもは何人かの兄弟と一緒に行動してんのに、今日はひとりだけなんだな？",
            ["DialogueId"] = 51002701,
            ["GUID"] = "7FAE0EA2",
            ["NextDialogue"] = 51002702,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700112:Talk01_Start",
                [2] = "100001:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700114:n(700112)",
                },
            },
        [51002702] = {
            ["Camera"] = "11.023438,10.769531,127.256836,0.0,0.0,8.403177,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "卫，卫戍部队？？！",
            ["ContentJP"] = "け、警備部隊！？？",
            ["DialogueId"] = 51002702,
            ["FinalCamera"] = "39.697266,15.063477,127.256836,0.0,0.0,8.403239,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAE0ECC",
            ["NextDialogue"] = 51002703,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Shock_Start",
                [2] = "700112:Talk01_End",
                [3] = "100001:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 1,
            },
        [51002703] = {
            ["Camera"] = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没事他们也不关键，倒是你啊，应该知道私自开采与贩卖月石都是违规行为的吧，我收到上级通知来……嘶，你这袋子上的血是怎么回事？",
            ["ContentJP"] = "まあ、なんだっていいさ、重要なのはそこじゃないし……お前さ、無断で月ノ石を採掘したり販売するのは法に触れるって知ってるよな？上層部から通知を受けちまって……ツッ、テメェおい、その袋の血はなんだってんだ？",
            ["DialogueId"] = 51002703,
            ["GUID"] = "7FAE0EF6",
            ["NextDialogue"] = 51002704,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700114:Shock_End",
                [2] = "700112:Talk01_Start",
                },
            },
        [51002704] = {
            ["Camera"] = "-24.264648,5.625977,122.256836,0.0,0.0,8.403694,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我，我……",
            ["ContentJP"] = "お、俺は……",
            ["DialogueId"] = 51002704,
            ["GUID"] = "7FAE0F20",
            ["NextDialogue"] = 51002705,
            ["Scripts"] = "SEQ{LookAt{LookAtDescription{\"700114:n(100001)\"}},LookAt{LookAtDescription{\"700114:n(700114)\"}}}",
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700112:Talk01_End",
                },
            },
        [51002705] = {
            ["Camera"] = "121.136719,-1.510742,123.537598,0.000002,0.399996,-168.191696,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别跑！{nickname}，搭把手！",
            ["ContentJP"] = "逃げんじゃねえよ！{nickname}、手伝え！",
            ["DialogueId"] = 51002705,
            ["GUID"] = "7FAE0F4A",
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700112},AnimationId{\"Angry01_Start\"},Duration{2}},LookAt{LookAtDescription{\"700112:n(100001)\"}},PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700112,
            },
        [51002801] = {
            ["Camera"] = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你，你这家伙居然骗我！为什么要把当兵的叫过来！",
            ["ContentJP"] = "お、お前！俺を騙したなぁ！兵士なんざ引き連れてきやがってぇ！！",
            ["DialogueId"] = 51002801,
            ["GUID"] = "7FAE1F0A",
            ["NextDialogue"] = 51002802,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_Start",
                },
            },
        [51002802] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "闭嘴，手放到我能看到的位置……双手张开，麻袋放下！",
            ["ContentJP"] = "黙れっての、俺の見えるところに手を出せ……両手を広げて、麻袋を下ろせ！",
            ["DialogueId"] = 51002802,
            ["GUID"] = "7FAE1F34",
            ["NextDialogue"] = 51002803,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700112:Angry01_Start",
                },
            },
        [51002803] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（黑洞洞的枪口顶在拉里头上，拉里犹豫了一下最终摊开双手。麻袋掉落地面，一颗颗沾血的月石顺势洒落在了众人脚下。）",
            ["ContentJP"] = "（真っ黒な銃口がラリーの頭に突きつけられる。ラリーは一瞬ためらう様子を見せたが、ついに両手を広げた。麻袋が地面に落ちる。血のついた月ノ石が足元辺りに次々と転がった）",
            ["DialogueId"] = 51002803,
            ["GUID"] = "7FAE1F5E",
            ["NextDialogue"] = 51002804,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_End",
                [2] = "700112:Angry01_End",
                },
            },
        [51002804] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……你用它们砸死了你的那群兄弟？",
            ["ContentJP"] = "手をかけやがったな？そいつで兄弟たちをぶん殴って……",
            ["DialogueId"] = 51002804,
            ["GUID"] = "7FAE1F88",
            ["NextDialogue"] = 51002805,
            ["SpeakNpcId"] = 700112,
            },
        [51002805] = {
            ["Camera"] = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是他们先动手的……我，我这都是正当防卫！",
            ["ContentJP"] = "先に手を出したのはあいつらだッ！！お、俺は、自分の身を守っただけさ……正当防衛なんだよぉッ！！",
            ["DialogueId"] = 51002805,
            ["GUID"] = "7FAE1FB2",
            ["NextDialogue"] = 51002806,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_Start",
                },
            },
        [51002806] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "正不正当我跟你说了不算，走！",
            ["ContentJP"] = "正当かなんて俺に言ったってしょうがないだろ！さっさと歩け！",
            ["DialogueId"] = 51002806,
            ["GUID"] = "7FAE1FDC",
            ["NextDialogue"] = 51002807,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700114:Sigh_End",
                [2] = "700112:Talk01_Start",
                },
            },
        [51002807] = {
            ["Camera"] = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不能怪我，不能怪我……！啊啊，都怪这袋月石！要不是刚好翻开了这个破袋子，我们现在一定都还好好的，都好好的！",
            ["ContentJP"] = "違う、俺のせいじゃ……！ああ全部、月ノ石めッ！こんなクソッタレな袋さえなけりゃ、俺たちみんな、なんにも……平和に暮らせたはずなんだよぉ……！！",
            ["DialogueId"] = 51002807,
            ["GUID"] = "7FAE2006",
            ["NextDialogue"] = 51002808,
            ["SpeakNpcId"] = 700114,
            ["TalkActionId"] = {
                [1] = "700114:Disagree",
                [2] = "700112:Talk01_End",
                },
            },
        [51002808] = {
            ["Camera"] = "121.290039,-83.856445,144.21875,0.000003,-0.999905,-165.995453,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉……",
            ["ContentJP"] = "はぁ……",
            ["DialogueId"] = 51002808,
            ["GUID"] = "7FAE2030",
            ["NextDialogue"] = 51002809,
            ["SpeakNpcId"] = 700112,
            ["TalkActionId"] = {
                [1] = "700112:Disagree",
                },
            },
        [51002809] = {
            ["Camera"] = "-3.327148,-490.567383,115.4375,0.000011,0.0,94.803833,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对了，还得例行公事一下。感谢{nickname}给卫戍部队提供的帮助，这些是协助的报酬。",
            ["ContentJP"] = "そうだ、規定通りに渡さないとだ。{nickname}、警備部隊への協力に感謝する。これは協力した報酬だ。",
            ["DialogueId"] = 51002809,
            ["GUID"] = "7FAE205A",
            ["Scripts"] = "SEQ{PARA{TurnTo{TurnToDescription{\"700112:n(100001)\"}},TurnTo{TurnToDescription{\"100001:n(700112)\"}}},PlayAnimation{ActorId{700112},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{700112},AnimationId{\"Talk01_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700112,
            },
        [51002810] = {
            ["Content"] = "拉里被凯文押送着渐渐走远。",
            ["ContentJP"] = "ケビンに連行されたラリーが徐々に遠ざかっていく。",
            ["DialogueId"] = 51002810,
            ["Duration"] = 2,
            ["GUID"] = "7FAE2084",
            ["NextDialogue"] = 51002811,
            },
        [51002811] = {
            ["Content"] = "这袋“血石”背后所蕴含的血腥过往，也随着拉里的离去，淹没在冰湖城的又一片雪花之下。",
            ["ContentJP"] = "「血の石」の裏に隠された血生臭い過去は、ラリーが去っていくにつれて、アイスレイク城に降り積もる雪の一粒として埋もれていくのだった。",
            ["DialogueId"] = 51002811,
            ["Duration"] = 4,
            ["GUID"] = "7FAE20AE",
            },
        [51002901] = {
            ["Content"] = "（一个嗓门奇高的人在大声念诵着什么，酒客们有一搭没一搭听着，时不时发出快活的笑声。）",
            ["ContentJP"] = "（大声で何かを朗読している男の声が聞こえる。酒客たちは気まぐれに聞いており、時折楽しげに笑っている。）",
            ["DialogueId"] = 51002901,
            ["GUID"] = "7FAE2F72",
            ["NextDialogue"] = 51002902,
            },
        [51002902] = {
            ["Content"] = "来自深山的幽魂，来自冰湖的鬼魅！",
            ["ContentJP"] = "深々たる山の奥底より具現化した！霊魂が！アイスレイクからの悪鬼が！",
            ["DialogueId"] = 51002902,
            ["GUID"] = "7FAE2F9C",
            ["NextDialogue"] = 51002903,
            ["SpeakNpcId"] = 700015,
            },
        [51002903] = {
            ["Content"] = "它们在逼近！它们在逼近！",
            ["ContentJP"] = "彼奴らが迫りくる！彼奴らが肉薄してくるのだ！！！",
            ["DialogueId"] = 51002903,
            ["GUID"] = "7FAE2FC6",
            ["NextDialogue"] = 51002904,
            ["SpeakNpcId"] = 700015,
            },
        [51002904] = {
            ["Content"] = "你来了？",
            ["ContentJP"] = "あら、来たのね？",
            ["DialogueId"] = 51002904,
            ["GUID"] = "7FAE2FF0",
            ["NextOptions"] = {
                [1] = 510029041,
                },
            ["SpeakNpcId"] = 200003,
            },
        [51002905] = {
            ["Content"] = "我手里暂且没什么活儿给你，不过……",
            ["ContentJP"] = "今、手元に頼める仕事はないわね。でも……",
            ["DialogueId"] = 51002905,
            ["GUID"] = "7FAE301A",
            ["NextDialogue"] = 51002906,
            ["SpeakNpcId"] = 200003,
            },
        [51002906] = {
            ["Content"] = "……你们无法想象！",
            ["ContentJP"] = "……貴様たちは想像し得るか！？",
            ["DialogueId"] = 51002906,
            ["GUID"] = "7FAE3044",
            ["NextDialogue"] = 51002907,
            ["SpeakNpcId"] = 700015,
            },
        [51002907] = {
            ["Content"] = "一个幽灵！！！一个穿门入户的无声行者！！！！",
            ["ContentJP"] = "亡霊だぞ！！！我が安息地である居館の静寂を鉤裂く者！！！門を通り抜けて邪魔立てる者！！！",
            ["DialogueId"] = 51002907,
            ["GUID"] = "7FAE306E",
            ["NextDialogue"] = 51002908,
            ["SpeakNpcId"] = 700015,
            },
        [51002908] = {
            ["Content"] = "如你所听，总是有碰上麻烦的人。",
            ["ContentJP"] = "お聞きの通り、トラブルの塊みたいなヤツならあそこにいるわ。",
            ["DialogueId"] = 51002908,
            ["GUID"] = "7FAE3098",
            ["NextOptions"] = {
                [1] = 510029081,
                },
            ["SpeakNpcId"] = 200003,
            },
        [51002909] = {
            ["Content"] = "巴克先生，因为沾一点酒精就倒，所以平时只点果汁和牛奶。职业嘛……三流的剧作家，一流的不好懂。喏，已经在那里絮絮叨叨半天了。",
            ["ContentJP"] = "バック氏、少しでも酒が入ると倒れちゃうから、果汁や牛乳しか頼まない人よ。職業は…三流の劇作家、一流の難解な語り手。ほら、あそこでずっとぶつぶつ言ってるよ。",
            ["DialogueId"] = 51002909,
            ["GUID"] = "7FAE30C2",
            ["NextDialogue"] = 51002910,
            ["SpeakNpcId"] = 200003,
            },
        [51002910] = {
            ["Content"] = "如你所见，他好像没办法明确表达自己的诉求，你要给他翻译翻译吗？",
            ["ContentJP"] = "まあ自分の言いたいことを単純明快に表現できない人でね。あなたは分かるかしら？",
            ["DialogueId"] = 51002910,
            ["GUID"] = "7FAE30EC",
            ["NextOptions"] = {
                [1] = 510029101,
                },
            ["RestartTag"] = 51002910,
            ["SpeakNpcId"] = 200003,
            ["bForbidSkipOptions"] = true,
            },
        [51002911] = {
            ["Content"] = "别沮丧，整个冰湖城能听懂他在说什么的也不超过一个巴掌数。",
            ["ContentJP"] = "ガッカリしなくてもいいわよ。アレの言語を解読できる人間なんて、アイスレイク中を探しても片手で数えるほどでしょうし。",
            ["DialogueId"] = 51002911,
            ["GUID"] = "7FAE3116",
            ["SpeakNpcId"] = 200003,
            },
        [51002912] = {
            ["Content"] = "以你的才智，这份工作看来非你莫属了。",
            ["ContentJP"] = "あなたほどの才智を持つ人間であれば、理解もなんとかできそうかしら。",
            ["DialogueId"] = 51002912,
            ["GUID"] = "7FAE3140",
            ["SpeakNpcId"] = 200003,
            },
        [51003001] = {
            ["Content"] = "（你侧耳倾听剧作家的高谈阔论。）",
            ["ContentJP"] = "（劇作家の妄言に耳を傾ける）",
            ["DialogueId"] = 51003001,
            ["GUID"] = "7FAE3FDA",
            ["NextDialogue"] = 51003002,
            },
        [51003002] = {
            ["Content"] = "诗人的夜晚总是漫长……剧作家也不例外！我们的笔书写着人间的脉动，我们的心自然也与潮汐和月亮为伴！",
            ["ContentJP"] = "終焉なき詩人の夜は毎晩と永らえるもの……それは劇作家も多分に漏れず！私のペンは人の拍動を描写し、私の心は自然や潮汐にあり、月の下にある！",
            ["DialogueId"] = 51003002,
            ["GUID"] = "7FAE4004",
            ["NextDialogue"] = 51003003,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_Start",
                },
            },
        [51003003] = {
            ["Content"] = "抛却了令人炫目的阳光，抛却了人间的声响，抛却了浮躁的心思，此时才是我与世界促膝长谈的时刻！",
            ["ContentJP"] = "燦爛たる陽光を見放し、喧々たる残響に耳を貸さず、思為す軽薄さなど遺棄する！その瞬間こそが、私と世界が邂逅し、対話する瞬間なのだ！",
            ["DialogueId"] = 51003003,
            ["GUID"] = "7FAE402E",
            ["NextOptions"] = {
                [1] = 510030031,
                [2] = 510030032,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003004] = {
            ["Content"] = "啊！要么是我不自知的怠慢惹恼了掌管灵感的女神，要么就是睡眠之神在刻意作弄我！否则我怎么会任由光阴的车轮滚滚而过，却没有半分察觉！",
            ["ContentJP"] = "ああ！私の無自覚な怠慢がインスピレーションの女神を怒らせてしまったのか！否、それだけに非ず、眠りへと誘う神が我が身を戯れに弄んでいるのか！さもなければ何故！何故この私が時の歯車の回り動く様を拝むことなく、露いささかも気づかないのであろうか！",
            ["DialogueId"] = 51003004,
            ["GUID"] = "7FAE4058",
            ["NextDialogue"] = 51003005,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Sigh_Start",
                },
            },
        [51003005] = {
            ["Content"] = "我应当用写满文辞的纸张去迎接清晨的到来，而不是只留下一个徒有健康的我与空白的稿纸！",
            ["ContentJP"] = "私の朝は揚々に語り明かされた物語を記する原稿を残して迎えるべきであったのだ！無意義にも健やかなりし身と虚無の純白を映写する原稿用紙を残すのではなく！",
            ["DialogueId"] = 51003005,
            ["GUID"] = "7FAE4082",
            ["NextOptions"] = {
                [1] = 510030051,
                [2] = 510030052,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Sigh_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003006] = {
            ["Content"] = "在充满诱惑的睡梦中，我听到窸窣的足音，它是那么轻盈，像精灵的旋舞，我闻到饱满果实的气味，那上面一定浇着厚厚的蜜糖！",
            ["ContentJP"] = "ある時、蠱惑の夢中で足音のざわめきが耳を撫でた。妖精かのように軽やかな舞いを感じた。その刹那には豊潤な果実に甘美なる白蜜を垂らしたような香りが私の鼻を突いた！",
            ["DialogueId"] = 51003006,
            ["GUID"] = "7FAE40AC",
            ["NextDialogue"] = 51003007,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Explain01_Start",
                },
            },
        [51003007] = {
            ["Content"] = "或许我曾在梦中迷失，但这声息与味道引领我回到现实，他们缥缈不定，他们萦绕我身，他们确实存在……",
            ["ContentJP"] = "夢中を彷徨ったのやも知れぬが、その音と香りが私を現実に繋ぎ止めたのだ。彼奴らは朧であろうと、私の周囲に纏わりつくように、確かに存在している……",
            ["DialogueId"] = 51003007,
            ["GUID"] = "7FAE40D6",
            ["NextOptions"] = {
                [1] = 510030071,
                [2] = 510030072,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003008] = {
            ["Content"] = "他们绝不是我的幻觉，但我抓不住痕迹的尾巴，我勘不破这诡秘的行径，是幽灵？是鬼魅？是幻影？",
            ["ContentJP"] = "彼奴らが私の虹彩にのみ射映される夢幻でないのは必定！然し私には痕跡の尻尾を把持することすら叶わず、この不可解の靄が晴れない実態は慙愧に堪えぬ。靄の真相とは亡霊か？いや悪鬼か？或いは幻影の結句なのか？",
            ["DialogueId"] = 51003008,
            ["GUID"] = "7FAE4100",
            ["NextDialogue"] = 51003009,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Disagree",
                },
            },
        [51003009] = {
            ["Content"] = "我那贫瘠的破屋不增不减，他唯独偷窃了我视为生命的灵感！眼看他就要让我的梦破碎……",
            ["ContentJP"] = "我が清貧なる破れ屋の家財が膨れることもなければ、萎むこともない。だがやつらは我が命とも言えるインスピレーションだけを確かに盗んでいったのだ！我が夢を挫き、砕こうとしているのだ……",
            ["DialogueId"] = 51003009,
            ["GUID"] = "7FAE412A",
            ["NextOptions"] = {
                [1] = 510030091,
                [2] = 510030092,
                },
            ["SpeakNpcId"] = 700015,
            ["bForbidSkipOptions"] = true,
            },
        [51003010] = {
            ["Content"] = "剧作家的夜晚是绝不可以付诸于睡眠的！在座的诸位谁能听从我的召唤，去为我、去为那即将问世的著作驱散那偷走灵感的窃贼！",
            ["ContentJP"] = "劇作家の夜間とは枕に伏せる刻限に決して非ず！今般の場に集いし宿命を負う者たちにて、我が咆哮に傾聴し、私のため、否、まもなく地上に産まれ出づる傑作のため、インスピレーションを掠め取る怪盗を討ち払う者はおらぬか！",
            ["DialogueId"] = 51003010,
            ["GUID"] = "7FAE4154",
            ["NextDialogue"] = 51003011,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk03_Start",
                },
            },
        [51003011] = {
            ["Content"] = "我将给予你荣耀，给予你身为主角的可能，让我见识你的出色，让我愿意为狩月人作传吧！",
            ["ContentJP"] = "名乗り上げる者あらば、私の紡ぎし妖精の尾の中心人物となる可能性を、それに伴う名誉を捧ぐことを誓う！私に腕前の見得を切らば、月狩り人の名を後世に残すための伝記を私が紡ぎ上げようではないか！",
            ["DialogueId"] = 51003011,
            ["GUID"] = "7FAE417E",
            ["NextOptions"] = {
                [1] = 510030111,
                [2] = 510030112,
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003012] = {
            ["Content"] = "虽然没什么钱赚，但听起来很有意思，你想接吗？",
            ["ContentJP"] = "儲けにはならなそうだけど、興味あるかしら？受けてみる？",
            ["DialogueId"] = 51003012,
            ["GUID"] = "7FAE41A8",
            ["NextOptions"] = {
                [1] = 510030121,
                [2] = 510030122,
                },
            ["SpeakNpcId"] = 200003,
            ["bForbidSkipOptions"] = true,
            },
        [51003013] = {
            ["Content"] = "哦！回应我呼唤的勇士出现了，这说不定是一段崭新冒险的序幕！",
            ["ContentJP"] = "おお！我が問いかけに呼応する勇士が顕現した！新生の冒険譚が幕を開けるのであろうか！",
            ["DialogueId"] = 51003013,
            ["GUID"] = "7FAE41D2",
            ["NextDialogue"] = 51003014,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_Start",
                },
            ["TurnTo"] = {
                [1] = "700015:n(0)",
                },
            },
        [51003014] = {
            ["Content"] = "我对你们接下来碰到的事情抱以十足的兴趣，当你们归来，请为我讲述你们的故事吧！",
            ["ContentJP"] = "此度より君たちに訪れるであろう壮絶な未来に私は興味を禁じ得ない。無事に生還した暁には、どのような物語が紡がれたのか教えてくれまいか！",
            ["DialogueId"] = 51003014,
            ["GUID"] = "7FAE41FC",
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700015:Talk01_End",
                },
            },
        [51003101] = {
            ["Content"] = "据卡米拉所说，巴克先生不胜酒力、从不喝酒，那壶里的酒难道是其他人加进去的？",
            ["ContentJP"] = "カミラさんの話だと、バックさんは酒がまったくダメで、一滴も飲まないって聞いたけど……この酒、誰かがこっそり混ぜたの？",
            ["DialogueId"] = 51003101,
            ["GUID"] = "7FAE5042",
            ["NextDialogue"] = 51003102,
            ["SpeakNpcId"] = 100001,
            },
        [51003102] = {
            ["Content"] = "仔细一看，这牛奶壶上还有个黏糊糊的手印……看起来那只手很小巧。",
            ["ContentJP"] = "よく見ると……ミルク壺に小さな、べたべたした手形が残ってる。──ずいぶん小さな手だ。",
            ["DialogueId"] = 51003102,
            ["GUID"] = "7FAE506C",
            ["SpeakNpcId"] = 100001,
            },
        [51003103] = {
            ["Content"] = "小小的脚印从屋外延伸至窗台，屋内还有雪化的积水。显然闯入者没有处理痕迹的意识，单纯就只是一个小孩子而已。",
            ["ContentJP"] = "小さな足跡が外から窓辺まで続いている。屋内には雪解け水も。荒らした様子はない……単に、小さな子どもが入り込んだだけのようだ。",
            ["DialogueId"] = 51003103,
            ["GUID"] = "7FAE5096",
            ["SpeakNpcId"] = 100001,
            },
        [51003104] = {
            ["Content"] = "看来似乎有个小孩把酒掺在牛奶里，灌醉了巴克先生。再去找找其他线索吧。",
            ["ContentJP"] = "どうやら子どもが牛乳に酒を混ぜて、バックさんを酔わせたみたいだね。他にも手がかりを探してみよう。",
            ["DialogueId"] = 51003104,
            ["Duration"] = 4,
            ["GUID"] = "7FAE50C0",
            ["SpeakNpcId"] = 100001,
            },
        [51003105] = {
            ["Content"] = "你好，请问平时会有小孩子来找巴克先生玩吗？",
            ["ContentJP"] = "こんにちは。普段、バックさんのところに遊びに来る子どもっていますか？",
            ["DialogueId"] = 51003105,
            ["GUID"] = "7FAE50EA",
            ["NextDialogue"] = 51003106,
            ["SpeakNpcId"] = 100001,
            },
        [51003106] = {
            ["Content"] = "小孩找巴克玩？不可能不可能，哪有小孩会对那种只在<H>家里、酒馆和剧院</>三点一线，还满嘴怪话的家伙感兴趣啊。",
            ["ContentJP"] = "子ども？まさか、あんな家と酒場と劇場の往復しかしない変人に興味を持つ子なんかいないよ。",
            ["DialogueId"] = 51003106,
            ["GUID"] = "7FAE5114",
            ["NextDialogue"] = 51003107,
            ["SpeakNpcId"] = 700213,
            },
        [51003107] = {
            ["Content"] = "别说小孩了，连我们平时都很少跟他打交道，烦得要死还一句话都听不懂。他是不是犯什么事了？我跟你讲啊，我早就感觉他不是好东西了。",
            ["ContentJP"] = "あんたも見たでしょう？子どもどころか、あいつ、誰ともろくに喋れないし、まともな働き口もない。昔からご近所の厄介者だよ。",
            ["DialogueId"] = 51003107,
            ["GUID"] = "7FAE513E",
            ["NextDialogue"] = 51003108,
            ["SpeakNpcId"] = 700213,
            },
        [51003108] = {
            ["Content"] = "（老妇人滔滔不绝地数落着巴克，诸如这么大了没有正经工作，一天到晚不出门，没老婆没朋友。一直到她讲得口干舌燥，你才找到机会离开。）",
            ["ContentJP"] = "隣人の老婆は延々とバックの悪口をまくしたてた。やっと話が一段落したところで、あなたはそっとその場を離れた。",
            ["DialogueId"] = 51003108,
            ["GUID"] = "7FAE5168",
            ["NextDialogue"] = 51003109,
            },
        [51003109] = {
            ["Content"] = "（巴克先生深居简出没有社交，大部分人都不了解他。所以会想到用酒来灌醉巴克先生的小孩子，一定是从什么地方知道了这个秘密……）",
            ["ContentJP"] = "バックさんは引きこもりがちで、外部との接点もほとんどない。彼に酒を飲ませようとした子どもは、きっと何か特別な情報を知っていたはず……",
            ["DialogueId"] = 51003109,
            ["GUID"] = "7FAE5192",
            ["NextDialogue"] = 51003110,
            ["SpeakNpcId"] = 100001,
            },
        [51003110] = {
            ["Content"] = "（水仙平原不招揽小孩子，家附近也没有小孩找巴克先生……那么就只剩下剧院了，过去看看吧。）",
            ["ContentJP"] = "アスフォデロスにも子どもはいないし、家の近くにもそれらしい目撃情報はない。残るは劇場だ、行ってみよう。",
            ["DialogueId"] = 51003110,
            ["GUID"] = "7FAE51BC",
            ["SpeakNpcId"] = 100001,
            },
        [51003111] = {
            ["Content"] = "（售票厅旁的卡戎小孩哈着冷气，打着冷颤。不停向来往行人推销着门票、海报、啤酒和爆米花。）",
            ["ContentJP"] = "チケット売り場近くで、寒さに震えながら小さな子どもがチラシやポップコーンを売っている。",
            ["DialogueId"] = 51003111,
            ["GUID"] = "7FAE51E6",
            ["NextDialogue"] = 51003112,
            },
        [51003112] = {
            ["Content"] = "（不停向路人推销商品的小孩，会是他灌醉的巴克先生吗？）",
            ["ContentJP"] = "待ちゆく人に商品を勧めている子ども。彼がバックさんを酔わせた犯人なのかな？",
            ["DialogueId"] = 51003112,
            ["GUID"] = "7FAE5210",
            ["SpeakNpcId"] = 100001,
            },
        [51003113] = {
            ["Content"] = "巴克先生经常出入剧院，一定多次碰到并拒绝过那个小孩推销啤酒……",
            ["ContentJP"] = "バックさんは劇場によく出入りしていた。この子に何度も飲み物を売りつけられていたに違いない。",
            ["DialogueId"] = 51003113,
            ["Duration"] = 3,
            ["GUID"] = "7FAE523A",
            ["NextDialogue"] = 51003114,
            ["SpeakNpcId"] = 100001,
            },
        [51003114] = {
            ["Content"] = "他袖口粘着的那几枚爆米花，跟我窗户下捡到的一模一样。怎么看他的嫌疑都很大，过去聊聊看吧。",
            ["ContentJP"] = "窓下で拾ったポップコーンの欠片と、あの子の持っているポップコーン……同じだ。間違いない、話を聞いてみよう。",
            ["DialogueId"] = 51003114,
            ["Duration"] = 4,
            ["GUID"] = "7FAE5264",
            ["SpeakNpcId"] = 100001,
            },
        [51003115] = {
            ["Content"] = "喝啊，我还能喝……不就是二十几瓶啤酒嘛，这才哪到哪啊！来，继续上酒继续喝！",
            ["ContentJP"] = "飲むぞ～！俺はまだ飲める！あと二十本は余裕だ！もっとビール持ってこい！",
            ["DialogueId"] = 51003115,
            ["GUID"] = "7FAE528E",
            ["NextDialogue"] = 51003116,
            ["SpeakNpcId"] = 700214,
            },
        [51003116] = {
            ["Content"] = "（浑身酒气的大叔。会是他灌醉的巴克先生吗？）",
            ["ContentJP"] = "ベロベロに酔ったオジサン。彼がバックさんを酔わせた犯人なのかな？",
            ["DialogueId"] = 51003116,
            ["GUID"] = "7FAE52B8",
            ["SpeakNpcId"] = 100001,
            },
        [51003117] = {
            ["Content"] = "那个爆米花……是什么味道的呀，爸爸，我想尝尝看！",
            ["ContentJP"] = "パパ、あのポップコーン食べてみたい～！",
            ["DialogueId"] = 51003117,
            ["GUID"] = "7FAE52E2",
            ["LookAt"] = {
                [1] = "700215:n(700219)",
                [2] = "700219:n(700215)",
                },
            ["NextDialogue"] = 51003118,
            ["SpeakNpcId"] = 700215,
            },
        [51003118] = {
            ["Content"] = "孩子，你是个淑女，不应该吃那种垃圾食品，等看完歌剧了，爸爸带你去银色和平餐厅吃大餐。",
            ["ContentJP"] = "ダメだ。あんなジャンクフードは身体に悪い。劇が終わったらレストランに連れて行ってやろう。",
            ["DialogueId"] = 51003118,
            ["GUID"] = "7FAE530C",
            ["NextDialogue"] = 51003119,
            ["SpeakNpcId"] = 700219,
            ["TalkActionId"] = {
                [1] = "700219:Talk03_Start",
                },
            },
        [51003119] = {
            ["Content"] = "好吧……",
            ["ContentJP"] = "……はぁい。",
            ["DialogueId"] = 51003119,
            ["GUID"] = "7FAE5336",
            ["NextDialogue"] = 51003120,
            ["SpeakNpcId"] = 700215,
            ["TalkActionId"] = {
                [1] = "700219:Talk03_End",
                },
            },
        [51003120] = {
            ["Content"] = "（出现在剧院附近的小孩，很想尝一口爆米花的样子。会是她灌醉的巴克先生吗？）",
            ["ContentJP"] = "劇場前にいる子ども。ポップコーンに興味津々だ。彼女がバックさんを酔わせた犯人なのかな？",
            ["DialogueId"] = 51003120,
            ["GUID"] = "7FAE5360",
            ["SpeakNpcId"] = 100001,
            },
        [51003301] = {
            ["Content"] = "阿嚏！怎么好像更冷了……",
            ["ContentJP"] = "ハックチュン！なんだかいつもより寒いや……",
            ["DialogueId"] = 51003301,
            ["GUID"] = "7FAE7112",
            ["NextDialogue"] = 51003302,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Sigh_Start",
                },
            },
        [51003302] = {
            ["Content"] = "就算是卡戎，不怕冷也是有极限的……到了晚上起码会降温二十多度，说不定又有孩子要冻死了，唉……",
            ["ContentJP"] = "カロンといえど無理なものは無理だよ……夜は一気に冷えるのが普通だし……20℃差だっけ。また凍死するヤツも出そうかな、はは……",
            ["DialogueId"] = 51003302,
            ["GUID"] = "7FAE713C",
            ["NextDialogue"] = 51003303,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Sigh_End",
                },
            },
        [51003303] = {
            ["Content"] = "你好。",
            ["ContentJP"] = "こんにちは。",
            ["DialogueId"] = 51003303,
            ["GUID"] = "7FAE7166",
            ["NextDialogue"] = 51003304,
            ["SpeakNpcId"] = 100001,
            },
        [51003304] = {
            ["Content"] = "您好，尊敬的阁下！看戏辛苦了！坐了三个小时，您一定饿了吧！想来点零食和饮品吗？",
            ["ContentJP"] = "これはどうも親愛なるお客様！ご観劇お疲れさまでございました！3時間もお座りになられたのなら、きっとお腹がお空きでしょう？お菓子やお飲み物はいかがでしょうか？",
            ["DialogueId"] = 51003304,
            ["GUID"] = "7FAE7190",
            ["NextDialogue"] = 51003305,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_Start",
                },
            },
        [51003305] = {
            ["Content"] = "或者您感动于精彩的表演，想看一看有演员签名的海报呢？",
            ["ContentJP"] = "それか素晴らしいショーに心動かされたのですか？ならば俳優のサイン入りポスターなどご覧になられませんか？",
            ["DialogueId"] = 51003305,
            ["GUID"] = "7FAE71BA",
            ["NextOptions"] = {
                [1] = 510033051,
                [2] = 510033052,
                },
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003306] = {
            ["Content"] = "让我瞧瞧你都卖些什么。",
            ["ContentJP"] = "{性别:何を売っているのか見せてよ。|何を売っているのか見せてくれ。}",
            ["DialogueId"] = 51003306,
            ["GUID"] = "7FAE71E4",
            ["NextDialogue"] = 51003307,
            ["SpeakNpcId"] = 100001,
            },
        [51003307] = {
            ["Content"] = "维蒂的珍藏版签名海报，《冰湖往事》的纪念手册，冰山融水，剧院联名版爆米花，以及清甜的啤酒！",
            ["ContentJP"] = "ヴィティの特別サイン入りポスター、『アイスフォルクテイル』記念ハンドブック、氷山の湧き水、劇場コラボのポップコーン、そしてさっぱりビールです！",
            ["DialogueId"] = 51003307,
            ["GUID"] = "7FAE720E",
            ["NextDialogue"] = 51003308,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain01_Start",
                },
            },
        [51003308] = {
            ["Content"] = "您放心，这度数聊胜于无，喝不醉人的！",
            ["ContentJP"] = "ご安心を、度数はないのと同じぐらいですから、酔っ払うことはありゃしません！",
            ["DialogueId"] = 51003308,
            ["GUID"] = "7FAE7238",
            ["NextDialogue"] = 51003309,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain01_End",
                },
            },
        [51003309] = {
            ["Content"] = "那可不一定……你认识剧作家巴克先生吗？",
            ["ContentJP"] = "{性别:必ずそうだとは言い切れないと思うけど……ところで劇作家のバックさんって知っているかな？|必ずそうだとは言い切れないと思うけど……ところで劇作家のバックさんって知っているか？}",
            ["DialogueId"] = 51003309,
            ["GUID"] = "7FAE7262",
            ["NextDialogue"] = 51003310,
            ["SpeakNpcId"] = 100001,
            },
        [51003310] = {
            ["Content"] = "当然认识！他是剧院的常客，也经常光顾我的生意，身为贵族但尊重我这样的卡戎小孩，是难得一见的大好人！",
            ["ContentJP"] = "もちろん存じておりますとも！劇場の常連様で私のところにもよく足を運んでくださります！高貴なお方でありながら僕のようなカロンにもお目をかけてくださる大変素晴らしいお人でございますね！",
            ["DialogueId"] = 51003310,
            ["GUID"] = "7FAE728C",
            ["NextDialogue"] = 51003311,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Agree",
                },
            },
        [51003311] = {
            ["Content"] = "我知道有人嘲笑他，但比起那些人，巴克先生更值得尊敬。",
            ["ContentJP"] = "あの方を冷やかす連中もいますが、そんな人たちよりもバック先生の方が何倍も尊敬に値しますよ。",
            ["DialogueId"] = 51003311,
            ["GUID"] = "7FAE72B6",
            ["NextDialogue"] = 51003312,
            ["SpeakNpcId"] = 700080,
            },
        [51003312] = {
            ["Content"] = "这不是你从窗台摸进他家，偷偷在他牛奶里倒酒的理由。",
            ["ContentJP"] = "だからといって、夜中に彼の家に忍び込んで、ミルクに酒を仕込む理由にはならないよ。",
            ["DialogueId"] = 51003312,
            ["GUID"] = "7FAE72E0",
            ["NextDialogue"] = 51003313,
            ["SpeakNpcId"] = 100001,
            },
        [51003313] = {
            ["Content"] = "你、你是怎么知道的……",
            ["ContentJP"] = "あ、ど、どうして、知って……",
            ["DialogueId"] = 51003313,
            ["GUID"] = "7FAE730A",
            ["NextDialogue"] = 51003321,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Shock_Start",
                },
            },
        [51003314] = {
            ["Content"] = "巴克先生总在夜间进行创作，你的行为让他的剧本一个月都没有进展，于是他雇佣我去寻找神秘的“灵感飞贼”。",
            ["ContentJP"] = "{性别:バックさんはいつも夜中に創作活動する人みたいなの。あなたがやったことのせいで1ヶ月も脚本の筆が進まなかったみたいでね、謎の「インスピレーション泥棒」を見つけて欲しいって私を雇ったのよ。|バックさんはいつも夜中に創作活動する人みたいなんだ。あなたがやったことのせいで1ヶ月も脚本の筆が進まなかったみたいでさ、謎の「インスピレーション泥棒」を見つけて欲しいって僕を雇ったんだ。}",
            ["DialogueId"] = 51003314,
            ["GUID"] = "7FAE7334",
            ["NextOptions"] = {
                [1] = 510033141,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700080:Shock_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003315] = {
            ["Content"] = "（想说的话突然卡在嘴边，在脑海里重新整理一下措辞吧。）",
            ["ContentJP"] = "（言いたいことが口から出る前に引っかかった。頭の中でもう一度整理してみよう）",
            ["DialogueId"] = 51003315,
            ["GUID"] = "7FAE735E",
            },
        [51003316] = {
            ["Content"] = "你的生意并不支持你买到足够的过冬物资，巴克先生虽然没什么钱，但好歹是个贵族，他的房子足够暖和，所以你才想潜入巴克先生家取暖。",
            ["ContentJP"] = "{性别:冬を生き延びるための物資を買うには売った物の利益だけじゃ足りないはず。バックさんはお金がないといっても曲がりなりに貴族だから家が十分に暖かい。というわけで暖を取るためにバックさんの家に忍び込んだって感じかな？|冬を生き延びるための物資を買うには売った物の利益だけじゃ足りないはず。バックさんはお金がないといっても曲がりなりに貴族だから家が十分に暖かい。というわけで暖を取るためにバックさんの家に忍び込んだって感じだな？}",
            ["DialogueId"] = 51003316,
            ["GUID"] = "7FAE7388",
            ["NextDialogue"] = 51003317,
            ["SpeakNpcId"] = 100001,
            },
        [51003317] = {
            ["Content"] = "至于为什么是巴克先生，那是因为不管度数有多低，只要沾一点点酒他都会睡过去，在这之后你就能安心地睡上一整晚而不必担心被冻死，对吗？",
            ["ContentJP"] = "{性别:バックさんを選んだ理由は、度数の低いお酒を少し口にするだけでも彼は眠り落ちてしまうから。寝てしまえば気づかれることなく安心して一夜を乗り越えられる……でしょ？|バックさんを選んだ理由は、度数の低いお酒を少し口にするだけでも彼は眠り落ちてしまうから。寝てしまえば気づかれることなく安心して一夜を乗り越えられる……だよな？}",
            ["DialogueId"] = 51003317,
            ["GUID"] = "7FAE73B2",
            ["NextDialogue"] = 51003318,
            ["SpeakNpcId"] = 100001,
            },
        [51003318] = {
            ["Content"] = "唉……您可真是名侦探再世，事情就像您说的一样。",
            ["ContentJP"] = "ええ……お客様は名探偵の生まれ変わりだ。事情はまさに仰った通りです。",
            ["DialogueId"] = 51003318,
            ["GUID"] = "7FAE73DC",
            ["NextDialogue"] = 51003319,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_Start",
                },
            },
        [51003319] = {
            ["Content"] = "您把我抓起来吧，我感到十分抱歉，但如果不这么做，我连被您抓起来的机会都没有……",
            ["ContentJP"] = "どうぞ僕をお捕まえください。捕まって当然のことをしでかしたのですから、これは自業自得です……申し訳ない……",
            ["DialogueId"] = 51003319,
            ["GUID"] = "7FAE7406",
            ["NextDialogue"] = 51003320,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700080:Explain02_End",
                },
            },
        [51003320] = {
            ["Content"] = "我没有权利决定怎么处理你，我会带你去见我的雇主。",
            ["ContentJP"] = "{性别:僕にどうするかを決める権利はないから、とりあえずバックさんのところまで連行するよ。|私にどうするかを決める権利はないから、とりあえずバックさんのところまで連行するよ。}",
            ["DialogueId"] = 51003320,
            ["GUID"] = "7FAE7430",
            ["SpeakNpcId"] = 100001,
            },
        [51003321] = {
            ["Content"] = "（果然如此。）",
            ["ContentJP"] = "（やっぱり。）",
            ["DialogueId"] = 51003321,
            ["GUID"] = "7FAE730B",
            ["NextDialogue"] = 51003314,
            ["SpeakNpcId"] = 100001,
            },
        [51003401] = {
            ["Camera"] = "98.558472,-67.410156,133.285156,0.0,-1.600033,173.800858,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我找到人了。",
            ["ContentJP"] = "見つけました。",
            ["DialogueId"] = 51003401,
            ["GUID"] = "7FAE817A",
            ["LookAt"] = {
                [1] = "700102:n(100001)",
                [2] = "100001:n(700102)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                },
            },
        [51003402] = {
            ["Content"] = "你将事情的来龙去脉告知给了巴克先生。",
            ["ContentJP"] = "（あなたはバックさんに経緯を伝えた）",
            ["DialogueId"] = 51003402,
            ["Duration"] = 3,
            ["GUID"] = "7FAE81A4",
            },
        [51003403] = {
            ["Camera"] = "-262.830322,120.149414,121.775391,0.000007,-0.200008,-45.795547,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦！我的勇士，对您道一万次的感谢！想必从今夜起，灵感女神的宠爱将重回我身！",
            ["ContentJP"] = "おお、我が勇士よ！勇士に1万回の拍手喝采を！今宵からインスピレーションの女神の寵愛が、再び我が身に戻るであろう！",
            ["DialogueId"] = 51003403,
            ["GUID"] = "7FAE81CE",
            ["LookAt"] = {
                [1] = "700102:n(100001)",
                },
            ["NextDialogue"] = 51003404,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700102:Agree",
                },
            ["TurnTo"] = {
                [1] = "700103:n(700102)",
                },
            },
        [51003404] = {
            ["Camera"] = "-73.412354,63.213867,126.775391,0.000008,0.200002,-62.796665,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "至于你……我梦中的小飞贼，你可真是给了我一个莫大的意外！",
            ["ContentJP"] = "続けて……私の夢中にいた小さき泥棒よ。君は真に莫大なサプライズを私に与えてくれたな！",
            ["DialogueId"] = 51003404,
            ["GUID"] = "7FAE81F8",
            ["LookAt"] = {
                [1] = "700102:n(700103)",
                },
            ["NextDialogue"] = 51003405,
            ["SpeakNpcId"] = 700015,
            ["TurnTo"] = {
                [1] = "700102:n(700103)",
                },
            },
        [51003405] = {
            ["Camera"] = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "非常抱歉，巴克先生……但请您相信我，我从没有要伤害你的意思……",
            ["ContentJP"] = "本当に申し訳ありません、バック先生……でもどうか信じてもらいたい。あなたを傷つける気はこれっぽっちもなかったんです……",
            ["DialogueId"] = 51003405,
            ["GUID"] = "7FAE8222",
            ["LookAt"] = {
                [1] = "700103:n(700102)",
                },
            ["NextDialogue"] = 51003406,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700103:Explain02_Start",
                },
            },
        [51003406] = {
            ["Camera"] = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦，小飞贼，我知道人们在背后是怎么笑话我的，我是个卖不出作品的废物剧作家。",
            ["ContentJP"] = "ああ、小さき泥棒。私は把握しているのだよ。売れない作品ばかりの三流劇作家だと皆が陰口を吹かせているのは。",
            ["DialogueId"] = 51003406,
            ["GUID"] = "7FAE824C",
            ["LookAt"] = {
                [1] = "700102:n(700103)",
                },
            ["NextDialogue"] = 51003407,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700103:Explain02_End",
                },
            },
        [51003407] = {
            ["Camera"] = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就算用再优美的辞藻装饰我的言语，也换不来他们对我的欣赏，他们拒绝倾听，拒绝理解……但依我看，这世上又有几个能有话直说的人呢？",
            ["ContentJP"] = "どれほど美しいレトリックで言葉を飾っても、彼らから称賛を受けるなど早々ないだろう。彼らは理解できぬモノを拒む、耳を傾ける努力さえ億劫だ……飾らず話せる人など世界に存在し得ぬというのにな。",
            ["DialogueId"] = 51003407,
            ["GUID"] = "7FAE8276",
            ["LookAt"] = {
                [1] = "700102:n(700103)",
                },
            ["NextDialogue"] = 51003408,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700102:Talk03_Start",
                },
            },
        [51003408] = {
            ["Camera"] = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "先生，我不明白您的意思。",
            ["ContentJP"] = "先生、できれば噛み砕いてご説明いただけると……",
            ["DialogueId"] = 51003408,
            ["GUID"] = "7FAE82A0",
            ["LookAt"] = {
                [1] = "700103:n(700102)",
                },
            ["NextDialogue"] = 51003409,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700102:Talk03_End",
                [2] = "700103:Disagree",
                },
            },
        [51003409] = {
            ["Camera"] = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我是说，你从不把我当成一个只知道痴人说梦的蠢货，那么对于你，我也有自己的尊重，如果你无法渡过这个冬天，何不早说呢？",
            ["ContentJP"] = "私としては尊重したいわけだな。私を支離滅裂な語り口調の愚者だと扱わなかった君を。なぜ速やかに冬を乗り越えるのが難しいと教えてくれなかったのだ？",
            ["DialogueId"] = 51003409,
            ["GUID"] = "7FAE82CA",
            ["LookAt"] = {
                [1] = "700102:n(700103)",
                },
            ["NextDialogue"] = 51003410,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700102:Agree",
                },
            },
        [51003410] = {
            ["Camera"] = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我会为你收拾出房间，如果你乐意，还能拿起我的稿纸当睡前故事，只是我不确定那些故事是否足够助眠。",
            ["ContentJP"] = "君の部屋を用意するとしよう。もし君が望むのであれば就寝時、私の原稿を枕元に携えてもよい。ただ私の物語で睡眠の質が上がるのかは別の話だが。",
            ["DialogueId"] = 51003410,
            ["GUID"] = "7FAE82F4",
            ["LookAt"] = {
                [1] = "700102:n(700103)",
                },
            ["NextDialogue"] = 51003411,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700102:Explain01_Start",
                },
            },
        [51003411] = {
            ["Camera"] = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "您真的愿意收留我吗……我不值得您这样做，但我可以帮您做一些琐事，就当是我耽误您一个月创作的补偿吧……",
            ["ContentJP"] = "受け入れて……くださるのですか？本当に……僕にそんな価値は。ですがこの1ヶ月の創作を遅らせた償いはします！身の回りのお世話ぐらいは、やらせてください……！",
            ["DialogueId"] = 51003411,
            ["GUID"] = "7FAE831E",
            ["LookAt"] = {
                [1] = "700103:n(700102)",
                },
            ["NextDialogue"] = 51003412,
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700102:Explain01_End",
                [2] = "700103:Explain02_Start",
                },
            },
        [51003412] = {
            ["Camera"] = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "感谢您所做的一切，尊敬的狩月人阁下！明察秋毫的冰湖城侦探非您莫属，我收获了一个温馨的故事，也收获了两个诚挚的朋友。",
            ["ContentJP"] = "謳われるべき月狩り人どの。君が巡らせた万物に心からの感謝を。優れた洞察力を有するアイスレイク城の探偵として、君は唯一無二であろう。私は一節の温かな物語を、そしてふたりの誠実な友を得ることができた。",
            ["DialogueId"] = 51003412,
            ["GUID"] = "7FAE8348",
            ["LookAt"] = {
                [1] = "700102:n(100001)",
                },
            ["NextDialogue"] = 51003413,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700103:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "700102:n(100001)",
                },
            },
        [51003413] = {
            ["Camera"] = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊！灵感纷至沓来！我得迅速回去把他们记下来，如果我的诗篇能得到传颂，千百年后人们也依然赞美着您的名字！",
            ["ContentJP"] = "ああ！インスピレーションが間断なく溢れて止まぬ！早急に帰らねば！一切を書き留めなければ！もし後世に私の詩が言い伝えられたならば、何千何百年であろうと人々は君の名を賛美し続けるであろう！",
            ["DialogueId"] = 51003413,
            ["GUID"] = "7FAE8372",
            ["LookAt"] = {
                [1] = "700102:n(100001)",
                },
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700102:Talk01_Start",
                },
            },
        [51003414] = {
            ["Content"] = "两人一起离去了，每个人都得到了他想要的，不知道巴克先生的下一部大作是否能和他说的一样精彩。",
            ["ContentJP"] = "（ふたりは一緒に立ち去り、誰もが自分の願い事を叶えた。次の大作がバックさんの言うように素晴らしいものとなるかどうかは未知数だが）",
            ["DialogueId"] = 51003414,
            ["Duration"] = 4,
            ["GUID"] = "7FAE839C",
            },
        }
  end },
  { MinKey = 51003501, MaxKey = 51004502, Loader = function()
      return {
        [51003501] = {
            ["Camera"] = "-813.361816,168.229736,207.784668,0.000003,-6.799986,-16.405685,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "感谢牺牲、感谢慈悲、感谢银色和平，让我们远离瘟疫，让我们远离蒙昧，让我们远离恶魔的威胁……",
            ["ContentJP"] = "我らを疫病や蒙昧、異族の脅威から遠ざけて下さった英霊たちに言葉をお贈りいたします。犠牲に感謝を。慈悲に感謝を。銀色の平和に感謝を。",
            ["DialogueId"] = 51003501,
            ["GUID"] = "7FAE91E2",
