        [51003503] = {
            ["Camera"] = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱歉老师！我这就来！",
            ["ContentJP"] = "あ、ご、ごめんなさい、先生！今すぐに！",
            ["DialogueId"] = 51003503,
            ["GUID"] = "7FAE9236",
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700086:Confident_End",
                [2] = "700016:Shock_Start",
                },
            },
        [51003504] = {
            ["Camera"] = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你这孩子最近怎么魂不守舍的，下次可不能这样了。",
            ["ContentJP"] = "最近は何事にも集中できていないご様子ですが？次回は許しませんからね。",
            ["DialogueId"] = 51003504,
            ["GUID"] = "7FAE9260",
            ["NextDialogue"] = 510035041,
            ["SpeakNpcId"] = 700086,
            ["TalkActionId"] = {
                [1] = "700086:Sigh_Start",
                },
            },
        [51003505] = {
            ["Content"] = "唉……真无聊……不知道婆婆在做什么呢？",
            ["ContentJP"] = "はぁ……本当つまんない……今頃おばあちゃん、何してるのかしら？",
            ["DialogueId"] = 51003505,
            ["GUID"] = "7FAE928A",
            ["NextOptions"] = {
                [1] = 510035051,
                [2] = 510035052,
                [3] = 510035053,
