            ["SpeakNpcId"] = 700016,
            ["bForbidSkipOptions"] = true,
            },
        [51003506] = {
            ["Content"] = "当然有原因啦，告诉你也不是不行，但你得保证守口如瓶。",
            ["ContentJP"] = "色々とこっちも訳があるの。別に教えてあげてもいいけど、誰にも教えないって約束が守れない人には無理よ。",
            ["DialogueId"] = 51003506,
            ["GUID"] = "7FAE92B4",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510035061,
                },
            ["RestartTag"] = 51003506,
            ["SpeakNpcId"] = 700016,
            ["bForbidSkipOptions"] = true,
            },
        [51003507] = {
            ["Content"] = "像，很像啊！",
            ["ContentJP"] = "ええ、そう見えるわ！",
            ["DialogueId"] = 51003507,
            ["GUID"] = "7FAE92DE",
            ["SpeakNpcId"] = 700016,
            },
        [51003508] = {
            ["Content"] = "那我就告诉你吧！",
            ["ContentJP"] = "じゃあ、あなたには教えてあげる！",
            ["DialogueId"] = 51003508,
            ["GUID"] = "7FAE9308",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextDialogue"] = 51003509,
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Confident_Start",
                },
            },
        [51003509] = {
            ["Content"] = "上个月我偷偷溜去贫民窟玩，结果在小巷子里碰到了一个神秘的老婆婆！",
            ["ContentJP"] = "先月こっそりスラム街に遊びに行ったらね、路地裏で謎のおばあちゃんと出会ったのよ！",
            ["DialogueId"] = 51003509,
            ["GUID"] = "7FAE9332",
            ["NextDialogue"] = 51003510,
            ["SpeakNpcId"] = 700016,
            },
        [51003510] = {
            ["Content"] = "她手可巧啦，会给我编各种花式的小辫子，会用鲜花给我染指甲，还知道许许多多我从来没听过的小故事！",
            ["ContentJP"] = "おばあちゃんはとても手先が器用なのよ！色々な結び方で髪の毛を編んでくれたり、花で爪を染めてくれたりもしたわ。全然知らないお話とかもいっぱい知ってるの！",
            ["DialogueId"] = 51003510,
            ["GUID"] = "7FAE935C",
            ["NextDialogue"] = 51003511,
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Confident_End",
                },
            },
        [51003511] = {
            ["Content"] = "她从不对我说教，也不把我当小孩糊弄，虽然那是我们头一回见，但她搂着我的时候就像我奶奶一样温暖……",
            ["ContentJP"] = "おばあちゃんは私にお説教したりしないし、私を子ども扱いして適当にあしらったりしないわ。初めて会った時も私を抱き寄せてくれたの。まるで本当のおばあちゃんみたいに暖かかった……",
            ["DialogueId"] = 51003511,
            ["GUID"] = "7FAE9386",
            ["NextDialogue"] = 51003512,
            ["SpeakNpcId"] = 700016,
            },
        [51003512] = {
            ["Content"] = "那不是很好吗？为什么不坦然告诉别人你有新朋友了呢？",
            ["ContentJP"] = "素敵なことなのに、普通に新しい友達ができたって周りの人には教えないの{性别:か|}？",
            ["DialogueId"] = 51003512,
            ["GUID"] = "7FAE93B0",
            ["NextDialogue"] = 51003513,
            ["SpeakNpcId"] = 100001,
            },
        [51003513] = {
            ["Content"] = "因为婆婆长了角……如果我告诉父母、同学、老师，一定会让她受到伤害吧……",
            ["ContentJP"] = "おばあちゃんには角が生えてるから……お父様やお母様も、同級生に先生だってイジめるに決まってるもの。そのことを知ったらおばあちゃんを……",
            ["DialogueId"] = 51003513,
            ["GUID"] = "7FAE93DA",
            ["NextDialogue"] = 51003514,
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Explain02_Start",
                },
            },
        [51003514] = {
            ["Content"] = "我们本来约好了今天见面，可是学校临时增加了纪念活动，我只能爽约了，如果你有空，可不可以帮我把这个布娃娃带给她？",
            ["ContentJP"] = "今日はおばあちゃんと会うって約束してたんだけど、学校が臨時で記念行事を始めるとか言い出しちゃってさ、約束が守れなくなっちゃって。もし暇なら、このぬいぐるみをおばあちゃんに渡してくれたりしないかしら？",
            ["DialogueId"] = 51003514,
            ["GUID"] = "7FAE9404",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510035141,
                [2] = 51000002,
                },
            ["SpeakNpcId"] = 700016,
            ["TalkActionId"] = {
                [1] = "700016:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003515] = {
            ["Content"] = "集合时间到了，拜托你可千万要送到哦！谢谢你！",
            ["ContentJP"] = "あ、もう集合時間が！ありがとね！絶対届けてよ！",
            ["DialogueId"] = 51003515,
            ["GUID"] = "7FAE942E",
            ["SpeakNpcId"] = 700016,
            },
        [51003520] = {
            ["Content"] = "下面由艾玛献上纪念的花……",
            ["ContentJP"] = "続けて学生代表のエマによる献花が……",
            ["DialogueId"] = 51003520,
            ["GUID"] = "7FAE9500",
            ["NextDialogue"] = 51003502,
            ["SpeakNpcId"] = 700086,
            },
        [51003601] = {
            ["Camera"] = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢你，婆婆，我觉得好多了，如果这是罗伯期望的，我会为了他好好生活。",
            ["ContentJP"] = "おばあさん、ありがとう。だいぶ気分も晴れたよ。それがロブの望みだったら、俺もあいつのために努力して生き続けないとね。",
            ["DialogueId"] = 51003601,
            ["GUID"] = "7FAEA24A",
            ["NextDialogue"] = 51003602,
            ["SpeakNpcId"] = 700087,
            ["TalkActionId"] = {
                [1] = "700087:Explain02_Start",
                },
            },
        [51003602] = {
            ["Camera"] = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "希望你早日走出悲痛，我们与你同在，孩子，如果你需要，贝琳达的小屋永远为你开放。",
            ["ContentJP"] = "早く悲しみから抜け出すんだよ。愛しい子や、あたしたちはあんたとともにあるからさ。もし必要ならベリンダの小屋はいつでも開けておくよ。あんたのためにいつまでも。",
            ["DialogueId"] = 51003602,
            ["GUID"] = "7FAEA274",
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700087:Explain02_End",
                [2] = "700081:Explain01_Start",
                },
            },
        [51003604] = {
            ["Content"] = "你好呀！我从没见过你，我猜你是刚来冰湖城的朋友？找贝琳达有什么事呢？",
            ["ContentJP"] = "おやまあこんにちは！あんたとは初めましてかねぇ。アイスレイク城には着いたばかりかい？このベリンダに何かご用でも？",
            ["DialogueId"] = 51003604,
            ["GUID"] = "7FAEA2C8",
            ["NextOptions"] = {
                [1] = 510036041,
                },
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain01_Start",
                },
            },
        [51003605] = {
            ["Content"] = "（虽然手艺粗糙，但你能看出娃娃和贝琳达有几分相似。卡戎婆婆满是喜悦，将娃娃抚摸了一遍又一遍。）",
            ["ContentJP"] = "（つたない技術で作られているぬいぐるみだが、ベリンダに少し似ているのは分かった。カロンのおばあさんはとても嬉しそうに、何度も何度もぬいぐるみに触れる）",
            ["DialogueId"] = 51003605,
            ["GUID"] = "7FAEA2F2",
            ["NextDialogue"] = 51003606,
            ["TalkActionId"] = {
                [1] = "700081:Explain01_End",
                },
            },
        [51003606] = {
            ["Content"] = "我从娃娃上感觉到了广场的气息……啊，瞧我这记性！纪念周到啦，这时候的活动总是很多……",
            ["ContentJP"] = "ぬいぐるみから広場の気配を感じる……ああ、すっかりと忘れていたよ！記念週間の時期はひっきりなしに行事があるもんさ……",
            ["DialogueId"] = 51003606,
            ["GUID"] = "7FAEA31C",
            ["NextDialogue"] = 51003607,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Agree",
                },
            },
        [51003607] = {
            ["Content"] = "我很感谢你，孩子。",
            ["ContentJP"] = "わざわざありがとうねぇ、優しい子や。",
            ["DialogueId"] = 51003607,
            ["GUID"] = "7FAEA346",
            ["NextDialogue"] = 51003608,
            ["SpeakNpcId"] = 700081,
            },
        [51003608] = {
            ["Content"] = "（她仔细地端详着你，有好几分钟都没有说话。）",
            ["ContentJP"] = "（そう言った途端に彼女はあなたのことをじっと見つめ始める。何分間もしゃべらずに）",
            ["DialogueId"] = 51003608,
            ["GUID"] = "7FAEA370",
            ["NextDialogue"] = 51003609,
            },
        [51003609] = {
            ["Content"] = "你好像惹上了大麻烦，我闻到了海风的味道，感受到了潮水的包裹，还有……你手掌上残留的，他人的温度，但这份温暖正逐渐远去……",
            ["ContentJP"] = "あんた……大きな災いに巻き込まれたのかい……鼻を抜ける海風の香り……あたしも体が潮水で覆われた気分になるよ。そして手のひらに残っているのは……誰かの温もり。その温もりが次第に遠ざかっていく……",
            ["DialogueId"] = 51003609,
            ["GUID"] = "7FAEA39A",
            ["NextDialogue"] = 51003610,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_Start",
                },
            },
        [51003610] = {
            ["Content"] = "来到这里的每时每刻，你都被困惑与悲伤缠绕，但你努力把这些压抑在心底，不去表露……",
            ["ContentJP"] = "アイスレイクに来てからも、あんたは困惑と悲壮の連鎖に巻き込まれているようだねぇ……なのに表に出さないよう努力をして……心底の想いを懸命に抑え込んで……",
            ["DialogueId"] = 51003610,
            ["GUID"] = "7FAEA3C4",
            ["NextDialogue"] = 51003611,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_End",
                },
            },
        [51003611] = {
            ["Content"] = "无意冒犯，你是否失去了重要之人？",
            ["ContentJP"] = "無礼を承知でお尋ねするけど。あんた、大切な人との繋がりが途絶えてしまったのかい？",
            ["DialogueId"] = 51003611,
            ["GUID"] = "7FAEA3EE",
            ["NextOptions"] = {
                [1] = 510036111,
                [2] = 510036112,
                [3] = 510036113,
                },
            ["SpeakNpcId"] = 700081,
            ["bForbidSkipOptions"] = true,
            },
        [51003612] = {
            ["Content"] = "能活到我这么大年纪的卡戎很稀奇吧？",
            ["ContentJP"] = "ほほ、珍しいだろう？こんな歳まで生きている、あたしみたいなカロンなんてのは。",
            ["DialogueId"] = 51003612,
            ["GUID"] = "7FAEA418",
            ["NextDialogue"] = 51003615,
            ["SpeakNpcId"] = 700081,
            },
        [51003613] = {
            ["Content"] = "你在难过，孩子。",
            ["ContentJP"] = "分かるさ、その悲しみ。",
            ["DialogueId"] = 51003613,
            ["GUID"] = "7FAEA442",
            ["NextDialogue"] = 51003615,
            ["SpeakNpcId"] = 700081,
            },
        [51003614] = {
            ["Content"] = "不用强撑，我知道的，孩子。",
            ["ContentJP"] = "無理をするんでないよ。あたしには分かるのさ。",
            ["DialogueId"] = 51003614,
            ["GUID"] = "7FAEA46C",
            ["NextDialogue"] = 51003615,
            ["SpeakNpcId"] = 700081,
            },
        [51003615] = {
            ["Content"] = "很遗憾，孩子，我没有帮助你的办法，但有一句话，我想正适合此时的你……",
            ["ContentJP"] = "優しい子や。残念ながらあたしは、あんたを助ける手立てを持ち合わせていない。だけど言葉を贈ることはできる。今のあんたにぴったりだと思う言葉さ……",
            ["DialogueId"] = 51003615,
            ["GUID"] = "7FAEA496",
            ["NextDialogue"] = 51003616,
            ["SpeakNpcId"] = 700081,
            },
        [51003616] = {
            ["Content"] = "“行人走上一线旅途，命运女神纺锤收束。当千头万绪重聚，失物在眼前沉浮。”",
            ["ContentJP"] = "「旅人が一筋の道を歩み、運命の女神の紡錘が巻かれた。千差万別の糸が再び集い、目の前に失物が浮かび上がる」",
            ["DialogueId"] = 51003616,
            ["GUID"] = "7FAEA4C0",
            ["NextOptions"] = {
                [1] = 510036161,
                },
            ["RestartTag"] = 51003616,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003617] = {
            ["Content"] = "孩子，你将在旅途中拾得你缺少的一切，去吧，去吧。",
            ["ContentJP"] = "優しい子や、欠けた全ては旅の道中で拾えるはずさ。いってらっしゃい。",
            ["DialogueId"] = 51003617,
            ["GUID"] = "7FAEA4EA",
            ["SpeakNpcId"] = 700081,
            },
        [51003618] = {
            ["Content"] = "出自《命运女神的纺锤》终幕……无可剥夺者在双面之境见到了自己失去的一切……你是在告诉我终有一天我们会再次相见？",
            ["ContentJP"] = "『運命の女神の紡錘』終幕から……全てを奪われた者が、対極の境で奪われた全てを見る……失ったとしても、いつかは必ず再会できるって言いたいのですか？",
            ["DialogueId"] = 51003618,
            ["GUID"] = "7FAEA514",
            ["NextDialogue"] = 51003619,
            ["SpeakNpcId"] = 100001,
            },
        [51003619] = {
            ["Content"] = "请把这句箴言当作送来娃娃的谢礼吧。你很聪明，孩子，就像我所看到的一样……不需要我告诉你什么，你会依靠自己的力量探明疑问。",
            ["ContentJP"] = "その一節をぬいぐるみのお礼とさせておくれ。あんたはあたしの見立て通り……とても賢い。手取り足取り教える必要もなさそうだねぇ。きっと自力で疑問を解き明かせるはずさ。",
            ["DialogueId"] = 51003619,
            ["GUID"] = "7FAEA53E",
            ["NextDialogue"] = 51003620,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Agree",
                },
            },
        [51003620] = {
            ["Content"] = "另外，我会送给每个初次来拜访我的人一件小礼物，只要一件带有你自身气息的铁丝就好，不急于现在，我会一直在这里等你。",
            ["ContentJP"] = "それと、初めて私を訪ねてくれた人には、ちょっとした贈り物を渡してるの。あなた自身の気配が染みついたワイヤーを一本持ってきて。今じゃなくてもいいわ、ここでずっと待ってるから。",
            ["DialogueId"] = 51003620,
            ["GUID"] = "7FAEA568",
            ["NextDialogue"] = 51003621,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_Start",
                },
            },
        [51003621] = {
            ["Content"] = "气息……虽然不太明白，但只要是我接触过的，或者在我身上待过的就可以吧。",
            ["ContentJP"] = "気配……よくわからないけど、触ったものとか、身に着けたものなら大丈夫ってことだよね。",
            ["DialogueId"] = 51003621,
            ["GUID"] = "7FAEA592",
            ["NextDialogue"] = 51003622,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700081:Explain02_End",
                },
            },
        [51003622] = {
            ["Content"] = "格雷姆废矿那里应该有不少铁丝，我去那边看看。",
            ["ContentJP"] = "グルビューム廃坑のあたりなら、ワイヤーがたくさん落ちてそう。行ってみよう。",
            ["DialogueId"] = 51003622,
            ["Duration"] = 3,
            ["GUID"] = "7FAEA5BC",
            ["SpeakNpcId"] = 100001,
            },
        [51003630] = {
            ["Content"] = "陌生的卡戎虽然还挂着泪痕，但你能从他的眼中看出，他已经燃起了活下去的勇气。",
            ["ContentJP"] = "見知らぬカロンの顔には涙の跡が。瞳の奥には生き抜こうと燃え盛る勇気が見て取れた。",
            ["DialogueId"] = 51003630,
            ["Duration"] = 4,
            ["GUID"] = "7FAEA70C",
            ["NextDialogue"] = 51003631,
            },
        [51003631] = {
            ["Content"] = "他与贝琳达拥抱后，依依不舍地离去了。",
            ["ContentJP"] = "彼はベリンダを抱きしめた後、名残惜しそうに立ち去っていく",
            ["DialogueId"] = 51003631,
            ["Duration"] = 2,
            ["GUID"] = "7FAEA736",
            },
        [51003701] = {
            ["Content"] = "（贝琳达从你手中接过铁丝，将其弯成了一枚侧脸肖像，你能看出这件小工艺品与贝蕾妮卡有些相似。）",
            ["ContentJP"] = "（ベリンダはあなたの手から針金を受け取った。すると針金を横顔の肖像画みたいな形に曲げ始めた。やがて完成した小さな工芸品にはベレニカの面影が窺える）",
            ["DialogueId"] = 51003701,
            ["GUID"] = "7FAEB2B2",
            ["NextDialogue"] = 51003702,
            },
        [51003702] = {
            ["Content"] = "我并不强大，只能看到些朦胧的影子，不知道这与你思念之人是否相像，只是希望这能让你好受一些。",
            ["ContentJP"] = "あたしの力はそう強くないから、ぼんやりとした影しか見えなかった。あんたの想い人に似ているかは見当もついていないけど、少しでも楽になれる代物が作れたのなら幸いさ。",
            ["DialogueId"] = 51003702,
            ["GUID"] = "7FAEB2DC",
            ["NextDialogue"] = 51003703,
            ["SpeakNpcId"] = 700081,
            ["TalkActionId"] = {
                [1] = "700081:Disagree",
                },
            },
        [51003703] = {
            ["Content"] = "衷心祝愿你们再次重逢。",
            ["ContentJP"] = "あんたともうひとりが再会を果たせるよう、心からお祈りしておくよ。",
            ["DialogueId"] = 51003703,
            ["GUID"] = "7FAEB306",
            ["NextDialogue"] = 51003704,
            ["SpeakNpcId"] = 700081,
            },
        [51003704] = {
            ["Content"] = "（你离开了贝琳达的小帐篷，现在你好像理解为什么艾玛对这里如此留恋了，贝琳达的力量并不强大，但她始终在治愈心灵，抚平伤痛。）",
            ["ContentJP"] = "（ベリンダの小さなテントから離れた。なぜエマがあんなにも彼女に会いたがっていたのか、分かった気がした。強い力を持っていなくとも、常に心を癒して痛みを和らげてくれるからだろう）",
            ["DialogueId"] = 51003704,
            ["GUID"] = "7FAEB330",
            },
        [51003705] = {
            ["Camera"] = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……这样应该就差不多了！",
            ["ContentJP"] = "うん……これだけあれば十分なはず！",
            ["DialogueId"] = 51003705,
            ["FinalCamera"] = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAEA5BD",
            ["NextDialogue"] = 51003706,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51003706] = {
            ["Camera"] = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "打打打打打劫！你怀里的宝贝是我的啦！",
            ["ContentJP"] = "ててて手を上げろ！その懐の物をよこせ！",
            ["DialogueId"] = 51003706,
            ["GUID"] = "7FAEA5BE",
            ["NextDialogue"] = 51003707,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},TurnTo{_delay{1},TurnToDescription{\"100001:p(180)\"}}}",
            ["SpeakNpcId"] = 700206,
            },
        [51003707] = {
            ["Camera"] = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（皎皎之民的身影猛地从一旁窜出，一把抢过你怀中的铁丝，一边跑一边回头嘲笑着你。）",
            ["ContentJP"] = "ルーナ族の影が突如飛び出してきて、あなたが抱えていたワイヤーをひったくった。そして、にやにや笑いながら逃げていった。",
            ["DialogueId"] = 51003707,
            ["GUID"] = "7FAEA5BF",
            ["NextDialogue"] = 51003708,
            ["Scripts"] = "MoveTo{ActorId{700206},TargetPoint{\"QuestPoint_DJMove\"},MoveSpeed{200},Visibility{\"Show\"}}",
            },
        [51003708] = {
            ["Camera"] = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "总算被我逮到机会了，这次我我我终于成功啦，哈哈哈哈哈哈哈！",
            ["ContentJP"] = "ついにチャンスをモノにしたぞ！ややややっと成功した、わはははは！",
            ["DialogueId"] = 51003708,
            ["GUID"] = "7FAEA5C0",
            ["NextDialogue"] = 51003709,
            ["SpeakNpcId"] = 700206,
            },
        [51003709] = {
            ["Camera"] = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（就算不知道贝琳达要这些铁丝做什么用，你也不打算让手中的东西被白白抢走，追上去好好教训她一番吧。）",
            ["ContentJP"] = "ワイヤーが何に使われるかは知らないが、ただで盗られてたまるか。追いかけて取り返そう！",
            ["DialogueId"] = 51003709,
            ["GUID"] = "7FAEA5C1",
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51003710] = {
            ["Content"] = "战胜打打打打打劫皎皎",
            ["ContentJP"] = "ルーナ族の略奪者に勝つ",
            ["DialogueId"] = 51003710,
            ["GUID"] = "7FAEA5C2",
            },
        [51003711] = {
            ["Camera"] = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "为了一堆破铜烂铁，至于打成这样嘛呜呜呜呜……",
            ["ContentJP"] = "たかがガラクタのために、なんでここまで……ぐすっ……",
            ["DialogueId"] = 51003711,
            ["GUID"] = "7FAEA5C3",
            ["SpeakNpcId"] = 700206,
            },
        [51003712] = {
            ["Content"] = "费了一些周折，你总算拿回了属于你的铁丝。检查无误再一抬头，发现那只皎皎早已不见了踪影。",
            ["ContentJP"] = "色々と手こずったが、無事に自分のワイヤーを取り戻すことができた。ふと顔を上げると、ルーナの姿はもう見当たらない。",
            ["DialogueId"] = 51003712,
            ["Duration"] = 5,
            ["GUID"] = "7FAEA5C4",
            ["NextDialogue"] = 51003713,
            },
        [51003713] = {
            ["Content"] = "你无奈地摇摇头，向着贝琳达的帐篷动身。",
            ["ContentJP"] = "ため息をつきつつ、ベリンダのテントへ向かうことにした。",
            ["DialogueId"] = 51003713,
            ["GUID"] = "7FAEA5C5",
            },
        [51003721] = {
            ["Content"] = "打打打打打劫皎皎已逃走，任务失败，请重新开始。",
            ["ContentJP"] = "天下御免の大泥棒が逃げてしまった。クエスト失敗、再チャレンジしてください。",
            ["DialogueId"] = 51003721,
            ["Duration"] = 3,
            ["GUID"] = "7FAEA5C6",
            },
        [51003801] = {
            ["Content"] = "你……卡戎……我的同类……",
            ["ContentJP"] = "あなたは……カロン……私と同族……",
            ["DialogueId"] = 51003801,
            ["GUID"] = "7FAEC31A",
            ["NextDialogue"] = 51003802,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Explain02_Start",
                },
            },
        [51003802] = {
            ["Content"] = "（眼前的少女喃喃地说着，眼神似乎是在看你，又似乎是在看着未知的远方。）",
            ["ContentJP"] = "（目の前の少女が何か呟いている。彼女の瞳はあなたを見ているようにも、未知の遠方を見ているようにも見える）",
            ["DialogueId"] = 51003802,
            ["GUID"] = "7FAEC344",
            ["NextOptions"] = {
                [1] = 510038021,
                [2] = 510038022,
                },
            ["TalkActionId"] = {
                [1] = "700012:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003803] = {
            ["Content"] = "你愿意帮我吗……？",
            ["ContentJP"] = "助けてくれるのですか……？",
            ["DialogueId"] = 51003803,
            ["GUID"] = "7FAEC36E",
            ["NextDialogue"] = 51003805,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Agree",
                },
            },
        [51003804] = {
            ["Content"] = "不……我不是索拉之民……",
            ["ContentJP"] = "ううん……私はソラの民じゃないのです……",
            ["DialogueId"] = 51003804,
            ["GUID"] = "7FAEC398",
            ["NextDialogue"] = 51003805,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            },
        [51003805] = {
            ["Content"] = "你看，我的……恶魔角。",
            ["ContentJP"] = "ほら見て、私の……悪魔の角を。",
            ["DialogueId"] = 51003805,
            ["GUID"] = "7FAEC3C2",
            ["NextDialogue"] = 51003806,
            ["SpeakNpcId"] = 700012,
            },
        [51003806] = {
            ["Content"] = "（女孩揪起自己的凌乱的发梢给你看，依稀可以看出那只是被拆掉了一半的辫子，没有任何角的痕迹。显然，她是一个如假包换的索拉之民。)",
            ["ContentJP"] = "（少女は自分の乱れた毛先をつかんで見せてくる。しかしそれは半分ほどけているだけのおさげ髪であって角の要素などない。彼女は正真正銘のソラの民である）",
            ["DialogueId"] = 51003806,
            ["GUID"] = "7FAEC3EC",
            ["NextDialogue"] = 51003807,
            },
        [51003807] = {
            ["Content"] = "这只是头发而已。",
            ["ContentJP"] = "それはただの髪の毛だよ。",
            ["DialogueId"] = 51003807,
            ["GUID"] = "7FAEC416",
            ["NextDialogue"] = 51003808,
            ["SpeakNpcId"] = 100001,
            },
        [51003808] = {
            ["Content"] = "不，这是角……它们只是被魔法隐藏起来了，所以看上去才像头发！他们都看到了……两根硕大无比的角！",
            ["ContentJP"] = "いいえ、角なのです……魔法で隠されているから髪のように見えるだけで！だってみんな見たって……2本のとても大きな角を！",
            ["DialogueId"] = 51003808,
            ["GUID"] = "7FAEC440",
            ["NextOptions"] = {
                [1] = 510038081,
                [2] = 510038082,
                },
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003809] = {
            ["Content"] = "是真的！虽然我也不知道该怎么解释，但是……",
            ["ContentJP"] = "本当なのです！どう説明すればいいか分かんないけど、でも……",
            ["DialogueId"] = 51003809,
            ["GUID"] = "7FAEC46A",
            ["NextDialogue"] = 51003811,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Agree",
                },
            },
        [51003810] = {
            ["Content"] = "我……我也不知道该怎么向你解释，但是……",
            ["ContentJP"] = "わ……私も、どう説明すればいいか分からないけど、でも……",
            ["DialogueId"] = 51003810,
            ["GUID"] = "7FAEC494",
            ["NextDialogue"] = 51003811,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            },
        [51003811] = {
            ["Content"] = "他们都这么说。",
            ["ContentJP"] = "みんながそう言うから。",
            ["DialogueId"] = 51003811,
            ["GUID"] = "7FAEC4BE",
            ["NextDialogue"] = 51003812,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Explain01_Start",
                },
            },
        [51003812] = {
            ["Content"] = "“他们”是谁？",
            ["ContentJP"] = "「みんな」って誰？",
            ["DialogueId"] = 51003812,
            ["GUID"] = "7FAEC4E8",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700012:Explain01_End",
                },
            },
        [51003813] = {
            ["Camera"] = "273.684082,-345.582031,101.247314,0.000134,0.0,134.992844,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费伊，原来你是跑到外城来了！可让我好找。",
            ["ContentJP"] = "フェイ、わざわざ外城区まで行っちまうなんてよ！探すの大変だったんだぜ～～？",
            ["DialogueId"] = 51003813,
            ["GUID"] = "7FAEC512",
            ["LookAt"] = {
                [1] = "700012:n(700089)",
                },
            ["NextDialogue"] = 51003814,
            ["SpeakNpcId"] = 700088,
            ["TurnTo"] = {
                [1] = "700012:n(700089)",
                [2] = "100001:n(700089)",
                },
            },
        [51003814] = {
            ["Camera"] = "-150.919434,85.612305,106.559326,0.000157,0.0,-35.397251,18.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么了？收到我们精心准备的礼物不开心吗？我雇了两个卡戎小孩才弄到那么多虫子，花了一整天的零花钱呢！",
            ["ContentJP"] = "どうしたんだよ？一生懸命準備してやったプレゼントなのに嬉しくないっていうのか？カロンをふたりも雇って大量のネズミを集めたのに。丸一日分のお小遣い使ったんだからな！",
            ["DialogueId"] = 51003814,
            ["GUID"] = "7FAEC53C",
            ["NextDialogue"] = 51003815,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Explain01_Start",
                },
            },
        [51003815] = {
            ["Camera"] = "-150.919434,85.612305,106.559326,0.000157,0.0,-35.397251,18.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "快回去吧，你跑来这种地方，可把大伙儿“担心”坏了。",
            ["ContentJP"] = "早くこっち帰ってこいよ。こんなとこまで行っちうもんだから、みんな「心配」してんだぞ？",
            ["DialogueId"] = 51003815,
            ["GUID"] = "7FAEC566",
            ["NextDialogue"] = 51003816,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Explain01_End",
                },
            },
        [51003816] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……我不要回去……",
            ["ContentJP"] = "わ……私、帰りたくない……",
            ["DialogueId"] = 51003816,
            ["GUID"] = "7FAEC590",
            ["NextDialogue"] = 51003817,
            ["Scripts"] = "SEQ{MoveTo{ActorId{100001},TargetPoint{\"QuestPoint_20021101\"},MoveSpeed{100}},TurnTo{TurnToDescription{\"100001:n(700089)\"}},PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Shock_Start",
                [2] = "700090:Confident_End",
                },
            },
        [51003817] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎，你们看，那边那个不是卡戎吗？",
            ["ContentJP"] = "ちょいちょい、アレってさ、ひょっとしてカロン？",
            ["DialogueId"] = 51003817,
            ["GUID"] = "7FAEC5BA",
            ["NextDialogue"] = 51003818,
            ["SpeakNpcId"] = 700089,
            ["TurnTo"] = {
                [1] = "700088:n(100001)",
                [2] = "700089:n(100001)",
                [3] = "700090:n(100001)",
                },
            },
        [51003818] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈哈，我就说她是恶魔嘛！",
            ["ContentJP"] = "プフフッハハッ！コイツやっぱ言ってた通りの悪魔じゃん！",
            ["DialogueId"] = 51003818,
            ["GUID"] = "7FAEC5E4",
            ["NextDialogue"] = 51003819,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Talk03_Start",
                },
            },
        [51003819] = {
            ["Camera"] = "305.593262,-312.492188,101.247314,0.000134,-0.200008,138.792572,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来你是跑到外城找亲戚啊，真有意思！",
            ["ContentJP"] = "スラム街で親戚探しか？流石にウケるわ！",
            ["DialogueId"] = 51003819,
            ["GUID"] = "7FAEC60E",
            ["NextDialogue"] = 51003820,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Talk03_End",
                },
            },
        [51003820] = {
            ["Camera"] = "-196.32959,376.199219,82.648193,0.000135,0.0,-68.609573,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我不是！……不，不，我是……",
            ["ContentJP"] = "違う！……あ、いや、私、は……",
            ["DialogueId"] = 51003820,
            ["FinalCamera"] = "-158.777344,280.334961,89.867432,0.000135,0.0,-68.609573,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAEC638",
            ["NextDialogue"] = 51003821,
            ["SpeakNpcId"] = 700012,
            ["TalkActionId"] = {
                [1] = "700012:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51003821] = {
            ["Content"] = "女孩捂着耳朵逃开了。",
            ["ContentJP"] = "（少女は耳を押さえて逃げ出した）",
            ["DialogueId"] = 51003821,
            ["GUID"] = "7FAEC662",
            ["IsBlack"] = 1,
            ["Scripts"] = "SetLocation{ActorId{700012},TargetPoint{\"QuestPoint_FayeRun\"},Visibility{\"Hide\"}}",
            },
        [51003901] = {
            ["Content"] = "（女孩低着头站在角落里，心情看上去非常低落。）",
            ["ContentJP"] = "（少女は俯きながら隅に立っている。とても落ち込んでいるみたいだ）",
            ["DialogueId"] = 51003901,
            ["GUID"] = "7FAED382",
            ["NextOptions"] = {
                [1] = 510039011,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003902] = {
            ["Content"] = "（女孩微微转过了头，似乎并不想开口。）",
            ["ContentJP"] = "（少女はこちらに微かだけ目線を向けた。口は開きたくないようだ）",
            ["DialogueId"] = 51003902,
            ["GUID"] = "7FAED3AC",
            },
        [51003903] = {
            ["Content"] = "是你啊……",
            ["ContentJP"] = "あなたでしたか……",
            ["DialogueId"] = 51003903,
            ["GUID"] = "7FAED3D6",
            ["NextDialogue"] = 51003904,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_Start",
                },
            },
        [51003904] = {
            ["Content"] = "刚才那些是你的同学吗？",
            ["ContentJP"] = "さっきの子たちは……あなたの同級生？",
            ["DialogueId"] = 51003904,
            ["GUID"] = "7FAED400",
            ["NextDialogue"] = 51003905,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_End",
                },
            },
        [51003905] = {
            ["Content"] = "是的……对不起……对不起……我又搞砸了。",
            ["ContentJP"] = "はい……ごめんなさい……ごめんなさい……私また失敗を……",
            ["DialogueId"] = 51003905,
            ["GUID"] = "7FAED42A",
            ["NextDialogue"] = 51003906,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Sigh_Start",
                },
            },
        [51003906] = {
            ["Content"] = "他们是不是欺负你了？",
            ["ContentJP"] = "{性别:あいつらに虐められているの？|あいつらに虐められているのか？}",
            ["DialogueId"] = 51003906,
            ["GUID"] = "7FAED454",
            ["NextDialogue"] = 51003907,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Sigh_End",
                },
            },
        [51003907] = {
            ["Content"] = "不……都是我的错……",
            ["ContentJP"] = "いいえ……全部、私のせいなのです……",
            ["DialogueId"] = 51003907,
            ["GUID"] = "7FAED47E",
            ["NextDialogue"] = 51003908,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Disagree",
                },
            },
        [51003908] = {
            ["Content"] = "我什么事都做不好，妈妈和老师都说我脑袋笨笨的。",
            ["ContentJP"] = "何をやっても上手くできないのです。お母さんも先生も「お前は頭が悪い」と……",
            ["DialogueId"] = 51003908,
            ["GUID"] = "7FAED4A8",
            ["NextDialogue"] = 51003909,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Disagree",
                },
            },
        [51003909] = {
            ["Content"] = "我的同学很聪明，他们发现我之所以脑袋笨，是因为我是个卡戎，只是爸爸妈妈用魔法把角藏起来了。",
            ["ContentJP"] = "同級生のみんなは私よりも賢いから気づいたのかも。私の頭が悪い原因はカロン族で、お父さんとお母さんが魔法で角を隠したって。",
            ["DialogueId"] = 51003909,
            ["GUID"] = "7FAED4D2",
            ["NextDialogue"] = 51003910,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain01_Start",
                },
            },
        [51003910] = {
            ["Content"] = "都是我的错……我不该混在索拉之民里的……",
            ["ContentJP"] = "だから私が悪いだけ……私はソラの民に紛れ込むべきじゃなかったのです……",
            ["DialogueId"] = 51003910,
            ["GUID"] = "7FAED4FC",
            ["NextDialogue"] = 51003911,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain01_End",
                },
            },
        [51003911] = {
            ["Content"] = "（毫无疑问，这是最拙劣的谎言。它勾起了一些令你不快的回忆：在净界岛上，你和贝蕾曾经遭遇的恶意。）",
            ["ContentJP"] = "（考えるまでもなく愚劣で卑怯な嘘だ。あなたとベレがパーガトリー島で経験した悪意を想起するような）",
            ["DialogueId"] = 51003911,
            ["GUID"] = "7FAED526",
            ["NextDialogue"] = 51003912,
            },
        [51003912] = {
            ["Content"] = "（这些恶意或者因为你的弱小，或者因为你与众不同，又或者毫无来由——他们只是需要找什么倾泻，而那个倒霉蛋恰好是你。）",
            ["ContentJP"] = "（その悪意は自分の弱さに起因しているかもしれないし、変わった個性を持っているからなのかもしれないし、果てには何も理由がない時もある——彼らは何かを発散する対象が必要で、運悪くこの子が選ばれただけなのだ）",
            ["DialogueId"] = 51003912,
            ["GUID"] = "7FAED550",
            ["NextDialogue"] = 51003913,
            ["TalkActionId"] = {
                [1] = "700104:Disagree",
                },
            },
        [51003913] = {
            ["Content"] = "（只是这个女孩比曾经的你更加无助：甚至没有一个贝蕾妮卡愿意与她分摊这一切。）",
            ["ContentJP"] = "（ただ少女はかつてのあなたよりも無力である。少女には痛みをともに耐えてくれるベレニカのような人もいない）",
            ["DialogueId"] = 51003913,
            ["GUID"] = "7FAED57A",
            ["NextOptions"] = {
                [1] = 510039131,
                [2] = 510039132,
                [3] = 510039133,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51003914] = {
            ["Content"] = "不是我的错吗……？",
            ["ContentJP"] = "私のせいじゃ、ないのですか……？",
            ["DialogueId"] = 51003914,
            ["GUID"] = "7FAED5A4",
            ["NextDialogue"] = 51003915,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_Start",
                },
            },
        [51003915] = {
            ["Content"] = "伤害别人的家伙才有错。",
            ["ContentJP"] = "{性别:人を平気で傷つけられるヤツこそ悪いんだよ。|人を平気で傷つけられるヤツこそ悪いんだ。}",
            ["DialogueId"] = 51003915,
            ["GUID"] = "7FAED5CE",
            ["NextDialogue"] = 51003916,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Explain02_End",
                },
            },
        [51003916] = {
            ["Content"] = "你没有必要害怕，去反击吧。",
            ["ContentJP"] = "恐れる必要なんてない。やり返しにいこう。",
            ["DialogueId"] = 51003916,
            ["GUID"] = "7FAED5F8",
            ["NextDialogue"] = 51003922,
            ["SpeakNpcId"] = 100001,
            },
        [51003917] = {
            ["Content"] = "咦……？",
            ["ContentJP"] = "え……？",
            ["DialogueId"] = 51003917,
            ["GUID"] = "7FAED622",
            ["NextDialogue"] = 51003918,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Shock_Start",
                },
            },
        [51003918] = {
            ["Content"] = "既然他们说你是恶魔，那不如就干点恶魔该干的事吧。",
            ["ContentJP"] = "{性别:悪魔だって言うなら、悪魔らしくやってやればいいじゃない。|悪魔だって言うなら、悪魔らしくやってやればいいじゃないか。}",
            ["DialogueId"] = 51003918,
            ["GUID"] = "7FAED64C",
            ["NextDialogue"] = 51003922,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Shock_End",
                },
            },
        [51003919] = {
            ["Content"] = "咦……？",
            ["ContentJP"] = "え……？",
            ["DialogueId"] = 51003919,
            ["GUID"] = "7FAED676",
            ["NextDialogue"] = 51003920,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Shock_Start",
                },
            },
        [51003920] = {
            ["Content"] = "他们编了个谎话拿你取乐呢。不过……",
            ["ContentJP"] = "{性别:自分たちの享楽であなたに嘘をついているだけ。でも……|自分たちの享楽であなたに嘘をついているだけだ。でも……}",
            ["DialogueId"] = 51003920,
            ["GUID"] = "7FAED6A0",
            ["NextDialogue"] = 51003921,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700104:Shock_End",
                },
            },
        [51003921] = {
            ["Content"] = "既然他们说你是恶魔，那不如就干点恶魔该干的事吧。",
            ["ContentJP"] = "{性别:悪魔だって言うなら、悪魔らしくやってやればいいじゃない。|悪魔だって言うなら、悪魔らしくやってやればいいじゃないか。}",
            ["DialogueId"] = 51003921,
            ["GUID"] = "7FAED6CA",
            ["NextDialogue"] = 51003922,
            ["SpeakNpcId"] = 100001,
            },
        [51003922] = {
            ["Content"] = "走，我们回去找他们。",
            ["ContentJP"] = "さあ、一緒にあいつらを探しにいこう。",
            ["DialogueId"] = 51003922,
            ["GUID"] = "7FAED6F4",
            ["SpeakNpcId"] = 100001,
            },
        [51004001] = {
            ["Camera"] = "-54.027344,192.986816,154.662109,0.000025,-9.800139,-47.991821,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我该怎么做呢……？",
            ["ContentJP"] = "私、どうすればいいのですか……？",
            ["DialogueId"] = 51004001,
            ["GUID"] = "7FAEE3EA",
            ["LookAt"] = {
                [1] = "700104:n(100001)",
                [2] = "100001:n(700104)",
                },
            ["NextOptions"] = {
                [1] = 510040011,
                [2] = 510040012,
                },
            ["SpeakNpcId"] = 700104,
            },
        [51004002] = {
            ["Camera"] = "-54.027344,192.986816,154.662109,0.000025,-9.800139,-47.991821,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……好……那、那我努力一下。",
            ["ContentJP"] = "は、はい……分かりました……じゃあ、頑張ってみます。",
            ["DialogueId"] = 51004002,
            ["GUID"] = "7FAEE414",
            ["NextDialogue"] = 51004003,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Agree",
                },
            },
        [51004003] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "快看，那家伙回来了！",
            ["ContentJP"] = "おい見ろよ！ノコノコと帰ってきやがった！",
            ["DialogueId"] = 51004003,
            ["GUID"] = "7FAEE43E",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "700104:n(700104)",
                },
            ["NextDialogue"] = 51004004,
            ["SpeakNpcId"] = 700089,
            ["TurnTo"] = {
                [1] = "700088:n(100001)",
                [2] = "700089:n(100001)",
                [3] = "700090:n(100001)",
                },
            },
        [51004004] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这就和卡戎勾搭上了？不是一家人不进一家门！",
            ["ContentJP"] = "とうとうカロンとツルみ始めたのか？類は友を呼ぶって本当だったんだな！",
            ["DialogueId"] = 51004004,
            ["GUID"] = "7FAEE468",
            ["NextDialogue"] = 51004005,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            },
        [51004005] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我……",
            ["ContentJP"] = "私……",
            ["DialogueId"] = 51004005,
            ["GUID"] = "7FAEE492",
            ["NextDialogue"] = 51004006,
            ["SpeakNpcId"] = 700104,
            },
        [51004006] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（女孩努力地张嘴想要说什么，但似乎还没组织好语言，也许是需要一些小小的帮助。要对她的同学们说什么？）",
            ["ContentJP"] = "（少女は懸命に口を開いて何かを言おうとしているが、放つべき言葉が見つけられない様子だ。少し助けが必要かもしれない。彼女の同級生たちに何を言うべきだろうか？）",
            ["DialogueId"] = 51004006,
            ["GUID"] = "7FAEE4BC",
            ["NextOptions"] = {
                [1] = 510040061,
                [2] = 510040062,
                },
            },
        [51004007] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的……给我……给我……滚开！",
            ["ContentJP"] = "そ、そう……えっと……き、消えな……さい！",
            ["DialogueId"] = 51004007,
            ["GUID"] = "7FAEE4E6",
            ["NextDialogue"] = 51004008,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Agree",
                },
            },
        [51004008] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……不然我……我会和我的朋友一起把你们都送进地狱……！",
            ["ContentJP"] = "……さもなくば私が……私と友達とで……あなたたちを地獄に叩き落とす……！",
            ["DialogueId"] = 51004008,
            ["GUID"] = "7FAEE510",
            ["NextDialogue"] = 51004009,
            ["SpeakNpcId"] = 700104,
            },
        [51004009] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "或者，你们不是喜欢虫子、喜欢老鼠吗？就把你们丢进下水道好了……！",
            ["ContentJP"] = "そうよ、あなたたちって虫とネズミが好きだったよね？下水道に放り込んであげるわ……！あなたたちにはお似合いの場所よ……！",
            ["DialogueId"] = 51004009,
            ["GUID"] = "7FAEE53A",
            ["NextDialogue"] = 51004010,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Think_Start",
                },
            },
        [51004010] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不，不行，老鼠肯定也会嫌弃你们的！",
            ["ContentJP"] = "い、いえ、そんなのダメね！きっとネズミの方があなたたちをお断りするに違いないもの！",
            ["DialogueId"] = 51004010,
            ["GUID"] = "7FAEE564",
            ["NextDialogue"] = 51004011,
            ["SpeakNpcId"] = 700104,
            ["TalkActionId"] = {
                [1] = "700104:Think_End",
                },
            },
        [51004011] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（仿佛是打破了某种无形的束缚，女孩一反之前寡言少语的样子，滔滔不绝地骂了起来。）",
            ["ContentJP"] = "（少女は見えない楔から解き放たれたかのように、少ない言葉数しか話せなかったこれまでとは一変し、絶えず罵詈雑言を吐き出し始めた）",
            ["DialogueId"] = 51004011,
            ["GUID"] = "7FAEE58E",
            ["NextDialogue"] = 51004012,
            },
        [51004012] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "她居然骂人？！她疯了吧？",
            ["ContentJP"] = "こ、こいつが俺らに口答えを！？頭おかしくなったのか！？",
            ["DialogueId"] = 51004012,
            ["GUID"] = "7FAEE5B8",
            ["NextDialogue"] = 51004013,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700089:n(700104)",
                },
            },
        [51004013] = {
            ["Camera"] = "-415.09082,-71.93457,95.116699,0.000026,0.0,13.207663,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "气死我了！来人啊，给我教训教训她，让我满意了这些钱就都是你们的！",
            ["ContentJP"] = "ふざけんなよ！おい誰か！！こいつに身の程を教えてやってくれ！こっちの気が済んだら、この金あんたらに全部渡すからさ！",
            ["DialogueId"] = 51004013,
            ["GUID"] = "7FAEE5E2",
            ["SpeakNpcId"] = 700089,
            ["TalkActionId"] = {
                [1] = "700089:Angry01_Start",
                },
            },
        [51004101] = {
            ["Camera"] = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个白头发的，不好惹啊！",
            ["ContentJP"] = "この白髪、とんでもなくヤバいじゃねぇか！",
            ["DialogueId"] = 51004101,
            ["GUID"] = "7FAEF452",
            ["NextDialogue"] = 51004102,
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Sigh_Start",
                [2] = "700089:Shock_Start",
                },
            },
        [51004102] = {
            ["Camera"] = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂……情况好像不太妙啊！我们还是先回去吧！",
            ["ContentJP"] = "うぐ……たしかにヤバそうだ！早く逃げよう！",
            ["DialogueId"] = 51004102,
            ["GUID"] = "7FAEF47C",
            ["LookAt"] = {
                [1] = "700089:n(700088)",
                },
            ["NextDialogue"] = 51004103,
            ["SpeakNpcId"] = 700089,
            },
        [51004103] = {
            ["Camera"] = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等等。",
            ["ContentJP"] = "{性别:待ちなよ。|待てよ。}",
            ["DialogueId"] = 51004103,
            ["GUID"] = "7FAEF4A6",
            ["NextDialogue"] = 51004104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51004104] = {
            ["Camera"] = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "费伊已经和我这个恶魔签了一份协议，如果你们再找她的麻烦，我会在一分钟之内出现在你们面前。",
            ["ContentJP"] = "{性别:フェイはもう私という悪魔と契約を結んだ。あんたたちが危害を加えたりしたら、私は1分も経たず目の前に現れるから。忘れないでね。|フェイはもう僕という悪魔と契約を結んだ。あんたたちが危害を加えたりしたら、僕は1分も経たず目の前に現れるから。忘れるなよ。}",
            ["DialogueId"] = 51004104,
            ["GUID"] = "7FAEF4D0",
            ["NextDialogue"] = 51004105,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700088:Sigh_End",
                },
            },
        [51004105] = {
            ["Camera"] = "-199.681152,34.707031,99.213867,0.000074,-2.198085,-15.786639,20.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……你……哼！",
            ["ContentJP"] = "お……お前……くっ！",
            ["DialogueId"] = 51004105,
            ["GUID"] = "7FAEF4FA",
            ["SpeakNpcId"] = 700088,
            ["TalkActionId"] = {
                [1] = "700088:Angry01_Start",
                },
            },
        [51004106] = {
            ["Content"] = "学生们一溜烟逃走了。",
            ["ContentJP"] = "（学生たちは一目散に逃げていった）",
            ["DialogueId"] = 51004106,
            ["GUID"] = "7FAEF524",
            },
        [51004107] = {
            ["Content"] = "你看，他们的胆量不过如此。",
            ["ContentJP"] = "{性别:ほら、あいつらなんてこの程度だよ。|ほら、あいつらなんてこの程度さ。}",
            ["DialogueId"] = 51004107,
            ["GUID"] = "7FAEF54E",
            ["NextDialogue"] = 51004108,
            ["SpeakNpcId"] = 100001,
            },
        [51004108] = {
            ["Content"] = "……嗯！",
            ["ContentJP"] = "……はい！",
            ["DialogueId"] = 51004108,
            ["GUID"] = "7FAEF578",
            ["NextDialogue"] = 51004109,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004109] = {
            ["Content"] = "多亏了有你在……你抡起拳头的样子真的很威风呢！",
            ["ContentJP"] = "あなたのお陰です……あいつらを倒す姿、本当に格好よかった！",
            ["DialogueId"] = 51004109,
            ["GUID"] = "7FAEF5A2",
            ["NextOptions"] = {
                [1] = 510041091,
                [2] = 510041092,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004110] = {
            ["Content"] = "诶，是、是吗？我只是……把以前偷偷在心里想的话说出来了。",
            ["ContentJP"] = "え、そ、そうですかね？私はただ……密かに心の中で思ってたことを吐き出しただけで。",
            ["DialogueId"] = 51004110,
            ["GUID"] = "7FAEF5CC",
            ["NextDialogue"] = 51004111,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Shock_Start",
                },
            },
        [51004111] = {
            ["Content"] = "谢谢你，我长这么大，还是头一次心里这么畅快呢！",
            ["ContentJP"] = "ありがとうございます！こんなに爽快感を感じたのは、私、初めてです！",
            ["DialogueId"] = 51004111,
            ["GUID"] = "7FAEF5F6",
            ["NextDialogue"] = 51004112,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Shock_End",
                },
            },
        [51004112] = {
            ["Content"] = "不用谢，他们短时间应该不会来找你麻烦了，我送你回家吧。这是我的地址——如果他们再惹你，就来找我。",
            ["ContentJP"] = "{性别:どういたしまして。これでしばらくは手を出してこないはず。私の住所を教えておくから——あいつらがまた来た時には私を探してね。それじゃ、家まで送るよ。|どういたしまして。これでしばらくは手を出してこないはず。僕の住所を教えておくから——あいつらがまた来た時には僕を探してくれ。それじゃ、家まで送るよ。}",
            ["DialogueId"] = 51004112,
            ["GUID"] = "7FAEF620",
            ["NextDialogue"] = 51004113,
            ["SpeakNpcId"] = 100001,
            },
        [51004113] = {
            ["Content"] = "我不想回家……！",
            ["ContentJP"] = "いや！家になんて帰りたくない……！",
            ["DialogueId"] = 51004113,
            ["GUID"] = "7FAEF64A",
            ["NextDialogue"] = 51004114,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Disagree",
                },
            },
        [51004114] = {
            ["Content"] = "我是卡戎，我要和卡戎之民待在一起……",
            ["ContentJP"] = "私はカロンなのです。だからカロン族と一緒にいるの……",
            ["DialogueId"] = 51004114,
            ["GUID"] = "7FAEF674",
            ["NextOptions"] = {
                [1] = 510041141,
                },
            ["RestartTag"] = 51004114,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004115] = {
            ["Content"] = "（女孩固执地噘着嘴，并没有被你说服。）",
            ["ContentJP"] = "（少女は口を堅くつぐむ。あなたの説得に耳を貸さなかった）",
            ["DialogueId"] = 51004115,
            ["GUID"] = "7FAEF69E",
            },
        [51004116] = {
            ["Content"] = "还没看清他们吗？他们平日里对着你威风凛凛，但真的有人比他们拳头更硬的时候，他们就会落荒而逃。",
            ["ContentJP"] = "{性别:もうあいつらの程度は見たでしょ？威張り散らしていようが、いざ自分より強いヤツが来たら逃げるしかできない。|もうあいつらの程度は見ただろ？威張り散らしていようが、いざ自分より強いヤツが来たら逃げるしかできない。}",
            ["DialogueId"] = 51004116,
            ["GUID"] = "7FAEF6C8",
            ["NextDialogue"] = 51004117,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700105:Think_Start",
                },
            },
        [51004117] = {
            ["Content"] = "他们不像自己表现得那么强大。所以，他们嘴里说的自然也不是事实。费伊，你是如假包换的索拉之民，不要被他们蹩脚的谎言骗了。",
            ["ContentJP"] = "{性别:見掛け倒しの嘘つきなんだから、あいつらがペラペラ話していたことも嘘だらけ。フェイ、あなたは正真正銘のソラの民なの。下手な嘘に騙されちゃダメよ。|見掛け倒しの嘘つきなんだから、あいつらがペラペラ話していたことも嘘だらけ。フェイ、あなたは正真正銘のソラの民だよ。下手な嘘に騙されちゃダメだ。}",
            ["DialogueId"] = 51004117,
            ["GUID"] = "7FAEF6F2",
            ["NextDialogue"] = 51004118,
            ["SpeakNpcId"] = 100001,
            },
        [51004118] = {
            ["Content"] = "记住，永远不要因为别人的恶意质疑自己，责备自己……这是我的家人教会我的，我也把它教给你。",
            ["ContentJP"] = "{性别:他人の悪意で自分を疑ったり、自分を責めたりしてはいけない……私の家族が聞かせてくれた教訓。覚えておいてね。|他人の悪意で自分を疑ったり、自分を責めたりしてはいけない……僕の家族が聞かせてくれた教訓。覚えておいて。}",
            ["DialogueId"] = 51004118,
            ["GUID"] = "7FAEF71C",
            ["NextDialogue"] = 51004119,
            ["SpeakNpcId"] = 100001,
            },
        [51004119] = {
            ["Content"] = "（女孩略带困惑地眨了眨眼，似乎还不能完全理解你话语的含义，但是表情却有所缓和。）",
            ["ContentJP"] = "（少女は少し困惑しながら目をパチクリさせた。あなたの言葉の意味を完全には理解できていないようだが、表情は和らいだように見える）",
            ["DialogueId"] = 51004119,
            ["GUID"] = "7FAEF746",
            ["NextDialogue"] = 51004120,
            },
        [51004120] = {
            ["Content"] = "好吧……既然你这么说的话，我会努力试试看的！但在那之前，我还有最后一个小小的请求……",
            ["ContentJP"] = "分かりました……あなたの言うことですし、頑張って試してみます！でも最後にちょっとだけお願いが……",
            ["DialogueId"] = 51004120,
            ["GUID"] = "7FAEF770",
            ["NextDialogue"] = 51004121,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_End",
                },
            },
        [51004121] = {
            ["Content"] = "可以让我摸一下你的角吗？",
            ["ContentJP"] = "あなたの角、触ってもいいですか？",
            ["DialogueId"] = 51004121,
            ["GUID"] = "7FAEF79A",
            ["NextOptions"] = {
                [1] = 510041211,
                [2] = 510041212,
                },
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004122] = {
            ["Content"] = "谢谢！",
            ["ContentJP"] = "ありがとうございます！",
            ["DialogueId"] = 51004122,
            ["GUID"] = "7FAEF7C4",
            ["NextDialogue"] = 51004123,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_End",
                },
            },
        [51004123] = {
            ["Content"] = "（女孩小心翼翼地伸出纤瘦的手，摸了摸你头上的角。）",
            ["ContentJP"] = "（少女はか細い手を慎重に伸ばして、あなたの頭上の角を触る）",
            ["DialogueId"] = 51004123,
            ["GUID"] = "7FAEF7EE",
            ["NextDialogue"] = 51004126,
            },
        [51004124] = {
            ["Content"] = "好吧，那我不摸，就看一看……",
            ["ContentJP"] = "わかりました。でも触ったりしないので、見るだけでも……",
            ["DialogueId"] = 51004124,
            ["GUID"] = "7FAEF818",
            ["NextDialogue"] = 51004125,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_End",
                },
            },
        [51004125] = {
            ["Content"] = "（女孩小心翼翼地凑上来，仔细地打量着你头上的角。）",
            ["ContentJP"] = "（少女は慎重に近づき、あなたの頭上の角をじっくりと見る）",
            ["DialogueId"] = 51004125,
            ["GUID"] = "7FAEF842",
            ["NextDialogue"] = 51004126,
            },
        [51004126] = {
            ["Content"] = "原来真正的角，是这样的啊……",
            ["ContentJP"] = "本物のカロン族の角って、こんな感じなのですね……",
            ["DialogueId"] = 51004126,
            ["GUID"] = "7FAEF86C",
            ["NextDialogue"] = 51004127,
            ["SpeakNpcId"] = 700105,
            },
        [51004127] = {
            ["Content"] = "红色的，很精巧……还会反射阳光呢。确实比我的辫子要可爱多了。",
            ["ContentJP"] = "赤色でキラキラと細かくて……太陽でピカピカと光ってて……私のお下げよりもずっと可愛いです。",
            ["DialogueId"] = 51004127,
            ["GUID"] = "7FAEF896",
            ["NextOptions"] = {
                [1] = 510041271,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004128] = {
            ["Content"] = "你是第一个这么说的人。但它们现在都被弄乱了……我要重新梳好才行。",
            ["ContentJP"] = "そんな風に言ってくれた人はあなたが初めてなのです。今はグチャグチャになっちゃってるから……もう一度結び直さないと。",
            ["DialogueId"] = 51004128,
            ["GUID"] = "7FAEF8C0",
            ["NextDialogue"] = 51004129,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004129] = {
            ["Content"] = "（女孩从书包里找出一把梳子，认真地将头上的两条辫子重新梳好，然后将它们向上提起来，比划出角的样子。）",
            ["ContentJP"] = "（少女はかばんの中から櫛を取り出した。頭の2本のお下げを丁寧に梳き直すと、持ち上げて角のようにする）",
            ["DialogueId"] = 51004129,
            ["GUID"] = "7FAEF8EA",
            ["NextDialogue"] = 51004130,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004130] = {
            ["Content"] = "这样像不像恶魔角？",
            ["ContentJP"] = "これで悪魔の角のように見えますか？",
            ["DialogueId"] = 51004130,
            ["GUID"] = "7FAEF914",
            ["NextOptions"] = {
                [1] = 510041301,
                [2] = 510041302,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004131] = {
            ["Content"] = "嘿嘿。",
            ["ContentJP"] = "えへへ。",
            ["DialogueId"] = 51004131,
            ["GUID"] = "7FAEF93E",
            ["NextDialogue"] = 51004133,
            ["SpeakNpcId"] = 700105,
            },
        [51004132] = {
            ["Content"] = "哈哈，那也不错。",
            ["ContentJP"] = "あはは、それでも悪くありません。",
            ["DialogueId"] = 51004132,
            ["GUID"] = "7FAEF968",
            ["NextDialogue"] = 51004133,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004133] = {
            ["Content"] = "啊，我口袋里还有多的发圈呢，要不要给你也扎个小辫子？",
            ["ContentJP"] = "あ、またポケットに髪留めはたくさんあるので、あなたの髪もお下げにしてみませんか？",
            ["DialogueId"] = 51004133,
            ["GUID"] = "7FAEF992",
            ["NextOptions"] = {
                [1] = 510041331,
                [2] = 510041332,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004134] = {
            ["Content"] = "就扎一下让我看看嘛！",
            ["ContentJP"] = "ちょっとだけ！ちょっとだけですから！",
            ["DialogueId"] = 51004134,
            ["GUID"] = "7FAEF9BC",
            ["NextDialogue"] = 51004135,
            ["SpeakNpcId"] = 700105,
            },
        [51004135] = {
            ["Content"] = "（女孩不由分说地踮起脚尖，试图把你按到一个她能够得到的位置。看来，她已经精神多了。）",
            ["ContentJP"] = "（少女はあなたに近づいてきて、つま先立ちで手を伸ばす。彼女はもう元気になった様子だ）",
            ["DialogueId"] = 51004135,
            ["GUID"] = "7FAEF9E6",
            ["NextDialogue"] = 51004136,
            },
        [51004136] = {
            ["Content"] = "来，稍微蹲下一些……",
            ["ContentJP"] = "はい、ちょっとしゃがんでくださいね……",
            ["DialogueId"] = 51004136,
            ["GUID"] = "7FAEFA10",
            ["NextDialogue"] = 51004137,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004137] = {
            ["Content"] = "（你感到脑后的发丝被人轻轻地揪住了。女孩梳头的动作非常温柔，看来不用担心发际线受到伤害了。）",
            ["ContentJP"] = "（後ろ髪を軽く引っ張られる感触がした。少女の髪を結ぶ動きは生え際が傷つく心配もなさそうなぐらい、とても優しい）",
            ["DialogueId"] = 51004137,
            ["GUID"] = "7FAEFA3A",
            ["NextDialogue"] = 51004138,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004138] = {
            ["Content"] = "好了！哇，你扎辫子的样子好可爱！",
            ["ContentJP"] = "よし！わあ、お下げ姿も可愛いです！",
            ["DialogueId"] = 51004138,
            ["GUID"] = "7FAEFA64",
            ["NextDialogue"] = 51004139,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004139] = {
            ["Content"] = "可惜我没有带镜子……",
            ["ContentJP"] = "残念ですが今は鏡を持ってなくて……",
            ["DialogueId"] = 51004139,
            ["GUID"] = "7FAEFA8E",
            ["NextDialogue"] = 51004140,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_Start",
                },
            },
        [51004140] = {
            ["Content"] = "啊……我想到了！我可以画出来。",
            ["ContentJP"] = "あ……わかった！描いてみせたらいいのです！",
            ["DialogueId"] = 51004140,
            ["GUID"] = "7FAEFAB8",
            ["NextDialogue"] = 51004141,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Think_End",
                },
            },
        [51004141] = {
            ["Content"] = "（女孩打开书包，在笔记本上认真画着你的样子。）",
            ["ContentJP"] = "（少女はカバンを開けてノートを取り出し、あなたの姿を真剣に描き始める）",
            ["DialogueId"] = 51004141,
            ["GUID"] = "7FAEFAE2",
            ["NextDialogue"] = 51004142,
            },
        [51004142] = {
            ["Content"] = "对了，你叫什么名字呀？",
            ["ContentJP"] = "ところで、あなたのお名前は？",
            ["DialogueId"] = 51004142,
            ["GUID"] = "7FAEFB0C",
            ["NextOptions"] = {
                [1] = 510041421,
                },
            ["SpeakNpcId"] = 700105,
            ["bForbidSkipOptions"] = true,
            },
        [51004143] = {
            ["Content"] = "嗯！{nickname}，我会一直一直记住你的。给，这是我给你画的画像，再见！",
            ["ContentJP"] = "はい！{nickname}さん、これでさよならになりますが、これから先もずっとあなたのことは忘れません。どうぞ、あなたを描いた絵です！！",
            ["DialogueId"] = 51004143,
            ["GUID"] = "7FAEFB36",
            ["NextDialogue"] = 51004144,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Agree",
                },
            },
        [51004144] = {
            ["Content"] = "……太神秘了，这就是城里人的艺术吗……",
            ["ContentJP"] = "謎すぎる……これが都会人の芸術……？",
            ["DialogueId"] = 51004144,
            ["GUID"] = "7FAEFB60",
            ["NextDialogue"] = 51004145,
            ["SpeakNpcId"] = 100001,
            },
        [51004145] = {
            ["Content"] = "（女孩正准备离开，忽然又回过头，认真地看向你。）",
            ["ContentJP"] = "（そのままさよならして離れようとした少女だが、急に振り返ってあなたを真剣に見つめる）",
            ["DialogueId"] = 51004145,
            ["GUID"] = "7FAEFB8A",
            ["NextDialogue"] = 51004146,
            },
        [51004146] = {
            ["Content"] = "对了……刚才给你梳头的时候，我突然想到一件事。",
            ["ContentJP"] = "あの……さっき髪を結んでた時に、ふと思ったのですが……",
            ["DialogueId"] = 51004146,
            ["GUID"] = "7FAEFBB4",
            ["NextDialogue"] = 51004147,
            ["SpeakNpcId"] = 700105,
            },
        [51004147] = {
            ["Content"] = "他们一直都告诉我，卡戎是恶魔的孩子，是脑袋笨笨又一肚子坏水的，总是在做坏事的……",
            ["ContentJP"] = "いじめっ子たちはずっと「カロンは悪魔の子、野蛮で邪の塊で、常に悪いことばかり考えているんだ」って言ってましたけど……",
            ["DialogueId"] = 51004147,
            ["GUID"] = "7FAEFBDE",
            ["NextDialogue"] = 51004148,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_Start",
                },
            },
        [51004148] = {
            ["Content"] = "这些话……其实也不是真的吧？",
            ["ContentJP"] = "そんな話……本当なんかじゃないのですよね？",
            ["DialogueId"] = 51004148,
            ["GUID"] = "7FAEFC08",
            ["NextDialogue"] = 51004149,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain01_End",
                },
            },
        [51004149] = {
            ["Content"] = "那也是他们用来欺负你们的借口，对不对？",
            ["ContentJP"] = "あなたたちを虐めるための口実なだけ。そうですよね？",
            ["DialogueId"] = 51004149,
            ["GUID"] = "7FAEFC32",
            ["NextOptions"] = {
                [1] = 510041491,
                [2] = 510041492,
                },
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Confident_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004150] = {
            ["Content"] = "你们一定……承受了比我多得多的痛苦吧。",
            ["ContentJP"] = "あなたたちは……私よりもずっと、つらい苦しみを背負っているはず。",
            ["DialogueId"] = 51004150,
            ["GUID"] = "7FAEFC5C",
            ["NextDialogue"] = 51004151,
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Confident_End",
                },
            },
        [51004151] = {
            ["Content"] = "今后，如果有什么我能帮得上忙的事，请尽管说……不是因为我们是同类，而是因为我们是朋友。",
            ["ContentJP"] = "何かお手伝いできることがあれば遠慮なく私に相談してくださいね……同類だからじゃなくて、友達だから。",
            ["DialogueId"] = 51004151,
            ["GUID"] = "7FAEFC86",
            ["SpeakNpcId"] = 700105,
            ["TalkActionId"] = {
                [1] = "700105:Explain02_Start",
                },
            },
        [51004152] = {
            ["Content"] = "同学们还是不喜欢我，但现在我已经不怕他们了！这都是多亏了你！",
            ["ContentJP"] = "同級生たちはまだ私のことを悪く見てきますが、もう怖くなんてありません！全部あなたのおかげです！",
            ["DialogueId"] = 51004152,
            ["GUID"] = "7FAEFCB0",
            ["SpeakNpcId"] = 700105,
            },
        [51004201] = {
            ["Content"] = "啧，生面孔啊。",
            ["ContentJP"] = "チッ、知らねぇ顔だな。",
            ["DialogueId"] = 51004201,
            ["GUID"] = "7FAF04BA",
            ["NextDialogue"] = 51004202,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Talk03_Start",
                },
            },
        [51004202] = {
            ["Content"] = "（眼前的男人眯起眼，抿了抿嘴唇上锐利的裂口，吐出干燥的话语。）",
            ["ContentJP"] = "（眼前の男は目を細めて、唇のひび割れを舐めながら乾いた言葉を吐き出した）",
            ["DialogueId"] = 51004202,
            ["GUID"] = "7FAF04E4",
            ["NextDialogue"] = 51004203,
            },
        [51004203] = {
            ["Content"] = "说说吧，谁介绍你来的？",
            ["ContentJP"] = "言ってみろ、誰ん紹介だ？",
            ["DialogueId"] = 51004203,
            ["GUID"] = "7FAF050E",
            ["NextOptions"] = {
                [1] = 510042031,
                [2] = 510042032,
                [3] = 510042033,
                },
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004204] = {
            ["Content"] = "（一个新的问题，才是最好的回答。）",
            ["ContentJP"] = "（新しい質問こそ、最高の答えとなるだろう）",
            ["DialogueId"] = 51004204,
            ["GUID"] = "7FAF0538",
            ["NextDialogue"] = 51004207,
            },
        [51004205] = {
            ["Content"] = "（“介绍”？很明显，他是在等什么人。）",
            ["ContentJP"] = "（「紹介」？恐らく彼は誰かを待っているのだろう）",
            ["DialogueId"] = 51004205,
            ["GUID"] = "7FAF0562",
            ["NextDialogue"] = 51004207,
            },
        [51004206] = {
            ["Content"] = "（不知道他在问什么，但没人会拒绝这个回答。）",
            ["ContentJP"] = "（問いかけてきた理由は分からないが、この回答を拒否する者はいないだろう）",
            ["DialogueId"] = 51004206,
            ["GUID"] = "7FAF058C",
            ["NextDialogue"] = 51004207,
            },
        [51004207] = {
            ["Content"] = "（男人沉默了一阵，抬眼打量起你来，几乎能听见他抬头时脊椎疲惫地的异响。）",
            ["ContentJP"] = "（男はしばらく黙り込むと、目線を上げてあなたを見つめた。彼が頭を上げたとき、脊椎から軋む音が聞こえてきそうな……そんな気がした。）",
            ["DialogueId"] = 51004207,
            ["GUID"] = "7FAF05B6",
            ["NextDialogue"] = 51004208,
            },
        [51004208] = {
            ["Content"] = "碎嘴子。",
            ["ContentJP"] = "調子のいいガキめ。",
            ["DialogueId"] = 51004208,
            ["GUID"] = "7FAF05E0",
            ["NextDialogue"] = 51004209,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Disagree",
                },
            },
        [51004209] = {
            ["Content"] = "（他轻哼了一声，又似乎很满意你的回答。）",
            ["ContentJP"] = "(彼は軽く鼻を鳴らしたが、君の答えに満足したようだ。）",
            ["DialogueId"] = 51004209,
            ["GUID"] = "7FAF060A",
            ["NextDialogue"] = 51004210,
            },
        [51004210] = {
            ["Content"] = "不管是谁介绍你来的，反正也是为了我口袋里的货，对吧？",
            ["ContentJP"] = "まあ誰ん紹介だろうと構わねぇさ。俺ん懐のブツが目当てなんだろ？",
            ["DialogueId"] = 51004210,
            ["GUID"] = "7FAF0634",
            ["NextDialogue"] = 51004211,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Confident_Start",
                },
            },
        [51004211] = {
            ["Content"] = "（男人扯开衣领，黯淡的金属管自怀中闪过。）",
            ["ContentJP"] = "（男が襟を開くと、鈍く光る金属が一瞬見える。）",
            ["DialogueId"] = 51004211,
            ["GUID"] = "7FAF065E",
            ["NextDialogue"] = 51004212,
            ["TalkActionId"] = {
                [1] = "700096:Confident_End",
                },
            },
        [51004212] = {
            ["Content"] = "（他立刻收紧了衣领，警惕地望了望四周。）",
            ["ContentJP"] = "（彼はすぐに襟を閉じ、警戒しながら辺りを見回した）",
            ["DialogueId"] = 51004212,
            ["GUID"] = "7FAF0688",
            ["NextDialogue"] = 51004213,
            },
        [51004213] = {
            ["Content"] = "4号口径，双管单发，不论是卡戎人还是秽兽，在它面前都走不过两下。",
            ["ContentJP"] = "23mm口径、ダブルバレルの中折式だ。カロンだろうが<Default note=\"text:エジュウ\">穢獣</>だろうが、こいつにゃ敵わん。",
            ["DialogueId"] = 51004213,
            ["GUID"] = "7FAF06B2",
            ["NextDialogue"] = 51004214,
            ["SpeakNpcId"] = 700096,
            },
        [51004214] = {
            ["Content"] = "（男人撇了撇嘴，像在谈论农用杀虫剂的功效。）",
            ["ContentJP"] = "（男は農作業で使う殺虫剤の効果でも話すかのように、実利的な言葉をツラツラと並べた）",
            ["DialogueId"] = 51004214,
            ["GUID"] = "7FAF06DC",
            ["NextDialogue"] = 51004215,
            },
        [51004215] = {
            ["Content"] = "这回的货不要钱，只要你帮我办件事。",
            ["ContentJP"] = "今回のブツに金は要らねぇ。ちょいとひとつ使い走ってくれりゃぁな。",
            ["DialogueId"] = 51004215,
            ["GUID"] = "7FAF0706",
            ["NextOptions"] = {
                [1] = 510042151,
                [2] = 510042152,
                },
            ["SpeakNpcId"] = 700096,
            ["bForbidSkipOptions"] = true,
            },
        [51004216] = {
            ["Content"] = "哆嗦什么？你不就是冲着这玩意来的吗？",
            ["ContentJP"] = "ブルってんじゃねぇぞ？こいつを欲しがった癖によぉ？",
            ["DialogueId"] = 51004216,
            ["GUID"] = "7FAF0730",
            ["NextDialogue"] = 51004217,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Explain01_Start",
                },
            },
        [51004217] = {
            ["Content"] = "事儿办利索了，不仅东西归你，我再追补给你一笔。",
            ["ContentJP"] = "要領よく済ませりゃブツ以外に報酬も上乗せてやっからよ。",
            ["DialogueId"] = 51004217,
            ["GUID"] = "7FAF075A",
            ["NextOptions"] = {
                [1] = 510042171,
                [2] = 510042172,
                },
            ["RestartTag"] = 51004216,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004218] = {
            ["Content"] = "想快点，我等不了你太久。",
            ["ContentJP"] = "ほら急げ、腹くくるの悠長に待ちゃしねぇぞ俺は。",
            ["DialogueId"] = 51004218,
            ["GUID"] = "7FAF0784",
            ["SpeakNpcId"] = 700096,
            },
        [51004219] = {
            ["Content"] = "好吧，你要我做什么？",
            ["ContentJP"] = "わかった。{性别:僕|私}に何をして欲しい{性别:んだ|の}？",
            ["DialogueId"] = 51004219,
            ["GUID"] = "7FAF07AE",
            ["NextDialogue"] = 51004220,
            ["SpeakNpcId"] = 100001,
            },
        [51004220] = {
            ["Content"] = "爽快，一会儿我给你个地方，目标就是那地方除了女人之外的东西都清了。",
            ["ContentJP"] = "話が早ぇじゃねぇか。ターゲットは指定の場所の女以外を全部だ。場所は後で教えっからよ、根こそぎ殺ってくれや。",
            ["DialogueId"] = 51004220,
            ["GUID"] = "7FAF07D8",
            ["NextDialogue"] = 51004221,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Agree",
                },
            },
        [51004221] = {
            ["Content"] = "这……感情问题……？",
            ["ContentJP"] = "えーっと……痴情のもつれ……？",
            ["DialogueId"] = 51004221,
            ["GUID"] = "7FAF0802",
            ["NextDialogue"] = 51004222,
            ["SpeakNpcId"] = 100001,
            },
        [51004222] = {
            ["Content"] = "别多嘴。",
            ["ContentJP"] = "余計な詮索はすんじゃねえ。",
            ["DialogueId"] = 51004222,
            ["GUID"] = "7FAF082C",
            ["NextDialogue"] = 51004223,
            ["SpeakNpcId"] = 700096,
            ["TalkActionId"] = {
                [1] = "700096:Disagree",
                },
            },
        [51004223] = {
            ["Content"] = "(男人紧了紧衣领，抿住干瘪的嘴唇，不愿再吐出任何一个字。)",
            ["ContentJP"] = "（男は襟を締め、ガサついた唇を真一文字に引き結び、それ以上は何ひとつ語らなくなった）",
            ["DialogueId"] = 51004223,
            ["GUID"] = "7FAF0856",
            },
        [51004301] = {
            ["Content"] = "行啊，收了钱就走吧，我不希望在这附近见到你。",
            ["ContentJP"] = "上出来だ、金を受け取ってさっさと行け。この辺りで、もう二度とその面を見せるんじゃないよ。",
            ["DialogueId"] = 51004301,
            ["GUID"] = "7FAF1522",
            ["NextDialogue"] = 51004302,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Agree",
                },
            },
        [51004302] = {
            ["Content"] = "你是想找人清理附近的秽兽？就算不雇佣我，也会有人处理那些秽兽的。",
            ["ContentJP"] = "この周辺の<Default note=\"text:エジュウ\">穢獣</>とかをどうにかしたかっただけなの{性别:か|}？だったら私に頼まなくとも、誰かが対処してくれたと思うけど。",
            ["DialogueId"] = 51004302,
            ["GUID"] = "7FAF154C",
            ["NextDialogue"] = 51004303,
            ["SpeakNpcId"] = 100001,
            },
        [51004303] = {
            ["Content"] = "有人处理？谁？那群把卡戎人当狗的杂碎？",
            ["ContentJP"] = "んだと？対処するってそりゃぁ誰だよ？カロン族と犬畜生を混同してるあの脳腐れどもがか?",
            ["DialogueId"] = 51004303,
            ["GUID"] = "7FAF1576",
            ["NextDialogue"] = 51004304,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Angry01_Start",
                },
            },
        [51004304] = {
            ["Content"] = "你猜猜他们到时候打开门，发现这里住的是一个卡戎女人，他们会怎么办？",
            ["ContentJP"] = "ここに住んでんのがカロンの虚弱な女と知った時、あいつらが何をやらかすか分かんねぇのかお前は？",
            ["DialogueId"] = 51004304,
            ["GUID"] = "7FAF15A0",
            ["NextDialogue"] = 51004305,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Angry01_End",
                },
            },
        [51004305] = {
            ["Content"] = "（男人突然捂紧胸口，浑身战栗起来，像是伤口被扯痛一般。好一阵，他才止住颤抖，偏过头，吐出一口唾沫钉在地上。）",
            ["ContentJP"] = "（唐突に男は胸を押さえた。抉られた傷口の痛みを耐えるかのように全身を震わせている。しばらくしてから震えを止めると、地面にツバを吐き捨てた）",
            ["DialogueId"] = 51004305,
            ["GUID"] = "7FAF15CA",
            ["NextDialogue"] = 51004306,
            },
        [51004306] = {
            ["Content"] = "一个善良的卡戎女人，为了救一个重伤躺在路边的陌生人，砸伤了内城跑出来的烈犬。",
            ["ContentJP"] = "傷だらけでスっ転んでた他人を救うために、善良なカロンの女は内城区から猛り出てきた犬畜生を追っぱらった。",
            ["DialogueId"] = 51004306,
            ["GUID"] = "7FAF15F4",
            ["NextDialogue"] = 51004307,
            ["SpeakNpcId"] = 700101,
            },
        [51004307] = {
            ["Content"] = "就因为这点事，她被毒打一顿，拖出冰湖城的门，丢到这荒地里。",
            ["ContentJP"] = "それだけなのに彼女はこっ酷くぶん殴られてよ、アイスレイクの街から放り出されちまったんだ。この荒地にポイっとゴミみてぇにな。",
            ["DialogueId"] = 51004307,
            ["GUID"] = "7FAF161E",
            ["NextDialogue"] = 51004308,
            ["SpeakNpcId"] = 700101,
            },
        [51004308] = {
            ["Content"] = "这……也许你可以想办法帮她离开冰湖城，换个地方生活。",
            ["ContentJP"] = "{性别:そんな……私も彼女が別の場所で生活できるよう、手助けできるかも。|そんな……僕も彼女が別の場所で生活できるよう、手助けできるかも。}",
            ["DialogueId"] = 51004308,
            ["GUID"] = "7FAF1648",
            ["NextDialogue"] = 51004309,
            ["SpeakNpcId"] = 100001,
            },
        [51004309] = {
            ["Content"] = "……快了，快攒够了。",
            ["ContentJP"] = "……目前なんだ。もう少しで目標まで貯まる。",
            ["DialogueId"] = 51004309,
            ["GUID"] = "7FAF1672",
            ["NextDialogue"] = 51004310,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Agree",
                },
            },
        [51004310] = {
            ["Content"] = "（男人转过身，面向帐篷的方向，僵硬的嘴角罕见地被撬开了一瞬，露出类似笑容的表情。）",
            ["ContentJP"] = "（男は振り向いてテントの方に目を向けた。強張った口元を珍しく一瞬だけ解き、微笑んだかのような表情を見せた）",
            ["DialogueId"] = 51004310,
            ["GUID"] = "7FAF169C",
            ["LookAt"] = {
                [1] = "700101:n(700100)",
                },
            ["NextDialogue"] = 51004311,
            ["TurnTo"] = {
                [1] = "700101:n(700100)",
                },
            },
        [51004311] = {
            ["Content"] = "（你似乎听见了朽木舒展时发出的干燥异响。）",
            ["ContentJP"] = "（朽ち木が生命を帯びてメキメキと伸びるような、そんな時に響くような音が聞こえた気がした）",
            ["DialogueId"] = 51004311,
            ["GUID"] = "7FAF16C6",
            },
        [51004401] = {
            ["Content"] = "下水道里的什么是不会消失的？",
            ["ContentJP"] = "下水道で消えることのないものは？",
            ["DialogueId"] = 51004401,
            ["GUID"] = "7FAF258A",
            ["NextOptions"] = {
                [1] = 510044011,
                [2] = 510044012,
                [3] = 510044013,
                },
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["bForbidSkipOptions"] = true,
            },
        [51004402] = {
            ["Content"] = "进来吧。",
            ["ContentJP"] = "よし、来いよ",
            ["DialogueId"] = 51004402,
            ["GUID"] = "7FAF25B4",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51004403] = {
            ["Content"] = "这不是什么都不知道的蠢货该来的地方。",
            ["ContentJP"] = "ここは何も知らない馬鹿が来る場所じゃないんだ。",
            ["DialogueId"] = 51004403,
            ["GUID"] = "7FAF25DE",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51004501] = {
            ["Camera"] = "-234.128906,122.0,168.883789,0.0,-11.799739,-20.999071,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没有女人，只有秽兽，全清完了。还是说这光秃秃的地皮也要我给铲了？",
            ["ContentJP"] = "女性の姿はなかったよ。いたのは<Default note=\"text:エジュウ\">穢獣</>だけ。全部片付けたけど……まさか、何もない地面まできれいにしろってこと？",
            ["DialogueId"] = 51004501,
            ["FinalCamera"] = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAF35F2",
            ["LookAt"] = {
                [1] = "700101:n(100001)",
                [2] = "100001:n(700101)",
                },
            ["NextDialogue"] = 51004502,
            ["SpeakNpcId"] = 100001,
