            },
        [51004504] = {
            ["Camera"] = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "专业，这才是狩月人该有的样子。抱歉试探了一下你，做我们这行的，总得多留个心眼。",
            ["ContentJP"] = "……ふむ、それでいい。これが月狩り人ってやつだ。疑って悪かったね。こういう仕事をしてると、どうしても警戒心が抜けないものだよ。",
            ["DialogueId"] = 51004504,
            ["GUID"] = "7FAF3670",
            ["NextDialogue"] = 51004505,
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "700101:Agree",
                },
            },
        [51004505] = {
            ["Camera"] = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "去这张纸上的位置吧，和之前一样，除了女人之外的东西全清了。",
            ["ContentJP"] = "次はこの紙に書いてある場所だ。今度も同じように、女以外はすべて片付けな。",
            ["DialogueId"] = 51004505,
            ["GUID"] = "7FAF369A",
            ["SpeakNpcId"] = 700101,
            ["TalkActionId"] = {
                [1] = "700101:Give",
                },
            },
        [51004901] = {
            ["Content"] = "（街边一位拿着一叠纸的女人吸引了你的注意：你留意到纸上罗列着一些药剂。也许这个女人与<H>玛尔洁给的某个线索</>有关。）",
            ["DialogueId"] = 51004901,
            ["GUID"] = "7FAF7792",
            ["LookAt"] = {
                [1] = "700010:n(0)",
                },
            },
        [51004902] = {
            ["Content"] = "你决定向她展示玛尔洁曾交给你的某样线索。",
            ["ContentJP"] = "マギーからもらった手がかりを彼女に見せることにした。",
            ["DialogueId"] = 51004902,
            ["FinalDialogueId"] = 51004905,
            ["GUID"] = "7FAF77BC",
            ["NextOptions"] = {
                [1] = 510049021,
                [2] = 510049022,
                [3] = 510049023,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004903] = {
            ["Content"] = "（女人一言不发，只是用警惕的目光盯着你，摇了摇头。看来，这不是她遗落的东西。）",
            ["ContentJP"] = "（女性は何も言わず警戒の眼差しをあなたに向ける。そして首を横に振った。どうやらこれは彼女の落とし物じゃないようだ）",
            ["DialogueId"] = 51004903,
            ["GUID"] = "7FAF77E6",
            ["NextOptions"] = {
                [1] = 510049031,
                [2] = 510049032,
                },
            ["TalkActionId"] = {
                [1] = "700010:Disagree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004905] = {
            ["Content"] = "露娜……医生？这份药方是你写的吗。",
            ["ContentJP"] = "ルナ……先生？この処方箋ってあなたが書いたモノですよね？",
            ["DialogueId"] = 51004905,
            ["GUID"] = "7FAF783A",
            ["NextDialogue"] = 51004906,
            ["SpeakNpcId"] = 100001,
            },
        [51004906] = {
            ["Content"] = "（你将手中的药方翻到露娜面前，好让药方上那些危险的文字能被露娜看到。）",
            ["ContentJP"] = "（手に持っている処方箋をルナの前に差し出す。処方箋に書かれている過激な文字を彼女に見せつけた）",
            ["DialogueId"] = 51004906,
            ["GUID"] = "7FAF7864",
            ["NextDialogue"] = 51004907,
            },
        [51004907] = {
            ["Content"] = "“城外的秽兽吃我们的肉，城内的农场主剪我们的毛。猎犬们吃着白面包，卡戎羊儿嚼着地上的草。摸爬滚打、摇尾乞怜，只为博主人芳心一笑。”",
            ["ContentJP"] = "「お城の外の怪物は、僕らの肉を食べちゃう。お城のなかの怪物は、僕らの毛をむしっちゃう。猟犬はふかふかパンを食ってるけど、哀れな羊の僕たちは、地面の草を食むだけさ。腹出し尾を振り慈悲を乞い、主人の機嫌を取るだけさ」",
            ["DialogueId"] = 51004907,
            ["GUID"] = "7FAF788E",
            ["NextDialogue"] = 51004908,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            },
        [51004908] = {
            ["Content"] = "啊……哇哇我……",
            ["ContentJP"] = "あ……わ、わ、私……",
            ["DialogueId"] = 51004908,
            ["GUID"] = "7FAF78B8",
            ["NextDialogue"] = 51004909,
            ["SpeakNpcId"] = 700010,
            ["TalkActionId"] = {
                [1] = "700010:Shock_Start",
                },
            },
        [51004909] = {
            ["Content"] = "（露娜看后立马支支吾吾了起来，焦急地用两只手胡乱地在空中比划，无论是字迹还是反应，都证明了你找对了人。）",
            ["ContentJP"] = "（それを見た途端、ルナは言葉を濁した。両手を宙でヒラヒラさせて慌てふためく。筆跡から反応まで見るに、どうやら正しい持ち主を発見できたようだ）",
            ["DialogueId"] = 51004909,
            ["GUID"] = "7FAF78E2",
            ["NextOptions"] = {
                [1] = 510049091,
                [2] = 510049092,
                },
            ["TalkActionId"] = {
                [1] = "700010:Shock_Loop",
                },
            },
        [51004910] = {
            ["Content"] = "（露娜的情绪稍微平复了一些。）",
            ["ContentJP"] = "（ルナは少し落ち着いたようだ）",
            ["DialogueId"] = 51004910,
            ["GUID"] = "7FAF790C",
            ["NextDialogue"] = 51004912,
            ["TalkActionId"] = {
                [1] = "700010:Shock_End",
                },
            },
        [51004911] = {
            ["Content"] = "（她看起来更加焦急了。）",
            ["ContentJP"] = "（彼女の焦りが加速したように見える）",
            ["DialogueId"] = 51004911,
            ["GUID"] = "7FAF7936",
            ["NextDialogue"] = 51004912,
            ["TalkActionId"] = {
                [1] = "700010:Shock_End",
                },
            },
        [51004912] = {
            ["Content"] = "这张纸如果落在其他人手里，你会惹上不小的麻烦吧？",
            ["ContentJP"] = "この紙が他の人の手に渡ったら、大変な事態になり兼ねませんよ？",
            ["DialogueId"] = 51004912,
            ["GUID"] = "7FAF7960",
            ["NextDialogue"] = 51004913,
            ["SpeakNpcId"] = 100001,
            },
        [51004913] = {
            ["Content"] = "（露娜指了指喉咙上的疤痕，然后拿起一张空白的纸，奋笔疾书。）",
            ["ContentJP"] = "ルナは自分の喉元を指さすと、真っ白な紙を手に取り、必死にペンを走らせた。",
            ["DialogueId"] = 51004913,
            ["GUID"] = "7FAF798A",
            ["NextDialogue"] = 51004914,
            ["TalkActionId"] = {
                [1] = "700010:Explain02_Start",
                },
            },
        [51004914] = {
            ["Content"] = "“我曾是一个吟游诗人。几个仇恨卡戎的人绑架了我。他们嘲弄我，殴打我，割去我的头发，划破我的皮肤。”",
            ["ContentJP"] = "「私はかつて吟遊詩人でした。ある日、カロンを憎む者たちに捕まり、嘲られ、殴られ、髪を切られ、肌を裂かれたんです」",
            ["DialogueId"] = 51004914,
            ["GUID"] = "7FAF79B4",
            ["NextDialogue"] = 510049141,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Explain02_End",
                },
            },
        [51004915] = {
            ["Content"] = "那你为什么还在写？",
            ["ContentJP"] = "……なのに、どうして書き続けてるの？",
            ["DialogueId"] = 51004915,
            ["GUID"] = "7FAF79DE",
            ["NextDialogue"] = 51004916,
            ["SpeakNpcId"] = 100001,
            },
        [51004916] = {
            ["Content"] = "（露娜低头在纸上写着什么。）",
            ["ContentJP"] = "（ルナは頭を下げて紙に何かを書く）",
            ["DialogueId"] = 51004916,
            ["GUID"] = "7FAF7A08",
            ["NextDialogue"] = 51004917,
            },
        [51004917] = {
            ["Content"] = "“憋在心里太难受。”",
            ["ContentJP"] = "「胸に抱えたままでは、あまりにも辛くて」",
            ["DialogueId"] = 51004917,
            ["GUID"] = "7FAF7A32",
            ["NextOptions"] = {
                [1] = 510049171,
                [2] = 510049172,
                [3] = 510049173,
                },
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Disagree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004918] = {
            ["Content"] = "“是啊。什么都改变不了，我甚至写了都不敢给别人看，但我还是忍不住想写点什么。”",
            ["ContentJP"] = "「そうですね。何も変わりません。書いた物を人に見せる勇気さえ出せません。しかしそれでも、書きたくてたまらなくなるのです」",
            ["DialogueId"] = 51004918,
            ["GUID"] = "7FAF7A5C",
            ["NextDialogue"] = 51004919,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            },
        [51004919] = {
            ["Content"] = "“我已经唱不了歌了，我怕如果有一天我什么也不写了，我就会弄丢最后一件珍贵的东西，那时我就真的什么也没有了。”",
            ["ContentJP"] = "「私はもう歌えなくなりました。それで書くことさえもやめたらどうなるのでしょうか？最後の大切なモノまで失くしたくないのです。失くせば私は何者でもなく、何物もなくなってしまうのです」",
            ["DialogueId"] = 51004919,
            ["GUID"] = "7FAF7A86",
            ["NextDialogue"] = 51004920,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            },
        [51004920] = {
            ["Content"] = "不开心的话就多找点实在的事做吧，会让自己舒服些。还有，你写可以，下次记得收好吧，别再不小心弄丢了。",
            ["ContentJP"] = "もっと実りあることで不満を解消した方がいいと思いますよ。それに次からは書いた物を厳重に仕舞いましょう。うっかり失くさないように。",
            ["DialogueId"] = 51004920,
            ["GUID"] = "7FAF7AB0",
            ["NextDialogue"] = 51004921,
            ["SpeakNpcId"] = 100001,
            },
        [51004921] = {
            ["Content"] = "（女人思索了良久，点了点头。）",
            ["ContentJP"] = "（女性はしばらく考えてから、うなずいた）",
            ["DialogueId"] = 51004921,
            ["GUID"] = "7FAF7ADA",
            ["NextDialogue"] = 51004922,
            ["TalkActionId"] = {
                [1] = "700010:Agree",
                },
            },
        [51004922] = {
            ["Content"] = "“谢谢你还给我，好心人。这是给你的报酬。”",
            ["ContentJP"] = "「親切な方。返してくれてありがとうございます。これはあなたへのお礼の品です」",
            ["DialogueId"] = 51004922,
            ["GUID"] = "7FAF7B04",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Give",
                },
            },
        [51004923] = {
            ["Content"] = "“你谬赞了，我只是一个只敢在纸上发牢骚的胆小鬼，我连把这些东西给其他人看的勇气都没有。”",
            ["ContentJP"] = "「とんでもありません。私は紙に文句を書き連ねているだけの臆病者です。それを人に見せる勇気さえ出せないのですから」",
            ["DialogueId"] = 51004923,
            ["GUID"] = "7FAF7B2E",
            ["NextDialogue"] = 51004924,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Disagree",
                },
            },
        [51004924] = {
            ["Content"] = "你肯写真心话，已经比大多数人勇敢了。只是下次收好吧，别再不小心弄丢了。",
            ["ContentJP"] = "書き記すだけでも本音に向き合えている時点で勇敢ですよ。ただ次からは書いた物を厳重に仕舞いましょう。うっかり失くさないように。",
            ["DialogueId"] = 51004924,
            ["GUID"] = "7FAF7B58",
            ["NextDialogue"] = 51004925,
            ["SpeakNpcId"] = 100001,
            },
        [51004925] = {
            ["Content"] = "（女人嘴唇勾出一丝微笑，她点点头，你看到她双眼噙着泪花。）",
            ["ContentJP"] = "（女性の口元に笑みが浮かんだ。うなずく彼女の眼には涙が溢れている）",
            ["DialogueId"] = 51004925,
            ["GUID"] = "7FAF7B82",
            ["NextDialogue"] = 51004926,
            },
        [51004926] = {
            ["Content"] = "“谢谢你还给我，好心人。这是给你的报酬。”",
            ["ContentJP"] = "「親切な方。返してくれてありがとうございます。これはあなたへのお礼の品です」",
            ["DialogueId"] = 51004926,
            ["GUID"] = "7FAF7BAC",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Give",
                },
            },
        [51004927] = {
            ["Content"] = "（女人发出一声嘶哑的哀鸣，痛苦地将脸埋在手掌间。良久，她才颤抖着打开手袋，把它交给了你。）",
            ["ContentJP"] = "（女性は掠れたような悲鳴をあげて、苦しそうに手のひらで顔を隠す。しばらくすると震えながらハンドバッグを開き、中から何かを取り出した）",
            ["DialogueId"] = 51004927,
            ["GUID"] = "7FAF7BD6",
            ["NextDialogue"] = 51004928,
            ["TalkActionId"] = {
                [1] = "700010:Sigh_Start",
                },
            },
        [51004928] = {
            ["Content"] = "“这些全都送给你，求你把那张纸还给我吧。”",
            ["ContentJP"] = "「これを全てお渡しします。どうかその紙を返してください」",
            ["DialogueId"] = 51004928,
            ["GUID"] = "7FAF7C00",
            ["NextDialogue"] = 51004929,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            ["TalkActionId"] = {
                [1] = "700010:Give",
                },
            },
        [51004929] = {
            ["Content"] = "（你满意地点点头——要是这张纸落在别人手里，她损失的可不只是这些了。你为她免去了大麻烦，这是你应得的报酬。）",
            ["ContentJP"] = "（あなたは満足気にうなずいた——もし紙が他人の手に落ちた場合、彼女が失う物はこんな程度じゃ済まない。あなたは大きなトラブルに巻き込まれる不運から彼女を救ったのだ。ならばこれは当然得られるべき報酬である）",
            ["DialogueId"] = 51004929,
            ["GUID"] = "7FAF7C2A",
            },
        [51004930] = {
            ["Content"] = "呜呜……哇呀……",
            ["ContentJP"] = "あうぅ……ううぅ……",
            ["DialogueId"] = 51004930,
            ["GUID"] = "7FAF7C54",
            ["NextDialogue"] = 51004931,
            ["SpeakNpcId"] = 700010,
            },
        [51004931] = {
            ["Content"] = "（露娜一如既往吐露着无人能听懂的字句，她看向你的目光有些躲闪。）",
            ["ContentJP"] = "（ルナは普段通り、あなたへ向ける視線を少し逸らしながら、理解しがたい言葉を呟いている）",
            ["DialogueId"] = 51004931,
            ["GUID"] = "7FAF7C7E",
            },
        [51004935] = {
            ["Camera"] = "-843.349854,-34.817383,370.464844,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
            ["Content"] = "不想活了是不是？交出来！",
            ["ContentJP"] = "死にたいのか？さっさと出せ！",
            ["DialogueId"] = 51004935,
            ["FinalCamera"] = "-635.633789,-118.727051,302.828857,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
            ["GUID"] = "7FAF7C7F",
            ["NextDialogue"] = 51004936,
            ["SpeakNpcId"] = 700225,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51004936] = {
            ["Content"] = "让老子看看你又在写什么好东西——",
            ["ContentJP"] = "何を書いたか見せてもらおう――",
            ["DialogueId"] = 51004936,
            ["GUID"] = "7FAF7C80",
            ["NextDialogue"] = 51004937,
            ["SpeakNpcId"] = 700226,
            },
        [51004937] = {
            ["Content"] = "上次是喉咙不听使唤，这次是什么？眼？手爪子？",
            ["ContentJP"] = "この前は声を潰したが……今度は目か？それとも手か？",
            ["DialogueId"] = 51004937,
            ["GUID"] = "7FAF7C81",
            ["NextDialogue"] = 51004938,
            ["SpeakNpcId"] = 700225,
            },
        [51004938] = {
            ["Content"] = "啊……啊啊！",
            ["ContentJP"] = "ぎゃっ、ああ……！",
            ["DialogueId"] = 51004938,
            ["GUID"] = "7FAF7C82",
            ["NextDialogue"] = 51004939,
            ["SpeakNpcId"] = 700010,
            },
        [51004939] = {
            ["Content"] = "（被恶徒包围的女人慌忙捡着地上的纸张，紧咬着下嘴唇，脸色苍白，眼神恐惧。你不清楚他们的关系，但你知道女人正处于危险之中。）",
            ["ContentJP"] = "ならず者たちに囲まれた女性が、地面に散らばった紙を必死に拾い集めている。唇をかみ、青ざめた顔に恐怖が滲む──事情はわからないが、彼女が危険な状況にあるのは明らかだった。",
            ["DialogueId"] = 51004939,
            ["GUID"] = "7FAF7C83",
            },
        [51004941] = {
            ["Content"] = "（露娜慌忙向你鞠了鞠躬，似是感谢，又接着焦急地开始收拾地上散落的纸。）",
            ["ContentJP"] = "ルナはあなたに小さく頭を下げると、焦りながらも紙をかき集めはじめた。",
            ["DialogueId"] = 51004941,
            ["GUID"] = "7FAF7C84",
            ["NextDialogue"] = 51004942,
            },
        [51004942] = {
            ["Content"] = "你还好吧？这些纸是什么？",
            ["ContentJP"] = "大丈夫？この紙……何か大事なものなの？",
            ["DialogueId"] = 51004942,
            ["GUID"] = "7FAF7C85",
            ["NextDialogue"] = 51004943,
            ["SpeakNpcId"] = 100001,
            },
        [51004943] = {
            ["Content"] = "啊……呜呜！",
            ["ContentJP"] = "あ、あぅ……！",
            ["DialogueId"] = 51004943,
            ["GUID"] = "7FAF7C86",
            ["NextDialogue"] = 51004944,
            ["SpeakNpcId"] = 700010,
            },
        [51004944] = {
            ["Content"] = "（你注意到，那些纸上写着“药方”……也许这个女人与<H>玛尔洁给的某个线索</>有关？）",
            ["ContentJP"] = "ふと目に留まった紙には「処方箋」と書かれていた。──もしかすると、彼女は<H>マギーから聞いた手がかり</>に関わる人物かもしれない。",
            ["DialogueId"] = 51004944,
            ["GUID"] = "7FAF7C87",
            ["NextOptions"] = {
                [1] = 510049011,
                [2] = 510049012,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51004945] = {
            ["Content"] = "唔……唔唔。",
            ["ContentJP"] = "ん……んん……",
            ["DialogueId"] = 51004945,
            ["GUID"] = "7FAF7C88",
            ["NextDialogue"] = 51004946,
            ["SpeakNpcId"] = 700010,
            },
        [51004946] = {
            ["Content"] = "（女人面带微笑，似是在表达谢意。）",
            ["ContentJP"] = "女性はかすかに笑みを浮かべた。どうやら感謝の気持ちを伝えようとしているようだ。",
            ["DialogueId"] = 51004946,
            ["GUID"] = "7FAF7C89",
            ["NextDialogue"] = 51004947,
            ["SpeakNpcId"] = 700010,
            },
        [51004947] = {
            ["Content"] = "我曾经认识一名医生，虽然他现在不在冰湖城了，但我可以尝试去他曾经的住所帮你找找有没有合适的药方。",
            ["ContentJP"] = "知り合いに医者がいるんだ。今はアイスレイク城にはいないけど……彼の家に行けば、何か役立つ処方箋が見つかるかもしれない。",
            ["DialogueId"] = 51004947,
            ["GUID"] = "7FAF7C8A",
            ["NextDialogue"] = 51004948,
            ["SpeakNpcId"] = 100001,
            },
        [51004948] = {
            ["Content"] = "呜……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51004948,
            ["GUID"] = "7FAF7C8B",
            ["NextDialogue"] = 51004949,
            ["SpeakNpcId"] = 700010,
            },
        [51004949] = {
            ["Content"] = "（露娜低下头，她似乎知道自己的嗓子铁定是没救的。但她再次抬头的时候眼中却闪了闪希望的光芒，好像在说：“万一呢？”）",
            ["ContentJP"] = "ルナはうつむいた。自分の喉がもう元に戻らないことを、きっと心のどこかで悟っている。それでも、彼女の目にはかすかな希望の光が宿っていた──まるで「わずかな望み」に賭けるかのように。",
            ["DialogueId"] = 51004949,
            ["GUID"] = "7FAF7C8C",
            },
        [51004950] = {
            ["Content"] = "呜……哇啊！",
            ["ContentJP"] = "うう…あ…！",
            ["DialogueId"] = 51004950,
            ["GUID"] = "7FAF7C8D",
            ["NextDialogue"] = 51004951,
            ["SpeakNpcId"] = 700010,
            },
        [51004951] = {
            ["Content"] = "（女人警惕地看着你，拼命摇着头，似乎是在说“我真的没有钱了”。）",
            ["ContentJP"] = "ルナは警戒心を隠そうともせず、あなたをじっと見つめ、必死に首を振った。「本当にお金は持っていない」という訴えがひしひしと伝わってくる。",
            ["DialogueId"] = 51004951,
            ["GUID"] = "7FAF7C8E",
            ["NextDialogue"] = 51004952,
            ["SpeakNpcId"] = 700010,
            },
        [51004952] = {
            ["Content"] = "唉，别那么紧张，这次我是来帮忙的。就那么白拿你的也不是我的作风。",
            ["ContentJP"] = "そんなに怖がらなくても大丈夫。今回はちゃんと手伝いに来たんだ。……さすがに、何ももらわずに助けるのも気が引けるけどね。",
            ["DialogueId"] = 51004952,
            ["GUID"] = "7FAF7C8F",
            ["NextDialogue"] = 51004953,
            ["SpeakNpcId"] = 100001,
            },
        [51004953] = {
            ["Content"] = "我曾经认识一名医生，虽然他现在不在冰湖城了，但我可以尝试去他曾经的住所帮你找找有没有合适的药方。",
            ["ContentJP"] = "知り合いに医者がいるんだ。今はアイスレイク城にはいないけど……彼の家に行けば、何か役立つ処方箋が見つかるかもしれない。",
            ["DialogueId"] = 51004953,
            ["GUID"] = "7FAF7C90",
            ["NextDialogue"] = 51004954,
            ["SpeakNpcId"] = 100001,
            },
        [51004954] = {
            ["Content"] = "（露娜的脸上写满了疑惑——现在的她并不是那么信任你。）",
            ["ContentJP"] = "ルナの顔にはまだ不信の色が濃く残っていた──今はあなたを完全には信じきれていないようだ。",
            ["DialogueId"] = 51004954,
            ["GUID"] = "7FAF7C91",
            },
        [51004955] = {
            ["Content"] = "（某书架上）",
            ["ContentJP"] = "ある本棚",
            ["DialogueId"] = 51004955,
            ["GUID"] = "7FAF7C92",
            },
        [51004956] = {
            ["Content"] = "（冰湖城总会有些古怪的感冒像大风一样刮过，虽然来得快去得也快，但孩子们生病时总归是很难受的。————感冒速效药）",
            ["ContentJP"] = "アイスレイク城には奇妙な流行り病があり、\
子どもたちが苦しむことも少なくない。\
──風邪速効薬",
            ["DialogueId"] = 51004956,
            ["Duration"] = 4,
            ["GUID"] = "7FAF7C93",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51004957,
            },
        [51004957] = {
            ["Content"] = "感觉不是这个。",
            ["ContentJP"] = "……これは違う気がする。",
            ["DialogueId"] = 51004957,
            ["Duration"] = 3,
            ["GUID"] = "7FAF7C94",
            ["SpeakNpcId"] = 100001,
            },
        [51004958] = {
            ["Content"] = "（某书架上）",
            ["ContentJP"] = "ある本棚",
            ["DialogueId"] = 51004958,
            ["GUID"] = "7FAF7C95",
            },
        [51004959] = {
            ["Content"] = "（古里古怪的药方，本是某种抗秽蚀药物的失败品。后续测试发现对一些疑难杂症却有奇效。）",
            ["ContentJP"] = "失敗作とされた抗穢蝕薬。だが、後に一部の難病症状に対して効果が見られた。",
            ["DialogueId"] = 51004959,
            ["Duration"] = 4,
            ["GUID"] = "7FAF7C96",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51004960,
            },
        [51004960] = {
            ["Content"] = "感觉不是这个。",
            ["ContentJP"] = "……これは違う気がする。",
            ["DialogueId"] = 51004960,
            ["Duration"] = 3,
            ["GUID"] = "7FAF7C97",
            ["SpeakNpcId"] = 100001,
            },
        [51004961] = {
            ["Content"] = "（地上）",
            ["ContentJP"] = "地面",
            ["DialogueId"] = 51004961,
            ["GUID"] = "7FAF7C98",
            },
        [51004962] = {
            ["Content"] = "（有些人或因饥饿误食过莲草，若中毒不深，这种药剂可以中和他们体内的毒素——莲草解毒剂）",
            ["ContentJP"] = "誤って蓮草を摂取した場合、\
軽度の中毒症状ならこれで解毒できる──蓮草解毒薬",
            ["DialogueId"] = 51004962,
            ["Duration"] = 5,
            ["GUID"] = "7FAF7C99",
            ["IsBlack"] = 1,
            },
        [51004963] = {
            ["Content"] = "怎么掉在地上了，这个说不定用得上！",
            ["ContentJP"] = "これ……落ちてたけど、使えそう！",
            ["DialogueId"] = 51004963,
            ["Duration"] = 4,
            ["GUID"] = "7FAF7C9A",
            ["SpeakNpcId"] = 100001,
            },
        [51004964] = {
            ["Content"] = "（获得或许能治疗嗓子的药方）",
            ["ContentJP"] = "喉の治療に使えそうな処方箋を発見",
            ["DialogueId"] = 51004964,
            ["Duration"] = 3,
            ["GUID"] = "7FAF7C9B",
            },
        [51004965] = {
            ["Content"] = "如果有一天你的嗓子真的治好了，你打算唱些什么呢？",
            ["ContentJP"] = "もし、声が戻ったら……何を詠いたい？",
            ["DialogueId"] = 51004965,
            ["GUID"] = "7FAF7C9C",
            ["NextDialogue"] = 51004966,
            ["SpeakNpcId"] = 100001,
            },
        [51004966] = {
            ["Content"] = "（露娜低下头，似是陷入了长长的思索。）",
            ["ContentJP"] = "ルナはうつむき、長い時間、静かに考え込んでいた。",
            ["DialogueId"] = 51004966,
            ["GUID"] = "7FAF7C9D",
            ["NextDialogue"] = 51004967,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            },
        [51004967] = {
            ["Content"] = "“唱我心中所想，即使以喉咙为代价。”",
            ["ContentJP"] = "「心の想いを打ち明けるわ──たとえ声を代償にしても」",
            ["DialogueId"] = 51004967,
            ["GUID"] = "7FAF7C9E",
            ["NextDialogue"] = 51004968,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Ziji",
            },
        [51004968] = {
            ["Content"] = "你意识到手中的这份治疗嗓子的药方，一旦真的有效，反而会让这位吟游诗人陷入更加危险的境地。",
            ["ContentJP"] = "あなたは気づいた。この薬が本当に効果を発揮したなら、彼女はさらに過酷な道を選ぶかもしれないことを。",
            ["DialogueId"] = 51004968,
            ["GUID"] = "7FAF7C9F",
            ["NextOptions"] = {
                [1] = 51004969,
                [2] = 51004970,
                },
            },
        [51004969] = {
            ["Content"] = "将药方递给露娜。",
            ["ContentJP"] = "処方箋をルナに手渡す。",
            ["DialogueId"] = 51004969,
            ["GUID"] = "7FAF7CA0",
            ["NextDialogue"] = 51004972,
            },
        [51004970] = {
            ["Content"] = "隐瞒药方的事。",
            ["ContentJP"] = "処方箋を隠す",
            ["DialogueId"] = 51004970,
            ["GUID"] = "7FAF7CA1",
            ["NextDialogue"] = 51004979,
            },
        [51004971] = {
            ["Content"] = "分支1",
            ["ContentJP"] = "サブ1",
            ["DialogueId"] = 51004971,
            ["GUID"] = "7FAF7CA2",
            },
        [51004972] = {
            ["Content"] = "这个药方，是我熟悉的那位医生用来治疗莲草中毒的。你拿去试一试，说不定能治好你的嗓子。",
            ["ContentJP"] = "この薬は……昔、知り合いの医者が作った蓮草中毒の治療薬なんだ。試してみない？",
            ["DialogueId"] = 51004972,
            ["GUID"] = "7FAF7CA3",
            ["NextDialogue"] = 51004973,
            ["SpeakNpcId"] = 100001,
            },
        [51004973] = {
            ["Content"] = "露娜的手有些颤抖，不敢相信般地接过了这张皱巴巴的纸。眼角微微有些湿润，拼命行礼表示感谢。",
            ["ContentJP"] = "ルナは信じられないように紙を受け取り、目に涙を浮かべながら必死に頭を下げた。",
            ["DialogueId"] = 51004973,
            ["GUID"] = "7FAF7CA4",
            ["NextDialogue"] = 51004974,
            },
        [51004974] = {
            ["Content"] = "（失去或许能治疗嗓子的药方）",
            ["ContentJP"] = "解毒できる処方箋を失う",
            ["DialogueId"] = 51004974,
            ["GUID"] = "7FAF7CA5",
            ["NextDialogue"] = 51004975,
            },
        [51004975] = {
            ["Content"] = "（你并不清楚将药方给她究竟是不是一件好事，药方究竟能不能起到作用也是个未知数。）",
            ["ContentJP"] = "それが本当に正しい選択だったかはわからない。そもそも処方箋が本当に効くのかすら不明だ。",
            ["DialogueId"] = 51004975,
            ["GUID"] = "7FAF7CA6",
            ["NextDialogue"] = 51004976,
            },
        [51004976] = {
            ["Content"] = "（一切都是这位吟游诗人自己的选择。你这样告诉自己。）",
            ["ContentJP"] = "ただ、これは彼女が自分で選んだ道だ。あなたはそう自分に言い聞かせた。",
            ["DialogueId"] = 51004976,
            ["GUID"] = "7FAF7CA7",
            },
        [51004977] = {
            ["Content"] = "任务完成，失去解毒剂药方，获得奖励",
            ["ContentJP"] = "クエスト完了、報酬獲得（ルナ個人ストーリーアンロック）",
            ["DialogueId"] = 51004977,
            ["GUID"] = "7FAF7CA8",
            },
        [51004978] = {
            ["Content"] = "分支2",
            ["ContentJP"] = "サブ2",
            ["DialogueId"] = 51004978,
            ["GUID"] = "7FAF7CA9",
            },
        [51004979] = {
            ["Content"] = "我的那位旧识医生已经不在冰湖城了，我去了他过去的住所，但很可惜那里已经被打扫干净了。",
            ["ContentJP"] = "ごめんね。知り合いの医者の家には、もう何も残ってなかった。",
            ["DialogueId"] = 51004979,
            ["GUID"] = "7FAF7CAA",
            ["NextDialogue"] = 51004980,
            ["SpeakNpcId"] = 100001,
            },
        [51004980] = {
            ["Content"] = "对不起，让你空欢喜一场。",
            ["ContentJP"] = "期待させちゃって、本当にごめん。",
            ["DialogueId"] = 51004980,
            ["GUID"] = "7FAF7CAB",
            ["NextDialogue"] = 51004981,
            ["SpeakNpcId"] = 100001,
            },
        [51004981] = {
            ["Content"] = "（露娜微笑着拍了拍你的肩，仿佛在说“没关系，谢谢你。”）",
            ["ContentJP"] = "ルナはかすかに微笑み、あなたの肩をぽんと叩いた。「気にしないで」と伝えたかったのだろう。",
            ["DialogueId"] = 51004981,
            ["GUID"] = "7FAF7CAC",
            ["NextDialogue"] = 51004982,
            },
        [51004982] = {
            ["Content"] = "（她并不清楚你心中的五味杂陈，不知道你只是不希望让她把自己摆在险境里——尽管这只是一种渺茫的可能性。）",
            ["ContentJP"] = "彼女は、あなたの心の葛藤など知らない。あなたもまた、彼女を無闇に危険へ追いやりたくなかっただけだ。",
            ["DialogueId"] = 51004982,
            ["GUID"] = "7FAF7CAD",
            ["NextDialogue"] = 51004983,
            },
        [51004983] = {
            ["Content"] = "（你明白她一定还会继续她自己的写作。但你已经尽力降低了风险——你这样告诉自己。）",
            ["ContentJP"] = "ルナはきっと、これからも書き続けるだろう。声を失ったままでも──それが、彼女自身の選んだ道なのだから。",
            ["DialogueId"] = 51004983,
            ["GUID"] = "7FAF7CAE",
            },
        [51005001] = {
            ["Content"] = "你是……？",
            ["ContentJP"] = "あなたは……？",
            ["DialogueId"] = 51005001,
            ["GUID"] = "7FAF87FA",
            ["NextDialogue"] = 51005002,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700013:Explain01_Start",
                },
            },
        [51005002] = {
            ["Content"] = "（眼前的中年女人正熟练地为落灰的家具清洁除尘，仿佛对修普诺斯之家格外熟悉——但你知道，这里本不该再有人造访。）",
            ["ContentJP"] = "（目の前の中年女性はホコリの積もった家具を慣れた手つきで掃除している。ヒュプノスの家について詳しいようだが——ここに訪れるような人間はもういないはずだと、あなたは知っている）",
            ["DialogueId"] = 51005002,
            ["GUID"] = "7FAF8824",
            ["NextDialogue"] = 51005003,
            ["TalkActionId"] = {
                [1] = "700013:Explain01_End",
                },
            },
        [51005003] = {
            ["Content"] = "打扰了，没想到还有除我以外的人会来到这里。",
            ["ContentJP"] = "お邪魔しております。ここに私め以外の人様が来るだなんて、思いがけないこともあるものね。",
            ["DialogueId"] = 51005003,
            ["GUID"] = "7FAF884E",
            ["NextDialogue"] = 51005004,
            ["SpeakNpcId"] = 700013,
            },
        [51005004] = {
            ["Content"] = "下仆是由恩里克先生雇佣的家政专员，负责定期上门进行保洁与维修工作，今天是我履约的日子。",
            ["ContentJP"] = "私めはヘンリック先生に雇われていた家政婦です。家の清掃とメンテナンスを任されておりました。今日が定期訪問の日でございまして。",
            ["DialogueId"] = 51005004,
            ["GUID"] = "7FAF8878",
            ["NextDialogue"] = 51005005,
            ["SpeakNpcId"] = 700013,
            },
        [51005005] = {
            ["Content"] = "请问您是？",
            ["ContentJP"] = "それで、あなた様は？",
            ["DialogueId"] = 51005005,
            ["GUID"] = "7FAF88A2",
            ["NextDialogue"] = 51005006,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Explain02_Start",
                },
            },
        [51005006] = {
            ["Content"] = "我是隔壁老宅的租客，今天是想看看房子的门窗是否锁好。",
            ["ContentJP"] = "隣の古家を借りている者です。今日はヒュプノスの家の扉と窓が施錠されているのか確認に来ました。",
            ["DialogueId"] = 51005006,
            ["GUID"] = "7FAF88CC",
            ["NextDialogue"] = 51005007,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700013:Explain02_End",
                },
            },
        [51005007] = {
            ["Content"] = "不知您是否收到消息，恩里克先生去世了……你已经没有履约的必要了。",
            ["ContentJP"] = "ヘンリックさんの訃報は聞きましたかね……あなたはもう仕事を果たさなくてもいいんです。",
            ["DialogueId"] = 51005007,
            ["GUID"] = "7FAF88F6",
            ["NextDialogue"] = 51005008,
            ["SpeakNpcId"] = 100001,
            },
        [51005008] = {
            ["Content"] = "下仆知道。",
            ["ContentJP"] = "承知はしていますとも。",
            ["DialogueId"] = 51005008,
            ["GUID"] = "7FAF8920",
            ["NextDialogue"] = 51005009,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Agree",
                },
            },
        [51005009] = {
            ["Content"] = "但恩里克先生已经提前将酬劳支付给下仆，在合同到期前，下仆不会做出有违职业素养的事情。",
            ["ContentJP"] = "ですが報酬は事前にお支払いを受けておりますので。契約が切れるまで私めは義務を果たすつもりです。",
            ["DialogueId"] = 51005009,
            ["GUID"] = "7FAF894A",
            ["NextDialogue"] = 51005010,
            ["SpeakNpcId"] = 700013,
            },
        [51005010] = {
            ["Content"] = "现在是下午四点，下仆将依约提供三小时左右的服务。",
            ["ContentJP"] = "今は午後4時でございます。私めは契約通り3時間の業務に努めます。",
            ["DialogueId"] = 51005010,
            ["GUID"] = "7FAF8974",
            ["NextDialogue"] = 51005011,
            ["SpeakNpcId"] = 700013,
            },
        [51005011] = {
            ["Content"] = "如有其他需要请随时告知，下仆会尽力满足您的需求。",
            ["ContentJP"] = "何かご用があれば、いつでもお声がけくださいね。最善を尽くしますわ。",
            ["DialogueId"] = 51005011,
            ["GUID"] = "7FAF899E",
            ["NextDialogue"] = 51005012,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Explain02_Start",
                },
            },
        [51005012] = {
            ["Content"] = "（莱娜发现了屋子里的爪痕，那是赛琪秽蚀后留下的痕迹。很快，她又看到了恩里克流下的，早已干涸的血迹。）",
            ["ContentJP"] = "（レナは部屋に残された爪跡を発見した。サイキに穢蝕が発現した際の痕跡だ。続けざまに乾き切ったヘンリックの血の跡が、目に飛び込んでくる）",
            ["DialogueId"] = 51005012,
            ["GUID"] = "7FAF89C8",
            ["NextOptions"] = {
                [1] = 510050121,
                },
            ["RestartTag"] = 51005012,
            ["TalkActionId"] = {
                [1] = "700013:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005013] = {
            ["Content"] = "下仆无权评价雇主的生活，我只是在评估如何修复它们能更加美观。",
            ["ContentJP"] = "雇用主の生活を評価する権利など私めにはございません。どのように手入れすれば綺麗になるかを、ただただ考えるのみです。",
            ["DialogueId"] = 51005013,
            ["GUID"] = "7FAF89F2",
            ["NextDialogue"] = 51005014,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Disagree",
                },
            },
        [51005014] = {
            ["Content"] = "（这位女士开始履行她的义务，她的动作都高效而准确，即使是在擦洗满是血渍的地板，她也是一副古井无波，绝不动摇的模样。）",
            ["ContentJP"] = "（彼女は己の義務を果たし始める。全て高効率かつ正確な動きで、血だらけの床を拭いているというのに静まり返った古井戸の水のように落ち着き払っている。何も動揺などしていない様子であった）",
            ["DialogueId"] = 51005014,
            ["GUID"] = "7FAF8A1C",
            },
        [51005015] = {
            ["Content"] = "我曾经……见过更糟的情况，在一栋更加金碧辉煌的住所。那家主人一把火烧掉了整个庄园，连同家人一起，烧得一干二净。",
            ["ContentJP"] = "私めはかつて……ここ以上に凄惨な状況を目の当たりにしたことがございます。それはもう豪華な邸宅でしたが。家の主が全てを焼き払ったのです。家族ですら諸共。",
            ["DialogueId"] = 51005015,
            ["GUID"] = "7FAF8A46",
            ["NextDialogue"] = 51005016,
            ["SpeakNpcId"] = 700013,
            },
        [51005016] = {
            ["Content"] = "相较来说，这里还算是一个家，至少恩里克让这里看起来像一个家。",
            ["ContentJP"] = "それに比べましたらまったく普通の家でございますよ。少なくともヘンリック先生は家らしくあろうとなさっておりましたから。",
            ["DialogueId"] = 51005016,
            ["GUID"] = "7FAF8A70",
            ["NextDialogue"] = 51005017,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Think_Start",
                },
            },
        [51005017] = {
            ["Content"] = "（她古井无波的面庞出现一丝波动，你不由揣测起这位举止端庄，做事利索的女士，也许并不像她表现出来的那样心如止水。）",
            ["ContentJP"] = "（古井戸の水のように落ち着いた彼女の顔に少し変化が生じた。あなたは思わず彼女を観察してしまう。礼儀正しく効率的に仕事をこなしているが、実のところ静止した水のような平静さは見せかけだけで、心の中は穏やかでないのかもしれない）",
            ["DialogueId"] = 51005017,
            ["GUID"] = "7FAF8A9A",
            ["NextOptions"] = {
                [1] = 510050171,
                },
            ["TalkActionId"] = {
                [1] = "700013:Think_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005018] = {
            ["Content"] = "二十年前，他是享有盛名的医生，而我是子爵的女仆。他受邀去为子爵夫人出诊，那是我第一次遇见他。但我本以为我和他不会有更多交集。",
            ["ContentJP"] = "20年前かしら。ヘンリック先生は有名な御医者様で、私めはとある子爵様のメイドでございました。彼が子爵夫人の診察に招かれた際に初めてお会いしまして……それ以上の関係などはございませんでしたが。",
            ["DialogueId"] = 51005018,
            ["GUID"] = "7FAF8AC4",
            ["NextDialogue"] = 51005019,
            ["SpeakNpcId"] = 700013,
            },
        [51005019] = {
            ["Content"] = "在奉命送他回旅馆的路上，他毫不犹豫地救治了一个倒在我们面前的卡戎，并托我照顾那个女孩。",
            ["ContentJP"] = "ご命令を受けて彼を宿まで送り届けておりました道中、倒れていたカロン族の女の子を彼は迷わず治療して救ったのです。そして私めにお世話をしてくれないかと頭をお下げになって……",
            ["DialogueId"] = 51005019,
            ["GUID"] = "7FAF8AEE",
            ["NextDialogue"] = 51005020,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Explain01_Start",
                },
            },
        [51005020] = {
            ["Content"] = "他是一个优秀的医生。不只是因为技艺，更因为……他救治病人的心意，从不因病人的身份有任何改变。",
            ["ContentJP"] = "彼は大変ご立派な御医者様です。診療の技術のみならず……身分で態度を変えることなどしない、患者を救う心意まで深い御方でございました。",
            ["DialogueId"] = 51005020,
            ["GUID"] = "7FAF8B18",
            ["NextOptions"] = {
                [1] = 510050201,
                [2] = 510050202,
                [3] = 510050203,
                },
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Explain01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005021] = {
            ["Content"] = "恩里克不在乎这些……至少，我对他的评价从没变过。",
            ["ContentJP"] = "栄誉などヘンリック先生は気にも留めないと思いますが……少なくとも私めは彼を揺るぎなく評価しております。",
            ["DialogueId"] = 51005021,
            ["GUID"] = "7FAF8B42",
            ["NextOptions"] = {
                [1] = 510050231,
                },
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Disagree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005022] = {
            ["Content"] = "这正是他光辉熠熠的地方。",
            ["ContentJP"] = "それこそが彼の美点なのでしょう。",
            ["DialogueId"] = 51005022,
            ["GUID"] = "7FAF8B6C",
            ["NextOptions"] = {
                [1] = 510050231,
                },
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Agree",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005023] = {
            ["Content"] = "我为发生在他身上的事情，感到深切的悲伤与遗憾。",
            ["ContentJP"] = "彼の身に起きた悲劇には、同情のみならず口惜しさすら感じて仕方がございません。",
            ["DialogueId"] = 51005023,
            ["GUID"] = "7FAF8B96",
            ["NextOptions"] = {
                [1] = 510050231,
                },
            ["SpeakNpcId"] = 700013,
            ["bForbidSkipOptions"] = true,
            },
        [51005024] = {
            ["Content"] = "我只觉得做得不够多。",
            ["ContentJP"] = "まだやるべきことが残っていると、勝手に思い込んでいるだけにすぎません。",
            ["DialogueId"] = 51005024,
            ["GUID"] = "7FAF8BC0",
            ["NextDialogue"] = 51005025,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Disagree",
                },
            },
        [51005025] = {
            ["Content"] = "恩里克先生并不希望和我产生太多的联系，我也不能常常拜访，否则，我和你也许早就见过了。",
            ["ContentJP"] = "ヘンリック先生は私めと接触するのに消極的でございましたから。なので私めも頻繁に訪れることは控えておりました。あなた様と私めが今までお会いできていなかったのはその点が理由でございます。",
            ["DialogueId"] = 51005025,
            ["GUID"] = "7FAF8BEA",
            ["NextDialogue"] = 51005026,
            ["SpeakNpcId"] = 700013,
            },
        [51005026] = {
            ["Content"] = "他也许同样不希望我在他离世后频繁拜访，所以，这把钥匙是时候物归原主了。我会将它妥善放回恩里克先生的办公桌，请您见证。",
            ["ContentJP"] = "彼は恐らく望んでいないかと。死後に私めが何度もここへ訪れるなど……そう考えればこの鍵も元の持ち主に返還した方がよいのでしょう。私めは鍵をヘンリック先生の机に戻そうと考えております。どうかそれに立ち合ってはいただけませんでしょうか。",
            ["DialogueId"] = 51005026,
            ["GUID"] = "7FAF8C14",
            ["NextOptions"] = {
                [1] = 510050261,
                },
            ["RestartTag"] = 51005026,
            ["SpeakNpcId"] = 700013,
            ["bForbidSkipOptions"] = true,
            },
        [51005027] = {
            ["Content"] = "（你什么也没想起来，或许只是你的错觉。）",
            ["ContentJP"] = "（あなたは何も思い出せなかった。ただの勘違いかもしれない）",
            ["DialogueId"] = 51005027,
            ["GUID"] = "7FAF8C3E",
            },
        [51005028] = {
            ["Content"] = "（你在玛尔洁那里得到的钥匙，与莱娜那把可以打开修普诺斯之家的钥匙非常相似。）",
            ["ContentJP"] = "（マギーからもらった鍵だが、レナが持つヒュプノスの家の鍵によく似ているとあなたは気づいた）",
            ["DialogueId"] = 51005028,
            ["GUID"] = "7FAF8C68",
            ["NextDialogue"] = 51005029,
            },
        [51005029] = {
            ["Content"] = "（你想起你曾在恩里克身上见过它。它应该是在那夜的混乱中丢失了，然后被玛尔洁无意间拾得。）",
            ["ContentJP"] = "（そしてヘンリックが鍵を持っていたことを思い出した。きっとあの夜の混乱に紛れた代物を、マギーが偶然に拾ったのだろう）",
            ["DialogueId"] = 51005029,
            ["GUID"] = "7FAF8C92",
            ["NextOptions"] = {
                [1] = 510050291,
                },
            },
        [51005030] = {
            ["Content"] = "恩里克有一个存放重要文件的箱子，我想，用这把钥匙可以打开它。",
            ["ContentJP"] = "ヘンリック先生は重要な書類を保管するチェストをお持ちでした。もしかすると、その鍵で開くかもしれません。",
            ["DialogueId"] = 51005030,
            ["GUID"] = "7FAF8CBC",
            ["NextDialogue"] = 51005031,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Think_Start",
                },
            },
        [51005031] = {
            ["Content"] = "恩里克先生曾委托下仆，如果有不幸降临在他的身上，就打开那个箱子，宣读他的遗嘱。",
            ["ContentJP"] = "自分の身に不幸が降りかかったら、チェストを開けて中にある遺言書を公開するようにと、私めはヘンリック先生からお達しを受けておりました。",
            ["DialogueId"] = 51005031,
            ["GUID"] = "7FAF8CE6",
            ["NextDialogue"] = 51005032,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Think_End",
                },
            },
        [51005032] = {
            ["Content"] = "我在宅子里找不到那把钥匙，没想到它在您手上。感谢您帮忙保管它。",
            ["ContentJP"] = "鍵がなかったので家中を探していたのですが……まさかあなたのお手の中にあったとは。お預かりいただき、誠にありがとうございます。",
            ["DialogueId"] = 51005032,
            ["GUID"] = "7FAF8D10",
            ["NextDialogue"] = 51005033,
            ["SpeakNpcId"] = 700013,
            },
        [51005033] = {
            ["Content"] = "如果可以，请您作为见证，督促下仆严格按照与恩里克先生的约定行事。",
            ["ContentJP"] = "もしよろしければ証人として、私めがヘンリック先生の約束を遵守する様を見届けてはくださいませんか？",
            ["DialogueId"] = 51005033,
            ["GUID"] = "7FAF8D3A",
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Explain02_Start",
                },
            },
        [51005034] = {
            ["Camera"] = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（箱子打开，女仆取出了恩里克的遗嘱，在你的见证之下，她庄重地诵读着。）",
            ["ContentJP"] = "箱が開き、レナはヘンリックの遺言状を取り出す。あなたの立ち会いのもと、彼女はゆっくりと読み上げ始めた。",
            ["DialogueId"] = 51005034,
            ["GUID"] = "7FAF8D64",
            ["NextDialogue"] = 51005035,
            },
        [51005035] = {
            ["Camera"] = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（恩里克也许早就预料到了今天的悲剧，他的遗嘱仍然冷静，只有对女儿的死亡仍旧遗憾，以及——）",
            ["ContentJP"] = "（ヘンリックは早くから来たる悲劇を予想していたのかもしれない。彼の遺言は冷静なものであったが、娘の死に対しては悔いが残されていた。そして——）",
            ["DialogueId"] = 51005035,
            ["GUID"] = "7FAF8D8E",
            ["NextDialogue"] = 51005036,
            },
        [51005036] = {
            ["Camera"] = "-3490.197266,-340.706116,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“在我死后，本人名下的所有房屋产权将移交给莱娜·贝尔女士——”",
            ["ContentJP"] = "「私の死後、私名義に属する住宅の所有権をレナ・ベル氏に引き渡すものとする——」",
            ["DialogueId"] = 51005036,
            ["FinalCamera"] = "-2771.669922,-330.52002,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAF8DB8",
            ["NextDialogue"] = 51005037,
            ["SpeakNpcId"] = 700013,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51005037] = {
            ["Camera"] = "-956.953125,124.710449,851.333984,0.000029,-16.600037,26.61047,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“以感谢她多年来对修普诺斯之家及卡戎病人的付出。”",
            ["ContentJP"] = "「長きに渡ってヒュプノスの家やカロンの患者たちに尽力してくれたことに感謝を」",
            ["DialogueId"] = 51005037,
            ["FinalCamera"] = "-938.859375,88.569275,851.333984,0.000038,-16.600002,26.610426,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAF8DE2",
            ["NextDialogue"] = 51005038,
            ["SpeakNpcId"] = 700013,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51005038] = {
            ["Camera"] = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“由衷感谢贝尔女士所做的一切，她是一位令人尊敬的女士。”",
            ["ContentJP"] = "「ベル氏が成した全ての行いに心からの感謝を贈る。彼女は尊敬されるべき女性だ」",
            ["DialogueId"] = 51005038,
            ["GUID"] = "7FAF8E0C",
            ["NextDialogue"] = 51005039,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "700013:Disagree",
                },
            },
        [51005039] = {
            ["Camera"] = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51005039,
            ["GUID"] = "7FAF8E36",
            ["NextDialogue"] = 510050391,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [51005040] = {
            ["Content"] = "你独自走出了恩里克的办公室。泣不成声的莱娜女士需要独处一会，至少在这段时间，不要打断她的悲伤。",
            ["ContentJP"] = "（あなたはひとりでヘンリックの事務室から出てきた。）\
（泣き崩れたレナさんにはしばらくひとりの時間が必要だろう。少なくとも今は彼女の悲しみに邪魔者などいらない）",
            ["DialogueId"] = 51005040,
            ["Duration"] = 4,
            ["GUID"] = "7FAF8E60",
            ["NextDialogue"] = 51005041,
            },
        [51005041] = {
            ["Content"] = "现在，你有一位新的房东太太了。",
            ["ContentJP"] = "（こうして新しい大家さんが誕生した）",
            ["DialogueId"] = 51005041,
            ["Duration"] = 2,
            ["GUID"] = "7FAF8E8A",
            },
        [51005042] = {
            ["Camera"] = "460.455078,-127.329834,335.509766,0.000047,-28.799341,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（莱娜女士熟悉修普诺斯之家的一草一木，你们顺利地找到箱子，而在箱子边，放着一个突兀的木盒。）",
            ["ContentJP"] = "レナはヒュプノスの家をよく知っていた。あなたたちは迷うことなく箱を見つけ、そのそばに、不自然に置かれた木箱も見つけた。",
            ["DialogueId"] = 51005042,
            ["FinalCamera"] = "460.455078,-148.0,335.509766,0.000054,-28.799347,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAF8EB4",
            ["NextDialogue"] = 51005043,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51005043] = {
            ["Camera"] = "-372.582031,8.945923,112.0,0.0,0.0,0.208069,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（你先打开了那奇怪的木盒，一张笔迹娟秀的信出现在你们眼前，你将信拿出，一字一句地念了出来。）",
            ["ContentJP"] = "あなたはまず、その奇妙な木箱を開けた。中には丁寧な筆跡で書かれた手紙があり、あなたはその一字一句を、声に出して読んだ。",
            ["DialogueId"] = 51005043,
            ["FinalCamera"] = "-350.582031,9.078125,112.0,0.0,0.0,0.408069,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FAF8EDE",
            ["NextDialogue"] = 51005044,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["TurnTo"] = {
                [1] = "700098:n(100001)",
                },
            },
        [51005044] = {
            ["ContentJP"] = "「あなたがこの手紙を読んでいる頃には、私たちはもう「ヒュプノスの家」にはいないでしょう。\
あの夜、サイキの件で警備部隊が動き出し、私たちはアイスレイク城にいられなくなりました。\
だから、警備部隊の捜査が及ぶ前に、私は皆を連れてここを後にしました。\
どうか私たちのことで悲しまないでください。\
そして、私たちが穢蝕によって、誰かを傷つけることを心配する必要はありません。\
私たちは荒野へ向かいます。誰も知らない、どこか遠い場所へ。\
その先に死が待つのか、それとも奇跡が待っているのか、わからないけれど──\
最後の最後まで、希望を信じ続けます。\
……それは、彼女が私たちに教えてくれたことだから。\
最後に、これまで私たちにしてくれたすべてに、感謝を込めて。\
──エリーザ・テイラー」",
            ["DialogueId"] = 51005044,
            ["DialoguePanelType"] = "{type:showtext;topic:Reading_Title_200208;content:Reading_Content_200208}",
            ["GUID"] = "7FAF8F08",
            ["NextDialogue"] = 51005045,
            },
        [51005045] = {
            ["Camera"] = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样啊……孩子们都安然……离开了。",
            ["ContentJP"] = "……そう……あの子たちは、無事に……旅立ったのね。",
            ["DialogueId"] = 51005045,
            ["GUID"] = "7FAF8F32",
            ["NextDialogue"] = 51005046,
            ["SpeakNpcId"] = 700013,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "700098:p(140)",
                },
            },
        [51005046] = {
            ["Camera"] = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（莱娜说完沉默了许久，才吃力地将钥匙插入锁孔。你看着她的手颤抖着，一次次从钥匙上滑落。）",
            ["ContentJP"] = "レナは長い沈黙のあと、ゆっくりと鍵を鍵穴に差し込んだ。あなたは、彼女の震える手が何度も鍵から滑り落ちるのを黙って見守った。",
            ["DialogueId"] = 51005046,
            ["GUID"] = "7FAF8F5C",
            ["NextDialogue"] = 51005047,
            },
        [51005047] = {
            ["Content"] = "……我们一起来吧。",
            ["ContentJP"] = "……手伝うよ。",
            ["DialogueId"] = 51005047,
            ["GUID"] = "7FAF8F86",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51005048,
            ["SpeakNpcId"] = 100001,
            },
        [51005048] = {
            ["Content"] = "抱歉，谢谢。",
            ["ContentJP"] = "……ありがとう。",
            ["DialogueId"] = 51005048,
            ["GUID"] = "7FAF8FB0",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 700013,
            },
        [51005101] = {
            ["Content"] = "这不是{nickname}吗？",
            ["ContentJP"] = "おやおや、そこにいるのは{nickname}ちゃんじゃ、あーりませんかー？",
            ["DialogueId"] = 51005101,
            ["GUID"] = "7FAF9862",
            ["NextDialogue"] = 51005102,
            ["SpeakNpcId"] = 700115,
            },
        [51005102] = {
            ["Content"] = "上回的事多谢你了！贫民窟那几家人拿到生活费以后，也一直托我向你致谢呢！",
            ["ContentJP"] = "この前はベリーサンキュー！ちゃんと生活費は配れたよ！スラム街に住むみんなも「くれぐれもお礼を伝えてくれ」ってさ！",
            ["DialogueId"] = 51005102,
            ["GUID"] = "7FAF988C",
            ["NextOptions"] = {
                [1] = 51005103,
                },
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Agree",
                },
            },
        [51005103] = {
            ["Content"] = "这没什么。",
            ["ContentJP"] = "いやいや、大したことじゃないから。",
            ["DialogueId"] = 51005103,
            ["GUID"] = "7FAF98B6",
            ["NextDialogue"] = 51005104,
            },
        [51005104] = {
            ["Content"] = "别谦虚呀，我都好久没碰上你这种又热心又能干又有礼貌的人了！",
            ["ContentJP"] = "謙遜しないでって！マジになってくれる有能プロなのにマナーも素晴らしいとか、君みたいなタイプにお目にかかるのも久しぶりだよ！",
            ["DialogueId"] = 51005104,
            ["GUID"] = "7FAF98E0",
            ["NextDialogue"] = 51005105,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Talk02_Start",
                },
            },
        [51005105] = {
            ["Content"] = "在冰湖城的这段时间，感觉怎么样呀？",
            ["ContentJP"] = "アイスレイク城にいる時間、いかがお過ごしでしょうか？",
            ["DialogueId"] = 51005105,
            ["GUID"] = "7FAF990A",
            ["NextOptions"] = {
                [1] = 510051051,
                [2] = 510051052,
                [3] = 510051053,
                },
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Talk02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005106] = {
            ["Content"] = "虽说我也觉得人生就是从始发点奔向目的地，但这么忽视路边的风景也很可惜！",
            ["ContentJP"] = "そりゃよーいドンで目的地まで向かうのが人生だとは思うけどさ？道行く景色をスルーってのはもったいないよ？",
            ["DialogueId"] = 51005106,
            ["GUID"] = "7FAF9934",
            ["NextDialogue"] = 51005109,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Agree",
                },
            },
        [51005107] = {
            ["Content"] = "我懂！！！刚来冰湖城的时候我也这么觉得！这儿的规矩莫名其妙，这儿的人也怪怪的！",
            ["ContentJP"] = "わっかるーっ！！アイスレイク城に来たばかりの私もおんなじ気持ちだった！街特有の暗黙の了解とかイミフだし、住んでるのもエキセントリックな人が大量だし！",
            ["DialogueId"] = 51005107,
            ["GUID"] = "7FAF995E",
            ["NextDialogue"] = 51005109,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Agree",
                },
            },
        [51005108] = {
            ["Content"] = "那看来你老家治安也不怎么样……你不会也是逃难来的吧？",
            ["ContentJP"] = "冗談じゃないなら君の実家もスラム的な……まさか君も逃亡してきた感じ？",
            ["DialogueId"] = 51005108,
            ["GUID"] = "7FAF9988",
            ["NextDialogue"] = 51005109,
            ["SpeakNpcId"] = 700115,
            },
        [51005109] = {
            ["Content"] = "算了，不说这些了。",
            ["ContentJP"] = "まあいっか！この話はキャンセル！",
            ["DialogueId"] = 51005109,
            ["GUID"] = "7FAF99B2",
            ["NextDialogue"] = 51005110,
            ["SpeakNpcId"] = 700115,
            },
        [51005110] = {
            ["Content"] = "还是来看看我刚进的货吧！都是些稀奇古怪的小玩意，要是有喜欢的，我就给你打个八折，就当是上次抓贼的谢礼了~",
            ["ContentJP"] = "新しく商品を仕入れたからチェックしてよ！珍妙なレア物たちが目白押し！好みの品があったら、前の大活躍のお礼として20％offしちゃいま～～す！",
            ["DialogueId"] = 51005110,
            ["GUID"] = "7FAF99DC",
            ["NextDialogue"] = 51005111,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Explain02_Start",
                },
            },
        [51005111] = {
            ["Content"] = "（你俯下身，仔细观察起玛尔洁“刚进的货”。不大的木架上堆满杂物，大多都有明显的使用痕迹，但都很干净，显然被精心擦拭过。）",
            ["ContentJP"] = "（あなたは身を屈めてマギーの「仕入れたばかりの商品」を観察した。さほど大きくない木の棚に雑多なモノが目一杯積まれてある。そのほとんどが未使用でない痕跡をはっきりと残していた。状態は綺麗なので、自分で丁寧に拭きあげたのだろう）",
            ["DialogueId"] = 51005111,
            ["GUID"] = "7FAF9A06",
            ["NextOptions"] = {
                [1] = 510051111,
                [2] = 510051112,
                [3] = 510051113,
                },
            ["TalkActionId"] = {
                [1] = "700115:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005112] = {
            ["Content"] = "重点是乐趣，光算账多没意思！",
            ["ContentJP"] = "大事なのは趣ですぜ！勘定ばかりで考えてちゃ楽しめないよ！",
            ["DialogueId"] = 51005112,
            ["GUID"] = "7FAF9A30",
            ["NextDialogue"] = 51005115,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Agree",
                },
            },
        [51005113] = {
            ["Content"] = "当然不是！我可是良民！这些都是被主人丢掉的宝贝。任由它们浪费才是真正的犯罪呢，我只是想给它们都找一个家！",
            ["ContentJP"] = "ノット、ノットギルティ！私めは善良な市民でございますから！この子たちは持ち主に捨てられて、でも私にとっては宝物なんです！浪費を見て見ぬフリする方が本当の罪ってもんじゃない！？この子たちに帰るべき場所を探してあげたいだけなんだって！",
            ["DialogueId"] = 51005113,
            ["GUID"] = "7FAF9A5A",
            ["NextDialogue"] = 51005115,
            ["SpeakNpcId"] = 700115,
            },
        [51005114] = {
            ["Content"] = "嘿嘿，商业机密！",
            ["ContentJP"] = "ふぁふぁふぁ、そりゃ企業秘密ですよ！トップシークレット！",
            ["DialogueId"] = 51005114,
            ["GUID"] = "7FAF9A84",
            ["NextDialogue"] = 51005115,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Agree",
                },
            },
        [51005115] = {
            ["Content"] = "（盛情难却。你翻找着玛尔洁的“货物摊”，试图从中找出有价值的东西。）",
            ["ContentJP"] = "（手厚いサービス精神に押されて断ることができなかったあなたは、マギーの「ガラクタ山」を探った。そこから価値があるものを見つけようとする）",
            ["DialogueId"] = 51005115,
            ["GUID"] = "7FAF9AAE",
            ["NextOptions"] = {
                [1] = 510051151,
                [2] = 510051152,
                [3] = 510051153,
                },
            ["RestartTag"] = 51005115,
            ["bForbidSkipOptions"] = true,
            },
        [51005116] = {
            ["Content"] = "实在没有喜欢的就算啦！等下次进货了再来看看吧。",
            ["ContentJP"] = "好みの品が見つからないなら無理しないで大丈夫だよ！今度仕入れた時にでも見に来てくれたらいいからさ！",
            ["DialogueId"] = 51005116,
            ["GUID"] = "7FAF9AD8",
            ["SpeakNpcId"] = 700115,
            },
        [51005117] = {
            ["Content"] = "不愧是你，一眼就看出这东西的珍贵之处，看来你也有侦探的灵敏嗅觉！",
            ["ContentJP"] = "さっすがお目が高い！その子が貴重品であることに気づくとは！君も探偵特有の鋭い嗅覚を持ってるようだね！",
            ["DialogueId"] = 51005117,
            ["GUID"] = "7FAF9B02",
            ["NextOptions"] = {
                [1] = 51005118,
                },
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Agree",
                },
            },
        [51005118] = {
            ["Content"] = "侦探？这都是哪跟哪啊……",
            ["ContentJP"] = "探偵って？全然関係なくない……？",
            ["DialogueId"] = 51005118,
            ["GUID"] = "7FAF9B2C",
            ["NextDialogue"] = 51005119,
            },
        [51005119] = {
            ["Content"] = "你看中的那几个，是最不值钱的，但也是最值钱的。最不值钱就是字面意义上的，卖不出几个铜币，其他人来了看都不看一眼。",
            ["ContentJP"] = "君のセレクトした品は無価物でもあるし有価物でもあるよ。無価物とは文字通り数枚の銅貨にもならないってこと。他の人は見向きもしないと思う。",
            ["DialogueId"] = 51005119,
            ["GUID"] = "7FAF9B56",
            ["NextDialogue"] = 51005120,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Think_Start",
                },
            },
        [51005120] = {
            ["Content"] = "最珍贵则是因为……这几样货看起来都很有“故事”！你不就是因为这个才挑中它们的吗？",
            ["ContentJP"] = "一方で有価物とは……この子たちの内々から漂ってくる「ストーリー性」の強さ！君はそれを見抜いたんでしょ？",
            ["DialogueId"] = 51005120,
            ["GUID"] = "7FAF9B80",
            ["NextDialogue"] = 51005121,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Think_End",
                },
            },
        [51005121] = {
            ["Content"] = "只要你有足够的耐心和细致入微的观察能力，就能调查出这些宝贝背后的故事和秘密！",
            ["ContentJP"] = "ならば忍耐力と観察力をマックスにして暴き出せるはず！この宝物の裏に隠されてある物語と秘密を！",
            ["DialogueId"] = 51005121,
            ["GUID"] = "7FAF9BAA",
            ["NextDialogue"] = 51005122,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Talk02_Start",
                },
            },
        [51005122] = {
            ["Content"] = "可别小看垃圾桶，很多案件与传闻的真相就藏在这些小角落里！我就是靠着垃圾桶，一点一点了解这座城市的。",
            ["ContentJP"] = "ゴミ箱を侮っちゃあいけないのさ。事件や噂の真相は、大体がちょっとした片隅に隠れている！私もこの街に関することは、ゴミ箱を通して少しずつ知っていったからね。",
            ["DialogueId"] = 51005122,
            ["GUID"] = "7FAF9BD4",
            ["NextDialogue"] = 51005123,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Talk02_End",
                },
            },
        [51005123] = {
            ["Content"] = "好奇了吧！你也想更了解这座城市吧！那就请这里付账！",
            ["ContentJP"] = "気になってきたかな！？この街についてもっと知りたくなったよね！？というわけで、お支払いはこちらにて～！",
            ["DialogueId"] = 51005123,
            ["GUID"] = "7FAF9BFE",
            ["NextDialogue"] = 51005124,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Confident_Start",
                },
            },
        [51005124] = {
            ["Content"] = "（总觉得在被她牵着鼻子走……）",
            ["ContentJP"] = "（なんだか上手く乗せられているだけな気が……）",
            ["DialogueId"] = 51005124,
            ["GUID"] = "7FAF9C28",
            ["NextDialogue"] = 51005125,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700115:Confident_End",
                },
            },
        [51005125] = {
            ["Content"] = "喂喂喂，把你眼睛里的“奸商”两个字收回去，只是一点推销手法！再说了，你都发现这几样东西不对劲了，怎么还能半途而废呢？",
            ["ContentJP"] = "待ってなんだいその目は！目ん玉に「悪徳商人」って文字を浮かべるのストップ！ただのセールトークだし、君だってもう私のコレクションに引っかかる何かを感じてるんでしょ？中途半端に終わりにする気はないよね？",
            ["DialogueId"] = 51005125,
            ["GUID"] = "7FAF9C52",
            ["NextOptions"] = {
                [1] = 510051251,
                [2] = 510051252,
                [3] = 510051253,
                },
            ["SpeakNpcId"] = 700115,
            ["bForbidSkipOptions"] = true,
            },
        [51005126] = {
            ["Content"] = "这么老实？我都有点不好意思了……",
            ["ContentJP"] = "いや、かといって素直すぎない？気恥ずかしくなるんだけど……",
            ["DialogueId"] = 51005126,
            ["GUID"] = "7FAF9C7C",
            ["NextDialogue"] = 51005129,
            ["SpeakNpcId"] = 700115,
            },
        [51005127] = {
            ["Content"] = "精打细算也是狩月人的共通之处呢……",
            ["ContentJP"] = "流石は月狩り人。予算管理を怠らないのは全員共通だけど……",
            ["DialogueId"] = 51005127,
            ["GUID"] = "7FAF9CA6",
            ["NextDialogue"] = 51005129,
            ["SpeakNpcId"] = 700115,
            },
        [51005128] = {
            ["Content"] = "别别别走啊！你再挣扎一下啊！",
            ["ContentJP"] = "タタ、タンマ、行かないで！もうちょっと粘りを見せてよ！",
            ["DialogueId"] = 51005128,
            ["GUID"] = "7FAF9CD0",
            ["NextDialogue"] = 51005129,
            ["SpeakNpcId"] = 700115,
            },
        [51005129] = {
            ["Content"] = "三件东西都交给你啦，就当是我感谢你帮忙抓贼的一点心意！",
            ["ContentJP"] = "そもそも泥棒キャッチャーを手伝ってくれたからね。感謝の気持ちとして3つの商品を君にプレゼントしちゃう予定だったのさ！",
            ["DialogueId"] = 51005129,
            ["GUID"] = "7FAF9CFA",
            ["NextDialogue"] = 51005130,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Talk02_Start",
                },
            },
        [51005130] = {
            ["Content"] = "（玛尔洁不由分说，把三样货物一股脑塞进了你的怀里。）",
            ["ContentJP"] = "（マギーは有無を言わさず3つの商品を一気にあなたの懐へ詰め込んだ）",
            ["DialogueId"] = 51005130,
            ["GUID"] = "7FAF9D24",
            ["NextDialogue"] = 51005131,
            ["TalkActionId"] = {
                [1] = "700115:Talk02_End",
                },
            },
        [51005131] = {
            ["Content"] = "祝您查案顺利，侦探阁下！",
            ["ContentJP"] = "調査が首尾よく進展することを、心よりお祈りしておきますです！名探偵閣下！",
            ["DialogueId"] = 51005131,
            ["GUID"] = "7FAF9D4E",
            ["NextDialogue"] = 51005132,
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Explain02_Start",
                },
            },
        [51005132] = {
            ["Content"] = "等你调查完这三件东西背后的故事，再来和我谈谈你对冰湖城的看法吧！",
            ["ContentJP"] = "この3種の宝に潜むストーリーを調べ上げた先！君のアイスレイク城への想いがどうなるか！全部の調査が終わったら教えてね！",
            ["DialogueId"] = 51005132,
            ["GUID"] = "7FAF9D78",
            ["SpeakNpcId"] = 700115,
            ["TalkActionId"] = {
                [1] = "700115:Explain02_End",
                },
            },
        [51005201] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你回来啦！",
            ["ContentJP"] = "おっかえり～～！",
            ["DialogueId"] = 51005201,
            ["FacialId"] = {
                [1] = "700127:Smile02",
                },
            ["GUID"] = "7FAFA8CA",
            ["NextDialogue"] = 51005202,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Explain02_Start",
                },
            },
        [51005202] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "快和我说说，你调查到了什么大秘密！",
            ["ContentJP"] = "というわけで早速と教えちゃってくださいな！一体全体、どんな巨大な秘密を暴き出したのか！",
            ["DialogueId"] = 51005202,
            ["GUID"] = "7FAFA8F4",
            ["NextOptions"] = {
                [1] = 510052021,
                [2] = 510052022,
                [3] = 510052023,
                },
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Explain02_End",
                },
            },
        [51005203] = {
            ["Camera"] = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "让她“从今以后一个字都别写”确实太残忍了点……我会重点关注她的废纸类垃圾的，尽量别惊动了别人！",
            ["ContentJP"] = "だったら「今後は一切こんなこと書かないように」とか言うのは残酷すぎるね……よし！彼女の出す紙くず類のゴミに気を配っておくよ！できるだけ他の人に気づかれないようにする！",
            ["DialogueId"] = 51005203,
            ["GUID"] = "7FAFA91E",
            ["NextDialogue"] = 51005206,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700127},AnimationId{\"Sigh_Start\"},Duration{2}},PlayAnimation{ActorId{700127},AnimationId{\"Sigh_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 700127,
            },
        [51005204] = {
            ["Camera"] = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "外面的世界也可能没有她想的这么美好……但她也许很需要这样的盼头吧。",
            ["ContentJP"] = "彼女が思ってるほど外の世界は美しくないかもだけど……そんな希望がどうしても必要だったんだね。",
            ["DialogueId"] = 51005204,
            ["FacialId"] = {
                [1] = "700127:Iyada01",
                },
            ["GUID"] = "7FAFA948",
            ["NextDialogue"] = 51005206,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Agree",
                },
            },
        [51005205] = {
            ["Camera"] = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你和莱娜女士也太幸运了！这也许就是命运对好人的奖励吧！",
            ["ContentJP"] = "君もレナさんもWin Winで大ラッキーに終わったんだね！善き人を導いたからこそのご褒美だよきっと！",
            ["DialogueId"] = 51005205,
            ["FacialId"] = {
                [1] = "700127:Satisfy01",
                },
            ["GUID"] = "7FAFA972",
            ["NextDialogue"] = 51005206,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Agree",
                },
            },
        [51005206] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "精彩！你简直就是个明察秋毫的大侦探！",
            ["ContentJP"] = "マーベラス！流石の優れた洞察力！君ってば希代の名探偵！",
            ["DialogueId"] = 51005206,
            ["FacialId"] = {
                [1] = "700127:Ahaha02",
                },
            ["GUID"] = "7FAFA99C",
            ["NextDialogue"] = 51005207,
            ["SpeakNpcId"] = 700127,
            },
        [51005207] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "在冰湖城，哪怕是在一些不起眼的地方，你也总能收获些新惊喜……或者惊吓？",
            ["ContentJP"] = "君の手にかかればアイスレイク城の目立たない場所であっても、フレッシュなサプライズが見つけられるはず……単なるビックリ地点なだけかもだけどさ？",
            ["DialogueId"] = 51005207,
            ["GUID"] = "7FAFA9C6",
            ["NextDialogue"] = 51005208,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Explain02_Start",
                },
            },
        [51005208] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "总而言之，逛了这么一大圈，你对这里有什么新感想吗？",
            ["ContentJP"] = "まま、それはともかくとして、アっちココっちと動き回ったはずですからね。では予告通りお尋ねしましょう！アイスレイク城に対して、何か新しい気持ちは湧いたりした？",
            ["DialogueId"] = 51005208,
            ["FacialId"] = {
                [1] = "700127:Confident02",
                },
            ["GUID"] = "7FAFA9F0",
            ["NextOptions"] = {
                [1] = 510052081,
                [2] = 510052082,
                [3] = 510052083,
                [4] = 510052084,
                [5] = 510052085,
                },
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005209] = {
            ["Camera"] = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哇……确实像是你会给出的答案！我猜了好久你会说些什么，不过完全没猜对！",
            ["ContentJP"] = "ほぉぉ……それが君の見つけ出した答えか！なんて言うか当てようと考えてたんだけど、これっぽっちも掠らなかったよ！",
            ["DialogueId"] = 51005209,
            ["FacialId"] = {
                [1] = "700127:Happy01",
                },
            ["GUID"] = "7FAFAA1A",
            ["NextDialogue"] = 51005210,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Think_Start",
                },
            },
        [51005210] = {
            ["Camera"] = "52.368652,-229.308594,141.289062,0.000091,-3.599974,111.20826,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "总有一种你会在这待上很长一段时间的预感。如果真的只是匆匆过客，谁会想这么多复杂的东西啊！",
            ["ContentJP"] = "君ってばここに長く滞在しそうだね？ただの慌ただしい通りすがりだったら、そんな答えは出せないし！",
            ["DialogueId"] = 51005210,
            ["GUID"] = "7FAFAA44",
            ["NextDialogue"] = 51005211,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Think_End",
                [2] = "100001:Agree",
                },
            },
        [51005211] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们会有很多很多的相处时间了，对不对？",
            ["ContentJP"] = "つまりは私たちの付き合いも長くなるはず。だよね？",
            ["DialogueId"] = 51005211,
            ["GUID"] = "7FAFAA6E",
            ["NextDialogue"] = 51005212,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Confident_Start",
                },
            },
        [51005212] = {
            ["Camera"] = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不知道有没有人已经和你说过这句话，但我一定要再说一次——",
            ["ContentJP"] = "もう誰かが言ってるかもしれないけど、私からも——",
            ["DialogueId"] = 51005212,
            ["GUID"] = "7FAFAA98",
            ["NextDialogue"] = 51005213,
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Confident_End",
                },
            },
        [51005213] = {
            ["Camera"] = "12.572754,75.52832,130.532715,-0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "外乡人，欢迎来到冰湖城！",
            ["ContentJP"] = "アイスレイク城へようこそ！旅人さん！",
            ["DialogueId"] = 51005213,
            ["FacialId"] = {
                [1] = "700127:Happy02",
                },
            ["GUID"] = "7FAFAAC2",
            ["SpeakNpcId"] = 700127,
            ["TalkActionId"] = {
                [1] = "700127:Talk02_Start",
                },
            },
        [51005301] = {
            ["Content"] = "只要消毒得当，就能成为一盘好菜！",
            ["ContentJP"] = "キチンと消毒さえ行えば、ハラショーな料理に仕上がることでしょう！",
            ["DialogueId"] = 51005301,
            ["GUID"] = "7FAFB932",
            ["NextDialogue"] = 51005302,
            ["SpeakNpcId"] = 700116,
            },
        [51005302] = {
            ["Content"] = "……腥味是没了，但这些水产本身的鲜甜味却没有激发出来……",
            ["ContentJP"] = "生臭さはなくなりましたが、いや、しかし、水産物本来の新鮮な甘みを引き出さなければ……",
            ["DialogueId"] = 51005302,
            ["GUID"] = "7FAFB95C",
            ["NextDialogue"] = 51005303,
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Think_Start",
                },
            },
        [51005303] = {
            ["Content"] = "（面前这位男人语速飞快，布满血丝的双眼死死盯着手中的册子和身旁不知名的鱼虾，用还黏着葱叶的双手飞快地写着什么。）",
            ["ContentJP"] = "（目の前の男は早口で何かを呟いている。手に持つ冊子と名も知らぬ魚やエビを血走った目で凝視しながら、ネギの葉が引っついた手で何かを書いている）",
            ["DialogueId"] = 51005303,
            ["GUID"] = "7FAFB986",
            ["NextOptions"] = {
                [1] = 510053031,
                [2] = 510053032,
                },
            ["TalkActionId"] = {
                [1] = "700116:Think_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005304] = {
            ["Content"] = "（装订环上的少量锈迹说明这本老旧册子近期才经历过不怎么细致的清理。）",
            ["ContentJP"] = "（バインダーのリングが僅かながら錆びついている。丁重に扱われていた古い冊子なのだろうが、最近は手入れを怠っていることが分かる）",
            ["DialogueId"] = 51005304,
            ["GUID"] = "7FAFB9B0",
            ["NextDialogue"] = 51005305,
            },
        [51005305] = {
            ["Content"] = "（凑近观察，勉强从杂乱的图形与线条间拼凑出几个香料与烹调方式的词组，想来男人手中的大概是一本食谱。）",
            ["ContentJP"] = "（近寄って内容を観察してみる。乱雑な図形と線の間に数種のスパイスや調理方法のフレーズが記されているとギリギリ読み取れた。この男の手にしている冊子は恐らくレシピなのだろう）",
            ["DialogueId"] = 51005305,
            ["GUID"] = "7FAFB9DA",
            ["NextDialogue"] = 51005307,
            },
        [51005306] = {
            ["Content"] = "（现在最好的选择就是转身离开，但身体在执行的时候却踩到了流淌在地面的粘液发出噗呲的闷响。）",
            ["ContentJP"] = "（今すぐ踵を返して離れるのが一番の選択だろう。そう思い足を動かしたが、地面にこぼれていた粘液を踏んでピチャッと音を立ててしまった）",
            ["DialogueId"] = 51005306,
            ["GUID"] = "7FAFBA04",
            ["NextDialogue"] = 51005307,
            },
        [51005307] = {
            ["Content"] = "（现在，这名男人注意到你了。）",
            ["ContentJP"] = "（男の注意は音に向き、あなたの存在に気づく）",
            ["DialogueId"] = 51005307,
            ["GUID"] = "7FAFBA2E",
            ["NextDialogue"] = 51005308,
            },
        [51005308] = {
            ["Content"] = "……你是？",
            ["ContentJP"] = "……アナタ様は？",
            ["DialogueId"] = 51005308,
            ["GUID"] = "7FAFBA58",
            ["NextDialogue"] = 51005309,
            ["SpeakNpcId"] = 700116,
            },
        [51005309] = {
            ["Content"] = "路过的狩月人。",
            ["ContentJP"] = "ただの通りすがりの月狩り人です。",
            ["DialogueId"] = 51005309,
            ["GUID"] = "7FAFBA82",
            ["NextDialogue"] = 51005310,
            ["SpeakNpcId"] = 100001,
            },
        [51005310] = {
            ["Content"] = "既然是狩月人的话，你是否愿意接受我的委托，与我一起做出更加美味的菜品呢？",
            ["ContentJP"] = "月狩り人であれば、ボクの依頼を引き受けてはくれませんか？イッショにハラショーな料理を完成させましょう！",
            ["DialogueId"] = 51005310,
            ["GUID"] = "7FAFBAAC",
            ["NextOptions"] = {
                [1] = 51000001,
                [2] = 51000002,
                },
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Explain02_Start",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005311] = {
            ["Content"] = "万分感谢。这第一道菜，是在渔民间流传的腌制活鱼活虾的方法上，进行改良的。我这还有些饵料，麻烦你去钓一些用来腌制的东西吧。",
            ["ContentJP"] = "スパシーバ（ありがとうございます）。まず最初の料理は、漁師の間で伝わる生魚と生エビの漬け方を少し改良してみたいんです。エサはまだ残っていますので、漬け込みに使う素材を、少し釣ってきていただけますか？",
            ["DialogueId"] = 51005311,
            ["GUID"] = "7FAFBAD6",
            ["NextOptions"] = {
                [1] = 510053111,
                [2] = 510053112,
                },
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Explain02_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005312] = {
            ["Content"] = "对啊！我会在这期间做好烹饪与消毒的准备。饵料用光了的话就再回来找我吧。",
            ["ContentJP"] = "はい。そのあいだに、ボクは料理と消毒の準備を進めておきます。餌がなくなりましたら、またボクのところへお戻りください。",
            ["DialogueId"] = 51005312,
            ["GUID"] = "7FAFBB00",
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Agree",
                },
            },
        [51005313] = {
            ["Content"] = "这里天然的盐泉似乎能提供腌制所需的材料，采集一些带回去吧。",
            ["ContentJP"] = "ここの天然の塩泉には、漬物に必要な材料があるようだ。いくつか採取して持ち帰ろう。",
            ["DialogueId"] = 51005313,
            ["GUID"] = "7FAFBB2A",
            ["SpeakNpcId"] = 100001,
            },
        [51005314] = {
            ["Content"] = "钓到了，回去找马库斯吧。",
            ["ContentJP"] = "釣れたよ。マーカスのところへ戻ろう。",
            ["DialogueId"] = 51005314,
            ["GUID"] = "7FAFBB54",
            ["SpeakNpcId"] = 100001,
            },
        [51005315] = {
            ["Content"] = "钓到了，回去找马库斯吧。",
            ["ContentJP"] = "釣れたよ。マーカスのところへ戻ろう。",
            ["DialogueId"] = 51005315,
            ["GUID"] = "7FAFBB7E",
            ["SpeakNpcId"] = 100001,
            },
        [51005401] = {
            ["Content"] = "滚滚葱叶切段备用……鱼虾冲净后加入盐、醋，考虑到冰湖城人的口味也许应该再加点糖……",
            ["ContentJP"] = "事前にネギの葉を切り落とす……魚やエビは丁寧に洗ってから塩と酢を加える……アイスレイク城のミナサンのお好みを考えて砂糖を少々加えるのも検討しなければ……",
            ["DialogueId"] = 51005401,
            ["GUID"] = "7FAFC99A",
            ["NextDialogue"] = 51005402,
            ["SpeakNpcId"] = 700116,
            },
        [51005402] = {
            ["Content"] = "（马库斯木讷地接过原料，一边念叨着烹调方式一边拖着它们走远了。）",
            ["ContentJP"] = "（マーカスは無言で材料を受け取る。そして調理方法を呟きながら街の中へと消えていった）",
            ["DialogueId"] = 51005402,
            ["GUID"] = "7FAFC9C4",
            },
        [51005403] = {
            ["Content"] = "（一段时间后，马库斯不知从哪里突然冲出，直到摔倒在雪地里才意识到自己的失态，尴尬地笑着用手拂去身上的尘土。）",
            ["ContentJP"] = "（と思ったひと段落後にどこからともなくマーカスが飛び出してくる。そのまま雪の中に倒れ込むと、ようやく自分の失態に気づいた様子だ。気まずそうに笑いながら体についた汚れを手で払い落す）",
            ["DialogueId"] = 51005403,
            ["GUID"] = "7FAFC9EE",
            ["NextDialogue"] = 51005404,
            },
        [51005404] = {
            ["Content"] = "……抱歉。",
            ["ContentJP"] = "……ハハ、失礼いたしました。",
            ["DialogueId"] = 51005404,
            ["GUID"] = "7FAFCA18",
            ["NextDialogue"] = 51005405,
            ["SpeakNpcId"] = 700116,
            },
        [51005405] = {
            ["Content"] = "你也尝尝味道怎么样？能不能感受到冰湖城特色风味？",
            ["ContentJP"] = "アナタ様もどうかおアジミを。アイスレイク独特の風味を舌で感じていただければ。",
            ["DialogueId"] = 51005405,
            ["GUID"] = "7FAFCA42",
            ["NextDialogue"] = 51005406,
            ["SpeakNpcId"] = 700116,
            },
        [51005406] = {
            ["Content"] = "（他从怀里掏出一包密封的鱼虾，浸润在黝黑的酱汁中隐隐散发着晶莹的光芒。即使隔着密封的薄膜也能闻到浓郁的酱香。）",
            ["ContentJP"] = "（彼の懐から密封された魚とエビが取り出された。真っ黒なソースに浸されていて、キラキラと光を放っている。フィルムで閉じられていても、濃厚な味噌の香りが漏れ出ている）",
            ["DialogueId"] = 51005406,
            ["GUID"] = "7FAFCA6C",
            ["NextOptions"] = {
                [1] = 510054061,
                [2] = 510054062,
                [3] = 510054063,
                },
            ["TalkActionId"] = {
                [1] = "700116:Give",
                },
            },
        [51005407] = {
            ["Content"] = "不要用那么古板的思维看待菜肴。一个人一生中如果不挑战一下非常规食材，那么他人生的乐趣就减少了一半。",
            ["ContentJP"] = "古い考えで料理と向き合うのはいけません。人生一度は常識外な食文化にチョウセンしてみないと、豊かさはハンゲンしてしまいますよ。",
            ["DialogueId"] = 51005407,
            ["GUID"] = "7FAFCA96",
            ["NextDialogue"] = 51005410,
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Disagree",
                },
            },
        [51005408] = {
            ["Content"] = "哈哈，算了算了，看你都快哭出来了。",
            ["ContentJP"] = "ハハハ、無理はなさらないでください。申し訳ございません。そんな今にも泣き出しそうなおカオにさせてしまい。",
            ["DialogueId"] = 51005408,
            ["GUID"] = "7FAFCAC0",
            ["NextDialogue"] = 51005410,
            ["SpeakNpcId"] = 700116,
            },
        [51005409] = {
            ["Content"] = "哼。还好不是所有人都像你一样，对食材的多样性心存偏见。",
            ["ContentJP"] = "ヌヌ、やれやれ。誰もが食材の多様性に偏見を持つ人ばかりではございませんが……ナルホド……",
            ["DialogueId"] = 51005409,
            ["GUID"] = "7FAFCAEA",
            ["NextDialogue"] = 51005410,
            ["SpeakNpcId"] = 700116,
            },
        [51005410] = {
            ["Content"] = "嗯……总之，还有些改良空间。",
            ["ContentJP"] = "……とにかく、改良の余地がまだまだ残っているのは事実です。",
            ["DialogueId"] = 51005410,
            ["GUID"] = "7FAFCB14",
            ["NextDialogue"] = 51005411,
            ["SpeakNpcId"] = 700116,
            ["TalkActionId"] = {
                [1] = "700116:Agree",
                },
            },
        [51005411] = {
            ["Content"] = "之后第二道菜也拜托你了，我的美食搭档！",
            ["ContentJP"] = "次のフタローエもどうかよろしくお頼みいたしますボクの美食のパルトニョール！",
            ["DialogueId"] = 51005411,
            ["GUID"] = "7FAFCB3E",
            ["SpeakNpcId"] = 700116,
            },
        }
  end },
  { MinKey = 51005501, MaxKey = 51006735, Loader = function()
      return {
        [51005501] = {
            ["Content"] = "炖的方式更暖胃，作为开胃菜刚刚好，现在还缺……",
            ["ContentJP"] = "ヴァリーチで胃を温める作用を、であればザクースキとしてちょうどいいでしょうか、今まだ不足していると考えられるのは……",
            ["DialogueId"] = 51005501,
            ["GUID"] = "7FAFDA02",
