            ["TalkActionId"] = {
                [1] = "700117:Think_Start",
                },
            },
        [51005502] = {
            ["Content"] = "（马库斯泛白的脸即使在冰湖的冷风吹拂下也不见一丝血色，不注意观察甚至会以为这是一尊被人遗弃的冰雕。）",
            ["ContentJP"] = "（マーカスの顔は真っ白だ。アイスレイクの冷たい風に吹かれて血の気が消え去っている。よく観察しないと誰かに捨てられた氷の彫刻だと思ってしまいそうなほどに）",
            ["DialogueId"] = 51005502,
            ["GUID"] = "7FAFDA2C",
            ["NextDialogue"] = 51005503,
            },
        [51005503] = {
            ["Content"] = "（但他完全没关注环境的恶劣与身体的哀嚎。）",
            ["ContentJP"] = "（だが環境の過酷さと体の悲鳴に彼はまったく関心を抱いていないようだ）",
            ["DialogueId"] = 51005503,
            ["GUID"] = "7FAFDA56",
            ["NextDialogue"] = 51005504,
            },
        [51005504] = {
            ["Content"] = "（他只是专注地念出一个个原料、调味与烹饪方式，又快速将其否掉，在脑海中拼凑着通向极致菜肴的道路。）",
            ["ContentJP"] = "（材料、味付け、調理方法を一心不乱に読み上げて、すぐに否定するを繰り返して、頭の中で究極の料理への道筋を探っている）",
            ["DialogueId"] = 51005504,
            ["GUID"] = "7FAFDA80",
            ["NextDialogue"] = 51005505,
            ["TalkActionId"] = {
                [1] = "700117:Think_End",
                },
            },
        [51005505] = {
            ["Content"] = "搭档，你来了！",
            ["ContentJP"] = "ヤー我がパルトニョール！来てくださいましたか！",
            ["DialogueId"] = 51005505,
            ["GUID"] = "7FAFDAAA",
            ["NextDialogue"] = 51005506,
            ["SpeakNpcId"] = 700117,
            ["TurnTo"] = {
                [1] = "700117:n(0)",
                },
            },
        [51005506] = {
            ["Content"] = "话不多说，现在还差些月牙鱼，拜托了！",
            ["ContentJP"] = "まだ「ツキワギョ」という魚が足りませんので、今回もお頼みいたします！",
            ["DialogueId"] = 51005506,
            ["GUID"] = "7FAFDAD4",
            ["NextDialogue"] = 51005507,
            ["SpeakNpcId"] = 700117,
            },
        [51005507] = {
            ["Content"] = "（听完马库斯的话你松了一口气。至少这次应该不会被要求试吃生食了。）",
            ["ContentJP"] = "難易度は上がったものの、あなたはむしろほっとした。少なくとも、今度は生ものを試食させられる心配はなさそうだ。",
            ["DialogueId"] = 51005507,
            ["GUID"] = "7FAFDAFE",
            },
        [51005508] = {
            ["Content"] = "垂钓了好一阵子，总算获得了马库斯所需的月牙鱼。",
            ["ContentJP"] = "しばらく釣りをして、ようやくマーカスが求めているツキワギョを手に入れた。",
            ["DialogueId"] = 51005508,
            ["Duration"] = 3,
            ["GUID"] = "7FAFDB28",
            },
        [51005601] = {
            ["Content"] = "（马库斯站在原地剥着北风莓的果皮，一言不发，愈发像是一尊冰雕。但不时抽动的眉头表明，他正在忍受着某种先前没有的刺痛。）",
            ["ContentJP"] = "（マーカスがアイスベリーの皮を剥いている。何も言わず一心不乱なそのありようは一層、氷の彫刻かのような印象を抱いてしまうが。時折ピクピクと眉を動かしているが、あなたはそれを痛みを感じている仕草だと感じた）",
            ["DialogueId"] = 51005601,
            ["GUID"] = "7FAFEA6A",
            ["NextOptions"] = {
                [1] = 510056011,
                [2] = 510056012,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005602] = {
            ["Content"] = "（果皮上有血渍与泥土，其中几枚还因用力过猛而发生了变形，结合马库斯手掌上崭新的划痕来看，这些北风莓应是马库斯刚才亲自攀上附近的山崖采摘的。）",
            ["ContentJP"] = "（果皮に血と土が付着している。果実の数個が力を入れすぎたせいか変形してしまっている。マーカスの手のひらにできた新しい傷を見るに、アイスベリーはマーカス自身が崖を登って摘んだのだろう）",
            ["DialogueId"] = 51005602,
            ["GUID"] = "7FAFEA94",
            ["NextOptions"] = {
                [1] = 51005604,
                },
            },
        [51005603] = {
            ["Content"] = "（鲜血将马库斯一侧的衣服浸透，应是刚才受过什么伤。虽已止血，但对他的伤势来说并没有太大帮助。）",
            ["ContentJP"] = "（マーカスの服の端が血で染まっている。ついさっき怪我したのだろうか。あなたは止血しようとしたが、マーカスが負った怪我にあまり効果はなかった）",
            ["DialogueId"] = 51005603,
            ["GUID"] = "7FAFEABE",
            ["NextOptions"] = {
                [1] = 51005604,
                },
            },
        [51005604] = {
            ["Content"] = "这些血……",
            ["ContentJP"] = "この血は……",
            ["DialogueId"] = 51005604,
            ["GUID"] = "7FAFEAE8",
            ["NextDialogue"] = 51005605,
            },
        [51005605] = {
            ["Content"] = "小事，摘北风莓的时候摔伤了而已。看你的样子，月牙鱼到手了啊，我就知道你做得到，谢了。",
            ["ContentJP"] = "たいしたことはありません。アイスベリーを摘んでいる最中に、少し滑ってけがをしただけです。それより——あっ、ツキワギョが釣れたのですね。さすがです。ぼくの目に狂いはありませんでした。本当にありがとうございます。",
            ["DialogueId"] = 51005605,
            ["GUID"] = "7FAFEB12",
            ["NextDialogue"] = 51005606,
            ["SpeakNpcId"] = 700117,
            ["TurnTo"] = {
                [1] = "700117:n(0)",
                },
            },
        [51005606] = {
            ["Content"] = "（马库斯不愿过多讨论自己的伤势，抬手将北风莓丢进锅里，搅拌均匀后舀出一勺汤汁轻抿了一口。）",
            ["ContentJP"] = "（マーカスは自分の怪我について多くを語らず手を動かし続けた。汚れていないアイスベリーを鍋に投入して、よく混ぜる。スープを掬いあげて軽くひと口、味見する）",
            ["DialogueId"] = 51005606,
            ["GUID"] = "7FAFEB3C",
            ["NextDialogue"] = 51005607,
            },
        [51005607] = {
            ["Content"] = "新鲜的北风莓，加入汤汁的话果然让香气更浓了。",
            ["ContentJP"] = "新鮮なアイスベリーをスープに加えると、芳醇な香りがいっそう引き立ちます……。……",
            ["DialogueId"] = 51005607,
            ["GUID"] = "7FAFEB66",
            ["NextDialogue"] = 51005608,
            ["SpeakNpcId"] = 700117,
            ["TalkActionId"] = {
                [1] = "700117:Agree",
                },
            },
        [51005608] = {
            ["Content"] = "那月牙鱼也得换种处理方式……",
            ["ContentJP"] = "これはツキワギョの調理方法も再考が必要ですな……",
            ["DialogueId"] = 51005608,
            ["GUID"] = "7FAFEB90",
            ["NextDialogue"] = 51005609,
            ["SpeakNpcId"] = 700117,
            },
        [51005609] = {
            ["Content"] = "（马库斯拖着受伤的身体完成剔油、翻焯、煨炖等一道道复杂又漫长的处理工序。）",
            ["ContentJP"] = "マーカスは怪我した体を引きずりながらも材料の油抜き、茹で、煮込み、長い複雑なプロセスを完了させた。",
            ["DialogueId"] = 51005609,
            ["GUID"] = "7FAFEBBA",
            ["NextDialogue"] = 51005610,
            },
        [51005610] = {
            ["Content"] = "（随着食物的香味在一点一滴的积累中迸发，他才从篝火旁起身，乘起满满一碗料理，期待着食客的评价。）",
            ["ContentJP"] = "（食べ物の香りが徐々に強くなる中で焚き火の傍から立ち上がると、彼は料理を椀いっぱいによそった。そして食客の評価を心待ちにしている）",
            ["DialogueId"] = 51005610,
            ["GUID"] = "7FAFEBE4",
            ["NextDialogue"] = 51005611,
            },
        [51005611] = {
            ["Content"] = "咳咳……完成了，你尝尝够好吃、够有特色吗？",
            ["ContentJP"] = "ゴホゴホ……完成いたしましたよ。どうぞごショウミあれ。ハラショーな特色のある料理ができているか、評価を下していただけますでしょうか？",
            ["DialogueId"] = 51005611,
            ["GUID"] = "7FAFEC0E",
            ["NextOptions"] = {
                [1] = 51005612,
                },
            ["SpeakNpcId"] = 700117,
            ["TalkActionId"] = {
                [1] = "700117:Give",
                },
            },
        [51005612] = {
            ["Content"] = "好吃，很暖和。",
            ["ContentJP"] = "とても美味しい、体が温まるよ。",
            ["DialogueId"] = 51005612,
            ["GUID"] = "7FAFEC38",
            ["NextDialogue"] = 51005613,
            },
        [51005613] = {
            ["Content"] = "太好了，我回趟内城，给老板看看我们的成果！",
            ["ContentJP"] = "ハラショー……本当によかった……！早急に内城区に戻って、ボスにもボクたちの成果を味わっていただきます！",
            ["DialogueId"] = 51005613,
            ["GUID"] = "7FAFEC62",
            ["NextDialogue"] = 51005614,
            ["SpeakNpcId"] = 700117,
            },
        [51005614] = {
            ["Content"] = "多谢啦，搭档！这可是我们一起完成的菜品。大伙儿一定会喜欢的！老板也一定会赞不绝口！",
            ["ContentJP"] = "バリショエスパシーバ！我がパルトニョール！これはイッショに作り上げた料理、ボクたちの料理です！ドナタもきっと好きになってくださるに違いありません！ボスも絶賛するのが目に浮かんできます！",
            ["DialogueId"] = 51005614,
            ["GUID"] = "7FAFEC8C",
            ["SpeakNpcId"] = 700117,
            },
        [51005701] = {
            ["Content"] = "……",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51005701,
            ["GUID"] = "7FAFFAD2",
            ["NextDialogue"] = 51005702,
            },
        [51005702] = {
            ["Content"] = "（第三次遇到马库斯时，他就静静地坐在那里，腿上放着一份饭盒。他的神情憔悴，皮肤干瘪，似是很久未曾入睡。）",
            ["ContentJP"] = "（マーカスに会ったのは3回目だろうか。彼は静かに椅子に座り込んでいる。顔は憔悴しきっており、肌はカサカサで長らく寝ていないようだ。膝には弁当箱が置かれてあった）",
            ["DialogueId"] = 51005702,
            ["GUID"] = "7FAFFAFC",
            ["NextDialogue"] = 51005703,
            },
        [51005703] = {
            ["Content"] = "（腹部的伤口依然没有得到妥善处置，若是在炎热的城市说不定那些伤口都会开始散发出腐臭的气息。）",
            ["ContentJP"] = "（体に負った傷はいまだ適切に手当てされていない。もしここが蒸し暑い都市であったならば、傷口から腐臭が立ち込め始めているかもしれないほどの具合だ）",
            ["DialogueId"] = 51005703,
            ["GUID"] = "7FAFFB26",
            ["NextOptions"] = {
                [1] = 51005704,
                },
            },
        [51005704] = {
            ["Content"] = "……你还好吗，老板怎么说？",
            ["ContentJP"] = "{性别:……大丈夫？ボスに何かを言われちゃったの？|……大丈夫？ボスに何かを言われちゃったのか？}",
            ["DialogueId"] = 51005704,
            ["GUID"] = "7FAFFB50",
            ["NextDialogue"] = 51005705,
            },
        [51005705] = {
            ["Content"] = "……",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51005705,
            ["GUID"] = "7FAFFB7A",
            ["LookAt"] = {
                [1] = "700121:n(0)",
                },
            ["NextDialogue"] = 51005706,
            ["SpeakNpcId"] = 700121,
            },
        [51005706] = {
            ["Content"] = "……哈哈，他看都没看，说我之前做的菜一直赚不了大钱，也不准备再雇佣我了。",
            ["ContentJP"] = "……ウージャス……ハハ。ボスは見向きもしてくれませんでした。ボクの料理はいつまで経っても儲けにならない、オマエを雇っているのはムダだと。",
            ["DialogueId"] = 51005706,
            ["GUID"] = "7FAFFBA4",
            ["NextOptions"] = {
                [1] = 51005707,
                },
            ["SpeakNpcId"] = 700121,
            },
        [51005707] = {
            ["Content"] = "……",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51005707,
            ["GUID"] = "7FAFFBCE",
            ["NextDialogue"] = 51005708,
            },
        [51005708] = {
            ["Content"] = "不重要，最后一道菜我也完成了，要不要尝尝看？",
            ["ContentJP"] = "もう疲れてしまったのですが……実は最後の一品も完成しているのです。よろしければヒトクチ、いかがでしょうか？",
            ["DialogueId"] = 51005708,
            ["GUID"] = "7FAFFBF8",
            ["NextDialogue"] = 51005709,
            ["SpeakNpcId"] = 700121,
            },
        [51005709] = {
            ["Content"] = "（马库斯颤抖着举起双手，将饭盒打开，炖菜与碎肉饼的香味便混在一起冲出饭盒，挑逗着食欲。）",
            ["ContentJP"] = "（マーカスは震える手で弁当箱を開けると、煮込み料理とミートボールの香りが混ざり合い、食欲をそそる香りが広がる。）",
            ["DialogueId"] = 51005709,
            ["GUID"] = "7FAFFC22",
            ["NextDialogue"] = 51005710,
            },
        [51005710] = {
            ["Content"] = "（虽说不是大人物们常吃的肉排，却也能支持人们一整天的劳作。几枚被雕刻成星星形状的薯饼点缀其间，为菜肴注入了别样的心意。）",
            ["ContentJP"] = "（上品な肉料理ではないが、人々が一日中働くためのエネルギーを支えるのに十分な料理だ。星の形にカットされたポテトが添えられ、料理に独自の心遣いが感じられる。）",
            ["DialogueId"] = 51005710,
            ["GUID"] = "7FAFFC4C",
            ["NextDialogue"] = 51005711,
            },
        [51005711] = {
            ["Content"] = "（品尝一口，这些食物平凡的外表下绽放出无法言喻的美味，让全身都充满活力，精神也为之振奋，甚至不再畏惧冰湖的寒冬。）",
            ["ContentJP"] = "（あなたは料理を口に運んだ。平凡な見た目からは想像できないほどの、表現しえない旨味が湧き出る。体中に力が滾り、精神が奮い立つ。アイスレイクの厳しい冬さえ恐れぬ心身が備わったかのように思えた）",
            ["DialogueId"] = 51005711,
            ["GUID"] = "7FAFFC76",
            ["NextDialogue"] = 51005712,
            },
        [51005712] = {
            ["Content"] = "（而在饭盒的下方，整齐地叠放着一张布满涂改痕迹的食谱。他点了点头，示意食谱现在起有了新的主人，并微笑等待着食客的评价。）",
            ["ContentJP"] = "（弁当箱の下にはレシピがしっかりと畳まれて置かれている。何度も書き直された痕跡がありありと見える試行錯誤の結晶だ。マーカスはコクリと頷いたことで、レシピの主人が今から新しくなる。そして微笑みながら彼は、食客の評価を待っていた）",
            ["DialogueId"] = 51005712,
            ["GUID"] = "7FAFFCA0",
            ["NextOptions"] = {
                [1] = 510057121,
                [2] = 510057122,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005713] = {
            ["Content"] = "谢谢你愿意吃我做的菜……",
            ["ContentJP"] = "スパシーバ……本当にありがとう……ボクの作った料理を食べてくださって……",
            ["DialogueId"] = 51005713,
            ["GUID"] = "7FAFFCCA",
            ["NextDialogue"] = 51005714,
            ["SpeakNpcId"] = 700121,
            },
        [51005714] = {
            ["Content"] = "（他长呼一口气，手臂无力地垂下，缓缓闭上了双眼。）",
            ["ContentJP"] = "（マーカスは長く息を吐いたかと思うと、力なく腕を垂らし、ゆっくりと目を閉じた）",
            ["DialogueId"] = 51005714,
            ["GUID"] = "7FAFFCF4",
            ["NextDialogue"] = 51005715,
            },
        [51005715] = {
            ["Content"] = "这段时间辛苦你陪我到处收集食材了，好好休息一下吧……我也是……",
            ["ContentJP"] = "食材集めも……お疲れさまでございました……ゆっくりオヤスミください……ボクも…………",
            ["DialogueId"] = 51005715,
            ["GUID"] = "7FAFFD1E",
            ["NextDialogue"] = 51005719,
            ["SpeakNpcId"] = 700121,
            },
        [51005716] = {
            ["Content"] = "即使失败这么多次，你也愿意相信我能做出美味的食物啊……谢谢……你愿意吃我做的菜。",
            ["ContentJP"] = "ボクの料理を……こんなにも多くの失敗をしても信じてくださるのですか……感謝しております……ボクの作った料理を……召し上がってくださったこと……",
            ["DialogueId"] = 51005716,
            ["GUID"] = "7FAFFD48",
            ["NextDialogue"] = 51005717,
            ["SpeakNpcId"] = 700121,
            },
        [51005717] = {
            ["Content"] = "（他长呼一口气，手臂无力地垂下，缓缓闭上了双眼。）",
            ["ContentJP"] = "（マーカスは長く息を吐いたかと思うと、力なく腕を垂らし、ゆっくりと目を閉じた）",
            ["DialogueId"] = 51005717,
            ["GUID"] = "7FAFFD72",
            ["NextDialogue"] = 51005718,
            },
        [51005718] = {
            ["Content"] = "为了搭档，我自然要再努力一把才是。但现在，就让我稍微休息一下吧……",
            ["ContentJP"] = "パルトニョールのためで……ございますからね……ボクは今よりも……励まねば……ですが今は……やはり……少しオヤスミを…………",
            ["DialogueId"] = 51005718,
            ["GUID"] = "7FAFFD9C",
            ["NextDialogue"] = 51005719,
            ["SpeakNpcId"] = 700121,
            },
        [51005719] = {
            ["Content"] = "（从马库斯满足的笑容来看，他应该是找到了心中最想要的评价吧。）",
            ["ContentJP"] = "（マーカスは満足そうな笑顔を見せた。彼は心の中で一番欲しかったであろう言葉を見出せたのだろう）",
            ["DialogueId"] = 51005719,
            ["GUID"] = "7FAFFDC6",
            },
        [51005801] = {
            ["Camera"] = "-210.938385,14.624023,190.298828,0.000005,-33.268826,14.713709,27.0,1.5,false,Disable,1.2",
            ["Content"] = "（面前的箱子无论如何都打不开。）",
            ["ContentJP"] = "（目の前の箱はどうやっても開けられない）",
            ["DialogueId"] = 51005801,
            ["GUID"] = "7FB00B3A",
            ["NextDialogue"] = 51005802,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
            },
        [51005802] = {
            ["Camera"] = "-330.6297,79.707031,109.34375,0.0,-0.468988,-3.087677,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "喂喂喂，你这家伙怎么随便动别人的宝贝啊！",
            ["ContentJP"] = "おいおい！俺らのお宝に許可なく触ってんじゃねえぞ！",
            ["DialogueId"] = 51005802,
            ["FinalCamera"] = "-342.559265,80.349609,109.441406,0.0,-0.468988,-3.087677,35.000011,1.5,false,Disable,1.2",
            ["GUID"] = "7FB00B64",
            ["NextOptions"] = {
                [1] = 510058021,
                [2] = 510058022,
                [3] = 510058023,
                },
            ["Scripts"] = "TurnTo{_delay{1.5},TurnToDescription{\"100001:p(180)\"}}",
            ["SpeakNpcId"] = 700123,
            ["ToFinalCameraBlendTime"] = 6,
            ["bForbidSkipOptions"] = true,
            },
        [51005803] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "好有气魄的发言，大哥，这{性别：小子|小妮子}感觉不好惹啊。",
            ["ContentJP"] = "ちょ、兄貴、この{性别:小僧っ子|小娘っ子}ガチな言いっぷりっすよ。俺たちの実力じゃキャパいんじゃ。",
            ["DialogueId"] = 51005803,
            ["GUID"] = "7FB00B8E",
            ["LookAt"] = {
                [1] = "700124:n(700123)",
                },
            ["NextDialogue"] = 51005807,
            ["SpeakNpcId"] = 700124,
            },
        [51005804] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "没事没事，人家也不知道……",
            ["ContentJP"] = "まあしゃーないっしょ。ぶっちゃけ俺たちも知んねえか……",
            ["DialogueId"] = 51005804,
            ["GUID"] = "7FB00BB8",
            ["NextDialogue"] = 51005805,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"700123:n(700124)\"}}",
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_Start",
                },
            },
        [51005805] = {
            ["Content"] = "（二哥话还没说完就被大哥捂住嘴打了一拳。）",
            ["ContentJP"] = "（次男は長男によって話し終える前に口を塞がれる。そして1発殴られた）",
            ["DialogueId"] = 51005805,
            ["GUID"] = "7FB00BE2",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "700123:n(700124)",
                },
            ["NextDialogue"] = 51005806,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_End",
                },
            ["TurnTo"] = {
                [1] = "700123:n(700124)",
                },
            },
        [51005806] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "爽……",
            ["ContentJP"] = "ふごぉ……",
            ["DialogueId"] = 51005806,
            ["GUID"] = "7FB00C0C",
            ["NextDialogue"] = 51005807,
            ["SpeakNpcId"] = 700124,
            },
        [51005807] = {
            ["Camera"] = "-121.098236,-47.270508,134.38916,0.00009,-2.592344,127.106155,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "哼，你再仔细看看！",
            ["ContentJP"] = "ふん、目ん玉かっぴらいてもっかい見てみな！",
            ["DialogueId"] = 51005807,
            ["GUID"] = "7FB00C36",
            ["LookAt"] = {
                [1] = "700123:n(100001)",
                [2] = "700124:n(100001)",
                },
            ["NextDialogue"] = 51005808,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_Start",
                },
            },
        [51005808] = {
            ["Camera"] = "202.494812,-61.686523,45.185059,0.000138,8.606803,150.299393,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "今天天气真好啊，有太阳有月亮的。",
            ["ContentJP"] = "ああ今日はいい天気だなぁ。太陽も月も綺麗だなぁ。",
            ["DialogueId"] = 51005808,
            ["GUID"] = "7FB00C60",
            ["LookAt"] = {
                [1] = "100001:n(700125)",
                },
            ["NextDialogue"] = 51005809,
            ["SpeakNpcId"] = 700125,
            },
        [51005809] = {
            ["Camera"] = "-644.993774,-361.563477,276.576172,0.000161,-16.793268,38.694996,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "（又一名男子不知何时站到了箱子旁边，黑色的墨水不断从他背在身后的手上流到地面。）",
            ["ContentJP"] = "（いつのまにか末っ子が箱の隣に立っていた。後ろに回した手から黒いインクが地面に垂れ続けている）",
            ["DialogueId"] = 51005809,
            ["FinalCamera"] = "-632.271545,-377.451172,276.576172,0.000162,-16.793268,38.694847,35.000011,1.5,false,Disable,1.2",
            ["GUID"] = "7FB00C8A",
            ["NextDialogue"] = 51005810,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51005810] = {
            ["Content"] = "（他吹着口哨，努力装着漫不经心的样子，而他脚边的箱子上则出现了几个大字——帝国三兄弟的宝贝！明显是三哥刚写上去的。）",
            ["ContentJP"] = "（『帝国三兄弟のお宝！』と明らかについさっき書いたばかりのモノだと分かる文字が箱には書かれてあった。彼は口笛を吹きながら知らないフリをしている）",
            ["DialogueId"] = 51005810,
            ["GUID"] = "7FB00CB4",
            ["NextDialogue"] = 51005811,
            },
        [51005811] = {
            ["Camera"] = "1.0383,-161.240234,125.036621,0.000154,-3.793118,125.094276,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "整个帝国还没人敢动我们帝国三兄弟的东西，你不赔我们七……八……九……九后面是几来着？",
            ["ContentJP"] = "俺ら帝国三兄弟のお宝に手を出すイカれポンチは帝国中をひっくり返したっていやしねえのに。こりゃベンショー的なヤツがなきゃ許さないぜ。7……8……9……きゅう、キュー。9の次ってなんぞ？",
            ["DialogueId"] = 51005811,
            ["GUID"] = "7FB00CDE",
            ["NextOptions"] = {
                [1] = 51005812,
                [2] = 51005813,
                },
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{700123},AnimationId{\"Think_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_End",
                },
            ["TurnTo"] = {
                [1] = "100001:n(700123)",
                },
            },
        [51005812] = {
            ["Content"] = "十。",
            ["ContentJP"] = "ジュウだよ。",
            ["DialogueId"] = 51005812,
            ["GUID"] = "7FB00D08",
            ["NextDialogue"] = 51005814,
            },
        [51005813] = {
            ["Content"] = "零。",
            ["ContentJP"] = "ゼロだよ。",
            ["DialogueId"] = 51005813,
            ["GUID"] = "7FB00D32",
            ["NextDialogue"] = 51005814,
            },
        [51005814] = {
            ["Content"] = "原来是这个啊，你人还怪好的，谢了哈。",
            ["ContentJP"] = "そうそれ、あざます。お前ひょっとしていいヤツじゃね？",
            ["DialogueId"] = 51005814,
            ["GUID"] = "7FB00D5C",
            ["NextDialogue"] = 51005815,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Think_End",
                },
            },
        [51005815] = {
            ["Camera"] = "-25.328522,-87.751953,115.732422,0.000161,1.406718,133.292084,35.000015,1.5,false,Disable,1.2",
            ["Content"] = "不对，谁问你了！",
            ["ContentJP"] = "ってちげぇ！お前になんざ聞いちゃねえの！",
            ["DialogueId"] = 51005815,
            ["FinalCamera"] = "-93.570923,-15.314453,118.177246,0.000161,1.406718,133.292084,35.000015,1.5,false,Disable,1.2",
            ["GUID"] = "7FB00D86",
            ["NextDialogue"] = 51005816,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 0.2,
            },
        [51005816] = {
            ["Camera"] = "-71.120178,15.601562,125.89209,0.00017,-3.194855,0.488689,35.000015,1.5,false,Disable,1.2",
            ["Content"] = "大哥大哥，九后面当然是两个九啊。",
            ["ContentJP"] = "兄貴、兄貴、9の次は9がふたつじゃない？だから99だと思うよ？",
            ["DialogueId"] = 51005816,
            ["GUID"] = "7FB00DB0",
            ["NextDialogue"] = 51005817,
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "700123:Confident_End",
                [2] = "700125:Explain02_Start",
                },
            },
        [51005817] = {
            ["Camera"] = "-377.132507,79.888672,168.172363,0.000133,-13.794611,-2.116058,27.0,1.5,false,Disable,1.2",
            ["Content"] = "他*的，居然敢耍我们帝国三兄弟，不揍你一顿再让你赔我们九九位数的银币这事就不算完！",
            ["ContentJP"] = "ちっ！俺ら帝国三兄弟を騙しやがったな！もう堪忍袋の緒が切れちまった！1発ボコってからキュウとキュウ桁の銀貨をベンショーしてもらおうぜ！",
            ["DialogueId"] = 51005817,
            ["FinalCamera"] = "-413.024841,81.214844,176.993164,0.000133,-13.794611,-2.116058,27.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB00DDA",
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51005901] = {
            ["Content"] = "嘘……别动，这种时候只要装死就好了。",
            ["ContentJP"] = "シッ……動くなよ。こんな時は死に真似しときゃいい。",
            ["DialogueId"] = 51005901,
            ["GUID"] = "7FB01BA2",
            ["NextDialogue"] = 51005902,
            ["Scripts"] = "PARA\
{\
PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}},\
