                [4] = "700125:Onground01_Loop",
                },
            },
        [51005902] = {
            ["Content"] = "我是死人，我是死人，我是死人……",
            ["ContentJP"] = "やっべ死んだ、俺死んだ、いやマジで死んだ……",
            ["DialogueId"] = 51005902,
            ["GUID"] = "7FB01BCC",
            ["NextDialogue"] = 51005903,
            ["SpeakNpcId"] = 700124,
            },
        [51005903] = {
            ["Camera"] = "-31.010925,345.116211,221.408691,0.000395,-17.802675,-135.255722,70.0,1.5,false,Disable,1.2",
            ["Content"] = "你……你把我大哥二哥打死了……你、你赔我钱！！",
            ["ContentJP"] = "よ……よくも兄貴たちを殺したな！ベ、ベンショーだ！！",
            ["DialogueId"] = 51005903,
            ["FinalCamera"] = "-31.011719,345.116211,173.425293,0.000394,-17.802668,-135.255737,70.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB01BF6",
            ["LookAt"] = {
                [1] = "100001:n(700125)",
                },
            ["NextDialogue"] = 51005904,
            ["SpeakNpcId"] = 700125,
            ["ToFinalCameraBlendTime"] = 12,
            },
        [51005904] = {
            ["Content"] = "（二哥无论你怎么打都死死抱着箱子，三哥则抱着你的大腿不让你离开，显然是讹定你了。）",
            ["ContentJP"] = "（次男はどんなにボコられてもしっかり箱にしがみついている。三男はあなたの脚に抱きついて離れない。あなたからタカるのを諦めていない様子だ）",
            ["DialogueId"] = 51005904,
            ["GUID"] = "7FB01C20",
            ["TalkOptions"] = {
                [1] = 510059041,
                [2] = 510059042,
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005905] = {
            ["Camera"] = "-506.111328,318.686523,121.462891,0.000001,-5.777739,-35.397011,28.0,1.5,false,Disable,1.2",
            ["Content"] = "哈哈哈哈复活！笨蛋笨蛋，知道我们帝国三兄弟的厉害了吧！",
            ["ContentJP"] = "ブゥワッハハハ！ふっかぁーつ！騙されたな三下ぁ！俺ら帝国三兄弟のヤバさが身に染みただろぉ！",
            ["DialogueId"] = 51005905,
            ["GUID"] = "7FB01C4A",
            ["NextDialogue"] = 51005906,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_Start",
                },
            },
        [51005906] = {
            ["Content"] = "笨蛋，蛋……我饿了。",
            ["ContentJP"] = "バーカ、バー……あぁ、お腹減ったな。",
            ["DialogueId"] = 51005906,
            ["GUID"] = "7FB01C74",
            ["NextDialogue"] = 51005907,
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "700125:Sigh_Start",
                [2] = "700123:Confident_End",
                },
            },
        [51005907] = {
            ["Content"] = "把箱子抱走卖了钱就吃得起饭了，快走快走。",
            ["ContentJP"] = "こいつを売りゃメシにもありつけるさ。さっさとズらかるぜ。",
            ["DialogueId"] = 51005907,
            ["GUID"] = "7FB01C9E",
            ["NextDialogue"] = 51005908,
            ["SpeakNpcId"] = 700123,
            ["TurnTo"] = {
                [1] = "700123:p(180)",
                },
            },
        [51005908] = {
            ["Camera"] = "-405.640564,-14.355469,143.032715,0.000066,-10.778933,-143.991943,50.000008,1.5,false,Disable,1.2",
            ["Content"] = "人可以走，箱子放下。",
            ["ContentJP"] = "ズラかってもいいが、箱は置いてけよ。",
            ["DialogueId"] = 51005908,
            ["GUID"] = "7FB01CC8",
            ["NextDialogue"] = 51005912,
            ["SpeakNpcId"] = 700126,
            },
        [51005909] = {
            ["Content"] = "你打死了我两位兄弟，还踢我！哎哟，我胳膊被你踢断了，你赔钱！加倍！",
            ["ContentJP"] = "お、お前、兄貴たちを殺した挙句に俺まで蹴るつもりかー！？お前に蹴られて俺の腕も骨折しちまったー！ベンショーしろ！倍だ！2倍だー！",
            ["DialogueId"] = 51005909,
            ["GUID"] = "7FB01CF2",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "100001:n(700125)",
                [2] = "700125:n(100001)",
                },
            ["NextDialogue"] = 51005910,
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                [2] = "700125:Onground01_Loop",
                },
            ["TurnTo"] = {
                [1] = "700123:p(180)",
                },
            },
        [51005910] = {
            ["Camera"] = "-237.173828,-25.819824,27.271973,0.000396,33.800621,119.541695,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "（三哥依旧牢牢地抱着你的腿。）",
            ["ContentJP"] = "（三男は変わらずあなたの脚にしがみついている）",
            ["DialogueId"] = 51005910,
            ["GUID"] = "7FB01D1C",
            ["NextDialogue"] = 51005911,
            },
        [51005911] = {
            ["Camera"] = "-405.640564,-14.355469,143.032715,0.000066,-10.778933,-143.991943,50.000008,1.5,false,Disable,1.2",
            ["Content"] = "干什么呢这是？拿开你的爪子。",
            ["ContentJP"] = "何してんだよ？その手を退けろっての。",
            ["DialogueId"] = 51005911,
            ["GUID"] = "7FB01D46",
            ["NextDialogue"] = 51005912,
            ["SpeakNpcId"] = 700126,
            },
        [51005912] = {
            ["Camera"] = "-83.982361,289.22168,60.012695,0.000395,10.797306,-133.456161,70.000015,1.5,false,Disable,1.2",
            ["Content"] = "刚才我可全都看到了，箱子明明是{nickname}先捡到的。你们抢别人的东西不说，还在这儿敲诈。",
            ["ContentJP"] = "大体は見てたが、何を譲歩したって{nickname}が先に箱を拾ってたとしか思えないがな。人様のもんを横取るだけじゃなく、金までぶんどろうってのはなかなかな連中だ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005912,
            ["GUID"] = "7FB01D70",
            ["NextDialogue"] = 51005913,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{700126},TargetPoint{\"200216Aote1\"},MoveSpeed{90},Visibility{\"Show\"}},\
LookAt{_delay{2},LookAtDescription{\"100001:n(700126)\"}}\
}\
",
            ["SpeakNpcId"] = 700126,
            },
        [51005913] = {
            ["Content"] = "（奥特赛德向你使了一个眼色，似乎在示意“他来解决你的麻烦”。）",
            ["ContentJP"] = "（アウトサイダーがあなたに目配せをしてきた。「俺がこのトラブルを解決する」との合図なようだ）",
            ["DialogueId"] = 51005913,
            ["GUID"] = "7FB01D9A",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005914,
            ["Scripts"] = "PARA{\
MoveTo{_delay{2},ActorId{700126},TargetPoint{\"200216Aote2\"},MoveSpeed{90},Visibility{\"Show\"}},\
LookAt{_delay{2},LookAtDescription{\"700126:n(700126)\"}}\
}",
            },
        [51005914] = {
            ["Camera"] = "-783.460938,-134.15332,202.978027,0.000408,-9.002374,17.755602,60.798176,1.5,false,Disable,1.2",
            ["Content"] = "谁说是你的了，这上面都写了人家的名了！",
            ["ContentJP"] = "リアル俺らのだっての！ちな箱に名前が書いてあっからそこんとこよろしく！",
            ["DialogueId"] = 51005914,
            ["GUID"] = "7FB01DC4",
            ["LookAt"] = {
                [1] = "700123:n(700126)",
                },
            ["NextDialogue"] = 51005915,
            ["Scripts"] = "LookAt{_delay{1.1},LookAtDescription{\"700123:n(700126)\"}}",
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700123:p(180)",
                },
            },
        [51005915] = {
            ["Content"] = "帝国三兄弟的宝贝，这写得还挺……狂野。",
            ["ContentJP"] = "帝国三兄弟のお宝だぁ？こりゃなかなか……ワイルドな字だな。",
            ["DialogueId"] = 51005915,
            ["GUID"] = "7FB01DEE",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextDialogue"] = 51005916,
            ["SpeakNpcId"] = 700126,
            },
        [51005916] = {
            ["Content"] = "漂亮吧，我用这支油笔练了好久呢。",
            ["ContentJP"] = "だろ！油性ペンで長いこと練習したからなぁ。",
            ["DialogueId"] = 51005916,
            ["GUID"] = "7FB01E18",
            ["NextDialogue"] = 51005917,
            ["Scripts"] = "PlayAnimation{_delay{1.1},ActorId{700125},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 700125,
            },
        [51005917] = {
            ["Camera"] = "-86.712891,359.711426,133.382812,0.00039,-1.602663,-103.652168,62.179134,1.5,false,Disable,1.2",
            ["Content"] = "什么油笔这么好用，让我看看？",
            ["ContentJP"] = "油性ペン？そいつって使いやすいのか？どんなのか見せてくれよ。",
            ["DialogueId"] = 51005917,
            ["GUID"] = "7FB01E42",
            ["NextDialogue"] = 51005918,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk02_Start",
                },
            },
        [51005918] = {
            ["Content"] = "哼哼，冰湖城人都没什么见识嘛。喏，拿去给你开开眼。",
            ["ContentJP"] = "おやおやアイスレイクに住んでるヤツはモノを知らねえのが多いってかさぁ……ほらよ、しかと見やがれってんだ。",
            ["DialogueId"] = 51005918,
            ["GUID"] = "7FB01E6C",
            ["NextDialogue"] = 51005919,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Give",
                },
            },
        [51005919] = {
            ["Content"] = "（奥特赛德接过笔后拿在手里转了几圈，然后在大哥背上写下了一行字。）",
            ["ContentJP"] = "（アウトサイダーはペンを受け取ると、何度かペンを回した後に長男の背中へひとつの言葉を書いた）",
            ["DialogueId"] = 51005919,
            ["GUID"] = "7FB01E96",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51005920,
            ["TalkActionId"] = {
                [1] = "700126:Talk02_End",
                [2] = "700124:Confident_End",
                },
            },
        [51005920] = {
            ["Content"] = "好了，按照你们的说法，从现在起，你们就是我奥特赛德的跟班了。",
            ["ContentJP"] = "さて、お前らの言い分が正しいなら、今からお前らはこの俺、アウトサイダーの付き人になったわけだ。",
            ["DialogueId"] = 51005920,
            ["GUID"] = "7FB01EC0",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextDialogue"] = 51005921,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk03_Start",
                },
            },
        [51005921] = {
            ["Content"] = "嗯？啊？",
            ["ContentJP"] = "あ？え？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005921,
            ["GUID"] = "7FB01EEA",
            ["NextDialogue"] = 51005922,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Sigh_Start",
                },
            },
        [51005922] = {
            ["Camera"] = "-317.345703,-158.464355,126.776367,0.000416,-0.602566,56.548306,62.738827,1.5,false,Disable,1.2",
            ["Content"] = "啊……大哥背上确实写着……“奥特赛德的跟班”。还、还真是……",
            ["ContentJP"] = "あ……確かに書いてる！兄貴の背中に「アウトサイダーの付き人」って！つまりは本当に……",
            ["DialogueId"] = 51005922,
            ["GUID"] = "7FB01F14",
            ["NextDialogue"] = 51005923,
            ["SpeakNpcId"] = 700125,
            },
        [51005923] = {
            ["Content"] = "既然大哥成了奥特赛德的跟班，咱们又是大哥的小弟，所以咱、咱们也是这个奥特赛德的……？",
            ["ContentJP"] = "兄貴がアウトサイダーの付き人になったわけだから、俺たちは兄貴の弟分だし、俺たちもアウトサイダーの……",
            ["DialogueId"] = 51005923,
            ["GUID"] = "7FB01F3E",
            ["NextDialogue"] = 51005924,
            ["SpeakNpcId"] = 700125,
            },
        [51005924] = {
            ["Content"] = "好耶，人家是奥特赛德的跟班了。跟班是什么意思啊？",
            ["ContentJP"] = "っしゃあこら！俺たち今日からアウトサイダーの付き人じゃん！てか付き人ってどゆこと？",
            ["DialogueId"] = 51005924,
            ["GUID"] = "7FB01F68",
            ["LookAt"] = {
                [1] = "700124:n(700125)",
                },
            ["NextDialogue"] = 51005925,
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Confident_Start",
                },
            },
        [51005925] = {
            ["Content"] = "跟班就是……就是……",
            ["ContentJP"] = "付き人ってのはなぁ……てのはなぁ……",
            ["DialogueId"] = 51005925,
            ["GUID"] = "7FB01F92",
            ["NextOptions"] = {
                [1] = 510059251,
                [2] = 510059252,
                [3] = 510059253,
                },
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "700125:Think_Start",
                [2] = "700126:Talk03_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005926] = {
            ["Camera"] = "-127.353516,-290.64502,141.182129,0.000389,-4.003146,93.954231,45.828033,1.5,false,Disable,1.2",
            ["Content"] = "哦哦，原来如此……还是不懂。",
            ["ContentJP"] = "あーね……うん、全然わかんね。",
            ["DialogueId"] = 51005926,
            ["GUID"] = "7FB01FBC",
            ["LookAt"] = {
                [1] = "700123:n(700126)",
                [2] = "700124:n(700126)",
                [3] = "700125:n(700126)",
                },
            ["NextDialogue"] = 51005927,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{700124},AnimationId{\"Disagree\"},Duration{0.1}}",
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Agree",
                },
            },
        [51005927] = {
            ["Content"] = "跟班就是你们听我的话，我就不会亏待你们，以后有我和{nickname}一口肉吃，就少不了你们一口汤喝。",
            ["ContentJP"] = "付き人ってのは契約みたいなもんさ。お前らが俺の言うことを聞いてりゃ、お前らは俺から酷く扱われない。俺と{nickname}に食い扶持がありゃ、お前らの腹は空かなくなる。",
            ["DialogueId"] = 51005927,
            ["GUID"] = "7FB01FE6",
            ["NextDialogue"] = 51005928,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_Start",
                },
            },
        [51005928] = {
            ["Camera"] = "-397.066406,36.696777,151.856934,0.000385,-6.203246,11.162275,50.000008,1.5,false,Disable,1.2",
            ["Content"] = "听起来很不赖啊！以后我们管你们叫大大哥，你们叫我们大哥二哥三哥就好，咱们各论各的，二哥三哥，来。",
            ["ContentJP"] = "なんだ悪かねえじゃん！じゃあこれからあんたらをおやじって呼ぶから、あんたらは俺らを「長男」「次男」「三男」って呼んでくれや。おい、次男、三男、いいよな？",
            ["DialogueId"] = 51005928,
            ["GUID"] = "7FB02010",
            ["NextDialogue"] = 51005929,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{700123},AnimationId{\"Confident_End\"},Duration{0.1}}",
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Confident_Start",
                },
            },
        [51005929] = {
            ["Content"] = "大大哥们好！",
            ["ContentJP"] = "おやじ！",
            ["DialogueId"] = 51005929,
            ["GUID"] = "7FB0203A",
            ["NextDialogue"] = 51005930,
            ["SpeakNpcName"] = "UI_CMNpc_Name_SanXiongdi",
            ["TalkActionId"] = {
                [1] = "700123:Agree",
                [2] = "700124:Agree",
                [3] = "700125:Agree",
                },
            },
        [51005930] = {
            ["Content"] = "行了行了，先说说看，为什么非得抢箱子。",
            ["ContentJP"] = "わかった、わかったから、まずは聞いていいか？一体全体どうして箱なんざ盗ろうとしたんだよ？",
            ["DialogueId"] = 51005930,
            ["GUID"] = "7FB02064",
            ["NextDialogue"] = 51005931,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk03_End",
                },
            },
        [51005931] = {
            ["Camera"] = "-691.196594,-40.563477,185.212402,0.000427,-10.603089,11.55783,35.0,1.5,false,Disable,1.2",
            ["Content"] = "我们是从丹流城过来讨生活的。谁知道这一路又是秽兽又是雪狼，甚至还有神弃者同盟跟军团打架的。但是，咱们也得吃饭的嘛，所以……",
            ["ContentJP"] = "生活のためにレッドバリーを飛び出したんだが、道すがら<Default note=\"text:エジュウ\">穢獣</>に白いオオカミだけじゃなく、フォーセイクン同盟と帝国軍がバトってんのともカチ合ってさ。何か腹の足しになるもんが欲しくて……",
            ["DialogueId"] = 51005931,
            ["FinalCamera"] = "-688.296509,-54.745117,185.212402,0.000428,-10.603083,11.557263,35.0,1.5,false,Disable,1.2",
            ["GUID"] = "7FB0208E",
            ["NextDialogue"] = 51005932,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51005932] = {
            ["Content"] = "那么远的地方你们怎么来的。",
            ["ContentJP"] = "そんな遠いとこから？どうやって来たんだよ。",
            ["DialogueId"] = 51005932,
            ["GUID"] = "7FB020B8",
            ["NextDialogue"] = 51005933,
            ["SpeakNpcId"] = 700126,
            },
        [51005933] = {
            ["Content"] = "那点路当然是用脚走过来的啦！",
            ["ContentJP"] = "んなの歩き一択っしょ！",
            ["DialogueId"] = 51005933,
            ["GUID"] = "7FB020E2",
            ["NextDialogue"] = 51005934,
            ["SpeakNpcId"] = 700124,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_Start",
                },
            },
        [51005934] = {
            ["Content"] = "那你们还……挺有毅力的。",
            ["ContentJP"] = "お前ら……根性だけはあるな。",
            ["DialogueId"] = 51005934,
            ["GUID"] = "7FB0210C",
            ["NextDialogue"] = 51005935,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Agree",
                },
            },
        [51005935] = {
            ["Camera"] = "-415.045776,25.477539,88.027344,0.000006,12.016644,20.329792,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "走过来是个什么概念？",
            ["ContentJP"] = "レッドバリーって徒歩でどれくらいの距離な{性别:んだ|の}？",
            ["DialogueId"] = 51005935,
            ["GUID"] = "7FB02136",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005936,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700124:Talk01_End",
                },
            },
        [51005936] = {
            ["Content"] = "没个半年走不过来，脑子正常的人都不会这么干。",
            ["ContentJP"] = "ここまで来るのに半年だろうな。頭がイかれてなきゃまずやらねえぞ。",
            ["DialogueId"] = 51005936,
            ["GUID"] = "7FB02160",
            ["NextDialogue"] = 51005937,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_Start",
                },
            },
        [51005937] = {
            ["Camera"] = "94.544922,-72.209961,230.001465,0.000072,-21.18392,156.51619,41.357956,1.5,false,Disable,1.2",
            ["Content"] = "咳咳，我作为大大哥，一向是很厚道的。你们把箱子还给{nickname}，再帮我跑几个腿，我就宽宏大量，不和你们计较了。",
            ["ContentJP"] = "ゴホン、俺にはおやじとして寛大な心ってもんがある。箱を{nickname}に返して、俺の用事を少し手伝ってくれるなら、お前ら見逃してやってもいいぞ。",
            ["DialogueId"] = 51005937,
            ["GUID"] = "7FB0218A",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextOptions"] = {
                [1] = 510059371,
                [2] = 510059372,
                },
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51005938] = {
            ["Camera"] = "-80.927734,-14.502441,185.629883,0.000013,-16.983728,145.126053,40.0,1.5,false,Disable,1.2",
            ["Content"] = "这不得给你找回场子嘛。再说了，这可不是欺负，他们还得谢谢咱们呢。",
            ["ContentJP"] = "筋は通してもらわないとだ。イジめじゃないし、むしろ感謝して欲しいぐらいの措置だぞ？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005938,
            ["GUID"] = "7FB021B4",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005940,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{700126},AnimationId{\"Confident_End\"},Duration{0.1}}",
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Confident_Start",
                },
            },
        [51005939] = {
            ["Camera"] = "-497.850647,19.27832,106.201172,0.000021,-0.383638,8.526095,35.000008,1.5,false,Disable,1.2",
            ["Content"] = "啊？没有了，真的没有了！我们的兜比你的脸还干净！",
            ["ContentJP"] = "え、俺たち無一文だって！今以上に出せるもんねえよ！？",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005939,
            ["GUID"] = "7FB021DE",
            ["NextDialogue"] = 51005940,
            ["SpeakNpcId"] = 700123,
            ["TalkActionId"] = {
                [1] = "700123:Disagree",
                },
            },
        [51005940] = {
            ["Camera"] = "97.474609,-59.709961,145.413574,0.000075,-3.983646,159.516525,41.357956,1.5,false,Disable,1.2",
            ["Content"] = "好吧，那就下次再说。",
            ["ContentJP"] = "んじゃ、また今度な。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51005940,
            ["GUID"] = "7FB02208",
            ["LookAt"] = {
                [1] = "700126:n(700123)",
                },
            ["NextDialogue"] = 51005941,
            ["SpeakNpcId"] = 700126,
            },
        [51005941] = {
            ["Content"] = "谢谢大大哥们！",
            ["ContentJP"] = "おやじたち、あざっした！",
            ["DialogueId"] = 51005941,
            ["GUID"] = "7FB02232",
            ["NextDialogue"] = 51005942,
            ["SpeakNpcName"] = "UI_CMNpc_Name_SanXiongdi",
            ["TalkActionId"] = {
                [1] = "700123:Agree",
                [2] = "700124:Agree",
                [3] = "700125:Agree",
                },
            },
        [51005942] = {
            ["Camera"] = "-425.447266,140.77002,126.579102,0.000018,-1.584133,-13.274455,35.000011,1.5,false,Disable,1.2",
            ["Content"] = "你看。",
            ["ContentJP"] = "おうよ。",
            ["DialogueId"] = 51005942,
            ["GUID"] = "7FB0225C",
            ["LookAt"] = {
                [1] = "700126:n(100001)",
                },
            ["NextDialogue"] = 51005943,
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_Start",
                [2] = "100001:Sigh_Start",
                },
            },
        [51005943] = {
            ["Camera"] = "-462.640625,217.032227,95.944336,0.000029,2.416118,-24.873308,35.222115,1.5,false,Disable,1.2",
            ["Content"] = "好了，既然麻烦完美解决，今晚都去我那吃？",
            ["ContentJP"] = "さて、問題も解決したし、今夜の晩メシは俺のとこで食おうぜ？",
            ["DialogueId"] = 51005943,
            ["FinalCamera"] = "-600.123047,257.368652,161.696289,0.000031,-4.384059,-21.671299,23.312325,1.5,false,Disable,1.2",
            ["GUID"] = "7FB02286",
            ["LookAt"] = {
                [1] = "700126:n(700126)",
                },
            ["NextDialogue"] = 51005944,
            ["Scripts"] = "TurnTo{_delay{1.5},TurnToDescription{\"700126:n(100001)\"}}",
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_End",
                [2] = "100001:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 12,
            },
        [51005944] = {
            ["Content"] = "好，又蹭到饭了！",
            ["ContentJP"] = "やったぁ！ただメシだぁ！",
            ["DialogueId"] = 51005944,
            ["GUID"] = "7FB022B0",
            ["LookAt"] = {
                [1] = "700126:n(700125)",
                },
            ["NextDialogue"] = 51005945,
            ["SpeakNpcId"] = 700125,
            ["TalkActionId"] = {
                [1] = "700125:Angry01_Start",
                },
            },
        [51005945] = {
            ["Content"] = "走吧走吧，跟我不用那么客气。",
            ["ContentJP"] = "さあ行くぞ。俺に遠慮はいらねえからさ。",
            ["DialogueId"] = 51005945,
            ["GUID"] = "7FB022DA",
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
            ["SpeakNpcId"] = 700126,
            ["TalkActionId"] = {
                [1] = "700126:Talk01_Start",
                },
            },
        [51005946] = {
            ["Content"] = "大大哥们好！",
            ["ContentJP"] = "ちっす！おやじ！",
            ["DialogueId"] = 51005946,
            ["GUID"] = "7FB02304",
            ["LookAt"] = {
                [1] = "700130:n(0)",
                },
            ["SpeakNpcName"] = "UI_CMNpc_Name_SanXiongdi",
            ["TurnTo"] = {
                [1] = "700130:n(0)",
                },
            },
        [51006001] = {
            ["Camera"] = "-1493.62561,331.186523,137.640625,0.0,0.0,-131.798843,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这个月的话，老猎人小队排行第一，卡米拉女士冷暴力受害者小队排行第二，目标是天生无敌大狩月人小队第三……",
            ["ContentJP"] = "今月のトップは「イツメンチーム」、次が「カミラさんの精神的虐待被害者の会」、3番目は「生まれながらの天才月狩り人に俺はなる！」か……",
            ["DialogueId"] = 51006001,
            ["GUID"] = "7FB02C0A",
            ["NextDialogue"] = 51006002,
            ["Scripts"] = "SEQ{CameraMoveTo{TargetPosition{\"-1493.62561,315.0,137.640625,0.0,0.0,-131.798843,35.0,100000.0,false,DoNotOverride,2.8\"},duration{1.5}},PARA{CameraMoveTo{_delay{2},TargetPosition{\"-963.597046,234.248047,150.28125,0.000001,1.799966,34.202541,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},PlayAnimation{ActorId{200003},AnimationId{\"Talk03_Start\"},Duration{2}}},CameraMoveTo{_delay{4},TargetPosition{\"-7.200806,-120.374023,142.90625,0.000004,0.0,87.602119,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
            ["SpeakNpcId"] = 700143,
            ["TurnTo"] = {
                [1] = "100001:n(700143)",
                [2] = "700144:n(700143)",
                },
            },
        [51006002] = {
            ["Camera"] = "-7.200806,-120.374023,142.90625,0.000004,0.0,87.602119,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "老队伍的名字都还是挺规矩的，但……哎，总有一天这个看板要会写不下的。",
            ["ContentJP"] = "古参のチームは無難でありふれた名前ばかりなんだが……そのうち掲示板に書き切れなくなりそうだな。",
            ["DialogueId"] = 51006002,
            ["FinalCamera"] = "-7.493896,-127.367188,142.90625,0.000004,0.0,87.602119,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB02C34",
            ["NextDialogue"] = 51006003,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700143},AnimationId{\"Disagree\"},Duration{1}},PlayAnimation{ActorId{700143},AnimationId{\"Sigh_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700143,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51006003] = {
            ["Camera"] = "-23.626343,-435.28418,117.951172,0.0,-1.000022,88.595695,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（水仙平原的侍者在看板前一边写着奇怪词汇一边喃喃自语，看上去非常专注地发着愁。）",
            ["ContentJP"] = "（アスフォデロスのウェイターが掲示板に奇妙な単語を書き込みながら、ぶつぶつと独り言をつぶやいている。なにか悩んでいるようだ）",
            ["DialogueId"] = 51006003,
            ["FinalCamera"] = "-23.626343,-403.0,117.951172,0.0,-0.999994,88.595695,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB02C5E",
            ["NextDialogue"] = 51006004,
            ["Scripts"] = "SEQ{PARA{LookAt{LookAtDescription{\"700144:n(100001)\"}},LookAt{LookAtDescription{\"100001:n(700144)\"}}},PARA{LookAt{_delay{2},LookAtDescription{\"700144:n(700144)\"}},LookAt{_delay{2},LookAtDescription{\"100001:n(100001)\"}}},PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}}}",
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51006004] = {
            ["Camera"] = "-29.76123,245.500977,144.087891,0.000001,-1.299956,-87.998413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你好，请问你这是……？",
            ["ContentJP"] = "こんにちは。あの……これって一体……？",
            ["DialogueId"] = 51006004,
            ["GUID"] = "7FB02C88",
            ["NextDialogue"] = 51006005,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700143:Sigh_End",
                [2] = "700144:Confident_End",
                [3] = "100001:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "700143:n(100001)",
                },
            },
        [51006005] = {
            ["Camera"] = "-41.585571,-289.919922,132.876953,0.000008,0.399996,91.800735,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯？我在更新这个月的狩月人小队排名——卡米拉女士想出来的法子，整理这些狩月人们的数据。",
            ["ContentJP"] = "ああ、今月の月狩り人ランキングですよ。カミラさんのアイディアでね、チームごとのデータをまとめているんです。",
            ["DialogueId"] = 51006005,
            ["GUID"] = "7FB02CB2",
            ["NextDialogue"] = 51006006,
            ["SpeakNpcId"] = 700143,
            ["TalkActionId"] = {
                [1] = "700143:Explain01_Start",
                [2] = "100001:Explain02_End",
                },
            },
        [51006006] = {
            ["Camera"] = "-41.585571,-289.919922,132.876953,0.000008,0.399996,91.800735,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "每个月完成了多少委托呀，平均一次委托收了多少佣金呀，和委托人吵没吵过架之类。",
            ["ContentJP"] = "例えば、月別の依頼完了件数、1回の依頼の平均報酬額、依頼人とトラブルを起こさなかったかとか。",
            ["DialogueId"] = 51006006,
            ["GUID"] = "7FB02CDC",
            ["NextDialogue"] = 51006007,
            ["SpeakNpcId"] = 700143,
            ["TalkActionId"] = {
                [1] = "700143:Explain01_End",
                },
            },
        [51006007] = {
            ["Camera"] = "-22.652466,-432.3125,117.951172,0.0,-1.000022,87.596008,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以你们如果要和奥特赛德一起结成新的小队的话，也最好商量一下自己的队伍名字，找我来登记。",
            ["ContentJP"] = "というわけで、あなたとアウトサイダーでチームを組むなら、まずは登録用のチーム名を考えてくださいね。",
            ["DialogueId"] = 51006007,
            ["FinalCamera"] = "-22.652466,-411.0,117.951172,0.0,-1.000022,87.596001,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB02D06",
            ["NextDialogue"] = 51006008,
            ["SpeakNpcId"] = 700143,
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51006008] = {
            ["Camera"] = "-165.896606,-64.533203,164.121094,0.000034,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来是这样，之前白确实听到过一些抱怨，说这里的狩月人们看起来脾气都不是很好，不敢委托工作。",
            ["ContentJP"] = "あーそういえば……依頼人が愚痴っているのを聞いたことがあるよ。アスフォデロスの月狩り人はなんだか柄が悪い人が多くて、依頼するのが怖いって。",
            ["DialogueId"] = 51006008,
            ["GUID"] = "7FB02D30",
            ["LookAt"] = {
                [1] = "100001:n(700144)",
                [2] = "700144:n(100001)",
                },
            ["NextDialogue"] = 51006009,
            ["SpeakNpcId"] = 700144,
            ["TurnTo"] = {
                [1] = "700144:n(100001)",
                },
            },
        [51006009] = {
            ["Camera"] = "-165.896606,-64.533203,164.121094,0.000034,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但是如果一个队伍起了什么汪汪队喵喵队之类的名字，就突然没那么可怕了——毕竟人们总说，喜欢小动物的没有坏人。",
            ["ContentJP"] = "でもでも、チームの名前が「尻尾ぶんぶんわんこ隊」とか「ゴロゴロ猫ちゃんチーム」とかだったらどうかな？怖さナッシングだよね。動物好きな人に悪いやつはいないっていうしさ。",
            ["DialogueId"] = 51006009,
            ["GUID"] = "7FB02D5A",
            ["NextDialogue"] = 51006010,
            ["Scripts"] = "SetLocation{ActorId{700145},TargetPoint{\"TargetPoint_Aote\"},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Talk01_Start",
                },
            },
        [51006010] = {
            ["Camera"] = "184.0,-79.0,87.949219,0.000015,4.999999,-170.997498,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我看不见得，我之前的单人小队的名字也是小动物啊，怎么委托数就没见涨。",
            ["ContentJP"] = "それはどうかな。俺のソロチームも動物の名前だったが、あまり依頼は来なかったぞ。",
            ["DialogueId"] = 51006010,
            ["FinalCamera"] = "184.0,-76.0,87.949219,0.000015,4.999999,-170.997498,33.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB02D84",
            ["LookAt"] = {
                [1] = "100001:n(700145)",
                [2] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006011,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Think_Start",
                [2] = "700144:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["TurnTo"] = {
                [1] = "100001:n(700145)",
                [2] = "700144:n(700145)",
                },
            },
        [51006011] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396646,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊！狗耳朵是从哪里冒出来的！",
            ["ContentJP"] = "ぬわっ！わんこ耳、どこから湧いて出たのさ！",
            ["DialogueId"] = 51006011,
            ["GUID"] = "7FB02DAE",
            ["NextDialogue"] = 51006012,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Shock_Start",
                [2] = "700145:Think_End",
                },
            ["TurnTo"] = {
                [1] = "700145:n(100001)",
                },
            },
        [51006012] = {
            ["Camera"] = "122.913086,-109.845703,133.205078,0.000018,0.999987,179.004623,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这不是路过刚好看到我们的新朋友，过来看看，搭把手什么的？",
            ["ContentJP"] = "たまたま取りかかったらお前たちを見かけただけだ。{nickname}はこの街じゃ新入りだから、何か手伝えることはないかと思ってな。",
            ["DialogueId"] = 51006012,
            ["GUID"] = "7FB02DD8",
            ["NextDialogue"] = 51006013,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Talk03_Start",
                },
            },
        [51006013] = {
            ["Camera"] = "-262.660034,43.351562,185.205078,0.000012,-11.200007,-53.19593,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你的小队名字是什么？",
            ["ContentJP"] = "そのチームはどんな名前だったの{性别:かな|}？",
            ["DialogueId"] = 51006013,
            ["GUID"] = "7FB02E02",
            ["NextDialogue"] = 51006014,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51006014] = {
            ["Camera"] = "122.937256,-108.84668,135.205078,0.000018,0.19994,178.604645,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“食用昆虫研究队”……",
            ["ContentJP"] = "「食用昆虫研究隊」だ。",
            ["DialogueId"] = 51006014,
            ["GUID"] = "7FB02E2C",
            ["NextDialogue"] = 51006015,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"700145:n(700145)\"}}",
            ["SpeakNpcId"] = 700145,
            },
        [51006015] = {
            ["Camera"] = "-262.660034,43.351562,185.205078,0.000012,-11.200007,-53.19593,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "首先我觉得我们提到小动物时一般想不到昆虫，然后我觉得你应该很清楚为什么这个名字不会带来更多委托……",
            ["ContentJP"] = "……ええっと、動物って言ったら普通は昆虫は思い浮かばないと思う。それにそんな名前じゃ依頼が来ないのはアウトサイダーだってわかってるはずだよね。",
            ["DialogueId"] = 51006015,
            ["GUID"] = "7FB02E56",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                },
            ["NextDialogue"] = 51006016,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Disagree",
                [2] = "700145:Talk03_End",
                },
            },
        [51006016] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396646,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是就是，我刚刚还在想，奥特赛德怎么会给队伍起可爱小动物的名字，怎么想都不太可能！",
            ["ContentJP"] = "そーだそーだ！アウトサイダーがかわいい動物のチーム名を名乗るなんて、どう考えてもあり得ないと思ったけどさ。",
            ["DialogueId"] = 51006016,
            ["GUID"] = "7FB02E80",
            ["NextDialogue"] = 51006017,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Angry01_Start",
                [2] = "100001:Confident_End",
                },
            },
        [51006017] = {
            ["Camera"] = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你懂什么，这叫做与众不同，一眼就能让人留下印象，你觉得呢，{nickname}？是不是非常有冲击力。",
            ["ContentJP"] = "お前はなにもわかってねえな。こういうのは目立つのが大事なんだよ。この名前なら一発で覚えてもらえること間違いなしだ。{nickname}だってインパクトのあるチーム名だと思うだろ？",
            ["DialogueId"] = 51006017,
            ["GUID"] = "7FB02EAA",
            ["NextOptions"] = {
                [1] = 510060171,
                [2] = 510060172,
                [3] = 510060173,
                },
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Explain01_Start",
                [2] = "700144:Angry01_End",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51006018] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是就是！",
            ["ContentJP"] = "そーだそーだ！",
            ["DialogueId"] = 51006018,
            ["GUID"] = "7FB02ED4",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
                [3] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006023,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Agree",
                },
            },
        [51006019] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是就是！",
            ["ContentJP"] = "そーだそーだ！",
            ["DialogueId"] = 51006019,
            ["GUID"] = "7FB02EFE",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
                [3] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006023,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Agree",
                },
            },
        [51006020] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不——好——！你们这样下去，队伍一定会变成看板上倒数第一的！",
            ["ContentJP"] = "ずぇったいにだめーーー！そんな名前にしたらランキング最下位になっちゃうよ！",
            ["DialogueId"] = 51006020,
            ["GUID"] = "7FB02F28",
            ["LookAt"] = {
                [1] = "700145:n(100001)",
                [2] = "100001:n(700145)",
                [3] = "700144:n(700145)",
                },
            ["NextDialogue"] = 51006021,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006021] = {
            ["Camera"] = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "倒数第一不也会让人好奇——",
            ["ContentJP"] = "最下位でも目立ちゃいいんだよ。じゃあこれで決まりだな――",
            ["DialogueId"] = 51006021,
            ["GUID"] = "7FB02F52",
            ["NextDialogue"] = 51006022,
            ["SpeakNpcId"] = 700145,
            },
        [51006022] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停停停！",
            ["ContentJP"] = "待って待って！",
            ["DialogueId"] = 51006022,
            ["GUID"] = "7FB02F7C",
            ["NextDialogue"] = 51006023,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006023] = {
            ["Camera"] = "-165.896606,-64.533203,164.121094,0.000035,-17.399591,-29.602789,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在我们组成了新的队伍，已经不是你一个人单打独斗了，所以你这个名字作废，我们来取一个新的名字！",
            ["ContentJP"] = "私たちの新しいチーム名なんだよね？だったらアウトサイダーのソロチームとは別の名前にしなくちゃ。",
            ["DialogueId"] = 51006023,
            ["GUID"] = "7FB02FA6",
            ["NextDialogue"] = 51006024,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "100001:n(700144)",
                },
            },
        [51006024] = {
            ["Camera"] = "-29.963501,-92.201172,138.935547,0.000018,8.199928,169.801865,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呃，也行，不过要是我们三个意见不统一怎么办。",
            ["ContentJP"] = "まあそれもそうだが……みんなの意見があわなかったらどうするんだ。",
            ["DialogueId"] = 51006024,
            ["GUID"] = "7FB02FD0",
            ["NextDialogue"] = 51006025,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Agree",
                [2] = "700144:Explain02_End",
                },
            },
        [51006025] = {
            ["Camera"] = "-81.742432,-73.919922,111.949219,0.000021,-10.600009,-24.396614,33.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，白早就想好啦，自然是靠身手决定，谁赢了就听谁的。跟我来，我们来比试比试吧。",
            ["ContentJP"] = "えっへん、それならちゃんと考えてあるぞ。運動神経の勝負で勝った人が考えた名前を採用するのさ。3回勝負だよ。スノウについてきて。",
            ["DialogueId"] = 51006025,
            ["GUID"] = "7FB02FFA",
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700144},AnimationId{\"Agree\"},Duration{2}},PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 700144,
            },
        [51006101] = {
            ["Camera"] = "245.083435,-275.051758,86.080566,0.0,0.0,113.398338,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，这不是吵闹小白吗！后面跟着的是……食用昆虫研究队的赛特奥德！",
            ["ContentJP"] = "おお、これはお騒がせなスノたんじゃないか！それに……食用昆虫研究隊のサイダーアウトくん。",
            ["DialogueId"] = 51006101,
            ["GUID"] = "7FB03C72",
            ["LookAt"] = {
                [1] = "100001:n(700146)",
                [2] = "700144:n(700146)",
                [3] = "700145:n(700146)",
                },
            ["NextDialogue"] = 51006102,
            ["Scripts"] = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "100001:n(700146)",
                [2] = "700144:n(700146)",
                [3] = "700145:n(700146)",
                [4] = "700146:n(700144)",
                },
            },
        [51006102] = {
            ["Camera"] = "234.691406,72.036133,66.071777,0.000003,10.399475,-155.20079,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，我当是谁呢，原来是探险家皎皎啊。虽然刚刚叫对了我的小队名让我有一点感动，但只是几天不见，你又把我名字叫错了。",
            ["ContentJP"] = "ああ、誰かと思ったらルーナ族の探検家か。チーム名を正しく呼んでくれたのはちょっと感動したが、何日か会わないだけでまた俺の名前を間違えたな。",
            ["DialogueId"] = 51006102,
            ["GUID"] = "7FB03C9C",
            ["NextDialogue"] = 51006103,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700145},AnimationId{\"Explain01_Start\"},Duration{3}},PlayAnimation{ActorId{700145},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{700145},AnimationId{\"Disagree\"},Duration{1}}}",
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006103] = {
            ["Camera"] = "-105.877808,-273.970215,200.745117,0.000031,-17.99987,65.800964,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那是因为我的注意力总是在你带回来的记录上，等下次，我就一定会记对你的名字的！赛特奥德小哥。",
            ["ContentJP"] = "それは私の関心がきみの名前より記録に向けられているからだ。次はちゃんと名前を覚えるよ、サイトアウダーくん。",
            ["DialogueId"] = 51006103,
            ["GUID"] = "7FB03CC6",
            ["NextDialogue"] = 51006104,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain01_Start",
                },
            },
        [51006104] = {
            ["Camera"] = "-253.942383,145.432129,112.640137,0.000095,-3.399563,-32.804798,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么吵闹小白，这位是？",
            ["ContentJP"] = "で、お騒がせなスノたん、{nickname}と連れだって私を訪ねるとは、なにか用かな？",
            ["DialogueId"] = 51006104,
            ["GUID"] = "7FB03CF0",
            ["NextDialogue"] = 51006105,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain01_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700144)",
                },
            },
        [51006105] = {
            ["Camera"] = "-47.697998,-122.447266,163.110352,0.000107,-15.799224,-21.20565,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "{性别：他|她}呀，是{nickname}，我新认识的小仆从，现在我在引导{性别：他|她}成为一名合格的狩月人。",
            ["ContentJP"] = "{nickname}は最近知り合った我が下僕で、スノウが一人前の月狩り人へと導いてあげているのさ。",
            ["DialogueId"] = 51006105,
            ["GUID"] = "7FB03D1A",
            ["LookAt"] = {
                [1] = "100001:n(700144)",
                },
            ["NextDialogue"] = 51006106,
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"700144:n(100001)\"}},LookAt{LookAtDescription{\"700144:n(100001)\"}},PlayAnimation{_delay{2},ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700144,
            },
        [51006106] = {
            ["Camera"] = "-70.926147,-57.200684,76.004883,0.000152,0.0,32.790924,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么，我再来向你介绍一下！她是探险家皎皎，我认识的皎皎之民中就数她最富有冒险精神，最喜欢收集各种冒险者的情报啦。",
            ["ContentJP"] = "じゃあ、改めて紹介するね！このお姉さんは、スノウが知っているルーナ族のなかでも冒険心が一番強くて、冒険家の情報を集めるのが大好きなんだ。",
            ["DialogueId"] = 51006106,
            ["GUID"] = "7FB03D44",
            ["LookAt"] = {
                [1] = "100001:n(700146)",
                },
            ["NextDialogue"] = 51006107,
            ["Scripts"] = "SEQ{CameraMoveTo{TargetPosition{\"-70.926147,-62.0,76.004883,0.000152,0.0,32.790958,28.0,100000.0,false,DoNotOverride,2.8\"},duration{2}},CameraMoveTo{TargetPosition{\"59.133484,-36.513672,112.323975,0.000181,0.0,78.584763,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"60.901123,-27.689453,112.323975,0.000181,0.0,78.984596,28.0,100000.0,false,DoNotOverride,2.8\"},duration{2}},CameraMoveTo{TargetPosition{\"35.020691,-126.598145,87.284668,0.000142,0.0,77.791298,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},PlayAnimation{ActorId{700146},AnimationId{\"Explain02_Start\"},Duration{2}}}",
            ["SpeakNpcId"] = 700144,
            ["TurnTo"] = {
                [1] = "700144:n(700146)",
                [2] = "700146:n(100001)",
                },
            },
        [51006107] = {
            ["Camera"] = "35.020691,-126.598145,87.284668,0.000142,0.0,77.791298,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你看，就连奥特赛德的那个糟糕的小队名字，她都会记得！",
            ["ContentJP"] = "ほら、アウトサイダーのあのへんちくりんなチーム名だってちゃんと覚えているよ！",
            ["DialogueId"] = 51006107,
            ["GUID"] = "7FB03D6E",
            ["NextDialogue"] = 51006108,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_End",
                },
            },
        [51006108] = {
            ["Camera"] = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "奥德赛特的起名水准虽然一般，但身手还是很厉害的！换做一般的狩月人，顶着这样一个小队名字，应该在一年前转行或者三个月前饿毙街头了。",
            ["ContentJP"] = "アウダーサイトくんのネーミングセンスは微妙だが、実力は認めるぞ。あんなチーム名じゃ普通の月狩り人ならとっくに転職するか、そのへんで行き倒れになっているだろう。",
            ["DialogueId"] = 51006108,
            ["GUID"] = "7FB03D98",
            ["NextDialogue"] = 51006109,
            ["Scripts"] = "CameraMoveTo{_delay{3},TargetPosition{\"62.480164,-164.678711,86.856934,0.000015,0.0,88.998657,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Talk03_Start",
                [2] = "700146:Confident_Start",
                },
            },
        [51006109] = {
            ["Camera"] = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "饿毙……行吧，改，改吧。那么小个子你说的靠身手决定，是什么意思？",
            ["ContentJP"] = "行き倒れ……あーわかったわかった。別の名前にすりゃいいんだろ。で、白いちびっ子、さっき言ってた運動神経の勝負ってどういうことだ？",
            ["DialogueId"] = 51006109,
            ["GUID"] = "7FB03DC2",
            ["NextDialogue"] = 51006110,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700146:Confident_End",
                },
            },
        [51006110] = {
            ["Camera"] = "78.202087,-48.859863,118.763184,0.000051,-12.200288,-36.19857,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼，你的疙瘩脑袋总算转过弯了，那么先让我来和探险家皎皎前辈解释一下发生了什么。",
            ["ContentJP"] = "へん、やっと理解したかアホチンサイダー。それじゃあ、スノウから探検家のお姉さんに事情を説明しちゃうね。",
            ["DialogueId"] = 51006110,
            ["GUID"] = "7FB03DEC",
            ["NextDialogue"] = 51006111,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Confident_Start",
                [2] = "700145:Talk03_End",
                },
            },
        [51006111] = {
            ["Camera"] = "46.114136,38.984375,117.397705,0.000007,10.999807,-124.000984,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（白张牙舞爪地比划了奥特赛德对于旧小队名的喜爱，以及通过靠身手来统一意见的打算。）",
            ["ContentJP"] = "（アウトサイダーが元のチーム名に思い入れがあることや運動神経の勝負でチーム名を決めることを、スノウは身振り手振りで説明した）",
            ["DialogueId"] = 51006111,
            ["GUID"] = "7FB03E16",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51006112,
            },
        [51006112] = {
            ["Content"] = "喔，我明白了，是用那个挑战来决定啊，那我是不会输的！",
            ["ContentJP"] = "あーわかったぞ。あのチャレンジで決めるのか。だったら俺の楽勝だな。",
            ["DialogueId"] = 51006112,
            ["GUID"] = "7FB03E40",
            ["NextDialogue"] = 51006113,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Angry01_Start",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006113] = {
            ["Camera"] = "-107.990723,-296.696289,204.89624,0.000065,-19.999907,67.198593,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你确实是挑战次数最多的几个人之一，但{nickname}应该没有见过我设下的挑战，让我来说明一下。",
            ["ContentJP"] = "たしかにサイトアウダーくんは何度も挑戦したことがあるが、{nickname}はまだあのチャレンジのルールを知らないだろう。まずは私から説明しよう。",
            ["DialogueId"] = 51006113,
            ["GUID"] = "7FB03E6A",
            ["NextDialogue"] = 51006114,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Angry01_End",
                [2] = "700146:Agree",
                },
            },
        [51006114] = {
            ["Camera"] = "18.039185,-278.991699,158.917725,0.000157,-13.200044,68.989624,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "简单来说呢，我之所以会对狩月人这么熟悉，是因为我会观察各位的身手，再记录下来。",
            ["ContentJP"] = "簡単に言うと、私は月狩り人の実力を観察し、記録するためにいろいろなチャレンジを用意しているのだ。",
            ["DialogueId"] = 51006114,
            ["GUID"] = "7FB03E94",
            ["NextDialogue"] = 51006115,
            ["SpeakNpcId"] = 700146,
            ["TurnTo"] = {
                [1] = "700146:n(100001)",
                },
            },
        [51006115] = {
            ["Camera"] = "61.417114,-123.797852,85.32666,0.0,0.0,86.990524,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但狩月人这么多，并且在他们执行委托时跟在后面也很危险，所以我就找了一个帮手——一位年长的，令人尊敬的，但是长得和你有些像的铁匠。",
            ["ContentJP"] = "しかし月狩り人は大勢いるし、依頼をこなす彼らについて行くのも危険がともなう。だから助っ人を頼んだのだ。皆から尊敬される年長者で、どこかきみに似ているところもある鍛冶師だ。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51006115,
            ["GUID"] = "7FB03EBE",
            ["NextDialogue"] = 51006116,
            ["Scripts"] = "SEQ{TurnTo{_delay{4},TurnToDescription{\"700146:n(700144)\"}},CameraMoveTo{_delay{1},TargetPosition{\"54.903625,146.320801,86.79541,0.000006,0.0,-72.008141,28.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{TargetPosition{\"59.0,148.0,86.79541,0.000006,0.0,-72.008102,28.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006116] = {
            ["Camera"] = "123.392273,2.931152,85.919922,0.000078,0.0,-60.200184,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "难道你说的是铁匠皎皎前辈？我们认识她呀！",
            ["ContentJP"] = "もしかしてルーナ族の鍛冶師のおばあちゃんのこと？",
            ["DialogueId"] = 51006116,
            ["GUID"] = "7FB03EE8",
            ["NextDialogue"] = 51006117,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Agree",
                },
            },
        [51006117] = {
            ["Camera"] = "245.083435,-275.051758,86.080566,0.0,0.0,113.398293,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，认识的话就好说了，你们应该见过她的手艺。",
            ["ContentJP"] = "知り合いなら話がはやい。彼女の腕前は知っているだろう。",
            ["DialogueId"] = 51006117,
            ["GUID"] = "7FB03F12",
            ["NextDialogue"] = 51006118,
            ["SpeakNpcId"] = 700146,
            },
        [51006118] = {
            ["Camera"] = "-36.301025,308.482422,2046.960449,0.000022,-8.399964,-137.801437,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我拜托她做了一个魔法小玩意，能够在各个地方留下记号。那个记号只要被人碰一下，就会显出一段文字，也能记录下附近的人的行动。",
            ["ContentJP"] = "彼女に頼んで、いろいろな場所に「印」を残せる魔法の道具を作ってもらったのだ。その印に触れると文字が浮かび上がり、付近にいる人の行動を記録する。",
            ["DialogueId"] = 51006118,
            ["FinalCamera"] = "78.561584,181.818848,2047.960449,0.000022,-8.399964,-137.801376,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB03F3C",
            ["NextDialogue"] = 51006119,
            ["SpeakNpcId"] = 700146,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51006119] = {
            ["Camera"] = "-317.315186,330.895508,307.277344,0.000049,-21.599884,-50.999966,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要是有人完成了文字要求的行动，就算是完成了挑战。要是结果足够好，就可以在我这里拿到一些报酬。所以说，我是最清楚怎么摸清狩月人身手的了。",
            ["ContentJP"] = "文字の指示にしたがって行動すればチャレンジ完了だ。優れた成績には報酬も用意してあるぞ。つまり、私は月狩り人の運動神経を見極める方法を熟知しているのだ。",
            ["DialogueId"] = 51006119,
            ["GUID"] = "7FB03F66",
            ["NextDialogue"] = 51006120,
            ["SpeakNpcId"] = 700146,
            },
        [51006120] = {
            ["Camera"] = "68.506897,3.594238,109.754639,0.000018,13.999626,-134.600388,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我可太熟悉这些挑战了，小个子这下失算了，我都不知道怎么输。",
            ["ContentJP"] = "白いチビの計画は失敗だな。あのチャレンジならもう慣れっこだ、俺が負けるはずがない。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 51006120,
            ["GUID"] = "7FB03F90",
            ["NextDialogue"] = 51006121,
            ["Scripts"] = "PlayAnimation{_delay{1},ActorId{700145},AnimationId{\"Disagree\"},Duration{2}}",
            ["SpeakNpcId"] = 700145,
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006121] = {
            ["Camera"] = "-17.909668,-172.834961,149.789795,0.000038,-17.999323,66.400116,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你先冷静一下，我只看最后的挑战结果。那么如果这位{nickname}{性别：小兄弟|小姑娘}也没问题的话，就来这里找我吧。",
            ["ContentJP"] = "それはどうかな、結果がすべてだ。{nickname}{性别:くん|ちゃん}、準備ができたら私に声をかけてくれたまえ。",
            ["DialogueId"] = 51006121,
            ["GUID"] = "7FB03FBA",
            ["NextDialogue"] = 51006122,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Disagree\"},Duration{2}},LookAt{LookAtDescription{\"700146:n(100001)\"}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006122] = {
            ["Camera"] = "68.506897,3.594238,109.754639,0.000018,13.999626,-134.600388,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（探险家皎皎掏出笔，在你手中的冰湖城地图上做了一个标记。）",
            ["ContentJP"] = "（ルーナ族の探検家はペンを取り出し、あなたの持つアイスレイク城の地図に印をつけた）",
            ["DialogueId"] = 51006122,
            ["GUID"] = "7FB03FE4",
            ["IsBlack"] = 1,
            },
        [51006201] = {
            ["Camera"] = "100.462158,-55.870972,113.845947,0.000005,-7.000062,-90.399178,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，那么在开始之前我讲解一下规则：在我说开始之后，沿着我标记的发光圈圈一直向前就好！",
            ["ContentJP"] = "始める前にルールを確認しよう。私がスタートと言ったら、光るリングに沿って進んでいけばいい。",
            ["DialogueId"] = 51006201,
            ["GUID"] = "7FB04CDA",
            ["NextDialogue"] = 51006202,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Explain02_Start\"},Duration{2}},PlayAnimation{ActorId{700146},AnimationId{\"Explain02_End\"},Duration{1}},PARA{TurnTo{TurnToDescription{\"700146:p(90)\"}},CameraMoveTo{TargetPosition{\"365.846802,-145.875488,80.777954,0.0,0.0,-161.797287,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}},CameraMoveTo{TargetPosition{\"365.846802,-135.0,80.777954,0.0,0.0,-161.797287,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006202] = {
            ["Camera"] = "176.590088,288.807129,234.116333,0.000006,-17.800079,-96.798767,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别担心，别看那个奥特赛文那么有信心，但是我更看好你，加油加油。",
            ["ContentJP"] = "大丈夫だ。あのアウトサイブンは自信満々だが、私はきみを応援している。頑張ってくれたまえ。",
            ["DialogueId"] = 51006202,
            ["GUID"] = "7FB04D04",
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"700146:n(100001)\"}},LookAt{LookAtDescription{\"700146:n(100001)\"}},PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}}}",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Sigh_Start",
                [2] = "100001:Confident_Start",
                },
            },
        [51006301] = {
            ["Content"] = "驾轻就熟，我赢定了。",
            ["ContentJP"] = "こんなの朝飯前だっての。この勝負もらったぜ。",
            ["DialogueId"] = 51006301,
            ["Duration"] = 3,
            ["GUID"] = "7FB05D42",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006302] = {
            ["Content"] = "哎？谁往地上泼油？",
            ["ContentJP"] = "はぁ？待て待て……地面に油がまいてあるぞ！？",
            ["DialogueId"] = 51006302,
            ["Duration"] = 3,
            ["GUID"] = "7FB05D6C",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006303] = {
            ["Content"] = "不是？怎么屋顶还有狗？",
            ["ContentJP"] = "いや待て待て……屋上に犬がいるとか聞いてねぇぞ？",
            ["DialogueId"] = 51006303,
            ["Duration"] = 3,
            ["GUID"] = "7FB05D96",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 51006304,
            ["SpeakNpcId"] = 700145,
            },
        [51006304] = {
            ["Content"] = "汪汪——",
            ["ContentJP"] = "ガルル……ワンワン！",
            ["DialogueId"] = 51006304,
            ["Duration"] = 2,
            ["GUID"] = "7FB05DC0",
            ["SpeakNpcName"] = "UI_Npc_Name_Dog",
            },
        [51006305] = {
            ["Content"] = "刚刚是发挥失常了吧，别着急，再来一次，我相信你！",
            ["ContentJP"] = "さっきは調子がいまいちだったかな？もう一度チャレンしてごらん。大丈夫、きみならできる！",
            ["DialogueId"] = 51006305,
            ["Duration"] = 3,
            ["GUID"] = "7FB05DEA",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700146,
            },
        [51006401] = {
            ["Content"] = "哦，{nickname}身手不错嘛，那么我们现在去进行第二场测试，跟着我来。",
            ["ContentJP"] = "なかなかの腕前だな、{nickname}。では次のチャレンジに移ろう。ついて来てくれたまえ。",
            ["DialogueId"] = 51006401,
            ["Duration"] = 3,
            ["GUID"] = "7FB06DAA",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 51006402,
            ["SpeakNpcId"] = 700146,
            },
        [51006402] = {
            ["Content"] = "奥德特赛也抓紧赶上，不要跟丢了。",
            ["ContentJP"] = "アウダーサイくんも遅れないように、急ぎたまえ。",
            ["DialogueId"] = 51006402,
            ["Duration"] = 2,
            ["GUID"] = "7FB06DD4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700146,
            },
        [51006501] = {
            ["Camera"] = "190.745117,183.455322,84.877686,0.000011,0.0,-90.395432,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这一个测试的规则也很简单：我说开始后，面前会出现我拜托铁匠皎皎前辈做的气球。",
            ["ContentJP"] = "このルールも簡単だ。私がスタートと言ったら、鍛冶師が作った風船が現れる。",
            ["DialogueId"] = 51006501,
            ["GUID"] = "7FB07E12",
            ["NextDialogue"] = 51006502,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700146},AnimationId{\"Agree\"},Duration{2}},PARA{TurnTo{TurnToDescription{\"700146:p(-90)\"}},CameraMoveTo{TargetPosition{\"-135.275879,-75.0,84.279785,0.000003,0.0,-0.597107,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}},CameraMoveTo{TargetPosition{\"-135.275879,-63.0,84.279785,0.000003,0.0,-0.597107,35.0,100000.0,false,DoNotOverride,2.8\"},duration{3}}}",
            ["SpeakNpcId"] = 700146,
            },
        [51006502] = {
            ["Camera"] = "485.306641,-103.10376,80.212891,0.000003,0.0,-177.99791,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "瞄准，然后打爆它就好！",
            ["ContentJP"] = "それを狙い撃ちしてくれたまえ。",
            ["DialogueId"] = 51006502,
            ["GUID"] = "7FB07E3C",
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Confident_Start",
                },
            },
        [51006601] = {
            ["Content"] = "奇怪了，我的子弹呢？",
            ["ContentJP"] = "ん？俺の弾はどこだ……",
            ["DialogueId"] = 51006601,
            ["Duration"] = 2,
            ["GUID"] = "7FB08E7A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006602] = {
            ["Content"] = "……可恶，刚刚手上沾了油，装弹好麻烦。",
            ["ContentJP"] = "……チッ、手が油で滑ってうまく装填できねえ。",
            ["DialogueId"] = 51006602,
            ["Duration"] = 2,
            ["GUID"] = "7FB08EA4",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700145,
            },
        [51006603] = {
            ["Content"] = "别装弹了，{nickname}已经完成测试了。",
            ["ContentJP"] = "もう装填する必要はないぞ。{nickname}がチャレンジを完了しているからな。",
            ["DialogueId"] = 51006603,
            ["Duration"] = 2,
            ["GUID"] = "7FB08ECE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700146,
            },
        [51006701] = {
            ["Camera"] = "-20.024414,-347.564941,170.543701,0.000067,-13.199791,66.207527,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "恭喜你，{nickname}，我的眼光没错，你是一位潜力十足的狩月人。",
            ["ContentJP"] = "おめでとう、{nickname}。私の目に狂いはなかった。きみは潜在能力の高い月狩り人だ。",
            ["DialogueId"] = 51006701,
            ["GUID"] = "7FB09EE2",
            ["LookAt"] = {
                [1] = "100001:n(700146)",
                [2] = "700144:n(700146)",
                [3] = "700145:n(700146)",
                [4] = "700146:n(100001)",
                },
            ["NextDialogue"] = 51006702,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Agree",
                },
            },
        [51006702] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，按照之前的约定，新的小队名字，就由你来取啦！奥特赛德，你有意见吗？",
            ["ContentJP"] = "ふふん、約束通り新しいチーム名は{nickname}が決めるってことでアウトサイダーも文句ないよね？",
            ["DialogueId"] = 51006702,
            ["GUID"] = "7FB09F0C",
            ["NextDialogue"] = 51006703,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{700144},AnimationId{\"Confident_Start\"},Duration{2}},LookAt{_delay{2},LookAtDescription{\"700144:n(700145)\"}}}",
            ["SpeakNpcId"] = 700144,
            },
        [51006703] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我抗议！你们一定是在针对我！",
            ["ContentJP"] = "異議あり！お前ら俺を妨害しやがったな！",
            ["DialogueId"] = 51006703,
            ["GUID"] = "7FB09F36",
            ["NextDialogue"] = 51006704,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Sigh_Start",
                },
            },
        [51006704] = {
            ["Camera"] = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么可能，我是专业的狩月人能力记录者，不会偏袒谁，也不会针对谁。",
            ["ContentJP"] = "まさか。私は月狩り人の能力を冷静かつ客観的に記録する者だ。誰かをひいきしたり、妨害するなんてありえない。",
            ["DialogueId"] = 51006704,
            ["GUID"] = "7FB09F60",
            ["LookAt"] = {
                [1] = "700146:n(700145)",
                },
            ["NextDialogue"] = 51006705,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Sigh_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(700145)",
                },
            },
        [51006705] = {
            ["Camera"] = "64.692383,-137.981445,87.32666,0.0,0.0,87.390518,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "除非……",
            ["ContentJP"] = "ただし……",
            ["DialogueId"] = 51006705,
            ["GUID"] = "7FB09F8A",
            ["NextDialogue"] = 51006706,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_Start",
                },
            },
        [51006706] = {
            ["Camera"] = "11.383789,132.50415,88.602051,0.000028,2.199956,-70.207726,28.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "除非？",
            ["ContentJP"] = "ただし？",
            ["DialogueId"] = 51006706,
            ["GUID"] = "7FB09FB4",
            ["NextDialogue"] = 51006707,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700146:Explain02_End",
                },
            },
        [51006707] = {
            ["Camera"] = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "除非有人和这个奥特赛德一样，简直把完成挑战当成营生的手段一样！每次我新布设了一批记号，他都第一个过去挑战，再冲到我这边要报酬，坏透了！",
            ["ContentJP"] = "私の用意したチャレンジで生計を立てるなら話は別だ。そう、きみのことだ、アウトサイダー！新しい印を設置するたびに真っ先にチャレンジして報酬をねだりに来るのだから、たまったもんじゃない！",
            ["DialogueId"] = 51006707,
            ["GUID"] = "7FB09FDE",
            ["NextDialogue"] = 51006708,
            ["SpeakNpcId"] = 700146,
            },
        [51006708] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只要他去过一次的挑战，就没几个人再能超过他拿到报酬！搞得别人都不愿意参加了！所以我要让他尝一尝苦头！",
            ["ContentJP"] = "アウトサイダーの記録を超えるのは難しい、つまり報酬がもらえる望みが薄いからほかの月狩り人がチャレンジに参加してくれない……というわけで困っているのだ。アウトサイダーには一度痛い目にあってもらわなくては！",
            ["DialogueId"] = 51006708,
            ["GUID"] = "7FB0A008",
            ["LookAt"] = {
                [1] = "700145:n(700145)",
                },
            ["NextDialogue"] = 51006709,
            ["SpeakNpcId"] = 700146,
            },
        [51006709] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你报复我居然是因为这个？！还有你终于叫对我的名字了，之前是不是都是故意的？",
            ["ContentJP"] = "それで俺に報復したってか？つーかやっと俺の名前を正しく呼んでくれたな。いままではわざと間違えてたのかよ。",
            ["DialogueId"] = 51006709,
            ["GUID"] = "7FB0A032",
            ["LookAt"] = {
                [1] = "700145:n(700146)",
                },
            ["NextOptions"] = {
                [1] = 510067091,
                [2] = 510067092,
                [3] = 510067093,
                },
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{700145},AnimationId{\"Talk03_Start\"},Duration{2}}",
            ["SpeakNpcId"] = 700145,
            ["TurnTo"] = {
                [1] = "700146:n(100001)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51006710] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎呀……我又不知道你是为了收集数据什么的，还以为你就是铜币花不完，解闷呢。",
            ["ContentJP"] = "わりぃ……あんたがデータ収集のためにやってるとは知らなかったんだ。てっきり金持ちの道楽だと……",
            ["DialogueId"] = 51006710,
            ["GUID"] = "7FB0A05C",
            ["LookAt"] = {
                [1] = "700145:n(700146)",
                [2] = "700146:n(700145)",
                },
            ["NextDialogue"] = 51006711,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Talk03_End",
                },
            ["TurnTo"] = {
                [1] = "700146:n(100001)",
                },
            },
        [51006711] = {
            ["Camera"] = "-120.803711,-309.877441,224.89624,0.000075,-19.999907,68.198792,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那这下知道了吧，以后不要再第一个冲过去挑战了。",
            ["ContentJP"] = "わかってくれればいいのだ。これからは一番乗りでチャレンジするのはやめてくれたまえ。",
            ["DialogueId"] = 51006711,
            ["GUID"] = "7FB0A086",
            ["LookAt"] = {
                [1] = "700146:n(700145)",
                },
            ["NextDialogue"] = 51006717,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700146:Agree",
                },
            },
        [51006712] = {
            ["Camera"] = "-20.936523,-347.155518,172.543701,0.000068,-12.799808,66.407326,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊，抱歉把你牵连进来，但是你的挑战结果确实很厉害哦，这一点我可没有骗你。",
            ["ContentJP"] = "ああ、それについてはすまない。{nickname}を巻き込んでしまった。しかしきみのチャレンジの結果は本当に素晴らしい。それについては嘘は言っていない。",
            ["DialogueId"] = 51006712,
            ["GUID"] = "7FB0A0B0",
            ["LookAt"] = {
                [1] = "700145:n(700146)",
                [2] = "700146:n(700145)",
                },
            ["NextDialogue"] = 51006713,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700145:Talk03_End",
                [2] = "700146:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700146:n(100001)",
                },
            },
        [51006713] = {
            ["Camera"] = "263.242676,-125.993896,140.543701,0.0,0.0,-169.591751,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "确实，都快赶上我的记录了，仅次于我！",
            ["ContentJP"] = "たしかにあと少しで俺の記録に追いつきそうだな。とはいえ俺にはまだまだ敵わないが。",
            ["DialogueId"] = 51006713,
            ["GUID"] = "7FB0A0DA",
            ["NextDialogue"] = 51006714,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700146:Confident_End",
                [2] = "700145:Agree",
                },
            },
        [51006714] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我看你是被狗咬得还不够疼！",
            ["ContentJP"] = "さっきわんこに追いかけられてヒイヒイ言ってたヤツが、えっらそうに！",
            ["DialogueId"] = 51006714,
            ["GUID"] = "7FB0A104",
            ["NextDialogue"] = 51006717,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006715] = {
