            ["TurnTo"] = {
                [1] = "700146:n(100001)",
                },
            },
        [51006716] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们……我不和你们较真！",
            ["ContentJP"] = "お前らなぁ……まあいいさ、勝手に言ってろ。",
            ["DialogueId"] = 51006716,
            ["GUID"] = "7FB0A158",
            ["NextDialogue"] = 51006717,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Disagree",
                },
            },
        [51006717] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那，我们回到一开始的话题，既然是{nickname}赢了，那小队名字还是由{性别：他|她}起好啦。",
            ["ContentJP"] = "さて本題に戻るよ。{nickname}が勝ったんだから、チーム名は{nickname}が決めるってことでいいよね？",
            ["DialogueId"] = 51006717,
            ["GUID"] = "7FB0A182",
            ["LookAt"] = {
                [1] = "700144:n(700145)",
                [2] = "700145:n(700144)",
                },
            ["NextDialogue"] = 51006718,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Confident_Start",
                },
            ["TurnTo"] = {
                [1] = "700144:n(700145)",
                [2] = "700145:n(700144)",
                },
            },
        [51006718] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "行吧，行吧，我没意见。",
            ["ContentJP"] = "わかったわかった。異議なし。",
            ["DialogueId"] = 51006718,
            ["GUID"] = "7FB0A1AC",
            ["NextDialogue"] = 51006719,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700144:Confident_End",
                [2] = "700145:Agree",
                },
            },
        [51006719] = {
            ["Camera"] = "-318.093262,330.265869,317.277344,0.00005,-21.599884,-51.000023,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不过，真的不考虑一下“食用昆虫研究队”这样让人看一眼后在半夜惊醒也会想到的如惊雷一般的好名字吗！",
            ["ContentJP"] = "だがな、「食用昆虫研究隊」ってマジでかっこいいと思わないか？夜中にふと思い出してゾッとするようなインパクトがあってさ。",
            ["DialogueId"] = 51006719,
            ["GUID"] = "7FB0A1D6",
            ["NextDialogue"] = 51006720,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700145:Think_Start",
                [2] = "100001:Sigh_Start",
                },
            },
        [51006720] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我不觉得！我还是觉得什么“光之魔王见习小队“这样的名字更能吸引人！",
            ["ContentJP"] = "だーめーーー！やっぱり「光の魔王様見習い小隊」とかのほうが依頼人の心を掴むと思うよ！",
            ["DialogueId"] = 51006720,
            ["GUID"] = "7FB0A200",
            ["NextDialogue"] = 51006721,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Disagree",
                },
            },
        [51006721] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那……“光之魔王的食用昆虫研究见习小队”？",
            ["ContentJP"] = "だったら……「光の魔王様の食用昆虫研究見習い小隊」はどうだ？",
            ["DialogueId"] = 51006721,
            ["GUID"] = "7FB0A22A",
            ["NextDialogue"] = 51006722,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            },
        [51006722] = {
            ["Camera"] = "70.664551,-61.835938,124.763184,0.000051,-13.200255,-30.598364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……昆虫还是很显眼，那“真·纯白地狱之极光大魔王的昆虫研究见习小队”？",
            ["ContentJP"] = "うーん……まだ昆虫が目立つなぁ。じゃあ「真・純白地獄の極光大魔王様の昆虫研究見習い小隊」は？",
            ["DialogueId"] = 51006722,
            ["GUID"] = "7FB0A254",
            ["NextDialogue"] = 51006723,
            ["SpeakNpcId"] = 700144,
            ["TalkActionId"] = {
                [1] = "700144:Talk03_Start",
                [2] = "700145:Think_End",
                },
            },
        [51006723] = {
            ["Camera"] = "73.404785,8.581055,112.754639,0.000019,13.999578,-134.799911,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "魔王的部分太多了！依我看不如“伪·纯白地狱之极光大魔王的六足有翅小动物的九十九种美味烹饪法研究见习小队”？",
            ["ContentJP"] = "魔王の肩書きが長すぎるだろ。「偽・純白地獄の極光大魔王様の6本足4枚翅生物のレシピ99種類研究見習い小隊」のほうがいいと思うぞ。",
            ["DialogueId"] = 51006723,
            ["GUID"] = "7FB0A27E",
            ["NextDialogue"] = 51006724,
            ["SpeakNpcId"] = 700145,
            ["TalkActionId"] = {
                [1] = "700144:Talk03_End",
                [2] = "700145:Angry01_Start",
                },
            },
        [51006724] = {
            ["Camera"] = "-20.024414,-347.564941,170.543701,0.000067,-13.199791,66.207527,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他们俩在一起犯蠢，正好给你考虑的时间。虽然好像有很多人在给小队起名的时候会犹豫非常久，不过，我的建议是，遵从内心就好。",
            ["ContentJP"] = "あのふたりが馬鹿話をしている隙にチーム名を決めてしまおう。あれこれと悩む人が多いが、自分の心の声に素直に従うのが一番だぞ。",
            ["DialogueId"] = 51006724,
            ["GUID"] = "7FB0A2A8",
            ["LookAt"] = {
                [1] = "700146:n(100001)",
                },
            ["NextDialogue"] = 51006725,
            ["SpeakNpcId"] = 700146,
            ["TalkActionId"] = {
                [1] = "700144:Angry01_Start",
                [2] = "700146:Explain02_Start",
                },
            },
        [51006725] = {
