            ["SpeakNpcId"] = 700146,
            },
        [51006734] = {
            ["Content"] = "“夜航者”……嗯，好名字！要是人人都像你们一样，这块看板就不会不够写了……",
            ["ContentJP"] = "「ノクトボイジャー」か……うん、いい名前だ！ ほかのチーム名もこれくらいシンプルだったら、掲示板のスペースが足りなくなる心配はないのだが……",
            ["DialogueId"] = 51006734,
            ["GUID"] = "7FB0A44C",
            ["LookAt"] = {
                [1] = "700143:n(0)",
                },
            ["NextDialogue"] = 51006735,
            ["SpeakNpcId"] = 700143,
            ["TalkActionId"] = {
                [1] = "700143:Explain01_Start",
                },
            ["TurnTo"] = {
                [1] = "700143:n(0)",
                },
            },
        [51006735] = {
            ["Content"] = "加油，加油，把那些又长又拗口的名字挤下去。",
            ["ContentJP"] = "応援しているぞ。君たちのチーム名であの長ったらしくてややこしいチーム名をランキング上位から追い払ってくれ。",
            ["DialogueId"] = 51006735,
            ["GUID"] = "7FB0A476",
            ["SpeakNpcId"] = 700143,
            ["TalkActionId"] = {
                [1] = "700143:Explain01_End",
                },
            },
        }
  end },
