        [51006807] = {
            ["Camera"] = "-122.856445,-382.609375,156.415039,0.000195,-5.601042,76.061539,80.0,1.5,false,Disable,1.2",
            ["Content"] = "你好，孩子。我是一名漂泊的雾海引渡人——或者，如果你更喜欢以姓名相称，也可以称呼我为妮弗尔夫人。",
            ["ContentJP"] = "こんにちは、{性别:坊や|お嬢さん}。私は漂泊するニブルヘイムの導き手——名前で呼びたいなら、ニフル夫人と呼んでね。",
            ["DialogueId"] = 51006807,
            ["GUID"] = "7FB0B046",
            ["LookAt"] = {
                [1] = "700133:n(100001)",
                },
            ["NextDialogue"] = 51006808,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Think_End",
                },
            ["TurnTo"] = {
                [1] = "700133:n(100001)",
                },
            },
        [51006808] = {
            ["Content"] = "我听见此处彷徨灵魂的絮语，因此前来指引“她”回归雾海。",
            ["ContentJP"] = "ここで彷徨う魂のささやきを聞いたから、「彼女」をニブルヘイムに導くために来たの。",
            ["DialogueId"] = 51006808,
            ["GUID"] = "7FB0B070",
            ["NextDialogue"] = 51006809,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Explain02_Start",
                },
            },
        [51006809] = {
            ["Content"] = "彷徨的灵魂？",
            ["ContentJP"] = "彷徨う魂？",
            ["DialogueId"] = 51006809,
            ["GUID"] = "7FB0B09A",
            ["NextDialogue"] = 51006810,
            ["SpeakNpcId"] = 100001,
            },
        [51006810] = {
