            ["SpeakNpcId"] = 100001,
            },
        [51006812] = {
            ["Content"] = "我的双眼能看到灵魂所思之物。",
            ["ContentJP"] = "私の目は、魂の思いを映し出せるから。",
            ["DialogueId"] = 51006812,
            ["GUID"] = "7FB0B118",
            ["NextDialogue"] = 51006813,
