            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Agree",
                },
            },
        [51006813] = {
            ["Content"] = "方才，在引导她归去之时，我看到了她牵念的一切，其中便有你的身影。",
            ["ContentJP"] = "さっき、彼女を送り出す時に、彼女が大切に想っていたすべてのものを見たわ。そのなかにあなたの姿もあったの。",
