        [51006823] = {
            ["Camera"] = "-147.616211,-244.476562,75.759766,0.000265,7.39762,69.851921,80.0,318.95755,false,Manual,11.670671",
            ["Content"] = "孩子，我已经在这世上活了很久、很久，送别了无数的亡魂，也曾无数次听过这样的话语。",
            ["ContentJP"] = "{性别:坊や|お嬢さん}、私はこの世界で長い、本当に長い時を生きてきたわ。無数の魂を見送り、何度もそんな言葉を聞いてきたの。",
            ["DialogueId"] = 51006823,
            ["FinalCamera"] = "-147.616211,-244.476562,78.396484,0.000265,7.39762,69.851921,80.0,318.95755,false,Manual,11.670671",
            ["GUID"] = "7FB0B2E6",
            ["NextDialogue"] = 51006824,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006824] = {
            ["Camera"] = "-2590.543945,-1518.859375,933.94043,0.000426,-19.601589,29.648626,18.0,318.95755,false,Disable,11.670671",
            ["Content"] = "草木会因一场山火而化作焦土，虫豸会因一阵狂风而溺于深水……无常本就是生命的一部分。或早或晚，死亡终将来临。",
            ["ContentJP"] = "草木は一つの山火事で焦土と化し、虫は一陣の嵐で深い水に溺れる……無常は生命そのものの一部。いつか、死は必ず訪れるものだから。",
            ["DialogueId"] = 51006824,
            ["FinalCamera"] = "-2618.442383,-1534.75,945.375,0.000426,-19.601589,29.648626,18.0,318.95755,false,Disable,11.670671",
            ["GUID"] = "7FB0B310",
            ["LookAt"] = {
                [1] = "700133:p(200218510060P2)",
                },
            ["NextDialogue"] = 51006825,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51006825] = {
            ["Camera"] = "-100.15625,166.824219,62.766602,0.000582,37.387058,-69.136719,18.0,318.95755,false,Disable,11.670671",
            ["Content"] = "除了诅咒命运的冷漠与残酷，或是哀叹自我的无力与渺小，我们还可以选择……珍惜切实拥有的回忆。",
            ["ContentJP"] = "運命の冷酷と残酷を呪うこともできるし、自らの無力を嘆くこともできる。でもね、別の選択もあるの……思い出を大切にすること。",
            ["DialogueId"] = 51006825,
            ["FinalCamera"] = "-100.15625,166.824219,58.511719,0.000582,37.387058,-69.136719,18.0,318.95755,false,Disable,11.670671",
            ["GUID"] = "7FB0B33A",
            ["NextDialogue"] = 51006826,
            ["Scripts"] = "CameraMoveTo{_delay{3.1},TargetPosition{\"-116.790039,-32.921875,80.651367,0.000596,20.386126,46.463051,50.0,318.95755,false,Disable,11.670671\"},duration{0}}",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 3,
            },
        [51006826] = {
            ["Camera"] = "-112.657227,-317.488281,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
            ["Content"] = "毕竟，如果说死亡是“必然”，那么活着的每一日，不正是与它擦肩而过的“奇迹”吗？",
            ["ContentJP"] = "だって、死が「必然」なら、生きている毎日は、その必然とすれ違う「奇跡」じゃない？",
            ["DialogueId"] = 51006826,
            ["FinalCamera"] = "-108.74707,-318.570312,141.492188,0.000272,-5.401217,74.453423,50.0,406.774475,false,Manual,11.670671",
            ["GUID"] = "7FB0B364",
            ["LookAt"] = {
                [1] = "700133:n(100001)",
                },
            ["NextDialogue"] = 51006827,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006827] = {
            ["Camera"] = "-108.535156,-156.035156,123.041016,0.000277,-1.200986,70.850563,50.0,262.367676,false,Manual,11.670671",
            ["Content"] = "我想，去往了雾海的那个灵魂，也一定会希望……当你回忆起与她共同经历的时日，你是面带笑意的，而非哀怜和悲泣。",
            ["ContentJP"] = "ニブルヘイムへと去った魂は、願うのではないかしら……あなたが彼女と共に過ごした日々を思い出すとき、哀しみや悲しみではなく、ほほ笑みを浮かべてほしいと。",
            ["DialogueId"] = 51006827,
            ["GUID"] = "7FB0B38E",
            ["NextOptions"] = {
                [1] = 51006828,
                },
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Give",
                },
            },
        [51006828] = {
            ["Content"] = "“雾海”到底是什么地方？",
            ["ContentJP"] = "ニブルヘイムって……どんなところ？",
            ["DialogueId"] = 51006828,
            ["GUID"] = "7FB0B3B8",
            ["NextDialogue"] = 51006829,
            },
        [51006829] = {
            ["Camera"] = "-95.244141,-1.792969,77.727539,0.000237,25.99535,65.250359,18.0,262.367676,false,Disable,11.670671",
            ["Content"] = "雾海……是卡戎之民的生命之源，亦是安眠之地。亡者的灵魂回归雾海，生者的灵魂从中诞生。生命如此循环流转，生生不息。",
            ["ContentJP"] = "ニブルヘイム…それはカロン族の生命の源であり、安らぎの地。亡き人の魂はニブルヘイムに帰り、生きる者の魂はそこから生まれる。命は、こうして果てしなく循環しているの。",
            ["DialogueId"] = 51006829,
            ["FinalCamera"] = "-100.587891,0.652344,77.727539,0.000236,25.99535,65.250565,18.0,262.367676,false,Disable,11.670671",
            ["GUID"] = "7FB0B3E2",
            ["NextDialogue"] = 51006830,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006830] = {
            ["Camera"] = "-111.96875,-162.601562,135.374023,0.000258,6.394546,-70.962959,27.0,262.367676,false,Disable,11.670671",
            ["Content"] = "如果是那样……",
            ["ContentJP"] = "もしそれが本当ならば……",
            ["DialogueId"] = 51006830,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "7FB0B40C",
            ["NextDialogue"] = 51006831,
            ["NextOptions"] = {
                [1] = 51006831,
                [2] = 51006832,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51006831] = {
            ["Content"] = "我能去雾海把她带回来吗？",
            ["ContentJP"] = "ニブルヘイムに行って、彼女を連れ戻せるかな？",
            ["DialogueId"] = 51006831,
            ["GUID"] = "7FB0B436",
            ["NextDialogue"] = 51006833,
            },
        [51006832] = {
            ["Content"] = "她还会回到我身边吗？",
            ["ContentJP"] = "彼女はまた、私のそばに戻ってくるのかな？",
            ["DialogueId"] = 51006832,
            ["GUID"] = "7FB0B460",
            ["NextDialogue"] = 51006833,
            },
        [51006833] = {
            ["Camera"] = "-792.569336,-40.027344,85.155273,0.000242,-0.205042,-2.348938,18.000004,262.367676,false,Disable,11.670671",
            ["Content"] = "（妮弗尔夫人没有立刻回答。她抬起那双满含温柔与悲悯的眼眸，静静地看着你，半晌之后才再度开口——）",
            ["ContentJP"] = "（ニフル夫人はすぐには答えない。温かさと哀れみに満ちた瞳で、じっと見つめて。やがて、ゆっくりと口を開く）",
            ["DialogueId"] = 51006833,
            ["FinalCamera"] = "-809.700195,-39.3125,85.211914,0.000242,-0.205042,-2.348938,18.000004,262.367676,false,Disable,11.670671",
            ["GUID"] = "7FB0B48A",
            ["NextDialogue"] = 51006834,
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006834] = {
            ["Camera"] = "-134.571289,-64.273438,162.016602,0.000233,-12.205288,51.838001,50.0,262.367676,false,Disable,11.670671",
            ["Content"] = "如果向我提问的是别人，我应当会如此回答：生与死的循环是不容违背的世界法则，凭人类的力量绝对无法与之抗衡。",
            ["ContentJP"] = "もし別の誰かが聞いたら、こう答えるわ。「生と死の循環は、逆らえない世界の掟。人間の力では、絶対に変えられない」って。",
            ["DialogueId"] = 51006834,
            ["FinalCamera"] = "-136.608398,-62.683594,162.016602,0.000234,-12.205288,51.838234,50.0,262.367676,false,Disable,11.670671",
            ["GUID"] = "7FB0B4B4",
            ["NextDialogue"] = 51006835,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006835] = {
            ["Camera"] = "-57.59375,207.816406,103.970703,0.000219,3.798521,-89.331329,80.0,445.659943,false,Manual,22.0",
            ["Content"] = "不过，孩子，我能感受得到……你背负着不同寻常的命运。",
            ["ContentJP"] = "でも、{性别:坊や|お嬢さん}。あなたの背負っているものは、普通じゃないって感じるわ。",
            ["DialogueId"] = 51006835,
            ["GUID"] = "7FB0B4DE",
            ["NextDialogue"] = 51006836,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006836] = {
            ["Camera"] = "-128.890625,-402.097656,132.947266,0.000231,-1.40176,75.0606,80.0,445.659943,false,Manual,22.0",
            ["Content"] = "有朝一日，当你获得了足够强大的力量——当你能够直面世界的真相，甚至打破构筑它的法则本身……或许，通向雾海之河亦会为你倒流。",
            ["ContentJP"] = "いつか、あなたが十分な力を手に入れた時——世界の本当の姿に向きあって、その掟さえも変えられるほどの力を得たら……ニブルヘイムへの道は、あなたのために逆流するかもしれない。",
            ["DialogueId"] = 51006836,
            ["FinalCamera"] = "-125.893555,-402.882812,132.947266,0.000233,-1.40176,75.060074,80.0,445.659943,false,Manual,22.0",
            ["GUID"] = "7FB0B508",
            ["LookAt"] = {
                [1] = "700133:p(200218510060P2)",
                },
            ["NextOptions"] = {
                [1] = 51006837,
                },
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["ToFinalCameraBlendTime"] = 6,
            },
        [51006837] = {
            ["Content"] = "你的意思是……？！",
            ["ContentJP"] = "つまり…！",
            ["DialogueId"] = 51006837,
            ["GUID"] = "7FB0B532",
            ["NextDialogue"] = 51006838,
            },
        [51006838] = {
            ["Camera"] = "-239.978516,-66.265625,99.682617,0.000237,6.198123,33.460938,80.000008,264.973846,false,Manual,22.0",
            ["Content"] = "呵呵……我不过是驻于河畔的一介旁观者。这个问题的答案，只能由你自己寻得。",
            ["ContentJP"] = "ふふっ……私は川べりの、ただの見物人に過ぎないわ。その答えは、あなた自身で見つけるしかないもの。",
            ["DialogueId"] = 51006838,
            ["GUID"] = "7FB0B55C",
            ["LookAt"] = {
                [1] = "700133:n(100001)",
                },
            ["NextDialogue"] = 51006839,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006839] = {
            ["Camera"] = "-142.427734,-464.648438,180.995117,0.000256,-7.402442,75.056717,80.000008,411.46283,false,Disable,22.0",
            ["Content"] = "如果你真的心怀渴望，那么，就请继续前进吧。",
            ["ContentJP"] = "本当に望んでいるなら、前に進み続けてね。",
            ["DialogueId"] = 51006839,
            ["GUID"] = "7FB0B586",
            ["NextDialogue"] = 51006840,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Agree",
                },
            },
        [51006840] = {
            ["Content"] = "一路顺风，亲爱的孩子。",
            ["ContentJP"] = "大切な{性别:坊や|お嬢さん}、良い旅を。",
            ["DialogueId"] = 51006840,
            ["GUID"] = "7FB0B5B0",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            ["TalkActionId"] = {
                [1] = "700133:Give",
                },
            },
        [51006841] = {
            ["Content"] = "孩子，纵是前路无常，也请你坚定地走下去吧。",
            ["ContentJP"] = "{性别:坊や|お嬢さん}、行く手が不確かででも、どうかその道を歩み続けてね。",
            ["DialogueId"] = 51006841,
            ["GUID"] = "7FB0B5DA",
            ["NextDialogue"] = 51006842,
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006842] = {
            ["Content"] = "愿母神茵布拉赐福于你。",
            ["ContentJP"] = "母なる神エムブラの祝福を。",
            ["DialogueId"] = 51006842,
            ["GUID"] = "7FB0B604",
            ["SpeakNpcId"] = 700133,
            ["SpeakNpcName"] = "UI_Npc_Name_Nifu",
            },
        [51006901] = {
            ["Camera"] = "475.811523,676.893555,129.602295,0.000004,0.0,-119.200165,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（列车售票亭吸引了你的注意：你回忆起从玛尔洁那里得到的“货物”，它们中的某一个似乎与“车票”有关。）",
            ["ContentJP"] = "（列車の切符売り場が目に入る：マギーから受け取った「もの」のことを思い出す。その中の一つが「切符」に関係しているようだ）",
            ["DialogueId"] = 51006901,
            ["FinalCamera"] = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FB0BFB2",
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                [2] = "700148:n(700147)",
                },
            ["NextDialogue"] = 51006902,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51006902] = {
            ["Camera"] = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（你来得不凑巧，一个异国打扮的卡戎之民与售票员起了冲突。）",
            ["ContentJP"] = "（ついたところ、異国風の装いをしたカロン族と切符売りが争っている）",
            ["DialogueId"] = 51006902,
            ["GUID"] = "7FB0BFDC",
            ["NextDialogue"] = 51006903,
            ["TalkActionId"] = {
                [1] = "700147:Confident_Start",
                [2] = "100001:Think_End",
                },
            },
        [51006903] = {
            ["Camera"] = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没钱就滚开！",
            ["ContentJP"] = "金がないなら出て行け！",
            ["DialogueId"] = 51006903,
            ["GUID"] = "7FB0C006",
            ["NextDialogue"] = 51006904,
            ["SpeakNpcId"] = 700147,
            },
        [51006904] = {
            ["Camera"] = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "天呐，我只想一问！你为何狂躁！",
            ["ContentJP"] = "ちょっと待つくれ、ただ聞くたいだけだ、そんなに怒りことはないだろう！",
            ["DialogueId"] = 51006904,
            ["GUID"] = "7FB0C030",
            ["NextDialogue"] = 51006905,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Confident_End",
                [2] = "700148:Shock_Start",
                },
            },
        [51006905] = {
            ["Camera"] = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦好的，这位怪腔怪调的穷鬼先生，在我礼貌地告诉你票价后，你打算怎么做？搓搓自己漏不出一个子儿的破口袋对我颐指气使？",
            ["ContentJP"] = "おやおや、この変な口調の貧乏人さん、私が丁寧に切符の値段を教えたらどうするつもり？金のない破れたポケットをこすりながら私に命令するつもりなの？",
            ["DialogueId"] = 51006905,
            ["GUID"] = "7FB0C05A",
            ["NextDialogue"] = 51006906,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Talk03_Start",
                [2] = "700148:Shock_End",
                },
            },
        [51006906] = {
            ["Camera"] = "33.833008,-38.410156,159.227783,0.00001,0.999987,101.202133,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你在讲什么？你怎知我没——",
            ["ContentJP"] = "何を言いてるんだ？私が持ってないとでも——",
            ["DialogueId"] = 51006906,
            ["GUID"] = "7FB0C084",
            ["NextDialogue"] = 51006907,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Explain01_Start",
                [2] = "700147:Talk03_End",
                },
            },
        [51006907] = {
            ["Camera"] = "8.34668,69.227539,155.484863,0.000015,-7.799837,-93.597458,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "知道什么？卡戎人兜里能有几个铜币？这里只属于富豪、贵族和高官，不欢迎穷光蛋！",
            ["ContentJP"] = "何が分かるって？カロン族にはいくら持っている？ここは金持ち、貴族、高官の場所で、貧乏人はお断りよ！",
            ["DialogueId"] = 51006907,
            ["GUID"] = "7FB0C0AE",
            ["NextDialogue"] = 51006908,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700148:Explain01_End",
                [2] = "700147:Confident_Start",
                },
            },
        [51006908] = {
            ["Camera"] = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（异国人哆嗦着嘴唇，改换某种方言加以反击，然而什么也没听懂的售票员轻蔑地看了他一眼，不再理他，商人自讨没趣，悻悻离去。）",
            ["ContentJP"] = "（異国人が唇を震わせながら変な言葉で反撃したが、何も理解できなかった切符売りには通じず、軽蔑の目で見られて無視された。商人は自分が恥をかいたと感じ、悄然として立ち去る）",
            ["DialogueId"] = 51006908,
            ["GUID"] = "7FB0C0D8",
            ["Scripts"] = "PARA{MoveTo{_delay{2},ActorId{700148},MoveSpeed{75},TargetPoint{\"QuestPoint_20021901Move\"}},CameraMoveTo{_delay{2},TargetPosition{\"479.638672,673.591797,127.602295,0.000004,-0.600005,-125.400406,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
            },
        [51006921] = {
            ["Content"] = "看你白白净净的，怎么也跟兄弟抢垃圾啊？",
            ["ContentJP"] = "おいおい、そんなきれいな顔して、まさかゴミ漁りに来たんじゃないだろうな？",
            ["DialogueId"] = 51006921,
            ["GUID"] = "7FB0C0D9",
            ["NextOptions"] = {
                [1] = 51006922,
                [2] = 51006923,
                },
            ["SpeakNpcId"] = 700230,
            },
        [51006922] = {
            ["Content"] = "我还没动手呢！",
            ["ContentJP"] = "まだ何もしてない！",
            ["DialogueId"] = 51006922,
            ["GUID"] = "7FB0C0DA",
            ["NextDialogue"] = 51006924,
            },
        [51006923] = {
            ["Content"] = "我才没有翻垃圾桶的癖好。",
            ["ContentJP"] = "別に、ゴミ箱をあさる趣味はないけど？",
            ["DialogueId"] = 51006923,
            ["GUID"] = "7FB0C0DB",
            ["NextDialogue"] = 51006924,
            },
        [51006924] = {
            ["Content"] = "你这小孩少充楞，我都看到了。",
            ["ContentJP"] = "とぼけたってムダだぜ、ちゃんと見てたからな。",
            ["DialogueId"] = 51006924,
            ["GUID"] = "7FB0C0DC",
            ["NextDialogue"] = 51006925,
            ["SpeakNpcId"] = 700230,
            },
        [51006925] = {
            ["Content"] = "昨天有个穿制服的女的，一边哭，一边把这盒子丢了进去。有个拾荒的老太太好心问她怎么了，结果愣是被那凶女人劈头盖脸骂了一顿，让少管闲事。",
            ["ContentJP"] = "昨日な、制服着た女が泣きながらこの箱を捨てていったんだよ。親切なおばあさんが声かけたら、逆ギレして怒鳴りつけてさ。ったく、ろくな奴じゃなかったな。",
            ["DialogueId"] = 51006925,
            ["GUID"] = "7FB0C0DD",
            ["NextDialogue"] = 51006926,
            ["SpeakNpcId"] = 700230,
            },
        [51006926] = {
            ["Content"] = "喏，就是你手上那个盒子。还说你不是从垃圾桶捡的？",
            ["ContentJP"] = "で、今お前が持ってるのがその箱ってわけだ。まだ白を切るつもりか？",
            ["DialogueId"] = 51006926,
            ["GUID"] = "7FB0C0DE",
            ["NextDialogue"] = 51006927,
            ["SpeakNpcId"] = 700230,
            },
        [51006927] = {
            ["Content"] = "不是我……算了懒得解释了，总之谢谢你告诉我失主的信息。",
            ["ContentJP"] = "……違うけど、もういいや。教えてくれてありがとう。",
            ["DialogueId"] = 51006927,
            ["GUID"] = "7FB0C0DF",
            ["NextDialogue"] = 51006928,
            ["SpeakNpcId"] = 100001,
            },
        [51006928] = {
            ["Content"] = "（穿制服的凶女人……会和玛尔洁的“哪件货物”有关呢？）",
            ["ContentJP"] = "（制服の女……もしかして、マギーが言ってた「例のモノ」と関係があるのかな？）",
            ["DialogueId"] = 51006928,
            ["GUID"] = "7FB0C0E0",
            ["SpeakNpcId"] = 100001,
            },
        [51006931] = {
            ["Content"] = "成为售票员的第一年零八个月，我终于攒够了可以从冰湖城坐到南方丹流城的车票钱。",
            ["ContentJP"] = "販売員になって一年と八ヶ月、やっと南のレッドバリー城までの運賃が貯まったよ。",
            ["DialogueId"] = 51006931,
            ["GUID"] = "7FB0C49E",
            ["NextDialogue"] = 51006932,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51006932] = {
            ["Content"] = "这不是很好吗？你在一步步接近梦想。",
            ["ContentJP"] = "すごいじゃんか。少しずつ夢に近づいたんだね。",
            ["DialogueId"] = 51006932,
            ["GUID"] = "7FB0C4C8",
            ["NextDialogue"] = 51006933,
            ["SpeakNpcId"] = 100001,
            },
        [51006933] = {
            ["Content"] = "接近？你忘了<H>卡戎监护金</>了吗？票本身的价格连买票要交的监护金零头都不到！要想买去他那边的票，我要不吃不喝五年！可我还有家要养……",
            ["ContentJP"] = "近づく？<H>カロン税</>のこと、忘れたの？チケット代なんか、税金の端数にもならないわ！向こうに行くためには、五年は食べず飲まずで貯めないといけない。……それに、家族だって養わなきゃいけないんだから。",
            ["DialogueId"] = 51006933,
            ["GUID"] = "7FB0C4F2",
            ["NextDialogue"] = 51007147,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007001] = {
            ["Content"] = "你来打听，火车信息？希望远离，有刻薄女性驻守关卡！",
            ["ContentJP"] = "列車の情報を尋ねる？意地悪な女性がありので、近づくないほうがいいよ！",
            ["DialogueId"] = 51007001,
            ["GUID"] = "7FB0D01A",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510070011,
                [2] = 510070012,
                },
            ["SpeakNpcId"] = 700149,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51007002] = {
            ["Content"] = "已经受够！特别、非常、极其想走！",
            ["ContentJP"] = "もううんざり！とても、非常に、極めてここを離れるたい！",
            ["DialogueId"] = 51007002,
            ["GUID"] = "7FB0D044",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextDialogue"] = 51007004,
            ["SpeakNpcId"] = 700149,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            },
        [51007003] = {
            ["Content"] = "在学了！此地口音，和故乡，有差别！",
            ["ContentJP"] = "学んでいるところだ！ここの、訛りは、あのう、故郷とは違うんだ！",
            ["DialogueId"] = 51007003,
            ["GUID"] = "7FB0D06E",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextDialogue"] = 51007004,
            ["SpeakNpcId"] = 700149,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            },
        [51007004] = {
            ["Content"] = "（这个售票员看着很不好惹。但考虑到你总有一天会离开冰湖城，和她打交道是必须的……是否应该现在采取些行动呢？）",
            ["ContentJP"] = "（この切符売りは厄介そうだ。しかし、いつかアイスレイク城を離れる時、彼女と関わるのは避けられない…今のうちに何かすべきか？）",
            ["DialogueId"] = 51007004,
            ["GUID"] = "7FB0D098",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextDialogue"] = 51007005,
            ["RestartTag"] = 51007004,
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            },
        [51007005] = {
            ["Content"] = "（你手上这份来自玛尔洁的“情报”，或许可以用来打开话题……）",
            ["ContentJP"] = "（マギーからの「情報」が手元にある。話のきっかけになれるかも…）",
            ["DialogueId"] = 51007005,
            ["GUID"] = "7FB0D0C2",
            ["LookAt"] = {
                [1] = "700149:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510070051,
                },
            ["TurnTo"] = {
                [1] = "700149:n(0)",
                },
            ["bForbidSkipOptions"] = true,
            },
        [51007006] = {
            ["Content"] = "（有心无力，一时没想到什么好办法。）",
            ["ContentJP"] = "（やる気はあるが、いい方法が思いつかない）",
            ["DialogueId"] = 51007006,
            ["GUID"] = "7FB0D0EC",
            },
        [51007007] = {
            ["Content"] = "感谢！为您喝彩！我全程目击该事件！",
            ["ContentJP"] = "ありがとう！君、良い人ね！ここで応援しるよ！",
            ["DialogueId"] = 51007007,
            ["GUID"] = "7FB0D116",
            ["SpeakNpcId"] = 700149,
            ["TalkActionId"] = {
                [1] = "700149:Agree",
                },
            },
        [51007101] = {
            ["Content"] = "（你和异国人走到售票亭前，售票员杰西卡上下打量你几眼，冷冷地开了口。）",
            ["ContentJP"] = "（君と異国人が切符売り場に近づくと、切符売りのジェシカが冷たい目で君を見下ろしながら話し始める）",
            ["DialogueId"] = 51007101,
            ["GUID"] = "7FB0E082",
            ["NextDialogue"] = 51007102,
            },
        [51007102] = {
            ["Content"] = "怎么又来了个穷酸卡戎？",
            ["ContentJP"] = "また貧乏くさいカロンが来たのか？",
            ["DialogueId"] = 51007102,
            ["GUID"] = "7FB0E0AC",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                [2] = "700148:n(700147)",
                },
            ["NextDialogue"] = 51007103,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Talk01_Start",
                },
            ["TurnTo"] = {
                [1] = "700147:n(0)",
                },
            },
        [51007103] = {
            ["Content"] = "注意你的态度，我可不是什么“穷酸卡戎”。修普诺斯之家的老板你知道吧，他空置的那间宅子现在是我租着。",
            ["ContentJP"] = "その態度に気をつけろ、私は「貧乏くさいカロン」じゃない。ヒュプノスの家の主人を知ってるだろう？あの空き家は今私が借りているんだ。",
            ["DialogueId"] = 51007103,
            ["GUID"] = "7FB0E0D6",
            ["NextDialogue"] = 51007104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Talk01_End",
                },
            },
        [51007104] = {
            ["Content"] = "哈？谁都知道那个臭脸大叔最讨厌外乡人，你说谎不打草稿吗？既然得了幻想症，就把自己关在那“大宅子”里哪儿也别去！",
            ["ContentJP"] = "は？誰もがあの厳しい叔父さんが外の人を嫌うことを知っている。嘘をつくならもっとましな嘘をつけ！妄想に取り憑かれているなら、その「大邸宅」にこもってどこにも行かないほうがいい！",
            ["DialogueId"] = 51007104,
            ["GUID"] = "7FB0E100",
            ["NextDialogue"] = 51007105,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Confident_Start",
                },
            },
        [51007105] = {
            ["Content"] = "过分！请说词，让她止住刻薄语言！",
            ["ContentJP"] = "ひどいだな！何か言うて、彼女のいやらしい発言を止めるくれ！",
            ["DialogueId"] = 51007105,
            ["GUID"] = "7FB0E12A",
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                },
            ["NextOptions"] = {
                [1] = 51007106,
                },
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Confident_End",
                [2] = "700148:Talk03_Start",
                },
            },
        [51007106] = {
            ["Content"] = "（将玛尔洁赠予的一盒纸星星放在售票员的桌子上。）",
            ["ContentJP"] = "（マギーからもらった折り紙の星を切符売りの机の上に置く）",
            ["DialogueId"] = 51007106,
            ["GUID"] = "7FB0E154",
            ["NextDialogue"] = 51007107,
            },
        [51007107] = {
            ["Content"] = "（看到纸星星的瞬间，售票员的神色有些动摇。但她很快恢复了刚才的表情，嫌弃地瞥了你一眼。）",
            ["ContentJP"] = "（折り紙の星を見ると、切符売りの表情が一瞬変わったが、すぐに冷たい表情に戻り、嫌そうに一瞥を投げる）",
            ["DialogueId"] = 51007107,
            ["GUID"] = "7FB0E17E",
            ["NextDialogue"] = 51007108,
            ["TalkActionId"] = {
                [1] = "700148:Talk03_End",
                },
            },
        [51007108] = {
            ["Content"] = "这是哪个桶捡来的垃圾？你把这儿当垃圾回收站？给我扔掉！",
            ["ContentJP"] = "どこかのゴミ箱から拾ってきたもの？ここをゴミ回収所とでも思ってるの？さっさと捨てて！",
            ["DialogueId"] = 51007108,
            ["GUID"] = "7FB0E1A8",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                },
            ["NextDialogue"] = 51007109,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Angry01_Start",
                },
            },
        [51007109] = {
            ["Content"] = "为什么说是垃圾？在我看来，这是很用心完成的手工艺品，可以感觉到制作者真挚的感情。",
            ["ContentJP"] = "どうしてゴミと言うの？真心を込めて作られた手工芸品に見えて、作り手の真摯な感情が感じられるよ。",
            ["DialogueId"] = 51007109,
            ["GUID"] = "7FB0E1D2",
            ["NextDialogue"] = 51007110,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Angry01_End",
                },
            },
        [51007110] = {
            ["Content"] = "华胥也有，折纸星星习俗。据说，折得多，会美梦成真。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>にもあるんだ、折り紙で星を作る風習が。たくさん折ったら、願いが叶うって言われてるよ。",
            ["DialogueId"] = 51007110,
            ["GUID"] = "7FB0E1FC",
            ["LookAt"] = {
                [1] = "700148:n(0)",
                },
            ["NextDialogue"] = 51007111,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Think_Start",
                },
            },
        [51007111] = {
            ["Content"] = "原来是这样……怪不得，我之前想研究一下它是怎么叠起来的，就拆了一个，结果发现里面写了字。",
            ["ContentJP"] = "そうだったのか…以前これを研究しようと思って一つ解いたら、中に字が書いてあった。",
            ["DialogueId"] = 51007111,
            ["GUID"] = "7FB0E226",
            ["NextDialogue"] = 51007112,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700148:Think_End",
                },
            },
        [51007112] = {
            ["Content"] = "上面写的好像正是……某个人许下的愿望？",
            ["ContentJP"] = "書かれていたのは…誰かの願い？",
            ["DialogueId"] = 51007112,
            ["GUID"] = "7FB0E250",
            ["NextDialogue"] = 51007113,
            ["SpeakNpcId"] = 100001,
            },
        [51007113] = {
            ["Content"] = "你……你都打开看了？！",
            ["ContentJP"] = "お前…全部開けて見たのか？！",
            ["DialogueId"] = 51007113,
            ["GUID"] = "7FB0E27A",
            ["LookAt"] = {
                [1] = "700148:n(700147)",
                },
            ["NextDialogue"] = 51007114,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_Start",
                },
            },
        [51007114] = {
            ["Content"] = "我只看了一张。我发现它是用车票折的，背面写的文字也和列车有关，所以我才想来车站看看，想着也许能物归原主。",
            ["ContentJP"] = "一つだけだよ。切符で折られていて、裏側に列車に関することが書かれていた。それで持ち主に返そうと思って駅に来たんだ。",
            ["DialogueId"] = 51007114,
            ["GUID"] = "7FB0E2A4",
            ["NextDialogue"] = 51007115,
            ["SpeakNpcId"] = 100001,
            },
        [51007115] = {
            ["Content"] = "但既然你说是垃圾，那就随我处置喽。",
            ["ContentJP"] = "でもそれがゴミだと言うなら、どう処分しても私の自由だな。",
            ["DialogueId"] = 51007115,
            ["GUID"] = "7FB0E2CE",
            ["NextDialogue"] = 51007116,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_End",
                },
            },
        [51007116] = {
            ["Content"] = "（你将纸星星拿在手里，再次看向售票员。她的目光分明跟着盒子移了过来，但她似乎还是不愿意开口。）",
            ["ContentJP"] = "（紙星を手に取り、再び切符売りを見る。彼女の視線は明らかに箱に向かっているが、話す気はなさそうだ）",
            ["DialogueId"] = 51007116,
            ["GUID"] = "7FB0E2F8",
            ["NextOptions"] = {
                [1] = 510071161,
                [2] = 510071162,
                },
            },
        [51007117] = {
            ["Content"] = "许愿的那个人虽然买不起车票，但还是忍不住把看起来像车站的词写在星星上。应该是希望有一天可以美梦成真，真的抵达这些地方吧。",
            ["ContentJP"] = "願いを込めた人は切符を買う余裕がなかったけど、それでも列車に関することを紙星に書いてしまったんだ。いつか夢が叶って、その場所に行けると信じているんだろう。",
            ["DialogueId"] = 51007117,
            ["GUID"] = "7FB0E322",
            ["NextDialogue"] = 51007118,
            ["SpeakNpcId"] = 100001,
            },
        [51007118] = {
            ["Content"] = "那个人真就这么忍心把这些愿望当垃圾丢掉吗？",
            ["ContentJP"] = "本当にこれらの願いをゴミのように捨てるつもりか？あの人は。",
            ["DialogueId"] = 51007118,
            ["GUID"] = "7FB0E34C",
            ["NextDialogue"] = 51007121,
            ["SpeakNpcId"] = 100001,
            },
        [51007119] = {
            ["Content"] = "“5月21日。凯瑟琳太太把银币扔在我脚边，让我蹲着一枚枚捡起来。她说我没资格从她手中接过钱袋。唉，如果我也能像她一样有花不完的银币就好了。”",
            ["ContentJP"] = "「5月21日。キャサリン夫人は私の足元に銀貨を投げ捨て、しゃがんで一枚一枚拾わせ、私が彼女の手から金を受け取る資格がないって。ああ、私も彼女のように使いきれないほどの銀貨を持っていたらなあ」",
            ["DialogueId"] = 51007119,
            ["GUID"] = "7FB0E376",
            ["NextDialogue"] = 51007120,
            ["SpeakNpcId"] = 100001,
            },
        [51007120] = {
            ["Content"] = "“9月13日。昨晚再次梦见自己终于攒够了钱，买下车票。这次梦里的终点站是丹流城……”",
            ["ContentJP"] = "「9月13日。昨晩また夢を見た。ついにお金を貯めて切符を買った夢だ。今回の終点はレッドバリー城だった…」",
            ["DialogueId"] = 51007120,
            ["GUID"] = "7FB0E3A0",
            ["NextDialogue"] = 51007121,
            ["SpeakNpcId"] = 100001,
            },
        [51007121] = {
            ["Content"] = "……住口！别说了！",
            ["ContentJP"] = "…やめて！もう読まないで！",
            ["DialogueId"] = 51007121,
            ["GUID"] = "7FB0E3CA",
            ["NextDialogue"] = 51007122,
            ["SpeakNpcId"] = 700147,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_Start",
                },
            },
        [51007122] = {
            ["Content"] = "其实这是你的东西，对吗——",
            ["ContentJP"] = "本当は君のものでしょう——",
            ["DialogueId"] = 51007122,
            ["GUID"] = "7FB0E3F4",
            ["NextDialogue"] = 51007123,
            ["SpeakNpcId"] = 100001,
            },
        [51007123] = {
            ["Content"] = "（你回忆了一下车票上写着的名字。）",
            ["ContentJP"] = "（切符に書かれていた名前を思い出す）",
            ["DialogueId"] = 51007123,
            ["GUID"] = "7FB0E41E",
            ["NextDialogue"] = 51007124,
            },
        [51007124] = {
            ["Content"] = "“杰西卡”？",
            ["ContentJP"] = "「ジェシカ」？",
            ["DialogueId"] = 51007124,
            ["GUID"] = "7FB0E448",
            ["NextDialogue"] = 51007125,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "700147:Sigh_End",
                },
            },
        [51007125] = {
            ["Content"] = "你……",
            ["ContentJP"] = "お前…",
            ["DialogueId"] = 51007125,
            ["GUID"] = "7FB0E472",
            ["NextDialogue"] = 51007126,
            ["SpeakNpcId"] = 700147,
            },
        [51007126] = {
            ["Content"] = "……好吧，没错。我是杰西卡。这些垃圾确实是我扔的，行了吧？你弯弯绕绕说了一大堆，不就想看我笑话吗？",
            ["ContentJP"] = "…分かった、そうだよ、ジェシカだよ。これらのゴミは確かに私が捨てた。これで満足か？回りくどく言って、私を笑いものにしたいだけなんだろう？",
            ["DialogueId"] = 51007126,
            ["GUID"] = "7FB0E49C",
            ["NextDialogue"] = 51007127,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Agree",
                },
            },
        [51007127] = {
            ["Content"] = "没错，我和所有穷鬼一样，根本坐不起这破车，满意了吗？！",
            ["ContentJP"] = "そうよ、あたしもほかの貧乏人と同じ。こんなおんぼろ車に乗る余裕なんてないの、わかった？",
            ["DialogueId"] = 51007127,
            ["GUID"] = "7FB0E4C6",
            ["NextDialogue"] = 51007128,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_Start",
                },
            },
        [51007128] = {
            ["Content"] = "……什么美梦成真……都是骗人的。",
            ["ContentJP"] = "…何が夢が叶うんだ…笑わせるな。",
            ["DialogueId"] = 51007128,
            ["GUID"] = "7FB0E4F0",
            ["NextDialogue"] = 51007129,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_End",
                },
            },
        [51007129] = {
            ["Content"] = "既然你也想乘上列车、也买不起车票，那么你本该能够理解其他和你一样的穷苦之人，为什么要对他们恶语相向？",
            ["ContentJP"] = "列車に乗りたくて、切符を買えないなら、同じように苦しんでいる他の人たちの気持ちが分かるはずなのに、なぜ彼らに辛辣な言葉をかけるの？",
            ["DialogueId"] = 51007129,
            ["GUID"] = "7FB0E51A",
            ["NextDialogue"] = 51007130,
            ["SpeakNpcId"] = 100001,
            },
        [51007130] = {
            ["Content"] = "呵，那我要怎么做，温柔地安慰他们吗？",
            ["ContentJP"] = "ふん、それで？どうすればいいの？優しく慰める？",
            ["DialogueId"] = 51007130,
            ["GUID"] = "7FB0E544",
            ["NextDialogue"] = 51007131,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007131] = {
            ["Content"] = "然后让他们产生不切实际的妄想，以为自己有一天也配坐上老爷们的列车？！",
            ["ContentJP"] = "そして現実離れした幻想を抱かせて、いつか自分も貴族たちの列車に乗れると思わせるの？",
            ["DialogueId"] = 51007131,
            ["GUID"] = "7FB0E56E",
            ["NextDialogue"] = 51007132,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Disagree",
                },
            },
        [51007132] = {
            ["Content"] = "只需好好赚钱，能坐上！我们织星客，做生意缓慢挣钱。",
            ["ContentJP"] = "コツコツ稼げば、そのうち乗れるさ。俺たち星織人は、のんびり商売して地道に儲けてるんだ。",
            ["DialogueId"] = 51007132,
            ["GUID"] = "7FB0E598",
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                },
            ["NextDialogue"] = 51007133,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Explain02_Start",
                },
            },
        [51007133] = {
            ["Content"] = "你是织星客？！那你……你知道一个叫“嘉言”的华胥织星客吗？他是十三年前到过冰湖城的。",
            ["ContentJP"] = "お前は星織人なの？！それなら…13年前にアイスレイク城に来た「カゲン」という名前の<Default note=\"text:カショ\">華胥</>の星織人を知っている？",
            ["DialogueId"] = 51007133,
            ["GUID"] = "7FB0E5C2",
            ["NextDialogue"] = 51007134,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700148:Explain02_End",
                },
            },
        [51007134] = {
            ["Content"] = "不记得。织星客，为数众多。",
            ["ContentJP"] = "さあな。星織人なんて山ほどいるから。",
            ["DialogueId"] = 51007134,
            ["GUID"] = "7FB0E5EC",
            ["NextDialogue"] = 51007135,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Disagree",
                },
            },
        [51007135] = {
            ["Content"] = "……好吧。",
            ["ContentJP"] = "…そうか。",
            ["DialogueId"] = 51007135,
            ["GUID"] = "7FB0E616",
            ["NextDialogue"] = 51007136,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007136] = {
            ["Content"] = "你说的那个人，是你的朋友？",
            ["ContentJP"] = "君が言っているその人は、お知り合い？",
            ["DialogueId"] = 51007136,
            ["GUID"] = "7FB0E640",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                },
            ["NextDialogue"] = 51007137,
            ["SpeakNpcId"] = 100001,
            },
        [51007137] = {
            ["Content"] = "呵呵，朋友？不，那是我最讨厌的人。",
            ["ContentJP"] = "ふふ、知り合い？違うわよ、あれは私が最も嫌いな人だ。",
            ["DialogueId"] = 51007137,
            ["GUID"] = "7FB0E66A",
            ["NextDialogue"] = 51007138,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Disagree",
                },
            },
        [51007138] = {
            ["Content"] = "（杰西卡拆开了一颗纸星星。她看一眼上面的字，又开始拆下一颗，就这样一颗一颗地拆了下去。）",
            ["ContentJP"] = "（ジェシカは紙星を一つ開け、文字を一瞥し、次の星を開け始める。こうして一つずつ…）",
            ["DialogueId"] = 51007138,
            ["GUID"] = "7FB0E694",
            ["NextDialogue"] = 51007139,
            },
        [51007139] = {
            ["Content"] = "他说自己去过很多国家，见过许多有趣的人和事。每卖出一件货物，他就会讲一个来自远方的故事。",
            ["ContentJP"] = "彼は多くの国を訪れ、たくさんの面白い人々や出来事に出会ったと言ってた。それに、商品を売るたびに、遠くの地からの物語を話してくれた。",
            ["DialogueId"] = 51007139,
            ["GUID"] = "7FB0E6BE",
            ["NextDialogue"] = 51007140,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_Start",
                },
            },
        [51007140] = {
            ["Content"] = "我就像个傻子一样，把他故事里的每个句子都记下来，背下来，以为这样就能更接近他说的那个广阔世界。",
            ["ContentJP"] = "私は馬鹿みたいに、こうして彼の話を一つ一つ覚えてた。それで彼の言う広い世界に近づけると思ってたんだ。",
            ["DialogueId"] = 51007140,
            ["GUID"] = "7FB0E6E8",
            ["NextDialogue"] = 51007141,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_End",
                },
            },
        [51007141] = {
            ["Content"] = "他说“星星是愿望的种子，当它坠落，就如果实收获，你所期盼的，都会实现。”他说“无数由珍爱之物做成的星，将在地上发芽。”",
            ["ContentJP"] = "「星は願いの種。それが落ちると、願いが実る」、彼はそう言ってた。「愛するものから作られた無数の星が地上で芽生える」って。",
            ["DialogueId"] = 51007141,
            ["GUID"] = "7FB0E712",
            ["NextDialogue"] = 51007142,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain02_Start",
                },
            },
        [51007142] = {
            ["Content"] = "我很想和他一起走，继续听他讲不完的故事。但是我买不起车票，最后只能独自目送他登上了远去的火车。",
            ["ContentJP"] = "彼と一緒に旅をして、話を聞き続けたかった。でも切符が買えず、最後は彼が遠くへ向かう列車に乗るのを見送るしかなかったのよ。",
            ["DialogueId"] = 51007142,
            ["GUID"] = "7FB0E73C",
            ["NextDialogue"] = 51007143,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain02_End",
                },
            },
        [51007143] = {
            ["Content"] = "（她又拆开了一颗星星，这张车票的颜色有些泛黄。车票背面写着“我想离开这里，追上你的脚步”。）",
            ["ContentJP"] = "（彼女はもう一つ、少し黄ばんでいた切符で作った紙星を開けた。裏には「ここを離れて、君の足跡を追いたい」と書かれていた）",
            ["DialogueId"] = 51007143,
            ["GUID"] = "7FB0E766",
            ["NextDialogue"] = 51007144,
            },
        [51007144] = {
            ["Content"] = "哈哈……找到了。这一张，是他登上的那趟列车。那辆列车将穿越海伯利亚大平原，去向遥远的南方。",
            ["ContentJP"] = "ふふ……あった。このチケット、あの人が乗った列車のだ。あの列車はヒュペリアを越えて、ずっと南へ向かうの。",
            ["DialogueId"] = 51007144,
            ["GUID"] = "7FB0E790",
            ["NextDialogue"] = 51007145,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Talk02_Start",
                },
            },
        [51007145] = {
            ["Content"] = "当时的售票员看我可怜，在发车后把没卖出去的废票给了我一张，安慰我说去那边的列车还有很多。",
            ["ContentJP"] = "当時、切符売りが私を哀れんで、売れ残ったチケットを一枚タダでくれたんだ。「向こう行きの列車ならまだいっぱいあるよ」ってね。",
            ["DialogueId"] = 51007145,
            ["GUID"] = "7FB0E7BA",
            ["NextDialogue"] = 51007146,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Talk02_End",
                },
            },
        [51007146] = {
            ["Content"] = "可是我始终买不起票，只能眼巴巴地在旁边看着。久而久之我也把卖票的流程看熟了，后来就接替她当了售票员。",
            ["ContentJP"] = "でも、結局私はチケットを買うお金もなくて、ただじっと横で見てるしかなかった。それでも売り方を覚えて、気づいたら自分が売る側になってた。",
            ["DialogueId"] = 51007146,
            ["GUID"] = "7FB0E7E4",
            ["NextDialogue"] = 51006931,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Disagree",
                },
            },
        [51007147] = {
            ["Content"] = "（她叹了一口气，停下了动作，把所有拆开和没拆开的纸星星拢在一起，推到了桌角。）",
            ["ContentJP"] = "（彼女はため息をつき、動きを止め、開けた星と開けていない星をすべてまとめて、テーブルの隅に押しのける）",
            ["DialogueId"] = 51007147,
            ["GUID"] = "7FB0E80E",
            ["NextDialogue"] = 51007148,
            },
        [51007148] = {
            ["Content"] = "现在你明白了吧？这些纸星星就是不折不扣的垃圾。谢谢你特地拿来还给我，下次我会把它们撕成碎片再扔。",
            ["ContentJP"] = "これで分かったでしょ？この紙星はただのゴミだ。わざわざと返してくれてありがとう。次は細かく破って捨てるから。",
            ["DialogueId"] = 51007148,
            ["GUID"] = "7FB0E838",
            ["NextDialogue"] = 51007149,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain02_Start",
                },
            },
        [51007149] = {
            ["Content"] = "怎么觉得，有点可惜……",
            ["ContentJP"] = "なんだか、もったいない気がする…",
            ["DialogueId"] = 51007149,
            ["GUID"] = "7FB0E862",
            ["NextDialogue"] = 51007150,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Explain02_End",
                [2] = "700148:Think_Start",
                },
            },
        [51007150] = {
            ["Content"] = "我用不着你可怜，织星客。",
            ["ContentJP"] = "同情なんていらないよ、星織人。",
            ["DialogueId"] = 51007150,
            ["GUID"] = "7FB0E88C",
            ["NextOptions"] = {
                [1] = 51007151,
                },
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700148:Think_End",
                },
            },
        [51007151] = {
            ["Content"] = "你就不能好好说话吗？",
            ["ContentJP"] = "もう少し親切にしてくれる？",
            ["DialogueId"] = 51007151,
            ["GUID"] = "7FB0E8B6",
            ["NextDialogue"] = 51007152,
            },
        [51007152] = {
            ["Content"] = "“好好说话”？你的意思是要我也像那个织星客、像那个售票员一样，说些漂亮的空话，什么“远方”，什么“未来”，然后让人眼巴巴地盼望着？",
            ["ContentJP"] = "「親切」って？星織人やあの切符売りみたいに、「遠く」とか「未来」とか言って人を期待させろってこと？",
            ["DialogueId"] = 51007152,
            ["GUID"] = "7FB0E8E0",
            ["NextDialogue"] = 51007153,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_Start",
                },
            },
        [51007153] = {
            ["Content"] = "既然你是卡戎，你应该比我、比这个华胥人更清楚冰湖城到底是个什么地方！",
            ["ContentJP"] = "カロンなら、私より、この<Default note=\"text:カショ\">華胥</>人よりもアイスレイク城がどんな場所か分かっているはずだろう！",
            ["DialogueId"] = 51007153,
            ["GUID"] = "7FB0E90A",
            ["NextDialogue"] = 51007154,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700147:Explain01_End",
                },
            },
        [51007154] = {
            ["Content"] = "去城里走上一圈，人人都在悲叹、抱怨、咒骂！在这种地方，好好说话有意义吗？",
            ["ContentJP"] = "街を一回りしてみなさい、みんな悲しんでいて、文句を言って、呪いの言葉を吐いているんだよ！こんな場所で、ちゃんと話す意味があるの？",
            ["DialogueId"] = 51007154,
            ["GUID"] = "7FB0E934",
            ["NextDialogue"] = 51007155,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007155] = {
            ["Content"] = "等一下！",
            ["ContentJP"] = "待つて！",
            ["DialogueId"] = 51007155,
            ["GUID"] = "7FB0E95E",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "700147:n(700148)",
                },
            ["NextDialogue"] = 51007156,
            ["SpeakNpcId"] = 700148,
            },
        [51007156] = {
            ["Content"] = "（异国人忽然想到了什么，转过身开始翻背包。你和杰西卡不明就里地听着一连串叮铃哐啷的声响，不知他到底在干什么。）",
            ["ContentJP"] = "（異国人が突然何かを思い出し、振り向いてバックパックを探し始める。君とジェシカは訳も分からず、ガチャガチャと音を立てる様子を見守る）",
            ["DialogueId"] = 51007156,
            ["GUID"] = "7FB0E988",
            ["NextDialogue"] = 51007157,
            },
        [51007157] = {
            ["Content"] = "（过了一会儿，声音停下来，他捧着一个外观颇有异域风情的小盒子递给杰西卡。）",
            ["ContentJP"] = "（しばらくして音が止まり、彼はエキゾチックな小箱をジェシカに差し出す）",
            ["DialogueId"] = 51007157,
            ["GUID"] = "7FB0E9B2",
            ["NextDialogue"] = 51007158,
            ["TalkActionId"] = {
                [1] = "700148:Give",
                },
            },
        [51007158] = {
            ["Content"] = "这个，华胥产出盒子！可以锁起，不怕再丢星星，被人看到。",
            ["ContentJP"] = "この箱は<Default note=\"text:カショ\">華胥</>産のものだ！鍵がかかるから、紙星を失くし心配もないし、誰にも見られるない。",
            ["DialogueId"] = 51007158,
            ["GUID"] = "7FB0E9DC",
            ["NextDialogue"] = 51007159,
            ["SpeakNpcId"] = 700148,
            },
        [51007159] = {
            ["Content"] = "你什么意思啊……？我哪来的钱买这么精致的盒子……",
            ["ContentJP"] = "…何のつもり？こんなに精巧な箱を買う金なんて持ってないわ…",
            ["DialogueId"] = 51007159,
            ["GUID"] = "7FB0EA06",
            ["NextDialogue"] = 51007160,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007160] = {
            ["Content"] = "不要钱，送给你！切勿放弃心愿！",
            ["ContentJP"] = "無料であげるよ！夢を諦めないで！",
            ["DialogueId"] = 51007160,
            ["GUID"] = "7FB0EA30",
            ["NextDialogue"] = 51007161,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Disagree",
                },
            },
        [51007161] = {
            ["Content"] = "（杰西卡愣了一下，低头看向那个盒子，又转过头去，沉默不语。）",
            ["ContentJP"] = "（ジェシカは一瞬動揺し、箱に目を落とし、再び顔を上げて黙っている）",
            ["DialogueId"] = 51007161,
            ["GUID"] = "7FB0EA5A",
            ["NextOptions"] = {
                [1] = 51007162,
                [2] = 51007168,
                },
            },
        [51007162] = {
            ["Content"] = "（劝杰西卡收下盒子。）",
            ["ContentJP"] = "（ジェシカに箱を受け取るように勧める）",
            ["DialogueId"] = 51007162,
            ["GUID"] = "7FB0EA84",
            ["NextDialogue"] = 51007163,
            },
        [51007163] = {
            ["Content"] = "……你看。温柔也不是全无意义的——至少它能变成一个精致的小盒子，守护一个藏在星星的梦想。",
            ["ContentJP"] = "…ほらね。優しさは無駄じゃないんだ――少なくともそれは精巧な箱になって、星に込められた夢を守るんだよ。",
            ["DialogueId"] = 51007163,
            ["GUID"] = "7FB0EAAE",
            ["LookAt"] = {
                [1] = "700147:n(0)",
                },
            ["NextDialogue"] = 51007164,
            ["SpeakNpcId"] = 100001,
            },
        [51007164] = {
            ["Content"] = "（你将桌上的纸星星都捧起来，放进了那个华胥风格的盒子，然后将它重新递给杰西卡。）",
            ["ContentJP"] = "（テーブルの上の紙星を集めて<Default note=\"text:カショ\">華胥</>風の箱に入れ、それをジェシカに手渡す）",
            ["DialogueId"] = 51007164,
            ["GUID"] = "7FB0EAD8",
            ["NextDialogue"] = 51007165,
            },
        [51007165] = {
            ["Content"] = "有空的时候，再把这些星星叠起来吧。",
            ["ContentJP"] = "時間ができたら、またこの紙星を折り直そう。",
            ["DialogueId"] = 51007165,
            ["GUID"] = "7FB0EB02",
            ["NextDialogue"] = 51007166,
            ["SpeakNpcId"] = 100001,
            },
        [51007166] = {
            ["Content"] = "你……",
            ["ContentJP"] = "お前…",
            ["DialogueId"] = 51007166,
            ["GUID"] = "7FB0EB2C",
            ["NextDialogue"] = 51007167,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007167] = {
            ["Content"] = "好……好吧。受不了你的啰嗦了，我收下就是了。谢……谢谢。",
            ["ContentJP"] = "ったく…分かったよ。お前のしつこさには勝てないわ。受け取るよ。ま、ありがとな。",
            ["DialogueId"] = 51007167,
            ["GUID"] = "7FB0EB56",
            ["NextDialogue"] = 51007172,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007168] = {
            ["Content"] = "（就这样吧，尊重他人命运。）",
            ["ContentJP"] = "（これでいい、他人の選んだ道に干渉しないでおこう）",
            ["DialogueId"] = 51007168,
            ["GUID"] = "7FB0EB80",
            ["NextDialogue"] = 51007169,
            },
        [51007169] = {
            ["Content"] = "把它拿走吧。你以为我为什么要扔掉那些星星？这么多年下来，该想的我早就想清楚了，现实也早就认清了。",
            ["ContentJP"] = "それを持ってて。なぜ私があの星を捨てたと思う？何年もかけて、私はもう考え尽くして、現実を受け入れたんだよ。",
            ["DialogueId"] = 51007169,
            ["GUID"] = "7FB0EBAA",
            ["NextDialogue"] = 51007170,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007170] = {
            ["Content"] = "唉，憾事，憾事！",
            ["ContentJP"] = "なんてことだ、残念だ！",
            ["DialogueId"] = 51007170,
            ["GUID"] = "7FB0EBD4",
            ["NextDialogue"] = 51007171,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Disagree",
                },
            },
        [51007171] = {
            ["Content"] = "…………",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51007171,
            ["GUID"] = "7FB0EBFE",
            ["NextDialogue"] = 51007172,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007172] = {
            ["Content"] = "……对了，就算是开往同一个目的地，不同车次的价格也不一样，有几趟会便宜些。虽然也省不了多少钱，但……",
            ["ContentJP"] = "…そうだ、同じ目的地でも列車によって料金は違うんだ。安い便もいくつかある。大した節約にはならないけど…",
            ["DialogueId"] = 51007172,
            ["GUID"] = "7FB0EC28",
            ["NextDialogue"] = 51007173,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007173] = {
            ["Content"] = "如果，有一天你们真能从自己的破口袋里掏出点钱来买票的话……我可以帮你们提前看一看，预留最便宜的那趟车的票。",
            ["ContentJP"] = "…いつかお前らが本当にお金を出して切符を買えるようになったら…私は一番安い切符を取っておくよ。",
            ["DialogueId"] = 51007173,
            ["GUID"] = "7FB0EC52",
            ["NextDialogue"] = 51007174,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007174] = {
            ["Content"] = "作为交换，星星的事，别说出去。",
            ["ContentJP"] = "その代わり、紙星のことは内緒にしておいてね。",
            ["DialogueId"] = 51007174,
            ["GUID"] = "7FB0EC7C",
            ["NextDialogue"] = 51007175,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007175] = {
            ["Content"] = "感谢感谢，你原来是善良售票员！",
            ["ContentJP"] = "どうもだどうもだ。君って意外と優しい切符売りだね！",
            ["DialogueId"] = 51007175,
            ["GUID"] = "7FB0ECA6",
            ["NextDialogue"] = 51007176,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Agree",
                },
            },
        [51007176] = {
            ["Content"] = "你说的，十几年前织星客，我遇到帮你捎话。",
            ["ContentJP"] = "君の言ってた、十数年前の星織人、もし会えたら、君の言葉を伝えてあげるよ。",
            ["DialogueId"] = 51007176,
            ["GUID"] = "7FB0ECD0",
            ["NextDialogue"] = 51007177,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700148:Talk02_Start",
                },
            },
        [51007177] = {
            ["Content"] = "谢谢你的好意，不过……不用了。如果有一天真的能离开这里，我大概也不会去找他了。我想去个不会下雪的地方，看看外边的人是不是都和冰湖城不一样。",
            ["ContentJP"] = "お前の好意には感謝するけど…ま、もし本当にここを離れることができたら、彼を探しに行くことはないと思うわ。雪の降らない場所に行って、外の世界がどんなところか見てみたい。",
            ["DialogueId"] = 51007177,
            ["GUID"] = "7FB0ECFA",
            ["NextDialogue"] = 51007178,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            ["TalkActionId"] = {
                [1] = "700148:Talk02_End",
                [2] = "700147:Explain02_Start",
                },
            },
        [51007178] = {
            ["Content"] = "也很好，用功攒钱，一定能够离开。",
            ["ContentJP"] = "それもいいね。努力してお金を貯めるば、きっとここを出られるよ。",
            ["DialogueId"] = 51007178,
            ["GUID"] = "7FB0ED24",
            ["NextDialogue"] = 51007179,
            ["SpeakNpcId"] = 700148,
            ["TalkActionId"] = {
                [1] = "700147:Explain02_End",
                [2] = "700148:Agree",
                },
            },
        [51007179] = {
            ["Content"] = "……嗯。",
            ["ContentJP"] = "…うん。",
            ["DialogueId"] = 51007179,
            ["GUID"] = "7FB0ED4E",
            ["NextDialogue"] = 51007186,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Jiexi",
            },
        [51007180] = {
            ["Content"] = "你也有自己的星星。保存好你的星星，切记，不要丢进垃圾桶。",
            ["ContentJP"] = "君にも、自分の星がある。だから、大切にして。絶対に、ゴミ箱に捨てちゃダメだよ。",
            ["DialogueId"] = 51007180,
            ["GUID"] = "7FB0ED78",
            ["NextDialogue"] = 51007181,
            ["SpeakNpcId"] = 700148,
            ["TurnTo"] = {
                [1] = "700148:n(0)",
                },
            },
        [51007181] = {
            ["Content"] = "我名李安德，是织星客。前日子，生意有点赔，现在城门附近用心摆摊，请光顾！",
            ["ContentJP"] = "私はリアンダー、星織人だ。最近、商売が少しうまくいくなくて、今は城門近くで商売すているんだ。ぜひ立ち寄ってくれ！",
            ["DialogueId"] = 51007181,
            ["GUID"] = "7FB0EDA2",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Liande",
            ["TalkActionId"] = {
                [1] = "700148:Explain02_Start",
                },
            },
        [51007182] = {
            ["Content"] = "是你啊……要买车票的话和我说一声就好。",
            ["ContentJP"] = "お前か…切符を買うなら声をかけてね。",
            ["DialogueId"] = 51007182,
            ["GUID"] = "7FB0EDCC",
            ["SpeakNpcId"] = 700021,
            ["TalkActionId"] = {
                [1] = "700021:Agree",
                },
            },
        [51007186] = {
            ["Content"] = "对了！我也有美丽纸张。我们一起折星星。",
            ["ContentJP"] = "そうだ！きれいな紙を持ってるんだ。一緒に星を折ろうよ！",
            ["DialogueId"] = 51007186,
            ["GUID"] = "7FB0ED4F",
            ["NextDialogue"] = 51007187,
            ["SpeakNpcId"] = 700148,
            },
        [51007187] = {
            ["Content"] = "啊？你是想让我帮你吗？可我不会折星星。",
            ["ContentJP"] = "えっ？手伝ってほしいってこと？でも……星なんて折ったことないんだよね。",
            ["DialogueId"] = 51007187,
            ["GUID"] = "7FB0ED50",
            ["NextDialogue"] = 51007188,
            ["SpeakNpcId"] = 100001,
            },
        [51007188] = {
            ["Content"] = "我也不会折，很丑。但是互帮互助，就会好看！",
            ["ContentJP"] = "私も上手くない、ぐちゃぐちゃだ。でも、助け合えばきっときれいに折れるよ！",
            ["DialogueId"] = 51007188,
            ["GUID"] = "7FB0ED51",
            ["NextDialogue"] = 51007189,
            ["SpeakNpcId"] = 700148,
            },
        [51007189] = {
            ["Content"] = "那我试试吧。",
            ["ContentJP"] = "……じゃあ、やってみる。",
            ["DialogueId"] = 51007189,
            ["GUID"] = "7FB0ED52",
            ["SpeakNpcId"] = 100001,
            },
        [51007190] = {
            ["Content"] = "收下吧，善良有龙氏同胞。这里还有一些谢礼。",
            ["ContentJP"] = "受け取って。優しい龍の民へ。……それと、ちょっとしたお礼もね兼ねてね。",
            ["DialogueId"] = 51007190,
            ["GUID"] = "7FB0ED53",
            ["NextDialogue"] = 51007191,
            ["SpeakNpcId"] = 700148,
            },
        [51007191] = {
            ["Content"] = "送我的？",
            ["ContentJP"] = "……くれるの？",
            ["DialogueId"] = 51007191,
            ["GUID"] = "7FB0ED54",
            ["NextDialogue"] = 51007192,
            ["SpeakNpcId"] = 100001,
            },
        [51007192] = {
            ["Content"] = "嗯！她的星星，是愿望。织星客的星星，是远方，是故乡。",
            ["ContentJP"] = "うん！この星は、願いだ。星織人にとって星は、旅立ちであり、故郷なんだ。",
            ["DialogueId"] = 51007192,
            ["GUID"] = "7FB0ED55",
            ["NextDialogue"] = 51007180,
            ["SpeakNpcId"] = 700148,
            },
        [51007301] = {
            ["Content"] = "忠于欲望，忠于欲望，忠于欲望，哎，到底怎么才算忠于欲望啊……",
            ["ContentJP"] = "欲望のままに、欲望のままに、欲望のままに……ああ、欲望に忠実とは、一体何をすればいいのでしょうか……",
            ["DialogueId"] = 51007301,
            ["GUID"] = "7FB10152",
            ["NextDialogue"] = 51007302,
            ["SpeakNpcId"] = 700077,
            },
        [51007302] = {
            ["Content"] = "我是考古学者！欲望这种东西不在我的研究领域啊！！！",
            ["ContentJP"] = "私は所詮、考古学者よ！欲望なんて、学問に関係ないわ！",
            ["DialogueId"] = 51007302,
            ["GUID"] = "7FB1017C",
            ["NextOptions"] = {
                [1] = 510073021,
                [2] = 510073022,
                [3] = 510073023,
                },
            ["SpeakNpcId"] = 700077,
            ["bForbidSkipOptions"] = true,
            },
        [51007303] = {
            ["Content"] = "你的见解很有意思，能帮帮我吗？",
            ["ContentJP"] = "その見方、面白いわ。「欲望」とはなんなのか、私にもわかるように手伝ってくれる？",
            ["DialogueId"] = 51007303,
            ["GUID"] = "7FB101A6",
            ["NextOptions"] = {
                [1] = 510073031,
                [2] = 510073032,
                },
            ["SpeakNpcId"] = 700077,
            },
        [51007304] = {
            ["Content"] = "我是阿特拉西亚大陆考古协会，帝国分会的研究员，最近交上去的学术报告总是被“感受不到欲望”为由打回来。",
            ["ContentJP"] = "私はアトラシア大陸考古協会帝国支部に所属する研究員よ。ここ最近、提出した調査報告がことごとく差し戻されるの。決まり文句はいつも同じ——「欲望が感じられない」ってね。",
            ["DialogueId"] = 51007304,
            ["GUID"] = "7FB101D0",
            ["NextDialogue"] = 51007305,
            ["SpeakNpcId"] = 700077,
            },
        [51007305] = {
            ["Content"] = "哎……真是搞不懂投资人的要求……",
            ["ContentJP"] = "はあ…投資家が何を求めてるのか、正直わからないわ。",
            ["DialogueId"] = 51007305,
            ["GUID"] = "7FB101FA",
            ["NextDialogue"] = 51007306,
            ["SpeakNpcId"] = 700077,
            },
        [51007306] = {
            ["Content"] = "什么投资人居然还懂学术？",
            ["ContentJP"] = "学問のある投資家なんて初耳だ{性别:な|ね}？",
            ["DialogueId"] = 51007306,
            ["GUID"] = "7FB10224",
            ["NextDialogue"] = 51007307,
            ["SpeakNpcId"] = 100001,
            },
        [51007307] = {
            ["Content"] = "虬先生可不是一般的投资人，卢卡的百年沉船、艾利西安的千年遗迹、海伯利亚的战争遗址等等考古学重大发现都是他亲自找到的。",
            ["ContentJP"] = "キョウンさんは、ただの投資者じゃないの。ルッカの「百年前の沈没船」、エリュシオンの「千年前の遺跡」、ヒュペリアの「戦争遺跡」など。考古学に関する様々な歴史的な発見を成し遂げたんだよ。",
            ["DialogueId"] = 51007307,
            ["GUID"] = "7FB1024E",
            ["NextDialogue"] = 51007308,
            ["SpeakNpcId"] = 700077,
            },
        [51007308] = {
            ["Content"] = "（雪莉眼含崇拜，滔滔不绝地向你讲述虬先生的过往。）",
            ["ContentJP"] = "（シェリーは崇敬の色を湛えた目で、キョウンの過去を次々と語り出してる。）",
            ["DialogueId"] = 51007308,
            ["GUID"] = "7FB10278",
            ["NextDialogue"] = 51007309,
            },
        [51007309] = {
            ["Content"] = "虬先生是大陆考古协会的总投资人，更是一名伟大的考古学家与大收藏家。甚至还有传言说他是行走在华胥“阴影”中的君主……",
            ["ContentJP"] = "キョウンは大陸考古協会の筆頭出資者であり、同時に偉大な考古学者にして蒐集家だ。キョウンこそ、華胥の「影」歩む君主だ——なんて噂さえ絶えないの。",
            ["DialogueId"] = 51007309,
            ["GUID"] = "7FB102A2",
            ["NextDialogue"] = 51007310,
            ["SpeakNpcId"] = 700077,
            },
        [51007310] = {
            ["Content"] = "要是没有他的幕后资助，考古协会根本发展不成遍布大陆各个角落的庞大组织。",
            ["ContentJP"] = "彼の支援がなければ、考古協会がいまのように大陸全土へ広がる組織には育たなかったでしょう。",
            ["DialogueId"] = 51007310,
            ["GUID"] = "7FB102CC",
            ["NextDialogue"] = 51007311,
            ["SpeakNpcId"] = 700077,
            },
        [51007311] = {
            ["Content"] = "唉……他老人家之前都不怎么管的，怎么突然又抓起我们考古协会不放了，华胥那边的退休生活这么清闲吗？",
            ["ContentJP"] = "はあ…これまでほとんど口出ししなかったのに、どうして急にこちらに絡んでくるの？華胥の隠居暮らしって、そんなに暇なのかしら。",
            ["DialogueId"] = 51007311,
            ["GUID"] = "7FB102F6",
            ["NextDialogue"] = 51007312,
            ["SpeakNpcId"] = 700077,
            },
        [51007312] = {
            ["Content"] = "能看看你的报告吗？",
            ["ContentJP"] = "その報告、見せてもらえる？",
            ["DialogueId"] = 51007312,
            ["GUID"] = "7FB10320",
            ["NextDialogue"] = 51007313,
            ["SpeakNpcId"] = 100001,
            },
        [51007313] = {
            ["Content"] = "好啊，《冰湖城酒馆客流变化的简要分析》、《水仙平原饮品技术工艺演变》，《自称魔王的皎皎的观察记录》，要看哪个？",
            ["ContentJP"] = "いいわ、『アイスレイク城酒場の客足の変動におけるシンプルデータアナリシス』、「アスフォデロスのドリンクのテクノロジーとレシピの進化」、「ルーナ族の魔王（自称）の観察日記」。どれが見たい？",
            ["DialogueId"] = 51007313,
            ["GUID"] = "7FB1034A",
            ["NextOptions"] = {
                [1] = 510073131,
                [2] = 510073132,
                },
            ["SpeakNpcId"] = 700077,
            },
        [51007314] = {
            ["Content"] = "这也没办法呀，冰湖城冰天雪地的啥都挖不出来，所以写不了什么正常的考古报告嘛！",
            ["ContentJP"] = "しょうがないよ。アイスレイク城の雪の下からは何も出てこないのよ。これでどうやって、まともな考古学の調査報告を書けっていうの？",
            ["DialogueId"] = 51007314,
            ["GUID"] = "7FB10374",
            ["NextOptions"] = {
                [1] = 510073141,
                },
            ["SpeakNpcId"] = 700077,
            },
        [51007315] = {
            ["Content"] = "也许你缺一个合适的向导。",
            ["ContentJP"] = "案内役でも探したら？",
            ["DialogueId"] = 51007315,
            ["FailDialogue"] = 510073151,
            ["GUID"] = "7FB1039E",
            ["ImprCheckId"] = 1061,
            ["NextDialogue"] = 510073152,
            },
        [51007316] = {
            ["Content"] = "拜托你不要放弃我！",
            ["ContentJP"] = "お願い、私を見捨てないで。",
            ["DialogueId"] = 51007316,
            ["GUID"] = "7FB103C8",
            ["SpeakNpcId"] = 700077,
            },
        [51007317] = {
            ["Content"] = "好复杂的下水道，要不是你带我进来肯定会迷路。",
            ["ContentJP"] = "ここの下水道、ほんとうに迷路ね。あなたが案内してくれなかったら、きっと迷ってたわ。",
            ["DialogueId"] = 51007317,
            ["GUID"] = "7FB103F2",
            ["NextDialogue"] = 51007318,
            ["SpeakNpcId"] = 700172,
            },
        [51007318] = {
            ["Content"] = "我偶尔也会迷路。",
            ["ContentJP"] = "{性别:僕|私}もたまに迷子になる{性别:んだ|の}。",
            ["DialogueId"] = 51007318,
            ["GUID"] = "7FB1041C",
            ["NextDialogue"] = 51007319,
            ["SpeakNpcId"] = 100001,
            },
        [51007319] = {
            ["Content"] = "嗯……就连经常来下水道探险的狩月人也会迷路，这个下水道的规模也太过巨大了。",
            ["ContentJP"] = "あなたみたいな月狩り人でも迷うくらいなら、ここは相当広いのね。",
            ["DialogueId"] = 51007319,
            ["GUID"] = "7FB10446",
            ["NextDialogue"] = 51007320,
            ["SpeakNpcId"] = 700172,
            },
        [51007320] = {
            ["Content"] = "对了，在海伯利亚的官方正史里，他们国家最早就是在冰湖城建立的。所以才会有这么一个和地面建筑差不多大的下水道吧。",
            ["ContentJP"] = "ヒュペリア正史の記すところでは、アイスレイク城はこの国が最初に根を下ろしたところ。だからここの下水道は、地上の街に匹敵するくらい大きいのかもしれない。",
            ["DialogueId"] = 51007320,
            ["GUID"] = "7FB10447",
            ["NextDialogue"] = 51007321,
            ["SpeakNpcId"] = 700172,
            },
        [51007321] = {
            ["Content"] = "感觉这里的墙壁要更古老一些。",
            ["ContentJP"] = "このあたりの壁は古いね。",
            ["DialogueId"] = 51007321,
            ["GUID"] = "7FB10470",
            ["NextDialogue"] = 51007322,
            ["SpeakNpcId"] = 100001,
            },
        [51007322] = {
            ["Content"] = "应该是随着当时冰湖城的扩建不断完善的吧，好像冰湖城一开始是就是一个卡戎的定居点……",
            ["ContentJP"] = "きっとアイスレイク城の拡張に合わせて継ぎ足されてきたのよ。そもそもアイスレイク城自体、カロン族の集落から始まったって聞いたし。",
            ["DialogueId"] = 51007322,
            ["GUID"] = "7FB1049A",
            ["NextDialogue"] = 51007323,
            ["SpeakNpcId"] = 700172,
            },
        [51007323] = {
            ["Content"] = "啊，你这倒提醒我了，虽然外面的是冻土终年封冻，地面的建筑不断翻新，但是下水道说不定没有彻底翻新过。",
            ["ContentJP"] = "あ、そうだ。永久凍土のせいで地上の建物はどんどん建て替わるけれど、地下の一部は、昔の姿がそのままに残っているかもしれない。",
            ["DialogueId"] = 51007323,
            ["GUID"] = "7FB104C4",
            ["NextDialogue"] = 510073231,
            ["SpeakNpcId"] = 700172,
            },
        [51007325] = {
            ["Content"] = "呜啊啊啊，这里也太高了吧，也不知道和华胥的执律阁比起来哪个高……我恐高症要犯了！",
            ["ContentJP"] = "ひゃあ……高すぎ！華胥の執律閣より高いのかどうか……いや、だめ、また高所恐怖症がぶり返してきた……",
            ["DialogueId"] = 51007325,
            ["GUID"] = "7FB10542",
            ["NextDialogue"] = 51007326,
            ["SpeakNpcId"] = 700173,
            },
        [51007326] = {
            ["Content"] = "你先别看外面，盯着脚底下看一会儿缓一下吧。",
            ["ContentJP"] = "足元に見つめて落ち着いて。外を見ないほうがいい",
            ["DialogueId"] = 51007326,
            ["GUID"] = "7FB1056C",
            ["NextDialogue"] = 51007327,
            ["SpeakNpcId"] = 100001,
            },
        [51007327] = {
            ["Content"] = "呼，呼……好多了。",
            ["ContentJP"] = "ふぅ、ふぅ……よし、だいぶ落ち着いた。",
            ["DialogueId"] = 51007327,
            ["GUID"] = "7FB10596",
            ["NextDialogue"] = 51007328,
            ["SpeakNpcId"] = 700173,
            },
        [51007328] = {
            ["Content"] = "真是的，当初帝国这帮人到底想什么，要修这么高的城墙。",
            ["ContentJP"] = "それにしても、当時の帝国の建築家は何を考えてたの？どうしてこんな高さの城壁を……。",
            ["DialogueId"] = 51007328,
            ["GUID"] = "7FB105C0",
            ["NextDialogue"] = 51007329,
            ["SpeakNpcId"] = 700173,
            },
        [51007329] = {
            ["Content"] = "？",
            ["ContentJP"] = "？",
            ["DialogueId"] = 51007329,
            ["GUID"] = "7FB105EA",
            ["NextDialogue"] = 51007330,
            ["SpeakNpcId"] = 700173,
            },
        [51007330] = {
            ["Content"] = "对哦，为什么呢？我记得按照帝国正史记载的话，冰湖城最初是卡戎人的聚落。",
            ["ContentJP"] = "どうして…ええと、正史の記述どおりなら、この城はもともとカロン族の集落から始まったはずよ。",
            ["DialogueId"] = 51007330,
            ["GUID"] = "7FB10614",
            ["NextDialogue"] = 51007331,
            ["SpeakNpcId"] = 700173,
            },
        [51007331] = {
            ["Content"] = "初代皇帝迪斯·盖雷亚，也就是迪斯一世在大迁徙后到了这附近，想要和这里的卡戎部落和平相处，但是他的弟弟却被这里的卡戎以宴会的名义诱杀了。",
            ["ContentJP"] = "大移住ののち、初代皇帝ディズ一世・ガレアこの地に来て、まずはカロン族と和を結ぼうとした。けれど弟君が饗応の約束に気を許して、カロン族に討たれてしまったの。",
            ["DialogueId"] = 51007331,
            ["GUID"] = "7FB1063E",
            ["NextDialogue"] = 51007333,
            ["SpeakNpcId"] = 700173,
            },
        [51007333] = {
            ["Content"] = "所以迪斯一世才会认定卡戎们是一群恶魔，率领着他的骑士团征服了附近的卡戎，带来了所谓的银色和平。",
            ["ContentJP"] = "それでディズ一世はカロン族を「悪魔」と見なし、騎士団を率いて鎮圧して、いわゆる『シルバー・ピース』を宣言した――というわけ。",
            ["DialogueId"] = 51007333,
            ["GUID"] = "7FB10692",
            ["NextDialogue"] = 51007334,
            ["SpeakNpcId"] = 700173,
            },
        [51007334] = {
            ["Content"] = "但如果是这样的话，这么高大的城墙，是要防备谁呢？是秽兽吗？还是说当时那些卡戎还在继续反抗？",
            ["ContentJP"] = "だとしたら、このそびえる城壁は誰に向けられていたの？穢獣？それとも当時のカロン族はまだ抗っていたのかしら。",
            ["DialogueId"] = 51007334,
            ["GUID"] = "7FB106BC",
            ["NextDialogue"] = 51007335,
            ["SpeakNpcId"] = 700173,
            },
        [51007335] = {
            ["Content"] = "看来你又获得了灵感？",
            ["ContentJP"] = "ひらめいた？",
            ["DialogueId"] = 51007335,
            ["GUID"] = "7FB106E6",
            ["NextDialogue"] = 51007336,
            ["SpeakNpcId"] = 100001,
            },
        [51007336] = {
            ["Content"] = "灵感说不上啦，但是就是感到有一些奇怪，但是虬先生有教导我们说，不要放过任何感到奇怪的时刻，那里潜藏着真相。",
            ["ContentJP"] = "ひらめきってほどじゃないけど、どこか引っかかるの。キョウンがいつも言ってたわ――違和感を見過ごすな、真実はそこに潜むって。",
            ["DialogueId"] = 51007336,
            ["GUID"] = "7FB10710",
            ["NextDialogue"] = 51007339,
            ["SpeakNpcId"] = 700173,
            },
        [51007339] = {
            ["Content"] = "总之谢谢，谢谢！现在的我感觉能写出有意思的考察报告了！",
            ["ContentJP"] = "ともあれ、本当にありがとう。これなら面白い報告書が書けそうだわ！",
            ["DialogueId"] = 51007339,
            ["GUID"] = "7FB1078E",
            ["NextDialogue"] = 51007340,
            ["SpeakNpcId"] = 700173,
            },
        [51007340] = {
            ["Content"] = "如果没有你，我肯定像个傻瓜一样，认为冰湖城这破冻土没什么考古价值，然后像之前那样糊弄下去。",
            ["ContentJP"] = "あなたがいなかったら、ここには考古学的価値なんてないって勝手に決めつけて、肝心なことを見落とした浅い報告を書いてたと思う。",
            ["DialogueId"] = 51007340,
            ["GUID"] = "7FB107B8",
            ["NextDialogue"] = 51007341,
            ["SpeakNpcId"] = 700173,
            },
        [51007341] = {
            ["Content"] = "是我太浅薄了！难道说，您就是潜藏在冰湖城的考古大师！",
            ["ContentJP"] = "私ってなんて目が狭かったの……。ねえ、もしかしてあなたは、アイスレイク城に隠居した大物の考古学マスターでしょうか？",
            ["DialogueId"] = 51007341,
            ["GUID"] = "7FB107E2",
            ["NextOptions"] = {
                [1] = 510073411,
                [2] = 510073412,
                [3] = 510073413,
                },
            ["SpeakNpcId"] = 700173,
            ["bForbidSkipOptions"] = true,
            },
        }
  end },
  { MinKey = 51007342, MaxKey = 51007694, Loader = function()
      return {
        [51007342] = {
