                [3] = 510073843,
                },
            },
        [51007388] = {
            ["Content"] = "别看我现在这样，在几年前，大多数人还是会尊敬地叫我“达顿医生”。",
            ["ContentJP"] = "こう見えても。数年前まで、うやうやしく「ダートン先生」って呼ばれてたんだぜ。",
            ["DialogueId"] = 51007388,
            ["GUID"] = "7FB10F98",
            ["NextDialogue"] = 51007389,
            ["SpeakNpcId"] = 700069,
            },
        [51007389] = {
            ["Content"] = "你应该明白作为一个出生在贫民区的卡戎人，这个称呼有怎样特别的意义吧。",
            ["ContentJP"] = "あんただってわかるだろ。スラム街出身のカロンにとって、そんな風に呼ばれるのがどれほど意味があることか。",
            ["DialogueId"] = 51007389,
            ["GUID"] = "7FB10FC2",
            ["NextDialogue"] = 51007390,
            ["SpeakNpcId"] = 700069,
            },
        [51007390] = {
            ["Content"] = "我在中心医院给数不清的卡戎人看病，甚至有贵族慕名请我问诊。",
            ["ContentJP"] = "俺は中央病院に務めてたんだ。カロン族の患者は数え切れないほど診てきたし、貴族に往診を頼まれたことだってある。",
            ["DialogueId"] = 51007390,
            ["GUID"] = "7FB10FEC",
            ["NextDialogue"] = 51007391,
            ["SpeakNpcId"] = 700069,
            },
        [51007391] = {
            ["Content"] = "不信的话你可以问问年轻一辈的卡戎小孩，他们父母以前最常说的话就是让这帮孩子向我好好学习。",
            ["ContentJP"] = "信じられないなら、カロン族の若者に訊いてみるといい。子供の頃、親から「あの人を見習いなさい」ってお手本にされていたのは誰だったか。",
            ["DialogueId"] = 51007391,
            ["GUID"] = "7FB11016",
            ["NextDialogue"] = 51007392,
            ["SpeakNpcId"] = 700069,
            },
        [51007392] = {
            ["Content"] = "那时候我可有着不轻的洁癖呢，地砖缝但凡有一点灰尘都受不了......",
            ["ContentJP"] = "あの頃の俺はかなりの潔癖症でな。床のタイルの隙間に少しでもホコリがあると我慢できなかったんだが……",
