            ["DialogueId"] = 51007398,
            ["GUID"] = "7FB1113C",
            ["NextDialogue"] = 51007399,
            ["SpeakNpcId"] = 700069,
            },
        [51007399] = {
            ["Content"] = "想知道结局是什么？等我修完下水道那几条破管子着，还是说你要跟我一起？",
            ["ContentJP"] = "それでどうなったのか知りたいか？まずはそこのスパナを取ってくれ――",
