            ["NextDialogue"] = 51007512,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007512] = {
            ["Content"] = "是这样的，我正在开展一项针对卡戎之民的实验调查，恭喜你被选中成为我的第一个实验对象！",
            ["ContentJP"] = "実は今、カロン向けの実験調査をやってるんだ。あなたが最初の協力者ってわけ！",
            ["DialogueId"] = 51007512,
            ["GUID"] = "7FB123F0",
            ["NextDialogue"] = 51007513,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007513] = {
            ["Content"] = "为什么选我？",
            ["ContentJP"] = "{性别:どうして僕？|どうして私？}",
            ["DialogueId"] = 51007513,
            ["GUID"] = "7FB1241A",
            ["NextDialogue"] = 51007514,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Think_Start",
                },
            },
        [51007514] = {
            ["Content"] = "是随机抽选的哦，这样才能排除主观因素影响！",
            ["ContentJP"] = "偶然だよ！無作為に選ばないと、偏りが出ちゃうからね！",
            ["DialogueId"] = 51007514,
            ["GUID"] = "7FB12444",
            ["NextDialogue"] = 51007515,
            ["SpeakNpcId"] = 700011,
            },
        [51007515] = {
            ["Content"] = "咳咳，请先告诉我你的名字吧。",
            ["ContentJP"] = "えっと、まずあなたの名前を教えて。",
            ["DialogueId"] = 51007515,
            ["GUID"] = "7FB1246E",
            ["NextOptions"] = {
                [1] = 51007516,
                [2] = 51007519,
                },
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_End",
                },
            },
        [51007516] = {
            ["Content"] = "我叫诞生于净界岛·重生之焰·冰湖城守护者·光荣的·{nickname}。",
            ["ContentJP"] = "{性别:僕|私}は、パーガトリー島生まれ、再生の炎にして、アイスレイク城の守護者、栄光なる——{nickname}{性别:だよ|よ}。",
            ["DialogueId"] = 51007516,
            ["GUID"] = "7FB12498",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007517,
            ["Scripts"] = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_1\"}}",
            },
        [51007517] = {
            ["Content"] = "啊，请你说慢点……！那么，诞生于净界岛·重生……诞……蛋……",
            ["ContentJP"] = "え、ええっと……え？パーガトリー島生まれで、再生の炎、アイスレイクの……シュシュ……",
            ["DialogueId"] = 51007517,
            ["GUID"] = "7FB124C2",
            ["NextDialogue"] = 51007518,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Talk01_Start",
                },
            },
        [51007518] = {
            ["Content"] = "呜，好难念！方便起见我就叫你{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}好了。",
            ["ContentJP"] = "うう、長い！じゃあ、{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}って呼ぶね！",
            ["DialogueId"] = 51007518,
            ["GUID"] = "7FB124EC",
            ["NextDialogue"] = 51007522,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007519] = {
            ["Content"] = "我叫西比尔。",
            ["ContentJP"] = "シビルだよ。",
            ["DialogueId"] = 51007519,
            ["GUID"] = "7FB12516",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007520,
            ["Scripts"] = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_2\"}}",
            },
        [51007520] = {
            ["Content"] = "总觉得这个名字有点耳熟，从哪里听过来着……",
            ["ContentJP"] = "なんか聞き覚えあるような……まあいいや！",
            ["DialogueId"] = 51007520,
            ["GUID"] = "7FB12540",
            ["NextDialogue"] = 51007521,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Think_Start",
                },
            },
        [51007521] = {
            ["Content"] = "算了，不重要。{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我们开始吧。",
            ["ContentJP"] = "じゃあ、{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、始めよっか！",
            ["DialogueId"] = 51007521,
            ["GUID"] = "7FB1256A",
            ["NextDialogue"] = 51007522,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007522] = {
            ["Content"] = "放心，实验内容很简单，你只要填完这个调查问卷就行了！",
            ["ContentJP"] = "安心して、実験は簡単！このアンケートに答えるだけだから！",
            ["DialogueId"] = 51007522,
            ["GUID"] = "7FB12594",
            ["NextDialogue"] = 51007523,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007523] = {
            ["Content"] = "（男孩双手捧起一沓厚厚的纸递给了你。）",
            ["ContentJP"] = "少年は抱える分厚い紙の束を、両手で差し出してきた。",
            ["DialogueId"] = 51007523,
            ["GUID"] = "7FB125BE",
            ["NextDialogue"] = 51007524,
            },
        [51007524] = {
            ["Content"] = "（纸张的边缘并不整齐，似乎是从作业本上撕下来的；纸上是用稚嫩但工整的字体写下的一长串问题，序号甚至标到了三位数。）",
            ["ContentJP"] = "紙は雑にちぎられていて、稚拙だけど丁寧な字でびっしり内容が書かれている。質問の数は三桁に優に超えているだろう。",
            ["DialogueId"] = 51007524,
            ["GUID"] = "7FB125E8",
            ["NextOptions"] = {
                [1] = 51007525,
                [2] = 51007527,
                [3] = 51007529,
                },
            },
        [51007525] = {
            ["Content"] = "你这问卷未免也太长了吧……",
            ["ContentJP"] = "……これ、ちょっと多すぎない？",
            ["DialogueId"] = 51007525,
            ["GUID"] = "7FB12612",
            ["NextDialogue"] = 51007526,
            },
        [51007526] = {
            ["Content"] = "也还好吧，只有七百七十七个问题哦！",
            ["ContentJP"] = "えー？たったの777問しかないよ！",
            ["DialogueId"] = 51007526,
            ["GUID"] = "7FB1263C",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007527] = {
            ["Content"] = "这个长度的问卷要加钱。",
            ["ContentJP"] = "このボリュームなら追加報酬ほしいな。",
            ["DialogueId"] = 51007527,
            ["GUID"] = "7FB12666",
            ["NextDialogue"] = 51007528,
            },
        [51007528] = {
            ["Content"] = "啊……可是我已经没有多的钱了……可以分期付款吗？",
            ["ContentJP"] = "えぇ〜……そんなにお小遣いないんだけど。分割払いでもいい？",
            ["DialogueId"] = 51007528,
            ["GUID"] = "7FB12690",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007529] = {
            ["Content"] = "好的，我争取十年内填完。",
            ["ContentJP"] = "よし、じゃあ十年かけて答える！",
            ["DialogueId"] = 51007529,
            ["GUID"] = "7FB126BA",
            ["NextDialogue"] = 51007530,
            },
        [51007530] = {
            ["Content"] = "咦？！那也太久了吧！",
            ["ContentJP"] = "そ、それは長すぎるよ〜！",
            ["DialogueId"] = 51007530,
            ["GUID"] = "7FB126E4",
            ["NextDialogue"] = 51007531,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Explain01_Start",
                },
            },
        [51007531] = {
            ["Content"] = "拜托你答应我吧，冰湖城有这么多的卡戎，偏偏是你成为了我随机选中的那个观察目标，这可是天大的运气呢！",
            ["ContentJP"] = "お願いだよ！アイスレイク城にはカロンがたくさんいるのに、あなたが選ばれるなんて……ものすごい幸運だと思わない！？",
            ["DialogueId"] = 51007531,
            ["GUID"] = "7FB1270E",
            ["NextDialogue"] = 51007532,
            ["SpeakNpcId"] = 700011,
            },
        [51007532] = {
            ["Content"] = "（此时，一个高大的卡戎之民从你们旁边路过，男孩的身影在一瞬间消失不见了。你转过头，发现他缩进了你身后的阴影里。）",
            ["ContentJP"] = "その時、大柄なカロン族が横を通り過ぎ、少年の姿が一瞬で消えた。振り返ると、少年はあなたの背後の影に隠れていた。",
            ["DialogueId"] = 51007532,
            ["GUID"] = "7FB12738",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007533,
            },
        [51007533] = {
            ["Content"] = "（高大的卡戎之民离开后，男孩又在一瞬间回到了原来的站立位置，仿佛什么都没发生过那样。）",
            ["ContentJP"] = "カロン族が離れていくと、少年はまたすぐ元の場所に戻ってきた。まるで最初からそこにいたかのように。",
            ["DialogueId"] = 51007533,
            ["GUID"] = "7FB12762",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51007534,
            },
        [51007534] = {
            ["Content"] = "好不好嘛，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}？",
            ["ContentJP"] = "ねえねえ、いいでしょ？{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！",
            ["DialogueId"] = 51007534,
            ["GUID"] = "7FB1278C",
            ["NextDialogue"] = 51007535,
            ["SpeakNpcId"] = 700011,
            },
        [51007535] = {
            ["Content"] = "你刚才是在害怕吗？",
            ["ContentJP"] = "さっき、もしかして怖がってた？",
            ["DialogueId"] = 51007535,
            ["GUID"] = "7FB127B6",
            ["NextDialogue"] = 51007536,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007536] = {
            ["Content"] = "才、才没有呢！我、我只是……担心不打招呼会显得不礼貌而已！",
            ["ContentJP"] = "ち、違うもん！ぼ、僕は……その……ちゃんと挨拶しないと失礼かなって思っただけだよ！",
            ["DialogueId"] = 51007536,
            ["GUID"] = "7FB127E0",
            ["NextDialogue"] = 51007537,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007537] = {
            ["Content"] = "研究者不能撒谎。",
            ["ContentJP"] = "研究者が嘘をついちゃだめだよ。",
            ["DialogueId"] = 51007537,
            ["GUID"] = "7FB1280A",
            ["NextDialogue"] = 51007538,
            ["SpeakNpcId"] = 100001,
            },
        [51007538] = {
            ["Content"] = "呃……可、可能是有一点点点点害怕……总之，这些小事不重要啦！",
            ["ContentJP"] = "うぅ……か、かもね……ちょっとだけ、ほんのちょっとだけ怖かったかも……。でも、そんなのどうでもいいってば！",
            ["DialogueId"] = 51007538,
            ["GUID"] = "7FB12834",
            ["NextDialogue"] = 51007539,
            ["SpeakNpcId"] = 700011,
            },
        [51007539] = {
            ["Content"] = "刚才说到哪儿了……噢，对了，问卷！如果你实在不愿意填的话，我就挑几个重要的问题问吧，你只要口头回答就行了！",
            ["ContentJP"] = "えっと、それより……あ、そうだ、アンケート！もし答えてくれるなら、大事な質問をいくつか選ぶよ！口頭で答えてくれるだけでいいから！",
            ["DialogueId"] = 51007539,
            ["GUID"] = "7FB1285E",
            ["NextDialogue"] = 51007540,
            ["SpeakNpcId"] = 700011,
            },
        [51007540] = {
            ["Content"] = "如果你现在有空的话，我们就立刻开始问答吧？",
            ["ContentJP"] = "もし今時間があるなら、すぐに始めよう？",
            ["DialogueId"] = 51007540,
            ["GUID"] = "7FB12888",
            ["SpeakNpcId"] = 700011,
            },
        [51007543] = {
            ["Content"] = "好耶！那就听好咯——",
            ["ContentJP"] = "やったー！それじゃ、いくよ！",
            ["DialogueId"] = 51007543,
            ["GUID"] = "7FB12906",
            ["NextDialogue"] = 51007544,
            ["SpeakNpcId"] = 700011,
            },
        [51007544] = {
            ["Content"] = "问题1：你为什么只有一只角？",
            ["ContentJP"] = "質問1：どうしてあなたには角が一本しかないの？",
            ["DialogueId"] = 51007544,
            ["GUID"] = "7FB12930",
            ["NextOptions"] = {
                [1] = 51007545,
                [2] = 51007547,
                [3] = 51007550,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007545] = {
            ["Content"] = "生来就是这样。",
            ["ContentJP"] = "生まれつきだよ。",
            ["DialogueId"] = 51007545,
            ["GUID"] = "7FB1295A",
            ["NextDialogue"] = 51007546,
            },
        [51007546] = {
            ["Content"] = "噢，所以是先天的差异……",
            ["ContentJP"] = "生まれつき……そっか、先天性なものなんだね。",
            ["DialogueId"] = 51007546,
            ["GUID"] = "7FB12984",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007547] = {
            ["Content"] = "另一只被我卖掉换钱了。",
            ["ContentJP"] = "もう一本はお金に換えた。",
            ["DialogueId"] = 51007547,
            ["GUID"] = "7FB129AE",
            ["NextDialogue"] = 51007548,
            },
        [51007548] = {
            ["Content"] = "咦，还能这样？！",
            ["ContentJP"] = "ええっ、売ったの！？そんなのアリ！？",
            ["DialogueId"] = 51007548,
            ["GUID"] = "7FB129D8",
            ["NextDialogue"] = 51007549,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Shock_Start",
                },
            },
        [51007549] = {
            ["Content"] = "好想买一个用来研究啊……",
            ["ContentJP"] = "うう、研究用に一本欲しかったなあ……",
            ["DialogueId"] = 51007549,
            ["GUID"] = "7FB12A02",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            },
        [51007550] = {
            ["Content"] = "只有聪明的孩子才能看到另一只。",
            ["ContentJP"] = "もう一本は賢い子にしか見えないんだよ。",
            ["DialogueId"] = 51007550,
            ["GUID"] = "7FB12A2C",
            ["NextDialogue"] = 51007551,
            },
        [51007551] = {
            ["Content"] = "……我才不会信这种骗小孩的话呢。",
            ["ContentJP"] = "……そんな子供だまし、信じないぞ。",
            ["DialogueId"] = 51007551,
            ["GUID"] = "7FB12A56",
            ["NextDialogue"] = 51007552,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Disagree",
                },
            },
        [51007552] = {
            ["Content"] = "不过，原来卡戎也会开玩笑啊……",
            ["ContentJP"] = "でも、カロンも冗談とか言うんだね。",
            ["DialogueId"] = 51007552,
            ["GUID"] = "7FB12A80",
            ["NextDialogue"] = 51007553,
            ["SpeakNpcId"] = 700011,
            },
        [51007553] = {
            ["Content"] = "嗯……下面是问题2：你的角摸起来是什么感觉，可以切一片给我摸摸吗？",
            ["ContentJP"] = "うーん、じゃあ次の質問ね！質問2：あなたの角って、どんな感触？少しだけ切って触らせてもらえない？",
            ["DialogueId"] = 51007553,
            ["GUID"] = "7FB12AAA",
            ["NextOptions"] = {
                [1] = 51007554,
                [2] = 51007556,
                [3] = 51007558,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007554] = {
            ["Content"] = "会痛，不可以。",
            ["ContentJP"] = "痛いからダメだよ。",
            ["DialogueId"] = 51007554,
            ["GUID"] = "7FB12AD4",
            ["NextDialogue"] = 51007555,
            },
        [51007555] = {
            ["Content"] = "对不起！……不过，原来恶魔的孩子也会感到痛吗，好像和爸爸说的不太一样……",
            ["ContentJP"] = "ご、ごめんなさい！……でも、悪魔の子でも痛みを感じるんだ……パパが言ってたのと違うなあ……",
            ["DialogueId"] = 51007555,
            ["GUID"] = "7FB12AFE",
            ["NextDialogue"] = 51007562,
            ["SpeakNpcId"] = 700011,
            },
        [51007556] = {
            ["Content"] = "一片三万银币。",
            ["ContentJP"] = "三万銀貨だよ。",
            ["DialogueId"] = 51007556,
            ["GUID"] = "7FB12B28",
            ["NextDialogue"] = 51007557,
            },
        [51007557] = {
            ["Content"] = "诶诶诶——？那、那就算了吧……",
            ["ContentJP"] = "えええ！？そんなに高いの！？……やっぱりやめとくよ……",
            ["DialogueId"] = 51007557,
            ["GUID"] = "7FB12B52",
            ["NextDialogue"] = 51007562,
            ["SpeakNpcId"] = 700011,
            },
        [51007558] = {
            ["Content"] = "摸了会中毒哦。",
            ["ContentJP"] = "触ると毒にやられるよ。",
            ["DialogueId"] = 51007558,
            ["GUID"] = "7FB12B7C",
            ["NextDialogue"] = 51007559,
            },
        [51007559] = {
            ["Content"] = "真的吗？毒性有多大呢？有解毒的方法吗？你自己也会中毒吗？",
            ["ContentJP"] = "毒！？どんな毒！？治療法は！？あなたもやられるの！？",
            ["DialogueId"] = 51007559,
            ["GUID"] = "7FB12BA6",
            ["NextDialogue"] = 51007560,
            ["SpeakNpcId"] = 700011,
            },
        [51007560] = {
            ["Content"] = "……没毒，只是开个玩笑。但是受伤会痛，所以不可以切。",
            ["ContentJP"] = "嘘だよ。毒はないけど、切られると痛いからダメ。",
            ["DialogueId"] = 51007560,
            ["GUID"] = "7FB12BD0",
            ["NextDialogue"] = 51007561,
            ["SpeakNpcId"] = 100001,
            },
        [51007561] = {
            ["Content"] = "对不起！……不过，原来恶魔的孩子也会感到痛吗，好像和爸爸说的不太一样……",
            ["ContentJP"] = "ご、ごめんなさい！……でも、悪魔の子でも痛みを感じるんだ……パパが言ってたのと違うなあ……",
            ["DialogueId"] = 51007561,
            ["GUID"] = "7FB12BFA",
            ["NextDialogue"] = 51007562,
            ["SpeakNpcId"] = 700011,
            },
        [51007562] = {
            ["Content"] = "既然你们是恶魔的孩子，那你的爸爸妈妈长什么样啊，是不是超凶的那种……可以把人一口吞掉？",
            ["ContentJP"] = "あなたたちが悪魔の子なら、お父さんとお母さんはどんな見た目なの？もしかして、とってもおっかなくて、一口で人を丸のみしちゃうような姿とか？",
            ["DialogueId"] = 51007562,
            ["GUID"] = "7FB12C24",
            ["NextOptions"] = {
                [1] = 51007563,
                [2] = 51007565,
                [3] = 51007567,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007563] = {
            ["Content"] = "应该只是普普通通的卡戎吧。",
            ["ContentJP"] = "たぶん普通のカロン族だと思う。",
            ["DialogueId"] = 51007563,
            ["GUID"] = "7FB12C4E",
            ["NextDialogue"] = 51007564,
            },
        [51007564] = {
            ["Content"] = "这样啊……没劲。",
            ["ContentJP"] = "そっかぁ……普通か……つまんないなぁ。",
            ["DialogueId"] = 51007564,
            ["GUID"] = "7FB12C78",
            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007565] = {
            ["Content"] = "不知道，我没见过他们。",
            ["ContentJP"] = "知らない、会ったことない。",
            ["DialogueId"] = 51007565,
            ["GUID"] = "7FB12CA2",
            ["NextDialogue"] = 51007566,
            },
        [51007566] = {
            ["Content"] = "“亲眼见过才能给出答案”——看来你也很有研究者的天赋嘛！",
            ["ContentJP"] = "「自分の目で見たことしか答えない」——うんうん、あなた、すごくいい研究者になれるよ！",
            ["DialogueId"] = 51007566,
            ["GUID"] = "7FB12CCC",
            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007567] = {
            ["Content"] = "是精灵。",
            ["ContentJP"] = "妖精だった。",
            ["DialogueId"] = 51007567,
            ["GUID"] = "7FB12CF6",
            ["NextDialogue"] = 51007568,
            },
        [51007568] = {
            ["Content"] = "哎，和我之前见过的哥哥说的一样！",
            ["ContentJP"] = "えっ、妖精！？あ、でもね、僕も前に会ったお兄さんから同じこと聞いたことがある！",
            ["DialogueId"] = 51007568,
            ["GUID"] = "7FB12D20",
            ["NextDialogue"] = 51007569,
            ["SpeakNpcId"] = 700011,
            },
        [51007569] = {
            ["Content"] = "几年前我遇到过一个很友善的卡戎哥哥，他对我说自己是“精灵”。",
            ["ContentJP"] = "何年か前、すごく優しいカロンのお兄さんに出会ったんだ。彼、自分のことを「妖精」って名乗ってたんだよ。",
            ["DialogueId"] = 51007569,
            ["GUID"] = "7FB12D4A",
            ["NextDialogue"] = 51007570,
            ["SpeakNpcId"] = 700011,
            },
        [51007570] = {
            ["Content"] = "他当时急着去见什么人，我就没来得及细问……",
            ["ContentJP"] = "でも、その人、すぐに誰かに会いに行っちゃって……それっきり、もう会えなかったんだ。",
            ["DialogueId"] = 51007570,
            ["GUID"] = "7FB12D74",
            ["NextDialogue"] = 51007571,
            ["SpeakNpcId"] = 700011,
            },
        [51007571] = {
            ["Content"] = "但关于卡戎的来源，他是第一个给我不同回答的人，所以我一直很在意。可惜后来我再也没见到他了。",
            ["ContentJP"] = "でも、彼は最初にカロンのことを答えてくれた人だから、とっても気になってたんだ。それで、いろんな人に聞きたかったんだけど、誰もあのお兄さんを知らなくて……",
            ["DialogueId"] = 51007571,
            ["GUID"] = "7FB12D9E",
            ["NextDialogue"] = 51007576,
            ["NextOptions"] = {
                [1] = 51007572,
                [2] = 51007574,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007572] = {
            ["Content"] = "他确实是精灵。",
            ["ContentJP"] = "彼は確かに妖精だったよ。",
            ["DialogueId"] = 51007572,
            ["GUID"] = "7FB12DC8",
            ["NextDialogue"] = 51007573,
            ["TriggerCondition"] = {
                ["ImprComp"] = {
                    ["TalkTriggerId"] = 500080,
                    },
                },
            },
        [51007573] = {
            ["Content"] = "嗯，既然你也这么说，那应该就是了吧！",
            ["ContentJP"] = "うん、あなたがそう言うなら、きっとそうだね！",
            ["DialogueId"] = 51007573,
            ["GUID"] = "7FB12DF2",
            ["NextDialogue"] = 51007576,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007574] = {
            ["Content"] = "他回到天上精灵的故乡了。",
            ["ContentJP"] = "彼は空へ、妖精たちの故郷に帰ったんだ。",
            ["DialogueId"] = 51007574,
            ["GUID"] = "7FB12E1C",
            ["NextDialogue"] = 51007575,
            ["TriggerCondition"] = {
                ["ImprComp"] = {
                    ["TalkTriggerId"] = 500080,
                    },
                },
            },
        [51007575] = {
            ["Content"] = "原来是这样啊……那就没办法啦。",
            ["ContentJP"] = "そっか……そういうことなら、仕方ないね……",
            ["DialogueId"] = 51007575,
            ["GUID"] = "7FB12E46",
            ["NextDialogue"] = 51007576,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007576] = {
            ["Content"] = "唔……总而言之，大家对问题3的答案都不太一样，看来我还需要收集更多的样本。",
            ["ContentJP"] = "うーん……やっぱり、みんな答えが違うなぁ。もっとたくさんサンプルを集めなきゃ！",
            ["DialogueId"] = 51007576,
            ["GUID"] = "7FB12E70",
            ["NextDialogue"] = 51007577,
            ["SpeakNpcId"] = 700011,
            },
        [51007577] = {
            ["Content"] = "下一个，问题4……",
            ["ContentJP"] = "じゃあ次、質問4──",
            ["DialogueId"] = 51007577,
            ["GUID"] = "7FB12E9A",
            ["NextOptions"] = {
                [1] = 51007578,
                [2] = 51007579,
                [3] = 51007580,
                },
            ["SpeakNpcId"] = 700011,
            },
        [51007578] = {
            ["Content"] = "停——你的问题很冒犯，我不想回答了。",
            ["ContentJP"] = "ちょっと待った。君の質問は失礼すぎるよ。もう答えたくない。",
            ["DialogueId"] = 51007578,
            ["GUID"] = "7FB12EC4",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007581,
            },
        [51007579] = {
            ["Content"] = "突然想起我还有事要忙。",
            ["ContentJP"] = "急に用事を思い出したから、この辺で。",
            ["DialogueId"] = 51007579,
            ["GUID"] = "7FB12EEE",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007581,
            },
        [51007580] = {
            ["Content"] = "再问加钱。",
            ["ContentJP"] = "これ以上は追加料金が必要だよ。",
            ["DialogueId"] = 51007580,
            ["GUID"] = "7FB12F18",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51007581,
            },
        [51007581] = {
            ["Content"] = "啊……那、那么今天就先问到这里吧。",
            ["ContentJP"] = "そ、そうなんだね……。じゃあ、今日はここまでにしよう。",
            ["DialogueId"] = 51007581,
            ["GUID"] = "7FB12F42",
            ["NextDialogue"] = 51007582,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Agree",
                },
            },
        [51007582] = {
            ["Content"] = "谢谢你，{性别：哥哥|姐姐}！这些银币给你，是今天实验的报酬。",
            ["ContentJP"] = "ありがとう、{性别:お兄さん|お姉さん}！この銀貨、今日の実験のお礼だよ！",
            ["DialogueId"] = 51007582,
            ["GUID"] = "7FB12F6C",
            ["NextDialogue"] = 51007583,
            ["SpeakNpcId"] = 700011,
            ["TalkActionId"] = {
                [1] = "700011:Give",
                },
            },
        [51007583] = {
            ["Content"] = "等我攒了新的零花钱，再来找你问其他问题！",
            ["ContentJP"] = "またお小遣いが貯まったら、続きをお願いするね！",
            ["DialogueId"] = 51007583,
            ["GUID"] = "7FB12F96",
            ["SpeakNpcId"] = 700011,
            },
        [51007601] = {
            ["Content"] = "老鼠们去哪儿了呢……",
            ["ContentJP"] = "ネズミたちどこ行っちゃったんだろう……？",
            ["DialogueId"] = 51007601,
            ["GUID"] = "7FB1328A",
            ["NextDialogue"] = 51007602,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Think_Start",
                },
            },
        [51007602] = {
            ["Content"] = "（男孩伸长了脖子，好奇地打量着下水道入口。）",
            ["ContentJP"] = "少年が首を伸ばし、下水道の入口を興味津々に覗き込んでいる。",
            ["DialogueId"] = 51007602,
            ["GUID"] = "7FB132B4",
            ["NextOptions"] = {
                [1] = 51007603,
                [2] = 51007604,
                },
            },
        [51007603] = {
            ["Content"] = "（和他打招呼。）",
            ["ContentJP"] = "声をかける。",
            ["DialogueId"] = 51007603,
            ["GUID"] = "7FB132DE",
            ["NextDialogue"] = 51007607,
            },
        [51007604] = {
            ["Content"] = "（吓他一跳。）",
            ["ContentJP"] = "驚かす。",
            ["DialogueId"] = 51007604,
            ["GUID"] = "7FB13308",
            ["NextDialogue"] = 51007605,
            },
        [51007605] = {
            ["Content"] = "呜哇？！呼，原来是你啊……",
            ["ContentJP"] = "うわっ？！……あ、あなたか！",
            ["DialogueId"] = 51007605,
            ["GUID"] = "7FB13332",
            ["NextDialogue"] = 51007607,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Shock_Start",
                },
            },
        [51007607] = {
            ["Content"] = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，好巧啊，又见面了！",
            ["ContentJP"] = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！すごい偶然だね！",
            ["DialogueId"] = 51007607,
            ["GUID"] = "7FB13386",
            ["NextDialogue"] = 51007608,
            ["SpeakNpcId"] = 700204,
            },
        [51007608] = {
            ["Content"] = "你为什么这么闲呀，你不用工作吗？妈妈说，卡戎们平时都在工厂里，没日没夜地工作。",
            ["ContentJP"] = "ところで、毎日ひまそうだね？働かなくていいの？ママが言ってたよ、カロンはみんな工場で、朝から晩まで働いてるんだって。",
            ["DialogueId"] = 51007608,
            ["GUID"] = "7FB133B0",
            ["NextDialogue"] = 51007609,
            ["SpeakNpcId"] = 700204,
            },
        [51007609] = {
            ["Content"] = "我是狩月人。",
            ["ContentJP"] = "{性别:僕は月狩り人だから。|私は月狩り人だから。}",
            ["DialogueId"] = 51007609,
            ["GUID"] = "7FB133DA",
            ["NextDialogue"] = 51007610,
            ["SpeakNpcId"] = 100001,
            },
        [51007610] = {
            ["Content"] = "噢，我听同学说起过！他们说狩月人是“只要给钱什么都会做的傻子”。",
            ["ContentJP"] = "ああ、そういえばクラスメートが言ってた！月狩り人って「金さえ積めば何でもやるバカ」だって。",
            ["DialogueId"] = 51007610,
            ["GUID"] = "7FB13404",
            ["NextDialogue"] = 51007611,
            ["SpeakNpcId"] = 700204,
            },
        [51007611] = {
            ["Content"] = "不过那只是他们的说法而已，你能告诉我这份工作的实际情况是怎样的吗？",
            ["ContentJP"] = "でも、それはあくまで子供の噂だよね？実際のところ、あなたたちの仕事ってどんな感じなの？",
            ["DialogueId"] = 51007611,
            ["GUID"] = "7FB1342E",
            ["NextOptions"] = {
                [1] = 51007612,
                [2] = 51007614,
                [3] = 51007616,
                },
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Explain01_Start",
                },
            },
        [51007612] = {
            ["Content"] = "（给他看身上的伤疤。)",
            ["ContentJP"] = "体の傷を見せる。",
            ["DialogueId"] = 51007612,
            ["GUID"] = "7FB13458",
            ["NextDialogue"] = 51007613,
            },
        [51007613] = {
            ["Content"] = "天哪，看来这份工作很危险……",
            ["ContentJP"] = "うわぁ……この仕事、かなり危険なんだね。",
            ["DialogueId"] = 51007613,
            ["GUID"] = "7FB13482",
            ["NextDialogue"] = 51007618,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Shock_Start",
                },
            },
        [51007614] = {
            ["Content"] = "（给他看赚到的报酬。）",
            ["ContentJP"] = "稼いだ報酬を見せる。",
            ["DialogueId"] = 51007614,
            ["GUID"] = "7FB134AC",
            ["NextDialogue"] = 51007615,
            },
        [51007615] = {
            ["Content"] = "哇，能赚这么多啊！",
            ["ContentJP"] = "うわぁ、こんなに稼げるの！？",
            ["DialogueId"] = 51007615,
            ["GUID"] = "7FB134D6",
            ["NextDialogue"] = 51007618,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Shock_Start",
                },
            },
        [51007616] = {
            ["Content"] = "（拿出武器吓唬他。）",
            ["ContentJP"] = "武器を見せつけて脅かす。",
            ["DialogueId"] = 51007616,
            ["GUID"] = "7FB13500",
            ["NextDialogue"] = 51007617,
            },
        [51007617] = {
            ["Content"] = "哎？意思是你很厉害吗？",
            ["ContentJP"] = "ん？あなたはとても強いって意味？",
            ["DialogueId"] = 51007617,
            ["GUID"] = "7FB1352A",
            ["NextDialogue"] = 51007618,
            ["SpeakNpcId"] = 700204,
            },
        [51007618] = {
            ["Content"] = "唔……真想看看你工作时的样子……啊，有了！",
            ["ContentJP"] = "うーん……あなたが仕事してるところ、見てみたいな……あ、そうだ！",
            ["DialogueId"] = 51007618,
            ["GUID"] = "7FB13554",
            ["NextDialogue"] = 51007619,
            ["SpeakNpcId"] = 700204,
            },
        [51007619] = {
            ["Content"] = "我正准备对下水道的生态环境展开调查，你能陪我一起吗？",
            ["ContentJP"] = "僕、ちょうど下水道の生態環境を調査しようと思ってたんだ。一緒に来てくれない？",
            ["DialogueId"] = 51007619,
            ["GUID"] = "7FB1357E",
            ["NextDialogue"] = 51007620,
            ["SpeakNpcId"] = 700204,
            },
        [51007620] = {
            ["Content"] = "就当做是我给你的委托好了，我会支付报酬的！",
            ["ContentJP"] = "これは依頼だよ。ちゃんと報酬も払うから！",
            ["DialogueId"] = 51007620,
            ["GUID"] = "7FB135A8",
            ["NextDialogue"] = 51007623,
            ["SpeakNpcId"] = 700204,
            },
        [51007623] = {
            ["Content"] = "好耶！那我们就出发吧。",
            ["ContentJP"] = "やった！じゃあ、行こう！",
            ["DialogueId"] = 51007623,
            ["GUID"] = "7FB13626",
            ["NextDialogue"] = 51007624,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007624] = {
            ["Content"] = "你知道吗，虽然大家都说老鼠是讨人厌的生物，不过据我观察，他们其实很有意思哦！",
            ["ContentJP"] = "知ってる？みんなはネズミを毛嫌いするけど、僕が観察した結果によれば、ネズミってすごく面白いんだよ！",
            ["DialogueId"] = 51007624,
            ["GUID"] = "7FB13650",
            ["NextDialogue"] = 51007625,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Explain01_Start",
                },
            },
        [51007625] = {
            ["Content"] = "我曾经在这里见到过一只非常威风的大老鼠，很像故事里说的“老鼠战士”。",
            ["ContentJP"] = "このあたりでも、一度だけすごく立派なネズミを見たことがあるんだ。まるで「ネズミ戦士」のお話みたいなやつ！",
            ["DialogueId"] = 51007625,
            ["GUID"] = "7FB1367A",
            ["NextDialogue"] = 51007626,
            ["SpeakNpcId"] = 700204,
            },
        [51007626] = {
            ["Content"] = "“老鼠战士”本来只是一只天生瘦弱的小老鼠，但它不断克服困难，勇敢战斗，最终成为保护族群的大英雄！",
            ["ContentJP"] = "「ネズミ戦士」っていうのは、もともとはすごく小さくて弱いネズミだったんだけど、困難に立ち向かって戦い抜いて、ついには仲間たちを守る英雄になったっていう伝説さ。",
            ["DialogueId"] = 51007626,
            ["GUID"] = "7FB136A4",
            ["NextDialogue"] = 51007627,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Angry01_Start",
                },
            },
        [51007627] = {
            ["Content"] = "我见到的那只大老鼠身上有很多伤疤，那一定就是它英勇战斗的证明。说起来，它还背着一个奇怪的小瓶子呢，也许那是什么特别的道具吧……",
            ["ContentJP"] = "僕が見たあのネズミも、傷だらけだったんだ。きっと勇敢に戦った証拠だよ。しかも、背中に小さな奇妙なボトルを背負ってたんだ。もしかして、特別な道具だったのかも？",
            ["DialogueId"] = 51007627,
            ["GUID"] = "7FB136CE",
            ["NextOptions"] = {
                [1] = 51007628,
                [2] = 51007631,
                [3] = 51007636,
                },
            ["SpeakNpcId"] = 700204,
            },
        [51007628] = {
            ["Content"] = "那也许是实验道具。",
            ["ContentJP"] = "それ、実験道具だったんじゃない？",
            ["DialogueId"] = 51007628,
            ["GUID"] = "7FB136F8",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007629,
            },
        [51007629] = {
            ["Content"] = "有道理，也许是什么人在用老鼠做实验……这么一想有点可怕……",
            ["ContentJP"] = "たしかに……誰かがネズミを使った実験だったのかも……そう考えるとちょっと怖いね。",
            ["DialogueId"] = 51007629,
            ["GUID"] = "7FB13722",
            ["NextDialogue"] = 51007630,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007630] = {
            ["Content"] = "不过，它勇敢地接受了自己的命运，这正是英雄气概的体现吧！只可惜……",
            ["ContentJP"] = "でも、運命を受け入れて勇敢に生きたんだ。それが英雄ってものだよね！……可哀想だけど。",
            ["DialogueId"] = 51007630,
            ["GUID"] = "7FB1374C",
            ["NextDialogue"] = 51007638,
            ["SpeakNpcId"] = 700204,
            },
        [51007631] = {
            ["Content"] = "就像是故事照进了现实一样，很有趣。",
            ["ContentJP"] = "まるで物語が現実になったみたいで、面白いね。",
            ["DialogueId"] = 51007631,
            ["GUID"] = "7FB13776",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007632,
            },
        [51007632] = {
            ["Content"] = "嘿嘿，我也这么觉得！",
            ["ContentJP"] = "へへ、僕もそう思う！",
            ["DialogueId"] = 51007632,
            ["GUID"] = "7FB137A0",
            ["NextDialogue"] = 51007633,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007633] = {
            ["Content"] = "哎，只可惜……你再也没机会见到它了。",
            ["ContentJP"] = "残念だなぁ……あなたはもう見れないんだから。",
            ["DialogueId"] = 51007633,
            ["GUID"] = "7FB137CA",
            ["NextOptions"] = {
                [1] = 51007634,
                [2] = 51007635,
                },
            ["SpeakNpcId"] = 700204,
            },
        [51007634] = {
            ["Content"] = "为什么？",
            ["ContentJP"] = "どうして？",
            ["DialogueId"] = 51007634,
            ["GUID"] = "7FB137F4",
            ["NextDialogue"] = 51007638,
            },
        [51007635] = {
            ["Content"] = "这话听起来怎么像是你要把我灭口……",
            ["ContentJP"] = "その言い方、僕を口封じするつもり？/その言い方、私を口封じするつもり？",
            ["DialogueId"] = 51007635,
            ["GUID"] = "7FB1381E",
            ["NextDialogue"] = 51007638,
            },
        [51007636] = {
            ["Content"] = "听上去感觉它能把你吃了。",
            ["ContentJP"] = "まさか、食べちゃったの？",
            ["DialogueId"] = 51007636,
            ["GUID"] = "7FB13848",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51007637,
            },
        [51007637] = {
            ["Content"] = "什么嘛，它可是一只好老鼠，从来没有攻击过我！而且，它也已经不在了……",
            ["ContentJP"] = "いや、違うよ！あのネズミはすごくいい子だったんだ！でも……もういないんだ……",
            ["DialogueId"] = 51007637,
            ["GUID"] = "7FB13872",
            ["NextDialogue"] = 51007638,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007638] = {
            ["Content"] = "几天前，我亲眼看见老鼠战士被一个乞丐大叔抓走做成了烤肉串……呜呜……",
            ["ContentJP"] = "数日前、僕、あのネズミ戦士が、物乞いのおじさんに捕まって……焼き串にされるところを見ちゃったんだ……ううっ。",
            ["DialogueId"] = 51007638,
            ["GUID"] = "7FB1389C",
            ["NextDialogue"] = 51007639,
            ["SpeakNpcId"] = 700204,
            },
        [51007639] = {
            ["Content"] = "唉……虽然很难过，但研究出现意外也是常有的事。我现在想看看那些它曾经关照过的小老鼠过得怎么样。",
            ["ContentJP"] = "……つらいけど、研究って予期せぬ出来事もつきものだよね。だから今は、あの子が世話してた小さなネズミたちがどうしてるか、見てみたいんだ。",
            ["DialogueId"] = 51007639,
            ["GUID"] = "7FB138C6",
            ["NextDialogue"] = 51007640,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007640] = {
            ["Content"] = "我们走吧，只要听声音应该就能找到老鼠窝的位置了！",
            ["ContentJP"] = "さあ、ネズミたちの声を頼りに、巣の場所を探しに行こう！",
            ["DialogueId"] = 51007640,
            ["GUID"] = "7FB138F0",
            ["NextOptions"] = {
                [1] = 51007641,
                [2] = 51007643,
                },
            ["SpeakNpcId"] = 700204,
            },
        [51007641] = {
            ["Content"] = "好。跟在我身后吧，我会保护你的。",
            ["ContentJP"] = "うん。しっかり着いてきて。ちゃんと守るから。",
            ["DialogueId"] = 51007641,
            ["GUID"] = "7FB1391A",
            ["NextDialogue"] = 51007642,
            },
        [51007642] = {
            ["Content"] = "谢谢，你真可靠！",
            ["ContentJP"] = "ありがとう！あなた、頼りになるね！",
            ["DialogueId"] = 51007642,
            ["GUID"] = "7FB13944",
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007643] = {
            ["Content"] = "我害怕，你来带路吧。",
            ["ContentJP"] = "怖いから、君が前歩いて。",
            ["DialogueId"] = 51007643,
            ["GUID"] = "7FB1396E",
            ["NextDialogue"] = 51007644,
            },
        [51007644] = {
            ["Content"] = "不会吧，你刚刚不是还很威风吗……",
            ["ContentJP"] = "ええー、さっきまであんな強がってたのに？",
            ["DialogueId"] = 51007644,
            ["GUID"] = "7FB13998",
            ["NextDialogue"] = 51007645,
            ["SpeakNpcId"] = 700204,
            },
        [51007645] = {
            ["Content"] = "唉，没办法，那你就跟着我吧。",
            ["ContentJP"] = "……しょうがないなぁ、じゃあ僕が先に行くよ。",
            ["DialogueId"] = 51007645,
            ["GUID"] = "7FB139C2",
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Sigh_Start",
                },
            },
        [51007646] = {
            ["Content"] = "原来下水道里面这么宽阔……",
            ["ContentJP"] = "下水道って、思ったより広いんだね……",
            ["DialogueId"] = 51007646,
            ["GUID"] = "7FB139EC",
            ["NextDialogue"] = 51007647,
            ["SpeakNpcId"] = 700204,
            },
        [51007647] = {
            ["Content"] = "（一团灰色的影子从角落里闪现，似乎是只小老鼠。）",
            ["ContentJP"] = "灰色の影が角をすり抜ける。どうやら小さなネズミらしい。",
            ["DialogueId"] = 51007647,
            ["GUID"] = "7FB13A16",
            ["NextDialogue"] = 51007648,
            },
        [51007648] = {
            ["Content"] = "啊，你看到了吗？那只断了一截尾巴的小老鼠我见过，它是老鼠战士的同伴！",
            ["ContentJP"] = "あっ、見た？あれ、尾っぽが途中で切れてる！あれは前に見た、ネズミ戦士の仲間だよ！",
            ["DialogueId"] = 51007648,
            ["GUID"] = "7FB13A40",
            ["NextDialogue"] = 51007649,
            ["SpeakNpcId"] = 700204,
            },
        [51007649] = {
            ["Content"] = "哎呀！怎么溜走了？",
            ["ContentJP"] = "あれっ！逃げた！？",
            ["DialogueId"] = 51007649,
            ["GUID"] = "7FB13A6A",
            ["NextDialogue"] = 51007650,
            ["SpeakNpcId"] = 700204,
            },
        [51007650] = {
            ["Content"] = "它好像不记得我啊……",
            ["ContentJP"] = "僕のこと忘れちゃったのかな……",
            ["DialogueId"] = 51007650,
            ["GUID"] = "7FB13A94",
            ["NextDialogue"] = 51007651,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Think_Start",
                },
            },
        [51007651] = {
            ["Content"] = "（男孩皱起了小小的眉头，似乎陷入了思考。）",
            ["ContentJP"] = "少年は小さな眉をひそめ、考え込んだ。",
            ["DialogueId"] = 51007651,
            ["GUID"] = "7FB13ABE",
            ["NextDialogue"] = 51007652,
            },
        [51007652] = {
            ["Content"] = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，你觉得动物有情感吗？我很想弄明白，可是我听不懂它们的语言……",
            ["ContentJP"] = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、動物に心ってあると思う？知りたいんだけど、言葉が通じないからなぁ……",
            ["DialogueId"] = 51007652,
            ["GUID"] = "7FB13AE8",
            ["NextOptions"] = {
                [1] = 51007653,
                [2] = 51007656,
                },
            ["SpeakNpcId"] = 700204,
            },
        [51007653] = {
            ["Content"] = "只要你相信它们是有情感的，那就是有。",
            ["ContentJP"] = "信じればあるんじゃないかな。",
            ["DialogueId"] = 51007653,
            ["GUID"] = "7FB13B12",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51007654,
            },
        [51007654] = {
            ["Content"] = "不行不行，这说法也太主观了，研究是要讲证据的！",
            ["ContentJP"] = "うーん、主観的な考え方じゃダメなんだよ。研究にはちゃんとした根拠が必要なんだ！",
            ["DialogueId"] = 51007654,
            ["GUID"] = "7FB13B3C",
            ["NextDialogue"] = 51007655,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007655] = {
            ["Content"] = "或许我们可以通过观察它们的行动来确认。",
            ["ContentJP"] = "そうだ、行動観察から証明できるかもしれない！",
            ["DialogueId"] = 51007655,
            ["GUID"] = "7FB13B66",
            ["NextDialogue"] = 51007658,
            ["SpeakNpcId"] = 700204,
            },
        [51007656] = {
            ["Content"] = "情感并不是只通过语言传达，你可以通过观察它们的行为来探究这个问题。",
            ["ContentJP"] = "心は言葉だけじゃなく、行動でもわかるんじゃないかな。彼らの行動を観察してみたら？",
            ["DialogueId"] = 51007656,
            ["GUID"] = "7FB13B90",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51007657,
            },
        [51007657] = {
            ["Content"] = "噢噢，你说得很对！",
            ["ContentJP"] = "確かに！",
            ["DialogueId"] = 51007657,
            ["GUID"] = "7FB13BBA",
            ["NextDialogue"] = 51007658,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007658] = {
            ["Content"] = "让我想想……假设这些小老鼠对老鼠战士抱有尊敬之情，那么它们应该也会像它一样，非常勇敢、对人友好、爱护同伴吧？",
            ["ContentJP"] = "もしあの小ネズミたちがネズミ戦士を尊敬しているなら、きっと勇敢で、優しくて、仲間思いの行動をするはずだよね！",
            ["DialogueId"] = 51007658,
            ["GUID"] = "7FB13BE4",
            ["NextDialogue"] = 51007659,
            ["SpeakNpcId"] = 700204,
            },
        [51007659] = {
            ["Content"] = "好，就让我们去亲眼验证一下！刚才的小老鼠往拐角方向去了，我们快追上它吧。",
            ["ContentJP"] = "よし、実際に確かめに行こう！さっきの子ネズミ、あっちへ走っていったよ。急ごう！",
            ["DialogueId"] = 51007659,
            ["GUID"] = "7FB13C0E",
            ["SpeakNpcId"] = 700204,
            },
        [51007660] = {
            ["Content"] = "看，那就是老鼠们的家！",
            ["ContentJP"] = "見て！ネズミの巣だ！",
            ["DialogueId"] = 51007660,
            ["GUID"] = "7FB13C38",
            ["NextDialogue"] = 51007661,
            ["SpeakNpcId"] = 700204,
            },
        [51007661] = {
            ["Content"] = "（老鼠窝中传来“吱——吱——”的尖锐叫声，伴随着一阵微妙的臭气，但西奥并没有退缩。他睁大了眼睛，认真地观察着老鼠们的行动。）",
            ["ContentJP"] = "ネズミの巣から「チューチュー」と鋭い鳴き声が聞こえた。わずかに漂う悪臭にも、テオは怯むことなく、目を大きく開いてネズミたちの動きを真剣に観察している。",
            ["DialogueId"] = 51007661,
            ["GUID"] = "7FB13C62",
            ["NextDialogue"] = 51007662,
            },
        [51007662] = {
            ["Content"] = "（小老鼠们正在为了争夺半块饼而互相撕咬。）",
            ["ContentJP"] = "子ネズミたちは半分に割れたビスケットを奪い合って、必死に揉み合っていた。",
            ["DialogueId"] = 51007662,
            ["GUID"] = "7FB13C8C",
            ["NextDialogue"] = 51007663,
            },
        [51007663] = {
            ["Content"] = "啊……他们好像……不是太爱护同伴。",
            ["ContentJP"] = "うう……彼ら、仲間思いじゃないかも……",
            ["DialogueId"] = 51007663,
            ["GUID"] = "7FB13CB6",
            ["NextDialogue"] = 51007664,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Shock_Start",
                },
            },
        [51007664] = {
            ["Content"] = "（注意到有人接近，一部分小老鼠受到了惊吓，慌张地逃走了。）",
            ["ContentJP"] = "人影に気づき、一部の子ネズミが驚いて慌てて逃げ出した。",
            ["DialogueId"] = 51007664,
            ["GUID"] = "7FB13CE0",
            ["NextDialogue"] = 51007665,
            },
        [51007665] = {
            ["Content"] = "呃……他们好像……也不太勇敢。",
            ["ContentJP"] = "うう……勇敢でもないみたいだね。",
            ["DialogueId"] = 51007665,
            ["GUID"] = "7FB13D0A",
            ["NextDialogue"] = 51007666,
            ["SpeakNpcId"] = 700204,
            },
        [51007666] = {
            ["Content"] = "（剩下的几只老鼠忽然眼露凶光，朝你们发起了攻击！）",
            ["ContentJP"] = "残った数匹のネズミが突然目を光らせ、こちらに飛びかかってきた！",
            ["DialogueId"] = 51007666,
            ["GUID"] = "7FB13D34",
            ["NextDialogue"] = 51007667,
            },
        [51007667] = {
            ["Content"] = "啊啊啊——怎么平白无故地袭击人呀，太没有礼貌了吧？！",
            ["ContentJP"] = "うわああ！何もしてないのにいきなり襲ってくるなんて、失礼すぎるよ！",
            ["DialogueId"] = 51007667,
            ["GUID"] = "7FB13D5E",
            ["NextDialogue"] = 51007668,
            ["SpeakNpcId"] = 700204,
            },
        [51007668] = {
            ["Content"] = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我们快逃！",
            ["ContentJP"] = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、逃げよう！",
            ["DialogueId"] = 51007668,
            ["GUID"] = "7FB13D88",
            ["NextDialogue"] = 51007669,
            ["SpeakNpcId"] = 700204,
            },
        [51007669] = {
            ["Content"] = "你先逃，我来对付它们。",
            ["ContentJP"] = "ここは任せて、君は先に逃げて。",
            ["DialogueId"] = 51007669,
            ["GUID"] = "7FB13DB2",
            ["SpeakNpcId"] = 100001,
            },
        [51007670] = {
            ["Content"] = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，你回来啦！我刚才远远地观察了你战斗的情况，你好厉害呀！",
            ["ContentJP"] = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、戻ってきたんだね！あなたの戦う姿、遠くから見てたよ！すっごくかっこよかった！",
            ["DialogueId"] = 51007670,
            ["GUID"] = "7FB13DDC",
            ["NextDialogue"] = 51007671,
            ["SpeakNpcId"] = 700204,
            },
        [51007671] = {
            ["Content"] = "“{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}拥有强大的战斗能力”……嗯，我记下了。",
            ["ContentJP"] = "「{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}はすごい戦闘能力を持ってる」……っと。ちゃんとメモしといたよ。",
            ["DialogueId"] = 51007671,
            ["GUID"] = "7FB13E06",
            ["NextDialogue"] = 51007672,
            ["SpeakNpcId"] = 700204,
            },
        [51007672] = {
            ["Content"] = "不过……唉，看来那些小老鼠并没有情感吧……",
            ["ContentJP"] = "でも……やっぱり、あの子ネズミたちには情がなかったみたいだね……",
            ["DialogueId"] = 51007672,
            ["GUID"] = "7FB13E30",
            ["NextOptions"] = {
                [1] = 51007673,
                [2] = 51007675,
                },
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007673] = {
            ["Content"] = "也许它们只是还在成长。",
            ["ContentJP"] = "まだ成長途中なのかもしれない。",
            ["DialogueId"] = 51007673,
            ["GUID"] = "7FB13E5A",
            ["NextDialogue"] = 51007674,
            },
        [51007674] = {
            ["Content"] = "嗯……！你说得对，也许等它们长大之后，就会成为像老鼠战士一样优秀的大老鼠了。",
            ["ContentJP"] = "うん……確かに！成長すれば、きっとネズミ戦士みたいな立派なネズミになるよね！",
            ["DialogueId"] = 51007674,
            ["GUID"] = "7FB13E84",
            ["NextDialogue"] = 51007677,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007675] = {
            ["Content"] = "也许是因为能教导它们的前辈已经不在了。",
            ["ContentJP"] = "きっと教えてくれる先輩がいなくなったからだよ。",
            ["DialogueId"] = 51007675,
            ["GUID"] = "7FB13EAE",
            ["NextDialogue"] = 51007676,
            },
        [51007676] = {
            ["Content"] = "嗯……你说得对。真是让人难过啊……希望就算失去了前辈的保护，它们也能坚强地长大。",
            ["ContentJP"] = "そうだよね……悲しいけど、先輩がいなくなっても、強く生き抜いてほしいな。",
            ["DialogueId"] = 51007676,
            ["GUID"] = "7FB13ED8",
            ["NextDialogue"] = 51007677,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007677] = {
            ["Content"] = "我已经做好记录了，今天的调查就到这里为止吧。",
            ["ContentJP"] = "よし、今日の調査はこれで終わりにしよう。",
            ["DialogueId"] = 51007677,
            ["GUID"] = "7FB13F02",
            ["NextDialogue"] = 51007678,
            ["SpeakNpcId"] = 700204,
            },
        [51007678] = {
            ["Content"] = "谢谢你陪我，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，你真是个聪明又可靠的人呀！看来他们说的那些关于狩月人的坏话并不是真的。",
            ["ContentJP"] = "付き合ってくれてありがとう{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！あなたはすごく賢くて頼れる人だね！世間で言われてる月狩り人の噂なんて、まっぴらな嘘だね！",
            ["DialogueId"] = 51007678,
            ["GUID"] = "7FB13F2C",
            ["NextDialogue"] = 51007679,
            ["SpeakNpcId"] = 700204,
            },
        [51007679] = {
            ["Content"] = "要是所有卡戎都像你一样友善就好啦……比如说，之前我在城北一家旅馆门口看到了一个绿衣服姐姐，我和她打招呼，但她完全不理我。",
            ["ContentJP"] = "ああ、もしも全てのカロンがあなたみたいに優しかったらなあ……そういえば、前に街の北側の宿屋で、緑の服を着たお姉さんを見かけたんだ。声をかけたのに、全然反応してくれなかったんだよね。",
            ["DialogueId"] = 51007679,
            ["GUID"] = "7FB13F56",
            ["NextDialogue"] = 51007680,
            ["SpeakNpcId"] = 700204,
            },
        [51007680] = {
            ["Content"] = "她可能只是刚好没看到吧。",
            ["ContentJP"] = "たぶん気づかなかっただけだよ。",
            ["DialogueId"] = 51007680,
            ["GUID"] = "7FB13F80",
            ["NextDialogue"] = 51007681,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007681] = {
            ["Content"] = "嗯？你这么说……难道是你认识那个姐姐吗？",
            ["ContentJP"] = "え？もしかして知り合い？",
            ["DialogueId"] = 51007681,
            ["GUID"] = "7FB13FAA",
            ["NextDialogue"] = 51007682,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007682] = {
            ["Content"] = "是的。",
            ["ContentJP"] = "うん。",
            ["DialogueId"] = 51007682,
            ["GUID"] = "7FB13FD4",
            ["NextDialogue"] = 51007683,
            ["SpeakNpcId"] = 100001,
            },
        [51007683] = {
            ["Content"] = "真了不起，你居然认识这么多人……你是怎么和他们沟通的，也教教我吧？",
            ["ContentJP"] = "すごいなあ、あなた、どうしてそんなにたくさんの人と知り合いなんだろう……その秘訣、教えてくれない？",
            ["DialogueId"] = 51007683,
            ["GUID"] = "7FB13FFE",
            ["NextOptions"] = {
                [1] = 51007684,
                [2] = 51007686,
                },
            ["SpeakNpcId"] = 700204,
            },
        [51007684] = {
            ["Content"] = "多和不同的人对话，积累技巧。",
            ["ContentJP"] = "いろんな人と会話して、経験を積むこと。",
            ["DialogueId"] = 51007684,
            ["GUID"] = "7FB14028",
            ["NextDialogue"] = 51007685,
            },
        [51007685] = {
            ["Content"] = "（西奥在本子上写下：“{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}与人沟通的秘诀是：多和不同的人对话，积累技巧。”）",
            ["ContentJP"] = "テオはノートに「{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}のコミュニケーションのコツ：いろんな人と話して経験を積む」と書き込んだ。",
            ["DialogueId"] = 51007685,
            ["GUID"] = "7FB14052",
            ["NextDialogue"] = 51007688,
            },
        [51007686] = {
            ["Content"] = "遇事不决武力威胁。",
            ["ContentJP"] = "とりあえず武力で威圧する。",
            ["DialogueId"] = 51007686,
            ["GUID"] = "7FB1407C",
            ["NextDialogue"] = 51007687,
            },
        [51007687] = {
            ["Content"] = "（西奥在本子上写下：“{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}与人沟通的秘诀是：遇事不决武力威胁。备注：这个方法似乎不适合我。”）",
            ["ContentJP"] = "テオはノートに「{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}のコミュニケーションのコツ：まずは武力で威圧。※この方法は僕には向かないかも」とメモした。",
            ["DialogueId"] = 51007687,
            ["GUID"] = "7FB140A6",
            ["NextDialogue"] = 51007688,
            },
        [51007688] = {
            ["Content"] = "嗯嗯……我记下了。",
            ["ContentJP"] = "うんうん、覚えたよ！",
            ["DialogueId"] = 51007688,
            ["GUID"] = "7FB140D0",
            ["NextDialogue"] = 51007689,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007689] = {
