                [3] = "700205:n(700204)",
                },
            },
        [51007701] = {
            ["Content"] = "（男孩被母亲强行拽走了。在离开之前，他悄悄地回过头，用口型对你说了一句“下次见”，并轻轻将一个小包裹扔给了你。）",
            ["ContentJP"] = "女性は無理やりテオの手を引き、去っていった。テオはこっそり「またね！」と言うと、小さな包みをあなたにそっと投げた。",
            ["DialogueId"] = 51007701,
            ["GUID"] = "7FB142F2",
            ["IsBlack"] = 1,
            },
        [51007702] = {
            ["Content"] = "{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，{$XiAoTag(Value_1,Value_2)$|蛋蛋:西比尔}{性别：哥哥|姐姐}，我在这里！",
            ["ContentJP"] = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！ここだよここ！",
            ["DialogueId"] = 51007702,
            ["GUID"] = "7FB1431C",
