            ["SpeakNpcId"] = 700204,
            },
        [51007703] = {
            ["Content"] = "（男孩躲在建筑的阴影中，激动地向你挥手。）",
            ["ContentJP"] = "（少年が建物の陰から手を振ってくる）",
            ["DialogueId"] = 51007703,
            ["GUID"] = "7FB14346",
            ["NextDialogue"] = 51007704,
            },
        [51007704] = {
            ["Content"] = "又见面啦！",
            ["ContentJP"] = "また会ったね！",
            ["DialogueId"] = 51007704,
            ["GUID"] = "7FB14370",
            ["NextDialogue"] = 51007705,
            ["SpeakNpcId"] = 700204,
            },
        [51007705] = {
            ["Content"] = "我后来去打听了哦，你的真名叫{nickname}对吧！真是的，怎么能骗小孩呢？",
            ["ContentJP"] = "聞いたんだけど、本当は{nickname}っていうんだよね？もー、子どもを騙しちゃダメでしょ！",
            ["DialogueId"] = 51007705,
            ["GUID"] = "7FB1439A",
            ["NextDialogue"] = 51007706,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Talk03_Start",
                },
            },
        [51007706] = {
            ["Content"] = "上次真是对不起，我妈妈好像很怕卡戎。",
            ["ContentJP"] = "この前はごめんね。母さん、カロン族のこと、すごく怖がってるんだ。",
            ["DialogueId"] = 51007706,
            ["GUID"] = "7FB143C4",
            ["NextDialogue"] = 51007707,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Explain01_Start",
                },
            },
        [51007707] = {
            ["Content"] = "那天回去以后，妈妈拉着我说了一大堆话，什么“卡戎人都是好吃懒做的家伙，是天生的罪犯，非常危险”之类的。",
            ["ContentJP"] = "帰ってからずっと、「カロン族は怠け者で、生まれつき犯罪者で、すごく危険な連中だ」なんて言っててさ。",
            ["DialogueId"] = 51007707,
            ["GUID"] = "7FB143EE",
            ["NextDialogue"] = 51007708,
            ["SpeakNpcId"] = 700204,
            },
        [51007708] = {
            ["Content"] = "其他大人说的也都差不多。但是我越想越觉得奇怪呀！",
            ["ContentJP"] = "他の大人たちも、似たようなこと言ってたよ。でも、なんだか変だなって思ってきたんだ。",
            ["DialogueId"] = 51007708,
            ["GUID"] = "7FB14418",
            ["NextDialogue"] = 51007709,
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Disagree",
                },
            },
        [51007709] = {
            ["Content"] = "我想去了解卡戎人，但要么是我不敢跟他们说话，要么是他们不愿意和我聊天，所以你能给我讲讲他们的生活吗？",
            ["ContentJP"] = "カロンのこと、もっとちゃんと知りたいんだ。でも、僕が話しかけても怖がられたり無視されたりするし……だから、あなたが教えてくれたら嬉しいな！",
            ["DialogueId"] = 51007709,
            ["GUID"] = "7FB14442",
            ["NextDialogue"] = 51007710,
            ["SpeakNpcId"] = 700204,
            },
        [51007710] = {
            ["Content"] = "比起说，不如直接带你去看看吧。我这里还有相机，你可以拍点照片带回去好好想一想。",
            ["ContentJP"] = "話すより、実際に見た方が早いよ。ちょうどカメラも持ってるし、写真を撮って帰ってからゆっくり考えてみるといい。",
            ["DialogueId"] = 51007710,
            ["GUID"] = "7FB1446C",
            ["NextDialogue"] = 51007711,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Explain01_Start",
                },
            },
        [51007711] = {
            ["Content"] = "真的吗？谢谢你！",
            ["ContentJP"] = "ほんとに？ありがとう！",
            ["DialogueId"] = 51007711,
            ["GUID"] = "7FB14496",
            ["SpeakNpcId"] = 700204,
            ["TalkActionId"] = {
                [1] = "700204:Agree",
                },
            },
        [51007712] = {
            ["Camera"] = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
            ["Content"] = "你看这些破旧的小摊，每天天不亮的时候便会支起来，很多卡戎之民就是这样谋生的。跟他们熟起来的话，说不定会给你打点折扣呢。",
            ["ContentJP"] = "あの屋台、毎朝まだ暗いうちから準備を始めるんだ。こうして、カロンたちは毎日必死に働いて生計を立ててるんだよ。仲良くなれば、ちょっとした値引きとかしてくれるかもね。",
            ["DialogueId"] = 51007712,
            ["GUID"] = "7FB144C0",
            ["NextDialogue"] = 51007713,
            ["SpeakNpcId"] = 100001,
            },
        [51007713] = {
            ["Camera"] = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
            ["Content"] = "大家……很累很辛苦呢。",
            ["ContentJP"] = "……すごく、大変そうだね。",
            ["DialogueId"] = 51007713,
            ["GUID"] = "7FB144EA",
            ["SpeakNpcId"] = 700204,
            },
        [51007714] = {
