            ["ToFinalCameraBlendTime"] = 30,
            },
        [51009230] = {
            ["Camera"] = "274.12793,98.953613,123.311523,0.000205,0.68726,-170.794342,25.000006,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂喂喂……你没事吧？",
            ["ContentJP"] = "お、おいおいおい……だ、大丈夫かね！？",
            ["DialogueId"] = 51009230,
            ["GUID"] = "7FB23DCC",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["NextDialogue"] = 51009231,
            ["SpeakNpcId"] = 230003,
            ["TalkActionId"] = {
