            ["SpeakNpcId"] = 700301,
            ["TalkActionId"] = {
                [1] = "700301:Disagree",
                },
            },
        [51009712] = {
            ["Content"] = "你是来让我解脱的吗？维尔莉特……",
            ["ContentJP"] = "この罪人の命を――刈るために……",
            ["DialogueId"] = 51009712,
            ["GUID"] = "7FB28CE0",
            ["SpeakNpcId"] = 700301,
            ["TalkActionId"] = {
                [1] = "700301:Sigh_Start",
                },
            },
        [51009713] = {
            ["Content"] = "（多纳特的声音逐渐虚弱，随即倒在了地上。）",
            ["ContentJP"] = "ドナートの声がかすれ、そしてその場に崩れ落ちる",
            ["DialogueId"] = 51009713,
            ["GUID"] = "7FB28D0A",
