            ["SpeakNpcId"] = 700309,
            },
        [51009732] = {
            ["Content"] = "抱歉，我只是一只普通的箱子，没有那种力量。",
            ["ContentJP"] = "残念、私はただの箱。願いを叶える力なんて持ってないの。",
