            ["GUID"] = "7FB2907C",
            ["NextDialogue"] = 51009735,
            ["SpeakNpcId"] = 700309,
            },
        [51009735] = {
            ["Content"] = "唱歌吧。",
            ["ContentJP"] = "……歌かな。",
            ["DialogueId"] = 51009735,
            ["GUID"] = "7FB290A6",
            ["NextDialogue"] = 51009736,
            ["SpeakNpcId"] = 100001,
            },
        [51009736] = {
            ["Content"] = "可有一种会唱歌的小盒子，只要拧几圈发条就可以歌唱。说话比唱歌更加简单，而我比八音盒更大，也更好——",
            ["ContentJP"] = "なら、ゼンマイを巻けば歌い出すオルゴールは？歌えるのに、言葉は話せない……って、不思議じゃない？私はそれよりちょっと大きくて、ちょっと賢いだけ。",
            ["DialogueId"] = 51009736,
            ["GUID"] = "7FB290D0",
            ["NextDialogue"] = 51009737,
            ["SpeakNpcId"] = 700309,
            },
        [51009737] = {
            ["Content"] = "所以我可以像这样对你说话，就像你现在正对我说话一样。",
            ["ContentJP"] = "だからこうして、あなたと話せるのよ。",
