        [51009738] = {
            ["Content"] = "可是……",
            ["ContentJP"] = "でも……",
            ["DialogueId"] = 51009738,
            ["GUID"] = "7FB29124",
            ["NextDialogue"] = 51009739,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51009739] = {
            ["Content"] = "我明白，你在疑惑。",
            ["ContentJP"] = "うん、わかってる。まだ信じられないんでしょ？",
            ["DialogueId"] = 51009739,
            ["GUID"] = "7FB2914E",
            ["NextDialogue"] = 51009740,
            ["SpeakNpcId"] = 700309,
            },
        [51009740] = {
            ["Content"] = "每个人都认为一只木箱不应该说话，就像他们记忆中那个只会响起回音的树洞一样。但是扪心自问，谁不想要一个会说话的木箱呢？",
            ["ContentJP"] = "「箱が喋るなんて変だ」ってよく言われるわ。でも、もしその箱が、誰かの声に応えてくれるなら……どう？ちょっとだけ、話してみたくならない？",
            ["DialogueId"] = 51009740,
            ["GUID"] = "7FB29178",
            ["NextDialogue"] = 51009741,
            ["SpeakNpcId"] = 700309,
            },
        [51009741] = {
            ["Content"] = "既然你没有第一时间掀开我，说明你还是希望会有一只木箱陪你说说话不是吗？",
            ["ContentJP"] = "それに、あなた……私をすぐに開けたり壊したりしなかった。つまり少しだけでも、私とお喋りしたいって思ったんじゃない？",
