        [51010106] = {
            ["Camera"] = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "抱……抱歉，我刚才没看路！没受伤吧？有没有哪里不舒服？",
            ["ContentJP"] = "ご、ごめんなさいっ！……どこかお怪我は？",
            ["DialogueId"] = 51010106,
            ["FacialId"] = {
                [1] = "700302:CM_Angry01",
                },
            ["GUID"] = "7FB2CD84",
            ["NextDialogue"] = 51010107,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010107] = {
            ["Content"] = "我没事，下次注意就好。",
            ["ContentJP"] = "大丈夫。次は気をつけてね。",
            ["DialogueId"] = 51010107,
            ["GUID"] = "7FB2CDAE",
            ["NextDialogue"] = 51010108,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
