                [1] = "100001:Talk03_Start",
                },
            },
        [51010110] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没什么，嘻嘻……谢谢你的草药。",
            ["ContentJP"] = "ううん、ふふ……薬草、ありがとう！",
            ["DialogueId"] = 51010110,
            ["FacialId"] = {
                [1] = "700305:CM_Happy01",
                },
            ["GUID"] = "7FB2CE2C",
            ["NextDialogue"] = 51010111,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "700305:Think_End",
                },
            },
        [51010111] = {
            ["Content"] = "约定的时间要来不及了哦。",
            ["ContentJP"] = "約束の時間に遅れるよ！",
            ["DialogueId"] = 51010111,
            ["GUID"] = "7FB2CE56",
            ["NextDialogue"] = 51010112,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010112] = {
            ["Content"] = "啊抱歉了我得走了！来了来了，等等我！",
            ["ContentJP"] = "あっ、やばっ！行かなきゃ！待って〜！",
            ["DialogueId"] = 51010112,
            ["GUID"] = "7FB2CE80",
            ["NextDialogue"] = 51010113,
            ["Scripts"] = "MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            },
        [51010113] = {
            ["Content"] = "什么草药……？等一下，你东西掉了！",
            ["ContentJP"] = "薬草……？待って、何か落としたよ！",
            ["DialogueId"] = 51010113,
            ["GUID"] = "7FB2CEAA",
            ["NextDialogue"] = 51010114,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Nvzhu_Story_StretchHand_Start",
                },
            },
        [51010114] = {
            ["Content"] = "——送给你了！！",
            ["ContentJP"] = "――あげるっ！！",
            ["DialogueId"] = 51010114,
            ["GUID"] = "7FB2CED4",
            ["NextDialogue"] = 51010115,
            ["SpeakNpcId"] = 700305,
            ["SpeakNpcName"] = "UI_CMNpc_Name_Rosalind02",
            ["TalkActionId"] = {
                [1] = "100001:Nvzhu_Story_StretchHand_End",
                },
            },
        [51010115] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在的年轻人还真是风风火火。",
            ["ContentJP"] = "はは、最近の若い子って、ほんとせっかち。",
            ["DialogueId"] = 51010115,
            ["GUID"] = "7FB2CEFE",
            ["LookAt"] = {
                [1] = "700302:n(100001)",
                [2] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51010116,
            ["SpeakNpcId"] = 700302,
            },
        [51010116] = {
            ["Content"] = "说什么送给我了……这上面好像绣了字，是那个女孩的名字吗？",
            ["ContentJP"] = "あげるって言われても……",
            ["DialogueId"] = 51010116,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                [2] = "700302:CM_Idle",
                },
            ["GUID"] = "7FB2CF28",
            ["NextDialogue"] = 51010117,
            ["SpeakNpcId"] = 100001,
            },
        [51010117] = {
            ["Content"] = "勇敢的蝴蝶挣脱了茧，向着天空振翅，她随风隐去，就像一枝紫罗兰消失在花海。",
            ["ContentJP"] = "勇敢な蝶は繭を破って羽ばたき、風に乗って消えていきました――まるで紫のスミレが、花の海へと溶け込むように。",
            ["DialogueId"] = 51010117,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FB2CF52",
            ["NextDialogue"] = 51010118,
            ["Scripts"] = "MoveTo{ActorId{700311},TargetPoint{\"ViolettePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010118] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "她可能很长一段时间都不会再同你我见面了……所以收下这份临别的礼物吧，她珍视的朋友。",
            ["ContentJP"] = "もうしばらく、彼女があなたの前に現れることはないでしょう。だからこそ、これは彼女から大切な友人への最後の贈り物です。",
            ["DialogueId"] = 51010118,
            ["GUID"] = "7FB2CF7C",
            ["LookAt"] = {
                [1] = "100001:n(700311)",
                [2] = "700302:n(700311)",
                },
            ["NextDialogue"] = 51010119,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010119] = {
            ["Camera"] = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "临别的礼物……这上面好像绣了字，是那个女孩的名字吗？",
            ["ContentJP"] = "贈り物……刺繍がある……あの子の名前かな？",
            ["DialogueId"] = 51010119,
            ["GUID"] = "7FB2CFA6",
            ["NextDialogue"] = 51010120,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51010120] = {
            ["Content"] = "……普蒂妮？",
            ["ContentJP"] = "……プティニー？",
            ["DialogueId"] = 51010120,
            ["GUID"] = "7FB2CFD0",
            ["NextDialogue"] = 51010121,
            ["SpeakNpcId"] = 100001,
            },
        [51010121] = {
            ["Content"] = "如果你以后遇到了一个叫普蒂妮的女孩，请一定要认出我，我也一定会认出你的。",
            ["ContentJP"] = "「もし、いつか『プティニー』という名の娘に出会ったら……どうか、私だと気づいてください。私もきっと、あなたを見つけてみせますから」",
            ["DialogueId"] = 51010121,
            ["GUID"] = "7FB2CFFA",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51010122,
            },
        [51010122] = {
            ["Content"] = "原来是这样啊，看来箱子小姐她平安踏上自己的旅途了。这么说来你是——",
            ["ContentJP"] = "そうか……箱の中のあの子、ちゃんと旅立てたんだね。ということは、あなたは……",
            ["DialogueId"] = 51010122,
            ["GUID"] = "7FB2D024",
            ["NextDialogue"] = 51010123,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51010123] = {
            ["Camera"] = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘘——虽然我认可你们的揭发，但还是会保守秘密的孩子更可爱哦。",
            ["ContentJP"] = "しーっ。真相を暴いてくれたことは感謝してるけど、秘密を守れる子のほうが私は好きよ。",
            ["DialogueId"] = 51010123,
            ["GUID"] = "7FB2D04E",
            ["NextDialogue"] = 51010124,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "700311:Disagree",
                },
            },
        [51010124] = {
            ["Content"] = "就这么暴露身份，你不怕我再找麻烦？",
            ["ContentJP"] = "そんなに堂々と正体バラして、また私に告発されるかもって思わないの？",
            ["DialogueId"] = 51010124,
            ["GUID"] = "7FB2D078",
            ["NextDialogue"] = 51010125,
            ["SpeakNpcId"] = 700302,
            },
        [51010125] = {
            ["Content"] = "“薇奥莱塔”不会再登台，可我短期内并不打算离开这里。当然，就算你再次揭发，我也不会有怨言。只是事关我的另一位学生，我无法弃之不顾。",
            ["ContentJP"] = "「ヴィオレッタ」はもう舞台に立たない。けど私はしばらくここにいるつもりよ。あなたがまた私を告発しても、恨んだりはしないわ。でも、もうひとりの教え子のこと――どうしても放っておけなくてね。",
            ["DialogueId"] = 51010125,
            ["GUID"] = "7FB2D0A2",
            ["NextDialogue"] = 51010126,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010126] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51010126,
            ["GUID"] = "7FB2D0CC",
            ["NextDialogue"] = 51010127,
            ["SpeakNpcId"] = 700302,
            },
        [51010127] = {
            ["Content"] = "……感谢你的沉默。",
            ["ContentJP"] = "……ありがとう。",
            ["DialogueId"] = 51010127,
            ["FacialId"] = {
                [1] = "700311:CM_Happy01",
                },
            ["GUID"] = "7FB2D0F6",
            ["NextDialogue"] = 51010128,
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "700311:Agree",
                },
            },
        [51010128] = {
            ["Content"] = "那么失陪了，愿二位度过一个美妙的假日。",
            ["ContentJP"] = "それでは、素敵な休暇を。",
            ["DialogueId"] = 51010128,
            ["GUID"] = "7FB2D120",
            ["NextDialogue"] = 51010129,
            ["Scripts"] = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 700311,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            },
        [51010129] = {
            ["Camera"] = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈，我就知道，那样的女人怎么可能乖乖束手就擒。",
            ["ContentJP"] = "やっぱりね。あの女が大人しく捕まるわけないと思ってた。",
            ["DialogueId"] = 51010129,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2D14A",
            ["LookAt"] = {
                [1] = "700302:n(100001)",
                [2] = "100001:n(700302)",
                },
            ["NextDialogue"] = 51010130,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "700302:Confident_Start",
                },
            },
        [51010130] = {
            ["Content"] = "你看起来好像有点高兴？",
            ["ContentJP"] = "なんだか、うれしそう？",
            ["DialogueId"] = 51010130,
            ["GUID"] = "7FB2D174",
            ["NextDialogue"] = 51010131,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51010131] = {
            ["Content"] = "这样吗？说实话，我也纠结过到底要不要牺牲活人的生活去换死者的清白……",
            ["ContentJP"] = "そう見える？……正直言うとね、生きてる人間の人生を犠牲にして、死者の名誉を守るってのは、悩んだわ。",
            ["DialogueId"] = 51010131,
            ["GUID"] = "7FB2D19E",
            ["NextDialogue"] = 51010132,
            ["SpeakNpcId"] = 700302,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_End",
                },
            },
        [51010132] = {
            ["Content"] = "如你所见，我做出了选择，这是吉赛尔的执着。",
            ["ContentJP"] = "でも、私なりの答えを出した。これが、ジゼルの選んだ道よ。",
            ["DialogueId"] = 51010132,
            ["GUID"] = "7FB2D1C8",
            ["NextDialogue"] = 51010133,
            ["SpeakNpcId"] = 700302,
            },
        [51010133] = {
            ["Content"] = "不过既然能在二选一的局面被打破后而感到开心，说明我这十六年来也有了成长不是吗？",
            ["ContentJP"] = "それに――こうしてどちらも失わずに済んで、今、少しでもホッとしてるってことは……私も、この十六年で少しは成長できたってことかもね。",
            ["DialogueId"] = 51010133,
            ["FacialId"] = {
                [1] = "700302:CM_Sad01",
                },
            ["GUID"] = "7FB2D1F2",
            ["NextDialogue"] = 51010134,
            ["SpeakNpcId"] = 700302,
            },
        [51010134] = {
            ["Content"] = "要是十六年前的我也能像现在一样，或许就不会有人因此逝去了。",
            ["ContentJP"] = "十六年前も、今の私みたいに振る舞えてたら……誰も死なずに済んだのかなって、少し思っただけ。",
            ["DialogueId"] = 51010134,
            ["GUID"] = "7FB2D21C",
            ["NextDialogue"] = 51010135,
            ["SpeakNpcId"] = 700302,
            },
        [51010135] = {
            ["Content"] = "这不是你的错，吉赛尔。",
            ["ContentJP"] = "ジゼルのせいじゃないよ。",
            ["DialogueId"] = 51010135,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FB2D246",
            ["NextDialogue"] = 51010136,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Disagree",
                },
            },
        [51010136] = {
            ["Content"] = "放心，我没有难过，我只是在想“狩月人吉赛尔”歇业后要去做点什么。",
            ["ContentJP"] = "大丈夫よ、落ち込んでるわけじゃないから。ただ――「月狩り人ジゼル」が休業になったから、次は何をしようかって考えてただけ。",
            ["DialogueId"] = 51010136,
            ["FacialId"] = {
                [1] = "700302:CM_Smile01",
                },
            ["GUID"] = "7FB2D270",
            ["NextDialogue"] = 51010137,
            ["SpeakNpcId"] = 700302,
            },
        [51010137] = {
            ["Content"] = "我放弃当演员了，看过薇奥莱塔的演出之后很难再夸下这种海口啊……",
            ["ContentJP"] = "役者はもうやめるわ。ヴィオレッタの舞台を観てたら、なんだか恥ずかしくなっちゃった。",
            ["DialogueId"] = 51010137,
            ["GUID"] = "7FB2D29A",
            ["NextOptions"] = {
                [1] = 510100471,
                [2] = 510100472,
                },
            ["SpeakNpcId"] = 700302,
            },
        }
  end },
  { MinKey = 51010138, MaxKey = 51011018, Loader = function()
      return {
        [51010138] = {
            ["Content"] = "因为感觉很赚钱。",
            ["ContentJP"] = "だって、儲かりそうじゃん。",
            ["DialogueId"] = 51010138,
            ["FacialId"] = {
                [1] = "700302:CM_Happy01",
                },
            ["GUID"] = "7FB2D2C4",
            ["NextDialogue"] = 51010140,
            ["SpeakNpcId"] = 700302,
            },
        [51010139] = {
            ["Content"] = "就别挖苦我了，真正的神探。",
            ["ContentJP"] = "茶化さないでよ、名探偵さん。",
            ["DialogueId"] = 51010139,
            ["GUID"] = "7FB2D2EE",
            ["NextDialogue"] = 51010140,
            ["SpeakNpcId"] = 700302,
            },
        [51010140] = {
            ["Content"] = "那现在呢，你打算做什么？",
