            ["DialogueId"] = 51010140,
            ["GUID"] = "7FB2D318",
            ["NextDialogue"] = 51010141,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02R_Start",
                },
            },
        [51010141] = {
            ["Content"] = "嗯……不知道。不过反正时间还有很多，我会慢慢想。",
            ["ContentJP"] = "うーん、まだ決めてない。でも、時間はあるから、ゆっくり考えるわ。",
            ["DialogueId"] = 51010141,
            ["FacialId"] = {
                [1] = "700302:CM_Happy01",
                },
            ["GUID"] = "7FB2D342",
            ["NextDialogue"] = 51010142,
            ["SpeakNpcId"] = 700302,
            },
        [51010142] = {
            ["Content"] = "毕竟舞台那么大，总会找到适合自己的那个角色的。",
            ["ContentJP"] = "だって舞台は広いもの。きっといつか、自分にぴったりの役が見つかると思う。",
            ["DialogueId"] = 51010142,
            ["GUID"] = "7FB2D36C",
            ["SpeakNpcId"] = 700302,
            },
        [51010143] = {
            ["Camera"] = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请等一下！",
            ["ContentJP"] = "待って！",
            ["DialogueId"] = 51010143,
            ["FacialId"] = {
                [1] = "700300:CM_Smile01",
                [2] = "700302:CM_Angry01",
                [3] = "100001:Angry01",
                },
            ["GUID"] = "7FB2AA92",
            ["NextDialogue"] = 51009894,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Nvzhu_Story_StretchHand_Start",
                },
            },
        [51010201] = {
            ["Content"] = "♪熔炉焚烧黎明 倾倒出白雪与铁的城塞……",
            ["ContentJP"] = "♪熔炉は黎明を焼き尽くし　白雪と鉄より　城が生まれん",
            ["DialogueId"] = 51010201,
            ["GUID"] = "7FB2DD1A",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB2DD1A",
            },
        [51010202] = {
            ["Content"] = "♪熔炉焚烧黎明 倾倒出白雪与铁的城塞\
齿轮高歌 吞没晨星 赞颂北地的伟大时代——",
            ["ContentJP"] = "熔炉は黎明を焼き尽くし　白雪と鉄より　城が生まれん　歯車高らかに歌い　暁の星静かに呑みこむ　讃えましょう　北の地に刻まれし　偉大なる時代を\
\
",
            ["DialogueId"] = 51010202,
            ["GUID"] = "7FB2DD44",
            ["NextDialogue"] = 51010203,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD44",
            },
        [51010203] = {
            ["Content"] = "嗯？你叫我……",
            ["ContentJP"] = "……あら？私に何かご用？",
            ["DialogueId"] = 51010203,
            ["GUID"] = "7FB2DD6E",
            ["LookAt"] = {
                [1] = "700342:n(0)",
                },
            ["NextOptions"] = {
                [1] = 510102031,
                [2] = 510102032,
                },
            ["SpeakNpcId"] = 700342,
            ["TalkActionId"] = {
                [1] = "700342:Lilikou_Story_Playlyre_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD6E",
            },
        [51010204] = {
            ["Content"] = "谢谢你，陌生的旅人！不过这首歌还没有完成，或许你可以和我一起来创作它。",
            ["ContentJP"] = "まあ、ありがとう、見知らぬ旅人さん！でも、この歌はまだ完成していないの。よかったら、一緒に続きを紡いでくれるかしら？",
            ["DialogueId"] = 51010204,
            ["GUID"] = "7FB2DD98",
            ["NextDialogue"] = 51010206,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DD98",
            },
        [51010205] = {
            ["Content"] = "很抱歉打扰到你！不过我问过那边的士兵，这座城市的广场并没有张贴律令，禁止一位吟游诗人在这里唱歌。",
            ["ContentJP"] = "ごめんなさい！でも、あちらの衛兵さんに確認したわ。この広場では、吟遊詩人が歌ってはいけないお触れなんて、なかったと思うけど……",
            ["DialogueId"] = 51010205,
            ["GUID"] = "7FB2DDC2",
            ["NextDialogue"] = 51010206,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DDC2",
            },
        [51010206] = {
            ["Content"] = "后一句应该是什么呢……",
            ["ContentJP"] = "締めの一句は何にしようかしら……",
            ["DialogueId"] = 51010206,
            ["GUID"] = "7FB2DDEC",
            ["NextDialogue"] = 51010207,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DDEC",
            },
        [51010207] = {
            ["Content"] = "我想我应该写“风”……每个地方的风都是不同的……",
            ["ContentJP"] = "やっぱり「風」がいいと思うの……どの場所も風だけは違うから……",
            ["DialogueId"] = 51010207,
            ["GUID"] = "7FB2DE16",
            ["NextDialogue"] = 51010208,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE16",
            },
        [51010208] = {
            ["Content"] = "艾利西安的风是融化在晚祷里的乳香，卢卡的风是画室的松节油和咖啡店的焦糖，伊瑟尔的风是混着野薄荷的油墨……",
            ["ContentJP"] = "エリュシオンの風は、晩祷に溶けたミルクの香り。ルッカの風は、画室のテレピン油と、街角のカラメル。イーザーの風は、野のミントと古いインクの匂いが入り混じってる……",
            ["DialogueId"] = 51010208,
            ["GUID"] = "7FB2DE40",
            ["NextDialogue"] = 51010209,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE40",
            },
        [51010209] = {
            ["Content"] = "那么海伯利亚的“风”是什么呢？",
            ["ContentJP"] = "ヒュペリアの風はどんなのかしら？",
            ["DialogueId"] = 51010209,
            ["GUID"] = "7FB2DE6A",
            ["NextOptions"] = {
                [1] = 510102091,
                [2] = 510102092,
                [3] = 510102093,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE6A",
            },
        [51010210] = {
            ["Content"] = "嗯……你说的有道理。这里有很多钢铁的森林，就像这座城市一样。",
            ["ContentJP"] = "ふむ……確かにそうね。この街には、鉄の森がいくつもあるもの。",
            ["DialogueId"] = 51010210,
            ["GUID"] = "7FB2DE94",
            ["NextDialogue"] = 51010211,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DE94",
            },
        [51010211] = {
            ["Content"] = "虽然吹起来有些冷，但风会捎来那些齿轮和引擎的声音，它们摸起来总是滚烫的。",
            ["ContentJP"] = "風は少し冷たくて、でもそこには、歯車やエンジンの音が混じってる。そういう音って、不思議と……いつも熱を帯びてるのよ。",
            ["DialogueId"] = 51010211,
            ["GUID"] = "7FB2DEBE",
            ["NextDialogue"] = 51010212,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DEBE",
            },
        [51010212] = {
            ["Content"] = "士兵的枪管或许也是滚烫的，虽然他们的表情是冷的……",
            ["ContentJP"] = "たぶん、兵士たちの銃身もそう。触れればきっと熱いのに、彼らの表情は、ひどく冷たいの。",
            ["DialogueId"] = 51010212,
            ["GUID"] = "7FB2DEE8",
            ["NextDialogue"] = 51010220,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DEE8",
            },
        [51010213] = {
            ["Content"] = "嗯！这座城市的四分之三是由雪组成的。因为这里的人说，冰湖城总是在下雪，融雪季只有短短的三个月~",
            ["ContentJP"] = "確かに！この街の四分の三は、雪でできてるしね。アイスレイク城には、いつも雪が降ってるし……雪解けの季節なんて、ほんの三ヶ月しかない。",
            ["DialogueId"] = 51010213,
            ["GUID"] = "7FB2DF12",
            ["NextDialogue"] = 51010214,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF12",
            },
        [51010214] = {
            ["Content"] = "而且风和雪总是在一起的，这是大自然给我们的经典搭配！",
            ["ContentJP"] = "それにね、風と雪って、どこへ行っても一緒なの。自然が選んだ最高の組み合わせだと思うわ。",
            ["DialogueId"] = 51010214,
            ["GUID"] = "7FB2DF3C",
            ["NextDialogue"] = 51010220,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF3C",
            },
        [51010215] = {
            ["Content"] = "“眼泪”吗……是这首歌前面没有用过的意象呢……",
            ["ContentJP"] = "「涙」か……この歌にはまだ出てこなかった言葉ね。",
            ["DialogueId"] = 51010215,
            ["GUID"] = "7FB2DF66",
            ["NextDialogue"] = 51010216,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF66",
            },
        [51010216] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51010216,
            ["GUID"] = "7FB2DF90",
            ["NextDialogue"] = 51010217,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DF90",
            },
        [51010217] = {
            ["Content"] = "第一天来到这座广场时，我看到一位目盲的小丑在广场表演，他说他的眼是多年前被锅炉熏坏的。一个孩子被表演逗得狂笑不止，他的仆人便抛下银币。",
            ["ContentJP"] = "初めてこの広場に来たとき、目の見えない道化師がいたの。昔、ボイラーの煙で目をやられたって言ってたわ。それでも、彼の芸に子どもが笑い――付き添いの人が、銀貨を放っていた。",
            ["DialogueId"] = 51010217,
            ["GUID"] = "7FB2DFBA",
            ["NextDialogue"] = 51010218,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DFBA",
            },
        [51010218] = {
            ["Content"] = "我现在坐的这条长椅上，一个退伍老兵叫喊着，兜售自己最后一枚勋章。旁边的长椅上，一个消瘦的母亲从干瘪的乳房挤出奶水喂给她重病的孩子。",
            ["ContentJP"] = "私が今座っているこのベンチには、退役した兵士がいて、自分の最後の勲章を誰かに買ってもらおうとしてる。隣では、やせたお母さんが、弱った赤ちゃんに母乳をあげてたわ。もう出るかどうかもわからないのに。",
            ["DialogueId"] = 51010218,
            ["GUID"] = "7FB2DFE4",
            ["NextDialogue"] = 51010219,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2DFE4",
            },
        [51010219] = {
            ["Content"] = "……我想那时，吹过这座广场的风，捎来的就是“眼泪”吧。",
            ["ContentJP"] = "……あのとき、広場を吹き抜けていた風が運んでいたのは、きっと「涙」だったのね。",
            ["DialogueId"] = 51010219,
            ["GUID"] = "7FB2E00E",
            ["NextDialogue"] = 51010220,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2E00E",
            },
        [51010220] = {
            ["Content"] = "谢谢你的建议，如冰原上玫瑰一般的{性别：先生|小姐}……我想，我很快就可以完成这首歌了。",
            ["ContentJP"] = "ありがとう、氷原に咲くバラのようなお方……ふふっ……なんだか、もう少しで歌が完成しそうな気がするわ。",
            ["DialogueId"] = 51010220,
            ["GUID"] = "7FB2E038",
            ["SpeakNpcId"] = 700342,
            ["TalkActionId"] = {
                [1] = "700342:Lilikou_Story_Playlyre_Start",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2E038",
            },
        [51010221] = {
            ["Content"] = "谢谢你的建议，如冰原上玫瑰一般的{性别：先生|小姐}。",
            ["ContentJP"] = "ありがとう、氷原に咲くバラのようなお方。",
            ["DialogueId"] = 51010221,
            ["GUID"] = "7FB2E062",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510102/7FB2E062",
            },
        [51010301] = {
            ["Content"] = "卡戎之民的雾海神话……",
            ["ContentJP"] = "……カロン族に伝わる、ニヴルヘイムの神話……",
            ["DialogueId"] = 51010301,
            ["GUID"] = "7FB2ED82",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB2ED82",
            },
        [51010302] = {
            ["Content"] = "……最有趣的就是这一篇，它说雾海中的万物都在生和死的循环中，你觉得呢？伊——",
            ["ContentJP"] = "ふふ、なかでも私がいちばん気に入っているのは――これ。ニヴルヘイムに生きるものは、すべて「生」と「死」のあいだを巡っている……あなたは、どう思う？ イ……",
            ["DialogueId"] = 51010302,
            ["GUID"] = "7FB2EDAC",
            ["NextDialogue"] = 51010303,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EDAC",
            },
        [51010303] = {
            ["Content"] = "啊，是你！我记得你的，我们上次就在这儿说过话。",
            ["ContentJP"] = "……あら、あなただったのね！覚えているわ、前にもこの場所でお話ししたもの。",
            ["DialogueId"] = 51010303,
            ["GUID"] = "7FB2EDD6",
            ["NextDialogue"] = 51010304,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EDD6",
            },
        [51010304] = {
            ["Content"] = "你有看到我的朋友吗？一个红发的女孩子，刚才应该就在这儿……",
            ["ContentJP"] = "ねえ、赤い髪の女の子、見かけなかった？さっきまで、ここにいたはずなんだけど……",
            ["DialogueId"] = 51010304,
            ["GUID"] = "7FB2EE00",
            ["NextOptions"] = {
                [1] = 51010305,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EE00",
            },
        [51010305] = {
            ["Content"] = "没有见过。",
            ["ContentJP"] = "見ていないよ。",
            ["DialogueId"] = 51010305,
            ["GUID"] = "7FB2EE2A",
            ["NextDialogue"] = 51010306,
            },
        [51010306] = {
            ["Content"] = "谢谢！那我继续等一会儿。她常常突然离开，又突然回来。",
            ["ContentJP"] = "ありがとう。もう少し待ってみるわ。あの子、いつも突然いなくなって、いつのまにか戻ってくるの。",
            ["DialogueId"] = 51010306,
            ["GUID"] = "7FB2EE54",
            ["NextDialogue"] = 51010307,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EE54",
            },
        [51010307] = {
            ["Content"] = "这几天，我们在这儿收集了许多卡戎之民的古老神话。我很惊讶，这里的人竟然不避讳讲这些。",
            ["ContentJP"] = "この数日、私たちはここで、カロン族の古い神話をたくさん集めていたのよ。驚いたわ――この街では、そういう話を隠そうともしないのね。",
            ["DialogueId"] = 51010307,
            ["GUID"] = "7FB2EE7E",
            ["NextDialogue"] = 51010308,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EE7E",
            },
        [51010308] = {
            ["Content"] = "在我们的故乡艾利西安，那里的卡戎之民地位比这里崇高得多。他们坐在高台上，与神问答，执掌权柄。但在那儿，讨论古老的神话是一件危险的事。",
            ["ContentJP"] = "エリュシオンの故郷では、カロン族はもっと高貴な存在とされていたわ。神と語らい、権威を授かる者として、高台に座す人々。でもね……あの地では、古い神話を語ること自体が、危うい行為だったの。",
            ["DialogueId"] = 51010308,
            ["GUID"] = "7FB2EEA8",
            ["NextDialogue"] = 51010309,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EEA8",
            },
        [51010309] = {
            ["Content"] = "对了，你知道卡戎之民的神话吗？",
            ["ContentJP"] = "ねえ、あなたはカロン族の神話、聞いたことある？",
            ["DialogueId"] = 51010309,
            ["GUID"] = "7FB2EED2",
            ["NextOptions"] = {
                [1] = 51010310,
                [2] = 51010311,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EED2",
            },
        [51010310] = {
            ["Content"] = "知道一点。",
            ["ContentJP"] = "少しだけ。",
            ["DialogueId"] = 51010310,
            ["GUID"] = "7FB2EEFC",
            ["NextDialogue"] = 51010312,
            },
        [51010311] = {
            ["Content"] = "不知道。",
            ["ContentJP"] = "ぜんぜん。",
            ["DialogueId"] = 51010311,
            ["GUID"] = "7FB2EF26",
            ["NextDialogue"] = 51010312,
            },
        [51010312] = {
            ["Content"] = "“卡戎”，这个词的意思是“来自雾海之人”……",
            ["ContentJP"] = "「カロン」という単語は、「ニヴルヘイムから来たりし者」を意味しているの。",
            ["DialogueId"] = 51010312,
            ["GUID"] = "7FB2EF50",
            ["NextDialogue"] = 51010313,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EF50",
            },
        [51010313] = {
            ["Content"] = "雾海是一切的原点。圣树自雾海生长，天之树是它庞大的枝叶，世界则立于圣树之上。",
            ["ContentJP"] = "ニヴルヘイムは、すべての始まり。聖なる樹はその海から芽吹き、やがて空を貫いて枝を広げる。その枝こそ「天上樹」、そして私たちの世界は――聖なる樹の上に築かれたもの。",
            ["DialogueId"] = 51010313,
            ["GUID"] = "7FB2EF7A",
            ["NextDialogue"] = 51010314,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EF7A",
            },
        [51010314] = {
            ["Content"] = "圣树绽放纯白的花，从中走出母神茵布拉。她创造万物，其中就有父神埃斯刻。母神与父神诞育出卡戎之民共同的先祖。",
            ["ContentJP"] = "聖なる樹は純白の花を咲かせ、そこから母なる神エムブラが現れたわ。彼女はあらゆるものを生み、そのなかには、父なる神アスクもいた。そしてふたりから、カロン族の始祖が生まれたの。",
            ["DialogueId"] = 51010314,
            ["GUID"] = "7FB2EFA4",
            ["NextDialogue"] = 51010315,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EFA4",
            },
        [51010315] = {
            ["Content"] = "但执掌<W>死之权能</>的埃斯刻却成为灾厄的化身，并最终带来叫做“日蚀”的末日。",
            ["ContentJP"] = "けれど……<W>死を司る</>アクスは、やがて災厄そのものとなり、「ラグナロク」という名の終焉をもたらした。",
            ["DialogueId"] = 51010315,
            ["GUID"] = "7FB2EFCE",
            ["NextDialogue"] = 51010316,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EFCE",
            },
        [51010316] = {
            ["Content"] = "在末日中，执掌<H>生之权能</>的母神庇护了她的子民，她散碎的灵魂飘向海洋，最终归于雾海——",
            ["ContentJP"] = "その災いの中、<H>生を司る</>エムブラは民をかばい、彼女の魂は砕け散って、海へと還り……やがてニヴルヘイムに溶けたの。",
            ["DialogueId"] = 51010316,
            ["GUID"] = "7FB2EFF8",
            ["NextDialogue"] = 51010317,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2EFF8",
            },
        [51010317] = {
            ["Content"] = "父神的身躯则化为大地，他高高举起的手臂化为山岳，永远伸向不知何时归来的神明。",
            ["ContentJP"] = "一方で、父なる神の身体は大地に変わり、天へ伸ばされたその腕は、山となった。それは、いつか神が戻る日を信じて、ずっと空へと手を伸ばし続けている――",
            ["DialogueId"] = 51010317,
            ["GUID"] = "7FB2F022",
            ["NextOptions"] = {
                [1] = 51010318,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F022",
            },
        [51010318] = {
            ["Content"] = "是个有些伤感的故事。",
            ["ContentJP"] = "なんだか、少し切ない話だね。",
            ["DialogueId"] = 51010318,
            ["GUID"] = "7FB2F04C",
            ["NextDialogue"] = 51010319,
            },
        [51010319] = {
            ["Content"] = "嗯，不过在这些古老的神话里，还有另一个有趣的故事。",
            ["ContentJP"] = "ええ……でもね、この神話には、もうひとつ別のお話もあるの。",
            ["DialogueId"] = 51010319,
            ["GUID"] = "7FB2F076",
            ["NextDialogue"] = 51010320,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F076",
            },
        [51010320] = {
            ["Content"] = "有个故事说，埃斯刻和茵布拉已经在末日后的新世界，以新生的样貌出现。",
            ["ContentJP"] = "終焉のあと、エムブラとアスクは新たな姿でふたたび生まれ変わった。",
            ["DialogueId"] = 51010320,
            ["GUID"] = "7FB2F0A0",
            ["NextDialogue"] = 51010321,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F0A0",
            },
        [51010321] = {
            ["Content"] = "而新生的他们则会带来新的一轮末日，以及再一度毁灭，再一度新生。",
            ["ContentJP"] = "そして、新たな彼らは、新たな「ラグナロク」を引き起こす。",
            ["DialogueId"] = 51010321,
            ["GUID"] = "7FB2F0CA",
            ["NextDialogue"] = 51010322,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F0CA",
            },
        [51010322] = {
            ["Content"] = "世界在无尽的循环之中，万物都在新生与死亡间轮回往复。",
            ["ContentJP"] = "世界はまた滅び、そして生まれ変わり、すべては絶え間ない循環の中にある……と。",
            ["DialogueId"] = 51010322,
            ["GUID"] = "7FB2F0F4",
            ["NextOptions"] = {
                [1] = 51010323,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F0F4",
            },
        [51010323] = {
            ["Content"] = "看来古人也不喜欢悲剧的结局。",
            ["ContentJP"] = "古代の人も、悲しい結末はあまり好きじゃなかったのかもね。",
            ["DialogueId"] = 51010323,
            ["GUID"] = "7FB2F11E",
            ["NextDialogue"] = 51010324,
            },
        [51010324] = {
            ["Content"] = "不过……我有些在意的是，为什么这个故事的作者坚信父神和母神得到了新生？或者说，是什么“定义”了茵布拉和埃斯刻的本质呢？",
            ["ContentJP"] = "ふふっ、そうかもしれないわね。でも……私、ひとつ気になるの。なぜこの話を書いた人は、ふたりの神が「生まれ変わった」って信じたのかしら？あるいは……何が「エムブラ」や「アスク」を定義していたのか――それが、知りたくなるの。",
            ["DialogueId"] = 51010324,
            ["GUID"] = "7FB2F148",
            ["NextDialogue"] = 51010325,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F148",
            },
        [51010325] = {
            ["Content"] = "是他们的肉体，他们的灵魂？……还是其他？",
            ["ContentJP"] = "彼らの肉体？ 魂？ それとも、まったく別の何か？",
            ["DialogueId"] = 51010325,
            ["GUID"] = "7FB2F172",
            ["NextDialogue"] = 51010326,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F172",
            },
        [51010326] = {
            ["Content"] = "假设——我是说假设，一位伟大的魔法师把我们脚下的大地重新变成了埃斯刻的模样——那么这个埃斯刻，和新生的埃斯刻，哪个才是我们的父神大人呢？",
            ["ContentJP"] = "たとえば……ただの例えよ？もし偉大な魔法使いがこの大地を作り直して、アスクの姿にしたら――その「新しいアスク」と、「生まれ変わったアスク」、どちらが「父なる神」と呼ぶべき存在なのかしら？",
            ["DialogueId"] = 51010326,
            ["GUID"] = "7FB2F19C",
            ["NextOptions"] = {
                [1] = 510103261,
                [2] = 510103262,
                [3] = 510103263,
                [4] = 510103264,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F19C",
            },
        [51010327] = {
            ["Content"] = "原来你是这样认为的……谢谢！你的观点启发了我很多。",
            ["ContentJP"] = "……なるほど。ふふっ、ありがとう。あなたの考え方、とても面白いわね。ずいぶん、感銘を受けたわ。",
            ["DialogueId"] = 51010327,
            ["GUID"] = "7FB2F1C6",
            ["NextDialogue"] = 51010329,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F1C6",
            },
        [51010328] = {
            ["Content"] = "很多创作都是从一个无聊的问题开始的，不是吗？",
            ["ContentJP"] = "面白い創作って、たいてい、そんな「退屈な問い」から始まるものなのよ？",
            ["DialogueId"] = 51010328,
            ["GUID"] = "7FB2F1F0",
            ["NextDialogue"] = 51010329,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F1F0",
            },
        [51010329] = {
            ["Content"] = "谢谢你，如蜡烛上火焰一般的{性别：先生|小姐}。我很喜欢这些神话，现在我已经有了关于它们的歌。",
            ["ContentJP"] = "ありがとう、あなたはロウソクの炎みたいに揺れる、あたたかいお方ね。これらの神話……きっと素敵な歌にしてみせるわ。",
            ["DialogueId"] = 51010329,
            ["GUID"] = "7FB2F21A",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F21A",
            },
        [51010330] = {
            ["Content"] = "是什么让我们得以成为“我们”？",
            ["ContentJP"] = "私たちを「私たち」たらしめるものって、何かしら？",
            ["DialogueId"] = 51010330,
            ["GUID"] = "7FB2F244",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510103/7FB2F244",
            },
        [51010401] = {
            ["Content"] = "盖雷亚剧院……",
            ["ContentJP"] = "ガレア劇場……",
            ["DialogueId"] = 51010401,
            ["GUID"] = "7FB2FDEA",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB2FDEA",
            },
        [51010402] = {
            ["Content"] = "又见面了，如白沙上石榴石一般的{性别：先生|小姐}。你很喜欢到这儿来呢，我也是。",
            ["ContentJP"] = "あら、また会えたね。白い砂の上で光るガーネットのようなお方。あなたも、ここが好きなのね。",
            ["DialogueId"] = 51010402,
            ["GUID"] = "7FB2FE14",
            ["NextDialogue"] = 51010403,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE14",
            },
        [51010403] = {
            ["Content"] = "你去过盖雷亚剧院吗？",
            ["ContentJP"] = "ねえ、ガレア劇場へ行ったことはある？",
            ["DialogueId"] = 51010403,
            ["GUID"] = "7FB2FE3E",
            ["NextOptions"] = {
                [1] = 510104031,
                [2] = 510104032,
                [3] = 510104033,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE3E",
            },
        [51010404] = {
            ["Content"] = "噢！真让人羡慕，你一定很富有。",
            ["ContentJP"] = "まあ、うらやましい……きっと裕福な方なのね。",
            ["DialogueId"] = 51010404,
            ["GUID"] = "7FB2FE68",
            ["NextDialogue"] = 51010407,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE68",
            },
        [51010405] = {
            ["Content"] = "嗯……你也是吗。",
            ["ContentJP"] = "……ふふっ、そう。あなたも、なのね。",
            ["DialogueId"] = 51010405,
            ["GUID"] = "7FB2FE92",
            ["NextDialogue"] = 51010407,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FE92",
            },
        [51010406] = {
            ["Content"] = "和军团？不可思议。看来你身上也有很多很多故事。",
            ["ContentJP"] = "えっ、帝国軍と……？信じられないわ。あなたって、本当に物語に満ちているのね。",
            ["DialogueId"] = 51010406,
            ["GUID"] = "7FB2FEBC",
            ["NextDialogue"] = 51010407,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FEBC",
            },
        [51010407] = {
            ["Content"] = "我在卢卡去过大大小小的歌剧院，但总被海伯利亚的剧院关在门外。",
            ["ContentJP"] = "私はルッカでいくつもの劇場を巡ったけれど、このヒュペリアでは、なかなか中に入れてもらえなくて。",
            ["DialogueId"] = 51010407,
            ["GUID"] = "7FB2FEE6",
            ["NextDialogue"] = 51010408,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FEE6",
            },
        [51010408] = {
            ["Content"] = "虽然知道卡戎之民在这儿过得不算好，但公共设施收的监护金比我想象中还要昂贵。",
            ["ContentJP"] = "カロン族がこの街で不遇だとは知っていたけれど、公共施設の「後見金」が、ここまで高いなんて思わなかったわ。",
            ["DialogueId"] = 51010408,
            ["GUID"] = "7FB2FF10",
            ["NextDialogue"] = 51010409,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF10",
            },
        [51010409] = {
            ["Content"] = "虽然幸运地赶上这座城市一年一度不需要门票的狂欢日，但又不幸地听说那儿发生了械战……简直糟透了。",
            ["ContentJP"] = "それでも、年に一度の入場無料の日にうまく間に合って――と思ったら、運悪くその日に騒動が起きたの。もう、最悪だったわ。",
            ["DialogueId"] = 51010409,
            ["GUID"] = "7FB2FF3A",
            ["NextDialogue"] = 51010410,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF3A",
            },
        [51010410] = {
            ["Content"] = "不过还好——我收集了很多乐谱！书店的价格还算公道，很多人也同意让我用歌声交换乐谱，还有一位神秘的好心朋友教过我一首有名的歌！",
            ["ContentJP"] = "でもね、良いこともあったのよ。たくさんの楽譜を集められたの。本屋さんの値段は良心的だったし、歌と引き換えに譲ってくれる人もいたわ。それに、ある「親切なお方」が、有名な歌をひとつ教えてくれたの。",
            ["DialogueId"] = 51010410,
            ["GUID"] = "7FB2FF64",
            ["NextOptions"] = {
                [1] = 510104101,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF64",
            },
        [51010411] = {
            ["Content"] = "前阵子的一个晚上，我靠着一堵墙，就着月光，随意弹唱一首从淘来的乐谱里学的歌。那首歌的旋律并不复杂，很容易便能记住。",
            ["ContentJP"] = "そう、先日壁にもたれて、月明かりの下で、古本から拾った旋律を歌っていたの。簡単な曲だったわ、すぐに覚えられるほどのね。",
            ["DialogueId"] = 51010411,
            ["GUID"] = "7FB2FF8E",
            ["NextDialogue"] = 51010412,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FF8E",
            },
        [51010412] = {
            ["Content"] = "但我唱完后，墙的那边突然传来奇怪的敲击声……我能听出来，那些敲击声遵循着某种规律。你知道的，吟游诗人总是对节奏格外敏感。",
            ["ContentJP"] = "でも歌い終わった瞬間、壁の向こうから変な音がして……不思議なリズムだった。私たち吟遊詩人って、そういうのには敏感なの。",
            ["DialogueId"] = 51010412,
            ["GUID"] = "7FB2FFB8",
            ["NextDialogue"] = 51010413,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FFB8",
            },
        [51010413] = {
            ["Content"] = "我试着拆解了那些节奏。那是一种很常见的古老密码，用两种不同的敲击声就可以传递讯号。",
            ["ContentJP"] = "耳を澄ませてみたら、それは良く知られた古い暗号だったわ――二種類の音を使って、メッセージを送るの。",
            ["DialogueId"] = 51010413,
            ["GUID"] = "7FB2FFE2",
            ["NextDialogue"] = 51010414,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB2FFE2",
            },
        [51010414] = {
            ["Content"] = "墙那边的人告诉我，我唱错了。那是一首歌剧的唱段，在这儿很有名——因为没读过剧本的缘故，我未能准确理解那首歌所传递给观众的情感。",
            ["ContentJP"] = "その人はね、「君、そこちょっと違うよ」って教えてくれたの。あの歌は歌劇の中の一節で、この街ではよく知られた曲だったみたい。私が歌を正しく解釈できなかったのは……台本を読んだことがなかったから。",
            ["DialogueId"] = 51010414,
            ["GUID"] = "7FB3000C",
            ["NextDialogue"] = 51010415,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB3000C",
            },
        [51010415] = {
            ["Content"] = "他则是因为某种原因没有办法开口说话和演唱。但他可以用这种讯号教给我如何演唱。",
            ["ContentJP"] = "でもその人は、声が出せないみたいだった。言葉も、歌も。でも、音でなら伝えられる。そうやって私に、歌の解釈を一つひとつ教えてくれたの。",
            ["DialogueId"] = 51010415,
            ["GUID"] = "7FB30036",
            ["NextDialogue"] = 51010416,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30036",
            },
        [51010416] = {
            ["Content"] = "但当我终于在他的教导下学会了那首歌，跑到对面那条街打算当面道谢时，那位好心人已经不在那里了。",
            ["ContentJP"] = "私、がんばって覚えて……ようやくきちんと歌えるようになって、お礼を言いに壁の向こうまで行ったの。でも、もうそこには誰もいなかった。",
            ["DialogueId"] = 51010416,
            ["GUID"] = "7FB30060",
            ["NextOptions"] = {
                [1] = 510104161,
                [2] = 510104162,
                },
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30060",
            },
        [51010417] = {
            ["Content"] = "噢，真是太巧了！",
            ["ContentJP"] = "まあ、そんな偶然って……！",
            ["DialogueId"] = 51010417,
            ["GUID"] = "7FB3008A",
            ["NextDialogue"] = 51010418,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB3008A",
            },
        [51010418] = {
            ["Content"] = "如果方便，还请你代我向那位先生或女士致谢——还有祝福！虽然不知道他为什么无法开口，但还是祝愿他早日好起来。我能感受到，他喜欢唱歌，非常喜欢。",
            ["ContentJP"] = "もしそうなら、どうか――その方にありがとうって伝えてほしいの。そして、祝福も。どうして声が出せなかったのかはわからないけれど、あの人は、歌が……本当に好きな人だったわ。私には、それが伝わってきた。",
            ["DialogueId"] = 51010418,
            ["GUID"] = "7FB300B4",
            ["NextDialogue"] = 51010419,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB300B4",
            },
        [51010419] = {
            ["Content"] = "……好，我会的。",
            ["ContentJP"] = "……わかった、伝えるよ。",
            ["DialogueId"] = 51010419,
            ["GUID"] = "7FB300DE",
            ["NextDialogue"] = 51010421,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB300DE",
            },
        [51010420] = {
            ["Content"] = "是呢……也藏着很多故事。",
            ["ContentJP"] = "ええ……でも、それだけたくさんの物語があるということよね。",
            ["DialogueId"] = 51010420,
            ["GUID"] = "7FB30108",
            ["NextDialogue"] = 51010421,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30108",
            },
        [51010421] = {
            ["Content"] = "说来，这里的歌剧和卢卡的很不一样……",
            ["ContentJP"] = "ここのオペラって、ルッカのとはずいぶん違うのよ。",
            ["DialogueId"] = 51010421,
            ["GUID"] = "7FB30132",
            ["NextDialogue"] = 51010422,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30132",
            },
        [51010422] = {
            ["Content"] = "卢卡的歌剧是焰火，伊瑟尔的歌剧是风。",
            ["ContentJP"] = "ルッカのオペラは、花火みたいに華やか。イーザーのは、風のように軽やか。",
            ["DialogueId"] = 51010422,
            ["GUID"] = "7FB3015C",
            ["NextDialogue"] = 51010423,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB3015C",
            },
        [51010423] = {
            ["Content"] = "而这里的歌剧是大地。广阔的，苦痛的大地……",
            ["ContentJP"] = "でもここのは……大地。広くて、苦しみをたたえた、大地の歌よ。",
            ["DialogueId"] = 51010423,
            ["GUID"] = "7FB30186",
            ["NextDialogue"] = 51010424,
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30186",
            },
        [51010424] = {
            ["Content"] = "我和朋友就快要离开这儿了，在那之前，我还想为这里写一首歌。",
            ["ContentJP"] = "私、もうすぐこの街を離れるわ。でもその前に……この地のための一曲を、書き残したい。",
            ["DialogueId"] = 51010424,
            ["GUID"] = "7FB301B0",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB301B0",
            },
        [51010425] = {
            ["Content"] = "♪白雪是她的羊水 晨昏线是她的脐带……",
            ["ContentJP"] = "♪白雪は彼女の温室　朝と夜の堺は命綱……",
            ["DialogueId"] = 51010425,
            ["GUID"] = "7FB301DA",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/env/700342/7FB301DA",
            },
        [51010426] = {
            ["Content"] = "♪白雪是她的羊水 晨昏线是她的脐带\
她娩出伟大与苦难 汇入白山下的黑铁摇篮……",
            ["ContentJP"] = "♪白雪は彼女の温室　朝と夜の堺は命綱\
偉大と苦難をともに生み　白き山の麓の黒き揺り籠へと注がれん……",
            ["DialogueId"] = 51010426,
            ["GUID"] = "7FB30204",
            ["SpeakNpcId"] = 700342,
            ["VoiceName"] = "voice/$Locale$/story/1002/510104/7FB30204",
            },
        [51010501] = {
            ["Content"] = "通行证——喂，说你呢，通行证带了吗？",
            ["ContentJP"] = "通行許可証を――おい、お前だよお前。通行許可証は持っているんだろうな？",
            ["DialogueId"] = 51010501,
            ["GUID"] = "7FB30E52",
            ["NextOptions"] = {
                [1] = 51010502,
                [2] = 51010504,
                [3] = 51010506,
                },
            ["SpeakNpcId"] = 700111,
            },
        [51010502] = {
            ["Content"] = "（声泪俱下地哭诉你是一个遵纪守法的人，只是碰巧又忘带通行证了。）",
            ["ContentJP"] = "（声を震わせ涙ながらに、自分は法を守る人間で、ただたまたま通行証をまた忘れただけだと訴える。）",
            ["DialogueId"] = 51010502,
            ["GUID"] = "7FB30E7C",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51010503,
            },
        [51010503] = {
            ["Content"] = "算了吧，你这话听得我耳朵都快起茧子了。去去，快过去，别搞得那么显眼。",
            ["ContentJP"] = "もういい、その話は耳にタコだ。さっさと通れ。目立つ真似はするな。",
            ["DialogueId"] = 51010503,
            ["GUID"] = "7FB30EA6",
            ["NextDialogue"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010504] = {
            ["Content"] = "（掏出卡米拉帮忙伪造的通行证。）",
            ["ContentJP"] = "（カミラに手伝ってもらって偽造した通行許可証を取り出す。）",
            ["DialogueId"] = 51010504,
            ["GUID"] = "7FB30ED0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51010505,
            },
        [51010505] = {
            ["Content"] = "通行证核验无误，准许放行。",
            ["ContentJP"] = "通行許可証に問題なし、通行を許可する。",
            ["DialogueId"] = 51010505,
            ["GUID"] = "7FB30EFA",
            ["NextDialogue"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010506] = {
            ["Content"] = "凯文先生，你也不想你在泪湖边上那件事被上级知……",
            ["ContentJP"] = "ケビンさん、あなたもダクリ湖でのあの件が上に知られたくは……",
            ["DialogueId"] = 51010506,
            ["GUID"] = "7FB30F24",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51010507,
            },
        [51010507] = {
            ["Content"] = "别念了！！！让你过还不行吗！！",
            ["ContentJP"] = "もう言うな！！！通せばいいんだろ！！",
            ["DialogueId"] = 51010507,
            ["GUID"] = "7FB30F4E",
            ["NextDialogue"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010508] = {
            ["Content"] = "难得今天没出什么事……",
            ["ContentJP"] = "今日は珍しく何も起きてねぇのに…",
            ["DialogueId"] = 51010508,
            ["GUID"] = "7FB30F78",
            ["NextOptions"] = {
                [1] = 51010509,
                },
            ["RestartTag"] = 51010508,
            ["SpeakNpcId"] = 700111,
            },
        [51010509] = {
            ["Content"] = "（按理说只要有人说出这种话，就会有意外发生。）",
            ["ContentJP"] = "（普通こういうことを口にした途端に何かしらのトラブルが起きるものだ。）",
            ["DialogueId"] = 51010509,
            ["FailDialogue"] = 51010510,
            ["GUID"] = "7FB30FA2",
            ["ImprCheckId"] = 1074,
            ["NextDialogue"] = 51010511,
            },
        [51010510] = {
            ["Content"] = "（预期的突发情况并未发生，与凯文简单寒暄几句后，大家就各自回到了工作岗位。）",
            ["ContentJP"] = "（予想された突発事件は起こらず、ケビンと軽く挨拶を交わした後、それぞれが自分の持ち場へ戻った。）",
            ["DialogueId"] = 51010510,
            ["GUID"] = "7FB30FCC",
            },
        [51010511] = {
            ["Content"] = "（大门旁突然响起急促的电话铃声，凯文如同受惊的兔子一般跳起，急匆匆地接起电话。）",
            ["ContentJP"] = "（正門のそばで突然電話のベルが鳴り、ケビンは飛び上がるようにびっくりして、慌てて電話を取った。）",
            ["DialogueId"] = 51010511,
            ["GUID"] = "7FB30FF6",
            ["NextDialogue"] = 51010512,
            },
        [51010512] = {
            ["Content"] = "好，好……是！我明白了！",
            ["ContentJP"] = "は、はいっ！……わかりました！",
            ["DialogueId"] = 51010512,
            ["GUID"] = "7FB31020",
            ["NextDialogue"] = 51010513,
            ["SpeakNpcId"] = 700111,
            },
        [51010513] = {
            ["Content"] = "（简短的交谈过后，凯文放下电话，对大门方向比了个通过的手势。）",
            ["ContentJP"] = "（短いやり取りの後、ケビンは受話器を置き、門の方に通行のジェスチャーをした。）",
            ["DialogueId"] = 51010513,
            ["GUID"] = "7FB3104A",
            ["NextDialogue"] = 51010514,
            },
        [51010514] = {
            ["Content"] = "没事的话就赶紧回去吧，我今天又没法安稳下班了。",
            ["ContentJP"] = "用がないならとっとと戻れ。今日もまた定時で上がれそうにねぇ。",
            ["DialogueId"] = 51010514,
            ["GUID"] = "7FB31074",
            ["NextDialogue"] = 51010515,
            ["SpeakNpcId"] = 700111,
            },
        [51010515] = {
            ["Content"] = "唉……怎么一遇到你就出意外……",
            ["ContentJP"] = "はあ……どうしてお前に会うと必ず何か起きるんだ……",
            ["DialogueId"] = 51010515,
            ["GUID"] = "7FB3109E",
            ["SpeakNpcId"] = 700111,
            },
        [51010516] = {
            ["Content"] = "喂！通行证……啊，是你啊，过去吧过去吧。",
            ["ContentJP"] = "通行許可証を……なんだお前か、さっさと通れ。",
            ["DialogueId"] = 51010516,
            ["GUID"] = "7FB310C8",
            ["SpeakNpcId"] = 700111,
            },
        [51010601] = {
            ["Content"] = "好心人，求你帮帮我……给多少都可以……救救身无分文的老人家吧……",
            ["ContentJP"] = "優しい人よ、どうか助けてくれ……いくらでもいい……無一文のこの年寄りを救っておくれ……",
            ["DialogueId"] = 51010601,
            ["GUID"] = "7FB31EBA",
            ["NextDialogue"] = 51010602,
            ["SpeakNpcId"] = 700338,
            },
        [51010602] = {
            ["Content"] = "（面前的老人白发苍苍，满面风霜。他呆滞的目光扫过冰湖城来来往往的行人，用嘶哑的声音请求怜悯。）",
            ["ContentJP"] = "（目の前の老人は白髪で、長年の苦労が顔に深く刻まれている。彼はぼんやりした視線でアイスレイク城を行き交う人々を見やり、かすれた声で哀れみを乞う。）",
            ["DialogueId"] = 51010602,
            ["GUID"] = "7FB31EE4",
            ["NextOptions"] = {
                [1] = 51010603,
                [2] = 51010606,
                [3] = 51010610,
                },
            },
        [51010603] = {
            ["Content"] = "（这个老人真可怜，给他一些钱。）",
            ["ContentJP"] = "（この老人は本当にかわいそう。少しお金を渡そう。）",
            ["DialogueId"] = 51010603,
            ["GUID"] = "7FB31F0E",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51010604,
            },
        [51010604] = {
            ["Content"] = "唉，谢谢你，年轻人。",
            ["ContentJP"] = "ああ、ありがとうよ、若いの。",
            ["DialogueId"] = 51010604,
            ["GUID"] = "7FB31F38",
            ["NextDialogue"] = 51010605,
            ["SpeakNpcId"] = 700338,
            },
        [51010605] = {
            ["Content"] = "也不知道我这老头子今天睡着明天还能不能醒过来，但至少，今天能吃顿饱饭了。",
            ["ContentJP"] = "今日眠って、明日目を覚ませるかどうかもわからんが、せめて今日は腹いっぱい食えそうだ。",
            ["DialogueId"] = 51010605,
            ["GUID"] = "7FB31F62",
            ["SpeakNpcId"] = 700338,
            },
        [51010606] = {
            ["Content"] = "（从老人的破碗里拿走几枚硬币。）",
            ["ContentJP"] = "（老人の割れた茶碗から数枚の硬貨を取り上げる。）",
            ["DialogueId"] = 51010606,
            ["GUID"] = "7FB31F8C",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51010607,
            },
        [51010607] = {
            ["Content"] = "你……唉。",
            ["ContentJP"] = "{性别:お兄さん|お嬢さん}……はあ。",
            ["DialogueId"] = 51010607,
            ["GUID"] = "7FB31FB6",
            ["NextDialogue"] = 51010608,
            ["SpeakNpcId"] = 700338,
            },
        [51010608] = {
            ["Content"] = "{性别：小伙子|小姑娘}你这眼睛，莫非也是让他们打的？",
            ["ContentJP"] = "{性别:お兄さん|お嬢さん}、その目、まさかあいつらにやられたのかい？",
            ["DialogueId"] = 51010608,
            ["GUID"] = "7FB31FE0",
            ["NextDialogue"] = 51010609,
            ["SpeakNpcId"] = 700338,
            },
        [51010609] = {
            ["Content"] = "算了，拿去吧，拿去吧，你可能比我更需要这些钱。",
            ["ContentJP"] = "まあいい、持っておいき。お前さんの方が、わしよりそれを必要としてるのかもしれん。",
            ["DialogueId"] = 51010609,
            ["GUID"] = "7FB3200A",
            ["SpeakNpcId"] = 700338,
            },
        [51010610] = {
            ["Content"] = "身体健全的你应该去工作。",
            ["ContentJP"] = "体が健全なら仕事を探すべきだ。",
            ["DialogueId"] = 51010610,
            ["GUID"] = "7FB32034",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51010611,
            },
        [51010611] = {
            ["Content"] = "工作……哈。谁还没有过一份体面的工作……",
            ["ContentJP"] = "仕事、か……。誰だって、昔はちゃんとした仕事のひとつやふたつは持ってたさ……。",
            ["DialogueId"] = 51010611,
            ["GUID"] = "7FB3205E",
            ["NextDialogue"] = 51010612,
            ["SpeakNpcId"] = 700338,
            },
        [51010612] = {
            ["Content"] = "可那又有什么用？有时候啊，他们夺走你的工作，就和夺走这破碗中的硬币一样简单。",
            ["ContentJP"] = "だが、それが何になる？あいつらはな、ときにはお前の仕事を平気で奪うんだよ、この割れた茶碗の中の硬貨を奪うのと同じくらい、たやすくな。",
            ["DialogueId"] = 51010612,
            ["GUID"] = "7FB32088",
            ["NextDialogue"] = 51010613,
            ["SpeakNpcId"] = 700338,
            },
        [51010613] = {
            ["Content"] = "在漂亮屋子里乞讨，在大街上乞讨，都一样的。",
            ["ContentJP"] = "綺麗な家で物乞いをしようが、大通りで物乞いをしようが、同じことさ。",
            ["DialogueId"] = 51010613,
            ["GUID"] = "7FB320B2",
            ["SpeakNpcId"] = 700338,
            },
        [51010614] = {
            ["Content"] = "好好活着吧……唉，这世道，越是好人越难立足啊。",
            ["ContentJP"] = "しっかり生きるんだよ……この世はな、善い人間ほど身の置きどころがないもんだ。",
            ["DialogueId"] = 51010614,
            ["GUID"] = "7FB320DC",
            ["SpeakNpcId"] = 700338,
            },
        [51010701] = {
            ["Content"] = "末日将至啊……末日将至……",
            ["ContentJP"] = "終末が来る……終末が来る……",
            ["DialogueId"] = 51010701,
            ["GUID"] = "7FB32F22",
            ["NextDialogue"] = 51010702,
            ["SpeakNpcId"] = 700337,
            },
        [51010702] = {
            ["Content"] = "（眼前的皎皎摇头晃脑地趴在桌子上，昏昏欲睡。）",
            ["ContentJP"] = "（目の前のルーナ族は机にうつ伏せ、頭をふらふらさせて今にも眠りに落ちそうだ。）",
            ["DialogueId"] = 51010702,
            ["GUID"] = "7FB32F4C",
            ["NextOptions"] = {
                [1] = 51010703,
                [2] = 51010704,
                },
            },
        [51010703] = {
            ["Content"] = "把她叫醒。",
            ["ContentJP"] = "彼女を起こす。",
            ["DialogueId"] = 51010703,
            ["GUID"] = "7FB32F76",
            ["NextDialogue"] = 51010705,
            },
        [51010704] = {
            ["Content"] = "让她继续睡。",
            ["ContentJP"] = "そのまま寝かせておく。",
            ["DialogueId"] = 51010704,
            ["GUID"] = "7FB32FA0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51010705] = {
            ["Content"] = "（悲观皎皎猛地抬起头，眼神闪闪发光，声音如洪水一般宣泄出来。）",
            ["ContentJP"] = "（ネガティブなルーナ族が勢いよく頭を上げ、目をきらきら輝かせ、声が洪水のようにあふれ出す。）",
            ["DialogueId"] = 51010705,
            ["GUID"] = "7FB32FCA",
            ["NextDialogue"] = 51010706,
            },
        [51010706] = {
            ["Content"] = "末日……末日要来了，没人能够逃掉。",
            ["ContentJP"] = "終末……終末が来る、誰も逃れられない。",
            ["DialogueId"] = 51010706,
            ["GUID"] = "7FB32FF4",
            ["NextDialogue"] = 51010707,
            ["SpeakNpcId"] = 700337,
            },
        [51010707] = {
            ["Content"] = "花店里的花朵不再鲜艳，褪色成纯白的石楠……",
            ["ContentJP"] = "花屋の花はもう鮮やかでなく、色あせて真っ白なシャクナゲになる……",
            ["DialogueId"] = 51010707,
            ["GUID"] = "7FB3301E",
            ["NextDialogue"] = 51010708,
            ["SpeakNpcId"] = 700337,
            },
        [51010708] = {
            ["Content"] = "广场上的猫猫不再毛绒绒，而是像石膏雕像一样又硬又滑……",
            ["ContentJP"] = "広場の猫たちもモフモフじゃなくなって、石膏像みたいに硬くてつるつるに……",
            ["DialogueId"] = 51010708,
            ["GUID"] = "7FB33048",
            ["NextDialogue"] = 51010709,
            ["SpeakNpcId"] = 700337,
            },
        [51010709] = {
            ["Content"] = "面包房再也做不出蓬松的面包，无论怎么烘焙都会变成黑漆漆的烂泥……",
            ["ContentJP"] = "パン屋はもうふわふわのパンを焼けなくなり、どう焼いても真っ黒などろどろになる……",
            ["DialogueId"] = 51010709,
            ["GUID"] = "7FB33072",
            ["NextDialogue"] = 51010710,
            ["SpeakNpcId"] = 700337,
            },
        [51010710] = {
            ["Content"] = "我最爱吃的冰棍也不再冰冰凉凉，放到嘴里只会黏糊糊粘住嗓子……",
            ["ContentJP"] = "私の大好物のアイスもひんやりしなくなって、口に入れるとねばねばして喉にくっつくだけに……",
            ["DialogueId"] = 51010710,
            ["GUID"] = "7FB3309C",
            ["NextDialogue"] = 51010711,
            ["SpeakNpcId"] = 700337,
            },
        [51010711] = {
            ["Content"] = "大家也开始慢慢变得和皎皎一样高，和皎皎一样白……",
            ["ContentJP"] = "みんなもだんだんルーナ族と同じくらいの背になって、ルーナ族みたいに白くなっていく……",
            ["DialogueId"] = 51010711,
            ["GUID"] = "7FB330C6",
            ["NextDialogue"] = 51010712,
            ["SpeakNpcId"] = 700337,
            },
        [51010712] = {
            ["Content"] = "到最后……",
            ["ContentJP"] = "最後には……",
            ["DialogueId"] = 51010712,
            ["GUID"] = "7FB330F0",
            ["NextDialogue"] = 51010713,
            ["SpeakNpcId"] = 700337,
            },
        [51010713] = {
            ["Content"] = "花店的阿姨，面包房的大婶，卖冰棍的爷爷……大家都会变成皎皎！",
            ["ContentJP"] = "花屋のおばさん、パン屋のおばちゃん、アイス売りのおじいさん……みんながルーナ族になる！",
            ["DialogueId"] = 51010713,
            ["GUID"] = "7FB3311A",
            ["NextOptions"] = {
                [1] = 51010714,
                [2] = 51010715,
                },
            ["SpeakNpcId"] = 700337,
            },
        [51010714] = {
            ["Content"] = "皎皎好，我也想变成皎皎。",
            ["ContentJP"] = "ルーナ族はいいよね、私もルーナ族になりたい。",
            ["DialogueId"] = 51010714,
            ["GUID"] = "7FB33144",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51010716,
            },
        [51010715] = {
            ["Content"] = "好可怕的末日……",
            ["ContentJP"] = "なんて恐ろしい終末……",
            ["DialogueId"] = 51010715,
            ["GUID"] = "7FB3316E",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51010716,
            },
        [51010716] = {
            ["Content"] = "你……你的头发、你的衣服、你的身高……你已经开始变成皎皎了吗！",
            ["ContentJP"] = "あなた……あなたの髪、あなたの服、あなたの身長……もうルーナ族になり始めてるの！",
            ["DialogueId"] = 51010716,
            ["GUID"] = "7FB33198",
            ["NextDialogue"] = 51010717,
            ["SpeakNpcId"] = 700337,
            },
        [51010717] = {
            ["Content"] = "末日……末日果然来了，一切都完了。",
            ["ContentJP"] = "終末……やっぱり来た、もうすべて終わりだ。",
            ["DialogueId"] = 51010717,
            ["GUID"] = "7FB331C2",
            ["NextDialogue"] = 51010718,
            ["SpeakNpcId"] = 700337,
            },
        [51010718] = {
            ["Content"] = "（悲观皎皎无力地垂下双手，看向你的视线透过你的身躯，透过层叠的建筑，失神地望向昏暗的天空。仿佛她口中的末日马上就要变为现实。）",
            ["ContentJP"] = "（ネガティブなルーナ族は力なく両手を垂らし、あなたを見る視線はあなたの体を通り抜け、幾重にも重なる建物を突き抜けて、茫然と暗い空を見上げる。まるで彼女の言う終末が今にも現実になりそうな様子だ。）",
            ["DialogueId"] = 51010718,
            ["GUID"] = "7FB331EC",
            ["NextDialogue"] = 51010719,
            },
        [51010719] = {
            ["Content"] = "（几分钟过去，理所当然的什么都未发生，悲观皎皎的视线再也没有落到你的身上，不断呢喃着末日将至。）",
            ["ContentJP"] = "（数分過ぎたが当然ながら何も起きず、ネガティブなルーナ族の視線は二度とあなたに戻ることはなく、「終末が来る」とぶつぶつ呟き続ける。）",
            ["DialogueId"] = 51010719,
            ["GUID"] = "7FB33216",
            ["NextDialogue"] = 51010720,
            },
        [51010720] = {
            ["Content"] = "（你有些好奇变成皎皎会是怎么样的感觉，但现在你能做的，也只有转身离开了。）",
            ["ContentJP"] = "（あなたはルーナ族になるとはどんな気分なのか少し気になったが、今できるのは背を向けて立ち去ることだけだった。）",
            ["DialogueId"] = 51010720,
            ["GUID"] = "7FB33240",
            },
        [51010721] = {
            ["Content"] = "末日，末日已经开始了……",
            ["ContentJP"] = "終末、終末はもう始まっている……",
            ["DialogueId"] = 51010721,
            ["GUID"] = "7FB3326A",
            ["SpeakNpcId"] = 700337,
            },
        [51010801] = {
            ["Content"] = "您好，这朵花与您今天的装扮很相称……如果那孩子还在的话，一定也会这么说吧。",
            ["ContentJP"] = "いらっしゃいませ。お客様の服装にあわせるなら、今日はこちらのお花がぴったりですよ......あの子がいたら、きっとこう言うはずです。",
            ["DialogueId"] = 51010801,
            ["GUID"] = "7FB33F8A",
            ["NextOptions"] = {
                [1] = 51010802,
                [2] = 51010803,
                },
            ["SpeakNpcId"] = 700203,
            },
        [51010802] = {
            ["Content"] = "你认识我？",
            ["ContentJP"] = "私のことを知っているのですか？",
            ["DialogueId"] = 51010802,
            ["GUID"] = "7FB33FB4",
            ["NextDialogue"] = 51010804,
            },
        [51010803] = {
            ["Content"] = "“那孩子”难道指的是……",
            ["ContentJP"] = "「その子」って、もしかして……",
            ["DialogueId"] = 51010803,
            ["GUID"] = "7FB33FDE",
            ["NextDialogue"] = 51010804,
            },
        [51010804] = {
            ["Content"] = "我的女儿。她的名字是赛琪。",
            ["ContentJP"] = "私の娘です。名前はサイキ。",
            ["DialogueId"] = 51010804,
            ["GUID"] = "7FB34008",
            ["NextDialogue"] = 51010805,
            ["SpeakNpcId"] = 700203,
            },
        [51010805] = {
            ["Content"] = "她曾在给我的信里提到过“一个新交的朋友”。您的模样与那封书信中的描述很相似……如果我认错了人，还请您谅解。",
            ["ContentJP"] = "娘は私への手紙で「新しくできた友達」について触れていました。あなたの様子がその手紙の描写によく似ていて……人違いならどうかお許しください。",
            ["DialogueId"] = 51010805,
            ["GUID"] = "7FB34032",
            ["NextOptions"] = {
                [1] = 51010806,
                [2] = 51010807,
                },
            ["SpeakNpcId"] = 700203,
            ["bForbidSkipOptions"] = true,
            },
        [51010806] = {
            ["Content"] = "……她是怎么说我的？",
            ["ContentJP"] = "……彼女は私のことをどう言っていましたか？",
            ["DialogueId"] = 51010806,
            ["GUID"] = "7FB3405C",
            ["NextDialogue"] = 51010809,
            },
        [51010807] = {
            ["Content"] = "……是的，你认错人了。（离开）",
            ["ContentJP"] = "……ええ、人違いです。",
            ["DialogueId"] = 51010807,
            ["GUID"] = "7FB34086",
            ["NextDialogue"] = 51010808,
            },
        [51010808] = {
            ["Content"] = "（你像逃跑一样转身离开。那是你们心中共同的隐痛，你不愿再触及它。）",
            ["ContentJP"] = "（あなたは逃げ出すように背を向けて去る。それはあなたたちの共通する痛みで、あなたはもう触れたくなかった。）",
            ["DialogueId"] = 51010808,
            ["GUID"] = "7FB340B0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [51010809] = {
            ["Content"] = "你很聪明，又很勇敢。听说你到冰湖城的第一天就深入格雷姆废矿，在她见过的所有同龄人里，你是最强大的一个。更重要的是……",
            ["ContentJP"] = "あなたは賢くて、とても勇敢だと。アイスレイク城に来た初日にグルビューム廃坑の奥まで入ったと聞いたわ。彼女が見てきた同世代の中で、あなたは最も強かった。もっと大事なのは……",
            ["DialogueId"] = 51010809,
            ["GUID"] = "7FB340DA",
            ["NextDialogue"] = 51010810,
            ["SpeakNpcId"] = 700203,
            },
        [51010810] = {
            ["Content"] = "“{性别：他|她}和冰湖城的大多数人不一样，{性别：他|她}还有着我们早就丢失了的东西——对正义和自由的渴望。”",
            ["ContentJP"] = "「{性别:彼|彼女}はアイスレイク城の大多数の人とは違う。{性别:彼|彼女}には、私たちがとうに失ってしまったもの――正義と自由への渇望がまだある。」",
            ["DialogueId"] = 51010810,
            ["GUID"] = "7FB34104",
            ["NextDialogue"] = 51010811,
            ["SpeakNpcId"] = 700203,
            },
        [51010811] = {
            ["Content"] = "“从{性别：他|她}身上，我看到了另一种不一样的生活。”",
            ["ContentJP"] = "「{性别:彼|彼女}の姿に、私は別の生き方を見たの。」",
            ["DialogueId"] = 51010811,
            ["GUID"] = "7FB3412E",
            ["NextDialogue"] = 51010812,
            ["SpeakNpcId"] = 700203,
            },
        [51010812] = {
            ["Content"] = "这是她信里写的。",
            ["ContentJP"] = "これは彼女の手紙に書かれていたことです。",
            ["DialogueId"] = 51010812,
            ["GUID"] = "7FB34158",
            ["NextDialogue"] = 51010813,
            ["SpeakNpcId"] = 700203,
            },
        [51010813] = {
            ["Content"] = "（女人熟练地复述着——显然，那封信她不知看了多少遍。）",
            ["ContentJP"] = "（女の人は淀みなく話した――明らかに、その手紙を何度も読み返している。）",
            ["DialogueId"] = 51010813,
            ["GUID"] = "7FB34182",
            ["NextDialogue"] = 51010814,
            },
        [51010814] = {
            ["Content"] = "对不起，我没能……",
            ["ContentJP"] = "ごめんなさい、私は……",
            ["DialogueId"] = 51010814,
            ["GUID"] = "7FB341AC",
            ["NextDialogue"] = 51010815,
            ["SpeakNpcId"] = 100001,
            },
        [51010815] = {
            ["Content"] = "不要说抱歉，孩子。我看得到，有你最后的陪伴，她是快乐的。这就够了。是我们应该感谢你。",
            ["ContentJP"] = "謝らなくていいのよ。最後にあなたがそばにいてくれて、彼女は幸せだったのが私には分かる。それで十分、感謝すべきは私たちの方よ。",
            ["DialogueId"] = 51010815,
            ["GUID"] = "7FB341D6",
            ["NextDialogue"] = 51010816,
            ["SpeakNpcId"] = 700203,
            },
        [51010816] = {
            ["Content"] = "请带上这束花吧，我们的祝福与你同在。",
            ["ContentJP"] = "この花束を持っていって。私たちの祝福はいつもあなたと共にあるわ。",
            ["DialogueId"] = 51010816,
            ["GUID"] = "7FB34200",
            ["SpeakNpcId"] = 700203,
            },
        [51010817] = {
            ["Content"] = "一路顺利，我们的祝福与你同在。",
            ["ContentJP"] = "道中お気をつけて。私たちの祝福はあなたと共に。",
            ["DialogueId"] = 51010817,
            ["GUID"] = "7FB3422A",
            ["SpeakNpcId"] = 700203,
            },
        [51010901] = {
            ["Content"] = "自家庄园的好果子，别的地方没有这培育技术！",
            ["ContentJP"] = "自家農園の最高フルーツ！よそにはまねできない栽培技術で育てた一級品だ！",
            ["DialogueId"] = 51010901,
            ["GUID"] = "7FB34FF2",
            ["NextDialogue"] = 51010902,
            ["SpeakNpcId"] = 700009,
            },
        [51010902] = {
            ["Content"] = "您来点果子吗？一等一的肥料加上好种子，自家温室培养出来的，个个营养丰富口感好！",
            ["ContentJP"] = "果物どうだい？特等の肥料に良い種、うちの温室育ちだ。どれも栄養満点、味は保証するぜ！",
            ["DialogueId"] = 51010902,
            ["GUID"] = "7FB3501C",
            ["NextOptions"] = {
                [1] = 51010903,
                [2] = 51010905,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010903] = {
            ["Content"] = "温室培育的果子应该很贵吧。",
            ["ContentJP"] = "温室栽培の果物は高いんでしょう。",
            ["DialogueId"] = 51010903,
            ["GUID"] = "7FB35046",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51010904,
            },
        [51010904] = {
            ["Content"] = "果子不同价格也不同，能吃到好果子本身就很难了，我之前在战场上根本吃不到。",
            ["ContentJP"] = "果物の値段はまちまちだ。そもそも旨い果物にありつくのが難しいんだ。俺なんざ前は戦場にいて、まるで口にできなかったからな。",
            ["DialogueId"] = 51010904,
            ["GUID"] = "7FB35070",
            ["NextOptions"] = {
                [1] = 51010907,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010905] = {
            ["Content"] = "掌握温室培育的技术应该很难。",
            ["ContentJP"] = "温室栽培の技術を身につけるのは難しそうですね。",
            ["DialogueId"] = 51010905,
            ["GUID"] = "7FB3509A",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51010906,
            },
        [51010906] = {
            ["Content"] = "技术是我爷爷传下来的，我一开始还不想继承，后来退伍了才接受。",
            ["ContentJP"] = "技はじいさん直伝だ。当初は継ぐ気なんてなかったが、除隊してから受け継いだんだ。",
            ["DialogueId"] = 51010906,
            ["GUID"] = "7FB350C4",
            ["NextOptions"] = {
                [1] = 51010907,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010907] = {
            ["Content"] = "您当过兵？",
            ["ContentJP"] = "軍隊にいたんですか？",
            ["DialogueId"] = 51010907,
            ["GUID"] = "7FB350EE",
            ["NextDialogue"] = 51010908,
            },
        [51010908] = {
            ["Content"] = "是啊，我当初可是优秀士兵，一个顶三个！",
            ["ContentJP"] = "ああ、当時の俺は腕利きの兵隊でね、一人で三人分は働いたもんだ！",
            ["DialogueId"] = 51010908,
            ["GUID"] = "7FB35118",
            ["NextDialogue"] = 51010909,
            ["SpeakNpcId"] = 700009,
            },
        [51010909] = {
            ["Content"] = "后来受伤了，越来越力不从心，就提前退伍了。",
            ["ContentJP"] = "そのあと怪我してな、だんだん無理が利かなくなって、少し早めに除隊したのさ。",
            ["DialogueId"] = 51010909,
            ["GUID"] = "7FB35142",
            ["NextDialogue"] = 51010910,
            ["SpeakNpcId"] = 700009,
            },
        [51010910] = {
            ["Content"] = "现在才明白平平淡淡才是真，踏踏实实培育果子，再遇到个好姑娘，一辈子挺好的了。",
            ["ContentJP"] = "今じゃ分かった。派手さより平穏よ。地道に果物を育てて、いい子に出会えりゃ、それで上等だ。",
            ["DialogueId"] = 51010910,
            ["GUID"] = "7FB3516C",
            ["NextOptions"] = {
                [1] = 51010911,
                },
            ["RestartTag"] = 51010910,
            ["SpeakNpcId"] = 700009,
            },
        [51010911] = {
            ["Content"] = "有心仪的人选吗？",
            ["ContentJP"] = "気になる人はいるんですか？",
            ["DialogueId"] = 51010911,
            ["FailDialogue"] = 51010912,
            ["GUID"] = "7FB35196",
            ["ImprCheckId"] = 1075,
            ["NextDialogue"] = 51010914,
            },
        [51010912] = {
            ["Content"] = "（男人一时语塞，尴尬地张了张嘴，艰难地挤出一句话。）",
            ["ContentJP"] = "（男は一瞬言葉が詰まり、気まずそうに口をぱくぱくさせて、やっとのことで一言しぼり出す。）",
            ["DialogueId"] = 51010912,
            ["GUID"] = "7FB351C0",
            ["NextDialogue"] = 51010913,
            },
        [51010913] = {
            ["Content"] = "您，您别问了，您还是多看看果子，我帮您挑挑。",
            ["ContentJP"] = "い、いやその話は勘弁してくれ。ほら、果物をもっと見てってくれ、俺がいいのを選んでやる。",
            ["DialogueId"] = 51010913,
            ["GUID"] = "7FB351EA",
            ["SpeakNpcId"] = 700009,
            },
        [51010914] = {
            ["Content"] = "（男人的眼睛闪过一丝亮光，不自觉地微笑了起来，但瞬间又陷入了困惑。）",
            ["ContentJP"] = "（男の目が一瞬きらりと光り、思わず笑みがこぼれるが、すぐに困惑の色に沈む。）",
            ["DialogueId"] = 51010914,
            ["GUID"] = "7FB35214",
            ["NextDialogue"] = 51010915,
            },
        [51010915] = {
            ["Content"] = "……虽然有，但我只见过她的背影。",
            ["ContentJP"] = "……いるにはいるが、背中しか見ちゃいない。",
            ["DialogueId"] = 51010915,
            ["GUID"] = "7FB3523E",
            ["NextDialogue"] = 51010916,
            ["SpeakNpcId"] = 700009,
            },
        [51010916] = {
            ["Content"] = "这么久了，我还没和她说过话呢，唉。",
            ["ContentJP"] = "こんなに時間がたっても、まだ声をかけられてなくてな、はあ。",
            ["DialogueId"] = 51010916,
            ["GUID"] = "7FB35268",
            ["NextDialogue"] = 51010917,
            ["SpeakNpcId"] = 700009,
            },
        [51010917] = {
            ["Content"] = "贸然搭话又怕吓到心爱的姑娘，我只好先让空空皎皎帮我传下话。唉，可我真是太倒霉了，每次空空皎皎去传话的时候，都赶上她不在家。",
            ["ContentJP"] = "いきなり声をかけて気になる子を驚かせるのも怖くてよ、まずはルーナ族のボケボケ丸に言付けを頼んだんだ。だが俺はつくづく運がない。ボケボケ丸が行くたび、彼女は留守でよ。",
            ["DialogueId"] = 51010917,
            ["GUID"] = "7FB35292",
            ["NextOptions"] = {
                [1] = 51010918,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010918] = {
            ["Content"] = "你看上去不拘小节，却很懂得尊重对方。",
            ["ContentJP"] = "大ざっぱに見えて、相手への敬意はちゃんとあるんですね。",
            ["DialogueId"] = 51010918,
            ["GUID"] = "7FB352BC",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51010919,
            },
        [51010919] = {
            ["Content"] = "您夸得我都不好意思了，哈哈。",
            ["ContentJP"] = "へへ、そんなふうに言われるとこそばゆいねぇ、はは。",
            ["DialogueId"] = 51010919,
            ["GUID"] = "7FB352E6",
            ["NextDialogue"] = 51010920,
            ["SpeakNpcId"] = 700009,
            },
        [51010920] = {
            ["Content"] = "对了，我看您像是个文化人，可不可以帮我这个粗人润色一下句子，我怎么写怎么别扭。",
            ["ContentJP"] = "ところであんた、学のある人に見えるな。この粗っぽい文章をちょいと手直ししてくれないか。どう書いても納得いかなくてよ。",
            ["DialogueId"] = 51010920,
            ["GUID"] = "7FB35310",
            ["NextOptions"] = {
                [1] = 51010921,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010921] = {
            ["Content"] = "我现在正好有时间，你读来听听？",
            ["ContentJP"] = "今ちょうど時間があるので、読み上げてみて。",
            ["DialogueId"] = 51010921,
            ["GUID"] = "7FB3533A",
            ["NextDialogue"] = 51010922,
            },
        [51010922] = {
            ["Content"] = "咳咳。",
            ["ContentJP"] = "コホン。",
            ["DialogueId"] = 51010922,
            ["GUID"] = "7FB35364",
            ["NextDialogue"] = 51010923,
            ["SpeakNpcId"] = 700009,
            },
        [51010923] = {
            ["Content"] = "“我对你的感情，一直升温，比冬天的温室，还要温暖。”",
            ["ContentJP"] = "「あんたへの気持ちは、ずっと上がりっぱなしで、冬の温室よりあったかいんだ。」",
            ["DialogueId"] = 51010923,
            ["GUID"] = "7FB3538E",
            ["NextOptions"] = {
                [1] = 51010924,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010924] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51010924,
            ["GUID"] = "7FB353B8",
            ["NextDialogue"] = 51010925,
            },
        [51010925] = {
            ["Content"] = "“你什么时候能发现，我的心像果子，就等着你来采摘。”",
            ["ContentJP"] = "「いつ気づいてくれる？俺の心は果物みたいに、あんたに摘んでもらえるのを待ってる。」",
            ["DialogueId"] = 51010925,
            ["GUID"] = "7FB353E2",
            ["NextDialogue"] = 51010926,
            ["SpeakNpcId"] = 700009,
            },
        [51010926] = {
            ["Content"] = "“接受我吧，我的姑娘！不要让我的爱像烂果子一样，烂在地里。”",
            ["ContentJP"] = "「受け取ってくれ、俺のお嬢さん！俺の愛を、腐った果物みたいに地べたで腐らせないでくれ。」",
            ["DialogueId"] = 51010926,
            ["GUID"] = "7FB3540C",
            ["NextDialogue"] = 51010927,
            ["SpeakNpcId"] = 700009,
            },
        [51010927] = {
            ["Content"] = "……怎么样，有可以润色的地方吗？",
            ["ContentJP"] = "……どうだ、手直しできそうか？",
            ["DialogueId"] = 51010927,
            ["GUID"] = "7FB35436",
            ["NextOptions"] = {
                [1] = 51010928,
                },
            ["SpeakNpcId"] = 700009,
            },
        [51010928] = {
            ["Content"] = "……很有个人特色，也很真挚，我觉得保持现状就好。",
            ["ContentJP"] = "……とても個性的で、真摯です。このままでいいと思います。",
            ["DialogueId"] = 51010928,
            ["GUID"] = "7FB35460",
            ["NextDialogue"] = 51010929,
            },
        [51010929] = {
            ["Content"] = "真的吗？那太好了，借您吉言。",
            ["ContentJP"] = "本当かい？そりゃありがてぇ。",
            ["DialogueId"] = 51010929,
            ["GUID"] = "7FB3548A",
            ["NextDialogue"] = 51010930,
            ["SpeakNpcId"] = 700009,
            },
        [51010930] = {
            ["Content"] = "如果这份感情有结果了，您来买果子我给您最大优惠，哈哈。",
            ["ContentJP"] = "この恋が実ったら、あんたが果物を買いに来たときは特大サービスしてやる、ははっ。",
            ["DialogueId"] = 51010930,
            ["GUID"] = "7FB354B4",
            ["SpeakNpcId"] = 700009,
            },
        [51010931] = {
            ["Content"] = "我的爱对方还没回应，唉，最大优惠您要等等了。",
            ["ContentJP"] = "まだ向こうから返事がなくてな、はあ、特大サービスはもうちょい先の話だ。",
            ["DialogueId"] = 51010931,
            ["GUID"] = "7FB354DE",
            ["SpeakNpcId"] = 700009,
            },
        [51011001] = {
            ["Content"] = "请留步，很抱歉突然叫住您。",
            ["ContentJP"] = "お待ちください、突然お呼び止めして申し訳ありません。",
            ["DialogueId"] = 51011001,
            ["GUID"] = "7FB3605A",
            ["NextDialogue"] = 51011002,
            ["SpeakNpcId"] = 700008,
            },
        [51011002] = {
            ["Content"] = "但若是我家衣服能拥有自己的思想，一定很盼望能够被像您一样俊美的人穿在身上。",
            ["ContentJP"] = "もしうちの服に意思があるなら、きっとあなたのように俊美な方に着ていただくことを切望するでしょう。",
            ["DialogueId"] = 51011002,
            ["GUID"] = "7FB36084",
            ["NextDialogue"] = 51011003,
            ["SpeakNpcId"] = 700008,
            },
        [51011003] = {
            ["Content"] = "如果就这么错过了您，它们一定会伤心的。",
            ["ContentJP"] = "このままあなたを逃してしまったら、きっと彼らは悲しむはずです。",
            ["DialogueId"] = 51011003,
            ["GUID"] = "7FB360AE",
            ["NextDialogue"] = 51011004,
            ["SpeakNpcId"] = 700008,
            },
        [51011004] = {
            ["Content"] = "（眼前的男人有着贵族的气质，举手投足之间尽显优雅，身躯瘦弱却又挺拔，富有亲和力的笑眼让人如沐春风。）",
            ["ContentJP"] = "（目の前の男は貴族の風格をまとい、所作の端々に優雅さがにじむ。痩せてはいるが背筋はすっと伸び、親しみやすい笑みの目は春風のように心地よい。）",
            ["DialogueId"] = 51011004,
            ["GUID"] = "7FB360D8",
            ["NextOptions"] = {
                [1] = 51011005,
                [2] = 51011006,
                },
            },
        [51011005] = {
            ["Content"] = "你这里的衣服是我能买得起的吗？",
            ["ContentJP"] = "ここの服は、私でも買える値段ですか？",
            ["DialogueId"] = 51011005,
            ["GUID"] = "7FB36102",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51011007,
            },
        [51011006] = {
            ["Content"] = "我穿麻袋都好看。",
            ["ContentJP"] = "私は麻袋でも似合うよ。",
            ["DialogueId"] = 51011006,
            ["GUID"] = "7FB3612C",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51011007,
            },
        [51011007] = {
            ["Content"] = "那是当然，您可以先看看我们的款式图册，如果看中了哪件可以试穿。",
            ["ContentJP"] = "もちろんです。まずはうちのデザイン集をご覧ください。気に入ったものがあればご試着をどうぞ。",
            ["DialogueId"] = 51011007,
            ["GUID"] = "7FB36156",
            ["NextDialogue"] = 51011008,
