            ["GUID"] = "7FB55CC8",
            ["NextDialogue"] = 51014101,
            },
        [51014101] = {
            ["Content"] = "啊，真抱歉——咦？！",
            ["DialogueId"] = 51014101,
            ["GUID"] = "7FB55CF2",
            ["NextDialogue"] = 51014102,
            ["SpeakNpcId"] = 700383,
            },
        [51014102] = {
            ["Content"] = "你怎么从这栋房子里走出来了，该不会这里其实是你家吧？",
            ["DialogueId"] = 51014102,
            ["GUID"] = "7FB55D1C",
            ["NextDialogue"] = 51014103,
            ["SpeakNpcId"] = 700383,
            },
        [51014103] = {
            ["Content"] = "确实。",
            ["DialogueId"] = 51014103,
            ["GUID"] = "7FB55D46",
            ["NextDialogue"] = 51014104,
            ["SpeakNpcId"] = 100001,
            },
        [51014104] = {
            ["Content"] = "什么！我只是随口一问，没想到这真是{性别：他|她}家……早知道就不急着订旅馆了，{性别：他|她}这么好说话，说不定会同意我在这里借宿的……呜……",
