                [1] = "700363:Shy03_End",
                },
            },
        [51102010] = {
            ["Camera"] = "375.533203,122.591797,81.722656,0.00012,-2.399288,-162.004395,35.0,468.597351,false,Manual,2.8",
            ["Content"] = "没没没，只是确信了您就是在下苦苦等候的英雄，一时有感而发。",
            ["ContentJP"] = "いやいや、これでようやく確信が持てたよ……！やっぱり君たちこそ、俺が待ち続けてた人間だ！",
            ["DialogueId"] = 51102010,
