                [3] = "700363:Shock_Start",
                },
            },
        [51102048] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "你在这里干什么？",
            ["ContentJP"] = "何をするつもり？",
            ["DialogueId"] = 51102048,
            ["GUID"] = "7FEDB9C0",
            ["NextDialogue"] = 51102049,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock_End",
                },
            },
        [51102049] = {
            ["Camera"] = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
            ["Content"] = "既然凶兽已驱，在下自然是取回应得之物。",
            ["ContentJP"] = "獣が片付いた今、宝を回収しに来たに決まってるじゃないか。",
            ["DialogueId"] = 51102049,
            ["GUID"] = "7FEDB9EA",
            ["NextDialogue"] = 51102050,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700363:Shock_End",
                },
            },
        [51102050] = {
            ["Camera"] = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
            ["Content"] = "多亏二位英雄“碰巧”来此除凶驱祸，不然在下埋在此处的积蓄怕是无法取回了。",
            ["ContentJP"] = "いやぁ、ちょうどいい具合に手間が省けたよ。ここに埋めたはいいが、掘り起こせず困ってたんだ。",
            ["DialogueId"] = 51102050,
            ["GUID"] = "7FEDBA14",
            ["NextDialogue"] = 51102051,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Confident_End",
                },
            },
        [51102051] = {
            ["Camera"] = "-113.234375,-79.991211,166.837891,0.000162,-10.798952,72.195564,35.0,148.932434,false,Manual,2.8",
            ["Content"] = "如果是这样，一开始就实话实说不就好了？",
            ["ContentJP"] = "だったら、最初からそういえばいいのに。",
            ["DialogueId"] = 51102051,
            ["GUID"] = "7FEDBA3E",
            ["NextDialogue"] = 51102052,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51102052] = {
            ["Camera"] = "534.162109,-171.324219,313.386719,0.000211,-18.79907,165.795944,35.0,672.763,false,Manual,2.8",
            ["Content"] = "此言差矣，在下若是寻求帮助，岂不是要凭空折损一笔报酬。",
            ["ContentJP"] = "それでは取り分が減ってしまうだろう？",
            ["DialogueId"] = 51102052,
            ["GUID"] = "7FEDBA68",
            ["NextDialogue"] = 51102053,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Disagree",
                },
            },
        [51102053] = {
            ["Camera"] = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
            ["Content"] = "有道理……等等，这不就是让我们打白工嘛？！",
            ["ContentJP"] = "確かに……ってちょっと！スノウたち、タダ働きってこと！？",
            ["DialogueId"] = 51102053,
            ["GUID"] = "7FEDBA92",
            ["NextDialogue"] = 51102054,
            ["SpeakNpcId"] = 700363,
            ["TalkActionId"] = {
                [1] = "700363:Angry02_Start",
                },
            },
        [51102054] = {
            ["Camera"] = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
            ["Content"] = "是又如何？这些本就是在下的财产，二位总不能在大风九章之下强取豪夺吧？",
            ["ContentJP"] = "だから何だ？元は俺の財産だ。まさか英雄サマが、横取りなんてこすい真似、しねぇよな？",
            ["DialogueId"] = 51102054,
            ["GUID"] = "7FEDBABC",
            ["NextDialogue"] = 51102055,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Angry01_Start",
                },
            },
        [51102055] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "你的财产？怕不是用你那套招摇撞骗得来的不义之财。",
            ["ContentJP"] = "あなたの財産？どうせ人を騙して巻き上げた金なんじゃない？",
            ["DialogueId"] = 51102055,
            ["GUID"] = "7FEDBAE6",
            ["NextDialogue"] = 51102056,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51102056] = {
            ["Camera"] = "-24.017578,125.793945,181.728516,0.000098,-3.3992,-116.801804,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "这位英雄可不要凭空污人清白，未来之事皆无定数，在下不过是提出一种猜测，总有人愿意花些小钱为未来的发达买单。",
            ["ContentJP"] = "おいおい、心外だな。未来なんて誰にも分からねぇ。俺はただ一つの可能性を示しただけだ。少しばかりの金で先行きを買いたいって連中は、いつだっているもんさ。",
            ["DialogueId"] = 51102056,
            ["GUID"] = "7FEDBB10",
            ["NextDialogue"] = 51102057,
            ["SpeakNpcId"] = 700322,
            },
        [51102057] = {
            ["Camera"] = "-24.017578,125.793945,181.728516,0.000098,-3.3992,-116.801804,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "至于能否兑现……就不在在下的能力范围之内了。",
            ["ContentJP"] = "それが現実になるかどうか……それは俺の力の及ぶところじゃない。",
            ["DialogueId"] = 51102057,
            ["GUID"] = "7FEDBB3A",
            ["NextDialogue"] = 51102058,
            ["SpeakNpcId"] = 700322,
            },
        [51102058] = {
            ["Camera"] = "534.162109,-171.324219,313.386719,0.000211,-18.79907,165.795944,35.0,672.763,false,Manual,2.8",
            ["Content"] = "诚然，在下的做法有些不确定性，但既然大风九章从未降下裁决，英雄又如何能称之为招摇撞骗呢？",
            ["ContentJP"] = "確かに、俺のやり方は正当ではないかもしれんな。だが大風九章が裁きを下していない以上、それを欺きと断じるのは早計ではないかね。",
            ["DialogueId"] = 51102058,
            ["GUID"] = "7FEDBB64",
            ["NextDialogue"] = 51102059,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Angry01_End",
                },
            },
        [51102059] = {
            ["Camera"] = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
            ["Content"] = "居然还一脸得意地解释起来了！这家伙惹我生气了！",
            ["ContentJP"] = "なにそれ！ドヤ顔でよくもそんなこと言えたな！ほんっとムカつく！",
            ["DialogueId"] = 51102059,
            ["FacialId"] = {
                [1] = "700363:Angry01",
                },
            ["GUID"] = "7FEDBB8E",
            ["NextDialogue"] = 51102060,
            ["SpeakNpcId"] = 700363,
            ["TalkActionId"] = {
                [1] = "700363:Angry02_End",
                },
            },
        [51102060] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51102060,
            ["GUID"] = "7FEDBBB8",
            ["NextDialogue"] = 51102061,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51102061] = {
            ["Camera"] = "-129.705078,-259.818359,233.538086,0.000134,-20.598783,73.194275,35.0,346.317627,false,Manual,2.8",
            ["Content"] = "小仆从你怎么不说话，你倒是想想办法啊。",
            ["ContentJP"] = "ちょっと下僕！？何黙ってるの！どうするの！？",
            ["DialogueId"] = 51102061,
            ["GUID"] = "7FEDBBE2",
            ["SpeakNpcId"] = 700363,
            ["TurnTo"] = {
                [1] = "700363:n(100001)",
                },
            },
        [51102062] = {
            ["Content"] = "识相点就赶紧离开吧，若是再纠缠，恐怕大风九章就要对二位出手了。",
            ["ContentJP"] = "おとなしく引き下がった方が身のためだぜ。これ以上食い下がるなら……大風九章の裁きが下るやもしれんぞ。",
            ["DialogueId"] = 51102062,
            ["GUID"] = "7FEDBC0C",
            ["SpeakNpcId"] = 700322,
            },
        [51102063] = {
            ["Content"] = "怎么还不走？赖在这干嘛？",
            ["ContentJP"] = "いつまで居座るつもりだ？",
            ["DialogueId"] = 51102063,
            ["GUID"] = "7FEDBC36",
            ["SpeakNpcId"] = 700322,
            },
        [51102064] = {
            ["Content"] = "二位最好离那个箱子远点，不然在下就要叫人了！",
            ["ContentJP"] = "その箱から離れろ。いい加減にしねぇと……人を呼ぶぞ。",
            ["DialogueId"] = 51102064,
            ["GUID"] = "7FEDBC60",
            ["SpeakNpcId"] = 700322,
            },
        [51102065] = {
            ["Content"] = "在下真的要叫人了！",
            ["ContentJP"] = "本当に人を呼ぶぞ！？",
            ["DialogueId"] = 51102065,
            ["GUID"] = "7FEDBC8A",
            ["SpeakNpcId"] = 700322,
            },
        [51102066] = {
            ["Camera"] = "-75.28125,-74.974609,175.415527,0.000164,-17.598877,87.793106,35.0,129.289429,false,Manual,2.8",
            ["Content"] = "原来如此……",
            ["ContentJP"] = "なるほど……",
            ["DialogueId"] = 51102066,
            ["GUID"] = "7FEDBCB4",
            ["NextDialogue"] = 51102067,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51102067] = {
            ["Camera"] = "177.078125,336.283203,166.046387,0.000125,-5.199065,-126.603699,35.0,516.776245,false,Manual,2.8",
            ["Content"] = "什……什么原来如此？",
            ["ContentJP"] = "な、なるほどって……何が？",
            ["DialogueId"] = 51102067,
            ["GUID"] = "7FEDBCDE",
            ["NextDialogue"] = 51102068,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Talk03_Start",
                },
            },
        [51102068] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "我本来还好奇你为什么要这么大费周章，还要自己跳出来亲自解说一番……",
            ["ContentJP"] = "最初から妙だと思ってた。どうしてわざわざ自分で出てきて、必死に説明してたのか……",
            ["DialogueId"] = 51102068,
            ["GUID"] = "7FEDBD08",
            ["LookAt"] = {
                [1] = "100001:n(700322)",
                },
            ["NextDialogue"] = 51102069,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "700363:n(700322)",
                },
            },
        [51102069] = {
            ["Camera"] = "46.033203,-537.740234,203.479492,0.000243,-11.398854,99.396233,35.0,611.363647,false,Manual,2.8",
            ["Content"] = "看来大风九章并没有认可这埋在荒郊野外的不义之财为你所有，所以你才要专门在我面前长篇大论试图劝退我们。",
            ["ContentJP"] = "大風九章はこの箱を「あなたの物」だと認めていない。だから長々と話して、{性别:僕|私}たちを退けようとしたわけだ。",
            ["DialogueId"] = 51102069,
            ["GUID"] = "7FEDBD32",
            ["NextDialogue"] = 51102070,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51102070] = {
            ["Camera"] = "46.033203,-537.740234,203.479492,0.000243,-11.398854,99.396233,35.0,611.363647,false,Manual,2.8",
            ["Content"] = "只要我像这样触碰到这个箱子，就会知道大风九章并不会生效，也就是说——这就是我捡到的。",
            ["ContentJP"] = "こうして触れても、何も起きない……つまり、この宝は{性别:僕|私}が拾ったものってことだ。",
            ["DialogueId"] = 51102070,
            ["GUID"] = "7FEDBD5C",
            ["NextDialogue"] = 51102071,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51102071] = {
            ["Camera"] = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
            ["Content"] = "真的诶，什么事都没有发生……",
            ["ContentJP"] = "あれ、ほんとだ。何も起きない……",
            ["DialogueId"] = 51102071,
            ["GUID"] = "7FEDBD86",
            ["NextDialogue"] = 51102072,
            ["SpeakNpcId"] = 700363,
            ["TalkActionId"] = {
                [1] = "700363:Shock03_Start",
                },
            },
        [51102072] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "怪不得煜明说这黑市都是些鸡鸣狗盗之徒，大风九章竟被这样曲解利用……",
            ["ContentJP"] = "ユーミンが言ってた通り{性别:だ|ね}。闇市はろくでもない連中ばかり{性别:だな|}。大風九章を都合よく捻じ曲げて利用してる……",
            ["DialogueId"] = 51102072,
            ["GUID"] = "7FEDBDB0",
            ["NextDialogue"] = 51102073,
            ["SpeakNpcId"] = 100001,
            },
        [51102073] = {
            ["Camera"] = "-24.017578,125.793945,181.728516,0.000098,-2.399199,-116.801994,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "你……你……",
            ["ContentJP"] = "お、お前……",
            ["DialogueId"] = 51102073,
            ["GUID"] = "7FEDBDDA",
            ["NextDialogue"] = 51102074,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Talk03_End",
                },
            },
        [51102074] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "如何，要试试在大风九章之下强取豪夺吗？",
            ["ContentJP"] = "どうする？試しに力ずくで奪ってみる？",
            ["DialogueId"] = 51102074,
            ["GUID"] = "7FEDBE04",
            ["NextDialogue"] = 51102075,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51102075] = {
            ["Camera"] = "-101.107422,-127.650391,136.024414,0.000225,-16.998995,60.194729,35.0,188.31813,false,Manual,2.8",
            ["Content"] = "就算你真的敢动手，你也打不过我们小仆从的哦~",
            ["ContentJP"] = "ふふん、やれるもんならやってみなさい！まぁ、うちの下僕には勝てないけどね～",
            ["DialogueId"] = 51102075,
            ["GUID"] = "7FEDBE2E",
            ["NextDialogue"] = 51102076,
            ["SpeakNpcId"] = 700363,
            ["TalkActionId"] = {
                [1] = "700363:Shock03_End",
                },
            },
        [51102076] = {
            ["Camera"] = "444.105469,-373.708008,196.07666,0.000038,-9.999697,143.80011,35.0,696.120667,false,Manual,2.8",
            ["Content"] = "你们……不要再让在下见到你们！否则肯定让你们吃不了兜着走！",
            ["ContentJP"] = "くっ……二度と俺の前に現れるな！次に会ったら……ただじゃおかねぇぞ！",
            ["DialogueId"] = 51102076,
            ["GUID"] = "7FEDBE58",
            ["NextDialogue"] = 51102077,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Angry01_Start",
                },
            },
        [51102077] = {
            ["Camera"] = "-130.197266,-168.708008,189.508789,0.000113,-15.199028,75.196854,35.0,238.547546,false,Manual,2.8",
            ["Content"] = "哦是吗？如果下次再见你没能让我们吃不了兜着走，大风九章会不会觉得你在说谎呢？",
            ["ContentJP"] = "へぇ。じゃあ次に会ったとき、{性别:僕|私}たちを打ち負かせなかったら……大風九章は「お前が嘘をついた」と見なすかもしれない{性别:な|ね}。",
            ["DialogueId"] = 51102077,
            ["GUID"] = "7FEDBE82",
            ["NextDialogue"] = 51102078,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51102078] = {
            ["Camera"] = "534.162109,-171.324219,313.386719,0.000211,-18.79907,165.795944,35.0,672.763,false,Manual,2.8",
            ["Content"] = "你……我……哎！",
            ["ContentJP"] = "なっ……ぐっ、くそ！",
            ["DialogueId"] = 51102078,
            ["GUID"] = "7FEDBEAC",
            ["NextDialogue"] = 51102079,
            ["SpeakNpcId"] = 700322,
            ["TalkActionId"] = {
                [1] = "700322:Angry01_End",
                },
            },
        [51102079] = {
            ["Camera"] = "100.279297,-863.963867,265.523926,0.00021,-8.998719,99.399925,35.0,1009.015198,false,Manual,2.8",
            ["Content"] = "哼，让你骗我们！宝箱~宝箱~看看里面有多少好东西吧。",
            ["ContentJP"] = "へっへ～ん！ざまぁみろ！さてさて、何が入ってるかなぁ～",
            ["DialogueId"] = 51102079,
            ["GUID"] = "7FEDBED6",
            ["NextDialogue"] = 51102080,
            ["SpeakNpcId"] = 700363,
            ["TalkActionId"] = {
                [1] = "700363:BaiTX_Story_Pride_Start",
                },
            },
        [51102080] = {
            ["Camera"] = "-113.234375,-79.991211,166.837891,0.000161,-10.19894,72.195618,35.0,148.932434,false,Manual,2.8",
            ["Content"] = "（到头来还是没搞清楚那个声音是什么。）",
            ["ContentJP"] = "（……結局、あの声が何だったのかは分からずじまいか。）",
            ["DialogueId"] = 51102080,
            ["GUID"] = "7FEDBF00",
            ["NextDialogue"] = 51102081,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            },
        [51102081] = {
            ["Camera"] = "-113.234375,-79.991211,166.837891,0.000161,-10.19894,72.195618,35.0,148.932434,false,Manual,2.8",
            ["Content"] = "（不过没想到会有人靠钻大风九章的空子牟利……这是抛下剑盾，将力量交予“规则”的结果？）",
            ["ContentJP"] = "（けど、こうして誰かが大風九章を抜け道にして稼いでる……それが、剣や盾を捨て「規律」にすがった結果だというの{性别:か|}？",
            ["DialogueId"] = 51102081,
            ["GUID"] = "7FEDBF2A",
            ["NextDialogue"] = 51102082,
            ["SpeakNpcId"] = 100001,
            },
        [51102082] = {
            ["Camera"] = "423.552734,881.602539,168.477539,0.000161,-0.198916,-119.004143,35.0,936.815369,false,Manual,2.8",
            ["Content"] = "（虬先生……这也是你想让我看到的吗？）",
            ["ContentJP"] = "（キョウンさん……あなたが{性别:僕|私}に見せたかったのはこれなのか？）",
            ["DialogueId"] = 51102082,
            ["GUID"] = "7FEDBF54",
            ["SpeakNpcId"] = 100001,
            },
        [51102083] = {
            ["Content"] = "二位英雄请留步。",
            ["ContentJP"] = "そこのお二人、ちょっと待った。",
            ["DialogueId"] = 51102083,
            ["GUID"] = "7FEDBF7E",
            ["SpeakNpcId"] = 700322,
            },
        [51103001] = {
            ["Camera"] = "-544.789062,-142.763672,309.863281,0.000017,-20.213533,11.708329,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（行至附近，你突然感觉怀中的牵机方枢震动了起来。）",
            ["ContentJP"] = "歩みを進めていると、不意に懐の「機巧制御盤」が振動しだした。",
            ["DialogueId"] = 51103001,
            ["GUID"] = "7FEE561A",
            ["NextDialogue"] = 51103002,
            },
        [51103002] = {
            ["Camera"] = "-231.298828,240.494141,220.422852,0.000012,-20.813593,-48.089558,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "小仆从，什么声音？是什么东西在震？！",
            ["ContentJP"] = "な、何この音！？何かが鳴ってない？",
            ["DialogueId"] = 51103002,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "7FEE5644",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51103003,
                [2] = 51103005,
                },
            ["SpeakNpcId"] = 200002,
            },
        [51103003] = {
            ["Content"] = "（震动似乎遵循着什么规律，仔细查看一下吧。）",
            ["ContentJP"] = "この振動には、一定の法則があるようだ。調べてみよう。",
            ["DialogueId"] = 51103003,
            ["GUID"] = "7FEE5645",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 51103004,
            },
        [51103004] = {
            ["Content"] = "（你用平生所学的所有知识分析了一下震动的声音，最终一无所获。）",
            ["ContentJP"] = "全力で解析してみたが、結局何もわからなかった。",
            ["DialogueId"] = 51103004,
            ["GUID"] = "7FEE566E",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51103007,
            },
        [51103005] = {
            ["Content"] = "（这玩意该不会要爆炸了吧，赶紧扔掉！）",
            ["ContentJP"] = "（まさか爆発するんじゃ……！？ はやく捨てないと！）",
            ["DialogueId"] = 51103005,
            ["GUID"] = "7FEE566F",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 51103006,
            },
        [51103006] = {
            ["Content"] = "（你一把将牵机方枢丢出去老远，但预想之中的爆炸并没有发生。确认它就只是在单纯地震动之后，你将它重新捡了起来。）",
            ["ContentJP"] = "慌てて制御盤を遠くへ投げ捨てた。だが爆発は起きず、ただ振動するだけだった。しばらくして、あなたは再びそれを拾い上げた。",
            ["DialogueId"] = 51103006,
            ["GUID"] = "7FEE5698",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51103007,
            },
        [51103007] = {
            ["Camera"] = "-544.789062,-142.763672,309.863281,0.000017,-20.213533,11.708329,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没看到关闭震动的机关，难道是坏了吗？等会去找公尚师傅帮忙看看吧。",
            ["ContentJP"] = "振動を止めるスイッチは見当たらないなぁ。壊れたのかな？あとでコウショウ師匠に見てもらおう。",
            ["DialogueId"] = 51103007,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "7FEE56C2",
            ["NextDialogue"] = 51103008,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            },
        [51103008] = {
            ["Content"] = "这个东西原来质量这么差哦，还没用几次就这样了……",
            ["ContentJP"] = "えーなにそれ、粗悪品じゃん！まだ数回しか使ってないのに！",
            ["DialogueId"] = 51103008,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "7FEE56EC",
            ["NextDialogue"] = 51103009,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                },
            },
        [51103009] = {
            ["Content"] = "（打定主意后，你转身准备离开，没走几步，你就感到牵机方枢的震动减弱了。）",
            ["ContentJP"] = "そう言いながら歩いていると、急に振動が弱まった。",
            ["DialogueId"] = 51103009,
            ["GUID"] = "7FEE5716",
            ["NextDialogue"] = 51103010,
            ["Scripts"] = "MoveTo{ActorId{100001},TargetPoint{\"TargetPoint200306_1\"},MoveSpeed{70},Visibility{\"Show\"}}",
            },
        [51103010] = {
            ["Camera"] = "532.106445,-37.09668,232.477539,0.000057,-18.413574,-177.48764,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51103010,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "7FEE5740",
            ["NextDialogue"] = 51103011,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            },
        [51103011] = {
            ["Content"] = "刚才我面向那边的时候，这牵机方枢的震动明显比其他方向要强一些。难道这震动，是在为我指明方向？",
            ["ContentJP"] = "あの方向を向いてる時だけ、振動が強くなってる……もしかして、道しるべをしてくれてるのかな？",
            ["DialogueId"] = 51103011,
            ["GUID"] = "7FEE576A",
            ["NextDialogue"] = 51103012,
            ["SpeakNpcId"] = 100001,
            },
        [51103012] = {
            ["Content"] = "哇——小仆从，那个方向该不会藏着什么大宝贝？！我们赶紧去看看吧！",
            ["ContentJP"] = "それって、お宝じゃない！？はやく行こっ！",
            ["DialogueId"] = 51103012,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["GUID"] = "7FEE5794",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:SpecialHappy_Start",
                },
            },
        [51103013] = {
            ["Camera"] = "-273.101562,182.818359,178.920898,0.00004,-6.843535,-26.529842,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "公尚师傅，你怎么在这？",
            ["ContentJP"] = "コウショウ師匠……ど、どうしてここに？",
            ["DialogueId"] = 51103013,
            ["FacialId"] = {
                [1] = "100001:Shock01",
                },
            ["GUID"] = "7FEE57BE",
            ["LookAt"] = {
                [1] = "100001:n(700323)",
                [2] = "200002:n(700323)",
                },
            ["NextDialogue"] = 51103014,
            ["SpeakNpcId"] = 100001,
            },
        [51103014] = {
            ["Camera"] = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "大惊小怪的干什么？",
            ["ContentJP"] = "いちいち大げさなやつだ。",
            ["DialogueId"] = 51103014,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "7FEE57E8",
            ["LookAt"] = {
                [1] = "700323:n(100001)",
                },
            ["NextDialogue"] = 51103015,
            ["SpeakNpcId"] = 700323,
            },
        [51103015] = {
            ["Content"] = "我腿脚不好，懒得走动。察觉你们到了附近，便用牵机方枢指引你们过来。如何？这只是它千般妙用中的一种，要论其中更多门道……",
            ["ContentJP"] = "私は足腰が悪くてな、歩き回るのは億劫なんだ。だからその装置でお前たちを呼び寄せた。どうだ、良い使い道だろう。そのほかにも……",
            ["DialogueId"] = 51103015,
            ["GUID"] = "7FEE5812",
            ["NextDialogue"] = 51103016,
            ["SpeakNpcId"] = 700323,
            },
        [51103016] = {
            ["Camera"] = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "还以为有什么大宝贝，原来是你……没劲。",
            ["ContentJP"] = "なんだ、あんたか。お宝かと思ったのに……",
            ["DialogueId"] = 51103016,
            ["GUID"] = "7FEE583C",
            ["LookAt"] = {
                [1] = "200002:n(200002)",
                },
            ["NextDialogue"] = 51103017,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Sigh_Start",
                },
            },
        [51103017] = {
            ["Camera"] = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "叫我们过来，就是为了说这些吗？",
            ["ContentJP"] = "{性别:わざわざ呼び寄せたのは、このためなのか？|わざわざ呼び寄せたのは、このためなの？}",
            ["DialogueId"] = 51103017,
            ["GUID"] = "7FEE5866",
            ["NextDialogue"] = 51103018,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51103018] = {
            ["Camera"] = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，连机关的使用说明都不愿意听完。现在的年轻人，沉不下心来研究学问，着实浮躁啊。",
            ["ContentJP"] = "ふん、今どきの若者はせっかちでいかん。学問というものに腰を据えて向き合えんのか。",
            ["DialogueId"] = 51103018,
            ["GUID"] = "7FEE5890",
            ["LookAt"] = {
                [1] = "200002:n(700323)",
                },
            ["NextDialogue"] = 51103019,
            ["SpeakNpcId"] = 700323,
            ["TalkActionId"] = {
                [1] = "200002:Sigh_End",
                },
            },
        [51103019] = {
            ["Camera"] = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们小仆从日理万机，你再不说正题，我们可就要走了。",
            ["ContentJP"] = "スノウたちは忙しいの！他に用がないなら帰るよ！",
            ["DialogueId"] = 51103019,
            ["GUID"] = "7FEE58BA",
            ["NextDialogue"] = 51103020,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            },
        [51103020] = {
            ["Camera"] = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎哎，可别走——",
            ["ContentJP"] = "待て待て！",
            ["DialogueId"] = 51103020,
            ["GUID"] = "7FEE58E4",
            ["NextDialogue"] = 51103021,
            ["SpeakNpcId"] = 700323,
            },
        [51103021] = {
            ["Content"] = "你二位怎么说也是机枢派荣誉学徒了。既然与我机枢派有缘，那我这引路人可得担起责任，让你们一品机枢之乐。",
            ["ContentJP"] = "お前たちは既に機枢派の名誉弟子だ。せっかくだから、私が直々に「機枢の楽しみ」を味わわせてやろう。",
            ["DialogueId"] = 51103021,
            ["GUID"] = "7FEE590E",
            ["NextDialogue"] = 51103022,
            ["SpeakNpcId"] = 700323,
            },
        [51103022] = {
            ["Camera"] = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我在这里布置了数处机枢机关，皆为匠心打造，各有精妙设计。怎么样，是不是心动了，想赶紧体验一把？",
            ["ContentJP"] = "ここに仕掛けをいくつか設けた。どれも工夫が凝らされておるぞ。どうだ、試してみたくなっただろう？",
            ["DialogueId"] = 51103022,
            ["GUID"] = "7FEE5938",
            ["NextOptions"] = {
                [1] = 51103023,
                [2] = 51103024,
                },
            ["SpeakNpcId"] = 700323,
            },
        [51103023] = {
            ["Content"] = "呃，这个嘛……",
            ["ContentJP"] = "ええと……",
            ["DialogueId"] = 51103023,
            ["GUID"] = "7FEE5939",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 51103025,
            },
        [51103024] = {
            ["Content"] = "没什么更实质性的好处吗？",
            ["ContentJP"] = "報酬は？",
            ["DialogueId"] = 51103024,
            ["GUID"] = "7FEE5940",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51103025,
            },
        [51103025] = {
            ["Camera"] = "689.817383,85.535156,210.976562,0.000054,-12.043699,-166.726059,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，就知道你们年轻人会这样。",
            ["ContentJP"] = "ははは、やはりそう来るか。",
            ["DialogueId"] = 51103025,
            ["GUID"] = "7FEE5962",
            ["NextDialogue"] = 51103026,
            ["SpeakNpcId"] = 700323,
            ["TalkActionId"] = {
                [1] = "700323:Disagree",
                },
            },
        [51103026] = {
            ["Content"] = "根据我收徒这么多年来的碰壁经验，没什么好处，你们年轻人是不会上钩的。放心，奖励我早就准备好了。",
            ["ContentJP"] = "安心せい、若もんの考えとることくらい、手に取るようにわかる。褒美はちゃんと用意しておるぞ。",
            ["DialogueId"] = 51103026,
            ["GUID"] = "7FEE598C",
            ["NextDialogue"] = 51103027,
            ["SpeakNpcId"] = 700323,
            },
        [51103027] = {
            ["Camera"] = "-24.505859,162.111328,225.938477,0.000064,-16.843164,-31.323021,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那就勉强答应你吧。",
            ["ContentJP"] = "じゃあ付き合うよ……",
            ["DialogueId"] = 51103027,
            ["GUID"] = "7FEE59B6",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            },
        [51103028] = {
            ["Content"] = "我们现在玩的这个很简单，找到附近的机枢球，用你手里的牵机方枢把它们引到这个坑里就行，试试看。",
            ["ContentJP"] = "ルールは簡単だ。近くにある機枢球を探して、この機巧制御盤であの穴まで誘導すればいい。さあ、試してみな。",
            ["DialogueId"] = 51103028,
            ["Duration"] = 12,
            ["GUID"] = "7FEE59E0",
            ["SpeakNpcId"] = 700323,
            },
        [51103029] = {
            ["Content"] = "不错，一点就通。",
            ["ContentJP"] = "やるじゃないか、コツを掴んだようだな。さあ次に進もう！",
            ["DialogueId"] = 51103029,
            ["Duration"] = 5,
            ["GUID"] = "7FEE5A0A",
            ["SpeakNpcId"] = 700323,
            },
        [51103030] = {
            ["Content"] = "这个机枢考验的是你的记忆力，记住那些金色组件的位置，然后用牵机方枢把它们拉出来就行，也不难对吧。",
            ["ContentJP"] = "ここは記憶力の試練だ。赤い部品の位置を覚えて、機巧制御盤で引っ張り出せばいい。そう難しくはないだろう？",
            ["DialogueId"] = 51103030,
            ["Duration"] = 12,
            ["GUID"] = "7FEE5A34",
            ["SpeakNpcId"] = 700323,
            },
        [51103031] = {
            ["Content"] = "干得好，不愧是我授予了机枢派名誉学徒的人。拿上你应得的奖励吧。",
            ["ContentJP"] = "よくやった！ さすが機枢派の名誉弟子だ。ご褒美を受け取って、次の挑戦に進め。",
            ["DialogueId"] = 51103031,
            ["Duration"] = 7,
            ["GUID"] = "7FEE5A5E",
            ["SpeakNpcId"] = 700323,
            },
        [51103032] = {
            ["Content"] = "这种机枢会稍微复杂一点，你可得看仔细了。",
            ["ContentJP"] = "最後のは難易度が上がるぞ。しっかり見ておけよ。",
            ["DialogueId"] = 51103032,
            ["Duration"] = 7,
            ["GUID"] = "7FEE5A88",
            ["NextDialogue"] = 51103033,
            ["SpeakNpcId"] = 700323,
            },
        [51103033] = {
            ["Content"] = "这机枢门的位置会根据牵引的方向不同而产生变化，所以你得把它停在合适的位置，然后钻进去拿奖励，明白了吧？",
            ["ContentJP"] = "このからくり門は、引き寄せる方向によって位置が変わる。正しい場所で止めれば、報酬を受け取れるぞ。わかったな？",
            ["DialogueId"] = 51103033,
            ["GUID"] = "7FEE5AB2",
            ["SpeakNpcId"] = 700323,
            },
        [51103034] = {
            ["Camera"] = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "感觉如何？",
            ["ContentJP"] = "どうだ？",
            ["DialogueId"] = 51103034,
            ["GUID"] = "7FEE5ADC",
            ["LookAt"] = {
                [1] = "100001:n(700323)",
                [2] = "200002:n(700323)",
                [3] = "700323:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51103035,
                [2] = 51103037,
                [3] = 51103039,
                },
            ["SpeakNpcId"] = 700323,
            },
        [51103035] = {
            ["Content"] = "是有点好玩。",
            ["ContentJP"] = "ちょっと楽しかったかも。",
            ["DialogueId"] = 51103035,
            ["GUID"] = "7FEE5ADD",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 51103036,
            },
        [51103036] = {
            ["Camera"] = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈，但凡体验过机枢之乐的人，无一不为其折服！别担心，我在烟津渡还布置了不少机枢，想玩的话管够。",
            ["ContentJP"] = "ハハッ、そうだろう？ 一度でもからくりの面白さを味わえば誰だって虜になる！安心しろ、煙津渡にはまだまだ仕掛けを用意してある。好きなだけ遊んでいけ。",
            ["DialogueId"] = 51103036,
            ["GUID"] = "7FEE5B06",
            ["NextDialogue"] = 51103042,
            ["SpeakNpcId"] = 700323,
            ["TalkActionId"] = {
                [1] = "700323:Agree",
                },
            },
        [51103037] = {
            ["Content"] = "奖励太少了。",
            ["ContentJP"] = "報酬が少なすぎるよ。",
            ["DialogueId"] = 51103037,
            ["GUID"] = "7FEE5B07",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51103038,
            },
        [51103038] = {
            ["Camera"] = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别担心，玩得越多，奖励就越多。我在烟津渡还布置了不少机枢，俗话说得好，积少成多嘛！",
            ["ContentJP"] = "心配するな。遊べば遊ぶほど報酬も増えていく。煙津渡にはまだからくりをたくさん仕込んであるんだ。俗に言うだろう、「塵も積もれば山となる」ってな！",
            ["DialogueId"] = 51103038,
            ["GUID"] = "7FEE5B30",
            ["NextDialogue"] = 51103042,
            ["SpeakNpcId"] = 700323,
            },
        [51103039] = {
            ["Content"] = "感觉不够……好玩……",
            ["ContentJP"] = "まだまだ……物足りない{性别:な|ね}。",
            ["DialogueId"] = 51103039,
            ["GUID"] = "7FEE5B31",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 51103040,
            },
        [51103040] = {
            ["Camera"] = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，没品，实在没品！你先别急，这些只是入门级别，六岁学童都能轻松过关。",
            ["ContentJP"] = "やれやれ、欲深いな！まあ焦るな、今のはほんの入門編。子どもでも簡単に突破できる程度のものだ。",
            ["DialogueId"] = 51103040,
            ["GUID"] = "7FEE5B5A",
            ["NextDialogue"] = 51103041,
            ["SpeakNpcId"] = 700323,
            ["TalkActionId"] = {
                [1] = "700323:Disagree",
                },
            },
        [51103041] = {
            ["Content"] = "好玩的还在后面呢！我在烟津渡还布置了不少机枢，再不济，为了奖励，你也多试试吧。",
            ["ContentJP"] = "本当に面白いのはこの先だ。煙津渡にはまだまだからくりを仕掛けてある。報酬目当てでも構わん、もっと挑戦してみろ。",
            ["DialogueId"] = 51103041,
            ["GUID"] = "7FEE5B84",
            ["NextDialogue"] = 51103042,
            ["SpeakNpcId"] = 700323,
            },
        [51103042] = {
            ["Camera"] = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎？原来我们一路上看到的那些机关块全都是你布置的。公尚师傅，你做这些到底有什么目的？",
            ["ContentJP"] = "え？道中で見たあの仕掛けの数々、全部あなたが仕込んだの？でも、いったい何のために？",
            ["DialogueId"] = 51103042,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "7FEE5BAE",
            ["NextDialogue"] = 51103043,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            },
        [51103043] = {
            ["Camera"] = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "目的？哈哈，这样想就落入俗套了。",
            ["ContentJP"] = "目的？ハハハ、そんなふうに考えるのは凡俗の発想さ。",
            ["DialogueId"] = 51103043,
            ["GUID"] = "7FEE5BD8",
            ["NextDialogue"] = 51103044,
            ["SpeakNpcId"] = 700323,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51103044] = {
            ["Content"] = "也难免你们这样想，毕竟帝国的炼金术师搞研究都带着些军事目的，像工造局那些迂腐的老东西则是为了混口饭吃。",
            ["ContentJP"] = "まあ無理もない。帝国の錬金術師どもは軍事目的で研究しているし、工造局の古臭い連中は生活のためにやっている。",
            ["DialogueId"] = 51103044,
            ["GUID"] = "7FEE5C02",
            ["NextDialogue"] = 51103045,
            ["SpeakNpcId"] = 700323,
            },
        [51103045] = {
            ["Content"] = "他们也不能说错，但目的性太强，便体会不到机枢中纯粹的乐趣。",
            ["ContentJP"] = "それも間違いじゃないが、目的ばかりに囚われていては、からくりの純粋な楽しみを味わえんのだよ。",
            ["DialogueId"] = 51103045,
            ["GUID"] = "7FEE5C2C",
            ["NextDialogue"] = 51103046,
            ["SpeakNpcId"] = 700323,
            },
        [51103046] = {
            ["Camera"] = "259.686523,140.730469,196.319336,0.000266,-11.042141,-145.534332,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "公尚师傅研究机枢，就是因为有趣吗？",
            ["ContentJP"] = "じゃあ、師匠は純粋に楽しむために研究してるってこと？",
            ["DialogueId"] = 51103046,
            ["GUID"] = "7FEE5C56",
            ["NextDialogue"] = 51103047,
            ["SpeakNpcId"] = 100001,
            },
        [51103047] = {
            ["Camera"] = "-343.328125,-542.464844,187.925781,0.000128,-9.042596,61.258392,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "人生不过短短数十年，怎能蹉跎在无趣之物上呢？只有从本心出发，才能追寻“道”的极致啊。",
            ["ContentJP"] = "人の一生なんて短いものだ。くだらんものに費やしてどうする？ 本心からの好奇心こそが「道」の極致を追う力になるのだ。",
            ["DialogueId"] = 51103047,
            ["GUID"] = "7FEE5C80",
            ["NextDialogue"] = 51103048,
            ["SpeakNpcId"] = 700323,
            ["TalkActionId"] = {
                [1] = "700323:Agree",
                },
            },
        [51103048] = {
            ["Content"] = "说到这里，虽然秦虬那家伙老是狗嘴吐不出象牙……但也多亏了他，我这些年里才能无拘无束全心沉浸于机枢研究。",
            ["ContentJP"] = "それに……キョウンは口の悪い男だが、あいつのおかげで私は何年も好きなだけ研究に没頭できた。",
            ["DialogueId"] = 51103048,
            ["GUID"] = "7FEE5CAA",
            ["NextDialogue"] = 51103049,
            ["SpeakNpcId"] = 700323,
            },
        [51103049] = {
            ["Content"] = "哎，刚才这句话你可别告诉他啊，不然他尾巴都得翘到天上去。",
            ["ContentJP"] = "――っと、このことは内緒だぞ。あいつに知られたら、鼻を天まで伸ばしかねねぇ。",
            ["DialogueId"] = 51103049,
            ["GUID"] = "7FEE5CD4",
            ["NextOptions"] = {
                [1] = 51103050,
                [2] = 51103051,
                },
            ["SpeakNpcId"] = 700323,
            },
        [51103050] = {
            ["Content"] = "好的。",
            ["ContentJP"] = "分かった。",
            ["DialogueId"] = 51103050,
            ["GUID"] = "7FEE5CD5",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 51103052,
            },
        [51103051] = {
            ["Content"] = "师傅，你也不想这些话传到他耳朵里吧。",
            ["ContentJP"] = "ふふん、この話が彼の耳に入ったらまずいよね。",
            ["DialogueId"] = 51103051,
            ["GUID"] = "7FEE5CD6",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 51103052,
            },
        [51103052] = {
            ["Content"] = "哈哈！好了好了，今天就到这里罢。我也得回去捣鼓别的发明了。",
            ["ContentJP"] = "ハハハッ！もう今日はここまでにしよう。私は別の発明に戻らねばならん。",
            ["DialogueId"] = 51103052,
            ["FacialId"] = {
                [1] = "700323:CM_Happy01",
                },
            ["GUID"] = "7FEE5CFE",
            ["LookAt"] = {
                [1] = "700323:n(700323)",
                },
            ["NextDialogue"] = 51103053,
            ["Scripts"] = "MoveTo{ActorId{700323},TargetPoint{\"TargetPoint200306_3\"},MoveSpeed{70},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700323,
            },
        [51103053] = {
            ["Content"] = "对了，等我研究出来新的机枢，记得再来体验体验啊。",
            ["ContentJP"] = "焦るな、また新しいアイデアが浮かんだぞ。",
            ["DialogueId"] = 51103053,
            ["GUID"] = "7FEE5D28",
            ["SpeakNpcId"] = 700323,
            },
        [51103054] = {
            ["Content"] = "别急，我有新点子了。",
            ["ContentJP"] = "……そうだ、新しいからくりが完成したら、また体験しに来いよ。",
            ["DialogueId"] = 51103054,
            ["GUID"] = "7FEE5D29",
            ["SpeakNpcId"] = 700323,
            },
        [51103055] = {
            ["Content"] = "公尚师傅，你怎么在这？",
            ["ContentJP"] = "コウショウ師匠……ど、どうしてここに？",
            ["DialogueId"] = 51103055,
            ["GUID"] = "7FEE5D2A",
            ["NextDialogue"] = 51103014,
            ["SpeakNpcId"] = 100001,
            },
        [51103056] = {
            ["Content"] = "公尚师傅，你怎么在这？",
            ["ContentJP"] = "コウショウ師匠……ど、どうしてここに？",
            ["DialogueId"] = 51103056,
            ["GUID"] = "7FEE5D2B",
            ["NextDialogue"] = 51103014,
            ["SpeakNpcId"] = 100001,
            },
        [51104001] = {
            ["Content"] = "小仆从小仆从，听我说！锦鲤皎皎告诉了本魔王一个天大的秘密——",
            ["ContentJP"] = "ねぇねぇ、聞いて！ニシキがとっておきの情報を教えてくれたんだ！",
            ["DialogueId"] = 51104001,
            ["GUID"] = "7FEEFA2A",
            ["NextDialogue"] = 51104002,
            ["SpeakNpcId"] = 700324,
            },
        [51104002] = {
            ["Content"] = "整个烟津渡最好吃最地道的小吃，就藏在这个码头的摊子里！这可是只有本地人才能知道的秘密，一般人她才不告诉！",
            ["ContentJP"] = "この港の屋台の片隅に、煙津渡で一番おいしい菓子があるって！地元の人しか知らない名物らしいよ！",
            ["DialogueId"] = 51104002,
            ["GUID"] = "7FEEFA54",
            ["NextDialogue"] = 51104003,
            ["SpeakNpcId"] = 700324,
            },
        [51104003] = {
            ["Content"] = "就是前面的桂花糕摊位了，我们赶紧去看看吧！",
            ["ContentJP"] = "ほら、あの桂花菓子の屋台だ！早く行ってみよう！",
            ["DialogueId"] = 51104003,
            ["GUID"] = "7FEEFA7E",
            ["SpeakNpcId"] = 700324,
            },
        [51104004] = {
            ["Camera"] = "-640.476562,-1148.253906,155.432617,0.000009,-1.399472,64.393364,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哥，这边这边！",
            ["ContentJP"] = "兄ちゃん、こっちこっち！",
            ["DialogueId"] = 51104004,
            ["GUID"] = "7FEEFAA8",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104005,
            ["Scripts"] = "MoveTo{ActorId{700327},TargetPoint{\"P51104004XiaoWu\"},MoveSpeed{250},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700327,
            },
        [51104005] = {
            ["Content"] = "别跑那么快啊，等等我！",
            ["ContentJP"] = "おい、走るなって！待てよ！",
            ["DialogueId"] = 51104005,
            ["GUID"] = "7FEEFAD2",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104006,
            ["Scripts"] = "MoveTo{ActorId{700326},TargetPoint{\"P51104004XiaoWen\"},MoveSpeed{250},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700326,
            ["TurnTo"] = {
                [1] = "700327:n(700328)",
                },
            },
        [51104006] = {
            ["Camera"] = "359.076172,-369.277344,120.089844,0.000002,-2.199519,103.398605,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哥，我想吃这个。",
            ["ContentJP"] = "兄ちゃん、これ食べたい！",
            ["DialogueId"] = 51104006,
            ["GUID"] = "7FEEFAFC",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104007,
            ["SpeakNpcId"] = 700327,
            ["TurnTo"] = {
                [1] = "700326:n(700327)",
                [2] = "700327:n(700326)",
                },
            },
        [51104007] = {
            ["Content"] = "啊？桂花糕啊……明明说好不买这买那才带你出门的。",
            ["ContentJP"] = "えっ、桂花菓子？……さっき「無駄遣いしない」って約束したばかりだろ！",
            ["DialogueId"] = 51104007,
            ["FacialId"] = {
                [1] = "700326:Syouganai01",
                },
            ["GUID"] = "7FEEFB26",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104008,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Disagree",
                },
            },
        [51104008] = {
            ["Content"] = "我没有买这买那，今天从出门到现在我明明只让你买了一次蜂蜜糍耙。",
            ["ContentJP"] = "うん、だから朝から今まで蜂蜜もちしかおねだりしてないじゃん！",
            ["DialogueId"] = 51104008,
            ["GUID"] = "7FEEFB50",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104009,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Talk03_Start",
                },
            },
        [51104009] = {
            ["Content"] = "糍粑不好消化，刚吃完现在又要吃这桂花糕……",
            ["ContentJP"] = "もちは消化に悪い。さっき食べたばかりなのに、またお菓子なんて……",
            ["DialogueId"] = 51104009,
            ["FacialId"] = {
                [1] = "700326:Unhappy01",
                },
            ["GUID"] = "7FEEFB7A",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104010,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700327:Talk03_End",
                [2] = "700326:Talk01_Start",
                },
            },
        [51104010] = {
            ["Content"] = "一会回家吃不下饭被阿娘骂事小，要是再晚上肚子胀到睡不着觉我可帮不了你。",
            ["ContentJP"] = "帰って晩ご飯が食べられなかったら母さんに叱られるし、夜お腹が張って眠れなくなっても知らないからな。",
            ["DialogueId"] = 51104010,
            ["GUID"] = "7FEEFBA4",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104011,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Talk01_End",
                },
            },
        [51104011] = {
            ["Content"] = "我不管！今天吃不到桂花糕我就不回去了，到时候阿娘一着急你就惨咯。",
            ["ContentJP"] = "そんなの知らない！桂花菓子買ってくれるまで帰らないからね！母さんが怒って困るのは兄ちゃんだよ！",
            ["DialogueId"] = 51104011,
            ["GUID"] = "7FEEFBCE",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104012,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Angry01_Start",
                },
            },
        [51104012] = {
            ["Content"] = "行吧行吧，拗不过你。老板，要一份桂花糕。",
            ["ContentJP"] = "はぁ……しょうがないな。――すみませーん、桂花菓子を一つください。",
            ["DialogueId"] = 51104012,
            ["FacialId"] = {
                [1] = "700326:Syouganai01",
                },
            ["GUID"] = "7FEEFBF8",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104013,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700327:Angry01_End",
                },
            ["TurnTo"] = {
                [1] = "700326:n(700328)",
                [2] = "700327:n(700328)",
                },
            },
        [51104013] = {
            ["Content"] = "好嘞。",
            ["ContentJP"] = "はいよ。",
            ["DialogueId"] = 51104013,
            ["FacialId"] = {
                [1] = "700328:Smile01",
                },
            ["GUID"] = "7FEEFC22",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104014,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Give",
                },
            },
        [51104014] = {
            ["Content"] = "呃……老板，桂花糕能卖半份……啊不，三分之一份吗？出门带的铜币好像不够了……",
            ["ContentJP"] = "……あっ、でも……桂花菓子、半分……いや、三分の一で売ってもらえますか？持ち金が足りなくて……",
            ["DialogueId"] = 51104014,
            ["GUID"] = "7FEEFC4C",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700328:n(700326)",
                },
            ["NextDialogue"] = 51104015,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Sigh_Start",
                },
            },
        [51104015] = {
            ["Content"] = "你这小家伙……罢了罢了。",
            ["ContentJP"] = "まったく……しょうがないねぇ。",
            ["DialogueId"] = 51104015,
            ["FacialId"] = {
                [1] = "700328:Syouganai01",
                },
            ["GUID"] = "7FEEFC76",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104016,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700326:Sigh_End",
                },
            },
        [51104016] = {
            ["Content"] = "我们家老爷子倒是交代过，要是有小孩子嘴馋也不用太计较，按老爷子说法，给你们两个小家伙出个谜语。",
            ["ContentJP"] = "うちの親父はね、子ども相手には細かいこと言うなって口うるさく言ってたんだよ。だから、こうしよう。ひとつ謎かけを出す。",
            ["DialogueId"] = 51104016,
            ["GUID"] = "7FEEFCA0",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104017,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Think_Start",
                },
            },
        [51104017] = {
            ["Content"] = "要是你俩能猜上来啊，这桂花糕送你们一份也行。",
            ["ContentJP"] = "それが解けたら、この桂花菓子をおまけしてやるよ。",
            ["DialogueId"] = 51104017,
            ["GUID"] = "7FEEFCCA",
            ["LookAt"] = {
                [1] = "700327:n(700328)",
                [2] = "700326:n(700328)",
                },
            ["NextDialogue"] = 51104018,
            ["SpeakNpcId"] = 700328,
            },
        [51104018] = {
            ["Content"] = "真的吗？",
            ["ContentJP"] = "ほんとに！？",
            ["DialogueId"] = 51104018,
            ["GUID"] = "7FEEFCF4",
            ["LookAt"] = {
                [1] = "700326:n(700327)",
                [2] = "700328:n(700327)",
                },
            ["NextDialogue"] = 51104019,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Huanhu_Nan_Start",
                [2] = "700328:Think_End",
                },
            },
        [51104019] = {
            ["Content"] = "我骗你们两个小毛孩做什么。",
