        [51104044] = {
            ["Content"] = "桂花",
            ["ContentJP"] = "桂花",
            ["DialogueId"] = 51104044,
            ["GUID"] = "7FEF0138",
            ["NextDialogue"] = 51104045,
            },
        [51104045] = {
            ["Content"] = "得了，就是这桂花糕的桂花……来，刚蒸好还冒着热气呢，您拿好。",
            ["ContentJP"] = "その通り。桂花菓子の桂花さ――さあ、蒸したてだ。持っていきな",
            ["DialogueId"] = 51104045,
            ["GUID"] = "7FEF0162",
            ["NextDialogue"] = 51104046,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk02_End",
                [2] = "700324:Angry02_End",
                },
            },
        [51104046] = {
            ["Content"] = "也不知道老爷子是怎么想的，做些糕点本就是小本营生，倒还是要猜谜白送些出去。这么一折腾啊，自己的养老钱都剩不下几个了哟。",
            ["ContentJP"] = "まったく……親父の気まぐれにはついていけない。商売で飯を食ってるのに、謎かけで菓子をタダでやるなんて……。こんな調子じゃ、老後の蓄えも残りゃしないよ。",
            ["DialogueId"] = 51104046,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake01.T_Guide_ChapterEast01_GuiHuaCake01'}",
            ["GUID"] = "7FEF018C",
            ["NextDialogue"] = 51104047,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Sigh_Start",
                },
            },
        [51104047] = {
            ["Camera"] = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你不同意这么做吗？",
            ["ContentJP"] = "あなたはこのやり方には反対なんだ{性别:な|ね}。",
            ["DialogueId"] = 51104047,
            ["GUID"] = "7FEF01B6",
            ["NextDialogue"] = 51104048,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51104048] = {
            ["Camera"] = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦，客人你别误会，说了猜谜白送那自然就是白送。看着小孩子眼巴巴地站在一边流口水，拿胳膊擦擦又往身上抹，我也不忍心。",
            ["ContentJP"] = "いや、そうじゃない。小さな子が菓子を欲しがってるのを見れば、つい渡したくなる。……俺もそうだったんだ。",
            ["DialogueId"] = 51104048,
            ["GUID"] = "7FEF01E0",
            ["NextDialogue"] = 51104049,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Sigh_End",
                [2] = "100001:Think_End",
                },
            },
        [51104049] = {
            ["Content"] = "小孩嘛，能吃多少？送就送了。当初我举目无亲在这街头闲逛，要不是馋这一口桂花糕让老爷子注意到我，收留我做了个学徒，恐怕也……",
            ["ContentJP"] = "天涯孤独でこの町をさまよってた俺を救ってくれたのはこの桂花菓子だ。この菓子のおかげで、親父に巡り合い、弟子として受け入れてもらえた……",
            ["DialogueId"] = 51104049,
            ["FacialId"] = {
                [1] = "700328:Happy01",
                },
            ["GUID"] = "7FEF020A",
            ["NextDialogue"] = 51104050,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk02_Start",
                },
            },
        [51104050] = {
            ["Content"] = "嗨，我跟客人您说这个干嘛……咱就是有点好奇，老爷子这猜谜送桂花糕的规矩，是为什么立的。",
            ["ContentJP"] = "……っと、客人に愚痴を聞かせるもんじゃないな。ただ、あの人がなぜ謎かけで菓子を渡すなんて決まりを作ったのか、不思議でさ。",
            ["DialogueId"] = 51104050,
            ["FacialId"] = {
                [1] = "700328:None",
                },
            ["GUID"] = "7FEF0234",
            ["NextDialogue"] = 51104051,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk02_End",
                },
            },
        [51104051] = {
            ["Content"] = "不过老爷子不想说，咱也不多问。摊子和手艺都是人家的，回头客也都是冲着桂花李的招牌来的。这些东西传给我一个捡来的野小子，我已经知足了。",
            ["ContentJP"] = "本人が言わない以上、俺が口を出すことじゃない。看板も腕前も全部あの人のものだ。俺みたいな拾われ者に継がせてくれただけで、十分すぎる恩だよ。",
            ["DialogueId"] = 51104051,
            ["GUID"] = "7FEF025E",
            ["NextDialogue"] = 51104052,
            ["SpeakNpcId"] = 700328,
            },
        [51104052] = {
            ["Camera"] = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你好像是在抱怨，但其实心里很喜欢这位老爷子吧？",
            ["ContentJP"] = "口では不満を言ってても、本当は大事に思ってるんだ{性别:な|ね}。",
            ["DialogueId"] = 51104052,
            ["GUID"] = "7FEF0288",
            ["NextDialogue"] = 51104053,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51104053] = {
            ["Camera"] = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈……这位客人，不瞒您说，他供我吃住又教我手艺。我早就把他当父亲看待了。只是他平日里不许我叫爹，非让我叫他师父。",
            ["ContentJP"] = "……はは、図星だな。あの人には飯を食わせてもらい、技を叩き込んでもらった。俺にとってはもう父親みたいな存在だ。ただ親父とは呼ばせてくれなくてな、師匠と呼べの一点張りだよ。",
            ["DialogueId"] = 51104053,
            ["GUID"] = "7FEF02B2",
            ["NextDialogue"] = 51104054,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            },
        [51104054] = {
            ["Content"] = "这再造之恩，无以能报。我只希望一直给他养老，让他安安稳稳地颐享天年哟。",
            ["ContentJP"] = "だからせめて、老後を支えてやりたい。穏やかに暮らして、天寿を全うしてほしいんだ",
            ["DialogueId"] = 51104054,
            ["GUID"] = "7FEF02DC",
            ["NextDialogue"] = 51104055,
            ["SpeakNpcId"] = 700328,
            },
        [51104055] = {
            ["Camera"] = "470.919922,-447.367188,169.704102,0.000065,-7.799495,112.800148,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哟，小李，忙着呐？",
            ["ContentJP"] = "おぅ、リー！忙しそうだな。",
            ["DialogueId"] = 51104055,
            ["GUID"] = "7FEF0306",
            ["LookAt"] = {
                [1] = "100001:n(700332)",
                [2] = "700324:n(700332)",
                [3] = "700328:n(700332)",
                },
            ["NextDialogue"] = 51104056,
            ["Scripts"] = "MoveTo{ActorId{700332},TargetPoint{\"P51104055ZhaoShu\"},MoveSpeed{90},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700332,
            },
        [51104056] = {
            ["Content"] = "赵叔，您怎么来了？现做的桂花糕，给您包一份？",
            ["ContentJP"] = "チョウさん、いらっしゃい！菓子、包みましょうか？",
            ["DialogueId"] = 51104056,
            ["GUID"] = "7FEF0330",
            ["LookAt"] = {
                [1] = "700332:n(700328)",
                },
            ["NextDialogue"] = 51104057,
            ["SpeakNpcId"] = 700328,
            ["TurnTo"] = {
                [1] = "700328:n(700332)",
                },
            },
        [51104057] = {
            ["Content"] = "不用不用，先招呼客人。闲下来了跟你家老爷子招呼一声，说好了上我那喝两杯，半晌了都没见人，再不来啊，我这好酒他可就尝不着喽。",
            ["ContentJP"] = "いやいや、客人を優先しなさい。それより、お前の親父さんによろしく言っといてくれ。うちで飲もうって誘ったのに、全然来なくてな。いい酒が冷めちまう。",
            ["DialogueId"] = 51104057,
            ["GUID"] = "7FEF035A",
            ["NextDialogue"] = 51104058,
            ["SpeakNpcId"] = 700332,
            ["TalkActionId"] = {
                [1] = "700332:Talk02_Start",
                },
            },
        [51104058] = {
            ["Content"] = "……这可奇怪了。老爷子这些年来，和人约好了时间从来只有提早登门，绝无迟到的道理。要是我不小心误了点，他还会用拐杖敲我哩。",
            ["ContentJP"] = "……妙だな。約束の時間に遅れたことなんて一度もない。むしろ俺が遅れると、杖でこづかれるくらいで……",
            ["DialogueId"] = 51104058,
            ["GUID"] = "7FEF0384",
            ["LookAt"] = {
                [1] = "100001:n(700328)",
                [2] = "700324:n(700328)",
                },
            ["NextDialogue"] = 51104059,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700332:Talk02_End",
                [2] = "700328:Talk01_Start",
                },
            },
        [51104059] = {
            ["Content"] = "不行，今日先收摊了。我得去找找老爷子。",
            ["ContentJP"] = "駄目だ、今日はもう店じまいだ。探しに行かないと。",
            ["DialogueId"] = 51104059,
            ["GUID"] = "7FEF03AE",
            ["NextDialogue"] = 51104060,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk01_End",
                },
            },
        [51104060] = {
            ["Content"] = "赵叔，您回家等着吧，我有了消息一定知会您。",
            ["ContentJP"] = "チョウさん、家で待っててください。見つけたら知らせるんで！",
            ["DialogueId"] = 51104060,
            ["GUID"] = "7FEF03D8",
            ["NextDialogue"] = 51104061,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk02_Start",
                },
            },
        [51104061] = {
            ["Camera"] = "447.546875,110.363281,105.350098,0.000169,-6.799733,-128.996719,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎……？现在外面有那么多玄色狴犴，该不会是碰上——呸呸呸，不乌鸦嘴，不乌鸦嘴！",
            ["ContentJP"] = "えっ……？まさか、どこぞの玄狴に……いやいやいや、縁起でもない！今の聞かなかったことにして！",
            ["DialogueId"] = 51104061,
            ["FacialId"] = {
                [1] = "700324:Shock01",
                },
            ["GUID"] = "7FEF0402",
            ["LookAt"] = {
                [1] = "700332:n(100001)",
                },
            ["NextDialogue"] = 51104062,
            ["SpeakNpcId"] = 700324,
            ["TalkActionId"] = {
                [1] = "700324:Shock_Start",
                [2] = "700328:Talk02_End",
                },
            },
        [51104062] = {
            ["Camera"] = "393.902344,31.90625,149.760742,0.000111,-7.799338,-168.793396,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……老板，我们也一起去吧。这包桂花糕就算委托费了。",
            ["ContentJP"] = "{性别:……店主さん、僕たちも手伝うよ。この桂花菓子は、その前金ってことで。|……店主さん、私たちも手伝うわ。この桂花菓子は、その前金ってことで。}",
            ["DialogueId"] = 51104062,
            ["GUID"] = "7FEF042C",
            ["NextDialogue"] = 51104063,
            ["SpeakNpcId"] = 100001,
            ["TurnTo"] = {
                [1] = "700328:n(100001)",
                },
            },
        [51104063] = {
            ["Camera"] = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那可帮大忙了。我知道老爷子可能去的地方，跟我来吧。",
            ["ContentJP"] = "そりゃあありがたい。行きそうな場所に心当たりがあるんだ。ついてきてくれ。",
            ["DialogueId"] = 51104063,
            ["GUID"] = "7FEF0456",
            ["LookAt"] = {
                [1] = "700328:n(100001)",
                },
            ["SpeakNpcId"] = 700328,
            },
        [51104064] = {
            ["Content"] = "这些天煞的孽畜，娃娃不要怕，躲到爷爷身后来。",
            ["ContentJP"] = "うぬら、また現れおったか……！大丈夫だ、わしの背に隠れておれ！",
            ["DialogueId"] = 51104064,
            ["GUID"] = "7FEF0480",
            ["NextDialogue"] = 51104065,
            ["SpeakNpcId"] = 700333,
            },
        [51104065] = {
            ["Content"] = "哥，我怕……",
            ["ContentJP"] = "兄ちゃん……こわいよぉ……",
            ["DialogueId"] = 51104065,
            ["GUID"] = "7FEF04AA",
            ["NextDialogue"] = 51104066,
            ["SpeakNpcId"] = 700327,
            },
        [51104066] = {
            ["Content"] = "别怕，拿好香囊，白龙神君会保佑我们的。",
            ["ContentJP"] = "大丈夫、香袋があれば、白龍様が守ってくださるはずだ！",
            ["DialogueId"] = 51104066,
            ["GUID"] = "7FEF04D4",
            ["NextDialogue"] = 51104067,
            ["SpeakNpcId"] = 700326,
            },
        [51104067] = {
            ["Content"] = "那是……刚刚的那两个孩子！",
            ["ContentJP"] = "……あれは！さっきの子どもたち！？",
            ["DialogueId"] = 51104067,
            ["GUID"] = "7FEF04FE",
            ["SpeakNpcId"] = 100001,
            },
        [51104068] = {
            ["Content"] = "罪业伏诛！",
            ["ContentJP"] = "罪業ことごとくを、滅するべし！",
            ["DialogueId"] = 51104068,
            ["GUID"] = "7FEF0528",
            ["SpeakNpcId"] = 700325,
            },
        [51104069] = {
            ["Content"] = "是煜明！",
            ["ContentJP"] = "ユーミンだ！",
            ["DialogueId"] = 51104069,
            ["GUID"] = "7FEF0552",
            ["SpeakNpcId"] = 100001,
            },
        [51104070] = {
            ["Camera"] = "-137.351562,325.910156,238.606445,0.00011,-10.794915,-30.803417,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是你们……出手相助，感激不尽。",
            ["ContentJP"] = "助勢、感謝する。",
            ["DialogueId"] = 51104070,
            ["GUID"] = "7FEF057C",
            ["LookAt"] = {
                [1] = "700325:n(100001)",
                },
            ["NextDialogue"] = 51104071,
            ["SpeakNpcId"] = 700325,
            ["TalkActionId"] = {
                [1] = "700326:Shock_Start",
                },
            },
        [51104071] = {
            ["Camera"] = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "老爷子！怎么回事，怎么让玄色狴犴缠上了，伤着没有？",
            ["ContentJP"] = "親父！なぜ狴犴に取り囲まれて……怪我は？",
            ["DialogueId"] = 51104071,
            ["GUID"] = "7FEF05A6",
            ["LookAt"] = {
                [1] = "700328:n(700333)",
                },
            ["NextDialogue"] = 51104072,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Angry01_Start",
                },
            },
        [51104072] = {
            ["Camera"] = "222.753906,168.0625,157.84082,0.00014,-5.794309,-28.59362,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我硬朗的很，能有什么事？倒是这两个娃娃吓得不轻，幸亏我就在附近，勉强护着他们。要是再晚一点……",
            ["ContentJP"] = "心配はいらん。まだ骨は折れとらんよ。ただ、この子らは危なかった。すぐそばにおったから庇えたが、あと一歩遅ければ……",
            ["DialogueId"] = 51104072,
            ["GUID"] = "7FEF05D0",
            ["LookAt"] = {
                [1] = "700326:n(700333)",
                [2] = "700327:n(700333)",
                },
            ["NextDialogue"] = 51104073,
            ["SpeakNpcId"] = 700333,
            },
        [51104073] = {
            ["Camera"] = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们两个小子，不快点回家在这荒郊野岭的乱逛干什么？",
            ["ContentJP"] = "お前たち！どうしてこんな野辺で遊んでいる！家に帰る時刻だろう！",
            ["DialogueId"] = 51104073,
            ["GUID"] = "7FEF05FA",
            ["NextDialogue"] = 51104074,
            ["SpeakNpcId"] = 700328,
            },
        [51104074] = {
            ["Camera"] = "222.753906,168.0625,157.84082,0.00014,-5.794309,-28.59362,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你认识这两个小娃娃？",
            ["ContentJP"] = "ふむ、知り合いか？",
            ["DialogueId"] = 51104074,
            ["GUID"] = "7FEF0624",
            ["NextDialogue"] = 51104075,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700328:Angry01_End",
                },
            },
        [51104075] = {
            ["Camera"] = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "码头上刚见过面，这小兄弟俩猜谜赢了咱们家的桂花糕回去。",
            ["ContentJP"] = "港で見かけたんです。うちの謎かけで菓子を持ち帰った兄弟ですよ。",
            ["DialogueId"] = 51104075,
            ["GUID"] = "7FEF064E",
            ["NextDialogue"] = 51104076,
            ["SpeakNpcId"] = 700328,
            ["TalkActionId"] = {
                [1] = "700328:Talk01_Start",
                [2] = "700333:Talk02_Start",
                [3] = "700326:Shock_End",
                },
            },
        [51104076] = {
            ["Camera"] = "254.984375,78.167969,126.896484,0.000137,-6.39389,-21.59598,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对不起。是我不想晚归挨骂，才带着小武走这条近路……",
            ["ContentJP"] = "ごめんなさい……叱られるのが嫌で、近道を選んだら……",
            ["DialogueId"] = 51104076,
            ["GUID"] = "7FEF0678",
            ["LookAt"] = {
                [1] = "700327:n(700326)",
                [2] = "700326:n(700327)",
                },
            ["NextDialogue"] = 51104077,
            ["SpeakNpcId"] = 700326,
            ["TalkActionId"] = {
                [1] = "700326:Explain02_Start",
                },
            ["TurnTo"] = {
                [1] = "700327:n(700326)",
                },
            },
        [51104077] = {
            ["Content"] = "哥……你不用道歉，怪我贪玩，误了回家的时辰。",
            ["ContentJP"] = "違うんだ。……僕が遊びたいって言ったから、遅くなったんだ……",
            ["DialogueId"] = 51104077,
            ["GUID"] = "7FEF06A2",
            ["NextDialogue"] = 51104078,
            ["SpeakNpcId"] = 700327,
            ["TalkActionId"] = {
                [1] = "700327:Sigh_Start",
                [2] = "700326:Explain02_End",
                },
            },
        [51104078] = {
            ["Camera"] = "-137.351562,325.910156,238.606445,0.00011,-10.794915,-30.803417,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了，有事回去再说。浣儿，你先把这两个娃娃送回家去。",
            ["ContentJP"] = "よい、無事ならそれでよい。ワンよ、二人を家まで送ってやりなさい。",
            ["DialogueId"] = 51104078,
            ["GUID"] = "7FEF06CC",
            ["NextDialogue"] = 51104079,
            ["SpeakNpcId"] = 700333,
            },
        [51104079] = {
            ["Camera"] = "445.683594,-16.105469,156.394531,0.000105,-5.594867,157.996689,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，您也早点回去，回头和赵叔报个平安。多谢几位英雄出手，我先告辞了。",
            ["ContentJP"] = "わかりました。――君たち、本当にありがとう。俺は子どもたちを送ってくから、これで。",
            ["DialogueId"] = 51104079,
            ["GUID"] = "7FEF06F6",
            ["NextDialogue"] = 51104080,
            ["SpeakNpcId"] = 700328,
            },
        [51104080] = {
            ["Camera"] = "-137.351562,325.910156,238.606445,0.00011,-10.794915,-30.803417,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢过应天尉，还有这两位异国的英雄了。若不是三位出手搭救，我这把老骨头怕是保不下那两个娃娃。",
            ["ContentJP"] = "異国の客人方、そして応天尉殿。助けていただき、感謝する。もし皆がおらなんだら、子らを守り切れんかっただろう。",
            ["DialogueId"] = 51104080,
            ["GUID"] = "7FEF0720",
            ["LookAt"] = {
                [1] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104081,
            ["SpeakNpcId"] = 700333,
            ["TurnTo"] = {
                [1] = "700325:n(700333)",
                },
            },
        [51104081] = {
            ["Camera"] = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "职责所在，不必言谢。",
            ["ContentJP"] = "務めを果たしたまで。礼は不要だ。",
            ["DialogueId"] = 51104081,
            ["GUID"] = "7FEF074A",
            ["NextDialogue"] = 51104082,
            ["SpeakNpcId"] = 700325,
            ["TalkActionId"] = {
                [1] = "700325:Talk02_Start",
                },
            },
        [51104082] = {
            ["Camera"] = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……恕我妄言，权当是我这匹夫老眼昏花。这位应天尉大人，我可曾在摊前见过你……与你的弟弟？",
            ["ContentJP"] = "……思い違いかもしれんが、応天尉殿。以前、桂花菓子の屋台で見かけたことがある。弟君とご一緒ではなかったかな？",
            ["DialogueId"] = 51104082,
            ["GUID"] = "7FEF0774",
            ["NextDialogue"] = 51104083,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700325:Talk02_End",
                },
            },
        [51104083] = {
            ["Camera"] = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51104083,
            ["GUID"] = "7FEF079E",
            ["NextDialogue"] = 51104084,
            ["SpeakNpcId"] = 700325,
            ["TalkActionId"] = {
                [1] = "700325:Think_Start",
                },
            },
        [51104084] = {
            ["Content"] = "嗯。",
            ["ContentJP"] = "うん。",
            ["DialogueId"] = 51104084,
            ["GUID"] = "7FEF07C8",
            ["NextDialogue"] = 51104085,
            ["SpeakNpcId"] = 700325,
            },
        [51104085] = {
            ["Camera"] = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那不会错了，我就说应天尉大人怎么有几分面熟。你是当时那位哥哥，还有个不听话的弟弟。就好像……就好像刚才那两个娃娃一样。",
            ["ContentJP"] = "やはりそうか。どこか見覚えがあると思った。あのときの兄弟……お前さんは兄で、弟は少しやんちゃな子だった。まるで、さきほどの二人のようにな。",
            ["DialogueId"] = 51104085,
            ["GUID"] = "7FEF07F2",
            ["NextOptions"] = {
                [1] = 51104086,
                [2] = 51104087,
                },
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700325:Think_End",
                },
            },
        [51104086] = {
            ["Content"] = "原来应天尉也有亲人。",
            ["ContentJP"] = "応天尉にも家族がいたんだ？",
            ["DialogueId"] = 51104086,
            ["GUID"] = "7FEF081C",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51104088,
            },
        [51104087] = {
            ["Content"] = "不听话的弟弟……难不成是刻舟？",
            ["ContentJP"] = "やんちゃな弟って……もしかしてカシュウのこと？",
            ["DialogueId"] = 51104087,
            ["GUID"] = "7FEF0846",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 51104088,
            },
        [51104088] = {
            ["Camera"] = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并非血亲，只是师出同门罢了。",
            ["ContentJP"] = "血のつながりはない。ただ同じ師を持つ者だ。",
            ["DialogueId"] = 51104088,
            ["GUID"] = "7FEF0870",
            ["NextDialogue"] = 51104089,
            ["SpeakNpcId"] = 700325,
            },
        [51104089] = {
            ["Camera"] = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样啊……你如今成了应天尉，倒也算出人头地。你那师弟呢？我看那小娃脾气顽劣，但聪慧得很，想必如今也和你一样一表人才。",
            ["ContentJP"] = "なるほど……だが、そなたは見事に名を成した。あの弟君も才気ある子だった。きっと今ごろは、そなたに並ぶ器となっておろう。",
            ["DialogueId"] = 51104089,
            ["GUID"] = "7FEF089A",
            ["NextDialogue"] = 51104090,
            ["SpeakNpcId"] = 700333,
            },
        [51104090] = {
            ["Camera"] = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51104090,
            ["GUID"] = "7FEF08C4",
            ["NextDialogue"] = 51104091,
            ["SpeakNpcId"] = 700325,
            },
        [51104091] = {
            ["Camera"] = "139.769531,398.101562,168.59668,0.000137,-6.594056,-58.797264,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……看来是我老头子说错话咯。也罢，时光荏苒，造化弄人，又曾几回能教人如愿以偿。",
            ["ContentJP"] = "……いや、わしの思い違いかもしれん。年月は人を翻弄し、願い通りに運ぶとは限らんからな。",
            ["DialogueId"] = 51104091,
            ["GUID"] = "7FEF08EE",
            ["NextDialogue"] = 51104092,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700333:Sigh_Start",
                },
            },
        [51104092] = {
            ["Camera"] = "343.269531,125.167969,194.758789,0.000055,-10.200463,-97.399925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "老人家，野外凶险，还是早些归家吧。",
            ["ContentJP"] = "野外は危険だ。早く家に戻るがよい。",
            ["DialogueId"] = 51104092,
            ["GUID"] = "7FEF0918",
            ["NextDialogue"] = 51104093,
            ["SpeakNpcId"] = 700325,
            },
        [51104093] = {
            ["Content"] = "也是，不然浣儿又该惦记了。几位若顺路，不妨和老夫一起走走？",
            ["ContentJP"] = "うむ。ワンもまた案じておろう。……もしよければ、皆も共に参らぬか？",
            ["DialogueId"] = 51104093,
            ["GUID"] = "7FEF0942",
            ["SpeakNpcId"] = 700333,
            },
        [51104094] = {
            ["Camera"] = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "又劳烦几位了，最近这地界一直都不太平。",
            ["ContentJP"] = "また助けてもらってしまったな……このあたり、近頃ずっと騒がしくてのう。",
            ["DialogueId"] = 51104094,
            ["GUID"] = "7FEF096C",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104095,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700333:Talk01_Start",
                },
            },
        [51104095] = {
            ["Content"] = "那里曾经有片桂花林。噢，倒也算不上林，只是几棵长在一起的桂花树罢了。但是那桂花开得好，一到时节，香气隔了山头都能闻到。",
            ["ContentJP"] = "昔はあのあたりに桂花の林があった。いや、林というほどでもない、ただ数本の桂花が寄り添って咲いておっただけだ。だが、その香りは山を越えて届き、時が来れば辺り一面に甘く満ちたものだ。",
            ["DialogueId"] = 51104095,
            ["GUID"] = "7FEF0996",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104096,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700333:Talk01_End",
                },
            },
        [51104096] = {
            ["Content"] = "桂花树下啊，有个小村子。说是村子，其实也就零零散散几户人家。这边有块不大不小的田，几户人就靠它填饱肚子。",
            ["ContentJP"] = "桂の木の下には小さな村があってな。村といっても、家はまばらに数軒。小さな田畑を耕し、どうにか腹を満たす程度の暮らしよ。",
            ["DialogueId"] = 51104096,
            ["GUID"] = "7FEF09C0",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104097,
            ["SpeakNpcId"] = 700333,
            },
        [51104097] = {
            ["Content"] = "这村子人家又少，离皓京也偏远，村里的孩子们没什么娱乐活动。我就让他们摘些桂花回来，做成桂花糕给孩子们分分。顺便出几个谜语让他们猜着玩。",
            ["ContentJP"] = "人も少なく、都からも遠い。子らには遊び場もなくてな……だから摘んだ花を菓子にしてやり、なぞかけを出して楽しませたものだ。",
            ["DialogueId"] = 51104097,
            ["GUID"] = "7FEF09EA",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104098,
            ["SpeakNpcId"] = 700333,
            },
        [51104098] = {
            ["Content"] = "这谜语猜的最好的，当属……当属我的儿子。浣儿他从小机灵，我不求他出人头地，只希望他能平平安安长大，接过我这小本生意……",
            ["ContentJP"] = "その謎に一番強かったのは――わしの息子、ワンだ。利口な子でな……大きな望みなど持たずとも、無事に育ち、この菓子屋を継いでくれればそれでよかった。",
            ["DialogueId"] = 51104098,
            ["GUID"] = "7FEF0A14",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104099,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "700333:Disagree",
                },
            },
        [51104099] = {
            ["Camera"] = "-118.90625,-330.195312,98.025879,0.0002,-11.993771,63.773678,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "难道说……",
            ["ContentJP"] = "まさか……！！",
            ["DialogueId"] = 51104099,
            ["GUID"] = "7FEF0A3E",
            ["LookAt"] = {
                [1] = "700333:n(100001)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104100,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51104100] = {
            ["Camera"] = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呵呵。浣儿从小崇拜应天尉，某次执法时非要去看热闹，结果不小心卷进其中，在坏人手下丢了性命……",
            ["ContentJP"] = "そうだ。あの子は応天尉に憧れていてな。ある日、執法の場を見たいと駆け出し、巻き込まれて……帰らぬ人となった。",
            ["DialogueId"] = 51104100,
            ["GUID"] = "7FEF0A68",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104101,
            ["SpeakNpcId"] = 700333,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51104101] = {
            ["Content"] = "几十年过去了，村里的人离的离散的散，我原本的名字，也没人记得了。后来的人啊，只知道我姓李，做得一手桂花糕，干脆都叫我桂花李。",
            ["ContentJP"] = "幾十年も過ぎ、村は人も散り、名も忘れられた。残ったのは桂花のリーと呼ばれるこの老いぼれだけよ。",
            ["DialogueId"] = 51104101,
            ["GUID"] = "7FEF0A92",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104102,
            ["SpeakNpcId"] = 700333,
            },
        [51104102] = {
            ["Content"] = "我这把老骨头再不想走，孤苦伶仃地也在这过不下去，只能去码头卖卖糕点。收养了个没爹没娘的小娃娃，还把儿子的名字给了他。",
            ["ContentJP"] = "独りで居ても心は空しくてな……だから城へ出ては菓子を売り、親を失った子を一人引き取った。そしてあの子の名を継がせた。",
            ["DialogueId"] = 51104102,
            ["GUID"] = "7FEF0ABC",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104103,
            ["SpeakNpcId"] = 700333,
            },
        [51104103] = {
            ["Content"] = "明明是我自己把他当儿子养，可他真叫我爹的时候，我反而心里难受。一到这时候，我就总会回到这里走走。",
            ["ContentJP"] = "わしが父と思い育てても、呼ばれるたび胸が痛んでな……そんな時は、こうしてまたここに戻ってしまうのだ。",
            ["DialogueId"] = 51104103,
            ["GUID"] = "7FEF0AE6",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104104,
            ["SpeakNpcId"] = 700333,
            },
        [51104104] = {
            ["Content"] = "从这看下去，总会感觉那个小村子又回来了，它就在这，哪也没去。",
            ["ContentJP"] = "ここから眺めていると、不思議とあの村がまだそこにある気がしてな。",
            ["DialogueId"] = 51104104,
            ["GUID"] = "7FEF0B10",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104105,
            ["SpeakNpcId"] = 700333,
            },
        [51104105] = {
            ["Content"] = "孩子，你还记得，你第一次带着师弟来买桂花糕，我给你出的谜面吗？",
            ["ContentJP"] = "……そういえば、お前さん。初めて弟と桂花菓子を買いに来た時、わしが出した謎かけを覚えておるか？",
            ["DialogueId"] = 51104105,
            ["GUID"] = "7FEF0B3A",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104106,
            ["SpeakNpcId"] = 700333,
            },
        [51104106] = {
            ["Camera"] = "-86.242188,466.148438,64.947754,0.000178,-7.393345,-67.627014,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "风也愁，雨也愁，木樨归处秋复秋，无人共倚舟。",
            ["ContentJP"] = "風嘆きて、雨嘆く。金木犀の帰処、秋は重なり、秋に還る。ともに船倚る人もなく、ただ影一つあるのみ。",
            ["DialogueId"] = 51104106,
            ["GUID"] = "7FEF0B64",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700333:n(700325)",
                },
            ["NextDialogue"] = 51104107,
            ["SpeakNpcId"] = 700325,
            },
        [51104107] = {
            ["Camera"] = "500.710938,139.5625,82.334961,0.000169,-10.993831,-172.027054,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "记性真不错。当年你们怎么也猜不出来，那是当然。只是我老头子随口的感慨罢了，哪有什么谜底。",
            ["ContentJP"] = "おお、よく覚えておったな。だがあれはただの老いの感慨。答えなど初めから無いのだ。",
            ["DialogueId"] = 51104107,
            ["GUID"] = "7FEF0B8E",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104108,
            ["SpeakNpcId"] = 700333,
            },
        [51104108] = {
            ["Content"] = "这么多年过去，儿子没了，但我有了徒弟，朋友没了，我又认识了愿意陪我喝酒的老伙伴。可唯独那桂花旁的小村子，终究是回不去了。",
            ["ContentJP"] = "……年月は過ぎ、息子は帰らず、友も減った。だが弟子を得て、仲間を得て、酒を酌み交わす友もできた。けれど――桂の花咲くあの村だけは、もう戻らぬ。",
            ["DialogueId"] = 51104108,
            ["GUID"] = "7FEF0BB8",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104109,
            ["SpeakNpcId"] = 700333,
            },
        [51104109] = {
            ["Content"] = "你还年轻，故人尚在，归处仍存，莫要像我老头子一般……",
            ["ContentJP"] = "お前はまだ若い。故郷も、友も、すべて残っておる。どうか、わしのようにはなるな。",
            ["DialogueId"] = 51104109,
            ["GUID"] = "7FEF0BE2",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["NextDialogue"] = 51104110,
            ["SpeakNpcId"] = 700333,
            },
        [51104110] = {
            ["Content"] = "就到这吧，剩下几步路老朽自己回去也无事。多谢几位英雄出手相助了。",
            ["ContentJP"] = "もうここまででよい。残りの道は、ひとりで歩ける。皆の助太刀、まことに感謝するぞ。",
            ["DialogueId"] = 51104110,
            ["GUID"] = "7FEF0C0C",
            ["LookAt"] = {
                [1] = "100001:n(700333)",
                [2] = "700325:n(700333)",
                },
            ["Scripts"] = "MoveTo{ActorId{700333},TargetPoint{\"P51104110GuiHuaLi\"},MoveSpeed{80},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700333,
            },
        [51104111] = {
            ["Camera"] = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "煜明，没想到在这又见面了。上次在听鸦原一别后，刻舟托我带话给你……",
            ["ContentJP"] = "ユーミン、また会えた{性别:な|ね}。……カシュウから言伝を預かっているんだけど……",
            ["DialogueId"] = 51104111,
            ["GUID"] = "7FEF0C36",
            ["LookAt"] = {
                [1] = "100001:n(700325)",
                [2] = "700325:n(100001)",
                [3] = "700324:n(700325)",
                },
            ["NextDialogue"] = 51104112,
            ["SpeakNpcId"] = 100001,
            },
        [51104112] = {
            ["Camera"] = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他的心思我早已知晓，恕难遂其心愿……劳烦你们二位了。",
            ["ContentJP"] = "……あいつの想いは承知している。だが叶えることはできん。二人に手間をかけさせたな。",
            ["DialogueId"] = 51104112,
            ["GUID"] = "7FEF0C60",
            ["LookAt"] = {
                [1] = "100001:n(700325)",
                [2] = "700324:n(700325)",
                },
            ["NextDialogue"] = 51104113,
            ["SpeakNpcId"] = 700325,
            },
        [51104113] = {
            ["Camera"] = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喂喂，我说，你们明明曾经那么要好，还一起买桂花糕吃。有什么误会真的不能说开嘛？",
            ["ContentJP"] = "なにそれ！昔は菓子を分け合った仲じゃんか！何か誤解があるのなら話し合えばいいのに！",
            ["DialogueId"] = 51104113,
            ["GUID"] = "7FEF0C8A",
            ["LookAt"] = {
                [1] = "100001:n(700324)",
                [2] = "700325:n(700324)",
                },
            ["NextDialogue"] = 51104114,
            ["SpeakNpcId"] = 700324,
            ["TalkActionId"] = {
                [1] = "700324:Think_Start",
                },
            },
        [51104114] = {
            ["Camera"] = "156.148438,383.179688,54.88623,0.000159,-8.793397,-104.439034,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……有人欲归家而故园不复。更有些人，故里虽在，却终不得回。",
            ["ContentJP"] = "……帰りたいと願っても、帰る場所が消えてしまう者もいる。帰る場所はあっても、もう二度と踏み入れぬ者もいる。",
            ["DialogueId"] = 51104114,
            ["GUID"] = "7FEF0CB4",
            ["LookAt"] = {
                [1] = "100001:n(700325)",
                [2] = "700324:n(700325)",
                },
            ["NextDialogue"] = 51104115,
            ["SpeakNpcId"] = 700325,
            ["TalkActionId"] = {
                [1] = "700324:Think_End",
                },
            },
        [51104115] = {
            ["Content"] = "其中恩怨纠葛并非寥寥数语可以道明。更何况如今我需应天执法，他乃飘零中人，立场之别，已是天渊。",
            ["ContentJP"] = "その因縁は言葉で尽くせるものではない。それに、いまの俺は応天の執法者。あいつは流れ者だ。立場が違う――それだけで、もう深い溝があるのだ。",
            ["DialogueId"] = 51104115,
            ["GUID"] = "7FEF0CDE",
            ["LookAt"] = {
                [1] = "100001:n(700325)",
                [2] = "700324:n(700325)",
                },
            ["NextDialogue"] = 51104116,
            ["SpeakNpcId"] = 700325,
            },
        [51104116] = {
            ["Content"] = "多谢两位从中调解……怕是让你们失望了。",
            ["ContentJP"] = "すまぬ、せっかく取り持ってくれたが、望みには応えられん。",
            ["DialogueId"] = 51104116,
            ["GUID"] = "7FEF0D08",
            ["LookAt"] = {
                [1] = "100001:n(700325)",
                [2] = "700324:n(700325)",
                [3] = "700325:n(100001)",
                },
            ["NextDialogue"] = 51104117,
            ["SpeakNpcId"] = 700325,
            ["TalkActionId"] = {
                [1] = "700325:Talk02_Start",
                },
            },
        [51104117] = {
            ["Camera"] = "-5.03125,-308.234375,39.374512,0.000165,-6.393542,75.963158,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "白听不明白，好像很深奥的样子……不过既然你想清楚了，那我和小仆从也不多说什么了。",
            ["ContentJP"] = "……なんだかよくわからないけど。でも、あんたが決めたなら、もう言わないよ。",
            ["DialogueId"] = 51104117,
            ["GUID"] = "7FEF0D32",
            ["LookAt"] = {
                [1] = "100001:n(700324)",
                [2] = "700325:n(700324)",
                },
            ["NextDialogue"] = 51104118,
            ["SpeakNpcId"] = 700324,
            ["TalkActionId"] = {
                [1] = "700325:Talk02_End",
                },
            },
        [51104118] = {
            ["Content"] = "那我们先走了。你保重好身体，不要太拼命了。",
            ["ContentJP"] = "無理しないで、身体を大事にするんだよ。",
            ["DialogueId"] = 51104118,
            ["GUID"] = "7FEF0D5C",
            ["NextDialogue"] = 51104119,
            ["Scripts"] = "PARA{\
MoveTo{_delay{3},ActorId{100001},TargetPoint{\"P51104118Avatar\"},MoveSpeed{80},Visibility{\"Show\"}},\
MoveTo{_delay{3},ActorId{700324},TargetPoint{\"P51104118White\"},MoveSpeed{80},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 100001,
            },
        [51104119] = {
            ["Camera"] = "-1452.339844,-2423.003906,585.456543,0.000174,-7.592308,44.551308,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "师兄，山外山的大家都未曾怪你，你何必如此执拗？",
            ["ContentJP"] = "ユーミン、山外山の皆は誰ひとりあんたを責めてない。",
            ["DialogueId"] = 51104119,
            ["GUID"] = "7FEF0D86",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51104120,
            ["TurnTo"] = {
                [1] = "700325:p(90)",
                },
            },
        [51104120] = {
            ["Content"] = "罢了，今日我纵是与你大战三百回合也要带你回去！",
            ["ContentJP"] = "今日こそ、しばりつけてでも連れて帰るからな！",
            ["DialogueId"] = 51104120,
            ["GUID"] = "7FEF0DB0",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51104121,
            },
        [51104121] = {
            ["Content"] = "……此去一别，不复当年，这或许就是天意。",
            ["ContentJP"] = "……昔日には戻れぬ。それもまた定めか。",
            ["DialogueId"] = 51104121,
            ["DialoguePanelType"] = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterEast01_GuiHuaCake02.T_Guide_ChapterEast01_GuiHuaCake02'}",
            ["GUID"] = "7FEF0DDA",
            ["NextDialogue"] = 51104122,
            ["SpeakNpcId"] = 700325,
            ["TalkActionId"] = {
                [1] = "700325:Explain02_Start",
                },
            },
        [51104122] = {
            ["Content"] = "故人尚在，归处仍存吗……终究只是个愿景罢了。",
            ["ContentJP"] = "故人はまだ残れど、帰る場所は……ただ幻にすぎぬのだ。",
            ["DialogueId"] = 51104122,
            ["GUID"] = "7FEF0E04",
            ["SpeakNpcId"] = 700325,
            },
        [51104200] = {
            ["Content"] = "盘子",
            ["ContentJP"] = "お皿",
            ["DialogueId"] = 51104200,
            ["GUID"] = "7FEF1AD0",
            ["NextDialogue"] = 51104202,
            },
        [51104201] = {
            ["Content"] = "天之树",
            ["ContentJP"] = "天上樹",
            ["DialogueId"] = 51104201,
            ["GUID"] = "7FEF1AD1",
            ["NextDialogue"] = 51104202,
            },
        [51104202] = {
            ["Content"] = "感觉不太对劲……",
            ["ContentJP"] = "違う気がする……",
            ["DialogueId"] = 51104202,
            ["GUID"] = "7FEF1AD2",
            ["NextOptions"] = {
                [1] = 51104026,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51104203] = {
            ["Content"] = "百年春",
            ["ContentJP"] = "百年春",
            ["DialogueId"] = 51104203,
            ["GUID"] = "7FEF0139",
            ["NextDialogue"] = 51104205,
            },
        [51104204] = {
            ["Content"] = "沉月香",
            ["ContentJP"] = "沈月香",
            ["DialogueId"] = 51104204,
            ["GUID"] = "7FEF013A",
            ["NextDialogue"] = 51104206,
            },
        [51104205] = {
            ["Camera"] = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要不客人您再想想？",
            ["ContentJP"] = "惜しいな、もう一度考えてみるか？",
            ["DialogueId"] = 51104205,
            ["GUID"] = "7FEF013B",
            ["NextOptions"] = {
                [1] = 51104044,
                },
            ["SpeakNpcId"] = 700328,
            },
        [51104206] = {
            ["Camera"] = "68.732422,-386.160156,178.870117,0.000121,-11.199583,62.005909,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "倒是有些接近了，再想想？",
            ["ContentJP"] = "お、だいぶ近いぞ。もう少しだ。",
            ["DialogueId"] = 51104206,
            ["GUID"] = "7FEF013C",
            ["NextOptions"] = {
                [1] = 51104044,
                },
            ["SpeakNpcId"] = 700328,
            },
        [51105001] = {
            ["Content"] = "灵灵好害怕……呜呜呜……白龙神君在上，能不能让奶奶来保护我……",
            ["ContentJP"] = "ううっ……怖いよぉ……白龍様、お願いします。どうかおばあちゃん呼んできて……",
            ["DialogueId"] = 51105001,
            ["GUID"] = "7FEF1AFA",
            ["NextDialogue"] = 51105002,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Sigh_Start",
                },
            },
        [51105002] = {
            ["Content"] = "只要白龙神君答应灵灵，灵灵就承认，自己的胆子确实比芝麻粒还小。对爹娘说不怕都是吹牛的！",
            ["ContentJP"] = "嘘をついてごめんなさい！本当は怖いのに、パパとママに「全然平気」とか言っちゃってごめんなさい。",
            ["DialogueId"] = 51105002,
            ["GUID"] = "7FEF1B24",
            ["NextOptions"] = {
                [1] = 51105003,
                [2] = 51105005,
                [3] = 51105007,
                },
            ["SpeakNpcId"] = 700329,
            },
        [51105003] = {
            ["Content"] = "怕的话，直接说出来比较好。",
            ["ContentJP"] = "怖いときは、素直に言えばいい。",
            ["DialogueId"] = 51105003,
            ["GUID"] = "7FEF1B4E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51105004,
            },
        [51105004] = {
            ["Content"] = "就是、就是，灵灵以为自己的胆子要更大一些，不是故意不说的……",
            ["ContentJP"] = "ち、違うの。リンリン、全然平気だって思ってたの。わざと内緒にしてたわけじゃないの……",
            ["DialogueId"] = 51105004,
            ["GUID"] = "7FEF1B78",
            ["NextDialogue"] = 51105009,
            ["SpeakNpcId"] = 700329,
            },
        [51105005] = {
            ["Content"] = "既然有白龙神君在上，为什么还需要奶奶保护？",
            ["ContentJP"] = "おばあちゃんじゃなくて、白龍に守ってもらえばいいじゃん。",
            ["DialogueId"] = 51105005,
            ["GUID"] = "7FEF1BA2",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51105006,
            },
        [51105006] = {
            ["Content"] = "白龙神君可以保护灵灵不受伤害，但如果奶奶在，灵灵会更安心……而且白龙神君很忙很忙，不一定有空降临，帮助灵灵。",
            ["ContentJP"] = "白龍様は強いけど、やっぱりおばあちゃんがいてくれる方がホッとするの。それに白龍様はお忙しいから、いつでも来れるわけじゃないし……",
            ["DialogueId"] = 51105006,
            ["GUID"] = "7FEF1BCC",
            ["NextDialogue"] = 51105009,
            ["SpeakNpcId"] = 700329,
            },
        [51105007] = {
            ["Content"] = "白龙神君和奶奶只能有一个来保护你，你选谁？",
            ["ContentJP"] = "もし、白龍とおばあちゃんのどちらかしか来れなかったら、どっちを選ぶ？",
            ["DialogueId"] = 51105007,
            ["GUID"] = "7FEF1BF6",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51105008,
            },
        [51105008] = {
            ["Content"] = "……你怎么和那些问灵灵，更喜欢爹还是更喜欢娘的亲戚一样烦人？",
            ["ContentJP"] = "どうしてそんなこと聞くの？「パパとママ、どっちが好き？」ってしつこく聞いてくる親戚のおばちゃんみたい。",
            ["DialogueId"] = 51105008,
            ["GUID"] = "7FEF1C20",
            ["NextDialogue"] = 51105009,
            ["SpeakNpcId"] = 700329,
            },
        [51105009] = {
            ["Content"] = "唉，如果奶奶在就好了，只要奶奶在，灵灵就不用独自看家，也不用劳烦白龙神君来解决家里的怪事了……",
            ["ContentJP"] = "はぁ……おばあちゃんがいてくれたらなぁ。お留守番も怖くないし、龍神様にも迷惑をかけなくて済むのに……",
            ["DialogueId"] = 51105009,
            ["GUID"] = "7FEF1C4A",
            ["NextDialogue"] = 51105010,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Sigh_End",
                },
            },
        [51105010] = {
            ["Content"] = "出什么事了？",
            ["ContentJP"] = "どうしたの？",
            ["DialogueId"] = 51105010,
            ["GUID"] = "7FEF1C74",
            ["NextDialogue"] = 51105011,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Talk02_Start",
                },
            ["TurnTo"] = {
                [1] = "700329:n(0)",
                },
            },
        [51105011] = {
            ["Content"] = "说出来你别害怕！灵灵家里，出了好多离奇的事情！比如，书架上的书会哐当一下掉到地上，灵灵害怕，不敢靠近……",
            ["ContentJP"] = "あ、あのね……家で変なことがいっぱい起きるの！たとえば、本棚の本が急に落ちてきたりして……リンリン、怖くて近づけないし……",
            ["DialogueId"] = 51105011,
            ["GUID"] = "7FEF1C9E",
            ["NextDialogue"] = 51105012,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Think_Start",
                },
            },
        [51105012] = {
            ["Content"] = "结果，那书像长了眼睛和腿一样，追着灵灵一路跑！",
            ["ContentJP"] = "そしたら、その本がね、まるで目と足が生えたみたいに、リンリンのこと追いかけてきたんだよ！",
            ["DialogueId"] = 51105012,
            ["GUID"] = "7FEF1CC8",
            ["NextDialogue"] = 51105013,
            ["SpeakNpcId"] = 700329,
            },
        [51105013] = {
            ["Content"] = "还有还有，爹爹和娘近日不在家，窗台上却总会突然变出来一束吿苍，灵灵问了一圈，并没有谁捎花到我家来呀！",
            ["ContentJP"] = "それからね！パパもママも最近家にいないのに、窓のところにいつの間にか花束が置いてあるの！いろんな人に聞いたけど、みんな知らないって言うんだよ！",
            ["DialogueId"] = 51105013,
            ["GUID"] = "7FEF1CF2",
            ["NextDialogue"] = 51105014,
            ["SpeakNpcId"] = 700329,
            },
        [51105014] = {
            ["Content"] = "这样的怪事还有不少呢！",
            ["ContentJP"] = "それにね！",
            ["DialogueId"] = 51105014,
            ["GUID"] = "7FEF1D1C",
            ["NextDialogue"] = 51105015,
            ["SpeakNpcId"] = 700329,
            },
        [51105015] = {
            ["Content"] = "比如有一天，灵灵摔破了膝盖，半夜的时候，隐隐约约听到风吹的“呼呼”响，醒来的时候，膝盖被上了药。",
            ["ContentJP"] = "この前リンリン、うっかり膝を擦りむいちゃってね。その日の夜中に風の音がして……朝起きたら、傷口にいつの間にか薬が塗ってあったの！",
            ["DialogueId"] = 51105015,
            ["GUID"] = "7FEF1D46",
            ["NextDialogue"] = 51105016,
            ["SpeakNpcId"] = 700329,
            },
        [51105016] = {
            ["Content"] = "还有的时候，灵灵的房间里莫名其妙地进来了好几只促织娘。但灵灵一点儿都不喜欢虫子，不知道是谁的恶作剧……",
            ["ContentJP"] = "それから、リンリンの部屋に突然コオロギがいっぱい入ってきたこともあったよ！リンリン、虫が苦手なのに……誰のいたずらなんだろう……",
            ["DialogueId"] = 51105016,
            ["GUID"] = "7FEF1D70",
            ["NextDialogue"] = 51105017,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Think_End",
                },
            },
        [51105017] = {
            ["Content"] = "你的家人呢？",
            ["ContentJP"] = "他の家族は？",
            ["DialogueId"] = 51105017,
            ["GUID"] = "7FEF1D9A",
            ["NextDialogue"] = 51105018,
            ["SpeakNpcId"] = 100001,
            },
        [51105018] = {
            ["Content"] = "爹和娘都是织星客，还要一阵才能回来，至于奶奶……奶奶去白龙神君的身边，做天上的一颗星星了。",
            ["ContentJP"] = "パパとママは「星織人」だから、しばらくは帰ってこれないの。おばあちゃんは……龍神様に呼ばれて、空のお星さまになったんだって。",
            ["DialogueId"] = 51105018,
            ["GUID"] = "7FEF1DC4",
            ["NextDialogue"] = 51105019,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Explain02_Start",
                },
            },
        [51105019] = {
            ["Content"] = "作为星星的奶奶会为爹娘照亮回家的路，会在夜晚守着灵灵直到梦里，无论是在皓京还是在烟津渡，哪怕出了华胥，奶奶也会一直望着灵灵……",
            ["ContentJP"] = "だから、毎回パパとママの帰り道を照らしてくれるんだって。夜は夢の中で、リンリンのことを見守ってくれるんだ。皓京にいても、煙津渡にいても、たとえ華胥を出たとしても……ずっとリンリンを見ていてくれるんだよ……",
            ["DialogueId"] = 51105019,
            ["GUID"] = "7FEF1DEE",
            ["NextDialogue"] = 51105020,
            ["SpeakNpcId"] = 700329,
            },
        [51105020] = {
            ["Content"] = "但灵灵很舍不得奶奶。比起天上的奶奶，灵灵还是更希望奶奶陪在身边……",
            ["ContentJP"] = "でもね……やっぱりリンリン、おばあちゃんに会いたい。お空にいるより、隣にいてほしいの。",
            ["DialogueId"] = 51105020,
            ["GUID"] = "7FEF1E18",
            ["NextDialogue"] = 51105021,
            ["SpeakNpcId"] = 700329,
            },
        [51105021] = {
            ["Content"] = "（你知道，灵灵的奶奶大约是去世了。）",
            ["ContentJP"] = "（リンリンのおばあちゃんは、恐らくもう…）",
            ["DialogueId"] = 51105021,
            ["GUID"] = "7FEF1E42",
            ["NextDialogue"] = 51105022,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "0:Talk02_End",
                },
            },
        [51105022] = {
            ["Content"] = "呜呜……呜哇哇哇！",
            ["ContentJP"] = "ううっ、うわあああん！",
            ["DialogueId"] = 51105022,
            ["GUID"] = "7FEF1E6C",
            ["NextDialogue"] = 51105026,
            ["NextOptions"] = {
                [1] = 51105023,
                },
            ["RestartTag"] = 51105021,
            ["SpeakNpcId"] = 700329,
            },
        [51105023] = {
            ["Content"] = "看着大哭不止的灵灵，你想：或许守护她，是一种足以化为无由生的执念。",
            ["ContentJP"] = "泣きじゃくるリンリンを見て、あなたは思った。彼女を守ること、それはムユウセイへと変わり得るほど強い「執念」なのかもしれない。",
            ["DialogueId"] = 51105023,
            ["FailDialogue"] = 51105024,
            ["GUID"] = "7FEF1E96",
            ["ImprCheckId"] = 1078,
            ["NextDialogue"] = 51105026,
            },
        [51105024] = {
            ["Content"] = "（很遗憾，你并非不想帮她，只是一时还没什么头绪。）",
            ["ContentJP"] = "手伝ってあげたいが、手がかりが少なすぎる。",
            ["DialogueId"] = 51105024,
            ["GUID"] = "7FEF1EEA",
            ["NextDialogue"] = 51105025,
            },
        [51105025] = {
            ["Content"] = "谢谢你陪我一会，灵灵没有那么害怕了，在爹娘回来之前，灵灵会一直向奶奶和白龙神君祈祷的……",
            ["ContentJP"] = "お話ししてくれてありがとう。パパとママが帰ってくるまで、おばあちゃんと白龍様にお祈りするよ……",
            ["DialogueId"] = 51105025,
            ["GUID"] = "7FEF1F14",
            ["SpeakNpcId"] = 700329,
            },
        [51105026] = {
            ["Content"] = "我有些头绪了，或许我能帮你解决这件事。",
            ["ContentJP"] = "なんとなくだけど、わかった気がする……もしかしたら、解決できるかもしれない。",
            ["DialogueId"] = 51105026,
            ["GUID"] = "7FEF1F68",
            ["NextDialogue"] = 51105027,
            ["SpeakNpcId"] = 100001,
            },
        [51105027] = {
            ["Content"] = "诶，可你既不是奶奶，也不是白龙神君啊？",
            ["ContentJP"] = "えっ？おばあちゃんでも白龍様でもないのに？",
            ["DialogueId"] = 51105027,
            ["GUID"] = "7FEF1F92",
            ["NextOptions"] = {
                [1] = 51105028,
                [2] = 51105031,
                [3] = 51105034,
                },
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Explain02_Start",
                },
            },
        [51105028] = {
            ["Content"] = "白龙神君让我来的。",
            ["ContentJP"] = "白龍様に遣わされたから。",
            ["DialogueId"] = 51105028,
            ["GUID"] = "7FEF1FBC",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51105029,
            },
        [51105029] = {
            ["Content"] = "咳咳，是白龙神君听到了灵灵的请求，特意派本神使过来帮忙的。",
            ["ContentJP"] = "コホン、実は白龍様の命令で来たんだ。",
            ["DialogueId"] = 51105029,
            ["GUID"] = "7FEF1FE6",
            ["NextDialogue"] = 51105030,
            ["SpeakNpcId"] = 100001,
            },
        [51105030] = {
            ["Content"] = "哇，原来{性别：大哥哥|大姐姐}就是被白龙神君眷顾的厉害的人！灵灵只是在传闻里听到过，第一次看见真人呢！",
            ["ContentJP"] = "わぁ！じゃあ{性别:お兄さん|お姉さん}は白龍様に選ばれたすごい人なんだね！リンリン、聞いたことはあるけど、本物を見るのは初めて！",
            ["DialogueId"] = 51105030,
            ["GUID"] = "7FEF2010",
            ["NextDialogue"] = 51105037,
            ["SpeakNpcId"] = 700329,
            },
        [51105031] = {
            ["Content"] = "奶奶让我来的。",
            ["ContentJP"] = "おばあちゃんにお願いされたから。",
            ["DialogueId"] = 51105031,
            ["GUID"] = "7FEF203A",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51105032,
            },
        [51105032] = {
            ["Content"] = "我随着星星的指引来到了这里，或许那颗星星就是你的奶奶。",
            ["ContentJP"] = "星の光に導かれてここまで来た……きっとあの星が、君のおばあちゃんなんだと思う。",
            ["DialogueId"] = 51105032,
            ["GUID"] = "7FEF2064",
            ["NextDialogue"] = 51105033,
            ["SpeakNpcId"] = 100001,
            },
        [51105033] = {
            ["Content"] = "呜……我就知道……奶奶一直看着我，奶奶从来没有离开我……",
            ["ContentJP"] = "うう……やっぱり……おばあちゃん、ずっと見守っててくれたんだね。",
            ["DialogueId"] = 51105033,
            ["GUID"] = "7FEF208E",
            ["NextDialogue"] = 51105037,
            ["SpeakNpcId"] = 700329,
            },
        [51105034] = {
            ["Content"] = "我是狩月人。",
            ["ContentJP"] = "{性别:僕|私}は月狩り人だから。",
            ["DialogueId"] = 51105034,
            ["GUID"] = "7FEF20B8",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51105035,
            },
        [51105035] = {
            ["Content"] = "我是一名狩月人，用你们华胥的话来说，这是一种“拿人钱财，替人消灾”的工作，只要你愿意给报酬，我就可以帮你解决麻烦。",
            ["ContentJP"] = "{性别:僕|私}は月狩り人だから。君たちの言葉で例えるなら「銭を受けて厄を引く」者ってとこかな。報酬さえくれれば、君の悩みを解決してあげるよ。",
            ["DialogueId"] = 51105035,
            ["GUID"] = "7FEF20E2",
            ["NextDialogue"] = 51105036,
            ["SpeakNpcId"] = 100001,
            },
        [51105036] = {
            ["Content"] = "哦哦，灵灵明白了，就像爹娘出海要雇佣可靠的水手一样！那……灵灵愿意把攒下来的零花钱都给你。",
            ["ContentJP"] = "そっかぁ！パパとママが海に出る時に雇う船乗りさんみたいな感じかな？じゃあ、リンリンのお小遣い全部あげる！",
            ["DialogueId"] = 51105036,
            ["GUID"] = "7FEF210C",
            ["NextDialogue"] = 51105037,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Explain02_End",
                },
            },
        [51105037] = {
            ["Content"] = "那就交给你啦，灵灵的家在那个方向——",
            ["ContentJP"] = "お願いね！リンリンのおうちはあっちだよ！",
            ["DialogueId"] = 51105037,
            ["GUID"] = "7FEF2136",
            ["SpeakNpcId"] = 700329,
            },
        [51105038] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "我好像知道是怎么回事了。真相只有一个——灵灵的奶奶变成了无由生，试图引起灵灵的注意。",
            ["ContentJP"] = "なるほど、そういうことか。ムユウセイになってしまったおばあちゃんが、リンリンの気を引こうとしていたんだ。",
            ["DialogueId"] = 51105038,
            ["GUID"] = "7FEF2B62",
            ["NextDialogue"] = 51105039,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51105039] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "虽然道理很简单，但能看到无由生的人毕竟很少，被误认为闹鬼也就理所当然了。",
            ["ContentJP"] = "道理は簡単だが、ムユウセイが見える人間はほとんどいない。だから「幽霊騒ぎ」と勘違いされるのも無理はない。",
            ["DialogueId"] = 51105039,
            ["GUID"] = "7FEF2B8C",
            ["NextDialogue"] = 51105040,
            ["SpeakNpcId"] = 100001,
            },
        [51105040] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "问题是……要如何向灵灵解释，这并非闹鬼，而是无由生的执念所致呢？",
            ["ContentJP"] = "問題はどうやってリンリンに説明するか……これは幽霊ではなく、おばあちゃんの「想い」が形になったムユウセイだと。",
            ["DialogueId"] = 51105040,
            ["GUID"] = "7FEF2BB6",
            ["NextOptions"] = {
                [1] = 51105041,
                },
            ["RestartTag"] = 51105040,
            ["SpeakNpcId"] = 100001,
            },
        [51105041] = {
            ["Content"] = "你碰到过类似的问题，好像有一个人可以帮你解决这个问题。",
            ["ContentJP"] = "似たような状況に出くわしたことがある……この問題を解決できる人物が一人いるはずだ。",
            ["DialogueId"] = 51105041,
            ["FailDialogue"] = 51105042,
            ["GUID"] = "7FEF2BE0",
            ["ImprCheckId"] = 1079,
            ["NextDialogue"] = 51105044,
            },
        [51105042] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "（明明想起了什么，转眼间就忘掉了。这是一种常见现象，只是出现得不太及时。）",
            ["ContentJP"] = "何かを思い出しかけたが、次の瞬間には霧のように消えてしまった。よくあることだが、今は少し間が悪い。",
            ["DialogueId"] = 51105042,
            ["GUID"] = "7FEF2C0A",
            ["NextDialogue"] = 51105043,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51105043] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "过一会儿就能想起来了吧……",
            ["ContentJP"] = "……そのうち思い出せるよね。",
            ["DialogueId"] = 51105043,
            ["FacialId"] = {
                [1] = "100001:Unhappy01",
                },
            ["GUID"] = "7FEF2C34",
            ["SpeakNpcId"] = 100001,
            },
        [51105044] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "在虞渊时，是扶疏设法让我看见无由生。",
            ["ContentJP"] = "そういえば、<Default note=\"text:ぐえん\">虞淵</>でフーシュがムユウセイを見せてくれたことがあった{性别:な|ね}。",
            ["DialogueId"] = 51105044,
            ["GUID"] = "7FEF2C5E",
            ["NextDialogue"] = 51105045,
            ["SpeakNpcId"] = 100001,
            },
        [51105045] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "如果能让灵灵亲眼再见一眼奶奶所化的无由生，灵灵就不会再害怕，无由生也能了却执念，安然离去了。",
            ["ContentJP"] = "もしリンリンにも、ムユウセイになったおばあちゃんの姿を見せることができれば──もう怖がることはないはず。",
            ["DialogueId"] = 51105045,
            ["GUID"] = "7FEF2C88",
            ["NextDialogue"] = 51105046,
            ["SpeakNpcId"] = 100001,
            },
        [51105046] = {
            ["Camera"] = "-74.585938,-129.239258,143.611328,0.000002,-2.000057,58.197319,35.0,143.663574,false,Manual,2.8",
            ["Content"] = "去拜访一下扶疏吧。",
            ["ContentJP"] = "フーシュを訪ねよう。",
            ["DialogueId"] = 51105046,
            ["GUID"] = "7FEF2CB2",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51105047] = {
            ["Content"] = "{nickname}，又见面了。",
            ["ContentJP"] = "{nickname}、またお会いしましたね。",
            ["DialogueId"] = 51105047,
            ["GUID"] = "7FEF3BCA",
            ["NextDialogue"] = 51105048,
            ["SpeakNpcId"] = 700330,
            ["TalkActionId"] = {
                [1] = "700330:Confident_Start",
                },
            },
        [51105048] = {
            ["Content"] = "今日前来，有什么急事吗，还是身体不适，需我以枯荣之术医治？",
            ["ContentJP"] = "本日は急用ですか？それとも、お身体がすぐれないとか？枯栄の術で治して差し上げましょうか？",
            ["DialogueId"] = 51105048,
            ["GUID"] = "7FEF3BF4",
            ["NextDialogue"] = 51105049,
            ["SpeakNpcId"] = 700330,
            },
        [51105049] = {
            ["Content"] = "你将灵灵的事情告知扶疏。",
            ["ContentJP"] = "あなたはリンリンのことをフーシュに伝えた。",
            ["DialogueId"] = 51105049,
            ["GUID"] = "7FEF3C1E",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105050,
            },
        [51105050] = {
            ["Content"] = "竟是如此……这种牵挂家人的心情，我倒是十分理解。既然需要我的援手，我自然没有二话。",
            ["ContentJP"] = "……そういうことでしたか。家族を想う気持ち、その切なさ、私にもよくわかります。必要とあらば、喜んでお手伝い致しましょう。",
            ["DialogueId"] = 51105050,
            ["GUID"] = "7FEF3C48",
            ["NextDialogue"] = 51105051,
            ["SpeakNpcId"] = 700330,
            ["TalkActionId"] = {
                [1] = "700330:Confident_End",
                },
            },
        [51105051] = {
            ["Content"] = "只是……我现在有些放不下的要紧事，无法前往那女孩身边。",
            ["ContentJP"] = "ただ――あいにく今は手が離せずでして……その子のもとへ直接向かうのは少々難儀かと。",
            ["DialogueId"] = 51105051,
            ["GUID"] = "7FEF3C72",
            ["NextDialogue"] = 51105052,
            ["SpeakNpcId"] = 700330,
            },
        [51105052] = {
            ["Content"] = "但我可以在一件物品上施以祝由秘法，最好是和那无由生与女孩都有关联的东西，只要她带在身上就能看见无由生。",
            ["ContentJP"] = "けれど、その子とムユウセイ、どちらにも縁のある物があれば、それに「祝由の術」を施すことはできます。その子に身に着けさせれば、ムユウセイの姿が見えるようになりましょう。",
            ["DialogueId"] = 51105052,
            ["GUID"] = "7FEF3C9C",
            ["NextDialogue"] = 51105053,
            ["SpeakNpcId"] = 700330,
            ["TalkActionId"] = {
                [1] = "700330:Explain02_Start",
                },
            },
        [51105053] = {
            ["Content"] = "若你有头绪，就请把东西交予我施法，如何？",
            ["ContentJP"] = "思い当たる物があるなら、持ってきてください。",
            ["DialogueId"] = 51105053,
            ["GUID"] = "7FEF3CC6",
            ["NextDialogue"] = 51105054,
            ["SpeakNpcId"] = 700330,
            },
        [51105054] = {
            ["Content"] = "当然好，辛苦你了，扶疏。",
            ["ContentJP"] = "助かった。ありがとう、フーシュ。",
            ["DialogueId"] = 51105054,
            ["GUID"] = "7FEF3CF0",
            ["SpeakNpcId"] = 100001,
            },
        [51105055] = {
            ["Content"] = "这些应该够了，回去找扶疏吧。",
            ["ContentJP"] = "これで足りるよね。フーシュのところに戻ろう。",
            ["DialogueId"] = 51105055,
            ["GUID"] = "7FEF3D1A",
            ["SpeakNpcId"] = 100001,
            },
        [51105056] = {
            ["Content"] = "一路辛苦，我施法完毕后即刻给你。",
            ["ContentJP"] = "ご苦労さまでした。では、しばしお待ちを。",
            ["DialogueId"] = 51105056,
            ["GUID"] = "7FEF4C32",
            ["NextDialogue"] = 51105057,
            ["SpeakNpcId"] = 700330,
            ["TalkActionId"] = {
                [1] = "700330:Baiheng_Story_Special03_Start",
                },
            },
        [51105057] = {
            ["Content"] = "一炷香后。",
            ["ContentJP"] = "ほどなくして——",
            ["DialogueId"] = 51105057,
            ["GUID"] = "7FEF4C5C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105058,
            },
        [51105058] = {
            ["Content"] = "好了，这个法子只能维持半小时，但十分安全，不用担心。",
            ["ContentJP"] = "……できました。効き目は長くありませんが、身に危うきことはございませんので、どうかご安心を。",
            ["DialogueId"] = 51105058,
            ["GUID"] = "7FEF4C86",
            ["NextDialogue"] = 51105059,
            ["SpeakNpcId"] = 700330,
            ["TalkActionId"] = {
                [1] = "700330:Baiheng_Story_Special03_End",
                },
            },
        [51105059] = {
            ["Content"] = "麻烦你了。",
            ["ContentJP"] = "ありがとう！",
            ["DialogueId"] = 51105059,
            ["GUID"] = "7FEF4CB0",
            ["NextDialogue"] = 51105060,
            ["SpeakNpcId"] = 100001,
            },
        [51105060] = {
            ["Content"] = "那祖孙俩的思亲之心，想必一定十分急迫，快去吧。",
            ["ContentJP"] = "その祖母と孫の想いの深さ、さぞ切実でありましょう。急ぎ、向かって差し上がってくださいませ。",
            ["DialogueId"] = 51105060,
            ["GUID"] = "7FEF4CDA",
            ["SpeakNpcId"] = 700330,
            },
        [51105061] = {
            ["Camera"] = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "其实，你家并没有闹鬼，大概是无由生执念未消，所以一直留在你身边，不肯离去。",
            ["ContentJP"] = "実はね、君の家で起こってた「心霊現象」は全部、君への想いが強すぎてムユウセイになってしまった人によるものな{性别:んだ|の}。",
            ["DialogueId"] = 51105061,
            ["GUID"] = "7FEF5C9A",
            ["LookAt"] = {
                [1] = "700329:n(100001)",
                [2] = "100001:n(700329)",
                },
            ["NextDialogue"] = 51105062,
            ["Scripts"] = "SetVisibility{ActorId{700331},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 100001,
            },
        [51105062] = {
            ["Camera"] = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "！",
            ["ContentJP"] = "！",
            ["DialogueId"] = 51105062,
            ["FacialId"] = {
                [1] = "700329:Shock01",
                },
            ["GUID"] = "7FEF5CC4",
            ["NextDialogue"] = 51105063,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Shock_Start",
                },
            },
        [51105063] = {
            ["Camera"] = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "难道是奶奶！",
            ["ContentJP"] = "もしかして、おばあちゃん！？",
            ["DialogueId"] = 51105063,
            ["GUID"] = "7FEF5CEE",
            ["NextDialogue"] = 51105064,
            ["SpeakNpcId"] = 700329,
            },
        [51105064] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "灵灵每天都祈祷，希望奶奶能一直留在身边保护灵灵，原来已经实现了吗？",
            ["ContentJP"] = "毎日お祈りしてたの。おばあちゃんが、ずっとそばにいて守ってくれますようにって……それが叶ったってこと？",
            ["DialogueId"] = 51105064,
            ["GUID"] = "7FEF5D18",
            ["NextDialogue"] = 51105065,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Shock_End",
                },
            },
        [51105065] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只是灵灵自己不知道而已……奶奶真好，白龙神君第二好！",
            ["ContentJP"] = "リンリンが気づいてなかっただけなんだね……おばあちゃん、大好き！白龍様は、その次に好き！",
            ["DialogueId"] = 51105065,
            ["GUID"] = "7FEF5D42",
            ["NextDialogue"] = 51105066,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Talk02_Start",
                },
            },
        [51105066] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然再也看不见奶奶了，但灵灵可以和以前一样，陪着奶奶晒太阳，为奶奶读她看不清的报纸……对了，这次轮到灵灵去给奶奶唱摇篮曲了！",
            ["ContentJP"] = "もうおばあちゃんの姿は見えないけど……リンリン、これからもおばあちゃんと一緒に日向ぼっこして、新聞を読んであげるんだ。それから——今度はリンリンが、おばあちゃんに子守唄を歌ってあげる！",
            ["DialogueId"] = 51105066,
            ["GUID"] = "7FEF5D6C",
            ["NextOptions"] = {
                [1] = 51105067,
                [2] = 51105069,
                },
            ["SpeakNpcId"] = 700329,
            },
        [51105067] = {
            ["Content"] = "我找到了能让你看见无由生的方法，但只在半个时辰内有效。",
            ["ContentJP"] = "ムユウセイの姿を見られる方法を見つけたんだ。ただし、効果はそんな長くないけどね。",
            ["DialogueId"] = 51105067,
            ["GUID"] = "7FEF5D96",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51105068,
            },
        [51105068] = {
            ["Camera"] = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么！我和奶奶可以再见面了吗？",
            ["ContentJP"] = "えっ、本当に？おばあちゃんに、また会えるの！？",
            ["DialogueId"] = 51105068,
            ["GUID"] = "7FEF5DC0",
            ["NextDialogue"] = 51105071,
            ["SpeakNpcId"] = 700329,
            },
        [51105069] = {
            ["Content"] = "加钱，我有办法让你再见一次奶奶，但只有半个时辰。",
            ["ContentJP"] = "追加料金さえくれれば、おばあちゃんにもう一度会わせてあげるよ。ただし、効果は1時間しかもたないけどね。",
            ["DialogueId"] = 51105069,
            ["GUID"] = "7FEF5DEA",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51105070,
            },
        [51105070] = {
            ["Camera"] = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "灵灵的零花钱全部给你！{性别：大哥哥|大姐姐}，这些够吗……？",
            ["ContentJP"] = "リンリンのお小遣い全部あげる！これで……足りる？",
            ["DialogueId"] = 51105070,
            ["FacialId"] = {
                [1] = "700329:Shy",
                },
            ["GUID"] = "7FEF5E14",
            ["NextDialogue"] = 51105071,
            ["SpeakNpcId"] = 700329,
            },
        [51105071] = {
            ["Camera"] = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "拿着这个就可以看到无由生了。",
            ["ContentJP"] = "これを持っていれば、ムユウセイに会えるよ。",
            ["DialogueId"] = 51105071,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "7FEF5E3E",
            ["NextDialogue"] = 51105072,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                },
            },
        [51105072] = {
            ["Content"] = "灵灵接过花束，紧张地闭上了眼睛，过了好一会才慢慢睁开。",
            ["ContentJP"] = "リンリンは花束を受け取り、緊張した様子で目を閉じた。そして、深呼吸をした後、ゆっくりと目を開けた。",
            ["DialogueId"] = 51105072,
            ["GUID"] = "7FEF5E68",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105073,
            ["TalkActionId"] = {
                [1] = "700329:Talk02_End",
                },
            },
        [51105073] = {
            ["Camera"] = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……？",
            ["ContentJP"] = "……？",
            ["DialogueId"] = 51105073,
            ["GUID"] = "7FEF5E92",
            ["NextDialogue"] = 51105074,
            ["SpeakNpcId"] = 700329,
            },
        [51105074] = {
            ["Camera"] = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "灵灵怎么什么都没看到？这里是华胥，说谎的话，会有狴犴来抓你的！灵灵可以不计较，但也不想看见你被揍，你要不快跑吧……",
            ["ContentJP"] = "あれ、なんにも見えないよ？……嘘ついたら、狴犴に捕まっちゃうよ！まぁ、リンリンは許してあげるけど。あなたがケガするのは見たくないから、はやく逃げたほうがいいよ……",
            ["DialogueId"] = 51105074,
            ["GUID"] = "7FEF5EBC",
            ["NextDialogue"] = 51105075,
            ["SpeakNpcId"] = 700329,
            },
        [51105075] = {
            ["Camera"] = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果无由生对你有执念，就一定不会离得太远。灵灵要不要试着呼唤她呢？",
            ["ContentJP"] = "ムユウセイが君に未練を抱いているなら、きっと近くにいるはず。呼びかけてみれば、来てくれると思う。",
            ["DialogueId"] = 51105075,
            ["GUID"] = "7FEF5EE6",
            ["NextDialogue"] = 51105076,
            ["SpeakNpcId"] = 100001,
            },
        [51105076] = {
            ["Camera"] = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那灵灵试试……",
            ["ContentJP"] = "うーん、やってみる。",
            ["DialogueId"] = 51105076,
            ["GUID"] = "7FEF5F10",
            ["NextDialogue"] = 51105077,
            ["SpeakNpcId"] = 700329,
            },
        [51105077] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "奶奶，我在这里！我好想你呀——所以可不可以让我见见你——",
            ["ContentJP"] = "おばあちゃん、聞こえる……？私、ここにいるよ……ずっと会いたかった……もう一度だけ、会わせて！",
            ["DialogueId"] = 51105077,
            ["GUID"] = "7FEF5F3A",
            ["LookAt"] = {
                [1] = "700329:n(700331)",
                },
            ["NextDialogue"] = 51105078,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Talk02_Start",
                },
            },
        [51105078] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "奶——奶——",
            ["ContentJP"] = "おばーちゃん！！",
            ["DialogueId"] = 51105078,
            ["GUID"] = "7FEF5F64",
            ["LookAt"] = {
                [1] = "700329:n(100001)",
                },
            ["NextDialogue"] = 51105079,
            ["SpeakNpcId"] = 700329,
            },
        [51105079] = {
            ["Camera"] = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "萍萍，你什么时候回来的？",
            ["ContentJP"] = "レンレン、いつ戻ってきたんだい？",
            ["DialogueId"] = 51105079,
            ["GUID"] = "7FEF5F8E",
            ["LookAt"] = {
                [1] = "100001:n(700331)",
                },
            ["NextDialogue"] = 51105080,
            ["Scripts"] = "SetVisibility{ActorId{700331},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 700331,
            ["TalkActionId"] = {
                [1] = "700329:Talk02_End",
                },
            ["TurnTo"] = {
                [1] = "700329:n(700331)",
                },
            },
        [51105080] = {
            ["Camera"] = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我、我等你好久了……萍萍，早上了，我们去找吿苍来插瓶吧。",
            ["ContentJP"] = "ずぅっと……待ってたんだよ。いい朝ね。さぁ、\
