            ["DialogueId"] = 51105114,
            ["GUID"] = "7FEF6E28",
            ["NextDialogue"] = 51105115,
            ["SpeakNpcId"] = 700331,
            },
        [51105115] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是呀，前几天只是和爷爷捉迷藏！现在爷爷找到我了，我当然要理爷爷，以后我会在这里住很久很久……",
            ["ContentJP"] = "うん！ずっとかくれんぼしてたんだよ！でも、見つかっちゃったからおしまい！私、これからはずっとずーっと、おじいちゃんと一緒にいるね！",
            ["DialogueId"] = 51105115,
            ["GUID"] = "7FEF6E52",
            ["NextDialogue"] = 51105116,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Talk02_Start",
                },
            },
        [51105116] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "爷爷可以一直看见我！",
            ["ContentJP"] = "もうどこにも行かないよ！",
            ["DialogueId"] = 51105116,
            ["GUID"] = "7FEF6E7C",
            ["NextDialogue"] = 51105117,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Talk02_End",
                },
            },
        [51105117] = {
            ["Camera"] = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是嘛，真好啊……真好啊……我等到了……",
            ["ContentJP"] = "そうか……そうか……ああ、やっと会えた……",
            ["DialogueId"] = 51105117,
            ["GUID"] = "7FEF6EA6",
            ["NextDialogue"] = 51105118,
            ["SpeakNpcId"] = 700331,
            },
        [51105118] = {
            ["Camera"] = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢你……谢谢你们……",
            ["ContentJP"] = "ありがとう……ありがとう……",
            ["DialogueId"] = 51105118,
            ["GUID"] = "7FEF6ED0",
            ["NextOptions"] = {
                [1] = 51105119,
                [2] = 51105121,
                [3] = 51105123,
                },
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{700331},AnimationId{\"Wuyou_Disappear01\"},Duration{1.5}},\
SetVisibility{ActorId{700331},Visibility{\"Hide\"}}\
}",
            ["SpeakNpcId"] = 700331,
            },
        [51105119] = {
            ["Content"] = "你不是害怕促织娘吗？",
            ["ContentJP"] = "コオロギさんが怖いんじゃなかったの？",
            ["DialogueId"] = 51105119,
            ["GUID"] = "7FEF6EFA",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51105120,
            },
        [51105120] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "灵灵是很害怕虫子，它有好多会乱动的腿，拿在手上刺挠挠的……但是想到这是太爷爷和奶奶的共同回忆，灵灵好像也没有那么害怕了。",
            ["ContentJP"] = "うん、だって足がいっぱいあるし、もぞもぞ動くし……でも、ひいおじいちゃんとおばあちゃんの思い出なんだって思ったら、不思議と大丈夫な気がしてきたの。",
            ["DialogueId"] = 51105120,
            ["GUID"] = "7FEF6F24",
            ["NextDialogue"] = 51105126,
            ["SpeakNpcId"] = 700329,
            ["TurnTo"] = {
                [1] = "700329:n(100001)",
                },
            },
        [51105121] = {
            ["Content"] = "冒充萍萍算说谎吗？",
            ["ContentJP"] = "レンレンのフリをするのって、嘘をついたことになるのかな？",
            ["DialogueId"] = 51105121,
            ["GUID"] = "7FEF6F4E",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51105122,
            },
        [51105122] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我可没说我是萍萍，是太爷爷自己误会了！灵灵从来不做违反大风九章的事情！",
            ["ContentJP"] = "自分のこと、レンレンだって言ってないもん。ひいおじいちゃんが勝手に誤解しただけだから、セーフだよ！",
            ["DialogueId"] = 51105122,
            ["GUID"] = "7FEF6F78",
            ["NextDialogue"] = 51105126,
            ["SpeakNpcId"] = 700329,
            ["TurnTo"] = {
                [1] = "700329:n(100001)",
                },
            },
        [51105123] = {
            ["Content"] = "太爷爷和奶奶都不在了，灵灵会感到寂寞吗？",
            ["ContentJP"] = "ひいおじいちゃんとおばあちゃんがいなくなって、さみしくない？",
            ["DialogueId"] = 51105123,
            ["GUID"] = "7FEF6FA2",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51105124,
            },
        [51105124] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不会哦，灵灵现在心里暖洋洋的。就算太爷爷和奶奶走了，他们的思念也会化作另外一种方式守护着灵灵吧。",
            ["ContentJP"] = "ぜんぜん！むしろ、心がぽかぽかしてるよ。ひいおじいちゃんたちはもういないけど、彼らの想いが別の形になって、リンリンを守ってくれるって信じてるから！",
            ["DialogueId"] = 51105124,
            ["GUID"] = "7FEF6FCC",
            ["NextDialogue"] = 51105125,
            ["SpeakNpcId"] = 700329,
            },
        [51105125] = {
            ["Camera"] = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "而且，他们现在一定已经在天上见面了吧！",
            ["ContentJP"] = "それに、きっとお空の上で見守っててくれるはず！",
            ["DialogueId"] = 51105125,
            ["GUID"] = "7FEF6FF6",
            ["NextDialogue"] = 51105126,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Confident_Start",
                },
            },
        [51105126] = {
            ["Camera"] = "-702.90625,168.117188,149.791992,0.000007,-3.799948,-12.6027,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "给！这些都是灵灵的零花钱！",
            ["ContentJP"] = "はい、これリンリンのお小遣い！",
            ["DialogueId"] = 51105126,
            ["GUID"] = "7FEF7020",
            ["NextDialogue"] = 51105127,
            ["SpeakNpcId"] = 700329,
            },
        [51105127] = {
            ["Camera"] = "-702.90625,168.117188,149.791992,0.000007,-3.799948,-12.6027,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“银货两讫”，咳咳，爹娘总是把这句话挂在嘴上。这可是织星客的优良传统哦！",
            ["ContentJP"] = "「現銀一丁、手渡し一番」――ゴホン、パパとママがよく言ってたの。星織人の座右の銘ってやつ！",
            ["DialogueId"] = 51105127,
            ["FacialId"] = {
                [1] = "700329:Smile01",
                },
            ["GUID"] = "7FEF704A",
            ["NextDialogue"] = 51105128,
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Confident_Start",
                },
            },
        [51105128] = {
            ["Camera"] = "-1365.160156,-105.44873,321.923828,0.000059,-6.199885,0.00011,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对灵灵来说，这段经历是无价之宝，所以灵灵愿意把自己身上的所有都给你！希望{性别：大哥哥|大姐姐}不要觉得少！",
            ["ContentJP"] = "リンリンにとって、この思い出はね、なによりもキラキラしてる宝物なの！だから……リンリンの持ってるもの、ぜんぶあげる……！これしかないけど……受け取ってくれる？",
            ["DialogueId"] = 51105128,
            ["GUID"] = "7FEF7074",
            ["SpeakNpcId"] = 700329,
            ["TalkActionId"] = {
                [1] = "700329:Confident_End",
                },
            },
        [51105129] = {
            ["Content"] = "要不要去采些吿苍来插瓶呢？",
            ["ContentJP"] = "告蒼の花、積みに行く？",
            ["DialogueId"] = 51105129,
            ["GUID"] = "7FEF709E",
            ["SpeakNpcId"] = 700361,
            },
        [51105201] = {
            ["Content"] = "一年一度的银烛狂欢节结束了，一切似乎都回复平静。水仙平原也理应恢复到一如既往的喧嚣气氛。",
            ["ContentJP"] = "年に一度の「銀燭祭り」は幕を閉じ、街にはいつもの賑わいが戻る——はずだった。",
            ["DialogueId"] = 51105201,
            ["GUID"] = "7FEFBF0A",
            ["NextDialogue"] = 51105202,
            },
        [51105202] = {
            ["Content"] = "但事实却并非如此……一连串的意外给本该人人尽兴的狂欢蒙上阴影。",
            ["ContentJP"] = "しかし、一連の騒動が、浮かれた空気に影を落とす。",
            ["DialogueId"] = 51105202,
            ["GUID"] = "7FEFBF34",
            ["NextDialogue"] = 51105203,
            },
        [51105203] = {
            ["Content"] = "于是，一件略带喧闹的小事在狂欢结束后的某天，悄然发生。",
            ["ContentJP"] = "そしてある日、そんな余韻の中で——小さな騒ぎが、静かに始まろうとしていた。",
            ["DialogueId"] = 51105203,
            ["GUID"] = "7FEFBF5E",
            },
        [51105204] = {
            ["Camera"] = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
            ["Content"] = "……唉，没什么动力啊，总感觉没玩够。",
            ["ContentJP"] = "……はあ、いまいち気が乗らないな。なんだか、遊びきった気がしなくてさ。",
            ["DialogueId"] = 51105204,
            ["GUID"] = "7FEFBF88",
            ["NextDialogue"] = 51105205,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Talk01_Start",
                },
            },
        [51105205] = {
            ["Camera"] = "391.339111,-304.583008,188.128906,0.00004,-11.199583,155.19725,35.0,305.677551,false,Manual,2.8",
            ["Content"] = "银烛狂欢就这么收场，真没意思，我一点灵感都没有了。",
            ["ContentJP"] = "あんな終わり方じゃあね。せっかくのインスピレーションも、煙みたいに消えてしまったよ。",
            ["DialogueId"] = 51105205,
            ["GUID"] = "7FEFBFB2",
            ["LookAt"] = {
                [1] = "700350:n(700349)",
                [2] = "700349:n(700350)",
                },
            ["NextDialogue"] = 51105206,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700350:Explain01_Start",
                [2] = "700349:Talk01_End",
                },
            },
        [51105206] = {
            ["Camera"] = "240.266602,24.936523,161.671875,0.000056,-2.399227,52.196819,35.0,204.573959,false,Manual,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51105206,
            ["FacialId"] = {
                [1] = "200003:Syouganai01",
                },
            ["GUID"] = "7FEFBFDC",
            ["NextDialogue"] = 51105207,
            ["SpeakNpcId"] = 200003,
            },
        [51105207] = {
            ["Camera"] = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
            ["Content"] = "怎么回事，大家都一副无精打采的样子。按照以往来说，卡米拉应该开始让大家别瘫在座位上影响生意了。",
            ["ContentJP"] = "んん？どうしたの、みんなして覇気がないよ？いつもなら、カミラの「ぐだぐだしてたらお店に迷惑よ」って声が聞こえてるはずじゃ？",
            ["DialogueId"] = 51105207,
            ["FacialId"] = {
                [1] = "700352:Doubt01",
                },
            ["GUID"] = "7FEFC006",
            ["LookAt"] = {
                [1] = "700352:n(700350)",
                [2] = "700349:n(700352)",
                [3] = "700350:n(700352)",
                },
            ["NextDialogue"] = 51105208,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                },
            },
        [51105208] = {
            ["Camera"] = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
            ["Content"] = "结果就连卡米拉也懒得说话。",
            ["ContentJP"] = "……カミラまで黙り込んでるし。",
            ["DialogueId"] = 51105208,
            ["GUID"] = "7FEFC030",
            ["NextDialogue"] = 51105209,
            ["SpeakNpcId"] = 700352,
            },
        [51105209] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "啊！我知道了，一定是银烛狂欢大家玩得太累了，所以需要休息一段时间。",
            ["ContentJP"] = "あっ、わかった！お祭りではしゃぎすぎて、疲れちゃったんだね、みんな！今はお休みタイムってとこ？",
            ["DialogueId"] = 51105209,
            ["FacialId"] = {
                [1] = "700352:Confident01",
                },
            ["GUID"] = "7FEFC05A",
            ["LookAt"] = {
                [1] = "700352:n(700349)",
                },
            ["NextDialogue"] = 51105210,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                },
            },
        [51105210] = {
            ["Camera"] = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
            ["Content"] = "不是的，并且恰恰相反，是因为今年的银烛狂欢由于剧院发生的意外，没有最后的收尾就匆忙结束了。",
            ["ContentJP"] = "むしろ逆だよ。劇場での騒ぎで、今年の祭りは終わり方がアレだっただろ？",
            ["DialogueId"] = 51105210,
            ["GUID"] = "7FEFC084",
            ["LookAt"] = {
                [1] = "700349:n(700352)",
                },
            ["NextDialogue"] = 51105211,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Disagree",
                },
            },
        [51105211] = {
            ["Camera"] = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
            ["Content"] = "就总觉得……提不起劲啊，狂欢的氛围开始没多久，就戛然而止了。这比一开始没有开始狂欢还要难受。",
            ["ContentJP"] = "熱が入りかけたところで打ち切られた、そんな感じでさ。やる気が霧散するあの感覚……最初から何もなかったほうが、まだマシかもしれない。",
            ["DialogueId"] = 51105211,
            ["GUID"] = "7FEFC0AE",
            ["NextDialogue"] = 51105212,
            ["SpeakNpcId"] = 700349,
            },
        [51105212] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "原来如此，也不是不能理解，就像很多时候我想要帮助别人，帮到一半才发现事情已经解决了一样，就是会很泄气！",
            ["ContentJP"] = "なるほど、確かに……誰かの力になろうとして、動き出した途端に「もう大丈夫」って言われる、あの脱力感。私もよくあるなぁ。",
            ["DialogueId"] = 51105212,
            ["FacialId"] = {
                [1] = "700352:Think02",
                },
            ["GUID"] = "7FEFC0D8",
            ["NextDialogue"] = 51105213,
            ["SpeakNpcId"] = 700352,
            },
        [51105213] = {
            ["Camera"] = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
            ["Content"] = "没错！就好像是最终消失了的梦中灵感、打到一半但是没有打出来的喷嚏……甚至我都想不出第三个合适的比喻来形容。",
            ["ContentJP"] = "そうそう！夢の中で手にしたはずのひらめきが、目覚めた瞬間に消えてる、あの感じだ。あるいは……出そうで出ないくしゃみ！くそ、もう一個くらい例え出したいのに、出てこない！",
            ["DialogueId"] = 51105213,
            ["GUID"] = "7FEFC102",
            ["LookAt"] = {
                [1] = "700350:n(700352)",
                },
            ["NextDialogue"] = 51105214,
            ["SpeakNpcId"] = 700350,
            },
        [51105214] = {
            ["Camera"] = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
            ["Content"] = "总之就是，没有生机！",
            ["ContentJP"] = "とにかく、気分が上がらないんだ！",
            ["DialogueId"] = 51105214,
            ["GUID"] = "7FEFC12C",
            ["NextDialogue"] = 51105215,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700350:Explain01_End",
                },
            },
        [51105215] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "听起来有些严重……",
            ["ContentJP"] = "うーん……思ったより深刻だね……",
            ["DialogueId"] = 51105215,
            ["FacialId"] = {
                [1] = "700352:Sad01",
                },
            ["GUID"] = "7FEFC156",
            ["LookAt"] = {
                [1] = "700352:n(700350)",
                },
            ["NextDialogue"] = 51105216,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                },
            },
        [51105216] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "不行，我得想想办法，找人一起来帮帮忙，否则大家变不回之前正常的样子啦。",
            ["ContentJP"] = "でもこのままじゃだめだよ。この調子だと、いつまでも元に戻れない。",
            ["DialogueId"] = 51105216,
            ["GUID"] = "7FEFC180",
            ["LookAt"] = {
                [1] = "700352:n(700352)",
                },
            ["NextDialogue"] = 51105217,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                },
            },
        [51105217] = {
            ["Camera"] = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
            ["Content"] = "该找谁呢……哦！她们，找她们准没错。毕竟她们一直以来都情绪稳定，不会受任何外界影响。",
            ["ContentJP"] = "誰かに相談してみよう……やっぱりあの三人しか思いつかないや！いつもどんな時もブレないからね！",
            ["DialogueId"] = 51105217,
            ["FacialId"] = {
                [1] = "700352:None",
                },
            ["GUID"] = "7FEFC1AA",
            ["NextDialogue"] = 51105218,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Bai_Think2Confident",
                },
            },
        [51105218] = {
            ["Camera"] = "-310.544434,-605.483398,200.802734,0.000083,-9.19898,40.997597,35.0,588.773376,false,Manual,2.8",
            ["Content"] = "我只要问问她们是怎样不受外界影响，保持工作热情的，就一定能借助她们的心得，让整个冰湖城重新打起精神来。",
            ["ContentJP"] = "あの人たちなら、きっと外の出来事に振り回されずに働ける秘訣を知ってるはず。そのコツを教えてもらえたら……アイスレイクのみんなの元気を取り戻せるはず！",
            ["DialogueId"] = 51105218,
            ["GUID"] = "7FEFC1D4",
            ["SpeakNpcId"] = 700352,
            },
        [51105301] = {
            ["Camera"] = "457.37326,-586.730225,248.960373,0.000032,-15.000139,121.598587,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "三位前辈，如何让冰湖城焕发生机，就拜托你们了！",
            ["ContentJP"] = "先輩方、アイスレイクを盛り上げたいんだ。力を貸して！",
            ["DialogueId"] = 51105301,
            ["GUID"] = "7FEFCF72",
            ["NextDialogue"] = 51105302,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"},RelatedRegionId{\"210101\"}}",
            ["SpeakNpcId"] = 700352,
            },
        [51105302] = {
            ["Camera"] = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "喔，虽然老朽只懂如何锻造，但是看到白这么热情，确实不好推辞啊。",
            ["ContentJP"] = "おお……この老いぼれにできるのは鍛冶ぐらいだが、そこまで言われちゃ断れんのう。",
            ["DialogueId"] = 51105302,
            ["FacialId"] = {
                [1] = "700353:Happy02",
                },
            ["GUID"] = "7FEFCF9C",
            ["NextDialogue"] = 51105303,
            ["SpeakNpcId"] = 700353,
            },
        [51105303] = {
            ["Camera"] = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "虽然我一直为大家在休息时提供饮品和补给，但如果所有人一直都在休息的话，那也是不对的。",
            ["ContentJP"] = "私の仕事は、みんなの休憩を支えること。でも、誰もがずっと休んでばかりじゃ、意味がないわ。",
            ["DialogueId"] = 51105303,
            ["GUID"] = "7FEFCFC6",
            ["NextDialogue"] = 51105304,
            ["SpeakNpcId"] = 700354,
            },
        [51105304] = {
            ["Camera"] = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯嗯，白这份心意很好，冰湖城在我的记录里一直是北方的都市，要是大家都一直提不起劲，我就要把记录变成北方的睡城啦。",
            ["ContentJP"] = "うんうん、スノウの気持ちは、よくわかるよ。この町は「北の希望都市」って私の記録にも書いてあるんだ。だけど今のみんなを見てたら、「北のぐうすか町」って訂正しなきゃいけなくなっちゃう。",
            ["DialogueId"] = 51105304,
            ["GUID"] = "7FEFCFF0",
            ["NextDialogue"] = 51105305,
            ["SpeakNpcId"] = 700355,
            },
        [51105305] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对吧，我也觉得，所以呀，让我们一起来想想办法，让大家都振作起来吧。",
            ["ContentJP"] = "でしょう？だから、みんなで何か方法を考えて……街に活気を取り戻そうよ！",
            ["DialogueId"] = 51105305,
            ["GUID"] = "7FEFD01A",
            ["NextDialogue"] = 51105306,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Talk02_Start",
                },
            },
        [51105306] = {
            ["Camera"] = "135.03241,-10.31543,93.88092,0.000073,-4.399932,146.59407,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "依老朽之见啊，方法很简单——",
            ["ContentJP"] = "私から見れば……大したことはない――",
            ["DialogueId"] = 51105306,
            ["FacialId"] = {
                [1] = "700353:Happy01",
                },
            ["GUID"] = "7FEFD044",
            ["NextDialogue"] = 51105307,
            ["SpeakNpcId"] = 700353,
            },
        [51105307] = {
            ["Camera"] = "130.178741,-15.803711,93.827461,0.000077,-0.999905,121.994286,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没有其他的方法了，那就是——",
            ["ContentJP"] = "やっぱりアレしか方法はないわ――",
            ["DialogueId"] = 51105307,
            ["GUID"] = "7FEFD06E",
            ["NextDialogue"] = 51105308,
            ["SpeakNpcId"] = 700354,
            ["TalkActionId"] = {
                [1] = "700352:Talk02_End",
                },
            },
        [51105308] = {
            ["Camera"] = "132.125397,17.031494,91.702133,0.000075,-2.599946,-177.40564,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是啊，我一下子就想到了——",
            ["ContentJP"] = "うんうん、私もアレしかないと思う！",
            ["DialogueId"] = 51105308,
            ["GUID"] = "7FEFD098",
            ["NextDialogue"] = 51105309,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Confident_Start",
                },
            },
        [51105309] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是什么呢！",
            ["ContentJP"] = "なになに！？",
            ["DialogueId"] = 51105309,
            ["GUID"] = "7FEFD0C2",
            ["NextDialogue"] = 51105310,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_Start",
                },
            },
        [51105310] = {
            ["Camera"] = "618.50708,-678.68042,180.93396,0.000092,-5.799923,127.191681,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "锻造！\
经商！\
冒险！",
            ["ContentJP"] = "鍛冶だ！ 商売よ！ 冒険だよ！",
            ["DialogueId"] = 51105310,
            ["FacialId"] = {
                [1] = "700353:Smile02",
                },
            ["GUID"] = "7FEFD0EC",
            ["NextDialogue"] = 51105311,
            ["SpeakNpcName"] = "UI_CMName_Name_SanRenTongShi",
            },
        [51105311] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这不是完全不一样嘛！！！",
            ["ContentJP"] = "ぜんぜん噛みあってないじゃんか！！",
            ["DialogueId"] = 51105311,
            ["FacialId"] = {
                [1] = "700352:Unhappy01",
                },
            ["GUID"] = "7FEFD116",
            ["NextDialogue"] = 51105312,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_End",
                },
            },
        [51105312] = {
            ["Camera"] = "429.908936,-169.867676,216.608871,0.000088,-20.19973,151.389633,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并且与其说是方法，不如说是三位前辈各自擅长的事情！",
            ["ContentJP"] = "しかもどれも、自分たちの得意分野だし！？",
            ["DialogueId"] = 51105312,
            ["GUID"] = "7FEFD140",
            ["NextDialogue"] = 51105313,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_Start",
                },
            },
        [51105313] = {
            ["Camera"] = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦？这确实是出乎我的意料之外。",
            ["ContentJP"] = "おやまぁ、てっきり同じことを思ってたが。",
            ["DialogueId"] = 51105313,
            ["FacialId"] = {
                [1] = "700353:Shock01",
                },
            ["GUID"] = "7FEFD16A",
            ["NextDialogue"] = 51105314,
            ["SpeakNpcId"] = 700353,
            },
        [51105314] = {
            ["Camera"] = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我还以为你们俩和我想的完全一样。",
            ["ContentJP"] = "こちらのセリフだよ。",
            ["DialogueId"] = 51105314,
            ["GUID"] = "7FEFD194",
            ["LookAt"] = {
                [1] = "700354:n(700353)",
                },
            ["NextDialogue"] = 51105315,
            ["SpeakNpcId"] = 700355,
            },
        [51105315] = {
            ["Camera"] = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……嗯，原来你们不来卖东西是因为真的觉得经商不是最重要的，有点失望。",
            ["ContentJP"] = "……なるほど。商売を最優先にしてるの、私だけってことね。ちょっと残念。",
            ["DialogueId"] = 51105315,
            ["GUID"] = "7FEFD1BE",
            ["LookAt"] = {
                [1] = "700355:n(700353)",
                },
            ["NextDialogue"] = 51105316,
            ["SpeakNpcId"] = 700354,
            },
        [51105316] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停，停一下三位前辈。这样吧，既然你们各自都觉得自己在干的事情能够让人振奋精神，那，那我来挨个试一遍好了。",
            ["ContentJP"] = "ストップストップ、ちょっと待って！三人とも、自分のやってることが一番相手を元気にさせられるって思ってるんだよね？だったらさ――全部試してみればいいんじゃない？",
            ["DialogueId"] = 51105316,
            ["GUID"] = "7FEFD1E8",
            ["LookAt"] = {
                [1] = "700354:n(700352)",
                [2] = "700355:n(700352)",
                },
            ["NextDialogue"] = 51105317,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_End",
                },
            },
        [51105317] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，那么就从我这里开始吧，和老朽一起挥动铁锤，一定会打起精神的。",
            ["ContentJP"] = "ふむ、よかろう。ではまずは、私から。一緒にハンマーを振ってみなさい。きっと気合いも湧いてくるぞい！",
            ["DialogueId"] = 51105317,
            ["FacialId"] = {
                [1] = "700353:Confident02",
                },
            ["GUID"] = "7FEFD212",
            ["NextDialogue"] = 51105318,
            ["SpeakNpcId"] = 700353,
            },
        [51105318] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，铁匠前辈，我之前没有干过这种活，你教一教我。",
            ["ContentJP"] = "よーし、じゃあ鍛冶屋さんから！こういうの初めてだから、やり方教えて！",
            ["DialogueId"] = 51105318,
            ["FacialId"] = {
                [1] = "700353:CM_Idle",
                },
            ["GUID"] = "7FEFD23C",
            ["NextDialogue"] = 51105319,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:AgreeHead",
                },
            },
        [51105319] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "简单的简单的，拿起铁锤，深吸一口气，砸——",
            ["ContentJP"] = "簡単じゃよ。ハンマーを握って、息を吸って――打つ！",
            ["DialogueId"] = 51105319,
            ["FacialId"] = {
                [1] = "700353:Smile02",
                },
            ["GUID"] = "7FEFD266",
            ["NextDialogue"] = 51105320,
            ["SpeakNpcId"] = 700353,
            },
        [51105320] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一边砸，一遍想着别人看到你锻造出的东西满意地露出笑容，就会产生动力。",
            ["ContentJP"] = "それだけじゃ。叩きながら、自分が作ったモノを誰かが笑顔で受け取るのを想像してごらん。それだけで、力が湧いてくる。",
            ["DialogueId"] = 51105320,
            ["GUID"] = "7FEFD290",
            ["NextDialogue"] = 51105321,
            ["SpeakNpcId"] = 700353,
            },
        [51105321] = {
            ["Camera"] = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并且呀，有节奏地敲击铁锤，看着火花迸出，每锤一次都会涌现出成就感。",
            ["ContentJP"] = "それにな、カン、カンとリズムよく打ちつけて、火花が散るのを見る。その一発ごとに、胸の奥が「やった！」って叫ぶんじゃよ。",
            ["DialogueId"] = 51105321,
            ["GUID"] = "7FEFD2BA",
            ["NextDialogue"] = 51105322,
            ["SpeakNpcId"] = 700353,
            },
        [51105322] = {
            ["Camera"] = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……好的，我明白了，总的来说就是，挥舞铁锤会让人感到振奋。",
            ["ContentJP"] = "なるほどね、つまり――ハンマー振り回すのって、めちゃくちゃ元気出るってことだよね？",
            ["DialogueId"] = 51105322,
            ["FacialId"] = {
                [1] = "700352:Happy02",
                },
            ["GUID"] = "7FEFD2E4",
            ["NextDialogue"] = 51105323,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialConfident_Start",
                },
            },
        [51105323] = {
            ["Camera"] = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么让白来试一试……呜哇，好重……",
            ["ContentJP"] = "よっしゃ、スノウも――って、重っ！",
            ["DialogueId"] = 51105323,
            ["FacialId"] = {
                [1] = "700352:Shock02",
                },
            ["GUID"] = "7FEFD30E",
            ["NextDialogue"] = 51105324,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/hammer\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialConfident_End",
                },
            },
        [51105324] = {
            ["Content"] = "白举起铁锤，用力挥舞了起来。",
            ["ContentJP"] = "スノウは大きな鉄槌を持ち上げ、思いきり振り下ろした。",
            ["DialogueId"] = 51105324,
            ["GUID"] = "7FEFD338",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105325,
            },
        [51105325] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，确实抡起大锤来会让人感觉力量从身体里涌出……",
            ["ContentJP"] = "ふんぬっ……おおっ、なんか、体の奥から力が湧いてくる感じするー！",
            ["DialogueId"] = 51105325,
            ["FacialId"] = {
                [1] = "700352:Confident02",
                },
            ["GUID"] = "7FEFD362",
            ["NextDialogue"] = 51105326,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_Start",
                },
            },
        [51105326] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "要不就号召大家一起来打铁锻造吧，一定能感到快乐的！",
            ["ContentJP"] = "みんなで打ち鍛え体験とかやったら、案外テンション上がるんじゃない！？",
            ["DialogueId"] = 51105326,
            ["GUID"] = "7FEFD38C",
            ["NextDialogue"] = 51105327,
            ["SpeakNpcId"] = 700352,
            },
        [51105327] = {
            ["Content"] = "随着白挥舞锤子的时间越来越长，她的速度也逐渐变慢……",
            ["ContentJP"] = "だが、時間が経つにつれて、スノウの動きはだんだん鈍くなっていき……",
            ["DialogueId"] = 51105327,
            ["GUID"] = "7FEFD3B6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51105328,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_End",
                },
            },
        [51105328] = {
            ["Camera"] = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好累……我挥不动了……",
            ["ContentJP"] = "はあ……はあ……無理……もう腕が動かない……",
            ["DialogueId"] = 51105328,
            ["FacialId"] = {
                [1] = "700352:Sad03",
                },
            ["GUID"] = "7FEFD3E0",
            ["NextDialogue"] = 51105329,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:BaiTX_Story_Cry_Start",
                },
            },
        [51105329] = {
            ["Camera"] = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不行，我累坏了，我必须立刻睡觉……晚安……",
            ["ContentJP"] = "ダメ、めっちゃ眠い……おやすみなさーい……",
            ["DialogueId"] = 51105329,
            ["GUID"] = "7FEFD40A",
            ["NextDialogue"] = 51105330,
            ["SpeakNpcId"] = 700352,
            },
        [51105330] = {
            ["Camera"] = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "并且我得出一个结论，这种方法不太适合……让大家振奋精神。",
            ["ContentJP"] = "うん、わかった。これはこれで悪くないけど――全員に元気出させるには、ちょっと違う、かも……",
            ["DialogueId"] = 51105330,
            ["FacialId"] = {
                [1] = "700352:Syouganai01",
                },
            ["GUID"] = "7FEFD434",
            ["NextDialogue"] = 51105331,
            ["SpeakNpcId"] = 700352,
            },
        [51105331] = {
            ["Camera"] = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以啊，这样是不行的，过度地劳动只会让大家变得更加疲惫。",
            ["ContentJP"] = "だから言ったでしょう？やりすぎは逆効果よ。身体を酷使すれば、心もすり減るの。",
            ["DialogueId"] = 51105331,
            ["GUID"] = "7FEFD45E",
            ["NextDialogue"] = 51105332,
            ["SpeakNpcId"] = 700354,
            },
        [51105332] = {
            ["Camera"] = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "本来狂欢节就是为了让大家休息才设立的，敲敲打打的声音只适合作为狂欢节的背景音乐。",
            ["ContentJP"] = "そもそもお祭りって、休むためのイベントなんだから。騒々しいのは、せいぜい賑やかしのBGMで十分よ。",
            ["DialogueId"] = 51105332,
            ["GUID"] = "7FEFD488",
            ["NextDialogue"] = 51105333,
            ["SpeakNpcId"] = 700354,
            },
        [51105333] = {
            ["Camera"] = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是这样吗？哎呀，能做背景音乐也很好啦，那么接下来该你啦。让我们见识见识什么叫做经商能够带来活力。",
            ["ContentJP"] = "ほう、それはそれで悪くないのう。BGM職人ってのも、粋じゃないか。さあ次は――君の番じゃ。「商売の力」ってやつ、見せてみなさい！",
            ["DialogueId"] = 51105333,
            ["FacialId"] = {
                [1] = "700353:Happy01",
                },
            ["GUID"] = "7FEFD4B2",
            ["NextDialogue"] = 51105334,
            ["SpeakNpcId"] = 700353,
            },
        [51105334] = {
            ["Camera"] = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，我看你是一直待在屋内打铁，根本不知道外面发生过什么。",
            ["ContentJP"] = "ふふん、ようやく私の出番ね。外の空気も知らずに火を焚いてるだけじゃ、見えてこないものもあるのよ。",
            ["DialogueId"] = 51105334,
            ["GUID"] = "7FEFD4DC",
            ["NextDialogue"] = 51105335,
            ["SpeakNpcId"] = 700354,
            },
        [51105335] = {
            ["Camera"] = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "跟我来吧，顺便把睡着的白给一起抬出去。",
            ["ContentJP"] = "さ、ついてきて。ついでに寝ちゃったスノウも運んでちょうだい。",
            ["DialogueId"] = 51105335,
            ["GUID"] = "7FEFD506",
            ["SpeakNpcId"] = 700354,
            },
        [51105401] = {
            ["Camera"] = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？我怎么在广场上啦？难道是因为我挥舞锤子的力气太大，把自己甩飞出去啦？",
            ["ContentJP"] = "……ん？ ここ、広場？なんで？もしかして私、ハンマー振りすぎて、勢い余って吹っ飛ばされたとか！？",
            ["DialogueId"] = 51105401,
            ["FacialId"] = {
                [1] = "700352:Shock02",
                },
            ["GUID"] = "7FEFDFDA",
            ["NextDialogue"] = 51105402,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialLook01_Start",
                },
            ["TurnTo"] = {
                [1] = "700360:n(700352)",
                },
            },
        [51105402] = {
            ["Camera"] = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你们没事吧？有没有受伤？",
            ["ContentJP"] = "ってことは……みんな大丈夫？ケガしてない！？",
            ["DialogueId"] = 51105402,
            ["GUID"] = "7FEFE004",
            ["LookAt"] = {
                [1] = "700352:n(700355)",
                },
            ["NextDialogue"] = 51105403,
            ["SpeakNpcId"] = 700352,
            },
        [51105403] = {
            ["Camera"] = "-158.35083,-438.890656,112.984375,0.000041,-9.199888,76.798775,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不是啦，只是刚刚你太用力，累坏了而已。",
            ["ContentJP"] = "ふふ、そんな大げさな。力みすぎて、疲れて眠っちゃっただけよ。",
            ["DialogueId"] = 51105403,
            ["GUID"] = "7FEFE02E",
            ["LookAt"] = {
                [1] = "700354:n(700352)",
                },
            ["NextDialogue"] = 51105404,
            ["SpeakNpcId"] = 700354,
            ["TurnTo"] = {
                [1] = "700352:n(700354)",
                },
            },
        [51105404] = {
            ["Camera"] = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "原来是这样……不过我刚刚要干什么来着。",
            ["ContentJP"] = "あー、そっか……でも私、なんか大事なことしようとしてたような……？",
            ["DialogueId"] = 51105404,
            ["FacialId"] = {
                [1] = "700352:CM_Idle",
                },
            ["GUID"] = "7FEFE058",
            ["NextDialogue"] = 51105405,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                },
            },
        [51105405] = {
            ["Camera"] = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是打算用经商来让冰湖城重新焕发生机哦。",
            ["ContentJP"] = "商売でアイスレイクに活力を取り戻そうって話だったでしょ？",
            ["DialogueId"] = 51105405,
            ["GUID"] = "7FEFE082",
            ["NextDialogue"] = 51105406,
            ["SpeakNpcId"] = 700354,
            },
        [51105406] = {
            ["Camera"] = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦对，想起来了，那么到底要怎么做，侍者前辈，请教教我！",
            ["ContentJP"] = "あっ、そうだ！思い出した！ねえ、教えて教えて。何をすればいいの！？",
            ["DialogueId"] = 51105406,
            ["GUID"] = "7FEFE0AC",
            ["NextDialogue"] = 51105407,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_Start",
                },
            },
        [51105407] = {
            ["Camera"] = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔，说起来其实也简单，就是制造商机，制造悬念，制造潮流，只要吊足大家的胃口，就能够唤出大家的热情。",
            ["ContentJP"] = "んー、やること自体はシンプルよ。商機をつくる、流行をつくる、そして――なにより「欲しい！」って思わせること。",
            ["DialogueId"] = 51105407,
            ["GUID"] = "7FEFE0D6",
            ["NextDialogue"] = 51105408,
            ["SpeakNpcId"] = 700354,
            },
        [51105408] = {
            ["Camera"] = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "而一旦想要拥有，想购买的情绪充斥着心胸，那么人们就会为此好好工作。这样就能让人们焕发活力。",
            ["ContentJP"] = "人ってね、何かを手に入れたいって思うと、不思議と元気になるの。その気持ちが、明日を頑張るエネルギーになるのよ。",
            ["DialogueId"] = 51105408,
            ["GUID"] = "7FEFE100",
            ["NextDialogue"] = 51105409,
            ["SpeakNpcId"] = 700354,
            ["TalkActionId"] = {
                [1] = "700352:Excited01_End",
                },
            },
        [51105409] = {
            ["Camera"] = "-698.29834,-1511.247803,548.52002,0.000096,-3.199643,-79.40123,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "话不多说，比如我这里就有准备好的银烛狂欢终场限定饮品，每购买一杯就能获得一个印章，",
            ["ContentJP"] = "たとえば、「銀燭祭り終幕限定ドリンク」！一杯買うごとにスタンプが一つ。",
            ["DialogueId"] = 51105409,
            ["GUID"] = "7FEFE12A",
            ["NextDialogue"] = 51105410,
            ["SpeakNpcId"] = 700354,
            },
        [51105410] = {
            ["Camera"] = "-60.891846,1.497742,78.666992,0.0,-1.200105,-41.399494,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "集齐五枚印章后可以获得限定款银色烛台一个，烛台总共有五种颜色款式还有斑斓之黑隐藏款。",
            ["ContentJP"] = "スタンプ五つで限定の「銀の燭台」がもらえるの！しかも五色のラインナップに、隠しレアカラー「カラフルブラック」まで用意してるわ！",
            ["DialogueId"] = 51105410,
            ["FacialId"] = {
                [1] = "700352:Shock02",
                },
            ["GUID"] = "7FEFE154",
            ["NextDialogue"] = 51105411,
            ["SpeakNpcId"] = 700354,
            },
        [51105411] = {
            ["Camera"] = "-211.238281,484.548462,133.915771,0.000002,-6.80019,-72.198151,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来吧，白，吆喝起来！只要来买的人足够多，那么冰湖城就一定会重新焕发活力的！",
            ["ContentJP"] = "さあスノウ、張り切って呼び込みなさい。お客さんが集まれば、街も自然と活気づくわ！",
            ["DialogueId"] = 51105411,
            ["GUID"] = "7FEFE17E",
            ["NextDialogue"] = 51105412,
            ["SpeakNpcId"] = 700354,
            },
        [51105412] = {
            ["Camera"] = "-165.009277,12.943481,86.168457,0.000005,-5.000094,-19.198158,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "噢！好耶！只要能够让冰湖城重新焕发生机我什么都会做的！",
            ["ContentJP"] = "おっしゃー！私に任せといて！アイスレイクの元気、取り戻すためならなんだってやるよっ！",
            ["DialogueId"] = 51105412,
            ["FacialId"] = {
                [1] = "700352:Happy02",
                },
            ["GUID"] = "7FEFE1A8",
            ["NextDialogue"] = 51105413,
            ["SpeakNpcId"] = 700352,
            },
        [51105413] = {
            ["Camera"] = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "银烛狂欢终场限定饮品！购入获得限定款银色烛台！还有隐藏款！",
            ["ContentJP"] = "銀燭祭り終幕限定ドリンク〜はいかがですか！一杯でスタンプが1つもらえるよ〜！スタンプ集めて、銀の燭台ゲット！レアカラーもあるよ〜！",
            ["DialogueId"] = 51105413,
            ["GUID"] = "7FEFE1D2",
            ["LookAt"] = {
                [1] = "700352:n(700360)",
                },
            ["NextDialogue"] = 51105414,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:BaiTX_Story_Shout_Start",
                },
            },
        [51105414] = {
            ["Camera"] = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只卖一天，今天卖完等到明年，快来看呀！",
            ["ContentJP"] = "本日限定！売り切れ御免！今を逃すと1年待ちだよ〜！",
            ["DialogueId"] = 51105414,
            ["GUID"] = "7FEFE1FC",
            ["LookAt"] = {
                [1] = "700352:n(700355)",
                },
            ["NextDialogue"] = 51105415,
            ["SpeakNpcId"] = 700352,
            },
        [51105415] = {
            ["Camera"] = "-32.104248,371.151123,518.605469,0.000011,-3.999909,-83.395515,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "侍者皎皎与白的吆喝在广场上交织，不少人驻足观看，但随即摇摇头离去。",
            ["ContentJP"] = "広場に響き渡るスノウとバーテンダーの呼び込み。足を止める人もいたが、しばらくして首を横に振り、また歩き出してしまった。",
            ["DialogueId"] = 51105415,
            ["GUID"] = "7FEFE226",
            ["NextDialogue"] = 51105416,
            },
        [51105416] = {
            ["Camera"] = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔……会不会是吆喝的声音不够大……",
            ["ContentJP"] = "……うぅ、もしかして声が小さかった！？もっと叫ばなきゃダメ！？",
            ["DialogueId"] = 51105416,
            ["FacialId"] = {
                [1] = "700352:Sad03",
                },
            ["GUID"] = "7FEFE250",
            ["NextDialogue"] = 51105417,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:BaiTX_Story_Shout_End",
                },
            },
        [51105417] = {
            ["Camera"] = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不是的……只是听了感觉有一些内心疲惫。",
            ["ContentJP"] = "違うよ……声は十分だ。でも、なんだか心が疲れちゃって……",
            ["DialogueId"] = 51105417,
            ["FacialId"] = {
                [1] = "700352:CM_Idle",
                },
            ["GUID"] = "7FEFE27A",
            ["NextDialogue"] = 51105418,
            ["SpeakNpcId"] = 700360,
            ["TurnTo"] = {
                [1] = "700352:n(700360);700355:n(700360)",
                },
            },
        [51105418] = {
            ["Camera"] = "-154.719238,-781.528137,203.725098,0.000044,-10.999541,77.402351,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？为什么？我们准备的饮料也很可口，烛台也很精致，为什么会疲惫呢？",
            ["ContentJP"] = "えっ？なんで？ドリンクも美味しいし、燭台もかわいくて凝ってるのに。",
            ["DialogueId"] = 51105418,
            ["FacialId"] = {
                [1] = "700352:Shock01",
                },
            ["GUID"] = "7FEFE2A4",
            ["LookAt"] = {
                [1] = "700354:n(700360)",
                },
            ["NextDialogue"] = 51105419,
            ["SpeakNpcId"] = 700354,
            ["TalkActionId"] = {
                [1] = "700352:Shock_Start",
                },
            },
        [51105419] = {
            ["Camera"] = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "因为我家里已经有七八个烛台啦、还有十几个银烛狂欢纪念牌、二十多个银烛狂欢纪念徽章。",
            ["ContentJP"] = "家にね、もう銀の燭台が七、八個あるんだ……記念プレートも十何枚、バッジなんて二十個以上ある。",
            ["DialogueId"] = 51105419,
            ["GUID"] = "7FEFE2CE",
            ["NextDialogue"] = 51105420,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Sigh_Start",
                },
            },
        [51105420] = {
            ["Camera"] = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "银烛狂欢期间，城里的商家就和约好了一样，每一家都在推出什么银烛狂欢特制纪念品，偏偏每一家都做得很好。",
            ["ContentJP"] = "お祭りの間、どのお店も「限定品」ってこぞって出してきてね。しかも、どれもよく出来てるから、ついつい買っちゃうのよ……",
            ["DialogueId"] = 51105420,
            ["FacialId"] = {
                [1] = "700352:CM_Idle",
                },
            ["GUID"] = "7FEFE2F8",
            ["NextDialogue"] = 51105421,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700352:Shock_End",
                },
            },
        [51105421] = {
            ["Camera"] = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "大家一不留神，就买了好多……所以现在都是钱包空空，后悔花了很多钱的状态。",
            ["ContentJP"] = "気づけば財布は空っぽ。後悔しか残らない。",
            ["DialogueId"] = 51105421,
            ["GUID"] = "7FEFE322",
            ["NextDialogue"] = 51105422,
            ["SpeakNpcId"] = 700360,
            },
        [51105422] = {
            ["Camera"] = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以在银烛狂欢结束的时候看到你们还在这样叫卖，反而让我感到后悔和痛苦……",
            ["ContentJP"] = "そんな状態でまた呼び込み聞かされると、ちょっとツラくて……",
            ["DialogueId"] = 51105422,
            ["GUID"] = "7FEFE34C",
            ["NextDialogue"] = 51105423,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Sigh_End",
                },
            },
        [51105423] = {
            ["Camera"] = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对不起，我……我不是故意的。",
            ["ContentJP"] = "……ごめん……そんなつもりじゃ……",
            ["DialogueId"] = 51105423,
            ["GUID"] = "7FEFE376",
            ["NextDialogue"] = 51105424,
            ["SpeakNpcId"] = 700352,
            },
        [51105424] = {
            ["Camera"] = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没有责怪你的意思啦，相反，我很感激你们能为了大家重新打起精神来能尝试各种方法。",
            ["ContentJP"] = "いや、責めるつもりはないよ。むしろ、元気を取り戻そうって頑張ってくれて、すごくうれしい。",
            ["DialogueId"] = 51105424,
            ["FacialId"] = {
                [1] = "700360:Smile01",
                },
            ["GUID"] = "7FEFE3A0",
            ["NextDialogue"] = 51105425,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Explain01_Start",
                },
            },
        [51105425] = {
            ["Camera"] = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "请继续加油，我相信你们一定可以的！",
            ["ContentJP"] = "きっと、うまくいくよ――応援してる！",
            ["DialogueId"] = 51105425,
            ["GUID"] = "7FEFE3CA",
            ["NextDialogue"] = 51105426,
            ["SpeakNpcId"] = 700360,
            ["TalkActionId"] = {
                [1] = "700360:Explain01_End",
                [2] = "700352:BaiTX_Story_RubForehead_End",
                },
            },
        [51105426] = {
            ["Camera"] = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好的！那么探险家前辈，最后的希望，靠你了！",
            ["ContentJP"] = "ありがとう……！よーし、次こそラストチャンス！冒険家さん、お願い！",
            ["DialogueId"] = 51105426,
            ["GUID"] = "7FEFE3F4",
            ["NextDialogue"] = 51105427,
            ["SpeakNpcId"] = 700352,
            ["TurnTo"] = {
                [1] = "700352:n(700355);700355:n(700352)",
                },
            },
        [51105427] = {
            ["Camera"] = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，确实也该是我出场的时候了。",
            ["ContentJP"] = "うん、ついに私の出番みたいだね。",
            ["DialogueId"] = 51105427,
            ["GUID"] = "7FEFE41E",
            ["LookAt"] = {
                [1] = "700354:n(700355)",
                },
            ["NextDialogue"] = 51105428,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Agree",
                },
            },
        [51105428] = {
            ["Camera"] = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那么我的答案是冒险——",
            ["ContentJP"] = "私が思うに……答えは「冒険」だ。",
            ["DialogueId"] = 51105428,
            ["GUID"] = "7FEFE448",
            ["NextDialogue"] = 51105429,
            ["SpeakNpcId"] = 700355,
            },
        [51105429] = {
            ["Camera"] = "122.499512,-108.44696,348.161377,0.000066,2.39976,-124.394104,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "银烛狂欢，大家都在冰湖城内狂欢，那么我有充分的理由认为大家是在城里憋坏了，是城墙让大家的心情压抑。",
            ["ContentJP"] = "だってさ、お祭りのあいだ、みんなアイスレイクの中ばっかりにいたわけでしょ？そりゃ気が滅入るってもんだよ。城壁に囲まれてちゃ、心まで縮こまっちゃう。",
            ["DialogueId"] = 51105429,
            ["GUID"] = "7FEFE472",
            ["NextDialogue"] = 51105430,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain02_Start",
                },
            },
        [51105430] = {
            ["Camera"] = "-5.647949,-37.965942,63.306885,0.000058,-1.398379,-172.39415,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，如果大家都能去冰湖城外，与自然亲近，呼吸新鲜空气，心情就一定会变好的！",
            ["ContentJP"] = "だからこそ！ 外へ出よう！自然の風に当たって、新鮮な空気を胸いっぱい吸い込めば、きっと気分も晴れるはず！",
            ["DialogueId"] = 51105430,
            ["GUID"] = "7FEFE49C",
            ["NextDialogue"] = 51105431,
            ["SpeakNpcId"] = 700355,
            },
        [51105431] = {
            ["Camera"] = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哦！听起来很有道理。那么，是不是找到泪湖边上风景最好的地方，让大家去那里欣赏风景就可以了！",
            ["ContentJP"] = "おお〜！それ、めっちゃ納得！じゃあさ、ダクリ湖のあたりとか、景色のいい場所探して、みんなでそこに行くのはどう！？",
            ["DialogueId"] = 51105431,
            ["GUID"] = "7FEFE4C6",
            ["NextDialogue"] = 51105432,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:RaiseHand_Start",
                },
            },
        [51105432] = {
            ["Camera"] = "-87.131836,-425.705322,92.41748,0.000067,-8.799558,88.407211,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不错，白很聪明嘛，已经完全知道我想要做什么了。",
            ["ContentJP"] = "うんうん、スノウ、飲み込みが早いね。もう何をすればいいか、しっかりわかってる。",
            ["DialogueId"] = 51105432,
            ["GUID"] = "7FEFE4F0",
            ["NextDialogue"] = 51105433,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain02_End",
                [2] = "700352:RaiseHand_End",
                },
            },
        [51105433] = {
            ["Camera"] = "-123.174316,-60.997009,67.639648,0.000072,4.20047,5.206679,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，那我们出发！",
            ["ContentJP"] = "よっしゃ〜！じゃあ、今すぐ出発だー！！",
            ["DialogueId"] = 51105433,
            ["FacialId"] = {
                [1] = "700352:Happy02",
                },
            ["GUID"] = "7FEFE51A",
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_Start",
                },
            },
        [51105501] = {
            ["Camera"] = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，就是这里了，视野开阔没有拘束，适合让大家来放松身心。",
            ["ContentJP"] = "うん、ここだね！ひらけてて、風も気持ちいいし――みんなの気持ちもきっとほぐれるはず！",
            ["DialogueId"] = 51105501,
            ["GUID"] = "7FEFF042",
            ["NextDialogue"] = 51105502,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700356:Avoid",
                [2] = "700357:Avoid",
                },
            },
        [51105502] = {
            ["Camera"] = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没错，每当我来到这里，都觉得内心被治愈了一样，所以我相信其他人也一定能重新打起精神来的。",
            ["ContentJP"] = "そう、私もここに来るたび、心がふっと軽くなるの。だから、きっと他のみんなにも効くと思ってたんだけど……",
            ["DialogueId"] = 51105502,
            ["GUID"] = "7FEFF06C",
            ["NextDialogue"] = 51105503,
            ["SpeakNpcId"] = 700355,
            },
        [51105503] = {
            ["Camera"] = "-157.613281,-2017.939453,386.613281,0.000007,-21.999744,146.197006,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "救命啊，救命——",
            ["ContentJP"] = "たすけてぇぇっ！誰か――！",
            ["DialogueId"] = 51105503,
            ["GUID"] = "7FEFF096",
            ["NextDialogue"] = 51105504,
            ["SpeakNpcName"] = "UI_CMName_Name_FuJinChuanLai",
            },
        [51105504] = {
            ["Camera"] = "-292.320312,132.621094,98.302734,0.000022,-9.399808,-35.402294,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好像是有人在呼救，我们过去看看。",
            ["ContentJP"] = "今の、聞こえた？誰かの叫び声だ。行ってみよう！",
            ["DialogueId"] = 51105504,
            ["GUID"] = "7FEFF0C0",
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain01_Start",
                },
            },
        [51105505] = {
            ["Camera"] = "468.472656,-386.455078,184.522461,0.000007,-11.999959,151.198257,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "谢谢，谢谢救了我们。",
            ["ContentJP"] = "ありがとう……助けてくれて……",
            ["DialogueId"] = 51105505,
            ["FacialId"] = {
                [1] = "700356:Sad01",
                [2] = "700357:Sad01",
                },
            ["GUID"] = "7FEFF0EA",
            ["LookAt"] = {
                [1] = "700356:n(700352);700357:n(700352);700352:n(700356);700355:n(700356)",
                },
            ["NextDialogue"] = 51105506,
            ["SpeakNpcId"] = 700356,
            ["TalkActionId"] = {
                [1] = "700356:Explain01_Start",
                },
            },
        [51105506] = {
            ["Camera"] = "145.941406,-168.082031,122.435547,0.000021,-0.999502,157.595932,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "如果不是你们的话，我们恐怕就回不去冰湖城了……呜呜呜。",
            ["ContentJP"] = "もしあのままだったら……あたしたち、帰れなかったかもしれない……うぅ……",
            ["DialogueId"] = 51105506,
            ["GUID"] = "7FEFF114",
            ["NextDialogue"] = 51105507,
            ["SpeakNpcId"] = 700357,
            ["TalkActionId"] = {
                [1] = "700357:Sigh_Start",
                },
            },
        [51105507] = {
            ["Camera"] = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没事了，你们已经安全啦！不过，为什么你们会在这里？",
            ["ContentJP"] = "もう大丈夫！私たちがついてるよ！でもさ、なんでこんなところに？",
            ["DialogueId"] = 51105507,
            ["GUID"] = "7FEFF13E",
            ["NextDialogue"] = 51105508,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Confident_Start",
                },
            },
        [51105508] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，都怪我。我和妹妹本来一直在雾区生活，爸爸妈妈管得很严，没有让我们出过城。",
            ["ContentJP"] = "……僕が悪いんだ。僕と妹はずっと霧の街で暮らしてたんだけど、両親が厳しくて、一度も城の外に出たことがなくてさ。",
            ["DialogueId"] = 51105508,
            ["GUID"] = "7FEFF168",
            ["NextDialogue"] = 51105509,
            ["SpeakNpcId"] = 700356,
            },
        [51105509] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以我们就想着趁着银烛狂欢期间，卫兵们也都放松去参加狂欢了，到城外看一看。",
            ["ContentJP"] = "だから、銀燭祭りの間なら、衛兵たちもお祭りに夢中で気がゆるんでると思って……ちょっとだけ外の世界を見てみようって。",
            ["DialogueId"] = 51105509,
            ["GUID"] = "7FEFF192",
            ["NextDialogue"] = 51105510,
            ["SpeakNpcId"] = 700356,
            },
        [51105510] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "结果一过了桥就遇见了秽兽，我们为了避免被发现，只能躲着它们，越躲越远……",
            ["ContentJP"] = "でも、橋を渡ったら穢獣に出くわして……気づかれないように逃げてたら、いつのまにか遠くまで来ちゃって……",
            ["DialogueId"] = 51105510,
            ["GUID"] = "7FEFF1BC",
            ["NextDialogue"] = 51105511,
            ["SpeakNpcId"] = 700356,
            ["TalkActionId"] = {
                [1] = "700357:Sigh_End",
                },
            },
        [51105511] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最后还是被它们围住了，如果不是你们的话……",
            ["ContentJP"] = "最後は囲まれて……",
            ["DialogueId"] = 51105511,
            ["GUID"] = "7FEFF1E6",
            ["NextDialogue"] = 51105512,
            ["SpeakNpcId"] = 700356,
            ["TalkActionId"] = {
                [1] = "700356:Explain01_End",
                },
            },
        [51105512] = {
            ["Camera"] = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哥哥，是我不好，我不应该闹着要出城，我们回去吧。我再也不要离开冰湖城了……",
            ["ContentJP"] = "お兄ちゃん、ごめんなさい……あたしが「外に行きたい」なんてわがまま言ったから……もう、もう絶対に城から出たりしない……",
            ["DialogueId"] = 51105512,
            ["GUID"] = "7FEFF210",
            ["LookAt"] = {
                [1] = "700357:n(700356)",
                },
            ["NextDialogue"] = 51105513,
            ["SpeakNpcId"] = 700357,
            ["TalkActionId"] = {
                [1] = "700357:Explain02_Start",
                },
            },
        [51105513] = {
            ["Camera"] = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是哦，对于大部分人来说，城墙之外的世界还是太危险了……",
            ["ContentJP"] = "うぅ……そうだよね。一般人には、城の外の世界って、まだまだ危なすぎるよね……",
            ["DialogueId"] = 51105513,
            ["GUID"] = "7FEFF23A",
            ["LookAt"] = {
                [1] = "700357:n(700352)",
                },
            ["NextDialogue"] = 51105514,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700357:Explain02_End",
                [2] = "700352:Think_Start",
                },
            },
        [51105514] = {
            ["Camera"] = "-51.9375,-57.070312,124.332031,0.000017,-6.39975,-57.802399,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是我欠考虑了，对远方的渴望虽然能够唤起热情，但并不适合每一个人。走吧，我们回去。",
            ["ContentJP"] = "……私の読みが甘かった。冒険が誰にとっても素晴らしいとは限らない。街へ戻ろう。",
            ["DialogueId"] = 51105514,
            ["GUID"] = "7FEFF264",
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                [2] = "700355:Agree",
                },
            },
        [51105515] = {
            ["Content"] = "（一阵有一些激烈但不那么激烈的打斗声）",
            ["ContentJP"] = "（激しく戦い合う音が響き渡った。あまり激しくないけど。）",
            ["DialogueId"] = 51105515,
            ["GUID"] = "7FEFF28E",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/fight\"},PlayAs2D{true}}",
            },
        [51105601] = {
            ["Camera"] = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，连探险家前辈的方法也没有成功……",
            ["ContentJP"] = "結局、どの方法もダメだったなぁ……",
            ["DialogueId"] = 51105601,
            ["GUID"] = "7FF000AA",
            ["LookAt"] = {
                [1] = "700352:n(700355);700355:n(700352)",
                },
            ["NextDialogue"] = 51105602,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_Start",
                },
            ["TurnTo"] = {
                [1] = "700355:n(700352)",
                },
            },
        [51105602] = {
            ["Camera"] = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "到底应该怎么做呢？",
            ["ContentJP"] = "どうしよう……",
            ["DialogueId"] = 51105602,
            ["GUID"] = "7FF000D4",
            ["NextDialogue"] = 51105603,
            ["SpeakNpcId"] = 700352,
            },
        [51105603] = {
            ["Camera"] = "93.466797,-74.861328,96.041504,0.000017,-5.799609,141.39859,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "别丧气，至少我们的尝试确实帮助了别人。",
            ["ContentJP"] = "落ち込まないで。私たちの行動は、ちゃんと誰かの役に立ったんだよ？",
            ["DialogueId"] = 51105603,
            ["GUID"] = "7FF000FE",
            ["NextDialogue"] = 51105604,
            ["SpeakNpcId"] = 700355,
            ["TalkActionId"] = {
                [1] = "700355:Explain02_Start",
                },
            },
        [51105604] = {
            ["Camera"] = "93.466797,-74.861328,96.041504,0.000017,-5.799609,141.39859,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，你说得对，无论如何都不算是白忙一场。",
            ["ContentJP"] = "……そっか。そうだよね、無駄なことなんて一つもなかったもん！",
            ["DialogueId"] = 51105604,
            ["GUID"] = "7FF00128",
            ["NextDialogue"] = 51105605,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_End",
                },
            },
        [51105605] = {
            ["Camera"] = "-192.395508,-2.036133,165.440918,0.000029,-7.999804,5.19757,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，你们两个都去哪里了？我和你们的父亲都快急疯了。",
            ["ContentJP"] = "お前たち！どこ行ってたんだ！？私も父さんも、気が気じゃなかったんだぞ！",
            ["DialogueId"] = 51105605,
            ["FacialId"] = {
                [1] = "700358:Sad02",
                },
            ["GUID"] = "7FF00152",
            ["LookAt"] = {
                [1] = "700358:n(700356);700352:n(700358);700355:n(700358)",
                },
            ["NextDialogue"] = 51105606,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Confident_Start",
                [2] = "700355:Explain02_End",
                },
            ["TurnTo"] = {
                [1] = "700352:n(700358)",
                [2] = "700355:(700358)",
                },
            },
        [51105606] = {
            ["Camera"] = "181.737305,9.148438,135.123047,0.000029,-7.799679,159.398849,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们去了城外，遇到了秽兽，多亏了他们，救了我们。",
            ["ContentJP"] = "ごめんなさい。外に出て、穢獣に襲われて……でも、この人たちが助けてくれたんだ！",
            ["DialogueId"] = 51105606,
            ["GUID"] = "7FF0017C",
            ["LookAt"] = {
                [1] = "700356:n(700358)",
                },
            ["NextDialogue"] = 51105607,
            ["SpeakNpcId"] = 700356,
            ["SpeakNpcName"] = "UI_CMName_Name_NanHai",
            ["TalkActionId"] = {
                [1] = "700358:Confident_End",
                },
            },
        [51105607] = {
            ["Camera"] = "-279.733398,363.849609,151.888672,0.000033,-5.399538,-40.201584,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "城外？！门口的那群卫兵到底在干什么……算了，没事就好，没事就好。",
            ["ContentJP"] = "……城の外だと！？衛兵たちは一体何やってたんだ……いや、いい。無事でよかった。本当によかった。",
            ["DialogueId"] = 51105607,
            ["FacialId"] = {
                [1] = "700358:Shock02",
                },
            ["GUID"] = "7FF001A6",
            ["NextDialogue"] = 51105608,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Shock_Start",
                },
            },
        [51105608] = {
            ["Camera"] = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "也谢谢你们二位。",
            ["ContentJP"] = "それと……君たち、本当にありがとう。",
            ["DialogueId"] = 51105608,
            ["FacialId"] = {
                [1] = "700358:None",
                },
            ["GUID"] = "7FF001D0",
            ["LookAt"] = {
                [1] = "700358:n(700352)",
                },
            ["NextDialogue"] = 51105609,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Shock_End",
                },
            },
        [51105609] = {
            ["Camera"] = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦，等等，这不是白嘛？",
            ["ContentJP"] = "……ん？君、スノウじゃないか！",
            ["DialogueId"] = 51105609,
            ["GUID"] = "7FF001FA",
            ["NextDialogue"] = 51105610,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Talk01_Start",
                },
            },
        [51105610] = {
            ["Camera"] = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯？你认识我吗？",
            ["ContentJP"] = "ん？私のこと知ってるの？",
            ["DialogueId"] = 51105610,
            ["GUID"] = "7FF00224",
            ["NextDialogue"] = 51105611,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_Start",
                [2] = "700358:Talk01_End",
                },
            },
        [51105611] = {
            ["Camera"] = "50.040039,30.647461,131.996094,0.000035,3.20023,0.399084,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "之前不认识，但是这几天听说有一位皎皎之民在努力让冰湖城的居民振奋精神，听他们来看描述就应该是你了。",
            ["ContentJP"] = "いやね、この数日、「アイスレイクを元気にしようとしてるルーナがいる」って話を、何度も耳にしててさ。なんとなく、君のことじゃないかって思ってたんだ。",
            ["DialogueId"] = 51105611,
            ["GUID"] = "7FF0024E",
            ["NextDialogue"] = 51105612,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Agree",
                },
            },
        [51105612] = {
            ["Camera"] = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼，没错，就是我！",
            ["ContentJP"] = "えっへん！そうそう、その通り!！",
            ["DialogueId"] = 51105612,
            ["GUID"] = "7FF00278",
            ["NextDialogue"] = 51105613,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Think_End",
                },
            },
        [51105613] = {
            ["Camera"] = "56.023438,-549.053711,122.467773,0.00005,-3.199588,88.599136,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不过……我也没有找到什么很好的让大家振作起来的办法。唉，这样一来连我都要没什么精神啦。",
            ["ContentJP"] = "……でも、実際には全然いい方法、見つかってなくてさ。私自身、ちょっと元気なくなってきちゃった……",
            ["DialogueId"] = 51105613,
            ["GUID"] = "7FF002A2",
            ["NextDialogue"] = 51105614,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sigh_Start",
                },
            },
        [51105614] = {
            ["Camera"] = "-228.207031,-9.803711,149.039062,0.000034,-4.999445,4.798473,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你可就白担心啦，快去盖雷亚剧院吧，我刚刚就听说你的几个朋友在到处找你，但是却不知道你跑到哪里去了。",
            ["ContentJP"] = "あはは、それなら無駄な心配してる場合じゃないぞ。君の友だちたちが、君のこと探してたよ。場所は――確か、ガレア劇場だったかな？",
            ["DialogueId"] = 51105614,
            ["GUID"] = "7FF002CC",
            ["NextDialogue"] = 51105615,
            ["SpeakNpcId"] = 700358,
            ["TalkActionId"] = {
                [1] = "700358:Explain01_Start",
                },
            },
        [51105615] = {
            ["Camera"] = "221.630859,16.369629,149.368164,0.000039,-18.199278,-167.801788,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯？盖雷亚剧院，好的，我这就去！",
            ["ContentJP"] = "えっ！？ガレア劇場だね？わかった、すぐ行くーっ！！",
            ["DialogueId"] = 51105615,
            ["GUID"] = "7FF002F6",
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Bai_Think2Confident",
                },
            },
        [51105701] = {
            ["Camera"] = "23.855469,1780.534668,845.710938,0.000039,-0.800191,-90.801872,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只见盖雷亚剧院的舞台上，一个纸质的画板竖立了起来，按轮廓来看，是皎皎的身形。",
            ["ContentJP"] = "ガレア劇場の舞台上――一枚の紙製パネルが立てかけられている。その輪郭は、どう見ても「ルーナ」の姿だった。",
            ["DialogueId"] = 51105701,
            ["FinalCamera"] = "17.328125,1336.186768,839.191406,0.000039,-1.000206,-90.801872,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FF01112",
            ["NextDialogue"] = 51105702,
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51105702] = {
            ["Camera"] = "410.433594,758.865479,107.394531,0.000057,-1.200132,-118.800987,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哟，白，你回来啦。",
            ["ContentJP"] = "おっ、スノウ。やっと戻ってきたか。",
            ["DialogueId"] = 51105702,
            ["GUID"] = "7FF0113C",
            ["LookAt"] = {
                [1] = "700349:n(700352)",
                },
            ["NextDialogue"] = 51105703,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain01_Start",
                },
            },
        [51105703] = {
            ["Camera"] = "22.292969,279.418884,100.0625,0.000061,4.399789,-95.400414,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那凯旋的身影在灯光的照射下，如同巨人一般伟岸！",
            ["ContentJP"] = "その帰還の姿、スポットライトに照らされて……まるで、巨人のような迫力！",
            ["DialogueId"] = 51105703,
            ["GUID"] = "7FF01166",
            ["NextDialogue"] = 51105704,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700350:Talk02_Start",
                },
            },
        [51105704] = {
            ["Camera"] = "71.03125,17.270752,111.34375,0.000066,-7.600156,112.99839,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "威尔斯大叔，巴克？还有这么多人，你们为什么在这里？",
            ["ContentJP"] = "ウェルズのおっちゃん！？それにバック！？って、なになに、この人だかり……みんなここで何してんの？",
            ["DialogueId"] = 51105704,
            ["GUID"] = "7FF01190",
            ["LookAt"] = {
                [1] = "700352:n(700349)",
                },
            ["NextDialogue"] = 51105705,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700350:Talk02_End",
                [2] = "700352:Shock03_Start",
                },
            },
        [51105705] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说来怪不好意思的，一开始听说你想办法让我们振作起来，就只是觉得你是又无聊啦，没事找事。",
            ["ContentJP"] = "えーと、最初はさ、スノウがみんなを元気づけようとしてるって聞いて、「ああ、またヒマしてんな」くらいにしか思ってなかったんだよ。",
            ["DialogueId"] = 51105705,
            ["GUID"] = "7FF011BA",
            ["NextDialogue"] = 51105706,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700352:Shock03_End",
                },
            },
        [51105706] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "结果没想到你真的去尝试了各种方式，虽然听说也没什么好的结果，但我们水仙平原的常客听说了，都有点被打动吧。",
            ["ContentJP"] = "でもよ、ほんとにいろんな方法を本気で試してたって聞いてな。結果は……まぁ、その、あんまりだったかもしれんけど……",
            ["DialogueId"] = 51105706,
            ["GUID"] = "7FF011E4",
            ["NextDialogue"] = 51105707,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain01_End",
                },
            },
        [51105707] = {
            ["Camera"] = "-117.642578,-246.383423,180.195312,0.00005,-13.000267,74.194115,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呃，“没什么好的结果”可以不用说的！",
            ["ContentJP"] = "ちょ、それ言わなくていいっ！",
            ["DialogueId"] = 51105707,
            ["FacialId"] = {
                [1] = "700352:Sad03",
                },
            ["GUID"] = "7FF0120E",
            ["NextDialogue"] = 51105708,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Sad02_Start",
                },
            },
        [51105708] = {
            ["Camera"] = "378.371094,743.933472,140.042969,0.000055,-4.200552,-119.40416,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唔，确实不是重点，重点是，我们觉得不能光看你一个人这样东奔西走！",
            ["ContentJP"] = "お、おう、悪かった。重要なのはそこじゃない。俺たちはさ、おまえが一人で動き回ってんのに、ただ見てるだけってのが……",
            ["DialogueId"] = 51105708,
            ["GUID"] = "7FF01238",
            ["NextDialogue"] = 51105709,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Talk02_Start",
                },
            },
        [51105709] = {
            ["Camera"] = "378.371094,743.933472,140.042969,0.000055,-4.200552,-119.40416,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是我们觉得得要做点什么，不能让你白忙活。",
            ["ContentJP"] = "なんか、違うなって思ったわけ。",
            ["DialogueId"] = 51105709,
            ["GUID"] = "7FF01262",
            ["NextDialogue"] = 51105710,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Talk02_End",
                },
            },
        [51105710] = {
            ["Camera"] = "45.978516,411.828857,121.648438,0.000068,-1.000397,-97.205254,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "然后，思想之间迸发出火花，火花引爆了更多的思绪。",
            ["ContentJP"] = "思考と情熱がぶつかり合い、火花を散らし！その火花がさらに火を呼び、ついには――",
            ["DialogueId"] = 51105710,
            ["FacialId"] = {
                [1] = "700352:None",
                },
            ["GUID"] = "7FF0128C",
            ["NextDialogue"] = 51105711,
            ["SpeakNpcId"] = 700350,
            ["TalkActionId"] = {
                [1] = "700352:Sad02_End",
                },
            },
        [51105711] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "巴克说的话呢，可能不是那么好懂，意思是我们俩商量了一会儿，没什么好法子，又找到了其他人，最后找到了普奇团长。",
            ["ContentJP"] = "……えー、バックのはちょっとわかりにくいが。要するに、二人で考えても良い案が出なくて、他のみんなに声かけたんだ。で、最終的にプッチ団長に相談して――",
            ["DialogueId"] = 51105711,
            ["GUID"] = "7FF012B6",
            ["NextDialogue"] = 51105712,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain02_Start",
                },
            },
        [51105712] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "大家对于怎么向你表示感谢都各自有想法，但又都觉得不是最好的。",
            ["ContentJP"] = "感謝の気持ちはみんなそれぞれあるけど、どう形にすればいいかは、誰も決めきれなくてな。",
            ["DialogueId"] = 51105712,
            ["GUID"] = "7FF012E0",
            ["NextDialogue"] = 51105713,
            ["SpeakNpcId"] = 700349,
            },
        [51105713] = {
            ["Camera"] = "85.224609,834.157471,143.992188,0.000093,-3.799914,-95.203133,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是大家聚在一起想啊想，想地抓耳挠腮，争地面红耳赤。就在这个过程中，突然就感觉热情又重新回来了。",
            ["ContentJP"] = "で、話し合ってるうちに、なんだか熱くなってきて……気づいたら、みんながワイワイ言いながら何かしようって本気になってたんだ。",
            ["DialogueId"] = 51105713,
            ["GUID"] = "7FF0130A",
            ["NextDialogue"] = 51105714,
            ["SpeakNpcId"] = 700349,
            },
        [51105714] = {
            ["Camera"] = "85.224609,834.157471,143.992188,0.000093,-3.799914,-95.203133,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是我们意识到了，为了一个明确的目标去行动，可以让所有人重新燃起热情。",
            ["ContentJP"] = "誰かのために動こうとするだけで、人って自然と元気になれるんだな。",
            ["DialogueId"] = 51105714,
            ["GUID"] = "7FF01334",
            ["NextDialogue"] = 51105715,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Explain02_End",
                },
            },
        [51105715] = {
            ["Camera"] = "242.505859,2691.037598,777.695312,0.000124,0.999209,-92.40229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最终呢，我们决定在这里搭建一个皎皎们的舞台，在这里举办一个小的舞会，以宣告银烛狂欢的正式结束。",
            ["ContentJP"] = "そうして行き着いた結論が、これよ。ここに「ルーナの舞台」を作って、小さな舞踏会を開くことにしたのさ。銀燭祭りの正式な終幕を、ここで宣言するために。",
            ["DialogueId"] = 51105715,
            ["GUID"] = "7FF0135E",
            ["LookAt"] = {
                [1] = "700352:n(700359)",
                },
            ["NextDialogue"] = 51105716,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Talk03_Start",
                },
            },
        [51105716] = {
            ["Camera"] = "48.492188,150.261108,106.398438,0.000098,6.400003,-77.597488,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "更重要的是，向你，以及为了人类奔走的每一位皎皎表示感谢。",
            ["ContentJP"] = "そして何より――スノウ、そして人間のために奔走してくれるすべてのルーナたちへ、感謝を伝えるために。",
            ["DialogueId"] = 51105716,
            ["FacialId"] = {
                [1] = "700359:Smile01",
                },
            ["GUID"] = "7FF01388",
            ["NextDialogue"] = 51105717,
            ["SpeakNpcId"] = 700359,
            },
        [51105717] = {
            ["Camera"] = "47.298828,36.943848,122.441406,0.000113,-10.600057,107.802986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只不过因为准备仓促，这个布景还没有做好，但是我相信会有热心的冰湖城市民伸出援手的！",
            ["ContentJP"] = "……まあ、かなり急でまだ準備できてないんだ。でも大丈夫、きっと熱意あるアイスレイクのみんなが手を貸してくれるはずだからね！",
            ["DialogueId"] = 51105717,
            ["GUID"] = "7FF013B2",
            ["NextDialogue"] = 51105718,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Talk03_End",
                },
            },
        [51105718] = {
            ["Camera"] = "47.298828,36.943848,122.441406,0.000113,-10.600057,107.802986,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？为什么是皎皎们……我们其实，也没做什么啦，只是都做了一些平时在做的事情。",
            ["ContentJP"] = "え、ルーナたちに感謝？でも私たち、いつも通りのことをしただけだよ？特別なことは何もしてない。",
            ["DialogueId"] = 51105718,
            ["GUID"] = "7FF013DC",
            ["NextDialogue"] = 51105719,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Shy03_Start",
                },
            },
        [51105719] = {
            ["Camera"] = "-8.619141,416.381531,105.339844,0.000135,-0.200131,-79.794884,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "正是因为你们平时一直都在帮助其他人，所以在大家都无精打采的时候，看到皎皎们还是和往常一样。",
            ["ContentJP"] = "……そう、君たちが「いつも通り」人のために動いてくれていたからこそ、この街がどんな時でも崩れずにすんだんだ。",
            ["DialogueId"] = 51105719,
            ["GUID"] = "7FF01406",
            ["NextDialogue"] = 51105720,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Think_Start",
                },
            },
        [51105720] = {
            ["Camera"] = "-8.619141,416.381531,105.339844,0.000135,-0.200131,-79.794884,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "和往常一样锻造，冒险，经商，并且又帮助感染了其他人，所以才会让大家想着为你们做点什么吧。",
            ["ContentJP"] = "君たちが変わらずにいてくれたからこそ、見ていた人たちも「自分も頑張ろう」と思えた。",
            ["DialogueId"] = 51105720,
            ["GUID"] = "7FF01430",
            ["NextDialogue"] = 51105721,
            ["SpeakNpcId"] = 700359,
            ["TalkActionId"] = {
                [1] = "700359:Think_End",
                },
            },
        [51105721] = {
            ["Camera"] = "210.134766,-175.124634,161.980469,0.000142,-12.600367,121.406113,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……即便和平常一样，也能让大家打起精神吗。",
            ["ContentJP"] = "……普段通りでも、元気は伝染するんだね……",
            ["DialogueId"] = 51105721,
            ["GUID"] = "7FF0145A",
            ["NextDialogue"] = 51105722,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:Shy03_End",
                },
            },
        [51105722] = {
            ["Camera"] = "13.275391,55.729736,111.578125,0.000138,-6.800259,96.806892,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我明白了，哼哼。看来平时本魔王大人和小仆从在冰湖城里跑来跑去，已经积攒了很多人望。",
            ["ContentJP"] = "ふっふっふ……なるほどなるほど。日頃から魔王さまとその忠実なしもべが街中を走り回ってたおかげで、いつの間にか人望がたまってたってわけだ！",
            ["DialogueId"] = 51105722,
            ["GUID"] = "7FF01484",
            ["LookAt"] = {
                [1] = "700352:n(700352)",
                },
            ["NextDialogue"] = 51105723,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialConfident_Start",
                },
            },
        [51105723] = {
            ["Camera"] = "-8.945312,81.085327,158.34375,0.000068,-1.800137,-122.402336,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是，是，你是最受大家畏惧，最受大家尊敬，也最热爱自己子民的魔王大人，只要你一声令下，大家都会充满力量。",
            ["ContentJP"] = "お、おう……そうだな！さすがは「恐れられ、尊敬され、そして誰よりも民を愛する」我らが魔王さま！",
            ["DialogueId"] = 51105723,
            ["FacialId"] = {
                [1] = "700349:Smile01",
                },
            ["GUID"] = "7FF014AE",
            ["NextDialogue"] = 51105724,
            ["SpeakNpcId"] = 700349,
            ["TalkActionId"] = {
                [1] = "700349:Agree",
                [2] = "700352:SpecialConfident_End",
                },
            },
        [51105724] = {
            ["Camera"] = "0.195312,-69.396484,112.128906,0.000143,-7.20016,90.206581,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没错，那么我命令你们所有人！听从魔王大人的命令，恢复精神，开始银烛狂欢最后的舞会！",
            ["ContentJP"] = "よく言ったっ！それじゃ、魔王さまから命令だよ！みんな元気出して！銀燭祭り最後の舞踏会を始めるよーっ！",
            ["DialogueId"] = 51105724,
            ["FacialId"] = {
                [1] = "700352:Smile02",
                },
            ["GUID"] = "7FF014D8",
            ["NextDialogue"] = 51105725,
            ["SpeakNpcId"] = 700352,
            ["TalkActionId"] = {
                [1] = "700352:SpecialHappy_Start",
                },
            },
        [51105725] = {
            ["Camera"] = "320.064453,1972.346924,419.992188,0.000141,-7.200317,-99.594925,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好！",
            ["ContentJP"] = "おー！",
            ["DialogueId"] = 51105725,
            ["GUID"] = "7FF01502",
            ["NextDialogue"] = 51105726,
            ["SpeakNpcName"] = "UI_CMName_Name_ZhongRen",
            },
        [51105726] = {
            ["Camera"] = "-22.078125,-800.788818,638.539062,0.000137,3.599831,-91.394226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是，今年本蒙上一层阴翳的银烛狂欢，在一位自称魔王的皎皎的努力下，成功地重新燃起欢乐氛围。",
            ["ContentJP"] = "こうして、暗い影を落としていた今年の銀燭祭り――一人の「自称・魔王」のルーナがまいた希望の火種によって、再び、笑顔と歓声が灯る祝祭へと生まれ変わった。",
            ["DialogueId"] = 51105726,
            ["FinalCamera"] = "61.220703,-802.816284,638.539062,0.000137,3.599831,-91.394226,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "7FF0152C",
            ["ToFinalCameraBlendTime"] = 7,
            },
        [51105801] = {
            ["Content"] = "释放魔灵“紫纱黑云”的技能，参加庆典",
            ["ContentJP"] = "ジェネモン 「ユカリウマ」のスキルを発動し、祭りに参加しよう！",
            ["DialogueId"] = 51105801,
            ["GUID"] = "7FF0217A",
            },
        [51105802] = {
            ["Content"] = "释放魔灵“紫纱黑云”的技能，参加庆典",
            ["ContentJP"] = "ジェネモン 「ユカリウマ」のスキルを発動し、祭りに参加しよう！",
            ["DialogueId"] = 51105802,
            ["GUID"] = "7FF021A4",
            },
        [51105803] = {
            ["Content"] = "释放魔灵“雨衣水滴”的技能，参加庆典",
