                [2] = "701017:Talk02_Start",
                },
            },
        [51114022] = {
            ["Camera"] = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51114022,
            ["GUID"] = "7FF5663C",
            ["LookAt"] = {
                [1] = "701016:n(701018)",
                [2] = "701018:n(701016)",
                },
            ["NextDialogue"] = 51114023,
            ["SpeakNpcName"] = "UI_CMNpc_Yanjindu_Name_YangJRAndZhangJR",
            ["TalkActionId"] = {
                [1] = "701017:Talk02_End",
                },
            },
        [51114023] = {
            ["Content"] = "（两个孩子眼巴巴地看向你，似乎很希望你能结束这场推让。）",
            ["ContentJP"] = "ふたりの父親が押し問答する横で、子どもたちは「どうにかして〜」と言いたげな顔であなたを見つめた。",
            ["DialogueId"] = 51114023,
            ["GUID"] = "7FF56666",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51114024,
                [2] = 51114026,
                [3] = 51114028,
                },
            ["TalkActionId"] = {
                [1] = "701016:Explain02_Start",
                [2] = "701018:Think_Start",
                },
            },
        [51114024] = {
            ["Content"] = "要不我再去买两个一样大的？",
            ["ContentJP"] = "いっそ、同じ大きさの梨をもう2つ買ってきましょうか？",
            ["DialogueId"] = 51114024,
            ["GUID"] = "7FF56690",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51114025,
            },
        [51114025] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "再劳烦你就说不过去了……",
            ["ContentJP"] = "いやいや、そこまでお世話になるわけにはいかないよ……",
            ["DialogueId"] = 51114025,
            ["GUID"] = "7FF566BA",
            ["NextDialogue"] = 51114030,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701016:Explain02_End",
                [2] = "701018:Think_End",
                },
            },
        [51114026] = {
            ["Content"] = "切成片大家分着吃吧。",
            ["ContentJP"] = "切ってみんなで分けたらどうですか？",
            ["DialogueId"] = 51114026,
            ["GUID"] = "7FF566E4",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51114027,
            },
        [51114027] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "万万不可，把梨切开就成了“分离”，不吉利的。",
            ["ContentJP"] = "ダメダメ、梨を分けるなんて縁を切るのと同じ！縁起が悪いんだよ",
            ["DialogueId"] = 51114027,
            ["GUID"] = "7FF5670E",
            ["NextDialogue"] = 51114030,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701016:Explain02_End",
                [2] = "701018:Think_End",
                },
            },
        [51114028] = {
            ["Content"] = "我是外国人，我也长身体，两个都给我吃。",
            ["ContentJP"] = "……実は{性别:僕|私}も育ち盛りなんで、2つともいただきます！",
            ["DialogueId"] = 51114028,
            ["GUID"] = "7FF56738",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51114029,
            },
        [51114029] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这位{性别：小兄弟|姑娘}说话真是风趣……",
            ["ContentJP"] = "ははは、{性别:お兄さん|お嬢さん}、面白いこと言うねぇ……",
            ["DialogueId"] = 51114029,
            ["GUID"] = "7FF56762",
            ["NextDialogue"] = 51114030,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701016:Explain02_End",
                [2] = "701018:Think_End",
                },
            },
        [51114030] = {
            ["Camera"] = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "真是对不住，我们光顾着推让，把你晾在一边了。",
            ["ContentJP"] = "いや〜ごめんごめん。押し付け合いに夢中で、君のことを忘れてしまったよ。",
            ["DialogueId"] = 51114030,
            ["GUID"] = "7FF5678C",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114031,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Explain01_Start",
                },
            },
        [51114031] = {
            ["Content"] = "来，{性别：小兄弟|姑娘}，请收下报酬吧。",
            ["ContentJP"] = "ほら、お礼を受け取ってくれ。ありがとう。",
            ["DialogueId"] = 51114031,
            ["GUID"] = "7FF567B6",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114032,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Explain01_End",
                },
            },
        [51114032] = {
            ["Camera"] = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哎，这钱我来出吧！",
            ["ContentJP"] = "いやいや、私が出すよ。",
            ["DialogueId"] = 51114032,
            ["GUID"] = "7FF567E0",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114033,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701017:Talk01_Start",
                },
            },
        [51114033] = {
            ["Camera"] = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哪有让客人出钱的道理？",
            ["ContentJP"] = "いやいや、うちが頼んだことなんだから、こちらで払うのが筋でしょ？",
            ["DialogueId"] = 51114033,
            ["GUID"] = "7FF5680A",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextDialogue"] = 51114034,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701017:Talk01_End",
                },
            },
        [51114034] = {
            ["Camera"] = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你看我今天来也没带什么礼物……",
            ["ContentJP"] = "しかし、こちらも手土産の一つくらい……ああ、けど何も持ってきてないし……",
            ["DialogueId"] = 51114034,
            ["GUID"] = "7FF56834",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701017)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701017)",
                [5] = "100001:n(701017)",
                },
            ["NextDialogue"] = 51114035,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701017:Sigh_Start",
                },
            },
        [51114035] = {
            ["Content"] = "客气什么呀！我早就和这位{性别：小兄弟|姑娘}说好了，理应我来付钱……",
            ["ContentJP"] = "そんなの気にするな。最初からお礼は私がすると言ってたんだから。",
            ["DialogueId"] = 51114035,
            ["GUID"] = "7FF5685E",
            ["LookAt"] = {
                [1] = "701015:n(701017)",
                [2] = "701016:n(701015)",
                [3] = "701017:n(701015)",
                [4] = "701018:n(701015)",
                [5] = "100001:n(701015)",
                },
            ["NextOptions"] = {
                [1] = 51114036,
                },
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701017:Sigh_End",
                },
            },
        [51114036] = {
            ["Content"] = "……我说，要不你们一人出一半吧？",
            ["ContentJP"] = "……あの、じゃあ半分ずつ出すっていうのはどうでしょう？",
            ["DialogueId"] = 51114036,
            ["GUID"] = "7FF56888",
            ["NextDialogue"] = 51114037,
            ["TalkActionId"] = {
                [1] = "701015:Talk02_Start",
                },
            },
        [51114037] = {
            ["Content"] = "呃……既然你这么说了，那倒也行？",
            ["ContentJP"] = "うーん……それなら納得できるかも。",
            ["DialogueId"] = 51114037,
            ["GUID"] = "7FF568B2",
            ["LookAt"] = {
                [1] = "701015:n(100001)",
                [2] = "701016:n(100001)",
                [3] = "701017:n(100001)",
                [4] = "701018:n(100001)",
                },
            ["NextDialogue"] = 51114038,
            ["SpeakNpcId"] = 701015,
            ["TalkActionId"] = {
                [1] = "701015:Talk02_End",
                },
            },
        [51114038] = {
            ["Content"] = "呵呵，这位异邦的{性别：小兄弟|姑娘}倒是机灵。那就这么办，咱们一人出一半！",
            ["ContentJP"] = "なるほど、さすが異国のお方、気が利くな！じゃ、それで決まりだな。",
            ["DialogueId"] = 51114038,
            ["GUID"] = "7FF568DC",
            ["NextDialogue"] = 51114039,
            ["SpeakNpcId"] = 701017,
            ["TalkActionId"] = {
                [1] = "701017:Explain01_Start",
                },
            },
        [51114039] = {
            ["Content"] = "（虽然大梨之争还没有结果，但你已经拿到了报酬，就随他们去吧。）",
            ["ContentJP"] = "結局、大きな梨の行方ははっきりしないままだったが、あなたは無事に報酬を手に入れたので、それで良しとした。",
            ["DialogueId"] = 51114039,
            ["GUID"] = "7FF56906",
            ["TalkActionId"] = {
                [1] = "701017:Explain01_End",
                },
            },
        [51114040] = {
            ["Content"] = "乖，还是把大的让给哥哥吧！",
            ["ContentJP"] = "ほれ、大きい方をお兄さんに譲りなさい。",
            ["DialogueId"] = 51114040,
            ["GUID"] = "7FF56930",
            ["SpeakNpcId"] = 701015,
            },
        [51115000] = {
            ["Content"] = "哼哼哼……我一定会让你们都尝到苦头的……",
            ["ContentJP"] = "ふふふ……絶対に後悔させてやるんだから……！",
            ["DialogueId"] = 51115000,
            ["GUID"] = "7FF606B0",
            ["NextOptions"] = {
                [1] = 51115001,
                },
            ["SpeakNpcId"] = 701019,
            },
        [51115001] = {
            ["Content"] = "谁？",
            ["ContentJP"] = "誰？",
            ["DialogueId"] = 51115001,
            ["GUID"] = "7FF606DA",
            ["NextDialogue"] = 51115002,
            },
        [51115002] = {
            ["Content"] = "咦？！",
            ["ContentJP"] = "え！？",
            ["DialogueId"] = 51115002,
            ["GUID"] = "7FF60704",
            ["LookAt"] = {
                [1] = "701019:n(0)",
                },
            ["NextDialogue"] = 51115003,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Shock_Start",
                },
            },
        [51115003] = {
            ["Content"] = "你、你听到什么了？",
            ["ContentJP"] = "い、今の聞こえちゃった！？",
            ["DialogueId"] = 51115003,
            ["GUID"] = "7FF6072E",
            ["NextDialogue"] = 51115004,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Shock_End",
                },
            },
        [51115004] = {
            ["Content"] = "听到你在盘算做一些坏事。",
            ["ContentJP"] = "悪だくみしてる声がバッチリね。",
            ["DialogueId"] = 51115004,
            ["GUID"] = "7FF60758",
            ["NextDialogue"] = 51115005,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701019:Explain01_Start",
                },
            },
        [51115005] = {
            ["Content"] = "才不是坏事呢，我是要报仇！",
            ["ContentJP"] = "違うもん、これは復讐なの！悪いことじゃないもん！",
            ["DialogueId"] = 51115005,
            ["GUID"] = "7FF60782",
            ["NextDialogue"] = 51115006,
            ["SpeakNpcId"] = 701019,
            },
        [51115006] = {
            ["Content"] = "报什么仇？找谁报仇？",
            ["ContentJP"] = "復讐？誰に？",
            ["DialogueId"] = 51115006,
            ["GUID"] = "7FF607AC",
            ["NextDialogue"] = 51115007,
            ["SpeakNpcId"] = 100001,
            },
        [51115007] = {
            ["Content"] = "我们商队的货品供应商呀！跟他们合作真是气死人啦！",
            ["ContentJP"] = "うちの商隊が取引してる仕入れ先に決まってるじゃない！アイツら、ほんっと腹立つのよ！",
            ["DialogueId"] = 51115007,
            ["GUID"] = "7FF607D6",
            ["NextOptions"] = {
                [1] = 51115008,
                [2] = 51115009,
                },
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Explain01_End",
                },
            },
        [51115008] = {
            ["Content"] = "工作中难免有糟心事，气坏自己就得不偿失了，还是放宽心吧。",
            ["ContentJP"] = "仕事でイライラすることなんてよくあるよ。気にしすぎない方がいいって。",
            ["DialogueId"] = 51115008,
            ["GUID"] = "7FF60800",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51115010,
            },
        [51115009] = {
            ["Content"] = "如果有人欺负你，大风九章应该会惩罚他们吧？",
            ["ContentJP"] = "もし本当に酷い相手なら、きっと大風九章が裁いてくれるよね？",
            ["DialogueId"] = 51115009,
            ["GUID"] = "7FF6082A",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51115010,
            },
        [51115010] = {
            ["Content"] = "嗨呀，你是不知道，这些人狡猾的很！",
            ["ContentJP"] = "ふん、あなたは何も分かってない！あいつら、狡猾すぎて誰も手が出せないんだから！",
            ["DialogueId"] = 51115010,
            ["GUID"] = "7FF60854",
            ["NextDialogue"] = 51115011,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk01_Start",
                },
            },
        [51115011] = {
            ["Content"] = "开工的时候吧，总是说着什么“相信贵方的实力”、“能力越大责任越大”，然后把困难的部分“让”给我们做。",
            ["ContentJP"] = "仕事のときは「君たちの実力を信じてる」だの、「力があるならその分責任も取るべき」だの言って、面倒な仕事だけ押しつけてくるくせに……",
            ["DialogueId"] = 51115011,
            ["GUID"] = "7FF6087E",
            ["NextDialogue"] = 51115012,
            ["SpeakNpcId"] = 701019,
            },
        [51115012] = {
            ["Content"] = "出了岔子呢，又总是念着“唇齿相依”、“同舟共济”云云，支使我们帮忙收拾烂摊子，给他们善后。",
            ["ContentJP"] = "ミスったときは「助け合いが大事」とか「会社一致団結」とか言って、始末はこっち任せ！",
            ["DialogueId"] = 51115012,
            ["GUID"] = "7FF608A8",
            ["NextDialogue"] = 51115013,
            ["SpeakNpcId"] = 701019,
            },
        [51115013] = {
            ["Content"] = "要是拒绝这些呀，他们就会闹别扭，在各种地方偷懒，虽然谁都看得出是故意的，但这种事情也没法证明……",
            ["ContentJP"] = "断ったらすぐ不機嫌になって、わざと手を抜くの。誰が見てもサボってるのに、証拠がないから何も言えないのよ……！",
            ["DialogueId"] = 51115013,
            ["GUID"] = "7FF608D2",
            ["NextDialogue"] = 51115014,
            ["SpeakNpcId"] = 701019,
            },
        [51115014] = {
            ["Content"] = "当面问的话，他们就会装出一副特别愧疚的样子，连声说“真是太对不住了下次一定注意”之类的鬼话……真是气煞我也！",
            ["ContentJP"] = "いざ問い詰めても、「本当にすみません、次はちゃんとやりますぅ～」って嘘臭い謝罪ばっか！あーもうムカつく！！",
            ["DialogueId"] = 51115014,
            ["GUID"] = "7FF608FC",
            ["NextDialogue"] = 51115015,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk01_End",
                },
            },
        [51115015] = {
            ["Content"] = "要不换一家合作呢？",
            ["ContentJP"] = "仕入れ先を変えればいいんじゃない？",
            ["DialogueId"] = 51115015,
            ["GUID"] = "7FF60926",
            ["NextDialogue"] = 51115016,
            ["SpeakNpcId"] = 100001,
            },
        [51115016] = {
            ["Content"] = "我倒是想……可是我们商队进的货品比较罕有，只有这一家能供应。",
            ["ContentJP"] = "できるならとっくにしてるわよ！でもうちが扱ってる品物って、珍しいものばっかりで他に取引できるとこなんてないの……",
            ["DialogueId"] = 51115016,
            ["GUID"] = "7FF60950",
            ["NextDialogue"] = 51115017,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk02_Start",
                },
            },
        [51115017] = {
            ["Content"] = "不过，我是不会就这么忍着的！我已经在写复仇计划了，待我准备妥当，定要叫那帮老东西跪下求饶，呵呵呵……",
            ["ContentJP"] = "でもね、だからって黙って泣き寝入りなんてごめんよ！もう復讐計画を書き始めてるの！あいつら、いずれひざまずいて謝らせてやる……ふふふふふ！",
            ["DialogueId"] = 51115017,
            ["GUID"] = "7FF6097A",
            ["NextDialogue"] = 51115018,
            ["SpeakNpcId"] = 701019,
            },
        [51115018] = {
            ["Content"] = "具体什么计划？",
            ["ContentJP"] = "で、具体的には？",
            ["DialogueId"] = 51115018,
            ["GUID"] = "7FF609A4",
            ["NextDialogue"] = 51115019,
            ["SpeakNpcId"] = 100001,
            },
        [51115019] = {
            ["Content"] = "可多啦，我给你念几条——",
            ["ContentJP"] = "全部言ってたらキリがないわ。例を挙げるなら――",
            ["DialogueId"] = 51115019,
            ["GUID"] = "7FF609CE",
            ["NextDialogue"] = 51115020,
            ["SpeakNpcId"] = 701019,
            },
        [51115020] = {
            ["Content"] = "一，把他们的桌子砍掉一截腿，让他们没法平稳地写字！",
            ["ContentJP"] = "その1、机の脚を1本だけ切って、字を書こうとするとグラグラしてイライラさせる！",
            ["DialogueId"] = 51115020,
            ["GUID"] = "7FF609F8",
            ["NextDialogue"] = 51115021,
            ["SpeakNpcId"] = 701019,
            },
        [51115021] = {
            ["Content"] = "二，在他们的茶里放泻药，让他们上不了班！",
            ["ContentJP"] = "その2、お茶に下剤を入れて、おなか壊させて会社に来れないようにする！",
            ["DialogueId"] = 51115021,
            ["GUID"] = "7FF60A22",
            ["NextDialogue"] = 51115022,
            ["SpeakNpcId"] = 701019,
            },
        [51115022] = {
            ["Content"] = "三，在他们祈求财运的盆栽里浇开水，让他们发不了财！",
            ["ContentJP"] = "その3、金運アップの植木鉢に熱湯をかけて、金運ダウンさせる！",
            ["DialogueId"] = 51115022,
            ["GUID"] = "7FF60A4C",
            ["NextDialogue"] = 51115023,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Talk02_End",
                },
            },
        [51115023] = {
            ["Content"] = "……听起来都没有什么杀伤力。而且，这些应该也是大风九章禁止的内容吧？",
            ["ContentJP"] = "……なかなかこすい仕返しばかりで逆にすごい{性别:な|ね}。てか、どれも大風九章で禁じられてる内容じゃない？",
            ["DialogueId"] = 51115023,
