            ["SpeakNpcId"] = 100001,
            },
        [51115029] = {
            ["Content"] = "唔……好像是前年秋天开始写的？也可能是再往前一年，记不太清了。",
            ["ContentJP"] = "えーっと、たしか一昨年の秋くらいから書き始めた……かも？いや、もっと前だったかな……？",
            ["DialogueId"] = 51115029,
            ["GUID"] = "7FF60B72",
            ["NextDialogue"] = 51115030,
            ["SpeakNpcId"] = 701019,
            },
        [51115030] = {
