            ["DialogueId"] = 51115030,
            ["GUID"] = "7FF60B9C",
            ["NextDialogue"] = 51115031,
            ["SpeakNpcId"] = 100001,
            },
        [51115031] = {
            ["Content"] = "古语有云：“君子报仇，十年不晚”！",
