            ["GUID"] = "7FF60C1A",
            ["NextDialogue"] = 51115034,
            ["SpeakNpcId"] = 701019,
            ["TalkActionId"] = {
                [1] = "701019:Shock_Start",
                },
            },
        [51115034] = {
