        [51116023] = {
            ["Content"] = "你应该向我支付听这段演奏的费用。",
            ["ContentJP"] = "今の曲を聞かされた分の報酬も欲しいんだけど。",
            ["DialogueId"] = 51116023,
            ["GUID"] = "7FF6AE86",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51116025,
            },
        [51116024] = {
            ["Content"] = "天哪，你弹得太好了，小动物们听完都热血沸腾了！",
            ["ContentJP"] = "動物たち、行っちゃったね。素晴らしい演奏に感動したのかな。",
            ["DialogueId"] = 51116024,
            ["GUID"] = "7FF6AEB0",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51116025,
            },
        [51116025] = {
            ["Content"] = "怎、怎会如此……这究竟是何缘故……？",
            ["ContentJP"] = "な、なぜだ……！？どうして……！？",
            ["DialogueId"] = 51116025,
            ["GUID"] = "7FF6AEDA",
            ["NextDialogue"] = 51116026,
            ["SpeakNpcId"] = 701020,
            },
        [51116026] = {
            ["Content"] = "你弹的东西真的是音乐吗？",
            ["ContentJP"] = "それ、本当に音楽って言える？",
            ["DialogueId"] = 51116026,
            ["GUID"] = "7FF6AF04",
            ["NextDialogue"] = 51116027,
            ["SpeakNpcId"] = 100001,
            },
        [51116027] = {
            ["Content"] = "这“出神入化之曲”，总应与一般的音乐有异啊。",
            ["ContentJP"] = "神がかった旋律とは、常の音とは異なるもの……動物に聴かせるなら、やはり自然の音がふさわしいと思いまして……",
            ["DialogueId"] = 51116027,
            ["GUID"] = "7FF6AF2E",
            ["NextDialogue"] = 51116028,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk02_Start",
                },
            },
        [51116028] = {
            ["Content"] = "我想既是要让动物也能欣赏，想必最好取材于自然……好比我刚才弹的这一曲，便是融合了树枝撕裂之声、蚊虫振翅之声、野狗刨地之声……",
            ["ContentJP"] = "たとえば、枝が裂ける音、蚊の羽音、野犬が地面を掘る音……それらを組み合わせてみたんです……",
            ["DialogueId"] = 51116028,
            ["GUID"] = "7FF6AF58",
            ["NextDialogue"] = 51116029,
            ["SpeakNpcId"] = 701020,
            },
        [51116029] = {
            ["Content"] = "我自以为此曲完美无缺，没想到，终究是错付了……",
            ["ContentJP"] = "自信作だったのですが、まさか……伝わらなかったとは……！",
            ["DialogueId"] = 51116029,
            ["GUID"] = "7FF6AF82",
            ["NextOptions"] = {
                [1] = 51116030,
                },
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Talk02_End",
                },
            },
        [51116030] = {
            ["Content"] = "有没有可能你选的这些声音本来也不好听……",
            ["ContentJP"] = "そもそもその音、聞いてて気持ちいいもんじゃない気がするけど……",
            ["DialogueId"] = 51116030,
            ["GUID"] = "7FF6AFAC",
            ["NextDialogue"] = 51116031,
            },
        [51116031] = {
            ["Content"] = "……！",
            ["ContentJP"] = "……！",
            ["DialogueId"] = 51116031,
            ["GUID"] = "7FF6AFD6",
            ["NextDialogue"] = 51116032,
            ["SpeakNpcId"] = 701020,
            },
        [51116032] = {
            ["Content"] = "{性别：兄台|姑娘}可真是一语惊醒梦中人！",
            ["ContentJP"] = "まさに目が覚めるような一言！",
            ["DialogueId"] = 51116032,
            ["GUID"] = "7FF6B000",
            ["NextDialogue"] = 51116033,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Sigh_Start",
                },
            },
        [51116033] = {
            ["Content"] = "原来如此，是我取材有误……我这就回去重新谱曲！让我想想……乌鸦高鸣之声、野鼠啃噬之声、金石摩擦之声……嗯，应当不错！",
            ["ContentJP"] = "そうか、素材の選定から誤っていたのですね……！では次は、カラスの鳴き声、ネズミのかじる音、金属を擦る音……ふふ、これはいけるかも！",
            ["DialogueId"] = 51116033,
            ["GUID"] = "7FF6B02A",
            ["NextDialogue"] = 51116034,
            ["SpeakNpcId"] = 701020,
            ["TalkActionId"] = {
                [1] = "701020:Sigh_End",
                },
            },
        [51116034] = {
            ["Content"] = "（具睦似乎已经完全沉浸在了自己的艺术之中。无论如何，你已经拿到了报酬，还是赶紧离开，保护好自己的耳朵吧。）",
            ["ContentJP"] = "オンチはすっかり自分の世界に入り込んでいる。報酬は手に入ったし、早めに離れて耳を守るとしよう。",
            ["DialogueId"] = 51116034,
            ["GUID"] = "7FF6B054",
            },
        [51116035] = {
            ["Content"] = "小鸟儿、小狐狸、小野猫你们别跑呀，再听一曲吧！",
            ["ContentJP"] = "小鳥さん、子ぎつねさん、野良猫くん！逃げないで、もう一曲だけ聴いていっておくれ〜！",
            ["DialogueId"] = 51116035,
            ["GUID"] = "7FF6B07E",
            ["SpeakNpcId"] = 701020,
            },
        [51117000] = {
            ["Camera"] = "-56.007812,179.976562,127.53125,0.000043,-7.60004,-107.399704,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一定是无由生啦！",
            ["ContentJP"] = "ぜったいムユウセイだってば！",
            ["DialogueId"] = 51117000,
            ["GUID"] = "7FF74ED0",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117001,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Angry01_Start",
                },
            },
        [51117001] = {
            ["Camera"] = "-175.459961,-170.417969,118.708984,0.000063,-4.799348,68.995163,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "一定是狴犴啦！",
            ["ContentJP"] = "いやいや、狴犴に決まってるって！",
            ["DialogueId"] = 51117001,
            ["GUID"] = "7FF74EFA",
            ["NextDialogue"] = 51117002,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Angry01_Start",
                },
            },
        [51117002] = {
            ["Camera"] = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（枯荣阁外，两个小孩吵吵嚷嚷的，不知在争论些什么。你无意中放慢了脚步，引起了他们的注意——）",
            ["ContentJP"] = "枯栄閣の外で、二人の子どもが言い争っている。何を話しているのかは分からないが、つい足を止めてしまったあなたに、二人の視線が向けられた——",
            ["DialogueId"] = 51117002,
            ["GUID"] = "7FF74F24",
            ["NextDialogue"] = 51117003,
            ["TalkActionId"] = {
                [1] = "701021:Angry01_End",
                [2] = "701022:Angry01_End",
                },
            },
        [51117003] = {
            ["Content"] = "{性别：大哥哥|大姐姐}，{性别：大哥哥|大姐姐}！你说呢？",
            ["ContentJP"] = "そこの{性别:お兄ちゃん|お姉ちゃん}！あなたはどっちだと思う？",
            ["DialogueId"] = 51117003,
            ["GUID"] = "7FF74F4E",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117004,
                },
            ["SpeakNpcId"] = 701021,
            },
        [51117004] = {
            ["Content"] = "我说什么？",
            ["ContentJP"] = "何の話？",
            ["DialogueId"] = 51117004,
            ["GUID"] = "7FF74F78",
            ["NextDialogue"] = 51117005,
            },
        [51117005] = {
            ["Content"] = "你说那个白色的影子到底是什么？",
            ["ContentJP"] = "ほら、あの白い影だよ！",
            ["DialogueId"] = 51117005,
            ["GUID"] = "7FF74FA2",
            ["NextDialogue"] = 51117006,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Think_Start",
                },
            },
        [51117006] = {
            ["Content"] = "什么白色的影子？",
            ["ContentJP"] = "白い影……？",
            ["DialogueId"] = 51117006,
            ["GUID"] = "7FF74FCC",
            ["NextDialogue"] = 51117007,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701021:Think_End",
                },
            },
        [51117007] = {
            ["Camera"] = "807.511719,-81.339844,690.010742,0.000093,5.194338,77.734879,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就是旁边的这间宅子里出现的那个呀！我们几个都看见过。",
            ["ContentJP"] = "このお屋敷で見たの！あたしたち、みんな見たんだから！",
            ["DialogueId"] = 51117007,
            ["GUID"] = "7FF74FF6",
            ["NextDialogue"] = 51117008,
            ["SpeakNpcId"] = 701021,
            },
        [51117008] = {
            ["Content"] = "那白色的影子会飞，会浮在空中，还会突然出现、突然消失，你觉得那到底是什么？",
            ["ContentJP"] = "ふわっと浮かんで、急に現れて、急に消えちゃうの。あれ、一体何だと思う？",
            ["DialogueId"] = 51117008,
            ["GUID"] = "7FF75020",
            ["NextDialogue"] = 51117009,
            ["SpeakNpcId"] = 701021,
            },
        [51117009] = {
            ["Camera"] = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我觉得是狴犴！身为执法者，狴犴在有人的地方要时刻保持威严，但一直这样多累呀，所以它们会偷偷跑进这间没人的宅子里嬉戏玩耍。",
            ["ContentJP"] = "あれは<Default note=\"text:ビーアン\">狴犴</>だって！いつも人前でカッコつけてるけど、実はこっそりこの無人の屋敷で遊んでるんだよ。たまには息抜きも必要でしょ？",
            ["DialogueId"] = 51117009,
            ["GUID"] = "7FF7504A",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117010,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_Start",
                },
            },
        [51117010] = {
            ["Content"] = "说什么傻话呢，狴犴可是大风九章的使者，又不是你家的狗狗，才不需要玩呢！而且这座宅子最近有人住了。",
            ["ContentJP"] = "なに言ってるの、狴犴は「<Default note=\"text:たいふうきゅうしょう\">大風九章</>」の使いなんだよ？あんたの飼い犬じゃないんだから、遊んだりしないってば。それに、この家、最近誰か住んでるって聞いたよ？",
            ["DialogueId"] = 51117010,
            ["GUID"] = "7FF75074",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117011,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_End",
                },
            },
        [51117011] = {
            ["Content"] = "我觉得那个白色影子一定是无由生。它可能是这个宅子的上一任主人变的，因为太喜欢这座宅子，所以不愿意离开……",
            ["ContentJP"] = "だから、あれはムユウセイ。前の住人がこの屋敷を手放せず、成仏できなかったのかも……",
            ["DialogueId"] = 51117011,
            ["GUID"] = "7FF7509E",
            ["NextDialogue"] = 51117012,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_Start",
                },
            },
        [51117012] = {
            ["Content"] = "如果真的是宅子主人变的，怎么会现在才出现呢？",
            ["ContentJP"] = "でもさ、本当にそうなら、なんで今になって出てきたの？",
            ["DialogueId"] = 51117012,
            ["GUID"] = "7FF750C8",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117013,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_End",
                },
            },
        [51117013] = {
            ["Content"] = "无由生可以活很久很久，说不定它之前是出门玩了呀。",
            ["ContentJP"] = "ムユウセイって長生きじゃん。もしかして旅にでも出てたんじゃない？",
            ["DialogueId"] = 51117013,
            ["GUID"] = "7FF750F2",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117014,
            ["SpeakNpcId"] = 701021,
            },
        [51117014] = {
            ["Content"] = "可是无由生的颜色也不是白的呀！",
            ["ContentJP"] = "でも、白くなかったよね？ムユウセイって。",
            ["DialogueId"] = 51117014,
            ["GUID"] = "7FF7511C",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117015,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Explain01_Start",
                },
            },
        [51117015] = {
            ["Content"] = "你怎么知道没有白的无由生？无由生才会飞，狴犴又不会飞。",
            ["ContentJP"] = "白いのもいるかもしれないでしょ？飛べるのはムユウセイだけだし。狴犴は飛べないもん。",
            ["DialogueId"] = 51117015,
            ["GUID"] = "7FF75146",
            ["LookAt"] = {
                [1] = "100001:n(701021)",
                },
            ["NextDialogue"] = 51117016,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Explain01_End",
                },
            },
        [51117016] = {
            ["Content"] = "你怎么知道没有会飞的狴犴？",
            ["ContentJP"] = "じゃあ、飛べる狴犴がいてもいいじゃん。",
            ["DialogueId"] = 51117016,
            ["GUID"] = "7FF75170",
            ["LookAt"] = {
                [1] = "100001:n(701022)",
                },
            ["NextDialogue"] = 51117017,
            ["SpeakNpcId"] = 701022,
            },
        [51117017] = {
            ["Content"] = "……哼！{性别：大哥哥|大姐姐}，你说呢，你觉得那是无由生还是狴犴？",
            ["ContentJP"] = "……むぅ！{性别:お兄さん|お姉さん}はどっちだと思う？ムユウセイ？それとも<Default note=\"text:ビーアン\">狴犴</>？",
            ["DialogueId"] = 51117017,
            ["GUID"] = "7FF7519A",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117018,
                },
            ["RestartTag"] = 51117017,
            ["SpeakNpcId"] = 701021,
            },
        [51117018] = {
            ["Content"] = "（白色影子吗……会是什么呢？）",
            ["ContentJP"] = "（白い影……何だろう？）",
            ["DialogueId"] = 51117018,
            ["FailDialogue"] = 51117019,
            ["GUID"] = "7FF751C4",
            ["ImprCheckId"] = 1125,
            ["NextDialogue"] = 51117020,
            },
        [51117019] = {
            ["Content"] = "（一时没想到答案。）",
            ["ContentJP"] = "（すぐには思いつかない。）",
            ["DialogueId"] = 51117019,
            ["GUID"] = "7FF751EE",
            },
        [51117020] = {
            ["Content"] = "我觉得你们说的都不对。我猜那个白色影子是住在这里的人养的小宠物。",
            ["ContentJP"] = "うーん、どっちでもないかも。あれって、この家の人が飼ってるペットじゃない？",
            ["DialogueId"] = 51117020,
            ["GUID"] = "7FF75218",
            ["NextDialogue"] = 51117021,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51117021] = {
            ["Content"] = "啊……？",
            ["ContentJP"] = "え……？",
            ["DialogueId"] = 51117021,
            ["GUID"] = "7FF75242",
            ["NextDialogue"] = 51117022,
            ["SpeakNpcId"] = 701021,
            },
        [51117022] = {
            ["Content"] = "小宠物……是说小猫小狗吗？可是我们看到的那个影子会瞬间消失诶！",
            ["ContentJP"] = "ペットって、猫とか犬のこと？でも、あの影、すごい速さで消えたりするんだよ？",
            ["DialogueId"] = 51117022,
            ["GUID"] = "7FF7526C",
            ["NextDialogue"] = 51117023,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk02_Start",
                },
            },
        [51117023] = {
            ["Content"] = "对呀，而且它有时候飞得特别快，比我们家的小猫被擀面杖吓得跳起来的速度还快。",
            ["ContentJP"] = "そうそう！うちの猫が麺棒にびっくりして飛び上がるより速かった！",
            ["DialogueId"] = 51117023,
            ["GUID"] = "7FF75296",
            ["NextDialogue"] = 51117024,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Think_Start",
                [2] = "701021:Talk02_End",
                },
            },
        [51117024] = {
            ["Content"] = "不信的话，你们就敲门问问看。",
            ["ContentJP"] = "信じられないなら、直接聞いてみれば？",
            ["DialogueId"] = 51117024,
            ["GUID"] = "7FF752C0",
            ["NextDialogue"] = 51117025,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701022:Think_End",
                },
            },
        [51117025] = {
            ["Content"] = "可、可是里面住的是个陌生人……",
            ["ContentJP"] = "えっ、でも……知らない人だし……",
            ["DialogueId"] = 51117025,
            ["GUID"] = "7FF752EA",
            ["NextDialogue"] = 51117026,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                },
            },
        [51117026] = {
            ["Content"] = "听我外婆讲，这个宅子里住的好像是很厉害的大人物，万一那个大人物听了生气了怎么办？",
            ["ContentJP"] = "ばあちゃんが言ってた。あそこに住んでるのは、すごく偉い人なんだって。怒らせたらどうするの……",
            ["DialogueId"] = 51117026,
            ["GUID"] = "7FF75314",
            ["NextDialogue"] = 51117028,
            ["SpeakNpcId"] = 701022,
            },
        [51117027] = {
            ["Content"] = "第三个小孩入场",
            ["ContentJP"] = "三人目の子どもが現れる。",
            ["DialogueId"] = 51117027,
            ["GUID"] = "7FF7533E",
            },
        [51117028] = {
            ["Camera"] = "-183.449219,717.648438,135.62793,0.000058,-3.004539,-77.045387,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？兰叶，望南，你们两个怎么在这里呀？",
            ["ContentJP"] = "あれ？ランヨウ、ボウナン、何してるの？",
            ["DialogueId"] = 51117028,
            ["GUID"] = "7FF75368",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(100001)",
                },
            ["NextDialogue"] = 51117029,
            ["Scripts"] = "MoveTo{ActorId{701023},TargetPoint{\"YuXian_Target\"},MoveSpeed{100},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 701023,
            },
        [51117029] = {
            ["Camera"] = "-157.855469,429.066406,150.193359,0.000067,-5.60486,-83.644531,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我们正在辩论那个白色影子的真身呢！",
            ["ContentJP"] = "ちょうど、白い影の正体について話してたの！",
            ["DialogueId"] = 51117029,
            ["GUID"] = "7FF75392",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117030,
            ["SpeakNpcId"] = 701021,
            },
        [51117030] = {
            ["Content"] = "噢，这个呀，我已经知道啦。我昨天经过这里的时候恰好遇见了住在里面的姐姐，她说那个白色的影子是“鱼龙”。",
            ["ContentJP"] = "ああ、それ？もう答えわかってるよ。昨日ここ通ったとき、中に住んでるお姉さんに会ったの。その人が教えてくれたの、「魚龍」っていうんだって。",
            ["DialogueId"] = 51117030,
            ["GUID"] = "7FF753BC",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(701023)",
                },
            ["NextDialogue"] = 51117031,
            ["SpeakNpcId"] = 701023,
            ["TalkActionId"] = {
                [1] = "701023:Explain01_Start",
                },
            },
        [51117031] = {
            ["Content"] = "她解释了一大堆什么“寄托”呀，“思念”呀什么的，我不太听得懂……反正就是类似于小宠物的东西啦！",
            ["ContentJP"] = "「寄托」とか「想い」とか、なんか難しいことも言ってたけど、要するにペットみたいなものらしいよ。",
            ["DialogueId"] = 51117031,
            ["GUID"] = "7FF753E6",
            ["NextDialogue"] = 51117032,
            ["SpeakNpcId"] = 701023,
            },
        [51117032] = {
            ["Content"] = "她还变了一只出来给我看呢，“鱼龙”摸上去就像水做的一样，凉凉的，可神奇了！",
            ["ContentJP"] = "それにね、その魚龍、実際に見せてもらったの！触ると水みたいにひんやりしてて、すっごくきれいだった！",
            ["DialogueId"] = 51117032,
            ["GUID"] = "7FF75410",
            ["NextDialogue"] = 51117033,
            ["SpeakNpcId"] = 701023,
            ["TalkActionId"] = {
                [1] = "701023:Explain01_End",
                },
            },
        [51117033] = {
            ["Content"] = "什么？！",
            ["ContentJP"] = "なっ……！",
            ["DialogueId"] = 51117033,
            ["GUID"] = "7FF7543A",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117034,
            ["SpeakNpcId"] = 701021,
            },
        [51117034] = {
            ["Content"] = "居、居然真的是小宠物……",
            ["ContentJP"] = "ホントに、ペットだったんだ……",
            ["DialogueId"] = 51117034,
            ["GUID"] = "7FF75464",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117035,
            ["SpeakNpcId"] = 701023,
            },
        [51117035] = {
            ["Content"] = "没想到最后是这个{性别：大哥哥|大姐姐}猜对了……",
            ["ContentJP"] = "まさか……{性别:お兄さん|お姉さん}の言ったことが本当だったなんて……",
            ["DialogueId"] = 51117035,
            ["GUID"] = "7FF7548E",
            ["LookAt"] = {
                [1] = "701021:n(100001)",
                [2] = "701022:n(100001)",
                [3] = "100001:n(100001)",
                [4] = "701023:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51117036,
                [2] = 51117040,
                [3] = 51117044,
                },
            ["SpeakNpcId"] = 701021,
            },
        [51117036] = {
            ["Content"] = "其实是因为我也见过那位姐姐，所以才能猜对的。",
            ["ContentJP"] = "実はね、前にそのお姉さんと会ったことがあるんだ。それでピンときた。",
