            ["GUID"] = "7FF754B8",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51117037,
            },
        [51117037] = {
            ["Content"] = "怎么你也见过？那我也要见。",
            ["ContentJP"] = "え〜っ！ずるい、あたしも会いたい！",
            ["DialogueId"] = 51117037,
            ["GUID"] = "7FF754E2",
            ["LookAt"] = {
