            ["TalkActionId"] = {
                [1] = "701021:Talk01_Start",
                },
            },
        [51117038] = {
            ["Content"] = "我也要，我也要！",
            ["ContentJP"] = "ぼくもぼくも！",
            ["DialogueId"] = 51117038,
            ["GUID"] = "7FF7550C",
            ["LookAt"] = {
