                [2] = "701022:n(701023)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117039,
            ["SpeakNpcId"] = 701022,
            },
        [51117039] = {
            ["Content"] = "嗯……那下次我们带点好吃的去找那个姐姐玩，让她也给我们看看“鱼龙”吧~",
            ["ContentJP"] = "じゃあさ、今度お菓子持って行こうよ！そうしたら、「魚龍」見せてもらえるかも！",
            ["DialogueId"] = 51117039,
            ["GUID"] = "7FF75536",
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_End",
                },
            },
        [51117040] = {
            ["Content"] = "也可能你们看到的是其他的白色影子。",
            ["ContentJP"] = "……でも、もしかしたら、君たちが見たのは別の影だったかもしれないよ。",
            ["DialogueId"] = 51117040,
            ["GUID"] = "7FF75560",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51117041,
            },
        [51117041] = {
            ["Content"] = "有道理诶！",
            ["ContentJP"] = "あっ、それもありえる！",
            ["DialogueId"] = 51117041,
            ["GUID"] = "7FF7558A",
            ["LookAt"] = {
                [1] = "701021:n(701021)",
                [2] = "701022:n(701021)",
                [3] = "100001:n(701021)",
                [4] = "701023:n(701021)",
                },
            ["NextDialogue"] = 51117042,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_Start",
                },
            },
        [51117042] = {
            ["Content"] = "也许这宅子里既有鱼龙，也有狴犴，还有无由生！",
            ["ContentJP"] = "もしかして、この家には……「魚龍」と「狴犴」と「ムユウセイ」が全部いるのかも！",
            ["DialogueId"] = 51117042,
            ["GUID"] = "7FF755B4",
            ["NextDialogue"] = 51117043,
            ["SpeakNpcId"] = 701021,
            },
        [51117043] = {
            ["Content"] = "那我们都说对了，好耶~",
            ["ContentJP"] = "それなら、全員正解ってことだ！やった〜！",
            ["DialogueId"] = 51117043,
            ["GUID"] = "7FF755DE",
            ["LookAt"] = {
