                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701021:Talk01_End",
                },
            },
        [51117044] = {
            ["Content"] = "哼哼，这就是大人的实力。",
            ["ContentJP"] = "……ふふ、これぞ大人の実力ってやつだよ。",
            ["DialogueId"] = 51117044,
            ["GUID"] = "7FF75608",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51117045,
            },
        [51117045] = {
            ["Content"] = "那我长大以后也要变得这么聪明。",
            ["ContentJP"] = "ぼくも早く大人になって、そんなふうに賢くなりたいな〜",
            ["DialogueId"] = 51117045,
            ["GUID"] = "7FF75632",
            ["LookAt"] = {
