                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117046,
            ["SpeakNpcId"] = 701022,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_Start",
                },
            },
        [51117046] = {
            ["Content"] = "我要变得比这个{性别：大哥哥|大姐姐}还聪明！",
            ["ContentJP"] = "あたしは絶対、{性别:お兄さん|お姉さん}より賢くなる！",
            ["DialogueId"] = 51117046,
            ["GUID"] = "7FF7565C",
            ["LookAt"] = {
                [1] = "701021:n(701022)",
                [2] = "701022:n(701022)",
                [3] = "100001:n(701022)",
                [4] = "701023:n(701022)",
                },
            ["NextDialogue"] = 51117047,
            ["SpeakNpcId"] = 701021,
            ["TalkActionId"] = {
                [1] = "701022:Talk01_End",
                },
            },
        [51117047] = {
            ["Content"] = "那你们还在这儿玩什么呀，赶快回去做功课啦。",
            ["ContentJP"] = "そんなこと言ってる場合？早く帰って宿題しなよ〜！",
            ["DialogueId"] = 51117047,
            ["GUID"] = "7FF75686",
            ["LookAt"] = {
                [1] = "701021:n(701023)",
                [2] = "701022:n(701023)",
                [3] = "100001:n(701023)",
                [4] = "701023:n(701023)",
                },
            ["NextDialogue"] = 51117048,
            ["SpeakNpcId"] = 701023,
            },
        [51117048] = {
            ["Content"] = "（孩子们有说有笑地离开了。也许，下次见到扶疏的时候，可以把这件趣闻说给她听听。）",
            ["ContentJP"] = "子どもたちは、笑い声を残して駆けていった。いつかまたフーシュに会えたなら、このちょっと不思議で、ちょっと楽しい出来事を、話してあげようかな。",
            ["DialogueId"] = 51117048,
            ["GUID"] = "7FF756B0",
            ["Scripts"] = "PARA{\
MoveTo{ActorId{701021},TargetPoint{\"LanYe_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701022},TargetPoint{\"WangNan_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701023},TargetPoint{\"YuXian_Leave_Target\"},MoveSpeed{100},Visibility{\"Hide\"}}\
}",
            },
        [51118000] = {
            ["Content"] = "呜……怎么还没来……",
            ["ContentJP"] = "うぅ……まだかな……",
            ["DialogueId"] = 51118000,
            ["GUID"] = "7FF7F2E0",
            ["NextDialogue"] = 51118001,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Sigh_Start",
                },
            },
        [51118001] = {
            ["Content"] = "（小女孩半睁着眼睛，坐在屋檐下嘟囔着什么。当你经过的时候，她忽然一头栽倒在地。）",
            ["ContentJP"] = "小さな女の子が、軒下でまどろむように座っている。あなたが通りかかったそのとき、ふらりと前のめりに倒れ込んだ。",
            ["DialogueId"] = 51118001,
            ["GUID"] = "7FF7F30A",
            ["NextDialogue"] = 51118002,
            },
        [51118002] = {
            ["Content"] = "哎？！",
            ["ContentJP"] = "えっ！？",
            ["DialogueId"] = 51118002,
            ["GUID"] = "7FF7F334",
            ["NextDialogue"] = 51118003,
            ["SpeakNpcId"] = 100001,
            },
        [51118003] = {
            ["Content"] = "（你连忙上前查看。被你拍了拍肩膀之后，小女孩睁开眼睛，从地上爬了起来。）",
            ["ContentJP"] = "慌てて駆け寄り、肩を軽く叩くと、女の子は目を開け、もそもそと体を起こした。",
            ["DialogueId"] = 51118003,
            ["GUID"] = "7FF7F35E",
            ["NextDialogue"] = 51118004,
            },
        [51118004] = {
            ["Content"] = "唔……",
            ["ContentJP"] = "んん……",
            ["DialogueId"] = 51118004,
            ["GUID"] = "7FF7F388",
            ["NextOptions"] = {
                [1] = 51118005,
                },
            ["SpeakNpcId"] = 701024,
            },
        [51118005] = {
            ["Content"] = "小妹妹，你还好吗？",
            ["ContentJP"] = "君、大丈夫？",
            ["DialogueId"] = 51118005,
            ["GUID"] = "7FF7F3B2",
            ["NextDialogue"] = 51118006,
            },
        [51118006] = {
            ["Content"] = "啊，我没事，我只是太困了……谢谢你，{性别：大哥哥|大姐姐}。",
            ["ContentJP"] = "あっ……へへ、大丈夫。ちょっと、眠かっただけ……ありがとう、{性别:お兄さん|お姉さん}。",
            ["DialogueId"] = 51118006,
            ["GUID"] = "7FF7F3DC",
            ["LookAt"] = {
                [1] = "701024:n(0)",
                },
            ["NextDialogue"] = 51118007,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Sigh_End",
                },
            },
        [51118007] = {
            ["Content"] = "既然困了，怎么不回去休息？",
            ["ContentJP"] = "そんなに眠いなら、家で休めばいいのに。",
            ["DialogueId"] = 51118007,
            ["GUID"] = "7FF7F406",
            ["NextDialogue"] = 51118008,
            ["SpeakNpcId"] = 100001,
            },
        [51118008] = {
            ["Content"] = "我在等我哥哥！他是个织星客，平常总是在外面游历，但每年这个时候，他都会带礼物和信给我。",
            ["ContentJP"] = "わたし……お兄ちゃんを待ってるの。星織人っていう旅の仕事をしてて、いつも遠くに行ってるけど……毎年この時期だけは、手紙とお土産を持って帰ってきてくれるの。",
            ["DialogueId"] = 51118008,
            ["GUID"] = "7FF7F430",
            ["NextDialogue"] = 51118009,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_Start",
                },
            },
        [51118009] = {
            ["Content"] = "不能在家里等吗？",
            ["ContentJP"] = "家の中で待てばいいんじゃない？",
            ["DialogueId"] = 51118009,
            ["GUID"] = "7FF7F45A",
            ["NextDialogue"] = 51118010,
            ["SpeakNpcId"] = 100001,
            },
        [51118010] = {
            ["Content"] = "那就会和他错过了。他每次来都不进家门，只会早早地把东西放在门口。等我起床看到的时候，他早就不见了。",
            ["ContentJP"] = "それじゃ、またすれ違っちゃう。お兄ちゃん、絶対に家には入らないの。いつも夜のうちに玄関に置いて、わたしが目を覚ますころには、もういなくなってるの。",
            ["DialogueId"] = 51118010,
            ["GUID"] = "7FF7F484",
            ["NextDialogue"] = 51118011,
            ["SpeakNpcId"] = 701024,
            },
        [51118011] = {
            ["Content"] = "所以我今年打算在门口等着，一定要当面见到他！",
            ["ContentJP"] = "だから今年は、ぜったいに会おうと思って！",
            ["DialogueId"] = 51118011,
            ["GUID"] = "7FF7F4AE",
            ["NextDialogue"] = 51118012,
            ["SpeakNpcId"] = 701024,
            },
        [51118012] = {
            ["Content"] = "但我也不知道他会几点来，所以只好从三更天就开始等……哈欠……结果等到现在他也没来……哈欠……",
            ["ContentJP"] = "でもいつ来るかわからないから、夜中からずっとここで……ふわぁ……待ってるんだけど……来ないんだぁ……",
            ["DialogueId"] = 51118012,
            ["GUID"] = "7FF7F4D8",
            ["NextOptions"] = {
                [1] = 51118013,
                },
            ["RestartTag"] = 51118012,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_End",
                },
            },
        [51118013] = {
            ["Content"] = "（想想该怎么帮助她。）",
            ["ContentJP"] = "（なんとかしてあげたい。）",
            ["DialogueId"] = 51118013,
            ["FailDialogue"] = 51118014,
            ["GUID"] = "7FF7F502",
            ["ImprCheckId"] = 1126,
            ["NextDialogue"] = 51118015,
            },
        [51118014] = {
            ["Content"] = "（哈欠……你也有点困了。）",
            ["ContentJP"] = "（考えてるうちに、なんだか眠くなってきた……）",
            ["DialogueId"] = 51118014,
            ["GUID"] = "7FF7F52C",
            },
        [51118015] = {
            ["Content"] = "会不会就是因为你在这里等着，所以他才不出现的？",
            ["ContentJP"] = "……もしかすると、君がここで待ってるから来られないのかも。",
            ["DialogueId"] = 51118015,
            ["GUID"] = "7FF7F556",
            ["NextDialogue"] = 51118016,
            ["SpeakNpcId"] = 100001,
            },
        [51118016] = {
            ["Content"] = "咦？什么意思？",
            ["ContentJP"] = "え？どういうこと？",
            ["DialogueId"] = 51118016,
            ["GUID"] = "7FF7F580",
            ["NextDialogue"] = 51118017,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_Start",
                },
            },
        [51118017] = {
            ["Content"] = "也许他是想要给你一个惊喜啊。",
            ["ContentJP"] = "君をびっくりさせたくて、こっそり来てるのかもしれないよ。",
            ["DialogueId"] = 51118017,
            ["GUID"] = "7FF7F5AA",
            ["NextDialogue"] = 51118018,
            ["SpeakNpcId"] = 100001,
            },
        [51118018] = {
            ["Content"] = "可是比起惊喜，我更想见到他……",
            ["ContentJP"] = "そんなのいらない。ただ、会いたいの……",
            ["DialogueId"] = 51118018,
            ["GUID"] = "7FF7F5D4",
            ["NextDialogue"] = 51118019,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_End",
                },
            },
        [51118019] = {
            ["Content"] = "那我有个办法。",
            ["ContentJP"] = "それじゃ、こうしよう。",
            ["DialogueId"] = 51118019,
            ["GUID"] = "7FF7F5FE",
            ["NextDialogue"] = 51118020,
            ["SpeakNpcId"] = 100001,
            },
        [51118020] = {
            ["Content"] = "你现在进屋去，假装休息。我到对面的角落帮你盯着这扇门，如果看到你哥哥出现，我就把他拦下来。怎么样？",
            ["ContentJP"] = "{性别:君はおうちに戻って、寝たふりをするんだ。僕がここで見張ってる。お兄さんが来たら、引き留めるからさ。|君はおうちに戻って、寝たふりをするんだ。私がここで見張ってる。お兄さんが来たら、引き留めるからさ。}",
            ["DialogueId"] = 51118020,
            ["GUID"] = "7FF7F628",
            ["NextDialogue"] = 51118021,
            ["SpeakNpcId"] = 100001,
            },
        [51118021] = {
            ["Content"] = "哈欠……咦？！所以，{性别：大哥哥|大姐姐}你要帮我等吗？好呀好呀，你真是个好人！",
            ["ContentJP"] = "えっ……ほんとに？わあっ、{性别:お兄さん|お姉さん}、ありがとう！あなた、いい人だね！",
            ["DialogueId"] = 51118021,
            ["GUID"] = "7FF7F652",
            ["NextDialogue"] = 51118022,
            ["SpeakNpcId"] = 701024,
            },
        [51118022] = {
            ["Content"] = "你哥哥叫什么名字？",
            ["ContentJP"] = "ところで、お兄さんの名前は？",
            ["DialogueId"] = 51118022,
            ["GUID"] = "7FF7F67C",
            ["NextDialogue"] = 51118023,
            ["SpeakNpcId"] = 100001,
            },
        [51118023] = {
            ["Content"] = "他叫朝雨。",
            ["ContentJP"] = "チョウユだよ！",
            ["DialogueId"] = 51118023,
            ["GUID"] = "7FF7F6A6",
            ["NextDialogue"] = 51118024,
            ["SpeakNpcId"] = 701024,
            },
        [51118024] = {
            ["Content"] = "好的，我记住了。",
            ["ContentJP"] = "了解。",
            ["DialogueId"] = 51118024,
            ["GUID"] = "7FF7F6D0",
            ["NextDialogue"] = 51118025,
            ["SpeakNpcId"] = 100001,
            },
        [51118025] = {
            ["Content"] = "（女孩揉着眼睛，晃晃悠悠地进屋休息去了。你来到角落，悄悄观察周围的动静。）",
            ["ContentJP"] = "少女は、少しほっとした顔で目をこすりながら、ふらふらと家の中へ戻っていった。あなたは静かに物陰に身を潜め、玄関を見つめる。",
            ["DialogueId"] = 51118025,
            ["GUID"] = "7FF7F6FA",
            },
        [51118026] = {
            ["Content"] = "（果不其然，就在女孩离开后没多久，一位青年男子便现身了。他四下打量了一番，飞快地将一个包裹放在了门口，然后转身离去。）",
            ["ContentJP"] = "それから間もなく、ひとりの青年が姿を現す。周囲を素早く見回すと、包みをそっと玄関先に置き、すぐに踵を返した。",
            ["DialogueId"] = 51118026,
            ["GUID"] = "7FF7F724",
            },
        [51118027] = {
            ["Content"] = "等等！",
            ["ContentJP"] = "待って！",
            ["DialogueId"] = 51118027,
            ["GUID"] = "7FF7F74E",
            ["LookAt"] = {
                [1] = "701025:n(0)",
                },
            ["NextDialogue"] = 51118028,
            ["SpeakNpcId"] = 100001,
            },
        [51118028] = {
            ["Content"] = "哎？！",
            ["ContentJP"] = "……えっ？",
            ["DialogueId"] = 51118028,
            ["GUID"] = "7FF7F778",
            ["NextDialogue"] = 51118029,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Shock_Start",
                },
            },
        [51118029] = {
            ["Content"] = "你就是朝雨吧！",
            ["ContentJP"] = "あなたがチョウユさん、だよね？",
            ["DialogueId"] = 51118029,
            ["GUID"] = "7FF7F7A2",
            ["NextDialogue"] = 51118030,
            ["SpeakNpcId"] = 100001,
            },
        [51118030] = {
            ["Content"] = "（听到这个名字，男子显得很惊讶。他愣了一会儿，然后才开口。）",
            ["ContentJP"] = "その名に、男の表情がこわばる。目を伏せたまま、しばらく沈黙ののち、小さく息を吐いた。",
            ["DialogueId"] = 51118030,
            ["GUID"] = "7FF7F7CC",
            ["NextDialogue"] = 51118031,
            ["TalkActionId"] = {
                [1] = "701025:Shock_End",
                },
            },
        [51118031] = {
            ["Content"] = "不……我不是朝雨。",
            ["ContentJP"] = "……違うよ。",
            ["DialogueId"] = 51118031,
            ["GUID"] = "7FF7F7F6",
            ["NextDialogue"] = 51118032,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk01_Start",
                },
            },
        [51118032] = {
            ["Content"] = "你为何会知道这个名字？你认识他吗？",
            ["ContentJP"] = "どうして、その名を？",
            ["DialogueId"] = 51118032,
            ["GUID"] = "7FF7F820",
            ["NextDialogue"] = 51118033,
            ["SpeakNpcId"] = 701025,
            },
        [51118033] = {
            ["Content"] = "我认识他的妹妹，他妹妹一直在等他出现。",
            ["ContentJP"] = "妹さんが、ずっと彼を待ってる{性别:んだ|の}。今日も朝早くから、ずっと……",
            ["DialogueId"] = 51118033,
            ["GUID"] = "7FF7F84A",
            ["NextDialogue"] = 51118034,
            ["SpeakNpcId"] = 100001,
            },
        [51118034] = {
            ["Content"] = "是吗……原来青青一直坐在门口，是想见哥哥啊。",
            ["ContentJP"] = "……そうか……セイセイ、やっぱり今年も……",
            ["DialogueId"] = 51118034,
            ["GUID"] = "7FF7F874",
            ["NextDialogue"] = 51118035,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk01_End",
                },
            },
        [51118035] = {
            ["Content"] = "但她怕是等不到了。",
            ["ContentJP"] = "でも、もう彼女が望む兄には、会えない。",
            ["DialogueId"] = 51118035,
            ["GUID"] = "7FF7F89E",
            ["NextDialogue"] = 51118036,
            ["SpeakNpcId"] = 701025,
            },
        [51118036] = {
            ["Content"] = "为什么？你是谁？",
            ["ContentJP"] = "……どういうこと？",
            ["DialogueId"] = 51118036,
            ["GUID"] = "7FF7F8C8",
            ["NextDialogue"] = 51118037,
            ["SpeakNpcId"] = 100001,
            },
        [51118037] = {
            ["Content"] = "我是朝雨的旧友。几年前，我们在同一个商队出海远航时，不慎遭遇了海难。朝雨他……为了救不通水性的我，不幸去世了。",
            ["ContentJP"] = "俺は、チョウユの旅の仲間だった。数年前、一緒に海を越える航路に出たとき、大きな嵐に巻き込まれて――泳げなかった俺を、チョウユは助けようとして……そのまま……",
            ["DialogueId"] = 51118037,
            ["GUID"] = "7FF7F8F2",
            ["NextDialogue"] = 51118038,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk02_Start",
                },
            },
        [51118038] = {
            ["Content"] = "这份救命之恩，我无以为报……但至少不忍看他疼爱的幼妹伤心，所以就想了这个办法。",
            ["ContentJP"] = "その恩は、一生かけても返しきれない。せめて妹さんを悲しませたくなかったんだ。",
            ["DialogueId"] = 51118038,
            ["GUID"] = "7FF7F91C",
            ["NextDialogue"] = 51118039,
            ["SpeakNpcId"] = 701025,
            },
        [51118039] = {
            ["Content"] = "在青青成年之前，我会假装成朝雨，每年给她送来礼物和信件。",
            ["ContentJP"] = "だから、こうして毎年「チョウユ」として、贈り物と手紙を届けてる。",
            ["DialogueId"] = 51118039,
            ["GUID"] = "7FF7F946",
            ["NextDialogue"] = 51118040,
            ["SpeakNpcId"] = 701025,
            },
        [51118040] = {
            ["Content"] = "竟然是这样……",
            ["ContentJP"] = "……そんなことが……",
            ["DialogueId"] = 51118040,
            ["GUID"] = "7FF7F970",
            ["NextDialogue"] = 51118041,
            ["SpeakNpcId"] = 100001,
            },
        [51118041] = {
            ["Content"] = "是的……所以，还请你对青青保密。",
            ["ContentJP"] = "だから、お願いだ。セイセイには、何も言わないでほしい。",
            ["DialogueId"] = 51118041,
            ["GUID"] = "7FF7F99A",
            ["NextDialogue"] = 51118042,
            ["SpeakNpcId"] = 701025,
            ["TalkActionId"] = {
                [1] = "701025:Talk02_End",
                },
            },
        [51118042] = {
            ["Content"] = "我明白了。",
            ["ContentJP"] = "わかった。",
            ["DialogueId"] = 51118042,
            ["GUID"] = "7FF7F9C4",
            ["SpeakNpcId"] = 100001,
            },
        [51118043] = {
            ["Camera"] = "-82.615234,229.359375,122.754883,0.0,-0.800191,-69.000504,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（你思考了一会儿，然后敲了敲门。）",
            ["ContentJP"] = "あなたは軽く息を整え、扉をそっとノックする。",
            ["DialogueId"] = 51118043,
            ["GUID"] = "7FF7F9EE",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "701024:n(100001)",
                [2] = "100001:n(701024)",
                },
            ["NextDialogue"] = 51118062,
            },
        [51118044] = {
            ["Content"] = "青青？",
            ["ContentJP"] = "セイセイ？",
            ["DialogueId"] = 51118044,
            ["GUID"] = "7FF7FA18",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51118045,
            },
        [51118045] = {
            ["Content"] = "{性别：大哥哥|大姐姐}，怎么啦？咦，你手上那是——是哥哥来了吗？他在哪里？",
            ["ContentJP"] = "{性别:お兄さん|お姉さん}、どうしたの？あれ、その手紙……お兄ちゃんが来たの！？どこにいるの？",
            ["DialogueId"] = 51118045,
            ["GUID"] = "7FF7FA42",
            ["NextDialogue"] = 51118046,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk01_Start",
                },
            },
        [51118046] = {
            ["Content"] = "他已经走了。",
            ["ContentJP"] = "……もう、帰っちゃったよ。",
            ["DialogueId"] = 51118046,
            ["GUID"] = "7FF7FA6C",
            ["NextDialogue"] = 51118047,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701024:Talk01_End",
                [2] = "100001:Talk02_Start",
                },
            },
        [51118047] = {
            ["Content"] = "什么？你不是答应我要拦下他的吗？呜呜……",
            ["ContentJP"] = "えっ……でも、止めてくれるって……言ってくれたのに……うぅ、ひどいよ……",
            ["DialogueId"] = 51118047,
            ["GUID"] = "7FF7FA96",
            ["NextOptions"] = {
                [1] = 51118048,
                [2] = 51118052,
                },
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            },
        [51118048] = {
            ["Content"] = "你哥哥工作很辛苦，不想让你担心。",
            ["ContentJP"] = "お兄さん、君に心配かけたくなかったんだよ。",
            ["DialogueId"] = 51118048,
            ["GUID"] = "7FF7FAC0",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51118049,
            },
        [51118049] = {
            ["Content"] = "他说自己常年风餐露宿，消瘦了不少，怕你看见会担心，所以才不露面。我看他好像很累，就没有强行拦下他。",
            ["ContentJP"] = "お兄さんね、旅ばかりで痩せちゃってた。そんな姿、君に見せたくなかったんだって。その顔を見て、無理には止められなかった。",
            ["DialogueId"] = 51118049,
            ["GUID"] = "7FF7FAEA",
            ["NextDialogue"] = 51118050,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51118050] = {
            ["Content"] = "居然是这样……可是见不到他我会更担心呀，笨哥哥……",
            ["ContentJP"] = "……そっか……余計に心配になっちゃうよ……もう、バカ……",
            ["DialogueId"] = 51118050,
            ["GUID"] = "7FF7FB14",
            ["NextDialogue"] = 51118051,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                [2] = "701024:Think_Start",
                },
            },
        [51118051] = {
            ["Content"] = "他说等他身体好一点，就一定会回来看你的。在那之前，你要照顾好自己。",
            ["ContentJP"] = "でもね、言ってたよ。体が元気になったら、今度こそちゃんと会いにくるって。だから、それまで元気でいてって。",
            ["DialogueId"] = 51118051,
            ["GUID"] = "7FF7FB3E",
            ["NextDialogue"] = 51118058,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701024:Think_End",
                },
            },
        [51118052] = {
            ["Content"] = "你哥哥在参加一场超级商战，分秒必争！",
            ["ContentJP"] = "お兄さんね、「大事な商戦」で忙しいんだ。一秒すら命取りなんだよ。",
            ["DialogueId"] = 51118052,
            ["GUID"] = "7FF7FB68",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51118053,
            },
        [51118053] = {
            ["Content"] = "“商战”……？那是什么？",
            ["ContentJP"] = "「商戦」……？",
            ["DialogueId"] = 51118053,
            ["GUID"] = "7FF7FB92",
            ["NextDialogue"] = 51118054,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_Start",
                },
            },
        [51118054] = {
            ["Content"] = "商战就是一种比谁挣钱更多、更快的游戏。你哥哥想要赢下第一名，所以一秒钟都不能耽误呢！",
            ["ContentJP"] = "うん。誰がいちばん早く、いちばん上手に稼げるかを競う、商人たちの決戦だよ。お兄さん、その頂点を目指してるんだって。",
            ["DialogueId"] = 51118054,
            ["GUID"] = "7FF7FBBC",
            ["NextDialogue"] = 51118055,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51118055] = {
            ["Content"] = "刚才他一放下礼物就跑了，这些还是他的同事告诉我的。",
            ["ContentJP"] = "さっきも、贈り物を置いた瞬間、すぐに走って行っちゃったよ。あとで通りかかった仲間の人が教えてくれたんだ。",
            ["DialogueId"] = 51118055,
            ["GUID"] = "7FF7FBE6",
            ["NextDialogue"] = 51118056,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            },
        [51118056] = {
            ["Content"] = "原来是这样啊！那我要给哥哥加油！",
            ["ContentJP"] = "……そっか。じゃあ、全力で応援しなくちゃね！",
            ["DialogueId"] = 51118056,
            ["GUID"] = "7FF7FC10",
            ["NextDialogue"] = 51118057,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Think_End",
                },
            },
        [51118057] = {
            ["Content"] = "他说你只要照顾好自己就行了，等他赢了游戏，一定会回来看你的。",
            ["ContentJP"] = "お兄さん、言ってたよ。「セイセイが元気でいてくれるなら、それがいちばんの力になる」って。勝負がついたら、会いに来るって。",
            ["DialogueId"] = 51118057,
            ["GUID"] = "7FF7FC3A",
            ["NextDialogue"] = 51118058,
            ["SpeakNpcId"] = 100001,
            },
        [51118058] = {
            ["Content"] = "嗯嗯，那我要回去好好睡一觉，不然哥哥会担心的……",
            ["ContentJP"] = "うん……わたし、ちゃんと食べて、ちゃんと寝て、元気で待ってる。",
            ["DialogueId"] = 51118058,
            ["GUID"] = "7FF7FC64",
            ["NextDialogue"] = 51118059,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_Start",
                },
            },
        [51118059] = {
            ["Content"] = "谢谢你帮我，{性别：大哥哥|大姐姐}，再见……哈欠……",
            ["ContentJP"] = "ありがとう、{性别:お兄さん|お姉さん}。おやすみなさい……ふぁぁ……",
            ["DialogueId"] = 51118059,
            ["GUID"] = "7FF7FC8E",
            ["NextDialogue"] = 51118060,
            ["SpeakNpcId"] = 701024,
            ["TalkActionId"] = {
                [1] = "701024:Talk02_End",
                },
            },
        [51118060] = {
            ["Content"] = "（女孩给了你报酬，然后带着一脸满足的笑容接过礼物，进屋去了。）",
            ["ContentJP"] = "少女は小さな礼の品を手渡し、胸に贈り物を抱いたまま、満ち足りた笑顔で家の中へと戻っていった。",
            ["DialogueId"] = 51118060,
            ["GUID"] = "7FF7FCB8",
            ["NextDialogue"] = 51118061,
            },
        [51118061] = {
            ["Content"] = "（等到真相被揭穿的那一天，她还能再露出这样的笑容吗……？）",
            ["ContentJP"] = "――この物語が、真実と出会うその日まで。せめて、あの微笑みだけは、変わらずにいてほしい。",
            ["DialogueId"] = 51118061,
            ["GUID"] = "7FF7FCE2",
            },
        [51118062] = {
            ["Content"] = "（青青打着哈欠走了出来。）",
            ["ContentJP"] = "(セイセイはあくびをしながら出てきた）。",
            ["DialogueId"] = 51118062,
            ["GUID"] = "7FF7FD0C",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 51118044,
                },
            },
        [51119000] = {
            ["Content"] = "金口一张白龙降，折扇轻摇故事来。诸位乡亲，诸位父老，诸位不远万里来到华胥的外乡客，大家且听我一言！",
            ["ContentJP"] = "金の口がひらけば白龍が舞い、扇ひとつで物語が生まれる――さてさて、<Default note=\"text:カショ\">華胥</>にお集まりの皆々さま、里の衆も、遠路はるばるやって来た旅のお方も、どうかこの全通先生に耳をお貸しくだされ！",
            ["DialogueId"] = 51119000,
            ["GUID"] = "7FF896F0",
            ["NextDialogue"] = 51119001,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk01_Start",
                },
            },
        [51119001] = {
            ["Content"] = "鄙人名唤权都通，曾被白龙神君赐号——全通先生。平时最爱与诸位挚爱亲朋分享这世间百态趣事，今日便有一桩趣闻想与各位说道说道。",
            ["ContentJP"] = "拙者の名はゼンブツウ、かつて白龍様より「全通」なる異名を賜った――などと申せば、皆さま少しは興味を持ってくださるかと思いまして。",
            ["DialogueId"] = 51119001,
            ["GUID"] = "7FF8971A",
            ["NextDialogue"] = 51119002,
            ["SpeakNpcId"] = 701026,
            },
        [51119002] = {
            ["Content"] = "不过呢……今日天气燥热，我这喉咙啊也焦渴难耐，若是诸位能先赏点银钱让我买壶茶水润润喉咙，或许这故事就能说得更好。",
            ["ContentJP"] = "……なのですが、いかんせん、この陽気。喉がからからでございましてな……もしよろしければ、茶代の銭を少々恵んでいただければ、この話も一層、滑らかになるかと。",
            ["DialogueId"] = 51119002,
            ["GUID"] = "7FF89744",
            ["LookAt"] = {
                [1] = "701026:n(0)",
                },
            ["NextOptions"] = {
                [1] = 51119003,
                [2] = 51119005,
                [3] = 51119007,
                },
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk01_End",
                },
            },
        [51119003] = {
            ["Content"] = "白龙神君赐号？骗人的吧？",
            ["ContentJP"] = "白龍様から……？それ、ウソでしょ",
            ["DialogueId"] = 51119003,
            ["GUID"] = "7FF8976E",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51119004,
            },
        [51119004] = {
            ["Content"] = "名号的确是假的，白龙神君并未与我赐号，但要不是如此吆喝，如何才能让诸位听众驻足呢？白龙神君即使知晓，想必也不会怪罪于我。",
            ["ContentJP"] = "まあ、嘘です。白龍様にそんなありがたいお言葉を頂いたことはございません。けれど、こうでも言わねば誰も足を止めてはくださらぬでしょう？白龍様も、それくらいはお許しくださると信じております。",
            ["DialogueId"] = 51119004,
            ["GUID"] = "7FF89798",
            ["NextDialogue"] = 51119009,
            ["SpeakNpcId"] = 701026,
            },
        [51119005] = {
            ["Content"] = "你得说的好才能讨钱吧。",
            ["ContentJP"] = "面白くないと、お金払いたくないな。",
            ["DialogueId"] = 51119005,
            ["GUID"] = "7FF897C2",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51119006,
            },
        [51119006] = {
            ["Content"] = "这位外乡客说的是，此举只凭自愿，绝无要挟之意，只是看各位父老是否愿意先让我们龙君青睐的信众喝上口水，解我燃喉之急啊。",
            ["ContentJP"] = "ははっ、ごもっとも。けれどこの商い、強制ではございません。ただ、信仰深き白龍様の御民として、一杯の茶がこの身に潤いを与えてくだされば――それだけで十分にございます。",
            ["DialogueId"] = 51119006,
            ["GUID"] = "7FF897EC",
            ["NextDialogue"] = 51119009,
            ["SpeakNpcId"] = 701026,
            },
        [51119007] = {
            ["Content"] = "（给他点银钱买茶水。）",
            ["ContentJP"] = "茶代の銀貨を渡す。",
            ["DialogueId"] = 51119007,
            ["GUID"] = "7FF89816",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51119008,
            },
        [51119008] = {
            ["Content"] = "感谢感谢，外乡客，鄙人记住你的恩情了。",
            ["ContentJP"] = "ありがたや、ありがたや……旅のお方、そのご厚意、しかと胸に刻みましたぞ。",
            ["DialogueId"] = 51119008,
            ["GUID"] = "7FF89840",
            ["NextDialogue"] = 51119009,
            ["SpeakNpcId"] = 701026,
            },
        [51119009] = {
            ["Content"] = "（一些不差钱的围观者递上了银钱，远处很快跑来一名端茶之人，这权都通接过紫砂壶，猛地灌了一口，这才继续说起来。）",
            ["ContentJP"] = "懐に余裕のある見物人たちが次々と銀貨を差し出すと、ほどなくして、茶壺を抱えた使いの者が駆けてきた。全通先生は紫砂の急須を受け取るなり、ごくりと喉を鳴らし、大きく一息――そして、また語り口を開いた。",
            ["DialogueId"] = 51119009,
            ["GUID"] = "7FF8986A",
            ["NextDialogue"] = 51119010,
            },
        [51119010] = {
            ["Content"] = "感谢诸位信任，今日，我权都通就为大家说上一个我才听说的趣闻。",
            ["ContentJP"] = "いやはや、感謝感激。皆さまのおかげで声が戻りました。では、参りましょう――",
            ["DialogueId"] = 51119010,
            ["GUID"] = "7FF89894",
            ["NextDialogue"] = 51119011,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk02_Start",
                },
            },
        [51119011] = {
            ["Content"] = "这华胥境内，哪里最繁华？自然是那皓京城中，这事儿，就发生在皓京。皓京城内呢，有一条狭窄的小巷，巷子两边都住着一户人家，一家姓吕，一家姓马。",
            ["ContentJP"] = "さて、<Default note=\"text:カショ\">華胥</>の地で最も栄えた場所といえば？そう、<Default note=\"text:こうけい\">皓京</>城。その賑わいの中にある細い路地での出来事でございます。その路地には、向かい合うように二つの家がありました。片やロ家、片やバ家――",
            ["DialogueId"] = 51119011,
            ["GUID"] = "7FF898BE",
            ["NextDialogue"] = 51119012,
            ["SpeakNpcId"] = 701026,
            },
        [51119012] = {
            ["Content"] = "这两家，平日相处很是和睦，端的是相敬如宾啊，但天有变迁，这皓京城内的天禄司，因着皓京城许多住宅年久失修问题，要各家上报宅邸面积。",
            ["ContentJP"] = "日頃はまことに礼を尽くす、良き隣人同士でございました。ところがある日、城の<Default note=\"text:てんろくし\">天禄司</>からお達しが。「古くなった家々を修繕するため、各戸の敷地面積を報告せよ」と。",
            ["DialogueId"] = 51119012,
            ["GUID"] = "7FF898E8",
            ["NextDialogue"] = 51119013,
            ["SpeakNpcId"] = 701026,
            },
        [51119013] = {
            ["Content"] = "这事闹得，上报上去的面积到时候可就是天禄司需要出钱的部分了，为着让上面多关照自家，这吕马两家啊，不约而同都开始琢磨起了扩建一事。",
            ["ContentJP"] = "修繕の費用は国が持つ。ならば、と皆が少しでも広く申告しようとするのは人の性。ロ家もバ家も、どうにか自宅の「領域」を広く見せようと考え始めたのです。",
            ["DialogueId"] = 51119013,
            ["GUID"] = "7FF89912",
            ["NextDialogue"] = 51119014,
            ["SpeakNpcId"] = 701026,
            },
        [51119014] = {
            ["Content"] = "但这小巷之间的地块此前并非两家所属，但也并无文书说明巷中空地归属，这一下可就陷入了僵局。",
            ["ContentJP"] = "だが問題がひとつ。ふたりの家の間にある細い空き地――そこは誰の所有とも記されておらぬ曖昧な場所でありました。",
            ["DialogueId"] = 51119014,
            ["GUID"] = "7FF8993C",
            ["NextDialogue"] = 51119015,
            ["SpeakNpcId"] = 701026,
            },
        [51119015] = {
            ["Content"] = "吕家说自己院中种了棵梨树，树荫早已罩住巷子，所以那地该是自家的。",
            ["ContentJP"] = "ロ家は言います。「我が庭の梨の木の影が、もうずっとその地を覆っている。ならば、我が敷地であろう」と。",
            ["DialogueId"] = 51119015,
            ["GUID"] = "7FF89966",
            ["NextDialogue"] = 51119016,
            ["SpeakNpcId"] = 701026,
            },
        [51119016] = {
            ["Content"] = "马家却说自己原先一直将家中香料放在巷内晾晒，吕家也从未提出异议，说明这地该是他家的呀。",
            ["ContentJP"] = "バ家は言います。「うちはいつも香料をそこに干しておる。ロ家も黙認していたではないか。ならば、うちのものだ」と。",
            ["DialogueId"] = 51119016,
            ["GUID"] = "7FF89990",
            ["NextDialogue"] = 51119017,
            ["SpeakNpcId"] = 701026,
            },
        [51119017] = {
            ["Content"] = "这双方，各执一词，那是吵个昏天黑地，要不是咱们大风九章在上，肯定是要撕打起来的。",
            ["ContentJP"] = "互いに譲らず、言い争いは日ごとに激しさを増し……あやうく手が出るところを、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の掟がかろうじて抑えていた――というわけです。",
            ["DialogueId"] = 51119017,
            ["GUID"] = "7FF899BA",
            ["NextDialogue"] = 51119018,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Talk02_End",
                },
            },
        [51119018] = {
            ["Content"] = "但话又说到这了，两家都有理，难道此事就没办法了吗？",
            ["ContentJP"] = "さて、ここで皆さまに問いたい。この争い、どうすれば収まると思います？",
            ["DialogueId"] = 51119018,
            ["GUID"] = "7FF899E4",
            ["NextDialogue"] = 51119019,
            ["SpeakNpcId"] = 701026,
            },
        [51119019] = {
            ["Content"] = "（权都通特意顿了一下，似乎在吊人胃口。）",
            ["ContentJP"] = "ここで、全通先生一拍置いて、観客の期待を煽る。",
            ["DialogueId"] = 51119019,
            ["GUID"] = "7FF89A0E",
            ["NextDialogue"] = 51119020,
            },
        [51119020] = {
            ["Content"] = "对了，大家可别忘了，那可是皓京城，自然是有着许多管理邻里纷争的调解人。",
            ["ContentJP"] = "<Default note=\"text:こうけい\">皓京</>のような大都市には、もちろんおりましてな――こういった揉め事をおさめる「調停人」と呼ばれる者たちが。",
            ["DialogueId"] = 51119020,
            ["GUID"] = "7FF89A38",
            ["NextDialogue"] = 51119021,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Explain01_Start",
                },
            },
        [51119021] = {
            ["Content"] = "那调解人，一听说此事，便马不停蹄地赶去了，调解者一听两家说出了自己的理由，却是幽幽一笑，当场作诗一首：",
            ["ContentJP"] = "その調停人が駆けつけ、両家の言い分を聞くや否や、ふっと笑って、詩をひとつ詠んだそうな。",
            ["DialogueId"] = 51119021,
            ["GUID"] = "7FF89A62",
            ["NextDialogue"] = 51119022,
            ["SpeakNpcId"] = 701026,
            },
        [51119022] = {
            ["Content"] = "黑蛟鼓惑恶念起，龙君一怒断嗔痴。几番无果闹荒唐，让他三尺又何妨？",
            ["ContentJP"] = "黒蛟おだてて欲に呑まれ、龍神怒りて煩悩を断つ。争うばかりが道ならば――三尺譲って、何が減る。",
            ["DialogueId"] = 51119022,
            ["GUID"] = "7FF89A8C",
            ["NextDialogue"] = 51119023,
            ["SpeakNpcId"] = 701026,
            },
        [51119023] = {
            ["Content"] = "诶呀！这话的意思说明什么？诸位听众可能听出来？这是要将这争吵不停的二人比作神话里那为非作歹的黑蛟一般，要与白龙神君劝人向善之心对着来！",
            ["ContentJP"] = "さあ、どういう意味か、お分かりになりますか？争いに囚われるロ家とバ家を、悪しき蛟龍になぞらえたのです。白龍様の教えに背いてまで、己が欲を通そうとするとは――と。",
            ["DialogueId"] = 51119023,
            ["GUID"] = "7FF89AB6",
            ["NextDialogue"] = 51119024,
            ["SpeakNpcId"] = 701026,
            },
        [51119024] = {
            ["Content"] = "那烛阴恶兽因心生恶念，被白龙神君封印于荒野，而今日，为何在这泱泱华胥又生出贪嗔之人啊？此话一出，两家讪讪，不再争执，各自回去了。",
            ["ContentJP"] = "黒蛟はかつて、心の闇に呑まれたがゆえに、神君に封じられました。ならば、今またこの華胥で、何ゆえに貪りの心が芽吹こうというのか――調停人のその言葉に、両家は恥じ入り、争いをやめたそうです。",
            ["DialogueId"] = 51119024,
            ["GUID"] = "7FF89AE0",
            ["NextDialogue"] = 51119025,
            ["SpeakNpcId"] = 701026,
            },
        [51119025] = {
            ["Content"] = "于是吕家回去后，为表自己诚心，拆了自家院墙向后三尺，在门口立上了一座白龙神君的雕像。那马家见状，也将自己院墙拆除，向后三尺，摆了同样的雕像。",
            ["ContentJP"] = "ロ家は家の塀を三尺下げ、その跡に白龍様の像を祀りました。それを見たバ家もまた、同じように三尺譲って像を建てた。",
            ["DialogueId"] = 51119025,
            ["GUID"] = "7FF89B0A",
            ["NextDialogue"] = 51119026,
            ["SpeakNpcId"] = 701026,
            },
        [51119026] = {
            ["Content"] = "喜哉乐哉！息事宁哉！这巷子后来也成了附近邻居们每每发生争执之时前往理论之地，为的就是让白龙神君见证自己的虔诚之心，从未动摇啊！",
            ["ContentJP"] = "それ以来、近隣の者たちが争いごとを持ち込むたび、その前で誓いを立てるようになった――我が心、神君の御前に恥じぬものであると。",
            ["DialogueId"] = 51119026,
            ["GUID"] = "7FF89B34",
            ["NextDialogue"] = 51119027,
            ["SpeakNpcId"] = 701026,
            },
        [51119027] = {
            ["Content"] = "今日鄙人便斗胆改一下诗句，不若改为“向善之心何以见，三尺之争见真心。”诸位看客以为如何？",
            ["ContentJP"] = "拙者、この話にあやかって一句詠ませていただきます。「求めれば、三尺の神君様にも善の種」っと",
            ["DialogueId"] = 51119027,
            ["GUID"] = "7FF89B5E",
            ["NextDialogue"] = 51119028,
            ["SpeakNpcId"] = 701026,
            ["TalkActionId"] = {
                [1] = "701026:Explain01_End",
                },
            },
        [51119028] = {
            ["Content"] = "（路人纷纷向其喝彩，夸赞起白龙神君，权都通又收到了许多打赏，人群逐渐散去……）",
            ["ContentJP"] = "聴衆たちからは白龍神君を讃える声があがる。全通先生のもとには、次々と銭が投げ込まれた――そして、人々は笑顔で散っていった。",
            ["DialogueId"] = 51119028,
            ["GUID"] = "7FF89B88",
            ["Scripts"] = "PARA{\
MoveTo{ActorId{701081},TargetPoint{\"quandoutong_show1\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701082},TargetPoint{\"quandoutong_show2\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701083},TargetPoint{\"quandoutong_show3\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701084},TargetPoint{\"quandoutong_show4\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701085},TargetPoint{\"quandoutong_show5\"},MoveSpeed{100},Visibility{\"Hide\"}},\
MoveTo{ActorId{701086},TargetPoint{\"quandoutong_show6\"},MoveSpeed{100},Visibility{\"Hide\"}}\
}",
            },
        [51119029] = {
            ["Content"] = "有钱的捧个钱场，没钱的捧个人场！",
            ["ContentJP"] = "手持ちのある方は金を、ない方は歓声を出しとくれ！",
            ["DialogueId"] = 51119029,
            ["GUID"] = "7FF89BB2",
            ["SpeakNpcId"] = 701026,
            },
        [51120000] = {
            ["Content"] = "黄药师，此药服用后有何注意事项？可有忌口？",
            ["ContentJP"] = "コウさん、この薬、服用する際に気をつけることってありますか？食べちゃダメな物とか……",
            ["DialogueId"] = 51120000,
            ["GUID"] = "7FF93B00",
            ["LookAt"] = {
                [1] = "701028:n(701027)",
                [2] = "701027:n(701028)",
                },
            ["NextDialogue"] = 51120001,
            ["SpeakNpcId"] = 701028,
            ["TalkActionId"] = {
                [1] = "701028:Talk01_Start",
                },
            },
        [51120001] = {
            ["Content"] = "自然是有的，你要记得，药效如何全依据你是否遵守我以下所说：",
            ["ContentJP"] = "おやおや、当然ありますぞ。薬の効果というのは、服み方次第。私の言うこと、よーく聞いておくように。",
            ["DialogueId"] = 51120001,
            ["GUID"] = "7FF93B2A",
            ["NextDialogue"] = 51120002,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701028:Talk01_End",
                },
            },
        [51120002] = {
            ["Content"] = "其一，这药不可空腹服下，否则体重不减反增。你需一日三餐都吃半饱以上，方可服用。",
            ["ContentJP"] = "ひとつめ。空腹で飲んではいけませんぞ。かえって太るやもしれぬ。一日三食、最低でも腹七分は召し上がれ。",
            ["DialogueId"] = 51120002,
            ["GUID"] = "7FF93B54",
            ["NextDialogue"] = 51120003,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_Start",
                },
            },
        [51120003] = {
            ["Content"] = "其二，这药副作用猛烈，你需努力运动，我给你一本册子，你按这上面，每日运动一个时辰，直至大汗淋漓，我这药带来的副作用才可被排出。",
            ["ContentJP"] = "ふたつめ。この薬、効き目は強いが副作用も手強い。運動が欠かせません。これ、特製の運動冊子。これに従い、毎日2時間は汗をかくまで体を動かすこと。そうして初めて、余分なものが外に出ていく。",
            ["DialogueId"] = 51120003,
            ["GUID"] = "7FF93B7E",
            ["NextDialogue"] = 51120004,
            ["SpeakNpcId"] = 701027,
            },
        [51120004] = {
            ["Content"] = "其三，我这药最忌断药，你此次只从我这里买了一月的用量，一月后你需要尽快来我这购入下一月的，若是断药，则你前一个月的效果全都前功尽弃！",
            ["ContentJP"] = "みっつめ。何よりいけないのが、途中でやめること。今回は一ヶ月分しかお求めでないが、来月分を切らさず継続せねば、今月の努力が水の泡となりますぞ。",
            ["DialogueId"] = 51120004,
            ["GUID"] = "7FF93BA8",
            ["NextDialogue"] = 51120005,
            ["SpeakNpcId"] = 701027,
            },
        [51120005] = {
            ["Content"] = "就是这三点，你可记住了？",
            ["ContentJP"] = "以上、三か条。しっかり覚えましたかな？",
            ["DialogueId"] = 51120005,
            ["GUID"] = "7FF93BD2",
            ["NextDialogue"] = 51120006,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_End",
                },
            },
        [51120006] = {
            ["Content"] = "药师，我这记住是记住了，但这么复杂的要求，你真能保证我在三个月内瘦成一道闪电吗？",
            ["ContentJP"] = "覚えたのは覚えたけど……そんなに面倒なことして、ほんとに三ヶ月で見違えるほど痩せられるんですか？",
            ["DialogueId"] = 51120006,
            ["GUID"] = "7FF93BFC",
            ["NextDialogue"] = 51120007,
            ["SpeakNpcId"] = 701028,
            ["TalkActionId"] = {
                [1] = "701028:Think_Start",
                },
            },
        [51120007] = {
            ["Content"] = "小雁啊小雁，我黄药师何曾骗过人？若不是我的药灵验，你又如何才能找到我这来？",
            ["ContentJP"] = "ラクさんや……私が嘘をついたことがあるか？効かぬ薬なら、そもそもこの私の元に辿り着けるはずもなかろう。",
            ["DialogueId"] = 51120007,
            ["GUID"] = "7FF93C26",
            ["NextDialogue"] = 51120008,
            ["SpeakNpcId"] = 701027,
            },
        [51120008] = {
            ["Content"] = "好……好像是这个道理……我明白了，这次一定要瘦下去！",
            ["ContentJP"] = "そ、そう言われると……たしかに。よーし、今回は本気で痩せてみせます！",
            ["DialogueId"] = 51120008,
            ["GUID"] = "7FF93C50",
            ["NextDialogue"] = 51120009,
            ["SpeakNpcId"] = 701028,
            ["TalkActionId"] = {
                [1] = "701028:Think_End",
                },
            },
        }
  end },
  { MinKey = 51120009, MaxKey = 51125051, Loader = function()
      return {
        [51120009] = {
            ["Content"] = "（名唤小雁的女孩手持一瓶药，兴致勃勃地跑走了。）",
            ["ContentJP"] = "ラクガンと名乗る少女は薬の瓶をぎゅっと握りしめ、意気揚々とその場を後にした。",
            ["DialogueId"] = 51120009,
            ["GUID"] = "7FF93C7A",
            ["NextDialogue"] = 51120010,
            ["Scripts"] = "MoveTo{ActorId{701028},TargetPoint{\"LuoYan_Target\"},MoveSpeed{200},Visibility{\"Hide\"}}",
            },
        [51120010] = {
            ["Content"] = "客人好性子，在此处等待如此之久，定是有药相求，说吧，是保身体康健，还是如刚才的小姑娘一般，求个身材窈窕？",
            ["ContentJP"] = "さて……お客人、長らくお待ちいただきましたな。さぞ、何かお求めの薬があると見える。健康のためか？それとも……あの娘のように、細身の姿を目指すおつもりで？",
            ["DialogueId"] = 51120010,
            ["GUID"] = "7FF93CA4",
            ["LookAt"] = {
                [1] = "701027:n(0)",
                },
            ["NextOptions"] = {
                [1] = 51120011,
                [2] = 51120013,
                [3] = 51120015,
                },
            ["SpeakNpcId"] = 701027,
            },
        [51120011] = {
            ["Content"] = "你刚才说的要求，不用吃药也可以瘦下来吧……",
            ["ContentJP"] = "さっき言ってた条件、薬なしでも痩せられるよね……？",
            ["DialogueId"] = 51120011,
            ["GUID"] = "7FF93CCE",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51120012,
            },
        [51120012] = {
            ["Content"] = "哦？客人聪明呀，这种事情都被你看出来了，的确如此，若是她严格按照我的要求行事，不出三月，恐怕两月便心想事成。",
            ["ContentJP"] = "おやおや、勘が鋭い。そこまで見抜かれるとは。その通り、彼女が私の言いつけを真面目に守れば、二月も経たぬうちに願いは叶うでしょう。",
            ["DialogueId"] = 51120012,
            ["GUID"] = "7FF93CF8",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120013] = {
            ["Content"] = "你不会是在卖假药吧？",
            ["ContentJP"] = "……まさか、ニセ薬売ってるわけじゃないよね？",
            ["DialogueId"] = 51120013,
            ["GUID"] = "7FF93D22",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51120014,
            },
        [51120014] = {
            ["Content"] = "假药？如何见得？那姑娘现在还没服下一口，客人您也未见成效，如何能断定我卖的是假药呢？",
            ["ContentJP"] = "ニセ薬？ほほう、それはどこを根拠に？あの娘はまだ一口も飲んでおらぬし、あなたも結果を見ていない。それで偽物と断じるのは、いささか気が早すぎはしまいか？",
            ["DialogueId"] = 51120014,
            ["GUID"] = "7FF93D4C",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120015] = {
            ["Content"] = "你得给我开点封口费了吧。",
            ["ContentJP"] = "……じゃあ、口止め料もらっておこうかな？",
            ["DialogueId"] = 51120015,
            ["GUID"] = "7FF93D76",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51120016,
            },
        [51120016] = {
            ["Content"] = "封口费？为何？我在这交易之地，做着你情我愿的买卖，也不违反大风九章，如何会需要到给客人您封口费的地步呢？",
            ["ContentJP"] = "おやおや、ご冗談を。ここは取引の場、売り手と買い手が互いに納得の上で物を交わしておる。<Default note=\"text:たいふうきゅうしょう\">大風九章</>にも背いてはおらぬというのに、なぜ口を塞ぐ必要がありましょうや？",
            ["DialogueId"] = 51120016,
            ["GUID"] = "7FF93DA0",
            ["NextDialogue"] = 51120017,
            ["SpeakNpcId"] = 701027,
            },
        [51120017] = {
            ["Content"] = "你卖给她的究竟是什么？",
            ["ContentJP"] = "……で、あの娘に渡した薬、結局なんだった{性别:|の}？",
            ["DialogueId"] = 51120017,
            ["GUID"] = "7FF93DCA",
            ["NextDialogue"] = 51120018,
            ["SpeakNpcId"] = 100001,
            },
        [51120018] = {
            ["Content"] = "客人既然已经知晓，何必再假意询问，卖的自然是让她心想事成之药，必能达成她心之所愿。",
            ["ContentJP"] = "もうお気づきでは？あれは「心の願いを叶える薬」……もっとも、その願いを叶える方法は、服薬ではないのですけれどね。",
            ["DialogueId"] = 51120018,
            ["GUID"] = "7FF93DF4",
            ["NextDialogue"] = 51120019,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_Start",
                },
            },
        [51120019] = {
            ["Content"] = "……所以还是假药喽？万一她吃出什么毛病怎么办？",
            ["ContentJP"] = "つまり……やっぱり「薬じゃない」ってこと？万一、体に悪影響を及ぼしたらどうする{性别:んだ|の}？",
            ["DialogueId"] = 51120019,
            ["GUID"] = "7FF93E1E",
            ["NextDialogue"] = 51120020,
            ["SpeakNpcId"] = 100001,
            },
        [51120020] = {
            ["Content"] = "呵呵，客人心地善良，但我黄药师也不是什么奸恶之人，不做谋财害命之事。那小姑娘体态康健，却执意想通过节食和药物减肥，实非明智之举。",
            ["ContentJP"] = "お客人、誤解なきよう。私は毒を売って金を稼ぐような下劣な真似はいたしませんよ。あの娘は元気な体を持ちながら、痩せたい一心で食を絶ち、薬に頼ろうとしていた。愚かではありますが、その想いを否定せず、私はこう言ったのです――「しっかり食べなさい」と。",
            ["DialogueId"] = 51120020,
            ["GUID"] = "7FF93E48",
            ["NextDialogue"] = 51120021,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_End",
                },
            },
        [51120021] = {
            ["Content"] = "所以我建议她好好吃饭的同时，给她开了些补剂，里面掺的是一人日常所需的营养，免得她运动后气血亏空，瘫倒在地啊。",
            ["ContentJP"] = "彼女に渡したのは、栄養補助の薬。運動で消耗する分を補えるように調整したものです。要は、倒れないための保険ですね。",
            ["DialogueId"] = 51120021,
            ["GUID"] = "7FF93E72",
            ["NextDialogue"] = 51120022,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk01_Start",
                },
            },
        [51120022] = {
            ["Content"] = "你很懂啊？",
            ["ContentJP"] = "……詳しいじゃん。",
            ["DialogueId"] = 51120022,
            ["GUID"] = "7FF93E9C",
            ["NextDialogue"] = 51120023,
            ["SpeakNpcId"] = 100001,
            },
        [51120023] = {
            ["Content"] = "诶？不敢很懂，只敢略懂，客人，小药师我只是做着一些小本生意，勉强在这黑市混口饭吃而已。",
            ["ContentJP"] = "ははっ、恐れ入ります。とはいえ、専門家などと呼ばれるほどでは。この闇市で細々と薬屋を続けている、ただのしがない商い人にすぎません。",
            ["DialogueId"] = 51120023,
            ["GUID"] = "7FF93EC6",
            ["NextDialogue"] = 51120024,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk01_End",
                },
            },
        [51120024] = {
            ["Content"] = "所以别的药你也是一样的卖法？用补剂代替药品。",
            ["ContentJP"] = "他の薬も、同じ感じ？いわゆる「薬品」ではなく「生活指導」を撃ってるんだね。",
            ["DialogueId"] = 51120024,
            ["GUID"] = "7FF93EF0",
            ["NextDialogue"] = 51120025,
            ["SpeakNpcId"] = 100001,
            },
        [51120025] = {
            ["Content"] = "你们这些家伙总是喜欢刨根问底，有些事睁一只眼闭一只眼便算了罢。我也并未害人，只是让他们以正确的方式去达成他们的目的。",
            ["ContentJP"] = "ふふ、あなたのような方は、何でも掘り下げたがる。ですがね、物事には目をつむる美学というのもあるんです。私は騙してなどいません。ただ、彼らの望む形で、彼らを「正しい方」へ導いているだけ。",
            ["DialogueId"] = 51120025,
            ["GUID"] = "7FF93F1A",
            ["NextDialogue"] = 51120026,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_Start",
                },
            },
        [51120026] = {
            ["Content"] = "想要长寿，那便早睡早起，健康饮食，想要美丽，那便香薰敷面，减少操劳。客人对药的定义还是过于狭隘了不是吗？",
            ["ContentJP"] = "長生きしたいなら、早寝早起きとバランスの良い食事。美しくなりたいなら、香を焚き、顔を休ませ、心の余裕を持つこと。これらすべて、薬と呼べない道理はありますか？",
            ["DialogueId"] = 51120026,
            ["GUID"] = "7FF93F44",
            ["NextDialogue"] = 51120027,
            ["SpeakNpcId"] = 701027,
            },
        [51120027] = {
            ["Content"] = "药，即可以是一方服入腹中便可见效的物品，也可以是一种生活方针，我表面是给了他们药，实际却是指导了他们要如何生活。",
            ["ContentJP"] = "薬とは、必ずしも瓶に詰められた液体や丸薬のことではない。時にそれは、生き方そのものを示す「処方」であってもよいのです。",
            ["DialogueId"] = 51120027,
            ["GUID"] = "7FF93F6E",
            ["NextDialogue"] = 51120028,
            ["SpeakNpcId"] = 701027,
            },
        [51120028] = {
            ["Content"] = "这样看起来，我拿这钱是否理所应当？",
            ["ContentJP"] = "そうして得た対価を、私は恥じることなく受け取っておりますよ。",
            ["DialogueId"] = 51120028,
            ["GUID"] = "7FF93F98",
            ["NextDialogue"] = 51120029,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Talk02_End",
                },
            },
        [51120029] = {
            ["Content"] = "（好像很有道理……）",
            ["ContentJP"] = "（言われてみれば一理あるような……）",
            ["DialogueId"] = 51120029,
            ["GUID"] = "7FF93FC2",
            ["NextDialogue"] = 51120030,
            ["SpeakNpcId"] = 100001,
            },
        [51120030] = {
            ["Content"] = "所以啊，客人莫要纠结了，若是我害人自有应天尉大人来找我麻烦，如何还能让我“作恶多端”呢？",
            ["ContentJP"] = "だからこそ、あなたが責めるまでもなく、もし私が本当に「悪」であるなら、とっくに応天尉様が引っ張りに来ているはずですわ。",
            ["DialogueId"] = 51120030,
            ["GUID"] = "7FF93FEC",
            ["NextDialogue"] = 51120031,
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_Start",
                },
            },
        [51120031] = {
            ["Content"] = "若是客人不买药，不如往边上让让？把机会让给需要的人？",
            ["ContentJP"] = "薬を買う気がないなら――さ、そこを空けてくださいな。後ろには、まだ願いを抱いた方々が並んでおりますのでな。",
            ["DialogueId"] = 51120031,
            ["GUID"] = "7FF94016",
            ["SpeakNpcId"] = 701027,
            ["TalkActionId"] = {
                [1] = "701027:Explain01_End",
                },
            },
        [51120032] = {
            ["Content"] = "看山看水不如看病，吃素吃肉不如吃我药师的灵丹妙药啊~",
            ["ContentJP"] = "よってらっしゃい、みてらっしゃい、ようこそ私の病院へ、どんな薬膳もこの私の妙薬には及ばないぞ～",
            ["DialogueId"] = 51120032,
            ["GUID"] = "7FF94040",
            ["SpeakNpcId"] = 701027,
            },
        [51121000] = {
            ["Content"] = "不管怎样，你今日必须给我一个说法！",
            ["ContentJP"] = "とにかく、今日ははっきりしてもらうぞ！",
            ["DialogueId"] = 51121000,
            ["GUID"] = "7FF9DF10",
            ["LookAt"] = {
                [1] = "701029:n(701030)",
                [2] = "701030:n(701029)",
                },
            ["NextDialogue"] = 51121001,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_Start",
                [2] = "701030:Talk02_Start",
                },
            },
        [51121001] = {
            ["Content"] = "说法，什么说法？你别太无理取闹……",
            ["ContentJP"] = "ハッキリって、何をだよ……勝手に怒鳴り込んできて、いい加減にしてくれ。",
            ["DialogueId"] = 51121001,
            ["GUID"] = "7FF9DF3A",
            ["NextOptions"] = {
                [1] = 51121002,
                [2] = 51121003,
                [3] = 51121004,
                },
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_End",
                [2] = "701030:Talk02_End",
                },
            },
        [51121002] = {
            ["Content"] = "看起来吵得有点凶，过去劝劝架吧。",
            ["ContentJP"] = "どうやら言い争いが本格化している。止めに入ろう……",
            ["DialogueId"] = 51121002,
            ["GUID"] = "7FF9DF64",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51121005,
            },
        [51121003] = {
            ["Content"] = "打起来！打起来！",
            ["ContentJP"] = "やれやれー！",
            ["DialogueId"] = 51121003,
            ["GUID"] = "7FF9DF8E",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51121005,
            },
        [51121004] = {
            ["Content"] = "什么事吵成这样……",
            ["ContentJP"] = "なんだこの騒ぎは……",
            ["DialogueId"] = 51121004,
            ["GUID"] = "7FF9DFB8",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51121005,
            },
        [51121005] = {
            ["Content"] = "你，对，就是你这个有着满头雪发的{性别：老头|老太}，你过来，帮人家评评理！",
            ["ContentJP"] = "そこの、白髪の{性别:じいさん|ばあさん}、そう、あんた！ちょっと来てくれ、第三者の意見が欲しい！",
            ["DialogueId"] = 51121005,
            ["GUID"] = "7FF9DFE2",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121006,
            ["SpeakNpcId"] = 701029,
            },
        [51121006] = {
            ["Content"] = "瞧你这眼神，大好一个{性别：小伙子|小姑娘}都被你看成老人家了。与其在这里丢人现脸，你还是早点回家睡觉吧。",
            ["ContentJP"] = "……あんた、目大丈夫か？こんな若者を老人扱いとはね。あんまりみっともない真似するくらいなら、さっさと帰って寝なよ。",
            ["DialogueId"] = 51121006,
            ["GUID"] = "7FF9E00C",
            ["LookAt"] = {
                [1] = "701029:n(701030)",
                [2] = "701030:n(701029)",
                },
            ["NextDialogue"] = 51121007,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_Start",
                },
            },
        [51121007] = {
            ["Content"] = "你还说！分明就是你害的，要不是你整日昼伏夜出，扰得我日日夜夜睡不上一个好觉，我写书的创意是如何枯竭的，定是被你搅浑了！",
            ["ContentJP"] = "まだ言う気か！？全部お前のせいだ！昼夜逆転で、夜中にガタガタうるさいせいで、寝不足で創作も進まない！きっとあの音が、私のインスピレーションをかき乱してるんだ！",
            ["DialogueId"] = 51121007,
            ["GUID"] = "7FF9E036",
            ["NextDialogue"] = 51121008,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_End",
                },
            },
        [51121008] = {
            ["Content"] = "你有完没完，不管我什么时间出门，什么时间回家，都是我的自由，我既没有在回家之时去敲你的门，也没在出门的时候摔你的门，如何惹到你了？",
            ["ContentJP"] = "何が創作だよ……オレが何時に出て、何時に帰ろうが自由だろ。ドア叩いたわけでも、騒ぎ立てたわけでもない。何が悪いっていうんだ？",
            ["DialogueId"] = 51121008,
            ["GUID"] = "7FF9E060",
            ["NextDialogue"] = 51121009,
            ["SpeakNpcId"] = 701030,
            },
        [51121009] = {
            ["Content"] = "你那动静，与敲门摔门有何区别？你那又笨又重的靴子在家中踩来踩去，呱唧作响，每回上床之前，要将两只靴子一一甩开，发出咚咚两声。",
            ["ContentJP"] = "あの足音だ！あの、ガンッて投げ捨てるブーツの音！毎晩寝入りばなに、お前の靴が「ドンッ！ドンッ！」って鳴るんだよ！",
            ["DialogueId"] = 51121009,
            ["GUID"] = "7FF9E08A",
            ["NextDialogue"] = 51121010,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_Start",
                },
            },
        [51121010] = {
            ["Content"] = "少胡扯了，之前你来说过一次，我不是后面都尽量想起来放轻声音了吗？",
            ["ContentJP"] = "……前に文句言ってきたとき、ちゃんと気をつけるようにしたろ？",
            ["DialogueId"] = 51121010,
            ["GUID"] = "7FF9E0B4",
            ["NextDialogue"] = 51121011,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk02_Start",
                },
            },
        [51121011] = {
            ["Content"] = "对！你只记得放轻第二只靴子，却忘了第一只，我被你那第一只靴子吵醒，一直在等你甩第二只，你却迟迟不甩，我便干等到天亮！",
            ["ContentJP"] = "ああ、確かに二回目の足音は静かにだった。でも一回目はうるさいままだ！そのせいで起きちゃって……残りの足音が鳴るのを待ち続けたのに、なかなか聞こえないから……結局一睡もできなかったんだぞ！",
            ["DialogueId"] = 51121011,
            ["GUID"] = "7FF9E0DE",
            ["NextDialogue"] = 51121012,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_End",
                },
            },
        [51121012] = {
            ["Content"] = "不是……这也怪我吗？况且在那之后我不都已经格外注意了吗，如今每晚不过是在自家正常走动、洗漱，也没见其他邻居来找我。",
            ["ContentJP"] = "それ、オレのせいか？その後はもう、細心の注意で静かに動いてる。普通に風呂入って、歩いてるだけだ。他の近所の人は何も言ってこないぜ。",
            ["DialogueId"] = 51121012,
            ["GUID"] = "7FF9E108",
            ["NextDialogue"] = 51121013,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk02_End",
                },
            },
        [51121013] = {
            ["Content"] = "半点声音都听不得，莫不是你自己耳朵有问题。有病就去治，别来烦别人好吗？",
            ["ContentJP"] = "ちょっとの音も我慢できないなんて……耳に問題があるんじゃないのか？病院行けば？",
            ["DialogueId"] = 51121013,
            ["GUID"] = "7FF9E132",
            ["NextDialogue"] = 51121014,
            ["SpeakNpcId"] = 701030,
            },
        [51121014] = {
            ["Content"] = "你！你欺人太甚！",
            ["ContentJP"] = "な、なんだと……！",
            ["DialogueId"] = 51121014,
            ["GUID"] = "7FF9E15C",
            ["NextOptions"] = {
                [1] = 51121015,
                },
            ["RestartTag"] = 51121014,
            ["SpeakNpcId"] = 701029,
            },
        [51121015] = {
            ["Content"] = "试试劝架吧。",
            ["ContentJP"] = "止めに入ろう",
            ["DialogueId"] = 51121015,
            ["FailDialogue"] = 51121016,
            ["GUID"] = "7FF9E186",
            ["ImprCheckId"] = 1127,
            ["NextDialogue"] = 51121017,
            },
        [51121016] = {
            ["Content"] = "（眼前的二人怒上心头，越吵越激烈，压根听不到你微弱的劝架声……）",
            ["ContentJP"] = "二人の言い合いはどんどんヒートアップして、あなたの静かな声では到底止められそうにない……",
            ["DialogueId"] = 51121016,
            ["GUID"] = "7FF9E1B0",
            },
        [51121017] = {
            ["Content"] = "不要吵了。",
            ["ContentJP"] = "もうやめましょうよ。",
            ["DialogueId"] = 51121017,
            ["GUID"] = "7FF9E1DA",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121018,
            ["SpeakNpcId"] = 100001,
            },
        [51121018] = {
            ["Content"] = "这位好心人，你刚才也听到了，这家伙作息吊诡，搅我安眠。我本在家中创作写书，创意枯竭，本就神经衰弱，却被这动静搅得连觉也没法睡！",
            ["ContentJP"] = "ね？聞いただろ、この人の夜行動がうるさくて、全然寝られないんだ！本当なら創作に集中したいのに、神経すり減って、身も心もボロボロだ！",
            ["DialogueId"] = 51121018,
            ["GUID"] = "7FF9E204",
            ["NextDialogue"] = 51121019,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_Start",
                },
            },
        [51121019] = {
            ["Content"] = "我到底闹出什么天大的动静了？连在自家走动都要管，难道非得要我像个贼一样蹑手蹑脚你才能满意？",
            ["ContentJP"] = "はあ？何がそんなにうるさいのか教えてほしいね。自分の家で静かに過ごしてるだけで、まるで犯罪者扱いとは……じゃあなんだ？泥棒みたいにコソコソ歩けって？",
            ["DialogueId"] = 51121019,
            ["GUID"] = "7FF9E22E",
            ["NextDialogue"] = 51121020,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701029:Talk01_End",
                [2] = "701030:Talk02_Start",
                },
            },
        [51121020] = {
            ["Content"] = "好了好了……我先问问你，你为什么要昼伏夜出？",
            ["ContentJP"] = "ちょっと落ち着いて。まず聞きたいけど、あなたはどうして夜遅くに出入りしてるの？",
            ["DialogueId"] = 51121020,
            ["GUID"] = "7FF9E258",
            ["NextDialogue"] = 51121021,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701030:Talk02_End",
                },
            },
        [51121021] = {
            ["Content"] = "我吗？我没办法，码头力工本来就是老板让几点过去搬货就几点去，只是最近接到的单子便让我深夜卸货，忙完回来也就天亮了。",
            ["ContentJP"] = "オレか？……港の荷揚げ作業だよ。仕事の時間なんて選べないし、夜の便が多い時期は深夜に荷下ろし、終わる頃には空も白んでる。",
            ["DialogueId"] = 51121021,
            ["GUID"] = "7FF9E282",
            ["NextDialogue"] = 51121022,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Explain01_Start",
                },
            },
        [51121022] = {
            ["Content"] = "你为何要接这种阴间时辰的单子？",
            ["ContentJP"] = "なぜそんな真夜中の仕事を？",
            ["DialogueId"] = 51121022,
            ["GUID"] = "7FF9E2AC",
            ["LookAt"] = {
                [1] = "701029:n(701030)",
                [2] = "701030:n(701029)",
                },
            ["NextDialogue"] = 51121023,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk02_Start",
                },
            },
        [51121023] = {
            ["Content"] = "呵……你以为大家都跟你一样在家躺着就有钱吃饭吗？我不干活哪来的钱吃饭，再说晚上的单子油水足，赚的多啊！",
            ["ContentJP"] = "そんなの決まってんだろ。働かないと飯も食えねぇ。夜の仕事は日給も高いし、生活のためだよ！家で寝っ転がってれば金が転がり込んでくるお前とは違うんだ。",
            ["DialogueId"] = 51121023,
            ["GUID"] = "7FF9E2D6",
            ["NextDialogue"] = 51121024,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Explain01_End",
                },
            },
        [51121024] = {
            ["Content"] = "什么叫我在家躺着就有饭吃？我每日呕心沥血在家钻研字句用词之时，你考虑过我创意的疲乏与苦衷吗？",
            ["ContentJP"] = "ふざけんな、私がどれだけ言葉を削り、推敲に苦しんでるか知りもしねぇくせに。",
            ["DialogueId"] = 51121024,
            ["GUID"] = "7FF9E300",
            ["NextDialogue"] = 51121025,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Talk02_End",
                },
            },
        [51121025] = {
            ["Content"] = "听起来你们两个都很有道理。",
            ["ContentJP"] = "……話を聞く限り、どちらにも言い分はあるみたいですね。",
            ["DialogueId"] = 51121025,
            ["GUID"] = "7FF9E32A",
            ["NextDialogue"] = 51121026,
            ["SpeakNpcId"] = 100001,
            },
        [51121026] = {
            ["Content"] = "我不管，他就是吵到我睡觉，你给评评理吧！",
            ["ContentJP"] = "でも！この人のせいで眠れないのは事実。お願い、判断して！",
            ["DialogueId"] = 51121026,
            ["GUID"] = "7FF9E354",
            ["NextDialogue"] = 51121027,
            ["SpeakNpcId"] = 701029,
            },
        [51121027] = {
            ["Content"] = "快结束这出闹剧吧，哈欠……我还得回家睡觉，晚上上工呢。",
            ["ContentJP"] = "ったく……もう勘弁してくれよ。……ふあぁ。はやく寝なきゃ、夜また仕事なんだよ。",
            ["DialogueId"] = 51121027,
            ["GUID"] = "7FF9E37E",
            ["NextOptions"] = {
                [1] = 51121028,
                [2] = 51121034,
                },
            ["SpeakNpcId"] = 701030,
            },
        [51121028] = {
            ["Content"] = "帮余下说话。",
            ["ContentJP"] = "ヨカをかばう。",
            ["DialogueId"] = 51121028,
            ["GUID"] = "7FF9E3A8",
            ["NextDialogue"] = 51121029,
            },
        [51121029] = {
            ["Content"] = "你的作息时间毕竟和大家都不一样，打扰了他也是事实。所以还是再注意把脚步声放轻点吧。",
            ["ContentJP"] = "確かに、あなたの生活サイクルが一般とずれてるのは事実。だからこそ、もう少し音に気を遣ってあげてください。少なくとも、隣人として。",
            ["DialogueId"] = 51121029,
            ["GUID"] = "7FF9E3D2",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121030,
            ["SpeakNpcId"] = 100001,
            },
        [51121030] = {
            ["Content"] = "你听你听，还是义士大人说话中肯！",
            ["ContentJP"] = "よくぞ言ってくれた！わかるやつにはわかるんだよ、この苦しみが！",
            ["DialogueId"] = 51121030,
            ["GUID"] = "7FF9E3FC",
            ["NextDialogue"] = 51121031,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_Start",
                },
            },
        [51121031] = {
            ["Content"] = "怎么你也向着他……哼！",
            ["ContentJP"] = "チッ……なんだよ、お前まであっちに肩入れかよ。",
            ["DialogueId"] = 51121031,
            ["GUID"] = "7FF9E426",
            ["NextDialogue"] = 51121032,
            ["SpeakNpcId"] = 701030,
            },
        [51121032] = {
            ["Content"] = "鄙人先行谢过，义士大人您可真是人中龙凤，气度不凡，多谢您为我伸冤！",
            ["ContentJP"] = "礼を言わせてもらうよ。あんたは真っ当な目と耳を持った人物だ。ありがとう。",
            ["DialogueId"] = 51121032,
            ["GUID"] = "7FF9E450",
            ["NextDialogue"] = 51121033,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701029:Explain01_End",
                },
            },
        [51121033] = {
            ["Content"] = "他吵到你也是生计所迫，并不是故意的。你们邻居一场，多体谅一些对方的难处吧。",
            ["ContentJP"] = "とはいえ、彼も故意に騒いでるわけじゃない。近所付き合いってのは、お互い少しずつ譲り合ってこそ成り立つものです。歩み寄れるところは、歩み寄ってください。",
            ["DialogueId"] = 51121033,
            ["GUID"] = "7FF9E47A",
            ["NextDialogue"] = 51121040,
            ["SpeakNpcId"] = 100001,
            },
        [51121034] = {
            ["Content"] = "帮董筑说话。",
            ["ContentJP"] = "トウチクをかばう。",
            ["DialogueId"] = 51121034,
            ["GUID"] = "7FF9E4A4",
            ["NextDialogue"] = 51121035,
            },
        [51121035] = {
            ["Content"] = "如果其他邻居没有和你一样的困扰，也许是你过于敏感了。考虑用棉花把耳朵塞起来如何？",
            ["ContentJP"] = "他の住人からは苦情が出ていないのなら、もしかするとあなたが少し敏感すぎるのかもしれません。試しに耳栓でもしてみたらどう{性别:だろう|でしょう}。",
            ["DialogueId"] = 51121035,
            ["GUID"] = "7FF9E4CE",
            ["LookAt"] = {
                [1] = "701029:n(0)",
                [2] = "701030:n(0)",
                },
            ["NextDialogue"] = 51121036,
            ["SpeakNpcId"] = 100001,
            },
        [51121036] = {
            ["Content"] = "听到没？路人都帮我说话，都说了你自己塞上耳朵得了，非要吵来吵去的。",
            ["ContentJP"] = "だよな。こいつ一人が騒ぎすぎなんだよ。自分で耳塞ぎやがれや。",
            ["DialogueId"] = 51121036,
            ["GUID"] = "7FF9E4F8",
            ["NextDialogue"] = 51121037,
            ["SpeakNpcId"] = 701030,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_Start",
                },
            },
        [51121037] = {
            ["Content"] = "你！你有眼无珠！分明就是他的过错，却让我一再忍耐，你们未免太过分了！",
            ["ContentJP"] = "……はぁ！？全部あいつのせいなのに、私だけが我慢しろってのか！？ふざけんなよ、こんな連中とは一刻も早くおさらばしたいぜ。",
            ["DialogueId"] = 51121037,
            ["GUID"] = "7FF9E522",
            ["NextDialogue"] = 51121038,
            ["SpeakNpcId"] = 701029,
            },
        [51121038] = {
            ["Content"] = "若是我的书出版之后有了钱，定要去皓京买幢独栋别墅，第一时间搬出这里，再不与你这种人同为里邻！",
            ["ContentJP"] = "本が売れて金が入ったら、<Default note=\"text:こうけい\">皓京</>に一軒家建ててすぐに引っ越してやる。二度と、こんな野蛮な連中と屋根を並べるものか！",
            ["DialogueId"] = 51121038,
            ["GUID"] = "7FF9E54C",
            ["NextDialogue"] = 51121039,
            ["SpeakNpcId"] = 701029,
            ["TalkActionId"] = {
                [1] = "701030:Talk01_End",
                },
            },
        [51121039] = {
            ["Content"] = "狴犴没来抓我，说明我没问题，但要是你再闹下去，会不会来抓你我就不知道了。",
            ["ContentJP"] = "ふん、<Default note=\"text:ビーアン\">狴犴</>が来ないってことは、オレは悪くないってことだ。それ以上騒いだら……お前を捕まえにくるかもな！",
            ["DialogueId"] = 51121039,
            ["GUID"] = "7FF9E576",
            ["NextDialogue"] = 51121040,
            ["SpeakNpcId"] = 701030,
            },
        [51121040] = {
            ["Content"] = "事情就到这里吧，我先走了，你们和睦相处，日后不要起争执了。",
            ["ContentJP"] = "……じゃあ、そろそろお暇します。お互いもう少し冷静になって、今後は穏やかにやってください。",
            ["DialogueId"] = 51121040,
            ["GUID"] = "7FF9E5A0",
            ["NextDialogue"] = 51121041,
            ["SpeakNpcId"] = 100001,
            },
        [51121041] = {
            ["Content"] = "（余下急匆匆地离开了，董筑挠挠头，切了一声，什么也没说。）",
            ["ContentJP"] = "ヨカは苛立ちを隠そうともせず足早に立ち去り、トウチクは無言で頭をかきながら、軽く舌打ちをして背を向けた。",
            ["DialogueId"] = 51121041,
            ["GUID"] = "7FF9E5CA",
            ["NextDialogue"] = 51121042,
            },
        [51121042] = {
            ["Content"] = "（想必他们的关系并不会因为一次小调解就冰释前嫌，但至少暂时不会吵架了。）",
            ["ContentJP"] = "二人の関係が今すぐに改善するとは思えないが――少なくとも今夜は、静かに更けてゆくだろう。",
            ["DialogueId"] = 51121042,
            ["GUID"] = "7FF9E5F4",
            },
        [51122000] = {
            ["Content"] = "娃娃娃娃，快过来！",
            ["ContentJP"] = "おーい、そこの坊や、ちょっと来てくれんか！",
            ["DialogueId"] = 51122000,
            ["GUID"] = "7FFA8320",
            ["LookAt"] = {
                [1] = "701031:n(0)",
                },
            ["NextDialogue"] = 51122001,
            ["SpeakNpcId"] = 701031,
            },
        [51122001] = {
            ["Content"] = "（你环顾四周，并没有发现别人的身影，于是你试探性指了指自己。）",
            ["ContentJP"] = "辺りを見回しても、誰かに呼ばれている様子はない……おそるおそる、自分を指さしてみる。",
            ["DialogueId"] = 51122001,
            ["GUID"] = "7FFA834A",
            ["NextDialogue"] = 51122002,
            },
        [51122002] = {
            ["Content"] = "对咯，叫你呢娃娃，快过来呀！",
            ["ContentJP"] = "そう、君だよ君！さ、こっちおいで！",
            ["DialogueId"] = 51122002,
            ["GUID"] = "7FFA8374",
            ["NextDialogue"] = 51122003,
            ["NextOptions"] = {
                [1] = 51122003,
                [2] = 51122004,
                [3] = 51122005,
                },
            ["SpeakNpcId"] = 701031,
            },
        [51122003] = {
            ["Content"] = "（老实走过去。）",
            ["ContentJP"] = "素直に近づく",
            ["DialogueId"] = 51122003,
            ["GUID"] = "7FFA839E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51122006,
            },
        [51122004] = {
            ["Content"] = "（难道是要给我推销？）",
            ["ContentJP"] = "どうせ押し売りだろうな……",
            ["DialogueId"] = 51122004,
            ["GUID"] = "7FFA83C8",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51122006,
            },
        [51122005] = {
            ["Content"] = "（装作什么也没看见走开。）",
            ["ContentJP"] = "聞こえなかったふりして離れる",
            ["DialogueId"] = 51122005,
            ["GUID"] = "7FFA83F2",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51122006,
            },
        [51122006] = {
            ["Content"] = "诶呀你这小娃儿，好生难叫，老夫我啊老远就注意到你了，叫你半天也不应，我就在那想啊，难道这娃娃小小年纪就失聪了？",
            ["ContentJP"] = "まったく、呼んでも全然来やしない。その若さで耳が遠いのかと思ったぞ。",
            ["DialogueId"] = 51122006,
            ["GUID"] = "7FFA841C",
            ["NextDialogue"] = 51122007,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk01_Start",
                },
            },
        [51122007] = {
            ["Content"] = "现在看起来，精精神神，倒是没有毛病的样子。",
            ["ContentJP"] = "いや、見ればピンピンしてるじゃないか、よかったよかった。",
            ["DialogueId"] = 51122007,
            ["GUID"] = "7FFA8446",
            ["NextDialogue"] = 51122008,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk01_End",
                },
            },
        [51122008] = {
            ["Content"] = "所以你叫我是做什么？",
            ["ContentJP"] = "で、何か用？",
            ["DialogueId"] = 51122008,
            ["GUID"] = "7FFA8470",
            ["NextDialogue"] = 51122009,
            ["SpeakNpcId"] = 100001,
            },
        [51122009] = {
            ["Content"] = "娃娃，你别紧张，华胥可没什么坏人，只是我这有一瓶新酿好的酒，想让你品鉴一番。",
            ["ContentJP"] = "そんな怖い顔せんどくれ。ここ<Default note=\"text:カショ\">華胥</>には悪い奴なんざいやしない。わしが新しく仕込んだ酒があってな、ちと味見してほしいだけなんじゃ。",
            ["DialogueId"] = 51122009,
            ["GUID"] = "7FFA849A",
            ["NextDialogue"] = 51122010,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk02_Start",
                },
            },
        [51122010] = {
            ["Content"] = "哦哦，老夫知晓你要怀疑，听我给你解释，我呢是个专门卖酒的，你可去城里打听打听我酒瓢子的名号，凡是平日爱喝上那么一口的，自然是都晓得。",
            ["ContentJP"] = "おっと、疑うのも無理はないな。わしは酒売りでな、「酒の仙人」と呼ばれる。町で聞いてみなされ、飲兵衛なら、わしの名を知らぬ者はいないはずじゃ。",
            ["DialogueId"] = 51122010,
            ["GUID"] = "7FFA84C4",
            ["NextDialogue"] = 51122011,
            ["SpeakNpcId"] = 701031,
            },
        [51122011] = {
            ["Content"] = "但这最近呢，老夫却接到个织星客的订单，说是要出口一批甜酒到大陆另一头的海伯利亚去。",
            ["ContentJP"] = "そんでな、最近ちと変わった注文を受けたんじゃ。<Default note=\"text:ほしおりびと\">星織人</>からの依頼でな、海の向こうのヒュペリアまで甘い酒を届けてほしいってな。",
            ["DialogueId"] = 51122011,
            ["GUID"] = "7FFA84EE",
            ["NextDialogue"] = 51122012,
            ["SpeakNpcId"] = 701031,
            },
        [51122012] = {
            ["Content"] = "但看了这订单我可就犯难了呀，订单特意要求了酒味要淡，甘甜可口，这这这……和咱平日酿的酒口味差了十万八千里呀，但奈何这订单出手确实阔绰……",
            ["ContentJP"] = "じゃが困ったことに、その注文ってのが、酒の香りは控えめにして、甘くて口当たりのよい酒にせい、ときた。いつもわしが造っとる酒とは真逆の方向性でな……けど、あの注文、かなり羽振りがよくてのぉ。",
            ["DialogueId"] = 51122012,
            ["GUID"] = "7FFA8518",
            ["NextDialogue"] = 51122013,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Talk02_End",
                },
            },
        [51122013] = {
            ["Content"] = "所以你研发新酒，想找人帮你试试口味。",
            ["ContentJP"] = "それで、試作品の味見をしてほしいってわけか。",
            ["DialogueId"] = 51122013,
            ["GUID"] = "7FFA8542",
            ["NextDialogue"] = 51122014,
            ["SpeakNpcId"] = 100001,
            },
        [51122014] = {
            ["Content"] = "娃娃聪慧！所以老夫绝无别心，这瓶香料酒，是我专程收的圆糯米，蒸制时加入玉桂，带出一丝温润的甜香，再加青砖红提香增味。",
            ["ContentJP"] = "おお、察しがよい！そういうこっちゃ。今回の酒はの、丸米を選び抜いて蒸し上げ、ケイヒを合わせて穏やかな甘みを引き出し、さらに青煉瓦で熟したブドウを風味付けに加えた。",
            ["DialogueId"] = 51122014,
            ["GUID"] = "7FFA856C",
            ["NextDialogue"] = 51122015,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Explain01_Start",
                },
            },
        [51122015] = {
            ["Content"] = "最后，老夫特地订购了一批南山甜果，果肉碾碎成汁后混入现采山泉之水，历时整整三日，最终制成。",
            ["ContentJP"] = "極めつけは南山の甘果よ。果肉を搾って、朝採れの山水に混ぜ、三日三晩漬け込んだ。",
            ["DialogueId"] = 51122015,
            ["GUID"] = "7FFA8596",
            ["NextDialogue"] = 51122016,
            ["SpeakNpcId"] = 701031,
            },
        [51122016] = {
            ["Content"] = "那帮老头们整日喝的都是辛辣烈酒，舌头早已品不出好坏，问来问去只说过于甜腻，老夫也是求助无门，才想起来在这街上等个有缘之人。",
            ["ContentJP"] = "だが、周りの年寄りどもは辛口の酒ばかりで舌がバカになっとる。甘すぎるってばかりでな……それで、通りがかりの誰かに頼もうかと思ってな。",
            ["DialogueId"] = 51122016,
            ["GUID"] = "7FFA85C0",
            ["NextDialogue"] = 51122017,
            ["SpeakNpcId"] = 701031,
            },
        [51122017] = {
            ["Content"] = "怎么样，娃娃，你可愿意尝尝我这新酒？你放心，这酒几乎没什么度数，你若后面有其他事，一两口也不会耽误的。",
            ["ContentJP"] = "どうじゃ、坊や？ちょっとだけ試してみんか？アルコールはほとんどない、予定があっても差し支えん。",
            ["DialogueId"] = 51122017,
            ["GUID"] = "7FFA85EA",
            ["NextDialogue"] = 51122018,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Explain01_End",
                },
            },
        [51122018] = {
            ["Content"] = "让我试试。",
            ["ContentJP"] = "じゃあ、ひと口だけ。",
            ["DialogueId"] = 51122018,
            ["GUID"] = "7FFA8614",
            ["NextOptions"] = {
                [1] = 51122019,
                },
            ["RestartTag"] = 51122018,
            ["SpeakNpcId"] = 100001,
            },
        [51122019] = {
            ["Content"] = "（你从他手中接过酒水，试探性抿了一口。）",
            ["ContentJP"] = "酒を受け取り、口をつける。",
            ["DialogueId"] = 51122019,
            ["FailDialogue"] = 51122020,
            ["GUID"] = "7FFA863E",
            ["ImprCheckId"] = 1128,
            ["NextDialogue"] = 51122021,
            },
        [51122020] = {
            ["Content"] = "（没品出来……）",
            ["ContentJP"] = "うーん、イマイチよくわからない……",
            ["DialogueId"] = 51122020,
            ["GUID"] = "7FFA8668",
            ["SpeakNpcId"] = 100001,
            },
        [51122021] = {
            ["Content"] = "入口甘甜似饮蜜，酒水从喉咙之间穿过之时，又隐约有股幽香，是瓶好酒。",
            ["ContentJP"] = "甘くて、のどごしもいい……いい酒だ。",
            ["DialogueId"] = 51122021,
            ["GUID"] = "7FFA8692",
            ["NextDialogue"] = 51122022,
            ["SpeakNpcId"] = 100001,
            },
        [51122022] = {
            ["Content"] = "酒甜不过娃娃嘴甜呀，你这一说，给老夫说的心里也甜滋滋的，不枉我这几日绞尽脑汁想着如何完成这场订单了。",
            ["ContentJP"] = "ほっほっほ、お前さんの口の方がよほど甘いのう。そう言ってもらえると、わしも胸のつかえが下りたわい。何日も頭をひねって作った甲斐があったというもんじゃ。",
            ["DialogueId"] = 51122022,
            ["GUID"] = "7FFA86BC",
            ["NextDialogue"] = 51122023,
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Confident_Start",
                },
            },
        [51122023] = {
            ["Content"] = "你为什么不从你现有的酒品里找一些做交易？",
            ["ContentJP"] = "でも、どうして今ある酒の中から選ばなかったの？",
            ["DialogueId"] = 51122023,
            ["GUID"] = "7FFA86E6",
            ["NextDialogue"] = 51122024,
            ["SpeakNpcId"] = 100001,
            },
        [51122024] = {
            ["Content"] = "你想，这海伯利亚离咱们这么远，那个远在另一头的娃娃不远万里下这个订单，定是信任老夫的酿酒技艺。",
            ["ContentJP"] = "ふむ、考えてもみなされ。ヒュペリアなどという遠い土地の娘が、わざわざわしに注文をよこしたのじゃぞ？",
            ["DialogueId"] = 51122024,
            ["GUID"] = "7FFA8710",
            ["NextDialogue"] = 51122025,
            ["SpeakNpcId"] = 701031,
            },
        [51122025] = {
            ["Content"] = "若我随意交差，岂不是辜负了她的信任，砸了咱酒坊多年的好名声？",
            ["ContentJP"] = "それはつまり、わしの酒造りの腕を信じてくれとるということじゃ。そんな信頼を裏切るような真似、できるはずもあるまい？わしの酒舗の看板を汚すことにもなるしの。",
            ["DialogueId"] = 51122025,
            ["GUID"] = "7FFA873A",
            ["NextDialogue"] = 51122026,
            ["SpeakNpcId"] = 701031,
            },
        [51122026] = {
            ["Content"] = "不过还好你这娃娃给了好评价，这让老夫交差的心都踏实了些，想必那个叫卡什么的外国女娃娃也会喜欢这特制甜酒吧。",
            ["ContentJP"] = "ともあれ、坊やがこうして褒めてくれたことで、わしの気持ちもようやく落ち着いたわい。きっとカ……なんじゃったか、あの娘もこの酒を気に入ってくれるじゃろう。",
            ["DialogueId"] = 51122026,
            ["GUID"] = "7FFA8764",
            ["NextDialogue"] = 51122027,
            ["SpeakNpcId"] = 701031,
            },
        [51122027] = {
            ["Content"] = "多谢你了，小娃，若下次还想饮酒，可再来找我酒瓢子，我可专程为你酿制一瓶好酒！",
            ["ContentJP"] = "恩に着るぞ、坊や。もしまた飲みたくなったら、わしのところに来なされ。またお前さんのためだけの一本、拵えておくからな。",
            ["DialogueId"] = 51122027,
            ["GUID"] = "7FFA878E",
            ["SpeakNpcId"] = 701031,
            ["TalkActionId"] = {
                [1] = "701031:Confident_End",
                },
            },
        [51122028] = {
            ["Content"] = "好酒不怕巷子深！",
            ["ContentJP"] = "うまい酒は、隠したって見つかるもんさ。",
            ["DialogueId"] = 51122028,
            ["GUID"] = "7FFA87B8",
            ["SpeakNpcId"] = 701031,
            },
        [51123000] = {
            ["Content"] = "早起去割麦，割出万里田，整日忙不歇，归家喝小酒。",
            ["ContentJP"] = "朝から麦刈り、万里の田んぼ。一日働いて、家で一杯……",
            ["DialogueId"] = 51123000,
            ["GUID"] = "7FFB2730",
            ["LookAt"] = {
                [1] = "701032:n(0)",
                },
            ["NextDialogue"] = 51123001,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Confident_Start",
                },
            },
        [51123001] = {
            ["Content"] = "歇，酒，好像不怎么押韵啊……改成什么好呢？",
            ["ContentJP"] = "んー、「働く」「酒」って、ちょっと韻が合ってない気がするな。何か他にいい言い回しないかね？",
            ["DialogueId"] = 51123001,
            ["GUID"] = "7FFB275A",
            ["NextOptions"] = {
                [1] = 51123002,
                },
            ["RestartTag"] = 51123001,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Confident_End",
                },
            },
        [51123002] = {
            ["Content"] = "帮他想想。",
            ["ContentJP"] = "知恵を貸す",
            ["DialogueId"] = 51123002,
            ["FailDialogue"] = 51123003,
            ["GUID"] = "7FFB2784",
            ["ImprCheckId"] = 1129,
            ["NextDialogue"] = 51123004,
            },
        [51123003] = {
            ["Content"] = "（没想出来，再想想吧。）",
            ["ContentJP"] = "（特に思いつかないや。もう少し考えてみようかな。）",
            ["DialogueId"] = 51123003,
            ["GUID"] = "7FFB27AE",
            ["SpeakNpcId"] = 100001,
            },
        [51123004] = {
            ["Content"] = "整日忙不歇，归家端菜碟。是不是押上了？",
            ["ContentJP"] = "「日が暮れ戻りて、膳に舌躍る」――とか？韻は合ってるかも？",
            ["DialogueId"] = 51123004,
            ["GUID"] = "7FFB27D8",
            ["NextDialogue"] = 51123005,
            ["SpeakNpcId"] = 100001,
            },
        [51123005] = {
            ["Content"] = "歇，碟……押上了，的确押上了，只是诗句还是不怎么好听，也是我这题出的不好啊，要是那文人墨客，定是比我这老农会作诗。",
            ["ContentJP"] = "……おぉ、すばらしい！ただ句の響きはまだイマイチかなぁ。ま、出題した俺が悪かったか。詩人の連中なら、もっと気の利いた一句にするんだろうなぁ。",
            ["DialogueId"] = 51123005,
            ["GUID"] = "7FFB2802",
            ["NextDialogue"] = 51123006,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Think_Start",
                },
            },
        [51123006] = {
            ["Content"] = "不过，{性别：小伙子|小姑娘}，你看起来不像是华胥人，竟也对诗句有些研究吗？",
            ["ContentJP"] = "でもあんた、どうもこの辺の人じゃなさそうなのに、詩に興味あるのかい？",
            ["DialogueId"] = 51123006,
            ["GUID"] = "7FFB282C",
            ["NextDialogue"] = 51123007,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Think_End",
                },
            },
        [51123007] = {
            ["Content"] = "随口瞎说的，这不是也没对出好的。",
            ["ContentJP"] = "いえ、たまたま口に出しただけで、別に大したもんじゃ。",
            ["DialogueId"] = 51123007,
            ["GUID"] = "7FFB2856",
            ["NextDialogue"] = 51123008,
            ["SpeakNpcId"] = 100001,
            },
        [51123008] = {
            ["Content"] = "哈哈哈哈！你倒是自谦，这不比我作的好多啦，{性别：小伙子|小姑娘}，你为何会往这田埂里跑？",
            ["ContentJP"] = "はっはっは！謙虚なもんだ、けど俺のよりずっといいじゃないか！にしても、こんな田んぼ道まで来るなんて……迷子になったんじゃないかと心配になるよ。",
            ["DialogueId"] = 51123008,
            ["GUID"] = "7FFB2880",
            ["NextOptions"] = {
                [1] = 51123009,
                [2] = 51123011,
                },
            ["SpeakNpcId"] = 701032,
            },
        [51123009] = {
            ["Content"] = "看你一人在这里，有些担心。",
            ["ContentJP"] = "一人で何か呟いてたから、気になって。",
            ["DialogueId"] = 51123009,
            ["GUID"] = "7FFB28AA",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51123010,
            },
        [51123010] = {
            ["Content"] = "嗨！这有什么好担心的，这可是华胥，白龙神君庇佑的好地方。{性别：小伙子|小姑娘}，你这份好意老农我心领了呀。",
            ["ContentJP"] = "おお、そりゃありがとさん。でも心配はいらんよ。ここは白龍様に守られた<Default note=\"text:カショ\">華胥</>の地、危ないもんはおらんさ。気にかけてくれるその気持ちだけで、十分嬉しいよ。",
            ["DialogueId"] = 51123010,
            ["GUID"] = "7FFB28D4",
            ["NextDialogue"] = 51123014,
            ["SpeakNpcId"] = 701032,
            },
        [51123011] = {
            ["Content"] = "我没事，我就溜达。",
            ["ContentJP"] = "ちょっと散歩してただけ。",
            ["DialogueId"] = 51123011,
            ["GUID"] = "7FFB28FE",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51123012,
            },
        [51123012] = {
            ["Content"] = "溜达？你不会是迷路了还嘴硬吧？记得带好香囊啊，可别碰上玄色狴犴喽。",
            ["ContentJP"] = "散歩かい？……もしかして、迷子なのに強がってるんじゃないの？香袋は持ってるかい？<Default note=\"text:ゲンビー\">玄狴</>には気を付けるんだよ。",
            ["DialogueId"] = 51123012,
            ["GUID"] = "7FFB2928",
            ["NextDialogue"] = 51123013,
            ["SpeakNpcId"] = 701032,
            },
        [51123013] = {
            ["Content"] = "所以，你是一位吟游诗人？",
            ["ContentJP"] = "もしかして、吟遊詩人さん？",
            ["DialogueId"] = 51123013,
            ["GUID"] = "7FFB2952",
            ["NextDialogue"] = 51123014,
            ["SpeakNpcId"] = 100001,
            },
        [51123014] = {
            ["Content"] = "吟游诗人？这名儿倒是新鲜。不过我可不是什么诗人，我是个种地的。喏，这一大片都是我家的田地。",
            ["ContentJP"] = "ぎんゆうしじん！？はっはっはっ、そいつは初耳だなぁ。でも、俺はただの百姓さ。見てみな、あの広い田んぼ、ぜ～んぶ俺のだ。",
            ["DialogueId"] = 51123014,
            ["GUID"] = "7FFB297C",
            ["NextDialogue"] = 51123015,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk01_Start",
                },
            },
        [51123015] = {
            ["Content"] = "对老农我来说啊，吟诗作对就是消遣罢了，和赏花看戏没什么区别。",
            ["ContentJP"] = "詩はただの趣味。花を眺めたり芝居を見たりするのと同じ、気晴らしみたいなもんさ。",
            ["DialogueId"] = 51123015,
            ["GUID"] = "7FFB29A6",
            ["NextDialogue"] = 51123016,
            ["SpeakNpcId"] = 701032,
            },
        [51123016] = {
            ["Content"] = "不过啊，想我年轻那会倒是真用心读过几年书，想着有朝一日能入三司为神君效力，诶呀，想想就美啊。",
            ["ContentJP"] = "でもな、若い頃は本気で勉強してた時期もあるんだ。いつか「三司」に入って神に仕えたいって思ってた。……夢のまた夢だったけどなぁ。",
            ["DialogueId"] = 51123016,
            ["GUID"] = "7FFB29D0",
            ["NextDialogue"] = 51123017,
            ["SpeakNpcId"] = 701032,
            },
        [51123017] = {
            ["Content"] = "那怎么没去？",
            ["ContentJP"] = "どうして行かなかったの？",
            ["DialogueId"] = 51123017,
            ["GUID"] = "7FFB29FA",
            ["NextDialogue"] = 51123018,
            ["SpeakNpcId"] = 701032,
            },
        [51123018] = {
            ["Content"] = "早起去割麦，割出万里田，整日忙不歇，归家喝小酒。老农我种田一等一地好，但摊上那些乱七八糟的事就开始犯难啦。",
            ["ContentJP"] = "朝から麦刈って、万里の田を耕して、帰って一杯……百姓仕事なら天下一品だが、役所のゴタゴタにはとんと疎くてな。",
            ["DialogueId"] = 51123018,
            ["GUID"] = "7FFB2A24",
            ["NextDialogue"] = 51123019,
            ["SpeakNpcId"] = 701032,
            },
        [51123019] = {
            ["Content"] = "天理司的辩经，天禄司的账，天梁司的机关，咱是一个都搞不明白哟。要是咱也能入仕，那明日大风九章就该改成大风乱吹啦。",
            ["ContentJP"] = "<Default note=\"text:てんれいし\">天礼司</>の議論？<Default note=\"text:てんろくし\">天禄司</>の帳簿？<Default note=\"text:てんりょうし\">天梁司</>のからくり？俺にゃどれもチンプンカンプンだわ。もし官僚になってたら、明日には「大風九章」じゃなく「台風九升」になってたかもな、ははっ！",
            ["DialogueId"] = 51123019,
            ["GUID"] = "7FFB2A4E",
            ["NextDialogue"] = 51123020,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk01_End",
                },
            },
        [51123020] = {
            ["Content"] = "原来是这样。",
            ["ContentJP"] = "なるほど。",
            ["DialogueId"] = 51123020,
            ["GUID"] = "7FFB2A78",
            ["NextDialogue"] = 51123021,
            ["SpeakNpcId"] = 100001,
            },
        [51123021] = {
            ["Content"] = "不过像现在这样，没事念念打油诗，和年轻人聊聊天，晚上回去和我那好大儿就着集市上买来的卤肉，喝点小酒，也挺好的不是？",
            ["ContentJP"] = "けど今の暮らしも悪くないさ。ちょいと打ち込みで句をひねって、あんたみたいな若者と世間話して、夜になりゃ、息子と市場で買った煮込みでもつまみながら一杯やる。……それで充分、しあわせってもんさ。",
            ["DialogueId"] = 51123021,
            ["GUID"] = "7FFB2AA2",
            ["NextDialogue"] = 51123022,
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk02_Start",
                },
            },
        [51123022] = {
            ["Content"] = "诶呀，今儿天不早了，{性别：小伙子|小姑娘}，咱们先不说啦！我要拾掇拾掇，回家喝上两口咯！",
            ["ContentJP"] = "っと、いかんいかん、もうこんな時間か！今日はここまでにしとこう！片付けて、一杯やりに帰らにゃな！",
            ["DialogueId"] = 51123022,
            ["GUID"] = "7FFB2ACC",
            ["SpeakNpcId"] = 701032,
            ["TalkActionId"] = {
                [1] = "701032:Talk02_End",
                },
            },
        [51123023] = {
            ["Content"] = "锄禾日当午，汗滴禾下土，好诗，好诗啊！",
            ["ContentJP"] = "「昼に畑を耕せば、汗は土に埋もる」……うーん、実に味わい深い詩じゃ！",
            ["DialogueId"] = 51123023,
            ["GUID"] = "7FFB2AF6",
            ["SpeakNpcId"] = 701032,
            },
        [51124000] = {
            ["Content"] = "呜啊！",
            ["ContentJP"] = "わっ！！",
            ["DialogueId"] = 51124000,
            ["FacialId"] = {
                [1] = "701033:Smile01",
                },
            ["GUID"] = "7FFBCB40",
            ["LookAt"] = {
                [1] = "701033:n(0)",
                },
            ["NextDialogue"] = 51124001,
            ["SpeakNpcId"] = 701033,
            },
        [51124001] = {
            ["Content"] = "（不知道从哪里突然窜出了一只皎皎……看起来张牙舞爪的样子。）",
            ["ContentJP"] = "どこからともなく飛び出してきたルーナが、牙を剥いてこちらを威嚇してくる。",
            ["DialogueId"] = 51124001,
            ["GUID"] = "7FFBCB6A",
            ["NextDialogue"] = 51124002,
            },
        [51124002] = {
            ["Content"] = "怎么不说话！怎么不尖叫！难道你已经被我吓傻了，额哈哈哈哈！看来本皎皎的吓人技术已经炉火纯青啦！",
            ["ContentJP"] = "……なによ、無言！？なんで叫ばないの！？まさか、ビビりすぎて声も出ないとか！？フフフ……ふはははっ！やっぱりあたしのビビらせスキル、極まってるってことね！！",
            ["DialogueId"] = 51124002,
            ["GUID"] = "7FFBCB94",
            ["NextOptions"] = {
                [1] = 51124003,
                [2] = 51124004,
                },
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Confident_Start",
                },
            },
        [51124003] = {
            ["Content"] = "为什么要在这里吓人？",
            ["ContentJP"] = "どうして人を驚かせてるの{性别:か|}？",
            ["DialogueId"] = 51124003,
            ["GUID"] = "7FFBCBBE",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51124005,
            },
        [51124004] = {
            ["Content"] = "这样好玩吗？",
            ["ContentJP"] = "それって楽しいの{性别:か|}？",
            ["DialogueId"] = 51124004,
            ["GUID"] = "7FFBCBE8",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51124005,
            },
        [51124005] = {
            ["Content"] = "唔？！说话了！没被吓傻呀。",
            ["ContentJP"] = "ん？喋った？まだ正気なんだ！へぇ～……",
            ["DialogueId"] = 51124005,
            ["FacialId"] = {
                [1] = "701033:Shock01",
                },
            ["GUID"] = "7FFBCC12",
            ["NextDialogue"] = 51124006,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Confident_End",
                },
            },
        [51124006] = {
            ["Content"] = "本皎皎只是在钻研，钻研一种华胥的特色生物是如何进行日常活动的，并进行一些简单的模仿！",
            ["ContentJP"] = "あたしはね、「研究」してるのよ。<Default note=\"text:カショ\">華胥</>に棲む「特殊生物」の日常行動を観察して、再現してみようってわけ！",
            ["DialogueId"] = 51124006,
            ["GUID"] = "7FFBCC3C",
            ["NextOptions"] = {
                [1] = 51124007,
                [2] = 51124009,
                },
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Excited01_Start",
                },
            },
        [51124007] = {
            ["Content"] = "你是说无由生？",
            ["ContentJP"] = "ムユウセイのこと？",
            ["DialogueId"] = 51124007,
            ["GUID"] = "7FFBCC66",
            ["NextDialogue"] = 51124008,
            },
        [51124008] = {
            ["Content"] = "嗐？！你知道？你居然知道无由生？难道……",
            ["ContentJP"] = "へえええ！？知ってるの！？まさか……",
            ["DialogueId"] = 51124008,
            ["GUID"] = "7FFBCC90",
            ["NextDialogue"] = 51124011,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Excited01_End",
                },
            },
        [51124009] = {
            ["Content"] = "无由生好像不会这么行动……",
            ["ContentJP"] = "ムユウセイってそんな動きしないような……",
            ["DialogueId"] = 51124009,
            ["GUID"] = "7FFBCCBA",
            ["NextDialogue"] = 51124010,
            },
        [51124010] = {
            ["Content"] = "嗐？！听你的意思，你好像亲眼看过无由生一样？！难道……",
            ["ContentJP"] = "へぇ！？まさかそれ、実物を見たことあるとか！？",
            ["DialogueId"] = 51124010,
            ["GUID"] = "7FFBCCE4",
            ["NextDialogue"] = 51124011,
            ["SpeakNpcId"] = 701033,
            },
        [51124011] = {
            ["Content"] = "难道本皎皎对于无由生的研究成果已经被泄密，现在所有华胥人都已经知道了无由生，我再也不是唯一一位研究无由生的皎皎了……",
            ["ContentJP"] = "えっ……もしかして、あたしの研究成果が流出した！？えぇえぇ！？じゃあ今や<Default note=\"text:カショ\">華胥</>中の人がムユウセイのこと知ってて、「ムユウセイ研究第一人者」の座を奪われる！？",
            ["DialogueId"] = 51124011,
            ["GUID"] = "7FFBCD0E",
            ["NextDialogue"] = 51124012,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Shock03_Start",
                },
            },
        [51124012] = {
            ["Content"] = "如果我不是唯一一个研究无由生的皎皎，我将失去自己的独特之处，我就会变成和别的皎皎一样的存在了！",
            ["ContentJP"] = "そんなの……そんなの、あたしの個性が……アイデンティティーが……崩れるぅぅ！モブルーナになっちゃう！！",
            ["DialogueId"] = 51124012,
            ["GUID"] = "7FFBCD38",
            ["NextDialogue"] = 51124013,
            ["RestartTag"] = 51124012,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Shock03_End",
                },
            },
        [51124013] = {
            ["Content"] = "不！我绝对不能接受！",
            ["ContentJP"] = "そんなの絶対いや！！",
            ["DialogueId"] = 51124013,
            ["GUID"] = "7FFBCD62",
            ["NextOptions"] = {
                [1] = 51124014,
                [2] = 51124016,
                },
            ["SpeakNpcId"] = 701033,
            },
        [51124014] = {
            ["Content"] = "别这么想，你是最独特的皎皎，至少在吓人这一点上……",
            ["ContentJP"] = "そんなことないよ。少なくとも、人を驚かすセンスは個性的かも？",
            ["DialogueId"] = 51124014,
            ["GUID"] = "7FFBCD8C",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51124015,
            },
        [51124015] = {
            ["Content"] = "唔……好像是这个道理，那本皎皎今日要放弃灵异皎皎这个称号，从今日开始，我要改名为恐怖皎皎！",
            ["ContentJP"] = "……ふむ、なるほど。確かにそれは一理あるわね。だったら肩書を変える！今日からあたしは「ホラールーナ」ね！",
            ["DialogueId"] = 51124015,
            ["GUID"] = "7FFBCDB6",
            ["NextOptions"] = {
                [1] = 51124018,
                },
            ["SpeakNpcId"] = 701033,
            },
        [51124016] = {
            ["Content"] = "我就是无由生。",
            ["ContentJP"] = "{性别:僕|私}はムユウセイだよ。",
            ["DialogueId"] = 51124016,
            ["GUID"] = "7FFBCDE0",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51124017,
            },
        [51124017] = {
            ["Content"] = "才不是嘞，虽然本皎皎对无由生的研究已经不再是唯一，但是据我所知，无由生都是没有实体的，你看起来分明就是直挺挺地站在这里……",
            ["ContentJP"] = "なわけあるかいっ！あたしの研究によると、ムユウセイには物理的な実体がないはず。その点、あなたはどう見ても立派な二本足で地に立ってるわ。",
            ["DialogueId"] = 51124017,
            ["GUID"] = "7FFBCE0A",
            ["NextOptions"] = {
                [1] = 51124018,
                },
            ["SpeakNpcId"] = 701033,
            },
        [51124018] = {
            ["Content"] = "（所以这只皎皎吓人的目的是……）",
            ["ContentJP"] = "……このルーナが人を驚かす理由って、いったいなんだろう？",
            ["DialogueId"] = 51124018,
            ["FailDialogue"] = 51124019,
            ["GUID"] = "7FFBCE34",
            ["ImprCheckId"] = 1130,
            ["NextDialogue"] = 51124020,
            },
        [51124019] = {
            ["Content"] = "（她为什么要在这里吓人呢？）",
            ["ContentJP"] = "（どうして人を驚かせようとしてるんだろ……？）",
            ["DialogueId"] = 51124019,
            ["GUID"] = "7FFBCE5E",
            ["SpeakNpcId"] = 100001,
            },
        [51124020] = {
            ["Content"] = "所以你不在乎自己是什么皎皎，你只是想要成为独一无二的皎皎。",
            ["ContentJP"] = "つまり……どんな種類のルーナでもいいから、「個性的でアイデンティティーを持つルーナ」でいたいってことなんだ{性别:な|ね}。",
            ["DialogueId"] = 51124020,
            ["GUID"] = "7FFBCE88",
            ["NextDialogue"] = 51124021,
            ["SpeakNpcId"] = 100001,
            },
        [51124021] = {
            ["Content"] = "噫呀呀呀！被戳穿了！被你发现了！哈哈！对，就是这样，无论如何我都是独一无二的皎皎哦！",
            ["ContentJP"] = "うわっ！図星っ！そこ突く！？うふふ……そう！その通りっ！あたしは、どんなときでも！どんなルーナよりも！オンリーワンなのよっ！",
            ["DialogueId"] = 51124021,
            ["FacialId"] = {
                [1] = "701033:Happy02",
                },
            ["GUID"] = "7FFBCEB2",
            ["NextDialogue"] = 51124022,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_Start",
                },
            },
        [51124022] = {
            ["Content"] = "现在在我这里，你已经是个非常独特的皎皎了。",
            ["ContentJP"] = "少なくとも、{性别:僕|私}にとってはすごくユニークなルーナだと思うよ。",
            ["DialogueId"] = 51124022,
            ["GUID"] = "7FFBCEDC",
            ["NextDialogue"] = 51124023,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_End",
                },
            },
        [51124023] = {
            ["Content"] = "真的？那你不会把我和别的皎皎弄混淆吧？",
            ["ContentJP"] = "ほんと！？じゃあ、今度また会ったとき、他のルーナと見間違えたりしないでよね？",
            ["DialogueId"] = 51124023,
            ["GUID"] = "7FFBCF06",
            ["NextDialogue"] = 51124024,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Shy03_Start",
                },
            },
        [51124024] = {
            ["Content"] = "我想不会。",
            ["ContentJP"] = "たぶん大丈夫。",
            ["DialogueId"] = 51124024,
            ["GUID"] = "7FFBCF30",
            ["NextDialogue"] = 51124025,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701033:Shy03_End",
                },
            },
        [51124025] = {
            ["Content"] = "嘿嘿~这还差不多，如果下次你遇到我却把我和别的皎皎弄混，我可是会生气的。",
            ["ContentJP"] = "ふふっ、それならよし！もし次会って間違えたら……怒っちゃうんだから！",
            ["DialogueId"] = 51124025,
            ["FacialId"] = {
                [1] = "701033:Smile01",
                },
            ["GUID"] = "7FFBCF5A",
            ["NextDialogue"] = 51124026,
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_Start",
                },
            },
        [51124026] = {
            ["Content"] = "今天就聊到这里吧，你是个好有龙氏，但我要去研究更多的无由生，证明我是个在无由生研究上独一无二的皎皎啦。",
            ["ContentJP"] = "じゃ、今日はここまでにしとくわ。あなた、なかなか話せる<Default note=\"text:りゅうのたみ\">龍の民</>だったわね！あたしはまだまだムユウセイの研究を続けるから！「オンリーワンのムユウセイマスタールーナ」としてねっ！",
            ["DialogueId"] = 51124026,
            ["GUID"] = "7FFBCF84",
            ["SpeakNpcId"] = 701033,
            ["TalkActionId"] = {
                [1] = "701033:Explain01_End",
                },
            },
        [51124027] = {
            ["Content"] = "我是最独特的皎皎，是吧？",
            ["ContentJP"] = "私こそ最もユニークなルーナ族である。そうでしょう？",
            ["DialogueId"] = 51124027,
            ["GUID"] = "7FFBCFAE",
            ["SpeakNpcId"] = 701033,
            },
        [51125000] = {
            ["Content"] = "什么！妙趣那家伙今天也来不了！水土不服这都几天了啊！唉……那烟津渡的几场戏可怎么拍啊……",
            ["ContentJP"] = "なんだって！？ミヤのやつ、今日も来られないだと？もう何日も体調崩してるじゃないか……くそっ、<Default note=\"text:えんしんと\">煙津渡</>のシーンがまだ残ってるのに……",
            ["DialogueId"] = 51125000,
            ["GUID"] = "7FFC6F50",
            ["NextOptions"] = {
                [1] = 51125001,
                [2] = 51125002,
                },
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Angry01_Start",
                },
            },
        [51125001] = {
            ["Content"] = "（面前这位男子似乎有什么难处，过去看看有什么需要帮忙的地方吧。）",
            ["ContentJP"] = "目の前の男は、何か困っている様子だ。声をかけてみようかな。",
            ["DialogueId"] = 51125001,
            ["GUID"] = "7FFC6F7A",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125003,
            },
        [51125002] = {
            ["Content"] = "（你闻到了一丝麻烦事的气息，还是离远点好。）",
            ["ContentJP"] = "いやな予感がする……関わらない方がよさそうだ。",
            ["DialogueId"] = 51125002,
            ["GUID"] = "7FFC6FA4",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125003,
            },
        [51125003] = {
            ["Content"] = "诶，我看你这{性别：兄弟|姑娘}浓眉大眼的，是个演戏好苗子，有没有兴趣来我们剧组看看啊？",
            ["ContentJP"] = "おや、君――ずいぶん目鼻立ちのいい顔だね。芝居の素質がありそうだ。どうだい、うちの撮影に興味はあるかい？",
            ["DialogueId"] = 51125003,
            ["GUID"] = "7FFC6FCE",
            ["NextDialogue"] = 51125004,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Angry01_End",
                },
            },
        [51125004] = {
            ["Content"] = "我们在拍戏——嗯，就是那种很新的戏，叫“照影”的。你有兴趣吗？",
            ["ContentJP"] = "今ちょうど、「連鎖劇」って新スタイルの作品を撮ってるんだ……どう？",
            ["DialogueId"] = 51125004,
            ["GUID"] = "7FFC6FF8",
            ["SpeakNpcId"] = 700365,
            },
        [51125005] = {
            ["DialogueId"] = 51125005,
            ["GUID"] = "7FFC7022",
            },
        [51125006] = {
            ["Content"] = "甚好甚好。自我介绍一下，我们正在拍摄的照影叫《应天尉大战飘零人3：最后一战》，今天就得把烟津渡的戏全部拍完。",
            ["ContentJP"] = "よしよし、では改めて紹介させてくれ。この作品のタイトルは『応天尉VS流れ者3：最後の戦い』だ。今日は<Default note=\"text:えんしんと\">煙津渡</>での決戦シーンを撮らないといけなくてな。",
            ["DialogueId"] = 51125006,
            ["GUID"] = "7FFC704C",
            ["NextDialogue"] = 51125007,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Agree",
                },
            },
        [51125007] = {
            ["Content"] = "但我们的主演这几天连床都下不来，更别提拍摄了。所以你来我们这客串一下应天尉吧。这个应天尉之前也没登过场，换个新人再合适不过。",
            ["ContentJP"] = "けど、主演が寝込んじまっててさ。ベッドから起き上がるのも無理だときた。撮影どころじゃない。そこでだ、君にちょっと「応天尉」を演じてもらいたくてね。このキャラ、今回が初登場だし、交代しても違和感はないよ。",
            ["DialogueId"] = 51125007,
            ["GUID"] = "7FFC7076",
            ["NextDialogue"] = 51125008,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Talk02_Start",
                },
            },
        [51125008] = {
            ["Content"] = "可是我不会拍戏。",
            ["ContentJP"] = "でも……演技なんて、やったことないよ。",
            ["DialogueId"] = 51125008,
            ["GUID"] = "7FFC70A0",
            ["NextDialogue"] = 51125009,
            ["SpeakNpcId"] = 100001,
            },
        [51125009] = {
            ["Content"] = "没事没事，这场戏简单得很，就是咱们华胥最常见的正义应天尉打败邪恶飘零人的故事。",
            ["ContentJP"] = "大丈夫大丈夫！今回のシーンは簡単だから。正義の応天尉が悪の流れ者を倒す、定番のヒーローものだ。",
            ["DialogueId"] = 51125009,
            ["GUID"] = "7FFC70CA",
            ["NextDialogue"] = 51125010,
            ["SpeakNpcId"] = 700365,
            },
        [51125010] = {
            ["Content"] = "文戏不长，你也不用背太多台词。主要体现的是那种正派的气质，基本往那一站感觉对了，就没问题。",
            ["ContentJP"] = "登場シーンも、セリフも少ないから。立ち姿と目線――要は「正義の風格」さえあれば十分ってわけ。",
            ["DialogueId"] = 51125010,
            ["GUID"] = "7FFC70F4",
            ["NextDialogue"] = 51125011,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Talk02_End",
                },
            },
        [51125011] = {
            ["Content"] = "横生！我们的临时主角找到了，赶紧过来对一下剧本，半个时辰以后开拍。",
            ["ContentJP"] = "おい、オウセイ！臨時の主役が決まったぞ！すぐに脚本合わせだ。1時間後にカメラ回すぞ！",
            ["DialogueId"] = 51125011,
            ["GUID"] = "7FFC711E",
            ["SpeakNpcId"] = 700365,
            },
        [51125012] = {
            ["Content"] = "（远处一位衣着简朴的男人听罢，拿起手边厚厚的本子，嘴里一边咕哝着什么一边跑了过来。）",
            ["ContentJP"] = "遠くにいた簡素な身なりの男が分厚い台本を手に、何やらブツブツ言いながら駆け寄ってきた。",
            ["DialogueId"] = 51125012,
            ["GUID"] = "7FFC7148",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125013,
            },
        [51125013] = {
            ["Camera"] = "325.265625,-73.105469,141.634766,0.017556,-1.600095,166.905365,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啧，你好，我叫横生，没有妙趣，也不是无由生。给，这是你的台本。",
            ["ContentJP"] = "どもども、俺はオウセイだ。ミヤでもムユウセイでもない。ほれ、これが君の台本だ。",
            ["DialogueId"] = 51125013,
            ["GUID"] = "7FFC7172",
            ["NextDialogue"] = 51125014,
            ["SpeakNpcId"] = 700366,
            ["TalkActionId"] = {
                [1] = "700366:Give",
                },
            },
        [51125014] = {
            ["Content"] = "（你接过横生递来的台本。乍看下来确实没什么演出难度。只要<H>不出什么意外</>的话……）",
            ["ContentJP"] = "台本を受け取った。ざっと見た感じ、それほど難しい演技ではない。<H>順調に進めば</></>の話だが……",
            ["DialogueId"] = 51125014,
            ["GUID"] = "7FFC719C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125015,
            },
        [51125015] = {
            ["Content"] = "一小时后……",
            ["ContentJP"] = "1時間後……",
            ["DialogueId"] = 51125015,
            ["GUID"] = "7FFC71C6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125016,
            },
        [51125016] = {
            ["Camera"] = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我乃应天尉，上承天命，下斩邪祟。尔等飘零人，还不速速伏法！",
            ["ContentJP"] = "我が名は応天尉！天の命を受け、この地に正義をもたらす者なり！流れ者よ、今こそ成敗してくれよう！",
            ["DialogueId"] = 51125016,
            ["GUID"] = "7FFC71F0",
            ["NextDialogue"] = 51125017,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Angry01_Start",
                },
            },
        [51125017] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哈哈哈哈……应天尉大人，你英明一世，糊涂一时，连中计了都浑然不知。你可识得此物？",
            ["ContentJP"] = "ハッハッハ……応天尉サマも、案外お甘いことで。名は轟けど、足元ガラ空きとは。……この品に、見覚えは？",
            ["DialogueId"] = 51125017,
            ["GUID"] = "7FFC721A",
            ["NextDialogue"] = 51125018,
            ["SpeakNpcId"] = 700366,
            ["TalkActionId"] = {
                [1] = "100001:Angry01_End",
                },
            },
        [51125018] = {
            ["Camera"] = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这是……缚仙索……尔等竟用此阴毒计俩！",
            ["ContentJP"] = "これは……まさか……<Default note=\"text:あまのくさり\">縛仙鎖</>か！？貴様ら、なんと卑怯な！",
            ["DialogueId"] = 51125018,
            ["FacialId"] = {
                [1] = "100001:Shock02",
                },
            ["GUID"] = "7FFC7244",
            ["NextDialogue"] = 51125019,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Shock02_Start",
                },
            },
        [51125019] = {
            ["Camera"] = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼，有了此物，管你是狴犴还是应天尉，便是那高高在上的白龙神君，我也杀给你看！",
            ["ContentJP"] = "フン！これさえあれば、応天尉だろうが、<Default note=\"text:ビーアン\">狴犴</>だろうが、白龍様だろうが、イチコロだ！",
            ["DialogueId"] = 51125019,
            ["GUID"] = "7FFC726E",
            ["NextDialogue"] = 51125020,
            ["SpeakNpcId"] = 700366,
            },
        [51125020] = {
            ["Content"] = "今日我即使战死在此，也不容尔等宵小对神君放肆！",
            ["ContentJP"] = "くっ、たとえここで殺されようと、貴様らのような外道に、神を侮辱する資格などない！",
            ["DialogueId"] = 51125020,
            ["GUID"] = "7FFC7298",
            ["NextDialogue"] = 51125021,
            ["SpeakNpcId"] = 100001,
            },
        [51125021] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘻嘻，看是你应天尉的命硬，还是我飘零人的刀子硬！弟兄们——",
            ["ContentJP"] = "フハハ、応天尉の命と流れ者の刀、果たしてどちらが上かな！野郎ども――かかれ！",
            ["DialogueId"] = 51125021,
            ["GUID"] = "7FFC72C2",
            ["SpeakNpcId"] = 700366,
            },
        [51125022] = {
            ["Camera"] = "94.78125,-111.488281,172.178711,0.017554,-4.800099,138.306519,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "来嘞！",
            ["ContentJP"] = "おうっ！",
            ["DialogueId"] = 51125022,
            ["GUID"] = "7FFC72EC",
            ["NextDialogue"] = 51125023,
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125023] = {
            ["Camera"] = "269.707031,21.212891,176.939453,0.017553,-5.400084,157.106674,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好，按照我们之前说的，接下来是今天的第一场打戏。三、二、一，开始——",
            ["ContentJP"] = "よーし、打ち合わせ通りに行くぞ！今日一発目のバトルシーンだ！３、２、１……アクション！",
            ["DialogueId"] = 51125023,
            ["GUID"] = "7FFC7316",
