        [51125027] = {
            ["DialogueId"] = 51125027,
            ["GUID"] = "7FFC73BE",
            },
        [51125028] = {
            ["Content"] = "宵小退散！",
            ["ContentJP"] = "卑怯者め、散れ！",
            ["DialogueId"] = 51125028,
            ["GUID"] = "7FFC73E8",
            ["NextDialogue"] = 51125029,
            ["SpeakNpcId"] = 100001,
            },
        [51125029] = {
            ["Content"] = "这厮好生厉害，中了缚仙索还不落下风！兄弟们快撤！",
            ["ContentJP"] = "こいつ、縛仙鎖をくらってながら……なおも怯まぬとは！全員退却だ！",
            ["DialogueId"] = 51125029,
            ["GUID"] = "7FFC7412",
            ["NextDialogue"] = 51125030,
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125030] = {
            ["Content"] = "哪里逃？！",
            ["ContentJP"] = "逃がすか！",
            ["DialogueId"] = 51125030,
            ["GUID"] = "7FFC743C",
            ["NextDialogue"] = 51125031,
            ["SpeakNpcId"] = 100001,
            },
        [51125031] = {
            ["Content"] = "还没结束呢……吃我正义的毒针！",
            ["ContentJP"] = "まだ終わっちゃいないぜ……正義の「毒針」ってやつを味わわせてやる！",
            ["DialogueId"] = 51125031,
            ["GUID"] = "7FFC7466",
            ["NextDialogue"] = 51125032,
            ["SpeakNpcId"] = 700366,
            },
        [51125032] = {
            ["Content"] = "（等下，台词里有“正义的毒针”吗？）",
            ["ContentJP"] = "（……え？台本に正義の「毒針」なんてセリフあったっけ？）",
