      return {
        [51125052] = {
            ["Content"] = "事儿办好了都是白龙神君英明神武，办砸了都是我们办事不力！还不如当个飘零人，逍遥自在！我是，飘——零——人——",
            ["ContentJP"] = "功績を挙げれば「白龍様のおかげ」だと讃えられ、やらかせば「無能な下っ端」だと罵られる――そんな人生、まっぴらだ！自由自在な流れ者になった方がよっぽどマシじゃないか！",
            ["DialogueId"] = 51125052,
            ["GUID"] = "7FFC77D8",
            ["NextDialogue"] = 51125053,
            ["SpeakNpcId"] = 700366,
            },
        [51125053] = {
            ["Camera"] = "-352.015625,-106.05957,152.610352,0.017523,-3.999574,17.508425,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等一下！我们的剧本里真的有这些词吗？",
            ["ContentJP"] = "いや待って、今のセリフ、台本にあったっけ……？",
            ["DialogueId"] = 51125053,
            ["GUID"] = "7FFC7802",
            ["NextDialogue"] = 51125054,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_End",
                },
            },
        [51125054] = {
            ["Content"] = "按照剧本，应该是你说完“那又如何”马上冲上来，然后我强忍着痛大战你们几个飘零人，把你们打翻在地才是……",
            ["ContentJP"] = "たしか台本では、「それがどうした！」って言ったあと、すぐ走って来る流れだったはず。で、{性别:僕|私}は傷をこらえながら流れ者たちを叩き伏せて――",
            ["DialogueId"] = 51125054,
            ["GUID"] = "7FFC782C",
            ["NextDialogue"] = 51125055,
            ["SpeakNpcId"] = 100001,
            },
        [51125055] = {
            ["Camera"] = "-183.84375,271.606445,161.805664,0.017533,-4.59964,-29.49268,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "导演，这对吗，这不对吧！",
            ["ContentJP"] = "監督さん！今のは絶対違うでしょ！",
            ["DialogueId"] = 51125055,
            ["GUID"] = "7FFC7856",
            ["SpeakNpcId"] = 100001,
            },
        [51125056] = {
            ["Camera"] = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "停停停！",
