            ["NextDialogue"] = 51125058,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Talk03_End",
                },
            },
        [51125058] = {
            ["Content"] = "这不是导演你教我们的吗，什么来着——优秀的演员要学会给自己的角色增加高光！",
            ["ContentJP"] = "でも監督、前に言ってたじゃないっすか。「役者たるもの、自分のキャラに「見せ場」を足すくらいの気概を持て」って！",
            ["DialogueId"] = 51125058,
            ["GUID"] = "7FFC78D4",
            ["LookAt"] = {
                [1] = "700366:n(700365)",
                },
            ["NextDialogue"] = 51125059,
            ["SpeakNpcId"] = 700366,
            },
        [51125059] = {
            ["Content"] = "嘶……好像还真是我说的。",
            ["ContentJP"] = "……言った、かもな……確かに。",
            ["DialogueId"] = 51125059,
            ["GUID"] = "7FFC78FE",
