            ["TalkActionId"] = {
                [1] = "700365:Think_Start",
                },
            },
        [51125060] = {
            ["Content"] = "是吧是吧。",
            ["ContentJP"] = "でしょでしょ？",
            ["DialogueId"] = 51125060,
            ["GUID"] = "7FFC7928",
            ["NextDialogue"] = 51125061,
            ["SpeakNpcId"] = 700366,
            },
        [51125061] = {
            ["Content"] = "不对，再怎么说你演的也只是一个反派，后面要被正派应天尉大人一剑砍死的！你一个反派加什么高光！",
            ["ContentJP"] = "でもだな！お前が演じてるのは噛ませ役の悪役だ！最終的には正義の応天尉に一太刀でやられる運命のな！",
            ["DialogueId"] = 51125061,
            ["GUID"] = "7FFC7952",
            ["NextDialogue"] = 51125062,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "700365:Think_End",
                },
            },
        [51125062] = {
            ["Content"] = "反派反派，我跟着导演你排了那么多年戏，你老让我演反派！就连妙趣请假了，还是不让我演那应天尉过过瘾，宁愿找个陌生人。",
            ["ContentJP"] = "俺、ずっと悪役をやらされてきたんスよ？もう何年も、ずーーっと。ミヤが来れなくなった今ぐらい、主役をやらせてくれても……",
            ["DialogueId"] = 51125062,
            ["FacialId"] = {
                [1] = "700366:CM_Angry01",
                },
            ["GUID"] = "7FFC797C",
            ["NextDialogue"] = 51125063,
            ["SpeakNpcId"] = 700366,
            },
        [51125063] = {
            ["Camera"] = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你看你那油里油气的样子，我说应天尉长这样，有人信吗？",
            ["ContentJP"] = "でもなあ、お前のその脂ぎった顔で応天尉やっても……正義の味方らしくないだろう？",
            ["DialogueId"] = 51125063,
            ["GUID"] = "7FFC79A6",
            ["NextDialogue"] = 51125064,
            ["SpeakNpcId"] = 700365,
            },
        [51125064] = {
            ["Camera"] = "127.339844,-18.349609,122.799805,0.017557,2.000023,179.711273,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么就不行？你也说过，优秀的演员应该有“整容式演技”。真让我穿上应天尉的行头，我保证演得不比妙趣差！说到底，你还是不信任我的演技。",
            ["ContentJP"] = "顔じゃないっすよ、演技っすよ演技！監督も言ってたじゃないですか、「演技は整形だ」って！本気でやれば、俺だってミヤに負けねぇ応天尉やってみせますよ！結局、監督は俺の芝居を信用してないだけなんだ！",
            ["DialogueId"] = 51125064,
            ["GUID"] = "7FFC79D0",
            ["NextDialogue"] = 51125065,
            ["SpeakNpcId"] = 700366,
            },
        [51125065] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就这样吧，今天小爷我不演了！走了走了！",
            ["ContentJP"] = "もういいっす、今日は降りますわ！やってらんねぇ！帰る！",
            ["DialogueId"] = 51125065,
            ["GUID"] = "7FFC79FA",
            ["NextDialogue"] = 51125066,
            ["SpeakNpcId"] = 700366,
            },
        [51125066] = {
            ["Content"] = "喂，喂，怎么就生气了！冷静一点！今天可是我们的最后期限啊！",
            ["ContentJP"] = "ちょっ、待てって！落ち着けオウセイ！今日は締切なんだぞ！",
            ["DialogueId"] = 51125066,
            ["GUID"] = "7FFC7A24",
            ["NextDialogue"] = 51125067,
            ["SpeakNpcId"] = 700365,
            },
        [51125067] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………{性别：兄弟|姑娘}你怎么看，现在这样拍下去确实不太行，要不，你俩换一下试试？",
            ["ContentJP"] = "…………なぁ、{性别:あんちゃん|嬢ちゃん}、ちょっと相談なんだけどさ。今の空気で続けるのは無理がある。オウセイと役を交代してみないか？",
            ["DialogueId"] = 51125067,
            ["GUID"] = "7FFC7A4E",
            ["LookAt"] = {
                [1] = "700365:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51125068,
                [2] = 51125069,
                },
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "100001:Think_Start",
                },
            },
        [51125068] = {
            ["Content"] = "看他这么想演，就让给他吧。",
            ["ContentJP"] = "……あんなに出たがってるなら、譲ってあげるよ。",
            ["DialogueId"] = 51125068,
            ["GUID"] = "7FFC7A78",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51125070,
            },
        [51125069] = {
            ["Content"] = "可以，得加钱。",
            ["ContentJP"] = "いいよ、その代わりギャラ上乗せね。",
            ["DialogueId"] = 51125069,
            ["GUID"] = "7FFC7AA2",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51125070,
            },
        [51125070] = {
            ["Content"] = "行，安排。",
            ["ContentJP"] = "……了解、段取り変えるよ！",
            ["DialogueId"] = 51125070,
            ["GUID"] = "7FFC7ACC",
            ["NextDialogue"] = 51125071,
            ["SpeakNpcId"] = 700365,
            ["TalkActionId"] = {
                [1] = "100001:Think_End",
                },
            },
        [51125071] = {
            ["Content"] = "几分钟后……",
            ["ContentJP"] = "数分後……",
            ["DialogueId"] = 51125071,
            ["GUID"] = "7FFC7AF6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51125072,
            },
        [51125072] = {
            ["Camera"] = "246.074219,-350.594727,117.375,0.01754,0.797944,105.297958,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51125072,
            ["GUID"] = "7FFC7B20",
            ["NextDialogue"] = 51125073,
            ["SpeakNpcId"] = 700365,
            },
        [51125073] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 51125073,
            ["GUID"] = "7FFC7B4A",
            ["LookAt"] = {
                [1] = "100001:n(700365)",
                },
            ["NextDialogue"] = 51125074,
            ["SpeakNpcId"] = 100001,
            },
        [51125074] = {
            ["Content"] = "……你真能演成反派吗，你这气质怎么看都更像那些违禁小说里的，那什么，“山外山大侠”啊……",
            ["ContentJP"] = "お前な……悪役が、なんで「<H>山外山</>で修行してた侠客」みたくなってんの……",
            ["DialogueId"] = 51125074,
            ["GUID"] = "7FFC7B74",
            ["NextDialogue"] = 51125075,
            ["SpeakNpcId"] = 700365,
            },
        [51125075] = {
            ["Content"] = "算了，看看横生那边换好了没。",
            ["ContentJP"] = "……もういい、オウセイがちゃんと着替えてきたか見てこい。",
            ["DialogueId"] = 51125075,
            ["GUID"] = "7FFC7B9E",
            ["SpeakNpcId"] = 700365,
            },
        [51125076] = {
            ["DialogueId"] = 51125076,
            ["GUID"] = "7FFC7BC8",
            ["IsBlack"] = 1,
            },
        [51125077] = {
            ["Camera"] = "-515.558594,-201.037109,125.110352,0.017539,0.198321,23.096621,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "演了十几年反派，今天终于轮到我当正派了，哈哈哈哈哈哈！",
            ["ContentJP"] = "十数年、悪役ばっかやらされてきたが……ついに！ついに俺にも正義の主役が回ってきたぜ！はっはっはっはっは！！",
            ["DialogueId"] = 51125077,
            ["GUID"] = "7FFC7BF2",
            ["NextDialogue"] = 51125078,
            ["SpeakNpcId"] = 700379,
            },
        [51125078] = {
            ["Content"] = "嘿你看，我现在是应天尉哦，帅不帅？唰——飒——咻咻咻——啊！",
            ["ContentJP"] = "見てくれよ、今の俺は応天尉だぜ？カッコいいだろ？――シュバッ！サッ！ヒュンヒュンヒュン！ハッ！",
            ["DialogueId"] = 51125078,
            ["GUID"] = "7FFC7C1C",
            ["NextDialogue"] = 51125079,
            ["SpeakNpcId"] = 700379,
            },
        [51125079] = {
            ["Content"] = "导演，你看我说的吧，是不是活生生一名应天尉了！",
            ["ContentJP"] = "監督ぅ、言っただろ？これぞ生き写しの応天尉ってやつだと思いません？",
            ["DialogueId"] = 51125079,
            ["GUID"] = "7FFC7C46",
            ["NextDialogue"] = 51125080,
            ["SpeakNpcId"] = 700379,
            },
        [51125080] = {
            ["Content"] = "这真的能行吗……算了，说不定入戏以后就不是这样了呢……来来来，都动起来，开拍开拍！",
            ["ContentJP"] = "……いや、お前……まあ……始まってみたら意外とハマる……かも？と、とにかく皆！位置ついて！撮影始めるぞー！",
            ["DialogueId"] = 51125080,
            ["GUID"] = "7FFC7C70",
            ["SpeakNpcId"] = 700365,
            },
        [51125081] = {
            ["DialogueId"] = 51125081,
            ["GUID"] = "7FFC7C9A",
            ["IsBlack"] = 1,
            },
        [51125082] = {
            ["Content"] = "可恶……没有力气！",
            ["ContentJP"] = "くっ……身体に力が入らない……！",
            ["DialogueId"] = 51125082,
            ["GUID"] = "7FFC7CC4",
            ["NextDialogue"] = 51125083,
            ["SpeakNpcId"] = 700379,
            },
        [51125083] = {
            ["Content"] = "兄弟们，上啊！",
            ["ContentJP"] = "今だ、やれ！",
            ["DialogueId"] = 51125083,
            ["GUID"] = "7FFC7CEE",
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125084] = {
            ["DialogueId"] = 51125084,
            ["GUID"] = "7FFC7D18",
            ["IsBlack"] = 1,
            },
        [51125085] = {
            ["Content"] = "哼——宵小！嗬——退散！",
            ["ContentJP"] = "卑怯者め、散れ！",
            ["DialogueId"] = 51125085,
            ["GUID"] = "7FFC7D42",
            ["NextDialogue"] = 51125086,
            ["SpeakNpcId"] = 700379,
            },
        [51125086] = {
            ["Content"] = "这厮好生厉害，中了缚仙索还不落下风！兄弟们快撤！",
            ["ContentJP"] = "こいつ、縛仙鎖をくらってながら……なおも怯まぬとは！全員退却だ！",
            ["DialogueId"] = 51125086,
            ["GUID"] = "7FFC7D6C",
            ["NextDialogue"] = 51125087,
            ["SpeakNpcName"] = "UI_CMNpc_Name_QunYan",
            },
        [51125087] = {
            ["Content"] = "呔！哪里逃！",
            ["ContentJP"] = "ぬぅん！逃がすか！",
            ["DialogueId"] = 51125087,
            ["GUID"] = "7FFC7D96",
            ["NextDialogue"] = 51125088,
            ["SpeakNpcId"] = 700379,
            },
        [51125088] = {
            ["Content"] = "看针！",
            ["ContentJP"] = "この毒針をくらえ！",
            ["DialogueId"] = 51125088,
            ["GUID"] = "7FFC7DC0",
            ["NextDialogue"] = 51125089,
            ["SpeakNpcId"] = 100001,
            },
        [51125089] = {
            ["Content"] = "哼！区区毒针，我避它锋芒！",
            ["ContentJP"] = "ふんっ、毒ごとき！刃筋、逸らしてみせる！",
            ["DialogueId"] = 51125089,
            ["GUID"] = "7FFC7DEA",
            ["SpeakNpcId"] = 700379,
            },
        [51125090] = {
            ["DialogueId"] = 51125090,
            ["GUID"] = "7FFC7E14",
            ["IsBlack"] = 1,
            },
        [51125091] = {
            ["Content"] = "等等，这不在剧本里吧。",
            ["ContentJP"] = "ちょ、待って！それ、台本にないけど！？",
            ["DialogueId"] = 51125091,
            ["GUID"] = "7FFC7E3E",
            ["NextDialogue"] = 51125092,
            ["SpeakNpcId"] = 100001,
            },
        [51125092] = {
            ["Content"] = "咿嘻嘻嘻嘻，你这小毒针算什么啊。我手上这把，可是沾满了剧毒的大斧哦~",
            ["ContentJP"] = "ヒヒヒヒ……その毒針じゃ俺は止まらねぇよ。見ろよ、この剣の毒を！毒の塗られた劇中最強の宝剣様だ〜！",
            ["DialogueId"] = 51125092,
            ["GUID"] = "7FFC7E68",
            ["NextDialogue"] = 51125093,
            ["SpeakNpcId"] = 700379,
            },
        [51125093] = {
            ["Content"] = "（怎么又在加戏！）",
            ["ContentJP"] = "（またアドリブ入れた！！）",
            ["DialogueId"] = 51125093,
            ["GUID"] = "7FFC7E92",
            ["SpeakNpcId"] = 100001,
            },
        [51125094] = {
            ["DialogueId"] = 51125094,
            ["GUID"] = "7FFC7EBC",
            ["IsBlack"] = 1,
            },
        [51125095] = {
            ["Camera"] = "493.785156,-135.24707,12.011719,0.017552,14.799428,162.905365,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "应天尉大人，你再英明神武，也敌不过这背后的毒针吧！",
            ["ContentJP"] = "フン、応天尉サマ……いかに武勇があろうと、不意打ちには敵うまい！",
            ["DialogueId"] = 51125095,
            ["GUID"] = "7FFC7EE6",
            ["NextDialogue"] = 51125096,
            ["SpeakNpcId"] = 100001,
            },
        [51125096] = {
            ["Camera"] = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……………………",
            ["ContentJP"] = "……………………",
            ["DialogueId"] = 51125096,
            ["GUID"] = "7FFC7F10",
            ["NextDialogue"] = 51125097,
            ["SpeakNpcId"] = 700379,
            },
        [51125097] = {
            ["Camera"] = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说台词啊！",
            ["ContentJP"] = "セリフは！？",
            ["DialogueId"] = 51125097,
            ["GUID"] = "7FFC7F3A",
            ["NextDialogue"] = 51125098,
            ["SpeakNpcId"] = 100001,
            },
        [51125098] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么词来着？",
            ["ContentJP"] = "え？なんだっけ？",
            ["DialogueId"] = 51125098,
            ["GUID"] = "7FFC7F64",
            ["NextDialogue"] = 51125099,
            ["SpeakNpcId"] = 700379,
            },
        [51125099] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“你家族世代为悬衡派香官，满门忠良，怎就出了你这败类！”",
            ["ContentJP"] = "「貴様の一族は代々……<Default note=\"text:けんこうは\">懸衡派</>の香官として忠義を貫いてきた。なぜ貴様のような外道が！」",
            ["DialogueId"] = 51125099,
            ["GUID"] = "7FFC7F8E",
            ["NextDialogue"] = 51125100,
            ["SpeakNpcId"] = 100001,
            },
        [51125100] = {
            ["Camera"] = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘿，骂谁败类呢？怎么就败类了呢？你想想，我们在悬衡派干的那都是什么活啊，报酬没给多少，一天到晚烧个破香熏得要死，假期也没几天。",
            ["ContentJP"] = "誰が外道だって！？懸衡派では、ひたすら香を焚いて燻されるだけの地味な仕事ばっか。給料は薄いし、休みもほとんどなし。朝から晩まで、香炉と睨めっこで寿命削られる毎日だぞ。このどこが外道なんだよ！",
            ["DialogueId"] = 51125100,
            ["GUID"] = "7FFC7FB8",
            ["NextDialogue"] = 51125101,
            ["SpeakNpcId"] = 700379,
            },
        [51125101] = {
            ["Content"] = "还整天受大风九章的条条框框拘束，连踹条路边的狗都不行，万一一不小心踹到了主人，还得担心被当成行凶。",
            ["ContentJP"] = "おまけに、大風九章の規則にガチガチに縛られてよ、道ばたの悪犬ひとつ蹴れやしねえ。もしそれがどっかの飼い犬だったら……下手すりゃ処罰だ。",
            ["DialogueId"] = 51125101,
            ["GUID"] = "7FFC7FE2",
            ["NextDialogue"] = 51125102,
            ["SpeakNpcId"] = 700379,
            },
        [51125102] = {
            ["Camera"] = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等一下……",
            ["ContentJP"] = "ちょっと待って……",
            ["DialogueId"] = 51125102,
            ["GUID"] = "7FFC800C",
            ["NextDialogue"] = 51125103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_Start",
                },
            },
        [51125103] = {
            ["Camera"] = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "事儿办好了都是白龙神君英明神武，办砸了都是我们办事不力！还不如当个飘零人，逍遥自在！",
            ["ContentJP"] = "功績を挙げれば「白龍様のおかげ」だと讃えられ、やらかせば「無能な下っ端」だと罵られる――そんな人生、まっぴらだ！自由自在な流れ者になった方がよっぽどマシじゃないか！",
            ["DialogueId"] = 51125103,
            ["GUID"] = "7FFC8036",
            ["NextDialogue"] = 51125104,
            ["SpeakNpcId"] = 700379,
            },
        [51125104] = {
            ["Content"] = "嘻嘻，看是你应天尉的命硬，还是我飘零人的刀子硬！吃我正义的毒针！",
            ["ContentJP"] = "フハハ、応天尉の命と流れ者の刀、果たしてどちらが上かな！正義の「毒針」ってやつを味わわせてやる！",
            ["DialogueId"] = 51125104,
            ["GUID"] = "7FFC8060",
            ["SpeakNpcId"] = 700379,
            },
        [51125105] = {
            ["DialogueId"] = 51125105,
            ["GUID"] = "7FFC808A",
            },
        [51125106] = {
            ["Camera"] = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "精彩，一气呵成行云流水！果然横生你就是万里挑一的天选反派！",
            ["ContentJP"] = "……ブラボー！セリフの流れも芝居の流れも見事にぶっ壊してきたな！オウセイ、やはりお前は悪役の星だな！！",
            ["DialogueId"] = 51125106,
            ["FacialId"] = {
                [1] = "700365:CM_Happy01",
                },
            ["GUID"] = "7FFC80B4",
            ["NextDialogue"] = 51125107,
            ["SpeakNpcId"] = 700365,
            },
        [51125107] = {
            ["Content"] = "不拍了不拍了，收工！烟津渡这几场最后就靠我的导演剪辑版来救一救吧。",
            ["ContentJP"] = "よし、今日はもうここまで！カット！撤収！煙津渡のこの数シーンは……最悪、俺の監督編集版でどうにか仕上げるとしよう。",
            ["DialogueId"] = 51125107,
            ["GUID"] = "7FFC80DE",
            ["LookAt"] = {
                [1] = "700365:n(700379)",
                },
            ["NextDialogue"] = 51125108,
            ["SpeakNpcId"] = 700365,
            },
        [51125108] = {
            ["Content"] = "{性别：兄弟|姑娘}，这是你今天拍戏的报酬，拿好了。",
            ["ContentJP"] = "{性别:あんちゃん|嬢ちゃん}、今日はよく頑張ったな。これが今日のギャラだ、受け取ってくれ。",
            ["DialogueId"] = 51125108,
            ["GUID"] = "7FFC8108",
            ["LookAt"] = {
                [1] = "700365:n(100001)",
                },
            ["NextDialogue"] = 51125109,
            ["SpeakNpcId"] = 700365,
            },
        [51125109] = {
            ["Content"] = "（这一场荒唐的闹剧总算是落下了帷幕。横生如愿以偿地留下了他的高光时刻……或许。）",
            ["ContentJP"] = "こうして、騒がしくも滑稽な茶番劇は、一応の幕を下ろした――オウセイも念願の見せ場をフィルムの片端にねじ込んだ……のかもしれない。",
            ["DialogueId"] = 51125109,
            ["GUID"] = "7FFC8132",
            ["IsBlack"] = 1,
            },
        [51125201] = {
            ["Content"] = "呼……可算搬完了，这下没有遗漏了吧？",
            ["ContentJP"] = "ふぅ……ようやく運び終えた。これで全部だよな？",
            ["DialogueId"] = 51125201,
            ["GUID"] = "7FFC904A",
            ["NextDialogue"] = 51125202,
            ["SpeakNpcId"] = 701034,
            },
        [51125202] = {
            ["Content"] = "还没完呢，今天阿庄哥休工，咱俩得把他那一份也搬完。",
            ["ContentJP"] = "まだ終わってないぞ。今日はソウ兄貴が休みだから、兄貴の分まで俺たちで運ばなきゃ。",
            ["DialogueId"] = 51125202,
            ["GUID"] = "7FFC9074",
            ["NextDialogue"] = 51125203,
            ["SpeakNpcId"] = 701035,
            },
        [51125203] = {
            ["Content"] = "为何不让他明天自己来？",
            ["ContentJP"] = "なんで明日自分でやらせないんだ？",
            ["DialogueId"] = 51125203,
            ["GUID"] = "7FFC909E",
            ["NextDialogue"] = 51125204,
            ["SpeakNpcId"] = 701034,
            },
        [51125204] = {
            ["Content"] = "阿庄哥说家里有喜事，回来请咱们吃茶呢！",
            ["ContentJP"] = "ソウ兄貴の家にめでたいことがあったんだって。戻ったらお茶をごちそうしてくれるらしい！",
            ["DialogueId"] = 51125204,
            ["GUID"] = "7FFC90C8",
            ["NextDialogue"] = 51125205,
            ["SpeakNpcId"] = 701035,
            },
        [51125205] = {
            ["Content"] = "嘿！有好事也不叫我们，可得敲他一壶上好的碧茅！",
            ["ContentJP"] = "へえ！いいことがあったなら、上等な緑茶を一杯分はおごってもらわないとな！",
            ["DialogueId"] = 51125205,
            ["GUID"] = "7FFC90F2",
            ["SpeakNpcId"] = 701034,
            },
        [51125301] = {
            ["Content"] = "您别说，咱们华胥就是数一数二的安全，看到那四处巡逻的狴犴了没？但凡有奸人作恶，都会被迅速逮捕！",
            ["ContentJP"] = "なあ、やっぱり華胥は一番安全だよな。あちこちで狴犴が巡回してるの見ただろ？悪さした奴はすぐ捕まるんだ！",
            ["DialogueId"] = 51125301,
            ["GUID"] = "7FFCA0B2",
            ["NextDialogue"] = 51125302,
            ["SpeakNpcId"] = 701036,
            },
        [51125302] = {
            ["Content"] = "哼，我们海伯利亚也很安全的，知道帝国军团的威名吗？帝国的铁骑会踏破每一句反抗的声音。",
            ["ContentJP"] = "ふん、俺たちヒュペリアも安全だぞ。帝国軍の威光を知らんのか？反抗する声はすべて鉄騎で踏み潰される！",
            ["DialogueId"] = 51125302,
            ["GUID"] = "7FFCA0DC",
            ["NextDialogue"] = 51125303,
            ["SpeakNpcId"] = 701037,
            },
        [51125303] = {
            ["Content"] = "拉倒吧！从外头回来的织星客谁不说你们海伯利亚隔三差五就和南边打仗，这也能叫安全？",
            ["ContentJP"] = "やめとけよ。外から戻ってきた星織人はみんな言ってるぜ、「ヒュペリアはしょっちゅう南の国と戦争してる」って。それで安全とか笑わせんなよ。",
            ["DialogueId"] = 51125303,
            ["GUID"] = "7FFCA106",
            ["NextDialogue"] = 51125304,
            ["SpeakNpcId"] = 701036,
            },
        [51125304] = {
            ["Content"] = "打仗那是……那是帝国的本事……打仗的目的就是为了和平！",
            ["ContentJP"] = "戦争は……それは帝国の強さの証だ！平和のために戦ってるんだ！",
            ["DialogueId"] = 51125304,
            ["GUID"] = "7FFCA130",
            ["NextDialogue"] = 51125305,
            ["SpeakNpcId"] = 701037,
            },
        [51125305] = {
            ["Content"] = "啧啧，那你为何苦苦要来华胥生活？姐们，来了华胥，只要你一心向善，白龙神君就会护佑你日日平安。",
            ["ContentJP"] = "チッ、それならなんでわざわざ華胥に来た？いいか相棒、ここじゃ善い心でいれば白龍様が毎日お前を守ってくれるんだぜ。",
            ["DialogueId"] = 51125305,
            ["GUID"] = "7FFCA15A",
            ["SpeakNpcId"] = 701036,
            },
        [51125401] = {
            ["Content"] = "这荒塔倒是上了年头了，想来曾经也是咱们机枢派的杰作，竟任由它被风吹雨打，无人维护……",
            ["ContentJP"] = "この古びた塔、ずいぶん前のものみたいだな。かつては機枢派の傑作だったんだろうに、今じゃ風雨にさらされて放置とは……",
            ["DialogueId"] = 51125401,
            ["GUID"] = "7FFCB11A",
            ["NextOptions"] = {
                [1] = 51125402,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125402] = {
            ["Content"] = "这是做什么用的？",
            ["ContentJP"] = "これは何に使われてたんだ？",
            ["DialogueId"] = 51125402,
            ["GUID"] = "7FFCB144",
            ["NextDialogue"] = 51125403,
            },
        [51125403] = {
            ["Content"] = "放在以前，是机枢派帮助织星客们建造的卜天楼，但要说现在……无人在意的废铜烂铁罢了。",
            ["ContentJP"] = "昔はな、機枢派が星織人のために建てた「<Default note=\"text:ぼくてんろう\">卜天楼</>」ってやつだ。けど今となっちゃ、ただの錆びた鉄くずさ。",
            ["DialogueId"] = 51125403,
            ["GUID"] = "7FFCB16E",
            ["NextOptions"] = {
                [1] = 51125404,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125404] = {
            ["Content"] = "卜天楼是？",
            ["ContentJP"] = "ぼく てんろう？",
            ["DialogueId"] = 51125404,
            ["GUID"] = "7FFCB198",
            ["NextDialogue"] = 51125405,
            },
        [51125405] = {
            ["Content"] = "卜算天象，测绘吉凶。说是这么说，但没这么玄乎，只是用于更好观测星空，推断后几日的天气情况的装置罢了。",
            ["ContentJP"] = "天象を観測して、吉凶を測るための塔だよ。まあ、言ってるほど神秘的なもんじゃない。星の動きを観て天気を予測するための装置だった。",
            ["DialogueId"] = 51125405,
            ["GUID"] = "7FFCB1C2",
            ["NextOptions"] = {
                [1] = 51125406,
                },
            ["SpeakNpcId"] = 701038,
            },
        [51125406] = {
            ["Content"] = "那为什么荒废了？",
            ["ContentJP"] = "じゃあ、なんで今は使われてない{性别:んだ|の}？",
            ["DialogueId"] = 51125406,
            ["GUID"] = "7FFCB1EC",
            ["NextDialogue"] = 51125407,
            },
        [51125407] = {
            ["Content"] = "……那可就说来话长了。最开始只是机枢派落魄，塔楼少人维护，计量结果也不怎么灵准了。",
            ["ContentJP"] = "……それは長くなる話だな。最初は機枢派が衰えて、塔を管理する人が減ったんだ。それで測定も狂い始めてさ。",
            ["DialogueId"] = 51125407,
            ["GUID"] = "7FFCB216",
            ["NextDialogue"] = 51125408,
            ["SpeakNpcId"] = 701038,
            },
        [51125408] = {
            ["Content"] = "后面织星客们改良了千星板，也能起到一定预测天气的作用，这塔便失去了作用。",
            ["ContentJP"] = "そのうち、星織人たちが「千星板」を改造して天気をある程度読めるようになった。そしたらこの塔の出番もなくなったってわけ。",
            ["DialogueId"] = 51125408,
            ["GUID"] = "7FFCB240",
            ["NextDialogue"] = 51125409,
            ["SpeakNpcId"] = 701038,
            },
        [51125409] = {
            ["Content"] = "不过要我说，若是机枢派还和百年以前一样风光，这塔应早该被后人迭新出其他作用才对。",
            ["ContentJP"] = "でもな、もし機枢派が昔みたいに栄えてたら、この塔もきっと別の使い道を見つけて進化してたはずなんだ。",
            ["DialogueId"] = 51125409,
            ["GUID"] = "7FFCB26A",
            ["NextDialogue"] = 51125410,
            ["SpeakNpcId"] = 701038,
            },
        [51125410] = {
            ["Content"] = "唉……都成过往，何必追溯。罢了，罢了……",
            ["ContentJP"] = "はぁ……もう昔のことだ。追いかけたって仕方ねぇ。忘れちまえ、忘れちまえ……",
            ["DialogueId"] = 51125410,
            ["GUID"] = "7FFCB294",
            ["SpeakNpcId"] = 701038,
            },
        [51125501] = {
            ["Content"] = "这位远来的小友，可否靠边站站？",
            ["ContentJP"] = "そこの君、少し端によってくれるかな？",
            ["DialogueId"] = 51125501,
            ["GUID"] = "7FFCC182",
            ["NextOptions"] = {
                [1] = 51125502,
                [2] = 51125505,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125502] = {
            ["Content"] = "不好意思。",
            ["ContentJP"] = "すみません。",
            ["DialogueId"] = 51125502,
            ["GUID"] = "7FFCC1AC",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125503,
            },
        [51125503] = {
            ["Content"] = "都是小事，异国小友来咱们华胥，恐怕也是人生地不熟，若是有什么地方疑惑不解，可以随时来问我。",
            ["ContentJP"] = "構わんよ。異国の者にとって、華胥は勝手の分からぬ土地だろう。わからないことがあったら、何でも聞いとくれ。",
            ["DialogueId"] = 51125503,
            ["GUID"] = "7FFCC1D6",
            ["NextDialogue"] = 51125504,
            ["SpeakNpcId"] = 701039,
            },
        [51125504] = {
            ["Content"] = "虽说我看起来平平无奇，但怎么也算是这浮星埠数一数二的点货人，上到天文地理下到民生风情，我啊，信手拈来。",
            ["ContentJP"] = "こう見えても、浮星埠じゃ指折りの点検員なんだ。天文地理から暮らしのことまで、まぁ、少しくらいは知ってるつもりさ。",
            ["DialogueId"] = 51125504,
            ["GUID"] = "7FFCC200",
            ["SpeakNpcId"] = 701039,
            },
        [51125505] = {
            ["Content"] = "这路好像也不是你的吧？",
            ["ContentJP"] = "……ここ、あなたの所有地じゃないよね？",
            ["DialogueId"] = 51125505,
            ["GUID"] = "7FFCC22A",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125506,
            },
        [51125506] = {
            ["Content"] = "诶呀这异国小友脾气就是有些大，我这是好心提醒你，这码头货工人来人往，搬运的全是重物，要是一个不小心磕碰到了你可如何是好？",
            ["ContentJP"] = "いやはや、異国の者はなんとも短気だな。これは君のためを思っての忠告だというのに。この港は人も荷物も多い。うっかりぶつかってケガでもされたら困るんだ。",
            ["DialogueId"] = 51125506,
            ["GUID"] = "7FFCC254",
            ["NextDialogue"] = 51125507,
            ["SpeakNpcId"] = 701039,
            },
        [51125507] = {
            ["Content"] = "小友初来乍到，对咱们华胥不熟悉也是正常，若是有什么不解，可随时来问我，虽说我只是个点货人，但毕竟也是土生土长的华胥之民。",
            ["ContentJP"] = "見知らぬ土地で勝手が分からないのは無理はない。わからないことがあったら、何でも聞いとくれ。私は点検員だが、生まれも育ちも華胥だから、この街のことには詳しいんだ。",
            ["DialogueId"] = 51125507,
            ["GUID"] = "7FFCC27E",
            ["SpeakNpcId"] = 701039,
            },
        [51125508] = {
            ["Content"] = "冰台五十斤，春一品三十斤，诶诶诶，那边的，香料都是稀奇货，搬运的时候可小心点！",
            ["ContentJP"] = "氷台五十斤に、春一品三十斤っと……おいおい、これらの香料はどれも珍しい品だ。運ぶときは気をつけてくれよ！",
            ["DialogueId"] = 51125508,
            ["GUID"] = "7FFCC2A8",
            ["NextDialogue"] = 51125509,
            },
        [51125509] = {
            ["Content"] = "哟，你是那位刚来华胥的异国小友吧，还在浮星埠？莫非其实是来经商的小掌柜？专门来看看我这点货人的日常活计。",
            ["ContentJP"] = "おや、君は……華胥に来たばかりの異国の方だったね。まだ浮星埠にいるってことは、もしかして商いをしに来たのかい？私の点検員としての仕事ぶりを身に来たとか？",
            ["DialogueId"] = 51125509,
            ["GUID"] = "7FFCC2D2",
            ["NextOptions"] = {
                [1] = 51125510,
                [2] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125510] = {
            ["Content"] = "我有事要问你。",
            ["ContentJP"] = "聞きたいことがある。",
            ["DialogueId"] = 51125510,
            ["GUID"] = "7FFCC2FC",
            ["NextDialogue"] = 51125511,
            },
        [51125511] = {
            ["Content"] = "你便问吧，我知晓的，必定一一答复于你。",
            ["ContentJP"] = "なんだい？知ってることなら、なんでも答えよう。",
            ["DialogueId"] = 51125511,
            ["GUID"] = "7FFCC326",
            ["NextOptions"] = {
                [1] = 51125512,
                [2] = 51125516,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125512] = {
            ["Content"] = "点货人是干什么的？",
            ["ContentJP"] = "点検員って？",
            ["DialogueId"] = 51125512,
            ["GUID"] = "7FFCC350",
            ["NextDialogue"] = 51125513,
            },
        [51125513] = {
            ["Content"] = "点货人，字如其名，自然是帮着织星客们清点货品的人物啦。",
            ["ContentJP"] = "読んで字のごとく、荷の数を点検する者さ。星織人たちの運ぶ品物の出入りを把握するのが私の役目だ。",
            ["DialogueId"] = 51125513,
            ["GUID"] = "7FFCC37A",
            ["NextDialogue"] = 51125514,
            ["SpeakNpcId"] = 701039,
            },
        [51125514] = {
            ["Content"] = "这浮星埠，每日吞吐船只容量大得很，要是只让织星客们自己清点这些货物，岂不是要忙坏他们了。",
            ["ContentJP"] = "ここ浮星埠は、毎日とんでもない量の船が出入りする。星織人たちが自分で荷物を数えなきゃならないとしたら、体がいくつあっても足りないだろうね。",
            ["DialogueId"] = 51125514,
            ["GUID"] = "7FFCC3A4",
            ["NextDialogue"] = 51125515,
            ["SpeakNpcId"] = 701039,
            },
        [51125515] = {
            ["Content"] = "所以我们点货人便应运而生，我们的主要任务就是帮着织星客们清点出入境的货物数量，防止有缺漏，届时也不好向国外的订购商们交代。",
            ["ContentJP"] = "だから、私たち点検員がいるんだ。荷の数をきっちり数えて、出入りの帳尻を合わせる。数が合わなきゃ、向こうの商人との揉め事も起こりかねないからな。",
            ["DialogueId"] = 51125515,
            ["GUID"] = "7FFCC3CE",
            ["NextOptions"] = {
                [1] = 51125516,
                [2] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125516] = {
            ["Content"] = "华胥的织星客们进出运输货物都需要登记吗？",
            ["ContentJP"] = "華胥の星織人たちは、出入りする荷物をすべて記録しているの？",
            ["DialogueId"] = 51125516,
            ["GUID"] = "7FFCC3F8",
            ["NextDialogue"] = 51125517,
            },
        [51125517] = {
            ["Content"] = "那是自然，一方面华胥贸易发达，天禄司上下管理繁琐，这出去和进来的货多少是要收些税金。",
            ["ContentJP"] = "ああ、もちろん。華胥の交易は大きいし、<Default note=\"text:てんろくし\">天禄司</>の連中も管理にはうるさい。出すにも入れるにも、きちんと帳をつけて税を納めるってのが決まりなんだ。",
            ["DialogueId"] = 51125517,
            ["GUID"] = "7FFCC422",
            ["NextDialogue"] = 51125518,
            ["SpeakNpcId"] = 701039,
            },
        [51125518] = {
            ["Content"] = "另一方面，华胥本身对一些重要香料配额管理便十分严苛，尤其是像吿苍这种本地人大量需求香料，若是任由织星客们贩至海外，咱们自己不够用如何是好？",
            ["ContentJP"] = "それに、華胥側にとって大事な香料なんかもあってな。たとえば「吿蒼」みたいなやつ──あれは需要が多くて、下手に海外に流されたら困る。だから配分も厳しく制限されてるのさ。",
            ["DialogueId"] = 51125518,
            ["GUID"] = "7FFCC44C",
            ["NextDialogue"] = 51125519,
            ["SpeakNpcId"] = 701039,
            },
        [51125519] = {
            ["Content"] = "这进来的东西自然更是需要登记，就说那什么海伯利亚，刀啊枪啊的，要是都进了华胥岂不是乱了套！",
            ["ContentJP"] = "逆に、外から入ってくる品も気が抜けない。たとえば、あのヒュペリアから刀やら銃やら持ち込まれてごらんよ──華胥の中がどうなるか、想像しただけでも背筋が寒くなるってもんだ。",
            ["DialogueId"] = 51125519,
            ["GUID"] = "7FFCC476",
            ["NextOptions"] = {
                [1] = 51125520,
                [2] = 51125524,
                [3] = 51125527,
                },
            ["SpeakNpcId"] = 701039,
            },
        [51125520] = {
            ["Content"] = "如果混进了违禁品呢？",
            ["ContentJP"] = "もし、禁制品が紛れ込んだら？",
            ["DialogueId"] = 51125520,
            ["GUID"] = "7FFCC4A0",
            ["NextDialogue"] = 51125521,
            },
        [51125521] = {
            ["Content"] = "小友啊小友，不是那么简单的事呀！且不说我们这样的点货人做得久了，光是看一眼货物大小，闻一闻香气，就能知道是运的何种货物。",
            ["ContentJP"] = "ふふ、それが一筋縄ではいかぬのさ。我々点検員ともなれば、荷の大きさや重さ、香りだけでだいたい見当がつく。長年の勘ってやつだ。",
            ["DialogueId"] = 51125521,
            ["GUID"] = "7FFCC4CA",
            ["NextDialogue"] = 51125522,
            ["SpeakNpcId"] = 701039,
            },
        [51125522] = {
            ["Content"] = "你再看看在这码头四周游走的狴犴大人们，我们点得出来的错额他们能知晓，我们点不出来的，更是瞒不过它们。",
            ["ContentJP"] = "それに、見てごらん、港のあちこちを巡っている<Default note=\"text:ビーアン\">狴犴</>様たちを。我らが見落としたものでも、あの方々の鼻はごまかせない。",
            ["DialogueId"] = 51125522,
            ["GUID"] = "7FFCC4F4",
            ["NextDialogue"] = 51125523,
            ["SpeakNpcId"] = 701039,
            },
        [51125523] = {
            ["Content"] = "为了防止有不好的东西进入咱们华胥，狴犴大人整日都在码头游走巡逻，大人们的鼻子可灵啦，一闻便知道有谁偷偷藏了东西。",
            ["ContentJP"] = "隠していたって、すぐに嗅ぎつけられるさ。",
            ["DialogueId"] = 51125523,
            ["GUID"] = "7FFCC51E",
            ["SpeakNpcId"] = 701039,
            },
        [51125524] = {
            ["Content"] = "所以你不是织星客？",
            ["ContentJP"] = "……つまり、あなたは星織人じゃないってこと？",
            ["DialogueId"] = 51125524,
            ["GUID"] = "7FFCC548",
            ["NextDialogue"] = 51125525,
            },
        [51125525] = {
            ["Content"] = "是，也不是，在华胥想成为织星客简单，但却没有必要一定要当个织星客。",
            ["ContentJP"] = "まあ、そうとも言えるし、そうでないとも言えるな。星織人になるのは簡単だが、私はそこにこだわってはいない。",
            ["DialogueId"] = 51125525,
            ["GUID"] = "7FFCC572",
            ["NextDialogue"] = 51125526,
            ["SpeakNpcId"] = 701039,
            },
        [51125526] = {
            ["Content"] = "商人做生意有赚有亏，我只想过好自己的日子，干着悠闲不忙碌的工作，拿着稳定的工资岂不美哉？何必与他们一样出海远航，家也不见得顾上。",
            ["ContentJP"] = "商売というものは、儲けることもあれば、損をすることもある。私はな、忙しさから少し離れて、堅実に生きていきたいだけさ。のんびりと働いて、安定した暮らしができれば、それで十分。海の向こうで奔走するのもいいが、家を空けてばかりでは、心も落ち着かぬだろう？",
            ["DialogueId"] = 51125526,
            ["GUID"] = "7FFCC59C",
            ["SpeakNpcId"] = 701039,
            },
        [51125527] = {
            ["Content"] = "我先走了。",
            ["ContentJP"] = "もう行くよ。",
            ["DialogueId"] = 51125527,
            ["GUID"] = "7FFCC5C6",
            ["NextDialogue"] = 51125528,
            },
        [51125528] = {
            ["Content"] = "小友慢逛~有事再来问我哈！",
            ["ContentJP"] = "はいよ、またいつでも声をかけてくれ！",
            ["DialogueId"] = 51125528,
            ["GUID"] = "7FFCC5F0",
            ["SpeakNpcId"] = 701039,
            },
        [51125601] = {
            ["Content"] = "这位客人您上上眼，小店卖的啊，都是在华胥游历必不可缺的尖货，样样好！尤其是这沉月香的香囊啊，想要得到咱们华胥的白龙神君的庇佑啊，必不可缺！",
            ["ContentJP"] = "こちらのお品をぜひご覧あれ、当店ご自慢の逸品ばかり！華胥での旅において欠かせない「旅の証」！とくにこの「沈月香」の香り袋――白龍様の加護をお求めなら、必携の一品ですぞ！",
            ["DialogueId"] = 51125601,
            ["GUID"] = "7FFCD1EA",
            ["NextOptions"] = {
                [1] = 51125602,
                [2] = 51125604,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125602] = {
            ["Content"] = "有人送过我了。",
            ["ContentJP"] = "それならもうもらった。",
            ["DialogueId"] = 51125602,
            ["GUID"] = "7FFCD214",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51125603,
            },
        [51125603] = {
            ["Content"] = "哦？客人是来华胥见朋友？难不成是哪位织星客将客人带来的？没事！除了香囊我这还有别的呢，要不您看看这把绢面的折扇？或者这柄金漆的雕花镜？",
            ["ContentJP"] = "おや、誰かとお会いになるご予定でしたか？もしや星織人のご友人で？それでしたらなおさら、どうぞどうぞ、香り袋のほかにも、絹地の扇子や金漆の手鏡などいかがです？目を惹く品、いろいろ取り揃えておりますよ。",
            ["DialogueId"] = 51125603,
            ["GUID"] = "7FFCD23E",
            ["SpeakNpcId"] = 701040,
            },
        [51125604] = {
            ["Content"] = "我没钱，你可以送我吗？",
            ["ContentJP"] = "お金ないから、タダでくれない？",
            ["DialogueId"] = 51125604,
            ["GUID"] = "7FFCD268",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51125605,
            },
        [51125605] = {
            ["Content"] = "哈哈哈，客人真会说笑，但其实并无不可，沉月香香囊在咱们华胥本就不是什么稀奇之物，客人不嫌弃的话，便从我这随便挑一个拿走吧！",
            ["ContentJP"] = "はは、ご冗談を。……ですがね、お客さん、沈月香の香り袋は手頃な品だ。もし気に入ったのがあれば、おひとつ持って行ってくださいな。",
            ["DialogueId"] = 51125605,
            ["GUID"] = "7FFCD292",
            ["NextDialogue"] = 51125606,
            ["SpeakNpcId"] = 701040,
            },
        [51125606] = {
            ["Content"] = "等客人在华胥发了财，可别忘了来我这再挑挑，选些纪念品带给亲朋好友啊！",
            ["ContentJP"] = "華胥で儲けた時には、ぜひまたお立ち寄りを。ご親戚やご友人への贈り物に、うってつけの品ばかりでございますよ！",
            ["DialogueId"] = 51125606,
            ["GUID"] = "7FFCD2BC",
            ["SpeakNpcId"] = 701040,
            },
        [51125607] = {
            ["Content"] = "专供异国友人的纪念品摊铺，来华胥之游人必不可错过！香囊折扇古玩珍宝，您想要的，应有尽有！",
            ["ContentJP"] = "うちは異国のお客様に大人気の土産屋です！華胥を旅するなら、一度は立ち寄るべき名所！香り袋に扇子、古美術に珍宝まで――お探しの品が、きっと見つかりますよ！",
            ["DialogueId"] = 51125607,
            ["GUID"] = "7FFCD2E6",
            ["NextDialogue"] = 51125608,
            ["SpeakNpcId"] = 701040,
            },
        [51125608] = {
            ["Content"] = "客人来啦，随便瞧随便看，有什么喜欢的您尽管说，价格好商量。",
            ["ContentJP"] = "さあさ、お気軽にお立ち寄りを！気に入ったものがあれば、遠慮なくお声かけください。おまけしちゃいますよ！",
            ["DialogueId"] = 51125608,
            ["GUID"] = "7FFCD310",
            ["NextOptions"] = {
                [1] = 51125609,
                [2] = 51125620,
                [3] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125609] = {
            ["Content"] = "有什么推荐的必备物品吗？除了香囊。",
            ["ContentJP"] = "香り袋以外に何かおすすめは？",
            ["DialogueId"] = 51125609,
            ["GUID"] = "7FFCD33A",
            ["NextDialogue"] = 51125610,
            },
        [51125610] = {
            ["Content"] = "有，自然是有的！首先便是这大风九章挂轴，上面把条目写得一清二楚。这样啊，您离开华胥回到故国，和朋友们讲起大风九章，就能有实物说明啦，不至于用手比划！",
            ["ContentJP"] = "そりゃございますとも！ たとえばこの「大風九章」の掛け軸などいかがです？華胥の大切な教えを絵と文字でまとめたもので、ご帰国後、ご友人への土産話の際にもお使いいただけますぞ！",
            ["DialogueId"] = 51125610,
            ["GUID"] = "7FFCD364",
            ["NextDialogue"] = 51125611,
            ["SpeakNpcId"] = 701040,
            },
        [51125611] = {
            ["Content"] = "客人再看看这华胥特有的首饰，咱们华胥上至老人下至小孩，都喜欢这种古色古香的款式，经典！",
            ["ContentJP"] = "それから、こちら華胥限定の装飾品です。年齢を問わず人気の品ですよ。この古風なデザインは誰にでも合うと思いますよ。",
            ["DialogueId"] = 51125611,
            ["GUID"] = "7FFCD38E",
            ["NextDialogue"] = 51125612,
            ["SpeakNpcId"] = 701040,
            },
        [51125612] = {
            ["Content"] = "您要是喜欢与众不同呢，也有这种以昆虫为主题的，更能凸显客人气质独特，品位不凡。",
            ["ContentJP"] = "ちょっと変わったものがお好きなら、この虫をモチーフにしたアクセサリーなんてどうです？個性派の方にぴったりで、粋な雰囲気が漂いますぞ。",
            ["DialogueId"] = 51125612,
            ["GUID"] = "7FFCD3B8",
            ["NextDialogue"] = 51125613,
            ["SpeakNpcId"] = 701040,
            },
        [51125613] = {
            ["Content"] = "对了对了，客人一定不能错过我们店里新到的香薰蜡烛，比普通蜡烛多了一份来自华胥的芳香，许多异国客人买过之后还想要呢！",
            ["ContentJP"] = "あ、そうそう、最近入荷したばかりの香りつき蝋燭もおすすめです。普通の蝋燭と違って、焚くだけで華胥の香りが部屋に満ちると評判でして、リピーターも多いんですよ。",
            ["DialogueId"] = 51125613,
            ["GUID"] = "7FFCD3E2",
            ["NextOptions"] = {
                [1] = 51125614,
                [2] = 51125618,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125614] = {
            ["Content"] = "这些我都不喜欢，有没有更实用的东西？",
            ["ContentJP"] = "どれもイマイチかも。もっと実用的なものはないの{性别:か|}？",
            ["DialogueId"] = 51125614,
            ["GUID"] = "7FFCD40C",
            ["NextDialogue"] = 51125615,
            },
        [51125615] = {
            ["Content"] = "客人呀~我就是个卖纪念品的小贩，纪念品这种东西，主打的就是一个没什么实际意义，买着好玩的存在呀。",
            ["ContentJP"] = "おやおや……困りましたね。記念品ってのは、そもそも実用性より面白味が主役ですし。",
            ["DialogueId"] = 51125615,
            ["GUID"] = "7FFCD436",
            ["NextDialogue"] = 51125616,
            ["SpeakNpcId"] = 701040,
            },
        [51125616] = {
            ["Content"] = "来咱们华胥的外国客人，要么是旅游要么是做生意，多少都想带点东西给家乡里没法亲自过来的人作为纪念，要是有用的华胥之物，他们也用不惯的。",
            ["ContentJP"] = "華胥を訪れる外国の方も、旅の記念や大切な人への手土産として選ばれるんです。役には立たずとも、心の中には残る品なんですよ。",
            ["DialogueId"] = 51125616,
            ["GUID"] = "7FFCD460",
            ["NextDialogue"] = 51125617,
            ["SpeakNpcId"] = 701040,
            },
        [51125617] = {
            ["Content"] = "再说了，要是真有大用的货物，早就会有商人把它当做紧俏货，卖得各国都是啦，又怎么会只有华胥才能买到呢。",
            ["ContentJP"] = "それに、本当に便利なものなら、すでに各国の商人が競って仕入れているはず。わざわざ華胥まで来なければ手に入らない、なんてことは、まずありませんって。",
            ["DialogueId"] = 51125617,
            ["GUID"] = "7FFCD48A",
            ["NextOptions"] = {
                [1] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125618] = {
            ["Content"] = "都想要，但我没钱，能不能赊账。",
            ["ContentJP"] = "全部ほしいけど、お金がない。ツケてもいい？",
            ["DialogueId"] = 51125618,
            ["GUID"] = "7FFCD4B4",
            ["NextDialogue"] = 51125619,
            },
        [51125619] = {
            ["Content"] = "客人这……我这是小本生意，客人别难为我啦，要是客人想找点活，我可以帮您引荐引荐，织星客们经常在码头招募搬货的工人，客人要不去问问？",
            ["ContentJP"] = "そ、それはちょっと……うちは、帳付けはできませんよ。けれど、もしお仕事を探しているなら、星織人たちが港で荷運びを募集してたりするんです。紹介くらいならできますよ！",
            ["DialogueId"] = 51125619,
            ["GUID"] = "7FFCD4DE",
            ["NextOptions"] = {
                [1] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125620] = {
            ["Content"] = "卖给外国人的货，不会在价格上坑我吧？",
            ["ContentJP"] = "わざと高値で売ったりしないよね？",
            ["DialogueId"] = 51125620,
            ["GUID"] = "7FFCD508",
            ["NextDialogue"] = 51125621,
            },
        [51125621] = {
            ["Content"] = "客人这话说的！我在这档口待了快有十年，远近闻名的好信用，货品都是尽量给客人最大的优惠。",
            ["ContentJP"] = "そんなことするわけないでしょう！開業から10年、うちは信用第一で営業してるんだから！できるだけお値打ちにしますんで、安心して見ていってくださいな。",
            ["DialogueId"] = 51125621,
            ["GUID"] = "7FFCD532",
            ["NextOptions"] = {
                [1] = 51125609,
                [2] = 51125622,
                },
            ["SpeakNpcId"] = 701040,
            },
        [51125622] = {
            ["Content"] = "没什么要说的，走了。",
            ["ContentJP"] = "もう帰る{性别:|ね}。",
            ["DialogueId"] = 51125622,
            ["GUID"] = "7FFCD55C",
            ["NextDialogue"] = 51125623,
            },
        [51125623] = {
            ["Content"] = "客人慢走，以后有空再来看看，定能找到您喜欢的东西！",
            ["ContentJP"] = "そりゃ残念。またいつでも来てくださいな。きっと好きなものが見つかりますぜ！",
            ["DialogueId"] = 51125623,
            ["GUID"] = "7FFCD586",
            ["SpeakNpcId"] = 701040,
            },
        [51125701] = {
            ["Content"] = "诸位有所不知啊，咱们浮星埠现在呢，只是织星客们货物往来的小小码头，平平无奇，但是在千年之前呢，这里可出过一位大人物。",
            ["ContentJP"] = "今でこそ星織人たちが荷をやり取りするだけの小さな港だが、昔はとんでもない人物がここから旅だったんじゃぞ。",
            ["DialogueId"] = 51125701,
            ["GUID"] = "7FFCE252",
            ["NextDialogue"] = 51125702,
            ["SpeakNpcId"] = 701041,
            },
        [51125702] = {
            ["Content"] = "哪位呢？说来大家也都听过名字，就是那大风九章的创立者之一，也是匠矩派的老祖宗——矩！",
            ["ContentJP"] = "あの「大風九章」を築き上げたお一人であり、匠矩派の始祖でもある。その名も、ノリ様じゃ！",
            ["DialogueId"] = 51125702,
            ["GUID"] = "7FFCE27C",
            ["NextOptions"] = {
                [1] = 51125703,
                [2] = 51125720,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125703] = {
            ["Content"] = "继续听下去。",
            ["ContentJP"] = "このまま聞く。",
            ["DialogueId"] = 51125703,
            ["GUID"] = "7FFCE2A6",
            ["NextDialogue"] = 51125704,
            },
        [51125704] = {
            ["Content"] = "南来北往的慢走一步，且听我说道说道咱们这浮星埠的千年历史——做生意讲究明明白白，对自己的过去啊，也得清清楚楚才好。",
            ["ContentJP"] = "ちょいと待たれよ、旅人さん。ここ浮星埠は千年の歴史を誇る。商いをする上で、過去を知るのは何よりも大切じゃ。",
            ["DialogueId"] = 51125704,
            ["GUID"] = "7FFCE2D0",
            ["NextDialogue"] = 51125705,
            ["SpeakNpcId"] = 701041,
            },
        [51125705] = {
            ["Content"] = "当年的华胥，没有大风九章的庇佑，秽兽四起，袭击无辜之人，为了活命，是不分老幼，都得想着法和那些凶恶的野兽去斗来斗去。",
            ["ContentJP"] = "あの頃の華胥には、「大風九章」なんて影も形もなかった。魔物はうろつき、人々は毎日を生き延びるのに必死でね。",
            ["DialogueId"] = 51125705,
            ["GUID"] = "7FFCE2FA",
            ["NextDialogue"] = 51125706,
            ["SpeakNpcId"] = 701041,
            },
        [51125706] = {
            ["Content"] = "有争斗就会有伤亡，那时，华胥人口数量极少，因为大多数出生的孩子都难在这乱世之中活下来，为了寻找到让华胥境内安宁的办法，有龙一族上下求索。",
            ["ContentJP"] = "子どもが無事に育つことさえ稀だった。それでも、なんとかして平和を取り戻そうと、龍の一族は知恵を絞り、方法を探していたんだ。",
            ["DialogueId"] = 51125706,
            ["GUID"] = "7FFCE324",
            ["NextDialogue"] = 51125707,
            ["SpeakNpcId"] = 701041,
            },
        [51125707] = {
            ["Content"] = "而我们的前辈矩呢，走遍了华胥，发现哪儿都是不得安生，于是他想着，不如出去看看，去看看人家是怎么做的，取其长处再充盈自身。",
            ["ContentJP"] = "そんな時、ノリさまは思った――「この国ではもう答えは見つからない。ならば、外に学べばいい」と。",
            ["DialogueId"] = 51125707,
            ["GUID"] = "7FFCE34E",
            ["NextOptions"] = {
                [1] = 51125708,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125708] = {
            ["Content"] = "继续听下去。",
            ["ContentJP"] = "このまま聞く。",
            ["DialogueId"] = 51125708,
            ["GUID"] = "7FFCE378",
            ["NextDialogue"] = 51125709,
            },
        [51125709] = {
            ["Content"] = "当年啊，还没现在这么厉害的船，也没有织星客的存在，想要出海，全凭运气，运气好便漂流到荒岛看鸟，运气不好，就只能葬身海底喂鱼喽。",
            ["ContentJP"] = "当時はまだ、今のような立派な船も、織星客もいなかった。海に出るなんて、まさに命がけ。運がよけりゃどこかの島に流れ着くが、悪けりゃ魚のエサさ。",
            ["DialogueId"] = 51125709,
            ["GUID"] = "7FFCE3A2",
            ["NextDialogue"] = 51125710,
            ["SpeakNpcId"] = 701041,
            },
        [51125710] = {
            ["Content"] = "但矩呢，抱定要为万民谋安宁的一颗赤心，自制了艘船，说是不连累别人，愣是一个人就从咱们这浮星埠下了海！",
            ["ContentJP"] = "けれどもノリ様は、「誰にも迷惑をかけたくない」と言って、自分で船を創り、一人でこの港から船を出したんじゃ。",
            ["DialogueId"] = 51125710,
            ["GUID"] = "7FFCE3CC",
            ["NextDialogue"] = 51125711,
            ["SpeakNpcId"] = 701041,
            },
        [51125711] = {
            ["Content"] = "好在，白龙神君眷顾，矩在风浪里去了那神秘的塔之国，但可惜的是，那边也不得安生，矩认为外民也无法给华胥带来希望，于是便带着同样想要安定的人回来了。",
            ["ContentJP"] = "白龍様がその旅路を見守ってくださったのかもしれんな。嵐の果て、あの不思議な「塔の国」にたどり着いたんじゃ。だがそこも、安らぎとは程遠い場所だった。「異国にも救いはない」そう悟ったノリ様は、同じ願いを抱く者たちとともに、再びこの浮星埠へ戻ってきた。",
            ["DialogueId"] = 51125711,
            ["GUID"] = "7FFCE3F6",
            ["NextDialogue"] = 51125712,
            ["SpeakNpcId"] = 701041,
            },
        [51125712] = {
            ["Content"] = "这都多少年过去了，大家都以为矩早就是个死人，结果啊非但没死，还又带了许许多多的活人回来了浮星埠。",
            ["ContentJP"] = "長い時が流れていた。誰もがもう、ノリ様は海の藻屑になったと信じていた。……だがね、そうじゃなかった。何十人もの生きた人間を連れて、彼は帰ってきたんじゃ！",
            ["DialogueId"] = 51125712,
            ["GUID"] = "7FFCE420",
            ["NextOptions"] = {
                [1] = 51125713,
                },
            ["SpeakNpcId"] = 701041,
            },
        [51125713] = {
            ["Content"] = "继续听下去。",
            ["ContentJP"] = "このまま聞く。",
            ["DialogueId"] = 51125713,
            ["GUID"] = "7FFCE44A",
            ["NextDialogue"] = 51125714,
            },
        [51125714] = {
            ["Content"] = "你们可能好奇，矩是如何做到如此准确的寻路，是有神灵庇佑还是靠的信念和直觉？",
            ["ContentJP"] = "驚くだろう？どうしてそんなことができたのかって？神の導き？信念？運？――いいや、違う！",
            ["DialogueId"] = 51125714,
            ["GUID"] = "7FFCE474",
            ["NextDialogue"] = 51125715,
            ["SpeakNpcId"] = 701041,
            },
        [51125715] = {
            ["Content"] = "都不是，老柳头啊也不卖关子了，现在织星者们出海时用的引路的工具不是叫千星板吗？矩也是一样，只是啊，他手里用的那个，就是第一个。",
            ["ContentJP"] = "「千星板・第一世代」を使ったんじゃ。今でこそ出航のたびに使われてるが、当時は誰も見たことすらなかった代物さ。\
 今どき出航でよく使われる「千星板」があるじゃろう？ノリ様はその初代版を使ったんじゃ。",
            ["DialogueId"] = 51125715,
            ["GUID"] = "7FFCE49E",
            ["NextDialogue"] = 51125716,
            ["SpeakNpcId"] = 701041,
            },
        [51125716] = {
            ["Content"] = "他用几块木板测绘星辰，记录航向，这才能在茫茫大海上自由来去，不受羁绊。",
            ["ContentJP"] = "星の動きを板に記し、進む方角を定めていく。その知恵が、ノリ様の旅を導いたんじゃ。",
            ["DialogueId"] = 51125716,
            ["GUID"] = "7FFCE4C8",
            ["NextDialogue"] = 51125717,
            ["SpeakNpcId"] = 701041,
            },
        [51125717] = {
            ["Content"] = "矩的成功出海与归来，让华胥的有龙们不再畏惧海洋，现在浮星埠的繁华和织星客们的昌盛，也是多亏了当年矩的先行。",
            ["ContentJP"] = "この偉業があってこそ、我らは海を恐れずに済むようになった。今の浮星埠のにぎわいも、織星客の活躍も、ぜんぶ、ノリ様のおかげなんじゃよ。",
            ["DialogueId"] = 51125717,
            ["GUID"] = "7FFCE4F2",
            ["NextDialogue"] = 51125718,
            ["SpeakNpcId"] = 701041,
            },
        [51125718] = {
            ["Content"] = "所以，矩和飏，都是咱们要时时牢记于心的开国贤君，没有他们，就没有今天的华胥，我们要时时刻刻记住他们的名字和事迹！懂了吗？",
            ["ContentJP"] = "だからね、若いの――ノリ様とヤン様の名は、忘れちゃいかん。あの二人がいなけりゃ、今の華胥はなかったんだから！",
            ["DialogueId"] = 51125718,
            ["GUID"] = "7FFCE51C",
            ["NextDialogue"] = 51125719,
            ["SpeakNpcId"] = 701041,
            },
        [51125719] = {
            ["Content"] = "（响起一阵叫好声。）",
            ["ContentJP"] = "その場に喝采が響いた。",
            ["DialogueId"] = 51125719,
            ["GUID"] = "7FFCE546",
            },
        [51125720] = {
            ["Content"] = "不听了。",
            ["ContentJP"] = "会話を終了する。",
            ["DialogueId"] = 51125720,
            ["GUID"] = "7FFCE570",
            ["NextDialogue"] = 51125721,
            },
        [51125721] = {
            ["Content"] = "（身后传来老柳头宣扬两位华胥开国贤君事迹的声音和喝茶群众的叫好声……）",
            ["ContentJP"] = "背後からは、リュウじいさんがふたたび華胥の二人の開祖――ノリとヤンの偉業を語る声と、それに茶をすすりながら相槌を打つ人々の喝采が聞こえてきた……",
            ["DialogueId"] = 51125721,
            ["GUID"] = "7FFCE59A",
            },
        [51125801] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentJP"] = "千星板、異常なしっと。そろそろメンテナンスの時期かしらね……",
            ["DialogueId"] = 51125801,
            ["GUID"] = "7FFCF2BA",
            ["NextDialogue"] = 51125802,
            ["SpeakNpcId"] = 701042,
            },
        [51125802] = {
            ["Content"] = "这千星板上了船还没个三年，怎么就这么快就要去保养了呢，这次不知道他们还记不记得提前预约机枢派的师傅……先看看刻度有没有被磨坏吧！",
            ["ContentJP"] = "この千星板、まだ積んで三年経ってないのに、もうメンテナンスなんて。まったく……予備検査を忘れてるんじゃないかしら。機枢派の師匠にちゃんと予約入れたのかしら。まずは目盛りの摩耗からチェックっと！",
            ["DialogueId"] = 51125802,
            ["GUID"] = "7FFCF2E4",
            ["NextDialogue"] = 51125803,
            ["SpeakNpcId"] = 701042,
            },
        [51125803] = {
            ["Content"] = "呀！吓了我一跳，你是异国人吗？在咱们船上做什么？",
            ["ContentJP"] = "わっ！びっくりした……あなた、ここの人じゃないわよね？どうして船に？",
            ["DialogueId"] = 51125803,
            ["GUID"] = "7FFCF30E",
            ["NextOptions"] = {
                [1] = 51125804,
                [2] = 51125807,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125804] = {
            ["Content"] = "好奇你在做什么。",
            ["ContentJP"] = "何をしてるか気になって。",
            ["DialogueId"] = 51125804,
            ["GUID"] = "7FFCF338",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51125805,
            },
        [51125805] = {
            ["Content"] = "我？我在查看这船上千星板的情况呀，我是这艘船上配的工匠，专门负责日常维护这千星板的运作，要是没有这千星板，这船只可就没法出航啦。",
            ["ContentJP"] = "私？この船に設置された千星板の点検をしてるの。私はここの職人だからね。毎日稼働チェックをするのも仕事なの。この板がないと、船は航行できないもの。",
            ["DialogueId"] = 51125805,
            ["GUID"] = "7FFCF362",
            ["NextDialogue"] = 51125806,
            ["SpeakNpcId"] = 701042,
            },
        [51125806] = {
            ["Content"] = "你有事的话，以后再来找我吧，现在我还要仔细检查一下过热情况……",
            ["ContentJP"] = "今は過熱の状態を見てるところだから、何か話があるなら、後でにしてもらえる？",
            ["DialogueId"] = 51125806,
            ["GUID"] = "7FFCF38C",
            ["SpeakNpcId"] = 701042,
            },
        [51125807] = {
            ["Content"] = "闲逛到这里了。",
            ["ContentJP"] = "なんとなく暇だったから。",
            ["DialogueId"] = 51125807,
            ["GUID"] = "7FFCF3B6",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51125808,
            },
        [51125808] = {
            ["Content"] = "哦哦是吗？可我在检查千星板的情况呢，要是出了问题，这船就没法出航啦，你有什么事情的话以后再来找我聊吧。",
            ["ContentJP"] = "ふーん、暇なのね。でも今は千星板の動作チェックの最中なの。これに不具合が出たら、この船、出航できなくなっちゃうから。用事があるなら後で来てくれる？",
            ["DialogueId"] = 51125808,
            ["GUID"] = "7FFCF3E0",
            ["SpeakNpcId"] = 701042,
            },
        [51125809] = {
            ["Content"] = "千星板运作情况一切正常，算算时间，马上要到下一次保养的日子了……",
            ["ContentJP"] = "千星板、異常なしっと。そろそろ保養の時期かしらね……",
            ["DialogueId"] = 51125809,
            ["GUID"] = "7FFCF40A",
            ["NextDialogue"] = 51125810,
            ["SpeakNpcId"] = 701042,
            },
        [51125810] = {
            ["Content"] = "这个刻度误差……我手动增加五次校准运算后结果也大差不差……那是不是可以申请延期保养时间了。",
            ["ContentJP"] = "……ん？この刻度、微妙にズレてる？手動で5回計算調整しても誤差範囲内か。今回は、保養申請を少し先延ばししても大丈夫かも。",
            ["DialogueId"] = 51125810,
            ["GUID"] = "7FFCF434",
            ["NextDialogue"] = 51125811,
            ["SpeakNpcId"] = 701042,
            },
        [51125811] = {
            ["Content"] = "呀，又是你，异国人，你又逛到我这啦。",
            ["ContentJP"] = "あら、また来たの？ほんと、暇なのね。",
            ["DialogueId"] = 51125811,
            ["GUID"] = "7FFCF45E",
            ["NextOptions"] = {
                [1] = 51125812,
                [2] = 51125815,
                [3] = 51125825,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125812] = {
            ["Content"] = "师傅你是做什么的？",
            ["ContentJP"] = "何してるの？",
            ["DialogueId"] = 51125812,
            ["GUID"] = "7FFCF488",
            ["NextDialogue"] = 51125813,
            },
        [51125813] = {
            ["Content"] = "我吗？自然是这船上配的工匠啦，我的工作就是负责维护千星板的运作情况，保证它一切正常，不会临时出意外，不然会影响到下一次出航。",
            ["ContentJP"] = "私はこの船の職人なんだから、当然、千星板のメンテナンスと動作確認をしてるのよ。いつでも船が出航できるように整備しないとね。故障や異常があったら、次の航海に影響するでしょ？",
            ["DialogueId"] = 51125813,
            ["GUID"] = "7FFCF4B2",
            ["NextDialogue"] = 51125814,
            ["SpeakNpcId"] = 701042,
            },
        [51125814] = {
            ["Content"] = "这些信息都要记录下来，找天禄司申请通文时用得到呢。",
            ["ContentJP"] = "点検記録は全部つけておかないと、<Default note=\"text:てんろくし\">天禄司</>に申請通す時に困るからね。",
            ["DialogueId"] = 51125814,
            ["GUID"] = "7FFCF4DC",
            ["NextOptions"] = {
                [1] = 51125815,
                [2] = 51125825,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125815] = {
            ["Content"] = "千星板是什么？",
            ["ContentJP"] = "千星板ってなに？",
            ["DialogueId"] = 51125815,
            ["GUID"] = "7FFCF506",
            ["NextDialogue"] = 51125816,
            },
        [51125816] = {
            ["Content"] = "千星板可是咱们织星客们赖以生存的传家宝呢！在一望无际的大海上，只有它能观测天上的星星的方位，给船只导航指路，怎么都不会跑偏。",
            ["ContentJP"] = "千星板はね、私たち星織人にとって命綱みたいなもの。あの広い海で、星の位置から航路を読み取ってくれる装置なの。どんなに海が荒れても、あれさえあれば道を見失わないんだから。",
            ["DialogueId"] = 51125816,
            ["GUID"] = "7FFCF530",
            ["NextDialogue"] = 51125817,
            ["SpeakNpcId"] = 701042,
            },
        [51125817] = {
            ["Content"] = "华胥四周的海域紊乱，没有千星板的正确指引，织星客们很容易在乱流之间迷路，所以啊，我们每回远航之前，都需要仔细检查千星板的情况。",
            ["ContentJP"] = "このあたりの海は流れも風も複雑だから、ちょっとでも狂うとすぐ迷子になるの。だから出航前には、千星板の状態をちゃんと見ておかないとダメなんだよ。",
            ["DialogueId"] = 51125817,
            ["GUID"] = "7FFCF55A",
            ["NextOptions"] = {
                [1] = 51125818,
                [2] = 51125822,
                },
            ["SpeakNpcId"] = 701042,
            },
        [51125818] = {
            ["Content"] = "你说的保养是什么意思？",
            ["ContentJP"] = "保養ってなんのこと？",
            ["DialogueId"] = 51125818,
            ["GUID"] = "7FFCF584",
            ["NextDialogue"] = 51125819,
            },
        [51125819] = {
            ["Content"] = "保养吗？其实就是让机枢派的老师傅们帮咱们看看千星板是否出现一些零件松动之类的情况，虽然大多数情况都没什么问题，但是在海上航行，难免会有浪涛大时磕碰。",
            ["ContentJP"] = "保養っていうのは、<Default note=\"text:きすうは\">機枢派</>の人たちにお願いして、千星板のパーツが緩んでないか、異常がないかを見てもらうことよ。大体は大丈夫だけど、海って予想以上に揺れるから、念には念を、ってね。",
            ["DialogueId"] = 51125819,
            ["GUID"] = "7FFCF5AE",
            ["NextDialogue"] = 51125820,
            ["SpeakNpcId"] = 701042,
            },
        [51125820] = {
            ["Content"] = "我们这种普通工匠能看出问题但不会修，只有去机枢派找有专门检测器材的老师傅们帮着看看，但是频率不需要太高，大概四五年一次就好。",
            ["ContentJP"] = "私たち技工でも異常はある程度わかるけど、細かい修理は専門の職人じゃないと無理なの。でもそうそう頻繁にお願いするものでもなくて、4〜5年に一度くらいってとこかな。",
            ["DialogueId"] = 51125820,
            ["GUID"] = "7FFCF5D8",
            ["NextDialogue"] = 51125821,
            ["SpeakNpcId"] = 701042,
            },
        [51125821] = {
            ["Content"] = "不过即使是过去找他们，也需要给到日常测量的一些数据，方便给出更好的判断。",
            ["ContentJP"] = "点検お願いするにしても、まずは私たちが日々の稼働データをちゃんと取っておかないと。それがあると、診断の精度も上がるからね。",
            ["DialogueId"] = 51125821,
            ["GUID"] = "7FFCF602",
            ["SpeakNpcId"] = 701042,
            },
        [51125822] = {
            ["Content"] = "千星板在哪，我怎么没看到？",
            ["ContentJP"] = "千星板ってどこにあるの？見えないけど……",
            ["DialogueId"] = 51125822,
            ["GUID"] = "7FFCF62C",
            ["NextDialogue"] = 51125823,
            },
        [51125823] = {
            ["Content"] = "哈哈，笨家伙，就在咱们脚下呀，咱们这种用来出海的大船，千星板都是装在船舱里的，只有最大的那块板会倒置朝向天空，方便观测星空。",
            ["ContentJP"] = "あっはっは、そりゃそうだよ。今あなたが立ってる足下にあるんだから。これくらいの大型船は、千星板は船底の観測室に設置されてるの。天井向きに取り付けられて、そこから星を観測してるのよ。",
            ["DialogueId"] = 51125823,
            ["GUID"] = "7FFCF656",
            ["NextDialogue"] = 51125824,
            ["SpeakNpcId"] = 701042,
            },
        [51125824] = {
            ["Content"] = "用你们外国人能听懂的话来形容，大概有些像那种大型的吊灯，我们在海上的时候，每时每刻都需要有人在船舱里值班记录千星板转动的幅度，不然就容易偏航呢。",
            ["ContentJP"] = "あなたの言葉でいうなら……そうね、でっかいシャンデリアってとこかな？海の上では毎分毎秒、誰かが板の回転角度を記録してて、それで船の方向を微調整してるの。少しでもズレると、すぐに航路が外れちゃうから。",
            ["DialogueId"] = 51125824,
            ["GUID"] = "7FFCF680",
            ["SpeakNpcId"] = 701042,
            },
        [51125825] = {
            ["Content"] = "没什么要问的。",
            ["ContentJP"] = "特に聞きたいことはない",
            ["DialogueId"] = 51125825,
            ["GUID"] = "7FFCF6AA",
            ["NextDialogue"] = 51125826,
            },
        [51125826] = {
            ["Content"] = "有事再来找我吧，我要测量新的数据啦。",
            ["ContentJP"] = "そっか。じゃあまた何かあったら来て。私はこれから、新しい測定始めなきゃだから！",
            ["DialogueId"] = 51125826,
            ["GUID"] = "7FFCF6D4",
            ["SpeakNpcId"] = 701042,
            },
        [51125901] = {
            ["Content"] = "白女士，这个什么什么身，是什么意思，我听不懂。",
            ["ContentJP"] = "ええと……身を……？",
            ["DialogueId"] = 51125901,
            ["GUID"] = "7FFD0322",
            ["NextDialogue"] = 51125902,
            ["SpeakNpcId"] = 701043,
            },
        [51125902] = {
            ["Content"] = "戕，这个字念戕，就是和你们异国人经常用的枪字一个读音。",
            ["ContentJP"] = "身を戕い、です。あなたたちの言葉でいうならば、撃つとか攻撃、でしょうかね。",
            ["DialogueId"] = 51125902,
            ["GUID"] = "7FFD034C",
            ["NextDialogue"] = 51125903,
            ["SpeakNpcId"] = 701044,
            },
        [51125903] = {
            ["Content"] = "哦哦！枪！枪身就是，用枪打对方的身子，对不对？",
            ["ContentJP"] = "ああっ、撃つ！相手を銃で撃つって意味デスね？",
            ["DialogueId"] = 51125903,
            ["GUID"] = "7FFD0376",
            ["NextDialogue"] = 51125904,
            ["SpeakNpcId"] = 701043,
            },
        [51125904] = {
            ["Content"] = "这……诶，你就这么理解吧，也没什么问题，总之就是，在我们华胥，不能出现伤人之事，所以你带来的枪我们就先没收了，等你离开华胥之时再还给你。",
            ["ContentJP"] = "……まあ、そういう解釈でも構いません。とにかく、ここ華胥では、人を傷つける行為はご法度。ですので、あなたが持ち込んだ銃器は一時お預かりします。ご出国の際に、返却いたしますのでご安心を。",
            ["DialogueId"] = 51125904,
            ["GUID"] = "7FFD03A0",
            ["NextDialogue"] = 51125905,
            ["SpeakNpcId"] = 701044,
            },
        [51125905] = {
            ["Content"] = "可以可以，我来做生意，听本地的规矩，大风什么的，还有别的吗？",
            ["ContentJP"] = "オーケーオーケー、ボクはビジネスで来たんだから。ローカルルール、尊重するヨ！その「大風ナントカ」、他にもルールある？",
            ["DialogueId"] = 51125905,
            ["GUID"] = "7FFD03CA",
            ["NextDialogue"] = 51125906,
            ["SpeakNpcId"] = 701043,
            },
        [51125906] = {
            ["Content"] = "你既然是来做生意的，那这第二条：毁约背盟，不可为也。你可得谨记于心。",
            ["ContentJP"] = "もちろん。第二条「誓いを破り、盟を背くこと、為すべからず」です。商人として、しっかり心に刻んでくださいね。",
            ["DialogueId"] = 51125906,
            ["GUID"] = "7FFD03F4",
            ["NextDialogue"] = 51125907,
            ["SpeakNpcId"] = 701044,
            },
        [51125907] = {
            ["Content"] = "毁约，听得懂，背萌是什么意思？背上萌萌的吗？",
            ["ContentJP"] = "えーと、契約はわかる。でも「モエモエを背く」ってなに？なんかカワイイね。",
            ["DialogueId"] = 51125907,
            ["GUID"] = "7FFD041E",
            ["NextDialogue"] = 51125908,
            ["SpeakNpcId"] = 701043,
            },
        [51125908] = {
            ["Content"] = "不是那个萌……是盟约的盟，意思就是，你如果和咱们华胥人做生意，在谈妥价格之后，一定要在白龙神君的见证下立契，不然我们是不敢信你的。",
            ["ContentJP"] = "……「萌え」ではなく「盟約」の盟です。つまり、もしあなたが華胥の者と取引をする場合――金額を決めたあとは、白龍様の御前で、正式な契約を結んでもらいます。それが我々の流儀です。",
            ["DialogueId"] = 51125908,
            ["GUID"] = "7FFD0448",
            ["NextDialogue"] = 51125909,
            ["SpeakNpcId"] = 701044,
            },
        [51125909] = {
            ["Content"] = "哦哦，我明白了，你们要写合同，我们那边也写的，没问题没问题！",
            ["ContentJP"] = "なるほどネ！つまり契約書ダネ！ウチの国でも似たようなことするヨ、オーケーオーケー！",
            ["DialogueId"] = 51125909,
            ["GUID"] = "7FFD0472",
            ["NextDialogue"] = 51125910,
            ["SpeakNpcId"] = 701043,
            },
        [51125910] = {
            ["Content"] = "不不不，不一样，我们这是契约，是在白龙神君的见证下完成的，我们写的合同都是用沉月香香灰掺进墨里写，立契的时候便有了神君亲鉴。",
            ["ContentJP"] = "いえ、華胥の契約は少し異なります。契約書は「沈月香」の香灰を混ぜた墨で書き、契約を結んだその時より白龍様のご加護が宿るのです。",
            ["DialogueId"] = 51125910,
            ["GUID"] = "7FFD049C",
            ["NextDialogue"] = 51125911,
            ["SpeakNpcId"] = 701044,
            },
        [51125911] = {
            ["Content"] = "如若一方背誓，可是会被狴犴大人追缉的！",
            ["ContentJP"] = "そして、もしその誓いに背いたなら――狴犴様によって処罰が下されます。",
            ["DialogueId"] = 51125911,
            ["GUID"] = "7FFD04C6",
            ["NextDialogue"] = 51125912,
            ["SpeakNpcId"] = 701044,
            },
        [51125912] = {
            ["Content"] = "狴犴！华胥大狗，这个我知道的！",
            ["ContentJP"] = "ビーアン！知ってるヨ！「華胥のイヌ」！有名ネ！",
            ["DialogueId"] = 51125912,
            ["GUID"] = "7FFD04F0",
            ["NextDialogue"] = 51125913,
            ["SpeakNpcId"] = 701043,
            },
        [51125913] = {
            ["Content"] = "你这家伙，好生无礼！不可以这么称呼狴犴大人！",
            ["ContentJP"] = "なんと……！あなた、無礼ですよ！狴犴様に向かって、そんな呼び方をしてはいけません！",
            ["DialogueId"] = 51125913,
            ["GUID"] = "7FFD051A",
            ["SpeakNpcId"] = 701044,
            },
        [51126001] = {
            ["Content"] = "妈妈说的都是骗我的，什么叫我大了就可以长出角，前年说去年长，去年说今年长。结果还是什么都没有……",
            ["ContentJP"] = "ママの言ってたこと、やっぱりウソだったんだ……「大きくなれば生えてくる」って毎年言ってたのに、結局、何もないじゃん……！",
            ["DialogueId"] = 51126001,
            ["GUID"] = "7FFD138A",
            ["NextDialogue"] = 51126002,
            ["SpeakNpcId"] = 701045,
            },
        [51126002] = {
            ["Content"] = "难道我根本长不出角吗？不要啊，我不想当抟土氏，我想当光荣的有龙氏。",
            ["ContentJP"] = "もしかして、あたし……一生、角が生えないの！？\
 やだよ、土の民なんてなりたくないっ！あたし、龍の民になって、かっこいい龍神様の仲間になりたい！",
            ["DialogueId"] = 51126002,
            ["GUID"] = "7FFD13B4",
            ["NextOptions"] = {
                [1] = 51126003,
                [2] = 51126005,
                },
            ["SpeakNpcId"] = 701045,
            },
        [51126003] = {
            ["Content"] = "当抟土氏不好吗？",
            ["ContentJP"] = "土の民じゃ嫌なの？",
            ["DialogueId"] = 51126003,
            ["GUID"] = "7FFD13DE",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51126004,
            },
        [51126004] = {
