        [51140038] = {
            ["Content"] = "是有什么心事吗？",
            ["ContentJP"] = "なにか……悩み事でも？",
            ["DialogueId"] = 51140038,
            ["GUID"] = "8006127C",
            ["ImprPlusId"] = 1209,
            },
        [51140039] = {
            ["Content"] = "（等她发现自己。）",
            ["ContentJP"] = "（彼女が自分に気付くのを待つ。）",
            ["DialogueId"] = 51140039,
            ["GUID"] = "800612A6",
            ["ImprPlusId"] = 1207,
            },
        [51140040] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "唔，{nickname}，是你……怎么得空来了枯荣阁，温习时想起一些往事，不免失神，让你见笑了。",
            ["ContentJP"] = "あら……{nickname}さんでございましたか。よくぞおいでくださいました。つい、温習の折に昔を思い出し、心が遠くへ彷徨っておりました。お恥ずかしいところをお見せしましたね。",
            ["DialogueId"] = 51140040,
            ["GUID"] = "800612D0",
            ["LookAt"] = {
                [1] = "701075:n(100001)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_End",
                },
            ["TurnTo"] = {
                [1] = "701075:n(100001)",
                },
            },
        [51140041] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "唔，{nickname}，是你……怎么得空来了枯荣阁，温书入迷一时失神，居然没注意到你进来。",
            ["ContentJP"] = "あら……{nickname}さん。<Default note=\"text:こえいかく\">枯栄閣</>までいらっしゃるなんて……いかがなさいました？私としたことが、書に没頭しすぎて気づきもせず、失礼いたしました。",
            ["DialogueId"] = 51140041,
            ["GUID"] = "800612FA",
            ["LookAt"] = {
                [1] = "701075:n(100001)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_End",
                },
            ["TurnTo"] = {
                [1] = "701075:n(100001)",
                },
            },
        [51140042] = {
            ["Camera"] = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
            ["Content"] = "我都要把这里的诊籍都翻遍了，不是发烧感冒就是胃痛腹泻，怎么也和尾生说的那种情况对不上呀。",
            ["ContentJP"] = "はぁ〜もう、ここにある診断書ほとんど見たけど……熱とか腹痛とか、そういうばっかりで、オショウの言ってた症状と合う人なんて全然いないよ〜",
            ["DialogueId"] = 51140042,
            ["GUID"] = "80061324",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Alright_Start",
                },
            },
        [51140043] = {
            ["Camera"] = "147.988281,-372.753906,263.493164,0.000021,-23.151232,113.072533,76.142418,493.532471,false,Manual,3.0",
            ["Content"] = "扶疏扶疏，我们这次来是有一件奇怪的事情要问你呢！",
            ["ContentJP"] = "フーシュ、今日はちょっとヘンな出来事があってたの！",
            ["DialogueId"] = 51140043,
            ["FacialId"] = {
                [1] = "200002:Happy01",
                },
            ["GUID"] = "8006134E",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["TurnTo"] = {
                [1] = "100001:n(701075)",
                [2] = "701075:n(200002)",
                },
            },
        [51140044] = {
            ["Camera"] = "-74.871094,-49.457031,176.993164,0.000086,-14.999942,-17.730551,35.000015,130.112747,false,Manual,7.0",
            ["Content"] = "是身体不适还是另有心疾，能帮到你的地方，扶疏定然鼎力相助。",
            ["ContentJP"] = "お体にご不調でも？あるいは、心病でも抱えておられるのか……いずれにせよ、私にできることがあれば、力の及ぶかぎりお助けいたしましょう。",
            ["DialogueId"] = 51140044,
            ["FacialId"] = {
                [1] = "701075:Smile01",
                },
            ["GUID"] = "80061378",
            ["SpeakNpcId"] = 701075,
            },
        [51140045] = {
            ["Content"] = "（你向扶疏讲述了一位无由生在寻找生病妻子的事。）",
            ["ContentJP"] = "あなたは、あるムユウセイが病に伏す妻を探しているという話をフーシュに伝えた。",
            ["DialogueId"] = 51140045,
            ["GUID"] = "800613A2",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            ["TurnTo"] = {
                [1] = "701075:n(100001)",
                },
            },
        [51140046] = {
            ["Camera"] = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
            ["Content"] = "大抵是家姐生前收治过的病人。据记载，烟津渡上次洪灾致人溺亡已是九十余年前……",
            ["ContentJP"] = "恐らくは、生前に姉が診ていた方でございましょう。記録によれば、<Default note=\"text:えんしんと\">煙津渡</>で洪水により人が亡くなったのは──もう九十余年も昔のこと……",
            ["DialogueId"] = 51140046,
            ["GUID"] = "800613CC",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain01_Start",
                [2] = "200002:Excited01_End",
                },
            },
        [51140047] = {
            ["Camera"] = "30.617188,116.332031,137.268555,0.000109,-3.549711,-71.720947,19.814159,203.327576,false,Manual,5.20548",
            ["Content"] = "那时家姐年纪尚轻，尚未自立门户，还在枯荣阁坐诊。",
            ["ContentJP"] = "当時、姉はまだ若く、自らの医館も持たず、<Default note=\"text:こえいかく\">枯栄閣</>で診療をしていた時分でございました。",
            ["DialogueId"] = 51140047,
            ["GUID"] = "800613F6",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain01_End",
                },
            },
        [51140048] = {
            ["Camera"] = "171.115234,-119.117188,100.751953,0.000108,-4.999999,154.070587,35.000008,300.780701,false,Manual,5.20548",
            ["Content"] = "那个尾生竟然已经死了九十多年了吗！",
            ["ContentJP"] = "ってことは……あのオショウって人、もう九十年以上も前に亡くなってたの！？",
            ["DialogueId"] = 51140048,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "80061420",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            },
        [51140049] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "没错，他的妻子如今还活着的希望已是渺茫。",
            ["ContentJP"] = "左様でございます。お連れ合いのご存命は、もはや望み薄かと……",
            ["DialogueId"] = 51140049,
            ["FacialId"] = {
                [1] = "701075:Think01",
                },
            ["GUID"] = "8006144A",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_Start",
                },
            },
        [51140050] = {
            ["Camera"] = "-170.042969,583.894531,146.733398,0.000065,-3.551971,-72.129524,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "但如此痴情之人，帮他寻得当年妻子下落，权当圆他一个念想，让他得以了却执念，回归往生也好。",
            ["ContentJP"] = "されど、これほど一途な想いを抱き続ける方にございますれば──たとえ姿の在り処が知れたとて、いま一度心を鎮め、想いを遂げてから旅立てるのではございましょうか。",
            ["DialogueId"] = 51140050,
            ["GUID"] = "80061474",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51140051] = {
            ["Camera"] = "-113.632812,-83.152344,198.851562,0.00007,-17.949545,-0.526916,35.000011,645.22876,false,DoNotOverride,7.0",
            ["Content"] = "家姐历年行医都有诊籍留档，{nickname}，我随你去阁中找找。",
            ["ContentJP"] = "姉が診た患者の記録は、年代を問わず診断書として残されております。{nickname}さん、ご一緒に閲覧室へ参りましょう。",
            ["DialogueId"] = 51140051,
            ["FacialId"] = {
                [1] = "701075:None",
                },
            ["GUID"] = "8006149E",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_End",
                },
            },
        [51140052] = {
            ["Camera"] = "95.519531,110.679688,109.566406,0.000037,0.0,-126.112823,11.880002,248.943176,false,Manual,2.8",
            ["Content"] = "找到诊籍了吗？",
            ["ContentJP"] = "診断書は見つかりましたか？",
            ["DialogueId"] = 51140052,
