                },
            },
        [51140053] = {
            ["Camera"] = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
            ["Content"] = "没有，似乎没有对得上的，只有这一篇有些奇怪。",
            ["ContentJP"] = "いや、どうも該当者がいなくて……ただ、一つだけ少し気になるものがある。",
            ["DialogueId"] = 51140053,
            ["GUID"] = "800614F2",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            },
        [51140054] = {
            ["Content"] = "（你将诊籍递给扶疏，她仔细看了一会儿。）",
            ["ContentJP"] = "あなたはその診断書をフーシュに差し出す。彼女は静かに目を通した。",
            ["DialogueId"] = 51140054,
            ["GUID"] = "8006151C",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 0,
            },
        [51140055] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "咦……这里面有个人……我曾在姐姐的日记里见过……",
            ["ContentJP"] = "あ……この方……姉が日記に記していた人物のような……",
            ["DialogueId"] = 51140055,
            ["GUID"] = "80061546",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Think_Start",
                },
            },
        [51140056] = {
            ["Camera"] = "120.662109,32.841797,142.3125,0.000078,-19.999907,-159.908264,22.322252,236.840927,false,Manual,7.0",
            ["Content"] = "日记？你姐姐还写过日记呀？",
            ["ContentJP"] = "日記？フーシュのお姉さん、そんなの書いてたの？",
            ["DialogueId"] = 51140056,
            ["GUID"] = "80061570",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "701075:n(200002)",
                },
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_Start",
                [2] = "701075:Think_End",
                },
            },
        [51140057] = {
            ["Camera"] = "-93.105469,39.958984,123.023438,0.000084,6.0,-18.908363,35.000008,178.587616,false,Manual,7.0",
            ["Content"] = "嗯，姐姐怕我醒了后她不在，我对她不与我重叠的生活毫无了解，便将自己的经历以日记形式记录了下来。",
            ["ContentJP"] = "ええ。私が眠りについていた間の出来事を、目覚めたときに少しでも分かるようにと……姉は、自分の日々を日記に記していたのです。",
            ["DialogueId"] = 51140057,
            ["GUID"] = "8006159A",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "701075:n(200002)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain02_Start",
                [2] = "200002:Talk01_End",
                },
            },
        [51140058] = {
            ["Camera"] = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
            ["Content"] = "……不好意思，又提到你的伤心事了。",
            ["ContentJP"] = "……ごめん。また触れてほしくないことを思い出させて。",
            ["DialogueId"] = 51140058,
            ["GUID"] = "800615C4",
            ["LookAt"] = {
                [1] = "701075:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                [2] = "701075:Explain02_End",
                },
            },
        [51140059] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "并无感伤，姐姐想必也是不愿看到我伤怀才如此行事。",
            ["ContentJP"] = "お気になさらず。姉も、私が悲しむことなど望まぬでしょうから。",
            ["DialogueId"] = 51140059,
            ["GUID"] = "800615EE",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Disagree",
                },
            },
        [51140060] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "姐姐曾在年轻时的日记里提过一名患者，其妻在大疫中不幸殒命，自此患上心病，终日幻想其妻尚存于世，与那个不存在的人对话。",
            ["ContentJP"] = "姉の若き日の記録に、一人の患者がありました。その妻は疫病で亡くなり、以来その人は心を患ってしまったとか。妻はまだ生きていると信じ続け、毎日その見えぬ妻と語り合っていたと……",
            ["DialogueId"] = 51140060,
            ["GUID"] = "80061618",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk03_Start",
                },
            },
        [51140061] = {
            ["Camera"] = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
            ["Content"] = "姐姐写道，这让她照见了自己的影子，如同姐姐与沉睡中的我对话一样，有趣却又愚痴。",
            ["ContentJP"] = "姉はその様子を見て、自分と眠る私の関係をどこか重ねたのかもしれません。愚かで、でもどこか愛おしいものだと、そんなふうに書いておりました。",
            ["DialogueId"] = 51140061,
            ["GUID"] = "80061642",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk03ToThink_Start",
                },
            },
        [51140062] = {
            ["Content"] = "那位患者拒绝服药，姐姐只得想了个法子，借口要为他的妻子诊病，以试药为由，回回让他带走两副汤药，自己先吃一副。",
            ["ContentJP"] = "その患者は薬を拒み続けたため……家姉は一計を案じ、妻のための薬を作ると説明し、そのたびに「まずあなたが試してみてください」と、一服を彼に渡し、残りを「妻へ」と持ち帰らせたそうです。",
            ["DialogueId"] = 51140062,
            ["GUID"] = "8006166C",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "200002:n(200002)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk03ToThink_End",
                },
            },
        }
  end },
