        [51140064] = {
            ["Camera"] = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
            ["Content"] = "…………！原来如此，尾生的妻子，我们已经找到了。她就是：",
            ["ContentJP"] = "…………！そうか……オショウの妻は……",
            ["DialogueId"] = 51140064,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "800616C0",
            ["LookAt"] = {
                [1] = "100001:n(701075)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Give",
                [2] = "200002:Shock03_End",
                },
            },
        [51140065] = {
            ["Content"] = "刘姓女子",
            ["ContentJP"] = "リュさんって女性だ",
            ["DialogueId"] = 51140065,
            ["GUID"] = "800616EA",
            ["ImprPlusId"] = 1211,
            },
        [51140066] = {
            ["Content"] = "陈姓女子",
            ["ContentJP"] = "チェンさんって女性だ",
            ["DialogueId"] = 51140066,
            ["GUID"] = "80061714",
            ["ImprPlusId"] = 1211,
            },
        [51140067] = {
            ["Content"] = "柳姓男子",
            ["ContentJP"] = "リョウさんって男性だ",
            ["DialogueId"] = 51140067,
            ["GUID"] = "8006173E",
            ["ImprPlusId"] = 1211,
            },
        [51140068] = {
            ["Content"] = "早已不存于世",
            ["ContentJP"] = "もうこの世にいない",
            ["DialogueId"] = 51140068,
            ["GUID"] = "80061768",
            ["ImprPlusId"] = 1208,
            },
        [51140069] = {
            ["Camera"] = "-130.283203,752.826172,160.511719,0.000086,2.696961,101.435776,11.88,100000.0,false,Manual,2.8",
            ["Content"] = "想来，那名真正的患者，应是诊籍里的柳姓男子，也就是<H>柳尾生</>吧？",
            ["ContentJP"] = "うん……患者は<H>リョウオショウ</>の方だったんだよ。",
            ["DialogueId"] = 51140069,
            ["GUID"] = "80061792",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk03ToTalkL_Start",
                },
            },
        [51140070] = {
            ["Camera"] = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
            ["Content"] = "拜托你们寻找妻子的那位无由生名叫尾生，应该就是这位柳姓病人死后幻化而成。",
            ["ContentJP"] = "妻の捜索を頼んできたムユウセイの名もオショウだった。つまり……この患者が死したのち、ムユウセイとなったということでしょうか。",
            ["DialogueId"] = 51140070,
            ["GUID"] = "800617BC",
            ["SpeakNpcId"] = 701075,
            },
        [51140071] = {
            ["Camera"] = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
            ["Content"] = "扶疏，你在说什么呀……我都有点糊涂了……",
            ["ContentJP"] = "えっ……えっ……つまりどういう……？",
            ["DialogueId"] = 51140071,
            ["GUID"] = "800617E6",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Disagree",
                [2] = "701075:Talk03ToTalkL_End",
                },
            },
        [51140072] = {
            ["Camera"] = "-86.828125,129.613281,73.053711,0.000108,9.999997,-87.957306,28.133715,234.328125,false,Manual,1.855292",
            ["Content"] = "……我明白了！你姐姐救治的那个病人，不是尾生的妻子，而是尾生自己！他的妻子早就过世了，而他得了心病，一直以为自己的妻子还在身边！",
            ["ContentJP"] = "わかった……！フーシュのお姉さんが診ていた患者は、オショウの妻じゃなくて……オショウ本人！オショウの妻はずっと前に亡くなっていて、彼は心を壊し、ずっと妻が側にいるって錯覚してたんだ……！",
            ["DialogueId"] = 51140072,
            ["GUID"] = "80061810",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                [2] = "100001:n(701075)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51140073] = {
            ["Camera"] = "-642.771484,-71.21875,4.600586,0.000118,7.999989,2.046195,42.955368,234.325912,false,DoNotOverride,7.0",
            ["Content"] = "是的……他之所以在暴雨中苦等一夜，直到溺亡都等不来他的妻子，是因为他吃了药，妄想的症状有所减轻，所以反而“看不到”幻想出的妻子了。",
            ["ContentJP"] = "うん……そして暴雨の日、どれだけ待っても妻が現れなかったのは──薬で妄想が少し薄れて、姿が見えなくなったからなんだ。",
            ["DialogueId"] = 51140073,
            ["GUID"] = "8006183A",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk03_End",
                },
            },
        [51140074] = {
            ["Camera"] = "-6.933594,-41.625,141.566406,0.000099,-5.84296,-115.514038,14.773981,58.703678,false,Manual,2.8",
            ["Content"] = "扶疏，这册诊籍里的柳姓男子，他的名字是不是叫<H>柳尾生</>？",
            ["ContentJP"] = "フーシュ……この診断書の「リョウ」という患者……名前は、<H>リョウオショウ</>なんじゃないかな？",
            ["DialogueId"] = 51140074,
            ["FacialId"] = {
                [1] = "100001:Confident02",
                },
            ["GUID"] = "80061864",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "200002:n(200002)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51140075] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "不错。他的姓名应该只记在姐姐日记里，你怎知……？",
            ["ContentJP"] = "え……？この指名は姉の日記にしか残っていないはず……どうしてそれを？",
            ["DialogueId"] = 51140075,
            ["GUID"] = "8006188E",
            ["SpeakNpcId"] = 701075,
            },
        [51140076] = {
            ["Camera"] = "-86.828125,129.613281,73.053711,0.000108,9.999997,-87.957306,28.133715,234.328125,false,Manual,1.855292",
            ["Content"] = "拜托我们寻找妻子的那位无由生名叫尾生，应该就是这位柳姓病人死后幻化而成。",
            ["ContentJP"] = "妻の捜索を頼んできたムユウセイの名もオショウだった。つまり……この患者が死したのち、ムユウセイとなったんだよ。",
            ["DialogueId"] = 51140076,
            ["GUID"] = "800618B8",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLToExplain_Start",
                },
            },
        [51140077] = {
            ["Camera"] = "-24.294922,12.818359,82.566406,0.000001,0.0,-178.519165,18.36294,75.471931,false,Manual,2.8",
            ["Content"] = "……我明白了！扶疏的姐姐救治的那个病人，不是尾生的妻子，而是尾生自己！他的妻子早就过世了，而他得了心病，一直以为自己的妻子还在身边！",
            ["ContentJP"] = "わかった……！フーシュのお姉さんが診ていた患者は、オショウの妻じゃなくて……オショウ本人！オショウの妻はずっと前に亡くなっていて、彼は心を壊し、ずっと妻が側にいるって錯覚してたんだ……！",
            ["DialogueId"] = 51140077,
            ["FacialId"] = {
                [1] = "200002:Smile01",
                },
            ["GUID"] = "800618E2",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited02_Start",
                },
            },
        [51140078] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "是的……他之所以在暴雨中苦等一夜，直到溺亡都等不来他的妻子，是因为他吃了药，妄想的症状有所减轻，所以反而“看不到”幻想出的妻子了。",
            ["ContentJP"] = "うん……そして暴雨の日、どれだけ待っても妻が現れなかったのは──薬で妄想が少し薄れて、姿が見えなくなったからなんだ。",
            ["DialogueId"] = 51140078,
            ["GUID"] = "8006190C",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLToExplain_End",
                [2] = "200002:Excited02_End",
                },
            },
        [51140079] = {
            ["Camera"] = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
            ["Content"] = "竟是……此般造化弄人。",
            ["ContentJP"] = "……まことに、運命とはいたずらなものです。",
            ["DialogueId"] = 51140079,
            ["GUID"] = "80061936",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "100001:Confident_End",
                },
            },
        [51140080] = {
            ["Camera"] = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
            ["Content"] = "呜……小仆从，我们赶紧回去把消息带给尾生吧。它实在太可怜了，希望它能解脱出来，回到那个什么忘川……",
            ["ContentJP"] = "うぅ……我が下僕、早く戻ってオショウに伝えてあげようよ……かわいそうだよ……はやく解き放って、三途の川とやらに……",
            ["DialogueId"] = 51140080,
            ["FacialId"] = {
                [1] = "200002:Sad01",
                },
            ["GUID"] = "80061960",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Sigh_Start",
                },
            },
        [51140081] = {
            ["Camera"] = "-81.537109,-85.851562,132.566406,0.000039,0.0,11.891485,18.482418,157.042984,false,Manual,1.41721",
            ["Content"] = "恕我冒昧，{nickname}，你打算如何告知那位尾生呢？",
            ["ContentJP"] = "ひとつ、お伺いしてもよろしいでしょうか。オショウに、あなたは「何と」伝えるおつもりですか？",
            ["DialogueId"] = 51140081,
            ["FacialId"] = {
                [1] = "701075:Disappoint01",
                },
            ["GUID"] = "8006198A",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Talk02_Start",
                [2] = "200002:Sigh_End",
                },
            },
        [51140082] = {
            ["Camera"] = "-80.082031,72.5625,90.84375,0.000107,3.097224,-93.557159,11.88,234.325912,false,Manual,1.855292",
            ["Content"] = "扶疏，你似乎有什么建议？",
            ["ContentJP"] = "……フーシュ、何か考えが？",
            ["DialogueId"] = 51140082,
            ["GUID"] = "800619B4",
            ["LookAt"] = {
                [1] = "200002:n(701075)",
                [2] = "100001:n(701075)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "701075:Talk02_End",
                [2] = "100001：Explain02_Start",
                },
            },
        [51140083] = {
            ["Camera"] = "-51.0,-35.339844,149.195312,0.000083,1.15922,9.291944,35.000008,116.515465,false,Manual,7.0",
            ["Content"] = "那位无由生，生前便已执念深重，不愿相信眼前事实。倘若如实告知，只怕……对它的执念并无助益。",
            ["ContentJP"] = "あのムユウセイは、生前から強い執念に囚われていた人。真実をそのまま告げたところで……それが彼を救うとは、言い切れませぬ。",
            ["DialogueId"] = 51140083,
            ["GUID"] = "800619DE",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain02_Start",
                },
            },
        [51140084] = {
            ["Camera"] = "-19.023438,-3.457031,149.845703,0.000083,1.15922,-11.708227,35.000008,85.264961,false,Manual,7.0",
            ["Content"] = "如果你愿意听扶疏一言——",
            ["ContentJP"] = "もし、お聞き届けいただけるなら──",
            ["DialogueId"] = 51140084,
            ["GUID"] = "80061A08",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "100001：Explain02_End",
                },
            },
        [51140085] = {
            ["Content"] = "（扶疏在你的耳边低语了几句。）",
            ["ContentJP"] = "フーシュはあなたの耳元で何かを呟いた。",
            ["DialogueId"] = 51140085,
            ["GUID"] = "80061A32",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "701075:n(701075)",
                [2] = "200002:n(200002)",
                [3] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 0,
            },
        [51140086] = {
            ["Camera"] = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
            ["Content"] = "如此，对它来说或许是更好的答案。",
            ["ContentJP"] = "……これが、彼にとって最も穏やかな答えでしょう。",
            ["DialogueId"] = 51140086,
            ["FacialId"] = {
                [1] = "701075:None",
                },
            ["GUID"] = "80061A5C",
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Explain02_End",
                },
            },
        [51140087] = {
            ["Camera"] = "313.945312,521.587891,463.705078,0.000028,-29.999958,-121.712296,35.000008,275.432831,false,DoNotOverride,7.0",
            ["Content"] = "谢谢你，扶疏。我们告辞了。",
            ["ContentJP"] = "ありがとう、フーシュ。行ってくる。",
            ["DialogueId"] = 51140087,
            ["GUID"] = "80061A86",
            ["Scripts"] = "PARA{\
MoveTo{_delay{2},ActorId{100001},MoveSpeed{150},TargetPoint{\"Targetpoint_20030905\"}},\
MoveTo{_delay{2},ActorId{200002},MoveSpeed{150},TargetPoint{\"Targetpoint_20030906\"}}\
}",
            ["SpeakNpcId"] = 100001,
            },
        [51140088] = {
            ["Camera"] = "112.988281,113.580078,57.077148,0.000138,3.696717,102.451233,35.000008,820.2052,false,Manual,7.0",
            ["Content"] = "……斯人已逝，徒留生者徘徊在尘世间，茕茕孑立，形影成双。",
            ["ContentJP"] = "……人は逝き、その影だけが残され、生者はただ迷い続ける──ひとりきりで、誰かの影と寄り添うように。",
            ["DialogueId"] = 51140088,
            ["GUID"] = "80061AB0",
            ["Scripts"] = "MoveTo{ActorId{701075},MoveSpeed{150},TargetPoint{\"Targetpoint_20030904\"}},",
            ["SpeakNpcId"] = 701075,
            },
        [51140089] = {
            ["Camera"] = "-50.109375,864.226562,147.566406,0.000144,0.0,169.044022,50.171638,134.067627,false,Manual,7.0",
            ["Content"] = "消弭执念，说起来容易，但对真正心怀执念的人而言，它真的好沉重……太沉重了……你说是不是？",
            ["ContentJP"] = "執念を断つというのは……言うほど容易ではございません。抱えた者にとっては……重すぎるのです、本当に。",
            ["DialogueId"] = 51140089,
            ["FacialId"] = {
                [1] = "701075:Sad01",
                },
            ["GUID"] = "80061ADA",
            ["Scripts"] = "SEQ{ TurnTo{TurnToDescription{\"701075:p(-20)\"}}, LookAt{LookAtDescription{\"701075:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 701075,
            },
        [51140090] = {
            ["Camera"] = "-50.109375,864.226562,147.566406,0.000144,0.0,169.044022,50.171638,134.067627,false,Manual,7.0",
            ["Content"] = "——姐姐。",
            ["ContentJP"] = "……そう思いませんか──姉さま。",
            ["DialogueId"] = 51140090,
            ["GUID"] = "80061B04",
            ["LookAt"] = {
                [1] = "701075:n(701075)",
                },
            ["SpeakNpcId"] = 701075,
            ["TalkActionId"] = {
                [1] = "701075:Sad02_Start",
                },
            },
        [51150001] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "你们回来了！怎么样，有问到我妻子的消息吗？",
            ["ContentJP"] = "……戻られたのですね！どうでしたか？妻の情報、わかりましたか……？",
            ["DialogueId"] = 51150001,
            ["GUID"] = "800C750A",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Born",
                },
            },
        [51150002] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "（按照扶疏的建议，你开始向尾生娓娓道来妻子的下落……）",
            ["ContentJP"] = "フーシュの助言を思い出し、あなたは静かに、オショウに語り始めた──",
            ["DialogueId"] = 51150002,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800C7534",
            ["TalkActionId"] = {
                [1] = "100001:Explain01_Start",
                },
            },
        [51150003] = {
            ["Camera"] = "11.114258,106.112305,84.475708,0.000119,19.999981,-140.838303,64.81044,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "什么？你说闲书已经不在人世了？因为……我已经死了九十多年？",
            ["ContentJP"] = "……なんと……カンショはもう、この世にいない……？それに……私がすでに、九十年もの時を……死して過ごしていた……と……？",
            ["DialogueId"] = 51150003,
            ["GUID"] = "800C755E",
            ["SpeakNpcId"] = 701074,
            },
        [51150004] = {
            ["Camera"] = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
            ["Content"] = "是的。",
            ["ContentJP"] = "うん。",
            ["DialogueId"] = 51150004,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "800C7588",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001：Explain01_End",
                },
            },
        [51150005] = {
            ["Camera"] = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "……原来……在这虞泉……我竟已浑浑噩噩度过如此之久……",
            ["ContentJP"] = "…………そうか……この<Default note=\"text:ぐせん\">虞泉</>で、そんなにも……私は、ただ彷徨い続けていたのですね……",
            ["DialogueId"] = 51150005,
            ["GUID"] = "800C75B2",
            ["SpeakNpcId"] = 701074,
            },
        [51150006] = {
            ["Camera"] = "121.967773,-57.251953,229.506348,0.000098,-10.894431,176.76123,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "那闲书呢？她去了哪儿？她……这些年来，她好吗？",
            ["ContentJP"] = "……それで、カンショは……？彼女は……この長い歳月を、どう過ごしていたのです……？",
            ["DialogueId"] = 51150006,
            ["GUID"] = "800C75DC",
            ["SpeakNpcId"] = 701074,
            },
        [51150007] = {
            ["Camera"] = "-455.513672,-227.362305,283.345703,0.000077,-20.494774,26.363897,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "(你与白对视了一眼）",
            ["ContentJP"] = "あなたは、隣に立つスノウと一瞬視線を交わす。",
            ["DialogueId"] = 51150007,
            ["GUID"] = "800C7606",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["SpeakNpcId"] = 0,
            },
        [51150008] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "闲书抱病多年，一直得你照料，但她不愿成为你的负累。所以当年，她选择了离家出走。",
            ["ContentJP"] = "カンショは、病に伏せていた間──あなたの献身に感謝しながらも、自分が重荷になることを恐れていました。だから……あの日、彼女はそっと家を出たのです。",
            ["DialogueId"] = 51150008,
            ["GUID"] = "800C7630",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                [2] = "200002:n(200002)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ExplainTwo_Start",
                },
            },
        [51150009] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "但是……机缘巧合之下，她遇到了一位在烟津渡旅行的天才药师。在那位天才药师的悉心治疗下，闲书得以痊愈。",
            ["ContentJP"] = "でも、運命は彼女に希望を残してくれました。旅の途中、彼女は偶然、<Default note=\"text:えんしんと\">煙津渡</>に訪れていた、名高き治療家と出会ったのです。その薬師の手厚い看病のもと、カンショの病は癒えました。",
            ["DialogueId"] = 51150009,
            ["GUID"] = "800C765A",
            ["LookAt"] = {
                [1] = "100001:n(701074)",
                [2] = "200002:n(701074)",
                },
            ["SpeakNpcId"] = 100001,
            },
        [51150010] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "可当她回到家去找你的时候，却听到了你已经死在洪水里的消息。",
            ["ContentJP"] = "……そして彼女が帰郷した時に耳にしたのは──あなたが洪水に巻き込まれ、亡くなったという知らせでした。",
            ["DialogueId"] = 51150010,
            ["FacialId"] = {
                [1] = "100001:Sad03",
                },
            ["GUID"] = "800C7684",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ExplainTwo_End",
                },
            },
        [51150011] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "竟是……如此……",
            ["ContentJP"] = "……そんな……",
            ["DialogueId"] = 51150011,
            ["GUID"] = "800C76AE",
            ["SpeakNpcId"] = 701074,
            },
        [51150012] = {
            ["Camera"] = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
            ["Content"] = "但，她并没有让自己就这样一辈子浑浑噩噩下去。为你痛哭一场后，她拜那位药师为师，开始学习药学。",
            ["ContentJP"] = "彼女は深く悲しみ、涙を流しました。けれど、悲しみに溺れることなく、心に決めたのです。",
            ["DialogueId"] = 51150012,
            ["FacialId"] = {
                [1] = "100001:Satisfy01",
                },
            ["GUID"] = "800C76D8",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51150013] = {
            ["Camera"] = "-125.262207,40.953125,171.12085,0.000126,-15.293818,-18.234081,35.000015,117.407356,false,Manual,3.0",
            ["Content"] = "她希望可以尽绵薄之力，为那些被病痛折磨的人缓解痛苦。她不希望她与你的悲剧，再在其他人身上上演。",
            ["ContentJP"] = "薬師に弟子入りし、医学を学び、今度は自らが、人々の苦しみを和らげる力になろうと。あなたとの哀しみを、他の誰かが繰り返さぬようにと──",
            ["DialogueId"] = 51150013,
            ["GUID"] = "800C7702",
            ["SpeakNpcId"] = 100001,
            },
        [51150014] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "她是一个勤奋的学生，后来，她也成为了老师，她也有了自己的学生。再后来，学生又有了学生……",
            ["ContentJP"] = "カンショは懸命に学びました。やがて師となり、弟子を育て……その弟子がまた弟子を持ち……彼女の想いは連なっていきました。",
            ["DialogueId"] = 51150014,
            ["GUID"] = "800C772C",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_End",
                },
            },
        [51150015] = {
            ["Camera"] = "-243.208984,-3.944336,191.368408,-0.0,-15.293783,-3.434053,35.000015,266.740662,false,Manual,7.0",
            ["Content"] = "他们一起，救治了很多病人。学生们都很爱戴她，就像她的儿女一样……一直到她九十岁高龄辞世。",
            ["ContentJP"] = "多くの命が救われ、彼女は皆に慕われました。子を持たぬ彼女でしたが、弟子たちは皆、彼女を母のように敬いました。そして──九十の齢まで、穏やかに、生をまっとうされたのです。",
            ["DialogueId"] = 51150015,
            ["GUID"] = "800C7756",
            ["SpeakNpcId"] = 100001,
            },
        [51150016] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "……太好了，太好了……",
            ["ContentJP"] = "……ああ……よかった……本当によかった……",
            ["DialogueId"] = 51150016,
            ["GUID"] = "800C7780",
            ["SpeakNpcId"] = 701074,
            },
        [51150017] = {
            ["Camera"] = "29.751953,-50.233398,225.475708,0.000091,-14.99999,175.16095,35.000011,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "她的病好了……她幸福地度过一生……我便放心了……",
            ["ContentJP"] = "病が癒えて……幸せに過ごしてくれていたのですね……それだけで……もう、私は……",
            ["DialogueId"] = 51150017,
            ["GUID"] = "800C77AA",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Agree",
                },
            },
        [51150018] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "一切都……过去了……我也可以安心地……",
            ["ContentJP"] = "……すべてが、過ぎ去った……これでもう……心残りはありません……",
            ["DialogueId"] = 51150018,
            ["GUID"] = "800C77D4",
            ["SpeakNpcId"] = 701074,
            },
        [51150019] = {
            ["Camera"] = "333.445312,-77.007812,119.176392,0.000049,3.105147,176.364456,35.0,100000.0,false,DoNotOverride,7.0",
            ["Content"] = "谢谢你们，二位，真的……谢谢……",
            ["ContentJP"] = "……ありがとう……本当に……ありがとうございます……",
            ["DialogueId"] = 51150019,
            ["GUID"] = "800C77FE",
            ["SpeakNpcId"] = 701074,
            ["TalkActionId"] = {
                [1] = "701074:Wuyou_Disappear",
                },
            },
        [51150020] = {
            ["Content"] = "尾生的身体逐渐透明，直到逐渐消失在你面前，在完全消散的瞬间，你看到什么晶莹剔透的东西从它体内坠落。",
            ["ContentJP"] = "オショウの身体が、ゆっくりと、透明になってゆく。やがて完全に姿を消すその瞬間、光の粒のような何かが、ふわりと彼の胸元からこぼれ落ちた。",
            ["DialogueId"] = 51150020,
            ["GUID"] = "800C7828",
            ["SpeakNpcId"] = 0,
            },
        [51150021] = {
            ["Content"] = "无由生也会流泪吗？还是说只是一束偶然折射过来的阳光……",
            ["ContentJP"] = "（それは涙だったのだろうか。それとも──ただ陽の光が偶然、そう見せただけなのか……）",
            ["DialogueId"] = 51150021,
            ["GUID"] = "800C7852",
            ["SpeakNpcId"] = 0,
            },
        [51151001] = {
            ["Camera"] = "-619.021484,275.37793,18.173828,0.000051,1.999995,-13.887951,33.047028,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是说百年春角落那间仓库吗？那里不是早就租给天岚先生做供货仓库了吗？为何现在过来提起？",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>の角の、あの古い倉庫のこと？あそこならテンランさんに貸しているはずだが……どうかしたの？",
            ["DialogueId"] = 51151001,
            ["FacialId"] = {
                [1] = "100001:Think01",
                [2] = "700371:Cin_Nervous",
                },
            ["FinalCamera"] = "-542.628906,256.49707,21.111328,0.000051,2.499999,-13.887944,33.047028,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "800D191A",
            ["LookAt"] = {
                [1] = "100001:n(700370)",
                },
            ["NextDialogue"] = 51151002,
            ["SpeakNpcId"] = 700370,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                [2] = "700370:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            },
        [51151002] = {
            ["Content"] = "天岚先生自从上次跟船出海后迟迟未归，但他之前收购的一批香料都放在仓库里，已经放了好几个月。",
            ["ContentJP"] = "それがですね、テンランさん……前に船に乗って海へ出て以来、ずっと戻ってこなくて。でも、あの人が買い取った香辛料の荷が倉庫に置きっぱなしで、もう何か月も経つんです。",
            ["DialogueId"] = 51151002,
            ["GUID"] = "800D1944",
            ["NextDialogue"] = 51151003,
            ["SpeakNpcId"] = 700371,
            ["TalkActionId"] = {
                [1] = "700371:Explain02_Start",
                },
            },
        [51151003] = {
            ["Content"] = "你这话说的我都有些迷糊了。放着便放着呗，那间仓库的租金一直续到明年呢……",
            ["ContentJP"] = "あら……そうだったの？まあ、置いてあるだけなら構わないだろうに。倉庫の賃料だって、来年までちゃんと契約してあるんだよ？",
            ["DialogueId"] = 51151003,
            ["GUID"] = "800D196E",
            ["NextDialogue"] = 51151004,
            ["SpeakNpcId"] = 700370,
            ["TalkActionId"] = {
                [1] = "700370:Talk03_End",
                },
            },
        [51151004] = {
            ["Content"] = "不是啊，望春姐，是最近百年春都在说，那仓库里闹鬼！",
            ["ContentJP"] = "いや、それが……最近、百年春じゅうで噂になってるんです。あの倉庫、出るらしいですよ──幽霊が。",
            ["DialogueId"] = 51151004,
            ["GUID"] = "800D1998",
            ["NextDialogue"] = 51151005,
            ["SpeakNpcId"] = 700371,
            },
        [51151005] = {
            ["Content"] = "什……什么？！",
            ["ContentJP"] = "……え！？",
            ["DialogueId"] = 51151005,
            ["FacialId"] = {
                [1] = "700370:Cin_Angry01",
                },
            ["GUID"] = "800D19C2",
            ["NextDialogue"] = 51151006,
            ["SpeakNpcId"] = 700370,
            ["TalkActionId"] = {
                [1] = "700370:Shock03_Start",
                [2] = "700371:Explain02_End",
                },
            },
        [51151006] = {
            ["Content"] = "是这样，之前有一批点货人想进去检查库存，结果刚进去就晕头转脑的，人没看到货就绕出门了。",
            ["ContentJP"] = "ほんとなんですって！このあいだ、荷物の確認で出入りした点検係の人たちが、中に入った途端ふらふらになって、肝心の荷も見ないまま、気づけば外に戻ってたんですよ。",
            ["DialogueId"] = 51151006,
            ["GUID"] = "800D19EC",
            ["NextDialogue"] = 51151007,
            ["SpeakNpcId"] = 700371,
            ["TalkActionId"] = {
                [1] = "700371:Explain02_Start",
                },
            },
        [51151007] = {
            ["Content"] = "后来有人不信邪，去了好些个胆子大的，都被这样恭恭敬敬“请”了出来。",
            ["ContentJP"] = "それで、半信半疑の人たちが何人も様子を見に行ったんですけど……みんな同じように「丁重に」外まで送り返されたみたいで。",
            ["DialogueId"] = 51151007,
            ["GUID"] = "800D1A16",
            ["NextDialogue"] = 51151008,
            ["SpeakNpcId"] = 700371,
            ["TalkActionId"] = {
                [1] = "700370:Shock03_End",
                },
            },
        [51151008] = {
            ["Content"] = "如此说来，虽然未出现伤人事件，但也确实是个麻烦事，我知晓了，抽空我会派人去看看的。",
            ["ContentJP"] = "……なるほどね。ケガ人はいないようだけれど、放っておくわけにもいかないわね。手が空き次第、誰か様子を見に向かわせましょう。",
            ["DialogueId"] = 51151008,
            ["FacialId"] = {
                [1] = "700370:Cin_Idle",
                },
            ["GUID"] = "800D1A40",
            ["LookAt"] = {
                [1] = "100001:n(100001)",
                },
            ["SpeakNpcId"] = 700370,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToThink_Start",
                [2] = "700370:Explain01_Start",
                },
            },
        [51151009] = {
            ["Content"] = "小仆从，你有没有觉得这间房子有些诡异……",
            ["ContentJP"] = "ねえ……この部屋、なんか……妙じゃない？",
            ["DialogueId"] = 51151009,
            ["GUID"] = "800D1A6A",
            ["NextDialogue"] = 51151010,
            ["SpeakNpcId"] = 200002,
            },
        [51151010] = {
            ["Content"] = "没有，是你想多了吧。",
            ["ContentJP"] = "気のせいだよ。",
            ["DialogueId"] = 51151010,
            ["GUID"] = "800D1A94",
            ["NextDialogue"] = 51151011,
            ["SpeakNpcId"] = 100001,
            },
        [51151011] = {
            ["Content"] = "是吗？可我总觉得这里的温度要比百年春别的地方冷一些，还能听到……一些奇怪的声音……",
            ["ContentJP"] = "そ、そうかな……？でも、なんとなく他の部屋より寒い気がする……それに、変な音も聞こえるんだよね……",
            ["DialogueId"] = 51151011,
            ["GUID"] = "800D1ABE",
            ["NextDialogue"] = 51151012,
            ["SpeakNpcId"] = 200002,
            },
        [51151012] = {
            ["Content"] = "如果你好奇的话，白天人来人往不太方便，我们晚上再来看看吧。",
            ["ContentJP"] = "気になるなら、夜にもう一度来てみよう。昼間は人通りが多すぎて、調べづらいし。",
            ["DialogueId"] = 51151012,
            ["GUID"] = "800D1AE8",
            ["SpeakNpcId"] = 100001,
            },
        [51151013] = {
            ["Camera"] = "-210.691406,554.429688,229.848145,0.000044,-12.799794,-74.596756,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "刚进那仓库没走几步路，我寻思那货箱怎么如此眼熟，就顺着墙壁摸着走，结果你猜怎么着？",
            ["ContentJP"] = "俺があの倉庫に入って、ほんの数歩歩いたあたりでさ……「あれ？この荷箱、見覚えあるな？」って思ったんだよ。で、壁を手でなぞりながら進んでたら──何が現れたと思う？",
            ["DialogueId"] = 51151013,
            ["FinalCamera"] = "-193.257812,491.109375,214.922363,0.000039,-12.799808,-74.597397,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "800D1B12",
            ["LookAt"] = {
                [1] = "700373:n(700372)",
                [2] = "700374:n(700372)",
                [3] = "100001:n(700372)",
                [4] = "200002:n(700372)",
                [5] = "700372:n(700374)",
                },
            ["NextDialogue"] = 51151014,
            ["SpeakNpcId"] = 700372,
            ["TalkActionId"] = {
                [1] = "700372:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51151014] = {
            ["Camera"] = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "有话快说，一天到晚尽卖你那关子。",
            ["ContentJP"] = "回りくどい！さっさと話せ！",
            ["DialogueId"] = 51151014,
            ["FacialId"] = {
                [1] = "700373:CM_Angry01",
                },
            ["GUID"] = "800D1B3C",
            ["NextDialogue"] = 51151015,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Confident_New_Start",
                [2] = "700372:Explain02_End",
                },
            },
        [51151015] = {
            ["Content"] = "咱们里面就你进去过百年春那闹鬼的仓库，别吊大伙的胃口啦。",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>で「あの」倉庫に入ったの、あんただけなんだからさ、引っ張らずに教えてくれよ〜！",
            ["DialogueId"] = 51151015,
            ["FacialId"] = {
                [1] = "700373:CM_Idle",
                },
            ["GUID"] = "800D1B66",
            ["NextDialogue"] = 51151016,
            ["SpeakNpcId"] = 700374,
            ["TalkActionId"] = {
                [1] = "700374:Talk03_Start",
                },
            },
        [51151016] = {
            ["Camera"] = "22.886719,365.171875,164.92334,0.000081,-4.399475,-107.398392,40.32243,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们还是太年轻，沉不住气，那我就给你们说明白咯——我当时就顺着墙壁，摸着货箱，一步一步地走。",
            ["ContentJP"] = "やれやれ、お前らはまだまだ若いねぇ。そんなに焦らなくてもいいじゃないの。……ま、教えてやるよ。俺はな、壁づたいに荷箱をたどって、ゆっくりと進んでたんだ。",
            ["DialogueId"] = 51151016,
            ["FacialId"] = {
                [1] = "700372:Cin_Angry01",
                },
            ["FinalCamera"] = "28.777344,301.472656,160.696777,0.000088,-3.399412,-113.597153,40.32243,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "800D1B90",
            ["NextDialogue"] = 51151017,
            ["SpeakNpcId"] = 700372,
            ["TalkActionId"] = {
                [1] = "700372:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 15,
            },
        [51151017] = {
            ["Content"] = "我手上不是拿着蜡烛嘛，我就觉得……诶？这蜡烛怎么摇摆不定的？这屋子里明明也没风呀，结果，就在我一个晃神之间——！",
            ["ContentJP"] = "そのとき手に持ってた蝋燭が、ふと──揺れた。風なんかないはずなのに、だぞ？おかしいなと思ったその瞬間──",
            ["DialogueId"] = 51151017,
            ["GUID"] = "800D1BBA",
            ["NextDialogue"] = 51151018,
            ["SpeakNpcId"] = 700372,
            ["TalkActionId"] = {
                [1] = "700372:Explain02_Start",
                [2] = "700373:Confident_New_End",
                [3] = "700374:Talk03_End",
                },
            },
        [51151018] = {
            ["Camera"] = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哇啊啊！",
            ["ContentJP"] = "うわああっ！！",
            ["DialogueId"] = 51151018,
            ["FacialId"] = {
                [1] = "700374:CM_Shock01",
                [2] = "700372:Cin_Idle",
                },
            ["GUID"] = "800D1BE4",
            ["NextDialogue"] = 51151019,
            ["SpeakNpcId"] = 700374,
            ["TalkActionId"] = {
                [1] = "700374:Shock_Start",
                },
            },
        [51151019] = {
            ["Content"] = "笨蛋，叫什么？本来不吓人，你这一嗓子给我吓得够呛！继续说！",
            ["ContentJP"] = "びっくりしたぁ！お前の叫び声のほうが怖えーよ！……それで、どうなったんだよ、続きは？",
            ["DialogueId"] = 51151019,
            ["FacialId"] = {
                [1] = "700373:CM_Angry01",
                },
            ["GUID"] = "800D1C0E",
            ["LookAt"] = {
