            },
        [51151023] = {
            ["Content"] = "你这不是也被吓到了吗？",
            ["ContentJP"] = "……あれ？お前も叫んでんじゃん！",
            ["DialogueId"] = 51151023,
            ["FacialId"] = {
                [1] = "700373:CM_Idle",
                [2] = "700374:CM_Ahaha01",
                },
            ["GUID"] = "800D1CB6",
            ["LookAt"] = {
                [1] = "700373:n(700374)",
                [2] = "700374:n(700373)",
                },
            ["NextDialogue"] = 51151024,
            ["SpeakNpcId"] = 700374,
            ["TalkActionId"] = {
                [1] = "700374:Shock_End",
                },
            },
        [51151024] = {
            ["Content"] = "我这是被你吓到的！后来呢？后来发生什么了？",
            ["ContentJP"] = "違う！お前の声に驚いただけだ！……で？その後は？",
            ["DialogueId"] = 51151024,
            ["FacialId"] = {
                [1] = "700373:CM_Angry01",
                [2] = "700374:CM_Idle",
                [3] = "200002:Happy02",
                [4] = "100001:Ahaha02",
                },
            ["GUID"] = "800D1CE0",
            ["NextDialogue"] = 51151025,
            ["Scripts"] = "LookAt{_delay{2},LookAtDescription{\"700373:n(700372)\"}}",
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Shock_End",
                },
            },
        [51151025] = {
            ["Camera"] = "28.777344,301.472656,160.696777,0.000088,-3.399412,-113.597153,40.32243,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "后面……我没了蜡烛看不见路，所以就顺着来路退出去咯。说了也奇怪，回程的时候顺风顺水，一点问题也没有。",
            ["ContentJP"] = "……もう真っ暗で、何も見えなくなったからさ。来た道を戻って出たよ。不思議なことにね、出るときはすんなりだったんだよな。何も起きなかった。不気味だけど、まあ無事には戻れたってわけ。",
            ["DialogueId"] = 51151025,
            ["FacialId"] = {
                [1] = "700373:CM_Idle",
                [2] = "100001:None",
                [3] = "200002:None",
                },
            ["GUID"] = "800D1D0A",
            ["LookAt"] = {
                [1] = "700373:n(700372)",
                [2] = "700374:n(700372)",
                [3] = "100001:n(700372)",
                [4] = "200002:n(700372)",
                [5] = "700372:n(700374)",
                },
            ["NextDialogue"] = 51151026,
            ["SpeakNpcId"] = 700372,
            ["TalkActionId"] = {
                [1] = "700372:Disagree",
                },
            },
        [51151026] = {
            ["Camera"] = "-306.484375,75.011719,167.002441,0.000083,-8.799134,3.801234,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "看来这闹鬼的地方是有些玄乎……你身上不会沾了什么脏东西吧，这几天你可得好好去白龙神君那拜拜。",
            ["ContentJP"] = "こりゃあ、マジで妙なことが起きてんのかもな……。お前、何か憑かれてないだろうな？この数日はちゃんと白龍様にお参り行けよ？",
            ["DialogueId"] = 51151026,
            ["GUID"] = "800D1D34",
            ["NextDialogue"] = 51151027,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Think_Start",
                },
            },
        [51151027] = {
            ["Content"] = "太可怕了，我每天回家的时候还要路过那间仓库呢，要是我也被那些家伙盯上……呜啊，好可怕！",
            ["ContentJP"] = "こ、こわすぎる……！俺、帰り道あの倉庫の前通るのに……！もし変なのに目つけられたら……ひぇぇ……",
            ["DialogueId"] = 51151027,
            ["FacialId"] = {
                [1] = "700374:CM_Sad01",
                },
            ["GUID"] = "800D1D5E",
            ["LookAt"] = {
                [1] = "700374:n(700374)",
                [2] = "200002:n(200002)",
                },
            ["NextDialogue"] = 51151028,
            ["SpeakNpcId"] = 700374,
            ["TalkActionId"] = {
                [1] = "700374:Pray_Start",
                },
            },
        [51151028] = {
            ["Camera"] = "213.640625,-171.183594,172.974609,0.000074,-8.198412,134.596756,40.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "闹鬼？华胥的幽灵不就是无由生嘛，所以说……是有无由生在捣乱？",
            ["ContentJP"] = "幽霊騒ぎ？華胥の幽霊って……ムユウセイじゃん。すべてはムユウセイの悪戯なのかな。",
            ["DialogueId"] = 51151028,
            ["FacialId"] = {
                [1] = "200002:Think02",
                [2] = "700374:CM_Idle",
                },
            ["GUID"] = "800D1D88",
            ["NextDialogue"] = 51151029,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                [2] = "700373:Think_End",
                },
            },
        [51151029] = {
            ["Camera"] = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "管他是闹鬼还是闹事，天岚先生既然把仓库托付给我们，就是相信我们无论发生什么都能把事摆平！",
            ["ContentJP"] = "幽霊だろうが何だろうが、テンランさんが倉庫を任せてくれたのは、俺たちが責任持って片づけるって信じてくれてるからだ！",
            ["DialogueId"] = 51151029,
            ["FacialId"] = {
                [1] = "700373:CM_Angry01",
                },
            ["GUID"] = "800D1DB2",
            ["LookAt"] = {
                [1] = "100001:n(700373)",
                [2] = "200002:n(700373)",
                },
            ["NextDialogue"] = 51151030,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:CM_Story_AngryPoint_Start",
                },
            },
        [51151030] = {
            ["Content"] = "兄弟们，话不多说，咱三今晚一起，把这仓库里的牛鬼蛇神全部赶走！成不成？",
            ["ContentJP"] = "お前たち、何も言うな！今夜、俺たち三人であの倉庫にいる連中──牛だろうが蛇だろうが神だろうが──まとめて追い払うぞ！",
            ["DialogueId"] = 51151030,
            ["GUID"] = "800D1DDC",
            ["LookAt"] = {
                [1] = "700373:n(700374)",
                },
            ["NextDialogue"] = 51151031,
            ["SpeakNpcId"] = 700373,
            },
        [51151031] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51151031,
            ["GUID"] = "800D1E06",
            ["LookAt"] = {
                [1] = "700373:n(700372)",
                },
            ["NextDialogue"] = 51151032,
            ["SpeakNpcId"] = 700372,
            ["TalkActionId"] = {
                [1] = "700374:Pray_End",
                },
            },
        [51151032] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 51151032,
            ["GUID"] = "800D1E30",
            ["LookAt"] = {
                [1] = "700373:n(700374)",
                },
            ["NextDialogue"] = 51151033,
            ["SpeakNpcId"] = 700374,
            },
        [51151033] = {
            ["Content"] = "怎么不说话？哑巴了？",
            ["ContentJP"] = "……なにその沈黙！？",
            ["DialogueId"] = 51151033,
            ["GUID"] = "800D1E5A",
            ["NextOptions"] = {
                [1] = 51151034,
                [2] = 51151035,
                },
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:CM_Story_AngryPoint_End",
                },
            },
        [51151034] = {
            ["Content"] = "他们看起来并不想去。",
            ["ContentJP"] = "彼らはまったく乗り気ではないようだ",
            ["DialogueId"] = 51151034,
            ["GUID"] = "800D1E84",
            ["ImprPlusId"] = 1209,
            ["NextDialogue"] = 51151036,
            },
        [51151035] = {
            ["Content"] = "怂了！",
            ["ContentJP"] = "怖いんだ{性别:な|ね}！",
            ["DialogueId"] = 51151035,
            ["GUID"] = "800D1EAE",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51151036,
            },
        [51151036] = {
            ["Content"] = "哥几个什么意思呢？天岚先生走之前怎么说的？你们对得起先生的信任吗？",
            ["ContentJP"] = "おいおい、どういうことだよ！？テンランさんが旅立つ前に言ってたことを忘れたのか？その信頼を裏切っていいのかよ！？",
            ["DialogueId"] = 51151036,
            ["GUID"] = "800D1ED8",
            ["LookAt"] = {
                [1] = "700373:n(700372)",
                },
            ["NextDialogue"] = 51151037,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Angry01_Start",
                },
            },
        [51151037] = {
            ["Camera"] = "28.777344,301.472656,160.696777,0.000088,-3.399412,-113.597153,40.32243,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我已经去过了，下一个该轮到你们了……",
            ["ContentJP"] = "いや俺はもう行ったし……次はお前らの番だろ？",
            ["DialogueId"] = 51151037,
            ["FacialId"] = {
                [1] = "700372:Cin_Ahaha02",
                },
            ["GUID"] = "800D1F02",
            ["NextDialogue"] = 51151038,
            ["SpeakNpcId"] = 700372,
            ["TalkActionId"] = {
                [1] = "700372:Salute_Start",
                },
            },
        [51151038] = {
            ["Camera"] = "-194.214844,51.722656,184.808594,0.000098,-12.799473,29.2036,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我、我实在不敢去……",
            ["ContentJP"] = "お、俺は無理だ……本当に無理……！",
            ["DialogueId"] = 51151038,
            ["FacialId"] = {
                [1] = "700374:CM_Sad01",
                },
            ["GUID"] = "800D1F2C",
            ["LookAt"] = {
                [1] = "700373:n(700374)",
                },
            ["NextDialogue"] = 51151039,
            ["SpeakNpcId"] = 700374,
            ["TalkActionId"] = {
                [1] = "700374:Disagree",
                },
            },
        [51151039] = {
            ["Camera"] = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好！好啊你们，既然你们都不敢去，我就找别人一同前去！我就不信这偌大一个华胥，找不出两个有胆之人！",
            ["ContentJP"] = "……チッ、わかったよ。お前らがビビってるなら──他を当たるまでだ！この華胥で、肝の据わった奴が一人もいないなんてこと、あるまいよ！",
            ["DialogueId"] = 51151039,
            ["GUID"] = "800D1F56",
            ["NextDialogue"] = 51151040,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700372:Salute_End",
                },
            },
        [51151040] = {
            ["Camera"] = "179.324219,-165.5,220.73877,0.000185,-15.398804,129.391922,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "就……你！你们这两个外乡人，今夜和我一起去，如何？",
            ["ContentJP"] = "──というわけで！そこのあんたたち！そう、そこの外から来たお二人さん！今夜、俺と一緒に行こうぜ！",
            ["DialogueId"] = 51151040,
            ["GUID"] = "800D1F80",
            ["LookAt"] = {
                [1] = "700373:n(100001)",
                [2] = "700372:n(100001)",
                [3] = "700374:n(100001)",
                },
            ["NextDialogue"] = 51151041,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Angry01_End",
                },
            },
        [51151041] = {
            ["Camera"] = "70.183594,-23.027344,199.26416,0.000156,-17.198503,132.787445,40.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "诶？我们只是来看热闹的，怎么把我们算上了？",
            ["ContentJP"] = "ええっ！？ちょ、ちょっと待って！スノウたち、通りかかっただけなんだけど！？",
            ["DialogueId"] = 51151041,
            ["FacialId"] = {
                [1] = "200002:Shock02",
                },
            ["GUID"] = "800D1FAA",
            ["NextDialogue"] = 51151042,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_End",
                [2] = "100001:TilteHead_Start",
                },
            },
        [51151042] = {
            ["Camera"] = "-416.273438,78.617188,184.048828,0.000083,-8.999136,0.601226,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "怎么？怕了？看你们两个浓眉大眼的样子，还以为是什么勇武之士，没想到还是和这两个笨蛋一样，胆小怕事！",
            ["ContentJP"] = "何だよ、もう腰が引けてんのか？その顔つきならてっきり肝の据わった奴かと思ったのによ、口だけの腰抜けだったとはな！",
            ["DialogueId"] = 51151042,
            ["GUID"] = "800D1FD4",
            ["LookAt"] = {
                [1] = "700373:n(200002)",
                [2] = "100001:n(100001)",
                },
            ["NextDialogue"] = 51151043,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Talk03_Start",
                [2] = "100001:TilteHead_End",
                },
            },
        [51151043] = {
            ["Camera"] = "32.535156,17.695312,163.679688,0.000156,-19.198513,142.387589,40.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你说谁胆小怕事了！不就是无由生嘛，我和小仆从不知道都已经见过多少只了！倒是你，到时候可别吓晕过去，拖我们后腿！",
            ["ContentJP"] = "誰が腰抜けだって！？ムユウセイなんて、山ほど見てきたんだから！？怖いのはあんたのほうでしょ！行ったら泣きながら逃げるの、目に見えてるんだから！",
            ["DialogueId"] = 51151043,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                [2] = "100001:Ahaha02",
                },
            ["GUID"] = "800D1FFE",
            ["NextDialogue"] = 51151044,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                [2] = "100001:Sigh_Start",
                },
            },
        [51151044] = {
            ["Camera"] = "-180.933594,126.3125,153.535645,0.000205,-4.798679,-17.01202,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好！有骨气！那咱们就约好了，今天晚上，仓库门口见！对，咱们定个接头的暗号吧！就用……最有名的那句！",
            ["ContentJP"] = "いいぞ、その心意気！なら決まりだ！ 今夜、倉庫前で合流な！そうだ、合言葉を決めておこうぜ──一番有名な、アレだ！",
            ["DialogueId"] = 51151044,
            ["FacialId"] = {
                [1] = "700373:CM_Happy01",
                },
            ["GUID"] = "800D2028",
            ["NextDialogue"] = 51151045,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_End",
                },
            },
        [51151045] = {
            ["Camera"] = "79.785156,-33.371094,194.149414,0.000156,-16.798576,132.787445,30.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "最有名的那句？想难倒我？魔王大人无所不知，那就今晚不见不散！",
            ["ContentJP"] = "ふふん、はいはいアレね。魔王様たる私に分からないはずがない！よし、今夜、待ち合わせは……絶対に忘れないでよね！",
            ["DialogueId"] = 51151045,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                [2] = "100001:Doubt01",
                },
            ["GUID"] = "800D2052",
            ["NextDialogue"] = 51151046,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            },
        [51151046] = {
            ["Camera"] = "-3.273438,56.136719,193.95459,0.000133,-19.998594,124.586739,30.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（为什么你会知道什么暗号啊！）",
            ["ContentJP"] = "（……いつそんな「合言葉」を？）",
            ["DialogueId"] = 51151046,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["FinalCamera"] = "-19.519531,79.710938,183.536133,0.000133,-19.998594,124.586739,30.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "800D207C",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 3,
            },
        [51151047] = {
            ["Camera"] = "595.386719,637.626953,151.045898,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "之前咱们听了望春他们聊过后，我就去跟锦鲤皎皎打听了一下，如果她的消息没有出错……闹鬼的仓库就是这里了！",
            ["ContentJP"] = "この前、ボウシュンたちの話を聞いてから、ニシキにもいろいろ聞いてみたんだ！彼女の情報が正しければ──幽霊騒ぎの倉庫ってここだよね！",
            ["DialogueId"] = 51151047,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["FinalCamera"] = "555.324219,595.366699,149.560547,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "800D20A6",
            ["NextDialogue"] = 51151048,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51151048] = {
            ["Camera"] = "-36.691406,-227.51709,152.65332,0.000044,-7.06497,67.329269,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "既然是百年春烦恼的事情，就交给我们来帮忙解决吧！狩月人的售后服务，包老板满意！",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>の人たちが困ってるなら、私たちで解決してあげよう！月狩り人のアフターサービスは満足度100％だぞっ！",
            ["DialogueId"] = 51151048,
            ["GUID"] = "800D20D0",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            },
        [51151049] = {
            ["Camera"] = "595.386719,637.626953,151.045898,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "我们白天路过的房子是这间吗？",
            ["ContentJP"] = "昼間に通りがかったの、ここだったっけ？",
            ["DialogueId"] = 51151049,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["FinalCamera"] = "555.324219,595.366699,149.560547,0.000026,-1.464959,-133.471008,35.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "800D20FA",
            ["NextDialogue"] = 51151050,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51151050] = {
            ["Camera"] = "-36.691406,-227.51709,152.65332,0.000044,-7.06497,67.329269,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "唔……门口我做了石头标记……嗯嗯！就是这间！",
            ["ContentJP"] = "えっと……門のところに、目印の石を置いておいたんだよね……うんうん、やっぱりここ！間違いなし！",
            ["DialogueId"] = 51151050,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "800D2124",
            ["NextDialogue"] = 51151051,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            },
        [51151051] = {
            ["Content"] = "那就进去一探究竟吧。",
            ["ContentJP"] = "よし、中を調べてみよう。",
            ["DialogueId"] = 51151051,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D214E",
            ["NextDialogue"] = 51151052,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            },
        [51151052] = {
            ["Content"] = "出发出发！",
            ["ContentJP"] = "出発〜っ！",
            ["DialogueId"] = 51151052,
            ["GUID"] = "800D2178",
            ["SpeakNpcId"] = 200002,
            },
        [51151053] = {
            ["Camera"] = "501.320312,-108.880371,210.521484,0.000008,-12.845597,152.96994,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "来了，接头暗号是？",
            ["ContentJP"] = "よく来た！さて、合言葉は？",
            ["DialogueId"] = 51151053,
            ["GUID"] = "800D21A2",
            ["LookAt"] = {
                [1] = "700373:n(100001)",
                [2] = "100001:n(700373)",
                [3] = "200002:n(700373)",
                },
            ["NextDialogue"] = 51151054,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Talk03_Start",
                },
            },
        [51151054] = {
            ["Content"] = "接头暗号？",
            ["ContentJP"] = "……合言葉？",
            ["DialogueId"] = 51151054,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["GUID"] = "800D21CC",
            ["NextDialogue"] = 51151055,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_Start",
                },
            },
        [51151055] = {
            ["Content"] = "你忘了吗？宫廷月夜酒……",
            ["ContentJP"] = "忘れたのか？風に舞うは桃の香……",
            ["DialogueId"] = 51151055,
            ["FacialId"] = {
                [1] = "700373:CM_Angry01",
                },
            ["GUID"] = "800D21F6",
            ["NextDialogue"] = 51151056,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "100001:ScratchHead_End",
                },
            },
        [51151056] = {
            ["Camera"] = "-75.279297,-3.990723,118.624023,0.000049,-9.845662,26.368061,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "二百八一壶！",
            ["ContentJP"] = "三文五厘、夜の茶屋！",
            ["DialogueId"] = 51151056,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "800D2220",
            ["LookAt"] = {
                [1] = "700373:n(200002)",
                [2] = "100001:n(200002)",
                },
            ["NextDialogue"] = 51151057,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            },
        [51151057] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "这就是最有名的接头暗号吗？",
            ["ContentJP"] = "それ本当に合言葉なの{性别:か|}？",
            ["DialogueId"] = 51151057,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "800D224A",
            ["LookAt"] = {
                [1] = "200002:n(100001)",
                },
            ["NextDialogue"] = 51151058,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:TilteHead_Start",
                },
            },
        [51151058] = {
            ["Camera"] = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哼哼，小仆从对华胥的了解还是太肤浅啦~不像魔王大人，未卜先知，无所不知！",
            ["ContentJP"] = "ふふん、下僕にはまだ早かったかな。こういうのはね、わかる者にだけわかる通の証なのだよ！",
            ["DialogueId"] = 51151058,
            ["GUID"] = "800D2274",
            ["NextDialogue"] = 51151059,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:AgreeHead",
                },
            },
        [51151059] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是你缠着锦鲤皎皎教你的吧。",
            ["ContentJP"] = "……どうせニシキに教えてもらったんでしょ。",
            ["DialogueId"] = 51151059,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "800D229E",
            ["NextDialogue"] = 51151060,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            },
        [51151060] = {
            ["Camera"] = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你怎么知道的！",
            ["ContentJP"] = "なぜそれを！？",
            ["DialogueId"] = 51151060,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800D22C8",
            ["NextDialogue"] = 51151061,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                [2] = "100001:TilteHead_End",
                },
            },
        [51151061] = {
            ["Camera"] = "501.320312,-108.880371,210.521484,0.000008,-12.845597,152.96994,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "哈哈。你们来之前，我早就绕着这房子转了两圈，除了檐角又长了些青苔之外，并无其他异样。等你们准备好了，咱们就进去。",
            ["ContentJP"] = "あはは、いい掛け合いだな！お前たちが来る前に、俺も倉庫のまわりをぐるっと二周してきたんだが……軒先にちょっと苔が増えてたくらいで、特に怪しい気配はなかったな。準備ができたら、いこうぜ！",
            ["DialogueId"] = 51151061,
            ["FacialId"] = {
                [1] = "700373:CM_Smile01",
                [2] = "100001:None",
                [3] = "200002:None",
                },
            ["GUID"] = "800D22F2",
            ["LookAt"] = {
                [1] = "700373:n(100001)",
                [2] = "100001:n(700373)",
                [3] = "200002:n(700373)",
                },
            ["NextDialogue"] = 51151062,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51151062] = {
            ["Content"] = "好，我们走吧。",
            ["ContentJP"] = "うん、行こう。",
            ["DialogueId"] = 51151062,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D231C",
            ["NextDialogue"] = 51151063,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                [2] = "200002:Confident_Start",
                },
            },
        [51151063] = {
            ["Content"] = "勇气可嘉，不愧是我看中的人，我这就……咦？",
            ["ContentJP"] = "いいぞ、その心意気！さすが俺の見込んだ連中だ！よし、鍵を──……って、あれ？……あれれ？",
            ["DialogueId"] = 51151063,
            ["GUID"] = "800D2346",
            ["NextDialogue"] = 51151064,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Talk03_End",
                },
            },
        [51151064] = {
            ["Content"] = "等等，我好像……没带开门的钥匙……",
            ["ContentJP"] = "しまった！鍵、持ってくるの忘れたかも……！",
            ["DialogueId"] = 51151064,
            ["FacialId"] = {
                [1] = "700373:CM_Idle",
                },
            ["GUID"] = "800D2370",
            ["LookAt"] = {
                [1] = "700373:n(700373)",
                },
            ["NextDialogue"] = 51151065,
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Disagree",
                },
            },
        [51151065] = {
            ["Camera"] = "-75.279297,-3.990723,118.624023,0.000049,-9.845662,26.368061,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "你也太粗心大意啦，这下我们该怎么进去？",
            ["ContentJP"] = "ちょっとぉ！？肝心なとこでなにやってんの！これじゃ入れないじゃん！",
            ["DialogueId"] = 51151065,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "800D239A",
            ["NextDialogue"] = 51151066,
            ["SpeakNpcId"] = 200002,
            },
        [51151066] = {
            ["Content"] = "（一阵阴风吹来。“吱呀”一声，那本该紧锁的门，不知为何竟大敞开来。乍一望去，宛如一张黑漆漆的饕餮大口，似乎随时会将你们吞入……）",
            ["ContentJP"] = "そのとき、風もないのに、ぞわりと冷たい空気が流れ──ギィィ……という軋む音とともに、閉ざされていたはずの扉がゆっくりと勝手に開いた。その先は黒々とした闇。まるで巨大な怪物が口を開けて待ち構えているかのように──",
            ["DialogueId"] = 51151066,
            ["GUID"] = "800D23C4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51151067,
            },
        [51151067] = {
            ["Camera"] = "212.025391,71.061035,156.366211,0.000012,-5.445498,168.168427,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "鬼啊！！！闹鬼啦！！！",
            ["ContentJP"] = "ひ、ひぃぃっ！！！で、出たーーー！！",
            ["DialogueId"] = 51151067,
            ["FacialId"] = {
                [1] = "700373:CM_Shock01",
                },
            ["GUID"] = "800D23EE",
            ["NextDialogue"] = 51151068,
            ["Scripts"] = "CameraShake{FileName {\"FixSimple_CameraShake_Normal\"}}",
            ["SpeakNpcId"] = 700373,
            ["TalkActionId"] = {
                [1] = "700373:Shock_Start",
                [2] = "200002:Confident_End",
                },
            },
        [51151068] = {
            ["Content"] = "（在你们面前，肖阿壮扭头就跑，眨眼间便已经没了踪影……）",
            ["ContentJP"] = "そう叫んだかと思うと、ショウは全速力で脱兎のごとく逃げ出し──あっという間に視界から消えた。",
            ["DialogueId"] = 51151068,
            ["GUID"] = "800D2418",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51151069,
            ["Scripts"] = "SetVisibility{ActorId{700373},Visibility{\"Hide\"}}",
            },
        [51151069] = {
            ["Camera"] = "-201.375,-40.395996,174.717773,0.000056,-11.445586,26.764484,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "不是……他……明明是他撺掇我们过来探险，这还没进去就被吓跑了？他今天在码头那样说话，我还以为他胆子很大呢！",
            ["ContentJP"] = "……ちょ、え？あの人……さっきまであんなに偉そうにしてたのに！？中に入る前から脱落！？今日あれだけ「任せろ」とか言ってたの、なんだったの！？",
            ["DialogueId"] = 51151069,
            ["GUID"] = "800D2442",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                [2] = "200002:n(100001)",
                },
            ["NextDialogue"] = 51151070,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            },
        [51151070] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "白，你好好想想。他如果真的胆子很大，又为什么一定要拉上别人和他一起探险呢？",
            ["ContentJP"] = "落ち着いて、スノウ。本当に肝が据わってる人なら、最初から他人を巻き込もうとはしないと思うけど。",
            ["DialogueId"] = 51151070,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "800D246C",
            ["NextDialogue"] = 51151071,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                [2] = "200002:Angry01_End",
                },
            },
        [51151071] = {
            ["Camera"] = "-38.962891,173.353027,130.660156,0.000067,-14.045956,-26.231251,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是哦，这么说好像有些道理。小仆从，还是你观察仔细。那现在要怎么办，我们还进去吗？",
            ["ContentJP"] = "……あっ。言われてみれば確かに。鋭いね。じゃあどうする？このまま、私たちだけで入る？",
            ["DialogueId"] = 51151071,
            ["FacialId"] = {
                [1] = "200002:Think02",
                },
            ["GUID"] = "800D2496",
            ["NextDialogue"] = 51151072,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Think_Start",
                [2] = "100001:Talk02_End",
                },
            },
        [51151072] = {
            ["Camera"] = "90.658203,-126.199219,65.186523,0.000053,10.554213,85.36705,35.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "是不是需要展现一下我对华胥的了解了？华胥有句俗语，叫……来都来了。",
            ["ContentJP"] = "……ここでひとつ、多分華胥のことわざを紹介するよ──「来たからには、入るしかない」",
            ["DialogueId"] = 51151072,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D24C0",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51151073] = {
            ["Camera"] = "-54.057632,-5.761841,316.41864,0.00005,-11.218168,90.395935,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "仓库里怎么都是游荡的无由生……他们好像在守护着最里面的什么东西？",
            ["ContentJP"] = "な、なにこれ……ムユウセイだらけじゃん！？しかも、みんな奥のほうを囲ってる感じ……あそこ、なんか隠してるのかな？",
            ["DialogueId"] = 51151073,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "800D24EA",
            ["NextDialogue"] = 51151074,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:PointF_Start",
                [2] = "100001:Think_Start",
                },
            },
        [51151074] = {
            ["Camera"] = "-65.365799,-156.657349,145.755508,0.000201,-8.416945,79.202469,15.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "地上的痕迹，嗅嗅……香香的，好像是香料耶？怎么洒出来了，也是无由生捣的鬼吗？",
            ["ContentJP"] = "ん？この床の跡……クンクン……いい匂い。香辛料だ！でもなんでこんなとこに……まさかムユウセイの仕業？",
            ["DialogueId"] = 51151074,
            ["FacialId"] = {
                [1] = "200002:Curious",
                },
            ["GUID"] = "800D2514",
            ["NextDialogue"] = 51151075,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:PointF_End",
                },
            },
        [51151075] = {
            ["Content"] = "看它们如此谨慎，想必被发现了会遭遇什么不好的事情吧，白，我们要谨慎前进了。",
            ["ContentJP"] = "この状況だと、あいつらに見つかったらヤバいかも……スノウ、慎重に進もう。",
            ["DialogueId"] = 51151075,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "800D253E",
            ["LookAt"] = {
                [1] = "100001:n(200002)",
                },
            ["SpeakNpcId"] = 100001,
            },
        [51151076] = {
            ["Content"] = "白，快蹲下来。",
            ["ContentJP"] = "スノウ、しゃがんで！",
            ["DialogueId"] = 51151076,
            ["GUID"] = "800D2568",
            ["SpeakNpcId"] = 100001,
            },
        [51151077] = {
            ["Content"] = "又是香料，看起来通向更深的地方，哦！前面也有好多无由生！",
            ["ContentJP"] = "また香辛料の跡……奥に続いてる！って、あっちにもムユウセイがいっぱいいるよっ！",
            ["DialogueId"] = 51151077,
            ["GUID"] = "800D2592",
            ["SpeakNpcId"] = 200002,
            },
        [51151078] = {
            ["Content"] = "这只无由生怎么绕来绕去的……要不趁它不注意，咱们一鼓作气冲过去？",
            ["ContentJP"] = "あの子、ずっと同じとこぐるぐる回ってない？いまのうちに、一気に駆け抜けちゃう！？どうする！？",
            ["DialogueId"] = 51151078,
            ["GUID"] = "800D25BC",
            ["SpeakNpcId"] = 200002,
            },
        [51151079] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（仓库的尽头，香料箱上，一只魔灵正把头埋在盒子里，忘情地吸着香料……）",
            ["ContentJP"] = "倉庫の奥には香辛料の箱に頭を突っ込み、夢中で香りを吸い込んでいるジェネモンの姿が！",
            ["DialogueId"] = 51151079,
            ["GUID"] = "800D25E6",
            ["NextDialogue"] = 51151080,
            },
        [51151080] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "哼哼……可算被我们抓到了，快束手就擒吧，你这小贼！",
            ["ContentJP"] = "ふっふっふ～、ついに見つけたわよ！観念しなさい、泥棒め！",
            ["DialogueId"] = 51151080,
            ["FacialId"] = {
                [1] = "200002:Confident02",
                },
            ["GUID"] = "800D2610",
            ["LookAt"] = {
                [1] = "200002:n(700377)",
