        [51151081] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾？",
            ["ContentJP"] = "ニャ、ンニャ？！",
            ["DialogueId"] = 51151081,
            ["GUID"] = "800D263A",
            ["NextDialogue"] = 51151125,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151082] = {
            ["Content"] = "灵神大人，哼生这便来为你护驾！何方鼠贼，瞒天过海只为靠近我们灵神大人！",
            ["ContentJP"] = "霊神さまーっ！アショウが参りましたぞ！この者ども、なんと霊神さまを欺いてまで近づこうとはっ！",
            ["DialogueId"] = 51151082,
            ["GUID"] = "800D2664",
            ["NextDialogue"] = 51151083,
            ["Scripts"] = "PARA{\
SetVisibility{ActorId{700375},Visibility{\"Show\"}},\
SetVisibility{ActorId{700376},Visibility{\"Show\"}}\
}",
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Born",
                [2] = "700375:Wuyou_Born",
                },
            },
        [51151083] = {
            ["Content"] = "哈生也来助你！",
            ["ContentJP"] = "ウンショウも参戦いたしますっ！",
            ["DialogueId"] = 51151083,
            ["GUID"] = "800D268E",
            ["NextDialogue"] = 51151084,
            ["SpeakNpcId"] = 700376,
            },
        [51151084] = {
            ["Content"] = "啾啾啾~~~",
            ["ContentJP"] = "ニャ、ンニャ！",
            ["DialogueId"] = 51151084,
            ["GUID"] = "800D26B8",
            ["NextDialogue"] = 51151126,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "200002:Confident_End",
                },
            },
        [51151085] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不对不对，这分明是魔灵呀？怎么变成灵神大人了？",
            ["ContentJP"] = "ちょ、ちょっと待って！これ、どう見てもただのジェネモンでしょ？ いつから霊神さまになったのよ？",
            ["DialogueId"] = 51151085,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800D26E2",
            ["NextDialogue"] = 51151086,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry02_Start",
                },
            },
        [51151086] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "恶徒休要胡言，感受到这空气之中飘散的狂风了吗？这就是灵神大人的威力！",
            ["ContentJP"] = "黙れい下郎！この空気に満ちる風の気配が感じられぬか？これぞ霊神さまのご威光であらせられる！",
            ["DialogueId"] = 51151086,
            ["GUID"] = "800D270C",
            ["NextDialogue"] = 51151087,
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "200002:Angry02_End",
                [2] = "700375:Wuyou_Agree",
                },
            },
        [51151087] = {
            ["Content"] = "（的确有些凉风在你的脖颈间转圈，你只觉得有点痒，忍不住咳嗽了一声。）",
            ["ContentJP"] = "確かに……首元にヒュッと冷たい風が……くすぐったくて、思わず咳き込んでしまう。",
            ["DialogueId"] = 51151087,
            ["GUID"] = "800D2736",
            ["NextDialogue"] = 51151088,
            },
        [51151088] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "什么嘛，分明只是一只会些风魔法的魔灵罢了。快老实交代，你们为什么要占据别人的仓库，还让这里传出闹鬼的传言？",
            ["ContentJP"] = "いやいや、それただの風魔法でしょ？さてはあんた、香料目当てにこの倉庫を乗っ取って、おまけに幽霊騒ぎまで起こしてたでしょ？",
            ["DialogueId"] = 51151088,
            ["FacialId"] = {
                [1] = "200002:Guilty",
                },
            ["GUID"] = "800D2760",
            ["NextDialogue"] = 51151089,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_Start",
                },
            },
        [51151089] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾啾！吖~吖吖！",
            ["ContentJP"] = "ニャ、ンニャ、チュー！",
            ["DialogueId"] = 51151089,
            ["FacialId"] = {
                [1] = "200002:None",
                },
            ["GUID"] = "800D278A",
            ["NextDialogue"] = 51151127,
            ["Scripts"] = "SEQ{\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_End",
                },
            },
        [51151090] = {
            ["Content"] = "灵神大人说，这里已经被它占领了，请你们速速离去，不然就别怪我们不客气了！",
            ["ContentJP"] = "霊神さま曰く「ここは我が香りの楽園、気に入ったから住む！邪魔すんな！」だ！",
            ["DialogueId"] = 51151090,
            ["GUID"] = "800D27B4",
            ["NextDialogue"] = 51151091,
            ["SpeakNpcId"] = 700376,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Disagree",
                },
            },
        [51151091] = {
            ["Camera"] = "23.355988,-69.482788,172.744568,0.000006,-14.788239,163.1539,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不客气……你确定吗？",
            ["ContentJP"] = "ふむ……邪魔すんな……？本気で言ってる？",
            ["DialogueId"] = 51151091,
            ["FacialId"] = {
                [1] = "100001:Ahaha02",
                },
            ["GUID"] = "800D27DE",
            ["NextDialogue"] = 51151092,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_Start",
                },
            },
        [51151092] = {
            ["Content"] = "（你看了一眼自己腰间的武器……）",
            ["ContentJP"] = "腰の武器にそっと手をかける……",
            ["DialogueId"] = 51151092,
            ["GUID"] = "800D2808",
            ["NextDialogue"] = 51151093,
            },
        [51151093] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吖吖……",
            ["ContentJP"] = "ンニャ…ニャ",
            ["DialogueId"] = 51151093,
            ["GUID"] = "800D2832",
            ["NextDialogue"] = 51151128,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_End",
                },
            },
        [51151094] = {
            ["Content"] = "灵神大人？此话怎讲？你为何让我们退下，不要招惹他们？",
            ["ContentJP"] = "れ、霊神さまっ！？なぜ下がるのです！？我らに退けというのですか？",
            ["DialogueId"] = 51151094,
            ["GUID"] = "800D285C",
            ["NextDialogue"] = 51151095,
            ["SpeakNpcId"] = 700375,
            },
        [51151095] = {
            ["Content"] = "莫非……这两位是比灵神大人还要强大的存在？是我哈生有眼不识泰山了？",
            ["ContentJP"] = "ま、まさか……このお二人、霊神さまよりお強いお方！？おお、なんたる不覚……！",
            ["DialogueId"] = 51151095,
            ["GUID"] = "800D2886",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 700376,
            },
        [51151096] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["DialogueId"] = 51151096,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 0.5,
            ["FacialId"] = {
                [1] = "100001:None",
                [2] = "200002:None",
                },
            ["FinalDialogueId"] = 51151107,
            ["GUID"] = "800D28B0",
            ["NextOptions"] = {
                [1] = 51151097,
                [2] = 51151101,
                [3] = 51151105,
                },
            },
        [51151097] = {
            ["Content"] = "你为什么会出现在华胥？",
            ["ContentJP"] = "そもそも、なんで華胥にジェネモンが？",
            ["DialogueId"] = 51151097,
            ["GUID"] = "800D28DA",
            ["NextDialogue"] = 51151098,
            },
        [51151098] = {
            ["Content"] = "啾啾~啾~~~",
            ["ContentJP"] = "チュ、チュッッ…。",
            ["DialogueId"] = 51151098,
            ["GUID"] = "800D2904",
            ["NextDialogue"] = 51151099,
            ["Scripts"] = "SEQ{\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 700377,
            },
        [51151099] = {
            ["Content"] = "灵神大人说，它在原来的地方闻到了很香的味道，十分喜欢，就跟着味道一路来到了船上……",
            ["ContentJP"] = "「どこからかいい匂いがしてきたから、ふら～っと船に乗ってたどり着いちゃった」とのことです！",
            ["DialogueId"] = 51151099,
            ["GUID"] = "800D292E",
            ["NextDialogue"] = 51151100,
            ["SpeakNpcId"] = 700375,
            },
        [51151100] = {
            ["Content"] = "所以这家伙是跟着织星客的船偷渡来的华胥！",
            ["ContentJP"] = "つまり、星織人の船にこっそり乗り込んで密航してきたってことね！",
            ["DialogueId"] = 51151100,
            ["FacialId"] = {
                [1] = "200002:Doubt01",
                },
            ["GUID"] = "800D2958",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 200002,
            },
        [51151101] = {
            ["Content"] = "那为什么要霸占这里？",
            ["ContentJP"] = "それでどうして倉庫を占拠してるの{性别:か|}？",
            ["DialogueId"] = 51151101,
            ["GUID"] = "800D2982",
            ["NextDialogue"] = 51151102,
            },
        [51151102] = {
            ["Content"] = "吖吖……啾！啾啾~",
            ["ContentJP"] = "……ンニャニャ！",
            ["DialogueId"] = 51151102,
            ["GUID"] = "800D29AC",
            ["NextDialogue"] = 51151103,
            ["Scripts"] = "SEQ{\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}},\
PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}\
}",
            ["SpeakNpcId"] = 700377,
            },
        [51151103] = {
            ["Content"] = "灵神大人说，这里有好闻的香料，没有不认识的面孔，没有凶巴巴的魔灵猎人，还有好兄弟无由生相随保护。",
            ["ContentJP"] = "「ここは香りがいっぱいで誰も来ないし、怖いジェネモンハンターもいない。ムユウセイたちも一緒にいてくれるし、居心地バツグン！」とのことです！",
            ["DialogueId"] = 51151103,
            ["GUID"] = "800D29D6",
            ["NextDialogue"] = 51151104,
            ["SpeakNpcId"] = 700376,
            },
        [51151104] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊~所以这里所谓的闹鬼，只是你想占据这里不让普通人打扰，故意和无由生一起闹出来的。",
            ["ContentJP"] = "あ～なるほどね！騒ぎを起こして人を遠ざけて、ここを自分の縄張りにしたかっただけってわけだ！",
            ["DialogueId"] = 51151104,
            ["FacialId"] = {
                [1] = "200002:Confident01",
                },
            ["GUID"] = "800D2A00",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Confident_Start",
                },
            },
        [51151105] = {
            ["Content"] = "（闻闻香料。）",
            ["ContentJP"] = "香辛料の匂いを嗅ぐ。",
            ["DialogueId"] = 51151105,
            ["GUID"] = "800D2A2A",
            ["NextDialogue"] = 51151106,
            },
        [51151106] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗅嗅……这香料和咱们投喂魔灵用的罐罐味道好像呀！难道这就是魔灵赖在这里的原因？",
            ["ContentJP"] = "うーん……この香り、ジェネモンのエサにそっくりなんだけど！？まさか、これが目当て……？",
            ["DialogueId"] = 51151106,
            ["FacialId"] = {
                [1] = "200002:Think02",
                },
            ["GUID"] = "800D2A54",
            ["NextDialogue"] = 51151096,
            ["SpeakNpcId"] = 200002,
            },
        [51151107] = {
            ["Camera"] = "23.355988,-69.482788,172.744568,0.000006,-14.788239,163.1539,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你们闹鬼的事情已经被百年春的人知道了，怕是再过几天就有人来抓你们了。",
            ["ContentJP"] = "でもね、この件はもう百年春の人たちの耳にも入ってる。そう遠くないうちに本格的に捕まえに来るよ？",
            ["DialogueId"] = 51151107,
            ["FacialId"] = {
                [1] = "100001:Angry01",
                [2] = "200002:None",
                },
            ["GUID"] = "800D2A7E",
            ["NextDialogue"] = 51151108,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_Start",
                },
            },
        [51151108] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾……吖……",
            ["ContentJP"] = "ニョ…。",
            ["DialogueId"] = 51151108,
            ["FacialId"] = {
                [1] = "100001:None",
                },
            ["GUID"] = "800D2AA8",
            ["NextDialogue"] = 51151109,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_End",
                },
            },
        [51151109] = {
            ["Content"] = "什么？灵神大人，你让我们离开，你一个神来承担？",
            ["ContentJP"] = "な、なんと！？霊神さま、あなたお一人で責任を背負うと……？",
            ["DialogueId"] = 51151109,
            ["GUID"] = "800D2AD2",
            ["NextDialogue"] = 51151110,
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "700375:Wuyou_Disagree",
                },
            },
        [51151110] = {
            ["Content"] = "不要啊，我们和灵神大人同生共死！哦不对……好像我们已经死掉了……",
            ["ContentJP"] = "や、やめてください！ぼくらは……霊神さまと共に……あっ、いやもう死んでたんだった！",
            ["DialogueId"] = 51151110,
            ["GUID"] = "800D2AFC",
            ["NextDialogue"] = 51151111,
            ["SpeakNpcId"] = 700376,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Disagree",
                },
            },
        [51151111] = {
            ["Camera"] = "172.276642,-106.706421,224.133514,0.000011,-22.388477,154.355042,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我看你们就别在这里演什么无由生魔灵情深的戏码了，都收拾收拾快点离开这里吧。",
            ["ContentJP"] = "感動の別れっぽくなってるけど、いいからさっさと荷物まとめて出てってちょうだい！",
            ["DialogueId"] = 51151111,
            ["FacialId"] = {
                [1] = "200002:Syouganai01",
                },
            ["GUID"] = "800D2B26",
            ["NextDialogue"] = 51151112,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_Start",
                },
            },
        [51151112] = {
            ["Camera"] = "-595.896667,244.201172,274.973206,0.000002,-17.388731,-24.245804,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啾~",
            ["ContentJP"] = "チュ！",
            ["DialogueId"] = 51151112,
            ["GUID"] = "800D2B50",
            ["NextDialogue"] = 51151113,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_hello\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            ["TalkActionId"] = {
                [1] = "200002:Helpless01_End",
                },
            },
        [51151113] = {
            ["Content"] = "至于你……",
            ["ContentJP"] = "君にいたっては……",
            ["DialogueId"] = 51151113,
            ["FacialId"] = {
                [1] = "200002:Angry01",
                },
            ["GUID"] = "800D2B7A",
            ["NextDialogue"] = 51151114,
            ["SpeakNpcId"] = 200002,
            },
        [51151114] = {
            ["Camera"] = "23.355988,-69.482788,172.744568,0.000006,-14.788239,163.1539,30.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "给你两个选择，一是继续在华胥游荡，直到你混到一艘船上回到你的故乡，另一个选择是……",
            ["ContentJP"] = "このまま華胥で放浪を続けるか、いつかまた船に紛れて帰るか。選んで――",
            ["DialogueId"] = 51151114,
            ["FacialId"] = {
                [1] = "100001:Think01",
                },
            ["GUID"] = "800D2BA4",
            ["NextDialogue"] = 51151115,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03ToTalkL_Start",
                },
            },
        [51151115] = {
            ["Content"] = "我这也有妙妙罐罐，和我走，怎么样？",
            ["ContentJP"] = "そういえば、うまうま缶詰持ってるんだよね。一緒に来ない？",
            ["DialogueId"] = 51151115,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800D2BCE",
            ["NextDialogue"] = 51151116,
            ["SpeakNpcId"] = 100001,
            },
        [51151116] = {
            ["Camera"] = "-257.016357,106.369873,179.233536,0.000001,-9.588553,-21.443916,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "吖……",
            ["ContentJP"] = "チュ…。",
            ["DialogueId"] = 51151116,
            ["GUID"] = "800D2BF8",
            ["NextDialogue"] = 51151117,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151117] = {
            ["Content"] = "吖！",
            ["ContentJP"] = "チュチュチュ！",
            ["DialogueId"] = 51151117,
            ["GUID"] = "800D2C22",
            ["NextDialogue"] = 51151118,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_happy\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151118] = {
            ["Content"] = "看起来它同意跟我们走啦~",
            ["ContentJP"] = "決まりだね！この子、ついてくるってさ。",
            ["DialogueId"] = 51151118,
            ["FacialId"] = {
                [1] = "200002:Smile01",
                },
            ["GUID"] = "800D2C4C",
            ["NextDialogue"] = 51151119,
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Excited01_Start",
                },
            ["TurnTo"] = {
                [1] = "200002:n(100001)",
                },
            },
        [51151119] = {
            ["Content"] = "灵神大人，相逢本是一场缘，若是今日你选择离开，我们自然也不宜久留，只求大人记得我们，有空再来找我们说说话！",
            ["ContentJP"] = "霊神さま、出会いは奇縁……旅立つのは寂しいけれど、我らもそろそろお暇いたしましょう。どうか、我らのこと……忘れないでくだされ！",
            ["DialogueId"] = 51151119,
            ["GUID"] = "800D2C76",
            ["NextDialogue"] = 51151120,
            ["SpeakNpcId"] = 700375,
            ["TalkActionId"] = {
                [1] = "700375:Wuyou_Agree",
                },
            },
        [51151120] = {
            ["Content"] = "大人……呜呜……可千万不要忘了我们啊，如果没有你，我们都不知道该和谁聊天了……",
            ["ContentJP"] = "ううっ、霊神さま……せめてたまに話しかけてくださいね……さもないと、誰とも話せなくて寂しくて……",
            ["DialogueId"] = 51151120,
            ["GUID"] = "800D2CA0",
            ["NextDialogue"] = 51151121,
            ["SpeakNpcId"] = 700376,
            ["TalkActionId"] = {
                [1] = "700376:Wuyou_Disagree",
                },
            },
        [51151121] = {
            ["Content"] = "吖吖……",
            ["ContentJP"] = "ンニャニャ……",
            ["DialogueId"] = 51151121,
            ["GUID"] = "800D2CCA",
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/vo_upset\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 700377,
            },
        [51151122] = {
            ["Content"] = "（你就这么看着一个魔灵和两个无由生相拥而泣，互相把不存在的眼泪抹在对方身上，等了好久，直到将哼哈二将送至门外……）",
            ["ContentJP"] = "そんな3人がハグしながら見えない涙をぬぐい合い、あなたは黙ってその別れを見届けた。やがてアショウとウンショウを見送ると――",
            ["DialogueId"] = 51151122,
            ["GUID"] = "800D2CF4",
            },
        [51151123] = {
            ["Content"] = "呼~可算把两位无由生送走了，想不到这些无由生还挺有情有义的嘛……接下来就轮到……",
            ["ContentJP"] = "ふぅ～、やっと送り出せたね……意外と情に厚い連中だったなぁ。",
            ["DialogueId"] = 51151123,
            ["GUID"] = "800D2D1E",
            ["NextDialogue"] = 51151124,
            ["SpeakNpcId"] = 200002,
            },
        [51151124] = {
            ["Content"] = "小仆从，你带妙妙罐罐了吗？试试投喂这只魔灵吧！",
            ["ContentJP"] = "さて、次は……この子に缶詰あげてみよ、我が下僕よ！",
            ["DialogueId"] = 51151124,
            ["GUID"] = "800D2D48",
            ["SpeakNpcId"] = 200002,
            },
        [51151125] = {
            ["Content"] = "（这只魔灵似乎对你们的到来看起来有些疑惑。）",
            ["ContentJP"] = "このジェネモンは、あなたたちが来たことに少し戸惑っているようだ。",
            ["DialogueId"] = 51151125,
            ["GUID"] = "800D263B",
            ["NextDialogue"] = 51151082,
            },
        [51151126] = {
            ["Content"] = "（这只魔灵明显意识到了你们的来意，但因有无由生相助而显得十分得意。）",
            ["ContentJP"] = "このジェネモンはあなたたちの目的を察したようだが、ムユウセイの助けがあるせいか、やけに得意げだ。",
            ["DialogueId"] = 51151126,
            ["GUID"] = "800D26B9",
            ["NextDialogue"] = 51151085,
            },
        [51151127] = {
            ["Content"] = "（咿咿呀呀说了一大堆，完全听不懂……）",
            ["ContentJP"] = "延々と何かをしゃべっているが、まったく聞き取れない……",
            ["DialogueId"] = 51151127,
            ["GUID"] = "800D278B",
            ["NextDialogue"] = 51151090,
            },
        [51151128] = {
            ["Content"] = "(它似乎有些害怕？）",
            ["ContentJP"] = "少し怖がっているようだ？",
            ["DialogueId"] = 51151128,
            ["GUID"] = "800D2833",
            ["NextDialogue"] = 51151094,
            },
        [51151129] = {
            ["Content"] = "是说百年春角落那间仓库吗？那里不是早就租给天岚先生做供货仓库了吗？为何现在过来提起？",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>の角の、あの古い倉庫のこと？あそこならテンランさんに貸しているはずだが……どうかしたの？",
            ["DialogueId"] = 51151129,
            ["GUID"] = "800D2D49",
            ["SpeakNpcId"] = 700370,
            },
        [51151201] = {
            ["Camera"] = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是白魔王大人和她忠诚的有龙氏随从！你们来找我玩啦！",
            ["ContentJP"] = "魔王さまと、その忠実なる龍の民の下僕じゃない！ ふたりとも、遊びに来てくれたのね！",
            ["DialogueId"] = 51151201,
            ["GUID"] = "800D39EA",
            ["NextDialogue"] = 51151202,
            ["Scripts"] = "SEQ{\
PARA{\
LookAt{LookAtDescription{\"200002:n(900012)\"}}, \
LookAt{LookAtDescription{\"100001:n(900012)\"}},\
PlayAnimation{ActorId{900012},AnimationId{\"Talk02_Start\"}},\
LookAt{LookAtDescription{\"900012:n(200002)\"}}\
},\
LookAt{_delay{1},LookAtDescription{\"900012:n(100001)\"}}\
}",
            ["SpeakNpcId"] = 900012,
            },
        [51151202] = {
            ["Content"] = "“她忠诚的有龙氏随从”不配拥有自己的姓名吗？",
            ["ContentJP"] = "「忠実なる龍の民の下僕」って……名前を持つ資格もないの{性别:か|}？",
            ["DialogueId"] = 51151202,
            ["GUID"] = "800D3A14",
            ["NextDialogue"] = 51151203,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51151203] = {
            ["Content"] = "当然是开玩笑的啦，{nickname}也是锦鲤皎皎的好朋友！你的角红红的一只，像枫叶，很特别。我很羡慕这样的角呢。",
            ["ContentJP"] = "もう、冗談に決まってるでしょ。{nickname}も、ニシキの大事なお友だちだよ！その角、片方だけ赤くてね、まるで紅葉みたいでとっても素敵だよ。",
            ["DialogueId"] = 51151203,
            ["FacialId"] = {
                [1] = "900012:Smile02",
                },
            ["GUID"] = "800D3A3E",
            ["NextDialogue"] = 51151204,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_End",
                [2] = "900012:Talk02_End",
                },
            },
        [51151204] = {
            ["Camera"] = "368.707031,55.0,181.27832,0.0001,-12.598782,-171.164566,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说起来，锦鲤皎皎，这个高高的、装满小球的机器是什么？",
            ["ContentJP"] = "ところで、ニシキ。この高くて、小さな玉がいっぱい入ってる機械って何？",
            ["DialogueId"] = 51151204,
            ["FacialId"] = {
                [1] = "900012:None",
                },
            ["FinalCamera"] = "368.707031,55.0,181.27832,0.000102,5.401252,-149.163544,25.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "800D3A68",
            ["NextDialogue"] = 51151205,
            ["SpeakNpcId"] = 200002,
            ["ToFinalCameraBlendTime"] = 1,
            },
        [51151205] = {
            ["Camera"] = "277.509766,14.723633,155.932617,0.000082,-10.198612,-178.573135,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不愧是火眼金睛的白魔王大人，一眼就能看出好东西！这可是本皎皎做生意的独家秘诀。",
            ["ContentJP"] = "さすが魔王さま、良い物は一目で見抜いちゃうんだから！これはね、ニシキが商売のために考えたとっておきの秘策なんだよ。",
            ["DialogueId"] = 51151205,
            ["FacialId"] = {
                [1] = "900012:Confident01",
                },
            ["GUID"] = "800D3A92",
            ["LookAt"] = {
                [1] = "900012:n(200002)",
                },
            ["NextDialogue"] = 51151206,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_Start",
                },
            },
        [51151206] = {
            ["Content"] = "我特意找一个机枢派的叫公、公什么的师傅定制了这套福运蛋机。只要往里面投入代币，它就会给你随机吐小奖品出来！",
            ["ContentJP"] = "わざわざ機枢派の……こう、公なんとかって職人さんに頼み込んで、特注で作ってもらった「ラッキーエッグガチャ」なの！代金を投入すると、ランダムで小さな景品をポンッて出してくれるんだ！",
            ["DialogueId"] = 51151206,
            ["GUID"] = "800D3ABC",
            ["NextDialogue"] = 51151207,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_End",
                },
            },
        [51151207] = {
            ["Camera"] = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "随机性才是挣钱的诀窍——这是本皎皎某天向白龙神君大人祈祷时，一下子福至心灵想出来的。怎么样，是不是天才般的想法？",
            ["ContentJP"] = "「ランダム性こそ儲けの秘訣」——これは、ある日わたしが白龍さまにお祈りしてた時、ピカーン！ってひらめいた天啓なの。どう？ なかなか天才的でしょ？",
            ["DialogueId"] = 51151207,
            ["GUID"] = "800D3AE6",
            ["LookAt"] = {
                [1] = "900012:n(900012)",
                },
            ["NextDialogue"] = 51151208,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_Start",
                },
            },
        [51151208] = {
            ["Camera"] = "-57.599609,-59.527832,146.118164,0.000087,-5.198607,48.427074,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那你的生意好吗？",
            ["ContentJP"] = "それで……商売は順調なの{性别:か|}？",
            ["DialogueId"] = 51151208,
            ["GUID"] = "800D3B10",
            ["NextDialogue"] = 51151209,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_End",
                [2] = "100001:Talk02_Start",
                },
            },
        [51151209] = {
            ["Camera"] = "83.419922,-2.439453,100.824219,0.000082,-6.798552,-173.972046,25.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……呜，一般。",
            ["ContentJP"] = "……うぅ、まあ、普通？",
            ["DialogueId"] = 51151209,
            ["FacialId"] = {
                [1] = "900012:Syouganai01",
                },
            ["GUID"] = "800D3B3A",
            ["NextDialogue"] = 51151210,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:DisagreeHead",
                [2] = "100001:Talk02_End",
                },
            },
        [51151210] = {
            ["Content"] = "因为这个想法太新潮了，所以到现在连机器的本钱还没挣回来。大概这就是高手常常落寞吧。",
            ["ContentJP"] = "アイデアが斬新すぎちゃって、いまだに機械代すら取り返せてないの。これぞ「高みに立つ者は孤独」ってやつだよね、多分。",
            ["DialogueId"] = 51151210,
            ["FacialId"] = {
                [1] = "900012:Sad03",
                },
            ["GUID"] = "800D3B64",
            ["NextDialogue"] = 51151211,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Shy03_Start",
                },
            },
        [51151211] = {
            ["Content"] = "如果你们在烟津渡捡到什么太虚符文呀、齿轮呀一类的玩意儿，可以用它来抽福运蛋机。",
            ["ContentJP"] = "もし<Default note=\"text:えんしんと\">煙津渡</>で<Default note=\"text:たいきょふもん\">太虚符文</>とか、歯車みたいな変わったものを拾ったら、ラッキーエッグガチャのコイン代わりに使えるよ！",
            ["DialogueId"] = 51151211,
            ["FacialId"] = {
                [1] = "900012:None",
                },
            ["GUID"] = "800D3B8E",
            ["NextDialogue"] = 51151212,
            ["SpeakNpcId"] = 900012,
            },
        [51151212] = {
            ["Content"] = "这些福运蛋里的小垃圾……咳咳，不对，是小奖品！你们就不客气地拿走，当做是本皎皎的一片心意吧！",
            ["ContentJP"] = "ガチャに入ってるガラクタ……じゃなくて、小さな景品！遠慮しないで持っていってね。ニシキのささやかな気持ちなんだから！",
            ["DialogueId"] = 51151212,
            ["GUID"] = "800D3BB8",
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Shy03_End",
                },
            },
        [51151301] = {
            ["Content"] = "是{nickname}和白魔王大人，你们来找我玩啦！今天的福运蛋又上新了新款式，要不要来扭一发试试？",
            ["ContentJP"] = "あっ、{nickname}と魔王さま！また遊びに来てくれたんだね！今日のガチャは新しいラインナップが入ってるよ、ひとつ回してみる？",
            ["DialogueId"] = 51151301,
            ["GUID"] = "800D4A52",
            ["NextOptions"] = {
                [1] = 51151302,
                [2] = 51151307,
                },
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Explain01_Start",
                },
            },
        [51151302] = {
            ["Content"] = "聊聊锦鲤皎皎的梦想。",
            ["ContentJP"] = "ニシキの夢について話す",
            ["DialogueId"] = 51151302,
            ["GUID"] = "800D4A7C",
            ["NextDialogue"] = 51151303,
            },
        [51151303] = {
            ["Content"] = "我呀，以前只是个普普通通的皎皎，每天最大的梦想不过是怎么从那些抠门织星客手中多抢下来几个单子，直到白魔王大人的出现改变了这一切——",
            ["ContentJP"] = "わたしね、昔はただの普通のルーナ族でさ、毎日「どうやってケチな星織人からもう少し仕事をもぎ取るか」ばかり考えてたの。でも魔王さまが現れて、全部変わったんだよ！",
            ["DialogueId"] = 51151303,
            ["GUID"] = "800D4AA6",
            ["NextDialogue"] = 51151304,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Explain01_End",
                },
            },
        [51151304] = {
            ["Content"] = "现在的我已经不再是昨日的我了！我要成为青史留名的织星客，带领皎皎一族走向辉煌！",
            ["ContentJP"] = "今のわたしは、もう昔のわたしじゃない！いつか歴史に名前を残す星織人になって、ルーナ族を大復興させるの！",
            ["DialogueId"] = 51151304,
            ["GUID"] = "800D4AD0",
            ["NextDialogue"] = 51151305,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_Start",
                },
            },
        [51151305] = {
            ["Content"] = "以后白魔王大人的宫殿旁边，一定也有本皎皎豪华商铺的一席之地！",
            ["ContentJP"] = "魔王さまのお城のとなりにはね、絶対にニシキの豪華ショップが建つんだ。",
            ["DialogueId"] = 51151305,
            ["GUID"] = "800D4AFA",
            ["NextDialogue"] = 51151306,
            ["SpeakNpcId"] = 900012,
            },
        [51151306] = {
            ["Content"] = "这是约定和梦想！你们就等着瞧吧，我一定会做到的！",
            ["ContentJP"] = "これは約束で、夢なの！ 絶対に叶えるよ、見てて！",
            ["DialogueId"] = 51151306,
            ["GUID"] = "800D4B24",
            ["NextDialogue"] = 51151313,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited02_End",
                },
            },
        [51151307] = {
            ["Content"] = "聊聊锦鲤皎皎的生意经。",
            ["ContentJP"] = "ニシキの商売術について話す",
            ["DialogueId"] = 51151307,
            ["GUID"] = "800D4B4E",
            ["NextDialogue"] = 51151308,
            },
        [51151308] = {
            ["Content"] = "听我说听我说，我最近有一个体悟……福运蛋之所以没什么人来玩，除了它太新潮之外，奖品不够吸引人也是一大痛点！",
            ["ContentJP"] = "聞いて聞いて！ 最近ね、ちょっと気づいたことがあって……ラッキーエッグがあんまり遊ばれないのって、新しすぎるのもあるけど、景品の魅力が足りないのが大問題なんだよ！",
            ["DialogueId"] = 51151308,
            ["GUID"] = "800D4B78",
            ["NextDialogue"] = 51151309,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Explain01_End",
                },
            },
        [51151309] = {
            ["Content"] = "华胥有些织星客和悬衡派谈下了授权，专门售卖限定版香囊，生意可红火啦。这给了本皎皎灵感！",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>じゃ、<Default note=\"text:ほしおりびと\">星織人</>の中には<Default note=\"text:けんこうは\">懸衡派</>と契約して限定香袋を売っている人もいてさ、それがまた大繁盛なの。それで、ニシキもひらめいちゃった！",
            ["DialogueId"] = 51151309,
            ["GUID"] = "800D4BA2",
            ["NextDialogue"] = 51151310,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Talk02_Start",
                },
            },
        [51151310] = {
            ["Content"] = "说到足够吸引人的奖品，那自然得是我们人见人爱的皎皎一族！",
            ["ContentJP"] = "みんなに愛されてるルーナ族を、景品にすればいいんじゃない？って！",
            ["DialogueId"] = 51151310,
            ["GUID"] = "800D4BCC",
            ["NextDialogue"] = 51151311,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Talk02_End",
                },
            },
        }
  end },
  { MinKey = 51151311, MaxKey = 51155215, Loader = function()
      return {
        [51151311] = {
            ["Content"] = "{nickname}，你说你说，我去订制一款皎皎联名奖品，将来自海伯利亚的魔王大人作为压轴隐藏款，是不是一定能大卖特卖？",
            ["ContentJP"] = "ねえ、{nickname}、聞いて聞いて！ルーナ族の限定コラボ景品を作って、最後のシークレットに「ヒュペリアから来た魔王さま」を入れるの。……これ、絶対バカ売れすると思わない！？",
            ["DialogueId"] = 51151311,
            ["GUID"] = "800D4BF6",
            ["NextDialogue"] = 51151312,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_Start",
                },
            },
        [51151312] = {
            ["Content"] = "嘿嘿，到时候一定会数钱数到手软！",
            ["ContentJP"] = "えへへ、その時はもうお金数えすぎて指つっちゃうかも〜！",
            ["DialogueId"] = 51151312,
            ["GUID"] = "800D4C20",
            ["NextDialogue"] = 51151313,
            ["SpeakNpcId"] = 900012,
            ["TalkActionId"] = {
                [1] = "900012:Excited01_End",
                },
            },
        [51151313] = {
            ["Content"] = "你们忙你们的去吧！在努力实现梦想这方面，本皎皎也不能输！",
            ["ContentJP"] = "さ、ふたりとも用事に戻っていいよ！夢を叶えるための努力、ニシキだって負けてられないんだからね！",
            ["DialogueId"] = 51151313,
            ["GUID"] = "800D4C4A",
            ["SpeakNpcId"] = 900012,
            },
        [51151401] = {
            ["Content"] = "…………（蛋皎在板子上写下了“喜欢您来”。）",
            ["ContentJP"] = "…………（ルーナエッグは板に「来てくれてうれしいです」と書いた。）",
            ["DialogueId"] = 51151401,
            ["GUID"] = "800D5ABA",
            ["NextOptions"] = {
                [1] = 51151402,
                [2] = 51151403,
                },
            ["SpeakNpcId"] = 900011,
            },
        [51151402] = {
            ["Content"] = "总觉得你有点眼熟……",
            ["ContentJP"] = "何となく、どこかで見たことがあるような……",
            ["DialogueId"] = 51151402,
            ["GUID"] = "800D5AE4",
            ["NextDialogue"] = 51151404,
            },
        [51151403] = {
            ["Content"] = "我们是不是在一个叫冰湖城的地方见过。",
            ["ContentJP"] = "私たち、アイスレイク城って場所で会ったことがありませんでしたっけ。",
            ["DialogueId"] = 51151403,
            ["GUID"] = "800D5B0E",
            ["NextDialogue"] = 51151404,
            },
        [51151404] = {
            ["Content"] = "…………（没错！就是我！我有好多好多分身。不信的话，等你去了下一个城市，我会再变出来一个分身。）",
            ["ContentJP"] = "…………（そう、そのとおり！この前のもぜんぶボク！ボクには分身がたくさんいるんだ。信じられないなら、君が次の街に行ったとき、またひとり分身を出してみせるよ。）",
            ["DialogueId"] = 51151404,
            ["GUID"] = "800D5B38",
            ["NextOptions"] = {
                [1] = 51151405,
                [2] = 51151407,
                },
            ["SpeakNpcId"] = 900011,
            },
        [51151405] = {
            ["Content"] = "相信。",
            ["ContentJP"] = "信じる。",
            ["DialogueId"] = 51151405,
            ["GUID"] = "800D5B62",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51151406,
            },
        [51151406] = {
            ["Content"] = "会分身的蛋皎吗……真是不可思议的神奇生物啊。",
            ["ContentJP"] = "分身できるルーナエッグか……本当に不思議な生き物だね。",
            ["DialogueId"] = 51151406,
            ["GUID"] = "800D5B8C",
            ["NextOptions"] = {
                [1] = 51151412,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51151407] = {
            ["Content"] = "不相信。",
            ["ContentJP"] = "信じない。",
            ["DialogueId"] = 51151407,
            ["GUID"] = "800D5BB6",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51151408,
            },
        [51151408] = {
            ["Content"] = "你们就是钻进了蛋壳的不同皎皎吧，只是不知为何选了同样的蛋壳。",
            ["ContentJP"] = "君たちは、それぞれ別のルーナ族が卵の殻の中に潜り込んでいるだけで、たまたま同じ卵の殻を選んだだけなんじゃないか？",
            ["DialogueId"] = 51151408,
            ["GUID"] = "800D5BE0",
            ["NextDialogue"] = 51151409,
            ["SpeakNpcId"] = 100001,
            },
        [51151409] = {
            ["Content"] = "…………（哼哼，当然是因为，最高明的躲藏方式，就是藏在一群蛋皎之中！）",
            ["ContentJP"] = "…………（ふふん、もちろん一番賢い隠れ方は、たくさんのルーナエッグの中に紛れ込むことだからさ！）",
            ["DialogueId"] = 51151409,
            ["GUID"] = "800D5C0A",
            ["NextDialogue"] = 51151410,
            ["SpeakNpcId"] = 900011,
            },
        [51151410] = {
            ["Content"] = "…………（这样当一只蛋皎在玩骰子时赢了你，你想赢回来的时候，就找不到当时赢你的到底是哪只蛋皎了。）",
            ["ContentJP"] = "…………（そうしておけば、もしあるルーナエッグがサイコロ勝負で君に勝っても、君が負けを取り返そうとしたときには、そのとき勝ったのがどの蛋皎だったのか分からなくなっちゃうでしょ。）",
            ["DialogueId"] = 51151410,
            ["GUID"] = "800D5C34",
            ["NextDialogue"] = 51151411,
            ["SpeakNpcId"] = 900011,
            },
        [51151411] = {
            ["Content"] = "好像挺有道理的。",
            ["ContentJP"] = "言われてみれば、確かに一理あるね。",
            ["DialogueId"] = 51151411,
            ["GUID"] = "800D5C5E",
            ["NextOptions"] = {
                [1] = 51151412,
                },
            ["SpeakNpcId"] = 100001,
            },
        [51151412] = {
            ["Content"] = "那么，能打开蛋壳给我看看吗？",
            ["ContentJP"] = "じゃあ、その卵の殻を開けて見せてくれない？",
            ["DialogueId"] = 51151412,
            ["GUID"] = "800D5C88",
            ["NextDialogue"] = 51151413,
            },
        [51151413] = {
            ["Content"] = "…………！（不可以！蛋壳之下就是蛋壳，蛋壳之下还是蛋壳，绝对不是皎皎，绝对！）",
            ["ContentJP"] = "…………！（ダメ！殻の下にあるのは殻、その下にあるのもまた殻。ぜったいにルーナ族なんか入ってないから！本当に！）",
            ["DialogueId"] = 51151413,
            ["GUID"] = "800D5CB2",
            ["SpeakNpcId"] = 900011,
            },
        [51152002] = {
            ["Content"] = "诶？小仆从小仆从，这附近的风声好大哦，你听你听，呜呜呜呜呜的。",
            ["ContentJP"] = "えっ？我が下僕､この辺り、風の音がすごく大きいぞ。ほらほら、フウーフウー鳴ってるのだ。",
            ["DialogueId"] = 51152002,
            ["GUID"] = "800DBD54",
            ["SpeakNpcId"] = 701087,
            },
        [51152003] = {
            ["Content"] = "呜……呜……",
            ["ContentJP"] = "ふぅ……うう……",
            ["DialogueId"] = 51152003,
            ["GUID"] = "800DBD7E",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Zhongniannan",
            },
        [51152004] = {
            ["Content"] = "呜……别过来，不要逼我……不要逼我！",
            ["ContentJP"] = "うぅ……来るな！これ以上来たら、私は……私は！",
            ["DialogueId"] = 51152004,
            ["GUID"] = "800DBDA8",
            ["SpeakNpcName"] = "UI_CMNpc_Name_Zhongniannan",
            },
        [51152005] = {
            ["Content"] = "咦，不，不是风声，好像是有人在前面！我们快过去看看发生了什么吧。",
            ["ContentJP"] = "あれ、風の音じゃないみたいだぞ。前の方に誰かいるよ！何が起きたのか、早く見に行くのだ。",
            ["DialogueId"] = 51152005,
            ["GUID"] = "800DBDD2",
            ["SpeakNpcId"] = 701087,
            },
        [51152007] = {
            ["Content"] = "好，我们出发！",
            ["ContentJP"] = "よし、出発だ！",
            ["DialogueId"] = 51152007,
            ["GUID"] = "800DBE26",
            ["SpeakNpcId"] = 200002,
            },
        [51152008] = {
            ["Content"] = "呜哇，好多秽兽，看招看招！",
            ["ContentJP"] = "うわぁ、穢獣がいっぱい！くっらえー！",
            ["DialogueId"] = 51152008,
            ["GUID"] = "800DBE50",
            ["SpeakNpcId"] = 200002,
            },
        [51152009] = {
            ["Content"] = "好耶，马上就能把这群坏家伙打跑了。不过话说回来，你有没有觉得那个被困的家伙有点眼熟哇？",
            ["ContentJP"] = "やったぁ、あと少しで悪い奴らを追い払えるぞ。でも、あの囲まれてる人、なんだか見覚えがない？",
            ["DialogueId"] = 51152009,
            ["GUID"] = "800DBE7A",
            ["SpeakNpcId"] = 200002,
            },
        [51152010] = {
            ["Content"] = "先专注眼前的敌人吧。",
            ["ContentJP"] = "今は目の前の敵に集中しよう。",
            ["DialogueId"] = 51152010,
            ["GUID"] = "800DBEA4",
            ["SpeakNpcId"] = 100001,
            },
        [51152011] = {
            ["Camera"] = "643.927734,72.326172,238.735352,0.000106,-19.939514,-168.080322,35.0,472.956573,false,Manual,2.557317",
            ["Content"] = "呼……呼……",
            ["ContentJP"] = "はぁ……はぁ……",
            ["DialogueId"] = 51152011,
            ["FinalCamera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["GUID"] = "800DBECE",
            ["LookAt"] = {
                [1] = "200002:n(701088)",
                },
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Hurt01",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51152012] = {
            ["Camera"] = "421.720703,-66.143555,106.893555,0.00008,-8.94039,-173.895111,35.000008,197.80249,false,Manual,2.8",
            ["Content"] = "那些秽兽都被我们打跑啦，你的伤……",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>たちは全部追い払ったよ。お前、怪我は大丈夫か？",
            ["DialogueId"] = 51152012,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800DBEF8",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_Start",
                },
            ["TurnTo"] = {
                [1] = "701088:n(100001)",
                },
            },
        [51152013] = {
            ["Content"] = "发乎于心，现乎于行。若是动了兵戈，人心就会变质。无论这兵戈朝向的是友邻还是恶敌，性质都是相同的！终是逆了天意呀！",
            ["ContentJP"] = "兵を念ずれば、行にあらわる。一たび刃を振るえば、人心は濁る。その矛、友に向けようと、敵に向けようと、性は同じくして変わらず。これは天意に背く行為だ！",
            ["DialogueId"] = 51152013,
            ["GUID"] = "800DBF22",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'\
",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "200002:Shock03_End",
                },
            },
        [51152014] = {
            ["Content"] = "按照你的意思。我们应该在原地待着，什么都不做，束手就擒……是吗？",
            ["ContentJP"] = "つまり、何もせず、襲い来る敵に食われろ、と？",
            ["DialogueId"] = 51152014,
            ["GUID"] = "800DBF4C",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'",
            ["SpeakNpcName"] = "UI_Npc_Name_Zhiliu",
            },
        [51152015] = {
            ["Content"] = "白龙神君会为我们驱除恶邪的！要是招来白龙神君的厌弃，失去了祂的庇护，那才是因小失大。您请三思啊！",
            ["ContentJP"] = "白龍様がきっと我々を守り、邪を祓ってくださるだろう！もし争いごとなどして、白龍様に見限られ、加護を失ってしまえば……それこそ本末転倒ではないか！もう一度考え直してくれ！",
            ["DialogueId"] = 51152015,
            ["GUID"] = "800DBF76",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20031004.T_Story_Recall_20031004'",
            ["SpeakNpcId"] = 701088,
            },
        [51152016] = {
            ["Camera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["Content"] = "啊，是你！你是那时候被止流姐姐赶出百年春的家伙。",
            ["ContentJP"] = "あっ、思い出した！あの時、シリュウに百年春から追い出された奴だ！",
            ["DialogueId"] = 51152016,
            ["FacialId"] = {
                [1] = "200002:Shock01",
                },
            ["GUID"] = "800DBFA0",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_Start",
                },
            },
        [51152017] = {
            ["Camera"] = "414.412109,-49.105469,121.125977,0.000048,1.599821,152.399612,35.0,290.856323,false,Manual,2.056568",
            ["Content"] = "（鲜血顺着男子的额角滑至地面，那摊鲜血旁，倒着一只死去不久的秽兽。结合周围香雾缭绕却未见狴犴的样子，看来他直到遇袭都没等到白龙神君的庇护。）",
            ["ContentJP"] = "（男性の額から血が滴り、地面へと流れていく。その血溜まりの傍らには、死んで間もない穢獣が一匹倒れている。辺りには線香の煙が立ち込めているが、<Default note=\"text:ビーアン\">狴犴</>の姿は見当たらない。どうやら彼は、襲撃を受けてから今まで、白龍様の加護を授かることはなかったようだ。）",
            ["DialogueId"] = 51152017,
            ["GUID"] = "800DBFCA",
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "200002:Talk01_End",
                [2] = "100001:Give",
                },
            },
        [51152018] = {
            ["Content"] = "这只秽兽是你杀死的。",
            ["ContentJP"] = "この穢獣を殺したのは、あなただ。",
            ["DialogueId"] = 51152018,
            ["GUID"] = "800DBFF4",
            ["ImprPlusId"] = 1208,
            },
        [51152019] = {
            ["Content"] = "看来白龙神君并没有对你出手相助。",
            ["ContentJP"] = "どうやら白龍様は、助けてはくれなかったようだね。",
            ["DialogueId"] = 51152019,
            ["GUID"] = "800DC01E",
            ["ImprPlusId"] = 1206,
            },
        [51152020] = {
            ["Content"] = "之前不是说，就算是死外面也绝不动武吗？",
            ["ContentJP"] = "外で死ぬことになっても絶対に武力は使わないって言ってなかったっけ？",
            ["DialogueId"] = 51152020,
            ["GUID"] = "800DC048",
            ["ImprPlusId"] = 1210,
            },
        [51152024] = {
            ["Camera"] = "360.478516,-106.482422,91.936523,0.000124,0.0,159.903,16.91279,275.194305,false,Manual,2.8",
            ["Content"] = "哈哈……是你们。我在百年春见过你们。",
            ["ContentJP"] = "はは……君たちか。百年春で見たことがある。",
            ["DialogueId"] = 51152024,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800DC0F0",
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{100001},AnimationId{\"Wave02_Start\"},Duration{3}},\
PlayAnimation{ActorId{100001},AnimationId{\"Wave02_End\"}}\
}",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Idle",
                [2] = "200002:Confident_Start",
                },
            },
        [51152025] = {
            ["Camera"] = "61.623047,-87.913086,149.791992,0.000068,3.860225,27.111759,35.000008,629.109375,false,DoNotOverride,2.8",
            ["Content"] = "你们是来耻笑我的吗……无所谓，笑就笑吧。我触犯了诫律，我动了兵刃……",
            ["ContentJP"] = "私を笑いに来たのか……いいさ、笑えばいい。私は戒律を破り、武器を振るった……",
            ["DialogueId"] = 51152025,
            ["GUID"] = "800DC11A",
            ["SpeakNpcId"] = 701088,
            },
        [51152026] = {
            ["Camera"] = "61.623047,-87.913086,149.791992,0.000068,3.860225,27.111759,35.000008,629.109375,false,DoNotOverride,2.8",
            ["Content"] = "我犯了错……白龙神君就要降下惩罚了。哈、哈……",
            ["ContentJP"] = "私は過ちを犯したのだ……時期に白龍様の天罰が下る。は、はは……",
            ["DialogueId"] = 51152026,
            ["FacialId"] = {
                [1] = "701088:Sad01",
                },
            ["GUID"] = "800DC144",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Disagree",
                },
            },
        [51152027] = {
            ["Camera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["Content"] = "你是笨蛋吗！死脑筋！",
            ["ContentJP"] = "お前はバカか！このわからず屋！",
            ["DialogueId"] = 51152027,
            ["FacialId"] = {
                [1] = "200002:Angry02",
                },
            ["GUID"] = "800DC16E",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_Start",
                },
            },
        [51152028] = {
            ["Camera"] = "467.330078,35.046875,173.258789,0.000107,-19.939507,-168.080215,35.0,283.195221,false,Manual,1.482159",
            ["Content"] = "我听小仆从说，白龙神君只是说，不能对人类动手吧？但祂没有说过，对秽兽动手也不可以吧？",
            ["ContentJP"] = "我が下僕から聞いたが、白龍様は人に手を出すなって言っただけ。穢獣相手なら、別にいいんじゃないか？",
            ["DialogueId"] = 51152028,
            ["GUID"] = "800DC198",
            ["SpeakNpcId"] = 200002,
            ["TalkActionId"] = {
                [1] = "200002:Angry01_End",
                },
            },
        [51152029] = {
            ["Camera"] = "-44.644531,-128.060547,109.717773,0.000053,4.460147,35.51128,35.000008,395.555206,false,Manual,2.8",
            ["Content"] = "我、我不知道……诫律没提到秽兽，我不知道……我只知道，不可动武，不可动武……这是我从小到大的信仰。",
            ["ContentJP"] = "わ、わからない……戒律に穢獣のことは書かれていなかった……ただ、争ってはならない、武力を使ってはならない……それが私の、幼い頃からの信仰だった。",
            ["DialogueId"] = 51152029,
            ["FacialId"] = {
                [1] = "701088:Grief",
                },
            ["GUID"] = "800DC1C2",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_Start",
                },
            },
        [51152030] = {
            ["Camera"] = "-44.644531,-128.060547,109.717773,0.000053,4.460147,35.51128,35.000008,395.555206,false,Manual,2.8",
            ["Content"] = "可是刚刚，那秽兽扑上来，血盆大口对着我，我无论如何都不想死、不想死啊！于是我就拿着、拿着砍树的柴刀，拼命地——",
            ["ContentJP"] = "だが、さっき……あの穢獣が飛びかかってきて、その大きな口が目の前に迫った時……どうしても死にたくない、死にたくないと思ったのだ！それで、持っていた薪割り用の鉈を、無我夢中で——",
            ["DialogueId"] = 51152030,
            ["GUID"] = "800DC1EC",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_End",
                },
            },
        [51152031] = {
            ["Camera"] = "431.021484,-25.061523,196.442383,0.000075,-11.940488,159.505447,35.000008,308.194794,false,Manual,2.8",
            ["Content"] = "这就对了。",
            ["ContentJP"] = "それでいい。",
            ["DialogueId"] = 51152031,
            ["FacialId"] = {
                [1] = "100001:Happy01",
                },
            ["GUID"] = "800DC216",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51152032] = {
            ["Camera"] = "431.021484,-25.061523,196.442383,0.000075,-11.940488,159.505447,35.000008,308.194794,false,Manual,2.8",
            ["Content"] = "什么神明，什么信仰，都没有活下去重要，这才是你的本心。所以，你才会在生死关头做出这样的选择。",
            ["ContentJP"] = "「神だの信仰だのよりも、生き延びることの方がずっと大切」。それこそがあなたの本心だよ。だからこそ、間一髪の時、あの選択ができた。",
            ["DialogueId"] = 51152032,
            ["GUID"] = "800DC240",
            ["SpeakNpcId"] = 100001,
            },
        [51152033] = {
            ["Camera"] = "338.265625,19.038086,179.210938,0.000076,-10.340483,176.105225,35.0,210.359772,false,Manual,2.8",
            ["Content"] = "看你伤成这样，就不笑话你了。人想活着有什么错？我送你回百年春吧。",
            ["ContentJP"] = "そんなにボロボロじゃ、もう笑う気にもなれないよ。生きたいと願うことに、何の罪がある？百年春まで送っていこう。",
            ["DialogueId"] = 51152033,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "800DC26A",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                },
            },
        [51152034] = {
            ["Camera"] = "60.732422,-88.369141,149.791992,0.000076,3.860225,27.111778,35.000008,290.0,false,Manual,2.8",
            ["Content"] = "百年春？这……",
            ["ContentJP"] = "<Default note=\"text:ももとき\">百年春</>？しかし……",
            ["DialogueId"] = 51152034,
            ["FacialId"] = {
                [1] = "701088:Nervous",
                },
            ["GUID"] = "800DC294",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Shock_Start",
                },
            },
        [51152035] = {
            ["Camera"] = "244.042969,25.453125,161.979492,0.000076,-9.34042,173.305008,35.000008,111.625343,false,Manual,2.8",
            ["Content"] = "想活命的话就少说几句吧。",
            ["ContentJP"] = "命が惜しいなら、つべこべ言わずに付いてきて。",
            ["DialogueId"] = 51152035,
            ["GUID"] = "800DC2BE",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51152036] = {
            ["Camera"] = "-22.400391,-85.114258,115.713867,0.000092,8.260102,28.910444,38.0,357.30426,false,Manual,2.0",
            ["Content"] = "是、是……",
            ["ContentJP"] = "は、はい……",
            ["DialogueId"] = 51152036,
            ["GUID"] = "800DC2E8",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Shock_End",
                },
            },
        [51152037] = {
            ["Camera"] = "204.353516,19.880981,141.953125,0.000018,0.800095,-168.670593,33.0,272.927826,false,Manual,2.8",
            ["Content"] = "我、我……",
            ["ContentJP"] = "私、私は……",
            ["DialogueId"] = 51152037,
            ["FacialId"] = {
                [1] = "701088:Grief",
                },
            ["GUID"] = "800DC312",
            ["LookAt"] = {
                [1] = "100001:n(701088)",
                },
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_Start",
                },
            },
        [51152038] = {
            ["Camera"] = "-151.316406,-261.926147,162.417969,0.000048,-3.799989,55.524673,50.0,371.934418,false,Manual,2.5",
            ["Content"] = "怎么了？",
            ["ContentJP"] = "なに？",
            ["DialogueId"] = 51152038,
            ["GUID"] = "800DC33C",
            ["LookAt"] = {
                [1] = "701088:n(100001)",
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_Start",
                },
            },
        [51152039] = {
            ["Camera"] = "204.353516,19.880981,141.953125,0.000018,0.800095,-168.670593,33.0,272.927826,false,Manual,2.8",
            ["Content"] = "方前我对止流大人如此出言不逊，她、她还愿意收留我吗……",
            ["ContentJP"] = "先ほどはシリュウ様に無礼な口を……そ、それでも、私を受け入れてくださるのだろうか……",
            ["DialogueId"] = 51152039,
            ["GUID"] = "800DC366",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Sigh_End",
                },
            },
        [51152040] = {
            ["Camera"] = "93.96875,-175.016968,177.651367,0.000065,-8.600068,90.798744,50.0,198.719955,false,Manual,2.5",
            ["Content"] = "她先前不过是对你以信仰为由，阻止大家自卫而愤怒。但如今……你已经用双手诚实地做出了选择。",
            ["ContentJP"] = "彼女が怒っていたのは、あなたが信仰を盾にしてみんなの自衛を妨げようとしたからだ。だけど今……あなたは自分の手で、正直な答えを出した。",
            ["DialogueId"] = 51152040,
            ["GUID"] = "800DC390",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk03_End",
                },
            },
        [51152041] = {
            ["Camera"] = "93.96875,-175.016968,177.651367,0.000065,-8.600068,90.798744,50.0,198.719955,false,Manual,2.5",
            ["Content"] = "只要你真诚道歉，我想她会谅解的。",
            ["ContentJP"] = "誠心誠意謝れば、きっと分かってくれるよ。",
            ["DialogueId"] = 51152041,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "800DC3BA",
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk02_Start",
                },
            },
        [51152042] = {
            ["Camera"] = "350.330078,-275.796265,132.675781,0.000026,0.600155,140.929413,15.794469,336.572845,false,Manual,2.8",
            ["Content"] = "……我明白了。",
            ["ContentJP"] = "……分かった。",
            ["DialogueId"] = 51152042,
            ["FacialId"] = {
                [1] = "701088:Nervous",
                },
            ["GUID"] = "800DC3E4",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Agree",
                },
            },
        [51152043] = {
            ["Camera"] = "350.330078,-275.796265,132.675781,0.000026,0.600155,140.929413,15.794469,336.572845,false,Manual,2.8",
            ["Content"] = "想不到我半生的信仰救不了我，最终救了我的竟是这把柴刀……",
            ["ContentJP"] = "半生を捧げた信仰が私を救わず、結局私を救ったのがこの鉈だったとは……",
            ["DialogueId"] = 51152043,
            ["GUID"] = "800DC40E",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Talk02_Start",
                },
            },
        [51152044] = {
            ["Camera"] = "69.585938,11.308655,153.422852,0.000016,0.999987,-144.27388,33.0,143.369492,false,Manual,2.8",
            ["Content"] = "我会向止流大人致歉……还有，致谢。",
            ["ContentJP"] = "シリュウ様には、謝罪を……そして、感謝を伝えようと思う。",
            ["DialogueId"] = 51152044,
            ["FacialId"] = {
                [1] = "701088:Sad01",
                },
            ["GUID"] = "800DC438",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Talk02_End",
                },
            },
        [51152045] = {
            ["Camera"] = "69.585938,11.308655,153.422852,0.000016,0.999987,-144.27388,33.0,143.369492,false,Manual,2.8",
            ["Content"] = "多谢义士一路护送，请收下我的谢礼吧。",
            ["ContentJP"] = "道中お守りいただき、感謝する。義士様、どうか私の謝礼を受け取っておくれ。",
            ["DialogueId"] = 51152045,
            ["GUID"] = "800DC462",
            ["SpeakNpcId"] = 701088,
            ["TalkActionId"] = {
                [1] = "701088:Give",
                },
            },
        [51153001] = {
            ["Content"] = "不对味，不对味，这味怎么不对啊？老板，你是不是做了什么手脚。这茶汤与我<H>记忆中的滋味</>分明相差甚远！",
            ["ContentJP"] = "違う、やはり違う。どうして味が違うんだ？店主、何か細工でもしたのではないか。この茶の味、私の<H>記憶にある味</>とは明らかにかけ離れている！",
            ["DialogueId"] = 51153001,
            ["GUID"] = "800E613A",
            ["SpeakNpcId"] = 701091,
            },
        [51153002] = {
            ["Camera"] = "-408.917969,289.988281,124.88916,-0.0,-4.999999,-26.999968,22.0,556.40625,false,Manual,1.7",
            ["Content"] = "这位客人，究竟是哪里不对，哪里味道不一样，你倒是说出个一二来啊？",
            ["ContentJP"] = "一体何が違うって言うんだ、お客さん。どこがどう違うのか、はっきり言ってくれよ。",
            ["DialogueId"] = 51153002,
            ["FacialId"] = {
                [1] = "701090:CM_Angry01",
                },
            ["GUID"] = "800E6164",
            ["LookAt"] = {
                [1] = "100001:n(701090)",
                },
            ["NextDialogue"] = 51153003,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Angry01_Start",
                },
            },
        [51153003] = {
            ["Camera"] = "-22.859375,122.511719,145.754395,0.000026,0.199988,-79.15564,33.0,197.256683,false,Manual,1.78578",
            ["Content"] = "你在这里红口白牙瞎说，这不是在砸我的买卖吗！这位白衣服{性别：小兄弟|姑娘}，我看你在这儿站了一阵子了，不然你来评评理？",
            ["ContentJP"] = "根も葉もないことを言われちゃ、商売あがったりだ！そこの白い服の{性别：お兄さん|お姉さん}、さっきから見てただろ。あんたが仲裁に入ってくれないか？",
            ["DialogueId"] = 51153003,
            ["GUID"] = "800E618E",
            ["LookAt"] = {
                [1] = "701090:n(100001)",
                },
            ["NextOptions"] = {
                [1] = 51153004,
                [2] = 51153007,
                },
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Angry01_End",
                },
            },
        [51153004] = {
            ["Content"] = "是不是老板换了原料或工艺，以次充好？",
            ["ContentJP"] = "店主が材料や製法を変えて、粗悪品を掴ませているのでは？",
            ["DialogueId"] = 51153004,
            ["GUID"] = "800E61B8",
            ["NextDialogue"] = 51153005,
            },
        [51153005] = {
            ["Camera"] = "-285.1875,166.675781,127.64502,0.000036,1.399991,-33.151527,50.0,375.0,false,Manual,2.8",
            ["Content"] = "你可别瞎说，我这大碗茶，三停茶叶一停花，半银币一大碗，从未变过。",
            ["ContentJP"] = "勝手なことを言うもんじゃない。うちのお茶は、茶葉三分に花一分。半銀貨でなみなみ一杯、昔から変えちゃいないよ。",
            ["DialogueId"] = 51153005,
            ["GUID"] = "800E61E2",
            ["NextDialogue"] = 51153006,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Talk03_Start",
                },
            },
        [51153006] = {
            ["Camera"] = "-285.1875,166.675781,127.64502,0.000036,1.399991,-33.151527,50.0,375.0,false,Manual,2.8",
            ["Content"] = "我随老父亲在此处卖了二十年茶水了，从挑着担子卖水起，到今日有两间小铺，从不做偷工减料，以次充好的事！",
            ["ContentJP"] = "ここでオヤジと二十年茶を売ってきた。天秤棒を担いでた頃から店を二軒構える今日まで、手抜きや誤魔化しなんて一度だってしたことはねえ！",
            ["DialogueId"] = 51153006,
            ["GUID"] = "800E620C",
            ["NextDialogue"] = 51153009,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Talk03_End",
                },
            },
        [51153007] = {
            ["Content"] = "是不是这位顾客故意找茬，白吃白喝？",
            ["ContentJP"] = "この客がわざと難癖をつけて、食い逃げしようとしているのでは？",
            ["DialogueId"] = 51153007,
            ["GUID"] = "800E6236",
            ["NextDialogue"] = 51153008,
            },
        [51153008] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "这位小友，我绝非信口开河，你且听我道来。",
            ["ContentJP"] = "若者よ、決してデタラメを言っているわけではない。私の話を聞いてくれ。",
            ["DialogueId"] = 51153008,
            ["GUID"] = "800E6260",
            ["LookAt"] = {
                [1] = "100001:n(701091)",
                },
            ["NextDialogue"] = 51153009,
            ["SpeakNpcId"] = 701091,
            ["TurnTo"] = {
                [1] = "701091:n(100001)",
                [2] = "100001:n(701091)",
                },
            },
        [51153009] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "小友你有所不知，我是一名织星客，常年游历异乡，久不归家。这次在横越沙漠，口干舌燥时，口中突然涌起年幼时曾经尝过的花茶的甘香。",
            ["ContentJP"] = "君は知らないだろうが、私は星織人でな。年中見知らぬ土地を旅しており、久しく故郷には戻っていなかった。今回、砂漠を越えて喉がからからだった時、ふと幼い頃に味わった花茶の甘い香りが口の中に蘇ってきたのだ。",
            ["DialogueId"] = 51153009,
            ["GUID"] = "800E628A",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                [2] = "100001:n(701091)",
                },
            ["NextDialogue"] = 51153010,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk02_Start",
                },
            },
        [51153010] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "这不，我一回到浮星埠，就奔着这家茶摊来了。可是他家的茶汤却变了味道，令人好不扫兴。",
            ["ContentJP"] = "それで、浮星の埠に戻るなり、この茶屋へ駆け込んだというわけだ。だが、ここの茶は味が変わってしまっていて、実に興ざめだよ。",
            ["DialogueId"] = 51153010,
            ["GUID"] = "800E62B4",
            ["NextDialogue"] = 51153011,
            ["SpeakNpcId"] = 701091,
            },
        [51153011] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "我记得之前的茶汤，甘冽解渴，花香隐约，只是汤中有碎末这一点不好。如今你这茶，透亮清澈，确不是曾经的茶汤。",
            ["ContentJP"] = "以前の茶は、甘露のように喉を潤し、かすかに花の香りがしたものだ。ただ、茶湯に茶葉のカスが混じっているのだけがキズだったが……今出されたこの茶は、透き通っていて綺麗すぎる。かつての茶ではない。",
            ["DialogueId"] = 51153011,
            ["GUID"] = "800E62DE",
            ["NextDialogue"] = 51153012,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk02_End",
                },
            },
        [51153012] = {
            ["Camera"] = "8.28125,542.140625,129.218262,0.000026,0.999981,-90.554573,50.0,605.407349,false,Manual,2.8",
            ["Content"] = "老弟，你这么一说我就明白了。我老父亲年前回家颐养天年，我接手了这家铺子，把之前的碎末子换成了整叶。",
            ["ContentJP"] = "それなら合点がいったよ、旦那。オヤジが去年に隠居してな、俺が店を継いだ時に、茶葉のカスを嫌って全部綺麗な茶葉に変えたんだ。",
            ["DialogueId"] = 51153012,
            ["FacialId"] = {
                [1] = "701090:CM_Smile01",
                },
            ["GUID"] = "800E6308",
            ["LookAt"] = {
                [1] = "100001:n(701090)",
                [2] = "701091:n(701090)",
                [3] = "701090:n(701091)",
                },
            ["NextDialogue"] = 51153013,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Think_Start",
                },
            },
        [51153013] = {
            ["Camera"] = "8.28125,542.140625,129.218262,0.000026,0.999981,-90.554573,50.0,605.407349,false,Manual,2.8",
            ["Content"] = "我这茶摊卖的不过是解渴的大碗茶，没想到这点差别让你给品出来了。",
            ["ContentJP"] = "うちは喉を潤すための番茶を売ってるだけの店だ。まさかそんな違いに気づく人がいるなんてな。",
            ["DialogueId"] = 51153013,
            ["GUID"] = "800E6332",
            ["NextDialogue"] = 51153014,
            ["SpeakNpcId"] = 701090,
            ["TalkActionId"] = {
                [1] = "701090:Think_End",
                },
            },
        [51153014] = {
            ["Camera"] = "141.191406,-101.46875,191.177734,0.000115,-13.600491,142.446793,50.0,284.737152,false,Manual,1.78578",
            ["Content"] = "既然误会解开，那我就告……",
            ["ContentJP"] = "誤解が解けたなら、{性别:僕|私}はこれで……",
            ["DialogueId"] = 51153014,
            ["FacialId"] = {
                [1] = "100001:Smile02",
                },
            ["GUID"] = "800E635C",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153015,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Talk01_Start",
                },
            },
        [51153015] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "小友且留步！",
            ["ContentJP"] = "待ってくれ、若者！",
            ["DialogueId"] = 51153015,
            ["GUID"] = "800E6386",
            ["LookAt"] = {
                [1] = "100001:n(701091)",
                [2] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153016,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153016] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "我今日定要找到旧时茶汤的滋味。百年春客商云集，天下商品无所不有，在那儿一定能找到老板曾经用过的那款茶叶。",
            ["ContentJP"] = "私は今日こそ、あの懐かしい茶の味を見つけ出したい。百年春は商人が集まり、天下の品が集まる場所だ。あそこなら、店主が以前使っていた茶葉も必ず見つかるはず。",
            ["DialogueId"] = 51153016,
            ["GUID"] = "800E63B0",
            ["NextDialogue"] = 51153017,
            ["SpeakNpcId"] = 701091,
            },
        [51153017] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "不知小友是否愿意随我一同前往。",
            ["ContentJP"] = "私と一緒に来てはくれないだろうか。",
            ["DialogueId"] = 51153017,
            ["GUID"] = "800E63DA",
            ["NextOptions"] = {
                [1] = 51153018,
                [2] = 51153020,
                },
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_End",
                },
            },
        [51153018] = {
            ["Content"] = "走这一趟也不是不行，有什么好处吗？",
            ["ContentJP"] = "それは構わないけど、何か見返りでも？",
            ["DialogueId"] = 51153018,
            ["GUID"] = "800E6404",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51153019,
            },
        [51153019] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "如今一路上玄色狴犴猖獗为灾，如能护送我平安抵达百年春，定当重金酬谢！",
            ["ContentJP"] = "道中は玄狴が災いとなっている。もし私を無事に百年春まで送り届けてくれたなら、相応の礼を約束しよう！",
            ["DialogueId"] = 51153019,
            ["GUID"] = "800E642E",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153020] = {
            ["Content"] = "一路上玄色狴犴泛滥，你是在担心安危吗？",
            ["ContentJP"] = "道中に玄狴が溢れている。もしかして己の身の安全を心配している？",
            ["DialogueId"] = 51153020,
            ["GUID"] = "800E6458",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 51153021,
            },
        [51153021] = {
            ["Camera"] = "-273.785156,39.746094,126.045898,0.000046,1.999934,16.852501,50.0,348.791229,false,Manual,2.8",
            ["Content"] = "正是。近来烛阴为灾，我多年未归，先前的道路也不知畅行与否。如能护送我平安抵达百年春，定当重金酬谢！",
            ["ContentJP"] = "その通りだ。近頃は燭陰が災いを成している。長らく帰っていなかった故、かつての道が今も通れるか分からなくてな。無事に送り届けてくれたなら、厚く謝礼をさせてもらう！",
            ["DialogueId"] = 51153021,
            ["GUID"] = "800E6482",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153022] = {
            ["Content"] = "经蒹葭浦至浮星埠，我幼时常走这条路去看船，没想到如今它竟变得如此危险。",
            ["ContentJP"] = "蒹葭の浦を通って浮星の埠へ……幼い頃はよく船を見にこの道を歩いたものだが、まさかこんなに危険な場所になっていようとは。",
            ["DialogueId"] = 51153022,
            ["GUID"] = "800E64AC",
            ["NextDialogue"] = 51153023,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Think_Start",
                },
            },
        [51153023] = {
            ["Content"] = "果然时移世易，不可同日而语。",
            ["ContentJP"] = "まさに時は移ろい、事態は変わるものだ。昔と同じようにはいかないか。",
            ["DialogueId"] = 51153023,
            ["GUID"] = "800E64D6",
            ["NextDialogue"] = 51153024,
            ["SpeakNpcId"] = 701091,
            },
        [51153024] = {
            ["Content"] = "我们继续前进吧，百年春就在前面了。",
            ["ContentJP"] = "先を急ごう。百年春はもうすぐそこだ。",
            ["DialogueId"] = 51153024,
            ["GUID"] = "800E6500",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Think_End",
                },
            },
        [51153025] = {
            ["Camera"] = "-218.316406,82.341675,107.538086,0.000017,5.878347,-22.685118,60.0,535.899536,false,Manual,2.8",
            ["Content"] = "陈老兄，哪阵风把你吹来了。久不见面，这一趟出海还顺利吗？",
            ["ContentJP"] = "これはこれは、ハクサさんじゃないか。一体どういう風の吹き回しだ？久しいな、今回の航海は順調だったか？",
            ["DialogueId"] = 51153025,
            ["GUID"] = "800E652A",
            ["LookAt"] = {
                [1] = "701092:n(701091)",
                [2] = "701091:n(701092)",
                [3] = "100001:n(701092)",
                },
            ["NextDialogue"] = 51153026,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Talk01_Start",
                },
            },
        [51153026] = {
            ["Content"] = "你不在的日子里，兄弟可挂心你了。为了我们一同长大的交情，我好茶好酒都给你留着，就等你回来一同品尝。",
            ["ContentJP"] = "あんたがいない間、寂しかったぞ。俺たちの幼馴染の付き合いに免じて、とっておきの茶と酒を取っておいたんだ。あんたが戻ったら一緒に味わおうと思ってな。",
            ["DialogueId"] = 51153026,
            ["GUID"] = "800E6554",
            ["NextDialogue"] = 51153027,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Talk01_End",
                },
            },
        [51153027] = {
            ["Camera"] = "-499.664062,-243.194458,187.458984,0.000042,-8.200284,15.325444,30.0,410.0,false,Manual,2.8",
            ["Content"] = "来来来二位请坐，请上座！我好好给你讲讲这些日子里发生的事！",
            ["ContentJP"] = "さあさあ、お二人ともどうぞ、お座りくだされ！最近起きた出来事をたっぷりと聞かせてやるからな！",
            ["DialogueId"] = 51153027,
            ["GUID"] = "800E657E",
            ["NextDialogue"] = 51153028,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Explain01_Start",
                },
            },
        [51153028] = {
            ["Content"] = "（胡老板滔滔不绝地讲述起了近日的见闻，你和陈白沙只能等待着他回过神来……）",
            ["ContentJP"] = "（店主のコさんは最近の出来事について立て板に水のごとく喋り始めた。あなたとハクサは、彼が我に返るのを待つしかなかった……）",
            ["DialogueId"] = 51153028,
            ["GUID"] = "800E65A8",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153029,
            ["SpeakNpcId"] = 0,
            },
        [51153029] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "对了老兄，我见到你激动得都忘了，你这趟来是为了什么事？",
            ["ContentJP"] = "おっと、そうだ。あんたの顔を見たら嬉しくてつい忘れるところだった。今日は一体どんな用件で来たんだ？",
            ["DialogueId"] = 51153029,
            ["GUID"] = "800E65D2",
            ["NextDialogue"] = 51153030,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Explain01_End",
                },
            },
        [51153030] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "我来找一款花茶……",
            ["ContentJP"] = "実は、ある花茶を探していて……",
            ["DialogueId"] = 51153030,
            ["GUID"] = "800E65FC",
            ["NextDialogue"] = 51153031,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153031] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "花茶，那还不容易！伙计们，把最好的端上来！",
            ["ContentJP"] = "花茶だって？そんなのお安い御用だ！おいお前ら、最高の一品を持ってこい！",
            ["DialogueId"] = 51153031,
            ["FacialId"] = {
                [1] = "701092:CM_Ahaha01",
                },
            ["GUID"] = "800E6626",
            ["NextDialogue"] = 51153032,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Explain02_Start",
                },
            },
        [51153032] = {
            ["Content"] = "（伙计们一溜烟地端上了十多款花茶。）",
            ["ContentJP"] = "（店員たちが素早く十数種類もの花茶を運んできた。）",
            ["DialogueId"] = 51153032,
            ["GUID"] = "800E6650",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153033,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701092:Explain02_End",
                },
            },
        [51153033] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "陈老兄，你先尝尝这款莲花茶。清晨日未出之时将茶叶置入菡萏中经日，如此反复数次，焙干后，香美异常。",
            ["ContentJP"] = "まずはこのハス茶を飲んでみてくれ。夜明け前、まだ日が昇らぬうちに茶葉をはすの花の中に閉じ込め、幾日も繰り返すと、それを乾燥させる。こうしてできた茶の香りは格別だぞ。",
            ["DialogueId"] = 51153033,
            ["FacialId"] = {
                [1] = "701092:CM_Smile01",
                },
            ["GUID"] = "800E667A",
            ["NextDialogue"] = 51153034,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153034] = {
            ["Content"] = "（陈白沙尝了尝这杯莲花茶。）",
            ["ContentJP"] = "（ハクサはそのハス茶を味わった。）",
            ["DialogueId"] = 51153034,
            ["GUID"] = "800E66A4",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153035,
            ["SpeakNpcId"] = 0,
            },
        [51153035] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "确实不错，但是……",
            ["ContentJP"] = "確かに素晴らしい。だが……",
            ["DialogueId"] = 51153035,
            ["GUID"] = "800E66CE",
            ["NextDialogue"] = 51153036,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_End",
                },
            },
        [51153036] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "陈老兄，你再尝尝这款茉莉花茶。九窨一提，汤色黄绿明净，花香清雅，滋味清甜，花叶交错，犹如碧潭飘雪。",
            ["ContentJP"] = "ならば次はこのジャスミン茶だ。九回の香り付けと一回の香り上げ。茶の色は澄んだ黄緑、香りは上品で味は清らかに甘い。花と葉が混じり合う様は、まさに緑の池に舞う雪のようだ。",
            ["DialogueId"] = 51153036,
            ["GUID"] = "800E66F8",
            ["NextDialogue"] = 51153037,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153037] = {
            ["Content"] = "（陈白沙又尝了尝这杯茉莉花茶。）",
            ["ContentJP"] = "（ハクサはそのジャスミン茶も味わった。）",
            ["DialogueId"] = 51153037,
            ["GUID"] = "800E6722",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153038,
            ["SpeakNpcId"] = 0,
            },
        [51153038] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "多谢招待，只是……",
            ["ContentJP"] = "もてなしには感謝する、だが……",
            ["DialogueId"] = 51153038,
            ["GUID"] = "800E674C",
            ["NextDialogue"] = 51153039,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Think_Start",
                },
            },
        [51153039] = {
            ["Camera"] = "-133.140625,43.044434,148.704102,0.000039,0.0,-19.0756,50.0,410.0,false,Manual,2.8",
            ["Content"] = "陈老兄，你再试试这款桂花茶。汤色通透，滋味醇厚，花茶一体，清雅有蜜香。",
            ["ContentJP"] = "これならどうだ、<Default note=\"text:キンモクセイ\">桂花</>茶だ。色は透き通り、味深く、花と茶が一体となって、蜜のような香りが漂うぞ。",
            ["DialogueId"] = 51153039,
            ["GUID"] = "800E6776",
            ["NextDialogue"] = 51153040,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153040] = {
            ["Content"] = "（陈白沙只得喝下了这杯桂花茶。）",
            ["ContentJP"] = "（ハクサは仕方なく、その<Default note=\"text:キンモクセイ\">桂花</>茶を飲み干した。）",
            ["DialogueId"] = 51153040,
            ["GUID"] = "800E67A0",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "701091:n(701091)",
                },
            ["NextDialogue"] = 51153041,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Think_End",
                },
            },
        [51153041] = {
            ["Camera"] = "305.871094,-370.953125,181.147461,0.000052,-6.399839,115.319542,50.0,440.022095,false,Manual,2.334505",
            ["Content"] = "好茶是好茶，就是……",
            ["ContentJP"] = "良い茶なのは分かっている、だが……",
            ["DialogueId"] = 51153041,
            ["GUID"] = "800E67CA",
            ["NextDialogue"] = 51153042,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Sigh_Start",
                },
            },
        [51153042] = {
            ["Camera"] = "48.894531,-6.67627,173.09668,0.000049,-4.600002,-33.478237,50.0,230.0,false,Manual,2.8",
            ["Content"] = "不合适，对不对？别急，再尝尝这个！",
            ["ContentJP"] = "しっくりこない、か。まあ焦るな。次はこれを試してみてくれ！",
            ["DialogueId"] = 51153042,
            ["GUID"] = "800E67F4",
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Give",
                },
            },
        [51153043] = {
            ["Content"] = "在胡老板热情的招待下，陈白沙一次性喝下了十多杯不同的花茶。",
            ["ContentJP"] = "コさんの熱烈なもてなしにより、ハクサは一度に十数杯もの異なる花茶を飲み干した。",
            ["DialogueId"] = 51153043,
            ["GUID"] = "800E681E",
            ["SpeakNpcId"] = 0,
            },
        [51153044] = {
            ["Camera"] = "205.382812,225.099731,26.811523,0.000026,3.692967,-111.917961,33.0,237.662262,false,Manual,2.8",
            ["Content"] = "不……嗝……不行了……我再也喝不下了……",
            ["ContentJP"] = "もう……げふっ……無理だ……これ以上は……",
            ["DialogueId"] = 51153044,
            ["GUID"] = "800E6848",
            ["NextDialogue"] = 51153045,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Onground01_Loop",
                },
            },
        [51153045] = {
            ["Camera"] = "57.484375,110.06665,34.862305,0.0,19.999989,-59.999985,50.000008,327.854492,false,Manual,5.0",
            ["Content"] = "怎么样，找到还可入口的没有？",
            ["ContentJP"] = "それで、口に合うものは見つかったか？",
            ["DialogueId"] = 51153045,
            ["FacialId"] = {
                [1] = "701092:CM_Smile01",
                },
            ["GUID"] = "800E6872",
            ["LookAt"] = {
                [1] = "701092:n(701091)",
                },
            ["NextDialogue"] = 51153046,
            ["SpeakNpcId"] = 701092,
            },
        [51153046] = {
            ["Camera"] = "205.382812,225.099731,26.811523,0.000026,3.692967,-111.917961,33.0,237.662262,false,Manual,2.8",
            ["Content"] = "我……我……嗝……",
            ["ContentJP"] = "そ……それは……げふっ……",
            ["DialogueId"] = 51153046,
            ["FacialId"] = {
                [1] = "701091:CM_Sad01",
                },
            ["GUID"] = "800E689C",
            ["LookAt"] = {
                [1] = "701091:n(701092)",
                },
            ["NextDialogue"] = 51153047,
            ["SpeakNpcId"] = 701091,
            },
        [51153047] = {
            ["Camera"] = "419.035156,-105.711426,187.561523,0.000082,-9.999806,-178.116913,50.0,398.468353,false,Manual,5.0",
            ["Content"] = "我来替他说吧，我们在找二十年前浮星埠茶摊子卖的碎末子。",
            ["ContentJP"] = "{性别:僕|私}が代わりに説明するよ。実は、二十年前に浮星の埠の茶屋で売られていた茶のカスを探している。",
            ["DialogueId"] = 51153047,
            ["FacialId"] = {
                [1] = "100001:Happy02",
                },
            ["GUID"] = "800E68C6",
            ["LookAt"] = {
                [1] = "701092:n(100001)",
                [2] = "100001:n(701092)",
                },
            ["NextDialogue"] = 51153048,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_Start",
                },
            },
        [51153048] = {
            ["Camera"] = "-133.570312,74.551025,127.095703,0.000084,2.000234,-34.916454,50.0,428.920837,false,Manual,2.8",
            ["Content"] = "碎末子？你们找它做什么，又不是什么好东西。",
            ["ContentJP"] = "茶のカス？そんなものを探してどうするんだ。大した品じゃないぞ。",
            ["DialogueId"] = 51153048,
            ["FacialId"] = {
                [1] = "701092:Curious",
                },
            ["GUID"] = "800E68F0",
            ["NextDialogue"] = 51153049,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Think_Start",
                },
            },
        [51153049] = {
            ["Camera"] = "419.035156,-105.711426,187.561523,0.000082,-9.999806,-178.116913,50.0,398.468353,false,Manual,5.0",
            ["Content"] = "确实不过是街上摊子卖的大碗茶。只是这位织星客对此念念不忘，一定要找到他所说的“旧时的滋味”不可。",
            ["ContentJP"] = "確かに、ただの街角で売っていた番茶だ。だけど、こちらの星織人さんはそれが忘れられないらしくて。どうしても「あの頃の味」を見つけたいんだそうだ。",
            ["DialogueId"] = 51153049,
            ["GUID"] = "800E691A",
            ["NextDialogue"] = 51153050,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Sigh_End",
                },
            },
        [51153050] = {
            ["Camera"] = "57.484375,110.06665,34.862305,0.0,19.999989,-59.999985,50.000008,327.854492,false,Manual,5.0",
            ["Content"] = "陈老兄，这些茶里有哪款让你想起以前的滋味的吗？",
            ["ContentJP"] = "ハクサさんよ、今の茶の中に、昔の味を思い出させるものはあったか？",
            ["DialogueId"] = 51153050,
            ["GUID"] = "800E6944",
            ["LookAt"] = {
                [1] = "701092:n(701091)",
                },
            ["NextDialogue"] = 51153051,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Think_End",
                },
            },
        [51153051] = {
            ["Camera"] = "610.267578,-184.272705,139.628906,0.000035,-9.30713,162.883575,60.0,605.249268,false,Manual,2.8",
            ["Content"] = "一次性……嗝……喝太多，分……嗝……不出来了。",
            ["ContentJP"] = "一度に……げふっ……飲みすぎて……もう……げふっ……判別がつかん。",
            ["DialogueId"] = 51153051,
            ["FacialId"] = {
                [1] = "701091:CM_Sad01",
                },
            ["GUID"] = "800E696E",
            ["NextDialogue"] = 51153052,
            ["SpeakNpcId"] = 701091,
            },
        [51153052] = {
            ["Camera"] = "239.548828,50.161377,163.197266,0.000064,-6.400146,-93.912025,30.0,181.281296,false,Manual,5.0",
            ["Content"] = "唉……老兄，让我来替你想想吧。",
            ["ContentJP"] = "はぁ……そんじゃ、俺も一緒に考えてやるよ。",
            ["DialogueId"] = 51153052,
            ["FacialId"] = {
                [1] = "701092:CM_Idle",
                },
            ["GUID"] = "800E6998",
            ["NextDialogue"] = 51153053,
            ["SpeakNpcId"] = 701092,
            ["TalkActionId"] = {
                [1] = "701092:Talk01_Start",
                },
            },
        [51153053] = {
            ["Camera"] = "664.539062,942.744019,270.186523,0.000074,-7.000185,72.683929,11.0,327.854492,false,DoNotOverride,5.0",
            ["Content"] = "二十年前，我们俩都还是在蒹葭浦的河滩上赤着脚玩泥巴的野孩子。",
            ["ContentJP"] = "二十年前、俺たちはまだ<Default note=\"text:けんか\">蒹葭</>の浦の河原で泥で遊んでたガキだったな。",
            ["DialogueId"] = 51153053,
            ["FinalCamera"] = "664.539062,942.744019,270.186523,-0.0,-7.000185,109.999985,11.000002,327.854492,false,DoNotOverride,5.0",
            ["GUID"] = "800E69C2",
            ["NextDialogue"] = 51153054,
            ["SpeakNpcId"] = 701092,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51153054] = {
            ["Content"] = "没想到二十年过去，一个往西，一个往东，好几年也见不上一面。",
            ["ContentJP"] = "あれから二十年。一人は西へ、一人は東へ。数年に一度しか会えない仲になっちまった。",
            ["DialogueId"] = 51153054,
            ["GUID"] = "800E69EC",
            ["NextDialogue"] = 51153055,
            ["SpeakNpcId"] = 701092,
            },
        [51153055] = {
            ["Content"] = "时光飞逝，有什么味道是永久不变的呢……",
            ["ContentJP"] = "時は飛ぶように過ぎ去る。ずっと変わらない味なんて、果たしてあるのかね……",
            ["DialogueId"] = 51153055,
            ["GUID"] = "800E6A16",
            ["NextDialogue"] = 51153056,
            ["SpeakNpcId"] = 701092,
            },
        [51153056] = {
            ["Camera"] = "388.880859,100.010376,1.513672,0.00003,10.692913,-163.316513,38.0,306.638,false,Manual,2.8",
            ["Content"] = "我……我知道了！",
            ["ContentJP"] = "そうか……分かったぞ！",
            ["DialogueId"] = 51153056,
            ["FacialId"] = {
                [1] = "701091:CM_Shock01",
                },
            ["FinalCamera"] = "208.158203,45.84729,37.138672,0.00003,10.692913,-163.316513,38.0,117.599663,false,Manual,2.8",
            ["GUID"] = "800E6A40",
            ["NextDialogue"] = 51153057,
            ["SpeakNpcId"] = 701091,
            ["ToFinalCameraBlendTime"] = 0.2,
            },
        [51153057] = {
            ["Content"] = "（陈白沙迅速地从地上爬了起来，目光炯炯地看着你。）",
            ["ContentJP"] = "（ハクサは勢いよく立ち上がり、目を輝かせてあなたを見つめた。）",
            ["DialogueId"] = 51153057,
            ["GUID"] = "800E6A6A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153058,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Idle",
                },
            },
        [51153058] = {
            ["Camera"] = "172.066406,36.535034,156.958008,0.000033,-6.107124,-151.715576,30.0,185.0,false,Manual,2.8",
            ["Content"] = "{nickname}小友……",
            ["ContentJP"] = "{nickname}くん……",
            ["DialogueId"] = 51153058,
            ["FacialId"] = {
                [1] = "701091:CM_Smile01",
                },
            ["GUID"] = "800E6A94",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                [2] = "100001:n(701091)",
                },
            ["NextOptions"] = {
                [1] = 51153059,
                [2] = 51153061,
                },
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "100001:Confident_Start",
                },
            },
        [51153059] = {
            ["Content"] = "来都来了，就帮忙帮到底吧。",
            ["ContentJP"] = "ここまで来たんだ、最後まで付き合うよ。",
            ["DialogueId"] = 51153059,
            ["GUID"] = "800E6ABE",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 51153060,
            },
        [51153060] = {
            ["Camera"] = "37.376953,-174.963745,129.658203,0.000059,3.999984,87.884972,30.000002,191.158386,false,Manual,2.8",
            ["Content"] = "多谢小友，等我尝到那旧日花茶，必有重谢！",
            ["ContentJP"] = "恩に着る。あの懐かしの花茶を味わうことができたら、必ずお礼をさせてもらうよ！",
            ["DialogueId"] = 51153060,
            ["GUID"] = "800E6AE8",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153061] = {
            ["Content"] = "再让我跑腿就要收费了！",
            ["ContentJP"] = "これ以上パシリをさせるなら、追加料金をもらうよ。",
            ["DialogueId"] = 51153061,
            ["GUID"] = "800E6B12",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 51153062,
            },
        [51153062] = {
            ["Camera"] = "37.376953,-174.963745,129.658203,0.000059,3.999984,87.884972,30.000002,191.158386,false,Manual,2.8",
            ["Content"] = "一定一定，绝不亏待！",
            ["ContentJP"] = "もちろんだ、決して損はさせない！",
            ["DialogueId"] = 51153062,
            ["GUID"] = "800E6B3C",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153063] = {
            ["Content"] = "你端着一壶茶来这儿，就是你说的……好主意？",
            ["ContentJP"] = "茶器を一つ抱えてここに来るのが……ハクサさんの「いい考え」？",
            ["DialogueId"] = 51153063,
            ["GUID"] = "800E6B66",
            ["NextDialogue"] = 51153064,
            ["SpeakNpcId"] = 100001,
            },
        [51153064] = {
            ["Content"] = "哈哈，我想明白了。既然想要找那时的味道，自然也要重现当时的情境不是。",
            ["ContentJP"] = "ははは、ようやくわかったのだよ。当時の味を見つけたいのなら、当時の状況を再現すればいい。",
            ["DialogueId"] = 51153064,
            ["GUID"] = "800E6B90",
            ["NextDialogue"] = 51153065,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_Start",
                },
            },
        [51153065] = {
            ["Content"] = "那时我整日在这片河滩上狂奔，兴许等我跑得渴了累了，就能找到当时的味道了。",
            ["ContentJP"] = "あの頃の私は、一日中この河原を駆け回っていた。きっと、喉が渇いて疲れ果てるまで走れば、あの時の味に辿り着けるはずだ。",
            ["DialogueId"] = 51153065,
            ["GUID"] = "800E6BBA",
            ["NextDialogue"] = 51153066,
            ["SpeakNpcId"] = 701091,
            },
        [51153066] = {
            ["Content"] = "小友不妨和我来比试一番。",
            ["ContentJP"] = "若者よ、私と競走してみないか。",
            ["DialogueId"] = 51153066,
            ["GUID"] = "800E6BE4",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Talk01_End",
                },
            },
        [51153067] = {
            ["Content"] = "二十年没在这片河滩上跑过了，今天真是过瘾！",
            ["ContentJP"] = "二十年ぶりにこの河原を走るが、実にいい気分だ！",
            ["DialogueId"] = 51153067,
            ["GUID"] = "800E6C0E",
            ["SpeakNpcId"] = 701091,
            },
        [51153068] = {
            ["Content"] = "嘿咻……有点跟不上了……",
            ["ContentJP"] = "よいしょ……少し、疲れてきたな……",
            ["DialogueId"] = 51153068,
            ["GUID"] = "800E6C38",
            ["SpeakNpcId"] = 701091,
            },
        [51153069] = {
            ["Content"] = "呼……呼……自愧不如！自愧不如！",
            ["ContentJP"] = "はぁ……はぁ……降参だ！私の負けだよ！",
            ["DialogueId"] = 51153069,
            ["GUID"] = "800E6C62",
            ["SpeakNpcId"] = 701091,
            },
        [51153070] = {
            ["Content"] = "（陈白沙大口将茶水灌进了口里，随即累得倒下了。）",
            ["ContentJP"] = "（ハクサは茶を勢いよく口に流し込み、そのまま疲れ果てて倒れ込んだ。）",
            ["DialogueId"] = 51153070,
            ["GUID"] = "800E6C8C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153071,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Onground01_Loop",
                },
            },
        [51153071] = {
            ["Camera"] = "82.539062,236.600586,94.693359,0.000013,-1.542742,-109.15033,38.0,410.739655,false,Manual,2.8",
            ["Content"] = "是你想找的滋味吗？",
            ["ContentJP"] = "……探していた味は出た？",
            ["DialogueId"] = 51153071,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["GUID"] = "800E6CB6",
            ["LookAt"] = {
                [1] = "100001:n(701091)",
                },
            ["NextDialogue"] = 51153072,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_Start",
                },
            },
        [51153072] = {
            ["Camera"] = "225.349609,-183.40332,129.71582,0.000022,-14.342556,161.450195,38.0,362.946472,false,Manual,2.8",
            ["Content"] = "有八分像了，还有两分差在哪里呢……",
            ["ContentJP"] = "八分通り、あの味だ。だが……残りの二分は、何が足りないのだろうな……",
            ["DialogueId"] = 51153072,
            ["GUID"] = "800E6CE0",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153073,
            ["SpeakNpcId"] = 701091,
            },
        [51153073] = {
            ["Camera"] = "225.349609,-183.40332,129.71582,0.000022,-14.342556,161.450195,38.0,362.946472,false,Manual,2.8",
            ["Content"] = "我记得……记得……",
            ["ContentJP"] = "そうだな……たしか……",
            ["DialogueId"] = 51153073,
            ["GUID"] = "800E6D0A",
            ["LookAt"] = {
                [1] = "701091:n(701091)",
                },
            ["NextDialogue"] = 51153074,
            ["SpeakNpcId"] = 701091,
            },
        [51153074] = {
            ["Camera"] = "82.539062,236.600586,94.693359,0.000013,-1.542742,-109.15033,38.0,410.739655,false,Manual,2.8",
            ["Content"] = "你回想起了什么？",
            ["ContentJP"] = "何か思い出した？",
            ["DialogueId"] = 51153074,
            ["FacialId"] = {
                [1] = "100001:Doubt01",
                },
            ["GUID"] = "800E6D34",
            ["NextDialogue"] = 51153075,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:TilteHead_Start",
                [2] = "100001:ConfidentLRToExplainL_Start",
                },
            },
        [51153075] = {
            ["Camera"] = "-105.767578,-54.1875,3088.036133,0.0,12.999988,42.650269,11.0,362.946472,false,DoNotOverride,2.8",
            ["Content"] = "我想起十数年前，蒹葭浦还没犯烛阴之灾的日子。我和伙伴一同在河滩上玩泥沙、磨螺壳的时候。",
            ["ContentJP"] = "十数年前、この<Default note=\"text:けんか\">蒹葭</>の浦がまだ燭陰の禍に見舞われていなかった頃のことだ。仲間たちと一緒に河原で泥遊びをしたり、貝殻を磨いたりしていた。",
            ["DialogueId"] = 51153075,
            ["FinalCamera"] = "-2100.933594,-1892.0625,2461.760742,0.0,12.999988,42.650452,11.000002,362.946472,false,DoNotOverride,2.8",
            ["GUID"] = "800E6D5E",
            ["NextDialogue"] = 51153076,
            ["SpeakNpcId"] = 701091,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51153076] = {
            ["Content"] = "我想起那时也是这样的天，白云悠悠从头顶飘过。似乎永无烦恼，永无忧虑。",
            ["ContentJP"] = "あの日も今日のような、白い雲がゆったりと頭上を流れる空だった。悩みも、憂いも、何一つなかった。",
            ["DialogueId"] = 51153076,
            ["GUID"] = "800E6D88",
            ["NextDialogue"] = 51153077,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "100001:TilteHead_End",
                },
            },
        [51153077] = {
            ["Content"] = "是从什么时候开始，我决定当一名织星客的呢……又是从什么时候开始，我们各奔东西，各自万里未归，异乡为客的呢……",
            ["ContentJP"] = "一体いつから、私は<Default note=\"text:ほしおりびと\">星織人</>になろうと決めたのだろうか……そしていつから、私たちはバラバラになり、万里の遠くへ旅立ち、故郷に戻らぬ旅人となったのだろうな……",
            ["DialogueId"] = 51153077,
            ["GUID"] = "800E6DB2",
            ["NextDialogue"] = 51153078,
            ["SpeakNpcId"] = 701091,
            },
        [51153078] = {
            ["Camera"] = "0.871094,-16.166992,127.25293,0.000021,-6.342841,-89.151169,38.000008,179.802216,false,Manual,2.8",
            ["Content"] = "你最早喝到这碗茶，是在什么时候？",
            ["ContentJP"] = "ハクサさんが初めてその茶を飲んだのは、いつ？",
            ["DialogueId"] = 51153078,
            ["GUID"] = "800E6DDC",
            ["NextDialogue"] = 51153079,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLRToExplainL_End",
                },
            },
        [51153079] = {
            ["Camera"] = "7466.974609,-3541.548828,3565.794922,0.0,-6.200104,-34.800346,11.0,362.946472,false,DoNotOverride,2.8",
            ["Content"] = "我年幼时，有一次父亲带着我，沿着蒹葭浦走去浮星埠看船。路途遥远，我累极了，也兴奋极了。",
            ["ContentJP"] = "幼い頃、父に連れられて<Default note=\"text:けんか\">蒹葭</>の浦沿いを歩き、<Default note=\"text:うきほしのはとば\">浮星の埠</>の船を見に行った時だ。道のりは遠くてな、私は疲れ切っていたが、同時に興奮もしていた。",
            ["DialogueId"] = 51153079,
            ["FinalCamera"] = "10758.478516,-5829.231445,3130.332031,0.0,-6.200104,-34.800346,11.0,362.946472,false,DoNotOverride,2.8",
            ["GUID"] = "800E6E06",
            ["NextDialogue"] = 51153080,
            ["SpeakNpcId"] = 701091,
            ["ToFinalCameraBlendTime"] = 10,
            },
        [51153080] = {
            ["Content"] = "我们在茶摊喝茶，不远处的大海波光粼粼，商船穿梭往来，码头上人声喧哗，还是孩子的我，一下被这场景所深深吸引。",
            ["ContentJP"] = "茶屋で茶を飲んでいると、すぐ先の海がキラキラと輝き、商船が行き交い、港には活気ある声が響いていた。子供だった私は、一瞬でその光景に心を奪われたのだ。",
            ["DialogueId"] = 51153080,
            ["GUID"] = "800E6E30",
            ["NextDialogue"] = 51153081,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "100001:ConfidentLR_End",
                },
            },
        [51153081] = {
            ["Content"] = "也许从第一次见到大海起，就注定了我未来会远远地离开这片土地，走到天涯海角去。",
            ["ContentJP"] = "おそらく、初めて海を見たあの時から、私はいつかこの土地を遠く離れ、地の果てまで歩んでいく運命だったのかもしれない。",
            ["DialogueId"] = 51153081,
            ["GUID"] = "800E6E5A",
            ["NextDialogue"] = 51153082,
            ["SpeakNpcId"] = 701091,
            },
        [51153082] = {
            ["Content"] = "但是再一次见到这片天空，还是会感慨万千啊……",
            ["ContentJP"] = "だが、再びこの空の下に立つと、やはり感慨深い……",
            ["DialogueId"] = 51153082,
            ["GUID"] = "800E6E84",
            ["NextDialogue"] = 51153083,
            ["SpeakNpcId"] = 701091,
            },
        [51153083] = {
            ["Content"] = "（陈白沙默然不语，在地上躺了好一会儿，似乎在深思些什么。）",
            ["ContentJP"] = "（ハクサは黙り込み、しばらくそのまま地面に横たわり、何かを深く考え込んでいた。）",
            ["DialogueId"] = 51153083,
            ["GUID"] = "800E6EAE",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 51153084,
            ["SpeakNpcId"] = 0,
            ["TalkActionId"] = {
                [1] = "701091:Idle",
                },
            },
        [51153084] = {
            ["Camera"] = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
            ["Content"] = "小友，我明白了。",
            ["ContentJP"] = "ようやく悟ったよ。",
            ["DialogueId"] = 51153084,
            ["GUID"] = "800E6ED8",
            ["LookAt"] = {
                [1] = "701091:n(100001)",
                },
            ["NextDialogue"] = 51153085,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153085] = {
            ["Camera"] = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
            ["Content"] = "再也不会有和从前一模一样的茶叶的味道了，就像不会有和从前一样的日子。",
            ["ContentJP"] = "かつてと全く同じ茶の味など、もう二度と現れない。あの頃と同じ日々が、二度と戻ってこないのと同じようにな。",
            ["DialogueId"] = 51153085,
            ["GUID"] = "800E6F02",
            ["NextDialogue"] = 51153086,
            ["SpeakNpcId"] = 701091,
            },
        [51153086] = {
            ["Camera"] = "308.283203,-261.548828,90.578125,0.000047,4.057549,157.051544,30.0,450.096558,false,Manual,2.8",
            ["Content"] = "我所怀念的不过是逝去的岁月，和再也回不去的小时候。",
            ["ContentJP"] = "私が懐かしんでいたのは、ただ過ぎ去った歳月と、もう戻れない子供時代だったのだ。",
            ["DialogueId"] = 51153086,
            ["GUID"] = "800E6F2C",
            ["NextDialogue"] = 51153087,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_End",
                },
            },
        [51153087] = {
            ["Camera"] = "-58.130859,194.003906,181.458984,0.000058,-9.342407,-86.547867,30.0,228.692245,false,Manual,2.8",
            ["Content"] = "再见了，小友，这些报酬你请收好。",
            ["ContentJP"] = "さらばだ、若者。報酬を受け取ってくれ。",
            ["DialogueId"] = 51153087,
            ["GUID"] = "800E6F56",
            ["LookAt"] = {
                [1] = "701091:n(701091)",
                },
            ["NextDialogue"] = 51153088,
            ["Scripts"] = "SEQ{\
TurnTo{TurnToDescription{\"701091:p(-180)\"}},   PlayAnimation{ActorId{100001},AnimationId{\"RaiseHand_Start\"}}\
}",
            ["SpeakNpcId"] = 701091,
            },
        [51153088] = {
            ["Camera"] = "18.898438,5.989258,151.822266,0.000043,-13.742524,-94.34774,30.0,192.427872,false,Manual,2.8",
            ["Content"] = "你要去哪里？",
            ["ContentJP"] = "これからどこへ？",
            ["DialogueId"] = 51153088,
            ["FacialId"] = {
                [1] = "100001:Curious",
                },
            ["GUID"] = "800E6F80",
            ["NextDialogue"] = 51153089,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:RaiseHand_End",
                },
            },
        [51153089] = {
            ["Camera"] = "-104.441406,157.805664,256.822266,0.000024,-24.942291,-76.543663,50.0,400.0,false,Manual,2.8",
            ["Content"] = "已经过去的不可再追回，现在的一切尚在手中。",
            ["ContentJP"] = "過ぎ去ったものは取り戻せないが、今あるものはこの手の中にある。",
            ["DialogueId"] = 51153089,
            ["FinalCamera"] = "-104.441406,157.805664,256.822266,0.000024,-24.942291,-76.543663,50.0,210.0,false,Manual,2.8",
            ["GUID"] = "800E6FAA",
            ["NextDialogue"] = 51153090,
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            },
        [51153090] = {
            ["Content"] = "我已经喝不到二十年前的茶了，但是我现在仍然能和我的父亲一起散步、谈天说地、走去港口看船。",
            ["ContentJP"] = "二十年前の茶を飲むことはもう叶わんが、今ならまだ父と一緒に散歩をし、語らい、港まで船を見に行くことができる。",
            ["DialogueId"] = 51153090,
            ["GUID"] = "800E6FD4",
            ["NextDialogue"] = 51153091,
            ["SpeakNpcId"] = 701091,
            },
        [51153091] = {
            ["Camera"] = "609.125,169.490234,2.267578,0.0,7.999989,-155.538208,34.0,720.492676,false,Manual,2.8",
            ["Content"] = "我要回家了。",
            ["ContentJP"] = "私は、家に帰るよ。",
            ["DialogueId"] = 51153091,
            ["GUID"] = "800E6FFE",
            ["SpeakNpcId"] = 701091,
            ["TalkActionId"] = {
                [1] = "701091:Explain02_Start",
                },
            },
        [51153092] = {
            ["Content"] = "如今的浮星埠，比二十年前父亲带我来看船时更加热闹了。",
            ["ContentJP"] = "今の<Default note=\"text:うきほしのはとば\">浮星の埠</>は、二十年前に父上に連れられて船を見に来た時よりも、ずっと賑やかだ。",
            ["DialogueId"] = 51153092,
            ["GUID"] = "800E6FFF",
            ["SpeakNpcId"] = 701098,
            },
        [51153093] = {
            ["Content"] = "二十年过去，这里也成了你出发的地方了……",
            ["ContentJP"] = "二十年が経って、ここもお前が旅立つ場所になったのじゃなぁ……",
            ["DialogueId"] = 51153093,
            ["GUID"] = "800E7000",
            ["SpeakNpcId"] = 701099,
            },
        [51153094] = {
            ["Content"] = "小友，还是我略胜一筹！",
            ["ContentJP"] = "どうやら私のほうが一枚上手だったな",
            ["DialogueId"] = 51153094,
            ["GUID"] = "800E7001",
            ["SpeakNpcId"] = 701091,
            },
        [51154001] = {
            ["Content"] = "我就知道你会再来找我。",
            ["ContentJP"] = "また私のところへ来ると分かっていたよ。",
            ["DialogueId"] = 51154001,
            ["GUID"] = "800F054A",
            ["NextOptions"] = {
                [1] = 51154002,
                [2] = 51154003,
                },
            ["SpeakNpcId"] = 701096,
            },
        [51154002] = {
            ["Content"] = "说吧，还有什么事。",
            ["ContentJP"] = "単刀直入に聞こう。何の用だ？",
            ["DialogueId"] = 51154002,
            ["GUID"] = "800F0574",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51154004,
            },
        [51154003] = {
            ["Content"] = "你笑得太恶心了，到底还想说什么。",
            ["ContentJP"] = "薄気味悪い笑いだね。一体何が言いたい？",
            ["DialogueId"] = 51154003,
            ["GUID"] = "800F059E",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51154004,
            },
        [51154004] = {
            ["Content"] = "不用如此戒备，既然提到投资，自然是要再为你提供一些切实的便利。",
            ["ContentJP"] = "そう警戒せずとも。投資の話となれば、君にそれ相応の便宜を図ろうと思ってね。",
            ["DialogueId"] = 51154004,
            ["GUID"] = "800F05C8",
            ["NextDialogue"] = 51154005,
            ["SpeakNpcId"] = 701096,
            },
        [51154005] = {
            ["Content"] = "小友且看我这件藏品。",
            ["ContentJP"] = "このコレクションを見ていただきたい。",
            ["DialogueId"] = 51154005,
            ["GUID"] = "800F05F2",
            ["NextDialogue"] = 51154006,
            ["SpeakNpcId"] = 701096,
            },
        [51154006] = {
            ["Content"] = "玄色狴犴！",
            ["ContentJP"] = "<Default note=\"text:ビーアン\">狴犴</>！？",
            ["DialogueId"] = 51154006,
            ["GUID"] = "800F061C",
            ["NextDialogue"] = 51154007,
            ["SpeakNpcId"] = 100001,
            },
        [51154007] = {
            ["Content"] = "哈哈哈哈，放心。我虽手眼通天，但也有一些力所不及的憾事，就比如我的珍藏里始终少了一只<H>真正的玄色狴犴</>。",
            ["ContentJP"] = "はははは！案ずるな。私は万事に通じているつもりだが、それでも力の及ばぬことがある。例えば、私のコレクションには常に<H>本物の狴犴</>が欠けている、といったことだよ。",
            ["DialogueId"] = 51154007,
            ["GUID"] = "800F0646",
            ["NextDialogue"] = 51154008,
            ["SpeakNpcId"] = 701096,
            },
        [51154008] = {
            ["Content"] = "你眼前的玄色狴犴，不过是一个徒有其表的样子货罢了。",
            ["ContentJP"] = "君の目の前にいるのは、見かけ倒しの紛い物に過ぎん。",
            ["DialogueId"] = 51154008,
            ["GUID"] = "800F0670",
            ["NextDialogue"] = 51154009,
            ["SpeakNpcId"] = 701096,
            },
        [51154009] = {
            ["Content"] = "样子货？",
            ["ContentJP"] = "紛い物？",
            ["DialogueId"] = 51154009,
            ["GUID"] = "800F069A",
            ["NextDialogue"] = 51154010,
            ["SpeakNpcId"] = 100001,
            },
        [51154010] = {
            ["Content"] = "哦，这么说可能会让公尚师傅急得跳脚了。要说“样子货”也有点折辱了它，这多少还算得上是机枢派智慧的结晶。",
            ["ContentJP"] = "おっと、そんな言い方をすればコウショウが血相を変えて怒り出すかもしれんな。紛い物と呼ぶのは、いささかこいつへの侮辱になる。これは<Default note=\"text:きすうは\">機枢派</>の知恵の結晶と言っても差し支えないものだからな。",
            ["DialogueId"] = 51154010,
            ["GUID"] = "800F06C4",
            ["NextDialogue"] = 51154011,
            ["SpeakNpcId"] = 701096,
            },
        [51154011] = {
            ["Content"] = "它的运作原理繁琐冗长，想必你也不感兴趣。你只需要知道，公尚师傅打磨了很多年才让它像狴犴一样动起来。",
            ["ContentJP"] = "作動原理を長々と説明しても退屈だろう。コウショウが長年磨き上げたことで、ようやく本物の<Default note=\"text:ビーアン\">狴犴</>のように動くようになった、ということを理解できれば十分だ。",
            ["DialogueId"] = 51154011,
            ["GUID"] = "800F06EE",
            ["NextDialogue"] = 51154012,
            ["SpeakNpcId"] = 701096,
            },
        [51154012] = {
            ["Content"] = "只可惜，公尚师傅一开始造的那几只拟真狴犴，引来了悬衡派一群无聊的老顽固，念叨着什么“渎神”、“不敬”之类的，给他没收了，无趣。",
            ["ContentJP"] = "ただ残念なことに、コウショウが最初に作った数体の擬似狴犴は、懸衡派の年寄りの頑固者どもを呼び寄せてしまってね。「神を冒涜している」「不敬だ」だのと小言を並べ立てた挙げ句、没収していった。まったくつまらない話だよ。",
            ["DialogueId"] = 51154012,
            ["GUID"] = "800F06EF",
            ["NextDialogue"] = 51154024,
            ["SpeakNpcId"] = 701096,
            },
        [51154013] = {
            ["Content"] = "要不要骑上它试上一试？华胥幅员辽阔，小友全凭一双脚又能走到何处。就算日后去了其他地方，它也能充当你上天入地、纵情奔走的不错助力。",
            ["ContentJP"] = "一度、乗ってみてはいかがかな？この広大な<Default note=\"text:カショ\">華胥</>を、その足だけで歩き通すのは酷というもの。たとえ他地へ赴く際にも、天を翔け地を駆ける良き相棒となろう。",
            ["DialogueId"] = 51154013,
            ["GUID"] = "800F0742",
            ["NextOptions"] = {
                [1] = 51154014,
                [2] = 51154015,
                [3] = 51154016,
                },
            ["SpeakNpcId"] = 701096,
            },
        [51154014] = {
            ["Content"] = "你想要多少钱？",
            ["ContentJP"] = "いくらだ？",
            ["DialogueId"] = 51154014,
            ["GUID"] = "800F076C",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51154017,
            },
        [51154015] = {
            ["Content"] = "我是狩月人，白送我。",
            ["ContentJP"] = "{性别:僕|私}は月狩り人だ。タダなら貰ってやってもいい。",
            ["DialogueId"] = 51154015,
            ["GUID"] = "800F0796",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51154017,
            },
        [51154016] = {
            ["Content"] = "这么好的东西，应该不会随随便便送给我吧。",
            ["ContentJP"] = "これほどの代物を、無条件で譲ってくれるとは思えないけど。",
            ["DialogueId"] = 51154016,
            ["GUID"] = "800F07C0",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51154017,
            },
        [51154017] = {
            ["Content"] = "呵呵，白送的东西就是天底下最贵的东西，我若是直接给，你也不敢直接收吧。",
            ["ContentJP"] = "ふっ…タダより高いものはない。私が無償で差し出したとしても、君は懸念して受け取れないだろう？",
            ["DialogueId"] = 51154017,
            ["GUID"] = "800F07EA",
            ["NextDialogue"] = 51154018,
            ["SpeakNpcId"] = 701096,
            },
        [51154018] = {
            ["Content"] = "诶诶？原来本魔王大人送出去的东西这么珍贵吗！",
            ["ContentJP"] = "ええーっ！？じゃあ、この魔王様があげたものって、そんなに貴重だったのか！？",
            ["DialogueId"] = 51154018,
            ["GUID"] = "800F0814",
            ["NextDialogue"] = 51154019,
            ["SpeakNpcId"] = 200002,
            },
        [51154019] = {
            ["Content"] = "哈哈哈哈哈，这是皎皎之民的幽默吗，有意思，真是有意思。",
            ["ContentJP"] = "ははははは！これがルーナ族のユーモアか。面白い、実に面白い。",
            ["DialogueId"] = 51154019,
            ["GUID"] = "800F083E",
            ["NextDialogue"] = 51154020,
            ["SpeakNpcId"] = 701096,
            },
        [51154020] = {
            ["Content"] = "呜哇啊啊啊，小仆从救命，他看起来要吃了我一样！",
            ["ContentJP"] = "うわわわっ、助けてくれ我が下僕！あの人、スノウを取って食おうという顔をしてるぞー！",
            ["DialogueId"] = 51154020,
            ["GUID"] = "800F0868",
            ["NextDialogue"] = 51154021,
            ["SpeakNpcId"] = 200002,
            },
        [51154021] = {
            ["Content"] = "好，好，好。作为博我一笑的报酬，这“假狴犴”我就不收你钱了。",
            ["ContentJP"] = "はははは、よろしい。私を笑わせてくれた報酬として、この「偽の狴犴」の代金は不要としよう。",
            ["DialogueId"] = 51154021,
            ["GUID"] = "800F0892",
            ["NextDialogue"] = 51154022,
            ["SpeakNpcId"] = 701096,
            },
        [51154022] = {
            ["Content"] = "言尽于此，慢走不送。日后若是有什么其他想要的珍藏，或是关于珍藏有什么疑问的话，再来这里找我吧。",
            ["ContentJP"] = "話はこれだけだ。他にも何か欲しいものや、コレクションについて疑問があれば、またここへ来るといい。",
            ["DialogueId"] = 51154022,
            ["GUID"] = "800F08BC",
            ["NextDialogue"] = 51154023,
            ["SpeakNpcId"] = 701096,
            },
        [51154023] = {
            ["Content"] = "微茫市的大门，随时为你敞开。",
            ["ContentJP"] = "<Default note=\"text:びぼうし\">微芒市</>の門は、いつでも君のために開いているよ。",
            ["DialogueId"] = 51154023,
            ["GUID"] = "800F08E6",
            ["SpeakNpcId"] = 701096,
            },
        [51154024] = {
            ["Content"] = "但公尚对他的拟真狴犴宝贝得很，怎么舍得就此放弃。所以后来的拟真狴犴啊，他都做成了玄色狴犴的样子，那些香官才不得不作罢。",
            ["ContentJP"] = "けれど、あのコウショウが「擬似狴犴」を手放すと思うか？そんなに甘い話じゃない。あれからの「擬似狴犴」は、「玄狴」の外観を模して作り上げた。香官たちも、非難のしようがなくなったはずだ。",
            ["DialogueId"] = 51154024,
            ["GUID"] = "800F0718",
            ["NextDialogue"] = 51154013,
            ["SpeakNpcId"] = 701096,
            },
        [51155001] = {
            ["Content"] = "小仆从小仆从，你刚刚听到没有！",
            ["ContentJP"] = "我が下僕よ、今の聞いたか？",
            ["DialogueId"] = 51155001,
            ["GUID"] = "800FA95A",
            ["NextDialogue"] = 51155002,
            ["SpeakNpcId"] = 200002,
            },
        [51155002] = {
            ["Content"] = "听到什么？",
            ["ContentJP"] = "何を？",
            ["DialogueId"] = 51155002,
            ["GUID"] = "800FA984",
            ["NextDialogue"] = 51155003,
            ["SpeakNpcId"] = 100001,
            },
        [51155003] = {
            ["Content"] = "“大烟花”！！",
            ["ContentJP"] = "「グレートグローリー」だ！！",
            ["DialogueId"] = 51155003,
            ["GUID"] = "800FA9AE",
            ["NextDialogue"] = 51155004,
            ["SpeakNpcId"] = 200002,
            },
        [51155004] = {
            ["Content"] = "刚刚黑市那个家伙在用通讯器和同伙聊天，说他们从帝国进了一批“大烟花”的货！那可是“大烟花”啊——",
            ["ContentJP"] = "さっきの闇市の奴、通信機で仲間と話していたのだ。「帝国から『グレートグローリー』を仕入れた」って！あれはあの「グレートグローリー」なのだぞ——",
            ["DialogueId"] = 51155004,
            ["GUID"] = "800FA9D8",
            ["NextDialogue"] = 51155005,
            ["SpeakNpcId"] = 200002,
            },
        [51155005] = {
            ["Content"] = "你记得吧？狩月人委托排行榜上，最危险、最艰辛、最有挑战性的委托之一，就是拆掉神弃者同盟安装的超级危险炸弹“大烟花”！",
            ["ContentJP"] = "覚えてるだろう？月狩り人の依頼ランキングでも、もっとも危険で、困難で、やりがいのある依頼の一つ……それがフォーセイクン同盟が仕掛ける超危険爆弾「グレートグローリー」の解除なのだ！",
            ["DialogueId"] = 51155005,
            ["GUID"] = "800FAA02",
            ["NextDialogue"] = 51155006,
            ["SpeakNpcId"] = 200002,
            },
        [51155006] = {
            ["Content"] = "要是在这里爆炸了，不知道会炸死多少人！这里的摊子通通都要被炸上天！天啊，这简直就是——烟津渡史上最大危机！",
            ["ContentJP"] = "もしここで爆発したら、犠牲者が何人出るのか……この辺の屋台も全部空にぶっ飛ぶぞ！ああ、これはまさに——<Default note=\"text:えんしんと\">煙津渡</>史上、最大の危機なのだ！",
            ["DialogueId"] = 51155006,
            ["GUID"] = "800FAA2C",
            ["NextOptions"] = {
                [1] = 51155007,
                [2] = 51155008,
                },
            ["SpeakNpcId"] = 200002,
            },
        [51155007] = {
            ["Content"] = "没想到黑市的人居然如此猖狂，必须去阻止他。",
            ["ContentJP"] = "まさか闇市の連中がこんなに大胆だとは。阻止しないと。",
            ["DialogueId"] = 51155007,
            ["GUID"] = "800FAA56",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51155009,
            },
        [51155008] = {
            ["Content"] = "那完了，我们跑路吧。",
            ["ContentJP"] = "もうおしまいだ。逃げるんだよ！ ",
            ["DialogueId"] = 51155008,
            ["GUID"] = "800FAA80",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51155009,
            },
        [51155009] = {
            ["Content"] = "其他人好像还没意识到问题的严重性，这种时候只能靠小仆从和本魔王大人来拯救世界了！",
            ["ContentJP"] = "他の人たちはまだ事の重大さに気づいてないようだ。こういう時は、この魔王様と下僕である{nickname}が世界を救うしかない！",
            ["DialogueId"] = 51155009,
            ["GUID"] = "800FAAAA",
            ["SpeakNpcId"] = 200002,
            },
        [51155010] = {
            ["Content"] = "这次的大烟花……",
            ["ContentJP"] = "「今回のグレートグローリー……」と吹き出しが出ているNPCとインタラクト",
            ["DialogueId"] = 51155010,
            ["GUID"] = "800FAAD4",
            ["SpeakNpcId"] = 701095,
            },
        [51155101] = {
            ["Content"] = "我们先去跟他接触一下，稳住他，探探口风。要是把他逼急了直接在这种地方引爆“大烟花”，那就危险了。",
            ["ContentJP"] = "まずは接触して、落ち着かせながら情報を聞き出そう。下手に追い詰めて、こんな場所で「グレートグローリー」を爆発させられたら取り返しがつかない。",
            ["DialogueId"] = 51155101,
            ["GUID"] = "800FB9C2",
            ["SpeakNpcId"] = 100001,
            },
        [51155201] = {
            ["Content"] = "听说你这里能买到“大烟花”？",
            ["ContentJP"] = "ここで「グレートグローリー」が買えると聞いた。",
            ["DialogueId"] = 51155201,
            ["GUID"] = "800FCA2A",
            ["NextDialogue"] = 51155202,
            ["SpeakNpcId"] = 100001,
            },
        [51155202] = {
            ["Content"] = "……什么人？谁介绍你来的？",
            ["ContentJP"] = "……何者だ？誰の紹介だ。",
            ["DialogueId"] = 51155202,
            ["GUID"] = "800FCA54",
            ["NextOptions"] = {
                [1] = 51155203,
                [2] = 51155204,
                },
            ["SpeakNpcId"] = 701093,
            },
        [51155203] = {
            ["Content"] = "别紧张，我也想买枚“大烟花”。",
            ["ContentJP"] = "落ち着いて。私も「グレートグローリー」を一枚買いたいと思ってね。",
            ["DialogueId"] = 51155203,
            ["GUID"] = "800FCA7E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51155205,
            },
        [51155204] = {
            ["Content"] = "我可是虬先生的贵客。",
            ["ContentJP"] = "私はキョウンの客人だ。",
            ["DialogueId"] = 51155204,
            ["GUID"] = "800FCAA8",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51155205,
            },
        [51155205] = {
            ["Content"] = "……你？看着很是面生。对不住了，咱家的货只卖熟人。",
            ["ContentJP"] = "……あんたが？見ない顔だな。悪いが、うちは馴染みの客にしか売らない主義でね。",
            ["DialogueId"] = 51155205,
            ["GUID"] = "800FCAD2",
            ["NextDialogue"] = 51155206,
            ["SpeakNpcId"] = 701093,
            },
        [51155206] = {
            ["Content"] = "小仆从小仆从，不行啊，这样他要怀疑我们了……",
            ["ContentJP"] = "ダメだ、我が下僕。このままじゃ怪しまれる……",
            ["DialogueId"] = 51155206,
            ["GUID"] = "800FCAFC",
            ["NextOptions"] = {
                [1] = 51155207,
                [2] = 51155208,
                },
            ["SpeakNpcId"] = 200002,
            },
        [51155207] = {
            ["Content"] = "谨慎是没错，但也没必要跟钱过不去吧。",
            ["ContentJP"] = "慎重なのはいいけど、金を棒に振る必要はないよ。",
            ["DialogueId"] = 51155207,
            ["GUID"] = "800FCB26",
            ["ImprPlusId"] = 1206,
            ["NextDialogue"] = 51155209,
            },
        [51155208] = {
            ["Content"] = "好你在这等着，我去叫秦虬那老东西来一趟。",
            ["ContentJP"] = "分かった、そこで待ってろ。キョウンのやつを呼んでくる。",
            ["DialogueId"] = 51155208,
            ["GUID"] = "800FCB50",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51155209,
            },
        [51155209] = {
            ["Content"] = "嘶……行吧行吧，今天我就破个例，勉为其难地卖你好了。但你记得，出去以后，别说这“大烟花”是在微茫市买的。",
            ["ContentJP"] = "チッ……分かったよ。今日だけは特別だ、売ってやる。だがな、ここを出たら、この「グレートグローリー」を<Default note=\"text:びぼうし\">微芒市</>で買ったとは口外するなよ。",
            ["DialogueId"] = 51155209,
            ["GUID"] = "800FCB7A",
            ["NextDialogue"] = 51155210,
            ["SpeakNpcId"] = 701093,
            },
        [51155210] = {
            ["Content"] = "不然坏了我和老主顾们定下的规矩，我到时候也不好给其他人交代。",
            ["ContentJP"] = "常連さんたちとのルールを破ることになっちまうからな。そうなったら他の連中に示しがつかねえ。",
            ["DialogueId"] = 51155210,
            ["GUID"] = "800FCBA4",
            ["NextDialogue"] = 51155211,
            ["SpeakNpcId"] = 701093,
            },
        [51155211] = {
            ["Content"] = "啊？？很，很多人买吗？",
            ["ContentJP"] = "えっ、そ、そんなに客がいるの{性别:か|}？",
            ["DialogueId"] = 51155211,
            ["GUID"] = "800FCBCE",
            ["NextDialogue"] = 51155212,
            ["SpeakNpcId"] = 100001,
            },
        [51155212] = {
            ["Content"] = "不然呢，这烛阴之灾害得商路阻断，好多原材料运不过来。我这批“大烟花”……嘿嘿，可是花了点门路从海伯利亚搞来的呢。",
            ["ContentJP"] = "当たり前だろ。<Default note=\"text:しょくいん\">燭陰</>の禍のせいで商路が断たれて、原材料がなかなか入ってこないんだ。うちの「グレートグローリー」は……へへっ、ちょっとしたコネを使ってヒュペリアから取り寄せたんだぜ。",
            ["DialogueId"] = 51155212,
            ["GUID"] = "800FCBF8",
            ["NextDialogue"] = 51155213,
            ["SpeakNpcId"] = 701093,
            },
        [51155213] = {
            ["Content"] = "今年的“大烟花”卖的可好了，有个大客户直接要了一半，说这不奉香大典快到了吗，他打算去百年春搞点大动静。",
            ["ContentJP"] = "今年の「グレートグローリー」は売れ行きが良くてな。ある大口の客なんか、半分も買い占めていったよ。「<Default note=\"text:ほうこうのぎ\">奉香の儀</>が近いから、<Default note=\"text:ももとき\">百年春</>でドカンと派手にやるつもりらしい。",
            ["DialogueId"] = 51155213,
            ["GUID"] = "800FCC22",
            ["NextDialogue"] = 51155214,
            ["SpeakNpcId"] = 701093,
            },
        [51155214] = {
            ["Content"] = "完了完了完了，这要是一引爆，整个百年春岂不是都要——",
            ["ContentJP"] = "やばいやばい、あんな大量に爆発したら、<Default note=\"text:ももとき\">百年春</>が丸ごと——",
            ["DialogueId"] = 51155214,
            ["GUID"] = "800FCC4C",
            ["NextDialogue"] = 51155215,
            ["SpeakNpcId"] = 200002,
            },
        [51155215] = {
