        [51155608] = {
            ["Content"] = "（黑市商人们离开了，只留下你和白呆愣在原地。随着微茫市上空绽放起了第一道烟花，烟津渡各处的天空也陆陆续续升起了五颜六色的花火。）",
            ["ContentJP"] = "（闇商人たちは去り、あなたとスノウだけがその場に呆然と立ち尽くした。微芒市の空に一発目の花火が上がったのを合図に、<Default note=\"text:えんしんと\">煙津渡</>のあちこちで色とりどりの花火が次々と打ち上がり始めた。）",
            ["DialogueId"] = 51155608,
            ["GUID"] = "80100CF0",
            ["NextDialogue"] = 51155609,
            },
        [51155609] = {
            ["Content"] = "这是……什么情况……",
            ["ContentJP"] = "どういう……こと？",
            ["DialogueId"] = 51155609,
            ["GUID"] = "80100D1A",
            ["NextDialogue"] = 51155610,
            ["SpeakNpcId"] = 100001,
            },
        [51155610] = {
            ["Content"] = "原来……他说的“大烟花”，真的就只是“大烟花”啊……",
            ["ContentJP"] = "なあんだ……あいつの言ってた「グレートグローリー」って、ただのハナビダマだったのか……",
            ["DialogueId"] = 51155610,
            ["GUID"] = "80100D44",
            ["NextOptions"] = {
                [1] = 51155611,
                [2] = 51155613,
                },
            ["SpeakNpcId"] = 200002,
            },
        [51155611] = {
            ["Content"] = "看来是我们误会了，后面去找人家道个歉吧。",
            ["ContentJP"] = "どうやら{性别:僕|私}たちの勘違いだったみたいだ。後でちゃんと謝りに行こう。",
            ["DialogueId"] = 51155611,
            ["GUID"] = "80100D6E",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51155612,
            },
        [51155612] = {
            ["Content"] = "唔……你说得对……",
            ["ContentJP"] = "うう……そうだな……",
            ["DialogueId"] = 51155612,
            ["GUID"] = "80100D98",
            ["NextDialogue"] = 51155615,
            ["SpeakNpcId"] = 200002,
            },
        [51155613] = {
            ["Content"] = "下次再颠倒是非我就把你扔在华胥，换锦鲤皎皎跟我回冰湖城。",
            ["ContentJP"] = "今度あんなデタラメを言ったら、華胥に置いていくから。代わりにニシキちゃんと一緒にアイスレイク城に戻る。",
            ["DialogueId"] = 51155613,
            ["GUID"] = "80100DC2",
            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51155614,
            },
        [51155614] = {
            ["Content"] = "不要啊呜呜呜呜呜……",
            ["ContentJP"] = "それは嫌だあぁぁ……",
            ["DialogueId"] = 51155614,
            ["GUID"] = "80100DEC",
            ["NextDialogue"] = 51155615,
            ["SpeakNpcId"] = 200002,
            },
        [51155615] = {
            ["Content"] = "不过，小仆从，这里的“大烟花”，可真漂亮呐……",
            ["ContentJP"] = "ところで我が下僕。ここの「グレートグローリー」、すっごく綺麗だな……",
            ["DialogueId"] = 51155615,
            ["GUID"] = "80100E16",
            ["SpeakNpcId"] = 200002,
            },
        [51155701] = {
            ["Content"] = "关于之前微茫市的“大烟花”……",
            ["ContentJP"] = "この前の<Default note=\"text:びぼうし\">微芒市</>の「グレートグローリー」について……",
            ["DialogueId"] = 51155701,
            ["GUID"] = "80101C32",
            ["NextDialogue"] = 51155702,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 200315,
                    },
                },
            },
        [51155702] = {
            ["Content"] = "哈哈哈，“大烟花”那事我听说了，这种小事就不必道歉了。毕竟，这种趣味横生的事情可不多见。",
            ["ContentJP"] = "ははは、その件なら耳に入っているよ。あのような些細なことで謝罪は不要だ。何より、これほど趣深い出来事は滅多にないからな。",
            ["DialogueId"] = 51155702,
            ["GUID"] = "80101C5C",
            ["SpeakNpcId"] = 210119,
            },
        [51156001] = {
            ["Content"] = "就是盯着那吹糖人的店家多看了会，结果准备掏钱买的时候，口袋里居然空空如也。",
            ["DialogueId"] = 51156001,
            ["GUID"] = "80104D6A",
            ["NextDialogue"] = 51156002,
            ["SpeakNpcId"] = 701113,
            },
        [51156002] = {
            ["Content"] = "难不成是被人偷了去？还是丢在了什么地方？",
            ["DialogueId"] = 51156002,
            ["GUID"] = "80104D94",
            ["NextOptions"] = {
                [1] = 51156003,
                [2] = 51156005,
                },
            ["SpeakNpcId"] = 701113,
            },
        [51156003] = {
            ["Content"] = "需要帮忙吗？",
            ["DialogueId"] = 51156003,
            ["GUID"] = "80104DBE",
            ["ImprPlusId"] = 1207,
            ["NextDialogue"] = 51156004,
            },
        [51156004] = {
            ["Content"] = "谢谢你，我的钱袋子好像不见了，不过我也记不起来丢在什么地方，也许……也许被人顺走了也说不定……",
            ["DialogueId"] = 51156004,
            ["GUID"] = "80104DE8",
            ["NextDialogue"] = 51156007,
            ["SpeakNpcId"] = 701113,
            },
        [51156005] = {
            ["Content"] = "华胥也有小偷小盗的事情？",
            ["DialogueId"] = 51156005,
            ["GUID"] = "80104E12",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51156006,
            },
        [51156006] = {
            ["Content"] = "说……说的也是，如果真是被偷了应该也会有狴犴相助才对……",
            ["DialogueId"] = 51156006,
            ["GUID"] = "80104E3C",
            ["NextDialogue"] = 51156007,
            ["SpeakNpcId"] = 701113,
            },
        [51156007] = {
            ["Content"] = "我还是再找找吧，多谢你。",
            ["DialogueId"] = 51156007,
            ["GUID"] = "80104E66",
            ["SpeakNpcId"] = 701113,
            },
        [51156008] = {
            ["Content"] = "我的钱袋子呢？我的钱袋子怎么不见了？",
            ["DialogueId"] = 51156008,
            ["GUID"] = "80104E90",
            ["NextDialogue"] = 51156009,
            ["SpeakNpcId"] = 701113,
            },
        [51156009] = {
            ["Content"] = "找了好半天也没找着，这可怎么办，我回家的船票还没买呢……",
            ["DialogueId"] = 51156009,
            ["GUID"] = "80104EBA",
            ["NextDialogue"] = 51156010,
            ["SpeakNpcId"] = 701113,
            },
        [51156010] = {
            ["Content"] = "咦，又是你？你找到我的钱袋子了吗？还是说……",
            ["DialogueId"] = 51156010,
            ["GUID"] = "80104EE4",
            ["NextOptions"] = {
                [1] = 51156011,
                [2] = 51156014,
                },
            ["SpeakNpcId"] = 701113,
            },
        [51156011] = {
            ["Content"] = "没找到。",
            ["DialogueId"] = 51156011,
            ["GUID"] = "80104F0E",
            ["NextDialogue"] = 51156012,
            },
        [51156012] = {
            ["Content"] = "啊……那也没办法了……虽然也不是什么大钱，但是好歹也是我出来玩带的所有资金了。",
            ["DialogueId"] = 51156012,
            ["GUID"] = "80104F38",
            ["NextDialogue"] = 51156013,
            ["SpeakNpcId"] = 701113,
            },
        [51156013] = {
            ["Content"] = "既然找不到，只能去求助天禄司，看看他们有没有办法临时安置一段时间，等家人寄钱来再解燃眉之急。",
            ["DialogueId"] = 51156013,
            ["GUID"] = "80104F62",
            ["NextOptions"] = {
                [1] = 51156014,
                [2] = 51156017,
                },
            ["SpeakNpcId"] = 701113,
            },
        [51156014] = {
            ["Content"] = "你不是皓京本地的？",
            ["DialogueId"] = 51156014,
            ["GUID"] = "80104F8C",
            ["NextDialogue"] = 51156015,
            },
        [51156015] = {
            ["Content"] = "是啊，我从烟津渡来，坐了好久的船，听说皓京是个大城市，今日一见果然名不虚传，瞧瞧这建筑多气派！商业街也比咱们那繁华多了。",
            ["DialogueId"] = 51156015,
            ["GUID"] = "80104FB6",
            ["NextDialogue"] = 51156016,
            ["SpeakNpcId"] = 701113,
            },
        [51156016] = {
            ["Content"] = "就是这么多的新鲜玩意，看得我眼花缭乱，这不是，钱袋子也没注意守住，丢了！",
            ["DialogueId"] = 51156016,
            ["GUID"] = "80104FE0",
            ["NextOptions"] = {
                [1] = 51156022,
                },
            ["SpeakNpcId"] = 701113,
            },
        [51156017] = {
            ["Content"] = "求助……天禄司？",
            ["DialogueId"] = 51156017,
            ["GUID"] = "8010500A",
            ["NextDialogue"] = 51156018,
            },
        [51156018] = {
            ["Content"] = "第一次听说的时候，我也觉得很奇怪，明明是三司之一，怎么平民百姓的蝇头小事也管。",
            ["DialogueId"] = 51156018,
            ["GUID"] = "80105034",
            ["NextDialogue"] = 51156019,
            ["SpeakNpcId"] = 701113,
            },
        [51156019] = {
            ["Content"] = "所以我刚刚便顺便抓了个皓京本地人问询。他给的解释是说，毕竟狴犴大人管的只是那些作奸犯科之事，还有许多是狴犴无暇顾及或是无法顾及的。",
            ["DialogueId"] = 51156019,
            ["GUID"] = "8010505E",
            ["NextDialogue"] = 51156020,
            ["SpeakNpcId"] = 701113,
            },
        [51156020] = {
            ["Content"] = "要是让应天尉插手吧，那也有些大材小用。所以天禄司只能承担了这皓京的一些民生问题，专门选了一些人来处理。",
            ["DialogueId"] = 51156020,
            ["GUID"] = "80105088",
            ["NextDialogue"] = 51156021,
            ["NextOptions"] = {
                [1] = 51156022,
                },
            ["SpeakNpcId"] = 701113,
            },
        [51156021] = {
            ["Content"] = "你看我这事，要是求助无门，岂不是叫天天不应，叫地地不灵了？还好有这样的规矩在，不过啊，我在烟津渡之时，百年春也承担这般功能。",
            ["DialogueId"] = 51156021,
            ["GUID"] = "801050B2",
            ["SpeakNpcId"] = 701113,
            },
        [51156022] = {
            ["Content"] = "先不聊了。",
            ["DialogueId"] = 51156022,
            ["GUID"] = "801050DC",
            ["NextDialogue"] = 51156023,
            },
        [51156023] = {
            ["Content"] = "我看这有好些朋友要帮我找钱包，皓京还是好心人多啊。",
            ["DialogueId"] = 51156023,
            ["GUID"] = "80105106",
            ["SpeakNpcId"] = 701113,
            },
        [51156024] = {
            ["Content"] = "我的钱袋子呢？我的钱袋子怎么不见了？",
            ["DialogueId"] = 51156024,
            ["GUID"] = "80104D6B",
            ["NextDialogue"] = 51156001,
            ["SpeakNpcId"] = 701113,
            },
        [51156101] = {
            ["Content"] = "要我说，那位姑娘何必再找那钱袋子，她自从进了这条街开始，我便一直盯着她的一举一动，她接触过的人里面，最有嫌疑的，就是刚才那吹糖人的小贩！",
            ["DialogueId"] = 51156101,
            ["GUID"] = "80105DD2",
            ["NextOptions"] = {
                [1] = 51156102,
                [2] = 51156109,
                },
            ["SpeakNpcId"] = 701114,
            },
        [51156102] = {
            ["Content"] = "怎么推断出的结果？",
            ["DialogueId"] = 51156102,
            ["GUID"] = "80105DFC",
            ["NextDialogue"] = 51156103,
            },
        [51156103] = {
            ["Content"] = "她与那么多人都擦肩而过，只在那糖人摊前停了片刻，排除所有嫌疑，那必然是这一种可能了！",
            ["DialogueId"] = 51156103,
            ["GUID"] = "80105E26",
            ["NextOptions"] = {
                [1] = 51156104,
                [2] = 51156107,
                },
            ["SpeakNpcId"] = 701114,
            },
        [51156104] = {
            ["Content"] = "她在摊子前停下来，难道不是为了看人吹糖人吗？",
            ["DialogueId"] = 51156104,
            ["GUID"] = "80105E50",
            ["NextDialogue"] = 51156105,
            },
        [51156105] = {
            ["Content"] = "的确如此，但你可曾听说过一种秘术，利用博人眼球的戏码转移他人的注意力，再用高超到人眼看不清的手上功夫，将人随身携带之物偷走！",
            ["DialogueId"] = 51156105,
            ["GUID"] = "80105E7A",
            ["NextDialogue"] = 51156106,
            ["SpeakNpcId"] = 701114,
            },
        [51156106] = {
            ["Content"] = "这便是那卖糖人的摊主所施之法！",
            ["DialogueId"] = 51156106,
            ["GUID"] = "80105EA4",
            ["NextOptions"] = {
                [1] = 51156112,
                },
            ["SpeakNpcId"] = 701114,
            },
        [51156107] = {
            ["Content"] = "你的推断没有任何依据。",
            ["DialogueId"] = 51156107,
            ["GUID"] = "80105ECE",
            ["NextDialogue"] = 51156108,
            },
        [51156108] = {
            ["Content"] = "如何没有依据，你根本不了解这个卖糖人的小贩，他就是靠这些花招来搏人开心。哼……你大可不信我，等到我拆穿他，你们就知道了！",
            ["DialogueId"] = 51156108,
            ["GUID"] = "80105EF8",
            ["NextOptions"] = {
                [1] = 51156112,
                },
            ["SpeakNpcId"] = 701114,
            },
        [51156109] = {
            ["Content"] = "你为何一直盯着她看？",
            ["DialogueId"] = 51156109,
            ["GUID"] = "80105F22",
            ["NextDialogue"] = 51156110,
            },
        [51156110] = {
            ["Content"] = "我可没看她！我一直看的是那心怀叵测的糖人摊主！自从他把摊子开在我隔壁之后，我这客人便都被他那诡异的戏码博去了眼球！",
            ["DialogueId"] = 51156110,
            ["GUID"] = "80105F4C",
            ["NextDialogue"] = 51156111,
            ["SpeakNpcId"] = 701114,
            },
        [51156111] = {
            ["Content"] = "所以我便整日盯着他，我定要盯出他做了什么坏事！好早日去检举这家伙！",
            ["DialogueId"] = 51156111,
            ["GUID"] = "80105F76",
            ["NextOptions"] = {
                [1] = 51156112,
                },
            ["SpeakNpcId"] = 701114,
            },
        [51156112] = {
            ["Content"] = "要是他真偷了，狴犴为什么不来抓他？",
            ["DialogueId"] = 51156112,
            ["GUID"] = "80105FA0",
            ["NextDialogue"] = 51156113,
            },
        [51156113] = {
            ["Content"] = "狴犴大人……在路上了，迟早会来的！你这人不懂事，我懒得和你废话！",
            ["DialogueId"] = 51156113,
            ["GUID"] = "80105FCA",
            ["SpeakNpcId"] = 701114,
            },
        [51156114] = {
            ["Content"] = "定是那油嘴滑舌的小贩子偷的！",
            ["DialogueId"] = 51156114,
            ["GUID"] = "80105DD1",
            ["NextDialogue"] = 51156101,
            ["SpeakNpcId"] = 701114,
            },
        [51156201] = {
            ["Content"] = "丢钱袋的姑娘别急，我在家中别称寻物仙人，我老婆乱丢的耳坠和挂饰，我回回都找得到！",
            ["DialogueId"] = 51156201,
            ["GUID"] = "80106E3A",
            ["NextDialogue"] = 51156202,
            ["SpeakNpcId"] = 701115,
            },
        [51156202] = {
            ["Content"] = "寻物，我有一简单之法，出自无穷藏派真人传授，十分有效！",
            ["DialogueId"] = 51156202,
            ["GUID"] = "80106E64",
            ["NextOptions"] = {
                [1] = 51156203,
                },
            ["SpeakNpcId"] = 701115,
            },
        [51156203] = {
            ["Content"] = "我挺好奇，你能给我说说吗？",
            ["DialogueId"] = 51156203,
            ["GUID"] = "80106E8E",
            ["ImprPlusId"] = 1208,
            ["NextDialogue"] = 51156204,
            },
        [51156204] = {
            ["Content"] = "勤奋好学定是好事，但现在最紧要之事还是帮这位可怜的外乡客找到丢失的钱包，等我找到了再详细和你说说吧！",
            ["DialogueId"] = 51156204,
            ["GUID"] = "80106EB8",
            ["SpeakNpcId"] = 701115,
            },
        [51156205] = {
            ["Content"] = "诶？怎么就是找不到呢？",
            ["DialogueId"] = 51156205,
            ["GUID"] = "80106EE2",
            ["NextDialogue"] = 51156206,
            ["SpeakNpcId"] = 701115,
            },
        [51156206] = {
            ["Content"] = "明明在家中寻物之时都十分好用，怎么到了这大街上就一点作用都没了？还是我学习之时不够认真，才让这寻物之法大打折扣！",
            ["DialogueId"] = 51156206,
            ["GUID"] = "80106F0C",
            ["NextDialogue"] = 51156207,
            ["SpeakNpcId"] = 701115,
            },
        [51156207] = {
            ["Content"] = "是你？我还是没找着那位外乡客的钱包，不过看起来她倒是也接受了这事……刚才还来问我要是真丢了要去何处求助。",
            ["DialogueId"] = 51156207,
            ["GUID"] = "80106F36",
            ["NextDialogue"] = 51156208,
            ["SpeakNpcId"] = 701115,
            },
        [51156208] = {
            ["Content"] = "不过我还是觉得很奇怪，我这寻物之法为何就是不灵验了呢？",
            ["DialogueId"] = 51156208,
            ["GUID"] = "80106F60",
            ["NextOptions"] = {
                [1] = 51156209,
                },
            ["SpeakNpcId"] = 701115,
            },
        [51156209] = {
            ["Content"] = "寻物之法究竟是什么？",
            ["DialogueId"] = 51156209,
            ["GUID"] = "80106F8A",
            ["NextDialogue"] = 51156210,
            },
        [51156210] = {
            ["Content"] = "诶呀，这方法，说起来是又复杂又简单，你要是愿意听，我就和你说道说道，就是可能有些长。",
            ["DialogueId"] = 51156210,
            ["GUID"] = "80106FB4",
            ["NextOptions"] = {
                [1] = 51156211,
                },
            ["SpeakNpcId"] = 701115,
            },
        [51156211] = {
            ["Content"] = "你说吧。",
            ["DialogueId"] = 51156211,
            ["GUID"] = "80106FDE",
            ["NextDialogue"] = 51156212,
            },
        [51156212] = {
            ["Content"] = "诶呀，你果然是个勤奋好学的家伙。是这样的，首先呢，你得确认丢东西的日子，上到月份，下到具体时间，越详细越好。",
            ["DialogueId"] = 51156212,
            ["GUID"] = "80107008",
            ["NextDialogue"] = 51156213,
            ["SpeakNpcId"] = 701115,
            },
        [51156213] = {
            ["Content"] = "以月份来算，一月有31天的为大，一月有30天的为小，如月即为平。",
            ["DialogueId"] = 51156213,
            ["GUID"] = "80107032",
            ["NextDialogue"] = 51156214,
            ["SpeakNpcId"] = 701115,
            },
        [51156214] = {
            ["Content"] = "大的话，要按天、地、春、星、人、时、风、利、明循环算，小，或平，则按天、明、利、风、时、人、星、春、地来算。",
            ["DialogueId"] = 51156214,
            ["GUID"] = "8010705C",
            ["NextOptions"] = {
                [1] = 51156215,
                },
            ["SpeakNpcId"] = 701115,
            },
        [51156215] = {
            ["Content"] = "等等等等……你给我绕糊涂了，你说的这些字是什么意思？",
            ["DialogueId"] = 51156215,
            ["GUID"] = "80107086",
            ["NextDialogue"] = 51156216,
            },
        [51156216] = {
            ["Content"] = "这天、春、星、人，分别代表的就是往西、西南、北、南方去找。至于地，是说此物过两天会自己出现。",
            ["DialogueId"] = 51156216,
            ["GUID"] = "801070B0",
            ["NextDialogue"] = 51156217,
            ["SpeakNpcId"] = 701115,
            },
        [51156217] = {
            ["Content"] = "时呢，是说被偷咯，难找嘞！风是他一时疏忽，或者压根没仔细去寻，利是此物被他熟悉之人拿走了，至于明……我给我那婆娘算时多半都是明，因为那物就在家中。",
            ["DialogueId"] = 51156217,
            ["GUID"] = "801070DA",
            ["NextOptions"] = {
                [1] = 51156218,
                },
            ["SpeakNpcId"] = 701115,
            },
        [51156218] = {
            ["Content"] = "那你给他算的是什么？",
            ["DialogueId"] = 51156218,
            ["GUID"] = "80107104",
            ["NextDialogue"] = 51156219,
            },
        [51156219] = {
            ["Content"] = "诶呀，实不相瞒，要是结果是时，我便不继续琢磨了，但偏偏就是春……我在她丢物的西南位置搜寻了好久，就是没找着呀。",
            ["DialogueId"] = 51156219,
            ["GUID"] = "8010712E",
            ["NextDialogue"] = 51156220,
            ["SpeakNpcId"] = 701115,
            },
        [51156220] = {
            ["Content"] = "难不成……她早就丢了钱袋，只是现在才发现？诶……我是爱莫能助了！",
            ["DialogueId"] = 51156220,
            ["GUID"] = "80107158",
            ["NextOptions"] = {
                [1] = 51156221,
                },
            ["SpeakNpcId"] = 701115,
            },
        [51156221] = {
            ["Content"] = "太复杂了，再见！",
            ["DialogueId"] = 51156221,
            ["GUID"] = "80107182",
            ["NextDialogue"] = 51156222,
            },
        [51156222] = {
            ["Content"] = "分明是春卦，为何会如此呢……",
            ["DialogueId"] = 51156222,
            ["GUID"] = "801071AC",
            ["SpeakNpcId"] = 701115,
            },
        [51156301] = {
            ["Content"] = "什么贼不贼的，咱们华胥哪有贼？你来说说看，大风九章难道是摆设吗？狴犴大人不会顺着风来抓贼吗？",
            ["DialogueId"] = 51156301,
            ["GUID"] = "80107EA2",
            ["NextDialogue"] = 51156302,
            ["SpeakNpcId"] = 701117,
            },
        [51156302] = {
            ["Content"] = "我们只是在讨论此事，你别一副我已经错了的语气，我只是说我看见过，真有个小贼，那贼不一定是自己亲自偷的，可能有别的办法……",
            ["DialogueId"] = 51156302,
            ["GUID"] = "80107ECC",
            ["NextDialogue"] = 51156303,
            ["SpeakNpcId"] = 701116,
            },
        [51156303] = {
            ["Content"] = "切……还能有什么办法？让那丢了钱袋的人钱袋自己飞起来？",
            ["DialogueId"] = 51156303,
            ["GUID"] = "80107EF6",
            ["NextDialogue"] = 51156304,
            ["SpeakNpcId"] = 701117,
            },
        [51156304] = {
            ["Content"] = "我亲眼所见……那小贼有一手奇妙魔法，唰的召唤出一个蠕动的触手，勾出他人包里的东西，掉在地上……",
            ["DialogueId"] = 51156304,
            ["GUID"] = "80107F20",
            ["NextDialogue"] = 51156305,
            ["SpeakNpcId"] = 701116,
            },
        [51156305] = {
            ["Content"] = "还有这种事……未免太玄乎了吧？",
            ["DialogueId"] = 51156305,
            ["GUID"] = "80107F4A",
            ["NextDialogue"] = 51156306,
            ["SpeakNpcId"] = 701117,
            },
        [51156306] = {
            ["Content"] = "嗯哼，世界之大，无奇不有~",
            ["DialogueId"] = 51156306,
            ["GUID"] = "80107F74",
            ["SpeakNpcId"] = 701116,
            },
        [51156307] = {
            ["Content"] = "我早跟你说了这街上有贼，之前有人看到了，一个小女孩，皮肤黑黢黢的！",
            ["DialogueId"] = 51156307,
            ["GUID"] = "80107EA1",
            ["NextDialogue"] = 51156301,
            ["SpeakNpcId"] = 701116,
            },
        [51156401] = {
            ["Content"] = "（地上静静躺着一个钱袋子，好像在无声说着：捡我！）",
            ["DialogueId"] = 51156401,
            ["GUID"] = "80108F0A",
            ["NextDialogue"] = 51156402,
            },
        [51156402] = {
            ["Content"] = "（你把它捡了起来，还给失主，或是……）",
            ["DialogueId"] = 51156402,
            ["GUID"] = "80108F34",
            },
        [51156501] = {
            ["Content"] = "这位客人，见你在此驻足许久，是不是对我们店的香料感兴趣？不妨进店看看，让店里的伙计好好为您挑选适合的香料和香囊。",
            ["DialogueId"] = 51156501,
            ["GUID"] = "80109F72",
            ["NextDialogue"] = 51156502,
            ["SpeakNpcId"] = 701118,
            },
        [51156502] = {
            ["Content"] = "我们香行历史悠久，也是织星客自营，在口碑和品质上，您完全可以放心。",
            ["DialogueId"] = 51156502,
            ["GUID"] = "80109F9C",
            ["NextOptions"] = {
                [1] = 51156503,
                [2] = 51156507,
                },
            ["SpeakNpcId"] = 701118,
            },
        [51156503] = {
            ["Content"] = "香料对我没什么用处，有一个香囊就行。",
            ["DialogueId"] = 51156503,
            ["GUID"] = "80109FC6",
            ["NextDialogue"] = 51156504,
            },
        [51156504] = {
            ["Content"] = "哦？看来客人并非华胥之人，若是生在华胥，生活中方方面面都是离不开香料的。",
            ["DialogueId"] = 51156504,
            ["GUID"] = "80109FF0",
            ["NextDialogue"] = 51156505,
            ["SpeakNpcId"] = 701118,
            },
        [51156505] = {
            ["Content"] = "不过没关系，咱们香行里还有香囊坠饰，香木雕刻摆件以及最为有名的博山香炉在售。",
            ["DialogueId"] = 51156505,
            ["GUID"] = "8010A01A",
            ["NextDialogue"] = 51156506,
            ["SpeakNpcId"] = 701118,
            },
        [51156506] = {
            ["Content"] = "客人也可以看看，带回去给朋友当做旅游纪念礼也是好的。",
            ["DialogueId"] = 51156506,
            ["GUID"] = "8010A044",
            ["NextDialogue"] = 51156510,
            ["SpeakNpcId"] = 701118,
            },
        [51156507] = {
            ["Content"] = "除了香料，你们还卖别的吗？",
            ["DialogueId"] = 51156507,
            ["GUID"] = "8010A06E",
            ["NextDialogue"] = 51156508,
            },
        [51156508] = {
            ["Content"] = "自然，除了香料，客人也可以看看我们特质的黍锦香囊，配饰也可分开购买，客人如果喜欢装饰品，还能在本店买到白木雕摆件。",
            ["DialogueId"] = 51156508,
            ["GUID"] = "8010A098",
            ["NextDialogue"] = 51156509,
            ["SpeakNpcId"] = 701118,
            },
        [51156509] = {
            ["Content"] = "当然最有名的，还是店里热销产品——博山香炉。",
            ["DialogueId"] = 51156509,
            ["GUID"] = "8010A0C2",
            ["NextDialogue"] = 51156510,
            ["SpeakNpcId"] = 701118,
            },
        [51156510] = {
            ["Content"] = "如何，今日还有周年酬宾活动，客人要进店挑挑看吗？",
            ["DialogueId"] = 51156510,
            ["GUID"] = "8010A0EC",
            ["SpeakNpcId"] = 701118,
            },
        [51156511] = {
            ["Content"] = "博山香行周年店庆，来店订购香料满十送五~",
            ["DialogueId"] = 51156511,
            ["GUID"] = "8010A116",
            ["NextDialogue"] = 51156512,
            ["SpeakNpcId"] = 701118,
            },
        [51156512] = {
            ["Content"] = "客人又来集市闲逛？这是已经在咱们华胥待了有些时日了吗？可有去街上的茶楼里品上一盏香茗？亦或是抽空体会过附近的山水美景？",
            ["DialogueId"] = 51156512,
            ["GUID"] = "8010A140",
            ["NextDialogue"] = 51156513,
            ["SpeakNpcId"] = 701118,
            },
        [51156513] = {
            ["Content"] = "今日来我们博山香行，有什么需要吗？",
            ["DialogueId"] = 51156513,
            ["GUID"] = "8010A16A",
            ["NextOptions"] = {
                [1] = 51156514,
                },
            ["SpeakNpcId"] = 701118,
            },
        [51156514] = {
            ["Content"] = "介绍一下你们香行。",
            ["DialogueId"] = 51156514,
            ["GUID"] = "8010A194",
            ["NextDialogue"] = 51156515,
            },
        [51156515] = {
            ["Content"] = "哦？客人对香行的历史感兴趣？您可知道华胥有着织星客这样的商人联盟，我们博山香行就是织星客自营的店铺。",
            ["DialogueId"] = 51156515,
            ["GUID"] = "8010A1BE",
            ["NextDialogue"] = 51156516,
            ["SpeakNpcId"] = 701118,
            },
        [51156516] = {
            ["Content"] = "不止皓京，我们在华胥各地都设有分店，主营的业务就是香料贩售，当然，也卖别的。因为信誉好，香料质量也高，受到各方欢迎。",
            ["DialogueId"] = 51156516,
            ["GUID"] = "8010A1E8",
            ["NextOptions"] = {
                [1] = 51156517,
                [2] = 51156521,
                },
            ["SpeakNpcId"] = 701118,
            },
        [51156517] = {
            ["Content"] = "我从烟津渡来，为什么那边没有博山香行？",
            ["DialogueId"] = 51156517,
            ["GUID"] = "8010A212",
            ["NextDialogue"] = 51156518,
            },
        [51156518] = {
            ["Content"] = "没想到客人还去过华胥不少地方呢！是了，虽然咱们是织星客们开的店，但烟津渡那边的确并无分店。",
            ["DialogueId"] = 51156518,
            ["GUID"] = "8010A23C",
            ["NextDialogue"] = 51156519,
            ["SpeakNpcId"] = 701118,
            },
        [51156519] = {
            ["Content"] = "其实之前也不是没有开过，但是他们大多早已养成了去百年春买香料的习惯，只有开店初期一段时间吸引了一批顾客，后续便来的少了。",
            ["DialogueId"] = 51156519,
            ["GUID"] = "8010A266",
            ["NextDialogue"] = 51156520,
            ["SpeakNpcId"] = 701118,
            },
        [51156520] = {
            ["Content"] = "如此这般，烟津渡的分铺便就歇业息市。",
            ["DialogueId"] = 51156520,
            ["GUID"] = "8010A290",
            ["NextOptions"] = {
                [1] = 51156526,
                },
            ["SpeakNpcId"] = 701118,
            },
        [51156521] = {
            ["Content"] = "你提到的博山香炉是什么东西？",
            ["DialogueId"] = 51156521,
            ["GUID"] = "8010A2BA",
            ["NextDialogue"] = 51156522,
            },
        [51156522] = {
            ["Content"] = "其实也就是个熏香用的炉子，只是最开始的那个锻自博山，后续便以此命名。此炉小巧精致，既具实用性又有观赏性，也是咱们店里最为畅销的商品之一。",
            ["DialogueId"] = 51156522,
            ["GUID"] = "8010A2E4",
            ["NextDialogue"] = 51156523,
            ["SpeakNpcId"] = 701118,
            },
        [51156523] = {
            ["Content"] = "不过客人可去过博山？那里可是个好地方，风景秀丽，还是咱们华胥最为知名的香料产地。",
            ["DialogueId"] = 51156523,
            ["GUID"] = "8010A30E",
            ["NextOptions"] = {
                [1] = 51156524,
                },
            ["SpeakNpcId"] = 701118,
            },
        [51156524] = {
            ["Content"] = "没去过，有机会一定。",
            ["DialogueId"] = 51156524,
            ["GUID"] = "8010A338",
            ["NextDialogue"] = 51156525,
            },
        [51156525] = {
            ["Content"] = "好啊，客人来华胥一趟，必定要游个尽兴再归家呢。华胥不像外面，日日提心吊胆，担心秽兽袭击，咱们得白龙神君庇佑，幸享万年和平。",
            ["DialogueId"] = 51156525,
            ["GUID"] = "8010A362",
            ["NextOptions"] = {
                [1] = 51156526,
                },
            ["SpeakNpcId"] = 701118,
            },
        [51156526] = {
            ["Content"] = "不聊了，再见。",
            ["DialogueId"] = 51156526,
            ["GUID"] = "8010A38C",
            ["NextDialogue"] = 51156527,
            },
        [51156527] = {
            ["Content"] = "走好。欢迎您下次再来~",
            ["DialogueId"] = 51156527,
            ["GUID"] = "8010A3B6",
            ["SpeakNpcId"] = 701118,
            },
        [51156528] = {
            ["Content"] = "博山香行，百年老店，千年基业，香料品质有保证，定让顾客买个安心，买个开心！",
            ["DialogueId"] = 51156528,
            ["GUID"] = "80109F73",
            ["NextDialogue"] = 51156501,
            ["SpeakNpcId"] = 701118,
            },
        [51156529] = {
            ["Content"] = "博山香行周年店庆，来店订购香料满十赠五~",
            ["DialogueId"] = 51156529,
            ["GUID"] = "80109F74",
            ["NextDialogue"] = 51156528,
            ["SpeakNpcId"] = 701118,
            },
        [51156601] = {
            ["Content"] = "那是自然，客人的要求我们定当全力以赴，但有些香料可能现在香行里没有存货，我去帮您问问下次到货的时间是什么时候？",
            ["DialogueId"] = 51156601,
            ["GUID"] = "8010AFDA",
            ["NextDialogue"] = 51156602,
            ["SpeakNpcId"] = 701120,
            },
        [51156602] = {
            ["Content"] = "问，都可以问，但是你要知道一点——我希望你们能尽快把东西送来，我可以等，但我不能等太久。",
            ["DialogueId"] = 51156602,
            ["GUID"] = "8010B004",
            ["NextDialogue"] = 51156603,
            ["SpeakNpcId"] = 701119,
            },
        [51156603] = {
            ["Content"] = "是，客人的时间也是时间，我们可以先从其他分铺问问，是否有您需要的香料，如果有，那就尽快为您调货。",
            ["DialogueId"] = 51156603,
            ["GUID"] = "8010B02E",
            ["NextDialogue"] = 51156604,
            ["SpeakNpcId"] = 701120,
            },
        [51156604] = {
            ["Content"] = "可以，怎么说呢……不愧是你们博山香行，在服务质量上的确没话说，但你要知道——",
            ["DialogueId"] = 51156604,
            ["GUID"] = "8010B058",
            ["NextDialogue"] = 51156605,
            ["SpeakNpcId"] = 701119,
            },
        [51156605] = {
            ["Content"] = "知道知道，质量也一定按您的要求嘛！",
            ["DialogueId"] = 51156605,
            ["GUID"] = "8010B082",
            ["SpeakNpcId"] = 701120,
            },
        [51156606] = {
            ["Content"] = "你要知道一点——我对香料品质的要求很高，晒得太干我不要，香味散得太过我也不要。",
            ["DialogueId"] = 51156606,
            ["GUID"] = "8010AFDB",
            ["NextDialogue"] = 51156601,
            ["SpeakNpcId"] = 701119,
            },
        [51156701] = {
            ["Content"] = "要我说，精挑细选对比了好些家香行，最终还是博山香行最值得信赖。陆陆续续已经在这里买了上千斤，品质依旧十分有保障。",
            ["DialogueId"] = 51156701,
            ["GUID"] = "8010C042",
            ["NextOptions"] = {
                [1] = 51156702,
                },
            ["SpeakNpcId"] = 701121,
            },
        [51156702] = {
            ["Content"] = "为什么要买这么多香料？",
            ["DialogueId"] = 51156702,
            ["GUID"] = "8010C06C",
            ["NextDialogue"] = 51156703,
            },
        [51156703] = {
            ["Content"] = "我吗？我是合香师呀！自然会购入大批量的香料，回家自己琢磨香方。",
            ["DialogueId"] = 51156703,
            ["GUID"] = "8010C096",
            ["NextDialogue"] = 51156704,
            ["SpeakNpcId"] = 701121,
            },
        [51156704] = {
            ["Content"] = "早在很久之前，我就开始从民间的香行订货，价格倒是便宜，但是质量参差不齐。",
            ["DialogueId"] = 51156704,
            ["GUID"] = "8010C0C0",
            ["NextDialogue"] = 51156705,
            ["SpeakNpcId"] = 701121,
            },
        [51156705] = {
            ["Content"] = "后来周围的朋友都说我，别省那点钱了，比起价格，稳定的品控对于我们这种民间合香师来说才最为重要。",
            ["DialogueId"] = 51156705,
            ["GUID"] = "8010C0EA",
            ["NextDialogue"] = 51156706,
            ["SpeakNpcId"] = 701121,
            },
        [51156706] = {
            ["Content"] = "要是研发阶段用的一种品质的香料，卖给客人时用的另一种，两者香气却天差地别，对咱们后续的信誉也不是特别好。",
            ["DialogueId"] = 51156706,
            ["GUID"] = "8010C114",
            ["NextOptions"] = {
                [1] = 51156707,
                [2] = 51156711,
                },
            ["SpeakNpcId"] = 701121,
            },
        [51156707] = {
            ["Content"] = "说的是，如果我是客人，我也不喜欢货不对版。",
            ["DialogueId"] = 51156707,
            ["GUID"] = "8010C13E",
            ["NextDialogue"] = 51156708,
            },
        [51156708] = {
            ["Content"] = "不过嘛……虽然博山香行的品控做的好，但有些稍许冷门的香料，或是产地特殊些的，我们还是会从别的散户那边采购。",
            ["DialogueId"] = 51156708,
            ["GUID"] = "8010C168",
            ["NextDialogue"] = 51156709,
            ["SpeakNpcId"] = 701121,
            },
        [51156709] = {
            ["Content"] = "比如像龙戚戚这种可遇不可得的香料，存世量本就稀少，要想拿到最高品质的，还得去那海边的产地探寻。",
            ["DialogueId"] = 51156709,
            ["GUID"] = "8010C192",
            ["NextDialogue"] = 51156710,
            ["SpeakNpcId"] = 701121,
            },
        [51156710] = {
            ["Content"] = "诶呀……说来说去还是因为咱们华胥讲究香道的人太多……才让我们一天到晚绞尽脑汁去研究如何让这香的制备精益求精。",
            ["DialogueId"] = 51156710,
            ["GUID"] = "8010C1BC",
            ["NextOptions"] = {
                [1] = 51156716,
                },
            ["SpeakNpcId"] = 701121,
            },
        [51156711] = {
            ["Content"] = "民间合香师……是什么意思？",
            ["DialogueId"] = 51156711,
            ["GUID"] = "8010C1E6",
            ["NextDialogue"] = 51156712,
            },
        [51156712] = {
            ["Content"] = "顾名思义啊，民间，合香，分开来都很好理解吧？毕竟咱们华胥对香一事颇有讲究，如果只依靠祀烟阁的香方产出，用多了多少是有些乏味的。",
            ["DialogueId"] = 51156712,
            ["GUID"] = "8010C210",
            ["NextDialogue"] = 51156713,
            ["SpeakNpcId"] = 701121,
            },
        [51156713] = {
            ["Content"] = "所以我们私下就喜欢自己琢磨琢磨香方成分，自制一些有独特风味的香品，供给那些讲究的客人。",
            ["DialogueId"] = 51156713,
            ["GUID"] = "8010C23A",
            ["NextDialogue"] = 51156714,
            ["SpeakNpcId"] = 701121,
            },
        [51156714] = {
            ["Content"] = "我们为了研究新香方，自然会消耗许多香料，自己种是太难了，哦！也确实有人这么干！但我这种，还是会选择靠谱的香行购买。",
            ["DialogueId"] = 51156714,
            ["GUID"] = "8010C264",
            ["NextDialogue"] = 51156715,
            ["SpeakNpcId"] = 701121,
            },
        [51156715] = {
            ["Content"] = "这不，博山香行，老靠谱啦！",
            ["DialogueId"] = 51156715,
            ["GUID"] = "8010C28E",
            ["NextOptions"] = {
                [1] = 51156716,
                },
            ["SpeakNpcId"] = 701121,
            },
        [51156716] = {
            ["Content"] = "我先走了。",
            ["DialogueId"] = 51156716,
            ["GUID"] = "8010C2B8",
            ["NextDialogue"] = 51156717,
            },
        [51156717] = {
            ["Content"] = "行啊，慢走，有缘再聊！",
            ["DialogueId"] = 51156717,
            ["GUID"] = "8010C2E2",
            ["SpeakNpcId"] = 701121,
            },
        [51156718] = {
