            ["ImprPlusId"] = 1210,
            ["NextDialogue"] = 51158706,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [51158706] = {
            ["Content"] = "监工大人大人有大量！我错啦，再也不在工作时间偷懒了……拜托不要回去告诉老板，就算告诉了……",
            ["DialogueId"] = 51158706,
            ["GUID"] = "80120934",
