            ["NextDialogue"] = 51158908,
            ["SpeakNpcId"] = 701136,
            },
        [51158908] = {
            ["Content"] = "为了让大家快些赶路，咱们便在这湖上开了供大家乘坐的游船。",
            ["DialogueId"] = 51158908,
            ["GUID"] = "80122A58",
            ["NextDialogue"] = 51158909,
            ["SpeakNpcId"] = 701136,
            },
        [51158909] = {
            ["Content"] = "本地人可以用游船快速赶路，免得有什么急事继续要去城另一头。外地的客人呢——也图个新鲜，毕竟这湖光山色，泛舟湖上可是一桩美事。",
            ["DialogueId"] = 51158909,
            ["GUID"] = "80122A82",
            ["NextDialogue"] = 51158910,
            ["SpeakNpcId"] = 701136,
            },
        [51158910] = {
            ["Content"] = "客人您说是不是？",
            ["DialogueId"] = 51158910,
            ["GUID"] = "80122AAC",
            ["SpeakNpcId"] = 701136,
            },
        [51158911] = {
            ["Content"] = "游船游船，十文一趟，排队购票，客满即发。",
