            ["GUID"] = "80122AD6",
            ["NextDialogue"] = 51158912,
            ["SpeakNpcId"] = 701136,
            },
        [51158912] = {
            ["Content"] = "客人您早！是要来坐船去西市吗？",
            ["DialogueId"] = 51158912,
            ["GUID"] = "80122B00",
            ["NextOptions"] = {
                [1] = 51158913,
