            ["SpeakNpcId"] = 701147,
            },
        [51159805] = {
            ["Content"] = "这看着很新啊？",
            ["DialogueId"] = 51159805,
            ["GUID"] = "8012BD82",
            ["NextDialogue"] = 51159806,
            },
        [51159806] = {
            ["Content"] = "许多屋子托匠矩阁的师傅们来翻新过，所以看起来确实相差不大。但毕竟年份和材质摆在那儿，多少都会出些问题。",
            ["DialogueId"] = 51159806,
            ["GUID"] = "8012BDAC",
            ["NextOptions"] = {
                [1] = 51159807,
                },
            ["SpeakNpcId"] = 701147,
            },
        [51159807] = {
            ["Content"] = "房子原先的主人呢？",
            ["DialogueId"] = 51159807,
            ["GUID"] = "8012BDD6",
            ["NextDialogue"] = 51159808,
            },
        [51159808] = {
            ["Content"] = "搬走了罢……算起来，已经不晓得过去几代人了呢。即使是现在，还愿意住在这边的原住民也多半都是念旧的老人，年轻人会更倾向于搬到其他地方。",
            ["DialogueId"] = 51159808,
            ["GUID"] = "8012BE00",
            ["NextOptions"] = {
                [1] = 51159809,
                },
            ["SpeakNpcId"] = 701147,
            },
        [51159809] = {
