            ["NextDialogue"] = 51159810,
            },
        }
  end },
  { MinKey = 51159810, MaxKey = 51161102, Loader = function()
      return {
        [51159810] = {
            ["Content"] = "那可就多了，大多都是搬去了别的城市，华胥境内叫得上名字的地方也不少，皓京外围也有一些新的街区。",
            ["DialogueId"] = 51159810,
            ["GUID"] = "8012BE54",
            ["NextDialogue"] = 51159811,
            ["SpeakNpcId"] = 701147,
            },
        [51159811] = {
            ["Content"] = "不过即使搬去天涯海角，只要尚未离开华胥，大风九章就会庇佑祂的子民。",
            ["DialogueId"] = 51159811,
            ["GUID"] = "8012BE7E",
            ["SpeakNpcId"] = 701147,
            },
        [51159901] = {
            ["Content"] = "娘，你说句话吧……你一直哭，阿囡心疼……",
            ["DialogueId"] = 51159901,
            ["GUID"] = "8012CD42",
            ["NextDialogue"] = 51159902,
            ["SpeakNpcId"] = 701148,
            },
        [51159902] = {
            ["Content"] = "阿囡，你爹走了……你爹走了……",
            ["DialogueId"] = 51159902,
            ["GUID"] = "8012CD6C",
            ["NextDialogue"] = 51159903,
            ["SpeakNpcName"] = "UI_NPC_Name_awandeniang_Sce",
            },
        [51159903] = {
            ["Content"] = "娘不是一直告诉我，人死后会化作天上的星星吗？或许爹就像娘说的那样，变成星星，一眨一眨地看着娘呢。",
            ["DialogueId"] = 51159903,
            ["GUID"] = "8012CD96",
            ["NextDialogue"] = 51159904,
            ["SpeakNpcId"] = 701148,
            },
        [51159904] = {
            ["Content"] = "别哭，别哭，哭肿了眼睛，就不好看啦。",
            ["DialogueId"] = 51159904,
            ["GUID"] = "8012CDC0",
            ["NextDialogue"] = 51159905,
            ["SpeakNpcId"] = 701148,
            },
        [51159905] = {
            ["Content"] = "他走了……他怎么就抛下我走了……",
            ["DialogueId"] = 51159905,
            ["GUID"] = "8012CDEA",
            ["SpeakNpcName"] = "UI_NPC_Name_awandeniang_Sce",
            },
        [51159906] = {
            ["Content"] = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
            ["DialogueId"] = 51159906,
            ["GUID"] = "8012CE14",
            ["NextDialogue"] = 51159907,
            ["SpeakNpcId"] = 701148,
            },
        [51159907] = {
            ["Content"] = "娘，你吃点东西吧……你看你都瘦了……",
            ["DialogueId"] = 51159907,
            ["GUID"] = "8012CE3E",
            ["NextOptions"] = {
                [1] = 51159908,
                },
            ["SpeakNpcId"] = 701148,
            },
        [51159908] = {
            ["Content"] = "发生什么了？",
            ["DialogueId"] = 51159908,
            ["GUID"] = "8012CE68",
            ["NextDialogue"] = 51159909,
            },
        [51159909] = {
            ["Content"] = "你好，你是来吊唁的吗？赙赠放在灵堂前的木箱里就好，我娘现在……可能暂时不能和你说话。",
            ["DialogueId"] = 51159909,
            ["GUID"] = "8012CE92",
            ["NextOptions"] = {
                [1] = 51159910,
                },
            ["SpeakNpcId"] = 701148,
            },
        [51159910] = {
            ["Content"] = "我只是路过。",
            ["DialogueId"] = 51159910,
            ["GUID"] = "8012CEBC",
            ["NextDialogue"] = 51159911,
            },
        [51159911] = {
            ["Content"] = "唔……你这一身白衣看着像是素服，是我看错了，不好意思，{性别:大哥哥|大姐姐}。",
            ["DialogueId"] = 51159911,
            ["GUID"] = "8012CEE6",
            ["NextOptions"] = {
                [1] = 51159912,
                },
            ["SpeakNpcId"] = 701148,
            },
        [51159912] = {
            ["Content"] = "你看起来并不怎么伤心？",
            ["DialogueId"] = 51159912,
            ["GUID"] = "8012CF10",
            ["NextDialogue"] = 51159913,
            },
        [51159913] = {
            ["Content"] = "我现在这样，只是因为我没办法自己沉浸在悲伤里。你也看到了，我娘因为爹走了，现在谁的话也听不进去。",
            ["DialogueId"] = 51159913,
            ["GUID"] = "8012CF3A",
            ["NextDialogue"] = 51159914,
            ["SpeakNpcId"] = 701148,
            },
        [51159914] = {
            ["Content"] = "如果我不现在站出来，就没有人可以撑起来这个家了。",
            ["DialogueId"] = 51159914,
            ["GUID"] = "8012CF64",
            ["NextOptions"] = {
                [1] = 51159915,
                },
            ["SpeakNpcId"] = 701148,
            },
        [51159915] = {
            ["Content"] = "你成熟得不像孩子。",
            ["DialogueId"] = 51159915,
            ["GUID"] = "8012CF8E",
            ["NextDialogue"] = 51159916,
            },
        [51159916] = {
            ["Content"] = "这算是……夸我吗？爹病重之时曾经告诉我，要我在他走了之后，承担起照顾这个家的责任。",
            ["DialogueId"] = 51159916,
            ["GUID"] = "8012CFB8",
            ["NextDialogue"] = 51159917,
            ["SpeakNpcId"] = 701148,
            },
        [51159917] = {
            ["Content"] = "没有人比他更了解我娘。现在看起来，事情果然如他所预想的那样。",
            ["DialogueId"] = 51159917,
            ["GUID"] = "8012CFE2",
            ["NextDialogue"] = 51159918,
            ["SpeakNpcId"] = 701148,
            },
        [51159918] = {
            ["Content"] = "所以我更不能在这个时候发泄自己的情绪，我只能坚强一点，再坚强一点……",
            ["DialogueId"] = 51159918,
            ["GUID"] = "8012D00C",
            ["NextOptions"] = {
                [1] = 51159919,
                },
            ["SpeakNpcId"] = 701148,
            },
        [51159919] = {
            ["Content"] = "加油。",
            ["DialogueId"] = 51159919,
            ["GUID"] = "8012D036",
            ["NextDialogue"] = 51159920,
            },
        [51159920] = {
            ["Content"] = "谢谢你，我会的。",
