            },
        [51168102] = {
            ["Content"] = "？？？",
            ["DialogueId"] = 51168102,
            ["GUID"] = "80180EBC",
            ["NextDialogue"] = 51168104,
            },
        [51168103] = {
            ["Content"] = "你在说什么呢？",
            ["DialogueId"] = 51168103,
            ["GUID"] = "80180EE6",
            ["NextDialogue"] = 51168104,
            },
        [51168104] = {
            ["Content"] = "听不懂？这什么破字典……不是说这么说话华胥人一定听得懂吗？",
            ["DialogueId"] = 51168104,
            ["GUID"] = "80180F10",
            ["NextDialogue"] = 51168105,
            ["SpeakNpcId"] = 701190,
            },
        [51168105] = {
            ["Content"] = "难道是我说错了？等下，我再翻一下……这位情头一盒的死生只有，笔人出入华胥，人地两生，敢问玉溪识在何方？",
