            ["GUID"] = "80180F3A",
            ["NextOptions"] = {
                [1] = 51168106,
                [2] = 51168108,
                },
            ["SpeakNpcId"] = 701190,
            },
        [51168106] = {
            ["Content"] = "能不能正常说话？",
            ["DialogueId"] = 51168106,
            ["GUID"] = "80180F64",
            ["NextDialogue"] = 51168107,
            },
        [51168107] = {
            ["Content"] = "能不能在大全里对应的是……能否，正常对应的是……诶？不对？你……你不是华胥人？你听得懂我说话？",
            ["DialogueId"] = 51168107,
            ["GUID"] = "80180F8E",
            ["NextDialogue"] = 51168110,
            ["SpeakNpcId"] = 701190,
            },
        [51168108] = {
            ["Content"] = "你要问的不会是厕所在哪吧？",
            ["DialogueId"] = 51168108,
            ["GUID"] = "80180FB8",
            ["NextDialogue"] = 51168109,
            },
        [51168109] = {
            ["Content"] = "对对对，就是厕所！诶？不是……你……你能听得懂我说话？你不是华胥人？",
            ["DialogueId"] = 51168109,
            ["GUID"] = "80180FE2",
            ["NextDialogue"] = 51168110,
            ["SpeakNpcId"] = 701190,
            },
        [51168110] = {
            ["Content"] = "我的打扮也不像华胥人吧？",
            ["DialogueId"] = 51168110,
            ["GUID"] = "8018100C",
            ["NextDialogue"] = 51168111,
            ["SpeakNpcId"] = 100001,
            },
        [51168111] = {
            ["Content"] = "诶呀！可算给我找着同乡了！我请的那个，华胥翻译，刚刚跟我说肚子疼，让我在这里等他一会，就把我丢在这里。",
            ["DialogueId"] = 51168111,
            ["GUID"] = "80181036.0",
            ["NextDialogue"] = 51168112,
            ["SpeakNpcId"] = 701190,
            },
        [51168112] = {
            ["Content"] = "现在已经过去了半小时，他还没回来，我一个人在这也不敢乱走，可总在这站着也不是办法呀！",
            ["DialogueId"] = 51168112,
            ["GUID"] = "80181060.0",
            ["NextDialogue"] = 51168113,
            ["SpeakNpcId"] = 701190,
            },
        [51168113] = {
            ["Content"] = "我就想着，要不要直接去找他回来得了。但我也不知道华胥人平常都怎么说话，就去买了一本这个……喏，你看！",
            ["DialogueId"] = 51168113,
            ["GUID"] = "8018108A",
            ["NextDialogue"] = 51168114,
            ["SpeakNpcId"] = 701190,
            },
        [51168114] = {
            ["Content"] = "（泛黄的扉页上工工整整地写着——华胥问候语录大全。）",
            ["DialogueId"] = 51168114,
            ["GUID"] = "801810B4",
            ["NextOptions"] = {
                [1] = 51168115,
                },
            },
        [51168115] = {
            ["Content"] = "谁卖给你的？",
            ["DialogueId"] = 51168115,
            ["GUID"] = "801810DE",
            ["NextDialogue"] = 51168116,
            },
        [51168116] = {
            ["Content"] = "就在广场附近，有个卖报的小孩，说是看在我是外乡客的面子上便宜卖我，只收五十铜！",
            ["DialogueId"] = 51168116,
            ["GUID"] = "80181108.0",
            ["NextDialogue"] = 51168117,
            ["SpeakNpcId"] = 701190,
            },
        [51168117] = {
            ["Content"] = "还说有了这本书，所有不了解华胥语言的家伙都能变成华胥通！只需要简单的对照就好了。",
            ["DialogueId"] = 51168117,
            ["GUID"] = "80181132.0",
            ["NextOptions"] = {
                [1] = 51168118,
                [2] = 51168121,
                },
            ["SpeakNpcId"] = 701190,
            },
        [51168118] = {
