            },
        [51168403] = {
            ["Content"] = "其实与普通的灯谜会并无太多区别。只是因着大典期间，许多外乡客或是奔波在外的游子归来，皓京城内也热闹起来了。",
            ["DialogueId"] = 51168403,
            ["GUID"] = "8018401E",
            ["NextDialogue"] = 51168404,
            ["SpeakNpcId"] = 701193,
            },
        [51168404] = {
            ["Content"] = "所以在西市和执律阁前广场这里准备了一些活动，灯谜会也是其中之一，大家一同欢庆佳节，岂不美哉？",
            ["DialogueId"] = 51168404,
            ["GUID"] = "80184048.0",
            ["NextOptions"] = {
                [1] = 51168405,
                },
            ["SpeakNpcId"] = 701193,
            },
        [51168405] = {
            ["Content"] = "有什么奖品吗？",
            ["DialogueId"] = 51168405,
            ["GUID"] = "80184072.0",
            ["NextDialogue"] = 51168406,
            },
        [51168406] = {
            ["Content"] = "自然是准备了些许薄礼，虽然不太丰厚，但也是一分心意。",
            ["DialogueId"] = 51168406,
            ["GUID"] = "8018409C",
            ["NextOptions"] = {
                [1] = 51168407,
                },
            ["SpeakNpcId"] = 701193,
            },
        [51168407] = {
            ["Content"] = "外来者也能参加？",
            ["DialogueId"] = 51168407,
            ["GUID"] = "801840C6",
            ["NextDialogue"] = 51168408,
            },
        [51168408] = {
            ["Content"] = "放心放心，就是考虑到了这一点，所以这次活动设置的谜题都不怎么困难，只需稍稍了解一些华胥文化，就能答上来。",
            ["DialogueId"] = 51168408,
            ["GUID"] = "801840F0",
            ["NextOptions"] = {
                [1] = 51168409,
                },
            ["SpeakNpcId"] = 701193,
            },
        [51168409] = {
            ["Content"] = "没什么要问的了。",
            ["DialogueId"] = 51168409,
            ["GUID"] = "8018411A",
            ["NextDialogue"] = 51168410,
            },
        [51168410] = {
            ["Content"] = "那我在此恭祝客人——游玩愉快。",
            ["DialogueId"] = 51168410,
            ["GUID"] = "80184144.0",
            ["SpeakNpcId"] = 701193,
            },
        [51168411] = {
            ["Content"] = "双石为开（打一字）",
            ["DialogueId"] = 51168411,
            ["GUID"] = "80184145.0",
            ["NextOptions"] = {
                [1] = 51168412,
                [2] = 51168413,
                [3] = 51168415,
                },
            },
        [51168412] = {
            ["Content"] = "石",
            ["DialogueId"] = 51168412,
            ["GUID"] = "80184146.0",
            },
        [51168413] = {
            ["Content"] = "砳",
            ["DialogueId"] = 51168413,
            ["GUID"] = "80184147.0",
            },
        [51168415] = {
            ["Content"] = "磊",
            ["DialogueId"] = 51168415,
            ["GUID"] = "80184148.0",
            },
        [51168416] = {
            ["Content"] = "这种灯谜就差把谜底写在字面上了，看不起谁呢？",
            ["DialogueId"] = 51168416,
            ["GUID"] = "80184149.0",
            },
        [51168417] = {
            ["Content"] = "尘香袅袅龙君现，典前争辉竞纷纭。奉香大典特别活动——灯谜会，待君赏玩！",
            ["DialogueId"] = 51168417,
            ["GUID"] = "80183FCB",
            ["NextDialogue"] = 51168401,
            ["SpeakNpcId"] = 701193,
            },
        [51168501] = {
            ["Content"] = "弟兄五六个，围着圆柱坐，大家一分手，衣服都扯破。",
            ["DialogueId"] = 51168501,
            ["GUID"] = "80185032.0",
            ["NextOptions"] = {
                [1] = 51168502,
                [2] = 51168503,
                [3] = 51168504,
                },
            },
        [51168502] = {
            ["Content"] = "柑橘",
            ["DialogueId"] = 51168502,
            ["GUID"] = "8018505C",
            },
        [51168503] = {
            ["Content"] = "甜橙",
            ["DialogueId"] = 51168503,
            ["GUID"] = "80185086.0",
            },
        [51168504] = {
            ["Content"] = "大蒜",
            ["DialogueId"] = 51168504,
            ["GUID"] = "801850B0",
            },
        [51168601] = {
            ["Content"] = "白又方，嫩又香，能做菜，能煮汤，豆子是它爹和娘，它和爹娘不一样。",
            ["DialogueId"] = 51168601,
            ["GUID"] = "8018609A",
            ["NextOptions"] = {
                [1] = 51168602,
                [2] = 51168603,
                [3] = 51168604,
                },
            },
        [51168602] = {
            ["Content"] = "豆腐",
            ["DialogueId"] = 51168602,
            ["GUID"] = "801860C4",
            },
        [51168603] = {
            ["Content"] = "千张",
            ["DialogueId"] = 51168603,
            ["GUID"] = "801860EE",
            },
        [51168604] = {
            ["Content"] = "豆泡",
            ["DialogueId"] = 51168604,
            ["GUID"] = "80186118.0",
            },
        [51168605] = {
            ["Content"] = "我考考你，这道题的谜底是什么？",
            ["DialogueId"] = 51168605,
            ["GUID"] = "80186142.0",
            },
        [51168606] = {
            ["Content"] = "还用你考我呢？我可随便就答出来了~",
            ["DialogueId"] = 51168606,
            ["GUID"] = "8018616C",
            },
        [51168701] = {
            ["Content"] = "年终岁尾，不缺鱼米。",
            ["DialogueId"] = 51168701,
            ["GUID"] = "80187102.0",
            ["NextOptions"] = {
