            ["GUID"] = "80187180.0",
            },
        [51168801] = {
            ["Content"] = "蜜饯黄连（打一成语）",
            ["DialogueId"] = 51168801,
            ["GUID"] = "8018816A",
            ["NextOptions"] = {
                [1] = 51168802,
                [2] = 51168803,
                [3] = 51168804,
                },
            },
        [51168802] = {
            ["Content"] = "良药苦口",
            ["DialogueId"] = 51168802,
            ["GUID"] = "80188194.0",
            },
        [51168803] = {
            ["Content"] = "苦尽甘来",
            ["DialogueId"] = 51168803,
            ["GUID"] = "801881BE",
            },
        [51168804] = {
            ["Content"] = "同甘共苦",
            ["DialogueId"] = 51168804,
            ["GUID"] = "801881BF",
            },
        [51168805] = {
            ["Content"] = "怎么觉得三个答案都对呢？难不成是谜题出错了？",
            ["DialogueId"] = 51168805,
            ["GUID"] = "80188212.0",
            },
        [51168901] = {
            ["Content"] = "尖尖长嘴，细细小腿。拖条大尾，疑神疑鬼。",
            ["DialogueId"] = 51168901,
            ["GUID"] = "801891D2",
            ["NextOptions"] = {
                [1] = 51168902,
                [2] = 51168903,
                [3] = 51168904,
                },
            },
        [51168902] = {
            ["Content"] = "松鼠",
            ["DialogueId"] = 51168902,
            ["GUID"] = "801891FC",
            },
        [51168903] = {
            ["Content"] = "赤狐",
            ["DialogueId"] = 51168903,
            ["GUID"] = "80189226.0",
            },
        [51168904] = {
            ["Content"] = "猴子",
            ["DialogueId"] = 51168904,
            ["GUID"] = "80189250.0",
            },
        [51169001] = {
            ["Content"] = "姑娘真辛苦，晚上还织布。天色蒙蒙亮，机声才停住。",
            ["DialogueId"] = 51169001,
            ["GUID"] = "8018A23A",
            ["NextOptions"] = {
                [1] = 51169002,
                [2] = 51169003,
                [3] = 51169004,
                },
            },
        [51169002] = {
            ["Content"] = "织机娘",
            ["DialogueId"] = 51169002,
            ["GUID"] = "8018A264",
            },
        [51169003] = {
            ["Content"] = "织织娘",
            ["DialogueId"] = 51169003,
            ["GUID"] = "8018A28E",
            },
        [51169004] = {
            ["Content"] = "纺织娘",
            ["DialogueId"] = 51169004,
            ["GUID"] = "8018A2B8",
            },
        [51169005] = {
            ["Content"] = "华胥的虫子，我不知道叫什么名字啊……",
            ["DialogueId"] = 51169005,
            ["GUID"] = "8018A2E2",
            },
        [51169101] = {
            ["Content"] = "一粒谷，占满屋。（打一物）",
            ["DialogueId"] = 51169101,
            ["GUID"] = "8018B2A2",
            ["NextOptions"] = {
                [1] = 51169102,
                [2] = 51169103,
                [3] = 51169104,
                },
            },
        [51169102] = {
            ["Content"] = "谷堆",
            ["DialogueId"] = 51169102,
            ["GUID"] = "8018B2CC",
            },
        [51169103] = {
            ["Content"] = "浴缸",
            ["DialogueId"] = 51169103,
            ["GUID"] = "8018B2F6",
            },
        [51169104] = {
            ["Content"] = "灯台",
            ["DialogueId"] = 51169104,
            ["GUID"] = "8018B320",
            },
        [51169202] = {
            ["Content"] = "此情此景，难以言表，唯有无言而泪流……",
            ["DialogueId"] = 51169202,
            ["GUID"] = "8018C334",
            ["NextDialogue"] = 51169203,
            ["SpeakNpcId"] = 701194,
            },
        [51169203] = {
            ["Content"] = "你也是来此瞻仰龙君威严的吗？看看这恢弘的殿前，高耸入云的执律阁，一切的一切都是那么伟大而壮阔，恰如……",
            ["DialogueId"] = 51169203,
            ["GUID"] = "8018C35E",
            ["NextOptions"] = {
                [1] = 51169204,
                [2] = 51169205,
                },
            ["SpeakNpcId"] = 701194,
            },
        [51169204] = {
            ["Content"] = "等等……",
            ["DialogueId"] = 51169204,
            ["GUID"] = "8018C388",
            ["NextDialogue"] = 51169206,
            },
        [51169205] = {
            ["Content"] = "有这么夸张吗？",
            ["DialogueId"] = 51169205,
            ["GUID"] = "8018C3B2",
            ["NextDialogue"] = 51169206,
            },
        [51169206] = {
            ["Content"] = "跨越千山万水，只为来到皓京，来到这执律阁广场见太皓神君一面——这样澎湃的心情，如何才能传达给你呢？",
            ["DialogueId"] = 51169206,
            ["GUID"] = "8018C3DC",
            ["NextDialogue"] = 51169207,
            ["SpeakNpcId"] = 701194,
            },
        [51169207] = {
            ["Content"] = "执律阁对我来说有着非同寻常的意义！我勤工俭学了一年，只为攒够来皓京的开销。",
            ["DialogueId"] = 51169207,
            ["GUID"] = "8018C406",
            ["NextDialogue"] = 51169208,
            ["SpeakNpcId"] = 701194,
            },
        [51169208] = {
            ["Content"] = "而今天，就在此时此地，我的梦想终于实现了！看这气派的广场，这康庄大道，是否预示着我的前程也在此刻分明了？",
            ["DialogueId"] = 51169208,
            ["GUID"] = "8018C430",
            ["NextOptions"] = {
                [1] = 51169209,
                },
            ["SpeakNpcId"] = 701194,
            },
        [51169209] = {
            ["Content"] = "执律阁广场对你来说有什么意义？",
            ["DialogueId"] = 51169209,
            ["GUID"] = "8018C45A",
            ["NextDialogue"] = 51169210,
            },
        [51169210] = {
            ["Content"] = "我从小就听着皓京执律阁的故事长大，奶奶总告诉我，若是我勤勉向学，就会被龙君亲自接引至这里。",
            ["DialogueId"] = 51169210,
            ["GUID"] = "8018C484",
            ["NextDialogue"] = 51169211,
            ["SpeakNpcId"] = 701194,
            },
        [51169211] = {
            ["Content"] = "成为龙渊上卿，成为龙中之龙，成为万千华胥人向往艳羡的存在，效力国家，效力百姓！",
            ["DialogueId"] = 51169211,
            ["GUID"] = "8018C4AE",
            ["NextDialogue"] = 51169212,
            ["SpeakNpcId"] = 701194,
            },
        [51169212] = {
            ["Content"] = "可偏偏小时的我无法理解奶奶劝我向学的用心，只顾贪玩，奶奶说想见到我独当一面的那一天，可她……",
            ["DialogueId"] = 51169212,
            ["GUID"] = "8018C4D8",
            ["NextDialogue"] = 51169213,
            ["SpeakNpcId"] = 701194,
            },
        [51169213] = {
            ["Content"] = "她再也见不到了，在我十岁那年，奶奶离开了我。",
            ["DialogueId"] = 51169213,
            ["GUID"] = "8018C502",
            ["NextDialogue"] = 51169214,
            ["SpeakNpcId"] = 701194,
            },
        [51169214] = {
            ["Content"] = "后来我就暗暗发誓，即使成不了龙渊上卿，我也要来执律阁看看，告诉黄泉之下的奶奶，孙儿不孝，辜负了您的期待。",
            ["DialogueId"] = 51169214,
            ["GUID"] = "8018C52C",
            ["NextOptions"] = {
                [1] = 51169215,
                [2] = 51169217,
                },
            ["SpeakNpcId"] = 701194,
            },
        [51169215] = {
            ["Content"] = "你是个孝顺的人，不要这么说自己。",
            ["DialogueId"] = 51169215,
            ["GUID"] = "8018C556",
            ["NextDialogue"] = 51169216,
            },
        [51169216] = {
            ["Content"] = "谢谢你，可现在说这些早就没什么用了，不过至少来到这里，也算是了却我自己一桩心愿。",
            ["DialogueId"] = 51169216,
            ["GUID"] = "8018C580",
            ["SpeakNpcId"] = 701194,
            },
        [51169217] = {
            ["Content"] = "奶奶不是希望你出人头地，只是希望你过得好。",
            ["DialogueId"] = 51169217,
            ["GUID"] = "8018C5AA",
            ["NextDialogue"] = 51169218,
            },
        [51169218] = {
            ["Content"] = "我又如何不知道，我只是气我自己，没有在奶奶还在的时候就让她过上好日子。",
            ["DialogueId"] = 51169218,
            ["GUID"] = "8018C5D4",
            ["NextDialogue"] = 51169219,
            ["SpeakNpcId"] = 701194,
            },
        [51169219] = {
            ["Content"] = "哪怕是现在，也只是攒了好久的银钱才能来这一趟，而不是在皓京定居。",
            ["DialogueId"] = 51169219,
            ["GUID"] = "8018C5FE",
            ["SpeakNpcId"] = 701194,
            },
        [51169301] = {
            ["Content"] = "不好意思，执律阁内部禁止外人随意进入。",
            ["DialogueId"] = 51169301,
            ["GUID"] = "8018D372",
            ["NextDialogue"] = 51169302,
            ["SpeakNpcName"] = "UI_NPC_Name_shougeren_Sce",
            },
        [51169302] = {
            ["Content"] = "不对，你们搞错了，我不是外人啊，我是华胥之人，身处于龙君的庇护之下，那就是内人！",
            ["DialogueId"] = 51169302,
            ["GUID"] = "8018D39C",
            ["NextDialogue"] = 51169303,
            ["SpeakNpcId"] = 701195,
            },
        [51169303] = {
            ["Content"] = "这位朋友，实在不好意思……可是这里真的不让进。",
            ["DialogueId"] = 51169303,
            ["GUID"] = "8018D3C6",
            ["NextDialogue"] = 51169304,
            ["SpeakNpcName"] = "UI_NPC_Name_shougeren_Sce",
            },
        [51169304] = {
            ["Content"] = "我千里迢迢来皓京，就是想见白龙神君一面呀，你就让我进去看看吧，我保证什么也不乱动。",
            ["DialogueId"] = 51169304,
            ["GUID"] = "8018D3F0",
            ["NextDialogue"] = 51169305,
            ["SpeakNpcId"] = 701195,
            },
        [51169305] = {
            ["Content"] = "真的不行……你看这怎么办呀？他一直不走……",
            ["DialogueId"] = 51169305,
            ["GUID"] = "8018D41A",
            ["NextDialogue"] = 51169306,
            ["SpeakNpcName"] = "UI_NPC_Name_shougeren_Sce",
            },
        [51169306] = {
            ["Content"] = "这位公子，我们自当理解你对神君的虔诚之心，但执律阁历来有规定，除非有重大案件，才会在阁内审理。",
            ["DialogueId"] = 51169306,
            ["GUID"] = "8018D444",
            ["NextDialogue"] = 51169307,
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieren_Sce",
            },
        [51169307] = {
            ["Content"] = "且龙君日理万机，并非成日驻守于执律阁，即使你贸然闯入，也难得一见。",
            ["DialogueId"] = 51169307,
            ["GUID"] = "8018D46E",
            ["NextDialogue"] = 51169308,
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieren_Sce",
            },
        [51169308] = {
            ["Content"] = "若阁下真有龙章凤资，何不努力成为龙渊上卿候选，被神君请来阁中，闻香入试？届时自可一睹真容。",
            ["DialogueId"] = 51169308,
            ["GUID"] = "8018D498",
            ["NextDialogue"] = 51169309,
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieren_Sce",
            },
        [51169309] = {
            ["Content"] = "我要有那本事还跟你们在这扯什么，我就想进去看看，这回还特地带了海伯利亚产的照相机，拍张照片我就走！",
            ["DialogueId"] = 51169309,
            ["GUID"] = "8018D4C2",
            ["NextDialogue"] = 51169310,
            ["SpeakNpcId"] = 701195,
            },
        [51169310] = {
            ["Content"] = "你看，说不通……",
            ["DialogueId"] = 51169310,
            ["GUID"] = "8018D4EC",
            ["NextDialogue"] = 51169311,
            ["SpeakNpcName"] = "UI_NPC_Name_shougeren_Sce",
            },
        [51169311] = {
            ["Content"] = "唉……每年都有几个这样的狂热分子啊……",
            ["DialogueId"] = 51169311,
            ["GUID"] = "8018D516",
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieren_Sce",
            },
        [51169312] = {
            ["Content"] = "这里面不能进去吗？我买票也不行？那有什么办法能进去看看？我想见白龙神君。",
            ["DialogueId"] = 51169312,
            ["GUID"] = "8018D371",
            ["NextDialogue"] = 51169301,
            ["SpeakNpcId"] = 701195,
            },
        [51169401] = {
            ["Content"] = "你看！只要内心足够虔诚，望向执律阁顶之时，就会看到白龙神君在云间遨游。",
            ["DialogueId"] = 51169401,
            ["GUID"] = "8018E3DA",
            ["NextDialogue"] = 51169402,
            ["SpeakNpcId"] = 701196,
            },
        [51169402] = {
            ["Content"] = "阿娘，我的眼睛都要睁到落泪了……怎么还没看见神君呢？",
            ["DialogueId"] = 51169402,
            ["GUID"] = "8018E404",
            ["NextDialogue"] = 51169403,
            ["SpeakNpcId"] = 701197,
            },
        [51169403] = {
            ["Content"] = "等你足够虔诚的时候，自然会看见。",
            ["DialogueId"] = 51169403,
            ["GUID"] = "8018E42E",
            ["NextDialogue"] = 51169404,
            ["SpeakNpcId"] = 701196,
            },
        [51169404] = {
            ["Content"] = "唔……那边的{性别:哥哥|姐姐}，你能看到白龙神君吗？",
            ["DialogueId"] = 51169404,
            ["GUID"] = "8018E458",
            ["NextOptions"] = {
                [1] = 51169405,
                [2] = 51169416,
                },
            ["SpeakNpcId"] = 701197,
            },
        [51169405] = {
            ["Content"] = "能。",
            ["DialogueId"] = 51169405,
            ["GUID"] = "8018E482",
            ["NextDialogue"] = 51169406,
            },
        [51169406] = {
            ["Content"] = "哇！真的吗！那你能不能告诉我，白龙神君究竟长什么样子呀？",
            ["DialogueId"] = 51169406,
            ["GUID"] = "8018E4AC",
            ["NextOptions"] = {
                [1] = 51169407,
                [2] = 51169410,
                },
            ["SpeakNpcId"] = 701197,
            },
        [51169407] = {
            ["Content"] = "描述龙的长相。",
            ["DialogueId"] = 51169407,
            ["GUID"] = "8018E4D6",
            ["NextDialogue"] = 51169408,
            },
        [51169408] = {
            ["Content"] = "长长的，弯弯曲曲的身体上面满是鳞片，头上有两只角，跟有龙氏差不多的那种。",
            ["DialogueId"] = 51169408,
            ["GUID"] = "8018E500",
            ["NextDialogue"] = 51169409,
            ["SpeakNpcId"] = 100001,
            },
        [51169409] = {
            ["Content"] = "唔……那不是和画里见到的一模一样吗？娘，我就说画画的人一定见过神君吧，他们一定是当着神君的面给他画像呢！",
            ["DialogueId"] = 51169409,
            ["GUID"] = "8018E52A",
            ["NextDialogue"] = 51169413,
            ["SpeakNpcId"] = 701197,
            },
        [51169410] = {
            ["Content"] = "描述人的长相。",
            ["DialogueId"] = 51169410,
            ["GUID"] = "8018E554",
            ["NextDialogue"] = 51169411,
            },
        [51169411] = {
            ["Content"] = "白龙神君有着和咱们一样的长相，两只眼睛一个鼻子，头顶尖尖的龙角。",
            ["DialogueId"] = 51169411,
            ["GUID"] = "8018E57E",
            ["NextDialogue"] = 51169412,
            ["SpeakNpcId"] = 100001,
            },
        [51169412] = {
            ["Content"] = "哇！白龙神君果然和画像上的那些不一样，那他是怎么在云上飞的呢？是踩着一片云朵吗？还是直接就——呜~地飞走了。",
            ["DialogueId"] = 51169412,
            ["GUID"] = "8018E5A8",
            ["NextDialogue"] = 51169413,
            ["SpeakNpcId"] = 701197,
            },
        [51169413] = {
            ["Content"] = "小孩子不懂事，说着玩的，你别介意。",
            ["DialogueId"] = 51169413,
            ["GUID"] = "8018E5D2",
            ["NextDialogue"] = 51169414,
            ["SpeakNpcId"] = 701196,
            },
        [51169414] = {
            ["Content"] = "没关系。",
            ["DialogueId"] = 51169414,
            ["GUID"] = "8018E5FC",
            ["NextDialogue"] = 51169415,
            ["SpeakNpcId"] = 100001,
            },
        [51169415] = {
            ["Content"] = "好啦，我们去东市吧，娘给你买糖葫芦。",
            ["DialogueId"] = 51169415,
            ["GUID"] = "8018E626",
            ["SpeakNpcId"] = 701196,
            },
        [51169416] = {
            ["Content"] = "不能。",
            ["DialogueId"] = 51169416,
            ["GUID"] = "8018E650",
            ["NextDialogue"] = 51169417,
            },
        [51169417] = {
            ["Content"] = "难道{性别:哥哥|姐姐}也不够虔诚吗？",
            ["DialogueId"] = 51169417,
            ["GUID"] = "8018E67A",
            ["NextDialogue"] = 51169418,
            ["SpeakNpcId"] = 701197,
            },
        [51169418] = {
            ["Content"] = "我不是华胥人，不虔诚也很正常。",
            ["DialogueId"] = 51169418,
            ["GUID"] = "8018E6A4",
            ["NextDialogue"] = 51169419,
            ["SpeakNpcId"] = 100001,
            },
        [51169419] = {
            ["Content"] = "哦~原来是这样呀，{性别:哥哥|姐姐}，欢迎你来华胥玩。",
            ["DialogueId"] = 51169419,
            ["GUID"] = "8018E6CE",
            ["NextDialogue"] = 51169420,
            ["SpeakNpcId"] = 701197,
            },
        [51169420] = {
            ["Content"] = "谢谢。",
            ["DialogueId"] = 51169420,
            ["GUID"] = "8018E6F8",
            ["NextDialogue"] = 51169421,
            ["SpeakNpcId"] = 100001,
            },
        [51169421] = {
            ["Content"] = "（你摸了摸她的头。）",
            ["DialogueId"] = 51169421,
            ["GUID"] = "8018E722",
            },
        [51169501] = {
            ["Content"] = "朝报朝报，茶不思饭不想只想看朝报，皓京独家新闻，绝对真实绝对劲爆！",
            ["DialogueId"] = 51169501,
            ["GUID"] = "8018F442",
            ["NextDialogue"] = 51169502,
            ["SpeakNpcId"] = 701198,
            },
        [51169502] = {
            ["Content"] = "这位客人，要不要来份朝报？匠矩阁出品的印刷机，字体清晰图片高清，内容也由学院才子再次加工，保准有趣！",
            ["DialogueId"] = 51169502,
            ["GUID"] = "8018F46C",
            ["NextOptions"] = {
                [1] = 51169503,
                [2] = 51169506,
                [3] = 51169510,
                },
            ["SpeakNpcId"] = 701198,
            },
        [51169503] = {
            ["Content"] = "你是做什么的？",
            ["DialogueId"] = 51169503,
            ["GUID"] = "8018F496",
            ["NextDialogue"] = 51169504,
            },
        [51169504] = {
            ["Content"] = "我呀？当然是卖报的啦！上至龙君动向，下至家长里短，我们报童无一不知无一不晓！",
            ["DialogueId"] = 51169504,
            ["GUID"] = "8018F4C0",
            ["NextDialogue"] = 51169505,
            ["SpeakNpcId"] = 701198,
            },
        [51169505] = {
            ["Content"] = "只是呢，我们打听来的消息，全都在这份朝报之中，客人想知道，那就……",
            ["DialogueId"] = 51169505,
            ["GUID"] = "8018F4EA",
            ["NextDialogue"] = 51169514,
            ["SpeakNpcId"] = 701198,
            },
        [51169506] = {
            ["Content"] = "朝报内容有什么？",
            ["DialogueId"] = 51169506,
            ["GUID"] = "8018F514",
            ["NextDialogue"] = 51169507,
            },
        [51169507] = {
            ["Content"] = "客人让我好为难呀，我当然知晓客人迫不及待想要知道报里的消息，可我却是个卖报的，要是都告诉你了，你不就不买报了吗？",
            ["DialogueId"] = 51169507,
            ["GUID"] = "8018F53E",
            ["NextDialogue"] = 51169508,
            ["SpeakNpcId"] = 701198,
            },
        [51169508] = {
            ["Content"] = "怎么办呢……不如这样！我不说内容，只告诉你标题，如何？",
            ["DialogueId"] = 51169508,
            ["GUID"] = "8018F568",
            ["NextDialogue"] = 51169509,
            ["SpeakNpcId"] = 701198,
            },
        [51169509] = {
            ["Content"] = "让我看看……今天的消息是……啊！水冲龙王庙，东市龙君雕像因湖水上涨而被淹；奇事！六旬老妪得子；怪哉，西市一狗拿耗子！",
            ["DialogueId"] = 51169509,
            ["GUID"] = "8018F592",
            ["NextDialogue"] = 51169514,
            ["SpeakNpcId"] = 701198,
            },
        [51169510] = {
            ["Content"] = "你这么小就工作吗？",
            ["DialogueId"] = 51169510,
            ["GUID"] = "8018F5BC",
            ["NextDialogue"] = 51169511,
            },
        [51169511] = {
            ["Content"] = "什么工作不工作的，我在给我爹帮忙呢，他就在店里面搞印刷，他答应了，我卖十本朝报，就可以换一串糖葫芦。",
            ["DialogueId"] = 51169511,
            ["GUID"] = "8018F5E6",
            ["NextDialogue"] = 51169512,
            ["SpeakNpcId"] = 701198,
            },
        [51169512] = {
            ["Content"] = "喏，你看，这是他给我的凭证，今天已经卖了六本了，我还把一本滞销已久的《华胥问候语录大全》卖给了个什么都不懂的异乡客！这得算我三本报呢！",
            ["DialogueId"] = 51169512,
            ["GUID"] = "8018F610",
            ["NextDialogue"] = 51169513,
            ["SpeakNpcId"] = 701198,
            },
        [51169513] = {
            ["Content"] = "嘿嘿，所以怎么样，客人要不要也来赞助一下我的糖葫芦生意？",
            ["DialogueId"] = 51169513,
            ["GUID"] = "8018F63A",
            ["NextDialogue"] = 51169514,
            ["SpeakNpcId"] = 701198,
            },
        [51169514] = {
            ["Content"] = "（要买他的朝报吗？）",
            ["DialogueId"] = 51169514,
            ["GUID"] = "8018F664",
            ["NextOptions"] = {
                [1] = 51169515,
                [2] = 51169518,
                },
            },
        [51169515] = {
            ["Content"] = "买。",
            ["DialogueId"] = 51169515,
            ["GUID"] = "8018F68E",
            ["NextDialogue"] = 51169516,
            },
        [51169516] = {
            ["Content"] = "（获得一份报纸。）",
            ["DialogueId"] = 51169516,
            ["GUID"] = "8018F6B8",
            ["NextDialogue"] = 51169517,
            },
        [51169517] = {
            ["Content"] = "好嘞，客人您收好，这是今日的朝报！",
            ["DialogueId"] = 51169517,
            ["GUID"] = "8018F6E2",
            ["SpeakNpcId"] = 701198,
            },
        [51169518] = {
            ["Content"] = "不买。",
            ["DialogueId"] = 51169518,
            ["GUID"] = "8018F70C",
            ["NextDialogue"] = 51169519,
            },
        [51169519] = {
            ["Content"] = "白费我半天口舌，诶呀，算啦算啦！",
            ["DialogueId"] = 51169519,
            ["GUID"] = "8018F736",
            ["SpeakNpcId"] = 701198,
            },
        [51169601] = {
            ["Content"] = "您好，这位{性别:先生|女士}，不知道您现在方不方便，我想问你些事情。",
            ["DialogueId"] = 51169601,
            ["GUID"] = "801904AA",
            ["NextDialogue"] = 51169602,
            ["SpeakNpcId"] = 701199,
            },
        [51169602] = {
            ["Content"] = "是这样的，我是一名来自海伯利亚帝国的商人，来皓京谈生意，因为回程的船只延期，只能在皓京游玩几天。",
            ["DialogueId"] = 51169602,
            ["GUID"] = "801904D4",
            ["NextDialogue"] = 51169603,
            ["SpeakNpcId"] = 701199,
            },
        [51169603] = {
            ["Content"] = "刚才有个卖报的小童，将这本报刊出售给了我，说是皓京最热门的活动都写在上面了，但我这翻来覆去看了半天，一个华胥字都不认识。",
            ["DialogueId"] = 51169603,
            ["GUID"] = "801904FE",
            ["NextOptions"] = {
                [1] = 51169604,
                },
            ["SpeakNpcId"] = 701199,
            },
        [51169604] = {
            ["Content"] = "我也是海伯利亚来的。",
            ["DialogueId"] = 51169604,
            ["GUID"] = "80190528.0",
            ["NextDialogue"] = 51169605,
            },
        [51169605] = {
            ["Content"] = "居然也是帝国之民！荣耀尽归吾皇！不过你这打扮确实不太像……我还以为是华胥哪个地方的小众穿搭呢……",
            ["DialogueId"] = 51169605,
            ["GUID"] = "80190552.0",
            ["NextDialogue"] = 51169606,
            ["SpeakNpcId"] = 701199,
            },
        [51169606] = {
            ["Content"] = "既然你也是帝国之民，那想必也不会特别了解华胥字，诶……算啦，我还是自己随便逛逛得了。",
            ["DialogueId"] = 51169606,
            ["GUID"] = "8019057C",
            ["NextOptions"] = {
                [1] = 51169607,
                },
            ["SpeakNpcId"] = 701199,
            },
        [51169607] = {
            ["Content"] = "我看看，但我也不一定都认识。",
            ["DialogueId"] = 51169607,
            ["GUID"] = "801905A6",
            ["NextDialogue"] = 51169608,
            },
        [51169608] = {
            ["Content"] = "（你从他手中拿过报刊，仔细研读。）",
            ["DialogueId"] = 51169608,
            ["GUID"] = "801905D0",
            ["NextDialogue"] = 51169609,
            },
        [51169609] = {
            ["Content"] = "（居然是一份只有字没有任何配图的报刊，密密麻麻的文字让你完全摸不着头脑！）",
            ["DialogueId"] = 51169609,
            ["GUID"] = "801905FA",
            ["NextDialogue"] = 51169610,
            },
        [51169610] = {
            ["Content"] = "（只能……）",
            ["DialogueId"] = 51169610,
            ["GUID"] = "80190624.0",
            ["NextOptions"] = {
                [1] = 51169611,
                [2] = 51169613,
                },
            },
        [51169611] = {
            ["Content"] = "我也看不懂。",
            ["DialogueId"] = 51169611,
            ["GUID"] = "8019064E",
            ["NextDialogue"] = 51169612,
            },
        [51169612] = {
            ["Content"] = "啊这……那好吧……算啦，我还是自己随便逛逛得了。",
            ["DialogueId"] = 51169612,
            ["GUID"] = "80190678.0",
            ["SpeakNpcId"] = 701199,
            },
        [51169613] = {
            ["Content"] = "（开始胡编乱造。）",
            ["DialogueId"] = 51169613,
            ["GUID"] = "801906A2",
            ["NextDialogue"] = 51169614,
            },
        [51169614] = {
            ["Content"] = "这上面是说，西市在办庙庆活动，摊位上有许多特色美食。",
            ["DialogueId"] = 51169614,
            ["GUID"] = "801906CC",
            ["NextDialogue"] = 51169615,
            ["SpeakNpcId"] = 100001,
            },
        [51169615] = {
            ["Content"] = "东市许多店家喜迎奉香大典，推出了折扣活动。",
            ["DialogueId"] = 51169615,
            ["GUID"] = "801906F6",
            ["NextDialogue"] = 51169616,
            ["SpeakNpcId"] = 100001,
            },
        [51169616] = {
            ["Content"] = "中心广场上也有猜灯谜活动，很有意思，当然，最重要的还是奉香大典这个全华胥最知名的活动，非常有趣，绝对不能错过！",
            ["DialogueId"] = 51169616,
            ["GUID"] = "80190720.0",
            ["NextDialogue"] = 51169617,
            ["SpeakNpcId"] = 100001,
            },
        [51169617] = {
            ["Content"] = "哦哦！原来写得如此详细！谢谢你！我这就去上面所说的地方看看，究竟是怎样有趣的事情！",
            ["DialogueId"] = 51169617,
            ["GUID"] = "8019074A",
            ["NextDialogue"] = 51169618,
            ["SpeakNpcId"] = 701199,
            },
        [51169618] = {
            ["Content"] = "不客气！",
            ["DialogueId"] = 51169618,
            ["GUID"] = "80190774.0",
            ["SpeakNpcId"] = 100001,
            },
        [51169619] = {
            ["Content"] = "这字乍一看好似和海伯利亚那边没什么区别，可凑在一起为什么完全看不懂……",
            ["DialogueId"] = 51169619,
            ["GUID"] = "801904AB",
            ["NextDialogue"] = 51169601,
            ["SpeakNpcId"] = 701199,
            },
        [51169701] = {
            ["Content"] = "您听我说，您去一个地方，吃什么玩什么，都是次要，主要的是要来感受当地的氛围，您说对不对？",
            ["DialogueId"] = 51169701,
            ["GUID"] = "80191512.0",
            ["NextDialogue"] = 51169702,
            ["SpeakNpcId"] = 701200,
            },
        [51169702] = {
            ["Content"] = "咱们呢就是一群老头老太，年轻时候忙习惯了，老了呢也闲不下来，我们就自愿来这执律阁前，来给你们这些小年轻讲讲华胥的历史。",
            ["DialogueId"] = 51169702,
            ["GUID"] = "8019153C",
            ["NextDialogue"] = 51169703,
            ["SpeakNpcId"] = 701200,
            },
        [51169703] = {
            ["Content"] = "不收钱的呀！您放心好啦！绝不是什么强买强卖，咱就是在家闲得长草，就想出门来晒晒。",
            ["DialogueId"] = 51169703,
            ["GUID"] = "80191566.0",
            ["NextOptions"] = {
                [1] = 51169704,
                [2] = 51169716,
                [3] = 51169729,
                },
            ["SpeakNpcId"] = 701200,
            },
        [51169704] = {
            ["Content"] = "（打听皓京城的历史。）",
            ["DialogueId"] = 51169704,
            ["GUID"] = "80191590.0",
            ["NextDialogue"] = 51169705,
            },
        [51169705] = {
            ["Content"] = "诶呀！又是来问皓京历史的，罗老头，你来你来！",
            ["DialogueId"] = 51169705,
            ["GUID"] = "801915BA",
            ["NextDialogue"] = 51169706,
            ["SpeakNpcId"] = 701200,
            },
        [51169706] = {
            ["Content"] = "诶哟，皓京城的故事，您问我就对咯！早在千年以前，这里还没有一个叫皓京的地方，只有飏先祖带领的小小聚落。",
            ["DialogueId"] = 51169706,
            ["GUID"] = "801915BB",
            ["NextDialogue"] = 51169707,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169707] = {
            ["Content"] = "那时的华胥啊，苦于秽兽之灾，人们流离失所，为了岌岌可危的生存资源你抢我夺，终日不得安宁。",
            ["DialogueId"] = 51169707,
            ["GUID"] = "8019160E",
            ["NextDialogue"] = 51169708,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169708] = {
            ["Content"] = "好在我们伟大的飏先祖觉醒了自己的魔法——分香术！分香术辅一落成，便已经可以控制咱这附近的一带的秽兽，只一个人的力量，实在过于渺小。",
            ["DialogueId"] = 51169708,
            ["GUID"] = "80191638.0",
            ["NextDialogue"] = 51169709,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169709] = {
            ["Content"] = "于是大风九章落成了，将这分香术发扬光大！围绕着这大风九章奠基的地方，在高悬的执律阁下，皓京应运而生！",
            ["DialogueId"] = 51169709,
            ["GUID"] = "80191662.0",
            ["NextDialogue"] = 51169710,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169710] = {
            ["Content"] = "最开始的皓京只有现在的一半大小。随着悬衡派的壮大，附近的居民也逐渐向皓京靠拢，有龙氏学习分香术，抟土氏则种植培养更多香料。",
            ["DialogueId"] = 51169710,
            ["GUID"] = "8019168C",
            ["NextDialogue"] = 51169711,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169711] = {
            ["Content"] = "于是椒兰村便因此逐渐落成，时至今日，椒兰村依旧是香料种植的一大宝地，那里的人世代种香供香用香，可能要比皓京城里的还要专业些！",
            ["DialogueId"] = 51169711,
            ["GUID"] = "801916B6",
            ["NextDialogue"] = 51169712,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169712] = {
            ["Content"] = "大风九章为华胥带来了和平，也带来了人口逐年上涨，直至今天，皓京已经进行了两次大建设以及数不清的无数次小型修缮。",
            ["DialogueId"] = 51169712,
            ["GUID"] = "801916B7",
            ["NextDialogue"] = 51169713,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169713] = {
            ["Content"] = "皓京老了，岁数大了，所以许多年轻人也不在皓京住了，但皓京依旧见证了华胥的千年和平，是当之无愧的华胥第一城！",
            ["DialogueId"] = 51169713,
            ["GUID"] = "8019170A",
            ["NextDialogue"] = 51169714,
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169714] = {
            ["Content"] = "老罗，说得好啊，你是回家又重新写了稿子吗？",
            ["DialogueId"] = 51169714,
            ["GUID"] = "80191734.0",
            ["NextDialogue"] = 51169715,
            ["SpeakNpcId"] = 701200,
            },
        [51169715] = {
            ["Content"] = "诶呀过奖过奖，我和夫人一起在家演练过好些遍。",
            ["DialogueId"] = 51169715,
            ["GUID"] = "8019175E",
            ["SpeakNpcName"] = "UI_NPC_Name_luolaotou_Sce",
            },
        [51169716] = {
            ["Content"] = "（打听皓京的文化。）",
            ["DialogueId"] = 51169716,
            ["GUID"] = "80191788.0",
            ["NextDialogue"] = 51169717,
            },
        [51169717] = {
            ["Content"] = "这个是乾老太的强项，乾老太！乾老太！快来，这里有人问文化呢！",
            ["DialogueId"] = 51169717,
            ["GUID"] = "801917B2",
            ["NextDialogue"] = 51169718,
            ["SpeakNpcId"] = 701200,
            },
        [51169718] = {
            ["Content"] = "来了来了！催什么催！这位小朋友呀，你问我可就问对人了。",
            ["DialogueId"] = 51169718,
            ["GUID"] = "801917DC",
            ["NextDialogue"] = 51169719,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169719] = {
            ["Content"] = "虽说我不晓得文化究竟是什么意思，但是我在外求学的丫头说文化呢，就是最独特的，别的地方没有的东西。",
            ["DialogueId"] = 51169719,
            ["GUID"] = "80191806.0",
            ["NextDialogue"] = 51169720,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169720] = {
            ["Content"] = "所以我就整理出来了三样，皓京最独特的东西，我这就说与你听！",
            ["DialogueId"] = 51169720,
            ["GUID"] = "80191830.0",
            ["NextDialogue"] = 51169721,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169721] = {
            ["Content"] = "这第一样呢，是这龙君所在的执律阁。这高悬于皓京之巅，有龙神盘旋的执律阁，可是绝无仅有只此一家的！",
            ["DialogueId"] = 51169721,
            ["GUID"] = "8019185A",
            ["NextDialogue"] = 51169722,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169722] = {
            ["Content"] = "这第二样呢，是皓京的府宅文化，您一路来的时候也看见了，咱们这里一家人，不止是一个小家庭，而是一整个大家族，都喜欢住在一栋房子里。",
            ["DialogueId"] = 51169722,
            ["GUID"] = "80191884.0",
            ["NextDialogue"] = 51169723,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169723] = {
            ["Content"] = "图的是一个团团美美，大家整日抬头不见低头见，有什么事情家人便一道帮忙，这在外地可是很难看着的。",
            ["DialogueId"] = 51169723,
            ["GUID"] = "801918AE",
            ["NextDialogue"] = 51169724,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169724] = {
            ["Content"] = "第三样……其实我也没特别想好，本想说香料，又觉得华胥处处是香，无甚稀奇。又想说商贸，想必也比不得烟津渡那边昌盛。",
            ["DialogueId"] = 51169724,
            ["GUID"] = "801918D8",
            ["NextDialogue"] = 51169725,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169725] = {
            ["Content"] = "我是觉得啊，皓京好在一个杂字，就是华胥天南地北的吃喝玩乐，你都能在皓京找到，只因为这座城市留人，离开的孩子们总想把外面的好东西带回家。",
            ["DialogueId"] = 51169725,
            ["GUID"] = "80191902.0",
            ["NextDialogue"] = 51169726,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169726] = {
            ["Content"] = "于是拼拼凑凑，就成了现在最为独特的皓京。",
            ["DialogueId"] = 51169726,
            ["GUID"] = "8019192C",
            ["NextDialogue"] = 51169727,
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169727] = {
            ["Content"] = "说的好啊，依我看，今年皓京导游非你莫属！",
            ["DialogueId"] = 51169727,
            ["GUID"] = "80191956.0",
            ["NextDialogue"] = 51169728,
            ["SpeakNpcId"] = 701200,
            },
        [51169728] = {
            ["Content"] = "韩哥谬赞了，我还差得远呢！",
            ["DialogueId"] = 51169728,
            ["GUID"] = "80191980.0",
            ["SpeakNpcName"] = "UI_NPC_Name_qianlaotai_Sce",
            },
        [51169729] = {
            ["Content"] = "（打听这些老人。）",
            ["DialogueId"] = 51169729,
            ["GUID"] = "801919AA",
            ["NextDialogue"] = 51169730,
            },
        [51169730] = {
            ["Content"] = "您问我们是做什么的？我们就是闲得没事做才来给大家回答问题的呀。",
            ["DialogueId"] = 51169730,
            ["GUID"] = "801919D4",
            ["NextDialogue"] = 51169731,
            ["SpeakNpcId"] = 701200,
            },
        [51169731] = {
            ["Content"] = "之前总听人家来了皓京的人说：诶呀皓京也就那样，一点意思都没有，跟别的地方差不多，不好玩。",
            ["DialogueId"] = 51169731,
            ["GUID"] = "801919FE",
            ["NextDialogue"] = 51169732,
            ["SpeakNpcId"] = 701200,
            },
        }
  end },
  { MinKey = 51169732, MaxKey = 51170919, Loader = function()
      return {
        [51169732] = {
            ["Content"] = "我们这帮人听了就不乐意啊，那他没去深入了解咋就说不好玩呢，或者说，皓京本身就不是什么“玩”的地方，皓京是华胥最大的一本书啊！",
            ["DialogueId"] = 51169732,
            ["GUID"] = "80191A28",
            ["NextDialogue"] = 51169733,
            ["SpeakNpcId"] = 701200,
            },
        [51169733] = {
            ["Content"] = "所以我就组织了一批和我志同道合的老朋友们，每天来这执律阁门口给人无偿科普！毕竟来皓京玩的孩子们总不会错过执律阁的对吧！",
            ["DialogueId"] = 51169733,
            ["GUID"] = "80191A52",
            ["NextDialogue"] = 51169734,
            ["SpeakNpcId"] = 701200,
            },
        [51169734] = {
            ["Content"] = "不过呢……这样的成效似乎不是特别好，你看我这跟你聊上了，那边那些个就没法理会，我们也在考虑改进一下方法了。",
            ["DialogueId"] = 51169734,
            ["GUID"] = "80191A7C",
            ["NextDialogue"] = 51169735,
            ["SpeakNpcId"] = 701200,
            },
        [51169735] = {
            ["Content"] = "你说编一出戏在这巡演怎么样？那唢呐一吹小鼓一敲，震个隆咚戕，还有谁人不知不晓？",
            ["DialogueId"] = 51169735,
            ["GUID"] = "80191AA6",
            ["NextOptions"] = {
                [1] = 51169736,
                [2] = 51169738,
                },
            ["SpeakNpcId"] = 701200,
            },
        [51169736] = {
            ["Content"] = "支持！",
            ["DialogueId"] = 51169736,
            ["GUID"] = "80191AD0",
            ["NextDialogue"] = 51169737,
            },
        [51169737] = {
            ["Content"] = "好啊！你可比我那不孝子有眼光，他只会觉得我这老头给他丢脸，回回动不动就来劝我回家！",
            ["DialogueId"] = 51169737,
            ["GUID"] = "80191AFA",
            ["SpeakNpcId"] = 701200,
            },
        [51169738] = {
            ["Content"] = "不好吧……",
            ["DialogueId"] = 51169738,
            ["GUID"] = "80191B24",
            ["NextDialogue"] = 51169739,
            },
        [51169739] = {
            ["Content"] = "你和我那不孝子说的一样！他非说在这唱大戏会扰民，扰什么呢？这大广场难道有人睡觉？难不成能吵到天上的龙君？",
            ["DialogueId"] = 51169739,
            ["GUID"] = "80191B4E",
            ["SpeakNpcId"] = 701200,
            },
        [51169801] = {
            ["Content"] = "您刚才说的皓京历史我还没听得特别明白，可以再说一遍吗？",
            ["DialogueId"] = 51169801,
            ["GUID"] = "8019257A",
            },
        [51169802] = {
            ["Content"] = "不用你们介绍，我都来皓京好几趟了！",
            ["DialogueId"] = 51169802,
            ["GUID"] = "801925A4",
            },
        [51169803] = {
            ["Content"] = "我知道这个，我们那也有，叫导游！哦不，是志愿者！",
            ["DialogueId"] = 51169803,
            ["GUID"] = "801925CE",
            },
        [51169901] = {
            ["Content"] = "退一万步说，在人家办事处门口宣传这些也不合适吧……",
            ["DialogueId"] = 51169901,
            ["GUID"] = "8019360B",
            ["NextDialogue"] = 51169902,
            ["SpeakNpcId"] = 701201,
            },
        [51169902] = {
            ["Content"] = "不晓得哪听来的闲言碎语，非说什么皓京不好玩，大伙都知道现在的言论二极分化，不是神了就是鬼了。",
            ["DialogueId"] = 51169902,
            ["GUID"] = "8019360C",
            ["NextDialogue"] = 51169903,
            ["SpeakNpcId"] = 701201,
            },
        [51169903] = {
            ["Content"] = "偏是老年人不清楚其中门道，只觉得是自己的故土被诋毁了，才想出了这一出。",
            ["DialogueId"] = 51169903,
            ["GUID"] = "80193636.0",
            ["NextDialogue"] = 51169904,
            ["SpeakNpcId"] = 701201,
            },
        [51169904] = {
            ["Content"] = "这有些消息啊，还是不能让他们听着了。",
            ["DialogueId"] = 51169904,
            ["GUID"] = "80193660.0",
            ["NextOptions"] = {
                [1] = 51169905,
                },
            ["SpeakNpcId"] = 701201,
            },
        [51169905] = {
            ["Content"] = "你说的是什么消息？",
            ["DialogueId"] = 51169905,
            ["GUID"] = "8019368A",
            ["NextDialogue"] = 51169906,
            },
        [51169906] = {
            ["Content"] = "还能是什么呢，不就是之前有些来皓京的游客，满城乱窜最后说不好玩，避雷！给我家老头子听着了，急得三天没合眼。",
            ["DialogueId"] = 51169906,
            ["GUID"] = "801936B4",
            ["NextDialogue"] = 51169907,
            ["SpeakNpcId"] = 701201,
            },
        [51169907] = {
            ["Content"] = "后面就撺掇着许多老头老太一起，来这执律阁做什么百科讲座，抓着过路人一顿训导。",
            ["DialogueId"] = 51169907,
            ["GUID"] = "801936DE",
            ["NextDialogue"] = 51169908,
            ["SpeakNpcId"] = 701201,
            },
        [51169908] = {
            ["Content"] = "你也是被抓的？还是只是路过，我可建议你，要是不想生命中宝贵的十分钟被浪费，还是离他们远些，绕开走。",
            ["DialogueId"] = 51169908,
            ["GUID"] = "80193708.0",
            ["NextOptions"] = {
                [1] = 51169909,
                [2] = 51169912,
                },
            ["SpeakNpcId"] = 701201,
            },
        [51169909] = {
            ["Content"] = "你觉得他们的行为没有意义？",
            ["DialogueId"] = 51169909,
            ["GUID"] = "80193732.0",
            ["NextDialogue"] = 51169910,
            },
        [51169910] = {
            ["Content"] = "倒也没那么绝对……只是你也看出来了，这种行为十分冒犯，尤其是选址还是在这执律阁前，皓京最庄严的地方！",
            ["DialogueId"] = 51169910,
            ["GUID"] = "8019375C",
            ["NextDialogue"] = 51169911,
            ["SpeakNpcId"] = 701201,
            },
        [51169911] = {
            ["Content"] = "有这时间不如去和西城的那些老头子们一起打打拳锻炼身体，来这缠着游客……那不是扰民吗？",
            ["DialogueId"] = 51169911,
            ["GUID"] = "80193786.0",
            ["NextOptions"] = {
                [1] = 51169918,
                },
            ["SpeakNpcId"] = 701201,
            },
        [51169912] = {
            ["Content"] = "你不支持他们宣扬皓京文化？",
            ["DialogueId"] = 51169912,
            ["GUID"] = "801937B0",
            ["NextDialogue"] = 51169913,
            },
        [51169913] = {
            ["Content"] = "别扣帽子，我支持宣扬皓京文化，但不是这个宣传法！",
            ["DialogueId"] = 51169913,
            ["GUID"] = "801937DA",
            ["NextDialogue"] = 51169914,
            ["SpeakNpcId"] = 701201,
            },
        [51169914] = {
            ["Content"] = "问题是皓京好不好玩这个事儿，他就不是你这样粗浅地宣传就能改变的。",
            ["DialogueId"] = 51169914,
            ["GUID"] = "80193804.0",
            ["NextDialogue"] = 51169915,
            ["SpeakNpcId"] = 701201,
            },
        [51169915] = {
            ["Content"] = "每个人来皓京的目的不同，有人是为了瞻仰旧都遗迹，他们看到这鲜亮重修过的街面，就要说了：啊皓京真无聊全是仿古建筑，避雷！",
            ["DialogueId"] = 51169915,
            ["GUID"] = "8019382E",
            ["NextDialogue"] = 51169916,
            ["SpeakNpcId"] = 701201,
            },
        [51169916] = {
            ["Content"] = "有人是为了龙君，为了来执律阁去见龙君，那没见着也要说了：啊皓京真没意思说了龙君在这我啥也没见着，避雷！",
            ["DialogueId"] = 51169916,
            ["GUID"] = "80193858.0",
            ["NextDialogue"] = 51169917,
            ["SpeakNpcId"] = 701201,
            },
        [51169917] = {
            ["Content"] = "皓京本就不是个可以让所有人都满意的地方，准确来说，没有一个地方能够做到。只有自己的心意才能决定的事情，旁人无论说什么也没用。",
            ["DialogueId"] = 51169917,
            ["GUID"] = "80193882.0",
            ["NextOptions"] = {
                [1] = 51169918,
                },
            ["SpeakNpcId"] = 701201,
            },
        [51169918] = {
            ["Content"] = "所以你想劝他们回去？",
            ["DialogueId"] = 51169918,
            ["GUID"] = "801938AC",
            ["NextDialogue"] = 51169919,
            },
        [51169919] = {
            ["Content"] = "难哦！他们觉得这两天很有成效，要变本加厉了呢，还在那琢磨着要在执律阁唱大戏，锣鼓喧天地宣传。",
            ["DialogueId"] = 51169919,
            ["GUID"] = "801938D6",
            ["NextDialogue"] = 51169920,
            ["SpeakNpcId"] = 701201,
            },
        [51169920] = {
            ["Content"] = "你说会不会过两天又多了什么说法，说皓京执律阁门口怎么有一堆吵死人的老头老太，实在不尊重龙君，避雷！",
            ["DialogueId"] = 51169920,
            ["GUID"] = "80193900.0",
            ["NextOptions"] = {
                [1] = 51169921,
                [2] = 51169924,
                },
            ["SpeakNpcId"] = 701201,
            },
        [51169921] = {
            ["Content"] = "你说的很有道理。",
            ["DialogueId"] = 51169921,
            ["GUID"] = "8019392A",
            ["NextDialogue"] = 51169922,
            },
        [51169922] = {
            ["Content"] = "是吧，你也这么觉得，我反正是希望他能早点醒悟，咱们回家过好自己的日子就得了，皓京如何都是外人眼中的事情。",
            ["DialogueId"] = 51169922,
            ["GUID"] = "80193954.0",
            ["NextDialogue"] = 51169923,
            ["SpeakNpcId"] = 701201,
            },
        [51169923] = {
            ["Content"] = "他们喜欢不喜欢又与我们何干？皓京究竟如何，是我们在这朝夕住着的人来决定的，我们才是最深有感触的人，谁会不喜欢自己的家乡呢？",
            ["DialogueId"] = 51169923,
            ["GUID"] = "8019397E",
            ["NextDialogue"] = 51169928,
            ["SpeakNpcId"] = 701201,
            },
        [51169924] = {
            ["Content"] = "他们做的也不一定不对。",
            ["DialogueId"] = 51169924,
            ["GUID"] = "801939A8",
            ["NextDialogue"] = 51169925,
            },
        [51169925] = {
            ["Content"] = "啊是，你要说，一定意义上确实是让部分游客对皓京有了更多的了解，可我真问你，那些游客真的在乎吗？",
            ["DialogueId"] = 51169925,
            ["GUID"] = "801939D2",
            ["NextDialogue"] = 51169926,
            ["SpeakNpcId"] = 701201,
            },
        [51169926] = {
            ["Content"] = "他们在这待着从来到走最多不过小一月，听了一些几千年积累的事情，别说是否真能深有感触，多半只是似懂非懂。",
            ["DialogueId"] = 51169926,
            ["GUID"] = "801939FC",
            ["NextDialogue"] = 51169927,
            ["SpeakNpcId"] = 701201,
            },
        [51169927] = {
            ["Content"] = "没有满足自身需求的地方终究是要批判的，是龙君来了也拦不住的，毕竟嘴长自己身上，想说什么都是自己的事情。",
            ["DialogueId"] = 51169927,
            ["GUID"] = "80193A26",
            ["NextDialogue"] = 51169928,
            ["SpeakNpcId"] = 701201,
            },
        [51169928] = {
            ["Content"] = "反正我是要跟这老头杠到底，他不是说唱大戏不会扰民吗？那我就偏在这睡觉，让他知晓这会打扰到我。",
            ["DialogueId"] = 51169928,
            ["GUID"] = "80193A50",
            ["NextDialogue"] = 51169929,
            ["SpeakNpcId"] = 701201,
            },
        [51169929] = {
            ["Content"] = "看看谁能耗得过谁呢……",
            ["DialogueId"] = 51169929,
            ["GUID"] = "80193A7A",
            ["SpeakNpcId"] = 701201,
            },
        [51170001] = {
            ["Content"] = "我家老婆子好好地走在街上，他路也不看，直接推着车撞了过来。",
            ["DialogueId"] = 51170001,
            ["GUID"] = "8019464A",
            ["NextDialogue"] = 51170002,
            ["SpeakNpcId"] = 701202,
            },
        [51170002] = {
            ["Content"] = "谁没看路呢？！分明是我老远就叫着让她让开些，她却充耳不闻，我那车上放着多少重物，我骤然之间停不下来呀！",
            ["DialogueId"] = 51170002,
            ["GUID"] = "80194674.0",
            ["NextDialogue"] = 51170003,
            ["SpeakNpcName"] = "UI_NPC_Name_chengyu_Sce",
            },
        [51170003] = {
            ["Content"] = "老婆子年纪大了，有些耳背也是常事吧，你为何不让旁人提醒一下，现在说这些又有何用？",
            ["DialogueId"] = 51170003,
            ["GUID"] = "8019469E",
            ["NextDialogue"] = 51170004,
            ["SpeakNpcId"] = 701202,
            },
        [51170004] = {
            ["Content"] = "当时情况紧急，我根本想不出这些，只知道一味叫喊了，我喉咙都喊破她还没听到，那这撞上去还能赖我吗？",
            ["DialogueId"] = 51170004,
            ["GUID"] = "801946C8",
            ["NextDialogue"] = 51170005,
            ["SpeakNpcName"] = "UI_NPC_Name_chengyu_Sce",
            },
        [51170005] = {
            ["Content"] = "尽管诡辩！我不与你分说，来寻调解员，让他们给我们个公道！",
            ["DialogueId"] = 51170005,
            ["GUID"] = "801946F2",
            ["NextDialogue"] = 51170006,
            ["SpeakNpcId"] = 701202,
            },
        [51170006] = {
            ["Content"] = "二位先别急，我先在此问一句，您家婆婆被撞后现下伤势如何了？可曾医治？",
            ["DialogueId"] = 51170006,
            ["GUID"] = "8019471C",
            ["NextDialogue"] = 51170007,
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieyuan_Sce",
            },
        [51170007] = {
            ["Content"] = "腿上磕到了，乌青一大截，老年人本就骨头脆，现在已经在床上躺着了。",
            ["DialogueId"] = 51170007,
            ["GUID"] = "80194746.0",
            ["NextDialogue"] = 51170008,
            ["SpeakNpcId"] = 701202,
            },
        [51170008] = {
            ["Content"] = "需要我们先帮你问问泽生阁的医师们看看吗？",
            ["DialogueId"] = 51170008,
            ["GUID"] = "80194770.0",
            ["NextDialogue"] = 51170009,
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieyuan_Sce",
            },
        [51170009] = {
            ["Content"] = "皮也没破血也没出！还看什么！但凡出点血狴犴大人都来找我麻烦了！",
            ["DialogueId"] = 51170009,
            ["GUID"] = "8019479A",
            ["NextDialogue"] = 51170010,
            ["SpeakNpcName"] = "UI_NPC_Name_chengyu_Sce",
            },
        [51170010] = {
            ["Content"] = "你还好意思说！虽是表面看着没事，你怎么知道里面的骨头没什么问题呢？",
            ["DialogueId"] = 51170010,
            ["GUID"] = "801947C4",
            ["NextDialogue"] = 51170011,
            ["SpeakNpcId"] = 701202,
            },
        [51170011] = {
            ["Content"] = "我要求立刻介入调解，让调教员还我们家里一个公道！",
            ["DialogueId"] = 51170011,
            ["GUID"] = "801947EE",
            ["NextDialogue"] = 51170012,
            ["SpeakNpcId"] = 701202,
            },
        [51170012] = {
            ["Content"] = "你分明就是想借机生事，讹我一笔！",
            ["DialogueId"] = 51170012,
            ["GUID"] = "80194818.0",
            ["NextDialogue"] = 51170013,
            ["SpeakNpcName"] = "UI_NPC_Name_chengyu_Sce",
            },
        [51170013] = {
            ["Content"] = "二位别吵了……我这就帮你们记录在册，你们先各自回去，过两日会有专人介入。期间我们会去二位家中问询查证，届时也好各自还二位一个公道！",
            ["DialogueId"] = 51170013,
            ["GUID"] = "80194842.0",
            ["SpeakNpcName"] = "UI_NPC_Name_tiaojieyuan_Sce",
            },
        [51170101] = {
            ["Content"] = "为人在世，奉天命当如沙洲，勤而学当如竹溪先生。",
            ["DialogueId"] = 51170101,
            ["GUID"] = "801956B2",
            ["NextDialogue"] = 51170102,
            ["SpeakNpcId"] = 701203,
            },
        [51170102] = {
            ["Content"] = "有沙洲先生，入悬衡派后修订分香术，将所学所得整理并录入成册，造福后续有志于分香术的华胥人。",
            ["DialogueId"] = 51170102,
            ["GUID"] = "801956DC",
            ["NextDialogue"] = 51170103,
            ["SpeakNpcId"] = 701203,
            },
        [51170103] = {
            ["Content"] = "又有竹溪先生，不求仕进，反求教习著述，办分殊学院，方得我等万千学子之归。",
            ["DialogueId"] = 51170103,
            ["GUID"] = "80195706.0",
            ["NextDialogue"] = 51170104,
            ["SpeakNpcId"] = 701203,
            },
        [51170104] = {
            ["Content"] = "而今学院欣欣向荣，学子各自峥嵘，桃李遍天下，想必竹溪先生泉下有知，也当欣慰万分。",
            ["DialogueId"] = 51170104,
            ["GUID"] = "80195730.0",
            ["NextOptions"] = {
                [1] = 51170105,
                [2] = 51170112,
                },
            ["SpeakNpcId"] = 701203,
            },
        [51170105] = {
            ["Content"] = "你说的沙洲先生是？",
            ["DialogueId"] = 51170105,
            ["GUID"] = "8019575A",
            ["NextDialogue"] = 51170106,
            },
        [51170106] = {
            ["Content"] = "沙洲先生是华胥历史上赫赫有名的香官，在其之前，悬衡派的分香术仅仅只有天才才能修行，更别说勤加练习。",
            ["DialogueId"] = 51170106,
            ["GUID"] = "80195784.0",
            ["NextDialogue"] = 51170107,
            ["SpeakNpcId"] = 701203,
            },
        [51170107] = {
            ["Content"] = "但沙洲先生却整理了自己修习分香术的心得体会，写成《香籍》，分成上下两篇，上篇专门为闻香不敏者所书，让其也得窥分香术一二。",
            ["DialogueId"] = 51170107,
            ["GUID"] = "801957AE",
            ["NextDialogue"] = 51170108,
            ["SpeakNpcId"] = 701203,
            },
        [51170108] = {
            ["Content"] = "不过我本人对于沙洲先生的了解并不算多，想知道更多的信息，你可能得去祀烟阁查查资料。",
            ["DialogueId"] = 51170108,
            ["GUID"] = "801957D8",
            ["NextOptions"] = {
                [1] = 51170109,
                },
            ["SpeakNpcId"] = 701203,
            },
        [51170109] = {
            ["Content"] = "闻香不敏者指的是？",
            ["DialogueId"] = 51170109,
            ["GUID"] = "80195802.0",
            ["NextDialogue"] = 51170110,
            },
        [51170110] = {
            ["Content"] = "简单来说，其实就是那些对于香术上没有什么天赋的人，也就是华胥绝大多数普通人。",
            ["DialogueId"] = 51170110,
            ["GUID"] = "8019582C",
            ["NextDialogue"] = 51170111,
            ["SpeakNpcId"] = 701203,
            },
        [51170111] = {
            ["Content"] = "其实我本人就是……",
            ["DialogueId"] = 51170111,
            ["GUID"] = "80195856.0",
            ["SpeakNpcId"] = 701203,
            },
        [51170112] = {
            ["Content"] = "你说的竹溪先生是？",
            ["DialogueId"] = 51170112,
            ["GUID"] = "80195880.0",
            ["NextDialogue"] = 51170113,
            },
        [51170113] = {
            ["Content"] = "刚才我所说的你也听到了吧？竹溪先生曾任一官半职，后来却成了我们分殊学院的创办人，是我们所有学子尊敬并爱戴的先驱者。",
            ["DialogueId"] = 51170113,
            ["GUID"] = "801958AA",
            ["NextDialogue"] = 51170114,
            ["SpeakNpcId"] = 701203,
            },
        [51170114] = {
            ["Content"] = "而今先生已然魂归九泉，但其分殊辩理的观念依旧被学子之间口耳相传，学院也在这样的理念下发展得越来越好。",
            ["DialogueId"] = 51170114,
            ["GUID"] = "801958D4",
            ["NextOptions"] = {
                [1] = 51170115,
                [2] = 51170119,
                },
            ["SpeakNpcId"] = 701203,
            },
        [51170115] = {
            ["Content"] = "他以前是香官？",
            ["DialogueId"] = 51170115,
            ["GUID"] = "801958FE",
            ["NextDialogue"] = 51170116,
            },
        [51170116] = {
            ["Content"] = "竹溪先生以前是在天禄司任职。在其任职期间多逢区域旱灾，天禄天梁二司携手兴修水利，抗灾救荒，也不失为一段佳话。",
            ["DialogueId"] = 51170116,
            ["GUID"] = "80195928.0",
            ["NextDialogue"] = 51170117,
            ["SpeakNpcId"] = 701203,
            },
        [51170117] = {
            ["Content"] = "但竹溪先生年岁渐长后，便不再继续留任，而是将全部心思都投在学院的建设上。年迈之时，还不忘将学子所阅书籍逐章进行批注。",
            ["DialogueId"] = 51170117,
            ["GUID"] = "80195952.0",
            ["NextDialogue"] = 51170118,
            ["SpeakNpcId"] = 701203,
            },
        [51170118] = {
            ["Content"] = "曾经皓京最大的藏书阁，便是竹溪先生与其他同僚共同主持倡导，才修建落地，只可惜后来被歹人烧毁大半……实属憾事。",
            ["DialogueId"] = 51170118,
            ["GUID"] = "8019597C",
            ["SpeakNpcId"] = 701203,
            },
        [51170119] = {
            ["Content"] = "你听起来相当尊敬他。",
            ["DialogueId"] = 51170119,
            ["GUID"] = "801959A6",
            ["NextDialogue"] = 51170120,
            },
        [51170120] = {
            ["Content"] = "实不相瞒，我并非皓京本地之人，而是从外地赶来，只为在分殊学院求学，就是慕先生之名而来。",
            ["DialogueId"] = 51170120,
            ["GUID"] = "801959D0",
            ["NextDialogue"] = 51170121,
            ["SpeakNpcId"] = 701203,
            },
        [51170121] = {
            ["Content"] = "又或者说，在这里的每个学生，心里都是尊敬他的，我不过是万千之一。",
            ["DialogueId"] = 51170121,
            ["GUID"] = "801959FA",
            ["SpeakNpcId"] = 701203,
            },
        [51170201] = {
            ["Content"] = "我何时曾说我亲眼见过竹溪先生？我说的是父亲年幼之时，曾在学院听竹溪先生传授最后一课。",
            ["DialogueId"] = 51170201,
            ["GUID"] = "8019671A",
            ["NextDialogue"] = 51170202,
            ["SpeakNpcId"] = 701204,
            },
        [51170202] = {
            ["Content"] = "据我父所述，那时的竹溪先生已经满头华发，双眼几近失明，虽是身形佝偻，但讲课的精气神却是让人浑然忘却他的年龄。",
            ["DialogueId"] = 51170202,
            ["GUID"] = "80196744.0",
            ["NextDialogue"] = 51170203,
            ["SpeakNpcId"] = 701204,
            },
        [51170203] = {
            ["Content"] = "你们这些小家伙，成日贪玩不好好念书。那一字一句可都是当年的竹溪先生用心血批注所得。现下听完了故事，是不是该去发奋向学了？",
            ["DialogueId"] = 51170203,
            ["GUID"] = "8019676E",
            ["NextDialogue"] = 51170204,
            ["SpeakNpcId"] = 701204,
            },
        [51170204] = {
            ["Content"] = "先生敷衍！我们分明是要听好玩的故事，你回回都要扯到念书上来。",
            ["DialogueId"] = 51170204,
            ["GUID"] = "80196798.0",
            ["NextDialogue"] = 51170205,
            ["SpeakNpcName"] = "UI_NPC_Name_xuetong_Sce",
            },
        [51170205] = {
            ["Content"] = "来学院不和你们说念书我还说什么？你们这些坏娃娃，快去快去！",
            ["DialogueId"] = 51170205,
            ["GUID"] = "801967C2",
            ["NextDialogue"] = 51170206,
            ["SpeakNpcId"] = 701204,
            },
        [51170206] = {
            ["Content"] = "（学生们嘟囔抱怨着散开了。）",
            ["DialogueId"] = 51170206,
            ["GUID"] = "801967EC",
            ["NextDialogue"] = 51170207,
            },
        [51170207] = {
            ["Content"] = "咦？你是哪个学堂的孩子？我在这里怎么从未见过你？",
            ["DialogueId"] = 51170207,
            ["GUID"] = "80196816.0",
            ["NextOptions"] = {
                [1] = 51170208,
                [2] = 51170210,
                },
            ["SpeakNpcId"] = 701204,
            },
        [51170208] = {
            ["Content"] = "我是闲逛的。",
            ["DialogueId"] = 51170208,
            ["GUID"] = "80196840.0",
            ["NextDialogue"] = 51170209,
            },
        [51170209] = {
            ["Content"] = "哦，你看我说，学堂选址在街旁，隔三差五有路人不小心闯进来，下次要让他们建些院墙才好。",
            ["DialogueId"] = 51170209,
            ["GUID"] = "8019686A",
            ["SpeakNpcId"] = 701204,
            },
        [51170210] = {
            ["Content"] = "我是隔壁班的孩子。",
            ["DialogueId"] = 51170210,
            ["GUID"] = "80196894.0",
            ["NextDialogue"] = 51170211,
            },
        [51170211] = {
            ["Content"] = "隔壁班的孩子……是什么意思？",
            ["DialogueId"] = 51170211,
            ["GUID"] = "801968BE",
            ["NextDialogue"] = 51170212,
            ["SpeakNpcId"] = 701204,
            },
        [51170212] = {
            ["Content"] = "意思就是我成绩很好，但不在你们这里念书。",
            ["DialogueId"] = 51170212,
            ["GUID"] = "801968BF",
            ["NextDialogue"] = 51170213,
            ["SpeakNpcId"] = 100001,
            },
        [51170213] = {
            ["Content"] = "那么小同学，你有何贵干呀？",
            ["DialogueId"] = 51170213,
            ["GUID"] = "80196912.0",
            ["NextOptions"] = {
                [1] = 51170214,
                [2] = 51170218,
                },
            ["SpeakNpcId"] = 701204,
            },
        [51170214] = {
            ["Content"] = "你刚才提到的竹溪先生因为什么原因仙逝？",
            ["DialogueId"] = 51170214,
            ["GUID"] = "8019693C",
            ["NextDialogue"] = 51170215,
            },
        [51170215] = {
            ["Content"] = "其实我也不是特别清楚，对于竹溪先生的死因，传言有许多，大多都说他日渐年迈，又劳于学院琐事，心力交瘁而死。",
            ["DialogueId"] = 51170215,
            ["GUID"] = "80196966.0",
            ["NextDialogue"] = 51170216,
            ["SpeakNpcId"] = 701204,
            },
        [51170216] = {
            ["Content"] = "也有说是因为疾病困扰，后逐渐恶化，最终还是没熬过去。",
            ["DialogueId"] = 51170216,
            ["GUID"] = "80196990.0",
            ["NextDialogue"] = 51170217,
            ["SpeakNpcId"] = 701204,
            },
        [51170217] = {
            ["Content"] = "不过无论是何原因，竹溪先生发葬那日，光是为其送行的学子，就浩浩荡荡聚集了近千人，人人披麻戴孝，哀先生之逝也。",
            ["DialogueId"] = 51170217,
            ["GUID"] = "801969BA",
            ["SpeakNpcId"] = 701204,
            },
        [51170218] = {
            ["Content"] = "他们听不到的好玩的故事，你可以给我说吗？",
            ["DialogueId"] = 51170218,
            ["GUID"] = "801969BB",
            ["NextDialogue"] = 51170219,
            },
        [51170219] = {
            ["Content"] = "竟是在这等着我呢！罢了罢了，那便与你说上一说！",
            ["DialogueId"] = 51170219,
            ["GUID"] = "80196A0E",
            ["NextDialogue"] = 51170220,
            ["SpeakNpcId"] = 701204,
            },
        [51170220] = {
            ["Content"] = "我曾听闻，竹溪先生极其爱酒，这与他平日里正襟危坐的样子天差地别。说竹溪先生经常邀约一群好友相聚，焚香煮酒，探讨理之一道。",
            ["DialogueId"] = 51170220,
            ["GUID"] = "80196A38",
            ["NextDialogue"] = 51170221,
            ["SpeakNpcId"] = 701204,
            },
        [51170221] = {
            ["Content"] = "但有人说，竹溪先生酒品极差，每每讨论到后半程，酒意上涌，就粗着嗓子开始大辩特辩，平日里那满腹经纶全忘干净了，只顾着要争出高低来。",
            ["DialogueId"] = 51170221,
            ["GUID"] = "80196A62",
            ["NextDialogue"] = 51170222,
            ["SpeakNpcId"] = 701204,
            },
        [51170222] = {
            ["Content"] = "毕竟，分殊辩理本就是一门容易起争执的学问，就算据理力争，也会被误解为吵架或是起了争执。",
            ["DialogueId"] = 51170222,
            ["GUID"] = "80196A8C",
            ["NextDialogue"] = 51170223,
            ["SpeakNpcId"] = 701204,
            },
        [51170223] = {
            ["Content"] = "可若是完全不顾辩，只向对方宣扬理，那就是彻彻底底的吵架了。",
            ["DialogueId"] = 51170223,
            ["GUID"] = "80196AB6",
            ["NextDialogue"] = 51170224,
            ["SpeakNpcId"] = 701204,
            },
        [51170224] = {
            ["Content"] = "竹溪先生就是这样，每回都要把满堂宾客辩到再无一人吭声，后来久而久之，大家也不愿再与他一道喝酒辩理。",
            ["DialogueId"] = 51170224,
            ["GUID"] = "80196AE0",
            ["NextDialogue"] = 51170225,
            ["SpeakNpcId"] = 701204,
            },
        [51170225] = {
            ["Content"] = "后来先生嘴馋，又亲自去旧友家提礼敲门拜访，只求他人谅解。",
            ["DialogueId"] = 51170225,
            ["GUID"] = "80196B0A",
            ["NextOptions"] = {
                [1] = 51170226,
                [2] = 51170228,
                },
            ["SpeakNpcId"] = 701204,
            },
        [51170226] = {
            ["Content"] = "这位德高望重的竹溪先生酒品这么差。",
            ["DialogueId"] = 51170226,
            ["GUID"] = "80196B34",
            ["NextDialogue"] = 51170227,
            },
        [51170227] = {
            ["Content"] = "人无完人，一件事物都有千面百面之分，何况人呢？",
            ["DialogueId"] = 51170227,
            ["GUID"] = "80196B5E",
            ["SpeakNpcId"] = 701204,
            },
        [51170228] = {
            ["Content"] = "不是特别有趣，还有别的吗？",
            ["DialogueId"] = 51170228,
            ["GUID"] = "80196B88",
            ["NextDialogue"] = 51170229,
            },
        [51170229] = {
            ["Content"] = "没啦，小同学，要是以后还想听，记得来学院报个名，来年咱们再好好絮叨絮叨。",
            ["DialogueId"] = 51170229,
            ["GUID"] = "80196BB2",
            ["NextDialogue"] = 51170230,
            ["SpeakNpcId"] = 701204,
            },
        [51170230] = {
            ["Content"] = "现在，我可是要赶着去看看那些孩子们是不是真的在好好背书啦。",
            ["DialogueId"] = 51170230,
            ["GUID"] = "80196BDC",
            ["SpeakNpcId"] = 701204,
            },
        [51170301] = {
            ["Content"] = "吵死了……这怎么让人背书！",
            ["DialogueId"] = 51170301,
            ["GUID"] = "80197782.0",
            ["NextDialogue"] = 51170302,
            ["SpeakNpcId"] = 701205,
            },
        [51170302] = {
            ["Content"] = "以天下相传，天下之大事也。以天下之大圣，行天下之大事……",
            ["DialogueId"] = 51170302,
            ["GUID"] = "801977AC",
            ["NextDialogue"] = 51170303,
            ["SpeakNpcId"] = 701205,
            },
        [51170303] = {
            ["Content"] = "天下……天下为公，选贤与能……啊不是！这是背到哪里去了！",
            ["DialogueId"] = 51170303,
            ["GUID"] = "801977D6",
            ["NextDialogue"] = 51170304,
            ["SpeakNpcId"] = 701205,
            },
        [51170304] = {
            ["Content"] = "诶呀，夫子叫我三日之内背完，今日都已是第三日了，明天就要被抽查，这可如何是好……都怪这学院太吵，建哪里不好，偏要在街道旁！",
            ["DialogueId"] = 51170304,
            ["GUID"] = "80197800.0",
            ["NextOptions"] = {
                [1] = 51170305,
                },
            ["SpeakNpcId"] = 701205,
            },
        [51170305] = {
            ["Content"] = "街道旁怎么了？",
            ["DialogueId"] = 51170305,
            ["GUID"] = "8019782A",
            ["NextDialogue"] = 51170306,
            },
        [51170306] = {
            ["Content"] = "你听听！这小贩叫卖声，孩童嬉戏声！你闻闻！这美食的味道，这脂粉的香气！没有一个不在勾得人心痒痒，没一会就想着要去买点好吃好喝的……",
            ["DialogueId"] = 51170306,
            ["GUID"] = "80197854.0",
            ["NextOptions"] = {
                [1] = 51170307,
                [2] = 51170310,
                },
            ["SpeakNpcId"] = 701205,
            },
        [51170307] = {
            ["Content"] = "你心不静。",
            ["DialogueId"] = 51170307,
            ["GUID"] = "8019787E",
            ["NextDialogue"] = 51170308,
            },
        [51170308] = {
            ["Content"] = "你瞧瞧你，分明和我差不多岁数，怎得说话和夫子一样！说什么闹市在外，静心其中，我要真有如此造诣，我早就……",
            ["DialogueId"] = 51170308,
            ["GUID"] = "801978A8",
            ["NextDialogue"] = 51170309,
            ["SpeakNpcId"] = 701205,
            },
        [51170309] = {
            ["Content"] = "我早就当夫子了！我还需要背书吗？",
            ["DialogueId"] = 51170309,
            ["GUID"] = "801978D2",
            ["SpeakNpcId"] = 701205,
            },
        [51170310] = {
            ["Content"] = "说的是，为什么学院会在商店街旁？",
            ["DialogueId"] = 51170310,
            ["GUID"] = "801978FC",
            ["NextDialogue"] = 51170311,
            },
        [51170311] = {
            ["Content"] = "诶……还不是皓京这地形，早年建学院之时哪有什么东市，那一片都是黄树林，清净得很。",
            ["DialogueId"] = 51170311,
            ["GUID"] = "80197926.0",
            ["NextDialogue"] = 51170312,
            ["SpeakNpcId"] = 701205,
            },
        [51170312] = {
            ["Content"] = "后来皓京扩建，便这样扩出了一条偌大的商业街出来，为何不能让咱们也迁走呢？",
            ["DialogueId"] = 51170312,
            ["GUID"] = "80197950.0",
            ["NextDialogue"] = 51170313,
            ["SpeakNpcId"] = 701205,
            },
        [51170313] = {
            ["Content"] = "不和你说了，我得背书了，呜呼哀哉！身在闹市，唯吾静心……夫子啊！我悟不出来！你来渡我吧！啊！！！",
            ["DialogueId"] = 51170313,
            ["GUID"] = "8019797A",
            ["SpeakNpcId"] = 701205,
            },
        [51170401] = {
            ["Content"] = "所谓理一，即天地万物都只有一个理，所谓分殊，即千差万殊的事物都是一个理的体现。",
            ["DialogueId"] = 51170401,
            ["GUID"] = "801987EA",
            ["NextDialogue"] = 51170402,
            ["SpeakNpcId"] = 701206,
            },
        [51170402] = {
            ["Content"] = "先生，我没听懂，如何当得一个理，难不成先生和我是一个理吗？",
            ["DialogueId"] = 51170402,
            ["GUID"] = "80198814.0",
            ["NextDialogue"] = 51170403,
            ["SpeakNpcName"] = "UI_NPC_Name_beimei_Sce",
            },
        [51170403] = {
            ["Content"] = "我便举例于你分说，你说你与我是师徒之理，你有师，我也有师，我师亦有师，你若苦学，以后也定有徒。",
            ["DialogueId"] = 51170403,
            ["GUID"] = "8019883E",
            ["NextDialogue"] = 51170404,
            ["SpeakNpcId"] = 701206,
            },
        [51170404] = {
            ["Content"] = "即你我在师徒之理间，又有不同，其分而殊，即为分殊。",
            ["DialogueId"] = 51170404,
            ["GUID"] = "80198868.0",
            ["NextDialogue"] = 51170405,
            ["SpeakNpcId"] = 701206,
            },
        [51170405] = {
            ["Content"] = "可是先生，理……究竟是什么东西呢？",
            ["DialogueId"] = 51170405,
            ["GUID"] = "80198892.0",
            ["NextDialogue"] = 51170406,
            ["SpeakNpcName"] = "UI_NPC_Name_beimei_Sce",
            },
        [51170406] = {
            ["Content"] = "理，是天地万物之理，是自然恒转之理，是道法伦常之理，是治家安邦之理，是一切正确的，合乎常理的理，是为人处事的准则，是规矩，是道理。",
            ["DialogueId"] = 51170406,
            ["GUID"] = "801988BC",
            ["NextDialogue"] = 51170407,
            ["SpeakNpcId"] = 701206,
            },
        [51170407] = {
            ["Content"] = "听……听不懂……",
            ["DialogueId"] = 51170407,
            ["GUID"] = "801988BD",
            ["NextDialogue"] = 51170408,
            ["SpeakNpcName"] = "UI_NPC_Name_beimei_Sce",
            },
        [51170408] = {
            ["Content"] = "那我便拿大风九章举例，你知晓大风九章的规则，但你也清楚，人如果蓄意要存险恶之心，大风九章无法将所有违纪之事一一写上。",
            ["DialogueId"] = 51170408,
            ["GUID"] = "80198910.0",
            ["NextDialogue"] = 51170409,
            ["SpeakNpcId"] = 701206,
            },
        [51170409] = {
            ["Content"] = "毕竟大风九章只有九章，不是千章，万章，亿万章。但即使如此，那些作奸犯科之人所行之事，岂非不齿之事邪？",
            ["DialogueId"] = 51170409,
            ["GUID"] = "8019893A",
            ["NextDialogue"] = 51170410,
            ["SpeakNpcId"] = 701206,
            },
        [51170410] = {
            ["Content"] = "是以大风九章就是一种理，你顺理而行事，区分看待每一样不同的事物，即是理一分殊。",
            ["DialogueId"] = 51170410,
            ["GUID"] = "80198964.0",
            ["NextDialogue"] = 51170411,
            ["SpeakNpcId"] = 701206,
            },
        [51170411] = {
            ["Content"] = "我好像应该也许大概可能似乎依稀明白了……",
            ["DialogueId"] = 51170411,
            ["GUID"] = "8019898E",
            ["NextDialogue"] = 51170412,
            ["SpeakNpcName"] = "UI_NPC_Name_beimei_Sce",
            },
        [51170412] = {
            ["Content"] = "甚好，那便继续温书去吧！",
            ["DialogueId"] = 51170412,
            ["GUID"] = "801989B8",
            ["SpeakNpcId"] = 701206,
            },
        [51170501] = {
            ["Content"] = "五味万殊，而大同于美；曲变虽众，亦大同于和；子性各异，但大同于敏；教术众多，然大同于情。",
            ["DialogueId"] = 51170501,
            ["GUID"] = "80199852.0",
            ["NextDialogue"] = 51170502,
            ["SpeakNpcId"] = 701207,
            },
        [51170502] = {
            ["Content"] = "在对不同学子的教导方面，不违背竹溪先生的创院宗旨的基础上，因材施教才是正道。",
            ["DialogueId"] = 51170502,
            ["GUID"] = "8019987C",
            ["NextDialogue"] = 51170503,
            ["SpeakNpcId"] = 701207,
            },
        [51170503] = {
            ["Content"] = "贪玩爱闹的孩子和一心读书的孩子，你能说他们谁更聪明，谁更愚笨吗？",
            ["DialogueId"] = 51170503,
            ["GUID"] = "801998A6",
            ["NextOptions"] = {
                [1] = 51170504,
                },
            ["SpeakNpcId"] = 701207,
            },
        [51170504] = {
            ["Content"] = "看谁的成绩好？",
            ["DialogueId"] = 51170504,
            ["GUID"] = "801998D0",
            ["NextDialogue"] = 51170505,
            },
        [51170505] = {
            ["Content"] = "不然，你说的前提是你认为学业优异才是聪明，学业不佳则是愚笨。实则世上众多事都不能以成绩来论高低。",
            ["DialogueId"] = 51170505,
            ["GUID"] = "801998FA",
            ["NextDialogue"] = 51170506,
            ["SpeakNpcId"] = 701207,
            },
        [51170506] = {
            ["Content"] = "一孩子虽贪玩，却玩着玩着自己琢磨造出了个会动的小木马；一孩子虽潜心读书，却苦学许久未能背出一段诗文。",
            ["DialogueId"] = 51170506,
            ["GUID"] = "80199924.0",
            ["NextDialogue"] = 51170507,
            ["SpeakNpcId"] = 701207,
            },
        [51170507] = {
            ["Content"] = "现在你觉得是谁更聪明呢？",
            ["DialogueId"] = 51170507,
            ["GUID"] = "8019994E",
            ["NextOptions"] = {
                [1] = 51170508,
                [2] = 51170510,
                },
            ["SpeakNpcId"] = 701207,
            },
        [51170508] = {
            ["Content"] = "那可能是造木马的孩子聪明。",
            ["DialogueId"] = 51170508,
            ["GUID"] = "80199978.0",
            ["NextDialogue"] = 51170509,
            },
        [51170509] = {
            ["Content"] = "你又错了，倘若我再告诉你，那造木马的孩子压根大字不识一个，一看到诗文就头疼，哭嚎着要逃跑。",
            ["DialogueId"] = 51170509,
            ["GUID"] = "801999A2",
            ["NextOptions"] = {
                [1] = 51170512,
                },
            ["SpeakNpcId"] = 701207,
            },
        [51170510] = {
            ["Content"] = "那可能还是潜心读书的孩子聪明。",
            ["DialogueId"] = 51170510,
            ["GUID"] = "801999CC",
            ["NextDialogue"] = 51170511,
            },
        [51170511] = {
            ["Content"] = "是，也不是，那潜心读书的孩子后来发现，他竟有着超乎常人的分香辨香之术，无论是多么相似的香料，他都能很快识别。",
            ["DialogueId"] = 51170511,
            ["GUID"] = "801999F6",
            ["NextOptions"] = {
                [1] = 51170512,
                },
            ["SpeakNpcId"] = 701207,
            },
        [51170512] = {
            ["Content"] = "无论我说是谁，你都会反驳我。",
            ["DialogueId"] = 51170512,
            ["GUID"] = "80199A20",
            ["NextDialogue"] = 51170513,
            },
        [51170513] = {
            ["Content"] = "哈哈，莫要生气。我只是想说，其实以上我们讨论的内容，即是因材施教的必要性。",
            ["DialogueId"] = 51170513,
            ["GUID"] = "80199A4A",
            ["NextDialogue"] = 51170514,
            ["SpeakNpcId"] = 701207,
            },
        [51170514] = {
            ["Content"] = "我们所教授的理，无关某一个专业方向的长处，有的孩子天生就不擅背书，有的孩子费劲力气也不擅算学，这都不稀奇。",
            ["DialogueId"] = 51170514,
            ["GUID"] = "80199A74",
            ["NextDialogue"] = 51170515,
            ["SpeakNpcId"] = 701207,
            },
        [51170515] = {
            ["Content"] = "但将孩子们框死在一个框架里，那才是限制了理的方向，理应该是教孩子们判断什么是对的，什么是错的，什么是好的，什么是坏的。",
            ["DialogueId"] = 51170515,
            ["GUID"] = "80199A9E",
            ["NextDialogue"] = 51170516,
            ["SpeakNpcId"] = 701207,
            },
        [51170516] = {
            ["Content"] = "为人子则孝亲敬长，事龙君则鞠躬尽瘁，为偶则忠贞不渝，为友则肝胆相照。",
            ["DialogueId"] = 51170516,
            ["GUID"] = "80199AC8",
            ["NextDialogue"] = 51170517,
            ["SpeakNpcId"] = 701207,
            },
        [51170517] = {
            ["Content"] = "待人接物，当秉仁爱向善之信，博学笃行，当有明辨慎思之能，处事为人，当循自省修身之道。",
            ["DialogueId"] = 51170517,
            ["GUID"] = "80199AF2",
            ["NextDialogue"] = 51170518,
            ["SpeakNpcId"] = 701207,
            },
        [51170518] = {
            ["Content"] = "若是在此求学的所有孩子都能深刻领悟到其中真谛，未来无论成大事还是遵小节，都不会做出什么损人利己的坏事来。",
            ["DialogueId"] = 51170518,
            ["GUID"] = "80199B1C",
            ["NextDialogue"] = 51170519,
            ["SpeakNpcId"] = 701207,
            },
        [51170519] = {
            ["Content"] = "如此，才是分殊学院创办时，竹溪先生所求之愿啊。",
            ["DialogueId"] = 51170519,
            ["GUID"] = "80199B46",
            ["SpeakNpcId"] = 701207,
            },
        [51170601] = {
            ["Content"] = "这万事万物，道理总是只有一个，但一个道理却可涵盖了世间万物，所以理一定是在前面的！",
            ["DialogueId"] = 51170601,
            ["GUID"] = "8019A8BA",
            ["NextDialogue"] = 51170602,
            ["SpeakNpcId"] = 701208,
            },
        [51170602] = {
            ["Content"] = "此话不然，这万事万物的理是最为看不见也摸不着的，只有去结合具体事件，即分殊而论，才得以见理。",
            ["DialogueId"] = 51170602,
            ["GUID"] = "8019A8E4",
            ["NextDialogue"] = 51170603,
            ["SpeakNpcName"] = "UI_NPC_Name_wenqi_Sce",
            },
        [51170603] = {
            ["Content"] = "若是没有那个需要遵循的理，没有找到本源，如何得以发散出具体的事物？不过是空口说白话！",
            ["DialogueId"] = 51170603,
            ["GUID"] = "8019A90E",
            ["NextDialogue"] = 51170604,
            ["SpeakNpcId"] = 701208,
            },
        [51170604] = {
            ["Content"] = "倘如没有具体的事物践行，你所谓的那些理不过是空中楼阁罢了，只有先“分殊”才能推出“理一”！",
            ["DialogueId"] = 51170604,
            ["GUID"] = "8019A938",
            ["NextDialogue"] = 51170605,
            ["SpeakNpcName"] = "UI_NPC_Name_wenqi_Sce",
            },
        [51170605] = {
            ["Content"] = "那我问你，你没有理的支撑的时候，如何去分辨事物是对还是错？凭直觉？还是妄下结论，直接断言？",
            ["DialogueId"] = 51170605,
            ["GUID"] = "8019A962",
            ["NextDialogue"] = 51170606,
            ["SpeakNpcId"] = 701208,
            },
        [51170606] = {
            ["Content"] = "那我反倒要问你，你没有具体的行为实践与反思，如何领悟这个理？说到底是先认知到了某些事之间存在联系，再去归纳总结。",
            ["DialogueId"] = 51170606,
            ["GUID"] = "8019A98C",
            ["NextDialogue"] = 51170607,
            ["SpeakNpcName"] = "UI_NPC_Name_wenqi_Sce",
            },
        [51170607] = {
            ["Content"] = "胡搅蛮缠！竹溪先生曾说过，天上只有一个太阳，但太阳出来的时候每个角落都有光，岂不是说明先有的太阳才有的光？",
            ["DialogueId"] = 51170607,
            ["GUID"] = "8019A9B6",
            ["NextDialogue"] = 51170608,
            ["SpeakNpcId"] = 701208,
            },
        [51170608] = {
            ["Content"] = "歪理一堆，举证也不清晰，我不与你辩了。",
            ["DialogueId"] = 51170608,
            ["GUID"] = "8019A9E0",
            ["NextDialogue"] = 51170609,
            ["SpeakNpcName"] = "UI_NPC_Name_wenqi_Sce",
            },
        [51170609] = {
            ["Content"] = "回来！你不继续说，那就说明我赢了！",
            ["DialogueId"] = 51170609,
            ["GUID"] = "8019AA0A",
            ["NextDialogue"] = 51170610,
            ["SpeakNpcId"] = 701208,
            },
        [51170610] = {
            ["Content"] = "你看，你这不是因为我不再与你争执，你才得出你赢了的理？我再问你，是理一在前还是分殊在前？",
            ["DialogueId"] = 51170610,
            ["GUID"] = "8019AA34",
            ["NextDialogue"] = 51170611,
            ["SpeakNpcName"] = "UI_NPC_Name_wenqi_Sce",
            },
        [51170611] = {
            ["Content"] = "你！你这家伙，竟是诈我的！",
            ["DialogueId"] = 51170611,
            ["GUID"] = "8019AA5E",
            ["SpeakNpcId"] = 701208,
            },
        [51170701] = {
            ["Content"] = "今天该轮到你执勤了吧，之前你说你娘风寒，我可帮你顶了三天，夫子都起疑了！",
            ["DialogueId"] = 51170701,
            ["GUID"] = "8019B922",
            ["NextDialogue"] = 51170702,
            ["SpeakNpcId"] = 701209,
            },
        [51170702] = {
            ["Content"] = "好姐姐，再帮我顶两天吧，我娘最近咳嗽得又严重了些，我想今日放学带她去泽生阁看看呢！",
            ["DialogueId"] = 51170702,
            ["GUID"] = "8019B94C",
            ["NextDialogue"] = 51170703,
            ["SpeakNpcName"] = "UI_NPC_Name_junke_Sce",
            },
        [51170703] = {
            ["Content"] = "你少胡说八道，我爹说上次在城西果干摊子上见着你了，还问你怎的没回家，你却理都不理，分明就是心虚。",
            ["DialogueId"] = 51170703,
            ["GUID"] = "8019B976",
            ["NextDialogue"] = 51170704,
            ["SpeakNpcName"] = "UI_NPC_Name_zhangzhizhi_Sce",
            },
        [51170704] = {
            ["Content"] = "你才胡说八道，那是我娘嗓子不舒服，我去摊子给她买蜜饯就药吃。",
            ["DialogueId"] = 51170704,
            ["GUID"] = "8019B9A0",
            ["NextDialogue"] = 51170705,
            ["SpeakNpcName"] = "UI_NPC_Name_junke_Sce",
            },
        [51170705] = {
            ["Content"] = "好了好了……我可以给你替，但你得去跟夫子说清楚，不然回回他都用那种起疑的眼神看我，好像我做错了什么一样……",
            ["DialogueId"] = 51170705,
            ["GUID"] = "8019B9CA",
            ["NextDialogue"] = 51170706,
            ["SpeakNpcId"] = 701209,
            },
        [51170706] = {
            ["Content"] = "还是姐姐你善解人意，我这就去跟夫子说明白！",
            ["DialogueId"] = 51170706,
            ["GUID"] = "8019B9F4",
            ["NextDialogue"] = 51170707,
            ["SpeakNpcName"] = "UI_NPC_Name_junke_Sce",
            },
        [51170707] = {
            ["Content"] = "你分明被他骗了……他就是看你好欺负，是个冤大头！",
            ["DialogueId"] = 51170707,
            ["GUID"] = "8019BA1E",
            ["SpeakNpcName"] = "UI_NPC_Name_zhangzhizhi_Sce",
            },
        [51170801] = {
            ["Content"] = "下午的蹴球赛，咱们队还差一人，你问过樾山哥没有？他要是肯来，咱们定能踢得对面满地找牙！",
            ["DialogueId"] = 51170801,
            ["GUID"] = "8019C98A",
            ["NextDialogue"] = 51170802,
            ["SpeakNpcId"] = 701211,
            },
        [51170802] = {
            ["Content"] = "问过了，樾山哥说有事，今日就不来了。",
            ["DialogueId"] = 51170802,
            ["GUID"] = "8019C9B4",
            ["NextDialogue"] = 51170803,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170803] = {
            ["Content"] = "嘿！那可不行！他不来咱们人不齐，到时候就踢不上蹴球了！",
            ["DialogueId"] = 51170803,
            ["GUID"] = "8019C9DE",
            ["NextDialogue"] = 51170804,
            ["SpeakNpcId"] = 701211,
            },
        [51170804] = {
            ["Content"] = "不来的又不止是他，小珍今日身体不适，也不来了。",
            ["DialogueId"] = 51170804,
            ["GUID"] = "8019CA08",
            ["NextDialogue"] = 51170805,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170805] = {
            ["Content"] = "什么意思？那这球还踢不踢了？我今日课都没仔细听，一门心思想着就是下午的蹴球。",
            ["DialogueId"] = 51170805,
            ["GUID"] = "8019CA32",
            ["NextDialogue"] = 51170806,
            ["SpeakNpcId"] = 701211,
            },
        [51170806] = {
            ["Content"] = "踢不了，不然你们组些人白打，也算解了你的球瘾。",
            ["DialogueId"] = 51170806,
            ["GUID"] = "8019CA5C",
            ["NextDialogue"] = 51170807,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170807] = {
            ["Content"] = "不成！白打没意思！我不干！",
            ["DialogueId"] = 51170807,
            ["GUID"] = "8019CA86",
            ["NextDialogue"] = 51170808,
            ["SpeakNpcId"] = 701211,
            },
        [51170808] = {
            ["Content"] = "那这样，小珍说，过两天她想去西郊踏青，看看风景，你要不要去？",
            ["DialogueId"] = 51170808,
            ["GUID"] = "8019CAB0",
            ["NextDialogue"] = 51170809,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170809] = {
            ["Content"] = "我们现在说的是今日的事，你为何要和我提过两天的事？再说了，那踏青，回回走得人脚酸力竭的，谁去啊？",
            ["DialogueId"] = 51170809,
            ["GUID"] = "8019CADA",
            ["NextDialogue"] = 51170810,
            ["SpeakNpcId"] = 701211,
            },
        [51170810] = {
            ["Content"] = "芊芊也去，你还去不去？",
            ["DialogueId"] = 51170810,
            ["GUID"] = "8019CB04",
            ["NextDialogue"] = 51170811,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170811] = {
            ["Content"] = "啧……去！",
            ["DialogueId"] = 51170811,
            ["GUID"] = "8019CB2E",
            ["NextDialogue"] = 51170812,
            ["SpeakNpcId"] = 701211,
            },
        [51170812] = {
            ["Content"] = "那你今天下午有事做了，小珍点名要吃东市的糕点，那家总要排队，还三天两头关店休息，趁着今天开，你去排队买糕点吧。",
            ["DialogueId"] = 51170812,
            ["GUID"] = "8019CB58",
            ["NextDialogue"] = 51170813,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170813] = {
            ["Content"] = "凭什么？她要吃她自己去买，关我何事？",
            ["DialogueId"] = 51170813,
            ["GUID"] = "8019CB82",
            ["NextDialogue"] = 51170814,
            ["SpeakNpcId"] = 701211,
            },
        [51170814] = {
            ["Content"] = "随你。只是你可别忘了，当时可是你亲口答应她的，要是她陪你玩蹴球，你就请她吃一个月的糕点。",
            ["DialogueId"] = 51170814,
            ["GUID"] = "8019CBAC",
            ["NextDialogue"] = 51170815,
            ["SpeakNpcName"] = "UI_NPC_Name_qizhi_Sce",
            },
        [51170815] = {
            ["Content"] = "……知道了，我去就是，你跟她说，下次蹴球绝不能放我鸽子了！不然约定取消！",
            ["DialogueId"] = 51170815,
            ["GUID"] = "8019CBD6",
            ["SpeakNpcId"] = 701211,
            },
        [51170901] = {
            ["Content"] = "以往其实已经为学院扩建过一次，但现在招了年纪更小的孩子，学堂数量又不够用了。",
            ["DialogueId"] = 51170901,
            ["GUID"] = "8019D9F2",
            ["NextDialogue"] = 51170902,
            ["SpeakNpcId"] = 701212,
            },
        [51170902] = {
            ["Content"] = "可眼见着隔壁起了商街，这再扩建又能往哪里扩呢？",
            ["DialogueId"] = 51170902,
            ["GUID"] = "8019DA1C",
            ["NextOptions"] = {
                [1] = 51170903,
                },
            ["SpeakNpcId"] = 701212,
            },
        [51170903] = {
            ["Content"] = "看起来学院很受欢迎。",
            ["DialogueId"] = 51170903,
            ["GUID"] = "8019DA46",
            ["NextDialogue"] = 51170904,
            },
        [51170904] = {
            ["Content"] = "那是自然，自昔日学院创办后，求学之人便络绎不绝，早些年还未收取学金的时候，有学子家长提着两只大鹅就要来念书了。",
            ["DialogueId"] = 51170904,
            ["GUID"] = "8019DA70",
            ["NextDialogue"] = 51170905,
            ["SpeakNpcId"] = 701212,
            },
        [51170905] = {
            ["Content"] = "后来收的学金虽也不高，但至少不会闹出什么大鹅在学院叫嚷妨碍孩子们念书的事来。",
            ["DialogueId"] = 51170905,
            ["GUID"] = "8019DA9A",
            ["NextOptions"] = {
                [1] = 51170906,
                [2] = 51170910,
                },
            ["SpeakNpcId"] = 701212,
            },
        [51170906] = {
            ["Content"] = "为什么这么受欢迎？",
            ["DialogueId"] = 51170906,
            ["GUID"] = "8019DAC4",
            ["NextDialogue"] = 51170907,
            },
        [51170907] = {
            ["Content"] = "那这说法可就太多了，最开始多是慕竹溪先生之名，后来则是学院教出的孩子们一传十十传百。",
            ["DialogueId"] = 51170907,
            ["GUID"] = "8019DAEE",
            ["NextDialogue"] = 51170908,
            ["SpeakNpcId"] = 701212,
            },
        [51170908] = {
            ["Content"] = "不过最终还是天禄司给学院出资扩建，于是便在皓京成名了。早先华胥的许多学院都未曾有过如此规模。",
            ["DialogueId"] = 51170908,
            ["GUID"] = "8019DB18",
            ["NextDialogue"] = 51170909,
            ["SpeakNpcId"] = 701212,
            },
        [51170909] = {
            ["Content"] = "多半只是小型学堂，一间里有个一两位先生就差不多了，只咱们分殊学院特殊些。许是这样也更受欢迎吧。",
            ["DialogueId"] = 51170909,
            ["GUID"] = "8019DB42",
            ["NextOptions"] = {
                [1] = 51170914,
                },
            ["SpeakNpcId"] = 701212,
            },
        [51170910] = {
            ["Content"] = "大鹅后面去哪里了？",
            ["DialogueId"] = 51170910,
            ["GUID"] = "8019DB6C",
            ["NextDialogue"] = 51170911,
            },
        [51170911] = {
            ["Content"] = "这个嘛……能吃的都在年宴上宰了吃了，吃不完的也都送去给了城外的养殖户，不能吃的……",
            ["DialogueId"] = 51170911,
            ["GUID"] = "8019DB96",
            ["NextDialogue"] = 51170912,
            ["SpeakNpcId"] = 701212,
            },
        [51170912] = {
            ["Content"] = "春来一并放生了，因这事还遭到了批评，说咱们把外地的生物放归野外，导致那些家养的大鹅一时间觅不到食……",
            ["DialogueId"] = 51170912,
            ["GUID"] = "8019DBC0",
            ["NextDialogue"] = 51170913,
            ["SpeakNpcId"] = 701212,
            },
        [51170913] = {
            ["Content"] = "哈哈，不过这都是后话了~大体上并未造成什么困扰。",
            ["DialogueId"] = 51170913,
            ["GUID"] = "8019DBEA",
            ["NextOptions"] = {
                [1] = 51170914,
                },
            ["SpeakNpcId"] = 701212,
            },
        [51170914] = {
            ["Content"] = "所以再扩建的话要去哪里？",
            ["DialogueId"] = 51170914,
            ["GUID"] = "8019DC14",
            ["NextDialogue"] = 51170915,
            },
        [51170915] = {
            ["Content"] = "唔……确实没有想好，不过之前有位先生提过，说不然就搬去城外吧，正好学生也几度埋怨，说学院附近太躁扰。",
            ["DialogueId"] = 51170915,
            ["GUID"] = "8019DC3E",
            ["NextDialogue"] = 51170916,
            ["SpeakNpcId"] = 701212,
            },
        [51170916] = {
            ["Content"] = "有时候我也想着，搬去个远些的，偏僻些，但山清水秀的地方，又安静又有野趣，岂不美哉？",
            ["DialogueId"] = 51170916,
            ["GUID"] = "8019DC68",
            ["NextDialogue"] = 51170917,
            ["SpeakNpcId"] = 701212,
            },
        [51170917] = {
            ["Content"] = "但后来……你看，这学院里小娃娃也多了起来，若是有那些走读的孩子早上还得花好些时间去山郊野外上学，太难为他们了。",
            ["DialogueId"] = 51170917,
            ["GUID"] = "8019DC92",
            ["NextDialogue"] = 51170918,
            ["SpeakNpcId"] = 701212,
            },
        [51170918] = {
            ["Content"] = "不管啦，等真容纳不了的时候再说吧，或许也等不到那天呢。",
            ["DialogueId"] = 51170918,
            ["GUID"] = "8019DCBC",
            ["SpeakNpcId"] = 701212,
            },
        [51170919] = {
            ["Content"] = "按这个势头算下去，岂不是又要扩张？可这又还能往哪里扩呢？",
            ["DialogueId"] = 51170919,
            ["GUID"] = "8019D9F1",
            ["NextDialogue"] = 51170901,
            ["SpeakNpcId"] = 701212,
            },
        }
  end },
  { MinKey = 51171001, MaxKey = 51172101, Loader = function()
      return {
        [51171001] = {
            ["Content"] = "是了，来年开春便要递上辞函，到时候自然是会念着大家的，放心！",
            ["DialogueId"] = 51171001,
            ["GUID"] = "8019EA5A",
            ["NextDialogue"] = 51171002,
            ["SpeakNpcId"] = 701213,
            },
        [51171002] = {
            ["Content"] = "不再考虑考虑了？若是你想，我帮你问问，再涨些薪资也不是问题。",
            ["DialogueId"] = 51171002,
            ["GUID"] = "8019EA84",
            ["NextDialogue"] = 51171003,
            ["SpeakNpcName"] = "UI_NPC_Name_xuanwu_Sce",
            },
        [51171003] = {
            ["Content"] = "不啦，并非与之相关，只是在皓京待得太久，总觉得……有些想念家乡故友。",
            ["DialogueId"] = 51171003,
            ["GUID"] = "8019EAAE",
            ["NextDialogue"] = 51171004,
            ["SpeakNpcId"] = 701213,
            },
        [51171004] = {
            ["Content"] = "若是想念，便准你个假期，回家多待些日子。奉香大典过后再回来便是？",
            ["DialogueId"] = 51171004,
            ["GUID"] = "8019EAD8",
            ["NextDialogue"] = 51171005,
            ["SpeakNpcName"] = "UI_NPC_Name_xuanwu_Sce",
            },
        [51171005] = {
            ["Content"] = "好归好……只是……嗯……家中长辈也……",
            ["DialogueId"] = 51171005,
            ["GUID"] = "8019EB02",
            ["NextDialogue"] = 51171006,
            ["SpeakNpcId"] = 701213,
            },
        [51171006] = {
            ["Content"] = "我一向劝不动你，罢了，随你去了！",
            ["DialogueId"] = 51171006,
            ["GUID"] = "8019EB2C",
            ["NextDialogue"] = 51171007,
            ["SpeakNpcName"] = "UI_NPC_Name_xuanwu_Sce",
            },
        [51171007] = {
            ["Content"] = "是，多谢您海涵。",
            ["DialogueId"] = 51171007,
