            ["GUID"] = "801A81C8",
            ["NextDialogue"] = 51171925,
            },
        [51171925] = {
            ["Content"] = "嘿嘿~增高计划卓有成效嘛，我这就回家多找些垫子垫上~",
            ["DialogueId"] = 51171925,
            ["GUID"] = "801A81F2",
            ["SpeakNpcId"] = 701222,
            },
        [51172001] = {
