            ["DialogueId"] = 51172001,
            ["GUID"] = "801A8E6A",
            ["NextDialogue"] = 51172002,
            ["SpeakNpcId"] = 701223,
            },
        [51172002] = {
            ["Content"] = "您不知道？前些日子听说阁内出了事故，引来了几只玄色狴犴。",
            ["DialogueId"] = 51172002,
            ["GUID"] = "801A8E94",
            ["NextDialogue"] = 51172003,
            ["SpeakNpcName"] = "UI_NPC_Name_yuwei_Sce",
            },
        [51172003] = {
            ["Content"] = "哦？那动静可确实不小了，我怎么没听说过？后来如何解决的？",
