        [70010100] = {
            ["Camera"] = "6426.663086,7746.713379,-121.966454,0.253341,0.343415,-129.197754,35.0,350.0,false,Manual,2.8",
            ["Content"] = "TalkMechanism测试",
            ["DialogueId"] = 70010100,
            ["GUID"] = "AF435008",
            ["SpeakNpcId"] = 10201,
            },
        [70010101] = {
            ["Camera"] = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
            ["Content"] = "近日岛上秽兽日渐活跃，所有居民准备好船只与物资，随时准备出海避险。",
            ["ContentJP"] = "最近、島内の<Default note=\"text:エジュウ\">穢獣</>の活動が活発化している。島民はいつでも海へと避難できるよう、船と物資の準備を整えている。",
            ["DialogueId"] = 70010101,
            ["Duration"] = 5,
            ["GUID"] = "AF435032",
            ["SpeakNpcId"] = 102011,
            },
        [70010201] = {
            ["Camera"] = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
            ["Content"] = "居民谨记，为了避免海伯利亚官员发现我们，出海捕鱼时远离不明船只。\
祖辈为了避免卷入无谓的战争逃到这里，相信他们的智慧，严守告诫。",
            ["ContentJP"] = "住民の皆様へ、漁に出て見知らぬ船舶を発見した際には、速やかに遠ざかるように。ヒュペリア軍に見つかってはいけません。\
先祖たちは無益な戦争を避けるためにこの島まで逃れてきました。彼らの知恵を信じて戒めを守り抜きましょう。",
            ["DialogueId"] = 70010201,
            ["Duration"] = 5,
            ["GUID"] = "AF43609A",
            ["SpeakNpcId"] = 102012,
            },
        [70010301] = {
            ["Camera"] = "-364.107666,1506.973633,120.13916,0.000131,13.391685,87.755157,18.0,100000.0,false,Manual,18.0",
            ["Content"] = "村民们应该早已乘船逃离秽兽肆虐的村子，而远处的“天之树”正是他们出海的天然灯塔。",
            ["ContentJP"] = "穢獣から逃れるべく、村人たちは船に乗って村を脱出したに違いない。遠くの「天上樹」は彼らの出航を導く天然の灯台だ",
            ["DialogueId"] = 70010301,
            ["Duration"] = 5,
            ["GUID"] = "AF437102",
            ["SpeakNpcId"] = 102013,
            },
        [70010401] = {
            ["Camera"] = "-564.918457,-24.525635,71.417542,0.000015,34.991844,0.800468,18.0,1932.963745,false,Manual,2.8",
            ["Content"] = "从未见过的雕像，供奉着不知姓名的神明，不知是什么时代的遗物……",
            ["ContentJP"] = "見たこともない彫像。名も知らぬ神が祀られている。いつの時代の遺物なのだろうか……",
            ["DialogueId"] = 70010401,
            ["Duration"] = 5,
            ["GUID"] = "AF43816A",
            ["SpeakNpcId"] = 102014,
            },
        [70010501] = {
