        [70015701] = {
            ["Camera"] = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
            ["Content"] = "与月石颜色相似的晶石。但仔细观察，纹路和质地与月石完全不同，只是一些普通的“会发光的石头”而已。",
            ["ContentJP"] = "月ノ石に似た色の晶石。しかし、よく見ると、月ノ石とは模様も質感もまったく異なり、ただの「光る石」にすぎない。",
            ["DialogueId"] = 70015701,
            ["Duration"] = 5,
            ["GUID"] = "AF46E6F2",
            ["NextDialogue"] = 70015702,
            },
        [70015702] = {
            ["Camera"] = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
            ["Content"] = "人类按照使用价值把矿石分为三六九等，月石是珍贵的资源，而它们则是无用的废品。\
但也正因于此，月石被采掘一空，被打碎，被切割，最终成为工厂里冰凉的月髓液，而它们则幸运而完整地留下了。",
            ["ContentJP"] = "人間は鉱石をその利用価値に応じて様々な等級に分類する。月ノ石は貴重な資源であるが、これらの晶石は役に立たない廃棄物と見なされている。\
そのため、月ノ石は掘り尽くされ、砕かれ、切断され、最終的には工場で冷たいイコル液にされる一方で、これらの晶石は幸運にも完全な形で残されている。",
            ["DialogueId"] = 70015702,
            ["Duration"] = 5,
            ["GUID"] = "AF46E71C",
            },
        [70015801] = {
            ["Camera"] = "492.773438,-508.054688,926.297363,0.000004,-0.000096,143.197693,11.88,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "码头四处可见的大型起重装置。不同于帝国常见的铆钉与金属交织而成的冰冷风格，华胥的装置多以木制榫卯结构为主。细看其底座上刻着一行小字：天梁司制造。",
            ["ContentJP"] = "埠頭のあちこちに見られる大型の起重機。帝国でよく見られる、鋲と金属が入り組んだ冷たい意匠とは異なり、華胥の起重機は木製のほぞ組み構造が主流だ。土台をよく見ると、小さな文字で「天梁司製」と刻まれている。",
            ["DialogueId"] = 70015801,
            ["Duration"] = 5,
            ["GUID"] = "AF46F75A",
            },
        [70015901] = {
            ["Camera"] = "-447.582031,-536.535156,268.742676,0.000001,5.399906,55.198711,11.88,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "损毁的上古机傀，在岁月的摧折中早已失去了原始功能。其零件如今随意地散落在烟津渡的各处，被茂盛生长的草木掩盖。",
            ["ContentJP"] = "古代のからくり人形が損壊したもの。長い歳月に晒され、すでに本来の機能は失われている。部品は今や煙津渡のあちこちに散らばり、繁茂した草木にすっかり覆い隠されている。",
            ["DialogueId"] = 70015901,
            ["Duration"] = 5,
            ["GUID"] = "AF4707C2",
            },
        [70016001] = {
            ["Content"] = "<H>银烛狂欢</>将在盖雷亚剧院如期举行，请参与者自行准备你心仪的装扮，选择你要扮演的身份。\
让我们放下职业、放下种族、放下冲突相聚在于此，沐浴在皇帝的恩典之下，齐声赞颂皇帝的仁德，荣耀尽归吾皇！",
            ["ContentJP"] = "<H>銀燭祭り</>は予定通り、ガレア劇場で開催されます。参加者はお好きな衣装を用意し、ご自分の演じたい役を選んでください。さあ、職業や種族、争いごとを忘れ、ここに集いましょう。\
皇帝の恩寵を浴び、皇帝の仁徳をたたえるために！皇帝に栄光あれ！",
            ["DialogueId"] = 70016001,
            ["GUID"] = "AF47182A",
            },
        [70016002] = {
            ["Content"] = "厚厚的点名册，详细地记录了每位工作人员一天的行程，除了排练，连吃饭睡觉和如厕的行程都被记录在内。\
不知是剧团长狠心地将所有人“软禁”在剧院之内，还是剧团长为了保护自己的演员，而不得不时刻关注每个人的动向。",
            ["ContentJP"] = "厚い点呼記録簿。スタッフ全員の1日の行動が詳細に記録されている。リハーサルだけでなく、食事や睡眠、トイレに行く時間まですべてが記録されている。\
果たして、座長が皆を「軟禁」しているのか、あるいは自分の俳優たちを守るために行動を常に監視しているのか。",
            ["DialogueId"] = 70016002,
            ["GUID"] = "AF471854",
            },
        [70016003] = {
            ["Content"] = "帝皇尾戒勋章，完全由纯金打造，只会颁发给为帝国做出卓越贡献的军人。\
\
科赛托斯行省冰湖城第六军团下属卫戍部队，<H>黎瑟·费西尔</>。\
在连年、数次<H>清缴秽兽作战</>中，决策果断，作战英勇，收尾迅速。\
在维护地区治安的过程中起到了无可比拟的关键作用。\
现经军团评估，以吾皇尤里乌斯之名，授予黎瑟·费西尔帝皇尾戒勋章及准尉军衔，望广大军人以其为榜样，奋发上进，共同成长。\
荣耀尽归吾皇。",
            ["ContentJP"] = "純金で作られた勲章。一枚の黄金から成るその輝きは、帝国への卓越した貢献を称える証だ。添えられた賞賛の書状によれば、この勲章は並外れた功績を上げた軍人のみに授与されるという。",
            ["DialogueId"] = 70016003,
            ["GUID"] = "AF47187E",
            },
        [70016004] = {
            ["Content"] = "压在一堆杂物下的老旧报纸，记录着很久以前的悲惨事故。\
\
<H>秽蚀者异常凶险，不要被表象欺骗！</>\
9月24日，本市发生一起极为恶劣的“秽蚀”事件，经第六军团卫戍部队调查后，得出以下结论：\
冰湖城市民费西尔夫妇于9月13日在泪湖畔公路边上偶遇一名叫做罗比·布朗的青年。因其身受重伤，费西尔夫妇将其带回家中照料。\
然而，罗比·布朗是一名秽蚀者，他躲过了帝国对潜在秽蚀者的例行盘查并潜逃至城外，且在接受费西尔夫妇帮助时，刻意掩盖了自己的秽蚀痕迹。十日后，悲剧发生：布朗蜕变成为秽兽，杀死了包括费西尔夫妇在内数十名居住在冰湖城南区的市民。第六军团下属冰湖城卫戍部队紧急出动才平息此次骚乱。\
骚乱共造成18人死亡，其中包含3名索拉之民；另有34人受伤。在此提醒各位市民谨记，不要轻易收留身份不明的卡戎之民，一旦发现秽蚀者，立即上报治安署。它们永远只是人类的敌人，无一例外。如有刻意包庇秽蚀者、隐瞒不报者，一律按照《海伯利亚刑事法典》第54条规定，处以死刑。",
            ["ContentJP"] = "ガラクタの下に埋もれていた一枚の古びた新聞――そこには、かつて起きた悲劇的な事件が記されていた。",
            ["DialogueId"] = 70016004,
            ["GUID"] = "AF4718A8",
            },
