            ["ContentJP"] = "時間稼ぎか。皆、この{性别:小僧|小娘}から目を離すな。",
            ["DialogueId"] = 71002113,
            ["GUID"] = "B1BF102A",
            ["SpeakNpcId"] = 818008,
            },
        [71002114] = {
            ["Content"] = "来了来了——",
            ["ContentJP"] = "おーす、戻ったぜ！",
