            ["GUID"] = "B1BF1054",
            ["NextDialogue"] = 71002115,
            ["SpeakNpcId"] = 818007,
            },
        [71002115] = {
            ["Content"] = "啊？物资少了？哦！2条弹匣和1把步枪是吧。在我这儿呢，刚刚我把自己那份直接拿走了。",
            ["ContentJP"] = "え？足りない？ああ、弾倉2つとライフル1丁だろ？俺の分だって。さっき持ってったんだよ。",
            ["DialogueId"] = 71002115,
            ["GUID"] = "B1BF107E",
            ["NextDialogue"] = 71002116,
            ["SpeakNpcId"] = 818007,
            },
        [71002116] = {
            ["Content"] = "你也太不谨慎了——军团的物资随手丢给路人？万一是同盟的家伙怎么交差？",
            ["ContentJP"] = "馬鹿者が……軍の物資を部外者に任せて、敵の手先だったらどうする気だ？",
            ["DialogueId"] = 71002116,
            ["GUID"] = "B1BF10A8",
            ["NextDialogue"] = 71002117,
            ["SpeakNpcId"] = 818008,
            },
        [71002117] = {
            ["Content"] = "啊哈，抱歉抱歉，下次注意，下次注意。",
            ["ContentJP"] = "あー悪かった。次からは注意するって。",
            ["DialogueId"] = 71002117,
            ["GUID"] = "B1BF10D2",
            ["NextDialogue"] = 71002118,
            ["SpeakNpcId"] = 818007,
            },
        [71002118] = {
            ["Content"] = "{nickname}，这点东西你收下当赔礼吧，连累了你，怪不好意思的。",
            ["ContentJP"] = "{nickname}、これ謝礼な。面倒かけてすまないな。",
            ["DialogueId"] = 71002118,
            ["GUID"] = "B1BF10FC",
            ["Scripts"] = "TurnTo{TurnToDescription{\"818007:n(0)\"}}",
            ["SpeakNpcId"] = 818007,
            },
        [71002201] = {
            ["Content"] = "咱不想……不想……不想上工啊……",
            ["ContentJP"] = "はぁ……仕事キライ……さぼりたい……",
            ["DialogueId"] = 71002201,
            ["GUID"] = "B1BF1E9A",
            ["SpeakNpcId"] = 818019,
            },
        [71002202] = {
            ["Content"] = "唉，老板非要搞什么什么——“让银色和平饭店的饭菜走进千家万户”，但他完全没考虑过咱们这些跑腿的苦哇！",
            ["ContentJP"] = "はぁ、店長ってばいつもいつも――「シルバーピース店の料理を全世界に届けよう」なんて言ってるけどさ……使いっぱしりにされてるこっちの身にもなってほしいもんだよ！",
            ["DialogueId"] = 71002202,
            ["GUID"] = "B1BF1EC4",
            ["NextDialogue"] = 71002203,
            ["SpeakNpcId"] = 818019,
            },
        [71002203] = {
            ["Content"] = "需要帮忙吗？",
            ["ContentJP"] = "手伝おっか？",
            ["DialogueId"] = 71002203,
            ["GUID"] = "B1BF1EEE",
            ["NextDialogue"] = 71002204,
            ["SpeakNpcId"] = 100001,
            },
        [71002204] = {
            ["Content"] = "需要，我非常需要一个人替我上工，不花钱的那种！唉……可惜根本没有这种好事！",
            ["ContentJP"] = "ほんと！？代わりに働いてくれる人探してたんだよね……できれば、タダ働きでーなんちゃって……",
            ["DialogueId"] = 71002204,
            ["GUID"] = "B1BF1F18",
            ["NextDialogue"] = 71002205,
            ["SpeakNpcId"] = 818019,
            },
        [71002205] = {
            ["Content"] = "你如果非要帮我拎点东西的话，那我除了谢谢，最多只能请你去泪湖边喝水喝到饱了。",
            ["ContentJP"] = "ちょっと配達物を運んでくれたら、感謝の言葉以外に、ダクリ湖の水をおなか一杯飲ませてあげてもいいよ！",
            ["DialogueId"] = 71002205,
            ["GUID"] = "B1BF1F42",
            ["SpeakNpcId"] = 818019,
            },
        [71002206] = {
            ["Content"] = "这皎皎身上带了不少吃的？哥几个今天看来有口福了呀。",
            ["ContentJP"] = "このルーナ、ずいぶん旨そうなもん持ってんな？こりゃあ今夜は御馳走だな。",
            ["DialogueId"] = 71002206,
            ["GUID"] = "B1BF1F6C",
            ["NextDialogue"] = 71002207,
            ["SpeakNpcId"] = 818057,
            },
        [71002207] = {
            ["Content"] = "不能给你们！这些菜送不到客人那的话我工钱就要被扣光了……",
            ["ContentJP"] = "これはあなたたちのじゃない！もし、ちゃんとお客さんに届けられなかったら、給料全部引かれちゃうんだから……",
            ["DialogueId"] = 71002207,
            ["GUID"] = "B1BF1F96",
            ["NextDialogue"] = 71002208,
            ["SpeakNpcId"] = 818019,
            },
        [71002208] = {
            ["Content"] = "关我们啥事，拿来吧你！",
            ["ContentJP"] = "そんなの俺らには関係ねぇ！さっさとよこせ！",
            ["DialogueId"] = 71002208,
            ["GUID"] = "B1BF1F97",
            ["NextDialogue"] = 71002209,
            ["SpeakNpcId"] = 818057,
            },
        [71002209] = {
            ["Content"] = "住手！",
            ["ContentJP"] = "そこまで{性别:だ|よ}！",
            ["DialogueId"] = 71002209,
            ["GUID"] = "B1BF1F98",
            ["SpeakNpcId"] = 100001,
            },
        [71002210] = {
            ["Content"] = "呼……还好汤没洒，我们快送过去吧……",
            ["ContentJP"] = "ふぅ……スープがこぼれなくてよかった……はやくお客さんに届けよう！",
            ["DialogueId"] = 71002210,
            ["GUID"] = "B1BF1FC0",
            ["SpeakNpcId"] = 818019,
            },
        [71002211] = {
            ["Content"] = "搞定搞定，还差最后一份！真是的，老板能不能少点奇思妙想哇……",
            ["ContentJP"] = "ふぅ、次ので最後だね！店長にも少しは変なアイデアを控えてほしいものだよ……",
            ["DialogueId"] = 71002211,
            ["GUID"] = "B1BF20BC",
            ["SpeakNpcId"] = 818019,
            },
        [71002212] = {
            ["Content"] = "这种杂物是怎么堆到大路上的啊……可恶！怎么今天所有东西都在跟我作对！",
            ["ContentJP"] = "なんで、こんなモノが道のど真ん中に……ああ！今日はまったくツイてなさすぎる！",
            ["DialogueId"] = 71002212,
            ["GUID"] = "B1BF1FEA",
            ["NextDialogue"] = 71002218,
            ["SpeakNpcId"] = 818019,
            },
        [71002213] = {
            ["Content"] = "你把吃的拿好，我来清理这些东西吧。",
            ["ContentJP"] = "片付けるから、ちょっと出前持ってて。",
            ["DialogueId"] = 71002213,
            ["GUID"] = "B1BF2014",
            ["SpeakNpcId"] = 100001,
            },
        [71002214] = {
            ["Content"] = "居然都清完了！那这时间还来得及！冲冲冲冲冲！",
            ["ContentJP"] = "すごい……こんなはやく片付くなんて！今ならまだ間に合う！急げ急げ！！",
            ["DialogueId"] = 71002214,
            ["GUID"] = "B1BF2015",
            ["SpeakNpcId"] = 818019,
            },
        [71002215] = {
            ["Content"] = "总算都送到了……要不是有你，我一点工钱都拿不到了。呼……休息好了，咱也该回去继续干活了。",
            ["ContentJP"] = "やっと全部送り届けた……あなたがいなかったら、給料もパァになるとこだったよ！さて、休みもとれたことだし、仕事に戻らないとね。",
            ["DialogueId"] = 71002215,
            ["GUID"] = "B1BF203E",
            ["NextDialogue"] = 71002216,
            ["SpeakNpcId"] = 818019,
            },
        [71002216] = {
            ["Content"] = "说好的辞职呢？",
            ["ContentJP"] = "辞職するんじゃなかった{性别:んだ|の}？",
            ["DialogueId"] = 71002216,
            ["GUID"] = "B1BF2068",
            ["NextDialogue"] = 71002217,
            ["SpeakNpcId"] = 100001,
            },
        [71002217] = {
            ["Content"] = "（外送皎皎拍了拍身上的灰尘便转身离开了。回答你问题的答案，也被藏在了她转身时的那一声叹息之中。）",
            ["ContentJP"] = "配達ルーナは身体の埃を払うと、そのまま立ち去った。あなたの質問に返ってきたのは、ため息だけだった。",
            ["DialogueId"] = 71002217,
            ["GUID"] = "B1BF2092",
            ["SpeakNpcId"] = 800006,
            },
        [71002218] = {
            ["Content"] = "不干了不干了！我要和老板说，这破活我不干啦！",
            ["ContentJP"] = "もうやめやめ！こうなったら、辞職届を出してやる！",
            ["DialogueId"] = 71002218,
            ["GUID"] = "B1BF1FEB",
            ["NextDialogue"] = 71002213,
            ["SpeakNpcId"] = 818019,
            },
        [71002301] = {
            ["Content"] = "嘶……刚刚那下没摔坏吧……",
            ["ContentJP"] = "っ……壊れてないよな？",
            ["DialogueId"] = 71002301,
            ["GUID"] = "B1BF2F02",
            ["SpeakNpcId"] = 818020,
            },
        [71002302] = {
            ["Content"] = "谁？！",
            ["ContentJP"] = "誰だ！？",
            ["DialogueId"] = 71002302,
            ["GUID"] = "B1BF2F2C",
            ["NextDialogue"] = 71002303,
            ["SpeakNpcId"] = 818020,
            },
        [71002303] = {
            ["Content"] = "嗯……咳，只是路过的狩月人啊。诶，我说，要不要来帮我个忙？就测下这玩意儿好不好用，很容易的！我会付你报酬。",
            ["ContentJP"] = "な、なんだ……通りすがりの月狩り人か。なぁ、ちょっと手伝ってくれないか？なぁに、これがちゃんと使えるか試すだけでいいんだ。報酬は弾むぜ。",
            ["DialogueId"] = 71002303,
            ["GUID"] = "B1BF2F56",
            ["SpeakNpcId"] = 818020,
            },
        [71002304] = {
            ["Content"] = "坚持15秒就差不多了，加油！",
            ["ContentJP"] = "15秒ほどでいい。頼んだぜ！",
            ["DialogueId"] = 71002304,
            ["GUID"] = "B1BF2F80",
            ["SpeakNpcId"] = 818020,
            },
        [71002305] = {
            ["Content"] = "居然全都躲过去了……不是说这是从艾利西安缴获的宝贝吗，我看跟破铜烂铁也没啥区别——啊没没，没什么，这些钱给你，别到处乱说啊。",
            ["ContentJP"] = "全部躱しやがった……エリュシオンから奪った宝物だと聞いたが、どうみてもただのガラクタじゃねぇか――あ、いや、なんでもねぇよ。ほら、金だ。このことは誰にも言うんじゃねぇぞ。",
            ["DialogueId"] = 71002305,
            ["GUID"] = "B1BF2FAA",
            ["SpeakNpcId"] = 818020,
            },
        [71002306] = {
            ["Content"] = "这人被打到怎么还活蹦乱跳的……不是说这是艾利西安缴获的宝贝吗，到底行不行啊——啊没没，没什么，这些钱给你，别到处乱说啊。",
            ["ContentJP"] = "命中したってのに、ピンピンしてやがる……エリュシオンから奪った宝物だと聞いたが、本当か？……あ、いや、なんでもねぇよ。ほら、金だ。このことは誰にも言うんじゃねぇぞ。",
            ["DialogueId"] = 71002306,
            ["GUID"] = "B1BF2FD4",
            ["SpeakNpcId"] = 818020,
            },
        [71002401] = {
            ["Content"] = "怎么勘探器还没干活就坏了，我的修理工具呢……",
            ["ContentJP"] = "探査機め、使う前から壊れるなんてどういうこと！？ええと、修理道具はっと……",
            ["DialogueId"] = 71002401,
            ["GUID"] = "B1BF3F6A",
            ["SpeakNpcId"] = 818015,
            },
        [71002402] = {
            ["Content"] = "我们在这种地方都能遇到，太有缘了吧！既然你来了，那要不要帮忙照看下我的宝贝勘探器？",
            ["ContentJP"] = "ここで会えるなんて、これも何かの縁だね！せっかくだし、うちのお宝探査機を見ててくれない？",
            ["DialogueId"] = 71002402,
            ["GUID"] = "B1BF3F94",
            ["SpeakNpcId"] = 818015,
            },
        [71002403] = {
            ["Content"] = "好耶，你就在它边上不要走动哦，我找到工具了就回来！",
            ["ContentJP"] = "サンキュー！じゃあ、そこで待ってて。使える道具を見つけたら、すぐに戻ってくるから！",
            ["DialogueId"] = 71002403,
            ["GUID"] = "B1BF3FBE",
            ["NextDialogue"] = 71002404,
            ["SpeakNpcId"] = 818015,
            },
        [71002404] = {
            ["Content"] = "看起来是有几个零件卡住了，把它们弄开的话应该会更好修一些。",
            ["ContentJP"] = "（部品がいくつか引っかかってるようだ。うまく外せば、修理しやすくなるはず。）",
            ["DialogueId"] = 71002404,
            ["GUID"] = "B1BF3FE8",
            ["SpeakNpcId"] = 100001,
            },
        [71002405] = {
            ["Content"] = "（勘探器的响动将周围的秽兽吸引了过来，击退它们吧。）",
            ["ContentJP"] = "探査機の音に、周囲の<Default note=\"text:エジュウ\">穢獣</>が集まってきてしまった。退治しよう！",
            ["DialogueId"] = 71002405,
            ["GUID"] = "B1BF4012",
            ["SpeakNpcId"] = 800006,
            },
        [71002406] = {
            ["Content"] = "诶，你还帮我把卡住的零件掰开了吗，好感动！",
            ["ContentJP"] = "あれ、引っかかってた部品を外してくれたの！？ちょっと感動だよ！！",
            ["DialogueId"] = 71002406,
            ["GUID"] = "B1BF403C",
            ["SpeakNpcId"] = 818015,
            },
        [71002407] = {
            ["Content"] = "久等啦！我就知道交给你照看肯定没问题！",
            ["ContentJP"] = "おまたせ！あなたに任せたのは正解だったようだね！",
            ["DialogueId"] = 71002407,
            ["GUID"] = "B1BF4066",
            ["SpeakNpcId"] = 818015,
            },
        [71002501] = {
            ["Content"] = "唉……这破下水道怎么又堵了……",
            ["ContentJP"] = "はぁ……また詰まっちまったぜ",
            ["DialogueId"] = 71002501,
            ["GUID"] = "B1BF4FD2",
            ["SpeakNpcId"] = 818021,
            },
        [71002502] = {
            ["Content"] = "发生什么了？",
            ["ContentJP"] = "どうしたの？",
            ["DialogueId"] = 71002502,
            ["GUID"] = "B1BF4FFC",
            ["NextDialogue"] = 71002503,
            ["SpeakNpcId"] = 100001,
            },
        [71002503] = {
            ["Content"] = "这片下水道堵住了，长官给了我个说明书，但我根本看不懂啊……你能帮帮我吗？",
            ["ContentJP"] = "ここ一帯の下水道が詰まっちまったんだよ。長官から説明書をもらったんだが、まったく理解できねぇ……手を貸してくれるか？",
            ["DialogueId"] = 71002503,
            ["GUID"] = "B1BF5026",
            ["NextOptions"] = {
                [1] = 710025041,
                [2] = 710025042,
                },
            ["SpeakNpcId"] = 818021,
            },
        [71002505] = {
            ["Content"] = "说明书上说，遇到下水道堵塞只要开启三道闸门放水强冲即可。",
            ["ContentJP"] = "説明書には「下水道が詰まった場合は、三つの水門を開けて、勢いよく水を流せば解消できる」と書いてある。",
            ["DialogueId"] = 71002505,
            ["GUID"] = "B1BF507A",
            ["NextDialogue"] = 71002511,
            ["SpeakNpcId"] = 100001,
            },
        [71002507] = {
            ["Content"] = "好嘞，接下来第二个在那边。",
            ["ContentJP"] = "了解！2つ目はあっちだ。",
            ["DialogueId"] = 71002507,
            ["GUID"] = "B1BF50CE",
            ["SpeakNpcId"] = 818021,
            },
        [71002508] = {
            ["Content"] = "第三个我看看啊……找到了，就在那！",
            ["ContentJP"] = "3つ目は……あった！あそこだ！",
            ["DialogueId"] = 71002508,
            ["GUID"] = "B1BF50F8",
            ["SpeakNpcId"] = 818021,
            },
        [71002509] = {
            ["Content"] = "好，我已经完全掌握了！这是我的一点心意，辛苦你啦！",
            ["ContentJP"] = "よし、もうバッチリ覚えたぜ！これ、ほんの気持ちだけど……ありがとうな！",
            ["DialogueId"] = 71002509,
            ["GUID"] = "B1BF5122",
            ["SpeakNpcId"] = 818021,
            },
        [71002510] = {
            ["Content"] = "嘿，你这法子也不赖嘛，来来，这是给你的报酬。",
            ["ContentJP"] = "へえ、あんたのやり方、なかなか悪くないな。ほら、報酬だ。",
            ["DialogueId"] = 71002510,
            ["GUID"] = "B1BF514C",
            ["SpeakNpcId"] = 818021,
            },
        [71002511] = {
            ["Content"] = "原来是这样啊，那你能示范一下怎么操作吗，我看着学一下。",
            ["ContentJP"] = "なるほどな。じゃあ、ちょっとやり方を見せてもらってもいいか？見ながら覚えるからさ。",
            ["DialogueId"] = 71002511,
            ["GUID"] = "B1BF507B",
            ["SpeakNpcId"] = 818021,
            },
        [71002601] = {
            ["Content"] = "可恶，这镐子也太不耐用了，剩下这些石头咋办呢，总不能让我用手挖吧……",
            ["ContentJP"] = "ちくしょう、このツルハシ脆すぎだろ……残りの岩、どうすんだよ。まさか素手で掘れってか……",
            ["DialogueId"] = 71002601,
            ["GUID"] = "B1BF603A",
            ["SpeakNpcId"] = 818023,
            },
        [71002602] = {
            ["Content"] = "看你的打扮，也是狩月人吧。我接的这个挖石头委托一个人做不完了，你要不要跟我一起？报酬直接分你一半。",
            ["ContentJP"] = "その身なり……あんたも月狩り人か。実は石を掘る依頼を引き受けたんだけど、一人じゃどうも手に負えなくてな。一緒にやらねぇか？報酬は半分分けてやるからさ。",
            ["DialogueId"] = 71002602,
            ["GUID"] = "B1BF6064",
            ["NextOptions"] = {
                [1] = 710026021,
                [2] = 710026022,
                },
            ["SpeakNpcId"] = 818023,
            ["bForbidSkipOptions"] = true,
            },
        [71002603] = {
            ["Content"] = "好，剩下的这些就交给你了，我来整理下之前挖好的。",
            ["ContentJP"] = "よし、じゃあ残りの採掘は頼むぜ。俺はさっき堀り出した石を整理しとくから。",
            ["DialogueId"] = 71002603,
            ["GUID"] = "B1BF608E",
            ["SpeakNpcId"] = 818023,
            },
        [71002604] = {
            ["Content"] = "原来还有这种办法，太厉害了！",
            ["ContentJP"] = "その手があったか！あんた賢いな！！",
            ["DialogueId"] = 71002604,
            ["GUID"] = "B1BF60B8",
            ["NextDialogue"] = 71002605,
            ["SpeakNpcId"] = 818023,
            },
        [71002605] = {
            ["Content"] = "辛苦你了，这是说好的报酬。",
            ["ContentJP"] = "ご苦労様。約束の報酬だ。",
            ["DialogueId"] = 71002605,
            ["GUID"] = "B1BF60E2",
            ["SpeakNpcId"] = 818023,
            },
        [71002701] = {
            ["Content"] = "（一些木桶顺着水道漂来，有的还发出着诡异的声响，谨慎打开的话，也许能发现一些有用的东西。）",
            ["ContentJP"] = "いくつかの木樽水路を伝って流れてきた。中には不気味な音を立てているものもある。慎重に開ければ、役に立つものが見つかるかもしれない。",
            ["DialogueId"] = 71002701,
            ["GUID"] = "B1BF70A2",
            ["SpeakNpcId"] = 800006,
            },
        [71002702] = {
            ["Content"] = "（木桶底部破了个大洞，除了风声穿过的嘶吼，你找不到任何有用的东西，去看看其他木桶吧。）",
            ["ContentJP"] = "樽の底に大きな穴が開いていて、風が通り抜けるヒュウヒュウという音しか聞こえない。役に立ちそうなものは何も見つからなかった。他の樽も見てみよう。",
            ["DialogueId"] = 71002702,
            ["GUID"] = "B1BF70CC",
            ["SpeakNpcId"] = 800006,
            },
        [71002703] = {
            ["Content"] = "（木桶里装满了生活垃圾，散发着咕嘟咕嘟的闷响和刺鼻的气味，去看看其他木桶吧。）",
            ["ContentJP"] = "樽の中にはゴミが詰まっていた。ブクブクと鈍い音を立てながら、鼻をつく悪臭が漂ってきた。他の樽を見てみよう。",
            ["DialogueId"] = 71002703,
            ["GUID"] = "B1BF70F6",
            ["SpeakNpcId"] = 800006,
            },
        [71002704] = {
            ["Content"] = "（付出必然要有回报，仔细翻找之后，你果然在木桶的夹层里找到了一些能用的物资。）",
            ["ContentJP"] = "やっぱり、努力は報われるものだ。念入りに探ったおかげで、樽の二重底から使えそうな物資を見つけた。",
            ["DialogueId"] = 71002704,
            ["GUID"] = "B1BF7120",
            ["SpeakNpcId"] = 800006,
            },
        [71002705] = {
            ["Content"] = "（破旧的木桶轰然散架，巨大的噪音将周围的秽兽吸引了过来，击败它们，拿到你应得的战利品吧。）",
            ["ContentJP"] = "ボロボロの木樽が派手な音を立てて崩れ落ちた。その音で周囲の<Default note=\"text:エジュウ\">穢獣</>が集まってきてしまった。奴らを倒して、戦利品を手に入れよう。",
            ["DialogueId"] = 71002705,
            ["GUID"] = "B1BF714A",
            ["SpeakNpcId"] = 800006,
            },
        [71002801] = {
            ["Content"] = "（坍塌的碎石挡住了前路，将它们清理掉吧。）",
            ["ContentJP"] = "崩れ落ちた瓦礫が道を塞いでいる。片づけて道を開こう。",
            ["DialogueId"] = 71002801,
            ["GUID"] = "B1BF810A",
            ["SpeakNpcId"] = 800006,
            },
        [71002802] = {
            ["Content"] = "（你在清理碎石的过程中找到了些能用的物资，将它们收好吧。）",
            ["ContentJP"] = "瓦礫を片付けてる最中に、使えそうなものをいくつか見つけた。さっそく回収しよう。",
            ["DialogueId"] = 71002802,
            ["GUID"] = "B1BF8134",
            ["SpeakNpcId"] = 800006,
            },
        [71002803] = {
            ["Content"] = "（清理碎石的响动将周围的秽兽吸引了过来，借助洞顶的落石击退它们吧。）",
            ["ContentJP"] = "瓦礫を整理する音に、周囲の<Default note=\"text:エジュウ\">穢獣</>が集まってきてしまった。頭上の岩を利用して、退治しよう。",
            ["DialogueId"] = 71002803,
            ["GUID"] = "B1BF815E",
            ["SpeakNpcId"] = 800006,
            },
        [71002804] = {
            ["Content"] = "（一番战斗后，你在周围找到了些能用的物资，将它们收好吧。）",
            ["ContentJP"] = "戦闘の末、使える物資をいくつか見つけた。さっそく回収しよう。",
            ["DialogueId"] = 71002804,
            ["GUID"] = "B1BF8188",
            ["SpeakNpcId"] = 800006,
            },
        [71002901] = {
            ["Content"] = "（敌人在士官的指挥下稳步向你推进，尽快击败士官，打乱对方的指挥吧。）",
            ["ContentJP"] = "（司令官に率いられた敵が着々と迫ってくる。司令官を倒して、敵の陣形を崩そう。）",
            ["DialogueId"] = 71002901,
            ["GUID"] = "B1BF9172",
            ["SpeakNpcId"] = 800006,
            },
        [71002902] = {
            ["Content"] = "（敌人在你冷静而正确的应对中溃败。）",
            ["ContentJP"] = "（あなたの冷静な判断と的確な対応で、敵は崩れ去った。）",
            ["DialogueId"] = 71002902,
            ["GUID"] = "B1BF919C",
            ["SpeakNpcId"] = 800006,
            },
        [71002903] = {
            ["Content"] = "（士官呼叫了新的援军，更多的敌人向你袭来了。）",
            ["ContentJP"] = "（司令官が援軍を要請した。新手の敵が押し寄せてくる。）",
            ["DialogueId"] = 71002903,
            ["GUID"] = "B1BF91C6",
            ["SpeakNpcId"] = 800006,
            },
        [71003001] = {
            ["Content"] = "（游荡的秽兽不安地嘶吼着，为附近笼罩起一丝不详的气息。尽快击退它们吧。）",
            ["ContentJP"] = "（<Default note=\"text:エジュウ\">穢獣</>たちが不気味に唸り、あたり不吉な気配が漂う。早くやつらを追い払おう。）",
            ["DialogueId"] = 71003001,
            ["GUID"] = "B1BFA1DA",
            ["SpeakNpcId"] = 800006,
            },
        [71003002] = {
            ["Content"] = "（笼罩于此的不详气息越发凝重，你知道，有什么东西就要降临了。）",
            ["ContentJP"] = "（この場に漂う不吉な気配が濃くなってきた。何かが、降り立とうとしている。）",
            ["DialogueId"] = 71003002,
            ["GUID"] = "B1BFA204",
            ["SpeakNpcId"] = 800006,
            },
        [71003003] = {
            ["Content"] = "（争斗的声响引来了不屈的灾厄，不详的化身终于降临于此。击败它吧，就像过去的无数次一样。）",
            ["ContentJP"] = "（戦いの音が災いを呼び寄せ、不吉な化身が姿を現した。過去に何度もそうしてきたように、撃退しよう。）",
            ["DialogueId"] = 71003003,
            ["GUID"] = "B1BFA22E",
            ["SpeakNpcId"] = 800006,
            },
        [71003004] = {
            ["Content"] = "（不祥的气息随着这些秽兽一同消失了，你知道，这附近暂时安全了。）",
            ["ContentJP"] = "（<Default note=\"text:エジュウ\">穢獣</>と共に不吉な気配も消え去った。しばらくは、この辺りも安全だろう。）",
            ["DialogueId"] = 71003004,
            ["GUID"] = "B1BFA258",
            ["SpeakNpcId"] = 800006,
            },
        [71003101] = {
            ["Content"] = "（最近多了好些觊觎魔灵的家伙，击退他们，救下眼前这只可怜的魔灵吧。）",
            ["ContentJP"] = "最近、ジェネモンを狙う輩が増えてきている。今すぐ彼らを撃破し、可哀そうなジェネモンを救おう。",
            ["DialogueId"] = 71003101,
            ["GUID"] = "B1BFB242",
            ["SpeakNpcId"] = 800006,
            },
        [71003102] = {
            ["Content"] = "（更多敌人从远处冲了过来。）",
            ["ContentJP"] = "さらに多くの敵が、遠方から駆けつけてきた。",
            ["DialogueId"] = 71003102,
            ["GUID"] = "B1BFB26C",
            ["SpeakNpcId"] = 800006,
            },
        [71003103] = {
            ["Content"] = "（现在，这只魔灵安全了。）",
            ["ContentJP"] = "このジェネモンはもう安全だ。",
            ["DialogueId"] = 71003103,
            ["GUID"] = "B1BFB296",
            ["SpeakNpcId"] = 800006,
            },
        [71003201] = {
            ["Content"] = "（坍塌的碎石挡住了前路，四周遗落的爆炸物也许能帮你更快地清理这些碎石。）",
            ["ContentJP"] = "崩れ落ちた瓦礫が道を塞いでいる。この辺りに転がってる爆発物をうまく使えば、手っ取り早く片付けられるかも。",
            ["DialogueId"] = 71003201,
            ["GUID"] = "B1BFC2AA",
            ["SpeakNpcId"] = 800006,
            },
        [71003202] = {
            ["Content"] = "（你找到了矿工们的简易爆破手册，勉强还能分辨出上面写的内容。）",
            ["ContentJP"] = "鉱夫たちが使ってた簡易な爆破マニュアルを見つけた。かなり汚れているが、ギリギリ内容が読める。",
            ["DialogueId"] = 71003202,
            ["GUID"] = "B1BFC2D4",
            ["SpeakNpcId"] = 800006,
            },
        [71003203] = {
            ["Content"] = "（你找到了一些爆炸物，稍微处理下应该还能用。）",
            ["ContentJP"] = "爆発物をいくつか見つけた。少し加工すれば使えるかも。",
            ["DialogueId"] = 71003203,
            ["GUID"] = "B1BFC2FE",
            ["SpeakNpcId"] = 800006,
            },
        [71003204] = {
            ["Content"] = "（你找到了一些引线，稍微处理下应该还能用。）",
            ["ContentJP"] = "導火線をいくつか見つけた。少し加工すれば使えるかも。",
            ["DialogueId"] = 71003204,
            ["GUID"] = "B1BFC328",
            ["SpeakNpcId"] = 800006,
            },
        [71003206] = {
            ["Content"] = "（你按照矿工手册上的指示安装好了爆炸物，用它们清空面前区域吧。）",
            ["ContentJP"] = "マニュアル通りに爆発物を組み立てた。さっそく目の前の障害物を吹き飛ばそう。",
            ["DialogueId"] = 71003206,
            ["Duration"] = 3,
            ["GUID"] = "B1BFC37C",
            ["SpeakNpcId"] = 800006,
            },
        [71003207] = {
            ["Content"] = "（你在清理碎石的过程中找到了些能用的物资，将它们收好吧。）",
            ["ContentJP"] = "瓦礫を片付けてる最中に、使えそうなものをいくつか見つけた。さっそく回収しよう。",
            ["DialogueId"] = 71003207,
            ["GUID"] = "B1BFC3A6",
            ["SpeakNpcId"] = 800006,
            },
        [71003501] = {
            ["Content"] = "（远处闪闪发光的东西吸引了你的注意，靠近看看到底是什么吧。）",
            ["ContentJP"] = "遠くで何かが光っている……近くまで行って、確かめてみよう。",
            ["DialogueId"] = 71003501,
            ["GUID"] = "B1BFF3E2",
            ["SpeakNpcId"] = 800006,
            },
        [71003502] = {
            ["Content"] = "我就说这亮闪闪的破镜子能引来狩月人吧，动手！",
            ["ContentJP"] = "ほらな！この鏡を使えば月狩り人が釣れるって言っただろ！！",
            ["DialogueId"] = 71003502,
            ["GUID"] = "B1BFF40C",
            ["SpeakNpcId"] = 818028,
            },
        [71003504] = {
            ["Content"] = "别打了别打了，我们再也不敢了……",
            ["ContentJP"] = "や、やめてくれ……もう二度としませんから……",
            ["DialogueId"] = 71003504,
            ["GUID"] = "B1BFF460",
            ["SpeakNpcId"] = 818028,
            },
        [71003601] = {
            ["Content"] = "（四周突然响起了刺耳的警报，大量磁暴机朝你涌了过来。）",
            ["ContentJP"] = "突如、四方から警報が鳴り響いた。次の瞬間、無数の磁気ドローンがなだれ込んできた。",
            ["DialogueId"] = 71003601,
            ["GUID"] = "B1C0044A",
            ["SpeakNpcId"] = 800006,
            },
        [71003602] = {
            ["Content"] = "（警报愈发响亮，更多敌人朝你涌了过来。）",
            ["ContentJP"] = "警報はさらに激しく鳴り響き、敵がこちらへとなだれ込んできた。",
            ["DialogueId"] = 71003602,
            ["GUID"] = "B1C00474",
            ["SpeakNpcId"] = 800006,
            },
        [71003603] = {
            ["Content"] = "（在逐渐安静的警报声中，最后一批敌人抵达了此处。）",
            ["ContentJP"] = "警報が徐々に静まっていく中、敵の集団は全員この場所に到達した。",
            ["DialogueId"] = 71003603,
            ["GUID"] = "B1C0049E",
            ["SpeakNpcId"] = 800006,
            },
        [71003604] = {
            ["Content"] = "（伴随着所有敌人倒下，四周总算重归寂静。）",
            ["ContentJP"] = "すべての敵が倒れ、辺りはようやく静寂を取り戻した。",
            ["DialogueId"] = 71003604,
            ["GUID"] = "B1C004C8",
            ["SpeakNpcId"] = 800006,
            },
        [71003701] = {
            ["Content"] = "咱不想……不想……不想上工啊……",
            ["ContentJP"] = "はぁ……仕事キライ……さぼりたい……",
            ["DialogueId"] = 71003701,
            ["GUID"] = "B1C014B2",
            ["SpeakNpcId"] = 818019,
            },
        [71003702] = {
            ["Content"] = "可恶……怎么这次还要往泪湖送吃的啊。大家就不能挑点正常的地方吃饭吗！不怕出事吗！跑死我了……",
            ["ContentJP"] = "はぁ……なんで皆してダクリ湖に飯運ぶのさ。たまにはもっとマシな場所で食べられないの？危険だとか思うでしょ普通……もう、走りすぎて足ガクガクだよ……",
            ["DialogueId"] = 71003702,
            ["GUID"] = "B1C014DC",
            ["NextDialogue"] = 71003703,
            ["SpeakNpcId"] = 818019,
            },
        [71003703] = {
            ["Content"] = "需要帮忙吗？",
            ["ContentJP"] = "手伝おっか？",
            ["DialogueId"] = 71003703,
            ["GUID"] = "B1C014DD",
            ["NextDialogue"] = 71003704,
            ["SpeakNpcId"] = 100001,
            },
        [71003704] = {
            ["Content"] = "需要！我需要你狠狠咬几口这些麻烦的客人，还要朝他们丢一大堆雪球！让他们以后别在这么难找的地方叫人送菜了。",
            ["ContentJP"] = "お願い！！あの面倒くさい客どもに一発かましてよ！それと雪玉、いっぱいぶつけてやって！もう二度とあんなわけわかんない場所で出前なんて頼ませないんだから！",
            ["DialogueId"] = 71003704,
            ["GUID"] = "B1C014DE",
            ["NextOptions"] = {
                [1] = 710037041,
                [2] = 710037042,
                },
            ["SpeakNpcId"] = 818019,
            ["bForbidSkipOptions"] = true,
            },
        [71003705] = {
            ["Content"] = "唉……也就只能嘴上过过瘾了，你来了就陪咱一起去吧，多个人路上还能解解闷。上工上工……",
            ["ContentJP"] = "ったく……文句ぐらいしか言えないんだもん。来たなら付き合ってよ。ひとりよりマシだし。……んじゃ、しぶしぶ出発～、おしごとおしごと。",
            ["DialogueId"] = 71003705,
            ["GUID"] = "B1C01506",
            ["SpeakNpcId"] = 818019,
            },
        [71003706] = {
            ["Content"] = "这些冰渣渣掉进菜里就不好了，有没有什么办法把它们清理掉呢……",
            ["ContentJP"] = "うわ、こんな氷の破片が料理に入ったら大変だよ。どうにかして片づけられないかな～……",
            ["DialogueId"] = 71003706,
            ["GUID"] = "B1C01530",
            ["SpeakNpcId"] = 818019,
            },
        [71003707] = {
            ["Content"] = "诶，好快！菜都还是暖的呢，我们快点送过去吧，不然老板又要唠唠叨叨了。",
            ["ContentJP"] = "えっ、もうっ！？料理もまだ冷めてない……よし、急ごう！また店長に小言言われる前に！",
            ["DialogueId"] = 71003707,
            ["GUID"] = "B1C01656",
            ["SpeakNpcId"] = 818019,
            },
        [71003708] = {
            ["Content"] = "救命啊，至少让我吃饱了再死！",
            ["ContentJP"] = "助けてくれー！せめて腹いっぱい食わせてから殺して！",
            ["DialogueId"] = 71003708,
            ["GUID"] = "B1C0155A",
            ["NextDialogue"] = 71003709,
            ["SpeakNpcId"] = 818029,
            },
        [71003709] = {
            ["Content"] = "居然真出事了啊！我们过去救他吧，如果他在老板面前夸夸我，老板说不定会给咱加工钱呢，嘿嘿，嘿嘿嘿……",
            ["ContentJP"] = "ほ～ら言わんこっちゃない！はやく助けてあげよ！店長の前で褒めてくれるかもしれないし。そんでもって……給料アップ……えへ、えへへ……",
            ["DialogueId"] = 71003709,
            ["GUID"] = "B1C01584",
            ["SpeakNpcId"] = 818019,
            },
        [71003710] = {
            ["Content"] = "碍眼的家伙没了，还有新鲜的饭菜，配着泪湖的美景，真是一大享受啊~",
            ["ContentJP"] = "邪魔者はいなくなったし、ダクリ湖の景色を眺めながら、出来立てホヤホヤの料理を堪能できるなんて……極楽極楽～",
            ["DialogueId"] = 71003710,
            ["GUID"] = "B1C015AE",
            ["NextDialogue"] = 71003711,
            ["SpeakNpcId"] = 818024,
            },
        [71003711] = {
            ["Content"] = "啊，那个……客人，你还没付钱……",
            ["ContentJP"] = "あ、その……お客さん、まだお代をいただいてないんだけど……",
            ["DialogueId"] = 71003711,
            ["GUID"] = "B1C015D8",
            ["NextDialogue"] = 71003712,
            ["SpeakNpcId"] = 818019,
            },
        [71003712] = {
            ["Content"] = "嗯？你不就是个跑腿的吗，站在这干啥？餐钱等我下次去你们餐厅再结。",
            ["ContentJP"] = "ん？ただの使いっ走りが、いつまでそこに突っ立ってるつもりだ？金なら今度店に行った時に払うよ。",
            ["DialogueId"] = 71003712,
            ["GUID"] = "B1C01602",
            ["NextDialogue"] = 71003713,
            ["SpeakNpcId"] = 818024,
            },
        [71003713] = {
            ["Content"] = "可是……这样咱没法交差呀……",
            ["ContentJP"] = "そんな……店長に怒られちゃうよ……",
            ["DialogueId"] = 71003713,
            ["Duration"] = 3,
            ["GUID"] = "B1C0162C",
            ["NextDialogue"] = 71003714,
            ["SpeakNpcId"] = 818019,
            },
        [71003714] = {
            ["Content"] = "（你将一切看在眼里，迈步跟了上去。没有人注意到，你背在身后的手上已经悄悄攒出了一枚雪球，蓄势待发。）",
            ["ContentJP"] = "全てを見ていたあなたは、誰にも気付かれずにそっと彼らに近づいた。その背中に隠した手には、ひとつの雪玉が静かに握られていた。あなたはグッと力を込めた。",
            ["DialogueId"] = 71003714,
            ["Duration"] = 4,
            ["GUID"] = "B1C0162D",
            ["NextDialogue"] = 71003715,
            ["SpeakNpcId"] = 800006,
            },
        [71003715] = {
            ["Content"] = "啊！哪来的雪球，好冰好冰！啊啊啊啊我的饭掉水里了！不————",
            ["ContentJP"] = "ぎゃっ！なんだこの雪玉は！！つ、冷たっ！ああああ！飯が湖に……！！",
            ["DialogueId"] = 71003715,
            ["GUID"] = "B1C0162E",
            ["SpeakNpcId"] = 818024,
            },
        [71003801] = {
            ["Content"] = "（游荡的秽兽挤满了通道，击退它们吧。）",
            ["ContentJP"] = "通路が<Default note=\"text:エジュウ\">穢獣</>の集団で塞がれている。退治しよう。",
            ["DialogueId"] = 71003801,
            ["GUID"] = "B1C0251A",
            ["SpeakNpcId"] = 800006,
            },
        [71003802] = {
            ["Content"] = "（更多秽兽被打斗的声响吸引，涌向了通道，击退它们吧。）",
            ["ContentJP"] = "戦闘の音に引き寄せられ、さらに多くの<Default note=\"text:エジュウ\">穢獣</>が通路へとなだれ込んできた。はやく退治しよう。",
            ["DialogueId"] = 71003802,
            ["GUID"] = "B1C02544",
            ["SpeakNpcId"] = 800006,
            },
        [71003803] = {
            ["Content"] = "（通道中的所有秽兽都被你清理干净，这里暂时安全了。）",
            ["ContentJP"] = "通路の<Default note=\"text:エジュウ\">穢獣</>はすべて排除された。これでひとまず安全だ。",
            ["DialogueId"] = 71003803,
            ["GUID"] = "B1C0256E",
            ["SpeakNpcId"] = 800006,
            },
        [71003901] = {
            ["Content"] = "房间中传来一股肃杀的气息，不安的预感萦绕在心头（待包装）",
            ["DialogueId"] = 71003901,
            ["GUID"] = "B1C03582",
            ["SpeakNpcId"] = 800006,
            },
        [71003902] = {
            ["Content"] = "齿轮运动的声音响起，敌人正从开启的通道口中窜出（待包装）",
            ["DialogueId"] = 71003902,
            ["GUID"] = "B1C035AC",
            ["SpeakNpcId"] = 800006,
            },
        [71003903] = {
            ["Content"] = "又是齿轮响动的声音，不远处的两个通道也开启了（待包装）",
            ["DialogueId"] = 71003903,
            ["GUID"] = "B1C035D6",
            ["SpeakNpcId"] = 800006,
            },
        [71003904] = {
            ["Content"] = "齿轮转动，室内的全部通道均已开启，努力击杀敌人吧（待包装）",
            ["DialogueId"] = 71003904,
            ["GUID"] = "B1C03600",
            ["SpeakNpcId"] = 800006,
            },
        [71003905] = {
            ["Content"] = "所有通道均已关闭，剩余的敌人将在不久后溃散（待包装）",
            ["DialogueId"] = 71003905,
            ["GUID"] = "B1C0362A",
            ["SpeakNpcId"] = 800006,
            },
        [71004101] = {
            ["Content"] = "（废弃飞艇不知何时成了山间部分动物的大号储物箱，翻找一下也许能发现些有用的物资。）",
            ["ContentJP"] = "いつの間にか、廃棄された飛空艇が山中の動物たちの巨大な物置になっていたらしい。中を探ってみれば、何か役に立つ物資が見つかるかもしれない。",
            ["DialogueId"] = 71004101,
            ["GUID"] = "B1C05652",
            ["SpeakNpcId"] = 800006,
            },
        [71004102] = {
            ["Content"] = "（翻动物资的声响将周围的敌人吸引了过来，击退他们吧。）",
            ["ContentJP"] = "物資を探る音が周囲の敵を引き寄せてしまった。撃退しよう。",
            ["DialogueId"] = 71004102,
            ["GUID"] = "B1C056A6",
            ["SpeakNpcId"] = 800006,
            },
        [71004103] = {
            ["Content"] = "（敌人退去，现在可以清点下你方才收集的物资了。）",
            ["ContentJP"] = "敵を撃退した。今のうちに、さきほど集めた物資を確認しておこう。",
            ["DialogueId"] = 71004103,
            ["GUID"] = "B1C056D0",
            ["SpeakNpcId"] = 800006,
            },
        [71004201] = {
            ["Content"] = "唔嗯嗯嗯嗯，好结实……",
            ["ContentJP"] = "うひょー！かったい……",
            ["DialogueId"] = 71004201,
            ["GUID"] = "B1C066BA",
            ["SpeakNpcId"] = 818038,
            },
        [71004202] = {
            ["Content"] = "你在干什么？",
            ["ContentJP"] = "何をしてるの？",
            ["DialogueId"] = 71004202,
            ["GUID"] = "B1C066E4",
            ["NextDialogue"] = 71004203,
            ["SpeakNpcId"] = 100001,
            },
        [71004203] = {
            ["Content"] = "我最近在研究秽兽的生态，你要不要帮我找点死掉的秽兽样本呀。",
            ["ContentJP"] = "<Default note=\"text:エジュウ\">穢獣</>の生態を調べてるんだよ。暇なら<Default note=\"text:エジュウ\">穢獣</>のサンプルを集めてくれない？もちろん、息してないやつでお願いね。",
            ["DialogueId"] = 71004203,
            ["GUID"] = "B1C066E5",
            ["NextOptions"] = {
                [1] = 710042031,
                [2] = 710042032,
                },
            ["SpeakNpcId"] = 818038,
            },
        [71004204] = {
            ["Content"] = "好，那就交给你了！我先休息一下，一直一个人收集样本差点累死我……",
            ["ContentJP"] = "やった！それじゃお願いね。私はちょっと休んでくるよ。ひとりで集めてたから、マジ倒れるとこだったんだ～",
            ["DialogueId"] = 71004204,
            ["GUID"] = "B1C0670E",
            ["SpeakNpcId"] = 818038,
            },
        [71004205] = {
            ["Content"] = "呜哇哇哇，周围怎么还有活的秽兽呀，别过来别过来，是我研究你们不是你们研究我！",
            ["ContentJP"] = "ぎゃあああ！な、なんで生きた<Default note=\"text:エジュウ\">穢獣</>がここに！？く、来るな！研究するのは私であって、あんたたちじゃないのよ！",
            ["DialogueId"] = 71004205,
            ["GUID"] = "B1C06738",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 818038,
            },
        [71004206] = {
            ["Content"] = "谢啦谢啦，现在样本集齐了，我也该去继续研究了，下次见喽！",
            ["ContentJP"] = "ほんとありがと！サンプルも揃ったことだし、そろそろ研究に戻るよ。またね！",
            ["DialogueId"] = 71004206,
            ["GUID"] = "B1C0678C",
            ["SpeakNpcId"] = 818038,
            },
        [71004301] = {
            ["Content"] = "（这一带总能捡到些漂亮的贝壳，打碎那些冲上岸的箱子找找看吧。）",
            ["ContentJP"] = "このあたりでは、キレイな貝殻がたくさん堕ちている。打ち上げられた箱を割ってみよう。",
            ["DialogueId"] = 71004301,
            ["GUID"] = "B1C07722",
            ["SpeakNpcId"] = 800006,
            },
        [71004302] = {
            ["Content"] = "（你在箱子底部找到了些被压住的贝壳。）",
            ["ContentJP"] = "箱の底から大量の貝殻が見つかった。",
            ["DialogueId"] = 71004302,
            ["GUID"] = "B1C0774C",
            ["SpeakNpcId"] = 800006,
            },
        [71004303] = {
            ["Content"] = "（你早就听闻部分秽兽会躲藏在阴暗的箱子内袭击他人，但不幸的是，这一次它们撞上你了。击败它们，拿到你应得的战利品吧。）",
            ["ContentJP"] = "一部の<Default note=\"text:エジュウ\">穢獣</>は、暗い箱に潜んで他者を襲うことがある――そんな噂は前から聞いていた。だが、それが自分の身に降りかかるとは思ってもいなかった。退治して戦利品を手に入れよう。",
            ["DialogueId"] = 71004303,
            ["GUID"] = "B1C07776",
            ["SpeakNpcId"] = 800006,
            },
        [71004401] = {
            ["Content"] = "（游荡的秽兽挤满了四周，先击退它们，再去解救魔灵吧。）",
            ["ContentJP"] = "あたりは<Default note=\"text:エジュウ\">穢獣</>で埋め尽くされている。やつらを退治してから、ジェネモンの捕獲に移ろう。",
            ["DialogueId"] = 71004401,
            ["GUID"] = "B1C0878A",
            ["SpeakNpcId"] = 800006,
            },
        [71004402] = {
            ["Content"] = "（争斗的声响引来了不屈的灾厄，不详的化身终于降临于此。击败它吧，就像过去的无数次一样。）",
            ["ContentJP"] = "争いの音が不屈の禍を呼び寄せ、不吉の化身がついに姿を現した。あとは退治するだけだ。これまで幾度となくそうしてきたように。",
            ["DialogueId"] = 71004402,
            ["GUID"] = "B1C087B4",
            ["SpeakNpcId"] = 800006,
            },
        [71004403] = {
            ["Content"] = "（附近暂时安全了，趁现在解救魔灵吧。）",
            ["ContentJP"] = "付近はひとまず安全だ。今のうちに、ジェネモンと仲良くしよう。",
            ["DialogueId"] = 71004403,
            ["GUID"] = "B1C087DE",
            ["SpeakNpcId"] = 800006,
            },
        [71004501] = {
            ["Content"] = "（敌人站在要回收的物资前，击败他们吧。）",
            ["ContentJP"] = "敵が回収する物資の前に立ちはだかっている。退治しよう。",
            ["DialogueId"] = 71004501,
            ["GUID"] = "B1C097F2",
            ["SpeakNpcId"] = 800006,
            },
        [71004502] = {
            ["Content"] = "（不详的化身终于降临于此，击败它后再回收物资吧。）",
            ["ContentJP"] = "不吉の化身がついにこの地に現れた。さきに退治してから物資を回収しよう。",
            ["DialogueId"] = 71004502,
            ["GUID"] = "B1C0981C",
            ["SpeakNpcId"] = 800006,
            },
        [71004503] = {
            ["Content"] = "（附近暂时安全了，趁现在回收所有物资吧。）",
            ["ContentJP"] = "付近はひとまず安全だ。今のうちに、物資を回収しよう。",
            ["DialogueId"] = 71004503,
            ["GUID"] = "B1C09846",
            ["SpeakNpcId"] = 800006,
            },
        [71004601] = {
            ["Content"] = "（面前摆放着大量的物资箱，打开它们搜寻有用的物资吧。）",
            ["ContentJP"] = "目の前には大量の物資箱が並んでいる。開いて、中から使える物資を探し出そう。",
            ["DialogueId"] = 71004601,
            ["GUID"] = "B1C0A85A",
            ["SpeakNpcId"] = 800006,
            },
        [71004602] = {
            ["Content"] = "（你在箱子中找到了些有用的物资。）",
            ["ContentJP"] = "箱の中から、いくつかの使える物資を見つけた。",
            ["DialogueId"] = 71004602,
            ["GUID"] = "B1C0A884",
            ["SpeakNpcId"] = 800006,
            },
        [71004603] = {
            ["Content"] = "（你早就听闻部分秽兽会躲藏在阴暗的箱子内袭击他人，但不幸的是，这一次它们撞上你了。击败它们，拿到你应得的战利品吧。）",
            ["ContentJP"] = "一部の<Default note=\"text:エジュウ\">穢獣</>は、暗い箱に潜んで他者を襲うことがある――そんな噂は前から聞いていた。だが、それが自分の身に降りかかるとは思ってもいなかった。退治して戦利品を手に入れよう。",
            ["DialogueId"] = 71004603,
            ["GUID"] = "B1C0A8AE",
            ["SpeakNpcId"] = 800006,
            },
        [71004701] = {
            ["Content"] = "（远处闪闪发光的东西吸引了你的注意，靠近看看到底是什么吧。）",
            ["ContentJP"] = "遠くで何かが光っている……近くまで行って、確かめてみよう。",
            ["DialogueId"] = 71004701,
            ["GUID"] = "B1C0B8C2",
            ["SpeakNpcId"] = 800006,
            },
        [71004702] = {
            ["Content"] = "（在你捡起物资的一瞬间，警报响起，大量敌人朝你涌了过来，击退他们吧。）",
            ["ContentJP"] = "物資を拾い上げたその瞬間、警報が鳴り響き、大量の敵が押し寄せてきた。撃破しよう。",
            ["DialogueId"] = 71004702,
            ["GUID"] = "B1C0B8EC",
            ["SpeakNpcId"] = 800006,
            },
        [71004703] = {
            ["Content"] = "（警报解除，又一批敌人循着声响赶到了此处，击退他们吧。）",
            ["ContentJP"] = "警報は解除されたが、その音を聞きつけて新たな敵が現れた。撃破しよう。",
            ["DialogueId"] = 71004703,
            ["GUID"] = "B1C0B916",
            ["SpeakNpcId"] = 800006,
            },
        [71004704] = {
            ["Content"] = "（伴随着所有敌人倒下，四周总算重归寂静。）",
            ["ContentJP"] = "すべての敵が倒れ、辺りはようやく静寂を取り戻した。",
            ["DialogueId"] = 71004704,
            ["GUID"] = "B1C0B940",
            ["SpeakNpcId"] = 800006,
            },
        [71004801] = {
            ["Content"] = "（远处传来碎冰掉落的声音，过去看看发生了什么吧。）",
            ["ContentJP"] = "遠くから氷の砕ける音が聞こえた……何があったのか、見に行ってみよう。",
            ["DialogueId"] = 71004801,
            ["GUID"] = "B1C0C92A",
            ["SpeakNpcId"] = 800006,
            },
        [71004802] = {
            ["Content"] = "狩月人？你来得正好，最近公路下面结的冰锥有点多了，一起把它们清理掉吧。",
            ["ContentJP"] = "君は……月狩り人か？ちょうどいい。最近公路の下に氷柱がたくさんできてしまってね。一緒に片付けてくれないか？",
            ["DialogueId"] = 71004802,
            ["GUID"] = "B1C0C954",
            ["NextOptions"] = {
                [1] = 710048021,
                [2] = 710048022,
                },
            ["SpeakNpcId"] = 818039,
            },
        [71004803] = {
            ["Content"] = "感谢帮助，那边几块交给你了。",
            ["ContentJP"] = "おお、ありがとう。ではあちらの方は君に任せよう。",
            ["DialogueId"] = 71004803,
            ["GUID"] = "B1C0C97E",
            ["SpeakNpcId"] = 818039,
            },
        [71004805] = {
            ["Content"] = "这样安全隐患就小很多了，拿上吧，这些都是给你的报酬。",
            ["ContentJP"] = "おかげで危険がほぼ解消されたよ。ほら、報酬だ。",
            ["DialogueId"] = 71004805,
            ["GUID"] = "B1C0C9D2",
            ["SpeakNpcId"] = 818039,
            },
        [71004901] = {
            ["Content"] = "唉……我过不去啊，早知道提前买点草饵了。",
            ["ContentJP"] = "はぁ……困ったなぁ。こんなことなら、事前に草エサを買っとけばよかったよ。",
            ["DialogueId"] = 71004901,
            ["GUID"] = "B1C0D992",
            ["SpeakNpcId"] = 818040,
            },
        [71004902] = {
            ["Content"] = "狩月人啊，我需要点莲草做鱼饵，但莲草都在湖对面我过不去啊，你能帮我采点回来吗？",
            ["ContentJP"] = "月狩り人か。魚のエサを作るのに蓮草が必要なんだが、湖の向こう側にあって、採れないんだ。手を貸してくれないか？",
            ["DialogueId"] = 71004902,
            ["GUID"] = "B1C0D9BC",
            ["NextOptions"] = {
                [1] = 710049021,
                [2] = 710049022,
                },
            ["SpeakNpcId"] = 818040,
            ["bForbidSkipOptions"] = true,
            },
        [71004903] = {
            ["Content"] = "谢谢！那我就先把竿架上等你哈。",
            ["ContentJP"] = "おお、ありがとう！じゃあ先に竿でも立てて待ってるよ。",
            ["DialogueId"] = 71004903,
            ["GUID"] = "B1C0D9E6",
            ["SpeakNpcId"] = 818040,
            },
        [71004905] = {
            ["Content"] = "（游荡的秽兽挤满了四周，先击退它们，再去采集莲草吧。）",
            ["ContentJP"] = "周囲は彷徨う<Default note=\"text:エジュウ\">穢獣</>であふれている。まずは奴らを撃退してから、蓮草を採取しよう。",
            ["DialogueId"] = 71004905,
            ["GUID"] = "B1C0DA3A",
            ["SpeakNpcId"] = 800006,
            },
        [71004906] = {
            ["Content"] = "（附近的莲草被你一扫而空，把它们交给捕鱼人吧。）",
            ["ContentJP"] = "近くの蓮草をすべて採取した。これらを漁師に渡そう。",
            ["DialogueId"] = 71004906,
            ["GUID"] = "B1C0DA64",
            ["SpeakNpcId"] = 800006,
            },
        [71004907] = {
            ["Content"] = "好好好，这么多饵料，今天绝对能钓上鱼！",
            ["ContentJP"] = "よしよし、これだけエサがあれば、今日こそ絶対に魚が釣れるはずだ！",
            ["DialogueId"] = 71004907,
            ["GUID"] = "B1C0DA8E",
            ["SpeakNpcId"] = 818040,
            },
        [71005001] = {
            ["Content"] = "喂，那边的朋友，能帮我拍张照吗？",
            ["ContentJP"] = "おーい、そこの君！ちょっと写真を撮ってくれない？",
            ["DialogueId"] = 71005001,
            ["GUID"] = "B1C0E9FA",
            ["SpeakNpcId"] = 818041,
            },
        [71005002] = {
            ["Content"] = "这位朋友，你能帮我拍几张照片吗？难得来一趟冰湖城，不留点合影就太可惜了。",
            ["ContentJP"] = "ねぇ君、ちょっと写真撮ってくれない？せっかくアイスレイク城まで来たんだし、記念に何枚か残しておきたくてさ！",
            ["DialogueId"] = 71005002,
            ["GUID"] = "B1C0EA24",
            ["NextOptions"] = {
                [1] = 710050021,
                [2] = 710050022,
                },
            ["SpeakNpcId"] = 818041,
            ["bForbidSkipOptions"] = true,
            },
        [71005004] = {
            ["Content"] = "太好了，记得把我后面的这栋房子也拍进去哦，我很喜欢它的造型。",
            ["ContentJP"] = "やった！ありがとう！後ろのこの建物もちゃんと写してね、あのデザイン、すっごく気に入ってるんだ〜！",
            ["DialogueId"] = 71005004,
            ["GUID"] = "B1C0EA78",
            ["SpeakNpcId"] = 818041,
            },
        [71005005] = {
            ["Content"] = "你拍得也太好了，真棒呀，多谢多谢。",
            ["ContentJP"] = "うわっ、めっちゃ上手に撮れてる！ほんとありがとう〜！",
            ["DialogueId"] = 71005005,
            ["GUID"] = "B1C0EAA2",
            ["SpeakNpcId"] = 818041,
            },
        [71005101] = {
            ["Content"] = "鱼来，鱼来。",
            ["ContentJP"] = "魚、来い！来い！",
            ["DialogueId"] = 71005101,
            ["GUID"] = "B1C0EAA3",
            ["SpeakNpcId"] = 818045,
            },
        [71005102] = {
            ["Content"] = "你在干什么？",
            ["ContentJP"] = "何をしてるの？",
            ["DialogueId"] = 71005102,
            ["GUID"] = "B1C0FA62",
            ["NextDialogue"] = 71005103,
            ["SpeakNpcId"] = 100001,
            },
        [71005103] = {
            ["Content"] = "钓鱼呢，等会再说。",
            ["ContentJP"] = "しっ！今魚釣りで忙しいんだ。話なら後にしてくれ。",
            ["DialogueId"] = 71005103,
            ["GUID"] = "B1C0FA8C",
            ["SpeakNpcId"] = 818045,
            },
        [71005104] = {
            ["Content"] = "（你在一旁等了许久，男人一条鱼都没钓上来。）",
            ["ContentJP"] = "しばらく様子を見ていたが、男性は一匹も釣れなかった。",
            ["DialogueId"] = 71005104,
            ["GUID"] = "B1C0FA8D",
            ["NextDialogue"] = 71005105,
            ["SpeakNpcId"] = 800006,
            },
        [71005105] = {
            ["Content"] = "这样能钓上什么鱼啊？",
            ["ContentJP"] = "とても釣れるとは思えないけど……",
            ["DialogueId"] = 71005105,
            ["GUID"] = "B1C0FAB6",
            ["NextDialogue"] = 71005106,
            ["SpeakNpcId"] = 100001,
            },
        [71005106] = {
            ["Content"] = "别说话，看着就好。",
            ["ContentJP"] = "黙って見てろって！",
            ["DialogueId"] = 71005106,
            ["GUID"] = "B1C0FAE0",
            ["SpeakNpcId"] = 818045,
            },
        [71005107] = {
            ["Content"] = "（你在一旁等了许久，男人还是一条鱼都没钓上来。）",
            ["ContentJP"] = "またしばらく様子を見ていたが、やはり一匹も釣れなかった。",
            ["DialogueId"] = 71005107,
            ["GUID"] = "B1C0FAE1",
            ["NextDialogue"] = 71005108,
            ["SpeakNpcId"] = 800006,
            },
        [71005108] = {
            ["Content"] = "鱼来，鱼来。",
            ["ContentJP"] = "来い！来い！",
            ["DialogueId"] = 71005108,
            ["GUID"] = "B1C0FAE2",
            ["NextDialogue"] = 71005109,
            ["SpeakNpcId"] = 818045,
            },
        [71005109] = {
            ["Content"] = "我觉得钓鱼至少得有个鱼竿吧，而不是嘴上说说就能钓到。",
            ["ContentJP"] = "少なくとも、釣り竿が必要なんじゃないかな？口で呼んだって釣れないと思う。",
            ["DialogueId"] = 71005109,
            ["GUID"] = "B1C0FB0A",
            ["NextDialogue"] = 71005110,
            ["SpeakNpcId"] = 100001,
            },
        [71005110] = {
            ["Content"] = "这是我与无数人交流后掌握的最新钓鱼技巧，钓到的鱼那是又大又好，不信你去钓一条我们比比看。",
            ["ContentJP"] = "これは俺が大勢の人と交流してつかんだ最新の釣りテクニックだ。デカくて質のいい魚が釣れるらしい。信じられないならお前も一匹釣ってみろ。",
            ["DialogueId"] = 71005110,
            ["GUID"] = "B1C0FB34",
            ["SpeakNpcId"] = 818045,
            },
        [71005111] = {
            ["Content"] = "我钓到了，你的鱼呢？",
            ["ContentJP"] = "釣れたよ。あなたは？",
            ["DialogueId"] = 71005111,
            ["GUID"] = "B1C0FB5E",
            ["NextDialogue"] = 71005112,
            ["SpeakNpcId"] = 100001,
            },
        [71005112] = {
            ["Content"] = "嗯，你这确实是条大鱼，但跟我要钓的相比还是差了点。",
            ["ContentJP"] = "うん、確かに大きいな。だが、俺のとは比べ物にもならん！",
            ["DialogueId"] = 71005112,
            ["GUID"] = "B1C0FB88",
            ["NextDialogue"] = 71005113,
            ["SpeakNpcId"] = 818045,
            },
        [71005113] = {
            ["Content"] = "我闻到那边有莲草的味道，害我的鱼都不咬钩了，你去把它们拔了再回来看看吧。",
            ["ContentJP"] = "あっちから蓮草の匂いがする。そのせいで魚が俺の針に食いつかないんだ。ちょっと引っこ抜いて来てくれないか。",
            ["DialogueId"] = 71005113,
            ["GUID"] = "B1C0FC06",
            ["SpeakNpcId"] = 818045,
            },
        [71005114] = {
            ["Content"] = "男人说的问题解决掉了，回去看看吧。",
            ["ContentJP"] = "男性の言う通り、すべて引っこ抜いた。急いで戻ろう。",
            ["DialogueId"] = 71005114,
            ["GUID"] = "B1C0FC30",
            ["SpeakNpcId"] = 100001,
            },
        [71005115] = {
            ["Content"] = "弄好了，你说的鱼呢。",
            ["ContentJP"] = "全部抜いたよ。それで、魚は？",
            ["DialogueId"] = 71005115,
            ["GUID"] = "B1C0FC5A",
