            ["DialogueId"] = 71005116,
            ["GUID"] = "B1C0FC84",
            ["NextDialogue"] = 71005117,
            ["SpeakNpcId"] = 818045,
            },
        [71005117] = {
            ["Content"] = "（男人说完指了指你。）",
            ["ContentJP"] = "男性はそう言いながら、あなたを指さした。",
            ["DialogueId"] = 71005117,
            ["GUID"] = "B1C0FCAE",
            ["NextDialogue"] = 71005118,
            ["SpeakNpcId"] = 800006,
            },
        [71005118] = {
            ["Content"] = "钓鱼钓的也可以不是鱼。撒下几句话，做一些奇怪的事，自会有无数鱼争相咬钩。",
            ["ContentJP"] = "釣りってのは、魚だけに限る必要はない。ちょっとした言葉を撒き餌に、奇妙な行為をしてやれば、色んな奴が勝手に食いついてくるもんだ。",
            ["DialogueId"] = 71005118,
            ["GUID"] = "B1C0FCD8",
            ["NextDialogue"] = 71005119,
            ["SpeakNpcId"] = 818045,
            },
        [71005119] = {
            ["Content"] = "这就是我与无数人交流后学到的感悟，希望以后你不会再被别人撒下的“鱼饵”戏弄。",
