            },
        [71005140] = {
            ["Content"] = "折腾了你半天真是抱歉。这些是我的赔礼，对不起了。",
            ["ContentJP"] = "振り回して悪かったな。これはほんの詫びだ。受け取ってくれ。",
            ["DialogueId"] = 71005140,
            ["GUID"] = "B1C0FF4E",
            ["SpeakNpcId"] = 818045,
            },
        [71005141] = {
            ["Content"] = "看来只有一种办法能让你说真话了。",
            ["ContentJP"] = "どうやら、真面目に話しをさせるには、こうするしかないようだね。",
            ["DialogueId"] = 71005141,
            ["GUID"] = "B1C0FF78",
            ["SpeakNpcId"] = 100001,
            },
        [71005142] = {
            ["Content"] = "我错了我错了，我就是看到经常有人随便讲几句话，就把一大波人耍得团团转，所以就想验证一下试试……",
            ["ContentJP"] = "わ、悪かったって！ただ、言葉のひとつや二つで、他人を振り回す者をよくみてきたから……俺も試してみようと思っただけで……",
            ["DialogueId"] = 71005142,
            ["GUID"] = "B1C0FFA2",
            ["NextDialogue"] = 71005143,
            ["SpeakNpcId"] = 818045,
            },
        [71005143] = {
            ["Content"] = "折腾了你半天真是抱歉。这些是我的赔礼，对不起了。",
            ["ContentJP"] = "振り回して悪かったな。これはほんの詫びだ。受け取ってくれ。",
            ["DialogueId"] = 71005143,
            ["GUID"] = "B1C0FFCC",
            ["SpeakNpcId"] = 818045,
            },
        [71005201] = {
            ["Content"] = "幸福硬币，有魔法的幸福硬币，大哥哥大姐姐们，来买一枚吧。",
            ["ContentJP"] = "ラッキーコインはいかが？魔法のラッキーコインだよ！お兄さん、お姉さん、おひとついかがですか！",
            ["DialogueId"] = 71005201,
            ["GUID"] = "B1C10ACA",
            ["SpeakNpcId"] = 818046,
            },
        [71005202] = {
            ["Content"] = "（待你靠近后，女孩立马从怀中掏出几枚铜币递到了你的面前。）",
            ["ContentJP"] = "近づいてみると、少女はすぐさま懐から数枚の銅貨を取り出し、あなたの目の前に差し出した。",
            ["DialogueId"] = 71005202,
            ["GUID"] = "B1C10AF4",
            ["NextDialogue"] = 71005203,
            ["SpeakNpcId"] = 800006,
            },
        [71005203] = {
            ["Content"] = "{性别：大哥哥|大姐姐}，你好你好，要买幸福硬币吗？这是妈妈留给我的，她说一枚烦恼消散，两枚幸福常伴，三枚……三枚想做什么都能做到！",
            ["ContentJP"] = "{性别:お兄さん|お姉さん}、こんにちは！ラッキーコインはいかが？これはね、ママが遺してくれたものなの。たった1枚で悩みが消えて、2枚あれば幸せになれて、3枚揃えたら……なんでも願いが叶っちゃうんだよ！",
            ["DialogueId"] = 71005203,
            ["GUID"] = "B1C10B1E",
            ["NextDialogue"] = 71005204,
            ["SpeakNpcId"] = 818046,
            },
        [71005204] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 71005204,
            ["GUID"] = "B1C10B48",
            ["NextDialogue"] = 71005205,
            ["SpeakNpcId"] = 100001,
            },
        [71005205] = {
            ["Content"] = "它们都被妈妈施过魔法了，真的很有用，不骗你！不信的话你去问问其他人嘛，问完再来看看要不要买呗。去吧去吧，我就在这等你。",
            ["ContentJP"] = "これらにはママの魔法がかかってるの！嘘じゃないよ！なんなら、他の人に聞いたっていいわ！私はずっとここにいるから。買いたくなったら、いつでも来てよ！",
            ["DialogueId"] = 71005205,
            ["GUID"] = "B1C10B49",
            ["SpeakNpcId"] = 818046,
            },
        [71005206] = {
            ["Content"] = "（你注意到老人的脚边摆放着几枚幸福硬币，于是你与他攀谈了起来。）",
            ["ContentJP"] = "老人の足元に、数枚のラッキーコインが置かれているのに気づいたあなたは、声をかけることにした。",
            ["DialogueId"] = 71005206,
            ["GUID"] = "B1C10B72",
            ["NextDialogue"] = 71005207,
            ["SpeakNpcId"] = 800006,
            },
        [71005207] = {
            ["Content"] = "幸福硬币？哈哈，真有这好东西我还会在这破地方饿肚子？",
            ["ContentJP"] = "ラッキーコイン？ははは、そんなもんあったら、今頃こんなとこで腹を空かせているはずあるまい。",
            ["DialogueId"] = 71005207,
            ["GUID"] = "B1C10B73",
            ["NextDialogue"] = 71005208,
            ["SpeakNpcId"] = 818047,
            },
        [71005208] = {
            ["Content"] = "这话不要告诉那小姑娘啊。她那么小就没有亲人了，怪可怜的……很多东西就算是假的，也能给人点盼头，你说对吧。",
            ["ContentJP"] = "あの娘には言わないでやってくれ。あの歳でひとりぼっちなんて、可哀そうじゃろう……たとえ嘘でも、希望ってのは人を支えるもんだ。お前も、そう思うだろ？",
            ["DialogueId"] = 71005208,
            ["GUID"] = "B1C10B74",
            ["SpeakNpcId"] = 818047,
            },
        [71005209] = {
            ["Content"] = "（你注意到男孩手中正把玩着几枚幸福硬币，于是你与他攀谈了起来。）",
            ["ContentJP"] = "数枚のラッキーコインを弄んでる少年に気づき、あなたは声をかけることにした。",
            ["DialogueId"] = 71005209,
            ["GUID"] = "B1C10B9C",
            ["NextDialogue"] = 71005210,
            ["SpeakNpcId"] = 800006,
            },
        [71005210] = {
            ["Content"] = "你看我左手的幸福硬币和右手的铜币有什么不一样吗？",
            ["ContentJP"] = "僕の左手に持ってるラッキーコインと、右手に持ってるただの銅貨……違いがわかるか？",
            ["DialogueId"] = 71005210,
            ["GUID"] = "B1C10B9D",
            ["NextDialogue"] = 71005211,
            ["SpeakNpcId"] = 818048,
            },
        [71005211] = {
            ["Content"] = "（男孩举起双手，你仔细观察后，确认它们就是完全一样的东西。）",
            ["ContentJP"] = "少年は両手を掲げる。よく見ると、確かに差はまったくない。",
            ["DialogueId"] = 71005211,
            ["GUID"] = "B1C10B9E",
            ["NextDialogue"] = 71005212,
            ["SpeakNpcId"] = 800006,
            },
        [71005212] = {
            ["Content"] = "是呀，幸福硬币就是我们手里的铜币。它不是魔法创造出来的宝贝，而是诞生自大家的善意。",
            ["ContentJP"] = "そう、ラッキーコインっていうのは、僕たちの手にある銅貨と同じだ。魔法のかかった宝物なんかじゃない。みんなの優しさから生まれた、本当の「幸せ」なんだ。",
            ["DialogueId"] = 71005212,
            ["GUID"] = "B1C10B9F",
            ["NextDialogue"] = 71005213,
            ["SpeakNpcId"] = 818048,
            },
        }
  end },
  { MinKey = 71005213, MaxKey = 71007204, Loader = function()
      return {
        [71005213] = {
            ["Content"] = "一枚幸福硬币就能买到她的笑容，这么轻松的买卖可不多见呀。",
            ["ContentJP"] = "たった一枚のラッキーコインで、あの子の笑顔が見られるんだ。こんな気前のいい取り引き、そうそうあるもんじゃない。",
            ["DialogueId"] = 71005213,
            ["GUID"] = "B1C10BA0",
            ["SpeakNpcId"] = 818048,
            },
        [71005214] = {
            ["Content"] = "怎么样，大家都说很有用吧！",
            ["ContentJP"] = "どう？これでわかったでしょ？",
            ["DialogueId"] = 71005214,
            ["GUID"] = "B1C10BC6",
            ["SpeakNpcId"] = 818046,
            },
        [71005215] = {
            ["Content"] = "嘿嘿，真是拿你没办法。那就全都卖给你吧，希望你能找到属于自己的幸福哦。",
            ["ContentJP"] = "えへへ、もう、しょうがないなぁ。じゃあ全部うってあげる！あなたにも、ちゃんと自分の「幸せ」が見つかりますように。",
            ["DialogueId"] = 71005215,
            ["GUID"] = "B1C10BF0",
            ["SpeakNpcId"] = 818046,
            },
        [71005216] = {
            ["Content"] = "靠自己吗……好帅气的发言啊！我以后也可以像你这样吗？",
            ["ContentJP"] = "自分の手で……かっこいい！私もいつかあなたみたいになれるかな？",
            ["DialogueId"] = 71005216,
            ["GUID"] = "B1C10C1A",
            ["NextDialogue"] = 71005217,
            ["SpeakNpcId"] = 818046,
            },
        [71005217] = {
            ["Content"] = "当然。",
            ["ContentJP"] = "もちろん。",
            ["DialogueId"] = 71005217,
            ["GUID"] = "B1C10C1B",
            ["NextDialogue"] = 71005218,
            ["SpeakNpcId"] = 100001,
            },
        [71005218] = {
            ["Content"] = "唔……这样子啊……我会好好想想的，谢谢你！",
            ["ContentJP"] = "う……そっか……ちゃんと考えてみるよ。ありがとう！",
            ["DialogueId"] = 71005218,
            ["GUID"] = "B1C10C1C",
            ["SpeakNpcId"] = 818046,
            },
        [71005301] = {
            ["Content"] = "抢劫啦，抢劫啦，有没有人帮帮我啊！",
            ["ContentJP"] = "ど、泥棒！だれか、誰か助けて！！",
            ["DialogueId"] = 71005301,
            ["GUID"] = "B1C11B32",
            ["SpeakNpcId"] = 818042,
            },
        [71005302] = {
            ["Content"] = "抢你的人跑哪去了？",
            ["ContentJP"] = "その人はどっちに似てげったの？",
            ["DialogueId"] = 71005302,
            ["GUID"] = "B1C11B5C",
            ["NextDialogue"] = 71005303,
            ["SpeakNpcId"] = 100001,
            },
        [71005303] = {
            ["Content"] = "他们，他们往那边跑了，呜呜呜，外城真的好危险啊……",
            ["ContentJP"] = "あ、あっちよ！で、でも……ううっ、外城区はとても危険な場所だし……",
            ["DialogueId"] = 71005303,
            ["GUID"] = "B1C11B86",
            ["SpeakNpcId"] = 818042,
            },
        [71005304] = {
            ["Content"] = "内城的家伙一个比一个有钱啊，几个月不愁吃喝喽。",
            ["ContentJP"] = "内城の連中はホント金持ちばっかだな～。これでしばらくは、メシの心配しなくて済みそうだぜ。",
            ["DialogueId"] = 71005304,
            ["GUID"] = "B1C11C04",
            ["NextDialogue"] = 71005305,
            ["SpeakNpcId"] = 818043,
            },
        [71005305] = {
            ["Content"] = "站住，把抢来的东西还回来。",
            ["ContentJP"] = "止まれ！盗んだモンを返{性别:せ|して}！",
            ["DialogueId"] = 71005305,
            ["GUID"] = "B1C11C2E",
            ["NextDialogue"] = 71005306,
            ["SpeakNpcId"] = 100001,
            },
        [71005306] = {
            ["Content"] = "哼，这么快就有人帮忙出头啊，那就别怪我们下狠手了！",
            ["ContentJP"] = "ふん、もう助っ人を呼びやがったか。痛い目見せてやらぁ！",
            ["DialogueId"] = 71005306,
            ["GUID"] = "B1C11C58",
            ["SpeakNpcId"] = 818043,
            },
        [71005307] = {
            ["Content"] = "啧，今天真是晦气，撤！",
            ["ContentJP"] = "チッ、今日はツイてねぇなぁ。引くぞ！",
            ["DialogueId"] = 71005307,
            ["GUID"] = "B1C11CAC",
            ["SpeakNpcId"] = 818043,
            },
        [71005308] = {
            ["Content"] = "（抢劫者们说完便朝各个方向逃去，你捡起地上的包裹，思索着下一步行动。）",
            ["ContentJP"] = "強盗たちはそう言い残すと、散り散りに逃げていった。あなたは地面に落ちたバッグを拾い、どうすべきか考え始めた。",
            ["DialogueId"] = 71005308,
            ["GUID"] = "B1C11CD6",
            ["SpeakNpcId"] = 800006,
            },
        [71005309] = {
            ["Content"] = "（这是帮女孩认识外城险恶的“学费”，你拿走它们天经地义。不找她再多要点钱已经算是相当仁慈了。）",
            ["ContentJP"] = "これは、あの子が外城区の厳しさを知るための「学費」なのだから、貰ってもいいはずだ。もっとふんだくろうとしなかっただけ、感謝してほしいくらいだ。",
            ["DialogueId"] = 71005309,
            ["GUID"] = "B1C11D2A",
            ["SpeakNpcId"] = 800006,
            },
        [71005310] = {
            ["Content"] = "我拿回来了，是这个包裹没错吧。",
            ["ContentJP"] = "ただいま。盗られたバッグってこれ？",
            ["DialogueId"] = 71005310,
            ["GUID"] = "B1C11D54",
            ["NextDialogue"] = 71005311,
            ["SpeakNpcId"] = 100001,
            },
        [71005311] = {
            ["Content"] = "是的是的，谢谢你！",
            ["ContentJP"] = "ええ、ありがとう！！",
            ["DialogueId"] = 71005311,
            ["GUID"] = "B1C11D7E",
            ["NextDialogue"] = 71005312,
            ["SpeakNpcId"] = 818042,
            },
        [71005312] = {
            ["Content"] = "（女孩擦了擦眼泪，从包裹中取出一大笔钱放到了你的手上。）",
            ["ContentJP"] = "少女は涙をぬぐい、バッグから大金を取り出して、あなたに手渡した。",
            ["DialogueId"] = 71005312,
            ["GUID"] = "B1C11DA8",
            ["NextDialogue"] = 71005313,
            ["SpeakNpcId"] = 800006,
            },
        [71005313] = {
            ["Content"] = "这些是谢礼，外城还有你这样善良的狩月人真是太好了，呜呜呜……",
            ["ContentJP"] = "これはほんのお気持ちよ。外城区にあなたのような心優しい月狩り人がいるなんて……ありがとう……ううっ……",
            ["DialogueId"] = 71005313,
            ["GUID"] = "B1C11DA9",
            ["SpeakNpcId"] = 818042,
            },
        [71005401] = {
            ["Content"] = "丰厚奖励就在眼前，走过路过别错过。",
            ["ContentJP"] = "よってらっしゃいみてらっしゃい！お宝はすぐ目の前ですぜ",
            ["DialogueId"] = 71005401,
            ["GUID"] = "B1C12B9A",
            ["SpeakNpcId"] = 818044,
            },
        [71005402] = {
            ["Content"] = "呦，这位狩月人要来试试吗，只要你能打开这个箱子，里面的奖励就都是你的了！",
            ["ContentJP"] = "おっと、そこの月狩り人さん、どうです？この箱を開ければ、中の賞品はすべて差し上げますぜ！",
            ["DialogueId"] = 71005402,
            ["GUID"] = "B1C12BC4",
            ["SpeakNpcId"] = 818044,
            },
        [71005403] = {
            ["Content"] = "（锁孔打开的声音传来，当你以为自己成功时，缓缓开启的箱子突然发出“咔哒”一声脆响，重重地关上。无论如何尝试，箱子都再也无法打开了。）",
            ["ContentJP"] = "鍵穴が開く音が聞こえた。だがゆっくりと開きかけたその箱は、突然「カチッ」と鋭い音を立てて再び重く閉ざされてしまった。どんなに試しても、二度とその箱が開くことはなかった——",
            ["DialogueId"] = 71005403,
            ["GUID"] = "B1C12C18",
            ["SpeakNpcId"] = 800006,
            },
        [71005404] = {
            ["Content"] = "啊，你把我的宝箱弄坏了啊，赔钱赔钱！",
            ["ContentJP"] = "あ！よくもうちの宝箱を壊してくれたな！！弁償しろ！！",
            ["DialogueId"] = 71005404,
            ["GUID"] = "B1C12C42",
            ["NextOptions"] = {
                [1] = 710054041,
                [2] = 710054042,
                },
            ["SpeakNpcId"] = 818044,
            },
        [71005405] = {
            ["Content"] = "嘘……别喊别喊，我之后还要在这一带骗……不是，跟其他人做生意呢。这些东西给你，行行好别喊了。",
            ["ContentJP"] = "なっ、しー！そんなに騒ぐな！ここ一帯で騙せ……じゃなかった。商売できなくなるだろ！ほら、これ全部やるから、黙っててくれ。",
            ["DialogueId"] = 71005405,
            ["GUID"] = "B1C12CC0",
            ["NextDialogue"] = 71005406,
            ["SpeakNpcId"] = 818044,
            },
        [71005406] = {
            ["Content"] = "（男人自知理亏，塞给你一袋钱财便抱着箱子灰溜溜地走开了。）",
            ["ContentJP"] = "男はバツの悪そうな顔で重そうな袋を手渡すと、箱を抱えてそそくさと立ち去った。",
            ["DialogueId"] = 71005406,
            ["GUID"] = "B1C12CEA",
            ["SpeakNpcId"] = 800006,
            },
        [71005407] = {
            ["Content"] = "你这家伙，非逼我动手是吧！",
            ["ContentJP"] = "こいつ、調子に乗りやがって！痛い目みたいようだな！",
            ["DialogueId"] = 71005407,
            ["GUID"] = "B1C12D14",
            ["NextDialogue"] = 71005408,
            ["SpeakNpcId"] = 818044,
            },
        [71005408] = {
            ["Content"] = "没想到你这骗子还有跟人动手的勇气啊，那就来吧。",
            ["ContentJP"] = "口だけの詐欺師かと思ってたけど……血の気も多いようだね。相手してあげる。",
            ["DialogueId"] = 71005408,
            ["GUID"] = "B1C12D3E",
            ["SpeakNpcId"] = 100001,
            },
        [71005409] = {
            ["Content"] = "（男人自知理亏，抱着箱子灰溜溜地走开了。）",
            ["ContentJP"] = "男はバツの悪そうな顔で、箱を抱えてそそくさと立ち去った。",
            ["DialogueId"] = 71005409,
            ["GUID"] = "B1C12D68",
            ["SpeakNpcId"] = 800006,
            },
        [71005501] = {
            ["Content"] = "那边的狩月人，帮帮我吧。",
            ["ContentJP"] = "そこの月狩り人、ちょっといいか？",
            ["DialogueId"] = 71005501,
            ["GUID"] = "B1C13C02",
            ["SpeakNpcId"] = 818049,
            },
        [71005502] = {
            ["Content"] = "我，我好像听到前面有可怕的声音，你能帮我去看看吗？",
            ["ContentJP"] = "ま、前の方から不気味な声が聞こえるんだ……ちょっくら見てきてくれねぇか？",
            ["DialogueId"] = 71005502,
            ["GUID"] = "B1C13C2C",
            ["SpeakNpcId"] = 818049,
            },
        [71005503] = {
            ["Content"] = "（你并未看到什么值得恐惧的东西，也许一切只是男子的错觉而已。）",
            ["ContentJP"] = "特に恐ろしい物とやらは見当たらない。男の錯覚だったのだろう。",
            ["DialogueId"] = 71005503,
            ["GUID"] = "B1C13CAA",
            ["SpeakNpcId"] = 800006,
            },
        [71005504] = {
            ["Content"] = "（几只秽兽徘徊在水道上游，不时发出嘶哑的吼叫。这大概就是吓到男子的声音。）",
            ["ContentJP"] = "数匹の<Default note=\"text:エジュウ\">穢獣</>が水路の上流をうろつき、ときおりかすれた咆哮を響かせている。男を怯えさせたのは、おそらくこの声だろう。",
            ["DialogueId"] = 71005504,
            ["GUID"] = "B1C13CFE",
            ["SpeakNpcId"] = 800006,
            },
        [71005505] = {
            ["Content"] = "（所有秽兽被你击退，四周恢复了寂静。回去告诉男子吧。）",
            ["ContentJP"] = "すべての<Default note=\"text:エジュウ\">穢獣</>を退治し、あたりには静けさが戻った――彼のもとに戻ろう。",
            ["DialogueId"] = 71005505,
            ["GUID"] = "B1C13D28",
            ["SpeakNpcId"] = 800006,
            },
        [71005506] = {
            ["Content"] = "（几块金属卡在了水道旁，不时发出刺耳的声响。这大概就是吓到男子的声音。）",
            ["ContentJP"] = "金属の破片が数枚、水路の縁に引っかかり、ときおり耳障りな音を立てている。男を怯えさせたのは、おそらくこの音だろう。",
            ["DialogueId"] = 71005506,
            ["Duration"] = 3,
            ["GUID"] = "B1C13D52",
            ["NextDialogue"] = 71005507,
            ["SpeakNpcId"] = 800006,
            },
        [71005507] = {
            ["Content"] = "（你将金属捡起，因为金属永远不缺买家。等完成男子的委托就找个地方把它们卖掉吧。）",
            ["ContentJP"] = "金属の破片を拾い上げた。こういうものは買い手に困らない――男の依頼を片づけてから、売れる場所を探すとしよう。",
            ["DialogueId"] = 71005507,
            ["GUID"] = "B1C13D53",
            ["SpeakNpcId"] = 800006,
            },
        [71005508] = {
            ["Content"] = "我听不到可怕的声音了，谢谢你。",
            ["ContentJP"] = "あの恐ろしい声がなくなったよ……ありがとう。",
            ["DialogueId"] = 71005508,
            ["GUID"] = "B1C13D7C",
            ["SpeakNpcId"] = 818049,
            },
        [71005601] = {
            ["Content"] = "哼啊啊啊……好重……鱼线，拉不起来了……",
            ["ContentJP"] = "ぐぬぬぅ……おもっ……糸が、引けん……",
            ["DialogueId"] = 71005601,
            ["GUID"] = "B1C14C6A",
            ["SpeakNpcId"] = 818050,
            },
        [71005602] = {
            ["Content"] = "发生什么了？",
            ["ContentJP"] = "どうした{性别:んだ|の}？",
            ["DialogueId"] = 71005602,
            ["GUID"] = "B1C14C94",
            ["NextDialogue"] = 71005603,
            ["SpeakNpcId"] = 100001,
            },
        [71005603] = {
            ["Content"] = "狩月人是你啊，我的鱼线被下面几块垃圾缠住了，你能帮帮我吗？",
            ["ContentJP"] = "月狩り人か。どうやら釣り糸にゴミが絡まってしまったようでね。手伝ってくれないか？",
            ["DialogueId"] = 71005603,
            ["GUID"] = "B1C14CBE",
            ["NextOptions"] = {
                [1] = 710056031,
                [2] = 710056032,
                },
            ["SpeakNpcId"] = 818050,
            },
        [71005604] = {
            ["Content"] = "好，那我在这边拉，你去那边打碎垃圾。",
            ["ContentJP"] = "よし、では俺はこっちで引いてるから、あそこのゴミを砕いてくれ。",
            ["DialogueId"] = 71005604,
            ["GUID"] = "B1C14CE8",
            ["SpeakNpcId"] = 818050,
            },
        [71005605] = {
            ["Content"] = "呼……拉起来了，谢谢你哈。",
            ["ContentJP"] = "ふぅ……助かった。ありがとな。",
            ["DialogueId"] = 71005605,
            ["GUID"] = "B1C14D12",
            ["SpeakNpcId"] = 818050,
            },
        [71005701] = {
            ["Content"] = "救命啊，有没有人来救救我。",
            ["ContentJP"] = "だ、誰か！助けてくれ！！",
            ["DialogueId"] = 71005701,
            ["GUID"] = "B1C15CD2",
            ["SpeakNpcId"] = 818051,
            },
        [71005702] = {
            ["Content"] = "多谢……那个，能不能再帮我一个小忙。我逃跑的时候把鱼竿落在前面了，但那里还有几只秽兽……",
            ["ContentJP"] = "た、助かったよ……その、もう一つだけ……お願い、できるかな？実は逃げたときに、釣り竿を置いてきてしまって……あっちまだ<Default note=\"text:エジュウ\">穢獣</>がうろついてるし……",
            ["DialogueId"] = 71005702,
            ["GUID"] = "B1C15CFC",
            ["NextOptions"] = {
                [1] = 710057021,
                [2] = 710057022,
                },
            ["SpeakNpcId"] = 818051,
            },
        [71005703] = {
            ["Content"] = "谢谢谢谢，我就在这等你哈。",
            ["ContentJP"] = "ああ、ありがとう！ここで待ってるよ。",
            ["DialogueId"] = 71005703,
            ["GUID"] = "B1C15D26",
            ["SpeakNpcId"] = 818051,
            },
        [71005704] = {
            ["Content"] = "就是这根鱼竿，谢谢你！",
            ["ContentJP"] = "これだよこれ！本当にありがとう！",
            ["DialogueId"] = 71005704,
            ["GUID"] = "B1C15D50",
            ["SpeakNpcId"] = 818051,
            },
        [71005801] = {
            ["Content"] = "喂，那边的狩月人，我这里有个大便宜要不要来看看。",
            ["ContentJP"] = "ねえそこの月狩り人……ちょっといい話あるんだけどさ、知りたいかい？",
            ["DialogueId"] = 71005801,
            ["GUID"] = "B1C16D3A",
            ["SpeakNpcId"] = 818052,
            },
        [71005802] = {
            ["Content"] = "我在前面发现了一堆银辉石，但我实在拿不下了，就全让给你吧。有兴趣的话我就带你过去。",
            ["ContentJP"] = "前の方で銀輝石をいっぱい見つけたんだけどな……この通り、もう荷物がパンパンなんだ。よかったら、全部あげるよ。欲しいなら案内しよう。",
            ["DialogueId"] = 71005802,
            ["GUID"] = "B1C16D64",
            ["NextOptions"] = {
                [1] = 710058031,
                [2] = 710058032,
                },
            ["SpeakNpcId"] = 818052,
            },
        [71005804] = {
            ["Content"] = "好，跟我来。",
            ["ContentJP"] = "よし、じゃあついてこい。",
            ["DialogueId"] = 71005804,
            ["GUID"] = "B1C16DB8",
            ["SpeakNpcId"] = 818052,
            },
        [71005805] = {
            ["Content"] = "第一批在这。",
            ["ContentJP"] = "ここだここ。",
            ["DialogueId"] = 71005805,
            ["GUID"] = "B1C16DE2",
            ["SpeakNpcId"] = 818052,
            },
        [71005806] = {
            ["Content"] = "前面还有，你还要吗？",
            ["ContentJP"] = "前にまだあるぜ。欲しいか？",
            ["DialogueId"] = 71005806,
            ["GUID"] = "B1C16E0C",
            ["NextOptions"] = {
                [1] = 710058061,
                [2] = 710058062,
                },
            ["SpeakNpcId"] = 818052,
            },
        [71005807] = {
            ["Content"] = "好，跟我来。",
            ["ContentJP"] = "よし、じゃあついてこい。",
            ["DialogueId"] = 71005807,
            ["GUID"] = "B1C16E36",
            ["SpeakNpcId"] = 818052,
            },
        [71005808] = {
            ["Content"] = "第二批在这。",
            ["ContentJP"] = "ここだ。",
            ["DialogueId"] = 71005808,
            ["GUID"] = "B1C16E60",
            ["SpeakNpcId"] = 818052,
            },
        [71005809] = {
            ["Content"] = "前面还有，你还要吗？",
            ["ContentJP"] = "前にまだあるぜ。欲しいか？",
            ["DialogueId"] = 71005809,
            ["GUID"] = "B1C16E8A",
            ["NextOptions"] = {
                [1] = 710058091,
                [2] = 710058092,
                },
            ["SpeakNpcId"] = 818052,
            },
        [71005810] = {
            ["Content"] = "好，你往前走就看到了。",
            ["ContentJP"] = "このまままっすぐ進めば見えてくるぜ。",
            ["DialogueId"] = 71005810,
            ["GUID"] = "B1C16EB4",
            ["SpeakNpcId"] = 818052,
            },
        [71005811] = {
            ["Content"] = "就是现在，兄弟们动手！",
            ["ContentJP"] = "今だ、お前らやれ！",
            ["DialogueId"] = 71005811,
            ["GUID"] = "B1C16EDE",
            ["NextDialogue"] = 71005812,
            ["SpeakNpcId"] = 818052,
            },
        [71005812] = {
            ["Content"] = "（显然银辉石都是这几名矿工装扮的强盗布置的陷阱，击退他们吧。）",
            ["ContentJP"] = "どうやら銀輝石は、鉱山労働者に扮した強盗たちの罠だったようだ。彼らを撃退しよう。",
            ["DialogueId"] = 71005812,
            ["Duration"] = 3,
            ["GUID"] = "B1C16F08",
            ["SpeakNpcId"] = 800006,
            },
        [71005813] = {
            ["Content"] = "（你击退了所有人，现在可以清点一下今天的收获了。）",
            ["ContentJP"] = "強盗を撃退した後、あなたは今日の収穫を数え始めた。",
            ["DialogueId"] = 71005813,
            ["GUID"] = "B1C16F32",
            ["SpeakNpcId"] = 800006,
            },
        [71005814] = {
            ["Content"] = "可恶，就差一点……不，我的意思是真可惜。那我就不打扰你了，再见。",
            ["ContentJP"] = "くそ、あと一歩で……いや、ええと、残念だなぁ。じゃあ俺はこの辺で！！",
            ["DialogueId"] = 71005814,
            ["GUID"] = "B1C16F5C",
            ["SpeakNpcId"] = 818052,
            },
        [71005901] = {
            ["Content"] = "爸爸跑得好快，所有人都输给你了！",
            ["ContentJP"] = "パパ、速い！誰もパパには勝てないね！",
            ["DialogueId"] = 71005901,
            ["GUID"] = "B1C17DA2",
            ["SpeakNpcId"] = 818053,
            },
        [71005902] = {
            ["Content"] = "又有人过来了。我告诉你哦，我爸爸跑得可快了，你要不要跟他比比看！",
            ["ContentJP"] = "あ、また挑戦者が来たぞ！パパはとっても足が速いんだ！信じないのなら、勝負してみる？",
            ["DialogueId"] = 71005902,
            ["GUID"] = "B1C17DCC",
            ["NextOptions"] = {
                [1] = 710059021,
                [2] = 710059022,
                },
            ["SpeakNpcId"] = 818053,
            ["bForbidSkipOptions"] = true,
            },
        [71005903] = {
            ["Content"] = "咳，既然要比那就来吧。不过比之前我有几句话要跟你交代一下，请跟我来。",
            ["ContentJP"] = "ゴホン、受けて立とう。だが、その前に伝えておきたいことがあるんだ。ちょっと来てくれ。",
            ["DialogueId"] = 71005903,
            ["GUID"] = "B1C17DF6",
            ["SpeakNpcId"] = 818054,
            },
        [71005904] = {
            ["Content"] = "这些钱你拿着，等会比的时候拜托你放放水哈……我……不想让儿子失望，所以就跟他编了个瞎话说谁都跑不过我。",
            ["ContentJP"] = "この金はやるよ。だから、後で走る時……少しだけ手加減してくれないか……頼むよ。息子に失望されたくなくて、つい誰も足では俺に勝てないとか行っちまったんだ。",
            ["DialogueId"] = 71005904,
            ["GUID"] = "B1C17E20",
            ["NextOptions"] = {
                [1] = 710059041,
                [2] = 710059042,
                },
            ["SpeakNpcId"] = 818054,
            ["bForbidSkipOptions"] = true,
            },
        [71005905] = {
            ["Content"] = "谢谢，给你添麻烦了……",
            ["ContentJP"] = "すまないね、ありがとう……",
            ["DialogueId"] = 71005905,
            ["GUID"] = "B1C17E4A",
            ["SpeakNpcId"] = 818054,
            },
        [71005906] = {
            ["Content"] = "唉……好吧。",
            ["ContentJP"] = "はあ……わかったよ……",
            ["DialogueId"] = 71005906,
            ["GUID"] = "B1C17E74",
            ["SpeakNpcId"] = 818054,
            },
        [71005907] = {
            ["Content"] = "那么比赛马上开始，爸爸加油哦！",
            ["ContentJP"] = "じゃあ始めるよ！パパ、頑張ってね！",
            ["DialogueId"] = 71005907,
            ["GUID"] = "B1C17E9E",
            ["NextDialogue"] = 71005908,
            ["SpeakNpcId"] = 818053,
            },
        [71005908] = {
            ["Content"] = "三……",
            ["ContentJP"] = "三……",
            ["DialogueId"] = 71005908,
            ["Duration"] = 1,
            ["GUID"] = "B1C17EC8",
            ["NextDialogue"] = 71005909,
            ["SpeakNpcId"] = 818053,
            },
        [71005909] = {
            ["Content"] = "二……",
            ["ContentJP"] = "二……",
            ["DialogueId"] = 71005909,
            ["Duration"] = 1,
            ["GUID"] = "B1C17EF2",
            ["NextDialogue"] = 71005910,
            ["SpeakNpcId"] = 818053,
            },
        [71005910] = {
            ["Content"] = "一！",
            ["ContentJP"] = "一！",
            ["DialogueId"] = 71005910,
            ["Duration"] = 1,
            ["GUID"] = "B1C17F1C",
            ["SpeakNpcId"] = 818053,
            },
        [71005911] = {
            ["Content"] = "哇，爸爸真的好厉害！",
            ["ContentJP"] = "わぁ、パパすっごい！！",
            ["DialogueId"] = 71005911,
            ["GUID"] = "B1C17F46",
            ["NextDialogue"] = 71005912,
            ["SpeakNpcId"] = 818053,
            },
        [71005912] = {
            ["Content"] = "谢谢……这是我的一点心意，都拿去吧。",
            ["ContentJP"] = "おい……わざと手を抜いたな。ありがとう……これはほんのお礼だ。受け取ってくれ。",
            ["DialogueId"] = 71005912,
            ["GUID"] = "B1C17F70",
            ["SpeakNpcId"] = 818054,
            },
        [71005913] = {
            ["Content"] = "喂，这跟我们说好的不一样啊……",
            ["ContentJP"] = "おいおい、話が違うじゃないか……",
            ["DialogueId"] = 71005913,
            ["GUID"] = "B1C17F9A",
            ["NextDialogue"] = 71005914,
            ["SpeakNpcId"] = 818054,
            },
        [71005914] = {
            ["Content"] = "咦，说好的什么？",
            ["ContentJP"] = "ん？なんのこと？",
            ["DialogueId"] = 71005914,
            ["GUID"] = "B1C17FC4",
            ["NextDialogue"] = 71005915,
            ["SpeakNpcId"] = 818053,
            },
        [71005915] = {
            ["Content"] = "咳，没什么。抱歉啊儿子，我输了……",
            ["ContentJP"] = "ぐっ、いや、なんでもない。すまんな。パパ、負けちまった……",
            ["DialogueId"] = 71005915,
            ["GUID"] = "B1C17FEE",
            ["NextDialogue"] = 71005916,
            ["SpeakNpcId"] = 818054,
            },
        [71005916] = {
            ["Content"] = "没事的爸爸，这次只是失误！下次我们一起赢回来！",
            ["ContentJP"] = "ううん、全然平気だよ！誰だってうっかりすることくらいあるもんね！次は絶対勝とう！",
            ["DialogueId"] = 71005916,
            ["GUID"] = "B1C18018",
            ["NextDialogue"] = 71005917,
            ["SpeakNpcId"] = 818053,
            },
        [71005917] = {
            ["Content"] = "唉……好，好吧。来，这是你应得的奖品，都拿去吧。",
            ["ContentJP"] = "あ、ああ……そうだな。これはお礼の品だ、受け取ってくれ。",
            ["DialogueId"] = 71005917,
            ["GUID"] = "B1C18042",
            ["SpeakNpcId"] = 818054,
            },
        [71005918] = {
            ["Content"] = "抱歉啊儿子，我输了……",
            ["ContentJP"] = "すまんな。パパ、負けちまった……",
            ["DialogueId"] = 71005918,
            ["GUID"] = "B1C1806C",
            ["NextDialogue"] = 71005919,
            ["SpeakNpcId"] = 818054,
            },
        [71005919] = {
            ["Content"] = "没事的爸爸，这次只是失误！下次我们一起赢回来！",
            ["ContentJP"] = "ううん、全然平気だよ！誰だってうっかりすることくらいあるもんね！次は絶対勝とう！",
            ["DialogueId"] = 71005919,
            ["GUID"] = "B1C18096",
            ["NextDialogue"] = 71005920,
            ["SpeakNpcId"] = 818053,
            },
        [71005920] = {
            ["Content"] = "唉……好，好吧。也要谢谢这位狩月人了，这是你应得的奖品，都拿去吧。",
            ["ContentJP"] = "あ、ああ……そうだな。月狩り人さんも感謝するよ。よかったら、これを受け取ってくれ。",
            ["DialogueId"] = 71005920,
            ["GUID"] = "B1C180C0",
            ["SpeakNpcId"] = 818054,
            },
        [71005921] = {
            ["Content"] = "哇，爸爸真的好厉害！",
            ["ContentJP"] = "わぁ、パパすっごい！！",
            ["DialogueId"] = 71005921,
            ["GUID"] = "B1C180EA",
            ["NextDialogue"] = 71005922,
            ["SpeakNpcId"] = 818053,
            },
        [71005922] = {
            ["Content"] = "嘿……你是故意的吧。谢谢……这是我的一点心意，都拿去吧。",
            ["ContentJP"] = "ありがとう……これはほんのお礼だ。受け取ってくれ。",
            ["DialogueId"] = 71005922,
            ["GUID"] = "B1C18114",
            ["SpeakNpcId"] = 818054,
            },
        [71006001] = {
            ["Content"] = "（游荡的秽兽挤满了四周，先击退它们，再去解救魔灵吧。）",
            ["ContentJP"] = "あたりは<Default note=\"text:エジュウ\">穢獣</>で埋め尽くされている。やつらを退治してから、ジェネモンの捕獲に移ろう。",
            ["DialogueId"] = 71006001,
            ["GUID"] = "B1C18E0A",
            ["SpeakNpcId"] = 800006,
            },
        [71006002] = {
            ["Content"] = "（争斗的声响引来了更多秽兽。）",
            ["ContentJP"] = "争いの音に、さらに多くの<Default note=\"text:エジュウ\">穢獣</>が引き寄せられてしまった。",
            ["DialogueId"] = 71006002,
            ["GUID"] = "B1C18E34",
            ["SpeakNpcId"] = 800006,
            },
        [71006003] = {
            ["Content"] = "（附近暂时安全了，趁现在解救魔灵吧。）",
            ["ContentJP"] = "付近はひとまず安全だ。今のうちに、ジェネモンを捕獲しよう。",
            ["DialogueId"] = 71006003,
            ["GUID"] = "B1C18E5E",
            ["SpeakNpcId"] = 800006,
            },
        [71006101] = {
            ["Content"] = "咱不想……不想……不想上工啊……",
            ["ContentJP"] = "はぁ……仕事キライ……さぼりたい……",
            ["DialogueId"] = 71006101,
            ["GUID"] = "B1C19E72",
            ["SpeakNpcId"] = 818019,
            },
        [71006102] = {
            ["Content"] = "可恶……怎么这次还要往废矿送吃的啊。大家就不能挑点正常的地方吃饭吗！不怕出事吗！跑死我了……",
            ["ContentJP"] = "はぁ……なんで皆して鉱山に飯運ぶのさ。たまにはもっとマシな場所で食べられないの？危険だとか思うでしょ普通……もう、走りすぎて足ガクガクだよ……",
            ["DialogueId"] = 71006102,
            ["GUID"] = "B1C19E9C",
            ["NextDialogue"] = 71006103,
            ["SpeakNpcId"] = 818019,
            },
        [71006103] = {
            ["Content"] = "需要帮忙吗？",
            ["ContentJP"] = "手伝おっか？",
            ["DialogueId"] = 71006103,
            ["GUID"] = "B1C19EC6",
            ["NextDialogue"] = 71006104,
            ["SpeakNpcId"] = 100001,
            },
        [71006104] = {
            ["Content"] = "需要！这下面全是秽兽我过不去，你帮我把这份吃的送过去吧。",
            ["ContentJP"] = "わーい！この下に<Default note=\"text:エジュウ\">穢獣</>がうじゃうじゃいて通れないんだ。手伝ってくれない？",
            ["DialogueId"] = 71006104,
            ["GUID"] = "B1C19EF0",
            ["NextDialogue"] = 71006105,
            ["SpeakNpcId"] = 818019,
            },
        [71006105] = {
            ["Content"] = "好，交给我吧。",
            ["ContentJP"] = "もちろん、任せて。",
            ["DialogueId"] = 71006105,
            ["GUID"] = "B1C19F1A",
            ["SpeakNpcId"] = 100001,
            },
        [71006106] = {
            ["Content"] = "（大批秽兽拦住了你的去路，击退它们再过去吧。）",
            ["ContentJP"] = "大量の<Default note=\"text:エジュウ\">穢獣</>があなたの行く手を阻んでいる。さっそく退治しよう。",
            ["DialogueId"] = 71006106,
            ["GUID"] = "B1C19F44",
            ["SpeakNpcId"] = 800006,
            },
        [71006107] = {
            ["Content"] = "怎么还没送到……",
            ["ContentJP"] = "おっそいなぁ……",
            ["DialogueId"] = 71006107,
            ["GUID"] = "B1C19F6E",
            ["SpeakNpcId"] = 818058,
            },
        [71006108] = {
            ["Content"] = "你好，你订的饭送到了。",
            ["ContentJP"] = "こんにちは。ご注文の品を届けにきました。",
            ["DialogueId"] = 71006108,
            ["GUID"] = "B1C19F98",
            ["NextDialogue"] = 71006109,
            ["SpeakNpcId"] = 100001,
            },
        [71006109] = {
            ["Content"] = "我看看，这都洒成什么样子，根本没法吃啊！银色和平餐厅这新服务真是不靠谱！",
            ["ContentJP"] = "どれどれ……なんだこれは！こぼれてるじゃないか！これでは食べられん！！「シルバーピース」はまったく頼りにならんな！",
            ["DialogueId"] = 71006109,
            ["GUID"] = "B1C19FC2",
            ["NextOptions"] = {
                [1] = 710061091,
                [2] = 710061092,
                },
            ["SpeakNpcId"] = 818058,
            ["bForbidSkipOptions"] = true,
            },
        [71006110] = {
            ["Content"] = "这样啊……那你来送餐，比我写论文也简单不了多少。算了，这些给你，刚刚凶了你不好意思啊。",
            ["ContentJP"] = "そうだったのか……どうやら、私の論文作業と同じくらい苦労したようだな。まあいい。これをやろう。先ほどはついカッとなってしまって……すまなかったね。",
            ["DialogueId"] = 71006110,
            ["GUID"] = "B1C19FEC",
            ["SpeakNpcId"] = 818058,
            },
        [71006111] = {
            ["Content"] = "（你当着地质学者的面快速吃完了饭菜。）",
            ["ContentJP"] = "地質学者の前で料理を一気に頬張った。",
            ["DialogueId"] = 71006111,
            ["Duration"] = 3,
            ["GUID"] = "B1C1A016",
            ["NextDialogue"] = 71006112,
            ["SpeakNpcId"] = 800006,
            },
        [71006112] = {
            ["Content"] = "慢点慢点，要是我害你噎死了怎么办……唉……你来送餐，比我写论文也简单不了多少。算了，这些给你，刚刚凶了你不好意思啊。",
            ["ContentJP"] = "ちょっ、ゆっくり食べなさい！喉をつまらせたらどうするんだ……はぁ……ここまで送ってくるのに、私の論文作業と同じくらい苦労したんだろう？まあいい。これをやろう。先ほどはついカッとなってしまって……すまなかったね。",
            ["DialogueId"] = 71006112,
            ["GUID"] = "B1C1A040",
            ["SpeakNpcId"] = 818058,
            },
        [71006201] = {
            ["Content"] = "今天怎么回事，这么久了一条鱼都没上钩。",
            ["ContentJP"] = "今日はどういうわけか、魚が一匹も釣れないんだ。",
            ["DialogueId"] = 71006201,
            ["GUID"] = "B1C1AEDA",
            ["SpeakNpcId"] = 818055,
            },
        [71006202] = {
            ["Content"] = "狩月人你来啦，我怀疑这地方今天根本没有鱼，你能不能帮我试试？",
            ["ContentJP"] = "月狩り人、よく来たね。今日はここには魚なんていないんじゃないかと思ってるんだが……見てくれないか？",
            ["DialogueId"] = 71006202,
            ["GUID"] = "B1C1AF04",
            ["SpeakNpcId"] = 818055,
            },
        [71006203] = {
            ["Content"] = "好，拜托你了。",
            ["ContentJP"] = "ありがとう。",
            ["DialogueId"] = 71006203,
            ["GUID"] = "B1C1AF2E",
            ["SpeakNpcId"] = 818055,
            },
        [71006204] = {
            ["Content"] = "（待捕鱼系统做好后接入捕鱼系统）",
            ["DialogueId"] = 71006204,
            ["Duration"] = 3,
            ["GUID"] = "B1C1AF58",
            ["SpeakNpcId"] = 800006,
            },
        [71006205] = {
            ["Content"] = "太厉害了，一下就钓上来了。看来不是地方的问题。",
            ["ContentJP"] = "おお、一発で釣れるなんてすごいじゃないか！！どうやら場所の問題ではなかったようだね。",
            ["DialogueId"] = 71006205,
            ["GUID"] = "B1C1AF82",
            ["NextDialogue"] = 71006206,
            ["SpeakNpcId"] = 818055,
            },
        [71006206] = {
            ["Content"] = "谢谢你帮我验证了一下哈，我自己再在这里试试看。今天绝对不能再提着空桶回去了！",
            ["ContentJP"] = "ありがとう。今度は自分で釣ってみるよ。今日こそは空のバケツで帰るわけにはいかん！",
            ["DialogueId"] = 71006206,
            ["GUID"] = "B1C1AFAC",
            ["SpeakNpcId"] = 818055,
            },
        [71006301] = {
            ["Content"] = "救命啊，有没有人来救救我。",
            ["ContentJP"] = "だ、誰か！助けてくれ！！",
            ["DialogueId"] = 71006301,
            ["GUID"] = "B1C1BF42",
            ["SpeakNpcId"] = 818056,
            },
        [71006302] = {
            ["Content"] = "多谢……那个，能不能再帮我一个小忙。我这几天一条鱼都没钓上，回去总被大家笑话。你能不能帮我钓一条呢。",
            ["ContentJP"] = "ああ、ありがとう……ついでに一つ、手伝ってほしいことがあるんだ。ここ数日魚がまったく釣れなくて、みんなに笑われてるんだよ。代わりに一匹釣ってくれないか？",
            ["DialogueId"] = 71006302,
            ["GUID"] = "B1C1BF6C",
            ["SpeakNpcId"] = 818056,
            },
        [71006303] = {
            ["Content"] = "谢谢谢谢，桶我给你放边上了哈。",
            ["ContentJP"] = "おお、ありがたい！バケツはここに置いとくぞ。",
            ["DialogueId"] = 71006303,
            ["GUID"] = "B1C1BF96",
            ["SpeakNpcId"] = 818056,
            },
        [71006304] = {
            ["Content"] = "（待捕鱼系统做好后接入捕鱼系统）",
            ["DialogueId"] = 71006304,
            ["Duration"] = 3,
            ["GUID"] = "B1C1BFC0",
            ["SpeakNpcId"] = 800006,
            },
        [71006305] = {
            ["Content"] = "太好了，今天终于不用被大伙嘲笑了！这是我的谢礼，真是辛苦你啦。",
            ["ContentJP"] = "ああ、良かった。今日こそ笑われずに済みそうだ。これはお礼だ。ご苦労さま。",
            ["DialogueId"] = 71006305,
            ["GUID"] = "B1C1BFEA",
            ["SpeakNpcId"] = 818056,
            },
        [71006401] = {
            ["Content"] = "（玄色狴犴骤然出现，击退它们！）",
            ["ContentJP"] = "（玄狴が現れた！奴らを撃破せよ！）",
            ["DialogueId"] = 71006401,
            ["GUID"] = "B1C1CFAA",
            ["SpeakNpcId"] = 800006,
            },
        [71006501] = {
            ["Content"] = "有奖竞猜有奖竞猜，那边那位朋友要不要来看看呀。",
            ["ContentJP"] = "賞品付き謎かけだよ！そこのお客さん、ちょっと見て行かない？",
            ["DialogueId"] = 71006501,
            ["GUID"] = "B1C1E012",
            ["SpeakNpcId"] = 818060,
            },
        [71006502] = {
            ["Content"] = "恰逢奉香大典临近，本店特推出节庆活动，在举办一个叫非常大脑的智力问答活动，答错也有安慰奖，要不要来挑战一下？",
            ["ContentJP"] = "ちょうど「奉香の儀」が近づいてるからね、うちではお祭りイベントとして、特別企画「スーパー脳力チャレンジ」開催中！間違えても参加賞があるよ、どう？腕試ししていかない？",
            ["DialogueId"] = 71006502,
            ["GUID"] = "B1C1E03C",
            ["NextOptions"] = {
                [1] = 710065021,
                [2] = 710065022,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006504] = {
            ["Content"] = "好，你先稍作休息，我们马上开始。",
            ["ContentJP"] = "よし、まずは少し休んでて。すぐに始めるからね。",
            ["DialogueId"] = 71006504,
            ["GUID"] = "B1C1E090",
            ["SpeakNpcId"] = 818060,
            },
        [71006505] = {
            ["Content"] = "喂，那边的朋友先别急着去答题，要不要听听我的提议？",
            ["ContentJP"] = "──そこのお客さん、そんなに急いで答えに行かなくてもいいんじゃない？ちょっと、私の話を聞いてよ。",
            ["DialogueId"] = 71006505,
            ["GUID"] = "B1C1E0BA",
            ["SpeakNpcId"] = 818061,
            },
        [71006506] = {
            ["Content"] = "那家伙净出一些麻烦的脑筋急转弯，你要是帮我搬下货，我就直接告诉你答案。如何？这样也省得你动脑子了。",
            ["ContentJP"] = "あいつさ、いつもややこしい謎かけばっか出してくるんだよね。もしちょっと荷物運びを手伝ってくれたら、こっそり答えを教えてあげるよ。どう？頭を使わずに済むし、お得でしょ？",
            ["DialogueId"] = 71006506,
            ["GUID"] = "B1C1E0E4",
            ["NextOptions"] = {
                [1] = 710065071,
                [2] = 710065072,
                },
            ["SpeakNpcId"] = 818061,
            },
        [71006507] = {
            ["Content"] = "辛苦了，货就在那边的船上。",
            ["ContentJP"] = "助かったよ。荷物はあそこの船に積んであるから、よろしくね。",
            ["DialogueId"] = 71006507,
            ["GUID"] = "B1C1E10E",
            ["SpeakNpcId"] = 818061,
            },
        [71006508] = {
            ["Content"] = "辛苦了，他今天这个问题应该选第一个。",
            ["ContentJP"] = "お疲れさま。今日の問題、正解はたぶん1だよ。",
            ["DialogueId"] = 71006508,
            ["GUID"] = "B1C1E138",
            ["SpeakNpcId"] = 818061,
            },
        [71006509] = {
            ["Content"] = "辛苦了，他今天这个问题应该选第二个。",
            ["ContentJP"] = "お疲れさま。今日の問題、2を選べばきっと当たるよ。",
            ["DialogueId"] = 71006509,
            ["GUID"] = "B1C1E162",
            ["SpeakNpcId"] = 818061,
            },
        [71006510] = {
            ["Content"] = "辛苦了，他今天这个问题应该选第三个。",
            ["ContentJP"] = "お疲れさま。今日の問題、3だったはず。",
            ["DialogueId"] = 71006510,
            ["GUID"] = "B1C1E18C",
            ["SpeakNpcId"] = 818061,
            },
        [71006511] = {
            ["Content"] = "休息好了吗？",
            ["ContentJP"] = "準備はいい？",
            ["DialogueId"] = 71006511,
            ["GUID"] = "B1C1E1B6",
            ["NextOptions"] = {
                [1] = 710065111,
                [2] = 710065112,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006512] = {
            ["Content"] = "休息好了吗？",
            ["ContentJP"] = "準備はいい？",
            ["DialogueId"] = 71006512,
            ["GUID"] = "B1C1E1E0",
            ["NextOptions"] = {
                [1] = 710065121,
                [2] = 710065122,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006513] = {
            ["Content"] = "休息好了吗？",
            ["ContentJP"] = "準備はいい？",
            ["DialogueId"] = 71006513,
            ["GUID"] = "B1C1E20A",
            ["NextOptions"] = {
                [1] = 710065131,
                [2] = 710065132,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006514] = {
            ["Content"] = "请听题！织星客丢了一件商品，经过调查找到了甲乙丙三人。甲指责：“是乙偷的！”。乙声称：“是丙偷的！”。丙说：“确实是我偷的！”。仅一人说了真话，请问到底是谁偷走了商品？",
            ["ContentJP"] = "では問題！星織人が商品をひとつ失くしてしまい、調査の末に見つかったのはA、B、Cの三人。Aさんは「盗んだのはBだ！」と、Bさんは「盗んだのはCだ！」と、Cさんは「そうだ、盗んだのは私だ！」と証言しているが、この中で本当のことを言っているのはたった一人だ。さて、盗んだのは誰でしょう？",
            ["DialogueId"] = 71006514,
            ["GUID"] = "B1C1E234",
            ["NextOptions"] = {
                [1] = 710065141,
                [2] = 710065142,
                [3] = 710065143,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006515] = {
            ["Content"] = "请听题！锦鲤皎皎的好友有三个皎皎朋友，第一个叫黄金皎皎，第二个叫白银皎皎，第三个叫什么？",
            ["ContentJP"] = "では問題！ニシキには、仲良しのルーナが三人いる。ひとり目はゴールド、ふたり目はシルバーって名前だ。さて、三人目の名前は何でしょう？",
            ["DialogueId"] = 71006515,
            ["GUID"] = "B1C1E25E",
            ["NextOptions"] = {
                [1] = 710065151,
                [2] = 710065152,
                [3] = 710065153,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006516] = {
            ["Content"] = "请听题！三人前后排队，各带帽子一顶，帽子颜色可能会出现红、黄、蓝其中一种。最后一人能看到前两人的帽子，中间的人只能看前面。最后一人沉默，接着中间人也沉默。第一人说自己戴黄帽。已知至少一人戴黄帽。下列哪个说法是正确的？",
            ["ContentJP"] = "三人が一列に並び、それぞれが赤・黄・青のいずれかの帽子をかぶっている。最後尾の人は前の二人の帽子の色を見ることができる。真ん中の人は前方一人の帽子のみ見える。先頭の人は他者の帽子を見ることができない。一番後ろの人と、真ん中の人も何も言わなかった。先頭の人が「私の帽子は黄色だ」と答えた。なお、三人の中に少なくとも一つは黄色の帽子があることがわかっている。このとき、次のうち正しいのはどれか？",
            ["DialogueId"] = 71006516,
            ["GUID"] = "B1C1E288",
            ["NextOptions"] = {
                [1] = 710065161,
                [2] = 710065162,
                [3] = 710065163,
                },
            ["SpeakNpcId"] = 818060,
            ["bForbidSkipOptions"] = true,
            },
        [71006517] = {
            ["Content"] = "恭喜你答对了！这是为你准备的豪华奖品，请拿好～",
            ["ContentJP"] = "おめでとう、正解だよ！この豪華賞品、受け取ってね～",
            ["DialogueId"] = 71006517,
            ["GUID"] = "B1C1E2B2",
            ["SpeakNpcId"] = 818060,
            },
        [71006518] = {
            ["Content"] = "回答错误，这是你的安慰奖，欢迎下次再来挑战哦～",
            ["ContentJP"] = "残念、不正解！はい、参加賞だよ。またいつでも挑戦しにおいで～",
            ["DialogueId"] = 71006518,
            ["GUID"] = "B1C1E2DC",
            ["SpeakNpcId"] = 818060,
            },
        [71006519] = {
            ["Content"] = "好吧好吧，还是年轻人有干劲，那你加油。",
            ["ContentJP"] = "はいはい、やっぱり若いって元気だねぇ。じゃあ、頑張って！",
            ["DialogueId"] = 71006519,
            ["GUID"] = "B1C1E306",
            ["SpeakNpcId"] = 818061,
            },
        [71006520] = {
            ["Content"] = "嗯，准备好了再来找我吧！",
            ["ContentJP"] = "うん、準備ができたらまた声をかけてね。",
            ["DialogueId"] = 71006520,
            ["GUID"] = "B1C1E330",
            ["SpeakNpcId"] = 818060,
            },
        [71006601] = {
            ["Content"] = "好想要小青蛙呀，咕咕呱呱呱。",
            ["ContentJP"] = "カエルさんが、ほしいなぁ、ケロケロ…",
            ["DialogueId"] = 71006601,
            ["GUID"] = "B1C1F07A",
            ["SpeakNpcId"] = 818062,
            },
        [71006602] = {
            ["Content"] = "小青蛙，好想要小青蛙，小青蛙小青蛙小青蛙。",
            ["ContentJP"] = "カエルさんがほしい、すごくほしい、カエルさんカエルさんカエルさん…",
            ["DialogueId"] = 71006602,
            ["GUID"] = "B1C1F0A4",
            ["NextOptions"] = {
                [1] = 710066021,
                [2] = 710066022,
                },
            ["SpeakNpcId"] = 818062,
            ["bForbidSkipOptions"] = true,
            },
        [71006603] = {
            ["Content"] = "（它似乎对青蛙有什么执念，帮它找找看吧。）",
            ["ContentJP"] = "どうやらカエルに強い執着があるようだ。探してあげよう。",
            ["DialogueId"] = 71006603,
            ["GUID"] = "B1C1F0CE",
            ["SpeakNpcId"] = 100001,
            },
        [71006604] = {
            ["Content"] = "这些应该足够了，回去交给它吧。",
            ["ContentJP"] = "これだけあれば十分だろう、あの子に届けに行こう。",
            ["DialogueId"] = 71006604,
            ["GUID"] = "B1C1F0F8",
            ["SpeakNpcId"] = 100001,
            },
        [71006605] = {
            ["Content"] = "小青蛙，好耶，小青蛙，好～咕呱咕呱。",
            ["ContentJP"] = "カエルさん！やった～！うれし～！ケロケロ！",
            ["DialogueId"] = 71006605,
            ["GUID"] = "B1C1F122",
            ["NextDialogue"] = 71006606,
            ["SpeakNpcId"] = 818062,
            },
        [71006606] = {
            ["Content"] = "（就这样，无由生消失在了你的面前。）",
            ["ContentJP"] = "こうして、ムユウセイはあなたの目の前からふっと姿を消した。",
            ["DialogueId"] = 71006606,
            ["GUID"] = "B1C1F14C",
            ["SpeakNpcId"] = 800006,
            },
        [71006701] = {
            ["Content"] = "这么简单的题要是再答错，今晚就给我留下来抄一百遍吧。",
            ["ContentJP"] = "こんな簡単な問題すら解けないようでは――今夜はここに残って、百回書き写してもらうしかないな。",
            ["DialogueId"] = 71006701,
            ["GUID"] = "B1C200E2",
            ["NextDialogue"] = 71006702,
            ["SpeakNpcId"] = 818064,
            },
        [71006702] = {
            ["Content"] = "（愤怒的声音从远处传来，过去看看发生了什么吧。）",
            ["ContentJP"] = "怒気をはらんだ声が風に乗って届く。何があったのか、見に行ってみよう。",
            ["DialogueId"] = 71006702,
            ["GUID"] = "B1C2010C",
            ["SpeakNpcId"] = 800006,
            },
        [71006703] = {
            ["Content"] = "这是怎么了？",
            ["ContentJP"] = "何があったんですか？",
            ["DialogueId"] = 71006703,
            ["GUID"] = "B1C20136",
            ["NextDialogue"] = 71006704,
            ["SpeakNpcId"] = 100001,
            },
        [71006704] = {
            ["Content"] = "呼……这孩子连大风九章都默写不下来。这点定性都没有，以后还怎么精进学业？",
            ["ContentJP"] = "まったく……この子、大風九章の写し書きすらできないんですよ。これほど落ち着きがなくては、学びを深めるどころか、足元さえおぼつかないでしょうね。",
            ["DialogueId"] = 71006704,
            ["GUID"] = "B1C20160",
            ["NextDialogue"] = 71006705,
            ["SpeakNpcId"] = 818064,
            },
        [71006705] = {
            ["Content"] = "不行，越想越气，我去喝口茶冷静一下，你帮我盯一下吧。",
            ["ContentJP"] = "ダメだ、考えれば考えるほど腹が立ってきた……。少し茶でも飲んで頭を冷やしてきます。悪いけど、この子のこと、ちょっと見ていてもらえますか？",
            ["DialogueId"] = 71006705,
            ["GUID"] = "B1C2018A",
            ["NextOptions"] = {
                [1] = 710067051,
                [2] = 710067052,
                },
            ["SpeakNpcId"] = 818064,
            ["bForbidSkipOptions"] = true,
            },
        [71006706] = {
            ["Content"] = "劳烦你了，我很快回来。",
            ["ContentJP"] = "申し訳ないね、すぐに戻りますので。",
            ["DialogueId"] = 71006706,
            ["GUID"] = "B1C201B4",
            ["SpeakNpcId"] = 818064,
            },
        [71006707] = {
            ["Content"] = "呜呜呜呜……下一句到底是什么来着……",
            ["ContentJP"] = "うぅぅぅ……下の句、なんだったっけ……",
            ["DialogueId"] = 71006707,
            ["GUID"] = "B1C201DE",
            ["NextDialogue"] = 71006708,
            ["SpeakNpcId"] = 818063,
            },
        [71006708] = {
            ["Content"] = "这位朋友，你能不能也帮帮我呀……",
            ["ContentJP"] = "そこのお方……お願い、少しだけ手を貸してくれませんか……？",
            ["DialogueId"] = 71006708,
            ["GUID"] = "B1C20208",
            ["SpeakNpcId"] = 818063,
            },
        [71006709] = {
            ["Content"] = "我写到“著真去伪，赤心为诚。”了，但下一句怎么都想不起来，你能帮我翻下书看看后面是什么吗？",
            ["ContentJP"] = "「真を著し、偽を払うは、赤心の証」までは書けたんですけど、その次がどうしても思い出せなくて……本で解答を探してもらえませんか？",
            ["DialogueId"] = 71006709,
            ["GUID"] = "B1C20232",
            ["NextOptions"] = {
                [1] = 710067091,
                [2] = 710067092,
                },
            ["SpeakNpcId"] = 818063,
            ["bForbidSkipOptions"] = true,
            },
        [71006711] = {
            ["Content"] = "不……我想出去玩啊……",
            ["ContentJP"] = "うぅ……本当は外に遊びに行きたいのに……",
            ["DialogueId"] = 71006711,
            ["GUID"] = "B1C20286",
            ["SpeakNpcId"] = 818063,
            },
        [71006712] = {
            ["Content"] = "真是帮了大忙了！谢谢你谢谢你！",
            ["ContentJP"] = "助かったよ、本当にありがとう！感謝してもしきれない……！",
            ["DialogueId"] = 71006712,
            ["GUID"] = "B1C202B0",
            ["SpeakNpcId"] = 818063,
            },
        [71006713] = {
            ["Content"] = "（你翻开抄写着大风九章的册子，“著真去伪，赤心为诚。”下一句是“妄言欺众，不可为也。”）",
            ["ContentJP"] = "あなたは『大風九章』の写本を開いた。「真を著し、偽を払うは、赤心の証」の下の句は――「虚を語り、衆を惑わすこと、為すべからず」と記されていた。",
            ["DialogueId"] = 71006713,
            ["GUID"] = "B1C202DA",
            ["NextDialogue"] = 71006714,
            ["SpeakNpcId"] = 800006,
            },
        [71006714] = {
            ["Content"] = "找到了，回去告诉他答案吧。",
            ["ContentJP"] = "見つけた。彼に教えてあげよう。",
            ["DialogueId"] = 71006714,
            ["GUID"] = "B1C20304",
            ["SpeakNpcId"] = 100001,
            },
        [71006715] = {
            ["Content"] = "你可算回来了，快快快，下一句是什么？",
            ["ContentJP"] = "あっ、帰ってきた！早く早く、下の句はなんだったの？",
            ["DialogueId"] = 71006715,
            ["GUID"] = "B1C2032E",
            ["SpeakNpcId"] = 818063,
            },
        [71006717] = {
            ["Content"] = "哼，这都能错！今晚给我再抄五百遍，少一遍都不准走！",
            ["ContentJP"] = "ふん、こんな簡単な問題を外すなど！今晩は五百回写し終えるまで帰さんからな！",
            ["DialogueId"] = 71006717,
            ["GUID"] = "B1C20382",
            ["NextDialogue"] = 71006718,
            ["SpeakNpcId"] = 818064,
            },
        [71006718] = {
            ["Content"] = "不——",
            ["ContentJP"] = "そんなああ――",
            ["DialogueId"] = 71006718,
            ["GUID"] = "B1C203AC",
            ["NextDialogue"] = 71006719,
            ["SpeakNpcId"] = 818063,
            },
        [71006719] = {
            ["Content"] = "谢谢你帮我盯着他了，这是给你的谢礼，还请收下。",
            ["ContentJP"] = "助かりました。これはあなたへのお礼です。どうかお受け取りください。",
            ["DialogueId"] = 71006719,
            ["GUID"] = "B1C203D6",
            ["SpeakNpcId"] = 818064,
            },
        [71006720] = {
            ["Content"] = "你看，只要沉下心来仔细回想，这不是能写出来吗！",
            ["ContentJP"] = "ほれ、落ち着いて思い出せば、ちゃんと書けるじゃないか。",
            ["DialogueId"] = 71006720,
            ["GUID"] = "B1C20400",
            ["NextDialogue"] = 71006721,
            ["SpeakNpcId"] = 818064,
            },
        [71006721] = {
            ["Content"] = "好耶，出去玩喽！",
            ["ContentJP"] = "やったー！これで遊びに行ける！",
            ["DialogueId"] = 71006721,
            ["GUID"] = "B1C2042A",
            ["NextDialogue"] = 71006722,
            ["SpeakNpcId"] = 818063,
            },
        [71006722] = {
            ["Content"] = "站住！因为你今日的默写达标，所以只用再抄五十遍就行，抄完再走。",
            ["ContentJP"] = "待ちなさい！今日の写し書きは基準に達していたぞ。五十回で許してやろう。だが、終わるまでは帰さんからな。",
            ["DialogueId"] = 71006722,
            ["Duration"] = 3,
            ["GUID"] = "B1C20454",
            ["NextDialogue"] = 71006723,
            ["SpeakNpcId"] = 818064,
            },
        [71006723] = {
            ["Content"] = "不——",
            ["ContentJP"] = "そんなああ――",
            ["DialogueId"] = 71006723,
            ["GUID"] = "B1C2047E",
            ["NextDialogue"] = 71006724,
            ["SpeakNpcId"] = 818063,
            },
        [71006724] = {
            ["Content"] = "谢谢你帮我盯着他了，这是给你的谢礼，还请收下。",
            ["ContentJP"] = "助かりました。これはあなたへのお礼です。どうかお受け取りください。",
            ["DialogueId"] = 71006724,
            ["GUID"] = "B1C204A8",
            ["SpeakNpcId"] = 818064,
            },
        [71006801] = {
            ["Content"] = "喂，那边的朋友，能帮我拍张照吗？",
            ["ContentJP"] = "おーい、そこの君！ちょっと写真を撮ってくれない？",
            ["DialogueId"] = 71006801,
            ["GUID"] = "B1C2114A",
            ["SpeakNpcId"] = 818041,
            },
        [71006802] = {
            ["Content"] = "这位朋友，你能帮我拍几张照片吗？难得来一趟百年春，不留点合影就太可惜了。",
            ["ContentJP"] = "ねぇ君、ちょっと写真撮ってくれない？せっかく百年春まで来たんだし、記念に何枚か残しておきたくてさ！",
            ["DialogueId"] = 71006802,
            ["GUID"] = "B1C21174",
            ["NextOptions"] = {
                [1] = 710068021,
                [2] = 710068022,
                },
            ["SpeakNpcId"] = 818041,
            ["bForbidSkipOptions"] = true,
            },
        [71006804] = {
            ["Content"] = "太好了，记得把我后面的这条白龙也拍进去哦，我很喜欢它的造型。",
            ["ContentJP"] = "やった！ありがとう！後ろの白龍もちゃんと写してね、あのデザイン、すっごく気に入ってるんだ〜！",
            ["DialogueId"] = 71006804,
            ["GUID"] = "B1C211C8",
            ["SpeakNpcId"] = 818041,
            },
        [71006805] = {
            ["Content"] = "你拍得也太好了，真棒呀，多谢多谢。",
            ["ContentJP"] = "うわっ、めっちゃ上手に撮れてる！ほんとありがとう〜！",
            ["DialogueId"] = 71006805,
            ["GUID"] = "B1C211F2",
            ["SpeakNpcId"] = 818041,
            },
        [71006901] = {
            ["Content"] = "哎呀哎呀，这可糟了……",
            ["ContentJP"] = "やってしまった……",
            ["DialogueId"] = 71006901,
            ["GUID"] = "B1C221B2",
            ["SpeakNpcId"] = 818065,
            },
        [71006902] = {
            ["Content"] = "这位朋友，我不小心把酒壶、鱼饵还有鱼竿全掉水里了，你能不能帮我钓几条鱼上来啊，不然回去又要被大伙嘲笑了。",
            ["ContentJP"] = "うっかり、酒壺と魚の餌、それに釣り竿まで川に落としちゃったんだ……代わりに何匹か魚を釣ってきてくれない？このままじゃ、みんなに笑われちゃうよ……",
            ["DialogueId"] = 71006902,
            ["GUID"] = "B1C221DC",
            ["NextOptions"] = {
                [1] = 710069021,
                [2] = 710069022,
                },
            ["SpeakNpcId"] = 818065,
            },
        [71006903] = {
            ["Content"] = "好好好，拜托你了。",
            ["ContentJP"] = "よかった。頼んだよ。",
            ["DialogueId"] = 71006903,
            ["GUID"] = "B1C22206",
            ["SpeakNpcId"] = 818065,
            },
        [71006904] = {
            ["Content"] = "怎么还能钓上这种鱼，总不会是被我的酒壶吸引过来的吧？！算了算了，以后再研究。",
            ["ContentJP"] = "こんな魚まで釣れちゃうなんて……まさか、酒壺の匂いに惹かれてきたのか？いや、まあいいや、今度じっくり研究してみるよ。",
            ["DialogueId"] = 71006904,
            ["GUID"] = "B1C22230",
            ["NextDialogue"] = 71006905,
            ["SpeakNpcId"] = 818065,
            },
        [71006905] = {
            ["Content"] = "谢谢你今天帮我钓的这些鱼啊，帮大忙了！",
            ["ContentJP"] = "今日はたくさん釣ってくれて、本当にありがとう！おかげで面目が立ったよ！",
            ["DialogueId"] = 71006905,
            ["GUID"] = "B1C2225A",
            ["SpeakNpcId"] = 818065,
            },
        [71007001] = {
            ["Content"] = "这可怎生是好？白龙神君，派个人来帮帮我吧！",
            ["ContentJP"] = "どうしたものか……白龍様、どうか助けてくだされ……！",
            ["DialogueId"] = 71007001,
            ["GUID"] = "B1C2321A",
            ["SpeakNpcId"] = 818066,
            },
        [71007002] = {
            ["Content"] = "发生什么了？",
            ["ContentJP"] = "どうした？",
            ["DialogueId"] = 71007002,
            ["GUID"] = "B1C23244",
            ["NextDialogue"] = 71007003,
            ["SpeakNpcId"] = 100001,
            },
        [71007003] = {
            ["Content"] = "我与心上人约在此处相见，但场地尚未布置妥当。阁下可以替我跑一趟，买件礼物回来吗？",
            ["ContentJP"] = "あの……この場所で、好きな人と会う約束をしているんです。でもまだ、場の準備が整っていなくて……代わりに贈り物をひとつ、買ってきていただけませんか？",
            ["DialogueId"] = 71007003,
            ["GUID"] = "B1C2326E",
            ["NextOptions"] = {
                [1] = 710070031,
                [2] = 710070032,
                },
            ["SpeakNpcId"] = 818066,
            ["bForbidSkipOptions"] = true,
            },
        [71007004] = {
            ["Content"] = "那可真是有劳了！啊对了，我那心上人对花过敏，切记不要买含花的礼物啊。",
            ["ContentJP"] = "助かります！あっ、それと……あの人、花粉アレルギーなんです。くれぐれも花だけは避けてくださいね。",
            ["DialogueId"] = 71007004,
            ["GUID"] = "B1C23298",
            ["SpeakNpcId"] = 818066,
            },
        [71007005] = {
            ["Content"] = "你好，我想挑一件适合送人的礼物。",
            ["ContentJP"] = "こんにちは。贈り物をひとつ選びたいのですが。",
            ["DialogueId"] = 71007005,
            ["GUID"] = "B1C232C2",
            ["NextDialogue"] = 71007006,
            ["SpeakNpcId"] = 100001,
            },
        [71007006] = {
            ["Content"] = "好嘞，现在这三款礼物最受欢迎，且听我慢慢道来。",
            ["ContentJP"] = "はいよ、お客さん。いま人気の三品、じっくり紹介させてもらいますよ。",
            ["DialogueId"] = 71007006,
            ["GUID"] = "B1C232EC",
            ["NextDialogue"] = 71007007,
            ["SpeakNpcId"] = 818067,
            },
        [71007007] = {
            ["Content"] = "第一件是蒹葭浦现采的告苍花，还带着清晨的露珠，送女孩子准没错。",
            ["ContentJP"] = "ひとつめは「吿蒼の花」。蒹葭の浦で朝摘みされたばかりで、露の香りが残ってます。女性に贈れば喜ばれること間違いなし。",
            ["DialogueId"] = 71007007,
            ["GUID"] = "B1C23316",
            ["NextDialogue"] = 71007008,
            ["SpeakNpcId"] = 818067,
            },
        [71007008] = {
            ["Content"] = "第二件是机枢派名家打磨的青铜吊坠，做功考究，细节精致。",
            ["ContentJP"] = "ふたつめは「ブロンズのペンダント」。機枢派の職人が丁寧に仕上げた逸品で、細部まで緻密な造りです。",
            ["DialogueId"] = 71007008,
            ["GUID"] = "B1C23340",
            ["NextDialogue"] = 71007009,
            ["SpeakNpcId"] = 818067,
            },
        [71007009] = {
            ["Content"] = "第三件是悬衡派特制的白龙神君造型摆件，技艺精湛，栩栩如生。",
            ["ContentJP"] = "みっつめは「白龍様の置物」。これは懸衡派特製で、彫りも見事。ほら、まるで生きているようでしょう？",
            ["DialogueId"] = 71007009,
            ["GUID"] = "B1C2336A",
            ["NextDialogue"] = 71007010,
            ["SpeakNpcId"] = 818067,
            },
        [71007010] = {
            ["Content"] = "你想要哪一件呀？",
            ["ContentJP"] = "さあ、どれにしますか？",
            ["DialogueId"] = 71007010,
            ["GUID"] = "B1C23394",
            ["NextOptions"] = {
                [1] = 710070101,
                [2] = 710070102,
                [3] = 710070103,
                },
            ["SpeakNpcId"] = 818067,
            ["bForbidSkipOptions"] = true,
            },
        [71007011] = {
            ["Content"] = "好嘞，这就给您包装好。下次再来哈。",
            ["ContentJP"] = "はいよ、ではお包みしますね。またのご利用、お待ちしております！",
            ["DialogueId"] = 71007011,
            ["GUID"] = "B1C233BE",
            ["SpeakNpcId"] = 818067,
            },
        [71007012] = {
            ["Content"] = "礼物来了，快打开看看合不合你心意！",
            ["ContentJP"] = "贈り物を持ってきました。さあ、開けてみて。気に入ってもらえるかな？",
            ["DialogueId"] = 71007012,
            ["GUID"] = "B1C233E8",
            ["NextDialogue"] = 71007013,
            ["SpeakNpcId"] = 818066,
            },
        [71007013] = {
            ["Content"] = "阿嚏！阿……阿嚏……怎，怎么有花……我感觉有点不舒服，要……喘不上气了……",
            ["ContentJP"] = "ハ、ハクションッ！は……ハクションッ……っ、ど、どうして……花……？うっ……息が……くるし……",
            ["DialogueId"] = 71007013,
            ["GUID"] = "B1C23412",
            ["NextDialogue"] = 71007014,
            ["SpeakNpcId"] = 818068,
            },
        [71007014] = {
            ["Content"] = "（男子见状立马背起他的心上人求医，留你一个人在原地。）",
            ["ContentJP"] = "男性は慌てて恋人を背負い、医者を求めて駆け出していった。あなたはその場にひとり取り残された。",
            ["DialogueId"] = 71007014,
            ["GUID"] = "B1C2343C",
            ["NextDialogue"] = 71007015,
            ["SpeakNpcId"] = 800006,
            },
        [71007015] = {
            ["Content"] = "（这里的事已经处理完毕，可以离开了。）",
            ["ContentJP"] = "これでここでの用は済んだ。立ち去ろう。",
            ["DialogueId"] = 71007015,
            ["GUID"] = "B1C23466",
            ["SpeakNpcId"] = 800006,
            },
        [71007016] = {
            ["Content"] = "礼物拿来了，快拆开来看看合不合你心意！",
            ["ContentJP"] = "贈り物を持ってきました。さあ、開けてみて。気に入ってもらえるかな？",
            ["DialogueId"] = 71007016,
            ["GUID"] = "B1C23490",
            ["NextDialogue"] = 71007017,
            ["SpeakNpcId"] = 818066,
            },
        [71007017] = {
            ["Content"] = "谢谢，只要是你为我准备的，我都喜欢！",
            ["ContentJP"] = "ありがとう……あなたが選んでくれたものなら、なんでも嬉しい。",
            ["DialogueId"] = 71007017,
            ["GUID"] = "B1C234BA",
            ["NextDialogue"] = 71007018,
            ["SpeakNpcId"] = 818068,
            },
        [71007018] = {
            ["Content"] = "（男子看着心上人脸上幸福的表情，悄悄向你竖起了大拇指。）",
            ["ContentJP"] = "恋人の幸せそうな笑顔を見て、男性はあなたにそっと親指を立てた。",
            ["DialogueId"] = 71007018,
            ["GUID"] = "B1C234E4",
            ["NextDialogue"] = 71007019,
            ["SpeakNpcId"] = 800006,
            },
        [71007019] = {
            ["Content"] = "（这里的事已经处理完毕，可以离开了。）",
            ["ContentJP"] = "これでここでの用は済んだ。立ち去ろう。",
            ["DialogueId"] = 71007019,
            ["GUID"] = "B1C2350E",
            ["SpeakNpcId"] = 800006,
            },
        [71007101] = {
            ["Content"] = "唉……怎么时间刚好都撞一块了呢……",
            ["ContentJP"] = "はぁ……なんでこう、予定が全部かぶっちゃうんだろう……",
            ["DialogueId"] = 71007101,
            ["GUID"] = "B1C24282",
            ["SpeakNpcId"] = 818069,
            },
        [71007103] = {
            ["Content"] = "诶，这位朋友来得正好，你能帮我去那边排块核桃酥吗？",
            ["ContentJP"] = "――あ、ちょうどよかった！そこの君、あっちの屋台でくるみ菓子「桃酥（タオス）」を買ってきてもらえないか？",
            ["DialogueId"] = 71007103,
            ["GUID"] = "B1C242D6",
            ["NextDialogue"] = 71007104,
            ["SpeakNpcId"] = 818069,
            },
        [71007104] = {
            ["Content"] = "我等会还约了其他人谈生意，实在没空去排队了。",
            ["ContentJP"] = "このあと取引の約束もあって、自分で並びに行く時間がなくて……",
            ["DialogueId"] = 71007104,
            ["GUID"] = "B1C24300",
            ["NextOptions"] = {
                [1] = 710071041,
                [2] = 710071042,
                },
            ["SpeakNpcId"] = 818069,
            ["bForbidSkipOptions"] = true,
            },
        [71007105] = {
            ["Content"] = "谢了，那我先走一步。",
            ["ContentJP"] = "ありがとう、じゃあ私は先に行くよ。",
            ["DialogueId"] = 71007105,
            ["GUID"] = "B1C2432A",
            ["SpeakNpcId"] = 818069,
            },
        [71007106] = {
            ["Content"] = "（一段时间后……）",
            ["ContentJP"] = "しばらくして……",
            ["DialogueId"] = 71007106,
            ["GUID"] = "B1C24354",
            ["SpeakNpcId"] = 800006,
            },
        [71007107] = {
            ["Content"] = "（刚买好小吃，你就看到身后有个孩子眼巴巴地看着你。）",
            ["ContentJP"] = "ちょうどくるみ菓子を手にしたあなたの背後に、小さな子どもがじっと見つめていた。",
            ["DialogueId"] = 71007107,
            ["GUID"] = "B1C2437E",
            ["SpeakNpcId"] = 800006,
            },
        [71007108] = {
            ["Content"] = "那个……我能用这些钱买你的核桃酥吗？我妈妈很喜欢这家的核桃酥，但她最近生病了，我想给她带一份回家……",
            ["ContentJP"] = "あの……そのくるみ菓子、ぼくに譲ってもらえませんか？お母さんがそのお菓子すごく好きなんだけど、最近ずっと寝込んでて……ぼく、お土産に持って帰りたいんです。",
            ["DialogueId"] = 71007108,
            ["GUID"] = "B1C243A8",
            ["NextOptions"] = {
                [1] = 710071081,
                [2] = 710071082,
                },
            ["SpeakNpcId"] = 818070,
            ["bForbidSkipOptions"] = true,
            },
        [71007109] = {
            ["Content"] = "既然这样，那还是让给你吧，希望你妈妈能快点好起来。",
            ["ContentJP"] = "そうなんだね……それなら、譲るよ。お母さん、早く元気になるといいね。",
            ["DialogueId"] = 71007109,
            ["GUID"] = "B1C243D2",
            ["NextDialogue"] = 710071091,
            ["SpeakNpcId"] = 100001,
            },
        [71007110] = {
            ["Content"] = "回来了回来了，吃的在哪呢？",
            ["ContentJP"] = "お帰り、お菓子はどこだい？",
            ["DialogueId"] = 71007110,
            ["GUID"] = "B1C243FC",
            ["NextDialogue"] = 71007111,
            ["SpeakNpcId"] = 818069,
            },
        [71007111] = {
            ["Content"] = "（你和男子说明了事情经过……）",
            ["ContentJP"] = "あなたは事情を説明した……",
            ["DialogueId"] = 71007111,
            ["GUID"] = "B1C24426",
            ["NextDialogue"] = 71007112,
            ["SpeakNpcId"] = 800006,
            },
        [71007112] = {
            ["Content"] = "这样啊，那就没办法了，毕竟那孩子比我更需要嘛，辛苦你啦。",
            ["ContentJP"] = "なるほど、そういうことなら仕方ないね。あの子のほうが、きっと必要なんだろう。ありがとう、おつかれさま。",
            ["DialogueId"] = 71007112,
            ["GUID"] = "B1C24450",
            ["SpeakNpcId"] = 818069,
            },
        [71007113] = {
            ["Content"] = "抱歉，我答应了别人。",
            ["ContentJP"] = "ごめん、他の人に譲っちゃった。",
            ["DialogueId"] = 71007113,
            ["GUID"] = "B1C2447A",
            ["NextDialogue"] = 710071131,
            ["SpeakNpcId"] = 100001,
            },
        [71007114] = {
            ["Content"] = "回来了回来了，吃的在哪呢？",
            ["ContentJP"] = "お帰り、お菓子はどこだい？",
            ["DialogueId"] = 71007114,
            ["GUID"] = "B1C244A4",
            ["NextDialogue"] = 71007115,
            ["SpeakNpcId"] = 818069,
            },
        [71007115] = {
            ["Content"] = "给你。",
            ["ContentJP"] = "はい、どうぞ。",
            ["DialogueId"] = 71007115,
            ["GUID"] = "B1C244CE",
            ["NextDialogue"] = 71007116,
            ["SpeakNpcId"] = 100001,
            },
        [71007116] = {
            ["Content"] = "嗯～真香！辛苦你啦，来来来，这是你的报酬。",
            ["ContentJP"] = "うん～いい香り！ありがとう、おつかれさま。はい、これはお礼。",
            ["DialogueId"] = 71007116,
            ["GUID"] = "B1C244F8",
            ["SpeakNpcId"] = 818069,
            },
        [71007201] = {
            ["Content"] = "嗯……到底选哪家好呢……",
            ["ContentJP"] = "うーん……どっちにしようかな……",
            ["DialogueId"] = 71007201,
            ["GUID"] = "B1C252EA",
            ["SpeakNpcId"] = 818074,
            },
        [71007203] = {
            ["Content"] = "啊呀，这位朋友来得正好。我每次买东西都拿不定主意，能拜托你帮我看看，给点建议吗？",
            ["ContentJP"] = "あら、ちょうどよかった。私、いつもこういうとき優柔不断で決められなくて。ねえ、ちょっと見てきて、どっちがよさそうか教えてもらえる？",
