  { MinKey = 71007206, MaxKey = 72003001, Loader = function()
      return {
        [71007206] = {
            ["Content"] = "我这可都是从原产地千里迢迢运输回来的高档货，更有百年春官方认证。虽说贵了些，但一分钱绝对对得起一分货。",
            ["ContentJP"] = "うちは産地直送、百年春の公式認証もついてる高級品だよ。確かに少し値は張るけど、その価値は保証済みなのさ。",
            ["DialogueId"] = 71007206,
            ["GUID"] = "B1C253BC",
            ["SpeakNpcId"] = 818072,
            },
        [71007207] = {
            ["Content"] = "都是日用品，高不高档有啥区别。还是我这便宜实惠的性价比更高，你说对吧。",
            ["ContentJP"] = "日用品なんて、高級とか関係ないだろ？うちのは安くて量も多い、コスパ重視なら断然こっちさ。そう思わないかい？",
            ["DialogueId"] = 71007207,
