            ["SpeakNpcId"] = 818073,
            },
        [71007208] = {
            ["Content"] = "（仔细确认之后，你已经做出了选择。现在去给那位纠结的旅人提供你的宝贵建议吧。）",
            ["ContentJP"] = "しっかり見比べたあなたは、判断を下した。あの旅人のもとへ戻り、意見を伝えよう。",
            ["DialogueId"] = 71007208,
            ["GUID"] = "B1C25410",
            ["SpeakNpcId"] = 800006,
            },
        [71007209] = {
            ["Content"] = "怎么样，你觉得哪家卖的更好？",
            ["ContentJP"] = "どうだった？どっちの店のほうがよさそう？",
            ["DialogueId"] = 71007209,
            ["GUID"] = "B1C2543A",
            ["NextOptions"] = {
                [1] = 710072091,
                [2] = 710072092,
                },
            ["SpeakNpcId"] = 818074,
            ["bForbidSkipOptions"] = true,
            },
        [71007210] = {
            ["Content"] = "好，那就买他的吧！谢谢你！",
            ["ContentJP"] = "じゃあ、そっちにする！ありがとう、助かった！",
            ["DialogueId"] = 71007210,
            ["GUID"] = "B1C25464",
            ["SpeakNpcId"] = 818074,
            },
        [71007301] = {
            ["Content"] = "（游荡的敌人挤满了四周，先击退它们，再去解救魔灵吧。）",
            ["ContentJP"] = "あたりは敵で埋め尽くされている。やつらを退治してから、ジェネモンの救出に移ろう。",
            ["DialogueId"] = 71007301,
            ["GUID"] = "B1C26352",
            ["SpeakNpcId"] = 800006,
            },
        [71007302] = {
            ["Content"] = "（争斗的声响引来了更多敌人。）",
            ["ContentJP"] = "争いの音に、さらに多くの敵が引き寄せられてしまった。",
            ["DialogueId"] = 71007302,
            ["GUID"] = "B1C2637C",
            ["SpeakNpcId"] = 800006,
            },
        [71007303] = {
            ["Content"] = "（附近暂时安全了，趁现在解救魔灵吧。）",
            ["ContentJP"] = "付近はひとまず安全だ。今のうちに、ジェネモンを救出しよう。",
            ["DialogueId"] = 71007303,
            ["GUID"] = "B1C263A6",
            ["SpeakNpcId"] = 800006,
            },
        [71007401] = {
            ["Content"] = "（应天尉来袭，击退他们！）",
            ["DialogueId"] = 71007401,
            ["GUID"] = "B1C273BA",
            ["SpeakNpcId"] = 800006,
            },
        [71007501] = {
            ["Content"] = "别抢了别抢了，都被你们抢完了我还卖什么啊！有没有人来帮帮我！",
            ["ContentJP"] = "もうやめてくれ！全部持っていかれたら、俺は何を売ればいいんだよ！誰か、誰か助けてくれ！",
            ["DialogueId"] = 71007501,
            ["GUID"] = "B1C28422",
            ["SpeakNpcId"] = 818078,
            },
        [71007502] = {
            ["Content"] = "（靠近之后，你发现了一名颓废的男子蹲坐在地上，在他身旁是散落一地的土豆丝。）",
            ["ContentJP"] = "（近づくと、やつれた男が地面にしゃがみ込み、周囲にはジャガイモの千切りが散乱している。）",
            ["DialogueId"] = 71007502,
            ["GUID"] = "B1C2844C",
            ["NextDialogue"] = 71007503,
            ["SpeakNpcId"] = 800006,
            },
        [71007503] = {
            ["Content"] = "这位外乡人，我一眼就看出你身手不凡了，帮帮忙吧。",
            ["ContentJP"] = "あ、あんた、ひと目で分かるよ……只者じゃないだろ。頼む、手を貸してくれ。",
            ["DialogueId"] = 71007503,
            ["GUID"] = "B1C28476",
            ["NextOptions"] = {
                [1] = 710075031,
                [2] = 710075032,
                },
            ["SpeakNpcId"] = 818078,
            },
        [71007504] = {
            ["Content"] = "多谢多谢。事情是这样的，每次我往摊子上摆点土豆丝，港口周围那些云翎鸥就跟疯了一样冲过来哄抢，就像这样……",
            ["ContentJP"] = "ありがとう、本当にありがとうよ。事情はこうなんだ。俺が港でジャガイモの千切りを出すたびに、周りのクモハネカモメが狂ったように群がってきて奪っていくんだ。ほら、見てくれ……",
            ["DialogueId"] = 71007504,
            ["GUID"] = "B1C284A0",
            ["SpeakNpcId"] = 818078,
            },
        [71007505] = {
            ["Content"] = "（男子说罢，从怀里颤巍巍地捡起几条土豆丝拿在手上，顿时几只云翎鸥就扇着翅膀在周围盘旋了起来。）",
            ["ContentJP"] = "（男が震える手で何本か拾い上げると、たちまち数羽のクモハネカモメが羽ばたきながら周囲を旋回し始めた。）",
            ["DialogueId"] = 71007505,
            ["GUID"] = "B1C284CA",
            ["SpeakNpcId"] = 800006,
            },
        [71007506] = {
            ["Content"] = "呃啊啊啊……你看你看，它们来了！快帮我赶走它们吧……",
            ["ContentJP"] = "うわあああ……見てくれ、来たぞ！頼む、追い払ってくれ！",
            ["DialogueId"] = 71007506,
            ["GUID"] = "B1C284F4",
            ["NextDialogue"] = 71007507,
            ["SpeakNpcId"] = 818078,
            },
        [71007507] = {
            ["Content"] = "（这些云翎鸥盘旋在四周久久不愿离去，稍有机会就朝男子飞近一些。就好像它们存在的意义就是土豆丝，活着的目标就是从男子手上抢走土豆丝一样。）",
            ["ContentJP"] = "（クモハネカモメたちはなかなか離れず、隙あらば男へと近づいてくる。まるで彼らの生きる理由がジャガイモの千切りを奪うことであるかのように。）",
            ["DialogueId"] = 71007507,
            ["GUID"] = "B1C2851E",
            ["SpeakNpcId"] = 800006,
            },
        [71007508] = {
            ["Content"] = "没想到你出手如此果断，在下佩服佩服。",
