            ["GUID"] = "B1C2851F",
            ["NextDialogue"] = 71007509,
            ["SpeakNpcId"] = 818078,
            },
        [71007509] = {
            ["Content"] = "呼……在码头卖土豆真是太危险了。谢谢，谢谢啊……",
            ["ContentJP"] = "はあ……港でジャガイモ売るなんて命がけだよ。ありがとう、助かった……",
            ["DialogueId"] = 71007509,
