            ["SpeakNpcId"] = 818078,
            },
        [71007510] = {
            ["Content"] = "还好你把它们赶走了，希望能消停一段时间。",
            ["DialogueId"] = 71007510,
            ["GUID"] = "B1C28549",
            ["NextDialogue"] = 71007511,
            ["SpeakNpcId"] = 818078,
            },
        [71007511] = {
            ["Content"] = "呼……在码头卖土豆真是太危险了。谢谢，谢谢啊……",
            ["DialogueId"] = 71007511,
            ["GUID"] = "B1C2855A",
            ["SpeakNpcId"] = 818078,
            },
        [71007601] = {
            ["Content"] = "今天怎么回事，这么久了一条鱼都没上钩。",
            ["DialogueId"] = 71007601,
            ["GUID"] = "B1C2948A",
            ["SpeakNpcId"] = 818079,
            },
        [71007602] = {
            ["Content"] = "这位路过的朋友，我怀疑这地方今天根本没有鱼，你能不能帮我试试？",
            ["DialogueId"] = 71007602,
            ["GUID"] = "B1C294B4",
            ["NextOptions"] = {
                [1] = 710076021,
                [2] = 710076022,
                },
            ["SpeakNpcId"] = 818079,
            ["bForbidSkipOptions"] = true,
            },
        [71007603] = {
            ["Content"] = "好，拜托你了。",
            ["ContentJP"] = "ああ、頼んだよ。",
            ["DialogueId"] = 71007603,
            ["GUID"] = "B1C294DE",
            ["SpeakNpcId"] = 818079,
            },
        [71007604] = {
            ["Content"] = "太厉害了，一下就钓上来了。看来不是水域的问题。",
            ["DialogueId"] = 71007604,
            ["GUID"] = "B1C29508",
            ["NextDialogue"] = 71007605,
            ["SpeakNpcId"] = 818079,
            },
        [71007605] = {
            ["Content"] = "谢谢你帮我验证了一下哈，我自己再试试看。今天绝对不能再提着空桶回去了！",
            ["DialogueId"] = 71007605,
            ["GUID"] = "B1C29532",
            ["SpeakNpcId"] = 818079,
            },
        [71007701] = {
            ["Content"] = "奇怪，到底掉到哪里去了……",
            ["DialogueId"] = 71007701,
            ["GUID"] = "B1C2A4F2",
            ["SpeakNpcId"] = 818080,
            },
        [71007702] = {
            ["Content"] = "请问你有在附近看到我掉的箱子吗？就普普通通的一个箱子，我找了半天都没找到。",
            ["DialogueId"] = 71007702,
            ["GUID"] = "B1C2A51C",
            ["NextOptions"] = {
                [1] = 710077021,
                [2] = 710077022,
                },
            ["SpeakNpcId"] = 818080,
            ["bForbidSkipOptions"] = true,
            },
        [71007703] = {
            ["Content"] = "谢谢，我在上面这块再找找，麻烦你去下面看看吧。",
            ["DialogueId"] = 71007703,
            ["GUID"] = "B1C2A546",
            ["SpeakNpcId"] = 818080,
            },
        [71007704] = {
            ["Content"] = "咦，看你在找什么东西的样子，是这些箱子吗？",
            ["DialogueId"] = 71007704,
            ["GUID"] = "B1C2A570",
            ["SpeakNpcId"] = 818081,
            },
        [71007705] = {
            ["Content"] = "我在勘探河水数据的时候捡到了这几个箱子，你看看有你在找的吗？",
            ["DialogueId"] = 71007705,
            ["GUID"] = "B1C2A59A",
            ["NextOptions"] = {
                [1] = 710077051,
                [2] = 710077052,
                [3] = 710077053,
                [4] = 710077054,
                },
            ["SpeakNpcId"] = 818081,
            },
        [71007706] = {
            ["Content"] = "好，那你就拿去吧。",
            ["ContentJP"] = "ありがとう、それが{性别:僕|私}の落とした宝箱だ",
            ["DialogueId"] = 71007706,
            ["GUID"] = "B1C2A5C4",
            ["SpeakNpcId"] = 818081,
            },
        [71007707] = {
            ["Content"] = "没错没错，就是这个，太谢谢你了。",
            ["ContentJP"] = "これが報酬だ。",
            ["DialogueId"] = 71007707,
            ["GUID"] = "B1C2A5EE",
            ["SpeakNpcId"] = 818080,
            },
        [71007708] = {
            ["Content"] = "这明显不是我掉的普通箱子，不过还是谢谢你了。",
            ["ContentJP"] = "この箱は豪華すぎる。絶対、{性别:僕|私}のじゃない",
            ["DialogueId"] = 71007708,
            ["GUID"] = "B1C2A618",
            ["SpeakNpcId"] = 818080,
            },
        [71007710] = {
            ["Content"] = "哇，没想到你找到了这么多箱子呀，那我就先拿走我掉的普通箱子了哈，谢谢你！",
            ["ContentJP"] = "うわ……こんなに見つけてきたのか",
            ["DialogueId"] = 71007710,
            ["GUID"] = "B1C2A66C",
            ["SpeakNpcId"] = 818080,
            },
        [71007712] = {
            ["Content"] = "（附近没看到什么箱子，再去其他地方找找。）",
            ["DialogueId"] = 71007712,
            ["GUID"] = "B1C2A6C0",
            ["SpeakNpcId"] = 800006,
            },
        [71007801] = {
            ["Content"] = "香……点燃……请……",
            ["ContentJP"] = "そこの月狩り人、ちょっと来てくれないか",
            ["DialogueId"] = 71007801,
            ["GUID"] = "B1C2B55A",
            ["SpeakNpcId"] = 818082,
            },
        [71007802] = {
            ["Content"] = "那边……请……点燃……谢谢……",
            ["ContentJP"] = "新しい香を開発したんだ。潜在意識を呼び覚ます効果がある。少し協力してくれないか？見えたものを教えてほしい。",
            ["DialogueId"] = 71007802,
            ["GUID"] = "B1C2B584",
            ["NextOptions"] = {
                [1] = 710078021,
                [2] = 710078022,
                },
            ["SpeakNpcId"] = 818082,
            ["bForbidSkipOptions"] = true,
            },
        [71007803] = {
            ["Content"] = "焚香……好……",
            ["ContentJP"] = "よし、あそこの香炉に火をつけてくれ",
            ["DialogueId"] = 71007803,
            ["GUID"] = "B1C2B5AE",
            ["SpeakNpcId"] = 818082,
            },
        [71007805] = {
            ["Content"] = "（点燃香炉之后，四周顿时弥漫起了浓厚的烟雾，透过这些烟雾，你似乎看到了什么东西？）",
            ["ContentJP"] = "（胸の内にひとつの問いが浮かぶ──今、あなたが最も願うことは？）",
            ["DialogueId"] = 71007805,
            ["GUID"] = "B1C2B602",
            ["NextOptions"] = {
                [1] = 710078051,
                [2] = 710078052,
                [3] = 710078053,
                },
            ["SpeakNpcId"] = 800006,
            ["bForbidSkipOptions"] = true,
            },
        [71007806] = {
            ["Content"] = "（朦胧的雾气中，你看到了数之不尽的宝箱，打开它们吧。）",
            ["ContentJP"] = "（宝箱が周囲に現れた）",
            ["DialogueId"] = 71007806,
            ["GUID"] = "B1C2B62C",
            ["SpeakNpcId"] = 800006,
            },
        [71007807] = {
            ["Content"] = "（烟雾散去，方才见到的一切也随之消散。回去问问无由生是怎么回事吧。）",
            ["ContentJP"] = "（ムユウセイに今の出来事を報告しよう）",
            ["DialogueId"] = 71007807,
            ["GUID"] = "B1C2B656",
            ["SpeakNpcId"] = 100001,
            },
        [71007808] = {
            ["Content"] = "焚香……再见……",
            ["ContentJP"] = "なるほど……そう見えたのか。協力、感謝するよ",
            ["DialogueId"] = 71007808,
            ["GUID"] = "B1C2B680",
            ["SpeakNpcId"] = 818082,
            },
        [71007809] = {
            ["Content"] = "（朦胧的雾气中，你看到了大量敌人，击败它们吧。）",
            ["ContentJP"] = "（敵が周囲に現れた）",
            ["DialogueId"] = 71007809,
            ["GUID"] = "B1C2B6AA",
            ["SpeakNpcId"] = 800006,
            },
        [71007810] = {
            ["Content"] = "（烟雾散去，方才见到的一切也随之消散。回去问问无由生是怎么回事吧。）",
            ["ContentJP"] = "（ムユウセイに今の出来事を報告しよう）",
            ["DialogueId"] = 71007810,
            ["GUID"] = "B1C2B6D4",
            ["SpeakNpcId"] = 100001,
            },
        [71007811] = {
            ["Content"] = "焚香……再见……",
            ["ContentJP"] = "なるほど……そう見えたのか。協力、感謝するよ",
            ["DialogueId"] = 71007811,
            ["GUID"] = "B1C2B6FE",
            ["SpeakNpcId"] = 818082,
            },
        [71007812] = {
            ["Content"] = "（朦胧的雾气中，你看到了贝蕾妮卡的身影。）",
            ["ContentJP"] = "（ベレが目の前に現れた）",
            ["DialogueId"] = 71007812,
            ["GUID"] = "B1C2B728",
            ["NextDialogue"] = 71007813,
            ["SpeakNpcId"] = 800006,
            },
        [71007813] = {
            ["Content"] = "（伸手触碰，贝蕾的身影开始变得模糊不清。你知道，她只是焚香之后出现的幻影。）",
            ["ContentJP"] = "（ベレとの会話・仮置き）",
            ["DialogueId"] = 71007813,
            ["GUID"] = "B1C2B752",
            ["SpeakNpcId"] = 800006,
            },
        [71007814] = {
            ["Content"] = "（烟雾散去，方才见到的一切也随之消散。回去问问无由生是怎么回事吧。）",
            ["ContentJP"] = "（ムユウセイに今の出来事を報告しよう）",
            ["DialogueId"] = 71007814,
            ["GUID"] = "B1C2B77C",
            ["SpeakNpcId"] = 100001,
            },
        [71007815] = {
            ["Content"] = "焚香……再见……",
            ["ContentJP"] = "なるほど……そう見えたのか。協力、感謝するよ",
            ["DialogueId"] = 71007815,
            ["GUID"] = "B1C2B7A6",
            ["SpeakNpcId"] = 818082,
            },
        [71007816] = {
            ["Content"] = "（一个香炉不知何时出现在了你的背后，这只无由生看起来很希望你能点燃它。）",
            ["DialogueId"] = 71007816,
            ["GUID"] = "B1C2B7A7",
            ["SpeakNpcId"] = 800006,
            },
        [71007901] = {
            ["Content"] = "救救我啊，我还没找到爸爸埋的宝藏，我不要死在这里哇……",
            ["DialogueId"] = 71007901,
            ["GUID"] = "B1C2C5C2",
            ["SpeakNpcId"] = 818083,
            },
        [71007905] = {
            ["Content"] = "谢谢你救了我，但我没什么好东西能够报答你……对了，我这有一张爸爸留下的藏宝图，要是你能找到宝藏，它们就归你了！",
            ["ContentJP"] = "（彼の無邪気な顔を見て、あなたは──）",
            ["DialogueId"] = 71007905,
            ["GUID"] = "B1C2C66A",
            ["NextOptions"] = {
                [1] = 710079051,
                [2] = 710079052,
                },
            ["SpeakNpcId"] = 818083,
            },
        [71007906] = {
            ["Content"] = "好厉害，一眼就看出来了！那快去把它挖出来吧。",
            ["DialogueId"] = 71007906,
            ["GUID"] = "B1C2C694",
            ["SpeakNpcId"] = 818083,
            },
        [71007907] = {
            ["Content"] = "好，按照约定，这些宝藏从现在开始就归你啦，谢谢你刚才救了我。",
            ["DialogueId"] = 71007907,
            ["GUID"] = "B1C2C6BE",
            ["SpeakNpcId"] = 818083,
            },
        [71007908] = {
            ["Content"] = "这怎么好意思呀……那，那我给你拿点其他小礼物吧，谢谢你刚才救了我。",
            ["DialogueId"] = 71007908,
            ["GUID"] = "B1C2C6E8",
            ["SpeakNpcId"] = 818083,
            },
        [71008001] = {
            ["Content"] = "那边那位外乡人，对对就是叫你呢，能不能来帮我个忙。",
            ["DialogueId"] = 71008001,
            ["GUID"] = "B1C2D62A",
            ["SpeakNpcId"] = 818084,
            },
        [71008002] = {
            ["Content"] = "我店里有个伙计最近总是偷偷跑出去跟隔壁店主碰面，我怀疑是想对我的店动什么手脚。能帮我去找点证据吗？",
            ["DialogueId"] = 71008002,
            ["GUID"] = "B1C2D654",
            ["NextOptions"] = {
                [1] = 710080021,
                [2] = 710080022,
                },
            ["SpeakNpcId"] = 818084,
            },
        [71008003] = {
            ["Content"] = "好，他们应该就在附近，全交给你了，我就不过去打草惊蛇了。",
            ["DialogueId"] = 71008003,
            ["GUID"] = "B1C2D67E",
            ["SpeakNpcId"] = 818084,
            },
        [71008004] = {
            ["Content"] = "只是把秘方拿出来给我看一眼而已，不会有什么风险的。",
            ["DialogueId"] = 71008004,
            ["GUID"] = "B1C2D6A8",
            ["NextDialogue"] = 71008005,
            ["SpeakNpcId"] = 818086,
            },
        [71008005] = {
            ["Content"] = "我……",
            ["DialogueId"] = 71008005,
            ["GUID"] = "B1C2D6D2",
            ["NextDialogue"] = 71008006,
            ["SpeakNpcId"] = 818085,
            },
        [71008006] = {
            ["Content"] = "事成之后分你三成，怎么样？",
            ["DialogueId"] = 71008006,
            ["GUID"] = "B1C2D6FC",
            ["NextDialogue"] = 71008007,
            ["SpeakNpcId"] = 818086,
            },
        [71008007] = {
            ["Content"] = "……",
            ["DialogueId"] = 71008007,
            ["GUID"] = "B1C2D726",
            ["NextDialogue"] = 71008008,
            ["SpeakNpcId"] = 818085,
            },
        [71008008] = {
            ["Content"] = "还不行，那就干脆……等等，你是不是听到什么了，过来过来。",
            ["DialogueId"] = 71008008,
            ["GUID"] = "B1C2D750",
            ["SpeakNpcId"] = 818086,
            },
        [71008009] = {
            ["Content"] = "这笔钱你拿着，刚才我们俩的对话你就当没听到如何。",
            ["DialogueId"] = 71008009,
            ["GUID"] = "B1C2D77A",
            ["SpeakNpcId"] = 818086,
            },
        [71008010] = {
            ["Content"] = "（男子给你的这笔钱无疑就是他们在酝酿什么阴谋的证据，现在可以直接回去交差，揭露二人的阴谋，或是藏在附近，继续听听这二人的对话。）",
            ["DialogueId"] = 71008010,
            ["GUID"] = "B1C2D7A4",
            ["SpeakNpcId"] = 100001,
            },
        [71008011] = {
            ["Content"] = "四成，给个痛快话，到底行不行啊，拖了我好几天了。",
            ["DialogueId"] = 71008011,
            ["GUID"] = "B1C2D7CE",
            ["NextDialogue"] = 71008012,
            ["SpeakNpcId"] = 818086,
            },
        [71008012] = {
            ["Content"] = "对，对不起。店主于我有恩，我不能帮你做这种事。",
            ["DialogueId"] = 71008012,
            ["GUID"] = "B1C2D7F8",
            ["NextDialogue"] = 71008013,
            ["SpeakNpcId"] = 818085,
            },
        [71008013] = {
            ["Content"] = "（你成功躲过二人的注意，了解到了伙计真正的选择，现在回去向店主揭露真相吧。）",
            ["DialogueId"] = 71008013,
            ["GUID"] = "B1C2D822",
            ["SpeakNpcId"] = 100001,
            },
        [71008014] = {
            ["Content"] = "哈哈，果然是我想得那样！等我家伙计回来我就让他滚蛋。",
            ["DialogueId"] = 71008014,
            ["GUID"] = "B1C2D84C",
            ["SpeakNpcId"] = 818084,
            },
        [71008015] = {
            ["Content"] = "原来是这样，差点错怪我家伙计了，谢谢你啊。",
            ["DialogueId"] = 71008015,
            ["GUID"] = "B1C2D876",
            ["SpeakNpcId"] = 818084,
            },
        [71008101] = {
            ["Content"] = "今天就差最后一圈了，大家再坚持一下！",
            ["DialogueId"] = 71008101,
            ["GUID"] = "B1C2E692",
            ["SpeakNpcId"] = 818087,
            },
        [71008102] = {
            ["Content"] = "要想成为织星客，脚力也是很重要的！你要不要跟我一起监督他们跑完今天的最后一圈呀？",
            ["DialogueId"] = 71008102,
            ["GUID"] = "B1C2E6BC",
            ["NextOptions"] = {
                [1] = 710081021,
                [2] = 710081022,
                },
            ["SpeakNpcId"] = 818087,
            },
        [71008103] = {
            ["Content"] = "好，你来选一个人监督就好，选好了告诉我哦。",
            ["DialogueId"] = 71008103,
            ["GUID"] = "B1C2E6E6",
            ["SpeakNpcId"] = 818087,
            },
        [71008104] = {
            ["Content"] = "怎么样，想好要监督谁了吗？",
            ["DialogueId"] = 71008104,
            ["GUID"] = "B1C2E710",
            ["NextOptions"] = {
                [1] = 710081041,
                [2] = 710081042,
                [3] = 710081043,
                },
            ["SpeakNpcId"] = 818087,
            },
        [71008105] = {
            ["Content"] = "没问题，我会好好盯着剩下两个人的！",
            ["DialogueId"] = 71008105,
            ["GUID"] = "B1C2E73A",
            ["SpeakNpcId"] = 818087,
            },
        [71008106] = {
            ["Content"] = "最后冲刺了！加油加油，不可以慢慢走哦！",
            ["DialogueId"] = 71008106,
            ["Duration"] = 1,
            ["GUID"] = "B1C2E7E2",
            ["SpeakNpcId"] = 818087,
            },
        [71008110] = {
            ["Content"] = "有你在一边盯着，他虽然跑得很慢，但还是坚持到最后了，真厉害！今天真是谢谢你啦，这是我们的一点小小心意。",
            ["DialogueId"] = 71008110,
            ["GUID"] = "B1C2E80C",
            ["SpeakNpcId"] = 818087,
            },
        [71008111] = {
            ["Content"] = "有你在一边盯着，他居然能跑这么快呀，真厉害！今天真是谢谢你啦，这是我们的一点小小心意。",
            ["DialogueId"] = 71008111,
            ["GUID"] = "B1C2E836",
            ["SpeakNpcId"] = 818087,
            },
        [71008201] = {
            ["Content"] = "（附近生长着不少山瑚，若是有空，不妨收集一些吧。）",
            ["ContentJP"] = "近くに山瑚がたくさん生えている。時間があるなら、いくつか採集しておこう。",
            ["DialogueId"] = 71008201,
            ["GUID"] = "B1C2F6FA",
            ["SpeakNpcId"] = 800006,
            },
        [71008202] = {
            ["Content"] = "（收集山瑚的响动将周围的敌人吸引了过来，击退它们吧。）",
            ["ContentJP"] = "山瑚を採集する音で周囲の敵が引き寄せられた。撃退しよう。",
            ["DialogueId"] = 71008202,
            ["GUID"] = "B1C2F724",
            ["SpeakNpcId"] = 800006,
            },
        [71008203] = {
            ["Content"] = "（虽然出现了一点小意外，但最后总算是顺利收集完了附近的所有山瑚。）",
            ["ContentJP"] = "ちょっとしたアクシデントはあったが、最後には近くの山瑚をすべて無事に採集できた。",
            ["DialogueId"] = 71008203,
            ["GUID"] = "B1C2F74E",
            ["SpeakNpcId"] = 800006,
            },
        [71008204] = {
            ["Content"] = "（成功收集完了附近的所有山瑚，是时候离开了。）",
            ["ContentJP"] = "近くの山瑚の採集が完了した。そろそろ離れよう。",
            ["DialogueId"] = 71008204,
            ["GUID"] = "B1C2F778",
            ["SpeakNpcId"] = 800006,
            },
        [71008301] = {
            ["Content"] = "（坍塌的碎石挡住了前路，将它们清理掉吧。）",
            ["ContentJP"] = "崩れ落ちた瓦礫が道を塞いでいる。片づけて道を開こう。",
            ["DialogueId"] = 71008301,
            ["GUID"] = "B1C30762",
            ["SpeakNpcId"] = 800006,
            },
        [71008302] = {
            ["Content"] = "（清理碎石的响动将周围的敌人吸引了过来，击退它们吧。）",
            ["ContentJP"] = "瓦礫を片付ける音で周囲の敵が引き寄せられた。撃退しよう。",
            ["DialogueId"] = 71008302,
            ["GUID"] = "B1C3078C",
            ["SpeakNpcId"] = 800006,
            },
        [71008303] = {
            ["Content"] = "（一番战斗后，你在周围找到了些能用的物资，将它们收好吧。）",
            ["ContentJP"] = "戦闘のあと、周囲で使えそうな物資を見つけた。回収しておこう。",
            ["DialogueId"] = 71008303,
            ["GUID"] = "B1C307B6",
            ["SpeakNpcId"] = 800006,
            },
        [71008401] = {
            ["Content"] = "（游荡的秽兽徘徊在附近，先击退它们，再去解救魔灵吧。）",
            ["DialogueId"] = 71008401,
            ["GUID"] = "B1C317CA",
            ["SpeakNpcId"] = 800006,
            },
        [71008402] = {
            ["Content"] = "（争斗的声响引来了更多秽兽。）",
            ["DialogueId"] = 71008402,
            ["GUID"] = "B1C317F4",
            ["SpeakNpcId"] = 800006,
            },
        [71008403] = {
            ["Content"] = "（这里暂时安全了，趁现在解救魔灵吧。）",
            ["DialogueId"] = 71008403,
            ["GUID"] = "B1C3181E",
            ["SpeakNpcId"] = 800006,
            },
