            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F1794",
            ["NextDialogue"] = 72000803,
            ["SpeakNpcId"] = 820000,
            },
        [72000803] = {
            ["Content"] = "一个士兵会平安……",
            ["ContentJP"] = "一人だけ無事だった……",
