            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72000902] = {
            ["Content"] = "这样一来，就没有人朝着不同方向坐了。",
            ["ContentJP"] = "これで、みんな同じ向きに座ることになるね。",
            ["DialogueId"] = 72000902,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F27FC",
            ["NextDialogue"] = 72000903,
            ["SpeakNpcId"] = 820000,
            },
        [72000903] = {
            ["Content"] = "不用担心腿太长，然后撞到。",
            ["ContentJP"] = "足が長すぎてぶつかる心配もないよ。",
            ["DialogueId"] = 72000903,
            ["FacialId"] = {
