            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
            ["bAllowClickSkipScript"] = false,
            },
        [72001002] = {
            ["Content"] = "墙说，它能挡住它想挡住的东西。",
            ["ContentJP"] = "壁が言ってたよ。「邪魔したいものは止める」って。",
            ["DialogueId"] = 72001002,
            ["FacialId"] = {
                [1] = "820000:PetPan_Common",
                },
            ["GUID"] = "B43F3864",
            ["NextDialogue"] = 72001003,
            ["SpeakNpcId"] = 820000,
            },
        [72001003] = {
            ["Content"] = "但是如果它不想挡住的东西，都会放进城里！",
            ["ContentJP"] = "けど、通したいものは、城の中に入れてあげるんだとも言ってた。",
            ["DialogueId"] = 72001003,
