            ["FacialId"] = {
                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47EDBCC",
            ["NextDialogue"] = 72100303,
            ["SpeakNpcId"] = 830001,
            },
        [72100303] = {
            ["Content"] = "唔……比起被太阳抓住，还不如被你抓住……",
            ["ContentJP"] = "ううん……太陽に捕まるより、あなたに捕まっていたほうがましだ……",
