                },
            ["GUID"] = "B47F0D04",
            ["NextDialogue"] = 72100603,
            ["SpeakNpcId"] = 830001,
            },
        [72100603] = {
            ["Content"] = "那要爬多久呢？十年，一百年，够不够呢？",
            ["ContentJP"] = "どのくらい登ればいいんでしょう？十年、百年……足りるでしょうか？",
