            ["SpeakNpcId"] = 830001,
            },
        [72100703] = {
            ["Content"] = "等等，原来我没有牙齿吗？那这种战栗的感觉是……",
            ["ContentJP"] = "待って、私に歯なんてあったっけ？じゃあこの震えは…？",
