            ["Scripts"] = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}",
            },
        [72100802] = {
            ["Content"] = "我以前总来这里看天空，好像可以从云层后面望见我自己。",
            ["ContentJP"] = "昔はよくここに来て空を見上げていた。雲の向こうに自分が見えるような気がしてね。",
