                [1] = "830001:PetPan_Common",
                },
            ["GUID"] = "B47F2DD4",
            ["NextDialogue"] = 72100803,
            ["SpeakNpcId"] = 830001,
            },
        [72100803] = {
            ["Content"] = "现在不用看啦，毕竟我再也看不到我自己啦~",
