            ["NextDialogue"] = 72101003,
            ["SpeakNpcId"] = 830001,
            },
        [72101003] = {
            ["Content"] = "还好有你为我指明方向。谢谢你，远道而来的朋友。",
            ["ContentJP"] = "私に道を示してくれてありがとう、遠路はるばる来てくれた友よ。",
