        [80002001] = {
            ["Content"] = "哇，这是一座迷宫花园！",
            ["ContentJP"] = "わぁ、ここは迷宮庭園なの！",
            ["DialogueId"] = 80002001,
            ["GUID"] = "C846D04A",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002002,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D04A",
            },
        [80002002] = {
            ["Content"] = "独角兽{性别：先生|小姐}会藏在哪里呢？",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}はどこに隠れてるのかな......",
            ["DialogueId"] = 80002002,
            ["GUID"] = "C846D074",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D074",
            },
        [80002003] = {
            ["Content"] = "嗯？没有反应……也许是需要用和它相同的颜色来画？",
            ["ContentJP"] = "あれ？反応が全く出てこない......同じ色で描かないとだめなのかな？",
            ["DialogueId"] = 80002003,
            ["GUID"] = "C846D09E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D09E",
            },
        [80002004] = {
            ["Content"] = "我还没有其他的颜料，去迷宫里找找看吧。",
            ["ContentJP"] = "フィーナの手元にはまだほかの絵具がないの。迷宮の中で探してみよう。",
            ["DialogueId"] = 80002004,
            ["GUID"] = "C846D0C8",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D0C8",
            },
        [80002005] = {
            ["Content"] = "唔，这一侧的迷宫被锁住了，看来要按从另一侧开始解谜呀。",
            ["ContentJP"] = "うぅ......こっちがロックされてるみたい。そっちから謎解きしなきゃならないね。",
            ["DialogueId"] = 80002005,
            ["GUID"] = "C846D0F2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D0F2",
            },
        [80002006] = {
            ["Content"] = "独角兽{性别：先生|小姐}曾经为了躲避怪兽，和家人一起躲在狭窄的山洞里……",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}が化け物から逃れるため、家族と一緒に狭い洞穴に隠れてて......",
            ["DialogueId"] = 80002006,
            ["GUID"] = "C846D11C",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D11C",
            },
        [80002007] = {
            ["Content"] = "后来，{性别：他们|她们}勇敢地拿起武器，与怪兽对抗。",
            ["ContentJP"] = "その後、{性别:彼ら|彼女たち}は勇気を出して武器を手に取り、化け物に立ち向かった。",
            ["DialogueId"] = 80002007,
            ["GUID"] = "C846D146",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D146",
            },
        [80002008] = {
            ["Content"] = "终于，独角兽{性别：先生|小姐}和家人一起打跑了拦路的秽兽，冲出重围……",
            ["ContentJP"] = "やがて、ユニコーンの{性别:お兄さん|お姉さん}が家族と一緒に穢獣を撃退し、包囲を突破できた。",
            ["DialogueId"] = 80002008,
            ["GUID"] = "C846D170",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D170",
            },
        [80002009] = {
            ["Content"] = "却又遇到了更强大的敌人！",
            ["ContentJP"] = "でも、もっと手強い敵に出くわしたの。",
            ["DialogueId"] = 80002009,
            ["GUID"] = "C846D19A",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D19A",
            },
        [80002010] = {
            ["Content"] = "他们拼命地战斗，使出了全部的力量，却还是被迫失散了……",
            ["ContentJP"] = "命を賭けて全力で戦ったのに、家族とぐれてしまった......",
            ["DialogueId"] = 80002010,
            ["GUID"] = "C846D1C4",
            ["GuideFacialId"] = "Confident",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002011,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D1C4",
            },
        [80002011] = {
            ["Content"] = "希望独角兽{性别：先生|小姐}能早一点找回重要的家人。",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}が、一刻も早く大事な家族に会えるように。",
            ["DialogueId"] = 80002011,
            ["GUID"] = "C846D1EE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D1EE",
            },
        [80002012] = {
            ["Content"] = "来到寒冰的国度之后，独角兽{性别：先生|小姐}遇到了新的伙伴，展开了一次次精彩的冒险。",
            ["ContentJP"] = "氷の国についた後、ユニコーンの{性别:お兄さん|お姉さん}は新しい友達を作り、素晴らしい冒険を次々と経験してきたの。",
            ["DialogueId"] = 80002012,
            ["GUID"] = "C846D218",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D218",
            },
        [80002013] = {
            ["Content"] = "嗯？水池里的圆环亮起了半边……看来我已经完成一半的谜题啦！",
            ["ContentJP"] = "あれ？池の円環、半分だけ光ってる......どうやら謎が半分解けたみたいね。",
            ["DialogueId"] = 80002013,
            ["GUID"] = "C846D242",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D242",
            },
