        [80002016] = {
            ["Content"] = "现在我有新的颜料了，试着改变它的颜色吧！",
            ["ContentJP"] = "新しい絵具を手に入れたよ。さっそく色を変えよう！",
            ["DialogueId"] = 80002016,
            ["GUID"] = "C846D2C0",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D2C0",
            },
        [80002017] = {
            ["Content"] = "这个颜色好像不对……试试看刚获得的新颜料吧。",
            ["ContentJP"] = "この色は違うようね......さっき手に入れた絵具を使ってみよう。",
            ["DialogueId"] = 80002017,
            ["GUID"] = "C846D2EA",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D2EA",
            },
        [80002018] = {
            ["Content"] = "换一种颜料试试看吧。",
            ["ContentJP"] = "ほかの絵具も試してみよう。",
            ["DialogueId"] = 80002018,
            ["GUID"] = "C846D314",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D314",
            },
        [80002019] = {
            ["Content"] = "成功了！现在可以去另一侧的迷宫探险啦。",
            ["ContentJP"] = "やった！これで向こう側の迷宮を探検できるね。",
            ["DialogueId"] = 80002019,
            ["GUID"] = "C846D33E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D33E",
            },
        [80002020] = {
            ["Content"] = "看，这里有积木！独角兽{性别：先生|小姐}曾经陪菲娜一起玩过叫做“弹壳”的积木呢。",
            ["ContentJP"] = "見て、ここに積み木がある！ユニコーンの{性别:お兄さん|お姉さん}が昔「薬莢」って積み木遊びに付き合ってくれたの。",
            ["DialogueId"] = 80002020,
            ["GUID"] = "C846D368",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D368",
            },
        [80002021] = {
            ["Content"] = "哇，是星星！好想再和独角兽{性别：先生|小姐}一起看一次真正的星空呀。",
            ["ContentJP"] = "わぁ、キラキラしてる星よ！ユニコーンの{性别:お兄さん|お姉さん}ともう一度本物の星空を見たいな。",
            ["DialogueId"] = 80002021,
            ["GUID"] = "C846D392",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D392",
            },
        [80002022] = {
            ["Content"] = "这里也有宝物，是独角兽{性别：先生|小姐}通过委托得到的报酬吗？",
            ["ContentJP"] = "ここにも宝物がある。これはユニコーンの{性别:お兄さん|お姉さん}が依頼で手に入れた報酬なの？",
            ["DialogueId"] = 80002022,
            ["GUID"] = "C846D3BC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D3BC",
            },
        [80002023] = {
            ["Content"] = "又发现了宝物！独角兽{性别：先生|小姐}，这是你给菲娜的惊喜吗？",
            ["ContentJP"] = "また宝物を発見！ユニコーンの{性别:お兄さん|お姉さん}、これってフィーナにくれたサプライズなの？",
            ["DialogueId"] = 80002023,
            ["GUID"] = "C846D3E6",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D3E6",
            },
        [80002024] = {
            ["Content"] = "菲娜和独角兽{性别：先生|小姐}一起书写的故事，一定会很长很长……嗯，我希望它永远也不要结束。",
            ["ContentJP"] = "フィーナとユニコーンの{性别:お兄さん|お姉さん}が一緒に書いた物語は、きっとずっとずっと......永遠に続いていくの。",
            ["DialogueId"] = 80002024,
            ["GUID"] = "C846D410",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D410",
            },
        [80002025] = {
            ["Content"] = "另一半的圆环也被点亮了。",
            ["ContentJP"] = "円環の残り半分も灯された。",
            ["DialogueId"] = 80002025,
            ["GUID"] = "C846D43A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002026,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D43A",
            },
        [80002026] = {
            ["Content"] = "回到水池旁边，看看有没有发生什么神奇的变化吧~",
            ["ContentJP"] = "池に戻ろう、何か特別な変化が起きてないか見てみないと～",
            ["DialogueId"] = 80002026,
            ["GUID"] = "C846D464",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D464",
            },
        [80002027] = {
            ["Content"] = "哇……地板飞起来了？看来我们找到迷宫的出口啦！",
            ["ContentJP"] = "わぁ......床が浮いてる？迷宮の出口を見つけたみたい！",
            ["DialogueId"] = 80002027,
            ["GUID"] = "C846D48E",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80002028,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D48E",
            },
        [80002028] = {
            ["Content"] = "谢谢你的帮忙，独角兽{性别：先生|小姐}。你这么聪明，一定也可以帮助菲娜解开现实世界中的谜题吧？",
            ["ContentJP"] = "ありがとう、ユニコーンの{性别:お兄さん|お姉さん}。賢いユニコーンの{性别:お兄さん|お姉さん}なら、現実世界の謎だってきっと解いてくれるよね？",
            ["DialogueId"] = 80002028,
            ["GUID"] = "C846D4B8",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120112/C846D4B8",
            },
