        [80003101] = {
            ["Content"] = "好漂亮的一片湖呀~",
            ["ContentJP"] = "綺麗な湖ね～",
            ["DialogueId"] = 80003101,
            ["Duration"] = 3,
            ["GUID"] = "C84784C2",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003102,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84784C2",
            },
        [80003102] = {
            ["Content"] = "那里有一艘小船，我可以划着小船去对岸找蝴蝶小姐。",
            ["ContentJP"] = "そこに小舟があるよ、これに乗って向こう岸の蝶々さんに会いに行こう！",
            ["DialogueId"] = 80003102,
            ["Duration"] = 3,
            ["GUID"] = "C84784EC",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84784EC",
            },
        [80003103] = {
            ["Content"] = "调皮的藤蔓在和菲娜玩游戏呢！",
            ["ContentJP"] = "やんちゃな蔓がフィーナと戯れているの！",
            ["DialogueId"] = 80003103,
            ["Duration"] = 3,
            ["GUID"] = "C8478516",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003104,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8478516",
            },
        [80003104] = {
            ["Content"] = "给藤蔓涂上它喜欢的颜色，它就会让开道路啦~",
            ["ContentJP"] = "蔓ちゃんの好みの色を塗ってあげれば、きっと道を譲ってくれるよ～",
            ["DialogueId"] = 80003104,
            ["Duration"] = 3,
            ["GUID"] = "C8478540",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8478540",
            },
        [80003105] = {
            ["Content"] = "咦，这朵花儿，你怎么没有颜色呢？",
            ["ContentJP"] = "あれ、この花ちゃん、どうして色がないの？",
            ["DialogueId"] = 80003105,
            ["Duration"] = 3,
            ["GUID"] = "C847856A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003106,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847856A",
            },
        [80003106] = {
            ["Content"] = "让菲娜来给你涂一个漂亮的颜色吧！",
            ["ContentJP"] = "フィーナが綺麗に色を塗ってあげよう！",
            ["DialogueId"] = 80003106,
            ["Duration"] = 3,
            ["GUID"] = "C8478594",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8478594",
            },
        [80003107] = {
            ["Content"] = "哇——快看，藤蔓变成了一座小桥！",
            ["ContentJP"] = "わぁーーほら、蔓ちゃんが小さな橋になってるよ！",
            ["DialogueId"] = 80003107,
            ["Duration"] = 3,
            ["GUID"] = "C84785BE",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003108,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84785BE",
            },
        [80003108] = {
            ["Content"] = "这样我就可以走到对面去了。",
            ["ContentJP"] = "これで向こうに行けるね。",
            ["DialogueId"] = 80003108,
            ["Duration"] = 3,
            ["GUID"] = "C84785E8",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84785E8",
            },
        [80003109] = {
            ["Content"] = "柱子顶上有一根羽毛……小夜莺飞得可真高呀！",
            ["ContentJP"] = "柱の上に一本の羽根が......ナイチンゲールは、ずいぶん高く飛べるのね！",
            ["DialogueId"] = 80003109,
            ["Duration"] = 3,
            ["GUID"] = "C8478612",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003110,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8478612",
            },
        [80003110] = {
            ["Content"] = "如果能让柱子降下来，我就可以拿到羽毛了。",
            ["ContentJP"] = "柱を降ろせたら、羽が取れるかもしれないね。",
            ["DialogueId"] = 80003110,
            ["Duration"] = 3,
            ["GUID"] = "C847863C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847863C",
            },
        [80003111] = {
            ["Content"] = "给水盆里的水涂上颜色，看起来就像果汁一样~",
            ["ContentJP"] = "水盆の水にも色をつけて、まるでジュースみたいね～",
            ["DialogueId"] = 80003111,
            ["Duration"] = 3,
            ["GUID"] = "C8478666",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003112,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8478666",
            },
        [80003112] = {
            ["Content"] = "咦？也许水盆的颜色中藏着什么规律……",
            ["ContentJP"] = "え......？水盆の色にも何かヒントが隠れてるかもね。",
            ["DialogueId"] = 80003112,
            ["Duration"] = 3,
            ["GUID"] = "C8478690",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8478690",
            },
        [80003113] = {
            ["Content"] = "看，湖里有许多大石头。给它们涂上魔法的颜色，让它们帮菲娜搭起一座彩色的桥吧！",
            ["ContentJP"] = "ほら、湖の中にも大きな石がたくさんあるよ。石に魔法の色を付けて、フィーナに色とりどりの橋をかけてくれるようにしよう！",
            ["DialogueId"] = 80003113,
            ["Duration"] = 3,
            ["GUID"] = "C84786BA",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84786BA",
            },
        [80003114] = {
            ["Content"] = "找到小船啦。",
            ["ContentJP"] = "小舟を発見！",
            ["DialogueId"] = 80003114,
            ["Duration"] = 3,
            ["GUID"] = "C84786E4",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003115,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84786E4",
            },
        [80003115] = {
            ["Content"] = "嘟嘟嘟——“白色夜莺号”，启航！",
            ["ContentJP"] = "プープープーーー「ホワイトナイチンゲール号」、出航！",
            ["DialogueId"] = 80003115,
            ["Duration"] = 3,
            ["GUID"] = "C847870E",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847870E",
            },
