        [80003201] = {
            ["Content"] = "唔，前面的航路被藤蔓挡住了……",
            ["ContentJP"] = "う......この先の道、また蔓に塞がれちゃったよ。",
            ["DialogueId"] = 80003201,
            ["Duration"] = 3,
            ["GUID"] = "C847952A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003202,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847952A",
            },
        [80003202] = {
            ["Content"] = "下船找找有没有其他的路吧。",
            ["ContentJP"] = "そろそろ船を降りよう、別の道はないか探しに行こう。",
            ["DialogueId"] = 80003202,
            ["Duration"] = 3,
            ["GUID"] = "C8479554",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479554",
            },
        [80003203] = {
            ["Content"] = "咦，是蝴蝶小姐！你特地飞过来帮助菲娜吗，谢谢！",
            ["ContentJP"] = "あれ、蝶々さんだ！わざわざフィーナを助けに来てくれたの？ありがとう！",
            ["DialogueId"] = 80003203,
            ["Duration"] = 3,
            ["GUID"] = "C847957E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C847957E",
            },
        [80003204] = {
            ["Content"] = "圆圆的荷叶浮起来，连成了一条路呢~这样菲娜就可以走在水面上啦。",
            ["ContentJP"] = "丸っこい荷葉が水中から浮かび上がって、道を作ってくれたね～これでフィーナも水面を歩けるようになったね。",
            ["DialogueId"] = 80003204,
            ["Duration"] = 3,
            ["GUID"] = "C84795A8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795A8",
            },
        [80003205] = {
            ["Content"] = "藤蔓都消失啦，可以回去再次开动“白色夜莺号”了！",
            ["ContentJP"] = "蔓が全部消え去ったよ。「ホワイトナイチンゲール号」に戻って、船を動かそう！",
            ["DialogueId"] = 80003205,
            ["Duration"] = 3,
            ["GUID"] = "C84795D2",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795D2",
            },
        [80003206] = {
            ["Content"] = "又出现了水盆，这次它们会藏着什么机关呢？",
            ["ContentJP"] = "また水盆が.....今度はどんなトラップが仕組まれてるのかな？",
            ["DialogueId"] = 80003206,
            ["Duration"] = 3,
            ["GUID"] = "C84795FC",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003207,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C84795FC",
            },
        [80003207] = {
            ["Content"] = "也许……是和这些石柱有关？",
            ["ContentJP"] = "たぶんね......これらの石柱と何か関わりがあるの？",
            ["DialogueId"] = 80003207,
            ["Duration"] = 3,
            ["GUID"] = "C8479626",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120113/C8479626",
            },
        [80003208] = {
            ["Content"] = "蝴蝶小姐，我们成功抵达目的地啦！",
            ["ContentJP"] = "蝶々さん、目的地に無事到着したよ！",
            ["DialogueId"] = 80003208,
            ["Duration"] = 3,
            ["GUID"] = "C8479650",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80003209,
            ["SpeakNpcId"] = 700142,
