        [80004101] = {
            ["Content"] = "森林里雾好大呀！",
            ["ContentJP"] = "この森は霧が濃すぎない？",
            ["DialogueId"] = 80004101,
            ["Duration"] = 3,
            ["GUID"] = "C84828D2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004102,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84828D2",
            },
        [80004102] = {
            ["Content"] = "为了避免迷路，就沿着这条小溪前进吧。",
            ["ContentJP"] = "迷子にならないように、この小川に沿って進んでみよう。",
            ["DialogueId"] = 80004102,
            ["Duration"] = 3,
            ["GUID"] = "C84828FC",
            ["GuideFacialId"] = "Idle",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84828FC",
            },
        [80004103] = {
            ["Content"] = "咦……这些荆棘缺了一部分颜色呢。",
            ["ContentJP"] = "ええっと......これらの棘も一部色が欠けてるね。",
            ["DialogueId"] = 80004103,
            ["Duration"] = 3,
            ["GUID"] = "C8482926",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004104,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482926",
            },
        [80004104] = {
            ["Content"] = "等我给空白的部分涂上颜色，也许它就会动起来啦。",
            ["ContentJP"] = "欠けているところに色を足してあげたら、動き始めるかもね。",
            ["DialogueId"] = 80004104,
            ["Duration"] = 3,
            ["GUID"] = "C8482950",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482950",
            },
        [80004105] = {
            ["Content"] = "小夜莺，你怎么待在里面不出来呀？是这些荆棘把你困住了吗？",
            ["ContentJP"] = "ナイチンゲール、どうして出てこないの？棘に囚われてるからなの？",
            ["DialogueId"] = 80004105,
            ["Duration"] = 3,
            ["GUID"] = "C848297A",
            ["GuideFacialId"] = "Sad",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004106,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848297A",
            },
        [80004106] = {
            ["Content"] = "别害怕，菲娜会帮助你的！",
            ["ContentJP"] = "怖がらないでね、フィーナが助けてあげるから！",
            ["DialogueId"] = 80004106,
            ["Duration"] = 3,
            ["GUID"] = "C84829A4",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829A4",
            },
        [80004107] = {
            ["Content"] = "这里的荆棘长得太高，把小夜莺的巢穴都挡住了。",
            ["ContentJP"] = "棘が生い茂りすぎて、ナイチンゲールの巣がすっかり見えなくなってしまったよ。",
            ["DialogueId"] = 80004107,
            ["Duration"] = 3,
            ["GUID"] = "C84829CE",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004108,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829CE",
            },
        [80004108] = {
            ["Content"] = "用刚才的方法给它们涂上颜色，他们就会给小夜莺让路了吧？",
            ["ContentJP"] = "まずは先の方法で色を付けてあげよう、そうすれば、ナイチンゲールが中から出てこられるはずよ。",
            ["DialogueId"] = 80004108,
            ["Duration"] = 3,
            ["GUID"] = "C84829F8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84829F8",
            },
        [80004109] = {
            ["Content"] = "拦路的荆棘消失了，我们继续前进吧，小夜莺~",
            ["ContentJP"] = "道を塞いでいた棘、片付いたみたいね。さあ、前に進んでみようよ、ナイチンゲール！",
            ["DialogueId"] = 80004109,
            ["Duration"] = 3,
            ["GUID"] = "C8482A22",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8482A22",
            },
