        [80004201] = {
            ["Content"] = "前面的雾气好像更浓了……",
            ["ContentJP"] = "前の霧、どんどん濃くなってきたみたい......",
            ["DialogueId"] = 80004201,
            ["Duration"] = 3,
            ["GUID"] = "C848393A",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004202,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848393A",
            },
        [80004202] = {
            ["Content"] = "小夜莺，你来给菲娜带路吧！",
            ["ContentJP"] = "ナイチンゲール、道を案内してくれる？",
            ["DialogueId"] = 80004202,
            ["Duration"] = 3,
            ["GUID"] = "C8483964",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483964",
            },
        [80004203] = {
            ["Content"] = "哇……原来这块石头是一盏灯呀！灯光亮起来，雾气就散开了。",
            ["ContentJP"] = "わぁ......この石、光ってるよ！石さんのおかげで、霧が少しずつ晴れてきたね～",
            ["DialogueId"] = 80004203,
            ["Duration"] = 3,
            ["GUID"] = "C848398E",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004204,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C848398E",
            },
        [80004204] = {
            ["Content"] = "我们再去找找别的石头吧。",
            ["ContentJP"] = "また別の石を探しに行こう。",
            ["DialogueId"] = 80004204,
            ["Duration"] = 3,
            ["GUID"] = "C84839B8",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84839B8",
            },
        [80004205] = {
            ["Content"] = "雾气会让人迷失方向，要紧跟在小夜莺身边才安全哦。",
            ["ContentJP"] = "霧のせいで、ちょっとでも道を見失いそう......ナイチンゲールの傍から、離れないでいてね。",
            ["DialogueId"] = 80004205,
            ["Duration"] = 3,
            ["GUID"] = "C84839E2",
            ["GuideFacialId"] = "Shock",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C84839E2",
            },
        [80004206] = {
            ["Content"] = "终于走出迷雾了！快看，森林的出口就在前面。",
            ["ContentJP"] = "ついに霧の迷宮を出たね！ほらほら、森の出口は、もうすぐそこよ！",
            ["DialogueId"] = 80004206,
            ["Duration"] = 3,
            ["GUID"] = "C8483A0C",
            ["GuideFacialId"] = "Smile",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A0C",
            },
        [80004207] = {
            ["Content"] = "走出森林之后，会见到怎样的风景呢？好期待呀！",
            ["ContentJP"] = "森の向こうに、どんな景色が広がっているかな？すごく楽しみ！",
            ["DialogueId"] = 80004207,
            ["Duration"] = 3,
            ["GUID"] = "C8483A36",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A36",
            },
        [80004208] = {
            ["Content"] = "咦，那是……大魔法师、独角兽{性别：先生|小姐}和蝴蝶小姐！大家都在等我们呢。",
            ["ContentJP"] = "あれ、あれは......大魔法使いとユニコーンの{性别:お兄さん|お姉さん}、蝶々さんまでも！ずっと私たちを待っていたのね。",
            ["DialogueId"] = 80004208,
            ["Duration"] = 3,
            ["GUID"] = "C8483A60",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["NextDialogue"] = 80004209,
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A60",
            },
        [80004209] = {
            ["Content"] = "小夜莺，我们赶快过去和它们会合吧！",
            ["ContentJP"] = "ナイチンゲール、早くみんなに会いに行こう！",
            ["DialogueId"] = 80004209,
            ["Duration"] = 3,
            ["GUID"] = "C8483A8A",
            ["GuideFacialId"] = "Happy",
            ["HeadIconType"] = "Npc",
            ["SpeakNpcId"] = 700142,
            ["VoiceName"] = "voice/$Locale$/story/1201/120114/C8483A8A",
            },
