        [80040206] = {
            ["Camera"] = "188.85791,-544.567139,199.893921,-0.000091,-9.499379,114.963852,40.0,657.361633,false,Manual,2.991984",
            ["Content"] = "听我的。",
            ["ContentJP"] = "言うことを聞きなさい。",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040206,
            ["GUID"] = "C85F4C4C",
