            ["Content"] = "你——我和你不一样！",
            ["ContentJP"] = "あ、あなたは――私と{nickname}は違う！",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040222,
            ["FacialId"] = {
