        [80040223] = {
            ["Camera"] = "-313.623535,-68.812988,127.089478,-0.007873,-2.815766,17.007097,35.0,386.208527,false,DoNotOverride,3.041301",
            ["Content"] = "没什么不一样的。你看，我这么说让你很担心对吧？要知道我的担心一丁点不比你少。",
            ["ContentJP"] = "{性别:何も違いなんてないさ。僕がこんなこと言ったらベレは心配になっちゃうんだよね？だったら僕だって同じぐらいベレを心配しているの、わかって欲しいな。|何も違いなんてないよ。私がこんなこと言ったらベレは心配になっちゃうんだよね？だったら私だって同じぐらいベレを心配しているの、わかって欲しいな。}",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040223,
            ["FacialId"] = {
                [1] = "790008:None",
                [2] = "790007:None",
                },
            ["FinalCamera"] = "-313.623535,-68.812988,127.089478,-0.007874,-0.415774,17.007204,35.0,386.208527,false,DoNotOverride,3.041301",
            ["GUID"] = "C85F4F16",
            ["NextDialogue"] = 80040224,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/002/C85F4F16",
            },
        [80040224] = {
            ["Camera"] = "-313.623535,-68.812988,127.089478,-0.007874,-0.415774,17.007204,35.0,386.208527,false,DoNotOverride,3.041301",
            ["Content"] = "所以，就当是为了我——多在意自己一点，好不好？",
            ["ContentJP"] = "{性别:お願い、自分のことをもっと大切にして。僕のためだと思って。|お願い、自分のことをもっと大切にして。私のためだと思って。}",
