            ["VoiceName"] = "voice/$Locale$/inv/Heitao/003/C85F5E04",
            },
        [80040315] = {
            ["Content"] = "和贝蕾在一起，我什么都不怕。不。一定要说的话，我……有点兴奋。这对我们来说，也许是一个<H>机会</>。",
            ["ContentJP"] = "{性别:ベレと一緒なら、なにも怖くない。いや……本当は少しだけワクワクしてるかも。この状況ってもしかすると、<H>チャンス</>かもしれないよね。|ベレと一緒なら、なにも怖くない。ううん……本当は少しだけワクワクしてるかも。この状況ってもしかすると、<H>チャンス</>かもしれないよね。}",
            ["DefaultLookAt"] = "TalkNpc",
            ["DialogueId"] = 80040315,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                [2] = "790007:None",
