            ["IsBlack"] = 1,
            ["NextDialogue"] = 80040424,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/story_invite_monster_far_loop\"},EventKey{\"Invite_Heitao_Sound_Loop\"},PlayAs2D{true}}",
            },
        [80040424] = {
            ["Camera"] = "-93.630859,24.962891,220.886658,5.000505,-29.609524,35.775024,30.000008,274.119965,false,DoNotOverride,2.993798",
            ["Content"] = "真奇怪……为什么秽兽会突然发狂呢？",
            ["ContentJP"] = "それにしても……<Default note=\"text:エジュウ\">穢獣</>が前ぶれもなく暴れ出したのはおかしい。",
            ["DialogueId"] = 80040424,
            ["FinalCamera"] = "-102.309082,35.967773,219.821167,5.000515,-29.609531,35.775021,30.000008,274.119965,false,DoNotOverride,2.993798",
            ["GUID"] = "C85F7010",
            ["LookAt"] = {
                [1] = "790060:p(BP_11010402_heitao)",
                },
            ["NextDialogue"] = 80040425,
            ["Scripts"] = "StopNormalSound{EventKey{\"Invite_Heitao_Sound_Loop\"}}",
            ["SpeakNpcId"] = 790060,
            ["TalkActionId"] = {
                [1] = "790060:Sit_Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/004/C85F7010",
            },
        [80040425] = {
            ["Camera"] = "-12.207031,335.27832,15.362854,0.002289,3.389604,-97.820328,30.0,346.472321,false,Manual,2.993798",
            ["Content"] = "也许你说的没错。是我太天真了，以为留在净界岛就能躲开一切危险。",
            ["ContentJP"] = "島を出たがるあなたが正しくて、私の考えが甘かったのかもしれない。パーガトリー島にさえいれば、危険を回避できるって思っていた。",
            ["DialogueId"] = 80040425,
            ["FacialId"] = {
                [1] = "790060:Satisfy01",
                },
            ["FinalCamera"] = "-26.918457,337.268066,15.362854,0.00229,3.389604,-95.620445,30.0,346.472321,false,Manual,2.993798",
            ["GUID"] = "C85F703A",
            ["NextDialogue"] = 80040426,
            ["SpeakNpcId"] = 790060,
            ["TalkActionId"] = {
                [1] = "790060:Sit_Think_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/004/C85F703A",
            },
        [80040426] = {
            ["Camera"] = "3.683594,184.143555,95.722168,0.002534,-6.803585,-60.810005,30.000008,308.979584,false,DoNotOverride,2.993798",
            ["Content"] = "……一直躲在这里也不是办法。他们能找来第一次，就有可能找来第二次。",
            ["ContentJP"] = "……ヤツらが嗅ぎつけてきた以上は、ここにずっと隠れていてもまた見つかるかもしれない。",
            ["DialogueId"] = 80040426,
            ["FinalCamera"] = "-19.79834,171.027344,95.722656,0.002534,-6.803585,-60.810005,30.000008,308.979584,false,DoNotOverride,2.993798",
            ["GUID"] = "C85F7064",
            ["NextDialogue"] = 80040427,
            ["SpeakNpcId"] = 790060,
            ["TalkActionId"] = {
                [1] = "790060:Sit_Idle_Loop",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/004/C85F7064",
            },
        [80040427] = {
            ["Camera"] = "-4.847656,66.36084,122.277466,0.002532,-4.803555,23.188864,30.000008,308.979584,false,DoNotOverride,2.993798",
            ["Content"] = "{nickname}，等明天你醒来，我们就一起离开吧。去自由的、辽阔的远方。像你说的那样——",
            ["ContentJP"] = "{nickname}、一緒にここから出ようか。{nickname}が目を覚ましたら、自由で、広大な、遥か遠くへ。あなたが前に言ってくれたみたいな旅を――",
            ["DialogueId"] = 80040427,
            ["FinalCamera"] = "-4.847656,66.36084,122.277466,0.002534,-4.803555,30.58811,30.000013,308.979584,false,DoNotOverride,2.993798",
            ["GUID"] = "C85F708E",
            ["LookAt"] = {
                [1] = "790060:n(790060)",
                },
            ["NextDialogue"] = 80040428,
            ["SpeakNpcId"] = 790060,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/004/C85F708E",
            },
        [80040428] = {
            ["Camera"] = "-123.908203,78.151855,88.040039,0.002289,15.593007,19.590528,30.0,346.472321,false,DoNotOverride,2.993798",
            ["Content"] = "“我做你的盾牌，你做我的唇齿。”",
            ["ContentJP"] = "「私があなたの盾となり、あなたが私の口となる」",
            ["DialogueId"] = 80040428,
            ["GUID"] = "C85F70B8",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80040429,
            ["SpeakNpcId"] = 790060,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/004/C85F70B8",
            },
        [80040429] = {
            ["Camera"] = "-30.251465,18.105957,23.325562,0.00232,8.991138,-48.805122,20.0,346.472321,false,DoNotOverride,2.993798",
            ["Content"] = "没什么好怕的——已经没什么好怕的了。",
            ["ContentJP"] = "恐れることは何もない――もう、なにも恐くない。",
            ["DialogueId"] = 80040429,
            ["FinalCamera"] = "-9.417969,-5.694824,28.330261,0.00232,8.991138,-48.805122,20.0,346.472321,false,DoNotOverride,2.993798",
            ["GUID"] = "C85F70E2",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790060,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Heitao/004/C85F70E2",
            },
        [80050100] = {
            ["Content"] = "独角兽{性别：先生|小姐}在举办茶会吗？菲娜也来参加吧~",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}、お茶会を開いているの？フィーナもまぜて。",
            ["DialogueId"] = 80050100,
            ["GUID"] = "C865A388",
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A388",
            },
        [80050101] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "你好呀，独角兽{性别：先生|小姐}。我从大魔法师那里收到了新的礼物，要来一起玩吗？",
            ["ContentJP"] = "こんにちは、ユニコーンの{性别:お兄さん|お姉さん}。フィーナは大魔法使いから新しいプレゼントをもらったの。これで一緒に遊びましょう？",
            ["DialogueId"] = 80050101,
            ["GUID"] = "C865A3B2",
            ["NextOptions"] = {
                [1] = 80050102,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A3B2",
            },
        [80050102] = {
            ["Content"] = "这是什么东西？",
            ["ContentJP"] = "これは何？",
            ["DialogueId"] = 80050102,
            ["GUID"] = "C865A3DC",
            ["NextDialogue"] = 80050103,
            },
        [80050103] = {
            ["Content"] = "是“积木”哦。",
            ["ContentJP"] = "「積み木」よ。",
            ["DialogueId"] = 80050103,
            ["GUID"] = "C865A406",
            ["NextDialogue"] = 80050104,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A406",
            },
        [80050104] = {
            ["Content"] = "你看，这些积木虽然一眼看上去很像，但仔细看的话，每一颗的形状、颜色和纹路都有小小的区别！",
            ["ContentJP"] = "ほら、ぱっと見た感じだとみんな同じにみえるでしょ。でもね、よーく見ると、形も色も、模様も、ひとつひとつ少しずつ違うの！",
            ["DialogueId"] = 80050104,
            ["GUID"] = "C865A430",
            ["NextDialogue"] = 80050105,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A430",
            },
        [80050105] = {
            ["Content"] = "我数过了，这一盒里有十几种呢！",
            ["ContentJP"] = "数えてみたら、箱の中に十何種類も入っていたわ！",
            ["DialogueId"] = 80050105,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["GUID"] = "C865A45A",
            ["NextOptions"] = {
                [1] = 80050106,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A45A",
            },
        [80050106] = {
            ["Content"] = "这不是弹壳吗？",
            ["ContentJP"] = "これって、薬莢じゃない？",
            ["DialogueId"] = 80050106,
            ["GUID"] = "C865A484",
            ["NextDialogue"] = 80050107,
            },
        [80050107] = {
            ["Content"] = "唔……原来这种积木的名字叫“弹壳”吗？你懂的真多呀！谢谢你告诉我，作为报答，菲娜来教你怎么搭积木吧。",
            ["ContentJP"] = "あれ……この積み木の名前、「薬莢」って言うの？{性别:お兄さん|お姉さん}ってとっても物知りなのね、教えてくれてありがとう！お礼に積み木の遊び方を教えてあげる。",
            ["DialogueId"] = 80050107,
            ["FacialId"] = {
                [1] = "790017:None",
                },
            ["GUID"] = "C865A4AE",
            ["NextDialogue"] = 80050108,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A4AE",
            },
        [80050108] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "看，这样拼起来，它就变成了小手枪——",
            ["ContentJP"] = "ほら、こうやって積むと、小さなピストルに――",
            ["DialogueId"] = 80050108,
            ["GUID"] = "C865A4D8",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050109,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_gun\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A4D8",
            },
        [80050109] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "这样拼是大炮——轰轰轰！",
            ["ContentJP"] = "こうすれば大砲――ドカン！ドカンドカーン！",
            ["DialogueId"] = 80050109,
            ["GUID"] = "C865A502",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050110,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_cannon\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A502",
            },
        [80050110] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "现在变成了飞艇！",
            ["ContentJP"] = "今度は飛行船に大変身！",
            ["DialogueId"] = 80050110,
            ["GUID"] = "C865A52C",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 80050111,
                },
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_engine\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A52C",
            },
        [80050111] = {
            ["Content"] = "这全是奥特赛德教的吧？",
            ["ContentJP"] = "これってアウトサイダーから教わったのかな？",
            ["DialogueId"] = 80050111,
            ["GUID"] = "C865A556",
            ["NextDialogue"] = 80050112,
            },
        [80050112] = {
            ["Content"] = "对！他还给我讲了好多拼法，比如可以拼成一个大积木人偶，人偶肩膀这里打开可以发射飞弹，背后还可以展开大翅膀——",
            ["ContentJP"] = "うん！アウトサイダーからいろいろな遊び方を教わったの。大きな積み木で人形を作るとか、人形の肩のこの辺りを開くとミサイルが発射できちゃうし、こうして大きな翼を広げたりも——",
            ["DialogueId"] = 80050112,
            ["FacialId"] = {
                [1] = "790017:Smile01",
                },
            ["GUID"] = "C865A580",
            ["NextDialogue"] = 80050113,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A580",
            },
        [80050113] = {
            ["Content"] = "还有拳头、拳头也是可以飞出去的！我来摆给你看！",
            ["ContentJP"] = "それにパンチ！拳だって飛び出すわ！やり方を見せてあげるね！",
            ["DialogueId"] = 80050113,
            ["GUID"] = "C865A5AA",
            ["NextDialogue"] = 80050114,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Give",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A5AA",
            },
        [80050114] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["DialogueId"] = 80050114,
            ["GUID"] = "C865A5AB",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050115,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/feina_bullet_to_punch\"},PlayAs2D{true}}",
            },
        [80050115] = {
            ["Content"] = "……呼，好难拼……不过总算大功告成啦！",
            ["ContentJP"] = "……ふぅ、難しかったけど……やっと大成功！",
            ["DialogueId"] = 80050115,
            ["GUID"] = "C865A5FE",
            ["NextDialogue"] = 80050116,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A5FE",
            },
        [80050116] = {
            ["Content"] = "弹壳居然还能这么玩，让我看看……",
            ["ContentJP"] = "まさか薬莢でこんな風に遊べるなんて……ちょっと見せて？",
            ["DialogueId"] = 80050116,
            ["GUID"] = "C865A628",
            ["NextDialogue"] = 80050117,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A628",
            },
        [80050117] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["DialogueId"] = 80050117,
            ["GUID"] = "C865A629",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050118,
            ["Scripts"] = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/break_bullet_building\"},PlayAs2D{true}}",
            },
        [80050118] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "呃！塌了……",
            ["ContentJP"] = "あ！崩れ、ちゃった……",
            ["DialogueId"] = 80050118,
            ["GUID"] = "C865A67C",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050119,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A67C",
            },
        [80050119] = {
            ["Content"] = "……啊……",
            ["ContentJP"] = "……あぁ……",
            ["DialogueId"] = 80050119,
            ["FacialId"] = {
                [1] = "790017:Sad02",
                },
            ["GUID"] = "C865A6A6",
            ["NextOptions"] = {
                [1] = 80050120,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A6A6",
            },
        [80050120] = {
            ["Content"] = "你别哭！我送个别的礼物给你作为赔礼吧。",
            ["ContentJP"] = "な、泣かないで！お詫びに別のプレゼントを贈るから！",
            ["DialogueId"] = 80050120,
            ["GUID"] = "C865A6D0",
            ["NextDialogue"] = 80050121,
            },
        [80050121] = {
            ["Content"] = "嗯……让我想想……",
            ["ContentJP"] = "わぁ……少しだけ考えさせて……",
            ["DialogueId"] = 80050121,
            ["FacialId"] = {
                [1] = "790017:Iyada01",
                },
            ["GUID"] = "C865A6FA",
            ["NextDialogue"] = 80050122,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A6FA",
            },
        [80050122] = {
            ["Content"] = "独角兽{性别：先生|小姐}，你可以帮菲娜实现四个愿望吗？传说中长有一只角的独角兽可以实现人的任何心愿，所以你也一定可以的！",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}、どうかフィーナの4つお願いを叶えてくれる？一角獣のユニコーンさんは、どんなお願いでも叶えられるって言い伝えられているの。だからきっと{性别:お兄さん|お姉さん}にもできるはず！",
            ["DialogueId"] = 80050122,
            ["GUID"] = "C865A724",
            ["NextOptions"] = {
                [1] = 80050123,
                [2] = 80050124,
                [3] = 80050125,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A724",
            },
        [80050123] = {
            ["Content"] = "当然，只要我能办到。",
            ["ContentJP"] = "もちろん{性别:僕|私}にできることなら。",
            ["DialogueId"] = 80050123,
            ["GUID"] = "C865A74E",
            ["NextDialogue"] = 80050126,
            },
        [80050124] = {
            ["Content"] = "总感觉自己被讹了……",
            ["ContentJP"] = "なんだか、都合よく解釈されている気が……",
            ["DialogueId"] = 80050124,
            ["GUID"] = "C865A778",
            ["NextDialogue"] = 80050126,
            },
        [80050125] = {
            ["Content"] = "人家不都是三个愿望吗！你怎么还多了一个啊！",
            ["ContentJP"] = "願い事って普通は3つじゃない！？1つ多いんですけど！",
            ["DialogueId"] = 80050125,
            ["GUID"] = "C865A7A2",
            ["NextDialogue"] = 80050126,
            },
        [80050126] = {
            ["Content"] = "嘿嘿……",
            ["ContentJP"] = "えへへ……",
            ["DialogueId"] = 80050126,
            ["FacialId"] = {
                [1] = "790017:Satisfy01",
                },
            ["GUID"] = "C865A7CC",
            ["NextOptions"] = {
                [1] = 80050127,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A7CC",
            },
        [80050127] = {
            ["Content"] = "好吧，那第一个愿望是什么？",
            ["ContentJP"] = "最初のお願いは何かな？",
            ["DialogueId"] = 80050127,
            ["GUID"] = "C865A7F6",
            ["NextDialogue"] = 80050128,
            },
        [80050128] = {
            ["Content"] = "菲娜想练习魔法！我虽然会一丁点魔法，但是总也不知道到底怎么用……独角兽{性别：先生|小姐}，你能不能教教我？",
            ["ContentJP"] = "フィーナね、魔法を練習したい！フィーナも魔法を使えるけど、少しだけ。使い方がよくわからなくて……だからユニコーンの{性别:お兄さん|お姉さん}から教わりたいな。",
            ["DialogueId"] = 80050128,
            ["FacialId"] = {
                [1] = "790017:Smile02",
                },
            ["GUID"] = "C865A820",
            ["NextOptions"] = {
                [1] = 80050129,
                [2] = 80050132,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A820",
            },
        [80050129] = {
            ["Content"] = "为什么不让奥特赛德教你？",
            ["ContentJP"] = "なんでアウトサイダーに教えてもらわない{性别:んだ|の}？",
            ["DialogueId"] = 80050129,
            ["GUID"] = "C865A84A",
            ["NextDialogue"] = 80050130,
            },
        [80050130] = {
            ["Content"] = "他不肯教我，也不给我看那些魔法学书本，他把那些书都放在了很高很高的柜子上，我使劲踮起脚尖也够不到。",
            ["ContentJP"] = "アウトサイダーは教えてくれないもの。魔法の本も読んじゃダメだって、高い棚の上に置くから。背伸びしても届かないの。",
            ["DialogueId"] = 80050130,
            ["GUID"] = "C865A874",
            ["NextDialogue"] = 80050131,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A874",
            },
        [80050131] = {
            ["Content"] = "我就只能趁他不在的时候，把凳子堆起来，偷偷去拿——对了对了，这个你千万别和其他人说！",
            ["ContentJP"] = "だからアウトサイダーがいないあいだに、椅子を積んでこっそり取っちゃうしか――あわ、これは内緒、誰にも言わないでね？",
            ["DialogueId"] = 80050131,
            ["GUID"] = "C865A89E",
            ["NextDialogue"] = 80050138,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A89E",
            },
        [80050132] = {
            ["Content"] = "我要收费的。",
            ["ContentJP"] = "うーん、だったら授業料をもらわなきゃ。",
            ["DialogueId"] = 80050132,
            ["GUID"] = "C865A8C8",
            ["NextDialogue"] = 80050133,
            },
        [80050133] = {
            ["Content"] = "咦……？我、我想想……一大罐棉花糖够吗？",
            ["ContentJP"] = "え……？待ってて、うーんと……マシュマロはダメかしら？缶の中にいっぱいの。",
            ["DialogueId"] = 80050133,
            ["FacialId"] = {
                [1] = "790017:Shock02",
                },
            ["GUID"] = "C865A8F2",
            ["NextDialogue"] = 80050134,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A8F2",
            },
        [80050134] = {
            ["Content"] = "但既然是帮菲娜实现愿望，就免费吧。",
            ["ContentJP"] = "でもフィーナの願い事を叶えるために無料してあげちゃう。",
            ["DialogueId"] = 80050134,
            ["GUID"] = "C865A91C",
            ["NextDialogue"] = 80050135,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A91C",
            },
        [80050135] = {
            ["Content"] = "好耶！",
            ["ContentJP"] = "やった！",
            ["DialogueId"] = 80050135,
            ["FacialId"] = {
                [1] = "790017:Happy01",
                },
            ["GUID"] = "C865A946",
            ["NextDialogue"] = 80050136,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A946",
            },
        [80050136] = {
            ["Content"] = "谢谢你愿意教我。奥特赛德就不肯教我，也不给我看那些魔法学书本，他把那些书都放在了很高很高的柜子上，我使劲踮起脚尖也够不到。",
            ["ContentJP"] = "お願い聞いてくれありがとう。だってアウトサイダーは教えてくれないもの。魔法の本も読んじゃダメだって、高い棚の上に置くから。背伸びしても届かないの。",
            ["DialogueId"] = 80050136,
            ["FacialId"] = {
                [1] = "790017:Smile01",
                },
            ["GUID"] = "C865A970",
            ["NextDialogue"] = 80050137,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A970",
            },
        [80050137] = {
            ["Content"] = "我就只能趁他不在的时候，把凳子堆起来，偷偷去拿——对了对了，这个你千万别和其他人说！",
            ["ContentJP"] = "だからアウトサイダーがいないあいだに、椅子を積んでこっそり取っちゃうしか――あわ、これは内緒、誰にも言わないでね？",
            ["DialogueId"] = 80050137,
            ["GUID"] = "C865A99A",
            ["NextDialogue"] = 80050138,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A99A",
            },
        [80050138] = {
            ["Content"] = "他总说，学魔法的人得走出安稳的房间，离开暖和的火炉，去一片荒原——荒芜的、严酷的荒原……",
            ["ContentJP"] = "アウトサイダーはいつもこう言うの。魔法を学ぶのはすごーく大変なんだって。暖かいストーブから離れて、気持ちいいお部屋から出て、荒野へ――過酷な不毛の地に行かないといけないって……",
            ["DialogueId"] = 80050138,
            ["GUID"] = "C865A9C4",
            ["NextDialogue"] = 80050139,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A9C4",
            },
        [80050139] = {
            ["Content"] = "那里有很多很多雪狼，眼睛放着可怕的绿光，还有骑着扫把、浑身上下涂满毒药的沼泽女巫。",
            ["ContentJP"] = "そこにはたくさんの雪狼がいて、その目は緑色にギラギラと光ってるの。箒に乗っている、全身に毒を塗った沼地の魔女もいるらしいわ。",
            ["DialogueId"] = 80050139,
            ["FacialId"] = {
                [1] = "790017:Iyada01",
                },
            ["GUID"] = "C865A9EE",
            ["NextOptions"] = {
                [1] = 80050140,
                [2] = 80050143,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865A9EE",
            },
        [80050140] = {
            ["Content"] = "没那么夸张，他是吓唬你的。",
            ["ContentJP"] = "そんな大げさな。アウトサイダーはフィーナを脅しているだけだよ。",
            ["DialogueId"] = 80050140,
            ["GUID"] = "C865AA18",
            ["NextDialogue"] = 80050141,
            },
        [80050141] = {
            ["Content"] = "啊……我就知道！他只是害怕我会生病、会受伤。但是，如果我的身体一直不能好起来……我也不想就这样一直一直躺在家里，当小拖油瓶。",
            ["ContentJP"] = "うん……私だってわかっているもん。フィーナは病気になりやすいし、怪我するから、アウトサイダーは心配してくれている。だけどフィーナの身体の調子がずっとよくならなかったら……家でずっと寝たきりでお荷物になるのだけは嫌なの。",
            ["DialogueId"] = 80050141,
            ["FacialId"] = {
                [1] = "790017:Smile01",
                },
            ["GUID"] = "C865AA42",
            ["NextDialogue"] = 80050142,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865AA42",
            },
        [80050142] = {
            ["Content"] = "……我想变成一个有用的孩子，我不想再被讨厌了。",
            ["ContentJP"] = "……フィーナも役に立つ子になりたいな。もう嫌われたくない。",
            ["DialogueId"] = 80050142,
            ["GUID"] = "C865AA6C",
            ["NextDialogue"] = 80050145,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865AA6C",
            },
        [80050143] = {
            ["Content"] = "有比雪狼和沼泽女巫更可怕的东西。",
            ["ContentJP"] = "雪狼や沼地の魔女より、もっと恐ろしい存在もいるよ。",
            ["DialogueId"] = 80050143,
            ["GUID"] = "C865AA96",
            ["NextDialogue"] = 80050144,
            },
        [80050144] = {
            ["Content"] = "可是这样的话……我就更不能让你们自己去那里了。我得好好学魔法，帮上你们的忙才行。",
            ["ContentJP"] = "それなら……フィーナはもっともっと魔法の勉強を頑張って、アウトサイダーや{性别:お兄さん|お姉さん}を手伝わなくちゃ。ただ待っているだけなんて嫌なの。",
            ["DialogueId"] = 80050144,
            ["GUID"] = "C865AAC0",
            ["NextDialogue"] = 80050145,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865AAC0",
            },
        [80050145] = {
            ["Content"] = "所以——拜托了，教教我吧！我一定会好好保密的。",
            ["ContentJP"] = "だから――お願い、教えて！フィーナ、絶対ちゃんと内緒にするから！",
            ["DialogueId"] = 80050145,
            ["FacialId"] = {
                [1] = "790017:Confident02",
                },
            ["GUID"] = "C865AAEA",
            ["NextOptions"] = {
                [1] = 80050146,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865AAEA",
            },
        [80050146] = {
            ["Content"] = "好吧，那我们现在就开始练习吧。",
            ["ContentJP"] = "わかったよ、じゃあ今から練習しようね。",
            ["DialogueId"] = 80050146,
            ["GUID"] = "C865AB14",
            ["NextDialogue"] = 80050147,
            },
        [80050147] = {
            ["Content"] = "太好了——你是全天下最好最好的独角兽{性别：先生|小姐}！",
            ["ContentJP"] = "やった～～！素敵な素敵なユニコーンの{性别:お兄さん|お姉さん}は、世界最高のユニコーンさんだわ！",
            ["DialogueId"] = 80050147,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["GUID"] = "C865AB3E",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/001/C865AB3E",
            },
        [80050201] = {
            ["Camera"] = "364.267578,-629.911316,141.387695,0.0,0.0,123.199776,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "菲娜的第二个愿望是，想要独角兽{性别：先生|小姐}偷偷带我去城外，看看真正的星星。",
            ["ContentJP"] = "フィーナの二つ目のお願い。フィーナを街の外へ連れていってほしいの。本当のお星さまを見てみたいなぁって。",
            ["DialogueId"] = 80050201,
            ["Duration"] = 5,
            ["GUID"] = "C865B41A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050202,
            ["Scripts"] = "PlayAnimation{_click{false},_delay{5},ActorId{790017},AnimationId{\"Disagree\"},Duration{1}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B41A",
            },
        [80050202] = {
            ["Camera"] = "198.488281,-216.339706,-7.433838,0.000016,4.399113,131.781357,18.0,100000.0,false,DoNotOverride,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "……天空好大，好高。星星好多，好亮……真好看……",
            ["ContentJP"] = "……広くて高い空。たくさんのお星さま。明るくて……本当にきれい……",
            ["DialogueId"] = 80050202,
            ["FinalCamera"] = "164.765625,-177.972809,-5.608887,0.000038,26.398823,132.182083,18.0,100000.0,false,DoNotOverride,22.0",
            ["GUID"] = "C865B444",
            ["NextDialogue"] = 80050203,
            ["SpeakNpcId"] = 790017,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B444",
            },
        [80050203] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "城里的晚上，就算不下雪，天空也总是被房子和城墙关起来，只有很小很小的一块，怎么也不够看的。",
            ["ContentJP"] = "街で夜空を見上げても、雪が降ってなかったとしても、建物とか城壁があるから。いつも小さくて狭い空しか見れなかったの。",
            ["DialogueId"] = 80050203,
            ["GUID"] = "C865B46E",
            ["NextDialogue"] = 80050204,
            ["SpeakNpcId"] = 790017,
            ["TurnTo"] = {
                [1] = "790017:n(100001)",
                [2] = "100001:n(790017)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B46E",
            },
        [80050204] = {
            ["Content"] = "奥特赛德送给我的星空灯很美……但果然，还是真正的星空更——阿嚏！",
            ["ContentJP"] = "アウトサイダーのくれたプラネタリウムはとってもきれいだった……でもやっぱり、本物の星空のほうが――クシュン！",
            ["DialogueId"] = 80050204,
            ["GUID"] = "C865B498",
            ["NextOptions"] = {
                [1] = 80050205,
                [2] = 80050206,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B498",
            },
        [80050205] = {
            ["Content"] = "小心着凉。",
            ["ContentJP"] = "風邪をひかないようにね。",
            ["DialogueId"] = 80050205,
            ["GUID"] = "C865B4C2",
            ["NextDialogue"] = 80050207,
            },
        [80050206] = {
            ["Content"] = "你站我后面吧，我帮你挡着风。",
            ["ContentJP"] = "{性别:僕|私}の後ろに立ってごらん。冷たい風をさえぎってあげる。",
            ["DialogueId"] = 80050206,
            ["GUID"] = "C865B4EC",
            ["NextDialogue"] = 80050207,
            },
        [80050207] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没事没事，菲娜一点也不冷。不信你摸摸我的手心，很暖和的！我想再多待一会儿……",
            ["ContentJP"] = "いいの、大丈夫、全然寒くないから。フィーナの手を触ってみて、温かいでしょ！だからもう少しだけ、ここにいたいな……",
            ["DialogueId"] = 80050207,
            ["GUID"] = "C865B516",
            ["NextDialogue"] = 80050208,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}},PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"Talk02_Start\"},Duration{1}}}",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B516",
            },
        [80050208] = {
            ["Camera"] = "-370.169922,731.447144,106.094727,0.000026,35.394604,129.986496,18.0,100000.0,false,DoNotOverride,22.0",
            ["Content"] = "快看快看，那几颗星星连起来，像不像一只小兔子？",
            ["ContentJP"] = "見て見て、あの星と星をつなげたら、ウサギさんみたいに見えないかな？",
            ["DialogueId"] = 80050208,
            ["GUID"] = "C865B540",
            ["NextOptions"] = {
                [1] = 80050209,
                [2] = 80050211,
                [3] = 80050214,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B540",
            },
        [80050209] = {
            ["Content"] = "像。",
            ["ContentJP"] = "たしかに。",
            ["DialogueId"] = 80050209,
            ["GUID"] = "C865B56A",
            ["NextDialogue"] = 80050210,
            },
        [80050210] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘿嘿~那么，我今晚就来给它编故事，小兔子在星星上的故事。",
            ["ContentJP"] = "えへへ～今夜、お話を作ろうっと。星の子ウサギの物語よ。",
            ["DialogueId"] = 80050210,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["GUID"] = "C865B594",
            ["NextOptions"] = {
                [1] = 80050217,
                },
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Confident_Start\"},Duration{2}},PlayAnimation{_delay{3},ActorId{790017},AnimationId{\"Confident_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B594",
            },
        [80050211] = {
            ["Content"] = "像大鸡腿。",
            ["ContentJP"] = "{性别:いや|ううん}、ニワトリのモモ肉に見える。",
            ["DialogueId"] = 80050211,
            ["GUID"] = "C865B5BE",
            ["NextDialogue"] = 80050212,
            },
        [80050212] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？……我好像看不出来。你是不是肚子饿了？",
            ["ContentJP"] = "え、フィーナにはそう見えないけど……{性别:お兄さん|お姉さん}、お腹が空いたのかな？",
            ["DialogueId"] = 80050212,
            ["FacialId"] = {
                [1] = "790017:Shock01",
                },
            ["GUID"] = "C865B5E8",
            ["NextDialogue"] = 80050213,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B5E8",
            },
        [80050213] = {
            ["Camera"] = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "开个玩笑。说来……",
            ["ContentJP"] = "冗談だよ。そういえば……",
            ["DialogueId"] = 80050213,
            ["GUID"] = "C865B612",
            ["NextOptions"] = {
                [1] = 80050217,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "790017:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B612",
            },
        [80050214] = {
            ["Content"] = "像一只头顶裤衩的海豚。",
            ["ContentJP"] = "{性别:いや|ううん}、パンツを被ったイルカに見える。",
            ["DialogueId"] = 80050214,
            ["GUID"] = "C865B63C",
            ["NextDialogue"] = 80050215,
            },
        [80050215] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "咦？那、那是什么？！我好像想象不出来……",
            ["ContentJP"] = "はぇ、そ、それはどんなものか、フィーナには想像つかないな……",
            ["DialogueId"] = 80050215,
            ["FacialId"] = {
                [1] = "790017:Shock01",
                },
            ["GUID"] = "C865B666",
            ["NextDialogue"] = 80050216,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B666",
            },
        [80050216] = {
            ["Camera"] = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "开个玩笑。说来……",
            ["ContentJP"] = "冗談だよ。そういえば……",
            ["DialogueId"] = 80050216,
            ["GUID"] = "C865B690",
            ["NextOptions"] = {
                [1] = 80050217,
                },
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "790017:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B690",
            },
        [80050217] = {
            ["Content"] = "菲娜为什么这么喜欢星空？",
            ["ContentJP"] = "フィーナってすごく星空が好きだけど……どうしてかな？",
            ["DialogueId"] = 80050217,
            ["GUID"] = "C865B6BA",
            ["NextDialogue"] = 80050218,
            },
        [80050218] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "很久很久以前啊，妈妈给我讲过一个故事。一只小鸟儿变成了星星的故事……这是我最喜欢的故事，我也来讲给你听吧。",
            ["ContentJP"] = "昔々ね、お母さんがフィーナにお話を聞かせてくれたの。小さな鳥がお星さまになるお話……フィーナが大好きなお話だから、{性别:お兄さん|お姉さん}にも聞いて欲しいな。",
            ["DialogueId"] = 80050218,
            ["GUID"] = "C865B6E4",
            ["NextDialogue"] = 80050219,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"Explain02_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B6E4",
            },
        [80050219] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这只鸟儿和其他鸟儿不一样，它羽毛生得丑陋，歌声也难听；没有尖尖的爪子，也没有锋利的喙。其他鸟儿们都讨厌它，每天都在欺负它，想要赶它走。",
            ["ContentJP"] = "その鳥はほかの鳥と違っていました。羽は醜く、歌声は聞き苦しく、尖った爪や鋭いクチバシもありません。ほかの鳥たちに嫌われていて、毎日イジメられて、仲間はずれにされていました。",
            ["DialogueId"] = 80050219,
            ["GUID"] = "C865B70E",
            ["NextDialogue"] = 80050220,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{2}}",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B70E",
            },
        [80050220] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但是，这只小小的鸟儿却向往着星空。它向满天繁星祈求，求星星把自己带到它们那儿，哪怕是被炽热的光芒灼烧而死，也心甘情愿。",
            ["ContentJP"] = "そんな小さな鳥ですが、実は星空に憧れていました。満天の星たちに祈りを捧げます。「どうか自分もお星さまのもとへ連れてってください。たとえ灼熱の光で灼けて死んでも、後悔はしません」と。",
            ["DialogueId"] = 80050220,
            ["GUID"] = "C865B738",
            ["NextOptions"] = {
                [1] = 80050221,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B738",
            },
        [80050221] = {
            ["Content"] = "星星回应了它的愿望？",
            ["ContentJP"] = "お星さまはその願いに応えてくれた？",
            ["DialogueId"] = 80050221,
            ["GUID"] = "C865B762",
            ["NextDialogue"] = 80050222,
            },
        [80050222] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没有哦……星星们要么不理睬它，要么嘲笑它的不自量力：一只丑陋的鸟儿，竟然也妄想和星星一起飞翔在漂亮的夜空之上。",
            ["ContentJP"] = "いいえ……お星さまたちは鳥をまったく相手にしないか、もしくは身のほど知らずってあざ笑ったの。醜い鳥が星と一緒に夜空を飛びたいなんて、とんでもない妄想だって。",
            ["DialogueId"] = 80050222,
            ["GUID"] = "C865B78C",
            ["NextOptions"] = {
                [1] = 80050223,
                },
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain01_End\"},Duration{2}},PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{1}}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B78C",
            },
        [80050223] = {
            ["Content"] = "后来呢？",
            ["ContentJP"] = "その後は？",
            ["DialogueId"] = 80050223,
            ["GUID"] = "C865B7B6",
            ["NextDialogue"] = 80050224,
            },
        [80050224] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "它不再哀求任何人，而是告别亲人，自己飞上了夜空。",
            ["ContentJP"] = "鳥はもう誰にも祈らないと決めました。家族に別れを告げて、自分で夜空へ向かって飛び立ったのです。",
            ["DialogueId"] = 80050224,
            ["GUID"] = "C865B7E0",
            ["NextDialogue"] = 80050225,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B7E0",
            },
        [80050225] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "它飞得越来越高，越来越高，天空也越来越冷。最终，它被冻住了，它再也不会飞，不会动弹了。",
            ["ContentJP"] = "高く飛んで、どこまでも、どこまでもまっすぐに昇って、暖かさが遠のいて、空が凍える寒さになろうと飛び続けました。最後に、鳥は凍ってしまい、動かなくなりました。醜い鳥はもう二度と羽ばたけません。",
            ["DialogueId"] = 80050225,
            ["GUID"] = "C865B80A",
            ["NextOptions"] = {
                [1] = 80050226,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B80A",
            },
        [80050226] = {
            ["Content"] = "……是个伤感的结局呢。",
            ["ContentJP"] = "……悲しい結末だね。",
            ["DialogueId"] = 80050226,
            ["GUID"] = "C865B834",
            ["NextDialogue"] = 80050227,
            },
        [80050227] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "还没有结束呢。鸟儿这时发现自己燃烧起来了，它丑陋的身体静静地在夜空中燃起了漂亮的火焰……就像一颗<H>真正的星星</>。",
            ["ContentJP"] = "まだ終わりじゃないの。その時、鳥は自分が静かに燃えていることに気づきました。その醜い体が静かな夜空で、美しく燃え続けている……まるで<H>本当のお星さまの</>のように。",
            ["DialogueId"] = 80050227,
            ["GUID"] = "C865B85E",
            ["NextDialogue"] = 80050228,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Explain01_Start\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"Explain01_End\"},Duration{1}}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B85E",
            },
        [80050228] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，它变成了一颗真正的星星！",
            ["ContentJP"] = "そう、この鳥は本当に、本当にお星さまになったの！",
            ["DialogueId"] = 80050228,
            ["GUID"] = "C865B888",
            ["NextDialogue"] = 80050229,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B888",
            },
        [80050229] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了，现在我讲完了。独角兽{性别：先生|小姐}喜欢这个故事吗？",
            ["ContentJP"] = "お話はこれでおしまいだけど……ユニコーンの{性别:お兄さん|お姉さん}は、どう思った？このお話、好き、嫌い？",
            ["DialogueId"] = 80050229,
            ["GUID"] = "C865B8B2",
            ["LookAt"] = {
                [1] = "790017:p(180102P)",
                },
            ["NextOptions"] = {
                [1] = 80050230,
                [2] = 80050232,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B8B2",
            },
        [80050230] = {
            ["Content"] = "我喜欢。这个故事很美丽。",
            ["ContentJP"] = "{性别:僕|私}は好き。とてもきれいなお話だね。",
            ["DialogueId"] = 80050230,
            ["GUID"] = "C865B8DC",
            ["NextDialogue"] = 80050231,
            },
        [80050231] = {
            ["Camera"] = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这只鸟儿很勇敢，比我想象中更加勇敢。我很喜欢。",
            ["ContentJP"] = "思っていた以上に勇敢な鳥のお話だったよ。とても素敵だと思う。",
            ["DialogueId"] = 80050231,
            ["GUID"] = "C865B906",
            ["LookAt"] = {
                [1] = "790017:n(100001)",
                },
            ["NextDialogue"] = 80050235,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B906",
            },
        [80050232] = {
            ["Content"] = "我不喜欢。这个故事太悲伤了。",
            ["ContentJP"] = "{性别:僕|私}は好きじゃない。悲しすぎるよ。",
            ["DialogueId"] = 80050232,
            ["GUID"] = "C865B930",
            ["NextDialogue"] = 80050233,
            },
        [80050233] = {
            ["Camera"] = "-232.548828,-74.897537,111.892822,0.000019,0.0,16.801809,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我觉得鸟儿不应该牺牲自己……这是一种逃避，逃避真正的不公平。它应该去抗争。",
            ["ContentJP"] = "鳥は自分を犠牲にする必要なんてなかった……それは現実逃避だと思う{性别:んだ|の}。鳥は不当な扱いをする連中と戦うべきだった。",
            ["DialogueId"] = 80050233,
            ["GUID"] = "C865B95A",
            ["LookAt"] = {
                [1] = "790017:n(100001)",
                },
            ["NextDialogue"] = 80050234,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B95A",
            },
        [80050234] = {
            ["Camera"] = "80.75,208.85965,155.646973,0.000058,-12.000109,-112.178284,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这样吗……唔，那就是一个完全不同的新故事啦。",
            ["ContentJP"] = "なるほど……うーん、だったら全然違うお話になっちゃうけど。",
            ["DialogueId"] = 80050234,
            ["GUID"] = "C865B984",
            ["NextDialogue"] = 80050235,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B984",
            },
        [80050235] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80050235,
            ["GUID"] = "C865B9AE",
            ["LookAt"] = {
                [1] = "790017:p(180102P)",
                },
            ["NextDialogue"] = 80050236,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B9AE",
            },
        [80050236] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我也有一天可以变成这样的鸟儿吧。",
            ["ContentJP"] = "フィーナもいつか、このお話みたいな鳥さんになりたいな。",
            ["DialogueId"] = 80050236,
            ["GUID"] = "C865B9D8",
            ["LookAt"] = {
                [1] = "790017:n(790017)",
                },
            ["NextOptions"] = {
                [1] = 80050237,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865B9D8",
            },
        [80050237] = {
            ["Content"] = "……鸟儿的亲人会伤心的。",
            ["ContentJP"] = "……鳥さんの家族が悲しむよ。",
            ["DialogueId"] = 80050237,
            ["GUID"] = "C865BA02",
            ["NextDialogue"] = 80050238,
            },
        [80050238] = {
            ["Camera"] = "23.431641,110.859238,117.97876,0.000015,-3.600008,-118.598862,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊……这个问题，我倒是从来没有思考过。",
            ["ContentJP"] = "あ……そうよね、考えていなかった。",
            ["DialogueId"] = 80050238,
            ["GUID"] = "C865BA2C",
            ["LookAt"] = {
                [1] = "790017:n(100001)",
                },
            ["NextDialogue"] = 80050239,
            ["Scripts"] = "SEQ{PlayAnimation{ActorId{790017},AnimationId{\"Sigh_End\"},Duration{3}},PlayAnimation{ActorId{790017},AnimationId{\"DisagreeHead\"},Duration{1}}}",
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865BA2C",
            },
        [80050239] = {
            ["Content"] = "我一直认为鸟儿的亲人们会很开心，因为它那么明亮，那么永恒，一直一直都挂在那儿。",
            ["ContentJP"] = "鳥さんの家族は喜んでいるんじゃないかなって、思ってたの。だって鳥さんはずっとずっとお空で、永遠に、輝いているんでしょ。",
            ["DialogueId"] = 80050239,
            ["GUID"] = "C865BA56",
            ["NextDialogue"] = 80050240,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865BA56",
            },
        [80050240] = {
            ["Content"] = "如果想它了，只要和我们一样，在没有云的夜里，抬起头来，就可以和它打招呼。",
            ["ContentJP"] = "もし会いたくなったら、今の私たちみたいに雲のいない夜空を見上げれば、挨拶できるから。",
            ["DialogueId"] = 80050240,
            ["GUID"] = "C865BA80",
            ["NextDialogue"] = 80050241,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865BA80",
            },
        [80050241] = {
            ["Content"] = "但是你提醒了我……它变成了星星，再也不会说话，不会动了。虽然见到了，但走多远也都到不了，够不到。",
            ["ContentJP"] = "でも{性别:お兄さん|お姉さん}の言う通りかも……星になった鳥はお話しも、動くことさえできない。見えるのにたどり着けない場所にいて、会いたくても手も届かない。",
            ["DialogueId"] = 80050241,
            ["GUID"] = "C865BAAA",
            ["NextDialogue"] = 80050242,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865BAAA",
            },
        [80050242] = {
            ["Content"] = "它的亲人们会为此难过吗？菲娜要好好想一想……",
            ["ContentJP"] = "だから鳥さん家族は悲しいのかな？よく考えなきゃ……",
            ["DialogueId"] = 80050242,
            ["GUID"] = "C865BAD4",
            ["NextDialogue"] = 80050243,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865BAD4",
            },
        [80050243] = {
            ["Content"] = "谢谢你今天陪我玩，独角兽{性别：先生|小姐}。我们回家吧。",
            ["ContentJP"] = "今日は遊んでくれてありがとう、ユニコーンの{性别:お兄さん|お姉さん}。一緒に帰りましょう。",
            ["DialogueId"] = 80050243,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["GUID"] = "C865BAFE",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/002/C865BAFE",
            },
        [80050301] = {
            ["Camera"] = "-220.272461,-361.613037,104.543945,0.0,0.0,64.200195,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "第三个愿望是，想要独角兽{性别：先生|小姐}带我到冰湖城的城墙上面去。",
            ["ContentJP"] = "アイスレイクの城壁の上までフィーナを連れていってほしいの。それがユニコーンの{性别:お兄さん|お姉さん}への3つ目のお願い。",
            ["DialogueId"] = 80050301,
            ["GUID"] = "C865C482",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80050302,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C482",
            },
        [80050302] = {
            ["Camera"] = "-58.240234,-248.958618,99.918945,0.000097,3.997675,105.603172,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "呼、呼、呼……",
            ["ContentJP"] = "はぁ、ひぃ、ふぅ……",
            ["DialogueId"] = 80050302,
            ["FacialId"] = {
                [1] = "790017:Iyada01",
                },
            ["FinalCamera"] = "-21.044922,-372.557251,86.48877,0.000079,4.397842,110.200386,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C4AC",
            ["NextOptions"] = {
                [1] = 80050303,
                },
            ["SpeakNpcId"] = 790017,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C4AC",
            },
        [80050303] = {
            ["Content"] = "慢一点，不要跑那么快。",
            ["ContentJP"] = "ゆっくりでいいよ、急ぎ足じゃなくても。",
            ["DialogueId"] = 80050303,
            ["GUID"] = "C865C4D6",
            ["NextDialogue"] = 80050304,
            },
        [80050304] = {
            ["Camera"] = "-62.108398,71.224731,134.228027,0.000089,-8.600738,-108.702515,35.000011,332.46875,false,Manual,2.8",
            ["Content"] = "没事的，没事的！你看，我们现在站在冰湖城外城最高最高的地方啦！我们在天上，就像真正的鸟儿一样！",
            ["ContentJP"] = "いいの、大丈夫！ほら見て、アイスレイクの外城区の一番、い～っちばん高いところにフィーナたちは立っているのよ！私たちは空にいるの、まるで本当の鳥みたいに！",
            ["DialogueId"] = 80050304,
            ["FacialId"] = {
                [1] = "790017:None",
                },
            ["GUID"] = "C865C500",
            ["NextDialogue"] = 80050305,
            ["SpeakNpcId"] = 790017,
            ["TurnTo"] = {
                [1] = "790017:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C500",
            },
        [80050305] = {
            ["Camera"] = "1406.34082,3547.11084,331.411621,0.000199,20.369057,76.672722,35.000015,332.468811,false,DoNotOverride,2.8",
            ["Content"] = "太阳——你好！云朵——你好！我是菲娜！这是独角兽{性别：先生|小姐}，{性别：他|她}是我的好朋友！",
            ["ContentJP"] = "太陽さーん、こんにちは！雲さーん、こんにちは！私はフィーナ！こちらはユニコーンの{性别:お兄さん|お姉さん}！フィーナのお友達なの！",
            ["DialogueId"] = 80050305,
            ["FinalCamera"] = "1406.34082,3547.11084,331.411621,0.00018,27.768972,76.671822,35.000015,332.468811,false,DoNotOverride,2.8",
            ["GUID"] = "C865C52A",
            ["NextDialogue"] = 80050306,
            ["Scripts"] = "SEQ{TurnTo{TurnToDescription{\"790017:p(-90)\"}},PlayAnimation{ActorId{790017},AnimationId{\"Explain02_Start\"},Duration{4}},PlayAnimation{ActorId{790017},AnimationId{\"Explain02_End\"},Duration{1}},LookAt{LookAtDescription{\"790017:n(100001)\"}}}",
            ["SpeakNpcId"] = 790017,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C52A",
            },
        [80050306] = {
            ["Camera"] = "-78.46582,31.777893,128.363281,0.000091,-6.59982,-104.609161,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嘿嘿……",
            ["ContentJP"] = "えへへ……",
            ["DialogueId"] = 80050306,
            ["FacialId"] = {
                [1] = "790017:Smile01",
                },
            ["GUID"] = "C865C554",
            ["NextOptions"] = {
                [1] = 80050307,
                [2] = 80050309,
                },
            ["SpeakNpcId"] = 790017,
            ["TurnTo"] = {
                [1] = "790017:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C554",
            },
        [80050307] = {
            ["Content"] = "小声点，你不想奥特赛德听到你偷跑出来吧。",
            ["ContentJP"] = "シーッ、こっそり来たこと、アウトサイダーにバレちゃう。",
            ["DialogueId"] = 80050307,
            ["GUID"] = "C865C57E",
            ["NextDialogue"] = 80050308,
            },
        [80050308] = {
            ["Camera"] = "-78.46582,31.777893,128.363281,0.000091,-6.59982,-104.609161,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "啊——对不起对不起……",
            ["ContentJP"] = "あっそうか――ごめんなさい……",
            ["DialogueId"] = 80050308,
            ["FacialId"] = {
                [1] = "790017:Sad01",
                },
            ["GUID"] = "C865C5A8",
            ["NextDialogue"] = 80050311,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C5A8",
            },
        [80050309] = {
            ["Content"] = "太阳——你好！",
            ["ContentJP"] = "太陽さーん！こーんにーちはー！",
            ["DialogueId"] = 80050309,
            ["GUID"] = "C865C5D2",
            ["NextDialogue"] = 80050310,
            },
        [80050310] = {
            ["Camera"] = "-78.46582,31.777893,128.363281,0.000091,-6.59982,-104.609161,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "独角兽{性别：先生|小姐}今天很有精神呢！",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}ったら、今日は元気いっぱいね！",
            ["DialogueId"] = 80050310,
            ["GUID"] = "C865C5FC",
            ["NextDialogue"] = 80050311,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C5FC",
            },
        [80050311] = {
            ["Camera"] = "-83.920898,-74.225281,112.907715,0.0,0.399805,-104.401306,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我还从没在这么高的地方看过冰湖城呢！对了对了，你现在熟悉冰湖城了吗？我来指给你看——",
            ["ContentJP"] = "フィーナ、今までこんな高いところからアイスレイク城を見たことなかったよ！そういえば、{性别:お兄さん|お姉さん}、もうアイスレイク城には慣れたかな？フィーナが案内してあげるね――",
            ["DialogueId"] = 80050311,
            ["FacialId"] = {
                [1] = "790017:None",
                },
            ["GUID"] = "C865C626",
            ["NextDialogue"] = 80050312,
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C626",
            },
        [80050312] = {
            ["Camera"] = "3399.474609,-93.6745,782.563721,0.000066,-15.400177,-17.203409,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那个黄铜色的，圆圆的，有一个尖尖翘起来的，是银色和平广场的雕塑！它已经站在那儿好几百年了哦。",
            ["ContentJP"] = "あの黄土色のトゲトゲしている丸いのが、シルバーピース広場の彫刻！何百年もあそこに立っているの。",
            ["DialogueId"] = 80050312,
            ["FinalCamera"] = "3399.474609,-93.6745,922.0,0.000066,-15.400177,-17.203409,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C650",
            ["NextDialogue"] = 80050313,
            ["SpeakNpcId"] = 790017,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C650",
            },
        [80050313] = {
            ["Camera"] = "-82.092773,-23.63623,98.630615,0.000068,2.799851,-101.803772,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "南边那些你靠着我、我靠着你的小房子，其中就有一座是菲娜的家！那里的邻居们很吵闹，但也很友好。",
            ["ContentJP"] = "南の方には小さなお家が寄りそっているわ。フィーナのお家もあそこにあるのよ！お隣さんたちはとっても騒がしいけど、みんな仲良し！",
            ["DialogueId"] = 80050313,
            ["GUID"] = "C865C67A",
            ["NextDialogue"] = 80050314,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C67A",
            },
        [80050314] = {
            ["Camera"] = "-70.529297,-88.626709,162.978516,0.000101,-23.199331,-111.998558,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "西边…………",
            ["ContentJP"] = "西の方は…………",
            ["DialogueId"] = 80050314,
            ["FacialId"] = {
                [1] = "790017:Sad01",
                },
            ["FinalCamera"] = "-75.646484,-101.298706,157.119873,0.000101,-23.199331,-111.998558,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C6A4",
            ["NextDialogue"] = 80050315,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C6A4",
            },
        [80050315] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80050315,
            ["FacialId"] = {
                [1] = "790017:Disappoint01",
                },
            ["GUID"] = "C865C6CE",
            ["NextOptions"] = {
                [1] = 80050316,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C6CE",
            },
        [80050316] = {
            ["Content"] = "怎么了？你不认识的话，我来告诉你吧。",
            ["ContentJP"] = "{性别:どうしたんだ|どうしてたの}？あそこってたしか……",
            ["DialogueId"] = 80050316,
            ["GUID"] = "C865C6F8",
            ["NextDialogue"] = 80050317,
            },
        [80050317] = {
            ["Camera"] = "-65.606445,-263.350464,109.867432,0.000101,0.000478,109.002274,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我是知道的。",
            ["ContentJP"] = "……知ってるわ。",
            ["DialogueId"] = 80050317,
            ["GUID"] = "C865C722",
            ["NextDialogue"] = 80050318,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C722",
            },
        [80050318] = {
            ["Camera"] = "-65.606445,-263.350464,109.867432,0.000101,0.000478,109.002274,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那是内城……菲娜长大的地方。看……那个方向，就是我以前住过的房子。",
            ["ContentJP"] = "内城区……フィーナが育った場所。見て……あっちにあるのが、フィーナが昔に住んでいたお家よ。",
            ["DialogueId"] = 80050318,
            ["GUID"] = "C865C74C",
            ["NextOptions"] = {
                [1] = 80050319,
                [2] = 80050321,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C74C",
            },
        [80050319] = {
            ["Content"] = "原来菲娜是有钱人家的大小姐啊，真好。",
            ["ContentJP"] = "フィーナってお金持ちのお嬢様{性别:だったのか|だったのね}。いいなぁ。",
            ["DialogueId"] = 80050319,
            ["GUID"] = "C865C776",
            ["NextDialogue"] = 80050320,
            },
        [80050320] = {
            ["Content"] = "不，一点儿也不好。",
            ["ContentJP"] = "ううん、なんにもよくない。",
            ["DialogueId"] = 80050320,
            ["GUID"] = "C865C7A0",
            ["NextDialogue"] = 80050323,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C7A0",
            },
        [80050321] = {
            ["Content"] = "你很想念那儿吗？",
            ["ContentJP"] = "あそこが恋しくなったのかな？",
            ["DialogueId"] = 80050321,
            ["GUID"] = "C865C7CA",
            ["NextDialogue"] = 80050322,
            },
        [80050322] = {
            ["Camera"] = "-61.318359,8.6604,109.648682,0.000008,0.0,-104.999664,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不，不想。一点儿也不想。",
            ["ContentJP"] = "ううん、全然。少しも恋しくなんて思っていない。",
            ["DialogueId"] = 80050322,
            ["GUID"] = "C865C7F4",
            ["NextDialogue"] = 80050323,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C7F4",
            },
        [80050323] = {
            ["Camera"] = "-101.632812,-105.954285,114.34375,0.000072,0.999728,-97.801895,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "因为那里是房子，不是家。",
            ["ContentJP"] = "あそこはただの建物。お家じゃないから。",
            ["DialogueId"] = 80050323,
            ["GUID"] = "C865C81E",
            ["NextDialogue"] = 80050324,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C81E",
            },
        [80050324] = {
            ["Camera"] = "-52.174805,-292.937622,109.959473,0.00007,-1.40012,109.791321,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "菲娜的爸爸和妈妈都去了很远很远的国度。都是在八月，都是在暴雨的夜晚。",
            ["ContentJP"] = "フィーナのお父さんとお母さんはね、遠い遠い国に行ってしまったの。8月の、滝みたいな雨が降っていた夜に。",
            ["DialogueId"] = 80050324,
            ["GUID"] = "C865C848",
            ["NextDialogue"] = 80050325,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C848",
            },
        [80050325] = {
            ["Camera"] = "2649.62207,-5001.596191,-1486.966064,7.200227,0.799276,-178.809067,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "爸爸被“坏猎人”带走了，他的脖子上套着绞索，身体挂在天空中。",
            ["ContentJP"] = "お父さんは「悪い狩人」に連れていかれちゃったの。首に縄をかけられて、身体は宙にぶら下がっていた。",
            ["DialogueId"] = 80050325,
            ["FinalCamera"] = "2247.921875,-5009.945801,-1481.363281,7.200307,0.799276,-178.809067,35.000011,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C872",
            ["NextDialogue"] = 80050326,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C872",
            },
        [80050326] = {
            ["Camera"] = "-7238.111328,-5586.991699,-2040.967285,7.243233,-14.796771,-166.212799,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "妈妈被凶猛的“野兽”杀死了，大雨冲刷掉了她像玫瑰一样鲜红的血，什么也不剩。",
            ["ContentJP"] = "お母さんは凶暴な「獣」に殺されたの。バラ色の血は雨で流れて、なんにも残らなかった。",
            ["DialogueId"] = 80050326,
            ["FinalCamera"] = "-7238.111328,-5586.991699,-2040.967285,7.245794,-5.59622,164.383118,35.000015,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C89C",
            ["NextDialogue"] = 80050327,
            ["SpeakNpcId"] = 790017,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C89C",
            },
        [80050327] = {
            ["Camera"] = "-61.800781,64.192169,129.852539,0.000068,-7.399963,-108.799545,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他们去了很远很远的国度……那里已经没有菲娜的家了。",
            ["ContentJP"] = "ふたりとも遠い遠い国に行ってしまったから……もうフィーナのお家はあそこにない。",
            ["DialogueId"] = 80050327,
            ["GUID"] = "C865C8C6",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 80050328,
                [2] = 80050329,
                },
            ["SpeakNpcId"] = 790017,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C8C6",
            },
        [80050328] = {
            ["Content"] = "（摸摸菲娜的头。）",
            ["ContentJP"] = "（フィーナの頭をなでる）",
            ["DialogueId"] = 80050328,
            ["GUID"] = "C865C8F0",
            ["NextDialogue"] = 80050330,
            },
        [80050329] = {
            ["Content"] = "（抱一抱她。）",
            ["ContentJP"] = "（抱きしめる）",
            ["DialogueId"] = 80050329,
            ["GUID"] = "C865C91A",
            ["NextDialogue"] = 80050330,
            },
        [80050330] = {
            ["Camera"] = "-61.800781,64.192169,129.852539,0.000068,-7.399963,-108.799545,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "独角兽{性别：先生|小姐}的手，也暖暖的呢……",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}の手、すっごく温かいのね……",
            ["DialogueId"] = 80050330,
            ["GUID"] = "C865C944",
            ["IsBlack"] = 1,
            ["NextOptions"] = {
                [1] = 80050331,
                },
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C944",
            },
        [80050331] = {
            ["Content"] = "还记得你讲过的“鸟儿和星星”的故事吗？",
            ["ContentJP"] = "前に「鳥が星になるお話」を、してくれたよね？",
            ["DialogueId"] = 80050331,
            ["GUID"] = "C865C96E",
            ["NextDialogue"] = 80050332,
            },
        [80050332] = {
            ["Camera"] = "408.845703,-129.991882,-10.434082,0.000055,3.199656,177.195557,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "菲娜的爸爸和妈妈……也许也变成了天上的星。虽然它们不会说话了，却依旧沉默但温柔地注视着你。",
            ["ContentJP"] = "フィーナのお父さんとお母さんは……夜空のお星さまになったのかも。お話はできなくなったけど、変わらず優しく見守ってくれていると思う。",
            ["DialogueId"] = 80050332,
            ["FinalCamera"] = "408.845703,-129.991882,-10.434082,0.000055,8.599618,177.395554,35.000008,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865C998",
            ["NextDialogue"] = 80050333,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "790017:Explain02_End",
                [2] = "100001:Explain01_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C998",
            },
        [80050333] = {
            ["Content"] = "想他们的时候，就对夜空笑一笑吧。",
            ["ContentJP"] = "だから恋しくなったら、夜空に向かって笑いかけてみよう。",
            ["DialogueId"] = 80050333,
            ["GUID"] = "C865C9C2",
            ["NextDialogue"] = 80050334,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C9C2",
            },
        [80050334] = {
            ["Camera"] = "-101.089844,-114.304626,115.5979,0.000041,2.199259,-98.406013,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯……好……我会试试的。",
            ["ContentJP"] = "うん……わかった……やってみる。",
            ["DialogueId"] = 80050334,
            ["FacialId"] = {
                [1] = "790017:Satisfy01",
                [2] = "100001:Sad01",
                },
            ["GUID"] = "C865C9EC",
            ["NextDialogue"] = 80050335,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:AgreeHead",
                [2] = "100001:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865C9EC",
            },
        [80050335] = {
            ["Camera"] = "-64.15625,-266.238037,110.220703,0.000082,-0.001892,107.984558,35.000015,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "没关系，没关系的，你不要为我难过。因为菲娜现在已经有了新的家。",
            ["ContentJP"] = "大丈夫よ、大丈夫。フィーナのために悲しまないでね。フィーナにはもう、新しいお家があるんだもの。",
            ["DialogueId"] = 80050335,
            ["GUID"] = "C865CA16",
            ["NextDialogue"] = 80050336,
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "790017:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865CA16",
            },
        [80050336] = {
            ["Camera"] = "-109.111328,-35.609192,129.727539,0.000115,-9.201903,-90.815498,35.000015,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我有大魔法师，还有你。现在的我啊，已经很满足了。",
            ["ContentJP"] = "フィーナには大魔法使いと{性别:お兄さん|お姉さん}がいる。今だって、とても満足しているんだから。",
            ["DialogueId"] = 80050336,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
            ["FinalCamera"] = "-109.111328,-35.609192,129.727539,0.000117,-6.401854,-90.81559,35.000015,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C865CA40",
            ["SpeakNpcId"] = 790017,
            ["TalkActionId"] = {
                [1] = "100001:Sad02_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Feina/003/C865CA40",
            },
        [80050401] = {
            ["Camera"] = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
            ["Content"] = "独角兽{性别：先生|小姐}，你来啦。",
            ["ContentJP"] = "ユニコーンの{性别:お兄さん|お姉さん}、来てくれたのね。",
            ["DialogueId"] = 80050401,
            ["FacialId"] = {
                [1] = "790017:Happy02",
                },
