            ["SpeakNpcId"] = 93301,
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B786",
            },
        }
  end },
  { MinKey = 80120440, MaxKey = 80140137, Loader = function()
      return {
        [80120440] = {
            ["Content"] = "嗯，所以我就听它的，回去了。不过还是出了点小状况……",
            ["ContentJP"] = "うん、だから私はニャーゴの言うとおり、街に戻ることにしたんだ。でも……まあ、ちょっとしたハプニングはあったけどね……",
            ["DialogueId"] = 80120440,
            ["GUID"] = "C892B7B0",
            ["LookAt"] = {
                [1] = "93301:p(18000P3)",
                },
            ["NextDialogue"] = 80120442,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B7B0",
            },
        [80120441] = {
            ["Content"] = "呜呜，别骂了别骂了，老马丁都没骂我！说起来那次老头儿难得地担心了一回，因为回去路上出了点小状况……",
            ["ContentJP"] = "うぅ、もう叱らないでよ～！オールドマーティンだってそんなに怒らなかったんだから！……まあ、実は帰り道にちょっとしたトラブルがあって、あのバカ親父も珍しく心配してくれたんだけどさ……",
            ["DialogueId"] = 80120441,
            ["FacialId"] = {
                [1] = "93301:Pain01",
                },
            ["GUID"] = "C892B7DA",
            ["NextDialogue"] = 80120442,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B7DA",
            },
        [80120442] = {
            ["Content"] = "我只闷着头往外跑……根本没记路！我告别了胖尾巴，走着走着就迷了路，越走越累，越走越累，走着走着就……睡着了……",
            ["ContentJP"] = "私はただ夢中で外へ飛び出したから……道なんて全然覚えてなかった！ニャーゴに別れを告げて歩き続けたけど、どんどん道が分からなくなって、どんどん疲れていって……歩いて、歩いて、気づいたら……そのまま寝ちゃってたんだよ……",
            ["DialogueId"] = 80120442,
            ["FacialId"] = {
                [1] = "93301:None",
                },
            ["GUID"] = "C892B804",
            ["NextDialogue"] = 80120443,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B804",
            },
        [80120443] = {
            ["Content"] = "醒来的时候我觉得一颠一颠的，原来是臭老头把我背在背上。他个子不高，但他的背真结实啊，和小时候一样结实。",
            ["ContentJP"] = "目が覚めた時、体がフワフワ揺れててさ……よく見たら、あのバカ親父が私を背負ってたんだよ。あの人、背は高くないけど、背中は昔と変わらずガッシリしてて……少しだけ、安心感を覚えたよ。",
            ["DialogueId"] = 80120443,
            ["FacialId"] = {
                [1] = "93301:Smile01",
                },
            ["GUID"] = "C892B82E",
            ["NextDialogue"] = 80120444,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B82E",
            },
        [80120444] = {
            ["Content"] = "我浑身上下热烘烘的，原来是老头儿用一条围巾把我裹了好几层，连嘴巴都被捂上了。",
            ["ContentJP"] = "体中がぽかぽかしてて、なんでだろうと思ったら……バカ親父が人間みたいに、マフラーで私を何重にもぐるぐる巻きにしてたんだ。おまけに、口までしっかり覆われてて、息苦しいったらありゃしない！",
            ["DialogueId"] = 80120444,
            ["GUID"] = "C892B858",
            ["NextDialogue"] = 80120445,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B858",
            },
        [80120445] = {
            ["Content"] = "于是玛尔洁来到冰湖城之后的第一次城外冒险，就这样稀里糊涂地结束啦。",
            ["ContentJP"] = "こうして、マギーのアイスレイク城に来てから初めての城外冒険は、なんともあっけなく終わっちゃったってわけ。",
            ["DialogueId"] = 80120445,
            ["GUID"] = "C892B882",
            ["NextDialogue"] = 80120446,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B882",
            },
        [80120446] = {
            ["Content"] = "从那以后我就学着如何努力在冰湖城生活，但每次碰到难题，臭老头还是会笑我是“学不会捕猎的胖尾巴二号”。",
            ["ContentJP"] = "その後、私はアイスレイク城でのライフを充実させようと頑張った。なのに、毎回困難にぶつかるたびに、あのバカ親父は「狩りも覚えられないまんまるニャーゴ2号」って笑ってくるんだよね……ぐぬぬぅ。",
            ["DialogueId"] = 80120446,
            ["GUID"] = "C892B8AC",
            ["NextDialogue"] = 80120447,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B8AC",
            },
        [80120447] = {
            ["Content"] = "可他说的不对！胖尾巴最终成为了一个好猎手，而我也学会了如何在这里生存——就像你说的一样，我们都长大了。",
            ["ContentJP"] = "そう、あのバカ親父が言ってることは間違いだよ！だって、まんまるニャーゴは最終的に立派な狩人になったし、私だって街での生き方を身につけた――私たちはちゃんと成長したんだよ。",
            ["DialogueId"] = 80120447,
            ["FacialId"] = {
                [1] = "93301:Confident02",
                },
            ["GUID"] = "C892B8D6",
            ["NextOptions"] = {
                [1] = 801204471,
                },
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B8D6",
            },
        [80120448] = {
            ["Content"] = "不怪我，都怪胖尾巴！谁叫它太阳还没下山就又要走了！我明明在心里说了无数遍“拜托！留下来！”但它们还是走了……",
            ["ContentJP"] = "ち、違う！全部ニャーゴのせいだよ！まだ太陽も沈んでないのに、また行っちゃうんだもん！心の中で何度も何度も「お願いだから、ここにいて！」って叫んだけど……それでも、あの子たちは行っちゃったんだ……",
            ["DialogueId"] = 80120448,
            ["FacialId"] = {
                [1] = "93301:Smile01",
                },
            ["GUID"] = "C892B900",
            ["NextDialogue"] = 80120449,
            ["SpeakNpcId"] = 93301,
            ["TalkActionId"] = {
                [1] = "93301:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B900",
            },
        [80120449] = {
            ["Content"] = "……算了，不找借口了！到下次，我和胖尾巴的下一次见面，我会笑着和它说再见的！",
            ["ContentJP"] = "……言い訳はやめた！今度まんまるニャーゴと再会したら、笑顔でバイバイするから！",
            ["DialogueId"] = 80120449,
            ["FacialId"] = {
