            ["GUID"] = "C892B92A",
            ["SpeakNpcId"] = 93301,
            ["VoiceName"] = "voice/$Locale$/inv/Maer/004/C892B92A",
            },
        [80130000] = {
            ["Content"] = "你好……希望我的到访没有打扰到你……",
            ["ContentJP"] = "あ、その、こんにちは……お邪魔じゃないと、良いのですが……",
            ["DialogueId"] = 80130000,
