            ["VoiceName"] = "voice/$Locale$/inv/Yeer/001/C898E95A",
            },
        [80130106] = {
            ["Content"] = "那我再在这里待一会儿……",
            ["ContentJP"] = "じゃ、じゃあ……もう少しだけ……",
            ["DialogueId"] = 80130106,
            ["FacialId"] = {
                [1] = "93103:Iyada01",
                },
            ["GUID"] = "C898E984",
            ["NextDialogue"] = 80130108,
            ["SpeakNpcId"] = 93103,
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/001/C898E984",
            },
        [80130107] = {
            ["Content"] = "你……看起来有点不高兴的样子，是因为我太没礼貌了吗，对不起，我不是有意的……",
            ["ContentJP"] = "ふ、不機嫌な顔……もしかして、何か気に障るようなこと……ご、ごめんなさい！わざとじゃ……",
            ["DialogueId"] = 80130107,
            ["FacialId"] = {
                [1] = "93103:Iyada01",
                },
            ["GUID"] = "C898E9AE",
