        [80130111] = {
            ["Content"] = "怕什么，你看{性别：他|她}又不吃人，像正常对待小朋友那样说话就好了。",
            ["ContentJP"] = "何も取って食われるわけじゃあるまいし、ガキと接する時みたく話しゃあいいだろ。",
            ["DialogueId"] = 80130111,
            ["FacialId"] = {
