            },
        [80130112] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80130112,
            ["FacialId"] = {
                [1] = "93103:None",
                },
            ["GUID"] = "C898EA80",
            ["LookAt"] = {
                [1] = "93103:p(18000P2)",
                },
            ["NextDialogue"] = 80130113,
            ["SpeakNpcId"] = 93103,
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/001/C898EA80",
            },
        [80130113] = {
            ["Content"] = "你说这话的时候一点都不吓人，是想要让我放松下来吧，谢谢你。",
            ["ContentJP"] = "その、全然怖くないですよ。でも、ありがとうございます。おかげで少し落ち着きました。",
            ["DialogueId"] = 80130113,
            ["FacialId"] = {
