            ["GUID"] = "C898EAAA",
            ["LookAt"] = {
                [1] = "93103:p(18000P3)",
                },
            ["NextDialogue"] = 80130115,
            ["SpeakNpcId"] = 93103,
            ["TalkActionId"] = {
                [1] = "93103:Sit_DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/001/C898EAAA",
            },
        [80130114] = {
            ["Content"] = "治……治愈系狩月人？虽然没有听说这个称号，但你确实和我想象中那种个子巨大，说话声音比炸弹还要大的狩月人不太一样。",
            ["ContentJP"] = "い……癒し系月狩り人？そんなのあるんですね、初耳です。でも、あなたは確かに、頭でっかちで声が爆弾より大きい月狩り人とは、どこか違う気がします。",
            ["DialogueId"] = 80130114,
            ["FacialId"] = {
                [1] = "93103:Shock01",
                },
            ["GUID"] = "C898EAD4",
            ["LookAt"] = {
                [1] = "93103:p(18000P3)",
                },
            ["NextDialogue"] = 80130115,
            ["SpeakNpcId"] = 93103,
            ["TalkActionId"] = {
                [1] = "93103:Sit_Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/001/C898EAD4",
            },
        [80130115] = {
            ["Content"] = "那么，让我来介绍一下吧，他是奥利弗，我的朋友。被一个炼金术师给关在了这颗炸弹里。",
            ["ContentJP"] = "では、改めて自己紹介を……彼はオリバー、僕の友達です。錬金術師によって、この爆弾の中に閉じ込められてしまったんです。",
            ["DialogueId"] = 80130115,
            ["FacialId"] = {
