            ["SpeakNpcId"] = 93103,
            ["TalkActionId"] = {
                [1] = "93103:Sit_Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/001/C898EAFE",
            },
        [80130116] = {
            ["Content"] = "刚刚我说到的“噼里啪啦”，实际上是我和他一起开的，我负责招待客人，他负责思考新产品。",
            ["ContentJP"] = "さっき話した「ドンパチ」も、彼と開いた店で、その、僕はお客さんの接待を、オリバーは、新しい商品の開発をやってます。",
            ["DialogueId"] = 80130116,
            ["FacialId"] = {
                [1] = "93103:Smile01",
