            ["ToFinalCameraBlendTime"] = 7,
            ["TurnTo"] = {
                [1] = "790023:n(790024)",
                [2] = "100001:n(790024)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991ABC",
            },
        [80130407] = {
            ["Camera"] = "-186.759766,-187.0,106.0,0.0,0.0,20.397503,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "奥利弗，原来你在的啊……",
            ["ContentJP"] = "オリバー……いたんだね。",
            ["DialogueId"] = 80130407,
            ["FacialId"] = {
                [1] = "790023:Shock01",
                },
            ["GUID"] = "C8991AE6",
            ["NextDialogue"] = 80130408,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991AE6",
            },
        [80130408] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "是的，我一直在。",
            ["ContentJP"] = "ああ、ずっとな。",
