        [80130412] = {
            ["Camera"] = "-315.086426,-472.144592,127.0,-0.0,-4.000004,58.795139,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "说什么蠢话！",
            ["ContentJP"] = "何言ってんだ！？",
            ["DialogueId"] = 80130412,
            ["GUID"] = "C8991BB8",
            ["NextDialogue"] = 80130413,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991BB8",
            },
        [80130413] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只是在等人道歉罢了。",
            ["ContentJP"] = "誰かさんの謝罪を待ってるんだよ。",
            ["DialogueId"] = 80130413,
            ["GUID"] = "C8991BE2",
            ["NextDialogue"] = 80130415,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TurnTo"] = {
                [1] = "790024:n(790023)",
                [2] = "790023:n(790024)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991BE2",
            },
        [80130414] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我没有什么憋在心里的，但是我觉得耶尔有。",
            ["ContentJP"] = "俺はないぜ。だが、イェールの方はどうなんだ？",
            ["DialogueId"] = 80130414,
            ["FacialId"] = {
                [1] = "790023:None",
                },
            ["GUID"] = "C8991C0C",
            ["LookAt"] = {
                [1] = "790024:n(790023)",
                [2] = "790023:n(790024)",
                },
            ["NextDialogue"] = 80130415,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991C0C",
            },
        [80130415] = {
            ["Camera"] = "-306.0,-179.0,112.583984,0.000004,-2.799988,17.994236,36.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对不起……我又想要把这副身体还给你。",
            ["ContentJP"] = "ごめんね……僕は、今度こそこの身体を返そうとした。",
            ["DialogueId"] = 80130415,
            ["FacialId"] = {
                [1] = "790023:Sad01",
                },
            ["GUID"] = "C8991C36",
            ["NextDialogue"] = 80130416,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Disagree",
                [2] = "790024:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991C36",
            },
        [80130416] = {
            ["Camera"] = "-306.0,-179.0,112.583984,0.000004,-2.799988,17.994236,36.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但从我知道你是这副身体原本的主人的时候，就已经下定了决心，要这么做。",
            ["ContentJP"] = "君がこの身体の本来の主だってわかった時から、僕は決心してたんだ。こうするってね。",
            ["DialogueId"] = 80130416,
            ["GUID"] = "C8991C60",
            ["NextDialogue"] = 80130417,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991C60",
            },
        [80130417] = {
            ["Camera"] = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "只是那时候还有琼斯在，我知道他对你的恶意，所以必须要先离开他，先到外面的世界才行。",
            ["ContentJP"] = "ジョーンズがいた時、彼の君に対する悪意は感じてた。だから、まずはあの人から離れる必要があったんだ。",
            ["DialogueId"] = 80130417,
            ["FacialId"] = {
                [1] = "790023:Unhappy01",
                },
            ["GUID"] = "C8991C8A",
            ["NextDialogue"] = 80130418,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991C8A",
            },
        [80130418] = {
            ["Camera"] = "353.637695,44.699951,122.273438,0.0,0.0,15.598783,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我也不知道外面的世界是什么样的，那时候我的记忆里只有一个总是开着灯的房间，满是消毒水的味道。",
            ["ContentJP"] = "僕も外の世界がどんなのかは、正直わからなかった。その時、僕の記憶にあったのは、いつも明かりが灯っている、消毒液の匂いが充満した部屋だけだったから。",
            ["DialogueId"] = 80130418,
            ["FinalCamera"] = "353.637695,60.0,122.273438,0.0,0.0,15.598783,35.0,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8991CB4",
            ["NextDialogue"] = 80130419,
            ["SpeakNpcId"] = 790023,
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991CB4",
            },
        [80130419] = {
            ["Camera"] = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "琼斯和我说外面的世界非常危险，都是凶恶的卡戎，所以必须一直待在这个房间里。但我读到的书里并不是这样说的。",
            ["ContentJP"] = "外の世界はとても危険で、凶暴なカロンたちがいる。だから、この部屋を離れてはいけないって、ずっとジョーンズおじいさんに言われていた。でも、僕が読んだ本には、そうは書かれていなかった。",
            ["DialogueId"] = 80130419,
            ["FacialId"] = {
                [1] = "790023:None",
                },
            ["GUID"] = "C8991CDE",
            ["NextDialogue"] = 80130420,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790023},AnimationId{\"Talk02_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790023},AnimationId{\"Talk02_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790023,
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991CDE",
            },
        [80130420] = {
            ["Camera"] = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那本书有趣极了，它说水的温度降到一定地步会变成冰，我没有见过，但那个叫做冰湖城的地方附近都是冰，还有雪。",
            ["ContentJP"] = "その本はすごく面白かった。水の温度がある一定のレベルまで下がると、氷に変わるって書いてあったんだ。実際に見たことはないけど、「アイスレイク城」ってところは、周りが全部氷と雪で覆われているって載ってたんだ。",
            ["DialogueId"] = 80130420,
            ["FacialId"] = {
                [1] = "790023:Happy01",
                },
            ["GUID"] = "C8991D08",
            ["NextDialogue"] = 80130421,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790023},AnimationId{\"Think_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790023},AnimationId{\"Think_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790023,
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991D08",
            },
        [80130421] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "还提到一个叫做丹流城的地方，城外的河水看起来是红色的，当落日的时候，会非常漂亮。",
            ["ContentJP"] = "その本には、もう一つ「レッドバリー城」って場所が載ってた。城外の川の水は赤く見えるらしく、特に夕日が沈む時にはすごく美しいんだって。",
            ["DialogueId"] = 80130421,
            ["FacialId"] = {
                [1] = "790023:Happy02",
                },
            ["GUID"] = "C8991D32",
            ["NextDialogue"] = 80130422,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk02R_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991D32",
            },
        [80130422] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那时候我见过的红色的事物只有血，所以觉得很奇怪，红色……怎么会漂亮呢？",
            ["ContentJP"] = "その時、僕が見た赤いものと言えば血だけだったから、ずっと信じられなかったんだ。赤い色のものが……美しいなんてね。",
            ["DialogueId"] = 80130422,
            ["FacialId"] = {
                [1] = "790023:None",
                },
            ["GUID"] = "C8991D5C",
            ["NextDialogue"] = 80130423,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991D5C",
            },
        [80130423] = {
            ["Camera"] = "-303.0,-180.0,112.583984,0.000004,-2.799988,17.9942,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "于是，我的心里又多了一个自私的愿望，等我见到了冰湖城的雪和丹流城的落日之后，再把身体还给奥利弗。",
            ["ContentJP"] = "僕の心にまた一つ、わがままな願いが芽生えてしまった。アイスレイク城の雪とレッドバリー城の夕日が見れたら、オリバーに身体を返そうって決めたんだ。",
            ["DialogueId"] = 80130423,
            ["FacialId"] = {
                [1] = "790023:Satisfy01",
                },
            ["GUID"] = "C8991D86",
            ["NextDialogue"] = 80130424,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991D86",
            },
        [80130424] = {
            ["Camera"] = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "现在，它们已经都实现了，雪的白色，落日的红色，我都看到了，记得清清楚楚，所以……",
            ["ContentJP"] = "白い雪も、赤い夕日も、そのすべてはもうちゃんと見たんだよ。はっきりと覚えてる。だから......",
            ["DialogueId"] = 80130424,
            ["FacialId"] = {
                [1] = "790023:None",
                },
            ["GUID"] = "C8991DB0",
            ["NextDialogue"] = 80130425,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991DB0",
            },
        [80130425] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了你不要再说了。",
            ["ContentJP"] = "わかったから、もう何も言うな。",
            ["DialogueId"] = 80130425,
            ["GUID"] = "C8991DDA",
            ["NextDialogue"] = 80130426,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991DDA",
            },
        [80130426] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "真是想不到有一天有人能顶着我的脸能说出这些话来，我都开始敬佩老琼斯的研究了。",
            ["ContentJP"] = "俺の顔でそんな甘っちょろいこと言うんじゃねぇよ。気持ち悪いだろーが！ここまでくると、ジョーンズの研究に感服してきたぜ。",
            ["DialogueId"] = 80130426,
            ["GUID"] = "C8991E04",
            ["NextDialogue"] = 80130427,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991E04",
            },
        [80130427] = {
            ["Camera"] = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我能理解你，我也不想欠着人什么东西，所以当你让琼斯拿走那台聒噪的唱片机的时候，在心里就觉得你已经还了我半条命。",
            ["ContentJP"] = "まあ、その気持ちは分かるぜ。俺も誰かに借りを作りたくないからな。お前がジョーンズにあのうるさい蓄音機を押し返した時から、この命を半分お前にくれてやると決めたんだ。",
            ["DialogueId"] = 80130427,
            ["GUID"] = "C8991E2E",
            ["NextDialogue"] = 80130428,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991E2E",
            },
        [80130428] = {
            ["Camera"] = "-306.0,-179.0,112.583984,0.000004,-2.799988,17.994255,36.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "等到后来，我们一起挣扎着逃出来的时候，就已经互不相欠了。",
            ["ContentJP"] = "あの部屋から逃げ出せた時点で、お互いチャラだったよ。",
            ["DialogueId"] = 80130428,
            ["GUID"] = "C8991E58",
            ["NextDialogue"] = 80130429,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790024},AnimationId{\"Explain01_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790024},AnimationId{\"Explain01_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991E58",
            },
        [80130429] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "但现在你又开始欠我东西了：就在你失去意识的几天里，我勉强应付了几个来“噼里啪啦”嚷嚷着买玩具的小孩子。",
            ["ContentJP"] = "だが、今回の件でまた俺に借りができちまったな。お前がいない間、「ドンパチ」でギャーギャー騒ぐガキをなだめるのにどれほど苦労したか、知ってるか？",
            ["DialogueId"] = 80130429,
            ["FacialId"] = {
                [1] = "790024:Yeer_EyeChangedSad",
                },
            ["GUID"] = "C8991E82",
            ["NextDialogue"] = 80130430,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790024},AnimationId{\"Sigh_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790024},AnimationId{\"Sigh_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991E82",
            },
        [80130430] = {
            ["Camera"] = "138.503418,-201.674438,112.0,0.000002,-2.799927,155.996429,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "他们可都是找你的，我应付不来他们。还得假扮成你的性格，忍住不骂人，好声好气把他们哄走。",
            ["ContentJP"] = "あいつら、お前がいいって泣きわめくんだ。この俺が、お前みたいに猫撫で声でガキに話すとこ、想像がつくか？",
            ["DialogueId"] = 80130430,
            ["FacialId"] = {
                [1] = "790024:Yeer_EyeChanged",
                },
            ["GUID"] = "C8991EAC",
            ["NextDialogue"] = 80130431,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991EAC",
            },
        [80130431] = {
            ["Content"] = "然后到了冰湖城，又是费口舌，又是费心地回忆之前的惨痛记忆，和{nickname}讲明白来龙去脉。",
            ["ContentJP"] = "その上、アイスレイク城まで駆けつけて、{nickname}に経緯を理解させるために、昔のつらい思い出を全部掘り返したんだ。",
            ["DialogueId"] = 80130431,
            ["GUID"] = "C8991ED6",
            ["NextDialogue"] = 80130432,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991ED6",
            },
        [80130432] = {
            ["Camera"] = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "这些，可不是你把身体还给我就能轻易了结的。",
            ["ContentJP"] = "身体の所有権程度で返せる借りじゃねぇって、分かるよな？",
            ["DialogueId"] = 80130432,
            ["GUID"] = "C8991F00",
            ["NextDialogue"] = 80130433,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991F00",
            },
        [80130433] = {
            ["Content"] = "并且最关键的是，你也从来没有问过我的意见：",
            ["ContentJP"] = "それに何よりも、一度でも俺の意見を聞いたか？",
            ["DialogueId"] = 80130433,
            ["GUID"] = "C8991F2A",
            ["NextDialogue"] = 80130434,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991F2A",
            },
        [80130434] = {
            ["Camera"] = "-55.089355,-146.949646,115.0,0.0,0.0,167.992569,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "对于奥利弗来说，耶尔既是恩人，也是欠着我人情的人，还是不可代替的朋友，一样都是”噼里啪啦“的主人。",
            ["ContentJP"] = "<Default note=\"text:お前\">イェール</>は<Default note=\"text:俺\">オリバー</>にとっての恩人であり、借りがある存在であり、そして――「ドンパチ」のもう一人の店主だ。",
            ["DialogueId"] = 80130434,
            ["FacialId"] = {
                [1] = "790024:Yeer_EyeChangedSad",
                },
            ["GUID"] = "C8991F54",
            ["NextDialogue"] = 80130435,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991F54",
            },
        [80130435] = {
            ["Camera"] = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "所以，不要再说对不起了，真觉得对不起的话，就一起把店开下去，有的是你偿还的机会。",
            ["ContentJP"] = "だから、もう謝るな。申し訳ないって思うんなら、一緒に店を手伝え。償いの機会など、いやって言うほどくれてやるから。",
            ["DialogueId"] = 80130435,
            ["GUID"] = "C8991F7E",
            ["NextDialogue"] = 80130436,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790024:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991F7E",
            },
        [80130436] = {
            ["Camera"] = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80130436,
            ["GUID"] = "C8991FA8",
            ["LookAt"] = {
                [1] = "790023:p(79002GP)",
                },
            ["NextDialogue"] = 80130437,
            ["SpeakNpcId"] = 790023,
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991FA8",
            },
        [80130437] = {
            ["Camera"] = "-303.0,-180.0,112.583984,0.000004,-2.799988,17.9942,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "嗯，好，你说的对……如果现在把身体还给你的话，“噼里啪啦”可就开不下去了。",
            ["ContentJP"] = "うん、そうだね……僕が消えちゃったら、「ドンパチ」は続けられなくなっちゃうよね。",
            ["DialogueId"] = 80130437,
            ["FacialId"] = {
                [1] = "790024:Yeer_EyeChanged",
                [2] = "790023:Smile01",
                },
            ["GUID"] = "C8991FD2",
            ["LookAt"] = {
                [1] = "790023:n(790024)",
                },
            ["NextDialogue"] = 80130438,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991FD2",
            },
        [80130438] = {
            ["Camera"] = "-303.0,-180.0,112.583984,0.000004,-2.799988,17.9942,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "以及，我在书上还看到过其他几个很好看的地方。其实，我也想去那些地方看一看。",
            ["ContentJP"] = "それに……実はまだ行きたい場所がいくつかあったんだ。前に本で見ただけなんだけど。",
            ["DialogueId"] = 80130438,
            ["GUID"] = "C8991FFC",
            ["NextDialogue"] = 80130439,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8991FFC",
            },
        [80130439] = {
            ["Camera"] = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "行啊，我们一起去看。不过要答应我，可别再和这次一样，看完后又冒出把身体还给我之类的笨蛋想法了。",
            ["ContentJP"] = "へぇ、いいじゃん。今度一緒に行こうぜ。だが、見終わった後でまた身体を返すなんて、なしだからな。",
            ["DialogueId"] = 80130439,
            ["GUID"] = "C8992026",
            ["NextDialogue"] = 80130440,
            ["SpeakNpcId"] = 790024,
            ["SpeakNpcName"] = "UI_Npc_Name_Oliver",
            ["TalkActionId"] = {
                [1] = "790023:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8992026",
            },
        [80130440] = {
            ["Camera"] = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不会的，再也不会了。我们回去吧，还有小朋友等着“噼里啪啦”营业呢。",
            ["ContentJP"] = "うん、もう絶対言わないよ。帰ろう、オリバー。きっと、子どもたちが「ドンパチ」の開店を待ってるよ。",
            ["DialogueId"] = 80130440,
            ["FacialId"] = {
                [1] = "790023:Happy02",
                },
            ["GUID"] = "C8992050",
            ["NextDialogue"] = 80130441,
            ["SpeakNpcId"] = 790023,
            ["TalkActionId"] = {
                [1] = "790023:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C8992050",
            },
        [80130441] = {
            ["Camera"] = "-315.086426,-472.144592,127.0,-0.0,-4.000004,58.795139,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "也谢谢你，{nickname}，等回去后，我们送一批免费的小可爱给你！",
            ["ContentJP"] = "それから、{nickname}さん。ありがとうございました。後ほど、「キュートちゃん」を一つ送りますね。もちろん、タダです。",
            ["DialogueId"] = 80130441,
            ["GUID"] = "C899207A",
            ["NextOptions"] = {
                [1] = 801304411,
                },
            ["SpeakNpcId"] = 790023,
            ["TurnTo"] = {
                [1] = "100001:n(790023)",
                [2] = "790023:n(100001)",
                [3] = "790024:n(100001)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C899207A",
            },
        [80130443] = {
            ["Content"] = "漫长的白天过去，随之而来的，并非是同样漫长的黑夜，而天际边缘，晨晖即将出现。",
            ["ContentJP"] = "長く感じられた一日がようやく終わりを迎えた。\
訪れたのは、同じように長い夜ではなく、遠くの空の端にほんのりと光が差し込み始めている。\
まるで新たな一日の始まりを告げるかのような、朝日の兆しだった。",
            ["DialogueId"] = 80130443,
            ["GUID"] = "C89920CE",
            ["VoiceName"] = "voice/$Locale$/inv/Yeer/004/C89920CE",
            },
        [80140101] = {
            ["Content"] = "你是谁？",
            ["ContentJP"] = "君は誰……？",
            ["DialogueId"] = 80140101,
            ["Duration"] = 3,
            ["GUID"] = "C89F5152",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5152",
            },
        [80140102] = {
            ["Content"] = "你在做什么？",
            ["ContentJP"] = "何をしてるの？",
            ["DialogueId"] = 80140102,
            ["Duration"] = 3,
            ["GUID"] = "C89F517C",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F517C",
            },
        [80140103] = {
            ["Camera"] = "308.258453,-324.54126,203.320312,0.000018,-13.199941,134.196289,45.171967,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "告诉我，帕西法尔，发生了什么事？是谁割断了你的角？",
            ["ContentJP"] = "パシファル、教えて。一体何があったの？あなたの角を折ったのは誰なの？",
            ["DialogueId"] = 80140103,
            ["FacialId"] = {
                [1] = "790031:CM_Angry01",
                [2] = "790030:Disappoint01",
                },
            ["GUID"] = "C89F51A6",
            ["LookAt"] = {
                [1] = "790031:n(790030)",
                },
            ["NextDialogue"] = 80140104,
            ["Scripts"] = "SetLocation{ActorId{790032},TargetPoint{\"SetPoint_Puqi\"},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F51A6",
            },
        [80140104] = {
            ["Camera"] = "-311.42627,-48.326935,136.539062,0.000017,-3.399344,6.607203,41.865784,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我不管外面的人怎么想、怎么做，但是一切霸凌行径在“魔笛”剧团都是绝对禁止的——我们不能让愚蠢的歧视和仇恨玷污高贵的艺术！",
            ["ContentJP"] = "世間の目や意見なんて、私にはどうでもいいの。でも、「マジックフルート」においては、いかなるいじめも許されないわ！馬鹿げた差別や憎しみは――高潔な芸術を汚す行為よ！",
            ["DialogueId"] = 80140104,
            ["GUID"] = "C89F51D0",
            ["LookAt"] = {
                [1] = "790031:n(790030)",
                },
            ["NextDialogue"] = 80140105,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F51D0",
            },
        [80140105] = {
            ["Content"] = "不用害怕，帕西法尔，你只要如实说出真相就好。我保证剧团会做出公正的处理，将霸凌者除名。",
            ["ContentJP"] = "怖がらないで、パシファル。ただ事実をありのままに話してくれればいいの。誰であれ公正に処罰するわ。その者は必ず除名されると約束しましょう。",
            ["DialogueId"] = 80140105,
            ["GUID"] = "C89F51FA",
            ["LookAt"] = {
                [1] = "790031:n(790030)",
                },
            ["NextDialogue"] = 80140106,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F51FA",
            },
        [80140106] = {
            ["Camera"] = "-60.211216,-179.25705,55.679688,0.000037,18.399382,95.598686,58.124969,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "“不能让愚蠢的歧视和仇恨玷污高贵的艺术”——老师，如果剧团没有“卡戎之民不能作为演员登上舞台”这条潜规则，我真的会相信。",
            ["ContentJP"] = "「愚馬鹿げた差別や憎しみは高潔な芸術を汚す行為」か――劇団に「カロン族は俳優として舞台に立てない」なんて暗黙のルールがなければ、信じるとこでしたよ。",
            ["DialogueId"] = 80140106,
            ["GUID"] = "C89F5224",
            ["NextDialogue"] = 80140107,
            ["Scripts"] = "LookAt{_delay{6},LookAtDescription{\"790030:n(790031)\"}}",
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5224",
            },
        [80140107] = {
            ["Camera"] = "-64.211678,-24.009537,132.21875,0.000007,2.199819,-2.797291,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那是因为……！",
            ["ContentJP"] = "それは……！",
            ["DialogueId"] = 80140107,
            ["FacialId"] = {
                [1] = "790031:CM_Shock01",
                },
            ["GUID"] = "C89F524E",
            ["LookAt"] = {
                [1] = "790030:n(790031)",
                },
            ["NextDialogue"] = 80140108,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F524E",
            },
        [80140108] = {
            ["Camera"] = "285.028381,-293.271179,282.699219,0.000063,-23.799669,134.202179,35.63834,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……抱歉，老师！请原谅我刚才的口不择言。",
            ["ContentJP"] = "……あ、ごめんなさい！僕、なんて失礼なことを……",
            ["DialogueId"] = 80140108,
            ["FinalCamera"] = "249.140015,-256.372009,260.007812,0.000063,-23.799669,134.202179,35.63834,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F5278",
            ["NextDialogue"] = 80140109,
            ["SpeakNpcId"] = 790030,
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5278",
            },
        [80140109] = {
            ["Content"] = "我没有质疑您的意思。我知道您教导我们时，从不因我们是索拉还是卡戎而有所偏私。狭隘傲慢的只是那些观众而已。",
            ["ContentJP"] = "先生を疑っているわけではありません。先生はソラであろうとカロンであろうと、偏見を持たず接してくれました。自己中で傲慢なのは、観客たちだけだってわかってます。",
            ["DialogueId"] = 80140109,
            ["GUID"] = "C89F52A2",
            ["NextDialogue"] = 80140110,
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F52A2",
            },
        [80140110] = {
            ["Content"] = "剧团的朋友都很友善，没有人霸凌我。头上的角，是<H>我自己</>切断的。",
            ["ContentJP"] = "劇団のみんなもとても優しくて、いじめられたことはありません。この角は、<H>自分で</>切り落としたんです。",
            ["DialogueId"] = 80140110,
            ["GUID"] = "C89F52CC",
            ["NextDialogue"] = 80140111,
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F52CC",
            },
        [80140111] = {
            ["Content"] = "……你……",
            ["ContentJP"] = "……なっ……",
            ["DialogueId"] = 80140111,
            ["GUID"] = "C89F52F6",
            ["NextDialogue"] = 80140112,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F52F6",
            },
        [80140112] = {
            ["Camera"] = "3689.480957,-784.508362,319.140625,0.000159,7.198042,-109.808243,11.909616,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我想要上台表演，老师。我想用自己的喉咙唱出歌词，我想用自己的眼睛看见观众。我想走进那个被聚光灯照亮的世界……",
            ["ContentJP"] = "先生、僕は舞台に立ちたいんです。自分の声で歌詞を歌い、自分の目で観客を見て、スポットライトに照らされたあの世界に踏み入れたいんです……",
            ["DialogueId"] = 80140112,
            ["FinalCamera"] = "3452.359619,-1442.865723,407.496094,0.000159,7.198042,-109.808243,11.909616,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F5320",
            ["NextDialogue"] = 80140113,
            ["SpeakNpcId"] = 790030,
            ["TalkActionId"] = {
                [1] = "790031:Shock_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5320",
            },
        [80140113] = {
            ["Camera"] = "-79.301102,-133.298798,120.894531,0.000185,-0.201231,89.005852,42.56609,134.092804,false,Manual,2.8",
            ["Content"] = "只要没有这双“恶魔角”，我就可以上台了，对吧？",
            ["ContentJP"] = "この「悪魔の角」さえなければ、僕も舞台に立てるんですよね？",
            ["DialogueId"] = 80140113,
            ["GUID"] = "C89F534A",
            ["NextDialogue"] = 80140114,
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F534A",
            },
        [80140114] = {
            ["Camera"] = "-72.874443,-96.31089,142.296875,0.000143,-1.001825,22.198147,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "傻孩子……",
            ["ContentJP"] = "なんてバカなことを……",
            ["DialogueId"] = 80140114,
            ["FacialId"] = {
                [1] = "790031:CM_Sad01",
                },
            ["GUID"] = "C89F5374",
            ["LookAt"] = {
                [1] = "790031:n(790030)",
                },
            ["NextDialogue"] = 80140115,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5374",
            },
        [80140115] = {
            ["Camera"] = "-39.245445,-88.370117,65.621094,0.000033,23.998367,110.798157,35.000011,76.612511,false,Manual,9.097586",
            ["Content"] = "只是，切断自己身体的一部分的确很疼。请再给我一些时间，我一定会把剩下的残角也——",
            ["ContentJP"] = "ただ、角は身体の一部なので、切り落とすのはすごく痛いんです。もう少しだけ時間をください。残りの部分も必ず……",
            ["DialogueId"] = 80140115,
            ["GUID"] = "C89F539E",
            ["NextDialogue"] = 80140116,
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F539E",
            },
        [80140116] = {
            ["Camera"] = "-272.279846,-55.369659,98.152344,0.000052,2.598238,8.203966,35.000011,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "不要说了！也不要再动你的角。",
            ["ContentJP"] = "やめて！これ以上、自分を傷つけちゃダメよ！",
            ["DialogueId"] = 80140116,
            ["GUID"] = "C89F53C8",
            ["NextDialogue"] = 80140117,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F53C8",
            },
        [80140117] = {
            ["Content"] = "……我明白了。下一场《雪国的孩子》，你和苏珊娜、费恩一起上。你来当主演，饰演“无名的妖精”。",
            ["ContentJP"] = "……わかったわ。次の公演『雪国の幼子』は、あなたとスザンナ、フェインと一緒に出演してもらうわ。あなたは主役の「無名の妖精」を演じてちょうだい。",
            ["DialogueId"] = 80140117,
            ["GUID"] = "C89F53F2",
            ["NextDialogue"] = 80140118,
            ["Scripts"] = "PlayAnimation{_delay{3},ActorId{790031},AnimationId{\"Talk03_End\"},Duration{2},_click{false}},",
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F53F2",
            },
        [80140118] = {
            ["Camera"] = "269.129089,-303.197998,134.738281,0.000062,-1.001852,131.806335,42.862888,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……您说什么？",
            ["ContentJP"] = "……えっ、先生、今なんて？",
            ["DialogueId"] = 80140118,
            ["FacialId"] = {
                [1] = "790030:Shock01",
                },
            ["GUID"] = "C89F541C",
            ["LookAt"] = {
                [1] = "790030:n(790031)",
                },
            ["NextDialogue"] = 80140119,
            ["Scripts"] = "SitOrStand{ActorId{790030},State{\"Stand\"}}",
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F541C",
            },
        [80140119] = {
            ["Camera"] = "-475.37677,-270.540131,435.15625,0.000049,-28.199356,17.585888,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "薇奥莱塔！我大老远就听到你在说荒唐话——让帕西法尔当主演？",
            ["ContentJP"] = "ヴィオレッタ！聞こえたぞ――パシファルを主役にするですって？",
            ["DialogueId"] = 80140119,
            ["FacialId"] = {
                [1] = "790030:None",
                },
            ["FinalCamera"] = "-475.37677,-270.540131,403.910156,0.000049,-28.199356,17.585888,25.000002,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F5446",
            ["LookAt"] = {
                [1] = "790030:n(790032)",
                [2] = "790032:n(790031)",
                },
            ["NextDialogue"] = 80140120,
            ["Scripts"] = "MoveTo{ActorId{790032},MoveSpeed{80},TargetPoint{\"P80140120\"}}",
            ["SpeakNpcId"] = 790032,
            ["ToFinalCameraBlendTime"] = 15,
            ["TurnTo"] = {
                [1] = "790031:n(790032)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5446",
            },
        [80140120] = {
            ["Content"] = "你疯了吗？第二天，“魔笛”剧团用卡戎当主演的消息就会传遍冰湖城的大街小巷！我们剧团几十年的名誉——",
            ["ContentJP"] = "正気か？翌日には、「マジックフルート」劇団がカロンを主演にしたって噂がアイスレイク中に広まるぞ！劇団が築き上げてきた数十年の名声が――！",
            ["DialogueId"] = 80140120,
            ["GUID"] = "C89F5470",
            ["LookAt"] = {
                [1] = "790031:n(790032)",
                },
            ["NextDialogue"] = 80140121,
            ["SpeakNpcId"] = 790032,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5470",
            },
        [80140121] = {
            ["Camera"] = "141.589691,-501.412964,133.425781,0.000001,-0.599643,94.196159,52.004452,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "放轻松点，团长。既然是妖精，头上有些装饰也很合理，对吧？我们可以拜托道具师设计更夸张的头饰，这样就没人会发现帕西法尔是卡戎了。",
            ["ContentJP"] = "落ち着いてください、団長。妖精役なら、頭に装飾があっても不思議じゃないでしょう？道具師に頼んで、派手な髪飾りを作ってもらえば、誰もパシファルがカロンだなんて気づきませんよ。",
            ["DialogueId"] = 80140121,
            ["FacialId"] = {
                [1] = "790031:CM_Smile01",
                },
            ["GUID"] = "C89F549A",
            ["LookAt"] = {
                [1] = "790031:n(790032)",
                },
            ["NextDialogue"] = 80140122,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790031},AnimationId{\"Explain02_Start\"},Duration{2}},\
PlayAnimation{_delay{3},ActorId{790031},AnimationId{\"Explain02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F549A",
            },
        [80140122] = {
            ["Content"] = "您放心，其他演职人员就由我来说服，不会让您为难。如果真的出了什么事，您就一口咬定剧团的其他人都是受了我的威胁。",
            ["ContentJP"] = "安心してください、他のスタッフは私が説得しますから。絶対に団長を困らせたりしませんって。もし本当に何かあったら、私に脅されたとでも言ってください。",
            ["DialogueId"] = 80140122,
            ["GUID"] = "C89F54C4",
            ["NextDialogue"] = 80140123,
            ["Scripts"] = "SEQ{\
PlayAnimation{_delay{1.5},ActorId{790031},AnimationId{\"Disagree\"},Duration{2},_delay{2}},\
PlayAnimation{_delay{1.5},ActorId{790031},AnimationId{\"Explain01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F54C4",
            },
        [80140123] = {
            ["Camera"] = "141.589691,-501.412964,133.425781,0.000001,-0.599643,94.196159,52.004452,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "更何况，您知道的，帕西法尔才是剧团最优秀的歌者，他的天赋甚至超过了年轻时的我。否则，您也不会一直让他在幕后献唱。",
            ["ContentJP"] = "それに、団長もご存じでしょう？パシファル以上に優れた俳優はいません。彼の才能は、若い頃の私さえ超えている。それを見込んだ上で、毎回舞台裏で歌わせていたのは知ってますよ。",
            ["DialogueId"] = 80140123,
            ["FinalCamera"] = "141.589691,-501.412964,133.425781,0.0,-0.399709,105.796799,52.004452,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F54EE",
            ["LookAt"] = {
                [1] = "790031:n(790030)",
                [2] = "790032:n(790030)",
                },
            ["NextDialogue"] = 80140124,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 1,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F54EE",
            },
        [80140124] = {
            ["Content"] = "我不想眼睁睁看着这样一粒珍贵的种子被永远埋没在无法发芽的黑暗中。帕西法尔值得一个站在台前的机会。",
            ["ContentJP"] = "私は、この貴重な種が、芽を出すことなく永遠に闇に埋もれるのを見過ごせません。パシファルには、舞台に立つ資格があるはずです。",
            ["DialogueId"] = 80140124,
            ["GUID"] = "C89F5518",
            ["NextDialogue"] = 80140125,
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5518",
            },
        [80140125] = {
            ["Camera"] = "-93.044205,115.413742,181.152344,0.000014,-13.400175,-51.013519,25.000002,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "可是《雪国的孩子》是近年来最受欢迎的剧目。如果突然宣布一位新人主演，人们肯定会很好奇他的身份。",
            ["ContentJP"] = "しかし、『雪国の幼子』はここ数年で最も人気のある劇だ。突然新人を主演にすると発表したら、きっと彼の素性に好奇の目が集まるに決まってる。",
            ["DialogueId"] = 80140125,
            ["GUID"] = "C89F5542",
            ["LookAt"] = {
                [1] = "790032:n(790031)",
                [2] = "790031:n(790032)",
                },
            ["NextDialogue"] = 80140126,
            ["SpeakNpcId"] = 790032,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5542",
            },
        [80140126] = {
            ["Content"] = "冰湖城的小报记者有多猖獗你也知道，我们要怎么把他的身份瞒住？",
            ["ContentJP"] = "アイスレイク城の記者がどれだけ厄介かは、君も知っているだろう。彼の素性をどう隠し通すつもりだ。",
            ["DialogueId"] = 80140126,
            ["GUID"] = "C89F556C",
            ["NextDialogue"] = 80140127,
            ["SpeakNpcId"] = 790032,
            ["TalkActionId"] = {
                [1] = "790032:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F556C",
            },
        [80140127] = {
            ["Camera"] = "135.852097,-177.88208,141.5,0.000022,-1.199743,108.59391,35.0,154.067352,false,Manual,2.8",
            ["Content"] = "在冰湖城，还有什么新闻能比大明星薇奥莱塔的新恋情更引人注目？",
            ["ContentJP"] = "果たして、大スターヴィオレッタ様の恋愛沙汰以上に注目を集められるニュースなんてあるかしら？",
            ["DialogueId"] = 80140127,
            ["FacialId"] = {
                [1] = "790031:CM_Smile01",
                },
            ["GUID"] = "C89F5596",
            ["NextDialogue"] = 80140128,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790032:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5596",
            },
        [80140128] = {
            ["Camera"] = "-16.624153,32.01741,155.753906,0.000003,-6.600373,-48.810413,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "你……难道是想？",
            ["ContentJP"] = "おい……まさか？",
            ["DialogueId"] = 80140128,
            ["FacialId"] = {
                [1] = "790031:CM_Idle",
                },
            ["GUID"] = "C89F55C0",
            ["NextDialogue"] = 80140129,
            ["SpeakNpcId"] = 790032,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F55C0",
            },
        [80140129] = {
            ["Camera"] = "132.767883,-339.10141,147.777344,0.000007,-3.800016,93.188416,43.91328,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我最近闷得慌，正打算找安德鲁男爵出去逛逛街、喝喝茶……嘻嘻，不知道这一次记者们又会编出什么有趣的标题呢？",
            ["ContentJP"] = "ちょうど退屈しててね。アンドリュー男爵と街をぶらついて、お茶でもしようかと思っていたところなの……ふふっ、さて今回はどんな面白い見出しを捏造してくれるのかしら？",
            ["DialogueId"] = 80140129,
            ["FacialId"] = {
                [1] = "790031:CM_Happy01",
                },
            ["GUID"] = "C89F55EA",
            ["NextDialogue"] = 80140130,
            ["SpeakNpcId"] = 790031,
            ["TalkActionId"] = {
                [1] = "790031:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F55EA",
            },
        [80140130] = {
            ["Camera"] = "310.552002,-526.269592,200.597656,0.000119,-8.998903,116.991135,41.455132,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "唉，真拿你没办法……但我不会让你一个人承担责任。我说过，进了剧团就是一家人，无论遇到什么事都要齐心协力解决。道具的事就交给我吧。",
            ["ContentJP"] = "はあ、まったくお前には敵わないねぇ……とはいえ、責任をなすりつけるつもりはないよ。劇団に入った以上、みんな家族だ。どんなことがあろうと、力を合わせて乗り越える。角の件は、私に任せろ。",
            ["DialogueId"] = 80140130,
            ["FacialId"] = {
                [1] = "790031:CM_Smile01",
                },
            ["FinalCamera"] = "292.040833,-535.704895,200.597656,0.000119,-8.998903,116.991135,41.455132,100000.0,false,DoNotOverride,2.8",
            ["GUID"] = "C89F5614",
            ["LookAt"] = {
                [1] = "790032:n(790031)",
                },
            ["NextDialogue"] = 80140131,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790032},AnimationId{\"Disagree\"},Duration{1},_click{false}},\
LookAt{_delay{4},LookAtDescription{\"790032:n(790030)\"}}\
}",
            ["SpeakNpcId"] = 790032,
            ["TalkActionId"] = {
                [1] = "790031:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5614",
            },
        [80140131] = {
            ["Content"] = "老师，团长，谢谢你们的好意。可是万一我的身份暴露，我会令剧团蒙受耻辱——",
            ["ContentJP"] = "先生、団長、ありがとうございます。でも、もし僕の正体が明るみに出たら、劇団に恥をかかせることに――",
            ["DialogueId"] = 80140131,
            ["GUID"] = "C89F563E",
            ["NextDialogue"] = 80140132,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790030},AnimationId{\"DisagreeHead\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790030,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F563E",
            },
        [80140132] = {
            ["Camera"] = "228.412537,-163.239441,130.269531,0.000019,1.000431,146.591461,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "帕西法尔，看着我的眼睛，回答我。你对自己的表演有信心吗？",
            ["ContentJP"] = "パシファル、私の目を見て答えて。自分の演技に自信は？",
            ["DialogueId"] = 80140132,
            ["GUID"] = "C89F5668",
            ["LookAt"] = {
                [1] = "790030:n(790031)",
                },
            ["NextDialogue"] = 80140133,
            ["SpeakNpcId"] = 790031,
            ["TurnTo"] = {
                [1] = "790031:n(790030)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5668",
            },
        [80140133] = {
            ["Content"] = "……是的。我有信心。",
            ["ContentJP"] = "……はい、あります。",
            ["DialogueId"] = 80140133,
            ["GUID"] = "C89F5692",
            ["NextDialogue"] = 80140134,
            ["SpeakNpcId"] = 790030,
            ["TalkActionId"] = {
                [1] = "790030:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5692",
            },
        [80140134] = {
            ["Camera"] = "-185.420715,-82.395569,162.160156,0.000011,-6.399982,13.392228,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "那就没问题了。你是我最优秀的学生，你只需思考一件事，那就是如何用歌声和表演把观众带进故事，让他们去关注角色本身，而非扮演者的身份。",
            ["ContentJP"] = "なら問題ないわ。あなたは私の最も優秀な生徒よ。考えるべきはただ一つ、どうやって歌声と演技で観客を物語に引き込むか。そうすれば観客が注目するのは、役そのものとなり、演じている者の正体なんてどうでもよくなるわ。",
            ["DialogueId"] = 80140134,
            ["GUID"] = "C89F56BC",
            ["NextDialogue"] = 80140135,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790031},AnimationId{\"Disagree\"},Duration{1},_click{false}},\
PlayAnimation{_delay{4},ActorId{790031},AnimationId{\"Explain01_Start\"},Duration{3},_click{false}}\
}",
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F56BC",
            },
        [80140135] = {
            ["Camera"] = "67.660095,-107.371399,151.609375,0.000017,0.599984,137.796341,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "……我明白了。我会尽全力准备好每一场排练。我会让他们看到……真正的妖精如何从剧本和曲谱中走来。",
            ["ContentJP"] = "……わかりました。リハーサル、全力で取り組みます。そして、彼らに……台本と楽譜から生まれた本物の妖精を見せてやる。",
            ["DialogueId"] = 80140135,
            ["FacialId"] = {
                [1] = "790030:Happy01",
                },
            ["GUID"] = "C89F56E6",
            ["NextDialogue"] = 80140136,
            ["SpeakNpcId"] = 790030,
            ["TalkActionId"] = {
                [1] = "790031:Explain01_End",
                [2] = "790030:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F56E6",
            },
        [80140136] = {
            ["Camera"] = "-176.469574,-68.699188,170.910156,0.000072,-9.199588,8.997595,35.000008,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好啦好啦，别紧张。你只要照常发挥就足够了。不过，呵呵……这下连我也有点激动了。说不定这会变成《雪国的孩子》有史以来最完美的一场演出。",
            ["ContentJP"] = "はいはい、そんなに力まないの。いつも通りで十分よ。でも、ふふ……なんだか私までちょっとワクワクしてきたわ。もしかすると、史上最高の『雪国の幼子』になるかもしれないわね。",
            ["DialogueId"] = 80140136,
            ["FacialId"] = {
                [1] = "790031:CM_Happy01",
                },
            ["GUID"] = "C89F5710",
            ["NextDialogue"] = 80140137,
            ["Scripts"] = "SEQ{\
PlayAnimation{ActorId{790031},AnimationId{\"Confident_Start\"},Duration{3},_click{false}},\
PlayAnimation{ActorId{790031},AnimationId{\"Confident_End\"},Duration{1},_click{false}}\
}",
            ["SpeakNpcId"] = 790031,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F5710",
            },
        [80140137] = {
            ["Camera"] = "332.264832,-264.852875,133.148438,0.000017,-1.400052,144.39798,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "我会的。我会演得比所有人都好，让老师和母亲为我骄傲。",
            ["ContentJP"] = "はい、やってみせます。誰よりも素晴らしい演技で、先生と母さんの誇りになれるように！",
            ["DialogueId"] = 80140137,
            ["GUID"] = "C89F573A",
            ["NextDialogue"] = 80140138,
            ["SpeakNpcId"] = 790030,
            ["TalkActionId"] = {
                [1] = "790030:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F573A",
            },
        }
  end },
  { MinKey = 80140138, MaxKey = 80140446, Loader = function()
      return {
        [80140138] = {
            ["Content"] = "嗯，我很期待。",
            ["ContentJP"] = "ええ、期待しているわ。",
