            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/001/C89F57B8",
            },
        [80140141] = {
            ["Content"] = "不过，他的声音听起来和之前的主演也很像啊，难道是刻意模仿？",
            ["ContentJP"] = "それにしても、声が前の主演とすごく似てない？意図的に真似てるのかな？",
            ["DialogueId"] = 80140141,
