}",
            ["SpeakNpcId"] = 790029,
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8A94",
            },
        [80140451] = {
            ["Content"] = "我是骄傲的演员，在此献上最后的歌声。",
            ["ContentJP"] = "僕は誇り高い俳優。ここに最後の歌声を捧げる。",
            ["DialogueId"] = 80140451,
            ["Duration"] = 4,
            ["GUID"] = "C89F8ABE",
            ["VoiceName"] = "voice/$Locale$/inv/Tuosi/004/C89F8ABE",
            },
        [80140452] = {
            ["Content"] = "然后，谢幕退场。",
            ["ContentJP"] = "そしてーー幕を下ろす。",
            ["DialogueId"] = 80140452,
            ["Duration"] = 3,
            ["GUID"] = "C89F8AE8",
