                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BA9A",
            },
        [80150106] = {
            ["Camera"] = "-40.058441,39.776855,134.843063,0.000255,1.20561,-70.709114,35.000008,1.5,false,DoNotOverride,15.0",
            ["Content"] = "我我我没没没事事事……只只只是是好好像被电到了……",
            ["ContentJP"] = "だだだだい大丈夫……ななな何これ……かか感電……？",
            ["DialogueId"] = 80150106,
            ["FacialId"] = {
                [1] = "790008:Ahaha02",
                },
            ["FinalCamera"] = "-39.278023,37.547852,134.892807,0.000255,1.20561,-71.109024,35.000008,1.5,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5BAC4",
            ["NextDialogue"] = 80150107,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BAC4",
            },
        [80150107] = {
            ["Camera"] = "-57.003677,-15.846191,180.836349,0.000262,-21.793663,58.104839,35.000011,1.5,false,DoNotOverride,15.0",
            ["Content"] = "抱歉，我没控制好自己的能力……",
            ["ContentJP"] = "ごめん……驚いてつい……",
            ["DialogueId"] = 80150107,
            ["FacialId"] = {
                [1] = "790044:Sad01",
                [2] = "\
790008:None",
                },
            ["GUID"] = "C8A5BAEE",
            ["NextDialogue"] = 80150110,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BAEE",
            },
        [80150108] = {
            ["Camera"] = "-33.815468,132.302734,128.652939,0.000185,-0.989838,-71.132233,25.0,208.607803,false,Manual,3.0",
            ["Content"] = "啊，你来了……我来的路上刮了大风，吹乱了头发，所以我就想整理一下。",
            ["ContentJP"] = "あ、あなただったか……来る途中で風が強すぎて、髪が乱れちゃったの。だから整えてたのよ。",
            ["DialogueId"] = 80150108,
            ["GUID"] = "C8A5BB18",
            ["NextDialogue"] = 80150109,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Sigh_End",
                },
            ["TurnTo"] = {
                [1] = "790044:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BB18",
            },
        [80150109] = {
            ["Camera"] = "-36.580048,-34.005859,134.240494,0.000189,0.610011,71.466766,25.0,116.244736,false,Manual,3.0",
            ["Content"] = "稍等，我把手套戴上，免得伤到你。",
            ["ContentJP"] = "ちょっと待ってね、手袋をつけるから。ほら、これで感電させずに済むわ。",
            ["DialogueId"] = 80150109,
            ["GUID"] = "C8A5BB42",
            ["NextDialogue"] = 80150110,
            ["SpeakNpcId"] = 790044,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BB42",
            },
        [80150110] = {
            ["Camera"] = "-28.686066,121.959473,136.35405,0.000194,-1.994627,-75.695625,35.000008,189.677307,false,Manual,5.0",
            ["Content"] = "抱歉，让你久等了吗？",
            ["ContentJP"] = "ごめん、待たせた？",
            ["DialogueId"] = 80150110,
            ["FacialId"] = {
                [1] = "790044:None",
                },
            ["GUID"] = "C8A5BB6C",
            ["NextDialogue"] = 80150111,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BB6C",
            },
        [80150111] = {
            ["Camera"] = "-61.534256,-174.127441,136.342422,0.000261,-1.99352,69.701683,35.000011,1.5,false,DoNotOverride,15.0",
            ["Content"] = "不，没关系……是我到得早了。",
            ["ContentJP"] = "いいえ……私が早く着きすぎちゃっただけよ。",
            ["DialogueId"] = 80150111,
            ["FacialId"] = {
                [1] = "790044:Smile01",
                },
            ["GUID"] = "C8A5BB96",
            ["NextDialogue"] = 80150112,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:DisagreeHead",
                [2] = "\
790008:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BB96",
            },
        [80150112] = {
            ["Camera"] = "-248.447357,-402.659668,260.974548,0.000288,-18.193834,59.49369,35.000011,1.5,false,DoNotOverride,15.0",
            ["Content"] = "也谢谢你能邀请我来走一走，之前在卫戍部队里待得太久，起床、巡逻和吃饭的时间都是固定的，离开军团，没有了时间表，反而无所适从。",
            ["ContentJP"] = "それと、誘ってくれてありがとう。警備部隊にいたから、起床、巡回、それに食事の時間まで全部決まってたから……突然、時間に縛られない生活になると、逆にどうしていいかわからなくなっちゃって。",
            ["DialogueId"] = 80150112,
            ["FinalCamera"] = "-276.814423,-450.70166,295.601501,0.000289,-21.193995,59.893017,35.000011,1.5,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5BBC0",
            ["NextDialogue"] = 80150113,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BBC0",
            },
        [80150113] = {
            ["Camera"] = "-28.686066,121.959473,136.35405,0.000194,-1.994627,-75.695625,35.000008,189.677307,false,Manual,5.0",
            ["Content"] = "你一定从来没有迟到过吧。",
            ["ContentJP"] = "リズムのことだから、遅刻なんてしたことないんだろうな。",
            ["DialogueId"] = 80150113,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                },
            ["GUID"] = "C8A5BBEA",
            ["NextDialogue"] = 80150114,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BBEA",
            },
        [80150114] = {
            ["Camera"] = "-57.786217,-158.110352,137.150558,0.000258,-2.393585,70.501198,35.000011,1.5,false,DoNotOverride,15.0",
            ["Content"] = "在卫戍部队，迟到是要记过的……并且，那时我想的是，早一点到，就能比别人多做一点事。",
            ["ContentJP"] = "警備部隊では、遅刻すると過失記録が残るのよ……それに、早く着けば、やれることも増えるって思ってたから。",
            ["DialogueId"] = 80150114,
            ["GUID"] = "C8A5BC14",
            ["NextDialogue"] = 80150115,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Explain01_Start",
                [2] = "\
790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BC14",
            },
        [80150115] = {
            ["Content"] = "城里所有的杂事基本上卫戍部队都要管。城市巡逻、处理秽兽、居民纠纷、清理下水道……有时候也需要协助军团上层的机密事务。",
            ["ContentJP"] = "街の雑用は、ほとんど警備部隊がやらなきゃいけなかったのよ。街の巡回、<Default note=\"text:エジュウ\">穢獣</>の処理、住民同士のトラブル解決、それに下水道の掃除まで……時には帝国軍上層部の機密任務を手伝うこともあったわ。",
            ["DialogueId"] = 80150115,
            ["GUID"] = "C8A5BC3E",
            ["NextOptions"] = {
                [1] = 801501151,
                [2] = 801501152,
                },
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790044},AnimationId{\"Confident_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BC3E",
            },
        [80150116] = {
            ["Camera"] = "-136.425461,-331.263672,112.150925,0.000309,-0.393275,66.71666,35.000011,1.5,false,DoNotOverride,15.0",
            ["Content"] = "算是吧……最初我选择这份工作，就是希望能在努力向桂冠卡戎靠齐的同时，也为其他卡戎同胞做点什么。",
            ["ContentJP"] = "そうね……この仕事を選んだのは、桂冠カロン族に少しでも近づくためでもあるけど、カロン族の役に立ちたかったからでもあるの。",
            ["DialogueId"] = 80150116,
            ["FinalCamera"] = "-147.876663,-326.149902,112.150925,0.000309,0.006735,65.517342,35.000011,1.5,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5BC68",
            ["NextDialogue"] = 80150117,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BC68",
            },
        [80150117] = {
            ["Camera"] = "-301.315765,-406.490723,309.517883,0.00037,-23.193838,54.118931,25.0,1.5,false,DoNotOverride,15.0",
            ["Content"] = "但真的开始工作以后，才发现有许多卡戎的处境超过了我的想象……",
            ["ContentJP"] = "でも、実際に仕事を始めてみて気付いたの。カロン族の状況は、私が想像していた以上に厳しいことにね……",
            ["DialogueId"] = 80150117,
            ["FinalCamera"] = "-310.991913,-420.473145,319.580383,0.000366,-23.593794,54.918797,25.0,1.5,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5BC92",
            ["NextDialogue"] = 80150118,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BC92",
            },
        [80150118] = {
            ["Camera"] = "-378.580231,-484.69873,32.48877,0.0,4.605992,51.329815,25.0,577.353577,false,Manual,3.0",
            ["Content"] = "有的卡戎累死累活，在索拉人开的店里打黑工，就为了攒下钱，搞到一张通行证，能够在冰湖城里住下来。",
            ["ContentJP"] = "お金を貯めて、アイスレイク城に入る通行証を手に入れるために、ソラが経営する店で違法労働をしてるカロン族も少なくないわ。",
            ["DialogueId"] = 80150118,
            ["FacialId"] = {
                [1] = "790044:Think01",
                },
            ["FinalCamera"] = "-389.878632,-475.570312,32.48877,0.000001,4.805994,50.930901,25.0,577.353577,false,Manual,3.0",
            ["GUID"] = "C8A5BCBC",
            ["NextDialogue"] = 80150119,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Talk03ToThink_Start",
                },
            ["ToFinalCameraBlendTime"] = 9.5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BCBC",
            },
        [80150119] = {
            ["Camera"] = "-34.448036,24.091309,124.4207,0.000072,6.405153,-69.263062,25.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "但是只要一封随意捏造罪状的举报信，没有通行证的卡戎就会被抓走，而老板则可以合法地赖掉这一笔工钱。",
            ["ContentJP"] = "でもね、でっち上げられた告発状一つで、通行証を持たないカロン族は捕らえられてしまう。それも、雇用主にとっては、合法的に労働の報酬を踏み倒せる手段に過ぎないの。",
            ["DialogueId"] = 80150119,
            ["FacialId"] = {
                [1] = "790008:Unhappy01",
                },
            ["GUID"] = "C8A5BCE6",
            ["NextDialogue"] = 80150120,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BCE6",
            },
        [80150120] = {
            ["Camera"] = "-44.109055,-126.602539,136.444473,0.0001,-3.194643,70.337288,25.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "每当遇到这种事情，我都只能尽可能去斥责那些黑心的店主，再想办法帮那些卡戎洗脱冤屈，报酬大多也讨不回来。",
            ["ContentJP"] = "そんな事件に出くわすたびに、私はその悪徳商人たちをしかり、カロンたちの冤罪を晴らすために必死に動いた。それでも、報酬が支払われることはほとんどないわ。",
            ["DialogueId"] = 80150120,
            ["FacialId"] = {
                [1] = "790008:None",
                },
            ["FinalCamera"] = "-37.875015,-128.81543,136.444473,0.0001,-3.194643,71.137253,25.0,577.353577,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5BD10",
            ["NextDialogue"] = 80150121,
            ["Scripts"] = "PlayAnimation{_delay{8},ActorId{790044},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Think_End",
                [2] = "\
790008:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BD10",
            },
        [80150121] = {
            ["Camera"] = "-5.2649,-7.188477,165.547684,0.000205,-19.394308,83.935265,27.000002,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "回想起来，我似乎没做什么真正有用的事。至多也就是每天更早一点到岗，在当值的时候不允许自己的手下粗暴对待卡戎而已。",
            ["ContentJP"] = "今思えば、何も大したことはできなかった。せいぜい少し早めに持ち場に着いて、目の届く限り部下がカロンに乱暴な振る舞いをしないよう注意してたくらいよ。",
            ["DialogueId"] = 80150121,
            ["FacialId"] = {
                [1] = "790044:Sad01",
                },
            ["FinalCamera"] = "-5.2649,-7.188477,165.547684,0.000213,-19.394308,83.935249,29.0,577.353577,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5BD3A",
            ["NextDialogue"] = 80150122,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BD3A",
            },
        [80150122] = {
            ["Camera"] = "1.409618,-55.074219,133.131363,0.000191,-2.394548,92.124672,25.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "真是讽刺啊，之前我花了很长的时间去适应军团，想要改变军团，结果到最后发现自己什么都没能做到，反而自己却被军团改变了。",
            ["ContentJP"] = "本当に皮肉よね。長い時間をかけて必死に帝国軍に馴染もうと……帝国軍を変えようと思ってた。なのに、自分が先に変わってしまうなんて――",
            ["DialogueId"] = 80150122,
            ["FacialId"] = {
                [1] = "790044:Ahaha01",
                },
            ["FinalCamera"] = "11.094885,-54.509277,133.131363,0.000189,-2.194546,94.124893,25.0,577.353577,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5BD64",
            ["NextDialogue"] = 80150123,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790044},AnimationId{\"ExplainTwo_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ScratchHead_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BD64",
            },
        [80150123] = {
            ["Camera"] = "35.181286,178.780762,145.219193,0.000211,-4.794485,-103.074188,35.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "我清楚地记得，前段时间，有一位卡戎青年被士兵当街射杀……我没能让凶手得到应有的惩罚。",
            ["ContentJP"] = "この前、あるカロンの青年が街中で兵士に射殺されたの。なのに、私はその加害者に相応の罰を与えることすらできなかったわ。",
            ["DialogueId"] = 80150123,
            ["FacialId"] = {
                [1] = "790044:Sad02",
                },
            ["FinalCamera"] = "41.404854,177.280762,145.219193,0.000211,-4.19446,-105.474739,35.0,577.353577,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5BD8E",
            ["NextDialogue"] = 80150124,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ExplainTwo_End",
                [2] = "\
790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BD8E",
            },
        [80150124] = {
            ["Camera"] = "38.396221,-28.182129,144.513809,0.000195,-3.394488,111.523338,35.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "我试过和上级争论那个士兵的量刑，得到的却是“管好你自己”的警告……于是我知道这件事追查也没有用，只能不了了之了。",
            ["ContentJP"] = "上官に何度も掛け合ったわ。でも返ってきたのは「身の程を弁えろ」って忠告だけ……その瞬間、これ以上追及しても無駄だってわかったの。",
            ["DialogueId"] = 80150124,
            ["FacialId"] = {
                [1] = "790044:Sad01",
                },
            ["FinalCamera"] = "38.396221,-28.182129,144.513809,0.000205,-3.394488,111.523308,37.0,577.353577,false,DoNotOverride,3.0",
            ["GUID"] = "C8A5BDB8",
            ["NextDialogue"] = 80150125,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 11.5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BDB8",
            },
        [80150125] = {
            ["Camera"] = "8.642662,54.186523,123.681046,0.000211,6.805033,-95.275452,37.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "我最后能做的，也就只有协助安葬那位青年，给他的父亲留下些钱财用于生活……对于悲剧的源头，我完全无能为力。",
            ["ContentJP"] = "結局、あの青年を埋葬し、彼の父親に慰め程度の金を渡すしかなかった……それ以外は、何もできなかった……私はなんて無力なんだろう……",
            ["DialogueId"] = 80150125,
            ["FacialId"] = {
                [1] = "790008:Sad01",
                },
            ["GUID"] = "C8A5BDE2",
            ["NextOptions"] = {
                [1] = 801501251,
                [2] = 801501252,
                },
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Sigh_End",
                [2] = "\
790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BDE2",
            },
        [80150126] = {
            ["Camera"] = "64.037247,-191.337891,135.108414,0.000222,-1.59517,110.723915,35.0,577.353577,false,DoNotOverride,3.0",
            ["Content"] = "哎？",
            ["ContentJP"] = "えっ？",
            ["DialogueId"] = 80150126,
            ["FacialId"] = {
                [1] = "790044:Shock01",
                },
            ["GUID"] = "C8A5BE0C",
            ["NextDialogue"] = 80150127,
            ["SpeakNpcId"] = 790044,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BE0C",
            },
        [80150127] = {
            ["Camera"] = "42.326603,34.966309,162.393936,0.000196,-12.195159,-114.703926,35.000008,1.5,false,DoNotOverride,15.0",
            ["Content"] = "那时我只是沉浸在震惊之中，什么也没做……",
            ["ContentJP"] = "あの時はただ、あまりの出来事に身体が固まって、何もできなかった……",
            ["DialogueId"] = 80150127,
            ["FacialId"] = {
                [1] = "790008:Unhappy01",
                },
            ["FinalCamera"] = "42.326603,34.966309,162.393936,0.000204,-12.195159,-114.703911,36.0,1.5,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5BE36",
            ["NextDialogue"] = 80150129,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BE36",
            },
        [80150128] = {
            ["Camera"] = "51.694923,-135.471191,130.445541,0.000198,-2.39004,114.467331,25.0,222.044281,false,Manual,3.0",
            ["Content"] = "相比于其他视而不见的军团成员，你已经很了不起了。",
            ["ContentJP"] = "見て見ぬふりしかできない他の軍人に比べれば、{性别:君|あなた}は本当に立派だよ。",
            ["DialogueId"] = 80150128,
            ["FacialId"] = {
                [1] = "790008:Unhappy01",
                },
            ["FinalCamera"] = "54.578606,-134.157715,130.445541,0.000198,-2.39004,114.467331,25.0,222.044281,false,Manual,3.0",
            ["GUID"] = "C8A5BE60",
            ["NextDialogue"] = 80150129,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BE60",
            },
        [80150129] = {
            ["Camera"] = "64.961464,239.010254,146.234573,0.000215,-4.794485,-107.101105,36.0,1.5,false,DoNotOverride,15.0",
            ["Content"] = "至少你还感到愤怒，感到不公，也试图去改变这件事的结果。而你现在下定决心离开军团，也是证明了你没有真的被改变，而是抗拒成为他们的一部分。",
            ["ContentJP"] = "少なくとも、{性别:君|あなた}は怒りを感じ、不条理だと思い、そして変えようとした。その結果を受け入れるんじゃなく、自ら軍団を去ると決めたことから見ても、{性别:君|あなた}は彼らとは違うってわかるよ。",
            ["DialogueId"] = 80150129,
            ["FacialId"] = {
                [1] = "790044:Sad01",
                [2] = "\
790008:None",
                },
            ["FinalCamera"] = "78.562416,234.505371,146.234573,0.000217,-4.594483,-110.301086,36.0,1.5,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5BE8A",
            ["NextDialogue"] = 80150130,
            ["Scripts"] = "PlayAnimation{_delay{2},ActorId{790008},AnimationId{\"Explain01L_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BE8A",
            },
        [80150130] = {
            ["Camera"] = "18.275681,-22.90625,132.089951,0.000379,3.803268,101.912422,35.000008,1.5,false,DoNotOverride,15.0",
            ["Content"] = "……谢谢你。",
            ["ContentJP"] = "……ありがとう。",
            ["DialogueId"] = 80150130,
            ["GUID"] = "C8A5BEB4",
            ["NextDialogue"] = 80150131,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2},ActorId{790044},AnimationId{\"AgreeHead\"},Duration{2}},\
PlayFacial{_delay{2},ActorId{790044},FacialId{\"Ahaha01\"}},\
}",
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790008:Explain01L_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BEB4",
            },
        [80150131] = {
            ["Camera"] = "544.644653,-481.905273,0.226059,0.000371,7.4029,139.905487,25.0,764.135925,false,Manual,3.0",
            ["Content"] = "本来我以为只有我一个人会有这些烦恼。其他人要么成为了军团的帮凶，要么是已经说服自己去无条件执行命令，不去质疑现状。",
            ["ContentJP"] = "初めは、自分だけがこんな悩みを抱えてるんだと思ってた。他の人は、軍団の手先になるか、疑うことなく命令を受け入れるかのどちらかだったから……",
            ["DialogueId"] = 80150131,
            ["FacialId"] = {
                [1] = "790044:None",
                },
            ["FinalCamera"] = "544.644653,-481.905273,19.850174,0.000372,4.802879,139.905487,25.0,764.135925,false,Manual,3.0",
            ["GUID"] = "C8A5BEDE",
            ["NextDialogue"] = 80150132,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BEDE",
            },
        [80150132] = {
            ["Camera"] = "79.820587,-183.252441,89.199783,0.000411,6.203034,115.097778,30.0,287.422333,false,Manual,3.0",
            ["Content"] = "不过，在军团，这么做也是天经地义的：即便是桂冠卡戎，也有可能会因为一通举报，和那些没有通行证的卡戎被关押在一起。",
            ["ContentJP"] = "軍団ではそれは当たり前のことなの。たとえ桂冠を持つカロンになっても、同じような告発状一つで、通行証のないカロンたちと同じ牢に入れられてしまうんだから。",
            ["DialogueId"] = 80150132,
            ["FinalCamera"] = "84.749573,-180.955078,89.199783,0.000408,6.203034,114.897316,30.0,287.422333,false,Manual,3.0",
            ["GUID"] = "C8A5BF08",
            ["NextDialogue"] = 80150133,
            ["SpeakNpcId"] = 790044,
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BF08",
            },
        [80150133] = {
            ["Camera"] = "30.429073,138.662598,138.840347,0.000409,-3.196897,-105.904358,30.0,287.422333,false,Manual,3.0",
            ["Content"] = "但……你说得对，我已经不用担心变得和他们一样了，我又重新是我。即便没有了时间表，也要好过按时去遵守军团的规则。",
            ["ContentJP"] = "……だけど、確かにあなたの言う通りよ。もう、彼らみたいになるなんて心配はないわ。私は私でしかない。日程表はなくなってしまったけど、軍団の理不尽な規則に従い続けるよりは、ずっとマシよね。",
            ["DialogueId"] = 80150133,
            ["FinalCamera"] = "32.942013,137.945801,138.840347,0.000409,-3.196897,-105.904396,30.0,287.422333,false,Manual,3.0",
            ["GUID"] = "C8A5BF32",
            ["NextDialogue"] = 80150134,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790008:Talk03_Start",
                [2] = "\
790044:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/001/C8A5BF32",
            },
        [80150134] = {
            ["Camera"] = "-6.938042,-5.080078,140.156479,0.000421,-0.797117,86.295319,30.0,80.256699,false,Manual,3.0",
            ["Content"] = "下一次再见面，我不会再提前到了。",
            ["ContentJP"] = "次は、時間通りに来るわ。",
            ["DialogueId"] = 80150134,
            ["FacialId"] = {
                [1] = "790044:Happy01",
                },
