            },
        [80150220] = {
            ["Camera"] = "103.385284,-50.706055,132.141708,0.001397,-0.59827,154.763184,35.000008,187.416504,false,Manual,5.0",
            ["Content"] = "（黎瑟看了看你，似乎欲言又止。）",
            ["ContentJP"] = "リズムはあなたを一瞥した。何か言いたいことがあるようだ。",
            ["DialogueId"] = 80150220,
            ["FacialId"] = {
                [1] = "790044:Doubt01",
                },
            ["GUID"] = "C8A5CD78",
