            },
        [80150221] = {
            ["Camera"] = "18.037659,16.478027,158.897934,0.001394,-14.398284,159.76268,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "我……",
            ["ContentJP"] = "その……",
            ["DialogueId"] = 80150221,
            ["FinalCamera"] = "14.119385,17.922363,157.825867,0.001394,-14.398284,159.76268,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CDA2",
            ["NextDialogue"] = 80150222,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 3,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CDA2",
            },
        [80150222] = {
            ["Camera"] = "107.989838,3.304688,102.144806,0.001394,10.202198,166.347549,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "说实话，我还没有找到自己要做什么。",
            ["ContentJP"] = "正直に言うと、これから何をすればいいのかわからないの。",
            ["DialogueId"] = 80150222,
            ["FacialId"] = {
                [1] = "790044:Think01",
                },
            ["FinalCamera"] = "113.353882,2.002441,101.151398,0.001394,10.202198,166.347549,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CDCC",
            ["NextDialogue"] = 80150223,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CDCC",
            },
        [80150223] = {
            ["Camera"] = "-107.190308,170.004395,154.377823,0.001395,-7.197776,-60.649319,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "虽然每天也有去打零工维持生活，但是我很清楚，这只是工作，并非是通向哪里的目标。",
            ["ContentJP"] = "毎日日雇いのお勤めをしてるから、生活は問題ないのだけれど……これはただの仕事であって、私の歩みを促す目標にはなれないの。",
            ["DialogueId"] = 80150223,
            ["FacialId"] = {
                [1] = "790044:None",
                },
            ["FinalCamera"] = "-105.4422,170.974121,154.377792,0.001396,-7.197776,-60.849224,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CDF6",
            ["NextDialogue"] = 80150224,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ScratchHead_End",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CDF6",
            },
        [80150224] = {
            ["Camera"] = "407.091949,-65.960449,176.961502,0.001397,-9.59744,171.546249,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "新的目标……我还没有找到。或者说，我发现，实际上我一直在等待别人给我目标。",
            ["ContentJP"] = "新しい目標を見つけようとは思ってるんだけど……どうしてもダメだった。私は今まで、ずっと誰かから与えられた目標を追ってただけなんだって気付いたの……",
            ["DialogueId"] = 80150224,
            ["FacialId"] = {
                [1] = "790008:Confident01",
                },
            ["GUID"] = "C8A5CE20",
            ["NextDialogue"] = 80150225,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                [2] = "\
790044:ExplainTwo_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CE20",
            },
        [80150225] = {
            ["Camera"] = "432.948853,337.427246,446.11792,0.001453,-32.598656,-143.248642,35.000008,291.99585,false,DoNotOverride,15.0",
            ["Content"] = "我心甘情愿地相信了军团教给我的道理，因为我需要这些。当我失去了它们，才发现我的人生空空荡荡，什么也没有。",
            ["ContentJP"] = "帝国軍が教えてくれた理を心の底から信じ込んでいた――私には信念が必要だったからね。でも、いざそれを失った時、私の人生は空っぽになってしまったわ……",
            ["DialogueId"] = 80150225,
            ["FinalCamera"] = "472.58075,367.021973,477.749329,0.001453,-32.598656,-143.248642,35.000008,291.99585,false,DoNotOverride,15.0",
            ["GUID"] = "C8A5CE4A",
            ["NextDialogue"] = 80150226,
            ["SpeakNpcId"] = 790044,
            ["TalkActionId"] = {
                [1] = "790044:ExplainTwo_End",
                },
            ["ToFinalCameraBlendTime"] = 11,
            ["VoiceName"] = "voice/$Locale$/inv/Lise/002/C8A5CE4A",
            },
        [80150226] = {
            ["Camera"] = "98.584686,-58.58252,136.45752,0.001476,-0.397852,150.748535,50.0,186.33757,false,Manual,5.0",
            ["Content"] = "我不知道接下来应该朝哪里前进才好……",
            ["ContentJP"] = "その、つまり、どこに進めばいいのかわからないの……",
            ["DialogueId"] = 80150226,
            ["FacialId"] = {
                [1] = "790044:Disappoint01",
                },
