            ["Camera"] = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
            ["Content"] = "（我曾战胜过同窗，战胜过实验，战胜过疼痛。我一度以为自己无所不能；但如今我已知晓，我无法战胜的东西，远比我可以战胜的多得多。）",
            ["ContentJP"] = "（私は、友を打ち負かし、実験に勝ち、痛みに打ち勝ってきた。\
なんでも乗り越えられると、そう思っていた。\
でも今はわかる。私に勝てないもののほうが、ずっとずっと多いのだと。）",
            ["DialogueId"] = 80180353,
            ["GUID"] = "C8B91D2A",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80180354,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91D2A",
            },
        [80180354] = {
            ["Camera"] = "47.957031,-1250.3125,16.771729,0.000155,3.202962,92.956001,45.0,317.18219,false,Manual,6.360716",
            ["Content"] = "（但无论前路是什么，我希望这场战役结束后，无论是活着的我，还是我的灵魂，在归去时，可以把这句话带给西比尔·梅森——）",
            ["ContentJP"] = "（それでも、この先に何が待っていても。\
この戦いが終わったあと、たとえ生き延びた私であっても、あるいは、魂だけになった私であっても――\
この言葉だけは、シビル・メイソンに伝えたい。）",
            ["DialogueId"] = 80180354,
            ["FinalCamera"] = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
            ["GUID"] = "C8B91D54",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790045,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91D54",
            },
        [80180355] = {
            ["Camera"] = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
            ["Content"] = "（<H>达芙涅·塞奥多尔理想仍存。</>）",
            ["ContentJP"] = "（<H>ダフネ・セオドールは、今なお理想を捨ててはいない。</>）",
            ["DialogueId"] = 80180355,
            ["GUID"] = "C8B91D7E",
            ["IsBlack"] = 1,
            ["SpeakNpcId"] = 790045,
            ["VoiceName"] = "voice/$Locale$/inv/Dafu/003/C8B91D7E",
            },
        [80190001] = {
            ["Content"] = "白吃白喝那我就不客气啦，有便宜不占纯傻瓜嘛。",
            ["ContentJP"] = "タダ酒を断るやつなんていると思うか？",
            ["DialogueId"] = 80190001,
            ["GUID"] = "C8BF4C0A",
            },
        [80190101] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["DialogueId"] = 80190101,
            ["Duration"] = 3,
            ["GUID"] = "C8BF5C72",
            ["NextDialogue"] = 80190102,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190102] = {
            ["Content"] = "你一个人住这么大宅子？看着还有模有样，居然还整理出了一个调酒台。",
            ["ContentJP"] = "お前、一人でこんなデカい屋敷に住んでんのかよ？見た目ちゃんとしてるし、バーカウンターまであんのな。",
            ["DialogueId"] = 80190102,
            ["FacialId"] = {
                [1] = "95102:Shock01",
                },
            ["GUID"] = "C8BF5C9C",
            ["NextDialogue"] = 80190103,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Idle_Loop",
                },
            },
        [80190103] = {
            ["Content"] = "挺好的，多请一些朋友来吧，这样一来，你也能在冰湖城拥有自己的人脉。",
            ["ContentJP"] = "いいねぇ、もっと友達呼べって。そうすりゃお前もアイスレイク城で人脈ってやつができるかもだろ？",
            ["DialogueId"] = 80190103,
            ["FacialId"] = {
                [1] = "95102:Smile01",
                },
            ["GUID"] = "C8BF5CC6",
            ["NextDialogue"] = 80190104,
            ["SpeakNpcId"] = 95102,
            },
        [80190104] = {
            ["Content"] = "那么，说吧，又有啥事要我帮忙。太麻烦就算了啊，我这几天手上还有个大活呢。",
            ["ContentJP"] = "で、何か用？どうせまた頼み事だろ？面倒なやつなら断るぞ、今けっこうデカい仕事抱えてるからな。",
            ["DialogueId"] = 80190104,
            ["GUID"] = "C8BF5CF0",
            ["NextOptions"] = {
                [1] = 801901041,
                [2] = 801901042,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_Start",
                },
            },
        [80190105] = {
            ["Content"] = "噫……我鸡皮疙瘩都起来了。这话我勉强能受得了，要是你请其他人来喝酒也是这个说辞，人家不一定吃得消啊。",
            ["ContentJP"] = "うわっ……鳥肌立ったんだけど。ま、俺だからまだしも、他のやつにもそんなセリフで酒誘ったらドン引きされっぞ？",
            ["DialogueId"] = 80190105,
            ["GUID"] = "C8BF5D1A",
            ["NextDialogue"] = 80190107,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190106] = {
            ["Content"] = "行，那么我就不客气了，让我来尝一尝你的手艺怎么样。",
            ["ContentJP"] = "おっ、そんじゃ遠慮なく。お前の腕前、味見させてもらおうか。",
            ["DialogueId"] = 80190106,
            ["GUID"] = "C8BF5D44",
            ["NextDialogue"] = 80190107,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190107] = {
            ["ContentJP"] = "{空格}",
            ["DialogueId"] = 80190107,
            ["Duration"] = 3,
            ["GUID"] = "C8BF5D6E",
            ["NextDialogue"] = 80190108,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190108] = {
            ["Content"] = "啧啧，嗯，甜中带酸，特意做成了温酒，和“水仙平原”的水准差不多，但是也有自己的风格。",
            ["ContentJP"] = "ぷはぁ、ん、甘みの中に酸味があるし、そのうえ暖め酒ときた。アスフォデロスで飲んだやつに似てるが、どこかお前らしい味わいを感じるぜ。",
            ["DialogueId"] = 80190108,
            ["FacialId"] = {
                [1] = "95102:Smile01",
                },
            ["GUID"] = "C8BF5D98",
            ["NextDialogue"] = 80190109,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Idle_Loop",
                },
            },
        [80190109] = {
            ["Content"] = "这一杯挺麻烦的吧。说实话水准超过我的预期了，实话说煮杯热水我都能乐呵地喝下去，没必要费这么大劲。",
            ["ContentJP"] = "これ、けっこう手間かかったろ？正直、期待以上だった。俺なんて熱湯でさえテンションが上がるやつだから、そこまで気合入れんでもよかったのによ。",
            ["DialogueId"] = 80190109,
            ["GUID"] = "C8BF5DC2",
            ["NextDialogue"] = 80190110,
            ["SpeakNpcId"] = 95102,
            },
        [80190110] = {
            ["Content"] = "不过，看你这么兴致勃勃，啊……我懂了，攒了点钱就得挥霍一下，请客喝酒，添置新物。用最近流行的话说，就叫“花钱买乐子”？",
            ["ContentJP"] = "ま、でもお前がノリノリだったのは分かったわ。あーなるほどな、ちょっと金入ったからパーッと使いたくなったんだろ？ご馳走して、新しいモン買ってさ。最近よくあるじゃん「金で気分を買う」みたいなやつ。",
            ["DialogueId"] = 80190110,
            ["GUID"] = "C8BF5DEC",
            ["NextOptions"] = {
                [1] = 801901101,
                [2] = 801901102,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190111] = {
            ["Content"] = "你请人来喝上一杯不就是为了说话？这说明我比其他人都要了解你在想什么，比其他人都要赏脸。",
            ["ContentJP"] = "だろ？一杯やるってことは、話したいってことだ。つまり俺が、他のやつらよりお前の気持ち分かってるってわけ。ありがたく思えよ？",
            ["DialogueId"] = 80190111,
            ["GUID"] = "C8BF5E16",
            ["NextDialogue"] = 80190113,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_Start",
                },
            },
        [80190112] = {
            ["Content"] = "别别别，我错了我错了，你花钱你是老大，要不你打我一拳消消气。",
            ["ContentJP"] = "わーったわーった、俺が悪かった！金出してんのお前様だもんな？一発殴って気が済むなら、好きにやれ。",
            ["DialogueId"] = 80190112,
            ["GUID"] = "C8BF5E40",
            ["NextDialogue"] = 80190113,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_Start",
                },
            },
        [80190113] = {
            ["Content"] = "不过说笑归说笑，作为半个过来人，我也得提醒你一下，并不是每个人都值得你视为“朋友”请客喝酒的。",
            ["ContentJP"] = "……っと冗談はさておき、先輩からひとつ忠告な。「全員が友達」って思うな。酒おごる相手は選べ。",
            ["DialogueId"] = 80190113,
            ["GUID"] = "C8BF5E6A",
            ["NextDialogue"] = 80190114,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_End",
                },
            },
        [80190114] = {
            ["Content"] = "尤其在冰湖城这个地界，总有那么些心术不正的人，会盯上你现在拥有的东西，主动来做你的酒肉之交。",
            ["ContentJP"] = "特にこのアイスレイク城じゃ、ロクでもねえ奴らが、お前の持ちもん狙ってすり寄ってくるからな。最初はいい顔して、やたら持ち上げてくる。",
            ["DialogueId"] = 80190114,
            ["GUID"] = "C8BF5E94",
            ["NextDialogue"] = 80190115,
            ["SpeakNpcId"] = 95102,
            },
        [80190115] = {
            ["Content"] = "他们表面上挂着笑，变着法哄你开心，恨不得把你捧到天上去。但真遇到事儿的时候啊，指望他们还不如指望路边的一条狗。",
            ["ContentJP"] = "表向きはへつらっていやがるが、いざってときには、なんの役にも立たねぇ。そいつらに比べたら、道端の野良犬のがマシだ。",
            ["DialogueId"] = 80190115,
            ["GUID"] = "C8BF5EBE",
            ["NextOptions"] = {
                [1] = 801901151,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_Start",
                },
            },
        [80190116] = {
            ["Content"] = "啊对的对的对的，我奥特赛德就是你身边最大的那一号狐朋狗友，有好处的时候不管多远我闻着味儿都能找过来。",
            ["ContentJP"] = "はいはい、そうでーす。俺こそ最高にいい例ってやつだ。得さえあれば、どこだろうが、鼻利かせて飛んでくっつーの。",
            ["DialogueId"] = 80190116,
            ["GUID"] = "C8BF5EE8",
            ["NextDialogue"] = 80190117,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_AgreeHead",
                },
            },
        [80190117] = {
            ["Content"] = "其他人要跟我抢这个名号，也得先掂量掂量自己的斤两。他们要想从你这吃到好处，那也得等本大爷“吃饱喝足”先。",
            ["ContentJP"] = "他のやつらがそのポジション欲しがったら、まずは自分の格をわきまえろってこったな。俺が腹いっぱいになるまで、他の誰かにうまい思いはさせないぜ？",
            ["DialogueId"] = 80190117,
            ["GUID"] = "C8BF5F12",
            ["NextOptions"] = {
                [1] = 801901171,
                [2] = 801901172,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190118] = {
            ["Content"] = "哎，别啊，我还没待够呢。",
            ["ContentJP"] = "えぇ！？ ちょっと待てよ、まだ帰りたくねぇんだけど！",
            ["DialogueId"] = 80190118,
            ["GUID"] = "C8BF5F3C",
            ["NextDialogue"] = 80190120,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190119] = {
            ["Content"] = "哦？是怎么回事呢？我可不知道呀。",
            ["ContentJP"] = "ん？……さあ？何の話だか、さっぱり分かんねぇな〜？",
            ["DialogueId"] = 80190119,
            ["GUID"] = "C8BF5F66",
            ["NextDialogue"] = 80190120,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190120] = {
            ["Content"] = "酒味道不错，再给我来一杯。喝完这口我就去接着忙活了。",
            ["ContentJP"] = "……酒、うまかった。もう一杯くれ。それ飲んだら、ちゃんと仕事戻るからさ。",
            ["DialogueId"] = 80190120,
            ["GUID"] = "C8BF5F90",
            ["SpeakNpcId"] = 95102,
            },
        [80190201] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "嗨呀，迟到了半个钟头。为表歉意，哪怕你今天的酒味道像鲱鱼罐头，我也会一口喝下！",
            ["ContentJP"] = "おーっと、30分遅刻しちまったな。お詫びに、たとえ今日の酒がニシン缶みてぇな味でも、きっちり飲み干してやるよ！",
            ["DialogueId"] = 80190201,
            ["FacialId"] = {
                [1] = "95102:Ahaha01",
                },
            ["GUID"] = "C8BF6CDA",
            ["NextOptions"] = {
                [1] = 801902011,
                [2] = 801902012,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190202] = {
            ["Content"] = "哈哈，怎么一下就看穿了。",
            ["ContentJP"] = "ハハ、バレたか。",
            ["DialogueId"] = 80190202,
            ["FacialId"] = {
                [1] = "95102:Smile02",
                },
            ["GUID"] = "C8BF6D04",
            ["NextDialogue"] = 80190203,
            ["SpeakNpcId"] = 95102,
            },
        [80190203] = {
            ["Content"] = "前几天跟你说的那个大活，记得吧？今天跟威尔斯刚弄完，所以多花了点时间。",
            ["ContentJP"] = "この前言ってたでかい仕事、覚えてるか？今日ようやくウェルズと片付けたんだわ。思ったより時間食っちまってさ。",
            ["DialogueId"] = 80190203,
            ["FacialId"] = {
                [1] = "95102:None",
                },
            ["GUID"] = "C8BF6D2E",
            ["NextDialogue"] = 80190204,
            ["SpeakNpcId"] = 95102,
            },
        [80190204] = {
            ["Content"] = "委托内容本身不麻烦，委托牵连到的家伙很麻烦。",
            ["ContentJP"] = "依頼自体は単純なんだけどな、関わってるヤツがとにかく厄介だった。",
            ["DialogueId"] = 80190204,
            ["GUID"] = "C8BF6D58",
            ["NextOptions"] = {
                [1] = 801902041,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190205] = {
            ["Content"] = "不是他们。只要你符合规矩，会察言观色，不违背帝国利益，总有很多办法可以规避军团的麻烦。",
            ["ContentJP"] = "いやいや、あいつらのがまだマシだ。ルール守って、空気読んで、帝国に逆らわなきゃ基本スルーしてくれる。",
            ["DialogueId"] = 80190205,
            ["GUID"] = "C8BF6D82",
            ["NextDialogue"] = 80190206,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_DisagreeHead",
                },
            },
        [80190206] = {
            ["Content"] = "他们就像一把剑，危险致命却有迹可循。",
            ["ContentJP"] = "言ってみりゃ剣みたいなもんだな。危ねぇけど、動きは読める。",
            ["DialogueId"] = 80190206,
            ["GUID"] = "C8BF6DAC",
            ["NextDialogue"] = 80190207,
            ["SpeakNpcId"] = 95102,
            },
        [80190207] = {
            ["Content"] = "但有一群人比他们更加暴力且毫无章法，就像一颗藏在暗处的炸弹——",
            ["ContentJP"] = "でもな、もっとヤベぇのがいる。タチ悪くて、横暴で、何考えてるかまったく分かんねぇ連中。まるで地雷みたいなやつらだ。",
            ["DialogueId"] = 80190207,
            ["GUID"] = "C8BF6DD6",
            ["NextDialogue"] = 80190208,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_Start",
                },
            },
        [80190208] = {
            ["Content"] = "神弃者同盟，那个不要命的组织。跟他们扯上关系的事都会变得无比麻烦。",
            ["ContentJP"] = "――フォーセイクン同盟だよ。あいつらに関わると、まったく厄介事だらけだ。",
            ["DialogueId"] = 80190208,
            ["GUID"] = "C8BF6E00",
            ["NextDialogue"] = 80190209,
            ["SpeakNpcId"] = 95102,
            },
        [80190209] = {
            ["Content"] = "比如这次，本来只是个普普通通的送货委托，但威尔斯觉得货的重量不对，偷偷凿了个洞一看，里面装满了神弃者同盟的违规武器。",
            ["ContentJP"] = "今回もな、本来はただの配送だったんだよ。でもウェルズが「荷物の重さおかしくね？」って言い出して、中身こっそり確認したら……違法武器の山ときた。",
            ["DialogueId"] = 80190209,
            ["GUID"] = "C8BF6E2A",
            ["NextDialogue"] = 80190210,
            ["SpeakNpcId"] = 95102,
            },
        [80190210] = {
            ["Content"] = "这要是光明正大走大门，怕不是被门口的卫兵当场给毙了。",
            ["ContentJP"] = "もし正門から入ってたら、門前で衛兵に撃ち殺されて終わってたな。",
            ["DialogueId"] = 80190210,
            ["GUID"] = "C8BF6E54",
            ["NextDialogue"] = 80190211,
            ["SpeakNpcId"] = 95102,
            },
        [80190211] = {
            ["Content"] = "但这应该正是他们想要的。有可能是他们想要几具狩月人的尸体，也可能是他们想要一场骚乱，趁乱进入冰湖城。",
            ["ContentJP"] = "たぶん、それがヤツらの狙いだったんだろうな。月狩り人の死体が欲しかったのか、騒ぎを起こして城に潜り込みたかったのか……",
            ["DialogueId"] = 80190211,
            ["GUID"] = "C8BF6E7E",
            ["NextDialogue"] = 80190212,
            ["SpeakNpcId"] = 95102,
            },
        [80190212] = {
            ["Content"] = "也有可能只是他们想要通过这种方式，向他们的追随者宣扬索拉是如何残忍对待卡戎的。",
            ["ContentJP"] = "もしくは、ソラがカロンをどう虐げてるかってのを、信者に見せたかったのかもしれねぇ。",
            ["DialogueId"] = 80190212,
            ["GUID"] = "C8BF6EA8",
            ["NextDialogue"] = 80190213,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190213] = {
            ["Content"] = "完全不可理喻，对吧？总之，一般人根本无法想象他们的行事手段和目的。",
            ["ContentJP"] = "もう意味わかんねぇだろ？常人の考え方じゃねぇよ。",
            ["DialogueId"] = 80190213,
            ["FacialId"] = {
                [1] = "95102:Angry01",
                },
            ["GUID"] = "C8BF6ED2",
            ["NextDialogue"] = 80190214,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk02_Start",
                },
            },
        [80190214] = {
            ["Content"] = "最后我们只能想办法把这批武器弄到下水道里，顺着排水口运进城，完成了他们表面上的送货委托。",
            ["ContentJP"] = "結局、荷物を下水道に流して、排水口からこっそり運び込んで、外面だけは納品完了ってことにしたんだ。",
            ["DialogueId"] = 80190214,
            ["GUID"] = "C8BF6EFC",
            ["NextDialogue"] = 80190215,
            ["SpeakNpcId"] = 95102,
            },
        [80190215] = {
            ["Content"] = "听我说可能觉得还挺轻松，实际上为了这事，我跟威尔斯几天都没合眼了。",
            ["ContentJP"] = "簡単に聞こえるかもしんねぇけど、実際は何日も徹夜だぞ。俺もウェルズも、クッタクタだぜ。",
            ["DialogueId"] = 80190215,
            ["GUID"] = "C8BF6F26",
            ["NextOptions"] = {
                [1] = 801902151,
                [2] = 801902152,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190216] = {
            ["Content"] = "两码事两码事，威尔斯那边再忙，这边也确实是迟到了。",
            ["ContentJP"] = "いやいや、それとこれとは別だろ。ウェルズ側で何があろうと、お前との約束に遅刻したのは確かだからな。",
            ["DialogueId"] = 80190216,
            ["GUID"] = "C8BF6F50",
            ["NextDialogue"] = 80190218,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk02_End",
                },
            },
        [80190217] = {
            ["Content"] = "两码事两码事，酒肉朋友就是这样，有酒喝，那躺在棺材里也要爬出来喝一口。",
            ["ContentJP"] = "いやいや、それとこれは別だ！飲み仲間ってのはな、酒があれば棺からだって這い出してくるもんだぞ。",
            ["DialogueId"] = 80190217,
            ["GUID"] = "C8BF6F7A",
            ["NextDialogue"] = 80190218,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk02_End",
                },
            },
        [80190218] = {
            ["ContentJP"] = "{空格}",
            ["DialogueId"] = 80190218,
            ["Duration"] = 3,
            ["GUID"] = "C8BF6FA4",
            ["NextDialogue"] = 80190219,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190219] = {
            ["Content"] = "但我现在确实得回去睡觉了。不过临走之前还是得和你说一句：为了你和关心你的人着想，少跟现在的神弃者同盟接触。",
            ["ContentJP"] = "……でもまぁ、そろそろマジで寝るべきかもな。ただ、その前にひとつだけ言っときたい。お前や、お前を大事に思ってる仲間のためにも――最近のフォーセイクン同盟には、できるだけ関わらない方がいい。",
            ["DialogueId"] = 80190219,
            ["GUID"] = "C8BF6FCE",
            ["NextOptions"] = {
                [1] = 801902191,
                },
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Idle_Loop",
                },
            },
        [80190220] = {
            ["Content"] = "……就跟大多数人一样，看到危险，离远一点，仅此而已。",
            ["ContentJP"] = "……そりゃまあ。好きなやつなんてほとんどいないだろ。危ないもんには近づくな。それだけだ。",
            ["DialogueId"] = 80190220,
            ["FacialId"] = {
                [1] = "95102:Sad01",
                },
            ["GUID"] = "C8BF6FF8",
            ["NextDialogue"] = 80190221,
            ["SpeakNpcId"] = 95102,
            },
        [80190221] = {
            ["Content"] = "这是我挣扎在暴力机器相互撕咬的夹缝中这么久，总结出的宝贵经验——绝对，绝对，绝对不要靠近神弃者同盟。",
            ["ContentJP"] = "長年このクソみてぇな暴力の世界で生き延びてきた俺が言える、たった一つの大事な教訓だ。フォーセイクン同盟には――絶対に、絶対に近づくな。",
            ["DialogueId"] = 80190221,
            ["GUID"] = "C8BF7022",
            ["NextDialogue"] = 80190222,
            ["SpeakNpcId"] = 95102,
            },
        [80190222] = {
            ["Content"] = "这不是酒局上的胡话……而是关乎性命的建议。",
            ["ContentJP"] = "これは酔っ払いの戯言じゃねぇ。命に関わる警告だ。",
            ["DialogueId"] = 80190222,
            ["GUID"] = "C8BF704C",
            ["SpeakNpcId"] = 95102,
            },
        [80190301] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "奥特塞德如期赴约，但是喝了一口酒后便一直没有了声响。",
            ["ContentJP"] = "アウトサイダーは約束どおり現れた。だが、一口酒を飲んだきり、押し黙ってしまった。",
            ["DialogueId"] = 80190301,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "95102:Unhappy02",
                },
            ["GUID"] = "C8BF7D42",
            ["NextDialogue"] = 80190302,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190302] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80190302,
            ["GUID"] = "C8BF7D6C",
            ["NextDialogue"] = 80190303,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Idle_Loop",
                },
            },
        [80190303] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80190303,
            ["GUID"] = "C8BF7D96",
            ["NextOptions"] = {
                [1] = 801903031,
                [2] = 801903032,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190304] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80190304,
            ["GUID"] = "C8BF7DC0",
            ["NextDialogue"] = 80190305,
            ["SpeakNpcId"] = 95102,
            },
        [80190305] = {
            ["Content"] = "啊……嗯，我没事，没事，酒不错，和之前一样，高水准。",
            ["ContentJP"] = "……ああ、大丈夫大丈夫。美味い酒だな。相変わらずいい出来だ。",
            ["DialogueId"] = 80190305,
            ["GUID"] = "C8BF7DEA",
            ["NextDialogue"] = 80190306,
            ["SpeakNpcId"] = 95102,
            },
        [80190306] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80190306,
            ["GUID"] = "C8BF7E14",
            ["NextOptions"] = {
                [1] = 801903061,
                [2] = 801903062,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190307] = {
            ["Content"] = "哈？想多了，我怎么会在人前掉眼泪，多愁善感和“狐朋狗友”这几个字可不怎么搭。",
            ["ContentJP"] = "は？勘違いすんなよ。俺が人前で泣くわけねーだろ。憂いた「飲み仲間」ってキャラじゃねーんだわ。",
            ["DialogueId"] = 80190307,
            ["FacialId"] = {
                [1] = "95102:Shock01",
                },
            ["GUID"] = "C8BF7E3E",
            ["NextDialogue"] = 80190308,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_Start",
                },
            },
        [80190308] = {
            ["Content"] = "不过，最近确实老想起过去的一些事……哎呀，没准是岁数大了。",
            ["ContentJP"] = "まあな、最近ちょくちょく昔のこと思い出すんだよ……年かね。",
            ["DialogueId"] = 80190308,
            ["FacialId"] = {
                [1] = "95102:Sad01",
                },
            ["GUID"] = "C8BF7E68",
            ["NextDialogue"] = 80190309,
            ["SpeakNpcId"] = 95102,
            },
        [80190309] = {
            ["Content"] = "别这样一脸凝重地看着我，我可没打算继续说下去，你不会以为几顿酒就能换来我过去的一切吧。",
            ["ContentJP"] = "そんな深刻そうな顔すんなって。別に昔話するつもりなんかねぇよ。まさか数杯か奢っただけで、俺の昔話を全部聞き出せると思ってんのか？",
            ["DialogueId"] = 80190309,
            ["GUID"] = "C8BF7E92",
            ["NextDialogue"] = 80190310,
            ["SpeakNpcId"] = 95102,
            },
        [80190310] = {
            ["Content"] = "每个人身上都有几件需要独自带入坟墓的秘密。它们不会出现在墓穴，却是墓主最重要的陪葬。",
            ["ContentJP"] = "誰にだって、墓まで持ってく秘密のひとつやふたつはあるんだよ。心の底に沈んでる副葬品ってやつがな。",
            ["DialogueId"] = 80190310,
            ["GUID"] = "C8BF7EBC",
            ["NextDialogue"] = 80190311,
            ["SpeakNpcId"] = 95102,
            },
        [80190311] = {
            ["Content"] = "这些秘密可大可小，小到一些奇怪经历，比如喜欢闻月髓液的味道、喜欢啃硬硬的姜饼结果硌掉了门牙，大到不为人知的过去。",
            ["ContentJP"] = "それが取るに足らないことでもいいんだ。たとえばイコル液の匂いが好きだとか、固ぇジンジャークッキーかじって前歯折ったとか、あるいは――誰にも言えねぇような過去とか、な。",
            ["DialogueId"] = 80190311,
            ["GUID"] = "C8BF7EE6",
            ["NextDialogue"] = 80190312,
            ["SpeakNpcId"] = 95102,
            },
        [80190312] = {
            ["Content"] = "但毫无疑问，这些你看不见的秘密才是一个人会做出什么事的最重要依据。唔，说是最重要可能也过了，但你明白意思就好。",
            ["ContentJP"] = "でもな、そういう目に見えねぇ秘密こそが、その人間の生き方を決めたりすんだ。……ま、言いすぎかもしんねーけど、言いたいことは伝わるだろ？",
            ["DialogueId"] = 80190312,
            ["GUID"] = "C8BF7F10",
            ["NextDialogue"] = 80190313,
            ["SpeakNpcId"] = 95102,
            },
        [80190313] = {
            ["Content"] = "随便把秘密和过去讲给你听的人只有几种可能，要么是那段过去对他们来说不够重要……",
            ["ContentJP"] = "自分の秘密をペラペラしゃべるやつってのは、大体二通りだ。ひとつは、そもそもその過去に重みがねぇやつ。",
            ["DialogueId"] = 80190313,
            ["GUID"] = "C8BF7F3A",
            ["NextDialogue"] = 80190314,
            ["SpeakNpcId"] = 95102,
            },
        [80190314] = {
            ["Content"] = "要么是期望从你这得到什么安慰，而随意捏造了一段不存在的过往。",
            ["ContentJP"] = "もうひとつは、誰かに慰めてもらいたくて、テキトーな作り話こさえてるやつだ。",
            ["DialogueId"] = 80190314,
            ["GUID"] = "C8BF7F64",
            ["NextDialogue"] = 80190315,
            ["SpeakNpcId"] = 95102,
            },
        [80190315] = {
            ["Content"] = "总之，随意向其他人吐露自己的秘密，是很轻率的。既是把自己的把柄交了出去，也很容易被别人认为当做是行为轻佻。",
            ["ContentJP"] = "とにかくだ、自分の秘密や弱みを簡単にさらけ出すのは軽率な行為だ。相手に軽いヤツだと思われかねねぇしな。",
            ["DialogueId"] = 80190315,
            ["GUID"] = "C8BF7F8E",
            ["NextOptions"] = {
                [1] = 801903151,
                [2] = 801903152,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190316] = {
            ["Content"] = "是是是，通常来说确实如此，你说得这些我也明白。我也时不时在水仙平原和人说我又偷偷接了几件大活这样的秘密。",
            ["ContentJP"] = "まあまあ、分かってるって。俺だってアスフォデロスじゃたまに「またデカい依頼引き受けちゃってさ〜」とかポロッと言ったりするし？",
            ["DialogueId"] = 80190316,
            ["GUID"] = "C8BF7FB8",
            ["NextDialogue"] = 80190317,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_AgreeHead",
                },
            },
        [80190317] = {
            ["Content"] = "但……有点狡辩地说，秘密也是有大有小的。",
            ["ContentJP"] = "でも、それと「本当のこと」ってのはやっぱ違ぇんだよな。",
            ["DialogueId"] = 80190317,
            ["GUID"] = "C8BF7FE2",
            ["NextOptions"] = {
                [1] = 801903171,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_Start",
                },
            },
        [80190318] = {
            ["Content"] = "说什么呢，别瞎想！",
            ["ContentJP"] = "おい！でたらめ言うなよ！",
            ["DialogueId"] = 80190318,
            ["GUID"] = "C8BF800C",
            ["NextDialogue"] = 80190319,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_End",
                },
            },
        [80190319] = {
            ["Content"] = "……正因为是你，才不能让你知道我的过去。这不是故弄玄虚吊你胃口，而是希望你能够理解的忠告吧：",
            ["ContentJP"] = "……お前だからこそ、俺は昔のこと、軽々しく話せねぇのよ。焦らしてるわけじゃねぇ。ただこれだけは分かってほしい。",
            ["DialogueId"] = 80190319,
            ["GUID"] = "C8BF8036",
            ["NextDialogue"] = 80190320,
            ["SpeakNpcId"] = 95102,
            },
        [80190320] = {
            ["Content"] = "挖开过去的坟冢，发现的可能不是宝藏，而是死亡。为了不给大家添麻烦，这些事就让我一个人烂在肚子里吧。",
            ["ContentJP"] = "墓を掘り返しても、宝が出てくるとは限らねぇ。むしろ呪いに引っかかる方が多い。だから俺は、秘密を墓まで持っていくんだ。",
            ["DialogueId"] = 80190320,
            ["GUID"] = "C8BF8060",
            ["NextDialogue"] = 80190321,
            ["SpeakNpcId"] = 95102,
            },
        [80190321] = {
            ["Content"] = "放心，这些年我不都成功地把过去远远甩在身后了嘛。就算真追上来了，也还有我扛着。你担心明天不如过好当下。",
            ["ContentJP"] = "心配すんなって。ちゃんと過去は振り切ってきたさ。仮にそれが追いついてきたとしても、俺が何とかする。いずれ訪れる不安より、今の一杯の方が大事だろ？",
            ["DialogueId"] = 80190321,
            ["FacialId"] = {
                [1] = "95102:Smile01",
                },
            ["GUID"] = "C8BF808A",
            ["NextDialogue"] = 80190322,
            ["SpeakNpcId"] = 95102,
            },
        [80190322] = {
            ["Content"] = "我要再来一杯！刚才那杯喝得太快了没尝出个咸淡来。",
            ["ContentJP"] = "――よし、もう一杯だ！さっきのは一気にいっちまったから、味わうヒマもなかったんだわ。",
            ["DialogueId"] = 80190322,
            ["GUID"] = "C8BF80B4",
            ["NextOptions"] = {
                [1] = 801903221,
                [2] = 801903222,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190323] = {
            ["Content"] = "哈哈哈哈哈。就着好酒，和好朋友有一茬没一茬地唠唠，多好的一天啊。",
            ["ContentJP"] = "ハハハッ、うまい酒といい仲間がいりゃ、ダラダラしゃべってるだけでも、最高の一日ってやつよ。",
            ["DialogueId"] = 80190323,
            ["FacialId"] = {
                [1] = "95102:Smile02",
                },
            ["GUID"] = "C8BF80DE",
            ["NextOptions"] = {
                [1] = 801903231,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190324] = {
            ["Content"] = "你刚才是不是骂人了？",
            ["ContentJP"] = "……って今の、俺のことバカにしてない？",
            ["DialogueId"] = 80190324,
            ["GUID"] = "C8BF8108",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Think_Start",
                },
            },
        [80190401] = {
            ["Camera"] = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
            ["Content"] = "拿起酒杯，猛喝一口",
            ["ContentJP"] = "{空格}",
            ["DialogueId"] = 80190401,
            ["GUID"] = "C8BF8DAA",
            ["NextDialogue"] = 80190402,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190402] = {
            ["Content"] = "嗯？你刚刚叫我吗？",
            ["ContentJP"] = "ん？今、お前俺の名前呼んだか？",
            ["DialogueId"] = 80190402,
            ["FacialId"] = {
                [1] = "95102:Doubt01",
                },
            ["GUID"] = "C8BF8DD4",
            ["NextOptions"] = {
                [1] = 801904021,
                },
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            },
        [80190403] = {
            ["Content"] = "啊……是吗？最近我有点疑神疑鬼的，抱歉。",
            ["ContentJP"] = "……あー、そっか。最近な、ちょっと被害妄想ぎみなんだよ。悪ぃな。",
            ["DialogueId"] = 80190403,
            ["FacialId"] = {
                [1] = "95102:Unhappy01",
                },
            ["GUID"] = "C8BF8DFE",
            ["NextDialogue"] = 80190404,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_DisagreeHead",
                },
            },
        [80190404] = {
            ["Content"] = "实际上从很久之前开始，我就会幻听有人叫我本来的名字。这些声音有的温柔，有的坚毅。",
            ["ContentJP"] = "実はな、だいぶ前から幻聴ってやつがあってさ。時折誰かに本名を呼ばれた気になるんだ。その声は時に優しく、時に凛としててな。",
            ["DialogueId"] = 80190404,
            ["GUID"] = "C8BF8E28",
            ["NextDialogue"] = 80190405,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk02_Start",
                },
            },
        [80190405] = {
            ["Content"] = "就跟耳鸣差不多吧，听久了也就习惯了。我无聊的时候还会回她们一声解解闷呢，反正知道是假的。",
            ["ContentJP"] = "ま、耳鳴りみたいなモンよ。聞き慣れちまえば平気だ。暇なときはノリで返事して遊んでんだわ、どうせ幻聴だしな。",
            ["DialogueId"] = 80190405,
            ["GUID"] = "C8BF8E52",
            ["NextDialogue"] = 80190406,
            ["SpeakNpcId"] = 95102,
            },
        [80190406] = {
            ["Content"] = "但最近吓人的事发生了，昨天我习惯性地诶了一声，结果居然真有人“回应”了。",
            ["ContentJP"] = "でもな、昨日ヤベぇことが起きたんだよ。いつも通り適当に「おう」って返したらよ、本当に返事が返ってきたんだ。",
            ["DialogueId"] = 80190406,
            ["GUID"] = "C8BF8E7C",
            ["NextDialogue"] = 80190407,
            ["SpeakNpcId"] = 95102,
            },
        [80190407] = {
            ["Content"] = "街角的垃圾桶突然翻了过来，蹦出来一个黑黢黢的人影，跟我打招呼。",
            ["ContentJP"] = "路地のゴミ箱がガターン！って倒れてな、真っ黒な人影が出てきて、俺に声かけてきたんだよ。",
            ["DialogueId"] = 80190407,
            ["GUID"] = "C8BF8EA6",
            ["NextDialogue"] = 80190408,
            ["SpeakNpcId"] = 95102,
            },
        [80190408] = {
            ["Content"] = "我多希望那是哪个倒霉孩子的恶作剧。但可惜的是我听到了那个只有神弃者同盟的人才会叫的名字，而不是你所知的“奥特赛德”。",
            ["ContentJP"] = "ガキのイタズラだったらどれだけ良かったか……けどな、あいつが呼んだのは「アウトサイダー」じゃなくて、フォーセイクン同盟の連中しか知らねぇ名前だったんだ。",
            ["DialogueId"] = 80190408,
            ["GUID"] = "C8BF8ED0",
            ["NextDialogue"] = 80190409,
            ["SpeakNpcId"] = 95102,
            },
        [80190409] = {
            ["Content"] = "我赶紧装听错的路人搪塞过去了，也不知道那人信了没……唉，早知道前几天那个神弃者同盟的活就全甩给威尔斯了。",
            ["ContentJP"] = "とっさに聞き間違ったふりをしたが……バレてないかは正直わかんねぇ。あ〜あ、あの依頼、全部ウェルズに押しつけときゃよかったわ。",
            ["DialogueId"] = 80190409,
            ["GUID"] = "C8BF8EFA",
            ["NextOptions"] = {
                [1] = 801904091,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk02_End",
                },
            },
        [80190410] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80190410,
            ["GUID"] = "C8BF8F24",
            ["NextDialogue"] = 80190411,
            ["SpeakNpcId"] = 95102,
            },
        [80190411] = {
            ["ContentJP"] = "{空格}",
            ["DialogueId"] = 80190411,
            ["GUID"] = "C8BF8F4E",
            ["NextDialogue"] = 80190412,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190412] = {
            ["Content"] = "好吧，也该告诉你一些的。不然你走在路上莫名其妙被神弃者同盟的疯子捅了一刀，都不知道该怨谁了。",
            ["ContentJP"] = "……まあいいか、正直に話すよ。そうじゃねぇと、油断したお前が道端でフォーセイクン同盟のキ●ガイに刺されでもしたら、心苦しいからな。",
            ["DialogueId"] = 80190412,
            ["GUID"] = "C8BF8F78",
            ["NextDialogue"] = 80190413,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_Start",
                },
            },
        [80190413] = {
            ["Content"] = "我以前跟神弃者同盟有点……小过节，所以他们一直在找我。然后前几天那个委托<H>可能</>暴露了我的行踪。",
            ["ContentJP"] = "昔ちょっとフォーセイクンとトラブったことあってよ、それ以来ずっと俺のこと探してんの。で、この前の依頼で……まあ、居場所がバレた<H>可能性</>があるってワケ。",
            ["DialogueId"] = 80190413,
            ["GUID"] = "C8BF8FA2",
            ["NextDialogue"] = 80190414,
            ["SpeakNpcId"] = 95102,
            },
        [80190414] = {
            ["Content"] = "所以我得费点功夫，消掉在冰湖城的一些痕迹，免得他们真的顺着线索找到我。",
            ["ContentJP"] = "だから今、アイスレイク城で俺の痕跡を全部消す作業してんのさ。厄介だからな。",
            ["DialogueId"] = 80190414,
            ["GUID"] = "C8BF8FCC",
            ["NextDialogue"] = 80190415,
            ["SpeakNpcId"] = 95102,
            },
        [80190415] = {
            ["Content"] = "真要被他们找到了啊，我的朋友们都得遭殃，挨个拷打，不吐出我的下落不罢休。连你也跑不掉。",
            ["ContentJP"] = "もし見つかったら、俺の友達は全員巻き添えだ。片っ端から拷問されて、俺の居場所聞き出されんの。お前も例外じゃねぇ。",
            ["DialogueId"] = 80190415,
            ["GUID"] = "C8BF8FF6",
            ["NextDialogue"] = 80190416,
            ["SpeakNpcId"] = 95102,
            },
        [80190416] = {
            ["Content"] = "不过嘛，你也大可以说，我是你的酒肉朋友，和我相关的事情一概不知——",
            ["ContentJP"] = "……まあでも、お前は「アイツはただの飲み友だし、何も知らねぇ」って言い切ってくれていいぜ？",
            ["DialogueId"] = 80190416,
            ["GUID"] = "C8BF9020",
            ["NextOptions"] = {
                [1] = 801904161,
                [2] = 801904162,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk01_End",
                },
            },
        [80190417] = {
            ["Content"] = "哎，别着急打断我，这不还没发生嘛。不过……万一真的有那么一天……",
            ["ContentJP"] = "そう焦って否定するなって……だが、もしも、本当にその日が来たら――",
            ["DialogueId"] = 80190417,
            ["GUID"] = "C8BF904A",
            ["NextDialogue"] = 80190418,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Think_Start",
                },
            },
        [80190418] = {
            ["Content"] = "到时候我得离开你们，离开这座城市。菲娜就拜托你照顾了。",
            ["ContentJP"] = "俺はお前らの前から姿を消す。もちろん、街からもな。そうなったら、フィーナのことは頼むぜ。",
            ["DialogueId"] = 80190418,
            ["GUID"] = "C8BF9074",
            ["NextDialogue"] = 80190419,
            ["SpeakNpcId"] = 95102,
            },
        [80190419] = {
            ["Content"] = "她要是问起来你就说我接了个大活。我这里写了些信，你到时候每个月给她一封，应该能稳住她一段时间。",
            ["ContentJP"] = "もしあいつが俺のこと尋ねたら、適当にはぐらかしてくれ。でっかい依頼が入ったとかな。そんで、俺の書いた手紙を月イチで渡してくれりゃあ、しばらくは誤魔化せると思う。",
            ["DialogueId"] = 80190419,
            ["GUID"] = "C8BF909E",
            ["NextDialogue"] = 80190420,
            ["SpeakNpcId"] = 95102,
            },
        [80190420] = {
            ["Content"] = "对了还有，我家暖炉右手第三块砖后面藏了一笔钱，你直接拿去用吧。我想想还有什么……",
            ["ContentJP"] = "あ、そうだ。ウチの暖炉な、右側の三枚目のレンガの裏にちょっとだけ金を隠してるんだ。好きに使ってくれ。えーと、あと何かあったか……",
            ["DialogueId"] = 80190420,
            ["GUID"] = "C8BF90C8",
            ["NextDialogue"] = 80190421,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Think_End",
                },
            },
        [80190421] = {
            ["Content"] = "奥特赛德你先冷静点。",
            ["ContentJP"] = "アウトサイダー、とりあえず落ち着いて。",
            ["DialogueId"] = 80190421,
            ["GUID"] = "C8BF90F2",
            ["NextDialogue"] = 80190422,
            ["SpeakNpcId"] = 790008,
            },
        [80190422] = {
            ["Content"] = "我很冷静。你跟我复述一遍我刚才说的，我到时候不在了一切都得靠你了。",
            ["ContentJP"] = "……俺はいたって冷静だ。さっき俺が言ったこと、復唱してくれ。俺がいなくなったときに頼れるのは、お前しかいねぇんだからな。",
            ["DialogueId"] = 80190422,
            ["GUID"] = "C8BF911C",
            ["NextDialogue"] = 80190423,
            ["SpeakNpcId"] = 95102,
            },
        [80190423] = {
            ["Content"] = "这可不是你平时的样子，就因为神弃者同盟吗？",
            ["ContentJP"] = "なんだかアウトサイダーらしくないね。フォーセイクン同盟にビビってるの？",
            ["DialogueId"] = 80190423,
            ["GUID"] = "C8BF9146",
            ["NextDialogue"] = 80190424,
            ["SpeakNpcId"] = 790008,
            },
        [80190424] = {
            ["Content"] = "平时？平时可应付不了毫无底线的疯子。",
            ["ContentJP"] = "いつものノリじゃ、あのイカれた連中を相手にできねぇからな。",
            ["DialogueId"] = 80190424,
            ["FacialId"] = {
                [1] = "95102:Unacceptable01",
                },
            ["GUID"] = "C8BF9170",
            ["NextDialogue"] = 80190425,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_Start",
                },
            },
        [80190425] = {
            ["Content"] = "举个例子，为了一条情报，他们会一枚一枚地拔掉你的指甲。",
            ["ContentJP"] = "あいつらはな、たったひとつの情報のために、指の爪を一本ずつ剥がすような奴らだぜ。",
            ["DialogueId"] = 80190425,
            ["GUID"] = "C8BF919A",
            ["NextDialogue"] = 80190426,
            ["SpeakNpcId"] = 95102,
            },
        [80190426] = {
            ["Content"] = "而这一切只是那群疯子折磨的开始罢了……我不想看到这种事……发生在朋友身上……",
            ["ContentJP"] = "何が怖いかって、それが拷問の「始まり」にすぎねぇってんだ……友人を……そんな目に遭わせたくねぇ……",
            ["DialogueId"] = 80190426,
            ["GUID"] = "C8BF91C4",
            ["NextDialogue"] = 80190427,
            ["SpeakNpcId"] = 95102,
            },
        [80190427] = {
            ["Content"] = "但这些都还没发生，而且你也说了自己的行踪只是<H>可能</>暴露了而已，不是吗？",
            ["ContentJP"] = "……けど、まだ何も起きてないじゃん？居場所ばバレたってのもあくまで<H>可能性</>の話でしょ？",
            ["DialogueId"] = 80190427,
            ["GUID"] = "C8BF91EE",
            ["NextDialogue"] = 80190428,
            ["SpeakNpcId"] = 790008,
            },
        [80190428] = {
            ["Content"] = "即使是“可能”，也得做好万全准备。",
            ["ContentJP"] = "1%でも可能性があるのなら、備えておくに越したことはない。",
            ["DialogueId"] = 80190428,
            ["GUID"] = "C8BF9218",
            ["NextDialogue"] = 80190429,
            ["SpeakNpcId"] = 95102,
            },
        [80190429] = {
            ["Content"] = "过去没有类似的“可能”吗？现在比过去更危险吗？",
            ["ContentJP"] = "以前にもこんなことなかったの？その時よりも危険だってこと？",
            ["DialogueId"] = 80190429,
            ["GUID"] = "C8BF9242",
            ["NextDialogue"] = 80190430,
            ["SpeakNpcId"] = 790008,
            },
        [80190430] = {
            ["Content"] = "要说最危险的时候，这次好像还真不算什么……",
            ["ContentJP"] = "まあ……確かに今よりずっと危険な時はあったな……",
            ["DialogueId"] = 80190430,
            ["FacialId"] = {
                [1] = "95102:Think01",
                },
            ["GUID"] = "C8BF926C",
            ["NextDialogue"] = 80190431,
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Talk03_End",
                },
            },
        [80190431] = {
            ["Content"] = "这不就对了，过去你是怎么解决的。",
            ["ContentJP"] = "でしょ？その時はどうしてたの？",
            ["DialogueId"] = 80190431,
            ["GUID"] = "C8BF9296",
            ["NextDialogue"] = 80190432,
            ["SpeakNpcId"] = 790008,
            },
        [80190432] = {
            ["Content"] = "……有些只是虚惊一场，有些被我用恐吓、欺骗，把军团引来，或者在其他城市抛头露面之类的把戏解决掉了。",
            ["ContentJP"] = "……まぁ、ただの空騒ぎだったこともある。そうでない場合は、脅しかけたり、ハッタリかましたり、軍団呼び込んだり、別の街でわざと目立ってごまかしたり――そういう小細工で乗り切ったことも、あるにはあるな。",
            ["DialogueId"] = 80190432,
            ["GUID"] = "C8BF92C0",
            ["NextOptions"] = {
                [1] = 801904321,
                [2] = 801904322,
                },
            ["SpeakNpcId"] = 95102,
            },
        [80190433] = {
            ["ContentJP"] = "{空格}",
            ["DialogueId"] = 80190433,
            ["GUID"] = "C8BF92EA",
            ["NextDialogue"] = 80190434,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190434] = {
            ["Content"] = "是啊……你说的对。刚才我好像是有点……不太对劲。更危险的时候我都挺过来了，这次却早早把“后事”交代给了你。",
            ["ContentJP"] = "ああ……お前の言うとおりだな。さっきは……どうかしてたぜ。もっとヤバい状況だって乗り越えてきたってのに、ガラにもなく「遺言」みてぇなこと言っちまったな。",
            ["DialogueId"] = 80190434,
            ["FacialId"] = {
                [1] = "95102:None",
                },
            ["GUID"] = "C8BF9314",
            ["NextDialogue"] = 80190435,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Idle_Loop",
                },
            },
        [80190435] = {
            ["Content"] = "是最近跟你聊得太多还是我下意识地想要依赖你这个队长了，亦或是我变软弱了吗……",
            ["ContentJP"] = "最近お前としゃべりすぎたせいか、それとも無意識に隊長のあんたに甘えたくなったのか、気が弱くなっちまったか……",
            ["DialogueId"] = 80190435,
            ["GUID"] = "C8BF933E",
            ["NextDialogue"] = 80190436,
            ["SpeakNpcId"] = 95102,
            },
        [80190436] = {
            ["Content"] = "不对不对，怎么可能嘛！肯定是今天的酒有问题！刚才我说过什么很恶心的话吗？没有吧，绝对没有，对吧！",
            ["ContentJP"] = "……って、そんなわけねぇ！さては、今日の酒に何か仕込んだな！俺、今ものすごくキモいこと言ってなかった？言ってねぇよな、な！？",
            ["DialogueId"] = 80190436,
            ["GUID"] = "C8BF9368",
            ["NextOptions"] = {
                [1] = 801904361,
                [2] = 801904362,
                },
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_DisagreeHead",
                },
            },
        [80190437] = {
            ["Content"] = "所以说回来，比起担心还未发生的“可能”，不如还是等一切发生的时候再来拜托我吧，也许那时候我们还能找到更好的办法。",
            ["ContentJP"] = "ま、とにかく。不確かな「いつか」に怯えるより、起きた時に真っ先に頼ってほしい。もしかしたら、その時にはもっといい解決策があるかもしれないし。",
            ["DialogueId"] = 80190437,
            ["GUID"] = "C8BF9392",
            ["NextDialogue"] = 80190438,
            ["SpeakNpcId"] = 790008,
            },
        [80190438] = {
            ["Content"] = "咳咳，说得好。拜托了，未来的我！来来喝酒喝酒，敬未来的我们。",
            ["ContentJP"] = "ゴホッゴホッ……言うじゃねぇか。頼んだぜ、未来の俺！さあさあ、飲もうぜ！未来の俺たちに、乾杯！",
            ["DialogueId"] = 80190438,
            ["FacialId"] = {
                [1] = "95102:Smile01",
                },
            ["GUID"] = "C8BF93BC",
            ["NextDialogue"] = 80190439,
            ["SpeakNpcId"] = 95102,
            },
        [80190439] = {
            ["ContentJP"] = "{空格}",
            ["DialogueId"] = 80190439,
            ["GUID"] = "C8BF93E6",
            ["NextDialogue"] = 80190440,
            ["Scripts"] = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "95102:Aote_Story_Drink",
                },
            },
        [80190440] = {
            ["Content"] = "哦，但我还得道个歉，关于未来的担心是解决了，但关于我的过去，还是没办法全部告诉你。",
            ["ContentJP"] = "おっと、でもひとつ謝っとくわ。未来の不安はまぁ落ち着いたけど――俺の過去のことは、やっぱ全部は話せねぇんだ。",
            ["DialogueId"] = 80190440,
            ["GUID"] = "C8BF9410",
            ["NextDialogue"] = 80190441,
            ["Scripts"] = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
            ["SpeakNpcId"] = 95102,
            ["TalkActionId"] = {
                [1] = "95102:Sit_Idle_Loop",
                },
            },
        [80190441] = {
            ["Content"] = "不过我向你保证，一定会有一天，我会带你看我来到冰湖城之前的路。虽然它会让我痛苦，也可能让你对我有所怀疑。",
            ["ContentJP"] = "でもな、これだけは約束する。いつか必ず、お前に見せるよ――俺がアイスレイク城に来るまで、どんな道を通ってきたのかを。たぶん、俺にとってはキツい話になるし、お前の俺に対する信用を下げるかもしれねぇがな。",
            ["DialogueId"] = 80190441,
            ["GUID"] = "C8BF943A",
            ["NextDialogue"] = 80190442,
            ["SpeakNpcId"] = 95102,
            },
        [80190442] = {
            ["Content"] = "但我相信，到那时候，你依旧不会介意为我调上一杯和今日一样的酒的，我的朋友。",
            ["ContentJP"] = "だが、その時が来ても、お前は今日と同じように、黙って俺に一杯ふるまってくれるって信じてるぜ――相棒。",
            ["DialogueId"] = 80190442,
            ["GUID"] = "C8BF9464",
            ["SpeakNpcId"] = 95102,
            },
        [80200001] = {
            ["Camera"] = "-1480.738281,3129.994141,100.084961,0.000177,18.397858,-82.573738,35.0,3295.439453,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "春采薇，夏生苋，秋结枳，冬访芝……",
            ["ContentJP"] = "春には薇を摘み、夏には莧を育て、秋には枳を結び、冬には芝を訪う……",
            ["DialogueId"] = 80200001,
            ["Duration"] = 1,
            ["FinalCamera"] = "-1480.738281,3129.994141,100.084961,0.000191,0.799146,-69.377235,35.0,3295.439453,false,Manual,2.8",
            ["GUID"] = "C8C5B4AA",
            ["NextDialogue"] = 80200002,
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/001/C8C5B4AA",
            },
        [80200002] = {
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不向阳处无灰木，冰雪心里紫露花。青草深处分碧薷，异香丛里是告苍……",
            ["ContentJP"] = "陽の当たらぬ地に灰木は育たず、氷雪の中には紫露の花が咲く。青草の奥には碧薷が生え、異香漂う叢には告蒼が息づく……",
            ["DialogueId"] = 80200002,
            ["GUID"] = "C8C5B4D4",
            ["NextOptions"] = {
                [1] = 802000021,
                [2] = 802000022,
                [3] = 802000023,
                },
            ["Scripts"] = "PARA{\
MoveTo{_delay{10},ActorId{790008},TargetPoint{\"BP_200101a_nvzhu01\"},MoveSpeed{55},Visibility{\"Show\"}},\
SEQ{\
CameraMoveTo{_delay{4},TargetPosition{\"-6.146816,120.018967,141.563477,0.000095,5.200048,-128.788574,45.000023,110.798798,false,Manual,7.870067\"},duration{0}},\
CameraMoveTo{TargetPosition{\"-9.100973,100.566628,143.263672,0.000098,5.199925,-138.591827,45.000023,93.368507,false,Manual,7.870067\"},duration{35}}\
},\
SEQ{\
