            ["NextDialogue"] = 80200134,
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CA52",
            },
        [80200134] = {
            ["Content"] = "身膺大风九章给予的神力，就应当救死扶伤，尽职尽责，哪怕耗尽最后一滴精血也在所不惜，我们扶氏代代如此……",
            ["ContentJP"] = "大風九章の力を授かり、人を癒やすのが務め。命尽きるまで、それが私の道……代々、そうしてきた……",
            ["DialogueId"] = 80200134,
            ["GUID"] = "C8C5CA7C",
            ["NextDialogue"] = 80200135,
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CA7C",
            },
        [80200135] = {
            ["Camera"] = "1.20282,-148.704437,-23.814941,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
            ["Content"] = "怎么只有你扶风如此特殊，上不应天命，下不惜生灵，不尽祝由义务，离经叛道……",
            ["ContentJP"] = "なのに、なぜあなたは……フーフォンだけが……命を選び、術を捨て……義を捨て……",
            ["DialogueId"] = 80200135,
            ["FacialId"] = {
                [1] = "790053:Angry01",
                },
            ["FinalCamera"] = "-1.691193,-164.853149,-30.109375,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
            ["GUID"] = "C8C5CAA6",
            ["LookAt"] = {
                [1] = "790053:n(790008)",
                },
            ["NextDialogue"] = 80200136,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
