            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/002/C8C5CAA6",
            },
        [80200136] = {
            ["Content"] = "等等！我不是你姐姐——",
            ["ContentJP"] = "待って、{性别:僕|私}はあなたのお姉さんじゃないよ！",
            ["DialogueId"] = 80200136,
            ["GUID"] = "C8C5CAD0",
            ["NextDialogue"] = 80200137,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
