        [80200209] = {
            ["Content"] = "（没等扶疏说完，你就撕下了指甲大小的叶片塞进了嘴里。）",
            ["ContentJP"] = "フーシュの言葉を待たず、あなたは葉をちぎって口に入れた。",
            ["DialogueId"] = 80200209,
            ["Duration"] = 2,
            ["GUID"] = "C8C5D08E",
