            },
        [80200217] = {
            ["Content"] = "那是……扶疏？",
            ["ContentJP"] = "あれは……フーシュ……？",
            ["DialogueId"] = 80200217,
            ["FacialId"] = {
                [1] = "790008:Shock01",
                },
            ["GUID"] = "C8C5D1DE",
            ["LookAt"] = {
                [1] = "790008:n(790054)",
                },
            ["NextDialogue"] = 80200218,
            ["Scripts"] = "PlayAnimation{_delay{1.01},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D1DE",
            },
        [80200218] = {
            ["Camera"] = "-84.304626,35.644173,65.415039,0.000002,2.396269,78.78582,35.0,107.243362,false,DoNotOverride,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "麻烦。麻烦。麻烦。麻烦！",
            ["ContentJP"] = "めんどくさい、めんどくさい、めんどくさいっ！",
            ["DialogueId"] = 80200218,
            ["FacialId"] = {
                [1] = "790054:Angry01",
                },
            ["FinalCamera"] = "-66.061569,127.614021,68.84082,0.000002,1.396248,78.785858,35.0,107.243362,false,DoNotOverride,2.8",
            ["GUID"] = "C8C5D208",
            ["NextDialogue"] = 80200219,
            ["SpeakNpcId"] = 790054,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790054:Angry01_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D208",
            },
        [80200219] = {
            ["Content"] = "唉，早上起来的时候，还再三告诫自己别去惹她别去惹她，怎么早饭还没吃完，就破戒了！",
            ["ContentJP"] = "朝起きたとき、今日は絶対に妹にキレないって決めたのに！なんで朝ごはんすら終わってないのに破ってんのよ、私！",
            ["DialogueId"] = 80200219,
            ["GUID"] = "C8C5D232",
            ["NextDialogue"] = 80200220,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Sigh_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Sigh_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790054:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D232",
            },
        [80200220] = {
            ["Camera"] = "-2343.795166,1023.041992,114.227539,0.000092,-0.803982,-4.996912,35.0,2401.962891,false,Manual,2.8",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "扶风啊扶风！你怎能如此沉不住气呢！那小妮子脾气再臭，也是你亲妹子！你又不可能扔下她不管，干嘛总是气她呢！",
            ["ContentJP"] = "ったく……どれだけせっかちなんだよ私！どんなに無愛想でも、結局あの子は私の妹だから。放っておくわけにはいかないし……いつも彼女を怒らせてどうする気なのよ。",
            ["DialogueId"] = 80200220,
            ["FinalCamera"] = "-2335.671875,1115.896973,114.227539,0.000092,-0.803982,-4.997154,35.0,2401.962891,false,Manual,2.8",
            ["GUID"] = "C8C5D25C",
            ["NextDialogue"] = 80200221,
            ["Scripts"] = "PARA{\
TurnTo{_delay{1.01},TurnToDescription{\"790054:p(90))\"}},\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}},\
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{\"Talk03_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["TalkActionId"] = {
                [1] = "790008:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D25C",
            },
        [80200221] = {
            ["Camera"] = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
            ["Content"] = "没办法啊没办法，扶疏那一本正经的样子，实在是很好气……笑容没有消失，只是从扶疏妹妹的脸上，移到了我的脸上……",
            ["ContentJP"] = "だけど、フーシュのあの生真面目な姿、あまりにもばかばかしくてしようがなくなるよね……あの子の笑顔、こっちで預かっとけよ。",
            ["DialogueId"] = 80200221,
            ["FacialId"] = {
                [1] = "790054:Sad01",
                },
            ["GUID"] = "C8C5D286",
            ["NextDialogue"] = 80200222,
            ["Scripts"] = "PARA{\
SetLocation{ActorId{790008},TargetPoint{\"BP_200301b_fushu01\"},Visibility{\"Show\"}},\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Think_Start\"},Duration{1}},\
PlayFacial{_delay{8.01},ActorId{790054},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D286",
            },
        [80200222] = {
            ["Camera"] = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "人之常情，人之常情嘛！",
            ["ContentJP"] = "まぁまぁ、人間として当然のこと……",
            ["DialogueId"] = 80200222,
            ["FinalCamera"] = "108.321411,1110.508301,147.339844,0.000063,-8.613893,-93.255981,40.0,218.69223,false,Manual,11.861392",
            ["GUID"] = "C8C5D2B0",
            ["NextDialogue"] = 80200223,
            ["Scripts"] = "MoveTo{ActorId{790008},TargetPoint{\"BP_200301b_nvzhu01\"},MoveSpeed{100},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D2B0",
            },
        [80200223] = {
            ["Content"] = "扶、扶疏？是你吗？",
            ["ContentJP"] = "……フーシュ？",
            ["DialogueId"] = 80200223,
            ["Duration"] = 1,
            ["GUID"] = "C8C5D2DA",
            ["LookAt"] = {
                [1] = "790008:n(790054)",
                [2] = "790054:n(790008)",
                },
            ["NextDialogue"] = 80200224,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D2DA",
            },
        [80200224] = {
            ["Camera"] = "-5.917664,812.056946,114.511719,0.000043,2.986077,54.542389,35.000015,234.030762,false,Manual,3.823875",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "不是哦。我是扶疏的双胞胎姐姐，扶风。将我俩弄混的人，你不是第一个。",
            ["ContentJP"] = "違うわ！私はフーシュの双子の姉、フーフォンよ。妹と間違える人、けっこういるの。",
            ["DialogueId"] = 80200224,
            ["FacialId"] = {
                [1] = "790008:None",
                [2] = "790054:None",
                },
            ["FinalCamera"] = "-19.185059,822.114929,114.511719,0.000044,2.786068,50.5424,35.000015,234.030762,false,Manual,3.823875",
            ["GUID"] = "C8C5D304",
            ["NextDialogue"] = 80200225,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D304",
            },
        [80200225] = {
            ["Content"] = "你找扶疏？怪了，她素来不和人来往，是个小闷葫芦，原来也有熟人？",
            ["ContentJP"] = "それにしても、あの子に知り合いがいるなんてね。あんな陰気なキノコ女に……びっくりだわ。",
            ["DialogueId"] = 80200225,
            ["GUID"] = "C8C5D32E",
            ["NextOptions"] = {
                [1] = 802002251,
                [2] = 802002252,
                [3] = 802002253,
                },
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}},\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D32E",
            },
        [80200226] = {
            ["Content"] = "哇……你这个年纪的人，竟不觉得她闷，还这样夸奖她，不错不错，扶疏的朋友，就是我扶风的朋友！",
            ["ContentJP"] = "へぇ……あんた、いいセンスしてるじゃない。フーシュの友だちは私の友だちよ！",
            ["DialogueId"] = 80200226,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D382",
            ["NextDialogue"] = 80200229,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D382",
            },
        [80200227] = {
            ["Content"] = "讹钱讹到我枯荣阁来了？！你去这十里八乡问问，这小闷葫芦的肚子里连点铜钱响都听不到，你要诬赖人，好歹也诬赖给我吧！",
            ["ContentJP"] = "はあ！？まさかここにまで取り立てに来たの！？あの子、銭勘定なんてできないし、小銭の音にすらびっくりするレベルよ？騙そうったってそうはいかないんだからね！",
            ["DialogueId"] = 80200227,
            ["FacialId"] = {
                [1] = "790054:Angry01",
                },
            ["GUID"] = "C8C5D3D6",
            ["NextDialogue"] = 80200229,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Angry01_Start\"},Duration{1}},\
PlayAnimation{_delay{8.01},ActorId{790054},AnimationId{\"Angry01_End\"},Duration{1}},\
PlayAnimation{_delay{8.5},ActorId{790054},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayAnimation{_delay{10},ActorId{790054},AnimationId{\"Talk02_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D3D6",
            },
        [80200228] = {
            ["Content"] = "噫，油嘴滑舌，要是没病没痛就回家自己玩儿吧，乖。",
            ["ContentJP"] = "うへぇ、軽い……あんた、もし病気じゃないなら、帰って寝な！",
            ["DialogueId"] = 80200228,
            ["GUID"] = "C8C5D42A",
            ["NextDialogue"] = 80200229,
            ["Scripts"] = "PlayAnimation{_delay{4.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D42A",
            },
        [80200229] = {
            ["Camera"] = "-30.235046,1285.589722,155.125977,0.000064,-7.212188,-68.241211,35.000019,393.319,false,Manual,3.482719",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所以，你造访枯荣阁所为何事？",
            ["ContentJP"] = "で、本題。あんたがここに来た理由、聞かせてくれる？",
            ["DialogueId"] = 80200229,
            ["FacialId"] = {
                [1] = "790054:None",
                },
            ["FinalCamera"] = "31.76886,1303.230225,155.125977,0.00006,-7.012207,-79.441032,35.000019,393.319,false,Manual,3.482719",
            ["GUID"] = "C8C5D454",
            ["NextDialogue"] = 80200230,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D454",
            },
        [80200230] = {
            ["Content"] = "我误食了音容草，头脑发昏，还看见奇奇怪怪的东西，我想扶疏一定能治，就寻医问药来了。",
            ["ContentJP"] = "音容草をうっかり食べちゃって……頭がふわふわするし、変な幻も見えてる。たぶんフーシュなら治せると思って、助けを求めに来たんだ。",
            ["DialogueId"] = 80200230,
            ["FacialId"] = {
                [1] = "790008:Sad03",
                },
            ["GUID"] = "C8C5D47E",
            ["NextDialogue"] = 80200231,
            ["Scripts"] = "PlayAnimation{_delay{7.01},ActorId{790008},AnimationId{\"Explain02_End\"},Duration{1}}\
",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D47E",
            },
        [80200231] = {
            ["Camera"] = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
            ["Content"] = "你来得不巧，扶疏正生着闷气呢，还是别在这时候打扰她了。不过我是一名医师，让我看病也是一样的。",
            ["ContentJP"] = "タイミングが悪いわね。フーシュ、今ちょっとご機嫌斜めでさ。でも、私も一応医師だし、代わりに診てあげる。",
            ["DialogueId"] = 80200231,
            ["FinalCamera"] = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
            ["GUID"] = "C8C5D4A8",
            ["NextDialogue"] = 80200232,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{\"Think_End\"},Duration{1}},\
TurnTo{_delay{5.8},TurnToDescription{\"790054:n(790008)\"}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D4A8",
            },
        [80200232] = {
            ["Camera"] = "-253.072449,961.222961,89.996094,0.000045,3.386319,-1.453428,35.000015,323.748901,false,Manual,3.482719",
            ["Content"] = "让我仔细看看……",
            ["ContentJP"] = "うん……",
            ["DialogueId"] = 80200232,
            ["FinalCamera"] = "-253.819214,931.512756,89.996094,0.000045,3.186317,-1.253389,35.000015,323.748901,false,Manual,3.482719",
            ["GUID"] = "C8C5D4D2",
            ["NextDialogue"] = 80200233,
            ["Scripts"] = "MoveTo{ActorId{790054},TargetPoint{\"BP_200301b_fushu03\"},MoveSpeed{80},Visibility{\"Show\"}}",
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D4D2",
            },
        [80200233] = {
            ["Content"] = "嗯……步履还算稳健，双目也有焦点，口齿利索，舌头不打架，误食的量应该不大。大约是半片左右？",
            ["ContentJP"] = "足取りもまあまあ、目の焦点も合ってるし、ろれつも回ってる。あの葉っぱ、半分くらいしか食べてないでしょ？",
            ["DialogueId"] = 80200233,
            ["GUID"] = "C8C5D4FC",
            ["NextDialogue"] = 80200234,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D4FC",
            },
        [80200234] = {
            ["Content"] = "你症状不重，没等解药熬完，就全好了。再耐心等等吧，很快就会清醒的，别怕。",
            ["ContentJP"] = "症状は軽めだね。もうちょっとで薬草の解毒が終わるから、安心してな。",
            ["DialogueId"] = 80200234,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D526",
            ["NextDialogue"] = 80200235,
            ["Scripts"] = "PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D526",
            },
        [80200235] = {
            ["Camera"] = "24.030762,840.372314,98.698242,0.000059,12.985261,58.542137,35.000023,135.488754,false,Manual,8.071544",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "要是实在难受，我随身带了些橘枳丸，你嚼两个，会好些。",
            ["ContentJP"] = "我慢できなかったら、橘と枳の丸薬があるから言って。",
            ["DialogueId"] = 80200235,
            ["FinalCamera"] = "14.792786,846.531738,98.698242,0.000066,12.985261,54.742638,35.000023,135.488754,false,Manual,8.071544",
            ["GUID"] = "C8C5D550",
            ["NextDialogue"] = 80200236,
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790054:p(-30)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D550",
            },
        [80200236] = {
            ["Content"] = "我猜，你还有少眠多梦的毛病，于是你想去找怀梦草医治，但却不小心误食了极其类似的音容草。",
            ["ContentJP"] = "……で、推測だけど。あんた、寝つき悪いとか、夢見がちとか、あるでしょ？それで憶夢草を探してたんじゃないの？でも、間違って音容草を食べたってわけ。",
            ["DialogueId"] = 80200236,
            ["FacialId"] = {
                [1] = "790054:Angry01",
                },
            ["GUID"] = "C8C5D57A",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200237,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D57A",
            },
        [80200237] = {
            ["Content"] = "不过想治这个毛病，还是匍地枝与隙中花一同煎来服下更合适，怀梦草虽能助眠，但会在梦中看到难以忘怀之事，徒惹伤怀。",
            ["ContentJP"] = "でも、その症状は、地伏せ枝と隙間で咲く花の方がいいと思うな。憶夢草はたしかに眠れるけど、夢の中に忘れたい記憶が出てくるのよ。むしろ心の傷をえぐりかねない。",
            ["DialogueId"] = 80200237,
            ["GUID"] = "C8C5D5A4",
            ["LookAt"] = {
                [1] = "790054:n(790008)",
                },
            ["NextDialogue"] = 80200238,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{\"Talk02_Start\"},Duration{1}},\
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Talk02_End\"},Duration{1}},\
PlayAnimation{_delay{10.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D5A4",
            },
        [80200238] = {
            ["Camera"] = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
            ["Content"] = "……不提外貌，你和扶疏确实相像。",
            ["ContentJP"] = "……見た目のことは置いといて、あなたとフーシュ、たしかに似てるね。",
            ["DialogueId"] = 80200238,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["GUID"] = "C8C5D5CE",
            ["NextDialogue"] = 80200239,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D5CE",
            },
        [80200239] = {
            ["Camera"] = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
            ["Content"] = "这话倒是鲜少听到，我和扶疏虽是双生胎，但都说我性格跳脱，颇有“离经叛道”的嫌疑，与大风九章第九条很不相宜。",
            ["ContentJP"] = "ふふっ、そんなこと言われたの、初めてかも。双子だけど、みんな私のことは「出来損ない」って言うからさ。ほら、大風九章の第九条とも相性悪いし。",
            ["DialogueId"] = 80200239,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D5F8",
            ["NextDialogue"] = 80200240,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D5F8",
            },
        [80200240] = {
            ["Camera"] = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
            ["Content"] = "扶疏瞧着冷淡疏离，你瞧着风风火火，但只要涉及问诊的时候，那份一本正经，温和耐心简直如出一辙。",
            ["ContentJP"] = "フーシュは静かでどこか疎遠な感じ。あなたは明るくてちょっとガサツだけど、診察のときの真面目さと優しさ、あれは本当に似てる。",
            ["DialogueId"] = 80200240,
            ["FacialId"] = {
                [1] = "790008:Shy",
                },
            ["GUID"] = "C8C5D622",
            ["NextDialogue"] = 80200241,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D622",
            },
        [80200241] = {
            ["Camera"] = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
            ["Content"] = "你这人……现在我相信你和扶疏很熟了。",
            ["ContentJP"] = "……そっか。あんた、ほんとにあの子と仲いいのね。",
            ["DialogueId"] = 80200241,
            ["FacialId"] = {
                [1] = "790054:None",
                },
            ["GUID"] = "C8C5D64C",
            ["NextDialogue"] = 80200242,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D64C",
            },
        [80200242] = {
            ["Camera"] = "-225.803223,724.690369,-5.095703,0.00006,18.385708,34.549988,35.000015,390.386017,false,Manual,3.482719",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "那孩子性格执拗，许多话憋在心里不肯说，一张嘴也不怎么灵巧，有时明明是这个意思，说出来却离题万里。",
            ["ContentJP"] = "あの子、不器用で、思ってることなかなか言えない子だから。言っても全然的外れだったりしてさ。",
            ["DialogueId"] = 80200242,
            ["FinalCamera"] = "-314.394165,663.687378,-40.84668,0.000058,18.385708,34.550003,35.000015,390.386017,false,Manual,3.482719",
            ["GUID"] = "C8C5D676",
            ["NextDialogue"] = 80200243,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D676",
            },
        [80200243] = {
            ["Camera"] = "60.795898,983.703857,142.798828,0.000097,-11.615378,-75.852562,35.000019,86.947418,false,Manual,4.75455",
            ["Content"] = "大概……只有你这样细心的人才能和她玩到一起吧！",
            ["ContentJP"] = "でも、あんたみたいに分かってくれる人がいるなら、あの子もきっと救われる。",
            ["DialogueId"] = 80200243,
            ["GUID"] = "C8C5D6A0",
            ["NextDialogue"] = 80200244,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D6A0",
            },
        [80200244] = {
            ["Camera"] = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
            ["Content"] = "我这个做姐姐的惯爱嘴欠，先甘拜下风啦。",
            ["ContentJP"] = "まったく、姉のくせに口ばっかりの私が先に謝っとくよ。ごめんね。",
            ["DialogueId"] = 80200244,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5D6CA",
            ["NextDialogue"] = 80200245,
            ["SpeakNpcId"] = 790054,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D6CA",
            },
        [80200245] = {
            ["Camera"] = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
            ["Content"] = "那么，扶疏的熟人！姐姐有件事情拜托，看在扶疏的面子上，你一定会答应我的吧！",
            ["ContentJP"] = "さて、フーシュの友だちさん。ちょっとお願いがあるんだけど、聞いてくれるよね？",
            ["DialogueId"] = 80200245,
            ["FinalCamera"] = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
            ["GUID"] = "C8C5D6F4",
            ["NextDialogue"] = 80200246,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D6F4",
            },
        [80200246] = {
            ["Content"] = "愿闻其详。",
            ["ContentJP"] = "うん、話してみて。",
            ["DialogueId"] = 80200246,
            ["GUID"] = "C8C5D71E",
            ["NextDialogue"] = 80200247,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D71E",
            },
        [80200247] = {
            ["Camera"] = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
            ["Content"] = "可不可以帮我找一下送给扶疏的道歉礼物？",
            ["ContentJP"] = "フーシュに、謝りたいことがあるの。そのための贈り物を、代わりに取ってきてもらえない？",
            ["DialogueId"] = 80200247,
            ["GUID"] = "C8C5D748",
            ["NextDialogue"] = 80200248,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790008:Confident_Start",
                [2] = "790054:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D748",
            },
        [80200248] = {
            ["Camera"] = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "离这里不远的水域中，常有寿星乌贼出没，帮我钓些来，不难的吧！",
            ["ContentJP"] = "ここからそう遠くない水辺に、「コトブキイカ」がよく出るの。釣ってきてくれるかな、あんたなら楽勝でしょ？",
            ["DialogueId"] = 80200248,
            ["FinalCamera"] = "-248.974243,678.924866,174.214844,0.000118,0.185153,65.936897,35.000019,4716.592773,false,Manual,1.2",
            ["GUID"] = "C8C5D772",
            ["Scripts"] = "PlayAnimation{_delay{1.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/003/C8C5D772",
            },
        [80200301] = {
            ["Camera"] = "-979.67981,-2224.893066,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "哇……真的钓到了，好厉害。全能如我，坐在那里一天也未必能钓上来一条……",
            ["ContentJP"] = "わっ、マジで釣れた！？すごいじゃん。この万能な私でも、一日粘って一匹も釣れないのにさ〜！",
            ["DialogueId"] = 80200301,
            ["Duration"] = 1,
            ["FinalCamera"] = "-1096.155396,-2166.05835,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
            ["GUID"] = "C8C5E5E2",
            ["NextDialogue"] = 80200302,
            ["Scripts"] = "PARA{\
MoveTo{ActorId{790008},TargetPoint{\"BP_200401a_nvzhu01\"},MoveSpeed{90},Visibility{\"Show\"}},\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{\"Explain01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 25,
            ["TurnTo"] = {
                [1] = "790054:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E5E2",
            },
        [80200302] = {
            ["Camera"] = "0.420166,-219.716721,163.364258,0.000018,-7.399601,85.99836,45.0,289.463654,false,Manual,6.00204",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "并非全能。",
            ["ContentJP"] = "万能……？",
            ["DialogueId"] = 80200302,
            ["FacialId"] = {
                [1] = "790008:Smile01",
                },
            ["FinalCamera"] = "-18.45842,-218.633926,160.760742,0.000016,-6.999639,81.997551,45.0,289.463654,false,Manual,6.00204",
            ["GUID"] = "C8C5E60C",
            ["NextDialogue"] = 80200303,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E60C",
            },
        [80200303] = {
            ["Content"] = "扶疏给我看过你的画，很抽象。",
            ["ContentJP"] = "そういえば、フーシュにあなたの絵、見せてもらったよ。……なんていうか、すごく……抽象的だね。",
            ["DialogueId"] = 80200303,
            ["Duration"] = 3,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                },
            ["GUID"] = "C8C5E636",
            ["LookAt"] = {
                [1] = "790008:n(790054)",
                },
            ["NextDialogue"] = 80200304,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E636",
            },
        [80200304] = {
            ["Camera"] = "-212.935883,315.686401,125.688477,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
            ["Content"] = "……你们是不是有点太熟了，她怎么把此等家丑也告诉你？",
            ["ContentJP"] = "……ちょっと待って、それ見せる？あの子は……まったく！！",
            ["DialogueId"] = 80200304,
            ["FinalCamera"] = "-271.671875,398.944336,125.233398,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
            ["GUID"] = "C8C5E660",
            ["NextDialogue"] = 80200305,
            ["Scripts"] = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E660",
            },
        [80200305] = {
            ["Content"] = "咳……但我从来不知道扶疏喜欢寿星乌贼。",
            ["ContentJP"] = "ゴホン……でも、彼女がコトブキイカ好きってのは初耳だったな。",
            ["DialogueId"] = 80200305,
            ["GUID"] = "C8C5E68A",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200306,
            ["Scripts"] = "PlayAnimation{_delay{1.1},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01L_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E68A",
            },
        [80200306] = {
            ["Content"] = "并非喜欢。",
            ["ContentJP"] = "別に好きじゃないよ〜",
            ["DialogueId"] = 80200306,
            ["GUID"] = "C8C5E6B4",
            ["NextDialogue"] = 80200307,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790008:Explain01L_End",
                },
            ["TurnTo"] = {
                [1] = "790054:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E6B4",
            },
        [80200307] = {
            ["Content"] = "扶疏最讨厌寿星乌贼，小时候被吓哭过呢！",
            ["ContentJP"] = "あれのせいで、子どもの頃、泣いたんだから。トラウマ級だね。",
            ["DialogueId"] = 80200307,
            ["FacialId"] = {
                [1] = "790054:Smile02",
                },
            ["GUID"] = "C8C5E6DE",
            ["LookAt"] = {
                [1] = "790054:n(790008)",
                },
            ["NextOptions"] = {
                [1] = 802003071,
                [2] = 802003072,
                [3] = 802003073,
                },
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E6DE",
            },
        [80200311] = {
            ["Camera"] = "-1.582031,-202.988312,154.458984,0.000054,-4.600522,86.210663,50.000008,127.993942,false,Manual,11.517033",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "其实我最近已经和她吵架好几次了，你应该知道我们吵架的缘由吧？",
            ["ContentJP"] = "……ぶっちゃけ最近も、何回か言い合いしたの。あんたもなんとなく分かるでしょ？",
            ["DialogueId"] = 80200311,
            ["FacialId"] = {
                [1] = "790008:Beg",
                [2] = "790054:Sad01",
                },
            ["FinalCamera"] = "-4.151443,-241.749527,157.583984,0.000054,-4.600494,86.210938,50.000008,320.172394,false,Manual,6.00204",
            ["GUID"] = "C8C5E786",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200312,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_End",
                [2] = "790008:Shy03_Start",
                },
            ["ToFinalCameraBlendTime"] = 25,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E786",
            },
        [80200312] = {
            ["Content"] = "无非就是我想要钻研新的治病救人的办法，而她认为要坚守枯荣之术。",
            ["ContentJP"] = "私は、新しい治療法を試したくて。でも、あの子は枯栄の術を守るべきって言うの。",
            ["DialogueId"] = 80200312,
            ["Duration"] = 1,
            ["GUID"] = "C8C5E7B0",
            ["NextDialogue"] = 80200313,
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E7B0",
            },
        [80200313] = {
            ["Camera"] = "-96.161865,159.932739,99.22168,0.000047,7.599357,-58.392002,40.0,273.733917,false,Manual,6.00204",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "老实说，她有她的道理，我的方法一是前途未卜，不知成效，二是背离了大风九章……",
            ["ContentJP"] = "正直、どっちにも言い分はあるんだけどさ。私の方法は、成果も分かんないし、大風九章に背いてる……",
            ["DialogueId"] = 80200313,
            ["FinalCamera"] = "-122.544006,202.442444,84.046875,0.000046,8.199416,-58.192867,40.0,320.911621,false,Manual,6.00204",
            ["GUID"] = "C8C5E7DA",
            ["NextDialogue"] = 80200314,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"Think_Start\"}},\
LookAt{_delay{1.1},LookAtDescription{\"790054:n(790008)\"}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E7DA",
            },
        [80200314] = {
            ["Content"] = "我与我的研究最后究竟是怎样的结局，谁也不知道。",
            ["ContentJP"] = "この先どうなるかなんて、自分でも分かんない。",
            ["DialogueId"] = 80200314,
            ["Duration"] = 2,
            ["GUID"] = "C8C5E804",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200315,
            ["Scripts"] = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E804",
            },
        [80200315] = {
            ["Camera"] = "-63.858021,-9.877949,179.9375,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "但有一件事我可以确定，那就是滥用枯荣之术，扶疏妹妹一定会英年早逝吧。",
            ["ContentJP"] = "でもね、一つだけ確かなことがある。——今のまま術を使い続けたら、あの子は……きっと、死んでしまう。",
            ["DialogueId"] = 80200315,
            ["FinalCamera"] = "-57.449242,-15.032286,177.196289,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
            ["GUID"] = "C8C5E82E",
            ["NextDialogue"] = 80200316,
            ["Scripts"] = "PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{\"Explain02_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E82E",
            },
        [80200316] = {
            ["Camera"] = "-43.131927,125.243118,128.523438,0.000069,4.597353,-67.988014,55.0,219.25647,false,Manual,17.764473",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "而我……不想看到这个局面，所以我绝不会让步，我们的架也只能一直吵下去了。",
            ["ContentJP"] = "だから、絶対譲れないの。ケンカになったって、止まれないんだよ。",
            ["DialogueId"] = 80200316,
            ["FinalCamera"] = "-50.373177,143.161255,126.967773,0.000069,4.597353,-67.987976,55.0,219.25647,false,Manual,17.764473",
            ["GUID"] = "C8C5E858",
            ["LookAt"] = {
                [1] = "790054:n(790008)",
                },
            ["NextDialogue"] = 80200317,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{4.1},ActorId{790054},AnimationId{\"Confident_Start\"},Duration{1}},\
PlayAnimation{_delay{11.1},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790054:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E858",
            },
        [80200317] = {
            ["Camera"] = "-826.984375,564.034241,566.810547,0.00006,-22.002954,-35.181374,30.0,1155.509888,false,Manual,17.764473",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "唉，摊上这么一个不知姐姐苦心的妹妹，就算是得由我来道歉，我也不会让她好过的！",
            ["ContentJP"] = "はあ……姉の苦労も知らないでさ。謝るのはこっちの役目でも、楽はさせたくないっての！",
            ["DialogueId"] = 80200317,
            ["FinalCamera"] = "-826.984375,564.034241,531.505859,0.000068,-22.202971,-35.380627,30.0,1155.509888,false,Manual,17.764473",
            ["GUID"] = "C8C5E882",
            ["NextDialogue"] = 80200318,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E882",
            },
        [80200318] = {
            ["Content"] = "但我已经不被允许靠近她了，这些小可爱就交由你来转赠吧！她那么信任你，肯定毫无防备，说不定还会像小时候一样被吓哭哦。",
            ["ContentJP"] = "でも、もう近づくのは禁止されてるからさ。この子たち——おともだちイカちゃんは、あんたから渡して。あの子、あんたにはガード甘いし、もしかしたらまた泣いてくれるかも……ふふっ。",
            ["DialogueId"] = 80200318,
            ["FacialId"] = {
                [1] = "790054:Smile01",
                },
            ["GUID"] = "C8C5E8AC",
            ["NextOptions"] = {
                [1] = 80200319,
                },
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{\"Explain01_End\"},Duration{1}},\
PlayAnimation{_delay{9.1},ActorId{790054},AnimationId{\"Angry01_Start\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Explain01_Start",
                [2] = "790008:Shy03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E8AC",
            },
        [80200319] = {
            ["Content"] = "寿星乌贼……",
            ["ContentJP"] = "コトブキイカ……",
            ["DialogueId"] = 80200319,
            ["GUID"] = "C8C5E8D6",
            ["NextDialogue"] = 80200320,
            },
        [80200320] = {
            ["Camera"] = "-40.08873,-25.583652,132.830078,0.000071,0.997262,64.819328,40.0,103.979561,false,Manual,17.764473",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你只是想拐弯抹角地告诉她，“希望你能长命百岁”吧？",
            ["ContentJP"] = "……つまりさ。彼女に「長生きしてほしい」って、遠回しに伝えたいんでしょ？",
            ["DialogueId"] = 80200320,
            ["Duration"] = 1,
            ["FinalCamera"] = "-44.77795,-23.377747,132.830078,0.000071,0.997262,64.819717,40.0,103.979561,false,Manual,17.764473",
            ["GUID"] = "C8C5E900",
            ["NextDialogue"] = 80200321,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{\"Think_End\"},Duration{1}},\
PlayFacial{_delay{4.1},ActorId{790008},FacialId{\"Smile02\"}}\
}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E900",
            },
        [80200321] = {
            ["Camera"] = "-335.726562,-30.426773,87.43457,-0.299988,4.600269,5.00543,28.0,371.52066,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "呃……看破不说破嘛，这种小心思说出来就没劲儿了。我还想看扶疏生气的样子呢！",
            ["ContentJP"] = "うっ……そ、そういうのは……言っちゃダメなの！バレてても、黙っててくれないと、台無しでしょ！？私は、あの子がムッとする顔、見たいだけなんだから〜！",
            ["DialogueId"] = 80200321,
            ["FinalCamera"] = "-376.866547,-34.026245,84.112305,-0.299988,4.600269,5.00543,28.0,383.921387,false,Manual,1.2",
            ["GUID"] = "C8C5E92A",
            ["LookAt"] = {
                [1] = "790054:n(790054)",
                },
            ["NextDialogue"] = 80200322,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}},\
LookAt{_delay{6.1},LookAtDescription{\"790054:n(790008)\"}}\
}",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790054:Angry01_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790054:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E92A",
            },
        [80200322] = {
            ["Content"] = "快去！快去！",
            ["ContentJP"] = "さっさと行って、ほらほら！",
            ["DialogueId"] = 80200322,
            ["GUID"] = "C8C5E954",
            ["SpeakNpcId"] = 790054,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                [2] = "790054:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E954",
            },
        [80200323] = {
            ["Content"] = "出幻境，回到采药任务点1，和扶疏站桩。",
            ["ContentJP"] = "幻境終了。採薬クエストポイント1に戻る。",
            ["DialogueId"] = 80200323,
            ["GUID"] = "C8C5E97E",
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E97E",
            },
        [80200324] = {
            ["Camera"] = "119.887146,130.070343,137.368652,0.000012,2.799851,-138.98819,45.0,175.296234,false,Manual,22.0",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你醒了！",
            ["ContentJP"] = "——目が覚めたのですね！",
            ["DialogueId"] = 80200324,
            ["FacialId"] = {
                [1] = "790053:Shock01",
                },
            ["FinalCamera"] = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98819,45.0,202.350357,false,Manual,12.098981",
            ["GUID"] = "C8C5E9A8",
            ["NextDialogue"] = 80200325,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["TurnTo"] = {
                [1] = "790008:n(790053)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E9A8",
            },
        [80200325] = {
            ["Content"] = "才过去三四分钟，但实在牵肠挂肚……我都怀疑是否记错了书上的内容，莫非毒性比我想象中大？",
            ["ContentJP"] = "ほんの三、四分のはずだったのに、どうにも心配で……本の記述を見間違えたのかと思ったわ。毒性、もっと強かったかもって。",
            ["DialogueId"] = 80200325,
            ["FacialId"] = {
                [1] = "790053:Sad01",
                },
            ["GUID"] = "C8C5E9D2",
            ["NextDialogue"] = 80200326,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{\"DisagreeHead\"},Duration{1}},\
PlayAnimation{_delay{3.1},ActorId{790053},AnimationId{\"Think_Start\"},Duration{1}},\
PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{\"Think_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E9D2",
            },
        [80200326] = {
            ["Content"] = "我想给你用枯荣之术，但又怕没等我施术完毕，你就又好了……",
            ["ContentJP"] = "枯栄の術を試そうとしたの。でも、術が終わる前に、あなたのほうが先に目覚めるんじゃないかって……",
            ["DialogueId"] = 80200326,
            ["GUID"] = "C8C5E9FC",
            ["NextDialogue"] = 80200327,
            ["Scripts"] = "PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{\"Explain01_End\"},Duration{1}}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5E9FC",
            },
        [80200327] = {
            ["Camera"] = "30.172951,-5.828094,146.924805,0.000022,-4.600405,68.410217,45.0,131.244232,false,Manual,6.805237",
            ["Content"] = "噗嗤……你们姐妹俩还真是像……",
            ["ContentJP"] = "あなたとフーフォン、やっぱり似てるね。",
            ["DialogueId"] = 80200327,
            ["FacialId"] = {
                [1] = "790008:Smile02",
                },
            ["GUID"] = "C8C5EA26",
            ["NextDialogue"] = 80200328,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Laugh01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EA26",
            },
        [80200328] = {
            ["Camera"] = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98822,45.0,202.350357,false,Manual,6.805237",
            ["Content"] = "你也……见到家姐了？",
            ["ContentJP"] = "……まさか、姉に会ったのですか？",
            ["DialogueId"] = 80200328,
            ["FacialId"] = {
                [1] = "790053:Unacceptable01",
                },
            ["GUID"] = "C8C5EA50",
            ["NextDialogue"] = 80200329,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Shy02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EA50",
            },
        [80200329] = {
            ["Camera"] = "-15.628626,-121.557404,164.124023,0.000028,-8.000521,72.409447,45.0,254.346725,false,Manual,6.805237",
            ["Content"] = "没错，你记得吗，她同你吵架，送了你最讨厌的寿星乌贼做道歉礼物。",
            ["ContentJP"] = "うん。昔の話、覚えてる？喧嘩して、謝るために、あなたの一番嫌いなコトブキイカをプレゼントしたって。",
            ["DialogueId"] = 80200329,
            ["GUID"] = "C8C5EA7A",
            ["NextDialogue"] = 80200330,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk01_Start",
                [2] = "790053:Shy02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EA7A",
            },
        [80200330] = {
            ["Camera"] = "95.230194,90.889275,139.040527,0.000013,1.999715,-138.388199,45.0,129.860046,false,Manual,6.805237",
            ["Content"] = "……我都已经忘记了。那真是，很久很久以前的往事了。",
            ["ContentJP"] = "……そんなことも、あったかもしれませんね。もう、すっかり忘れていました。もうずいぶん前のことでしたし。",
            ["DialogueId"] = 80200330,
            ["FacialId"] = {
                [1] = "790053:Sad03",
                },
            ["GUID"] = "C8C5EAA4",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextDialogue"] = 80200331,
            ["Scripts"] = "PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{\"Explain02_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:DisagreeHead",
                [2] = "790008:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EAA4",
            },
        [80200331] = {
            ["Camera"] = "415.101501,-1311.599854,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "你接受她的道歉了吗？",
            ["ContentJP"] = "で、許してあげたの？",
            ["DialogueId"] = 80200331,
            ["FinalCamera"] = "448.243896,-1301.340576,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
            ["GUID"] = "C8C5EACE",
            ["NextDialogue"] = 80200332,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_Start",
                [2] = "790053:Explain02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EACE",
            },
        [80200332] = {
            ["Content"] = "呵呵……没有，我和她又吵了一架。我虽然不后悔……",
            ["ContentJP"] = "ふふ……いいえ。またひと悶着しました。あのときは、後悔してなかったのですが——",
            ["DialogueId"] = 80200332,
            ["GUID"] = "C8C5EAF8",
            ["NextDialogue"] = 80200333,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Talk02_End",
                [2] = "790053:Sad02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EAF8",
            },
        [80200333] = {
            ["Camera"] = "106.505447,46.279133,180.103516,0.000015,-17.200472,-157.386368,45.0,118.629143,false,Manual,12.098981",
            ["Content"] = "但或许，现在的我会愿意接受那条寿星乌贼。",
            ["ContentJP"] = "今の私なら、もしかしたら、あのイカを受け取ったかもしれません。",
            ["DialogueId"] = 80200333,
            ["FacialId"] = {
                [1] = "790053:SpecialSmile",
                },
            ["FinalCamera"] = "93.592377,40.89082,175.773438,0.000015,-17.200472,-157.386368,45.0,109.419518,false,Manual,12.098981",
            ["GUID"] = "C8C5EB22",
            ["NextDialogue"] = 80200334,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Sad02_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EB22",
            },
        [80200334] = {
            ["Content"] = "……但也只是或许，我不喜欢多足生物，这点千真万确。",
            ["ContentJP"] = "……「もしかしたら」ですけどね。多足類は、今も本当に苦手なんです。",
            ["DialogueId"] = 80200334,
            ["FacialId"] = {
                [1] = "790053:Pain01",
                },
            ["GUID"] = "C8C5EB4C",
            ["NextDialogue"] = 80200335,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EB4C",
            },
        [80200335] = {
            ["Camera"] = "48.175987,-418.433289,149.098633,0.000042,-4.200382,92.013222,45.0,450.246735,false,Manual,12.098981",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "其实……不应该让你看到这些往事，过去的人都已作古，看到这些徒惹伤怀，也是无益。",
            ["ContentJP"] = "でも、本当は……こんな過去、あなたに見せるべきじゃなかったのかもしれません。もう還らない人のことなんて、思い出しても切なくなるだけですもの。",
            ["DialogueId"] = 80200335,
            ["FacialId"] = {
                [1] = "790008:Beg",
                },
            ["FinalCamera"] = "-69.18502,-422.553558,149.098633,0.000043,-3.200346,79.0131,45.0,450.246735,false,Manual,12.098981",
            ["GUID"] = "C8C5EB76",
            ["NextDialogue"] = 80200336,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Sigh_End",
                [2] = "790008:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EB76",
            },
        [80200336] = {
            ["Content"] = "只是这枯荣阁是我们从小生长的地方，恐怕所有的音容草里，都存放着我们的过往。",
            ["ContentJP"] = "だけど、ここは……私たちが育った場所。枯栄閣にある音容草のすべてに、きっと私たちの記憶が眠っているんです。",
            ["DialogueId"] = 80200336,
            ["GUID"] = "C8C5EBA0",
            ["NextDialogue"] = 80200337,
            ["SpeakNpcId"] = 790053,
            ["TurnTo"] = {
                [1] = "790053:p(70)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EBA0",
            },
        [80200337] = {
            ["Camera"] = "-23.33609,-427.601105,149.098633,0.00004,16.598991,57.414169,45.0,450.246735,false,Manual,12.098981",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "所以下一次，还是由我来尝试吧，好吗？",
            ["ContentJP"] = "だから、次は……私が、自分で確かめたいんです。よろしいですか？",
            ["DialogueId"] = 80200337,
            ["FinalCamera"] = "-23.33609,-427.601105,149.098633,0.000045,22.798664,61.012764,45.0,450.246735,false,Manual,12.098981",
            ["GUID"] = "C8C5EBCA",
            ["NextOptions"] = {
                [1] = 802003371,
                [2] = 802003372,
                },
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EBCA",
            },
        [80200339] = {
            ["Content"] = "谢谢。",
            ["ContentJP"] = "ありがとうございます。",
            ["DialogueId"] = 80200339,
            ["GUID"] = "C8C5EC1E",
            ["NextDialogue"] = 80200342,
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EC1E",
            },
        [80200341] = {
            ["Content"] = "呵呵，下次相约之时，我再讲给你听吧。",
            ["ContentJP"] = "ふふっ、また今度会ったときに話してあげますね。",
            ["DialogueId"] = 80200341,
            ["GUID"] = "C8C5EC72",
            ["NextDialogue"] = 80200342,
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EC72",
            },
        [80200342] = {
            ["Content"] = "好，那去寻找下一个地方吧。",
            ["ContentJP"] = "さあ、次の場所へ行きましょう。",
            ["DialogueId"] = 80200342,
            ["GUID"] = "C8C5EC9C",
            ["SpeakNpcId"] = 790053,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EC9C",
            },
        [80200343] = {
            ["Content"] = "转场，枯荣阁野外",
            ["ContentJP"] = "場面転換：枯栄閣・野外",
            ["DialogueId"] = 80200343,
            ["GUID"] = "C8C5ECC6",
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ECC6",
            },
        [80200344] = {
            ["Camera"] = "172.202026,4449.555664,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "找到了。",
            ["ContentJP"] = "見つけました。",
            ["DialogueId"] = 80200344,
            ["FinalCamera"] = "402.414307,4427.007812,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
            ["GUID"] = "C8C5ECF0",
            ["NextDialogue"] = 80200345,
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 10,
            ["TurnTo"] = {
                [1] = "790008:n(790053)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ECF0",
            },
        [80200345] = {
            ["Content"] = "要不要猜一猜，这是音容草，还是怀梦草呢？",
            ["ContentJP"] = "さて、これは音容草でしょうか、それとも憶夢草……？",
            ["DialogueId"] = 80200345,
            ["GUID"] = "C8C5ED1A",
            ["NextOptions"] = {
                [1] = 802003451,
                [2] = 802003452,
                },
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["TurnTo"] = {
                [1] = "790053:n(790008)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ED1A",
            },
        [80200348] = {
            ["Camera"] = "-514.179199,-65.437241,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
            ["Content"] = "看着没什么殊异之处，但摸在手里，确实有些极其微妙的差别……我猜这就是我们要找的怀梦草。",
            ["ContentJP"] = "見た目には大差ありませんが、手で触れると、ほんのわずかに違いを感じます。……恐らく、これは憶夢草でしょう。",
            ["DialogueId"] = 80200348,
            ["FinalCamera"] = "-516.200806,-55.210449,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
            ["GUID"] = "C8C5ED98",
            ["NextDialogue"] = 80200349,
            ["Scripts"] = "PARA{\
PlayAnimation{_delay{5.1},ActorId{790053},AnimationId{\"Confident_End\"},Duration{1}},\
PlayAnimation{_delay{6.1},ActorId{790053},AnimationId{\"Explain01_Start\"},Duration{1}},\
PlayAnimation{_delay{8.1},ActorId{790053},AnimationId{\"Explain01_End\"},Duration{1}}\
}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5ED98",
            },
        [80200349] = {
            ["Camera"] = "83.302071,146.197098,182.37207,0.000091,-11.599047,-118.401756,40.000011,172.35437,false,Manual,3.813417",
            ["Content"] = "如果不是连续失败两次，我恐怕永远不会有这样的发现。",
            ["ContentJP"] = "もし、あのとき二度も失敗していなければ、この違いには気づけなかったかもしれません。",
            ["DialogueId"] = 80200349,
            ["GUID"] = "C8C5EDC2",
            ["NextDialogue"] = 80200350,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EDC2",
            },
        [80200350] = {
            ["Camera"] = "5.743984,121.353485,148.166016,0.000061,-2.198931,1.794543,40.000023,104.974152,false,Manual,8.259511",
            ["Content"] = "第一个发现这两种植物的人是怎么做到的？难道她也像我们一样，一点一点试出来的？",
            ["ContentJP"] = "最初にこれを見分けた人って、どうやって判断したんだろ？もしかして、{性别:僕|私}たちみたいに手探りで試したのかな。",
            ["DialogueId"] = 80200350,
            ["GUID"] = "C8C5EDEC",
            ["NextDialogue"] = 80200351,
            ["Scripts"] = "PlayAnimation{_delay{5.1},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EDEC",
            },
        [80200351] = {
            ["Camera"] = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
            ["Content"] = "呵……是呀，她是怎么做到的呢？",
            ["ContentJP"] = "ふふ……そうかもしれませんね。",
            ["DialogueId"] = 80200351,
            ["FacialId"] = {
                [1] = "790053:Think01",
                },
            ["GUID"] = "C8C5EE16",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextDialogue"] = 80200352,
            ["Scripts"] = "PlayFacial{_delay{2.1},ActorId{790053},FacialId{\"Sad03\"}}",
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790053:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE16",
            },
        [80200352] = {
            ["Camera"] = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
            ["Content"] = "想必，一定经过无数次危险，与无数次不眠不休的钻研吧，即使不被理解，即使历经伤痛，她也从来没有放弃过。",
            ["ContentJP"] = "おそらく、数えきれないほどの危険を乗り越え、眠れぬ夜を過ごし、理解されず、傷つくこともあったでしょう。それでも決して諦めなかった。",
            ["DialogueId"] = 80200352,
            ["FinalCamera"] = "30.070026,119.496765,135.290039,0.000068,30.998163,-82.200356,50.000008,3999.122314,false,Manual,9.225292",
            ["GUID"] = "C8C5EE40",
            ["LookAt"] = {
                [1] = "790053:p(BP_200401fushu)",
                },
            ["NextDialogue"] = 80200353,
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 32,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE40",
            },
        [80200353] = {
            ["Content"] = "一切都是为了从无数个一百年前，一直流传到今天的那个悬壶济世的理想。",
            ["ContentJP"] = "すべては——何百年も受け継がれてきた、「人を癒す」という、たった一つの理想のために。",
            ["DialogueId"] = 80200353,
            ["Duration"] = 2,
            ["GUID"] = "C8C5EE6A",
            ["NextDialogue"] = 80200354,
            ["SpeakNpcId"] = 790053,
            ["TalkActionId"] = {
                [1] = "790008:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE6A",
            },
        [80200354] = {
            ["Camera"] = "-159.132416,-51.042709,147.863281,0.00019,-2.796628,27.59856,50.000011,312.992676,false,Manual,3.221528",
            ["Content"] = "其实，还有一件事忘了告诉你。我刚才遇见的扶风说，匍地枝与隙中花更合适治疗多梦少眠。",
            ["ContentJP"] = "そういえば、フーフォンが言ってたよ。地伏せ枝と隙間で咲く花の方が、不眠には合ってるって。",
            ["DialogueId"] = 80200354,
            ["FacialId"] = {
                [1] = "790008:Beg",
                },
            ["GUID"] = "C8C5EE94",
            ["LookAt"] = {
                [1] = "790053:n(790053)",
                },
            ["NextDialogue"] = 80200355,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EE94",
            },
        [80200355] = {
            ["Content"] = "怀梦草虽能助眠，但会在梦中看到无法忘怀之事。",
            ["ContentJP"] = "憶夢草は眠れるけど、忘れたくない夢を見てしまうってさ。",
            ["DialogueId"] = 80200355,
            ["GUID"] = "C8C5EEBE",
            ["NextDialogue"] = 80200356,
            ["Scripts"] = "PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{\"DisagreeHead\"},Duration{1}}",
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EEBE",
            },
        [80200356] = {
            ["Camera"] = "71.251167,76.700455,164.569336,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
            ["Content"] = "也就是说，我不需要怀梦草了，但即使如此，你也要尝试吗？",
            ["ContentJP"] = "つまり、{性别:僕|私}には憶夢草はもう必要ないわけだけど。……それでも、試すの？",
            ["DialogueId"] = 80200356,
            ["Duration"] = 1,
            ["FinalCamera"] = "66.068237,71.181648,163.882812,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
            ["GUID"] = "C8C5EEE8",
            ["NextDialogue"] = 80200357,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Shy03_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EEE8",
            },
        [80200357] = {
            ["Content"] = "扶疏没有说话，只是照旧将那叶尖放入口中。这一次，没有不安与责难，你听到了均匀的呼吸声，以及一句浅浅的梦呓——",
            ["ContentJP"] = "フーシュは答えず、静かにその葉の先を口に含んだ。そこにあったのは、不安でも、迷いでもなく——穏やかな呼吸と、優しい寝言だった。",
            ["DialogueId"] = 80200357,
            ["Duration"] = 2,
            ["GUID"] = "C8C5EF12",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80200358,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EF12",
            },
        [80200358] = {
            ["Camera"] = "10.260178,29.508621,158.517578,0.00016,-13.799194,-104.60054,55.0,26.127415,false,Manual,15.973291",
            ["CameraBlendCurve"] = "easeInOutQuad",
            ["Content"] = "唉……下一次，换个道歉礼物吧。",
            ["ContentJP"] = "……はあ……次はもう少し、まともなお詫びの品にしてほしいですね。",
            ["DialogueId"] = 80200358,
            ["FacialId"] = {
                [1] = "790053:Close",
                },
            ["FinalCamera"] = "13.641603,40.02512,158.702148,0.000164,-2.999177,-107.99968,55.000008,38.118717,false,Manual,15.973291",
            ["GUID"] = "C8C5EF3C",
            ["Scripts"] = "PlayFacial{_delay{1.5},ActorId{790053},FacialId{\"SpecialSmile\"}}",
            ["SpeakNpcId"] = 790053,
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Fushu/004/C8C5EF3C",
            },
        [80210101] = {
            ["Camera"] = "805.707031,-8.211914,540.876953,0.0,0.0,-177.666962,25.0,125.0,false,DoNotOverride,2.8",
            ["Content"] = "侠自然是快意恩仇的，他们手提三尺剑，专爱打抱不平。",
            ["ContentJP"] = "侠とは、恩と仇をはっきりさせる者。彼らは剣ひとつで世をさすらい、不正を見過ごさず。",
            ["DialogueId"] = 80210101,
            ["FinalCamera"] = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8CC2DB2",
            ["NextDialogue"] = 80210102,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2DB2",
            },
        [80210102] = {
            ["Content"] = "浪迹天涯，四海飘零，不受任何羁绊。要按时回家的人，武艺再高，也更像是镖师，这听起来就比侠客不潇洒得多了。",
            ["ContentJP"] = "逆に、家の持つ者はどれだけ武芸に通じても、ただの用心棒に過ぎぬ、大胆洒脱な侠客とは比べ物にならない。",
            ["DialogueId"] = 80210102,
            ["GUID"] = "C8CC2DDC",
            ["NextDialogue"] = 80210103,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2DDC",
            },
        [80210103] = {
            ["Camera"] = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
            ["Content"] = "你要走了。",
            ["ContentJP"] = "行くのか？",
            ["DialogueId"] = 80210103,
            ["FacialId"] = {
                [1] = "790065:CM_Sad01",
                [2] = "790066:CM_Sad01",
                },
            ["GUID"] = "C8CC2E06",
            ["LookAt"] = {
                [1] = "790065:n(790066)",
                },
            ["NextDialogue"] = 80210104,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790067:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "790065:n(790066)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E06",
            },
        [80210104] = {
            ["Camera"] = "390.390625,-180.267578,96.469727,0.000003,-1.798122,157.194687,30.0,337.309082,false,Manual,2.8",
            ["Content"] = "我要走了。",
            ["ContentJP"] = "ええ。行くとも。",
            ["DialogueId"] = 80210104,
            ["FinalCamera"] = "310.414062,-146.627441,93.75,0.000003,0.0,157.194702,30.0,323.332245,false,Manual,2.8",
            ["GUID"] = "C8CC2E30",
            ["NextDialogue"] = 80210105,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E30",
            },
        [80210105] = {
            ["Content"] = "你毕竟还是要走。",
            ["ContentJP"] = "そうか、もう行くのか。",
            ["DialogueId"] = 80210105,
            ["GUID"] = "C8CC2E5A",
            ["NextDialogue"] = 80210106,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E5A",
            },
        [80210106] = {
            ["Content"] = "我毕竟还是要走。",
            ["ContentJP"] = "もう行かなくては。",
            ["DialogueId"] = 80210106,
            ["GUID"] = "C8CC2E84",
            ["NextDialogue"] = 80210107,
            ["SpeakNpcId"] = 790066,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2E84",
            },
        [80210107] = {
            ["Content"] = "你本不该走的。",
            ["ContentJP"] = "ここまで…か。",
            ["DialogueId"] = 80210107,
            ["GUID"] = "C8CC2EAE",
            ["NextDialogue"] = 80210108,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2EAE",
            },
        [80210108] = {
            ["Content"] = "可我已经要走了。",
            ["ContentJP"] = "ここまでです。",
            ["DialogueId"] = 80210108,
            ["GUID"] = "C8CC2ED8",
            ["NextDialogue"] = 80210109,
            ["SpeakNpcId"] = 790066,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2ED8",
            },
        [80210109] = {
            ["Content"] = "你为什么要走？",
            ["ContentJP"] = "一体……何のために。",
            ["DialogueId"] = 80210109,
            ["GUID"] = "C8CC2F02",
            ["NextDialogue"] = 80210110,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F02",
            },
        [80210110] = {
            ["Content"] = "因为要留人的性命。",
            ["ContentJP"] = "……これも、人を救うため。",
            ["DialogueId"] = 80210110,
            ["GUID"] = "C8CC2F2C",
            ["NextDialogue"] = 80210111,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F2C",
            },
        [80210111] = {
            ["Content"] = "留谁的性命？",
            ["ContentJP"] = "誰を？",
            ["DialogueId"] = 80210111,
            ["GUID"] = "C8CC2F56",
            ["NextDialogue"] = 80210112,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F56",
            },
        [80210112] = {
            ["Camera"] = "-97.171875,135.871094,124.923828,0.000072,-11.800135,-56.803616,25.0,226.88681,false,Manual,2.8",
            ["Content"] = "留你的性命！",
            ["ContentJP"] = "貴殿を。",
            ["DialogueId"] = 80210112,
            ["Duration"] = 4,
            ["GUID"] = "C8CC2F80",
            ["LookAt"] = {
                [1] = "790066:n(790065)",
                },
            ["NextDialogue"] = 80210113,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790065:Explain01_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["TurnTo"] = {
                [1] = "790066:n(790065)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2F80",
            },
        [80210113] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "哎呀，果然帅气，这次我们交换，让我来说：“留你的性命！”",
            ["ContentJP"] = "……いやあ、やっぱりこのセリフってかっこいいなぁ。さぁ、交代交代。俺も一度「貴殿を」って言ってみたいぜ。 ",
            ["DialogueId"] = 80210113,
            ["FacialId"] = {
                [1] = "790065:CM_Happy01",
                },
            ["GUID"] = "C8CC2FAA",
            ["NextDialogue"] = 80210114,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Huanhu_Nan_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2FAA",
            },
        [80210114] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "蠢死啦，我只答应你演一遍的。",
            ["ContentJP"] = "ばかばかしい。次はなしって言ったでしょ。",
            ["DialogueId"] = 80210114,
            ["FacialId"] = {
                [1] = "790066:CM_Idle",
                },
            ["GUID"] = "C8CC2FD4",
            ["NextDialogue"] = 80210115,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2FD4",
            },
        [80210115] = {
            ["Camera"] = "-154.820312,-313.032227,46.03125,0.000064,4.999999,61.640118,22.063116,681.604492,false,Manual,2.8",
            ["Content"] = "你们……这是在干什么。",
            ["ContentJP"] = "あんたたちは……何をしている。",
            ["DialogueId"] = 80210115,
            ["FinalCamera"] = "-182.828125,-367.04541,41.943359,0.000061,3.999984,62.639935,22.063116,681.604492,false,Manual,2.8",
            ["GUID"] = "C8CC2FFE",
            ["NextDialogue"] = 80210116,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790066:Sigh_End",
                },
            ["ToFinalCameraBlendTime"] = 8,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC2FFE",
            },
        [80210116] = {
            ["Camera"] = "274.847656,276.966309,232.944336,0.00018,-20.000671,-141.973434,30.0,445.724579,false,Manual,4.0",
            ["Content"] = "这都不知道，我们这是在模仿飘零人对话呀。",
            ["ContentJP"] = "はあ？そんなことも知らねぇかよ、俺たちは流れ者のまねをしてるんだ。",
            ["DialogueId"] = 80210116,
            ["FinalCamera"] = "262.335938,267.178223,227.157227,0.00018,-20.000671,-141.973434,30.0,248.094116,false,Manual,4.0",
            ["GUID"] = "C8CC3028",
            ["LookAt"] = {
                [1] = "790067:n(790065)",
                },
            ["NextDialogue"] = 80210117,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790067:ScratchHead_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["TurnTo"] = {
                [1] = "790065:n(790067)",
                [2] = "790066:n(790067)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3028",
            },
        [80210117] = {
            ["Content"] = "这场对话是之前最流行的飘零人小说里，最有名的一段台词了，每当读到这里的时候，我都恨不得钻进书里去。",
            ["ContentJP"] = "先の会話はな、最近もっとも流行してる流れ者小説で一番有名なセリフさ。めちゃすっげーんだ！ここ読むたび、本の中に飛び込みたくなっちゃうぜ！",
            ["DialogueId"] = 80210117,
            ["GUID"] = "C8CC3052",
            ["NextDialogue"] = 80210118,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3052",
            },
        [80210118] = {
            ["Content"] = "要不是每天被阿妈揪着耳朵读书，我肯定去奔赴那山外山学得一身好本领，快意恩仇！",
            ["ContentJP"] = "毎日オカンに耳引っぱられて勉強させられてなきゃ、俺だってあの山外山にでも行って、武芸をみっちり身につけて、堂々たる侠客になってやるのに！",
            ["DialogueId"] = 80210118,
            ["GUID"] = "C8CC307C",
            ["LookAt"] = {
                [1] = "790065:n(790066)",
                },
            ["NextDialogue"] = 80210119,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC307C",
            },
        [80210119] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "你要是和我一样早早做完功课，阿妈才懒得管你呢。",
            ["ContentJP"] = "私みたいにさっさと宿題済ませたら、オカンにガミガミ言われないでしょ。",
            ["DialogueId"] = 80210119,
            ["GUID"] = "C8CC30A6",
            ["LookAt"] = {
                [1] = "790066:n(790065)",
                },
            ["NextDialogue"] = 80210120,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC30A6",
            },
        [80210120] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "阿妈是偏心，她的那把佩剑，你拿来砍柴杀鱼她都不会说什么。而我想要拿起来舞一个剑花，她都要说我是玩物丧志呢。",
            ["ContentJP"] = "不公平だ。なんでお前はオカンの剣で柴刈りや魚を捌いても何の問題もねぇのに、俺があの剣を振るうと「遊びに夢中になって志を失っちゃう」ってオカンに言われるんだよ。",
            ["DialogueId"] = 80210120,
            ["GUID"] = "C8CC30D0",
            ["NextDialogue"] = 80210121,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC30D0",
            },
        [80210121] = {
            ["Camera"] = "-97.171875,135.871094,124.923828,0.000072,-11.800135,-56.803616,25.0,226.88681,false,Manual,2.8",
            ["Content"] = "那当然了，我这可都干得是正事，给阿妈帮忙的。你拿起剑来舞来舞去，不伤到自己都算是好的。",
            ["ContentJP"] = "当然でしょ。私、家事の手伝いをしてるんだから。あんたこそ、あの剣振り回して、ケガでもしたらどうすんの。",
            ["DialogueId"] = 80210121,
            ["GUID"] = "C8CC30FA",
            ["NextDialogue"] = 80210122,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC30FA",
            },
        [80210122] = {
            ["Camera"] = "112.191406,49.433105,156.642578,0.000145,-12.799466,173.017639,35.0,178.705887,false,Manual,2.8",
            ["Content"] = "要我说啊，阿妈就是没读过飘零人小说，否则才不会由着你拿着这把剑干杂活。",
            ["ContentJP"] = "俺に言わせりゃ、オカンがまだ流れ者小説を読んでねぇからだ。読んでりゃ、こんなことさせたりしねぇっての！",
            ["DialogueId"] = 80210122,
            ["FinalCamera"] = "80.292969,53.341797,149.338867,0.000145,-12.799466,173.017639,35.000011,149.474472,false,Manual,2.8",
            ["GUID"] = "C8CC3124",
            ["NextDialogue"] = 80210123,
            ["SpeakNpcId"] = 790065,
            ["TalkActionId"] = {
                [1] = "790065:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3124",
            },
        [80210123] = {
            ["Content"] = "应该给我才是，让我练习剑谱，等我长大了就可以保护阿姐你和阿妈。",
            ["ContentJP"] = "あの剣は俺に渡すべきだ。ちゃんと剣術を極めて、大人になったらお前のこと守ってやるからな！",
            ["DialogueId"] = 80210123,
            ["GUID"] = "C8CC314E",
            ["NextDialogue"] = 80210124,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC314E",
            },
        [80210124] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "你就是小说看多啦，现在有大风九章，根本不需要飘零人保护大家的。",
            ["ContentJP"] = "あんたはね、本を読み過ぎるよ。大風九章がある限り、流れ者なんていらないわよ。",
            ["DialogueId"] = 80210124,
            ["GUID"] = "C8CC3178",
            ["NextDialogue"] = 80210125,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3178",
            },
        [80210125] = {
            ["Camera"] = "160.730469,298.234375,220.72168,0.000052,-13.400564,-69.973022,35.000011,125.0,false,Manual,2.8",
            ["Content"] = "说得是啊，现在这个时日，确实已经没多少个飘零人了。",
            ["ContentJP"] = "まあ、そりゃそうだな。今の世の中じゃ、侠客なんてもうほとんどいねぇ。",
            ["DialogueId"] = 80210125,
            ["FinalCamera"] = "165.699219,284.596191,217.265625,0.000052,-13.400564,-69.973022,35.000011,110.763969,false,Manual,2.8",
            ["GUID"] = "C8CC31A2",
            ["NextDialogue"] = 80210126,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC31A2",
            },
        [80210126] = {
            ["Camera"] = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
            ["Content"] = "啊，不好意思，大哥哥，刚刚我只顾着和弟弟说话了，忘了你还在边上。",
            ["ContentJP"] = "ああ、すみません。お兄さん——さっきは弟との話に夢中になっていて、お兄さんがいるのを忘れてました。",
            ["DialogueId"] = 80210126,
            ["GUID"] = "C8CC31CC",
            ["LookAt"] = {
                [1] = "790065:n(790067)",
                [2] = "790066:n(790067)",
                },
            ["NextDialogue"] = 80210127,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC31CC",
            },
        [80210127] = {
            ["Camera"] = "153.617188,127.562012,157.194336,0.000101,-18.800348,-103.577133,35.000011,187.821686,false,Manual,2.8",
            ["Content"] = "请问你来这里是……找阿妈吗？她吩咐过，不见来客的。",
            ["ContentJP"] = "お兄さん……母に会いたいの？母は誰にも会いませんよ。",
            ["DialogueId"] = 80210127,
            ["GUID"] = "C8CC31F6",
            ["LookAt"] = {
                [1] = "790067:n(790066)",
                },
            ["NextDialogue"] = 80210128,
            ["SpeakNpcId"] = 790066,
            ["TalkActionId"] = {
                [1] = "790066:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC31F6",
            },
        [80210128] = {
            ["Camera"] = "-2.984375,-178.594238,79.739258,0.000157,10.398853,55.621544,40.0,463.63916,false,Manual,2.8",
            ["Content"] = "嗯，看得出来，她之前佩剑不离身，现在这把佩剑却在你们手上，那我自然明白她是什么意思。",
            ["ContentJP"] = "ああ、見りゃ分かる。彼女がいつも身につけてた剣が、今はあんたらの手にある。その理由は――言うまでもねぇ。",
            ["DialogueId"] = 80210128,
            ["FinalCamera"] = "13.074219,-155.074219,84.959961,0.000157,10.398853,55.621544,40.0,463.63916,false,Manual,2.8",
            ["GUID"] = "C8CC3220",
            ["NextDialogue"] = 80210129,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3220",
            },
        [80210129] = {
            ["Camera"] = "274.847656,276.966309,232.944336,0.00018,-20.000671,-141.973434,30.0,445.724579,false,Manual,4.0",
            ["Content"] = "你认识阿妈？能和我讲讲她年轻时候的事情吗？我总怀疑她是一位大侠，否则怎么会有这么一把好剑。",
            ["ContentJP"] = "兄ちゃん、オカンの知り合い？ だったらさ、若いころのオカンの話、教えてよ。あの人、かなり上等な剣を持ってるし、若いころは相当な侠客だったんじゃねぇかって、ずっと思ってたんだ。",
            ["DialogueId"] = 80210129,
            ["FinalCamera"] = "262.335938,267.178223,227.157227,0.00018,-20.000671,-141.973434,30.0,248.094116,false,Manual,4.0",
            ["GUID"] = "C8CC324A",
            ["LookAt"] = {
                [1] = "790067:n(790065)",
                },
            ["NextDialogue"] = 80210130,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 9,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC324A",
            },
        [80210130] = {
            ["Content"] = "每次我缠着她，她却又什么都不肯说。",
            ["ContentJP"] = "けどさ、俺には何も言ってくれないんだぜ。",
            ["DialogueId"] = 80210130,
            ["GUID"] = "C8CC3274",
            ["NextDialogue"] = 80210131,
            ["SpeakNpcId"] = 790065,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3274",
            },
        [80210131] = {
            ["Camera"] = "105.101562,49.699219,200.319336,0.000131,-3.00042,53.422153,35.000011,175.117645,false,Manual,2.8",
            ["Content"] = "那，我也是受人所托来找她，但既然她无意相见，那么我也不便多说。",
            ["ContentJP"] = "ま、俺も頼まれで来たから。向こうが会う気がねぇなら、余計なことは言わねぇ。",
            ["DialogueId"] = 80210131,
            ["FinalCamera"] = "112.863281,60.17041,199.636719,0.000131,-3.00042,53.422176,35.000011,175.117645,false,Manual,2.8",
            ["GUID"] = "C8CC329E",
            ["LookAt"] = {
                [1] = "790067:n(790065)",
                },
            ["NextDialogue"] = 80210132,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 6,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC329E",
            },
        [80210132] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "什么嘛，没劲。我看你这副行头，又背着剑，还以为能看到阿妈出手呢。",
            ["ContentJP"] = "なんだよ、つまんねーな。こんな格好で剣まで背負ってるくせに、オカンの勇姿が見られるのかと思って期待したのによ。",
            ["DialogueId"] = 80210132,
            ["GUID"] = "C8CC32C8",
            ["NextDialogue"] = 80210133,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC32C8",
            },
        [80210133] = {
            ["Camera"] = "393.839844,444.308105,335.135742,0.000015,-26.198637,-130.560333,35.000011,240.726898,false,Manual,2.8",
            ["Content"] = "哈哈，假以时日，会见到的。那么，在下告辞。",
            ["ContentJP"] = "……はは。いつかまたな。じゃ、ここまでだ。",
            ["DialogueId"] = 80210133,
            ["FacialId"] = {
                [1] = "790067:Smile02",
                },
            ["FinalCamera"] = "359.804688,403.016113,308.810547,0.000015,-26.198637,-130.560333,35.000011,290.796356,false,Manual,2.8",
            ["GUID"] = "C8CC32F2",
            ["LookAt"] = {
                [1] = "790067:n(790067)",
                },
            ["NextDialogue"] = 80210134,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 4,
            ["TurnTo"] = {
                [1] = "790067:p(180)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC32F2",
            },
        [80210134] = {
            ["Camera"] = "150.417969,40.62793,98.314453,0.000076,-0.199004,171.387024,30.0,201.271973,false,Manual,2.8",
            ["Content"] = "真的假的。喂，阿姐，听见了没，快别用阿妈的剑杀鸡了，以后还会用的，锈了怎么办。",
            ["ContentJP"] = "マジかよ……おい、ねえちゃん、聞いたか？ オカンの剣は大事にしなきゃダメだろ。錆びが付いたらどうすんだよ！",
            ["DialogueId"] = 80210134,
            ["FacialId"] = {
                [1] = "790065:CM_Happy01",
                },
            ["GUID"] = "C8CC331C",
            ["LookAt"] = {
                [1] = "790065:n(790066)",
                },
            ["NextDialogue"] = 80210135,
            ["SpeakNpcId"] = 790065,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC331C",
            },
        [80210135] = {
            ["Camera"] = "33.960938,151.338867,112.264648,0.000069,-7.200624,-74.774574,35.000011,224.596802,false,Manual,2.8",
            ["Content"] = "一惊一乍的，以后的事，以后再说。",
            ["ContentJP"] = "だからさ、いちいち構えすぎ。まだこれからの話でしょ？",
            ["DialogueId"] = 80210135,
            ["GUID"] = "C8CC3346",
            ["LookAt"] = {
                [1] = "790066:n(790065)",
                },
            ["NextDialogue"] = 80210136,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3346",
            },
        [80210136] = {
            ["Camera"] = "71.171875,-18.830078,134.579102,0.000001,10.798099,59.223282,35.000011,265.938843,false,Manual,2.8",
            ["Content"] = "倒是这位大哥哥，不妨坐下来歇息一会儿再走？",
            ["ContentJP"] = "それよりも……お兄さん、よければ、ここに座って、休んでください！",
            ["DialogueId"] = 80210136,
            ["FinalCamera"] = "71.171875,-18.830078,134.579102,0.0,10.798091,56.999958,35.000011,265.938843,false,Manual,2.8",
            ["GUID"] = "C8CC3370",
            ["LookAt"] = {
                [1] = "790065:n(790067)",
                [2] = "790066:n(790067)",
                },
            ["NextDialogue"] = 80210137,
            ["SpeakNpcId"] = 790066,
            ["ToFinalCameraBlendTime"] = 4,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC3370",
            },
        [80210137] = {
            ["Camera"] = "-152.511719,-805.267578,105.516602,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
            ["Content"] = "这可不行，我身后可是一直有一群小狗在追着，停留不得，就不打扰你们了。",
            ["ContentJP"] = "そいつは困るな。お兄さんの後ろに何匹のワンチャンが付いてるから、立ち止まってる暇はないさ。じゃあな。",
            ["DialogueId"] = 80210137,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "-218.78125,-1024.449219,87.90332,0.000007,4.396415,73.174652,20.0,125.0,false,DoNotOverride,2.8",
            ["GUID"] = "C8CC339A",
            ["Scripts"] = "MoveTo{ActorId{790067},TargetPoint{\"BP_NewTargetPoint_150301\"},MoveSpeed{150}}",
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/001/C8CC339A",
            },
        [80210201] = {
            ["Camera"] = "-3911.427734,-2583.495605,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
            ["Content"] = "侠客爱憎分明，情天恨海，是非多多。更有好事者把这些纠缠写成书册，人人爱看。",
            ["ContentJP"] = "侠とは、愛と憎をくっきりさせる者。彼らの因縁が混じる波乱万丈な人生は小説のテーマとなり、多くの人を魅了させた。",
            ["DialogueId"] = 80210201,
            ["FinalCamera"] = "-3781.285156,-2732.086426,1694.981445,0.000021,-15.999539,41.210613,30.000002,5058.067383,false,Manual,2.8",
            ["GUID"] = "C8CC3E1A",
            ["NextDialogue"] = 80210202,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E1A",
            },
        [80210202] = {
            ["Content"] = "人人皆向往能策马红尘，但身在其中者，往往是另外一番愁滋味。",
            ["ContentJP"] = "されど、浮世の真ん中にいる彼ら自身の気持ちは、誰に分かるであろう。",
            ["DialogueId"] = 80210202,
            ["GUID"] = "C8CC3E44",
            ["NextDialogue"] = 80210203,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E44",
            },
        [80210203] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "你回来了，鸣鸾。",
            ["ContentJP"] = "帰ったな。メイラン。",
            ["DialogueId"] = 80210203,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["FinalCamera"] = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC3E6E",
            ["LookAt"] = {
                [1] = "790067:n(790068)",
                [2] = "790068:n(790067)",
                },
            ["NextDialogue"] = 80210204,
            ["Scripts"] = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E6E",
            },
        [80210204] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "我回来了，刻舟。",
            ["ContentJP"] = "……ただいま。カシュウ。",
            ["DialogueId"] = 80210204,
            ["FacialId"] = {
                [1] = "790068:CM_Smile01",
                },
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC3E98",
            ["NextDialogue"] = 80210205,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Agree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3E98",
            },
        [80210205] = {
            ["Camera"] = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
            ["Content"] = "那么结果呢？",
            ["ContentJP"] = "で、どうだった？",
            ["DialogueId"] = 80210205,
            ["FinalCamera"] = "-361.898438,-71.477051,182.797852,0.0001,-12.798893,15.006591,20.0,592.475586,false,Manual,4.0",
            ["GUID"] = "C8CC3EC2",
            ["NextDialogue"] = 80210206,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3EC2",
            },
        [80210206] = {
            ["Content"] = "自然是有一些的。",
            ["ContentJP"] = "ああ、まぁまぁ。",
            ["DialogueId"] = 80210206,
            ["GUID"] = "C8CC3EEC",
            ["NextDialogue"] = 80210207,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3EEC",
            },
        [80210207] = {
            ["Camera"] = "109.556641,-109.840332,171.128906,0.000122,-10.598042,137.795868,20.0,275.546844,false,Manual,4.0",
            ["Content"] = "我踏足了五个国家，悟出了五门新功夫。",
            ["ContentJP"] = "僕は、五つの国を巡り、五つの技を悟った。",
            ["DialogueId"] = 80210207,
            ["FinalCamera"] = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
            ["GUID"] = "C8CC3F16",
            ["NextDialogue"] = 80210208,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F16",
            },
        [80210208] = {
            ["Camera"] = "1812.060547,3093.102783,-750.477539,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
            ["Content"] = "我先是西出了华胥，踏入了赫墨的瀚海。",
            ["ContentJP"] = "最初に華胥を西に出で、ケメトのアモス海原に入った。",
            ["DialogueId"] = 80210208,
            ["FinalCamera"] = "1251.640625,3319.118652,-659.09082,0.000029,8.600014,158.03595,15.133835,13322.412109,false,Manual,4.0",
            ["GUID"] = "C8CC3F40",
            ["NextDialogue"] = 80210209,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F40",
            },
        [80210209] = {
            ["Camera"] = "-1200.404297,23490.853516,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
            ["Content"] = "之前我听人说赫墨的瀚海是万里黄沙，酷热无比。于是便拿定主意，夜半披星赶路。",
            ["ContentJP"] = "聞いていたとおり、あそこは容赦のない暑さが続く砂の大海原だ。だから、夜のうちに進むことにした。",
            ["DialogueId"] = 80210209,
            ["FinalCamera"] = "-1074.800781,23130.9375,354.0,0.000031,0.0,-70.761887,15.133835,13322.412109,false,Manual,4.0",
            ["GUID"] = "C8CC3F6A",
            ["NextDialogue"] = 80210210,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F6A",
            },
        [80210210] = {
            ["Content"] = "但我没料到夜半的沙漠却又奇寒无比，如果不做些什么必将冻毙其中，成为一具无名的白骨。",
            ["ContentJP"] = "ところが、夜は一転して凍てつく寒さ。そのままじゃ凍え死んで、名もなき骸骨になるところだった。",
            ["DialogueId"] = 80210210,
            ["GUID"] = "C8CC3F94",
            ["NextDialogue"] = 80210211,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3F94",
            },
        [80210211] = {
            ["Camera"] = "-23017.669922,21547.728516,8057.0,0.000038,14.399909,168.238129,22.934771,13322.412109,false,Manual,4.0",
            ["Content"] = "正当我烦恼该如何自救之时，我看到远处的地平上有几颗绿星忽闪忽闪，却又渐渐变大。",
            ["ContentJP"] = "どうしたものかと悩んでいたとき、はるか地平の向こうに緑の光がちらちら明滅するのが目に入った。しかも、その光が少しずつ大きくなっていることに気づいた。",
            ["DialogueId"] = 80210211,
            ["FinalCamera"] = "-23384.009766,19835.208984,8057.0,0.000038,14.399909,166.236816,22.934771,13322.412109,false,Manual,4.0",
            ["GUID"] = "C8CC3FBE",
            ["NextDialogue"] = 80210212,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3FBE",
            },
        [80210212] = {
            ["Content"] = "那些绿星都是成对的，并且远远地也能透着股肃杀之气，像是典籍上提到的贪狼星。我突然醒悟过来，这并非是什么星星，而是狼的眼睛。",
            ["ContentJP"] = "最初は対になった星かと思ったんだが、遠く離れていても刺すような殺気が伝わってきて、ようやく察した——星じゃない。オオカミの目だ。",
            ["DialogueId"] = 80210212,
            ["GUID"] = "C8CC3FE8",
            ["NextDialogue"] = 80210213,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC3FE8",
            },
        [80210213] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "可怜。",
            ["ContentJP"] = "かわいそうだな。",
            ["DialogueId"] = 80210213,
            ["GUID"] = "C8CC4012",
            ["NextDialogue"] = 80210214,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4012",
            },
        [80210214] = {
            ["Camera"] = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
            ["Content"] = "谁可怜。",
            ["ContentJP"] = "なんだって？",
            ["DialogueId"] = 80210214,
            ["FinalCamera"] = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
            ["GUID"] = "C8CC403C",
            ["NextDialogue"] = 80210215,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC403C",
            },
        [80210215] = {
            ["Content"] = "自然不是你可怜。",
            ["ContentJP"] = "お前のことじゃねぇよ。",
            ["DialogueId"] = 80210215,
            ["GUID"] = "C8CC4066",
            ["NextDialogue"] = 80210216,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4066",
            },
        [80210216] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "那你错怪我了，那些小狗崽子安然无恙，我只是拍晕了几只，把它们拖到沙丘的背风处，当做垫背，靠着它们的体温囫囵了一个晚上。",
            ["ContentJP"] = "勘違いしないでくれ。やつらは無事だ。何匹かを気絶させて、砂丘の陰まで引きずり、防寒用のクッションにしただけだ。",
            ["DialogueId"] = 80210216,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4090",
            ["NextDialogue"] = 80210217,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4090",
            },
        [80210217] = {
            ["Content"] = "了结它们倒也不难，但真要如此的话，我活不过第一个晚上。",
            ["ContentJP"] = "そこで仕留めるのは簡単だったが、やつらがいなければ一日目の夜は持ちこたえられなかっただろう。",
            ["DialogueId"] = 80210217,
            ["GUID"] = "C8CC40BA",
            ["NextDialogue"] = 80210218,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC40BA",
            },
        [80210218] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000083,-19.79907,13.007248,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "于你来说，几只野狼自然不是对手，但是我记得你的掌风素来刚猛凌厉，号称降龙，没想到居然能控制到恰好击晕活物而留其性命的地步。",
            ["ContentJP"] = "オオカミの群れなんざ、お前の敵じゃねぇ。だがよ、よくやったな。「降龍」と呼ばれたあの剛烈な掌法を、殺さねぇところでちゃんと止められたじゃねぇか。",
            ["DialogueId"] = 80210218,
            ["FinalCamera"] = "-29.367188,-76.549561,193.577148,0.000083,-19.79907,13.007559,30.000008,125.0,false,Manual,2.8",
            ["GUID"] = "C8CC40E4",
            ["NextDialogue"] = 80210219,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 12,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC40E4",
            },
        [80210219] = {
            ["Content"] = "这应该便是你悟出的第一门功夫吧。",
            ["ContentJP"] = "どうやら、それがお前が最初に悟った技ってわけだな。",
            ["DialogueId"] = 80210219,
            ["GUID"] = "C8CC410E",
            ["NextDialogue"] = 80210220,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC410E",
            },
        [80210220] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "不愧是刻舟刻大侠，立刻意识到关节所在。在那过后每晚我都是如此过夜，击晕野狼取暖。从而悟出了一套新的掌法，我称之为狼眠掌。",
            ["ContentJP"] = "さすが大侠客のカシュウ様、やっぱり鋭いね。その後も毎晩同じやり方で夜を越えた。その間に新しい掌法を悟った。僕はそれを「狼眠り」と呼んでいる。",
            ["DialogueId"] = 80210220,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4138",
            ["NextDialogue"] = 80210221,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Agree",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4138",
            },
        [80210221] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "好，好个狼眠掌，当浮一大白。",
            ["ContentJP"] = "いい名じゃねぇか。さぁ、いっきにいけ。",
            ["DialogueId"] = 80210221,
            ["FacialId"] = {
                [1] = "790067:Smile02",
                },
            ["FinalCamera"] = "-156.203125,50.284424,160.674805,0.000084,-5.398062,-15.405737,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC4162",
            ["NextDialogue"] = 80210222,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4162",
            },
        [80210222] = {
            ["Content"] = "那么第二门功夫，应当就是在海伯利亚帝国了。让我猜猜你悟出了什么……有类迅捷剑术的快剑？还是如同冰湖城坚冰一样厚重的长拳？",
            ["ContentJP"] = "そして次の技は……ヒュペリア帝国で悟っただろ。当ててやろうか……悟ったのは「レイピア剣術」みたいな速い剣？それともアイスレイク城の堅氷の如く、重厚なる「長拳」？",
            ["DialogueId"] = 80210222,
            ["GUID"] = "C8CC418C",
            ["NextDialogue"] = 80210223,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC418C",
            },
        [80210223] = {
            ["Camera"] = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["Content"] = "想不到你人一直在华胥，却还知道海伯利亚还有个冰湖城。",
            ["ContentJP"] = "まさか、ずっと華胥にいるお前がヒュペリアのアイスレイク城さえも知ってるとは。",
            ["DialogueId"] = 80210223,
            ["FinalCamera"] = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["GUID"] = "C8CC41B6",
            ["NextDialogue"] = 80210224,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 30,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC41B6",
            },
        [80210224] = {
            ["Content"] = "最近交了个朋友，在冰湖城居住，所以多少知道一些。",
            ["ContentJP"] = "つい最近、アイスレイク城に住んでる新しい友だちができてな。多少くらいは知ってるぜ。",
            ["DialogueId"] = 80210224,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["GUID"] = "C8CC41E0",
            ["NextDialogue"] = 80210225,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC41E0",
            },
        [80210225] = {
            ["Content"] = "原来如此，不过你猜错了，我着急赶路，直接去了卢卡。",
            ["ContentJP"] = "……なるほどな。だが違うよ、当時の僕は先に急いでいたのて、直接ルッカまで行ったね。",
            ["DialogueId"] = 80210225,
            ["GUID"] = "C8CC420A",
            ["NextDialogue"] = 80210226,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790067:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC420A",
            },
        [80210226] = {
            ["Content"] = "在前往卢卡的路上，我遭遇了传说中的海中精怪，被称作塞壬的异兽。它们貌似婵娟，但是却能以歌声摄人心魄。",
            ["ContentJP"] = "その途中、伝説の海獣「セイレーン」に遭った。花魁のような美貌に、美しい歌声で人を魅惑する。",
            ["DialogueId"] = 80210226,
            ["GUID"] = "C8CC4234",
            ["NextDialogue"] = 80210227,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4234",
            },
        [80210227] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "那岂不是和百年前的前辈莫抱琴一般，能以传音入密的功夫乱人心神？",
            ["ContentJP"] = "それじゃあ、百年前の「琴のバク」様みたいに、声だけで人を惑わすってわけか。",
            ["DialogueId"] = 80210227,
            ["GUID"] = "C8CC425E",
            ["NextDialogue"] = 80210228,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 7,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC425E",
            },
        [80210228] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "确实如出一辙。只是我当时没有想到这些，只顾着跳入水中，闭息凝神，又抓住了路过的巨鲸，才堪堪逃得性命。",
            ["ContentJP"] = "確かにそっくりだ。けれど、当時の僕はそこまで考えなかった。ただ水に入って呼吸を止め、意識を集中しようとするだけだっだ。そこで通りすがりのバハムートを掴めたことで、命を拾ったんだ。",
            ["DialogueId"] = 80210228,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4288",
            ["NextDialogue"] = 80210229,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Agree",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4288",
            },
        [80210229] = {
            ["Content"] = "但也因此，我的闭气功夫见长不少，几乎不再惧怕毒雾之类的雕虫小技。而我将这套法门唤作长鲸心法。",
            ["ContentJP"] = "そのおかげで、呼吸の術はより一層、向上してたよ。今の僕にとっては、毒霧のような小細工なんて取るに足らん。僕はあの時悟った術を「長鯨の心法」と呼んでいる。",
            ["DialogueId"] = 80210229,
            ["GUID"] = "C8CC42B2",
            ["NextDialogue"] = 80210230,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC42B2",
            },
        [80210230] = {
            ["Content"] = "然后呢？",
            ["ContentJP"] = "後は？",
            ["DialogueId"] = 80210230,
            ["GUID"] = "C8CC42DC",
            ["NextDialogue"] = 80210231,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC42DC",
            },
        [80210231] = {
            ["Content"] = "我在卢卡也没有停留太久，于是去了传颂会的雅什尼亚，在那里我……",
            ["ContentJP"] = "ルッカにはあまり長居してなかった。その後、僕は礼賛会のエルシュニアへ行き、そこで…",
            ["DialogueId"] = 80210231,
            ["GUID"] = "C8CC4306",
            ["NextDialogue"] = 80210232,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4306",
            },
        [80210232] = {
            ["Camera"] = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "稍等，我打断一下。",
            ["ContentJP"] = "ちょっと待ってくれ。",
            ["DialogueId"] = 80210232,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["GUID"] = "C8CC4330",
            ["NextDialogue"] = 80210233,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4330",
            },
        [80210233] = {
            ["Content"] = "你可以打断，但需要自罚一杯。",
            ["ContentJP"] = "いいけど、代わりに一杯飲んで。",
            ["DialogueId"] = 80210233,
            ["GUID"] = "C8CC435A",
            ["NextDialogue"] = 80210234,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC435A",
            },
        [80210234] = {
            ["Content"] = "罚就罚，没问题，我只是想问你，她呢？你最终找到她了吗？",
            ["ContentJP"] = "構わん。ちょっと聞きてぇことがあるだけだ……「彼女」は？見つけたのか？",
            ["DialogueId"] = 80210234,
            ["GUID"] = "C8CC4384",
            ["NextDialogue"] = 80210235,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4384",
            },
        [80210235] = {
            ["Camera"] = "-54.832031,-48.86377,169.512695,0.000115,-10.397644,109.791862,20.0,116.948799,false,Manual,4.0",
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80210235,
            ["FacialId"] = {
                [1] = "790068:CM_Idle",
                },
            ["GUID"] = "C8CC43AE",
            ["NextDialogue"] = 80210236,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC43AE",
            },
        [80210236] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "你说过，不找到她是不会回华胥的。",
            ["ContentJP"] = "お前、彼女を見つけるまで華胥には戻らないって言ったよな。",
            ["DialogueId"] = 80210236,
            ["FinalCamera"] = "-22.458984,-65.278564,190.244141,0.000084,-19.79907,13.007616,30.000008,115.331322,false,Manual,2.8",
            ["GUID"] = "C8CC43D8",
            ["NextDialogue"] = 80210237,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC43D8",
            },
        [80210237] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "我累了。",
            ["ContentJP"] = "……もう、疲れたよ。",
            ["DialogueId"] = 80210237,
            ["FacialId"] = {
                [1] = "790068:CM_Sad01",
                },
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC4402",
            ["NextDialogue"] = 80210238,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Disagree",
                },
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4402",
            },
        }
  end },
  { MinKey = 80210238, MaxKey = 80220205, Loader = function()
      return {
        [80210238] = {
            ["Content"] = "我无时无刻不在想着她。沙砾里，海浪里，森林里，圣塔旁，絮语河上，我都寻觅过她，但是却又寻她不见。",
            ["ContentJP"] = "僕はね、いつだって彼女のことを想ってる。砂漠でも、海でも、森の中でも、聖塔のそばでも、ススルス川のほとりでも——どこでだって探してきた。けど、結局見つからなかった。",
            ["DialogueId"] = 80210238,
            ["GUID"] = "C8CC442C",
            ["NextDialogue"] = 80210239,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC442C",
            },
        [80210239] = {
            ["Content"] = "于是我在想，她会不会是回到了华胥这个伤心地。但，依旧没有人见过她。",
            ["ContentJP"] = "ひょっとして華胥という悲しみの地に戻ったかなと、ふと思った。けれど、彼女を見た者は誰もいなかった。",
            ["DialogueId"] = 80210239,
            ["GUID"] = "C8CC4456",
            ["NextDialogue"] = 80210240,
            ["SpeakNpcId"] = 790068,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4456",
            },
        [80210240] = {
            ["Camera"] = "55.90625,-152.534912,193.577148,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
            ["Content"] = "可怜。",
            ["ContentJP"] = "かわいそうだな。",
            ["DialogueId"] = 80210240,
            ["FinalCamera"] = "57.841797,-147.262451,191.289062,0.000092,-22.199057,72.007072,30.000013,109.656555,false,Manual,2.8",
            ["GUID"] = "C8CC4480",
            ["NextDialogue"] = 80210241,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4480",
            },
        [80210241] = {
            ["Camera"] = "118.96875,-145.442871,164.535156,0.000056,-5.398397,129.398148,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "谁可怜。",
            ["ContentJP"] = "なんだって？",
            ["DialogueId"] = 80210241,
            ["FinalCamera"] = "107.117188,-131.01001,162.773438,0.000061,-5.398397,129.398041,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC44AA",
            ["NextDialogue"] = 80210242,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC44AA",
            },
        [80210242] = {
            ["Camera"] = "-2.816406,-67.810547,183.550781,0.000092,-19.198992,12.008528,30.000008,92.276848,false,Manual,2.8",
            ["Content"] = "天下有情人。",
            ["ContentJP"] = "恋する人々よ。",
            ["DialogueId"] = 80210242,
            ["GUID"] = "C8CC44D4",
            ["NextDialogue"] = 80210243,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC44D4",
            },
        [80210243] = {
            ["Camera"] = "371.589844,-637.212402,325.822266,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["Content"] = "哈哈。",
            ["ContentJP"] = "……ははっ。",
            ["DialogueId"] = 80210243,
            ["FacialId"] = {
                [1] = "790068:CM_Smile01",
                },
            ["FinalCamera"] = "305.197266,-520.310547,282.146484,0.000051,-17.998013,119.596794,33.0,1098.901978,false,Manual,3.0",
            ["GUID"] = "C8CC44FE",
            ["NextDialogue"] = 80210244,
            ["SpeakNpcId"] = 790068,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC44FE",
            },
        [80210244] = {
            ["Content"] = "要说可怜，你也同样，我远离华胥不受大风九章羁绊，而你的话，恐怕在来见我之前，刚刚和应天尉交过手吧。",
            ["ContentJP"] = "お前もそうだろう。華胥から遠く離れて「大風九章」から解放された僕と違って、ここに来る前に応天尉と戦ったよね。",
            ["DialogueId"] = 80210244,
            ["GUID"] = "C8CC4528",
            ["NextDialogue"] = 80210245,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4528",
            },
        [80210245] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "那是自然，但也早就习惯如此了，正如你习惯了漂泊异乡一样。",
            ["ContentJP"] = "もちろんだ。もう慣れたから……お前が各地を転々とするような暮らしを慣れたように。",
            ["DialogueId"] = 80210245,
            ["FinalCamera"] = "-214.660156,57.06543,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC4552",
            ["NextDialogue"] = 80210246,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4552",
            },
        [80210246] = {
            ["Camera"] = "150.619141,-184.330078,170.381836,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["Content"] = "刚刚你打断我的话，罚酒一杯，该喝了。等你喝完我就上路继续找她，这次我反其道行之，先从海路到伊瑟尔。",
            ["ContentJP"] = "ほら、僕の話を遮ったんだし、約束どおりの一杯、さっさと飲んで。それからまた人探しの旅に出る。今度は、逆に海沿ってイーザーへ。",
            ["DialogueId"] = 80210246,
            ["FinalCamera"] = "134.451172,-164.355713,167.136719,0.000057,-7.198452,128.998718,33.0,376.434326,false,Manual,3.0",
            ["GUID"] = "C8CC457C",
            ["NextDialogue"] = 80210247,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC457C",
            },
        [80210247] = {
            ["Camera"] = "-461.167969,-98.087646,206.131836,0.000101,-12.798893,15.005779,20.0,592.475586,false,Manual,4.0",
            ["Content"] = "我刚刚已经罚完了。",
            ["ContentJP"] = "もう飲んだぞ。",
            ["DialogueId"] = 80210247,
            ["FinalCamera"] = "-425.052734,-189.832764,206.131836,0.000102,-12.998901,25.60441,20.0,592.475586,false,Manual,4.0",
            ["GUID"] = "C8CC45A6",
            ["NextDialogue"] = 80210248,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC45A6",
            },
        [80210248] = {
            ["Content"] = "什么时候？我怎么没瞧见。",
            ["ContentJP"] = "えっ、いつの間に？見えなかったよ。",
            ["DialogueId"] = 80210248,
            ["GUID"] = "C8CC45D0",
            ["NextDialogue"] = 80210249,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC45D0",
            },
        [80210249] = {
            ["Content"] = "在你说到圣塔旁，絮语河上的时候。",
            ["ContentJP"] = "「聖塔のそば、ススルス川のほとり」のところ？",
            ["DialogueId"] = 80210249,
            ["GUID"] = "C8CC45FA",
            ["NextDialogue"] = 80210250,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC45FA",
            },
        [80210250] = {
            ["Content"] = "真的假的？唉，可能是我太想见她了。",
            ["ContentJP"] = "マジかよ。はあ、彼女を強く想っているからか。",
            ["DialogueId"] = 80210250,
            ["GUID"] = "C8CC4624",
            ["NextDialogue"] = 80210251,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4624",
            },
        [80210251] = {
            ["Camera"] = "-31.490234,-67.365234,193.577148,0.000082,-19.79907,13.007189,30.000008,125.0,false,Manual,2.8",
            ["Content"] = "骗你的，我还没喝。",
            ["ContentJP"] = "冗談だ。まだ飲んでねえよ。",
            ["DialogueId"] = 80210251,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["GUID"] = "C8CC464E",
            ["NextDialogue"] = 80210252,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC464E",
            },
        [80210252] = {
            ["Camera"] = "32.886719,-42.50415,154.229492,0.000131,-5.197801,142.396057,20.0,155.23967,false,Manual,4.0",
            ["Content"] = "你小子，从小就喜欢骗人，一直没变。",
            ["ContentJP"] = "お前、いつものように、嘘つきで悪戯好きだな。",
            ["DialogueId"] = 80210252,
            ["GUID"] = "C8CC4678",
            ["NextDialogue"] = 80210253,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790067:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4678",
            },
        [80210253] = {
            ["Camera"] = "-212.583984,65.048096,167.224609,0.000083,-6.598106,-14.604714,33.0,343.677704,false,Manual,3.0",
            ["Content"] = "而你就没有识破的时候。",
            ["ContentJP"] = "そしてお前はいつものように、騙されやすいだな。",
            ["DialogueId"] = 80210253,
            ["FinalCamera"] = "-246.677734,73.932129,171.296875,0.000083,-6.598113,-14.604773,33.0,343.677704,false,Manual,3.0",
            ["GUID"] = "C8CC46A2",
            ["NextDialogue"] = 80210254,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC46A2",
            },
        [80210254] = {
            ["Content"] = "哈哈哈哈。",
            ["ContentJP"] = "ハッハッハッハ。",
            ["DialogueId"] = 80210254,
            ["FacialId"] = {
                [1] = "790067:Smile02",
                },
            ["GUID"] = "C8CC46CC",
            ["NextDialogue"] = 80210255,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC46CC",
            },
        [80210255] = {
            ["Camera"] = "-17.587891,-73.812012,162.646484,0.000131,-7.797698,121.197479,20.0,155.23967,false,Manual,4.0",
            ["Content"] = "那么，我出发了，后会有期。",
            ["ContentJP"] = "では、さらばだ。またいつの日か会おう。",
            ["DialogueId"] = 80210255,
            ["FacialId"] = {
                [1] = "790068:CM_Idle",
                },
            ["GUID"] = "C8CC46F6",
            ["NextDialogue"] = 80210256,
            ["SpeakNpcId"] = 790068,
            ["TalkActionId"] = {
                [1] = "790068:Salute_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC46F6",
            },
        [80210256] = {
            ["Camera"] = "-786.357422,-477.311035,427.586914,0.000243,-19.797138,31.996326,20.0,1022.357056,false,Manual,4.0",
            ["Content"] = "后会有期。",
            ["ContentJP"] = "またな。",
            ["DialogueId"] = 80210256,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "-968.662109,-591.214844,504.962891,0.000238,-17.997028,31.397633,20.0,1022.357056,false,Manual,4.0",
            ["GUID"] = "C8CC4720",
            ["LookAt"] = {
                [1] = "790068:n(790068)",
                },
            ["NextDialogue"] = 80210257,
            ["Scripts"] = "MoveTo{_delay{3},ActorId{790068},TargetPoint{\"BP_NewTargetPoint_15032\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790068:Salute_End",
                [2] = "790067:Story_HoldFist_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC4720",
            },
        [80210257] = {
            ["Content"] = "这第二位也就此离去……那么接下来是第三位。",
            ["ContentJP"] = "これで二人目も去ったか．．．今度は三人目だな。",
            ["DialogueId"] = 80210257,
            ["GUID"] = "C8CC474A",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Story_HoldFist_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/002/C8CC474A",
            },
        [80210301] = {
            ["Camera"] = "-1168.496094,1264.441406,313.365234,0.000131,-4.398683,-49.787758,30.000002,1615.87854,false,Manual,2.8",
            ["Content"] = "侠客大多是吃主，玩主。想来也是正常的，好马，好剑，好衣裳，总是大侠的标配。",
            ["ContentJP"] = "侠とは、食と嗜をぴったりさせる者。彼らにはいつもお似合いの名馬、宝剣、衣装が揃っている。",
            ["DialogueId"] = 80210301,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
            ["GUID"] = "C8CC4E82",
            ["LookAt"] = {
                [1] = "790071:n(790069)",
                [2] = "790069:n(790071)",
                },
            ["NextDialogue"] = 80210302,
            ["Scripts"] = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4E82",
            },
        [80210302] = {
            ["Content"] = "至于酒食，更是极为精细。以至于提起侠客，总是感觉他们好酒，大块吃肉。而如果一个侠客明言不喝酒，就多少觉得他的剑意少了三分老辣。",
            ["ContentJP"] = "酒と肴となると、じつに繊細をきわめている。 侠と聞けば、つい大酒をくらい、塊肉にかぶりつく姿が浮かぶ。 まして「酒はやらぬ」と言い切る侠客なら、その剣の冴えにも、薄い気がしてしまう。",
            ["DialogueId"] = 80210302,
            ["GUID"] = "C8CC4EAC",
            ["NextDialogue"] = 80210303,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4EAC",
            },
        [80210303] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "小二，一斤黄酒，七个油豆腐，辣酱要多！",
            ["ContentJP"] = "おい、黄酒を一本。油揚げを七枚。唐辛子味噌は多めで。",
            ["DialogueId"] = 80210303,
            ["FinalCamera"] = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC4ED6",
            ["NextDialogue"] = 80210304,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4ED6",
            },
        [80210304] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "好嘞，我这就吩咐给您做。",
            ["ContentJP"] = "かしこまりました、では少々お待ちください。",
            ["DialogueId"] = 80210304,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC4F00",
            ["NextDialogue"] = 80210305,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F00",
            },
        [80210305] = {
            ["Content"] = "一斤黄酒，七个油豆腐，辣酱要多！",
            ["ContentJP"] = "黄酒一本、油揚げ七枚、唐辛子味噌多めで。",
            ["DialogueId"] = 80210305,
            ["GUID"] = "C8CC4F2A",
            ["NextDialogue"] = 80210306,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F2A",
            },
        [80210306] = {
            ["Camera"] = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
            ["Content"] = "谢了。顺便问下，你可听说过一位飘零人，名唤铁掌移山刘纬甫，年纪应该有六七十了。",
            ["ContentJP"] = "ありがとよ。ところで、「鉄掌山移のリュウ」という名の流れ者、聞いたことあるか？ 歳は六十か七十くらいだ……。",
            ["DialogueId"] = 80210306,
            ["FinalCamera"] = "-444.984375,-72.832031,49.90918,0.00003,6.600196,30.607128,20.0,400.820953,false,Manual,2.8",
            ["GUID"] = "C8CC4F54",
            ["NextDialogue"] = 80210307,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F54",
            },
        [80210307] = {
            ["Content"] = "没听说过。我这辈子都没见过飘零人呢。",
            ["ContentJP"] = "聞いたことがありません。そもそも、流れ者さえ見たことはありませんな。",
            ["DialogueId"] = 80210307,
            ["GUID"] = "C8CC4F7E",
            ["NextDialogue"] = 80210308,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4F7E",
            },
        [80210308] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "那你现在见过了。",
            ["ContentJP"] = "じゃあ今は見たよ。",
            ["DialogueId"] = 80210308,
            ["FinalCamera"] = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC4FA8",
            ["NextDialogue"] = 80210309,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 15,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FA8",
            },
        [80210309] = {
            ["Content"] = "您是飘零人？",
            ["ContentJP"] = "お客様はもしや、流れ者では？",
            ["DialogueId"] = 80210309,
            ["GUID"] = "C8CC4FD2",
            ["NextDialogue"] = 80210310,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FD2",
            },
        [80210310] = {
            ["Content"] = "我是啊，怎么，看着不像？",
            ["ContentJP"] = "いかにも。なんだ、流れ者に見えねぇか？",
            ["DialogueId"] = 80210310,
            ["GUID"] = "C8CC4FFC",
            ["NextDialogue"] = 80210311,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC4FFC",
            },
        [80210311] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "是不像，我听说飘零人啊都是喜欢大口喝酒大口吃肉的，没见过点油豆腐的。",
            ["ContentJP"] = "失礼ながら、そうは見えませんね。流れ者は皆がぶがぶお酒を飲み、がつがつお肉を食うと聞きましたけど、油揚げを注文する流れ者とは……",
            ["DialogueId"] = 80210311,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5026",
            ["NextDialogue"] = 80210312,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5026",
            },
        [80210312] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "这叫什么话，飘零人又不是野狼野狗就爱吃肉，那吃得精细起来也是自有一套讲究的。",
            ["ContentJP"] = "何言ってんだ。流れ者ってのはな、どこぞの野良犬みたいに肉だけ喰ってりゃいいわけじゃねぇ、食事にはそれなりのこだわりがあんだよ。",
            ["DialogueId"] = 80210312,
            ["FinalCamera"] = "-220.636719,18.855469,140.509766,0.000013,-19.999994,47.002541,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5050",
            ["NextDialogue"] = 80210313,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5050",
            },
        [80210313] = {
            ["Camera"] = "-545.542969,-132.332031,36.390137,0.000018,6.600196,30.606834,20.0,466.554138,false,Manual,2.8",
            ["Content"] = "那野狼野狗也不止吃肉，还吃其他东西呢……",
            ["ContentJP"] = "ですが、野良犬だって肉だけではなくて、ほかのものも食べるんではありませんか？",
            ["DialogueId"] = 80210313,
            ["FinalCamera"] = "-462.796875,-83.355469,47.517578,0.0,6.600196,30.608337,20.0,466.554138,false,Manual,2.8",
            ["GUID"] = "C8CC507A",
            ["NextDialogue"] = 80210314,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC507A",
            },
        [80210314] = {
            ["Content"] = "打住，打住，我油豆腐好没？帮我催一催。",
            ["ContentJP"] = "もういい、俺の油揚げはまだか？早く持って来い！",
            ["DialogueId"] = 80210314,
            ["GUID"] = "C8CC50A4",
            ["NextDialogue"] = 80210315,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50A4",
            },
        [80210315] = {
            ["Content"] = "得嘞，卯金叔，油豆腐快点。",
            ["ContentJP"] = "かしこまりました！リユウさん、早く油揚げをもってきてください。",
            ["DialogueId"] = 80210315,
            ["GUID"] = "C8CC50CE",
            ["NextDialogue"] = 80210316,
            ["SpeakNpcId"] = 790069,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50CE",
            },
        [80210316] = {
            ["Content"] = "莫催莫催，就好了。",
            ["ContentJP"] = "すぐできるけん、急がんでよかばい。",
            ["DialogueId"] = 80210316,
            ["GUID"] = "C8CC50F8",
            ["NextDialogue"] = 80210317,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC50F8",
            },
        [80210317] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "行。客官您再等等。不过，刚刚您说飘零人吃起来自有一套，要不多讲讲呗，反正现在店里也没人，想听。",
            ["ContentJP"] = "はいよ。お客様、どうか、もう少しお待ちください。「食事には流れ者なりのこだわりがある」とおっしゃいましたが、詳しくは教えてくれませんか？ちょうど今、ほかの客人様もいませんので。",
            ["DialogueId"] = 80210317,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC5122",
            ["NextDialogue"] = 80210318,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5122",
            },
        [80210318] = {
            ["Camera"] = "-235.25,3.191406,148.305176,0.000013,-19.999994,47.002541,20.0,187.784851,false,Manual,2.8",
            ["Content"] = "也罢，我今天来找的这位飘零人前辈，当年也以做得一手好菜闻名，被称作庖侠。",
            ["ContentJP"] = "まぁいい、教えてやる。今探してる男は、料理の腕でも鳴らしてて、「庖侠」とも呼ばれてた",
            ["DialogueId"] = 80210318,
            ["FinalCamera"] = "-208.675781,31.691406,134.121582,0.000012,-19.999954,47.00246,20.0,150.472961,false,Manual,2.8",
            ["GUID"] = "C8CC514C",
            ["NextDialogue"] = 80210319,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC514C",
            },
        [80210319] = {
            ["Content"] = "他老人家最知名的一手是“若木无觅衔烛龙”，号称是能把维系大风九章的那白龙斩了做宴席。",
            ["ContentJP"] = "彼の得意料理は「燭龍焼き」――大風九章を司るあの白龍様を斬って宴に供す、とうたう一品だ。",
            ["DialogueId"] = 80210319,
            ["GUID"] = "C8CC5176",
            ["NextDialogue"] = 80210320,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5176",
            },
        [80210320] = {
            ["Content"] = "实际上呢，是用各种飞禽走兽的肉分别以掌力击碎，再绞制成型。这样一来，一口下去可以尝出百般滋味，所以敢自称是龙肉。",
            ["ContentJP"] = "とはいえ実際は、鳥だの獣だのさまざまな肉を掌で叩き潰して細かくし、練り合わせて形を作るんだ。ひと口でいろんな味が楽しめるような肉料理で、「龍肉」と名乗れるわけだ。",
            ["DialogueId"] = 80210320,
            ["GUID"] = "C8CC51A0",
            ["NextDialogue"] = 80210321,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51A0",
            },
        [80210321] = {
            ["Content"] = "然后再又以极其滑嫩的豆腐作为基底，与诸多畜类的脊髓骨髓一同炒制，让它们的香味渗入豆腐中，号称龙髓。",
            ["ContentJP"] = "さらに、絹みたいに滑らかな豆腐を土台にして、いろんな獣の骨髄と一緒に炒める。骨髄の香りと旨みが豆腐に染みるまでな。そうやって仕上げた豆腐を、「龍髄」って呼ぶ。",
            ["DialogueId"] = 80210321,
            ["GUID"] = "C8CC51CA",
            ["NextDialogue"] = 80210322,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51CA",
            },
        [80210322] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "客官您说笑了，豆腐就是豆腐，怎么能号称是龙髓呢。要这么说，我们店卖的油豆腐，也能叫炸龙髓了。",
            ["ContentJP"] = "お客さま、ご冗談を。豆腐はあくまで豆腐で、「龍髄」なんて名乗れませんよ。そんな理屈なら、うちの油揚げも「龍髄揚げ」になってしまうのでは？",
            ["DialogueId"] = 80210322,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC51F4",
            ["NextDialogue"] = 80210323,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC51F4",
            },
        [80210323] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "哎，我也是听师父说过而已。那位铁掌移山刘纬甫早早金盆洗手，如今没人知道他身在何方。",
            ["ContentJP"] = "やれやれ、俺も師匠から聞いたんだ。「鉄掌山移のリュウ」はとうに隠退して、どこにいるかは誰にも分からねぇ。",
            ["DialogueId"] = 80210323,
            ["FinalCamera"] = "-185.449219,100.574219,121.142578,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC521E",
            ["NextDialogue"] = 80210324,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC521E",
            },
        [80210324] = {
            ["Camera"] = "-1040.925781,1113.558594,298.16748,0.000131,-4.398683,-49.787758,30.000002,1361.954834,false,Manual,2.8",
            ["Content"] = "说半天说得我都流口水了，原来您没吃过啊。行了那别说这些虚无缥缈的了，来尝尝这个吧，我们店招牌的油豆腐。",
            ["ContentJP"] = "もう、聞いてるだけでよだれが…でも実物はまだ未体験なんですね。なら、その絵空事はこのへんにして、まずはうちの看板・油揚げをどうぞ。",
            ["DialogueId"] = 80210324,
            ["FinalCamera"] = "-847.84375,934.597656,274.614746,0.000131,-6.0,-49.78775,30.000002,1361.954834,false,Manual,2.8",
            ["GUID"] = "C8CC5248",
            ["NextDialogue"] = 80210325,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5248",
            },
        [80210325] = {
            ["Content"] = "……我来尝尝。",
            ["ContentJP"] = "おお、どれどれ……",
            ["DialogueId"] = 80210325,
            ["GUID"] = "C8CC5272",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5272",
            },
        [80210326] = {
            ["Content"] = "啊……烫，但……好好吃。",
            ["ContentJP"] = "熱…熱い！熱いけど…うまっ。",
            ["DialogueId"] = 80210326,
            ["GUID"] = "C8CC529C",
            ["IsBlack"] = 1,
            ["LookAt"] = {
                [1] = "790071:n(790069)",
                [2] = "790069:n(790071)",
                },
            ["NextDialogue"] = 80210327,
            ["Scripts"] = "PlayAnimation{ActorId{790071},AnimationId{\"Sit_Idle_Loop\"},Sync{true}}",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC529C",
            },
        [80210327] = {
            ["Content"] = "嘶哈——",
            ["ContentJP"] = "フーフー……",
            ["DialogueId"] = 80210327,
            ["GUID"] = "C8CC52C6",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 80210328,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC52C6",
            },
        [80210328] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "表皮被炸得酥脆，咬下去嘎吱作响，而里面的豆腐却软嫩绵滑，却又不至于立刻散掉，得要相当的力道和巧劲才能做到这个地步。",
            ["ContentJP"] = "この油揚げ、衣はカリッと揚がってるのに、中の豆腐は驚くほどやわらかくて絹のようになめらかだとは……しかも形が崩れてねぇ。ここまで仕上げるには、火加減と手さばき―相当な腕だな。",
            ["DialogueId"] = 80210328,
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC52F0",
            ["NextDialogue"] = 80210329,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC52F0",
            },
        [80210329] = {
            ["Camera"] = "-159.164062,204.953125,88.058105,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["Content"] = "算你识货，我们卯金叔做得油豆腐可是远近闻名，想来啊，不比那什么“若木无觅衔烛龙”差。",
            ["ContentJP"] = "お目が高いですね。うちのリユウさんが作った油揚げ料理はあちこちで有名なんですよ。きっと、その「燭龍焼き」とやらにも劣らないでしょうね。",
            ["DialogueId"] = 80210329,
            ["FinalCamera"] = "-156.535156,189.371094,90.843262,0.000052,9.999997,-80.395218,20.0,169.81192,false,Manual,2.8",
            ["GUID"] = "C8CC531A",
            ["NextDialogue"] = 80210330,
            ["SpeakNpcId"] = 790069,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC531A",
            },
        [80210330] = {
            ["Content"] = "等等……莫非……",
            ["ContentJP"] = "ちょっ……まさか、な。",
            ["DialogueId"] = 80210330,
            ["FacialId"] = {
                [1] = "790071:Shock01",
                },
            ["GUID"] = "C8CC5344",
            ["NextDialogue"] = 80210331,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5344",
            },
        [80210331] = {
            ["Camera"] = "-291.878906,37.308594,153.111328,0.000122,-8.597596,-25.187979,30.000013,264.169495,false,Manual,2.8",
            ["Content"] = "就你个瓜娃儿话多，莫要和客人摆龙门阵了，又有油豆腐弄好了，上菜。",
            ["ContentJP"] = "こら小僧、客さんとしゃべり過ぎやろが。もう油揚げぁできあがっとるばい。はよ客んとこに持っていかんか。",
            ["DialogueId"] = 80210331,
            ["FinalCamera"] = "-241.59375,9.6875,154.276855,0.000128,-8.597521,-24.999588,30.000013,185.753601,false,Manual,2.8",
            ["GUID"] = "C8CC536E",
            ["NextDialogue"] = 80210332,
            ["Scripts"] = "MoveTo{ActorId{790070},TargetPoint{\"BP_NewTargetPoint_150303_1\"},MoveSpeed{150}}",
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC536E",
            },
        [80210332] = {
            ["Content"] = "得嘞。",
            ["ContentJP"] = "はいよ。",
            ["DialogueId"] = 80210332,
            ["Duration"] = 5,
            ["GUID"] = "C8CC5398",
            ["LookAt"] = {
                [1] = "790069:n(790069)",
                },
            ["NextDialogue"] = 80210333,
            ["Scripts"] = "MoveTo{ActorId{790069},TargetPoint{\"BP_NewTargetPoint_150303_2\"},MoveSpeed{150},Visibility{\"Hide\"}}",
            ["SpeakNpcId"] = 790069,
            ["TurnTo"] = {
                [1] = "790070:n(790071)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5398",
            },
        [80210333] = {
            ["Camera"] = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
            ["Content"] = "尝出来了？",
            ["ContentJP"] = "わかっとうとや？",
            ["DialogueId"] = 80210333,
            ["FinalCamera"] = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
            ["GUID"] = "C8CC53C2",
            ["LookAt"] = {
                [1] = "790071:n(790070)",
                },
            ["NextDialogue"] = 80210334,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["TurnTo"] = {
                [1] = "790070:n(790071)",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC53C2",
            },
        [80210334] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "尝出来了，前辈的手艺果然名不虚传，难怪我师父这么多年一直念念不忘。",
            ["ContentJP"] = "わかったぞ。流石はリュウ様だ、噂通りの腕前。我が師匠が長年に渡っても食べたがってる気持ちもわかるぜ！",
            ["DialogueId"] = 80210334,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC53EC",
            ["NextDialogue"] = 80210335,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC53EC",
            },
        [80210335] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "净讲这些虚的干啥子嘞，你吃东西是为自己吃的还是为你师父吃的？讲你自己的想法。",
            ["ContentJP"] = "ばかたれ！誰が食いよるとや？ おまえん師匠か？ それともおまえや？ わかっとうなら、自分の気持ちば言わんか！",
            ["DialogueId"] = 80210335,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC5416",
            ["NextDialogue"] = 80210336,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5416",
            },
        [80210336] = {
            ["Camera"] = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
            ["Content"] = "好吃！",
            ["ContentJP"] = "うまい！",
            ["DialogueId"] = 80210336,
            ["FinalCamera"] = "-314.59375,-444.601562,82.464844,0.000134,1.999995,62.002323,20.0,592.152588,false,Manual,2.8",
            ["GUID"] = "C8CC5440",
            ["NextDialogue"] = 80210337,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5440",
            },
        [80210337] = {
            ["Content"] = "对头，那好吃的话应该怎么做啊？",
            ["ContentJP"] = "よし！ うまかとや？",
            ["DialogueId"] = 80210337,
            ["GUID"] = "C8CC546A",
            ["NextDialogue"] = 80210338,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC546A",
            },
        [80210338] = {
            ["Content"] = "再来七块！",
            ["ContentJP"] = "おかわり！",
            ["DialogueId"] = 80210338,
            ["GUID"] = "C8CC5494",
            ["NextDialogue"] = 80210339,
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5494",
            },
        [80210339] = {
            ["Content"] = "嘞就对嘛。",
            ["ContentJP"] = "そうたい、そうたい！",
            ["DialogueId"] = 80210339,
            ["GUID"] = "C8CC54BE",
            ["NextDialogue"] = 80210340,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC54BE",
            },
        [80210340] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "好，吃的问题解决了，现在你告诉我，你师父是哪一个？",
            ["ContentJP"] = "よし。食いもんの話は片ぁ付いたばい。次ん問題や――おまえが言いよった師匠っち、誰やと？",
            ["DialogueId"] = 80210340,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC54E8",
            ["NextDialogue"] = 80210341,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC54E8",
            },
        [80210341] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "宴山亭。",
            ["ContentJP"] = "宴山亭。",
            ["DialogueId"] = 80210341,
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC5512",
            ["NextDialogue"] = 80210342,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5512",
            },
        [80210342] = {
            ["Camera"] = "-187.410156,43.980469,119.370605,0.00013,1.999995,-44.796921,20.0,171.840973,false,Manual,2.8",
            ["Content"] = "喔，原来是他，是为了论剑而来的吧？没想到他还记得这个事。",
            ["ContentJP"] = "おう…あいつだったのか。試合のために来たんだろうな。まだワシのこと覚えてるのか。",
            ["DialogueId"] = 80210342,
            ["FinalCamera"] = "-198.394531,31.234375,119.370605,0.00013,1.999995,-39.196651,20.0,171.840973,false,Manual,2.8",
            ["GUID"] = "C8CC553C",
            ["NextDialogue"] = 80210343,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC553C",
            },
        [80210343] = {
            ["Camera"] = "-104.40625,-155.425781,163.111328,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
            ["Content"] = "师父念念不忘，敢问刘前辈会参加吗？",
            ["ContentJP"] = "最後までも忘れてなかったよ。リュウ様、剣道の試合に参加してくれるか？",
            ["DialogueId"] = 80210343,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-102.179688,-128.832031,153.394531,0.000038,-19.999928,85.208679,20.0,314.309692,false,Manual,2.8",
            ["GUID"] = "C8CC5566",
            ["NextDialogue"] = 80210344,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5566",
            },
        [80210344] = {
            ["Camera"] = "-201.753906,194.632812,93.111328,0.000129,1.999995,-50.996628,20.0,305.107788,false,Manual,2.8",
            ["Content"] = "这里没有刘前辈，我早已放下刀，这里只有卯金叔。",
            ["ContentJP"] = "おまえが言ったリュウ様は、もういないよ。剣の道はもうやめた。ここにいるのは、料理人のリユウだけだ。",
            ["DialogueId"] = 80210344,
            ["FinalCamera"] = "-191.488281,181.953125,93.680664,0.000129,1.999995,-50.996746,20.0,305.107788,false,Manual,2.8",
            ["GUID"] = "C8CC5590",
            ["NextDialogue"] = 80210345,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5590",
            },
        [80210345] = {
            ["Content"] = "好了，莫要再问了，再要七个油豆腐是吧，我这就继续。",
            ["ContentJP"] = "もう、これ以上聞くな。おかわりだね、また作ってやるよ。",
            ["DialogueId"] = 80210345,
            ["GUID"] = "C8CC55BA",
            ["NextDialogue"] = 80210346,
            ["SpeakNpcId"] = 790070,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC55BA",
            },
        [80210346] = {
            ["Camera"] = "-194.460938,93.691406,125.272461,0.000011,-19.99996,37.409882,20.0,81.55352,false,Manual,2.8",
            ["Content"] = "……再来七个，打包带走，我也让我朋友尝一尝。",
            ["ContentJP"] = "……もう七枚くれ。友達の分だ。お持ち帰りしたい。",
            ["DialogueId"] = 80210346,
            ["FacialId"] = {
                [1] = "790071:Smile01",
                },
            ["FinalCamera"] = "-189.175781,97.710938,122.863281,0.00001,-19.999954,37.409824,20.0,81.55352,false,Manual,2.8",
            ["GUID"] = "C8CC55E4",
            ["NextDialogue"] = 80210347,
            ["SpeakNpcId"] = 790071,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC55E4",
            },
        [80210347] = {
            ["Camera"] = "-400.648438,-387.972656,82.464844,0.000133,1.999995,51.002842,20.0,592.152588,false,Manual,2.8",
            ["Content"] = "要得，但切记，只许和朋友说这是卯金叔做的，要是多说一句，我把你舌头割下来做成卤菜。",
            ["ContentJP"] = "わかったばい。だが覚えておけ、これはリユウが作った料理ばい。もしおまえの友達に余計な話をしたら、あんたの舌を切り取って鍋にするばい。",
            ["DialogueId"] = 80210347,
            ["FinalCamera"] = "-544.378906,-565.476562,74.48877,0.000132,1.999995,51.004082,20.0,592.152588,false,Manual,2.8",
            ["GUID"] = "C8CC560E",
            ["NextDialogue"] = 80210348,
            ["SpeakNpcId"] = 790070,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC560E",
            },
        [80210348] = {
            ["Content"] = "那是自然，那么后生拜别前辈。",
            ["ContentJP"] = "ああ、分かっているさ。では、これにて失礼致します、先生。",
            ["DialogueId"] = 80210348,
            ["GUID"] = "C8CC5638",
            ["SpeakNpcId"] = 790071,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/003/C8CC5638",
            },
        [80210401] = {
            ["Camera"] = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["Content"] = "一大早的，还没睡醒呢就把人吵起来，是要去哪儿？",
            ["ContentJP"] = "朝っぱらから{性别:なんだ|なによ}、もう少し{性别:休ませてくれよ|休ませてよ}……どうしたの{性别:か|}？",
            ["DialogueId"] = 80210401,
            ["FacialId"] = {
                [1] = "790008:Doubt01",
                },
            ["FinalCamera"] = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["GUID"] = "C8CC5EEA",
            ["LookAt"] = {
                [1] = "790008:n(790067)",
                [2] = "790067:n(790008)",
                },
            ["NextDialogue"] = 80210402,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5EEA",
            },
        [80210402] = {
            ["Camera"] = "15.414062,815.271973,212.397461,0.000014,-4.60016,-71.792816,40.310993,430.446808,false,Manual,2.8",
            ["Content"] = "比武论剑，二十年一次。",
            ["ContentJP"] = "二十年に一度の剣道試合だ。",
            ["DialogueId"] = 80210402,
            ["FacialId"] = {
                [1] = "790067:Confident01",
                },
            ["FinalCamera"] = "28.40625,774.96582,208.994141,0.000013,-4.60016,-72.792603,40.310993,430.446808,false,Manual,2.8",
            ["GUID"] = "C8CC5F14",
            ["NextDialogue"] = 80210403,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F14",
            },
        [80210403] = {
            ["Camera"] = "-748.292969,-30.820801,161.345703,0.000053,0.0,31.808994,40.310993,975.20166,false,Manual,2.8",
            ["Content"] = "说这个我就不困了，谁和谁啊？",
            ["ContentJP"] = "眠気は吹っ飛んだ。詳しく教えて、誰と誰が戦う{性别:|の}？",
            ["DialogueId"] = 80210403,
            ["FinalCamera"] = "-626.019531,45.025391,161.345703,0.000053,0.0,31.809633,40.310993,872.170044,false,Manual,2.8",
            ["GUID"] = "C8CC5F3E",
            ["NextDialogue"] = 80210404,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Confident_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F3E",
            },
        [80210404] = {
            ["Content"] = "华胥有头有脸的飘零人理应都会来，之前已经举行过七八次了，大家会在山巅互相比试，直到分出胜负。",
            ["ContentJP"] = "華胥で有名な流れ者たちが揃って来るはずだ。これまでに七つか八つは開かれてる。みんな山頂で手合わせして、決着がつくまでやり合うんだ。",
            ["DialogueId"] = 80210404,
            ["GUID"] = "C8CC5F68",
            ["NextDialogue"] = 80210405,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F68",
            },
        [80210405] = {
            ["Camera"] = "-15.96875,236.780762,198.734375,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["Content"] = "那么这次，会有多少人参加？",
            ["ContentJP"] = "じゃ今回の参加者数は何人？",
            ["DialogueId"] = 80210405,
            ["FinalCamera"] = "0.390625,269.174805,197.469727,0.00004,-1.999995,63.206463,40.310993,407.767792,false,Manual,2.8",
            ["GUID"] = "C8CC5F92",
            ["NextDialogue"] = 80210406,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5F92",
            },
        [80210406] = {
            ["Camera"] = "-26.566406,613.213379,186.345703,0.000053,0.0,-59.788727,40.310993,251.490341,false,Manual,2.8",
            ["Content"] = "等到了你就知道了。",
            ["ContentJP"] = "それは、着いたら分かる。",
            ["DialogueId"] = 80210406,
            ["FinalCamera"] = "-14.558594,592.585449,193.345703,0.000053,0.0,-59.788727,40.310993,213.980072,false,Manual,2.8",
            ["GUID"] = "C8CC5FBC",
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_End",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5FBC",
            },
        [80210407] = {
            ["Camera"] = "976.125,1795.242676,518.382812,0.000097,-9.999997,-118.000748,26.65424,2016.868164,false,Manual,2.8",
            ["Content"] = "跟着刻舟到了一处相当荒僻的山间，想来这就是他们此前比武论剑之地了。",
            ["ContentJP"] = "カシュウの後について、人の気配のない山奥へ分け入った。どうやら、ここが連中がこれまで刃を交えてきた場所らしい。",
            ["DialogueId"] = 80210407,
            ["FinalCamera"] = "882.355469,1518.284668,467.509766,0.000097,-9.999964,-118.000748,26.65424,1751.967041,false,Manual,2.8",
            ["GUID"] = "C8CC5FE6",
            ["NextDialogue"] = 80210408,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC5FE6",
            },
        [80210408] = {
            ["Content"] = "但见满目新绿，飞泉直下。是适合比试的场地，只是，似乎有些过于冷清……",
            ["ContentJP"] = "あたり一面は新緑に染まり、岩間を抜けた清水がまっすぐ落ちていく。試合の場としては申し分ない……ただ、いささか静かすぎる。",
            ["DialogueId"] = 80210408,
            ["GUID"] = "C8CC6010",
            ["NextDialogue"] = 80210409,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6010",
            },
        [80210409] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "怎么只有我们俩，不是说有头有脸的飘零人都会来吗？",
            ["ContentJP"] = "えっ？なんで私たちしかいないの{性别:か|}？「有名な流れ者たちが揃って来る」って言った{性别:だろう|でしょう}？",
            ["DialogueId"] = 80210409,
            ["FacialId"] = {
                [1] = "790008:Doubt01",
                },
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC603A",
            ["LookAt"] = {
                [1] = "790067:n(790008)",
                },
            ["NextDialogue"] = 80210410,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC603A",
            },
        [80210410] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "说来惭愧，现在有头有脸的飘零人也不剩几位了，正所谓江湖儿女日渐少。",
            ["ContentJP"] = "まったく情けねぇ話だが……今じゃ“有名な流れ者”なんてほとんどいねぇ。まさに「盛者必衰」ってやつだ。",
            ["DialogueId"] = 80210410,
            ["FacialId"] = {
                [1] = "790067:Sad01",
                },
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC6064",
            ["NextDialogue"] = 80210411,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790008:Sigh_End",
                [2] = "790067:Talk01_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6064",
            },
        [80210411] = {
            ["Content"] = "且不说这次，就是上一次参加比武论剑的飘零人，仅有四位而已。",
            ["ContentJP"] = "今回はともかく、前回の試合も出場はたった四人だった。",
            ["DialogueId"] = 80210411,
            ["FacialId"] = {
                [1] = "790008:None",
                },
            ["GUID"] = "C8CC608E",
            ["LookAt"] = {
                [1] = "790008:n(790067)",
                },
            ["NextDialogue"] = 80210412,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC608E",
            },
        [80210412] = {
            ["Content"] = "第一位呢，便是我的师父宴山亭。虽然他已经离世，但是在离世前对这比武论剑念念不忘，让我代他出战。",
            ["ContentJP"] = "その一人は俺の師匠、宴山亭だった。今はもう亡くなったが、最後まで勝負を気にかけてたから、俺が代わりに出た。",
            ["DialogueId"] = 80210412,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["GUID"] = "C8CC60B8",
            ["NextDialogue"] = 80210413,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC60B8",
            },
        [80210413] = {
            ["Content"] = "于是我就走访了各处，找到了另外三位当年参加了比武论剑的高手。",
            ["ContentJP"] = "それで俺は方々を回って、かつてその試合に出た残り三人を探し出した。",
            ["DialogueId"] = 80210413,
            ["GUID"] = "C8CC60E2",
            ["NextDialogue"] = 80210414,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC60E2",
            },
        [80210414] = {
            ["Content"] = "我先找了其中一位善于用剑的女侠，也是上次论剑时夺得魁首的天下第一。但却连面也没见到。",
            ["ContentJP"] = "まず訪ねたのは、剣の冴えで鳴らした女侠だ。前の試合の優勝者だが、結局、顔を合わせることすらできなかった。",
            ["DialogueId"] = 80210414,
            ["GUID"] = "C8CC610C",
            ["NextDialogue"] = 80210415,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC610C",
            },
        [80210415] = {
            ["Content"] = "我师父一直说她爱剑成痴，大部分时候甚至不愿意拔剑，只以剑鞘伤人，又早早归隐，远离江湖，所以并没有被大风九章盯上。",
            ["ContentJP"] = "師匠の話じゃ、彼女は剣を愛するあまり、ふだんは抜きもせず鞘打ちだけで人を制した。",
            ["DialogueId"] = 80210415,
            ["GUID"] = "C8CC6136",
            ["NextDialogue"] = 80210416,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6136",
            },
        [80210416] = {
            ["Content"] = "现如今，却把自己的佩剑拿去当孩子的玩物，想必是不愿踏足江湖，只想躲进小楼，远离纷扰，那么我也没有多打扰她。",
            ["ContentJP"] = "愛刀を子どものおもちゃにする今の彼女は、もう剣士の世界へは戻る気はねぇんだろう。なら、こっちが踏み込む筋合いもねぇ。",
            ["DialogueId"] = 80210416,
            ["GUID"] = "C8CC6160",
            ["NextDialogue"] = 80210417,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6160",
            },
        [80210417] = {
            ["Content"] = "师父一直说她有大智慧，我此前都不明白，这次见了……不，这次没见到她，但是也已经明白师父为什么会这么说了。",
            ["ContentJP"] = "師匠は「あの女侠は大きな智恵を持つ」とよく言ってたけど、この言葉の意味をずっと理解できなかったんだ。実際に彼女と会った——いや、まだ会ってはいないけど、それでも今はその意味が分かる気がする。",
            ["DialogueId"] = 80210417,
            ["GUID"] = "C8CC618A",
            ["NextDialogue"] = 80210418,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC618A",
            },
        [80210418] = {
            ["Camera"] = "478.570312,-143.509766,121.444336,0.000169,2.99999,132.400314,42.362053,217.393646,false,Manual,2.8",
            ["Content"] = "嗯，换做是我的话，我应该也会这么做。",
            ["ContentJP"] = "もし{性别:僕|私}が彼女の立場でも、きっと同じ選択をする{性别:だろう|かも}。",
            ["DialogueId"] = 80210418,
            ["FinalCamera"] = "472.527344,-136.883301,121.911133,0.00017,2.99999,132.400513,42.362053,217.393646,false,Manual,2.8",
            ["GUID"] = "C8CC61B4",
            ["NextDialogue"] = 80210419,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC61B4",
            },
        [80210419] = {
            ["Camera"] = "925.164062,204.170898,224.050781,0.000123,-9.999943,-150.992493,26.65424,679.187683,false,Manual,2.8",
            ["Content"] = "再一位呢，唤作鸣鸾，比我年长一点，自幼就被认定是习武的天才，年少成名，以弱冠之龄便能参加比武论剑。",
            ["ContentJP"] = "次に会ったのは、メイランという名の剣士だ。俺より少し年上で、子どものころから武の才を見込まれ、華胥で名を上げた。そして、弱冠にして試合の場に立った。",
            ["DialogueId"] = 80210419,
            ["FinalCamera"] = "742.019531,445.837402,225.842773,0.000124,-9.999943,-129.189941,26.65424,679.187683,false,Manual,2.8",
            ["GUID"] = "C8CC61DE",
            ["NextDialogue"] = 80210420,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02R_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC61DE",
            },
        [80210420] = {
            ["Content"] = "他本有一位红颜知己，剑法同样精微，一直与他快意恩仇，人人都觉得他们是一对璧人，天作之合。",
            ["ContentJP"] = "彼には愛しい女がいて、その剣筋もまた精妙。二人で好き勝手に旅をし、義理も仇も自分たちなりに片をつけてきた。まぁ、誰もが「お似合いの二人」だと羨む仲だった。",
            ["DialogueId"] = 80210420,
            ["GUID"] = "C8CC6208",
            ["NextDialogue"] = 80210421,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6208",
            },
        [80210421] = {
            ["Content"] = "但是再多的快意恩仇也会让人厌倦，那位红颜知己厌倦了终日飘零，不得不躲避应天尉追杀的生活。",
            ["ContentJP"] = "だが、どんな旅でも、いつかは疲れが来る。応天尉をかわし続ける流転の暮らしに、その女も倦んだのだろう。",
            ["DialogueId"] = 80210421,
            ["GUID"] = "C8CC6232",
            ["NextDialogue"] = 80210422,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6232",
            },
        [80210422] = {
            ["Content"] = "于是他们相约，在某日一起离开华胥，去大陆的其他地方，过安稳日子。",
            ["ContentJP"] = "そこで、二人はいつの日か華胥の地から離れて、大陸の他の場所で静かに暮らそうと約した。",
            ["DialogueId"] = 80210422,
            ["GUID"] = "C8CC625C",
            ["NextDialogue"] = 80210423,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC625C",
            },
        [80210423] = {
            ["Content"] = "只是他们许约的那一日，偏偏又是论剑的日子。而鸣鸾被年少盛名所累，想要等到比武结束后，夺了第一的名号后与那位知己再一同离开华胥。",
            ["ContentJP"] = "だが、約したその日が、よりによって試合の当日と重なった。メイランは名に縛られて、「まずは勝負に決着をつけ、天下一の名を携えてから」と考えた。",
            ["DialogueId"] = 80210423,
            ["GUID"] = "C8CC6286",
            ["NextDialogue"] = 80210424,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6286",
            },
        [80210424] = {
            ["Content"] = "但高手对决，又怎么会几招内分出胜负，他们斗了三个日夜。等鸣鸾比试结束，前去赴约时，眼前所见只有江上数峰青山，不见人影。",
            ["ContentJP"] = "だが達人同士の勝負が、三合五合で決まるもんじゃねぇ。三日三晩、斬り結んだ。勝負を終え、駆けつけた時、そこに残ってたのは、川向こうに連なる青い山並みだけだった。",
            ["DialogueId"] = 80210424,
            ["GUID"] = "C8CC62B0",
            ["NextDialogue"] = 80210425,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC62B0",
            },
        [80210425] = {
            ["Content"] = "应当是那位红颜知己见他仍然是放不下名声，感到失望而独自离开。",
            ["ContentJP"] = "虚名に未練を残す彼に失望して、女はひとり去ったんだろう。",
            ["DialogueId"] = 80210425,
            ["GUID"] = "C8CC62DA",
            ["NextDialogue"] = 80210426,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC62DA",
            },
        [80210426] = {
            ["Content"] = "鸣鸾最初不以为意，但是很快便思念成疾，察觉到这世界上有比所谓的“天下第一”更重要的事物。",
            ["ContentJP"] = "初めは気にも留めなかったメイランだが、やがて悲しい想いは病のように身を蝕み、この世には“天下一”より大切なものがあると悟った。",
            ["DialogueId"] = 80210426,
            ["GUID"] = "C8CC6304",
            ["NextDialogue"] = 80210427,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6304",
            },
        [80210427] = {
            ["Content"] = "于是他也离开了华胥，寻觅至今，却还是没有寻到。",
            ["ContentJP"] = "そして彼は華胥を離れ、愛を取り戻すため旅に出たが、未だに進展がねぇ。",
            ["DialogueId"] = 80210427,
            ["GUID"] = "C8CC632E",
            ["NextDialogue"] = 80210428,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC632E",
            },
        [80210428] = {
            ["Content"] = "所以这一次比武论剑，他不参加。",
            ["ContentJP"] = "だから彼も今回の試合に出られねぇ。",
            ["DialogueId"] = 80210428,
            ["GUID"] = "C8CC6358",
            ["NextDialogue"] = 80210429,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk02R_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6358",
            },
        [80210429] = {
            ["Camera"] = "523.363281,229.195312,121.128906,0.000162,1.999995,-122.399033,42.362053,406.334045,false,Manual,2.8",
            ["Content"] = "至于最后一位，被称作庖侠，妙手调羹的本领是一绝，所制作的“若木无觅衔烛龙”更是举世无双。",
            ["ContentJP"] = "最後に会ったのは、「庖侠」とも呼ばれた男だ。料理の腕で名が知れてて、得意の「燭龍焼き」は天下一と言っても過言ではない。",
            ["DialogueId"] = 80210429,
            ["FinalCamera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["GUID"] = "C8CC6382",
            ["NextDialogue"] = 80210430,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_Start",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6382",
            },
        [80210430] = {
            ["Content"] = "但在他某次设宴招待客人时，却被歹人在饭菜中下了毒，青花的瓷盘本来盛的是珍果佳肴，却沾染了血。",
            ["ContentJP"] = "ある宴で、悪党が料理に毒を盛った。青花の皿に並んだ佳肴は、一転して血に染まった。",
            ["DialogueId"] = 80210430,
            ["GUID"] = "C8CC63AC",
            ["NextDialogue"] = 80210431,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC63AC",
            },
        [80210431] = {
            ["Content"] = "这毒虽然不是他下的，但毕竟饭菜都经过他手，于是也被大风九章认定为有罪。",
            ["ContentJP"] = "もちろん毒は庖侠の仕業じゃねぇ。だが料理は彼の手を経ている——それだけで大風九章に罪人扱いされた。",
            ["DialogueId"] = 80210431,
            ["GUID"] = "C8CC63D6",
            ["NextDialogue"] = 80210432,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC63D6",
            },
        [80210432] = {
            ["Content"] = "他的武艺，要应对应天尉倒也不难。但一旦反抗，那简直如同是自认有罪，所以他就束手就擒，受到惩罚，跛了一足。",
            ["ContentJP"] = "彼の腕は立つが、そこで抗えば自白したも同然。そう思うと、彼は抵抗せずに捕らえられ、片脚を折られる罰を受けた。",
            ["DialogueId"] = 80210432,
            ["GUID"] = "C8CC6400",
            ["NextDialogue"] = 80210433,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6400",
            },
        [80210433] = {
            ["Content"] = "等他重回自由身时，也是心灰意冷，不再以飘零人自居，专心磨练厨艺去了，炸油豆腐是一绝。",
            ["ContentJP"] = "心が折れちまったんだろう。牢から出た今の彼は流れ者をやめ、鍋と火にだけ向き合って生きてる。あいつの油揚げは、そりゃもう絶品だ。",
            ["DialogueId"] = 80210433,
            ["GUID"] = "C8CC642A",
            ["NextDialogue"] = 80210434,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC642A",
            },
        [80210434] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "难道说前几天你带给我的油豆腐就是……",
            ["ContentJP"] = "もしかして、この前あなたが持って帰ってきてくれた油揚げは……",
            ["DialogueId"] = 80210434,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC6454",
            ["NextDialogue"] = 80210435,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6454",
            },
        [80210435] = {
            ["Camera"] = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
            ["Content"] = "不，不是，我什么都没说，你什么都没听见。",
            ["ContentJP"] = "ん？……あっ！何も言ってねぇよ、何も……",
            ["DialogueId"] = 80210435,
            ["FacialId"] = {
                [1] = "790067:Nervous",
                },
            ["FinalCamera"] = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
            ["GUID"] = "C8CC647E",
            ["NextDialogue"] = 80210436,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC647E",
            },
        [80210436] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "噢……我懂了。",
            ["ContentJP"] = "なるほど……わかった。",
            ["DialogueId"] = 80210436,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC64A8",
            ["NextDialogue"] = 80210437,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64A8",
            },
        [80210437] = {
            ["Content"] = "不过这么一来……岂不是来参加比武的，只有代表宴山亭师父的你？",
            ["ContentJP"] = "でも、こうなると……残された参加者はあなただけではない{性别:か|の}？",
            ["DialogueId"] = 80210437,
            ["GUID"] = "C8CC64D2",
            ["NextDialogue"] = 80210438,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64D2",
            },
        [80210438] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "没错，这次比武论剑，只有我代表师父参加。",
            ["ContentJP"] = "そう、今回の剣道試合の参加者はただ一人、宴山亭の代表者——この俺。",
            ["DialogueId"] = 80210438,
            ["FacialId"] = {
                [1] = "790067:None",
                },
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC64FC",
            ["NextDialogue"] = 80210439,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk03_End",
                [2] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 40,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC64FC",
            },
        [80210439] = {
            ["Content"] = "这就是现在飘零人的现状啊，曾几何时他们聚啸山林，没有什么特意需要遵从的法条，只需要遵从内心与手中剑。",
            ["ContentJP"] = "これが流れ者の現状さ。昔はあれだけ達人が集まって、好き放題に世を渡ってたってのにな。",
            ["DialogueId"] = 80210439,
            ["GUID"] = "C8CC6526",
            ["NextDialogue"] = 80210440,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6526",
            },
        [80210440] = {
            ["Content"] = "刀光剑影里有着一个又一个快意恩仇的故事。",
            ["ContentJP"] = "剣の光と影が交わって、夢みてぇな武勇譚が毎日のように続いてた。",
            ["DialogueId"] = 80210440,
            ["GUID"] = "C8CC6550",
            ["NextDialogue"] = 80210441,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6550",
            },
        [80210441] = {
            ["Content"] = "在大风九章之下，没有所谓的路见不平拔刀相助，大家都畏惧触发法条，被应天尉盯上。",
            ["ContentJP"] = "だが、大風九章の下で人を助けることも、悪を討つことも一切ない。皆天律に触れることを怖がっているんだから。",
            ["DialogueId"] = 80210441,
            ["GUID"] = "C8CC657A",
            ["NextDialogue"] = 80210442,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC657A",
            },
        [80210442] = {
            ["Content"] = "即便是号称自由自在的飘零人，也无法免于受到大风九章的羁绊。",
            ["ContentJP"] = "そして、自由の流れ者も、大風九章に縛られてるんだ。",
            ["DialogueId"] = 80210442,
            ["GUID"] = "C8CC65A4",
            ["NextDialogue"] = 80210443,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65A4",
            },
        [80210443] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "所以，你才会想要推翻大风九章？",
            ["ContentJP"] = "だから大風九章を倒したいの{性别:か|}……",
            ["DialogueId"] = 80210443,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC65CE",
            ["NextDialogue"] = 80210444,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65CE",
            },
        [80210444] = {
            ["Camera"] = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
            ["Content"] = "只能说是原因之一吧，还有其他的新仇旧恨。",
            ["ContentJP"] = "まあ…それも理由の一つだけと、他にもいろいろあったんだぜ。",
            ["DialogueId"] = 80210444,
            ["FinalCamera"] = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
            ["GUID"] = "C8CC65F8",
            ["NextDialogue"] = 80210445,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Talk01_End",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC65F8",
            },
        [80210445] = {
            ["Content"] = "有时候我也在想，有大风九章在，至少大部分人能够安居，去反对它是不是真的有意义。",
            ["ContentJP"] = "実はよ、時々考えるんだ。多くの人に安泰をもたらしてる大風九章を反抗することに、果たして意味はあるのであろうか？",
            ["DialogueId"] = 80210445,
            ["GUID"] = "C8CC6622",
            ["NextDialogue"] = 80210446,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6622",
            },
        [80210446] = {
            ["Content"] = "但这次为了准备论剑拜访了诸位前辈，看他们也都过得不尽如人意，那么在一片祥和之下，到底有多少不平之事，又有谁知道。",
            ["ContentJP"] = "だがな、今回の立ち合いに向けてあちこちの先輩を訪ね歩いたが、皆胸を張って幸せとは言い難ぇ。この「安泰」の裏に、一体どれだけの理不尽が隠れてんだか……。",
            ["DialogueId"] = 80210446,
            ["GUID"] = "C8CC664C",
            ["NextDialogue"] = 80210447,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC664C",
            },
        [80210447] = {
            ["Content"] = "我作为飘零人，就不应该袖手旁观。虽说江湖儿女日渐少，但也有句话说得好嘛，天下风云出我辈。",
            ["ContentJP"] = "流れ者の俺は、このような不正を、腕をこまねいて見過ごすわけにはいかねぇ。「盛者必衰」をひっくり返しゃ――「衰者必盛」だ。変わらないものなんて、この世にはあるはずがねぇ。",
            ["DialogueId"] = 80210447,
            ["GUID"] = "C8CC6676",
            ["NextDialogue"] = 80210448,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6676",
            },
        [80210448] = {
            ["Content"] = "长剑在手，人在江湖，即便如孤鹜飘零，也能为天下之先，一览他人未见之景，是好事。",
            ["ContentJP"] = "剣を携えて、漂泊の身でも、誰より先に踏み込んで、誰も見たことのねぇ景色をこの目で見られるんだ。悪くねぇだろ？",
            ["DialogueId"] = 80210448,
            ["GUID"] = "C8CC66A0",
            ["NextDialogue"] = 80210449,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66A0",
            },
        [80210449] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "行应行之路，竟未竟之志。我想，我大概明白所谓的飘零人为什么能延续至今了。",
            ["ContentJP"] = "ゆえに、歩むべき道を歩き、未だ果たせぬ志を成し遂げる――{性别:そういうことだ|そういうことなんだね}。流れ者ってのがどうやって今日まで続いてきたのか、ちょっと分かった気がする。",
            ["DialogueId"] = 80210449,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC66CA",
            ["NextDialogue"] = 80210450,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_Start",
                },
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66CA",
            },
        [80210450] = {
            ["Content"] = "并且我也相信，此后比武论剑之人，肯定不会像今天这样，只有你孤身一人的。",
            ["ContentJP"] = "信じているよ。きっと、今後の試合は、一人にさせない。",
            ["DialogueId"] = 80210450,
            ["GUID"] = "C8CC66F4",
            ["NextDialogue"] = 80210451,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC66F4",
            },
        [80210451] = {
            ["Camera"] = "795.160156,-371.187988,113.348633,0.000152,1.999995,146.999313,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "哈哈哈哈，好，好，好，说得好。",
            ["ContentJP"] = "ははははっ！よく言うじゃねぇか。",
            ["DialogueId"] = 80210451,
            ["FacialId"] = {
                [1] = "790067:Smile01",
                },
            ["FinalCamera"] = "862.960938,-289.070312,112.585938,0.000152,1.999995,156.599838,42.362053,398.766113,false,Manual,2.8",
            ["GUID"] = "C8CC671E",
            ["NextDialogue"] = 80210452,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 10,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC671E",
            },
        [80210452] = {
            ["Content"] = "不过嘛，我可没有为没有人论剑感到难过，不如说，这可是大好事——",
            ["ContentJP"] = "ところで。試合の相手がいないのは、逆にラッキーだと思うぜ！",
            ["DialogueId"] = 80210452,
            ["GUID"] = "C8CC6748",
            ["NextDialogue"] = 80210453,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6748",
            },
        [80210453] = {
            ["Camera"] = "408.371094,68.496582,165.21582,0.000151,-3.99997,-106.198517,42.362053,214.163193,false,Manual,2.8",
            ["Content"] = "我宣布，因为其他三位比武者的缺席，宴山亭的弟子刻舟，正式成为华胥第一飘零人。",
            ["ContentJP"] = "では、今回の剣道試合——相手が欠席したため、優勝者は宴山亭の弟子カシュウだ！ここで「華胥一の流れ者」になった！",
            ["DialogueId"] = 80210453,
            ["FinalCamera"] = "399.097656,36.579102,162.895508,0.000151,-2.99999,-106.198524,42.362053,175.129822,false,Manual,2.8",
            ["GUID"] = "C8CC6772",
            ["NextDialogue"] = 80210454,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_Start",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6772",
            },
        [80210454] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "就这么宣布了？",
            ["ContentJP"] = "かるい。",
            ["DialogueId"] = 80210454,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC679C",
            ["NextDialogue"] = 80210455,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC679C",
            },
        [80210455] = {
            ["Camera"] = "434.003906,248.654785,121.818359,0.000152,1.999995,-107.80146,42.362053,398.766113,false,Manual,2.8",
            ["Content"] = "那不然呢？我师父就让我这么做的。我记得清清楚楚，当时他和我说，如果上一届的参加者们不想参加比武，那么也不用强行劝说。",
            ["ContentJP"] = "仕方ねぇだろ。師匠に頼まれたんだ。あの人の言葉はちゃんと覚えてるよ。「もし、前回の参加者たちは出たくないなら、無理に説得しなくていいぞ」ってことだ。",
            ["DialogueId"] = 80210455,
            ["FinalCamera"] = "408.511719,168.209961,124.753906,0.000153,2.99999,-105.801682,42.362053,306.325958,false,Manual,2.8",
            ["GUID"] = "C8CC67C6",
            ["NextDialogue"] = 80210456,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC67C6",
            },
        [80210456] = {
            ["Content"] = "毕竟，如果参加人数少了，那么赢到最后的可能性也会跟着变大，说不定只要比试一场就能夺冠了。",
            ["ContentJP"] = "なぜなら——出場者が少なけりゃ、勝ち抜ける目もでかくなる。下手すりゃ一戦勝てば優勝――そんな計算だった。",
            ["DialogueId"] = 80210456,
            ["GUID"] = "C8CC67F0",
            ["NextDialogue"] = 80210457,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC67F0",
            },
        [80210457] = {
            ["Content"] = "师父还是太保守了，实际上一场都没比试，这才叫真正的天下无敌！",
            ["ContentJP"] = "だがふたを開けりゃ見通しが甘かったな。\
結局、一度も刃を交えることすらなかった。まさに、天下無双である！",
            ["DialogueId"] = 80210457,
            ["GUID"] = "C8CC681A",
            ["NextDialogue"] = 80210458,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC681A",
            },
        [80210458] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "我还以为你会再低落一会儿。",
            ["ContentJP"] = "もっと落ち込んでると思ったけど？",
            ["DialogueId"] = 80210458,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC6844",
            ["NextDialogue"] = 80210459,
            ["SpeakNpcId"] = 790008,
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6844",
            },
        [80210459] = {
            ["Camera"] = "502.972656,27.527832,181.694336,0.000158,-7.999989,-134.198502,42.362053,234.67363,false,Manual,2.8",
            ["Content"] = "黯然神伤刻舟求剑这种事情，不适合我，有其他人做就行了。",
            ["ContentJP"] = "昔の事でひたすらかなしゅうことなんで、俺には合わないよ。他の誰かがやればいい。",
            ["DialogueId"] = 80210459,
            ["FinalCamera"] = "481.535156,5.483887,177.371094,0.000159,-7.999968,-134.198471,42.362053,201.77124,false,Manual,2.8",
            ["GUID"] = "C8CC686E",
            ["NextDialogue"] = 80210460,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC686E",
            },
        [80210460] = {
            ["Content"] = "我要做的，是斩落师父，师兄，以及诸位前辈们为之郁结的大风九章。",
            ["ContentJP"] = "今の俺がやるべき事は、仲間と師匠を悲しませた大風九章を討伐するこどだ。",
            ["DialogueId"] = 80210460,
            ["GUID"] = "C8CC6898",
            ["NextDialogue"] = 80210461,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6898",
            },
        [80210461] = {
            ["Content"] = "等到这件事告一段落后，我大概才能和那些飘零人小说中描写的一样，退隐山林了。",
            ["ContentJP"] = "無事に一段落ついた後、俺も流れ者小説に描かれた名手達のように俗世から離れ、引退するつもりなんだ。",
            ["DialogueId"] = 80210461,
            ["GUID"] = "C8CC68C2",
            ["NextDialogue"] = 80210462,
            ["SpeakNpcId"] = 790067,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC68C2",
            },
        [80210462] = {
            ["Camera"] = "511.71875,-314.994141,144.21875,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["Content"] = "依你的性格，我感觉你闲不下来。",
            ["ContentJP"] = "どうにもふさわしくないと思う{性别:な|よ}。",
            ["DialogueId"] = 80210462,
            ["FinalCamera"] = "491.65625,-286.541504,141.78418,0.000125,-4.000004,125.200066,42.362053,376.295776,false,Manual,2.8",
            ["GUID"] = "C8CC68EC",
            ["NextDialogue"] = 80210463,
            ["SpeakNpcId"] = 790008,
            ["TalkActionId"] = {
                [1] = "790008:DisagreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC68EC",
            },
        [80210463] = {
            ["Camera"] = "377.449219,42.706543,179.00293,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
            ["Content"] = "确实，那就等那时再说吧。",
            ["ContentJP"] = "確かに。まぁ、その話はまた後にしよう。",
            ["DialogueId"] = 80210463,
            ["FinalCamera"] = "377.128906,35.079102,177.938477,0.000195,-7.99994,-98.99649,42.362053,171.145584,false,Manual,2.8",
            ["GUID"] = "C8CC6916",
            ["NextDialogue"] = 80210464,
            ["SpeakNpcId"] = 790067,
            ["TalkActionId"] = {
                [1] = "790067:AgreeHead",
                },
            ["ToFinalCameraBlendTime"] = 5,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6916",
            },
        [80210464] = {
            ["Camera"] = "855.464844,-598.185059,132.694336,0.0,0.0,136.606979,26.65424,695.636841,false,Manual,2.8",
            ["Content"] = "今日拔得头筹成为第一飘零人，应该开心过活，不去管那以后的事。来吧，朋友，且歌且醉，且醉且歌！",
            ["ContentJP"] = "それよりも…とうとう天下一の流れ者になれたぞ！思う存分楽しまないと！さあ、友よ！音を奏でろ！酔っぱらうまで飲むぞ！",
            ["DialogueId"] = 80210464,
            ["FinalCamera"] = "1130.59375,-914.811523,132.694336,0.0,0.0,133.406891,26.65424,275.423279,false,Manual,2.8",
            ["GUID"] = "C8CC6940",
            ["NextDialogue"] = 80210465,
            ["SpeakNpcId"] = 790067,
            ["ToFinalCameraBlendTime"] = 20,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6940",
            },
        [80210465] = {
            ["Content"] = "那些曾经锋芒毕露的，生死相许的，快意恩仇的，都早已成为风中一缕轻尘。",
            ["ContentJP"] = "刃を輝かせ、命を預け合い、恩と仇をはっきりさせた日々も、いまや風に紛れる微塵のよう。",
            ["DialogueId"] = 80210465,
            ["GUID"] = "C8CC696A",
            ["NextDialogue"] = 80210466,
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC696A",
            },
        [80210466] = {
            ["Content"] = "最终都只剩下满头霜雪与轻叹一声，少年子弟江湖老。",
            ["ContentJP"] = "残るのは雪のような白髪と、ふっと漏れる溜息だけ。",
            ["DialogueId"] = 80210466,
            ["GUID"] = "C8CC6994",
            ["VoiceName"] = "voice/$Locale$/inv/Kezhou/004/C8CC6994",
            },
        [80210467] = {
            ["DialogueId"] = 80210467,
            ["Duration"] = 1,
            ["GUID"] = "C8CC6995",
            ["IsBlack"] = 1,
            },
        [80220101] = {
            ["Content"] = "……",
            ["DialogueId"] = 80220101,
            ["GUID"] = "C8D29652",
            ["NextDialogue"] = 80220102,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29652",
            },
        [80220102] = {
            ["Content"] = "师兄？",
            ["ContentJP"] = "兄さん……？",
            ["DialogueId"] = 80220102,
            ["GUID"] = "C8D2967C",
            ["NextDialogue"] = 80220103,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2967C",
            },
        [80220103] = {
            ["Content"] = "是不夏啊。",
            ["ContentJP"] = "フウカか。",
            ["DialogueId"] = 80220103,
            ["GUID"] = "C8D296A6",
            ["NextDialogue"] = 80220104,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296A6",
            },
        [80220104] = {
            ["Content"] = "老远就听到笛声了，果然是你。",
            ["ContentJP"] = "遠くから笛の音がする。やっぱり兄さんだね。",
            ["DialogueId"] = 80220104,
            ["GUID"] = "C8D296D0",
            ["NextDialogue"] = 80220105,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296D0",
            },
        [80220105] = {
            ["Content"] = "你找我有事？",
            ["ContentJP"] = "俺に用か。",
            ["DialogueId"] = 80220105,
            ["GUID"] = "C8D296FA",
            ["NextDialogue"] = 80220106,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D296FA",
            },
        [80220106] = {
            ["Content"] = "其实是……师兄，帮忙看看它吧。",
            ["ContentJP"] = "えっと……この子、見てもらえる？",
            ["DialogueId"] = 80220106,
            ["GUID"] = "C8D29724",
            ["NextDialogue"] = 80220107,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29724",
            },
        [80220107] = {
            ["Content"] = "我和刻舟师兄在山外山外面发现了这只小狐狸，它被野兽咬伤了。",
            ["ContentJP"] = "カシュウ兄さんと<Default note=\"text:さんがいさん\">山外山</>の外で、この小さなキツネを見つけたの。どうやら獣に噛まれたみたいで……。",
            ["DialogueId"] = 80220107,
            ["GUID"] = "C8D2974E",
            ["NextDialogue"] = 80220108,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2974E",
            },
        [80220108] = {
            ["Content"] = "刻舟师兄粗枝大叶，完全不知道怎么处理它身上的伤，就只能来找师兄你了。放着不管的话，它很快便会死掉的。",
            ["ContentJP"] = "カシュウ兄さん、荒っぽいのでこういう手当てはさっぱりで……。だからお願い、あなたに診てもらいたくて来たの。このまま放っておいたら、すぐ死んじゃう……。",
            ["DialogueId"] = 80220108,
            ["GUID"] = "C8D29778",
            ["NextDialogue"] = 80220109,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29778",
            },
        [80220109] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80220109,
            ["GUID"] = "C8D297A2",
            ["NextDialogue"] = 80220110,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297A2",
            },
        [80220110] = {
            ["Content"] = "师兄？",
            ["ContentJP"] = "兄さん……？",
            ["DialogueId"] = 80220110,
            ["GUID"] = "C8D297CC",
            ["NextDialogue"] = 80220111,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297CC",
            },
        [80220111] = {
            ["Content"] = "没什么。让我来看看吧。",
            ["ContentJP"] = "……いい。見せろ。",
            ["DialogueId"] = 80220111,
            ["GUID"] = "C8D297F6",
            ["NextDialogue"] = 80220112,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D297F6",
            },
        [80220112] = {
            ["Content"] = "我们发现它的时候，它就那么蜷在岩石的缝隙之间，死死地盯着外面。我们在附近找到了几只断了气的大狐狸，顺着它们的血迹才找到了这个小家伙。",
            ["ContentJP"] = "見つけたとき、この子は岩の割れ目で丸くなって、ずっと外を見つめてた。近くにキツネの死骸があって……血の跡をたどったら、この子がいたの。",
            ["DialogueId"] = 80220112,
            ["GUID"] = "C8D29820",
            ["NextDialogue"] = 80220113,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29820",
            },
        [80220113] = {
            ["Content"] = "刻舟师兄把它抱起来的时候，它没有叫，也没有害怕。或者说……它太小了，小到甚至不明白发生了什么，只能这么颤抖着被带来这里。",
            ["ContentJP"] = "カシュウ兄さんに抱き上げられても、この子、鳴きもしないし暴れもしなかった。たぶん……小さすぎて、何が起きてるのかも分からなくて、ただ震えることしかできなかったんだと思う。",
            ["DialogueId"] = 80220113,
            ["GUID"] = "C8D2984A",
            ["NextDialogue"] = 80220114,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2984A",
            },
        [80220114] = {
            ["Content"] = "……伤口处理好了。",
            ["ContentJP"] = "……手当ては済んだ。",
            ["DialogueId"] = 80220114,
            ["GUID"] = "C8D29874",
            ["NextDialogue"] = 80220115,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29874",
            },
        [80220115] = {
            ["Content"] = "让刻舟去砍些木材回来，我给它搭个窝避雨。",
            ["ContentJP"] = "カシュウに伝えろ。薪を割ってこい。雨宿りできる巣を作るから。",
            ["DialogueId"] = 80220115,
            ["GUID"] = "C8D2989E",
            ["NextDialogue"] = 80220116,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2989E",
            },
        [80220116] = {
            ["Content"] = "师兄你的意思是……我们可以养它吗？",
            ["ContentJP"] = "えっ……この子、うちで飼ってもいいってこと！？",
            ["DialogueId"] = 80220116,
            ["GUID"] = "C8D298C8",
            ["NextDialogue"] = 80220117,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D298C8",
            },
        [80220117] = {
            ["Content"] = "太好了，我这就去！嗯嗯，还得给它取个名字……就叫你“小橙子”吧！小狐狸！",
            ["ContentJP"] = "やった！ すぐ行く！そうそう、名前もつけなきゃね……よし、あなたは「ミカン」よ！",
            ["DialogueId"] = 80220117,
            ["GUID"] = "C8D298F2",
            ["NextDialogue"] = 80220118,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D298F2",
            },
        [80220118] = {
            ["Content"] = "一年后",
            ["ContentJP"] = "1年後",
            ["DialogueId"] = 80220118,
            ["GUID"] = "C8D2991C",
            ["NextDialogue"] = 80220119,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2991C",
            },
        [80220119] = {
            ["Content"] = "不夏？",
            ["ContentJP"] = "フウカ……？",
            ["DialogueId"] = 80220119,
            ["GUID"] = "C8D29946",
            ["NextDialogue"] = 80220120,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29946",
            },
        [80220120] = {
            ["Content"] = "……",
            ["ContentJP"] = "......",
            ["DialogueId"] = 80220120,
            ["GUID"] = "C8D29970",
            ["NextDialogue"] = 80220121,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29970",
            },
        [80220121] = {
            ["Content"] = "不夏。",
            ["ContentJP"] = "おい、フウカ。",
            ["DialogueId"] = 80220121,
            ["GUID"] = "C8D2999A",
            ["NextDialogue"] = 80220122,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2999A",
            },
        [80220122] = {
            ["Content"] = "师兄！你回来啦？",
            ["ContentJP"] = "あっ、兄さん、お帰り。",
            ["DialogueId"] = 80220122,
            ["GUID"] = "C8D299C4",
            ["NextDialogue"] = 80220123,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D299C4",
            },
        [80220123] = {
            ["Content"] = "你的耳朵？",
            ["ContentJP"] = "……耳、どうした。",
            ["DialogueId"] = 80220123,
            ["GUID"] = "C8D299EE",
            ["NextDialogue"] = 80220124,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D299EE",
            },
        [80220124] = {
            ["Content"] = "没事没事，只是有一只耳朵偶尔听不清而已，另一只好着呢！……嗯，一定是耳朵告诉我，我又该睡大觉了！",
            ["ContentJP"] = "大丈夫、大丈夫！ 片耳がちょっと聞こえにくい時があるだけで、もう片方は平気！……それにほら、耳が「今が寝坊の時間だよ」って教えてくれてるだけだよ、きっと！",
            ["DialogueId"] = 80220124,
            ["GUID"] = "C8D29A18",
            ["NextDialogue"] = 80220125,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A18",
            },
        [80220125] = {
            ["Content"] = "……不要怠惰。若不是你与刻舟偷懒被发现，师父也不会罚你们在这里抄书三天，磨砺心性。你与刻舟天赋有别，若继续和他一般，迟早会被拖累。",
            ["ContentJP"] = "とぼけるな。あんたとカシュウがサボってたのが師匠にバレたんだろ。罰で写本だ。……才能に差がある以上、カシュウみたいな真似を続けるな。いずれ足を引っ張られる。",
            ["DialogueId"] = 80220125,
            ["GUID"] = "C8D29A42",
            ["NextDialogue"] = 80220126,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A42",
            },
        [80220126] = {
            ["Content"] = "至于你的耳朵，我想还是得早日去皓京寻得药师来瞧瞧。",
            ["ContentJP"] = "それと、その耳だ。早く<Default note=\"text:こうけい\">皓京</>の薬師に診てもらおう。",
            ["DialogueId"] = 80220126,
            ["GUID"] = "C8D29A6C",
            ["NextDialogue"] = 80220127,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A6C",
            },
        [80220127] = {
            ["Content"] = "知道啦知道啦——师兄还那么年轻，就像师父那个老头子一样唠唠叨叨的。",
            ["ContentJP"] = "わかったわかった、もう。兄さんってば、まるであの口うるさい師匠みたい。",
            ["DialogueId"] = 80220127,
            ["GUID"] = "C8D29A96",
            ["NextDialogue"] = 80220128,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29A96",
            },
        [80220128] = {
            ["Content"] = "对了对了，小橙子怎么样了？昨天下了那么大的雨，我有点担心……",
            ["ContentJP"] = "そうだ、ミカンちゃんは元気？昨日はすごい雨だったから、ちょっと心配で……。",
            ["DialogueId"] = 80220128,
            ["GUID"] = "C8D29AC0",
            ["NextDialogue"] = 80220129,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29AC0",
            },
        [80220129] = {
            ["Content"] = "今天我去后山看它，此前给它造的小窝被山石砸坏了。它蜷缩在那些折断的木板下面，任凭雨水渗过缝隙流淌在它身上。",
            ["ContentJP"] = "裏山を見てきた。以前作ってあげた小さな巣は石に潰されてたから、割れた板の下にあいつを見つけた。隙間からしみ込んできた雨に濡れながら、影に小さく丸くなっているんだ。",
            ["DialogueId"] = 80220129,
            ["GUID"] = "C8D29AEA",
            ["NextDialogue"] = 80220130,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29AEA",
            },
        [80220130] = {
            ["Content"] = "我把窝修补好了，又放了些干草。但它还是老样子，蜷在那儿发抖。",
            ["ContentJP"] = "一応あいつの巣を直し、干し草も入れたけど。まだ震えてるんだ。",
            ["DialogueId"] = 80220130,
            ["GUID"] = "C8D29B14",
            ["NextDialogue"] = 80220131,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B14",
            },
        [80220131] = {
            ["Content"] = "唉……这叫我怎么放心得下呀。",
            ["ContentJP"] = "ほんと……心配でたまらないよ……。",
            ["DialogueId"] = 80220131,
            ["GUID"] = "C8D29B3E",
            ["NextDialogue"] = 80220132,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B3E",
            },
        [80220132] = {
            ["Content"] = "你们在干什么？不夏，你的书抄完了？",
            ["ContentJP"] = "こら！お前ら何をしている？フウカ、写本は終わったか。",
            ["DialogueId"] = 80220132,
            ["GUID"] = "C8D29B68",
            ["NextDialogue"] = 80220133,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B68",
            },
        [80220133] = {
            ["Content"] = "啊，师父，我……我们只是在商量武学！今天早上煜明师兄使出了一招枪，特别好看前所未见，我看了就也想学一学，所以正在和他讨教……没干什么，嘿嘿。",
            ["ContentJP"] = "あっ、師匠！ わ、私たちは……ちょうど武術の話をしていたんです！今朝、ユーミン先輩が槍さばきを見せてくれて……すごく格好よくて、私も習いたいなって。ほ、本当ですから！えへへっ…",
            ["DialogueId"] = 80220133,
            ["GUID"] = "C8D29B92",
            ["NextDialogue"] = 80220134,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29B92",
            },
        [80220134] = {
            ["Content"] = "是的。",
            ["ContentJP"] = "うん。",
            ["DialogueId"] = 80220134,
            ["GUID"] = "C8D29BBC",
            ["NextDialogue"] = 80220135,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29BBC",
            },
        [80220135] = {
            ["Content"] = "唉，你们俩，一个说谎的时候话会变多，一个说谎的时候话会变少。当为师是你们俩养的那小狐狸一样不通人言吗？",
            ["ContentJP"] = "はぁ…お前ら、嘘をつくときは決まって、片方がやたら喋って、もう片方が口を閉じる。わしを、言葉の分からん子ギツネだと思っておるのか。",
            ["DialogueId"] = 80220135,
            ["GUID"] = "C8D29BE6",
            ["NextDialogue"] = 80220136,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29BE6",
            },
        [80220136] = {
            ["Content"] = "原来……师父都知道了呀。",
            ["ContentJP"] = "バレ.....た。",
            ["DialogueId"] = 80220136,
            ["GUID"] = "C8D29C10",
            ["NextDialogue"] = 80220137,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C10",
            },
        [80220137] = {
            ["Content"] = "为师只是老了不是傻了！一年前你们把这小东西捡来的时候我就知道了，毕竟它也时不时到处撒欢。",
            ["ContentJP"] = "わしはまだボケてはおらん！あの暴れん坊のことなら、とっくに気づいている。……一年も前からな。お前らが拾ってきた日から、あちこちを駆け回っておった。",
            ["DialogueId"] = 80220137,
            ["GUID"] = "C8D29C3A",
            ["NextDialogue"] = 80220138,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C3A",
            },
        [80220138] = {
            ["Content"] = "这几天没有见它，特意寻过来看一看，发现你们俩在这边愁眉苦脸，想问问怎么回事，没想到还和我不老实。",
            ["ContentJP"] = "ここ数日、姿を見んので探しに行った。戻ってみれば、お前らが浮かぬ顔。何があったのかと思って声をかけたが……まさか、わしに隠し立てするとはな。",
            ["DialogueId"] = 80220138,
            ["GUID"] = "C8D29C64",
            ["NextDialogue"] = 80220139,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C64",
            },
        [80220139] = {
            ["Content"] = "哎呀，这不是因为师父一直仙风道骨，是武林耆宿，想着你可能更喜欢什么鹤呀鹿呀之类的动物，不喜欢狐狸，所以不敢告诉你嘛。",
            ["ContentJP"] = "だってぇ……天才で格好いい師匠さまは、きっとツルとかシカが好きで……キツネなんてお嫌いかもしれないって思ったら、言い出す勇気なんて出ないですよぉ。",
            ["DialogueId"] = 80220139,
            ["GUID"] = "C8D29C8E",
            ["NextDialogue"] = 80220140,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29C8E",
            },
        [80220140] = {
            ["Content"] = "还在饶舌，又是跟刻舟学的吧。为师什么时候讲究那些了。说吧，遇到什么问题了？",
            ["ContentJP"] = "うまいこと言うの。カシュウにでも仕込まれたか。わしはそんなにことなど気にせん。言え。何があった？",
            ["DialogueId"] = 80220140,
            ["GUID"] = "C8D29CB8",
            ["NextDialogue"] = 80220141,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29CB8",
            },
        [80220141] = {
            ["Content"] = "（不夏和煜明把“小橙子”的事告诉了宴山亭。）",
            ["ContentJP"] = "(フウカとユーミンは宴山亭に「ミカン」のことを話した）",
            ["DialogueId"] = 80220141,
            ["GUID"] = "C8D29CE2",
            ["NextDialogue"] = 80220142,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29CE2",
            },
        [80220142] = {
            ["Content"] = "哈哈，我当是什么事。要是我，我就把它拎起来，拎到它来的地方去。山外山不是它的家，外面的山林才是。",
            ["ContentJP"] = "……はは、そういうことか。わしなら拾って、元の場所へ戻すぞ。あの子の故郷は、この<Default note=\"text:さんがいさん\">山外山</>ではない。外の山と森だ。",
            ["DialogueId"] = 80220142,
            ["GUID"] = "C8D29D0C",
            ["NextDialogue"] = 80220143,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D0C",
            },
        [80220143] = {
            ["Content"] = "那……那怎么行！它饿的时候谁来喂食，冷的时候谁来给它往窝里多塞点棉絮？",
            ["ContentJP"] = "そんな……お腹すいたら誰がごはんあげるんですか？寒かったら、誰が綿を詰めてあげるんですか？",
            ["DialogueId"] = 80220143,
            ["GUID"] = "C8D29D36",
            ["NextDialogue"] = 80220144,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D36",
            },
        [80220144] = {
            ["Content"] = "你看，就是因为你总做这些，它才一直长不大的。",
            ["ContentJP"] = "いつまでもこうしておるから、育たんのだ。",
            ["DialogueId"] = 80220144,
            ["GUID"] = "C8D29D60",
            ["NextDialogue"] = 80220145,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D60",
            },
        [80220145] = {
            ["Content"] = "你们给它搭了避雨的窝，却没有教会它如何度过寒冬。给了它果腹之物，却没有教会它如何捕猎。",
            ["ContentJP"] = "雨よけを与えても、冬を越す方は教えておらん。餌を与えたも、狩り方は教えておらん。",
            ["DialogueId"] = 80220145,
            ["GUID"] = "C8D29D8A",
            ["NextDialogue"] = 80220146,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29D8A",
            },
        [80220146] = {
            ["Content"] = "它饿了冷了都等着你们照顾，要如何自己谋生？要是哪天没我的傻徒儿盯着，一场大雨就能要了它的小命啦。",
            ["ContentJP"] = "腹が減れば、寒くなれば――お前らが世話をするのを待てばいい。それで、どうやって自力で生きるつもりだ。わしの愚かな弟子が見ておらねば、土砂降りひとつで死ぬぞ。",
            ["DialogueId"] = 80220146,
            ["GUID"] = "C8D29DB4",
            ["NextDialogue"] = 80220147,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29DB4",
            },
        [80220147] = {
            ["Content"] = "那、那师父的意思是……",
            ["ContentJP"] = "それは…つまり…？",
            ["DialogueId"] = 80220147,
            ["GUID"] = "C8D29DDE",
            ["NextDialogue"] = 80220148,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29DDE",
            },
        [80220148] = {
            ["Content"] = "纵是你再不舍，它终究还是要回归山林的。它是头小野兽，一味地庇护只会让它失去生存的能力。",
            ["ContentJP"] = "放したくなくとも、いずれ山へ帰るんだ。小さな獣は、匿えば匿うほど、生きる力を失うだけだ。",
            ["DialogueId"] = 80220148,
            ["GUID"] = "C8D29E08",
            ["NextDialogue"] = 80220149,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E08",
            },
        [80220149] = {
            ["Content"] = "……我明白了。让我和两位师兄商量商量……",
            ["ContentJP"] = "わかりました。兄さんたちと相談してきます……",
            ["DialogueId"] = 80220149,
            ["GUID"] = "C8D29E32",
            ["NextDialogue"] = 80220150,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E32",
            },
        [80220150] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80220150,
            ["GUID"] = "C8D29E5C",
            ["NextDialogue"] = 80220151,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E5C",
            },
        [80220151] = {
            ["Content"] = "煜明，你有心事。",
            ["ContentJP"] = "何か悩んでるな、ユーミン。",
            ["DialogueId"] = 80220151,
            ["GUID"] = "C8D29E86",
            ["NextDialogue"] = 80220152,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29E86",
            },
        [80220152] = {
            ["Content"] = "没有。",
            ["ContentJP"] = "……いえ。",
            ["DialogueId"] = 80220152,
            ["GUID"] = "C8D29EB0",
            ["NextDialogue"] = 80220153,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29EB0",
            },
        [80220153] = {
            ["Content"] = "就两个字？又在扯谎。",
            ["ContentJP"] = "「一言」か。……はは、また嘘をついたな。",
            ["DialogueId"] = 80220153,
            ["GUID"] = "C8D29EDA",
            ["NextDialogue"] = 80220154,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29EDA",
            },
        [80220154] = {
            ["Content"] = "……徒儿愚钝。",
            ["ContentJP"] = "申し訳ありません……",
            ["DialogueId"] = 80220154,
            ["GUID"] = "C8D29F04",
            ["NextDialogue"] = 80220155,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F04",
            },
        [80220155] = {
            ["Content"] = "也许那日我们收养小橙子并非明智之举，但如今错已铸成。",
            ["ContentJP"] = "あの日、ミカンを受け入れたのは軽率でした。ですが、起きてしまった以上、責任は取ります。",
            ["DialogueId"] = 80220155,
            ["GUID"] = "C8D29F2E",
            ["NextDialogue"] = 80220156,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F2E",
            },
        [80220156] = {
            ["Content"] = "如您所言，它和我们一起生活许久，已经失去了独自生存的能力。此时若选择放归野外，只怕它……",
            ["ContentJP"] = "おっしゃる通り、あの子は長い間、私たちと一緒に暮らしてきて……自力で生きる術を失っています。このまま野に返せば……",
            ["DialogueId"] = 80220156,
            ["GUID"] = "C8D29F58",
            ["NextDialogue"] = 80220157,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F58",
            },
        [80220157] = {
            ["Content"] = "可能会冻死饿死。你说的这些，我又如何不知。但为师只有一句话，做就别怕，怕就别做。",
            ["ContentJP"] = "おそらく凍えて飢えて死ぬだろう。その可能性を、わしが知らんとでも思ったか。だが言いたいことは一つだ。やるなら、怖がるな。",
            ["DialogueId"] = 80220157,
            ["GUID"] = "C8D29F82",
            ["NextDialogue"] = 80220158,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29F82",
            },
        [80220158] = {
            ["Content"] = "任何选择都伴随着所失和所得。就像咱们飘零人，丢下了大风九章，便是选择自己庇护自己。这无关对错，只关抉择。",
            ["ContentJP"] = "どんな選択にも、損と得がある。我ら流れ者もそうだろう。『<Default note=\"text:たいふうきゅうしょう\">大風九章</>』の教えを捨てて、「己の身は己で守る」道を選んだのだ。これは「善悪」の問題ではなく、「選択」の問題だ。",
            ["DialogueId"] = 80220158,
            ["GUID"] = "C8D29FAC",
            ["NextDialogue"] = 80220159,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29FAC",
            },
        [80220159] = {
            ["Content"] = "为师唯一要的，便是你在做出抉择之前细细思量，莫要让自己后悔才是。",
            ["ContentJP"] = "教えたいのはただ一つ。後悔せぬよう、よく考えて選択せよ。",
            ["DialogueId"] = 80220159,
            ["GUID"] = "C8D29FD6",
            ["NextDialogue"] = 80220160,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D29FD6",
            },
        [80220160] = {
            ["Content"] = "谨遵教诲。",
            ["ContentJP"] = "……はい。承知しました。",
            ["DialogueId"] = 80220160,
            ["GUID"] = "C8D2A000",
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/001/C8D2A000",
            },
        [80220201] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80220201,
            ["GUID"] = "C8D2A6BA",
            ["NextDialogue"] = 80220202,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A6BA",
            },
        [80220202] = {
            ["Content"] = "这是什么？不夏她……变成了妖物？！",
            ["ContentJP"] = "これは…一体？あのフウカさんが......妖怪になったのか？！",
            ["DialogueId"] = 80220202,
            ["GUID"] = "C8D2A6E4",
            ["NextDialogue"] = 80220203,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A6E4",
            },
        [80220203] = {
            ["Content"] = "……不要……别过来，我不想死！",
            ["ContentJP"] = "く、来るな…死にたくないぃ！",
            ["DialogueId"] = 80220203,
            ["GUID"] = "C8D2A70E",
            ["NextDialogue"] = 80220204,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A70E",
            },
        [80220204] = {
            ["Content"] = "莫非这便是……神君的惩罚……因为我们背弃了祂的恩泽？！",
            ["ContentJP"] = "これは…<Default note=\"text:しんくん\">神君</>から下される罰なのか......我々は、神の恵みに背いたからか？",
            ["DialogueId"] = 80220204,
            ["GUID"] = "C8D2A738",
            ["NextDialogue"] = 80220205,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A738",
            },
        [80220205] = {
            ["Content"] = "爹爹、爹爹！呜呜……求你醒醒，求你说句话啊……",
            ["ContentJP"] = "父さん、父さん！ああ......お願い…起きて、何か言ってよ.....",
            ["DialogueId"] = 80220205,
            ["GUID"] = "C8D2A762",
            ["NextDialogue"] = 80220206,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A762",
            },
        }
  end },
  { MinKey = 80220206, MaxKey = 80230219, Loader = function()
      return {
        [80220206] = {
            ["Content"] = "师兄……救我……我，不想……",
            ["ContentJP"] = "兄さん…助けて……死にたく、ない……",
            ["DialogueId"] = 80220206,
            ["GUID"] = "C8D2A78C",
            ["NextDialogue"] = 80220207,
            ["SpeakNpcId"] = 790073,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A78C",
            },
        [80220207] = {
            ["Content"] = "…………",
            ["ContentJP"] = "............",
            ["DialogueId"] = 80220207,
            ["GUID"] = "C8D2A7B6",
            ["NextDialogue"] = 80220208,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A7B6",
            },
        [80220208] = {
            ["Content"] = "是你让我看到这些的吗……太皓？",
            ["ContentJP"] = "……<Default note=\"text:たいこう\">太皓</>よ。俺に見せたいのは……これか。",
            ["DialogueId"] = 80220208,
            ["GUID"] = "C8D2A7E0",
            ["NextDialogue"] = 80220209,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A7E0",
            },
        [80220209] = {
            ["Content"] = "非吾所为。吾无意窥伺凡人心神。",
            ["ContentJP"] = "それは吾の仕業ではない。定命の者の心を、あえて詮索するつもりもない。",
            ["DialogueId"] = 80220209,
            ["GUID"] = "C8D2A80A",
            ["NextDialogue"] = 80220210,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A80A",
            },
        [80220210] = {
            ["Content"] = "你为什么会出现在我心中？我非但是一介凡人，还是一介飘零人。",
            ["ContentJP"] = "なら、なぜ俺の中にいる？俺はただの人間だ。しかも……流れ者だ。",
            ["DialogueId"] = 80220210,
            ["GUID"] = "C8D2A834",
            ["NextDialogue"] = 80220211,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A834",
            },
        [80220211] = {
            ["Content"] = "汝心怀渴盼，欲吾解其惑。吾观汝非池中物，故应此愿。",
            ["ContentJP"] = "汝の胸には、求める答えがすでに在る。汝――どうやら……<Default note=\"text:ぼんよう\">凡庸</>の徒にあらぬ。ゆえに、汝の疑問に答えよう。",
            ["DialogueId"] = 80220211,
            ["GUID"] = "C8D2A85E",
            ["NextDialogue"] = 80220212,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A85E",
            },
        [80220212] = {
            ["Content"] = "……原来我内心深处，竟真的期盼着你的回应。",
            ["ContentJP"] = "......なるほどな。俺は心の底で、その答えを待っていた……ということか。",
            ["DialogueId"] = 80220212,
            ["GUID"] = "C8D2A888",
            ["NextDialogue"] = 80220213,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A888",
            },
        [80220213] = {
            ["Content"] = "汝眼前种种，乃旧魇缚身，不得解脱。",
            ["ContentJP"] = "汝の目の前にあるのは、古き悪夢。忘れられしと思うたものが、なお汝を縛る。汝は未だ、そこより解き放たれておらぬ。",
            ["DialogueId"] = 80220213,
            ["GUID"] = "C8D2A8B2",
            ["NextDialogue"] = 80220214,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A8B2",
            },
        [80220214] = {
            ["Content"] = "……我知道。",
            ["ContentJP"] = "……分かってる。",
            ["DialogueId"] = 80220214,
            ["GUID"] = "C8D2A8DC",
            ["NextDialogue"] = 80220215,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A8DC",
            },
        [80220215] = {
            ["Content"] = "此其墓乎？",
            ["ContentJP"] = "……ここが、彼女の墓であるか。",
            ["DialogueId"] = 80220215,
            ["GUID"] = "C8D2A906",
            ["NextDialogue"] = 80220216,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A906",
            },
        [80220216] = {
            ["Content"] = "她……变成了那样，我甚至无法捡回她的遗骨。我只能寻得她的一些旧衣物，葬在这里。",
            ["ContentJP"] = "あいつは……もう、ああなって。俺は骨を拾うことさえできなかった。見つけられたのは、古い着物が数枚だけだ。……それをここに埋めるしかなかった。",
            ["DialogueId"] = 80220216,
            ["GUID"] = "C8D2A930",
            ["NextDialogue"] = 80220217,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A930",
            },
        [80220217] = {
            ["Content"] = "之所以选择这里，而非山外山……",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>じゃない。ここを選んだ理由は――",
            ["DialogueId"] = 80220217,
            ["GUID"] = "C8D2A95A",
            ["NextDialogue"] = 80220218,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A95A",
            },
        [80220218] = {
            ["Content"] = "是因为她的最后一句话是，“如果当时我选择了大风九章，那么结果会不会不一样。”",
            ["ContentJP"] = "「もしあの時、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の側を選んでいたら――結果は、変わっていたのかな。」それが、あいつの最後の言葉だったからだ。",
            ["DialogueId"] = 80220218,
            ["GUID"] = "C8D2A984",
            ["NextDialogue"] = 80220219,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A984",
            },
        [80220219] = {
            ["Content"] = "祖师扶风教诲过，医者对一切病患都应一视同仁，纵是飘零人也一样。但凡有一线生机，我又怎会不救她！",
            ["ContentJP"] = "たとえ流れ者であっても、医者はすべての患者を平等に扱うべきだと祖師・フーフォン様は教えてた。助かる可能性がある以上、彼女を救わないわけにはいかない！",
            ["DialogueId"] = 80220219,
            ["GUID"] = "C8D2A9AE",
            ["NextDialogue"] = 80220220,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A9AE",
            },
        [80220220] = {
            ["Content"] = "但那是秽蚀，是绝症，一旦开始发作，便再无半分转圜余地！她快要变成妖物了，你们还是趁这个机会赶紧逃命吧！",
            ["ContentJP"] = "しかし、これは穢蝕だ！不治の病だ！ 一度始まったら後戻りはできない！もはや万策尽きた！彼女はまもなく妖怪になる。 今のうち逃げよう！",
            ["DialogueId"] = 80220220,
            ["GUID"] = "C8D2A9D8",
            ["NextDialogue"] = 80220221,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2A9D8",
            },
        [80220221] = {
            ["Content"] = "唉，若非你们飘零人执意脱离大风九章庇佑，又何至于此！",
            ["ContentJP"] = "はぁ、もしあなたたち流れ者が<Default note=\"text:たいふうきゅうしょう\">大風九章</>の祝福から離れなかったら、こんなことにならないのに。",
            ["DialogueId"] = 80220221,
            ["GUID"] = "C8D2AA02",
            ["NextDialogue"] = 80220222,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA02",
            },
        [80220222] = {
            ["Content"] = "为师唯一要的，便是你在做出抉择之前细细思量，莫要让自己后悔才是。",
            ["ContentJP"] = "教えたいのはただ一つ。後悔せぬよう、よく考えて選択せよ。",
            ["DialogueId"] = 80220222,
            ["GUID"] = "C8D2AA2C",
            ["NextDialogue"] = 80220223,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA2C",
            },
        [80220223] = {
            ["Content"] = "……选择。",
            ["ContentJP"] = "……選択、か。",
            ["DialogueId"] = 80220223,
            ["GUID"] = "C8D2AA56",
            ["NextDialogue"] = 80220224,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA56",
            },
        [80220224] = {
            ["Content"] = "太皓，如果我们选择了大风九章，那么结果会不会不一样？",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>よ、もし、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の側を選んでいたら――結果は、変わっていたのか。",
            ["DialogueId"] = 80220224,
            ["GUID"] = "C8D2AA80",
            ["NextDialogue"] = 80220225,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AA80",
            },
        [80220225] = {
            ["Content"] = "汝等飘零人渴求无拘，却不知鸢无线而坠，川无堤不海。",
            ["ContentJP"] = "流れ者よ。汝は自由を求めて流れ、鎖を<Default note=\"text:いと\">厭</>うてきた。されど、凧は糸なくして天に留まらず。川は<Default note=\"text:つつみ\">堤</>なくして流れを保てぬ。",
            ["DialogueId"] = 80220225,
            ["GUID"] = "C8D2AAAA",
            ["NextDialogue"] = 80220226,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAAA",
            },
        [80220226] = {
            ["Content"] = "往事已矣，来日可期。迷途知返，犹未晚也。",
            ["ContentJP"] = "すべては過ぎ去った。この先がどうなるかは、未だ定まらぬ。\
 たとえ一度道を踏み外そうと、引き返すに遅きことはない。",
            ["DialogueId"] = 80220226,
            ["GUID"] = "C8D2AAD4",
            ["NextDialogue"] = 80220227,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAD4",
            },
        [80220227] = {
            ["Content"] = "言尽于此，汝其慎思。",
            ["ContentJP"] = "吾が言いたいことは、それだけだ。くれぐれも、よく考えよう。",
            ["DialogueId"] = 80220227,
            ["GUID"] = "C8D2AAFE",
            ["NextDialogue"] = 80220228,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AAFE",
            },
        [80220228] = {
            ["Content"] = "太皓的幻影消失在了天际。",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>の幻影が消えた。",
            ["DialogueId"] = 80220228,
            ["GUID"] = "C8D2AB28",
            ["NextDialogue"] = 80220229,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AB28",
            },
        [80220229] = {
            ["Content"] = "呜……",
            ["ContentJP"] = "こんー......。",
            ["DialogueId"] = 80220229,
            ["GUID"] = "C8D2AB52",
            ["NextDialogue"] = 80220230,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AB52",
            },
        [80220230] = {
            ["Content"] = "……你还活着。原来那日，你是逃出了山外山吗……",
            ["ContentJP"] = "お前……生きていたのか。あの日、<Default note=\"text:さんがいさん\">山外山</>から……逃げ切れたのか。",
            ["DialogueId"] = 80220230,
            ["GUID"] = "C8D2AB7C",
            ["NextDialogue"] = 80220231,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AB7C",
            },
        [80220231] = {
            ["Content"] = "呜……呜呜……",
            ["ContentJP"] = "こん……こんこん……。",
            ["DialogueId"] = 80220231,
            ["GUID"] = "C8D2ABA6",
            ["NextDialogue"] = 80220232,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ABA6",
            },
        [80220232] = {
            ["Content"] = "你在哭吗？",
            ["ContentJP"] = "……泣いているのか。",
            ["DialogueId"] = 80220232,
            ["GUID"] = "C8D2ABD0",
            ["NextDialogue"] = 80220233,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ABD0",
            },
        [80220233] = {
            ["Content"] = "是在哭她，哭师父，哭那些无辜的死难者——还是哭竟然心生叛意的我？",
            ["ContentJP"] = "その涙はあいつのためか。師匠のためか。あの件に巻き込まれて死んだ、罪のない者たちのためか……。それとも、裏切り者になろうとする俺のためか。",
            ["DialogueId"] = 80220233,
            ["GUID"] = "C8D2ABFA",
            ["NextDialogue"] = 80220234,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ABFA",
            },
        [80220234] = {
            ["Content"] = "呜呜……",
            ["ContentJP"] = "こん......。",
            ["DialogueId"] = 80220234,
            ["GUID"] = "C8D2AC24",
            ["NextDialogue"] = 80220235,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AC24",
            },
        [80220235] = {
            ["Content"] = "你是打算让我带你回山外山吗？",
            ["ContentJP"] = "一緒に<Default note=\"text:さんがいさん\">山外山</>へ戻りたいのか。",
            ["DialogueId"] = 80220235,
            ["GUID"] = "C8D2AC4E",
            ["NextDialogue"] = 80220236,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AC4E",
            },
        [80220236] = {
            ["Content"] = "呜呜！",
            ["ContentJP"] = "こんこん！",
            ["DialogueId"] = 80220236,
            ["GUID"] = "C8D2AC78",
            ["NextDialogue"] = 80220237,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2AC78",
            },
        [80220237] = {
            ["Content"] = "抱歉，我已经回不去了。",
            ["ContentJP"] = "すまん……もう、帰れないな……",
            ["DialogueId"] = 80220237,
            ["GUID"] = "C8D2ACA2",
            ["NextDialogue"] = 80220238,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ACA2",
            },
        [80220238] = {
            ["Content"] = "（不过……这只已经被驯服了的小野兽，如果不回山外山的话，恐怕是活不下去的。）",
            ["ContentJP"] = "(だが......だが、お前は違う。人に馴れた小さな獣が、外で独りで生きるのは――きつい。）",
            ["DialogueId"] = 80220238,
            ["GUID"] = "C8D2ACCC",
            ["NextDialogue"] = 80220239,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ACCC",
            },
        [80220239] = {
            ["Content"] = "山外山的方向在那边。接下来的路，便由你自己选择吧。",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>は……あっちだ。これから先は、お前が選べ。",
            ["DialogueId"] = 80220239,
            ["GUID"] = "C8D2ACF6",
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/002/C8D2ACF6",
            },
        [80220301] = {
            ["Content"] = "……哈、哈……",
            ["ContentJP"] = "……はぁ、はぁ……。",
            ["DialogueId"] = 80220301,
            ["GUID"] = "C8D2B722",
            ["NextDialogue"] = 80220302,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B722",
            },
        [80220302] = {
            ["Content"] = "在山外山的时候不声不响，当狗倒是挺有本事。",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>じゃ大人しかったくせに……大風九章の犬としての腕は、なかなかのもんだな。",
            ["DialogueId"] = 80220302,
            ["GUID"] = "C8D2B74C",
            ["NextDialogue"] = 80220303,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B74C",
            },
        [80220303] = {
            ["Content"] = "……束手就擒吧。",
            ["ContentJP"] = "……大人しく、縛られろ。",
            ["DialogueId"] = 80220303,
            ["GUID"] = "C8D2B776",
            ["NextDialogue"] = 80220304,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B776",
            },
        [80220304] = {
            ["Content"] = "束手就擒……好一个束手就擒！若旁人不知，怕不是真当我是罪人。",
            ["ContentJP"] = "大人しくしろ、だぁ？よくそんな口が利けるな。真実を知らなきゃ、俺は本当に罪人扱いで終わりだ。",
            ["DialogueId"] = 80220304,
            ["GUID"] = "C8D2B7A0",
            ["NextDialogue"] = 80220305,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B7A0",
            },
        [80220305] = {
            ["Content"] = "你已犯戕身害命之罪，自为罪人，就此悔过才是正途。",
            ["ContentJP"] = "「身を<Default note=\"text:そこな\">戕</>い、命を奪うこと、為すべからず。」貴様はすでに罪を犯した。……反省しろ。",
            ["DialogueId"] = 80220305,
            ["GUID"] = "C8D2B7CA",
            ["NextDialogue"] = 80220306,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B7CA",
            },
        [80220306] = {
            ["Content"] = "悔过？可笑！那老贼曲解契约，坑害劳苦欺压邻里，我不过是替天行道。",
            ["ContentJP"] = "反省？笑わせるな。あの老いぼれの外道め……契約を捻じ曲げて人を騙し、弱い者を食い物にしやがった。俺はただ――天に代わって、天誅を下しただけだ。",
            ["DialogueId"] = 80220306,
            ["GUID"] = "C8D2B7F4",
            ["NextDialogue"] = 80220307,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B7F4",
            },
        [80220307] = {
            ["Content"] = "僭权徇私，无可谓替天行道。天道既存，无需凡人替之。",
            ["ContentJP"] = "貴様は己のために刃を振るっただけだ。「天に代わる」などと言えるはずがない。天道がある以上、人が代わりを務める必要はない。",
            ["DialogueId"] = 80220307,
            ["GUID"] = "C8D2B81E",
            ["NextDialogue"] = 80220308,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B81E",
            },
        [80220308] = {
            ["Content"] = "天道既存？呸！我倒要问问，那老贼靠一纸阴阳契诈取钱财，害得无数人倾家荡产时，你的天道又在哪里？大风九章又在哪里？",
            ["ContentJP"] = "天道があるって言うなら、出てこいな。おい！答えろ。あいつが偽りの契約で金を巻き上げ、いくつの家を潰した。その時、天道はどこにいた。<Default note=\"text:たいふうきゅうしょう\">大風九章</>はどこにいたんだ！",
            ["DialogueId"] = 80220308,
            ["GUID"] = "C8D2B848",
            ["NextDialogue"] = 80220309,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B848",
            },
        [80220309] = {
            ["Content"] = "大风九章非一蹴而就，也非不可更改。这等恶性当如何裁断，太皓神君自有定夺，不容你我僭越。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>は一夜で成るものではない。だが、永遠に変わらぬものでもない。善悪をどう裁くかは、上の沙汰だ。身の程を知れ！",
            ["DialogueId"] = 80220309,
            ["GUID"] = "C8D2B872",
            ["NextDialogue"] = 80220310,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B872",
            },
        [80220310] = {
            ["Content"] = "……哈，冠冕堂皇。来吧，那就让我领教一番你这应天尉的本事！",
            ["ContentJP"] = "……はっ。講釈はいい。来い。<Default note=\"text:おうてんい\">応天尉</>の実力とやら、見せてもらおうじゃねぇか！",
            ["DialogueId"] = 80220310,
            ["GUID"] = "C8D2B89C",
            ["NextDialogue"] = 80220311,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B89C",
            },
        [80220311] = {
            ["Content"] = "煜明与飘零人兵刃相向。飘零人没几招就败下阵来。\
长枪刺向飘零人，却未刺破他的胸膛——\
而一枚断成两截的玉带钩，从他的胸前掉落。",
            ["ContentJP"] = "刃を交え、流れ者は数合で崩れ落ちた。 槍先は胸元に突き立ったが、致命には至らない。 代わりに、二つに割れた翡翠のベルトフックが流れ者の胸元から転がり落ちる。",
            ["DialogueId"] = 80220311,
            ["GUID"] = "C8D2B8C6",
            ["NextDialogue"] = 80220312,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B8C6",
            },
        [80220312] = {
            ["Content"] = "那是……师父的……",
            ["ContentJP"] = "……あれは。師匠の……？",
            ["DialogueId"] = 80220312,
            ["GUID"] = "C8D2B8F0",
            ["NextDialogue"] = 80220313,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B8F0",
            },
        [80220313] = {
            ["Content"] = "那日不夏秽蚀，他为掩护大家逃离而辞世。而我在血泊里捡起了他留下的这枚玉带钩。",
            ["ContentJP"] = "フウカが穢蝕者になったあの日、師匠は皆を逃がすために死んだ。俺は血だまりの中に落ちてたそれを拾った。",
            ["DialogueId"] = 80220313,
            ["GUID"] = "C8D2B91A",
            ["NextDialogue"] = 80220314,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B91A",
            },
        [80220314] = {
            ["Content"] = "我将它小心翼翼地粘在一起，想留个念想……结果……该碎的东西还是要碎的。",
            ["ContentJP"] = "形見にしたくて、割れ目まで丁寧に繋ぎ直した。……だがな。一度壊れたもんは、結局また壊れる。まさに因果ってやつだ。",
            ["DialogueId"] = 80220314,
            ["GUID"] = "C8D2B944",
            ["NextDialogue"] = 80220315,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B944",
            },
        [80220315] = {
            ["Content"] = "飘零人无人不敬宴山亭，他告诉大家什么是恣意，什么是无拘，什么是虽千万人吾往矣，什么是一诺千金。",
            ["ContentJP"] = "流れ者は皆、宴山亭先生のことを慕ってた。先生は俺たちに「自由」の道を示した。本当の勇気と……約束を守る重さも、叩き込んでくれた。",
            ["DialogueId"] = 80220315,
            ["GUID"] = "C8D2B96E",
            ["NextDialogue"] = 80220316,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B96E",
            },
        [80220316] = {
            ["Content"] = "但你呢？应天尉大人，他昔日的爱徒——竟选择背弃飘零人，向那条破龙摇尾乞怜！",
            ["ContentJP"] = "それなのに、お前はどうだ、<Default note=\"text:おうてんい\">応天尉</>殿、宴山亭先生の愛弟子だったんだろ。......よくも皆を裏切り、あの邪竜に尻尾を振りやがる。施しでも貰って、生き延びてんのかよ。",
            ["DialogueId"] = 80220316,
            ["GUID"] = "C8D2B998",
            ["NextDialogue"] = 80220317,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B998",
            },
        [80220317] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80220317,
            ["GUID"] = "C8D2B9C2",
            ["NextDialogue"] = 80220318,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B9C2",
            },
        [80220318] = {
            ["Content"] = "……你走吧。你既接下这一枪，便是上天要你命不该绝。",
            ["ContentJP"] = "......行け。その一撃を受け止めた以上、貴様がここで死なぬのは――天の意思だ。",
            ["DialogueId"] = 80220318,
            ["GUID"] = "C8D2B9EC",
            ["NextDialogue"] = 80220319,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2B9EC",
            },
        [80220319] = {
            ["Content"] = "……哼。",
            ["ContentJP"] = "……ふん。",
            ["DialogueId"] = 80220319,
            ["GUID"] = "C8D2BA16",
            ["NextDialogue"] = 80220320,
            ["SpeakNpcId"] = 790075,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA16",
            },
        [80220320] = {
            ["Content"] = "飘零人瞪了煜明一眼，转头奔去，直到消失在煜明的视线之外……",
            ["ContentJP"] = "流れ者はユーミンを睨みつけて、顔を向けた。ユーミンの視界から消えていく・・・・・・",
            ["DialogueId"] = 80220320,
            ["GUID"] = "C8D2BA40",
            ["NextDialogue"] = 80220321,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA40",
            },
        [80220321] = {
            ["Content"] = "——本应如此。",
            ["ContentJP"] = "――そのはずだった。",
            ["DialogueId"] = 80220321,
            ["GUID"] = "C8D2BA6A",
            ["NextDialogue"] = 80220322,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA6A",
            },
        [80220322] = {
            ["Content"] = "但身后忽地有鼓鼓烈风吹来。未及煜明反应，飘零人已无气息。",
            ["ContentJP"] = "突然、彼の背後で疾風が吹き荒れる。ユーミンが反応する前に、流れ者はすでに息絶えていた。",
            ["DialogueId"] = 80220322,
            ["GUID"] = "C8D2BA94",
            ["NextDialogue"] = 80220323,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BA94",
            },
        [80220323] = {
            ["Content"] = "不知何时从身后赶来的狴犴以利爪贯穿了飘零人的胸口。",
            ["ContentJP"] = "いつの間にか背後からやってきた狴犴が、流れ者の胸に鋭い爪を走らせた。",
            ["DialogueId"] = 80220323,
            ["GUID"] = "C8D2BABE",
            ["NextDialogue"] = 80220324,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BABE",
            },
        [80220324] = {
            ["Content"] = "吼——",
            ["ContentJP"] = "グオォォ……！",
            ["DialogueId"] = 80220324,
            ["GUID"] = "C8D2BAE8",
            ["NextDialogue"] = 80220325,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BAE8",
            },
        [80220325] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80220325,
            ["GUID"] = "C8D2BB12",
            ["NextDialogue"] = 80220326,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB12",
            },
        [80220326] = {
            ["Content"] = "煜明。",
            ["ContentJP"] = "ユーミン……。",
            ["DialogueId"] = 80220326,
            ["GUID"] = "C8D2BB3C",
            ["NextDialogue"] = 80220327,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB3C",
            },
        [80220327] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80220327,
            ["GUID"] = "C8D2BB66",
            ["NextDialogue"] = 80220328,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB66",
            },
        [80220328] = {
            ["Content"] = "师父……",
            ["ContentJP"] = "……師匠。",
            ["DialogueId"] = 80220328,
            ["GUID"] = "C8D2BB90",
            ["NextDialogue"] = 80220329,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BB90",
            },
        [80220329] = {
            ["Content"] = "煜明，你又长高了，也长壮了。",
            ["ContentJP"] = "ユーミン、随分と立派になったな。背も伸びた。",
            ["DialogueId"] = 80220329,
            ["GUID"] = "C8D2BBBA",
            ["NextDialogue"] = 80220330,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BBBA",
            },
        [80220330] = {
            ["Content"] = "师父，我很多年前就不长个子了。",
            ["ContentJP"] = "私の身長は、何年も前から止まりました。",
            ["DialogueId"] = 80220330,
            ["GUID"] = "C8D2BBE4",
            ["NextDialogue"] = 80220331,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BBE4",
            },
        [80220331] = {
            ["Content"] = "你这个孽徒！师父我好不容易想说句肉麻一点的开场白，你就在这里拆台。",
            ["ContentJP"] = "こら、小僧。……せっかく感動的な出だしを用意したんだ、少しは付き合え。",
            ["DialogueId"] = 80220331,
            ["GUID"] = "C8D2BC0E",
            ["NextDialogue"] = 80220332,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC0E",
            },
        [80220332] = {
            ["Content"] = "你怎么了？一脸苦相，又在发愁？",
            ["ContentJP"] = "どうした。随分と苦しそうな顔をしている。また何を抱え込んでるのか。",
            ["DialogueId"] = 80220332,
            ["GUID"] = "C8D2BC38",
            ["NextDialogue"] = 80220333,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC38",
            },
        [80220333] = {
            ["Content"] = "……没有……",
            ["ContentJP"] = "……いえ。",
            ["DialogueId"] = 80220333,
            ["GUID"] = "C8D2BC62",
            ["NextDialogue"] = 80220334,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC62",
            },
        [80220334] = {
            ["Content"] = "扯谎。说过多少次了，你这孩子，一说谎就两个字两个字往外蹦。",
            ["ContentJP"] = "こら、また嘘をついたな。何度も言っただろう。お前は嘘をつくと、一言しか出てこなくなる。",
            ["DialogueId"] = 80220334,
            ["GUID"] = "C8D2BC8C",
            ["NextDialogue"] = 80220335,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BC8C",
            },
        [80220335] = {
            ["Content"] = "师父，您是来训斥徒儿的吗？",
            ["ContentJP"] = "師匠は、私を叱りに来られたのですか。",
            ["DialogueId"] = 80220335,
            ["GUID"] = "C8D2BCB6",
            ["NextDialogue"] = 80220336,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BCB6",
            },
        [80220336] = {
            ["Content"] = "徒儿辜负了您的期待，与昔日旧友兵刃相向。",
            ["ContentJP"] = "私は師匠のご期待を裏切り、かつての友にまで刃を向けました。",
            ["DialogueId"] = 80220336,
            ["GUID"] = "C8D2BCE0",
            ["NextDialogue"] = 80220337,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BCE0",
            },
        [80220337] = {
            ["Content"] = "我背叛了您，背弃了飘零人，皈依了大风九章。如今，我已无面目见您。",
            ["ContentJP"] = "私は……師匠と流れ者たちを裏切って、<Default note=\"text:たいふうきゅうしょう\">大風九章</>に寝返りました。今さら、師匠にお会いできる顔などございません。",
            ["DialogueId"] = 80220337,
            ["GUID"] = "C8D2BD0A",
            ["NextDialogue"] = 80220338,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD0A",
            },
        [80220338] = {
            ["Content"] = "死脑筋。我宴山亭聪明一世，怎就教出来你这块榆木疙瘩。",
            ["ContentJP"] = "大馬鹿者。お前はこの宴山亭の弟子だというのに、その頑固さはいったい誰に似た。",
            ["DialogueId"] = 80220338,
            ["GUID"] = "C8D2BD34",
            ["NextDialogue"] = 80220339,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD34",
            },
        [80220339] = {
            ["Content"] = "徒儿愚钝。",
            ["ContentJP"] = "……申し訳ありません。",
            ["DialogueId"] = 80220339,
            ["GUID"] = "C8D2BD5E",
            ["NextDialogue"] = 80220340,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD5E",
            },
        [80220340] = {
            ["Content"] = "我只问你一句，你可曾后悔过？",
            ["ContentJP"] = "一つだけ聞こう。……後悔したことはあるか。",
            ["DialogueId"] = 80220340,
            ["GUID"] = "C8D2BD88",
            ["NextDialogue"] = 80220341,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BD88",
            },
        [80220341] = {
            ["Content"] = "煜明……不知。",
            ["ContentJP"] = "私には……分かりません。",
            ["DialogueId"] = 80220341,
            ["GUID"] = "C8D2BDB2",
            ["NextDialogue"] = 80220342,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BDB2",
            },
        [80220342] = {
            ["Content"] = "那为师换个问法，若往日再起，你是否还会像当初那样成为应天尉？",
            ["ContentJP"] = "……いや、聞き方を変える。もしあの日に戻れるとして――それでも同じ選択をするか。",
            ["DialogueId"] = 80220342,
            ["GUID"] = "C8D2BDDC",
            ["NextDialogue"] = 80220343,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BDDC",
            },
        [80220343] = {
            ["Content"] = "……会。",
            ["ContentJP"] = "…………します。",
            ["DialogueId"] = 80220343,
            ["GUID"] = "C8D2BE06",
            ["NextDialogue"] = 80220344,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE06",
            },
        [80220344] = {
            ["Content"] = "为何？",
            ["ContentJP"] = "理由は？",
            ["DialogueId"] = 80220344,
            ["GUID"] = "C8D2BE30",
            ["NextDialogue"] = 80220345,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE30",
            },
        [80220345] = {
            ["Content"] = "大风九章之下，我们失去了洒脱，失去了快意恩仇，失去了一部分正义。可……<H>坏的规则也好过没有规则</>。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>の下で、私たちは洒脱も自由も失いました。正義も……いくらか削れました。ですが、<H>悪い掟でも――無いよりはまし</>です。",
            ["DialogueId"] = 80220345,
            ["GUID"] = "C8D2BE5A",
            ["NextDialogue"] = 80220346,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE5A",
            },
        [80220346] = {
            ["Content"] = "若无大风九章，世道失序，人间只会变得更糟。纵有飘零人惩恶扬善，也不过杯水车薪。",
            ["ContentJP"] = "大風九章が無ければ、世は秩序を失い、崩れていく一方だ。たとえ悪を討ち、善を掲げる流れ者がいたとしても……焼け石に水にすぎません。",
            ["DialogueId"] = 80220346,
            ["GUID"] = "C8D2BE84",
            ["NextDialogue"] = 80220347,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BE84",
            },
        [80220347] = {
            ["Content"] = "更何况，我已不想再看到不夏的事情重演一次。",
            ["ContentJP"] = "それに……フウカのことは、もう二度と繰り返したくありません。",
            ["DialogueId"] = 80220347,
            ["GUID"] = "C8D2BEAE",
            ["NextDialogue"] = 80220348,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BEAE",
            },
        [80220348] = {
            ["Content"] = "……我不想再有下一位大英雄宴山亭死去了。",
            ["ContentJP"] = "また一人、「大英雄宴山亭」が死ぬのを……見たくありません。",
            ["DialogueId"] = 80220348,
            ["GUID"] = "C8D2BED8",
            ["NextDialogue"] = 80220349,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BED8",
            },
        [80220349] = {
            ["Content"] = "哈哈……哈哈！你既已遵循本心，又何须多言。纵然身不由己，但若让你重来一世仍会坚持曾经的抉择，旁人又说得什么？",
            ["ContentJP"] = "……はは。はははは……。そうか。お前はもう、本心に従っている。なら、わしが言うことはない。世の中にはな、思うままにならぬことが山ほどある。だが、たとえやり直す機会があったとしても――お前はきっと、また同じ道を選ぶ。……そういう男だ。",
            ["DialogueId"] = 80220349,
            ["GUID"] = "C8D2BF02",
            ["NextDialogue"] = 80220350,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF02",
            },
        [80220350] = {
            ["Content"] = "哪怕如今的我已与曾经的师父势不两立？",
            ["ContentJP"] = "……師匠と真逆の道を歩んでも、ですか。",
            ["DialogueId"] = 80220350,
            ["GUID"] = "C8D2BF2C",
            ["NextDialogue"] = 80220351,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF2C",
            },
        [80220351] = {
            ["Content"] = "垂髫尊父母，弱冠循师长，不惑事权贵，耳顺系子女。可若人的一生如此遵从他人所制定好的路途，不曾自己做出选择，又怎么说是活过。",
            ["ContentJP"] = "人はな、幼い頃は親を敬い、二十の頃は師に従い、四十を過ぎれば、金と権力のために働き、六十を越えれば、家のまとめ役になる。……世の理屈はそうだ。けれども、そうして他人の決めた道をなぞるだけなら、人はいつ「自分の人生を生きた」と言えるのだろうな。",
            ["DialogueId"] = 80220351,
            ["GUID"] = "C8D2BF56",
            ["NextDialogue"] = 80220352,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF56",
            },
        [80220352] = {
            ["Content"] = "为师从来只教你<H>行无悔之事</>，可从未教过你跟在师父后面亦步亦趋，做那跟屁虫。",
            ["ContentJP"] = "わしが教えたのは「<H>悔いなき選択をせよ</>」だ。「黙ってわしに従え」「腰巾着みたいにくっついていろ」などとは、教えた覚えはないぞ。",
            ["DialogueId"] = 80220352,
            ["GUID"] = "C8D2BF80",
            ["NextDialogue"] = 80220353,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BF80",
            },
        [80220353] = {
            ["Content"] = "煜明，你可记得我为何要反抗大风九章？",
            ["ContentJP"] = "ユーミン、わしが大風九章に刃向かった理由は、覚えているか。",
            ["DialogueId"] = 80220353,
            ["GUID"] = "C8D2BFAA",
            ["NextDialogue"] = 80220354,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BFAA",
            },
        [80220354] = {
            ["Content"] = "为了不让世人困于囚笼，永无自立之本？",
            ["ContentJP"] = "人が檻に閉じ込められ、自分の足で前に進めなくなる未来を……避けるために。",
            ["DialogueId"] = 80220354,
            ["GUID"] = "C8D2BFD4",
            ["NextDialogue"] = 80220355,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BFD4",
            },
        [80220355] = {
            ["Content"] = "不，是为了在天道之外，夺取<H>另一种选择的权利</>。",
            ["ContentJP"] = "いや、「天道」などに縋らずとも、<H>別の道を選べる権利</>――そのためだ。",
            ["DialogueId"] = 80220355,
            ["GUID"] = "C8D2BFFE",
            ["NextDialogue"] = 80220356,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2BFFE",
            },
        [80220356] = {
            ["Content"] = "山外山虽与大风九章为敌，却向来任意来去。这是因为飘零人应当是人生的另一种可能，而不应成为另一个樊笼。",
            ["ContentJP"] = "山外山は大風九章の敵でもあるが、いつでも出入りできる場所だ。なぜなら、流れ者とは、人生の「もう一つの道」であるべきなんだ。……もう一つの檻になってはならん。",
            ["DialogueId"] = 80220356,
            ["GUID"] = "C8D2C028",
            ["NextDialogue"] = 80220357,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C028",
            },
        [80220357] = {
            ["Content"] = "不要再惩罚自己了，煜明。因为……",
            ["ContentJP"] = "自分を責め続けるのは、もうやめろ、ユーミン……なぜなら。",
            ["DialogueId"] = 80220357,
            ["GUID"] = "C8D2C052",
            ["NextDialogue"] = 80220358,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C052",
            },
        [80220358] = {
            ["Content"] = "你是我的骄傲。",
            ["ContentJP"] = "お前は――わしの自慢の弟子だ。",
            ["DialogueId"] = 80220358,
            ["GUID"] = "C8D2C07C",
            ["NextDialogue"] = 80220359,
            ["SpeakNpcId"] = 790074,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C07C",
            },
        [80220359] = {
            ["Content"] = "师父……",
            ["ContentJP"] = "……師匠。",
            ["DialogueId"] = 80220359,
            ["GUID"] = "C8D2C0A6",
            ["NextDialogue"] = 80220360,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C0A6",
            },
        [80220360] = {
            ["Content"] = "徒儿……谨遵教诲！",
            ["ContentJP"] = "ご教示、肝に銘じます。",
            ["DialogueId"] = 80220360,
            ["GUID"] = "C8D2C0D0",
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/003/C8D2C0D0",
            },
        [80220401] = {
            ["Content"] = "煜明？是你在吹奏吗？",
            ["ContentJP"] = "ユーミン？笛を吹いてたのは、{性别:あなたか|あなたなの}？",
            ["DialogueId"] = 80220401,
            ["GUID"] = "C8D2C78A",
            ["NextDialogue"] = 80220402,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C78A",
            },
        [80220402] = {
            ["Content"] = "{nickname}……别来无恙。",
            ["ContentJP"] = "{nickname}……久しぶりだ。",
            ["DialogueId"] = 80220402,
            ["GUID"] = "C8D2C7B4",
            ["NextDialogue"] = 80220403,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C7B4",
            },
        [80220403] = {
            ["Content"] = "没想到你还会这一手，以前从来没见过。",
            ["ContentJP"] = "笛、吹けたんだね。そんなの、今まで見たことなかったよ。",
            ["DialogueId"] = 80220403,
            ["GUID"] = "C8D2C7DE",
            ["NextDialogue"] = 80220404,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C7DE",
            },
        [80220404] = {
            ["Content"] = "虽未能为所有百姓排忧解难，倒也确实事务繁忙，无暇抽身。",
            ["ContentJP"] = "全部片付いたわけじゃないが……この前は立て込んでいて、こういうことをする暇もなかった。",
            ["DialogueId"] = 80220404,
            ["GUID"] = "C8D2C808",
            ["NextDialogue"] = 80220405,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C808",
            },
        [80220405] = {
            ["Content"] = "如今烛阴归位，辩法回归，人神共治，我等太皓代行之人反倒落得清闲。",
            ["ContentJP"] = "今は燭陰もお戻りになって、裁定の儀も再開した。神と人が並び立つ世になった今……俺たち<Default note=\"text:たいこう\">太皓</>の執行者は、暇になったな。",
            ["DialogueId"] = 80220405,
            ["GUID"] = "C8D2C832",
            ["NextDialogue"] = 80220406,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C832",
            },
        [80220406] = {
            ["Content"] = "怎么听起来好像有些落寞……",
            ["ContentJP"] = "なんか……ちょっと寂しそう。",
            ["DialogueId"] = 80220406,
            ["GUID"] = "C8D2C85C",
            ["NextDialogue"] = 80220407,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C85C",
            },
        [80220407] = {
            ["Content"] = "见笑了。",
            ["ContentJP"] = "……すまん。みっともないところを見せた。",
            ["DialogueId"] = 80220407,
            ["GUID"] = "C8D2C886",
            ["NextDialogue"] = 80220408,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C886",
            },
        [80220408] = {
            ["Content"] = "山外山……算是你的故乡吧。",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>……そこがユーミンの故郷、だったよね。",
            ["DialogueId"] = 80220408,
            ["GUID"] = "C8D2C8B0",
            ["NextDialogue"] = 80220409,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C8B0",
            },
        [80220409] = {
            ["Content"] = "你是打算回去看看他们？",
            ["ContentJP"] = "みんなのところに、戻ろうと思ってた{性别:|の}？",
            ["DialogueId"] = 80220409,
            ["GUID"] = "C8D2C8DA",
            ["NextDialogue"] = 80220410,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C8DA",
            },
        [80220410] = {
            ["Content"] = "……并未。",
            ["ContentJP"] = "......いや。",
            ["DialogueId"] = 80220410,
            ["GUID"] = "C8D2C904",
            ["NextDialogue"] = 80220411,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C904",
            },
        [80220411] = {
            ["Content"] = "我……只是路过。我为应天尉太久，与他们早已殊途。",
            ["ContentJP"] = "俺はただ……通りがかっただけだ。長く<Default note=\"text:おうてんい\">応天尉</>をやったせいで、<Default note=\"text:さんがいさん\">山外山</>の連中とは――もう袂を分かっている。",
            ["DialogueId"] = 80220411,
            ["GUID"] = "C8D2C92E",
            ["NextDialogue"] = 80220412,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C92E",
            },
        [80220412] = {
            ["Content"] = "比赛一事，我已完成止流嘱托，往后便不再见了吧。",
            ["ContentJP"] = "試合の件について、シリュウ当主の依頼も終わった。……この先、会うこともないだろう。",
            ["DialogueId"] = 80220412,
            ["GUID"] = "C8D2C958",
            ["NextDialogue"] = 80220413,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C958",
            },
        [80220413] = {
            ["Content"] = "那真是太可惜了。我来找你，原本是刻舟让我给你带个话——",
            ["ContentJP"] = "そっか……残念。カシュウに頼まれて、伝言を届けに来たんだけど――",
            ["DialogueId"] = 80220413,
            ["GUID"] = "C8D2C982",
            ["NextDialogue"] = 80220414,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C982",
            },
        [80220414] = {
            ["Content"] = "他说什么？",
            ["ContentJP"] = "あいつは、何て言った？",
            ["DialogueId"] = 80220414,
            ["GUID"] = "C8D2C9AC",
            ["NextDialogue"] = 80220415,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C9AC",
            },
        [80220415] = {
            ["Content"] = "你看，这不是还是很关心山外山的人们嘛。",
            ["ContentJP"] = "ほら。やっぱり、気にしてるんじゃない。",
            ["DialogueId"] = 80220415,
            ["GUID"] = "C8D2C9D6",
            ["NextDialogue"] = 80220416,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2C9D6",
            },
        [80220416] = {
            ["Content"] = "…………！",
            ["ContentJP"] = "…………！",
            ["DialogueId"] = 80220416,
            ["GUID"] = "C8D2CA00",
            ["NextDialogue"] = 80220417,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA00",
            },
        [80220417] = {
            ["Content"] = "呵呵。",
            ["ContentJP"] = "……はは。",
            ["DialogueId"] = 80220417,
            ["GUID"] = "C8D2CA2A",
            ["NextDialogue"] = 80220418,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA2A",
            },
        [80220418] = {
            ["Content"] = "你笑了？这在你们华胥好像是叫什么——铁做的木头也会开花？",
            ["ContentJP"] = "笑った。珍しいね。ここの言い方だと――「鉄木にも花が咲く」……だっけ？合ってる？",
            ["DialogueId"] = 80220418,
            ["GUID"] = "C8D2CA54",
            ["NextDialogue"] = 80220419,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA54",
            },
        [80220419] = {
            ["Content"] = "我只是觉得，你开起玩笑来像我和刻舟的师父。",
            ["ContentJP"] = "いや、その言い方が――俺とカシュウの師匠に、少し似ていたから。",
            ["DialogueId"] = 80220419,
            ["GUID"] = "C8D2CA7E",
            ["NextDialogue"] = 80220420,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CA7E",
            },
        [80220420] = {
            ["Content"] = "听刻舟说那是个糟老头子。唉，你这究竟算是夸我还是算在阴阳怪气。",
            ["ContentJP"] = "カシュウが「不機嫌な年寄りだった」って言ってたあの師匠{性别:だね|ね}。それって褒めてるの？ それとも、{性别:僕|私}への当てこすり？",
            ["DialogueId"] = 80220420,
            ["GUID"] = "C8D2CAA8",
            ["NextDialogue"] = 80220421,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CAA8",
            },
        [80220421] = {
            ["Content"] = "……{nickname}。",
            ["ContentJP"] = "……{nickname}。",
            ["DialogueId"] = 80220421,
            ["GUID"] = "C8D2CAD2",
            ["NextDialogue"] = 80220422,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CAD2",
            },
        [80220422] = {
            ["Content"] = "怎么了？",
            ["ContentJP"] = "……どうしたの？",
            ["DialogueId"] = 80220422,
            ["GUID"] = "C8D2CAFC",
            ["NextDialogue"] = 80220423,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CAFC",
            },
        [80220423] = {
            ["Content"] = "依你所见，我此前所践行之路，能称之为正确吗？",
            ["ContentJP"] = "{nickname}から見て……俺が歩んできた道は、正しかったと言えるのか。",
            ["DialogueId"] = 80220423,
            ["GUID"] = "C8D2CB26",
            ["NextDialogue"] = 80220424,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CB26",
            },
        [80220424] = {
            ["Content"] = "这个问题……问我？",
            ["ContentJP"] = "え、{性别:僕|私}に聞くの？",
            ["DialogueId"] = 80220424,
            ["GUID"] = "C8D2CB50",
            ["NextDialogue"] = 80220425,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CB50",
            },
        [80220425] = {
            ["Content"] = "的确。",
            ["ContentJP"] = "……そうだな。（軽く笑う）",
            ["DialogueId"] = 80220425,
            ["GUID"] = "C8D2CB7A",
            ["NextDialogue"] = 80220426,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CB7A",
            },
        [80220426] = {
            ["Content"] = "这个问题，你不是早就应该自己得到答案了吗？",
            ["ContentJP"] = "それ、もう自分で分かってるんじゃないかな。",
            ["DialogueId"] = 80220426,
            ["GUID"] = "C8D2CBA4",
            ["NextDialogue"] = 80220427,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CBA4",
            },
        [80220427] = {
            ["Content"] = "师父曾说：前路荒芜，砥砺前行，皆是前人未至之处。",
            ["ContentJP"] = "師匠は、こう言った。「前途は不毛。ゆえにこそ、まだ誰も踏み入れておらぬ」。",
            ["DialogueId"] = 80220427,
            ["GUID"] = "C8D2CBCE",
            ["NextDialogue"] = 80220428,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CBCE",
            },
        [80220428] = {
            ["Content"] = "吾等须一日三省，问天、问人、问心。三省无愧，即是前程。",
            ["ContentJP"] = "「己を省みよ。天に問え、人に問え、心に問え。恥じぬなら――その道に誤りはない」",
            ["DialogueId"] = 80220428,
            ["GUID"] = "C8D2CBF8",
            ["NextDialogue"] = 80220429,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CBF8",
            },
        [80220429] = {
            ["Content"] = "本以为尘埃落定后，又要重新经历这三问，会无比漫长痛苦。就像过去的日子里，不夏、刻舟、师父、太皓……他们的身影总出现在我眼前，令我整夜无眠。",
            ["ContentJP"] = "全部終わったら……俺はまた、昔みたいに自分を責め続けると思っていた。フウカ、カシュウ、師匠、太皓……あいつらの顔が勝手に浮かんで、眠れない夜が続くと。",
            ["DialogueId"] = 80220429,
            ["GUID"] = "C8D2CC22",
            ["NextDialogue"] = 80220430,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CC22",
            },
        [80220430] = {
            ["Content"] = "但当真迈开脚步，反倒也没有如旧日般迷惘了。",
            ["ContentJP"] = "だが……一歩前に踏み出したら、不思議と前ほど迷わなくなった。",
            ["DialogueId"] = 80220430,
            ["GUID"] = "C8D2CC4C",
            ["NextDialogue"] = 80220431,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CC4C",
            },
        [80220431] = {
            ["Content"] = "只是向他人寻求答案的习惯一时半会还没改过来？",
            ["ContentJP"] = "つまり、まだ「誰かに答えをもらう癖」が抜けてないってこと？",
            ["DialogueId"] = 80220431,
            ["GUID"] = "C8D2CC76",
            ["NextDialogue"] = 80220432,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CC76",
            },
        [80220432] = {
            ["Content"] = "经年如此，莫要见怪。",
            ["ContentJP"] = "いつもの癖だ。悪く思わないでくれ。",
            ["DialogueId"] = 80220432,
            ["GUID"] = "C8D2CCA0",
            ["NextDialogue"] = 80220433,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CCA0",
            },
        [80220433] = {
            ["Content"] = "看开一点，连龙神都说要改变了，属于一个人的改变又有什么好奇怪的？",
            ["ContentJP"] = "大丈夫、もう少し前向きに考えよ。あの白龍様だって「変化を受け入れろ」って言ったんじゃない。人は変わるんだ。別に変なことじゃないよ。",
            ["DialogueId"] = 80220433,
            ["GUID"] = "C8D2CCCA",
            ["NextDialogue"] = 80220434,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CCCA",
            },
        [80220434] = {
            ["Content"] = "……说的也是。你说话很像我的师父，让我豁然开朗。",
            ["ContentJP"] = "……確かに。お前の言い方、本当に師匠に似ている。少し、楽になった。",
            ["DialogueId"] = 80220434,
            ["GUID"] = "C8D2CCF4",
            ["NextDialogue"] = 80220435,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CCF4",
            },
        [80220435] = {
            ["Content"] = "说了不要把我比作老头子了。",
            ["ContentJP"] = "ちょっと。言ったでしょ。{性别:僕|私}のこと、年寄り扱いしないで{性别:|よ}。",
            ["DialogueId"] = 80220435,
            ["GUID"] = "C8D2CD1E",
            ["NextDialogue"] = 80220436,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD1E",
            },
        [80220436] = {
            ["Content"] = "呜嗷——",
            ["ContentJP"] = "こん――",
            ["DialogueId"] = 80220436,
            ["GUID"] = "C8D2CD48",
            ["NextDialogue"] = 80220437,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD48",
            },
        [80220437] = {
            ["Content"] = "什么声音……狐狸叫？",
            ["ContentJP"] = "……今のは、キツネ？",
            ["DialogueId"] = 80220437,
            ["GUID"] = "C8D2CD72",
            ["NextDialogue"] = 80220438,
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD72",
            },
        [80220438] = {
            ["Content"] = "……是你？小橙子？！",
            ["ContentJP"] = "......お前か。ミカン……？",
            ["DialogueId"] = 80220438,
            ["GUID"] = "C8D2CD9C",
            ["NextDialogue"] = 80220439,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CD9C",
            },
        [80220439] = {
            ["Content"] = "嗷嗷——嗷呜！",
            ["ContentJP"] = "こんこん！",
            ["DialogueId"] = 80220439,
            ["GUID"] = "C8D2CDC6",
            ["NextDialogue"] = 80220440,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CDC6",
            },
        [80220440] = {
            ["Content"] = "你没有回山外山。还有，你还活着。",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>へ戻らなかったのか。……それに、生きていたんだな。",
            ["DialogueId"] = 80220440,
            ["GUID"] = "C8D2CDF0",
            ["NextDialogue"] = 80220441,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CDF0",
            },
        [80220441] = {
            ["Content"] = "嗷呜！",
            ["ContentJP"] = "こんこん！",
            ["DialogueId"] = 80220441,
            ["GUID"] = "C8D2CE1A",
            ["NextDialogue"] = 80220442,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE1A",
            },
        [80220442] = {
            ["Content"] = "你已经长得这么大了，也比过去精神得多。当年我以为，如果你不回山外山，一定会冻死饿死在野外……看来竟是我想错了。",
            ["ContentJP"] = "……まさか、ここまで大きくなるとは。前よりずっと、元気そうだ。あの頃は……お前が<Default note=\"text:さんがいさん\">山外山</>に戻らなければ、凍えて飢えて死ぬだろうと思っていた。……結局、俺の見立てが間違っていたらしい。",
            ["DialogueId"] = 80220442,
            ["GUID"] = "C8D2CE44",
            ["NextDialogue"] = 80220443,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE44",
            },
        [80220443] = {
            ["Content"] = "生命每个选择得到的结果，原是无定数的。一切，都要自己走上那条路后方才知晓。",
            ["ContentJP"] = "……なるほどな。選択の結果は、いつだって確かじゃない。この先の景色は――その道を歩んだらこそ見えるんだ。",
            ["DialogueId"] = 80220443,
            ["GUID"] = "C8D2CE6E",
            ["NextDialogue"] = 80220444,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE6E",
            },
        [80220444] = {
            ["Content"] = "嗷呜！嗷呜！",
            ["ContentJP"] = "こん……こんこん……。",
            ["DialogueId"] = 80220444,
            ["GUID"] = "C8D2CE98",
            ["NextDialogue"] = 80220445,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CE98",
            },
        [80220445] = {
            ["Content"] = "那是山外山的方向。你是想喊我一起回去看看？",
            ["ContentJP"] = "あっちは<Default note=\"text:さんがいさん\">山外山</>だ。……一緒に戻りたいと、言ってるのか。",
            ["DialogueId"] = 80220445,
            ["GUID"] = "C8D2CEC2",
            ["NextDialogue"] = 80220446,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CEC2",
            },
        [80220446] = {
            ["Content"] = "嗷呜！",
            ["ContentJP"] = "こんこん！",
            ["DialogueId"] = 80220446,
            ["GUID"] = "C8D2CEEC",
            ["NextDialogue"] = 80220447,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CEEC",
            },
        [80220447] = {
            ["Content"] = "……我明白了。那么，{nickname}，后会有期。",
            ["ContentJP"] = "……わかった。では、{nickname}、またいつの日か会おう。",
            ["DialogueId"] = 80220447,
            ["GUID"] = "C8D2CF16",
            ["NextDialogue"] = 80220448,
            ["SpeakNpcId"] = 790072,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CF16",
            },
        [80220448] = {
            ["Content"] = "去吧，他们在等你。",
            ["ContentJP"] = "いってらっしゃい。<Default note=\"text:さんがいさん\">山外山</>のみんな、あなたの帰りを待ってるよ。",
            ["DialogueId"] = 80220448,
            ["GUID"] = "C8D2CF40",
            ["SpeakNpcId"] = 790008,
            ["VoiceName"] = "voice/$Locale$/inv/Yuming/004/C8D2CF40",
            },
        [80230101] = {
            ["Content"] = "龙渊上卿拔擢仪式即刻开始——诸位受太皓青睐者，请依序入觐——",
            ["ContentJP"] = "<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>の叙任の儀、まもなく執り行われる。<Default note=\"text:たいこう\">太皓</>の<Default note=\"text:みこころ\">御心</>に選ばれし者たちよ——いま一度、秩序をもって御前へ。",
            ["DialogueId"] = 80230101,
            ["GUID"] = "C8D8FEF2",
            ["NextDialogue"] = 80230102,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FEF2",
            },
        [80230102] = {
            ["DialogueId"] = 80230102,
            ["GUID"] = "C8D8FF1C",
            ["NextDialogue"] = 80230103,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF1C",
            },
        [80230103] = {
            ["Content"] = "我乃现任龙渊上卿，目前协理天礼司。今日代行太皓旨意，特来考教诸君气量、心智与觉悟。",
            ["ContentJP"] = "私は、現任の<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>にして、<Default note=\"text:てんれいし\">天礼司</>を補佐する身——本日は<Default note=\"text:たいこう\">太皓</>の<Default note=\"text:ぎょし\">御旨</>を預かり、そなたらの器量、叡智、そして覚悟を見定めに参じた。",
            ["DialogueId"] = 80230103,
            ["GUID"] = "C8D8FF46",
            ["NextDialogue"] = 80230104,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF46",
            },
        [80230104] = {
            ["Content"] = "今日于执律阁内，我等一举一动，一言一行，都将由祂见证。纤毫必现，心念亦无可隐遁。",
            ["ContentJP"] = "ここ<Default note=\"text:しつりつかく\">執律閣</>において、我らの<Default note=\"text:いっきょしゅいっとうそく\">一挙手一投足</>、吐く<Default note=\"text:いちごんいっく\">一言一句</>すら、あまねく「あのお方」の御目に映る。微細すら逃れず、心のうちまでも見透かされよう。",
            ["DialogueId"] = 80230104,
            ["GUID"] = "C8D8FF70",
            ["NextDialogue"] = 80230105,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF70",
            },
        [80230105] = {
            ["Content"] = "最终裁决非我所能定夺。唯有太皓之神意，方能决断谁人有资格承此重任。",
            ["ContentJP"] = "最終の裁きは、我が手にあらず。誰がこの重き位を継ぐにふさわしきか、それを定めるは<Default note=\"text:たいこう\">太皓</>の神意のみ。",
            ["DialogueId"] = 80230105,
            ["GUID"] = "C8D8FF9A",
            ["NextDialogue"] = 80230106,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FF9A",
            },
        [80230106] = {
            ["Content"] = "望诸君谨记此间神圣，摒除杂念，以尔等本心与真知应对考问。现在，仪式开始——",
            ["ContentJP"] = "そなたらに望むは、ただひとつ——この場の神聖を胸に刻み、雑念を払い、本心と真知をもって問いに臨むこと。……では、儀式を始めよう。",
            ["DialogueId"] = 80230106,
            ["GUID"] = "C8D8FFC4",
            ["NextDialogue"] = 80230107,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FFC4",
            },
        [80230107] = {
            ["Content"] = "上前来。先介绍一下自己吧，家住何处，姓甚名谁？",
            ["ContentJP"] = "前へ出なさい。まずは名乗りを——いずこに住まう？",
            ["DialogueId"] = 80230107,
            ["GUID"] = "C8D8FFEE",
            ["NextDialogue"] = 80230108,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D8FFEE",
            },
        [80230108] = {
            ["Content"] = "回大人，我名顾砚，乃本地人士，祖上数代都长居皓京脚下的椒兰村中。",
            ["ContentJP"] = "恐れながら申し上げます。私はコエンと申します。郷里は<Default note=\"text:こうけい\">皓京</>の<Default note=\"text:ふもと\">麓</>に広がるショウラン村、代々この地に暮らして参りました。",
            ["DialogueId"] = 80230108,
            ["GUID"] = "C8D90018",
            ["NextDialogue"] = 80230109,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90018",
            },
        [80230109] = {
            ["Content"] = "不必这么拘谨。龙渊上卿的吉兆降于你身时，你的家人想必高兴得紧吧？",
            ["ContentJP"] = "それほどかしこまらずともよい。<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>の<Default note=\"text:ずいちょう\">瑞兆</>がそなたに降りしとき、ご家族はさぞ喜ばれたであろう？",
            ["DialogueId"] = 80230109,
            ["GUID"] = "C8D90042",
            ["NextDialogue"] = 80230110,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90042",
            },
        [80230110] = {
            ["Content"] = "那是当然！狴犴刚衔着吉讯到来时，家母她老人家还没想到会发生什么。等她后知后觉反应过来顾家竟然要出一位龙渊上卿了，高兴得差点昏厥过去。",
            ["ContentJP"] = "ええ、まさしくその通りです！<Default note=\"text:ビーアン\">狴犴</>が<Default note=\"text:きっちょう\">吉兆</>をくわえて現れたとき、母はまだ事の重大さに気づいておらず……我が家から<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>が出ると悟った瞬間には、喜びのあまり卒倒しかけたほどでして。",
            ["DialogueId"] = 80230110,
            ["GUID"] = "C8D9006C",
            ["NextDialogue"] = 80230111,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9006C",
            },
        [80230111] = {
            ["Content"] = "事后，家母把那日飘落的香花都一瓣瓣拾了起来，精心装裱，说要作为之后子子孙孙的传家宝供起来呢。",
            ["ContentJP"] = "それからというもの、母はその日に舞い散った<Default note=\"text:こうばな\">香花</>の花びらを一枚ずつ拾い集め、丁寧に額へと仕立て、「これは子々孫々、代々伝える宝とするのだ」と申しておりました。",
            ["DialogueId"] = 80230111,
            ["GUID"] = "C8D90096",
            ["NextDialogue"] = 80230112,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90096",
            },
        [80230112] = {
            ["Content"] = "呵呵，获得太皓的青睐只是第一步。接下来，你们还要通过三道试炼，才能加身龙渊上卿之殊荣。",
            ["ContentJP"] = "ふふ……<Default note=\"text:たいこう\">太皓</>に選ばれるは、あくまで始まりにすぎぬ。真に<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>の誉れを受けるには、なお三つの試練を越えねばならぬ。",
            ["DialogueId"] = 80230112,
            ["GUID"] = "C8D900C0",
            ["NextDialogue"] = 80230113,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D900C0",
            },
        [80230113] = {
            ["Content"] = "那么，闲谈就到此为止。请对答——",
            ["ContentJP"] = "……では、雑談はここまで。問いに答えるがよい。",
            ["DialogueId"] = 80230113,
            ["GUID"] = "C8D900EA",
            ["NextDialogue"] = 80230114,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D900EA",
            },
        [80230114] = {
            ["Content"] = "华胥人生而知大风九章。但你可曾想过，大风九章究其根本为何物？",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>の民は生まれながらに<Default note=\"text:たいふうきゅうしょう\">大風九章</>を知るという。されど、そなたは考えたことがあるか？その<Default note=\"text:たいふうきゅうしょう\">大風九章</>とは、果たして何なのかを——",
            ["DialogueId"] = 80230114,
            ["GUID"] = "C8D90114",
            ["NextDialogue"] = 80230115,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90114",
            },
        [80230115] = {
            ["Content"] = "……自然是太皓神力的流溢。",
            ["ContentJP"] = "……もちろん、<Default note=\"text:たいこう\">太皓</>の神力のあふれ出たものに他なりません。",
            ["DialogueId"] = 80230115,
            ["GUID"] = "C8D9013E",
            ["NextDialogue"] = 80230116,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9013E",
            },
        [80230116] = {
            ["Content"] = "大风九章有如日月轮转，江河奔流，是天地自然之理。它存在于此，亘古如斯。纵地裂山崩，江水为竭，冬雷夏雪，沧海桑田，它仍如日月般恒久不变。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>は、日の昇り沈み、河の流れと同じ。それは天地の<Default note=\"text:ことわり\">理</>であり、あらゆる自然のめぐりそのもの。地が裂け、山が崩れ、川が涸れようとも、冬に雷が走り、夏に雪が舞おうとも、それは絶えずめぐり続け、<Default note=\"text:じつげつ\">日月</>のごとく変わることはありません。",
            ["DialogueId"] = 80230116,
            ["GUID"] = "C8D90168",
            ["NextDialogue"] = 80230117,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90168",
            },
        [80230117] = {
            ["Content"] = "我等尊奉大风九章，就和鱼得水逝而相忘乎水，鸟乘风飞而不知有风是一样的道理。",
            ["ContentJP"] = "私たちが<Default note=\"text:たいふうきゅうしょう\">大風九章</>を<Default note=\"text:とうと\">尊</>ぶのは、魚が水に泳ぎて水を知らず、鳥が風に乗りて風を<Default note=\"text:し\">識</>らぬがごとし。それがあまりに根源で、あまりに自然だからです。",
            ["DialogueId"] = 80230117,
            ["GUID"] = "C8D90192",
            ["NextDialogue"] = 80230118,
            ["SpeakNpcId"] = 790078,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90192",
            },
        [80230118] = {
            ["Content"] = "你对神君的虔诚，祂与我等皆已知悉。先下去歇息，回家静候吧。",
            ["ContentJP"] = "その信心と敬意、<Default note=\"text:たいこう\">太皓</>もまた汲み取られておろう。しばし下がり、家にて静かに待つがよい。",
            ["DialogueId"] = 80230118,
            ["GUID"] = "C8D901BC",
            ["NextDialogue"] = 80230119,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D901BC",
            },
        [80230119] = {
            ["Content"] = "下一位。",
            ["ContentJP"] = "次の者。",
            ["DialogueId"] = 80230119,
            ["GUID"] = "C8D901E6",
            ["NextDialogue"] = 80230120,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D901E6",
            },
        [80230120] = {
            ["DialogueId"] = 80230120,
            ["GUID"] = "C8D90210",
            ["NextDialogue"] = 80230121,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90210",
            },
        [80230121] = {
            ["Content"] = "晚辈止流，见过大人。",
            ["ContentJP"] = "シリュウと申します。お目にかかれて光栄です。",
            ["DialogueId"] = 80230121,
            ["GUID"] = "C8D9023A",
            ["NextDialogue"] = 80230122,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9023A",
            },
        [80230122] = {
            ["Content"] = "止流，你要回答的问题，与上个人相同——“大风九章究其根本为何物？”",
            ["ContentJP"] = "シリュウよ、そなたへの問いもまた、先の者と同じ。<Default note=\"text:たいふうきゅうしょう\">大風九章</>とは、果たして何だい？",
            ["DialogueId"] = 80230122,
            ["GUID"] = "C8D90264",
            ["NextDialogue"] = 80230123,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90264",
            },
        [80230123] = {
            ["Content"] = "……您问的是大风九章的“本质”……",
            ["ContentJP"] = "……御尋ねは、その「<Default note=\"text:ほんしつ\">本質</>」にございますね……",
            ["DialogueId"] = 80230123,
            ["GUID"] = "C8D9028E",
            ["NextDialogue"] = 80230124,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9028E",
            },
        [80230124] = {
            ["Content"] = "止流心中确有拙见。但若有冒犯，还请大人和神君宽恕晚辈无知。",
            ["ContentJP"] = "<Default note=\"text:つたな\">拙</>きながら、私なりの見立てがございます。もしも不敬の念あらば、どうかご<Default note=\"text:かんじょ\">寛恕</>を。",
            ["DialogueId"] = 80230124,
            ["GUID"] = "C8D902B8",
            ["NextDialogue"] = 80230125,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D902B8",
            },
        [80230125] = {
            ["Content"] = "哦？那依你之见，这“本质”该如何解读？",
            ["ContentJP"] = "ふむ。では申してみよ。そなたの言う本質とは、いかなるものか？",
            ["DialogueId"] = 80230125,
            ["GUID"] = "C8D902E2",
            ["NextDialogue"] = 80230126,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D902E2",
            },
        [80230126] = {
            ["Content"] = "太皓非自然之天道，而是顺应民心而生。",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>とは、天より与えられた自然の<Default note=\"text:せつり\">摂理</>ではなく——民の心が願い、呼び、創り上げた存在だと思っております。",
            ["DialogueId"] = 80230126,
            ["GUID"] = "C8D9030C",
            ["NextDialogue"] = 80230127,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9030C",
            },
        [80230127] = {
            ["Content"] = "昔日华胥子民久罹战祸，厌倦纷争，故而先祖矩、飏回应众人对和平的盼望，以无上伟力铸就大风九章之基石。",
            ["ContentJP"] = "かつて、<Default note=\"text:カショ\">華胥</>の人々は長き戦乱に苦しみ、争いに倦み果てておりました。その切なる願いに応え、先祖たるノリとヤンは、<Default note=\"text:たいこう\">太皓</>を立て、その力によって<Default note=\"text:たいふうきゅうしょう\">大風九章</>の<Default note=\"text:いしずえ\">礎</>を築いたのです。",
            ["DialogueId"] = 80230127,
            ["GUID"] = "C8D90336",
            ["NextDialogue"] = 80230128,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90336",
            },
        [80230128] = {
            ["Content"] = "神与万民实为相互成就，缺一不可。万民自愿收兵止戈，将裁定善恶之权柄托付于太皓，以己身信守诫律，如此才造就了今日的华胥。",
            ["ContentJP"] = "神と民とが、互いに支え合い、ひとつの秩序を成したのです。民はみずから剣を納め、善悪の裁きを<Default note=\"text:たいこう\">太皓</>に委ね、その<Default note=\"text:かいりつ\">誡律</>を自ら守ることを誓った。",
            ["DialogueId"] = 80230128,
            ["GUID"] = "C8D90360",
            ["NextDialogue"] = 80230129,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90360",
            },
        [80230129] = {
            ["Content"] = "与此同时，太皓回应万民心愿，使允诺的和平化为现实，泽被苍生。于是生生不息，往复循环。故而大风九章的本质，实为双方达成的<H>誓约</>。",
            ["ContentJP"] = "そして<Default note=\"text:たいこう\">太皓</>は、民の心を汲みとり、約された平和をこの地に現し、広く恵みを与えられた。この循環こそが、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の核であり、すなわち——神と人が結んだひとつの<H>誓約</>に他なりません。",
            ["DialogueId"] = 80230129,
            ["GUID"] = "C8D9038A",
            ["NextDialogue"] = 80230130,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9038A",
            },
        [80230130] = {
            ["Content"] = "……好一个誓约之说，你这解读却是大胆。",
            ["ContentJP"] = "……<Default note=\"text:せいやく\">誓約</>とな。なかなか見事な言い回しだ。だが、その解釈はずいぶんと大胆でもあるな。",
            ["DialogueId"] = 80230130,
            ["GUID"] = "C8D903B4",
            ["NextDialogue"] = 80230131,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D903B4",
            },
        [80230131] = {
            ["Content"] = "我且问你，你说太皓回应万民心愿，但那些太皓照耀不到的民心，又该如何看待呢？",
            ["ContentJP"] = "では問おう。<Default note=\"text:たいこう\">太皓</>が民の願いに応えるというが——その光が届かぬ者たちの心は、どうなるのだ？",
            ["DialogueId"] = 80230131,
            ["GUID"] = "C8D903DE",
            ["NextDialogue"] = 80230132,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D903DE",
            },
        [80230132] = {
            ["Content"] = "近来有些对大风九章的坊间杂言，其中不乏飘零人的推波助澜，相信你也有所耳闻——不必忌讳这个话题。",
            ["ContentJP"] = "近ごろ、<Default note=\"text:たいふうきゅうしょう\">大風九章</>を<Default note=\"text:やゆ\">揶揄</>する声が世間に流れておる。とりわけ、根なき者たちが火に油を注いでいるとも聞くが……心にあることを、隠さず申してみよ。",
            ["DialogueId"] = 80230132,
            ["GUID"] = "C8D90408",
            ["NextDialogue"] = 80230133,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90408",
            },
        [80230133] = {
            ["Content"] = "回大人，不同人的内心有千万种声音，神明统合了众人的心愿后，却只能保有一种声音。人人遂心所愿的世界，大约是不存在的。",
            ["ContentJP"] = "はい、人の心には、<Default note=\"text:いくせんいくまん\">幾千幾万</>の声が渦巻いております。神がそのすべてを束ね、ひとつの願いに結晶化するには、必ず「選ばれぬ声」が生まれてしまう。すべてが叶う世界など、きっとどこにも存在しません。",
            ["DialogueId"] = 80230133,
            ["GUID"] = "C8D90432",
            ["NextDialogue"] = 80230134,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90432",
            },
        [80230134] = {
            ["Content"] = "凝聚多数之共识，规训少数之异见，这是构建秩序的代价，亦为社稷存续的根基。",
            ["ContentJP"] = "多数の声をひとつにまとめ、異なる声を律する——それは秩序の代償であり、国という器を保つために避けられぬ<Default note=\"text:いしずえ\">礎</>なのです。",
            ["DialogueId"] = 80230134,
            ["GUID"] = "C8D9045C",
            ["NextDialogue"] = 80230135,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9045C",
            },
        [80230135] = {
            ["Content"] = "有点意思……再说一遍你的名字，叫什么来着？",
            ["ContentJP"] = "……ほう、面白いことを申す。名はなんだったかな？",
            ["DialogueId"] = 80230135,
            ["GUID"] = "C8D90486",
            ["NextDialogue"] = 80230136,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90486",
            },
        [80230136] = {
            ["Content"] = "止流，不吝赐教。",
            ["ContentJP"] = "シリュウと申します。どうか、ご指導を。",
            ["DialogueId"] = 80230136,
            ["GUID"] = "C8D904B0",
            ["NextDialogue"] = 80230137,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D904B0",
            },
        [80230137] = {
            ["Content"] = "止狂澜，断万流……是个寓意不错的名字。回去等消息吧。",
            ["ContentJP"] = "「世の混乱を止め、流れを正す者……」良き名だ。意味を携えておる。家に戻り、しばし知らせを待て。",
            ["DialogueId"] = 80230137,
            ["GUID"] = "C8D904DA",
            ["NextDialogue"] = 80230138,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D904DA",
            },
        [80230138] = {
            ["Content"] = "止流，我见你有眼缘，便多叮嘱你一句。",
            ["ContentJP"] = "……シリュウ。そなた、我が目に少なからぬ縁を感じるゆえ、ひとつ言葉を贈ろう。",
            ["DialogueId"] = 80230138,
            ["GUID"] = "C8D90504",
            ["NextDialogue"] = 80230139,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D90504",
            },
        [80230139] = {
            ["Content"] = "——治国乃修罗之道，你须承担百般恶名，漠视万民冤屈。你下定决心了吗？",
            ["ContentJP"] = "——国を治めるとは、修羅の道なり。百の悪名を背負い、万の嘆きを聞かぬふりせねばならぬ。それでもなお——進む覚悟はあるか？",
            ["DialogueId"] = 80230139,
            ["GUID"] = "C8D9052E",
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/001/C8D9052E",
            },
        [80230201] = {
            ["Content"] = "大风九章出错了——有冤情！我要伸冤！",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>の裁きに、間違いがあるんです……お願い、話を聞いてください！",
            ["DialogueId"] = 80230201,
            ["GUID"] = "C8D90F5A",
            ["NextDialogue"] = 80230202,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90F5A",
            },
        [80230202] = {
            ["Content"] = "这位大人，求您了，听听我要说的话吧，只需要耽误您一点时间——",
            ["ContentJP"] = "ほんの少しだけでいいんです……どうか！",
            ["DialogueId"] = 80230202,
            ["GUID"] = "C8D90F84",
            ["NextDialogue"] = 80230203,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90F84",
            },
        [80230203] = {
            ["Content"] = "请您稍留片刻——",
            ["ContentJP"] = "聞いてください！",
            ["DialogueId"] = 80230203,
            ["GUID"] = "C8D90FAE",
            ["NextDialogue"] = 80230204,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90FAE",
            },
        [80230204] = {
            ["DialogueId"] = 80230204,
            ["GUID"] = "C8D90FD8",
            ["NextDialogue"] = 80230205,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D90FD8",
            },
        [80230205] = {
            ["Content"] = "出什么事了？",
            ["ContentJP"] = "…どうかしましたか？",
            ["DialogueId"] = 80230205,
            ["GUID"] = "C8D91002",
            ["NextDialogue"] = 80230206,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91002",
            },
        [80230206] = {
            ["Content"] = "——！",
            ["ContentJP"] = "……っ！",
            ["DialogueId"] = 80230206,
            ["GUID"] = "C8D9102C",
            ["NextDialogue"] = 80230207,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9102C",
            },
        [80230207] = {
            ["Content"] = "我先前身患重病，被一位泽生阁的医师所救。治好我的那位医师，她甚至未收分文，却被狴犴惩处身亡了！",
            ["ContentJP"] = "私、重い病を患っていたんです。もう治らないって言われて……でも、<Default note=\"text:たくせいかく\">澤生閣</>のある女医さんが救ってくれました。お金も取らずに、命を……助けてくれたんです。",
            ["DialogueId"] = 80230207,
            ["GUID"] = "C8D91056",
            ["NextDialogue"] = 80230208,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91056",
            },
        [80230208] = {
            ["Content"] = "求求你们，至少——至少把清誉还给她吧！她是个一心救人的医师啊，大风九章判她的药害了我，但那只是暂时的药效变化而已。",
            ["ContentJP"] = "でも、その人は「薬害の罪」って──<Default note=\"text:ビーアン\">狴犴</>に裁かれて、処刑されました……！お願いです……せめて……せめて、名誉だけでも返してあげてください！あの人は、ただ人を救いたいって、それだけだったんです……！",
            ["DialogueId"] = 80230208,
            ["GUID"] = "C8D91080",
            ["NextDialogue"] = 80230209,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91080",
            },
        [80230209] = {
            ["Content"] = "我病情复杂，当时看了很多医师都只是摆摆手表示无能为力，只有她提出用以毒攻毒的险方一试。",
            ["ContentJP"] = "私の病は気難しくて、他の医者はみんな「手に負えない」と匙を投げたんです。でも彼女だけが、「毒をもって毒を制す」って、危険を承知で治療法を示してくれて……",
            ["DialogueId"] = 80230209,
            ["GUID"] = "C8D910AA",
            ["NextDialogue"] = 80230210,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D910AA",
            },
        [80230210] = {
            ["Content"] = "服药后可能出现惊厥，甚至短暂的呼吸停止，这些后果她都与我详细说过。我甘愿承担这风险，却没想到最终反倒牵连了她。",
            ["ContentJP"] = "飲んだ薬で、痙攣や呼吸の一時停止が起こるかもしれない、そう言われていました。私は納得して、命を預けたんです。……なのに、助けてくれた人が死ぬなんて……そんなのおかしいです！",
            ["DialogueId"] = 80230210,
            ["GUID"] = "C8D910D4",
            ["NextDialogue"] = 80230211,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D910D4",
            },
        [80230211] = {
            ["Content"] = "你的意思是，大风九章错判了治疗过程，使治你的人含冤而死，是吗？",
            ["ContentJP"] = "……つまり、<Default note=\"text:たいふうきゅうしょう\">大風九章</>はその治療を誤って裁いた。あなたを救った人が、冤罪で命を奪われたというのですね？",
            ["DialogueId"] = 80230211,
            ["GUID"] = "C8D910FE",
            ["NextDialogue"] = 80230212,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D910FE",
            },
        [80230212] = {
            ["Content"] = "就是这样！我还好端端地站在这里呢，不然还有死人诈尸的道理吗？",
            ["ContentJP"] = "そうです！私はこうしてちゃんと生きています！これはまぎれもない事実です！",
            ["DialogueId"] = 80230212,
            ["GUID"] = "C8D91128",
            ["NextDialogue"] = 80230213,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91128",
            },
        [80230213] = {
            ["Content"] = "我还活着，救我的人却因此去世了。我……我没有办法接受这种事。",
            ["ContentJP"] = "私はこうして生きているのに──救ってくれた人は、もうどこにもいない。どうしても、納得できないんです。",
            ["DialogueId"] = 80230213,
            ["GUID"] = "C8D91152",
            ["NextDialogue"] = 80230214,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91152",
            },
        [80230214] = {
            ["Content"] = "我明白了。这件事情我不敢保证什么，但我会尽力而为。",
            ["ContentJP"] = "……事情は理解しました。約束はできませんが、力を尽くしましょう。",
            ["DialogueId"] = 80230214,
            ["GUID"] = "C8D9117C",
            ["NextDialogue"] = 80230215,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9117C",
            },
        [80230215] = {
            ["Content"] = "——谢谢您！谢谢！",
            ["ContentJP"] = "……ありがとう、ございます……！ほんとうに……！",
            ["DialogueId"] = 80230215,
            ["GUID"] = "C8D911A6",
            ["NextDialogue"] = 80230216,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D911A6",
            },
        [80230216] = {
            ["Content"] = "……其实我知道这件事情非常难，您可能也没办法做到什么。我在这里站了好几天了，只有您一个人愿意停下来听我说话……",
            ["ContentJP"] = "……無理を言ってるのは、わかってるんです。たぶん、あなたにもどうにもできないってことも。何日もここに立ってましたが……話を聞いてくれたの、あなただけでした。",
            ["DialogueId"] = 80230216,
            ["GUID"] = "C8D911D0",
            ["NextDialogue"] = 80230217,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D911D0",
            },
        [80230217] = {
            ["Content"] = "哪怕是为了这点善意，我也要感谢您……",
            ["ContentJP"] = "それでも……救われた気になれました。ありがとうございます……",
            ["DialogueId"] = 80230217,
            ["GUID"] = "C8D911FA",
            ["NextDialogue"] = 80230218,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D911FA",
            },
        [80230218] = {
            ["Content"] = "呵呵，只是无足挂齿的小事而已。",
            ["ContentJP"] = "ふふ……たいしたことではありませんよ。",
            ["DialogueId"] = 80230218,
            ["GUID"] = "C8D91224",
            ["NextDialogue"] = 80230219,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91224",
            },
        [80230219] = {
            ["DialogueId"] = 80230219,
            ["GUID"] = "C8D9124E",
            ["NextDialogue"] = 80230220,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9124E",
            },
        }
  end },
  { MinKey = 80230220, MaxKey = 80240235, Loader = function()
      return {
        [80230220] = {
            ["Content"] = "各位既已到齐，接下来便开始第二道试炼——",
            ["ContentJP"] = "よく揃った。では、第二の試練を――",
            ["DialogueId"] = 80230220,
            ["GUID"] = "C8D91278",
            ["NextDialogue"] = 80230221,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91278",
            },
        [80230221] = {
            ["Content"] = "……有冤……我要申冤！",
            ["ContentJP"] = "……冤罪……なんです！……聞いてください……！",
            ["DialogueId"] = 80230221,
            ["GUID"] = "C8D912A2",
            ["NextDialogue"] = 80230222,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D912A2",
            },
        [80230222] = {
            ["Content"] = "那女孩怎么还在执律阁下闹个不停？既让路人烦扰不堪，也扰了太皓清净。大人，不如请应天尉将她清退吧！",
            ["ContentJP"] = "あの娘、まだ騒いでるのか？通行人まで迷惑してるし、<Default note=\"text:たいこう\">太皓</>の静寂を乱すことにもなる。いっそ<Default note=\"text:おうてんい\">応天尉</>に命じて追い払っては……？",
            ["DialogueId"] = 80230222,
            ["GUID"] = "C8D912CC",
            ["NextDialogue"] = 80230223,
            ["SpeakNpcId"] = 790080,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D912CC",
            },
        [80230223] = {
            ["Content"] = "稍安勿躁，她便是你们今日的试题。",
            ["ContentJP"] = "……そう急くな。あの娘こそが、そなたらに与えられた問いだ。",
            ["DialogueId"] = 80230223,
            ["GUID"] = "C8D912F6",
            ["NextDialogue"] = 80230224,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D912F6",
            },
        [80230224] = {
            ["Content"] = "（嘈杂的议论声）\
配音：什么？真的吗？（复数人声）",
            ["ContentJP"] = "なんだって？本気か？",
            ["DialogueId"] = 80230224,
            ["GUID"] = "C8D91320",
            ["NextDialogue"] = 80230225,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91320",
            },
        [80230225] = {
            ["Content"] = "大风九章作为经年累月运转的庞大体系，哪怕是万分之一的几率，也会产生纰漏。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>は、長きに渡り運用されてきた体系にして、完全<Default note=\"text:むびゅう\">無謬</>を許されぬ以上、常に誤差を孕む宿命にある。わずかとはいえ、綻びが生まれるのもまた理。",
            ["DialogueId"] = 80230225,
            ["GUID"] = "C8D9134A",
            ["NextDialogue"] = 80230226,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9134A",
            },
        [80230226] = {
            ["Content"] = "如何辅助太皓妥善处理这些纰漏，是治理国家的重要一环，也是今日为诸位所设置的考察。诸位有想法，都可以畅所欲言。",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>の御下、これをいかに補い、穏やかに治めるか──それこそが、政を担う者に求められる資質にほかならぬ。今日、そなたらが試されるのは、その見極めよ。思うところあらば、遠慮なく申すがよい。",
            ["DialogueId"] = 80230226,
            ["GUID"] = "C8D91374",
            ["NextDialogue"] = 80230227,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91374",
            },
        [80230227] = {
            ["Content"] = "大人，大风九章的正义早已深入人心。这种杂音，不予理会就是。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>の正義は、既に民の信を得ております。この手の雑音に耳を傾ける必要はないかと。",
            ["DialogueId"] = 80230227,
            ["GUID"] = "C8D9139E",
            ["NextDialogue"] = 80230228,
            ["SpeakNpcId"] = 790080,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9139E",
            },
        [80230228] = {
            ["Content"] = "千里之堤，溃于蚁穴。如果长期放任不管，只会助长了山外山那等势力的气焰，造成隐患。",
            ["ContentJP"] = "……「千里の<Default note=\"text:つつみ\">堤</>も、蟻の一穴より崩れる」という。小さき声を侮れば、いずれは<Default note=\"text:さんがいさん\">山外山</>のような異端の火種を育てましょう。それは、見過ごしてはならぬ脅威となる。",
            ["DialogueId"] = 80230228,
            ["GUID"] = "C8D913C8",
            ["NextDialogue"] = 80230229,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D913C8",
            },
        [80230229] = {
            ["Content"] = "依我看，不外乎威逼利诱二种做法！给出足够强力的威胁，或者足够动人的利益交换，再顽固的人也会败下阵来。",
            ["ContentJP"] = "……拙案ながら、要は「威」と「利」にございます。十分な威圧か、あるいは魅力ある取引をもってすれば、どれほど頑なな者とて、いずれは屈しましょう。",
            ["DialogueId"] = 80230229,
            ["GUID"] = "C8D913F2",
            ["NextDialogue"] = 80230230,
            ["SpeakNpcId"] = 790081,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D913F2",
            },
        [80230230] = {
            ["Content"] = "人非草木。你若是轻视了人心，引起对方反弹，非但平息不了风波，只会让事情更加棘手。",
            ["ContentJP"] = "人は<Default note=\"text:くさき\">草木</>にあらず。心を軽んじては、反発を呼び、かえって波風を立てましょう。志を挫くより、志を読め。そう心得よ。",
            ["DialogueId"] = 80230230,
            ["GUID"] = "C8D9141C",
            ["NextDialogue"] = 80230231,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9141C",
            },
        [80230231] = {
            ["Content"] = "（嘈杂的议论声）\
配音：这也不行，那也不行？那该如何是好（复数人声）",
            ["ContentJP"] = "じゃあどうすれば……",
            ["DialogueId"] = 80230231,
            ["GUID"] = "C8D91446",
            ["NextDialogue"] = 80230232,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91446",
            },
        [80230232] = {
            ["Content"] = "我有一法，且让我试试吧。",
            ["ContentJP"] = "私に一策ございます。お試しいただけますか。",
            ["DialogueId"] = 80230232,
            ["GUID"] = "C8D91470",
            ["NextDialogue"] = 80230233,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91470",
            },
        [80230233] = {
            ["DialogueId"] = 80230233,
            ["GUID"] = "C8D9149A",
            ["NextDialogue"] = 80230234,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9149A",
            },
        [80230234] = {
            ["Content"] = "好心的姐姐，是您……您来见我了！",
            ["ContentJP"] = "……あなた、来てくれたんですね……！",
            ["DialogueId"] = 80230234,
            ["GUID"] = "C8D914C4",
            ["NextDialogue"] = 80230235,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D914C4",
            },
        [80230235] = {
            ["Content"] = "这么快就回来，难不成……您有什么办法了？",
            ["ContentJP"] = "もしかして、何か手立てが……？",
            ["DialogueId"] = 80230235,
            ["GUID"] = "C8D914EE",
            ["NextDialogue"] = 80230236,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D914EE",
            },
        [80230236] = {
            ["Content"] = "抱歉，你的诉求，我恐怕没法满足。",
            ["ContentJP"] = "……申し訳ない。あなたの願い──私には、叶えられそうにありません。",
            ["DialogueId"] = 80230236,
            ["GUID"] = "C8D91518",
            ["NextDialogue"] = 80230237,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91518",
            },
        [80230237] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80230237,
            ["GUID"] = "C8D91542",
            ["NextDialogue"] = 80230238,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91542",
            },
        [80230238] = {
            ["Content"] = "大风九章关乎华胥万民生息，万民信赖是其运转的根基。不可因为零星错案动摇根基，因小失大。这是利弊取舍的一环。",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>は、<Default note=\"text:カショ\">華胥</>の万民の営みを支える根幹。その運用は、信頼によって初めて成立する。わずかとはいえ、誤判の可能性が根幹を揺るがすならば──本末転倒になってしまう。",
            ["DialogueId"] = 80230238,
            ["GUID"] = "C8D9156C",
            ["NextDialogue"] = 80230239,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9156C",
            },
        [80230239] = {
            ["Content"] = "但我可以承诺的是，此事风波平息后，泽生阁会获得扶持。此外，我还能为你个人申请一笔补偿金，聊以慰藉。",
            ["ContentJP"] = "ただし、騒ぎが収まったのち、<Default note=\"text:たくせいかく\">澤生閣</>への支援を約束しましょう。あなた個人には補償金を申請いたします。ささやかでも、少しは慰めになることを願って。",
            ["DialogueId"] = 80230239,
            ["GUID"] = "C8D91596",
            ["NextDialogue"] = 80230240,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91596",
            },
        [80230240] = {
            ["Content"] = "这些听起来似乎很好，可是姐姐……我不想要这样。",
            ["ContentJP"] = "……確かに、一理ありますね。でも、お姉さん……私、そういうの……いらないんです。",
            ["DialogueId"] = 80230240,
            ["GUID"] = "C8D915C0",
            ["NextDialogue"] = 80230241,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D915C0",
            },
        [80230241] = {
            ["Content"] = "要是没有救我的那位医师，我现在已经是黄土之下的一缕亡魂了。对死人来说，钱还能花到哪里去呢？",
            ["ContentJP"] = "あの人がいなければ、私は今ごろ、土の下。助けてくれた人が死んだのに、私が金をもらうなんて……そんなのおかしい。",
            ["DialogueId"] = 80230241,
            ["GUID"] = "C8D915EA",
            ["NextDialogue"] = 80230242,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D915EA",
            },
        [80230242] = {
            ["Content"] = "同样的道理，对于救下我却失去了性命的那位医师，这些身外之物也没有意义了。我唯一能为她争的，只有生后的清白而已。",
            ["ContentJP"] = "死んだ人に、補償なんて届かない。命を差し出してまで私を救った人に、私が返せるものは──ただひとつ、名誉だけなんです。",
            ["DialogueId"] = 80230242,
            ["GUID"] = "C8D91614",
            ["NextDialogue"] = 80230243,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91614",
            },
        [80230243] = {
            ["Content"] = "拿了这些钱，我或许能过上更好的生活，但是我的良心呢？它以后要是痛了起来，我再也找不到药方去治疗它了。",
            ["ContentJP"] = "もし私がこのお金で少しでも楽に生きられたとしても……いつか、心が痛んだとき──その痛みを癒す薬は、どこにも見つからないと思うんです。",
            ["DialogueId"] = 80230243,
            ["GUID"] = "C8D9163E",
            ["NextDialogue"] = 80230244,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9163E",
            },
        [80230244] = {
            ["Content"] = "姐姐，大风九章的运转，真的要以一个个人的冤屈被掩埋为代价吗？",
            ["ContentJP"] = "……お姉さん。<Default note=\"text:たいふうきゅうしょう\">大風九章</>って、本当に……誰かひとりの冤罪を、黙って飲み込むことでしか、運用できないものなんですか？",
            ["DialogueId"] = 80230244,
            ["GUID"] = "C8D91668",
            ["NextDialogue"] = 80230245,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91668",
            },
        [80230245] = {
            ["Content"] = "……你这性子和我年轻时倒有几分相似。那有些话，我也只说与你我二人听。",
            ["ContentJP"] = "……そのまっすぐな目、昔の私によく似てる。今から言うことは、私とあなただけの秘密よ。",
            ["DialogueId"] = 80230245,
            ["GUID"] = "C8D91692",
            ["NextDialogue"] = 80230246,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91692",
            },
        [80230246] = {
            ["DialogueId"] = 80230246,
            ["GUID"] = "C8D916BC",
            ["NextDialogue"] = 80230247,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D916BC",
            },
        [80230247] = {
            ["Content"] = "止流少卿，未想到你三言两语就摆平了那少女，使她签下了放弃伸冤的契书。有什么诀窍呀？也教教我们吧！",
            ["ContentJP"] = "こんな容易くあの娘を引き下がらせるとは！何か秘訣でも？ぜひ私たちにもご教授を！",
            ["DialogueId"] = 80230247,
            ["GUID"] = "C8D916E6",
            ["NextDialogue"] = 80230248,
            ["SpeakNpcId"] = 790081,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D916E6",
            },
        [80230248] = {
            ["Content"] = "过誉了。我还未通过全部试炼，当不起这一声称呼。只是耐心为她分析了其中利弊而已。",
            ["ContentJP"] = "……お褒めには及びません。私はまだすべての試練を終えたわけではないので。ただ、利害の理を説いただけですよ。",
            ["DialogueId"] = 80230248,
            ["GUID"] = "C8D91710",
            ["NextDialogue"] = 80230249,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91710",
            },
        [80230249] = {
            ["Content"] = "若无其他要事，我先告退了。",
            ["ContentJP"] = "他にご用がなければ──これにて失礼いたします。",
            ["DialogueId"] = 80230249,
            ["GUID"] = "C8D9173A",
            ["NextDialogue"] = 80230250,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9173A",
            },
        [80230250] = {
            ["DialogueId"] = 80230250,
            ["GUID"] = "C8D91764",
            ["NextDialogue"] = 80230251,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91764",
            },
        [80230251] = {
            ["Content"] = "你们知道吗？听说那个止流啊，从前也受过大风九章的冤屈。",
            ["ContentJP"] = "……知ってる？あのシリュウって女、<Default note=\"text:たいふうきゅうしょう\">大風九章</>の誤審で裁かれたことがあるらしいよ。",
            ["DialogueId"] = 80230251,
            ["GUID"] = "C8D9178E",
            ["NextDialogue"] = 80230252,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9178E",
            },
        [80230252] = {
            ["Content"] = "曾经她也在执律阁下那个位置四处奔走，甚至是这附近居民茶余饭后的谈资呢。",
            ["ContentJP"] = "なんでも、<Default note=\"text:しつりつかく\">執律閣</>の下で叫んでたんだって。この辺の住人の酒のつまみになったくらいだ。",
            ["DialogueId"] = 80230252,
            ["GUID"] = "C8D917B8",
            ["NextDialogue"] = 80230253,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D917B8",
            },
        [80230253] = {
            ["Content"] = "没想到今天她能眼都不眨地摆平和曾经的自己一样的人。这就是成大事者吗？",
            ["ContentJP"] = "それが今日じゃ、自分と同じ境遇の子を、なんの迷いもなく黙らせたんだ。……やっぱり、出世できる奴は違うね。",
            ["DialogueId"] = 80230253,
            ["GUID"] = "C8D917E2",
            ["NextDialogue"] = 80230254,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D917E2",
            },
        [80230254] = {
            ["Content"] = "唉……恐怕她就是下一位龙渊上卿了，我们也羡慕不来，毕竟学不了她的心狠手辣。恐怕只有修罗心肠的人，才能站在那个位置吧。",
            ["ContentJP"] = "はぁ……きっと、次の<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>は彼女なんだろうな。真似できないよ──あそこまで心を切り捨てられなきゃ、無理だ。",
            ["DialogueId"] = 80230254,
            ["GUID"] = "C8D9180C",
            ["NextDialogue"] = 80230255,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D9180C",
            },
        [80230255] = {
            ["Content"] = "呵呵……只有修罗心肠，才能治大国吗？",
            ["ContentJP"] = "ふふ……心を捨てなければ、国は治められない、ですって？",
            ["DialogueId"] = 80230255,
            ["GUID"] = "C8D91836",
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/002/C8D91836",
            },
        [80230301] = {
            ["Content"] = "接下来便是最后一道试炼了，先提前恭贺你一声。迈过此关，你便能以龙渊上卿的头衔荣登执律阁巅。",
            ["ContentJP"] = "……さて。これより、最後の試練に移る。一足先に、祝意を述べておこう。この関門を越えれば、そなたは「<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>」の名を授かり、<Default note=\"text:しつりつかく\">執律閣</>の頂に立つこととなる。",
            ["DialogueId"] = 80230301,
            ["GUID"] = "C8D91FC2",
            ["NextDialogue"] = 80230302,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D91FC2",
            },
        [80230302] = {
            ["Content"] = "这最后一道试炼，其名为“问心”。",
            ["ContentJP"] = "この最終の試練――名を「<Default note=\"text:うらどい\">心問い</>」という。",
            ["DialogueId"] = 80230302,
            ["GUID"] = "C8D91FEC",
            ["NextDialogue"] = 80230303,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D91FEC",
            },
        [80230303] = {
            ["Content"] = "在太皓的神力照耀之下，你的过往心魔将如影照形，历历可见。",
            ["ContentJP"] = "<Default note=\"text:たいこう\">太皓</>の神威のもと、そなたの過去は影のごとく形を取り、心に巣くうものどもが、余すところなく現れよう。",
            ["DialogueId"] = 80230303,
            ["GUID"] = "C8D92016",
            ["NextDialogue"] = 80230304,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92016",
            },
        [80230304] = {
            ["Content"] = "对于尔等大毅力者，必能斩断过往，踏过心中软弱，从而执起“承九鼎，济苍黎”之重任。",
            ["ContentJP"] = "されど、大いなる志を抱く者であれば、過去を断ち、心の弱さを踏み越え、人々を背負い、世を救う重責を、その手に取ることができる。",
            ["DialogueId"] = 80230304,
            ["GUID"] = "C8D92040",
            ["NextDialogue"] = 80230305,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92040",
            },
        [80230305] = {
            ["Content"] = "止流，你可准备好了？",
            ["ContentJP"] = "シリュウ、覚悟はできたか？",
            ["DialogueId"] = 80230305,
            ["GUID"] = "C8D9206A",
            ["NextDialogue"] = 80230306,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9206A",
            },
        [80230306] = {
            ["Content"] = "从很久之前，我就已明确此心志向，不会再随外物而动。",
            ["ContentJP"] = "ずっと以前より、進む道は定まっています。もはや、外のものに心を揺らされることはありません。",
            ["DialogueId"] = 80230306,
            ["GUID"] = "C8D92094",
            ["NextDialogue"] = 80230307,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92094",
            },
        [80230307] = {
            ["Content"] = "很好。我没有看走眼。",
            ["ContentJP"] = "我が目に、狂いはなかったようだ。",
            ["DialogueId"] = 80230307,
            ["GUID"] = "C8D920BE",
            ["NextDialogue"] = 80230308,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D920BE",
            },
        [80230308] = {
            ["Content"] = "止流，甫一见面，我便看出你是那些人里最出类拔萃的一个苗子。",
            ["ContentJP"] = "シリュウ、初めて相まみえたその時から、そなたが群を抜く存在となることは、見えていた。",
            ["DialogueId"] = 80230308,
            ["GUID"] = "C8D920E8",
            ["NextDialogue"] = 80230309,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D920E8",
            },
        [80230309] = {
            ["Content"] = "那么试炼正式开始。无关人士便先清退了，我在执律阁外静候你的佳音。",
            ["ContentJP"] = "では、試練を始める。部外者は退くとしよう。<Default note=\"text:しつりつかく\">執律閣</>の外にて、そなたの報せを待っているよ。",
            ["DialogueId"] = 80230309,
            ["GUID"] = "C8D92112",
            ["NextDialogue"] = 80230310,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92112",
            },
        [80230310] = {
            ["DialogueId"] = 80230310,
            ["GUID"] = "C8D9213C",
            ["NextDialogue"] = 80230311,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9213C",
            },
        [80230311] = {
            ["Content"] = "——！",
            ["ContentJP"] = "……っ！",
            ["DialogueId"] = 80230311,
            ["GUID"] = "C8D92166",
            ["NextDialogue"] = 80230312,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92166",
            },
        [80230312] = {
            ["Content"] = "……",
            ["ContentJP"] = "……",
            ["DialogueId"] = 80230312,
            ["GUID"] = "C8D92190",
            ["NextDialogue"] = 80230313,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92190",
            },
        [80230313] = {
            ["DialogueId"] = 80230313,
            ["GUID"] = "C8D921BA",
            ["NextDialogue"] = 80230314,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D921BA",
            },
        [80230314] = {
            ["Content"] = "呜……呜呜……为什么……",
            ["ContentJP"] = "うっ……ひっく……どうして……どうしてなの……",
            ["DialogueId"] = 80230314,
            ["GUID"] = "C8D921E4",
            ["NextDialogue"] = 80230315,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D921E4",
            },
        [80230315] = {
            ["Content"] = "（果然……不出所料。）",
            ["ContentJP"] = "（……やっぱり。想定どおりね。）",
            ["DialogueId"] = 80230315,
            ["GUID"] = "C8D9220E",
            ["NextDialogue"] = 80230316,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9220E",
            },
        [80230316] = {
            ["Content"] = "你已经忘记了吗……<H>我们</>那些夜不能寐的晚上？",
            ["ContentJP"] = "忘れたの……？<H>私たち</>が越えた幾晩もの眠れぬ夜を……",
            ["DialogueId"] = 80230316,
            ["GUID"] = "C8D92238",
            ["NextDialogue"] = 80230317,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92238",
            },
        [80230317] = {
            ["Content"] = "你忘记了吗……在山洞里饥饿如蛆附骨的感觉，身体上下的每一处，每一根发丝都在叫嚣着好饿、好饿……",
            ["ContentJP"] = "忘れたの……？洞穴の奥で、お腹を空かせ、体の隅々まで空腹を嘆いた、あの感覚を……",
            ["DialogueId"] = 80230317,
            ["GUID"] = "C8D92262",
            ["NextDialogue"] = 80230318,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92262",
            },
        [80230318] = {
            ["Content"] = "你忘记了吗……那个歹徒，他满是茧子的手紧紧钳住<H>我们</>脖子的那一刻，无论我们怎么挣扎，怎么奋力踢腿，都阻止不了分毫……",
            ["ContentJP"] = "忘れたの……？あの男の、マメだらけの手が<H>私たち</>の首を締めた瞬間を……どれほど足掻いても、何ひとつ変わらなかった……",
            ["DialogueId"] = 80230318,
            ["GUID"] = "C8D9228C",
            ["NextDialogue"] = 80230319,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9228C",
            },
        [80230319] = {
            ["Content"] = "空气逐渐消失，一切闪着光的画面都变得稀薄，冰冷的死亡即将把我们拽入雾中……",
            ["ContentJP"] = "空気が薄れ……光ある景色が薄れ……冷たい死が、霧の向こうから手を伸ばしてきた、あの時を……",
            ["DialogueId"] = 80230319,
            ["GUID"] = "C8D922B6",
            ["NextDialogue"] = 80230320,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D922B6",
            },
        [80230320] = {
            ["Content"] = "以及……你忘了吗，<H>他</>冲上来，撞开歹徒，让空气一下子全部涌回来的那个时刻。",
            ["ContentJP"] = "それから……その男を吹き飛ばし、あなたに再び空気を与えた……<H>彼</>を……",
            ["DialogueId"] = 80230320,
            ["GUID"] = "C8D922E0",
            ["NextDialogue"] = 80230321,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D922E0",
            },
        [80230321] = {
            ["Content"] = "他曾经那样对你，不计回报地去救你，却只落得了身死名灭的下场。",
            ["ContentJP"] = "あの人は、何も求めず、あなたを助けた。なのに残ったのは、死と、忘却だけ……",
            ["DialogueId"] = 80230321,
            ["GUID"] = "C8D9230A",
            ["NextDialogue"] = 80230322,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9230A",
            },
        [80230322] = {
            ["Content"] = "现在，你要背叛他，背叛我们曾经发下的誓言，投向<H>他们</>那边吗？",
            ["ContentJP"] = "あなたまで……彼を裏切るの？私たちの誓いを捨てて、<H>あちら</>へ行くの？",
            ["DialogueId"] = 80230322,
            ["GUID"] = "C8D92334",
            ["NextDialogue"] = 80230323,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92334",
            },
        [80230323] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80230323,
            ["GUID"] = "C8D9235E",
            ["NextDialogue"] = 80230324,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9235E",
            },
        [80230324] = {
            ["Content"] = "（是的……是的……你不需要去铭记。因为遗忘明显更加甜美。）",
            ["ContentJP"] = "（そうだ……そうだ……覚えている必要などない。忘却こそ、何より楽にしてくれる。）",
            ["DialogueId"] = 80230324,
            ["GUID"] = "C8D92388",
            ["NextDialogue"] = 80230325,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92388",
            },
        [80230325] = {
            ["Content"] = "（你即将成为万人之上的止流大人！这些过去的纷扰无法撼动你，和你即将获得的地位相比，他们显得那么不起眼，那么无足轻重，甚至不如一根轻飘飘的鸿毛。）",
            ["ContentJP"] = "（お前は、万民の上にに立つシリュウ様となる。この程度の過去が、未来を揺らすはずもない。得られる地位に比べれば、羽よりも軽い。）",
            ["DialogueId"] = 80230325,
            ["GUID"] = "C8D923B2",
            ["NextDialogue"] = 80230326,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D923B2",
            },
        [80230326] = {
            ["Content"] = "（倒不如说，铭记只是软弱的证明。软弱者用无谓的良心将自己束缚住，于是他们屈服了。他们的膝盖承受不住大地的重力，永远匍匐在尘埃之中。）",
            ["ContentJP"] = "（そもそもこの記憶自体が、弱さの証だ。弱き者は、無用な良心に縛られ、膝を折り、塵に伏す。）",
            ["DialogueId"] = 80230326,
            ["GUID"] = "C8D923DC",
            ["NextDialogue"] = 80230327,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D923DC",
            },
        [80230327] = {
            ["Content"] = "（那些软弱者沉浸在自己的梦中，同时世界毫无变化。而你，你显然更加坚毅，更加勇敢——你懂得取舍，于是你能成大器。有几人能有成为修罗的大毅力呢？）",
            ["ContentJP"] = "（夢に沈む者が、世を変えることはない。だが、お前は違う。選び、捨てることを知っている。修羅となる覚悟を持つ者が、どれほどいる？）",
            ["DialogueId"] = 80230327,
            ["GUID"] = "C8D92406",
            ["NextDialogue"] = 80230328,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92406",
            },
        [80230328] = {
            ["Content"] = "（不要听他的！！止流，你与那些冷眼旁观的人有何区别？）",
            ["ContentJP"] = "（聞くな！！シリュウ、それでは見て見ぬふりをした者たちと、何が違う！）",
            ["DialogueId"] = 80230328,
            ["GUID"] = "C8D92430",
            ["NextDialogue"] = 80230329,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92430",
            },
        [80230329] = {
            ["Content"] = "（止流，你想好了，你也要成为他们的帮凶吗？！）",
            ["ContentJP"] = "（考え直せ！これでは、あいつらと同じだ！）",
            ["DialogueId"] = 80230329,
            ["GUID"] = "C8D9245A",
            ["NextDialogue"] = 80230330,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9245A",
            },
        [80230330] = {
            ["Content"] = "（若是踏出这一步，你还是昨日之你吗？）",
            ["ContentJP"] = "（この一歩を踏み出した先に、もはや昨日までのお前はいない！）",
            ["DialogueId"] = 80230330,
            ["GUID"] = "C8D92484",
            ["NextDialogue"] = 80230331,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92484",
            },
        [80230331] = {
            ["DialogueId"] = 80230331,
            ["GUID"] = "C8D924AE",
            ["NextDialogue"] = 80230332,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D924AE",
            },
        [80230332] = {
            ["Content"] = "救命，谁来救救我……这里好黑……我好害怕……我，我不能待在这个地方！",
            ["ContentJP"] = "たすけて……だれか……ここ、真っ暗で……こわい……ここにいたくない……！",
            ["DialogueId"] = 80230332,
            ["GUID"] = "C8D924D8",
            ["NextDialogue"] = 80230333,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D924D8",
            },
        [80230333] = {
            ["DialogueId"] = 80230333,
            ["GUID"] = "C8D92502",
            ["NextDialogue"] = 80230334,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92502",
            },
        [80230334] = {
            ["Content"] = "你知道吗……自从几年前有意识地去控制后，怕黑便不再能影响我的一举一动了。",
            ["ContentJP"] = "……あのね、暗闇なんて、数年前からとっくに克服してるの。もうなんともないわ。",
            ["DialogueId"] = 80230334,
            ["GUID"] = "C8D9252C",
            ["NextDialogue"] = 80230335,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9252C",
            },
        [80230335] = {
            ["Content"] = "当我意识到无论恐惧抑或痛苦都于事无补之时，我便舍弃了这些情绪。",
            ["ContentJP"] = "恐れようが、痛もうが――どうせ何も変わらない。そう気づいたときから、それらの感情を捨てたの。",
            ["DialogueId"] = 80230335,
            ["GUID"] = "C8D92556",
            ["NextDialogue"] = 80230336,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92556",
            },
        [80230336] = {
            ["Content"] = "因为我突然发现，人拥有的时间过于短暂——短暂到无法偿换自己欲求之物，这一生便匆匆结束了。",
            ["ContentJP"] = "人の一生なんて、思ってるよりずっと短い。欲しいものを手に入れるには、あまりに足りない。",
            ["DialogueId"] = 80230336,
            ["GUID"] = "C8D92580",
            ["NextDialogue"] = 80230337,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92580",
            },
        [80230337] = {
            ["Content"] = "从那一天起，我便下定决心。这世上的任何事情，无论是良心还是过往，都不再能绊住我的脚步。因为我还有要去完成的事情。",
            ["ContentJP"] = "だから決めたの。この先、良心だの過去だのに足を取られるわけにはいかない。まだ、やらなきゃいけないことがあるから。",
            ["DialogueId"] = 80230337,
            ["GUID"] = "C8D925AA",
            ["NextDialogue"] = 80230338,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D925AA",
            },
        [80230338] = {
            ["Content"] = "我很抱歉只能让你待在黑暗之中……但是不会有谁来救你了，你只能凭自己的力量走出这里。",
            ["ContentJP"] = "……ごめんね。助けるつもりはないわ。ここから出られるかどうかは――あなた次第よ。",
            ["DialogueId"] = 80230338,
            ["GUID"] = "C8D925D4",
            ["NextDialogue"] = 80230339,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D925D4",
            },
        [80230339] = {
            ["Content"] = "我言尽于此。",
            ["ContentJP"] = "それじゃ。",
            ["DialogueId"] = 80230339,
            ["GUID"] = "C8D925FE",
            ["NextDialogue"] = 80230340,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D925FE",
            },
        [80230340] = {
            ["DialogueId"] = 80230340,
            ["GUID"] = "C8D92628",
            ["NextDialogue"] = 80230341,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92628",
            },
        [80230341] = {
            ["Content"] = "传吉讯——",
            ["ContentJP"] = "吉報――",
            ["DialogueId"] = 80230341,
            ["GUID"] = "C8D92652",
            ["NextDialogue"] = 80230342,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D92652",
            },
        [80230342] = {
            ["Content"] = "皓京人士止流，现荣升为龙渊上卿——愿其承九鼎，济苍黎，不负太皓之望，传大风于万代——",
            ["ContentJP"] = "<Default note=\"text:こうけい\">皓京</>の士・シリュウ、このたび<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>に昇任す。九鼎を継ぎ、蒼生を救い、民を導く者となれ。<Default note=\"text:たいこう\">太皓</>の御意に応え、大風の理を万世へ届けよ。",
            ["DialogueId"] = 80230342,
            ["GUID"] = "C8D9267C",
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/003/C8D9267C",
            },
        [80230401] = {
            ["Content"] = "龙渊上卿每四载选拔一任，同时在任者寥寥无几，关于其选拔过程的记载往往残缺不全。如今竟从亲历者口中听到这么多细节，妙哉，妙哉！",
            ["ContentJP"] = "<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>の任は、四年に一度の選抜制。しかも同時に在任する者は、常にごくわずか。その選抜の過程ときたら、文献にも断片しか残らんのが常だ。まさか、当事者の口からこれほど詳しく聞けるとは……いやはや、面白い、実に面白い。",
            ["DialogueId"] = 80230401,
            ["GUID"] = "C8D9302A",
            ["NextDialogue"] = 80230402,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9302A",
            },
        [80230402] = {
            ["Content"] = "能旁观这段活生生的历史，我的心事又了了一桩。",
            ["ContentJP"] = "こうして生きた歴史を傍らから見届けられるとは……長年の念願が、また一つ叶った気分だよ。",
            ["DialogueId"] = 80230402,
            ["GUID"] = "C8D93054",
            ["NextDialogue"] = 80230403,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93054",
            },
        [80230403] = {
            ["Content"] = "……要是这些往事能让你消停片刻，少做些节外生枝的事情，那也不枉我费这么多口舌。",
            ["ContentJP"] = "……それで、少しでも落ち着いてくれるなら。余計なことを仕掛けずに済むのなら、私がこれだけ話した甲斐もあるというもの。",
            ["DialogueId"] = 80230403,
            ["GUID"] = "C8D9307E",
            ["NextDialogue"] = 80230404,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9307E",
            },
        [80230404] = {
            ["Content"] = "秦虬，我提醒你一句。{nickname}是我的座上宾，我不希望{性别：他|她}出什么意外。你行事最好有些分寸。",
            ["ContentJP"] = "キョウン、ひとつ忠告よ。{nickname}は、私が自ら招いた賓客。{性别：彼|彼女}に何かあれば、私は見過ごさない。行動には節度をもつことね。",
            ["DialogueId"] = 80230404,
            ["GUID"] = "C8D930A8",
            ["NextDialogue"] = 80230405,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D930A8",
            },
        [80230405] = {
            ["Content"] = "哈哈！你从冰湖城不远千里请回来的那位小友确实有趣，使我忍不住捉弄一番。",
            ["ContentJP"] = "ははは！いやはや、あのアイスレイク城からわざわざ連れ戻してきた客人だ。あまりの面白さについ、ちょっと茶々を入れてみたくなっただけさ。",
            ["DialogueId"] = 80230405,
            ["GUID"] = "C8D930D2",
            ["NextDialogue"] = 80230406,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D930D2",
            },
        [80230406] = {
            ["Content"] = "不过，止流掌柜对某人如此上心，倒是难得一见的光景。",
            ["ContentJP"] = "だがそれにしても、シリュウ殿が誰かにそこまで気を配るとは……これはまた、珍しいものを見せてもらった。",
            ["DialogueId"] = 80230406,
            ["GUID"] = "C8D930FC",
            ["NextDialogue"] = 80230407,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D930FC",
            },
        [80230407] = {
            ["Content"] = "这次计划的实情，你真不打算对{性别：他|她}托出一二吗？",
            ["ContentJP"] = "ところで。今回の計画、肝心なところは{性别：彼|彼女}に伏せたままで通すつもりかね？",
            ["DialogueId"] = 80230407,
            ["GUID"] = "C8D93126",
            ["NextDialogue"] = 80230408,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93126",
            },
        [80230408] = {
            ["Content"] = "……我自有我的打算，劝你不要有什么额外心思。",
            ["ContentJP"] = "……それなら、私なりの筋立てがあるわ。詮索は無用よ。",
            ["DialogueId"] = 80230408,
            ["GUID"] = "C8D93150",
            ["NextDialogue"] = 80230409,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93150",
            },
        [80230409] = {
            ["Content"] = "世人皆知我虬某阴险狡诈，无孔不钻，而你止流掌柜行事光明磊落，手段高明。",
            ["ContentJP"] = "世間じゃ、私のことを――陰険で抜け目なく、隙あらば食い込んでくる厄介者と呼ぶらしい。一方、シリュウ殿は正々堂々だそうだ。確かに、手口も見事なもんだ。",
            ["DialogueId"] = 80230409,
            ["GUID"] = "C8D9317A",
            ["NextDialogue"] = 80230410,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9317A",
            },
        [80230410] = {
            ["Content"] = "殊不知论心狠手辣，我可连你的皮毛都够不上。",
            ["ContentJP"] = "だがね、「残酷」という点では、私はあなたの足元にも及ばないよ。",
            ["DialogueId"] = 80230410,
            ["GUID"] = "C8D931A4",
            ["NextDialogue"] = 80230411,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D931A4",
            },
        [80230411] = {
            ["Content"] = "可我看你不是很喜欢那位小友吗？为了所谓的大计，把自己逼到众叛亲离的那一天，这对你而言真的值得吗？",
            ["ContentJP"] = "……本当は、あの子のこと、結構気に入ってるんじゃないか？それでも大義のために、味方を失ってまで突き進むつもりか？たとえ最後に、誰ひとり残らなくなったとしても――それで、本当に悔いはないのかい？",
            ["DialogueId"] = 80230411,
            ["GUID"] = "C8D931CE",
            ["NextDialogue"] = 80230412,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D931CE",
            },
        [80230412] = {
            ["Content"] = "秦虬，勿对自己不了解的事情妄加评论，我以为这是为人的基本。",
            ["ContentJP"] = "キョウン、知りもしないことで軽々しく語らないこと。それが、人として最低限の分別だと、私は思っている。",
            ["DialogueId"] = 80230412,
            ["GUID"] = "C8D931F8",
            ["NextDialogue"] = 80230413,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D931F8",
            },
        [80230413] = {
            ["Content"] = "你我不过暂且利益一致，各取所需。无论是你所言的“大计”，抑或是我的目的，你都不了解分毫。",
            ["ContentJP"] = "あなたと私の関係など、利が一致しているから成り立っているだけのこと。大義とやらも、私の真意も――あなたは何一つ知る必要すらない。",
            ["DialogueId"] = 80230413,
            ["GUID"] = "C8D93222",
            ["NextDialogue"] = 80230414,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93222",
            },
        [80230414] = {
            ["Content"] = "怎么生气了？这么开不起玩笑，消消气消消气。",
            ["ContentJP"] = "あれまあ……お怒りかい？いやいや、冗談だってば。なに、そんなに本気にしなさんな。ほら、怒りは体に毒だよ。",
            ["DialogueId"] = 80230414,
            ["GUID"] = "C8D9324C",
            ["NextDialogue"] = 80230415,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9324C",
            },
        [80230415] = {
            ["Content"] = "止流大当家——您在这里吗？",
            ["ContentJP"] = "シリュウ当主！いらっしゃいますか？",
            ["DialogueId"] = 80230415,
            ["GUID"] = "C8D93276",
            ["NextDialogue"] = 80230416,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93276",
            },
        [80230416] = {
            ["Content"] = "呵呵，你的助手来找你了。看来比起在这里讨人嫌，我也该告辞了。",
            ["ContentJP"] = "おや、助っ人のお出ましだ。これ以上居座っても嫌われるだけだし、私もこの辺で引くとしよう。",
            ["DialogueId"] = 80230416,
            ["GUID"] = "C8D932A0",
            ["NextDialogue"] = 80230417,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D932A0",
            },
        [80230417] = {
            ["Content"] = "您这龙渊上卿大忙人，就不用在我这个见不得光的闲人身上浪费时间了。",
            ["ContentJP"] = "――なに、<Default note=\"text:りょうえんのしょうけい\">龍淵の上卿</>たるお方の貴重な時間を、日陰者の私ごときが奪っては申し訳ないからね。",
            ["DialogueId"] = 80230417,
            ["GUID"] = "C8D932CA",
            ["NextDialogue"] = 80230418,
            ["SpeakNpcId"] = 790079,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D932CA",
            },
        [80230418] = {
            ["Content"] = "那便不送了。",
            ["ContentJP"] = "ご自由に。",
            ["DialogueId"] = 80230418,
            ["GUID"] = "C8D932F4",
            ["NextDialogue"] = 80230419,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D932F4",
            },
        [80230419] = {
            ["DialogueId"] = 80230419,
            ["GUID"] = "C8D9331E",
            ["NextDialogue"] = 80230420,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9331E",
            },
        [80230420] = {
            ["Content"] = "止流大当家，百年春那里有些举棋不定的事，需要您去拿一下主意。",
            ["ContentJP"] = "シリュウ当主、<Default note=\"text:ももとき\">百年春</>の件ですが……少し意見が分かれいます。ご判断を仰ぎたいのですが……",
            ["DialogueId"] = 80230420,
            ["GUID"] = "C8D93348",
            ["NextDialogue"] = 80230421,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93348",
            },
        [80230421] = {
            ["Content"] = "好。",
            ["ContentJP"] = "わかった。",
            ["DialogueId"] = 80230421,
            ["GUID"] = "C8D93372",
            ["NextDialogue"] = 80230422,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93372",
            },
        [80230422] = {
            ["Content"] = "大当家，您看起来好像有点累了……？",
            ["ContentJP"] = "あの……少し、お疲れのようですね？",
            ["DialogueId"] = 80230422,
            ["GUID"] = "C8D9339C",
            ["NextDialogue"] = 80230423,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9339C",
            },
        [80230423] = {
            ["Content"] = "……呵呵，没什么大碍。秦虬还是如以往一般问东问西，为了应付他，我不得已说了太多话。",
            ["ContentJP"] = "……ふふ、大したことではないわ。キョウンが相変わらずあれこれ詮索してくるものだから――つい、余計な話まで引き出されてしまったの。",
            ["DialogueId"] = 80230423,
            ["GUID"] = "C8D933C6",
            ["NextDialogue"] = 80230424,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D933C6",
            },
        [80230424] = {
            ["Content"] = "不过，倒是聊到了你我在执律阁下相识的过往。没想到一转眼也是数年过去了。",
            ["ContentJP"] = "でも、ふとあなたと私が初めて出会った時のことを思い出したわ。気づけば、もう何年も昔の話ね。",
            ["DialogueId"] = 80230424,
            ["GUID"] = "C8D933F0",
            ["NextDialogue"] = 80230425,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D933F0",
            },
        [80230425] = {
            ["Content"] = "哇，你们竟然聊到了那么久远的往事！",
            ["ContentJP"] = "えっ、そんな昔のことまで……！",
            ["DialogueId"] = 80230425,
            ["GUID"] = "C8D9341A",
            ["NextDialogue"] = 80230426,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9341A",
            },
        [80230426] = {
            ["Content"] = "那时候为了给救我的医师伸冤，我在执律阁底下站了那么多天，看够了别人的冷眼，其实已经不抱什么希望了。",
            ["ContentJP"] = "あの頃、私はただ、命を救ってくれた医師の冤罪を晴らしたくて、<Default note=\"text:しつりつかく\">執律閣</>の前に立ち尽くしてた。何日も、冷たい視線にさらされながら、もう絶望だって……そんな気持ちでいたんです。",
            ["DialogueId"] = 80230426,
            ["GUID"] = "C8D93444",
            ["NextDialogue"] = 80230427,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93444",
            },
        [80230427] = {
            ["Content"] = "您来劝说我时，我虽然勉强反驳了几句，但心中已经生出恐怕只能到这里为止了的念头。",
            ["ContentJP"] = "あなたが声をかけてくださった時、口では何か言い返したけど――本当は、もう自分でも、あそこで終わりだと思ってたんです。",
            ["DialogueId"] = 80230427,
            ["GUID"] = "C8D9346E",
            ["NextDialogue"] = 80230428,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9346E",
            },
        [80230428] = {
            ["Content"] = "却没想到您当时会对我说……",
            ["ContentJP"] = "でも、まさかあの時……あなたが、あんなふうに言ってくださるとは思わなくて――",
            ["DialogueId"] = 80230428,
            ["GUID"] = "C8D93498",
            ["NextDialogue"] = 80230429,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93498",
            },
        [80230429] = {
            ["Content"] = "我以无穷藏派秘法遮蔽了我们的声音。接下来的这些话，包括现在的这份无力感，你都必须牢牢铭记，然后再也不和旁人提起。",
            ["ContentJP"] = "……今、<Default note=\"text:むきゅうぞうは\">無窮蔵派</>の秘術で音を遮った。これから話すことも、今感じているその無力さも――全部、心に刻みなさい。そして誰にも話してはダメよ。",
            ["DialogueId"] = 80230429,
            ["GUID"] = "C8D934C2",
            ["NextDialogue"] = 80230430,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D934C2",
            },
        [80230430] = {
            ["Content"] = "我曾经与你一样，为了清白之人的冤屈，在这执律阁下四处奔走。很快，我意识到这一行为无异于以卵击石。",
            ["ContentJP"] = "……私もかつて、あなたと同じだった。潔白な者の冤屈を晴らすために、ここを奔走していた時期がある。けれどすぐに思い知ったわ。それは、焼け石に水のようなものだと。",
            ["DialogueId"] = 80230430,
            ["GUID"] = "C8D934EC",
            ["NextDialogue"] = 80230431,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D934EC",
            },
        [80230431] = {
            ["Content"] = "蚍蜉之力，如何撼树？大风九章是一整个庞大的不以个人意志为转移的体系。",
            ["ContentJP"] = "アリが巨木を揺らすことはできない。<Default note=\"text:たいふうきゅうしょう\">大風九章</>とは、個の意志では動かせぬ土台――理不尽の集合体よ。",
            ["DialogueId"] = 80230431,
            ["GUID"] = "C8D93516",
            ["NextDialogue"] = 80230432,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93516",
            },
        [80230432] = {
            ["Content"] = "现在这样做，除了让你的良心好受一点，此外毫无作用。到了最后，世界照常运转，不会产生丝毫变化。而你会在日复一日中背离当初的执着。",
            ["ContentJP"] = "いま行っているのは、せいぜい自分の良心を慰める行為にすぎない。この世界は、何ひとつ変わらず回り続け、やがてあなた自身が、その信念を忘れていく。",
            ["DialogueId"] = 80230432,
            ["GUID"] = "C8D93540",
            ["NextDialogue"] = 80230433,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93540",
            },
        [80230433] = {
            ["Content"] = "所以——你现在需要暂时妥协，但我可以承诺你一件事。",
            ["ContentJP"] = "だから――いまは一度、折れなさい。その代わり、約束するわ。",
            ["DialogueId"] = 80230433,
            ["GUID"] = "C8D9356A",
            ["NextDialogue"] = 80230434,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9356A",
            },
        [80230434] = {
            ["Content"] = "大风九章宣告终结的一天将会来临。我会不惜代价使这错置颠倒的一切重新归位……你愿意相信我吗？",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>が終わりを迎える日が、必ず来る。その日までに、私はすべてをあるべき形に戻してみせる。……信じてくれるかしら？",
            ["DialogueId"] = 80230434,
            ["GUID"] = "C8D93594",
            ["NextDialogue"] = 80230435,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93594",
            },
        [80230435] = {
            ["DialogueId"] = 80230435,
            ["GUID"] = "C8D935BE",
            ["NextDialogue"] = 80230436,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D935BE",
            },
        [80230436] = {
            ["Content"] = "时间过得真快，没想到您当年对我许下的承诺，眼看着就要实现了……不过大当家，您最近疲于奔波，面容都憔悴了许多，还是要以自己的身体为重啊！",
            ["ContentJP"] = "時間の流れというのは、本当に早いものですね……あの日の約束が、もうすぐ現実になろうとしているなんて。でも当主様、最近すこし詰め込みすぎですよ。顔色もあまりよくないし、身体を大事にしてくださいね。",
            ["DialogueId"] = 80230436,
            ["GUID"] = "C8D935E8",
            ["NextDialogue"] = 80230437,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D935E8",
            },
        [80230437] = {
            ["Content"] = "放心，我心中有数。",
            ["ContentJP"] = "……大丈夫よ。自分の限界くらい、わかってるつもり。",
            ["DialogueId"] = 80230437,
            ["GUID"] = "C8D93612",
            ["NextDialogue"] = 80230438,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93612",
            },
        [80230438] = {
            ["Content"] = "大当家，你知道吗？有很多人怕你，惧你，在背后腹诽于你。",
            ["ContentJP"] = "当主様、あなたを恐れてる人や、嫌ってる人、案外多いんですよ。",
            ["DialogueId"] = 80230438,
            ["GUID"] = "C8D9363C",
            ["NextDialogue"] = 80230439,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D9363C",
            },
        [80230439] = {
            ["Content"] = "那些人说你铁石心肠，行事如同修罗，只会做做表面的慈善工夫，但只有我知道……您是什么样的人。",
            ["ContentJP"] = "「情のない人だ」「冷酷で人形みたいな修羅だ」――でも、私は知ってます。あなたがどんな想いで、何を背負っているのか。",
            ["DialogueId"] = 80230439,
            ["GUID"] = "C8D93666",
            ["NextDialogue"] = 80230440,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93666",
            },
        [80230440] = {
            ["Content"] = "我非常佩服您的那份决心！跟在您身边越久，我越感谢，那一天遇到的是您。",
            ["ContentJP"] = "その覚悟、本当に尊敬してます！側においてくださり、感謝しています。あの時、出会えたのがあなたで――本当に、よかった。",
            ["DialogueId"] = 80230440,
            ["GUID"] = "C8D93690",
            ["NextDialogue"] = 80230441,
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D93690",
            },
        [80230441] = {
            ["Content"] = "呵呵……怎么突然说这么多，与其有逞这些口舌之快的功夫，不如再多做点实事。",
            ["ContentJP"] = "ふふ……どうしたの、急に。私に感謝するのは、百年春の件を片づけてからでいいわ。",
            ["DialogueId"] = 80230441,
            ["GUID"] = "C8D936BA",
            ["NextDialogue"] = 80230442,
            ["SpeakNpcId"] = 790076,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D936BA",
            },
        [80230442] = {
            ["Content"] = "我知道啦，大当家——",
            ["ContentJP"] = "わかってますって、当主様！",
            ["DialogueId"] = 80230442,
            ["GUID"] = "C8D936E4",
            ["SpeakNpcId"] = 790077,
            ["VoiceName"] = "voice/$Locale$/inv/Zhiliu/004/C8D936E4",
            },
        [80240101] = {
            ["Content"] = "小苏？在这做什么呢。",
            ["ContentJP"] = "スー？こんなところで何をしてるんだい？",
            ["DialogueId"] = 80240101,
            ["GUID"] = "C8DF6792",
            ["NextDialogue"] = 80240102,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "790082.0",
            },
        [80240102] = {
            ["Content"] = "好不容易天气放晴了，我晒点东西。",
            ["ContentJP"] = "ちょっと、干したいものがあって……珍しく晴れたから。",
            ["DialogueId"] = 80240102,
            ["GUID"] = "C8DF67BC",
            ["NextDialogue"] = 80240103,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF67BC",
            },
        [80240103] = {
            ["Content"] = "好哇，唐叔！你又不带拐杖，跟你说了好几次，你的腿才好些呢，不能受太多的力。你不是刚换完拐杖吗，这个款式也不喜欢？",
            ["ContentJP"] = "あれ？タンさん、まーた杖忘れてる！もう、何回言わせるの。足、やっと良くなってきたところなんだから、ちゃんと労わりなさいよ。新しいの……デザイン気に入らなかった？",
            ["DialogueId"] = 80240103,
            ["GUID"] = "C8DF67E6",
            ["NextDialogue"] = 80240104,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF67E6",
            },
        [80240104] = {
            ["Content"] = "这拐杖可是小苏亲自给我做的，唐叔不舍得用啊。",
            ["ContentJP"] = "いやいや、スーが作ってくれたもんだろ？もったいなくて使えないんだよ。",
            ["DialogueId"] = 80240104,
            ["GUID"] = "C8DF6810",
            ["NextDialogue"] = 80240105,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6810",
            },
        [80240105] = {
            ["Content"] = "做出来不用，放在那儿吃灰就舍得了？算了，现在也来不及拿了，唐叔你就勉勉强强，把我当拐杖吧。来，唐叔，我扶着你。",
            ["ContentJP"] = "使わないでホコリかぶせるのは平気なんだ？……ったく、今さら取りに戻れないし、もういいわ。今日は私が杖になってあげる。ほら、つかまって。",
            ["DialogueId"] = 80240105,
            ["GUID"] = "C8DF683A",
            ["NextDialogue"] = 80240106,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF683A",
            },
        [80240106] = {
            ["Content"] = "哎哟……小苏啊，真没到那个地步，唐叔这个年纪，撑着拐杖出门，人还以为唐叔七老八十了呢，多丢人啊。",
            ["ContentJP"] = "はは……スーよ、そこまでじゃない。杖なんぞついて歩いたら、「もう七十過ぎのジジイか」って思われるだろ？なんだか情けなくてな。",
            ["DialogueId"] = 80240106,
            ["GUID"] = "C8DF6864",
            ["NextDialogue"] = 80240107,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6864",
            },
        [80240107] = {
            ["Content"] = "哼哼，这才是唐叔的真心话，被我套出来了吧~但是不行！",
            ["ContentJP"] = "あー、やっぱそれが本音だったのね。でもダメ！甘やかしませんよっ！",
            ["DialogueId"] = 80240107,
            ["GUID"] = "C8DF688E",
            ["NextDialogue"] = 80240108,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF688E",
            },
        [80240108] = {
            ["Content"] = "药师说，不能听病人的意见，你这腿不是第一次摔了，得多看顾着，免得落下病根。",
            ["ContentJP"] = "薬師さんにもね、「平気って言う患者ほど信用するな」って言われたし。前転んだ時のこと、忘れたの？ちゃんと労わらないと、ずっと引きずることになるんだから。",
            ["DialogueId"] = 80240108,
            ["GUID"] = "C8DF68B8",
            ["NextDialogue"] = 80240109,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF68B8",
            },
        [80240109] = {
            ["Content"] = "好小苏，饶了唐叔吧，别去跟药师告状了。你都知道要让放久了的物什见见光，唐叔在床上躺了半个月了，也得出来晒晒太阳。",
            ["ContentJP"] = "ああもう、スー、薬師にチクるのだけは勘弁してくれよ。長く仕舞ってた物は陽に当てろって言うだろ？俺もさ、半月も寝たきりだったんだから、たまには日に当たりたくもなるさ。",
            ["DialogueId"] = 80240109,
            ["GUID"] = "C8DF68E2",
            ["NextDialogue"] = 80240110,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF68E2",
            },
        [80240110] = {
            ["Content"] = "快不说这个了，让唐叔看看，你这忙前忙后的，这晒的是什么东西啊？",
            ["ContentJP"] = "……で、そんなにあたふたと、何を干してたんだ？",
            ["DialogueId"] = 80240110,
            ["GUID"] = "C8DF690C",
            ["NextDialogue"] = 80240111,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF690C",
            },
        [80240111] = {
            ["Content"] = "这是——",
            ["ContentJP"] = "ああ、それは……",
            ["DialogueId"] = 80240111,
            ["GUID"] = "C8DF6936",
            ["NextDialogue"] = 80240112,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6936",
            },
        [80240112] = {
            ["Content"] = "这是……抱抱鸟，一种能发热的机傀玩具。小时候我不爱睡觉，爸妈就做了这个，拿它哄我。我一抱住它，就能睡得着了。",
            ["ContentJP"] = "……「ウパシ」っていうの、あったかくなるからくりだよ。子どもの頃、寝つけないときは、これ抱いて寝てたの。両親が作ってくれてさ。これがあると、すーって眠れたんだよね。",
            ["DialogueId"] = 80240112,
            ["GUID"] = "C8DF6960",
            ["NextDialogue"] = 80240113,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6960",
            },
        [80240113] = {
            ["Content"] = "哟，这么一看有印象了。这不是小苏每年都要买上一只的那个吗？",
            ["ContentJP"] = "ああ、そう言えば……思い出したぞ。スー、毎年こっそり買ってたやつだよな？",
            ["DialogueId"] = 80240113,
            ["GUID"] = "C8DF698A",
            ["NextDialogue"] = 80240114,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF698A",
            },
        [80240114] = {
            ["Content"] = "唐叔？！我不是都藏起来了吗，唐叔你——你在哪里见到的呀？",
            ["ContentJP"] = "えっ、見てたの！？うまく隠せてると思ってたのに……どこで見たの！？",
            ["DialogueId"] = 80240114,
            ["GUID"] = "C8DF69B4",
            ["NextDialogue"] = 80240115,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF69B4",
            },
        [80240115] = {
            ["Content"] = "小苏年年都要买，买了之后又不开心，唐叔都看在眼里，担心着呢。",
            ["ContentJP"] = "そりゃ気づくさ。毎年買ってるのに、ちっともうれしそうな顔しないんだから……ずっと心配してたんだよ。",
            ["DialogueId"] = 80240115,
            ["GUID"] = "C8DF69DE",
            ["NextDialogue"] = 80240116,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF69DE",
            },
        [80240116] = {
            ["Content"] = "那会儿小苏刚来山外山，嘴巴像蚌壳一样，时常一个人闷着不说话。唐叔当时没找到机会问一问你，现在终于好跟小苏说点知心话了。",
            ["ContentJP"] = "スーが<Default note=\"text:さんがいさん\">山外山</>に来たばっかの頃を思い出すよ。ひとりで黙って座ってることが多かった。聞きたいことは山ほどあったけど、タイミングを逃しちゃってな。今じゃこうして話せるようになったけど。",
            ["DialogueId"] = 80240116,
            ["GUID"] = "C8DF6A08",
            ["NextDialogue"] = 80240117,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A08",
            },
        [80240117] = {
            ["Content"] = "现在想想，小苏……莫不是想家了？",
            ["ContentJP"] = "なあ、スー。本当は、家が恋しいんじゃないか？",
            ["DialogueId"] = 80240117,
            ["GUID"] = "C8DF6A32",
            ["NextDialogue"] = 80240118,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A32",
            },
        [80240118] = {
            ["Content"] = "才没有！我家里人就在皓京，离得又不远，我想回去就回去了，有什么好想的。",
            ["ContentJP"] = "ないない！だって家、<Default note=\"text:こうけい\">皓京</>にあるし、そんなに遠くないでしょ？ 帰りたくなったら帰ればいいだけだし。",
            ["DialogueId"] = 80240118,
            ["GUID"] = "C8DF6A5C",
            ["NextDialogue"] = 80240119,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A5C",
            },
        [80240119] = {
            ["Content"] = "呵呵……若是家是想回去就能回去的地方，也不至于有这么多飘零的游子了。",
            ["ContentJP"] = "ははっ、そんな容易なら、この世にはきっと、「さすらい人」なんていないんだろうなぁ。",
            ["DialogueId"] = 80240119,
            ["GUID"] = "C8DF6A86",
            ["NextDialogue"] = 80240120,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6A86",
            },
        [80240120] = {
            ["Content"] = "和唐叔说说，小苏是因为什么不愿意回家？是不是最近太累了，身体撑不住，怕让家里人担心？",
            ["ContentJP"] = "スーが帰りたくない本当の理由、よかったら教えてくれないか？最近疲れてる？体がきつくて、家族に心配かけたくないとか？",
            ["DialogueId"] = 80240120,
            ["GUID"] = "C8DF6AB0",
            ["NextDialogue"] = 80240121,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6AB0",
            },
        [80240121] = {
            ["Content"] = "没什么啦，就是没时间回去而已！我自己的身体我心里有数，你看，我能跑能跳的，特别健康。",
            ["ContentJP"] = "違うってば。ただ、帰る時間がないだけ！ それに、体のことは自分が一番わかってるから。ね、ほら、見て。ピンピンしてるでしょ。",
            ["DialogueId"] = 80240121,
            ["GUID"] = "C8DF6ADA",
            ["NextDialogue"] = 80240122,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6ADA",
            },
        [80240122] = {
            ["Content"] = "不是身体上的问题，就是心里的问题喽？",
            ["ContentJP"] = "体じゃないなら、心のほうか？",
            ["DialogueId"] = 80240122,
            ["GUID"] = "C8DF6B04",
            ["NextDialogue"] = 80240123,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B04",
            },
        [80240123] = {
            ["Content"] = "都说了我没……",
            ["ContentJP"] = "だから違うって……",
            ["DialogueId"] = 80240123,
            ["GUID"] = "C8DF6B2E",
            ["NextDialogue"] = 80240124,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B2E",
            },
        [80240124] = {
            ["Content"] = "……好吧！真是什么都瞒不过唐叔，我是有点想家。",
            ["ContentJP"] = "っ……もう。ほんと何でも見抜かれちゃうな私……はい、ちょっとだけ。ほんのちょっとだけ……寂しい、かも。",
            ["DialogueId"] = 80240124,
            ["GUID"] = "C8DF6B58",
            ["NextDialogue"] = 80240125,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B58",
            },
        [80240125] = {
            ["Content"] = "难不成是纠结带什么礼物？你这些年的发明，随意拿回去一个，就够让人刮目相看了。",
            ["ContentJP"] = "そっか。じゃあ、お土産に迷ってるのか？スーの作った発明、なんでも持って帰れば、皆びっくりすると思うぞ。",
            ["DialogueId"] = 80240125,
            ["GUID"] = "C8DF6B82",
            ["NextDialogue"] = 80240126,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6B82",
            },
        [80240126] = {
            ["Content"] = "不是啦，我爸妈不喜欢机枢，看见我研究机枢就来气，更不会因为这个夸我。礼物带这个，那是火上浇油了。",
            ["ContentJP"] = "それは無理。あの人たち、<Default note=\"text:きすう\">機枢</>術が大嫌いだからね。ちょっと研究しただけで睨まれるし、褒められたことなんて一度もない。持って帰ったりしたら、余計に怒られるかもね。",
            ["DialogueId"] = 80240126,
            ["GUID"] = "C8DF6BAC",
            ["NextDialogue"] = 80240127,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6BAC",
            },
        [80240127] = {
            ["Content"] = "我……从小就很喜欢机枢术，学的也很快。天工苏氏古籍所载技法，我看一遍就会，哪怕是缺页少字的篇章，我也能看得懂，还能自行补全。",
            ["ContentJP"] = "……私、小さい頃から機枢が大好きだったの。覚えるのも早かったし、うちの家系の古書も一度読んだら大体わかっちゃう。欠けてるページも、自分で補えるくらいにはね。",
            ["DialogueId"] = 80240127,
            ["GUID"] = "C8DF6BD6",
            ["NextDialogue"] = 80240128,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6BD6",
            },
        [80240128] = {
            ["Content"] = "我喜欢机枢，也喜欢研究机枢，但是爸妈不喜欢，他们不希望我学这个。",
            ["ContentJP"] = "でも、両親はそれが気に入らなかった。「女の子がやるもんじゃない」って。",
            ["DialogueId"] = 80240128,
            ["GUID"] = "C8DF6C00",
            ["NextDialogue"] = 80240129,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C00",
            },
        [80240129] = {
            ["Content"] = "家里……就是父母的一言堂，他们不喜欢，我就也不能喜欢。幸好还有姑姑在，会偷偷地教我机枢知识，陪我一起拆卸研究。",
            ["ContentJP"] = "家の中じゃ、あの人たちの言うことが絶対だったから、正直に好きって言えなかった。でも、叔母だけは違った。色んな事をこっそり教えてくれたの。一緒に部品をばらして、研究して……それがすごく楽しくてさ。",
            ["DialogueId"] = 80240129,
            ["GUID"] = "C8DF6C2A",
            ["NextDialogue"] = 80240130,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C2A",
            },
        [80240130] = {
            ["Content"] = "呵呵，现在大风九章可是大变样咯，机枢派的往事也翻了盘。你父母心里头的想法，指不定有所改变呢。人呐，都是在向前走的。",
            ["ContentJP"] = "はは、今じゃ<Default note=\"text:たいふうきゅうしょう\">大風九章</>ガラッと変わったからな。<Default note=\"text:きすうは\">機枢派</>の評価だってひっくり返った。ご両親の考え方も、もしかしたら少しずつ変わってるかもしれんぞ。人の気持ちって、前に進むもんだからな。",
            ["DialogueId"] = 80240130,
            ["GUID"] = "C8DF6C54",
            ["NextDialogue"] = 80240131,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C54",
            },
        [80240131] = {
            ["Content"] = "但是……这毕竟不算他们眼里的正道，再说，这么些年对我不闻不问，肯定是还没原谅我。",
            ["ContentJP"] = "でもさ……あの人たちにとっては、「外れた生き方」にしか見えないと思う。それに、この何年もずっと音沙汰なしだよ。きっと、まだ許してくれてないんだ……",
            ["DialogueId"] = 80240131,
            ["GUID"] = "C8DF6C7E",
            ["NextDialogue"] = 80240132,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6C7E",
            },
        [80240132] = {
            ["Content"] = "来山外山的时候跟家里人吵架了？",
            ["ContentJP"] = "<Default note=\"text:さんがいさん\">山外山</>に来るとき、家と揉めたのか？",
            ["DialogueId"] = 80240132,
            ["GUID"] = "C8DF6CA8",
            ["NextDialogue"] = 80240133,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6CA8",
            },
        [80240133] = {
            ["Content"] = "嗯……我走的时候，跟爸妈说了一些不太好的话。爸妈也说，以后就当没我这个女儿。",
            ["ContentJP"] = "うん……出ていくとき、私もひどいこと言ったし……あの人たちも、「もうお前とは縁を切る」って……",
            ["DialogueId"] = 80240133,
            ["GUID"] = "C8DF6CD2",
            ["NextDialogue"] = 80240134,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6CD2",
            },
        [80240134] = {
            ["Content"] = "在家的时候，每逢年关新至，爸妈就会送我一只新的抱抱鸟，我失眠的时候，抱着它就能睡得着。",
            ["ContentJP"] = "毎年、年が明けるたびに、両親が新しいウパシを作ってくれたの。眠れないときは、それを抱いて眠ってた。",
            ["DialogueId"] = 80240134,
            ["GUID"] = "C8DF6CFC",
            ["NextDialogue"] = 80240135,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6CFC",
            },
        [80240135] = {
            ["Content"] = "我最后悔的一件事，就是离家出走的时候没有揣上两只抱抱鸟，害得我刚来山外山时彻夜难眠。幸好后来在往返于山外山的商人那买到了差不多的。",
            ["ContentJP"] = "一番後悔してるのは……家を出るときに、それを持ってこなかったこと。二つくらいカバンに入れとけばよかった。<Default note=\"text:さんがいさん\">山外山</>に来てすぐの頃、毎晩眠れなかった。でもね、あとから行商人が持ってきたやつの中に、すごく似たのがあって……",
            ["DialogueId"] = 80240135,
            ["GUID"] = "C8DF6D26",
            ["NextDialogue"] = 80240136,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6D26",
            },
        [80240136] = {
            ["Content"] = "这个……真的很像我爸妈做的，但是针脚密密的，手艺比我爸妈好多了。",
            ["ContentJP"] = "ほんとにそっくりだった。両親が作ってくれたのと。けど……両親のものの方が縫い目はもっと細かくて、仕上がりもずっと綺麗だった。",
            ["DialogueId"] = 80240136,
            ["GUID"] = "C8DF6D50",
            ["NextDialogue"] = 80240137,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6D50",
            },
        [80240137] = {
            ["Content"] = "我每次看到都会忍不住买下来，又不敢仔细看太久，怕自己难过。买回来就匆匆塞进箱子里，扣上盖子推回床底下，好像什么都没发生过。",
            ["ContentJP"] = "見かけるたびに、つい買っちゃって……でも、長く見てられなくて。胸がギュッてなるから、すぐ箱にしまって、ふたを閉めて、ベッドの下に押し込んで……何もなかったふりしてた。",
            ["DialogueId"] = 80240137,
            ["GUID"] = "C8DF6D7A",
            ["NextDialogue"] = 80240138,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6D7A",
            },
        [80240138] = {
            ["Content"] = "……很自欺欺人，对吧？我也意识到，不能再继续逃避了。",
            ["ContentJP"] = "……バカみたいでしょ。自分でもわかってるの。逃げてばっかじゃダメなんだって。",
            ["DialogueId"] = 80240138,
            ["GUID"] = "C8DF6DA4",
            ["NextDialogue"] = 80240139,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6DA4",
            },
        [80240139] = {
            ["Content"] = "这几天取出来，发现它们落了好多灰。我把灰尘拍掉，又怕它们发霉，所以晾晒一下……看着这些抱抱鸟，我就又想起家里的事情了。",
            ["ContentJP"] = "このあいだ久々に箱を開けたら、ウパシたちがホコリまみれになっててさ。払っても払っても、粉みたいに積もってて……カビる前に干しとこうと思って、持ち出したの。",
            ["DialogueId"] = 80240139,
            ["GUID"] = "C8DF6DCE",
            ["NextDialogue"] = 80240140,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6DCE",
            },
        [80240140] = {
            ["Content"] = "之前是我的身份不方便走动，也怕连累他们，不敢回家。",
            ["ContentJP"] = "でも……こうして見てると、やっぱり思い出すんだ。家のこと、昔のこと……前は、立場的に、帰るに帰れなかった。何かあったら、向こうにも迷惑かけるし……",
            ["DialogueId"] = 80240140,
            ["GUID"] = "C8DF6DF8",
            ["NextDialogue"] = 80240141,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6DF8",
            },
        [80240141] = {
            ["Content"] = "最近华胥的天变了，我就想……",
            ["ContentJP"] = "でも最近、<Default note=\"text:カショ\">華胥</>もなんだか空気が変わってきた気がして……ちょっとだけ、考えた。",
            ["DialogueId"] = 80240141,
            ["GUID"] = "C8DF6E22",
            ["NextDialogue"] = 80240142,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6E22",
            },
        [80240142] = {
            ["Content"] = "……唐叔，我不敢想。我想回去，可是我不敢回去……我该怎么办？",
            ["ContentJP"] = "でも、怖いんだ。帰りたいのに、足がすくむ。",
            ["DialogueId"] = 80240142,
            ["GUID"] = "C8DF6E4C",
            ["NextDialogue"] = 80240143,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6E4C",
            },
        [80240143] = {
            ["Content"] = "要是他们没原谅我，赶我走，不承认我是他们的女儿，那我、那我……",
            ["ContentJP"] = "もし……もし、あの人たちがまだ許してなくて、「帰ってくるな」って言われたら……「もうお前は娘じゃない」って言われたら……私……",
            ["DialogueId"] = 80240143,
            ["GUID"] = "C8DF6E76",
            ["NextDialogue"] = 80240144,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6E76",
            },
        [80240144] = {
            ["Content"] = "我们小苏啊，心思细，想得也多，这是好事。只是有时候，不必考虑那么多，负担都在心里坠着，多沉、多难受啊。",
            ["ContentJP"] = "スーは、本当に優しい子だな。いろんなこと、よく考えて……それは立派なことだよ。だけど、ときには考えすぎて、心に抱え込みすぎることもある。",
            ["DialogueId"] = 80240144,
            ["GUID"] = "C8DF6EA0",
            ["NextDialogue"] = 80240145,
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6EA0",
            },
        [80240145] = {
            ["Content"] = "想家了，就回去看看吧。",
            ["ContentJP"] = "……会いたいと思ったら、会いに行ってみたらどうだ？家が恋しいなら、一度帰ってみるといい。",
            ["DialogueId"] = 80240145,
            ["GUID"] = "C8DF6ECA",
            ["SpeakNpcId"] = 790083,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/001/C8DF6ECA",
            },
        [80240201] = {
            ["Content"] = "四年前",
            ["ContentJP"] = "四年前",
            ["DialogueId"] = 80240201,
            ["GUID"] = "C8DF77FA",
            ["NextDialogue"] = 80240202,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF77FA",
            },
        [80240202] = {
            ["Content"] = "小黑，我要走了。我走之后，爸妈只能托你来照顾了。",
            ["ContentJP"] = "クロ、もう行くね。パパとママのこと、頼んだよ。",
            ["DialogueId"] = 80240202,
            ["GUID"] = "C8DF7824",
            ["NextDialogue"] = 80240203,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7824",
            },
        [80240203] = {
            ["Content"] = "你可得时不时来巡逻一番，把那坏耗子统统逮住，别让家里的米粮遭了殃。要是我走后爸妈寂寞了，你也替我去他们脚旁蹭上两圈……",
            ["ContentJP"] = "時々パトロールして、あの悪さするネズミたち、ぜーんぶ追っ払ってよ。米とか食べられたら困るから。……もし二人が寂しそうにしてたら、私の代わりに、足元でぐるぐるっと甘えてやって。",
            ["DialogueId"] = 80240203,
            ["GUID"] = "C8DF784E",
            ["NextDialogue"] = 80240204,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF784E",
            },
        [80240204] = {
            ["Content"] = "喵~",
            ["ContentJP"] = "にゃ～",
            ["DialogueId"] = 80240204,
            ["GUID"] = "C8DF7878",
            ["NextDialogue"] = 80240205,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7878",
            },
        [80240205] = {
            ["Content"] = "最后检查一遍行李。两套衣裳，榫卯青铜工具各一套，姑姑留给我的图纸……",
            ["ContentJP"] = "さて……荷物の最終チェック。服二着に工具セット一式、それから叔母が遺してくれた設計図……よし。",
            ["DialogueId"] = 80240205,
            ["GUID"] = "C8DF78A2",
            ["NextDialogue"] = 80240206,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF78A2",
            },
        [80240206] = {
            ["Content"] = "糟糕，抱抱鸟忘带了，得再回去拿一趟——",
            ["ContentJP"] = "やば、ウパシちゃん忘れた。取りに戻らなきゃ——",
            ["DialogueId"] = 80240206,
            ["GUID"] = "C8DF78CC",
            ["NextDialogue"] = 80240207,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF78CC",
            },
        [80240207] = {
            ["Content"] = "既已下定决心要走，这家此后与你就再无瓜葛。又何必再进进出出，反反复复，牵扯不休。",
            ["ContentJP"] = "家を出ると決めたのなら、この家との縁も、それっきりよ。何度も出たり入ったりして、気持ちを引きずるのはおやめなさい。",
            ["DialogueId"] = 80240207,
            ["GUID"] = "C8DF78F6",
            ["NextDialogue"] = 80240208,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF78F6",
            },
        [80240208] = {
            ["Content"] = "……妈，你怎么还醒着？",
            ["ContentJP"] = "……ママ？まだ起きてたの……？",
            ["DialogueId"] = 80240208,
            ["GUID"] = "C8DF7920",
            ["NextDialogue"] = 80240209,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7920",
            },
        [80240209] = {
            ["Content"] = "我还以为你早就睡了。难不成是看到我留在桌上的信了？",
            ["ContentJP"] = "もう寝たと思ってた。まさか、机の上に置いた手紙……読んじゃった？",
            ["DialogueId"] = 80240209,
            ["GUID"] = "C8DF794A",
            ["NextDialogue"] = 80240210,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF794A",
            },
        [80240210] = {
            ["Content"] = "那个，就像我信里写的一样啦，你们的女儿要去追求理想了，但以后有机会还会常回来看看的，不用为我担心……",
            ["ContentJP"] = "書いてあったとおりだよ。私、自分の夢を追いに行くの。でもまた帰ってくるつもりだし、心配なんて——",
            ["DialogueId"] = 80240210,
            ["GUID"] = "C8DF7974",
            ["NextDialogue"] = 80240211,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7974",
            },
        [80240211] = {
            ["Content"] = "够了，休要再说这些儿戏之言。",
            ["ContentJP"] = "もういい。そんな子どもじみた言い訳、聞き飽きたわ。",
            ["DialogueId"] = 80240211,
            ["GUID"] = "C8DF799E",
            ["NextDialogue"] = 80240212,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF799E",
            },
        [80240212] = {
            ["Content"] = "你是我怀胎十月生下的骨肉，你那心思自以为藏得很好，我实际一看即知。是我平时太娇纵于你，才把你养得这般离经叛道，不知天高地厚。",
            ["ContentJP"] = "我が子のことを、私が見抜けないとでも思って？お前が何を思ってるかなんて、顔を見ればすぐにわかる。……私が甘やかしすぎたから、お前はこんなに分別のない子になってしまったのね。",
            ["DialogueId"] = 80240212,
            ["GUID"] = "C8DF79C8",
            ["NextDialogue"] = 80240213,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF79C8",
            },
        [80240213] = {
            ["Content"] = "听话，回家去。今日之事，权做未曾发生。妈妈不想你重蹈你姑姑的覆辙。",
            ["ContentJP"] = "今家に戻れば、今日のことは、なかったことにしてあげる。母さんは、お前にあの人と同じ道を歩んでほしくないの。",
            ["DialogueId"] = 80240213,
            ["GUID"] = "C8DF79F2",
            ["NextDialogue"] = 80240214,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF79F2",
            },
        [80240214] = {
            ["Content"] = "……娇纵？你还好意思说娇纵？",
            ["ContentJP"] = "甘やかした？ ……よく、そんなこと言えるね。",
            ["DialogueId"] = 80240214,
            ["GUID"] = "C8DF7A1C",
            ["NextDialogue"] = 80240215,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A1C",
            },
        [80240215] = {
            ["Content"] = "从小到大，你们什么都不让我做。不许学机枢术，不许捣鼓工具，吃饭不许出声，不许对白龙神不敬。我就像木偶一样被你们摆弄。你管这叫娇纵？！",
            ["ContentJP"] = "小さい頃から私に、何かひとつでも「自由」をくれた？<Default note=\"text:きすう\">機枢</>術はダメ、工具を触るのもダメ。ご飯中は音を立てるな、白龍様には頭を下げろ……まるで操り人形みたいだった。",
            ["DialogueId"] = 80240215,
            ["GUID"] = "C8DF7A46",
            ["NextDialogue"] = 80240216,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A46",
            },
        [80240216] = {
            ["Content"] = "最后还是姑姑央求，你们才勉强睁一只眼闭一只眼，允许我做自己喜欢的事情！而姑姑走后，这个家里连她的名字都不允许提！",
            ["ContentJP"] = "私が好きなことを続けられたのだって、叔母が必死に頼み込んでくれたからじゃん！ なのに叔母さんがいなくなった瞬間、今度は名前すら出すなって……！",
            ["DialogueId"] = 80240216,
            ["GUID"] = "C8DF7A70",
            ["NextDialogue"] = 80240217,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A70",
            },
        [80240217] = {
            ["Content"] = "大风九章种种不公，你们视而不见。姑姑含冤而死，你们甚至没有为她流一滴泪，只顾着保全自己，天天想着如何不受牵连。你们的心肠是铁石做的吗？！",
            ["ContentJP"] = "<Default note=\"text:たいふうきゅうしょう\">大風九章</>で起きてる不公平には、何一つ目を向けない。叔母が濡れ衣を着せられて死んだときだって、あんたたち、一滴も涙を流さなかった。自分たちが無事ならそれでいい、毎日毎日、自分の身を守ることばっかり……冷たすぎるよ、この家！",
            ["DialogueId"] = 80240217,
            ["GUID"] = "C8DF7A9A",
            ["NextDialogue"] = 80240218,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7A9A",
            },
        [80240218] = {
            ["Content"] = "你……怎敢这般口出狂言！",
            ["ContentJP"] = "なっ……なんて無礼なことを！",
            ["DialogueId"] = 80240218,
            ["GUID"] = "C8DF7AC4",
            ["NextDialogue"] = 80240219,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7AC4",
            },
        [80240219] = {
            ["Content"] = "太皓神君原谅小女无心之言，小苏，快为刚刚的话道歉。",
            ["ContentJP"] = "ああ、<Default note=\"text:たいこう\">太皓</>様、どうかお許しください。この子はまだ子どもなんです……さぁ、早く謝りなさい！早く！",
            ["DialogueId"] = 80240219,
            ["GUID"] = "C8DF7AEE",
            ["NextDialogue"] = 80240220,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7AEE",
            },
        [80240220] = {
            ["Content"] = "不，我今天一定要把话说个明白！",
            ["ContentJP"] = "いやだ。今日こそ、ちゃんと言うって決めたんだ！",
            ["DialogueId"] = 80240220,
            ["GUID"] = "C8DF7B18",
            ["NextDialogue"] = 80240221,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B18",
            },
        [80240221] = {
            ["Content"] = "姑姑和我说，曾经的你爱笑，爱妆扮，还有一手机枢独学。可是现在的你呢？成天战战兢兢，如履薄冰，总是板着个脸，担心哪一步踏错了。",
            ["ContentJP"] = "叔母が教えてくれたよ。昔のママは、いつも笑顔でおしゃれが大好きで、独学で<Default note=\"text:きすう\">機枢</>術を学んで立って。なのに今のママは、いつも顔をこわばらせて、ビクビクしてて、「間違えないように」って、そればっか。",
            ["DialogueId"] = 80240221,
            ["GUID"] = "C8DF7B42",
            ["NextDialogue"] = 80240222,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B42",
            },
        [80240222] = {
            ["Content"] = "你的一身技艺只能用来做抱抱鸟这种没用的玩具，可是机枢术明明能够用来尝试更突破性，更了不起，能够造福所有人的技术！",
            ["ContentJP"] = "ママの技術って、ただのウパシを作るだけのものじゃないはずでしょ。もっと人の役に立つ、未来を変えられる、そういうものにできるって……私は、そう信じてる。",
            ["DialogueId"] = 80240222,
            ["GUID"] = "C8DF7B6C",
            ["NextDialogue"] = 80240223,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B6C",
            },
        [80240223] = {
            ["Content"] = "你愿意放弃理想，向太皓俯首。可是你不能替我决定，把我的一辈子也关在牢笼里啊！",
            ["ContentJP"] = "ママが夢を捨てたなら、勝手にすればいい。でも、それを私に押しつけないで。私の人生まで、あんたの怖さで縛らないでよ！",
            ["DialogueId"] = 80240223,
            ["GUID"] = "C8DF7B96",
            ["NextDialogue"] = 80240224,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7B96",
            },
        [80240224] = {
            ["Content"] = "好啊，既然你一定要把话说开，今天为娘就和你统统说个明白。",
            ["ContentJP"] = "そう……だったら、こっちも全部はっきり言うわ。",
            ["DialogueId"] = 80240224,
            ["GUID"] = "C8DF7BC0",
            ["NextDialogue"] = 80240225,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7BC0",
            },
        [80240225] = {
            ["Content"] = "苏乙，你以为我这么多年的牺牲，这么多年的小心谨慎是为了谁？不都是为了你，为了这个家吗。",
            ["ContentJP"] = "お前は何もわかってない。私がこれまで、どれだけ身を削ってきたか。何もかもこの家のためよ。",
            ["DialogueId"] = 80240225,
            ["GUID"] = "C8DF7BEA",
            ["NextDialogue"] = 80240226,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7BEA",
            },
        [80240226] = {
            ["Content"] = "天工苏氏是什么处境，你难道不知道？平时不让你摆弄这些，是怕你触犯“禁忌”，自毁前程。",
            ["ContentJP"] = "「<Default note=\"text:てんこう\">天工</>のスー氏」がどれだけ脆い立場か、お前も知ってるはず。お前に何もさせなかったのは、間違っても「禁忌」に触れさせたくなかったから。",
            ["DialogueId"] = 80240226,
            ["GUID"] = "C8DF7C14",
            ["NextDialogue"] = 80240227,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C14",
            },
        [80240227] = {
            ["Content"] = "天工苏氏断臂求生，好不容易才有今日，已经担不起半点风险了。你年轻气盛，想要的无非是学以致用、出人头地。天梁司用人有缺，恰有你的用武之地。",
            ["ContentJP"] = "ようやくここまで立て直した家よ。もう一度、失うわけにはいかない。若いゆえの勢い……これ以上に恐ろしいものはないわ。出世したい、認められたい、世の中に機枢を役立てたい……その気持ちはわかる。でも<Default note=\"text:てんりょうし\">天梁司</>にはもう席がある、安定した未来がそこにあるじゃない。",
            ["DialogueId"] = 80240227,
            ["GUID"] = "C8DF7C3E",
            ["NextDialogue"] = 80240228,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C3E",
            },
        [80240228] = {
            ["Content"] = "为了安稳度日，那些机枢理想统统可以让步。你年轻，还不懂这样的道理。等你受伤的时候再后悔，就来不及了！",
            ["ContentJP"] = "毎日平穏に暮らすことのほうが、よっぽど大事なの。夢なんて、いざというときには捨てなきゃならないの。お前はまだ、その覚悟ができてないだけ。",
            ["DialogueId"] = 80240228,
            ["GUID"] = "C8DF7C68",
            ["NextDialogue"] = 80240229,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C68",
            },
        [80240229] = {
            ["Content"] = "……妈，为什么你不明白呢？你给的再多也没用，那些都不是我想要的啊。",
            ["ContentJP"] = "……わかってないの？どんなに平穏な暮らしをくれても、私の心が望んでないなら……それ、檻と同じだよ。",
            ["DialogueId"] = 80240229,
            ["GUID"] = "C8DF7C92",
            ["NextDialogue"] = 80240230,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7C92",
            },
        [80240230] = {
            ["Content"] = "我要走了，既然你不让我回去拿，那抱抱鸟我也不要了。反正我也不稀罕。",
            ["ContentJP"] = "もういい。どうせ取りに戻らせてくれないんでしょ？ なら、ウパシなんていらない。……別に。あんなの、欲しくなんかないし。",
            ["DialogueId"] = 80240230,
            ["GUID"] = "C8DF7CBC",
            ["NextDialogue"] = 80240231,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7CBC",
            },
        [80240231] = {
            ["Content"] = "回来，我没让你走。",
            ["ContentJP"] = "戻りなさい。わたしはまだ行っていいなんて一言も言ってないわ。",
            ["DialogueId"] = 80240231,
            ["GUID"] = "C8DF7CE6",
            ["NextDialogue"] = 80240232,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7CE6",
            },
        [80240232] = {
            ["Content"] = "我凭什么不能走？",
            ["ContentJP"] = "なんで、あんたの言うことを聞かなきゃいけないの？",
            ["DialogueId"] = 80240232,
            ["GUID"] = "C8DF7D10",
            ["NextDialogue"] = 80240233,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D10",
            },
        [80240233] = {
            ["Content"] = "凭你是我的女儿，我是你妈妈！",
            ["ContentJP"] = "お前は、私の娘だからよ！母親の言葉に背いていいわけがない！",
            ["DialogueId"] = 80240233,
            ["GUID"] = "C8DF7D3A",
            ["NextDialogue"] = 80240234,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D3A",
            },
        [80240234] = {
            ["Content"] = "今天你敢走出这巷口，天工苏氏就再无苏乙这号人！",
            ["ContentJP"] = "あと一歩でも進んだら——<Default note=\"text:てんこう\">天工</>のスー氏にお前という娘は、もういないものと思いなさい！",
            ["DialogueId"] = 80240234,
            ["GUID"] = "C8DF7D64",
            ["NextDialogue"] = 80240235,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D64",
            },
        [80240235] = {
            ["Content"] = "你什么都不懂，就别再拦我了！！我才不要和你一起被困在这囚笼里！",
            ["ContentJP"] = "勝手にすれば！？ …… あんたみたいに、自分を閉じ込めて生きてくなんて……ごめんだから！！",
            ["DialogueId"] = 80240235,
            ["GUID"] = "C8DF7D8E",
            ["NextDialogue"] = 80240236,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7D8E",
            },
        }
  end },
  { MinKey = 80240236, MaxKey = 90070202, Loader = function()
      return {
        [80240236] = {
            ["Content"] = "十几年殷殷爱护……养出这么个无法无天之徒……",
            ["ContentJP"] = "十何年も大事に育ててきたのに……こんな親不孝者になるなんて……",
            ["DialogueId"] = 80240236,
            ["GUID"] = "C8DF7DB8",
            ["NextDialogue"] = 80240237,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7DB8",
            },
        [80240237] = {
            ["Content"] = "不，妈妈，你还好吗？我不是故意的——",
            ["ContentJP"] = "ママ、ごめん！そんなつもりじゃ——",
            ["DialogueId"] = 80240237,
            ["GUID"] = "C8DF7DE2",
            ["NextDialogue"] = 80240238,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7DE2",
            },
        [80240238] = {
            ["Content"] = "别喊我了。你不愿认我这个妈，我也从未生过你这个女儿。从此我们一刀两断，再无瓜葛。",
            ["ContentJP"] = "もう結構。お前が娘でいたくないなら、私も母親でいる義理はないわ。今この瞬間から——お前とは縁を切る。二度と戻ってこないで。",
            ["DialogueId"] = 80240238,
            ["GUID"] = "C8DF7E0C",
            ["NextDialogue"] = 80240239,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7E0C",
            },
        [80240239] = {
            ["Content"] = "拿好你的东西，滚！再也别回来！滚——",
            ["ContentJP"] = "荷物持って、とっとと出て行きなさい！二度と顔見せるんじゃないよ……！！",
            ["DialogueId"] = 80240239,
            ["GUID"] = "C8DF7E36",
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/002/C8DF7E36",
            },
        [80240301] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 80240301,
            ["GUID"] = "C8DF8862",
            ["NextDialogue"] = 80240302,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8862",
            },
        [80240302] = {
            ["Content"] = "奇怪，怎么没有人应门？",
            ["ContentJP"] = "あれ、なんで誰も出てこないの……？",
            ["DialogueId"] = 80240302,
            ["GUID"] = "C8DF888C",
            ["NextDialogue"] = 80240303,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF888C",
            },
        [80240303] = {
            ["Content"] = "爸妈是搬走了吗，还是不愿见我……",
            ["ContentJP"] = "もしかして、引っ越しちゃった？それとも……私に会いたくないのかな……",
            ["DialogueId"] = 80240303,
            ["GUID"] = "C8DF88B6",
            ["NextDialogue"] = 80240304,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF88B6",
            },
        [80240304] = {
            ["Content"] = "喵~",
            ["ContentJP"] = "にゃ～",
            ["DialogueId"] = 80240304,
            ["GUID"] = "C8DF88E0",
            ["NextDialogue"] = 80240305,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF88E0",
            },
        [80240305] = {
            ["Content"] = "小黑！这么些年过去了，你还在这里！",
            ["ContentJP"] = "クロ！？まだここにいたの！？何年も経ったのに……",
            ["DialogueId"] = 80240305,
            ["GUID"] = "C8DF890A",
            ["NextDialogue"] = 80240306,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF890A",
            },
        [80240306] = {
            ["Content"] = "……要是你能说话就好了，至少你能告诉我这些年爸妈过得怎么样，还好不好……",
            ["ContentJP"] = "あんたが喋れたらなあ。そしたら、パパとママが元気だったかくらい、教えてくれるのに。",
            ["DialogueId"] = 80240306,
            ["GUID"] = "C8DF8934",
            ["NextDialogue"] = 80240307,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8934",
            },
        [80240307] = {
            ["Content"] = "要不我还是回去……不行，都到这里了，我苏乙的字典里没有半途而废！",
            ["ContentJP"] = "戻ろうかな……いや、ダメダメ！ここまで来て、引き返すなんて絶対しない。スーイーの辞書に「<Default note=\"text:ざせつ\">挫折</>」なんて単語はないんだからっ。",
            ["DialogueId"] = 80240307,
            ["GUID"] = "C8DF895E",
            ["NextDialogue"] = 80240308,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF895E",
            },
        [80240308] = {
            ["Content"] = "大家都好忙啊，总感觉不太方便打扰。",
            ["ContentJP"] = "みんな忙しそう。いま声かけたら迷惑かな……",
            ["DialogueId"] = 80240308,
            ["GUID"] = "C8DF8988",
            ["NextDialogue"] = 80240309,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8988",
            },
        [80240309] = {
            ["Content"] = "……等一下，这里有个闲人？",
            ["ContentJP"] = "あ、あそこにヒマそうな人が……？",
            ["DialogueId"] = 80240309,
            ["GUID"] = "C8DF89B2",
            ["NextDialogue"] = 80240310,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF89B2",
            },
        [80240310] = {
            ["Content"] = "工匠大叔，你在这儿晒太阳呢？",
            ["ContentJP"] = "おじさん、こんなとこでひなたぼっこですか？",
            ["DialogueId"] = 80240310,
            ["GUID"] = "C8DF89DC",
            ["NextDialogue"] = 80240311,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF89DC",
            },
        [80240311] = {
            ["Content"] = "天气这么好，不晒晒太阳，多不给太阳面子。你也来享受享受？不过我这儿可没有垫子。",
            ["ContentJP"] = "天気がいいからな。陽の光、浴びとかなきゃ損だろ？お嬢さんも一緒にどうだい？……座布団はないけどな。",
            ["DialogueId"] = 80240311,
            ["GUID"] = "C8DF8A06",
            ["NextDialogue"] = 80240312,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A06",
            },
        [80240312] = {
            ["Content"] = "我就不坐了，有点急事。",
            ["ContentJP"] = "私はいいや、急用があるから。",
            ["DialogueId"] = 80240312,
            ["GUID"] = "C8DF8A30",
            ["NextDialogue"] = 80240313,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A30",
            },
        [80240313] = {
            ["Content"] = "叔，跟你打听个事儿。你……你认不认识在工造局当值的苏止？",
            ["ContentJP"] = "ちょっと聞きたいことがあって。……<Default note=\"text:こうぞうきょく\">工造局</>にいるスージーって人、知ってます？",
            ["DialogueId"] = 80240313,
            ["GUID"] = "C8DF8A5A",
            ["NextDialogue"] = 80240314,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A5A",
            },
        [80240314] = {
            ["Content"] = "你知道苏止他们家最近是怎么了？我刚刚去敲门，好像没人在家。他们是搬家了吗？",
            ["ContentJP"] = "さっきその人の家に行ったんだけど、誰も出てこなくて……引っ越しちゃったのかな？",
            ["DialogueId"] = 80240314,
            ["GUID"] = "C8DF8A84",
            ["NextDialogue"] = 80240315,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8A84",
            },
        [80240315] = {
            ["Content"] = "搬家？哈哈，也难怪你会这么想。在回答你的问题之前，先听我讲个故事吧。",
            ["ContentJP"] = "引っ越し？まぁ、そう思うのも無理はない。……答える前に、ちょっと話を聞いてくれないか",
            ["DialogueId"] = 80240315,
            ["GUID"] = "C8DF8AAE",
            ["NextDialogue"] = 80240316,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8AAE",
            },
        [80240316] = {
            ["Content"] = "我没时间听故事……抱歉啦大叔。",
            ["ContentJP"] = "えっ……いや、でも私……ほんとに急いでて……",
            ["DialogueId"] = 80240316,
            ["GUID"] = "C8DF8AD8",
            ["NextDialogue"] = 80240317,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8AD8",
            },
        [80240317] = {
            ["Content"] = "别急着走。说不定你要找的答案就在这故事里呢。",
            ["ContentJP"] = "まあそう言わずに。もしかしたら、あんたの探してる答え、話の中にあるかもしれないぞ？",
            ["DialogueId"] = 80240317,
            ["GUID"] = "C8DF8B02",
            ["NextDialogue"] = 80240318,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B02",
            },
        [80240318] = {
            ["Content"] = "……好吧！那你快点说，好不容易回来一趟，我真的赶时间。",
            ["ContentJP"] = "……うぅ、わかったよ！でも手短にお願い。帰ってくるの、けっこう大変だったんだから。",
            ["DialogueId"] = 80240318,
            ["GUID"] = "C8DF8B2C",
            ["NextDialogue"] = 80240319,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B2C",
            },
        [80240319] = {
            ["Content"] = "好好，小丫头性子真急。心急吃不到热豆腐哟。",
            ["ContentJP"] = "はいはい、せっかちなお嬢さんだ。焦ってもロクなことはないぞ。よく聞いてくれ。",
            ["DialogueId"] = 80240319,
            ["GUID"] = "C8DF8B56",
            ["NextDialogue"] = 80240320,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B56",
            },
        [80240320] = {
            ["Content"] = "曾经有一对夫妇，他们对女儿严加管教，结果起了反效果。某一天女儿与他们大吵一架后，离开了家。",
            ["ContentJP"] = "昔な、ある夫婦がいたんだ。娘に厳しすぎたせいで、ある日大げんかして、娘は家を飛び出してしまった。",
            ["DialogueId"] = 80240320,
            ["GUID"] = "C8DF8B80",
            ["NextDialogue"] = 80240321,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8B80",
            },
        [80240321] = {
            ["Content"] = "起初，这对夫妇还气她固执，觉得女儿迟早会后悔的。",
            ["ContentJP"] = "夫婦は最初、娘を責めたよ。頑固で、どうせそのうち泣きついて戻ってくるって。",
            ["DialogueId"] = 80240321,
            ["GUID"] = "C8DF8BAA",
            ["NextDialogue"] = 80240322,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8BAA",
            },
        [80240322] = {
            ["Content"] = "有一天，他们在收拾女儿旧房间时，找到了一只陈旧的机傀。女儿小时候不爱睡觉，父母想尽办法，做出了这只机傀。",
            ["ContentJP"] = "でな、あるとき娘の部屋を整理してたら、古いからくり人形を見つけた。娘が小さい頃、眠れなくてな。両親が作ってやったぬいぐるみさ。",
            ["DialogueId"] = 80240322,
            ["GUID"] = "C8DF8BD4",
            ["NextDialogue"] = 80240323,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8BD4",
            },
        [80240323] = {
            ["Content"] = "它生来为拥抱存在，柔软的胸腹只有一颗恒温核心。说是机傀，却没有任何攻击性。",
            ["ContentJP"] = "柔らかい腹の中に恒温装置が一つ。武装も攻撃性も何もない、ただの優しいからくりだ。",
            ["DialogueId"] = 80240323,
            ["GUID"] = "C8DF8BFE",
            ["NextDialogue"] = 80240324,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8BFE",
            },
        [80240324] = {
            ["Content"] = "时间在它的身上留下灰尘，也留下伤痕，它脏了、旧了，被夫妇和女儿遗忘了。",
            ["ContentJP"] = "年月と共に、汚れて、壊れて、忘れられて……夫婦と娘さんに忘れられた古物だ。",
            ["DialogueId"] = 80240324,
            ["GUID"] = "C8DF8C28",
            ["NextDialogue"] = 80240325,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8C28",
            },
        [80240325] = {
            ["Content"] = "面对这无害的机傀，这对夫妇想了很多，也想了很久。",
            ["ContentJP"] = "けど、それを見たとき、二人は目が離せなかった。",
            ["DialogueId"] = 80240325,
            ["GUID"] = "C8DF8C52",
            ["NextDialogue"] = 80240326,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8C52",
            },
        [80240326] = {
            ["Content"] = "他们后悔了。",
            ["ContentJP"] = "後悔が、どっと押し寄せたんだ。",
            ["DialogueId"] = 80240326,
            ["GUID"] = "C8DF8C7C",
            ["NextDialogue"] = 80240327,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8C7C",
            },
        [80240327] = {
            ["Content"] = "可已经太迟了，他们对女儿说了太多冷酷的话，不知道如何挽回这段关系。",
            ["ContentJP"] = "もう手遅れだった。娘に投げた冷たい言葉の数々が、心に深い溝を残し、どうやって埋め直せばいいのか……その術が、二人にはもうわからなかった。",
            ["DialogueId"] = 80240327,
            ["GUID"] = "C8DF8CA6",
            ["NextDialogue"] = 80240328,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8CA6",
            },
        [80240328] = {
            ["Content"] = "……我猜这故事结局应该挺圆满吧，离家出走的女儿最后肯定回来了。",
            ["ContentJP"] = "で？最後はハッピーエンドってオチでしょ。娘が帰ってきて、みんなで仲直り、みたいな？",
            ["DialogueId"] = 80240328,
            ["GUID"] = "C8DF8CD0",
            ["NextDialogue"] = 80240329,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8CD0",
            },
        [80240329] = {
            ["Content"] = "我不是满口大道理的夫子，但故事到这里还没结束。",
            ["ContentJP"] = "いや、まだ終わってない。むしろ、ここからが本番だ。",
            ["DialogueId"] = 80240329,
            ["GUID"] = "C8DF8CFA",
            ["NextDialogue"] = 80240330,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8CFA",
            },
        [80240330] = {
            ["Content"] = "这对夫妇又制作了许多机傀，在夹层里放上他们一字一字斟酌写下的信，把它们托给了一位来往于山外山的商人。",
            ["ContentJP"] = "その夫婦は、新しくたくさんのからくり人形を作ったんだ。中に手紙を忍ばせて。何度も書き直して、何度も迷って。……それを、<Default note=\"text:さんがいさん\">山外山</>に通う行商人に託した。",
            ["DialogueId"] = 80240330,
            ["GUID"] = "C8DF8D24",
            ["NextDialogue"] = 80240331,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8D24",
            },
        [80240331] = {
            ["Content"] = "……难道说……",
            ["ContentJP"] = "えっ……まさか……",
            ["DialogueId"] = 80240331,
            ["GUID"] = "C8DF8D4E",
            ["NextDialogue"] = 80240332,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8D4E",
            },
        [80240332] = {
            ["Content"] = "我也问过他们，为什么不直接让商人带话，这不是方便多了？",
            ["ContentJP"] = "俺も聞いたんだ、「手紙だけ渡せば早いのに」って。",
            ["DialogueId"] = 80240332,
            ["GUID"] = "C8DF8D78",
            ["NextDialogue"] = 80240333,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8D78",
            },
        [80240333] = {
            ["Content"] = "他们犹豫了很久，告诉我，他们害怕你没有原谅他们，不愿意回来，也害怕再次被你的话语刺伤，不敢直接托人告诉你。",
            ["ContentJP"] = "そしたらな、あの夫婦、怖かったんだとさ。娘がもう自分たちを許してないんじゃないかって。伝える勇気が持てなかったんだ",
            ["DialogueId"] = 80240333,
            ["GUID"] = "C8DF8DA2",
            ["NextDialogue"] = 80240334,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8DA2",
            },
        [80240334] = {
            ["Content"] = "他们做好了准备，哪怕你一辈子都不会回家、更不会发现夹层里的信，他们也会一直写下去的。",
            ["ContentJP"] = "それでも彼らは、娘が一生その手紙を見つけなくても、書き続けるって決めてた。",
            ["DialogueId"] = 80240334,
            ["GUID"] = "C8DF8DCC",
            ["NextDialogue"] = 80240335,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8DCC",
            },
        [80240335] = {
            ["Content"] = "幸好啊……第四年，你终于发现了。",
            ["ContentJP"] = "だけどな、よかったな。四年目にして、ついに見つけてもらえた。",
            ["DialogueId"] = 80240335,
            ["GUID"] = "C8DF8DF6",
            ["NextDialogue"] = 80240336,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8DF6",
            },
        [80240336] = {
            ["Content"] = "怎么哭了？唉，果然还是个小丫头。先收收眼泪，免得看不清字。",
            ["ContentJP"] = "どうした？泣いてんのか？ほら、涙で文字が読めなくなるぞ。",
            ["DialogueId"] = 80240336,
            ["GUID"] = "C8DF8E20",
            ["NextDialogue"] = 80240337,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E20",
            },
        [80240337] = {
            ["Content"] = "我从来、从来没有想过，要拆开看看。",
            ["ContentJP"] = "私、考えたこともなかった……開けてみようなんて……",
            ["DialogueId"] = 80240337,
            ["GUID"] = "C8DF8E4A",
            ["NextDialogue"] = 80240338,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E4A",
            },
        [80240338] = {
            ["Content"] = "我一直以为……爸妈肯定不想见到我。我也很害怕回家，害怕被爸妈再次赶走，害怕他们冷冰冰地看着我，说我不是他们的女儿……",
            ["ContentJP"] = "パパもママも、私に会いたくなんてないんだって、帰ったらまた拒絶されるんじゃないかってずっと思ってた……それが怖くて……",
            ["DialogueId"] = 80240338,
            ["GUID"] = "C8DF8E74",
            ["NextDialogue"] = 80240339,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E74",
            },
        [80240339] = {
            ["Content"] = "……原来爸妈也是这么想的。",
            ["ContentJP"] = "そっか、あの人たちも……同じだったんだ……",
            ["DialogueId"] = 80240339,
            ["GUID"] = "C8DF8E9E",
            ["NextDialogue"] = 80240340,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8E9E",
            },
        [80240340] = {
            ["Content"] = "如果我能早点发现，如果我能早点回来……",
            ["ContentJP"] = "もっと早く気づけてたら……もっと早く帰ってこれてたら……",
            ["DialogueId"] = 80240340,
            ["GUID"] = "C8DF8EC8",
            ["NextDialogue"] = 80240341,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8EC8",
            },
        [80240341] = {
            ["Content"] = "前些年时局不好，就算你有心也无力，这也怪不得你。现在就看看吧。",
            ["ContentJP"] = "いやいや、あの頃は状況も悪かったし、帰りたくても無理だったろ。誰のせいでもないさ。……さあ、読んでみな。",
            ["DialogueId"] = 80240341,
            ["GUID"] = "C8DF8EF2",
            ["NextDialogue"] = 80240342,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8EF2",
            },
        [80240342] = {
            ["Content"] = "……好，我看看。",
            ["ContentJP"] = "……うん。",
            ["DialogueId"] = 80240342,
            ["GUID"] = "C8DF8F1C",
            ["NextDialogue"] = 80240343,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F1C",
            },
        [80240343] = {
            ["Content"] = "“岁末将至。因你不在，家中未办年事，一切从简。不晓得外面有多好，能叫你有家不回，一走就是一年，年夜饭也不回来吃。”",
            ["ContentJP"] = "『年の瀬も迫ってきた。お前が不在のゆえ、家中は年越しの支度もろくにせず、何もかも簡素に済ませた。一年もの間、便りの一つも寄こさぬとは、外の世界はそれほど居心地がよいのか？』",
            ["DialogueId"] = 80240343,
            ["GUID"] = "C8DF8F46",
            ["NextDialogue"] = 80240344,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F46",
            },
        [80240344] = {
            ["Content"] = "“……也不知道报个平安，叫父母担心。”",
            ["ContentJP"] = "『せめて一言でよい。達者でいると知らせてくれ。心配するばかりだ。』",
            ["DialogueId"] = 80240344,
            ["GUID"] = "C8DF8F70",
            ["NextDialogue"] = 80240345,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F70",
            },
        [80240345] = {
            ["Content"] = "接着看吧，每个玩偶里面都有。",
            ["ContentJP"] = "まだまだあるぞ。他のぬいぐるみも開けてみな。",
            ["DialogueId"] = 80240345,
            ["GUID"] = "C8DF8F9A",
            ["NextDialogue"] = 80240346,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8F9A",
            },
        [80240346] = {
            ["Content"] = "“我的女儿，这是你离家的第三个年头。”",
            ["ContentJP"] = "『娘よ、これで家を出て三年目になるな。』",
            ["DialogueId"] = 80240346,
            ["GUID"] = "C8DF8FC4",
            ["NextDialogue"] = 80240347,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8FC4",
            },
        [80240347] = {
            ["Content"] = "“……你妈妈制作机枢，划伤了手。我问她在想什么，她忽地落下泪来，说女儿钻研机枢以来，一定受了很多伤，她身为母亲，此前却一直不懂女儿的辛苦。”",
            ["ContentJP"] = "『先日、母さんがからくりをいじっていた時に手を切った。その途端、ぽろっと泣き出してな……「あの子も、こうして何度も怪我しながら頑張っていたんだろうね」と……』",
            ["DialogueId"] = 80240347,
            ["GUID"] = "C8DF8FEE",
            ["NextDialogue"] = 80240348,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF8FEE",
            },
        [80240348] = {
            ["Content"] = "“我们没有在你最需要帮助的时候，撑起你的天地，如今有心作为，你却已经不在了……盼望吾女得见此信，早日归家。”",
            ["ContentJP"] = "『お前が一番助けを求めていた時、何もしてやれなかった。いまさら償いたくとも、もうお前はこの家には居ない。……この手紙が届いたのなら、どうか早く帰ってきておくれ』",
            ["DialogueId"] = 80240348,
            ["GUID"] = "C8DF9018",
            ["NextDialogue"] = 80240349,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9018",
            },
        [80240349] = {
            ["Content"] = "“一晃四年过去，我女儿年已十八，定是出落得亭亭玉立……母亲真想见见你，又怕你已经变了模样，叫母亲认不出了。”",
            ["ContentJP"] = "『気づけば四年。お前ももう十八か……きっと綺麗になっているのだろうね。母さんはそれを見るのが楽しみにしている、でももしわからなくなってたら……そう思うと、少しだけ怖くもなるのだよ。』",
            ["DialogueId"] = 80240349,
            ["GUID"] = "C8DF9042",
            ["NextDialogue"] = 80240350,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9042",
            },
        [80240350] = {
            ["Content"] = "“听闻应天尉捕下几名飘零人……最近时局动荡，母亲寝食难安，唯恐你也沦落囚狱……别又忘记吃饭，你小时候就这样，总要母亲……”",
            ["ContentJP"] = "『最近、応天尉が流れ者を何人か捕らえたって聞いた。世の中は騒がしく、先が見えない。母さんは夜もろくに眠れない。お前まで巻き込まれてはいないかと、心配で心配でたまらないんだ。ごはん……ちゃんと食べているかい？お前は子どものころから食が細くて、いつも母さんが——』",
            ["DialogueId"] = 80240350,
            ["GUID"] = "C8DF906C",
            ["NextDialogue"] = 80240351,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF906C",
            },
        [80240351] = {
            ["Content"] = "“小苏，爸妈想你了……如果你还愿意回来，爸妈……一直在等你。”",
            ["ContentJP"] = "『スー……パパもママも、今でもずっと、お前のことを思っている。……もし、もし帰ってきてくれるなら……いつでも、ここで待っているよ』",
            ["DialogueId"] = 80240351,
            ["GUID"] = "C8DF9096",
            ["NextDialogue"] = 80240352,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9096",
            },
        [80240352] = {
            ["Content"] = "爸爸，妈妈……我也……想你们……",
            ["ContentJP"] = "パパ、ママ……わたしも、会いたかったよ……っ",
            ["DialogueId"] = 80240352,
            ["GUID"] = "C8DF90C0",
            ["NextDialogue"] = 80240353,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF90C0",
            },
        [80240353] = {
            ["Content"] = "大叔，我爸妈、不是，那对夫妇……现在、现在怎么样了？",
            ["ContentJP"] = "おじさん……パ…あの夫婦……今、どうしてるの……？",
            ["DialogueId"] = 80240353,
            ["GUID"] = "C8DF90EA",
            ["NextDialogue"] = 80240354,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF90EA",
            },
        [80240354] = {
            ["Content"] = "那对夫妇年初生了一场大病，现在已经……",
            ["ContentJP"] = "年の初め、大きな病にかかってな……",
            ["DialogueId"] = 80240354,
            ["GUID"] = "C8DF9114",
            ["NextDialogue"] = 80240355,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9114",
            },
        [80240355] = {
            ["Content"] = "……",
            ["ContentJP"] = "…………っ",
            ["DialogueId"] = 80240355,
            ["GUID"] = "C8DF913E",
            ["NextDialogue"] = 80240356,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF913E",
            },
        [80240356] = {
            ["Content"] = "泽生阁药师妙手回春，现在已经痊愈了。",
            ["ContentJP"] = "でもな、薬師の腕がよくて、今じゃすっかり完治してるよ。",
            ["DialogueId"] = 80240356,
            ["GUID"] = "C8DF9168",
            ["NextDialogue"] = 80240357,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9168",
            },
        [80240357] = {
            ["Content"] = "……啊？",
            ["ContentJP"] = "……は？",
            ["DialogueId"] = 80240357,
            ["GUID"] = "C8DF9192",
            ["NextDialogue"] = 80240358,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9192",
            },
        [80240358] = {
            ["Content"] = "哈哈，看你这样子，吓坏了吧？这么担心他们，想来心里也没少记挂。",
            ["ContentJP"] = "はは、びっくりしたろ。そんなに心配してたんだな。あの夫婦のこと、ずっと胸の奥に引っかかってたんだろ？",
            ["DialogueId"] = 80240358,
            ["GUID"] = "C8DF91BC",
            ["NextDialogue"] = 80240359,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF91BC",
            },
        [80240359] = {
            ["Content"] = "眉眼长相，身高体量，这些东西证明了我们的来处。我看见你第一眼，就知道你是他们的女儿。",
            ["ContentJP"] = "顔立ちも、背丈も、雰囲気も……見た瞬間、わかったさ。お前がスー家の娘だってことくらいな。",
            ["DialogueId"] = 80240359,
            ["GUID"] = "C8DF91E6",
            ["NextDialogue"] = 80240360,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF91E6",
            },
        [80240360] = {
            ["Content"] = "你爹娘刚刚下工，恰好和你错开了时辰。现在，他们就在家里，准备着今年的信。",
            ["ContentJP"] = "ちょうどさっき、ご両親が仕事から帰ってきたはずだ。タイミングがずれてただけだよ。今頃、来年の手紙を書いてる頃じゃないか？",
            ["DialogueId"] = 80240360,
            ["GUID"] = "C8DF9210",
            ["NextDialogue"] = 80240361,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9210",
            },
        [80240361] = {
            ["Content"] = "回去吧，苏乙。",
            ["ContentJP"] = "さあ、帰りな。スー家の娘よ。",
            ["DialogueId"] = 80240361,
            ["GUID"] = "C8DF923A",
            ["NextDialogue"] = 80240362,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF923A",
            },
        [80240362] = {
            ["Content"] = "你看，亲情嘛，就是这样斩也斩不断的东西啊。",
            ["ContentJP"] = "やっぱり、親子の縁ってのは……切ろうとしても切れないもんだな。",
            ["DialogueId"] = 80240362,
            ["GUID"] = "C8DF9264",
            ["NextDialogue"] = 80240363,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF9264",
            },
        [80240363] = {
            ["Content"] = "我那犟脾气的哥哥在山外山一待就是十几年，不知道现今过得如何，也是时候走动走动了……",
            ["ContentJP"] = "兄貴も、あの<Default note=\"text:さんがいさん\">山外山</>に行って十数年たつ。今ごろどうしてるやら。そろそろ顔でも見に行くかね。",
            ["DialogueId"] = 80240363,
            ["GUID"] = "C8DF928E",
            ["NextDialogue"] = 80240364,
            ["SpeakNpcId"] = 790085,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF928E",
            },
        [80240364] = {
            ["Content"] = "……小苏？是你吗？",
            ["ContentJP"] = "……スー？……ほんとに、あんたなの……？",
            ["DialogueId"] = 80240364,
            ["GUID"] = "C8DF92B8",
            ["NextDialogue"] = 80240365,
            ["SpeakNpcId"] = 790084,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF92B8",
            },
        [80240365] = {
            ["Content"] = "……是我！",
            ["ContentJP"] = "……うん！",
            ["DialogueId"] = 80240365,
            ["GUID"] = "C8DF92E2",
            ["NextDialogue"] = 80240366,
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF92E2",
            },
        [80240366] = {
            ["Content"] = "爸，妈，我回来了！",
            ["ContentJP"] = "パパ、ママ——ただいま！",
            ["DialogueId"] = 80240366,
            ["GUID"] = "C8DF930C",
            ["SpeakNpcId"] = 790082,
            ["VoiceName"] = "voice/$Locale$/inv/Suyi/003/C8DF930C",
            },
        [88888801] = {
            ["DialogueId"] = 88888801,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 5,
            ["GUID"] = "DE8616EA",
            ["Scripts"] = "SEQ{SetRotation{SetRotationDescription{\"888888:n(0)\"}},PlayAnimation{ActorId{0},AnimationId{\"Cat_Interactive01\"}}}",
            ["SpeakNpcId"] = 888888,
            ["bAllowClickSkipScript"] = false,
            },
        [90000001] = {
            ["Content"] = "年轻人，你之前记挂着的那个好东西，老朽瞧着材料已经齐全了。",
            ["ContentJP"] = "若者よ、君が気になったあのもの、もう材料が揃っているようだ。",
            ["DialogueId"] = 90000001,
            ["Duration"] = 3,
            ["GUID"] = "E14E392A",
            ["SpeakNpcId"] = 200024,
            ["SpeakNpcName"] = "UI_Npc_Name_Tiejiang",
            },
        [90000011] = {
            ["Content"] = "强大的刻印！",
            ["ContentJP"] = "強力な刻印！",
            ["DialogueId"] = 90000011,
            ["GUID"] = "E14E3ACE",
            },
        [90000012] = {
            ["Content"] = "强大的宝物！",
            ["ContentJP"] = "強力な宝物！",
            ["DialogueId"] = 90000012,
            ["GUID"] = "E14E3AF8",
            },
        [90000013] = {
            ["Content"] = "我全都要！",
            ["ContentJP"] = "全部欲しい！",
            ["DialogueId"] = 90000013,
            ["GUID"] = "E14E3B22",
            },
        [90000021] = {
            ["Content"] = "选择一个中稀有度的刻印",
            ["ContentJP"] = "中レアリティの刻印を1個選ぶ",
            ["DialogueId"] = 90000021,
            ["GUID"] = "E14E3C72",
            },
        [90000022] = {
            ["Content"] = "随机获得一个高稀有度的刻印",
            ["ContentJP"] = "ランダムに高レアリティの刻印を1個獲得",
            ["DialogueId"] = 90000022,
            ["GUID"] = "E14E3C9C",
            },
        [90000031] = {
            ["Content"] = "随机获得两个低稀有度的宝物",
            ["ContentJP"] = "ランダムに低レアリティの宝物を2個獲得",
            ["DialogueId"] = 90000031,
            ["GUID"] = "E14E3E16",
            },
        [90000032] = {
            ["Content"] = "随机获得一个任意稀有度的宝物",
            ["ContentJP"] = "ランダムに任意レアリティの宝物を1個獲得",
            ["DialogueId"] = 90000032,
            ["GUID"] = "E14E3E40",
            },
        [90000041] = {
            ["Content"] = "你什么也没有得到",
            ["ContentJP"] = "君は何も得ていない",
            ["DialogueId"] = 90000041,
            ["GUID"] = "E14E3FBA",
            },
        [90000051] = {
            ["Content"] = "伟大的刻印赠礼人啊，我需要至高无上的您的帮助！",
            ["ContentJP"] = "偉大なる刻印の贈り主よ、いと高き御方の助けが必要です！",
            ["DialogueId"] = 90000051,
            ["GUID"] = "E14E415E",
            },
        [90000052] = {
            ["Content"] = "选择一个低稀有度的刻印",
            ["ContentJP"] = "低レアリティの刻印を1個選ぶ",
            ["DialogueId"] = 90000052,
            ["GUID"] = "E14E4188",
            },
        [90000053] = {
            ["Content"] = "随机获得一个中稀有度的刻印",
            ["ContentJP"] = "ランダムに中レアリティの刻印を1個獲得",
            ["DialogueId"] = 90000053,
            ["GUID"] = "E14E41B2",
            },
        [90000061] = {
            ["Content"] = "伟大的宝物赠礼人啊，我需要至高无上的您的帮助！",
            ["ContentJP"] = "偉大なる宝物の贈り主よ、いと高き御方の助けが必要です！",
            ["DialogueId"] = 90000061,
            ["GUID"] = "E14E4302",
            },
        [90000062] = {
            ["Content"] = "随机获得一个低稀有度的宝物",
            ["ContentJP"] = "ランダムに低レアリティの宝物を1個獲得",
            ["DialogueId"] = 90000062,
            ["GUID"] = "E14E432C",
            },
        [90010101] = {
            ["Content"] = "嘿咻、嘿咻……",
            ["ContentJP"] = "よいせっ、どっこいせっ……",
            ["DialogueId"] = 90010101,
            ["Duration"] = 3,
            ["GUID"] = "E154B232",
            ["SpeakNpcId"] = 900001,
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_forge_05",
            },
        [90010201] = {
            ["Camera"] = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
            ["Content"] = "最近有没有找到什么好东西？给老朽看看，说不定能锻造出一把很特别的武器！",
            ["ContentJP"] = "最近どうじゃ？いい品物はあったか？あたしに見せておくれよ。特別な武器を鍛えられるやもしれんぞ！",
            ["DialogueId"] = 90010201,
            ["GUID"] = "E154C29A",
            ["SpeakNpcId"] = 900001,
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_forge_r02",
            },
        [90010301] = {
            ["Camera"] = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
            ["Content"] = "是老朽的好友，虽然看起来个子小，但是力气可不小，老朽便让它帮忙给炉火鼓风。",
            ["ContentJP"] = "あたしの親友じゃ。体はちっこいが力は強い。こやつには炉の火の吹きつけを手伝うてもらっておる。",
            ["DialogueId"] = 90010301,
            ["GUID"] = "E154D302",
            ["SpeakNpcId"] = 900001,
            },
        [90020101] = {
            ["Content"] = "早上好……",
            ["ContentJP"] = "おはよう……",
            ["DialogueId"] = 90020101,
            ["Duration"] = 3,
            ["GUID"] = "E15B1AD2",
            ["SpeakNpcId"] = 900002,
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_shop_r03",
            },
        [90020201] = {
            ["Content"] = "啊！我、我才没有偷懒……咳！有什么想买的吗？",
            ["ContentJP"] = "ハッ！さ、サボってない……ん゛っん゛ん！何か欲しい物でもあるの？",
            ["DialogueId"] = 90020201,
            ["GUID"] = "E15B2B3A",
            ["SpeakNpcId"] = 900002,
            ["TalkActionId"] = {
                [1] = "900002:Shangdian_Write_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Bai/vo_shop_r01",
            },
        [90020301] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90020301,
            ["GUID"] = "E15B3BA2",
            },
        [90020302] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90020302,
            ["GUID"] = "E15B3BCC",
            },
        [90030000] = {
            ["Content"] = "{性别：他|她}从来都不是一只甘愿困在笼中的鸟。我知道的，总有一天{性别：他|她}会离开那座岛，飞向更远的天空。但我不知道的是，这对我们来说究竟是幸运还是不幸。",
            ["ContentJP"] = "あの子は、籠に閉じ込められる鳥じゃない。いつかあの島を出て、空へと羽ばたく。それは私たちにとって幸なか不幸か、今はわからないけど。",
            ["DialogueId"] = 90030000,
            ["GUID"] = "E15B3BCB",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_idle",
            },
        [90030001] = {
            ["Content"] = "你回来了。今天打算做什么？还是在家休息？",
            ["ContentJP"] = "お帰りなさい。今日は何をする？それとも家で休もうか？",
            ["DialogueId"] = 90030001,
            ["GUID"] = "E161730A",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextOptions"] = {
                [1] = 900300011,
                [2] = 900300013,
                [3] = 900300014,
                [4] = 900300015,
                [5] = 900300016,
                [6] = 900300018,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90030002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90030002,
            ["GUID"] = "90030002.0",
            ["NextDialogue"] = 90030001,
            },
        [90030003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90030003,
            ["GUID"] = "90030003.0",
            },
        [90030101] = {
            ["Content"] = "愿望？我……没有什么特别的愿望。每个早上都看见你笑着，就足够了。",
            ["ContentJP"] = "願い事？私は……特にないかも。毎朝、あなたの笑顔が見られるだけで十分。",
            ["DialogueId"] = 90030101,
            ["GUID"] = "E1618372",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030103,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_02_1",
            },
        [90030103] = {
            ["Content"] = "好，我会做到。",
            ["ContentJP"] = "わかった、絶対に叶えるよ。",
            ["DialogueId"] = 90030103,
            ["GUID"] = "E16183C6",
            ["NextDialogue"] = 90030104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_End",
                },
            },
        [90030104] = {
            ["Content"] = "也不用勉强自己。如果你觉得不开心，就来靠着我说会儿话吧。或者，如果你不想说的话，我们就一起安静地待一会儿。",
            ["ContentJP"] = "無理しなくてもいい。心が晴れない時は何でも話してね。もし話したくなかったら、一緒に静かに過ごしてもいいし。",
            ["DialogueId"] = 90030104,
            ["GUID"] = "E16183F0",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030301] = {
            ["Content"] = "和净界岛不一样，这座城的每一天都在下雪。不过，还好你有这么一个温暖的住处。和我们在净界岛上的破房子相比，这个地方算得上奢侈了。",
            ["ContentJP"] = "パーガトリー島と違って、この街では毎日が雪だね。あなたが暖かな住まいで暮らせていてよかった。パーガトリー島の私たちの家に比べれば、すごく贅沢じゃない？",
            ["DialogueId"] = 90030301,
            ["GUID"] = "E161A442",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030303,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_03_1",
            },
        [90030303] = {
            ["Content"] = "可我还是觉得有点冷。",
            ["ContentJP"] = "{性别:でもやっぱり少し寒いな。|でもやっぱり少し寒いよ。}",
            ["DialogueId"] = 90030303,
            ["GUID"] = "E161A443",
            ["NextDialogue"] = 90030304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81101:Think_End",
                },
            },
        [90030304] = {
            ["Content"] = "以前每到冬天，你的手都会变得很凉……来，手给我，我帮你暖一暖。",
            ["ContentJP"] = "冬になると、あなた、いつも冷たい手をしていたよね…………さあ手を出して、温めてあげる。",
            ["DialogueId"] = 90030304,
            ["GUID"] = "E161A46C",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030401] = {
            ["Content"] = "为什么呢……我也不知道。不妨就认为这是一个美好的梦吧——就当作我还在你身边，像从前一样。",
            ["ContentJP"] = "どうしてかな……私にもわからないけど、素敵な夢だと思えばいいんじゃないかな――あなたのそばに私がいる。昔みたいに。",
            ["DialogueId"] = 90030401,
            ["GUID"] = "E161B4AA",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030403,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_01_1",
            },
        [90030403] = {
            ["Content"] = "我想再次见到你。",
            ["ContentJP"] = "またベレに、会いたい。",
            ["DialogueId"] = 90030403,
            ["GUID"] = "E161B4FE",
            ["NextDialogue"] = 90030404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81101:Talk02_End",
                },
            },
        [90030404] = {
            ["Content"] = "嗯，我也想，非常想……但愿有一天，我们能够真正重逢。",
            ["ContentJP"] = "うん、私も会いたいよ、とても……いつか私たち本当に再会できたらって……そう思っている。",
            ["DialogueId"] = 90030404,
            ["GUID"] = "E161B528",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030501] = {
            ["Content"] = "应该怎么说呢，那个地方像一座钢铁做的城市……不对，应该说更像牢狱吧。很小的时候，我是在那儿度过的。",
            ["ContentJP"] = "どう言えばいいかな。鋼鉄の城……いいえ、牢獄というべき場所ね。小さい頃、私は軍団で過ごしていた。",
            ["DialogueId"] = 90030501,
            ["GUID"] = "E161C512",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030503,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_04_1",
            },
        [90030503] = {
            ["Content"] = "后来一个人带着我逃走了。被她一同带到净界岛的，还有你。只是关于她的事，我不能说更多了……抱歉。我答应过她不说。",
            ["ContentJP"] = "ある人が私を連れ出してくれて、一緒にパーガトリー島に来た。それとあなたも。ただ……彼女については、これ以上は話せない……ごめんなさい。言わないって彼女と約束したから。",
            ["DialogueId"] = 90030503,
            ["GUID"] = "E161C566",
            ["NextDialogue"] = 90030504,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_04_2",
            },
        [90030504] = {
            ["Content"] = "……在净界岛的日子是那么平静，我差点以为我们会一辈子这样生活下去。但那天，他们再次出现的时候，我才发觉我从未真正逃离那个牢狱。",
            ["ContentJP"] = "……パーガトリー島での暮らしはとても穏やかで、ずっとこんな毎日が続くんだって思っていた。だけどあの日、軍団の連中が現れて気づいたの。本当はあの牢獄から逃げ出せていなかったことに。",
            ["DialogueId"] = 90030504,
            ["GUID"] = "E161C590",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90030601] = {
            ["Content"] = "是有些吵闹，不过，我并不讨厌。你结识了许多新的朋友，这是好事，我为你高兴。",
            ["ContentJP"] = "少しうるさいけど、嫌じゃない。あなたにたくさんの友達ができた……それってすごくいいことだから。私も嬉しい。",
            ["DialogueId"] = 90030601,
            ["GUID"] = "E161D57A",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextDialogue"] = 90030603,
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_05_1",
            },
        [90030603] = {
            ["Content"] = "这样一来，就算我不在你身边，你也不会觉得孤单了。",
            ["ContentJP"] = "友達が増えれば、私がそばにいなくても、あなたは独りぼっちじゃないもの。",
            ["DialogueId"] = 90030603,
            ["GUID"] = "E161D5A4",
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_05_2",
            ["bForbidSkipOptions"] = true,
            },
        [90030801] = {
            ["Content"] = "那就枕在我身上歇息一会儿吧，像从前那样。",
            ["ContentJP"] = "なら私に寄りかかって。少し休もうか、昔みたいに。",
            ["DialogueId"] = 90030801,
            ["GUID"] = "E161F64A",
            ["LookAt"] = {
                [1] = "81101:n(0)",
                [2] = "0:n(81101)",
                },
            ["NextOptions"] = {
                [1] = 90030002,
                [2] = 90030003,
                },
            ["SpeakNpcId"] = 81101,
            ["TalkActionId"] = {
                [1] = "81101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_topic_06_1",
            ["bForbidSkipOptions"] = true,
            },
        [90031001] = {
            ["Content"] = "松露小姐，你的……猪，我可以摸一摸吗？摸一下就好。请你帮我按住它，我怕它跑远了，小动物看到我总会跑得远远的。",
            ["ContentJP"] = "トリュフ、あなたの……豚、触ってもいい？ちょっとでいい、逃げないように抑えていてくれる？動物は私を見ると、すぐに逃げちゃうから……",
            ["DialogueId"] = 90031001,
            ["GUID"] = "E162171A",
            ["NextDialogue"] = 90031002,
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_02_1",
            },
        [90031002] = {
            ["Content"] = "谢谢你……啊，暖暖的，毛茸茸的，真好啊……",
            ["ContentJP"] = "ありがとう……ああ、暖かい。ぷにぷにしていて、いい……",
            ["DialogueId"] = 90031002,
            ["GUID"] = "E1621744",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_02_2",
            },
        [90031101] = {
            ["Content"] = "我不是军团的“零号”，更不是你手中随意拨弄的玩具。你可以离开，或者带着我的尸骸回去。",
            ["ContentJP"] = "私は軍団の「No.0」じゃない、そしてあなたが好きに弄べるおもちゃでもない。さあ消えなさい、それとも、私の死体を持ち帰る？",
            ["DialogueId"] = 90031101,
            ["GUID"] = "E1622782",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_03",
            },
        [90031201] = {
            ["Content"] = "听说你是位优秀的美食家，可以给我看看你的食谱吗？{nickname}总说你做的饭很好吃，听起来不像客套话，而是发自内心的夸奖。",
            ["ContentJP"] = "あなたはとても料理上手だと聞いたけど、レシピを見せてもらえる？いつもあなたの料理が美味しいって、{nickname}が言っているの。社交辞令とかじゃなく、心から褒めているみたいで。",
            ["DialogueId"] = 90031201,
            ["GUID"] = "E16237EA",
            ["NextDialogue"] = 90031202,
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_04_1",
            },
        [90031202] = {
            ["Content"] = "……你用的食材，也只是最普通不过的食物而已？那为什么……",
            ["ContentJP"] = "でもどうして……あなたが使っている食材も、ごく普通の食べ物じゃない？",
            ["DialogueId"] = 90031202,
            ["GUID"] = "E1623814",
            ["SpeakNpcId"] = 81101,
            ["VoiceName"] = "voice/$Locale$/char/Heitao/vo_companio_04_2",
            },
        [90040000] = {
            ["Content"] = "你留在这里，是为了和我一起度过一段缱绻的二人时光吗……呵呵，我已经开始期待了。",
            ["ContentJP"] = "ここにいるのは、私とずっと一緒にいたいから？……うふふ、それって、期待してもいいのかしら？",
            ["DialogueId"] = 90040000,
            ["GUID"] = "E167DBA9",
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_idle",
            },
        [90040001] = {
            ["Content"] = "我从睡醒就一直在这里等着，体内的毒液都快干涸了……不过还好你来了，现在它们又开始因为兴奋而跳动。你……可以再靠近一些吗？",
            ["ContentJP"] = "目が覚めてからずっと待っていたのよ？身体の毒が枯れそうになっても……でも来てくれてよかった。今、私ドキドキしているわ……あ、また毒が……ねえ……もう少し……近くにきて？",
            ["DialogueId"] = 90040001,
            ["GUID"] = "E167DBAA",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextOptions"] = {
                [1] = 900400011,
                [2] = 900400012,
                [3] = 900400013,
                [4] = 900400014,
                [5] = 900400015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Give",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90040002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90040002,
            ["GUID"] = "90040002.0",
            ["NextDialogue"] = 90040001,
            },
        [90040003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90040003,
            ["GUID"] = "90040003.0",
            },
        [90040101] = {
            ["Content"] = "是的，我喜欢雨天，我读了许多遍的小说里，爱的邂逅总是在下雨天自然发生。",
            ["ContentJP"] = "ええ、雨は好き。何度も読んだ小説だと、ロマンチックな出会いはいつも雨の日に始まるの。",
            ["DialogueId"] = 90040101,
            ["GUID"] = "E167EC12",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040103,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_01_1",
            },
        [90040103] = {
            ["Content"] = "下雨天应该更适合家里睡觉吧，为什么会有邂逅？",
            ["ContentJP"] = "雨の日は家で過ごす人の方が多くない？なぜ出会いが？",
            ["DialogueId"] = 90040103,
            ["GUID"] = "E167EC13",
            ["NextDialogue"] = 90040104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82101:Explain02_End",
                },
            },
        [90040104] = {
            ["Content"] = "你留心观察过那些躲雨的人吗？他们在屋檐下不期而遇，潮湿的气息让草木的芳香更加馥郁，小心的试探使爱意缓缓流动……",
            ["ContentJP"] = "雨宿りしている人たちを観察したことはあるかしら？思いがけず軒下で出会うふたり。湿った空気が草木の香りを色濃くして、ぎこちなく探りあう会話でゆっくりと愛が育まれる……",
            ["DialogueId"] = 90040104,
            ["GUID"] = "E167EC3C",
            ["NextDialogue"] = 90040105,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_01_2",
            },
        [90040105] = {
            ["Content"] = "呵呵……等到下个雨天，您同我一起出去瞧瞧，就会明白的。",
            ["ContentJP"] = "ふふ……次に雨の日が来たら、一緒に出かけてみない？そうしたら、きっとわかるわ。",
            ["DialogueId"] = 90040105,
            ["GUID"] = "E167EC3B",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90040201] = {
            ["Content"] = "啊呀，难得你居然会和我主动谈论“爱”。",
            ["ContentJP"] = "まさか、あなたから「愛」について聞いてくれるだなんて。",
            ["DialogueId"] = 90040201,
            ["GUID"] = "E167FC7A",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040203,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Shock_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_02_1",
            },
        [90040203] = {
            ["Content"] = "应该如何描述呢……嗯，就像这香薰中的水：亲吻拥抱每一剂原料，吞噬汲取它们的气味，并最终在长久的馥郁中合为一体。",
            ["ContentJP"] = "なんと言えばいいのかしら……そう、例えるならアロマね。色んな香りが愛を確かめながら、離れたくないって絡みあうの。そして長く満ちあふれた最後には、ひとつになる。",
            ["DialogueId"] = 90040203,
            ["GUID"] = "E167FCA4",
            ["NextDialogue"] = 90040204,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Shock_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_02_2",
            },
        [90040204] = {
            ["Content"] = "听起来是两个人每天腻在一起？",
            ["ContentJP"] = "毎日ずっと一緒にいるってこと？",
            ["DialogueId"] = 90040204,
            ["GUID"] = "E167FCA5",
            ["NextDialogue"] = 90040205,
            ["SpeakNpcId"] = 100001,
            },
        [90040205] = {
            ["Content"] = "不止哦。我想要的爱情，是彻底的交融，没有彼此之分……即使一方生命终结了，也会成为香料园中的花泥；从中绽放的花朵将变成香薰，永远萦绕着另一个。",
            ["ContentJP"] = "それだけじゃないわ。私の欲しい愛は、お互いに分かつことができない、徹底的に溶け合う愛よ……たとえ一方の命が尽きても、ハーブ園の土に変わって、そこから咲く花がアロマとなって、永遠にもう一方を包みこむの。",
            ["DialogueId"] = 90040205,
            ["GUID"] = "E167FCA6",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90040301] = {
            ["Content"] = "特别？啊，是的……从小到大，身边可有不少人视我为“怪物”呢。",
            ["ContentJP"] = "特別？ええ、そうね……小さい頃からいろんな人に「化け物」扱いされていたもの。",
            ["DialogueId"] = 90040301,
            ["GUID"] = "E1680CE2",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040303,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_1",
            },
        [90040303] = {
            ["Content"] = "他们每次看到我都会露出厌恶的表情，不过那样的表情可不好看，得想办法纠正一下呢……",
            ["ContentJP"] = "そんな人たちは私に会うたび不快な表情になるけど、ああいう顔って醜いと思わない？だから美しくしてあげないと……",
            ["DialogueId"] = 90040303,
            ["GUID"] = "E1680D36",
            ["NextDialogue"] = 90040304,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_2",
            },
        [90040304] = {
            ["Content"] = "若是刺痛他们的脸，让毒素渗透进他们的肌肤，那张嫌恶的脸，也一定会变得温柔起来吧……呵呵。",
            ["ContentJP"] = "顔に刺激を与えれば、毒が肌に広がって……こわばる顔もきっと優しくなるわ……うふふ。",
            ["DialogueId"] = 90040304,
            ["GUID"] = "E1680D60",
            ["NextDialogue"] = 90040305,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_3",
            },
        [90040305] = {
            ["Content"] = "那么话说回来，你说的“特别”指的又是哪种“特别”？“特别”像个怪物……还是，“特别”令人倾心？",
            ["ContentJP"] = "ところであなたの言う「特別」って、どんな「特別」かしら？「特別」に化け物らしい？……それとも「特別」に、心が惹かれるの？",
            ["DialogueId"] = 90040305,
            ["GUID"] = "E1680D8A",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90040401] = {
            ["Content"] = "不，不会的，这份毒与生俱来，像是爱之神赐给我的礼物，不会伤害我，只会帮助我找到命定的恋人。",
            ["ContentJP"] = "ええ、まったくもって。生まれつきのこの毒は、愛の神様からの贈り物なの。私を傷つけているわけじゃない。運命の人を見つける手助けをしてくれているのよ。",
            ["DialogueId"] = 90040401,
            ["GUID"] = "E1681D4A",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040403,
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_04_1",
            },
        [90040403] = {
            ["Content"] = "听起来你还挺喜欢这份礼物的？",
            ["ContentJP"] = "レベッカはその贈り物を気に入っているんだね。",
            ["DialogueId"] = 90040403,
            ["GUID"] = "E1681D4B",
            ["NextDialogue"] = 90040404,
            ["SpeakNpcId"] = 100001,
            },
        [90040404] = {
            ["Content"] = "是啊，虽然容易失控的毒液总让我被当做怪物，但也让我和其他人不同。所以我坚信，一个怪物的命定之人，也一定很特别，你说对吗？",
            ["ContentJP"] = "もちろんよ。コントロールの難しい毒のせいで、いつも化け物扱いだったけど、他人と違うからこそ私は信じられるわ。怪物と結ばれる運命の人って、特別な人じゃない？",
            ["DialogueId"] = 90040404,
            ["GUID"] = "E1681D74",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90040501] = {
            ["Content"] = "是我自制的香薰哦，前调如同初遇一般浓烈，中调则是用来定香的甜言蜜语，最后的尾调，是散不去的回味再加一点苦涩。",
            ["ContentJP"] = "私の調合したアロマの香りね。トップノートは濃厚な出会いのときめき、ミドルノートは甘い言葉で香りを定着させて、ベースノートは消えない余韻に少しの苦味を。",
            ["DialogueId"] = 90040501,
            ["GUID"] = "E1682DB2",
            ["LookAt"] = {
                [1] = "82101:n(0)",
                [2] = "0:n(82101)",
                },
            ["NextDialogue"] = 90040503,
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_05_1",
            },
        [90040503] = {
            ["Content"] = "那，具体成分是什么呢？",
            ["ContentJP"] = "具体的な成分は何を使っているの？",
            ["DialogueId"] = 90040503,
            ["GUID"] = "E1682E06",
            ["NextDialogue"] = 90040504,
            ["SpeakNpcId"] = 100001,
            },
        [90040504] = {
            ["Content"] = "秘密哟，当然，我也可以亲手教你如何调制，从始至终，一步一步。",
            ["ContentJP"] = "それは内緒なの。作り方を教えることはできるけどね。ひとつずつ、手取り足取り、最初から最後まで。",
            ["DialogueId"] = 90040504,
            ["GUID"] = "E1682E30",
            ["NextOptions"] = {
                [1] = 90040002,
                [2] = 90040003,
                },
            ["SpeakNpcId"] = 82101,
            ["TalkActionId"] = {
                [1] = "82101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_topic_05_2",
            ["bForbidSkipOptions"] = true,
            },
        [90040601] = {
            ["Content"] = "……这个干燥的气息，原来是你啊。好久不见，你还是想把我拷走吗？\
嗯！可以哦。毕竟，即使重来一遍，重来多少遍，我依旧能够从你掌心逃脱的……你、相、信、吗？海尔法大人。",
            ["ContentJP"] = "この乾燥する感じ、あなただと思った。お久しぶりね、また私を捕まえる気なの？えぇ！構わないわ！何回やり直しても、何回だってあなたの手から逃れるつもりよ……だから、つ・か・ま・え・て？ねぇ、ヘルファイア様。",
            ["DialogueId"] = 90040601,
            ["GUID"] = "E1683E1A",
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_companio_01",
            },
        [90040701] = {
            ["Content"] = "你害怕我吗？那我会让你喜欢上我的，来闻一闻我调配的香薰吧，很甜的，保证你能体会到前所未有的幸福。",
            ["ContentJP"] = "私のことが怖いのかしら？大丈夫よ、きっと好きにしてみせるから。私の調合したアロマを嗅いでみて……いい香りでしょ？今までにない幸せに包まれる感じで……",
            ["DialogueId"] = 90040701,
            ["GUID"] = "E1684E82",
            ["SpeakNpcId"] = 82101,
            ["VoiceName"] = "voice/$Locale$/char/Shuimu/vo_companio_02",
            },
        [90050000] = {
            ["Content"] = "……喂……喂，放我出去玩啦！闲得我触手都要僵了！",
            ["ContentJP"] = "……おい……おーい、遊びに連れてってくれよ！ヒマすぎて触手が固まりそうだ！",
            ["DialogueId"] = 90050000,
            ["GUID"] = "E16E4449",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_idle",
            },
        [90050001] = {
            ["Content"] = "嗯，这个时间最适合动手了，要赶紧出门，不然就……哇！你什么时候来的！",
            ["ContentJP"] = "さて、今が絶好のチャンスだ、早く出かけなきゃ……うわ！いつの間に来たんだ！",
            ["DialogueId"] = 90050001,
            ["GUID"] = "E16E444A",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextOptions"] = {
                [1] = 900500011,
                [2] = 900500012,
                [3] = 900500013,
                [4] = 900500014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90050002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90050002,
            ["GUID"] = "90050002.0",
            ["NextDialogue"] = 90050001,
            },
        [90050003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90050003,
            ["GUID"] = "90050003.0",
            },
        [90050101] = {
            ["Content"] = "贝蕾，我……",
            ["ContentJP"] = "{性别:ねえ、ベレ、僕は……|ねえ、ベレ、私は……}",
            ["DialogueId"] = 90050101,
            ["GUID"] = "E16E54B2",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050103,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_01_1",
            },
        [90050103] = {
            ["Content"] = "？",
            ["ContentJP"] = "……？",
            ["DialogueId"] = 90050103,
            ["GUID"] = "E16E5506",
            ["NextDialogue"] = 90050104,
            ["SpeakNpcId"] = 100001,
            },
        [90050104] = {
            ["Content"] = "每个早上都看见你笑着，就足够了。从今以后的每一天，我都会一直保护你的。嘻嘻，我学得像不像？",
            ["ContentJP"] = "毎朝、あなたの笑顔が見られるだけで十分。これから毎日、ずっとあなたを守っていく……どうよどうよ、似てる？",
            ["DialogueId"] = 90050104,
            ["GUID"] = "E16E5530",
            ["NextDialogue"] = 90050105,
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_01_2",
            },
        [90050105] = {
            ["Content"] = "不像！一点也不像！不许学！",
            ["ContentJP"] = "似てない！全然似てない！真似しないで！",
            ["DialogueId"] = 90050105,
            ["GUID"] = "E16E555A",
            ["NextDialogue"] = 90050106,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82301:Explain02_End",
                },
            },
        [90050106] = {
            ["Content"] = "生气啦？嘻嘻嘻，你生气的样子让人更想学了！",
            ["ContentJP"] = "怒った？キキキキ、その怒った顔！ますます真似したくなるんだ！",
            ["DialogueId"] = 90050106,
            ["GUID"] = "E16E5584",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050201] = {
            ["Content"] = "因为我会变呀，嘻嘻，我能变成任何形状，任何颜色，完美地伪装自己，一般人绝对发现不了我！",
            ["ContentJP"] = "だって変身できるからな？キキキ、オレ様はどんな形、どんな色にでも擬態できるんだ！普通のヤツなら絶対に見抜けないぜ！",
            ["DialogueId"] = 90050201,
            ["GUID"] = "E16E651A",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050203,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_02_1",
            },
        [90050203] = {
            ["Content"] = "有一天我还偷偷假扮成了木桶，等着吓唬你呢，没想到你根本不靠近……",
            ["ContentJP"] = "この前も樽に化けて驚かそうとしたけど、お前、全然近づいてこなかったな…",
            ["DialogueId"] = 90050203,
            ["GUID"] = "E16E6544",
            ["NextDialogue"] = 90050204,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_02_2",
            },
        [90050204] = {
            ["Content"] = "屋子正中央突然出现一个木桶，怎么想都只有一种可能吧……",
            ["ContentJP"] = "{性别:部屋の真ん中に樽が唐突に現れたら、それは疑うよ……|部屋の真ん中に樽が唐突に現れたら、それは疑うでしょ……}",
            ["DialogueId"] = 90050204,
            ["GUID"] = "E16E6546",
            ["NextDialogue"] = 90050205,
            ["SpeakNpcId"] = 100001,
            },
        [90050205] = {
            ["Content"] = "什么？！所以原来你是故意无视我的！你这家伙！",
            ["ContentJP"] = "なに！？わざと無視していたんだな！こんにゃろー！",
            ["DialogueId"] = 90050205,
            ["GUID"] = "E16E6545",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050301] = {
            ["Content"] = "喂喂喂——我可和那些什么都偷还一肚子坏水的家伙不一样！",
            ["ContentJP"] = "おいおいおい――なんでもかんでも盗むような、小悪党どもとオレを一緒にするなよな！",
            ["DialogueId"] = 90050301,
            ["GUID"] = "E16E7582",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050303,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_03_1",
            },
        [90050303] = {
            ["Content"] = "不一样？哪里不一样？",
            ["ContentJP"] = "{性别:一緒じゃないって、どこが違うのかな？|一緒じゃないって、どこが違うの？}",
            ["DialogueId"] = 90050303,
            ["GUID"] = "E16E7584",
            ["NextDialogue"] = 90050304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82301:Talk01_End",
                },
            },
        [90050304] = {
            ["Content"] = "我专门偷小偷的东西——伪装成他们认不出来的样子，慢慢靠近，从他们的口袋里挑出最顺眼的赃物，统统带走！",
            ["ContentJP"] = "オレは泥棒のモノだけ盗むのさ！相手がわからないように変身して、ゆっくり近寄って、ポケットからいい感じの獲物を選んで、かっさらう！",
            ["DialogueId"] = 90050304,
            ["GUID"] = "E16E7585",
            ["NextDialogue"] = 90050305,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_03_2",
            },
        [90050305] = {
            ["Content"] = "等他们发现的时候，总是震惊得眼珠都快掉出来！嘻嘻嘻……我这是伸张正义，怎么能算坏人！",
            ["ContentJP"] = "やつらが気づいた時の顔と来たら！びっくりして目ん玉が落っこちそうになるんだ！キキキキ……オレは正義の泥棒なんだよ。ワルモノ呼ばわりされる筋合いはないのさ！",
            ["DialogueId"] = 90050305,
            ["GUID"] = "E16E7583",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050401] = {
            ["Content"] = "那当然了，你要是被人皱着眉头一脸嫌弃地叫着“恶魔”，你也不会喜欢的。",
            ["ContentJP"] = "そりゃそうなんじゃね？ムカつくしかめっ面で「悪魔」って呼ばれるのなんか、誰だって嫌じゃん。",
            ["DialogueId"] = 90050401,
            ["GUID"] = "E16E85EA",
            ["LookAt"] = {
                [1] = "82301:n(0)",
                [2] = "0:n(82301)",
                },
            ["NextDialogue"] = 90050403,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_04_1",
            },
        [90050403] = {
            ["Content"] = "可你怎么会管自己叫做“恶魔大盗”啊？",
            ["ContentJP"] = "じゃあどうして自分から「悪魔の大泥棒」って名乗ってるの？",
            ["DialogueId"] = 90050403,
            ["GUID"] = "E16E85EC",
            ["NextDialogue"] = 90050404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82301:Talk03_End",
                },
            },
        [90050404] = {
            ["Content"] = "那当然是想要让“恶魔”这个词变得帅气起来，现在的小偷啊，听到“恶魔大盗”的名头就会魂不附体。",
            ["ContentJP"] = "そりゃトーゼン「悪魔」って言葉をカッコよくするためさ！いまじゃコソ泥どもは「悪魔の大泥棒」って聞くだけで、ビビッて震え上がるんだぜ！",
            ["DialogueId"] = 90050404,
            ["GUID"] = "E16E85EB",
            ["NextDialogue"] = 90050405,
            ["SpeakNpcId"] = 82301,
            ["TalkActionId"] = {
                [1] = "82301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_04_2",
            },
        [90050405] = {
            ["Content"] = "迟早有一天，人们提到“恶魔”，就只会想到厉害的我，怎么样，是很伟大的梦想吧！",
            ["ContentJP"] = "そのうち「悪魔」っていったら、偉大なこのオレ様しか思い浮かばなくなるだろうさ。どうだ！めっちゃくちゃデッカイ夢だろ！",
            ["DialogueId"] = 90050405,
            ["GUID"] = "E16E85ED",
            ["NextOptions"] = {
                [1] = 90050002,
                [2] = 90050003,
                },
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90050501] = {
            ["Content"] = "要抓我？我又不是坏人！不就是顺了点东西吗，还是小偷的东西……哇，你不要过来啊！好热！",
            ["ContentJP"] = "オレを捕まえるって？ オレは悪いことしてないぞ！ちょっと盗んだだけだ、しかも泥棒のモンを……うわ、それ以上近寄るな！アツいんだよ！",
            ["DialogueId"] = 90050501,
            ["GUID"] = "E16E9652",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_companio_01",
            },
        [90050601] = {
            ["Content"] = "送我香薰？唔，你看起来就好危险，我不要我不要！等等……这个香薰闻起来，怎么让人感觉飘飘的……我的触手怎么麻麻的……你果然很危险！",
            ["ContentJP"] = "アロマをくれる？いやいいよ、お前ちょっとアブないやつに見えるから、いらないいらない！待て……このアロマの匂い、何だかフワフワする……触手がシビれ、て……って、やっぱりお前、アブないやつだな！",
            ["DialogueId"] = 90050601,
            ["GUID"] = "E16EA6BA",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_companio_02",
            },
        [90050701] = {
            ["Content"] = "你对着剑说话的样子好好玩！萨麦尔，你喜欢这个地方吗，我们还要一起去更多的地方哦！\
嗯……？你怎么在那里干憋气不出声，这样子更好玩了嘻嘻嘻！",
            ["ContentJP"] = "お前が剣と話してるさまはサイコーだな！サマエル、ここが好きなの？私たちは一緒にもっとたくさんのところに行くのよ！\
あれー……？なんでそこでだんまりするんだ。余計に面白くなってきたぞキキキキキ！",
            ["DialogueId"] = 90050701,
            ["GUID"] = "E16EB722",
            ["SpeakNpcId"] = 82301,
            ["VoiceName"] = "voice/$Locale$/char/Zhangyu/vo_companio_03",
            },
        [90060000] = {
            ["Content"] = "真是惬意自得……不害怕我的炼火吗？哈，无知的蝼蚁，或许把你踩在脚下时你才会感到悔意。",
            ["ContentJP"] = "なんとも身の程知らずな……私の煉火が怖くないのか？ハハッ、愚かな虫けらめ。踏みにじらないとわからないようだな？",
            ["DialogueId"] = 90060000,
            ["GUID"] = "E174ACE9",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_idle",
            },
        [90060001] = {
            ["Content"] = "今天准备好接受拷问了吗？！",
            ["ContentJP"] = "拷問の時間だ、準備はできてるな！？",
            ["DialogueId"] = 90060001,
            ["GUID"] = "E174ACEA",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextOptions"] = {
                [1] = 900600011,
                [2] = 900600012,
                [3] = 900600013,
                [4] = 900600014,
                [5] = 900600015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90060002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90060002,
            ["GUID"] = "90060002.0",
            ["NextDialogue"] = 90060001,
            },
        [90060003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90060003,
            ["GUID"] = "90060003.0",
            },
        [90060101] = {
            ["Content"] = "如果你熟读历史的话，就会知道，皇家军事监狱的初代典狱长也有着熔岩一般的皮肤，再凶恶的罪徒也会畏惧她的拷问。",
            ["ContentJP"] = "ヒュペリアの歴史を知らないのだな？皇立軍事監獄が誇る初代典獄も溶岩のごとき肌を持っていた。凶悪な罪人であろうと、彼女の拷問には恐れおののいたという。",
            ["DialogueId"] = 90060101,
            ["GUID"] = "E174BD52",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060102,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_1",
            },
        [90060102] = {
            ["Content"] = "而我，作为她的后代，继承了她的名号，同样会用炼火将一切罪行烧成炉灰。",
            ["ContentJP"] = "私は彼女の子孫であり、名を頂いた後継者でもある。全ての罪を灰燼に帰すべく、彼女と同じ煉火を得たのだ。",
            ["DialogueId"] = 90060102,
            ["GUID"] = "E174BD53",
            ["NextDialogue"] = 90060103,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_2",
            },
        [90060103] = {
            ["Content"] = "那……你滚烫的皮肤会不会让你生活不太方便？",
            ["ContentJP"] = "その……熱い肌だと日常で不便が出たりは？",
            ["DialogueId"] = 90060103,
            ["GUID"] = "E174BD54",
            ["NextDialogue"] = 90060104,
            ["SpeakNpcId"] = 100001,
            },
        [90060104] = {
            ["Content"] = "有一些影响，我只能睡在铁制的床上，也不能在木头屋子里待上太久。但与之相对的，我能在火场里把罪犯带出来让他们直面法律，也从不怕冷。",
            ["ContentJP"] = "少しだけな。木造の部屋に長期間の滞在はできないし、ベッドはもちろん鉄製を選ぶことになるが、まあ些末事だろう。代わりに火災現場でも臆せず犯罪者を法の前へ引っ張り出せるぞ。寒さに恐怖を抱かずともよくなるのも零幸いだ。",
            ["DialogueId"] = 90060104,
            ["GUID"] = "E174BD55",
            ["NextDialogue"] = 90060105,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_3",
            },
        [90060105] = {
            ["Content"] = "异于常人的外表于我而言，更像是一份馈赠，非要说有什么不方便的……我一直想尝一尝那种叫做冰激凌的甜品，但它总是在我手上就化掉了……",
            ["ContentJP"] = "外見が一般人と異なろうが私にとっては利点であるし、強いて不便を挙げるとすれば……アイスクリームというデザートを食せない点ぐらいか。味わってみたいのだが、手にした瞬間に溶けてしまう……",
            ["DialogueId"] = 90060105,
            ["GUID"] = "E174BD56",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90060201] = {
            ["Content"] = "从帝国诞生起，我的家族就世代执掌着关押罪大恶极的犯人们的牢狱，理清冤罪，或是斩除祸患。",
            ["ContentJP"] = "罪深き者どもの牢獄を立国から代々と管理してきただけだ。冤罪を清算して災いを断ち切るのが、私の家の役目である。",
            ["DialogueId"] = 90060201,
            ["GUID"] = "E174CDBA",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060202,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_02_1",
            },
        [90060202] = {
            ["Content"] = "而我与生俱来和先祖同样的火红肤色，就注定了我要拿起她留下的铁铸法典。所以并非是我选择成为典狱长，而是典狱长的头衔选择了我。",
            ["ContentJP"] = "そして私は先祖と同じ紅蓮の肌を、生まれながらに得ていたからな。初代典獄が残した不磨の法条を継承する者として決まっていた。つまり私が典獄を選んだのではなく、典獄の称号が私を選んだのだと言えるだろう。",
            ["DialogueId"] = 90060202,
            ["GUID"] = "E174CDBB",
            ["NextDialogue"] = 90060203,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_02_2",
            },
        [90060203] = {
            ["Content"] = "这么说你已经实现了自己的愿望？",
            ["ContentJP"] = "つまり、典獄になるべくしてなったと？",
            ["DialogueId"] = 90060203,
            ["GUID"] = "E174CDBC",
            ["NextDialogue"] = 90060204,
            ["SpeakNpcId"] = 100001,
            },
        [90060204] = {
            ["Content"] = "成为典狱长并非愿望的终点，相反，这只是一个开始，它意味着我需要时刻保持戒备和警醒一一斩除帝国土地上孳生的任何不义，直到死亡将我熄灭。",
            ["ContentJP"] = "ああ、なるだけは叶った。しかしそれは私にとって単なる出発点でしかない。帝国の地に生じる不義を余すことなく断ち切るためには一一死によって自分の存在が抹消される最後まで、警戒と警告を怠ってはならないのだ。",
            ["DialogueId"] = 90060204,
            ["GUID"] = "E174CDBD",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90060301] = {
            ["Content"] = "那当然，帝国监狱里多的是难缠的犯人，审讯案件、查阅卷宗、防止那些狡猾的老鼠设法逃走都是典狱长的职责所在。",
            ["ContentJP"] = "言うまでもないだろう。帝国にて収監されているのは一癖も二癖もある畜生ばかりだ。事件の尋問、公文書の調査、小賢しいネズミどもの脱走を阻止するのも典獄の職務となる。",
            ["DialogueId"] = 90060301,
            ["GUID"] = "E174DE22",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060302,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_03_1",
            },
        [90060302] = {
            ["Content"] = "每休息一分，都会让正义迟到一分——而当正义迟迟不来时，混乱与弱肉强食就会代替法条成为新的规则。",
            ["ContentJP"] = "少しでも休めば正義の執行が遅れる——正義が遅れると法の条文は崩され、弱肉強食と狂瀾怒濤が新たなルールと成り果ててしまうからな。",
            ["DialogueId"] = 90060302,
            ["GUID"] = "E174DE23",
            ["NextDialogue"] = 90060303,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_03_2",
            },
        [90060303] = {
            ["Content"] = "如果监狱里的犯人越来越少，你会不会轻松一点。",
            ["ContentJP"] = "牢獄の罪人がいなくなっていけば、少しは楽になったり？",
            ["DialogueId"] = 90060303,
            ["GUID"] = "E174DE24",
            ["NextDialogue"] = 90060304,
            ["SpeakNpcId"] = 100001,
            },
        [90060304] = {
            ["Content"] = "确实有学者设想过没有罪犯的世界。如果真的有那天，我也将不复存在，因为正是罪恶造就了典狱长。但是在那之前，我会尽力维护好现存的秩序。",
            ["ContentJP"] = "罪悪があってこそ典獄がある。犯罪のない世界の構築を目指す学者もいるが、仮に成し遂げられたなら、私は楽どころか存在もしなくなるだろう。そんな未来が訪れるまで、現存する秩序の維持を疎かにはしないつもりだ。",
            ["DialogueId"] = 90060304,
            ["GUID"] = "E174DE25",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90060401] = {
            ["Content"] = "正义？正义就是权力约束欲望，力量桎梏罪孽，强者鞭挞恶徒。",
            ["ContentJP"] = "正義？正義とは欲を拘束し得る権力だろう。罪を制する力、悪に鞭を打つ強者だ。",
            ["DialogueId"] = 90060401,
            ["GUID"] = "E174EE8A",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060402,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_04_1",
            },
        [90060402] = {
            ["Content"] = "这样的规则也太绝对了吧。",
            ["ContentJP"] = "それは絶対的すぎて残酷な気が。",
            ["DialogueId"] = 90060402,
            ["GUID"] = "E174EE8B",
            ["NextDialogue"] = 90060403,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83201:Explain01_End",
                },
            },
        [90060403] = {
            ["Content"] = "哼，绝对？不然呢，天真的小朋友，难道指望人人都手拉手过家家？绝对的力量、绝对的秩序，这就是我的正义！",
            ["ContentJP"] = "まったく無邪気なヤツだな。それ以外に何がある？手を取り合って仲良しごっこできると期待しているのか？絶対的な力、絶対的な秩序！それこそが私の正義だ！",
            ["DialogueId"] = 90060403,
            ["GUID"] = "E174EE8C",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90060501] = {
            ["Content"] = "帝国的罪犯还在满大街地跑，身为典狱长哪有什么闲暇时间。只能在忙里偷闲的时候，喝几杯烈酒。",
            ["ContentJP"] = "帝国のいたるところで犯罪者が闊歩しているのだぞ。典獄として私に暇な時間などあるものか。できても酒をキツめに何杯か、少しの合間あおるだけだ。",
            ["DialogueId"] = 90060501,
            ["GUID"] = "E174FEF2",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060502,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_05_1",
            },
        [90060502] = {
            ["Content"] = "什么！你会喝酒？",
            ["ContentJP"] = "{性别:意外だな！お酒、飲むんだ？|意外だね！お酒、飲むんだ？}",
            ["DialogueId"] = 90060502,
            ["GUID"] = "E174FF1C",
            ["LookAt"] = {
                [1] = "83201:n(0)",
                [2] = "0:n(83201)",
                },
            ["NextDialogue"] = 90060503,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83201:Talk01_End",
                },
            },
        [90060503] = {
            ["Content"] = "怎么，很惊讶？消遣而已：审讯时总会听到各种酒的名字，就开始好奇，这到底是什么邪恶药水，总是和犯罪沾边，于是偶尔会来上一些。",
            ["ContentJP"] = "何を驚いている？ただの憂さ晴らしの物種だろう？取り調べで酒の名前を耳にする機会が多くてな。「どれほどに邪悪な薬なのか」「なぜ犯罪と関わりが多いのか」と気になって試しに飲んでみたのが始まりだ。",
            ["DialogueId"] = 90060503,
            ["GUID"] = "E174FF1D",
            ["NextDialogue"] = 90060504,
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_05_2",
            },
        [90060504] = {
            ["Content"] = "喝得越多，我越是确信，邪恶的并不是酒。",
            ["ContentJP"] = "飲めば飲むほど、酒そのものが邪悪ではないと思い知った。",
            ["DialogueId"] = 90060504,
            ["GUID"] = "E174FF1E",
            ["NextOptions"] = {
                [1] = 90060002,
                [2] = 90060003,
                },
            ["SpeakNpcId"] = 83201,
            ["TalkActionId"] = {
                [1] = "83201:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90060601] = {
            ["Content"] = "典狱长和军团长，都是帝国“黑暗”秩序的维护者。我们心狠手辣、声名狼藉——但是为了海伯利亚，这点恶名又算得上什么？！",
            ["ContentJP"] = "典獄と軍団長。どちらも帝国における「闇」の秩序の守護者だ。私たちは残酷無比と悪名が轟いているだろうが……ヒュペリアのためであれば、悪名ごときがなんだというのだ！？",
            ["DialogueId"] = 90060601,
            ["GUID"] = "E1750F5A",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_companio_01",
            },
        [90060701] = {
            ["Content"] = "又是你。",
            ["ContentJP"] = "また、お前か。",
            ["DialogueId"] = 90060701,
            ["GUID"] = "E1751FC2",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_companio_02",
            },
        [90060801] = {
            ["Content"] = "啧，西比尔的副官……那个总被指责不尽职的家伙，对吧？可惜，你那些隐藏实力的拙劣技巧瞒不过我的眼睛！藏匿锋芒混迹在军团长身边，你到底有什么居心？！",
            ["ContentJP"] = "チッ、シビルの副官か……無能だとよく言われているそうだな？しかし私の目は誤魔化せんぞ！なぜ下手な演技をしてまで実力を隠している！？強さを隠して軍団長にまとわりつくとは、何が目的だ！？",
            ["DialogueId"] = 90060801,
            ["GUID"] = "E175302A",
            ["SpeakNpcId"] = 83201,
            ["VoiceName"] = "voice/$Locale$/char/Haier/vo_companio_03",
            },
        [90070000] = {
            ["Content"] = "无事，便是好事。",
            ["ContentJP"] = "別条なければ、すべて世は事もない。",
            ["DialogueId"] = 90070000,
            ["GUID"] = "E17B1589",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_idle",
            },
        [90070001] = {
            ["Content"] = "趁着你还没有被各种律法束缚，想做什么事情，就去做吧。",
            ["ContentJP"] = "やりたいことがあれば、今のうちにやっておくことだ。あんたの身が自由でいられるうちに。",
            ["DialogueId"] = 90070001,
            ["GUID"] = "E17B158A",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextOptions"] = {
                [1] = 900700011,
                [2] = 900700012,
                [3] = 900700013,
                [4] = 900700014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90070002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90070002,
            ["GUID"] = "90070002.0",
            ["NextDialogue"] = 90070001,
            },
        [90070003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90070003,
            ["GUID"] = "90070003.0",
            },
        [90070101] = {
            ["Content"] = "……这等闲聊，有更适合的人选吧。找那些贩卖货物的织星客吧，或者看看书也好。",
            ["ContentJP"] = "……物売りの星織人に尋ねるか、本で調べた方がいい。俺に聞くよりもずっと早いと思うが。",
            ["DialogueId"] = 90070101,
            ["GUID"] = "E17B25F2",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070102,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_01_1",
            },
        [90070102] = {
            ["Content"] = "每个人眼中的世界各不相同，我是在问你的看法。",
            ["ContentJP"] = "{性别:世界の見え方は人それぞれだろ。僕はユーミンの意見が聞きたいんだ。|世界の見え方は人それぞれでしょ。私はユーミンの意見が聞きたいな。}",
            ["DialogueId"] = 90070102,
            ["GUID"] = "E17B25F3",
            ["NextDialogue"] = 90070103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84201:Talk03_End",
                },
            },
        [90070103] = {
            ["Content"] = "我平素繁忙，所以眼见多有偏狭。你若是真的好奇，与其假他人言语，不如亲自踏足那里，如何？",
            ["ContentJP"] = "……日がな一日を忙しなく生きてきた。そんな人間の目にするモノなど限られている。本当に興味があるのならば他人の言葉よりも自身の目で確かめるべきだ。",
            ["DialogueId"] = 90070103,
            ["GUID"] = "E17B25F4",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070201] = {
            ["Content"] = "《大风九章》是华胥的律法，谁都不能违抗。但倘若真要有人倒反天命，那自然要有人去收拾乱局。",
            ["ContentJP"] = "<Default note=\"text:カショ\">華胥</>に定められた絶対的な法が『<Default note=\"text:タイフウキュウショウ\">大風九章</>』なのだが、仮に背くような者が現れたとしたら、当然ながら収拾を図る者も必要だろう？",
            ["DialogueId"] = 90070201,
            ["GUID"] = "E17B365A",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070202,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_02_1",
            },
        [90070202] = {
            ["Content"] = "那么你一定很受崇敬吧。",
            ["ContentJP"] = "じゃあユーミンって崇敬される存在だったり？",
            ["DialogueId"] = 90070202,
            ["GUID"] = "E17B365B",
            ["NextDialogue"] = 90070203,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84201:Explain01_End",
                },
            },
        }
  end },
  { MinKey = 90070203, MaxKey = 90160404, Loader = function()
      return {
        [90070203] = {
            ["Content"] = "……也许吧，我不常与人们闲谈，毕竟但凡需要我出手的地方，总有伤逝。大部华胥之民，是并不乐见我的。",
            ["ContentJP"] = "……どうだろうか。俺は人と多くを話さないし、俺が手を下した大体には必ず悲しみがつきまとう。それで歓迎する<Default note=\"text:カショ\">華胥</>の民などいるとは思わないが。",
            ["DialogueId"] = 90070203,
            ["GUID"] = "E17B365C",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070301] = {
            ["Content"] = "无事可乐，自然如此。",
            ["ContentJP"] = "問題ない。特に愉快だと思ってもなければ、至極普通な表情だろう。",
            ["DialogueId"] = 90070301,
            ["GUID"] = "E17B46C2",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070302,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_03_1",
            },
        [90070302] = {
            ["Content"] = "也许我可以分享你的烦恼。",
            ["ContentJP"] = "{性别:悩みがあるなら、僕が聞いてあげられるかも。|悩みがあるなら、私が聞いてあげられるかも。}",
            ["DialogueId"] = 90070302,
            ["GUID"] = "E17B46C3",
            ["NextDialogue"] = 90070303,
            ["SpeakNpcId"] = 100001,
            },
        [90070303] = {
            ["Content"] = "谢了，但是说与你听，也不过是徒然让这世上又多了一个烦恼之人，何必。",
            ["ContentJP"] = "心遣いには感謝するが、話したとしても恐らく、悩みを持つ者を世の中にひとり増やすだけだ。だから聞く必要はない。",
            ["DialogueId"] = 90070303,
            ["GUID"] = "E17B46C4",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070401] = {
            ["Content"] = "是啊，月亮很好，很好。无论前一天发生过什么，杯盘狼籍还是血溅五步，月光都能洗净一切。不管过去多久，天边的一角总是会为你留下一弯月亮。",
            ["ContentJP"] = "ああ、月は美しい、本当に美しい。前日に何が起ころうとも、席上の皿鉢が飛び散ろうとも、血も涙もなくとも……月光が全てを洗い流してくれる。時間が過ぎ去ろうがいつだって、夜空の片隅には三日月が残されている。",
            ["DialogueId"] = 90070401,
            ["GUID"] = "E17B572A",
            ["LookAt"] = {
                [1] = "84201:n(0)",
                [2] = "0:n(84201)",
                },
            ["NextDialogue"] = 90070402,
            ["SpeakNpcId"] = 84201,
            ["TalkActionId"] = {
                [1] = "84201:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_04_1",
            },
        [90070402] = {
            ["Content"] = "你在想过去的事？",
            ["ContentJP"] = "{性别:昔のことを思い出しているのか？|昔のことを思い出しているの？}",
            ["DialogueId"] = 90070402,
            ["GUID"] = "E17B572B",
            ["NextDialogue"] = 90070403,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84201:Talk02_End",
                },
            },
        [90070403] = {
            ["Content"] = "不，我是与过去诀别之人，没有过去，只是今天多喝了半杯酒而已。",
            ["ContentJP"] = "いや、俺は過去と決別した。俺の過去などすでに存在していない。ただ今日は……酒を少しばかり飲みすぎただけだ。",
            ["DialogueId"] = 90070403,
            ["GUID"] = "E17B572C",
            ["NextOptions"] = {
                [1] = 90070002,
                [2] = 90070003,
                },
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90070501] = {
            ["Content"] = "虽然不知道你告别了怎样的过去，但我们气息相似，保持距离吧：我并不喜欢同类。",
            ["ContentJP"] = "お前がどんな過去と決別したのかは知らないが、少なくとも俺たちは似た気配をまとっている。だからこそお前とは距離を置きたい。悪いが俺は、同類が好きではないのだ。",
            ["DialogueId"] = 90070501,
            ["GUID"] = "E17B6792",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_companio_01",
            },
        [90070601] = {
            ["Content"] = "我早已不是你的故知。世人萍水相逢本就如风过耳，放下吧。",
            ["ContentJP"] = "俺はもう、お前の昔馴染みでもなんでもない。人との出会いは過ぎ去る風と同じ。全て忘れた方がお前にとってもいい風が吹くはずだ。",
            ["DialogueId"] = 90070601,
            ["GUID"] = "E17B77FA",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_companio_02",
            },
        [90070701] = {
            ["Content"] = "我羡慕你的意志与同样坚固的法条，不知道你可有过什么时刻，曾自我怀疑过。",
            ["ContentJP"] = "お前の揺るがない意志と、堅固な法を羨ましくも思ったが……そんな己を疑った瞬間は一度もないのか？",
            ["DialogueId"] = 90070701,
            ["GUID"] = "E17B8862",
            ["SpeakNpcId"] = 84201,
            ["VoiceName"] = "voice/$Locale$/char/Yuming/vo_companio_03",
            },
        [90080000] = {
            ["Content"] = "嗯……这个自动绕后的折叠枪可以升级成连发的……火力也可以再猛一些……嗯，不错不错，下次出任务就可以更快地解决敌人，然后回家休息了。",
            ["ContentJP"] = "ふむ……自動で敵の背後に回り込む折り畳み式の銃。それに連射力向上のアップグレードを施すべきか否か。火力も高められる可能性があるならば……よし、次の任務ではもっと早く敵が始末できるぞ。そして休める時間が増えるって寸法だ。",
            ["DialogueId"] = 90080000,
            ["GUID"] = "E1817E29",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_idle",
            },
        [90080001] = {
            ["Content"] = "呼~刚睡醒的感觉好舒爽啊，你呀，也不要每天太紧绷了，任务是永远也做不完的，要懂得休息。",
            ["ContentJP"] = "あー……心地のいい目覚めは何と清々しいのやら。あなたも、もっと肩の力を抜いて気楽にいきましょうよ。どうせ次から次へと任務が来るんですから。休める時は休んだ方が得策ですよ。",
            ["DialogueId"] = 90080001,
            ["GUID"] = "E1817E2A",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextOptions"] = {
                [1] = 900800011,
                [2] = 900800012,
                [3] = 900800013,
                [4] = 900800014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90080002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90080002,
            ["GUID"] = "90080002.0",
            ["NextDialogue"] = 90080001,
            },
        [90080003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90080003,
            ["GUID"] = "90080003.0",
            },
        [90080101] = {
            ["Content"] = "家里人？我爸妈都好多年没管过我了，也就两位姐姐偶尔会对我指手画脚，不过啊我现在进了军团，她们进不来。",
            ["ContentJP"] = "家族ですか？両親は僕のことなんか気にかけませんよ。ふたりの姉はたまに口を挟んできますが、今の僕は軍属ですからね。幸いにもあれこれとは立ち入れないんです。",
            ["DialogueId"] = 90080101,
            ["GUID"] = "E1818E92",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080103,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_01_1",
            },
        [90080103] = {
            ["Content"] = "听起来你的姐姐们很凶。",
            ["ContentJP"] = "お姉さんたちは気が強いって聞いたけど。",
            ["DialogueId"] = 90080103,
            ["GUID"] = "E1818EE6",
            ["NextDialogue"] = 90080104,
            ["SpeakNpcId"] = 100001,
            },
        [90080104] = {
            ["Content"] = "不，不是的，她们都是泼可爱动人聪明贤惠温柔乐观善良积极天真烂漫落落大方的美人！不过，如果能端庄一点就更好了……",
            ["ContentJP"] = "い、いいえ。元気で可愛くて、魅力的で知的で、優しく明るく、ポジティブかつジェントル、天真爛漫感謝感激な麗しき姉たちです！いや、ただ淑やかさが少し足りないもので……",
            ["DialogueId"] = 90080104,
            ["GUID"] = "E1818F10",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90080201] = {
            ["Content"] = "呵，你们这些不懂休息好的人有难了！听我说：床是抚慰心灵的港湾，屋顶是洗涤灵魂的圣地，午后的花园是光明降临的方向，小憩的时刻是甜蜜的交响诗……",
            ["ContentJP"] = "これはこれは、上手な休み方を理解してないとは大変だ！今から語る言葉にしっかりと耳を傾けてください。ベッドは魂を癒す楽園、屋根は魂を清める聖域、午後の庭は光明の差す場所、昼寝は甘い交響曲……",
            ["DialogueId"] = 90080201,
            ["GUID"] = "E1819EFA",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080203,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_02_1",
            },
        [90080203] = {
            ["Content"] = "（转身离开。）",
            ["ContentJP"] = "（背を向けて離れる）",
            ["DialogueId"] = 90080203,
            ["GUID"] = "E1819F4E",
            ["NextDialogue"] = 90080204,
            ["SpeakNpcId"] = 100001,
            },
        [90080204] = {
            ["Content"] = "……诶！你等我念完啊！",
            ["ContentJP"] = "……っておーい！最後まで聞いてくれ！",
            ["DialogueId"] = 90080204,
            ["GUID"] = "E1819F78",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90080301] = {
            ["Content"] = "她可太能使唤人了，一个人劈三份都不够用……咳，我是说，西比尔大人作为长官，对下属一向严格。",
            ["ContentJP"] = "とにかく人使いが荒いもんですから、3人に分身したとしてもまだ足りない感じ……ゴホン、シビル軍団長様は上級将校として部下に厳しい方ですね。それをお伝えしたく思っただけです。",
            ["DialogueId"] = 90080301,
            ["GUID"] = "E181AF62",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080303,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_03_1",
            },
        [90080303] = {
            ["Content"] = "改口也没用，我已经听到了。",
            ["ContentJP"] = "{性别:言い直してももう遅いって、全部聞こえちゃった。|言い直してももう遅いよ、全部聞こえちゃった。}",
            ["DialogueId"] = 90080303,
            ["GUID"] = "E181AFB6",
            ["NextDialogue"] = 90080304,
            ["SpeakNpcId"] = 100001,
            },
        [90080304] = {
            ["Content"] = "哎呀，这可怎么办才好呢……要不，我请你一份下午茶，你就当什么都没有听见，怎么样？别担心，里面没有下药。",
            ["ContentJP"] = "これはしくじったな……ではこうしましょう、アフタヌーンティーをご馳走します。それに免じて、何も聞こえなかったことにするのはどうです？毒など入れたりはしないので、ご安心ください。",
            ["DialogueId"] = 90080304,
            ["GUID"] = "E181AFE0",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90080401] = {
            ["Content"] = "我给你设计了一个好东西，一个小型机器人偶！战斗的时候它可以跟在你后面一边摇小旗，一边大喊“加油！”“你揍人的样子真的很酷！”",
            ["ContentJP"] = "あなたのために素晴らしいモノを設計しました。この小型ロボットは、戦闘の際に後ろで旗を振って、「頑張れ！」「戦う姿が素敵！」「やっちまいな！」と応援してくれるんです。",
            ["DialogueId"] = 90080401,
            ["GUID"] = "E181BFCA",
            ["LookAt"] = {
                [1] = "84202:n(0)",
                [2] = "0:n(84202)",
                },
            ["NextDialogue"] = 90080403,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_04_1",
            },
        [90080403] = {
            ["Content"] = "怎么样，是不是感觉浑身充满力量？等我把它做出来……",
            ["ContentJP"] = "どうです？全身から力が湧きでるような応援でしょう？完成まで待っててくださいね……",
            ["DialogueId"] = 90080403,
            ["GUID"] = "E181BFF4",
            ["NextDialogue"] = 90080404,
            ["SpeakNpcId"] = 84202,
            ["TalkActionId"] = {
                [1] = "84202:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_04_2",
            },
        [90080404] = {
            ["Content"] = "（转身离开。）",
            ["ContentJP"] = "（背を向けて離れる）",
            ["DialogueId"] = 90080404,
            ["GUID"] = "E181BFF5",
            ["NextDialogue"] = 90080405,
            ["SpeakNpcId"] = 100001,
            },
        [90080405] = {
            ["Content"] = "喂喂，别走啊，图纸可是我瞒着西比尔长官，用宝贵的休息时间画的——",
            ["ContentJP"] = "ってあれ、どこへ行くんです？い、行かないでー！貴重な休み時間を割いて作った、シビル長官にも内緒の設計図なんだぞー！",
            ["DialogueId"] = 90080405,
            ["GUID"] = "E181BFF6",
            ["NextOptions"] = {
                [1] = 90080002,
                [2] = 90080003,
                },
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90080501] = {
            ["Content"] = "报告军团长，今日的工作已经安排完毕，您如果有其他的需要，可以随时下达指示。不过今日的工作已经很饱和了，您还是要注意歇息，不要再给自己增添额外的负担了。",
            ["ContentJP"] = "お疲れさまです、長官殿。仕事の段取りを組んでおきました。何かあればいつでも指示を受けられる状態です。しかしながら今日はすでに仕事がいっぱいですので、休憩時間をしっかり確保して、ご自分に今以上の余計な負担をかけないよう、ご注意くださいね。",
            ["DialogueId"] = 90080501,
            ["GUID"] = "E181D032",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_companio_01",
            },
        [90080601] = {
            ["Content"] = "上次的任务真是辛苦你了，不过我接到了一些投诉，说是你在执行任务中损坏公物，唉，你是知道我的，我这么羞涩内向，还要替你去赔不是，这也太难为我了。所以……这几个紧急任务就麻烦你代劳了，相信美丽善良和蔼可亲的琳恩小姐一定不会拒绝的吧！",
            ["ContentJP"] = "前回の任務はご苦労さまでした。しかしですね、任務中に公共物が壊れたとクレームが寄せられているんです。はぁ……こーんなに内向的な僕があなたに代わって謝罪に行かなくてはいけないんですよ。なので……こちらの緊急任務をあなたに一任します。美しく優しいリーンさんなら絶対に断ったりしないはず……ですよね？",
            ["DialogueId"] = 90080601,
            ["GUID"] = "E181E09A",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_companio_02",
            },
        [90080701] = {
            ["Content"] = "嗯，你怎么会……？哎呀，看来我还是休息太少，竟然都出现幻觉，能看见不存在的人了！之后向长官打个工伤报告，再休两天病假好了。",
            ["ContentJP"] = "おお…なんてことだ……やっぱり休暇が足りていないのか？存在しない人の幻覚まで見てしまうとは！あとで長官殿に労務災害の報告をして、何日か病気休暇を取らなくては、うん。",
            ["DialogueId"] = 90080701,
            ["GUID"] = "E181F102",
            ["SpeakNpcId"] = 84202,
            ["VoiceName"] = "voice/$Locale$/char/Landi/vo_companio_03",
            },
        [90090000] = {
            ["Content"] = "居然把后背轻易暴露给自己的敌人……，该说你天真还是愚蠢？",
            ["ContentJP"] = "よくもまあ簡単に、敵に背中を晒すわね？無邪気と言うべきか、愚かと言うべきか。",
            ["DialogueId"] = 90090000,
            ["GUID"] = "E187E6C9",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_idle",
            },
        [90090001] = {
            ["Content"] = "看到你日复一日这样奔波努力，我就忍不住开始想象，想象你再次挑战我的那一天，让人期待。",
            ["ContentJP"] = "そうやって毎日駆けずり回って足掻くお前を見ていると、想像してしまうわね。再び私に立ち向かってくるであろう日を。楽しみでしかたないわ。",
            ["DialogueId"] = 90090001,
            ["GUID"] = "E187E6CA",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextOptions"] = {
                [1] = 900900011,
                [2] = 900900012,
                [3] = 900900013,
                [4] = 900900014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90090002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90090002,
            ["GUID"] = "90090002.0",
            ["NextDialogue"] = 90090001,
            },
        [90090003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90090003,
            ["GUID"] = "90090003.0",
            },
        [90090101] = {
            ["Content"] = "直属于皇帝的特殊军团，执行机密的任务，以及作为战场上随时击出的铁锤。",
            ["ContentJP"] = "皇帝直属の鉄槌……要は機密任務を遂行する特殊部隊よ。いついかなる時も戦地に赴く機動部隊でもあるわね。",
            ["DialogueId"] = 90090101,
            ["GUID"] = "E187F732",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090103,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_01_1",
            },
        [90090103] = {
            ["Content"] = "有皇帝在背后支持，难怪这么蛮横。",
            ["ContentJP"] = "{性别:皇帝の後ろ盾があるから、そんなに横暴なんだな。|皇帝の後ろ盾があるから、そんなに横暴なのね。}",
            ["DialogueId"] = 90090103,
            ["GUID"] = "E187F786",
            ["NextDialogue"] = 90090104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84301:Talk03_End",
                },
            },
        [90090104] = {
            ["Content"] = "你误会了。没有皇帝，军团依旧是军团，但没有军团，皇冠可就要落地了。",
            ["ContentJP"] = "とんだ見当違いね。皇帝なくとも軍隊は変わらず軍隊であり続ける。軍隊がなければすぐにでも、王冠は地に転がるわ。",
            ["DialogueId"] = 90090104,
            ["GUID"] = "E187F7B0",
            ["NextDialogue"] = 90090105,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_01_2",
            },
        [90090105] = {
            ["Content"] = "凭这句话，我是不是可以检举你打算谋反？",
            ["ContentJP"] = "いまの言葉は「軍団長に反乱の兆候あり」って告発できそう。",
            ["DialogueId"] = 90090105,
            ["GUID"] = "E187F7DA",
            ["NextDialogue"] = 90090106,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "84301:Confident_Start",
                },
            },
        [90090106] = {
            ["Content"] = "你大可以这么做，毕竟谋逆可是重罪，然后你的状告书会立刻被逐级上报，最后呈到我的书桌上。",
            ["ContentJP"] = "やってみなさいな。謀反は重罪だから、すぐに上層部に告発状が回ってくるでしょうね。で、最終的な提出先は私の机の上ってわけ。",
            ["DialogueId"] = 90090106,
            ["GUID"] = "E187F804",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90090201] = {
            ["Content"] = "呵，我并非忠于帝国，只是忠于理想罢了。曾有一个人为了这个理想付出了他的一切，而我要铭记与践行他的意志。",
            ["ContentJP"] = "ふふ、私は帝国ではなく、理想に忠実なのよ。昔、その理想のためにすべてを捧げた方がいたわ。私は、あの方の意志を身に刻み、実践し続けるのみ。",
            ["DialogueId"] = 90090201,
            ["GUID"] = "E188079A",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090203,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_02_1",
            },
        [90090203] = {
            ["Content"] = "你在诡辩。不管原因为何，你的所作所为就是为虎作伥。",
            ["ContentJP"] = "詭弁だよ、理由なんて関係ない。やっていることはただの悪の手先だし。",
            ["DialogueId"] = 90090203,
            ["GUID"] = "E18807EE",
            ["NextDialogue"] = 90090204,
            ["SpeakNpcId"] = 100001,
            },
        [90090204] = {
            ["Content"] = "我不否认，不过为了我想要的，我会抓紧能利用的一切，不择手段地往上爬。但我每爬一步，都离我的理想更近一步。而你，又走到了哪一步呢？",
            ["ContentJP"] = "否定はしないわ。望むモノのためならば、私は手段を問わずなんでも利用して這い上がる。一歩這い上がれば、理想に一歩近づけるもの。お前はどうなの？自分の理想にどこまで近づけているのかしら？",
            ["DialogueId"] = 90090204,
            ["GUID"] = "E1880818",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90090301] = {
            ["Content"] = "没关系，我的家人很早就不在了。",
            ["ContentJP"] = "ええ、全然。とっくの昔に私の家族は死んでいるもの。",
            ["DialogueId"] = 90090301,
            ["GUID"] = "E1881802",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090303,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_03_1",
            },
        [90090303] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 90090303,
            ["GUID"] = "E1881856",
            ["NextDialogue"] = 90090304,
            ["SpeakNpcId"] = 100001,
            },
        [90090304] = {
            ["Content"] = "我甚至为此庆幸，这样一来我就没有了后顾之忧，只需要专心和正面与背面的敌人们厮杀。",
            ["ContentJP"] = "ありがたいことね。お陰で私には不安材料がないのだから。敵を倒すことだけに専念できるわ。",
            ["DialogueId"] = 90090304,
            ["GUID"] = "E1881880",
            ["NextDialogue"] = 90090305,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_03_2",
            },
        [90090305] = {
            ["Content"] = "情感，对于每一个踏入军团的人来说，都是破绽罢了。",
            ["ContentJP"] = "感情なんて、帝国軍に属する者には必要ない。破滅につながる障害よ。",
            ["DialogueId"] = 90090305,
            ["GUID"] = "E18818AA",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90090401] = {
            ["Content"] = "当然，当面的咒骂和揶揄我已经听过不少，阴沟里的硕鼠们的抱怨只会更多。",
            ["ContentJP"] = "もちろん、面と向かっての罵倒やあざけりは耳が腐るほど聞いたわ。影でコソコソ言うネズミどもの嫌味のほうがもっと多いけどね。",
            ["DialogueId"] = 90090401,
            ["GUID"] = "E188286A",
            ["LookAt"] = {
                [1] = "84301:n(0)",
                [2] = "0:n(84301)",
                },
            ["NextDialogue"] = 90090403,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_04_1",
            },
        [90090403] = {
            ["Content"] = "所幸，尽管这个世界有万般不公，但只要坐拥众人之上的力量，就能获得最起码的善意。",
            ["ContentJP"] = "でもね、幸い、世界がどれほど不公平であろうと、愚衆の上に立つ力さえ持っていれば、少なくとも最低限の善意は得られるわね。",
            ["DialogueId"] = 90090403,
            ["GUID"] = "E18828BE",
            ["NextDialogue"] = 90090404,
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_04_2",
            },
        [90090404] = {
            ["Content"] = "那么如果你失去了力量，他们一定会落井下石。",
            ["ContentJP"] = "いつか力を失った時に必ず復讐されるよ。",
            ["DialogueId"] = 90090404,
            ["GUID"] = "E18828E8",
            ["NextDialogue"] = 90090405,
            ["SpeakNpcId"] = 100001,
            },
        [90090405] = {
            ["Content"] = "那是自然，所以我永远不会对他们卑躬屈膝，否则，他们会立刻变成闻到血腥味的狼群。",
            ["ContentJP"] = "何を当たり前のことを。だからこそ私は絶対に連中に弱みを見せたりしないのよ。さもなくば、ヤツらはすぐに血に飢えた狼の群れとなるでしょうね。",
            ["DialogueId"] = 90090405,
            ["GUID"] = "E1882912",
            ["NextOptions"] = {
                [1] = 90090002,
                [2] = 90090003,
                },
            ["SpeakNpcId"] = 84301,
            ["TalkActionId"] = {
                [1] = "84301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90090501] = {
            ["Content"] = "……你与我，是时候做个了断了。",
            ["ContentJP"] = "……貴方と私、そろそろ決着をつけましょう？",
            ["DialogueId"] = 90090501,
            ["GUID"] = "E18838D2",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_companio_01",
            },
        [90090801] = {
            ["Content"] = "你的伪装越是完美，就说明你的獠牙在暗地里打磨地越发锋锐，我等着你脱缰的那一天，亲手敲断你的大牙。",
            ["ContentJP"] = "偽りの顔が完璧であればあるほど、隠された牙が鋭くなっている証拠なのよ。お前が化けの皮を脱ぎ捨てる時が待ち遠しいわ。その時には私がこの手で、お前の牙を引き抜いてやるから。",
            ["DialogueId"] = 90090801,
            ["GUID"] = "E1886A0A",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_companio_04",
            },
        [90091001] = {
            ["Content"] = "近期的任务说明、作战计划、后勤运输、损失条目都整理好了吗。\
好，那今天再和我把对外宣传标语、对内案例分析、对皇帝的定期报告以及佩剑炼金院新武器的测试数据做完。工作，可不能叫额外的负担。",
            ["ContentJP"] = "近日の任務説明、作戦プラン、後方輸送、損失は照合したかしら？\
よし、なら今日は対外宣伝、対内案件の分析、皇帝への定期報告とサーベル錬金院が開発した新兵器の試験データを私と一緒に完成しましょう。これは仕事よ、余計な負担とは言わせないわ。",
            ["DialogueId"] = 90091001,
            ["GUID"] = "E1888ADA",
            ["SpeakNpcId"] = 84301,
            ["VoiceName"] = "voice/$Locale$/char/Xibi/vo_companio_05",
            },
        [90100000] = {
            ["Content"] = "什么都不做，只是就这样看着大家，就感觉过得好快好快……真希望时间能走慢一点儿呀。",
            ["ContentJP"] = "何もしないで、ただみんなを眺めているだけでも、時間があっという間に過ぎていくみたい……もっと時間がゆっくりだったら良いのに……",
            ["DialogueId"] = 90100000,
            ["GUID"] = "E18E4F69",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_idle",
            },
        [90100001] = {
            ["Content"] = "太好了，今天我还在这儿。而且，你也在这儿……",
            ["ContentJP"] = "よかった、今日もまだ私はここにいるよ。そしてあなたも、ここにいるの……",
            ["DialogueId"] = 90100001,
            ["GUID"] = "E18E4F6A",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextOptions"] = {
                [1] = 901000011,
                [2] = 901000012,
                [3] = 901000013,
                [4] = 901000014,
                [5] = 901000015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90100002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90100002,
            ["GUID"] = "90100002.0",
            ["NextDialogue"] = 90100001,
            },
        [90100003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90100003,
            ["GUID"] = "90100003.0",
            },
        [90100101] = {
            ["Content"] = "谢谢，着凉的话不用担心啦，卡戎之民是不怎么怕冷的，正好也不用再去买又厚又贵的大衣。",
            ["ContentJP"] = "ありがとう。風邪の心配はいらないの。カロン族は寒さに強いから、値の張るコートを買う必要もないんだよ。",
            ["DialogueId"] = 90100101,
            ["GUID"] = "E18E5FD2",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100103,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_01_1",
            },
        [90100103] = {
            ["Content"] = "现在的衣服是妈妈帮我裁的，不过颜色是我自己选的，嫩绿色，这些蝴蝶形状的装饰也是我自己挑的，如果在暖和的南方的话，这一身应该就不奇怪了。",
            ["ContentJP"] = "この服はお母さんが作ってくれたんだけど、若葉色とか、蝶の飾りとかは、自分で選んだの。暖かい南の方だったら、この身なりでもおかしくないよね。",
            ["DialogueId"] = 90100103,
            ["GUID"] = "E18E6026",
            ["NextDialogue"] = 90100104,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_01_2",
            },
        [90100104] = {
            ["Content"] = "原来是这样，蝴蝶装饰确实很适合你。",
            ["ContentJP"] = "そうなんだ。蝶々の飾りがサイキによく似合っているよ。",
            ["DialogueId"] = 90100104,
            ["GUID"] = "E18E6050",
            ["NextDialogue"] = 90100105,
            ["SpeakNpcId"] = 100001,
            },
        [90100105] = {
            ["Content"] = "真的吗？太好了。其实我只见过冰湖城附近的蝴蝶，都是蓝色的。要是能去其他地方，看一看不同颜色的蝴蝶就好了。",
            ["ContentJP"] = "本当？よかった。実は私、アイスレイク城の近くにいる青い蝶しか見たことがなくて。ほかの場所でいろんな色の蝶が見れたらいいのにな。",
            ["DialogueId"] = 90100105,
            ["GUID"] = "E18E607A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90100201] = {
            ["Content"] = "是的，据说几百年来一直都是这个样子。人们看到我们总像看到老鼠一样，我自己也被人追着骂过很难听的话。",
            ["ContentJP"] = "うん、何百年もずっとそうみたい。カロン族は悪い虫みたいな扱いで……私も酷い言葉を浴びせられたことがあるの。",
            ["DialogueId"] = 90100201,
            ["GUID"] = "E18E703A",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100203,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_1",
            },
        [90100203] = {
            ["Content"] = "因为索拉畏惧卡戎的力量？",
            ["ContentJP"] = "カロンの力を恐れているから？",
            ["DialogueId"] = 90100203,
            ["GUID"] = "E18E708E",
            ["NextDialogue"] = 90100204,
            ["SpeakNpcId"] = 100001,
            },
        [90100204] = {
            ["Content"] = "或许吧。“魔法是最邪恶的东西”，大家总是这么说。历史书上也写着，卡戎之民的先祖在一千多年前，曾经凭借魔法支配索拉之民，做出了很多恶事。",
            ["ContentJP"] = "多分ね。「魔法は世界で一番邪悪なものだ」って、みんなそう言うの。ほら、千年以上も前にカロン族の先祖が魔法を使ってソラの民を支配して、ひどいことをたくさんしたって、歴史書にも書いてあるでしょ。だから、そう思われるのも仕方ないのかも……",
            ["DialogueId"] = 90100204,
            ["GUID"] = "E18E70B8",
            ["NextDialogue"] = 90100205,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_2",
            },
        [90100205] = {
            ["Content"] = "说实话我有点难想象……因为我看到的卡戎们都很害怕索拉之民，不太敢和他们说话，在他们面前总是小心翼翼的，更不敢使用魔法。",
            ["ContentJP"] = "まったく想像できないよ……カロンたちって、ソラの民の前ではいつもオドオドしてて、話しかけるのもやっとだというほどなのに。ましてや魔法を使うなんて……",
            ["DialogueId"] = 90100205,
            ["GUID"] = "E18E70E2",
            ["NextDialogue"] = 90100206,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_3",
            },
        [90100206] = {
            ["Content"] = "而且其实大多数卡戎魔法都很寻常，也就是能用来点点壁炉，冰冻一下食物之类的。",
            ["ContentJP"] = "本当はカロンの魔法ってそんなにすごいものじゃないんだけど。ほとんどは、暖炉に火をつけたりとか、食べ物を冷凍したりとか、そんな感じで。",
            ["DialogueId"] = 90100206,
            ["GUID"] = "E18E710C",
            ["NextDialogue"] = 90100207,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_4",
            },
        [90100207] = {
            ["Content"] = "你会想回到那个时代吗——卡戎之民支配索拉之民的时代？",
            ["ContentJP"] = "カロン族がソラの民を支配していた時代に戻りたいと思ったりする？",
            ["DialogueId"] = 90100207,
            ["GUID"] = "E18E7136",
            ["NextDialogue"] = 90100208,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85301:Talk01_End",
                },
            },
        [90100208] = {
            ["Content"] = "不，一点也不。为什么卡戎之民和索拉之民之间，一定要一个支配另一个，一个畏惧另一个呢？",
            ["ContentJP"] = "ううん、全然。支配と恐怖しか選べない世の中なんて、変と思わない？",
            ["DialogueId"] = 90100208,
            ["GUID"] = "E18E7160",
            ["NextDialogue"] = 90100209,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_5",
            },
        [90100209] = {
            ["Content"] = "我希望的只是……到了春天，所有人都能一起肩并着肩，一起去原野上看各种各样的花。只要这样就够了。",
            ["ContentJP"] = "私の願いはひとつだけ……春になったら、みんなで一緒に野原でいろんな花を見たい。それだけで十分なの。",
            ["DialogueId"] = 90100209,
            ["GUID"] = "E18E718A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_02_6",
            ["bForbidSkipOptions"] = true,
            },
        [90100301] = {
            ["Content"] = "啊，大概是因为我在试着培育新的花朵。修普诺斯之家前面的庭院只有几棵树，总觉得有点儿光秃秃的。所以，我想在那里种满白色的花……",
            ["ContentJP"] = "あ、新しい花を育てているからかも。ヒュプノスの家の庭……木が少し植えてあるだけで、なんだか殺風景な感じがするから、白いお花でいっぱいにしたくて。",
            ["DialogueId"] = 90100301,
            ["GUID"] = "E18E80A2",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100303,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_03_1",
            },
        [90100303] = {
            ["Content"] = "在这里也种一点吧，铃兰，银莲，仙女木……哪种更合适呢？",
            ["ContentJP"] = "ここにも少し植えてみたいな。スズランにアネモネ、ドリアス……何がいいかな？",
            ["DialogueId"] = 90100303,
            ["GUID"] = "E18E80F6",
            ["NextDialogue"] = 90100304,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_03_2",
            },
        [90100304] = {
            ["Content"] = "也许可以问问大家的意见。",
            ["ContentJP"] = "みんなに意見を聞いてみようか。",
            ["DialogueId"] = 90100304,
            ["GUID"] = "E18E8120",
            ["NextDialogue"] = 90100305,
            ["SpeakNpcId"] = 100001,
            },
        [90100305] = {
            ["Content"] = "你说得对，应该让大家一起决定……我会去问问看的！啊，对了，这些花里有你喜欢的品种吗？等花开了，我摘一些送给你吧。",
            ["ContentJP"] = "そうね、みんなで決めたほうがいいかも……うん、聞いてみるね！あ、それと、さっき言った花の中で好きな品種とかあったりするかな？花が咲いたら、プレゼントしたいの！",
            ["DialogueId"] = 90100305,
            ["GUID"] = "E18E814A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90100401] = {
            ["Content"] = "嗯，我从出生起就一直住在这里，虽然每天都能听到列车的声音，但从来没去过其他地方。如果有机会的话，真想去外面看一看。",
            ["ContentJP"] = "うん、生まれた時からずっとここに住んでいるの。列車の音を毎日聞いているけど、他の場所に行ったことはなくて。機会があれば、外の世界を見てみたいな。",
            ["DialogueId"] = 90100401,
            ["GUID"] = "E18E80CC",
            ["LookAt"] = {
                [1] = "85301:n(0)",
                [2] = "0:n(85301)",
                },
            ["NextDialogue"] = 90100403,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_04_1",
            },
        [90100403] = {
            ["Content"] = "想去哪些地方呢？",
            ["ContentJP"] = "どこに行きたい？",
            ["DialogueId"] = 90100403,
            ["GUID"] = "E18E80CB",
            ["NextDialogue"] = 90100404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85301:Explain02_End",
                },
            },
        [90100404] = {
            ["Content"] = "唔，我想想，皇都总是要去的，恩里克叔叔说过丹流城的落日也很好看。对了，还想去你说的净界岛，在南方的海岛上，闻一闻海风是不是真的是咸的！",
            ["ContentJP"] = "えと、そうだな……帝都は絶対に行くとして、レッドバリー城の夕日もきれいだってヘンリックおじさんが言っていたし。そう、{nickname}のパーガトリー島にも行ってみたい！南の島で、海風が本当に塩辛いか、確かめてみるの！",
            ["DialogueId"] = 90100404,
            ["GUID"] = "E18E910A",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90100501] = {
            ["Content"] = "没什么，我只是想……再多看几眼，这样我就可以把你们的样子记得更清楚了。",
            ["ContentJP"] = "ううん、別に。私はただ……もう少しだけ、見ていたいだけなの。{nickname}やみんなのことを、もっとはっきり覚えていられるように。",
            ["DialogueId"] = 90100501,
            ["GUID"] = "E18EA172",
            ["NextDialogue"] = 90100502,
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_05_1",
            },
        [90100502] = {
            ["Content"] = "如果可以，你可以也多看我几眼吗？我也想让你记住我的样子……我现在的样子。",
            ["ContentJP"] = "もし叶うなら、{nickname}も私をもっと、見ていてくれないかな？私のことも覚えていて……私の今を、今の姿を。",
            ["DialogueId"] = 90100502,
            ["GUID"] = "E18EA19C",
            ["NextOptions"] = {
                [1] = 90100002,
                [2] = 90100003,
                },
            ["SpeakNpcId"] = 85301,
            ["TalkActionId"] = {
                [1] = "85301:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_topic_05_2",
            ["bForbidSkipOptions"] = true,
            },
        [90100601] = {
            ["Content"] = "我听说奥特赛德先生为菲娜的生日精心准备了很久。虽然嘴上不饶人，但你其实是个很体贴的人吧？下一次菲娜生日，我可以和你们一起为她准备惊喜吗？",
            ["DialogueId"] = 90100601,
            ["GUID"] = "E18EB1DA",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_companio_01",
            },
        [90100701] = {
            ["Content"] = "看见卡米拉女士总会让我想起那间吵闹却温馨的酒馆……这些年能够认识大家，真是太好了。",
            ["ContentJP"] = "カミラさんに会うたびに、あの酒場を思い出すんだ。騒がしいけど居心地がよくて……この何年間かでみんなと知り合うことができて、本当によかった。",
            ["DialogueId"] = 90100701,
            ["GUID"] = "E18EC242",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_companio_02",
            },
        [90100801] = {
            ["Content"] = "你要讲艾利西安的故事给我听吗？太感谢了！唔……作为回礼，我应该送你什么花好呢……\
咦，你最喜欢好吃的花？",
            ["ContentJP"] = "エリュシオンのお話を教えてくれるのね？ 本当にありがとう！ お礼に何かお花をプレゼントしたいのだけど、どんなお花が欲しいかな？\
えっ、一番は美味しいお花？",
            ["DialogueId"] = 90100801,
            ["GUID"] = "E18ED2AA",
            ["SpeakNpcId"] = 85301,
            ["VoiceName"] = "voice/$Locale$/char/Saiqi/vo_companio_03",
            },
        [90110000] = {
            ["Content"] = "晨间打扫后通风，午后四处喷洒烈酒，薄暮时再点几支香驱散蚊虫，只有这样才能保持室内洁净。",
            ["ContentJP"] = "朝はお掃除をしたあとで換気を済ませ、昼に強いお酒で消毒をし、夕方には香を焚いて蚊を払う――こうして初めて、室内を清潔に保ち、病を遠ざけることができるのです。",
            ["DialogueId"] = 90110000,
            ["GUID"] = "E194B809",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_idle",
            },
        [90110001] = {
            ["Content"] = "居移气，养移体，不妨趁天气晴朗出去走走，想必对身体会有所裨益。",
            ["ContentJP"] = "環境と習慣は心身を育てるものだと聞いたことはありますか？せっかくの晴れ間ですし、外に出て少し散策などなさってはいかがですか？健康にとって何よりの良薬となりましょう。",
            ["DialogueId"] = 90110001,
            ["GUID"] = "E194B80A",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextOptions"] = {
                [1] = 901100011,
                [2] = 901100012,
                [3] = 901100013,
                [4] = 901100014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90110002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90110002,
            ["GUID"] = "90110002.0",
            ["NextDialogue"] = 90110001,
            },
        [90110003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90110003,
            ["GUID"] = "90110003.0",
            },
        [90110101] = {
            ["Content"] = "确然。只是书中的内容晦涩难懂，药石之间的差异，在我看来也难以辨别。或许，我在此道上确实没什么天赋。",
            ["ContentJP"] = "左様でございます。ただ、私にとって書に記された内容は難解を極め、薬石の違いすら見分けられません。恐らく、私は医術の才に恵まれていないのでしょう。",
            ["DialogueId"] = 90110101,
            ["GUID"] = "E194C872",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110103,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_1",
            },
        [90110103] = {
            ["Content"] = "咦？我还以为对医师来说，这些都信手拈来呢。",
            ["ContentJP"] = "え？医者にとっては、そんなの朝飯前だと思ってた。",
            ["DialogueId"] = 90110103,
            ["GUID"] = "E194C8C6",
            ["NextDialogue"] = 90110104,
            ["SpeakNpcId"] = 100001,
            },
        [90110104] = {
            ["Content"] = "在我的时代……药物并不是医治疾病的主流方式，人们通常依靠一种名为“祝由术”的奇迹驱退病魔。",
            ["ContentJP"] = "私の時代では……治療の主流は薬ではありませんでした。人々は「祝由術」と呼ばれる奇跡に頼って病魔を追い払っていたんです。",
            ["DialogueId"] = 90110104,
            ["GUID"] = "E194C8F0",
            ["NextDialogue"] = 90110105,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_2",
            },
        [90110105] = {
            ["Content"] = "然而，这种治疗方式虽然会带来“治愈”与“平安”，但也代表着“交换”与“牺牲”。从没有寿终正寝的医者，透支生命直至亡故才是我们唯一的选择。",
            ["ContentJP"] = "しかし、この治療法は「癒し」と「安らぎ」をもたらす一方で、「代償」と「犠牲」を伴うものでした。 天寿を全うした医師はおらず、命を燃やし尽くして果てること、それが我々の宿命でございます。",
            ["DialogueId"] = 90110105,
            ["GUID"] = "E194C8F1",
            ["NextDialogue"] = 90110106,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_3",
            },
        [90110106] = {
            ["Content"] = "……真是沉重的使命啊。",
            ["ContentJP"] = "……なんとも重い使命だね。",
            ["DialogueId"] = 90110106,
            ["GUID"] = "E194C8F2",
            ["NextDialogue"] = 90110107,
            ["SpeakNpcId"] = 100001,
            },
        [90110107] = {
            ["Content"] = "枯荣阁虽然已是岁月的一件遗物，但在治病救人的道路上，永远不缺后继者。即便使命沉重，总有人会肩负起这份责任，矢志不渝地走下去。",
            ["ContentJP"] = "枯栄閣は、今や時代に取り残された遺物となってしまいました。ですが、病を癒し命を救う道において、後継の志士が絶えることはありません。たとえその使命がいかに重かろうとも、この責務を背負い、志を貫いて歩み続ける者が、必ず現れるのです。",
            ["DialogueId"] = 90110107,
            ["GUID"] = "E194C8F3",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90110201] = {
            ["Content"] = "愿世间再无“无药可医”的顽疾。",
            ["ContentJP"] = "この世から「救えぬ病」を絶やすことでございます。",
            ["DialogueId"] = 90110201,
            ["GUID"] = "E194D8DA",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110203,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_04_1",
            },
        [90110203] = {
            ["Content"] = "好宏大的梦想……",
            ["ContentJP"] = "壮大な夢だね……",
            ["DialogueId"] = 90110203,
            ["GUID"] = "E194D92E",
            ["NextDialogue"] = 90110204,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "82401:Explain02_End",
                },
            },
        [90110204] = {
            ["Content"] = "听起来与空想无异吧？但即使没有术法带来的奇迹，医师所要做的事也从未改变。这样的话由我这个医书都未读通的人说出口，实在贻笑大方。",
            ["ContentJP"] = "夢物語のように聞こえるでしょう？ですが、術法の奇跡がなくとも、医師の果たすべき役目は何一つ変わりません。こんなこと、 医学書すら満足に読み解けぬ私が言うと、笑い話にしかなりませんね。",
            ["DialogueId"] = 90110204,
            ["GUID"] = "E194D958",
            ["NextDialogue"] = 90110205,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_04_2",
            },
        [90110205] = {
            ["Content"] = "但……我会继续在这条路上走下去，不止是为了黎民百姓，为了枯荣阁，也是为了我自己。",
            ["ContentJP"] = "それでも……私はこの道を進み続けます。民と枯栄閣のために、そして私自身のために――",
            ["DialogueId"] = 90110205,
            ["GUID"] = "E194D982",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90110301] = {
            ["Content"] = "一个治病救人的地方。",
            ["ContentJP"] = "病を癒し、命を救う場所でございます。",
            ["DialogueId"] = 90110301,
            ["GUID"] = "E194E942",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110303,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_1",
            },
        [90110303] = {
            ["Content"] = "还有别的吗？",
            ["ContentJP"] = "それだけ？",
            ["DialogueId"] = 90110303,
            ["GUID"] = "E194E944",
            ["NextDialogue"] = 90110304,
            ["SpeakNpcId"] = 100001,
            },
        [90110304] = {
            ["Content"] = "枯荣阁的使命，仅此而已。若说其他……每位入枯荣阁修行的医师，都要手植杏树一株，只是岁月流逝，风雨摧折，留存至今的已不足半数。",
            ["ContentJP"] = "枯栄閣の使命は、それに尽きます。強いて挙げるとすれば……枯栄閣で修行を積む医師たちは、杏の木を一本手植えする習わしがございます。しかし、時の移ろいとともに雨風に晒され、今も残る木は半数にさえ及ばぬありさまです。",
            ["DialogueId"] = 90110304,
            ["GUID"] = "E194E943",
            ["NextDialogue"] = 90110305,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_2",
            },
        [90110305] = {
            ["Content"] = "从长眠中苏醒后，我也曾去寻找回忆里那株属于我的杏树，但天不垂怜，花树已成枯木，今春虽暖，也未曾发出新芽来。",
            ["ContentJP"] = "長い眠りから覚めた後、私も記憶を便りに自分の杏の木を探しに行ったことがございます。残念ながら、その木はすでに枯れ果て、花どころか新芽のひとつもつけておりませんでした。今年の春は例年より暖かかったのですがね……",
            ["DialogueId"] = 90110305,
            ["GUID"] = "E194E945",
            ["NextDialogue"] = 90110306,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_3",
            },
        [90110306] = {
            ["Content"] = "叹隙中驹，石中火，梦中身，几时归去，空作闲人。过去的已无法挽留，就算想要弥补，也再无可能了。",
            ["ContentJP"] = "時の流れは隙間を駆ける馬のごとく、石の中の火花のように儚く、夢の中の我が身のように虚しいもの――いずれは、ただ空虚な存在として果てるのみ。過去はもはや取り戻せず、償いたいと願っても、それが叶うことは決してありません。",
            ["DialogueId"] = 90110306,
            ["GUID"] = "E194E946",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90110401] = {
            ["Content"] = "人死如灯灭，一切痕迹湮没，一切声息断绝。那种与世隔绝的寂静会吞没一切希望与可能，如果可以，我不希望任何一个病人落入那种境地。",
            ["ContentJP"] = "人の死は、まるで灯火がふっと消えるように、すべての痕跡は掻き消され、声すらも完全に途絶えます。その隔絶された静寂は、希望も可能性もことごとく呑み込み、すべてを無へと帰してしまう……私は、どの患者もそのような境地に陥らせたくはないのです。",
            ["DialogueId"] = 90110401,
            ["GUID"] = "E194F9AA",
            ["LookAt"] = {
                [1] = "82401:n(0)",
                [2] = "0:n(82401)",
                },
            ["NextDialogue"] = 90110403,
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_02_1",
            },
        [90110403] = {
            ["Content"] = "听起来，就像扶疏亲身体验过一样。",
            ["ContentJP"] = "まるで自分で体験したかのような言い方だね。",
            ["DialogueId"] = 90110403,
            ["GUID"] = "E194F9FE",
            ["NextDialogue"] = 90110404,
            ["SpeakNpcId"] = 100001,
            },
        [90110404] = {
            ["Content"] = "的确如你所说，我……曾经从一场重病中逃出生天。假使让我再次面对这样的考验，我也不知道自己是否还会坚持当初的选择。",
            ["ContentJP"] = "おっしゃる通り、私は……かつて重い病を患い、生死の境をさまよったことがございます。もし再びあの試練を迎えることになったとして、果たして同じ選択を貫けるのか――正直、自信はありません。",
            ["DialogueId"] = 90110404,
            ["GUID"] = "E194FA28",
            ["NextOptions"] = {
                [1] = 90110002,
                [2] = 90110003,
                },
            ["SpeakNpcId"] = 82401,
            ["TalkActionId"] = {
                [1] = "82401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90110501] = {
            ["Content"] = "兰迪先生，依我看来，懒惰散漫也是身患疾病的一种表现，如今虽一时无恙，但毕竟也是个隐患。不如我来陪你过上两招，活动活动筋骨，可好？",
            ["ContentJP"] = "ランディーさん、惰性も過ぎれば病の元ですよ。今は平気でも、いずれ体に障りかねません。この機会に、私と手合わせして少し体を動かしてみませんか？",
            ["DialogueId"] = 90110501,
            ["GUID"] = "E1950A12",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_companio_01",
            },
        [90110601] = {
            ["Content"] = "医者疗疾，却终究无法逆天改命。我可以为您开一贴缓解心热的药方，但病因却无法根除，但愿您能顺天应时，自渡为好……",
            ["ContentJP"] = "医師は病を癒せても、天命を変えることはできません。心を落ち着ける薬をお出しすることはできますが、病の根本を断つことはできないのです。どうか、自ら救いの道を見出してください……\
 ",
            ["DialogueId"] = 90110601,
            ["GUID"] = "E1951A7A",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_companio_02",
            },
        [90110701] = {
            ["Content"] = "有时会听到另一个人在说话？只有你能听见吗？近日睡眠如何？是否心有郁结？最怕心病难医，即使用上祝由术也无能为力，但身为医者，我必定竭尽全力。",
            ["ContentJP"] = "時折、誰かの声が聞こえるのですか？それは……あなただけに聞こえるものですか？最近よく眠れていますか？おそらく、心に何か引っかかることがあるのかもしれませんね。心の病は厄介なものです。祝由術をもってしても手に負えないこともありますが、医師として全力を尽くしましょう。",
            ["DialogueId"] = 90110701,
            ["GUID"] = "E1952AE2",
            ["SpeakNpcId"] = 82401,
            ["VoiceName"] = "voice/$Locale$/char/Baiheng/vo_companio_03",
            },
        [90120000] = {
            ["Content"] = "休息一会儿吧，榛子，吃点小麦，吃点坚果。再来上几朵花当零食，要是吃不完的话，我就先插在帽子上。",
            ["ContentJP"] = "ヘーゼルナッツ、ひと休みして、小麦とナッツを食べよう。おやつの花も少しある。食べきれなかったら、帽子に挿しとくからね。",
            ["DialogueId"] = 90120000,
            ["GUID"] = "E19B20A9",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_idle",
            },
        [90120001] = {
            ["Content"] = "太阳热气腾腾，云朵松软蓬蓬，早起的鸟儿吃个饱饱。你的肚子有没有像鸟儿一样咕咕叫呢？",
            ["ContentJP"] = "お日さまがポカポカで、雲はふわふわで、早起きの鳥さんたちももうお腹いっぱいだよ。あなたのお腹も、鳥さんたちみたいにグーグー鳴ってるの？",
            ["DialogueId"] = 90120001,
            ["GUID"] = "E19B20AA",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextOptions"] = {
                [1] = 901200011,
                [2] = 901200012,
                [3] = 901200013,
                [4] = 901200014,
                [5] = 901200015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90120002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90120002,
            ["GUID"] = "90120002.0",
            ["NextDialogue"] = 90120001,
            },
        [90120003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90120003,
            ["GUID"] = "90120003.0",
            },
        [90120101] = {
            ["Content"] = "咦？你不知道吗？粮秣专员就是负责填饱大家肚子的人哦，每天都要和各种食物打交道。",
            ["ContentJP"] = "ほや？知らないのですか？食糧補給官はみんなのお腹をいっぱいにする責任者！毎日いろ～んな食べ物を取り扱うのです！",
            ["DialogueId"] = 90120101,
            ["GUID"] = "E19B3112",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120103,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_1",
            },
        [90120103] = {
            ["Content"] = "比如我的话，就会去野外收集各种各样的食物，让榛子驮回城里，然后再去委托面包店的胡子叔叔做成吃的，分给大家。",
            ["ContentJP"] = "例えばね、お外で食料を集めて、ヘーゼルナッツに街まで運んでもらうとか！それをパン屋のヒゲおじさんに頼んで、おいしく食べられるようにしてもらって、みんなに分けてあげるって感じ！",
            ["DialogueId"] = 90120103,
            ["GUID"] = "E19B3166",
            ["NextDialogue"] = 90120104,
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_2",
            },
        [90120104] = {
            ["Content"] = "顺带一说，和那位胡子叔叔讨价还价，也是我的工作！哼哼。",
            ["ContentJP"] = "ちなみに、ヒゲおじさんと値段交渉するのも、私のお仕事なのです！えっへん~",
            ["DialogueId"] = 90120104,
            ["GUID"] = "E19B3190",
            ["NextDialogue"] = 90120105,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_3",
            },
        [90120105] = {
            ["Content"] = "哇！听起来很厉害，不过所有的粮秣专员的工作都是这样的吗？",
            ["ContentJP"] = "へえ、すごいね。他の食糧補給官もトリュフみたいな仕事をしているの？",
            ["DialogueId"] = 90120105,
            ["GUID"] = "E19B31BA",
            ["NextDialogue"] = 90120106,
            ["SpeakNpcId"] = 100001,
            },
        [90120106] = {
            ["Content"] = "那当然不是啦，其他的粮秣官好像都是一些脑子很好的家伙，写什么手续呀文书呀申请呀，然后就会有火车头拖着小山一样的吃的过来。",
            ["ContentJP"] = "そいつは違います。他の食糧補給官って頭の良さそうな人が多くて。申請やら手続きやらの書類をペペっと書きあげたかと思えば、汽車が山ほど食べ物を運んでくるの。",
            ["DialogueId"] = 90120106,
            ["GUID"] = "E19B31E4",
            ["NextDialogue"] = 90120107,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_4",
            },
        [90120107] = {
            ["Content"] = "不过，我住的镇子上人不是很多，有我和榛子就够啦！否则可能我就也得去学怎么写那些什么申请书之类的，唉，谁懂那些啊。",
            ["ContentJP"] = "でもでも、私の住んでる町は人が少ないし、私とヘーゼルナッツだけでいいんですって！さもなくば申請書やらの書き方を覚えなくちゃいけないかもで……んにゃぁ～そんなの覚えられないよ～……",
            ["DialogueId"] = 90120107,
            ["GUID"] = "E19B320E",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_01_5",
            ["bForbidSkipOptions"] = true,
            },
        [90120201] = {
            ["Content"] = "诶？会吧……没太想过，不过反正榛子撞飞的一定都是那些喜欢哇哇乱叫，打来打去的坏家伙！是他们活该！",
            ["ContentJP"] = "ふぇっ？それは痛いでしょうけど……あんまり気にしたことないや。だってヘーゼルが吹っ飛ばすのは喧嘩好きでギャーギャーうるさいヤツらばっかりだし！自業自得なのです！",
            ["DialogueId"] = 90120201,
            ["GUID"] = "E19B417A",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120203,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_1",
            },
        [90120203] = {
            ["Content"] = "这些家伙，打打杀杀后又会叫饿连天。有挥武器的劲头不如多垦一会儿地啦，这样才会有更多人吃饱。",
            ["ContentJP"] = "あいつら喧嘩した後いつもお腹すいた～って騒ぐんです。武器を振りまわす元気があるなら、畑を耕したらいいのに。そしたら、もっとたくさんの人がお腹いっぱいになれるのになぁ。",
            ["DialogueId"] = 90120203,
            ["GUID"] = "E19B41CE",
            ["NextDialogue"] = 90120204,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_2",
            },
        [90120204] = {
            ["Content"] = "所以你也很讨厌战争喽？",
            ["ContentJP"] = "だから戦争が嫌いなんだね？",
            ["DialogueId"] = 90120204,
            ["GUID"] = "E19B41F8",
            ["NextDialogue"] = 90120205,
            ["SpeakNpcId"] = 100001,
            },
        [90120205] = {
            ["Content"] = "那是当然！战斗是饥饿之母，是坏家伙！听说一旦遇到战争，那么大家都会饿肚子，非常讨厌！希望我不要遇上就是了。",
            ["ContentJP"] = "とーぜんっ！争いは飢餓の母、ワルモノです！戦争になるとみんなお腹ペコペコになっちゃうし。大っ嫌い！絶対に巻き込まれたくないよ。",
            ["DialogueId"] = 90120205,
            ["GUID"] = "E19B4222",
            ["NextDialogue"] = 90120206,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_3",
            },
        [90120206] = {
            ["Content"] = "真要遇到战争，就骑上榛子，撞飞开战的坏人。",
            ["ContentJP"] = "本当に戦争が起きたら、ヘーゼルナッツに乗って戦争を始めた悪人を吹き飛ばさないとね。",
            ["DialogueId"] = 90120206,
            ["GUID"] = "E19B424C",
            ["NextDialogue"] = 90120207,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85101:Confident_End",
                },
            },
        [90120207] = {
            ["Content"] = "没错，谁让人饿肚子，谁就迟早会被榛子撞飞！",
            ["ContentJP"] = "覚悟するべし悪人め！みんなのお腹を空かせるワルモノは、みーんなヘーゼルナッツが吹っ飛ばしちゃうんだから！",
            ["DialogueId"] = 90120207,
            ["GUID"] = "E19B4276",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90120301] = {
            ["Content"] = "是不少啦，不过其实不用特别为她准备吃的，她会自己找的。哪怕隔着几条小溪，榛子也能闻到熟透浆果的味道，然后驮着我飞奔过去，可能干啦。",
            ["ContentJP"] = "確かに少なくはないけど、特別にゴハンを用意する必要はないのです。だって自分で探せちゃいますから。ヘーゼルは、小川をいくつも越えた遠くからでも熟したベリーの匂いを嗅ぎつけて、私を乗せたまま駆けつけちゃうの。すごいでしょ？",
            ["DialogueId"] = 90120301,
            ["GUID"] = "E19B51E2",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120303,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_03_1",
            },
        [90120303] = {
            ["Content"] = "那还好，不用担心破产了。",
            ["ContentJP"] = "なら安心だね。おカネの心配はいらないかな。",
            ["DialogueId"] = 90120303,
            ["GUID"] = "E19B5236",
            ["NextDialogue"] = 90120304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85101:Talk02_End",
                },
            },
        [90120304] = {
            ["Content"] = "别担心别担心，榛子只会带来食物，不会吃垮这里的！所以，一定一定不要拿榛子开玩笑哦，她听到的话会伤心的，我也会。",
            ["ContentJP"] = "心配ご無用！ヘーゼルは食料を持ってくるだけ。ここを食い荒らしたりなんかしないよ！だからね、ぜーったいにからかわないであげて。あの子、傷つくから。私も。",
            ["DialogueId"] = 90120304,
            ["GUID"] = "E19B5260",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90120401] = {
            ["Content"] = "谢谢夸奖，不过我要纠正一下，这其实是裤子。一开始倒的确是裙子，白色的，长长的，可好看啦。是裁缝店的婆婆帮我改成了裤子。",
            ["ContentJP"] = "ありがとう！でもひとつ訂正すると、これ実はズボンなのです。最初は白くて長くてとっても綺麗なスカートだったんだけどね。裁縫屋のおばあちゃんにお願いしてズボンに変えてもらったんだ～",
            ["DialogueId"] = 90120401,
            ["GUID"] = "E19B624A",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120403,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_04_1",
            },
        [90120403] = {
            ["Content"] = "为什么呀？",
            ["ContentJP"] = "どうして？",
            ["DialogueId"] = 90120403,
            ["GUID"] = "E19B629E",
            ["NextDialogue"] = 90120404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85101:Explain01_End",
                },
            },
        [90120404] = {
            ["Content"] = "因为穿着裙子到处跑太不方便啦，有一次我跑得快了，都被裙摆绊倒，手里的面包都撒了。",
            ["ContentJP"] = "走りまわるのに不便でしょ？全力疾走した時にスカートに足が引っかかったことがあって、手に持ってたパンをぜ～んぶ台なしにしちゃって……",
            ["DialogueId"] = 90120404,
            ["GUID"] = "E19B62C8",
            ["NextDialogue"] = 90120405,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_04_2",
            },
        [90120405] = {
            ["Content"] = "所以，哎……要是哪天，没有人挨饿了，我就拜托婆婆再把这条裤子改回去！",
            ["ContentJP"] = "だから、そーだね……誰も食べ物に困らない日がいつか来たら、おばあちゃんに頼んで、またスカートに戻してもらうよ！",
            ["DialogueId"] = 90120405,
            ["GUID"] = "E19B62F2",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90120501] = {
            ["Content"] = "才不是发呆，是在冥想。不管怎么说我都是传颂会的一员，所以偶尔也会像这样用力想事情的。",
            ["ContentJP"] = "ぼんやりじゃありません、瞑想してるのです。私も礼賛会の一員だから、時々こうして頑張って考えてみたりしてます。",
            ["DialogueId"] = 90120501,
            ["GUID"] = "E19B72B2",
            ["LookAt"] = {
                [1] = "85101:n(0)",
                [2] = "0:n(85101)",
                },
            ["NextDialogue"] = 90120503,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_05_1",
            },
        [90120503] = {
            ["Content"] = "那在想什么呢？为什么没有吃饱饭之神？",
            ["ContentJP"] = "考えるって何を？みんなのお腹を満たしてくれる神様はどうしていないのか、とか？",
            ["DialogueId"] = 90120503,
            ["GUID"] = "E19B7306",
            ["NextDialogue"] = 90120504,
            ["SpeakNpcId"] = 100001,
            },
        [90120504] = {
            ["Content"] = "之前想过，不过修士们说，想这种事情是什么读……神？所以我就不想这些了。",
            ["ContentJP"] = "考えたことあります……でも修道士の人たちが言ってたんです。そういうことを考えること自体が神様へのぼ、ぼう……冒涜とかなんとか。だから、私はもうそのことについて考えてないよ。",
            ["DialogueId"] = 90120504,
            ["GUID"] = "E19B7330",
            ["NextDialogue"] = 90120505,
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_05_2",
            },
        [90120505] = {
            ["Content"] = "唉，修士们的话我总是听得半懂不懂的，比如他们总是说贪吃是非常非常严重的罪过……可是好像越是大吃大喝的人，地位就越高哦。",
            ["ContentJP"] = "ふあ～ぁ、あの人たちの話って私にはよくわからないの。いつも「暴食はとても重い罪だ」って言うけど……食いしん坊な人ほど偉い肩書きをもってたりするのになぁ。",
            ["DialogueId"] = 90120505,
            ["GUID"] = "E19B735A",
            ["NextOptions"] = {
                [1] = 90120002,
                [2] = 90120003,
                },
            ["SpeakNpcId"] = 85101,
            ["TalkActionId"] = {
                [1] = "85101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90120601] = {
            ["Content"] = "你在垃圾桶里翻到了发了芽的土豆？不要扔不要扔，我们把它种起来，松松土、浇浇水，就会有好多好多土豆可以吃啦！",
            ["ContentJP"] = "芽が生えたジャガイモをゴミ箱で見つけたのですか？ダメです、捨てちゃダメです！畑に植えて水をあげれば、ジャガイモがたくさん採れるから！",
            ["DialogueId"] = 90120601,
            ["GUID"] = "E19B831A",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_companio_01",
            },
        [90120701] = {
            ["Content"] = "一直忙着干活，不饿吗？要不要加入传颂会，我会喂饱你的！",
            ["ContentJP"] = "仕事が忙しくて、お腹が空いていませんか？礼賛会に入ったら、お腹いっぱいになりますよ！",
            ["DialogueId"] = 90120701,
            ["GUID"] = "E19B9382",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_companio_02",
            },
        [90120801] = {
            ["Content"] = "你好你好，我想请教一下……据说祈祷可以让人的灵魂感到满足，我觉得吃饭也可以，那么吃饭和祈祷哪个更管用呀？",
            ["ContentJP"] = "ハロハロ～、ちょっとお訊ねしますが……祈ることで魂が満たされるというけど、食べることでも満たされると思うのです。食べることと祈ること、どちらが効果的かな？",
            ["DialogueId"] = 90120801,
            ["GUID"] = "E19BA3EA",
            ["SpeakNpcId"] = 85101,
            ["VoiceName"] = "voice/$Locale$/char/Songlu/vo_companio_03",
            },
        [90130000] = {
            ["Content"] = "……还好，这个月的钱一分不少，还以为真的被兰迪那扣光了……嗯，这些寄回家里，剩下的生活费应该还够用。",
            ["ContentJP"] = "よかった、今月の稼ぎ減ってねぇな……ランディーの **が全部抜いたかと。まあ、この分は家に仕送りだな。残りは生活費に回して……足りるはず……",
            ["DialogueId"] = 90130000,
            ["GUID"] = "E1A18949",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_idle",
            },
        [90130001] = {
            ["Content"] = "有事快说，没有我就出任务去。",
            ["ContentJP"] = "用があるならサッサと言え。ないなら任務に向かうが。",
            ["DialogueId"] = 90130001,
            ["GUID"] = "E1A1894A",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextOptions"] = {
                [1] = 901300011,
                [2] = 901300012,
                [3] = 901300013,
                [4] = 901300014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90130002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90130002,
            ["GUID"] = "90130002.0",
            ["NextDialogue"] = 90130001,
            },
        [90130003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90130003,
            ["GUID"] = "90130003.0",
            },
        [90130101] = {
            ["Content"] = "西比尔长官？她是十三军团的军团长。",
            ["ContentJP"] = "シビル長官？アイツは第十三軍団の軍団長サマだが。",
            ["DialogueId"] = 90130101,
            ["GUID"] = "E1A199B2",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130103,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_01_1",
            },
        [90130103] = {
            ["Content"] = "还有什么？",
            ["ContentJP"] = "他には？",
            ["DialogueId"] = 90130103,
            ["GUID"] = "E1A199B3",
            ["NextDialogue"] = 90130104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83101:Talk03_End",
                },
            },
        [90130104] = {
            ["Content"] = "啧，我上哪知道那么多，她是上司，她下命令，我办事，就行了。",
            ["ContentJP"] = "チッ、アタシがアイツのこと詳しいと思ってんのか？あの女は上司であって、アタシは命令が来たらやる。ただそれだけだ。",
            ["DialogueId"] = 90130104,
            ["GUID"] = "E1A199B4",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90130201] = {
            ["Content"] = "经验？什么经验，我的经验就是没有拳头解决不了的问题，如果有，那就再来一拳。",
            ["ContentJP"] = "経験だぁ？アタシの経験から言わせてもらえば、拳で解決できない問題なんざねえってこった。できなかったら、もう1発殴れ。",
            ["DialogueId"] = 90130201,
            ["GUID"] = "E1A1AA1A",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130203,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_02_1",
            },
        [90130203] = {
            ["Content"] = "两拳也不行呢？",
            ["ContentJP"] = "2回殴ってもダメだったら？",
            ["DialogueId"] = 90130203,
            ["GUID"] = "E1A1AA6E",
            ["NextDialogue"] = 90130204,
            ["SpeakNpcId"] = 100001,
            },
        [90130204] = {
            ["Content"] = "那就再补上一枪。",
            ["ContentJP"] = "なら銃弾1発追加だ。",
            ["DialogueId"] = 90130204,
            ["GUID"] = "E1A1AA98",
            ["NextDialogue"] = 90130205,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_02_2",
            },
        [90130205] = {
            ["Content"] = "不是听说有人能中一枪也不死吗？",
            ["ContentJP"] = "1発ぐらいじゃ死なないって誰かが言っていたけど。",
            ["DialogueId"] = 90130205,
            ["GUID"] = "E1A1AAC2",
            ["NextDialogue"] = 90130206,
            ["SpeakNpcId"] = 100001,
            },
        [90130206] = {
            ["Content"] = "哎，我这就是打比方，只要拳头够硬枪够准，比什么都好使，你要是再抬杠，我先给你两拳。",
            ["ContentJP"] = "ったく、いまのはたとえだっての。まずは拳でガツンとやれば、そのあとの銃が効くんだよ。また揚げ足とったらガツンと2発たたき込んでやるからな。",
            ["DialogueId"] = 90130206,
            ["GUID"] = "E1A1AAEC",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90130301] = {
            ["Content"] = "前几天看到的那把枪真不错……算了，不能因为买它饿肚子，反正旧的用着更顺手些。",
            ["ContentJP"] = "この前いい感じの銃を見かけたんだが……いや、忘れてくれ。あれを買ったせいで腹が減ってりゃ意味もねえ。いつもの銃の方が使い慣れてるしな。",
            ["DialogueId"] = 90130301,
            ["GUID"] = "E1A1BA82",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130303,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_03_1",
            },
        [90130303] = {
            ["Content"] = "要我想办法送你一把吗？",
            ["ContentJP"] = "{性别:僕がどうにかしてプレゼントしようか？|私がどうにかしてプレゼントしようか？}",
            ["DialogueId"] = 90130303,
            ["GUID"] = "E1A1BAD6",
            ["NextDialogue"] = 90130304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83101:Think_End",
                },
            },
        [90130304] = {
            ["Content"] = "真的假……不对，你看着也不比我有钱……算了，我不怀疑你的好意，但你用不着破费，我不想欠无谓的人情。",
            ["ContentJP"] = "マジでか……あーいや、お前だってアタシより金持ちって立場でもねえだろうし……いや、好意は疑っちゃないが、無駄金を使う必要はねえよ。余計な貸し借りは作りたくねえしな。",
            ["DialogueId"] = 90130304,
            ["GUID"] = "E1A1BB00",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90130401] = {
            ["Content"] = "不工作就没饭吃，这个道理不懂吗？",
            ["ContentJP"] = "働かざる者食うべからず。この道理がわかんねえのか？",
            ["DialogueId"] = 90130401,
            ["GUID"] = "E1A1CAEA",
            ["LookAt"] = {
                [1] = "83101:n(0)",
                [2] = "0:n(83101)",
                },
            ["NextDialogue"] = 90130403,
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_04_1",
            },
        [90130403] = {
            ["Content"] = "但劳逸结合也是很重要的呀。",
            ["ContentJP"] = "だけど仕事と休養のバランスも大事だ{性别:ぞ|よ}。",
            ["DialogueId"] = 90130403,
            ["GUID"] = "E1A1CB3E",
            ["NextDialogue"] = 90130404,
            ["SpeakNpcId"] = 100001,
            },
        [90130404] = {
            ["Content"] = "我倒是想，但是那些雇主们可不这么想，隔三差五就问我委托做完没有，快点做之类，催催催，要不是我还有一家子人要养活，真想给他们来上几发。",
            ["ContentJP"] = "そりゃアタシだって休みたいさ。だけど、アタシに金払ってる連中には関係ねえんだ。暇さえありゃ「依頼は終わったか」だの「早く終わらせろ」だの、ケツ叩きにきやがってさ。養う家族さえいなけりゃ、連中に何発かお見舞いしてやんだがよ。",
            ["DialogueId"] = 90130404,
            ["GUID"] = "E1A1CB68",
            ["NextOptions"] = {
                [1] = 90130002,
                [2] = 90130003,
                },
            ["SpeakNpcId"] = 83101,
            ["TalkActionId"] = {
                [1] = "83101:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90130501] = {
            ["Content"] = "下次派任务能不能直说？唠唠叨叨的，烦死了。",
            ["ContentJP"] = "次からは任務内容だけを説明してくれ。くどくど言われても、ウゼえだけなんだ。",
            ["DialogueId"] = 90130501,
            ["GUID"] = "E1A1DB52",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_companio_01",
            },
        [90130601] = {
            ["Content"] = "……长官好。",
            ["ContentJP"] = "こんにちは……長官殿。",
            ["DialogueId"] = 90130601,
            ["GUID"] = "E1A1EBBA",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_companio_02",
            },
        [90130701] = {
            ["Content"] = "你是优秀的士兵，仅此一句。哦，还有……好好工作之余，也得好好生活……啧，听完了还不快走？",
            ["ContentJP"] = "お前は優秀な兵士、そのひと言に尽きる。ああ、それと……働きまくるのはいいが、仕事以外の生活も充実させて……チッ、話はこれでおしまいだ。さっさと行けよ。",
            ["DialogueId"] = 90130701,
            ["GUID"] = "E1A1FC22",
            ["SpeakNpcId"] = 83101,
            ["VoiceName"] = "voice/$Locale$/char/Linen/vo_companio_03",
            },
        [90150000] = {
            ["Content"] = "我的小小的、小小的家……藏在树梢的新绿里，藏在金色的河流间……温暖的壁炉呀，小火苗噼啪噼啪……握着爸爸刚修好的锡兵，听妈妈唱起摇篮曲……睡吧……",
            ["ContentJP"] = "～～♪ ちいちゃなちいさな私の家、金の小川のそば。暖炉はぱちぱち暖かで、パパが作ったブリキの人形、ママが歌う子守歌。さあみんなでおやすみ。",
            ["DialogueId"] = 90150000,
            ["GUID"] = "E1AE5A8B",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_idle",
            },
        [90150001] = {
            ["Content"] = "……唔……是你。你好，你好呀。",
            ["ContentJP"] = "……あっ……あなたは。こんにちは、どうも。",
            ["DialogueId"] = 90150001,
            ["GUID"] = "E1AE5A8A",
            ["NextOptions"] = {
                [1] = 901500011,
                [2] = 901500012,
                [3] = 901500013,
                [4] = 901500014,
                [5] = 901500015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90150002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90150002,
            ["GUID"] = "90150002.0",
            ["NextDialogue"] = 90150001,
            },
        [90150003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90150003,
            ["GUID"] = "90150003.0",
            },
        [90150101] = {
            ["Content"] = "唔，我想吃掉可以让人变得很大很大的糖果……",
            ["ContentJP"] = "えっとね、背が伸びるキャンディーがあったらなって考えてたの。もしあるなら食べてみたいなあって……",
            ["DialogueId"] = 90150101,
            ["GUID"] = "E1AE6AF2",
            ["NextDialogue"] = 90150103,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_01_1",
            },
        [90150103] = {
            ["Content"] = "吃下那样的糖果，我就会长得比云还高，可以摸一摸天上的星星了吧？",
            ["ContentJP"] = "そしたら雲よりも背が高くなって、お空に浮かぶお星さまを、なでてあげられるでしょう？",
            ["DialogueId"] = 90150103,
            ["GUID"] = "E1AE6B46",
            ["NextDialogue"] = 90150104,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_01_2",
            },
        [90150104] = {
            ["Content"] = "会不会一不留神一脚把我踩扁了……",
            ["ContentJP"] = "{性别:うっかり僕のことを踏み潰して、ぺっちゃんこに……？|うっかり私のことを踏み潰して、ぺっちゃんこに……？}",
            ["DialogueId"] = 90150104,
            ["GUID"] = "E1AE6B70",
            ["NextDialogue"] = 90150105,
            ["SpeakNpcId"] = 100001,
            },
        [90150105] = {
            ["Content"] = "不会的，我会很小心的！嗯……如果你实在害怕的话，就坐在我的手心里，我带你出去兜风，怎么样？",
            ["ContentJP"] = "そ、そんなことしないわ！気をつけるもの！でも……本当に心配なら、私の手の平に座るのはどうかしら？そうやって一緒にお散歩するの、素敵じゃないかな？",
            ["DialogueId"] = 90150105,
            ["GUID"] = "E1AE6B9A",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_01_3",
            ["bForbidSkipOptions"] = true,
            },
        [90150201] = {
            ["Content"] = "我有一个很大很大的玻璃盒子，盒子里面装着窗户外软绵绵的雪，装着雪一样白白的棉花糖。我还想装进去棉花糖一样轻飘飘的云朵，云朵一样暖乎乎的风……",
            ["ContentJP"] = "フィーナね、とっても大きなガラスの箱を持っているの。なかにはフワフワな白い雪……雪みたいに白いマシュマロが入っているわ。マシュマロみたいにフカフカな雲と、雲みたいに暖かい風をそこに入れたいの……",
            ["DialogueId"] = 90150201,
            ["GUID"] = "E1AE7B5A",
            ["NextDialogue"] = 90150203,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_1",
            },
        [90150203] = {
            ["Content"] = "连同你们的笑声一起，全～都装进盒子。",
            ["ContentJP"] = "みんなの笑顔も一緒に、ぜ～んぶ、箱の中に入れたいな。",
            ["DialogueId"] = 90150203,
            ["GUID"] = "E1AE7BAE",
            ["NextDialogue"] = 90150204,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_2",
            },
        [90150204] = {
            ["Content"] = "真好啊，想钻进去。",
            ["ContentJP"] = "いいね、入ってみたい。",
            ["DialogueId"] = 90150204,
            ["GUID"] = "E1AE7BD8",
            ["NextDialogue"] = 90150205,
            ["SpeakNpcId"] = 100001,
            },
        [90150205] = {
            ["Content"] = "嗯……如果你能吃下让人变得很小很小的糖果，就可以进去玩啦。不过，这个盒子里到处都是白色的，你要小心，别在里面迷路哦。",
            ["ContentJP"] = "うん、小さくなれるキャンディーを食べれば、なかに入って遊べるわ。でも……箱の中はどっちを向いても真っ白だから、迷子にならないように気をつけないと。",
            ["DialogueId"] = 90150205,
            ["GUID"] = "E1AE7C02",
            ["NextDialogue"] = 90150206,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_3",
            },
        [90150206] = {
            ["Content"] = "如果我迷路了，菲娜会来救我吗？",
            ["ContentJP"] = "もし迷子になったら、フィーナは助けに来てくれる？",
            ["DialogueId"] = 90150206,
            ["GUID"] = "E1AE7C2C",
            ["NextDialogue"] = 90150207,
            ["SpeakNpcId"] = 100001,
            },
        [90150207] = {
            ["Content"] = "让我想想……如果你迷路了，菲娜就把面包掰成一小块一小块，连成一条路……这样，你只要沿着面包屑向前走，就能找到出口啦！",
            ["ContentJP"] = "{性别:えっと、お兄さんが迷子になってしまったら……そしたらフィーナが、パンを小さくちぎって落としながら探しにいくわ！パンの欠片が道になって、たどっていけば出口が見つけられるはず！|えっと、お姉さんが迷子になってしまったら……そしたらフィーナが、パンを小さくちぎって落としながら探しにいくわ！パンの欠片が道になって、たどっていけば出口が見つけられるはず！}",
            ["DialogueId"] = 90150207,
            ["GUID"] = "E1AE7C56",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90150301] = {
            ["Content"] = "嗯……！在梦里，我看到了一只纯白羽毛的夜莺，它一会儿落在我的手上，一会儿绕着屋子和我捉迷藏……唔……到底是我梦见了它，还是它梦见了我呢……",
            ["ContentJP"] = "うん……！夢の中で真っ白なナイチンゲールを見たわ。私のね、手に止まったり、部屋のなかでかくれんぼもしたの……うーん……でも夢を見ていたのはフィーナ？それとも、ナイチンゲールがフィーナの夢を見ていたのかしら……？",
            ["DialogueId"] = 90150301,
            ["GUID"] = "E1AE8BC2",
            ["NextDialogue"] = 90150303,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_03_1",
            },
        [90150303] = {
            ["Content"] = "也许是你们做了同一个梦呢？",
            ["ContentJP"] = "フィーナもナイチンゲールも、同じ夢を見たのかな？",
            ["DialogueId"] = 90150303,
            ["GUID"] = "E1AE8C16",
            ["NextDialogue"] = 90150304,
            ["SpeakNpcId"] = 100001,
            },
        [90150304] = {
            ["Content"] = "你说得对！也许那是一个仙境，所有睡着的孩子和小动物都可以在那里一起玩。嗯……下次的梦里会遇到谁呢？猫头鹰爷爷、金丝雀小姐，还是白兔先生？",
            ["ContentJP"] = "きっとそうだわ！あそこはワンダーランドだったのよ！眠っている子供、小さな動物のお友達、みんなで一緒に遊べる素敵な場所。ああ……次の夢では誰に出会えるのかしら？フクロウのおじいさん？カナリアのお嬢さん？それとも白ウサギさん？",
            ["DialogueId"] = 90150304,
            ["GUID"] = "E1AE8C40",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90150401] = {
            ["Content"] = "菲娜曾经有一个妈妈，两个爸爸。不过，他们都不在了……",
            ["ContentJP"] = "フィーナにはお母さんと、ふたりのお父さんがいたの。でもみんな、もういなくなっちゃった……",
            ["DialogueId"] = 90150401,
            ["GUID"] = "E1AE9C2A",
            ["NextDialogue"] = 90150402,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_04_1",
            },
        [90150402] = {
            ["Content"] = "第一个爸爸，和妈妈一起，去了很远很远的国度。第二个爸爸，也去了很远很远的国度……是我带他去的哦。",
            ["ContentJP"] = "最初のお父さんは、お母さんと一緒に遠い遠い国へと行ったわ。2番目のお父さんも、遠い遠い国に行っちゃった……フィーナが連れていったのだけど。",
            ["DialogueId"] = 90150402,
            ["GUID"] = "E1AE9C54",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90150501] = {
            ["Content"] = "他是最伟大的魔法师，是说话最好听的人，是全世界最温柔最温柔的人……",
            ["ContentJP"] = "アウトサイダーはね、世界で一番偉大な魔法使い。一番心地よい言葉を話す、世界で一番優しい人……",
            ["DialogueId"] = 90150501,
            ["GUID"] = "E1AEAC92",
            ["NextDialogue"] = 90150503,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_05_1",
            },
        [90150503] = {
            ["Content"] = "？",
            ["ContentJP"] = "……？",
            ["DialogueId"] = 90150503,
            ["GUID"] = "E1AEACE6",
            ["NextDialogue"] = 90150504,
            ["SpeakNpcId"] = 100001,
            },
        [90150504] = {
            ["Content"] = "唔，你看起来有很多很多问题，我哪里说的不对吗？",
            ["ContentJP"] = "あれ、ハテナが頭に浮かんでいるみたいだけど、フィーナ、何か間違っているの？",
            ["DialogueId"] = 90150504,
            ["GUID"] = "E1AEAD10",
            ["NextDialogue"] = 90150505,
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_05_2",
            },
        [90150505] = {
            ["Content"] = "和我认识的奥特赛德完全是两个人吧！",
            ["ContentJP"] = "{性别:少なくとも僕の知っているアウトサイダーとは別人だ。|少なくとも私の知っているアウトサイダーとは別人ね。}",
            ["DialogueId"] = 90150505,
            ["GUID"] = "E1AEAD3A",
            ["NextDialogue"] = 90150506,
            ["SpeakNpcId"] = 100001,
            },
        [90150506] = {
            ["Content"] = "咦……？他对你说话不好听、不温柔吗？真对不起……我会敲敲他的脑袋，要他改正的！",
            ["ContentJP"] = "{性别:え……じゃあアウトサイダーってお兄さんに優しくないの？本当にごめんなさい、私がデコピンして、態度を改めてもらうわ！|じゃあアウトサイダーってお姉さんに優しくないの？本当にごめんなさい、私がデコピンして、態度を改めてもらうわ！}",
            ["DialogueId"] = 90150506,
            ["GUID"] = "E1AEAD64",
            ["NextOptions"] = {
                [1] = 90150002,
                [2] = 90150003,
                },
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90150601] = {
            ["Content"] = "答应菲娜，再也再也再也……不要去那些有很多很多坏巫师的危险地方了，好吗？",
            ["ContentJP"] = "約束して。もう絶対に、絶対に絶対に……悪い呪い師がたくさんいる危険な場所には行かないで。いい？",
            ["DialogueId"] = 90150601,
            ["GUID"] = "E1AEBCFA",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_companio_01",
            },
        [90150701] = {
            ["Content"] = "那是什么？仓鼠小姐饲养的精灵吗？不可思议……它一定可以载着你飞过所有城堡的围墙！",
            ["ContentJP"] = "それは……何？ハムスターのお姉さんが飼っている妖精？不思議……きっとお姉さんを乗せて、どんなお城の壁でも飛び越えてしまうのね？",
            ["DialogueId"] = 90150701,
            ["GUID"] = "E1AECD62",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_companio_02",
            },
        [90150801] = {
            ["Content"] = "狮子小姐，你想要唤醒沉睡在巨剑中的仙女吗？也许你需要吟诵很多很多咒语，比如——“唤醒圣剑萨麦尔之人啊，必将成为艾利西安之王！”",
            ["ContentJP"] = "ライオンのお姉さんは大剣の中に眠っている女神様を呼び覚ましたいのね？多分だけど、呪文をいっぱい唱えないといけないのかも。例えばーー「この聖剣サマエルを覚醒させし者は、エリュシオンの王となるであろう！」とか！",
            ["DialogueId"] = 90150801,
            ["GUID"] = "E1AEDDCA",
            ["SpeakNpcId"] = 81801,
            ["VoiceName"] = "voice/$Locale$/char/Feina/vo_companio_03",
            },
        [90160000] = {
            ["Content"] = "现在这种安心的感觉也不错，甚至让我在过了那么多年后，还能对一个地方产生一丝归属感。",
            ["ContentJP"] = "今のこの安心感も悪くない。何年も経ってやっと、ここに少しだけ居場所を感じられた。",
            ["DialogueId"] = 90160000,
            ["GUID"] = "E1B4C329",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_idle",
            },
        [90160001] = {
            ["Content"] = "你可来了，我把之前剩的杂活清了一下，钱没赚多少还差点把自己累死，唉，为了这个家我真是付出了太多啊。",
            ["ContentJP"] = "やっと来たか、残ってた用事は片付けといた。たいした稼ぎにもならないってのに、疲れて死にそうだ。あーあ、この家のために俺、必死だな。",
            ["DialogueId"] = 90160001,
            ["GUID"] = "E1B4C32A",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextOptions"] = {
                [1] = 901600011,
                [2] = 901600012,
                [3] = 901600013,
                [4] = 901600014,
                [5] = 901600015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90160002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90160002,
            ["GUID"] = "90160002.0",
            ["NextDialogue"] = 90160001,
            },
        [90160003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90160003,
            ["GUID"] = "90160003.0",
            },
        [90160101] = {
            ["Content"] = "手册？没有，干这行的可大部分没看书的耐性，但是口诀倒是不少，比如我自创的打人口诀：“两下腰子一下头，皇帝看了说没救”。",
            ["ContentJP"] = "マニュアルだぁ？あるわけないだろ？こんな仕事してる連中に本を読む根気があると思ってんのか？\
といっても、格言はいろいろあるがね。たとえば「体に2発入れた後に頭をぶん殴れ。そしたらどんな相手だってイチコロだ」、ってオレが考えた喧嘩のコツだけどな。",
            ["DialogueId"] = 90160101,
            ["GUID"] = "E1B4D392",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160103,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_01_1",
            },
        [90160103] = {
            ["Content"] = "有意思，再来上几句？",
            ["ContentJP"] = "{性别:なんだかおもしろそう。他にはどんなのがあるんだ？|なんだかおもしろそう。他にはどんなのがあるの？}",
            ["DialogueId"] = 90160103,
            ["GUID"] = "E1B4D3E6",
            ["NextDialogue"] = 90160104,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Confident_Start",
                },
            },
        [90160104] = {
            ["Content"] = "别贪多，饭一口一口吃，干这行的，最大的敌人永远是贪婪，有时候来自别人，但更多时候来自自己。",
            ["ContentJP"] = "おーおーがっつくなって、美味いもんは一口ずつ噛みしめろよ。強欲がこの仕事の天敵なんだぜ？欲深さってやつは、他人からもらうより、たいがいは自分の心から生まれるもんだ。",
            ["DialogueId"] = 90160104,
            ["GUID"] = "E1B4D410",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_01_2",
            ["bForbidSkipOptions"] = true,
            },
        [90160201] = {
            ["Content"] = "他们是一团未熄灭的野火，稍不留神就会烧成满山烈焰。为你个人考虑，还是少与他们接触为好……",
            ["ContentJP"] = "あいつらは消えない野焼きの火さ。油断してると山ごと燃やされちまう。お前のために言っとくが、あんまりヤツらと関わるなよ……",
            ["DialogueId"] = 90160201,
            ["GUID"] = "E1B4E3FA",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160203,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_02_1",
            },
        [90160203] = {
            ["Content"] = "这么严肃，为什么？",
            ["ContentJP"] = "いつになく真剣だね……どうして？",
            ["DialogueId"] = 90160203,
            ["GUID"] = "E1B4E44E",
            ["NextDialogue"] = 90160204,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Talk03_End",
                },
            },
        [90160204] = {
            ["Content"] = "那当然是因为……有过一些小过节，要是哪天你和他们打上交道，可千万记得别报我名字。",
            ["ContentJP"] = "そりゃあれだ……何度かトラブったことがあるからな。この先あいつらと関わることがあったとしても、絶対に俺の名前は出すんじゃないぞ。",
            ["DialogueId"] = 90160204,
            ["GUID"] = "E1B4E478",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90160301] = {
            ["Content"] = "嗯，能帮我拿一下那边的纱布吗？可不能被菲娜发现，不然她又要唠叨了。",
            ["ContentJP"] = "まあちょいとな。そっちのガーゼを取ってくれないか？フィーナにバレたら、また口酸っぱく言われちまうからよ。",
            ["DialogueId"] = 90160301,
            ["GUID"] = "E1B4F462",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160303,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_03_1",
            },
        [90160303] = {
            ["Content"] = "她那是在关心你。",
            ["ContentJP"] = "{性别:/フィーナはアウトサイダーのことが心配なんだよ。|フィーナはアウトサイダーのことが心配なのよ。}",
            ["DialogueId"] = 90160303,
            ["GUID"] = "E1B4F4B6",
            ["NextDialogue"] = 90160304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Explain02_End",
                },
            },
        [90160304] = {
            ["Content"] = "我知道，但干咱们这一行总免不了受点伤，我也不想让她一直担心嘛。她要是真的问起来，你记得帮我打个圆场啊，回头请你吃饭。",
            ["ContentJP"] = "わかっちゃいるんだけどさ、怪我なんざ仕事柄日常茶飯事だろ？あまり心配かけたくないんだよ。フィーナに聞かれたら誤魔化してくれって、な、今度、飯でも奢るから。",
            ["DialogueId"] = 90160304,
            ["GUID"] = "E1B4F4E0",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90160401] = {
            ["Content"] = "噢，你要不要也试试这些小家伙？别看它们长得丑，去掉头就跟小饼干一样脆脆的，甚至能在嘴巴里留下一丝肉类的回甘……",
            ["ContentJP"] = "お、食ってみないか？見た目はアレだけど、頭さえとっちまえば、クッキーみたいにサクサクだぞ。なんかちょっとだけ肉っぽい味もするし……",
            ["DialogueId"] = 90160401,
            ["GUID"] = "E1B504CA",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160403,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Give",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_04_1",
            },
        [90160403] = {
            ["Content"] = "（转身逃跑。）",
            ["ContentJP"] = "（身を翻して逃げ出す）",
            ["DialogueId"] = 90160403,
            ["GUID"] = "E1B5051E",
            ["NextDialogue"] = 90160404,
            ["SpeakNpcId"] = 100001,
            },
        [90160404] = {
            ["Content"] = "你别跑啊，这可是很有用的生存智慧……等你迷失在野外，干粮吃完的时候，它们就是最宝贵的能量来源。",
            ["ContentJP"] = "逃げるなって。役立つサバイバルの知恵だってのに……荒野で迷って食料がなくなったら、こいつらは大切なエネルギー源だぞ。",
            ["DialogueId"] = 90160404,
            ["GUID"] = "E1B50548",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        }
  end },
  { MinKey = 90160501, MaxKey = 90220301, Loader = function()
      return {
        [90160501] = {
            ["Content"] = "嗯……等等，你手上怎么才这么几个钱，是不是又把你那份报酬随便分给其他人了？",
            ["ContentJP"] = "だな……っておい、どうしてこれっぽっちしか持ってないんだ。まさかまた自分の報酬を他人にやったのか？",
            ["DialogueId"] = 90160501,
            ["GUID"] = "E1B51532",
            ["LookAt"] = {
                [1] = "85102:n(0)",
                [2] = "0:n(85102)",
                },
            ["NextDialogue"] = 90160503,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_1",
            },
        [90160503] = {
            ["Content"] = "他们比我更需要那些钱。",
            ["ContentJP"] = "{性别:あの人たちの方が僕よりおカネが必要みたいだったから。|あの人たちの方が私よりおカネが必要みたいだったから。}",
            ["DialogueId"] = 90160503,
            ["GUID"] = "E1B51586",
            ["NextDialogue"] = 90160504,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "85102:Confident_End",
                },
            },
        [90160504] = {
            ["Content"] = "你……哎，算了，这大概就是你的优点吧。手头紧的时候记得跟我说。",
            ["ContentJP"] = "お前ってやつは……はぁ……まあいい、これもお前の長所だろうしな。カネに困ったら俺に言えよ。",
            ["DialogueId"] = 90160504,
            ["GUID"] = "E1B515B0",
            ["NextDialogue"] = 90160505,
            ["SpeakNpcId"] = 85102,
            ["TalkActionId"] = {
                [1] = "85102:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_2",
            },
        [90160505] = {
            ["Content"] = "好，那我现在手头紧了！",
            ["ContentJP"] = "じゃあ、いま、おカネに困ってます！",
            ["DialogueId"] = 90160505,
            ["GUID"] = "E1B515DA",
            ["NextDialogue"] = 90160506,
            ["SpeakNpcId"] = 100001,
            },
        [90160506] = {
            ["Content"] = "……我这是身为朋友在关心你，你别得寸进尺耍无赖啊！",
            ["ContentJP"] = "……友人としてお前のことを心配してんだぞ！何を図々しく調子に乗ってんだ",
            ["DialogueId"] = 90160506,
            ["GUID"] = "E1B51604",
            ["NextOptions"] = {
                [1] = 90160002,
                [2] = 90160003,
                },
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90160601] = {
            ["Content"] = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
            ["DialogueId"] = 90160601,
            ["GUID"] = "E1B5259A",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_01",
            },
        [90160701] = {
            ["Content"] = "你是跟{nickname}关系很好的那个女孩子吧……听说你身体不太好，就坐下好好休息一会儿吧。",
            ["ContentJP"] = "おっ、あいつと仲のいい嬢ちゃんじゃないか……体がそんなに強くないって聞いたぜ？座って楽にしてくれよ。",
            ["DialogueId"] = 90160701,
            ["GUID"] = "E1B53602",
            ["NextDialogue"] = 90160702,
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_02_1",
            },
        [90160702] = {
            ["Content"] = "不用跟我客气，我家里也有个体弱多病的妹妹，早就习惯照顾人了……要是饿了、渴了，尽管跟我说，{nickname}的朋友就是我的朋友。",
            ["ContentJP"] = "遠慮なんてすんなよ。病弱な妹と暮らしてるからな、世話焼きには慣れてんのさ……もし腹が減ったり喉が渇いたりしたらなんでも言ってくれ。あいつの友達ってことは、俺の友達でもあるんだぞ？",
            ["DialogueId"] = 90160702,
            ["GUID"] = "E1B5362C",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_02_2",
            },
        [90160801] = {
            ["Content"] = "哟，老板娘，你怎么也在这儿……难不成是有什么紧急的委托？{nickname}这段时间已经累坏了，暂时就让我们歇歇吧……",
            ["ContentJP"] = "よぉ女将さんじゃないか。なんであんたがここに……なんか緊急の依頼か？あいつはこの間の疲れが残ってんだ、少しは休ませてくれよ……",
            ["DialogueId"] = 90160801,
            ["GUID"] = "E1B5466A",
            ["NextDialogue"] = 90160802,
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_03_1",
            },
        [90160802] = {
            ["Content"] = "噢，不过，如果报酬够高的话，还是说来听听吧。",
            ["ContentJP"] = "あ、だが報酬の割がいいってんなら話は別だ。まずは話を聞かせてくれ",
            ["DialogueId"] = 90160802,
            ["GUID"] = "E1B54694",
            ["SpeakNpcId"] = 85102,
            ["VoiceName"] = "voice/$Locale$/char/Aote/vo_companio_03_2",
            },
        [90170000] = {
            ["Content"] = "嗯~天气不错，正适合去采一些花，熏得身上香香的！{nickname}，想一起出门逛逛吗？",
            ["ContentJP"] = "んん～天気いいねぇ。花を摘んだりするのにはピッタリな日和！体もいい香りになるしね！ねえねえ、{nickname}、一緒にお出かけでもしない？",
            ["DialogueId"] = 90170000,
            ["GUID"] = "E1BB2BC9",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_idle",
            },
        [90170001] = {
            ["Content"] = "我来的时候顺手把你家门口的雪给铲了！是不是特别感动，特别想请我喝一杯热可可呀~",
            ["ContentJP"] = "ここに来たついでに君ん家の前を雪かきしといてあげたよ！これにはもう、スーパー感謝でしょ？私にあったかココアをご馳走したくなったりした？",
            ["DialogueId"] = 90170001,
            ["GUID"] = "E1BB2BCA",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextOptions"] = {
                [1] = 901700011,
                [2] = 901700012,
                [3] = 901700013,
                [4] = 901700014,
                [5] = 901700015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90170002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90170002,
            ["GUID"] = "90170002.0",
            ["NextDialogue"] = 90170001,
            },
        [90170003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90170003,
            ["GUID"] = "90170003.0",
            },
        [90170101] = {
            ["Content"] = "嗯……大概是为那些被舍弃的物品找到合适的主人的营生，唔，也能让那些遭受物资匮乏之苦的人，得到更好的生活。",
            ["ContentJP"] = "んーっとね……ポイされた子たちに次のご主人様を見つけてあげる仕事かな。あと物資不足で困ってる人たちの生活を、少しはマシにしてあげられるよ。",
            ["DialogueId"] = 90170101,
            ["GUID"] = "E1BB3C32",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170103,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_01_1",
            },
        [90170103] = {
            ["Content"] = "具体要怎么做？",
            ["ContentJP"] = "具体的にどんなことをしているの？",
            ["DialogueId"] = 90170103,
            ["GUID"] = "E1BB3C86",
            ["NextDialogue"] = 90170104,
            ["SpeakNpcId"] = 100001,
            },
        [90170104] = {
            ["Content"] = "比如，把贵族老爷淘汰下来的丝绒窗帘换成冬衣，让老人们暖暖过冬；把被丢弃的玩偶小人带给那些只能抛石头玩的孩子，他们能高兴很久。",
            ["ContentJP"] = "例えば、貴族のおじさまが手放したベルベットのカーテンを冬服に仕立てれば、お年寄りが暖かく過ごせるし。捨てられちゃった人形は、石とかでしか遊べない子供たちに渡すとハッピーにできるね。",
            ["DialogueId"] = 90170104,
            ["GUID"] = "E1BB3CB0",
            ["NextDialogue"] = 90170105,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_01_2",
            },
        [90170105] = {
            ["Content"] = "还有一次，我把不知道哪家丢掉的破烂书架搬了回来，累得半死，但没过多久，就有一群猫妈妈猫小孩过来上蹿下跳，从太阳上山玩到月亮落山。",
            ["ContentJP"] = "誰が捨てたかもわかんないボロい本棚を運んでさ、へばって休んでたんだ。そしたらさ、猫のお母さんが子猫を連れてきてね？その子たち本棚に飛び乗ったり、飛び降りたり、月が沈んで太陽が昇るまでずーっと遊んでたよ。",
            ["DialogueId"] = 90170105,
            ["GUID"] = "E1BB3CDA",
            ["NextDialogue"] = 90170106,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_01_3",
            },
        [90170106] = {
            ["Content"] = "拾荒者的工作就是这样啦！大多是一些鸡毛蒜皮的小事，但永远不会无聊，怎么样，想不想加入我们！",
            ["ContentJP"] = "ゴミ拾いの仕事ってそんな感じ！こまごました仕事ばかりだけどさ、絶対に退屈はしない！どうよどうよ？君も私たちのフォロワーになっちゃう？",
            ["DialogueId"] = 90170106,
            ["GUID"] = "E1BB3D04",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90170201] = {
            ["Content"] = "嘘嘘嘘，这可是拾荒者的最高机密！要不是你帮我抓过贼，才不会轻易透露给你呢！",
            ["ContentJP"] = "おぉぉう、声が大きい！これはゴミ拾いにとってのトップシークレットでありますから……泥棒を捕まえてくれた君にだけ、特別に教えてあげる。",
            ["DialogueId"] = 90170201,
            ["GUID"] = "E1BB4C9A",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170203,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_02_1",
            },
        [90170203] = {
            ["Content"] = "这张图标明了冰湖城所有垃圾桶的位置，我在上面标了好东西最多的几个，不仅把那边的垃圾桶换成了大号，就连什么时候去进货都经过我严密的计算！",
            ["ContentJP"] = "ま、よーするにアイスレイク城のゴミ箱マップなんだけど。上物が拾える場所にマーク付けといたから。それに、そこのゴミ箱を大きいサイズに変えたりとか、「入荷」はいつになるかとかも計算してあるのだーー！",
            ["DialogueId"] = 90170203,
            ["GUID"] = "E1BB4CEE",
            ["NextDialogue"] = 90170204,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Give",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_02_2",
            },
        [90170204] = {
            ["Content"] = "不过我们这行旱涝不保收，能有多少进账，大部分时候还得靠运气……",
            ["ContentJP"] = "まあこの業界は大豊作が毎回起きるわけじゃないから。どれぐらいゲットできるかは、結局運任せになっちゃうんだけどね……",
            ["DialogueId"] = 90170204,
            ["GUID"] = "E1BB4D18",
            ["NextDialogue"] = 90170205,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_02_3",
            },
        [90170205] = {
            ["Content"] = "捡垃圾也真不容易……",
            ["ContentJP"] = "ゴミ拾いも大変なんだね……",
            ["DialogueId"] = 90170205,
            ["GUID"] = "E1BB4D42",
            ["NextDialogue"] = 90170206,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Sigh_End",
                },
            },
        [90170206] = {
            ["Content"] = "可不是嘛，嘿，我就说你是个明眼人！",
            ["ContentJP"] = "ザッツライト！その通り！いやぁ、やっぱ君は分かってくれる人だね！",
            ["DialogueId"] = 90170206,
            ["GUID"] = "E1BB4D6C",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90170301] = {
            ["Content"] = "不，你说反啦！我非常喜欢冰湖城。只是我常常回想起和爸爸一起在雪原上流浪的日子，我的整个童年都是在那里度过的。",
            ["ContentJP"] = "ノーノー、私はアイスレイク城が大好きだよ！雪原を見て思い出してるだけ。お父さんと一緒にさまよい歩いた日々とかさ、雪原で子供時代を過ごしてたから。",
            ["DialogueId"] = 90170301,
            ["GUID"] = "E1BB5D02",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170303,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_03_1",
            },
        [90170303] = {
            ["Content"] = "你怎么看待那些时光呢？",
            ["ContentJP"] = "そんな風に過ごした時間をどう思う？",
            ["DialogueId"] = 90170303,
            ["GUID"] = "E1BB5D56",
            ["NextDialogue"] = 90170304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Agree",
                },
            },
        [90170304] = {
            ["Content"] = "从这里看向雪原，美得像童话里的冰国雪国。可一步一步走进去，又会觉得自己好小好小。在齐膝的雪地里迈着腿，不管走了多久，看到的景色都不会改变。",
            ["ContentJP"] = "ここから眺める雪原は、メルヘンストーリーに出てくる雪の国みたいにきれいだよね。でもさ……一歩、また一歩と踏み込むと、ほんと自分がちっぽけに感じるんだよ。膝まで積もった雪の中を歩けど歩けど景色はずっと変わらないまま。",
            ["DialogueId"] = 90170304,
            ["GUID"] = "E1BB5D80",
            ["NextDialogue"] = 90170305,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_03_2",
            },
        [90170305] = {
            ["Content"] = "我不讨厌那段时光，但我最喜欢的，果然还是热热闹闹，充满烟火味的冰湖城！",
            ["ContentJP"] = "あの頃も嫌いじゃないけど、でもやっぱり私は、賑やかでいい感じに栄えてるアイスレイク城が大好きなんだ！",
            ["DialogueId"] = 90170305,
            ["GUID"] = "E1BB5DAA",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90170401] = {
            ["Content"] = "是小时候和我在雪原上一起流浪的大猫！它叫“胖尾巴”，平时得用肉干贿赂才愿意给我摸摸，但那个手感——嘿嘿嘿嘿，一个字，绝啦！",
            ["ContentJP"] = "子供の頃、一緒に雪原をさまよい歩いてくれた猫ちゃんだよ。名前は「まんまるニャーゴ」！干し肉をあげないとなでさせてくれないんだけど。あの手触りったら——んぬふふふふぅ、頭がオーバーロードしちゃうね！",
            ["DialogueId"] = 90170401,
            ["GUID"] = "E1BB6D6A",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170403,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_04_1",
            },
        [90170403] = {
            ["Content"] = "雪原大猫怎么叫？像猫还是像老虎？",
            ["ContentJP"] = "雪原の猫ってどんな風に鳴くのかな？虎っぽいかんじ？",
            ["DialogueId"] = 90170403,
            ["GUID"] = "E1BB6DBE",
            ["NextDialogue"] = 90170404,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Explain02_End",
                },
            },
        [90170404] = {
            ["Content"] = "嗯……反正不是喵喵喵，大概是，嗷呜——嗷呜——嗷呜——的声音！",
            ["ContentJP"] = "うーんと……ニャーニャーじゃないね。……ガォ、ガゥ、ガォオン！って感じ！",
            ["DialogueId"] = 90170404,
            ["GUID"] = "E1BB6DE8",
            ["NextDialogue"] = 90170405,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_04_2",
            },
        [90170405] = {
            ["Content"] = "现在还能见到它吗？",
            ["ContentJP"] = "いまでも会ったりしてるの？",
            ["DialogueId"] = 90170405,
            ["GUID"] = "E1BB6E12",
            ["NextDialogue"] = 90170406,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83301:Think_End",
                },
            },
        [90170406] = {
            ["Content"] = "胖尾巴毕竟是生活在雪原的野兽，它不愿意靠近城市，等待我们的只有分道扬镳。但它会一直留在我的记忆里，和那片雪原一起。",
            ["ContentJP"] = "まんまるニャーゴは雪原に生きる獣だから、街には近づきたがらない。だからお別れするしかなかったけど……あの子はずっと私の記憶のなかにいるんだ。あの雪原の景色と一緒にさ。",
            ["DialogueId"] = 90170406,
            ["GUID"] = "E1BB6E3C",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90170501] = {
            ["Content"] = "我没有，我不是，别瞎说！我都这么大了，怎么还用这种哄小孩的称呼！算我求你了，别再提这个了！",
            ["ContentJP"] = "違うし、私じゃないし、そんなんじゃないし、姫様なんて子供が喜ぶような呼び方されるわけないし！ギブです、ギブするので、もうその話はなしで……！",
            ["DialogueId"] = 90170501,
            ["GUID"] = "E1BB7DD2",
            ["LookAt"] = {
                [1] = "83301:n(0)",
                [2] = "0:n(83301)",
                },
            ["NextDialogue"] = 90170503,
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_05_1",
            },
        [90170503] = {
            ["Content"] = "那玛尔洁希望被人们怎样称呼呢？",
            ["ContentJP"] = "ならマギーはみんなにどう呼ばれたいの？",
            ["DialogueId"] = 90170503,
            ["GUID"] = "E1BB7E26",
            ["NextDialogue"] = 90170504,
            ["SpeakNpcId"] = 100001,
            },
        [90170504] = {
            ["Content"] = "那当然是——咳咳，于城市背面孤独行走，缄默的侦探——玛尔洁小姐！今天，也为你揭示冰湖城不为人知的隐秘！",
            ["ContentJP"] = "そりゃもちろん——ゴホン、街の闇に潜み、独り暗躍する、人呼んで物言わぬ探偵…… それこそがLadyマギー！今日もアイスレイク城の知られざるシークレットを、彼女は丸っと解き明かしていく！",
            ["DialogueId"] = 90170504,
            ["GUID"] = "E1BB7E50",
            ["NextDialogue"] = 90170505,
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_05_2",
            },
        [90170505] = {
            ["Content"] = "嘿嘿，这才是与我相称的外号嘛~",
            ["ContentJP"] = "ふぁふぁふぁ、これこそ私にふさわしい通り名だもんね！",
            ["DialogueId"] = 90170505,
            ["GUID"] = "E1BB7E7A",
            ["NextOptions"] = {
                [1] = 90170002,
                [2] = 90170003,
                },
            ["SpeakNpcId"] = 83301,
            ["TalkActionId"] = {
                [1] = "83301:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90170701] = {
            ["Content"] = "小菲娜！好久不见啦~想听《雪猫游侠与橘猫侦探》的后续？好！等我搬个小板凳，坐下来慢慢给你讲！",
            ["ContentJP"] = "フィーナちゃん、おひさ～！んっ？『雪ネコ冒険者と茶トラ探偵』の続きを聞きたいって？オーケー、椅子を持ってくるから待ってて！座ってゆっくりとお話して進ぜよう！",
            ["DialogueId"] = 90170701,
            ["GUID"] = "E1BB9EA2",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_02",
            },
        [90170801] = {
            ["Content"] = "典狱长大人，我可是彻头彻尾的良民！一没偷二没抢，只是从垃圾桶里拿一点点残羹剩饭果腹罢了，您再敬业，也管不到垃圾头上吧？",
            ["ContentJP"] = "典獄様、私は根っからの善良な市民でございます！空腹を満たすべくゴミ箱から少～しばかし食べ残しなどをちょうだいしているだけで、盗んだり奪ったりはしておりません！いくら仕事熱心な典獄様でも、ゴミ箱は管轄外だと思いますです、はい。",
            ["DialogueId"] = 90170801,
            ["GUID"] = "E1BBAF0A",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_03",
            },
        [90170901] = {
            ["Content"] = "你这日子过得也太紧巴巴了吧！好、好惨……你要不要来和我一起捡垃圾，说不定日子还能过得宽裕一点？",
            ["ContentJP"] = "リーンさんの暮らしぶりってすごく……大変そう。私と一緒にゴミ拾いしよっか？少しは生活に余裕が出るかもだよ？",
            ["DialogueId"] = 90170901,
            ["GUID"] = "E1BBBF72",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_04",
            },
        [90171001] = {
            ["Content"] = "最最最善良美丽的卡米拉姐，我这里有一点小小小小的麻烦，得拜托你帮个忙——这回绝对是最后一次！呃，本月的最后一次！你一定会答应我的，对吧？",
            ["ContentJP"] = "超絶、アルティメット、ベストにトップで優しくお美しいカミラお姉さま。実は少しばかりトラブルが発生しちゃって、ちょびっと助けて欲しいんだけど――今回で絶対に最後！えっと「今月は」最後ね！でもきっと助けてくれるよね！信じてます！そうだよね？",
            ["DialogueId"] = 90171001,
            ["GUID"] = "E1BBCFDA",
            ["SpeakNpcId"] = 83301,
            ["VoiceName"] = "voice/$Locale$/char/Maer/vo_companio_05",
            },
        [90180000] = {
            ["Content"] = "耶尔：红鲤鱼，有头小绿、绿，绿鲤，绿驴，绿缕鱼…….",
            ["ContentJP"] = "イェール：ぬ、ぬき、にき、くい、釘、引きにき、引きぬきにき、釘、釘にきで、くきで……",
            ["DialogueId"] = 90180000,
            ["GUID"] = "E1C19467",
            ["NextDialogue"] = 90180002,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_idle_1",
            },
        [90180001] = {
            ["Content"] = "耶尔：你来啦……天气真好……很适合做爆炸实验……唔，天气真好。",
            ["ContentJP"] = "イェール：いらっしゃい……お天気、いいですね…… はい、爆発実験に向いてる……本当に、いいお天気です。",
            ["DialogueId"] = 90180001,
            ["GUID"] = "E1C1946A",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextOptions"] = {
                [1] = 901800011,
                [2] = 901800012,
                [3] = 901800013,
                [4] = 901800014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90180002] = {
            ["Content"] = "奥利弗：是“红鲤鱼有头小绿驴，绿鲤鱼有头小红驴！”笨蛋耶尔，快跟我念！",
            ["ContentJP"] = "オリバー：「ぬきにくい釘、引きぬきにくい釘、釘ぬきでぬく釘」だ！おら俺に続いて言ってみろ、バカイェール！",
            ["DialogueId"] = 90180002,
            ["GUID"] = "E1C19468",
            ["NextDialogue"] = 90180003,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_idle_2",
            },
        [90180003] = {
            ["Content"] = "耶尔：好、好的！红、红鲤鱼……",
            ["ContentJP"] = "イェール：は、はいぃ！ぬ、抜き、にき……",
            ["DialogueId"] = 90180003,
            ["GUID"] = "E1C19469",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_idle_3",
            },
        [90180004] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90180004,
            ["GUID"] = "90180004.0",
            ["NextDialogue"] = 90180001,
            },
        [90180005] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90180005,
            ["GUID"] = "90180005.0",
            },
        [90180101] = {
            ["Content"] = "耶尔：奥利弗不是会说话的炸弹……可能听起来有些不可思议，但……他其实是……",
            ["ContentJP"] = "イェール：オリバーは、しゃべる爆弾ではないです……信じられないかもですが……彼は、実は……",
            ["DialogueId"] = 90180101,
            ["GUID"] = "E1C1A4D2",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180103,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_1",
            },
        [90180103] = {
            ["Content"] = "奥利弗：闭嘴，被你急死了！我就是耶尔，耶尔就是我。听明白了吗？不明白也无所谓，也没指望你木屑一样的脑子能搞懂。",
            ["ContentJP"] = "オリバー：黙れっつーのイラつかせんじゃねぇ！俺はイェールでイェールは俺ってだけだ。わかったか？まぁわかんなくても別にどーでもいいがな。けし粒みてぇなおめぇの脳ミソの理解力になんざ期待しちゃいねぇし。",
            ["DialogueId"] = 90180103,
            ["GUID"] = "E1C1A526",
            ["NextDialogue"] = 90180104,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_2",
            },
        [90180104] = {
            ["Content"] = "好没礼貌的炸弹，扔了算了。",
            ["ContentJP"] = "生意気な爆弾は、さっさと捨ててしまおう。",
            ["DialogueId"] = 90180104,
            ["GUID"] = "E1C1A550",
            ["NextDialogue"] = 90180105,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83103:Angry01_End",
                },
            },
        [90180105] = {
            ["Content"] = "耶尔：奥利弗他、他他是个好孩子！虽然看看上去脾气不好，说话有点凶，还总总总是突然冒出来，但……",
            ["ContentJP"] = "イェール：か、彼は、オリバーは、い、い、いい子なんですよ！ぶっきらぼうで、話し方も、まあ、キツい感じで……いきなり現れる時も、ありますが……でも……",
            ["DialogueId"] = 90180105,
            ["GUID"] = "E1C1A57A",
            ["NextDialogue"] = 90180106,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_3",
            },
        [90180106] = {
            ["Content"] = "奥利弗：喂，有你这么夸奖人的吗？",
            ["ContentJP"] = "オリバー：おい、おめぇそれ褒めてんのか？",
            ["DialogueId"] = 90180106,
            ["GUID"] = "E1C1A5A4",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90180201] = {
            ["Content"] = "耶尔：我……可能派不上什么用场。唯一擅长的……可能就只有制作“小可爱”了吧？",
            ["ContentJP"] = "イェール：僕は……お役には、立てないかもです。唯一の特技は、この……「キュートちゃん」を作ることだけかも……？",
            ["DialogueId"] = 90180201,
            ["GUID"] = "E1C1B53A",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180203,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_02_1",
            },
        [90180203] = {
            ["Content"] = "嗯？“小可爱”是什么？",
            ["ContentJP"] = "えーと、「キュートちゃん」って？",
            ["DialogueId"] = 90180203,
            ["GUID"] = "E1C1B58E",
            ["NextDialogue"] = 90180204,
            ["SpeakNpcId"] = 100001,
            },
        [90180204] = {
            ["Content"] = "耶尔：“小可爱”……是“劈里啪啦”玩具店中……最受欢迎的商品，制作它们，要花费不少时间。",
            ["ContentJP"] = "イェール：「キュートちゃん」は……オモチャ屋「ドンパチ」の……一番の人気商品です。作るのには、すごく時間がかかります。",
            ["DialogueId"] = 90180204,
            ["GUID"] = "E1C1B5B8",
            ["NextDialogue"] = 90180205,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_02_2",
            },
        [90180205] = {
            ["Content"] = "耶尔：但，不是因为我的技艺……有多好，只是因为，奥利弗他很熟悉。",
            ["ContentJP"] = "イェール：でも、僕の技術力が優れてるとかじゃなくて……オリバーがただ、慣れてるだけなんです。",
            ["DialogueId"] = 90180205,
            ["GUID"] = "E1C1B5E2",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_02_3",
            ["bForbidSkipOptions"] = true,
            },
        [90180301] = {
            ["Content"] = "耶尔：啊，抱歉！但、但是要是说得快了，我的舌头就就就容易打结。",
            ["ContentJP"] = "イェール：あ、あ、すみません！で、でも、速くしゃべろうとすると、舌が、回らなくなってしまって。",
            ["DialogueId"] = 90180301,
            ["GUID"] = "E1C1C5A2",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180303,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_03_1",
            },
        [90180303] = {
            ["Content"] = "那和别人交流起来应该还挺不容易的。",
            ["ContentJP"] = "それでも頑張ってほかの人と話しているんだね。",
            ["DialogueId"] = 90180303,
            ["GUID"] = "E1C1C5F6",
            ["NextDialogue"] = 90180304,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "83103:Sigh_End",
                },
            },
        [90180304] = {
            ["Content"] = "耶尔：还、还好，有时候奥利弗会帮我说......而且，旁边没有人的时候，奥利弗总会把我想说的话听完的。",
            ["ContentJP"] = "イェール：ま、まあ、はい。時々オリバーが、代わりに話してくれます……僕の言いたいことは、隣に誰もいない時、オリバーが全部聞いてくれます。",
            ["DialogueId"] = 90180304,
            ["GUID"] = "E1C1C620",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_03_2",
            ["bForbidSkipOptions"] = true,
            },
        [90180401] = {
            ["Content"] = "耶尔：我没有“小时候”……我从记事的时候，就在这个大孩子的身体里了。奥利弗也许有吧。",
            ["ContentJP"] = "イェール：僕には「子供の頃」が、ありません……気がついたら、この身体の中にいたので。オリバーなら、「子供の頃」が、あるかもです。",
            ["DialogueId"] = 90180401,
            ["GUID"] = "E1C1D60A",
            ["LookAt"] = {
                [1] = "83103:n(0)",
                [2] = "0:n(83103)",
                },
            ["NextDialogue"] = 90180403,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_1",
            },
        [90180403] = {
            ["Content"] = "少了很多回忆，有点遗憾。",
            ["ContentJP"] = "思い出が少ないのは悲しいね。",
            ["DialogueId"] = 90180403,
            ["GUID"] = "E1C1D65E",
            ["NextDialogue"] = 90180404,
            ["SpeakNpcId"] = 100001,
            },
        [90180404] = {
            ["Content"] = "耶尔：我也想过如果能有“童年”，应该会是……怎样的呢？每晚睡觉前……琼斯先生会不会像普通的爸爸一样，坐在我的床头……给我讲故事……",
            ["ContentJP"] = "イェール：考えたことはあります。もし「子供の頃」があれば……どんな感じかなって。ジョーンズ先生が、普通のお父さんのように……毎晩寝る前に、ベッドの横に座って……物語を、聞かせてくれたら……",
            ["DialogueId"] = 90180404,
            ["GUID"] = "E1C1D688",
            ["NextDialogue"] = 90180405,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_2",
            },
        [90180405] = {
            ["Content"] = "奥利弗：琼斯那混蛋讲故事？你脑子进胶水了吗？",
            ["ContentJP"] = "オリバー：あのジョーンズの野郎から物語を聞くだって？おめぇん頭んなかは花畑かよ？",
            ["DialogueId"] = 90180405,
            ["GUID"] = "E1C1D6B2",
            ["NextDialogue"] = 90180406,
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_3",
            },
        [90180406] = {
            ["Content"] = "耶尔：对对对不起！我我知道的，他只关心实验，不会做这些……",
            ["ContentJP"] = "イェール：ご、ごご、ごめん、なさい！わ、わかってるから！彼の興味があるのは実験だけで、物語なんて、聞かせる気ないってことは……",
            ["DialogueId"] = 90180406,
            ["GUID"] = "E1C1D6DC",
            ["NextOptions"] = {
                [1] = 90180004,
                [2] = 90180005,
                },
            ["SpeakNpcId"] = 83103,
            ["TalkActionId"] = {
                [1] = "83103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_topic_04_4",
            ["bForbidSkipOptions"] = true,
            },
        [90180501] = {
            ["Content"] = "耶尔：您，您好……您的歌声，真的很、很动听。",
            ["ContentJP"] = "イェール：こ、こんにちは……君の歌声、本当にと、とても、とても美しいです。",
            ["DialogueId"] = 90180501,
            ["GUID"] = "E1C1E672",
            ["NextDialogue"] = 90180502,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_01_1",
            },
        [90180502] = {
            ["Content"] = "奥利弗：哼，又一只可怜虫。",
            ["ContentJP"] = "オリバー：ふん、哀れな虫のもう1匹か。",
            ["DialogueId"] = 90180502,
            ["GUID"] = "E1C1E69C",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_01_2",
            },
        [90180601] = {
            ["Content"] = "耶尔：榛子……是你的朋友吗？我也有很好的朋友，他像榛、榛子一样可靠。",
            ["ContentJP"] = "イェール：ヘーゼルナッツは……君の、友達ですか？僕にも、友達がいます、仲のいい。彼はヘ、ヘーゼルナッツのように、信頼できます。",
            ["DialogueId"] = 90180601,
            ["GUID"] = "E1C1F6DA",
            ["NextDialogue"] = 90180602,
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_02_1",
            },
        [90180602] = {
            ["Content"] = "奥利弗：你骂谁呢？",
            ["ContentJP"] = "オリバー：俺のことブタと同じって言いたいのか？",
            ["DialogueId"] = 90180602,
            ["GUID"] = "E1C1F704",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_02_2",
            },
        [90180701] = {
            ["Content"] = "耶尔：唔啊……你、你不要生气，我的炸弹实验都是符！符符符符合安全规定的……",
            ["ContentJP"] = "イェール：あぅ……お、お、怒らないで。僕の、爆弾の実験は、せせ、セキュリティ基準を、ぜんぶ、み、満たしてますから……",
            ["DialogueId"] = 90180701,
            ["GUID"] = "E1C20742",
            ["SpeakNpcId"] = 83103,
            ["VoiceName"] = "voice/$Locale$/char/Yeer/vo_companio_03",
            },
        [90190000] = {
            ["Content"] = "难得有这么悠闲的时光，没有伤患的呼救，也没有紧急的战报。嗯……泡杯咖啡，把那本小说看完吧。公主最后到底和谁在一起了呢……",
            ["ContentJP"] = "怪我人のうめき声も、急な戦況報告もない、これほど安らかなひと時はいつぶりか……コーヒーを淹れて、あの小説を最後まで読んでしまいましょう。お姫様は結局、誰と結ばれたのかしら……",
            ["DialogueId"] = 90190000,
            ["GUID"] = "E1C7FD09",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_idle",
            },
        [90190001] = {
            ["Content"] = "很高兴看到您今天健康平安。请多加珍重……为了终有一天会到来的和平。",
            ["ContentJP"] = "今日もお元気そうでホッとしました。お体にはくれぐれも気をつけてください……いずれ訪れる平和のためにも。",
            ["DialogueId"] = 90190001,
            ["GUID"] = "E1C7FD0A",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextOptions"] = {
                [1] = 901900011,
                [2] = 901900012,
                [3] = 901900013,
                [4] = 901900014,
                [5] = 901900015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90190002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90190002,
            ["GUID"] = "90190002.0",
            ["NextDialogue"] = 90190001,
            },
        [90190003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90190003,
            ["GUID"] = "90190003.0",
            },
        [90190101] = {
            ["Content"] = "我……没有什么特别的爱好。也许读书算一个吧？",
            ["ContentJP"] = "そうですね……特に趣味と呼べるようなものはありません。強いて言えば、読書でしょうか。",
            ["DialogueId"] = 90190101,
            ["GUID"] = "E1C80D72",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190102,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_1",
            },
        [90190102] = {
            ["Content"] = "虽然妈妈总是唠叨，说我一直把自己关在家里，错过了那些舞会和沙龙，会失去很多跻身更上一层的机会……",
            ["ContentJP"] = "舞踏会や社交の席にほとんど参加せず、家に閉じこもってばかりだったので……お偉いさまに取り入る機会を無駄にしたと、母に口うるさく言われたものです……",
            ["DialogueId"] = 90190102,
            ["GUID"] = "E1C80D9C",
            ["NextDialogue"] = 90190103,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_2",
            },
        [90190103] = {
            ["Content"] = "但我还是觉得，这样就很好。",
            ["ContentJP"] = "ですが、私は今の生活に十分満足しています。",
            ["DialogueId"] = 90190103,
            ["GUID"] = "E1C80DC6",
            ["NextDialogue"] = 90190104,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_3",
            },
        [90190104] = {
            ["Content"] = "那你最近在看什么书？",
            ["ContentJP"] = "最近はどんな本を読んでいるの？",
            ["DialogueId"] = 90190104,
            ["GUID"] = "E1C80DF0",
            ["NextDialogue"] = 90190105,
            ["SpeakNpcId"] = 100001,
            },
        [90190105] = {
            ["Content"] = "主要是战伤救治相关的书籍，《战地应急救援策略》、《常规外伤处理》、《野战医院的临时搭建》……",
            ["ContentJP"] = "ほとんど戦場での応急処置に関するものですね。例えば、『戦場救援マニュアル』、『一般的な外傷の手当て』、『野戦臨時病院の構造』ってところでしょうか……",
            ["DialogueId"] = 90190105,
            ["GUID"] = "E1C80E1A",
            ["NextDialogue"] = 90190106,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_4",
            },
        [90190106] = {
            ["Content"] = "您也许知道，我过去学习的方向并非救护相关，尽管我已经获得了军团随行医务员的资格，但仍然时常感到沉重与惶恐。",
            ["ContentJP"] = "ご存知のように、私がこれまで学んできた内容は人の救助とは全く無関係の知識でした。医務官の資格を取得した今でも、時々プレッシャーと不安を感じてしまうんです。",
            ["DialogueId"] = 90190106,
            ["GUID"] = "E1C80E44",
            ["NextDialogue"] = 90190107,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_5",
            },
        [90190107] = {
            ["Content"] = "你也要适当放松一下，不要让自己太紧绷了。",
            ["ContentJP"] = "そんなに緊張しないで、リラックスした方がいいよ。",
            ["DialogueId"] = 90190107,
            ["GUID"] = "E1C80E6E",
            ["NextDialogue"] = 90190108,
            ["SpeakNpcId"] = 100001,
            },
        [90190108] = {
            ["Content"] = "嗯，最近我也在看一本叫做《玻璃鞋》的书。是关于……呃，公主和骑士……我、我并不是非常喜欢看浪漫小说！只是，随便……翻一下……",
            ["ContentJP"] = "ええ、最近『ガラスの靴』という本を読んだんです。ええと……その、お姫様と騎士の……物語です。べ、べつに恋愛小説が好きなわけではありません！ただ、少し……内容が気になっただけで……",
            ["DialogueId"] = 90190108,
            ["GUID"] = "E1C80E98",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_01_6",
            ["bForbidSkipOptions"] = true,
            },
        [90190201] = {
            ["Content"] = "嗯，当然可以！它是海伯利亚的基石，是学者们口中“原初的奇迹”！",
            ["ContentJP"] = "もちろんです！錬金術とは、ヒュペリアの土台であり、学者たちの間では「始まりの奇跡」と呼ばれています！",
            ["DialogueId"] = 90190201,
            ["GUID"] = "E1C81DDA",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190202,
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_1",
            },
        [90190202] = {
            ["Content"] = "最一开始，人们试图从月石中分离出黄金，但后来，人们发现这枚小小的石头还有更多用途——转动机械的齿轮，释放电的火花……它就是索拉之民的“魔法”。",
            ["ContentJP"] = "当初、人々は月ノ石から金を分離しようとしていました。しかし、のちにこの小さな石に潜む無数の可能性を発見したのです――それは機械の歯車を回し、電気の火花を散らす……ソラ族でいう「魔法」です。",
            ["DialogueId"] = 90190202,
            ["GUID"] = "E1C81E04",
            ["NextDialogue"] = 90190203,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_2",
            },
        [90190203] = {
            ["Content"] = "……只是后来，炼金院……",
            ["ContentJP"] = "……ただその後、錬金院は……",
            ["DialogueId"] = 90190203,
            ["GUID"] = "E1C81E2E",
            ["NextDialogue"] = 90190204,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_3",
            },
        [90190204] = {
            ["Content"] = "你好像在炼金院待过？",
            ["ContentJP"] = "確か、錬金院にいたよね？",
            ["DialogueId"] = 90190204,
            ["GUID"] = "E1C81E58",
            ["NextDialogue"] = 90190205,
            ["SpeakNpcId"] = 100001,
            },
        [90190205] = {
            ["Content"] = "……是的。不过，那已经是过去的事了。",
            ["ContentJP"] = "……ええ。ですが、もう昔のことです。",
            ["DialogueId"] = 90190205,
            ["GUID"] = "E1C81E82",
            ["NextDialogue"] = 90190206,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_4",
            },
        [90190206] = {
            ["Content"] = "你为什么要离开炼金院？",
            ["ContentJP"] = "なぜ錬金院を離れたの？",
            ["DialogueId"] = 90190206,
            ["GUID"] = "E1C81EAC",
            ["NextDialogue"] = 90190207,
            ["SpeakNpcId"] = 100001,
            },
        [90190207] = {
            ["Content"] = "因为后来的佩剑炼金院偏离了轨道，走在了一条错误的路上。它是海伯利亚这座战车最炽热的炉芯，但燃料却是太多人的痛苦和不幸。",
            ["ContentJP"] = "サーベル錬金院が本来の軌道から外れ、人の道を誤ったからです。錬金院はヒュペリアという戦車におけるエンジンでした。ですが、その燃料は人々の苦しみと不幸から搾られたものだったんです。",
            ["DialogueId"] = 90190207,
            ["GUID"] = "E1C81ED6",
            ["NextDialogue"] = 90190208,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_5",
            },
        [90190208] = {
            ["Content"] = "我想，我远比自己想象中更软弱。我无法说服自己接受它，也没有勇气和力量阻止它。所以，我只能选择逃避它。",
            ["ContentJP"] = "私は自分が思っていたより弱い人だったんだと思います。それを受け入れる覚悟も、止める勇気や力もなく、ただ逃げるという選択しかできませんでした。",
            ["DialogueId"] = 90190208,
            ["GUID"] = "E1C81F00",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_02_6",
            ["bForbidSkipOptions"] = true,
            },
        [90190301] = {
            ["Content"] = "一些应急的器械和药品。绷带，消毒剂，麻醉剂，还有处理外伤的刀片和缝线。",
            ["ContentJP"] = "緊急用の機械と薬品です。包帯、消毒液、麻酔剤、そして外傷を処理するメスと縫い糸を常に持ち歩くようにしているんです。",
            ["DialogueId"] = 90190301,
            ["GUID"] = "E1C82E42",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190302,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_1",
            },
        [90190302] = {
            ["Content"] = "此外，还有一张手帕和一把梳子。",
            ["ContentJP"] = "あとは、ハンカチとくしですかね。",
            ["DialogueId"] = 90190302,
            ["GUID"] = "E1C82E6C",
            ["NextDialogue"] = 90190303,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_2",
            },
        [90190303] = {
            ["Content"] = "战场上也要梳妆么？达芙涅很爱美呢。",
            ["ContentJP"] = "戦場でも身だしなみに気をつかってるんだね。",
            ["DialogueId"] = 90190303,
            ["GUID"] = "E1C82E96",
            ["NextDialogue"] = 90190304,
            ["SpeakNpcId"] = 100001,
            },
        [90190304] = {
            ["Content"] = "啊，这个……不是我自己用的。如果救护的伤员不幸离世，我会帮他们简单整理一下仪容。",
            ["ContentJP"] = "あ、いえ……これは私が使うのではありません。負傷者さんが不運にも命を落とした時、簡単に身だしなみを整えるために使うものなんです。",
            ["DialogueId"] = 90190304,
            ["GUID"] = "E1C82EC0",
            ["NextDialogue"] = 90190305,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_3",
            },
        [90190305] = {
            ["Content"] = "伤痛是很残忍的东西，它从人们那里夺走的，除了生命，还有生而为人的全部尊严。",
            ["ContentJP"] = "痛みとは残酷なものです。それは命だけでなく、人間としての尊厳をすべて奪われてしまうのですから。",
            ["DialogueId"] = 90190305,
            ["GUID"] = "E1C82EEA",
            ["NextDialogue"] = 90190306,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_4",
            },
        [90190306] = {
            ["Content"] = "我希望……他们的家人看到的他们，可以干净一些、安详一些……久别重逢，父母应该看到孩子们安然睡去的脸，而不是被疼痛扭曲五官的凄惨面容。",
            ["ContentJP"] = "なので……せめて遺族の方たちには、よりキレイで穏やかな姿にして送り返したいんです……痛みで歪んだ無残な姿ではなく、安らかに眠る我が子の顔を見せることが、せめてもの慰めだと思いまして……",
            ["DialogueId"] = 90190306,
            ["GUID"] = "E1C82F14",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_03_5",
            ["bForbidSkipOptions"] = true,
            },
        [90190401] = {
            ["Content"] = "我没关系，不辛苦的！……呃，其实还是有点……急救和护理知识的学习还好，但体能测试确实令人苦恼。",
            ["ContentJP"] = "いえ、全然平気です！……ええと、実は少しだけ……応急処置と看護の知識はバッチリなのですが、体力テストは着いていくので精一杯で……",
            ["DialogueId"] = 90190401,
            ["GUID"] = "E1C83EAA",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190402,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_1",
            },
        [90190402] = {
            ["Content"] = "就算每天比大家起得更早独自加练，还是只能拿勉强及格的分数……唉，不要笑话我，锻炼体力真是比读书难太多了。",
            ["ContentJP"] = "毎日早起きして、自主練をしているのですが、それでもギリギリ合格点しか取れなくて……うっ、笑わないでください！勉強よりも運動のほうがよっぽど大変なんですから。",
            ["DialogueId"] = 90190402,
            ["GUID"] = "E1C83ED4",
            ["NextDialogue"] = 90190403,
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_2",
            },
        [90190403] = {
            ["Content"] = "早起加练，听起来好累啊。",
            ["ContentJP"] = "早起きして自主練なんて、聞いただけで大変そうだね。",
            ["DialogueId"] = 90190403,
            ["GUID"] = "E1C83EFE",
            ["NextDialogue"] = 90190404,
            ["SpeakNpcId"] = 100001,
            },
        [90190404] = {
            ["Content"] = "嗯，的确很累。不过当我把注意力从脚下移开，去看城郊的麦田，地平线尽头的小屋，去听风车的每一声转动和牧牛人的每一声哨笛，就觉得平静许多。",
            ["ContentJP"] = "はい、確かにとても疲れます。でも、注意力を足元から逸らし、郊外の麦畑や地平線の果てにある小屋を眺めたり、風車の音や牛飼いの笛の音に耳を傾けたりしていると、不思議と気持ちが落ち着くんです。",
            ["DialogueId"] = 90190404,
            ["GUID"] = "E1C83F28",
            ["NextDialogue"] = 90190405,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_3",
            },
        [90190405] = {
            ["Content"] = "因为……也许我奔跑在这条路上，就是为了保护这些最普通、最寻常的东西不被毁掉吧。",
            ["ContentJP"] = "……私がこうして走っているのは、このありふれた日常を守るためなんだって思えるから。",
            ["DialogueId"] = 90190405,
            ["GUID"] = "E1C83F52",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_04_4",
            ["bForbidSkipOptions"] = true,
            },
        [90190501] = {
            ["Content"] = "……我最后一次和爸爸说话，就是在对讲机里。那时还在龙莎要塞危机四伏的战场，他却对我说，“你放心。”",
            ["ContentJP"] = "……父との最後の会話は、トランシーバー越しだったんです。その時、父はロンザ要塞にある危険な戦場にいたのに、「心配するな 」って慰めてくれました。",
            ["DialogueId"] = 90190501,
            ["GUID"] = "E1C84F12",
            ["LookAt"] = {
                [1] = "85401:n(0)",
                [2] = "0:n(85401)",
                },
            ["NextDialogue"] = 90190502,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_1",
            },
        [90190502] = {
            ["Content"] = "后来我还是会常常在深夜打开自己的对讲机，调到爸爸的频段，按下呼叫按钮，期待着他的声音从对讲机那头传来……",
            ["ContentJP"] = "その後、ときどき深夜にトランシーバーの電源を入れて、父の周波数に合わせていました。トランシーバーの向こうから父の声が聞こえてくるのに期待して――",
            ["DialogueId"] = 90190502,
            ["GUID"] = "E1C84F3C",
            ["NextDialogue"] = 90190503,
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_2",
            },
        [90190503] = {
            ["Content"] = "直到我对着听筒等了十几分钟，我才突然发现，他是真的回不来了。",
            ["ContentJP"] = "ある日の夜、いつものように電源を入れて十数分待った時、急に気付いたんです。彼はもう二度と帰って来ないんだと……",
            ["DialogueId"] = 90190503,
            ["GUID"] = "E1C84F66",
            ["NextDialogue"] = 90190504,
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_3",
            },
        [90190504] = {
            ["Content"] = "请你节哀……",
            ["ContentJP"] = "その、元気出して……",
            ["DialogueId"] = 90190504,
            ["GUID"] = "E1C84F90",
            ["NextDialogue"] = 90190505,
            ["SpeakNpcId"] = 100001,
            },
        [90190505] = {
            ["Content"] = "谢谢，我明白的。我会好好活下去，在为父亲、为龙莎战役的死难者洗刷冤屈之前，我不会停下脚步。",
            ["ContentJP"] = "ええ、心配しないでください。父の分までしっかり生きるって決めたので。ロンザの戦いの犠牲者たちの無念を晴らすまで、歩みを止めるつもりはありません。",
            ["DialogueId"] = 90190505,
            ["GUID"] = "E1C84FBA",
            ["NextOptions"] = {
                [1] = 90190002,
                [2] = 90190003,
                },
            ["SpeakNpcId"] = 85401,
            ["TalkActionId"] = {
                [1] = "85401:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_topic_05_4",
            ["bForbidSkipOptions"] = true,
            },
        [90190601] = {
            ["Content"] = "我曾在皇都的图书馆中阅读过华胥的医书，虽然与海伯利亚的医理不太相同，但应用于救治却十分有效。这本书中我仍有一些问题，方便向您请教吗？",
            ["ContentJP"] = "帝都の図書館で華胥の医学書を読んだことがあります。ヒュペリアの医学論とは少し違いますが、応急処置に応用するには最適な内容でした。ただ、いくつかわからないことがありまして、お聞きしてもいいですか？",
            ["DialogueId"] = 90190601,
            ["GUID"] = "E1C85F7A",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_01",
            },
        [90190701] = {
            ["Content"] = "典狱长女士，迟来的正义真的还是正义吗？",
            ["ContentJP"] = "典獄さん、遅れてやってきた正義は本当に正義と呼べるのでしょうか？",
            ["DialogueId"] = 90190701,
            ["GUID"] = "E1C86FE2",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_02",
            },
        [90190801] = {
            ["Content"] = "好久不见，自离开炼金院后我们就很少联系了，你还……好吗？",
            ["ContentJP"] = "お久しぶりです。錬金院を離れてから、お会いするのは随分久しぶりですね。お元気……でしたか？",
            ["DialogueId"] = 90190801,
            ["GUID"] = "E1C8804A",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_03",
            },
        [90190901] = {
            ["Content"] = "虽然我已经离开了佩剑炼金院，但那依旧是我学习过的地方。也许您永远不会选择宽恕，但还是请允许我说一句，对不起。",
            ["ContentJP"] = "既に縁を断ったとはいえ、サーベル錬金院が私の学びの場だった事実は払拭できません。お許しいただかなくていいので、どうか謝らせてください。",
            ["DialogueId"] = 90190901,
            ["GUID"] = "E1C890B2",
            ["SpeakNpcId"] = 85401,
            ["VoiceName"] = "voice/$Locale$/char/Dafu/vo_companio_04",
            },
        [90200000] = {
            ["Content"] = "嘘……我就快要进入角色了。",
            ["ContentJP"] = "静かに……あとちょっとで役に入れそうだから。",
            ["DialogueId"] = 90200000,
            ["GUID"] = "E1CE65A9",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_idle",
            },
        [90200001] = {
            ["Content"] = "如今我扮演破碎的囚徒，而你是为我执掌枷锁的典狱长。",
            ["ContentJP"] = "僕は傷だらけの囚人役で、君はその僕を縛り付ける監守役だ。",
            ["DialogueId"] = 90200001,
            ["GUID"] = "E1CE65AA",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextOptions"] = {
                [1] = 902000011,
                [2] = 902000012,
                [3] = 902000013,
                [4] = 902000014,
                [5] = 902000015,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90200002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90200002,
            ["GUID"] = "90200002.0",
            ["NextDialogue"] = 90200001,
            },
        [90200003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90200003,
            ["GUID"] = "90200003.0",
            },
        [90200101] = {
            ["Content"] = "他是被摔碎的玻璃灯，是洒在污水沟里的星星。",
            ["ContentJP"] = "粉々に砕けたガラスのランプ、下水道に落ちた星――ってところかな。",
            ["DialogueId"] = 90200101,
            ["GUID"] = "E1CE7612",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200102,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_1",
            },
        [90200102] = {
            ["Content"] = "…………？",
            ["ContentJP"] = "…………？",
            ["DialogueId"] = 90200102,
            ["GUID"] = "E1CE763C",
            ["NextDialogue"] = 90200103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81103:Talk01_End",
                },
            },
        [90200103] = {
            ["Content"] = "和那些东西一样，荒诞得惹人发笑，却又闪闪发亮。",
            ["ContentJP"] = "それらと同じように、思わず笑っちゃうほどバカバカしいのに、どこか眩しいやつだった。",
            ["DialogueId"] = 90200103,
            ["GUID"] = "E1CE7666",
            ["NextDialogue"] = 90200104,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_2",
            },
        [90200104] = {
            ["Content"] = "我们的牢房只隔着一道墙，隔音差得让人绝望。他就在我看不见的一米之外，一会儿回忆家人，一会儿憧憬未来，一会儿又五音不全地哼起歌。",
            ["ContentJP"] = "僕たちの牢屋は壁一枚隔てられてるだけで、何もかもが筒抜けだった。あいつは1メートル先で、家族を思い出したり、未来を夢見たり、急に音痴な声で歌ってたな。",
            ["DialogueId"] = 90200104,
            ["GUID"] = "E1CE7690",
            ["NextDialogue"] = 90200105,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_3",
            },
        [90200105] = {
            ["Content"] = "有时我甚至恍惚觉得，我不是被关在笼子里的困兽，而是一个无忧无虑的普通学生，在午后打盹时做了个噩梦，被邻座聒噪的同学吵醒了。",
            ["ContentJP"] = "そのせいか、僕は時折自分が檻に閉じ込められた獣ではなく、無邪気な学生だと錯覚することがある。午後の昼寝で悪夢にうなされてた時、隣の席の騒がしいクラスメイトに起こされたかのような気分になるんだ。",
            ["DialogueId"] = 90200105,
            ["GUID"] = "E1CE76BA",
            ["NextDialogue"] = 90200106,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_4",
            },
        [90200106] = {
            ["Content"] = "所以，你被他吸引，和他成为了朋友。",
            ["ContentJP"] = "だから、彼に惹かれて、友だちになったんだね。",
            ["DialogueId"] = 90200106,
            ["GUID"] = "E1CE76E4",
            ["NextDialogue"] = 90200107,
            ["SpeakNpcId"] = 100001,
            },
        [90200107] = {
            ["Content"] = "……呵，也许吧。",
            ["ContentJP"] = "……まあ、そうかもね。",
            ["DialogueId"] = 90200107,
            ["GUID"] = "E1CE770E",
            ["NextDialogue"] = 90200108,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_5",
            },
        [90200108] = {
            ["Content"] = "但“朋友”是一个过于耀眼的词语，我不配拥有它。或许更应该算是，干枯河床里搁浅的两条鱼吧。",
            ["ContentJP"] = "けど、「友だち」という言葉はあまりに眩すぎる。僕にはその資格はないよ。干上がった川底に取り残された二匹の魚のようなものかな。",
            ["DialogueId"] = 90200108,
            ["GUID"] = "E1CE7738",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_01_6",
            ["bForbidSkipOptions"] = true,
            },
        [90200201] = {
            ["Content"] = "为什么？“帕西法尔”的人生早已落幕。那个名字太遥远了，远到我怀疑自己是否曾真的拥有它。",
            ["ContentJP"] = "なぜ？ 「パシファル」の人生はもう終わった。今となっては、どちらが本名だったか疑うほど、遠い記憶の断片に過ぎない。",
            ["DialogueId"] = 90200201,
            ["GUID"] = "E1CE867A",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200202,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_1",
            },
        [90200202] = {
            ["Content"] = "但对我来说，你的存在是真实的。",
            ["ContentJP"] = "大事なのはあなたが存在しているということだよ。",
            ["DialogueId"] = 90200202,
            ["GUID"] = "E1CE86A4",
            ["NextDialogue"] = 90200203,
            ["SpeakNpcId"] = 100001,
            },
        [90200203] = {
            ["Content"] = "……是吗？",
            ["ContentJP"] = "……そうか？",
            ["DialogueId"] = 90200203,
            ["GUID"] = "E1CE86CE",
            ["NextDialogue"] = 90200204,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_2",
            },
        [90200204] = {
            ["Content"] = "好吧。既然如此，我会把这最后一场戏一直演下去——为了我最后的、唯一的观众。",
            ["ContentJP"] = "まあいい。では、このラストショーを演じ続けるとしよう――僕の最後の、そして唯一の観客のために。",
            ["DialogueId"] = 90200204,
            ["GUID"] = "E1CE86F8",
            ["NextDialogue"] = 90200205,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_3",
            },
        [90200205] = {
            ["Content"] = "谢谢你，让我停驻在你的舞台上。",
            ["ContentJP"] = "舞台にあげてくれて、ありがとう。",
            ["DialogueId"] = 90200205,
            ["GUID"] = "E1CE8722",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90200301] = {
            ["Content"] = "多谢你的慷慨。但我的承诺都已兑现，我已经不再有什么值得眷念的事。",
            ["ContentJP"] = "お前は優しいな。だが、果たすべき約束は全て果たした。もう心残りはないよ。",
            ["DialogueId"] = 90200301,
            ["GUID"] = "E1CE96E2",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200302,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_1",
            },
        [90200302] = {
            ["Content"] = "…………",
            ["ContentJP"] = "…………",
            ["DialogueId"] = 90200302,
            ["GUID"] = "E1CE970C",
            ["NextDialogue"] = 90200303,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_2",
            },
        [90200303] = {
            ["Content"] = "若有一天你在盖雷亚剧院遇到我的恩师薇奥莱塔女士，请转告她，我已在伊瑟尔定居。现在过得很好，请不要担忧。",
            ["ContentJP"] = "ガレア劇場に、僕の先生だったヴィオレッタさんがいるんだ。もしもいつか出会ったら、僕はイーザーで幸せに暮らしてるから、心配しないでって伝えてくれないか？",
            ["DialogueId"] = 90200303,
            ["GUID"] = "E1CE9736",
            ["NextDialogue"] = 90200304,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_3",
            },
        [90200304] = {
            ["Content"] = "“那是音乐与诗的国度，那里的每一颗卵石都敲击着节拍，每一泓泉水都歌唱着旋律。”",
            ["ContentJP"] = "「そこは音楽と詩の国で、小石すらリズムを刻み、泉の水すら旋律を奏でてるんだ」って。",
            ["DialogueId"] = 90200304,
            ["GUID"] = "E1CE9760",
            ["NextDialogue"] = 90200305,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_4",
            },
        [90200305] = {
            ["Content"] = "这样一来，或许她就不会再打听我的下落了。我曾是她欣赏的学生……我不希望她因我蒙羞。",
            ["ContentJP"] = "それで僕を探すのを諦めてくれるといいが……僕は先生の自慢の生徒だったからな。僕のせいで彼女に恥をかかせたくないんだ。",
            ["DialogueId"] = 90200305,
            ["GUID"] = "E1CE978A",
            ["NextDialogue"] = 90200306,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_5",
            },
        [90200306] = {
            ["Content"] = "善意的欺骗吗……",
            ["ContentJP"] = "優しい嘘、ってことだね……",
            ["DialogueId"] = 90200306,
            ["GUID"] = "E1CE97B4",
            ["NextDialogue"] = 90200307,
            ["SpeakNpcId"] = 100001,
            },
        [90200307] = {
            ["Content"] = "嗯，一无所知总会是更加幸福的。",
            ["ContentJP"] = "うん、何も知らないほうが幸せなこともあるからな。",
            ["DialogueId"] = 90200307,
            ["GUID"] = "E1CE97DE",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_03_6",
            ["bForbidSkipOptions"] = true,
            },
        [90200401] = {
            ["Content"] = "为什么想学表演？你不需要变成任何人。",
            ["ContentJP"] = "なぜだ？お前はお前だ。他人に成りきる必要はない。",
            ["DialogueId"] = 90200401,
            ["GUID"] = "E1CEA74A",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200402,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_04_1",
            },
        [90200402] = {
            ["Content"] = "“变成任何人”？",
            ["ContentJP"] = "「他人に成りきる」？",
            ["DialogueId"] = 90200402,
            ["GUID"] = "E1CEA774",
            ["NextDialogue"] = 90200403,
            ["SpeakNpcId"] = 100001,
            },
        [90200403] = {
            ["Content"] = "只要站在舞台上，把你的每一寸骨骼，每一缕气息奉献给演出，你就可以彻底变成另一个人、忘记带给你痛苦的一切，走向你前所未见的世界。",
            ["ContentJP"] = "舞台に立った時、その体と呼吸のすべてを演技に捧げれば、お前は完全に別人となれるんだ。その瞬間、初めて自分を苦しめたすべてを忘れ、未知の世界に踏み出すことができる。",
            ["DialogueId"] = 90200403,
            ["GUID"] = "E1CEA79E",
            ["NextDialogue"] = 90200404,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_04_2",
            },
        [90200404] = {
            ["Content"] = "但你生而就是一位冒险故事里被祝福的主人公，拥有所有角色的瞩目和信赖。你无需舞台，便足以熠熠生辉。",
            ["ContentJP"] = "とはいえ、お前は生まれた瞬間から冒険物語で祝福を受けた主人公になると決まっていた。すべての登場人物がお前を注目し信用するだろう。舞台がなくとも、お前は十分輝かしい存在だ。",
            ["DialogueId"] = 90200404,
            ["GUID"] = "E1CEA7C8",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_04_3",
            ["bForbidSkipOptions"] = true,
            },
        [90200501] = {
            ["Content"] = "它站在那儿，经历远比我的生命悠长的岁月。在它外墙的这一边，是巍峨的内城。和乌云一样高，比乌云更冷。",
            ["ContentJP"] = "あれは僕が生まれるよりずっと前からそこに佇んでいた。その外壁の向こうには、そびえ立つ内城区があり――雲のように高く、雲よりずっと寒い場所だ。",
            ["DialogueId"] = 90200501,
            ["GUID"] = "E1CEB7B2",
            ["LookAt"] = {
                [1] = "81103:n(0)",
                [2] = "0:n(81103)",
                },
            ["NextDialogue"] = 90200502,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_1",
            },
        [90200502] = {
            ["Content"] = "人们从裹着丝绸的马车走来，谈论总不放晴的天气，谈论诗歌与绘画，谈论舞会与婚事，抱怨外城污浊的雪水弄脏了漂亮的皮靴。",
            ["ContentJP"] = "絹に包まれた馬車から降りてくる人々は、曇り続きの天気を語り、詩や絵画、舞踏会や結婚式の話をしながら、外城区から流れ込む汚れた雪水が上品な革靴を汚すことに不満を漏らしていた。",
            ["DialogueId"] = 90200502,
            ["GUID"] = "E1CEB7DC",
            ["NextDialogue"] = 90200503,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_2",
            },
        [90200503] = {
            ["Content"] = "外墙的另一侧，是嘈杂的雾区。在那儿，小贩扯尖嗓子叫卖，母亲抱着自己的孩子，乞求一片黑面包果腹。好事者一边躲着卫兵，一边在墙上涂鸦。",
            ["ContentJP"] = "外壁のもう一方には、賑やかな霧の街が広がっている。そこでは、声を張り上げて客引きする屋台の商人や子供たちを抱えて黒パンを乞う母親、さまざまな人たちが暮らしていた。警備員の目を盗んで、壁に落書きをする者もいたな。",
            ["DialogueId"] = 90200503,
            ["GUID"] = "E1CEB806",
            ["NextDialogue"] = 90200504,
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_3",
            },
        [90200504] = {
            ["Content"] = "这就是我们的盖雷亚剧院。它站在那儿，听着这些声音，但又听不懂这些声音。",
            ["ContentJP"] = "それが僕たちのガレア劇場だ。 劇場はそこに在り、それらの声に耳を傾けるが、理解することはない。",
            ["DialogueId"] = 90200504,
            ["GUID"] = "E1CEB830",
            ["NextDialogue"] = 90200505,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_4",
            },
        [90200505] = {
            ["Content"] = "那，那里有什么关于你自己的回忆吗？",
            ["ContentJP"] = "君自身のそこでの思い出は？",
            ["DialogueId"] = 90200505,
            ["GUID"] = "E1CEB85A",
            ["NextDialogue"] = 90200506,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81103:Confident_End",
                },
            },
        [90200506] = {
            ["Content"] = "……不知为什么，我第一个想起的不是各种剧本，不是花哨的戏服和首饰，甚至不是每天打扫的小道具间。",
            ["ContentJP"] = "……なぜだか、真っ先に思い出したのは、様々な脚本でも、派手な衣装やアクセサリーでも、毎日掃除をしていた小さな道具部屋でもなかった。",
            ["DialogueId"] = 90200506,
            ["GUID"] = "E1CEB884",
            ["NextDialogue"] = 90200507,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_5",
            },
        [90200507] = {
            ["Content"] = "我想起的是演出落幕后，舞台上那袭薄绒毯。小时候，记忆里的第一场演出结束后，我和母亲在那儿重复着剧里的唱词，跳了整夜的舞。",
            ["ContentJP"] = "幕引きのあと、舞台に敷かれたあの薄い絨毯が今でも忘れられない。子供の頃、初めての公演が終わったあと、母とそこで劇の歌詞を繰り返し歌い、一晩中踊ったことを思い出すんだ。",
            ["DialogueId"] = 90200507,
            ["GUID"] = "E1CEB8AE",
            ["NextDialogue"] = 90200508,
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Sigh_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_6",
            },
        [90200508] = {
            ["Content"] = "日出时分我累了，就躺在那袭绒毯上，枕着她的两膝，做了一个长长的梦。",
            ["ContentJP"] = "朝日がちらつく頃、疲れた僕は母の両膝に頭をのせ、その絨毯の上で長い夢を見るんだ。",
            ["DialogueId"] = 90200508,
            ["GUID"] = "E1CEB8D8",
            ["NextOptions"] = {
                [1] = 90200002,
                [2] = 90200003,
                },
            ["SpeakNpcId"] = 81103,
            ["TalkActionId"] = {
                [1] = "81103:Sigh_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_topic_05_7",
            ["bForbidSkipOptions"] = true,
            },
        [90200601] = {
            ["Content"] = "你最近过得好吗？\
……抱歉，是我唐突了。我们并不相识，我只是……替一个朋友问问罢了。",
            ["ContentJP"] = "元気にしてたか？\
 ……ごめん、急に。君とは初対面だよ。ただ、友人の代わりに……聞いただけだ。",
            ["DialogueId"] = 90200601,
            ["GUID"] = "E1CEC81A",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_companio_01",
            },
        [90200701] = {
            ["Content"] = "是吗，你现在有了一个新家，也有了会关心照顾你的家人……真是太好了。你逃出了自己的囚笼，是个勇敢的孩子。",
            ["ContentJP"] = "そうか、新しい家と優しい家族ができたのか……本当によかったな。自分の檻から脱出するなんて、君は本当に勇敢な子だ。",
            ["DialogueId"] = 90200701,
            ["GUID"] = "E1CED882",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_companio_02",
            },
        [90200901] = {
            ["Content"] = "你的拟态能力非常特别，哪怕是最优秀的舞台道具师也未必能做出这样精妙绝伦的效果。",
            ["ContentJP"] = "君の擬態力は本当に並外れているね。どんなに優秀な小道具職人でも、これほど精巧に仕上げることはできないだろうね。",
            ["DialogueId"] = 90200901,
            ["GUID"] = "E1CEF952",
            ["SpeakNpcId"] = 81103,
            ["VoiceName"] = "voice/$Locale$/char/Tuosi/vo_companio_04",
            },
        [90210000] = {
            ["Content"] = "有没有什么任务可以安排给我？不，我并非有多喜欢工作，而是……一种惯性吧。如果无法让自己忙碌起来，我总觉得坐立难安。",
            ["ContentJP"] = "何か任務を割り当ててくれない？いえ、別に働くのが好きなわけじゃないけど……習慣というか、やることがないと、どうも落ち着かないの。",
            ["DialogueId"] = 90210000,
            ["GUID"] = "E1D4CE49",
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_idle",
            },
        [90210001] = {
            ["Content"] = "今日据点巡逻结束。未发现危险生物，未发现墙壁开裂，未发现可疑记号，潜在威胁排除，可照例进行日常生活，报告完毕。",
            ["ContentJP"] = "ベースのパトロール完了。危険生物の痕跡なし、塀の損傷なし、すべて異常なしーー警戒体制を解除し、日常活動を承認する。以上。",
            ["DialogueId"] = 90210001,
            ["GUID"] = "E1D4CE4A",
            ["NextOptions"] = {
                [1] = 902100011,
                [2] = 902100012,
                [3] = 902100013,
                [4] = 902100014,
                [5] = 902100015,
                [6] = 902100016,
                [7] = 902100017,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90210002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90210002,
            ["GUID"] = "90210002.0",
            ["NextDialogue"] = 90210001,
            },
        [90210003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90210003,
            ["GUID"] = "90210003.0",
            },
        [90210101] = {
            ["Content"] = "呃……你注意到了啊，我是有一把亲人留下的口琴。好好地锁了起来，但又总担心它会突然消失不见，所以会时不时，忍不住地去确认一下。",
            ["ContentJP"] = "あ……よく気づいたね。確かにハーモニカを一つ持ってるわ。あれは家族が残してくれたもので――だから鍵をかけて大事に保管してるんだけど、ふと消えてしまうんじゃないかって怖くて……つい何度も確認してしまうの。",
            ["DialogueId"] = 90210101,
            ["GUID"] = "E1D4DEB2",
            ["NextDialogue"] = 90210102,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_1",
            },
        [90210102] = {
            ["Content"] = "那么你一定会很多首曲子啦？",
            ["ContentJP"] = "なら、いろんな曲が弾けるの？",
            ["DialogueId"] = 90210102,
            ["GUID"] = "E1D4DEDC",
            ["NextDialogue"] = 90210103,
            ["SpeakNpcId"] = 100001,
            },
        [90210103] = {
            ["Content"] = "其实只会一首，还是亲人教给我的。我学得也不是很快，因为实在不擅长音乐这样需要情绪起伏的东西……",
            ["ContentJP"] = "実は一曲しか弾けないの。それも家族に教わったものでね。音楽のような感情の起伏が必要なものはどうも苦手で……練習にかなり時間をかけたわ。",
            ["DialogueId"] = 90210103,
            ["GUID"] = "E1D4DF06",
            ["NextDialogue"] = 90210104,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_2",
            },
        [90210104] = {
            ["Content"] = "不过，每当我太过紧张或者太过开心的时候，总会暗暗握住它，这能让我想到很多我确信的事，反而能够让我冷静一些。",
            ["ContentJP"] = "緊張したり興奮するたびに、こっそりそれを握りしめるの。そうすることで、私の決意をたくさん思い出して、却って少し落ち着くの。",
            ["DialogueId"] = 90210104,
            ["GUID"] = "E1D4DF30",
            ["NextDialogue"] = 90210105,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_3",
            },
        [90210105] = {
            ["Content"] = "我的许多同僚会因为压力而去找医生，需要镇定或者兴奋。我不需要那些，心跳快一拍也好慢一拍也罢，口琴会帮找回正常的节拍。",
            ["ContentJP"] = "ストレスにまいった同僚のほとんどは、一時の安らぎや快楽を得るために医者を訪ねるわ。でも私には必要ない。ハーモニカが私の鼓動を正常な拍子に戻してくれるから。",
            ["DialogueId"] = 90210105,
            ["GUID"] = "E1D4DF5A",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90210201] = {
            ["Content"] = "还不错，军团是一个只要努力就能获得回报的地方。我现在受到了认可，拥有几名部下，我还可以命令他们一定要平等对待卡戎之民和索拉之民。",
            ["ContentJP"] = "まあね。あそこは努力が報われる場所だから。今では、部下も数名いる。カロン族とソラ族も平等に扱うよう、命令してるの。",
            ["DialogueId"] = 90210201,
            ["GUID"] = "E1D4EF1A",
            ["NextDialogue"] = 90210202,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_1",
            },
        [90210202] = {
            ["Content"] = "我听过许多人抱怨甚至谩骂军团对于卡戎之民过度严苛，而我能尽可能去缓和这些声音……我希望日子久了，可以让大家眼里的军团变得有那么一点点不一样。",
            ["ContentJP"] = "カロン族の扱いが厳しいという苦情は何度も聞いたわ。私はそれをできるだけ緩和したい……時が経つにつれて、いつか帝国軍に向けられる視線が少しでも変わってくれるといいな。",
            ["DialogueId"] = 90210202,
            ["GUID"] = "E1D4EF44",
            ["NextDialogue"] = 90210203,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_2",
            },
        [90210203] = {
            ["Content"] = "可是像你这样的人还是太少了。",
            ["ContentJP"] = "でも、その考え方は少数派だよね。",
            ["DialogueId"] = 90210203,
            ["GUID"] = "E1D4EF6E",
            ["NextDialogue"] = 90210204,
            ["SpeakNpcId"] = 100001,
            },
        [90210204] = {
            ["Content"] = "会慢慢多起来的，在更早之前军团里连一个卡戎都没有呢。我虽然能做的不多，但是只要我坚持这样教导部下，那么卡戎之民和索拉之民的矛盾就会变少。",
            ["ContentJP"] = "これから少しずつ増やしていけばいい。初期の帝国軍にだって、カロン族はいなかったんだから。私にできることはそんなに多くないわ。でも、部下たちにこの思想を広めていけば、カロン族とソラ族の矛盾も減るはずだと思うの。",
            ["DialogueId"] = 90210204,
            ["GUID"] = "E1D4EF98",
            ["NextDialogue"] = 90210205,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_3",
            },
        [90210205] = {
            ["Content"] = "是的，平等对待所有人，努力保护大家远离秽兽和秽蚀的威胁，就一定能让卡戎们的境遇好上一些，冰湖城里的叹气声也能少一些。",
            ["ContentJP"] = "民を平等に扱い、穢獣や穢蝕（えしょく）の脅威から守り続ければ、カロン族の境遇も少しずつ良くなっていく。アイスレイク城で聞こえるため息も減るって信じているわ。",
            ["DialogueId"] = 90210205,
            ["GUID"] = "E1D4EFC2",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90210301] = {
            ["Content"] = "谈不上负责，我只是严格遵守了卫戍部队规章的所有内容而已。",
            ["ContentJP"] = "責任感というよりも、警備隊の規則を遵守してるだけです。",
            ["DialogueId"] = 90210301,
            ["GUID"] = "E1D4FF82",
            ["NextDialogue"] = 90210302,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_1",
            },
        [90210302] = {
            ["Content"] = "可是其他人好像都不遵守什么规定，横行霸道的。",
            ["ContentJP"] = "でも、他の人は規則をあまり守ってないし、好き勝手やってるよ？",
            ["DialogueId"] = 90210302,
            ["GUID"] = "E1D4FFAC",
            ["NextDialogue"] = 90210303,
            ["SpeakNpcId"] = 100001,
            },
        [90210303] = {
            ["Content"] = "规章规定不允许随意讨论同僚的言行，否则会被视为违背军纪。",
            ["ContentJP"] = "規則に基づけば、同僚の言動を勝手に議論することは禁じられている。それは軍紀に反する行為よ。",
            ["DialogueId"] = 90210303,
            ["GUID"] = "E1D4FFD6",
            ["NextDialogue"] = 90210304,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_2",
            },
        [90210304] = {
            ["Content"] = "不过实话说，我不理解他们是怎么想的，可能觉得卫戍部队就只是一份普通的工作，只要不被上司发现，怎么胡闹都无所谓。",
            ["ContentJP"] = "でも、彼らの考え方を理解できないのは確かよ。警備隊をただのお勤めだと考えてるんだと思う。上役にさえバレなければ、何をしてもいいと思ってるのよ。",
            ["DialogueId"] = 90210304,
            ["GUID"] = "E1D50000",
            ["NextDialogue"] = 90210305,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_3",
            },
        [90210305] = {
            ["Content"] = "我觉得，不应该这样，人应该遵循着固定的规则而活着，否则的话，就会不断放低对自己的要求，过一天算一天，最后只能和下水道里的老鼠混在一起。",
            ["ContentJP"] = "そんなの間違ってる。人は決まった規則にしたがって生きるべきよ。自分を甘やかし、毎日をただやり過ごすだけの人生じゃ、結局下水道のネズミと同じ運命を辿ることになるわ。",
            ["DialogueId"] = 90210305,
            ["GUID"] = "E1D5002A",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90210401] = {
            ["Content"] = "不用了……抱歉，我不太喜欢照镜子。毕竟一眼就能看到头上的角，总觉得有些难受……",
            ["ContentJP"] = "遠慮するわ……申し訳ないけど、鏡を見るのは嫌いなの。どうしても頭に生えた角に目が行っちゃうから……",
            ["DialogueId"] = 90210401,
            ["GUID"] = "E1D50FEA",
            ["NextDialogue"] = 90210402,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_04_1",
            },
        [90210402] = {
            ["Content"] = "原来你不喜欢卡戎之民的外表啊……",
            ["ContentJP"] = "カロン族の姿を嫌ってたんだ……",
            ["DialogueId"] = 90210402,
            ["GUID"] = "E1D51014",
            ["NextDialogue"] = 90210403,
            ["SpeakNpcId"] = 100001,
            },
        [90210403] = {
            ["Content"] = "不，我并非对我们一族的外表自轻自贱。我只是觉得，如果它能长得更规则、更对称一些，也许会看起来舒服很多。啊，不是，我也没有在说你的角……",
            ["ContentJP"] = "いいえ。同族の血を卑下しているわけじゃないわ。ただ、これがもっと規則的で対称だったら、もっとしっくりするのにって思ってしまうの。あ、あなたの角のことを言ってるわけじゃないのよ……",
            ["DialogueId"] = 90210403,
            ["GUID"] = "E1D5103E",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90210501] = {
            ["Content"] = "还在，只是它现在变得好沉重，太沉重了……我不知道自己是否还有力气再次握起它，吹奏下去。",
            ["ContentJP"] = "ええ。ただ、だいぶ重くなったように感じるわ……もう一度それを手に取って演奏する力が、今の私にあるのか……",
            ["DialogueId"] = 90210501,
            ["GUID"] = "E1D52052",
            ["NextDialogue"] = 90210502,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_05_1",
            },
        [90210502] = {
            ["Content"] = "毕竟，这把口琴曾装载了我全部的期待和梦想。",
            ["ContentJP"] = "このハーモニカには私の期待と夢がすべて詰まってたの。",
            ["DialogueId"] = 90210502,
            ["GUID"] = "E1D5207C",
            ["NextDialogue"] = 90210503,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_05_2",
            },
        [90210503] = {
            ["Content"] = "如果有一天你能重新吹起它，让我做你的第一个听众吧。",
            ["ContentJP"] = "もしいつか再び演奏する日が来たら、最初の観客になるよ。",
            ["DialogueId"] = 90210503,
            ["GUID"] = "E1D520A6",
            ["NextDialogue"] = 90210504,
            ["SpeakNpcId"] = 100001,
            },
        [90210504] = {
            ["Content"] = "……我明白了。我答应你，等将来有一天，我能够再次拿起这把口琴，去学习新曲子的时候……一定第一个吹奏给你听。",
            ["ContentJP"] = "……もちろん。いつかまたこのハーモニカを手にして、新しい曲を学ぶ時が来たら……あなたに一番に聞かせるわ。",
            ["DialogueId"] = 90210504,
            ["GUID"] = "E1D520D0",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_05_3",
            ["bForbidSkipOptions"] = true,
            },
        [90210601] = {
            ["Content"] = "我每天都会接到一些零工，够我一个人日常开销和吃穿用度。不过，对现在的我来说，工作与其说是为了糊口，不如说是为了工作本身。",
            ["ContentJP"] = "日雇いのお勤めをいくつか請け負ってるわ。一人で生活する分には十分よ。ただ、今の私の場合、生きるために働いてるっていうより、むしろその逆かな。",
            ["DialogueId"] = 90210601,
            ["GUID"] = "E1D530BA",
            ["NextDialogue"] = 90210602,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_06_1",
            },
        [90210602] = {
            ["Content"] = "为了工作本身？",
            ["ContentJP"] = "その逆って？",
            ["DialogueId"] = 90210602,
            ["GUID"] = "E1D530E4",
            ["NextDialogue"] = 90210603,
            ["SpeakNpcId"] = 100001,
            },
        [90210603] = {
            ["Content"] = "工作让我的生活充实无比，工作让我的心情更加快乐，有工作的日子，太阳都会更暖和一点。",
            ["ContentJP"] = "働くことで、生活が満たされる気になるの――おかげで、気分も少し楽になるわ。お勤めがある日は、日の光すらいつもより暖かく感じるの。",
            ["DialogueId"] = 90210603,
            ["GUID"] = "E1D5310E",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_06_2",
            ["bForbidSkipOptions"] = true,
            },
        [90210701] = {
            ["Content"] = "至少比待在里面要好。军团曾是我安身的庇护所，是我的梦想所在。但是现在梦想成了谎言，我以为的庇护所是让家人万劫不复的地狱……",
            ["ContentJP"] = "あそこにいた時よりはだいぶよくなったわ。あそこはかつて私にとって安らぎの場であり、夢のような場所だった。でも、その夢は嘘となり、信じていた安らぎの場が家族を地獄にたたき落としてしまった……",
            ["DialogueId"] = 90210701,
            ["GUID"] = "E1D54122",
            ["NextDialogue"] = 90210702,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_07_1",
            },
        [90210702] = {
            ["Content"] = "我无法释怀家人的仇，可是我也无法对昔日同僚拔枪相向。我真的不知道……告诉我，我应该怎么办才好？",
            ["ContentJP"] = "家族の仇をうちたい。でも、昔の同僚に銃を向けるなんてできない。頭の中がめちゃくちゃよ……ねえ、私、どうすればいいの？",
            ["DialogueId"] = 90210702,
            ["GUID"] = "E1D5414C",
            ["NextDialogue"] = 90210703,
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_07_2",
            },
        [90210703] = {
            ["Content"] = "我想这个问题只能由你自己回答。",
            ["ContentJP"] = "その質問の答えは、自分にしかわからないよ。",
            ["DialogueId"] = 90210703,
            ["GUID"] = "E1D54176",
            ["NextDialogue"] = 90210704,
            ["SpeakNpcId"] = 100001,
            },
        [90210704] = {
            ["Content"] = "……抱歉，刚才是我失态了。你说得没错，我应该自己找出答案，而不是把问题推给你。虽然，这可能还要花上很长的时间吧……",
            ["ContentJP"] = "……ごめんなさい、取り乱してしまって。あなたのいう通り、他人に問題を押し付けず、自分で答えを見つけないとだよね。たとえ、長い時間をかけることになっても……",
            ["DialogueId"] = 90210704,
            ["GUID"] = "E1D541A0",
            ["NextOptions"] = {
                [1] = 90210002,
                [2] = 90210003,
                },
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_topic_07_3",
            ["bForbidSkipOptions"] = true,
            },
        [90210901] = {
            ["Content"] = "这份计划书上的安排详略得当，精确到秒，逐步完成这些安排想必能获得巨大的满足感。只是……真的很难把这样严密的计划与兰迪长官联系起来。",
            ["ContentJP"] = "この計画書、秒単位でスケジュールが立てられていて、とても素晴らしいです。すべてこなした時の達成感は想像もつきません。ただ……こんな几帳面な計画がランディー長官によるものだなんて、あまり信じられないです。",
            ["DialogueId"] = 90210901,
            ["GUID"] = "E1D561F2",
            ["SpeakNpcId"] = 84101,
            ["VoiceName"] = "voice/$Locale$/char/Lise/vo_companio_02",
            },
        [90220000] = {
            ["Content"] = "在这纷争的土地上，能拥有这么一方安宁天地，享受片刻放松的时光，也不错。",
            ["ContentJP"] = "争いの絶えないこの土地で、こうして静けさに身をゆだねられるひとときがあるのは、悪くないものですね。",
            ["DialogueId"] = 90220000,
            ["GUID"] = "E1DB36E9",
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_idle",
            },
        [90220001] = {
            ["Content"] = "是你呀，亲爱的孩子。日安，有什么事想要讲给我听吗？",
            ["ContentJP"] = "まあ、いらっしゃったのね。ごきげんよう。どうなさいましたの？",
            ["DialogueId"] = 90220001,
            ["GUID"] = "E1DB36EA",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextOptions"] = {
                [1] = 902200011,
                [2] = 902200012,
                [3] = 902200013,
                [4] = 902200014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90220002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90220002,
            ["GUID"] = "90220002.0",
            ["NextDialogue"] = 90220001,
            },
        [90220003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90220003,
            ["GUID"] = "90220003.0",
            },
        [90220101] = {
            ["Content"] = "是的，在漫长的时间中，我在阿特拉西亚的各处旅行——或者流浪。我用双足丈量过这片土地的每一寸刻度，也用手指摩挲过它的每一缕纹理。",
            ["ContentJP"] = "ええ、私は長い歳月をアトラシアで過ごしてきました――旅と言うより、放浪に近いものかもしれません。この大地を隅々まで踏みしめ、その息吹を手で感じながらね。",
            ["DialogueId"] = 90220101,
            ["GUID"] = "E1DB4752",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220102,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_1",
            },
        [90220102] = {
            ["Content"] = "那你最喜欢的地方是哪儿？",
            ["ContentJP"] = "一番好きな場所はどこ？",
            ["DialogueId"] = 90220102,
            ["GUID"] = "E1DB477C",
            ["NextDialogue"] = 90220103,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_End",
                },
            },
        [90220103] = {
            ["Content"] = "如果你走过足够多的地方，会觉得各处的风景并无太多差别。北境的飞雪，赫墨的砂砾，或者华胥的炊烟，无非也是另一种林间的薄雾而已。",
            ["ContentJP"] = "あちこち旅していれば、どこの景色も似たようなものだと気づくでしょう。北境の舞い落ちる雪も、ケメトの砂利も、<Default note=\"text:カショ\">華胥</>に立ち上る炊煙も、結局は、森に漂う霧の化身に過ぎませんわ。",
            ["DialogueId"] = 90220103,
            ["GUID"] = "E1DB47A6",
            ["NextDialogue"] = 90220104,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_2",
            },
        [90220104] = {
            ["Content"] = "如果一定要说个地方的话……那便是伊瑟尔的群山和林地。那里的气息最让我感到安心。",
            ["ContentJP"] = "強いて言えば……イーザーの山々や森でしょうか。あの地に漂う空気に包まれると、不思議と安らぐんです。",
            ["DialogueId"] = 90220104,
            ["GUID"] = "E1DB47D0",
            ["NextDialogue"] = 90220105,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_3",
            },
        [90220105] = {
            ["Content"] = "那我有机会也要去看看。",
            ["ContentJP"] = "今度行ってみるよ。",
            ["DialogueId"] = 90220105,
            ["GUID"] = "E1DB47FA",
            ["NextDialogue"] = 90220106,
            ["SpeakNpcId"] = 100001,
            },
        [90220106] = {
            ["Content"] = "好啊。",
            ["ContentJP"] = "ええ、ぜひ。",
            ["DialogueId"] = 90220106,
            ["GUID"] = "E1DB4824",
            ["NextDialogue"] = 90220107,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_4",
            },
        [90220107] = {
            ["Content"] = "若有一天你去翡翠森林，请帮我带一束白堇致候吧。在那里长眠的啊，是我的友人、我的孩子、以及少时的我。",
            ["ContentJP"] = "いつの日か、エメラルドの森を訪れることがあれば、どうか白いパンジーを一束手向けてくださいませ。そこに眠っているのは、私の友人と子ども、そして幼き日の私なんです。",
            ["DialogueId"] = 90220107,
            ["GUID"] = "E1DB484E",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_01_5",
            ["bForbidSkipOptions"] = true,
            },
        [90220201] = {
            ["Content"] = "雾海是一切生者的来处与归途。万物归于雾海，雾海又孕育新的万物……就像死去的云滴落泥土，鲜花又自泥土中盛开。",
            ["ContentJP"] = "ニヴルヘイムはすべての生命が始まり、そして終わる場所。万物はやがてその地に還り、また新たな命が芽生える……まるで大地に落ちた雲のしずくが、やがて花を咲かせるように。",
            ["DialogueId"] = 90220201,
            ["GUID"] = "E1DB57BA",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220202,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_1",
            },
        [90220202] = {
            ["Content"] = "有一天我也会去往那里吗？",
            ["ContentJP"] = "いつか私もそこに行くってこと？",
            ["DialogueId"] = 90220202,
            ["GUID"] = "E1DB57E4",
            ["NextDialogue"] = 90220203,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81502:Confident_End",
                },
            },
        [90220203] = {
            ["Content"] = "我想是的。终有一天，你会前往雾海，前往茵布拉女神的怀抱。",
            ["ContentJP"] = "ええ、きっとあなたも、いつかはニヴルヘイムに赴き――女神エムブラの安らぎを得られる日が来るでしょう。",
            ["DialogueId"] = 90220203,
            ["GUID"] = "E1DB580E",
            ["NextDialogue"] = 90220204,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_2",
            },
        [90220204] = {
            ["Content"] = "听上去有些可怕……",
            ["ContentJP"] = "なんだか怖くなってきた……",
            ["DialogueId"] = 90220204,
            ["GUID"] = "E1DB5838",
            ["NextDialogue"] = 90220205,
            ["SpeakNpcId"] = 100001,
            },
        [90220205] = {
            ["Content"] = "孩子，请你爱着生的一切，亦不要畏惧消亡。消亡并非苦痛，只是生命必经的终点。",
            ["ContentJP"] = "すべての<Default note=\"text:いのち\">生命</>を愛しなさい。やがて訪れる死を恐れてはいけません。終わりとは苦しみではなく、誰もが辿る道なのですから。",
            ["DialogueId"] = 90220205,
            ["GUID"] = "E1DB5862",
            ["NextDialogue"] = 90220206,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_3",
            },
        [90220206] = {
            ["Content"] = "若你累了，就在我的臂弯中安歇片刻吧……别害怕，这不会是永眠。现在的你，还有太多未竟之事。",
            ["ContentJP"] = "お疲れでしたら、この腕の中でしばしお休みになられてはいかがでしょう……恐れることはありません。永遠の眠りに落ちることなどございませんよ。あなたには、まだ果たすべきことが星の数ほど残っているのですから。",
            ["DialogueId"] = 90220206,
            ["GUID"] = "E1DB588C",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_02_4",
            ["bForbidSkipOptions"] = true,
            },
        [90220301] = {
            ["Content"] = "怎么，这很让你惊讶吗？实不相瞒，在昔日“大迁徙”时，我还曾是一位在前线冲锋陷阵的战士，一位格斗的好手。",
            ["ContentJP"] = "あら、驚かせてしまいました？昔「大移住」の際、私は前線で戦う戦士でございましたのよ。格闘の腕前にも、それなりに自信がございますの。",
            ["DialogueId"] = 90220301,
            ["GUID"] = "E1DB6822",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220302,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_1",
            },
        }
  end },
  { MinKey = 90220302, MaxKey = 101012133, Loader = function()
      return {
        [90220302] = {
            ["Content"] = "虽说那是十分遥远的过去，但基本的战斗技巧，我大体都还记得。",
            ["ContentJP"] = "もう随分遠い昔の話ではございますが、基本的な戦闘技術は覚えておりますわ。",
            ["DialogueId"] = 90220302,
            ["GUID"] = "E1DB684C",
            ["NextDialogue"] = 90220303,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_2",
            },
        [90220303] = {
            ["Content"] = "在旅途中，我也会时不时要与盘桓的兽群搏斗，它们也曾带给我爪痕，淤伤，甚至理当的死亡。",
            ["ContentJP"] = "旅の途中では、獣たちとの衝突は珍しくないことです。爪痕や打撲痕で済むこともあれば、命を脅かすほどの怪我を負ったこともございました。",
            ["DialogueId"] = 90220303,
            ["GUID"] = "E1DB6876",
            ["NextDialogue"] = 90220304,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_3",
            },
        [90220304] = {
            ["Content"] = "好难想象你近身搏斗的样子。",
            ["ContentJP"] = "あなたが接近戦で戦う姿は想像がつかないよ。",
            ["DialogueId"] = 90220304,
            ["GUID"] = "E1DB68A0",
            ["NextDialogue"] = 90220305,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "81502:Talk02_End",
                },
            },
        [90220305] = {
            ["Content"] = "亘古的月亮尚且每天都在变幻，人类当然更加复杂。更何况如我一般，经历过数倍于常人岁月的人呢？",
            ["ContentJP"] = "……永遠に輝く月さえ、毎日その姿を変えるのですから。人間がもっと複雑なのは当然でしょう。まして、私のように、常人の何倍も長く生きてきた者ならなおさら、ね。",
            ["DialogueId"] = 90220305,
            ["GUID"] = "E1DB68CA",
            ["NextDialogue"] = 90220306,
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_4",
            },
        [90220306] = {
            ["Content"] = "若是你对这段过往有兴趣，改日我细细说与你听吧。",
            ["ContentJP"] = "私の過去に興味があるのなら、また別の機会にじっくり話しましょう。",
            ["DialogueId"] = 90220306,
            ["GUID"] = "E1DB68F4",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_03_5",
            ["bForbidSkipOptions"] = true,
            },
        [90220401] = {
            ["Content"] = "“朋友”……以人们对这二字的通常定义来看，我有过很多朋友。",
            ["ContentJP"] = "「友人」……ですか。この世の基準からすれば、私には友人と呼べる存在がたくさんおりました。",
            ["DialogueId"] = 90220401,
            ["GUID"] = "E1DB788A",
            ["LookAt"] = {
                [1] = "81502:n(0)",
                [2] = "0:n(81502)",
                },
            ["NextDialogue"] = 90220402,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_1",
            },
        [90220402] = {
            ["Content"] = "不过，提起这个词，我最先想到的还是莱克西斯和艾瑞卡——就是带我离开艾利西安的那两位朋友。",
            ["ContentJP"] = "ですが、真っ先に思い浮かぶのはレクシスとエリカ――私をエリュシオンから連れ出してくれた、大切な友人たちです。",
            ["DialogueId"] = 90220402,
            ["GUID"] = "E1DB78B4",
            ["NextDialogue"] = 90220403,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_2",
            },
        [90220403] = {
            ["Content"] = "他们是怎样的人？",
            ["ContentJP"] = "どんな人たちだったの？",
            ["DialogueId"] = 90220403,
            ["GUID"] = "E1DB78DE",
            ["NextDialogue"] = 90220404,
            ["SpeakNpcId"] = 100001,
            },
        [90220404] = {
            ["Content"] = "在后世的史书和英雄故事里，他们通常被描述成揭下神明蒙昧的纱幕、将真理带给人们的“智者”，以及为了智者崇奉的真理而牺牲的“英雄”……",
            ["ContentJP"] = "後世の歴史書や英雄物語では、彼らはよく、神々の秘密を暴き、人々に真理をもたらした「賢者」、そして賢者が掲げた真理のために命を捧げた「英雄」として語られています……",
            ["DialogueId"] = 90220404,
            ["GUID"] = "E1DB7908",
            ["NextDialogue"] = 90220405,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_3",
            },
        [90220405] = {
            ["Content"] = "但我常常回忆起他们还仅仅是“莱克西斯”和“艾瑞卡”的时候。",
            ["ContentJP"] = "ですが、私が思い出すのは、彼らがまだ 「レクシス」と 「エリカ」でしかなかった時のことばかりで……",
            ["DialogueId"] = 90220405,
            ["GUID"] = "E1DB7932",
            ["NextDialogue"] = 90220406,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_4",
            },
        [90220406] = {
            ["Content"] = "那时艾瑞卡是个勇敢活泼的姑娘，大家都很喜欢她。莱克西斯虽然头脑很聪明，但有时候太较真，经常突然陷入沉思，所以反而会显得有些迟钝。",
            ["ContentJP"] = "当時のエリカは勇敢で活発な少女で、誰からも愛されていました。一方のレクシスは、頭の回転は速いものの、時々真面目な性格が災いして考え込むことが多く、かえって鈍感に見られることもありました。",
            ["DialogueId"] = 90220406,
            ["GUID"] = "E1DB795C",
            ["NextDialogue"] = 90220407,
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_5",
            },
        [90220407] = {
            ["Content"] = "你还记得什么趣事吗？",
            ["ContentJP"] = "何か面白いことはあったの？",
            ["DialogueId"] = 90220407,
            ["GUID"] = "E1DB7986",
            ["NextDialogue"] = 90220408,
            ["SpeakNpcId"] = 100001,
            },
        [90220408] = {
            ["Content"] = "嗯……有一次，莱克西斯为了某件事去给艾瑞卡道歉，艾瑞卡便随口指着士兵们用来练箭的靶子说，他要是能射中红心就原谅他……",
            ["ContentJP"] = "そうですね……レクシスが何かの理由でエリカに謝罪に行ったことがありました。その時、エリカは冗談交じりに、兵士たちが弓の練習で使う的を指して、「真ん中を射抜けたら許してあげる」って言ったんです……",
            ["DialogueId"] = 90220408,
            ["GUID"] = "E1DB79B0",
            ["NextDialogue"] = 90220409,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_6",
            },
        [90220409] = {
            ["Content"] = "当然，这是一句气话。连士兵都不是每个人都做得到，更何况莱克西斯的双手并不是用来握剑，而是用来书写灵智与真理的。",
            ["ContentJP"] = "もちろん、ほんの気まぐれだったのでしょう。兵士ですら、的の中央を射るのは難しいことですし、レクシスの手は剣を握るためではなく、知恵と真理を書き記すためのものでしたから。",
            ["DialogueId"] = 90220409,
            ["GUID"] = "E1DB79DA",
            ["NextDialogue"] = 90220410,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_7",
            },
        [90220410] = {
            ["Content"] = "但他却把这话当真了，趁士兵们歇息之后，一个人练习了一晚上。",
            ["ContentJP"] = "ですが、彼はその言葉を真に受けてしまったのです。兵士たちが休んだ後、彼は一人夜通しで練習をなさいました。",
            ["DialogueId"] = 90220410,
            ["GUID"] = "E1DB7A04",
            ["NextDialogue"] = 90220411,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_8",
            },
        [90220411] = {
            ["Content"] = "当然，历史不是英雄传说。即使是聪慧如莱克西斯，也有学不会的事。他一直练习到手心被磨出血，艾瑞卡为他包上麻布，也没能射中靶心。",
            ["ContentJP"] = "もちろん、人生は英雄物語のように全てが順調に進むわけではありません。どんなに賢いレクシスでも、どうしても苦手なことはありました。彼は手のひらに血がにじむほど練習を重ねました。最後には、エリカが包帯を巻いてくれたものの、的を射抜くことは叶いませんでした。",
            ["DialogueId"] = 90220411,
            ["GUID"] = "E1DB7A2E",
            ["NextDialogue"] = 90220412,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_9",
            },
        [90220412] = {
            ["Content"] = "呵呵……最开始他们到底是为了什么吵架，我反而记不起来了。真是奇怪……现在回忆起有关他们的事，最先浮现的总是这些微不足道的细节。",
            ["ContentJP"] = "ふふ……そもそも、けんかのきっかけが何だったのか、今となってはもう思い出せません。不思議なものですね……彼らのことを振り返ると、浮かんでくるのはいつも、こんな些細な出来事ばかりです。",
            ["DialogueId"] = 90220412,
            ["GUID"] = "E1DB7A58",
            ["NextDialogue"] = 90220413,
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_10",
            },
        [90220413] = {
            ["Content"] = "听起来是一段非常快乐的时光。",
            ["ContentJP"] = "とても幸せなひと時だったんだね。",
            ["DialogueId"] = 90220413,
            ["GUID"] = "E1DB7A82",
            ["NextDialogue"] = 90220414,
            ["SpeakNpcId"] = 100001,
            },
        [90220414] = {
            ["Content"] = "嗯，是啊。那确实是……非常、非常快乐的日子。只是，已经是很久很久以前的事了。",
            ["ContentJP"] = "ええ、そうですね。あの頃は……本当に、本当に毎日が幸せでした。ただ、もう遠い昔のことです。",
            ["DialogueId"] = 90220414,
            ["GUID"] = "E1DB7AAC",
            ["NextOptions"] = {
                [1] = 90220002,
                [2] = 90220003,
                },
            ["SpeakNpcId"] = 81502,
            ["TalkActionId"] = {
                [1] = "81502:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_topic_04_11",
            ["bForbidSkipOptions"] = true,
            },
        [90220501] = {
            ["Content"] = "人无法真正逃离自己的过去。总有一天，你会需要面对它们……希望到那时，你已经获得了足够与之对抗的力量。",
            ["ContentJP"] = "人は決して自分の過去から逃れることはできません。いつか必ず、向き合わねばならない時が訪れるでしょう……その時には、立ち向かえるだけの力を身につけていることを願っています。",
            ["DialogueId"] = 90220501,
            ["GUID"] = "E1DB88F2",
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_companio_01",
            },
        [90220601] = {
            ["Content"] = "姑娘，你身上有股熟悉的气息，莫不是与我同为旧日之人？",
            ["ContentJP"] = "お嬢さん、あなたから懐かしい気配を感じます。もしかして、私と同じく旧き時代の方なのでは？",
            ["DialogueId"] = 90220601,
            ["GUID"] = "E1DB995A",
            ["SpeakNpcId"] = 81502,
            ["VoiceName"] = "voice/$Locale$/char/Nifu/vo_companio_02",
            },
        [90230000] = {
            ["Content"] = "近来的日程我都让秘书推掉了。这几日，我只想与你待在一起，排却外界纷扰，体会此处的清净——这次是真心诚意，还是另有所图？不妨猜猜看吧。",
            ["ContentJP"] = "最近の予定は全部秘書に調整させたわ。あなたと一緒に世間の喧騒を忘れ、静寂なひと時を過ごしたいの。――さて、これは本心かしら、それとも何か企んでいると思う？じっくり考えるといいわ。",
            ["DialogueId"] = 90230000,
            ["GUID"] = "E1E19F60",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_idle",
            },
        [90230001] = {
            ["Content"] = "你愿意来见我了……你还在生气吗？困惑吗？还是说，你已经对我漠然无动于衷？无妨，现在我们有大把的时间可以一一探讨。",
            ["ContentJP"] = "まあ、会いに来てくれたのね……まだ怒っているの？それとも戸惑っているの？それとも……もう私に対して何も感じなくなってしまった？まあいいわ。これからたっぷり時間があるもの、ゆっくり話をしましょう。",
            ["DialogueId"] = 90230001,
            ["GUID"] = "E1E19F8A",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextOptions"] = {
                [1] = 902300011,
                [2] = 902300012,
                [3] = 902300013,
                [4] = 902300014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90230002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90230002,
            ["GUID"] = "E1E19FB4",
            ["NextDialogue"] = 90230001,
            },
        [90230003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90230003,
            ["GUID"] = "E1E19FDE",
            },
        [90230101] = {
            ["Content"] = "没有什么是不能作为筹码的。区别仅仅在于，你所付出的，能够撬动怎样的回报。",
            ["ContentJP"] = "もちろんよ。違いがあるとすれば――差し出したものが、どれだけの見返りを引き出せるか、ということだけよ。",
            ["DialogueId"] = 90230101,
            ["GUID"] = "E1E1AFF2",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230102,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_1",
            },
        [90230102] = {
            ["Content"] = "就算是性命也没关系吗？",
            ["ContentJP"] = "それが命だとしても？",
            ["DialogueId"] = 90230102,
            ["GUID"] = "E1E1B01C",
            ["NextDialogue"] = 90230103,
            ["SpeakNpcId"] = 100001,
            },
        [90230103] = {
            ["Content"] = "没错。你的性命、我的性命，乃至于芸芸众生，在更高的利益层面上，都只是一枚筹码罢了。",
            ["ContentJP"] = "その通りよ。あなたの命、私の命、その他大勢の命も、より大きな利益の前では、ただの駒に過ぎないわ。",
            ["DialogueId"] = 90230103,
            ["GUID"] = "E1E1B046",
            ["NextDialogue"] = 90230104,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_2",
            },
        [90230104] = {
            ["Content"] = "对于渺小的人类而言，能够用自己仅有的筹码，去偿换欲求之物，未尝不是一件幸事。",
            ["ContentJP"] = "取るに足らない存在である人間にとって、自らのわずかな持ち駒を使って欲望を満たすことができるのは、ある意味では幸せなことなのかもしれないわね。",
            ["DialogueId"] = 90230104,
            ["GUID"] = "E1E1B070",
            ["NextDialogue"] = 90230105,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_3",
            },
        [90230105] = {
            ["Content"] = "讨厌这个答案吗？那就向我证明，我所言非实吧。",
            ["ContentJP"] = "この答えが気に入らないのなら、私の言葉が間違っていると証明してみせてちょうだい。",
            ["DialogueId"] = 90230105,
            ["GUID"] = "E1E1B09A",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90230201] = {
            ["Content"] = "让我想想……不必计较一时得失，多多让利。学会观人、用人，施以恩惠。让他们敬你、重你，但也畏惧于你。",
            ["ContentJP"] = "そうね……目先の損得に囚われず、もっと譲歩してみること、かしら。人を見る目を養い、人を使いこなしなさい。そして恩を施すのよ。人々にあなたを敬わせると同時に、畏れるを抱かされることも忘れてはいけないわ。",
            ["DialogueId"] = 90230201,
            ["GUID"] = "E1E1C05A",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230202,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_02_1",
            },
        [90230202] = {
            ["Content"] = "这和我想的不太一样。",
            ["ContentJP"] = "思ってたのと違うかも。",
            ["DialogueId"] = 90230202,
            ["GUID"] = "E1E1C084",
            ["NextDialogue"] = 90230203,
            ["SpeakNpcId"] = 100001,
            },
        [90230203] = {
            ["Content"] = "呵呵。货物有价，人情无价。锱铢必较者，只能经营足下一隅。学会借助人情的东风，才能飞向更加广阔的天地。",
            ["ContentJP"] = "ふふっ。物には値段がつけられるけれど、人情には値段がつけられないのよ。細かい損得にこだわるようでは、足元の小さな世界でしか生きられないわ。人情という追い風を上手に利用すれば、もっと広い世界へ飛び立つことができるのよ。",
            ["DialogueId"] = 90230203,
            ["GUID"] = "E1E1C0AE",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90230301] = {
            ["Content"] = "我平素多有琐事缠身，很少能真正得空。闲暇二字，于我倒是有些许奢侈。",
            ["ContentJP"] = "普段から雑事に追われていて、時間を持て余したことなんてほとんどないわ。私にとって「暇」という言葉は、少し贅沢な響きよ。",
            ["DialogueId"] = 90230301,
            ["GUID"] = "E1E1D0C2",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230302,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_1",
            },
        [90230302] = {
            ["Content"] = "若是侥幸得了浮生半日闲……我大约会去观戏吧。无论是华胥的说书、评弹，帝国的歌剧、话剧，抑或是远洋新近流行的照影，我都有几分兴致。",
            ["ContentJP"] = "もし運良く束の間の自由が手に入ったなら……そうね、たぶん劇を観に行くわ。華胥の語りや評弾、帝国のオペラや演劇、それに最近遠洋で流行している連鎖劇――どれも興味があるのよ。",
            ["DialogueId"] = 90230302,
            ["GUID"] = "E1E1D0EC",
            ["NextDialogue"] = 90230303,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_2",
            },
        [90230303] = {
            ["Content"] = "原来我们相遇在剧院并非偶然。",
            ["ContentJP"] = "つまり、劇場での出会いは偶然じゃなかったんだね。",
            ["DialogueId"] = 90230303,
            ["GUID"] = "E1E1D116",
            ["NextDialogue"] = 90230304,
            ["SpeakNpcId"] = 100001,
            },
        [90230304] = {
            ["Content"] = "呵呵……是啊。戏剧撷取吉光片羽，却能讲尽人性幽微。人心这东西，说不清，道不明，总是带来意外，又永远教人看不厌。",
            ["ContentJP"] = "ふふ……そうね。舞台はほんの一片を切り取るだけで、人間の奥深さを語り尽くせるのよ。人の心というものは、不思議で曖昧で予想外の連続――だから何度見ても飽きることはないわ。",
            ["DialogueId"] = 90230304,
            ["GUID"] = "E1E1D140",
            ["NextDialogue"] = 90230305,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_3",
            },
        [90230305] = {
            ["Content"] = "今后的日子里，你又会给我带来怎样的意外？我可是拭目以待呢。",
            ["ContentJP"] = "この先、あなたは私にどんな舞台を見せてくれるのかしら？ふふ、楽しみにしているわ。",
            ["DialogueId"] = 90230305,
            ["GUID"] = "E1E1D16A",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90230401] = {
            ["Content"] = "嗯？这也被你注意到了。只是有些老毛病罢了。",
            ["ContentJP"] = "あら？よく気付いたわね。昔のトラウマよ、大したことないわ。",
            ["DialogueId"] = 90230401,
            ["GUID"] = "E1E1E12A",
            ["LookAt"] = {
                [1] = "84102:n(0)",
                [2] = "0:n(84102)",
                },
            ["NextDialogue"] = 90230402,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_1",
            },
        [90230402] = {
            ["Content"] = "我年幼时，曾因一起意外，受困于山洞涧谷中，三天三夜不见天日。大约是从那时起落下的陋习。",
            ["ContentJP"] = "幼い頃、とある事故で山中の洞窟に閉じ込められてしまったの。三日三晩、光ひとつない暗闇で過ごしたわ。たぶんそれが原因だと思う。",
            ["DialogueId"] = 90230402,
            ["GUID"] = "E1E1E154",
            ["NextDialogue"] = 90230403,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_2",
            },
        [90230403] = {
            ["Content"] = "在这世间，为人皆有恐惧之物，我也不能幸免……看你的表情，这让你很惊讶吗？",
            ["ContentJP"] = "誰だって怖いもののひとつやふたつ、あって不思議じゃないわ。私も同じよ。ふふ、その顔……そんなに驚いた？",
            ["DialogueId"] = 90230403,
            ["GUID"] = "E1E1E17E",
            ["NextDialogue"] = 90230404,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_3",
            },
        [90230404] = {
            ["Content"] = "只是觉得，你平时的形象好像没有弱点。",
            ["ContentJP"] = "うん、弱点なんてなさそうなイメージだったから。",
            ["DialogueId"] = 90230404,
            ["GUID"] = "E1E1E1A8",
            ["NextDialogue"] = 90230405,
            ["SpeakNpcId"] = 100001,
            },
        [90230405] = {
            ["Content"] = "呵呵……没错。弱点只会成为商人的绊脚石。",
            ["ContentJP"] = "ふふ……そうね。商人にとって、「弱み」は足枷にしかならないわ。",
            ["DialogueId"] = 90230405,
            ["GUID"] = "E1E1E1D2",
            ["NextDialogue"] = 90230406,
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_4",
            },
        [90230406] = {
            ["Content"] = "我后来针对这点进行了严格的特训。若对面是谈判的对手，我可以随时将这份恐惧抛之脑后。只是在你面前，没有强装的必要罢了。",
            ["ContentJP"] = "だから、克服するために厳しい修行を積んだの。目の前にいるのが取引相手であれば、一瞬で恐怖心を頭から払拭できるわ。でも、あなたの前では……無理をする必要なんてないでしょう？",
            ["DialogueId"] = 90230406,
            ["GUID"] = "E1E1E1FC",
            ["NextOptions"] = {
                [1] = 90230002,
                [2] = 90230003,
                },
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_topic_04_5",
            ["bForbidSkipOptions"] = true,
            },
        [90230501] = {
            ["Content"] = "你身上香水的味道，浓郁、热烈，散发出毫不克制的甜美。与华胥惯用香的疏淡却是有所不同。我很感兴趣。",
            ["ContentJP"] = "あなたの香水の香り、濃厚で情熱的ね。そして抑えの効かない甘さを漂わせているわ。華胥でよく使われる控えめな香りとはまた違っていて、とても興味深いわ。",
            ["DialogueId"] = 90230501,
            ["GUID"] = "E1E1F192",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_companio_01",
            },
        [90230601] = {
            ["Content"] = "我在你身上看见了故人的影子……不，是我多言了。",
            ["ContentJP"] = "あなたに、どこか懐かしい面影を感じたわ……いえ、ただの思い過ごしよ。忘れてちょうだい。",
            ["DialogueId"] = 90230601,
            ["GUID"] = "E1E201FA",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_companio_03",
            },
        [90230701] = {
            ["Content"] = "许久未品过你亲手调的酒了。今日得空，可否再为我浅酌一杯午后小饮？",
            ["ContentJP"] = "あなたが作る酒を味わうのは、随分と久しぶりね。今日は少し時間があるの。午後のひとときを彩る一杯を、また作ってくれるかしら？",
            ["DialogueId"] = 90230701,
            ["GUID"] = "E1E21262",
            ["SpeakNpcId"] = 84102,
            ["VoiceName"] = "voice/$Locale$/char/Zhiliu/vo_companio_04",
            },
        [90240000] = {
            ["Content"] = "这里很是亮堂又宽敞，就是桌椅板凳多了些，否则倒是演武对练的好地方。",
            ["ContentJP"] = "実に日差しが良くて広々とした場所だ。ただ、机や椅子が多すぎるのが玉に瑕だな。そうでなけりゃ、稽古にはもってこいの場所だったんだが。",
            ["DialogueId"] = 90240000,
            ["GUID"] = "E1E80800",
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_idle",
            },
        [90240001] = {
            ["Content"] = "今日宜饮酒纵歌，来来，待我饮完这杯，一起去诛尽那些应杀之人。什么？你说昨天我也是这样说的？那当然，一年三百六十日，日日都宜如此过活。",
            ["ContentJP"] = "今日は酒を飲んで騒ぐにゃうってつけの日だ！さて、この杯を空にしたら、ひと仕事片付けに行くとするか……ん？昨日も同じこと言ってたって？そりゃあそうだろ。こういう生活が一番楽しいからな。",
            ["DialogueId"] = 90240001,
            ["GUID"] = "E1E8082A",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextOptions"] = {
                [1] = 902400011,
                [2] = 902400012,
                [3] = 902400013,
                [4] = 902400014,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90240002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90240002,
            ["GUID"] = "E1E80854",
            ["NextDialogue"] = 90240001,
            },
        [90240003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90240003,
            ["GUID"] = "E1E8087E",
            },
        [90240101] = {
            ["Content"] = "怎么，你也对剑法感兴趣吗？是了，我看你也带着一把好剑，想必是有家传的功夫。比一比就知道啦。",
            ["ContentJP"] = "なかなかいい剣を持ってるじゃないか。あんたも剣術に興味があるのか？もしや流儀を一つや二つ叩き込まれてたり……ま、百聞は一見に如かずってな。ちょっくら腕試ししようぜ。",
            ["DialogueId"] = 90240101,
            ["GUID"] = "E1E81892",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240102,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_1",
            },
        [90240102] = {
            ["Content"] = "老实说，我已经很久没有遇到过势均力敌的对手了。但是按照我师父的说法，我个性太直，不会演戏，还需要继续磨练。",
            ["ContentJP"] = "正直、互角に渡り合えるやつなんて久しぶりだぜ。だが師匠には、素直すぎて駆け引きが下手だってよく言われたもんさ。俺もまだまだ修行が足りねぇな。",
            ["DialogueId"] = 90240102,
            ["GUID"] = "E1E818BC",
            ["NextDialogue"] = 90240103,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_2",
            },
        [90240103] = {
            ["Content"] = "演技也是剑法的一种吗？",
            ["ContentJP"] = "駆け引きも剣術の一部ってこと？",
            ["DialogueId"] = 90240103,
            ["GUID"] = "E1E818E6",
            ["NextDialogue"] = 90240104,
            ["SpeakNpcId"] = 100001,
            },
        [90240104] = {
            ["Content"] = "其实我觉得不是，但是师父有说用剑需要会演：“能而示之不能”，和“不战而屈人之兵”、“以众击寡”一样，都是上等的剑法。",
            ["ContentJP"] = "俺はそうは思わないんだが、師匠は剣の扱いにおいて駆け引きは欠かせないって言ってたよ。「技を隠して妙を成す」、「戦わずして勝つが上策」、「多をもって少を制す」――聞いたことあるだろ？これらと同じで、上等な剣術なんだってさ。",
            ["DialogueId"] = 90240104,
            ["GUID"] = "E1E81910",
            ["NextDialogue"] = 90240105,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Disagree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_3",
            },
        [90240105] = {
            ["Content"] = "我小的时候他就是这样对待我的，说自己本领稀松平常，只要把他打倒在地就可以不用练习之类的话。我试了一年，从没碰到过他的衣袖。",
            ["ContentJP"] = "ガキの頃、あの人はよく言ってたよ。「俺など凡人に過ぎない、俺を倒せばもう稽古はせんでよい」ってな。一年間挑み続けたが、裾すら触れられなかったぜ。",
            ["DialogueId"] = 90240105,
            ["GUID"] = "E1E8193A",
            ["NextDialogue"] = 90240106,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_4",
            },
        [90240106] = {
            ["Content"] = "直到有一天累到趴在地上，看他脚底下连一滴汗都没有。才确信他那副颠颠又倒倒的样子都是演的。",
            ["ContentJP"] = "ある日、疲れ果てて地面に倒れ込んだ時、汗一つかいてないあの人を見て悟ったよ。あのふざけた態度は全部演技だったんだってな。",
            ["DialogueId"] = 90240106,
            ["GUID"] = "E1E81964",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_01_5",
            ["bForbidSkipOptions"] = true,
            },
        [90240201] = {
            ["Content"] = "理由可以举出无数个，但是归根结底无非三个字：我不愿。",
            ["ContentJP"] = "理由なんていくらでもあるが、一言で言やぁ「気に食わねぇから」ってとこだな。",
            ["DialogueId"] = 90240201,
            ["GUID"] = "E1E828FA",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240202,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_1",
            },
        [90240202] = {
            ["Content"] = "从小逍遥自在惯了，只知道路见不平拔刀相助。师父和师兄的话我都只听爱听的，大半当作秋风过耳。又怎么会受什么律法的羁绊。",
            ["ContentJP"] = "子供の頃から気ままに生きてきて、困ってる人を見れば剣を抜いて助ける――それが当たり前だった。師匠や兄弟子の言うことも、都合がいいものは聞くが、あとはほとんど右から左さ。 そんな俺が法令や規則なんざに縛られるわけねぇだろ。",
            ["DialogueId"] = 90240202,
            ["GUID"] = "E1E82924",
            ["NextDialogue"] = 90240203,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Think_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_2",
            },
        [90240203] = {
            ["Content"] = "那说一说最重要的理由吧。",
            ["ContentJP"] = "決め手となる理由は？",
            ["DialogueId"] = 90240203,
            ["GUID"] = "E1E8294E",
            ["NextDialogue"] = 90240204,
            ["SpeakNpcId"] = 100001,
            },
        [90240204] = {
            ["Content"] = "身为剑客的担忧吧：打个比方，习剑的基础是熟记图谱上的一招一式，面对一般的敌人时可以不用多加思索，顷刻间拔剑迎敌。",
            ["ContentJP"] = "剣士としての悩みってやつだな。例えば、剣術の基本は本に書かれた型を体に叩き込むこと。それができりゃ、普通の相手なんざ考える間もなく、一瞬で剣を抜いて迎え撃てるってもんさ。",
            ["DialogueId"] = 90240204,
            ["GUID"] = "E1E82978",
            ["NextDialogue"] = 90240205,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_3",
            },
        [90240205] = {
            ["Content"] = "但太过依赖图谱，不会随机应变，那手中的剑就会变成死剑、呆剑、傻瓜剑。面对未曾谋面的敌人就会方寸大乱，如同呆头鹅。",
            ["ContentJP"] = "だが、本頼りで応用が聞かん者は、その手に握る剣も鈍く愚かな鉄くずになるだけだ。予測不能の事態に出くわしゃ、すぐ頭が真っ白になっちまうのさ。",
            ["DialogueId"] = 90240205,
            ["GUID"] = "E1E829A2",
            ["NextDialogue"] = 90240206,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_4",
            },
        [90240206] = {
            ["Content"] = "在我看来，现在的华胥就是把《大风九章》翻烂的拙剑客，连像我这样的飘零人都斩不尽，要是遇到真正的强敌，是会败的。",
            ["ContentJP"] = "俺から見りゃ、今の<Default note=\"text:カショ\">華胥</>は『<Default note=\"text:タイフウキュウショウ\">大風九章</>』を読み古しただけの不器用な剣士と同じだ。俺みたいな流れ者すら倒せないんじゃ、本当に強い敵に出くわしたら、間違いなく殺られちまうぜ。",
            ["DialogueId"] = 90240206,
            ["GUID"] = "E1E829CC",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_02_5",
            ["bForbidSkipOptions"] = true,
            },
        [90240301] = {
            ["Content"] = "当然了，剑客的意思是擅长用剑，不是只会用剑。否则的话，华胥还有人能拿笔和筷子当做武器，那剑客岂不是不能写字吃饭？",
            ["ContentJP"] = "もちろんさ。剣士ってのは剣術を得意とする者ってだけで、剣しか使えないわけじゃねぇ。<Default note=\"text:カショ\">華胥</>じゃ筆や箸を武器として使う剣士もいるが、そいつらだって文字を書いたり飯を食ったりするだろ？",
            ["DialogueId"] = 90240301,
            ["GUID"] = "E1E83962",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240302,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_03_1",
            },
        [90240302] = {
            ["Content"] = "好遗憾，我还以为你真能做到用剑切开子弹。",
            ["ContentJP"] = "残念……てっきり剣で弾丸を切るとこ見れると思ってたのに。",
            ["DialogueId"] = 90240302,
            ["GUID"] = "E1E8398C",
            ["NextDialogue"] = 90240303,
            ["SpeakNpcId"] = 100001,
            },
        [90240303] = {
            ["Content"] = "我能啊，但能这样做不代表必须这么做，躲开可要比硬接容易多了。山里的野猪都知道能吃萝卜的时候决不去啃树皮呢。",
            ["ContentJP"] = "もちろんできるさ。だが、できるからって必ずしも披露する必要はないだろ？避ける方がよっぽど楽だからな。山ん中のイノシシだって、ニンジンがあるのにわざわざ木の皮をかじりに行ったりしないもんだ。",
            ["DialogueId"] = 90240303,
            ["GUID"] = "E1E839B6",
            ["NextDialogue"] = 90240304,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_03_2",
            },
        [90240304] = {
            ["Content"] = "当然，如果碰见能痛快打上一场的对手，我肯定会拔出剑来，全力以赴。",
            ["ContentJP"] = "もちろん、本気で遣りあえる相手に出会った時は、迷わず剣を抜いて全力で挑むさ。",
            ["DialogueId"] = 90240304,
            ["GUID"] = "E1E839E0",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_03_3",
            ["bForbidSkipOptions"] = true,
            },
        [90240401] = {
            ["Content"] = "确实，你这么一问我能想到不少。啥啥一哥，什么王，某仙之类，用动物来做外号的尤其多，龙虎狮鹤，飞禽走兽都有，非常热闹。",
            ["ContentJP"] = "まあ、言われてみりゃ確かにな。○○の兄貴、○○王、○○仙人……中でも、動物絡みの異名がやたら多いんだよ。龍や虎、獅子に鶴、類を問わず使われてるらしい。まったく賑やかなもんだ。",
            ["DialogueId"] = 90240401,
            ["GUID"] = "E1E849CA",
            ["LookAt"] = {
                [1] = "81503:n(0)",
                [2] = "0:n(81503)",
                },
            ["NextDialogue"] = 90240402,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_1",
            },
        [90240402] = {
            ["Content"] = "然后这些外号啊，往往字数越长，功夫越差。四个字的一看就是刚入门，三个字的有头有脸，两个字，高手。至于没有外号的，那都是大宗师了。",
            ["ContentJP"] = "だがな、こういう異名ってのは文字数が多いやつほど腕が鈍いんだよ。四文字のやつは見るからに新米、三文字ならそれなりに名の通ったやつ、二文字は間違いなく玄人だ。で、異名がないやつはなんだと思う？そいつぁ、まさに達人の域だぜ。",
            ["DialogueId"] = 90240402,
            ["GUID"] = "E1E849F4",
            ["NextDialogue"] = 90240403,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_2",
            },
        [90240403] = {
            ["Content"] = "刻舟是真名还是外号？",
            ["ContentJP"] = "「カシュウ」は本名なの異名なの？",
            ["DialogueId"] = 90240403,
            ["GUID"] = "E1E84A1E",
            ["NextDialogue"] = 90240404,
            ["SpeakNpcId"] = 100001,
            },
        [90240404] = {
            ["Content"] = "行不更名坐不改姓，是真名。我知道你想说这个听起来像是外号。师父也这么说过，说是容易小小年纪就被当做高手，会吃亏。",
            ["ContentJP"] = "俺はいつだって本名を名乗ることにしてる。異名みたいだって思っただろ？師匠にも同じことを言われたよ。文字で書くと二文字でな。「そんな名前じゃ、幼くして玄人扱いされて、痛い目を見るぞ」ってな。",
            ["DialogueId"] = 90240404,
            ["GUID"] = "E1E84A48",
            ["NextDialogue"] = 90240405,
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_3",
            },
        [90240405] = {
            ["Content"] = "可毕竟这个名字是老爹给我起的，可能也是希望我成为一个侠客吧。他留下的东西不多，但只要这个名字还在，就总归证明他在世上还留有剑痕一道。",
            ["ContentJP"] = "だが、この名はおやじがつけてくれたものだからな。きっと、俺に正義を貫く者になってほしいって願いを込めたんだろう。おやじが残してくれたものは多くないが、この名前がある限り、おやじがこの世に刻んだ剣の軌跡は消えないって思えるんだ。",
            ["DialogueId"] = 90240405,
            ["GUID"] = "E1E84A72",
            ["NextOptions"] = {
                [1] = 90240002,
                [2] = 90240003,
                },
            ["SpeakNpcId"] = 81503,
            ["TalkActionId"] = {
                [1] = "81503:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_topic_04_4",
            ["bForbidSkipOptions"] = true,
            },
        [90240601] = {
            ["Content"] = "你的旧剑我先代为保管，等你什么时候不再紧锁着眉头哭丧着脸，我就还你。当然，得先比试一场，要是输了，这剑就当你送我了。",
            ["ContentJP"] = "お前の古い剣はしばらく俺が預かってやるよ。いつかそのしかめっ面をやめたら返してやろう。もちろん、その前に一勝負だ。もしお前が負けたら、その剣は俺のもんだってことでいいよな？",
            ["DialogueId"] = 90240601,
            ["GUID"] = "E1E86A9A",
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_companio_02",
            },
        [90240701] = {
            ["Content"] = "剑可以是朋友，可以是玩物，甚至也可以是餐具、撬棍和剃须刀，但是唯独不可以是主人。希望你前行的旅途不要被这柄剑困住。",
            ["ContentJP"] = "剣は友にも、玩具にもなれる。さらには食器やてこ、ヒゲ剃りにだって使える。けどな、主になることだけは許されねぇ。お前の未来がこの剣に縛られねぇことを祈るよ。",
            ["DialogueId"] = 90240701,
            ["GUID"] = "E1E87B02",
            ["SpeakNpcId"] = 81503,
            ["VoiceName"] = "voice/$Locale$/char/Kezhou/vo_companio_03",
            },
        [90250000] = {
            ["Content"] = "萨麦尔，今天外面正艳阳高照呢，那我们吃点凉的怎么样？唔，听说圣都最近有一种叫“冰淇淋”的甜品，莉兹偷偷买给你吧！虽然是平民的食物，但肯定比那些老顽固给的餐点美味很多！",
            ["ContentJP"] = "サマエル、今日は外の日差しが強いし、冷たいものでも食べよっか？\
最近の聖都には「アイスクリーム」っていうデザートがあるみたい。リズがこっそり買ってくるね！庶民の食べ物だけど、絶対あの頑固爺さんたちのご飯よりは美味しいはず！",
            ["DialogueId"] = 90250000,
            ["GUID"] = "E1EE70A0",
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_idle",
            },
        [90250001] = {
            ["Content"] = "你好啊，我在带着萨麦尔呼吸新鲜空气，熟悉这里的氛围和阳光，你要和它打招呼吗？它会很高兴的，嗯嗯，应该会的！",
            ["ContentJP"] = "やっほー、今ね、サマエルとお外の空気を吸ってたの。ここの陽光や雰囲気に慣れてほしくてね！サマエルにも挨拶してみる？きっと喜ぶと思うな。たぶん！",
            ["DialogueId"] = 90250001,
            ["GUID"] = "E1EE70CA",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextOptions"] = {
                [1] = 90250100,
                [2] = 90250200,
                [3] = 90250300,
                [4] = 90250400,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90250002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "別の話にしようか。",
            ["DialogueId"] = 90250002,
            ["GUID"] = "E1EE70F4",
            ["NextDialogue"] = 90250001,
            },
        [90250003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90250003,
            ["GUID"] = "E1EE711E",
            },
        [90250100] = {
            ["Content"] = "你的兵器好像很厉害的样子……",
            ["ContentJP"] = "その武器、なんだか強そうだね……",
            ["DialogueId"] = 90250100,
            ["GUID"] = "E1EE8108",
            ["NextDialogue"] = 90250101,
            },
        [90250101] = {
            ["Content"] = "萨麦尔可不是什么普通兵器，它是我最好的朋友！",
            ["ContentJP"] = "サマエルはただの武器なんかじゃないよ！私の、一番の友だちなんだから！",
            ["DialogueId"] = 90250101,
            ["GUID"] = "E1EE8132",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250102,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_1",
            },
        [90250102] = {
            ["Content"] = "为什么莉兹贝尔会把一把剑当做朋友呢？",
            ["ContentJP"] = "剣が友だちなの？",
            ["DialogueId"] = 90250102,
            ["GUID"] = "E1EE815C",
            ["NextDialogue"] = 90250103,
            ["SpeakNpcId"] = 100001,
            },
        [90250103] = {
            ["Content"] = "在传颂会，只有被七件圣器选中的人才能成为“七美德”。当时有那么多那么多大力士，但只有我能拔出萨麦尔——既然它选择了我，我也一定会好好对待它的！",
            ["ContentJP"] = "礼賛会では、「セブンヴァーチェス」になれるのは七つの聖器に選ばれた人だけ。あのとき、力自慢がいっぱいいたのに、サマエルを引き抜けたのは、あたしだけだったんだよ！選ばれたからには、大事にしなくっちゃでしょ？",
            ["DialogueId"] = 90250103,
            ["GUID"] = "E1EE8186",
            ["NextDialogue"] = 90250104,
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_2",
            },
        [90250104] = {
            ["Content"] = "只是，虽然我拔出了它，但从那天开始，它就再也没有回应过我的呼唤了……等等，这是秘密，绝对不要说出去！",
            ["ContentJP"] = "でもね、あたしがサマエルを引き抜いてから……一回も返事してくれなくなっちゃったの……あっ、これは内緒！絶対に誰にも言っちゃダメだからね！",
            ["DialogueId"] = 90250104,
            ["GUID"] = "E1EE81B0",
            ["NextDialogue"] = 90250105,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_3",
            },
        [90250105] = {
            ["Content"] = "你天天往剑刃上抹奶油，它当然不会回应你。",
            ["ContentJP"] = "毎日剣にクリームを塗ってたら、そりゃ返事してくれないよ。",
            ["DialogueId"] = 90250105,
            ["GUID"] = "E1EE81DA",
            ["NextDialogue"] = 90250106,
            ["SpeakNpcId"] = 100001,
            },
        [90250106] = {
            ["Content"] = "啊？难道它不喜欢冰淇淋？！那……土豆泥怎么样？沙拉酱呢？",
            ["ContentJP"] = "えっ？アイスダメだった！？……じゃあ、マッシュポテトは？それともサラダソース……？",
            ["DialogueId"] = 90250106,
            ["GUID"] = "E1EE8204",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Think_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90250200] = {
            ["Content"] = "艾利西安传颂会的人对你怎么样？",
            ["ContentJP"] = "エリュシオン礼賛会の人ってどんな感じ？",
            ["DialogueId"] = 90250200,
            ["GUID"] = "E1EE9170",
            ["NextDialogue"] = 90250201,
            },
        [90250201] = {
            ["Content"] = "闭嘴闭嘴！别和我提那群老顽固！啊啊，真是的，好好的心情都被你……啊，我不能生气，不能生气……\
",
            ["ContentJP"] = "うっさいうっさい！その頑固ジジイどもの話はやめてよ！ああもう、せっかくのいい気分が……いけない、怒っちゃダメ、怒っちゃ……",
            ["DialogueId"] = 90250201,
            ["GUID"] = "E1EE919A",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250202,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Angry01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_02_1",
            },
        [90250202] = {
            ["Content"] = "听起来你对他们意见很大啊……",
            ["ContentJP"] = "……そんなに嫌いなの？",
            ["DialogueId"] = 90250202,
            ["GUID"] = "E1EE91C4",
            ["NextDialogue"] = 90250203,
            ["SpeakNpcId"] = 100001,
            },
        [90250203] = {
            ["Content"] = "咳咳，才没有呢！司祭们人都好棒的，一个个都特别和蔼可亲的。背错的经文只需要抄三十遍，喂萨麦尔吃奶油被发现也只要面壁思过两天就行了，超喜欢大家的。",
            ["ContentJP"] = "ゴホン、そ、そんなことないし！司祭さまたちはみんなとーっても優しいよ？お経間違えたら三十回書き直すだけだし、サマエルにアイスあげて怒られても、二日間壁に向かって反省すれば許してくれるし？うん、大好きだよ、みんな……",
            ["DialogueId"] = 90250203,
            ["GUID"] = "E1EE91EE",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Angry01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90250300] = {
            ["Content"] = "“坚忍”意味着什么？",
            ["ContentJP"] = "「ペイシェンス」ってどういう意味？",
            ["DialogueId"] = 90250300,
            ["GUID"] = "E1EEA1D8",
            ["NextDialogue"] = 90250301,
            },
        [90250301] = {
            ["Content"] = "就是字面意思啊，“坚忍”就是要坚定、要忍耐，无论遇到什么事都不能生气！",
            ["ContentJP"] = "そのまんまだよ。文字で「堅く忍ぶ」って書くくらいだし、怒らず耐えることが大事って意味！",
            ["DialogueId"] = 90250301,
            ["GUID"] = "E1EEA202",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250302,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_1",
            },
        [90250302] = {
            ["Content"] = "那也太难了吧……",
            ["ContentJP"] = "それって難しくない……？",
            ["DialogueId"] = 90250302,
            ["GUID"] = "E1EEA22C",
            ["NextDialogue"] = 90250303,
            ["SpeakNpcId"] = 100001,
            },
        [90250303] = {
            ["Content"] = "可不是嘛……因为这个称号，我总是被教导要用忍耐去对抗愤怒。可这就像是打哈欠打到一半被人搭话，又或是举剑后被告知眼前的敌人并非敌人而是同伴一样。总之就是，反而会让人更加生……",
            ["ContentJP"] = "だよねぇ……この称号をもらってから、怒りにはぜったい耐えろって教えられてて……でも、これってあくびしてるときに話しかけられたり、剣を構えた瞬間に「その人は味方だ」って言われるのとおんなじ……逆に、もっとムカッとするっていうか……",
            ["DialogueId"] = 90250303,
            ["GUID"] = "E1EEA256",
            ["NextDialogue"] = 90250304,
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_2",
            },
        [90250304] = {
            ["Content"] = "唔，他们说愤怒是很大的罪恶，我不能生气，不能生气……",
            ["ContentJP"] = "……怒りは大罪、怒っちゃダメ……怒っちゃダメ……",
            ["DialogueId"] = 90250304,
            ["GUID"] = "E1EEA280",
            ["NextDialogue"] = 90250305,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_3",
            },
        [90250305] = {
            ["Content"] = "真是辛苦你了。",
            ["ContentJP"] = "……君はえらいね。",
            ["DialogueId"] = 90250305,
            ["GUID"] = "E1EEA2AA",
            ["NextDialogue"] = 90250306,
            ["SpeakNpcId"] = 100001,
            },
        [90250306] = {
            ["Content"] = "哼哼，谁叫我是“坚忍”大人呢！",
            ["ContentJP"] = "ふっふーん、だってあたし、「ペイシェンス」様だもん！",
            ["DialogueId"] = 90250306,
            ["GUID"] = "E1EEA2D4",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Agree",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_03_4",
            ["bForbidSkipOptions"] = true,
            },
        [90250400] = {
            ["Content"] = "“七美德”是什么?",
            ["ContentJP"] = "「セブンヴァーチェス」って何？",
            ["DialogueId"] = 90250400,
            ["GUID"] = "E1EEB240",
            ["NextDialogue"] = 90250401,
            },
        [90250401] = {
            ["Content"] = "“七美德”是艾利西安最威风，最高贵，最强大帅气的七个人。当然，顾名思义，也是美德最丰沛的七个人啦。",
            ["ContentJP"] = "「セブンヴァーチェス」はね、エリュシオンでいっちばんすごくて、いっちばんカッコよくて、いっちばん気高い七人のこと！もちろん、美徳もてんこ盛り！……えへへっ。",
            ["DialogueId"] = 90250401,
            ["GUID"] = "E1EEB26A",
            ["LookAt"] = {
                [1] = "81501:n(0)",
                [2] = "0:n(81501)",
                },
            ["NextDialogue"] = 90250402,
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_04_1",
            },
        [90250402] = {
            ["Content"] = "呃……",
            ["ContentJP"] = "う、うーん……",
            ["DialogueId"] = 90250402,
            ["GUID"] = "E1EEB294",
            ["NextDialogue"] = 90250403,
            ["SpeakNpcId"] = 100001,
            },
        [90250403] = {
            ["Content"] = "你那是什么表情……真是放肆！竟然敢质疑本大人，我要罚你抄写戒律三十……不，一百遍！",
            ["ContentJP"] = "ちょっと！なにその顔！？よくもあたしを疑ったな！？よーし、罰として戒律を30……いや、100回書き写してもらうよ！",
            ["DialogueId"] = 90250403,
            ["GUID"] = "E1EEB2BE",
            ["NextOptions"] = {
                [1] = 90250002,
                [2] = 90250003,
                },
            ["SpeakNpcId"] = 81501,
            ["TalkActionId"] = {
                [1] = "81501:Confident_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_topic_04_2",
            ["bForbidSkipOptions"] = true,
            },
        [90250601] = {
            ["Content"] = "“坚忍，是七大美德之一……心中常存忍耐，就能够见到常人不能见的，行世人难以……难以……”\
啊啊啊不行受不了啦！小矮子你再在那里模仿本大人的样子本大人就要忍不住拿萨麦尔切水产了我以九神之名发誓真的会做到的！！",
            ["ContentJP"] = "「ペイシェンス、セブンヴァーチェスが一席……常に己を律して耐え忍ぶことで、常人に見え得ぬものを瞳に捉え、世の人々に困難な……困難な……」\
ああ、もう我慢できるかぁぁ！こらチビ、これ以上あたしの真似するなら、サマエルでお前のニョロニョロをブッタ斬ってやる！九神の名に誓ってやるったらやるからなぁぁ！",
            ["DialogueId"] = 90250601,
            ["GUID"] = "E1EED33A",
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_companio_02",
            },
        [90250701] = {
            ["Content"] = "抹奶油？怎么啦。我们艾利西安人就是这样保养武器的，有什么意见吗？",
            ["ContentJP"] = "なんで生クリームを塗るのかって？どういう意味よ？これがエリュシオン流の武器のメンテナンスだけど、何か文句でもあるの？",
            ["DialogueId"] = 90250701,
            ["GUID"] = "E1EEE3A2",
            ["SpeakNpcId"] = 81501,
            ["VoiceName"] = "voice/$Locale$/char/Baonu/vo_companio_03",
            },
        [90260000] = {
            ["Content"] = "你一个人在外面……没有我真的可以吗？",
            ["ContentJP"] = "あんた、一人で外に出るの……？ ほんとに、私がいなくても大丈夫なの？",
            ["DialogueId"] = 90260000,
            ["GUID"] = "E1F4D940",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_idle",
            },
        [90260001] = {
            ["Content"] = "你来啦！是不是听说我又重新改装了青鸾贰型，给你看——咦，你只是来找我闲聊的？",
            ["ContentJP"] = "いらっしゃい！聞いたでしょ？また「青鳳二型」をちょっと改造してみたの！ほら、見て見て！ここが――えっ？話しに来ただけですって？ ",
            ["DialogueId"] = 90260001,
            ["GUID"] = "E1F4D96A",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextOptions"] = {
                [1] = 90260100,
                [2] = 90260200,
                [3] = 90260300,
                [4] = 90260400,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90260002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "他の話をしよう。",
            ["DialogueId"] = 90260002,
            ["GUID"] = "E1F4D994",
            ["NextDialogue"] = 90260001,
            },
        [90260003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90260003,
            ["GUID"] = "E1F4D9BE",
            },
        [90260100] = {
            ["Content"] = "闲暇时喜欢做什么？",
            ["ContentJP"] = "暇な時って何してる？",
            ["DialogueId"] = 90260100,
            ["GUID"] = "E1F4E9A8",
            ["NextDialogue"] = 90260101,
            },
        [90260101] = {
            ["Content"] = "拼机枢，打磨齿轮，寻找新材料，研发更好用的东西。",
            ["ContentJP"] = "……まあ、からくり作ったり、ギア磨いたり。新しい素材を探したり……あとは、もっといいの開発したり、かな。",
            ["DialogueId"] = 90260101,
            ["GUID"] = "E1F4E9D2",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260102,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_1",
            },
        [90260102] = {
            ["Content"] = "上次唐叔不是腿摔了吗？刚好最近有空，我就一直在研究能够更平稳升空的载具。机枢派弟子总是要成果不要命，可不能放任这样的风气延续下去！",
            ["ContentJP"] = "ほら、タンさん、足折っちゃったんでしょ？……最近ちょうど時間できたからさ、もっとスムーズに離陸できる乗り物、作れないかなって。今、いろいろ試してるの……もう。機枢派の皆ったら、命より発明を優先しがちでしょ。そういうの、放っておけないのよ。",
            ["DialogueId"] = 90260102,
            ["GUID"] = "E1F4E9FC",
            ["NextDialogue"] = 90260103,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_2",
            },
        [90260103] = {
            ["Content"] = "一直工作不累吗？",
            ["ContentJP"] = "ずっと仕事していて疲れないのか?",
            ["DialogueId"] = 90260103,
            ["GUID"] = "E1F4EA26",
            ["NextDialogue"] = 90260104,
            ["SpeakNpcId"] = 100001,
            },
        [90260104] = {
            ["Content"] = "怎么会累？世上还有比工作最有趣的事吗？你只需要在脑海中把机枢拆解成一个个组件，再在现实中拼起来就好。这简直是最享受的时刻啦。",
            ["ContentJP"] = "まさか、 仕事より面白いものがある？ 頭の中でからくりをバラして、現実でそれを組み立てる。それだけのことよ。 最高のエンターテインメントだと思わない？ ",
            ["DialogueId"] = 90260104,
            ["GUID"] = "E1F4EA50",
            ["NextDialogue"] = 90260105,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk03_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_3",
            },
        [90260105] = {
            ["Content"] = "你要不要也试试？全山外山最厉害的机枢大师现在有空，可以手把手教你哦。",
            ["ContentJP"] = "あんたも試してみない？山外山一のからくりマスターが、手とり足とり教えてあげるわ！",
            ["DialogueId"] = 90260105,
            ["GUID"] = "E1F4EA7A",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk03_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_01_4",
            ["bForbidSkipOptions"] = true,
            },
        [90260200] = {
            ["Content"] = "你之前说过自己辈分高，是什么意思？",
            ["ContentJP"] = "「カシュウの師匠と同格」って言ったけど、一体どういうことなの？",
            ["DialogueId"] = 90260200,
            ["GUID"] = "E1F4FA10",
            ["NextDialogue"] = 90260201,
            },
        [90260201] = {
            ["Content"] = "机枢派和飘零人都讲究世代传承。比方说，一个九十岁的老师父，收了一个十岁的孩子当关门弟子，那么门派里很多四十多岁的中年人都要管这个孩子叫师叔。",
            ["ContentJP"] = "それはね、機枢派も流れ者も世代の伝承をすごく重んじるの。 例えば、90歳の師匠が10歳の子を内弟子に取ったらさ。ほかの弟子が40代であろうと、その子のこと「義叔父」って呼ばなきゃいけないわけ。",
            ["DialogueId"] = 90260201,
            ["GUID"] = "E1F4FA3A",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260202,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_1",
            },
        [90260202] = {
            ["Content"] = "我比较幸运，我的老师——也就是我的姑姑，她辈分很高，所以我的辈分自然也很高啦。",
            ["ContentJP"] = "私の場合は、けっこう運がよかったのよ。だって先生が実の叔母で、しかもその世代が山外山じゃ上のほうだったから。おかげで私まで『大先輩』扱い、ってわけ。 ",
            ["DialogueId"] = 90260202,
            ["GUID"] = "E1F4FA64",
            ["NextDialogue"] = 90260203,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_2",
            },
        [90260203] = {
            ["Content"] = "刻舟就比较不幸，他师父宴山亭辈分低，所以论起排辈啊，他得管我叫姑奶奶~",
            ["ContentJP"] = "それに比べてカシュウは不運だよねー。あいつの師匠――「宴山亭」の世代、下のほうだったでしょ？ だから世代で言うと、カシュウは私のこと「叔母様」って呼ばなきゃいけないの。",
            ["DialogueId"] = 90260203,
            ["GUID"] = "E1F4FA8E",
            ["NextDialogue"] = 90260204,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_3",
            },
        [90260204] = {
            ["Content"] = "那我呢那我呢？",
            ["ContentJP"] = "じゃ私は？",
            ["DialogueId"] = 90260204,
            ["GUID"] = "E1F4FAB8",
            ["NextDialogue"] = 90260205,
            ["SpeakNpcId"] = 100001,
            },
        [90260205] = {
            ["Content"] = "公尚先生的辈分也是很高的哦。让我换算一下……巧了，你和我算是同辈呢！",
            ["ContentJP"] = "コウショウ先生の世代も、けっこう上なんだよね。えっと……ちょっと計算させて……あ、えっ。うそ。あんた、私と同世代じゃん！",
            ["DialogueId"] = 90260205,
            ["GUID"] = "E1F4FAE2",
            ["NextDialogue"] = 90260206,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_4",
            },
        [90260206] = {
            ["Content"] = "嘻嘻，如果以后刻舟那家伙对你耍贫嘴，你就可以尽情让他管你喊{性别：爷爷|奶奶}了。",
            ["ContentJP"] = "ふふ。そうね、もし今度カシュウのやつがあんたに悪ふざけしたら……何回でも{性别:おじい様|おばあ様}って呼ばせてやってもいいわ。",
            ["DialogueId"] = 90260206,
            ["GUID"] = "E1F4FB0C",
            ["NextDialogue"] = 90260207,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_5",
            },
        [90260207] = {
            ["Content"] = "等等，我记得你是白的小仆从来着……意思是她是你师父？……天啊，难道我们中辈分最高的其实是一个小不点吗？！",
            ["ContentJP"] = "ちょ、ちょっと待って、あんたは確かあのスノウちゃんの下僕だっけ…… それはつまり、彼女があんたの師匠ってこと？ …… えっ嘘？！私たちの中で一番上のはあのチビなの？！",
            ["DialogueId"] = 90260207,
            ["GUID"] = "E1F4FB36",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_02_6",
            ["bForbidSkipOptions"] = true,
            },
        [90260300] = {
            ["Content"] = "说起来，最近经常在你身边见到一只小鸟。",
            ["ContentJP"] = "ところでさ、最近よくスーイーの隣に小鳥がいるのを見かけるけど……",
            ["DialogueId"] = 90260300,
            ["GUID"] = "E1F50A78",
            ["NextDialogue"] = 90260301,
            },
        [90260301] = {
            ["Content"] = "哦，那是青鸾叁型，我最新的宠物！",
            ["ContentJP"] = "ああ、あれは「青鳳三型」。私の最新のペットよ!",
            ["DialogueId"] = 90260301,
            ["GUID"] = "E1F50AA2",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260302,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_1",
            },
        [90260302] = {
            ["Content"] = "你看，是不是很像是真的云翎鸥？我简化了发动流程，长按头顶，它就能开启拟态飞行模式了。说到飞行——",
            ["ContentJP"] = "どう、本物のクモハネカモメに見えない? 起動手順を簡略化してあって、頭のてっぺんを長押しするとミミック飛行モードがオンになるの。 で、飛行といえば——",
            ["DialogueId"] = 90260302,
            ["GUID"] = "E1F50ACC",
            ["NextDialogue"] = 90260303,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_2",
            },
        [90260303] = {
            ["Content"] = "这羽毛也是有学问的！我回收了云翎鸥自然掉落的羽毛，用了改良版的离水技艺给羽毛封层，几乎不会增加重量。",
            ["ContentJP"] = "実はこの羽根にも奥深いものがあるのよ! 自然に抜け落ちたクモハネカモメの羽をリサイクルし、改良版の水除去技術で一枚一枚を密封処理したの。これで強度は上がるのに、ほとんど重さが増えないわ。",
            ["DialogueId"] = 90260303,
            ["GUID"] = "E1F50AF6",
            ["NextDialogue"] = 90260304,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_3",
            },
        [90260304] = {
            ["Content"] = "不会掉色，永远毛茸茸，也不是飞天老虎钳，情绪价值拉满，完美的宠物。",
            ["ContentJP"] = "色あせることもなく、いつもふわふわで、癒しと安心感たっぷり！完璧で究極のペットって言っても、過言じゃないわ！ ",
            ["DialogueId"] = 90260304,
            ["GUID"] = "E1F50B20",
            ["NextDialogue"] = 90260305,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Talk01_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_4",
            },
        [90260305] = {
            ["Content"] = "为什么不养只真的？",
            ["ContentJP"] = "なぜ本物のクモハネカモメを飼わないの？",
            ["DialogueId"] = 90260305,
            ["GUID"] = "E1F50B4A",
            ["NextDialogue"] = 90260306,
            ["SpeakNpcId"] = 100001,
            },
        [90260306] = {
            ["Content"] = "云翎鸥是喜欢天空的鸟儿，如果要养，就只能关在笼子里。可是如果我只是为了一饱眼福就把它捉来，那我和昔日的悬衡派有什么区别？",
            ["ContentJP"] = "クモハネカモメは空が好きな鳥なの、飼うってなると結局、檻に入れるしかないでしょ。でもね……目を楽しむためだけに捕まえて、自由を奪うなんて。そんなの、昔の懸衡派と何が違うのよ？",
            ["DialogueId"] = 90260306,
            ["GUID"] = "E1F50B74",
            ["NextDialogue"] = 90260307,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_5",
            },
        [90260307] = {
            ["Content"] = "有些动物适合伴人左右，但云翎鸥显然不在此列。它尖尖的喙，长长的尾，适应风阻的双翼，足以证明——它属于天空，而并非某人的掌心。",
            ["ContentJP"] = "人間の暮らしに慣れる動物もいる、……でも、クモハネカモメは明らかに違うわ。あの尖ったくちばし、長い尾、風に適応した翼――あれは誰かの手のひらじゃなくて、空のものだって証明してる。",
            ["DialogueId"] = 90260307,
            ["GUID"] = "E1F50B9E",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_03_6",
            ["bForbidSkipOptions"] = true,
            },
        [90260400] = {
            ["Content"] = "山外山是个怎样的地方？",
            ["ContentJP"] = "山外山ってどんなところ？",
            ["DialogueId"] = 90260400,
            ["GUID"] = "E1F51AE0",
            ["NextDialogue"] = 90260401,
            },
        [90260401] = {
            ["Content"] = "山外山啊……嗯，好问题。",
            ["ContentJP"] = "山外山か…… いい質問ね。",
            ["DialogueId"] = 90260401,
            ["GUID"] = "E1F51B0A",
            ["LookAt"] = {
                [1] = "81504:n(0)",
                [2] = "0:n(81504)",
                },
            ["NextDialogue"] = 90260402,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_1",
            },
        [90260402] = {
            ["Content"] = "我们因为相似的处境而集结起来，为了相同的目标而努力着，能够互相理解、彼此信任，战斗时交托后背，疲惫时携手同行……是个很好很好的地方。",
            ["ContentJP"] = "……似たような事情を抱えた人たちが集まって、同じ目標のために必死で努力する。その中でお互いを理解して、信頼していく。戦うときは背中を預けられるし、疲れたときは、ちゃんと支え合える。……そういう場所よ。",
            ["DialogueId"] = 90260402,
            ["GUID"] = "E1F51B34",
            ["NextDialogue"] = 90260403,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:AgreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_2",
            },
        [90260403] = {
            ["Content"] = "对于山外山的很多人来说，这里就像是家一样。",
            ["ContentJP"] = "山外山にいる多くの人々にとって、山外山は……家みたいな場所なのよ。",
            ["DialogueId"] = 90260403,
            ["GUID"] = "E1F51B5E",
            ["NextDialogue"] = 90260404,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_3",
            },
        [90260404] = {
            ["Content"] = "这也是你的家吗？",
            ["ContentJP"] = "山外山もスーイーの家なの?",
            ["DialogueId"] = 90260404,
            ["GUID"] = "E1F51B88",
            ["NextDialogue"] = 90260405,
            ["SpeakNpcId"] = 100001,
            },
        [90260405] = {
            ["Content"] = "这……当然也是我家了！",
            ["ContentJP"] = "……も、もちろんよ。山外山は、私にとっても「家」みたいな場所なんだから！！",
            ["DialogueId"] = 90260405,
            ["GUID"] = "E1F51BB2",
            ["NextDialogue"] = 90260406,
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_4",
            },
        [90260406] = {
            ["Content"] = "你好像不太对劲，怎么了？",
            ["ContentJP"] = "なんか変だね、何があったの?",
            ["DialogueId"] = 90260406,
            ["GUID"] = "E1F51BDC",
            ["NextDialogue"] = 90260407,
            ["SpeakNpcId"] = 100001,
            },
        [90260407] = {
            ["Content"] = "好敏锐啊，这就是雇佣兵……不对不对，狩月人的直觉？不只是战斗，接人待物也有用？要是我的机傀探测导航装置，也能和你一样灵活就好了。",
            ["ContentJP"] = "……鋭いわね。これって、傭兵の――……ううん、違う。月狩り人の直感ってやつ？まさか戦闘だけじゃなくて、人付き合いまでこんなに……はぁ。私の「からくり検知・ナビゲーション装置」も、あんたくらい機敏ならいいのに。",
            ["DialogueId"] = 90260407,
            ["GUID"] = "E1F51C06",
            ["NextDialogue"] = 90260408,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Explain02_Start",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_5",
            },
        [90260408] = {
            ["Content"] = "我只是有点迷茫……家应该是一个什么样的地方？",
            ["ContentJP"] = "私は、ただ……少し迷ってるの。「家」って、結局どんな場所なんだろう..... ",
            ["DialogueId"] = 90260408,
            ["GUID"] = "E1F51C30",
            ["NextDialogue"] = 90260409,
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_6",
            },
        [90260409] = {
            ["Content"] = "那是，不管多远都要回去的地方。",
            ["ContentJP"] = "それは、どれだけ遠くへ行っても、そこに戻らなければならない場所なんだ。",
            ["DialogueId"] = 90260409,
            ["GUID"] = "E1F51C5A",
            ["NextDialogue"] = 90260410,
            ["SpeakNpcId"] = 100001,
            },
        [90260410] = {
            ["Content"] = "那……回不去的地方，还算是家吗？……抱歉，让你听了奇怪的话，还是当我没说过吧！",
            ["ContentJP"] = "じゃあ、戻れない場所も……まだ「家」なの？……っ、ごめん。いきなり変なこと聞いた。……い、今の話、やっぱりなし！",
            ["DialogueId"] = 90260410,
            ["GUID"] = "E1F51C84",
            ["NextOptions"] = {
                [1] = 90260002,
                [2] = 90260003,
                },
            ["SpeakNpcId"] = 81504,
            ["TalkActionId"] = {
                [1] = "81504:DisagreeHead",
                },
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_topic_04_7",
            ["bForbidSkipOptions"] = true,
            },
        [90260501] = {
            ["Content"] = "卢卡人都这么开放吗，说话没有三两句，就要拥抱了。不、不行！现在还不可以！",
            ["ContentJP"] = "ルカの人って、そんなにオープンなの……？ 何も言わずに、いきなりハグしようとしてくるし。だ、だめっ！ こ、これ以上は――！",
            ["DialogueId"] = 90260501,
            ["GUID"] = "E1F52B72",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_companio_01",
            },
        [90260601] = {
            ["Content"] = "又要买新剑？！……我们山外山的预算有那么充足吗？不买！跪下求也没用！喊姑奶奶也不行！这次我绝对不会被你说动了！",
            ["ContentJP"] = "また新しい剣を買いたいですって！？……山外山の予算、そんなに余ってると思ってんの？ダメ！買わない！ひざまずいてお願いしても無駄！「叔母さま」って呼んでも駄目！今度こそ、ぜっっっったいに譲・ら・な・いんだからね！",
            ["DialogueId"] = 90260601,
            ["GUID"] = "E1F53BDA",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_companio_02",
            },
        [90260701] = {
            ["Content"] = "你的翅膀……真漂亮，不过我的也不差。要不要来比比谁飞得快？",
            ["ContentJP"] = "あんたの翼……本当に綺麗ね。でも、私のも悪くないわ。 ねぇ、どっちの方が速いか勝負しない? ",
            ["DialogueId"] = 90260701,
            ["GUID"] = "E1F54C42",
            ["SpeakNpcId"] = 81504,
            ["VoiceName"] = "voice/$Locale$/char/Suyi/vo_companio_03",
            },
        [90270000] = {
            ["Content"] = "烈酒要越纯粹越好，如果掺杂了太多味道，就会掩盖原本的芳香，人也是一样的。",
            ["ContentJP"] = "（軽く匂いを嗅ぐ）強めなお酒は混じり気がないほど上物なの。色々な味が混ざると本来の香りが薄れてしまうから……人も、案外それと同じなのかもしれないわね。",
            ["DialogueId"] = 90270000,
            ["GUID"] = "E1FB41E0",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_idle",
            },
        [90270001] = {
            ["Content"] = "叫醒我的是生意，叫醒你的是什么？",
            ["ContentJP"] = "私を目覚めさせるはビジネスだけど……あなたを目覚めさせるのは、何かしら？",
            ["DialogueId"] = 90270001,
            ["GUID"] = "E1FB420A",
            ["NextOptions"] = {
                [1] = 90270100,
                [2] = 90270200,
                [3] = 90270300,
                [4] = 90270400,
                },
            ["RandomOptionNum"] = 3,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_welcome",
            ["bForbidSkipOptions"] = true,
            },
        [90270002] = {
            ["Content"] = "聊点别的",
            ["ContentJP"] = "他の話をしよう。",
            ["DialogueId"] = 90270002,
            ["GUID"] = "E1FB4234",
            ["NextDialogue"] = 90270001,
            },
        [90270003] = {
            ["Content"] = "再见",
            ["ContentJP"] = "それじゃあ、また。",
            ["DialogueId"] = 90270003,
            ["GUID"] = "E1FB425E",
            },
        [90270100] = {
            ["Content"] = "水仙平原那几个大酒桶是干什么用的？",
            ["ContentJP"] = "アスフォデロスにたくさん酒樽があるけど、何に使ってるの{性别:か|}？",
            ["DialogueId"] = 90270100,
            ["GUID"] = "E1FB5248",
            ["NextDialogue"] = 90270101,
            },
        [90270101] = {
            ["Content"] = "酒桶？那自然是用来装美酒的。“冰湖往事”爽口，“军团狼血”浓烈，华胥运来的“苍龙醉”清冽悠长，卢卡的“假面舞会”由十种口味混合而成，每个人品出来的味道都不一样。",
            ["ContentJP"] = "あの酒樽？ふふ、もちろんお酒を眠らせてるのよ。「アイスフォルクテイル」は澄んだ雪解けみたいに喉をすべり、「帝国軍の狼血（レギオンブラッド）」は熱く鋭く、舌に痕を残す。華胥から運ばせた「蒼龍酔」は、氷のように冷たくて……けれど、ひとたび染みれば、なかなか醒めてくれないの。それからルッカの「マスカレード」。十の味が交じり合って、飲む人によって違う味を見せる……不思議なお酒よ。",
            ["DialogueId"] = 90270101,
            ["GUID"] = "E1FB5272",
            ["NextDialogue"] = 90270102,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_1",
            },
        [90270102] = {
            ["Content"] = "怎么，你也打算来一杯？",
            ["ContentJP"] = "一杯、いかが？",
            ["DialogueId"] = 90270102,
            ["GUID"] = "E1FB529C",
            ["NextDialogue"] = 90270103,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_2",
            },
        [90270103] = {
            ["Content"] = "别装傻了，我敲过，那些酒桶一直是空的。",
            ["ContentJP"] = "いやいや、叩いて確かめたけどあの酒樽、ずっと空っぽじゃないか。",
            ["DialogueId"] = 90270103,
            ["GUID"] = "E1FB52C6",
            ["NextDialogue"] = 90270104,
            ["SpeakNpcId"] = 100001,
            },
        [90270104] = {
            ["Content"] = "……呵呵，你聪明了许多，早就不像初来冰湖城那样懵懂无知。",
            ["ContentJP"] = "……ふふ、随分賢くなったわね。もうあの頃の、何も知らない旅人さんの影はないわ。",
            ["DialogueId"] = 90270104,
            ["GUID"] = "E1FB52F0",
            ["NextDialogue"] = 90270105,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_3",
            },
        [90270105] = {
            ["Content"] = "冰湖城往北走一百多公里，翻越维德弗尼尔山脉，便是峡湾地埃斯加特——传说中卡戎之民真正的故乡。",
            ["ContentJP"] = "アイスレイク城から北へ百キロあまり。ヴィドフニル山脈を越えたその先に「アースガルド」と呼ばれる地があるの——伝説では、そこがカロン族の本当の故郷だと言われているのよ。",
            ["DialogueId"] = 90270105,
            ["GUID"] = "E1FB531A",
            ["NextDialogue"] = 90270106,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_4",
            },
        [90270106] = {
            ["Content"] = "对于很多冰湖城的卡戎之民来说，隔着一百多公里，一座高山……应许之地也并非远不可及，不是吗？",
            ["ContentJP"] = "アイスレイク城に生きるカロンにとって、百キロの距離と山ひとつ……その向こうの約束の地は、手の届かない夢なんかじゃない。——そう思わない？",
            ["DialogueId"] = 90270106,
            ["GUID"] = "E1FB5344",
            ["NextDialogue"] = 90270107,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_5",
            },
        [90270107] = {
            ["Content"] = "难道你在帮他们偷渡……",
            ["ContentJP"] = "まさか……カミラさん、彼らの密航を手引きしてるの{性别:か|}？",
            ["DialogueId"] = 90270107,
            ["GUID"] = "E1FB536E",
            ["NextDialogue"] = 90270108,
            ["SpeakNpcId"] = 100001,
            },
        [90270108] = {
            ["Content"] = "嘘——我可什么都没有说哦。",
            ["ContentJP"] = "しーっ……私は何も言ってないわよ？",
            ["DialogueId"] = 90270108,
            ["GUID"] = "E1FB5398",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_01_6",
            ["bForbidSkipOptions"] = true,
            },
        [90270200] = {
            ["Content"] = "“水仙平原”撑起了冰湖城狩月人这样一个职业，真了不起。",
            ["ContentJP"] = "アスフォデロスがあってこそ、アイスレイク城に月狩り人なんて職が成り立ってるんだね……すごいよ。",
            ["DialogueId"] = 90270200,
            ["GUID"] = "E1FB62B0",
            ["NextDialogue"] = 90270201,
            },
        [90270201] = {
            ["Content"] = "承蒙缪赞。狩月人的历史比我这间酒馆古老得多，他们需要一个地方谈谈天，吹吹牛，交换一下彼此手里的“生意”，就算没有“水仙平原”，也会有“铃兰平原”，“郁金香平原”。",
            ["ContentJP"] = "ふふ、ありがとう。でもね、月狩り人の歴史はうちの酒場よりずっと古いの。彼らは昔から、誰かと語らい、虚勢を張り合いながら、「取引き」を交わす場所を求めてきた。「アスフォデロス」じゃなかったとしても、きっとそのうち別の寄り合い所ができてたでしょうね。",
            ["DialogueId"] = 90270201,
            ["GUID"] = "E1FB62DA",
            ["NextDialogue"] = 90270202,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_02_1",
            },
        [90270202] = {
            ["Content"] = "至于最终他们为什么汇集到我这儿来……无非是好喝的酒，作为中间人的公道无欺，以及人们困窘时给出的一点小恩小惠罢了。",
            ["ContentJP"] = "ふふ、どうして皆ここに集まってくるのかって？理由なんて、単純なものよ——口当たりのいいお酒と、仲介役としての公正。それから……困ってる人に、そっと差し出す小さな手。ただ、それだけよ。",
            ["DialogueId"] = 90270202,
            ["GUID"] = "E1FB6304",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_02_2",
            ["bForbidSkipOptions"] = true,
            },
        [90270300] = {
            ["Content"] = "金钱对人们究竟意味着什么呢？",
            ["ContentJP"] = "……お金って人にとって結局、なんなんだろうね。",
            ["DialogueId"] = 90270300,
            ["GUID"] = "E1FB7318",
            ["NextDialogue"] = 90270301,
            },
        [90270301] = {
            ["Content"] = "比起问我，问你自己不是更加合适吗？我还记得你初来冰湖城时无处可去的窘境，你应该很明白，钱是在世间立足的根本。",
            ["ContentJP"] = "私に聞くより、まずは自分に問いかけたらどうかしら？——アイスレイク城に来たばかりの頃、行き場もなくて戸惑ってた、あの姿……今でも覚えてるわ。あなたなら、わかるでしょう？この世で足場を築くには、金こそがいちばん確かな土台よ。",
            ["DialogueId"] = 90270301,
            ["GUID"] = "E1FB7342",
            ["NextDialogue"] = 90270302,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_03_1",
            },
        [90270302] = {
            ["Content"] = "我没有忘记，缺钱的时候确实很困难。",
            ["ContentJP"] = "忘れてなんかない。金がない時の苦しさは、よく知ってる。",
            ["DialogueId"] = 90270302,
            ["GUID"] = "E1FB736C",
            ["NextDialogue"] = 90270303,
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_03_2",
            },
        [90270303] = {
            ["Content"] = "只要积累财富，即使无法改变出身，也会获得勇气对抗命运，即使周遭都是风雨，也能给自己买上一瓶酒暖暖身子，甚至能给别人分上一口，赚个人情。",
            ["ContentJP"] = "たとえ生まれは変えられなくても、財を蓄えれば、運命に立ち向かう勇気は手に入る。嵐の中にいても、自分のために一杯の酒を買って、体を温めることができるし……ときにはその一口を誰かに分けて、ちょっとした借りを作ることだって、できるのよ。",
            ["DialogueId"] = 90270303,
            ["GUID"] = "E1FB7396",
            ["NextDialogue"] = 90270304,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_03_3",
            },
        [90270304] = {
            ["Content"] = "你说，钱是不是很重要？",
            ["ContentJP"] = "ねえ……お金って、大事だと思わない？",
            ["DialogueId"] = 90270304,
            ["GUID"] = "E1FB73C0",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["bForbidSkipOptions"] = true,
            },
        [90270400] = {
            ["Content"] = "关于带我来冰湖城的神秘人，你还知道些什么？",
            ["ContentJP"] = "私をアイスレイク城に連れてき「あの人」について……どこまで知ってるの{性别:か|}？",
            ["DialogueId"] = 90270400,
            ["GUID"] = "E1FB8380",
            ["NextDialogue"] = 90270401,
            },
        [90270401] = {
            ["Content"] = "很遗憾，我在冰湖城待了这么多年，但那人我也是第一次瞧见。他把自己裹在一身斗篷里，说话也是用的变声器。从哪儿来的，是男是女，多大年纪……一概不知。",
            ["ContentJP"] = "残念だけど……私も何も知らないわ。アイスレイク城で長く過ごしてるけど、あの人は全身を深いフードで覆ってて、声も機械で歪めてた。どこから来たのか、男か女か、歳すらもわからない。正体は——まるで霧の中よ。",
            ["DialogueId"] = 90270401,
            ["GUID"] = "E1FB83AA",
            ["NextDialogue"] = 90270402,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_1",
            },
        [90270402] = {
            ["Content"] = "我唯一可以确认的便是他的力量深不可测。只是短暂的交手，我便知绝无胜算。",
            ["ContentJP"] = "ただ、あの人の力は……底が知れない。ほんの一瞬、ほんのひと手合わせしただけでわかったわ——勝ち目なんて、微塵もないってね。",
            ["DialogueId"] = 90270402,
            ["GUID"] = "E1FB83D4",
            ["NextDialogue"] = 90270403,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_2",
            },
        [90270403] = {
            ["Content"] = "想不到你会这么谦虚。",
            ["ContentJP"] = "へえ……まさか、あなたがそんなに謙虚だとは思わなかったよ。",
            ["DialogueId"] = 90270403,
            ["GUID"] = "E1FB83FE",
            ["NextDialogue"] = 90270404,
            ["SpeakNpcId"] = 100001,
            },
        [90270404] = {
            ["Content"] = "呵呵，对生意人来说，最重要的就是盘清自己和对方手里分别捏着多少价码，只有你们手里的价码差不多时，虚张声势才有意义。这种利弊，我还是看得清。",
            ["ContentJP"] = "ふふ……商売人にとっていちばん大事なのは、自分と相手が、どれだけの札を握ってるかを見極めること。持ち札が釣り合ってはじめて、駆け引きってものは意味を持つ。そういう損得勘定だけは、見る目があると思う。",
            ["DialogueId"] = 90270404,
            ["GUID"] = "E1FB8428",
            ["NextDialogue"] = 90270405,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_3",
            },
        [90270405] = {
            ["Content"] = "对了，我想起来了，那人离开前说了一句话——",
            ["ContentJP"] = "そうそう……今、ふと思い出したわ。あの人、去り際に——こう言ったのよ。",
            ["DialogueId"] = 90270405,
            ["GUID"] = "E1FB8452",
            ["NextDialogue"] = 90270406,
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_4",
            },
        [90270406] = {
            ["Content"] = "他说，他希望从你那里得到的，是一个“答案”。",
            ["ContentJP"] = "あなたから「答え」を得たい、とね。",
            ["DialogueId"] = 90270406,
            ["GUID"] = "E1FB847C",
            ["NextOptions"] = {
                [1] = 90270002,
                [2] = 90270003,
                },
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_topic_04_5",
            ["bForbidSkipOptions"] = true,
            },
        [90270601] = {
            ["Content"] = "每个人的天赋不同，有些人生来就拥有治愈人心的能力，就像你，好孩子。",
            ["ContentJP"] = "人にはそれぞれ違った才能があって、中には心を癒す力を持って生まれてくる子もいる。あなたのようにね……本当にいい子。",
            ["DialogueId"] = 90270601,
            ["GUID"] = "E1FBA47A",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_companio_01",
            },
        [90270701] = {
            ["Content"] = "难得你会大老远跑来冰湖城。这次是想要什么帝国特产物资？还是只是打算听场戏？",
            ["ContentJP"] = "ここまで足を運ぶなんて珍しいわね。さて今回のお目当ては、帝国の珍しい物資かしら？それとも、舞台の幕開けを見にきたの？",
            ["DialogueId"] = 90270701,
            ["GUID"] = "E1FBB4E2",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_companio_02",
            },
        [90270801] = {
            ["Content"] = "这伤疤……你难道又接了危险的任务？……唉，我店里有药，你自己去涂点，毕竟在这里出事会影响我做生意。怎么，傻站在这是想让我亲自给你去拿？",
            ["ContentJP"] = "——その傷……また危ない仕事を引き受けたのね？あーあー……うちの店に薬があるから持っていきなさい。ここに居座られたらお店の邪魔だからね。なにをぼーっとしてるの？まさか私に持ってこいって言うつもりかしら？",
            ["DialogueId"] = 90270801,
            ["GUID"] = "E1FBC54A",
            ["SpeakNpcId"] = 83202,
            ["VoiceName"] = "voice/$Locale$/char/Kami/vo_companio_03",
            },
        [100365691] = {
            ["DialogueId"] = 100365691,
            ["DialoguePanelType"] = "None",
            ["Duration"] = 3,
            ["GUID"] = "100365691",
            ["GraphPath"] = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036571.T_Story_Recall_10036571'",
