            },
        [101054211] = {
            ["Content"] = "行吧。",
            ["ContentJP"] = "わかった。",
            ["DialogueId"] = 101054211,
            ["GUID"] = "101054211",
            ["NextDialogue"] = 10105425,
            },
        [101054212] = {
            ["Content"] = "口说无凭，我要怎么相信你？",
            ["ContentJP"] = "そんな口先だけの話、信じられると思う{性别:か|}？",
            ["DialogueId"] = 101054212,
            ["GUID"] = "101054212",
            ["NextDialogue"] = 10105422,
            },
        [101058131] = {
            ["Content"] = "她又不是你的女儿。",
            ["ContentJP"] = "別にあなたの娘ってわけでもない{性别:だろう|でしょう}に。",
            ["DialogueId"] = 101058131,
            ["GUID"] = "101058131",
            ["NextDialogue"] = 10105814,
            },
        [101058132] = {
            ["Content"] = "你对所有人都这样礼貌吗？",
            ["ContentJP"] = "誰に対してもそんな態度なんですか？",
            ["DialogueId"] = 101058132,
            ["GUID"] = "101058132",
            ["NextDialogue"] = 10105815,
            },
        [101063031] = {
            ["Content"] = "你不想让白听到？",
            ["ContentJP"] = "スノウに聞かれたくなかった？",
            ["DialogueId"] = 101063031,
            ["GUID"] = "101063031",
            ["NextDialogue"] = 10106304,
            },
        [101063032] = {
            ["Content"] = "你不想让赛琪听到？",
            ["ContentJP"] = "サイキに聞かれたくなかった？",
            ["DialogueId"] = 101063032,
            ["GUID"] = "101063032",
            ["NextDialogue"] = 10106305,
            },
        [101063245] = {
            ["Content"] = "如果恩里克真的有什么阴谋，相比怀疑，我更担心恩里克会对她不利。她不会做坏事……我相信我的直觉。",
            ["ContentJP"] = "もしヘンリックが本当に何かを企んでいるとして。{性别:僕|私}は企みそのものより、サイキが巻き込まれてしまわないか心配{性别:だ|}……{性别:僕|私}は自分の直感を信じてる。あの子は悪いことをする人間じゃない。",
            ["DialogueId"] = 101063245,
            ["ExStoryInfo"] = "Player",
            ["GUID"] = "194CD3A2",
            ["NextDialogue"] = 10106325,
            ["SpeakNpcId"] = 100001,
            ["TalkActionId"] = {
                [1] = "100001:Explain02_End",
                },
            ["VoiceName"] = "voice/$Locale$/story/1002/101063/194CD3A2",
            },
        [101068021] = {
            ["Content"] = "请过目。",
            ["ContentJP"] = "どうぞご確認を。",
            ["DialogueId"] = 101068021,
            ["GUID"] = "101068021",
            ["NextDialogue"] = 10106803,
            },
        [101070021] = {
            ["Content"] = "谢谢你，赛琪。不过，我从奥特赛德那里把绮晶讨了回来。",
            ["ContentJP"] = "ありがとう、サイキ。でもそうじゃなくて、アウトサイダーからジェムを取り返した{性别:んだ|の}。",
            ["DialogueId"] = 101070021,
            ["GUID"] = "101070021.0",
            ["NextDialogue"] = 10107003,
            },
        [101070031] = {
            ["Content"] = "我讲了个故事把他感动哭了。 ",
            ["ContentJP"] = "{性别:僕|私}が身の上話を語ったら胸を打ったみたいで。",
            ["DialogueId"] = 101070031,
            ["GUID"] = "101070031",
            ["ImprPlusId"] = 1009,
            ["NextDialogue"] = 10107004,
            },
        [101070032] = {
            ["Content"] = "他回城路上摔断了腿，现在在家嗷嗷乱叫。",
            ["ContentJP"] = "あの人、街に帰る途中で転んで脚を折ったみたい。今頃、家でうめいてると思う。",
            ["DialogueId"] = 101070032,
            ["GUID"] = "101070032",
            ["ImprPlusId"] = 1010,
            ["NextDialogue"] = 10107006,
            },
        [101070071] = {
            ["Content"] = "这里的住客看起来有些……无精打采。",
            ["ContentJP"] = "ここで宿泊しているお客さんたち……なんだか元気がないように見える{性别:な|ね}？",
            ["DialogueId"] = 101070071,
            ["GUID"] = "101070071.0",
            ["NextDialogue"] = 10107008,
            },
        [101070131] = {
            ["Content"] = "恩里克先生平常主要什么时候在家？",
            ["ContentJP"] = "ヘンリックさんって普段、何時ごろ家にいるのかな？",
            ["DialogueId"] = 101070131,
            ["GUID"] = "101070131",
            ["NextDialogue"] = 10107014,
            },
        [101070171] = {
            ["Content"] = "你还好吗？",
            ["ContentJP"] = "あれからサイキは大丈夫だった？",
            ["DialogueId"] = 101070171,
            ["GUID"] = "101070171",
            ["NextDialogue"] = 10107018,
            },
        [101070291] = {
            ["Content"] = "谢谢你，是很漂亮的花。",
            ["ContentJP"] = "ありがとう、きれいな花{性别:だ|}ね。",
            ["DialogueId"] = 101070291,
            ["GUID"] = "101070291.0",
            ["NextDialogue"] = 10107030,
            },
        [101071031] = {
            ["Content"] = "这么说不就让人更好奇了吗。",
            ["ContentJP"] = "そう言われるとますます気になるな。",
            ["DialogueId"] = 101071031,
            ["GUID"] = "101071031",
            ["NextDialogue"] = 10107104,
            },
        [101071032] = {
            ["Content"] = "你在这里做什么？",
            ["ContentJP"] = "ここで何をしているの？",
            ["DialogueId"] = 101071032,
            ["GUID"] = "101071032.0",
            ["NextDialogue"] = 10107106,
            },
        [101071051] = {
