            ["DialogueId"] = 101073021,
            ["GUID"] = "101073021.0",
            ["NextDialogue"] = 10107303,
            },
        [101073041] = {
            ["Content"] = "是你自己说话太大声了……",
            ["ContentJP"] = "声が大きかったから……",
            ["DialogueId"] = 101073041,
            ["GUID"] = "101073041.0",
            ["NextDialogue"] = 10107305,
            },
        [101073051] = {
            ["Content"] = "我们聊聊“亨特”吧。他去了哪里？",
            ["ContentJP"] = "その「ハンター」って人のことを教えてほしいな。どこに行っちゃった{性别:んだ|の}？",
            ["DialogueId"] = 101073051,
            ["GUID"] = "101073051",
            ["NextDialogue"] = 10107306,
            },
        [101073071] = {
            ["Content"] = "抱歉，我这就走。",
            ["ContentJP"] = "ごめん、悪かった、もう行くから。",
            ["DialogueId"] = 101073071,
            ["GUID"] = "101073071.0",
            ["NextDialogue"] = 10107308,
            },
        [101078021] = {
