            ["NextDialogue"] = 10107808,
            },
        [101078111] = {
            ["Content"] = "恩里克绝大部分时间都在宅邸内，但有一个例外。",
            ["ContentJP"] = "ヘンリックは基本的に屋敷でずっと過ごしているみたい{性别:なんだ|}。ただし例外がある{性别:|の}。",
