            ["ContentJP"] = "飲み過ぎはよくないよ。",
            ["DialogueId"] = 101291023,
            ["GUID"] = "101291023",
            },
        [101292021] = {
            ["Content"] = "格雷姆废矿怎么？",
            ["ContentJP"] = "グルビューム廃坑がどうしたの？",
            ["DialogueId"] = 101292021,
            ["GUID"] = "101292021",
            ["NextDialogue"] = 10129204,
            },
        [101292022] = {
