            ["DialogueId"] = 101292022,
            ["GUID"] = "101292022",
            ["NextDialogue"] = 10129208,
            },
        [101292023] = {
            ["Content"] = "你是谁？",
            ["ContentJP"] = "あなたは誰……？",
            ["DialogueId"] = 101292023,
            ["GUID"] = "101292023",
            ["NextDialogue"] = 10129211,
            },
        [101292024] = {
            ["Content"] = "再见。",
            ["ContentJP"] = "バイバイ。",
            ["DialogueId"] = 101292024,
            ["GUID"] = "101292024",
            },
