        [120013301] = {
            ["Content"] = "询问止流感受",
            ["ContentJP"] = "シリュウに感想を聞く",
            ["DialogueId"] = 120013301,
            ["GUID"] = "120013301.0",
            ["NextDialogue"] = 12001331,
            },
        [120013321] = {
            ["Content"] = "保持沉默",
            ["ContentJP"] = "沈黙する",
            ["DialogueId"] = 120013321,
            ["GUID"] = "120013321.0",
            ["NextDialogue"] = 12001333,
            },
        [120013351] = {
            ["Content"] = "没有比生命更加珍贵的事物。",
            ["ContentJP"] = "命より大切なものなんてないよ。",
            ["DialogueId"] = 120013351,
            ["GUID"] = "120013351.0",
            ["NextDialogue"] = 12001336,
            },
        [120013352] = {
            ["Content"] = "如果他们能够得偿所愿……或许也是值得的。",
            ["ContentJP"] = "もし彼らが願いを叶えられるのなら……それは価値があるのかもしれないね。",
            ["DialogueId"] = 120013352,
            ["GUID"] = "120013352.0",
            ["NextDialogue"] = 12001336,
            },
        [120017101] = {
            ["Content"] = "夸赞白很厉害。",
            ["ContentJP"] = "スノウをすごいと褒める。",
            ["DialogueId"] = 120017101,
            ["GUID"] = "120017101.0",
            ["NextDialogue"] = 12001711,
            },
        [120017111] = {
            ["Content"] = "指出白战斗时总是躲在自己身后。",
            ["ContentJP"] = "戦闘中スノウは常に自分の後ろに隠れていることを指摘する。",
            ["DialogueId"] = 120017111,
            ["GUID"] = "120017111.0",
            ["NextDialogue"] = 12001712,
            },
        [120017451] = {
            ["Content"] = "赞美白。",
            ["ContentJP"] = "スノウを褒める",
            ["DialogueId"] = 120017451,
            ["GUID"] = "120017451.0",
            ["NextDialogue"] = 12001746,
            },
        [120017461] = {
            ["Content"] = "表示自己一个人也能找到方法。",
            ["ContentJP"] = "自分一人でもなんとかなると伝える。",
            ["DialogueId"] = 120017461,
            ["GUID"] = "120017461.0",
            ["NextDialogue"] = 12001747,
            },
        [120017641] = {
            ["DialogueId"] = 120017641,
            ["Duration"] = 5,
            ["GUID"] = "120017641.0",
            ["IsBlack"] = 1,
            ["NextDialogue"] = 12001764,
            ["Scripts"] = "PlayNormalSound{EventKey{\"carplay\"},EventPath{\"event:/sfx/common/story/yinru/carplay\"},PlayAs2D{true}}",
            ["TalkActionId"] = {
                [1] = "220025:Talk01_End",
                },
            },
        [120018011] = {
            ["Content"] = "询问另一处的“嫌犯”是什么情况。",
            ["ContentJP"] = "別の場所に現れた「容疑者」について聞く。",
            ["DialogueId"] = 120018011,
            ["GUID"] = "120018011.0",
            ["NextDialogue"] = 12001802,
            },
        [120018041] = {
            ["Content"] = "询问止流为什么会出现在这里。",
            ["ContentJP"] = "シリュウがどうしてここに現れたのか聞く。",
            ["DialogueId"] = 120018041,
            ["GUID"] = "120018041.0",
            ["NextDialogue"] = 12001805,
            },
        [120100131] = {
            ["Content"] = "还好。",
            ["ContentJP"] = "ううん、ぜんぜん。",
            ["DialogueId"] = 120100131,
            ["GUID"] = "120100131.0",
            ["NextDialogue"] = 12010014,
            },
        [120100132] = {
            ["Content"] = "是有点。",
            ["ContentJP"] = "ちょっとね。",
            ["DialogueId"] = 120100132,
            ["GUID"] = "120100132.0",
            ["NextDialogue"] = 12010014,
            },
        [120101151] = {
            ["Content"] = "那怎么好意思……",
            ["ContentJP"] = "さすがにそれは申し訳ないよ……",
            ["DialogueId"] = 120101151,
            ["GUID"] = "120101151.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12010116,
            },
        [120101152] = {
            ["Content"] = "真的？我能买到那个百年春破产！",
            ["ContentJP"] = "ほんとに？百年春を破産させちゃおっかな！",
            ["DialogueId"] = 120101152,
            ["GUID"] = "120101152.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12010116,
            },
        [120101231] = {
            ["Content"] = "有很多铺子的商人？",
            ["ContentJP"] = "お店をたくさん持ってる……大商人とか？",
            ["DialogueId"] = 120101231,
            ["GUID"] = "120101231.0",
            ["NextDialogue"] = 12010124,
            },
        [120101232] = {
            ["Content"] = "难道……和我想的不一样？",
            ["ContentJP"] = "あれ……もしかして、思ってたのと違う。",
            ["DialogueId"] = 120101232,
            ["GUID"] = "120101232.0",
            ["NextDialogue"] = 12010124,
            },
        [120101281] = {
            ["Content"] = "那怎么好意思……",
            ["ContentJP"] = "さすがにそれは申し訳ないよ……",
            ["DialogueId"] = 120101281,
            ["GUID"] = "120101281.0",
            ["NextDialogue"] = 12010129,
            },
        [120101282] = {
            ["Content"] = "我就不客气了！",
            ["ContentJP"] = "じゃあ、遠慮なく！",
            ["DialogueId"] = 120101282,
            ["GUID"] = "120101282.0",
            ["NextDialogue"] = 12010129,
            },
        [120102101] = {
            ["Content"] = "世界第一的大魔王早上总是赖床？",
            ["ContentJP"] = "世界一の魔王様ねぇ、毎朝寝坊してるのに？",
            ["DialogueId"] = 120102101,
            ["GUID"] = "120102101.0",
            ["NextDialogue"] = 12010211,
            },
        [120102102] = {
            ["Content"] = "世界第一的大魔王打架时总是躲在我身后？",
            ["ContentJP"] = "世界一の魔王様ねぇ、毎回何かあると真っ先に逃げるのに？",
            ["DialogueId"] = 120102102,
            ["GUID"] = "120102102.0",
            ["NextDialogue"] = 12010211,
            },
        [120102111] = {
            ["Content"] = "我一开始就在了。",
            ["ContentJP"] = "最初から。",
            ["DialogueId"] = 120102111,
            ["GUID"] = "120102111.0",
            ["NextDialogue"] = 12010212,
            },
        [120102112] = {
            ["Content"] = "也就是刚刚到。",
            ["ContentJP"] = "今来たばかりだよ。",
            ["DialogueId"] = 120102112,
            ["GUID"] = "120102112.0",
            ["NextDialogue"] = 12010212,
            },
        [120103091] = {
            ["Content"] = "还是正事要紧。",
            ["ContentJP"] = "気にしないでください。",
            ["DialogueId"] = 120103091,
            ["GUID"] = "120103091.0",
            ["NextDialogue"] = 12010310,
            },
        [120103092] = {
            ["Content"] = "真是遗憾，您要走了吗……",
            ["ContentJP"] = "残念です。どうしても行くんですか……",
            ["DialogueId"] = 120103092,
            ["GUID"] = "120103092.0",
            ["NextDialogue"] = 12010310,
            },
        [120104121] = {
            ["Content"] = "惩罚恶人？狴犴似乎并不是普通猛兽。",
            ["ContentJP"] = "悪者を罰する存在……狴犴、ただの獣ではないようだね。",
            ["DialogueId"] = 120104121,
            ["GUID"] = "120104121.0",
            ["ImprPlusId"] = 1203,
            ["NextDialogue"] = 12010413,
            },
        [120104122] = {
            ["Content"] = "这么厉害，可以抱一只回冰湖城养吗？",
            ["ContentJP"] = "すごいね。アイスレイク城に一匹連れて行ってもいい？",
            ["DialogueId"] = 120104122,
            ["GUID"] = "120104122.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12010414,
            },
        [120104291] = {
            ["Content"] = "夫人根基，定文为信。",
            ["ContentJP"] = "人の根、信に立つ。",
            ["DialogueId"] = 120104291,
            ["GUID"] = "120104291.0",
            ["NextDialogue"] = 12010432,
            },
        [120104292] = {
            ["Content"] = "毁约背盟，不可为也。",
            ["ContentJP"] = "誓いを破り、盟を背くこと、為すべからず。",
            ["DialogueId"] = 120104292,
            ["GUID"] = "120104292.0",
            ["NextDialogue"] = 12010432,
            },
        [120104401] = {
            ["Content"] = "应该不会吧？",
            ["ContentJP"] = "違うと思う。",
            ["DialogueId"] = 120104401,
            ["GUID"] = "120104401.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12010441,
            },
        [120104402] = {
            ["Content"] = "瞒了你很久。其实我就是飏，我没死，只是被困在海伯利亚帝国。",
            ["ContentJP"] = "ずっと黙っててごめん。私は……ほんとはヤンだ。死んでなんてなくて、ずっとヒュペリア帝国に閉じ込められていたんだ。",
            ["DialogueId"] = 120104402,
            ["GUID"] = "120104402.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12010441,
            },
        [120105101] = {
            ["Content"] = "感谢对方。",
            ["ContentJP"] = "ありがとう。",
            ["DialogueId"] = 120105101,
            ["GUID"] = "120105101.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12010511,
            },
        [120105102] = {
            ["Content"] = "表示自己一个人也能解决。",
            ["ContentJP"] = "一人でも解決できたよ。",
            ["DialogueId"] = 120105102,
            ["GUID"] = "120105102.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12010511,
            },
        [120109041] = {
            ["Content"] = "道上的朋友？",
            ["ContentJP"] = "顔の利く友人？",
            ["DialogueId"] = 120109041,
            ["GUID"] = "120109031.0",
            ["NextDialogue"] = 12010905,
            },
        [120109042] = {
            ["Content"] = "是“有点危险的朋友”吗？",
            ["ContentJP"] = "……いわゆる「ちょっと危ないお友だち」ってやつですか？",
            ["DialogueId"] = 120109042,
            ["GUID"] = "120109032.0",
            ["NextDialogue"] = 12010905,
            },
        [120120031] = {
            ["Content"] = "皎皎之民，白。",
            ["ContentJP"] = "{性别:ルーナ族のスノウだ。|ルーナ族のスノウよ。}",
            ["DialogueId"] = 120120031,
            ["GUID"] = "120120031.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12012005,
            },
        [120120032] = {
            ["Content"] = "纯白的救赎☆光之魔王大人！",
            ["ContentJP"] = "純白の救い手☆そして光の魔王様だよ！",
            ["DialogueId"] = 120120032,
            ["GUID"] = "120120032.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12012007,
            },
        [120126041] = {
            ["Content"] = "我是海伯利亚来的狩月人。",
            ["ContentJP"] = "ヒュペリアから来た月狩り人だよ。",
            ["DialogueId"] = 120126041,
            ["GUID"] = "120126041.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12012607,
            },
        [120126042] = {
            ["Content"] = "我是你{性别：爷爷|奶奶}！",
            ["ContentJP"] = "{性别:兄貴|姉御}って呼べ！",
            ["DialogueId"] = 120126042,
            ["GUID"] = "120126042.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12012607,
            },
        [120127101] = {
            ["Content"] = "猛虎。",
            ["ContentJP"] = "虎に決まってる。",
            ["DialogueId"] = 120127101,
            ["GUID"] = "120127101.0",
            ["NextDialogue"] = 12012711,
            },
        [120127102] = {
            ["Content"] = "羊群。",
            ["ContentJP"] = "羊たちに決まってる。",
            ["DialogueId"] = 120127102,
            ["GUID"] = "120127102.0",
            ["NextDialogue"] = 12012712,
            },
        [120127103] = {
            ["Content"] = "侠义之士。",
            ["ContentJP"] = "義士に決まってる。",
            ["DialogueId"] = 120127103,
            ["GUID"] = "120127103.0",
            ["NextDialogue"] = 12012713,
            },
        [120127104] = {
            ["Content"] = "够了，我不想和你玩智力游戏。",
            ["ContentJP"] = "もういい、あなたと知恵比べをする気はない。",
            ["DialogueId"] = 120127104,
            ["GUID"] = "120127104.0",
            ["NextDialogue"] = 12012714,
            },
        [120131061] = {
            ["Content"] = "她是我的朋友。",
            ["ContentJP"] = "友人だよ。",
            ["DialogueId"] = 120131061,
            ["GUID"] = "120131061.0",
            ["NextDialogue"] = 12013107,
            },
        [120131062] = {
            ["Content"] = "她是路见不平救下来的人。",
            ["ContentJP"] = "道端で理不尽な目に遭ってたところを、助けたんだ。",
            ["DialogueId"] = 120131062,
            ["GUID"] = "120131062.0",
            ["NextDialogue"] = 12013107,
            },
        [120131141] = {
            ["Content"] = "你调理了我的身体，送给你是应当的。",
            ["ContentJP"] = "体の調子を整えてくれたんだ、笛くらい……お安い御用だよ。",
            ["DialogueId"] = 120131141,
            ["GUID"] = "120131141.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12013115,
            },
        [120131142] = {
            ["Content"] = "如果是对你来说很重要的人。",
            ["ContentJP"] = "あなたにとって大切な人に関わるものなら。",
            ["DialogueId"] = 120131142,
            ["GUID"] = "120131142.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12013116,
            },
        [120131143] = {
            ["Content"] = "世上没有免费的午餐！",
            ["ContentJP"] = "タダってわけにはいかないよ！世の中そんなに甘くない！",
            ["DialogueId"] = 120131143,
            ["GUID"] = "120131143.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12013117,
            },
        [120131211] = {
            ["Content"] = "我是{nickname}，这位皎皎叫做白。",
            ["ContentJP"] = "{性别:僕|私}は{nickname}、こっちのルーナはスノウだよ。",
            ["DialogueId"] = 120131211,
            ["GUID"] = "120131211.0",
            ["NextDialogue"] = 12013125,
            },
        [120131212] = {
            ["Content"] = "我是骁勇的独目勇者，冷酷的冰湖之主，第一代下水道公爵。",
            ["ContentJP"] = "我こそは剛猛な片目の勇者かつ冷酷なアイスレイクの主である初代下水道公爵なり！",
            ["DialogueId"] = 120131212,
            ["GUID"] = "120131212.0",
            ["NextDialogue"] = 12013122,
            },
        [120134311] = {
            ["Content"] = "呜呼哀哉……",
            ["ContentJP"] = "ああ……なんと嘆かわしい……",
            ["DialogueId"] = 120134311,
            ["GUID"] = "1E130CF8",
            ["NextDialogue"] = 12013432,
            ["SnapShot"] = "ECHO",
            ["SpeakNpcName"] = "UI_Npc_Name_Wenhao",
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130CF8",
            },
        [120134351] = {
            ["Content"] = "（声音好像是从那个方向传来的……）",
            ["ContentJP"] = "(声はあっちの方からだ)",
            ["DialogueId"] = 120134351,
            ["GUID"] = "1E130A2F",
            ["SnapShot"] = "HEART",
            ["SpeakNpcId"] = 100001,
            ["VoiceName"] = "voice/$Locale$/story/1201/120134/1E130A2F",
            },
        [120134391] = {
            ["Content"] = "告诉白刚刚听到的声音。",
            ["ContentJP"] = "声のことを話す。",
            ["DialogueId"] = 120134391,
