            ["NextDialogue"] = 12015509,
            },
        [120186141] = {
            ["Content"] = "他们也不是故意的。",
            ["ContentJP"] = "彼らもわざとじゃないよ。",
            ["DialogueId"] = 120186141,
            ["GUID"] = "120186141.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12018616,
            },
        [120186142] = {
            ["Content"] = "罚他们三天工资！",
            ["ContentJP"] = "三日の減給で勘弁してあげな！",
            ["DialogueId"] = 120186142,
            ["GUID"] = "120186142.0",
            ["ImprPlusId"] = 1205,
            ["NextDialogue"] = 12018619,
            },
        [120193051] = {
            ["Content"] = "幸会幸会……原来华胥之外的地方，还有如此拉风的职业！相逢即是有缘，何不结伴一程？",
            ["ContentJP"] = "どうもどうも……それにしても、<Default note=\"text:カショ\">華胥</>の外にはこんなイカした職業があったのか！せっかくだし、一緒に旅でもするか？",
            ["DialogueId"] = 120193051,
            ["GUID"] = "120193050",
            ["NextDialogue"] = 12019307,
            ["SpeakNpcId"] = 210021,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/120193050",
            },
        [120193141] = {
            ["Content"] = "哦哦……！原来如此！难怪我以随身的枪戟剑林将此地翻来覆去轰了几遍，都没能撼动分毫……竟是要敲击这里。话说回来，这机枢派的造物可真结实。",
            ["ContentJP"] = "こんにちは。",
            ["DialogueId"] = 120193141,
            ["GUID"] = "1E16CD3A",
            ["NextDialogue"] = 12019316,
            ["VoiceName"] = "voice/$Locale$/story/1201/120193/1E16CD3A",
            },
        [120223281] = {
            ["Content"] = "我不想看着华胥陷入祸乱，我想看看有什么我能做的。",
            ["ContentJP"] = "華胥が災禍に沈むのを、黙って見ていたくない。何かできることがあるはずだ。",
            ["DialogueId"] = 120223281,
            ["GUID"] = "120223281.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12022329,
            },
        [120223282] = {
            ["Content"] = "今天实在是发生了太多事情，我只想回冰湖城……",
            ["ContentJP"] = "今日は本当に色々あった……もう、アイスレイク城に戻りたい……",
            ["DialogueId"] = 120223282,
            ["GUID"] = "120223282.0",
            ["ImprPlusId"] = 1201,
            ["NextDialogue"] = 12022329,
            },
        [120230021] = {
            ["Content"] = "感觉那个人有点可怜……",
            ["ContentJP"] = "あの人、ちょっと可哀そう……",
            ["DialogueId"] = 120230021,
            ["GUID"] = "120230021.0",
            ["ImprPlusId"] = 1204,
            ["NextDialogue"] = 12023003,
            },
        [120230022] = {
            ["Content"] = "虽然他的想法可能有错，但也不应该这样对待他。",
            ["ContentJP"] = "確かに考え方は良くないけど、あんな風に扱うのは……",
            ["DialogueId"] = 120230022,
            ["GUID"] = "120230022.0",
            ["ImprPlusId"] = 1202,
            ["NextDialogue"] = 12023003,
            },
        [120230023] = {
            ["Content"] = "为了防止人心动摇，适当的手段也是应该的。",
