            },
        [200005261] = {
            ["Content"] = "（便宜的价格，令人心动。）",
            ["ContentJP"] = "（安くしてくれるなら、ありがたい）",
            ["DialogueId"] = 200005261,
            ["GUID"] = "200005261",
