            ["NextDialogue"] = 20000533,
            },
        [200005262] = {
            ["Content"] = "（无事献殷勤，令人不安。）",
            ["ContentJP"] = "（わけもなく親切なのは、あやしい）",
            ["DialogueId"] = 200005262,
            ["GUID"] = "200005262.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 20000528,
            },
        [200006051] = {
            ["Content"] = "皎皎之民是一群怎样的人？",
            ["ContentJP"] = "ルーナ族ってどんな一族？",
            ["DialogueId"] = 200006051,
            ["GUID"] = "200006051",
            ["NextDialogue"] = 20000606,
            },
        [200006151] = {
            ["Content"] = "是是。您说的对！",
            ["ContentJP"] = "はいはい、仰せのままに。",
            ["DialogueId"] = 200006151,
            ["GUID"] = "200006151",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20000619,
            },
        [200006152] = {
            ["Content"] = "你说的那个军团长给开多少工钱啊？",
            ["ContentJP"] = "軍団長の給料はいくらもらえるの{性别:かな|}？",
            ["DialogueId"] = 200006152,
            ["GUID"] = "200006152",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 20000618,
            },
        [200008091] = {
            ["Content"] = "（留意到她有些无精打采——她好像有什么心事。）",
            ["ContentJP"] = "（サイキはなんだか元気がない――何か悩みがあるようだ）",
            ["DialogueId"] = 200008091,
            ["GUID"] = "200008091",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20000810,
            },
        [200008092] = {
            ["Content"] = "（留意到她刚才在照看的花——她刚才似乎就是对着这些花叹气。）",
            ["ContentJP"] = "（サイキが手入れしていた花を見てみる。彼女はこの花に向かってため息をついていたようだ）",
            ["DialogueId"] = 200008092,
            ["GUID"] = "200008092.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 20000811,
            },
        [200008093] = {
            ["Content"] = "一般来说休息没什么用，出去找点乐子就精神了。",
            ["ContentJP"] = "部屋で休むより、外で遊んだほうが元気がでるよ。",
            ["DialogueId"] = 200008093,
            ["GUID"] = "200008093.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 20000812,
            },
        [200008161] = {
            ["Content"] = "这盆花有点无精打采的。",
            ["ContentJP"] = "少し元気がないみたいだね。",
            ["DialogueId"] = 200008161,
            ["GUID"] = "200008161.0",
            ["NextDialogue"] = 20000817,
            },
        [200008162] = {
            ["Content"] = "花开得很好！",
            ["ContentJP"] = "きれいに咲いているよ！",
            ["DialogueId"] = 200008162,
            ["GUID"] = "200008162.0",
            ["NextDialogue"] = 20000818,
            },
        [200008201] = {
            ["Content"] = "（描述花的颜色。）",
            ["ContentJP"] = "（花の色について語る）",
            ["DialogueId"] = 200008201,
            ["GUID"] = "200008201.0",
            ["NextDialogue"] = 20000821,
            },
        [200008202] = {
            ["Content"] = "（描述花的形态。）",
            ["ContentJP"] = "（花の様子について語る）",
            ["DialogueId"] = 200008202,
            ["GUID"] = "200008202.0",
            ["NextDialogue"] = 20000823,
            },
        [200008203] = {
            ["Content"] = "（描述花瓣的细节。）",
            ["ContentJP"] = "（花びらの細かな部分について語る）",
            ["DialogueId"] = 200008203,
            ["GUID"] = "200008203.0",
            ["NextDialogue"] = 20000827,
            },
        [200008341] = {
            ["Content"] = "（安慰她。再坚韧的花也是娇贵的植物，枯萎是很平常的事。）",
            ["ContentJP"] = "（丈夫な品種だとしても植物は繊細だから、枯れることもあるとサイキを慰める）",
            ["DialogueId"] = 200008341,
            ["GUID"] = "200008341",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20000835,
            },
        [200008342] = {
            ["Content"] = "（让她仔细回想一下，除了照料手法，还有没有什么和之前不一样的。）",
            ["ContentJP"] = "（両親の栽培方法とどこか違う点はないかサイキに聞いてみる）",
            ["DialogueId"] = 200008342,
            ["GUID"] = "200008342",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 20000836,
            },
        [200008411] = {
            ["Content"] = "（你对“特别的土壤”也有些兴趣。）",
            ["ContentJP"] = "（「特別な土」に少し興味がある）",
            ["DialogueId"] = 200008411,
            ["GUID"] = "200008411",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 20000842,
            },
        [200008412] = {
            ["Content"] = "（你决定帮助赛琪。）",
            ["ContentJP"] = "（サイキを手伝ってあげよう）",
            ["DialogueId"] = 200008412,
            ["GUID"] = "200008412",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 20000842,
            },
        [200009111] = {
            ["Content"] = "的确……如果有的选，花也不想被采摘下来吧。",
            ["ContentJP"] = "たしかに……花だって選べるならば摘まれたくない{性别:はずだ|よね}。",
            ["DialogueId"] = 200009111,
            ["GUID"] = "200009111",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20000913,
            },
        [200009112] = {
            ["Content"] = "如果这些花能够被人们欣赏，也算是发挥了作用。",
            ["ContentJP"] = "たくさんの人の目を楽しませるのも、花としての役割だと思う。",
            ["DialogueId"] = 200009112,
            ["GUID"] = "200009112",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 20000912,
            },
        [200009151] = {
            ["Content"] = "我会努力让它们活得更久一些。",
            ["ContentJP"] = "その花ができるだけ長く咲けるよう努力する。",
            ["DialogueId"] = 200009151,
            ["GUID"] = "200009151",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 20000916,
            },
        [200009152] = {
            ["Content"] = "我会珍惜它们盛放的时刻。",
            ["ContentJP"] = "その花の咲いている時間を大切にしたいと思う。",
            ["DialogueId"] = 200009152,
            ["GUID"] = "200009152",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 20000917,
            },
        [200009153] = {
            ["Content"] = "我也觉得它们很可怜……",
            ["ContentJP"] = "{性别:僕|私}もかわいそうに感じてしまうかな……",
            ["DialogueId"] = 200009153,
            ["GUID"] = "200009153",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20000918,
            },
        [200009221] = {
            ["Content"] = "是啊，真了不起。",
            ["ContentJP"] = "そうだね、本当にすごい{性别:な|よね}。",
            ["DialogueId"] = 200009221,
            ["GUID"] = "200009221.0",
            ["NextDialogue"] = 20000923,
            },
        [200009222] = {
            ["Content"] = "我还是希望它们能留在枝干上，不要被切下。",
            ["ContentJP"] = "でもやっぱり切り取られないで、枝から離れないで欲しいかも。",
            ["DialogueId"] = 200009222,
            ["GUID"] = "200009222.0",
            ["NextDialogue"] = 20000924,
            },
        [200009261] = {
            ["Content"] = "不客气，如果不够了我还可以再去帮你挖。",
            ["ContentJP"] = "どういたしまして。足りなくなったらまた取ってくるから。",
            ["DialogueId"] = 200009261,
            ["GUID"] = "200009261.0",
            ["NextDialogue"] = 20000929,
            },
        [200009262] = {
            ["Content"] = "那正好，你有时间也教教我吧。",
