            ["ContentJP"] = "まだ準備が整っていない。",
            ["DialogueId"] = 200017012,
            ["GUID"] = "200017012",
            ["SpeakNpcId"] = 200021,
            },
        [200023011] = {
            ["Content"] = "唤醒她。",
            ["ContentJP"] = "サイキを起こす。",
            ["DialogueId"] = 200023011,
            ["GUID"] = "200023011",
            },
        [200023012] = {
            ["Content"] = "还没有准备好。",
            ["ContentJP"] = "まだ準備が整っていない。",
            ["DialogueId"] = 200023012,
            ["GUID"] = "200023012",
            },
        [200048041] = {
            ["Content"] = "这不是好事吗？顺便问一下，你喜欢哪种做法？",
            ["ContentJP"] = "それは、食べ応えがありそうだね。",
            ["DialogueId"] = 200048041,
            ["GUID"] = "200048041",
            ["NextDialogue"] = 20004805,
            },
        [200048042] = {
            ["Content"] = "“大事”指的是看见了很大的猪这件事？",
            ["ContentJP"] = "「大事件」ってそのブタのこと？",
            ["DialogueId"] = 200048042,
            ["GUID"] = "200048042.0",
            ["NextDialogue"] = 20004806,
            },
        [200049011] = {
            ["Content"] = "可以。",
            ["DialogueId"] = 200049011,
            ["GUID"] = "200049011.0",
            },
        [200049012] = {
            ["Content"] = "猪的事先放一放。",
            ["DialogueId"] = 200049012,
            ["GUID"] = "200049012.0",
            },
        [200054111] = {
            ["Content"] = "就和卡戎之民与索拉之民外表不同，但都是人类一样？",
            ["ContentJP"] = "カロン族とソラの民みたいに、外見は違えど、本質は同じだってこと？",
            ["DialogueId"] = 200054111,
            ["GUID"] = "200054111",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 20005412,
            },
        [200054112] = {
            ["Content"] = "就和枪与弓箭虽然外表不同，但都是远距离武器一样？",
            ["ContentJP"] = "銃と弓矢のように、見た目は違えど、種類は同じだってこと？",
            ["DialogueId"] = 200054112,
            ["GUID"] = "200054112.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 20005413,
            },
        [200054113] = {
            ["Content"] = "就和雪和雾虽然是不一样的东西，但其实主要都是水做的一样？",
            ["ContentJP"] = "雪と霧のように、性質は違えど、主成分は水だってこと？",
            ["DialogueId"] = 200054113,
            ["GUID"] = "200054113.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 20005414,
            },
        [200054311] = {
            ["Content"] = "包在我身上。",
            ["ContentJP"] = "任せて。",
            ["DialogueId"] = 200054311,
            ["GUID"] = "200054311",
            ["NextDialogue"] = 20005432,
            },
        [200054312] = {
            ["Content"] = "你能听懂魔灵说话？",
            ["ContentJP"] = "ジェネモンの言葉が分かるの？",
            ["DialogueId"] = 200054312,
            ["GUID"] = "200054312.0",
            ["NextDialogue"] = 20005433,
            },
        [200055011] = {
            ["Content"] = "榛子可真大啊。",
            ["ContentJP"] = "それにしても大きいブタだね。",
            ["DialogueId"] = 200055011,
            ["GUID"] = "200055011.0",
            ["NextDialogue"] = 20005502,
            },
        [200055012] = {
            ["Content"] = "你的亲人不担心你吗？",
            ["ContentJP"] = "家族が心配するんじゃない？",
            ["DialogueId"] = 200055012,
            ["GUID"] = "200055012.0",
            ["NextDialogue"] = 20005504,
            },
        [200055013] = {
            ["Content"] = "好的哦。",
            ["ContentJP"] = "分かった。",
            ["DialogueId"] = 200055013,
            ["GUID"] = "200055013.0",
            },
        [200056041] = {
            ["Content"] = "好。",
            ["ContentJP"] = "そうだね。",
            ["DialogueId"] = 200056041,
            ["GUID"] = "200056041",
            },
        [200056042] = {
            ["Content"] = "先等一等。",
            ["ContentJP"] = "少し待って。",
            ["DialogueId"] = 200056042,
            ["GUID"] = "200056042",
            },
        [200057151] = {
