        [200065130] = {
            ["Camera"] = "242.134766,284.203125,81.299271,0.000249,2.80091,-142.179596,28.0,300.0,false,Manual,8.0",
            ["DialogueId"] = 200065130,
            ["FacialId"] = {
                [1] = "100001:Smile01",
                },
            ["GUID"] = "32158E8B",
            ["NextOptions"] = {
                [1] = 200065131,
                [2] = 200065132,
                [3] = 200065133,
                },
            ["TalkActionId"] = {
                [1] = "100001:Explain02_Start",
                },
            },
        [200065131] = {
            ["Content"] = "我乃夜航者小队队长——{nickname}！在此细数你们的罪恶！",
            ["ContentJP"] = "我は夜航者小隊の隊長――{nickname}なり！さぁ、お前の罪を{性别:数えろ|数えなさい}!",
            ["DialogueId"] = 200065131,
            ["GUID"] = "200065131",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 20006514,
            },
        [200065132] = {
            ["Content"] = "我是路过的下水道工人马里奥，不认识她们！",
            ["ContentJP"] = "{性别:僕|私}は通りすがりの下水道整備士マリオ。この二人とは赤の他人だよ。",
            ["DialogueId"] = 200065132,
            ["GUID"] = "200065132",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 20006516,
            },
        [200065133] = {
            ["Content"] = "放了这些魔灵！",
            ["ContentJP"] = "ジェネモンたちを解放しなさい！",
            ["DialogueId"] = 200065133,
            ["GUID"] = "200065133",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 20006518,
            },
        [200070081] = {
            ["Content"] = "别说傻话，松露会为难的。",
            ["ContentJP"] = "トリュフを困らせちゃダメだよ。",
            ["DialogueId"] = 200070081,
            ["GUID"] = "200070081",
            ["NextDialogue"] = 20007009,
            },
        [200070161] = {
            ["Content"] = "拉钩为定！",
            ["ContentJP"] = "指切りげんまん。",
            ["DialogueId"] = 200070161,
            ["GUID"] = "200070161",
            ["NextDialogue"] = 20007017,
            },
        [200071011] = {
            ["Content"] = "关于魔灵潘神……",
            ["ContentJP"] = "パーンジェネモンについて……",
            ["DialogueId"] = 200071011,
            ["GUID"] = "200071011",
            ["NextDialogue"] = 20007102,
            },
        [200071012] = {
            ["Content"] = "做魔灵学者的感觉如何？",
            ["ContentJP"] = "ジェネモン博士になった感想は？",
            ["DialogueId"] = 200071012,
            ["GUID"] = "200071012",
            ["NextDialogue"] = 20007105,
            },
        [200071013] = {
            ["Content"] = "没什么事。",
            ["ContentJP"] = "特に用はない。",
            ["DialogueId"] = 200071013,
            ["GUID"] = "200071013",
            },
        [510001041] = {
            ["Content"] = "啊啊啊！我喝！让我自己来！",
            ["ContentJP"] = "待って！飲みます！自分で飲みますから！",
            ["DialogueId"] = 510001041,
            ["GUID"] = "510001041.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000105,
            },
        [510001042] = {
            ["Content"] = "（灵巧地闪开——你并不信任陌生人过分的热情。）",
            ["ContentJP"] = "（あなたは老婦人の手をサッとかわした。見知らぬ人からの過剰な親切には用心するべきだ）",
            ["DialogueId"] = 510001042,
            ["GUID"] = "510001042.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000107,
            },
        [510001101] = {
            ["Content"] = "您口中的“夫人”生了病？",
            ["ContentJP"] = "その「奥様」は病気なんですか？",
            ["DialogueId"] = 510001101,
            ["GUID"] = "510001101",
            ["NextDialogue"] = 51000111,
            },
        [510003021] = {
            ["Content"] = "（留意到她的衣服布料颇为华贵。）",
            ["ContentJP"] = "（彼女の身なりがとてもいいことに気がつく）",
            ["DialogueId"] = 510003021,
            ["GUID"] = "510003021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000303,
            },
        [510003022] = {
            ["Content"] = "（留意到她似乎在找什么人。）",
            ["ContentJP"] = "（彼女が誰かを探していることに気づく）",
            ["DialogueId"] = 510003022,
            ["GUID"] = "510003022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51000304,
            },
        [510003023] = {
            ["Content"] = "（留意到她很悲伤。）",
            ["ContentJP"] = "（彼女がとても悲しんでいることに気づく）",
            ["DialogueId"] = 510003023,
            ["GUID"] = "510003023.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000305,
            },
        [510003051] = {
            ["Content"] = "（也许可以帮上什么忙。）",
            ["ContentJP"] = "（何か助けられるかもしれない）",
            ["DialogueId"] = 510003051,
            ["GUID"] = "510003051.0",
            ["NextDialogue"] = 510003052,
            },
        [510003052] = {
            ["Content"] = "（也许可以帮上什么忙。）",
            ["ContentJP"] = "（何か助けられるかもしれない）",
            ["DialogueId"] = 510003052,
            ["GUID"] = "510003052.0",
            ["NextOptions"] = {
                [1] = 510003054,
                [2] = 510003055,
                [3] = 510003056,
                },
            ["SpeakNpcId"] = 100001,
            ["bForbidSkipOptions"] = true,
            },
        [510003053] = {
            ["Content"] = "（离开。）",
            ["ContentJP"] = "（立ち去る）",
            ["DialogueId"] = 510003053,
            ["GUID"] = "510003053.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510003054] = {
            ["Content"] = "（询问她是不是遇到了什么烦心事。付一些报酬的话，可以考虑帮忙解决。）",
            ["ContentJP"] = "（何か困り事はないかと尋ねてみる。少し報酬付きで依頼してくれたら役に立てるかも）",
            ["DialogueId"] = 510003054,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003054.0",
            ["ImprCheckId"] = 1001,
            ["NextDialogue"] = 51000307,
            },
        [510003055] = {
            ["Content"] = "（询问她是否在找什么人，也许日后出城的时候可以帮她留意一下。）",
            ["ContentJP"] = "（誰か探しているのかと尋ねてみる。街を出た時にでも探してあげられるかも）",
            ["DialogueId"] = 510003055,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003055.0",
            ["ImprCheckId"] = 1002,
            ["NextDialogue"] = 51000307,
            },
        [510003056] = {
            ["Content"] = "（询问她是不是有什么困难，或许能提供一些帮助。）",
            ["ContentJP"] = "（何か困ってないか尋ねてみる。少しでも手助けしたい）",
            ["DialogueId"] = 510003056,
            ["FailDialogue"] = 51000306,
            ["GUID"] = "510003056.0",
            ["ImprCheckId"] = 1003,
            ["NextDialogue"] = 51000307,
            },
        [510003111] = {
            ["Content"] = "对此没有印象。",
            ["ContentJP"] = "思い当たる人はいません",
            ["DialogueId"] = 510003111,
            ["GUID"] = "510003111.0",
            ["NextDialogue"] = 51000312,
            },
        [510004031] = {
            ["Content"] = "那个……{性别：我是男的。|我不是你的女儿。}",
            ["ContentJP"] = "あの……{性别:僕、男だけど……？|私、あなたの娘じゃないよ……？}",
            ["DialogueId"] = 510004031,
            ["GUID"] = "510004031.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000490,
            },
        [510004032] = {
            ["Content"] = "冷静一下。你在找人？我会帮你留意。",
            ["ContentJP"] = "落ち着いて。誰かを探しているなら手伝うから。",
            ["DialogueId"] = 510004032,
            ["GUID"] = "510004032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000490,
            },
        [510004033] = {
            ["Content"] = "妈！！！",
            ["ContentJP"] = "お母さん！！会いたかった！！！",
            ["DialogueId"] = 510004033,
            ["GUID"] = "510004033.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51000404,
            },
        [510004071] = {
            ["Content"] = "（接受）",
            ["ContentJP"] = "（同意する）",
            ["DialogueId"] = 510004071,
            ["GUID"] = "510004071.0",
            ["NextDialogue"] = 51000408,
            },
        [510004921] = {
            ["Content"] = "请好好回想一下你女儿的特征与失踪的经过，这样我才能确定能否帮到你。",
            ["ContentJP"] = "娘さんの特徴と、行方不明になった経緯を思い出せるかな？何か手助けできるかもしれないから。",
            ["DialogueId"] = 510004921,
            ["FailDialogue"] = 51000405,
            ["GUID"] = "510004921.0",
            ["ImprCheckId"] = 1007,
            ["NextDialogue"] = 51000406,
            },
        [510005011] = {
            ["Content"] = "爱尔莎，我有了安妮的消息……",
            ["ContentJP"] = "アニーについてわかったことがある{性别:んだ|の}……",
            ["DialogueId"] = 510005011,
            ["GUID"] = "510005011.0",
            ["NextDialogue"] = 51000502,
            },
        [510005021] = {
            ["Content"] = "请您节哀，安妮已经去世了……在她生命的最后，她帮助另一个女孩活了下来，她的善良值得被铭记。",
            ["ContentJP"] = "アニーのこと、お悔やみ申し上げる……人生の最後に、アニーはもう一人の少女が生き延びるのを助けた。その優しさは記憶されるべきものだ。",
            ["DialogueId"] = 510005021,
            ["GUID"] = "510005021.0",
            ["NextDialogue"] = 51000503,
            },
        [510006011] = {
            ["Content"] = "爱尔莎，我有了安妮的消息……",
            ["ContentJP"] = "娘さん、見つかったよ。",
            ["DialogueId"] = 510006011,
            ["GUID"] = "510006011.0",
            ["NextDialogue"] = 51000602,
            },
        [510007011] = {
            ["Content"] = "你一直在这里徘徊，有什么能帮你的吗？",
            ["ContentJP"] = "ずっとこの辺をさまよっているみたいだけど、{性别:僕|私}に何か手伝えることはある？",
            ["DialogueId"] = 510007011,
            ["GUID"] = "510007011.0",
            ["NextDialogue"] = 51000702,
            },
        [510007031] = {
            ["Content"] = "我理解你的迷茫，失去归属感的确很糟。",
            ["ContentJP"] = "戸惑うのは仕方ないよ。帰るべき場所もわからないなんて、落ち着かなくて当たり前だし。",
            ["DialogueId"] = 510007031,
            ["GUID"] = "510007031.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51000705,
            },
        [510007032] = {
            ["Content"] = "滞留在外并不安全，还是尽早弄清你的真实身份为妙。",
            ["ContentJP"] = "ずっと外にいるのは安全じゃないよ。できるだけ早く自分が何者なのか思い出した方がいいはず。",
            ["DialogueId"] = 510007032,
            ["GUID"] = "510007032.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51000705,
            },
        [510007033] = {
            ["Content"] = "眼见不一定为实。一切都需要调查后才能得出结论。",
            ["ContentJP"] = "目先の事実だけが真実だとは限らないし、いろいろ調査してから結論を出さないとね。",
            ["DialogueId"] = 510007033,
            ["GUID"] = "510007033.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51000705,
            },
        [510007051] = {
            ["Content"] = "（接受）",
            ["ContentJP"] = "（同意する）",
            ["DialogueId"] = 510007051,
            ["GUID"] = "510007051.0",
            ["NextDialogue"] = 51000706,
            },
        [510008121] = {
            ["Content"] = "（不展示爱丽丝的日记）",
            ["ContentJP"] = "（アリスの日記を見せない）",
            ["DialogueId"] = 510008121,
            ["GUID"] = "510008121.0",
            ["NextDialogue"] = 51000813,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510008141] = {
            ["Content"] = "正是你母亲托我来寻找你，我会带你去见她。",
            ["ContentJP"] = "実はそのお母さんから、あなたを探してほしいって頼まれていた{性别:んだ|の}。一緒にお母さんに会いに{性别:行かない|行こう}？",
            ["DialogueId"] = 510008141,
            ["GUID"] = "510008141.0",
            ["NextDialogue"] = 51000814,
            },
        [510008921] = {
            ["Content"] = "（展示爱丽丝的日记）",
            ["ContentJP"] = "（アリスの日記を見せる）",
            ["DialogueId"] = 510008921,
            ["GUID"] = "510008921.0",
            ["NextDialogue"] = 51000803,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510009031] = {
            ["Content"] = "我只看到了一些破烂，据我估价，他们不会比几块石头更有价值。",
            ["ContentJP"] = "ガラクタにしか見えないけど……{性别:僕|私}の見立てだと石よりも価値がなさそうな……",
            ["DialogueId"] = 510009031,
            ["GUID"] = "510009031.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51000904,
            },
        [510009032] = {
            ["Content"] = "不问自取的行为还是少做为妙。",
            ["ContentJP"] = "買い物に来たわけじゃないのに。勝手にそんなこと言われても困るんだけど……",
            ["DialogueId"] = 510009032,
            ["GUID"] = "510009032.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51000905,
            },
        [510009033] = {
            ["Content"] = "从哪儿摸的！带我一个！",
            ["ContentJP"] = "どこで手に入れた{性别:んだ|の}！{性别:僕|私}にも教えて！",
            ["DialogueId"] = 510009033,
            ["GUID"] = "510009033.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51000906,
            },
        [510009071] = {
            ["Content"] = "很可惜，这里没有我需要的商品。",
            ["ContentJP"] = "残念だけど、ここに{性别:僕|私}の欲しい物はないよ。",
            ["DialogueId"] = 510009071,
            ["GUID"] = "510009071.0",
            ["NextDialogue"] = 51000907,
            },
        [510009072] = {
            ["Content"] = "（他仔仔细细地打量着你，露出了一个深思的表情）",
            ["ContentJP"] = "（彼はあなたの顔をじっと見つめながら、何かを考え込んでいる）",
            ["DialogueId"] = 510009072,
            ["GUID"] = "510009072.0",
            ["ImprCheckId"] = 1004,
            ["NextDialogue"] = 51000909,
            },
        [510009101] = {
            ["Content"] = "我听说有人可以提供一部分价格低廉的燃料与布匹，这让不少穷人能安然渡过隆冬。",
            ["ContentJP"] = "手頃な価格で燃料や布を提供してくれる人がいるとは聞いていたよ。お陰でたくさんの貧しい人が冬を無事に乗り切れたって。",
            ["DialogueId"] = 510009101,
            ["GUID"] = "510009101.0",
            ["ImprPlusId"] = 1002,
            },
        [510009102] = {
            ["Content"] = "你售卖情报，但你看起来不像个私家侦探，难道你有特别的情报来源？",
            ["ContentJP"] = "あなたは情報を売っているらしいけど、私立探偵には見えない{性别:な|ね}。もしかして特別な情報源を持っている{性别:とか|の}？",
            ["DialogueId"] = 510009102,
            ["GUID"] = "510009102.0",
            ["ImprPlusId"] = 1003,
            },
        [510009103] = {
            ["Content"] = "我已经听你说过三遍马丁了，你到底谁啊？",
            ["ContentJP"] = "あなたの口から「マーティン」って名前を3回は聞いたけど、ところであなたはいったい誰{性别:なんだ|なの}？",
            ["DialogueId"] = 510009103,
            ["GUID"] = "510009103.0",
            ["ImprPlusId"] = 1005,
            },
        [510009121] = {
            ["Content"] = "真有那么神奇吗？",
            ["ContentJP"] = "そんな不思議なことがあるの{性别:か|}？",
            ["DialogueId"] = 510009121,
            ["GUID"] = "510009121",
            },
        [510009161] = {
            ["Content"] = "（接受）",
            ["ContentJP"] = "（同意する）",
            ["DialogueId"] = 510009161,
            ["GUID"] = "510009161.0",
            },
        [510010071] = {
            ["Content"] = "你丢了一样东西。这件东西证明了你不过也是个和他一样的窝棚板富豪。",
            ["ContentJP"] = "あなた、「何か」を失くした{性别:ね|よね}？その「何か」があなたも同じだって証明してる{性别:んだ|よ}。さっきの行商の人と同じ、ただのあばら屋の住人でしかないって{性别:さ|}。",
            ["DialogueId"] = 510010071,
            ["GUID"] = "510010071.0",
            ["ImprCheckId"] = 1005,
            ["NextDialogue"] = 51001008,
            },
        [510010072] = {
            ["Content"] = "你丢了一样东西。通常来说，过期车票应该销毁以防模仿造假，而私藏显然是个违规行为。",
            ["ContentJP"] = "あなたが失くした「何か」……たぶん取り扱いの決まりがあるよね。偽造を防ぐために期限切れの切符はすぐ破棄するよう決まっていて、持ち帰って保管するなんて違反行為のはず。",
            ["DialogueId"] = 510010072,
            ["GUID"] = "510010072.0",
            ["ImprCheckId"] = 1006,
            ["NextDialogue"] = 51001008,
            },
        [510010101] = {
            ["Content"] = "传说星星有实现愿望的能力，你用车票叠了上百颗星星，又想实现什么样的愿望呢？",
            ["ContentJP"] = "星には願いを叶える力があるって言われているけど……切符でこんなにたくさん星を折って、どんな願いを叶えたいの？",
            ["DialogueId"] = 510010101,
            ["GUID"] = "510010101.0",
            },
        [510010181] = {
            ["Content"] = "我理解你的不甘与悲痛，人生总有不如意的时候，但现在无法跨越的天堑也许终有一天会成为坦途。",
            ["ContentJP"] = "気持ちは痛いくらいわかる{性别:|よ}……人生は思い通りにいかないことばかりだ{性别:|よね}……でも今は乗り越えられない断崖絶壁だっていつかは乗り越える方法が見つかるかも。",
            ["DialogueId"] = 510010181,
            ["GUID"] = "510010181.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001019,
            },
        [510010182] = {
            ["Content"] = "不论如何，刚才的先生都不应该被你这么羞辱，恕我难以苟同你把怒火发泄到别人身上的行为。",
            ["ContentJP"] = "だとしてもさっきの人を侮辱するのは間違いだ{性别:|よ}。ごめん……でも他人に八つ当たりなんて同情できない{性别:から|もの}。",
            ["DialogueId"] = 510010182,
            ["GUID"] = "510010182.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001020,
            },
        [510010183] = {
            ["Content"] = "不管你怎么想，要是不想摊上事，你就该把这东西收回去，妥善保存也罢，销毁也好，那是你的问题。",
            ["ContentJP"] = "想いがどうだとしても、トラブルを避けたいなら、この星はちゃんと処理するか保管するかしたほうがいいよ。どちらを選ぶかはあなた次第だけど。",
            ["DialogueId"] = 510010183,
            ["GUID"] = "510010183.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001021,
            },
        [510010184] = {
            ["Content"] = "你干嘛不扒在车顶坐个来回过过瘾？",
            ["ContentJP"] = "そんなに乗りたいなら汽車の屋根に乗って楽しめばいい{性别:じゃないか|のに}？",
            ["DialogueId"] = 510010184,
            ["GUID"] = "510010184.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001022,
            },
        [510012011] = {
            ["Content"] = "那些鸟都是你养的吗？",
            ["ContentJP"] = "あの鳥たちはおじいさんが飼っているんですか？",
            ["DialogueId"] = 510012011,
            ["GUID"] = "510012011.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001202,
            },
        [510012012] = {
            ["Content"] = "那些鸟飞得太高了，不然今天还能加顿餐。",
            ["ContentJP"] = "高く飛びすぎだ{性别:んだね|のね}。\
――今日は鳥料理が食べられると思ったのにな。",
            ["DialogueId"] = 510012012,
            ["GUID"] = "510012012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001203,
            },
        [510012041] = {
            ["Content"] = "（回忆你从书本上看到的金翎鸟的知识——它们的习性，以及为什么它们可以成为探测工具。）",
            ["ContentJP"] = "（カナリアの習性と、なぜ鉱山の有毒ガス検知手段として使われるようになったのか、本で読んだことを思い出した）",
            ["DialogueId"] = 510012041,
            ["GUID"] = "510012041.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001205,
            },
        [510012042] = {
            ["Content"] = "（附和面前这位矿工，批判人们对传统的遗弃。）",
            ["ContentJP"] = "（鉱夫に同意して、昔ながらのやり方を放棄する風潮を批判する）",
            ["DialogueId"] = 510012042,
            ["GUID"] = "510012042.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001206,
            },
        [510012043] = {
            ["Content"] = "（向面前这位矿工赞扬技术发展能让人类社会更高效地运转。）",
            ["ContentJP"] = "（技術は社会機能をより効率化できると、鉱夫に説明する）",
            ["DialogueId"] = 510012043,
            ["GUID"] = "510012043.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001207,
            },
        [510013011] = {
            ["Content"] = "你不能这样侮辱一位受尊敬的女士。",
            ["ContentJP"] = "そんな風に尊敬されるべき女性を侮辱するのはやめろ。",
            ["DialogueId"] = 510013011,
            ["GUID"] = "510013011.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001302,
            },
        [510013012] = {
            ["Content"] = "（上去就是一拳）",
            ["ContentJP"] = "（パンチをお見舞いする）",
            ["DialogueId"] = 510013012,
            ["GUID"] = "510013012.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001303,
            },
        [510013013] = {
            ["Content"] = "给她点面子就敢蹬鼻子上脸，还说什么看不上老子的酒，老子早晚让她吃不了兜着走！",
            ["ContentJP"] = "あいつにちょっとでも顔を立てたらすぐに調子に乗りやがって、俺の酒を気に入らないだと？そのうちあいつを痛い目に合わせてやる！",
            ["DialogueId"] = 510013013,
            ["GUID"] = "510013013",
            ["NextOptions"] = {
                [1] = 510013011,
                [2] = 510013012,
                },
            ["SpeakNpcId"] = 700014,
            ["bForbidSkipOptions"] = true,
            },
        [510013041] = {
            ["Content"] = "不，卡米拉是一位值得信赖的朋友，她帮过我忙。",
            ["ContentJP"] = "いや、カミラは信頼できる友人だ。私を助けてくれたんだ。",
            ["DialogueId"] = 510013041,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013041.0",
            ["ImprCheckId"] = 1008,
            ["NextDialogue"] = 51001306,
            },
        [510013042] = {
            ["Content"] = "你不用多费唇舌，卡米拉为人怎么样，我相信自己的判断。",
            ["ContentJP"] = "無駄な口を叩くな。カミラがどんな人かは、自分の目で見てきた。",
            ["DialogueId"] = 510013042,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013042.0",
            ["ImprCheckId"] = 1009,
            ["NextDialogue"] = 51001306,
            },
        [510013043] = {
            ["Content"] = "所以你是向卡米拉推销酒水不成，着急了。",
            ["ContentJP"] = "つまりカミラに酒を売り込もうとして失敗した、それで焦ってるんだろう。",
            ["DialogueId"] = 510013043,
            ["FailDialogue"] = 51001305,
            ["GUID"] = "510013043.0",
            ["ImprCheckId"] = 1010,
            ["NextDialogue"] = 51001306,
            },
        [510013061] = {
            ["Content"] = "嗯，咳，听口音你不是本地人吧。我猜，自从来到冰湖城，你就没去水仙平原之外的地方喝过吧？",
            ["ContentJP"] = "お前…聞いた感じでは、この辺りの出身ではなさそうだな。アイスレイク城に来てから「アスフォデロス」以外で酒飲んだことがないんだろう？",
            ["DialogueId"] = 510013061,
            ["GUID"] = "510013061.0",
            ["SpeakNpcId"] = 700014,
            },
        [510013062] = {
            ["Content"] = "那又如何？",
            ["ContentJP"] = "それがどうかした？",
            ["DialogueId"] = 510013062,
            ["GUID"] = "510013062",
            },
        [510013091] = {
            ["Content"] = "好吧，来一桶。",
            ["ContentJP"] = "じゃあ、一杯だけ……",
            ["DialogueId"] = 510013091,
            ["GUID"] = "510013091.0",
            ["NextDialogue"] = 51001310,
            },
        [510013092] = {
            ["Content"] = "便宜没好货。",
            ["ContentJP"] = "安物にはロクな物がないから、やめておく。",
            ["DialogueId"] = 510013092,
            ["GUID"] = "510013092.0",
            ["NextDialogue"] = 51001313,
            },
        [510013231] = {
            ["Content"] = "抢生意也就算了，万一假酒把人喝出毛病怎么办？",
            ["ContentJP"] = "商売の取り合いはともかく、偽物で人に害が出たらどうするんだ？",
            ["DialogueId"] = 510013231,
            ["GUID"] = "510013231.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001324,
            },
        [510013232] = {
            ["Content"] = "就是！还怕她一张嘴！兄弟你喝一桶看看实力！",
            ["ContentJP"] = "そうだ！そんなデタラメなんて怖がる必要ない！一樽飲んで、実力を見せてやれ！",
            ["DialogueId"] = 510013232,
            ["GUID"] = "510013232.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001326,
            },
        [510013281] = {
            ["Content"] = "假货害人啊……",
            ["ContentJP"] = "ニセ酒は身体に悪いな……",
            ["DialogueId"] = 510013281,
            ["GUID"] = "510013281.0",
            ["NextDialogue"] = 51001329,
            },
        [510014021] = {
            ["Content"] = "孩子本就是天生通透的诗人。",
            ["ContentJP"] = "子供はみんな生まれながらの詩人{性别:だね|ね}。",
            ["DialogueId"] = 510014021,
            ["GUID"] = "510014021.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001403,
            },
        [510014022] = {
            ["Content"] = "你看起来非常为他们自豪。",
            ["ContentJP"] = "生徒さんのことをとても誇りに思っている{性别:んだね|のね}。",
            ["DialogueId"] = 510014022,
            ["GUID"] = "510014022.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001403,
            },
        [510014023] = {
            ["Content"] = "可恶，原来我输在了起跑线上。",
            ["ContentJP"] = "やばい......{性别:僕|私}はスタートラインから負けてる……",
            ["DialogueId"] = 510014023,
            ["GUID"] = "510014023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001403,
            },
        [510014061] = {
            ["Content"] = "才不是呢，你教会了孩子可贵的纯真与浪漫。",
            ["ContentJP"] = "そんなことない。子供たちにとって大切な純粋さとロマンを教えられるじゃない{性别:か|}。",
            ["DialogueId"] = 510014061,
            ["FailDialogue"] = 51001407,
            ["GUID"] = "510014061.0",
            ["ImprCheckId"] = 1011,
            ["NextDialogue"] = 51001409,
            },
        [510014901] = {
            ["Content"] = "你看起来在和孩子们的相处中收获了很多。",
            ["ContentJP"] = "子供たちと過ごす時間から、たくさんのものを手に入れたみたい{性别:だね|ね}。",
            ["DialogueId"] = 510014901,
            ["GUID"] = "510014901.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001412,
            },
        [510014902] = {
            ["Content"] = "为这些孩子们做出牺牲，真的是值得的吗？",
            ["ContentJP"] = "子供たちのためにそこまでする必要あるかな？",
            ["DialogueId"] = 510014902,
            ["GUID"] = "510014902.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001412,
            },
        [510015021] = {
            ["Content"] = "用清洁剂泡一泡再擦？",
            ["ContentJP"] = "洗剤をかけてから拭いたらどうかな？",
            ["DialogueId"] = 510015021,
            ["GUID"] = "510015021.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001503,
            },
        [510015022] = {
            ["Content"] = "你付钱给我，我给你擦。",
            ["ContentJP"] = "おカネをくれたら、代わりに掃除してあげるよ。",
            ["DialogueId"] = 510015022,
            ["GUID"] = "510015022.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51001503,
            },
        [510015023] = {
            ["Content"] = "挨打挨骂是好事，有助于锻炼精神。",
            ["ContentJP"] = "殴られるのも悪くないよ。精神を鍛えるのに役立つから。",
            ["DialogueId"] = 510015023,
            ["GUID"] = "510015023.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001503,
            },
        [510015071] = {
            ["Content"] = "你不觉得说这种话太冷漠了吗？",
            ["ContentJP"] = "そんな……冷たすぎる{性别:だろ|んじゃない}？",
            ["DialogueId"] = 510015071,
            ["GUID"] = "510015071.0",
            ["ImprCheckId"] = 1012,
            ["NextDialogue"] = 51001509,
            },
        [510016021] = {
            ["Content"] = "（此人脾气有点暴躁，摸一摸他的恶魔角安抚下吧。）",
            ["ContentJP"] = "（なんだか機嫌が悪そうだな。悪魔の角をなでてなだめてみよう）",
            ["DialogueId"] = 510016021,
            ["GUID"] = "510016021.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51001603,
            },
        [510016022] = {
            ["Content"] = "卡戎和索拉是平等的。你不该心存偏见。",
            ["ContentJP"] = "カロン族もソラの民も平等だ。偏見はよくない。",
            ["DialogueId"] = 510016022,
            ["GUID"] = "510016022.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001605,
            },
        [510016023] = {
            ["Content"] = "可是你也是个卡戎啊……？",
            ["ContentJP"] = "でも、あなただって同じカロン族じゃない{性别:か|}。",
            ["DialogueId"] = 510016023,
            ["GUID"] = "510016023.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001607,
            },
        [510016121] = {
            ["Content"] = "我可以看看您的“桂冠卡戎”奖章吗？",
            ["ContentJP"] = "「桂冠カロン」の勲章を見せてくれませんか？",
            ["DialogueId"] = 510016121,
            ["FailDialogue"] = 51001690,
            ["GUID"] = "510016121.0",
            ["ImprCheckId"] = 1013,
            ["NextDialogue"] = 51001613,
            },
        [510017031] = {
            ["Content"] = "（真诚建议他注意个人卫生问题）",
            ["ContentJP"] = "（もっと身だしなみに気をつけた方がいいと、真面目にアドバイスする）",
            ["DialogueId"] = 510017031,
            ["GUID"] = "510017031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51001704,
            },
        [510017032] = {
            ["Content"] = "（为自己刚才失礼的动作道歉）",
            ["ContentJP"] = "（失礼な振る舞いを詫びる）",
            ["DialogueId"] = 510017032,
            ["GUID"] = "510017032.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51001704,
            },
        [510017033] = {
            ["Content"] = "（指责他的味道过于腥臭有恶劣影响）",
            ["ContentJP"] = "（臭すぎて周りに迷惑になると非難する）",
            ["DialogueId"] = 510017033,
            ["GUID"] = "510017033.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51001704,
            },
        [510017081] = {
            ["Content"] = "一个本该救死扶伤的人不应该来修理下水道。",
            ["ContentJP"] = "命を救う仕事をしていたのに、今は下水道の修理をしているなんて……",
