            ["NextDialogue"] = 51001924,
            },
        [510019911] = {
            ["Content"] = "威尔斯先生没你说的不堪，别太过分了。",
            ["ContentJP"] = "ウェルズさんはあなたが言うような人じゃない。そんな風に言わないでよ。",
            ["DialogueId"] = 510019911,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019911.0",
            ["ImprCheckId"] = 1015,
            ["NextDialogue"] = 51001918,
            },
        [510019912] = {
            ["Content"] = "桂冠卡戎对我们没有任何吸引力，别拿你浅薄的认知定义所有人。",
            ["ContentJP"] = "桂冠カロン族になろうだなんて考えていない。薄っぺらい認識で他人を{性别:決めつけるな|決めつけないで}。",
            ["DialogueId"] = 510019912,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019912.0",
            ["ImprCheckId"] = 1016,
            ["NextDialogue"] = 51001918,
            },
        [510019913] = {
            ["Content"] = "嘴巴放干净点。不然今天像狗一样被打一顿的，就是另一个“威尔斯先生”了。",
            ["ContentJP"] = "ウェルズさんを犬扱いしているけど、あなただってキャンキャン吠える犬みたい……口の利き方がなっていない犬にはしつけが必要そう{性别:だ|}ね？ねえ「ウェルズさん」？",
            ["DialogueId"] = 510019913,
            ["FailDialogue"] = 51001916,
            ["GUID"] = "510019913.0",
            ["ImprCheckId"] = 1017,
            ["NextDialogue"] = 51001918,
            },
        [510020031] = {
            ["Content"] = "为什么你不自己去寻宝呢？",
            ["ContentJP"] = "なぜ自分で秘宝を探さない{性别:んだ|の}？",
            ["DialogueId"] = 510020031,
            ["GUID"] = "510020031.0",
            ["ImprPlusId"] = 1003,
            ["NextDialogue"] = 51002004,
            },
        [510020032] = {
            ["Content"] = "稍微介绍一下这个宝藏？",
            ["ContentJP"] = "秘宝について少し聞いてもいい？",
            ["DialogueId"] = 510020032,
            ["GUID"] = "510020032.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51002006,
            },
        [510020033] = {
            ["Content"] = "你是不是在骗人啊……",
            ["ContentJP"] = "根も葉もないうそだったり……？",
            ["DialogueId"] = 510020033,
            ["GUID"] = "510020033.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002008,
            },
        [510020131] = {
            ["Content"] = "我总觉得你说的这个南方海岛很耳熟。",
            ["ContentJP"] = "おじさんの言う南方の島って……もしかして……",
            ["DialogueId"] = 510020131,
            ["FailDialogue"] = 51002014,
            ["GUID"] = "510020131.0",
            ["ImprCheckId"] = 1018,
            ["NextDialogue"] = 51002016,
            },
        [510023011] = {
            ["Content"] = "哈默尔·狄金森……我好像看到过这个名字……",
            ["ContentJP"] = "ハーメル・ディキンソン……どこかで名前を見たような……",
            ["DialogueId"] = 510023011,
            ["GUID"] = "510023011.0",
            ["NextDialogue"] = 51002302,
            },
        [510023041] = {
            ["Content"] = "（交出在矿坑中得到的日记）",
            ["ContentJP"] = "（鉱山で見つけた日記を渡す）",
            ["DialogueId"] = 510023041,
            ["GUID"] = "510023041.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002305,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [510023042] = {
            ["Content"] = "（隐瞒在矿坑中得到的日记）",
            ["ContentJP"] = "（鉱山で手に入れた日記のことを隠す）",
            ["DialogueId"] = 510023042,
            ["GUID"] = "510023042.0",
            ["ImprPlusId"] = 1016,
            ["NextDialogue"] = 51002312,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
        [510024031] = {
            ["Content"] = "可以告诉我哈默尔的事情吗？",
            ["ContentJP"] = "ハーメルのことを教えてくれませんか？",
            ["DialogueId"] = 510024031,
            ["GUID"] = "510024031.0",
            ["NextDialogue"] = 51002432,
            },
        [510024141] = {
            ["Content"] = "但是哈默尔爽约了？",
            ["ContentJP"] = "だけど、ハーメルは約束の場所に来なかった？",
            ["DialogueId"] = 510024141,
            ["GUID"] = "510024141.0",
            ["NextDialogue"] = 51002415,
            },
        [510025021] = {
            ["Content"] = "我虽然不买，但分我一半报酬的话，可以帮你找找买家。",
            ["ContentJP"] = "{性别:私は買わないけど、報酬の半分を分けてくれるなら、買い手を探してあげないこともない。|僕は買わないけど、報酬の半分を分けてくれるなら、買い手を探してやらないこともない。}",
            ["DialogueId"] = 510025021,
            ["GUID"] = "510025021.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 51002505,
            },
        [510025022] = {
            ["Content"] = "你需要什么帮助吗？",
            ["ContentJP"] = "{性别:何か手伝いが必要なの？|何か手伝いが必要なのか？}",
            ["DialogueId"] = 510025022,
            ["GUID"] = "510025022.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51002505,
            },
        [510025023] = {
            ["Content"] = "帝国肯定不会允许你干这种事，不想惹麻烦的话就快走吧。",
            ["ContentJP"] = "{性别:帝国がそんな商売を許すわけないじゃない。早く行かないと面倒事に巻き込まれるよ？|帝国がそんな商売を許すわけないじゃないか。早く行かないと面倒事に巻き込まれるぞ？}",
            ["DialogueId"] = 510025023,
            ["GUID"] = "510025023.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 51002503,
            },
        [510025024] = {
            ["Content"] = "咳！军团的士兵委托我盘查你，赶紧把通行证拿出来！",
            ["ContentJP"] = "帝国軍の兵士様からお前に尋問しろと依頼を受けた！サッサと通行許可証を出せ！",
            ["DialogueId"] = 510025024,
            ["GUID"] = "510025024.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51002504,
            },
        [510026031] = {
            ["Content"] = "凯文，冰湖城有人在违规售卖月石。",
            ["ContentJP"] = "ケビン、スラムに月ノ石の違法販売してる奴がいる。",
            ["DialogueId"] = 510026031,
            ["FailDialogue"] = 51002604,
            ["GUID"] = "510026031.0",
            ["ImprCheckId"] = 1026,
            ["NextDialogue"] = 51002605,
            },
        [510029041] = {
            ["Content"] = "按时报到。",
            ["ContentJP"] = "はい、いつもどおりに。",
            ["DialogueId"] = 510029041,
            ["GUID"] = "510029041.0",
            ["NextDialogue"] = 51002905,
            },
        [510029081] = {
            ["Content"] = "他是谁？",
            ["ContentJP"] = "彼は、何者？",
            ["DialogueId"] = 510029081,
            ["GUID"] = "510029081.0",
            ["NextDialogue"] = 51002909,
            },
        [510029101] = {
            ["Content"] = "省略巴克先生层层叠叠的修辞手法，再将关键词重新组合，或许能听懂他在说些什么。",
            ["ContentJP"] = "多層的なレトリックを省略して言葉を組み替えれば、話している内容が理解できるかもしれない。",
            ["DialogueId"] = 510029101,
            ["FailDialogue"] = 51002911,
            ["GUID"] = "510029101.0",
            ["ImprCheckId"] = 1019,
            ["NextDialogue"] = 51002912,
            },
        [510030031] = {
            ["Content"] = "巴克先生总是熬夜创作。",
            ["ContentJP"] = "いつも徹夜で創作しているらしいです。",
            ["DialogueId"] = 510030031,
            ["GUID"] = "510030031.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003004,
            },
        [510030032] = {
            ["Content"] = "嗐，夜猫子罢了。",
            ["ContentJP"] = "ただの夜型人間です。",
            ["DialogueId"] = 510030032,
            ["GUID"] = "510030032.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003004,
            },
        [510030051] = {
            ["Content"] = "巴克先生的工作不太顺利。",
            ["ContentJP"] = "お仕事があまり順調じゃないみたいです。",
            ["DialogueId"] = 510030051,
            ["GUID"] = "510030051.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003006,
            },
        [510030052] = {
            ["Content"] = "哦~把自己写睡着了，说不定他更适合去写睡前故事。",
            ["ContentJP"] = "寝かしつけ絵本の作家に転向できますね。書いている途中で寝ちゃうような内容であれば。",
            ["DialogueId"] = 510030052,
            ["GUID"] = "510030052.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003006,
            },
        [510030071] = {
            ["Content"] = "巴克先生在睡着的时候注意到了一些反常的动静。",
            ["ContentJP"] = "寝ている時に、何か異常があるって気づいたみたいです。",
            ["DialogueId"] = 510030071,
            ["GUID"] = "510030071.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003008,
            },
        [510030072] = {
            ["Content"] = "不排除睡傻了的可能性，也不排除有人跟他过不去的可能性。",
            ["ContentJP"] = "寝ぼけていたって可能性もあるし、誰かのイタズラって可能性もあると思いますが。",
            ["DialogueId"] = 510030072,
            ["GUID"] = "510030072.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003008,
            },
        [510030091] = {
            ["Content"] = "巴克先生没有财物上的损失。",
            ["ContentJP"] = "家財に被害はなかったみたいです。",
            ["DialogueId"] = 510030091,
            ["GUID"] = "510030091.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003010,
            },
        [510030092] = {
            ["Content"] = "什么都没偷？这贼难道有偷窥别人睡觉的嗜好？",
            ["ContentJP"] = "何も盗まれなかったって？寝ている姿を盗み見るだけの泥棒なんていますかね？",
            ["DialogueId"] = 510030092,
            ["GUID"] = "510030092.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003010,
            },
        [510030111] = {
            ["Content"] = "如果有人帮他找出真相，巴克先生会把他当做下部戏剧的主角。",
            ["ContentJP"] = "真相を解き明かす手助けをしたら、バックさんの次の演劇の主人公にしてくれるらしいです。",
            ["DialogueId"] = 510030111,
            ["GUID"] = "510030111.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 51003012,
            },
        [510030112] = {
            ["Content"] = "穷光蛋啊！",
            ["ContentJP"] = "タダ働きじゃん！",
            ["DialogueId"] = 510030112,
            ["GUID"] = "510030112.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 51003012,
            },
        [510030121] = {
            ["Content"] = "让我来为你解决问题吧，巴克先生。",
            ["ContentJP"] = "{性别:バックさん、私があなたの問題を引き受けます。|バックさん、僕があなたの問題を引き受けます。}",
            ["DialogueId"] = 510030121,
            ["GUID"] = "510030121.0",
            ["NextDialogue"] = 51003013,
            },
        [510030122] = {
            ["Content"] = "算了吧。",
            ["ContentJP"] = "いや、やめておくよ。",
            ["DialogueId"] = 510030122,
            ["GUID"] = "510030122.0",
            ["Scripts"] = "SetOutport{FinishType{\"Fail\"}}",
            },
        [510033051] = {
            ["Content"] = "今天生意怎么样，足够购买过夜的燃料吗？",
            ["ContentJP"] = "{性别:売れ行きはどうだったの？今日の寒夜はしのげそう？|売れ行きはどうだった？今日の寒夜はしのげそうか？}",
            ["DialogueId"] = 510033051,
            ["GUID"] = "510033051.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 510033053,
            },
        [510033052] = {
            ["Content"] = "你这点哪够我吃的。",
            ["ContentJP"] = "{性别:その量じゃ私が食べるには足りない。|その量じゃ僕が食べるには足りない。}",
            ["DialogueId"] = 510033052,
            ["GUID"] = "510033052.0",
            ["ImprPlusId"] = 1005,
            ["NextDialogue"] = 510033054,
            },
        [510033053] = {
            ["Content"] = "托您的福，食物和燃料，我总能得到其中一个，人生就是一场取舍。",
            ["ContentJP"] = "お陰さまで食べ物か燃料か、どっちかひとつは有りつけそうです。人生は「あちら立てればこちらが立たぬ」といったところで。",
            ["DialogueId"] = 510033053,
            ["GUID"] = "510033053.0",
            ["NextDialogue"] = 51003306,
            ["SpeakNpcId"] = 700080,
            },
        [510033054] = {
            ["Content"] = "给您塞塞牙缝！虽然数量不足 ，但口味可以保证！",
            ["ContentJP"] = "とはいえ何か召し上がって一息つくのも大事ですよ！量は物足りなくとも、味は保証いたしますし！",
            ["DialogueId"] = 510033054,
            ["GUID"] = "510033054.0",
            ["NextDialogue"] = 51003306,
            ["SpeakNpcId"] = 700080,
            },
        [510033141] = {
            ["Content"] = "你并不怨恨他，也没有偷窃他家的财物，让我来猜猜看你为什么要半夜闯空门吧。",
            ["ContentJP"] = "{性别:あなたは彼を恨んでいない、彼の物も盗んでいない。だったらなぜ夜中にこっそり部屋に忍び込んだのか……恐らくだけど――|あなたは彼を恨んでいない、彼の物も盗んでいない。だったらなぜ夜中にこっそり部屋に忍び込んだのか……恐らくだけど――}",
            ["DialogueId"] = 510033141,
            ["FailDialogue"] = 51003315,
            ["GUID"] = "510033141.0",
            ["ImprCheckId"] = 1022,
            ["NextDialogue"] = 51003316,
            },
        [510034141] = {
            ["Content"] = "有什么将要发生了！我们站在冻结的湖面，能看到的只是冷漠，深邃，凝结。",
            ["ContentJP"] = "何事かが生起する！凍てつく湖面に立った我らの目に映るのは、冷厳と、深淵と、凝結と。",
            ["DialogueId"] = 510034141,
            ["GUID"] = "510034141.0",
            ["NextDialogue"] = 510034142,
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700093:Talk01_Start",
                },
            },
        [510034142] = {
            ["Content"] = "但我们谁都知道暗流正在酝酿，正在壮大，终有一天，它会吞噬我们现有的一切。在这之前，我会乘上火车前往预兆的源头。",
            ["ContentJP"] = "然し我らは暗流が生い育つことを了知している。肥大していく暗流が我らの全てを呑み下すのだ。その時が訪れる前に、私は汽車に乗って兆しの源へと向かう算段である。",
            ["DialogueId"] = 510034142,
            ["GUID"] = "510034142.0",
            ["SpeakNpcId"] = 700015,
            ["TalkActionId"] = {
                [1] = "700093:Talk01_End",
                },
            },
        [510034143] = {
            ["Content"] = "冬天的寒冷已经不再困扰我了，谢谢你，狩月人。",
            ["ContentJP"] = "もう冬の寒さに困ることもありません。ありがとうございました、月狩り人のお客様。",
            ["DialogueId"] = 510034143,
            ["GUID"] = "510034143.0",
            ["SpeakNpcId"] = 700080,
            ["TalkActionId"] = {
                [1] = "700094:Explain02_Start",
                },
            },
        [510035031] = {
            ["Content"] = "艾玛匆忙将花放在指定地点，并按流程献上了感谢致辞，但她的走神还是引起了老师的嘀咕。",
            ["ContentJP"] = "（エマは急いで指定された場所に花を置き、流れに沿って感謝の挨拶を行った。しかし気が抜けていた事実は取り返せず、先生の小言が始まってしまう）",
            ["DialogueId"] = 510035031,
            ["Duration"] = 3,
            ["GUID"] = "510035031.0",
            },
        [510035041] = {
            ["Camera"] = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "好了，下面就是自由活动时间，半个小时后还在雕像下集合，千万别走太远了。",
            ["ContentJP"] = "さて、ここからは自由時間といたします。集合は彫像の下で30分後に。自由と言いましても、目の届かないところへ行ってはいけませんよ。",
            ["DialogueId"] = 510035041,
            ["GUID"] = "510035041.0",
            ["NextDialogue"] = 510035042,
            ["SpeakNpcId"] = 700086,
            ["TalkActionId"] = {
                [1] = "700086:Sigh_End",
                [2] = "700086:Explain01_Start",
                },
            },
        [510035042] = {
            ["Camera"] = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
            ["Content"] = "（纪念活动结束后，艾玛还是一个人发呆，时不时喃喃自语着什么。）",
            ["ContentJP"] = "（記念行事が終了しても、エマはひとりで上の空だ。時折何かを呟きはしているが）",
            ["DialogueId"] = 510035042,
            ["GUID"] = "510035042.0",
            ["TalkActionId"] = {
                [1] = "700016:Confident_Start",
                },
            },
        [510035051] = {
            ["Content"] = "这么敷衍老师可不行，当心被她记小本本哦。",
            ["ContentJP"] = "そんな手抜きじゃ先生に怒られるよ！リストにメモされたらどうするの。",
            ["DialogueId"] = 510035051,
            ["GUID"] = "510035051.0",
            ["ImprPlusId"] = 1001,
            ["NextDialogue"] = 510035054,
            },
        [510035052] = {
            ["Content"] = "你是不是有比参加纪念仪式更想去做的事呀？",
            ["ContentJP"] = "記念式典に参加するより、他に優先してやりたいことでもあったの{性别:か|}？",
            ["DialogueId"] = 510035052,
            ["GUID"] = "510035052.0",
            ["ImprPlusId"] = 1004,
            ["NextDialogue"] = 510035055,
            },
        [510035053] = {
            ["Content"] = "在这种正式场合走神是对被纪念者的不敬。",
            ["ContentJP"] = "公式な場で気を抜くのは祀られている英霊に対して不敬だよ。",
            ["DialogueId"] = 510035053,
            ["GUID"] = "510035053.0",
            ["ImprPlusId"] = 1002,
            ["NextDialogue"] = 510035056,
            },
        [510035054] = {
            ["Content"] = "老师才不会呢！虽然啰嗦，但对我们她可有耐心了！",
            ["ContentJP"] = "あの人はそう簡単に怒らないわよ！口うるさいけど辛抱強いし！",
            ["DialogueId"] = 510035054,
            ["GUID"] = "510035054",
            ["LookAt"] = {
                [1] = "700016:n(0)",
                },
            ["NextDialogue"] = 51003506,
            ["SpeakNpcId"] = 700016,
            },
        [510035055] = {
            ["Content"] = "哎呀！这么明显吗？",
            ["ContentJP"] = "あ！そこまで顔に出てた？",
            ["DialogueId"] = 510035055,
            ["GUID"] = "510035055",
            ["NextDialogue"] = 51003506,
            ["SpeakNpcId"] = 700016,
            },
        [510035056] = {
            ["Content"] = "对我说教的只有老师就够了！",
            ["ContentJP"] = "お説教は先生のでもう十分よ！",
            ["DialogueId"] = 510035056,
            ["GUID"] = "510035056",
            ["NextDialogue"] = 51003506,
            ["SpeakNpcId"] = 700016,
            },
        [510035061] = {
            ["Content"] = "你觉得我像是会泄密的人吗？",
            ["ContentJP"] = "{性别:僕|私}が秘密をバラすように見える{性别:のか|かな}？",
            ["DialogueId"] = 510035061,
            ["FailDialogue"] = 51003507,
            ["GUID"] = "510035061.0",
            ["ImprCheckId"] = 1021,
            ["NextDialogue"] = 51003508,
            },
        [510035141] = {
            ["Content"] = "（接受）",
            ["ContentJP"] = "（受け入れる）",
            ["DialogueId"] = 510035141,
            ["GUID"] = "510035141.0",
            ["NextDialogue"] = 51003515,
