            ["GUID"] = "510073992.0",
            },
        [510074041] = {
            ["Content"] = "将扳手递给达顿。",
            ["DialogueId"] = 510074041,
            ["GUID"] = "510074041.0",
            ["NextDialogue"] = 510074042,
            },
        [510074042] = {
            ["Content"] = "嗯……差不多了，走吧，下一个。",
            ["DialogueId"] = 510074042,
            ["GUID"] = "510074042.0",
            ["SpeakNpcId"] = 700193,
            },
        [510074043] = {
            ["Content"] = "再帮我一下。",
            ["DialogueId"] = 510074043,
            ["GUID"] = "510074043.0",
            ["SpeakNpcId"] = 700191,
            },
        [510074044] = {
            ["Content"] = "将扳手递给达顿。",
            ["DialogueId"] = 510074044,
            ["GUID"] = "510074044.0",
            ["NextDialogue"] = 510074045,
            },
        [510074045] = {
            ["Content"] = "这个也没什么问题了，来，还剩一个。咱们继续往前走。",
            ["DialogueId"] = 510074045,
            ["GUID"] = "510074045.0",
            ["SpeakNpcId"] = 700191,
            },
        [510074048] = {
