            },
        [710051331] = {
            ["Content"] = "（接受。）",
            ["ContentJP"] = "（受け入れる）",
            ["DialogueId"] = 710051331,
            ["GUID"] = "710051271.0",
            },
        [710051332] = {
            ["Content"] = "（前言不搭后语，男人明显在耍你。）",
            ["ContentJP"] = "話に追いつけない。男性は明らかにあなたをからかっている。",
            ["DialogueId"] = 710051332,
            ["GUID"] = "710051272.0",
            },
        [710052141] = {
            ["Content"] = "太神奇了，所有幸福硬币我都要了！",
            ["ContentJP"] = "なんて不思議な{性别:んだ|の}！ここにあるラッキーコインは全部いただく{性别:よ|わ}！",
            ["DialogueId"] = 710052141,
            ["GUID"] = "710052071.0",
            },
        [710052142] = {
            ["Content"] = "比起借助外物，我选择靠自己的双手来获得幸福。",
            ["ContentJP"] = "他に頼るより、{性别:僕|私}は自分の手で幸せをつかみ取る主義だから。",
            ["DialogueId"] = 710052142,
            ["GUID"] = "710052072.0",
            },
        [710053081] = {
            ["Content"] = "（拿走钱财，给内城那些高高在上的家伙一点教训。）",
            ["ContentJP"] = "金目の物を盗んで、内城区のお高く止まってる連中に一泡吹かせる。",
            ["DialogueId"] = 710053081,
            ["GUID"] = "710053121.0",
            },
        [710053082] = {
            ["Content"] = "（归还钱财，即使出身不同，丢失物品的悲伤都是共通的。）",
            ["ContentJP"] = "すべて返す。身分は違えど、物を取られた悲しみは変わらないはずだから。",
            ["DialogueId"] = 710053082,
            ["GUID"] = "710053122.0",
            },
        [710054021] = {
            ["Content"] = "试试看吧。",
            ["ContentJP"] = "試してみる。",
            ["DialogueId"] = 710054021,
            ["GUID"] = "710054031.0",
            },
        [710054022] = {
            ["Content"] = "稍等一下。",
            ["ContentJP"] = "また後で。",
            ["DialogueId"] = 710054022,
            ["GUID"] = "710054032.0",
            },
        [710054041] = {
            ["Content"] = "箱子一碰就坏，你没做手脚的话我把锁芯拆出来给所有人看看如何。",
            ["ContentJP"] = "触れただけで壊れるなんておかしい。なんの小細工もしてないのなら、この場で鍵のシリンダーを見せて。",
            ["DialogueId"] = 710054041,
            ["GUID"] = "710054071.0",
            ["NextDialogue"] = 71005405,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{1}}",
            },
        [710054042] = {
            ["Content"] = "上一个讹我钱的人已经成为病房贵宾了。",
            ["ContentJP"] = "前にも騙して来た人がいたよ。今ではすっかり病室のVIPになってるけどね。",
            ["DialogueId"] = 710054042,
            ["GUID"] = "710054072.0",
            ["NextDialogue"] = 71005407,
            ["Scripts"] = "SetOutport{FinishType{2},OptionIdx{2}}",
            },
