            ["GUID"] = "710055042.0",
            },
        [710055031] = {
            ["Content"] = "（声音可以传播很远。再往前看看吧。）",
            ["ContentJP"] = "声は遠くまで伝わるものだし、もっと奥に行ってみよう。",
            ["DialogueId"] = 710055031,
            ["GUID"] = "710055061.0",
            },
