        [760000201] = {
            ["Content"] = "测试1",
            ["DialogueId"] = 760000201,
            ["NextDialogue"] = 760000202,
            ["SpeakNpcId"] = 77000008,
            },
        [760000202] = {
            ["Content"] = "测试2",
            ["DialogueId"] = 760000202,
            ["NextDialogue"] = 760000203,
            ["SpeakNpcId"] = 100001,
            },
        [760000203] = {
            ["Content"] = "测试3",
            ["DialogueId"] = 760000203,
            ["SpeakNpcId"] = 77000008,
            },
        [800202021] = {
            ["Content"] = "那么，你先去休息？",
            ["ContentJP"] = "じゃあ、先に休んでくる？",
            ["DialogueId"] = 800202021,
            ["GUID"] = "800202021.0",
            ["NextDialogue"] = 80020203,
            },
        [800202022] = {
            ["Content"] = "有这么夸张吗？",
            ["ContentJP"] = "ずいぶん大袈裟だね。",
            ["DialogueId"] = 800202022,
            ["GUID"] = "800202022.0",
            ["NextDialogue"] = 80020204,
            },
        [800202091] = {
            ["Content"] = "你真的只是一名女仆吗？",
            ["ContentJP"] = "ヒルダって本当にただのメイドなのかな？",
            ["DialogueId"] = 800202091,
            ["GUID"] = "800202091.0",
            ["NextDialogue"] = 80020210,
            },
        [800202092] = {
            ["Content"] = "太危险了。",
            ["ContentJP"] = "危険すぎるよ。",
            ["DialogueId"] = 800202092,
            ["GUID"] = "800202092.0",
            ["NextDialogue"] = 80020211,
            },
        [800202161] = {
            ["Content"] = "听起来有些浪漫。",
            ["ContentJP"] = "なんだか格好よく聞こえるね。",
            ["DialogueId"] = 800202161,
            ["GUID"] = "800202161.0",
            ["NextDialogue"] = 80020217,
            },
        [800202162] = {
            ["Content"] = "听起来很辛苦。",
            ["ContentJP"] = "大変そうだね。",
            ["DialogueId"] = 800202162,
            ["GUID"] = "800202162.0",
            ["NextDialogue"] = 80020218,
            },
        [800203021] = {
            ["Content"] = "我可以一起吗？",
            ["ContentJP"] = "一緒に行ってもいい？",
            ["DialogueId"] = 800203021,
            ["GUID"] = "800203021.0",
            ["NextDialogue"] = 80020303,
            },
        [800203022] = {
            ["Content"] = "你也会逛街吗？",
            ["ContentJP"] = "ヒルダでも街をぶらついたりするんだ？",
            ["DialogueId"] = 800203022,
            ["GUID"] = "800203022.0",
            ["NextDialogue"] = 80020304,
            },
        [800203121] = {
            ["Content"] = "真的这么神奇？",
            ["ContentJP"] = "え？本当にそんな効果あるかな？",
            ["DialogueId"] = 800203121,
            ["GUID"] = "800203121.0",
            ["NextDialogue"] = 80020313,
            },
        [800203122] = {
            ["Content"] = "听上去确实会很好看。",
            ["ContentJP"] = "確かに見栄えがよくなりそう。",
            ["DialogueId"] = 800203122,
            ["GUID"] = "800203122.0",
            ["NextDialogue"] = 80020314,
            },
        [800203161] = {
            ["Content"] = "王子？",
            ["ContentJP"] = "王子様？",
            ["DialogueId"] = 800203161,
            ["GUID"] = "800203161.0",
            ["NextDialogue"] = 80020317,
            },
        [800204021] = {
            ["Content"] = "听起来心情不错？",
            ["ContentJP"] = "機嫌が悪そうだけど、花の剪定が嫌いだったり？",
            ["DialogueId"] = 800204021,
            ["GUID"] = "800204021.0",
            ["NextDialogue"] = 80020403,
            },
        [800204022] = {
            ["Content"] = "这才更像是女仆的工作啊。",
            ["ContentJP"] = "メイドらしい仕事だね。",
            ["DialogueId"] = 800204022,
            ["GUID"] = "800204022.0",
            ["NextDialogue"] = 80020404,
            },
        [800204091] = {
            ["Content"] = "那么你是遇到了什么烦心事？",
            ["ContentJP"] = "今は何に悩んでいるのかな？",
            ["DialogueId"] = 800204091,
            ["GUID"] = "800204091.0",
            ["NextDialogue"] = 80020410,
            },
        [800204092] = {
            ["Content"] = "展开讲讲你的前同僚们？",
            ["ContentJP"] = "前の同僚について詳しく聞いていい？",
            ["DialogueId"] = 800204092,
            ["GUID"] = "800204092.0",
