            },
        [801904322] = {
            ["Content"] = "那就说明还没到你必须离开的时候。",
            ["ContentJP"] = "少なくとも、今は離れる必要なんてないってことじゃん。",
            ["DialogueId"] = 801904322,
            ["GUID"] = "801904322.0",
            ["NextDialogue"] = 80190433,
            },
        [801904361] = {
            ["Content"] = "没有，想喝点什么吗？",
            ["ContentJP"] = "いや、そんなことないよ。で、何飲みたい？",
            ["DialogueId"] = 801904361,
            ["GUID"] = "801904361.0",
            ["NextDialogue"] = 80190437,
            },
        [801904362] = {
            ["Content"] = "恶心到我了，你得赔钱。",
            ["ContentJP"] = "うん、気持ち悪かった。慰謝料払って。",
            ["DialogueId"] = 801904362,
            ["GUID"] = "801904362.0",
            ["NextDialogue"] = 80190437,
            },
        [802000021] = {
            ["Content"] = "听起来像是在说植物，能写进书里，一定有某种价值吧。",
            ["ContentJP"] = "植物のことを言ってるみたいだね。本に載せるなら、きっと何かしらの価値があるのかな？",
            ["DialogueId"] = 802000021,
            ["GUID"] = "C8C5B4FE",
            ["NextDialogue"] = 80200004,
            },
        [802000022] = {
            ["Content"] = "这似乎是哪本医书里的内容，好像与药草有关。",
            ["ContentJP"] = "薬草に関する記述のように聞こえるけど、何かの医書の一節？",
            ["DialogueId"] = 802000022,
            ["GUID"] = "C8C5B552",
            ["NextDialogue"] = 80200006,
            },
        [802000023] = {
            ["Content"] = "我打扰到你了吗？看你读书正读得入神。",
            ["ContentJP"] = "読書に没頭してたね。邪魔しちゃったかな？",
            ["DialogueId"] = 802000023,
            ["GUID"] = "C8C5B5A6",
            ["NextDialogue"] = 80200008,
            },
        [802000101] = {
            ["Content"] = "扶疏独自在这里生活，会有什么不便吗？",
            ["ContentJP"] = "この場所でひとり暮らすのって、やっぱり少し大変なんじゃない？",
            ["DialogueId"] = 802000101,
            ["GUID"] = "C8C5B64E",
            ["NextDialogue"] = 80200012,
            },
        [802000102] = {
            ["Content"] = "这点小事不用介意的。",
            ["ContentJP"] = "気にしないで。",
            ["DialogueId"] = 802000102,
            ["GUID"] = "C8C5B6A2",
            ["NextDialogue"] = 80200014,
            },
        [802000103] = {
            ["Content"] = "糟糕，又少要到一顿饭。",
            ["ContentJP"] = "残念、ただ飯はなしかぁ……",
            ["DialogueId"] = 802000103,
            ["GUID"] = "C8C5B6F6",
            ["NextDialogue"] = 80200016,
            },
        [802000271] = {
            ["Content"] = "你愿意少用枯荣术当然是好事，这样的小忙我一定会帮。",
            ["ContentJP"] = "枯栄の術に頼りすぎないようにするのって、大事なことだと思う。できることなら、力になりたいな。",
            ["DialogueId"] = 802000271,
            ["GUID"] = "C8C5B918",
            ["NextDialogue"] = 80200029,
            },
        [802000272] = {
            ["Content"] = "我才不会错过免费的看病机会！来来来，咱们从哪儿看起？",
            ["ContentJP"] = "うん、無料で診てもらえる機会なんて滅多にないしね。さ、どこから見てもらおうかな〜",
            ["DialogueId"] = 802000272,
            ["GUID"] = "C8C5B96C",
            ["NextDialogue"] = 80200031,
            },
        [802000273] = {
            ["Content"] = "我还以为你要我去和烛阴决一死战呢，把大家叫出来就这点事啊？",
            ["ContentJP"] = "もっと大ごとを頼まれるのかと思ったよ。燭陰と一騎打ち、とかさ。",
            ["DialogueId"] = 802000273,
            ["GUID"] = "C8C5B9C0",
            ["NextDialogue"] = 80200033,
            },
        [802000371] = {
