        [802001371] = {
            ["Content"] = "我不是你姐姐，我是你的朋友，我叫{nickname}，我们正一起寻药。",
            ["ContentJP"] = "{性别:僕|私}はフーフォンではなく、あなたの友だちの{nickname}。今、一緒に薬を探してるんだよ。",
            ["DialogueId"] = 802001371,
            ["GUID"] = "C8C5CB24",
            ["NextDialogue"] = 80200139,
            },
        [802001372] = {
            ["Content"] = "我是你姐姐，我已经知道错了。",
            ["ContentJP"] = "うん、姉さんが悪かった。",
            ["DialogueId"] = 802001372,
            ["GUID"] = "C8C5CB78",
            ["NextDialogue"] = 80200141,
            },
        [802001373] = {
            ["Content"] = "对，我不是你姐，我是你妈呀！",
            ["ContentJP"] = "違うよ。母さんだよ！",
            ["DialogueId"] = 802001373,
            ["GUID"] = "C8C5CBCC",
            ["NextDialogue"] = 80200143,
            },
        [802001501] = {
            ["Content"] = "你是为了让我睡个好觉才去尝叶的，怎么能怪你。",
            ["ContentJP"] = "眠れるようにって、{性别:僕|私}のためにあの草を試してくれたんだもん。責めるなんて、とんでもない。",
            ["DialogueId"] = 802001501,
            ["GUID"] = "C8C5CD46",
            ["NextDialogue"] = 80200153,
            },
        [802001502] = {
            ["Content"] = "第一次被比我大那么多的人叫姐姐，还挺刺激的。",
            ["ContentJP"] = "人生で初めて、年上の女性に「姉さん」って言われたかも。ちょっと貴重な体験だったよ。",
            ["DialogueId"] = 802001502,
            ["GUID"] = "C8C5CD70",
            ["NextDialogue"] = 80200153,
            },
        [802002251] = {
            ["Content"] = "扶疏待人诚挚，对病人也用心，我们是朋友。",
            ["ContentJP"] = "フーシュは誠実で、病人にも真剣に向き合ってる。{性别:僕|私}は彼女の友だちだよ。",
            ["DialogueId"] = 802002251,
            ["GUID"] = "C8C5D358",
            ["NextDialogue"] = 80200226,
            },
        [802002252] = {
            ["Content"] = "我是扶疏的病人，上次她收我天价诊金，我是来要钱的。",
            ["ContentJP"] = "いや、{性别:僕|私}は彼女の患者なんだ。前にぼったくられたから、お金返してほしくて{性别:さ|}。",
            ["DialogueId"] = 802002252,
            ["GUID"] = "C8C5D3AC",
            ["NextDialogue"] = 80200227,
            },
        [802002253] = {
