            ["GUID"] = "900300013.0",
            ["NextDialogue"] = 90030301,
            },
        [900300014] = {
            ["Content"] = "贝蕾？为什么你会在这里？",
            ["ContentJP"] = "ベレ？どうしてここにいるの？",
            ["DialogueId"] = 900300014,
            ["GUID"] = "900300014.0",
            ["NextDialogue"] = 90030401,
            },
        [900300015] = {
            ["Content"] = "海伯利亚军团是一个怎样的地方？",
            ["ContentJP"] = "ヒュペリア軍団ってどんなところ？",
            ["DialogueId"] = 900300015,
            ["GUID"] = "900300015.0",
            ["NextDialogue"] = 90030501,
            },
        [900300016] = {
            ["Content"] = "你向来喜欢安静，会觉得这里太吵吗？",
            ["ContentJP"] = "ベレって静かな方が好きだよね？ここって騒々しいけど、大丈夫？",
            ["DialogueId"] = 900300016,
            ["GUID"] = "900300016.0",
            ["NextDialogue"] = 90030601,
            },
        [900300018] = {
            ["Content"] = "贝蕾，我累了。",
            ["ContentJP"] = "{性别:ベレ、僕、疲れちゃった。|ベレ、私、疲れちゃった。}",
            ["DialogueId"] = 900300018,
            ["GUID"] = "900300018.0",
            ["NextDialogue"] = 90030801,
            },
        [900400011] = {
            ["Content"] = "每次下雨时，丽蓓卡总是特别开心？",
            ["ContentJP"] = "雨が降っている日のレベッカって、いつも楽しそうだね？",
            ["DialogueId"] = 900400011,
            ["GUID"] = "900400011.0",
            ["NextDialogue"] = 90040101,
            },
        [900400012] = {
            ["Content"] = "丽蓓卡嘴上总挂着“爱”。你心中的“爱”究竟是……？",
            ["ContentJP"] = "レベッカはいつも「愛」というけど、レベッカにとって「愛」っていったい……？",
            ["DialogueId"] = 900400012,
            ["GUID"] = "900400012.0",
            ["NextDialogue"] = 90040201,
            },
        [900400013] = {
            ["Content"] = "你的想法总是很特别。",
            ["ContentJP"] = "レベッカの考え方はいつも特別だね。",
            ["DialogueId"] = 900400013,
            ["GUID"] = "900400013.0",
            ["NextDialogue"] = 90040301,
            },
        [900400014] = {
            ["Content"] = "你身体里的毒素，不要紧吗？",
            ["ContentJP"] = "身体に毒があっても、大丈夫なの？",
            ["DialogueId"] = 900400014,
            ["GUID"] = "900400014.0",
            ["NextDialogue"] = 90040401,
            },
        [900400015] = {
            ["Content"] = "在你身边总是能闻到香味。",
            ["ContentJP"] = "レベッカのそばにいると、いい香りがするね。",
            ["DialogueId"] = 900400015,
            ["GUID"] = "900400015.0",
            ["NextDialogue"] = 90040501,
            },
        [900500011] = {
            ["Content"] = "今天怎么这么安静，简直像是换了个人。",
            ["ContentJP"] = "{性别:今日は静かだね、別人みたいだ。|今日は静かだね、別人みたい。}",
            ["DialogueId"] = 900500011,
            ["GUID"] = "900500011.0",
            ["NextDialogue"] = 90050101,
            },
        [900500012] = {
            ["Content"] = "小偷一般都会很警觉，你是怎么从他们眼皮子底下拿他们东西的？",
            ["ContentJP"] = "{性别:泥棒ってみんな用心深いよね？そんな人たちからよくモノを盗めるね。|泥棒ってみんな用心深いでしょ？そんな人たちからよくモノを盗めるね。}",
            ["DialogueId"] = 900500012,
            ["GUID"] = "900500012.0",
            ["NextDialogue"] = 90050201,
            },
        [900500013] = {
            ["Content"] = "喜欢偷东西的没有好人！",
            ["ContentJP"] = "手癖の悪い人が善人なわけないよ！",
            ["DialogueId"] = 900500013,
            ["GUID"] = "900500013.0",
            ["NextDialogue"] = 90050301,
            },
        [900500014] = {
            ["Content"] = "大部分卡戎之民应该都不喜欢“恶魔”这个称呼？",
