            },
        [900900014] = {
            ["Content"] = "帝国敌视卡戎，想必他们也看不惯你吧。",
            ["ContentJP"] = "帝国はカロンを敵視しているんだし、内部の人たちはシビルをよく思ってないんじゃないかな？",
            ["DialogueId"] = 900900014,
            ["GUID"] = "900900014.0",
            ["NextDialogue"] = 90090401,
            },
        [901000011] = {
            ["Content"] = "你的衣服真好看，只是，不用担心着凉吗？",
            ["ContentJP"] = "本当にきれいな服だね。ただ風邪とか引きそうだけど。",
            ["DialogueId"] = 901000011,
            ["GUID"] = "901000011.0",
            ["NextDialogue"] = 90100101,
            },
        [901000012] = {
            ["Content"] = "我记得你说过，卡戎之民在海伯利亚不太受欢迎。",
            ["ContentJP"] = "カロン族はヒュペリアではあまり歓迎されていないって言ってたよね？",
            ["DialogueId"] = 901000012,
            ["GUID"] = "901000012.0",
            ["NextDialogue"] = 90100201,
            },
        [901000013] = {
            ["Content"] = "最近总是能闻到花香。",
            ["ContentJP"] = "{性别:最近いつも花の香りがするな。|最近いつも花の香りがするね。}",
            ["DialogueId"] = 901000013,
            ["GUID"] = "901000013.0",
            ["NextDialogue"] = 90100301,
            },
        [901000014] = {
            ["Content"] = "赛琪是不是没离开过冰湖城？",
            ["ContentJP"] = "サイキはアイスレイク城から離れたことがないんだよね？",
            ["DialogueId"] = 901000014,
            ["GUID"] = "901000014.0",
            ["NextDialogue"] = 90100401,
            },
        [901000015] = {
            ["Content"] = "你好像一直有什么话想说。",
            ["ContentJP"] = "ずっと何か言いたそうにみえるけど。",
            ["DialogueId"] = 901000015,
            ["GUID"] = "901000015.0",
            ["NextDialogue"] = 90100501,
            },
        [901100011] = {
            ["Content"] = "你在看医书吗？",
            ["ContentJP"] = "医学書を読んでいるの？",
            ["DialogueId"] = 901100011,
            ["GUID"] = "901100011.0",
            ["NextDialogue"] = 90110101,
            },
        [901100012] = {
            ["Content"] = "扶疏的梦想是什么？",
            ["ContentJP"] = "フーシュの夢って何？",
            ["DialogueId"] = 901100012,
            ["GUID"] = "901100012.0",
            ["NextDialogue"] = 90110201,
            },
        [901100013] = {
            ["Content"] = "枯荣阁是个怎样的地方？",
            ["ContentJP"] = "枯栄閣ってどんなところ？",
            ["DialogueId"] = 901100013,
            ["GUID"] = "901100013.0",
            ["NextDialogue"] = 90110301,
            },
        [901100014] = {
            ["Content"] = "身为医者，对死亡这种事一定深有感触吧。",
            ["ContentJP"] = "医者って、やっぱり死に対する感覚も違うの？",
            ["DialogueId"] = 901100014,
            ["GUID"] = "901100014.0",
            ["NextDialogue"] = 90110401,
            },
        [901200011] = {
            ["Content"] = "听说你是粮秣专员？是干什么的？",
            ["ContentJP"] = "トリュフは食糧補給官だって聞いたけど……どんな仕事？",
            ["DialogueId"] = 901200011,
            ["GUID"] = "901200011.0",
            ["NextDialogue"] = 90120101,
            },
        [901200012] = {
            ["Content"] = "说起来我有点好奇，如果被榛子撞一下会不会很痛？",
            ["ContentJP"] = "気になったんだけど、ヘーゼルナッツのタックルって痛いよね？",
            ["DialogueId"] = 901200012,
            ["GUID"] = "901200012.0",
            ["NextDialogue"] = 90120201,
            },
        [901200013] = {
            ["Content"] = "榛子这么大一只，每天一定会吃不少吧。",
            ["ContentJP"] = "ヘーゼルナッツって大きいし、食べる量も多そうだね。",
            ["DialogueId"] = 901200013,
            ["GUID"] = "901200013.0",
            ["NextDialogue"] = 90120301,
            },
        [901200014] = {
            ["Content"] = "早就想说了：你的裙子真可爱。",
            ["ContentJP"] = "ずっと言おうと思っていたんだけど、そのスカート、本当に可愛いね。",
            ["DialogueId"] = 901200014,
            ["GUID"] = "901200014.0",
            ["NextDialogue"] = 90120401,
            },
        [901200015] = {
            ["Content"] = "你今天好像在这里发呆挺久了。",
            ["ContentJP"] = "今日はずっとここでぼんやりしているね。",
            ["DialogueId"] = 901200015,
            ["GUID"] = "901200015.0",
            ["NextDialogue"] = 90120501,
            },
        [901300011] = {
            ["Content"] = "能给我提供些西比尔的情报吗？",
            ["ContentJP"] = "シビルの情報を教えてくれないかな？",
            ["DialogueId"] = 901300011,
            ["GUID"] = "901300011.0",
            ["NextDialogue"] = 90130101,
            },
        [901300012] = {
            ["Content"] = "听说你进军团前也接过不少委托，作为前辈，讲讲经验？",
            ["ContentJP"] = "帝国軍に入る前はいろいろな依頼をこなしていたって聞いたけど、先輩として役立ちそうな経験とか教えてくれない？",
            ["DialogueId"] = 901300012,
            ["GUID"] = "901300012.0",
            ["NextDialogue"] = 90130201,
            },
        [901300013] = {
            ["Content"] = "嘴里念念有词的，在想什么呢？",
            ["ContentJP"] = "独り言をブツブツと、何か考えごと？",
            ["DialogueId"] = 901300013,
            ["GUID"] = "901300013.0",
            ["NextDialogue"] = 90130301,
            },
        [901300014] = {
            ["Content"] = "你为什么这么努力工作？",
            ["ContentJP"] = "{性别:どうしてそんなに一生懸命働いているんだ？|どうしてそんなに一生懸命働いているの？}",
            ["DialogueId"] = 901300014,
            ["GUID"] = "901300014.0",
            ["NextDialogue"] = 90130401,
            },
        [901500011] = {
            ["Content"] = "在想什么？",
            ["ContentJP"] = "何を考えているの？",
            ["DialogueId"] = 901500011,
            ["GUID"] = "901500011.0",
            ["NextDialogue"] = 90150101,
            },
        [901500012] = {
            ["Content"] = "菲娜有什么可以讲给我听的小秘密吗？",
            ["ContentJP"] = "{性别:フィーナ、僕に聞かせられる秘密ってある？|フィーナ、私に聞かせられる秘密ってある？}",
            ["DialogueId"] = 901500012,
            ["GUID"] = "901500012.0",
            ["NextDialogue"] = 90150201,
            },
        [901500013] = {
            ["Content"] = "昨天睡得好吗？",
            ["ContentJP"] = "昨日はよく眠れた？",
            ["DialogueId"] = 901500013,
            ["GUID"] = "901500013.0",
            ["NextDialogue"] = 90150301,
            },
        [901500014] = {
            ["Content"] = "菲娜还有哥哥之外的家人吗？",
            ["ContentJP"] = "フィーナってアウトサイダー以外の家族はいるの？",
            ["DialogueId"] = 901500014,
            ["GUID"] = "901500014.0",
            ["NextDialogue"] = 90150401,
            },
        [901500015] = {
            ["Content"] = "奥特赛德是个怎样的人？",
            ["ContentJP"] = "アウトサイダーってどんな人？",
            ["DialogueId"] = 901500015,
            ["GUID"] = "901500015.0",
            ["NextDialogue"] = 90150501,
            },
        [901600011] = {
            ["Content"] = "有没有什么资深狩月人速成手册之类的东西，传授一下？",
            ["ContentJP"] = "月狩り人のマニュアルみたいなのってないの？",
            ["DialogueId"] = 901600011,
            ["GUID"] = "901600011.0",
            ["NextDialogue"] = 90160101,
            },
        [901600012] = {
            ["Content"] = "帝国严加防范的“神弃者同盟”是什么来头？",
            ["ContentJP"] = "帝国が厳重に警戒している「フォーセイクン同盟」って？",
            ["DialogueId"] = 901600012,
            ["GUID"] = "901600012.0",
            ["NextDialogue"] = 90160201,
            },
        [901600013] = {
            ["Content"] = "你受伤了？",
            ["ContentJP"] = "{性别:怪我したのか？|怪我したの？}",
            ["DialogueId"] = 901600013,
            ["GUID"] = "901600013.0",
            ["NextDialogue"] = 90160301,
            },
        [901600014] = {
            ["Content"] = "你手里拿的是什么东西？！",
            ["ContentJP"] = "{性别:なんてもの持っているんだよ！？|なんてもの持っているの！？}",
            ["DialogueId"] = 901600014,
            ["GUID"] = "901600014.0",
            ["NextDialogue"] = 90160401,
            },
        [901600015] = {
            ["Content"] = "这次的委托顺利完成了。",
            ["ContentJP"] = "今回の依頼は上手くいったね。",
            ["DialogueId"] = 901600015,
            ["GUID"] = "901600015.0",
            ["NextDialogue"] = 90160501,
            },
        [901700011] = {
            ["Content"] = "“拾荒者”是一份怎样的工作？",
            ["ContentJP"] = "「ゴミ拾い」ってどんな仕事なの？",
            ["DialogueId"] = 901700011,
            ["GUID"] = "901700011.0",
            ["NextDialogue"] = 90170101,
            },
        [901700012] = {
            ["Content"] = "《冰湖城垃圾桶一站式地图指南》……？",
            ["ContentJP"] = "『アイスレイク城のゴミ箱全攻略ガイド』……？",
            ["DialogueId"] = 901700012,
            ["GUID"] = "901700012.0",
            ["NextDialogue"] = 90170201,
            },
        [901700013] = {
            ["Content"] = "偶尔会看见你对着远方的冰原出神，你想离开这里吗？",
            ["ContentJP"] = "時々遠くの雪原を眺めているね。この街から離れたい？",
            ["DialogueId"] = 901700013,
            ["GUID"] = "901700013.0",
            ["NextDialogue"] = 90170301,
            },
        [901700014] = {
            ["Content"] = "你的挂件是什么动物？",
            ["ContentJP"] = "マギーのつけているそれって、なんの動物のストラップ？",
            ["DialogueId"] = 901700014,
            ["GUID"] = "901700014.0",
            ["NextDialogue"] = 90170401,
            },
        [901700015] = {
            ["Content"] = "贫民窟的大家都称你为“垃圾桶公主”呢。",
            ["ContentJP"] = "スラム街のみんなはマギーを「ゴミ拾いの姫様」と呼んでいるんだね。",
            ["DialogueId"] = 901700015,
            ["GUID"] = "901700015.0",
            ["NextDialogue"] = 90170501,
            },
        [901800011] = {
            ["Content"] = "你有一个会说话的炸弹？",
            ["ContentJP"] = "イェールはしゃべる爆弾を持っているの？",
            ["DialogueId"] = 901800011,
            ["GUID"] = "901800011.0",
            ["NextDialogue"] = 90180101,
            },
        [901800012] = {
            ["Content"] = "你对狩月人委托感兴趣吗？要不要一起？",
            ["ContentJP"] = "月狩り人の依頼に興味はないかな？一緒にどう？",
            ["DialogueId"] = 901800012,
            ["GUID"] = "901800012.0",
            ["NextDialogue"] = 90180201,
            },
        [901800013] = {
            ["Content"] = "你说话总是慢吞吞的。",
            ["ContentJP"] = "イェールの話し方って、いつもゆっくりだね。",
            ["DialogueId"] = 901800013,
            ["GUID"] = "901800013.0",
            ["NextDialogue"] = 90180301,
            },
        [901800014] = {
            ["Content"] = "你和奥利弗也是小时候就认识的同伴吗？",
            ["ContentJP"] = "オリバーとは子供の頃から一緒なのかな？",
            ["DialogueId"] = 901800014,
            ["GUID"] = "901800014.0",
            ["NextDialogue"] = 90180401,
            },
        [901900011] = {
            ["Content"] = "不在战场的时候，达芙涅喜欢做些什么呢？",
            ["ContentJP"] = "普段は何をして過ごしてるの？",
            ["DialogueId"] = 901900011,
            ["GUID"] = "901900011.0",
            ["NextDialogue"] = 90190101,
            },
        [901900012] = {
            ["Content"] = "可以和我说说炼金术的事吗？",
            ["ContentJP"] = "錬金術について教えてくれない？",
            ["DialogueId"] = 901900012,
            ["GUID"] = "901900012.0",
            ["NextDialogue"] = 90190201,
            },
        [901900013] = {
            ["Content"] = "你一直带着背包，里面装了什么？",
            ["ContentJP"] = "いつもリュックを背負ってるけど、何が入ってるの？",
            ["DialogueId"] = 901900013,
            ["GUID"] = "901900013.0",
            ["NextDialogue"] = 90190301,
            },
        [901900014] = {
            ["Content"] = "医务员平时的训练是不是很辛苦？",
            ["ContentJP"] = "医務官って、普段の訓練も大変そうだね。",
            ["DialogueId"] = 901900014,
            ["GUID"] = "901900014.0",
            ["NextDialogue"] = 90190401,
            },
        [901900015] = {
            ["Content"] = "有时候会看到你对着对讲机发呆。",
            ["ContentJP"] = "時々、トランシーバーを見つめてボーっとしてるよね？",
            ["DialogueId"] = 901900015,
            ["GUID"] = "901900015.0",
            ["NextDialogue"] = 90190501,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 110109,
                    },
                },
            },
        [902000011] = {
            ["Content"] = "和我说说布鲁斯的事吧。",
            ["ContentJP"] = "ブルースについて教えて。",
            ["DialogueId"] = 902000011,
            ["GUID"] = "902000011.0",
            ["NextDialogue"] = 90200101,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902000012] = {
            ["Content"] = "我希望有一天能看到你重拾本名。",
            ["ContentJP"] = "いつか本名を取り戻せるといいね。",
            ["DialogueId"] = 902000012,
            ["GUID"] = "902000012.0",
            ["NextDialogue"] = 90200201,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902000013] = {
            ["Content"] = "你还有什么心愿？如果我能帮上忙。",
            ["ContentJP"] = "何か願い事はある？できることなら手伝うよ。",
            ["DialogueId"] = 902000013,
            ["GUID"] = "902000013.0",
            ["NextDialogue"] = 90200301,
            },
        [902000014] = {
            ["Content"] = "可以教我表演吗？",
            ["ContentJP"] = "演技を教えてくれない？",
            ["DialogueId"] = 902000014,
            ["GUID"] = "902000014.0",
            ["NextDialogue"] = 90200401,
            },
        [902000015] = {
            ["Content"] = "和我聊聊盖雷亚剧院吧。",
            ["ContentJP"] = "ガレア劇場について教えて。",
            ["DialogueId"] = 902000015,
            ["GUID"] = "902000015.0",
            ["NextDialogue"] = 90200501,
            },
        [902100011] = {
            ["Content"] = "你好像很喜欢吹口琴？",
            ["ContentJP"] = "ハーモニカが好きなの？",
            ["DialogueId"] = 902100011,
            ["GUID"] = "902100011.0",
            ["NextDialogue"] = 90210101,
            ["TriggerCondition"] = {
                ["QuestChainUnFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902100012] = {
            ["Content"] = "你在军团还好吗？",
            ["ContentJP"] = "帝国軍ではうまくやってる？",
            ["DialogueId"] = 902100012,
            ["GUID"] = "902100012.0",
            ["NextDialogue"] = 90210201,
            ["TriggerCondition"] = {
                ["QuestChainUnFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902100013] = {
            ["Content"] = "感觉你执行任务时要比其他同僚更加负责。",
            ["ContentJP"] = "任務の時、人一倍責任感が強いように見えるけど。",
            ["DialogueId"] = 902100013,
            ["GUID"] = "902100013.0",
            ["NextDialogue"] = 90210301,
            ["TriggerCondition"] = {
                ["QuestChainUnFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902100014] = {
            ["Content"] = "我把据点里的镜子擦干净了，你要来照一照吗？",
            ["ContentJP"] = "ここの鏡をキレイにしたから、映ってみる？",
            ["DialogueId"] = 902100014,
            ["GUID"] = "902100014.0",
            ["NextDialogue"] = 90210401,
            },
        [902100015] = {
            ["Content"] = "你的那把口琴还在吗？",
            ["ContentJP"] = "あのハーモニカはまだ手元に？",
            ["DialogueId"] = 902100015,
            ["GUID"] = "902100015.0",
            ["NextDialogue"] = 90210501,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902100016] = {
            ["Content"] = "你现在靠什么维持生活啊，钱还够用吗？",
            ["ContentJP"] = "今はどう生計を立ててるの？貯金は足りてる？",
            ["DialogueId"] = 902100016,
            ["GUID"] = "902100016.0",
            ["NextDialogue"] = 90210601,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902100017] = {
            ["Content"] = "离开军团后，你还好吗？",
            ["ContentJP"] = "帝国軍を離れてから、調子はどう？",
            ["DialogueId"] = 902100017,
            ["GUID"] = "902100017.0",
            ["NextDialogue"] = 90210701,
            ["TriggerCondition"] = {
                ["QuestChainFinish"] = {
                    ["QuestChainId"] = 100306,
                    },
                },
            },
        [902200011] = {
            ["Content"] = "看装扮，你似乎并不是海伯利亚人。",
            ["ContentJP"] = "その着こなし、ヒュペリアの人じゃないよね？",
            ["DialogueId"] = 902200011,
            ["GUID"] = "902200011.0",
            ["NextDialogue"] = 90220101,
            },
        [902200012] = {
            ["Content"] = "和我说说雾海吧。",
            ["ContentJP"] = "ニヴルヘイムについて教えて。",
            ["DialogueId"] = 902200012,
            ["GUID"] = "902200012.0",
            ["NextDialogue"] = 90220201,
            },
        [902200013] = {
            ["Content"] = "你好像很擅长战斗？",
            ["ContentJP"] = "戦闘が得意そうだね？",
            ["DialogueId"] = 902200013,
            ["GUID"] = "902200013.0",
            ["NextDialogue"] = 90220301,
            },
        [902200014] = {
            ["Content"] = "讲讲你的朋友吧。",
            ["ContentJP"] = "あなたの友人について教えて。",
            ["DialogueId"] = 902200014,
            ["GUID"] = "902200014.0",
            ["NextDialogue"] = 90220401,
            },
        [902300011] = {
            ["Content"] = "对于商人，一切都可以用来交易吗？",
            ["ContentJP"] = "商人はなんでも取引の商品にできるの？",
            ["DialogueId"] = 902300011,
            ["GUID"] = "902300011.0",
            ["NextDialogue"] = 90230101,
            },
        [902300012] = {
            ["Content"] = "做生意有什么诀窍吗？",
            ["ContentJP"] = "商売に何かコツは？",
            ["DialogueId"] = 902300012,
            ["GUID"] = "902300012.0",
            ["NextDialogue"] = 90230201,
            },
        [902300013] = {
            ["Content"] = "闲暇时间你会做什么？",
            ["ContentJP"] = "暇な時って何してる？",
            ["DialogueId"] = 902300013,
            ["GUID"] = "902300013.0",
            ["NextDialogue"] = 90230301,
            },
        [902300014] = {
            ["Content"] = "我发现你好像有点怕黑。",
            ["ContentJP"] = "もしかして暗いところが少し苦手なの？",
            ["DialogueId"] = 902300014,
            ["GUID"] = "902300014.0",
            ["NextDialogue"] = 90230401,
            },
        [902400011] = {
            ["Content"] = "听说你的剑法很好？",
            ["ContentJP"] = "お前、剣の腕がすごいんだって？",
            ["DialogueId"] = 902400011,
            ["GUID"] = "902400011.0",
            ["NextDialogue"] = 90240101,
            },
        [902400012] = {
            ["Content"] = "你为什么要反对华胥的律法呢？",
            ["ContentJP"] = "なぜ華胥の法令に反対なの？",
            ["DialogueId"] = 902400012,
            ["GUID"] = "902400012.0",
            ["NextDialogue"] = 90240201,
            },
        [902400013] = {
            ["Content"] = "除了剑你好像还会用很多其他武器，这也能叫剑客吗？",
            ["ContentJP"] = "剣以外にも色々使ってるみたいだけど、剣士なのにいいの？",
            ["DialogueId"] = 902400013,
            ["GUID"] = "902400013.0",
            ["NextDialogue"] = 90240301,
            },
